public void onLivingDeath(LivingDeathEvent event) {
	if (event.getEntity() instanceof Player && !event.getEntity().level().isClientSide) {
		Player player = (Player) event.getEntity();

		if (SuperpositionHandler.isTheBlessedOne(player)) {
			ItemStack scroll = SuperpositionHandler.getCurioStack(player, this);

			if (scroll != null && !this.hasCooldown(scroll)) {
				event.setCanceled(true);
				player.setHealth(player.getMaxHealth() / 2);

				player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1200, 2));
				player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1200, 1));
				player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 1200, 0));
				player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1200, 1));

				this.setCooldown(scroll, deathProtectionCooldown.getValue() * 20);

				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() ->
				new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128,
						player.level().dimension())), new PacketCosmicRevive(player.getId(), 0));
			}
		}
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof ServerPlayer player && player.tickCount % 5 == 0
			&& SuperpositionHandler.isTheWorthyOne(player)) {
		List<LivingEntity> entities = SuperpositionHandler.getObservedEntities(player, player.level(), 3, 128, false);
		for (LivingEntity entity : entities) {
			if (entity instanceof ServerPlayer otherPlayer && SuperpositionHandler.hasCurio(otherPlayer, this)
					&& SuperpositionHandler.isTheWorthyOne(otherPlayer)) {
				continue;
			}

			entity.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 10, 1));
			entity.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN, 10, 1));
			entity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 10, 1));
		}
	}
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);

	if (hand == InteractionHand.MAIN_HAND) {
		ItemStack offhandStack = player.getOffhandItem();

		if (offhandStack.getItem().getUseAnimation(offhandStack) == UseAnim.BLOCK)
			return InteractionResultHolder.pass(stack);
	}

	if (SuperpositionHandler.isTheCursedOne(player)) {
		player.startUsingItem(hand);
		return InteractionResultHolder.consume(stack);
	} else
		return InteractionResultHolder.pass(stack);
}

