            if (stack.getTag().getInt("HurtingTicks") > 120) {
                stack.hurtAndBreak(1, (LivingEntity) entity, (p_220017_1_) -> {
                });
                stack.getTag().putInt("HurtingTicks", 0);
            }
        }

    }
