public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
	ItemStack heldStack = player.getItemInHand(hand);
	if (ShootableGadgetItemMethods.shouldSwap(player, heldStack, hand, s -> s.getItem() instanceof PotatoCannonItem)) {
		return InteractionResultHolder.fail(heldStack);
	}

	Ammo ammo = getAmmo(player, heldStack);
	if (ammo == null) {
		return InteractionResultHolder.pass(heldStack);
	}
	ItemStack ammoStack = ammo.stack();
	PotatoCannonProjectileType projectileType = ammo.type();

	if (level.isClientSide) {
		CreateClient.POTATO_CANNON_RENDER_HANDLER.dontAnimateItem(hand);
		return InteractionResultHolder.success(heldStack);
	}

	Vec3 barrelPos = ShootableGadgetItemMethods.getGunBarrelVec(player, hand == InteractionHand.MAIN_HAND,
		new Vec3(.75f, -0.15f, 1.5f));
	Vec3 correction =
		ShootableGadgetItemMethods.getGunBarrelVec(player, hand == InteractionHand.MAIN_HAND, new Vec3(-.05f, 0, 0))
			.subtract(player.position()
				.add(0, player.getEyeHeight(), 0));

	Vec3 lookVec = player.getLookAngle();
	Vec3 motion = lookVec.add(correction)
		.normalize()
		.scale(2)
		.scale(projectileType.velocityMultiplier());

	float soundPitch = projectileType.soundPitch() + (level.getRandom().nextFloat() - .5f) / 4f;

	boolean spray = projectileType.split() > 1;
	Vec3 sprayBase = VecHelper.rotate(new Vec3(0, 0.1, 0), 360 * level.getRandom().nextFloat(), Axis.Z);
	float sprayChange = 360f / projectileType.split();

	ItemStack ammoStackCopy = ammoStack.copy();

	for (int i = 0; i < projectileType.split(); i++) {
		PotatoProjectileEntity projectile = AllEntityTypes.POTATO_PROJECTILE.create(level);
		projectile.setItem(ammoStackCopy);
		projectile.setEnchantmentEffectsFromCannon(heldStack);

		Vec3 splitMotion = motion;
		if (spray) {
			float imperfection = 40 * (level.getRandom().nextFloat() - 0.5f);
			Vec3 sprayOffset = VecHelper.rotate(sprayBase, i * sprayChange + imperfection, Axis.Z);
			splitMotion = splitMotion.add(VecHelper.lookAt(sprayOffset, motion));
		}

		if (i != 0)
			projectile.recoveryChance = 0;

		projectile.setPos(barrelPos.x, barrelPos.y, barrelPos.z);
		projectile.setDeltaMovement(splitMotion);
		projectile.setOwner(player);
		level.addFreshEntity(projectile);
	}

	if (!player.isCreative()) {
		ammoStack.shrink(1);
		if (ammoStack.isEmpty())
			player.getInventory().removeItem(ammoStack);
	}

	if (!BacktankUtil.canAbsorbDamage(player, maxUses()))
		heldStack.hurtAndBreak(1, player, LivingEntity.getSlotForHand(hand));

	ShootableGadgetItemMethods.applyCooldown(player, heldStack, hand, s -> s.getItem() instanceof PotatoCannonItem, projectileType.reloadTicks());
	ShootableGadgetItemMethods.sendPackets(player,
		b -> new PotatoCannonPacket(barrelPos, lookVec.normalize(), ammoStack, hand, soundPitch, b));
	return InteractionResultHolder.success(heldStack);
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
	ItemStack itemstack = playerIn.getItemInHand(handIn);
	InteractionResultHolder<ItemStack> FAIL = new InteractionResultHolder<>(InteractionResult.FAIL, itemstack);

	if (itemstack.has(AllDataComponents.SAND_PAPER_POLISHING)) {
		playerIn.startUsingItem(handIn);
		return new InteractionResultHolder<>(InteractionResult.PASS, itemstack);
	}

	InteractionHand otherHand =
		handIn == InteractionHand.MAIN_HAND ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND;
	ItemStack itemInOtherHand = playerIn.getItemInHand(otherHand);
	if (SandPaperPolishingRecipe.canPolish(worldIn, itemInOtherHand)) {
		ItemStack item = itemInOtherHand.copy();
		ItemStack toPolish = item.split(1);
		playerIn.startUsingItem(handIn);
		itemstack.set(AllDataComponents.SAND_PAPER_POLISHING, new SandPaperItemComponent(toPolish));
		playerIn.setItemInHand(otherHand, item);
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, itemstack);
	}

	BlockHitResult raytraceresult = getPlayerPOVHitResult(worldIn, playerIn, ClipContext.Fluid.NONE);
	Vec3 hitVec = raytraceresult.getLocation();

	AABB bb = new AABB(hitVec, hitVec).inflate(1f);
	ItemEntity pickUp = null;
	for (ItemEntity itemEntity : worldIn.getEntitiesOfClass(ItemEntity.class, bb)) {
		if (!itemEntity.isAlive())
			continue;
		if (itemEntity.position()
			.distanceTo(playerIn.position()) > 3)
			continue;
		ItemStack stack = itemEntity.getItem();
		if (!SandPaperPolishingRecipe.canPolish(worldIn, stack))
			continue;
		pickUp = itemEntity;
		break;
	}

	if (pickUp == null)
		return FAIL;

	ItemStack item = pickUp.getItem()
		.copy();
	ItemStack toPolish = item.split(1);

	playerIn.startUsingItem(handIn);

	if (!worldIn.isClientSide) {
		itemstack.set(AllDataComponents.SAND_PAPER_POLISHING, new SandPaperItemComponent(toPolish));
		if (item.isEmpty())
			pickUp.discard();
		else
			pickUp.setItem(item);
	}

	return new InteractionResultHolder<>(InteractionResult.SUCCESS, itemstack);
}

public InteractionResult useOn(UseOnContext context) {
	Player player = context.getPlayer();
	BlockPos pos = context.getClickedPos();
	if (player == null)
		return InteractionResult.PASS;
	player.getCooldowns()
		.addCooldown(this, 5);
	ItemStack wand = player.getItemInHand(context.getHand());
	checkComponents(wand);

	// Shift -> open GUI
	if (player.isShiftKeyDown()) {
		if (player.level().isClientSide) {
			CatnipServices.PLATFORM.executeOnClientOnly(() -> () -> {
				openWandGUI(wand, context.getHand());
			});
			player.getCooldowns()
				.addCooldown(this, 5);
		}
		return InteractionResult.SUCCESS;
	}

	if (context.getLevel().isClientSide || context.getHand() != InteractionHand.MAIN_HAND)
		return InteractionResult.SUCCESS;

	pos = pos.relative(context.getClickedFace());
	SymmetryMirror previousElement = wand.get(AllDataComponents.SYMMETRY_WAND);

	// No Shift -> Make / Move Mirror
	wand.set(AllDataComponents.SYMMETRY_WAND_ENABLE, true);
	Vec3 pos3d = new Vec3(pos.getX(), pos.getY(), pos.getZ());
	SymmetryMirror newElement = new PlaneMirror(pos3d);

	if (previousElement instanceof EmptyMirror) {
		newElement.setOrientation(
			(player.getDirection() == Direction.NORTH || player.getDirection() == Direction.SOUTH)
				? PlaneMirror.Align.XY.ordinal()
				: PlaneMirror.Align.YZ.ordinal());
		newElement.enable = true;
		wand.set(AllDataComponents.SYMMETRY_WAND_ENABLE, true);
	} else {
		previousElement.setPosition(pos3d);

		if (previousElement instanceof PlaneMirror) {
			previousElement.setOrientation(
				(player.getDirection() == Direction.NORTH || player.getDirection() == Direction.SOUTH)
					? PlaneMirror.Align.XY.ordinal()
					: PlaneMirror.Align.YZ.ordinal());
		}

		if (previousElement instanceof CrossPlaneMirror) {
			float rotation = player.getYHeadRot();
			float abs = Math.abs(rotation % 90);
			boolean diagonal = abs > 22 && abs < 45 + 22;
			previousElement
				.setOrientation(diagonal ? CrossPlaneMirror.Align.D.ordinal() : CrossPlaneMirror.Align.Y.ordinal());
		}

		newElement = previousElement;
	}

	wand.set(AllDataComponents.SYMMETRY_WAND, newElement);

	player.setItemInHand(context.getHand(), wand);
	return InteractionResult.SUCCESS;
}

