public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
	ItemStack item = player.getItemInHand(hand);
	boolean mainHand = hand == InteractionHand.MAIN_HAND;

	// Shift -> Open GUI
	if (player.isShiftKeyDown()) {
		if (world.isClientSide) {
			CatnipServices.PLATFORM.executeOnClientOnly(() -> () -> {
				openHandgunGUI(item, hand);
			});
			player.getCooldowns()
				.addCooldown(item.getItem(), 10);
		}
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, item);
	}

	if (ShootableGadgetItemMethods.shouldSwap(player, item, hand, this::isZapper))
		return new InteractionResultHolder<>(InteractionResult.FAIL, item);

	// Check if can be used
	Component msg = validateUsage(item);
	if (msg != null) {
		AllSoundEvents.DENY.play(world, player, player.blockPosition());
		player.displayClientMessage(msg.plainCopy()
			.withStyle(ChatFormatting.RED), true);
		return new InteractionResultHolder<>(InteractionResult.FAIL, item);
	}

	BlockState stateToUse = Blocks.AIR.defaultBlockState();
	if (item.has(AllDataComponents.SHAPER_BLOCK_USED))
		stateToUse = item.get(AllDataComponents.SHAPER_BLOCK_USED);
	stateToUse = BlockHelper.setZeroAge(stateToUse);
	CompoundTag data = null;
	if (AllBlockTags.SAFE_NBT.matches(stateToUse) && item.has(AllDataComponents.SHAPER_BLOCK_DATA)) {
		data = item.get(AllDataComponents.SHAPER_BLOCK_DATA);
	}

	// Raytrace - Find the target
	Vec3 start = player.position()
		.add(0, player.getEyeHeight(), 0);
	Vec3 range = player.getLookAngle()
		.scale(getZappingRange(item));
	BlockHitResult raytrace =
		world.clip(new ClipContext(start, start.add(range), Block.OUTLINE, Fluid.NONE, player));
	BlockPos pos = raytrace.getBlockPos();
	BlockState stateReplaced = world.getBlockState(pos);

	// No target
	if (pos == null || stateReplaced.getBlock() == Blocks.AIR) {
		ShootableGadgetItemMethods.applyCooldown(player, item, hand, this::isZapper, getCooldownDelay(item));
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, item);
	}

	// Find exact position of gun barrel for VFX
	Vec3 barrelPos = ShootableGadgetItemMethods.getGunBarrelVec(player, mainHand, new Vec3(.35f, -0.1f, 1));

	// Client side
	if (world.isClientSide) {
		CreateClient.ZAPPER_RENDER_HANDLER.dontAnimateItem(hand);
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, item);
	}

	// Server side
	if (activate(world, player, item, stateToUse, raytrace, data)) {
		ShootableGadgetItemMethods.applyCooldown(player, item, hand, this::isZapper, getCooldownDelay(item));
		ShootableGadgetItemMethods.sendPackets(player,
			b -> new ZapperBeamPacket(barrelPos, hand, b, raytrace.getLocation()));
	}

	return new InteractionResultHolder<>(InteractionResult.SUCCESS, item);
}

public InteractionResult useOn(UseOnContext context) {
	Player playerEntity = context.getPlayer();
	ItemStack heldStack = context.getItemInHand();

	if (playerEntity != null && playerEntity.isShiftKeyDown()) {
		heldStack.remove(AllDataComponents.BELT_FIRST_SHAFT);
		return InteractionResult.SUCCESS;
	}

	Level world = context.getLevel();
	BlockPos pos = context.getClickedPos();
	boolean validAxis = validateAxis(world, pos);

	if (world.isClientSide)
		return validAxis ? InteractionResult.SUCCESS : InteractionResult.FAIL;

	BlockPos firstPulley = null;

	// Remove first if no longer existant or valid
	if (heldStack.has(AllDataComponents.BELT_FIRST_SHAFT)) {
		firstPulley = heldStack.get(AllDataComponents.BELT_FIRST_SHAFT);
		if (!validateAxis(world, firstPulley) || !firstPulley.closerThan(pos, maxLength() * 2)) {
			heldStack.remove(AllDataComponents.BELT_FIRST_SHAFT);
		}
	}

	if (!validAxis || playerEntity == null)
		return InteractionResult.FAIL;

	if (heldStack.has(AllDataComponents.BELT_FIRST_SHAFT)) {

		if (!canConnect(world, firstPulley, pos))
			return InteractionResult.FAIL;

		if (firstPulley != null && !firstPulley.equals(pos)) {
			createBelts(world, firstPulley, pos);
			AllAdvancements.BELT.awardTo(playerEntity);
			if (!playerEntity.isCreative())
				context.getItemInHand()
					.shrink(1);
		}

		if (!context.getItemInHand()
			.isEmpty()) {
			heldStack.remove(AllDataComponents.BELT_FIRST_SHAFT);
			playerEntity.getCooldowns()
				.addCooldown(this, 5);
		}
		return InteractionResult.SUCCESS;
	}

	heldStack.set(AllDataComponents.BELT_FIRST_SHAFT, pos);
	playerEntity.getCooldowns()
		.addCooldown(this, 5);
	return InteractionResult.SUCCESS;
}

public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase entity, int timeLeft) {
    if (!world.isRemote) {
        double charge = (Math.min(MAX_CHARGE, getMaxItemUseDuration(stack) - timeLeft)) / MAX_CHARGE;
        float spawnDistance = 2.0f;//Math.max(1.0f, (float)charge/5.0f);
        Vec3d eyesPos = entity.getPositionEyes(1.0f);
        RayTraceResult traceResult = this.rayTrace(world, (EntityPlayer) entity, false);
        if (traceResult != null && traceResult.typeOfHit == RayTraceResult.Type.BLOCK)
            spawnDistance = (float) Math.min(spawnDistance, traceResult.hitVec.distanceTo(eyesPos));
        Vec3d launchPos = eyesPos.add(entity.getLookVec().scale(spawnDistance));
        float damage = (float) Math.max(charge * DAMAGE, 0.5f);
        float size = (float) Math.max(charge * SIZE, 0.5f);
        float aoeSize = (float) charge * AOE_SIZE;
        int lifetime = charge * DAMAGE >= 1.0 ? LIFETIME : 5;
        EffectArea effect = new EffectArea(new EffectDamage(damage, DamageEmber.EMBER_DAMAGE_SOURCE_FACTORY, 1, 1.0), aoeSize, false);
        ProjectileFireball fireball = new ProjectileFireball(entity, launchPos, entity.getLookVec().scale(0.85), size, lifetime, effect);
        EmberProjectileEvent event = new EmberProjectileEvent(entity, stack, charge, fireball);
        MinecraftForge.EVENT_BUS.post(event);
        if (!event.isCanceled()) {
            for (IProjectilePreset projectile : event.getProjectiles()) {
                projectile.shoot(world);
            }
        }
        SoundEvent sound;
        if (charge * DAMAGE >= 10.0)
            sound = SoundManager.FIREBALL_BIG;
        else if (charge * DAMAGE >= 1.0)
            sound = SoundManager.FIREBALL;
        else
            sound = SoundManager.CINDER_STAFF_FAIL;
        world.playSound(null, launchPos.x, launchPos.y, launchPos.z, sound, SoundCategory.PLAYERS, 1.0f, 1.0f);
    }
    entity.swingArm(entity.getActiveHand());
    stack.getTagCompound().setInteger("cooldown", COOLDOWN);
}

