protected void onHit(HitResult result) {
  HitResult.Type type = result.getType();
  if (type == HitResult.Type.ENTITY) {
    //damage entity by zero
    //drop torch
    EntityHitResult entityRayTrace = (EntityHitResult) result;
    Entity target = entityRayTrace.getEntity();
    var level = level();
    if (target.isAlive()) {
      target.hurt(level.damageSources().thrown(this, this.getOwner()), Mth.nextInt(level.random, 2, 6));
      if (!level.isClientSide && target.isOnFire() == false
          && target instanceof LivingEntity) {
        target.hurt(level.damageSources().inFire(), Mth.nextInt(level.random, 3, 5));
        LivingEntity living = (LivingEntity) target;
        living.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, Const.TICKS_PER_SEC * 4, 1, false, false, false));
        living.igniteForSeconds(Mth.nextInt(level.random, 1, 5));
      }
    }
  }
  else if (type == HitResult.Type.BLOCK) {
    BlockHitResult ray = (BlockHitResult) result;
    //  set fire in the area here, small radius randomized, similar to lightning strike or tnt
    var level = this.level();
    if (!level.isClientSide && ray.getBlockPos() != null) {
      final int radius = 2;
      final BlockPos center = ray.getBlockPos().relative(ray.getDirection());
      final int attempts = Mth.nextInt(level.random, 3, 6); //range similar to lightning default
      for (int i = 0; i < attempts; i++) {
        BlockPos firePos = center.offset(
            Mth.nextInt(level.random, -radius, radius),
            Mth.nextInt(level.random, -1, 1),
            Mth.nextInt(level.random, -radius, radius));
        if (level.isEmptyBlock(firePos) && BaseFireBlock.canBePlacedAt(level, firePos, ray.getDirection())) {
          level.setBlockAndUpdate(firePos, BaseFireBlock.getState(level, firePos));
        }
      }
    }
  }
  this.remove(RemovalReason.DISCARDED);
}

public void releaseUsing(ItemStack stack, Level worldIn, LivingEntity entity, int chargeTimer) {
  if (entity instanceof Player == false) {
    return;
  }
  Player player = (Player) entity;
  int charge = this.getUseDuration(stack, entity) - chargeTimer;
  float percentageCharged = BowItem.getPowerForTime(charge); //never zero, its from [0.03,1];
  float velocityFactor = percentageCharged * ItemBaseCyclic.VELOCITY_MAX;
  shootMe(worldIn, player, new FireEntity(player, worldIn), 0, velocityFactor);
  shootMe(worldIn, player, new FireEntity(player, worldIn), 10, velocityFactor);
  shootMe(worldIn, player, new FireEntity(player, worldIn), -10, velocityFactor);
  player.getCooldowns().addCooldown(stack.getItem(), COOLDOWN);
  ItemStackUtil.damageItem(player, stack);
  SoundUtil.playSound(player, SoundRegistry.FIREBALL_STAFF_LAUNCH.get());
}

protected void onHit(HitResult result) {
  HitResult.Type type = result.getType();
  var level = level();
  if (type == HitResult.Type.ENTITY) {
    EntityHitResult entityRayTrace = (EntityHitResult) result;
    Entity target = entityRayTrace.getEntity();
    if (target.isAlive() && target instanceof LivingEntity alive) {
      alive.addEffect(new MobEffectInstance(BuiltInRegistries.MOB_EFFECT.wrapAsHolder(PotionEffectRegistry.SWIMSPEED.get()), 60, 2, false, false, false));
      target.hurt(level.damageSources().thrown(this, this.getOwner()), 0);// zero damage for visuals and knockback 
    }
  }
  else if (type == HitResult.Type.BLOCK) {
    BlockHitResult ray = (BlockHitResult) result;
    if (ray.getBlockPos() == null) {
      return;
    }
    BlockPos pos = ray.getBlockPos();
    if (ray.getDirection() != null) {
      pos = pos.relative(ray.getDirection());
    }
    if (TileFisher.isWater(level, pos)) {
      //fish!
      if (!level.isClientSide) {
        LootTable table;
        if (level.random.nextDouble() < 0.10) { // 10% junk
          table = level.getServer().reloadableRegistries().getLootTable(BuiltInLootTables.FISHING_JUNK);
        }
        else { // 90% fish (ignoring treasure tier)
          table = level.getServer().reloadableRegistries().getLootTable(BuiltInLootTables.FISHING_FISH);
        }
        final int luck = 2;
        final ItemStack fishingRod = new ItemStack(Items.FISHING_ROD);
        // fishingRod.enchant disabled - needs Holder<Enchantment>
        LootParams lootContext = new LootParams.Builder((ServerLevel) level)
            .withLuck(luck)//.withRandom(level.random)
            .withParameter(LootContextParams.ORIGIN, new Vec3(pos.getX(), pos.getY(), pos.getZ()))
            .withParameter(LootContextParams.TOOL, fishingRod)
            .create(LootContextParamSets.FISHING);
        List<ItemStack> lootDrops = table.getRandomItems(lootContext);
        if (lootDrops != null && lootDrops.size() > 0) {
          //            ItemStackUtil.damageItem(null, fishingRod);
          ItemStackUtil.drop(level, pos, lootDrops);
        }
      }
    }
  }
  this.remove(RemovalReason.DISCARDED);
