    CompoundTag tag = stack.getOrCreateTag();
    boolean charged = tag.getBoolean(UtilBooster.chargedKey);
    if (!player.isInWater() && player.getVehicle() == null && UtilBooster.isActive(tag) && UtilBooster.hasFuel(tag, charged)) {
        if (charged) {
            UtilBooster.boostPlayerCharged(player, tag, level);
        } else {
            UtilBooster.boostPlayer(player, tag, level);
        }

        UtilBooster.consumeFuel(tag, charged);
    } else {
        UtilBooster.rechargeFuel(tag, stack);
    }

    if (charged) {
        tag.putBoolean(UtilBooster.chargedKey, false);
    }
}

public static void consumeFuel(CompoundTag tag, boolean charged) {
    if (charged) {
        tag.putInt(fuelKey, tag.getInt(fuelKey) - fuelCostCharged);
    } else {
        tag.putInt(fuelKey, tag.getInt(fuelKey) - fuelCost);
    }
    tag.putInt(cooldownKey, cooldownTicks);
}

public static void rechargeFuel(CompoundTag tag, ItemStack itemStack) {
    int fuel = tag.getInt(fuelKey);
    int buffer = tag.getInt(bufferKey);
    int cooldown = tag.getInt(cooldownKey);
    if (cooldown > 0) {
        tag.putInt(cooldownKey, cooldown - 1);
    } else if (fuel + fuelRecharge < fuelCapacity) {
        if (buffer > 0) {
            tag.putInt(fuelKey, fuel + fuelRecharge);
            tag.putInt(bufferKey, buffer - 1);
        } else {
            refuelBuffer(tag, itemStack);
        }
    }
}

private static void refuelBuffer(CompoundTag tag, ItemStack itemStack) {
    ToolbeltInventory inventory = new QuickslotInventory(itemStack);
    int index = inventory.getFirstIndexForItem(Items.GUNPOWDER);
    if (index != -1) {
        inventory.removeItem(index, 1);
        tag.putInt(bufferKey, gunpowderGain);
        return;
    }

    inventory = new StorageInventory(itemStack);
    index = inventory.getFirstIndexForItem(Items.GUNPOWDER);
    if (index != -1) {
        inventory.removeItem(index, 1);
        tag.putInt(bufferKey, gunpowderGain);
        return;
    }

    tag.putInt(cooldownKey, cooldownTicks);
}

public static void setActive(CompoundTag tag, boolean active, boolean charged) {
    tag.putBoolean(activeKey, active);
    if (charged) {
        tag.putBoolean(chargedKey, charged);
    }
}

public static void toggleSuspend(Player entity, boolean toggleOn) {
    if (toggleOn) {
        if (canSuspend(entity)) {
            Vec3 motion = entity.getDeltaMovement();
            entity.setDeltaMovement(motion.x, 0, motion.z);
            entity.hurtMarked = true;
            entity.addEffect(new MobEffectInstance(SuspendPotionEffect.instance, 100, 0, false, false));
        }
    } else {
        entity.removeEffect(SuspendPotionEffect.instance);
    }
}

public void applyEffectTick(LivingEntity entity, int amplifier) {
    entity.fallDistance = 0;
    if (entity.onGround()) {
        entity.removeEffect(this);
    } else {
        Vec3 motion = entity.getDeltaMovement();
        double dy = motion.y;
        if (entity.isCrouching()) {
            entity.setDeltaMovement(motion.x, Math.max(-0.3, dy - 0.05), motion.z);
        } else {
            entity.setDeltaMovement(motion.x, Math.abs(dy) > 0.02 ? dy * 0.9 : 0, motion.z);
        }

        MobEffectInstance effectInstance = entity.getEffect(this);
        if (effectInstance != null && effectInstance.getDuration() < 20) {
            if (entity instanceof Player player && SuspendEffect.canSuspend(player)) {
                entity.addEffect(new MobEffectInstance(SuspendPotionEffect.instance, 100, 0, false, false));
            } else {
                entity.removeEffect(this);
            }
        }
    }
}

