public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity) {
	super.finishUsingItem(stack, level, entity);
	boolean single = stack.isEmpty();
	if (single) {
		stack.setCount(1);
	}

	PotionFlaskComponent flaskContents = stack.getOrDefault(TFDataComponents.POTION_FLASK_CONTENTS, PotionFlaskComponent.EMPTY);
	if (flaskContents.potion() == PotionContents.EMPTY)
		return stack;

	if (entity instanceof ServerPlayer player) {
		for (MobEffectInstance mobeffectinstance : flaskContents.potion().getAllEffects()) {
			if (mobeffectinstance.is(MobEffects.INSTANT_DAMAGE) != entity.isInvertedHealAndHarm() && mobeffectinstance.getAmplifier() > 0) {
				//custom harming death message for the advancement
				entity.hurtServer(player.level(), entity.damageSources().source(TFDamageTypes.FAILED_CHALLENGE), (float)(6 << mobeffectinstance.getAmplifier()));
			} else if (mobeffectinstance.getEffect().value().isInstantenous()) {
				mobeffectinstance.getEffect().value().applyInstantenousEffect(player.level(), player, player, player, mobeffectinstance.getAmplifier(), 1.0D);
			} else {
				player.addEffect(new MobEffectInstance(mobeffectinstance));
			}
		}
		if (!player.hasInfiniteMaterials() && !player.isSpectator()) {
			flaskContents.potion().potion().ifPresent(potion -> player.getData(TFDataAttachments.FLASK_DOSES).trackDrink(potion, player));
		}
	}

	if (entity.hasInfiniteMaterials())
		return stack;

	ItemStack drunk = single ? stack : stack.copyWithCount(1);
	PotionFlaskComponent remaining = flaskContents.removeDose();
	if (remaining.breakable()) {
		if (remaining.breakage() >= DOSES) {
			if (!level.isClientSide()) {
				level.playSound(null, entity, TFSounds.BRITTLE_FLASK_BREAK.get(), entity.getSoundSource(), 1.5F, 0.7F);
			}
			if (single) {
				stack.shrink(1);
			}
			return stack;
		}
		if (!level.isClientSide()) {
			level.playSound(null, entity, TFSounds.BRITTLE_FLASK_CRACK.get(), entity.getSoundSource(), 1.5F, 2.0F);
		}
	}

	drunk.set(TFDataComponents.POTION_FLASK_CONTENTS, remaining);
	if (!single && entity instanceof Player player) {
		InventoryUtil.giveItemToPlayer(player, drunk);
	}
	return stack;
}

public InteractionResult performScepterAction(Level level, ItemStack stack, Player player, InteractionHand hand) {
	if (level.isClientSide()) {
		return InteractionResult.SUCCESS;
	}

	// what block is the player pointing at?
	BlockHitResult result = getPlayerPOVHitResult(level, player, ClipContext.Fluid.NONE);
	if (result.getType() == HitResult.Type.MISS) {
		return InteractionResult.SUCCESS;
	}

	LoyalZombie zombie = TFEntities.LOYAL_ZOMBIE.get().create(level, EntitySpawnReason.SPAWN_ITEM_USE);
	zombie.snapTo(result.getLocation());
	if (!level.noCollision(zombie, zombie.getBoundingBox())) {
		return InteractionResult.PASS;
	}
	zombie.spawnAnim();
	zombie.setTame(true, false);
	zombie.setOwner(player);
	zombie.addEffect(new MobEffectInstance(MobEffects.STRENGTH, 1200, 1));
	if (player.getItemBySlot(EquipmentSlot.HEAD).is(TFItems.MYSTIC_CROWN) && level.getRandom().nextFloat() <= 0.1f) {
		zombie.setBaby(true);
	}
	level.addFreshEntity(zombie);
	level.gameEvent(player, GameEvent.ENTITY_PLACE, result.getBlockPos());

	if (!player.isCreative()) {
		stack.hurtWithoutBreaking(1, player);
	}
	zombie.playSound(TFSounds.ZOMBIE_SCEPTER_USE.get(), 1.0F, 1.0F);
	return InteractionResult.SUCCESS;
}

private boolean applyOrStackEffect(StackableEffectInstance effect, LivingEntity user) {
	int currentDuration = 0;
	MobEffectInstance activeEffect = user.getEffect(effect.effect());
	if (activeEffect != null) {
		currentDuration = activeEffect.getDuration();
	}
	return user.addEffect(new MobEffectInstance(effect.effect(), currentDuration + effect.extraDurationTicks(), effect.amplifier()));
}

public static void travellersBootsStraightAhead(LivingEntity livingEntity) {
	ItemStack leggingsStack = livingEntity.getItemBySlot(EquipmentSlot.FEET);
	Double multiplier = leggingsStack.get(TFDataComponents.STRAIGHT_AHEAD_MULTIPLIER);
	AttributeInstance attributeInstance = livingEntity.getAttributes().getInstance(Attributes.MOVEMENT_SPEED);
	if (attributeInstance == null)
		return;
	if (multiplier == null)
		multiplier = 1D;
	boolean hasModifier = TravellersModifiersManager.isModifierActive(livingEntity, leggingsStack, TravellersModifiersManager.STRAIGHT_AHEAD_MODIFIER) && multiplier != 1;
	if (hasModifier == attributeInstance.hasModifier(TFAttributeModifiers.STRAIGHT_AHEAD_ATTRIBUTE_MODIFIER_LOCATION))
		return;
	if (hasModifier) {
		attributeInstance.addOrUpdateTransientModifier(new AttributeModifier(TFAttributeModifiers.STRAIGHT_AHEAD_ATTRIBUTE_MODIFIER_LOCATION, multiplier - 1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
	} else {
		attributeInstance.removeModifier(TFAttributeModifiers.STRAIGHT_AHEAD_ATTRIBUTE_MODIFIER_LOCATION);
	}

}

