public boolean itemInteractionForEntity(ItemStack stack, EntityPlayer playerIn, EntityLivingBase target, EnumHand hand) {
	if (playerIn.isSneaking()) return false;
	if (isCoolingDown(playerIn.world, stack)) return false;
	if (BaublesSupport.getItem(playerIn, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty())
		return false;
	if (requiresBowAction(stack)) return false;

	SpellData spell = new SpellData();
	spell.processEntity(playerIn, true);
	spell.processEntity(target, false);
	SpellUtils.runSpell(playerIn.world, stack, spell);

	setCooldown(playerIn.world, playerIn, hand, stack, spell);
	return true;
}

public EnumActionResult onItemUse(EntityPlayer player, World world, BlockPos pos, EnumHand hand, EnumFacing side, float par8, float par9, float par10) {
	ItemStack stack = player.getHeldItem(hand);
	if (player.isSneaking()) {
		for (SpellRing spellRing : SpellUtils.getAllSpellRings(stack)) {
			if ((spellRing.getModule() != null ? spellRing.getModule().getModuleClass() : null) instanceof IBlockSelectable) {
				if (player.world.isAirBlock(pos)) break;
				NBTHelper.setCompound(stack, "selected", NBTUtil.writeBlockState(new NBTTagCompound(), world.getBlockState(pos)));
				player.stopActiveHand();
				player.swingArm(hand);
				return EnumActionResult.PASS;
			}
		}
	}

	if (isCoolingDown(world, stack)) return EnumActionResult.PASS;
	if (requiresBowAction(stack)) return EnumActionResult.PASS;
	if (BaublesSupport.getItem(player, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty())
		return EnumActionResult.PASS;

	SpellData spell = new SpellData();
	spell.processEntity(player, true);
	spell.processBlock(pos, side, new Vec3d(pos).add(0.5, 0.5, 0.5));
	SpellUtils.runSpell(world, stack, spell);

	setCooldown(world, player, hand, stack, spell);

	return EnumActionResult.PASS;
}

public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, @Nonnull EnumHand hand) {
	ItemStack stack = player.getHeldItem(hand);

	if(PotionTimeSlow.timeScale(player) == 0) return new ActionResult<>(EnumActionResult.PASS, stack);

	if (player.isSneaking()) return new ActionResult<>(EnumActionResult.PASS, stack);

	boolean hasHalo = BaublesSupport.getItem(player, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty();
	if (isCoolingDown(world, stack) || hasHalo) {
		return new ActionResult<>(EnumActionResult.FAIL, stack);
	} else {
		if (requiresBowAction(stack))
			player.setActiveHand(hand);
		else {
			SpellData spell = new SpellData();
			spell.processEntity(player, true);
			SpellUtils.runSpell(world, stack, spell);

			setCooldown(world, player, hand, stack, spell);
		}
		return new ActionResult<>(EnumActionResult.PASS, stack);
	}
}

public void onUsingTick(ItemStack stack, EntityLivingBase player, int count) {
	if (isCoolingDown(player.world, stack)) return;
	if (!(player instanceof EntityPlayer)) return;

	if (player.isSneaking()) {
		for (SpellRing spellRing : SpellUtils.getAllSpellRings(stack)) {
			if ((spellRing.getModule() != null ? spellRing.getModule().getModuleClass() : null) instanceof IBlockSelectable) {
				RayTraceResult result = new RayTrace(
						player.world, player.getLookVec(), player.getPositionVector().add(0, player.getEyeHeight(), 0),
						player.getEntityAttribute(EntityPlayer.REACH_DISTANCE).getAttributeValue())
						.setEntityFilter(input -> input != player)
						.setReturnLastUncollidableBlock(true)
						.setIgnoreBlocksWithoutBoundingBoxes(true)
						.trace();

				if (result.typeOfHit == RayTraceResult.Type.BLOCK) {
					BlockPos posHit = result.getBlockPos();
					if (player.world.isAirBlock(posHit)) break;

					NBTHelper.setCompound(stack, "selected", NBTUtil.writeBlockState(new NBTTagCompound(), player.world.getBlockState(posHit)));
					player.stopActiveHand();
					player.swingArm(player.getActiveHand());
				}
				return;
			}
		}
	}

	if (isContinuousSpell(stack)) {

		SpellData spell = new SpellData();
		spell.processEntity(player, true);
		SpellUtils.runSpell(player.world, stack, spell);
	} else {
		int chargeup = getChargeupTime(stack);
		if (72000 - count >= chargeup) {

			SpellData spell = new SpellData();
			spell.processEntity(player, true);
			SpellUtils.runSpell(player.world, stack, spell);

			setCooldown(player.world, (EntityPlayer) player, player.getActiveHand(), stack, spell);
		}
	}
}

public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, @Nonnull EnumHand hand) {
	ItemStack stack = player.getHeldItem(hand);
	if (getItemUseAction(stack) == EnumAction.BOW) {
		if (world.isRemote && (Minecraft.getMinecraft().currentScreen != null)) {
			return new ActionResult<>(EnumActionResult.FAIL, stack);
		} else {
			player.setActiveHand(hand);
			return new ActionResult<>(EnumActionResult.PASS, stack);
		}
	} else return new ActionResult<>(EnumActionResult.FAIL, stack);
}

public void onUsingTick(ItemStack stack, EntityLivingBase player, int count) {
	if (!(player instanceof EntityPlayer)) return;
	if (player.world.isRemote) return;

	if (count <= 1) {
		player.swingArm(player.getActiveHand());
		((EntityPlayer) player).getCooldownTracker().setCooldown(this, 30);

		if (stack.getItemDamage() == 2) {
			player.addPotionEffect(new PotionEffect(ModPotions.STEROID, 500, 0, true, false));
			stack.setItemDamage(0);
		} else if (stack.getItemDamage() == 1) {
			ManaManager.forObject(player)
					.addMana(ManaManager.getMaxMana(player))
					.close();
			player.attackEntityFrom(DamageSourceMana.INSTANCE, 2);
			stack.setItemDamage(0);
		} else if (stack.getItemDamage() == 0) {

			RayTraceResult raytraceresult = this.rayTrace(player.world, (EntityPlayer) player, true);

			if (raytraceresult != null && raytraceresult.typeOfHit != null && raytraceresult.typeOfHit == RayTraceResult.Type.BLOCK) {
				BlockPos blockpos = raytraceresult.getBlockPos();
				if (raytraceresult.sideHit == null) raytraceresult.sideHit = EnumFacing.UP;

				if (player.world.isBlockModifiable((EntityPlayer) player, blockpos)
						&& ((EntityPlayer) player).canPlayerEdit(blockpos.offset(raytraceresult.sideHit), raytraceresult.sideHit, stack)) {

					IBlockState iblockstate = player.world.getBlockState(blockpos);

					Fluid fluid = FluidRegistry.lookupFluidForBlock(iblockstate.getBlock());
					if (fluid != null && fluid == ModFluids.MANA && iblockstate.getValue(BlockLiquid.LEVEL) == 0) {
						stack.setItemDamage(1);
					}
				}
			}
		}
	}
}

