public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack heldStack = player.getItemInHand(hand);
    boolean hasAmmo = !player.getProjectile(heldStack).isEmpty();

    InteractionResultHolder<ItemStack> result = EventHooks.onArrowNock(heldStack, level, player, hand, hasAmmo);
    if (result == null) {
        if (player.getAbilities().instabuild || hasAmmo) {
            player.startUsingItem(hand);
            return InteractionResultHolder.consume(heldStack);
        } else {
            return InteractionResultHolder.fail(heldStack);
        }
    } else {
        return result;
    }
}

public boolean onEntitySwing(ItemStack stack, LivingEntity entity, InteractionHand hand) {
    if (entity instanceof Player player) {
        var data = player.getData(AetherDataAttachments.AETHER_PLAYER);
        if (!player.getCooldowns().isOnCooldown(this) && data.isHitting()) {
            boolean hasMinions = false;
            for (int i = 0; i < data.getCloudMinions().size(); i++) {
                CloudMinion cloudMinion = data.getCloudMinions().get(i);
                if (cloudMinion != null) {
                    cloudMinion.setShouldShoot(true);
                    hasMinions = true;
                }
            }
            if (hasMinions && !player.getAbilities().instabuild) {
                player.getCooldowns().addCooldown(this, AetherConfig.SERVER.cloud_staff_cooldown.get());
            }
        }
    }
    return super.onEntitySwing(stack, entity, hand);
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack heldStack = player.getItemInHand(hand);
    if (!level.isClientSide()) {
        if (!player.getAbilities().instabuild) {
            player.getCooldowns().addCooldown(this, AetherConfig.SERVER.hammer_of_kingbdogz_cooldown.get());
            heldStack.hurtAndBreak(1, player, LivingEntity.getSlotForHand(hand));
        }
        HammerProjectile hammerProjectile = new HammerProjectile(player, level);
        hammerProjectile.shoot(player.getXRot(), player.getYRot(), 3.0F, 1.0F);
        if (heldStack.getHoverName().getString().equalsIgnoreCase("hammer of jeb")) {
            hammerProjectile.setIsJeb(true); // Handles Hammer of Jeb texture for the projectile.
        }
        level.addFreshEntity(hammerProjectile);
    }
    level.playLocalSound(player.getX(), player.getY(), player.getZ(), AetherSoundEvents.ITEM_HAMMER_OF_KINGBDOGZ_SHOOT.get(), SoundSource.PLAYERS, 1.0F, 1.0F / (player.getRandom().nextFloat() * 0.4F + 0.8F), false);
    player.awardStat(Stats.ITEM_USED.get(this));
    return InteractionResultHolder.success(heldStack);
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack heldStack = player.getItemInHand(hand);
    if (this.getFoodProperties(heldStack, player) != null) { // If AetherConfig.SERVER.healing_gummy_swets.get() is false.
        FoodProperties foodProperties = this.getFoodProperties(heldStack, player);
        if (foodProperties != null && player.canEat(foodProperties.canAlwaysEat())) {
            player.startUsingItem(hand);
            return InteractionResultHolder.consume(heldStack);
        } else {
            return InteractionResultHolder.fail(heldStack);
        }
    } else { // If AetherConfig.SERVER.healing_gummy_swets.get() is true.
        if (player.getHealth() < player.getMaxHealth() && !player.isCreative()) {
            player.startUsingItem(hand);
            return InteractionResultHolder.consume(heldStack);
        } else {
            return InteractionResultHolder.fail(heldStack);
        }
    }
}

