	public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand)
	{
		ItemStack stack = player.getItemInHand(hand);
		if (PlayerHelper.isFakePlayer(player))
			return super.use(world, player, hand);

		if (this.canUseForSacrifice(stack))
		{
			player.startUsingItem(hand);
			return InteractionResultHolder.success(stack);
		}

		int lpAdded = ConfigManager.COMMON.sacrificialDaggerConversion.get() * 2;

//		RayTraceResult rayTrace = rayTrace(world, player, false);
//		if (rayTrace != null && rayTrace.typeOfHit == RayTraceResult.Type.BLOCK)
//		{
//			TileEntity tile = world.getTileEntity(rayTrace.getBlockPos());
//
//			if (tile != null && tile instanceof TileAltar && stack.getItemDamage() == 1)
//				lpAdded = ((TileAltar) tile).getCapacity();
//		}

		if (!player.getAbilities().instabuild)
		{
			SacrificeKnifeUsedEvent evt = new SacrificeKnifeUsedEvent(player, true, true, 2, lpAdded);
			if (MinecraftForge.EVENT_BUS.post(evt))
				return super.use(world, player, hand);

			if (evt.shouldDrainHealth)
			{
				player.invulnerableTime = 0;

				player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 0.001F);
				player.setHealth(Math.max(player.getHealth() - 1.998F, 0.0001f));
				if (player.getHealth() <= 0.001f && !world.isClientSide)
				{
					player.invulnerableTime = 0;
					player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 10);
				}
			}

			if (!evt.shouldFillAltar)
				return super.use(world, player, hand);

			lpAdded = evt.lpAdded;
		} else if (player.isShiftKeyDown())
		{
			lpAdded = Integer.MAX_VALUE;
		}

		double posX = player.getX();
		double posY = player.getY();
		double posZ = player.getZ();
		world.playSound(player, posX, posY, posZ, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F, 2.6F + (world.random.nextFloat() - world.random.nextFloat()) * 0.8F);

		for (int l = 0; l < 8; ++l)
			world.addParticle(DustParticleOptions.REDSTONE, posX + Math.random() - Math.random(), posY + Math.random() - Math.random(), posZ + Math.random() - Math.random(), 0, 0, 0);

		if (!world.isClientSide && PlayerHelper.isFakePlayer(player))
			return super.use(world, player, hand);

		// TODO - Check if SoulFray is active
		PlayerSacrificeHelper.findAndFillAltar(world, player, lpAdded, false);

		return super.use(world, player, hand);
	}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand hand)
{
	ItemStack stack = playerIn.getItemInHand(hand);
	if (!playerIn.isCreative())
	{
		stack.shrink(1);
	}
	playerIn.getCooldowns().addCooldown(this, 50);

	worldIn.playSound((Player) null, playerIn.getX(), playerIn.getY(), playerIn.getZ(), SoundEvents.SNOWBALL_THROW, SoundSource.NEUTRAL, 0.5F, 0.4F / (worldIn.random.nextFloat() * 0.4F + 0.8F));

	if (!worldIn.isClientSide)
	{
		ItemStack copyStack = stack.copy();
		copyStack.setCount(1);
		AbstractEntityThrowingDagger dagger = getDagger(copyStack, worldIn, playerIn);

		worldIn.addFreshEntity(dagger);
	}

	return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
}

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving)
{
	Player playerentity = entityLiving instanceof Player ? (Player) entityLiving : null;
	if (playerentity instanceof ServerPlayer)
	{
		CriteriaTriggers.CONSUME_ITEM.trigger((ServerPlayer) playerentity, stack);
	}

	if (!worldIn.isClientSide)
	{
		for (MobEffectInstance effectinstance : PotionUtils.getMobEffects(stack))
		{
			if (effectinstance.getEffect().isInstantenous())
			{
				effectinstance.getEffect().applyInstantenousEffect(playerentity, playerentity, entityLiving, effectinstance.getAmplifier(), 1.0D);
			} else
			{
				entityLiving.addEffect(new MobEffectInstance(effectinstance));
			}
		}
	}

	if (playerentity != null)
	{
		playerentity.awardStat(Stats.ITEM_USED.get(this));
		if (!playerentity.getAbilities().instabuild)
		{
			stack.setDamageValue(stack.getDamageValue() + 1);
		}
	}

	return stack;
}

public int receiveButtonPress(ItemStack filterStack, String buttonKey, int ghostItemSlot, int currentButtonState)
{
	// Returns new state that the pressed button is in. -1 for an invalid button.
	CompoundTag tag = filterStack.getTag();
	if (tag == null)
	{
		filterStack.setTag(new CompoundTag());
		tag = filterStack.getTag();
	}

	if (buttonKey.equals(Constants.BUTTONID.BLACKWHITELIST))
	{
		int nextState = 0;
		switch (currentButtonState)
		{
		case 0:
			nextState = 1;
			break;
		default:
			nextState = 0;
		}

		tag.putInt(Constants.NBT.BLACKWHITELIST, nextState);

		return nextState;
	}

	List<ItemStack> nestedList = getNestedFilters(filterStack);
	for (ItemStack nestedStack : nestedList)
	{
		int nextState = ((INestableItemFilterProvider) nestedStack.getItem()).receiveButtonPress(filterStack, buttonKey, ghostItemSlot, currentButtonState);
		if (nextState != -1)
		{
			return nextState;
		}
	}

	return -1;
}

