public boolean performArrayEffect(Level world, BlockPos pos)
{
	double radius = 10;
	int ticks = 600;
	int potionPotency = 2;

	AABB bb = new AABB(pos).inflate(radius);
	List<Player> playerList = world.getEntitiesOfClass(Player.class, bb);
	for (Player player : playerList)
	{
		if (!player.hasEffect(MobEffects.DIG_SPEED) || (player.hasEffect(MobEffects.DIG_SPEED)
				&& player.getEffect(MobEffects.DIG_SPEED).getAmplifier() < potionPotency))
		{
			player.addEffect(new MobEffectInstance(MobEffects.DIG_SPEED, ticks, potionPotency));
			if (!player.isCreative())
			{
				player.invulnerableTime = 0;
				player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 1.0F);
			}
		}
	}

	return false;
}

public void applyEffectToEntity(EnumDemonWillType type, int willBracket, LivingEntity target, Player attacker)
{
	switch (type)
	{
	case CORROSIVE:
		target.addEffect(new MobEffectInstance(MobEffects.WITHER, poisonTime[willBracket], poisonLevel[willBracket]));
		break;
	case DEFAULT:
		break;
	case DESTRUCTIVE:
		break;
	case STEADFAST:
		if (!target.isAlive())
		{
			float absorption = attacker.getAbsorptionAmount();
			attacker.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, absorptionTime[willBracket], 127));
			attacker.setAbsorptionAmount((float) Math.min(absorption + target.getMaxHealth() * 0.05f, maxAbsorptionHearts));
		}
		break;
	case VENGEFUL:
		break;
	}
}

