public static Multimap<Attribute, AttributeModifier> handle(Player player, Multimap<Attribute, AttributeModifier> existing)
{

	ItemStack chest = player.getItemBySlot(EquipmentSlot.CHEST);
	boolean hasFullSet = LivingUtil.hasFullSet(player);

	if (hasFullSet && existing == null)
	{
		existing = ((ExpandedArmor) chest.getItem()).getAttributeModifiers(EquipmentSlot.CHEST, chest);
		player.getAttributes().addTransientAttributeModifiers(existing);
	}

	if (!hasFullSet && existing != null)
	{
		player.getAttributes().removeAttributeModifiers(existing);
		existing = null;
	}

	return existing;
}

public static List<Text> textFor(ItemStack stack, @Nullable PlayerEntity player) {
    var text = new ArrayList<Text>();
    var component = stack.get(SpellDataComponents.EQUIPMENT_SET);
    if (component == null) {
        return text;
    }
    var optionalEntry = EquipmentSetRegistry.from(player.getWorld()).getEntry(component);
    if (optionalEntry.isPresent() && player != null && player.getWorld() != null) {
        var equipmentSetEntry = optionalEntry.get();
        var equipmentSet = equipmentSetEntry.value();
        var setSize = equipmentSet.items().size();

        var activeSets = ((EquipmentSet.Owner) player).getActiveEquipmentSets();
        List<ItemStack> wornItems = List.of();
        for (var entry : activeSets) {
            if (entry.set().getKey().get().equals(equipmentSetEntry.getKey().get())) {
                wornItems = entry.items();
            }
        }

        text.add(Text.literal(" "));

        // Title:
        // Justicar Raiment (2/4)
        text.add(
                Text.translatable(EquipmentSet.translationKey(equipmentSetEntry))
                        .append(Text.literal(" (" + wornItems.size() + "/" + setSize + ")"))
                        .formatted(Formatting.GOLD)
        );

        // Items:
        //  Justicar Helm
        //  Justicar Chestplate
        //  Justicar Leggings
        //  Justicar Boots
        for (var item : equipmentSet.items()) {
            var isWorn = wornItems.stream().anyMatch(wornItem -> wornItem.isOf(item.value()));
            text.add(
                    Text.literal(" ").append(
                            Text.translatable(item.value().getTranslationKey())
                                    .formatted(isWorn ? Formatting.GRAY : Formatting.DARK_GRAY)
                    )
            );
        }

        // Bonuses:
        // (2) Set : +5% Attack Damage
        // (4) Set : Reduces cooldown of Judgement by 3 seconds
        for (var bonus: equipmentSet.bonuses()) {
            var isActive = wornItems.size() >= bonus.requiredPieceCount();
            text.addAll(bonusText(player, stack, bonus, isActive));
        }
    }
    return text;
}

public static void onSpellAdded(ItemStack itemStack, RegistryEntry<Spell> spellEntry, @Nullable TagKey<Spell> pool) {
    // Set rarity
    var spell = spellEntry.value();
    var ordinal = Math.max(spell.tier - 1, 0); // minimum 0
    var rarity = Rarity.values().length > ordinal ? Rarity.values()[ordinal] : Rarity.EPIC;
    itemStack.set(DataComponentTypes.RARITY, rarity);

    if (pool != null) {
        // Set custom model override
        var modelId = modelIdForPool(pool.id());
        itemStack.set(SpellDataComponents.ITEM_MODEL, modelId);

        // Set custom name
        // - Example: "paladins:spell_scroll/paladin" -> "item.paladins.paladin_spell_scroll"
        var key = translationKeyForPool(pool.id());
        if (Language.getInstance().hasTranslation(key)) {
            itemStack.set(DataComponentTypes.ITEM_NAME, Text.translatable(key));
        }
    }
}

