public record PotionLauncherData(PotionContents renderData, int lastSlot) {

    public static MapCodec<PotionLauncherData> CODEC = RecordCodecBuilder.mapCodec(instance -> instance.group(
            PotionContents.CODEC.fieldOf("lastDataForRender").forGetter(PotionLauncherData::renderData),
            Codec.INT.fieldOf("lastSlot").forGetter(PotionLauncherData::lastSlot)
    ).apply(instance, PotionLauncherData::new));

    public static StreamCodec<RegistryFriendlyByteBuf, PotionLauncherData> STREAM = StreamCodec.composite(
            PotionContents.STREAM_CODEC,
            PotionLauncherData::renderData,
            ByteBufCodecs.INT,
            PotionLauncherData::lastSlot,
            PotionLauncherData::new
    );

    public PotionLauncherData() {
        this(PotionContents.EMPTY, -1);
    }

    public @Nullable IPotionProvider getPotionDataFromSlot(Player player) {
        ItemStack stack = getSelectedStack(player);
        return PotionProviderRegistry.from(stack);
    }

    public ItemStack getSelectedStack(Player player) {
        if (lastSlot < 0 || lastSlot >= player.inventory.getContainerSize())
            return ItemStack.EMPTY;
        return player.inventory.getItem(lastSlot);
    }

    public PotionContents expendPotion(Player player, ItemStack launcherStack) {
        if (lastSlot >= player.inventory.getContainerSize())
            return PotionContents.EMPTY;
        ItemStack item = player.inventory.getItem(lastSlot);
        var provider = PotionProviderRegistry.from(item);
        if (provider == null) {
            return PotionContents.EMPTY;
        }
        if (provider.usesRemaining(item) <= 0) {
            return PotionContents.EMPTY;
        }

        PotionContents contents = provider.getPotionData(item);
        if (item.getItem() instanceof PotionFlask potionFlask) {
            contents = potionFlask.getModifiedPotionContents(contents);
        }

        provider.consumeUses(item, 1, player);
        launcherStack.set(DataComponentRegistry.POTION_LAUNCHER, new PotionLauncherData(provider.getPotionData(item), lastSlot));
        return contents;
    }

    public int amountLeft(Player player) {
        ItemStack stack = getSelectedStack(player);
        var provider = PotionProviderRegistry.from(stack);
        if (provider == null) {
            return 0;
        }
        return provider.usesRemaining(stack);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        PotionLauncherData that = (PotionLauncherData) o;
        return lastSlot == that.lastSlot && Objects.equals(renderData, that.renderData);
    }

    @Override
    public int hashCode() {
        return Objects.hash(renderData, lastSlot);
    }
}

public PotionContents expendPotion(Player player, ItemStack launcherStack) {
    if (lastSlot >= player.inventory.getContainerSize())
        return PotionContents.EMPTY;
    ItemStack item = player.inventory.getItem(lastSlot);
    var provider = PotionProviderRegistry.from(item);
    if (provider == null) {
        return PotionContents.EMPTY;
    }
    if (provider.usesRemaining(item) <= 0) {
        return PotionContents.EMPTY;
    }

    PotionContents contents = provider.getPotionData(item);
    if (item.getItem() instanceof PotionFlask potionFlask) {
        contents = potionFlask.getModifiedPotionContents(contents);
    }

    provider.consumeUses(item, 1, player);
    launcherStack.set(DataComponentRegistry.POTION_LAUNCHER, new PotionLauncherData(provider.getPotionData(item), lastSlot));
    return contents;
}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    ItemStack dyeStack = getDye(shooter, spellStats, spellContext);
    if (dyeStack.isEmpty()) return;
    DyeItem dye = (DyeItem) dyeStack.getItem();

    if (rayTraceResult.getEntity() instanceof ItemEntity itemEntity) {
        ItemStack item = itemEntity.getItem();

        if (itemEntity.getItem().has(DataComponents.BASE_COLOR)) {
            itemEntity.getItem().set(DataComponents.BASE_COLOR, dye.getDyeColor());
        } else if (item.getItem() instanceof BlockItem blockItem) {
            ItemStack result = getDyedResult((ServerLevel) world, makeContainer(dye, blockItem));
            result.setCount(itemEntity.getItem().getCount());
            if (!result.isEmpty() && result.getItem() instanceof BlockItem) {
                itemEntity.setItem(result);
            }
        }


    } else if (rayTraceResult.getEntity() instanceof LivingEntity living) {
        if (living instanceof Sheep sheep)
            sheep.setColor(dye.getDyeColor());
        else if (spellStats.isSensitive() || living instanceof ArmorStand) {
            for (ItemStack armorStack : living.getArmorSlots()) {
                if (!armorStack.isEmpty()) {
                    var dyeComponent = armorStack.get(DataComponents.DYED_COLOR);
                    if (dyeComponent != null) {
                        armorStack.set(DataComponents.DYED_COLOR, new DyedItemColor(dye.getDyeColor().getTextureDiffuseColor(), false));
                    } else if (armorStack.has(DataComponents.BASE_COLOR)) {
                        armorStack.set(DataComponents.BASE_COLOR, dye.getDyeColor());
                    }
                }
            }
        } else if (living instanceof Mob mob) {
            Player player = ANFakePlayer.getPlayer((ServerLevel) world);
            player.setItemInHand(InteractionHand.MAIN_HAND, dyeStack);
            ((MobAccessor) mob).callMobInteract(player, InteractionHand.MAIN_HAND);
            player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
        }
    }
    world.playSound(null, rayTraceResult.getEntity().getX(), rayTraceResult.getEntity().getY(), rayTraceResult.getEntity().getZ(), SoundEvents.EVOKER_PREPARE_WOLOLO, SoundSource.PLAYERS, 1.0f, 1.0f);
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack itemStack = player.getItemInHand(hand);
    if (level instanceof ServerLevel serverlevel && player instanceof ServerPlayer serverPlayer) {
        player.getCooldowns().addCooldown(ItemRegistry.CINDEROUS_SOULCALLER.get(), 80);
        BlockPos playerBlockPos = player.blockPosition();
        PoiManager poimanager = serverlevel.getPoiManager();
        // arena radius is 23. slightly shorter distance means player must approach center/keystone
        // player must also be at or above the keystone (with tolerance of 2 blocks) so as to be on an even fighting field
        var keystone = poimanager.findClosest(poi -> Objects.equals(poi.getKey(), PoiTypeRegistry.CINDEROUS_KEYSTONE_POI.getKey()), playerBlockPos, 22, PoiManager.Occupancy.ANY);
        if (keystone.isPresent() && playerBlockPos.getY() + 2 >= keystone.get().getY()) {
            BlockPos keystonePos = keystone.get();
            AABB exclusiveRange = AABB.ofSize(keystonePos.getCenter(), 80, 80, 80);
            if (level.getEntitiesOfClass(FireBossEntity.class, exclusiveRange).isEmpty()) {
                //success, consume and summon
                if (!player.getAbilities().instabuild) {
                    Vec3 particlePos = player.getEyePosition().add(player.getForward().scale(0.6)).subtract(0, 0.3, 0);
                    MagicManager.spawnParticles(serverlevel, new ItemParticleOption(ParticleTypes.ITEM, itemStack), particlePos.x, particlePos.y, particlePos.z, 9, .15, .15, .15, 0.08, false);
                    itemStack.shrink(1);
                    player.setItemInHand(hand, itemStack);
                }
                Vec3 center = keystonePos.getCenter().add(0, 0.6, 0);
                float yRot = Utils.getAngle(center.x, center.z, player.getX(), player.getZ()) * Mth.RAD_TO_DEG;
                FireBossEntity fireBoss = EntityRegistry.FIRE_BOSS.get().create(serverlevel);
                fireBoss.setSpawnPos(center);
                fireBoss.moveTo(center);
                fireBoss.setYRot(yRot + 90);
                fireBoss.triggerSpawnAnim();
                level.addFreshEntity(fireBoss);
                fireBoss.finalizeSpawn(serverlevel, level.getCurrentDifficultyAt(player.blockPosition()), MobSpawnType.MOB_SUMMONED, null);
                tollEffects(serverlevel, player.position(), true);
            } else {
                //failure, boss already exists
                serverPlayer.connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("item.irons_spellbooks.cinderous_soulcaller.failure.in_progress").withStyle(ChatFormatting.GOLD)));
                tollEffects(serverlevel, player.position(), false);
            }
        } else {
            //failure, no soul present
            serverPlayer.connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("item.irons_spellbooks.cinderous_soulcaller.failure.no_soul").withStyle(ChatFormatting.GOLD)));
            tollEffects(serverlevel, player.position(), false);
        }
    }
    player.swing(hand);
    return InteractionResultHolder.consume(itemStack);
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    if (level instanceof ServerLevel serverlevel) {
        level.playSound(null, player, SoundEvents.UI_CARTOGRAPHY_TABLE_TAKE_RESULT, player.getSoundSource(), 1.0F, 1.0F);
        ItemStack itemStack = player.getItemInHand(hand);
        player.getCooldowns().addCooldown(itemStack.getItem(), 50);

        if (itemStack.has(ComponentRegistry.FURLED_MAP_COMPONENT)) {
            var furledMapData = itemStack.get(ComponentRegistry.FURLED_MAP_COMPONENT);
            ResourceKey<Structure> structureResourceKey = ResourceKey.create(Registries.STRUCTURE, furledMapData.destinationResource);
            var holder = serverlevel.registryAccess().registryOrThrow(Registries.STRUCTURE).getHolder(structureResourceKey).map(HolderSet::direct);
            if (furledMapData.dimension().isPresent()) {
                var dimensionRestriction = furledMapData.dimension().get();
                if (!serverlevel.dimension().equals(dimensionRestriction)) {
                    ((ServerPlayer) player).connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("item.irons_spellbooks.furled_map.dimension_fail").withStyle(ChatFormatting.RED)));
                    return InteractionResultHolder.fail(itemStack);
                }
            }
            if (holder.isPresent()) {
                Pair<BlockPos, Holder<Structure>> pair = serverlevel.getChunkSource().getGenerator().findNearestMapStructure(serverlevel, holder.get(), player.blockPosition(), 100, ServerConfigs.FURLED_MAPS_SKIP_CHUNKS.get());
                if (pair != null) {
                    var blockpos = pair.getFirst();
                    ItemStack mapStack = MapItem.create(serverlevel, blockpos.getX(), blockpos.getZ(), (byte) 2, true, true);
                    MapItem.renderBiomePreviewMap(serverlevel, mapStack);
                    MapItemSavedData.addTargetDecoration(mapStack, blockpos, "red_x", MapDecorationTypes.RED_X);
                    furledMapData.descriptionOverride.ifPresent(component -> mapStack.set(DataComponents.CUSTOM_NAME, component));

                    replaceItem(player, mapStack, hand);
                    return InteractionResultHolder.sidedSuccess(itemStack, level.isClientSide);
                }
            }
        }
        replaceItem(player, new ItemStack(Items.MAP), hand);
    }
    return super.use(level, player, hand);
}

