}

public static void UseItemEvent(LivingEntityUseItemEvent.Finish event){
    if (CuriosFinder.hasCurio(event.getEntity(), ModItems.CRONE_HAT.get())){
        if (event.getEntity().level.random.nextFloat() <= 0.25F){
            if (event.getItem().getItem() instanceof PotionItem){
                event.setResultStack(event.getItem());
            }
        }
        if (event.getEntity().level.random.nextFloat() <= 0.1F){
            if (event.getItem().getItem() instanceof BrewItem){
                event.setResultStack(event.getItem());
            }
        }
    } else if (CuriosFinder.hasCurio(event.getEntity(), itemStack -> itemStack.getItem() instanceof WitchHatItem)){
        if (event.getEntity().level.random.nextFloat() <= 0.1F){
            if (event.getItem().getItem() instanceof PotionItem){
                event.setResultStack(event.getItem());
            }
        }
    }
    if (event.getEntity() instanceof Player player) {
        if (MainConfig.WandCoolItemUse.get()) {
            if (!(event.getItem().getItem() instanceof IWand)) {
                Item main = event.getEntity().getMainHandItem().getItem();
                Item off = event.getEntity().getOffhandItem().getItem();
                if (main instanceof IWand) {
                    player.getCooldowns().addCooldown(main, 10);
                } else if (off instanceof IWand) {
                    player.getCooldowns().addCooldown(off, 10);
                }
            }
        }
    }
}

public static void AxeDeath(LivingDeathEvent event){
    LivingEntity killed = event.getEntity();
    Entity killer = event.getSource().getEntity();
    Level world = killed.getCommandSenderWorld();
    if (killer instanceof LivingEntity livingEntity) {
        if (ModDamageSource.physicalAttacks(event.getSource()) && livingEntity.getMainHandItem().getItem() instanceof RampagingAxeItem) {
            MobEffectInstance effectinstance1 = livingEntity.getEffect(GoetyEffects.RAMPAGE.get());
            if (!livingEntity.hasEffect(GoetyEffects.RAMPAGE.get())){
                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.RAMPAGE.get(), MathHelper.secondsToTicks(ItemConfig.RampagingAxeDuration.get())));
            } else if (effectinstance1 != null){
                int random = killed.getMaxHealth() >= 20 ? 0 : world.random.nextInt(4);
                if (effectinstance1.getAmplifier() < 4) {
                    if (random == 0) {
                        EffectsUtil.amplifyEffect(livingEntity, GoetyEffects.RAMPAGE.get(), MathHelper.secondsToTicks(ItemConfig.RampagingAxeDuration.get()));
                    }
                } else {
                    livingEntity.removeEffect(GoetyEffects.RAMPAGE.get());
                    if (world instanceof ServerLevel serverLevel) {
                        serverLevel.sendParticles(new ShockwaveParticleOption(), livingEntity.getX(), livingEntity.getY() + 0.5F, livingEntity.getZ(), 0, 0.0D, 0.0D, 0.0D, 0);
                        serverLevel.sendParticles(ParticleTypes.EXPLOSION_EMITTER, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 1.0D, 0.0D, 0.0D, 0.5F);
                    }
                    LootingExplosion.Mode lootMode = CuriosFinder.hasWanting(livingEntity) ? LootingExplosion.Mode.LOOT : LootingExplosion.Mode.REGULAR;
                    ExplosionUtil.lootExplode(world, livingEntity, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 3.0F, false, Explosion.BlockInteraction.KEEP, lootMode);
                }
            }
        }
    }
}

public static void onPlayerLichdom(TickEvent.PlayerTickEvent event){
    Player player = event.player;
    Level world = player.level;
    if (LichdomHelper.isLich(player)){
        player.getFoodData().setFoodLevel(17);
        player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_REST));
        boolean burn = MobUtil.isInSunlightNoRain(player);

        if (!player.level.isClientSide) {
            if (burn){
                ItemStack helmet = player.getItemBySlot(EquipmentSlot.HEAD);
                if (!helmet.isEmpty()) {
                    if (!player.isCreative()) {
                        if (!MobUtil.isFireImmune(player)) {
                            if (MainConfig.LichDamageHelmet.get()) {
                                if (helmet.isDamageableItem()) {
                                    ItemHelper.hurtAndBreak(helmet, world.random.nextInt(2), player);
                                }
                            }
                        }
                    }
                    burn = false;
                }
                if (burn){
                    if (!MobUtil.isFireImmune(player)){
                        player.setSecondsOnFire(8);
                    }
                }
            }
        }

        player.getActiveEffects().removeIf(effectInstance -> !EffectsUtil.canAffectLich(effectInstance, world));
        if (player.hasEffect(GoetyEffects.SOUL_HUNGER.get())){
            if (SEHelper.getSoulsAmount(player, MainConfig.MaxSouls.get())){
                player.removeEffect(GoetyEffects.SOUL_HUNGER.get());
            }
        }
        if (MainConfig.LichSoulHeal.get()) {
            if (!(player.isOnFire() && !MobUtil.isFireImmune(player)) && LichdomHelper.smited(player) <= 0) {
                if (player.getHealth() < player.getMaxHealth()) {
                    if (player.tickCount % (MathHelper.secondsToTicks(MainConfig.LichHealSeconds.get()) + 1) == 0 && SEHelper.getSoulsAmount(player, MainConfig.LichHealCost.get())) {
                        player.heal(MainConfig.LichHealAmount.get().floatValue());
                        Vec3 vector3d = player.getDeltaMovement();
                        if (!player.level.isClientSide) {
                            ServerLevel serverWorld = (ServerLevel) player.level;
                            serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, player.getRandomX(0.5D), player.getRandomY(), player.getRandomZ(0.5D), 0, vector3d.x * -0.2D, 0.1D, vector3d.z * -0.2D, 0.5F);
                        }
                        SEHelper.decreaseSouls(player, MainConfig.LichHealCost.get());
                    }
                }
            }
        }
        if (MainConfig.LichVillagerHate.get() && player.tickCount % 20 == 0) {
            for (Villager villager : player.level.getEntitiesOfClass(Villager.class, player.getBoundingBox().inflate(16.0D))) {
                if (villager.getPlayerReputation(player) > -200 && villager.getPlayerReputation(player) < 100) {
                    villager.getGossips().add(player.getUUID(), GossipType.MAJOR_NEGATIVE, 25);
                }
            }
            for (IronGolem ironGolem : player.level.getEntitiesOfClass(IronGolem.class, player.getBoundingBox().inflate(16.0D))) {
                if (!ironGolem.isPlayerCreated() && ironGolem.getTarget() != player && TargetingConditions.forCombat().range(16.0F).test(ironGolem, player)) {
                    ironGolem.setTarget(player);
                }
            }
        }
        if (LichdomHelper.isInLichMode(player)) {
            if (player.tickCount % 5 == 0) {
                if (world.isClientSide) {
                    int color = LichdomHelper.lichModeColor(player);
                    if (color > -1) {
                        ColorUtil colorUtil = new ColorUtil(color);
                        world.addParticle(ModParticleTypes.LICH_COLORED.get(), player.getRandomX(0.5D), player.getY(), player.getRandomZ(0.5D), colorUtil.red(), colorUtil.green(), colorUtil.blue());
                    } else {
                        world.addParticle(ModParticleTypes.LICH.get(), player.getRandomX(0.5D), player.getY(), player.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
                    }
                }
            }
            if (MainConfig.LichModeSounds.get()) {
                if (event.phase == TickEvent.Phase.END) {
                    if (player.isAlive()) {
                        MiscCapHelper.doAmbientSoundTime(player);
                        if (MiscCapHelper.getAmbientSoundTime(player) > player.getRandom().nextInt(1000)) {
                            MiscCapHelper.setAmbientSoundTime(player, -MathHelper.secondsToTicks(4));
                            if (!player.level.isClientSide) {
                                ModNetwork.sentToTrackingEntityAndPlayer(player, new SPlayFollowSoundPacket(player, ModSounds.LICH_AMBIENT.get(), 1.0F, player.getVoicePitch(), false));
                            }
                        }
                    }
                }
            }
        }
        if (player.isAlive()){
            if (!player.level.isClientSide) {
                MobEffectInstance instance = player.getEffect(MobEffects.NIGHT_VISION);
                if (LichdomHelper.nightVision(player) && MainConfig.LichNightVision.get()) {
                    if (instance == null || instance.getDuration() <= 210) {
                        player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, 300, 0, false, false, false));
                    }
                } else {
                    if (instance != null) {
                        if (instance.getDuration() <= 300) {
                            player.removeEffect(MobEffects.NIGHT_VISION);
                        }
                    }
                }
            }
        }
        if (LichdomHelper.smited(player) > 0){
            LichdomHelper.setSmited(player, LichdomHelper.smited(player) - 1);
        }
    } else {
        if (LichdomHelper.isInLichMode(player)) {
            LichdomHelper.setLichMode(player, false);
        }
        if (LichdomHelper.nightVision(player)) {
            LichdomHelper.setNightVision(player, false);
        }
    }

    if (IronLoaded.IRON_SPELLBOOKS.isLoaded()){
        AttributeInstance bloodResist = player.getAttribute(IronAttributes.BLOOD_MAGIC_RESIST);
        if (bloodResist != null){
            if (LichdomHelper.isLich(player)){
                if (!bloodResist.hasModifier(BLOOD_RESIST_MOD)){
                    bloodResist.addPermanentModifier(BLOOD_RESIST_MOD);
                }
            } else {
                if (bloodResist.hasModifier(BLOOD_RESIST_MOD)){
                    bloodResist.removeModifier(BLOOD_RESIST_MOD);
                }
            }
        }

        AttributeInstance holyResist = player.getAttribute(IronAttributes.HOLY_MAGIC_RESIST);
        if (holyResist != null){
            if (LichdomHelper.isLich(player)){
                if (!holyResist.hasModifier(HOLY_WEAK_MOD)){
                    holyResist.addPermanentModifier(HOLY_WEAK_MOD);
                }
            } else {
                if (holyResist.hasModifier(HOLY_WEAK_MOD)){
                    holyResist.removeModifier(HOLY_WEAK_MOD);
                }
            }
        }
    }
}

public static void HurtEvent(LivingHurtEvent event){
    LivingEntity victim = event.getEntity();
    Entity source = event.getSource().getEntity();
    if (victim instanceof Player player) {
        if (LichdomHelper.isLich(player)){
            if (event.getSource().is(ModTags.DamageTypes.LICH_IMMUNE)) {
                event.setCanceled(true);
            }
            if (MainConfig.LichMagicResist.get()) {
                if (event.getSource().is(DamageTypeTags.WITCH_RESISTANT_TO)) {
                    event.setAmount(event.getAmount() * 0.15F);
                }
            }
            if (ModDamageSource.freezeAttacks(event.getSource()) || event.getSource().is(DamageTypeTags.IS_FREEZING)){
                event.setAmount(event.getAmount()/2);
            }
            if (MainConfig.LichUndeadFriends.get()) {
                if (CuriosFinder.hasUndeadSet(player) && source != null) {
                    if (source instanceof LivingEntity attacker && attacker.isAlive()) {
                        for (Mob undead : player.level.getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(16))) {
                            if (!MobUtil.areAllies(attacker, player)) {
                                if (undead.getMobType() == MobType.UNDEAD) {
                                    if (undead.getTarget() != player) {
                                        if (MainConfig.LichPowerfulFoes.get()) {
                                            if (undead.getMaxHealth() <= MainConfig.LichPowerfulFoesHealth.get()) {
                                                undead.setLastHurtByMob(attacker);
                                                undead.setTarget(attacker);
                                            }
                                        } else {
                                            undead.setLastHurtByMob(attacker);
                                            undead.setTarget(attacker);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (LichdomHelper.isInLichMode(player)){
                if (MainConfig.LichModeSounds.get()) {
                    if (player.isAlive()) {
                        if (event.getAmount() > 0.0F) {
                            if (!player.level.isClientSide) {
                                player.level.playSound(null, player.getX(), player.getY(), player.getZ(), ModSounds.LICH_HURT.get(), player.getSoundSource(), 1.0F, player.getVoicePitch());
                                MiscCapHelper.setAmbientSoundTime(player, -MathHelper.secondsToTicks(4));
                            }
                        }
                    }
                }
            }
        }
    }
    if (event.getSource().getDirectEntity() instanceof Player player){
        if (LichdomHelper.isLich(player) && MainConfig.LichTouch.get()){
            if (ModDamageSource.physicalAttacks(event.getSource()) && victim != player){
                if (player.getMainHandItem().isEmpty()) {
                    victim.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), 900));
                }
                if (victim.getMobType() != MobType.UNDEAD && player.getMainHandItem().is(ModTags.Items.LICH_WITHER_ITEMS)){
                    victim.addEffect(new MobEffectInstance(MobEffects.WITHER, MathHelper.secondsToTicks(5)));
                }
            }
        }
    }
}

public static void HurtEvent(LivingHurtEvent event){
    LivingEntity victim = event.getEntity();
    Entity attacker = event.getSource().getEntity();
    float finalAmount = event.getAmount();
    float bonus = 0.0F;
    if (attacker instanceof LivingEntity living) {
        if (ModDamageSource.physicalAttacks(event.getSource())) {
            if (living.hasEffect(GoetyEffects.FLAME_HANDS.get())) {
                MobEffectInstance mobEffectInstance = living.getEffect(GoetyEffects.FLAME_HANDS.get());
                if (mobEffectInstance != null) {
                    int a = mobEffectInstance.getAmplifier() + 1;
                    victim.setSecondsOnFire(a * 4);
                }
            }
            if (living.hasEffect(GoetyEffects.VENOMOUS_HANDS.get())) {
                MobEffect effect = MobEffects.POISON;
                if (CuriosFinder.hasWildRobe(living)){
                    effect = GoetyEffects.ACID_VENOM.get();
                }
                MobEffectInstance mobEffectInstance = living.getEffect(GoetyEffects.VENOMOUS_HANDS.get());
                if (mobEffectInstance != null) {
                    int a = mobEffectInstance.getAmplifier();
                    victim.addEffect(new MobEffectInstance(effect, 200, a), living);
                }
            }
        }
        if (victim.hasEffect(GoetyEffects.REPULSIVE.get())) {
            MobEffectInstance mobEffectInstance = victim.getEffect(GoetyEffects.REPULSIVE.get());
            if (mobEffectInstance != null){
                int a = mobEffectInstance.getAmplifier();
                living.playSound(SoundEvents.IRON_GOLEM_ATTACK);
                if (!living.level.isClientSide){
                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(living.blockPosition(), SoundEvents.IRON_GOLEM_ATTACK, 1.0F, 1.0F));
                    MobUtil.knockBack(living, victim, 1.0D + (a / 2.0D), 0.4D + (a * 0.2D), 1.0D + (a / 2.0D));
                }
            }
        }
        if (living.hasEffect(GoetyEffects.ENCHANTED.get())) {
            finalAmount *= 1.25F;
        }
    }
    if (victim.hasEffect(GoetyEffects.SOUL_ARMOR.get())){
        MobEffectInstance mobEffectInstance = victim.getEffect(GoetyEffects.SOUL_ARMOR.get());
        if (mobEffectInstance != null){
            if (mobEffectInstance.getDuration() > MathHelper.secondsToTicks(event.getAmount())){
                EffectsUtil.decreaseDuration(victim, GoetyEffects.SOUL_ARMOR.get(), MathHelper.secondsToTicks(event.getAmount()), mobEffectInstance.isAmbient(), mobEffectInstance.isVisible());
            }
            if (victim instanceof Player player){
                SEHelper.decreaseSouls(player, (int) event.getAmount());
            }
        }
    }
    if (victim.hasEffect(GoetyEffects.EXPLOSIVE.get())) {
        MobEffectInstance mobEffectInstance = victim.getEffect(GoetyEffects.EXPLOSIVE.get());
        if (mobEffectInstance != null){
            int a = mobEffectInstance.getAmplifier() + 1;
            int max = Math.max(1, 5 - a);
            if (victim.getRandom().nextInt(max) == 0) {
                if (!victim.level.isClientSide) {
                    victim.level.explode(victim, victim.getX(), victim.getY(), victim.getZ(), 3.0F + (a / 2.0F), Level.ExplosionInteraction.BLOCK);
                    victim.removeEffect(GoetyEffects.EXPLOSIVE.get());
                }
            }
        }
    }
    if (victim.hasEffect(GoetyEffects.FLAMMABLE.get())){
        MobEffectInstance mobEffectInstance = victim.getEffect(GoetyEffects.FLAMMABLE.get());
        if (mobEffectInstance != null){
            int a = mobEffectInstance.getAmplifier() + 2;
            if (event.getSource().is(DamageTypeTags.IS_FIRE)) {
                event.setAmount(event.getAmount() * a);
            }
        }
    }
    if (victim.hasEffect(GoetyEffects.ENDER_FLUX.get())){
        MobEffectInstance mobEffectInstance = victim.getEffect(GoetyEffects.ENDER_FLUX.get());
        if (mobEffectInstance != null){
            int a = mobEffectInstance.getAmplifier();
            for(int i = 0; i < 64; ++i) {
                if (MobUtil.teleport(victim, 16, a)){
                    if (victim.getRandom().nextFloat() < 0.05F && victim.level.getGameRules().getBoolean(GameRules.RULE_DOMOBSPAWNING)) {
                        Endermite endermite = EntityType.ENDERMITE.create(victim.level);
                        if (endermite != null) {
                            endermite.moveTo(victim.getX(), victim.getY(), victim.getZ(), victim.getYRot(), victim.getXRot());
                            victim.level.addFreshEntity(endermite);
                        }
                    }
                    break;
                }
            }
        }
    }
    if (attacker instanceof LivingEntity attackerL && ModDamageSource.physicalAttacks(event.getSource())) {
        if (attackerL.hasEffect(GoetyEffects.SMITING.get())) {
            MobEffectInstance inst = attackerL.getEffect(GoetyEffects.SMITING.get());
            if (inst != null) {
                int amp = inst.getAmplifier() + 1;
                ItemStack weapon = attackerL.getMainHandItem();
                if (weapon.getEnchantmentLevel(Enchantments.SMITE) < amp) {
                    bonus += Enchantments.SMITE.getDamageBonus(amp, victim.getMobType(), weapon);
                }
            }
        }

        if (attackerL.hasEffect(GoetyEffects.INSECT_BANE.get())) {
            MobEffectInstance inst = attackerL.getEffect(GoetyEffects.INSECT_BANE.get());
            if (inst != null) {
                int amp = inst.getAmplifier() + 1;
                ItemStack weapon = attackerL.getMainHandItem();
                if (weapon.getEnchantmentLevel(Enchantments.BANE_OF_ARTHROPODS) < amp) {
                    bonus += Enchantments.BANE_OF_ARTHROPODS.getDamageBonus(amp, victim.getMobType(), weapon);
                }
            }
        }
    }
    if (bonus > 0.0F || finalAmount != event.getAmount()) {
        event.setAmount(finalAmount + bonus);
    }
}

public static void HurtEvent(LivingHurtEvent event){
    LivingEntity victim = event.getEntity();
    float finalDamage = event.getAmount();
    if (CuriosFinder.hasFrostRobes(victim)){
        if (ModDamageSource.freezeAttacks(event.getSource()) || event.getSource().is(DamageTypeTags.IS_FREEZING)){
            float resistance = 1.0F - (ItemConfig.FrostRobeResistance.get() / 100.0F);
            finalDamage *= resistance;
        }
    }
    if (CuriosFinder.hasAbyssRobes(victim)){
        if (event.getSource().is(DamageTypeTags.IS_DROWNING)){
            if (victim.getAirSupply() <= 0){
                victim.setAirSupply(50);
            }
            finalDamage *= 0.5F;
        }
    }
    if (CuriosFinder.hasNetherRobe(victim)){
        float resistance = 1.0F - (ItemConfig.NetherRobeResistance.get() / 100.0F);
        if (resistance <= 0.0F){
            event.setCanceled(true);
        } else {
            if (ModDamageSource.hellfireAttacks(event.getSource())){
                resistance = Math.max(0.75F, resistance);
                finalDamage *= resistance;
            } else if (event.getSource().is(DamageTypeTags.IS_FIRE) || ModDamageSource.isMagicFire(event.getSource())){
                finalDamage *= resistance;
            }
        }
    }
    if (CuriosFinder.hasCurio(victim, ModItems.GRAND_TURBAN.get())){
        if (victim instanceof Player player) {
            if (SEHelper.getSoulsAmount(player, ItemConfig.ItemsRepairAmount.get())) {
                int irks = victim.level.getEntitiesOfClass(AllyIrk.class, victim.getBoundingBox().inflate(32)).size();
                if ((victim.level.random.nextBoolean() || victim.getHealth() <= victim.getMaxHealth() / 2) && irks < 16) {
                    AllyIrk irk = new AllyIrk(ModEntityType.IRK_SERVANT.get(), victim.level);
                    irk.setPos(victim.getX(), victim.getY(), victim.getZ());
                    irk.setLimitedLife(MobUtil.getSummonLifespan(victim.level));
                    irk.setTrueOwner(victim);
                    if (victim.level.addFreshEntity(irk)) {
                        SEHelper.decreaseSouls(player, ItemConfig.ItemsRepairAmount.get());
                    }
                }
            }
        }
    }
    if (CuriosFinder.hasCurio(victim, ModItems.GRAND_ROBE.get())){
        if (MobUtil.isSpellCasting(victim)){
            finalDamage /= 2.0F;
        }
    }
    if(CuriosFinder.hasCurio(victim, ModItems.STORM_ROBE.get())){
        if (ModDamageSource.shockAttacks(event.getSource()) || event.getSource().is(DamageTypes.LIGHTNING_BOLT)){
            float resistance = 1.0F - (ItemConfig.StormRobeResistance.get() / 100.0F);
            finalDamage *= resistance;
        }
        if (event.getSource().is(DamageTypes.LIGHTNING_BOLT)){
            victim.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 300));
        }
    }
    if (CuriosFinder.hasWitchRobe(victim) || CuriosFinder.hasWarlockRobe(victim)){
        if (event.getSource().is(DamageTypeTags.WITCH_RESISTANT_TO)){
            if (!(LichdomHelper.isLich(victim) && MainConfig.LichMagicResist.get())){
                float resistance = 1.0F - (ItemConfig.WitchRobeResistance.get() / 100.0F);
                if (CuriosFinder.hasWarlockRobe(victim)){
                    resistance = 1.0F - (ItemConfig.WarlockRobeResistance.get() / 100.0F);
                }
                finalDamage *= resistance;
            }
        }
    }
    if (CuriosFinder.hasUnholyHat(victim)){
        if (victim.level.dimension() == Level.NETHER){
            finalDamage *= 1.0F - (ItemConfig.UnholyHatNetherResistance.get() / 100.0F);
        }
        if (!event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY)){
            finalDamage = Math.min(finalDamage, AttributesConfig.ApostleDamageCap.get().floatValue());
        }
    }
    if (finalDamage != event.getAmount()) {
        event.setAmount(finalDamage);
    }
}

public static void AttackEvent(LivingAttackEvent event){
    LivingEntity victim = event.getEntity();
    Entity attacker = event.getSource().getEntity();
    if (attacker instanceof IOwned owned){
        if (MobsConfig.ServantsMasterImmune.get()){
            if (owned.getTrueOwner() == victim){
                event.setCanceled(true);
            }
        }
        if (attacker instanceof Mob mob) {
            if (mob.getMainHandItem().getItem() instanceof AxeItem) {
                if (victim.getType().is(ModTags.EntityTypes.BIC_SHIELDED_MOBS)) {
                    MobEffect mobEffect = ForgeRegistries.MOB_EFFECTS.getValue(new ResourceLocation("born_in_chaos_v1", "block_break"));
                    if (mobEffect != null) {
                        victim.addEffect(new MobEffectInstance(mobEffect, 120, 0, false, false));
                        if (!victim.level.isClientSide()) {
                            victim.level.playSound(null, victim.getX(), victim.getY(), victim.getZ(), SoundEvents.ZOMBIE_BREAK_WOODEN_DOOR, SoundSource.NEUTRAL, 0.2F, 1.0F);
                        } else {
                            victim.level.playLocalSound(victim.getX(), victim.getY(), victim.getZ(), SoundEvents.ZOMBIE_BREAK_WOODEN_DOOR, SoundSource.NEUTRAL, 0.2F, 1.0F, false);
                        }

                        if (victim.level instanceof ServerLevel serverLevel) {
                            serverLevel.sendParticles(ParticleTypes.CRIT, victim.getX(), victim.getY(), victim.getZ(), 9, 0.6, 1.0, 0.6, 0.6);
                        }

                        if (victim.hasEffect(MobEffects.DAMAGE_RESISTANCE)) {
                            victim.removeEffect(MobEffects.DAMAGE_RESISTANCE);
                        }
                    }
                }
            }
        }
        if (owned.getMasterOwner() instanceof Player || attacker instanceof Player){
            if (attacker.level.getServer() != null) {
                if (!attacker.level.getServer().isPvpAllowed()) {
                    if (victim instanceof Player || (victim instanceof IOwned owned1 && owned1.getMasterOwner() instanceof Player)) {
                        event.setCanceled(true);
                    }
                }
            }
        }
    }
    if (MobsConfig.OwnerAttackCancel.get()){
        if (attacker != null) {
            if (victim instanceof IOwned owned) {
                if (owned.getTrueOwner() == attacker) {
                    event.setCanceled(true);
                }
            }
        }
    }
    if (attacker instanceof FrozenZombieServant){
        victim.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, MathHelper.secondsToTicks(3)));
    }
}

public static void onLivingDeathEvent(LivingDeathEvent event) {
    Entity killer = event.getSource().getEntity();
    Entity projectile = event.getSource().getDirectEntity();
    Entity killed = event.getEntity();

    if (killed instanceof LivingEntity victim){
        if (killer instanceof LivingEntity livingKiller) {
            Player player = null;
            boolean charmMob = killer instanceof ICharmUser charmUser && charmUser.getCharm().getItem() instanceof ISoulContainer;
            if (killer instanceof Player player1) {
                player = player1;
            } else {
                LivingEntity owner = MobUtil.getOwner(killer);
                if (MobUtil.getOwner(owner) instanceof Player player1) {
                    player = player1;
                } else if (owner instanceof Player playerEntity) {
                    player = playerEntity;
                }
            }
            if (player != null) {
                if (!(player instanceof FakePlayer)) {
                    if (projectile instanceof Fangs fangEntity && fangEntity.isTotemSpawned()) {
                        SEHelper.rawHandleKill(player, victim, fangEntity.getSoulEater(), event.getSource());
                    } else {
                        if (livingKiller instanceof Player || MobsConfig.ServantsAlwaysGiveSE.get() || CuriosFinder.hasDarkRobe(player) || CuriosFinder.hasUndeadSet(player) || ItemHelper.armorSet(player, ModArmorMaterials.BLACK_IRON) || ItemHelper.armorSet(player, ModArmorMaterials.DARK) || livingKiller instanceof RaiderServant || charmMob) {
                            SEHelper.handleKill(livingKiller, victim, event.getSource());
                        }
                    }
                }
            } else if (charmMob) {
                SEHelper.handleKill(livingKiller, victim, event.getSource());
            }
        }

        if (victim != killer && killer instanceof LivingEntity) {
            if (CuriosFinder.hasCurio(victim, itemStack -> itemStack.getItem() instanceof ITotem)) {
                ItemStack itemStack = CuriosFinder.findCurio(victim, itemStack1 -> itemStack1.getItem() instanceof ITotem);
                ITotem.increaseSouls(itemStack, SEHelper.getSoulGiven(victim) * 2);
            }
        }

        if (!(victim instanceof Player) || !MainConfig.TotemUndying.get()) {
            if (victim.getMainHandItem().getItem() instanceof ITotem){
                ItemStack itemStack = victim.getMainHandItem();
                if (revive(itemStack, victim)) {
                    event.setCanceled(true);
                }
            } else if (victim.getOffhandItem().getItem() instanceof ITotem) {
                ItemStack itemStack = victim.getOffhandItem();
                if (revive(itemStack, victim)) {
                    event.setCanceled(true);
                }
            }
        }
    }

    if (killed instanceof Player player){
        bindArcaCompass(killer, player);
        ISoulEnergy soulEnergy = SEHelper.getCapability(player);
        if (MainConfig.LichArcaRemove.get()) {
            if (!soulEnergy.getSEActive() || soulEnergy.getArcaBlock() == null) {
                if (LichdomHelper.isLich(player)) {
                    LichdomHelper.setLich(player, false);
                }
            }
        }
        if (killer instanceof Wight wight){
            if (wight.level instanceof ServerLevel serverLevel) {
                SEHelper.decreaseSoulsNoDiscount(player, 1000);
                float healAmount = 50.0F * (Math.min(0.0F, SEHelper.getSoulAmountInt(player)) / 1000.0F);
                wight.heal(healAmount);
                ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.SCULK_SOUL, wight);
            }
        }
        if (killer instanceof AbstractIllager){
            soulEnergy.setRestPeriod(soulEnergy.getRestPeriod() + MathHelper.minecraftDayToTicks(MobsConfig.IllagerAssaultRestDeath.get()));
        }
        if (soulEnergy.getSEActive()){
            if (soulEnergy.getArcaBlock() != null) {
                if (MainConfig.ArcaUndying.get() || (MainConfig.ArcaLichUndying.get() && LichdomHelper.isLich(player))) {
                    if (!player.level.isClientSide) {
                        if (LichdomHelper.isLich(player)) {
                            if (MainConfig.LichNoSERemove.get()){
                                if (soulEnergy.getSoulEnergy() >= MainConfig.MaxSouls.get()){
                                    SEHelper.teleportToArca(player);
                                    player.setHealth(1.0F);
                                    player.removeAllEffects();
                                    player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
                                    player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
                                    player.playSound(SoundEvents.WITHER_DEATH, 1.0F, 1.0F);
                                    ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.WITHER_DEATH, 1.0F, 1.0F));
                                    SEHelper.decreaseSoulsNoDiscount(player, MainConfig.MaxSouls.get());
                                    event.setCanceled(true);
                                } else {
                                    if (MainConfig.LichModeSounds.get()) {
                                        Vec3 vec3 = player.position();
                                        player.level.playSound(null, vec3.x, vec3.y, vec3.z, ModSounds.LICH_DEATH.get(), player.getSoundSource(), 1.0F, player.getVoicePitch());
                                    }
                                    if (player.level instanceof ServerLevel serverLevel){
                                        ColorUtil colorUtil = new ColorUtil(0x36e416);
                                        serverLevel.sendParticles(new LichShockwaveParticleOption(colorUtil, 40, 20, 1, 100), player.getX(), player.getY() + 0.5F, player.getZ(), 0, 0, 0, 0, 0.5F);
                                    }
                                    if (LichdomHelper.isLich(player)) {
                                        LichdomHelper.setLich(player, false);
                                    }
                                }
                            } else {
                                SEHelper.teleportToArca(player);
                                player.setHealth(1.0F);
                                player.removeAllEffects();
                                if (soulEnergy.getSoulEnergy() >= MainConfig.MaxSouls.get()) {
                                    player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
                                    player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
                                } else {
                                    player.addEffect(new MobEffectInstance(GoetyEffects.SOUL_HUNGER.get(), MathHelper.minutesToTicks(2), 4, false, false));
                                }
                                player.playSound(SoundEvents.WITHER_DEATH, 1.0F, 1.0F);
                                ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.WITHER_DEATH, 1.0F, 1.0F));
                                SEHelper.decreaseSoulsNoDiscount(player, MainConfig.MaxSouls.get());
                                event.setCanceled(true);
                            }
                        } else if (soulEnergy.getSoulEnergy() >= MainConfig.MaxSouls.get()) {
                            SEHelper.teleportToArca(player);
                            player.setHealth(1.0F);
                            player.removeAllEffects();
                            player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
                            player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
                            player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
                            player.playSound(SoundEvents.WITHER_DEATH, 1.0F, 1.0F);
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.WITHER_DEATH, 1.0F, 1.0F));
                            SEHelper.decreaseSoulsNoDiscount(player, MainConfig.MaxSouls.get());
                            event.setCanceled(true);
                        }
                    }
                }
            }
        } else if (ITotem.UndyingEffect(player)){
            if (!player.level.isClientSide) {
                player.setHealth(1.0F);
                player.removeAllEffects();
                player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
                player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
                player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
                ModNetwork.sendTo(player, new TotemDeathPacket(player.getUUID()));
                SEHelper.sendSoulChange(player, -ITotem.currentSouls(TotemFinder.FindTotem(player)));
                ITotem.setSoulsAmount(TotemFinder.FindTotem(player), 0);
            }
            event.setCanceled(true);
        }
    }

}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    double potency = spellStat.getPotency();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster) / 2.0D;
    }
    if (this.victim != null){
        try {
            Vec3 vec3 = this.victim.getDeltaMovement();
            Vec3 force = (caster.getLookAngle()
                    .normalize()
                    .scale(Math.max(caster.distanceTo(this.victim), 4))
                    .add(caster.position())
                    .subtract(this.victim.position()))
                    .scale(potency);
            if (force.y > 0) {
                this.victim.resetFallDistance();
            }
            Vec3 newMotion = force.subtract(vec3).scale(0.25).add(vec3);
            Vec3 delta = newMotion.subtract(vec3);
            Vec3 clampedMotion = new Vec3(signedMin(delta.x, force.x * 4), signedMin(delta.y, force.y * 4), signedMin(delta.z, force.z * 4));
            MobUtil.push(this.victim, clampedMotion, 0.25D);
            Vec3 old = new Vec3(this.victim.xOld, this.victim.yOld, this.victim.zOld);
            Vec3 travel = this.victim.position().subtract(old);
            if (this.victim.horizontalCollision && this.victim instanceof LivingEntity livingTarget) {
                double d11 = livingTarget.getDeltaMovement().horizontalDistance();
                float f1 = (float) (d11 * 10.0D - 3.0D);
                int airborne = (int) travel.horizontalDistanceSqr() / 2;
                if (f1 >= 1.0F) {
                    if (livingTarget.hurt(livingTarget.damageSources().flyIntoWall(), 4.0F + (airborne + 1) * 0.5F)) {
                        livingTarget.playSound(livingTarget.getFallSounds().big(), 2.0F, 1.0F);
                    }
                }
            }
            if (CuriosFinder.hasCurio(caster, ModItems.RING_OF_FORCE.get())){
                this.victim.setAirSupply(Math.max(-20, this.victim.getAirSupply() - 10));
                if (this.victim.getAirSupply() <= -20){
                    this.victim.setAirSupply(0);
                    this.victim.hurt(ModDamageSource.choke(caster, caster), 2.0F);
                }
            }
            ServerParticleUtil.addParticlesAroundMiddleSelf(worldIn, ParticleTypes.PORTAL, this.victim);
        } catch (NullPointerException exception) {
            caster.stopUsingItem();
        }
    } else {
        this.findVictim(worldIn, caster, spellStat);
    }
}

public void tick() {
	LivingEntity target = this.boss.getTarget();
	if (target != null) {
		this.boss.lookAt(target, 10.0F, 500.0F);

		if (target.isAlive()) {
			float f1 = target.distanceTo(this.boss);

			if (this.boss.getSensing().hasLineOfSight(target)) {
				if (attackTime-- <= 0 && f1 < 2.0F && target.getBoundingBox().maxY > this.boss.getBoundingBox().minY && this.boss.getTarget().getBoundingBox().minY < this.boss.getBoundingBox().maxY) {
					attackTime = 20;
					this.boss.doHurtTarget(getServerLevel(target), target);
				}
			}

			if (this.boss.getOffhandItem().getItem() instanceof ShieldItem && this.boss.getCurrentFormation() != KnightPhantom.Formation.ATTACK_PLAYER_ATTACK && this.isGuard) {
				this.boss.startUsingItem(InteractionHand.OFF_HAND);
			} else {
				this.boss.stopUsingItem();
			}

			if (this.isGuard) {
				if (this.guardCoolDownTime <= 180) {
					++this.guardCoolDownTime;
				} else {
					this.isGuard = false;
				}
			} else {
				if (this.guardCoolDownTime > 0) {
					--this.guardCoolDownTime;
				} else {
					this.isGuard = true;
				}
			}
		}
	}
}

public void aiStep() {
    super.aiStep();
    if(!this.level.isClientSide) {
        if(this.isAlive() && this.isEffectiveAi()) {
            ItemStack itemstack = this.getItemBySlot(EquipmentSlot.MAINHAND);
            if(itemstack.getItem().isEdible() && this.getTarget() == null) {
                ++this.eatTicks;
                if(this.eatTicks > 200) {
                    if(itemstack.getItem() == Items.BREAD) {
                        this.addEffect(new MobEffectInstance(MobEffects.POISON, 900));
                    }
                    ItemStack itemstack1 = itemstack.finishUsingItem(this.level, this);

                    if(!itemstack1.isEmpty()) {
                        this.setItemSlot(EquipmentSlot.MAINHAND, itemstack1);
                    }
                    this.eatTicks = 0;
                } else if(this.eatTicks > 160 && this.random.nextFloat() < 0.1F) {
                    this.playSound(this.getEatingSound(itemstack), 1.0F, 1.0F);
                    this.level.broadcastEntityEvent(this, (byte) 45); // calls handleStatusUpdate((byte) 45);
                }
            }
        }
        if(!this.isBaby() && ModEventBus.LayEggTickEvent.emit(this) && --this.timeUntilNextEgg <= 0) {
            this.playSound(SoundEvents.CHICKEN_EGG, 1.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            this.spawnAtLocation(this.getRandom().nextInt(128) == 0 ? ModItems.GOLDEN_GOOSE_EGG.get() : ModItems.GOOSE_EGG.get(), 1);
            this.timeUntilNextEgg = this.random.nextInt(6000) + 6000;
        }
    }
}

public void tick() {
   LivingEntity livingentity = this.mob.getTarget();
   if (livingentity != null) {
      this.mob.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
      double d0 = this.mob.getPerceivedTargetDistanceSquareForMeleeAttack(livingentity);
      this.ticksUntilNextPathRecalculation = Math.max(this.ticksUntilNextPathRecalculation - 1, 0);

      if(!isShieldDisabled(mob) && mob.getOffhandItem().canPerformAction(net.minecraftforge.common.ToolActions.SHIELD_BLOCK) &&  this.mob.getRandom().nextInt(6) == 0){
         this.mob.startUsingItem(InteractionHand.OFF_HAND);
      }

      if ((this.followingTargetEvenIfNotSeen || this.mob.getSensing().hasLineOfSight(livingentity)) && this.ticksUntilNextPathRecalculation <= 0 && (this.pathedTargetX == 0.0D && this.pathedTargetY == 0.0D && this.pathedTargetZ == 0.0D || livingentity.distanceToSqr(this.pathedTargetX, this.pathedTargetY, this.pathedTargetZ) >= 1.0D || this.mob.getRandom().nextFloat() < 0.05F)) {
         this.pathedTargetX = livingentity.getX();
         this.pathedTargetY = livingentity.getY();
         this.pathedTargetZ = livingentity.getZ();
         this.ticksUntilNextPathRecalculation = 4 + this.mob.getRandom().nextInt(7);
      if (this.canPenalize) {
         this.ticksUntilNextPathRecalculation += failedPathFindingPenalty;
         if (this.mob.getNavigation().getPath() != null) {
            net.minecraft.world.level.pathfinder.Node finalPathPoint = this.mob.getNavigation().getPath().getEndNode();
            if (finalPathPoint != null && livingentity.distanceToSqr(finalPathPoint.x, finalPathPoint.y, finalPathPoint.z) < 1)
               failedPathFindingPenalty = 0;
            else
               failedPathFindingPenalty += 10;
         } else {
            failedPathFindingPenalty += 10;
         }
      }
         if (d0 > 1024.0D) {
            this.ticksUntilNextPathRecalculation += 10;
         } else if (d0 > 256.0D) {
            this.ticksUntilNextPathRecalculation += 5;
         }

         if (!this.mob.getNavigation().moveTo(livingentity, this.speedModifier)) {
            this.ticksUntilNextPathRecalculation += 15;
         }

         this.ticksUntilNextPathRecalculation = this.adjustedTickDelay(this.ticksUntilNextPathRecalculation);
      }

      this.ticksUntilNextAttack = Math.max(this.ticksUntilNextAttack - 1, 0);
      this.checkAndPerformAttack(livingentity, d0);
   }
}

public void aiStep() {
    if (this.isPregnant()) {
        if (this.random.nextInt(3000) == 0) {
            if (!this.level.isClientSide) {
                ServerLevel level = (ServerLevel) this.level;
                this.setPregnant(false);
                Penguin penguin = ModEntityTypes.PENGUIN.get().create(level);
                penguin.setBaby(true);
                penguin.moveTo(this.getX(), this.getY(), this.getZ(), 0.0F, 0.0F);
                level.addFreshEntityWithPassengers(penguin);
                level.broadcastEntityEvent(this, (byte) 18);
            }
        }
    }
    if (level.getGameTime() % 80L == 0L) {
        if (this.level.getEntitiesOfClass(Penguin.class, this.getBoundingBox().inflate(20.0D)).size() > 4) {
            for (Player player : this.level.getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(10.0D))) {
                player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 100, 0, true, true));
            }
        }
    }
    if (!this.level.isClientSide && this.isAlive() && this.isEffectiveAi()) {
        ++this.ticksSinceEaten;
        ItemStack stack = this.getItemBySlot(EquipmentSlot.MAINHAND);
        if (this.canEat(stack)) {
            if (this.ticksSinceEaten > 600) {
                ItemStack finishedStack = stack.finishUsingItem(this.level, this);
                if (!finishedStack.isEmpty()) {
                    this.setItemSlot(EquipmentSlot.MAINHAND, finishedStack);
                }
                this.ticksSinceEaten = 0;
            } else if (this.ticksSinceEaten > 560 && this.random.nextFloat() < 0.1f) {
                this.playSound(this.getEatingSound(stack), 1.0f, 1.0f);
                this.level.broadcastEntityEvent(this, (byte)45);
            }
        }
    }
    super.aiStep();
}

public void onHitEntity(EntityHitResult result) {
	super.onHitEntity(result);
	Entity entity = result.getEntity();
	if (entity instanceof LivingEntity livingEntity) {
		livingEntity.hurt(this.damageSources().thrown(this, this.getOwner()), 0);
		livingEntity.addEffect(new MobEffectInstance(PFEffects.GINKGO_SPLATTERED.get(), 150, 0, false, false, false));
	}
	this.discard();
}

public void eatSnack() {
	ItemStack itemstack = this.getMainHandItem();

	if (Ingredient.of(AutumnityItemTags.SNAIL_GLOW_SNACKS).test(itemstack)) {
		this.addEffect(new MobEffectInstance(MobEffects.GLOWING, 200, 0));
	}
	if (Ingredient.of(AutumnityItemTags.SNAIL_SPEED_SNACKS).test(itemstack)) {
		this.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 320, 2));
	}

	Item item = itemstack.getItem();
	ItemStack itemstack1 = itemstack.finishUsingItem(this.level(), this);
	if (!itemstack1.isEmpty()) {
		if (itemstack1.getItem() != item) {
			this.setItemSlot(EquipmentSlot.MAINHAND, itemstack1);
			this.spitOutItem();
		} else {
			this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
		}
	}

	this.setGooAmount(4);
}

protected void pickUpItem(ItemEntity itemEntity) {
	ItemStack stack = itemEntity.getItem();
	if (!this.isDoingAction(ChimpanzeeAction.LOOKING_AT_ITEM, ChimpanzeeAction.PLAYING_WITH_ITEM) && this.canHoldItem(stack)) {
		int i = stack.getCount();
		if (i > 1) {
			ItemEntity itementity = new ItemEntity(this.level(), this.getX(), this.getY(), this.getZ(), stack.split(i - 1));
			this.level().addFreshEntity(itementity);
		}

		this.dropItem(this.getMainHandItem());

		this.onItemPickup(itemEntity);
		this.setItemSlot(EquipmentSlot.MAINHAND, stack.split(1));
		this.handDropChances[EquipmentSlot.MAINHAND.getIndex()] = 2.0F;
		this.take(itemEntity, stack.getCount());
		itemEntity.discard();

		if (this.isSnack(stack)) {
			this.stopBeingAngry();
		}
	}

	AttributeInstance damageMod = this.getAttribute(Attributes.ATTACK_DAMAGE);
	damageMod.removeModifier(ATTACK_WEAPON_MODIFIER.id());
	if (this.isChimpanzeeWeapon(this.getMainHandItem())) {
		damageMod.addTransientModifier(ATTACK_WEAPON_MODIFIER);
	}
}

public void saveToBucketTag(ItemStack stack) {
	super.saveToBucketTag(stack);
	CustomData.update(DataComponents.BUCKET_ENTITY_DATA, stack, tag -> {
		this.getVariant().unwrapKey().ifPresent(variant -> tag.putString("BucketVariantTag", variant.location().toString()));
		tag.putInt("EatingLootDropCooldown", this.dropEatingLootCooldown);
		tag.putBoolean("ShouldDropItem", this.shouldDropItem());
		tag.putBoolean("IsLit", this.isLit());

		CompoundTag heldItemTag = new CompoundTag();
		if (!this.getItemBySlot(EquipmentSlot.MAINHAND).isEmpty()) {
			this.getItemBySlot(EquipmentSlot.MAINHAND).save(this.level().registryAccess(), heldItemTag);
		}
		tag.put("PikeHeldItem", heldItemTag);
	});
}

public void handleIncomingDamage(LivingEntity entity, EnumSet<Piece> equippedPieces, LivingIncomingDamageEvent ev) {
	if (!equippedPieces.contains(Piece.FULL_SET))
		ev.addReductionModifier(DamageContainer.Reduction.ARMOR, (container, reduction) -> DamageUtil.percentDamageReduction(container, reduction, equippedPieces.size() * 0.2f));
}

