	if (equippedPieces.contains(Piece.FULL_SET) && !DamageUtil.isEnvironmentalDamage(ev.getContainer().getSource()) && ev.getContainer().getNewDamage() >= entity.getHealth() && (!(entity instanceof Player pl) || !isOnCooldown(pl))) {
		ev.getContainer().setNewDamage(0);
		entity.hurtArmor(entity.level().damageSources().generic(), 2000);

		if (entity.getHealth() < 4)
			entity.setHealth(4);

		if (entity instanceof ServerPlayer pl)
			setArmourCooldown(pl, AoAArmour.NECRO_ARMOUR, 72000);

		ParticleBuilder.forRandomPosInEntity(ParticleTypes.HEART, entity)
				.spawnNTimes(5)
				.sendToAllPlayersTrackingEntity(entity);
	}
}

public boolean releaseFamiliar(Player player, Level level, IFamiliar familiar) {
    if (familiar == null || familiar.getFamiliarEntity().isAddedToLevel())
        return false;

    var output = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, level.registryAccess());
    familiar.getFamiliarEntity().saveAsPassenger(output);
    EntityType.loadEntityRecursive(output.buildResult(), level, EntitySpawnReason.LOAD, e -> {
        e.setPos(player.getX(), player.getY(), player.getZ());
        ((IFamiliar) e).setFamiliarOwner(player);
        level.addFreshEntity(e);

        return e;
    });

    this.clearFamiliar(level, familiar, level.registryAccess());
    return true;
}

public Multimap<Attribute, AttributeModifier> getAttributeModifiers(SlotContext slotContext, UUID uuid, ItemStack stack) {
    Multimap<Attribute, AttributeModifier> modifiers = LinkedHashMultimap.create();

    if (slotContext.identifier().equals(this.attributeSlot) && this.attributes != null) {
        modifiers.putAll(this.attributes.apply(slotContext.index()));
    }
    if (!this.slotModifiers.isEmpty()) {
        this.slotModifiers.forEach((slotId, amount) -> {
            CuriosApi.addSlotModifier(modifiers, slotId, uuid, amount, AttributeModifier.Operation.ADDITION);
        });
    }

    CurioAttributeModifierEvent evt = new CurioAttributeModifierEvent(stack, slotContext, uuid, modifiers);
    MinecraftForge.EVENT_BUS.post(evt);

    return modifiers;
}

public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
    Player player = commonArmorHandler.getPlayer();
    AttributeInstance attributeInstance = player.getAttribute(getModifiedAttribute());
    if (attributeInstance != null) {
        AttributeModifier currentModifier = attributeInstance.getModifier(getModifierId());
        double newValue = enabled && commonArmorHandler.hasMinPressure(getEquipmentSlot()) && isAttributeModifierApplicable(commonArmorHandler) ?
                getModifiedAttributeValue(commonArmorHandler) : 0f;
        if (currentModifier != null) {
            if (Math.abs(currentModifier.amount() - newValue) < Mth.EPSILON) {
                return;  // already good
            }
            attributeInstance.removeModifier(currentModifier.id());
        }
        if (newValue > 0) {
            attributeInstance.addTransientModifier(new AttributeModifier(getModifierId(), newValue, getModifierOperation()));
        }
    }
}

private static boolean loadProjectile(LivingEntity shooter, ItemStack crossbow, ItemStack arrow, boolean hasArrow, boolean creative) {
    if (arrow.isEmpty()) {
        return false;
    } else {
        boolean flag = creative && arrow.getItem() instanceof ArrowItem;
        ItemStack itemstack;
        if (!flag && !creative && !hasArrow) {
            itemstack = arrow.split(1);
            if (arrow.isEmpty() && shooter instanceof Player player) {
                player.getInventory().removeItem(arrow);
            }
        } else {
            itemstack = arrow.copy();
        }

        addChargedProjectile(crossbow, itemstack);
        return true;
    }
}

