private void removeSlot(EquipmentSlot slotType) {
  int index = slotType.getFilterFlag();
  totalLevel -= levels[index];
  levels[index] = 0;
  // prioritize armor slots
  for (EquipmentSlot armorSlot : ModifiableArmorMaterial.ARMOR_SLOTS) {
    if (levels[armorSlot.getFilterFlag()] > 0) {
      inCharge = armorSlot;
      return;
    }
  }
  // if none, find a hand slot
  for (EquipmentSlot hand : InteractionHandler.HAND_SLOTS) {
    if (levels[hand.getFilterFlag()] > 0) {
      inCharge = hand;
      return;
    }
  }
  inCharge = null;
}

private Supplier<ItemAttributeModifiers> createAttributes(Holder<ArmorMaterial> material, ArmorItem.Type slot) {
	return Suppliers.memoize(() -> {
		final int armourValue = material.value().getDefense(slot);
		final float toughness = material.value().toughness();
		final float knockbackResistance = material.value().knockbackResistance();
		final ItemAttributeModifiers.Builder builder = ItemAttributeModifiers.builder();
		final EquipmentSlotGroup slotGroup = EquipmentSlotGroup.bySlot(slot.getSlot());
		final ResourceLocation attributeId = ResourceLocation.withDefaultNamespace("armor." + slot.getName());

		builder.add(Attributes.ARMOR, new AttributeModifier(attributeId, armourValue, AttributeModifier.Operation.ADD_VALUE), slotGroup);
		builder.add(Attributes.ARMOR_TOUGHNESS, new AttributeModifier(attributeId, toughness, AttributeModifier.Operation.ADD_VALUE), slotGroup);

		addArmourAttributes(slotGroup, (attribute, modifier) -> builder.add(attribute, modifier, slotGroup));

		if (knockbackResistance > 0)
			builder.add(Attributes.KNOCKBACK_RESISTANCE, new AttributeModifier(attributeId, knockbackResistance, AttributeModifier.Operation.ADD_VALUE), slotGroup);

		return builder.build();
	});
}

public static void onLivingSetAttackTargetEvent(LivingSetAttackTargetEvent event){
	// Undo the mob detection penalty for wearing armour when invisible
	// Only bother doing this for players because the penalty only applies to them
	if(event.getTarget() instanceof EntityPlayer && event.getEntityLiving() instanceof EntityLiving
			&& event.getEntityLiving().isInvisible()){

		int armourPieces = (int)Streams.stream(event.getTarget().getArmorInventoryList())
				.filter(s -> !s.isEmpty() && !(s.getItem() instanceof ItemWizardArmour))
				.count();

		if(armourPieces == 0) return;

		// Repeat the calculation from EntityAIFindNearestPlayer, but ignoring wizard armour
		IAttributeInstance attribute = event.getEntityLiving().getEntityAttribute(SharedMonsterAttributes.FOLLOW_RANGE);
		double followRange = attribute == null ? 16 : attribute.getAttributeValue();
		if(event.getTarget().isSneaking()) followRange *= 0.8;
		float f = (float)armourPieces / ((EntityPlayer)event.getTarget()).inventory.armorInventory.size();
		if(f < 0.1F) f = 0.1F;
		followRange *= 0.7F * f;
		// Don't need to worry about the isSuitableTarget check since it must already have been checked to get this far
		if(event.getTarget().getDistance(event.getEntity()) > followRange) ((EntityLiving)event.getEntityLiving()).setAttackTarget(null);
	}
}

public void setActiveEquipmentSets(List<EquipmentSet.Result> results) {
    /// Remove attribute bonuses of previous sets from player
    var player = (PlayerEntity) (Object) this;
    AttributeContainer attributeContainer = player.getAttributes();
    for(var bonus: EquipmentSet.attributesFrom(activeEquipmentSets)) {
        for (var modifier: bonus.modifiers()) {
            EntityAttributeInstance entityAttributeInstance = attributeContainer.getCustomInstance(modifier.attribute());
            if (entityAttributeInstance != null) {
                entityAttributeInstance.removeModifier(modifier.modifier());
            }
        }
    }
    this.activeEquipmentSets = results;
    /// Add attribute bonuses of new sets to player
    for(var bonus: EquipmentSet.attributesFrom(activeEquipmentSets)) {
        for (var modifier: bonus.modifiers()) {
            EntityAttributeInstance entityAttributeInstance = attributeContainer.getCustomInstance(modifier.attribute());
            if (entityAttributeInstance != null) {
                entityAttributeInstance.removeModifier(modifier.modifier().id());
                entityAttributeInstance.addTemporaryModifier(modifier.modifier());
            }
        }
    }
}

public static void travellersTrySwapHotbar(Player player) {
	ItemStack legArmor = player.getInventory().getItem(EquipmentSlot.LEGS.getIndex(Inventory.INVENTORY_SIZE));
	ItemContainerContents containerContents = legArmor.get(DataComponents.CONTAINER);
	if (!hasSwapHotbar(player, legArmor) || containerContents == null)
		return;

	NonNullList<ItemStack> hotbarStacks = NonNullList.withSize(9, ItemStack.EMPTY);
	Inventory inventory = player.getInventory();
	boolean isSwapHotbarActive = isSwapHotbarActive(player, legArmor);
	boolean hasChanged = false;
	for (int slotIndex = 0; slotIndex < 9; slotIndex++) {
		ItemStack inventoryStack = inventory.getItem(slotIndex);
		ItemStack beltStack = containerContents.getSlots() <= slotIndex ? ItemStack.EMPTY : containerContents.getStackInSlot(slotIndex);
		if (inventoryStack.canFitInsideContainerItems() && !inventoryStack.is(TFItemTags.TRAVELLERS_BELT_BLACKLISTED) && (isSwapHotbarActive || inventoryStack.isEmpty())) {
			hotbarStacks.set(slotIndex, inventoryStack);
			inventory.setItem(slotIndex, beltStack);
			if (!beltStack.equals(inventoryStack))
				hasChanged = true;
		} else {
			hotbarStacks.set(slotIndex, beltStack);  // keep the same item in belt inventory
		}
	}
	legArmor.set(DataComponents.CONTAINER, ItemContainerContents.fromItems(hotbarStacks));
	if (hasChanged)
		player.level().playSound(null, player, TFSounds.SWAP_HOTBAR.get(), SoundSource.PLAYERS, 1F, 1F);
}

public Multimap<Attribute, AttributeModifier> getDefaultAttributeModifiers(EquipmentSlot equipmentSlot) {
    if (getMaterial() == AMItemRegistry.CROCODILE_ARMOR_MATERIAL && equipmentSlot == this.type.getSlot()) {
        if (attributeMapCroc == null) {
            buildCrocAttributes(AMItemRegistry.CROCODILE_ARMOR_MATERIAL);
        }
        return attributeMapCroc;
    }
    if (getMaterial() == AMItemRegistry.MOOSE_ARMOR_MATERIAL && equipmentSlot == this.type.getSlot()) {
        if (attributeMapMoose == null) {
            buildMooseAttributes(AMItemRegistry.MOOSE_ARMOR_MATERIAL);
        }
        return attributeMapMoose;
    }
    if (getMaterial() == AMItemRegistry.FLYING_FISH_MATERIAL && equipmentSlot == this.type.getSlot()) {
        if (attributeMapFlyingFish == null) {
            buildFlyingFishAttributes(AMItemRegistry.FLYING_FISH_MATERIAL);
        }
        return attributeMapFlyingFish;
    }
    if (getMaterial() == AMItemRegistry.KIMONO_MATERIAL && equipmentSlot == this.type.getSlot()) {
        if (attributeMapKimono == null) {
            buildKimonoAttributes(AMItemRegistry.KIMONO_MATERIAL);
        }
        return attributeMapKimono;
    }
    return super.getDefaultAttributeModifiers(equipmentSlot);
}

public static void handleAbility(LivingIncomingDamageEvent event) {
    var RING = ((BetrayerSignetRingItem) ItemRegistry.SIGNET_OF_THE_BETRAYER.get());
    if (event.getSource().getEntity() instanceof ServerPlayer attackingPlayer) {
        if (RING.isEquippedBy(attackingPlayer)) {
            var victim = event.getEntity();
            var victimMaxMana = victim.getAttributeValue(AttributeRegistry.MAX_MANA);
            var victimBaseMana = victim.getAttributeBaseValue(AttributeRegistry.MAX_MANA);
            if (victimMaxMana > victimBaseMana && RING.tryProcCooldown(attackingPlayer)) {
                /*
                If a victim's mana is above the base mana, they are considering a mage
                Therefore, we do extra damage based on the following (informal) formula:
                    - Σ(10 - n)% for n steps of 100 mana above base
                    - ie, 10% for the first 100, 9% for the second 100, 8% for the third 100, etc
                 */
                var manaAboveBase = victimMaxMana - victimBaseMana;
                double conversionRatioPer100 = 0.10;
                double totalExtraDamagePercent = 0;
                while (manaAboveBase > 0 && conversionRatioPer100 > 0) {
                    var step = Math.clamp(manaAboveBase, 0, 100) * .01;
                    totalExtraDamagePercent += step * conversionRatioPer100;
                    manaAboveBase -= 100;
                    conversionRatioPer100 -= 0.01;
                }
                event.setAmount((float) (event.getAmount() * Math.max(1, 1 + totalExtraDamagePercent)));
            }
        }
    }
}

public static void mobsMayLoseTargetWhenItIsWearingCardboard(EntityTickEvent.Pre event) {
	if (!(event.getEntity() instanceof LivingEntity entity))
		return;

	if (entity.tickCount % 16 != 0)
		return;
	if (!(entity instanceof Mob mob))
		return;

	if (testForStealth(mob.getTarget())) {
		mob.setTarget(null);
		if (mob.targetSelector != null)
			for (WrappedGoal goal : mob.targetSelector.getAvailableGoals()) {
				if (goal.isRunning() && goal.getGoal() instanceof TargetGoal tg)
					tg.stop();
			}
	}

	if (entity instanceof NeutralMob nMob && entity.level() instanceof ServerLevel sl) {
		UUID uuid = nMob.getPersistentAngerTarget();
		if (uuid != null && testForStealth(sl.getEntity(uuid)))
			nMob.stopBeingAngry();
	}

	if (testForStealth(mob.getLastHurtByMob())) {
		mob.setLastHurtByMob(null);
		mob.setLastHurtByPlayer(null);
	}
}

public void setJetBootsActive(ICommonArmorHandler commonArmorHandler, boolean newActive) {
    Player player = commonArmorHandler.getPlayer();
    JetBootsStateTracker.JetBootsState jbs = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
    JetBootsLocalState jbLocal = commonArmorHandler.getExtensionData(this);

    if (!newActive) {
        jbLocal.resetActive();
        if (jbLocal.isFlightStabilizers() && jbs.isActive() && !jbs.isBuilderMode()) {
            if (!player.level().isClientSide) {
                double l = Math.pow(player.getDeltaMovement().length(), 1.65);
                commonArmorHandler.addAir(EquipmentSlot.FEET, (int) (l * -50));
                NetworkHandler.sendToAllTracking(new PacketSpawnParticle(AirParticleData.DENSE,
                        player.position().toVector3f(),
                        PneumaticCraftUtils.VEC3F_ZERO,
                        (int) (l * 2),
                        Optional.empty()
                ), player.level(), player.blockPosition());
            }
            player.setDeltaMovement(Vec3.ZERO);
        }
    }

    if (jbLocal.isSmartHover()) {
        jbLocal.setHovering(true);
    }

    JetBootsStateTracker.getTracker(player).setJetBootsState(player, jbs.isEnabled(), newActive, jbs.isBuilderMode());
    player.setForcedPose(newActive && !jbs.isBuilderMode() ? Pose.FALL_FLYING : null);
}

public void tickArmorPiece(EquipmentSlot slot) {
    ItemStack armorStack = player.getItemBySlot(slot);
    boolean armorActive = false;
    if (armorStack.getItem() instanceof PneumaticArmorItem) {
        airHandlers.set(slot.getIndex(), armorStack.getCapability(PNCCapabilities.AIR_HANDLER_ITEM));
        if (ticksSinceEquip[slot.getIndex()] == 0) {
            initArmorInventory(slot);
        }
        ticksSinceEquip[slot.getIndex()]++;
        if (isArmorEnabled() && getArmorPressure(slot) > 0F) {
            armorActive = true;
            if (!player.level().isClientSide && isArmorReady(slot) && !player.isCreative()) {
                // use up air in the armor piece
                float airUsage = getIdleAirUsage(slot, false);
                if (airUsage != 0) {
                    addAir(slot, (int) -airUsage);
                }
            }
            doArmorActions(slot);
        }
    } else {
        airHandlers.set(slot.getIndex(), null);
    }
    if (!armorActive) {
        if (ticksSinceEquip[slot.getIndex()] > 1) {
            onArmorRemoved(slot);
        }
        ticksSinceEquip[slot.getIndex()] = 0;
    }
}

public Multimap<Attribute,AttributeModifier> getAttributeModifiers(IToolStackView tool, EquipmentSlot slot) {
  if (slot != getEquipmentSlot()) {
    return ImmutableMultimap.of();
  }

  ImmutableMultimap.Builder<Attribute, AttributeModifier> builder = ImmutableMultimap.builder();
  if (!tool.isBroken()) {
    // base stats
    StatsNBT statsNBT = tool.getStats();
    UUID uuid = ARMOR_MODIFIER_UUID_PER_TYPE.get(type);
    float armor = statsNBT.get(ToolStats.ARMOR);
    if (armor > 0) {
      builder.put(Attributes.ARMOR, new AttributeModifier(uuid, "tconstruct.armor.armor", armor, AttributeModifier.Operation.ADDITION));
    }
    float toughness = statsNBT.get(ToolStats.ARMOR_TOUGHNESS);
    if (toughness > 0) {
      builder.put(Attributes.ARMOR_TOUGHNESS, new AttributeModifier(uuid, "tconstruct.armor.toughness", toughness, AttributeModifier.Operation.ADDITION));
    }
    double knockbackResistance = statsNBT.get(ToolStats.KNOCKBACK_RESISTANCE);
    if (knockbackResistance > 0) {
      builder.put(Attributes.KNOCKBACK_RESISTANCE, new AttributeModifier(uuid, "tconstruct.armor.knockback_resistance", knockbackResistance, AttributeModifier.Operation.ADDITION));
    }
    // grab attributes from modifiers
    BiConsumer<Attribute,AttributeModifier> attributeConsumer = builder::put;
    for (ModifierEntry entry : tool.getModifierList()) {
      entry.getHook(ModifierHooks.ATTRIBUTES).addAttributes(tool, entry, slot, attributeConsumer);
    }
  }

  return builder.build();
}

public boolean overrideStackedOnOther(ItemStack stack, Slot slot, ClickAction action, Player player) {
  // stacking a crystal on a tool attempts to add it when in creative
  // see also - modifier adding command

  // must be op or in creative, right-clicking onto a modifiable slot
  if (action == ClickAction.SECONDARY && slot.allowModification(player) && CreativeSlotItem.canApply(player)) {
    ModifierId modifier = getModifier(stack);
    ItemStack toolItem = slot.getItem();
    // slot must have a tool, NBT must be valid
    if (modifier != null && !toolItem.isEmpty() && toolItem.is(TinkerTags.Items.MODIFIABLE)) {
      if (!player.level().isClientSide || (player.isCreative() && player.containerMenu.menuType == null)) {
        ToolStack tool = ToolStack.copyFrom(toolItem);

        // add modifier
        tool.addModifier(modifier, stack.getCount());

        // ensure no modifier problems after adding
        Component toolValidation = tool.tryValidate();
        if (toolValidation != null) {
          player.displayClientMessage(toolValidation, false);
        } else {
          tool.updateStack(toolItem);
          FluidTransferHelper.playUISound(player, SoundEvents.ENCHANTMENT_TABLE_USE);
        }
      }
      return true;
    }
    return false;
  }
  return false;
}

public static void applyEffect(Level world, double x, double y, double z) {
	int range = 8;
	List<ThrowableProjectile> entities = world.getEntitiesOfClass(ThrowableProjectile.class, new AABB(x - range, y - range, z - range, x + range, y + range, z + range), Predicates.instanceOf(ManaBurst.class));
	for (ThrowableProjectile entity : entities) {
		ManaBurst burst = (ManaBurst) entity;
		ItemStack lens = burst.getSourceLens();
		if (lens != null && lens.getItem() instanceof TinyPlanetExcempt excempt && !excempt.shouldPull(lens)) {
			continue;
		}

		int orbitTime = burst.getOrbitTime();
		if (orbitTime == 0) {
			burst.setMinManaLoss(burst.getMinManaLoss() * 3);
		}

		float radius = Math.min(7.5F, (Math.max(40, orbitTime) - 40) / 40F + 1.5F);
		int angle = orbitTime % 360;

		float xTarget = (float) (x + Math.cos(angle * 10 * Math.PI / 180F) * radius);
		float yTarget = (float) y;
		float zTarget = (float) (z + Math.sin(angle * 10 * Math.PI / 180F) * radius);

		Vec3 targetVec = new Vec3(xTarget, yTarget, zTarget);
		Vec3 currentVec = entity.position();
		Vec3 moveVector = targetVec.subtract(currentVec);

		entity.setDeltaMovement(moveVector);

		burst.setOrbitTime(burst.getOrbitTime() + 1);
	}
}

public void onWornTick(ItemStack stack, LivingEntity living) {
	if (!(living instanceof Player player) || player.level().isClientSide) {
		return;
	}
	if (player.isInWaterOrBubble()) {
		// only activate for one ring at a time
		ItemStack result = EquipmentHandler.findOrEmpty(BotaniaItems.waterRing, living);
		if (result != stack) {
			return;
		}

		boolean hasMana = ManaItemHandler.instance().requestManaExact(stack, player, MANA_COST, false);
		if (hasMana) {
			EntityHelper.addStaticEffect(living, MobEffects.CONDUIT_POWER, CONDUIT_POWER_AMPLIFIER);

			if (StoneOfTemperanceItem.hasTemperanceActive(player)) {
				EntityHelper.removeStaticEffect(living, MobEffects.DOLPHINS_GRACE, DOLPHINS_GRACE_AMPLIFIER);
			} else {
				EntityHelper.addStaticEffect(living, MobEffects.DOLPHINS_GRACE, DOLPHINS_GRACE_AMPLIFIER);
			}
			ManaItemHandler.instance().requestManaExact(stack, player, MANA_COST, true);
		} else {
			// convert to short finite duration to prevent flickering and other weird behavior in cases where the
			// player is out of mana and an aura band causes the ring to temporarily turn one in short intervals
			EntityHelper.convertStaticEffectToFinite(living, MobEffects.CONDUIT_POWER, CONDUIT_POWER_AMPLIFIER,
					OUT_OF_MANA_DURATION);
			EntityHelper.convertStaticEffectToFinite(living, MobEffects.DOLPHINS_GRACE,
					DOLPHINS_GRACE_AMPLIFIER, OUT_OF_MANA_DURATION);
		}
	} else {
		onUnequipped(stack, living);
	}
}

public static void handleAbility(LivingIncomingDamageEvent event) {
    var RING = ((ExpulsionRing) ItemRegistry.EXPULSION_RING.get());
    if (event.getEntity() instanceof ServerPlayer serverPlayer) {
        if (event.getSource().getEntity() != null && RING.isEquippedBy(serverPlayer) && RING.tryProcCooldown(serverPlayer)) {
            var vec = serverPlayer.getBoundingBox().getCenter();
            //Visual Explosion
            serverPlayer.level.explode(
                    null,
                    null,
                    null,
                    vec.x,
                    vec.y,
                    vec.z,
                    0,
                    false,
                    Level.ExplosionInteraction.NONE,
                    ParticleTypes.GUST_EMITTER_SMALL,
                    ParticleTypes.GUST_EMITTER_LARGE,
                    SoundEvents.WIND_CHARGE_BURST
            );
            //Knockback effect
            serverPlayer.level.getEntities(serverPlayer, serverPlayer.getBoundingBox().inflate(3)).forEach(entity -> {
                var d = Math.max(entity.distanceToSqr(serverPlayer), .2);
                if (d < RADIUS_SQR && !DamageSources.isFriendlyFireBetween(serverPlayer, entity)) {
                    var f = 1 - d / (RADIUS_SQR) + .6f * (entity instanceof LivingEntity living ? 1 - living.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE) : 1);
                    var impulse = entity.getBoundingBox().getCenter().subtract(serverPlayer.getBoundingBox().getCenter()).normalize().add(0, 0.1, 0).scale(f);
                    entity.setDeltaMovement(entity.getDeltaMovement().add(impulse));
                    entity.hurtMarked = true;
                }
            });
        }
    }
}

public static void tick() {
	Minecraft mc = Minecraft.getInstance();

	BlueprintSection last = lastTargetedSection;
	lastTargetedSection = null;
	active = false;
	noOutput = false;
	shopContext = null;

	if (mc.gameMode.getPlayerMode() == GameType.SPECTATOR)
		return;

	HitResult mouseOver = mc.hitResult;
	if (mouseOver == null)
		return;
	if (mouseOver.getType() != Type.ENTITY)
		return;

	EntityHitResult entityRay = (EntityHitResult) mouseOver;
	if (!(entityRay.getEntity() instanceof BlueprintEntity blueprintEntity))
		return;

	BlueprintSection sectionAt = blueprintEntity.getSectionAt(entityRay.getLocation()
		.subtract(blueprintEntity.position()));

	lastTargetedSection = last;
	active = true;

	boolean sneak = mc.player.isShiftKeyDown();
	if (sectionAt != lastTargetedSection || AnimationTickHolder.getTicks() % 10 == 0 || lastSneakState != sneak)
		rebuild(sectionAt, sneak);

	lastTargetedSection = sectionAt;
	lastSneakState = sneak;
}

static void handleFlight(LivingEntity entity) {
    if (EquipmentUtil.hasFullValkyrieSet(entity)) {
        if (entity instanceof Player player && !player.getAbilities().flying) { // The player can't have creative flight enabled, otherwise it causes issues.
            var data = player.getData(AetherDataAttachments.AETHER_PLAYER);
            Vec3 deltaMovement = player.getDeltaMovement();
            // Updates the flight modifier and timer values.
            if (data.isJumping() && !onGround(player)) { // Checks if the player is off the ground and holding the jump key (space bar by default).
                if (data.getFlightModifier() >= data.getFlightModifierMax()) { // Limits the flight modifier to a maximum value.
                    data.setFlightModifier(data.getFlightModifierMax());
                }
                if (data.getFlightTimer() > 2) { // Starts allowing the player to fly after a 2 tick delay of being off the ground.
                    if (data.getFlightTimer() < data.getFlightTimerMax()) { // Allows the player to fly until the maximum value is hit.
                        data.setFlightModifier(data.getFlightModifier() + 0.25F);
                        data.setFlightTimer(data.getFlightTimer() + 1);
                    }
                } else {
                    data.setFlightTimer(data.getFlightTimer() + 1);
                }
            } else if (!data.isJumping()) {
                // Resets only the modifier if the player stops holding the jump key midair. The timer doesn't reset though and remains frozen, and will continue where it left off when the key is held again, preventing infinite flight.
                data.setFlightModifier(1.0F);
            }
            if (onGround(player)) { // Resets both timer and modifier if the player is on the ground.
                data.setFlightTimer(0);
                data.setFlightModifier(1.0F);
            }
            // Modifies the player's upwards movement based on the set flight modifier and timer values.
            if (data.isJumping() && !onGround(player) && data.getFlightTimer() > 2 && data.getFlightTimer() < data.getFlightTimerMax() && data.getFlightModifier() > 1.0F) {
                player.setDeltaMovement(deltaMovement.x(), 0.025F * data.getFlightModifier(), deltaMovement.z());
            }
            if (player instanceof ServerPlayer serverPlayer) { // Prevents the player from being kicked for flying.
                ServerGamePacketListenerImplAccessor serverGamePacketListenerImplAccessor = (ServerGamePacketListenerImplAccessor) serverPlayer.connection;
                serverGamePacketListenerImplAccessor.aether$setAboveGroundTickCount(0);
            }
        }
    }
}

public void tick() {
	super.tick();
	if (getSpeed() == 0)
		return;

	BlockState state = getBlockState();
	BooleanProperty waterProperty = BlockStateProperties.WATERLOGGED;
	if (state.hasProperty(waterProperty) && state.getValue(waterProperty))
		return;

	if (airLevelTimer > 0) {
		airLevelTimer--;
		return;
	}

	int max = BacktankUtil.maxAir(capacityEnchantLevel);
	if (level.isClientSide) {
		Vec3 centerOf = VecHelper.getCenterOf(worldPosition);
		Vec3 v = VecHelper.offsetRandomly(centerOf, level.random, .65f);
		Vec3 m = centerOf.subtract(v);
		if (airLevel != max)
			level.addParticle(new AirParticleData(1, .05f), v.x, v.y, v.z, m.x, m.y, m.z);
		return;
	}

	if (airLevel == max)
		return;

	int prevComparatorLevel = getComparatorOutput();
	float abs = Math.abs(getSpeed());
	int increment = Mth.clamp(((int) abs - 100) / 20, 1, 5);
	airLevel = Math.min(max, airLevel + increment);
	if (getComparatorOutput() != prevComparatorLevel && !level.isClientSide)
		level.updateNeighbourForOutputSignal(worldPosition, state.getBlock());
	if (airLevel == max)
		sendData();
	airLevelTimer = Mth.clamp((int) (128f - abs / 5f) - 108, 0, 20);
}

public boolean onApplyButtonPressed(EntityPlayer player, Slot centre, Slot crystals, Slot upgrade, Slot[] spellBooks){

	boolean changed = false;

	if(upgrade.getHasStack()){
		ItemStack original = centre.getStack().copy();
		centre.putStack(this.applyUpgrade(player, centre.getStack(), upgrade.getStack()));
		changed = !ItemStack.areItemStacksEqual(centre.getStack(), original);
	}

	// Charges armour by appropriate amount
	if(crystals.getStack() != ItemStack.EMPTY && !this.isManaFull(centre.getStack())){

		int chargeDepleted = this.getManaCapacity(centre.getStack()) - this.getMana(centre.getStack());

		// Not too pretty but allows addons implementing the IManaStoringItem interface to provide their mana amount for custom crystals,
		// previously this was defaulted to the regular crystal's amount, allowing players to exploit it if a crystal was worth less mana than that.
		int manaPerItem = crystals.getStack().getItem() instanceof IManaStoringItem ?
				((IManaStoringItem) crystals.getStack().getItem()).getMana(crystals.getStack()) :
				crystals.getStack().getItem() instanceof ItemCrystal ? Constants.MANA_PER_CRYSTAL : Constants.MANA_PER_SHARD;

		if(crystals.getStack().getItem() == WizardryItems.crystal_shard) manaPerItem = Constants.MANA_PER_SHARD;
		if(crystals.getStack().getItem() == WizardryItems.grand_crystal) manaPerItem = Constants.GRAND_CRYSTAL_MANA;

		if(crystals.getStack().getCount() * manaPerItem < chargeDepleted){
			// If there aren't enough crystals to fully charge the armour
			this.rechargeMana(centre.getStack(), crystals.getStack().getCount() * Constants.MANA_PER_CRYSTAL);
			crystals.decrStackSize(crystals.getStack().getCount());

		}else{
			// If there are excess crystals (or just enough)
			this.setMana(centre.getStack(), this.getManaCapacity(centre.getStack()));
			crystals.decrStackSize((int)Math.ceil(((double)chargeDepleted) / Constants.MANA_PER_CRYSTAL));
		}

		changed = true;
	}

	return changed;
}

public void doRender(HumanoidModel<?> bipedModel, ItemStack stack, LivingEntity living, PoseStack ms, MultiBufferSource buffers, int light, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
	int meta = getVariant(stack);
	if (meta <= 0 || meta >= MiscellaneousModels.INSTANCE.tiaraWingIcons.length + 1) {
		return;
	}

	BakedModel model = MiscellaneousModels.INSTANCE.tiaraWingIcons[meta - 1];
	ClientXplatAbstractions.instance().markSpriteActive(model.getParticleIcon());
	boolean flying = living instanceof Player player && player.getAbilities().flying;
	float flap = 20F + (float) ((Math.sin((double) (living.tickCount + partialTicks) * (flying ? 0.4F : 0.2F)) + 0.5F) * (flying ? 30F : 5F));

	switch (meta) {
		case 1:
			renderBasic(bipedModel, model, stack, ms, buffers, light, flap);
			ms.pushPose();
			ClientLogic.renderHalo(bipedModel, living, ms, buffers, partialTicks);
			ms.popPose();
			break;
		case 2:
			renderSephiroth(bipedModel, model, stack, ms, buffers, light, flap);
			break;
		case 3:
			renderCirno(bipedModel, model, stack, ms, buffers, light);
			break;
		case 4:
			renderPhoenix(bipedModel, model, stack, ms, buffers, flap);
			break;
		case 5:
			renderKuroyukihime(bipedModel, model, stack, ms, buffers, flap);
			break;
		case 6:
		case 8:
			renderBasic(bipedModel, model, stack, ms, buffers, light, flap);
			break;
		case 7:
			float alpha = 0.5F + (float) Math.cos((double) (living.tickCount + partialTicks) * 0.3F) * 0.2F;
			int color = 0xFFFFFF | ((int) (alpha * 255F)) << 24;
			renderCustomColor(bipedModel, model, living, stack, ms, buffers, flap, color);
			break;
		case 9:
			flap = -(float) ((Math.sin((double) (living.tickCount + partialTicks) * 0.2F) + 0.6F) * (flying ? 12F : 5F));
			alpha = 0.5F + (flying ? (float) Math.cos((double) (living.tickCount + partialTicks) * 0.3F) * 0.25F + 0.25F : 0F);
			color = 0xFFFFFF | ((int) (alpha * 255F)) << 24;
			renderCustomColor(bipedModel, model, living, stack, ms, buffers, flap, color);
			break;
	}
}

public static void onRenderWorld(RenderLevelStageEvent event) {
	if (event.getStage() != Stage.AFTER_PARTICLES)
		return;

	Minecraft mc = Minecraft.getInstance();
	LocalPlayer player = mc.player;
	RandomSource random = RandomSource.create();

	for (int i = 0; i < Inventory.getSelectionSize(); i++) {
		ItemStack stackInSlot = player.getInventory()
			.getItem(i);
		if (!AllItems.WAND_OF_SYMMETRY.isIn(stackInSlot))
			continue;
		if (!SymmetryWandItem.isEnabled(stackInSlot))
			continue;
		SymmetryMirror mirror = SymmetryWandItem.getMirror(stackInSlot);
		if (mirror instanceof EmptyMirror)
			continue;

		BlockPos pos = BlockPos.containing(mirror.getPosition());

		float yShift = 0;
		double speed = 1 / 16d;
		yShift = Mth.sin((float) (AnimationTickHolder.getRenderTime() * speed)) / 5f;

		MultiBufferSource.BufferSource buffer = mc.renderBuffers()
			.bufferSource();
		Camera info = mc.gameRenderer.getMainCamera();
		Vec3 view = info.getPosition();

		PoseStack ms = event.getPoseStack();
		ms.pushPose();
		ms.translate(pos.getX() - view.x(), pos.getY() - view.y(), pos.getZ() - view.z());
		ms.translate(0, yShift + .2f, 0);
		mirror.applyModelTransform(ms);
		BakedModel model = mirror.getModel()
			.get();
		VertexConsumer builder = buffer.getBuffer(RenderType.solid());

		mc.getBlockRenderer()
			.getModelRenderer()
			.tesselateBlock(player.level(), model, Blocks.AIR.defaultBlockState(), pos, ms, builder, true,
				random, Mth.getSeed(pos), OverlayTexture.NO_OVERLAY, ModelData.EMPTY, RenderType.solid());

		ms.popPose();
		buffer.endBatch();
	}
}

