private boolean otherHandgunCooledDownMore(Player player, InteractionHand currentHand, ItemStack currentHandgun) {
	if (currentHand == InteractionHand.MAIN_HAND) {
		ItemStack offHandItem = player.getOffhandItem();
		return offHandItem.getItem() == this && getCooldown(offHandItem) < getCooldown(currentHandgun);
	}

	ItemStack mainHandItem = player.getMainHandItem();
	return mainHandItem.getItem() == this && getCooldown(mainHandItem) < getCooldown(currentHandgun);
}

public void addStoredCharge(ItemStack containerStack, int slot, int chargeToAdd, @Nullable ItemStack chargeStack) {
	if (slot == BONEMEAL_SLOT) {
		int currentCharge = getBoneMealCount(containerStack);
		int chargeToStore = chargeToAdd > 0 ? Math.min(chargeToAdd, Math.max(getContainerSlotLimit(slot) - currentCharge, 0)) : chargeToAdd;
		setBoneMealCount(containerStack, currentCharge + chargeToStore);
	} else {
		incrementPlantable(containerStack, new ItemStack(Items.BONE_MEAL), chargeToAdd);
	}
}

private void cycleMode(ItemStack harvestRod, boolean next) {
	Mode currentMode = getMode(harvestRod);
	int plantableCount = getCountOfPlantables(harvestRod);
	if (next) {
		setNextMode(harvestRod, currentMode, plantableCount);
	} else {
		setPreviousMode(harvestRod, currentMode, plantableCount);
	}
}

