public float onShieldBlock(AffixInstance inst, LivingEntity entity, DamageSource source, float amount) {
    if (source.is(DamageTypeTags.IS_EXPLOSION)) {
        int time = this.values.get(inst.getRarity()).getInt(inst.level());
        int modifier = 1 + (int) (Math.log(amount) / Math.log(3));
        entity.addEffect(new MobEffectInstance(MobEffects.STRENGTH, time, modifier));
    }

    return super.onShieldBlock(inst, entity, source, amount);
}

public float onShieldBlock(GemInstance inst, LivingEntity entity, DamageSource source, float amount) {
    Data d = this.values.get(inst.purity());
    if (amount <= 2 || AbilityCooldowns.isOnCooldown(entity, makeUniqueId(inst), d.cooldown)) {
        return amount;
    }
    entity.heal(amount * d.healFactor);
    AbilityCooldowns.startCooldown(entity, makeUniqueId(inst));
    return amount;
}

