public void applyEntityEffect(LivingEntity pTarget, @Nullable Entity source, @Nullable Entity pIndirectSource, int pAmplifier){
    pAmplifier += 1;
    if(pTarget.level.random.nextInt(Mth.floor(5.0F / Mth.clamp(pAmplifier, 1, 5))) == 0) {
        pTarget.hurt(pTarget.damageSources().thrown(pTarget, pIndirectSource), 8.0F * pAmplifier);
    }

    for(EquipmentSlot equipmentSlot : EquipmentSlot.values()) {
        ItemStack stack = pTarget.getItemBySlot(equipmentSlot);
        if(stack.isDamageableItem()) {
            ItemHelper.hurtAndBreak(stack, 50 + (pTarget.level.random.nextInt(25) * pAmplifier), pIndirectSource instanceof LivingEntity entity ? entity : null);
        }
    }
}

public void addModifiers(AffixInstance inst, StackAttributeModifiersEvent event) {
    LootCategory cat = inst.category();
    if (cat.isNone()) {
        Apotheosis.LOGGER.debug("Attempted to apply the attributes of affix {} on item {}, but it is not an affix-compatible item!", this.id(), inst.stack().getHoverName().getString());
        return;
    }
    ModifierInst modif = this.modifiers.get(inst.getRarity());
    if (modif.attr == null) {
        Apotheosis.LOGGER.debug("The affix {} has attempted to apply a null attribute modifier to {}!", this.id(), inst.stack().getHoverName().getString());
        return;
    }
    event.addModifier(this.attribute, modif.build(inst), cat.getSlots());
}

public MutableComponent getDescription(AffixInstance inst, AttributeTooltipContext ctx) {
    MobEffectInstance effectInst = this.values.get(inst.getRarity()).build(this.effect, inst.level());
    MutableComponent comp = this.target.toComponent(toComponent(effectInst, ctx.tickRate()));
    int cooldown = this.getCooldown(inst.getRarity());
    if (cooldown != 0) {
        Component cd = Component.translatable("affix.apotheosis.cooldown", StringUtil.formatTickDuration(cooldown, ctx.tickRate()));
        comp = comp.append(" ").append(cd);
    }
    if (this.stackOnReapply) {
        comp = comp.append(" ").append(Component.translatable("affix.apotheosis.stacking"));
    }
    return comp;
}

