	Long cooldown = leggingsStack.get(TFDataComponents.SIDESTEP_COOLDOWN);
	long currentTime = player.level().getGameTime();
	if (TravellersModifiersManager.isModifierActive(player, leggingsStack, TravellersModifiersManager.SIDESTEP_MODIFIER) && cooldown != null && currentTime - lastSidestepTime > cooldown && !player.isFallFlying() && player.onGround() && !player.isCrouching()) {
		TravellersGearLogic.performSidestep(player, isLeftSidestep);
		attachment.lastSidestepTime = currentTime;
		attachment.shouldPlaySideStepCooldownSound = true;
		return true;
	}
	return false;
}

private int getChargeupTime(ItemStack stack) {
	int maxChargeUp = 0;
	for (SpellRing spellRing : SpellUtils.getAllSpellRings(stack)) {
		if (spellRing.isContinuous()) {
			return 72000;
		} else if (spellRing.getChargeUpTime() > maxChargeUp)
			maxChargeUp = spellRing.getChargeUpTime();

		IModuleOverrides overrides = spellRing.getOverrideHandler().getConsumerInterface(IModuleOverrides.class);
		maxChargeUp = overrides.modifyChargeupTime(maxChargeUp);
	}

	return maxChargeUp;
}

public ActionResult<ItemStack> onItemRightClick(World worldIn, PlayerEntity playerIn, Hand handIn) {
  ItemStack itemstack = playerIn.getHeldItem(handIn);
  boolean playerHasAmmo = !playerIn.findAmmo(itemstack).isEmpty();

  ActionResult<ItemStack> ret = net.minecraftforge.event.ForgeEventFactory.onArrowNock(itemstack, worldIn, playerIn, handIn, playerHasAmmo);
  if (ret != null) return ret;

  if (!playerIn.abilities.isCreativeMode && !playerHasAmmo) {
    return ActionResult.resultFail(itemstack);
  } else {
    playerIn.setActiveHand(handIn);
    return ActionResult.resultConsume(itemstack);
  }
}

private static void addChargedProjectile(ItemStack itemStackCrossbow, ItemStack itemStackProjectile) {
  CompoundNBT crossbowBaseTag = itemStackCrossbow.getOrCreateTag();
  ListNBT listOfProjectilesNBT;
  if (crossbowBaseTag.contains("ChargedProjectiles", NBTtypesMBE.COMPOUND_NBT_ID)) {
    listOfProjectilesNBT = crossbowBaseTag.getList("ChargedProjectiles", NBTtypesMBE.LIST_NBT_ID);
  } else {
    listOfProjectilesNBT = new ListNBT();
  }

  CompoundNBT projectileNBT = new CompoundNBT();
  itemStackProjectile.write(projectileNBT);
  listOfProjectilesNBT.add(projectileNBT);
  crossbowBaseTag.put("ChargedProjectiles", listOfProjectilesNBT);
}

