}

protected void checkAndPerformAttack(LivingEntity target) {
	if (this.isTimeToAttack() && this.mob.getBoundingBox().inflate(1.0F).intersects(target.getBoundingBox())) {
		this.resetAttackCooldown();
		double x = target.getX() - this.mob.getX();
		double y = target.getZ() - this.mob.getZ();
		float f = (float) (Mth.atan2(y, x) * Mth.RAD_TO_DEG) - 90.0F;
		this.mob.setYRot(f);
		this.mob.yRotO = this.mob.getYRot();
		this.mob.yBodyRot = this.mob.getYRot();
		this.mob.yHeadRot = this.mob.yBodyRot;
		((Zebroid) this.mob).kick(false);
		((Zebroid) this.mob).playKickingSound();
	}
}

private void doInitialPosing(LevelAccessor world) {
    BlockPos above = this.blockPosition();
    int upBy = 100;
    int k = 0;
    while (world.isEmptyBlock(above) && above.getY() < level().getMaxBuildHeight() && k < upBy) {
        above = above.above();
        k++;
    }
    if (world.isEmptyBlock(above)) {
        this.setFlying(true);
    } else {
        this.setHanging(true);
    }
    this.setPos(above.getX() + 0.5F, above.getY() - this.getBoundingBox().getYsize(), above.getZ() + 0.5F);
}

