public AbstractArrow createArrow(Level level, ItemStack stack, @Nullable LivingEntity shooter, Position position, @Nullable ItemStack weapon) {
    boolean intangible = stack.has(DataComponents.INTANGIBLE_PROJECTILE);
    QuarrelProperties properties = this.behavior.properties();
    QuarrelEntity arrowEntity = new QuarrelEntity(level, position.x(), position.y(), position.z(), stack, weapon);
    arrowEntity.setBaseDamage(QuarrelEntity.launchBaseDamage(properties));
    this.behavior.modifyArrow(level, stack, shooter, arrowEntity);
    if (shooter instanceof Player || shooter == null) {
        arrowEntity.pickup = intangible ? AbstractArrow.Pickup.CREATIVE_ONLY : properties.pickupBehavior();
    } else {
        arrowEntity.pickup = AbstractArrow.Pickup.DISALLOWED;
    }
    arrowEntity.setOwner(shooter);

    return arrowEntity;
}

public void checkToolDamage(@NotNull ItemStack from, @NotNull ItemStack itemInHand, boolean forceCalculation) {
    AttributeInstance attribute = player.getAttribute(Attributes.ATTACK_DAMAGE);
    if (this.getLevel() > 0 && this.form.isTransformed() && itemInHand.isEmpty()) {
        if (!from.isEmpty() || forceCalculation) {
            float damage = WerewolvesConfig.BALANCE.PLAYER.werewolf_claw_damage.get().floatValue();
            if (specialAttributes.diggerTier != null) {
                damage += (1 + specialAttributes.diggerTier.getAttackDamageBonus()) / 2;
            }
            attribute.removeModifier(CLAWS);
            attribute.addTransientModifier(new AttributeModifier(CLAWS, damage, AttributeModifier.Operation.ADD_VALUE));
        }
    } else {
        attribute.removeModifier(CLAWS);
    }
}

public void tick() {
	if (this.operation == MoveControl.Operation.MOVE_TO) {
		double dx = this.getWantedX() - this.parentEntity.getX();
		double dy = this.getWantedY() - this.parentEntity.getY();
		double dz = this.getWantedZ() - this.parentEntity.getZ();
		double dist = dx * dx + dy * dy + dz * dz;

		if (this.courseChangeCooldown-- <= 0) {
			this.courseChangeCooldown += this.parentEntity.getRandom().nextInt(5) + 2;
			dist = Mth.sqrt((float) dist);

			this.parentEntity.setDeltaMovement(this.parentEntity.getDeltaMovement().add((dx / dist * 0.1D) * this.speedModifier, (dy / dist * 0.1D) * this.speedModifier, (dz / dist * 0.1D) * speedModifier));
		}
	}
}

private static List<ItemStack> getChargedProjectiles(ItemStack crossbowItemStack) {
  ArrayList projectileList = Lists.newArrayList();
  CompoundNBT crossbowBaseTag = crossbowItemStack.getTag();
  if (crossbowBaseTag != null && crossbowBaseTag.contains("ChargedProjectiles", NBTtypesMBE.LIST_NBT_ID)) {
    ListNBT chargedProjectilesNBTlist = crossbowBaseTag.getList("ChargedProjectiles", NBTtypesMBE.COMPOUND_NBT_ID);
    if (chargedProjectilesNBTlist != null) {
      for (int i = 0; i < chargedProjectilesNBTlist.size(); ++i) {
        CompoundNBT projectileNBT = chargedProjectilesNBTlist.getCompound(i);
        projectileList.add(ItemStack.read(projectileNBT));
      }
    }
  }

  return projectileList;
}

