    if (this.level().isClientSide()) {
        this.idleAnimationState.animateWhen(!this.walkAnimation.isMoving() && this.getAttackState() == 0 && this.getAwaken(), this.tickCount);
    }
    prevAttackProgress = AttackProgress;
    if (isAggressive() && AttackProgress < 10F) {
        AttackProgress++;
    }
    if (!isAggressive() && AttackProgress > 0F) {
        AttackProgress--;
    }
    if (charge_cooldown > 0) charge_cooldown--;
    if (magic_cooldown > 0) magic_cooldown--;
}

protected void checkForCloseRangeAttack (double distance){
    int meleeRange = 36;
    int r = (triceratops.getRandom().nextInt(100) + 1);
    if (distance <= meleeRange) {
        if (r <= 50) {
            triceratops.setAnimationState(21);
        }
        else {
            triceratops.setAnimationState(22);
        }
    }
    else if (distance > meleeRange && this.chargeCooldown <= 0 && !triceratops.isInWater()) {
        triceratops.setAnimationState(23);
