public boolean shouldExecute() {
	boolean canLay = this.entity.isEntityAlive() && this.entity.getAttackTarget() != null && this.entity.getEggSacPercentage() < 0;
	if(canLay) {
		if(this.cooldown-- <= 0) {
			List<EntityTinyWormEggSac> nearbyEggSacs = this.entity.world.getEntitiesWithinAABB(EntityTinyWormEggSac.class, this.entity.getEntityBoundingBox().grow(16.0D));
			List<EntityTinySludgeWorm> nearbyTinyWorms = this.entity.world.getEntitiesWithinAABB(EntityTinySludgeWorm.class, this.entity.getEntityBoundingBox().grow(16.0D));

			if(nearbyEggSacs.size() < 5 && nearbyTinyWorms.size() < 8) {
				this.cooldown = 30 + this.entity.rand.nextInt(30);
				return true;
			} else {
				this.cooldown = 10 + this.entity.rand.nextInt(20);
			}
		}
	}
	return false;
}

public void onCollideWithPlayer(EntityPlayer player) {

	if (player.getEntityBoundingBox().maxY >= getEntityBoundingBox().minY && player.getEntityBoundingBox().minY <= getEntityBoundingBox().maxY)
		if (player.getEntityBoundingBox().maxX >= getEntityBoundingBox().minX && player.getEntityBoundingBox().minX <= getEntityBoundingBox().maxX)
			if (player.getEntityBoundingBox().maxZ >= getEntityBoundingBox().minZ && player.getEntityBoundingBox().minZ <= getEntityBoundingBox().maxZ) {
				if (!getEntityWorld().isRemote) {
					if (player.isPotionActive(ElixirEffectRegistry.EFFECT_DECAY.getPotionEffect()))
						player.addPotionEffect(ElixirEffectRegistry.EFFECT_DECAY.createEffect(60, 3));
					IDecayCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_DECAY, null);
					if (cap != null)
						cap.getDecayStats().addDecayAcceleration(0.1F);

				}
				if (getEntityWorld().isRemote)
					player.addVelocity(0, 0.2D, 0);
			}
}

private void resetModifiers(Player player, ItemStack removeFrom, ItemStack addFrom) {
    removeFrom.forEachModifier(EquipmentSlot.MAINHAND, (attribute, modifier) -> {
        AttributeInstance instance = player.getAttribute(attribute);

        if (instance != null && instance.hasModifier(modifier.id())) {
            instance.removeModifier(modifier);
        }
    });

    addFrom.forEachModifier(EquipmentSlot.MAINHAND, (attribute, modifier) -> {
        AttributeInstance instance = player.getAttribute(attribute);

        if (instance != null && !instance.hasModifier(modifier.id())) {
            instance.addTransientModifier(modifier);
        }
    });
}

private void eat(World world, ItemStack stack, CallbackInfoReturnable<ItemStack> callbackInfo) {
	if (!world.isClient) {
		FoodComponent foodComponent = stack.getItem().getFoodComponent();
		if (foodComponent != null) {
			boolean vampire = BewitchmentAPI.isVampire(this, true);
			if (vampire || (BewitchmentAPI.isWerewolf(this, true) && !foodComponent.isMeat())) {
				addStatusEffect(new StatusEffectInstance(StatusEffects.WITHER, 100, 1));
				addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS, 100, 1));
				addStatusEffect(new StatusEffectInstance(StatusEffects.WEAKNESS, 100, 1));
				addStatusEffect(new StatusEffectInstance(StatusEffects.NAUSEA, 100, 1));
			}
			if (vampire && (stack.getItem() == BWObjects.GARLIC || stack.getItem() == BWObjects.GRILLED_GARLIC || stack.getItem() == BWObjects.GARLIC_BREAD)) {
				damage(BWDamageSources.create(world, BWDamageSources.MAGIC_COPY), Float.MAX_VALUE);
			}
		}
	}
}

private void absorbBlazeFireballs(ItemStack stack, Player player) {
	List<SmallFireball> blazeFireballs = player.level().getEntitiesOfClass(SmallFireball.class, player.getBoundingBox().inflate(3));
	for (SmallFireball fireball : blazeFireballs) {
		if (fireball.getOwner() == player) {
			continue;
		}
		int pointsToAdd = getBlazeAbsorbWorth();
		if (pointsToAdd > 0 && addPartialCharge(stack, BLAZE_POWDER_SLOT, pointsToAdd, getBlazePowderLimit(), new ItemStack(Items.BLAZE_POWDER))) {
			for (int particles = 0; particles < 4; particles++) {
				player.level().addParticle(DustParticleOptions.REDSTONE, fireball.getX(), fireball.getY(), fireball.getZ(), 0.0D, 1.0D, 1.0D);
			}
			player.level().playLocalSound(fireball.getX(), fireball.getY(), fireball.getZ(), SoundEvents.LAVA_EXTINGUISH, SoundSource.BLOCKS, 0.5F,
					2.6F + RandHelper.getRandomMinusOneToOne(player.level().random) * 0.8F, false);
		}
		fireball.discard();
	}
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
    ItemStack itemstack = playerIn.getItemInHand(handIn);
    if (!SEHelper.isOnCooldown(playerIn, itemstack)) {
        int soulCost = this.getSoulCost(playerIn);
        if (SEHelper.getSoulsAmount(playerIn, soulCost)) {
            if (worldIn instanceof ServerLevel serverLevel) {
                this.mobUse(serverLevel, playerIn, itemstack);
                if (!playerIn.getAbilities().instabuild) {
                    SEHelper.decreaseSouls(playerIn, soulCost);
                    SEHelper.sendSEUpdatePacket(playerIn);
                }
            }
            return InteractionResultHolder.success(itemstack);
        }
    }
    return super.use(worldIn, playerIn, handIn);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    float radius = (float) spellStat.getRadius();
    float velocity = spellStat.getVelocity() + WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster) / 3.0F;
    float extraBlast = WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 2.0F;
    if (this.rightStaff(staff)){
        radius += 1.0F;
    }
    MagmaBomb blast = new MagmaBomb(caster, worldIn);
    blast.setExtraDamage(spellStat.getPotency() + WandUtil.getPotencyLevel(caster));
    blast.setExplosionPower(extraBlast + radius);
    blast.setDuration(spellStat.getDuration() + WandUtil.getLevels(ModEnchantments.DURATION.get(), caster));
    blast.setStaff(this.rightStaff(staff));
    blast.shootFromRotation(caster, caster.getXRot(), caster.getYRot(), 0.0F, velocity, 1.0F);
    worldIn.addFreshEntity(blast);

    this.playSound(worldIn, caster, ModSounds.CAST_SPELL.get());
}

public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
    if (target instanceof LivingEntity target1){
        super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
        float chance = rightStaff(staff) ? 0.25F : 0.05F;
        float chainDamage = actualDamage / 2.0F;
        if (worldIn.isThundering() && worldIn.isRainingAt(target1.blockPosition())){
            chance += 0.25F;
            chainDamage = actualDamage;
        }
        if (worldIn.random.nextFloat() <= chance){
            target1.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
        }
        if (rightStaff(staff)){
            WandUtil.chainLightning(target1, caster, 6.0D, chainDamage);
        }
    }
}

public boolean doHurtTarget(ServerLevel level, Entity entity) {
	this.attackTimer = 10;
	this.level().broadcastEntityEvent(this, (byte) 4);
	float attackDamage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
	float damage = (int) attackDamage > 0 ? attackDamage / 2.0F + (float) this.getRandom().nextInt((int) attackDamage) : attackDamage;
	DamageSource damageSource = this.damageSources().mobAttack(this);
	boolean hurt = entity.hurtServer(level, damageSource, damage);
	if (hurt) {
		double knockbackResistance = entity instanceof LivingEntity livingEntity ? livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE) : 0.0;
		double scale = Math.max(0.0D, 1.0D - knockbackResistance);
		entity.setDeltaMovement(entity.getDeltaMovement().add(0.0, 0.4F * scale, 0.0));
		EnchantmentHelper.doPostAttackEffects(level, entity, damageSource);
	}

	this.playSound(UGSoundEvents.ROTBEAST_ATTACK.get(), 1.0F, 1.0F);
	return hurt;
}

