protected void checkAndPerformAttack(LivingEntity victim) {
	if (this.canPerformAttack(victim) && this.getTicksUntilNextAttack() <= 0 && this.mob.getPassengers().isEmpty() && this.cooldown-- == 0) {
		this.cooldown = 3; // Gives the thrower a pause so it doesn't pick the target back up immediately after throwing; for whatever reason the attack cooldown isn't enough...
		this.resetAttackCooldown();
		this.mob.swing(InteractionHand.MAIN_HAND);
		if (this.mob.getPassengers().isEmpty()) {
			var v = victim.getVehicle();

			if (v == null || !v.is(TFEntityTypeTags.RIDES_OBSTRUCT_SNATCHING)) {
				// Pluck them from the boat, minecart, donkey, or whatever
				victim.stopRiding();

				victim.startRiding(this.mob, true, false);
			}
		}
	}
}

private void shootAtBlockPos(int head, double posX, double posY, double posZ) {
	if (attackCooldown > 0) {
		attackCooldown--;
	}
	else {
		attackCooldown = getAttackCooldown();
		BaseMobProjectile projectile = new NethengeicWitherShotEntity(this, getStage() == 3);

		double distanceFactorX = posX - projectile.getX();
		double distanceFactorY = posY - projectile.getY();
		double distanceFactorZ = posZ - projectile.getZ();
		double hyp = MathHelper.sqrt(distanceFactorX * distanceFactorX + distanceFactorZ * distanceFactorZ) * 0.05d;

		projectile.shoot(distanceFactorX, distanceFactorY + hyp, distanceFactorZ, 1.6f, (float)(4 - this.level.getDifficulty().getId()));
		level.addFreshEntity(projectile);
	}
}

public BrainActivityGroup<? extends SpinoledonEntity> getFightTasks() {
