public void resyncEffectInstances(ItemStack stack)
{
	double durationModifier = getDurationModifier(stack);
	List<EffectHolder> holderList = getEffectHoldersOfFlask(stack);
	List<MobEffectInstance> effectList = new ArrayList<MobEffectInstance>();

	for (EffectHolder holder : holderList)
	{
		effectList.add(holder.getEffectInstance(durationModifier, false, true));
	}

	setEffectsOfFlask(stack, effectList);
	Collection<MobEffectInstance> instanceList = PotionUtils.getMobEffects(stack);

	int color = instanceList.isEmpty() ? PotionUtils.getColor(Potions.WATER) : PotionUtils.getColor(instanceList);
	stack.getTag().putInt("CustomPotionColor", color);
}

protected void actuallyHurt(DamageSource damageSrc, float damageAmount) {
    if (!level.isClientSide && armorCooldown == 0) {
        setArmored(true);
        armorCooldown = 200;
        armorTimeRemaining = 100;
        this.navigation.stop();
    }
    if (!level.isClientSide && isArmored() && !damageSrc.is(DamageTypeTags.BYPASSES_ARMOR)) {
        damageAmount *= 0.75;

        if (damageSrc.getEntity() != null && BlockUtil.distanceFrom(level, damageSrc.getEntity().position, this.position) <= 2.0 && !damageSrc.type().msgId().equals("thorns")) {
            damageSrc.getEntity().hurt(level.damageSources().thorns(this), 3.0f);
        }

    }
    super.actuallyHurt(damageSrc, damageAmount);
}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!(rayTraceResult.getEntity() instanceof LivingEntity livingEntity && world instanceof ServerLevel level))
        return;
    Vec3 vec = safelyGetHitPos(rayTraceResult);
    float damage = (float) (DAMAGE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier());

    if (!canDamage(livingEntity))
        return;
    this.damage(vec, level, shooter, livingEntity, spellStats, spellContext, resolver, damage);
    spawnCinders(shooter, level, rayTraceResult.getLocation().add(0, (rayTraceResult.getEntity().onGround() ? 1 : 0), 0), spellStats, spellContext, resolver);

    if (rayTraceResult.getEntity() instanceof LivingEntity living && living.hasEffect(ModPotions.BLAST_EFFECT)) {
        int amplifier = living.getEffect(ModPotions.BLAST_EFFECT).getAmplifier();
        living.removeEffect(ModPotions.BLAST_EFFECT);
        BlastEffect.explode(living, amplifier + 1);
    }
}

public static void onPlayerCloned(PlayerEvent.Clone event) {
    if (event.getEntity() instanceof ServerPlayer newServerPlayer && event.isWasDeath()) {
        event.getOriginal().getActiveEffects().forEach((effect -> {
            //IronsSpellbooks.LOGGER.debug("{}", effect.getEffect().getDisplayName().getString());
            if (effect.getEffect() instanceof SummonTimer) {
                newServerPlayer.addEffect(effect, newServerPlayer);
            }
        }));

        IronsSpellbooks.LOGGER.debug("onPlayerCloned: copy data: client: {}", newServerPlayer.level.isClientSide);
        MagicData oldMagicData = MagicData.getPlayerMagicData(event.getOriginal());
        MagicData newMagicData = MagicData.getPlayerMagicData(newServerPlayer);
        newMagicData.setSyncedData(oldMagicData.getSyncedData().getPersistentData(newServerPlayer));
        oldMagicData.getPlayerCooldowns().getSpellCooldowns().forEach((spellId, cooldown) -> newMagicData.getPlayerCooldowns().getSpellCooldowns().put(spellId, cooldown));
        //newMagicData.getSyncedData().syncToPlayer(newServerPlayer);
    }
}

