        LevelAttributeModifier.applyModifier(player, Attributes.ARMOR_TOUGHNESS, "Werewolf", newLevel, getMaxLevel(), WerewolvesConfig.BALANCE.PLAYER.werewolf_armor_toughness.get(), 0.5, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, false);
        LevelAttributeModifier.applyModifier(player, Attributes.ATTACK_DAMAGE, "Werewolf", newLevel, getMaxLevel(), WerewolvesConfig.BALANCE.PLAYER.werewolf_damage.get(), 0.5, AttributeModifier.Operation.ADD_VALUE, false);
        if (newLevel <= 0) {
            this.actionHandler.resetTimers();
            this.skillHandler.disableAllSkills();
        }
    } else {
        if (newLevel == 0) {
            this.actionHandler.resetTimers();
        }
    }
}

public void handleGUIButtonPress(String tag, boolean shiftHeld, ServerPlayer player) {
    ItemStack hammerStack = player.getItemInHand(hand);
    if (hammerStack.getItem() instanceof JackHammerItem) {
        if (tag.startsWith("digmode:")) {
            try {
                DrillBitItem.DrillBitType ourBit = JackHammerItem.getDrillBit(hammerStack);
                DigMode newDigMode = DigMode.valueOf(tag.substring(8));
                if (ourBit.getBitQuality() >= newDigMode.getBitType().getBitQuality() || newDigMode == DigMode.MODE_1X1) {
                    JackHammerItem.setDigMode(hammerStack, newDigMode);
                }
            } catch (IllegalArgumentException ignored) {
            }
        } else if (tag.equals("speed_cap")) {
            boolean capped = JackHammerItem.isSpeedCapped(hammerStack);
            hammerStack.set(ModDataComponents.JACKHAMMER_SPEED_CAPPED, !capped);
        }
    }
}

public void tick(Player player) {
	if (this.getThrown()) {
		if (player.onGround() || player.isSwimming() || player.isInWater()) {
			this.setThrown(player, false, null);
		}
	}
	if (this.throwCooldown > 0) {
		if (!player.level().isClientSide() && this.throwCooldown == THROW_COOLDOWN - 1) { // Actually throw the victim
			player.push(this.throwVector.x(), this.throwVector.y(), this.throwVector.z());

			if (player instanceof ServerPlayer server) {
				PacketDistributor.sendToPlayer(server, new MovePlayerPacket(this.throwVector.x(), this.throwVector.y(), this.throwVector.z()));
			}
			this.throwVector = Vec3.ZERO;
		}
		this.throwCooldown--;
	}
}

private void setChargingAtPlayer(boolean flag) {
	this.getEntityData().set(FLAG_CHARGING, flag);
	if (!this.level().isClientSide()) {
		if (flag) {
			if (!this.getAttribute(Attributes.ATTACK_DAMAGE).hasModifier(CHARGING_MODIFIER.id())) {
				this.getAttribute(Attributes.ATTACK_DAMAGE).addTransientModifier(CHARGING_MODIFIER);
			}
			if (this.getAttribute(Attributes.ARMOR).hasModifier(NON_CHARGING_ARMOR_MODIFIER.id())) {
				this.getAttribute(Attributes.ARMOR).removeModifier(NON_CHARGING_ARMOR_MODIFIER.id());
			}
		} else {
			this.getAttribute(Attributes.ATTACK_DAMAGE).removeModifier(CHARGING_MODIFIER.id());
			if (!this.getAttribute(Attributes.ARMOR).hasModifier(NON_CHARGING_ARMOR_MODIFIER.id())) {
				this.getAttribute(Attributes.ARMOR).addTransientModifier(NON_CHARGING_ARMOR_MODIFIER);
			}
		}
	}
}

public void tick() {
	LivingEntity target = this.taskOwner.getTarget();

	if (target.distanceToSqr(this.taskOwner) < 4096 && this.taskOwner.hasLineOfSight(target)) {
		this.attackCooldownTimer++;

		if (this.attackCooldownTimer == attackCooldownMin - taskOwner.getPreAttackTime())
			this.taskOwner.swing(InteractionHand.MAIN_HAND);

		if (this.attackCooldownTimer >= attackCooldownMin) {
			taskOwner.performRangedAttack(target, 0);
			attackCooldownTimer = -taskOwner.getRandom().nextInt(attackCooldownMax - attackCooldownMin);
		}
	}
	else if (this.attackCooldownTimer > 0) {
		this.attackCooldownTimer--;
	}
}

