protected void customServerAiStep() {
	super.customServerAiStep();

	if (this.nextChargerSpawn < this.tickCount) {
		LivingEntity target = getTarget();

		if (target != null) {
			ChargerEntity charger = EntitySpawningUtil.spawnEntity((ServerLevel)level(), AoAMonsters.CHARGER.get(), RandomUtil.positionWithinRange(target.blockPosition(), 40, 10, 40, 30, 0, 30, true, level(), 2, (state, statePos) -> true), MobSpawnType.MOB_SUMMONED);

			charger.getAttribute(Attributes.FOLLOW_RANGE).addTransientModifier(MINION_FOLLOW_RANGE_MOD);

			if (charger != null)
				BrainUtils.setTargetOfEntity(charger, target);
		}

		this.nextChargerSpawn = this.tickCount + RandomUtil.numberBetween(80, 140);
	}
}

private void popOre(boolean natural) {
	if(!natural && ToretoiseModule.regrowChance == 0)
		return;
	if(getOreType() == 0 && (natural || level().random.nextInt(ToretoiseModule.regrowChance) == 0)) {
		int ore = random.nextInt(ORE_TYPES) + 1;
		entityData.set(ORE_TYPE, ore);
		this.setBoundingBox(this.makeBoundingBox());

		if(!natural) {
			eatCooldown = ToretoiseModule.cooldownTicks;

			if(level() instanceof ServerLevel serverLevel) {
				serverLevel.sendParticles(ParticleTypes.CLOUD, getX(), getY() + 0.5, getZ(), 100, 0.6, 0.6, 0.6, 0);
				playSound(QuarkSounds.ENTITY_TORETOISE_REGROW, 10F, 0.7F);
			}
		}
	}
}

public void setEffectHoldersOfFlask(ItemStack stack, List<EffectHolder> effects)
{
	if (effects.isEmpty())
	{
		return;
	} else
	{
		CompoundTag compoundnbt = stack.getOrCreateTag();
		ListTag listnbt = new ListTag();

		for (EffectHolder effectHolder : effects)
		{
			listnbt.add(effectHolder.write(new CompoundTag()));
		}

		compoundnbt.put("effectholder", listnbt);
	}
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand)
{
	ItemStack stack = player.getItemInHand(hand);
	if (stack.getItem() instanceof ISigil.Holding)
		stack = ((Holding) stack.getItem()).getHeldItem(stack, player);
	if (PlayerHelper.isFakePlayer(player))
		return InteractionResultHolder.fail(stack);

	if (!world.isClientSide && !isUnusable(stack))
	{
		if (player.isShiftKeyDown())
			setActivatedState(stack, !getActivated(stack));
		if (getActivated(stack))
			return super.use(world, player, hand);
	}

	return super.use(world, player, hand);
}

