public boolean canUse() {
	Purpoid purpoid = this.purpoid;
	this.notMovingTicks = !purpoid.getMoveControl().hasWanted() ? this.notMovingTicks + 1 : 0;
	boolean canUse = false;
	if ((purpoid.forcedRelativeTeleportingPos != null || (this.notMovingTicks >= 20 && !purpoid.isBoosting() && !purpoid.hasTeleportCooldown())) && !purpoid.isPassenger() && purpoid.isNoEndimationPlaying()) {
		BlockPos teleportPos = this.generateTeleportPos(purpoid, purpoid.getRandom());
		Level level = purpoid.level();
		if (teleportPos != null && level.hasChunkAt(teleportPos)) {
			AABB collisionBox = purpoid.getDimensions(purpoid.getPose()).makeBoundingBox(teleportPos.getX() + 0.5F, teleportPos.getY(), teleportPos.getZ() + 0.5F);
			if (level.noCollision(collisionBox) && level.isUnobstructed(purpoid, Shapes.create(collisionBox)) && !level.containsAnyLiquid(collisionBox)) {
				this.beginTeleportation(purpoid, teleportPos);
				canUse = true;
			}
		}
	}
	purpoid.forcedRelativeTeleportingPos = null;
	return canUse;
}

private StructureStart getNearestStructure(BlockPos pos) {
    ServerLevel serverlevel = (ServerLevel) this.mob.level();
    try {
        StructureStart start = serverlevel.structureManager().getStructureWithPieceAt(pos, structureTagKey);
        if (start.isValid()) {
            return start;
        } else {
            BlockPos nearestOf = serverlevel.findNearestMapStructure(structureTagKey, pos, (int) (this.maximumDistance / 16), false);
            if (nearestOf == null || nearestOf.distToCenterSqr(this.mob.getX(), this.mob.getY(), this.mob.getZ()) > 256 || !serverlevel.isLoaded(nearestOf)) {
                return null;
            }
            return serverlevel.structureManager().getStructureWithPieceAt(nearestOf, structureTagKey);
        }
    } catch (Exception e) {
        AlexsCaves.LOGGER.warn(this.mob + " encountered an issue searching for a nearby structure.");
        errorCooldown = 2000 + this.mob.getRandom().nextInt(2000);
        return null;
    }
}

public boolean canUse() {
    if (!catfish.isInWaterOrBubble() || catfish.eatCooldown > 0) {
        return false;
    }
    if (executionCooldown > 0) {
        executionCooldown--;
    } else {
        executionCooldown = 50 + random.nextInt(50);
        if (!this.catfish.isFull()) {
            final List<Entity> list = catfish.level().getEntitiesOfClass(Entity.class, catfish.getBoundingBox().inflate(8, 8, 8), EntitySelector.NO_SPECTATORS.and(entity -> entity != catfish && catfish.isFood(entity)));
            list.sort(Comparator.comparingDouble(catfish::distanceToSqr));
            if (!list.isEmpty()) {
                food = list.get(0);
                return true;
            }
        }
    }
    return false;
}

public boolean hurt(DamageSource source, float amount) {
    boolean prev = super.hurt(source, amount);
    if (prev) {
        double range = 15;
        int fleeTime = 100 + getRandom().nextInt(5);
        this.revengeCooldown = fleeTime;
        List<? extends EntityEmu> list = this.level().getEntitiesOfClass(this.getClass(), this.getBoundingBox().inflate(range, range / 2, range));
        for (EntityEmu emu : list) {
            emu.revengeCooldown = fleeTime;
            if(emu.isBaby() && random.nextInt(2) == 0){
                emu.emuAttackedDirectly = this.getLastHurtByMob() != null;
                emu.revengeCooldown = emu.emuAttackedDirectly ? 10 + getRandom().nextInt(30) : fleeTime;
            }
        }
        emuAttackedDirectly = this.getLastHurtByMob() != null;
        this.revengeCooldown = emuAttackedDirectly ? 10 + getRandom().nextInt(30) : revengeCooldown;
    }
    return prev;
}

