private StructureStart getNearestStructure(BlockPos pos){
    ServerLevel serverlevel = (ServerLevel)this.mob.level();
    try{
        StructureStart start = serverlevel.structureManager().getStructureWithPieceAt(pos, structureTagKey);
        if(start.isValid()){
            return start;
        }else{
            BlockPos nearestOf = serverlevel.findNearestMapStructure(structureTagKey, pos, (int)(this.maximumDistance / 16), false);
            if(nearestOf == null || nearestOf.distToCenterSqr(this.mob.getX(), this.mob.getY(), this.mob.getZ()) > 256 || !serverlevel.isLoaded(nearestOf)){
                return null;
            }
            return serverlevel.structureManager().getStructureWithPieceAt(nearestOf, structureTagKey);
        }
    }catch (Exception e){
        AlexsMobs.LOGGER.warn(this.mob + " encountered an issue searching for a nearby structure.");
        errorCooldown = 2000 + this.mob.getRandom().nextInt(2000);
        return null;
    }
}

public boolean shouldExecute() {
	if(!this.isHoldingShield()) {
		return false;
	}

	target = crawler.getAttackTarget();

	if(target != null && !crawler.isSwingInProgress && crawler.hurtResistantTime <= Math.max(0, crawler.maxHurtResistantTime - 5)) {
		blockingCooldownCounter++;

		if(blockingCooldownCounterMax < 0) {
			blockingCooldownCounterMax = 4 + crawler.rand.nextInt(5);
		}

		return blockingCooldownCounter > blockingCooldownCounterMax;
	}

	return false;
}

public void updateCurrentArenaNode() {
    if(!this.hasArenaCenter())
        return;
    if(this.arenaNodeChangeCooldown > 0) {
        this.arenaNodeChangeCooldown--;
        return;
    }

    // Return to center with no target.
    if(this.getAttackTarget() == null || !this.getAttackTarget().isEntityAlive()) {
        this.setCurrentArenaNode(this.arenaNodeNetwork.centralNode);
        return;
    }

    if(this.currentArenaNode != null)
        this.setCurrentArenaNode(this.currentArenaNode.getClosestAdjacentNode(this.getAttackTarget().getPosition()));
    else
        this.setCurrentArenaNode(this.arenaNodeNetwork.getClosestNode(this.getAttackTarget().getPosition()));
}

