public boolean canUse() {
	if (this.cooldown > 0) {
		this.cooldown--;
	} else if (this.entity.getRandom().nextFloat() < 0.1F) {
		ChargerEetle chargerEetle = this.entity;
		LivingEntity attackTarget = chargerEetle.getTarget();
		if (attackTarget != null && attackTarget.isAlive() && !chargerEetle.isCatapultProjectile() && chargerEetle.onGround()) {
			Level world = chargerEetle.level();
			ChargerEetle closestCharger = world.getNearestEntity(world.getEntitiesOfClass(ChargerEetle.class, chargerEetle.getBoundingBox().inflate(2.5F), eetle -> {
				return eetle != chargerEetle && eetle.onGround() && !eetle.isBaby() && eetle.getTarget() == attackTarget && !eetle.isCatapulting() && attackTarget.distanceTo(eetle) >= MIN_DISTANCE;
			}), PREDICATE, null, chargerEetle.getX(), chargerEetle.getY(), chargerEetle.getZ());
			if (closestCharger != null) {
				chargerEetle.setCatapultingTarget(closestCharger);
				return true;
			}
		}
	}
	return false;
}

protected static void retaliate(Yak yak, LivingEntity target) {
	if (yak.getBrain().isActive(Activity.AVOID))
		return;

	Brain<Yak> brain = yak.getBrain();
	brain.eraseMemory(EnvironmentalMemoryModuleTypes.HERDING_POSITION.get());

	if (Sensor.isEntityAttackableIgnoringLineOfSight(yak, target)) {
		if (!BehaviorUtils.isOtherTargetMuchFurtherAwayThanCurrentAttackTarget(yak, target, 4.0D)) {
			if (target.getType() == EntityType.PLAYER && yak.level().getGameRules().getBoolean(GameRules.RULE_UNIVERSAL_ANGER)) {
				setAngerTargetToNearestTargetablePlayerIfFound(yak, target);
				broadcastUniversalAnger(yak);
			} else {
				setAngerTarget(yak, target);
				broadcastAngerTarget(yak, target);
			}
		}
	}
}

public void handleEnigmaticFlight(final Player player) {
	try {
		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ENIGMATIC_ITEM)) {
			this.flightMap.put(player, true);
			if (!player.getAbilities().mayfly) {
				player.getAbilities().mayfly = true;
				player.onUpdateAbilities();
			}
		} else if (this.flightMap.get(player)) {
			if (!player.isCreative()) {
				player.getAbilities().mayfly = false;
				player.getAbilities().flying = false;
				player.onUpdateAbilities();
			}
			this.flightMap.put(player, false);
		}
	} catch (NullPointerException ex) {
		this.flightMap.put(player, false);
	}
}

