public void tick() {
    if (parentEntity.getTarget() != null) {
        float width =  parentEntity.getTarget().getBbWidth() + parentEntity.getBbWidth() + 2;
        boolean isWithinReach = parentEntity.distanceToSqr(parentEntity.getTarget()) < width * width;
        if (parentEntity.isFlying() || isWithinReach) {
            this.parentEntity.getMoveControl().setWantedPosition(parentEntity.getTarget().getX(), parentEntity.getTarget().getY(), parentEntity.getTarget().getZ(), isWithinReach ? 1.6D : 1.0D);
        } else {
            this.parentEntity.getNavigation().moveTo(parentEntity.getTarget().getX(), parentEntity.getTarget().getY(), parentEntity.getTarget().getZ(), 1.2D);
        }
        if (parentEntity.getTarget().getY() > this.parentEntity.getY() + 1.2F) {
            parentEntity.setFlying(true);
        }
        if (parentEntity.dismountCooldown == 0 && parentEntity.getBoundingBox().inflate(0.3, 0.3, 0.3).intersects(parentEntity.getTarget().getBoundingBox()) && !isBittenByPhage(parentEntity.getTarget())) {
            parentEntity.startRiding(parentEntity.getTarget(), true);
            if (!parentEntity.level().isClientSide) {
                AlexsMobs.sendMSGToAll(new MessageMosquitoMountPlayer(parentEntity.getId(), parentEntity.getTarget().getId()));
            }
        }
    }
}

public boolean canUse() {
    if (EntityUnderminer.this.mineCooldown == 0 && EntityUnderminer.this.hasPick() && !EntityUnderminer.this.isHiding() && !EntityUnderminer.this.isActuallyInAWall() && EntityUnderminer.this.getRandom().nextInt(30) == 0) {
        List<BlockPos> obscuredOres = EntityUnderminer.this.getNearbyObscuredOres(16, 8);
        BlockPos nearest = null;
        double nearestDist = Double.MAX_VALUE;
        if (!obscuredOres.isEmpty()) {
            for (BlockPos obscuredPos : obscuredOres) {
                final double dist = EntityUnderminer.this.position().distanceTo(Vec3.atCenterOf(obscuredPos));
                if (nearestDist > dist) {
                    nearest = obscuredPos;
                    nearestDist = dist;
                }
            }
        }
        EntityUnderminer.this.mineAIFlag = false;
        minePretendPos = nearest;
        return minePretendPos != null;
    }
    return false;
}

private void teleportEntityFromDimension(Entity entity, ServerLevel endpointWorld, BlockPos endpoint, boolean b) {
    if (entity instanceof ServerPlayer) {
        ServerEvents.teleportPlayers.add(new Triple<>((ServerPlayer)entity, endpointWorld, endpoint));
        if(this.getSisterId() == null){
            createAndSetSister(endpointWorld, Direction.DOWN);
        }
    } else {
        entity.unRide();
        entity.setLevel(endpointWorld);
        Entity teleportedEntity = entity.getType().create(endpointWorld);
        if (teleportedEntity != null) {
            teleportedEntity.restoreFrom(entity);
            teleportedEntity.moveTo(endpoint.getX() + 0.5D, endpoint.getY() + 0.5D, endpoint.getZ() + 0.5D, entity.getYRot(), entity.getXRot());
            teleportedEntity.setYHeadRot(entity.getYHeadRot());
            teleportedEntity.setPortalCooldown();
            endpointWorld.addFreshEntity(teleportedEntity);
        }
        entity.remove(RemovalReason.DISCARDED);
    }
}

