public boolean canUse() {
    if (jumpCooldown > 0) {
        jumpCooldown--;
    }
    if (this.dolphin.getRandom().nextInt(this.chance) != 0 || dolphin.isVehicle()
        || dolphin.getTarget() != null) {
        return false;
    } else {
        Direction direction = this.dolphin.getMotionDirection();
        final int i = direction.getStepX();
        final int j = direction.getStepZ();
        BlockPos blockpos = this.dolphin.blockPosition();
        for (int k : JUMP_DISTANCES) {
            if (!this.canJumpTo(blockpos, i, j, k) || !this.isAirAbove(blockpos, i, j, k)) {
                return false;
            }
        }
        return true;
    }
}

public void start() {
    LivingEntity target = this.dolphin.getTarget();
    if (target != null) {
        final double distanceXZ = dolphin.distanceToSqr(target.getX(), dolphin.getY(), target.getZ());
        if (distanceXZ < 300) {
            dolphin.lookAt(target, 260, 30);
            final double smoothX = Mth.clamp(Math.abs(target.getX() - dolphin.getX()), 0, 1);
            final double smoothZ = Mth.clamp(Math.abs(target.getZ() - dolphin.getZ()), 0, 1);
            final double d0 = (target.getX() - this.dolphin.getX()) * 0.3 * smoothX;
            final double d2 = (target.getZ() - this.dolphin.getZ()) * 0.3 * smoothZ;
            final float up = 1F + dolphin.getRandom().nextFloat() * 0.8F;
            this.dolphin.setDeltaMovement(this.dolphin.getDeltaMovement().add(d0 * 0.3D, up, d2 * 0.3D));
            this.dolphin.getNavigation().stop();
            this.dolphin.jumpCooldown = dolphin.getRandom().nextInt(32) + 32;
        } else {
            dolphin.getNavigation().moveTo(target, 1.0F);
        }

    }
}

public void onCollideWithPlayer(EntityPlayer player) {
	if(this.playerUuid == null || this.playerUuid.equals(player.getUniqueID())) {
		if(this.xpValue < 0 && !this.world.isRemote && this.delayBeforeCanPickup == 0 && player.xpCooldown == 0) {
			if(net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(new net.minecraftforge.event.entity.player.PlayerPickupXpEvent(player, this))) {
				return;
			}

			player.xpCooldown = 2;
			player.onItemPickup(this, 1);

			this.xpValue = Math.min(this.xpValue + ItemRing.removeXp(player, -this.xpValue), 0);

			if(this.xpValue >= 0) {
				this.setDead();
			}
		} else {
			super.onCollideWithPlayer(player);
		}
	}
}

public void updateTask() {
	if(!this.mummy.isCharging()) {
