protected void updateWispStrengthModifier() {
	List<LocationSpiritTree> locations = BetweenlandsWorldStorage.forWorld(this.world).getLocalStorageHandler().getLocalStorages(LocationSpiritTree.class, this.getEntityBoundingBox(), loc -> loc.isInside(this));
	if(!locations.isEmpty()) {
		LocationSpiritTree location = locations.get(0);

		int activeWisps = location.getActiveWisps();
		int generatedWisps = location.getGeneratedWispPositions().size();

		float newModifier;
		if(activeWisps < generatedWisps) {
			newModifier = 0.5F + activeWisps / (float)generatedWisps * 0.5F;
		} else {
			newModifier = Math.min(1.0F + (activeWisps - generatedWisps) / 6.0F, 2.0F);
		}

		float decay = (float) Math.pow(this.getHealth() / this.getMaxHealth(), 6) * 0.33F;

		this.dataManager.set(WISP_STRENGTH_MODIFIER, decay * newModifier + (1 - decay) * this.dataManager.get(WISP_STRENGTH_MODIFIER));
	}
}

public static List<BlockStateMatcher> getSavedStates(Item.TooltipContext worldIn, ItemStack held) {
  List<BlockStateMatcher> st = new ArrayList<>();
  if (held.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag() != null && held.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag().contains(STATESTAG)) {
    //get it
    ListTag stateTags = held.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag().getList(STATESTAG, 10);
    for (int i = 0; i < stateTags.size(); ++i) {
      CompoundTag currTag = stateTags.getCompound(i);
      BlockState stateFound = NbtUtils.readBlockState(BuiltInRegistries.BLOCK.asLookup(), currTag);
      if (stateFound != null && !stateFound.isAir()) {
        BlockStateMatcher matcher = new BlockStateMatcher();
        matcher.setState(stateFound);
        if (currTag.contains(EXACT_TAG)) {
          matcher.setExactProperties(currTag.getBoolean(EXACT_TAG));
        }
        st.add(matcher);
      }
    }
  }
  return st;
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    float potency = spellStat.getPotency();
    if (WandUtil.enchantedFocus(caster)) {
        potency += WandUtil.getPotencyLevel(caster) / 2.0F;
    }
    List<CorruptedBeam> entities = worldIn.getEntitiesOfClass(CorruptedBeam.class, caster.getBoundingBox().inflate(2.0F),
            corruptedBeam -> corruptedBeam.getOwner() == caster);
    Vec3 vector3d = caster.getViewVector( 1.0F);
    if (entities.isEmpty()) {
        CorruptedBeam corruptedBeam = new CorruptedBeam(ModEntityType.CORRUPTED_BEAM.get(), worldIn, caster);
        corruptedBeam.moveTo(
                caster.getX() + vector3d.x / 2,
                caster.getEyeY() - 0.2,
                caster.getZ() + vector3d.z / 2, caster.getYRot(), caster.getXRot());
        corruptedBeam.setOwner(caster);
        corruptedBeam.setExtraDamage(potency);
        corruptedBeam.setItemBase(true);
        worldIn.addFreshEntity(corruptedBeam);
    }
