public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!canSummon(shooter))
        return;

    Vec3 vector3d = safelyGetHitPos(rayTraceResult);
    int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
    BlockPos pos = BlockPos.containing(vector3d);
    if (ticks <= 0) return;
    for (int i = 0; i < 3; ++i) {
        BlockPos blockpos = pos.offset(-2 + shooter.getRandom().nextInt(5), 2, -2 + shooter.getRandom().nextInt(5));
        EntityAllyVex vexentity = new EntityAllyVex(world, shooter);
        vexentity.moveTo(blockpos, 0.0F, 0.0F);
        vexentity.finalizeSpawn((ServerLevelAccessor) world, world.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null);
        vexentity.setOwner(shooter);
        vexentity.setBoundOrigin(blockpos);
        vexentity.setLimitedLife(ticks);
        summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, vexentity);
    }
    shooter.addEffect(new MobEffectInstance(ModPotions.SUMMONING_SICKNESS_EFFECT, ticks));
}

private void updateAttribute(Player player, Holder<Attribute> attribute, Identifier id, ToFloatFunction<Player> additionalSupplier) {
    AttributeInstance attributeInstance = player.getAttribute(attribute);
    if (attributeInstance != null) {
        AttributeModifier existing = attributeInstance.getModifier(id);
        float additional = additionalSupplier.applyAsFloat(player);
        if (existing != null) {
            if (existing.amount() == additional) {
                //If we already have it set to the correct value just exit
                //Note: We don't need to check for if it is equal to zero as we should never have the attribute applied then
                return;
            }
            //Otherwise, remove the no longer valid value, so we can add it again properly
            attributeInstance.removeModifier(id);
        }
        if (additional > 0) {
            //If we should have the attribute, but we don't have it set yet, or our stored amount was different, update
            attributeInstance.addTransientModifier(new AttributeModifier(id, additional, Operation.ADD_VALUE));
        }
    }
}

private void handleEating() {
    if (!this.isEating() && !this.isSleeping() && !this.getMainHandItem().isEmpty()) {
        this.eat(true);
    } else if (this.getMainHandItem().isEmpty()) {
        this.eat(false);
    }
    if (this.isEating()) {
        if (!this.level.isClientSide && this.getEatCounter() > 6000) {
            if (!this.getMainHandItem().isEmpty()) {
                if (!this.level.isClientSide) {
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                    this.gameEvent(GameEvent.EAT);
                }
            }
            this.eat(false);
            return;
        }
        this.setEatCounter(this.getEatCounter() + 1);
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
	boolean flag = !this.isBaby() && this.isTamed() && player.isSecondaryUseActive();
	if (!this.isVehicle() && !flag && !player.getItemInHand(hand).isEmpty() && !this.isTamed()) {
		if (this.isAngryAt(player)) {
			return InteractionResult.CONSUME;
		} else {
			this.makeMad();
			this.setTarget(player);
			return InteractionResult.sidedSuccess(this.level().isClientSide);
		}
	}

	if (!this.isVehicle() && !flag) {
		ItemStack itemstack = player.getItemInHand(hand);
		if (!itemstack.isEmpty() && this.isFood(itemstack)) {
			return this.fedFood(player, itemstack);
		}
	}
	return super.mobInteract(player, hand);
}

