	this.prevRotationPitch = this.rotationPitch = 0;
	this.prevRotationYaw = this.rotationYaw = this.dataManager.get(FACING).getHorizontalAngle();
	this.prevRenderYawOffset = this.renderYawOffset = this.dataManager.get(FACING).getHorizontalAngle();

	if (disappearTimer > 0 && disappearTimer < 8) disappearTimer++;

	if(!this.world.isRemote) {
		if (disappearTimer == 5) this.world.setEntityState(this, EVENT_DISAPPEAR);
		if (disappearTimer >= 8) setDead();

		List<EntityPlayer> nearPlayers = world.getEntitiesWithinAABB(EntityPlayer.class, getEntityBoundingBox().grow(4.5, 5, 4.5), e -> !e.capabilities.isCreativeMode && !e.isInvisible());
		if (disappearTimer == 0 && !nearPlayers.isEmpty()) {
			disappearTimer++;
			this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.GREEBLING_VANISH, SoundCategory.NEUTRAL, 1, 1);
			this.world.setEntityState(this, EVENT_START_DISAPPEARING);
		}
	}
}

	public boolean targetBlock(World world, BlockPos pos, EnumFacing face, ItemStack stack) {
		NBTTagCompound tagCompound = stack.getTagCompound();
		int dimension = tagCompound.getInteger("targetWorld");
		if (world.provider.getDimension() != dimension)
			return false;
		TileEntity tile = world.getTileEntity(pos);
		BlockPos targetPos = new BlockPos(tagCompound.getInteger("targetX"), tagCompound.getInteger("targetY"), tagCompound.getInteger("targetZ"));
		if (tile instanceof IEmberPacketProducer) {
			TileEntity targetTile = world.getTileEntity(targetPos);
			if (targetTile instanceof IEmberPacketReceiver) {
                ((IEmberPacketProducer) tile).setTargetPosition(targetPos, face);
                world.playSound(pos.getX(), pos.getY(), pos.getZ(), SoundEvents.BLOCK_ANVIL_LAND, SoundCategory.BLOCKS, 1.0f, 0.95f + Misc.random.nextFloat() * 0.1f, false);
				return true;
            }
        } else if (tile instanceof ITargetable) {
			ITargetable targetable = (ITargetable) tile;
			targetable.setTarget(targetPos);
			return true;
        }
		return false;
	}

