    if (entity instanceof EntityWolf)
    {
        EntityCreature entitycreature = (EntityCreature) entity;
        entitycreature.setAttackTarget(null);
        return false;
    }
    else
    {
        i = i - (getArmorType() + 2);
        if (i < 0)
        {
            i = 0;
        }
        return super.attackEntityFrom(damagesource, i);
    }
}

public boolean canCast(ItemStack stack, Spell spell, EntityPlayer caster, EnumHand hand, int castingTick, SpellModifiers modifiers){

	// Spells can only be cast if the casting events aren't cancelled...
	if(castingTick == 0){
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.WAND, spell, caster, modifiers))) return false;
	}else{
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Tick(Source.WAND, spell, caster, modifiers, castingTick))) return false;
	}

	int cost = (int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f); // Weird floaty rounding

	// As of wizardry 4.2 mana cost is only divided over two intervals each second
	if(spell.isContinuous) cost = getDistributedCost(cost, castingTick);

	// ...and the wand has enough mana to cast the spell...
	return cost <= this.getMana(stack) // This comes first because it changes over time
			// ...and the wand is the same tier as the spell or higher...
			&& spell.getTier().level <= this.tier.level
			// ...and either the spell is not in cooldown or the player is in creative mode
			&& (WandHelper.getCurrentCooldown(stack) == 0 || caster.isCreative());
}

public void releaseUsing(ItemStack stack, Level world, LivingEntity entity, int chargeTimer) {
  int charge = this.getUseDuration(stack, entity) - chargeTimer;
  float percentageCharged = BowItem.getPowerForTime(charge); //never zero, its from [0.03,1];
  if (percentageCharged < 0.1) {
    return; //not enough force to go with any realistic path
  }
  final int maxRadius = 32;
  int rad = (int) percentageCharged * maxRadius;
  for (BlockPos pos : LevelWorldUtil.findBlocksByTag(world, entity.blockPosition(), BlockTags.FIRE, rad + 1)) {
    world.setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
    ParticleUtil.spawnParticle(world, ParticleTypes.SNOWFLAKE, pos, 6);
  }
  for (BlockPos pos : LevelWorldUtil.findBlocksByTag(world, entity.blockPosition(), BlockTags.CAMPFIRES, rad + 1)) {
    BlockState cFire = world.getBlockState(pos);
    if (cFire.hasProperty(CampfireBlock.LIT)) {
      world.setBlock(pos, cFire.setValue(CampfireBlock.LIT, false), 3);
      ParticleUtil.spawnParticle(world, ParticleTypes.SNOWFLAKE, pos, 6);
    }
  }
  ItemStackUtil.damageItem(entity, stack);
}

protected boolean addPartialCharge(ItemStack containerStack, int slot, int chargeToAdd, int pointLimit, ItemStack chargeStack) {
	int worth = getSlotWorth(slot);
	int storedCharge = getMigratedStoredCharge(containerStack, slot);
	int currentCharge = getPartialCharge(containerStack, slot);
	long totalCharge = (long) storedCharge * worth + currentCharge;
	int remainingCapacity = Math.toIntExact(Math.max(pointLimit - totalCharge, 0));
	int acceptedCharge = Math.min(Math.max(chargeToAdd, 0), remainingCapacity);
	int updatedPartialCharge = currentCharge + acceptedCharge;
	if (updatedPartialCharge >= worth) {
		int maxPhysicalCharge = pointLimit / worth;
		int fullCharges = Math.min(updatedPartialCharge / worth, Math.max(maxPhysicalCharge - storedCharge, 0));
		if (fullCharges > 0) {
			ItemStack storedChargeStack = chargeStack.copy();
			storedChargeStack.setCount(fullCharges);
			addStoredCharge(containerStack, slot, fullCharges, storedChargeStack);
			updatedPartialCharge -= fullCharges * worth;
		}
	}
	setPartialCharge(containerStack, slot, updatedPartialCharge);
	return acceptedCharge > 0;
}

public void applyBlockEffect(Level pLevel, BlockPos pPos, LivingEntity pSource, int pAmplifier, int pAreaOfEffect) {
    Item axeItem = Items.STONE_AXE;
    if (pAmplifier == 1){
        axeItem = Items.IRON_AXE;
    } else if (pAmplifier == 2){
        axeItem = Items.DIAMOND_AXE;
    } else if (pAmplifier > 3){
        axeItem = Items.NETHERITE_AXE;
    }
    ItemStack axe = new ItemStack(axeItem);
    if (pLevel instanceof ServerLevel serverLevel) {
        if (pSource instanceof ServerPlayer serverPlayer) {
            for (BlockPos blockPos : this.getSquarePos(pPos, pAreaOfEffect + 3)) {
                BlockState blockState = serverLevel.getBlockState(blockPos.above());
                if (this.isTree(serverLevel, blockPos.above(), blockState)){
                    TimedEvents.submitTask("goety:brew_chop_tree", new BlockFinder.ChopTreeTask(serverPlayer.getUUID(), axe, serverLevel, blockPos));
                }
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    Vec3 vector3d = caster.getViewVector( 1.0F);
    MagicBolt soulBolt = new MagicBolt(worldIn,
            caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.2,
            caster.getZ() + vector3d.z / 2,
            vector3d.x,
            vector3d.y,
            vector3d.z);
    soulBolt.setOwner(caster);
    soulBolt.setExtraDamage(potency);
    soulBolt.setExtraDuration(duration);
    worldIn.addFreshEntity(soulBolt);
    this.playSound(worldIn, caster, 1.0F, 1.0F);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    float velocity = spellStat.getVelocity();
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)) {
        velocity += WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster) / 3.0F;
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    PoisonQuill poisonQuill = new PoisonQuill(worldIn, caster);
    poisonQuill.setSpear(rightStaff(staff), potency + 1);
    poisonQuill.shootFromRotation(caster, caster.getXRot(), caster.getYRot(), 0.0F, velocity, 1.0F);
    poisonQuill.setOwner(caster);
    poisonQuill.setExtraDamage(potency);
    poisonQuill.setDuration(duration);
    if (caster.isUnderWater()){
        poisonQuill.setAqua(true);
    }
    worldIn.addFreshEntity(poisonQuill);
    this.playSound(worldIn, caster, ModSounds.POISON_QUILL_VINE_SHOOT.get(), 1.0F, this.projPitch(worldIn.getRandom()));
}

