public void onServerReceived(MinecraftServer minecraftServer, ServerPlayer owner) {
    IPlayerCap cap = CapabilityRegistry.getPlayerDataCap(owner);
    if (cap == null)
        return;

    if (owner == null)
        return;

    IFamiliar familiarEntity = cap.getFamiliarData(familiarID).getEntity(owner.level);
    familiarEntity.setOwnerID(owner.getUUID());
    familiarEntity.getThisEntity().setPos(owner.getX(), owner.getY(), owner.getZ());

    FamiliarSummonEvent summonEvent = new FamiliarSummonEvent(familiarEntity.getThisEntity(), owner);
    NeoForge.EVENT_BUS.post(summonEvent);

    if (!summonEvent.isCanceled()) {
        owner.level.addFreshEntity(familiarEntity.getThisEntity());
        ParticleUtil.spawnPoof((ServerLevel) owner.level, familiarEntity.getThisEntity().blockPosition());
        cap.setLastSummonedFamiliar(familiarID);
    }
}

public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    int duration = (int) (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier());

    List<BlockPos> posList = SpellUtil.calcAOEBlocks(shooter, rayTraceResult.getBlockPos(), rayTraceResult, spellStats);
    for (BlockPos pos1 : posList) {
        if (world.getBlockEntity(pos1) != null || world.getBlockState(pos1).isAir()
                || world.getBlockState(pos1).is(BlockTagProvider.INTANGIBLE_BLACKLIST)
                || !canBlockBeHarvested(spellStats, world, pos1)
                || !BlockUtil.destroyRespectsClaim(getPlayer(shooter, (ServerLevel) world), world, pos1))
            continue;

        BlockState state = world.getBlockState(pos1);
        int id = Block.getId(state);
        world.setBlockAndUpdate(pos1, BlockRegistry.INTANGIBLE_AIR.defaultBlockState());
        IntangibleAirTile tile = ((IntangibleAirTile) world.getBlockEntity(pos1));
        if (tile != null) {
            tile.stateID = id;
            tile.maxLength = duration * 20;
        }
    }
}

public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {

    if (!canSummon(shooter))
        return;

    int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
    if (ticks <= 0)
        ticks = 20; //leave at least one second of life, since summon sick doesn't depend on it and short life horses can be useful (?)
    Vec3 hit = rayTraceResult.getLocation();
    for (int i = 0; i < 1 + Math.round(spellStats.getAoeMultiplier()); i++) {
        SummonHorse horse = new SummonHorse(ModEntities.SUMMON_HORSE.get(), world);
        horse.setPos(hit.x(), hit.y(), hit.z());
        horse.ticksLeft = ticks;
        horse.tameWithName((Player) shooter);
        horse.getHorseInventory().setItem(0, new ItemStack(Items.SADDLE));
        horse.setOwnerID(shooter.getUUID());
        horse.setDropChance(EquipmentSlot.CHEST, 0.0F);
        summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, horse);
    }
    applySummoningSickness(shooter, 30 * 20);
}

public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!canSummon(shooter) || shooter == null)
        return;
    Vec3 hit = rayTraceResult.getLocation();
    int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
    if (ticks <= 0) return;
    Holder<Biome> holder = world.getBiome(BlockPos.containing(rayTraceResult.getLocation()));
    var wolfVariant = WolfVariants.getSpawnVariant(world.registryAccess(), holder);
    for (int i = 0; i < 2; i++) {
        SummonWolf wolf = new SummonWolf(ModEntities.SUMMON_WOLF.get(), world);
        wolf.ticksLeft = ticks;
        wolf.setVariant(wolfVariant);
        wolf.setPos(hit.x(), hit.y(), hit.z());
        wolf.setTarget(shooter.getLastHurtMob() == null ? shooter.getLastHurtByMob() : shooter.getLastHurtMob());
        wolf.setAggressive(true);
        wolf.setTame(true, false);
        wolf.tame((Player) shooter);
        summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, wolf);
    }
    applySummoningSickness(shooter, ticks);
}

protected static void handleTicking(ItemStack itemStack, Level level, @NotNull Entity entity) {
    if (!level.isClientSide) {
        if (isLoading(itemStack)) {
            int i = getLoadingTicks(itemStack);
            if (i > (entity instanceof LivingEntity livingEntity ? getChargeDuration(itemStack, livingEntity) : 1.25f * 20 * 3)) {
                setLoading(itemStack, false);
                if (entity instanceof LivingEntity livingEntity && !isCharged(itemStack)) {
                    tryLoadProjectiles(livingEntity, itemStack);
                }
                SoundSource soundsource = entity instanceof Player ? SoundSource.PLAYERS : SoundSource.BLOCKS;
                if (isCharged(itemStack)) {
                    level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), SoundEvents.CROSSBOW_LOADING_END, soundsource, 1.0F, 1.0F / (level.getRandom().nextFloat() * 0.5F + 1.0F) + 0.2F);
                } else {
                    level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), SoundEvents.ITEM_BREAK, soundsource, 1.0F, 1.5F + 0.2F);
                }
            }
            i++;
            setLoadingTicks(itemStack, i);
        }
    }
}

public void tick() {
    super.tick();
    LivingEntity target = this.getTarget();
    if (lightcooldown > 0) {
        lightcooldown--;
    }

    if(this.isAlive()) {
        if (this.getAnimation() == DEEPLING_MELEE) {
            if (this.getAnimationTick() == 5) {
                this.playSound(ModSounds.DEEPLING_SWING.get(), 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                if (target != null) {
                    if (this.distanceTo(target) < 3.0F) {
                        float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                        target.hurt(damageSources().mobAttack(this), damage);
                    }
                }
            }
        }
    }
}

private <E extends IAnimatable> PlayState predicate(AnimationEvent<E> event) {
    if (this.stunnedTick > 0) {
        event.getController().setAnimation(new AnimationBuilder().addAnimation("rhino.stunned", true));
        event.getController().setAnimationSpeed(1.0F);
    } else if (event.isMoving()) {
        if (this.isSprinting()) {
            event.getController().setAnimation(new AnimationBuilder().addAnimation("rhino.run", true));
            event.getController().setAnimationSpeed(3.0F);
        } else {
            event.getController().setAnimation(new AnimationBuilder().addAnimation("rhino.walk", true));
            event.getController().setAnimationSpeed(1.0F);
        }
    } else if (this.hasChargeCooldown() && this.hasTarget()) {
        event.getController().setAnimation(new AnimationBuilder().addAnimation("rhino.foot", true));
        event.getController().setAnimationSpeed(1.0F);
    } else {
        event.getController().setAnimation(new AnimationBuilder().addAnimation("rhino.idle", true));
        event.getController().setAnimationSpeed(1.0F);
    }
    return PlayState.CONTINUE;
}

