public void loadFromBucketTag(CompoundTag tag) {
	super.loadFromBucketTag(tag);
	if (tag.contains("BucketVariantTag", CompoundTag.TAG_STRING)) {
		Optional.ofNullable(ResourceLocation.tryParse(tag.getString("BucketVariantTag")))
				.map(loc -> ResourceKey.create(UARegistries.PIKE_VARIANT, loc))
				.flatMap(key -> this.registryAccess().registryOrThrow(UARegistries.PIKE_VARIANT).getHolder(key))
				.ifPresent(this::setVariant);
		this.dropEatingLootCooldown = tag.getInt("EatingLootDropCooldown");
		if (tag.contains("ShouldDropItem")) {
			this.setToDropItem(tag.getBoolean("ShouldDropItem"));
		}
		if (tag.contains("IsLit")) {
			this.setLit(tag.getBoolean("IsLit"));
		}

		if (tag.contains("PikeHeldItem")) {
			this.startUsingItem(InteractionHand.MAIN_HAND);
			this.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse(tag.getString("PikeHeldItem")))));
		}
	}
}

private void setAttackTarget(Monster monster, Monster otherMonster) {
	if (monster != null && otherMonster != null && monster != otherMonster) {
		if (monster instanceof AbstractPiglin) {
			((AbstractPiglin)monster).getBrain().setMemory(MemoryModuleType.ATTACK_TARGET, otherMonster);
			monster.setTarget(otherMonster);
			monster.setLastHurtByMob(otherMonster);

			if (monster instanceof PiglinBrute) {
				PiglinBruteAi.wasHurtBy((PiglinBrute) monster, otherMonster);
			} else if (monster instanceof Piglin) {
				PiglinAi.wasHurtBy((Piglin) monster, otherMonster);
			}

			//monster.goalSelector.addGoal(1, new NearestAttackableTargetGoal<>(monster, Monster.class, true));
		} else if (monster instanceof NeutralMob) {
			((NeutralMob)monster).setTarget(otherMonster);
		} else {
			monster.setTarget(otherMonster);
			monster.setLastHurtByMob(otherMonster);
		}
	}
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    InteractionResult type = super.mobInteract(player, hand);
    if (!type.consumesAction() && canTargetItem(itemstack) && !this.fedCarrot) {
        if (!player.getAbilities().instabuild) {
            itemstack.shrink(1);
        }
        this.gameEvent(GameEvent.EAT);
        this.playSound(SoundEvents.CAT_EAT, this.getVoicePitch(), this.getSoundVolume());
        this.heal(5);
        if (itemstack.is(AMTagRegistry.TRIOPS_BREEDABLES)) {
            if (!this.level().isClientSide) {
                if (breedCooldown == 0) {
                    this.level().broadcastEntityEvent(this, (byte) 67);
                }
            }
            this.fedCarrot = true;
        }
        return InteractionResult.SUCCESS;
    }
    return Bucketable.bucketMobPickup(player, hand, this).orElse(type);
}

