public void onUpdate() {
	super.onUpdate();

	if (!this.world.isRemote) {
		if (this.aggroCooldown == 200 && !this.canAttack) {
			this.tasks.removeTask(this.aiRunAway);
			this.tasks.addTask(0, this.aiAttack);
			this.targetTasks.addTask(1, this.aiTarget);
			this.canAttack = true;
		}

		if (this.aggroCooldown == 0 && this.canAttack) {
			this.tasks.removeTask(this.aiAttack);
			this.targetTasks.removeTask(this.aiTarget);
			this.tasks.addTask(1, this.aiRunAway);
			this.canAttack = false;
		}

		if (this.aggroCooldown < 201)
			this.aggroCooldown++;
	}
}

protected Entity checkAreaOfEffect() {
	Entity entity = null;
	if (!getEntityWorld().isRemote && getEntityWorld().getDifficulty() != EnumDifficulty.PEACEFUL) {
		List<EntityPlayer> list = getEntityWorld().getEntitiesWithinAABB(EntityPlayer.class, getEntityBoundingBox());
		for (int entityCount = 0; entityCount < list.size(); entityCount++) {
			entity = list.get(entityCount);
			if (entity != null)
				if (entity instanceof EntityPlayer) {
					EntityPlayer player = (EntityPlayer) entity;
					if(!player.isSpectator() && !player.isCreative()) {
						player.addPotionEffect(new PotionEffect(MobEffects.BLINDNESS, 60));
						player.addPotionEffect(ElixirEffectRegistry.EFFECT_DECAY.createEffect(40, 1));
							IRotSmellCapability capSmell = player.getCapability(CapabilityRegistry.CAPABILITY_ROT_SMELL, null);
							if(capSmell != null)
								if(!capSmell.isSmellingBad())
									capSmell.setSmellingBad(Math.max(capSmell.getRemainingSmellyTicks(), 24000));
						}
					}
				}
			}
	return entity;
}

public void onUseTick(Level level, LivingEntity livingEntity, ItemStack stack, int remainingUseDuration) {
	if (!(livingEntity instanceof Player player)) {
		return;
	}
	if (getMode(stack) == Mode.ERUPTION && (player.isCreative() || getTotalCharge(stack, BLAZE_POWDER_SLOT) >= getBlazePowderCost())) {
		HitResult rayTraceResult = player.pick(12, 1, true);

		if (rayTraceResult.getType() == HitResult.Type.BLOCK) {
			remainingUseDuration -= 1;
			remainingUseDuration = getUseDuration(stack, livingEntity) - remainingUseDuration;

			BlockHitResult blockRayTraceResult = (BlockHitResult) rayTraceResult;
			doEruptionAuxEffects(player, blockRayTraceResult.getBlockPos().getX(), blockRayTraceResult.getBlockPos().getY(),
					blockRayTraceResult.getBlockPos().getZ());
			if (remainingUseDuration % 10 == 0 && !player.level().isClientSide()
					&& (player.isCreative() || useCharge(stack, BLAZE_POWDER_SLOT, getBlazePowderCost()))) {
				doEruptionEffect(player, blockRayTraceResult.getBlockPos().getX(), blockRayTraceResult.getBlockPos().getY(),
						blockRayTraceResult.getBlockPos().getZ());
			}
		}
	}
}

public void applyBlockEffect(Level pLevel, BlockPos pPos, LivingEntity pSource, int pAmplifier, int pAreaOfEffect) {
    for (BlockPos blockPos : this.getCubePos(pPos, pAreaOfEffect + 2)) {
        if (pLevel.getBlockState(blockPos).getBlock() instanceof LeavesBlock || pLevel.getBlockState(blockPos).is(BlockTags.LEAVES) || pLevel.getBlockState(blockPos).getBlock() instanceof WebBlock){
            if (pLevel.getBlockState(blockPos).canEntityDestroy(pLevel, blockPos, pSource)) {
                if (pAmplifier > 0) {
                    if (pLevel.getGameRules().getBoolean(GameRules.RULE_DOBLOCKDROPS) && !pLevel.restoringBlockSnapshots) {
                        ItemStack itemStack = new ItemStack(pLevel.getBlockState(blockPos).getBlock().asItem());
                        double d0 = (double) (pLevel.random.nextFloat() * 0.5F) + 0.25D;
                        double d1 = (double) (pLevel.random.nextFloat() * 0.5F) + 0.25D;
                        double d2 = (double) (pLevel.random.nextFloat() * 0.5F) + 0.25D;
                        ItemEntity itementity = new ItemEntity(pLevel, (double) blockPos.getX() + d0, (double) blockPos.getY() + d1, (double) blockPos.getZ() + d2, itemStack);
                        itementity.setDefaultPickUpDelay();
                        pLevel.addFreshEntity(itementity);
                    }
                    pLevel.setBlockAndUpdate(blockPos, Blocks.AIR.defaultBlockState());
                } else {
                    pLevel.destroyBlock(blockPos, true, pSource);
                }
            }
        }
    }
}

