}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    float velocity = spellStat.getVelocity();
    if (WandUtil.enchantedFocus(caster)) {
        potency += WandUtil.getPotencyLevel(caster);
        velocity += WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster);
    }
    Vec3 vector3d = caster.getViewVector(1.0F);
    double accuracy = 8.0D;
    Vec3 vec3 = (new Vec3(vector3d.x, vector3d.y, vector3d.z)).normalize().add(worldIn.random.triangle(0.0D, 0.0172275D * (double) accuracy), 0.0D, worldIn.random.triangle(0.0D, 0.0172275D * (double) accuracy));
    SpellHurtingProjectile steamMissile = new SteamMissile(
            caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.2,
            caster.getZ() + vector3d.z / 2,
            vec3.x,
            vec3.y,
            vec3.z, worldIn);
    steamMissile.setExtraDamage(potency);
    steamMissile.setBoltSpeed((int) velocity);
    steamMissile.setOwner(caster);
    worldIn.addFreshEntity(steamMissile);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float velocity = spellStat.getVelocity();
    if (WandUtil.enchantedFocus(caster)) {
        velocity = WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster) / 2.0F;
    }
    if (caster instanceof Player player){
        Projectile projectile = SEHelper.getGrappling(player);
        if (projectile != null) {
            projectile.discard();
            SEHelper.setGrappling(player, null);
            this.playSound(worldIn, player, SoundEvents.FISHING_BOBBER_RETRIEVE, 1.0F, 0.4F / (worldIn.getRandom().nextFloat() * 0.4F + 0.8F));
            worldIn.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.FISHING_BOBBER_RETRIEVE, this.getSoundSource(), 1.0F, 0.4F / (worldIn.getRandom().nextFloat() * 0.4F + 0.8F));
            this.trueCooldown = this.defaultSpellCooldown();
        } else {
            VineHook vineHook = new VineHook(worldIn, player, 2.5F + velocity);
            vineHook.setStaff(rightStaff(staff));
            worldIn.addFreshEntity(vineHook);
            this.playSound(worldIn, player, SoundEvents.FISHING_BOBBER_THROW, 0.5F, 0.4F / (worldIn.getRandom().nextFloat() * 0.4F + 0.8F));
            this.trueCooldown = 0;
        }
    }
}

public boolean hurtServer(ServerLevel level, DamageSource source, float amount) {
	if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
		if (!this.isActive() && amount > 0) {
			float yRot = this.getNearestViewDirection().toYRot();
			if (source.getDirectEntity() != null) {
				double d0 = source.getDirectEntity().getX() - this.getX();
				double d2 = source.getDirectEntity().getZ() - this.getZ();
				float rawRot = ((float)(Mth.atan2(d2, d0) * Mth.RAD_TO_DEG) - 90.0F);
				yRot = Math.round(rawRot / 90) * 90;
			}
			this.setYRot(this.yRotO = yRot);
			this.setYHeadRot(this.yHeadRotO = yRot);
			this.yBodyRot = this.yBodyRotO = yRot;
			this.jumpFromGround();
			this.setActive(true);
			this.hideCooldown = 200;
			return false;
		}
	}
	if (source.getWeaponItem() != null && source.getWeaponItem().is(ItemTags.BREAKS_DECORATED_POTS)) amount *= 2;
	return super.hurtServer(level, source, amount);
}

public void tick() {
    // For some fucking reason, Panda Bears stop long before reaching their target block
    this.taskOwner.getLookControl().setLookAt(this.targetPos.getX(), this.targetPos.getY() + 1.5F, this.targetPos.getZ(), 10f, (float)this.taskOwner.getMaxHeadXRot());
    if (!this.taskOwner.isSitting()) {
        this.taskOwner.getMoveControl().strafe(1, 0);
    }
    if (this.targetPos != null && this.taskOwner.distanceToSqr(targetPos.getX(), targetPos.getY(), targetPos.getZ()) < 5) {
        this.taskOwner.getLookControl().setLookAt(this.targetPos.getX(), this.targetPos.getY() + 1.5F, this.targetPos.getZ(), 10f, (float)this.taskOwner.getMaxHeadXRot());
        this.taskOwner.getNavigation().stop();
        this.taskOwner.setSitting(true);
        this.searchCooldown--;
        if (this.searchCooldown == 0) {
            this.searchCooldown = 100;
            this.taskOwner.level.destroyBlock(this.targetPos.above(), false);
            this.taskOwner.setAnimation(EntityBear.ATTACK_SWIPE);
            // TODO: Make the Panda hold the Bamboo and chew it
            this.taskOwner.addHunger(8);
            this.continueTask = false;
        }
    }
    super.tick();
}

public boolean canUse() {
    if (!FossilConfig.isEnabled(FossilConfig.BREEDING_DINOS)) {
        return false;
    }
    if (male.getGender() != Gender.MALE || !male.isAdult() || male.getMatingCooldown() > 0 || male.moodSystem.getMood() <= 50) {
        return false;
    }
    List<? extends Prehistoric> sameTypes = male.getNearbySpeciesMembers(64);
    if (sameTypes.size() + 1 >= male.data().maxPopulation()) {
        male.setMatingCooldown(male.getRandom().nextInt(5000) + 5000);
        return false;
    }
    double shortestDistance = Double.MAX_VALUE;
    for (Prehistoric sameType : sameTypes) {
        if (!male.canMate(sameType) || male.distanceToSqr(sameType) > shortestDistance) {
            continue;
        }
        female = sameType;
        shortestDistance = male.distanceToSqr(female);
    }
    return female != null;
}

public boolean canUse() {
    long l = dino.level.getGameTime();
    if (l - lastCanUseCheck < COOLDOWN_BETWEEN_CAN_USE_CHECKS) {
        return false;
    }
    lastCanUseCheck = l;
    if (dino.isFleeing() || dino.getTarget() != null || dino.getCurrentOrder() != OrderType.WANDER) {
        return false;
    }
    if (dino.moodSystem.getPlayingCooldown() > 0 || dino.moodSystem.getMood() >= 100) {
        return false;
    }
    target = findPlayTarget();
    if (target == null) {
        return false;
    }
    path = dino.getNavigation().createPath(target, 0);
    if (path != null) {
        return true;
    }
    return Util.canReachPrey(dino, target);
}

public @NotNull InteractionResult mobInteract(Player player, InteractionHand hand) {
    if (level.isClientSide) {
        return (isOwnedBy(player) || isTame()) ? InteractionResult.CONSUME : InteractionResult.PASS;
    }
    if (isTame()) {
        ItemStack stack = player.getItemInHand(hand);
        if (stack.is(Items.GOLD_NUGGET) && getHealth() < getMaxHealth()) {
            usePlayerItem(player, hand, stack);
            heal(2);
            gameEvent(GameEvent.MOB_INTERACT, eyeBlockPosition());
            return InteractionResult.SUCCESS;
        }
        if (isOwnedBy(player)) {
            setOrderedToSit(!isOrderedToSit());
            jumping = false;
            navigation.stop();
            setTarget(null);
            return InteractionResult.SUCCESS;
        }
    }
    return super.mobInteract(player, hand);
}

