public ItemStack run(ItemStack itemStack, LootContext context) {
    if (!itemStack.is(Items.MAP)) {
        return itemStack;
    } else {
        Vec3 lootPos = context.getOptionalParameter(LootContextParams.ORIGIN);
        if (lootPos != null) {
            ServerLevel level = context.getLevel();
            BlockPos nearestMapStructure = TotemHelper.getTotemNearPos(level, new BlockPos((int) lootPos.x, (int) lootPos.y, (int) lootPos.z), true)
                    .flatMap(x -> NearestVillage.get(x).getClosestVampireForest())
                    .orElse(null);

            if (nearestMapStructure != null) {
                ItemStack map = MapItem.create(level, nearestMapStructure.getX(), nearestMapStructure.getZ(), this.zoom, true, true);
                MapItem.renderBiomePreviewMap(level, map);
                MapItemSavedData.addTargetDecoration(map, nearestMapStructure, "+", this.mapDecoration);
                return map;
            }
        }

        return itemStack;
    }
}

private void spawnMinionAt() {
	// find a good spot
	LivingEntity targetedEntity = this.lich.getTarget();
	Vec3 minionSpot = this.lich.findVecInLOSOf(targetedEntity);

	if (minionSpot != null && this.lich.level() instanceof ServerLevelAccessor accessor) {
		// put a clone there
		LichMinion minion = new LichMinion(this.lich.level(), this.lich);
		minion.setPos(minionSpot.x(), minionSpot.y(), minionSpot.z());
		EventHooks.finalizeMobSpawn(minion, accessor, accessor.getCurrentDifficultyAt(BlockPos.containing(minionSpot)), EntitySpawnReason.MOB_SUMMONED, null);
		this.lich.level().addFreshEntity(minion);

		minion.setTarget(targetedEntity);

		minion.spawnAnim();
