public void stop() {
	if (!this.mob.getPassengers().isEmpty()) {
		Entity rider = this.mob.getPassengers().getFirst();
		HostileMountEvents.hostileDismount(rider);

		Vec3 throwVec = new Vec3(this.mob.getLookAngle().x() * 2.0D, 0.9, this.mob.getLookAngle().z() * 2.0D);

		if (rider instanceof Player player) {
			var attachment = player.getData(TFDataAttachments.YETI_THROWING);
			attachment.setThrown(player, true, this.mob);
			// Make it so other yetis won't try to pick us up for a bit, 10 seconds seems fair
			attachment.setThrowVector(throwVec);
			attachment.setThrowCooldown(player, YetiThrowAttachment.THROW_COOLDOWN);
			player.push(throwVec.x(), throwVec.y(), throwVec.z());

			if (player instanceof ServerPlayer server) {
				PacketDistributor.sendToPlayer(server, new MovePlayerPacket(throwVec.x(), throwVec.y(), throwVec.z()));
			}
		} else rider.push(throwVec.x(), throwVec.y(), throwVec.z());
	}
	super.stop();
}

public void performRangedAttack(LivingEntity target, float distanceFactor) {
	if (this.hasRock()) {
		ThrownBlock blocc = new ThrownBlock(this.level(), this.rock);
		blocc.setPos(this.getX(), this.getY() + this.getBbHeight(), this.getZ());


		double d0 = target.getX() - this.getX();
		double d1 = target.getBoundingBox().minY + target.getBbHeight() / 3.0F - blocc.getY();
		double d2 = target.getZ() - this.getZ();
		double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
		blocc.shoot(d0, d1 + d3 * 0.2D, d2, 1.6F, 4 - this.level().getDifficulty().getId());

		this.playSound(TFSounds.TROLL_THROWS_ROCK.get(), 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
		this.level().addFreshEntity(blocc);
		this.setHasRock(false);
		if (!this.getPassengers().isEmpty() && Objects.requireNonNull(this.getFirstPassenger()).getType() == TFEntities.THROWN_BLOCK.get()) {
			this.getFirstPassenger().discard();
		}
		this.rockCooldown = 300 + this.getRandom().nextInt(100);
		this.rock = null;
	}
}

public void onUse(World world, LivingEntity livingEntity, ItemStack itemStack, int ticksRemaining) {
  if (!world.isRemote) {
    int enchantmentLevel = EnchantmentHelper.getEnchantmentLevel(Enchantments.QUICK_CHARGE, itemStack);
    SoundEvent soundEvent = this.getSoundEvent(enchantmentLevel);
    SoundEvent soundEvent1 = enchantmentLevel == 0 ? SoundEvents.ITEM_CROSSBOW_LOADING_MIDDLE : null;
    float fractionCharged = (itemStack.getUseDuration() - ticksRemaining) / (float)getChargeTime(itemStack);
    if (fractionCharged < 0.2F) {
      this.isLoadingStart = false;
      this.isLoadingMiddle = false;
    }

    if (fractionCharged >= 0.2F && !this.isLoadingStart) {
      this.isLoadingStart = true;
      world.playSound((PlayerEntity)null, livingEntity.getPosX(), livingEntity.getPosY(), livingEntity.getPosZ(), soundEvent, SoundCategory.PLAYERS, 0.5F, 1.0F);
    }

    if (fractionCharged >= 0.5F && soundEvent1 != null && !this.isLoadingMiddle) {
      this.isLoadingMiddle = true;
      world.playSound((PlayerEntity)null, livingEntity.getPosX(), livingEntity.getPosY(), livingEntity.getPosZ(), soundEvent1, SoundCategory.PLAYERS, 0.5F, 1.0F);
    }
  }
}

public void onUseTick(Level level, LivingEntity livingEntity, ItemStack stack, int remainingUseDuration) {
	if (!level.isClientSide) {
		ChargingSounds chargeSounds = getChargingSounds(stack);
		float chargeTime = (float)(stack.getUseDuration(livingEntity) - remainingUseDuration) / (float)getTimeToReload(stack, livingEntity);

		if (chargeTime < 0.2F) {
			this.startSoundPlayed = false;
			this.midLoadSoundPlayed = false;
		}
		else if (chargeTime >= 0.2F) {
			if (!this.startSoundPlayed) {
				this.startSoundPlayed = true;
				chargeSounds.start().ifPresent((sound) -> SoundBuilder.at(sound, livingEntity).volume(0.5f).play());
			}

			if (chargeTime >= 0.5f && !this.midLoadSoundPlayed) {
				this.midLoadSoundPlayed = true;
				chargeSounds.mid().ifPresent((sound) -> SoundBuilder.at(sound, livingEntity).volume(0.5f).play());
			}
		}
	}
}

public ItemStack quickMoveStack(@NotNull Player playerIn, int index) {
	ItemStack activeStack = ItemStack.EMPTY;
	Slot slot = this.slots.get(index);

	if(slot != null && slot.hasItem()) {
		ItemStack stackInSlot = slot.getItem();
		activeStack = stackInSlot.copy();

		if(index < totalSlots) {
			if(!this.moveItemStackTo(stackInSlot, totalSlots, slots.size(), true))
				return ItemStack.EMPTY;
		} else if(!this.moveItemStackTo(stackInSlot, 0, totalSlots, false))
			return ItemStack.EMPTY;

		if(stackInSlot.isEmpty())
			slot.set(ItemStack.EMPTY);
		else
			slot.setChanged();
	}

	return activeStack;
}

public void addPerkStack(ItemStack stack, Player player) {
    ArmorPerkHolder perkHolder = PerkUtil.getPerkHolder(armorStack);
    if (perkHolder == null) {
        PortUtil.sendMessage(player, Component.translatable("ars_nouveau.perk.set_armor"));
        return;
    }
    if (this.perkList.size() >= 3 || this.perkList.size() >= perkHolder.getSlotsForTier(armorStack).size()) {
        PortUtil.sendMessage(player, Component.translatable("ars_nouveau.perk.max_perks"));
        return;
    }
    PerkSlot foundSlot = getAvailableSlot(perkHolder);
    if (stack.getItem() instanceof PerkItem perkItem) {
        IPerk perk = perkItem.perk;
        if (foundSlot != null && perk.validForSlot(foundSlot, armorStack, player)) {
            this.perkList.add(stack.split(1));
            if (newPerkTimer <= 0) {
                newPerkTimer = 40;
            }
            updateBlock();
        }
    }
}

