        if (world.isClientSide) {
          ParticleUtil.spawnParticleBeam(world, ParticleTypes.PORTAL, oldPos, newPos, RANGE.get());
          SoundUtil.playSound(player, SoundRegistry.WARP_ECHO.get());
        }
      }
    }
  }
}

