public void onFOVUpdate(ComputeFovModifierEvent event) {
    Player player = event.getPlayer();
    if (player.isUsingItem()) {
        ItemStack itemStack = player.getUseItem();
        CastOptional.cast(itemStack.getItem(), ModularBowItem.class)
                .ifPresent(item -> {
                    float progress = item.getProgress(itemStack, player);
                    if (progress > 1.0F) {
                        progress = 1.0F;
                    } else {
                        progress = progress * progress;
                    }

                    event.setNewFovModifier((event.getNewFovModifier() - progress * 0.15F));
                });
    }

    if (player.isCrouching()) {
        ItemStack itemStack = player.getMainHandItem();
        CastOptional.cast(itemStack.getItem(), ModularBowItem.class)
                .ifPresent(item -> event.setNewFovModifier(event.getNewFovModifier() / getZoom(item, itemStack)));
    }
}

public void applyEntityEffect(LivingEntity pTarget, @Nullable Entity pSource, @Nullable Entity pIndirectSource, int pAmplifier){
    LivingEntity livingEntity = pIndirectSource instanceof LivingEntity living ? living : null;
    DamageSource damageSource = livingEntity != null ? pTarget.damageSources().mobAttack(livingEntity) : pTarget.damageSources().sweetBerryBush();
    if (pTarget instanceof Animal animal){
        if (animal.level.getServer() != null) {
            LootTable loottable = animal.level.getServer().getLootData().getLootTable(animal.getLootTable());
            LootParams.Builder lootcontext$builder = MobUtil.createLootContext(damageSource, animal).withLuck(pAmplifier);
            LootParams ctx = lootcontext$builder.create(LootContextParamSets.ENTITY);
            for (int i = 0; i < pAmplifier + 1; ++i) {
                for (ItemStack itemStack : loottable.getRandomItems(ctx)) {
                    if (!itemStack.getItem().isEdible() && !itemStack.isEmpty()) {
                        if (animal.hurt(damageSource, animal.getMaxHealth() / 4.0F)) {
                            itemStack.setCount(1);
                            ItemEntity item = ItemHelper.itemEntityDrop(animal, itemStack);
                            item.setDefaultPickUpDelay();
                            animal.level.addFreshEntity(item);
                        }
                    }
                }
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int amount = SpellConfig.BulwarkShieldAmount.get();
    int duration = SpellConfig.BulwarkShieldTime.get();
    if (WandUtil.enchantedFocus(caster)) {
        amount += WandUtil.getPotencyLevel(caster);
        duration *= Math.min(4, WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1);
    }
    amount += spellStat.getPotency();
    if (spellStat.getDuration() > 0){
        duration = spellStat.getDuration();
    }
    LivingEntity target = this.getTarget(caster);
    if (isShifting(caster) && target != null){
        if (MobUtil.areAllies(target, caster)){
            MiscCapHelper.setShields(target, amount);
            MiscCapHelper.setShieldTime(target, duration);
        }
    } else {
        MiscCapHelper.setShields(caster, amount);
        MiscCapHelper.setShieldTime(caster, duration);
    }
    this.playSound(worldIn, caster, ModSounds.SHIELD_UP.get(), 3.0F, caster.getVoicePitch());
}

