private void updateArmour(float newArmour) {
    newArmour = Mth.clamp(newArmour, 0, MAX_ARMOUR);
    int oldArmourStage = Mth.ceil(getSynchedData(ARMOUR) / MAX_ARMOUR * 4);
    int newArmourStage = Mth.ceil(newArmour / MAX_ARMOUR * 4);

    setSynchedData(ARMOUR, newArmour);

    float armourPercent = getArmourPercent();

    AttributeUtil.applyTransientModifier(this, Attributes.ARMOR, getArmourMod(armourPercent));
    AttributeUtil.applyTransientModifier(this, Attributes.ARMOR_TOUGHNESS, getArmourToughnessMod(armourPercent));

    if (oldArmourStage != newArmourStage) {
        SoundBuilder.following(AoASounds.STONE_CRUMBLE, this)
                .play();
        ParticleBuilder.forRandomPosInEntity(ParticleTypes.DUST_PLUME, this)
                .lifespan(20)
                .colourTint(0.5f, 0.5f, 0.5f, 1f)
                .spawnNTimes(20)
                .addTransition(AwayFromPositionParticleTransition.create(position().add(0, getBbHeight() * 0.5f, 0), 10))
                .sendToAllPlayersTrackingEntity(this);
    }
}

protected void doMeleeEffect(ItemStack stack, LivingEntity target, LivingEntity attacker, float attackCooldown) {
	if (!attacker.level().isClientSide && !EntityUtil.isImmuneToSpecialAttacks(target) && RandomUtil.percentChance(0.1f * attackCooldown)) {
		List<LivingEntity> nearbyMobs = EntityRetrievalUtil.getEntities(target, 5, LivingEntity.class, nearby -> EntityUtil.areProbablyEnemies(nearby, attacker));

		if (nearbyMobs.size() > 1) {
			EffectBuilder builder = new EffectBuilder(MobEffects.BLINDNESS, 60);
			LivingEntity newTarget = null;

			for (LivingEntity nearbyMob : nearbyMobs) {
				if ((newTarget = nearbyMob) != target)
					break;
			}

			if (newTarget == null)
				return;

			target.setLastHurtByMob(newTarget);
			BrainUtils.setTargetOfEntity(target, newTarget);

			EntityUtil.applyPotions(target, attacker, builder);
		}
	}
}

public void inventoryTick(ItemStack stack, Level world, Entity entity, int slot, boolean held) {
	if (!(entity instanceof Player)) {
		return;
	}

	int ticksTillExpire = ItemNBTHelper.getInt(stack, TAG_TICKS_TILL_EXPIRE, 0);
	int ticksCooldown = ItemNBTHelper.getInt(stack, TAG_TICKS_COOLDOWN, 0);

	if (ticksTillExpire == 0) {
		ItemNBTHelper.setInt(stack, TAG_TARGET, -1);
		ItemNBTHelper.setDouble(stack, TAG_DIST, -1);
	}

	if (ticksCooldown > 0) {
		ticksCooldown--;
	}

	if (ticksTillExpire >= 0) {
		ticksTillExpire--;
	}
	ItemNBTHelper.setInt(stack, TAG_TICKS_TILL_EXPIRE, ticksTillExpire);
	ItemNBTHelper.setInt(stack, TAG_TICKS_COOLDOWN, ticksCooldown);
}

