private void handleEating() {
    if (!this.isEating() && this.isSitting() && !this.isSleeping() && !this.getMainHandItem().isEmpty() && this.random.nextInt(80) == 1) {
        this.eat(true);
    } else if (this.getMainHandItem().isEmpty() || !this.isSitting()) {
        this.eat(false);
    }
    if (this.isEating()) {
        this.addEatingParticles();
        if (!this.level.isClientSide && this.getEatCounter() > 40) {
            if (this.isFood(this.getItemBySlot(EquipmentSlot.MAINHAND))) {
                if (!this.level.isClientSide) {
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                    this.gameEvent(GameEvent.EAT);
                    this.setSheared(false);
                }
                this.setSitting(false);
            }
            this.eat(false);
            return;
        }
        this.setEatCounter(this.getEatCounter() + 1);
    }
}

public boolean canUse() {
	if (this.taskOwner.hasFollowers()) {
		return false;
	} else if (this.taskOwner.isBaby()) {
		return false;
	} else if (this.taskOwner.hasGroupLeader()) {
		return true;
	} else if (this.cooldown > 0) {
		--this.cooldown;
		return false;
	} else {
		this.cooldown = this.getNewCooldown(this.taskOwner);
		Predicate<AgedHerdDinosaurEntity> predicate = (dinosaur) -> {
			return dinosaur.canBeFollowed() || !dinosaur.hasGroupLeader();
		};
		List<? extends AgedHerdDinosaurEntity> list = this.taskOwner.level().getEntitiesOfClass(this.taskOwner.getClass(), this.taskOwner.getBoundingBox().inflate(8.0D, 8.0D, 8.0D), predicate);
		AgedHerdDinosaurEntity dinosaurEntity = DataFixUtils.orElse(list.stream().filter(AgedHerdDinosaurEntity::canBeFollowed).findAny(), this.taskOwner);
		dinosaurEntity.addFollowers(list.stream().filter((dinosaur) -> {
			return !dinosaur.hasGroupLeader();
		}));
		return this.taskOwner.hasGroupLeader();
	}
}

public void start() {
	cooldown = MIN_INTERVAL + mob.getRandom().nextInt(MAX_INTERVAL - MIN_INTERVAL);

	int minX = mob.getPatrolMinBlockX();
	int maxX = mob.getPatrolMaxBlockX();
	int minZ = mob.getPatrolMinBlockZ();
	int maxZ = mob.getPatrolMaxBlockZ();

	int targetX, targetZ;
	if (!mob.isInsidePatrolChunk()) {
		targetX = (minX + maxX) / 2;
		targetZ = (minZ + maxZ) / 2;
	} else {
		targetX = minX + mob.getRandom().nextInt(16);
		targetZ = minZ + mob.getRandom().nextInt(16);
	}

	BlockPos candidate = new BlockPos(targetX, (int) mob.getY(), targetZ);
	BlockPos groundPos = findGround(mob.level(), candidate);
	if (groundPos != null) {
		mob.getNavigation().moveTo(groundPos.getX() + 0.5, groundPos.getY(), groundPos.getZ() + 0.5, 1.0D);
	}
}

