public boolean shouldExecute() {
	if(!crawler.isChief()) {
		return false;
	}

	ItemStack heldItem = crawler.getItemStackFromSlot(EntityEquipmentSlot.OFFHAND);
	if (heldItem.isEmpty()) {
		return false;
	} else if(!heldItem.getItem().isShield(heldItem, this.crawler)) {
		return false;
	}

	if(crawler.getAttackTarget() != null) {
		if(chargeCooldownMax < 0) {
			chargeCooldownMax = 80 + crawler.rand.nextInt(90);
		}

		chargeCooldown++;

		return chargeCooldown > chargeCooldownMax;
	}

	return false;
}

public void applyBlockBreakEffects(ItemStack itemStack, Level world, BlockState state, BlockPos pos, LivingEntity entity) {
    if (!world.isClientSide) {
        int intuitLevel = getEffectLevel(itemStack, ItemEffect.intuit);
        if (intuitLevel > 0) {
            int xp = state.getExpDrop(world, world.getRandom(), pos, EnchantmentHelper.getItemEnchantmentLevel(Enchantments.BLOCK_FORTUNE, itemStack),
                    EnchantmentHelper.getItemEnchantmentLevel(Enchantments.SILK_TOUCH, itemStack));
            if (xp > 0) {
                tickHoningProgression(entity, itemStack, xp * intuitLevel);
            }
        }

        int jankLevel = getEffectLevel(itemStack, ItemEffect.janking);
        if (jankLevel > 0) {
            JankEffect.jankItemsDelayed((ServerLevel) world, pos, jankLevel, getEffectEfficiency(itemStack, ItemEffect.janking), entity);
        }

        int skulkTaintLevel = getEffectLevel(itemStack, ItemEffect.sculkTaint);
        if (skulkTaintLevel > 0) {
            SculkTaintEffect.perform((ServerLevel) world, pos, skulkTaintLevel, getEffectEfficiency(itemStack, ItemEffect.sculkTaint));
        }

        DataEffectsHandler.applyBreakBlockEffects(itemStack, entity, pos);
    }
}

public void onUseTick(Level world, LivingEntity entity, ItemStack itemStack, int count) {
    if (!world.isClientSide) {
        int drawDuration = getReloadDuration(itemStack);
        float f = getProgress(itemStack, entity);

        if (f < 0.2F) {
            isLoadingStart = false;
            isLoadingMiddle = false;
        }

        if (f >= 0.2F && !isLoadingStart) {
            isLoadingStart = true;
            world.playSound(null, entity.getX(), entity.getY(), entity.getZ(), getSoundEvent(drawDuration), SoundSource.PLAYERS, 0.5F, 1.0F);
        }

        if (f >= 0.5F && drawDuration <= 28 && !isLoadingMiddle) {
            isLoadingMiddle = true;
            if (drawDuration > 21) {
                world.playSound(null, entity.getX(), entity.getY(), entity.getZ(), SoundEvents.CROSSBOW_LOADING_MIDDLE,
                        SoundSource.PLAYERS, 0.5F, 1.0F);
            }
        }
    }
}

public static void finishItemEvents(LivingEntityUseItemEvent.Finish event){
    if (event.getItem().getItem() == Items.MILK_BUCKET){
        if (event.getEntity().hasEffect(GoetyEffects.SOUL_ARMOR.get())){
            event.getEntity().removeEffect(GoetyEffects.SOUL_ARMOR.get());
        }
    }
    if (event.getItem().is(ModTags.Items.BREWABLE_FOOD)){
        for(MobEffectInstance mobeffectinstance : PotionUtils.getMobEffects(event.getItem())) {
            if (mobeffectinstance.getEffect().isInstantenous()) {
                mobeffectinstance.getEffect().applyInstantenousEffect(event.getEntity(), event.getEntity(), event.getEntity(), mobeffectinstance.getAmplifier(), 1.0D);
            } else {
                event.getEntity().addEffect(new MobEffectInstance(mobeffectinstance));
            }
        }
        for (BrewEffectInstance brewEffectInstance : BrewUtils.getBrewEffects(event.getItem())){
            brewEffectInstance.getEffect().drinkBlockEffect(event.getEntity(), event.getEntity(), event.getEntity(), brewEffectInstance.getAmplifier(), BrewUtils.getAreaOfEffect(event.getItem()));
        }
    }
    if (!(event.getItem().getItem() instanceof IWand)) {
        if (event.getEntity().hasEffect(GoetyEffects.SHADOW_WALK.get())) {
            event.getEntity().removeEffect(GoetyEffects.SHADOW_WALK.get());
        }
    }
}

