private void applyEffect(GemInstance inst, LivingEntity target) {
    int cooldown = this.getCooldown(inst.purity());
    if (cooldown != 0 && AbilityCooldowns.isOnCooldown(target, makeUniqueId(inst), cooldown)) {
        return;
    }
    EffectData data = this.values.get(inst.purity());
    MobEffectInstance effectInst = target.getEffect(this.effect);
    if (this.stackOnReapply && effectInst != null) {
        if (inst != null) {
            int duration = Math.max(effectInst.getDuration(), data.duration);
            int amp = Math.min(this.stackingLimit, effectInst.getAmplifier() + 1 + data.amplifier);
            var newInst = new MobEffectInstance(this.effect, duration, amp, effectInst.isAmbient(), effectInst.isVisible());
            effectInst.update(newInst);
            ((LivingEntityInvoker) target).callOnEffectUpdated(effectInst, true, null);
            effectInst.onEffectStarted(target);
        }
    }
    else {
        target.addEffect(data.build(this.effect));
    }
    if (cooldown != 0) {
        AbilityCooldowns.startCooldown(target, makeUniqueId(inst));
    }
}

public void chargeItem() {
    ItemStack chargeable = ITEM_TO_CHARGE.getItemStack(this);
    IEnergyStorage itemEnergyHandler = chargeable.getCapability(Capabilities.EnergyStorage.ITEM);

    if (itemEnergyHandler != null) {
        if (itemEnergyHandler.getEnergyStored() == itemEnergyHandler.getMaxEnergyStored()) {
            ITEM_CHARGED.setStackInSlot(this, chargeable);
            ITEM_TO_CHARGE.setStackInSlot(this, ItemStack.EMPTY);
        } else {
            int energyToInsert = Math.min(
                    itemEnergyHandler.getMaxEnergyStored() - itemEnergyHandler.getEnergyStored(),
                    Math.max(getEnergyStorage().getEnergyStored(), getEnergyStorage().getMaxEnergyUse()));

            if (energyToInsert > 0) {
                int taken = getEnergyStorage().consumeEnergy(energyToInsert, true);
                int accepted = itemEnergyHandler.receiveEnergy(taken, true);
                itemEnergyHandler.receiveEnergy(accepted, false);
                getEnergyStorage().consumeEnergy(accepted, false);
                this.progress = (float) itemEnergyHandler.getEnergyStored()
                        / itemEnergyHandler.getMaxEnergyStored();
            }
        }
    }
}

private void playChargeSounds(Level level, LivingEntity entity, ItemStack stack, InteractionHand hand, int elapsed) {
    float progress;

    if (!CrossbowItem.isCharged(stack)) {
        progress = (float) elapsed / getChargeDurationMod(stack, level);
    } else {
        ItemStack otherStack = entity.getItemInHand(hand == InteractionHand.MAIN_HAND ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND);
        if (!canUseDoubleCrossbow(entity) || !(otherStack.getItem() instanceof HunterCrossbowItem otherCrossbow) || CrossbowItem.isCharged(otherStack)) return;
        progress = (float) (elapsed - getChargeDurationMod(stack, level)) / otherCrossbow.getChargeDurationMod(otherStack, level);
    }

    if (progress < 0.2F) {
        this.chargeStartSoundPlayed = false;
        this.chargeMidSoundPlayed = false;
    }
    if (progress >= 0.2F && !this.chargeStartSoundPlayed) {
        this.chargeStartSoundPlayed = true;
        level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), SoundEvents.CROSSBOW_LOADING_START, SoundSource.PLAYERS, 0.5F, 1.0F);
    }
    if (progress >= 0.5F && !this.chargeMidSoundPlayed) {
        this.chargeMidSoundPlayed = true;
        level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), SoundEvents.CROSSBOW_LOADING_MIDDLE, SoundSource.PLAYERS, 0.5F, 1.0F);
    }
}

	public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, @NotNull InteractionHand handIn) {
		ItemStack itemstack = playerIn.getItemInHand(handIn);

		if(!worldIn.isClientSide) {
			BlockPos blockpos = ((ServerLevel) worldIn).findNearestMapStructure(WraithModule.soulBeadTargetTag, playerIn.blockPosition(), 100, false);

			if(blockpos != null) {
				if (!playerIn.isCreative()) itemstack.shrink(1);
				SoulBead entity = new SoulBead(WraithModule.soulBeadType, worldIn);

				Vec3 look = playerIn.getLookAngle();
				entity.setPos(playerIn.getX() + look.x * 2, playerIn.getY() + 0.25, playerIn.getZ() + look.z * 2);
				worldIn.addFreshEntity(entity);

                entity.setTarget(blockpos.getX(), blockpos.getZ());

