public @Nullable CrabState tick() {

    var pos = alakarkinos.getHome();
    if (pos == null) {
        return new DecideCrabActionState(alakarkinos);
    }

    var radius = 5;
    for (BlockPos pos1 : BlockPos.withinManhattan(pos, radius, 3, radius)) {
        var state = alakarkinos.level.getBlockState(pos1);
        var consumable = AlakarkinosConversionRegistry.isConvertable(state.getBlock());
        if (!consumable)
            continue;
        var path = alakarkinos.getNavigation().createPath(pos1, 2);
        if (path == null || !path.canReach()) {
            continue;
        }
        return new PlaceHatState(alakarkinos, PlaceHatState.findHatPos(alakarkinos), pos1);
    }

    alakarkinos.findBlockCooldown = 100 + alakarkinos.level.random.nextInt(100);

    return new DecideCrabActionState(alakarkinos);
}

public void onServerReceived(MinecraftServer minecraftServer, ServerPlayer owner) {
    IPlayerCap cap = CapabilityRegistry.getPlayerDataCap(owner);
    if (cap == null)
        return;

    if (PacketDispelFamiliars.dispelForPlayer(owner)) {
        return;
    }

    FamiliarData lastSummoned = cap.getLastSummonedFamiliar();
    if (lastSummoned == null)
        return;
    IFamiliar familiarEntity = lastSummoned.getEntity(owner.level);
    familiarEntity.setOwnerID(owner.getUUID());
    familiarEntity.getThisEntity().setPos(owner.getX(), owner.getY(), owner.getZ());

    FamiliarSummonEvent summonEvent = new FamiliarSummonEvent(familiarEntity.getThisEntity(), owner);
    NeoForge.EVENT_BUS.post(summonEvent);

    if (!summonEvent.isCanceled()) {
        owner.level.addFreshEntity(familiarEntity.getThisEntity());
        ParticleUtil.spawnPoof((ServerLevel) owner.level, familiarEntity.getThisEntity().blockPosition());
    }
}

public boolean doHurtTarget(ServerLevel serverLevel, Entity entity) {
    DamageSource damagesource = this.damageSources().sting(this);
    boolean flag = entity.hurtServer(serverLevel, damagesource, (float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE)));
    if (flag) {
        if (this.level() instanceof ServerLevel serverlevel) {
            EnchantmentHelper.doPostAttackEffects(serverlevel, entity, damagesource);
        }

        if (entity instanceof LivingEntity livingentity) {
            livingentity.setStingerCount(livingentity.getStingerCount() + 1);
            int i = 10;
            if (this.level().getDifficulty() == Difficulty.NORMAL) {
                i = 20;
            } else if (this.level().getDifficulty() == Difficulty.HARD) {
                i = 30;
            }
            livingentity.addEffect(new MobEffectInstance(MobEffects.POISON, i * 20, 0), this);
        }

        this.playSound(SoundEvents.BEE_STING, 1.0F, 1.0F);
    }

    return flag;
}

public static void tick(Level level, BlockPos pos, BlockState state, PuffBugHiveTileEntity hive) {
	if (!level.isClientSide && !hive.hiveOccupants.isEmpty()) {
		if (hive.ticksTillResetTeleport > 0) {
			hive.ticksTillResetTeleport--;
		} else if (hive.shouldReset) {
			hive.hiveOccupants.forEach(occupent -> occupent.teleportSide = null);
			hive.shouldReset = false;
		}

		if (hive.teleportCooldown > 0) {
			hive.teleportCooldown--;
		}

		for (int i = 0; i < hive.hiveOccupants.size(); i++) {
			HiveOccupantData hiveOccupant = hive.hiveOccupants.get(i);

			if (hiveOccupant.occupant == null) {
				hive.hiveOccupants.remove(i);
			} else {
				hiveOccupant.tick(level);
			}
		}
	}
}

public void alertPuffBugs(@Nullable LivingEntity breaker) {
	this.hiveOccupants.forEach((Occupant) -> {
		PuffBug puffBug = Occupant.getOccupant(this.level);
		BlockPos hivePos = this.worldPosition;
		if (puffBug != null) {
			if (puffBug.getTarget() == null) {
				puffBug.setAttachedHiveSide(Direction.UP);
				puffBug.tryToTeleportToHive(hivePos);
			}

			if (breaker == null) {
				LivingEntity target = DetectionHelper.getClosestEntity(this.level.getEntitiesOfClass(LivingEntity.class, new AABB(hivePos).inflate(12.0D), PuffBug.CAN_ANGER), hivePos.getX(), hivePos.getY(), hivePos.getZ());
				if (target != null && puffBug.getTarget() == null) {
					puffBug.setTarget(target);
				}
			} else {
				puffBug.setTarget(breaker);
				puffBug.setHivePos(null);
			}
		}
	});

	this.addTeleportCooldown();
}

public void setBaby(boolean child) {
	boolean wasChild = this.isBaby();
	this.entityData.set(CHILD, child);
	this.updateGoals(this.goalSelector, this.targetSelector, child);
	if (child) {
		this.xpReward = 2;
		if (this.level() != null && !this.level().isClientSide) {
			AttributeInstance maxHealth = this.getAttribute(Attributes.MAX_HEALTH);
			if (maxHealth != null) {
				maxHealth.addTransientModifier(LEETLE_HEALTH);
				this.setHealth(Math.max(this.getHealth(), this.getMaxHealth()));
			}
		}
	} else {
		this.xpReward = 6;
		if (wasChild) {
			AttributeInstance maxHealth = this.getAttribute(Attributes.MAX_HEALTH);
			if (maxHealth != null) {
				maxHealth.removeModifier(LEETLE_HEALTH);
			}
			this.setHealth(Math.min(this.getMaxHealth(), this.getHealth() * 4.3F));
		}
	}
}

default void handleStepSound(BlockPos pos, BlockState state) {
	AbstractHorse horse = (AbstractHorse) this;

	if (!state.liquid()) {
		BlockState blockstate = horse.level().getBlockState(pos.above());
		SoundType soundtype = state.getSoundType(horse.level(), pos, horse);
		if (blockstate.is(Blocks.SNOW)) {
			soundtype = blockstate.getSoundType(horse.level(), pos, horse);
		}

		if ((horse.isVehicle() || horse.getMoveControl().getSpeedModifier() > 1.6D) && this.canGallop()) {
			this.setGallopSoundCounter(this.getGallopSoundCounter() + 1);
			if (this.getGallopSoundCounter() > 5 && this.getGallopSoundCounter() % 3 == 0) {
				this.playZebroidGallopSound(soundtype);
			} else if (this.getGallopSoundCounter() <= 5) {
				horse.playSound(SoundEvents.HORSE_STEP_WOOD, soundtype.getVolume() * 0.15F, soundtype.getPitch());
			}
		} else if (soundtype == SoundType.WOOD) {
			horse.playSound(SoundEvents.HORSE_STEP_WOOD, soundtype.getVolume() * 0.15F, soundtype.getPitch());
		} else {
			horse.playSound(SoundEvents.HORSE_STEP, soundtype.getVolume() * 0.15F, soundtype.getPitch());
		}
	}
}

