public void activateNukeVirus(int pos) {
    int neighbour = getHackedNeighbour(pendingNukePos);
    if (neighbour >= 0) {
        boolean found = false;
        Node neighbourNode = getNodeAt(neighbour);
        if (neighbourNode != null) {
            for (Pair<Integer, Float> conn : neighbourNode.outGoingHacks) {
                if (conn.getLeft() == pendingNukePos) {
                    conn.setValue(1f);
                    found = true;
                }
            }
            if (!found) {
                neighbourNode.outGoingHacks.add(Pair.of(pendingNukePos, 1f));
            }
            Node node = getNodeAt(pos);
            if (node != null) {
                node.setHackProgress(pos, 1f, false);
            }
            if (controller != null) controller.getHacker().playSound(SoundEvents.GENERIC_EXPLODE.value(), 1f, 1f);
            nukeVirusCooldown = 60;
        }
    }
    pendingNukePos = -1;
}

protected boolean spawnMyBoss(ServerLevel level) {
	Lich myCreature = this.makeMyCreature(level);

	BlockPos.MutableBlockPos mutableBlockPos = this.getBlockPos().mutable();
	while (true) {
		if (level.getMinY() >= mutableBlockPos.getY()) break;
		if (level.getBlockState(mutableBlockPos.below()).isAir()) {
			mutableBlockPos.move(Direction.DOWN);
		} else break;
	}

	mutableBlockPos.move(Direction.UP);

	myCreature.snapTo(mutableBlockPos, level.getRandom().nextFloat() * 360F, 0.0F);

	EventHooks.finalizeMobSpawn(myCreature, level, level.getCurrentDifficultyAt(mutableBlockPos), EntitySpawnReason.SPAWNER, null);
	myCreature.setAttackCooldown(40);
	myCreature.setExtinguishTimer();

	// set creature's home to this
	myCreature.setRestrictionPoint(GlobalPos.of(myCreature.level().dimension(), mutableBlockPos));

	// spawn it
	return level.addFreshEntity(myCreature);
}

default Function2<ItemStack, Integer, Integer> getItemColorFunction() {
	return (stack, tintIndex) -> {
		if (tintIndex != 0) return 0xFFFFFF;
		if (!stack.hasTagCompound())
			return Color.HSBtoRGB(MathHelper.sin(Minecraft.getMinecraft().world.getTotalWorldTime() / 140f), 0.75f, 1f);

		long lastCast = NBTHelper.getLong(stack, NBT.LAST_CAST, -1);
		int decayCooldown = NBTHelper.getInt(stack, NBT.LAST_COOLDOWN, -1);
		long tick = Minecraft.getMinecraft().world.getTotalWorldTime();
		long timeSinceCooldown = tick - lastCast;
		float decayStage = (decayCooldown > 0) ? ((float) timeSinceCooldown) / decayCooldown : 1f;


		float rand = NBTHelper.getFloat(stack, NBT.RAND, -1);
		float hue = rand < 0 ? (tick / 140f) % 140f : rand;
		float pow = Math.min(1f, Math.max(0f, getQuality(stack)));

		double decaySaturation = (lastCast == -1 || decayCooldown <= 0 || decayStage >= 1f) ? 1f :
				(decayStage < decayCurveDelimiter) ? Math.pow(Math.E, -15 * decayStage) : Math.pow(Math.E, 3 * decayStage - 3);

		float saturation = curveConst * (1 - (float) Math.pow(Math.E, -pow)) * (float) decaySaturation;

		return Color.HSBtoRGB(hue, saturation, 1f);
	};
}

