public void setJetpackState(UUID uuid, boolean isActive, boolean isLocal) {
    boolean alreadyActive = isJetpackOn(uuid);
    boolean changed = alreadyActive != isActive;
    if (alreadyActive && !isActive) {
        // On -> off
        activeJetpacks.remove(uuid);
    } else if (!alreadyActive && isActive) {
        // Off -> on
        activeJetpacks.add(uuid);
    }

    LevelAccessor level = level();
    // If something changed, and we're in a remote world, take appropriate action
    if (changed && level.isClientSide()) {
        // If the player is the "local" player, we need to tell the server the state has changed
        if (isLocal) {
            PacketUtils.sendToServer(new PacketGearStateUpdate(GearType.JETPACK, uuid, isActive));
        }

        // Start a sound playing if the person is now flying
        if (isActive && MekanismConfig.client.enablePlayerSounds.get()) {
            SoundHandler.startSound(level, uuid, SoundType.JETPACK);
        }
    }
}

protected void checkForCloseRangeAttack (double distance){
    this.tyrannosaurus.setAggro(distance <= 60);

    int r = (this.tyrannosaurus.getRandom().nextInt(100) + 1);
    if (distance <= 30) {
        if (r <= 20) {
            this.tyrannosaurus.setAnimationState(21);
        }
        else if (r <= 40) {
            this.tyrannosaurus.setAnimationState(22);
        }
        else if (r <= 60) {
            this.tyrannosaurus.setAnimationState(23);
        }
        else if (r <= 80) {
            this.tyrannosaurus.setAnimationState(24);
        }
        else {
            this.tyrannosaurus.setAnimationState(25);
        }
    }
    if (distance > 30 && this.tackleCooldown <= 0 && !this.tyrannosaurus.isInWater()) {
        this.tyrannosaurus.setAnimationState(26);
    }
}

public void tick() {
    if (cooldown > 0) {
        cooldown--;
    }
    if (flightTarget != null) {
        this.telecrex.setFlying(true);
        this.telecrex.getMoveControl().setWantedPosition(flightTarget.x, flightTarget.y, flightTarget.z, 1.25F);
        if(cooldown == 0 && this.telecrex.isTargetBlocked(flightTarget)){
            cooldown = 30;
            flightTarget = null;
        }
    }

    if (targetEntity != null) {
        if (this.telecrex.onGround() || flightTarget == null || this.telecrex.distanceToSqr(flightTarget) < 3 ) {
            final Vec3 vec = this.telecrex.getBlockInViewAway(targetEntity.position(), 0);
            if (vec != null && vec.y() > this.telecrex.getY()) {
                flightTarget = vec;
            }
        }
        if (this.telecrex.distanceTo(targetEntity) > 20.0F) {
            this.stop();
        }
    }
}

public void rideTick() {
    Entity mount = this.getVehicle();

    if (this.isPassenger() && !mount.isAlive()) {
        this.stopRiding();
    } else if (mount instanceof Player player && this.isPassenger()) {
        this.setDeltaMovement(0, 0, 0);
        //this.yBodyRot = ((LivingEntity) player).yBodyRot;
        //this.setYRot(player.getYRot());
        //this.yHeadRot = ((LivingEntity) player).yHeadRot;
        //this.yRotO = ((LivingEntity) player).yHeadRot;
        float radius = 0F;
        float angle = (0.01745329251F * (player.yBodyRot - 180F));
        double extraX = radius * Mth.sin((float) (Math.PI + angle));
        double extraZ = radius * Mth.cos(angle);
        playPanicSound();
        this.setPos(player.getX() + extraX, Math.max(player.getY() + player.getBbHeight() + 0.1, player.getY()), player.getZ() + extraZ);
        if (!player.isAlive() || rideCooldown == 0 || player.isShiftKeyDown() || !mount.isAlive()) {
            this.stopRiding();
        }
    } else {
        super.rideTick();
    }

}

public boolean processInteract(EntityPlayer player, EnumHand hand) {
	ItemStack stack = player.getHeldItem(hand);
	player.swingArm(hand);
	if(!getIsTransforming() && getHasHatched()) {
		if (!stack.isEmpty() && !checkFoodEqual(stack, getFoodCraved())) {
			getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_HATCHLING_NO, SoundCategory.NEUTRAL, 1F, 1F);
				return false;
		}
		if (!stack.isEmpty() && getIsHungry()) {

			if (checkFoodEqual(stack, getFoodCraved())) {
				if (!player.capabilities.isCreativeMode) {
					stack.shrink(1);
					if (stack.getCount() <= 0)
						player.setHeldItem(hand, ItemStack.EMPTY);
				}
				setEatingCooldown(MAX_EATING_COOLDOWN);
				setAmountEaten(getAmountEaten() + 1);
				getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_HATCHLING_EAT, SoundCategory.NEUTRAL, 1F, 1F);
				setIsHungry(false);
				return true;
			}
		}
	}
	return super.processInteract(player, hand);
}

