public void triggerChargedAbility(ItemStack itemStack, Level world, LivingEntity entity, int ticksUsed) {
    if (entity instanceof Player) {
        HitResult rayTrace = Minecraft.getInstance().hitResult;

        LivingEntity target = Optional.ofNullable(rayTrace)
                .filter(rayTraceResult -> rayTraceResult.getType() == HitResult.Type.ENTITY)
                .map(rayTraceResult -> ((EntityHitResult) rayTraceResult).getEntity())
                .flatMap(hitEntity -> CastOptional.cast(hitEntity, LivingEntity.class))
                .orElse(null);

        BlockPos targetPos = Optional.ofNullable(rayTrace)
                .filter(rayTraceResult -> rayTraceResult.getType() == HitResult.Type.BLOCK)
                .map(rayTraceResult -> ((BlockHitResult) rayTraceResult).getBlockPos())
                .orElse(null);

        Vec3 hitVec = Optional.ofNullable(rayTrace)
                .map(HitResult::getLocation)
                .orElse(null);

        InteractionHand activeHand = entity.getUsedItemHand();

        TetraMod.packetHandler.sendToServer(new ChargedAbilityPacket(target, targetPos, hitVec, activeHand, ticksUsed));

        handleChargedAbility((Player) entity, activeHand, target, targetPos, hitVec, ticksUsed);
    }
}

public boolean canUse() {
    this.chargeTarget = this.charger.getTarget();

    if (this.charger.tickCount < this.coolDown){
        return false;
    } else if (this.chargeTarget == null) {
        return false;
    } else {
        double distance = this.charger.distanceTo(this.chargeTarget);
        if (distance < this.minRange || distance > this.maxRange) {
            return false;
        } else if (!this.charger.onGround()) {
            return false;
        } else {
            Vec3 chargePos = findChargePoint(this.charger, this.chargeTarget);
            boolean canSeeTarget = this.charger.getSensing().hasLineOfSight(this.chargeTarget);
            if (!canSeeTarget) {
                return false;
            } else {
                this.chargePos = chargePos;

                return this.chance == 0 || this.charger.getRandom().nextInt(this.chance + 1) == 0;
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        potency += WandUtil.getPotencyLevel(caster);
    }
    LivingEntity target = this.getTarget(caster);
    AABB aabb = caster.getBoundingBox().inflate(4.0D);
    if (isShifting(caster) && target != null){
        if (MobUtil.areAllies(target, caster)){
            target.addEffect(new MobEffectInstance(GoetyEffects.CHILL_HIDE.get(), MathHelper.secondsToTicks(45 * duration), potency));
            aabb = target.getBoundingBox().inflate(4.0D);
        }
    } else {
        caster.addEffect(new MobEffectInstance(GoetyEffects.CHILL_HIDE.get(), MathHelper.secondsToTicks(45 * duration), potency));
    }
    if (this.rightStaff(staff)){
        for (LivingEntity livingEntity : worldIn.getEntitiesOfClass(LivingEntity.class, aabb)) {
            if (MobUtil.areAllies(livingEntity, caster) && livingEntity != caster) {
                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.CHILL_HIDE.get(), MathHelper.secondsToTicks(45 * duration), potency));
            }
        }
    }
    this.playSound(worldIn, caster, ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 0.5F);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float potency = SpellConfig.LeechingDamage.get().floatValue() * WandUtil.damageMultiply();
    int range = spellStat.getRange();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster) / 2.0F;
        range += WandUtil.getRangeLevel(caster);
    }
    potency += spellStat.getPotency();
    LivingEntity target = this.getTarget(caster, range);
    if (target != null){
        ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_RED);
        Vec3 targetVec = new Vec3(target.getX(), target.getY() + (target.getBbHeight() / 2.0F), target.getZ());
        Vec3 casterVec = new Vec3(caster.getRandomX(1.0F), caster.getEyeY(), caster.getRandomZ(1.0F));
        worldIn.sendParticles(new GatherTrailParticleOption(colorUtil, casterVec), targetVec.x, targetVec.y, targetVec.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
        for (int i = 0; i < 8; ++i) {
            targetVec = new Vec3(target.getRandomX(1.0F), target.getRandomY(), target.getRandomZ(1.0F));
            worldIn.sendParticles(new AbsorbTrailParticleOption(casterVec, 11141120, 10), targetVec.x, targetVec.y, targetVec.z, 1, 0.0, 0.0, 0.0, 0.0);
        }
        if (target.hurt(ModDamageSource.lifeLeech(caster, caster), potency)) {
            if (this.rightStaff(staff)){
                target.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 60, 0));
            }
            this.playSound(worldIn, caster, ModSounds.SOUL_EAT.get());
        }
    }
}

