private void equipBestMeleeWeapon() {
    // switch to the carried melee weapon with the highest attack damage
    int bestSlot = 0;
    double bestDmg = 0;
    for (int i = 0; i < attacker.getInv().getSlots(); i++) {
        ItemStack stack = attacker.getInv().getStackInSlot(i);
        if (!stack.isEmpty()) {
            AttributeInstance damage = new AttributeInstance(Attributes.ATTACK_DAMAGE, c -> {});
            stack.getAttributeModifiers().forEach(EquipmentSlot.MAINHAND, (attr, mod) -> {
                if (attr.is(Attributes.ATTACK_DAMAGE)) {
                    damage.addTransientModifier(mod);
                }
            });
            float modified = EnchantmentHelper.modifyDamage((ServerLevel) attacker.level(), stack, attacker.getTarget(), attacker.damageSources().mobAttack(attacker), (float) damage.getValue());
            if (modified > bestDmg) {
                bestDmg = modified;
                bestSlot = i;
            }
        }
    }
    if (bestSlot != 0) {
        ItemStack copy = attacker.getInv().getStackInSlot(0).copy();
        attacker.getInv().setStackInSlot(0, attacker.getInv().getStackInSlot(bestSlot));
        attacker.getInv().setStackInSlot(bestSlot, copy);
    }
}

public static IHackableEntity<?> getHackableForEntity(Entity entity, Player player) {
    HackManager manager = getInstance(player.level());

    // prune the tracked entities map every 60 ticks, removing dead or no-longer-hackable entities
    if (player.level().getGameTime() - 60 > manager.lastEntityPrune) {
        manager.hackableEntities.entrySet().removeIf(
                entry -> !entry.getKey().isAlive()
                        || !entry.getValue().canHack(entry.getKey(), player) && !isInDisplayCooldown(entry.getValue(), entry.getKey())
        );
        manager.lastEntityPrune = player.level().getGameTime();
    }

    // entities which implement IHackableEntity directly
    if (entity instanceof IHackableEntity<?> h && h.canHack(entity, player))
        return h;

    // entities which have been registered with the hack manager
    IHackableEntity<?> hackable = manager.hackableEntities.get(entity);
    if (hackable == null) {
        hackable = CommonArmorRegistry.getInstance().getHackable(entity, player);
        if (hackable != null) {
            manager.hackableEntities.put(entity, hackable);
        }
    }
    return hackable;
}

	public void tick() {
		if (!this.lich.isShadowClone()) {
			this.lich.getAllClones().forEach(clone -> {
				clone.setAttackCooldown(this.lich.getAttackCooldown());
				clone.setTeleportInvisibility(this.lich.getTeleportInvisibility());
			});
		}

		if (this.lich.getTeleportInvisibility() > 0) return;

		if (!this.lich.isShadowClone()) {
			LivingEntity targetedEntity = this.lich.getTarget();

			if (this.lich.getAttackCooldown() == 60) {
				if (!this.lich.teleportToNewTarget(targetedEntity, this.attackRange, this)) this.lich.teleportHome();
			} else if (targetedEntity != null && this.lich.getAttackCooldown() == 0) {
				if (this.lich.distanceTo(targetedEntity) < this.attackRange) {
					this.attack(this.lich);
                    for (Lich clone : this.lich.getAllClones()) {
						clone.setTarget(this.lich.getTarget());
						this.attack(clone);
                    }
                }
			}
		} else this.checkForMaster();
	}

static void deflectProjectile(ProjectileImpactEvent event, HitResult hitResult, Projectile projectile) {
    if (hitResult.getType() == HitResult.Type.ENTITY && hitResult instanceof EntityHitResult entityHitResult) {
        if (entityHitResult.getEntity() instanceof LivingEntity impactedLiving) {
            if (projectile.getType().is(AetherTags.Entities.DEFLECTABLE_PROJECTILES)) {
                SlotEntryReference slotResult = EquipmentUtil.getAccessory(impactedLiving, AetherItems.SHIELD_OF_REPULSION.get());
                if (slotResult != null) {
                    Vec3 motion = impactedLiving.getDeltaMovement();
                    if (impactedLiving instanceof Player player) {
                        var data = player.getData(AetherDataAttachments.AETHER_PLAYER);
                        if (!data.isMoving() || (data.isMoving() && motion.x() == 0.0 && (motion.y() == ConstantsUtil.DEFAULT_DELTA_MOVEMENT_Y || motion.y() == 0.0) && motion.z() == 0.0)) {
                            if (player.level().isClientSide()) { // Values used by the Shield of Repulsion screen overlay vignette.
                                data.setProjectileImpactedMaximum(150);
                                data.setProjectileImpactedTimer(150);
                            }
                            handleDeflection(event, projectile, player, slotResult);
                        }
                    } else {
                        if (motion.x() == 0.0 && (motion.y() == ConstantsUtil.DEFAULT_DELTA_MOVEMENT_Y || motion.y() == 0.0) && motion.z() == 0.0) {
                            handleDeflection(event, projectile, impactedLiving, slotResult);
                        }
                    }
                }
            }
        }
    }
}

public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker) {
    if (EquipmentUtil.isFullStrength(attacker)) {
        if (target.getType().is(AetherTags.Entities.PIGS)) {
            if (target instanceof ZombifiedPiglin zombifiedPiglin) {
                if (!(attacker instanceof Player player) || !player.isCreative()) {
                    ZombifiedPiglinAccessor zombifiedPiglinAccessor = (ZombifiedPiglinAccessor) zombifiedPiglin;
                    zombifiedPiglin.setTarget(attacker);
                    zombifiedPiglinAccessor.callAlertOthers();
                }
            }
            if (target.level() instanceof ServerLevel level) {
                for (int i = 0; i < 20; i++) {
                    double d0 = level.getRandom().nextGaussian() * 0.02;
                    double d1 = level.getRandom().nextGaussian() * 0.02;
                    double d2 = level.getRandom().nextGaussian() * 0.02;
                    double d3 = 5.0;
                    double x = target.getX() + (level.getRandom().nextFloat() * target.getBbWidth() * 2.0) - target.getBbWidth() - d0 * d3;
                    double y = target.getY() + (level.getRandom().nextFloat() * target.getBbHeight()) - d1 * d3;
                    double z = target.getZ() + (level.getRandom().nextFloat() * target.getBbWidth() * 2.0) - target.getBbWidth() - d2 * d3;
                    level.sendParticles(ParticleTypes.FLAME, x, y, z, 1, d0, d1, d2, 0.0);
                }
            }
        }
    }
    return super.hurtEnemy(stack, target, attacker);
}

