public void tick() {

    if (level == null)
        return;
    if (!level.isClientSide) {
        if (--ticksUntilCharge > 0) {
            return;
        }
    }
    if (this.isCharged)
        return;
    if (!level.isClientSide && this.isTemporary) {
        level.destroyBlock(this.worldPosition, false);
    }
    if (!level.isClientSide) {
        List<ISpecialSourceProvider> provider = SourceUtil.takeSourceMultipleWithParticles(worldPosition, level, 10, spell.getCost());
        if (provider != null) {
            this.isCharged = true;
            level.setBlockAndUpdate(worldPosition, level.getBlockState(worldPosition).cycle(RuneBlock.POWERED));
            updateBlock();
        } else {
            ticksUntilCharge = 20 * 3;
            updateBlock();
        }
    }
}

public void tick() {
    super.tick();
    ticks++;
    boss.setDefensiveMode(true);
    boss.setDeltaMovement(0, 0, 0);
    if (ticks % 20 == 0) {
        spawnAOESpikes(boss);
        for (int i = 0; i < 3; i++) {
            if (this.boss.getTarget() != null) {
                EntityChimeraProjectile abstractarrowentity = new EntityChimeraProjectile(boss.level);
                abstractarrowentity.setPos(boss.getX(), boss.getY(), boss.getZ());
                double d0 = boss.getTarget().getX() - boss.getX();
                double d1 = boss.getTarget().getY(0.3333333333333333D) - abstractarrowentity.getY();
                double d2 = boss.getTarget().getZ() - boss.getZ();
                double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                abstractarrowentity.shoot(d0, d1 + d3 * (double) 0.2F, d2, 1.6F, 1.0f);
                this.boss.level.addFreshEntity(abstractarrowentity);
            }
        }
    }
    if (ticks >= 120) {
        finished = true;
        boss.spikeCooldown = (int) (500 + ParticleUtil.inRange(-100, 100) + boss.getCooldownModifier());
        tearDownGoal();
    }
}

public void createShard() {
    var shard = new ItemStack(OccultismItems.FRAGILE_SOUL_GEM_ITEM.get());

    var health = this.getHealth();
    this.setHealth(this.getMaxHealth()); //simulate a healthy familiar to avoid death on respawn
    this.resetFallDistance();
    this.removeAllEffects();
    this.remove(RemovalReason.DISCARDED);

    var id = this.getEncodeId();
    var entityData = new CompoundTag();
    if (id != null)
        entityData.putString("id", id);
    var valueOutput = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, this.registryAccess());
    this.saveWithoutId(valueOutput);
    entityData.merge(valueOutput.buildResult());

    shard.set(DataComponents.ENTITY_DATA, TypedEntityData.of(this.getType(), entityData));
    this.setHealth(health);

