public boolean attackEntityAsMob(Entity target) {
    boolean flag = super.attackEntityAsMob(target);
    if (!flag) {
        return false;
    }

    if (this.isInWater() && deathRollCooldown == 0) {
        this.setAnimation(EntityAnimation.SNAP.get());
        deathRollCooldown = DEATH_ROLL_COOLDOWN_T;
        this.playSound(SoundEvents.ENTITY_GENERIC_SPLASH, 0.6F, 0.7F + this.rand.nextFloat() * 0.4F);
    } else if (!this.isInWater() && tailSweepCooldown == 0 && this.rand.nextFloat() < TAIL_SWEEP_CHANCE) {
        this.setAnimation(EntityAnimation.TAIL_DISPLAY.get());
        tailSweepCooldown = TAIL_SWEEP_COOLDOWN_T;

        double dx = this.posX - target.posX;
        double dz = this.posZ - target.posZ;
        double n = Math.sqrt(dx * dx + dz * dz);
        if (n > 0.0001D) {
            dx /= n;
            dz /= n;
            target.addVelocity(dx * TAIL_SWEEP_KNOCKBACK, 0.1D, dz * TAIL_SWEEP_KNOCKBACK);
        }

        this.playSound(SoundEvents.ENTITY_WITHER_SKELETON_STEP, 0.4F, 0.8F + this.rand.nextFloat() * 0.3F);
    }
    return true;
}

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
  if (!worldIn.isClientSide && entityLiving instanceof Player player) { // && !player.isCrouching()
    IItemHandler handler = stack.getCapability(Capabilities.ItemHandler.ITEM);
    if (handler != null) {
      int foundSlot = -1;
      ItemStack found = ItemStack.EMPTY;
      //just go left to right and eat in order
      for (int i = 0; i < handler.getSlots(); i++) {
        ItemStack test = handler.getStackInSlot(i);
        if (test.has(DataComponents.FOOD) && !player.getCooldowns().isOnCooldown(test.getItem())) {
          found = test;
          foundSlot = i;
          break;
        }
      }
      if (!found.isEmpty()) {
        ChatUtil.addServerChatMessage(player, found.getDisplayName());
        // forward to the food's finishUsingItem so mods can apply their own effects (e.g. artifacts' everlasting beef);
        // pass a copy so vanilla LivingEntity.eat's in-place shrink doesn't bypass the handler's onContentsChanged
        found.getItem().finishUsingItem(found.copy(), worldIn, entityLiving);
        // route the actual consumption through the handler so onContentsChanged fires and the slot persists
        handler.extractItem(foundSlot, 1, false);
      }
    }
  }
  return super.finishUsingItem(stack, worldIn, entityLiving);
}

