public ActionResult useOnBlock(ItemUsageContext context) {
	World world = context.getWorld();
	BlockPos pos = context.getBlockPos();
	boolean client = world.isClient;
	ItemPlacementContext placementContext = new ItemPlacementContext(context);
	if (!world.getBlockState(pos).canReplace(placementContext)) {
		pos = pos.offset(context.getSide());
	}
	if (!world.getBlockState(pos).canReplace(placementContext)) {
		return ActionResult.PASS;
	}
	BlockState state = glyph.getPlacementState(placementContext);
	if (state.canPlaceAt(world, pos)) {
		if (!client) {
			PlayerEntity player = context.getPlayer();
			ItemStack stack = context.getStack();
			world.playSound(null, pos, state.getSoundGroup().getPlaceSound(), SoundCategory.BLOCKS, 1, MathHelper.nextFloat(world.random, 0.8f, 1.2f));
			world.setBlockState(pos, state);
			if (player instanceof ServerPlayerEntity serverPlayer) {
				Criteria.PLACED_BLOCK.trigger(serverPlayer, pos, stack);
				stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(context.getHand()));
			}
		}
		return ActionResult.success(client);
	}
	return super.useOnBlock(context);
}

public void onUseTick(Level level, LivingEntity livingEntity, ItemStack rendingGale, int remainingUseDuration) {
	if (!(livingEntity instanceof Player player)) {
		return;
	}

	Mode mode = getMode(rendingGale);
	int chargeCost = mode == Mode.BOLT ? getBoltChargeCost() : getChargeCost();
	if (getTotalCharge(rendingGale) < chargeCost) {
		player.releaseUsingItem();
		return;
	}

	if (mode == Mode.BOLT) {
		if (remainingUseDuration % 8 == 0) {
			spawnBolt(rendingGale, player);
		}
	} else if (player.level().isClientSide || useCharge(rendingGale, FIRST_SLOT, chargeCost)) {
		if (mode == Mode.FLIGHT) {
			attemptFlight(player);
			spawnFlightParticles(player.level(), player.getX(), player.getY() + player.getEyeHeight(), player.getZ(), player);
		} else if (mode == Mode.PUSH) {
			doRadialPush(player.level(), player.getX(), player.getY(), player.getZ(), player, false);
		} else if (mode == Mode.PULL) {
			doRadialPush(player.level(), player.getX(), player.getY(), player.getZ(), player, true);
		}
	}
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    float velocity = spellStat.getVelocity();
    int potency = spellStat.getPotency();
    int burning = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)) {
        velocity += WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster) / 3.0F;
        potency += WandUtil.getPotencyLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
    }
    SmackStone smackStone = new SmackStone(caster, worldIn);
    smackStone.shootFromRotation(caster, caster.getXRot(), caster.getYRot(), 0.0F, velocity, 1.0F);
    smackStone.setOwner(caster);
    smackStone.setExtraDamage(potency);
    smackStone.setFiery(burning);
    worldIn.addFreshEntity(smackStone);
    if (rightStaff(staff)) {
        for (int i = 0; i < 2; ++i) {
            SmackStone smackStone1 = new SmackStone(caster, worldIn);
            smackStone1.shootFromRotation(caster, caster.getXRot(), caster.getYRot(), 0.0F, velocity, 16.0F);
            smackStone1.setOwner(caster);
            smackStone1.setExtraDamage(potency);
            smackStone1.setFiery(burning);
            worldIn.addFreshEntity(smackStone1);
        }
    }
    this.playSound(worldIn, caster, SoundEvents.BASALT_PLACE, 1.0F, this.projPitch(worldIn.getRandom()));
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int range = spellStat.getRange();
    int duration = spellStat.getDuration();
    int radius = (int) spellStat.getRadius();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, 3.0D);
    LivingEntity target = this.getTarget(caster, range);
    if (target != null){
        Cushion cushion = new Cushion(ModEntityType.CUSHION.get(), worldIn);
        cushion.setRadius(radius);
        cushion.increaseLifeSpan(duration);
        cushion.setPos(target.position());
        worldIn.addFreshEntity(cushion);
    } else if (rayTraceResult instanceof BlockHitResult){
        BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
        Cushion cushion = new Cushion(ModEntityType.CUSHION.get(), worldIn);
        cushion.setRadius(radius);
        cushion.increaseLifeSpan(duration);
        cushion.setPos(blockPos.getX() + 0.5F, blockPos.getY() + 1.0F, blockPos.getZ() + 0.5F);
        worldIn.addFreshEntity(cushion);
    }
    this.playSound(worldIn, caster, SoundEvents.EVOKER_CAST_SPELL);
}

