public static double getManaRegen(Player e) {
    IManaCap mana = CapabilityRegistry.getMana(e);

    if (mana == null) return 0;
    double regen = 0;

    int tier = mana.getBookTier();
    double numGlyphs = mana.getGlyphBonus();
    regen += numGlyphs * ServerConfig.GLYPH_REGEN_BONUS.get();
    regen += tier * ServerConfig.TIER_REGEN_BONUS.get();
    regen += ServerConfig.INIT_MANA_REGEN.get();

    var manaAttribute = e.getAttribute(PerkAttributes.MANA_REGEN_BONUS);
    if (manaAttribute != null) {
        var manaCache = manaAttribute.getModifier(MANA_REGEN_MODIFIER);
        if (manaCache == null || manaCache.amount() != regen) {
            if (manaCache != null) manaAttribute.removeModifier(manaCache);
            manaAttribute.addTransientModifier(new AttributeModifier(MANA_REGEN_MODIFIER, regen, AttributeModifier.Operation.ADD_VALUE));
        }
        regen = manaAttribute.getValue();
    }

    ManaRegenCalcEvent event = new ManaRegenCalcEvent(e, regen);
    NeoForge.EVENT_BUS.post(event);
    regen = event.getRegen();
    return regen;
}

private void resetTarget() {
    DepositOrder currentOrder = this.job.getCurrentDepositOrder();
    MachineReference machineReference = this.job.getManagedMachine();
    BlockEntity machine = this.job.getManagedMachineBlockEntity();
    BlockEntity extractBlockEntity = this.job.getExtractBlockEntity();
    IStorageController storageController = this.job.getStorageController();

    if (machine != null && extractBlockEntity != null && storageController != null) {

        //machine was replaced or no longer supports inventories, so we unlink it and abort
        if (machine.getLevel().getCapability(Item.BLOCK,
                machine.getBlockPos(), machine.getBlockState(), machine, machineReference.insertFacing) == null ||
                extractBlockEntity.getLevel().getCapability(Item.BLOCK, extractBlockEntity.getBlockPos(), extractBlockEntity.getBlockState(), extractBlockEntity, machineReference.extractFacing) == null) {
            this.job.setManagedMachine(null);
            this.targetBlock = null;
            return;
        }

        //if we have an order, we move to the controller to get resources for the machine
        if (currentOrder == null ||
                !this.startTargetingStorageController(currentOrder, machineReference, machine, storageController)) {
            //we either have no order, or no space in the machine, so we extract from  the machine first
            //to be precise, we extract from the extract block entity, which might be different from the machine
            this.startTargetingExtractBlockEntity(currentOrder, machineReference, extractBlockEntity, storageController);
        }
    }
}

protected void doTick(ServerLevel level, E entity) {
    Brain<?> brain = entity.getBrain();

    var walkTarget = BrainUtil.getMemory(entity, OccultismMemoryTypes.LAST_CROP_WALK_TARGET.get());
    if (walkTarget == null) {
        this.resetState(brain);
    } else {
        Long unpathableTime = BrainUtil.getMemory(brain, MemoryModuleType.CANT_REACH_WALK_TARGET_SINCE);
        if (unpathableTime == null) {
            this.resetState(brain);
        } else {
            if (this.lastUnpathableTime == 0L) {
                this.lastUnpathableTime = unpathableTime;
            } else if (this.lastUnpathableTime == unpathableTime) {
                BrainUtil.clearMemory(brain, OccultismMemoryTypes.WALK_TARGET_UNREACHABLE.get());
            } else if (this.lastUnpathableTime < unpathableTime) {
                this.lastUnpathableTime = unpathableTime;
                BrainUtil.setMemory(brain, OccultismMemoryTypes.WALK_TARGET_UNREACHABLE.get(), walkTarget.getTarget().currentBlockPosition().getY() > entity.getEyeY());
                BrainUtil.clearMemory(brain, OccultismMemoryTypes.LAST_CROP_WALK_TARGET.get());
                if (Occultism.DEBUG.debugAI) {
                    Networking.sendToTracking(entity, new MessageSelectBlock(walkTarget.getTarget().currentBlockPosition(), 50000, Color.RED));
                }
            }

        }
    }
}

