public void setNightForm(boolean nightForm) {
    getEntityData().set(NIGHT_FORM, nightForm);

    if (nightForm) {
        getAttribute(Attributes.MOVEMENT_SPEED).removeModifier(DAY_SPEED_MODIFIER_ID);
        float healthFraction = getHealthRatio();
        getAttribute(Attributes.MAX_HEALTH).removeModifier(DAY_HEALTH_MODIFIER_ID);
        setHealth(getMaxHealth() * healthFraction);
        setPose(Pose.STANDING);
        refreshDimensions();
    }
    else {
        if (!getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(DAY_SPEED_MODIFIER_ID)) {
            getAttribute(Attributes.MOVEMENT_SPEED).addTransientModifier(SPEED_MODIFIER_DAY);
        }
        float healthFraction = getHealthRatio();
        if (!getAttribute(Attributes.MAX_HEALTH).hasModifier(DAY_HEALTH_MODIFIER_ID)) {
            getAttribute(Attributes.MAX_HEALTH).addTransientModifier(HEALTH_MODIFIER_DAY);
        }
        setHealth(getMaxHealth() * healthFraction);
        setPose(Pose.CROUCHING);
        refreshDimensions();
        if (getClingDirection() == Direction.UP) {
            float heightDiff = this.getType().getDimensions().height() - DAY_FORM_DIMENSIONS.height();
            setPos(getX(), getY() + heightDiff, getZ());
        }
    }
}

    public boolean tame(EntityPlayer player) {
    	if(!this.getEntityWorld().isRemote && !this.isRareSubspecies()) {
			if (this.rand.nextInt(3) == 0) {
				this.setPlayerOwner(player);
				this.onTamedByPlayer();
				this.unsetTemporary();
				String tameMessage = I18n.translateToLocal("message.pet.tamed");
				tameMessage = tameMessage.replace("%creature%", this.getSpeciesName());
				player.sendMessage(new TextComponentString(tameMessage));
				this.playTameEffect(this.isTamed());
				player.addStat(ObjectManager.getStat(this.creatureInfo.getName() + ".tame"), 1);
				if (this.timeUntilPortal > this.getPortalCooldown()) {
					this.timeUntilPortal = this.getPortalCooldown();
				}
				ExtendedPlayer extendedPlayer = ExtendedPlayer.getForPlayer(player);
				if(extendedPlayer != null) {
					extendedPlayer.getBeastiary().discoverCreature(this, 2, false);
				}
			}
			else {
				String tameFailedMessage = I18n.translateToLocal("message.pet.tamefail");
				tameFailedMessage = tameFailedMessage.replace("%creature%", this.getSpeciesName());
				player.sendMessage(new TextComponentString(tameFailedMessage));
				this.playTameEffect(this.isTamed());
			}
		}
    	return this.isTamed();
    }

public static boolean revive(ItemStack itemStack, LivingEntity victim){
    if (!itemStack.isEmpty()) {
        if (itemStack.getTag() != null) {
            if (itemStack.getTag().getInt(ITotem.SOULS_AMOUNT) == ITotem.MAX_SOULS) {
                if (!victim.level.isClientSide) {
                    victim.setHealth(1.0F);
                    victim.removeAllEffects();
                    victim.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
                    victim.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
                    victim.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
                    if (victim instanceof Player) {
                        ModNetwork.sendTo((Player) victim, new TotemDeathPacket(victim.getUUID()));
                    } else {
                        ServerLevel serverWorld = (ServerLevel) victim.level;
                        serverWorld.getChunkSource().broadcast(victim, new ClientboundEntityEventPacket(victim, (byte)35));
                    }
                    ITotem.setSoulsAmount(itemStack, 0);
                    if (victim instanceof Mob){
                        itemStack.shrink(1);
                        victim.spawnAtLocation(new ItemStack(ModItems.SPENT_TOTEM.get()));
                    }
                }
                return true;
            }
        }
    }
    return false;
}

public void releaseUsing(ItemStack stack, Level level, LivingEntity livingEntity, int useTimeRemaining) {
    if (level instanceof ServerLevel serverLevel) {
        int CastTime = stack.getUseDuration() - useTimeRemaining;
        ISpell spell = GoetyEventFactory.onStopSpell(livingEntity, stack, this.getSpell(stack), CastTime, useTimeRemaining);
        if (spell != null) {
            spell.stopSpell(serverLevel, livingEntity, stack, IWand.getFocus(stack), CastTime, WandUtil.getStats(livingEntity, spell));
            if (livingEntity instanceof Player player) {
                if (spell instanceof IChargingSpell chargeSpell) {
                    if (chargeSpell.shotsNumber(player, stack) > 0) {
                        if (this.ShotsFired(stack) > 0) {
                            float coolPercent = (float) this.ShotsFired(stack) / chargeSpell.shotsNumber(player, stack);
                            this.setShots(stack, 0);
                            if (!spell.hasCustomCooldown(player, stack, IWand.getFocus(stack), Mth.floor(chargeSpell.spellCooldown(player) * coolPercent))) {
                                SEHelper.addSpellCooldown(player, spell, Mth.floor(chargeSpell.spellCooldown(player) * coolPercent));
                            }
                        }
                    } else {
                        if (!spell.hasCustomCooldown(player, stack, IWand.getFocus(stack), Mth.floor(chargeSpell.spellCooldown(player)))) {
                            if (CastTime > chargeSpell.castUp(player, stack)) {
                                SEHelper.addSpellCooldown(player, spell, Mth.floor(chargeSpell.spellCooldown(player)));
                            }
                        }
                    }
                }
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    int potency = spellStat.getPotency();
    int radius = (int) spellStat.getRadius();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    ColorUtil colorUtil = new ColorUtil(ChatFormatting.LIGHT_PURPLE);
    worldIn.sendParticles(new ShockwaveParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, radius, 1, true), caster.getX(), caster.getY() + 0.25F, caster.getZ(), 0, 0, 0, 0, 0);
    for (int i = -radius; i < radius; ++i){
        for (int k = -radius; k < radius; ++k){
            BlockPos blockPos = caster.blockPosition().offset(i, 0, k);
            if (worldIn.random.nextFloat() <= 0.25F){
                worldIn.sendParticles(ModParticleTypes.SPELL_SQUARE.get(), blockPos.getX(), blockPos.getY(), blockPos.getZ(), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 0.5F);
            }
        }
    }
    for (LivingEntity livingEntity : worldIn.getEntitiesOfClass(LivingEntity.class, caster.getBoundingBox().inflate(radius))){
        if (!MobUtil.areAllies(caster, livingEntity)) {
            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), MathHelper.secondsToTicks(duration), potency + 4));
            livingEntity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, MathHelper.secondsToTicks(duration), potency));
            livingEntity.playSound(ModSounds.WEAKEN_CURSE.get());
        }
    }
    this.playSound(worldIn, caster, 2.0F, 1.0F);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int radius = (int) spellStat.getRadius();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    if (rightStaff(staff)){
        radius *= 2;
    }
    ColorUtil colorUtil = new ColorUtil(0xffffff);
    worldIn.sendParticles(new CircleExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), (float) (radius * 2), radius), caster.getX(), caster.getY() + 0.5F, caster.getZ(), 0, 0, 0, 0, 0);
    worldIn.sendParticles(new SmashParticleOption(colorUtil, radius, 10), caster.getX(), caster.getY() + 1.0D, caster.getZ(), 1, 0, 0, 0, 0);
    for (LivingEntity livingEntity : worldIn.getEntitiesOfClass(LivingEntity.class, caster.getBoundingBox().inflate(radius))){
        if (!MobUtil.areAllies(caster, livingEntity)) {
            double power = 4.0D + potency;
            double d0 = livingEntity.getX() - caster.getX();
            double d1 = livingEntity.getZ() - caster.getZ();
            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
            MobUtil.push(livingEntity, d0 / d2 * power, 0.2D, d1 / d2 * power);
            livingEntity.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, MathHelper.secondsToTicks(duration), potency));
            livingEntity.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN, MathHelper.secondsToTicks(duration), potency));
        }
    }
    this.playSound(worldIn, caster, ModSounds.WIND_HORN.get(), 3.0F, 1.0F);
}

public boolean canUse() {
    if (!(this.mob instanceof EntityCamel)) {
        UntamedWilds.LOGGER.warn("Trying to run BeAnAssTarget Goal on a mob without a ranged attack");
        return false;
    }
    if (this.mob.getRandom().nextInt(200) != 0 || this.mob.isBaby() || this.mob.getHealth() < this.mob.getMaxHealth() / 2) {
        return false;
    }
    if (this.mob instanceof ComplexMob complexMob) {
        if (complexMob.isTame()) {
            return false;
        }
    }
    List<T> list = this.mob.level.getEntitiesOfClass(this.targetClass, this.getTargetableArea(this.getFollowDistance()), this.targetEntitySelector);
    list.removeIf((Predicate<LivingEntity>) this::shouldRemoveTarget);

    if (list.isEmpty()) {
        return false;
    }
    else {
        list.sort(this.sorter);
        this.targetEntity = list.get(0);
        if (this.mob instanceof ComplexMob) {
            ((ComplexMob)this.mob).huntingCooldown = 6000;
        }
        return true;
    }
}

private void applyEffect(LivingEntity target, LootRarity rarity, float level) {
    if (target.level().isClientSide()) {
        return;
    }

    int cooldown = this.getCooldown(rarity);
    if (cooldown != 0 && AbilityCooldowns.isOnCooldown(target, this.id(), cooldown)) {
        return;
    }
    EffectData data = this.values.get(rarity);
    MobEffectInstance inst = target.getEffect(this.effect);
    if (this.stackOnReapply && inst != null) {
        if (inst != null) {
            int duration = Math.max(inst.getDuration(), data.duration.getInt(level));
            int amp = Math.min(this.stackingLimit, inst.getAmplifier() + 1 + data.amplifier.getInt(level));
            var newInst = new MobEffectInstance(this.effect, duration, amp, inst.isAmbient(), inst.isVisible());
            inst.update(newInst);
            ((LivingEntityInvoker) target).callOnEffectUpdated(inst, true, null);
            inst.onEffectStarted(target);
        }
    }
    else {
        target.addEffect(data.build(this.effect, level));
    }
    if (cooldown != 0) {
        AbilityCooldowns.startCooldown(target, this.id());
    }
}

public static void serverTick(Level level, BlockPos pos, BlockState state, AnubiteStatueBlockEntity blockEntity) {
    if (FossilConfig.isEnabled(FossilConfig.ANUBITE_HAS_COOLDOWN)) {
        if (blockEntity.cooldown <= 0) {
            Player player = level.getNearestPlayer(pos.getX(), pos.getY(), pos.getZ(), 5, true);
            if (player != null) {
                level.explode(null, pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, 5f, true, Explosion.BlockInteraction.NONE);
                BlockPos spawnPos = pos.relative(state.getValue(AnubiteStatueBlock.FACING));
                ModEntities.ANUBITE.get().spawn((ServerLevel) level, null, null, spawnPos, MobSpawnType.EVENT, false, false);
                blockEntity.cooldown = FossilConfig.getInt(FossilConfig.ANUBITE_COOLDOWN);
                level.setBlockAndUpdate(pos, state.setValue(AnubiteStatueBlock.LIT, false));
            }
        }
    } else {
        Player player = level.getNearestPlayer(pos.getX(), pos.getY(), pos.getZ(), 5, true);
        if (player != null) {
            level.explode(null, pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, 5f, true, Explosion.BlockInteraction.NONE);
            BlockPos spawnPos = pos.relative(state.getValue(AnubiteStatueBlock.FACING));
            ModEntities.ANUBITE.get().spawn((ServerLevel) level, null, null, spawnPos, MobSpawnType.EVENT, false, false);
            level.removeBlock(pos, false);
        }
    }
    if (blockEntity.cooldown > 0) {
        blockEntity.cooldown--;
        if (blockEntity.cooldown == 0) {
            level.setBlockAndUpdate(pos, state.setValue(AnubiteStatueBlock.LIT, true));
        }
    }
}

public void tick() {
	if (this.lich.getTeleportInvisibility() > 0) return;
	super.tick();
	if (this.lich.getScepterTimeLeft() > 0) return;
	for (Mob mob : this.lich.level().getEntitiesOfClass(Mob.class, this.lich.getBoundingBox().inflate(32.0D, 16.0D, 32.0D), e -> e.is(TFEntityTypeTags.LICH_POPPABLES) && e != this.lich)) {
		if (this.lich.getSensing().hasLineOfSight(mob)) {
			mob.discard();
			//rain particles
			LifedrainScepterItem.animateTargetShatter((ServerLevel) this.lich.level(), mob);
			// play death sound
			SoundEvent deathSound = EntityUtil.getDeathSound(mob);
			if (deathSound != null) {
				this.lich.level().playSound(null, mob.blockPosition(), deathSound, SoundSource.HOSTILE, 1.0F, mob.getVoicePitch());
			}
			//funny pop sound
			this.lich.playSound(TFSounds.LICH_POP_MOB.get(), 3.0F, 0.4F + this.lich.getRandom().nextFloat() * 0.2F);
			mob.playSound(TFSounds.LICH_POP_MOB.get(), 3.0F, 0.4F + this.lich.getRandom().nextFloat() * 0.2F);
			// make trail so it's clear that we did it
			this.lich.makeMagicTrail(mob.getEyePosition(), this.lich.getEyePosition(), 1.0F, 0.5F, 0.5F);
			//heal a little health
			this.lich.heal(2.0F);
			this.lich.swing(InteractionHand.MAIN_HAND);
			this.lich.setPopCooldown(40);
			this.lich.gameEvent(GameEvent.ENTITY_DIE);
			break;
		}
	}
}

protected void customServerAiStep(ServerLevel serverLevel) {
	super.customServerAiStep(serverLevel);

	// Teleport home if we get too far away from it
	if (this.isOutsideHomeRange(this.position()) && this.getTeleportInvisibility() <= 0) this.teleportHome();

	if (this.getAttackCooldown() > 0 && this.spawnTime <= 0) {
		this.attackCooldown--;
	}

	if (this.getPopCooldown() > 0 && this.getHealth() < this.getMaxHealth() && this.getScepterTimeLeft() <= 0) {
		this.popCooldown--;
	}

	if (this.getScepterTimeLeft() == 0 && this.getPopCooldown() < 30 && this.getItemInHand(InteractionHand.MAIN_HAND).is(TFItems.LIFEDRAIN_SCEPTER.get())) {
		this.setItemInHand(InteractionHand.MAIN_HAND, new ItemStack(this.getPhase() == 2 ? TFItems.ZOMBIE_SCEPTER.get() : Items.GOLDEN_SWORD));
	}

	if (this.getScepterTimeLeft() > 0) {
		this.heldScepterTime--;
	}

	if (this.getTarget() != null) {
		if (this.spawnTime > 0 && this.spawnTime-- < 40) {
			this.turnNearbyCandles(40 - this.spawnTime, !(this.spawnTime - 1 > 0 && this.spawnTime - 1 < 40));
		}
	}
}

	public void thunderHit(@NotNull ServerLevel sworld, @NotNull LightningBolt lightningBolt) { // onStruckByLightning
		if(lightningCooldown > 0 || level().isClientSide)
			return;

		float sizeMod = getScale();
		if(sizeMod <= 15) {

			var healthAttr = this.getAttribute(Attributes.MAX_HEALTH);
			if(healthAttr != null)
				healthAttr.addPermanentModifier(new AttributeModifier(Quark.asResource("lightning_max_health_bonus_" + sizeMod), 0.5, Operation.ADD_VALUE));

			var speedAttr = this.getAttribute(Attributes.MOVEMENT_SPEED);
			if(speedAttr != null)
				speedAttr.addPermanentModifier(new AttributeModifier(Quark.asResource("lightning_speed_debuff_" + sizeMod), -0.05, Operation.ADD_MULTIPLIED_TOTAL));

			var armorAttr = this.getAttribute(Attributes.ARMOR);
			if(armorAttr != null)
				armorAttr.addPermanentModifier(new AttributeModifier(Quark.asResource("lightning_armor_bonus_" + sizeMod), 0.125, Operation.ADD_VALUE));

			float scale = Math.min(sizeMod + 1, 16);
            var scaleAttr = this.getAttribute(Attributes.SCALE);
            if (scaleAttr != null)
                scaleAttr.addOrReplacePermanentModifier(new AttributeModifier(Quark.asResource("lightning_size_increase"), scale, Operation.ADD_VALUE));
			refreshDimensions();

			lightningCooldown = 150;
		}
	}

public void onResolveEntity(@NotNull EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    var dispelEvent = NeoForge.EVENT_BUS.post(new DispelEvent.Pre(rayTraceResult, world, shooter, spellStats, spellContext));
    if (dispelEvent.isCanceled())
        return;
    if (rayTraceResult.getEntity() instanceof LivingEntity entity) {
        Collection<MobEffectInstance> effects = entity.getActiveEffects();
        MobEffectInstance[] array = effects.toArray(new MobEffectInstance[0]);
        Optional<HolderSet.Named<MobEffect>> blacklist = world.registryAccess().registryOrThrow(Registries.MOB_EFFECT).getTag(PotionEffectTags.DISPEL_DENY);
        Optional<HolderSet.Named<MobEffect>> whitelist = world.registryAccess().registryOrThrow(Registries.MOB_EFFECT).getTag(PotionEffectTags.DISPEL_ALLOW);
        for (MobEffectInstance e : array) {
            if (e.getCures().contains(EffectCures.MILK)) {
                if (blacklist.isPresent() && blacklist.get().stream().anyMatch(effect -> effect.value() == e.getEffect()))
                    continue;
                entity.removeEffect(e.getEffect());
            } else if (whitelist.isPresent() && whitelist.get().stream().anyMatch(effect -> effect.value() == e.getEffect())) {
                entity.removeEffect(e.getEffect());
            }
        }
        if (!entity.isAlive() || entity.getHealth() <= 0 || entity.isRemoved()) {
            //TODO dispel loot table?
            return;
        }
        if (entity instanceof IDispellable iDispellable) {
            iDispellable.onDispel(shooter);
        }
        NeoForge.EVENT_BUS.post(new DispelEvent.Post(rayTraceResult, world, shooter, spellStats, spellContext));
    }
}

protected InteractionResult mobInteract(Player playerIn, InteractionHand hand) {
    ItemStack stack = playerIn.getItemInHand(hand);
    boolean isInTransformationBiome = this.isInTransformationBiome(playerIn) || this.isInTransformationBiome(this);
    if (this.isTransformItem(stack) && playerIn == this.getFamiliarOwner()) {
        if (isInTransformationBiome) {

            if (stack.is(Tags.Items.DYES_BLACK))
                this.setBlack(true);
            else if (stack.getItem() == Items.ENDER_EYE)
                this.setRedEyes(true);
            else if (stack.getItem() == Items.FLINT)
                this.setEvilHorns(true);
            if (this.shouldTransform()) {
                OccultismAdvancements.FAMILIAR.get().trigger(playerIn, Type.SHUB_NIGGURATH_SUMMON);
                this.transform();
            }

            if (!this.level().isClientSide()) //do this down here because shrink will erase item info and cause checks to fail
                stack.shrink(1);

            return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
        } else {
            this.shakeHeadTimer = 20;
            return InteractionResult.CONSUME;
        }
    }
    return super.mobInteract(playerIn, hand);
}

