		Level level = purpoid.level();
		int blockX = purpoid.getBlockX();
		int blockZ = purpoid.getBlockZ();
		int heightBelow = level.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, blockX, blockZ);
		boolean isAirBelow = level.getBlockState(new BlockPos(blockX, heightBelow, blockZ)).isAir();
		int blockY = purpoid.getBlockY();
		Vec3 randomPos;
		if ((!isAirBelow && blockY - heightBelow > 15) || (isAirBelow && blockY > level.getSeaLevel() + 15)) {
			RandomSource random = purpoid.getRandom();
			randomPos = purpoid.position().add(new Vec3(MathUtil.makeNegativeRandomly(random.nextInt(17), random), -random.nextInt(32), MathUtil.makeNegativeRandomly(random.nextInt(17), random)));
		} else {
			Vec3 view = purpoid.getViewVector(0.0F);
			randomPos = HoverRandomPos.getPos(purpoid, 32, 16, view.x, view.z, ((float) Math.PI / 2F), 3, 1);
		}
		if (randomPos != null) {
			this.x = randomPos.x();
			this.y = randomPos.y();
			this.z = randomPos.z();
			return true;
		}
	}
	return false;
}

private void doItemInteraction() {
	Item item = this.itemStack.getItem();

	if (this.itemStack.is(NeapolitanItemTags.CHIMPANZEE_APE_MODE_ITEMS) && this.chimpanzee.getApeModeTime() <= 0) {
		this.lookTimer = 40;
		this.chimpanzee.setApeModeTime(1200 + this.chimpanzee.getRandom().nextInt(1200));
	} else if (this.shouldPlayWithItem(this.itemStack) && this.chimpanzee.isDoingAction(ChimpanzeeAction.LOOKING_AT_ITEM)) {
		this.lookTimer = 60 + this.chimpanzee.getRandom().nextInt(20);
		this.chimpanzee.setAction(ChimpanzeeAction.PLAYING_WITH_ITEM);
	} else {
		if (item instanceof ArmorItem armorItem && armorItem.getEquipmentSlot() == EquipmentSlot.HEAD && this.chimpanzee.getItemBySlot(EquipmentSlot.HEAD).isEmpty()) {
			this.chimpanzee.setItemSlot(EquipmentSlot.HEAD, this.itemStack);
			this.chimpanzee.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
			this.chimpanzee.setDropChance(EquipmentSlot.HEAD, 2.0F);
			this.playEquipSound(armorItem);
		} else {
			if (this.chimpanzee.getMainHandItem() == this.itemStack) {
				this.chimpanzee.throwHeldItem(InteractionHand.MAIN_HAND);
			}
		}

		if (this.wasHurt) {
			this.runAway();
		}

		this.chimpanzee.setDefaultAction();
	}
}

public void tick() {
	if (this.lookAtCooldown > 0) {
		this.lookAtCooldown--;
		if (this.isTurningForSonar) {
			this.getYRotD().ifPresent(yRot -> this.mob.setYRot(this.rotateTowards(this.mob.getYRot(), yRot, this.yMaxRotSpeed)));
		} else {
			this.getYRotD().ifPresent(yRot -> this.mob.yHeadRot = this.rotateTowards(this.mob.yHeadRot, yRot, this.yMaxRotSpeed));
		}
		this.mob.setXRot(this.rotateTowards(this.mob.getXRot(), this.getXRotD().get(), this.xMaxRotAngle));
	} else {
		if (this.mob.getNavigation().isDone()) {
			this.mob.setXRot(this.rotateTowards(this.mob.getXRot(), 0.0F, 5.0F));
		}
		if (this.isTurningForSonar) {
			this.mob.setYRot(this.rotateTowards(this.mob.getYRot(), this.mob.yBodyRot, this.yMaxRotSpeed));
		} else {
			this.mob.yHeadRot = this.rotateTowards(this.mob.yHeadRot, this.mob.yBodyRot, this.yMaxRotSpeed);
		}
	}

	float wrappedDegrees = Mth.wrapDegrees(this.mob.yHeadRot - this.mob.yBodyRot);
	float angleLimit = this.mob.getPassengers().isEmpty() ? 10.0F : 5.0F;
	if (wrappedDegrees < -angleLimit) {
		this.mob.yBodyRot -= 4.0F;
	} else if (wrappedDegrees > angleLimit) {
		this.mob.yBodyRot += 4.0F;
	}
}

public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
	if (SuperpositionHandler.hasSpellstoneCooldown(player))
		return;

	LivingEntity target = SuperpositionHandler.getObservedEntity(player, world, 3.0F, (int) phaseRange.getValue());

	if (target != null) {
		Vector3 targetPos = Vector3.fromEntityCenter(target);
		Vector3 chaserPos = Vector3.fromEntityCenter(player);

		Vector3 dir = targetPos.subtract(chaserPos);
		dir = dir.normalize();
		dir = dir.multiply(1.5D);

		dir = targetPos.add(dir);

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 72, 1.0F, false));

		player.teleportTo(dir.x, target.getY() + 0.25D, dir.z);
		EnigmaticLegacy.packetInstance.send(PacketDistributor.PLAYER.with(() -> player), new PacketPlayerSetlook(target.getX(), target.getY() - 1.0D + (target.getBbHeight() / 2), target.getZ()));

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 24, false));

		SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));
		TransientPlayerData.get(player).setEyeOfNebulaPower(true);
	}
}

public static TransientPlayerData decode(FriendlyByteBuf buf) {
	UUID playerID = buf.readUUID();
	int spellstoneCooldown = buf.readInt();
	int fireImmunityTimer = buf.readInt();
	int fireImmunityTimerCap = buf.readInt();
	int fireImmunityTimerLast = buf.readInt();
	boolean consumedForbiddenFruit = buf.readBoolean();
	boolean disabledMagnetEffects = buf.readBoolean();
	boolean unlockedNarrator = buf.readBoolean();
	boolean elytraBoosting = buf.readBoolean();

	Player player = EnigmaticLegacy.PROXY.getPlayer(playerID);

	if (player != null) {
		TransientPlayerData data = new TransientPlayerData(player);
		data.spellstoneCooldown = spellstoneCooldown;
		data.fireImmunityTimer = fireImmunityTimer;
		data.fireImmunityTimerCap = fireImmunityTimerCap;
		data.fireImmunityTimerLast = fireImmunityTimerLast;
		data.consumedForbiddenFruit = consumedForbiddenFruit;
		data.disabledMagnetEffects = disabledMagnetEffects;
		data.unlockedNarrator = unlockedNarrator;
		data.elytraBoosting = elytraBoosting;

		return data;
	}

	return null;
}

public void startAttackBehavior(LivingEntity target) {
    this.yBodyRot = this.getYRot();
    double distance = this.distanceTo(target);
    float f = this.getBbWidth() + target.getBbWidth();
    if (distance > 20 + f) {
        this.getNavigation().moveTo(target, 1.2);
    } else if (distance < 2F + f && spinCooldown <= 0) {
        if (this.getAnimation() == NO_ANIMATION) {
            this.setAnimation(ANIMATION_SPIN);
            spinCooldown = 1000 + random.nextInt(60);
        }
    } else {
        if (strafeTarget == null || strafeTarget.distanceTo(this.position()) < 4) {
            Vec3 possible = target.position().add(random.nextInt(20) - 10, random.nextInt(2), random.nextInt(20) - 10);
            if (!isTargetBlocked(possible)) {
                strafeTarget = possible;
            }
        } else {
            this.getNavigation().moveTo(strafeTarget.x, strafeTarget.y, strafeTarget.z, 1.5F);
        }
        if (rangedCooldown <= 0 && this.getAnimation() == NO_ANIMATION && hasLineOfSight(target)) {
            this.setAnimation(ANIMATION_ATTACK);
            this.playSound(ACSoundRegistry.DEEP_ONE_MAGE_ATTACK.get());
            rangedCooldown = 30 + random.nextInt(20);
        }
        this.getLookControl().setLookAt(target.getX(), target.getEyeY(), target.getZ(), 30.0F, 10.0F);

    }
}

public void rideTick() {
    final Entity entity = this.getVehicle();
    if (this.isPassenger() && !entity.isAlive()) {
        this.stopRiding();
    } else if (isTame() && entity instanceof LivingEntity && isOwnedBy((LivingEntity) entity)) {
        this.setDeltaMovement(0, 0, 0);
        this.tick();
        final Entity riding = this.getVehicle();
        if (this.isPassenger()) {
            final int i = riding.getPassengers().indexOf(this);
            final float radius = 0.43F;
            final float angle = (Maths.STARTING_ANGLE * (((Player) riding).yBodyRot + (i == 0 ? -90 : 90)));
            final double extraX = radius * Mth.sin(Mth.PI + angle);
            final double extraZ = radius * Mth.cos(angle);
            final double extraY = (riding.isShiftKeyDown() ? 1.25D : 1.45D);
            this.yHeadRot = ((Player) riding).yHeadRot;
            this.yRotO = ((Player) riding).yHeadRot;
            this.setPos(riding.getX() + extraX, riding.getY() + extraY, riding.getZ() + extraZ);
            if (!riding.isAlive() || boardingCooldown == 0 && riding.isShiftKeyDown() || ((Player) riding).isFallFlying() || this.getTarget() != null && this.getTarget().isAlive()) {
                this.removeVehicle();
                if (!this.level().isClientSide) {
                    AlexsMobs.sendMSGToAll(new MessageCrowDismount(this.getId(), riding.getId()));
                }
            }
        }
    } else {
        super.rideTick();
    }
}

public void readAdditionalSaveData(CompoundTag compound) {
    super.readAdditionalSaveData(compound);
    this.entityData.set(ATTACHED_FACE, Direction.from3DDataValue(compound.getByte("AttachFace")));
    this.setLeaf(compound.getBoolean("Leaf"));
    this.setQueen(compound.getBoolean("Queen"));
    this.setAntScale(compound.getFloat("AntScale"));
    BlockState blockstate = null;
    if (compound.contains("HarvestedLeafState", 10)) {
        blockstate = NbtUtils.readBlockState(this.level().holderLookup(Registries.BLOCK), compound.getCompound("HarvestedLeafState"));
        if (blockstate.isAir()) {
            blockstate = null;
        }
    }
    this.stayOutOfHiveCountdown = compound.getInt("CannotEnterHiveTicks");
    this.haveBabyCooldown = compound.getInt("BabyCooldown");
    this.hivePos = null;
    if (compound.contains("HivePos")) {
        this.hivePos = NbtUtils.readBlockPos(compound.getCompound("HivePos"));
    }
    this.setLeafHarvestedState(blockstate);
    if (compound.contains("HLPX")) {
        int i = compound.getInt("HLPX");
        int j = compound.getInt("HLPY");
        int k = compound.getInt("HLPZ");
        this.entityData.set(LEAF_HARVESTED_POS, Optional.of(new BlockPos(i, j, k)));
    } else {
        this.entityData.set(LEAF_HARVESTED_POS, Optional.empty());
    }
}

public boolean canUse() {
    if(EntityLeafcutterAnt.this.stayOutOfHiveCountdown > 0){
        return false;
    }
    if (EntityLeafcutterAnt.this.hasLeaf() || EntityLeafcutterAnt.this.isQueen()) {
        searchCooldown--;
        BlockPos hive = EntityLeafcutterAnt.this.hivePos;
        if (hive != null && EntityLeafcutterAnt.this.level().getBlockEntity(hive) instanceof TileEntityLeafcutterAnthill) {
            hivePos = hive;
            return true;
        }
        if (searchCooldown <= 0) {
            searchCooldown = 400;
            PoiManager pointofinterestmanager = ((ServerLevel) level()).getPoiManager();
            Stream<BlockPos> stream = pointofinterestmanager.findAll(poiTypeHolder -> poiTypeHolder.is(AMPointOfInterestRegistry.LEAFCUTTER_ANT_HILL.getKey()), Predicates.alwaysTrue(), EntityLeafcutterAnt.this.blockPosition(), 100, PoiManager.Occupancy.ANY);
            List<BlockPos> listOfHives = stream.collect(Collectors.toList());
            BlockPos ret = null;
            for (BlockPos pos : listOfHives) {
                if (ret == null || pos.distSqr(EntityLeafcutterAnt.this.blockPosition()) < ret.distSqr(EntityLeafcutterAnt.this.blockPosition())) {
                    ret = pos;
                }
            }
            hivePos = ret;
            EntityLeafcutterAnt.this.hivePos = ret;
            return hivePos != null;
        }
    }
    return false;
}

private void handleRoll() {
    ++this.rollCounter;
    if (!this.level().isClientSide) {
        if (this.horizontalCollision && earthquakeCooldown == 0 & this.isAngry()) {
            earthquakeCooldown = maxRollTime;
            this.earthquake();
        }
        if (this.rollCounter > maxRollTime) {
            this.setRolling(false);
            this.rollCooldown = 10 + random.nextInt(10);
            this.rollCounter = 0;
            this.setDeltaMovement(Vec3.ZERO);
        } else {
            Vec3 vec3 = this.getDeltaMovement();
            if (this.rollCounter == 1) {
                float f = this.getYRot() * Mth.DEG_TO_RAD;
                float f1 = this.isBaby() ? 0.2F : 0.35F;
                this.rollYRot = this.getYRot();
                this.rollDelta = new Vec3(vec3.x + (double) (-Mth.sin(f) * f1), 0.0D, vec3.z + (double) (Mth.cos(f) * f1));
                this.setDeltaMovement(this.rollDelta.add(0.0D, 0.27D, 0.0D));
            } else {
                this.setYRot(rollYRot);
                this.setYHeadRot(rollYRot);
                this.setYBodyRot(rollYRot);
                this.setDeltaMovement(this.rollDelta.x, vec3.y, this.rollDelta.z);
            }
        }
    }
}

public void tick() {
    super.tick();
    this.prevOnLandProgress = onLandProgress;

    if (this.isInWater()) {
        if (onLandProgress > 0F)
            onLandProgress--;
    } else {
        if (onLandProgress < 5F)
            onLandProgress++;
    }

    if (this.onGround() && !this.isInWater()) {
        this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
        this.setYRot(this.random.nextFloat() * 360.0F);
        this.setOnGround(false);
        this.hasImpulse = true;
    }
    if (circleCooldown > 0) {
        circleCooldown--;
        this.setTarget(null);
        this.setLastHurtByMob(null);
    }
    if(this.getAnimation() == ANIMATION_POINT){
        this.yBodyRot = this.getYHeadRot();
        this.rotOffs = this.getYHeadRot();
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

