public boolean canCastTouch(ItemStack stack, Level worldIn, LivingEntity caster, @Nullable LivingEntity target){
    Player playerEntity = (Player) caster;
    if (worldIn instanceof ServerLevel serverLevel) {
        ISpell spell = GoetyEventFactory.onTouchBasedSpell(caster, stack, this.getSpell(stack));
        if (spell != null && !this.cannotCast(caster, stack, spell)) {
            if (spell instanceof ITouchSpell touchSpell) {
                if (!touchSpell.targetConditions(serverLevel, caster, target, stack, WandUtil.getStats(caster, touchSpell))) {
                    return false;
                }
            }
            if (playerEntity.isCreative()){
                if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                    SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                }
                return stack.getTag() != null;
            } else if (SEHelper.getSoulsAmount(playerEntity, SoulUse(caster, stack))) {
                if (stack.getTag() != null) {
                    SEHelper.decreaseSouls(playerEntity, SoulUse(caster, stack));
                    if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                        SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                    }
                    SEHelper.sendSEUpdatePacket(playerEntity);
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos) {
    if (!level.isClientSide) {
        if (level.getBlockState(blockPos).is(Blocks.BLUE_ICE)) {
            if (conditionsMet(level, player)) {
                if (canSpawn(level, blockPos)) {
                    IceGolem iceGolem = ModEntityType.ICE_GOLEM.get().create(level);
                    if (iceGolem != null) {
                        iceGolem.setTrueOwner(player);
                        iceGolem.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(iceGolem.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                        iceGolem.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.below().getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                        if (level.addFreshEntity(iceGolem)) {
                            removeBlocks(level, blockPos);
                            stack.shrink(1);
                            if (player instanceof ServerPlayer serverPlayer) {
                                CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, iceGolem);
                            }
                            return true;
                        }
                    }
                } else {
                    player.displayClientMessage(Component.translatable("info.goety.block.fail"), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.summon.limit"), true);
            }
        }
    }
    return false;
}

public boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos) {
    if (!level.isClientSide) {
        if (level.getBlockState(blockPos).is(ModBlocks.JADE_BLOCK.get())) {
            if (checkBlocks(level, blockPos)) {
                if (SEHelper.hasResearch(player, ResearchList.MISTRAL)) {
                    SquallGolem squallGolem = ModEntityType.SQUALL_GOLEM.get().create(level);
                    if (squallGolem != null) {
                        squallGolem.setTrueOwner(player);
                        squallGolem.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(squallGolem.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                        squallGolem.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                        if (level.addFreshEntity(squallGolem)) {
                            removeBlocks(level, blockPos);
                            stack.shrink(1);
                            if (player instanceof ServerPlayer serverPlayer) {
                                CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, squallGolem);
                            }
                            return true;
                        }
                    }
                } else {
                    player.displayClientMessage(Component.translatable("info.goety.research.fail"), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.block.fail"), true);
            }
        }
    }
    return false;
}

public void surroundTeeth(LivingEntity livingEntity, BlockPos blockPos, float damage, boolean isStaff){
    BlockPos.MutableBlockPos blockpos$mutable = new BlockPos.MutableBlockPos(blockPos.getX(), blockPos.getY(), blockPos.getZ());

    while (blockpos$mutable.getY() < blockPos.getY() + 8.0D && !livingEntity.level.getBlockState(blockpos$mutable).blocksMotion()) {
        blockpos$mutable.move(Direction.UP);
    }

    if (isStaff) {
        for (int i = 0; i < 5; ++i) {
            float f1 = (float) i * (float) Math.PI * 0.4F;
            ViciousTooth viciousTooth = new ViciousTooth(ModEntityType.VICIOUS_TOOTH.get(), livingEntity.level);
            viciousTooth.setPos(blockPos.getX() + (double) Mth.cos(f1) * 1.5D, blockpos$mutable.getY(), blockPos.getZ() + (double) Mth.cos(f1) * 1.5D);
            viciousTooth.setOwner(livingEntity);
            if (livingEntity.level.addFreshEntity(viciousTooth)) {
                viciousTooth.playSound(ModSounds.TOOTH_SPAWN.get());
            }
        }
        for (int k = 0; k < 8; ++k) {
            float f2 = (float) k * (float) Math.PI * 2.0F / 8.0F + 1.2566371F;
            ViciousTooth viciousTooth = new ViciousTooth(ModEntityType.VICIOUS_TOOTH.get(), livingEntity.level);
            viciousTooth.setPos(blockPos.getX() + (double) Mth.cos(f2) * 2.5D, blockpos$mutable.getY(), blockPos.getZ() + (double) Mth.sin(f2) * 2.5D);
            viciousTooth.setOwner(livingEntity);
            viciousTooth.setExtraDamage(damage);
            if (livingEntity.level.addFreshEntity(viciousTooth)) {
                viciousTooth.playSound(ModSounds.TOOTH_SPAWN.get());
            }
        }
    }
}

public void tick() {
	LivingEntity target = this.entity.getTarget();
	double targetDistance = this.entity.distanceToSqr(target.getX(), target.getY(), target.getZ());

	if (this.newPathCooldown > 0)
		this.newPathCooldown--;

	this.entity.getLookControl().setLookAt(target, 30, 30);

	if (this.newPathCooldown <= 0 && (this.ignoreLineOfSight || this.entity.getSensing().canSee(target)) && (this.targetLocation == null || target.distanceToSqr(this.targetLocation) >= 1 || RandomUtil.oneInNChance(20))) {
		this.targetLocation = target.position();
		this.newPathCooldown = RandomUtil.randomNumberBetween(4, 11);

		if (targetDistance > 256) {
			this.newPathCooldown += 5;

			if (targetDistance > 1024)
				this.newPathCooldown += 5;
		}

		if (!this.entity.getNavigation().moveTo(target, this.speedModifier))
			this.newPathCooldown += 15;
	}

	if (this.attackCooldown > 0)
		this.attackCooldown--;

	this.checkAndPerformAttack(target, targetDistance);
}

protected void checkAndPerformAttack(LivingEntity target, double sqrDistToTarget) {
	int animState = this.entity.getAnimationState(animKey);
	boolean withinReach = sqrDistToTarget <= getAttackReachSqr(target);

	if (animState > 0 && attackCooldown > 0)
		this.entity.setAnimationState(animKey, 0);

	if (withinReach || (animState > 0 && !this.stopAttackIfOutOfRange)) {
		if (attackCooldown <= 0) {
			this.attackCooldown = this.attackInterval;
			this.entity.swing(Hand.MAIN_HAND);
			this.entity.setAnimationState(animKey, 1);

			this.attackDamageTick = this.entity.level.getGameTime() + this.preAttackTime;
		}

		if (this.attackDamageTick >= 0 && this.entity.level.getGameTime() >= attackDamageTick) {
			if (withinReach)
				this.entity.doHurtTarget(target);

			this.entity.setAnimationState(animKey, 2);

			this.attackDamageTick = -1;
		}
	}
	else {
		this.attackDamageTick = -1;
	}
}

