public void tick() {
    boolean flag = this.inWater;
    if (!flag) {
        FluidState fluidstate = this.dolphin.level().getFluidState(this.dolphin.blockPosition());
        this.inWater = fluidstate.is(FluidTags.LAVA) || fluidstate.is(FluidTags.WATER);
    }
    if(attackCooldown > 0){
        attackCooldown--;
    }
    if (this.inWater && !flag) {
        this.dolphin.playSound(SoundEvents.DOLPHIN_JUMP, 1.0F, 1.0F);
    }
    LivingEntity target = this.dolphin.getTarget();
    if(target != null){
        if(this.dolphin.distanceTo(target) < 3F && attackCooldown <= 0){
            this.dolphin.doHurtTarget(target);
            attackCooldown = 20;
        }
    }

    Vec3 vector3d = this.dolphin.getDeltaMovement();
    if (vector3d.y * vector3d.y < (double) 0.1F && this.dolphin.getXRot() != 0.0F) {
        this.dolphin.setXRot(Mth.rotLerp(this.dolphin.getXRot(), 0.0F, 0.2F));
    } else {
        double d0 = Math.sqrt(vector3d.horizontalDistanceSqr());
        double d1 = Math.signum(-vector3d.y) * Math.acos(d0 / vector3d.length()) * (double) Mth.RAD_TO_DEG;
        this.dolphin.setXRot((float) d1);
    }

}

public void aiStep() {
    super.aiStep();
    if (this.getAnimation() == ANIMATION_SPAWN && this.getAnimationTick() < 30) {
        BlockState belowBlock = level.getBlockState(this.blockPosition().below());
        if (belowBlock.getBlock() != Blocks.AIR) {
            for (int i = 0; i < 5; i++) {
                this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, belowBlock), this.getX() + this.random.nextFloat() * this.getBbWidth() * 2.0F - this.getBbWidth(), this.getBoundingBox().minY, this.getZ() + this.random.nextFloat() * this.getBbWidth() * 2.0F - this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
            }
        }
        this.setDeltaMovement(0, this.getDeltaMovement().y, this.getDeltaMovement().z);

    }
    if (this.level.isClientSide && this.getAnimation() == ANIMATION_SUMMON) {
        double d0 = 0;
        double d1 = 0;
        double d2 = 0;
        float f = this.yBodyRot * 0.017453292F + Mth.cos(this.tickCount * 0.6662F) * 0.25F;
        float f1 = Mth.cos(f);
        float f2 = Mth.sin(f);
        IceAndFire.PROXY.spawnParticle(EnumParticles.Dread_Torch, this.getX() + (double) f1 * 0.6D, this.getY() + 1.8D, this.getZ() + (double) f2 * 0.6D, d0, d1, d2);
        IceAndFire.PROXY.spawnParticle(EnumParticles.Dread_Torch, this.getX() - (double) f1 * 0.6D, this.getY() + 1.8D, this.getZ() - (double) f2 * 0.6D, d0, d1, d2);
    }
    if (fireCooldown > 0) {
        fireCooldown--;
    }
    if (minionCooldown > 0) {
        minionCooldown--;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    dragon.getNavigation().stop();
    dragon.setTarget(null);
    double x = dragon.getX();
    double y = dragon.getY();
    if (dragon instanceof EntityDeathWorm) {
        y = ((EntityDeathWorm) dragon).processRiderY(y);
    }
    double z = dragon.getZ();
    double speed = 1.8F * dragon.getRideSpeedModifier();
    if (player.xxa != 0 || player.zza != 0) {
        Vec3 lookVec = player.getLookAngle();
        if (player.zza < 0) {
            lookVec = lookVec.yRot((float) Math.PI);
        } else if (player.xxa > 0) {
            lookVec = lookVec.yRot((float) Math.PI * 0.5f);
        } else if (player.xxa < 0) {
            lookVec = lookVec.yRot((float) Math.PI * -0.5f);
        }
        if (Math.abs(player.xxa) > 0.0) {
            speed *= 0.25D;
        }
        if (player.zza < 0.0) {
            speed *= 0.15D;
        }
        x += lookVec.x * 10;
        z += lookVec.z * 10;
    }
    dragon.getMoveControl().setWantedPosition(x, y, z, speed);
}

