public void applyEntityEffect(LivingEntity pTarget, @Nullable Entity pSource, @Nullable Entity pIndirectSource, int pAmplifier){
    for (int i = 0; i < pAmplifier + 1; ++i){
        EquipmentSlot equipmentSlot = EquipmentSlot.byTypeAndIndex(EquipmentSlot.Type.ARMOR, pTarget.getRandom().nextInt(4));
        ItemStack armor = pTarget.getItemBySlot(equipmentSlot);
        if (pTarget instanceof Mob mob){
            if (MobUtil.getEquipmentDropChance(mob, equipmentSlot) <= 0.0F){
                armor = ItemStack.EMPTY;
            }
        }
        if (EnchantmentHelper.hasBindingCurse(armor)){
            armor = ItemStack.EMPTY;
        }
        if (!armor.isEmpty()){
            ItemEntity itemEntity = new ItemEntity(pTarget.level,
                    pTarget.getX() + pTarget.getRandom().nextDouble(),
                    pTarget.getY() + pTarget.getRandom().nextDouble(),
                    pTarget.getZ() + pTarget.getRandom().nextDouble(), armor);
            itemEntity.setPickUpDelay(80);
            ItemStack itemStack = itemEntity.getItem();
            Item item = itemStack.getItem();
            if (pTarget.level.addFreshEntity(itemEntity) || item.hasCustomEntity(itemStack)){
                pTarget.setItemSlot(equipmentSlot, ItemStack.EMPTY);
                if (!pTarget.level.isClientSide) {
                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(pTarget.blockPosition(), SoundEvents.ARMOR_EQUIP_GENERIC, 10.0F, 1.5F));
                }
                pTarget.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 10.0F, 1.5F);
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    int range = spellStat.getRange();
    float velocity = spellStat.getVelocity();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        range += WandUtil.getRangeLevel(caster);
        velocity += WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster);
    }
    Vec3 vector3d = caster.getViewVector( 1.0F);
    IceStorm iceStorm = new IceStorm(
            caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.2,
            caster.getZ() + vector3d.z / 2,
            vector3d.x,
            vector3d.y,
            vector3d.z, worldIn);
    iceStorm.setExtraDamage(potency);
    iceStorm.setDuration(duration);
    iceStorm.setRange(range);
    iceStorm.setBoltSpeed((int) velocity);
    if (rightStaff(staff)){
        iceStorm.setSize(1.0F);
    }
    iceStorm.setOwner(caster);
    worldIn.addFreshEntity(iceStorm);
    this.playSound(worldIn, caster, ModSounds.WIND_BLAST.get(), 1.0F, 0.75F);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    if (rightStaff(staff)){
        return;
    }
    int potency = spellStat.getPotency();
    double radius = spellStat.getRadius();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 2.0F;
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    int amount = 3;
    for (int i = 0; i < amount; ++i) {
        Vec3 vec3 = MobUtil.getFrontPos(caster, 4.0D);
        if (i == 1) {
            vec3 = MobUtil.getRightPos(caster, 4.0D);
        } else if (i == 2) {
            vec3 = MobUtil.getLeftPos(caster, 4.0D);
        }
        ScatterMine scatterMine = new ScatterMine(worldIn, caster, vec3);
        scatterMine.setIsSpell();
        scatterMine.setExtraDamage(potency);
        scatterMine.setExtraRadius((float) radius);
        scatterMine.lifeTicks = MathHelper.secondsToTicks(duration);
        if (worldIn.addFreshEntity(scatterMine)) {
            SoundUtil.playRedstoneMineLoad(scatterMine);
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (rightStaff(staff)){
            i = 2 + caster.level.getRandom().nextInt(4);
        }
        for (int i1 = 0; i1 < i; ++i1) {
            BlockPos blockpos = caster.blockPosition().offset(-2 + caster.getRandom().nextInt(5), 1, -2 + caster.getRandom().nextInt(5));
            SpriteMob spriteMob = new SpriteMob(ModEntityType.SPRITE.get(), worldIn);
            spriteMob.setTrueOwner(caster);
            spriteMob.moveTo(blockpos, caster.getYRot(), 0.0F);
            spriteMob.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            spriteMob.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null, null);
            this.buffSummon(caster, spriteMob, potency);
            this.SummonSap(caster, spriteMob);
            this.setTarget(caster, spriteMob);
            worldIn.addFreshEntity(spriteMob);
            this.summonAdvancement(caster, spriteMob);
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.SUMMON_SPELL.get());
    }
}

private static void tick(Level level, BlockPos pos, BlockState state, AncientChestBlockEntity blockEntity) {
    if (blockEntity.state != STATE_CLOSING) {
        if (blockEntity.lidTimer > 0) {
            blockEntity.lidTimer++;
        }
        if (blockEntity.lidTimer >= 91) {
            blockEntity.state = STATE_CLOSING;
            if (!level.isClientSide) {
                ItemEntity itemEntity = new ItemEntity(level, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5,
                        new ItemStack(ModItems.ANCIENT_CLOCK.get()), 0, 0.1, 0);
                level.addFreshEntity(itemEntity);
                itemEntity = new ItemEntity(level, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5,
                        new ItemStack(ModItems.ANCIENT_HELMET.get()), 0, 0.1, 0);
                level.addFreshEntity(itemEntity);
                itemEntity = new ItemEntity(level, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5,
                        new ItemStack(ModItems.ANCIENT_JAVELIN.get()), 0, 0.1, 0);
                level.addFreshEntity(itemEntity);
                ExperienceOrb.award((ServerLevel)level, Vec3.atCenterOf(pos), 200);
            }
        }
    } else {
        if (blockEntity.lidTimer > 0) {
            blockEntity.lidTimer--;
        }
        if (blockEntity.lidTimer == 0) {
            blockEntity.state = STATE_LOCKED;
        }

    }
}

public void tick() {
	if (this.lich.getTeleportInvisibility() > 0) return;
	super.tick();
	if (this.lich.getScepterTimeLeft() > 0) return;

	List<LichMinion> minions = this.lich.level().getEntitiesOfClass(LichMinion.class, this.lich.getBoundingBox().inflate(32.0D, 16.0D, 32.0D))
		.stream().filter(m -> m.master == this.lich).toList();

	if (!minions.isEmpty()) {
		LichMinion minion = minions.getFirst();
		minion.discard();
		//rain particles
		LifedrainScepterItem.animateTargetShatter((ServerLevel) this.lich.level(), minion);
		// play death sound
		SoundEvent deathSound = EntityUtil.getDeathSound(minion);
		if (deathSound != null) {
			this.lich.level().playSound(null, minion.blockPosition(), deathSound, SoundSource.HOSTILE, 1.0F, minion.getVoicePitch());
		}
		//funny pop sound
		this.lich.playSound(TFSounds.LICH_POP_MOB.get(), 3.0F, 0.4F + this.lich.getRandom().nextFloat() * 0.2F);
		minion.playSound(TFSounds.LICH_POP_MOB.get(), 3.0F, 0.4F + this.lich.getRandom().nextFloat() * 0.2F);
		// make trail so it's clear that we did it
		this.lich.makeMagicTrail(minion.getEyePosition(), this.lich.getEyePosition(), 1.0F, 0.5F, 0.5F);
		//heal some health
		this.lich.heal(minion.getHealth());
		this.lich.swing(InteractionHand.MAIN_HAND);
		this.lich.setPopCooldown(40);
		this.lich.gameEvent(GameEvent.ENTITY_DIE);
	}
}

public void tick() {
	super.tick();

	ItemStack item = getItem(0);
	if(item.isEmpty()) {
		if(matrix != null) {
			matrixDirty = true;
			matrix = null;
		}
	} else {
		loadMatrix(item);

		if(level.getGameTime() % 20 == 0 || matrixDirty)
			updateEnchantPower();
	}

	if(charge <= 0 && !level.isClientSide) {
		ItemStack lapis = getItem(1);
		if(!lapis.isEmpty()) {
			lapis.shrink(1);
			charge += MatrixEnchantingModule.chargePerLapis;
			sync();
		}
	}

	if(matrixDirty) {
		makeOutput();
		matrixDirty = false;
	}
}

	public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker)
	{
		if (super.hurtEnemy(stack, target, attacker))
		{
			if (attacker instanceof Player)
			{
				Player attackerPlayer = (Player) attacker;
				this.recalculatePowers(stack, attackerPlayer.getCommandSenderWorld(), attackerPlayer);
				EnumDemonWillType type = this.getCurrentType(stack);
				double will = PlayerDemonWillHandler.getTotalDemonWill(type, attackerPlayer);
				int willBracket = this.getLevel(stack, will);

				applyEffectToEntity(type, willBracket, target, attackerPlayer);

