public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    Component name = getName(world, shooter, spellStats, spellContext, resolver);
    BlockPos pos = rayTraceResult.getBlockPos();
    BlockState state = world.getBlockState(pos);
    BlockEntity blockEntity = world.getBlockEntity(pos);
    if (blockEntity instanceof SkullBlockEntity head) {
        head.setOwner(name == null ? null : new ResolvableProfile(Optional.of(name.getString()), Optional.empty(), new PropertyMap()));
        world.sendBlockUpdated(pos, state, state, 3);
        return;
    }
    if (blockEntity instanceof BaseContainerBlockEntity nameable) {
        nameable.name = name;
        world.sendBlockUpdated(pos, state, state, 3);
        nameable.setChanged();
        return;
    }

    for (Entity entity : world.getEntities(null, new AABB(pos).inflate(0.08))) {
        entity.setCustomName(name);
        if (entity instanceof Mob mob && mob.hasCustomName()) {
            mob.setPersistenceRequired();
        } else if (entity instanceof ItemEntity item) {
            if (name == null) {
                item.getItem().remove(DataComponents.CUSTOM_NAME);
            } else {
                item.getItem().set(DataComponents.CUSTOM_NAME, name);
            }
        }
    }
}

public void onResolve(HitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    super.onResolve(rayTraceResult, world, shooter, spellStats, spellContext, resolver);

    var loc = rayTraceResult.getLocation();
    double x = loc.x;
    double y = loc.y;
    double z = loc.z;

    var dummyWindCharge = new WindCharge(world, x, y, z, Vec3.ZERO);
    if (spellStats.isSensitive()) {
        dummyWindCharge.setOwner(shooter);
    }

    world.explode(
            spellStats.isSensitive() ? shooter : dummyWindCharge,
            null,
            new SimpleExplosionDamageCalculator(
                    true, false, Optional.of(1.22f + (float) (spellStats.getAmpMultiplier() * this.AMP_VALUE.getAsDouble())), BuiltInRegistries.BLOCK.getTag(BlockTags.BLOCKS_WIND_CHARGE_EXPLOSIONS).map(Function.identity())
            ),
            x,
            y,
            z,
            1.2f + (float) (spellStats.getAoeMultiplier() * this.GENERIC_DOUBLE.getAsDouble()),
