            Level.ExplosionInteraction.TRIGGER,
            ParticleTypes.GUST_EMITTER_SMALL,
            ParticleTypes.GUST_EMITTER_LARGE,
            SoundEvents.WIND_CHARGE_BURST
    );
}

public boolean canUse() {
    LivingEntity target = mob.getTarget();
    if ((target == null || !target.isAlive()) && mob.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
        if (executionCooldown-- > 0) {
            return false;
        } else {
            executionCooldown = 350 + mob.getRandom().nextInt(200);
            BlockPos pos = null;
            if (mob.getLastCruciblePos() != null) {
                if (canWitchUseCrucibleAt(mob.level(), mob.getLastCruciblePos(), true)) {
                    executionCooldown = 10;
                    pos = mob.getLastCruciblePos();
                } else {
                    mob.setLastCruciblePos(null);
                }
            }
            if (pos == null) {
                List<BlockPos> list = getNearbyCrucibles(mob.blockPosition(), (ServerLevel) mob.level(), 32).sorted(Comparator.comparingDouble(mob.blockPosition()::distSqr)).toList();
                if (!list.isEmpty()) {
                    pos = list.get(0);
                }
            }
            if (pos != null && mob.getRandom().nextInt(4) == 0) {
                cruciblePos = pos;
                mob.setLastCruciblePos(cruciblePos);
                return true;
            }
        }
    }
    return false;
}

public void breakBlock() {
    if (blockBreakCooldown-- > 0) {
        return;
    }
    boolean flag = false;
    AABB damageBox = this.headPart.getBoundingBox().inflate(1.2F).move(this.calculateViewVector(this.getXRot(), this.getYRot()));
    if (!level().isClientSide && net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(level(), this) && this.getTarget() instanceof Player) {
        for (int a = (int) Math.round(damageBox.minX); a <= (int) Math.round(damageBox.maxX); a++) {
            for (int b = (int) Math.round(damageBox.minY) - 1; (b <= (int) Math.round(damageBox.maxY) + 1) && (b <= 127); b++) {
                for (int c = (int) Math.round(damageBox.minZ); c <= (int) Math.round(damageBox.maxZ); c++) {
                    final BlockPos pos = new BlockPos(a, b, c);
                    final BlockState state = level().getBlockState(pos);
                    if (!state.isAir() && !state.getShape(level(), pos).isEmpty() && !state.is(ACTagRegistry.UNMOVEABLE) && state.getBlock().getExplosionResistance() <= 15) {
                        final Block block = state.getBlock();
                        if (block != Blocks.AIR) {
                            this.setDeltaMovement(this.getDeltaMovement().multiply(0.6F, 1, 0.6F));
                            flag = true;
                            level().destroyBlock(pos, true);
                            if (state.is(BlockTags.ICE)) {
                                level().setBlockAndUpdate(pos, Blocks.WATER.defaultBlockState());
                            }
                        }
                    }
                }
            }
        }
    }
    if (flag) {
        blockBreakCooldown = 3;
    }
}

public void rideTick() {
    final Entity entity = this.getVehicle();
    if (this.isPassenger() && !entity.isAlive()) {
        this.stopRiding();
    } else if (isTame() && entity instanceof LivingEntity && isOwnedBy((LivingEntity) entity)) {
        this.setDeltaMovement(0, 0, 0);
        this.tick();
        if (this.isPassenger()) {
            final Entity mount = this.getVehicle();
            if (mount instanceof final Player player) {
                this.yBodyRot = player.yBodyRot;
                this.setYRot(player.getYRot());
                this.yHeadRot = player.yHeadRot;
                this.yRotO = player.yHeadRot;
                final float radius = 0F;
                final float angle = (Maths.STARTING_ANGLE * (((LivingEntity) mount).yBodyRot - 180F));
                final double extraX = radius * Mth.sin(Mth.PI + angle);
                final double extraZ = radius * Mth.cos(angle);
                this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getBbHeight() + 0.1, mount.getY()), mount.getZ() + extraZ);
                attackDecision = true;
                if (!mount.isAlive() || rideCooldown == 0 && mount.isShiftKeyDown()) {
                    this.removeVehicle();
                    attackDecision = false;
                }
            }
        }
    } else {
        super.rideTick();
    }

}

private void updateEars() {
    final float pitchDist = Math.abs(targetPitch - this.getEarPitch());
    final float yawDist = Math.abs(targetYaw - this.getEarYaw());
    if (earCooldown <= 0 && this.random.nextInt(30) == 0 && pitchDist <= 0.1F && yawDist <= 0.1F) {
        targetPitch = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
        targetYaw = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
        earCooldown = 8 + random.nextInt(15);
    }

    if (pitchDist > 0.1F) {
        if (this.getEarPitch() < this.targetPitch) {
            this.setEarPitch(this.getEarPitch() + Math.min(pitchDist, 4F));
        }
        if (this.getEarPitch() > this.targetPitch) {
            this.setEarPitch(this.getEarPitch() - Math.min(pitchDist, 4F));
        }
    }

    if (yawDist > 0.1F) {
        if (this.getEarYaw() < this.targetYaw) {
            this.setEarYaw(this.getEarYaw() + Math.min(yawDist, 4F));
        }
        if (this.getEarYaw() > this.targetYaw) {
            this.setEarYaw(this.getEarYaw() - Math.min(yawDist, 4F));
        }
    }

    if (earCooldown > 0) {
        earCooldown--;
    }
}

