public boolean doHurtTarget(@NotNull Entity entityIn) {
    if (this.getGrowthStage() < 2) {
        return false;
    }
    if (this.getAnimation() != ANIMATION_STING && this.getAnimation() != ANIMATION_BITE) {
        this.setAnimation(this.getRandom().nextBoolean() ? ANIMATION_STING : ANIMATION_BITE);
        float f = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
        this.setLastHurtMob(entityIn);
        boolean flag = entityIn.hurt(DamageSource.mobAttack(this), f);
        if (this.getAnimation() == ANIMATION_STING && flag) {
            this.playStingSound();
            if (entityIn instanceof LivingEntity) {
                ((LivingEntity) entityIn).addEffect(new MobEffectInstance(MobEffects.POISON, 200, 2));
                this.setTarget((LivingEntity) entityIn);
            }
        } else {
            this.playBiteSound();
        }
        if (!this.level.isClientSide && this.getRandom().nextInt(3) == 0 && this.getItemInHand(InteractionHand.MAIN_HAND) != ItemStack.EMPTY) {
            this.spawnAtLocation(this.getItemInHand(InteractionHand.MAIN_HAND), 0);
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
        }
        if (!this.getPassengers().isEmpty()) {
            for (Entity entity : this.getPassengers()) {
                entity.stopRiding();
            }
        }
        return true;
    }
    return false;
}

public void updateTask() {
	if(this.taskOwner instanceof EntityCreature) {
		EntityCreature creature = (EntityCreature) this.taskOwner;
		EntityLivingBase target = creature.getAttackTarget();

		if(target == this.puppeteer.get()) {
			creature.setAttackTarget(null);
		} else if(target != null) {
			IPuppetCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);
			if(cap != null && cap.getPuppeteer() == this.puppeteer.get()) {
				creature.setAttackTarget(null);
			}
		}
	}

	this.setMutexBits(0);

	if(this.tasks != null) {
		int mutexBits = 0;

		this.tasks.onUpdateTasks();

		for(EntityAITasks.EntityAITaskEntry task : this.tasks.taskEntries) {
			//if(task.using) {
			mutexBits |= task.action.getMutexBits();
			//}
		}

		this.setMutexBits(mutexBits);
	}
}

public void respondToAttack(EntityLivingBase attacker) {
    if (attacker != null && !attacker.isDead && !(attacker instanceof EntityPlayer && ((EntityPlayer) attacker).capabilities.isCreativeMode)) {
        List<EntityLivingBase> enemies = new LinkedList<>();

        if (attacker instanceof DinosaurEntity) {
            DinosaurEntity enemyDinosaur = (DinosaurEntity) attacker;

            if (enemyDinosaur.herd != null) {
                enemies.addAll(enemyDinosaur.herd.members);
            }
        } else {
            enemies.add(attacker);
        }

        if (enemies.size() > 0) {
            Herd herd = this.herd;

            if (herd != null) {
                herd.fleeing = !herd.shouldDefend(enemies) || this.dinosaur.shouldFlee();

                for (EntityLivingBase entity : enemies) {
                    if (!herd.enemies.contains(entity)) {
                        herd.enemies.add(entity);
                    }
                }
            } else {
                this.setAttackTarget(enemies.get(this.getRNG().nextInt(enemies.size())));
            }
        }
    }
}

