public void releaseUsing(ItemStack bow, Level level, LivingEntity living, int chargeRemaining) {
  ToolStack tool = ToolStack.from(bow);

  // call the stop using modifier hook
  int duration = getUseDuration(bow);
  for (ModifierEntry entry : tool.getModifiers()) {
    entry.getHook(ModifierHooks.TOOL_USING).beforeReleaseUsing(tool, entry, living, duration, chargeRemaining, ModifierEntry.EMPTY);
  }

  // any reason we shouldn't load?
  // specifically: broken, not fully charged, already have ammo
  ModDataNBT persistentData = tool.getPersistentData();
  if (tool.isBroken() || getUseDuration(bow) - chargeRemaining < persistentData.getInt(KEY_DRAWTIME) || persistentData.contains(KEY_CROSSBOW_AMMO, Tag.TAG_COMPOUND)) {
    return;
  }

  // find ammo and store it on the bow
  Player player = living instanceof Player p ? p : null;
  ItemStack ammo = BowAmmoModifierHook.consumeAmmo(tool, bow, living, player, getSupportedHeldProjectiles());
  if (!ammo.isEmpty()) {
    level.playSound(null, living.getX(), living.getY(), living.getZ(), SoundEvents.CROSSBOW_LOADING_END, SoundSource.PLAYERS, 1.0F, 1.0F / (level.getRandom().nextFloat() * 0.5F + 1.0F) + 0.2F);
    if (!level.isClientSide) {
      CompoundTag ammoNBT = ammo.save(new CompoundTag());
      persistentData.put(KEY_CROSSBOW_AMMO, ammoNBT);
      // if the crossbow broke during loading, fire immediately
      if (tool.isBroken()) {
        fireCrossbow(tool, living, player != null && player.getAbilities().instabuild, living.getUsedItemHand(), ammoNBT);
      }
    }
  }
}

public boolean onEntityAttacked(DamageSource src, float amt) {
    if (getLevel() > 0) {
        if (isDBNO() && !Helper.canKillVampires(src)) {
            if (src.getEntity() != null && src.getEntity() instanceof Mob && ((Mob) src.getEntity()).getTarget() == player) {
                ((Mob) src.getEntity()).setTarget(null);
            }
            return true;
        }
        if (asEntity().level() instanceof ServerLevel level) {
            if (src.is(DamageTypes.ON_FIRE)) {
                DamageHandler.hurtModded(level, player, ModDamageSources::vampireOnFire, calculateFireDamage(amt));
                return true;
            } else if (src.is(DamageTypes.IN_FIRE) || src.is(DamageTypes.LAVA)) {
                DamageHandler.hurtModded(level, player, ModDamageSources::vampireInFire, calculateFireDamage(amt));
                return true;
            }
        }
    }
    endFeeding(true);
    if (getSkillProperties().half_invulnerable) {
        if (amt >= asEntity().getMaxHealth() * (this.getRefinementHandler().isRefinementEquipped(ModRefinements.HALF_INVULNERABLE) ? ModConfig.balance().vrHalfInvulnerableThresholdMod.get() : 1) * ModConfig.balance().vaHalfInvulnerableThreshold.get() && amt < 999) { //Make sure "instant kills" are not blocked by this
            if (useBlood(ModConfig.balance().vaHalfInvulnerableBloodCost.get(), false)) {
                return true;
            } else {
                this.getActionHandler().deactivateAction(VampireActions.HALF_INVULNERABLE);
            }
        }
    }

    return false;
}

private boolean bite(LivingEntity entity) {
    if (this.specialAttributes.biteTicks > 0) return false;
    if (!this.form.isTransformed()) return false;
    if (!canBite()) return false;
    if (!canBiteEntity(entity)) return false;
    double damage = this.player.getAttribute(ModAttributes.BITE_DAMAGE).getValue();
    boolean flag = DamageHandler.hurtModded(entity, (ModDamageSources sources) -> sources.bite(this.player), (float) damage);
    if (flag) {
        this.getRepresentingPlayer().playSound(ModSounds.ENTITY_WEREWOLF_BITE.get(), 1.0F, 1.0F);
        this.getRepresentingPlayer().playNotifySound(ModSounds.ENTITY_WEREWOLF_BITE.get(), SoundSource.PLAYERS, 1.0F, 1.0F);
        this.eatEntity(entity);
        this.specialAttributes.biteTicks = WerewolvesConfig.BALANCE.PLAYER.bite_cooldown.get();
        if (!getForm().isHumanLike()) {
            if (this.skillHandler.isSkillEnabled(ModSkills.STUN_BITE.get())) {
                int duration = WerewolvesConfig.BALANCE.SKILLS.stun_bite_duration.get();
                if (this.skillHandler.isRefinementEquipped(ModRefinements.STUN_BITE.get())) {
                    duration += WerewolvesConfig.BALANCE.REFINEMENTS.stun_bite_duration_extend.get();
                }
                entity.addEffect(new MobEffectInstance(ModEffects.STUN, duration));
            }
            if (this.skillHandler.isSkillEnabled(ModSkills.BLEEDING_BITE.get())) {
                entity.addEffect(new MobEffectInstance(ModEffects.BLEEDING, WerewolvesConfig.BALANCE.SKILLS.bleeding_bite_duration.get(), this.skillHandler.isRefinementEquipped(ModRefinements.BLEEDING_BITE.get()) ? 3 : 0));
            }
        }
        this.sync(NBTHelper.nbtWith(nbt -> nbt.putInt("biteTicks", this.specialAttributes.biteTicks)), false);
        if (!(entity instanceof ServerPlayer) || PermissionAPI.getPermission((ServerPlayer) this.getRepresentingPlayer(), Permissions.INFECT_PLAYER)) {
            LupusSanguinemEffect.infectRandomByPlayer(entity);
        }
    }
    return flag;
}

public static DigMode cycleDigMode(ItemStack stack, boolean forward) {
    if (stack.getItem() instanceof JackHammerItem jackHammer) {
        DrillBitType ourBit = getDrillBit(stack);
        DigMode currentMode = getDigMode(stack);
        DigMode newMode = currentMode;
        if (forward) {
            if (currentMode == DigMode.MODE_VEIN_PLUS) {
                newMode = DigMode.MODE_1X1;
            } else {
                newMode = DigMode.values()[currentMode.ordinal() + 1];
                newMode = newMode.getBitType().getBitQuality() <= ourBit.getBitQuality() ? newMode : DigMode.MODE_1X1;
            }
        } else {
            if (currentMode == DigMode.MODE_1X1) {
                // search backward to find the highest dig mode our bit supports
                for (int i = DigMode.values().length - 1; i >= 0; i--) {
                    if (DigMode.values()[i].getBitType().getBitQuality() <= ourBit.getBitQuality()) {
                        newMode = DigMode.values()[i];
                        break;
                    }
                }
            } else {
                newMode = DigMode.values()[currentMode.ordinal() - 1];
            }
        }

        setDigMode(stack, newMode);
        return newMode;
    }
    return null;
}

private void advanceHeadState() {
	// check head state
	if (++this.ticksProgress >= this.ticksNeeded) {
		State myNext;

		// advance state
		if (this.nextState == NEXT_AUTOMATIC) {
			myNext = State.NEXT_STATE.get(this.currentState);
			if (myNext != this.currentState) {
				// when returning from a secondary attack, no attack cooldown
				if (this.isSecondaryAttacking && myNext == State.ATTACK_COOLDOWN) {
					this.isSecondaryAttacking = false;
					myNext = State.IDLE;
				}
			}
		} else {
			myNext = this.nextState;
			this.nextState = NEXT_AUTOMATIC;
		}

		this.ticksNeeded = myNext.duration;
		this.ticksProgress = 0;

		this.prevState = this.currentState;
		this.currentState = myNext;
	}
	// set datawatcher so client can properly animate
	if (this.headEntity.getState() != this.currentState) {
		this.headEntity.setState(this.currentState);
	}
}

public EnumActionResult onItemUseFirst(EntityPlayer player, World world, BlockPos pos, EnumFacing side, float hitX, float hitY, float hitZ, EnumHand hand) {
	ItemStack stack = player.getHeldItem(hand);
	if (stack.getItemDamage() != 1) {
		BlockPos offset = pos.offset(side);
		IBlockState offsetState = world.getBlockState(offset);
		if (offsetState.getBlock().isAir(offsetState, world, offset) || offsetState.getBlock().isReplaceable(world, offset)) {

			if (!world.mayPlace(ModBlocks.JAR, offset, false, side, player)) return PASS;

			boolean replacable = world.getBlockState(pos).getBlock().isReplaceable(world, pos);
			boolean success = world.setBlockState(replacable ? pos : offset, ModBlocks.JAR.getDefaultState());
			if (success) {
				world.playSound(pos.getX(), pos.getY(), pos.getZ(), SoundEvents.BLOCK_GLASS_PLACE, SoundCategory.BLOCKS, 1, 1, false);

				if (!player.isCreative())
					stack.shrink(1);

				TileEntity tileEntity = world.getTileEntity(replacable ? pos : offset);
				if (tileEntity instanceof TileJar) {
					TileJar jar = (TileJar) tileEntity;
					jar.fairy = FairyData.deserialize(NBTHelper.getCompound(stack, "fairy"));
					jar.markDirty();
					world.checkLight(replacable ? pos : offset);
				}
			}

			return SUCCESS;
		}
	}
	return PASS;
}

public void tick() {
	super.tick();

	LivingEntity target = this.entity.getTarget();
	double targetDistance = this.entity.distanceToSqr(target.getX(), target.getY(), target.getZ());

	if (this.newPathCooldown > 0)
		this.newPathCooldown--;

	this.entity.getLookControl().setLookAt(target, 30, 30);

	if (this.newPathCooldown <= 0 && (this.ignoreLineOfSight || this.entity.getSensing().hasLineOfSight(target)) && (this.targetLocation == null || target.distanceToSqr(this.targetLocation) >= 1 || RandomUtil.oneInNChance(20))) {
		this.targetLocation = target.position();
		this.newPathCooldown = RandomUtil.numberBetween(4, 11);

		if (targetDistance > 256) {
			this.newPathCooldown += 5;

			if (targetDistance > 1024)
				this.newPathCooldown += 5;
		}

		if (!this.entity.getNavigation().moveTo(target, this.speedModifier))
			this.newPathCooldown += 15;
	}

	if (this.attackCooldown > 0)
		this.attackCooldown--;

	this.checkAndPerformAttack(target, targetDistance);
}

