public void releaseUsing(ItemStack stack, Level level, LivingEntity shooter, int timeLeft) {
	boolean infiniteAmmo = (shooter instanceof Player pl && pl.hasInfiniteMaterials()) || EnchantmentUtil.hasEnchantment(level, stack, Enchantments.INFINITY);
	ItemStack ammoStack = findAmmo(shooter, stack, infiniteAmmo);

	if (ammoStack.isEmpty())
		return;

	int charge = (int)((getUseDuration(stack, shooter) - timeLeft) * getDrawSpeedMultiplier(stack));

	if (shooter instanceof Player pl)
		charge = EventHooks.onArrowLoose(stack, level, pl, charge, true);

	if (charge < 0)
		return;

	float power = getPowerForTime(charge);

	if (power < 0.1f)
		return;

	List<ItemStack> projectileItems = drawProjectileItems(stack, ammoStack, shooter, power, false);

	if (!projectileItems.isEmpty() && level instanceof ServerLevel serverLevel)
		fireArrows(stack, this, ammoStack, projectileItems, serverLevel, shooter, power, getBowDamage(stack), infiniteAmmo);

	if (!level.isClientSide)
		SoundBuilder.at(SoundEvents.ARROW_SHOOT, shooter).pitch(1f / RandomUtil.valueBetween(1.2f, 1.6f) + power * 0.5F).play();

	if (shooter instanceof Player pl)
		pl.awardStat(Stats.ITEM_USED.get(this));
}

public static Mana calcMaxMana(Player e) {
    IManaCap mana = CapabilityRegistry.getMana(e);
    if (mana == null)
        return new Mana(0, 0f);

    double rawMax = 0;
    int tier = mana.getBookTier();
    int numGlyphs = mana.getGlyphBonus();

    rawMax += ServerConfig.INIT_MAX_MANA.get();
    rawMax += numGlyphs * ServerConfig.GLYPH_MAX_BONUS.get();
    rawMax += tier * ServerConfig.TIER_MAX_BONUS.get();

    var manaAttribute = e.getAttribute(PerkAttributes.MAX_MANA);
    if (manaAttribute != null) {
        var manaCache = manaAttribute.getModifier(MAX_MANA_MODIFIER);
        if (manaCache == null || manaCache.amount() != rawMax) {
            if (manaCache != null) manaAttribute.removeModifier(manaCache);
            manaAttribute.addTransientModifier(new AttributeModifier(MAX_MANA_MODIFIER, rawMax, AttributeModifier.Operation.ADD_VALUE));
        }
        rawMax = manaAttribute.getValue();
    }

    int max = (int) rawMax;

    MaxManaCalcEvent event = new MaxManaCalcEvent(e, max);
    NeoForge.EVENT_BUS.post(event);
    max = event.getMax();
    float reserve = event.getReserve();
    return new Mana(max, reserve);
}

public static @Nullable EnchantedFallingBlock fall(Level level, BlockPos pos, Entity owner, SpellContext context, SpellResolver resolver, SpellStats spellStats) {
    if (!canFall(level, pos, owner, spellStats)) return null;
    BlockState blockState = level.getBlockState(pos);
    EnchantedFallingBlock fallingblockentity;
    if (level.getBlockEntity(pos) instanceof MageBlockTile tile) {
        fallingblockentity = new EnchantedMageblock(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState);
        fallingblockentity.resolver = resolver;
    } else if (level.getBlockEntity(pos) instanceof SkullBlockEntity tile) {
        fallingblockentity = new EnchantedSkull(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState);
    } else {
        fallingblockentity = new EnchantedFallingBlock(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState, resolver);
    }
    if (level.getBlockEntity(pos) != null) {
        fallingblockentity.blockData = level.getBlockEntity(pos).saveWithoutMetadata(level.registryAccess());
    }
    level.addFreshEntity(fallingblockentity);
    fallingblockentity.setOwner(owner);
    fallingblockentity.context = context;
    fallingblockentity.baseDamage = (float) (9.0f + spellStats.getDamageModifier());
    fallingblockentity.dropItem = !blockState.is(BlockTagProvider.GRAVITY_BLACKLIST);
    fallingblockentity.spellStats = spellStats;
    if (resolver.hasFocus(ItemsRegistry.SHAPERS_FOCUS.get())) {
        fallingblockentity.hurtEntities = true;
    }
    if (context != null) {
        RewindAttachment rewindAttachment = RewindAttachment.get(context);
        rewindAttachment.addRewindEvent(level.getGameTime(), new BlockToEntityRewind(pos, blockState));
    }
    level.setBlock(pos, blockState.getFluidState().createLegacyBlock(), 3);
    return fallingblockentity;
}

public void onRewind(RewindEvent event) {
    var entity = event.entity;
    if (!(entity instanceof IRewindable rewindable) || entity.isRemoved() || (entity instanceof LivingEntity living && living.isDeadOrDying())) {
        return;
    }
    entity.hurtMarked = true;
    // Disable the flag that prevents the entity from moving and reenable
    rewindable.setRewinding(false);

    if (event.respectsGravity) {
        if (entity instanceof LivingEntity le) {
            var weightless = le.getAttribute(PerkAttributes.WEIGHT);
            var modifierId = ArsNouveau.prefix("rewind");
            if (weightless != null) {
                weightless.addOrUpdateTransientModifier(new AttributeModifier(modifierId, -1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
            }
        } else {
            entity.setNoGravity(true);
        }
    }
    entity.setPos(position);
    entity.setDeltaMovement(deltaMovement.scale(-1));
    entity.fallDistance = 0;
    rewindable.setRewinding(true);

    if (event.serverSide) {
        if (entity instanceof LivingEntity living) {
            living.setHealth(health);
        }
    }
}

private static void guardianUltimateSacrifice(LivingDeathEvent event) {
    if (event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY) || !(event.getEntity() instanceof Player player))
        return;

    if (!FamiliarUtil.isFamiliarEnabled(player, OccultismEntities.GUARDIAN_FAMILIAR.get()))
        return;

    GuardianFamiliarEntity guardian = FamiliarUtil.getFamiliar(player, OccultismEntities.GUARDIAN_FAMILIAR.get());
    if (guardian == null)
        return;

    if (!guardian.isAddedToLevel() && player.hasEffect(OccultismEffects.OCCULT_UNDYING_COOLDOWN)) {
        return;
    }

    if (!guardian.sacrifice())
        return;

    event.setCanceled(true);
    player.setHealth(1);
    player.removeAllEffects();
    player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20 * 10, 1));
    player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 20 * 5, 1));
    player.invulnerableTime = 30;
    if (!guardian.isAddedToLevel()) {
        int i = guardian.hasBlacksmithUpgrade() ? 6 : 7;
        int t = guardian.hasIesniumUpgrade() ? 10 : 20;
        i -= guardian.getLives();
        player.addEffect(new MobEffectInstance(OccultismEffects.OCCULT_UNDYING_COOLDOWN, i * 60 * t, 0, true, true));
    }
}

