public boolean canUse() {
    LivingEntity target = mob.getTarget();
    if ((target == null || !target.isAlive()) && (mob.getItemInHand(InteractionHand.OFF_HAND).is(ACTagRegistry.GINGERBREAD_MAN_STEALS) || mob.isOvenSpawned() && !mob.getItemInHand(InteractionHand.OFF_HAND).isEmpty())) {
        if (executionCooldown-- > 0) {
            return false;
        } else {
            executionCooldown = 20 + mob.getRandom().nextInt(30);
            BlockPos pos = null;
            if (mob.getLastBarrelPos() != null) {
                if (doesBarrelHaveSpace(mob.level(), mob.getLastBarrelPos(), mob.getItemInHand(InteractionHand.OFF_HAND))) {
                    executionCooldown = 10;
                    pos = mob.getLastBarrelPos();
                } else {
                    mob.setLastBarrelPos(null);
                }
            }
            if (pos == null) {
                List<BlockPos> list = getNearbyBarrels(mob.blockPosition(), (ServerLevel) mob.level(), 32).sorted(Comparator.comparingDouble(mob.blockPosition()::distSqr)).toList();
                if (!list.isEmpty()) {
                    pos = list.get(0);
                }
            }
            if (pos != null) {
                barrelPos = pos;
                mob.setLastBarrelPos(barrelPos);
                openBarrelTicks = 0;
                return true;
            }
        }
    }
    return false;
}

public void tick() {
    boolean flag = this.inWater;
    if (!flag) {
        FluidState fluidstate = this.dolphin.level().getFluidState(this.dolphin.blockPosition());
        this.inWater = fluidstate.is(FluidTags.WATER);
    }
    if(attackCooldown > 0){
        attackCooldown--;
    }
    if (this.inWater && !flag) {
        this.dolphin.playSound(SoundEvents.DOLPHIN_JUMP, 1.0F, 1.0F);
    }
    LivingEntity target = this.dolphin.getTarget();
    if(target != null){
        if(this.dolphin.distanceTo(target) < 3F && attackCooldown <= 0){
            this.dolphin.onJumpHit(target);
            attackCooldown = 20;
        }else if(this.dolphin.distanceTo(target) < 5F){
            this.dolphin.setAnimation(EntityOrca.ANIMATION_BITE);
        }
    }

    Vec3 vector3d = this.dolphin.getDeltaMovement();
    if (vector3d.y * vector3d.y < (double) 0.1F && this.dolphin.getXRot() != 0.0F) {
        this.dolphin.setXRot(Mth.rotLerp(this.dolphin.getXRot(), 0.0F, 0.2F));
    } else {
        final double d0 = Math.sqrt(vector3d.horizontalDistanceSqr());
        final double d1 = Math.signum(-vector3d.y) * Math.acos(d0 / vector3d.length()) * (double) Mth.RAD_TO_DEG;
        this.dolphin.setXRot((float) d1);
    }

}

public void tick() {
    if (targetPos != null && waterPos != null) {
        double dist = bird.distanceToSqr(Vec3.atCenterOf(waterPos));
        if (dist <= 1F) {
            navigateTime = 0;
            double d0 = waterPos.getX() + 0.5D - bird.getX();
            double d2 = waterPos.getZ() + 0.5D - bird.getZ();
            float yaw = (float)(Mth.atan2(d2, d0) * (double)Mth.RAD_TO_DEG) - 90.0F;
            bird.setYRot(yaw);
            bird.yHeadRot = yaw;
            bird.yBodyRot = yaw;
            bird.getNavigation().stop();
            idleTime++;
            if(idleTime > 25){
                bird.setAnimation(EntityShoebill.ANIMATION_FISH);
            }
            if(idleTime > 45 && bird.getAnimation() == EntityShoebill.ANIMATION_FISH){
                this.bird.gameEvent(GameEvent.ITEM_INTERACT_START);
                this.bird.playSound(SoundEvents.GENERIC_SPLASH, 0.7F, 0.5F + bird.getRandom().nextFloat());
                this.bird.resetFishingCooldown();
                this.spawnFishingLoot();
                this.stop();
            }
        }else{
            navigateTime++;
            bird.getNavigation().moveTo(waterPos.getX(), waterPos.getY(), waterPos.getZ(), 1.2D);
        }
        if(navigateTime > 3600){
            this.stop();
        }
    }
}

protected void onHit(@NotNull HitResult movingObject) {
    boolean flag = false;
    Entity shootingEntity = this.getOwner();
    if (!this.level.isClientSide) {
        if (movingObject.getType() == HitResult.Type.ENTITY && !((EntityHitResult) movingObject).getEntity().is(shootingEntity)) {
            Entity entity = ((EntityHitResult) movingObject).getEntity();
            if (shootingEntity != null && shootingEntity.equals(entity)) {
                flag = true;
            } else {
                if (entity instanceof LivingEntity) {
                    ((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.LEVITATION, 100, 0));
                    ((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.GLOWING, 100, 0));
                    entity.hurt(DamageSource.indirectMagic(shootingEntity, null), 5.0F);
                }
                if (this.level.isClientSide) {
                    for (int i = 0; i < 20; ++i) {
                        IceAndFire.PROXY.spawnParticle(EnumParticles.If_Pixie, this.getX() + this.random.nextDouble() * 1F * (this.random.nextBoolean() ? -1 : 1), this.getY() + this.random.nextDouble() * 1F * (this.random.nextBoolean() ? -1 : 1), this.getZ() + this.random.nextDouble() * 1F * (this.random.nextBoolean() ? -1 : 1), rgb[0], rgb[1], rgb[2]);
                    }
                }
                if (shootingEntity == null || !(shootingEntity instanceof Player) || !((Player) shootingEntity).isCreative()) {
                    if (random.nextInt(3) == 0) {
                        this.spawnAtLocation(new ItemStack(IafItemRegistry.PIXIE_DUST.get(), 1), 0.45F);
                    }
                }
            }
            if (!flag && this.tickCount > 4) {
                this.remove(RemovalReason.DISCARDED);
            }
        }

    }
}

