public void updateTask() {
	--attackTime;
	EntityLivingBase entitylivingbase = crab.getAttackTarget();
	if (entitylivingbase != null && entitylivingbase.isEntityAlive()) {
		double d0 = crab.getDistanceSq(entitylivingbase);
		if (d0 < 25D) {
			double d1 = entitylivingbase.posX - crab.posX;
			double d2 = entitylivingbase.posY - crab.posY;
			double d3 = entitylivingbase.posZ - crab.posZ;
			if (attackTime <= 0) {
				++attackStep;
				if (attackStep == 1)
					attackTime = 40;
				else {
					attackTime = 40;
					attackStep = 0;
				}
				if (attackStep == 1) {
					EntityBubblerCrabBubble entityBubble = new EntityBubblerCrabBubble(crab.getEntityWorld(),
							crab);
					entityBubble.setPosition(crab.posX, crab.posY + crab.height + 0.5D, crab.posZ);
					entityBubble.shoot(d1, d2, d3, 0.5F, 0F);
					crab.getEntityWorld().spawnEntity(entityBubble);
					crab.getEntityWorld().playSound((EntityPlayer) null, crab.getPosition(),
							SoundRegistry.BUBBLER_SPIT, SoundCategory.HOSTILE, 1F, 1.0F);
					crab.aggroCooldown = 0;
				}
			}
		}
	}
	super.updateTask();
}

public boolean attackEntityFrom(DamageSource damageSrc, float damage) {
	if(this.getEntityWorld().isRemote)
		return false;
    if(this.isEntityInvulnerable(damageSrc))
    	return false;
    if(!this.isDamageTypeApplicable(damageSrc.getDamageType(), damageSrc, damage))
    	return false;
    if(!this.isDamageEntityApplicable(damageSrc.getTrueSource()))
    	return false;
    damage *= this.getDamageModifier(damageSrc);
    damage = this.getDamageAfterDefense(damage);
    if(this.isBoss() || this.isRareSubspecies()) {
        if (!(damageSrc.getTrueSource() instanceof EntityPlayer))
            damage *= 0.25F;
    }

    if(super.attackEntityFrom(damageSrc, damage)) {
    	this.onDamage(damageSrc, damage);
        Entity entity = damageSrc.getImmediateSource();
        if(entity instanceof EntityThrowable)
        	entity = ((EntityThrowable)entity).getThrower();

        if(entity instanceof EntityLivingBase && this.getRider() != entity && this.getRidingEntity() != entity) {
            if(entity != this)
                this.setRevengeTarget((EntityLivingBase)entity);
            return true;
        }
        else
            return true;
    }
    return false;
}

public void specialAttack() {
    // Withering Roar:
    double distance = 5.0D;
    List<EntityLivingBase> possibleTargets = this.getEntityWorld().getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(distance, distance, distance), new Predicate<EntityLivingBase>() {
