public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int range = spellStat.getRange();
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, 3);
    LivingEntity target = this.getTarget(caster, range);
    Vec3 vec3 = null;
    if (target != null){
        vec3 = target.position();
    } else if (rayTraceResult instanceof BlockHitResult result){
        vec3 = result.getLocation();
    }
    if (vec3 != null) {
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            WandUtil.spawnTowerIceBouquet(worldIn, vec3, caster, potency, MathHelper.secondsToTicks(duration));
        } else if (rightStaff(staff)) {
            if (worldIn.getRandom().nextFloat() <= 0.05F) {
                WandUtil.spawnCrossIceBouquet(worldIn, vec3, caster, potency, MathHelper.secondsToTicks(duration));
            } else {
                WandUtil.spawnIceBouquet(worldIn, vec3, caster, potency, MathHelper.secondsToTicks(duration));
            }
        } else {
            WandUtil.spawn4x4IceBouquet(worldIn, vec3, caster, potency, MathHelper.secondsToTicks(duration));
        }
        SoundUtil.playNecromancerSummon(caster);
    }
}

public Component getAugmentingText(AffixInstance inst, AttributeTooltipContext ctx) {
    LootRarity rarity = inst.getRarity();
    MobEffectInstance effectInst = this.values.get(rarity).build(this.effect, inst.level());
    MutableComponent comp = this.target.toComponent(toComponent(effectInst, ctx.tickRate()));

    MobEffectInstance min = this.values.get(rarity).build(this.effect, 0);
    MobEffectInstance max = this.values.get(rarity).build(this.effect, 1);

    if (min.getAmplifier() != max.getAmplifier()) {
        // Vanilla ships potion.potency.0 as an empty string, so we have to fix that here
        Component minComp = min.getAmplifier() == 0 ? Component.literal("I") : Component.translatable("potion.potency." + min.getAmplifier());
        Component maxComp = Component.translatable("potion.potency." + max.getAmplifier());
        comp.append(valueBounds(minComp, maxComp));
    }

    if (!this.effect.value().isInstantenous() && min.getDuration() != max.getDuration()) {
        Component minComp = MobEffectUtil.formatDuration(min, 1, ctx.tickRate());
        Component maxComp = MobEffectUtil.formatDuration(max, 1, ctx.tickRate());
        comp.append(valueBounds(minComp, maxComp));
    }

    int cooldown = this.getCooldown(rarity);
    if (cooldown != 0) {
        Component cd = Component.translatable("affix.apotheosis.cooldown", StringUtil.formatTickDuration(cooldown, ctx.tickRate()));
        comp = comp.append(" ").append(cd);
    }
    if (this.stackOnReapply) {
        comp = comp.append(" ").append(Component.translatable("affix.apotheosis.stacking"));
    }

    return comp;
}

default Function2<ItemStack, Integer, Integer> getBeltColorFunction() {
	return (pearlBelt, tintIndex) -> {
		if (tintIndex == 0) return 0xFFFFFF;

		IItemHandler handler = getPearls(pearlBelt);
		if (handler == null) return 0;

		ItemStack stack = handler.getStackInSlot(tintIndex - 1);
		if (stack.isEmpty()) return 0xFFFFFF;

		if (!stack.hasTagCompound())
			return Color.HSBtoRGB(MathHelper.sin(Minecraft.getMinecraft().world.getTotalWorldTime() / 140f), 0.75f, 1f);

		long lastCast = NBTHelper.getLong(stack, NBTConstants.NBT.LAST_CAST, -1);
		int decayCooldown = NBTHelper.getInt(stack, NBTConstants.NBT.LAST_COOLDOWN, -1);
		long tick = Minecraft.getMinecraft().world.getTotalWorldTime();
		long timeSinceCooldown = tick - lastCast;
		float decayStage = (decayCooldown > 0) ? ((float) timeSinceCooldown) / decayCooldown : 1f;


		float rand = NBTHelper.getFloat(stack, NBTConstants.NBT.RAND, -1);
		float hue = rand < 0 ? (tick / 140f) % 140f : rand;
		float pow = Math.min(1f, Math.max(0f, getQuality(stack)));

		double decaySaturation = (lastCast == -1 || decayCooldown <= 0 || decayStage >= 1f) ? 1f :
				(decayStage < decayCurveDelimiter) ? Math.pow(Math.E, -15 * decayStage) : Math.pow(Math.E, 3 * decayStage - 3);

		float saturation = curveConst * (1 - (float) Math.pow(Math.E, -pow)) * (float) decaySaturation;

		return Color.HSBtoRGB(hue, saturation, 1f);
	};
}

public ActionResultType interactAt(PlayerEntity player, Vector3d vec, Hand hand) {
	if (isAlive() && (ownerUUID == null || player.getUUID().equals(ownerUUID))) {
		if (player instanceof ServerPlayerEntity) {
			if (winnerUUID != null && winnerUUID.equals(getUUID())) {

				for (ItemStack stack : LootUtil.generateLoot((ServerWorld)level,  new ResourceLocation(AdventOfAscension.MOD_ID, "misc/lotto_totem"), LootUtil.getGiftContext((ServerWorld)level, position(), 5, player))) {
					ItemEntity drop = spawnAtLocation(stack, 0);

					if (drop != null)
						drop.setOwner(player.getUUID());

					AdvancementUtil.completeAdvancement((ServerPlayerEntity)player, new ResourceLocation(AdventOfAscension.MOD_ID, "overworld/winner_winner"), "lotto_win");
				}

				ItemEntity drop = spawnAtLocation(new ItemStack(AoABlocks.LOTTO_BANNER.get()), 0);

				if (drop != null)
					drop.setOwner(player.getUUID());

				level.playSound(null, blockPosition(), AoASounds.LOTTO_WIN.get(), SoundCategory.PLAYERS, 1.0f, 1.0f);
			}

			for (LottoTotemEntity totem : level.getEntitiesOfClass(LottoTotemEntity.class, new AxisAlignedBB(blockPosition()).inflate(2d))) {
				totem.remove();
			}
		}

		return ActionResultType.SUCCESS;
	}

	return ActionResultType.PASS;
}

public void aiStep() {
	super.aiStep();

	if (!isAlive())
		return;

	if (invisCooldown > 0)
		--invisCooldown;

	if (cloneCooldown > 1)
		--cloneCooldown;

	if (!level.isClientSide) {
		if (invisCooldown == 0) {
			cloneCooldown = 60;
			invisCooldown = 240;

			EntityUtil.applyPotions(this, new EffectBuilder(Effects.INVISIBILITY, 60));
			playSound(AoASounds.ENTITY_TRICKSTER_HIDE.get(), 1.0f, 1.0f);
		}

		if (cloneCooldown == 1 && level.getEntitiesOfClass(TricksterCloneEntity.class, getBoundingBox().inflate(10)).size() < 5) {
			TricksterCloneEntity clone = new TricksterCloneEntity(AoAEntities.Mobs.TRICKSTER_CLONE.get(), level);

			clone.setPos(getX(), getY(), getZ());

			level.addFreshEntity(clone);
			clones.add(clone);
			cloneCooldown = 0;
		}
	}
}

public InteractionResult useOn(UseOnContext context)
{
	// the things in this method only care about it being used on a MRS, if thats not the case we ignore
	if (!(context.getLevel().getBlockEntity(context.getClickedPos()) instanceof TileMasterRitualStone)) {
		return InteractionResult.PASS;
	}

	ItemStack stack = context.getPlayer().getItemInHand(context.getHand());
	if (context.getPlayer().isShiftKeyDown())
	{
		if (context.getLevel().isClientSide)
		{
			trySetDisplayedRitual(stack, context.getLevel(), context.getClickedPos());
		}

		return InteractionResult.SUCCESS;
	} else if (addRuneToRitual(stack, context.getLevel(), context.getClickedPos(), context.getPlayer()))
	{
		setStoredPos(stack, context.getClickedPos());
		setActivatedState(stack, true);

		if (context.getLevel().isClientSide)
		{
			spawnParticles(context.getLevel(), context.getClickedPos().relative(context.getClickedFace()), 15);
		}

		return InteractionResult.SUCCESS;
		// TODO: Have the diviner automagically build the ritual
	}

	return InteractionResult.PASS;
}

public void castSpell(Entity entity) {
    if (entity == null)
        return;
    if (!this.isCharged || spell.isEmpty() || !(level instanceof ServerLevel serverLevel) || !(spell.get(0) instanceof MethodTouch))
        return;
    if (!this.isTemporary && this.disabled) return;
    try {
        Player playerEntity = uuid != null ? FakePlayerFactory.get(serverLevel, new GameProfile(uuid, "")) : ANFakePlayer.getPlayer(serverLevel);
        if (this.isSensitive) {
            Player onlinePlayer = serverLevel.getServer().getPlayerList().getPlayer(uuid);
            if (onlinePlayer != null) {
                playerEntity = onlinePlayer;
            }
        }
        EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(entity.level, spell, playerEntity, new RuneCaster(this, SpellContext.CasterType.RUNE)));
        resolver.onCastOnEntity(ItemStack.EMPTY, entity, InteractionHand.MAIN_HAND);

        if (this.isTemporary) {
            level.destroyBlock(worldPosition, false);
            return;
        }
        this.isCharged = false;

        level.setBlockAndUpdate(worldPosition, level.getBlockState(worldPosition).cycle(RuneBlock.POWERED));
        ticksUntilCharge = 20 * 2;
        updateBlock();
    } catch (Exception e) {
        PortUtil.sendMessage(entity, Component.translatable("ars_nouveau.rune.error"));
        e.printStackTrace();
        level.destroyBlock(worldPosition, false);
    }
}

protected InteractionResult mobInteract(Player playerIn, InteractionHand hand) {
    if (this.getOwner() == null)
        this.setFamiliarOwner(playerIn);

    if (hand != InteractionHand.MAIN_HAND)
        return InteractionResult.PASS;

    ItemStack stack = playerIn.getItemInHand(hand);
    if (stack.getItem() instanceof FamiliarCurio) {
        return stack.interactLivingEntity(playerIn, this, hand);
    } else if (stack.getItem() == OccultismItems.DEBUG_WAND.get()) {
        if (playerIn.isShiftKeyDown() && !this.level().isClientSide()) {
            if (this.hasBlacksmithUpgrade()) {
                if (this.hasIesniumUpgrade()) {
                    this.setBlacksmithUpgrade(false);
                    this.setIesniumUpgrade(false);
                } else {
                    this.iesniumUpgrade();
                }
            } else {
                this.blacksmithUpgrade();
            }
        } else {
            this.setFamiliarOwner(playerIn);
        }
        return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
    } else if (stack.isEmpty() && !this.level().isClientSide() && this.getFamiliarOwner() == playerIn) {
        this.setSitting(!this.isSitting());
        return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
    }
    return InteractionResult.PASS;
}

public boolean hurt(DamageSource source, float damage) {
    Entity entity = source.getDirectEntity();
    if (!this.level().isClientSide) {
        if(this.getIsAnger()) {
            if (entity instanceof LivingEntity) {
                // Shield disabling on critical axe hit
                if (((LivingEntity) entity).getMainHandItem().getItem() instanceof AxeItem) {
                    double itemDamage = ((AxeItem) ((LivingEntity) entity).getMainHandItem().getItem()).getAttackDamage()+ 1;
                    if (damage >= itemDamage + (itemDamage / 2)) {
                        if (this.getShieldDurability() < 4) {
                            this.playSound(SoundEvents.WITHER_BREAK_BLOCK, 1.0F, 1.5F);

                            this.setShieldDurability(this.getShieldDurability() + 1);
                            return false;
                        }
                    }
                }
            }
        }
    }
    if (damage > 0.0F && canBlockDamageSource(source)) {
        this.hurtCurrentlyUsedShield(damage);
        if (!source.is(DamageTypeTags.IS_PROJECTILE)) {
            if (entity instanceof LivingEntity) {
                this.blockUsingShield((LivingEntity) entity);
            }
        }
        this.playSound(SoundEvents.ANVIL_PLACE, 0.3F, 0.5F);
        return false;
    }
    return super.hurt(source, damage);
}

public void tick() {
	super.tick();
	if (!this.level().isClientSide()) {
		if (this.horizontalCollision) {
			if (this.horizontalCollision) {
				Boolean logBlock;
				BlockPos blockpos1 = new BlockPos(this.blockPosition().getX() + 1, this.blockPosition().getY() + 1, this.blockPosition().getZ());
				BlockPos blockpos2 = new BlockPos(this.blockPosition().getX() - 1, this.blockPosition().getY() + 1, this.blockPosition().getZ());
				BlockPos blockpos3 = new BlockPos(this.blockPosition().getX(), this.blockPosition().getY() + 1, this.blockPosition().getZ() + 1);
				BlockPos blockpos4 = new BlockPos(this.blockPosition().getX(), this.blockPosition().getY() + 1, this.blockPosition().getZ() - 1);
				BlockState blockstate1 = this.level().getBlockState(blockpos1);
				BlockState blockstate2 = this.level().getBlockState(blockpos2);
				BlockState blockstate3 = this.level().getBlockState(blockpos3);
				BlockState blockstate4 = this.level().getBlockState(blockpos4);
				if (blockstate1.is(BlockTags.LOGS) || blockstate1.is(BlockTags.PLANKS) || blockstate1.is(BlockTags.WOODEN_DOORS) || blockstate1.is(BlockTags.WOODEN_FENCES) || blockstate1.is(BlockTags.WOODEN_SLABS) || blockstate1.is(BlockTags.WOODEN_STAIRS) || blockstate2.is(BlockTags.LOGS) || blockstate2.is(BlockTags.PLANKS) || blockstate2.is(BlockTags.WOODEN_DOORS) || blockstate2.is(BlockTags.WOODEN_FENCES) || blockstate2.is(BlockTags.WOODEN_SLABS) || blockstate2.is(BlockTags.WOODEN_STAIRS)  || blockstate3.is(BlockTags.LOGS) || blockstate3.is(BlockTags.PLANKS) || blockstate3.is(BlockTags.WOODEN_DOORS) || blockstate3.is(BlockTags.WOODEN_FENCES) || blockstate3.is(BlockTags.WOODEN_SLABS) || blockstate3.is(BlockTags.WOODEN_STAIRS) || blockstate4.is(BlockTags.LOGS) || blockstate4.is(BlockTags.PLANKS) || blockstate4.is(BlockTags.WOODEN_DOORS) || blockstate4.is(BlockTags.WOODEN_FENCES) || blockstate4.is(BlockTags.WOODEN_SLABS) || blockstate4.is(BlockTags.WOODEN_STAIRS)) {
					logBlock = true;
					if (climbingTickCooldown == 0 && climbingTicks < 600) {
						this.setBesideClimbableBlock(logBlock);
						climbingTicks++;
					}
					if (climbingTicks >= 599 && climbingTickCooldown <= 300) {
						climbingTickCooldown++;
					}
					if (climbingTickCooldown == 300) {
						climbingTicks = 0;
						climbingTickCooldown = 0;
					}
				}
			}
		}
	}
}

public void readAdditionalSaveData(CompoundTag compound) {
	super.readAdditionalSaveData(compound);

	this.setAttachedHiveSide(Direction.from3DDataValue(compound.getByte("AttachedHiveSide")));
	this.setFromBottle(compound.getBoolean("FromBottle"));

	this.teleportCooldown = compound.getInt("TeleportCooldown");
	this.ticksAwayFromHive = compound.getInt("TicksAwayFromHive");

	if (compound.contains("IsInflated")) {
		this.setInflated(compound.getBoolean("IsInflated"));
	}

	if (compound.contains("HivePos", 10)) {
		this.setHivePos(NbtUtils.readBlockPos(compound.getCompound("HivePos")));
	}

	if (compound.contains("StuckInBlockState", 10)) {
		this.stuckInBlockState = NbtUtils.readBlockState(this.level().holderLookup(Registries.BLOCK), compound.getCompound("StuckInBlockState"));
	}

	CompoundTag stackToCreate = compound.getCompound("ItemStackToCreate");

	if (stackToCreate != null) {
		ItemStack newStackToCreate = ItemStack.of(stackToCreate);
		if (!newStackToCreate.isEmpty()) {
			this.setStackToCreate(newStackToCreate);
		}
	}

	this.rotationController = this.getRotationController().read(this, compound.getCompound("Orientation"));
}

public void tick() {
	if (this.jumpCooldown > 0)
		--this.jumpCooldown;

	if (this.jumping && this.deer.onGround()) {
		this.deer.spawnFlower();
		this.jumpCooldown = Math.max(this.adjustedTickDelay(2), this.jumpCooldown);
		this.jumping = false;
	} else if (this.deer.getNavigation().isDone()) {
		if (this.frolicCooldown > 0) {
			--this.frolicCooldown;
		} else if (this.deer.isSpreadingFlowers()) {
			Vec3 vec3 = DefaultRandomPos.getPos(this.deer, 15, 7);
			if (vec3 != null) {
				this.deer.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 1.6D);
				if (this.deer.getRandom().nextInt(8) == 0)
					this.frolicCooldown = this.adjustedTickDelay(20 + this.deer.getRandom().nextInt(20));
			}
		}
	} else if (this.jumpCooldown <= 0 && this.deer.onGround()) {
		Path path = this.deer.getNavigation().getPath();
		Vec3 vec3 = path.getNextEntityPos(this.deer);
		Vec3 vec31 = vec3.subtract(this.deer.position());
		Vec3 vec32 = vec31.normalize();

		this.deer.level().broadcastEntityEvent(this.deer, (byte) 4);
		this.deer.setJumping(true);
		this.deer.setDeltaMovement(this.deer.getDeltaMovement().add(vec32.x * 0.32D, 0.5D, vec32.z * 0.32D));
		this.resetJumpCooldown();
		this.jumping = true;
	}
}

public boolean canUse() {
    LivingEntity target = mob.getTarget();
    if ((target == null || !target.isAlive()) && mob.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
        if (executionCooldown-- > 0) {
            return false;
        } else {
            executionCooldown = 150 + mob.getRandom().nextInt(100);
            BlockPos pos = null;
            if (mob.getLastAltarPos() != null) {
                if (mob.level().getBlockEntity(mob.getLastAltarPos()) instanceof AbyssalAltarBlockEntity altar) {
                    executionCooldown = 10;
                    if (altar.getItem(0).is(ACTagRegistry.DEEP_ONE_BARTERS)) {
                        pos = mob.getLastAltarPos();
                    }
                } else {
                    mob.setLastAltarPos(null);
                }
            }
            if (pos == null) {
                List<BlockPos> list = getNearbyAltars(mob.blockPosition(), (ServerLevel) mob.level(), 64).sorted(Comparator.comparingDouble(mob.blockPosition()::distSqr)).toList();
                if (!list.isEmpty()) {
                    pos = list.get(0);
                }
            }
            if (pos != null) {
                altarPos = pos;
                mob.setLastAltarPos(altarPos);
                return true;
            }
        }
    }
    return false;
}

public void tick() {
    if(cod.circleTime > cod.maxCircleTime){
        cod.circleTime = 0;
        cod.circlePos = null;
    }
    if(cod.circlePos != null && cod.circleTime <= cod.maxCircleTime){
        cod.circleTime++;
        Vec3 movePos = getSharkCirclePos(cod.circlePos);
        cod.getMoveControl().setWantedPosition(movePos.x(), movePos.y(), movePos.z(), 1.0F);
    }else if (this.cod.isGroupLeader()) {
        if (cod.baitballCooldown == 0) {
            cod.resetBaitballCooldown();
            if (cod.circlePos == null || cod.circleTime >= cod.maxCircleTime) {
                cod.circleTime = 0;
                cod.maxCircleTime = 360 + this.cod.random.nextInt(80);
                circleDistance = 1 + this.cod.random.nextFloat();
                clockwise = this.cod.random.nextBoolean();
                cod.circlePos = cod.blockPosition().above();
            }
        }
    } else if (cod.random.nextInt(40) == 0 || cod.hasNoLeader()) {
        final Vec3 movepos = cod.position().add(cod.random.nextInt(4) - 2, cod.getY() < 0 ? 1 : cod.random.nextInt(4) - 2, cod.random.nextInt(4) - 2);
        cod.getMoveControl().setWantedPosition(movepos.x, movepos.y, movepos.z, 1.0F);
    } else if (cod.hasGroupLeader() && cod.groupLeader.circlePos != null) {
        if (cod.circlePos == null) {
            cod.circlePos = cod.groupLeader.circlePos;
            cod.circleTime = cod.groupLeader.circleTime;
            cod.maxCircleTime = cod.groupLeader.maxCircleTime;
            circleDistance = 1 + this.cod.random.nextFloat();
            clockwise = this.cod.random.nextBoolean();
        }
    }
}

public void tick() {
    super.tick();
    if(jumpCooldown > 0){
        jumpCooldown--;
    }
    refreshDimensions();
    onUpdateParts();
    if (this.isInWater()) {
        spawnParticlesAroundEntity(ParticleTypes.BUBBLE, this, (int) this.getSeaSerpentScale());

    }
    if (!this.level.isClientSide && this.level.getDifficulty() == Difficulty.PEACEFUL) {
        this.remove(RemovalReason.DISCARDED);
    }
    if (this.getTarget() != null && !this.getTarget().isAlive()) {
        this.setTarget(null);
    }
    for (int i = 0; i < tailYaw.length; i++) {
        prevTailYaw[i] = tailYaw[i];
    }
    for (int i = 0; i < tailPitch.length; i++) {
        prevTailPitch[i] = tailPitch[i];
    }
    this.tailYaw[0] = this.yBodyRot;
    this.tailPitch[0] = this.getXRot();
    for (int i = 1; i < tailYaw.length; i++) {
        tailYaw[i] = prevTailYaw[i - 1];
    }
    for (int i = 1; i < tailPitch.length; i++) {
        tailPitch[i] = prevTailPitch[i - 1];
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void updateTask() {
	if(this.spawnCooldown <= 0) {
		this.spawnCooldown = (int)((180 + this.entity.rand.nextInt(100)) / this.entity.getWispStrengthModifier());
		List<BlockPos> blocks = this.entity.findSmallFacesBlocks();

		if(!blocks.isEmpty()) {
			EntitySpiritTreeFaceSmall face = new EntitySpiritTreeFaceSmall(this.entity.world);

			spawnLoop: for(int i = 0; i < 16; i++) {
				BlockPos anchor = blocks.get(this.entity.rand.nextInt(blocks.size()));

				List<EnumFacing> facings = new ArrayList<>();
				facings.addAll(Arrays.asList(EnumFacing.VALUES));
				Collections.shuffle(facings, this.entity.rand);

				for(EnumFacing facing : facings) {
					EnumFacing facingUp = facing.getAxis().isVertical() ? EnumFacing.HORIZONTALS[this.entity.rand.nextInt(EnumFacing.HORIZONTALS.length)] : EnumFacing.UP;
					if(face.checkAnchorAt(anchor, facing, facingUp, AnchorChecks.ALL) == 0) {
						face.onInitialSpawn(this.entity.world.getDifficultyForLocation(anchor), null);
						face.setPositionToAnchor(anchor, facing, facingUp);
						this.entity.world.spawnEntity(face);
						break spawnLoop;
					}
				}
			}

			if(this.hasEnoughSmallFaces()) {
				this.shouldContinue = false;
			}
		}
	}
	this.spawnCooldown--;
}

public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase user, int timeLeft){

	if(user instanceof EntityPlayer){

		EntityPlayer player = (EntityPlayer)user;

		Spell spell = WandHelper.getCurrentSpell(stack);

		SpellModifiers modifiers;

		if(WizardData.get(player) != null){
			modifiers = WizardData.get(player).itemCastingModifiers;
		}else{
			modifiers = this.calculateModifiers(stack, (EntityPlayer)user, spell); // Fallback to the old way, should never be used
		}

		int castingTick = stack.getMaxItemUseDuration() - timeLeft; // Might as well include this

		int cost = getDistributedCost((int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f), castingTick);

		// Still need to check there's enough mana or the spell will finish twice, since running out of mana is
		// handled separately.
		if(spell.isContinuous && spell.getTier().level <= this.tier.level && cost <= this.getMana(stack)){

			MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Finish(Source.WAND, spell, player, modifiers, castingTick));
			spell.finishCasting(world, player, Double.NaN, Double.NaN, Double.NaN, null, castingTick, modifiers);

			if(!player.isCreative()){ // Spells only have a cooldown in survival
				WandHelper.setCurrentCooldown(stack, (int)(spell.getCooldown() * modifiers.get(WizardryItems.cooldown_upgrade)));
			}
		}
	}
}

