public boolean mineBlock(ItemStack itemStack, Level world, BlockState state, BlockPos pos, LivingEntity entity) {
    if (state.getDestroySpeed(world, pos) > 0) {
        applyDamage(blockDestroyDamage, itemStack, entity);

        if (!isBroken(itemStack)) {
            applyUsageEffects(entity, itemStack, 1);
        }
    }

    applyBlockBreakEffects(itemStack, world, state, pos, entity);

    if (!world.isClientSide && !isBroken(itemStack)) {
        // todo (destabilization): apply chaotic effect here
        if (getEffectLevel(itemStack, ItemEffect.piercingHarvest) > 0) {
            PiercingEffect.pierceBlocks(this, itemStack, getEffectLevel(itemStack, ItemEffect.piercing), (ServerLevel) world, state, pos, entity);
        }

        int extractorLevel = getEffectLevel(itemStack, ItemEffect.extraction);
        if (extractorLevel > 0) {
            ExtractionEffect.breakBlocks(this, itemStack, extractorLevel, (ServerLevel) world, state, pos, entity);
        }

        int unboundExtractionLevel = getEffectLevel(itemStack, ItemEffect.unboundExtraction);
        if (unboundExtractionLevel > 0) {
            UnboundExtractionEffect.breakBlocks(this, itemStack, unboundExtractionLevel, (ServerLevel) world, state, pos, entity);
        }

        CritEffect.onBlockBreak(entity);
        DataEffectsHandler.applyMineBlockEffects(itemStack, entity, pos);
    }

    return true;
}

public boolean hurtEnemy(ItemStack itemStack, LivingEntity target, LivingEntity attacker) {
    applyDamage(entityHitDamage, itemStack, attacker);

    if (!isBroken(itemStack)) {
        float attackStrength = CastOptional.cast(attacker, Player.class)
                .map(EffectHelper::getCooledAttackStrength)
                .orElse(1f);

        if (attackStrength > 0.9) {
            int sweepingLevel = SweepingEffect.getSweepingLevel(itemStack);
            if (sweepingLevel > 0 && attacker.onGround() && !EffectHelper.getSprinting(attacker)) {
                SweepingEffect.sweepAttack(itemStack, target, attacker, sweepingLevel);
            }

            int howlingLevel = EffectHelper.getEffectLevel(itemStack, ItemEffect.howling);
            if (howlingLevel > 0) {
                HowlingEffect.trigger(itemStack, attacker, howlingLevel);
            }

            ItemEffectHandler.applyHitEffects(itemStack, target, attacker);
            applyPositiveUsageEffects(attacker, itemStack, 1);
        }

        int skulkTaintLevel = getEffectLevel(itemStack, ItemEffect.sculkTaint);
        if (skulkTaintLevel > 0) {
            SculkTaintEffect.perform((ServerLevel) target.level(), target.blockPosition(), skulkTaintLevel, getEffectEfficiency(itemStack, ItemEffect.sculkTaint));
        }

        applyNegativeUsageEffects(attacker, itemStack, 1);
    }

    return true;
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    if (itemstack.getItem() == this){
        if (hasSummon(itemstack)){
            LivingEntity summon = getSummon(itemstack);
            if (itemstack.getTag() != null) {
                if (summon instanceof IOwned owned) {
                    if (!level.isClientSide) {
                        if (owned.getTrueOwner() == player) {
                            if (player.isShiftKeyDown() || player.isCrouching()){
                                itemstack.getTag().remove(TAG_ENTITY);
                                return InteractionResultHolder.success(itemstack);
                            }
                        } else if (RitualRequirements.canSummon(level, player, summon.getType())){
                            owned.setTrueOwner(player);
                            if (summon instanceof RaiderServant servant && servant.isLeader()) {
                                ItemStack newBanner = servant.getLeaderBannerWithNameInstance();
                                if (!newBanner.isEmpty()) {
                                    servant.setItemSlot(EquipmentSlot.HEAD, newBanner);
                                }
                            }
                            player.playSound(SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, 1.0F, 1.0F);
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, 1.0F, 1.0F));
                            itemstack.shrink(1);
                            return InteractionResultHolder.success(itemstack);
                        }
                    }
                }
            }
        }
    }
    return InteractionResultHolder.pass(itemstack);
}

public boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos){
    if (!level.isClientSide) {
        if (level.getBlockState(blockPos).is(ModBlocks.SKULL_PILE.get())) {
            if (checkBlocks(level, blockPos)) {
                if (SEHelper.hasResearch(player, ResearchList.WARRED) && SEHelper.hasResearch(player, ResearchList.HAUNTING)) {
                    if (conditionsMet(level, player)) {
                        GraveGolem graveGolem = ModEntityType.GRAVE_GOLEM.get().create(level);
                        if (graveGolem != null) {
                            graveGolem.setTrueOwner(player);
                            graveGolem.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(graveGolem.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                            graveGolem.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                            if (level.addFreshEntity(graveGolem)) {
                                removeBlocks(level, blockPos);
                                stack.shrink(1);
                                if (player instanceof ServerPlayer serverPlayer) {
                                    CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, graveGolem);
                                }
                                return true;
                            }
                        }
                    } else {
                        player.displayClientMessage(Component.translatable("info.goety.summon.limit"), true);
                    }
                } else {
                    player.displayClientMessage(Component.translatable("info.goety.research.fail"), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.block.fail"), true);
            }
        }
    }
    return false;
}

