            MobUtil.moveDownToGround(summonedentity);
            summonedentity.setPersistenceRequired();
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.SUMMON_SPELL.get());
    }
}

private void applyRegen(Player player, int max, ItemStack cadStack) {
	RegenPsiEvent event = new RegenPsiEvent(player, this, cadStack);

	if(!PsiEvents.post(event).isCanceled()) {
		if(!cadStack.isEmpty()) {
			ICAD cad = (ICAD) cadStack.getItem();
			cad.regenPsi(cadStack, event.getCadRegen());
		}

		boolean anyChange = availablePsi != max && event.getPlayerRegen() > 0;

		int prevPsi = availablePsi;
		availablePsi = Math.min(max, availablePsi + event.getPlayerRegen());

		if(overflowed && event.willHealOverflow()) {
			anyChange = true;
			overflowed = false;
		}

		if(regenCooldown != event.getRegenCooldown()) {
			anyChange = true;
		}
		regenCooldown = event.getRegenCooldown();

		if(anyChange) {
			if(player instanceof ServerPlayer) {
				PsiPlayerDataSync.sendDeduction((ServerPlayer) player, prevPsi, availablePsi, regenCooldown, false);
			}

			save();
		}
	}
}

public static void handleOminousEntities(EntityJoinLevelEvent event) {
    if (!(event.getLevel() instanceof ServerLevel serverLevel) || event.loadedFromDisk()) {
        return;
    }
    var entity = event.getEntity();
    if (entity instanceof IOminousEntity ominousSettings && !ominousSettings.isOminous() && ominousSettings.canTriggerOminous()) {
        float rangeSqr = ominousSettings.ominousTriggerRange();
        rangeSqr *= rangeSqr;
        Vec3 center = entity.position();
        List<Player> ominousPlayers = new ArrayList<>();
        for (Player player : serverLevel.players()) {
            if (player.isCreative() || player.isSpectator() || player.distanceToSqr(center) > rangeSqr) {
                continue;
            }
            if (player.hasEffect(MobEffects.TRIAL_OMEN)) {
                ominousPlayers.add(player);
            } else if (player.hasEffect(MobEffects.BAD_OMEN)) {
                ominousPlayers.add(player);
                MobEffectInstance mobeffectinstance = player.getEffect(MobEffects.BAD_OMEN);
                int i = mobeffectinstance.getAmplifier() + 1;
                int j = 18000 * i;
                player.removeEffect(MobEffects.BAD_OMEN);
                player.addEffect(new MobEffectInstance(MobEffects.TRIAL_OMEN, j, 0));
                MagicManager.spawnParticles(serverLevel, ParticleTypes.SOUL_FIRE_FLAME, player.getX(), player.getY(0.5), player.getZ(), 25, 0.1, 0.2, 0.1, 0.2, false);
                MagicManager.spawnParticles(serverLevel, ParticleTypes.TRIAL_OMEN, player.getX(), player.getY(0.5), player.getZ(), 25, 0.1, 0.2, 0.1, 0.2, false);
            }
        }
        if (!ominousPlayers.isEmpty()) {
            ominousSettings.onOminousTrigger();
            serverLevel.playSound(null, BlockPos.containing(center), SoundEvents.TRIAL_SPAWNER_OMINOUS_ACTIVATE, SoundSource.BLOCKS, 4, 1.0F);
        }
    }
}

protected void dropFromLootTable(ServerLevel level, @NotNull DamageSource pDamageSource, boolean pAttackedRecently) {
    super.dropFromLootTable(level, pDamageSource, pAttackedRecently);

    var owner = this.getOwner();

    var shard = new ItemStack(OccultismItems.SOUL_SHARD_ITEM.get());

    var health = this.getHealth();
    this.setHealth(this.getMaxHealth()); //simulate a healthy familiar to avoid death on respawn
    this.resetFallDistance();
    this.removeAllEffects();

    var entityData = new CompoundTag();
    var id = this.getEncodeId();
    if (id != null)
        entityData.putString("id", id);
    var output = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, this.registryAccess());
    this.saveWithoutId(output);
    entityData.merge(output.buildResult());

    shard.set(DataComponents.ENTITY_DATA, TypedEntityData.of(this.getType(), entityData));
    this.setHealth(health);

    if (owner instanceof Player player) {
        ItemTransferUtil.giveItemToPlayer(player, shard);
    } else {
        ItemEntity entityItem = new ItemEntity(this.level(), this.getX(), this.getY() + 0.5, this.getZ(), shard);
        entityItem.setPickUpDelay(5);
        entityItem.setDeltaMovement(entityItem.getDeltaMovement().multiply(0, 1, 0));

        this.level().addFreshEntity(entityItem);
    }
}

public void tick() {
    LivingEntity target = Ignis_Entity.this.getTarget();
    if(target !=null){
        boolean flag = Ignis_Entity.this.getAnimationTick() < look1 || Ignis_Entity.this.getAnimationTick() > look2 ;
        if(flag){
            entity.getLookControl().setLookAt(target,  30.0F, 30.0F);
            entity.lookAt(target, 30.0F, 30.0F);
        }else{
            entity.getLookControl().setLookAt(target,0F, 30.0F);
            entity.setYRot(entity.yRotO);
        }

    }else{
        entity.setYRot(entity.yRotO);
    }


    if (Ignis_Entity.this.getAnimationTick() == charge) {
        float f1 = (float) Math.cos(Math.toRadians(Ignis_Entity.this.getYRot() + 90));
        float f2 = (float) Math.sin(Math.toRadians(Ignis_Entity.this.getYRot() + 90));
        if (target != null) {
