public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof Player player) {
		if (player.getAirSupply() < 300) {
			player.setAirSupply(300);
		}

		if (player.isOnFire()) {
			player.clearFire();
		}

		AttributeMap map = player.getAttributes();
		map.addTransientAttributeModifiers(this.getCurrentModifiers(player));

		if (context.entity() instanceof ServerPlayer) {
			if (!this.locationCache.containsKey(player)) {
				this.generateCachedLocation((ServerPlayer) player);
			} else {
				Future<CachedTeleportationLocation> future = this.locationCache.get(player);

				if (future.isDone() && !future.isCancelled()) {
					try {
						CachedTeleportationLocation location = future.get();

						if (location.dimension() == player.level().dimension()) {
							this.generateCachedLocation((ServerPlayer) player);
						}
					} catch (Exception ex) {
						throw new RuntimeException(ex);
					}
				}
			}
		}
	}
}

public void tick() {
    super.tick();
    prevExplodeProgress = explodeProgress;
    if (this.level().isClientSide) {
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
        } else {
            this.reapplyPosition();
        }
    } else {
        this.reapplyPosition();
        this.setRot(this.getYRot(), this.getXRot());
    }
    if(this.isExplosive() && this.getBounces() >= this.getMaximumBounces()){
        if(explodeProgress > 20.0F){
            if(!level().isClientSide){
                this.level().explode(this.getOwner(), this.getX(), this.getY() + 0.5F, this.getZ(), (float)2.0, false, Level.ExplosionInteraction.NONE);
                this.discard();
            }
        }else{
            explodeProgress++;
        }
        this.level().addParticle(ParticleTypes.SMOKE, this.getX(), this.getY() + 0.4F, this.getZ(), 0, 0.1F, 0);
    }
    if(bounceSoundCooldown > 0){
        bounceSoundCooldown--;
    }
}

