public void tick() {
    super.tick();
    if (!this.level().isClientSide) {
        if (this.getLastHurtByMob() == null && this.getTarget() == null) {
            if (this.getDeltaMovement().lengthSqr() < 0.03D && this.getRandom().nextInt(190) == 0 && this.getAnimation() == NO_ANIMATION) {
                if (getRandom().nextInt(3) == 0) {
                    this.setAnimation(ANIMATION_PUZZLED);
                } else if (this.onGround()) {
                    this.setAnimation(ANIMATION_PECK_GROUND);
                }
            }
        }
        if (revengeCooldown > 0) {
            revengeCooldown--;
        }
        if (revengeCooldown <= 0 && this.getLastHurtByMob() != null && !emuAttackedDirectly) {
            this.setLastHurtByMob(null);
            revengeCooldown = 0;
        }
        LivingEntity target = getTarget();
        if (this.isAlive() && target != null && this.getAnimation() == ANIMATION_SCRATCH && this.distanceTo(target) < 4F && (this.getAnimationTick() == 8 || this.getAnimationTick() == 15)) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
            target.knockback(0.4F, target.getX() - this.getX(), target.getZ() - this.getZ());
            target.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
    }
    if (!this.level().isClientSide && this.isAlive() && !this.isBaby() && --this.timeUntilNextEgg <= 0) {
        this.playSound(SoundEvents.CHICKEN_EGG, 1.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
        this.spawnAtLocation(AMItemRegistry.EMU_EGG.get());
        this.timeUntilNextEgg = this.random.nextInt(6000) + 6000;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    Item item = itemstack.getItem();
    if (item == Items.SADDLE && !this.isSaddled() && !this.isBaby()) {
        if (!player.isCreative()) {
            itemstack.shrink(1);
        }
        this.setSaddled(true);
        return InteractionResult.SUCCESS;
    }
    if (item == AMItemRegistry.PIGSHOES.get() && this.getShoeStack().isEmpty() && !this.isBaby()) {
        this.setShoeStack(itemstack.copy());
        if (!player.isCreative()) {
            itemstack.shrink(1);
        }
        return InteractionResult.SUCCESS;
    }
    if (isMushroom(itemstack) && (this.getPassiveTicks() <= 0 || this.getHealth() < this.getMaxHealth())) {
        if (!player.isCreative()) {
            itemstack.shrink(1);
        }
        this.heal(6);
        this.setPassiveTicks(this.getPassiveTicks() + 1200);
        return InteractionResult.SUCCESS;
    }
    InteractionResult type = super.mobInteract(player, hand);
    if (type != InteractionResult.SUCCESS && !isFood(itemstack)) {
        if (!player.isShiftKeyDown() && !this.isBaby() && this.isSaddled() && this.getAnimation() != ANIMATION_BUCK) {
            player.startRiding(this);
            return InteractionResult.SUCCESS;
        }
    }
    return type;
}

private void eatHive() {
    if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(bear.level(), bear)) {
        BlockState blockstate = bear.level().getBlockState(this.blockPos);
        if (blockstate.is(AMTagRegistry.GRIZZLY_BEEHIVE)) {
            if (bear.level().getBlockEntity(this.blockPos) instanceof BeehiveBlockEntity) {
                final RandomSource rand = this.bear.getRandom();
                BeehiveBlockEntity beehivetileentity = (BeehiveBlockEntity) bear.level().getBlockEntity(this.blockPos);
                beehivetileentity.emptyAllLivingFromHive(null, blockstate, BeehiveBlockEntity.BeeReleaseStatus.EMERGENCY);
                bear.level().updateNeighbourForOutputSignal(this.blockPos, blockstate.getBlock());
                ItemStack stack = new ItemStack(Items.HONEYCOMB);
                int level = 0;
                if (blockstate.getBlock() instanceof BeehiveBlock) {
                    level = blockstate.getValue(BeehiveBlock.HONEY_LEVEL);
                }
                for (int i = 0; i < level; i++) {
                    ItemEntity itementity = new ItemEntity(bear.level(), blockPos.getX() + rand.nextFloat(), blockPos.getY() + rand.nextFloat(), blockPos.getZ() + rand.nextFloat(), stack);
                    itementity.setDefaultPickUpDelay();
                    bear.level().addFreshEntity(itementity);
                }
                bear.level().destroyBlock(blockPos, false);
                if (blockstate.getBlock() instanceof BeehiveBlock) {
                    bear.level().setBlockAndUpdate(blockPos, blockstate.setValue(BeehiveBlock.HONEY_LEVEL, 0));
                }
                double d0 = 15;
                for (Bee bee : bear.level().getEntitiesOfClass(Bee.class, new AABB((double) blockPos.getX() - d0, (double) blockPos.getY() - d0, (double) blockPos.getZ() - d0, (double) blockPos.getX() + d0, (double) blockPos.getY() + d0, (double) blockPos.getZ() + d0))) {
                    bee.setRemainingPersistentAngerTime(100);
                    bee.setTarget(bear);
                    bee.setStayOutOfHiveCountdown(400);
                }
                stop();
            }
        }
    }
}

