public void updateTask() {
	if(this.findBlocksCooldown <= 0 && (this.trackingBlocks == null || this.trackingBlocks.isEmpty())) {
		this.findBlocksCooldown = 40 + this.entity.getRNG().nextInt(60);
		this.trackingBlocks = this.entity.findNearbyBlocksForMovement();
	}

	if(this.trackingBlocks != null && !this.trackingBlocks.isEmpty() && this.checkCooldown <= 0) {
		this.checkCooldown = 5 + this.entity.getRNG().nextInt(15);

		for(int i = 0; i < 16; i++) {
			if(this.trackingBlocks.isEmpty()) {
				break;
			}

			BlockPos pos = this.trackingBlocks.remove(this.entity.getRNG().nextInt(this.trackingBlocks.size()));

			if(this.entity.getDistanceSqToCenter(pos) <= this.rangeSq && this.entity.isWithinHomeDistanceFromPosition(pos)) {
				Vec3d center = new Vec3d(pos.getX() + this.entity.getBlockWidth() / 2.0D, pos.getY() + this.entity.getBlockHeight() / 2.0D, pos.getZ() + this.entity.getBlockWidth() / 2.0D);
				double dx = this.entity.getRNG().nextDouble() - 0.5D;
				double dy = this.entity.getRNG().nextDouble() - 0.5D;
				double dz = this.entity.getRNG().nextDouble() - 0.5D;
				if(this.entity.checkAnchorAt(center, new Vec3d(dx, dy, dz), AnchorChecks.ALL) == 0) {
					this.entity.getMoveHelper().setMoveTo(center.x, center.y, center.z, this.speed);
					this.entity.getLookHelper().setLookDirection(dx, dy, dz);
					this.wandered = true;
					return;
				}
			}
		}
	}

	this.checkCooldown--;
	this.findBlocksCooldown--;
}

protected void onImpact(RayTraceResult result) {
	if (result.typeOfHit != null) {
		if (this.world.isRemote) {
			double particleX = MathHelper.floor(this.posX) + this.rand.nextFloat();
			double particleY = MathHelper.floor(this.posY) + this.rand.nextFloat();
			double particleZ = MathHelper.floor(this.posZ) + this.rand.nextFloat();
			for (int count = 0; count < 10; count++) {
				world.spawnParticle(EnumParticleTypes.SLIME, particleX, particleY, particleZ, 0, 0, 0);
			}
		} else {
			if (result.typeOfHit == RayTraceResult.Type.BLOCK) {
				EnumFacing facing = result.sideHit;
				BlockPos pos = result.getBlockPos();
				pos = pos.offset(facing);
				IBlockState state = this.world.getBlockState(pos);

				if (state.getBlock().isReplaceable(this.world, pos) && BlockRegistry.GLOWING_GOOP.canPlaceBlockAt(this.world, pos)){
					if(state.getMaterial() == Material.WATER) {
						world.setBlockState(pos, BlockRegistry.GLOWING_GOOP_UNDERWATER.getDefaultState().withProperty(BlockGlowingGoop.FACING, facing));
					} else {
						world.setBlockState(pos, BlockRegistry.GLOWING_GOOP.getDefaultState().withProperty(BlockGlowingGoop.FACING, facing));
					}

					world.playSound(null, pos, SoundEvents.ENTITY_SLIME_SQUISH, SoundCategory.NEUTRAL, 1F, 1F);	
				}
				else {
					InventoryHelper.spawnItemStack(world, posX, posY, posZ, new ItemStack(BlockRegistry.GLOWING_GOOP));
				}

				setDead();
			}
		}
	}
}

public void onUpdateFlying() {
    if (this.action == EntityMoveHelper.Action.MOVE_TO) {
        double xDistance = this.posX - this.entityCreature.posX;
        double yDistance = this.posY - this.entityCreature.posY;
        double zDistance = this.posZ - this.entityCreature.posZ;
        double distance = xDistance * xDistance + yDistance * yDistance + zDistance * zDistance;

        if (this.courseChangeCooldown-- <= 0) {
            this.courseChangeCooldown += this.entityCreature.getRNG().nextInt(5) + 2;
            distance = (double)MathHelper.sqrt(distance);
            if(distance >= 1D) {
                this.entityCreature.setAIMoveSpeed((float)this.entityCreature.getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getAttributeValue());
                double speed = (this.entityCreature.getAIMoveSpeed() / 2.4D) * this.getSpeed();
                this.entityCreature.motionX += xDistance / distance * speed;
                this.entityCreature.motionY += yDistance / distance * speed;
                this.entityCreature.motionZ += zDistance / distance * speed;
            }
            else {
                this.action = EntityMoveHelper.Action.WAIT;
            }
        }
    }

    // Look At Target or Movement Direction:
    if (this.entityCreature.getAttackTarget() != null) {
        EntityLivingBase entitylivingbase = this.entityCreature.getAttackTarget();
        double distanceX = entitylivingbase.posX - this.entityCreature.posX;
        double distanceZ = entitylivingbase.posZ - this.entityCreature.posZ;
        this.entityCreature.renderYawOffset = this.entityCreature.rotationYaw = -((float)MathHelper.atan2(distanceX, distanceZ)) * (180F / (float)Math.PI);
    }
    else if(this.action == EntityMoveHelper.Action.MOVE_TO) {
        this.entityCreature.renderYawOffset = this.entityCreature.rotationYaw = -((float)MathHelper.atan2(this.entityCreature.motionX, this.entityCreature.motionZ)) * (180F / (float)Math.PI);
    }
}

public void onLivingUpdate() {
    super.onLivingUpdate();
    if(!this.getEntityWorld().isRemote) {
        // Wander Pause Rates:
        if(this.isInWater())
            this.wanderAI.setPauseRate(120);
        else
            this.wanderAI.setPauseRate(0);

        // Drop Owner When Tamed:
        if(this.isTamed() && this.hasPickupEntity() && this.getPickupEntity() == this.getOwner())
            this.dropPickupEntity();

        // Entity Pickup Update:
        this.attackAI.setEnabled(!this.hasPickupEntity());
        if(this.hasPickupEntity()) {
            ExtendedEntity extendedEntity = ExtendedEntity.getForEntity(this.getPickupEntity());
            if(extendedEntity != null)
                extendedEntity.setPickedUpByEntity(this);
            if(this.pickupTime++ % 40 == 0) {
                this.attackEntityAsMob(this.getPickupEntity(), 0.5F);
                if(this.getPickupEntity() instanceof EntityLivingBase) {
                    if(ObjectManager.getPotionEffect("penetration") != null)
                        this.getPickupEntity().addPotionEffect(new PotionEffect(ObjectManager.getPotionEffect("penetration"), this.getEffectDuration(5), 1));
                }
            }
        }
        else {
            if(this.pickupCooldown > 0)
                this.pickupCooldown--;
            this.pickupTime = 0;
        }
    }
}

