public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    int range = spellStat.getRange();
    double radius = spellStat.getRadius();
    if (rightStaff(staff)){
        range *= 2;
        radius += 0.5D;
    }
    int potency = spellStat.getPotency();
    float damage = SpellConfig.UpdraftBlastDamage.get().floatValue() * WandUtil.damageMultiply();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
        potency += WandUtil.getPotencyLevel(caster);
    }
    damage += potency;
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, radius);
    LivingEntity target = this.getTarget(caster, range);
    if (target != null){
        UpdraftBlast updraftBlast = new UpdraftBlast(ModEntityType.UPDRAFT_BLAST.get(), worldIn);
        updraftBlast.setOwner(caster);
        updraftBlast.setDamage(damage);
        updraftBlast.setAreaOfEffect((float) radius);
        updraftBlast.setPos(target.position());
        worldIn.addFreshEntity(updraftBlast);
    } else if (rayTraceResult instanceof BlockHitResult){
        BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
        UpdraftBlast updraftBlast = new UpdraftBlast(ModEntityType.UPDRAFT_BLAST.get(), worldIn);
        updraftBlast.setOwner(caster);
        updraftBlast.setDamage(damage);
        updraftBlast.setAreaOfEffect((float) radius);
        updraftBlast.setPos(blockPos.getX() + 0.5F, blockPos.getY() + 1.0F, blockPos.getZ() + 0.5F);
        worldIn.addFreshEntity(updraftBlast);
    }
}

public void handleServer(LinkItemToChatPayload msg, IPayloadContext ctx) {
    Player player = ctx.player();
    if (ItemLinking.isOnCooldown(player.getUUID(), player.level().getGameTime())) {
        return;
    }

    if (!AdventureConfig.enableItemLinking) {
        player.sendSystemMessage(Apotheosis.lang("message", "item_linking_disabled"));
        return;
    }

    AbstractContainerMenu menu = player.containerMenu;
    if (menu.containerId == msg.containerId && menu.slots.size() > msg.slot) {
        Slot slot = menu.getSlot(msg.slot);
        ItemStack stack = slot.getItem();

        int count = stack.getCount();

        // Stacks with a count higher than 99 cannot be serialized, so we have to clamp them.
        if (count > 99) {
            stack = stack.copyWithCount(99);
        }

        if (stack.getItem() == msg.intendedItem) {
            Component comp = stack.getDisplayName();
            if (count > 1) {
                comp = Apotheosis.lang("chat", "link_item_with_count", String.valueOf(count), comp);
            }
            PlayerChatMessage chatMsg = PlayerChatMessage.system("").withUnsignedContent(comp);
            player.level().getServer().getPlayerList().broadcastChatMessage(chatMsg, (ServerPlayer) player, ChatType.bind(ChatType.CHAT, player));
            ItemLinking.startCooldown(player.getUUID(), player.level().getGameTime());
        }
    }
}

protected void customServerAiStep() {
	super.customServerAiStep();

	if (isEgg())
		setSynchedData(IS_EGG, false);

	boolean wasFlying = isFlying();

	if (isInLove())
		setDeltaMovement(getDeltaMovement().subtract(0, 0.1f, 0));

	this.isFlying = !onGround();

	if (wasFlying != isFlying())
		updatePathControllers();

	if (isFlying()) {
		if (!isBaby())
			setNoGravity(true);
	}
	else if (!isVehicle()) {
		if (wasFlying) {
			triggerAnim("Movement", "Land");
			setNoGravity(false);
			getNavigation().stop();
			setDeltaMovement(0, -0.1f, 0);
		}
		else if (rand().oneInNChance(2000) && !BrainUtils.hasMemory(this, MemoryModuleType.BREED_TARGET) && !isInLove()) {
			getNavigation().stop();
			setDeltaMovement(0, 0.2f, 0);
			triggerAnim("Movement", "Takeoff");
		}
	}
}

protected InteractionResult mobInteract(Player player, InteractionHand hand) {
	if (isAlive() && isOwner(player) && getSynchedData(SUCCESS_TIMER) == -1) {
		ItemStack heldStack = player.getItemInHand(hand);

		if (getSynchedData(OWNER).isEmpty() && player instanceof ServerPlayer owner)
			setOwner(owner);

		if (heldStack.canPerformAction(ItemAbilities.HOE_TILL)) {
			if (getVariant().isCorrectOffering(heldStack)) {
				if (!level().isClientSide()) {
					setSynchedData(SUCCESS_TIMER, 44);
					player.awardKillScore(this, 1, this.level().damageSources().playerAttack(player));
					navigation.stop();
					setDeltaMovement(0, 0, 0);
				}
			}
			else if (!level().isClientSide) {
				discard();

				level().playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_DRYAD_SPRITE_UNHAPPY.get(), SoundSource.PLAYERS, 1, 1);

				for(int i = 0; i < 20; ++i) {
					ParticleBuilder.forRandomPosInEntity(ParticleTypes.ANGRY_VILLAGER, this)
							.velocity(RandomUtil.scaledGaussianValue(0.02d), RandomUtil.scaledGaussianValue(0.02d), RandomUtil.scaledGaussianValue(0.02d))
							.sendToAllPlayersTrackingEntity(this);
				}
			}

			return InteractionResult.SUCCESS;
		}
	}

	return super.mobInteract(player, hand);
}

		private static void render(Minecraft mc, GuiGraphics guiGraphics, String before, float extraShift, float x, float y, Style style, int color) {
			float a = (color >> 24 & 255) / 255.0F;

