protected void dropFromLootTable(@NonNull ServerLevel serverLevel, @NonNull DamageSource pDamageSource, boolean pAttackedRecently) {
    super.dropFromLootTable(serverLevel, pDamageSource, pAttackedRecently);

    var owner = this.getFamiliarOwner();

    var shard = new ItemStack(OccultismItems.SOUL_SHARD_ITEM.get());

    var health = this.getHealth();
    this.setHealth(this.getMaxHealth()); //simulate a healthy familiar to avoid death on respawn
    this.resetFallDistance();
    this.removeAllEffects();

    var id = this.getEncodeId();
    var entityData = new CompoundTag();
    if (id != null)
        entityData.putString("id", id);
    var valueOutput = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, this.registryAccess());
    this.saveWithoutId(valueOutput);
    entityData.merge(valueOutput.buildResult());

    shard.set(DataComponents.ENTITY_DATA, TypedEntityData.of(this.getType(), entityData));

    this.setHealth(health);

    if (owner instanceof Player player) {
        ItemTransferUtil.giveItemToPlayer(player, shard);
    } else {
        ItemEntity entityitem = new ItemEntity(this.level(), this.getX(), this.getY() + 0.5, this.getZ(), shard);
        entityitem.setPickUpDelay(5);
        entityitem.setDeltaMovement(entityitem.getDeltaMovement().multiply(0, 1, 0));

        this.level().addFreshEntity(entityitem);
    }
}

private static void fairySave(LivingDeathEvent event) {
    LivingEntity entity = event.getEntity();

    if (event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY) || !(entity instanceof IFamiliar familiar)
            || entity.getType() == OccultismEntities.GUARDIAN_FAMILIAR.get()
            || entity.getType() == OccultismEntities.FAIRY_FAMILIAR.get())
        return;

    LivingEntity owner = familiar.getFamiliarOwner();

    if (owner == null || !FamiliarUtil.isFamiliarEnabled(owner, OccultismEntities.FAIRY_FAMILIAR.get()))
        return;

    FairyFamiliarEntity fairy = FamiliarUtil.getFamiliar(owner, OccultismEntities.FAIRY_FAMILIAR.get());

    if (fairy == null || !fairy.saveFamiliar(familiar))
        return;

    if (!fairy.isAddedToLevel()) {
        if (entity.hasEffect(OccultismEffects.OCCULT_UNDYING_COOLDOWN)) {
            return;
        } else {
            int i = fairy.hasBlacksmithUpgrade() ? 1 : 2;
            entity.addEffect(new MobEffectInstance(OccultismEffects.OCCULT_UNDYING_COOLDOWN, i * 20 * 20, 0));
        }
    }

    event.setCanceled(true);
    entity.setHealth(2);
    entity.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 20 * 5, 2));

    if (!owner.level().isClientSide())
        OccultismAdvancements.FAMILIAR.get().trigger(owner, Type.FAIRY_SAVE);
}

public void tick() {
    tickMultipart();
    super.tick();
    this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
    prevLandProgress = landProgress;
    prevFishPitch = fishPitch;
    prevPulseAmount = pulseAmount;
    float targetFishPitch = Mth.clamp((float) this.getDeltaMovement().y * 2F, -1.4F, 1.4F) * -(float) (180F / (float) Math.PI);
    if(!isAlive()){
        targetFishPitch = 0.0F;
    }
    fishPitch = Mth.approachDegrees(fishPitch, targetFishPitch, 2.5F);
    boolean grounded = this.onGround() && !isInWaterOrBubble();
    if (grounded && landProgress < 5F) {
        landProgress++;
    }
    if (!grounded && landProgress > 0F) {
        landProgress--;
    }
    float pulseBy = getInterestLevel() * 0.45F;
    pulseAmount += pulseBy;
    if (!level().isClientSide) {
        double waterHeight = getFluidTypeHeight(ForgeMod.WATER_TYPE.get());
        if (waterHeight > 0 && waterHeight < this.getBbHeight() - 1.0F) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.05, 0));
        }
    }
    if (this.getAnimation() == HullbreakerEntity.ANIMATION_BASH && this.getAnimationTick() > 10 && this.getAnimationTick() <= 20) {
        breakBlock();
    }
    if (blockBreakCooldown > 0) {
        blockBreakCooldown--;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    if (fish.circleTime > fish.maxCircleTime) {
        fish.circleTime = 0;
        fish.circlePos = null;
    }
    if (fish.circlePos != null && fish.circleTime <= fish.maxCircleTime) {
        fish.circleTime++;
        Vec3 movePos = orbitAroundPos(fish.circlePos);
        fish.getNavigation().moveTo(movePos.x(), movePos.y(), movePos.z(), this.fish.circleSpeed);
    } else if (this.fish.isGroupLeader()) {
        if (fish.baitballCooldown == 0) {
            fish.baitballCooldown = 100 + this.fish.random.nextInt(150);
            if (fish.circlePos == null || fish.circleTime >= fish.maxCircleTime) {
                fish.circleTime = 0;
                fish.maxCircleTime = 100 + this.fish.random.nextInt(200);
                circleDistance = 1 + this.fish.random.nextFloat() * 1.5F;
                fish.circleSpeed = 0.75F + this.fish.random.nextFloat() * 0.5F;
                clockwise = this.fish.random.nextBoolean();
                fish.circlePos = findSwimToPos(3);
            }
        }
    } else if (fish.random.nextInt(40) == 0 || fish.hasNoLeader()) {
        Vec3 result = Vec3.atCenterOf(findSwimToPos(6));
        fish.getNavigation().moveTo(result.x, result.y, result.z, 1.0F);
    } else if (fish.hasGroupLeader() && fish.groupLeader.circlePos != null) {
        if (fish.circlePos == null) {
            fish.circlePos = fish.groupLeader.circlePos;
            fish.circleTime = fish.groupLeader.circleTime;
            fish.maxCircleTime = fish.groupLeader.maxCircleTime;
            circleDistance = 1 + this.fish.random.nextFloat() * 1.5F;
            clockwise = this.fish.random.nextBoolean();
            fish.circleSpeed = 0.75F + this.fish.random.nextFloat() * 0.5F;
        }
    }
}

