private void tetraTransformCrossbow(AbstractClientPlayer player, float partialTicks, float interpolatedPitch, InteractionHand hand,
        float p_109376_,
        ItemStack itemStack, float p_109378_, PoseStack poseStack, MultiBufferSource buffer, int light, CallbackInfo ci) {
    boolean isMainhand = hand == InteractionHand.MAIN_HAND;
    HumanoidArm arm = isMainhand ? player.getMainArm() : player.getMainArm().getOpposite();
    boolean isCharged = CrossbowItem.isCharged(itemStack);
    boolean flag2 = arm == HumanoidArm.RIGHT;
    int i = flag2 ? 1 : -1;
    if (player.isUsingItem() && player.getUseItemRemainingTicks() > 0 && player.getUsedItemHand() == hand) {
        this.applyItemArmTransform(poseStack, arm, p_109378_);
        poseStack.translate(i * -0.4785682F, -0.094387F, 0.05731531F);
        poseStack.mulPose(Axis.XP.rotationDegrees(-11.935F));
        poseStack.mulPose(Axis.YP.rotationDegrees(i * 65.3F));
        poseStack.mulPose(Axis.ZP.rotationDegrees(i * -9.785F));
        float f9 = itemStack.getUseDuration() - (player.getUseItemRemainingTicks() - partialTicks + 1.0F);
        float f13 = f9 / ((ModularCrossbowItemImpl) itemStack.getItem()).getReloadDuration(itemStack);
        if (f13 > 1.0F) {
            f13 = 1.0F;
        }

        if (f13 > 0.1F) {
            float f16 = Mth.sin((f9 - 0.1F) * 1.3F);
            float f3 = f13 - 0.1F;
            float f4 = f16 * f3;
            poseStack.translate(f4 * 0.0F, f4 * 0.004F, f4 * 0.0F);
        }

        poseStack.translate(0, 0, f13 * 0.04);
        poseStack.scale(1.0F, 1.0F, 1.0F + f13 * 0.2F);
        poseStack.mulPose(Axis.YN.rotationDegrees((float) i * 45.0F));
    } else if (isCharged && p_109376_ < 0.001F && isMainhand) {
        poseStack.translate(i * -0.641864F, 0.0D, 0.0D);
        poseStack.mulPose(Axis.YP.rotationDegrees((float) i * 10.0F));
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    int range = spellStat.getRange();
    int duration = spellStat.getDuration();
    double radius = spellStat.getRadius();
    float potency = spellStat.getPotency();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        duration *= WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
        potency += WandUtil.getPotencyLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, radius);
    LivingEntity target = this.getTarget(caster, range);
    if (target != null){
        if (target instanceof LivingEntity) {
            HailCloud hailCloud = new HailCloud(worldIn, caster, target);
            hailCloud.setExtraDamage(potency);
            hailCloud.setRadius((float) radius);
            hailCloud.setLifeSpan(duration);
            hailCloud.setStaff(rightStaff(staff));
            worldIn.addFreshEntity(hailCloud);
        }
        this.playSound(worldIn, caster, SoundEvents.PLAYER_HURT_FREEZE);
    } else if (rayTraceResult instanceof BlockHitResult){
        BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
        HailCloud hailCloud = new HailCloud(worldIn, caster, null);
        hailCloud.setExtraDamage(potency);
        hailCloud.setRadius((float) radius);
        hailCloud.setLifeSpan(duration);
        hailCloud.setStaff(rightStaff(staff));
        hailCloud.setPos(blockPos.getX() + 0.5F, blockPos.getY() + 4, blockPos.getZ() + 0.5F);
        worldIn.addFreshEntity(hailCloud);
        this.playSound(worldIn, caster, SoundEvents.PLAYER_HURT_FREEZE);
    }
}

