public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            i = caster.level.getRandom().nextIntBetweenInclusive(4, 7);
        } else if (rightStaff(staff)){
            i = 2 + caster.level.getRandom().nextInt(4);
        }
        for (int i1 = 0; i1 < i; ++i1) {
            AbstractReaper summonedentity = new AbstractReaper(ModEntityType.REAPER_SERVANT.get(), worldIn);
            summonedentity.setTrueOwner(caster);
            summonedentity.moveTo(BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn), 0.0F, 0.0F);
            MobUtil.moveDownToGround(summonedentity);
            summonedentity.setPersistenceRequired();
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        SoundUtil.playNecromancerSummon(caster);
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    if (hand == InteractionHand.MAIN_HAND && !this.level.isClientSide()) {
        if (!CompatBridge.Patchouli) {
            ModAdvancementTriggers.NO_PATCHOULI_LOADED.trigger((ServerPlayer) player);
        }
        ItemStack itemstack = player.getItemInHand(hand);

        // Highlight mobs in the same pack if Player is in Creative mode
        if (player.isCreative() && itemstack.isEmpty() && this instanceof IPackEntity && this.herd != null) {
            for (int i = 0; i < this.herd.creatureList.size(); ++i) {
                ComplexMob creature = this.herd.creatureList.get(i);
                creature.addEffect(new MobEffectInstance(MobEffects.GLOWING, 80, 0));
            }
        }

        // Command handler for tamed mobs, includes Food/Potion consumption
        if (this.isTame() && this.getOwner() == player) {
            if (itemstack.isEmpty()) {
                this.setCommandInt(this.getCommandInt() + 1);
                player.sendMessage(new TranslatableComponent("entity.untamedwilds.command." + this.getCommandInt()), Util.NIL_UUID);
                if (this.getCommandInt() > 1) {
                    this.getNavigation().stop();
                    this.setSitting(true);
                } else if (this.getCommandInt() <= 1 && this.isSitting()) {
                    this.setSitting(false);
                }
            }
            else {
                EntityUtils.consumeItemStack(this, itemstack);
            }
        }
        return super.mobInteract(player, hand);
    }
    return InteractionResult.PASS;
}

protected void tickMoveTo() {
    this.operation = Operation.WAIT;
    double xDelta = this.wantedX - this.mob.getX();
    double yDelta = this.wantedY - this.mob.getY();
    double zDelta = this.wantedZ - this.mob.getZ();

    if (xDelta * xDelta + yDelta * yDelta + zDelta * zDelta < 0.9f) {
        this.mob.setYya(0);
        this.mob.setZza(0);
        this.repathCooldown = this.mob.getTarget() != null ? 0 : this.mob.getRandom().nextIntBetweenInclusive(15, 25);

        return;
    }

    float yRot = (float)(Mth.atan2(zDelta, xDelta) * Mth.RAD_TO_DEG) - 90;
    float moveSpeed = getMoveSpeed();

    this.mob.setNoGravity(true);
    this.mob.setSpeed(moveSpeed);
    this.mob.setYRot(rotClamped(this.mob.getYRot(), yRot, 90f));

    double lateralDist = Math.sqrt(xDelta * xDelta + zDelta * zDelta);

    if (Math.abs(yDelta) > 0.75f || Math.abs(lateralDist) > 0.75f) {
        double angle = Mth.atan2(yDelta, lateralDist) * -Mth.RAD_TO_DEG;

        this.mob.setXRot(rotClamped(this.mob.getXRot(), (float)angle, this.maxTurn));

        if (Math.abs(yDelta) > 0.75f)
            this.mob.setYya(yDelta > 0 ? moveSpeed : -moveSpeed);
    }
    else {
        this.mob.setSpeed(0);
    }
}

public InteractionResult useOn(UseOnContext ctx) {
	Level world = ctx.getLevel();
	BlockPos pos = ctx.getClickedPos();
	Player player = ctx.getPlayer();
	ItemStack stack = ctx.getItemInHand();
	BlockState wstate = world.getBlockState(pos);
	Block block = wstate.getBlock();

	if (player != null && player.isSecondaryUseActive()) {
		if (world.getBlockEntity(pos) == null && block.asItem() != Items.AIR
				&& (wstate.isSolidRender(world, pos) || wstate.getRenderShape() == RenderShape.MODEL)
				&& (wstate.canOcclude() || block instanceof AbstractGlassBlock || block instanceof IronBarsBlock)
				&& block.asItem() instanceof BlockItem) {
			setItemToPlace(stack, block.asItem());
			setSwapTemplateDirection(stack, ctx.getClickedFace());
			setHitPos(stack, ctx.getClickLocation());

			displayRemainderCounter(player, stack);
			return InteractionResult.sidedSuccess(world.isClientSide());
		}
	} else if (canExchange(stack) && !ItemNBTHelper.getBoolean(stack, TAG_SWAPPING, false)) {
		Item replacement = getItemToPlace(stack);
		List<BlockPos> swap = getTargetPositions(world, stack, replacement, pos, block, ctx.getClickedFace());
		if (swap.size() > 0) {
			ItemNBTHelper.setBoolean(stack, TAG_SWAPPING, true);
			ItemNBTHelper.setInt(stack, TAG_SELECT_X, pos.getX());
			ItemNBTHelper.setInt(stack, TAG_SELECT_Y, pos.getY());
			ItemNBTHelper.setInt(stack, TAG_SELECT_Z, pos.getZ());
			setSwapClickDirection(stack, ctx.getClickedFace());
			setTarget(stack, block);
		}
	}

	return InteractionResult.sidedSuccess(world.isClientSide());
}

public void onAvatarUpdate(Avatar tile) {
	BlockEntity te = (BlockEntity) tile;
	Level world = te.getLevel();
	Map<UUID, Integer> cooldowns = tile.getBoostCooldowns();
	ManaReceiver receiver = XplatAbstractions.INSTANCE.findManaReceiver(world, te.getBlockPos(), te.getBlockState(), te, null);

	if (!world.isClientSide) {
		decAvatarCooldowns(cooldowns);
	}
	if (!world.isClientSide && receiver.getCurrentMana() >= COST && tile.isEnabled()) {
		double range = 5.5;
		double rangeY = 3.5;
		List<Player> players = world.getEntitiesOfClass(Player.class, new AABB(
				te.getBlockPos().getCenter().add(-range, -rangeY, -range),
				te.getBlockPos().getCenter().add(range, rangeY, range)
		));
		for (Player p : players) {
			int cooldown = 0;
			if (cooldowns.containsKey(p.getUUID())) {
				cooldown = cooldowns.get(p.getUUID());
			}
			if (!p.isShiftKeyDown() && cooldown <= 0) {
				if (p.getDeltaMovement().length() > 0.2 && p.getDeltaMovement().length() < 5 && p.isFallFlying()) {
					doAvatarElytraBoost(p, world);
					doAvatarMiscEffects(p, receiver);
					cooldowns.put(p.getUUID(), 20);
					te.setChanged();
				} else if (p.getDeltaMovement().y() > 0.3 && p.getDeltaMovement().y() < 2 && !p.isFallFlying()) {
					doAvatarJump(p, world);
					doAvatarMiscEffects(p, receiver);
				}
			}
		}
	}
}

public void tick() {
	super.tick();

	if(!level().isClientSide && entityData.get(VARIANT) == -1) {
		int variant = 0;
		if(random.nextBoolean()) // Color change
			variant += random.nextInt(COLORS - 1) + 1;

		if(random.nextInt(3) == 0) // Mold
			variant += COLORS;

		entityData.set(VARIANT, variant);
	}

	if(lightningCooldown > 0) {
		lightningCooldown--;
		clearFire();
	}

	if(isRaving() && level().isClientSide && tickCount % 10 == 0) {
		BlockPos below = blockPosition().below();
		BlockState belowState = level().getBlockState(below);
		if(belowState.is(BlockTags.SAND))
			level().levelEvent(LevelEvent.PARTICLES_DESTROY_BLOCK, below, Block.getId(belowState));
	}

	if(isRaving() && !level().isClientSide && tickCount % 20 == 0 && shouldStopRaving()) {
		setRaving(false);
		jukeboxPosition = null;
	}

	if(!level().isClientSide){
		recalculateStepHeight();
	}
}

public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!canSummon(shooter))
        return;

    Vec3 vector3d = safelyGetHitPos(rayTraceResult);
    int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
    BlockPos pos = BlockPos.containing(vector3d);
    if (ticks <= 0) return;
    int count = 3 + spellStats.getBuffCount(AugmentSplit.INSTANCE);
    for (int i = 0; i < count; ++i) {
        BlockPos blockpos = pos.offset(-2 + shooter.getRandom().nextInt(5), 2, -2 + shooter.getRandom().nextInt(5));

        ItemStack weapon = Items.IRON_SWORD.getDefaultInstance();
        if ((spellStats.hasBuff(AugmentPierce.INSTANCE))) {
            weapon = Items.BOW.getDefaultInstance();
            if (spellStats.getAmpMultiplier() > 0)
                weapon.enchant(HolderHelper.unwrap(world, Enchantments.POWER), Math.max(4, (int) spellStats.getAmpMultiplier()) - 1);
        } else {
            if (spellStats.getAmpMultiplier() >= 3) {
                weapon = Items.NETHERITE_AXE.getDefaultInstance();
            } else if (spellStats.getAmpMultiplier() > 2) {
                weapon = Items.NETHERITE_SWORD.getDefaultInstance();
            } else if (spellStats.getAmpMultiplier() > 1) {
                weapon = Items.DIAMOND_SWORD.getDefaultInstance();
            }
        }
        SummonSkeleton undeadentity = new SummonSkeleton(world, shooter, weapon);
        undeadentity.moveTo(blockpos, 0.0F, 0.0F);
        undeadentity.finalizeSpawn((ServerLevelAccessor) world, world.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null);
        undeadentity.setOwner(shooter);
        undeadentity.setLimitedLife(ticks);
        summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, undeadentity);
    }
    shooter.addEffect(new MobEffectInstance(ModPotions.SUMMONING_SICKNESS_EFFECT, ticks));
}

protected void dropFromLootTable(ServerLevel serverLevel, DamageSource pDamageSource, boolean pAttackedRecently) {
