protected boolean onUpdateServer(ServerLevel level) {
    boolean sendUpdatePacket = super.onUpdateServer(level);
    boolean active = false;
    if (!energyContainer.isEmpty()) {
        //Use 0.4 for y to catch entities that are partially standing on the back pane
        List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, new AABB(worldPosition.getX(), worldPosition.getY(), worldPosition.getZ(),
              worldPosition.getX() + 1, worldPosition.getY() + 0.4, worldPosition.getZ() + 1), CHARGE_PREDICATE);
        try (Transaction transaction = Transaction.openRoot()) {
            //TODO - 26.3: We are using this as a energy per target per tick limit rather than an overall transfer rate limit.
            // Do we want to somehow document that fact for the chargepad's limit
            int energyToGive = energyContainer.getEnergyPerTick();
            for (LivingEntity entity : entities) {
                if (energyContainer.isEmpty()) {
                    //If we run out of energy, stop checking the remaining entities
                    break;
                } else if (entity instanceof Player) {
                    if (chargeHandler(Capabilities.ITEM.getCapability(entity), energyToGive, transaction)) {
                        active = true;
                    } else if (chargeHandler(Mekanism.hooks.getCuriosInventory(entity), energyToGive, transaction)) {
                        //If we didn't charge anything in the inventory and curios is loaded try charging things in the curios slots
                        active = true;
                    }
                } else if (provideEnergy(Capabilities.ENERGY.getCapability(entity), energyToGive, transaction)) {
                    //Note: Robits are handled by this path
                    active = true;
                }
            }
            if (active) {
                transaction.commit();
            }
        }
    }
    setActive(active);
    return sendUpdatePacket;
}

public void tick() {
    super.tick();
    assert player != null;
    Item item = player.getItemInHand(InteractionHand.MAIN_HAND).getItem();
    List<LootFruitCodec> lootFruits = LootFruitJsonManager.getLoot(item, null);
    if (lootFruits == null) return;
    if (!lootFruits.isEmpty()) {
        ItemStack lootFruit = new ItemStack(UPBlocks.FRUIT_LOOT_BOX.get());
        CompoundTag lootFruitTag = lootFruit.getOrCreateTag();
        int color = lootFruits.get(0).getColor().getValue();
        int modelData = lootFruits.get(0).getCustomModelData();
        lootFruitTag.putString("translationKey", lootFruits.get(0).getTranslationKey());
        lootFruitTag.putInt("color", color);
        lootFruitTag.put("tradeItem", item.getDefaultInstance().serializeNBT());
        lootFruitTag.putInt("CustomModelData", modelData);
        lootFruit.setTag(lootFruitTag);
        this.mob.setItemInHand(InteractionHand.MAIN_HAND, lootFruit);
        if (this.mob.getTradingAndGottenItem()) {

            double d0 = this.player.getX()- this.mob.getX();
            double d1 = this.player.getY() - this.mob.getY();
            double d2 = this.player.getZ() - this.mob.getZ();
            Vec3 vec3 = new Vec3(d0, d1, d2);
            vec3.multiply(0.5, 0.5 ,0.5);
