public void aiStep() {
	super.aiStep();
	int i = 10;
	int j = 4;
	BlockPos blockpos = this.blockPosition();
	BlockPos.MutableBlockPos blockpos$mutableblockpos = new BlockPos.MutableBlockPos();

	for(int k = 4; k <= j; k = k > 0 ? -k : 1 - k) {
		for(int l = 0; l < i; ++l) {
			for(int i1 = 0; i1 <= l; i1 = i1 > 0 ? -i1 : 1 - i1) {
				for(int j1 = i1 < l && i1 > -l ? l : 0; j1 <= l; j1 = j1 > 0 ? -j1 : 1 - j1) {
					blockpos$mutableblockpos.setWithOffset(blockpos, i1, k - 1, j1);
					Block eggs = level().getBlockState(blockpos$mutableblockpos).getBlock();
					if (this.isWithinRestriction(blockpos$mutableblockpos) && (level().getBlockState(blockpos$mutableblockpos).is(Blocks.TURTLE_EGG) && level().getBlockState(blockpos$mutableblockpos).getValue(TurtleEggBlock.EGGS) >= 1 || eggs instanceof DinosaurEggBlock && level().getBlockState(blockpos$mutableblockpos).getValue(DinosaurEggBlock.EGGS) >= 1)) {
						if (!this.isBaby()) {
							for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(10, 4, 10))) {
								if (entity instanceof DinosaurEntity dinosaur) {
									if (dinosaur.isOvivorous()) {
										this.setTarget(dinosaur);
									}
								}
								if (entity instanceof Player player) {
									if (!trusts(player.getUUID()) && !isPassive() || !player.getItemBySlot(EquipmentSlot.HEAD).is(PFItems.EGG_HELMET.get())) {
										this.setTarget(player);
									}
								}
							}
						}
					}
				}
			}
		}
	}

}

public boolean canUse() {
    if (entity.sacrificeCooldown > 0) {
        return false;
    }
    if (entity.isPackFollower()) {
        UnderzealotEntity leader = (UnderzealotEntity) entity.getPackLeader();
        if (leader.isCarrying() && leader.getLastSacrificePos() != null && leader.distanceToSqr(Vec3.atCenterOf(leader.getLastSacrificePos())) < 2.5F) {
            center = leader.getLastSacrificePos();
            return true;
        }
    } else if (entity.isCarrying()) {
        if (executionCooldown-- > 0) {
            return false;
        } else {
            executionCooldown = 20 + entity.getRandom().nextInt(100);
            BlockPos pos = null;
            if (entity.getLastSacrificePos() != null) {
                if (isValidSacrificePos(entity.getLastSacrificePos())) {
                    executionCooldown = 10;
                    pos = entity.getLastSacrificePos();
                } else {
                    entity.setLastSacrificePos(null);
                }
            }
            if (pos == null) {
                pos = findNearestSacrificePos();
            }
            if (pos != null) {
                center = pos;
                entity.setLastSacrificePos(center);
                return true;
            }
        }
    }
    return false;
}

