public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {

    if (!target.level().isClientSide) {
        int amplifier = item.getEffectLevel(itemStack, ItemEffect.pry);
        amplifier += (int) (getOverchargeBonus(item, itemStack, chargedTicks) * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));

        double damageMultiplier = PryEffect.damageMultiplier;
        damageMultiplier += getOverchargeBonus(item, itemStack, chargedTicks) * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;

        int comboPoints = ComboPoints.get(attacker);
        boolean isSatiated = !attacker.getFoodData().needsFood();

        AbilityUseResult result = PryEffect.performRegular(attacker, item, itemStack, damageMultiplier, amplifier, target, isSatiated, comboPoints);
        item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            PryEffect.performEcho(attacker, item, itemStack, damageMultiplier, amplifier, target, isSatiated, comboPoints);
        }
    }

    attacker.causeFoodExhaustion(1f);
    attacker.swing(hand, false);
    attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack));

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
    if (revengeLevel > 0) {
        RevengeTracker.removeEnemy(attacker, target);
    }

    item.applyDamage(2, itemStack, attacker);
}

public boolean useCharge(ItemStack containerStack, int slot, int chargeToUse) {
	int charge = getMigratedStoredCharge(containerStack, slot);
	int partialCharge = getPartialCharge(containerStack, slot);

	if (partialCharge >= chargeToUse) {
		if (partialCharge == chargeToUse) {
			removePartialCharge(containerStack, slot);
		} else {
			setPartialCharge(containerStack, slot, partialCharge - chargeToUse);
		}
		return true;
	}

	int worth = getSlotWorth(slot);

	if ((long) charge * worth + partialCharge >= chargeToUse) {
		long additionalPartialChargeNeeded = (long) chargeToUse - partialCharge;
		int actualChargeToRemove = (int) (additionalPartialChargeNeeded / worth + (additionalPartialChargeNeeded % worth > 0 ? 1 : 0));
		int partialChargeToAdd = (int) ((long) actualChargeToRemove * worth - chargeToUse);
		if (actualChargeToRemove == charge && removeSlotWhenEmpty(slot)) {
			removeSlot(containerStack, slot);
		} else {
			extractStoredCharge(containerStack, slot, actualChargeToRemove);
		}

		int newPartialCharge = partialCharge + partialChargeToAdd;
		if (newPartialCharge > 0) {
			setPartialCharge(containerStack, slot, newPartialCharge);
		} else {
			removePartialCharge(containerStack, slot);
		}
		return true;
	}

	return false;
}

public static void TargetEvents(LivingChangeTargetEvent event){
    LivingEntity attacker = event.getEntity();
    LivingEntity target = event.getOriginalTarget();
    if (attacker instanceof Mob mobAttacker) {
        if (target != null) {
            if (attacker instanceof IOwned){
                if (target instanceof ArmorStand || target instanceof HauntedArmorStand){
                    if (event.getTargetType() == MOB_TARGET) {
                        event.setNewTarget(null);
                    } else {
                        event.setCanceled(true);
                    }
                }
            }
            if ((mobAttacker.getMobType() == MobType.UNDEAD && !(mobAttacker instanceof IOwned) && mobAttacker.getMaxHealth() < 100.0F) || mobAttacker instanceof Creeper) {
                if (event.getNewTarget() instanceof Apostle) {
                    event.setCanceled(true);
                }
            }
            if (mobAttacker.getType().is(ModTags.EntityTypes.CREEPERS) && CuriosFinder.hasCurio(target, ModItems.FELINE_AMULET.get())){
                if (event.getTargetType() == MOB_TARGET) {
                    event.setNewTarget(null);
                } else {
                    event.setCanceled(true);
                }
            }
            if (mobAttacker instanceof Phantom && CuriosFinder.hasCurio(target, ModItems.FELINE_AMULET.get())){
                if (event.getTargetType() == MOB_TARGET) {
                    event.setNewTarget(null);
                } else {
                    event.setCanceled(true);
                }
            }
        }
    }
}

public boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos) {
    if (!level.isClientSide) {
        if (level.getBlockState(blockPos).is(Blocks.MAGMA_BLOCK)) {
            if (level.getBlockState(blockPos.offset(MAGMA_BLOCK)).is(Blocks.MAGMA_BLOCK)
                    && level.getBlockState(blockPos.offset(DEEPSLATE)).getBlock().getDescriptionId().contains("deepslate")
                    && level.getBlockState(blockPos.offset(DEEPSLATE)).isSolidRender(level, blockPos.offset(DEEPSLATE))
                    && level.getBlockState(blockPos.offset(BRAZIER)).is(ModTags.Blocks.BRAZIER)) {
                if (conditionsMet(level, player)) {
                    if (SEHelper.hasResearch(player, ResearchList.WARRED)) {
                        FlameConstruct construct = ModEntityType.FLAME_CONSTRUCT.get().create(level);
                        if (construct != null) {
                            construct.setTrueOwner(player);
                            construct.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(construct.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                            construct.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.below().getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                            if (level.addFreshEntity(construct)) {
                                removeBlocks(level, blockPos);
                                stack.shrink(1);
                                if (player instanceof ServerPlayer serverPlayer) {
                                    CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, construct);
                                }
                                return true;
                            }
                        }
                    } else {
                        player.displayClientMessage(Component.translatable("info.goety.research.fail"), true);
                    }
                } else {
                    player.displayClientMessage(Component.translatable("info.goety.summon.limit"), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.block.fail"), true);
            }
        }
    }
    return false;
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 3;
        if (rightStaff(staff)){
            i = 3 + worldIn.random.nextInt(3);
        }
        for (int i1 = 0; i1 < i; ++i1) {
            BlockPos blockpos = caster.blockPosition().offset(-2 + caster.getRandom().nextInt(5), 1, -2 + caster.getRandom().nextInt(5));
            AllyVex vexentity = new AllyVex(ModEntityType.VEX_SERVANT.get(), worldIn);
            vexentity.setTrueOwner(caster);
            vexentity.moveTo(blockpos, 0.0F, 0.0F);
            vexentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null, null);
            vexentity.setBoundOrigin(blockpos);
            vexentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            if (potency > 0) {
                Map<Enchantment, Integer> map = EnchantmentHelper.getEnchantments(vexentity.getMainHandItem());
                map.putIfAbsent(Enchantments.SHARPNESS, potency);
                EnchantmentHelper.setEnchantments(map, vexentity.getMainHandItem());
                vexentity.setItemSlot(EquipmentSlot.MAINHAND, vexentity.getMainHandItem());
            }
            this.SummonSap(caster, vexentity);
            this.setTarget(caster, vexentity);
            worldIn.addFreshEntity(vexentity);
            this.summonAdvancement(caster, vexentity);
        }
        this.playSound(worldIn, caster, SoundEvents.EVOKER_CAST_SPELL);
        this.SummonDown(caster);
    }
}

