public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    double radius = spellStat.getRadius();
    int range = spellStat.getRange();
    float damage = SpellConfig.LightningDamage.get().floatValue() * WandUtil.damageMultiply();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        damage += WandUtil.getPotencyLevel(caster);
    }
    damage += spellStat.getPotency();
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, radius);
    Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()));
    if (lightningRod.isPresent() && !rightStaff(staff)){
        BlockPos blockPos = lightningRod.get();
        SpellLightningBolt lightningBolt = new SpellLightningBolt(ModEntityType.SPELL_LIGHTNING_BOLT.get(), worldIn);
        lightningBolt.setDamage(damage);
        lightningBolt.moveTo(Vec3.atBottomCenterOf(blockPos));
        lightningBolt.setOwner(caster);
        worldIn.addFreshEntity(lightningBolt);
    } else {
        LivingEntity target = this.getTarget(caster, range);
        if (target != null){
            SpellLightningBolt lightningBolt = new SpellLightningBolt(ModEntityType.SPELL_LIGHTNING_BOLT.get(), worldIn);
            lightningBolt.setDamage(damage);
            lightningBolt.setPos(target.position());
            lightningBolt.setOwner(caster);
            worldIn.addFreshEntity(lightningBolt);
        } else if (rayTraceResult instanceof BlockHitResult blockHitResult){
            BlockPos blockPos = blockHitResult.getBlockPos();
            SpellLightningBolt lightningBolt = new SpellLightningBolt(ModEntityType.SPELL_LIGHTNING_BOLT.get(), worldIn);
            lightningBolt.setDamage(damage);
            lightningBolt.moveTo(Vec3.atBottomCenterOf(blockPos));
            lightningBolt.setOwner(caster);
            worldIn.addFreshEntity(lightningBolt);
        }
    }
}

private static void tick(Level level, BlockPos pos, BlockState state, SarcophagusBlockEntity blockEntity) {
    if (state.getValue(SarcophagusBlock.LAYER) != 0) {
        return;
    }
    if (blockEntity.state != STATE_CLOSING) {
        if (blockEntity.doorTimer > 0) {
            blockEntity.doorTimer++;
        }
        if (blockEntity.doorTimer >= 91) {
            level.setBlockAndUpdate(pos, state.setValue(SarcophagusBlock.LIT, false));
            level.setBlockAndUpdate(pos.above(), level.getBlockState(pos.above()).setValue(SarcophagusBlock.LIT, false));
            level.setBlockAndUpdate(pos.above(2), level.getBlockState(pos.above(2)).setValue(SarcophagusBlock.LIT, false));
            blockEntity.setState(STATE_CLOSING);
            if (!level.isClientSide) {
                AnuBoss anuBoss = ModEntities.ANU_BOSS.get().create(level);
                BlockPos anuPos = pos.relative(state.getValue(SarcophagusBlock.FACING));
                anuBoss.moveTo(anuPos, state.getValue(SarcophagusBlock.FACING).toYRot(), 0);
                anuBoss.yHeadRot = state.getValue(SarcophagusBlock.FACING).toYRot();
                anuBoss.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(pos), MobSpawnType.NATURAL, null, null);
                Vec3 spawn = anuBoss.position();
                AABB arenaBounds = new AABB(spawn.x - AnuBoss.ARENA_RADIUS, spawn.y - 10, spawn.z - AnuBoss.ARENA_RADIUS,
                        spawn.x + AnuBoss.ARENA_RADIUS, spawn.y + 10, spawn.z + AnuBoss.ARENA_RADIUS);
                List<Player> players = level.getNearbyPlayers(TargetingConditions.DEFAULT, anuBoss, arenaBounds);
                players.forEach(player -> player.displayClientMessage(AnuBoss.getRandomGreeting(level.random), false));
                level.addFreshEntity(anuBoss);
            }
        }
    } else {
        if (blockEntity.doorTimer > 0) {
            blockEntity.doorTimer--;
        }
        if (blockEntity.doorTimer == 0) {
            blockEntity.setState(STATE_LOCKED);
        }
    }
}

public void tick() {
	super.tick();

	setDeltaMovement(getDeltaMovement().multiply(1, 0.15f, 1));

	if (!level.isClientSide) {
		if (chargeCooldown > 0) {
			chargeCooldown--;

			if (chargeCooldown == 40)
				level.playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_CRAEXXEUS_CHARGE.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
		}
		else {
			chargeCooldown = 300;

			if (getTarget() != null) {
				LivingEntity target = getTarget();
				BaseMobProjectile projectile = new CraexxeusNukeEntity(this, BaseMobProjectile.Type.MAGIC);

				double distanceFactorX = target.getX() - projectile.getX();
				double distanceFactorY = target.getBoundingBox().minY + (target.getBbHeight() / 3) - projectile.getY();
				double distanceFactorZ = target.getZ() - projectile.getZ();
				double hyp = MathHelper.sqrt(distanceFactorX * distanceFactorX + distanceFactorZ * distanceFactorZ) * 0.05d;

				level.playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_CRAEXXEUS_NUKE.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
				projectile.shoot(distanceFactorX, distanceFactorY + hyp, distanceFactorZ, 1.6f, (float)(4 - this.level.getDifficulty().getId()));
				level.addFreshEntity(projectile);
			}
		}

		float healthPercent = getHealth() / getMaxHealth();

		if (healthPercent != bossInfo.getPercent())
			bossInfo.setPercent(healthPercent);
	}
}

