public void tick() {
    super.tick();

    if (entityData.get(HAS_POPPED)) {
        poppingTicks++;
    }

    if (!level.isClientSide) {
        age++;
        if (age > maxAge) {
            this.pop();
        }

        if (this.getPassengers().isEmpty()) {
            for (Entity entity1 : level.getEntities(this, this.getBoundingBox().inflate(0.5f), this::canHitEntity)) {
                // ignore boardingCooldown
                var accessor = (EntityAccessor) entity1;
                var cooldown = accessor.getBoardingCooldown();
                accessor.setBoardingCooldown(0);
                if (!entity1.startRiding(this)) {
                    accessor.setBoardingCooldown(cooldown);
                }
            }
        }
    }

    if (poppingTicks > 5 && !level.isClientSide) {
        this.remove(RemovalReason.DISCARDED);
    }

    this.xOld = this.getX();
    this.yOld = this.getY();
    this.zOld = this.getZ();
    this.setDeltaMovement(ParticleUtil.inRange(-0.01, 0.01), 0.1, ParticleUtil.inRange(-0.01, 0.01));
    this.setPos(getNextHitPosition());
}

