public InteractionResult mobInteract(Player player, InteractionHand hand) {
	ItemStack itemstack = player.getItemInHand(hand);
	Item item = itemstack.getItem();
	if (item == Items.WATER_BUCKET && this.isAlive()) {
		this.playSound(UASoundEvents.BUCKET_FILL_JELLYFISH.get(), 1.0F, 1.0F);
		itemstack.shrink(1);
		ItemStack bucket = this.getBucketItemStack();
		this.saveToBucketTag(bucket);
		if (!this.level().isClientSide) {
			CriteriaTriggers.FILLED_BUCKET.trigger((ServerPlayer) player, bucket);
		}

		if (itemstack.isEmpty()) {
			player.setItemInHand(hand, bucket);
		} else if (!player.getInventory().add(bucket)) {
			player.drop(bucket, false);
		}

		this.discard();
		return InteractionResult.SUCCESS;
	} else if (itemstack.isEmpty() && this.getName().getString().toLowerCase(Locale.ROOT).trim().equals("jellysox345")) {
		this.startRiding(player);
		return InteractionResult.SUCCESS;
	} else if (item == UAItems.PRISMARINE_ROD.get() && !this.hasCooldown()) {
		Random rand = new Random();
		if (this.isEffectiveAi() && rand.nextFloat() < this.getCooldownChance()) {
			this.setCooldown(20 * (rand.nextInt(16) + 15));
			this.playSound(UASoundEvents.JELLYFISH_COOLDOWN_START.get(), 1.0F, this.random.nextFloat() * 0.15F + 1.0F);
		}
		itemstack.shrink(1);
		player.addItem(this.getTorchByType(this.getJellyTorchType()));
		this.playSound(UASoundEvents.JELLYFISH_HARVEST.get(), 1.0F, this.random.nextFloat() * 0.15F + 1.0F);
		return InteractionResult.SUCCESS;
	}
	return super.mobInteract(player, hand);
}

public void tick() {
    EntityBison.this.lookAt(EntityBison.this.chargePartner, 30, 30);
    EntityBison.this.yBodyRot = EntityBison.this.getYRot();
    if (!EntityBison.this.isCharging()) {
        final Animation bisonAnimation = EntityBison.this.getAnimation();
        if (bisonAnimation == NO_ANIMATION || bisonAnimation == ANIMATION_PREPARE_CHARGE && EntityBison.this.getAnimationTick() > 35) {
            EntityBison.this.setCharging(true);
        }
    } else {
        final float dist = EntityBison.this.distanceTo(EntityBison.this.chargePartner);
        EntityBison.this.getNavigation().moveTo(EntityBison.this.chargePartner, 1.0F);
        if (EntityBison.this.hasLineOfSight(EntityBison.this.chargePartner)) {
            final float flingAnimAt = EntityBison.this.getBbWidth() + 1.0F;
            if (dist < flingAnimAt && EntityBison.this.getAnimation() == ANIMATION_ATTACK) {
                if (EntityBison.this.getAnimationTick() > 8) {
                    boolean flag = false;
                    if (EntityBison.this.onGround()) {
                        EntityBison.this.pushBackJostling(EntityBison.this.chargePartner, 0.2F);
                        flag = true;
                    }
                    if (EntityBison.this.chargePartner.onGround()) {
                        EntityBison.this.chargePartner.pushBackJostling(EntityBison.this, 0.9F);
                        flag = true;
                    }
                    if (flag) {
                        EntityBison.this.resetChargeCooldown();
                    }
                }
            } else {
                final float startFlingAnimAt = EntityBison.this.getBbWidth() + 3.0F;
                if (dist < startFlingAnimAt && EntityBison.this.getAnimation() != ANIMATION_ATTACK) {
                    EntityBison.this.setAnimation(ANIMATION_ATTACK);
                }
            }
        }
    }
}

public void tick(){
    if(jumpCooldown > 0){
        jumpCooldown--;
    }
    double dist = chungus.distanceTo(chungus.getTarget()) - chungus.getTarget().getBbWidth();
    if(dist < 2.0D){
        if(hasJumped){
            if(!chungus.onGround()){
                chungus.getTarget().hurt(chungus.damageSources().mobAttack(chungus), 10);
            }
            hasJumped = false;
        }else{
            if(chungus.getRandom().nextBoolean()){
                chungus.setAnimation(EntityBunfungus.ANIMATION_SLAM);
            }else{
                chungus.setAnimation(EntityBunfungus.ANIMATION_BELLY);
            }
        }
    }else if(dist < 5.0D || !chungus.hasLineOfSight(chungus.getTarget()) || jumpCooldown > 0 || chungus.isInWaterOrBubble()){
        chungus.getNavigation().moveTo(chungus.getTarget(), 1.0D);
    }else{
        chungus.getNavigation().stop();
        if(chungus.onGround()){
            Vec3 vector3d = this.chungus.getDeltaMovement();
            Vec3 vector3d1 = new Vec3(chungus.getTarget().getX() - this.chungus.getX(), 0.0D, chungus.getTarget().getZ() - this.chungus.getZ());
            if (vector3d1.lengthSqr() > 1.0E-7D) {
                vector3d1 = vector3d1.normalize().scale(0.9D).add(vector3d.scale(0.8D));
            }
            this.chungus.onJump();
            this.chungus.setDeltaMovement(vector3d1.x, 0.6F, vector3d1.z);
            chungus.setYRot(-((float) Mth.atan2(vector3d1.x, vector3d1.z)) * Mth.RAD_TO_DEG);
            chungus.yBodyRot = chungus.getYRot();
            hasJumped = true;
            jumpCooldown = 10;
        }
    }
}

public void tick() {
    if (moveCooldown > 0) {
        moveCooldown--;
    }
    BlockPos blockpos = this.getMoveToTarget();
    if (!isWithinXZDist(blockpos, this.mob.position(), this.acceptedDistance())) {
        this.isAboveDestinationBear = false;
        ++this.tryTicks;
        if (this.shouldRecalculatePath()) {
            moveCooldown = 30 + elephant.getRandom().nextInt(50);
            this.mob.getNavigation().moveTo((double) ((float) blockpos.getX()) + 0.5D, blockpos.getY(), (double) ((float) blockpos.getZ()) + 0.5D, this.speedModifier);
        }
    } else {
        this.isAboveDestinationBear = true;
        this.tryTicks = 0;
    }

    if (this.isReachedTarget() && Math.abs(elephant.getY() - blockPos.getY()) <= 3) {
        elephant.lookAt(EntityAnchorArgument.Anchor.EYES, new Vec3(blockPos.getX() + 0.5D, blockPos.getY(), blockPos.getZ() + 0.5));
        if (elephant.getY() + 2 < blockPos.getY()) {
            if (elephant.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                elephant.setAnimation(EntityElephant.ANIMATION_BREAKLEAVES);
            }
            elephant.setStanding(true);
            elephant.maxStandTime = 15;
        } else {
            elephant.setAnimation(EntityElephant.ANIMATION_BREAKLEAVES);
            elephant.setStanding(false);
        }
        if (this.idleAtLeavesTime >= 10) {
            this.breakLeaves();
        } else {
            ++this.idleAtLeavesTime;
        }
    }

}

public void breakBlock() {
    if (this.blockBreakCounter > 0 || IafConfig.dragonBreakBlockCooldown == 0) {
        --this.blockBreakCounter;
        if (!this.isIceInWater() && (this.blockBreakCounter == 0 || IafConfig.dragonBreakBlockCooldown == 0) && net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level, this)) {
            if (IafConfig.dragonGriefing != 2 && (!this.isTame() || IafConfig.tamedDragonGriefing)) {
                if (!isModelDead() && this.getDragonStage() >= 3 && (this.canMove() || this.getControllingPassenger() != null)) {
                    final int bounds = 1;//(int)Math.ceil(this.getRenderSize() * 0.1);
                    final int flightModifier = isFlying() && this.getTarget() != null ? -1 : 1;
                    final int yMinus = calculateDownY();
                    BlockPos.betweenClosedStream(
                        (int) Math.floor(this.getBoundingBox().minX) - bounds,
                        (int) Math.floor(this.getBoundingBox().minY) + yMinus,
                        (int) Math.floor(this.getBoundingBox().minZ) - bounds,
                        (int) Math.floor(this.getBoundingBox().maxX) + bounds,
                        (int) Math.floor(this.getBoundingBox().maxY) + bounds + flightModifier,
                        (int) Math.floor(this.getBoundingBox().maxZ) + bounds
                    ).forEach(pos -> {
                        if (MinecraftForge.EVENT_BUS.post(new GenericGriefEvent(this, pos.getX(), pos.getY(), pos.getZ())))
                            return;
                        final BlockState state = level.getBlockState(pos);
                        final float hardness = IafConfig.dragonGriefing == 1 || this.getDragonStage() <= 3 ? 2.0F : 5.0F;
                        if (isBreakable(pos, state, hardness)) {
                            this.setDeltaMovement(this.getDeltaMovement().multiply(0.6F, 1, 0.6F));
                            if (!level.isClientSide) {
                                if (random.nextFloat() <= IafConfig.dragonBlockBreakingDropChance && DragonUtils.canDropFromDragonBlockBreak(state)) {
                                    level.destroyBlock(pos, true);
                                } else {
                                    level.setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());
                                }
                            }
                        }
                    });
                }
            }
        }
    }
}

public void onUpdate() {
	super.onUpdate();

	if(!this.world.isRemote) {
		if(this.isEntityAlive()) {
			if(this.eggSacMovementCooldown > 0) {
				this.eggSacMovementCooldown--;
			} else if(this.getEggSacPercentage() >= 0) {
				float percentage = Math.max(this.getEggSacPercentage(), 0) + 0.005F;

				if(percentage >= 1.0F) {
					MultiPartEntityPart tailPart = this.parts[this.parts.length - 1];

					EntityTinyWormEggSac eggSac = new EntityTinyWormEggSac(this.world);
					eggSac.setLocationAndAngles(tailPart.posX, tailPart.posY, tailPart.posZ, 0, 0);

					this.world.spawnEntity(eggSac);

					this.setEggSacPercentage(-1);
				} else {
					this.setEggSacPercentage(percentage);
				}
			}
		}
	} else {
		this.updateSegmentPositions();

		float eggSackPercentage = this.getEggSacPercentage();

		if(eggSackPercentage >= 0) {
			this.prevEggSacPosition = this.eggSacPosition;
			this.eggSacPosition = this.spineySpliney.interpolate(eggSackPercentage);
		} else {
			this.prevEggSacPosition = this.eggSacPosition = null;
		}
	}
}

public static void PotionAddedEvents(MobEffectEvent.Added event){
    LivingEntity effected = event.getEntity();
    MobEffectInstance instance = event.getEffectInstance();
    MobEffect effect = instance.getEffect();
    if (effect == GoetyEffects.BURN_HEX.get()){
        if (effected.hasEffect(MobEffects.FIRE_RESISTANCE)){
            effected.removeEffect(MobEffects.FIRE_RESISTANCE);
        }
    }
    if (effect == GoetyEffects.SNOW_SKIN.get()){
        if (effected.hasEffect(GoetyEffects.FREEZING.get())){
            effected.removeEffect(GoetyEffects.FREEZING.get());
        }
    }
    if (effect == GoetyEffects.ENDER_GROUND.get()){
        if (effected.hasEffect(GoetyEffects.SHADOW_WALK.get())){
            effected.removeEffect(GoetyEffects.SHADOW_WALK.get());
        }
    }
    if (effect == GoetyEffects.VOID_TOUCHED.get()){
        if (!effected.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
            if (effected.level instanceof ServerLevel) {
                ModNetwork.sentToTrackingEntityAndPlayer(effected, new SPlayWorldSoundPacket(effected.blockPosition(), ModSounds.VOID_TOUCHED_ACTIVATE.get(), 1.0F, 1.0F));
            }
        }
    }
    if (effect == GoetyEffects.SENSE_LOSS.get()){
        if (effected instanceof Mob mob){
            mob.setTarget(null);
        }
    }
    if (effect == GoetyEffects.ENCHANTED.get()) {
        if (event.getEffectSource() != null) {
            MiscCapHelper.setEnchanter(effected, event.getEffectSource());
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (rightStaff(staff)){
            i = 2 + caster.level.getRandom().nextInt(2);
        }
        for (int i1 = 0; i1 < i; ++i1) {
            Summoned summonedentity = new StoneMinistrosity(ModEntityType.STONE_MINISTROSITY.get(), worldIn);
            if (this.GeoPower(caster)) {
                summonedentity = new RedstoneMinistrosity(ModEntityType.REDSTONE_MINISTROSITY.get(), worldIn);
            }
            BlockPos blockPos = BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn);
            summonedentity.setTrueOwner(caster);
            summonedentity.moveTo(blockPos, 0.0F, 0.0F);
            MobUtil.moveDownToGround(summonedentity);
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.setPersistenceRequired();
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED,null,null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.SUMMON_SPELL.get());
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    int range = spellStat.getRange();
    if (WandUtil.enchantedFocus(caster)) {
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        range += WandUtil.getRangeLevel(caster);
    }
    float damage = this.damage + potency;
    if (!worldIn.isClientSide) {
        for (Entity target : getBreathTarget(caster, range)) {
            if (target != null) {
                if (target.hurt(ModDamageSource.swarm(caster, caster), damage)){
                    if (rightStaff(staff)) {
                        if (target instanceof LivingEntity livingTarget) {
                            MobEffect mobEffect = MobEffects.POISON;
                            if (CuriosFinder.hasWildRobe(caster)) {
                                mobEffect = GoetyEffects.ACID_VENOM.get();
                            }
                            livingTarget.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(5) * duration));
                        }
                    }
                    if (!target.isAlive()){
                        InsectSwarm insectSwarm = new InsectSwarm(worldIn, caster, target.position());
                        insectSwarm.setLimitedLife(200 * duration);
                        if (potency > 0){
                            insectSwarm.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), potency - 1, false, false));
                        }
                        worldIn.addFreshEntity(insectSwarm);
                    }
                }
            }
        }
    }
    this.playSound(worldIn, caster, ModSounds.INSECT_SWARM.get(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
}

private boolean tryDigDown() {
    if (isUnbreakable(getBlockPos().relative(Direction.DOWN, currentDepth + 1))) {
        status = Status.STUCK;
    } else if (getBlockPos().getY() - currentDepth >= nonNullLevel().getMinBuildHeight()) {
        status = Status.DIGGING;
        currentDepth++;
        BlockPos pos1 = getBlockPos().relative(Direction.DOWN, currentDepth);
        final Level level = nonNullLevel();
        if (!isPipe(level, pos1)) {
            ItemStack extracted = inventory.extractItem(0, 1, true);
            if (extracted.getItem() == ModBlocks.DRILL_PIPE.get().asItem()) {
                BlockState currentState = level.getBlockState(pos1);
                BlockState newState = ((BlockItem) extracted.getItem()).getBlock().defaultBlockState();

                int airRequired = Math.round(66.66f * currentState.getDestroySpeed(level, pos1));
                if (airHandler.getAir() > airRequired) {
                    inventory.extractItem(0, 1, false);
                    level.destroyBlock(pos1, false);
                    level.setBlockAndUpdate(pos1, newState);
                    // kludge: don't permit placing more than one tube per tick
                    // causes BE cache problems - root cause to be determined
                    workTimer = 19;
                    addAir(-airRequired);
                } else {
                    status = Status.IDLE;
                    currentDepth--;
                }
            } else {
                status = Status.IDLE;
                currentDepth--;
            }
        }
    } else {
        status = Status.IDLE;
    }
    return status == Status.DIGGING;
}

public static void handle(PacketChestplateLauncher message, IPayloadContext ctx) {
    if (!(ctx.player() instanceof ServerPlayer sp)) return;

    ItemStack stack = sp.getOffhandItem();
    CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(sp);

    // Allows launching if upgrade is active, there is an offhand item, and the item is not on cooldown
    if (handler.upgradeUsable(CommonUpgradeHandlers.chestplateLauncherHandler, false) && !stack.isEmpty()
            && !sp.getCooldowns().isOnCooldown(stack.getItem())) {

        ItemStack toFire = stack;

        // Split stack only for items that are consumed when dispensed (not micromissiles)
        if (!(stack.getItem() == ModItems.MICROMISSILES.get())) {
            toFire = sp.isCreative() ? stack.copyWithCount(1) : stack.split(1);
        }

        Entity launchedEntity = ItemLaunching.getEntityToLaunch(sp.getCommandSenderWorld(), toFire, sp,true, true);
        int upgrades = handler.getUpgradeCount(EquipmentSlot.CHEST, ModUpgrades.DISPENSER.get(), PneumaticValues.PNEUMATIC_LAUNCHER_MAX_UPGRADES);
        Vec3 velocity = sp.getLookAngle().normalize().scale(message.amount() * upgrades * SCALE_FACTOR);

        // Special launch case for arrows/tridents
        if (launchedEntity instanceof AbstractArrow arrow) {
            arrow.pickup = sp.isCreative() ? AbstractArrow.Pickup.CREATIVE_ONLY : AbstractArrow.Pickup.ALLOWED;
            arrow.setBaseDamage(arrow.getBaseDamage() + 0.25 * upgrades * message.amount());
        }

        // Launches item
        ItemLaunching.launchEntity(launchedEntity, sp.getEyePosition(1f).add(0, -0.1, 0), velocity, true);

        // Uses air from chestplate (unless in creative)
        if (!sp.isCreative()) {
            int usedAir = (int) (20 * upgrades * message.amount());
            handler.addAir(EquipmentSlot.CHEST, -usedAir);
        }
    }
}

public void tickServer() {
    super.tickServer();

    if (pressureTube.nonNullLevel().isClientSide || (pressureTube.nonNullLevel().getGameTime() & 0x7) != 0) return;

    getConnectedInventory().ifPresent(itemHandler -> {
        // times 8 because we only run every 8 ticks
        int advMul = pressureTube instanceof AdvancedPressureTubeBlockEntity ? 4 : 1;
        int transferLimit = 8 * PneumaticValues.CHARGING_STATION_CHARGE_RATE * (upgraded ? 10 : 1) * advMul;
        PNCCapabilities.getAirHandler(pressureTube).ifPresent(airHandler -> {
            for (int slot = 0; slot < itemHandler.getSlots(); slot++) {
                ItemStack chargedItem = itemHandler.getStackInSlot(slot);
                if (chargedItem.getCount() != 1) continue;
                PNCCapabilities.getAirHandler(chargedItem).ifPresent(airHandlerItem -> {
                    float itemPressure = airHandlerItem.getPressure();
                    float modulePressure = airHandler.getPressure();
                    float delta = Math.abs(modulePressure - itemPressure) / 2.0F;
                    int airInItem = airHandlerItem.getAir();
                    if (itemPressure > modulePressure + 0.01F && itemPressure > 0F) {
                        // move air from item to charger (tube)
                        int airToMove = Math.min(Math.min(transferLimit, airInItem), (int) (delta * airHandler.getVolume()));
                        airHandlerItem.addAir(-airToMove);
                        airHandler.addAir(airToMove);
                    } else if (itemPressure < modulePressure - 0.01F && itemPressure < airHandlerItem.maxPressure()) {
                        // move air from charger (tube) to item
                        float itemVolume = airHandlerItem.getVolume();
                        int maxAirInItem = (int) (airHandlerItem.maxPressure() * itemVolume);
                        int airToMove = Math.min(Math.min(transferLimit, airHandler.getAir()), (int) (delta * itemVolume));
                        airToMove = Math.min(maxAirInItem - airInItem, airToMove);
                        airHandlerItem.addAir(airToMove);
                        airHandler.addAir(-airToMove);
                    }
                });
            }
        });
    });
}

