public AbilityUseResult hitEntity(ItemStack itemStack, Player player, LivingEntity target, double damageMultiplier, double damageBonus,
        float knockbackBase, float knockbackMultiplier) {
    float targetModifier = EnchantmentHelper.getDamageBonus(itemStack, target.getMobType());
    float critMultiplier = Optional.ofNullable(ForgeHooks.getCriticalHit(player, target, false, 1.5f))
            .map(CriticalHitEvent::getDamageModifier)
            .orElse(1f);

    double damage = (1 + getAbilityBaseDamage(player, itemStack) + targetModifier) * critMultiplier * damageMultiplier + damageBonus;

    boolean success = target.hurt(player.damageSources().playerAttack(player), (float) damage);
    if (success) {
        // applies enchantment effects on both parties
        EnchantmentHelper.doPostHurtEffects(target, player);
        EffectHelper.applyEnchantmentHitEffects(itemStack, target, player);

        // tetra item effects
        ItemEffectHandler.applyHitEffects(itemStack, target, player);

        // knocks back the target based on effect level + knockback enchantment level
        float knockbackFactor = knockbackBase + EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack);
        target.knockback(knockbackFactor * knockbackMultiplier,
                player.getX() - target.getX(), player.getZ() - target.getZ());

        if (targetModifier > 1) {
            player.magicCrit(target);
            return AbilityUseResult.magicCrit;
        }

        if (critMultiplier > 1) {
            player.crit(target);
            return AbilityUseResult.crit;
        }

        return AbilityUseResult.hit;
    }

    return AbilityUseResult.fail;
}

public static void PotionRemoveEvents(MobEffectEvent.Remove event){
    LivingEntity effected = event.getEntity();
    if (effected != null) {
        if (event.getEffect() != null) {
            if (effected.hasEffect(GoetyEffects.SAVE_EFFECTS.get())) {
                event.setCanceled(event.getEffect() != GoetyEffects.SAVE_EFFECTS.get()
                        && (effected instanceof Player player
                        && SEHelper.hasEndWalk(player)
                        && event.getEffect() != GoetyEffects.SHADOW_WALK.get()));
            }
            if (event.getEffect() != null) {
                if (event.getEffect() == GoetyEffects.SHADOW_WALK.get()) {
                    if (effected instanceof Player player) {
                        teleportShadowWalk(player);
                    }
                }
            }
            if (event.getEffect() == GoetyEffects.WILD_RAGE.get()){
                if (effected instanceof Mob mob) {
                    mob.setTarget(null);
                    mob.setLastHurtByMob(null);
                    mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                    mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                }
            }
            if (event.getEffect() == GoetyEffects.VOID_TOUCHED.get()){
                if (effected.level instanceof ServerLevel) {
                    ModNetwork.sentToTrackingEntityAndPlayer(effected, new SPlayWorldSoundPacket(effected.blockPosition(), ModSounds.VOID_TOUCHED_DEACTIVATE.get(), 1.0F, 1.0F));
                }
            }
            if (event.getEffect() == GoetyEffects.ENCHANTED.get()) {
                if (effected.level instanceof ServerLevel) {
                    MiscCapHelper.setEnchanter(effected, null);
                }
            }
        }
    }
}

public InteractionResult interactLivingEntity(ItemStack stack, Player player, LivingEntity target, InteractionHand hand) {
    Level level = player.getCommandSenderWorld();
    if (!level.isClientSide) {
        if (target instanceof AbstractVillager villager && !villager.isBaby() && !villager.getType().is(ModTags.EntityTypes.UNSHACKLEABLE)) {
            Prisoner prisoner = ServantUtil.takePrisoner(villager);
            if (prisoner != null) {
                prisoner.setTrueOwner(player);
                for (Mob mob : level.getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(16.0D))) {
                    if (mob instanceof Villager villager1) {
                        Brain<?> brain = villager1.getBrain();
                        Player player1 = brain.getMemory(MemoryModuleType.NEAREST_VISIBLE_PLAYER).orElse(null);
                        if (player1 != null && player1 == player) {
                            if (villager1.getPlayerReputation(player) > -200) {
                                villager1.getGossips().add(player.getUUID(), GossipType.MAJOR_NEGATIVE, 25);
                            }
                        }
                    }
                    if (mob.getType().is(ModTags.EntityTypes.VILLAGE_GUARDS)) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(player) && !MobUtil.areAllies(mob, player)) {
                            if (mob instanceof IronGolem ironGolem) {
                                if (!ironGolem.isPlayerCreated()) {
                                    ironGolem.setTarget(player);
                                }
                            } else {
                                mob.setTarget(player);
                            }
                        }
                    }
                }
                prisoner.setItemInHand(InteractionHand.OFF_HAND, new ItemStack(ModItems.OMINOUS_SHACKLES.get()));
                prisoner.setDropChance(EquipmentSlot.OFFHAND, 0.0F);
                stack.shrink(1);
                return InteractionResult.SUCCESS;
            }
        }
    }
    return super.interactLivingEntity(stack, player, target, hand);
}

public @NotNull InteractionResultHolder<ItemStack> use(@NotNull Level p_43225_, Player p_43226_, @NotNull InteractionHand p_43227_) {
    ItemStack itemstack = p_43226_.getItemInHand(p_43227_);
    BlockHitResult blockhitresult = getPlayerPOVHitResult(p_43225_, p_43226_, ClipContext.Fluid.SOURCE_ONLY);
    if (blockhitresult.getType() != HitResult.Type.BLOCK) {
        return InteractionResultHolder.pass(itemstack);
    } else if (!(p_43225_ instanceof ServerLevel serverLevel)) {
        return InteractionResultHolder.success(itemstack);
    } else {
        BlockPos blockpos = blockhitresult.getBlockPos();
        if (!(p_43225_.getBlockState(blockpos).getBlock() instanceof LiquidBlock)) {
            return InteractionResultHolder.pass(itemstack);
        } else if (p_43225_.mayInteract(p_43226_, blockpos) && p_43226_.mayUseItemAt(blockpos, blockhitresult.getDirection(), itemstack)) {
            EntityType<?> entitytype = this.getType(itemstack.getTag());
            Entity entity = entitytype.spawn(serverLevel, itemstack, p_43226_, blockpos, MobSpawnType.SPAWN_EGG, false, false);
            if (entity == null) {
                return InteractionResultHolder.pass(itemstack);
            } else {
                if (entity instanceof IOwned owned && !owned.isHostile()){
                    if (p_43226_.isCrouching()){
                        owned.setTrueOwner(p_43226_);
                        if (owned instanceof Mob mob){
                            ForgeEventFactory.onFinalizeSpawn(mob, serverLevel, serverLevel.getCurrentDifficultyAt(mob.blockPosition()), MobSpawnType.SPAWN_EGG, null, itemstack.getTag());
                        }
                    }
                }
                if (!p_43226_.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }

                p_43226_.awardStat(Stats.ITEM_USED.get(this));
                p_43225_.gameEvent(p_43226_, GameEvent.ENTITY_PLACE, entity.position());
                return InteractionResultHolder.consume(itemstack);
            }
        } else {
            return InteractionResultHolder.fail(itemstack);
        }
    }
}

public boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos) {
    if (!level.isClientSide) {
        if (level.getBlockState(blockPos).is(Blocks.MOSS_BLOCK)) {
            if (level.getBlockState(blockPos.offset(MOSS)).is(Blocks.MOSS_BLOCK)
                    && level.getBlockState(blockPos.offset(LEAVES)).is(ModBlocks.OVERGROWN_ROOTS.get())
                    && level.getBlockState(blockPos.offset(CORPSE_BLOSSOM)).is(ModBlocks.CORPSE_BLOSSOM.get())) {
                if (conditionsMet(level, player)) {
                    if (SEHelper.hasResearch(player, ResearchList.FLORAL)) {
                        Whisperer whisperer = ModEntityType.WHISPERER.get().create(level);
                        if (level.getBlockState(blockPos.offset(CORPSE_BLOSSOM)).getValue(CorpseBlossomBlock.WATERLOGGED)) {
                            whisperer = ModEntityType.WAVEWHISPERER.get().create(level);
                        }
                        if (whisperer != null) {
                            whisperer.setTrueOwner(player);
                            whisperer.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(whisperer.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                            whisperer.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.below().getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                            if (level.addFreshEntity(whisperer)) {
                                removeBlocks(level, blockPos);
                                stack.shrink(1);
                                if (player instanceof ServerPlayer serverPlayer) {
                                    CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, whisperer);
                                }
                                return true;
                            }
                        }
                    } else {
                        player.displayClientMessage(Component.translatable("info.goety.research.fail"), true);
                    }
                } else {
                    player.displayClientMessage(Component.translatable("info.goety.summon.limit"), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.block.fail"), true);
            }
        }
    }
    return false;
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float potency = spellStat.getPotency();
    int range = spellStat.getRange();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)) {
        potency += WandUtil.getPotencyLevel(caster) / 2.0F;
        range += WandUtil.getRangeLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    HitResult hitResult = this.rayTrace(worldIn, caster, range, 3);
    Entity target = this.getTarget(caster, range);
    int lifespan = 0;
    double y = 0;
    Vec3 vec3 = null;
    if (target != null){
        lifespan = (int) (Math.floor(caster.distanceTo(target))) + 10;
        vec3 = target.position().subtract(caster.position());
        y = target.getY();
    } else if (hitResult instanceof BlockHitResult result) {
        BlockPos blockPos = result.getBlockPos();
        Vec3 vec30 = Vec3.atCenterOf(blockPos);
        lifespan = (int) (Math.floor(Mth.sqrt((float) caster.distanceToSqr(vec30)))) + 10;
        vec3 = vec30.subtract(caster.position());
        y = blockPos.getY() + 1.0D;
    }
    int h = this.rightStaff(staff) ? 1 : 0;
    if (vec3 != null) {
        for (int i = -h; i <= h; i++) {
            TidalSurge tidalSurge = new TidalSurge(worldIn, caster);
            tidalSurge.setPos(caster.getX(), y, caster.getZ());
            tidalSurge.setLifespan(lifespan + duration);
            tidalSurge.setWaveScale(tidalSurge.getWaveScale() + (potency / 2.0F));
            tidalSurge.setYRot(-(float) (Mth.atan2(vec3.x, vec3.z) * (double) (180F / (float) Math.PI)) + (i * 10));
            worldIn.addFreshEntity(tidalSurge);
        }
    }
    worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), SoundEvents.PLAYER_SPLASH_HIGH_SPEED, this.getSoundSource(), 1.0F, 1.0F);
}

public void useSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, int castTime, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    double radius = spellStat.getRadius();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
    }
    if (castTime >= 20) {
        int amount = this.rightStaff(staff) ? 2 : 1;
        for (int i = 0; i < amount; ++i) {
            BlockPos blockPos = caster.blockPosition();
            LivingEntity target = this.getTarget(caster);
            if (castTime < 40 && target != null) {
                blockPos = target.blockPosition();
            }
            BlockPos blockPos1 = blockPos.offset(worldIn.getRandom().nextInt(-16, 16), 0, worldIn.getRandom().nextInt(-16, 16));
            BlockPos blockPos2 = blockPos.offset(worldIn.getRandom().nextInt(-16, 16), 0, worldIn.getRandom().nextInt(-16, 16));
            Vec3 vec3 = Vec3.atBottomCenterOf(blockPos1);
            Vec3 vec32 = Vec3.atBottomCenterOf(blockPos2);
            MagicLightningTrap trap = new MagicLightningTrap(worldIn, vec3.x, vec3.y, vec3.z);
            if (this.typeStaff(staff, SpellType.VOID)) {
                trap = new VoidLightningTrap(worldIn, vec3.x, vec3.y, vec3.z);
            } else if (staff.is(ModItems.NAMELESS_STAFF.get())) {
                trap.setColor(0xa7fc3e);
            }
            trap.setOwner(caster);
            trap.setDuration(40);
            trap.setDamage(trap.getDamage() + potency);
            trap.setRadius((float) (trap.radius() + (radius / 2.0F)));
            if (!worldIn.getEntitiesOfClass(MagicLightningTrap.class, new AABB(blockPos1)).isEmpty()) {
                trap.setPos(vec32.x(), vec32.y(), vec32.z());
            }
            MobUtil.moveDownToGround(trap);
            worldIn.addFreshEntity(trap);
        }
    }
    super.useSpell(worldIn, caster, staff, castTime, spellStat);
}

public void updateNaturalArmor(int lvl) {
    AttributeInstance armorAtt = player.getAttribute(Attributes.ARMOR);
    AttributeInstance toughnessAtt = player.getAttribute(Attributes.ARMOR_TOUGHNESS);
    if (armorAtt != null && toughnessAtt != null) {
        if (lvl == 0) {
            armorAtt.removeModifier(NATURAL_ARMOR_UUID);
            toughnessAtt.removeModifier(NATURAL_ARMOR_UUID);
        } else {
            AttributeModifier modArmor = armorAtt.getModifier(NATURAL_ARMOR_UUID);
            AttributeModifier modToughness = toughnessAtt.getModifier(NATURAL_ARMOR_UUID);
            double naturalArmor = getNaturalArmorValue(lvl);
            MobEffectInstance armorRegen = player.getEffect(ModEffects.ARMOR_REGENERATION);
            double armorRegenerationMod = armorRegen == null ? 0 : armorRegen.getDuration() / ((double) ModConfig.balance().vpNaturalArmorRegenDuration.get() * 20);
            naturalArmor *= (1 - 0.75 * armorRegenerationMod); //Modify natural armor between 25% and 100% depending on the armor regen state
            double naturalToughness = getNaturalArmorToughnessValue(lvl);
            double baseArmor = armorAtt.invokeGetModifiersOrEmpty(AttributeModifier.Operation.ADD_VALUE).stream().filter(pair -> ArmorModifier.ARMOR_IDS.contains(pair.id())).map(AttributeModifier::amount).mapToDouble(Double::doubleValue).sum();
            double baseToughness = toughnessAtt.invokeGetModifiersOrEmpty(AttributeModifier.Operation.ADD_VALUE).stream().filter(m -> ArmorModifier.ARMOR_IDS.contains(m.id())).map(AttributeModifier::amount).mapToDouble(Double::doubleValue).sum();
            double targetArmor = Math.max(0, naturalArmor - baseArmor);
            double targetToughness = Math.max(0, naturalToughness - baseToughness);
            if (modArmor != null && targetArmor != modArmor.amount()) {
                armorAtt.removeModifier(modArmor);
                modArmor = null;
            }
            if (targetArmor != 0 && modArmor == null) {
                armorAtt.addTransientModifier(new AttributeModifier(NATURAL_ARMOR_UUID, targetArmor, AttributeModifier.Operation.ADD_VALUE));
            }
            if (modToughness != null && targetToughness != modToughness.amount()) {
                toughnessAtt.removeModifier(modToughness);
                modToughness = null;
            }
            if (targetToughness != 0 && modToughness == null) {
                toughnessAtt.addTransientModifier(new AttributeModifier(NATURAL_ARMOR_UUID, targetToughness, AttributeModifier.Operation.ADD_VALUE));
            }
            applyLevelModifiersB(lvl, ModConfig.balance().vpArmorPenalty.get() && baseArmor > 7);

        }
    }
}

    public void tickServer() {
        airPerTick = getBaseProduction() * getSpeedMultiplierFromUpgrades() * getHeatEfficiency() / 100F;

        if (rsController.shouldRun() && burnTime < curFuelUsage) {
            ItemStack fuelStack = itemHandler.getStackInSlot(FUEL_SLOT);
            int itemBurnTime = fuelStack.getBurnTime(RecipeType.SMELTING);
//            int itemBurnTime = CommonHooks.getBurnTime(fuelStack, RecipeType.SMELTING);
            if (itemBurnTime > 0) {
                burnTime += itemBurnTime;
                maxBurnTime = burnTime;
                if (fuelStack.hasCraftingRemainingItem()) {
                    itemHandler.setStackInSlot(FUEL_SLOT, fuelStack.getCraftingRemainingItem());
                } else {
                    itemHandler.extractItem(FUEL_SLOT, 1, false);
                }
            }
        }

        curFuelUsage = (int) (getBaseProduction() * getSpeedUsageMultiplierFromUpgrades() / 10);
        if (burnTime >= curFuelUsage) {
            burnTime -= curFuelUsage;
            airBuffer += airPerTick;
            if (airBuffer >= 1f) {
                int toAdd = (int) airBuffer;
                addAir(toAdd);
                airBuffer -= toAdd;
                addHeatForAir(toAdd);
            }
        }
        boolean newIsActive = burnTime > curFuelUsage;
        if (isActive() != newIsActive) {
            BlockState state = getBlockState();
            if (state.hasProperty(PNCBlockStateProperties.ON)) {
                nonNullLevel().setBlockAndUpdate(getBlockPos(), state.setValue(PNCBlockStateProperties.ON, newIsActive));
            }
        }
        airHandler.setSideLeaking(hasNoConnectedAirHandlers() ? getRotation() : null);
    }

public void tickServer() {
    inputDir = getInputDirection();

    if (firstTick) {
        isCreative = getUpgrades(ModUpgrades.CREATIVE.get()) > 0;
        setupInputOutputRegions();
        firstTick = false;
    }

    super.tickServer();

    if (getRedstoneController().shouldRun()) {
        if (--entityScanCooldown <= 0) {
            cachedInputEntities.clear();
            if (shouldScanForEntities(inputDir)) {
                cachedInputEntities.addAll(nonNullLevel().getEntitiesOfClass(Entity.class, inputAABB, EntitySelector.ENTITY_STILL_ALIVE));
            }
            cachedOutputEntities.clear();
            if (shouldScanForEntities(getRotation())) {
                cachedOutputEntities.addAll(nonNullLevel().getEntitiesOfClass(Entity.class, outputAABB, EntitySelector.ENTITY_STILL_ALIVE));
            }
            entityScanCooldown = BASE_TICK_RATE;
        }

        if (--cooldown <= 0) {
            int maxItems = getMaxItems();
            boolean success = doImport(maxItems);
            success |= doExport(maxItems);

            // If we couldn't pull or push, slow down a bit for performance reasons
            cooldown = success ? getItemTransferInterval() : BASE_TICK_RATE;

            if (lastComparatorValue != getComparatorValueInternal()) {
                lastComparatorValue = getComparatorValueInternal();
            }
        }
    }
}

