public boolean canUse() {
    if (orbitResetCooldown < 0) {
        orbitResetCooldown++;
    }
    if ((pterodaustro.getTarget() != null && pterodaustro.getTarget().isAlive() && !this.pterodaustro.isVehicle()) || this.pterodaustro.isPassenger()) {
        return false;
    } else {
        if (this.pterodaustro.getRandom().nextInt(15) != 0 && !pterodaustro.isFlying()) {
            return false;
        }
        if (this.pterodaustro.isBaby()) {
            this.flightTarget = false;
        } else if (this.pterodaustro.isInWaterOrBubble()) {
            this.flightTarget = true;
        } else if (this.pterodaustro.onGround()) {
            this.flightTarget = pterodaustro.getRandom().nextBoolean();
        } else {
            if (orbitResetCooldown == 0 && pterodaustro.getRandom().nextInt(6) == 0) {
                orbitResetCooldown = 400;
                pterodaustro.orbitPos = pterodaustro.blockPosition();
                pterodaustro.orbitDist = 4 + pterodaustro.getRandom().nextInt(5);
                pterodaustro.orbitClockwise = pterodaustro.getRandom().nextBoolean();
                orbitTime = 0;
                maxOrbitTime = (int) (360 + 360 * pterodaustro.getRandom().nextFloat());
            }
            this.flightTarget = pterodaustro.isVehicle() || pterodaustro.getRandom().nextInt(7) > 0 && pterodaustro.timeFlying < 700;
        }
        Vec3 lvt_1_1_ = this.getPosition();
        if (lvt_1_1_ == null) {
            return false;
        } else {
            this.x = lvt_1_1_.x;
            this.y = lvt_1_1_.y;
            this.z = lvt_1_1_.z;
            return true;
        }
    }
}

public void tick() {
    super.tick();
    if (soundTimer > 0) {
        soundTimer--;
    }
    this.prevFeedProgress = feedProgress;
    if (this.getFeedingTime() > 0 && feedProgress < 5F) {
        feedProgress++;
    }
    if (this.getFeedingTime() <= 0 && feedProgress > 0F) {
        feedProgress--;
    }
    BlockPos feedingPos = this.entityData.get(FEEDING_POS).orElse(null);
    if (feedingPos == null) {
        float f2 = (float) -((float) this.getDeltaMovement().y * 2.2F * (double) (180F / (float) Math.PI));
        this.setXRot(f2);
    } else if (this.getFeedingTime() > 0) {
        Vec3 face = Vec3.atCenterOf(feedingPos).subtract(this.position());
        double d0 = face.horizontalDistance();
        this.setXRot((float) (-Mth.atan2(face.y, d0) * (double) (180F / (float) Math.PI)));
        this.setYRot(((float) Mth.atan2(face.z, face.x)) * (180F / (float) Math.PI) - 90F);
        this.yBodyRot = this.getYRot();
        this.yHeadRot = this.getYRot();
        BlockState state = level().getBlockState(feedingPos);
        if (random.nextInt(2) == 0 && !state.isAir()) {
            Vec3 mouth = new Vec3(0, this.getBbHeight() * 0.5F, 0.4F * -0.5).xRot(this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYRot() * ((float) Math.PI / 180F));
            for (int i = 0; i < 4 + random.nextInt(2); i++) {
                double motX = this.random.nextGaussian() * 0.02D;
                double motY = 0.1F + random.nextFloat() * 0.2F;
                double motZ = this.random.nextGaussian() * 0.02D;
                level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, state), this.getX() + mouth.x, this.getY() + mouth.y, this.getZ() + mouth.z, motX, motY, motZ);
            }
        }
    }
    if (rideCooldown > 0) {
        rideCooldown--;
    }
}

public void tick(){
    super.tick();
    this.prevSprayProgress = sprayProgress;
    if(this.getSprayTime() > 0){
        if(this.sprayProgress < 5F){
            this.sprayProgress++;
        }

        this.setSprayTime(this.getSprayTime() - 1);
        if(this.getSprayTime() == 0){
            spawnLingeringCloud();
        }else if(this.getSprayTime() % 6 == 0){
            this.playSound(AMSoundRegistry.SKUNK_SPRAY.get());
        }
        this.yBodyRot = this.getYRot();
        this.setYRot(approachRotation(this.getSprayYaw(), this.getYRot() + 10, 15F));
    }
    if(this.getSprayTime() <= 0 && this.sprayProgress > 0F){
        this.sprayProgress--;
    }
    if(!this.level().isClientSide){
        if(harassedTime > 200 && sprayCooldown == 0 && !this.isBaby()){
            harassedTime = 0;
            sprayCooldown = 200 + random.nextInt(200);
            this.setSprayTime(60 + random.nextInt(60));
        }
        if(harassedTime > 0){
            harassedTime--;
        }
        if(sprayCooldown > 0){
            sprayCooldown--;
        }
        Entity lastHurt = this.getLastHurtByMob();
        if(lastHurt != null){
            this.sprayAt = lastHurt.position();
        }
    }
    prevSprayTime = this.getSprayTime();
}

public void tick() {
    if (targetPos != null && waterPos != null) {
        double dist = this.raccoon.distanceToSqr(Vec3.atCenterOf(waterPos));
        if (dist > 2 && this.raccoon.isWashing()) {
            this.raccoon.setWashing(false);
        }
        if (dist <= 1F) {
            double d0 = waterPos.getX() + 0.5D - this.raccoon.getX();
            double d2 = waterPos.getZ() + 0.5D - this.raccoon.getZ();
            float yaw = (float)(Mth.atan2(d2, d0) * (double)Mth.RAD_TO_DEG) - 90.0F;
            this.raccoon.setYRot(yaw);
            this.raccoon.yHeadRot = yaw;
            this.raccoon.yBodyRot = yaw;
            this.raccoon.getNavigation().stop();
            this.raccoon.setWashing(true);
            this.raccoon.setWashPos(waterPos);
            this.raccoon.lookForWaterBeforeEatingTimer = 0;
            if(washTime % 10 == 0){
                this.raccoon.gameEvent(GameEvent.BLOCK_ACTIVATE);
                this.raccoon.playSound(SoundEvents.GENERIC_SWIM, 0.7F, 0.5F + raccoon.getRandom().nextFloat());
            }
            washTime++;
            if(washTime > 100 || raccoon.isHoldingSugar() && washTime > 20){
                this.stop();
                if(!raccoon.isHoldingSugar()){
                    raccoon.onEatItem();
                }
                this.raccoon.postWashItem(raccoon.getMainHandItem());
                if(this.raccoon.getMainHandItem().hasCraftingRemainingItem()){
                    this.raccoon.spawnAtLocation(this.raccoon.getMainHandItem().getCraftingRemainingItem());
                }
                this.raccoon.getMainHandItem().shrink(1);
            }
        }else{
            this.raccoon.getNavigation().moveTo(waterPos.getX(), waterPos.getY(), waterPos.getZ(), 1.2D);
        }

    }
}

public void tick() {
    this.temptedEntity.getLookControl().setLookAt(this.temptingPlayer, this.temptedEntity.getMaxHeadYRot() + 20, this.temptedEntity.getMaxHeadXRot());
    ArrayList<Integer> slotlist = new ArrayList<>();
    if (this.temptedEntity.distanceToSqr(this.temptingPlayer) < 3D && !this.temptingPlayer.getInventory().isEmpty()) {

        for (int i = 0; i < this.temptingPlayer.getInventory().getContainerSize(); i++) {
            ItemStack targetStack = this.temptingPlayer.getInventory().getItem(i);
            if (!Inventory.isHotbarSlot(i) && !targetStack.isEmpty() && targetStack.isStackable()) {
                slotlist.add(i);
            }
        }
        if (!slotlist.isEmpty()) {
            final int slot;
            if (slotlist.size() == 1) {
                slot = slotlist.get(0);
            } else {
                slot = slotlist.get(ThreadLocalRandom.current().nextInt(slotlist.size()));
            }
            ItemStack randomItem = this.temptingPlayer.getInventory().getItem(slot);
            this.temptedEntity.setItemInHand(InteractionHand.MAIN_HAND, randomItem);
            this.temptingPlayer.getInventory().removeItemNoUpdate(slot);
            this.temptedEntity.flipAI(true);
            this.temptedEntity.playSound(IafSoundRegistry.PIXIE_TAUNT, 1F, 1F);

            for (EntityPixie pixie : this.temptingPlayer.level.getEntitiesOfClass(EntityPixie.class, temptedEntity.getBoundingBox().inflate(40))) {
                pixie.stealCooldown = 1000 + pixie.getRandom().nextInt(3000);
            }
            if (temptingPlayer != null) {
                this.temptingPlayer.addEffect(new MobEffectInstance(this.temptedEntity.negativePotions[this.temptedEntity.getColor()], 100));
            }
        } else {
            //If the pixie couldn't steal anything
            this.temptedEntity.flipAI(true);
            this.delayTemptCounter = 10 *20;
        }
    } else {
        this.temptedEntity.getMoveControl().setWantedPosition(this.temptingPlayer.getX(), this.temptingPlayer.getY() + 1.5F, this.temptingPlayer.getZ(), 1D);
    }
}

public InteractionResult useOn(UseOnContext context) {
  Player player = context.getPlayer();
  //
  ItemStack stack = context.getItemInHand();
  BlockPos pos = context.getClickedPos();
  Direction direction = context.getClickedFace();
  if (direction == null) {
    return super.useOn(context);
  }
  Level worldObj = context.getLevel();
  //    boolean showOdds = player.isSneaking();
  boolean found = false;
  //    if (!worldObj.isRemote) {
  BlockPos current = pos;
  for (int i = 1; i <= RANGE; i++) {
    current = current.relative(direction.getOpposite());
    if (context.getLevel().isEmptyBlock(current)) {
      ChatUtil.addChatMessage(player, ChatUtil.lang("tool.spelunker.cave") + i);
      found = true;
    }
    else if (worldObj.getBlockState(current) == Blocks.WATER.defaultBlockState()) {
      ChatUtil.addChatMessage(player, ChatUtil.lang("tool.spelunker.water") + i);
      found = true;
    }
    else if (worldObj.getBlockState(current) == Blocks.LAVA.defaultBlockState()) {
      ChatUtil.addChatMessage(player, ChatUtil.lang("tool.spelunker.lava") + i);
      found = true;
    }
    if (found) {
      break;
    }
  }
  if (found == false) {
    ChatUtil.addChatMessage(player, ChatUtil.lang("tool.spelunker.none") + RANGE);
  }
  ItemStackUtil.damageItem(player, stack);
  EntityUtil.setCooldownItem(player, this, COOLDOWN);
  return super.useOn(context);
}

public static boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos) {
    BlockState blockState = level.getBlockState(blockPos);
    if (!level.isClientSide) {
        Summoned summoned = null;
        if (blockState.is(Blocks.SLIME_BLOCK)) {
            summoned = ModEntityType.SLIME_SERVANT.get().create(level);
            if (surroundedWater(level, blockPos)){
                summoned = ModEntityType.TROPICAL_SLIME_SERVANT.get().create(level);
            } else if (BlockFinder.findStructure(level, blockPos, ModStructures.CRYPT_KEY)){
                summoned = ModEntityType.CRYPT_SLIME_SERVANT.get().create(level);
            }
        } else if (blockState.is(Blocks.MAGMA_BLOCK)){
            summoned = ModEntityType.MAGMA_CUBE_SERVANT.get().create(level);
        }
        if (summoned != null){
            if (conditionsMet(level, player)){
                summoned.setTrueOwner(player);
                summoned.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(summoned.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                summoned.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                if (summoned instanceof SlimeServant slime) {
                    slime.setSize(2, true);
                }
                if (level.addFreshEntity(summoned)) {
                    level.levelEvent(2001, blockPos, Block.getId(level.getBlockState(blockPos)));
                    level.setBlockAndUpdate(blockPos, Blocks.AIR.defaultBlockState());
                    stack.shrink(1);
                    if (player instanceof ServerPlayer serverPlayer) {
                        CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, summoned);
                    }
                    return true;
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.summon.limit"), true);
                summoned.discard();
            }
        }
    }
    return false;
}

