public void deserialize(@NotNull ValueInput input) {
    var faction = input.read("faction", ModCodecs.playableFaction());
    if (faction.isEmpty()) {
        this.maxMinions = 0;
        return;
    }

    this.faction = faction.get();
    this.maxMinions = input.getIntOr("max_minions", 0);

    Map<Integer, MinionInfo> infos = new HashMap<>();
    Map<Integer, Optional<Integer>> tokens = new HashMap<>();

    for (ValueInput data : input.childrenListOrEmpty("data")) {
        Optional<Integer> idOpt = data.getInt("id");
        if (idOpt.isEmpty()) {
            continue;
        }

        int id = idOpt.get();

        MinionData minionData = MinionData.fromNBT(data.childOrEmpty("content"));
        if (minionData == null) {
            continue;
        }

        EntityType<? extends MinionEntity<?>> type = data.read("entity_type", ModCodecs.<MinionEntity<?>>entityCodec()).orElse(null);

        MinionInfo minionInfo = new MinionInfo(id, minionData, type);
        minionInfo.deathCooldown = data.getIntOr("death_timer", 0);

        infos.put(id, minionInfo);
        tokens.put(id, data.getInt("token").or(Optional::empty));
    }

    this.minions = infos.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(Map.Entry::getValue).toArray(MinionInfo[]::new);
    this.minionTokens = (Optional<Integer>[]) tokens.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(Map.Entry::getValue).toArray(Optional[]::new);

}

public boolean doHurtTarget(ServerLevel serverLevel, Entity toAttack) {
	if (toAttack instanceof LivingEntity living && living.isBlocking()) {
		if (this.getMovementPattern().getState() == NagaMovementPattern.MovementState.CHARGE) {
			Vec3 motion = this.getDeltaMovement();
			toAttack.push(motion.x() * 1.5D, 0.5D, motion.z() * 1.5D);
			this.push(motion.x() * -1.25D, 0.5D, motion.z() * -1.25D);
			if (toAttack instanceof ServerPlayer player) {
				player.getUseItem().hurtAndBreak(5, player, player.getUsedItemHand());
				PacketDistributor.sendToPlayer(player, new MovePlayerPacket(motion.x() * 3.0D, motion.y() + 0.75D, motion.z() * 3.0D));
			}
			this.hurt(this.damageSources().generic(), 2.0F);
			this.level().playSound(null, toAttack.blockPosition(), SoundEvents.SHIELD_BLOCK.value(), SoundSource.PLAYERS, 1.0F, 0.8F + this.level().getRandom().nextFloat() * 0.4F);
			this.getMovementPattern().doDaze();
			return false;
		} else if (this.getMovementPattern().getState() == NagaMovementPattern.MovementState.STUNLESS_CHARGE) {
			if (toAttack instanceof ServerPlayer player) {
				player.getUseItem().hurtAndBreak(10, player, player.getUsedItemHand());
				player.getCooldowns().addCooldown(player.getUseItem(), 200);
				player.stopUsingItem();
				this.level().broadcastEntityEvent(player, (byte) 30);
			}
			living.hurt(this.damageSources().mobAttack(this), 4.0F);
			this.playSound(SoundEvents.FOX_BITE, 2.0F, 0.5F);
			this.getMovementPattern().doCircle();
			return false;
		}
	}
	if (!this.isDazed()) {
		boolean result = super.doHurtTarget(serverLevel, toAttack);

		if (result) {
			// charging, apply extra pushback
			toAttack.push(-Mth.sin((getYRot() * Mth.PI) / 180.0F) * 2.0F, 0.4F, Mth.cos((getYRot() * Mth.PI) / 180.0F) * 2.0F);
		}

		return result;
	}
	return false;
}

public void tick() {
	super.tick();
	if (!this.level().isClientSide()) {

		if (!this.hasRock() && this.getTarget() != null) {
			if (this.rockCooldown > 0) {
				this.rockCooldown--;
			} else {
				//copied from EnderMan.EndermanTakeBlockGoal.tick()
				RandomSource random = this.getRandom();
				Level level = this.level();
				int i = Mth.floor(this.getX() - 2.0D + random.nextDouble() * 4.0D);
				int j = Mth.floor(this.getY() + random.nextDouble() * 3.0D);
				int k = Mth.floor(this.getZ() - 2.0D + random.nextDouble() * 4.0D);
				BlockPos blockpos = new BlockPos(i, j, k);
				BlockState blockstate = level.getBlockState(blockpos);
				Vec3 vec3 = new Vec3((double) this.getBlockX() + 0.5D, (double) j + 0.5D, (double) this.getBlockZ() + 0.5D);
				Vec3 vec31 = new Vec3((double) i + 0.5D, (double) j + 0.5D, (double) k + 0.5D);
				BlockHitResult blockhitresult = level.clip(new ClipContext(vec3, vec31, ClipContext.Block.OUTLINE, ClipContext.Fluid.NONE, this));
				boolean flag = blockhitresult.getBlockPos().equals(blockpos);
				if (blockstate.is(BlockTags.BASE_STONE_OVERWORLD) && flag) {
					this.rock = level.getBlockState(blockpos);
					level.removeBlock(blockpos, false);
					level.gameEvent(this, GameEvent.BLOCK_DESTROY, blockpos);
				}

				if (this.rock != null) {
					this.setHasRock(true);
					this.playSound(TFSounds.TROLL_GRABS_ROCK.get());
					ThrownBlock block = new ThrownBlock(level, this.rock);
					block.setPos(this.getX(), this.getY() + this.getBbHeight(), this.getZ());

					block.startRiding(this, true, false);
					level.addFreshEntity(block);
				}
			}
		}
	}
}

