public void renderWidget(@Nonnull GuiGraphics graphics, int mouseX, int mouseY, float partialTicks) {
	this.active = true;

	if (this.parentGui instanceof InventoryScreen || this.parentGui instanceof CuriosScreen) {
		boolean lastVisible = this.isRecipeBookVisible;

		if (this.parentGui instanceof InventoryScreen) {
			this.isRecipeBookVisible = ((InventoryScreen)this.parentGui).getRecipeBookComponent().isVisible();
		} else if (this.parentGui instanceof CuriosScreen) {
			this.isRecipeBookVisible = ((CuriosScreen)this.parentGui).getRecipeBookComponent().isVisible();
		}

		if (lastVisible != this.isRecipeBookVisible) {
			Tuple<Integer, Integer> offsets = this.getOffsets(false);
			this.setPosition(this.parentGui.getGuiLeft() + offsets.getA(), this.parentGui.getGuiTop() + offsets.getB());
		}
	} else if (this.parentGui instanceof CreativeModeInventoryScreen) {
		CreativeModeInventoryScreen gui = (CreativeModeInventoryScreen) this.parentGui;
		boolean isInventoryTab = gui.selectedTab == BuiltInRegistries.CREATIVE_MODE_TAB
				.getOrThrow(CreativeModeTabs.INVENTORY);

		if (!isInventoryTab) {
			this.active = false;
			return;
		}
	}

	if (this.beforeRender(graphics, mouseX, mouseY, partialTicks)) {
		RenderSystem.setShader(GameRenderer::getPositionTexShader);
		RenderSystem.setShaderTexture(0, this.resourceLocation);
		int i = this.yTexStart;
		if (this.isHoveredOrFocused()) {
			i += this.yDiffTex;
		}

		RenderSystem.enableDepthTest();
		graphics.blit(this.resourceLocation, this.getX(), this.getY(), this.xTexStart, i, this.width, this.height,
				this.textureWidth, this.textureHeight);
	}
}

public boolean canUse() {
    if (orbitResetCooldown < 0) {
        orbitResetCooldown++;
    }
    if ((eagle.getTarget() != null && eagle.getTarget().isAlive() && !this.eagle.isVehicle()) || this.eagle.isPassenger() || this.eagle.isSitting() || eagle.controlledFlag) {
        return false;
    } else {
        if (this.eagle.getRandom().nextInt(15) != 0 && !eagle.isFlying()) {
            return false;
        }
        if (this.eagle.isBaby()) {
            this.flightTarget = false;
        } else if (this.eagle.isInWaterOrBubble()) {
            this.flightTarget = true;
        } else if (this.eagle.hasCap()) {
            this.flightTarget = false;
        } else if (this.eagle.onGround()) {
            this.flightTarget = random.nextBoolean();
        } else {
            if (orbitResetCooldown == 0 && random.nextInt(6) == 0) {
                orbitResetCooldown = 400;
                eagle.orbitPos = eagle.blockPosition();
                eagle.orbitDist = 4 + random.nextInt(5);
                eagle.orbitClockwise = random.nextBoolean();
                orbitTime = 0;
                maxOrbitTime = (int) (360 + 360 * random.nextFloat());
            }
            this.flightTarget = eagle.isVehicle() || random.nextInt(7) > 0 && eagle.timeFlying < 700;
        }
        Vec3 lvt_1_1_ = this.getPosition();
        if (lvt_1_1_ == null) {
            return false;
        } else {
            this.x = lvt_1_1_.x;
            this.y = lvt_1_1_.y;
            this.z = lvt_1_1_.z;
            return true;
        }
    }
}

private void eatHive() {
    if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(anteater.level(), anteater)) {
        BlockState blockstate = anteater.level().getBlockState(this.blockPos);
        if (blockstate.is(AMBlockRegistry.LEAFCUTTER_ANTHILL.get())) {
            if (anteater.level().getBlockEntity(this.blockPos) instanceof TileEntityLeafcutterAnthill) {
                final RandomSource rand = this.anteater.getRandom();
                TileEntityLeafcutterAnthill anthill = (TileEntityLeafcutterAnthill) anteater.level().getBlockEntity(this.blockPos);
                anthill.angerAntsBecauseAnteater(anteater, blockstate, BeehiveBlockEntity.BeeReleaseStatus.EMERGENCY);
                anteater.level().updateNeighbourForOutputSignal(this.blockPos, blockstate.getBlock());
                if(!anthill.hasNoAnts()){
                    BlockState state = anthill.shrinkFungus();
                    if(state != null && state.is(AMBlockRegistry.LEAFCUTTER_ANT_CHAMBER.get()) && state.getValue(BlockLeafcutterAntChamber.FUNGUS) >= 5){
                        ItemStack stack = new ItemStack(AMItemRegistry.GONGYLIDIA.get());
                        ItemEntity itementity = new ItemEntity(anteater.level(), blockPos.getX() + rand.nextFloat(), blockPos.getY() + rand.nextFloat(), blockPos.getZ() + rand.nextFloat(), stack);
                        itementity.setDefaultPickUpDelay();
                        anteater.level().addFreshEntity(itementity);
                    }
                    anteater.setAntOnTongue(true);
                }
            }
        }else if(blockstate.is(AMBlockRegistry.LEAFCUTTER_ANT_CHAMBER.get())){
            anteater.level().destroyBlock(blockPos, false);
            if(blockstate.getValue(BlockLeafcutterAntChamber.FUNGUS) >= 5){
                final RandomSource rand = this.anteater.getRandom();
                ItemStack stack = new ItemStack(AMItemRegistry.GONGYLIDIA.get());
                ItemEntity itementity = new ItemEntity(anteater.level(), blockPos.getX() + rand.nextFloat(), blockPos.getY() + rand.nextFloat(), blockPos.getZ() + rand.nextFloat(), stack);
                itementity.setDefaultPickUpDelay();
                anteater.level().addFreshEntity(itementity);
            }
            anteater.level().setBlockAndUpdate(blockPos, Blocks.COARSE_DIRT.defaultBlockState());
            anteater.setAntOnTongue(true);
        }
        double d0 = 15;
        for (EntityLeafcutterAnt leafcutter : anteater.level().getEntitiesOfClass(EntityLeafcutterAnt.class, new AABB((double) blockPos.getX() - d0, (double) blockPos.getY() - d0, (double) blockPos.getZ() - d0, (double) blockPos.getX() + d0, (double) blockPos.getY() + d0, (double) blockPos.getZ() + d0))) {
            leafcutter.setRemainingPersistentAngerTime(100);
            leafcutter.setTarget(anteater);
            leafcutter.setStayOutOfHiveCountdown(400);
        }
    }
}

public void tick() {
    Entity target = this.entity.getTarget();
    boolean keepFollowing = true;
    if(shootCooldown > 0){
        shootCooldown--;
    }
    if(this.entity.getSensing().hasLineOfSight(target)){
        float dist = this.entity.distanceTo(target);
        if(dist < this.entity.getBbWidth() + target.getBbWidth() + 3.0F){
            keepFollowing = false;
            this.entity.lookAt(target, 360, 360);
            this.entity.getMoveControl().strafe(-3.0F, 0);
            strafed = true;
        }
        if(dist < 8 && shootCooldown == 0){
            EntityMudBall mudball = new EntityMudBall(this.entity.level(), this.entity);
            double d0 = target.getX() - mudball.getX();
            double d1 = target.getY(0.3F) - mudball.getY();
            double d2 = target.getZ() - mudball.getZ();
            float f = Mth.sqrt((float) (d0 * d0 + d2 * d2)) * 0.4F;
            mudball.shoot(d0, d1 + (double) f, d2, 1F, 10.0F);
            if (!this.entity.isSilent()) {
                this.entity.gameEvent(GameEvent.PROJECTILE_SHOOT);
                this.entity.level().playSound(null, this.entity.getX(), this.entity.getY(), this.entity.getZ(), AMSoundRegistry.MUDSKIPPER_SPIT.get(), this.entity.getSoundSource(), 1.0F, 1.0F + (this.entity.getRandom().nextFloat() - this.entity.getRandom().nextFloat()) * 0.2F);
            }
            this.entity.level().addFreshEntity(mudball);
            shootCooldown = 10 + entity.getRandom().nextInt(10);
            this.entity.openMouth(10);
        }
    }
    if(keepFollowing){
        if(strafed){
            this.entity.getMoveControl().strafe(0, 0);
            strafed = false;
        }
        this.entity.getNavigation().moveTo(target, 1.5F);
    }else{
        this.entity.getNavigation().stop();
    }
}

public boolean processInteract(EntityPlayer player, EnumHand hand) {
	ItemStack stack = player.getHeldItem(hand);
	boolean holdsEquipment = hand == EnumHand.MAIN_HAND && !stack.isEmpty() && (stack.getItem() instanceof IEquippable || stack.getItem() == ItemRegistry.AMULET_SLOT);
	if (holdsEquipment)
		return true;
	if (!stack.isEmpty()) {
		if (isTamed()) {
			if ((EnumItemMisc.OCTINE_NUGGET.isItemOf(stack) || stack.getItem() == ItemRegistry.OCTINE_INGOT)) {
				if (getHealth() < getMaxHealth()) {
					if (!getEntityWorld().isRemote) {
						heal(EnumItemMisc.OCTINE_NUGGET.isItemOf(stack) ? 10.0F : getMaxHealth() - getHealth());

						if (!player.capabilities.isCreativeMode) {
							stack.shrink(1);
							if (stack.getCount() <= 0)
								player.setHeldItem(hand, ItemStack.EMPTY);
						}

						if (getHealth() == getMaxHealth()) {
							getEntityWorld().playSound(null, getPosition(), SoundRegistry.EMBERLING_LIVING, SoundCategory.NEUTRAL, 1.0F, 0.75F);
						}
					} else {
						playTameEffect(true);
					}

					return true;
				}
			}
		}
	}

	if (isOwner(player) && !world.isRemote) {
		aiSit.setSitting(!isSitting());
		isJumping = false;
		navigator.clearPath();
		setAttackTarget((EntityLivingBase) null);
	}

	return super.processInteract(player, hand);
}

public boolean processInteract(EntityPlayer player, EnumHand hand) {
	boolean holdsEquipment = hand == EnumHand.MAIN_HAND && !player.getHeldItem(hand).isEmpty() && (player.getHeldItem(hand).getItem() instanceof IEquippable || player.getHeldItem(hand).getItem() == ItemRegistry.AMULET_SLOT);
	if (holdsEquipment)
		return true;
	boolean holdsWings = EnumItemMisc.DRAGONFLY_WING.isItemOf(player.getHeldItem(hand));
	if (!this.isBeingRidden() && this.isTamed() && (!holdsWings || this.getHealth() >= this.getMaxHealth()) && !player.isSneaking() && !this.world.isRemote) {
		player.startRiding(this);
		return true;
	} else if (holdsWings) {
		if (!this.isTamed()) {
			if (!this.world.isRemote) {
				this.temper += this.rand.nextInt(4) + 1;
				if (this.temper >= 30 && !net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, player)) {
					this.world.setEntityState(this, (byte) 7);
					this.setTamedBy(player);
					this.temper = 0;
				} else {
					this.world.setEntityState(this, (byte) 6);
				}
				if (!player.capabilities.isCreativeMode) {
					player.getHeldItem(hand).shrink(1);
					if (player.getHeldItem(hand).getCount() <= 0)
						player.setHeldItem(hand, ItemStack.EMPTY);
				}
			}
			return true;
		}
		if (this.getHealth() < this.getMaxHealth()) {
			if (!this.world.isRemote) {
				this.world.setEntityState(this, (byte) 6);
				this.heal(4.0F);
				player.getHeldItem(hand).shrink(1);
				if (player.getHeldItem(hand).getCount() <= 0)
					player.setHeldItem(hand, ItemStack.EMPTY);
			}
			return true;
		}
	}
	return false;
}

