public boolean hurt(DamageSource source, float amount) {
    if (source.is(DamageTypes.CACTUS) || source.is(DamageTypes.SWEET_BERRY_BUSH) || source.is(DamageTypes.IN_WALL) || source.is(DamageTypes.LAVA) || source.is(DamageTypes.DROWN))
        return false;
    if (source.is(DamageTypes.FREEZE))
        amount = amount / 2;
    if (this.getPhaseSwapping())
        return false;

    Entity entity = source.getEntity();
    if (entity instanceof LivingEntity entity1 && !entity.equals(this)) {
        if (isDefensive() && !source.is(DamageTypes.THORNS)) {
            if (!source.is(DamageTypeTags.BYPASSES_ARMOR) && BlockUtil.distanceFrom(level, entity.position, position) <= 3) {
                entity.hurt(level.damageSources().thorns(this), 6.0f);
            }
        }

        // Omit our summoned sources that might aggro or accidentally hurt us
        if (entity1 instanceof WildenStalker || entity1 instanceof WildenGuardian || entity instanceof WildenHunter
                || entity instanceof ISummon && ((ISummon) entity).getOwnerUUID() != null && ((ISummon) entity).getOwnerUUID().equals(this.getUUID())
                || entity1 instanceof SummonWolf && ((SummonWolf) entity1).isWildenSummon)
            return false;
    }

    if (isDefensive())
        return false;
    var threshold = this.getMaxHealth() / 4;
    var nextMin = this.getMaxHealth() - threshold * (1 + getPhase());
    boolean res = super.hurt(source, amount);
    if (!this.level.isClientSide && this.getHealth() <= nextMin && getPhase() < 3) {
        this.setPhaseSwapping(true);
        this.setPhase(this.getPhase() + 1);
        this.getNavigation().stop();
        this.setHealth(nextMin);
        this.dead = false;
        this.setFlying(false);
        this.setDefensiveMode(false);
        isRamGoal = false;
    }
    return res;
}

public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    int signalModifier = Mth.clamp((int) spellStats.getAmpMultiplier() + 10, 1, 15);
    int timeBonus = (int) spellStats.getDurationMultiplier();
    int delay = Math.max(GENERIC_INT.get() + timeBonus * BONUS_TIME.get(), 2);
    List<BlockPos> posList = SpellUtil.calcAOEBlocks(shooter, rayTraceResult.getBlockPos(), rayTraceResult, spellStats);
    Player fakePlayer = ANFakePlayer.getOrFakePlayer((ServerLevel) world, shooter);
    for (BlockPos pos1 : posList) {
        if (spellStats.isSensitive()) {
            if (!world.isInWorldBounds(pos1))
                return;
            pos1 = pos1.immutable();
            RedstoneSavedData.from((ServerLevel) world).SIGNAL_MAP.put(pos1, new RedstoneSavedData.Entry(pos1, signalModifier, delay));
            world.neighborChanged(pos1, world.getBlockState(pos1).getBlock(), pos1);
            world.updateNeighborsAt(pos1, world.getBlockState(pos1).getBlock());
        } else {

            pos1 = pos1.relative(rayTraceResult.getDirection());

            if (!world.isInWorldBounds(pos1))
                return;
            boolean notReplaceable = !world.getBlockState(pos1).canBeReplaced();
            if (notReplaceable)
                continue;
            var event = NeoForge.EVENT_BUS.post(new BlockEvent.EntityPlaceEvent(BlockSnapshot.create(world.dimension(), world, pos1), world.getBlockState(pos1), fakePlayer));
            if (event.isCanceled()) {
                continue;
            }
            BlockState state1 = BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState().setValue(TemporaryBlock.POWER, signalModifier);
            world.setBlockAndUpdate(pos1, state1);
            if (world.getBlockEntity(pos1) instanceof TemporaryTile tile) {
                tile.gameTime = world.getGameTime();
                tile.tickDuration = delay;
                tile.mimicState = Blocks.REDSTONE_BLOCK.defaultBlockState();
                tile.updateBlock();
            }
            world.sendBlockUpdated(pos1, world.getBlockState(pos1), world.getBlockState(pos1), 2);
        }
    }

}

