                MagnetronEntity.this.getNavigation().moveTo(target, 1);
                if (MagnetronEntity.this.getAttackPose() == AttackPose.NONE && MagnetronEntity.this.getAttackPoseProgress(1.0F) >= 1.0F) {
                    if (trueDist < 5F && punchCooldown <= 0) {
                        AttackPose set = getPoseForHand();
                        MagnetronEntity.this.playSound(ACSoundRegistry.MAGNETRON_ATTACK.get());
                        MagnetronEntity.this.setAttackPose(set);
                        punchCooldown = set == AttackPose.SLAM ? 15 : 10;
                    }
                } else if (trueDist < 7.5F && MagnetronEntity.this.getAttackPoseProgress(1.0F) >= 0.9F) {
                    dealDamage(target, MagnetronEntity.this.getAttackPose());
                }
            }
        }
        MagnetronEntity.this.getNavigation().moveTo(target, 1);
        Vec3 lookDist = target.getEyePosition().subtract(MagnetronEntity.this.getEyePosition());
        float targetXRot = (float) (-(Mth.atan2(lookDist.y, lookDist.horizontalDistance()) * (double) (180F / (float) Math.PI)));
        float targetYRot = (float) (-Mth.atan2(lookDist.x, lookDist.z) * (double) (180F / (float) Math.PI));
        MagnetronEntity.this.setXRot(targetXRot);
        MagnetronEntity.this.setYRot(targetYRot);
    }
    if (MagnetronEntity.this.getAttackPose() != AttackPose.NONE && punchCooldown == 0) {
        MagnetronEntity.this.setAttackPose(AttackPose.NONE);
    }
}

public void customServerAiStep() {
    super.customServerAiStep();

    if (this.currentMoveTypeDuration > 0) {
        --this.currentMoveTypeDuration;
    }

    if (this.onGround()) {
        if (!this.wasOnGround) {
            this.setJumping(false);
            this.checkLandingDelay();
        }

        if (this.currentMoveTypeDuration == 0) {
            LivingEntity livingentity = this.getTarget();
            if (livingentity != null && this.distanceToSqr(livingentity) < 16.0D) {
                this.calculateRotationYaw(livingentity.getX(), livingentity.getZ());
                this.moveControl.setWantedPosition(livingentity.getX(), livingentity.getY(), livingentity.getZ(), this.moveControl.getSpeedModifier());
                this.startJumping();
                this.wasOnGround = true;
            }
        }
        if (this.jumpControl instanceof EntityKangaroo.JumpHelperController) {
            EntityKangaroo.JumpHelperController rabbitController = (EntityKangaroo.JumpHelperController) this.jumpControl;
            if (!rabbitController.getIsJumping()) {
                if (this.moveControl.hasWanted() && this.currentMoveTypeDuration == 0) {
                    Path path = this.navigation.getPath();
                    Vec3 vector3d = new Vec3(this.moveControl.getWantedX(), this.moveControl.getWantedY(), this.moveControl.getWantedZ());
                    if (path != null && !path.isDone()) {
                        vector3d = path.getNextEntityPos(this);
                    }
                    this.startJumping();
                }
            } else if (!rabbitController.canJump()) {
                this.enableJumpControl();
            }
        }
    }

    this.wasOnGround = this.onGround();
}

public void tick() {
    if(moveToCooldown > 0){
        moveToCooldown--;
    }
    if(hivePos != null){

        double dist = EntityLeafcutterAnt.this.distanceToSqr(Vec3.upFromBottomCenterOf(hivePos, 1));
        if (dist < 1.2F && EntityLeafcutterAnt.this.getBlockPosBelowThatAffectsMyMovement().equals(hivePos)) {
            BlockEntity tileentity = EntityLeafcutterAnt.this.level().getBlockEntity(hivePos);
            if (tileentity instanceof TileEntityLeafcutterAnthill) {
                TileEntityLeafcutterAnthill beehivetileentity = (TileEntityLeafcutterAnthill) tileentity;
                beehivetileentity.tryEnterHive(EntityLeafcutterAnt.this, EntityLeafcutterAnt.this.hasLeaf());
            }
        }
        if (dist < 16) {
            approachTime++;
            if(dist < 4){
                Vec3 center = Vec3.upFromBottomCenterOf(hivePos, 1.1F);
                Vec3 add = center.subtract(EntityLeafcutterAnt.this.position());
                if(add.length() > 1F){
                    add = add.normalize();
                }
                add = add.scale(0.2F);
                EntityLeafcutterAnt.this.setDeltaMovement(EntityLeafcutterAnt.this.getDeltaMovement().add(add));
            }
            if(dist < (approachTime < 200 ? 2 : 10) && EntityLeafcutterAnt.this.getY() >= hivePos.getY()){
                if(EntityLeafcutterAnt.this.getAttachmentFacing() != Direction.DOWN){
                    EntityLeafcutterAnt.this.setDeltaMovement(EntityLeafcutterAnt.this.getDeltaMovement().add(0, 0.1, 0));
                }
                EntityLeafcutterAnt.this.getMoveControl().setWantedPosition((double) hivePos.getX() + 0.5F, (double) hivePos.getY() + 1.5F, (double) hivePos.getZ() + 0.5F, 1.0D);
            }
            if(moveToCooldown <= 0){
                moveToCooldown = 50 + random.nextInt(30);
                EntityLeafcutterAnt.this.navigation.resetMaxVisitedNodesMultiplier();
                EntityLeafcutterAnt.this.navigation.moveTo((double) hivePos.getX() + 0.5F, (double) hivePos.getY() + 1.6F, (double) hivePos.getZ() + 0.5F, 1.0D);
            }
        } else {
            startMovingToFar(this.hivePos);
        }
    }
}

public void tick() {
    super.tick();
if(this.blockPos == null){
    return;
}else {
        BlockEntity te = this.entity.level().getBlockEntity(this.blockPos);
        if (te instanceof Container) {
            Container feeder = (Container) te;
            double distance = this.entity.distanceToSqr(this.blockPos.getX() + 0.5F, this.blockPos.getY() + 0.5F, this.blockPos.getZ() + 0.5F);
            if (hasLineOfSightChest()) {
                if (this.isReachedTarget() && distance <= 3) {
                    toggleChest(feeder, false);
                    ItemStack stack = getFoodFromInventory(feeder, this.entity.level().random);
                    if (stack == ItemStack.EMPTY) {
                        this.stop();
                    } else {
                        ItemStack duplicate = stack.copy();
                        duplicate.setCount(1);
                        if (!this.entity.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && !this.entity.level().isClientSide) {
                            this.entity.spawnAtLocation(this.entity.getItemInHand(InteractionHand.MAIN_HAND), 0.0F);
                        }
                        this.entity.setItemInHand(InteractionHand.MAIN_HAND, duplicate);
                        if (entity instanceof EntityRaccoon) {
                            ((EntityRaccoon) entity).lookForWaterBeforeEatingTimer = 10;
                        }
                        stack.shrink(1);
                        this.stop();

                    }
                } else {
                    if (distance < 5 && !hasOpenedChest) {
                        hasOpenedChest = true;
                        toggleChest(feeder, true);
                    }
                }
            }

        }

    }
}

public void handleStatusUpdate(byte id) {
	super.handleStatusUpdate(id);

	if(id == EVENT_HATCH_PARTICLES) {
		for (int count = 0; count <= 100; ++count) {
			BLParticles.ITEM_BREAKING.spawn(world, this.posX + (world.rand.nextDouble() - 0.5D), this.posY + 2D + world.rand.nextDouble(), this.posZ + (world.rand.nextDouble() - 0.5D), ParticleArgs.get().withData(new ItemStack(ItemRegistry.CHIROMAW_EGG)));
		}
	}

	if(id == EVENT_FLOAT_UP_PARTICLES) {
		ParticleArgs<?> args = ParticleArgs.get().withDataBuilder().setData(2, this).buildData();
		if(getElectricBoogaloo())
			args.withColor(0.420F, 0.565F, 0.553F, 1); //lightning
		else
			args.withColor(0.227F, 0.317F, 0.294F, 1); //normal

		args.withScale(0.5F + rand.nextFloat() * 0.5f);
		ParticleEntitySwirl particle = (ParticleEntitySwirl) BLParticles.CHIROMAW_TRANSFORM_SWIRL.create(this.world, this.posX, this.posY + 2.6D, this.posZ, args);
		particle.setOffset(0, -1.3D, 0);
		particle.setTargetOffset(0, 1.3D, 0);
		particle.updateTarget();
		Minecraft.getMinecraft().effectRenderer.addEffect(particle);
	}

	if(id == EVENT_NEW_SPAWN) {
		int leafCount = 40;
		float x = (float) (posX);
		float y = (float) (posY + 1.1F);
		float z = (float) (posZ);
		while (leafCount-- > 0) {
			float dx = getEntityWorld().rand.nextFloat() * 1 - 0.5f;
			float dy = getEntityWorld().rand.nextFloat() * 1f - 0.1F;
			float dz = getEntityWorld().rand.nextFloat() * 1 - 0.5f;
			float mag = 0.08F + getEntityWorld().rand.nextFloat() * 0.07F;
			if(getElectricBoogaloo())
				BLParticles.CHIROMAW_TRANSFORM_LIGHTNING.spawn(getEntityWorld(), x, y, z, ParticleFactory.ParticleArgs.get().withMotion(dx * mag, dy * mag, dz * mag));
			else
				BLParticles.CHIROMAW_TRANSFORM.spawn(getEntityWorld(), x, y, z, ParticleFactory.ParticleArgs.get().withMotion(dx * mag, dy * mag, dz * mag));
		}
	}
}

public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase entity, int timeLeft){
	// Decreases the timer by the amount it should have been decreased while the bow was in use.
	if(!world.isRemote) stack.setItemDamage(stack.getItemDamage() + (this.getMaxItemUseDuration(stack) - timeLeft));

	if(entity instanceof EntityPlayer){

		EntityPlayer player = (EntityPlayer)entity;

		int charge = this.getMaxItemUseDuration(stack) - timeLeft;
		charge = net.minecraftforge.event.ForgeEventFactory.onArrowLoose(stack, world, (EntityPlayer)entity, charge, true);
		if(charge < 0) return;

		float velocity = (float)charge / DRAW_TIME;
		velocity = (velocity * velocity + velocity * 2) / 3;

		if(velocity > 1) velocity = 1;

		if((double)velocity >= 0.1D){

			if(stack.getTagCompound() != null){
				int shotsLeft = stack.getTagCompound().getInteger(Flamecatcher.SHOTS_REMAINING_NBT_KEY) - 1;
				stack.getTagCompound().setInteger(Flamecatcher.SHOTS_REMAINING_NBT_KEY, shotsLeft);
				if(shotsLeft == 0 && !world.isRemote){
					stack.setItemDamage(getMaxDamage(stack) - getAnimationFrames());
				}
			}

			if(!world.isRemote){
				EntityFlamecatcherArrow arrow = new EntityFlamecatcherArrow(world);
				arrow.aim(player, EntityFlamecatcherArrow.SPEED * velocity);
				world.spawnEntity(arrow);
			}

			world.playSound(null, player.posX, player.posY, player.posZ,
					WizardrySounds.ITEM_FLAMECATCHER_SHOOT, WizardrySounds.SPELLS, 1, 1);

			world.playSound(null, player.posX, player.posY, player.posZ,
					WizardrySounds.ITEM_FLAMECATCHER_FLAME, WizardrySounds.SPELLS, 1, 1);
		}
	}
}

