public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    float potency = spellStat.getPotency();
    int range = spellStat.getRange();
    int burning = spellStat.getBurning();
    if (WandUtil.enchantedFocus(caster)) {
        potency += WandUtil.getPotencyLevel(caster);
        range += WandUtil.getRangeLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
    }
    float damage = SpellConfig.WaterJetDamage.get().floatValue() * WandUtil.damageMultiply();
    damage += potency;
    HitResult result = this.rayTrace(worldIn, caster, range, 3.0F);
    if (result.getType() != HitResult.Type.MISS) {
        double particleOffset = 0;
        if (result instanceof EntityHitResult entityHitResult) {
            Entity target = entityHitResult.getEntity();
            if (!MobUtil.areAllies(caster, target)) {
                MiscCapHelper.setClientTarget(caster, target);
                if (target.hurt(ModDamageSource.directDrench(caster), damage)) {
                    if (this.rightStaff(staff) && target instanceof LivingEntity livingEntity) {
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), MathHelper.secondsToTicks(5)));
                    }
                }
            }
            if (burning <= 0) {
                target.clearFire();
            } else if (!MobUtil.areAllies(caster, target)) {
                target.setSecondsOnFire(5 * burning);
            }
            particleOffset = target.getBbHeight() / 2;
        } else if (result instanceof BlockHitResult blockHitResult) {
            BlockPos blockPos = blockHitResult.getBlockPos();
            this.dowseFire(caster, worldIn, blockPos);
        }
        Vec3 vec3 = result.getLocation();
        worldIn.sendParticles(ModParticleTypes.WATER_TRAIL.get(), vec3.x, vec3.y + particleOffset, vec3.z, 1, 0, 0, 0, 0.15);
    }
    if (result.getType() == HitResult.Type.MISS || !(result instanceof EntityHitResult)) {
        MiscCapHelper.setClientTarget(caster, null);
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int duration = spellStat.getDuration();
    float radius = (float) spellStat.getRadius();
    if (WandUtil.enchantedFocus(caster)){
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 2.0F;
    }
    BlockPos left = BlockPos.containing(MobUtil.getLeftPos(caster, 2));
    left = BlockFinder.findGroundBelow(worldIn, left);
    BurningHoglin hoglin = new BurningHoglin(ModEntityType.BURNING_HOGLIN.get(), worldIn);
    hoglin.setTrueOwner(caster);
    hoglin.setPos(Vec3.atBottomCenterOf(left));
    if (this.rightStaff(staff)) {
        hoglin.setWindUpTime(10);
    }
    hoglin.setLimitedLife(100 * duration);
    hoglin.setExplosionPower(hoglin.getExplosionPower() + radius);
    hoglin.finalizeSpawn(worldIn, worldIn.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
    this.setTarget(caster, hoglin);
    if (worldIn.addFreshEntity(hoglin)) {
        this.uponSummon(worldIn, caster, staff, hoglin);
    }
    this.summonAdvancement(caster, hoglin);
    if (this.rightStaff(staff)) {
        BlockPos right = BlockPos.containing(MobUtil.getRightPos(caster, 2));
        right = BlockFinder.findGroundBelow(worldIn, right);
        BurningHoglin hoglin2 = new BurningHoglin(ModEntityType.BURNING_HOGLIN.get(), worldIn);
        hoglin2.setTrueOwner(caster);
        hoglin2.setPos(Vec3.atBottomCenterOf(right));
        hoglin2.setWindUpTime(10);
        hoglin2.setLimitedLife(100 * duration);
        hoglin2.setExplosionPower(hoglin2.getExplosionPower() + radius);
        hoglin2.finalizeSpawn(worldIn, worldIn.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
        this.setTarget(caster, hoglin2);
        if (worldIn.addFreshEntity(hoglin2)) {
            this.uponSummon(worldIn, caster, staff, hoglin2);
        }
    }
    this.SummonDown(caster);
    worldIn.playSound((Player) null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.SUMMON_SPELL.get(), this.getSoundSource(), 1.0F, 1.0F);
}

public SpawnGroupData finalizeSpawn(ServerLevelAccessor levelIn, DifficultyInstance difficultyIn, MobSpawnType reason, @Nullable SpawnGroupData spawnDataIn, @Nullable CompoundTag dataTag) {
    //Skip AgeableMob#finalizeSpawn
    getAttribute(Attributes.FOLLOW_RANGE).addPermanentModifier(new AttributeModifier("Random spawn bonus", this.random.nextGaussian() * 0.05, AttributeModifier.Operation.MULTIPLY_BASE));
    if (spawnDataIn instanceof PrehistoricGroupData prehistoricGroupData) {
        setAgeInDays(prehistoricGroupData.ageInDays());
    } else if (spawnDataIn == null) {
        spawnDataIn = new PrehistoricGroupData(data().adultAgeDays());
        setAgeInDays(((PrehistoricGroupData) spawnDataIn).ageInDays);
    }
    updateAbilities();
    setHunger(getMaxHunger() / 2);
    refreshDimensions();
    moodSystem.setPlayingCooldown(0);
    setMatingCooldown(24000);
    heal(getMaxHealth());
    setCurrentOrder(OrderType.WANDER);
    setNoAi(false);
    for (VariantCondition.WithVariant<ConfigCondition> pair : variantsByCondition(ConfigCondition.class)) {
        if (pair.condition().test()) {
            setVariant(VariantRegistry.CONFIG, pair);
            break;
        } else if (allVariants.containsKey(VariantRegistry.CONFIG) && Objects.equals(allVariants.get(VariantRegistry.CONFIG).condition(), pair.condition())) {
            clearVariant(VariantRegistry.CONFIG);
        }
    }
    for (VariantCondition.WithVariant<DateCondition> pair : variantsByCondition(DateCondition.class)) {
        if (pair.condition().test(random, ZonedDateTime.now())) {
            setVariant(VariantRegistry.DATE, pair);
            break;
        }
    }
    if (dataTag != null) {
        for (VariantCondition.WithVariant<NbtCondition> pair : variantsByCondition(NbtCondition.class)) {
            if (pair.condition().test(dataTag)) {
                setVariant(VariantRegistry.NBT, pair);
                break;
            }
        }
    }
    return spawnDataIn;
}

public void aiStep() {
    updateSwingTime();
    super.aiStep();

    if (getRidingPlayer() != null) {
        maxUpStep = 1;
    } else {
        maxUpStep = 0.6f;
    }

    if (!level.isClientSide) {
        setSprinting(getDeltaMovement().horizontalDistance() > 0.1 && getMoveControl().getSpeedModifier() >= attributes().sprintMod());
        if (getHunger() > getMaxHunger()) {
            setHunger(getMaxHunger());
        }
        if (getMatingCooldown() > 0) {
            setMatingCooldown(getMatingCooldown() - 1);
        }
        if (FossilConfig.isEnabled(FossilConfig.HEALING_DINOS) && random.nextInt(500) == 0 && deathTime == 0) {
            heal(1);
        }

        if (Version.debugEnabled()) {
            MessageHandler.DEBUG_CHANNEL.sendToPlayers(((ServerLevel) level).getPlayers(serverPlayer -> serverPlayer.distanceTo(this) < 16),
                    new SyncDebugInfoMessage(getId(), getGender().name(), getAge(), matingCooldown, moodSystem.getPlayingCooldown(), climbingCooldown, getHunger(), moodSystem.getMood()));
        }
        aiSystems.forEach(AISystem::serverTick);
        if (horizontalCollision && data().breaksBlocks() && moodSystem.getMood() < 0) {
            breakBlock((float) FossilConfig.getDouble(FossilConfig.BLOCK_BREAK_HARDNESS));
        }
        if (isFleeing()) {
            fleeTicks++;
            if (fleeTicks > getFleeingCooldown()) {
                this.setFleeing(false);
                fleeTicks = 0;
            }
        }
    } else {
        aiSystems.forEach(AISystem::clientTick);
    }
}

public void aiStep() {
	super.aiStep();

	if (isEgg()) {
		if (isMultipartActive()) {
			toggleMultipart(false);
			refreshDimensions();
		}
	}
	else if (!isMultipartActive()) {
		toggleMultipart(true);
		refreshDimensions();
	}

	if (level().isClientSide) {
		this.isFlying = !onGround();
	}
	else {
		if (isEgg()) {
			if (getAge() > -120000) {
				if (getAge() == -24000) {
					level().playSound(null, blockPosition(), SoundEvents.TURTLE_EGG_HATCH, SoundSource.NEUTRAL, 0.7f, (float)rand().valueBetween(0.2f, 1.1f));
				}
				else if (getAge() % 12000 == 0) {
					level().playSound(null, blockPosition(), SoundEvents.TURTLE_EGG_CRACK, SoundSource.NEUTRAL, 0.7f, (float)rand().valueBetween(0.2f, 1.1f));
				}
			}

			setDeltaMovement(getDeltaMovement().multiply(0.25f, 1, 0.25f).subtract(0, getAttributeValue(Attributes.GRAVITY), 0));
			move(MoverType.SELF, getDeltaMovement());
			AttributeUtil.applyPermanentModifier(this, Attributes.MAX_HEALTH, EGG_HEALTH_MOD, true);
		}
		else {
			AttributeUtil.removeModifier(this, Attributes.MAX_HEALTH, EGG_HEALTH_MOD);
		}

		if (isVehicle() && this.isFlying) {
			setDeltaMovement(getDeltaMovement().subtract(0, getAttributeValue(Attributes.GRAVITY) * 0.5f, 0));
		}
	}
}

public void onPlayerDrops(ZLivingDrops.Lowest event) {
	LivingEntity entity = event.getEntity();
	if(!(entity instanceof Player player))
		return;

	Collection<ItemEntity> drops = event.getDrops();

	if(!event.isCanceled() && (enableOnPK || !(event.getSource().getEntity() instanceof Player) || entity == event.getSource().getEntity())) {
		CompoundTag data = player.getPersistentData();
		CompoundTag persistent = data.getCompound(Player.PERSISTED_NBT_TAG);

		if(!drops.isEmpty()) {
			TotemOfHoldingEntity totem = new TotemOfHoldingEntity(totemType, player.level());
			totem.setPos(player.getX(), Math.max(player.level().getMinBuildHeight() + 3, player.getY() + 1), player.getZ());
			totem.setOwner(player);
			totem.setCustomName(player.getDisplayName());
			drops.stream()
					.filter(Objects::nonNull)
					.map(ItemEntity::getItem)
					.filter(stack -> !stack.isEmpty())
					.forEach(totem::addItem);
			if (zeta().isModLoaded("curios"))
				TotemOfHoldingCuriosCompat.saveCurios(player, totem);
			if(!player.level().isClientSide)
				player.level().addFreshEntity(totem);

			persistent.putString(TAG_LAST_TOTEM, totem.getUUID().toString());

			event.setCanceled(true);
		} else
			persistent.putString(TAG_LAST_TOTEM, "");

		BlockPos pos = player.blockPosition(); // getPosition
		persistent.putInt(TAG_DEATH_X, pos.getX());
		persistent.putInt(TAG_DEATH_Z, pos.getZ());
		persistent.putString(TAG_DEATH_DIM, player.level().dimension().location().toString());

		if(!data.contains(Player.PERSISTED_NBT_TAG))
			data.put(Player.PERSISTED_NBT_TAG, persistent);
	}
}

public @Nullable CrabState tick() {
    var hatPos = alakarkinos.hatPos;
    if (hatPos == null || alakarkinos.getHome() == null) {
        return new DecideCrabActionState(alakarkinos);
    }
    if (waitTicks > 0) {
        waitTicks--;
        return null;
    }
    alakarkinos.lookAt = Vec3.atCenterOf(hatPos);
    if (BlockUtil.distanceFrom(alakarkinos.level(), alakarkinos.blockPosition(), hatPos) > 2) {
        alakarkinos.getNavigation().moveTo(hatPos.getX() + 0.5, hatPos.getY() + 0.5, hatPos.getZ() + 0.5, 1.0);
        return null;
    }
    if (!backToHat) {
        backToHat = true;
        waitTicks = 60;
        alakarkinos.getEntityData().set(Alakarkinos.BLOWING_AT, Optional.of(hatPos));
        alakarkinos.setBlowingBubbles(true);
        alakarkinos.getNavigation().stop();
        return null;
    }
    alakarkinos.setBlowingBubbles(false);
    alakarkinos.findBlockCooldown = 60 * 20;
    List<ItemStack> loot = getLoot();
    if (!loot.isEmpty()) {
        IItemHandler handler = alakarkinos.level.getCapability(Capabilities.ItemHandler.BLOCK, alakarkinos.getHome(), null);

        for (ItemStack stack : loot) {
            if (stack.isEmpty()) {
                continue;
            }

            EntityFlyingItem.spawn(alakarkinos.getHome(), (ServerLevel) alakarkinos.level, hatPos, alakarkinos.getHome().above())
                    .setStack(stack)
                    .getEntityData().set(EntityFlyingItem.IS_BUBBLE, true);
            ItemHandlerHelper.insertItemStacked(handler, stack, false);
        }
    }
    return new DecideCrabActionState(alakarkinos);
}

public void tick() {
    super.tick();
    float tailSwing = getTailSwingRot();
    this.prevTailSwingRot = tailSwing;
    if (this.getAnimation() == ANIMATION_MELEE_TAIL_1 || this.getAnimation() == ANIMATION_MELEE_TAIL_2) {
        float start = this.getAnimation() == ANIMATION_MELEE_TAIL_1 ? 30 : -30;
        float end = this.getAnimation() == ANIMATION_MELEE_TAIL_1 ? -180 : 180;
        if (this.getAnimationTick() <= 7) {
            this.setTailSwingRot(Mth.approachDegrees(tailSwing, start, 5));
        } else {
            this.setTailSwingRot(Mth.approachDegrees(tailSwing, end, 25));
        }
        this.walkAnimation.setSpeed(1);
    } else {
        if (Math.abs(tailSwing) > 0.0F) {
            this.setTailSwingRot(Mth.approachDegrees(tailSwing, 0, 20));
        }
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
    }
    if (this.getAnimation() == ANIMATION_CHEW || this.getAnimation() == ANIMATION_CHEW_FROM_GROUND) {
        if (this.getAnimationTick() > this.getAnimation().getDuration() - 1) {
            this.heal(5);
        }
    }
    if (this.getAnimation() == ANIMATION_CHEW && this.getAnimationTick() == 2 || this.getAnimation() == ANIMATION_CHEW_FROM_GROUND && this.getAnimationTick() == 10) {
        this.playSound(ACSoundRegistry.GROTTOCERATOPS_GRAZE.get());
    }
    if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
        this.heal(2);
    }
    if (resetAttackerCooldown > 0) {
        resetAttackerCooldown--;
    } else if (!level().isClientSide && !this.isBaby() && (this.getLastHurtByMob() == null || !this.getLastHurtByMob().isAlive())) {
        this.setTarget(this.getLastHurtByMob());
        resetAttackerCooldown = 600;
    }
    if (this.getAnimation() == ANIMATION_SPEAK_1 && this.getAnimationTick() == 5 || this.getAnimation() == ANIMATION_SPEAK_2 && this.getAnimationTick() == 2) {
        actuallyPlayAmbientSound();
    }
    this.legSolver.update(this, this.yBodyRot + getTailSwingRot(), this.getScale());
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    super.tick();
    this.prevFishPitch = this.getFishPitch();
    if (!this.level().isClientSide) {
        final double ydist = (this.yo - this.getY());//down 0.4 up -0.38
        final float fishDist = (float) ((Math.abs(this.getDeltaMovement().x) + Math.abs(this.getDeltaMovement().z)) * 6F) / getPitchSensitivity();
        this.incrementFishPitch((float) (ydist) * 10 * getPitchSensitivity());
        this.setFishPitch(Mth.clamp(this.getFishPitch(), -60, 40));
        if (this.getFishPitch() > 2F) {
            this.decrementFishPitch(fishDist * Math.abs(this.getFishPitch()) / 90);
        }
        if (this.getFishPitch() < -2F) {
            this.incrementFishPitch(fishDist * Math.abs(this.getFishPitch()) / 90);
        }
        if (this.getFishPitch() > 2F) {
            this.decrementFishPitch(1);
        } else if (this.getFishPitch() < -2F) {
            this.incrementFishPitch(1);
        }
        if (baitballCooldown > 0) {
            baitballCooldown--;
        }
    }
    if(teleportIn > 0){
        teleportIn--;
        if(teleportIn == 0 && !this.level().isClientSide){
            final double range = 8;
            final AABB bb = new AABB(this.getX() - range, this.getY() - range, this.getZ() - range, this.getX() + range, this.getY() + range, this.getZ() + range);
            final List<EntityCosmicCod> list = this.level().getEntitiesOfClass(EntityCosmicCod.class, bb);
            final Vec3 vec3 = this.teleport();
            if (vec3 != null) {
                baitballCooldown = 5;
                for (final EntityCosmicCod cod : list) {
                    if (cod != this) {
                        cod.baitballCooldown = 5;
                        cod.teleport(vec3.x, vec3.y, vec3.z);
                    }
                }
            }
        }
    }
}

public void tick() {
    if (cooldown > 0) {
        cooldown--;
    }
    if (flightTarget != null) {
        EntityCrow.this.setFlying(true);
        if(EntityCrow.this.horizontalCollision){
            EntityCrow.this.getMoveControl().setWantedPosition(flightTarget.x, EntityCrow.this.getY() + 1F, flightTarget.z, 1F);

        }else{
            EntityCrow.this.getMoveControl().setWantedPosition(flightTarget.x, flightTarget.y, flightTarget.z, 1F);
        }
    }
    if (targetEntity != null) {
        flightTarget = targetEntity.position();
        if (EntityCrow.this.distanceTo(targetEntity) < 2.0F) {
            try{
                final BlockPos hangingPosition = targetEntity.getPos().relative(targetEntity.getDirection().getOpposite());
                final BlockEntity entity = targetEntity.level().getBlockEntity(hangingPosition);
                final Direction deposit = targetEntity.getDirection();
                final LazyOptional<IItemHandler> handler = entity.getCapability(ForgeCapabilities.ITEM_HANDLER, deposit);
                if(handler.orElse(null) != null && cooldown == 0) {
                    ItemStack duplicate = EntityCrow.this.getItemInHand(InteractionHand.MAIN_HAND).copy();
                    ItemStack insertSimulate = ItemHandlerHelper.insertItem(handler.orElse(null), duplicate, true);
                    if (!insertSimulate.equals(duplicate)) {
                        ItemStack shrunkenStack = ItemHandlerHelper.insertItem(handler.orElse(null), duplicate, false);
                        if(shrunkenStack.isEmpty()){
                            EntityCrow.this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                        }else{
                            EntityCrow.this.setItemInHand(InteractionHand.MAIN_HAND, shrunkenStack);
                        }
                        EntityCrow.this.peck();
                    }else{
                        cooldown = 20;
                    }
                }
            }catch (Exception e){
            }
            this.stop();
        }
    }
}

public void tick() {
    if (orbitResetCooldown > 0) {
        orbitResetCooldown--;
    }
    if (orbitResetCooldown < 0) {
        orbitResetCooldown++;
    }
    if (orbitResetCooldown > 0 && eagle.orbitPos != null) {
        if (orbitTime < maxOrbitTime && !eagle.isInWaterOrBubble()) {
            orbitTime++;
        } else {
            orbitTime = 0;
            eagle.orbitPos = null;
            orbitResetCooldown = -400 - random.nextInt(400);
        }
    }
    if (eagle.horizontalCollision && !eagle.onGround()) {
        stop();
    }
    if (flightTarget) {
        eagle.getMoveControl().setWantedPosition(x, y, z, 1F);
    } else {
        if (!eagle.isFlying() || eagle.onGround()) {
            this.eagle.getNavigation().moveTo(this.x, this.y, this.z, 1F);
        }
    }
    if (!flightTarget && isFlying()) {
        eagle.fallFlag = true;
        if (eagle.onGround()) {
            eagle.setFlying(false);
            orbitTime = 0;
            eagle.orbitPos = null;
            orbitResetCooldown = -400 - random.nextInt(400);
        }
    }
    if (isFlying() && (!level().isEmptyBlock(eagle.getBlockPosBelowThatAffectsMyMovement()) || eagle.onGround()) && !eagle.isInWaterOrBubble() && eagle.timeFlying > 30) {
        eagle.setFlying(false);
        orbitTime = 0;
        eagle.orbitPos = null;
        orbitResetCooldown = -400 - random.nextInt(400);
    }
}

public void tick() {
    toucan.aiItemFlag = true;
    double up = 3.0;
    if (encircleTime > 0) {
        encircleTime--;
    }
    if (isWithinXZDist(pos, toucan.position(), 5) && encircleTime <= 0) {
        up = 0.0D;
    }
    if (toucan.distanceToSqr(Vec3.atCenterOf(pos)) < 3.0D) {
        toucan.setFlying(false);
        toucan.peck();
        plantTime++;
        if (plantTime > 60) {
            BlockState state = toucan.getSaplingState();
            if (state != null) {
                if (state.canSurvive(toucan.level(), pos) && toucan.level().getBlockState(pos).canBeReplaced()) {
                    toucan.level().setBlockAndUpdate(pos, state);
                    if (!toucan.isEnchanted()) {
                        toucan.setSaplingState(null);
                    }
                }
            }
            stop();
        }
    } else {
        BlockPos moveTo = pos;

        if (encircleTime > 0) {
            moveTo = getVultureCirclePos(pos, 3, up);
        }
        if (moveTo != null) {
            if (encircleTime <= 0 && !toucan.hasLineOfSightSapling(pos)) {
                toucan.setFlying(false);
                toucan.getNavigation().moveTo(moveTo.getX() + 0.5F, moveTo.getY() + up + 0.5F, moveTo.getZ() + 0.5F, 1F);
