            }
        }
    }
}

public boolean attackEntityAsMob(Entity target, double damageScale) {
    if(!this.isEntityAlive())
        return false;
    if(target == null)
        return false;
    if(!this.canEntityBeSeen(target))
        return false;

    float damage = this.getAttackDamage(damageScale);
    int i = 0;

    //if(target instanceof EntityLivingBase) { // TODO Enchanted Weapon Damage and Knockback
    	//damage += EnchantmentHelper.getModifierForCreature(this.getHeldItemMainhand(), this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE));
        //i += EnchantmentHelper.getKnockbackModifier(this, (EntityLivingBase)target);
    //}

    boolean attackSuccess;
    double pierceDamage = this.creatureStats.getPierce();
    if(damage <= pierceDamage)
    	attackSuccess = target.attackEntityFrom(this.getDamageSource(null).setDamageBypassesArmor().setDamageIsAbsolute(), damage);
    else {
    	int hurtResistantTimeBefore = target.hurtResistantTime;
    	target.attackEntityFrom(this.getDamageSource(null).setDamageBypassesArmor().setDamageIsAbsolute(), (float)pierceDamage);
    	target.hurtResistantTime = hurtResistantTimeBefore;
		damage -= pierceDamage;
    	attackSuccess = target.attackEntityFrom(this.getDamageSource(null), damage);
    }

    if(attackSuccess) {
        if(i > 0) {
        	target.addVelocity((double)(-MathHelper.sin(this.rotationYaw * (float)Math.PI / 180.0F) * (float)i * 0.5F), 0.1D, (double)(MathHelper.cos(this.rotationYaw * (float)Math.PI / 180.0F) * (float)i * 0.5F));
            this.motionX *= 0.6D;
            this.motionZ *= 0.6D;
        }

        int fireEnchantDuration = EnchantmentHelper.getFireAspectModifier(this);
        if(fireEnchantDuration > 0)
        	target.setFire(fireEnchantDuration * 4);
    }

    return attackSuccess;
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int range = spellStat.getRange();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        range += WandUtil.getRangeLevel(caster);
    }
    int i;
    if (WandUtil.getSpellOnHand(caster, InteractionHand.MAIN_HAND) == this){
        if (caster.getMainArm() == HumanoidArm.RIGHT){
            i = 1;
        } else {
            i = -1;
        }
    } else {
        if (caster.getMainArm() == HumanoidArm.RIGHT){
            i = -1;
        } else {
            i = 1;
        }
    }
    float f2 = caster.yBodyRot * (float) (Math.PI / 180.0);
    double d0 = Mth.sin(f2);
    double d1 = Mth.cos(f2);
    double d2 = (double)i * 0.5D;
    double d3 = 1.0D;
    float f3 = caster.isCrouching() ? -0.1875F : 0.0F;
    Vec3 vec3 = caster.getEyePosition().add(-d1 * d2 - d0 * d3, (double)f3 - 0.45F, -d0 * d2 + d1 * d3);
    GulfTentacle gulfTentacle = new GulfTentacle(ModEntityType.GULF_TENTACLE.get(), worldIn);
    gulfTentacle.setPos(vec3);
    gulfTentacle.setOffset(i);
    gulfTentacle.setRot(caster.getYRot(), caster.getXRot());
    gulfTentacle.setTrueOwner(caster);
    gulfTentacle.setRange(gulfTentacle.getRange() + range);
    gulfTentacle.setStaff(this.rightStaff(staff));
    if (potency > 0){
        int boost = Mth.clamp(potency - 1, 0, 10);
        gulfTentacle.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), boost, false, false));
    }
    worldIn.addFreshEntity(gulfTentacle);
    this.playSound(worldIn, caster, ModSounds.WHIP_SWING.get());
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    int range = spellStat.getRange();
    int duration = spellStat.getDuration();
    double radius = spellStat.getRadius();
    float potency = spellStat.getPotency();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        duration *= WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
        potency += WandUtil.getPotencyLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, radius);
    LivingEntity target = this.getTarget(caster, range);
    if (rightStaff(staff)) {
        radius += 1.0D;
    }
    if (target != null){
        MonsoonCloud monsoonCloud = new MonsoonCloud(worldIn, caster, (LivingEntity) target);
        monsoonCloud.setExtraDamage(potency);
        monsoonCloud.setRadius((float) radius);
        monsoonCloud.setLifeSpan(duration);
        monsoonCloud.setStaff(rightStaff(staff));
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
