        monsoonCloud.setStaff(rightStaff(staff));
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            monsoonCloud.setLightningColor(0xa7fc3e);
        }
        monsoonCloud.setPos(blockPos.getX() + 0.5F, blockPos.getY() + 4, blockPos.getZ() + 0.5F);
