protected void onHitEntity(@NotNull EntityHitResult pResult) {
    if (!hurtEntities)
        return;
    super.onHitEntity(pResult);
    Entity entity = pResult.getEntity();
    float f = (float) this.getDeltaMovement().length();
    int i = Mth.ceil(Mth.clamp((Math.min(f, 2.5) * this.baseDamage) + getStateDamageBonus(), 0.0D, 2.147483647E9D));
    this.piercingIgnoreEntityIds.add(entity.getId());

    Entity owner = this.getOwner();
    DamageSource damagesource;
    damagesource = getDamageSource(owner, entity);

    boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
    int k = entity.getRemainingFireTicks();
    if (this.isOnFire() && !isEnderman) {
        entity.igniteForTicks(5);
    }

    if (entity.hurt(damagesource, (float) i)) {
        if (isEnderman) {
            return;
        }

        if (entity instanceof LivingEntity livingentity) {

            if (this.knockback > 0) {
                Vec3 vec3 = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double) this.knockback * 0.6D);
                if (vec3.lengthSqr() > 0.0D) {
                    livingentity.push(vec3.x, 0.1D, vec3.z);
                }
            }

            this.doPostHurtEffects(livingentity);
        }

        this.playSound(this.blockState.getSoundType().getBreakSound(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));

    } else {
        entity.setRemainingFireTicks(k);
    }
}

public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (shooter == null && spellContext.castingTile != null) {
        shooter = ANFakePlayer.getPlayer((ServerLevel) world);
        BlockPos pos = spellContext.castingTile.getBlockPos();
        shooter.setPos(pos.getX(), pos.getY(), pos.getZ());
    }

    if (shooter == null)
        return;
    Vec3 vec = rayTraceResult.getLocation();

    double damage = DAMAGE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier();
    double targetX = vec.x;
    double targetY = vec.y;
    double targetZ = vec.z;

    double d0 = Math.min(targetY, shooter.getY());
    double d1 = Math.max(targetY, shooter.getY()) + 1.0D;
    float f = (float) Mth.atan2(targetZ - shooter.getZ(), targetX - shooter.getX());
    int accelerate = spellStats.getBuffCount(AugmentAccelerate.INSTANCE); //no decelerate support atm
    double durationModifier = spellStats.getDurationMultiplier();
    // Create fangs in an AOE around the caster
    if (rayTraceResult instanceof EntityHitResult && shooter.equals(((EntityHitResult) rayTraceResult).getEntity())) {
        for (int i = 0; i < 5; ++i) {
            float f1 = f + (float) i * (float) Math.PI * 0.4F;
            int j = (int) ((i + durationModifier) / (1 + accelerate));
            spawnFangs(world, shooter.getX() + (double) Mth.cos(f1) * 1.5D, shooter.getZ() + (double) Mth.sin(f1) * 1.5D, d0, d1, f1, j, shooter, (float) damage);
        }

        for (int k = 0; k < 8; ++k) {
            float f2 = f + (float) k * (float) Math.PI * 2.0F / 8.0F + 1.2566371F;
            int j = (int) ((k + durationModifier) / (1 + accelerate));
            spawnFangs(world, shooter.getX() + (double) Mth.cos(f2) * 2.5D, shooter.getZ() + (double) Mth.sin(f2) * 2.5D, d0, d1, f2, j, shooter, (float) damage);
        }
        return;
    }
    for (int l = 0; l < 16; ++l) {
        double d2 = 1.25D * (double) (l + 1);
        int j = (int) ((l + durationModifier) / (1 + accelerate));
        this.spawnFangs(world, shooter.getX() + (double) Mth.cos(f) * d2, shooter.getZ() + (double) Mth.sin(f) * d2, d0, d1, f, j, shooter, (float) damage);
    }
}

public boolean startRitual(@Nullable ServerPlayer player, ItemStack activationItem, RecipeHolder<RitualRecipe> ritualRecipe) {
    if (!this.level.isClientSide()) {
        this.currentRitualRecipe = ritualRecipe;
        this.castingPlayerId = player == null ? null : player.getUUID();
        this.castingPlayer = player;
        this.currentTime = 0;
        this.sacrificeProvided = false;
        this.itemUseProvided = false;
        this.consumedIngredients.clear();
        this.remainingAdditionalIngredients = new ArrayList<>(this.currentRitualRecipe.value().getIngredients());
        this.ritualActive = true;
        if (!this.currentRitualRecipe.value().getRitual().start(this.level, this.getBlockPos(), this, player, this.itemStackHandler.getResource(0).toStack())) {
            this.stopRitual(false, false); //do not show message as start will already do that
            return false;
        }

        NeoForge.EVENT_BUS.addListener(this.rightClickItemListener);
        NeoForge.EVENT_BUS.addListener(this.livingDeathEventListener);

        this.setChanged();
        this.markNetworkDirty();

        this.level.updateNeighborsAt(this.getBlockPos(), this.getBlockState().getBlock());

        if (player != null) {
            if (ritualRecipe.value().requiresSacrifice()) {
                player.sendSystemMessage(Component.translatable(String.format("ritual.%s.sacrifice", Occultism.MODID)));
                player.sendSystemMessage(Component.translatable(String.format(ritualRecipe.value().getEntityToSacrificeDisplayName())));
            }

            if (ritualRecipe.value().requiresItemUse()) {
                player.sendSystemMessage(Component.translatable(String.format("ritual.%s.use_item", Occultism.MODID)));
                var itemToUseItems = ritualRecipe.value().getItemToUse().items().map(holder -> new ItemStack(holder.value())).toList();
                if (!itemToUseItems.isEmpty()) {
                    String s = itemToUseItems.getFirst().getDisplayName().getString();
                    player.sendSystemMessage(Component.translatable(s.substring(1, s.length() - 1)));
                }
            }
        }
    }
    return true;
}

public void aiStep() {
    super.aiStep();
    if (this.isSitting() && this.getNavigation().isDone()) {
        this.getNavigation().stop();
    }
    boolean swim = this.isInWater();
    this.prevSwimProgress = SwimProgress;
    this.prevSitProgress = sitProgress;
    if(SwimProgress < 5F && swim){
        SwimProgress++;
    }
    if(SwimProgress > 0 && !swim){
        SwimProgress--;
    }
    if (this.isSitting() && sitProgress < 5) {
        this.sitProgress ++;
    }
    if (!this.isSitting() && sitProgress > 0) {
        this.sitProgress --;
    }

    if (this.isInWater() && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (!this.isInWater() && !this.isLandNavigator) {
        switchNavigator(true);
    }

    if (blast_cooldown > 0) {
        blast_cooldown--;
    }

    AnimationHandler.INSTANCE.updateAnimations(this);
    if (this.getAnimation() == BABY_LEVIATHAN_BITE) {
        if (this.getAnimationTick() == 7) {
            this.playSound(ModSounds.LEVIATHAN_BITE.get(), 0.5f, 2.0f);
        }
        if (this.getAnimationTick() == 9) {
            biteattack(1.5f, 0.5, 0.5, 0.5);
        }
    }
}

public InteractionResult interact(Player pPlayer, InteractionHand pHand) {
    ItemStack itemStack = pPlayer.getItemInHand(pHand);
    if (!this.isLocked()) {
        if (itemStack.isEmpty() && pHand == InteractionHand.MAIN_HAND && !this.isNatural() && pPlayer.isShiftKeyDown() && !this.isWaxed()) {
            this.playSound(SoundEvents.SKELETON_STEP, 0.15F, 1.0F);

            if (!this.isBase() && !this.isRoar() && !this.isWorm() && !this.isFucked() && !this.isWalk() && !this.isCharge() && !this.isConstruct1() && !this.isConstruct2() && !this.isDead()) {
                this.setBase(true);
            }

            if (this.isBase()) {
                this.setBase(false);
                this.setRoar(true);
            } else if (this.isRoar()) {
                this.setRoar(false);
                this.setWalk(true);
            } else if (this.isWalk()) {
                this.setWalk(false);
                this.setCharge(true);
            } else if (this.isCharge()) {
                this.setCharge(false);
                this.setConstruct1(true);
            } else if (this.isConstruct1()) {
                this.setConstruct1(false);
                this.setConstruct2(true);
            } else if (this.isConstruct2()) {
                this.setConstruct2(false);
                this.setFucked(true);
            } else if (this.isFucked()) {
                this.setFucked(false);
                this.setWorm(true);
            } else if (this.isWorm()) {
                this.setWorm(false);
                this.setDead(true);
            } else if (this.isDead()) {
                this.setDead(false);
                this.setBase(true);
            }
        }
    }
    return super.interact(pPlayer, pHand);
}

protected boolean handleEating(Player player, ItemStack stack) {
    boolean shouldEat = false;
    float foodHealAmount = 0.0f;
    int ageUpAmount = 0;
    if (stack.is(Items.HAY_BLOCK)) {
        foodHealAmount = 20.0f;
        ageUpAmount = 180;
        if (!this.level.isClientSide() && this.getAge() == 0 && !this.isInLove()) {
            shouldEat = true;
            this.setInLove(player);
        }
    } else if (FOOD_ITEMS.test(stack)) {
        foodHealAmount = 2.0f;
        ageUpAmount = 20;
        if (!this.level.isClientSide()) {
            if (this.getTameTicks() > 0) {
                this.level.broadcastEntityEvent(this, (byte)6);
            } else {
                shouldEat = true;
                this.setTameTicks(600);
                this.level.broadcastEntityEvent(this, (byte)7);
            }
        }
    }
    if (this.getHealth() < this.getMaxHealth() && foodHealAmount > 0) {
        this.heal(foodHealAmount);
        shouldEat = true;
    }
    if (this.isBaby() && ageUpAmount > 0) {
        this.level.addParticle(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0), this.getRandomY() + 0.5, this.getRandomZ(1.0), 0.0, 0.0, 0.0);
        if (!this.level.isClientSide) {
            this.ageUp(ageUpAmount);
        }
        shouldEat = true;
    }
    if (shouldEat) {
        this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.HORSE_EAT, this.getSoundSource(), 1.0f, 1.0f + (this.random.nextFloat() - this.random.nextFloat()) * 0.2f);
        this.swing(InteractionHand.MAIN_HAND);
        this.gameEvent(GameEvent.EAT);
    }
    return shouldEat;
}

