public void tick() {
    LivingEntity target = BrainiacEntity.this.getTarget();
    if (tongueCooldown > 0) {
        tongueCooldown--;
    }
    if (target != null && target.isAlive()) {
        double dist = BrainiacEntity.this.distanceTo(target);
        if (BrainiacEntity.this.getAnimation() == NO_ANIMATION) {
            if (BrainiacEntity.this.getHealth() < BrainiacEntity.this.getMaxHealth() * 0.5F && BrainiacEntity.this.hasBarrel() && BrainiacEntity.this.random.nextInt(20) == 0) {
                BrainiacEntity.this.setAnimation(ANIMATION_DRINK_BARREL);
            }
            BrainiacEntity.this.getNavigation().moveTo(target, 1.2D);
            if (BrainiacEntity.this.hasLineOfSight(target)) {
                if (BrainiacEntity.this.getHealth() < BrainiacEntity.this.getMaxHealth() * 0.75F && dist < 20 && BrainiacEntity.this.hasBarrel() && BrainiacEntity.this.random.nextInt(30) == 0) {
                    BrainiacEntity.this.setAnimation(ANIMATION_THROW_BARREL);
                    BrainiacEntity.this.playSound(ACSoundRegistry.BRAINIAC_THROW.get());
                }
                if (dist < BrainiacEntity.this.getBbWidth() + target.getBbWidth() + 3.5D) {
                    BrainiacEntity.this.setAnimation(BrainiacEntity.this.random.nextBoolean() ? ANIMATION_SMASH : ANIMATION_BITE);
                    BrainiacEntity.this.playSound(ACSoundRegistry.BRAINIAC_ATTACK.get());
                    return;
                }
                if (tongueCooldown == 0 && BrainiacEntity.this.random.nextInt(16) == 0 && dist < 25) {
                    BrainiacEntity.this.playSound(ACSoundRegistry.BRAINIAC_LICK.get());
                    BrainiacEntity.this.setLickTicks(20);
                    tongueCooldown = 15 + BrainiacEntity.this.random.nextInt(15);
                }
            } else {
                BrainiacEntity.this.setLickTicks(0);
            }
        }
        if (BrainiacEntity.this.getAnimation() == ANIMATION_SMASH) {
            if (BrainiacEntity.this.getAnimationTick() >= 10 && BrainiacEntity.this.getAnimationTick() <= 15) {
                checkAndDealDamage(target, 2);
            }
        }
        if (BrainiacEntity.this.getAnimation() == ANIMATION_BITE) {
            if (BrainiacEntity.this.getAnimationTick() >= 10 && BrainiacEntity.this.getAnimationTick() <= 15) {
                checkAndDealDamage(target, 1);
            }
        }
    }
}

public void tick() {
    if (orbitResetCooldown > 0) {
        orbitResetCooldown--;
    }
    if (orbitResetCooldown < 0) {
        orbitResetCooldown++;
    }
    if (orbitResetCooldown > 0 && eagle.orbitPos != null) {
        if (orbitTime < maxOrbitTime && !eagle.isInWaterOrBubble()) {
            orbitTime++;
        } else {
            orbitTime = 0;
            eagle.orbitPos = null;
            orbitResetCooldown = -400 - random.nextInt(400);
        }
    }
    if (eagle.horizontalCollision && !eagle.onGround()) {
        stop();
    }
    if (flightTarget) {
        eagle.getMoveControl().setWantedPosition(x, y, z, 1F);
    } else {
        if (!eagle.onGround() && eagle.isFlying()) {
            if (!eagle.isInWaterOrBubble()) {
                eagle.setDeltaMovement(eagle.getDeltaMovement().multiply(1.2F, 0.6F, 1.2F));
            }
        } else {
            this.eagle.getNavigation().moveTo(this.x, this.y, this.z, 1F);
        }
    }
    if (!flightTarget && eagle.onGround() && isFlying()) {
        eagle.setFlying(false);
        orbitTime = 0;
        eagle.orbitPos = null;
        orbitResetCooldown = -400 - random.nextInt(400);
    }
    if (eagle.timeFlying > 30 && isFlying() && (!level().isEmptyBlock(eagle.getBlockPosBelowThatAffectsMyMovement()) || eagle.onGround()) && !eagle.isInWaterOrBubble()) {
        eagle.setFlying(false);
        orbitTime = 0;
        eagle.orbitPos = null;
        orbitResetCooldown = -400 - random.nextInt(400);
    }
}

public void tick() {
    super.tick();
    prevRollProgress = rollProgress;

    if (isRolling()) {
        if (rollProgress < 5F)
            rollProgress++;
    } else {
        if (rollProgress > 0F)
            rollProgress--;
    }

    if (!this.level().isClientSide) {
        this.setAngry(this.getTarget() != null && this.getTarget().isAlive() && this.distanceToSqr(this.getTarget()) < 20 * 20);
    }
    if (this.isRolling() && rollCooldown <= 0) {
        this.handleRoll();
        if (this.isAngry() && this.isAlive()) {
            for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.3F))) {
                if (!isAlliedTo(entity) && entity != this) {
                    entity.hurt(this.damageSources().mobAttack(this), (isTarget(entity) ? 5.0F : 2.0F) + random.nextFloat() * 2.0F);
                    launch(entity, isTarget(entity));
                    if (isTarget(entity)) {
                        maxRollTime = rollCounter + 10;
                    }
                }
            }
        }
        if (this.rollCounter > 2 && !this.isMoving() || !this.isAlive()) {
            this.setRolling(false);
        }
        this.setMaxUpStep(1F);
    } else {
        this.setMaxUpStep(0.66F);
        this.rollCounter = 0;
    }
    if (rollCooldown > 0) {
        rollCooldown--;
    }
    if (earthquakeCooldown > 0) {
        earthquakeCooldown--;
    }
}

public void onUsingTick(ItemStack stack, EntityLivingBase user, int count){

	if(user instanceof EntityPlayer){

		EntityPlayer player = (EntityPlayer)user;

		Spell spell = WandHelper.getCurrentSpell(stack);

		SpellModifiers modifiers;

		if(WizardData.get(player) != null){
			modifiers = WizardData.get(player).itemCastingModifiers;
		}else{
			modifiers = this.calculateModifiers(stack, (EntityPlayer)user, spell); // Fallback to the old way, should never be used
		}

		int useTick = stack.getMaxItemUseDuration() - count;
		int chargeup = (int)(spell.getChargeup() * modifiers.get(SpellModifiers.CHARGEUP));

		if(spell.isContinuous){
			// Continuous spell charge-up is simple, just don't do anything until it's charged
			if(useTick >= chargeup){
				// castingTick needs to be relative to when the spell actually started
				int castingTick = useTick - chargeup;
				// Continuous spells (these must check if they can be cast each tick since the mana changes)
				// Don't call canCast when castingTick == 0 because we already did it in onItemRightClick - even
				// with charge-up times, because we don't want to trigger events twice
				if(castingTick == 0 || canCast(stack, spell, player, player.getActiveHand(), castingTick, modifiers)){
					cast(stack, spell, player, player.getActiveHand(), castingTick, modifiers);
				}else{
					// Stops the casting if it was interrupted, either by events or because the wand ran out of mana
					player.stopActiveHand();
				}
			}
		}else{
			// Non-continuous spells need to check they actually have a charge-up since ALL spells call setActiveHand
			if(chargeup > 0 && useTick == chargeup){
				// Once the spell is charged, it's exactly the same as in onItemRightClick
				cast(stack, spell, player, player.getActiveHand(), 0, modifiers);
			}
		}
	}
}

public void tickTask() {
    ++this.ticks;
    if (this.level.getEntity(this.owner) instanceof LivingEntity living) {
        living.fallDistance = 0;
        living.invulnerableTime = 20;
        double radius = 1.0D;
        if (this.staff){
            radius += 0.25D;
        }
        for(int i = 0; i < 2; ++i) {
            double d0 = (2.0D * Math.random() - 1.0D) * 0.2D;
            double d1 = (2.0D * Math.random() - 1.0D) * 0.2D;
            double d2 = (2.0D * Math.random() - 1.0D) * 0.2D;
            this.level.sendParticles(ModParticleTypes.BIG_ELECTRIC.get(), living.getRandomX(1.0D), living.getRandomY(), living.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
        }
        ServerParticleUtil.addParticlesAroundMiddleSelf(this.level, ModParticleTypes.ELECTRIC.get(), living);

        List<Entity> list = this.level.getEntities(living, living.getBoundingBox().inflate(radius));
        if (!list.isEmpty()) {
            for (Entity entity : list) {
                if (entity instanceof LivingEntity target) {
                    if (!MobUtil.areAllies(living, entity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(entity) && entity.isAttackable()){
                        float baseDamage = SpellConfig.BoltingDamage.get().floatValue() * WandUtil.damageMultiply();
                        if (target.hurt(ModDamageSource.directShock(living), baseDamage + this.damage)){
                            float chance = this.staff ? 0.25F : 0.05F;
                            float chainDamage = this.damage / 2.0F;
                            if (this.level.isThundering() && this.level.isRainingAt(target.blockPosition())){
                                chance += 0.25F;
                                chainDamage = this.damage;
                            }
                            if (this.level.random.nextFloat() <= chance){
                                target.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                            }
                            if (this.staff){
                                WandUtil.chainLightning(target, living, 2.0D, chainDamage);
                            }
                        }
                    }
                }
            }
        }
    }
}

public void chainCharge(ServerLevel serverLevel, LivingEntity pTarget, LivingEntity pAttacker, double range) {
    List<Entity> harmed = new ArrayList<>();
    Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && !harmed.contains(livingEntity);
    if (pAttacker != null){
        selector = selector.and(entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && pTarget instanceof OwnableEntity ownable && ownable.getOwner() == pAttacker);
    }
    Entity prevTarget = pTarget;

    int hops = serverLevel.isThundering() ? 8 : 4;

    for (int i = 0; i < hops; i++) {
        AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
        Entity finalPrevTarget = prevTarget;
        List<Entity> entities = serverLevel.getEntities(prevTarget, aabb, selector.and(entity -> MobUtil.hasLineOfSight(finalPrevTarget, entity)));
        if (!entities.isEmpty()) {
            Entity entity = entities.get(serverLevel.getRandom().nextInt(entities.size()));
            if (entity instanceof LivingEntity target) {
                if (!target.hasEffect(GoetyEffects.CHARGED.get())) {
                    this.playSound(serverLevel, target, 1.0F, 0.5F);
                    target.addEffect(new MobEffectInstance(GoetyEffects.CHARGED.get(), MathHelper.secondsToTicks(30), 0, false, false));
                } else {
                    MobEffectInstance instance = target.getEffect(GoetyEffects.CHARGED.get());
                    if (instance != null) {
                        if (instance.getAmplifier() >= 1) {
                            target.hurt(ModDamageSource.directShock(pAttacker), SpellConfig.ChargeDamage.get().floatValue());
                        } else {
                            this.playSound(serverLevel, target, 1.0F, 0.75F);
                        }
                        EffectsUtil.amplifyEffect(target, GoetyEffects.CHARGED.get(), MathHelper.secondsToTicks(30), 3, false, false);
                    }
                }
                if (prevTarget != target) {
                    Vec3 vec3 = prevTarget.getEyePosition();
                    Vec3 vec31 = target.getEyePosition();
                    ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, 5));
                }

                harmed.add(target);
                prevTarget = target;
            }
        }
    }
}

public void computeResults() {
    if (this.salvageBtn == null) {
        return;
    }

    var matches = new ArrayList<OutputData>();

    for (int i = 0; i < 15; i++) {
        Slot s = this.menu.getSlot(i);
        ItemStack stack = s.getItem();
        for (RecipeHolder<SalvagingRecipe> recipe : SalvagingMenu.findMatch(Minecraft.getInstance().level, stack)) {
            if (recipe != null) {
                for (OutputData d : recipe.value().getOutputs()) {
                    int[] counts = SalvagingMenu.getSalvageCounts(d, stack);
                    matches.add(new OutputData(d.stack(), counts[0], counts[1]));
                }
            }
        }
    }

    var compressed = new ArrayList<OutputData>();

    for (OutputData data : matches) {
        if (data == null) {
            continue;
        }
        boolean success = false;
        for (int i = 0; i < compressed.size(); i++) {
            OutputData existing = compressed.get(i);
            if (data.stack().item().equals(existing.stack().item()) && data.stack().components().equals(existing.stack().components())) {
                compressed.set(i, new OutputData(existing.stack(), existing.min() + data.min(), existing.max() + data.max()));
                success = true;
                break;
            }
        }
        if (!success) {
            compressed.add(data);
        }
    }

    this.results = compressed;
    this.salvageBtn.active = !this.results.isEmpty();
}

public void serverTick(Level level, BlockPos pos, BlockState state) {
    boolean wasProcessing = cookingProgress > 0;
    boolean dirty = false;
    if (litTime > 0) {
        --litTime;
    }

    if (canProcess() && (litTime == 0 || (litTime > 0 && !canProcess(fuel)))) {
        ItemStack fuelStack = items.get(WorktableMenu.FUEL_SLOT_ID);
        litDuration = litTime = getRecipeFuelTime(items.get(WorktableMenu.INPUT_SLOT_ID), fuelStack);
        cookingTotalTime = timeToSmelt(items.get(WorktableMenu.INPUT_SLOT_ID), fuelStack);
        fuel = fuelStack.copy();
        if (litTime > 0) {
            dirty = true;
            fuelStack.shrink(1);
            if (fuelStack.isEmpty() && fuelStack.getItem().hasCraftingRemainingItem()) {
                items.set(WorktableMenu.FUEL_SLOT_ID, new ItemStack(fuelStack.getItem().getCraftingRemainingItem()));
            }
        }
    }

    if (litTime > 0 && canProcess(fuel)) {
        cookingProgress++;
        if (cookingProgress >= cookingTotalTime) {
            cookingProgress = 0;
            createItem();
            dirty = true;
        }
    }
    if (litTime == 0 && cookingProgress > 0 || litTime > 0 && cookingProgress > 0 && !canProcess(fuel)) {
        cookingProgress = Mth.clamp(cookingProgress - 2, 0, cookingTotalTime);
    }

    if (wasProcessing != cookingProgress > 0) {
        dirty = true;
        state = state.setValue(WorktableBlock.ACTIVE, cookingProgress > 0);
        level.setBlock(pos, state, 3);
    }

    if (dirty) {
        setChanged(level, pos, state);
    }
}

public void readAdditionalSaveData(CompoundTag compound) {
    super.readAdditionalSaveData(compound);
    aiSystems.forEach(system -> system.load(compound));
    int savedAge = compound.getInt("Age");
    //When the mob was saved the position + bb were still calculated with savedAge - savedAge % GROW_UP_INTERVAL
    //However on world load the mob calls refreshDimensions and if we were to use savedAge here the bb  would be
    // ever so slightly offset and potentially inside a block and the mob would ignore collision for that block
    setAgeInTicks(savedAge - savedAge % GROW_UP_INTERVAL);
    setMatingCooldown(compound.getInt("MatingCooldown"));
    setHunger(compound.getInt("Hunger"));
    setFleeing(compound.getBoolean("Fleeing"));
    setClimbing(compound.getBoolean("Climbing"));
    ticksClimbing = compound.getInt("TicksClimbing");
    climbingCooldown = compound.getInt("ClimbingCooldown");
    if (compound.contains("CurrentOrder", Tag.TAG_BYTE)) {
        setCurrentOrder(OrderType.values()[compound.getByte("CurrentOrder")]);
    }
    yBodyRot = compound.getInt("YBodyRot");
    yHeadRot = compound.getInt("YHeadRot");
    setAgingDisabled(compound.getBoolean("AgingDisabled"));
    if (compound.contains("Gender", Tag.TAG_STRING)) {
        //Stored in mobs pre-1.9.4.2
        if ("female".equalsIgnoreCase(compound.getString("Gender"))) {
            setGender(Gender.FEMALE);
        } else {
            setGender(Gender.MALE);
        }
    } else {
        setGender(Gender.values()[compound.getByte("Gender")]);
    }
    if (compound.contains("VariantId", Tag.TAG_STRING)) {
        setVariantId(compound.getString("VariantId"));
    }
    ListTag saved = compound.getList("Variants", Tag.TAG_COMPOUND);
    allVariants.clear();
    for (Tag savedTag : saved) {
        VariantRegistry.RegistryObject<? extends VariantCondition> type = VariantRegistry.RegistryObject.parse((CompoundTag) savedTag);
        String variantId = compound.getString("VariantId");
        if (variants().containsKey(variantId)) {
            allVariants.put(type, VariantCondition.WithVariant.of(type.serializer().load((CompoundTag) savedTag), variants().get(variantId)));
        }
    }
}

public void landHeavySpearAttack() {
	// find vector in front of us
	Vec3 vector = calculateViewVector(0.0F, getYRot());

	double dist = 1.25;
	double px = this.getX() + vector.x() * dist;
	double py = this.getBoundingBox().minY - (this.isPassenger() ? 0.75D : 0.0D);
	double pz = this.getZ() + vector.z() * dist;

	if (this.level() instanceof ServerLevel) {
		ParticlePacket particlePacket = new ParticlePacket();
		for (int i = 0; i < 50; i++) {
			particlePacket.queueParticle(ParticleTypes.LARGE_SMOKE, false, false,
				px + (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.25F * this.getRandom().nextGaussian(),
				py,
				pz + (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.25F * this.getRandom().nextGaussian(),
				0, 0, 0);
		}
		PacketDistributor.sendToPlayersTrackingEntity(this, particlePacket);
	}

	// damage things in front that aren't us or our "mount"
	double radius = 1.5D;
	AABB spearBB = new AABB(px - radius, py - radius, pz - radius, px + radius, py + radius, pz + radius);
	List<Entity> inBox = this.level().getEntities(this, spearBB, e -> e != this.getVehicle());

	if (this.level() instanceof ServerLevel server) {
		AttributeInstance attackDamage = Objects.requireNonNull(getAttribute(Attributes.ATTACK_DAMAGE));
		attackDamage.addOrUpdateTransientModifier(DAMAGE_MODIFIER);

		for (Entity entity : inBox) {
			super.doHurtTarget(server, entity);
		}

		attackDamage.removeModifier(DAMAGE_MODIFIER.id());
	}

	if (!inBox.isEmpty()) {
		this.playSound(SoundEvents.PLAYER_ATTACK_CRIT, getSoundVolume(), getVoicePitch());
	}

	this.gameEvent(GameEvent.HIT_GROUND);
}

