                    umvuthana.setMisbehavedPlayerId(entity.getTarget().getUUID());
                }
            }
        }
    }
}

private static int update(EntityPlayer player, Integer chargeTime){

	if(chargeTime == null) chargeTime = 0;

	if(chargeTime > 0){

		SpellModifiers modifiers = WizardData.get(player).getVariable(CHARGE_MODIFIERS);
		if(modifiers == null) modifiers = new SpellModifiers();

		Vec3d look = player.getLookVec();

		float speed = Spells.charge.getProperty(Charge.CHARGE_SPEED).floatValue() * modifiers.get(WizardryItems.range_upgrade);

		player.motionX = look.x * speed;
		player.motionZ = look.z * speed;

		if(player.world.isRemote){
			for(int i = 0; i < 5; i++){
				ParticleBuilder.create(Type.SPARK, player).spawn(player.world);
			}
		}

		List<EntityLivingBase> collided = player.world.getEntitiesWithinAABB(EntityLivingBase.class, player.getEntityBoundingBox().grow(EXTRA_HIT_MARGIN));

		collided.remove(player);

		float damage = Spells.charge.getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY);
		float knockback = Spells.charge.getProperty(KNOCKBACK_STRENGTH).floatValue();

		collided.forEach(e -> e.attackEntityFrom(MagicDamage.causeDirectMagicDamage(player, MagicDamage.DamageType.SHOCK), damage));
		collided.forEach(e -> e.addVelocity(player.motionX * knockback, player.motionY * knockback + 0.3f, player.motionZ * knockback));

		if(player.world.isRemote) player.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE,
				player.posX + player.motionX, player.posY + player.height/2, player.posZ + player.motionZ, 0, 0, 0);

		if(collided.isEmpty()) chargeTime--;
		else{
			EntityUtils.playSoundAtPlayer(player, SoundEvents.ENTITY_GENERIC_HURT, 1, 1);
			chargeTime = 0;
		}
	}

	return chargeTime;
}

public InteractionResult interactLivingEntity(ItemStack itemStack, Player player, LivingEntity target, InteractionHand hand) {
    if (!player.getCooldowns().isOnCooldown(this) && !isBroken(itemStack)) {
        if (getUseDuration(itemStack) == 0 || player.isCrouching()) {
            int bashingLevel = getEffectLevel(itemStack, ItemEffect.bashing);
            if (bashingLevel > 0) {
                bashEntity(itemStack, bashingLevel, player, target);

                tickProgression(player, itemStack, 2);
                applyDamage(2, itemStack, player);
                return InteractionResult.sidedSuccess(player.level().isClientSide);
            }

            int pryLevel = getEffectLevel(itemStack, ItemEffect.pry);
            if (pryLevel > 0) {
                PryEffect.perform(player, hand, this, itemStack, pryLevel, target);
                return InteractionResult.sidedSuccess(player.level().isClientSide);
            }

            if (InteractionHand.OFF_HAND.equals(hand)) {
                int jabLevel = getEffectLevel(itemStack, ItemEffect.jab);
                if (jabLevel > 0) {
                    jabEntity(itemStack, jabLevel, player, target);

                    if (!player.level().isClientSide) {
                        if (getEffectLevel(itemStack, ItemEffect.truesweep) > 0 && player.onGround() && !player.isSprinting()) {
                            SweepingEffect.truesweep(itemStack, player, true);
                        }

                        int howlingLevel = getEffectLevel(itemStack, ItemEffect.howling);
                        if (howlingLevel > 0) {
                            HowlingEffect.trigger(itemStack, player, howlingLevel);
                        }
                    }

                    tickProgression(player, itemStack, 2);
                    applyDamage(2, itemStack, player);
                    return InteractionResult.sidedSuccess(player.level().isClientSide);
                }
            }
        }
    }

    return InteractionResult.PASS;
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        SpawnGroupData spawngroupdata = null;
        int l = 1;

        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            l = caster.getRandom().nextIntBetweenInclusive(4, 7);
        } else if (rightStaff(staff)){
            l += caster.getRandom().nextInt(4);
        }

        for(int i1 = 0; i1 < l; ++i1) {
            PhantomServant phantom = ModEntityType.PHANTOM_SERVANT.get().create(worldIn);
            if (phantom != null) {
                BlockPos.MutableBlockPos blockpos$mutable = BlockFinder.SummonFlyingRadius(caster.blockPosition(), phantom, worldIn, 15).mutable();

                while(blockpos$mutable.getY() < caster.getY() + 20 + caster.getRandom().nextInt(15) && !worldIn.getBlockState(blockpos$mutable).blocksMotion()) {
                    blockpos$mutable.move(Direction.UP);
                }
                DifficultyInstance difficultyinstance = worldIn.getCurrentDifficultyAt(blockpos$mutable);
                phantom.setTrueOwner(caster);
                phantom.moveTo(blockpos$mutable, 0.0F, 0.0F);
                spawngroupdata = phantom.finalizeSpawn(worldIn, difficultyinstance, MobSpawnType.MOB_SUMMONED, spawngroupdata, (CompoundTag)null);
                phantom.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
                if (potency > 0){
                    phantom.setPhantomSize(potency);
                }
                this.SummonSap(caster, phantom);
                this.setTarget(caster, phantom);
                worldIn.addFreshEntityWithPassengers(phantom);
                this.summonAdvancement(caster, phantom);
            }
        }
        this.SummonDown(caster);
        SoundUtil.playNecromancerSummon(caster);
    }
}

public void tick() {
	LivingEntity target = this.taskOwner.getTarget();

	if (target == null) {
		stop();

		return;
	}

	double attackDistance = this.taskOwner.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());

	this.taskOwner.getLookControl().setLookAt(target, 30, 30);
	this.delayTicks--;

	if ((this.retainTarget || this.taskOwner.getSensing().canSee(target)) &&
			this.delayTicks <= 0 &&
			(this.targetX == 0 && this.targetY == 0 && this.targetZ == 0 || target.distanceToSqr(this.targetX, this.targetY, this.targetZ) >= 1 ||
					this.taskOwner.getRandom().nextFloat() < 0.05f)) {
		this.targetX = target.getX();
		this.targetY = target.getBoundingBox().minY;
		this.targetZ = target.getZ();
		this.delayTicks = 4 + this.taskOwner.getRandom().nextInt(7);

		if (attackDistance > 1024) {
			this.delayTicks += 10;
		}
		else if (attackDistance < 256) {
			this.delayTicks += 5;
		}

		if (!this.taskOwner.getNavigation().moveTo(target, this.speedModifier)) {
			this.delayTicks += 15;
		}
		else {
			this.taskOwner.getMoveControl().setWantedPosition(this.targetX, this.targetY, this.targetZ, this.speedModifier);
		}

	}

	if (this.attackCooldown > 0)
		this.attackCooldown--;

	this.checkAndAttack(target, attackDistance);
