public void tick(MobJarTile tile) {
    super.tick(tile);
    Level level = tile.getLevel();
    Pufferfish pufferfish = (Pufferfish) tile.getEntity();
    if (level.isClientSide || pufferfish == null || isPowered(tile)) {
        return;
    }
    PufferfishAccessor pufferfishAccessor = (PufferfishAccessor) pufferfish;
    boolean playerNearby = mobsNearby(tile, pufferfish);
    BlockPos worldPosition = tile.getBlockPos();
    if (playerNearby) {
        if (pufferfish.getPuffState() == 0) {
            pufferfish.playSound(SoundEvents.PUFFER_FISH_BLOW_UP, 1.0f, pufferfish.getVoicePitch());
            pufferfish.setPuffState(1);
            level.updateNeighborsAt(worldPosition, BlockRegistry.ITEM_DETECTOR.get());
            syncClient(tile);
        } else if (pufferfishAccessor.getInflateCounter() > 40 && pufferfish.getPuffState() == 1) {
            pufferfish.playSound(SoundEvents.PUFFER_FISH_BLOW_UP, 1.0f, pufferfish.getVoicePitch());
            pufferfish.setPuffState(2);
            level.updateNeighborsAt(worldPosition, BlockRegistry.ITEM_DETECTOR.get());
            syncClient(tile);
        }
        pufferfishAccessor.setInflateCounter(pufferfishAccessor.getInflateCounter() + 1);
    } else if (pufferfish.getPuffState() != 0) {
        if (pufferfishAccessor.getDeflateTimer() > 60 && pufferfish.getPuffState() == 2) {
            pufferfish.playSound(SoundEvents.PUFFER_FISH_BLOW_OUT, 1.0f, pufferfish.getVoicePitch());
            pufferfish.setPuffState(1);
            level.updateNeighborsAt(worldPosition, BlockRegistry.ITEM_DETECTOR.get());
            syncClient(tile);
        } else if (pufferfishAccessor.getDeflateTimer() > 100 && pufferfish.getPuffState() == 1) {
            pufferfish.playSound(SoundEvents.PUFFER_FISH_BLOW_OUT, 1.0f, pufferfish.getVoicePitch());
            pufferfish.setPuffState(0);
            level.updateNeighborsAt(worldPosition, BlockRegistry.ITEM_DETECTOR.get());
            syncClient(tile);
        }
        pufferfishAccessor.setDeflateTimer(pufferfishAccessor.getDeflateTimer() + 1);
    }
    if (!playerNearby) {
        pufferfishAccessor.setInflateCounter(0);
        if (pufferfish.getPuffState() == 0) {
            pufferfishAccessor.setDeflateTimer(0);
        }
    }
}

protected void tickSpitAttack() {
    animTime++;
    LivingEntity target = this.mob.getTarget();
    boolean inLineOfSight = this.mob.getSensing().hasLineOfSight(target);
    this.mob.lookAt(target, 30.0F, 30.0F);
    double d0 = this.mob.distanceToSqr(target.getX(), target.getY(), target.getZ());
    double d1 = this.getAttackReachSqr(target);
    if (inLineOfSight) {
        if (this.mob.distanceTo(target) >= 6.0D) {
            if (animTime == 1) {
                this.mob.getNavigation().stop();
                this.mob.setAnimationState(2);
            }
            if (animTime == 4) {
                this.attack.shoot();

            }
            if (animTime == 6 && this.multiShot) {
                this.attack.shoot();
                boolean isInsideWaterBlock = mob.level().isWaterAt(mob.blockPosition());
            }
            if (animTime >= 8) {
                this.mob.setAnimationState(0);
                this.animTime = -15;
            }
        }
        else {
            if (animTime == 4) {
                this.mob.getNavigation().stop();
                if (d0 <= d1) {
                    this.mob.doHurtTarget(target);
                    this.mob.setAnimationState(1);
                }
                target.invulnerableTime = 0;
            }
            if (this.animTime >= 8) {
                animTime=0;
                this.mob.setAnimationState(0);
                this.resetAttackCooldown();
                this.ticksUntilNextPathRecalculation = 0;
            }
        }
    }
}

public void tick() {
    super.tick();
    this.prevFlyProgress = flyProgress;
    if (this.isFlying() && flyProgress < 5F) {
        flyProgress++;
    }
    if (!this.isFlying() && flyProgress > 0F) {
        flyProgress--;
    }
    if (this.ringBufferIndex < 0) {
        //initial population of buffer
        for (int i = 0; i < this.ringBuffer.length; ++i) {
            this.ringBuffer[i] = 15;
        }
    }
    if(pollinateCooldown > 0){
        pollinateCooldown--;
    }
    this.ringBufferIndex++;
    if (this.ringBufferIndex == this.ringBuffer.length) {
        this.ringBufferIndex = 0;
    }
    if (!level().isClientSide) {
        if (isFlying() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!isFlying() && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (this.isFlying()) {
            if (this.isFlying() && !this.onGround()) {
                if (!this.isInWaterOrBubble()) {
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1F, 0.6F, 1F));
                }
            }
            if (this.onGround() && timeFlying > 20) {
                this.setFlying(false);
            }
            this.timeFlying++;
        } else {
            this.timeFlying = 0;
        }
    }
}

private void tickWalking() {
    this.prevWalkAnimPosition = walkAnimPosition;
    this.prevWalkAnimSpeed = walkAnimSpeed;
    this.prevLegBackAmount = legBackAmount;
    float f = getLegSlamAmount(2.0F, 0.333F);
    float f1 = getLegSlamAmount(2.0F, 0.666F);
    Vec3 movement = this.getDeltaMovement();
    float speed = (float) movement.length();
    if (this.areLegsMoving()) {
        this.walkAnimPosition += walkAnimSpeed;
        if (this.getAnimation() == ANIMATION_LEFT_WHIP || this.getAnimation() == ANIMATION_RIGHT_WHIP) {
            walkAnimSpeed = Mth.approach(walkAnimSpeed, 4.0F, 0.66F);
        } else {
            walkAnimSpeed = Mth.approach(walkAnimSpeed, this.isBaby() ? 2.0F : 1.0F, this.isBaby() ? 0.2F : 0.1F);
        }
    } else {
        if (f > 0.05) {
            this.walkAnimPosition += Math.min(f - 0.05F, walkAnimSpeed);
        }
        if (walkAnimSpeed > 0.0F) {
            walkAnimSpeed = Math.max(0, walkAnimSpeed - 0.025F);
        }
    }
    if (f <= 0.05 && walkAnimSpeed > 0.0F && this.onGround() && (speed > 0.003F || this.isVehicle()) && stepSoundCooldown <= 0) {
        this.onStep();
        stepSoundCooldown = 5;
    }
    if (f1 < 0.65F) {
        this.lastStompX = this.getX();
        this.lastStompZ = this.getZ();
    }
    if(stepSoundCooldown > 0){
        stepSoundCooldown--;
    }
    double stompX = (this.getX() - this.lastStompX);
    double stompZ = (this.getZ() - this.lastStompZ);
    float stompDist = Mth.sqrt((float) (stompX * stompX + stompZ * stompZ));
    if (speed <= 0.003 || !areLegsMoving()) {
        stompDist = 0;
    }
    if (this.getAnimation() == ANIMATION_SPEAK && this.getAnimationTick() == 2) {
        actuallyPlayAmbientSound();
    }
    this.legBackAmount = Mth.clamp(Mth.approach(this.legBackAmount, stompDist, speed), -1, 1);
}

public void spit() {
    this.setSpitTime(10);
    this.eatCooldown = 60 + random.nextInt(60);
    if (this.getCatfishSize() == 2) {
        if (this.hasSwallowedEntity()) {
            EntityType type = ForgeRegistries.ENTITY_TYPES.getValue(new ResourceLocation(this.getSwallowedEntityType()));
            if (type != null) {
                Entity entity = type.create(level());
                if (entity instanceof final LivingEntity alive) {
                    alive.readAdditionalSaveData(this.getSwallowedData());
                    alive.setHealth(Math.max(2, alive.getMaxHealth() * 0.25F));
                    alive.setYRot(random.nextFloat() * 360 - 180);
                    alive.setPos(this.getMouthVec());
                    if (level().addFreshEntity(alive)) {
                        this.setHasSwallowedEntity(false);
                        this.setSwallowedEntityType("minecraft:pig");
                        this.setSwallowedData(new CompoundTag());
                    }
                }
            }
        }
    } else {
        ItemStack itemStack = ItemStack.EMPTY;
        int index = -1;
        if(this.catfishInventory != null){
            for (int i = 0; i < this.catfishInventory.getContainerSize(); i++) {
                if (!this.catfishInventory.getItem(i).isEmpty()) {
                    itemStack = this.catfishInventory.getItem(i);
                    index = i;
                    break;
                }
            }
        }
        if (!itemStack.isEmpty()) {
            final Vec3 vec3 = this.getMouthVec();
            final Vec3 vec32 = vec3.subtract(position()).normalize().scale(0.14F);
            final ItemEntity item = new ItemEntity(level(), vec3.x, vec3.y, vec3.z, itemStack, vec32.x, vec32.y, vec32.z);
            item.setDeltaMovement(Vec3.ZERO);
            item.setPickUpDelay(30);
            if (level().addFreshEntity(item) && this.catfishInventory != null) {
                this.catfishInventory.setItem(index, ItemStack.EMPTY);
            }
        }
    }
}

public void readAdditionalSaveData(@NotNull CompoundTag compound) {
    super.readAdditionalSaveData(compound);
    this.setVariant(compound.getInt("Variant"));
    this.setChested(compound.getBoolean("Chested"));
    this.setSaddled(compound.getBoolean("Saddled"));
    this.setHovering(compound.getBoolean("Hovering"));
    this.setFlying(compound.getBoolean("Flying"));
    this.setArmor(compound.getInt("Armor"));
    feedings = compound.getInt("Feedings");
    if (hippogryphInventory != null) {
        ListTag nbttaglist = compound.getList("Items", 10);
        this.initHippogryphInv();
        for (int i = 0; i < nbttaglist.size(); ++i) {
            CompoundTag CompoundNBT = nbttaglist.getCompound(i);
            int j = CompoundNBT.getByte("Slot") & 255;
            this.hippogryphInventory.setItem(j, ItemStack.of(CompoundNBT));
        }
    } else {
        ListTag nbttaglist = compound.getList("Items", 10);
        this.initHippogryphInv();
        for (int i = 0; i < nbttaglist.size(); ++i) {
            CompoundTag CompoundNBT = nbttaglist.getCompound(i);
            int j = CompoundNBT.getByte("Slot") & 255;
            this.initHippogryphInv();
            this.hippogryphInventory.setItem(j, ItemStack.of(CompoundNBT));
            //this.setArmorInSlot(j, this.getIntFromArmor(ItemStack.loadItemStackFromNBT(CompoundNBT)));
            ItemStack saddle = hippogryphInventory.getItem(0);
            ItemStack chest = hippogryphInventory.getItem(1);
            if (level.isClientSide) {
                IceAndFire.NETWORK_WRAPPER.sendToServer(new MessageHippogryphArmor(this.getId(), 0, saddle != null && saddle.getItem() == Items.SADDLE && !saddle.isEmpty() ? 1 : 0));
                IceAndFire.NETWORK_WRAPPER.sendToServer(new MessageHippogryphArmor(this.getId(), 1, chest != null && chest.getItem() == Blocks.CHEST.asItem() && !chest.isEmpty() ? 1 : 0));
                IceAndFire.NETWORK_WRAPPER.sendToServer(new MessageHippogryphArmor(this.getId(), 2, getIntFromArmor(hippogryphInventory.getItem(2))));
            }
        }
    }
    this.hasHomePosition = compound.getBoolean("HasHomePosition");
    if (hasHomePosition && compound.getInt("HomeAreaX") != 0 && compound.getInt("HomeAreaY") != 0 && compound.getInt("HomeAreaZ") != 0) {
        homePos = new BlockPos(compound.getInt("HomeAreaX"), compound.getInt("HomeAreaY"), compound.getInt("HomeAreaZ"));
    }
    this.setCommand(compound.getInt("Command"));

    if (this.isOrderedToSit()) {
        this.sitProgress = 20.0F;
    }
}

public void startExecuting() {
	this.scurryingCooldown = 0;

	this.isScurrying = true;

	PathPoint finalPoint = this.path != null ? this.path.getFinalPathPoint() : null;
	this.scurryingStart = this.entity.getAttackTarget() != null ? this.entity.getAttackTarget().getPositionVector() : finalPoint != null ? new Vec3d(finalPoint.x + 0.5f, finalPoint.y + 0.5f, finalPoint.z + 0.5f) : this.entity.getPositionVector();

	PathPoint[] pathPoints = new PathPoint[this.pathMemory.size()];

	double furthestPathPosDst = 0;
	BlockPos furthestPathPos = null;

	int i = 0;
	for(BlockPos pos : this.pathMemory.values()) {
		pathPoints[this.pathMemory.size() - ++i] = new PathPoint(pos.getX(), pos.getY(), pos.getZ());

		double dst = pos.getDistance((int)this.scurryingStart.x, (int)this.scurryingStart.y, (int)this.scurryingStart.z);
		if(dst > furthestPathPosDst) {
			furthestPathPosDst = dst;
			furthestPathPos = pos;
		}
	}

	if(furthestPathPos != null) {
		this.path = this.entity.getNavigator().getPathToPos(furthestPathPos);
	}

	if(this.path == null) {
		this.path = new Path(pathPoints);
	}

	for(int j = 0; (this.path == null || this.path.getCurrentPathLength() < 6 || this.path.getFinalPathPoint().distanceTo(new PathPoint((int)this.scurryingStart.x, (int)this.scurryingStart.y, (int)this.scurryingStart.z)) < 6) && j < 3; j++) {
		Vec3d dir = this.entity.getPositionVector().subtract(this.scurryingStart).add(this.entity.getLookVec().scale(-0.25f)).normalize();

		Vec3d right = dir.crossProduct(new Vec3d(0, 1, 0));
		Vec3d up = right.crossProduct(dir);

		Vec3d target = this.entity.getPositionVector().add(dir.scale(32.0f).add(right.scale((this.entity.rand.nextFloat() - 0.5f) * 16.0f)).add(up.scale((this.entity.rand.nextFloat() - 0.5f) * 16.0f)));

		this.path = this.entity.getNavigator().getPathToXYZ(target.x, target.y, target.z);
	}

	this.entity.playLivingSound();
}

public @NotNull Optional<Mob> spawnOffspringFromSpawnEgg(@NotNull Player player, @NotNull Mob targetMob, @NotNull EntityType<? extends Mob> entityType, @NotNull ServerLevel serverLevel, @NotNull Vec3 vec3, ItemStack itemStack) {
    if (!this.spawnsEntity(itemStack.getTag(), entityType)) {
        return Optional.empty();
    } else {
        Mob mob;
        if (targetMob instanceof AgeableMob ageableMob) {
            mob = ageableMob.getBreedOffspring(serverLevel, ageableMob);
        } else if (targetMob instanceof AnimalSummon animalSummon) {
            mob = animalSummon.getBreedOffspring(serverLevel, animalSummon);
        } else if (targetMob instanceof AbstractIllagerServant illager) {
            mob = illager.getBreedOffspring(serverLevel, illager);
        } else {
            mob = entityType.create(serverLevel);
        }

        if (mob == null) {
            return Optional.empty();
        } else {
            mob.setBaby(true);
            if (!mob.isBaby()) {
                return Optional.empty();
            } else {
                if (mob instanceof IOwned owned && !owned.isHostile()) {
                    if (targetMob instanceof IOwned owned1 && !owned1.isHostile()) {
                        if (owned1.getTrueOwner() != null){
                            owned.setTrueOwner(owned1.getTrueOwner());
                        }
                    }
                }

                mob.moveTo(vec3.x(), vec3.y(), vec3.z(), 0.0F, 0.0F);
                serverLevel.addFreshEntityWithPassengers(mob);
                if (itemStack.hasCustomHoverName()) {
                    mob.setCustomName(itemStack.getHoverName());
                }

                if (!player.getAbilities().instabuild) {
                    itemStack.shrink(1);
                }

                return Optional.of(mob);
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float potency = spellStat.getPotency();
    float radius = (float) spellStat.getRadius();
    int duration = spellStat.getDuration();
    float damage = SpellConfig.FrostNovaDamage.get().floatValue() * WandUtil.damageMultiply();
    float maxDamage = SpellConfig.FrostNovaMaxDamage.get().floatValue() * WandUtil.damageMultiply();
    int cooldown = this.defaultSpellCooldown();
    if (WandUtil.enchantedFocus(caster)){
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        potency += WandUtil.getPotencyLevel(caster) / 2.0F;
    }
    damage += potency;
    maxDamage += potency;
    LivingEntity spellTarget = caster;
    LivingEntity target = this.getTarget(caster);
    if (isShifting(caster) && target != null){
        spellTarget = target;
        cooldown = SpellConfig.FrostNovaTargetCoolDown.get();
    }
    this.createParticleBall(worldIn, spellTarget, (int) radius);
    worldIn.sendParticles(new ShockwaveParticleOption(0, (float) (radius * 2), 1), spellTarget.getX(), spellTarget.getY() + 0.5F, spellTarget.getZ(), 0, 0, 0, 0, 0);
    float trueDamage = Mth.clamp(damage + RandomUtil.nextInt(worldIn.getRandom(), (int) (maxDamage - damage)), damage, maxDamage);
    int finalDuration = duration;
    int amp = 0;
    if (rightStaff(staff)) {
        amp += 1;
        radius += 0.5F;
    }
    int finalAmp = amp;
    new SpellExplosion(worldIn, caster, ModDamageSource.directFreeze(caster), spellTarget.blockPosition(), (float) radius, trueDamage){
        @Override
        public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
            if (target instanceof LivingEntity target1 && !MobUtil.areAllies(caster, target1) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target1)){
                super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                target1.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(5) * finalDuration, finalAmp));
            }
        }
    };
    this.playSound(worldIn, spellTarget, ModSounds.ICE_CHUNK_HIT.get(), 1.0F, 0.5F);
    if (caster instanceof Player player) {
        cooldown *= (int) ModAttributes.getCooldownDiscount(caster);
        SEHelper.addSpellCooldown(player, this, cooldown);
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 3;
        if (rightStaff(staff)){
            i = 3 + worldIn.random.nextInt(3);
        }
        if (this.NetherPower(caster)){
            i -= 2;
        }
        for (int i1 = 0; i1 < i; ++i1) {
            BlockPos blockpos = caster.blockPosition().offset(-2 + caster.getRandom().nextInt(5), 1, -2 + caster.getRandom().nextInt(5));
            Malghast ghast = new MiniGhast(ModEntityType.MINI_GHAST.get(), worldIn);
            if (this.NetherPower(caster)){
                ghast = new GhastServant(ModEntityType.GHAST_SERVANT.get(), worldIn);
                if (CuriosFinder.hasUnholySet(caster)){
                    ghast = new Malghast(ModEntityType.MALGHAST.get(), worldIn);
                }
                blockpos = BlockFinder.SummonFlyingRadius(caster.blockPosition().above(2), ghast, worldIn, 12);
            }
            ghast.setTrueOwner(caster);
            ghast.moveTo(blockpos, caster.getYRot(), 0.0F);
            ghast.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null, null);
            ghast.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            this.SummonSap(caster, ghast);
            int boost = Mth.clamp(potency, 0, 10);
            ghast.setFireBallDamage(boost - EffectsUtil.getAmplifierPlus(caster, MobEffects.WEAKNESS));
            float extraBlast = Mth.clamp(potency, 0, SpellConfig.MaxRadiusLevel.get()) / 2.5F;
            ghast.setExplosionPower(ghast.getExplosionPower() + extraBlast);
            this.setTarget(caster, ghast);
            if (worldIn.addFreshEntity(ghast)) {
                this.uponSummon(worldIn, caster, staff, ghast);
            }
            this.summonAdvancement(caster, ghast);
        }
        this.SummonDown(caster);
        worldIn.playSound((Player) null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.SUMMON_SPELL.get(), this.getSoundSource(), 1.0F, 1.0F);
    }
}

public static boolean performDoubleJump(Player player) {
	boolean hasDoubleJump = player.getData(TFDataAttachments.HAS_DOUBLE_JUMP);
	if (!hasDoubleJump || player.isFallFlying() || player.onClimbable() || player.onGround() || player.isSwimming() || player.getAbilities().flying || player.isInLiquid() || player.isPassenger())
		return false;
	player.jumpFromGround();
	Vec3 velocity = player.getDeltaMovement();
	double boostVelocity = player.getData(TFDataAttachments.SLIMY_SOLES_BOUNCE_INFO).doubleJumpBoostVelocity;
	if (boostVelocity != 0) {
		player.setDeltaMovement(velocity.x(), Math.sqrt(Math.pow(velocity.y(), 2) + Math.pow(boostVelocity, 2)), velocity.z());
		player.getData(TFDataAttachments.SLIMY_SOLES_BOUNCE_INFO).doubleJumpBoostVelocity = 0;
	}
	player.resetFallDistance();
	float pitchShift = 0.1F;
	player.playSound(TFSounds.DOUBLE_JUMP.get(), 1.5F, (player.getVoicePitch() - 1) * (1 + pitchShift) + (1 - pitchShift * 0.2F));
	player.setData(TFDataAttachments.HAS_DOUBLE_JUMP, false);
	player.setData(TFDataAttachments.DOUBLE_JUMP_VALIDATOR, 0);
	AttributeInstance instance = player.getAttribute(Attributes.SAFE_FALL_DISTANCE);
	if (instance != null) // Increase safe fall distance so the player can land up to 2 blocks below their starting height after performing a double jump at peak height without taking fall damage
		instance.addOrUpdateTransientModifier(TFAttributeModifiers.TRAVELLERS_DOUBLE_JUMP_SAFE_FALL_DISTANCE);

	if (player.getItemBySlot(EquipmentSlot.LEGS).is(TFItems.TRAVELLERS_WINGS)) {
		TravellersWingsAttachment attachment = player.getData(TFDataAttachments.TRAVELLERS_WINGS);
		attachment.state = TravellersWingsAttachment.WingState.DOUBLE_JUMP;
		attachment.doubleJumpTimer = 0;
	}

	if (player.level() instanceof ServerLevel serverLevel && player.getItemBySlot(EquipmentSlot.LEGS).is(TFItems.TRAVELLERS_WINGS)) {
		ParticlePacket particlePacket = new ParticlePacket();
		Vec3 deltaMovement = player.getDeltaMovement();
		for (int particleNumber = 0; particleNumber < 10; particleNumber++) {
			Vec3 particleVelocity = new Vec3(
				(serverLevel.getRandom().nextDouble() - 0.5),
				serverLevel.getRandom().nextDouble() + 1,
				(serverLevel.getRandom().nextDouble() - 0.5)
			);
			ParticleOptions type = TFParticleType.DOUBLE_JUMP.get();
			Vec3 wingsPosition = player.position().add(Math.sin(Math.toRadians(player.yBodyRot)) / 3, 1.2, -Math.cos(Math.toRadians(player.yBodyRot)) / 3);
			particlePacket.queueParticle(type, false, false, wingsPosition, particleVelocity.multiply(0.25, -0.5, 0.25).add(deltaMovement));
		}
		PacketDistributor.sendToPlayersTrackingEntityAndSelf(player, particlePacket);
		TravellersWingsAttachment attachment = player.getData(TFDataAttachments.TRAVELLERS_WINGS);
		PacketDistributor.sendToPlayersTrackingEntityAndSelf(player, new TravellersWingsStatePacket(player.getId(), TravellersWingsAttachment.WingState.DOUBLE_JUMP, attachment.sidestepLeft, attachment.doubleJumpTimer, attachment.sidestepTimer));
	}
	return true;
}

public @NonNull InteractionResult mobInteract(Player playerIn, @NonNull InteractionHand hand) {
    if (this.getOwner() == null)
        this.setFamiliarOwner(playerIn);

    ItemStack stack = playerIn.getItemInHand(hand);
    if (stack.getItem() instanceof FamiliarCurio) {
        return stack.interactLivingEntity(playerIn, this, hand);
    } else if (stack.getItem() == OccultismItems.DEBUG_WAND.get()) {
        if (playerIn.isShiftKeyDown() && !this.level().isClientSide()) {
            if (this.hasBlacksmithUpgrade()) {
                if (this.hasIesniumUpgrade()) {
                    this.setBlacksmithUpgrade(false);
                    this.setIesniumUpgrade(false);
                } else {
                    this.iesniumUpgrade();
                }
            } else {
                this.blacksmithUpgrade();
            }
        } else {
            this.setFamiliarOwner(playerIn);
            this.setTame(true, true);
        }
        return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
    }
    if (this.isOwnedBy(playerIn) && playerIn.isShiftKeyDown()) {
        if (this.age >= 0) {
            ItemStack feather = OccultismItems.AWAKENED_FEATHER.toStack();
            Optional<HolderSet.Named<Item>> a = this.registryAccess().get(Tags.Items.FEATHERS);
            if (a.isPresent() && this.getRandom().nextFloat() > 0.1F) {
                feather = a.get().get(this.getRandom().nextInt(a.get().size())).value().getDefaultInstance();
            }
            playerIn.addItem(feather);
            int cooldown = this.hasIesniumUpgrade() ? FEATHER_COOLDOWN_IESNIUM :
                    this.hasBlacksmithUpgrade() ? FEATHER_COOLDOWN_UPGRADED : FEATHER_COOLDOWN;
            this.setAge(-cooldown);
        } else {
            if (playerIn.level().isClientSide())
                playerIn.sendSystemMessage(Component.translatable("dialog.occultism.otherworldbird.feather_on_cooldown_" + this.getRandom().nextInt(3)));
        }
        return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
    }

    return super.mobInteract(playerIn, hand);
}

public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
	if (SuperpositionHandler.hasSpellstoneCooldown(player))
		return;

	CachedTeleportationLocation location = null;

	if (this.locationCache.containsKey(player)) {
		try {
			var future = this.locationCache.get(player);

			if (future.isDone()) {
				location = this.locationCache.get(player).get();
			} else {
				future.cancel(true);
			}

			this.locationCache.remove(player);
		} catch (Exception ex) {
			ex.printStackTrace();
		}
	}

	if (location == null) {
		EnigmaticLegacy.LOGGER.getInternal().info("No cached location found for {}, generating new one synchronously.", player.getGameProfile().getName());
		location = this.findRandomLocation(player);
	}

	ResourceKey<Level> key = location.dimension();

	world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
	EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
	player.teleportTo(location.x(), location.y(), location.z());

	if (player.level().dimension() != key) {
		SuperpositionHandler.sendToDimension(player, key);
		player.teleportTo(location.x(), location.y(), location.z());
	}

	world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
	EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));

	SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));

	EnigmaticLegacy.LOGGER.getInternal().info("Player {} triggered active ability of Non-Euclidean Cube. Teleported to D: {}, X: {}, Y: {}, Z: {}.",
			player.getGameProfile().getName(), player.level().dimension(), player.getX(), player.getY(), player.getZ());
}

public void customServerAiStep() {
    super.customServerAiStep();

    if (this.currentMoveTypeDuration > 0) {
        --this.currentMoveTypeDuration;
    }

    if (this.onGround() && this.shouldMove()) {
        if (!this.wasOnGround) {
            this.setJumping(false);
            this.checkLandingDelay();
        }

        if (this.currentMoveTypeDuration == 0) {
            LivingEntity livingentity = this.getTarget();
            if (livingentity != null && this.distanceToSqr(livingentity) < 16.0D) {
                this.calculateRotationYaw(livingentity.getX(), livingentity.getZ());
                this.moveControl.setWantedPosition(livingentity.getX(), livingentity.getY(), livingentity.getZ(), this.moveControl.getSpeedModifier());
                this.startJumping();
                this.wasOnGround = true;
            }
        }
        if (this.jumpControl instanceof EntityJerboa.JumpHelperController) {
            EntityJerboa.JumpHelperController rabbitController = (EntityJerboa.JumpHelperController) this.jumpControl;
            if (!rabbitController.getIsJumping()) {
                if (this.moveControl.hasWanted() && this.currentMoveTypeDuration == 0) {
                    Path path = this.navigation.getPath();
                    Vec3 vector3d = new Vec3(this.moveControl.getWantedX(), this.moveControl.getWantedY(), this.moveControl.getWantedZ());
                    if (path != null && !path.isDone()) {
                        vector3d = path.getNextEntityPos(this);
                    }

                    this.calculateRotationYaw(vector3d.x, vector3d.z);
                    this.startJumping();
                }
            } else if (!rabbitController.canJump()) {
                this.enableJumpControl();
            }
        }
    } else if (!this.shouldMove()) {
        this.setJumping(false);
        this.checkLandingDelay();
    }

    this.wasOnGround = this.onGround();
}

