private void containerChanged() {
    this.data.clear();
    for (Gem gem : GemRegistry.INSTANCE.getValues()) {
        var slot = new SafeSlot(gem, this.menu.getGemCount(gem), new ItemStack(Apoth.Items.GEM));
        GemItem.setGem(slot.displayStack, gem);
        GemItem.setPurity(slot.displayStack, Purity.NORMAL);
        this.data.add(slot);
    }

    this.data = this.filter(this.data);

    if (!this.isScrollBarActive()) {
        this.scrollOffs = 0.0F;
        this.startIndex = 0;
    }
    Collections.sort(this.data, Comparator.<SafeSlot, Boolean>comparing(slot -> slot.count <= 0).thenComparing(Comparator.comparing(slot -> slot.gem.getId().toString())));

    for (int i = 0; i < this.upgradeButtons.size(); i++) {
        Purity prev = Purity.values()[i];
        Purity purity = prev.next();
        GemUpgradeMatch match = this.menu.getUpgradeMatch(purity);
        SimpleTexButton button = this.upgradeButtons.get(i);
        if (match != null) {
            button.active = true;
            ItemStack leftMat = this.menu.getUpgradeMaterial(match.leftSlot());
            ItemStack rightMat = this.menu.getUpgradeMaterial(match.rightSlot());
            int leftCount = match.leftIng().count(), rightCount = match.rightIng().count();

            button.setTooltipProvider((btn, tooltip) -> {
                tooltip.accept(Apotheosis.lang("button", "gem_case.upgrade_cost", leftCount, leftMat.getHoverName(), rightCount, rightMat.getHoverName()));
                if (Minecraft.getInstance().hasShiftDown()) {
                    tooltip.accept(Apotheosis.lang("button", "gem_case.upgrade_all").withStyle(ChatFormatting.YELLOW));
                }
            });
        }
        else {
            button.active = false;
            if (this.menu.getGemCount(this.getSelectedGem(), prev) < 2) {
                button.setInactiveMessage(Apotheosis.lang("button", "gem_case.upgrade_no_gems").withStyle(ChatFormatting.RED));
            }
            else {
                button.setInactiveMessage(Apotheosis.lang("button", "gem_case.upgrade_no_materials").withStyle(ChatFormatting.RED));
            }
        }
    }
}

public void hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker) {
    //Vampire Finisher skill
    if (attacker instanceof Player player && !Helper.isVampire(target) && !target.typeHolder().is(ModEntityTags.IGNORE_VAMPIRE_SWORD_FINISHER)) {
        double relTh = 0;
        ISkillHandler<IVampirePlayer> skillHandler = VampirePlayer.get(player).getSkillHandler();
        IRefinementAccess refinementHandler = VampirePlayer.get(player).getRefinementHandler();
        if (skillHandler.isSkillEnabled(VampireSkills.SWORD_FINISHER) && !(target instanceof Player) || ModConfig.balance().vsSwordFinisherOnPlayer.get()) {
            relTh = ModConfig.balance().vsSwordFinisherMaxHealth.get() * (refinementHandler.isRefinementEquipped(ModRefinements.SWORD_FINISHER) ? ModConfig.balance().vrSwordFinisherThresholdMod.get() : 1d);
        }
        List<IItemWithTier.Tier> hunterCoatArmor = Arrays.stream(EquipmentSlot.values()).filter(EquipmentSlot::isArmor).map(target::getItemBySlot).filter(s -> s.getItem() instanceof HunterCoatItem).map(s -> ((HunterCoatItem) s.getItem()).getVampirismTier()).toList();
        if (hunterCoatArmor.size() == 4) {
            var level = hunterCoatArmor.stream().min(Comparator.comparingInt(IItemWithTier.Tier::ordinal)).orElse(IItemWithTier.Tier.NORMAL);
            relTh *= (1- switch (level) {
                case NORMAL -> 0.25f;
                case ENHANCED -> 0.3f;
                case ULTIMATE -> 0.35f;
            });
        }
        if (relTh > 0 && target.getHealth() <= target.getMaxHealth() * relTh) {
            if (player.level() instanceof ServerLevel level) {
                DamageHandler.hurtModded(level, target, s -> s.getPlayerAttackWithBypassArmor(player), 10000f);
            }
            Vec3 center = Vec3.atLowerCornerOf(target.blockPosition());
            center.add(0, target.getBbHeight() / 2d, 0);
            ModParticles.spawnParticlesServer(target.level(), new GenericParticleOptions(VIdentifier.mc("effect_4"), 12, 0xE02020), center.x, center.y, center.z, 15, 0.5, 0.5, 0.5, 0);
        }
    }
    //Update training on kill
    if (target.getHealth() <= 0.0f && Helper.isVampire(attacker)) {
        float trained = getTrained(stack, attacker);
        int exp = target instanceof Player ? 10 : (attacker instanceof Player && attacker.level() instanceof ServerLevel serverLevel ? target.getExperienceReward(serverLevel, attacker) : 5);
        float newTrained = exp / 5f * (1.0f - trained) / 15f;
        if (attacker instanceof Player && VampirePlayer.get((Player) attacker).getRefinementHandler().isRefinementEquipped(ModRefinements.SWORD_TRAINED_AMOUNT)) {
            newTrained *= ModConfig.balance().vrSwordTrainingSpeedMod.get();
        }
        trained += newTrained;
        setTrained(stack, attacker, trained);
    }
    //Consume blood
    float charged = getChargePercentage(stack);
    charged -= getChargeUsage(stack);
    setCharged(stack, charged);
    attacker.setItemInHand(InteractionHand.MAIN_HAND, stack);

    super.hurtEnemy(stack, target, attacker);
}

public void tick() {
    super.tick();
   // setYRot(yBodyRot);
    LivingEntity target = this.getTarget();
    if (!this.onGround() && this.getDeltaMovement().y < 0.0D) {
        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0D, 0.6D, 1.0D));
    }
    prevangerProgress = angerProgress;
    if (this.getIsAnger() && angerProgress < 5F) {
        angerProgress++;
    }
    if (!this.getIsAnger() && angerProgress > 0F) {
        angerProgress--;
    }
    if (breath_cooldown > 0) breath_cooldown--;
    if (storm_cooldown > 0) storm_cooldown--;
    if (this.isAlive()) {
        if (target != null && target.isAlive()) {
            if (breath_cooldown <= 0 && !isNoAi() && this.getAnimation() == NO_ANIMATION && (this.random.nextInt(35) == 0 && this.distanceTo(target) < 4.5F) && this.getShieldDurability() < 4) {
                breath_cooldown = BREATH_COOLDOWN;
                this.setAnimation(ASH_BREATH_ATTACK);
            } else if (storm_cooldown <= 0 && this.distanceTo(target) < 6 && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.random.nextInt(15) == 0) {
                storm_cooldown = STORM_COOLDOWN;
                this.setAnimation(BONE_STORM_ATTACK);
            }else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && (this.random.nextInt(12) == 0 && this.distanceTo(target) < 4.5F) && this.getShieldDurability() > 3) {
                this.setAnimation(ASH_BREATH_ATTACK);
            }
        }
        if(this.getAnimation() == NO_ANIMATION && this.getIsAnger() && this.getShieldDurability() < 4){
            if(this.tickCount % (6 + this.getShieldDurability() * 2) == 0){
                for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.25D))) {
                    if (!isAlliedTo(entity) && !(entity instanceof Ignited_Revenant_Entity) && entity != this) {
                        boolean flag = entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        if (flag) {
                            double d0 = entity.getX() - this.getX();
                            double d1 = entity.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            entity.push(d0 / d2 * 1.5D, 0.2D, d1 / d2 * 1.5D);
                        }
                    }
                }
            }
        }
    }

}

public void tick() {
    super.tick();
    if (isInWater() && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (!isInWater() && !this.isLandNavigator) {
        switchNavigator(true);
    }

    if (this.isNoAi()) {
        this.setAirSupply(this.getMaxAirSupply());
    } else {
        if (this.isInWaterRainOrBubble()) {
            this.setMoistness(6000);
        } else {
            int dry = this.level().isDay() ? 2 : 1;
            this.setMoistness(this.getMoistness() - dry);
            if (this.getMoistness() <= 0 && moistureAttackTime-- <= 0) {
                this.hurt(damageSources().dryOut(), random.nextInt(2) == 0 ? 1.0F : 0F);
                moistureAttackTime = 20;
            }
        }
    }

    boolean flag1 = this.canInFluidType(this.getEyeInFluidType());

    if(flag1){
        if(this.level().noCollision(this, this.getBoundingBox())) {
            if (!this.getSwim()) {
                setSwim(true);
            }
        }
    }else{
        if(this.level().noCollision(this, this.getBoundingBox())) {
            if (this.getSwim()) {
                setSwim(false);
            }
        }
    }

    if (this.level().isClientSide()) {
        this.idleAnimationState.animateWhen(!this.walkAnimation.isMoving() && this.getAttackState() == 0, this.tickCount);
    }
    if (nanta_cooldown > 0) nanta_cooldown--;
    if (jump_cooldown > 0) jump_cooldown--;
}

public void aiStep() {
	super.aiStep();
	ItemStack stack = this.getMainHandItem();
	ItemStack newStack = new ItemStack(Items.AIR);

	if (stack.getItem() == Items.AIR && !this.isAsleep() && !this.isInWater() && this.getRandom().nextInt(500) == 0 && !this.isFlicking()) {
		this.setFlicking(true);
	}
	if (this.isFlicking() && this.getRandom().nextInt(20) == 0) {
		this.setFlicking(false);
	}
	if (this.isFlicking() && (this.isInWater() || this.isAsleep() || stack.getItem() != Items.AIR)) this.setFlicking(false);
	if (stack.getItem() != Items.AIR) {
		timer++;
		if (timer == 600) {
			if (PrehistoricFaunaConfig.advancedHunger) {
				if (stack.is(PFTags.EGGS_5_HUNGER)) {
					if (this.getCurrentHunger() + 5 >= this.maxHunger) {
						this.setHunger(this.maxHunger);
					} else {
						this.setHunger(currentHunger + 5);
					}
				}
				if (stack.is(PFTags.EGGS_10_HUNGER)) {
					if (this.getCurrentHunger() + 10 >= this.maxHunger) {
						this.setHunger(this.maxHunger);
					} else {
						this.setHunger(currentHunger + 10);
					}
				}
				if (stack.is(PFTags.EGGS_15_HUNGER)) {
					if (this.getCurrentHunger() + 15 >= this.maxHunger) {
						this.setHunger(this.maxHunger);
					} else {
						this.setHunger(currentHunger + 15);
					}
				}
			}
			this.setItemInHand(InteractionHand.MAIN_HAND, newStack);
		}
		if (this.getLastHurtByMob() != null && timer < 600) {
			this.spawnItem(stack);
			this.setItemInHand(InteractionHand.MAIN_HAND, newStack);
		}
	}
}

