public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    float potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    int range = spellStat.getRange();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        range += WandUtil.getRangeLevel(caster);
    }
    float damage = this.damage + potency;
    if (!worldIn.isClientSide) {
        if (this.rightStaff(staff)) {
            damage *= 2.0F;
            if (SpellConfig.DragonFrostGriefing.get()) {
                float flameRange = range * ((float) Math.PI / 180.0F);
                for (int i = 0; i < 3; i++) {
                    Vec3 cast = caster.getLookAngle().normalize().xRot(worldIn.random.nextFloat() * flameRange * 2 - flameRange).yRot(worldIn.random.nextFloat() * flameRange * 2 - flameRange);
                    HitResult hitResult = worldIn.clip(new ClipContext(caster.getEyePosition(), caster.getEyePosition().add(cast.scale(10)), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, caster));
                    if (hitResult.getType() == HitResult.Type.BLOCK) {
                        Vec3 pos = hitResult.getLocation().subtract(cast.scale(0.5D));
                        BlockPos blockPos = BlockPos.containing(pos.x, pos.y, pos.z);
                        if ((worldIn.getBlockState(blockPos).isAir() ||
                                (BlockFinder.canBeReplaced(worldIn, blockPos)
                                        && worldIn.getFluidState(blockPos).isEmpty()))
                                && worldIn.getBlockState(blockPos.below()).isSolidRender(worldIn, blockPos.below())) {
                            worldIn.setBlockAndUpdate(blockPos, Blocks.SNOW.defaultBlockState());
                        }
                        BlockState blockstate = Blocks.FROSTED_ICE.defaultBlockState();
                        if (worldIn.getBlockState(blockPos) == FrostedIceBlock.meltsInto() && blockstate.canSurvive(worldIn, blockPos) && worldIn.isUnobstructed(blockstate, blockPos, CollisionContext.empty()) && !net.minecraftforge.event.ForgeEventFactory.onBlockPlace(caster, net.minecraftforge.common.util.BlockSnapshot.create(worldIn.dimension(), worldIn, blockPos), net.minecraft.core.Direction.UP)) {
                            worldIn.setBlockAndUpdate(blockPos, blockstate);
                            worldIn.scheduleTick(blockPos, Blocks.FROSTED_ICE, Mth.nextInt(caster.getRandom(), 60, 120));
                        }
                    }
                }
            }
        }
        for (Entity target : getBreathTarget(caster, range)) {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null) {
                if (livingEntity.hurt(ModDamageSource.frostBreath(caster, caster), damage)) {
                    livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(1) * duration));
                }
            }
        }
    }
    worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.FROST_BREATH.get(), this.getSoundSource(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int range = spellStat.getRange();
    float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        damage += WandUtil.getPotencyLevel(caster);
    }
    ColorUtil colorUtil = new ColorUtil(0xb1abf1);
    if (staff.is(ModItems.NAMELESS_STAFF.get())) {
        colorUtil = new ColorUtil(0xa7fc3e);
    }
    damage += spellStat.getPotency();
    Vec3 vec3 = caster.getEyePosition();
    BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
    Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
    Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
    if (lightningRod.isPresent() && !rightStaff(staff)){
        BlockPos blockPos = lightningRod.get();
        ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
        this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
    } else {
        LivingEntity livingEntity = MobUtil.getLivingTarget(target);
        if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
            Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
            if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                float chance = rightStaff(staff) ? 0.25F : 0.05F;
                float chainDamage = damage / 2.0F;
                if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                    chance += 0.25F;
                    chainDamage = damage;
                }
                if (worldIn.random.nextFloat() <= chance){
                    livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                }
                if (rightStaff(staff)){
                    WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage);
                }
            }
            this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
        } else {
            BlockPos blockPos = rayTraceResult.getBlockPos();
            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
            this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
        }
    }
}

private static @Nullable Player modifyTempt(ServerLevel level, Animal animal, Predicate<ItemStack> temptations) {
    //early-exit conditions
    if (!Quark.ZETA.modules.isEnabled(FeedingTroughModule.class) || !animal.canFallInLove() || animal.getAge() != 0) return null;

    //do we already know about a nearby trough?
    var iterator = NEARBY_TROUGH_CACHE.entrySet().iterator();
    while (iterator.hasNext()) {
        var entry = iterator.next();
        TroughPointer pointer = entry.getValue();
        if (!pointer.valid(entry.getKey())) {
            iterator.remove();
            // add fake player back to the list
            FREE_FAKE_PLAYERS.add(pointer.fakePlayer);
        }
    }
    TroughPointer pointer = NEARBY_TROUGH_CACHE.get(animal);

    //There's no cached trough nearby.
    //Randomize whether we actually look for a new trough, to hopefully not eat all the tick time.
    if (pointer == null && level.random.nextFloat() <= lookChance*20) {
        pointer = TroughPointer.find(level, animal, temptations);
        if (pointer != null){
            NEARBY_TROUGH_CACHE.put(animal, pointer);
            // remove from free players list
            FREE_FAKE_PLAYERS.remove(pointer.fakePlayer);
        }
    }

    //did we find one?
    if (pointer != null) {
        pointer.tryEatingOrTickCooldown(animal);

        if (!pointer.isOnCooldown()) {

            //if the animal can see it, direct the animal to this trough's fakeplayer
            BlockPos location = pointer.pos;
            Vec3 eyesPos = animal.position().add(0, animal.getEyeHeight(), 0);
            Vec3 targetPos = new Vec3(location.getX(), location.getY(), location.getZ()).add(0.5, 0.0625, 0.5);
            BlockHitResult ray = level.clip(new ClipContext(eyesPos, targetPos, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, animal));
            if (ray.getType() == HitResult.Type.BLOCK && ray.getBlockPos().equals(location)) {
                return pointer.fakePlayer;
            }
        }
    }

    return null;
}

public InteractionResult useOn(UseOnContext context) {
    Player player = context.getPlayer();
    if (player == null) {
        return InteractionResult.PASS;
    }
    Level world = context.getLevel();
    BlockPos pos = context.getClickedPos();
    TileEntityMekanism chargepad = WorldUtils.getTileEntity(TileEntityChargepad.class, world, pos);
    if (chargepad != null && !chargepad.getActive()) {
        if (world instanceof ServerLevel level) {
            ItemStack stack = context.getItemInHand();
            EntityRobit spawnedRobit = MekanismEntityTypes.ROBIT.get().spawn(level, robit -> {
                robit.setHome(chargepad.getTileGlobalPos());
                ItemAccess itemAccess = ItemAccessUtils.sideEffectFreeAccess(stack);
                ItemResource itemType = itemAccess.getResource();
                UUID ownerUUID = IItemSecurityUtils.INSTANCE.getOwnerUUID(itemAccess);
                if (ownerUUID == null) {
                    robit.setOwnerUUID(player.getUUID(), null);
                    //If the robit doesn't already have an owner, make sure we portray this
                    PacketDistributor.sendToAllPlayers(new PacketSyncSecurity(player.getUUID()));
                } else {
                    robit.setOwnerUUID(ownerUUID, null);
                }
                ContainerType.ENERGY.copyToContainer(robit.getEnergyContainer(), itemType);
                ContainerType.ITEM.copyToContainers(robit.getInventorySlots(), itemType);
                Component name = itemType.get(MekanismDataComponents.ROBIT_NAME);
                if (name != null) {
                    robit.setCustomName(name);
                }
                ISecurityObject securityObject = IItemSecurityUtils.INSTANCE.securityCapability(itemAccess);
                if (securityObject != null) {
                    robit.setSecurityMode(securityObject.getSecurityMode(), null);
                }
                robit.setSkin(itemType.getOrDefault(MekanismDataComponents.ROBIT_SKIN, MekanismRobitSkins.BASE), player);
                robit.setDefaultSkinManuallySelected(itemType.getOrDefault(MekanismDataComponents.DEFAULT_MANUALLY_SELECTED, false));
            }, pos, EntitySpawnReason.SPAWN_ITEM_USE, true, false);
            if (spawnedRobit == null) {
                return InteractionResult.FAIL;
            }
            world.gameEvent(player, GameEvent.ENTITY_PLACE, spawnedRobit.blockPosition());
            stack.consume(1, player);
            CriteriaTriggers.SUMMONED_ENTITY.trigger((ServerPlayer) player, spawnedRobit);
        }
        return InteractionResult.SUCCESS;
    }
    return InteractionResult.PASS;
}

public void tick() {
    super.tick();

    if(attackCooldown > 0){
        attackCooldown--;
    }

    if(soundTimer > 0){
        soundTimer--;
    }

   if (this.isShooting() && shootProgress < 50 && !this.hasControllingPassenger() && !this.isInWater() && !this.isSwimming()) {
       this.spit(this.getTarget());
       this.getNavigation().stop();
       shootProgress += 1;
       return;
   }

   if (this.isShooting() && shootProgress < 50 && this.hasControllingPassenger() && !this.isInWater() && !this.isSwimming()) {
       this.spitNoTarget();
       this.getNavigation().stop();
       shootProgress += 1;
       return;
   }

    shootProgress = 0;
    this.setIsShooting(false);

    boolean ridden = !this.getPassengers().isEmpty();
    boolean water = this.isInWater();
    if(ridden && water) {
        boolean waterBelow = this.level().isWaterAt(this.blockPosition().below());

        if(waterBelow) {
            this.move(MoverType.PLAYER, new Vec3(0, 0.08, 0));
        }
    }

    if (isRunning() && !hasRunningAttributes) {
        hasRunningAttributes = true;
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.31D);
    }
    if (!isRunning() && hasRunningAttributes) {
        hasRunningAttributes = false;
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.17D);
    }
}

public SpawnGroupData finalizeSpawn(ServerLevelAccessor worldIn, DifficultyInstance difficultyIn, MobSpawnType reason, @Nullable SpawnGroupData spawnDataIn, @Nullable CompoundTag dataTag) {
	RandomSource rng = this.getRandom();

	if (dataTag != null) {
		int age = dataTag.getBoolean("IsChild") ? -24000 : 0;

		this.setAge(age);
		this.teleportCooldown = dataTag.getInt("TeleportCooldown");
		this.setFromBottle(dataTag.getBoolean("IsFromBottle"));

		if (dataTag.contains("ColorTag", 3)) {
			this.setColor(dataTag.getInt("ColorTag"));
		}

		if (dataTag.contains("CustomPotionEffects")) {
			for (MobEffectInstance effectinstance : PotionUtils.getCustomEffects(dataTag)) {
				this.addEffect(effectinstance);
			}
		}
	}

	if (reason == MobSpawnType.STRUCTURE) {
		this.ticksAwayFromHive = rng.nextInt(1500) + 1500;

		if (rng.nextFloat() < 0.1F) {
			this.age = -24000;
		}
	} else if (reason == MobSpawnType.NATURAL || reason == MobSpawnType.SPAWNER) {
		if (rng.nextFloat() < 0.05F) {
			int swarmSize = rng.nextInt(11) + 10;
			Vec3 centeredPos = Vec3.atCenterOf(this.blockPosition());
			for (int i = 0; i < swarmSize; i++) {
				Vec3 spawnPos = centeredPos.add(MathUtil.makeNegativeRandomly(rng.nextFloat() * 5.5F, rng), MathUtil.makeNegativeRandomly(rng.nextFloat() * 2.0F, rng), MathUtil.makeNegativeRandomly(rng.nextFloat() * 5.5F, rng));

				if (this.level().isEmptyBlock(BlockPos.containing(spawnPos))) {
					PuffBug swarmChild = EEEntityTypes.PUFF_BUG.get().create(this.level());
					swarmChild.moveTo(spawnPos.x(), spawnPos.y(), spawnPos.z(), 0.0F, 0.0F);
					swarmChild.finalizeSpawn(worldIn, this.level().getCurrentDifficultyAt(BlockPos.containing(spawnPos)), MobSpawnType.EVENT, null, null);
					swarmChild.setAge(-24000);

					this.level().addFreshEntity(swarmChild);
				}
			}
		}
	}
	return super.finalizeSpawn(worldIn, difficultyIn, reason, spawnDataIn, dataTag);
}

