public void tick() {
    if (target != null) {
        golemCheckTime++;
        if (fleeTime > 0) {
            fleeTime--;
            if (raccoon.getNavigation().isDone()) {
                Vec3 fleevec = DefaultRandomPos.getPosAway(raccoon, 16, 7, raccoon.position());
                if (fleevec != null) {
                    raccoon.getNavigation().moveTo(fleevec.x, fleevec.y, fleevec.z, 1.3F);
                }
            }
            if (fleeTime == 0) {
                stop();
            }
        } else {
            raccoon.getNavigation().moveTo(target, 1.0D);
            if (raccoon.distanceTo(target) < 1.7F) {
                raccoon.setStanding(true);
                raccoon.maxStandTime = 15;
                MerchantOffers offers = target.getOffers();
                if (offers == null || offers.isEmpty() || offers.size() < 1) {
                    stop();
                } else {
                    MerchantOffer offer = offers.get(offers.size() <= 1 ? 0 : raccoon.getRandom().nextInt(offers.size() - 1));
                    if (offer != null) {
                        ItemStack stealStack = offer.getResult().getItem() == Items.EMERALD ? offer.getBaseCostA() : offer.getResult();
                        if (stealStack.isEmpty()) {
                            stop();
                        } else {
                            offer.increaseUses();
                            ItemStack copy = stealStack.copy();
                            copy.setCount(1);
                            raccoon.setItemInHand(InteractionHand.MAIN_HAND, copy);
                            fleeTime = 60 + random.nextInt(60);
                            raccoon.getNavigation().stop();
                            lookForWaterBeforeEatingTimer = 120 + random.nextInt(60);
                            target.hurt(damageSources().generic(), 0);
                            raccoon.stealCooldown = 24000 + random.nextInt(48000);
                        }
                    }
                }
            }
            if (golemCheckTime % 30 == 0 && random.nextBoolean() && isGolemNearby()) {
                stop();
            }
        }
    }
}

public void onUsingTick(ItemStack stack, LivingEntity player, int count) {
    if (player instanceof Player) {
        double dist = 32;
        Vec3 playerEyePosition = player.getEyePosition(1.0F);
        Vec3 playerLook = player.getViewVector(1.0F);
        Vec3 Vector3d2 = playerEyePosition.add(playerLook.x * dist, playerLook.y * dist, playerLook.z * dist);
        Entity pointedEntity = null;
        List<Entity> nearbyEntities = player.level.getEntities(player, player.getBoundingBox().expandTowards(playerLook.x * dist, playerLook.y * dist, playerLook.z * dist).inflate(1.0D, 1.0D, 1.0D), new Predicate<Entity>() {
            @Override
            public boolean test(Entity entity) {
                boolean blindness = entity instanceof LivingEntity && ((LivingEntity) entity).hasEffect(MobEffects.BLINDNESS) || (entity instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) entity).canBeTurnedToStone());
                return entity != null && entity.isPickable() && !blindness && (entity instanceof Player || (entity instanceof LivingEntity && DragonUtils.isAlive((LivingEntity) entity)));
            }
        });
        double d2 = dist;
        for (Entity nearbyEntity : nearbyEntities) {
            AABB axisalignedbb = nearbyEntity.getBoundingBox().inflate(nearbyEntity.getPickRadius());
            Optional<Vec3> optional = axisalignedbb.clip(playerEyePosition, Vector3d2);

            if (axisalignedbb.contains(playerEyePosition)) {
                if (d2 >= 0.0D) {
                    pointedEntity = nearbyEntity;
                    d2 = 0.0D;
                }
            } else if (optional.isPresent()) {
                double d3 = playerEyePosition.distanceTo(optional.get());

                if (d3 < d2 || d2 == 0.0D) {
                    if (nearbyEntity.getRootVehicle() == player.getRootVehicle() && !player.canRiderInteract()) {
                        if (d2 == 0.0D) {
                            pointedEntity = nearbyEntity;
                        }
                    } else {
                        pointedEntity = nearbyEntity;
                        d2 = d3;
                    }
                }
            }

        }
        if (pointedEntity instanceof LivingEntity) {
            if (!pointedEntity.isAlive())
                return;
            MiscProperties.addScepterTargetData(player, (LivingEntity) pointedEntity);
        }
        attackTargets(player);
    }
}

public boolean teleportNearEntity(Entity entity) {
    double targetX = entity.posX + (rand.nextDouble() - 0.5D) * 6.0D;
    double targetY = entity.posY + (rand.nextInt(3) - 1);
    double targetZ = entity.posZ + (rand.nextDouble() - 0.5D) * 6.0D;
    double x = posX;
    double y = posY;
    double z = posZ;
    boolean successful = false;
    BlockPos pos = this.getPosition();
    if (world.isBlockLoaded(pos)) {
        boolean validBlock = false;
        while (!validBlock && pos.getY() > 0) {
            IBlockState block = world.getBlockState(pos.down());
            if (block.getMaterial().blocksMovement()) {
                validBlock = true;
            } else {
                pos = pos.down();
            }
        }
        if (validBlock) {
            teleportCooldown = rand.nextInt(20 * 2) + 20 * 2;
            EntityDarkDruid newDruid = new EntityDarkDruid(world);
            newDruid.copyDataFromOld(this);
            newDruid.setUniqueId(UUID.randomUUID());
            newDruid.setPosition(targetX, targetY, targetZ);
            newDruid.faceEntity(entity, 100, 100);
            newDruid.setAttackTarget(this.getAttackTarget());
            newDruid.attackDelayCounter = MIN_ATTACK_DELAY + this.rand.nextInt(MAX_ATTACK_DELAY - MIN_ATTACK_DELAY + 1) + 1;
            if (world.getCollisionBoxes(newDruid, newDruid.getEntityBoundingBox()).isEmpty() && !world.containsAnyLiquid(newDruid.getEntityBoundingBox())) {
                successful = true;
                setDead();
                world.spawnEntity(newDruid);
                druidParticlePacketOrigin();
                druidParticlePacketTarget(newDruid);

                this.playSound(SoundRegistry.DRUID_TELEPORT, 1.0F, 1.0F);
                newDruid.playSound(SoundRegistry.DRUID_TELEPORT, 1.0F, 1.0F);
            } else
                newDruid.setDead();
        }
    }

    if (successful) {
        return true;
    }
    setPosition(x, y, z);
    return false;
}

public boolean shouldExecute() {
	if(!this.isScurrying) {
		Path path = this.entity.getNavigator().getPath();
		if(path != null) {
			double smallestDst = Double.MAX_VALUE;
			PathPoint closestPathPoint = null;
			int closestPathPointIndex = 0;

			for(int i = 0; i < path.getCurrentPathIndex(); i++) {
				PathPoint point = path.getPathPointFromIndex(i);

				double dst = this.entity.getDistanceSq(point.x + 0.5f, point.y + 0.5f, point.z + 0.5f);

				if(dst <= smallestDst) {
					smallestDst = dst;
					closestPathPoint = point;
					closestPathPointIndex = i;
				}
			}

			if(closestPathPoint != null) {
				Pair<Path, Integer> key = Pair.of(path, closestPathPointIndex);

				if(!this.pathMemory.containsKey(key)) {
					if(this.pathMemory.size() > this.maxPathMemory) {
						this.pathMemory.remove(this.pathMemory.keySet().iterator().next());
					}

					this.pathMemory.put(key, new BlockPos(closestPathPoint.x, closestPathPoint.y, closestPathPoint.z));
				}
			}
		}

		if(this.entity.isStalking || this.scurryingCooldown++ < 40) {
			return false;
		}
	}

	EntityLivingBase target = this.entity.getAttackTarget();

	if(target != null) {
		Vec3d dir = this.entity.getPositionEyes(1).subtract(target.getPositionEyes(1)).normalize();
		float angle = (float) Math.toDegrees(Math.acos(dir.dotProduct(target.getLook(1))));
		return angle < 5;
	}

	return false;
}

