            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.SUMMON_SPELL.get());
    }
}

public void tickServer() {
    super.tickServer();

    if (shouldUpdateNeighbours) {
        updateNeighbours();
        shouldUpdateNeighbours = false;
    }

    DroneFakePlayer fp = getFakePlayer();
    tickFakePlayer(fp);

    ChunkPos newChunkPos = new ChunkPos((int)curX >> 4, (int)curZ >> 4);
    if (chunkLoader != null) {
        if (PlayerLogoutTracker.INSTANCE.isPlayerLoggedOutTooLong(level.getServer(), ownerID)) {
            chunkLoader.unloadAll((ServerLevel) level);
        } else if (prevChunkPos == null || !prevChunkPos.equals(newChunkPos)) {
            chunkLoader.updateLoadedChunks((ServerLevel) level, newChunkPos);
        }
    }
    prevChunkPos = newChunkPos;

    heldItem = ConfigHelper.common().drones.dronesRenderHeldItem.get() ? fp.getMainHandItem() : ItemStack.EMPTY;

    if (getPressure() >= getMinWorkingPressure()) {
        if (!isIdle) {
            addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER);
            if (chunkloadWorkingChunk3x3) {
                addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER_CHUNKLOAD_WORK3);
            } else if (chunkloadWorkingChunk) {
                addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER_CHUNKLOAD_WORK);
            }
        }
        if (chunkloadSelf) {
            addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER_CHUNKLOAD_SELF);
        }
        DroneAIManager prevActive = getActiveAIManager();
        aiManager.onUpdateTasks();
        if (getActiveAIManager() != prevActive) {
            // active AI has changed (started or stopped using External Program) - resync widget list to debugging players
            getDebugger().getDebuggingPlayers().forEach(p -> NetworkHandler.sendToPlayer(PacketSyncDroneProgWidgets.create(this), p));
        }
        maybeChargeHeldItem();
    }

    if (nonNullLevel().getGameTime() % 20 == 0) {
        debugger.updateDebuggingPlayers();
    }
}

public EnumActionResult onItemUse(EntityPlayer playerIn, World worldIn, BlockPos pos, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ) {
	if (worldIn.isRemote || playerIn.isSneaking())
		return super.onItemUse(playerIn, worldIn, pos, hand, facing, hitX, hitY, hitZ);

	IMiscCapability cap = MiscCapabilityProvider.getCap(playerIn);
	if (cap == null) return super.onItemUse(playerIn, worldIn, pos, hand, facing, hitX, hitY, hitZ);

	EntityFairy entityFairy = cap.getSelectedFairyEntity(worldIn);
	if (entityFairy == null) return super.onItemUse(playerIn, worldIn, pos, hand, facing, hitX, hitY, hitZ);

	cap.setSelectedFairy(null);
	cap.dataChanged(playerIn);

	if (worldIn.isBlockLoaded(pos) && !worldIn.isAirBlock(pos)) {
		IBlockState state = worldIn.getBlockState(pos);
		if (state.getBlock().isCollidable()) {

			ItemStack stack = playerIn.getHeldItem(hand);
			boolean movingMode = NBTHelper.getBoolean(stack, "moving_mode", true);

			if (entityFairy.originPos != null) {
				if (!movingMode) {

					Vec3d hitVec = new Vec3d(pos).add(hitX, hitY, hitZ);
					Vec3d subtract = hitVec.subtract(entityFairy.getPositionVector());
					subtract = new Vec3d(MathHelper.clamp(subtract.x, -ConfigValues.fairyReach, ConfigValues.fairyReach), MathHelper.clamp(subtract.y, -ConfigValues.fairyReach, ConfigValues.fairyReach), MathHelper.clamp(subtract.z, -ConfigValues.fairyReach, ConfigValues.fairyReach));

					entityFairy.setLookTarget(subtract);

					playerIn.world.playSound(null, playerIn.getPosition(), ModSounds.TINY_BELL, SoundCategory.NEUTRAL, 1, 0.75f);

					cap.setSelectedFairy(null);
					cap.dataChanged(playerIn);


				} else {

					entityFairy.targetPos = pos.offset(facing);
					entityFairy.setLookTarget(null);

					playerIn.world.playSound(null, playerIn.getPosition(), ModSounds.TINY_BELL, SoundCategory.NEUTRAL, 1, 1.25f);
				}
			}
		}
	}

	return super.onItemUse(playerIn, worldIn, pos, hand, facing, hitX, hitY, hitZ);
}

public void tick() {
    for (Entry<UUID, Integer> entry : this.cooldowns.entrySet())
        if (entry.getValue() > 0)
            this.cooldowns.put(entry.getKey(), entry.getValue() - 1);

    if (this.fairy.tickCount % 5 != 0)
        return;

    LivingEntity owner = this.fairy.getFamiliarOwner();

    if (owner == null)
        return;

    List<Mob> familiars = this.fairy.level().getEntitiesOfClass(Mob.class,
            this.fairy.getBoundingBox().inflate(10),
            e -> e != this.fairy && e instanceof IFamiliar && ((IFamiliar) e).getFamiliarOwner() == owner);

    for (Mob familiar : familiars) {
        UUID id = familiar.getUUID();
        if (!this.cooldowns.containsKey(id))
            this.cooldowns.put(id, 0);

        if (this.cooldowns.get(id) == 0) {
            boolean gaveSupport = familiar.isOnFire()
                    && familiar.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, DURATION));
            if (familiar.isInWater()
                    && familiar.addEffect(new MobEffectInstance(MobEffects.WATER_BREATHING, DURATION)))
                gaveSupport = true;
            if (!familiar.isNoGravity() && familiar.fallDistance > 3
                    && familiar.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING, DURATION)))
                gaveSupport = true;
            if (familiar.getNavigation().isInProgress()
                    && familiar.getNavigation().getTargetPos().distSqr(familiar.blockPosition()) > 100
                    && familiar.addEffect(new MobEffectInstance(MobEffects.SPEED, DURATION)))
                gaveSupport = true;
            if (familiar.getLastHurtByMob() != null
                    && familiar.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, DURATION)))
                gaveSupport = true;
            if (familiar instanceof HeadlessFamiliarEntity ratman && ratman.reviveHeadlessRatman())
                gaveSupport = true;
            if (gaveSupport) {
                Networking.sendToTracking(this.fairy,
                        new MessageFairySupport(this.fairy.getId(), familiar.getId()));
                this.cooldowns.put(id, DURATION);
            }
        }
    }
}

private static void spiritFire(RightClickBlock event) {
    boolean isFlintAndSteel = event.getItemStack().is(Tags.Items.TOOLS_IGNITER);
    boolean isFireCharge = event.getItemStack().getItem() == Items.FIRE_CHARGE;
    boolean canLightFire = event.getItemStack().canPerformAction(LIGHT_FIRE)
            || event.getItemStack().canPerformAction(LIGHT_CAMPFIRE)
            || event.getItemStack().canPerformAction(LIGHT_STARTER);

    if (isFlintAndSteel || isFireCharge || canLightFire) {
        //find if there is any datura
        AABB box = new AABB(-1, -1, -1, 1, 1, 1)
                .move(Math3DUtil.center(event.getPos()));
        List<ItemEntity> list = event.getLevel().getEntitiesOfClass(ItemEntity.class, box,
                item -> item.getItem().is(OccultismTags.Items.START_SPIRIT_FIRE));
        if (!list.isEmpty()) {
            //if there is datura, check if we can edit the target face
            Level level = event.getLevel();
            BlockPos pos = level.getBlockState(event.getPos()).canBeReplaced() ? event.getPos() : event.getPos().relative(event.getFace());
            if (!event.getEntity().mayUseItemAt(pos, event.getFace(), event.getItemStack())) {
                return;
            }

            //consume all datura
            list.forEach(e -> e.remove(RemovalReason.DISCARDED));

            //if there is air, place block and play sound
            if (level.getBlockState(pos).canBeReplaced()) {
                //sound based on the item used
                SoundEvent soundEvent =
                        isFlintAndSteel ? SoundEvents.FLINTANDSTEEL_USE : SoundEvents.FIRECHARGE_USE;
                level.playSound(event.getEntity(), pos, soundEvent,
                        SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.4F + 0.8F);

                level.setBlock(pos, OccultismBlocks.SPIRIT_FIRE.get().defaultBlockState(), 11);

                //now handle used item
                if (isFlintAndSteel) {
                    EquipmentSlot slot = event.getHand() == InteractionHand.MAIN_HAND ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND;
                    event.getItemStack().hurtAndBreak(1, event.getEntity(), slot);
                } else if (isFireCharge) {
                    event.getItemStack().shrink(1);
                }
            }
            //finally, cancel original event to prevent real action and show use animation
            event.setCanceled(true);
            event.getEntity().swing(InteractionHand.MAIN_HAND);
        }
    }
}

protected void onHitEntity(EntityHitResult p_37626_) {
    super.onHitEntity(p_37626_);
    Entity shooter = this.getOwner();
    if (!this.level().isClientSide && !(p_37626_.getEntity() instanceof Ignis_Fireball_Entity ||  p_37626_.getEntity() instanceof Ignis_Abyss_Fireball_Entity || p_37626_.getEntity() instanceof Cm_Falling_Block_Entity || p_37626_.getEntity() instanceof Ignis_Entity && shooter instanceof Ignis_Entity) && getFired()) {
        Entity entity = p_37626_.getEntity();
        boolean flag;
        if (shooter instanceof LivingEntity) {
            LivingEntity owner = (LivingEntity)shooter;
            if (entity instanceof LivingEntity) {
                flag = entity.hurt(damageSources().mobProjectile(this, owner), 10.0F + ((LivingEntity) entity).getMaxHealth() * 0.2f);
            }else{
                flag = entity.hurt(damageSources().mobProjectile(this, owner), 10.0F);
            }
            if (flag) {
                this.doEnchantDamageEffects(owner, entity);
                if(owner instanceof Ignis_Entity) {
                    owner.heal(5.0F * (float) CMCommonConfig.Ignis.HealingMultiplier);
                }else{
                    owner.heal(5.0F);
                }
            }
        } else {
            flag = entity.hurt(this.damageSources().magic(), 5.0F );
        }
        IgnisExplosion explosion = new IgnisExplosion(level(), this,null,null, this.getX(), this.getY(), this.getZ(), 2f, true, Explosion.BlockInteraction.KEEP);
        explosion.explode();
        explosion.finalizeExplosion(3,0.75D);
        this.discard();

        if (flag && entity instanceof LivingEntity) {
            MobEffectInstance effectinstance1 = ((LivingEntity)entity).getEffect(ModEffect.EFFECTBLAZING_BRAND.get());
            int i = 2;
            if (effectinstance1 != null) {
                i += effectinstance1.getAmplifier();
                ((LivingEntity)entity).removeEffectNoUpdate(ModEffect.EFFECTBLAZING_BRAND.get());
            } else {
                --i;
            }

            i = Mth.clamp(i, 0, 4);
            MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTBLAZING_BRAND.get(), 200, i, false, false, true);
            ((LivingEntity)entity).addEffect(effectinstance);

        }


    }
}

protected void tickTackleAttack () {
    this.tackleTime++;
    Entity target = this.tyrannosaurus.getTarget();
    double distance = this.tyrannosaurus.distanceToSqr(target.getX(), target.getY(), target.getZ());

    if (distance > 24 && !this.tyrannosaurus.isTackling()) {
        if (this.tackleTime < 3) {
            this.tyrannosaurus.setDeltaMovement(0, this.tyrannosaurus.getDeltaMovement().y, 0);
            this.tyrannosaurus.getNavigation().stop();
        }
        if (this.tackleTime == 3) this.tyrannosaurus.playSound(UPSounds.TYRANNO_AGGRO.get(), 1.5F, 0.8F + this.tyrannosaurus.getRandom().nextFloat() * 0.1F);
        if (this.tackleTime > 3 && this.tackleTime < 26) {
            this.tyrannosaurus.setAggro(true);
            this.tyrannosaurus.getNavigation().moveTo(target, 2.2D);
        }
        if (this.tackleTime >= 26) {
            this.attackTime = 0;
            this.tackleTime = 0;
            this.tyrannosaurus.setTackling(false);
            this.tyrannosaurus.setAggro(false);
            this.tyrannosaurus.setAnimationState(0);
            if (this.tyrannosaurus.isAngry()) {
                this.tackleCooldown = this.tyrannosaurus.getRandom().nextInt(25) + 50;
            }
            else this.tackleCooldown = this.tyrannosaurus.getRandom().nextInt(100) + 50;
        }
    }
    else {
        this.attackTime++;
        this.tyrannosaurus.setTackling(true);
        if (this.attackTime == 10) {
            if (this.tyrannosaurus.distanceTo(target) < 4.7F) {
                this.tyrannosaurus.doHurtTarget(target);
            }
        }
        if (this.attackTime >= 39) {
            this.attackTime = 0;
            this.tackleTime = 0;
            this.tyrannosaurus.setTackling(false);
            this.tyrannosaurus.setAggro(false);
            this.tyrannosaurus.setAnimationState(0);
            if (this.tyrannosaurus.isAngry()) {
                this.tackleCooldown = this.tyrannosaurus.getRandom().nextInt(25) + 50;
            }
            else this.tackleCooldown = this.tyrannosaurus.getRandom().nextInt(100) + 50;
        }
    }
}

public void inventoryTick(ItemStack stack, @NotNull Level world, @NotNull Entity entity, int itemSlot, boolean isSelected) {
    boolean hitMob = false;
    if (stack.getTag() == null) {
        stack.setTag(new CompoundTag());
    } else {
        if (!(entity instanceof LivingEntity))
            return;
        int tempLungeTicks = MiscProperties.getLungeTicks((LivingEntity) entity);
        if (deathwormReceded) {
            if (tempLungeTicks > 0) {
                tempLungeTicks = tempLungeTicks - 4;
            }
            if (tempLungeTicks <= 0) {
                tempLungeTicks = 0;
                deathwormReceded = false;
                deathwormLaunched = false;
            }
        } else if (deathwormLaunched) {
            tempLungeTicks = 4 + tempLungeTicks;
            if (tempLungeTicks > 20 && !deathwormReceded) {
                deathwormReceded = true;
            }
        }

        if (MiscProperties.getLungeTicks((LivingEntity) entity) == 20) {
            if (entity instanceof Player) {
                Player player = (Player) entity;
                Vec3 Vector3d = player.getViewVector(1.0F).normalize();
                double range = 5;
                for (LivingEntity livingEntity : world.getEntitiesOfClass(LivingEntity.class, new AABB(player.getX() - range, player.getY() - range, player.getZ() - range, player.getX() + range, player.getY() + range, player.getZ() + range))) {
                    //Let's not pull/hit ourselves
                    if (livingEntity == entity)
                        continue;
                    Vec3 Vector3d1 = new Vec3(livingEntity.getX() - player.getX(), livingEntity.getY() - player.getY(), livingEntity.getZ() - player.getZ());
                    double d0 = Vector3d1.length();
                    Vector3d1 = Vector3d1.normalize();
                    double d1 = Vector3d.dot(Vector3d1);
                    boolean canSee = d1 > 1.0D - 0.5D / d0 && player.hasLineOfSight(livingEntity);
                    if (canSee) {
                        specialDamage++;
                        livingEntity.hurt(DamageSource.playerAttack((Player) entity), 3F);
                        livingEntity.knockback(0.5F, livingEntity.getX() - player.getX(), livingEntity.getZ() - player.getZ());
                    }
                }
            }
        }
        MiscProperties.setLungeTicks((LivingEntity) entity, tempLungeTicks);
    }
}

	public void flightMovement(float moveStrafe, float moveForward) {
		if(this.host.isInWater()) {
            this.host.moveSwimmingWithHeading(moveStrafe, moveForward);
            this.host.move(MoverType.SELF, this.host.motionX, this.host.motionY, this.host.motionZ);
            this.host.motionX *= 0.800000011920929D;
            this.host.motionY *= 0.800000011920929D;
            this.host.motionZ *= 0.800000011920929D;
        }
        else if(this.host.lavaContact()) {
            this.host.moveSwimmingWithHeading(moveStrafe, moveForward);
            this.host.move(MoverType.SELF, this.host.motionX, this.host.motionY, this.host.motionZ);
            this.host.motionX *= 0.5D;
            this.host.motionY *= 0.5D;
            this.host.motionZ *= 0.5D;
        }
        else {
        	float motion = 0.91F;
            if(this.host.onGround) {
            	motion = 0.54600006F;
                Block block = this.host.getEntityWorld().getBlockState(new BlockPos(MathHelper.floor(this.host.posX), MathHelper.floor(this.host.getEntityBoundingBox().minY) - 1, MathHelper.floor(this.host.posZ))).getBlock();
                if(block != null)
                	motion = block.slipperiness * 0.91F;
            }
            float flyingMotion = 0.16277136F / (motion * motion * motion);
            this.host.moveFlying(moveStrafe, moveForward, this.host.onGround ? 0.1F * flyingMotion : (float)(0.02F * this.speedModifier));

            motion = 0.91F;
            if(this.host.onGround) {
            	motion = 0.54600006F;
                Block block = this.host.getEntityWorld().getBlockState(new BlockPos(MathHelper.floor(this.host.posX), MathHelper.floor(this.host.getEntityBoundingBox().minY) - 1, MathHelper.floor(this.host.posZ))).getBlock();
                if(block != null)
                	motion = block.slipperiness * 0.91F;
            }

            if(this.host != null && this.host.getEntityBoundingBox() != null)
            	this.host.move(MoverType.SELF, this.host.motionX, this.host.motionY, this.host.motionZ);
            this.host.motionX *= (double)motion;
            this.host.motionY *= (double)motion;
            this.host.motionZ *= (double)motion;
        }

        this.host.prevLimbSwingAmount = this.host.limbSwingAmount;
        double deltaX = this.host.posX - this.host.prevPosX;
        double deltaZ = this.host.posZ - this.host.prevPosZ;
        float var7 = MathHelper.sqrt(deltaX * deltaX + deltaZ * deltaZ) * 4.0F;
        if(var7 > 1.0F) var7 = 1.0F;
        this.host.limbSwingAmount += (var7 - this.host.limbSwingAmount) * 0.4F;
        this.host.limbSwing += this.host.limbSwingAmount;
	}

public BrainActivityGroup<AoABoss> getFightTasks() {
	return BrainActivityGroup.fightTasks(
			new InvalidateAttackTarget<AoABoss>()
					.invalidateIf((entity, target) -> !DamageUtil.isAttackable(target) || distanceToSqr(target.position()) > Mth.square(getAttributeValue(Attributes.FOLLOW_RANGE))),
			new SetAdditionalAttackTargets<>()
					.withMemories(AoABrainMemories.SECOND_ATTACK_TARGET.get(), AoABrainMemories.THIRD_ATTACK_TARGET.get())
					.attackablePredicate((mob, memoryModuleType, livingEntity) -> DamageUtil.isAttackable(livingEntity) && EntityUtil.areProbablyEnemies(livingEntity, mob, true))
					.allowDuplicateTargeting()
					.whenTargeting((owner, memory, target) -> {
						if (memory == AoABrainMemories.SECOND_ATTACK_TARGET.get()) {
							setSynchedData(SECOND_HEAD_TARGET, target.getId());
						}
						else {
							setSynchedData(THIRD_HEAD_TARGET, target.getId());
						}
					}),
			new SetWalkTargetToAttackTarget<>()
					.speedMod((entity, target) -> 1.25f)
					.startCondition(entity -> hasAura() && !isAttackState(FIRE_BOMB_STATE))
					.stopIf(entity -> !hasAura()),
			new StayWithinDistanceOfAttackTarget<>()
					.startCondition(entity -> !hasAura())
					.stopIf(entity -> hasAura()),
			new StrafeTarget<>()
					.startCondition(entity -> !hasAura())
					.stopIf(entity -> hasAura()),
			new FirstApplicableBehaviour(
					new FireBombAttack(),
					new FlamethrowerAttack(),
					new OneRandomBehaviour<AoABoss>(
							Pair.of(new AnimatableRangedAttack(getSwingWarmupTicks(FIREBALL_STATE))
											.attackInterval(entity -> rand().numberBetween(getSwingDurationTicks(FIREBALL_STATE), getSwingDurationTicks(FIREBALL_STATE) * 2))
											.attackRadius((int)getAttributeValue(Attributes.FOLLOW_RANGE))
											.whenStarting(entity -> triggerAnim("Middle Head", "fireball"))
											.whenStopping(entity -> BrainUtils.setForgettableMemory((NethengeicWitherEntity)entity, SBLMemoryTypes.SPECIAL_ATTACK_COOLDOWN.get(), true, 21)),
									10),
							Pair.of(new CustomDelayedBehaviour<>(20)
											.whenActivating(entity -> toggleAura())
											.cooldownFor(entity -> entity.getRandom().nextIntBetweenInclusive(400, 800))
											.whenStarting(entity -> {
												triggerAnim("Middle Head", "fire_aura");

												entity.playSound(AoASounds.ENTITY_NETHENGEIC_BEAST_FLAME_AURA_ACTIVATE.get(), 2, 1);
											}),
									1
							)
					).startCondition(entity -> !BrainUtils.hasMemory(entity, SBLMemoryTypes.SPECIAL_ATTACK_COOLDOWN.get()))
			));
}

public void finish(Level level, BlockPos goldenBowlPosition, GoldenSacrificialBowlBlockEntity blockEntity,
                   @Nullable ServerPlayer castingPlayer, ItemStack activationItem) {
    //manually call content of Ritual.finish(), because we cannot access it via super
    level.playSound(null, goldenBowlPosition, OccultismSounds.POOF.get(), SoundSource.BLOCKS, 0.7f,
            0.7f);
    if (castingPlayer != null) {
        castingPlayer.sendSystemMessage(Component.translatable(this.getFinishedMessage(castingPlayer)));
        OccultismAdvancements.RITUAL.get().trigger(castingPlayer, this);
    }

    var shard = activationItem.copy();
    activationItem.shrink(1); //remove original activation item.

    ((ServerLevel) level).sendParticles(ParticleTypes.LARGE_SMOKE, goldenBowlPosition.getX() + 0.5,
            goldenBowlPosition.getY() + 0.5, goldenBowlPosition.getZ() + 0.5, 1, 0, 0, 0, 0);

    //copied and modified from soul gem item
    if (shard.has(DataComponents.ENTITY_DATA)) {
        // Get entity type directly from TypedEntityData - the "id" field is stripped from the NBT
        // by TypedEntityData.of() since the type is already stored in the TypedEntityData itself
        var typedEntityData = shard.get(DataComponents.ENTITY_DATA);
        var entityData = typedEntityData.copyTagWithoutId();
        EntityType<?> entityType = typedEntityData.type();

        //remove position from tag to allow the entity to spawn where it should be
        entityData.remove("Pos");

        //type.spawn uses the sub-tag EntityTag
        CompoundTag wrapper = new CompoundTag();
        wrapper.put("EntityTag", entityData);

        Entity entity = entityType.create(level, EntitySpawnReason.MOB_SUMMONED);
        entity.load(TagValueInput.create(ProblemReporter.DISCARDING, entity.registryAccess(), entityData));
        double dy = level.getBlockState(goldenBowlPosition).getShape(level, goldenBowlPosition).max(Direction.Axis.Y);
        entity.snapTo(goldenBowlPosition.getX() + 0.5,
                goldenBowlPosition.getY() + dy,
                goldenBowlPosition.getZ() + 0.5,
                level.getRandom().nextInt(360), 0);
        entity.setDeltaMovement(Vec3.ZERO);
        level.addFreshEntity(entity);

        if (entity instanceof FamiliarEntity familiar && castingPlayer != null)
            familiar.setFamiliarOwner(castingPlayer);

        if (entity instanceof DemonicPartner partner && castingPlayer != null)
            partner.setOwner(castingPlayer);
    }
    this.dropResultAndFlame(level, goldenBowlPosition, blockEntity, castingPlayer, ItemStack.EMPTY);
}

public void tick(LivingEntity entity) {
    if(isCharge()) {
        if (!entity.level().isClientSide()) {
            int temp = getTimer();
            setTimer(temp - 1);
            //Deal with rocket punch is valid
            if (temp > 0) {
                //Slightly enlarge player's hitbox
                AABB collideBox = entity.getBoundingBox().inflate(0.75f, 0.75f, 0.75f);

                //Collision Detection
                List<LivingEntity> checks = entity.level().getEntitiesOfClass(LivingEntity.class, collideBox);
                checks.remove(entity);

                //If any mob is detected
                if (!checks.isEmpty()) {
                    // spawn an watchEntity to simulate rocket punch effect
                    Wall_Watcher_Entity watchEntity = new Wall_Watcher_Entity(entity.level(), entity.blockPosition(), temp, effectiveChargeTime,
                            knockbackSpeedIndex, damagePerEffectiveCharge, dx, dz,
                            entity);

                    List<LivingEntity> impact = entity.level().getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(3.5f, 0.75f, 3.5f));
                    impact.remove(entity);

                    for (LivingEntity target : impact) {
                        // Deal damage
                        if (!target.isAlliedTo(entity)) {
                            boolean flag = target.hurt(entity.damageSources().mobProjectile(entity, entity), damagePerEffectiveCharge * effectiveChargeTime);
                            watchEntity.watch(target);
                            if (flag) {
                                target.playSound(SoundEvents.ANVIL_LAND, 1.5f, 0.8F);
                            }

                        }
                    }
                    entity.level().addFreshEntity(watchEntity);

                    // Player stop moving and clear pocket punch status
                    entity.setDeltaMovement(0, 0, 0);
                    entity.hurtMarked = true;
                    setCharge(false);
                }
            }
            if (entity.horizontalCollision || temp == 0) {
                setCharge(false);
            }
        }
    }
}

	public InteractionResult mobInteract(Player p_230254_1_, InteractionHand p_230254_2_) {
		ItemStack itemstack = p_230254_1_.getItemInHand(p_230254_2_);
		Item item = itemstack.getItem();

		if (item instanceof PaleopediaItem) {
			CompoundTag tag = itemstack.getTag();
            final List<Integer> already = new ArrayList<>(Ints.asList(tag.getIntArray("Pages")));
            if (!already.contains(EnumPaleoPages.PLESIOHADROS.ordinal())) {
				EnumPaleoPages.addPage(EnumPaleoPages.fromInt(EnumPaleoPages.PLESIOHADROS.ordinal()), itemstack);
				p_230254_1_.displayClientMessage(Component.translatable("paleopedia.plesiohadros_added"), true);
				return InteractionResult.SUCCESS;
			} else {
				p_230254_1_.displayClientMessage(Component.translatable("paleopedia.plesiohadros_already_added"), true);
				return InteractionResult.SUCCESS;
			}
		}
		if (!this.isTame()) {
			if (item == PFBlocks.COBBANIA.get().asItem()) {
				if (!p_230254_1_.getAbilities().instabuild) {
					itemstack.shrink(1);
				}

				if (this.random.nextInt(3) == 0 && !net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, p_230254_1_)) {
					this.tame(p_230254_1_);
					this.navigation.stop();
					this.setTarget((LivingEntity)null);
					this.setOrderedToSit(true);
					this.level().broadcastEntityEvent(this, (byte)7);
				} else {
					this.level().broadcastEntityEvent(this, (byte)6);
				}
				return InteractionResult.SUCCESS;
			}
		} 
		if (!this.isSaddled() && !this.isBaby() && this.isTame()) {
			if (item == Items.SADDLE) {
				if (!p_230254_1_.getAbilities().instabuild) {
					itemstack.shrink(1);
				}
				this.setSaddled(true);
				this.level().playSound(p_230254_1_, this.getX(), this.getY(), this.getZ(), SoundEvents.PIG_SADDLE, SoundSource.NEUTRAL, 0.5F, 1.0F);
