			}
		}
		if (this.isSaddled() && !this.isVehicle() && !this.isBaby()) {
			p_230254_1_.startRiding(this);
		}
		return super.mobInteract(p_230254_1_, p_230254_2_);
	}

public void tick() {
    if(chargeCooldown > 0){
        chargeCooldown--;
    }
    if(chargeTimeout > 100){
        chargeTimeout = 0;
        candicorn.setCharging(false);
    }
    LivingEntity target = candicorn.getTarget();
    if (target != null && target.isAlive()) {
        double distance = candicorn.distanceTo(target);
        double chargeFromDistance = 15;
        double attackDistance = candicorn.getBbWidth() + target.getBbWidth() + 0.5F;
        candicorn.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
        if (candicorn.getAnimation() == CandicornEntity.ANIMATION_STAB) {
            candicorn.getNavigation().stop();
            if(candicorn.getAnimationTick() > 8 && candicorn.getAnimationTick() <= 12){
                if(target.hurt(target.damageSources().mobAttack(candicorn), (float) candicorn.getAttribute(Attributes.ATTACK_DAMAGE).getValue())){
                    target.knockback(0.6F, candicorn.getX() - target.getX(), candicorn.getZ() - target.getZ());
                }
            }
        } else {
            if(candicorn.isCharging()){
                chargeTimeout++;
                candicorn.getNavigation().stop();
                Vec3 sub = startChargeTargetVec.subtract(startChargeFromVec);
                Vec3 delta = sub.normalize().scale(0.85);
                candicorn.setDeltaMovement(candicorn.getDeltaMovement().scale(0.9).add(delta));
                candicorn.setChargeYaw(Mth.wrapDegrees((float)(Mth.atan2(sub.z, sub.x) * (double)(180F / (float)Math.PI)) - 90.0F));
                if((distance < attackDistance || candicorn.distanceToSqr(startChargeTargetVec) < attackDistance * attackDistance) && candicorn.getChargeProgress(1.0F) == 1.0F && candicorn.hasLineOfSight(target)){
                    chargeCooldown = 100;
                    candicorn.setCharging(false);
                }
                candicorn.setRunning(true);
            }else if(distance > attackDistance && distance < chargeFromDistance && chargeCooldown <= 0 && !candicorn.isCharging() && candicorn.hasLineOfSight(target)){
                candicorn.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                candicorn.setCharging(true);
                startChargeTargetVec = target.position();
                startChargeFromVec = candicorn.position();
            }else if (distance < attackDistance && candicorn.getAnimation() == IAnimatedEntity.NO_ANIMATION && candicorn.hasLineOfSight(target) && !candicorn.isCharging()) {
                candicorn.setAnimation(CandicornEntity.ANIMATION_STAB);
            }else if (distance > attackDistance) {
                this.candicorn.getNavigation().moveTo(target, 1.0D);
                candicorn.setRunning(true);
            } else {
                candicorn.setRunning(false);
            }
        }
    }
}

public void tick() {
    LivingEntity target = entity.getTarget();
    if (target != null) {
        double dist = entity.distanceTo(target);
        if (dist > 13 && !leapingAttack && entity.leapAttackCooldown >= 0 && (entity.isInWall() || entity.onGround()) && leapTicks == 0) {
            leapingAttack = true;
            maxLeapTicks = 15 + entity.getRandom().nextInt(8);
            leapTicks = 0;
        }
        if (leapingAttack) {
            entity.getNavigation().stop();
            if ((entity.isInWall()) && !entity.isLeaping()) {
                entity.setLeaping(true);
                entity.leapAttackCooldown = 330;
            }
            if (entity.isLeaping()) {
                Vec3 leapOnPos = target.position().subtract(entity.position());
                float f = -((float) Mth.atan2(leapOnPos.x, leapOnPos.z)) * 180.0F / (float) Math.PI;
                entity.setYRot(f);
                float f1 = (float) (-(Mth.atan2(leapOnPos.y, leapOnPos.horizontalDistance()) * (double) (180F / (float) Math.PI)));
                entity.setTargetDigPitch(f1);
                if (this.leapTicks <= maxLeapTicks) {
                    this.leapTicks++;
                    float leapUp = (float) ((1F - leapTicks / (float) maxLeapTicks) * 8 * leapHeight);
                    Vec3 delta = leapOnPos.scale(0.1F);
                    entity.setDeltaMovement(entity.getDeltaMovement().scale(0.1F).add(delta.add(0, leapUp, 0)));
                } else {
                    leapingAttack = false;
                    leapTicks = 0;
                    entity.leapAttackCooldown = 300;
                }
            }
        } else {
            entity.getNavigation().moveTo(target, 1.0D);
            entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            if(entity.isLeaping()){
                entity.setLeaping(false);
            }
        }
        if (entity.isMouthOpen()) {
            if (entity.attackAllAroundMouth((float) entity.getAttribute(Attributes.ATTACK_DAMAGE).getValue(), 2.0F)) {
                entity.timeBetweenAttacks = leapingAttack ? 100 : 20;
                entity.leapAttackCooldown = 300;
                leapingAttack = false;
                entity.attemptPlayAttackNoise();
            }
        }
        entity.setBiting(dist < 15 + target.getBbWidth());
    }
}

public void updateTask() {
	EntityLivingBase target = this.entity.getAttackTarget();

	if(target != null && this.canMove()) {
		if(this.findBlocksCooldown <= 0 && (this.trackingBlocks == null || this.trackingBlocks.isEmpty())) {
			this.findBlocksCooldown = 20 + this.entity.rand.nextInt(40);
			this.trackingBlocks = this.entity.findNearbyBlocksForMovement();
		}

		if(this.trackingBlocks != null && !this.trackingBlocks.isEmpty() && this.checkCooldown <= 0) {
			this.checkCooldown = 5 + this.entity.rand.nextInt(15);

			for(int i = 0; i < 16; i++) {
				if(this.trackingBlocks.isEmpty()) {
					break;
				}

				BlockPos pos = this.trackingBlocks.remove(this.entity.rand.nextInt(this.trackingBlocks.size()));

				if(!this.stayInRange || target.getDistanceSqToCenter(pos) <= this.maxRangeSq) {
					Vec3d center = new Vec3d(pos.getX() + this.entity.getBlockWidth() / 2.0D, pos.getY() + this.entity.getBlockHeight() / 2.0D, pos.getZ() + this.entity.getBlockWidth() / 2.0D);
					Vec3d lookDir = target.getPositionVector().add(0, target.getEyeHeight(), 0).subtract(center);

					EnumFacing facing = EnumFacing.getFacingFromVector((float)lookDir.x, (float)lookDir.y, (float)lookDir.z);

					if(this.canSeeFrom(pos, facing, target) && this.entity.checkAnchorAt(center, lookDir, AnchorChecks.ALL) == 0) {
						this.entity.moveHelper.setMoveTo(center.x, center.y, center.z, 1);
						this.entity.lookHelper.setLookDirection(facing.getXOffset(), facing.getYOffset(), facing.getZOffset());
						break;
					} else {
						for(EnumFacing otherFacing : EnumFacing.HORIZONTALS) {
							if(otherFacing != facing) {
								lookDir = new Vec3d(otherFacing.getXOffset(), 0, otherFacing.getZOffset());

								if(this.canSeeFrom(pos, otherFacing, target) && this.entity.checkAnchorAt(center, lookDir, AnchorChecks.ALL) == 0) {
									this.entity.moveHelper.setMoveTo(center.x, center.y, center.z, 1);
									this.entity.lookHelper.setLookDirection(otherFacing.getXOffset(), otherFacing.getYOffset(), otherFacing.getZOffset());
									break;
								} 
							}
						}
					}
				}
			}
		}

		this.checkCooldown--;
		this.findBlocksCooldown--;
	}
}

public boolean shouldExecute() {
    if (this.entity.getRNG().nextInt(10) != 0) {
        return false;
    }

    if (!this.entity.getMetabolism().isHungry() && RebornConfig.ENTITIES.huntWhenHungry) {
        return false;
    }

    Entity target = this.entity.getAttackTarget();
    if (target != null && !target.isDead && this.entity.getEntitySenses().canSee(target) ) {
        return false;
    }

    if (!(this.entity.herd != null && this.entity.herd.fleeing) && this.entity.getAgePercentage() > 50 && (this.entity.getOwner() == null || this.entity.getMetabolism().isStarving()) && !this.entity.isSleeping() && this.entity.getAttackCooldown() <= 0) {
        List<EntityLivingBase> entities = this.entity.world.getEntitiesWithinAABB(EntityLivingBase.class, this.entity.getEntityBoundingBox().grow(16.0D, 16.0D, 16.0D));

        if (entities.size() > 0) {
            this.targetEntity = null;
            double bestScore = Double.MAX_VALUE;

            Collections.sort(entities, this.sorter);

            for (EntityLivingBase entity : entities) {
                if (!entity.equals(this.entity) && !entity.isInLava() && this.entity.getEntitySenses().canSee(entity) && this.canAttack(entity)) {
                    double score = entity.getHealth() <= 0.0F ? (this.entity.getDistanceSq(entity) / entity.getHealth()) : 0;

                    if (entity.isInWater()) {
                        score *= 3;
                    }

                    if (score < bestScore) {
                        bestScore = score;

                        if (entity.getRidingEntity() instanceof EntityLivingBase) {
                            this.targetEntity = (EntityLivingBase) entity.getRidingEntity();
                        } else {
                            this.targetEntity = entity;
                        }
                    }
                }

            }

            return this.targetEntity != null;
        }
    }

    return false;
}

    public void onUpdate() {
    	this.updateTick++;

        if(!this.movement) {
            this.inGround = false;
            this.timeUntilPortal = this.getPortalCooldown();
        }
        double initX = this.posX;
        double initY = this.posY;
        double initZ = this.posZ;

		super.onUpdate();

        if(!this.movement) {
            this.posX = initX;
            this.posY = initY;
            this.posZ = initZ;
            this.motionX = 0;
            this.motionY = 0;
            this.motionZ = 0;
            this.setPosition(this.posX, this.posY, this.posZ);
        }

    	this.isInWeb = false;

    	// Terrain Destruction
    	if(!this.getEntityWorld().isRemote) {
    		if(!this.waterProof && this.isInWater())
    			this.setDead();
    		else if(!this.lavaProof && this.isInLava())
    			this.setDead();
    	}
        if(!this.getEntityWorld().isRemote || this.clientOnly) {
            if(this.projectileLife-- <= 0)
                this.setDead();
        }

        // Sync Scale:
        if(this.getEntityWorld().isRemote) {
            this.projectileScale = this.dataManager.get(SCALE);
        }

        // Animation:
        if(this.animationFrameMax > 0) {
            if (this.animationFrame == this.animationFrameMax || this.animationFrame < 0)
                this.animationFrame = 0;
            else
                this.animationFrame++;
        }
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int range = spellStat.getRange();
    int radius = (int) spellStat.getRadius();
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    int burning = spellStat.getBurning();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, 3);
    LivingEntity target = this.getTarget(caster, range);
    BlockPos blockPos = caster.blockPosition();
    if (target != null){
        blockPos = target.blockPosition();
    } else if (rayTraceResult instanceof BlockHitResult blockHitResult){
        blockPos = blockHitResult.getBlockPos().above();
    }
    Volcano volcano = ModEntityType.VOLCANO.get().create(worldIn);
    if (volcano != null){
        volcano.setTrueOwner(caster);
        volcano.setPos(blockPos.getX() + 0.5D, blockPos.getY(), blockPos.getZ() + 0.5D);
        volcano.finalizeSpawn(worldIn, worldIn.getCurrentDifficultyAt(blockPos), MobSpawnType.MOB_SUMMONED, null, null);
        volcano.setExplosionPower(volcano.getExplosionPower() + (radius / 2.0F));
        volcano.setLifeSpan(6 * duration);
        volcano.setPotency(potency);
        volcano.setFlaming(burning);
        volcano.setUpgraded(SpellConfig.PyroclastStun.get());
        worldIn.addFreshEntity(volcano);
    }
    if (this.rightStaff(staff)) {
        for (int i = 0; i < 2; ++i) {
            blockPos = blockPos.offset(-4 + worldIn.random.nextInt(8), 0, -4 + worldIn.random.nextInt(8));
            Vec3 vec3 = Vec3.atBottomCenterOf(blockPos);
            Volcano volcano2 = new Volcano(ModEntityType.VOLCANO.get(), worldIn);
            volcano2.setTrueOwner(caster);
            volcano2.setPos(vec3.x(), vec3.y(), vec3.z());
            volcano2.finalizeSpawn(worldIn, worldIn.getCurrentDifficultyAt(blockPos), MobSpawnType.MOB_SUMMONED, null, null);
            volcano2.setExplosionPower(volcano2.getExplosionPower() + (radius / 2.0F));
            volcano2.setLifeSpan(6 * duration);
            volcano2.setPotency(potency);
            volcano2.setFlaming(burning);
            volcano2.setUpgraded(SpellConfig.PyroclastStun.get());
            worldIn.addFreshEntity(volcano2);
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    float velocity = spellStat.getVelocity();
    double radius = spellStat.getRadius();
    Vec3 vector3d = caster.getViewVector( 1.0F);
    Vec3 vec3 = vector3d;
    LivingEntity livingEntity = this.getTarget(caster);
    if (livingEntity != null) {
        double d1 = livingEntity.getX() - caster.getX();
        double d2 = livingEntity.getY(0.5D) - caster.getY(0.5D);
        double d3 = livingEntity.getZ() - caster.getZ();
        vec3 = new Vec3(d1, d2, d3);
    }
    AbstractCyclone cyclone = new Cyclone(worldIn,
            caster,
            vec3.x,
            vec3.y,
            vec3.z);
    if (CuriosFinder.hasUnholySet(caster)){
        cyclone = new FireTornado(worldIn,
                caster,
                vec3.x,
                vec3.y,
                vec3.z);
    }
    cyclone.setOwner(caster);
    if (livingEntity != null) {
        cyclone.setTarget(livingEntity);
    }
    if (rightStaff(staff)){
        radius += 1.0F;
        potency += 1;
    }
    if (WandUtil.enchantedFocus(caster)){
        potency *= (WandUtil.getPotencyLevel(caster) + 1);
        duration *= (WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1);
        velocity += WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster);
        radius += (WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 10.0F);
    }
    cyclone.setDamage(potency);
    cyclone.setTotalLife(duration);
    cyclone.setBoltSpeed((int) velocity);
    cyclone.setSize((float) (radius));
    cyclone.setPos(caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.2,
            caster.getZ() + vector3d.z / 2);
    worldIn.addFreshEntity(cyclone);
    this.playSound(worldIn, caster, 1.0F, 1.0F);
}

public void serverTick() {
    if (tryTicks > 0) {
        tryTicks++;
    }
    if (mob.isBaby()) {
        attachCooldown = 150;
        return;
    }
    if (attachCooldown > 0) {
        attachCooldown--;
    }
    if (!isAttached() && targetLocation != null) {
        double dist = targetLocation.distanceTo(mob.position());
        if (dist < 1) {
            mob.getMoveControl().setWantedPosition(targetLocation.x, targetLocation.y, targetLocation.z, 0.9);
            mob.getNavigation().stop();
            if (!attachStarted()) {
                approachAttachPos();
            }
            if (dist < 0.2) {
                startAttaching();
            }
        }
    }
    if (isAttached()) {
        attachTicks++;
        mob.setDeltaMovement(Vec3.ZERO);
    }
    if (attachStarted() && targetBlockPos != null) {
        mob.setYRot(0);
        mob.setXRot(0);
        mob.yBodyRot = 0;
        mob.yHeadRot = 0;
        if (!mob.level.getBlockState(targetBlockPos).isFaceSturdy(mob.level, targetBlockPos, getAttachmentFace())) {
            stopAttaching();
        }
        if (isAttached()) {
            if (!mob.isSleeping() && mob.getCurrentOrder() != OrderType.STAY && (attachTicks > MAX_ATTACH_TICKS && mob.getRandom().nextInt(123) == 0 || mob.getTarget() != null)) {
                stopAttaching(1000 + mob.getRandom().nextInt(1500));
            }

            if (mob.getCurrentOrder() == OrderType.FOLLOW) {
                stopAttaching();
            }
        }
    }
    if (tryTicks > MAX_TRY_TICKS) {
        stopAttaching();
    }
}

public BrainActivityGroup<AoABoss> getFightTasks() {
	return BrainActivityGroup.fightTasks(
			new InvalidateAttackTarget<AoABoss>()
					.invalidateIf((entity, target) -> !DamageUtil.isAttackable(target) || distanceToSqr(target.position()) > Mth.square(getAttributeValue(Attributes.FOLLOW_RANGE))),
			new SetAdditionalAttackTargets<>()
					.withMemories(AoABrainMemories.SECOND_ATTACK_TARGET.get(), AoABrainMemories.THIRD_ATTACK_TARGET.get())
					.attackablePredicate((mob, memoryModuleType, livingEntity) -> DamageUtil.isAttackable(livingEntity) && EntityUtil.areProbablyEnemies(livingEntity, mob, true))
					.allowDuplicateTargeting()
					.whenTargeting((owner, memory, target) -> {
						if (memory == AoABrainMemories.SECOND_ATTACK_TARGET.get()) {
							setSynchedData(SECOND_HEAD_TARGET, target.getId());
						}
						else {
							setSynchedData(THIRD_HEAD_TARGET, target.getId());
						}
					}),
			new SetWalkTargetToAttackTarget<>()
					.speedMod((entity, target) -> 1.5f)
					.startCondition(entity -> hasAura() && !isAttackState(FIRE_BOMB_STATE))
					.stopIf(entity -> !hasAura()),
			new StayWithinDistanceOfAttackTarget<>()
					.startCondition(entity -> !hasAura())
					.stopIf(entity -> hasAura()),
			new StrafeTarget<>()
					.startCondition(entity -> !hasAura())
					.stopIf(entity -> hasAura()),
			new FirstApplicableBehaviour(
					new FlamethrowerAttack(MemoryModuleType.ATTACK_TARGET, entity -> PositionAndMotionUtil.moveRelativeToFacing(entity.getEyePosition(), entity.getYRot(), 0, 1, 0)),
					new FireBombAttack(),
					new OneRandomBehaviour<AoABoss>(
							Pair.of(new AnimatableRangedAttack(getSwingWarmupTicks(FIREBALL_STATE))
											.attackInterval(entity -> rand().numberBetween(getSwingDurationTicks(FIREBALL_STATE), (int)Math.floor(getSwingDurationTicks(FIREBALL_STATE) * 1.5f)))
											.attackRadius((int)getAttributeValue(Attributes.FOLLOW_RANGE))
											.whenStarting(entity -> triggerAnim("Middle Head", "fireball"))
											.whenStopping(entity -> BrainUtils.setForgettableMemory((EliteNethengeicWitherEntity)entity, SBLMemoryTypes.SPECIAL_ATTACK_COOLDOWN.get(), true, 21)),
									10),
							Pair.of(new CustomDelayedBehaviour<>(20)
											.whenActivating(entity -> toggleAura())
											.cooldownFor(entity -> entity.getRandom().nextIntBetweenInclusive(400, 800))
											.whenStarting(entity -> {
												triggerAnim("Middle Head", "fire_aura");

												entity.playSound(AoASounds.ENTITY_NETHENGEIC_BEAST_FLAME_AURA_ACTIVATE.get(), 2, 1);
											})
											.startCondition(entity -> !BrainUtils.hasMemory(entity, SBLMemoryTypes.SPECIAL_ATTACK_COOLDOWN.get())),
									1
							)
					)
			));
}

public void tick() {
    super.tick();
    if (this.tickCount == 1) {
        if(this.getLifespan() == 0){
            this.setLifespan(2000);
        }
    }
    if(!madeOpenNoise){
        this.gameEvent(GameEvent.ENTITY_PLACE);
        this.playSound(SoundEvents.END_PORTAL_SPAWN, 1.0F, 1 + random.nextFloat() * 0.2F);
        madeOpenNoise = true;
    }
    if(random.nextFloat() < 0.5F && level().isClientSide && Math.min(tickCount, this.getLifespan()) >= 20){
        double particleX = this.getBoundingBox().minX + random.nextFloat() * (this.getBoundingBox().maxX - this.getBoundingBox().minX);
        double particleY = this.getBoundingBox().minY + random.nextFloat() * (this.getBoundingBox().maxY - this.getBoundingBox().minY);
        double particleZ = this.getBoundingBox().minZ + random.nextFloat() * (this.getBoundingBox().maxZ - this.getBoundingBox().minZ);
        level().addParticle(ParticleTypes.PORTAL, particleX, particleY, particleZ, 0.1 * random.nextGaussian(), 0.1 * random.nextGaussian(), 0.1 * random.nextGaussian());
    }
    List<Entity> entities = new ArrayList<>();
    entities.addAll(this.level().getEntities(this, this.getBoundingBox().deflate(0.2F)));
    entities.addAll(this.level().getEntitiesOfClass(The_Leviathan_Entity.class, this.getBoundingBox().inflate(3)));
    if (!level().isClientSide) {
        if (this.getDestination() != null && this.getLifespan() > 20 && tickCount > 20 && this.getEntrance()) {
            for (Entity e : entities) {
                if(e.isOnPortalCooldown() || e.isShiftKeyDown() || e instanceof Abyss_Portal_Entity ){
                    continue;
                }
                 if (e instanceof The_Leviathan_Entity) {
                    ((The_Leviathan_Entity) e).teleportTo(Vec3.atCenterOf(this.getDestination()));
                    e.setPortalCooldown();
                    ((The_Leviathan_Entity) e).resetPortalLogic();
                }else {
                    e.teleportTo(this.getDestination().getX() + 0.5f, this.getDestination().getY() + 0.5f, this.getDestination().getZ() + 0.5f);
                    e.setPortalCooldown();
                 }
            }
        }
    }
    this.setLifespan(this.getLifespan() - 1);
    if(this.getLifespan() <= 20){
        if(!madeCloseNoise){
            this.gameEvent(GameEvent.ENTITY_PLACE);
          //  this.playSound(AMSoundRegistry.VOID_PORTAL_CLOSE.get(), 1.0F, 1 + random.nextFloat() * 0.2F);
            madeCloseNoise = true;
        }
    }
    if (this.getLifespan() <= 0) {
        this.remove(RemovalReason.DISCARDED);
    }
}

protected void onHitEntity(EntityHitResult p_37626_) {
    super.onHitEntity(p_37626_);
    Entity entity = p_37626_.getEntity();
    Entity shooter = this.getOwner();

    if (this.level() instanceof ServerLevel serverlevel && getFired() && !(entity instanceof Ignis_Fireball_Entity || entity instanceof Ignis_Abyss_Fireball_Entity || entity instanceof Cm_Falling_Block_Entity || entity instanceof Ignis_Entity && shooter instanceof Ignis_Entity)) {
        boolean flag;
        if (shooter instanceof LivingEntity owner) {
            DamageSource damagesource = this.damageSources().mobProjectile(this, owner);
            float damage = this.isSoul() ? 8.0F : 6.0F;
            if (entity instanceof LivingEntity) {
                flag = entity.hurt(damageSources().mobProjectile(this, owner), damage + ((LivingEntity) entity).getMaxHealth() * 0.07f);
            }else{
                flag = entity.hurt(damageSources().mobProjectile(this, owner), damage);
            }

            if (flag) {
                if (entity.isAlive()) {
                    this.doEnchantDamageEffects(owner, entity);
                }
                if(owner instanceof Ignis_Entity) {
                    owner.heal(5.0F * (float) CMCommonConfig.Ignis.HealingMultiplier);
                }else{
                    owner.heal(5.0F);
                }
            }
        } else {
            flag = entity.hurt(this.damageSources().magic(), 5.0F);
        }
        if (flag && entity instanceof LivingEntity) {
            MobEffectInstance effectinstance1 = ((LivingEntity)entity).getEffect(ModEffect.EFFECTBLAZING_BRAND.get());
            int i = 2;
            if (effectinstance1 != null) {
                i += effectinstance1.getAmplifier();
                ((LivingEntity)entity).removeEffectNoUpdate(ModEffect.EFFECTBLAZING_BRAND.get());
            } else {
                --i;
            }

            i = Mth.clamp(i, 0, 4);
            MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTBLAZING_BRAND.get(), 200, i, false, false, true);
            ((LivingEntity)entity).addEffect(effectinstance);

        }
        IgnisExplosion explosion = new IgnisExplosion(level(), this,null,null, this.getX(), this.getY(), this.getZ(), 1f, true, Explosion.BlockInteraction.KEEP);
        explosion.explode();
        explosion.finalizeExplosion(this.isSoul() ?2 :1,0.35D);
        this.discard();
    }
}

public void tick() {
    if (destinationBlock == null || this.crab.passive) stop();
    Vec3 vec = Vec3.atCenterOf(destinationBlock);
    if (vec != null) {
        timer++;
        double dist = crab.blockPosition().distToCenterSqr(vec.x, vec.y, vec.z);
        if (dist > 2D) {
            crab.getNavigation().moveTo(vec.x - 0.5, vec.y + 1, vec.z - 0.5, 1F);
        } else if (crab.distanceToSqr(vec) <= 2F) {
            crab.entityData.set(FEEDING_POS, Optional.of(destinationBlock));
            Vec3 face = vec.subtract(crab.position());
            crab.setDeltaMovement(crab.getDeltaMovement().add(face.normalize().scale(0.1F)));
            crab.setFeedingTime(crab.getFeedingTime() + 1);
            crab.playSound(SoundEvents.SAND_BREAK, crab.getSoundVolume(), crab.getVoicePitch());
            if (crab.getFeedingTime() > maxFeedTime) {
                if (random.nextInt(1) == 0) {
                    List<ItemStack> lootList = getDigLoot(crab);
                    if (lootList.size() > 0) {
                        for (ItemStack stack : lootList) {
                            ItemEntity e = crab.spawnAtLocation(stack.copy());
                            e.hasImpulse = true;
                            e.setDeltaMovement(e.getDeltaMovement().multiply(0.2, 0.2, 0.2));
                        }
                    }

                }
                stop();
            } else {
                BlockPos feedingPos = this.crab.entityData.get(FEEDING_POS).orElse(null);
                double d0 = face.horizontalDistance();
                this.crab.setXRot((float) (-Mth.atan2(face.y, d0) * (double) (180F / (float) Math.PI)));
                this.crab.setYRot(((float) Mth.atan2(face.z, face.x)) * (180F / (float) Math.PI) - 90F);
                this.crab.yBodyRot = this.crab.getYRot();
                this.crab.yHeadRot = this.crab.getYRot();
                BlockState state = level().getBlockState(feedingPos);
                if (random.nextInt(2) == 0 && !state.isAir()) {
                    Vec3 mouth = new Vec3(0, this.crab.getBbHeight() * 0.5F, 0.4F * -0.5).xRot(this.crab.getXRot() * ((float) Math.PI / 180F)).yRot(-this.crab.getYRot() * ((float) Math.PI / 180F));
                    for (int i = 0; i < 4 + random.nextInt(2); i++) {
                        double motX = this.crab.random.nextGaussian() * 0.02D;
                        double motY = 0.1F + random.nextFloat() * 0.2F;
                        double motZ = this.crab.random.nextGaussian() * 0.02D;
                        ((ServerLevel)level()).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, state), this.crab.getX() - mouth.x, this.crab.getY() + mouth.y, this.crab.getZ() - mouth.z, 1,  motX, motY, motZ, 0.1D);
                    }
                }
            }
        } else {
            crab.entityData.set(FEEDING_POS, Optional.empty());
        }
    }
}

protected void onHitEntity(EntityHitResult result) {
    Entity target = result.getEntity();
    Entity shooter = this.getOwner();

    float motion = (float) this.getDeltaMovement().length();
    int damage = Mth.ceil(Mth.clamp((double) motion * 0.5F * this.getBaseDamage(), 0.0D, 2.147483647E9D));

    DamageSource damagesource = UPDamageTypes.shuriken(this.level(), this, shooter);

    if (shooter instanceof LivingEntity living) {
        living.setLastHurtMob(target);
    }

    boolean isEnderman = target.getType() == EntityType.ENDERMAN;
    if (this.isOnFire() && !isEnderman) {
        target.setSecondsOnFire(5);
    }

    if (target.hurt(damagesource, (float) damage)) {
        if (isEnderman) return;

        if (target instanceof LivingEntity livingTarget) {

            if (!this.level().isClientSide() && shooter instanceof LivingEntity) {
                EnchantmentHelper.doPostHurtEffects(livingTarget, shooter);
                EnchantmentHelper.doPostDamageEffects((LivingEntity) shooter, livingTarget);
            }

            this.doPostHurtEffects(livingTarget);
            if (livingTarget != shooter && livingTarget instanceof Player && shooter instanceof ServerPlayer && !this.isSilent()) {
                ((ServerPlayer) shooter).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
            }

        }

        this.playSound(this.getDefaultHitGroundSoundEvent(), 1.0F, 1.25F / (this.random.nextFloat() * 0.2F + 0.9F));
    }
    else {
        target.setRemainingFireTicks(target.getRemainingFireTicks());
        this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
        this.setYRot(this.getYRot() + 180.0F);
        this.yRotO += 180.0F;
        if (!this.level().isClientSide() && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
            if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                this.spawnAtLocation(this.getPickupItem(), 0.1F);
            }
            this.discard();
        }
    }
}

public void tick() {
    super.tick();
    if (this.movesEntities() && this.getDeltaMovement().length() > 0) {
        moveEntitiesOnTop();
    }
    this.move(MoverType.SELF, this.getDeltaMovement());
    if (!level().isClientSide && canBePlaced()) {
        if (placementCooldown > 0) {
            placementCooldown--;
        } else {
            boolean clearance = true;
            BlockPos pos = BlockPos.containing(this.getX(), this.getY(), this.getZ());
            for (MovingBlockData dataBlock : this.getData()) {
                BlockPos set = pos.offset(dataBlock.getOffset());
                BlockState at = level().getBlockState(set);
                if (at.isAir()) {
                    continue;
                } else if (at.canBeReplaced()) {
                    level().destroyBlock(set, true);
                    continue;
                }
                clearance = false;
            }
            if (clearance) {
                for (MovingBlockData dataBlock : this.getData()) {
                    BlockPos set = pos.offset(dataBlock.getOffset());
                    level().setBlockAndUpdate(set, dataBlock.getState());
                    if (dataBlock.blockData != null && dataBlock.getState().hasBlockEntity()) {
                        BlockEntity blockentity = this.level().getBlockEntity(set);
                        if (blockentity != null) {
                            CompoundTag compoundtag = blockentity.saveWithoutMetadata();
                            for (String s : dataBlock.blockData.getAllKeys()) {
                                compoundtag.put(s, dataBlock.blockData.get(s).copy());
                            }
                            try {
                                blockentity.load(compoundtag);
                            } catch (Exception exception) {
                            }
                            blockentity.setChanged();
                        }
                    }
                }
                this.remove(RemovalReason.KILLED);

            } else {
                placementCooldown = 5 + random.nextInt(10);
            }
        }
    }
    this.setDeltaMovement(this.getDeltaMovement().scale(0.98D));
}

public void tick() {
    this.noPhysics = true;
    super.tick();
    this.prevHidingProgress = hidingProgress;
    this.noPhysics = false;
    if(this.isHiding() && hidingProgress < 10F){
        this.hidingProgress++;
    }
    if(!this.isHiding() && hidingProgress > 0F){
        hidingProgress--;
    }
    if (!this.level().isClientSide) {
        final double xzSpeed = this.getDeltaMovement().horizontalDistance();
        final double distToFloor = Mth.clamp(calculateDistanceToFloor(), -1F, 1F);
        if (Math.abs(distToFloor) > 0.01 && xzSpeed < 0.05 && !this.isActuallyInAWall()) {
            if (distToFloor < 0.0) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -Math.min(distToFloor * 0.1F, 0F), 0));
            } else if (distToFloor > 0.0) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -Math.max(distToFloor * 0.1F, 0F), 0));
            }
        }
        if(lastPosition != null && lastPosition.distSqr(this.blockPosition()) > 2.5F && Math.abs(distToFloor) < 0.5){
            this.playSound(AMSoundRegistry.UNDERMINER_STEP.get(), 1F, 0.75F + random.nextFloat() * 0.25F);
            lastPosition = this.blockPosition();
            if(random.nextFloat() < 0.015F && !level().canSeeSky(lastPosition)){
                this.playSound(SoundEvents.AMBIENT_CAVE.get(), 3F, 0.75F + random.nextFloat() * 0.25F);
            }
        }
        Player player = this.level().getNearestPlayer(this.getX(), this.getY(), this.getZ(), AMConfig.underminerDisappearDistance, true);
        if(player != null && lastGivenStack == null && (this.getTarget() == null || !this.getTarget().isAlive())){
            this.setHiding(true);
            this.lookAt(player, 360F, 360F);
        }else{
            this.setHiding(false);
        }
    }
    this.setYBodyRot(this.getYRot());

    if(mineCooldown > 0){
        mineCooldown--;
    }
    if(resetStackTime > 0){
        resetStackTime--;
        if(resetStackTime == 0){
            lastGivenStack = null;
        }
    }
    if(entityData.get(VISUALLY_MINING)){
        this.swing(InteractionHand.MAIN_HAND);
    }
}

    public void onLivingUpdate() {
        super.onLivingUpdate();

		// Pull:
		if(!this.getEntityWorld().isRemote) {
			if(this.pullRecharging) {
				if(++this.pullEnergyRecharge >= this.pullEnergyRechargeMax) {
					this.pullRecharging = false;
					this.pullEnergy = this.pullEnergyMax;
					this.pullEnergyRecharge = 0;
				}
			}
			this.pullEnergy = Math.min(this.pullEnergy, this.pullEnergyMax);
			if(this.canPull()) {
				for (EntityLivingBase entity : this.getNearbyEntities(EntityLivingBase.class, null, this.pullRange)) {
					if (entity == this || entity == this.getControllingPassenger() || entity instanceof IGroupBoss || entity instanceof IGroupHeavy || entity.isPotionActive(ObjectManager.getPotionEffect("weight")) || !this.canAttackEntity(entity))
						continue;
					EntityPlayerMP player = null;
					if (entity instanceof EntityPlayerMP) {
						player = (EntityPlayerMP) entity;
						if (player.capabilities.isCreativeMode)
							continue;
					}
					double xDist = this.posX - entity.posX;
					double zDist = this.posZ - entity.posZ;
					double xzDist = MathHelper.sqrt(xDist * xDist + zDist * zDist);
					double factor = 0.1D;
					double motionCap = 10;
					if(entity.motionX < motionCap && entity.motionX > -motionCap && entity.motionZ < motionCap && entity.motionZ > -motionCap) {
						entity.addVelocity(
								xDist / xzDist * factor + entity.motionX * factor,
								0,
								zDist / xzDist * factor + entity.motionZ * factor
						);
					}
					if (player != null)
						player.connection.sendPacket(new SPacketEntityVelocity(entity));
				}
				if(--this.pullEnergy <= 0) {
					this.pullRecharging = true;
					this.pullEnergyRecharge = 0;
				}
			}
		}

        // Particles:
        if(this.getEntityWorld().isRemote)
	        for(int i = 0; i < 2; ++i) {
	            this.getEntityWorld().spawnParticle(EnumParticleTypes.SUSPENDED_DEPTH, this.posX + (this.rand.nextDouble() - 0.5D) * (double)this.width, this.posY + this.rand.nextDouble() * (double)this.height, this.posZ + (this.rand.nextDouble() - 0.5D) * (double)this.width, 0.0D, 0.0D, 0.0D);
	        }
    }

public InteractionResult useOn(UseOnContext p_40510_) {
   Direction direction = p_40510_.getClickedFace();
   if (direction == Direction.DOWN) {
      return InteractionResult.FAIL;
   } else {
      Level level = p_40510_.getLevel();
      BlockPlaceContext blockplacecontext = new BlockPlaceContext(p_40510_);
      BlockPos blockpos = blockplacecontext.getClickedPos();
      ItemStack itemstack = p_40510_.getItemInHand();
      Vec3 vec3 = Vec3.atBottomCenterOf(blockpos);
      AABB aabb = ModEntityType.QUICK_GROWING_VINE.get().getDimensions().makeBoundingBox(vec3.x(), vec3.y(), vec3.z());
      if (level.noCollision(null, aabb.deflate(0.25D)) && level.getEntities(null, aabb.deflate(0.25D)).isEmpty()) {
         if (level instanceof ServerLevel serverlevel) {
            AbstractVine vine = ModEntityType.QUICK_GROWING_VINE.get().create(serverlevel);
            if (this.isPoison){
               vine = ModEntityType.POISON_QUILL_VINE.get().create(serverlevel);
            }
            if (vine == null){
               return InteractionResult.FAIL;
            }
            EntityType<?> entityType = vine.getVariant(p_40510_.getPlayer(), level, blockpos);
            if (entityType != null){
               vine = (AbstractVine) entityType.create(level);
            }
            if (vine == null){
               return InteractionResult.FAIL;
            }
            vine.setPos(vec3);
            if (p_40510_.getPlayer() != null) {
               vine.setTrueOwner(p_40510_.getPlayer());
            }
            vine.finalizeSpawn(serverlevel, serverlevel.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null, null);
            vine.setPerpetual(true);
            vine.setPersistenceRequired();
            if (p_40510_.getPlayer() != null) {
               if (p_40510_.getPlayer().isCrouching()) {
                  vine.setProximity(true);
               }
            }
            serverlevel.addFreshEntityWithPassengers(vine);
            level.playSound((Player)null, vine.getX(), vine.getY(), vine.getZ(), SoundEvents.GRASS_PLACE, SoundSource.BLOCKS, 0.75F, 0.8F);
            vine.gameEvent(GameEvent.ENTITY_PLACE, p_40510_.getPlayer());
         }

         itemstack.shrink(1);
         return InteractionResult.sidedSuccess(level.isClientSide);
      } else {
         return InteractionResult.FAIL;
      }
   }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int range = spellStat.getRange();
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, 3);
    LivingEntity target = this.getTarget(caster, range);
    if (target != null){
        if (this.isShifting(caster)){
            int x = (int) (this.getHorizontalLeftLookAngle(caster).x * 2);
            int z = (int) (this.getHorizontalLeftLookAngle(caster).z * 2);
            int x1 = (int) (this.getHorizontalRightLookAngle(caster).x * 2);
            int z1 = (int) (this.getHorizontalRightLookAngle(caster).z * 2);
            BlockPos left = new BlockPos(caster.blockPosition().offset(x, 0, z));
            BlockPos right = new BlockPos(caster.blockPosition().offset(x1, 0, z1));
            EntityType<? extends AbstractMonolith> entityType = ModEntityType.POISON_QUILL_VINE.get();
            WandUtil.summonTurret(caster, BlockFinder.SummonPosition(caster, left), entityType, target, duration, potency);
            if (rightStaff(staff)) {
                WandUtil.summonTurret(caster, BlockFinder.SummonPosition(caster, right), entityType, target, duration, potency);
            }
        } else {
            int random = worldIn.random.nextInt(5);
            Direction direction = Direction.fromYRot(target.getYHeadRot());
            EntityType<? extends AbstractMonolith> entityType = ModEntityType.QUICK_GROWING_VINE.get();
            if (random == 0) {
                WandUtil.summonMinorSquareTrap(caster, target, entityType, direction, duration);
            } else if (random == 1) {
                WandUtil.summonHallTrap(caster, target, entityType, duration);
            } else if (random == 2) {
                WandUtil.summonCubeTrap(caster, target, entityType, duration);
            } else if (random == 3) {
                WandUtil.summonCircleTrap(caster, target, entityType, direction, duration);
            } else {
                WandUtil.summonSurroundTrap(caster, target, entityType, duration);
            }
        }
    } else if (rayTraceResult instanceof BlockHitResult){
        BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
        if (this.isShifting(caster)){
            EntityType<? extends AbstractMonolith> entityType = ModEntityType.POISON_QUILL_VINE.get();
            WandUtil.summonTurret(caster, blockPos, entityType, null, duration, potency);
        } else {
            EntityType<? extends AbstractMonolith> entityType = ModEntityType.QUICK_GROWING_VINE.get();
            WandUtil.summonCubeTrap(caster, blockPos, entityType, duration);
        }
    }
}

public void inventoryTick(ItemStack stack, Level world, Entity ent, int slot, boolean active) {
	if (ent instanceof Player player) {
		boolean damaged = getFlyCounter(stack) > 0;
		boolean held = player.getMainHandItem() == stack || player.getOffhandItem() == stack;

		if (damaged && !isFlying(stack)) {
			setFlyCounter(stack, getFlyCounter(stack) - 1);
		}

		if (getFlyCounter(stack) >= MAX_COUNTER) {
			setFlying(stack, false);
		} else if (isFlying(stack)) {
			if (held) {
				player.fallDistance = 0F;
				double my = ManaItemHandler.instance().hasProficiency(player, stack) ? 1.6 : 1.25;
				Vec3 oldMot = player.getDeltaMovement();
				if (player.isFallFlying()) {
					double boost = my * 1.2;
					Vec3 lookDir = player.getLookAngle();
					player.setDeltaMovement(oldMot.add(
							lookDir.x * 0.1 + (lookDir.x * boost - oldMot.x) * 0.5,
							lookDir.y * 0.1 + (lookDir.y * boost - oldMot.y) * 0.5,
							lookDir.z * 0.1 + (lookDir.z * boost - oldMot.z) * 0.5));
				} else {
					player.setDeltaMovement(new Vec3(oldMot.x(), my, oldMot.z()));
				}

				player.playSound(BotaniaSounds.airRod, 1F, 1F);
				if (getFlyCounter(stack) % 3 == 0) {
					player.gameEvent(GameEvent.FLAP);
				}
				for (int i = 0; i < 5; i++) {
					WispParticleData data = WispParticleData.wisp(0.35F + (float) Math.random() * 0.1F, 0.25F, 0.25F, 0.25F);
					world.addParticle(data, player.getX(), player.getY(), player.getZ(),
							0.2F * (float) (Math.random() - 0.5),
							-0.01F * (float) Math.random(),
							0.2F * (float) (Math.random() - 0.5));
				}
			}

			setFlyCounter(stack, getFlyCounter(stack) + FALL_MULTIPLIER);
			if (getFlyCounter(stack) == MAX_COUNTER) {
				setFlying(stack, false);
			}
		}

		if (damaged) {
			player.fallDistance = 0;
		}
	}
}

public void tick() {
    super.tick();

    if (complete || target == null)
        return;

    if (approached) {
        drygmy.setChannelingEntity(target.getId());
        drygmy.getLookControl().setLookAt(target, 10.0F, (float) drygmy.getMaxHeadXRot());
        drygmy.getNavigation().stop();
        this.approached = true;
        drygmy.setChanneling(true);
        timeChanneling++;
        if (timeChanneling >= 100) {
            drygmy.setChanneling(false);
            drygmy.setHoldingEssence(true);
            drygmy.setChannelingEntity(-1);
            this.complete = true;
            BlockPos homePos = drygmy.getHome().getBlockPos();
            BlockPos targetPos = target.blockPosition().above(1);
            if (homePos.getY() >= targetPos.getY() - 2) {
                targetPos = targetPos.above(homePos.getY() - targetPos.getY());
            }
            EntityFlyingItem.spawn(homePos, (ServerLevel) drygmy.level,
                    targetPos, homePos,
                    50,
                    255,
                    20);

            drygmy.channelCooldown = 100;
            drygmy.getHome().giveProgress();
        }
    } else {
        if (timePathing > 20 * 8) {
            approached = true;
            drygmy.getNavigation().stop();
        }
        if (BlockUtil.distanceFrom(drygmy.level(), drygmy.position, target.position) <= 2.3) {
            approached = true;
        } else {
            timePathing++;
            Path path = drygmy.getNavigation().createPath(target.getX(), target.getY(), target.getZ(), 1);
            if (path == null || !path.canReach()) {
                approached = true;
                drygmy.getNavigation().stop();
            } else {
                drygmy.getNavigation().moveTo(path, 1.0);
            }
        }
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    if(this.isTame()) {
        if(!itemstack.isEmpty()) {
            if(itemstack.getItem().isEdible()) {
                FoodProperties food = itemstack.getItem().getFoodProperties();
                if(food.isMeat() && this.entityData.get(EntityFeralWolf.DATA_HEALTH_ID) < TAMED_HEALTH) {
                    if(!player.isCreative()) {
                        itemstack.shrink(1);
                    }
                    this.heal(food.getNutrition());
                    return InteractionResult.SUCCESS;
                }
            }
        }

        if(this.isOwnedBy(player) && !this.level.isClientSide && !this.isFood(itemstack) && (!(itemstack.getItem().isEdible()) || !(itemstack.getItem().getFoodProperties().isMeat()))) {
            this.setOrderedToSit(!this.isInSittingPose());
            this.jumping = false;
            this.navigation.stop();
            this.setTarget(null);
        }
    } else if(this.isTamingItem(itemstack.getItem())) {
        ItemStack stack = player.getItemBySlot(EquipmentSlot.HEAD);
        if(stack.is(ModResources.Tags.Items.FERAL_WOLF_TAME_ARMOR)) {
            if(!player.isCreative()) {
                itemstack.shrink(1);
            }
            if(!this.level.isClientSide) {
                if(this.random.nextInt(100) <= 14 && !ModPlatformEvents.tame(this, player)) {
                    this.tame(player);
                    this.navigation.stop();
                    this.setTarget(null);
                    this.setOrderedToSit(true);
                    this.setHealth((float) TAMED_HEALTH);
                    this.level.broadcastEntityEvent(this, (byte) 7);
                } else {
                    this.level.broadcastEntityEvent(this, (byte) 6);
                }
            }

            return InteractionResult.SUCCESS;
        } else {
            if(!this.level.isClientSide) {
                player.sendSystemMessage(Component.translatable("entity.betteranimalsplus.feralwolf.message.wear_head"));
            }
        }
    }

    return super.mobInteract(player, hand);
}

public void onEntityAttacked(LivingIncomingDamageEvent event) {
    LivingEntity entity = event.getEntity();
    DamageContainer damageContainer = event.getContainer();
    float damage = damageContainer.getNewDamage();
    if (damage <= 0 || !entity.isAlive()) {
        //If some mod does weird things and causes the damage value to be negative or zero then exit
        // as our logic assumes there is actually damage happening and can crash if someone tries to
        // use a negative number as the damage value. We also check to make sure that we don't do
        // anything if the entity is dead as living attack is still fired when the entity is dead
        // for things like fall damage if the entity dies before hitting the ground, and then energy
        // would be depleted regardless if keep inventory is on even if no damage was stopped as the
        // entity can't take damage while dead
        return;
    }
    DamageSource source = damageContainer.getSource();
    //Gas Mask checks
    if (source.is(MekanismAPITags.DamageTypes.IS_PREVENTABLE_MAGIC)) {
        ItemStack headStack = entity.getItemBySlot(EquipmentSlot.HEAD);
        if (!headStack.isEmpty() && headStack.getItem() instanceof ItemScubaMask) {
            ItemAccess chestAccess = ItemAccessUtils.forEntitySlot(entity, EquipmentSlot.CHEST);
            if (chestAccess.getResource().getItem() instanceof ItemScubaTank tank && tank.getMode(chestAccess) && tank.hasChemical(chestAccess)) {
                event.setCanceled(true);
                return;
            }
        }
    }
    for (EquipmentSlot slot : EquipmentSlotGroup.ARMOR) {
        if (entity.getItemBySlot(slot).is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR)) {
            //Only add the reduction modifier if at least one module container armor is being worn
            event.addReductionModifier(Reduction.ARMOR, (container, reduction) -> {
                float newDamage = container.getNewDamage();
                if (newDamage > reduction) {
                    //Note: This acts on the damage after the reduction from armor has been performed
                    float toReduce = newDamage - reduction;
                    float ratioAbsorbed = Math.max(0, ItemMekaSuitArmor.getDamageAbsorbed(entity, container.getSource(), toReduce));
                    if (ratioAbsorbed > 0) {
                        if (ratioAbsorbed >= 1) {
                            //If we fully absorbed the damage, mark that we don't want side effects to be performed
                            container.setShouldCauseSideEffects(false);
                            //And just return that we reduced all the damage so that we don't have to worry about floating point nonsense
                            return newDamage;
                        }
                        return reduction + toReduce * ratioAbsorbed;
                    }
                }
                return reduction;
            });
            break;
        }
    }
}

public void tick() {
	super.tick();

	if (this.isEffectiveAi()) {
		if (this.isPassenger()) {
			this.setYRot(0.0F);
			this.setXRot(0.0F);
			this.setAirSupply(this.getMaxAirSupply());
		} else if (this.isInWater() && this.getNavigation().isDone()) {
			float yaw = this.getYRot();
			float pitch = this.getXRot();
			float pitchFactor = Mth.cos(pitch * ((float) Math.PI / 180F));
			float x = -Mth.sin(yaw * ((float) Math.PI / 180F)) * pitchFactor;
			float y = -Mth.sin(pitch * ((float) Math.PI / 180F));
			float z = Mth.cos(yaw * ((float) Math.PI / 180F)) * pitchFactor;
			Vec3 motion = new Vec3(x, y, z).normalize().scale(0.01666666666F);
			this.push(motion.x, motion.y, motion.z);
		}

		if (!this.level().isClientSide && (Mth.abs(this.xRotO - this.getXRot()) >= 1.0F || Mth.abs(this.yRotO - this.getYRot()) >= 1.0F)) {
			this.hasImpulse = true;
		}
	}

	if (this.hasCooldown()) {
		if (this.isEffectiveAi()) {
			this.setCooldown(this.getCooldown() - 1);
			if (!this.hasCooldown()) {
				this.playSound(UASoundEvents.JELLYFISH_COOLDOWN_END.get(), 1.0F, this.random.nextFloat() * 0.15F + 1.0F);
			}
		}

		if (this.level().isClientSide && this.level().getGameTime() % 4 == 0) {
			for (int i = 0; i < 2; i++) {
				this.level().addParticle(JellyTorchType.getBlobParticleType(this.getJellyTorchType()), this.getRandomX(0.5D), this.getY() + this.getEyeHeight(), this.getRandomZ(0.5D), makeNegativeRandomly(this.random.nextDouble() * 0.05F, this.getRandom()), -this.random.nextDouble() * 0.05F, makeNegativeRandomly(this.random.nextDouble() * 0.05F, this.getRandom()));
			}
		}
	}

	if (this.isAlive()) {
		for (LivingEntity entities : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.15D), CAN_STING)) {
			if (entities.isAlive()) {
				this.stingEntity(entities);
			}
		}

		if (this.isInWater() && this.isNoEndimationPlaying()) {
			this.setDeltaMovement(this.getDeltaMovement().subtract(0.0F, 0.005F, 0.0F));
		}
	}
}

public void tick() {
    super.tick();
    Vec3 vector3d = this.getDeltaMovement();
    boolean flag = this.getDeltaMovement().x * this.getDeltaMovement().x + this.getDeltaMovement().z * this.getDeltaMovement().z >= 1.0E-3D;
    if (!this.onGround() && vector3d.y < 0.0D) {
        this.setDeltaMovement(vector3d.multiply(1.0D, 0.4D, 1.0D));
    }
    this.setFlying(true);
    this.setNoGravity(true);
    if (this.isFlying() && flyProgress < 5F) {
        flyProgress++;
    }
    if (!this.isFlying() && flyProgress > 0F) {
        flyProgress--;
    }
    if(sippy && sipProgress < 5F){
        sipProgress++;
    }
    if(!sippy && sipProgress > 0F){
        sipProgress--;
    }
    if(sippy && sipProgress == 5F){
        sippy = false;
    }
    if (flag && movingProgress < 5F) {
        movingProgress++;
    }
    if (!flag && movingProgress > 0F) {
        movingProgress--;
    }
    if(this.getDeltaMovement().lengthSqr() < 1.0E-7D){
        hummingStill++;
    }else{
        hummingStill = 0;
    }
    if(pollinateCooldown > 0){
        pollinateCooldown--;
    }
    if(sipCooldown > 0){
        sipCooldown--;
    }
    if(loopSoundTick == 0){
        this.playSound(AMSoundRegistry.HUMMINGBIRD_LOOP.get(), this.getSoundVolume() * 0.33F, this.getVoicePitch());
    }
    loopSoundTick++;
    if(loopSoundTick > 27){
        loopSoundTick = 0;
    }
    prevFlyProgress = flyProgress;
    prevMovingProgress = movingProgress;
    prevSipProgress = sipProgress;
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    Item item = itemstack.getItem();
    InteractionResult type = super.mobInteract(player, hand);
    if (!isTame() && itemstack.is(AMTagRegistry.SUGAR_GLIDER_TAMEABLES)) {
        this.usePlayerItem(player, hand, itemstack);
        this.gameEvent(GameEvent.EAT);
        this.playSound(SoundEvents.FOX_EAT, this.getSoundVolume(), this.getVoicePitch());
        if (getRandom().nextInt(2) == 0) {
            this.tame(player);
            this.level().broadcastEntityEvent(this, (byte) 7);
        } else {
            this.level().broadcastEntityEvent(this, (byte) 6);
        }
        return InteractionResult.SUCCESS;
    }
    if (isTame() && itemstack.is(AMTagRegistry.INSECT_ITEMS)) {
        if (this.getHealth() < this.getMaxHealth()) {
            this.usePlayerItem(player, hand, itemstack);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.FOX_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.heal(5);
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.PASS;

    }
    InteractionResult interactionresult = itemstack.interactLivingEntity(player, this, hand);
    if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS && isTame() && isOwnedBy(player) && !isFood(itemstack)) {
        if (player.isShiftKeyDown() && player.getPassengers().isEmpty()) {
            this.startRiding(player);
            rideCooldown = 20;
            return InteractionResult.SUCCESS;
        } else {
            this.setCommand(this.getCommand() + 1);
            if (this.getCommand() == 3) {
                this.setCommand(0);
            }
            player.displayClientMessage(Component.translatable("entity.alexsmobs.all.command_" + this.getCommand(), this.getName()), true);
            boolean sit = this.getCommand() == 2;
            if (sit) {
                this.setOrderedToSit(true);
                return InteractionResult.SUCCESS;
            } else {
                this.setOrderedToSit(false);
                return InteractionResult.SUCCESS;
            }
        }

    }
    return type;
}

public void onUseTick(Level level, LivingEntity player, ItemStack stack, int remainingUseDuration)
{
	FluidStack fs = this.getFluid(stack);
	if(!fs.isEmpty())
	{
		int duration = getUseDuration(stack, player)-remainingUseDuration;
		int consumed = IEServerConfig.TOOLS.chemthrower_consumption.get();
		if(consumed*duration <= fs.getAmount())
		{
			Vec3 v = player.getLookAngle();
			int split = 8;
			boolean isGas = fs.getFluid().is(Fluids.GASEOUS);

			float scatter = isGas?.25f: .15f;
			float range = isGas?.5f: 1f;
			if(getUpgrades(stack).has(UpgradeEffect.FOCUS))
			{
				range += .25f;
				scatter = .025f;
			}

			boolean ignite = ChemthrowerHandler.isFlammable(fs.getFluid())&&isIgniteEnable(stack);
			for(int i = 0; i < split; i++)
			{
				Vec3 vecDir = v.add(player.getRandom().nextGaussian()*scatter, player.getRandom().nextGaussian()*scatter, player.getRandom().nextGaussian()*scatter);
				ChemthrowerShotEntity chem = new ChemthrowerShotEntity(player.level(), player, vecDir.x*0.25, vecDir.y*0.25, vecDir.z*0.25, fs);

				// Apply momentum from the player.
				chem.setDeltaMovement(player.getDeltaMovement().add(vecDir.scale(range)));

				// Apply a small amount of backforce.
				if(!player.onGround())
					player.setDeltaMovement(player.getDeltaMovement().subtract(vecDir.scale(0.0025*range)));
				if(ignite)
					chem.igniteForSeconds(10);
				if(!player.level().isClientSide)
					player.level().addFreshEntity(chem);
			}
			if(remainingUseDuration%4==0)
			{
				if(ignite)
					player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.sprayFire.value(), SoundSource.PLAYERS, .5f, 1.5f);
				else
					player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.spray.value(), SoundSource.PLAYERS, .5f, .75f);
			}
		}
		else
			player.releaseUsingItem();
	}
	else
		player.releaseUsingItem();
}

    public void updateTask() {
        EntityLivingBase attackTarget = this.host.getAttackTarget();
        this.host.getLookHelper().setLookPositionWithEntity(attackTarget, 30.0F, 30.0F);

		// Path To Target:
		if((this.longMemory || this.host.getEntitySenses().canSee(attackTarget)) && --this.repathTime <= 0) {
			this.repathTime = failedPathFindingPenalty + 4 + this.host.getRNG().nextInt(7);

        	if(!this.host.useDirectNavigator()) {
				if(this.host.isCurrentlyFlying()) {
					this.host.getNavigator().tryMoveToXYZ(this.attackTarget.posX, this.attackTarget.getEntityBoundingBox().minY + this.host.getFlightOffset(), this.attackTarget.posZ, this.speed);
				}
				else {
					this.host.getNavigator().tryMoveToEntityLiving(attackTarget, this.speed);
				}
				if(this.host.getNavigator().getPath() != null) {
	                PathPoint finalPathPoint = this.host.getNavigator().getPath().getFinalPathPoint();
	                if(finalPathPoint != null && attackTarget.getDistanceSq(finalPathPoint.x, finalPathPoint.y, finalPathPoint.z) < 1) {
						failedPathFindingPenalty = 0;
					}
	                else {
						failedPathFindingPenalty += failedPathFindingPenaltyMax;
					}
	            }
	            else {
					failedPathFindingPenalty += failedPathFindingPenaltyMax;
				}
        	}
        	else {
        		this.host.directNavigator.setTargetPosition(new BlockPos((int) attackTarget.posX, (int) (attackTarget.getEntityBoundingBox().minY + this.host.getFlightOffset()), (int) attackTarget.posZ), speed);
        	}
        }

        // Damage Target:
        if(this.host.getDistance(attackTarget.posX, attackTarget.getEntityBoundingBox().minY + this.host.getFlightOffset(), attackTarget.posZ) <= this.getAttackRange(attackTarget)) {
            if(--this.attackTime <= 0) {
                this.attackTime = this.host.getMeleeCooldown();
                if(this.host.getHeldItemMainhand() != null)
                    this.host.swingArm(EnumHand.MAIN_HAND);
                this.host.attackMelee(attackTarget, damage);
            }

            // Move helper won't change the Yaw if the target is already close by
            double d0 = this.host.posX - attackTarget.posX;
            double d1 = this.host.posZ - attackTarget.posZ;
            float f = (float)(Math.atan2(d1, d0) * 180.0D / Math.PI) + 90.0F;
            f = MathHelper.wrapDegrees(f - this.host.rotationYaw);
            if(f < -30f) f = -30f;
            if(f > 30f) f = 30f;
            this.host.rotationYaw = this.host.rotationYaw + f;
        }
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            i = caster.level.getRandom().nextIntBetweenInclusive(4, 7);
        } else if (rightStaff(staff)){
            i = 2 + caster.level.getRandom().nextInt(4);
        } else if (typeStaff(staff, SpellType.FROST)){
            i = 2;
        }
        for (int i1 = 0; i1 < i; ++i1) {
            AbstractWraith summonedentity = new AbstractWraith(ModEntityType.WRAITH_SERVANT.get(), worldIn);
            Player player = null;
            if (caster instanceof Player player1){
                player = player1;
            }
            if (typeStaff(staff, SpellType.WILD)) {
                summonedentity = new AbstractMuckWraith(ModEntityType.MUCK_WRAITH_SERVANT.get(), worldIn);
            } else {
                EntityType<?> entityType1 = summonedentity.getVariant(player, worldIn, caster.blockPosition());
                if (entityType1 != null) {
                    Entity entity = entityType1.create(worldIn);
                    if (entity instanceof AbstractWraith wraith){
                        summonedentity = wraith;
                    }
                }
            }
            summonedentity.setTrueOwner(caster);
            summonedentity.moveTo(BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn), 0.0F, 0.0F);
            MobUtil.moveDownToGround(summonedentity);
            summonedentity.setPersistenceRequired();
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        SoundUtil.playNecromancerSummon(caster);
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int range = spellStat.getRange();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, 3);
    if (rightStaff(staff)){
        int i = (int) caster.getX();
        int j = (int) caster.getY();
        int k = (int) caster.getZ();
        int amount = 0;
        List<LivingEntity> list = worldIn.getEntitiesOfClass(LivingEntity.class, (new AABB(i, j, k, i, j - 4, k)).inflate(16));
        if (!list.isEmpty()) {
            for (LivingEntity entity : list) {
                if (amount < SpellConfig.EntanglingStaffAmount.get()) {
                    if (entity != caster && !MobUtil.areAllies(entity, caster) && !entity.getType().is(ModTags.EntityTypes.UNTANGLEABLE)) {
                        EntangleVines entangleVines = new EntangleVines(worldIn, caster, entity);
                        entangleVines.setLifeSpan(entangleVines.getLifeSpan() + MathHelper.secondsToTicks(duration));
                        if (CuriosFinder.hasWildRobe(caster)){
                            entangleVines.setDamaging(true);
                        }
                        if (worldIn.addFreshEntity(entangleVines)) {
                            ++amount;
                        }
                    }
                }
            }
        } else if (rayTraceResult instanceof BlockHitResult){
            BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
            EntangleVines entangleVines = new EntangleVines(worldIn, caster, blockPos);
            entangleVines.setLifeSpan(entangleVines.getLifeSpan() + MathHelper.secondsToTicks(duration));
            worldIn.addFreshEntity(entangleVines);
        }
    } else {
        LivingEntity target = this.getTarget(caster, range);
        if (target != null){
            EntangleVines entangleVines = new EntangleVines(worldIn, caster, target);
            entangleVines.setLifeSpan(entangleVines.getLifeSpan() + MathHelper.secondsToTicks(duration));
            if (CuriosFinder.hasWildRobe(caster)){
                entangleVines.setDamaging(true);
            }
            worldIn.addFreshEntity(entangleVines);
        } else if (rayTraceResult instanceof BlockHitResult){
            BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
            EntangleVines entangleVines = new EntangleVines(worldIn, caster, blockPos);
            entangleVines.setLifeSpan(entangleVines.getLifeSpan() + MathHelper.secondsToTicks(duration));
            worldIn.addFreshEntity(entangleVines);
        }
    }
}

private boolean rightClickItem(FakePlayer fakePlayer, BlockPos pos) {
    // if necessary, find a filter-matching item in the inventory, and swap it into slot 0 (drone's held item)
    if (!progWidget.isItemValidForFilters(drone.getInv().getStackInSlot(0)) && !trySwapItem()) {
        return false;
    }

    ItemStack stack = fakePlayer.getMainHandItem();
    Level world = fakePlayer.getCommandSenderWorld();

    // this is adapted from PlayerInteractionManager#processRightClickBlock()
    try {
        BlockHitResult brtr = doTrace(world, pos, fakePlayer);
        if (brtr == null) return false;

        PlayerInteractEvent.RightClickBlock event = CommonHooks.onRightClickBlock(fakePlayer, InteractionHand.MAIN_HAND, pos, brtr);
        if (event.isCanceled() || event.getUseItem() == TriState.FALSE) {
            return false;
        }

        InteractionResult ret = stack.onItemUseFirst(new UseOnContext(fakePlayer, InteractionHand.MAIN_HAND, brtr));
        if (ret != InteractionResult.PASS) return ret.consumesAction();

        if (stack.isEmpty() || fakePlayer.getCooldowns().isOnCooldown(stack.getItem())) {
            return false;
        }

        if (stack.getItem() instanceof BlockItem) {
            Block block = ((BlockItem)stack.getItem()).getBlock();
            if (block instanceof CommandBlock || block instanceof StructureBlock) {
                return false;
            }
        }

        if (event.getUseItem() != TriState.FALSE) {
            ItemStack copyBeforeUse = stack.copy();
            InteractionResult result = stack.useOn(new UseOnContext(fakePlayer, InteractionHand.MAIN_HAND, brtr));
            if (result == InteractionResult.PASS) {
                InteractionResultHolder<ItemStack> rightClickResult = stack.getItem().use(world, fakePlayer, InteractionHand.MAIN_HAND);
                fakePlayer.setItemInHand(InteractionHand.MAIN_HAND, rightClickResult.getObject());
            }
            if (fakePlayer.getItemInHand(InteractionHand.MAIN_HAND).isEmpty()) {
                net.neoforged.neoforge.event.EventHooks.onPlayerDestroyItem(fakePlayer, copyBeforeUse, InteractionHand.MAIN_HAND);
            }
            return true;
        }
    } catch (Throwable e) {
        // crash could happen in right-click logic of item, which could be from any mod...
        Log.error("DroneAIRightClickBlock crashed! Stacktrace: ");
        e.printStackTrace();
    }
    return false;
}

public void deductPsi(int psi, int cd, boolean sync, boolean shatter) {
	int currentPsi = availablePsi;

	Player player = playerWR.get();
	if(player == null) {
		return;
	}

	ItemStack cadStack = getCAD();

	if(!cadStack.isEmpty()) {
		ICAD cad = (ICAD) cadStack.getItem();
		int storedPsi = cad.getStoredPsi(cadStack);
		if(storedPsi == -1) {
			return;
		}
	}

	availablePsi -= psi;
	if(regenCooldown < cd) {
		regenCooldown = cd;
	}

	if(availablePsi < 0) {
		int overflow = -availablePsi;
		availablePsi = 0;

		if(!cadStack.isEmpty()) {
			ICAD cad = (ICAD) cadStack.getItem();
			overflow = cad.consumePsi(cadStack, overflow);
		}

		if(!shatter && overflow > 0) {
			float dmg = (float) overflow / (loopcasting ? 50 : 125);
			if(!client) {
				Registry<DamageType> types = player.registryAccess().registryOrThrow(Registries.DAMAGE_TYPE);
				DamageSource overloadSource = new DamageSource(types.getHolderOrThrow(LibResources.PSI_OVERLOAD));
				player.hurt(overloadSource, dmg);
			}
			overflowed = true;
			if(sync && player instanceof ServerPlayer) {
				PsiPlayerDataSync.sendOverflow((ServerPlayer) player, true);
			}
		}
	}

	if(sync && player instanceof ServerPlayer) {
		PsiPlayerDataSync.sendDeduction((ServerPlayer) player, currentPsi, availablePsi, regenCooldown, shatter);
	}

	save();
}

