                Vec3 vec31 = Vec3.atCenterOf(target);
                Vec3 vec32 = vec31.subtract(relicheirus.position());
                if (vec32.length() > 1) {
                    vec32 = vec32.normalize();
                }
                Vec3 delta = new Vec3(vec32.x * 0.1F, 0F, vec32.z * 0.1F);
                relicheirus.setDeltaMovement(relicheirus.getDeltaMovement().add(delta));
            }
        }
    }
}

public void tick() {
    super.tick();
    this.prevOnLandProgress = onLandProgress;
    this.prevFeedProgress = feedProgress;
    if(chaseCooldown > 0){
        chaseCooldown--;
    }
    final boolean inWaterOrBubble = this.isInWaterOrBubble();
    if (!inWaterOrBubble && onLandProgress < 5F) {
        onLandProgress++;
    }
    if (inWaterOrBubble && onLandProgress > 0F) {
        onLandProgress--;
    }
    final int feedingTime = this.getFeedingTime();
    if (feedingTime > 0 && feedProgress < 5F) {
        feedProgress++;
    }
    if (feedingTime <= 0 && feedProgress > 0F) {
        feedProgress--;
    }
    if(this.isBaby()){
        this.setBabyAge(this.getBabyAge() + 1);
    }
    BlockPos feedingPos = this.entityData.get(FEEDING_POS).orElse(null);
    if(feedingPos == null){
        float f2 = (float) -((float) this.getDeltaMovement().y * 2.2F * (double) Mth.RAD_TO_DEG);
        this.setXRot(f2);
    }else if(this.getFeedingTime() > 0){
        Vec3 face = Vec3.atCenterOf(feedingPos).subtract(this.position());
        double d0 = face.horizontalDistance();
        this.setXRot((float)(-Mth.atan2(face.y, d0) * (double)Mth.RAD_TO_DEG));
        this.setYRot(((float) Mth.atan2(face.z, face.x)) * Mth.RAD_TO_DEG - 90F);
        this.yBodyRot = this.getYRot();
        this.yHeadRot = this.getYRot();
        BlockState state = level().getBlockState(feedingPos);
        if(random.nextInt(2) == 0 && !state.isAir()){
            Vec3 mouth = new Vec3(0, this.getBbHeight() * 0.5F, 0.4F * this.getPupfishScale()).xRot(this.getXRot() * Mth.DEG_TO_RAD).yRot(-this.getYRot() * Mth.DEG_TO_RAD);
            for (int i = 0; i < 4 + random.nextInt(2); i++) {
                double motX = this.random.nextGaussian() * 0.02D;
                double motY = 0.1F + random.nextFloat() * 0.2F;
                double motZ = this.random.nextGaussian() * 0.02D;
                level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, state), this.getX() + mouth.x, this.getY() + mouth.y, this.getZ() + mouth.z, motX, motY, motZ);
            }
        }
    }
    if(!isInWaterOrBubble() && this.isAlive()){
        if (this.onGround() && random.nextFloat() < 0.5F) {
            this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
            this.setYRot(this.random.nextFloat() * 360.0F);
            this.playSound(SoundEvents.COD_FLOP, this.getSoundVolume(), this.getVoicePitch());
        }
    }
}

public void tick() {
    if(jumpCooldown > 0){
        jumpCooldown--;
    }
    if (stalk) {
        if (secondPartOfLeap) {
            this.leopard.setTackling(!leopard.onGround());
            leopard.lookAt(target, 180F, 10F);
            leopard.yBodyRot = leopard.getYRot();
            if (this.leopard.distanceTo(target) < 3F && this.leopard.hasLineOfSight(target)) {
                target.hurt(this.leopard.damageSources().mobAttack(leopard), (float) (leopard.getAttribute(Attributes.ATTACK_DAMAGE).getValue() * 2.5F));
                this.stalk = false;
                this.secondPartOfLeap = false;
            }else if (leopard.onGround() && jumpCooldown == 0) {
                this.leopard.setSlSneaking(false);
                jumpCooldown = 10 + leopard.getRandom().nextInt(10);
                Vec3 vector3d = this.leopard.getDeltaMovement();
                Vec3 vector3d1 = new Vec3(this.target.getX() - this.leopard.getX(), 0.0D, this.target.getZ() - this.leopard.getZ());
                if (vector3d1.lengthSqr() > 1.0E-7D) {
                    vector3d1 = vector3d1.normalize().scale(0.9D).add(vector3d.scale(0.8D));
                }
                this.leopard.setDeltaMovement(vector3d1.x, vector3d1.y + 0.6F, vector3d1.z);
            }
        } else {
            if (leapPos == null || target.distanceToSqr(leapPos) > 250) {
                Vec3 vector3d1 = calculateFarPoint(50);
                if (vector3d1 != null) {
                    leapPos = vector3d1;
                }else{
                    leapPos = LandRandomPos.getPosTowards(leopard, 10, 10, target.position());
                }
            } else {
                this.leopard.setSlSneaking(true);
                this.leopard.getNavigation().moveTo(leapPos.x, leapPos.y, leapPos.z, 1D);
                if (this.leopard.distanceToSqr(leapPos.x, leapPos.y, leapPos.z) < 9) {
                    if (this.leopard.hasLineOfSight(target)) {
                        secondPartOfLeap = true;
                        this.leopard.getNavigation().stop();
                    }
                }
            }
        }
    } else {
        this.leopard.setSlSneaking(false);
        this.leopard.getNavigation().moveTo(target, 1D);
        if (this.leopard.distanceTo(target) < 3F) {
            if(leopard.getAnimation() == IAnimatedEntity.NO_ANIMATION){
                leopard.setAnimation(leopard.getRandom().nextBoolean() ? EntitySnowLeopard.ANIMATION_ATTACK_R : EntitySnowLeopard.ANIMATION_ATTACK_L);
            }else if(this.leopard.getAnimationTick() == 5){
                leopard.doHurtTarget(target);
            }
        }
    }
}

public @NotNull InteractionResult mobInteract(@NotNull Player player, @NotNull InteractionHand hand) {
    if (this.isOwnedBy(player)) {

        if (player.getItemInHand(hand).getItem() == Items.SUGAR && this.getHealth() < this.getMaxHealth()) {
            this.heal(5);
            player.getItemInHand(hand).shrink(1);
            this.playSound(IafSoundRegistry.PIXIE_TAUNT, 1F, 1F);
            return InteractionResult.SUCCESS;
        } else {

            // make pixie sit via a check in livingTick() like Hippogryphs work
            this.setCommand(this.getCommand() + 1);
            if (this.getCommand() > 1) {
                this.setCommand(0);
            }

            return InteractionResult.SUCCESS;
        }
    } else if (player.getItemInHand(hand).getItem() == IafBlockRegistry.JAR_EMPTY.get().asItem() && !this.isTame()) {
        if (!player.isCreative()) {
            player.getItemInHand(hand).shrink(1);
        }
        Block jar = IafBlockRegistry.JAR_PIXIE_0.get();
        switch (this.getColor()) {
            case 0:
                jar = IafBlockRegistry.JAR_PIXIE_0.get();
                break;
            case 1:
                jar = IafBlockRegistry.JAR_PIXIE_1.get();
                break;
            case 2:
                jar = IafBlockRegistry.JAR_PIXIE_2.get();
                break;
            case 3:
                jar = IafBlockRegistry.JAR_PIXIE_3.get();
                break;
            case 4:
                jar = IafBlockRegistry.JAR_PIXIE_4.get();
                break;
        }
        ItemStack stack = new ItemStack(jar, 1);
        if (!level.isClientSide) {
            if (!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty()) {
                this.spawnAtLocation(this.getItemInHand(InteractionHand.MAIN_HAND), 0.0F);
                this.stealCooldown = STEAL_COOLDOWN;
            }

            this.spawnAtLocation(stack, 0.0F);
        }
        //player.addStat(ModAchievements.jarPixie);
        this.remove(RemovalReason.DISCARDED);
    }
    return super.mobInteract(player, hand);
}

public static void tick() {
	if (promptKeepAlive > 0)
		promptKeepAlive--;
	else
		currentPrompt = null;

	Minecraft mc = Minecraft.getInstance();
	displayedPromptSize.chase(currentPrompt != null ? mc.font.width(currentPrompt) + 17 : 0, .5f, Chaser.EXP);
	displayedPromptSize.tickChaser();

	Carriage carriage = getCarriage();
	if (carriage == null)
		return;

	Train train = carriage.train;
	double value =
		Math.abs(train.speed) / (train.maxSpeed() * AllConfigs.server().trains.manualTrainSpeedModifier.getF());
	value = Mth.clamp(value + 0.05f, 0, 1);

	displayedSpeed.chase((int) (value * 18) / 18f, .5f, Chaser.EXP);
	displayedSpeed.tickChaser();
	displayedThrottle.chase(editedThrottle != null ? editedThrottle : train.throttle, .75f, Chaser.EXP);
	displayedThrottle.tickChaser();

	boolean isSprintKeyPressed = ControlsUtil.isActuallyPressed(mc.options.keySprint);

	if (isSprintKeyPressed && honkPacketCooldown-- <= 0) {
		train.determineHonk(mc.level);
		if (train.lowHonk != null) {
			CatnipServices.NETWORK.sendToServer(new HonkPacket.Serverbound(train, true));
			honkPacketCooldown = 5;
			usedToHonk = true;
		}
	}

	if (!isSprintKeyPressed && usedToHonk) {
		CatnipServices.NETWORK.sendToServer(new HonkPacket.Serverbound(train, false));
		honkPacketCooldown = 0;
		usedToHonk = false;
	}

	if (editedThrottle == null)
		return;
	if (Mth.equal(editedThrottle, train.throttle)) {
		editedThrottle = null;
		hudPacketCooldown = 5;
		return;
	}

	if (hudPacketCooldown-- <= 0) {
		CatnipServices.NETWORK.sendToServer(new TrainHUDUpdatePacket.Serverbound(train, editedThrottle));
		hudPacketCooldown = 5;
	}
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    float velocity = spellStat.getVelocity();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        velocity += WandUtil.getLevels(ModEnchantments.VELOCITY.get(), caster);
    }
    Vec3 vector3d = caster.getViewVector( 1.0F);
    SpellHurtingProjectile soulBolt = new SoulBolt(
            caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.2,
            caster.getZ() + vector3d.z / 2,
            vector3d.x,
            vector3d.y,
            vector3d.z, worldIn);
    if (this.typeStaff(staff, SpellType.WILD)) {
        soulBolt = new PoisonBolt(
                caster.getX() + vector3d.x / 2,
                caster.getEyeY() - 0.2,
                caster.getZ() + vector3d.z / 2,
                vector3d.x,
                vector3d.y,
                vector3d.z, worldIn);
        SoundUtil.playSoulBolt(caster);
    } else if (this.typeStaff(staff, SpellType.NETHER) && CuriosFinder.hasNetherSet(caster)) {
        soulBolt = new WitherBolt(
                caster.getX() + vector3d.x / 2,
                caster.getEyeY() - 0.2,
                caster.getZ() + vector3d.z / 2,
                vector3d.x,
                vector3d.y,
                vector3d.z, worldIn);
        this.playSound(worldIn, caster, SoundEvents.WITHER_SHOOT, 0.5F, 0.25F);
        this.playSound(worldIn, caster, ModSounds.HELL_BOLT_SHOOT.get());
    } else if (staff.is(ModItems.NAMELESS_STAFF.get())) {
        soulBolt = new NecroBolt(
                caster.getX() + vector3d.x / 2,
                caster.getEyeY() - 0.2,
                caster.getZ() + vector3d.z / 2,
                vector3d.x,
                vector3d.y,
                vector3d.z, worldIn);
        SoundUtil.playNecroBolt(caster);
    } else {
        SoundUtil.playSoulBolt(caster);
    }
    if (soulBolt instanceof SoulBolt soulBolt1){
        soulBolt1.setNecro(this.typeStaff(staff, SpellType.NECROMANCY));
    }
    soulBolt.setExtraDamage(potency);
    soulBolt.setBoltSpeed((int) velocity);
    soulBolt.setOwner(caster);
    worldIn.addFreshEntity(soulBolt);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (rightStaff(staff)){
            i = 3;
        } else if (specialStaffs(staff)){
            i = 2;
        }
        for (int i1 = 0; i1 < i; ++i1) {
            Summoned summonedentity = new BlackWolf(ModEntityType.BLACK_WOLF.get(), worldIn);
            BlockPos blockPos = BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn);
            if (caster.isUnderWater()){
                blockPos = BlockFinder.SummonWaterRadius(caster, worldIn);
            }
            if (this.typeStaff(staff, SpellType.NECROMANCY)){
                summonedentity = new SkeletonWolf(ModEntityType.SKELETON_WOLF.get(), worldIn);
            } else if ((worldIn.isThundering() && worldIn.canSeeSky(blockPos)) || this.typeStaff(staff, SpellType.STORM)) {
                summonedentity = new Stormhound(ModEntityType.STORMHOUND.get(), worldIn);
            } else if (worldIn.getBiome(blockPos).is(Tags.Biomes.IS_MOUNTAIN) || this.typeStaff(staff, SpellType.WIND)){
                summonedentity = new TwilightGoat(ModEntityType.TWILIGHT_GOAT.get(), worldIn);
            } else if (worldIn.isWaterAt(blockPos) || this.typeStaff(staff, SpellType.ABYSS)) {
                summonedentity = new Snapper(ModEntityType.SNAPPER.get(), worldIn);
            } else if (worldIn.getBiome(blockPos).get().coldEnoughToSnow(blockPos) || this.typeStaff(staff, SpellType.FROST)) {
                summonedentity = new WinterWolf(ModEntityType.WINTER_WOLF.get(), worldIn);
            } else if (worldIn.dimensionType().ultraWarm() || worldIn.getBiome(blockPos).is(BiomeTags.IS_NETHER) || this.typeStaff(staff, SpellType.NETHER)){
                summonedentity = new Hellhound(ModEntityType.HELLHOUND.get(), worldIn);
            }
            summonedentity.setTrueOwner(caster);
            summonedentity.moveTo(blockPos, 0.0F, 0.0F);
            if (summonedentity.getType() != ModEntityType.SNAPPER.get()){
                MobUtil.moveDownToGround(summonedentity);
            }
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.setPersistenceRequired();
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED,null,null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.SUMMON_SPELL.get());
    }
}

public void tick() {
    super.tick();
    if (level.isClientSide) {
        //Used for smooth rotation
        prevClimbTick = climbTick;
        if (isClimbing()) {
            climbTick = Math.min(5, climbTick + 1);
        } else {
            climbTick = Math.max(0, climbTick - 1);
        }
    } else {
        if (!isAgingDisabled() && canAgeUpNaturally()) {
            setAgeInTicks(getAge() + 1);
        }
        if (tickCount % 1200 == 0 && getHunger() > 0 && FossilConfig.isEnabled(FossilConfig.ENABLE_HUNGER)) {
            if (!isNoAi()) {
                setHunger(getHunger() - 1);
            } else {
                setHunger(getMaxHunger());
                setHealth(getMaxHealth());
            }
        }
        if (tickCount % 40 == 0 && getHunger() == 0 && getHealth() > (FossilConfig.isEnabled(FossilConfig.ENABLE_STARVATION) ? 0 : getMaxHealth() / 2)) {
            hurt(DamageSource.STARVE, 1);
        }

        if (aiClimbType() == Climbing.ARTHROPOD) {
            if (isClimbing()) {
                ticksClimbing++;
                boolean onCooldown = ticksClimbing >= 100 || level.getBlockState(blockPosition().above()).getMaterial().isSolid();
                if (!horizontalCollision || onCooldown) {
                    stopClimbing();
                    ticksClimbing = 0;
                    if (onCooldown) {
                        climbingCooldown = 900;
                    }
                } else {
                    Pair<Direction, Double> dir = Util.getClosestSide(getBoundingBox(), blockPosition());
                    entityData.set(CLIMBING_DIR, dir.key());
                    if (getDeltaMovement().horizontalDistance() < Mth.EPSILON) {
                        //Climbing in corner
                        setYRot(dir.key().toYRot());
                    }
                }
            } else {
                climbingCooldown--;
                if (canClimb()) {
                    ticksClimbing = 0;
                    setClimbing(true);
                }
            }
        }
    }
}

