public void render(GuiGraphics guiHelper, DeltaTracker deltaTracker) {
    if (Minecraft.getInstance().options.hideGui || Minecraft.getInstance().player.isSpectator()) {
        return;
    }
    var screenWidth = guiHelper.guiWidth();
    var screenHeight = guiHelper.guiHeight();
    Player player = Minecraft.getInstance().player;
    if (player == null)
        return;
    ItemStack stack = player.getMainHandItem();
    AbstractSpell spell;
    if (hasRightClickCasting(stack.getItem())) {
        if (ISpellContainer.isSpellContainer(stack)) {
            spell = ISpellContainer.get(stack).getSpellAtIndex(0).getSpell();
        } else {
            spell = ClientMagicData.getSpellSelectionManager().getSelectedSpellData().getSpell();
        }
    } else {
        stack = player.getOffhandItem();
        if (hasRightClickCasting(stack.getItem())) {
            if (ISpellContainer.isSpellContainer(stack)) {
                spell = ISpellContainer.get(stack).getSpellAtIndex(0).getSpell();
            } else {
                spell = ClientMagicData.getSpellSelectionManager().getSelectedSpellData().getSpell();
            }
        } else {
            return;
        }
    }
    if (stack.isEmpty() || spell == SpellRegistry.none()) {
        return;
    }

    int centerX, centerY;
    //GUI:522 (offhand slot location)
    centerX = screenWidth / 2 + 91 + 9;// + 29;
    centerY = screenHeight - 23;

    //
    //  Render Spells
    //
    //Slot Border
    guiHelper.blit(FRAME_LOCATION, centerX, centerY, 0, 0, 29, 24, 29, 24);
    //Spell Icon
    guiHelper.blit(spell.getSpellIconResource(), centerX + 3, centerY + 4, 0, 0, 16, 16, 16, 16);
    //Border + Cooldowns
    float f = ClientMagicData.getCooldownPercent(spell);
    if (f > 0 && !stack.getItem().equals(ItemRegistry.SCROLL.get())) {
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();
        int pixels = (int) (16 * f + 1f);
        guiHelper.blit(TEXTURE, centerX + 3, centerY + 20 - pixels, 47, 87, 16, pixels);
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    if(this.isTame()) {
        if(!itemstack.isEmpty()) {
            if(itemstack.getItem().isEdible()) {
                FoodProperties food = itemstack.getItem().getFoodProperties();
                if(food.isMeat() && this.entityData.get(DATA_HEALTH_ID) < TAMED_HEALTH) {
                    if(!player.isCreative()) {
                        itemstack.shrink(1);
                    }

                    this.heal(food.getNutrition());
                    return InteractionResult.SUCCESS;
                }
            }
        }

        if (this.isOwnedBy(player) && !this.level.isClientSide && !this.isFood(itemstack) && (!(itemstack.getItem().isEdible()) || !itemstack.getItem().getFoodProperties().isMeat())) {
            this.setOrderedToSit(!this.isInSittingPose());
            this.jumping = false;
            this.navigation.stop();
            this.setTarget(null);
        }
    } else if(this.isTamingItem(itemstack.getItem())) {
        if(isHostileDaytime()) {
            if(!this.level.isClientSide) {
                player.sendSystemMessage(Component.translatable("entity.betteranimalsplus.coyote.message.always_hostile"));
            }
        } else if(this.isDaytime()) {
            if(!player.isCreative()) {
                itemstack.shrink(1);
            }
            if(!this.level.isClientSide) {
                if(this.random.nextInt(100) <= 14 && !ModPlatformEvents.tame(this, player)) {
                    this.tame(player);
                    this.navigation.stop();
                    this.setTarget(null);
                    this.setOrderedToSit(true);
                    this.setHealth((float) TAMED_HEALTH);
                    this.level.broadcastEntityEvent(this, (byte) 7);
                } else {
                    this.level.broadcastEntityEvent(this, (byte) 6);
                }
            }

            return InteractionResult.SUCCESS;
        } else {
            if(!this.level.isClientSide) {
                player.sendSystemMessage(Component.translatable("entity.betteranimalsplus.coyote.message.currently_hostile"));
            }
        }
    }
    return super.mobInteract(player, hand);
}

public void aiStep() {
    super.aiStep();
    if (playerStatueCooldown > 0) {
        playerStatueCooldown--;
    }
    LivingEntity attackTarget = this.getTarget();
    if (attackTarget != null) {
        boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget.hasEffect(MobEffects.BLINDNESS);
        if (!blindness && this.deathTime == 0 && attackTarget instanceof Mob && !(attackTarget instanceof Player)) {
            forcePreyToLook(attackTarget);
        }
        if (isEntityLookingAt(attackTarget, this, 0.4)) {
            this.getLookControl().setLookAt(attackTarget.getX(), attackTarget.getY() + (double) attackTarget.getEyeHeight(), attackTarget.getZ(), (float) this.getMaxHeadYRot(), (float) this.getMaxHeadXRot());
        }
    }


    if (attackTarget != null && isEntityLookingAt(this, attackTarget, 0.4) && isEntityLookingAt(attackTarget, this, 0.4) && !isBlindfolded(attackTarget)) {
        boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget.hasEffect(MobEffects.BLINDNESS) || attackTarget instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) attackTarget).canBeTurnedToStone();
        if (!blindness && this.deathTime == 0) {
            if (this.getAnimation() != ANIMATION_SCARE) {
                this.playSound(IafSoundRegistry.GORGON_ATTACK, 1, 1);
                this.setAnimation(ANIMATION_SCARE);
            }
            if (this.getAnimation() == ANIMATION_SCARE) {
                if (this.getAnimationTick() > 10) {
                    if (!level.isClientSide) {
                        if (playerStatueCooldown == 0) {
                            EntityStoneStatue statue = EntityStoneStatue.buildStatueEntity(attackTarget);
                            statue.absMoveTo(attackTarget.getX(), attackTarget.getY(), attackTarget.getZ(), attackTarget.getYRot(), attackTarget.getXRot());
                            if (!level.isClientSide) {
                                level.addFreshEntity(statue);
                            }
                            statue.setYRot(attackTarget.getYRot());
                            statue.setYRot(attackTarget.getYRot());
                            statue.yHeadRot = attackTarget.getYRot();
                            statue.yBodyRot = attackTarget.getYRot();
                            statue.yBodyRotO = attackTarget.getYRot();
                            playerStatueCooldown = 40;
                            if (attackTarget instanceof Player) {

                                attackTarget.hurt(IafDamageRegistry.causeGorgonDamage(this), Integer.MAX_VALUE);
                            } else {
                                attackTarget.remove(RemovalReason.KILLED);
                            }
                            this.setTarget(null);

                        }
                    }
                }
            }
        }
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    Vec3 vec3 = caster.getDeltaMovement();
    double y = 0.04D;
    float radius = (float) spellStat.getRadius();
    if (rightStaff(staff)){
        radius += 1.0F;
    }
    if (WandUtil.enchantedFocus(caster)) {
        y += WandUtil.getPotencyLevel(caster) / 100.0D;
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
    }
    if (vec3.y < 0.0D) {
        y = 0.2D;
    }
    int fireTicks = caster.getRemainingFireTicks();
    if (fireTicks > 0){
        int amount = rightStaff(staff) ? 4 : 1;
        caster.setRemainingFireTicks(Math.max(fireTicks - amount, 0));
    }
    MobUtil.forcePush(caster, 0.0D, y, 0.0D);
    for (Entity entity : worldIn.getEntitiesOfClass(Entity.class, caster.getBoundingBox().inflate(radius))){
        if (entity != caster) {
            if (caster.getVehicle() == null || caster.getVehicle() != entity) {
                boolean flag = entity instanceof LivingEntity
                        || (entity instanceof AbstractArrow arrow
                        && (arrow.getOwner() == null
                        || !arrow.getOwner().getType().is(Tags.EntityTypes.BOSSES)));
                if (flag) {
                    Vec3 vec31 = new Vec3(caster.getX(), caster.getY(), caster.getZ());
                    Vec3 vec32 = new Vec3(entity.getX(), entity.getY(), entity.getZ());
                    double distance = vec31.distanceTo(vec32) + 0.1D;
                    Vec3 vec33 = new Vec3(vec32.x - vec31.x, vec32.y - vec31.y, vec32.z - vec31.z);
                    MobUtil.push(entity, vec33.x / radius / distance,
                            vec33.y / radius / distance,
                            vec33.z / radius / distance);
                    if (rightStaff(staff)) {
                        if (entity instanceof AbstractArrow arrow) {
                            if (!arrow.onGround()){
                                double d0 = arrow.getX() - caster.getX();
                                double d1 = arrow.getY() - caster.getY();
                                double d2 = arrow.getZ() - caster.getZ();
                                double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                                arrow.shoot(d0, d1 + d3 * (double)0.2F, d2, 1.0F, 10);
                            }
                        }
                    }
                }
            }
        }
    }
    ColorUtil color = new ColorUtil(0xffffff);
    ServerParticleUtil.windParticle(worldIn, color, radius - 1.0F, -0.5F, caster.getId(), caster.position());
    ServerParticleUtil.windParticle(worldIn, color, radius - 1.0F, 1.0F, caster.getId(), caster.position());
    ServerParticleUtil.windParticle(worldIn, color, radius, 0.5F, caster.getId(), caster.position());
}

private void executeAttacks() {
	if (this.currentState == State.MORTAR_SHOOTING && this.ticksProgress % 10 == 0) {
		HydraMortar mortar = new HydraMortar(TFEntities.HYDRA_MORTAR.get(), this.headEntity.level(), this.headEntity);

		// launch blasting mortars if the player is hiding
		if (this.targetEntity != null && !this.headEntity.canEntityBeSeen(this.targetEntity)) {
			mortar.setToBlasting();
		}

		this.headEntity.playSound(TFSounds.HYDRA_SHOOT.get(), 10.0F, (this.headEntity.level().getRandom().nextFloat() - this.headEntity.level().getRandom().nextFloat()) * 0.2F + 1.0F);
		this.headEntity.level().addFreshEntity(mortar);

	}
	if (this.headEntity.getState() == State.BITING) {
		// damage nearby things
		List<Entity> nearbyList = this.headEntity.level().getEntities(this.headEntity, this.headEntity.getBoundingBox().inflate(0.0, 1.0, 0.0));

		for (Entity nearby : nearbyList) {
			if (nearby instanceof LivingEntity living && nearby != this.hydra) {
				//is a player holding a shield? Let's do some extra stuff!
				if (nearby instanceof Player player && player.isBlocking()) {
					if (!player.getCooldowns().isOnCooldown(player.getUseItem())) {
						//cause severe damage and play a shatter sound
						this.headEntity.level().playSound(null, player.blockPosition(), player.getUseItem().is(Items.SHIELD) ? TFSounds.WOOD_SHIELD_SHATTERS.get() : TFSounds.METAL_SHIELD_SHATTERS.get(), SoundSource.PLAYERS, 1.0F, player.getVoicePitch());
						player.getUseItem().hurtAndBreak(112, player, player.getUsedItemHand());
					}
					//add cooldown and knockback
					player.getCooldowns().addCooldown(player.getUseItem(), 200);
					player.stopUsingItem();
					PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.15F, -this.headEntity.getDirection().getStepZ() * 0.5F));
				}

				// bite it!
				nearby.hurt(TFDamageTypes.getEntityDamageSource(living.level(), TFDamageTypes.HYDRA_BITE, this.hydra, TFEntities.HYDRA.get()), BITE_DAMAGE);

				//knockback!
				if (living instanceof Player player) {
					PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.1F, -this.headEntity.getDirection().getStepZ() * 0.5F));
				} else {
					living.knockback(-this.headEntity.getDirection().getStepX(), 0.1F, -this.headEntity.getDirection().getStepZ());
				}
			}
		}
	}

	if (this.headEntity.getState() == State.FLAMING) {
		Entity target = getHeadLookTarget();

		if (target != null && target != this.headEntity.getParent() && (!(target instanceof HydraPart) || ((HydraPart) target).getParent() != this.headEntity.getParent()) && this.hydra.level() instanceof ServerLevel serverLevel) {
			if (!target.fireImmune() && target.hurtServer(serverLevel, TFDamageTypes.getEntityDamageSource(target.level(), TFDamageTypes.HYDRA_FIRE, this.hydra, TFEntities.HYDRA.get()), FLAME_DAMAGE)) {
				target.igniteForSeconds(FLAME_BURN_FACTOR);
			}
		}
	}
}

public void stopRitual(boolean finished, boolean showInterruptedMessage) {
    if (this.level != null && !this.level.isClientSide()) {
        var recipe = this.getCurrentRitualRecipe();
        if (recipe != null) {
            if (finished) {
                var activationResource = this.itemStackHandler.getResource(0);
                ItemStack activationItem = activationResource.toStack();
                recipe.value().getRitual().finish(this.level, this.getBlockPos(), this, this.castingPlayer, activationItem);

                try (var tx = Transaction.openRoot()) {
                    int extracted = this.itemStackHandler.extract(0, activationResource, 1, tx);
                    if (extracted > 0) {
                        tx.commit();
                    }
                }
            } else {
                recipe.value().getRitual().interrupt(this.level, this.getBlockPos(), this, this.castingPlayer,
                        this.itemStackHandler.getResource(0).toStack(), showInterruptedMessage);
                //Pop activation item back into level
                try (var tx = Transaction.openRoot()) {
                    var resource = this.itemStackHandler.getResource(0);
                    if (!resource.isEmpty()) {
                        int extracted = this.itemStackHandler.extract(0, resource, 1, tx);
                        if (extracted > 0) {
                            Containers.dropItemStack(this.level, this.getBlockPos().getX(), this.getBlockPos().getY(), this.getBlockPos().getZ(),
                                    resource.toStack(extracted));
                        }
                    }
                    tx.commit();
                }
                for (ItemStack consumed : this.consumedIngredients) {
                    Containers.dropItemStack(this.level, this.getBlockPos().getX(), this.getBlockPos().getY(), this.getBlockPos().getZ(),
                            consumed);
                }
            }
        }
        this.currentRitualRecipe = null;
        this.castingPlayerId = null;
        this.castingPlayer = null;
        this.currentTime = 0;
        this.sacrificeProvided = false;
        this.itemUseProvided = false;
        if (this.remainingAdditionalIngredients != null)
            this.remainingAdditionalIngredients.clear();
        this.consumedIngredients.clear();

        NeoForge.EVENT_BUS.unregister(this.rightClickItemListener);
        NeoForge.EVENT_BUS.unregister(this.livingDeathEventListener);
        this.ritualActive = false;
        this.setChanged();
        this.markNetworkDirty();

        this.level.updateNeighborsAt(this.getBlockPos(), this.getBlockState().getBlock());
    }
}

public void performCommand(String command, EntityPlayer player, ItemStack itemStack) {

	// Open GUI:
	if(command.equals("GUI")) {
		this.playTameSound();
		this.openGUI(player);
	}

	// Tame:
	if(command.equals("Tame")) {
		this.tame(player);
		this.consumePlayersItem(player, itemStack);
	}

	// Feed:
	if(command.equals("Feed")) {
		int healAmount = 4;
		if(itemStack.getItem() instanceof ItemFood) {
			ItemFood itemFood = (ItemFood)itemStack.getItem();
			healAmount = itemFood.getHealAmount(itemStack);
		}
		this.heal((float)healAmount);
        this.playEatSound();
        if(this.getEntityWorld().isRemote) {
            EnumParticleTypes particle = EnumParticleTypes.HEART;
            double d0 = this.rand.nextGaussian() * 0.02D;
            double d1 = this.rand.nextGaussian() * 0.02D;
            double d2 = this.rand.nextGaussian() * 0.02D;
            for(int i = 0; i < 25; i++)
            	this.getEntityWorld().spawnParticle(particle, this.posX + (double)(this.rand.nextFloat() * this.width * 2.0F) - (double)this.width, this.posY + 0.5D + (double)(this.rand.nextFloat() * this.height), this.posZ + (double)(this.rand.nextFloat() * this.width * 2.0F) - (double)this.width, d0, d1, d2);
        }
		this.consumePlayersItem(player, itemStack);
	}

	// Equip Armor:
	if(command.equals("Equip Item")) {
		ItemStack equippedItem = this.inventory.getEquipmentStack(this.inventory.getSlotForEquipment(itemStack));
		if(equippedItem != null)
			this.dropItem(equippedItem);
		ItemStack equipStack = itemStack.copy();
		equipStack.setCount(1);
		this.inventory.setEquipmentStack(equipStack.copy());
		this.consumePlayersItem(player, itemStack);
	}

	// Sit:
	if(command.equals("Sit")) {
		this.playTameSound();
        this.setAttackTarget((EntityLivingBase)null);
        this.clearMovement();
    	this.setSitting(!this.isSitting());
        this.isJumping = false;
	}

	super.performCommand(command, player, itemStack);
}

public static void onUseItem(PlayerInteractEvent.RightClickItem event) {
    var player = event.getEntity();
    if (player.level.isClientSide) {
        MinecraftInstanceHelper.ifPlayerPresent(localPlayer -> {
            if (ClientMagicData.isCasting() && player.getUUID().equals(localPlayer.getUUID())) {
                event.setCanceled(true);
            }
        });
    } else {
        var magicData = MagicData.getPlayerMagicData(player);
        if (magicData.isCasting() && event.getItemStack() != magicData.getPlayerCastingItem()) {
            event.setCanceled(true);
        }
    }
    if (event.isCanceled()) {
        return;
    }

    var level = player.level;
    var hand = event.getHand();
    ItemStack itemStack = player.getItemInHand(hand);
    if (itemStack.has(ComponentRegistry.CASTING_IMPLEMENT)) {
        SpellSelectionManager spellSelectionManager = new SpellSelectionManager(player);
        SpellSelectionManager.SelectionOption selectionOption = spellSelectionManager.getSelection();
        if (selectionOption == null || selectionOption.spellData.equals(SpellData.EMPTY)) {
            //IronsSpellbooks.LOGGER.debug("CastingItem.Use.1 {} {}", level.isClientSide, hand);
            return;
        }
        SpellData spellData = selectionOption.spellData;
        int spellLevel = spellData.getSpell().getLevelFor(spellData.getLevel(), player);
        if (level.isClientSide()) {
            if (ClientMagicData.isCasting()) {
                //IronsSpellbooks.LOGGER.debug("CastingItem.Use.2 {} {}", level.isClientSide, hand);
                event.setCancellationResult(InteractionResult.CONSUME);
            } else if (ClientMagicData.getPlayerMana() < spellData.getSpell().getManaCost(spellLevel)
                    || ClientMagicData.getCooldowns().isOnCooldown(spellData.getSpell())
                    || !ClientMagicData.getSyncedSpellData(player).isSpellLearned(spellData.getSpell())) {
                //IronsSpellbooks.LOGGER.debug("CastingItem.Use.3 {} {}", level.isClientSide, hand);
                return;
            } else {
                //IronsSpellbooks.LOGGER.debug("CastingItem.Use.4 {} {}", level.isClientSide, hand);
                event.setCancellationResult(InteractionResult.CONSUME);
            }
        }

        var castingSlot = hand.ordinal() == 0 ? SpellSelectionManager.MAINHAND : SpellSelectionManager.OFFHAND;

        if (spellData.getSpell().attemptInitiateCast(itemStack, spellLevel, level, player, selectionOption.getCastSource(), true, castingSlot)) {
            event.setCancellationResult(InteractionResult.CONSUME);
        } else {
            //IronsSpellbooks.LOGGER.debug("CastingItem.Use.6 {} {}", level.isClientSide, hand);
            event.setCancellationResult(InteractionResult.FAIL);
        }
        event.setCanceled(true);
    }
}

public void tick(){
    LivingEntity target = EntityMurmurHead.this.getTarget();
    Entity body = EntityMurmurHead.this.getBody();
    if(target != null){
        double dist = Math.sqrt(EntityMurmurHead.this.distanceToSqr(target.getEyePosition()));
        double bodyDist = body != null ? body.distanceTo(target) : 0.0;
        if(bodyDist > 16 && time > 30){
            if(body instanceof EntityMurmur){
                EntityMurmur murmur = (EntityMurmur) body;
                murmur.setTarget(target);
                murmur.getNavigation().moveTo(target, 1.35D);
            }
        }
        if(bodyDist > 64){
            EntityMurmurHead.this.setPulledIn(true);
        }else if(biteCooldown == 0){
            EntityMurmurHead.this.setPulledIn(false);
            Vec3 moveTo = target.getEyePosition();
            if(time > 30){
                if(!EntityMurmurHead.this.isAngry()){
                    EntityMurmurHead.this.playSound(AMSoundRegistry.MURMUR_ANGER.get(), 1.5F * EntityMurmurHead.this.getSoundVolume(), EntityMurmurHead.this.getVoicePitch());
                    EntityMurmurHead.this.gameEvent(GameEvent.ENTITY_ROAR);
                }
                EntityMurmurHead.this.setAngry(true);
                EntityMurmurHead.this.getNavigation().moveTo(moveTo.x, moveTo.y, moveTo.z, 1.3D);
            }else{
                if(time == 0){
                    emergeFrom = EntityMurmurHead.this.getNeckTop(1.0F).add(0, 0.5F, 0);
                    Vec3 face = moveTo.subtract(emergeFrom);
                }
                boolean clockwise = false;
                float circleDistance = 2.5F;
                float circlingTime = 30 * time;
                float angle = (Maths.STARTING_ANGLE * (clockwise ? -circlingTime : circlingTime));
                double extraX = circleDistance * Mth.sin(Mth.PI + angle);
                double extraZ = circleDistance * Mth.cos(angle);
                double y = Math.max(emergeFrom.y + 2, target.getEyeY());
                Vec3 vec3 = new Vec3(emergeFrom.x + extraX, y, emergeFrom.z + extraZ);
                EntityMurmurHead.this.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 0.7D);
            }
            EntityMurmurHead.this.lookAt(EntityAnchorArgument.Anchor.EYES, moveTo);
            if(dist < 1.5F && EntityMurmurHead.this.hasLineOfSight(target)){
                EntityMurmurHead.this.playSound(AMSoundRegistry.MURMUR_ATTACK.get(), EntityMurmurHead.this.getSoundVolume(), EntityMurmurHead.this.getVoicePitch());
                biteCooldown = 5 + EntityMurmurHead.this.getRandom().nextInt(15);
                target.hurt(EntityMurmurHead.this.damageSources().mobAttack(EntityMurmurHead.this), 5.0F);
            }
        }else{
            EntityMurmurHead.this.setPulledIn(true);
            EntityMurmurHead.this.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            EntityMurmurHead.this.setAngry(false);
        }
        time++;
    }
    if(biteCooldown > 0){
        biteCooldown--;
    }
}

public void tick() {
    if (leapSearchCooldown > 0) {
        leapSearchCooldown--;
    }
    if (climbing) {
        float inDir = EntitySugarGlider.this.getAttachmentFacing() == Direction.DOWN && EntitySugarGlider.this.getY() > climb.getY() + 0.3F ? 0.5F + EntitySugarGlider.this.getBbWidth() * 0.5F : 0.5F;
        Vec3 offset = Vec3.atCenterOf(climb).subtract(0, 0, 0).add(climbOffset.getStepX() * inDir, climbOffset.getStepY() * inDir, climbOffset.getStepZ() * inDir);
        final double d0 = climb.getX() + 0.5F - EntitySugarGlider.this.getX();
        final double d2 = climb.getZ() + 0.5F - EntitySugarGlider.this.getZ();
        final double xzDistSqr = d0 * d0 + d2 * d2;
        if (EntitySugarGlider.this.getY() > offset.y - 0.3F - EntitySugarGlider.this.getBbHeight()) {
            EntitySugarGlider.this.stopClimbing = true;
        }
        if (xzDistSqr < 3 && EntitySugarGlider.this.getAttachmentFacing() != Direction.DOWN) {
            Vec3 silly = new Vec3(d0, 0, d2).normalize().scale(0.1);
            EntitySugarGlider.this.setDeltaMovement(EntitySugarGlider.this.getDeltaMovement().add(silly));
        } else {
            EntitySugarGlider.this.getNavigation().moveTo(offset.x, offset.y, offset.z, 1F);
        }
        if (EntitySugarGlider.this.getAttachmentFacing() == Direction.DOWN) {
            climbTimeout++;
            climbTime = 0;
        } else {
            climbTimeout = 0;
            climbTime++;
            if (climbTime > 40 && leapSearchCooldown == 0) {
                BlockPos leapTo = findLeapPos(EntitySugarGlider.this.shouldForage() && random.nextInt(5) != 0);
                leapSearchCooldown = 5 + EntitySugarGlider.this.getRandom().nextInt(10);
                if (leapTo != null) {
                    EntitySugarGlider.this.stopClimbing = false;
                    EntitySugarGlider.this.setGliding(true);
                    EntitySugarGlider.this.getNavigation().stop();
                    EntitySugarGlider.this.entityData.set(ATTACHED_FACE, Direction.DOWN);
                    glide = leapTo;
                    climbing = false;
                }
            }
        }
    } else if (glide != null) {
        EntitySugarGlider.this.stopClimbing = false;
        EntitySugarGlider.this.setGliding(true);
        if (airtime > 5 && (EntitySugarGlider.this.horizontalCollision || EntitySugarGlider.this.onGround()
                || Math.sqrt(EntitySugarGlider.this.distanceToSqr(Vec3.atCenterOf(glide))) < 1.1F)) {
            EntitySugarGlider.this.setGliding(false);
            EntitySugarGlider.this.detachCooldown = 20 + random.nextInt(80);
            itsOver = true;
        }
        Vec3 fly = Vec3.atCenterOf(glide).subtract(EntitySugarGlider.this.position()).normalize().scale(0.3F);
        EntitySugarGlider.this.setDeltaMovement(fly);

        Vec3 move = EntitySugarGlider.this.getDeltaMovement();
        double d0 = move.horizontalDistance();
        EntitySugarGlider.this.setXRot((float) (-Mth.atan2(move.y, d0) * (double) Mth.RAD_TO_DEG));
        EntitySugarGlider.this.setYRot(((float) Mth.atan2(move.z, move.x)) * Mth.RAD_TO_DEG - 90F);
        airtime++;
    }
}

public static void tickCharmedEntity(LivingEntity entity) {
    EntitySiren siren = getSiren(entity);
    if (siren != null && siren.isActuallySinging()) {
        if (EntitySiren.isWearingEarplugs(entity) || getSingTime(entity) > IafConfig.sirenMaxSingTime) {
            clearCharmedStatus(entity);
            siren.singCooldown = IafConfig.sirenTimeBetweenSongs;
        } else {
            if (!siren.isAlive() || entity.distanceTo(siren) > EntitySiren.SEARCH_RANGE * 2 || entity instanceof Player && ((Player) entity).isCreative()) {
                clearCharmedStatus(entity);
                return;
            }
            if (entity.distanceTo(siren) < 5D) {
                clearCharmedStatus(entity);
                siren.singCooldown = IafConfig.sirenTimeBetweenSongs;
                siren.setSinging(false);
                siren.setTarget(entity);
                siren.setAggressive(true);
                siren.triggerOtherSirens(entity);
                return;
            }
            CompoundTag sirenData = getOrCreateCharmData(entity);
            sirenData.putBoolean(SIREN_CHARMED, true);
            sirenData.putInt(SIREN_TIME, getSingTime(entity));
            updateCharmData(entity, sirenData);

            if (rand.nextInt(7) == 0) {
                for (int i = 0; i < 5; i++) {
                    entity.level.addParticle(ParticleTypes.HEART,
                        entity.getX() + ((rand.nextDouble() - 0.5D) * 3),
                        entity.getY() + ((rand.nextDouble() - 0.5D) * 3),
                        entity.getZ() + ((rand.nextDouble() - 0.5D) * 3),
                        0, 0, 0);
                }
            }
            if (entity.horizontalCollision) {
                entity.setJumping(true);
            }
            double motionXAdd = (Math.signum(siren.getX() - entity.getX()) * 0.5D - entity.getDeltaMovement().x) * 0.100000000372529;
            double motionYAdd = (Math.signum(siren.getY() - entity.getY() + 1) * 0.5D - entity.getDeltaMovement().y) * 0.100000000372529;
            double motionZAdd = (Math.signum(siren.getZ() - entity.getZ()) * 0.5D - entity.getDeltaMovement().z) * 0.100000000372529;
            entity.setDeltaMovement(entity.getDeltaMovement().add(motionXAdd, motionYAdd, motionZAdd));
            if (entity.isPassenger()) {
                entity.stopRiding();
            }
            if (!(entity instanceof Player)) {
                double d0 = siren.getX() - entity.getX();
                double d2 = siren.getZ() - entity.getZ();
                double d1 = siren.getY() - 1 - entity.getY();
                double d3 = Math.sqrt(d0 * d0 + d2 * d2);
                float f = (float) (Mth.atan2(d2, d0) * (180D / Math.PI)) - 90.0F;
                float f1 = (float) (-(Mth.atan2(d1, d3) * (180D / Math.PI)));
                entity.setXRot(updateRotation(entity.getXRot(), f1, 30F));
                entity.setYRot(updateRotation(entity.getYRot(), f, 30F));
            }
        }
    }
}

public ActionResult useOnBlock(ItemUsageContext context) {
	World world = context.getWorld();
	BlockPos pos = context.getBlockPos();
	ItemStack stack = context.getStack();
	PlayerEntity player = context.getPlayer();
	boolean client = world.isClient;
	BlockState state = world.getBlockState(pos);
	if (!sigil.active) {
		ItemPlacementContext placementContext = new ItemPlacementContext(context);
		if (!state.canReplace(placementContext)) {
			pos = pos.offset(context.getSide());
		}
		if (!world.getBlockState(pos).canReplace(placementContext)) {
			return ActionResult.PASS;
		}
		BlockState sigilState = BWObjects.SIGIL.getPlacementState(placementContext);
		if (sigilState.canPlaceAt(world, pos)) {
			if (!client) {
				world.playSound(null, pos, sigilState.getSoundGroup().getPlaceSound(), SoundCategory.BLOCKS, 1, MathHelper.nextFloat(world.random, 0.8f, 1.2f));
				world.setBlockState(pos, sigilState);
				BlockEntity blockEntity = world.getBlockEntity(pos);
				SigilHolder sigilHolder = (SigilHolder) blockEntity;
				sigilHolder.setSigil(sigil);
				sigilHolder.setUses(sigil.uses * (BewitchmentAPI.getFamiliar(player) == BWEntityTypes.SNAKE ? 2 : 1));
				sigilHolder.setOwner(player.getUuid());
				sigilHolder.syncSigilHolder(blockEntity);
				blockEntity.markDirty();
				if (player instanceof ServerPlayerEntity serverPlayerEntity) {
					Criteria.PLACED_BLOCK.trigger(serverPlayerEntity, pos, stack);
					if (!player.isCreative()) {
						stack.decrement(1);
					}
				}
			}
			return ActionResult.success(client);
		}
	} else {
		BlockEntity blockEntity = world.getBlockEntity(pos);
		if (blockEntity instanceof SigilHolder sigilHolder && state.getBlock() != BWObjects.SIGIL) {
			if (state.getBlock() instanceof DoorBlock && state.get(DoorBlock.HALF) == DoubleBlockHalf.UPPER) {
				blockEntity = world.getBlockEntity(pos.down());
			}
			if (!client) {
				sigilHolder.setSigil(sigil);
				sigilHolder.setUses(sigil.uses * (BewitchmentAPI.getFamiliar(player) == BWEntityTypes.SNAKE ? 2 : 1));
				sigilHolder.setOwner(player.getUuid());
				sigilHolder.syncSigilHolder(blockEntity);
				blockEntity.markDirty();
				if (!player.isCreative()) {
					stack.decrement(1);
				}
			}
			return ActionResult.success(client);
		}
	}
	return super.useOnBlock(context);
}

	public void tick() {
		if (this.lich.getTeleportInvisibility() > 0) return;
		LivingEntity targetedEntity = this.lich.getTarget();
		if (targetedEntity == null) return;
		float dist = this.lich.distanceTo(targetedEntity);
		// spawn minions every so often
		if (this.lich.getAttackCooldown() % 15 == 0) this.checkAndSpawnMinions();

		boolean hasLineOfSight = this.lich.getSensing().hasLineOfSight(targetedEntity);
		if (hasLineOfSight != this.seeTime > 0) this.seeTime = 0;

		if (hasLineOfSight) ++this.seeTime;
        else --this.seeTime;

		if (dist < ATTACK_RANGE && this.seeTime >= 20) {
			this.lich.getNavigation().stop();
			++this.strafingTime;
		} else this.strafingTime = -1;

		if (this.strafingTime >= 20) {
			if ((double)this.lich.getRandom().nextFloat() < 0.3) this.strafingClockwise = !this.strafingClockwise;
			if ((double)this.lich.getRandom().nextFloat() < 0.3) this.strafingBackwards = !this.strafingBackwards;
			this.strafingTime = 0;
		}

		if (this.strafingTime > -1) {
			if (dist > (double)(ATTACK_RANGE * 0.75F)) this.strafingBackwards = false;
            else if (dist < (double)(ATTACK_RANGE * 0.25F)) this.strafingBackwards = true;

			this.lich.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
			this.lich.lookAt(targetedEntity, 30.0F, 30.0F);
		} else {
			this.lich.getLookControl().setLookAt(targetedEntity, 30.0F, 30.0F);
		}

		if (this.lich.getAttackCooldown() == 0) {
			ServerLevel serverLevel = getServerLevel(this.lich);
			if (dist < 2.0F) {
				// melee attack
				this.lich.doHurtTarget(serverLevel, targetedEntity);

				this.lich.swing(InteractionHand.MAIN_HAND);
				this.lich.setAttackCooldown(20);
			} else if (dist < ATTACK_RANGE && this.lich.getSensing().hasLineOfSight(targetedEntity)) {
				if (this.lich.getNextAttackType() == 0) this.lich.launchProjectileAt(new LichBolt(serverLevel, this.lich));
				else this.lich.launchProjectileAt(new LichBomb(serverLevel, this.lich));

				this.lich.swing(InteractionHand.MAIN_HAND);
				this.lich.setNextAttackType(this.lich.getRandom().nextBoolean() ? 0 : 1);
				this.lich.setAttackCooldown(60);
			} else {
				// if not, teleport around
				this.lich.teleportToNewTarget(targetedEntity, ATTACK_RANGE, null);
				this.lich.setAttackCooldown(20);
			}
		}
	}

protected void crushBlocksInRing(int width, int ringStartX, int ringStartZ, float dropChance) {
    BlockPos.MutableBlockPos mutableBlockPos = new BlockPos.MutableBlockPos();
    float lowestFoot = 0.0F;
    for(LuxtructosaurusLegSolver.Leg leg : legSolver.legs){
        float height = leg.getHeight(1.0F);
        if(height > lowestFoot){
            lowestFoot = height;
        }
    }
    int feetY = this.blockPosition().getY() - (int)lowestFoot;
    BlockPos center = new BlockPos(ringStartX, feetY, ringStartZ);
    if(net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this) || this.isVehicle() && this.getControllingPassenger() instanceof Player){
        for (int y = 0; y <= STOMP_CRUSH_HEIGHT; y++) {
            List<MovingBlockData> dataPerYLevel = new ArrayList<>();
            int currentBlocksInChunk = 0;
            for (int i = -width - 1; i <= width + 1; i++) {
                for (int j = -width - 1; j <= width + 1; j++) {
                    mutableBlockPos.set(this.getBlockX() + i, feetY + y, this.getBlockZ() + j);
                    double dist = Math.sqrt(mutableBlockPos.distSqr(center));
                    if (dist <= width && level().isLoaded(mutableBlockPos)) {
                        BlockState state = level().getBlockState(mutableBlockPos);
                        if (state.is(ACTagRegistry.UNMOVEABLE) || state.isAir() || state.canBeReplaced() || state.getBlock().getExplosionResistance() > AlexsCaves.COMMON_CONFIG.atlatitanMaxExplosionResistance.get()) {
                            continue;
                        } else {
                            BlockEntity te = level().getBlockEntity(mutableBlockPos);
                            BlockPos offset = mutableBlockPos.immutable().subtract(center);
                            MovingBlockData data = new MovingBlockData(state, state.getShape(level(), mutableBlockPos), offset, te == null ? null : te.saveWithoutMetadata());
                            dataPerYLevel.add(data);

                            if (currentBlocksInChunk < 16) {
                                currentBlocksInChunk++;
                            } else {
                                CrushedBlockEntity crushed = ACEntityRegistry.CRUSHED_BLOCK.get().create(level());
                                crushed.moveTo(Vec3.atCenterOf(center.above(y)));
                                crushed.setAllBlockData(FallingTreeBlockEntity.createTagFromData(dataPerYLevel));
                                crushed.setPlacementCooldown(10);
                                crushed.setDropChance(dropChance);
                                level().addFreshEntity(crushed);
                                dataPerYLevel.clear();
                                currentBlocksInChunk = 0;
                            }
                            level().setBlockAndUpdate(mutableBlockPos, Blocks.AIR.defaultBlockState());
                        }
                    }
                }
            }
            if (!dataPerYLevel.isEmpty()) {
                CrushedBlockEntity crushed = ACEntityRegistry.CRUSHED_BLOCK.get().create(level());
                crushed.moveTo(Vec3.atCenterOf(center.above(y)));
                crushed.setAllBlockData(FallingTreeBlockEntity.createTagFromData(dataPerYLevel));
                crushed.setDropChance(dropChance);
                crushed.setPlacementCooldown(1);
                level().addFreshEntity(crushed);
            }
        }
    }

}

public void tick() {
    if (jumpAttemptCooldown > 0) {
        jumpAttemptCooldown--;
    }
    LivingEntity target = tiger.getTarget();
    if (target != null && target.isAlive()) {
        final double dist = tiger.distanceTo(target);
        if (dist < 10 && tiger.getLastHurtByMob() != null && tiger.getLastHurtByMob().isAlive()) {
            tiger.setStealth(false);
        } else {
            if (dist > 20) {
                tiger.setRunning(false);
                tiger.setStealth(true);
            }
        }
        if (dist <= 20) {
            tiger.setStealth(false);
            tiger.setRunning(true);
            if (tiger.entityData.get(LAST_SCARED_MOB_ID) != target.getId()) {
                tiger.entityData.set(LAST_SCARED_MOB_ID, target.getId());
                target.addEffect(new MobEffectInstance(AMEffectRegistry.FEAR.get(), 100, 0, true, false));
            }
        }
        if (dist < 12 && tiger.getAnimation() == NO_ANIMATION && tiger.onGround() && jumpAttemptCooldown == 0 && !tiger.isHolding()) {
            tiger.setAnimation(ANIMATION_LEAP);
            jumpAttemptCooldown = 70;
        }
        if ((jumpAttemptCooldown > 0 || tiger.isInWaterOrBubble()) && !tiger.isHolding() && tiger.getAnimation() == NO_ANIMATION && dist < 4 + target.getBbWidth()) {
            tiger.setAnimation(tiger.getRandom().nextBoolean() ? ANIMATION_PAW_L : ANIMATION_PAW_R);
        }
        if (dist < 4 + target.getBbWidth() && (tiger.getAnimation() == ANIMATION_PAW_L || tiger.getAnimation() == ANIMATION_PAW_R) && tiger.getAnimationTick() == 8) {
            target.hurt(tiger.damageSources().mobAttack(tiger), 7 + tiger.getRandom().nextInt(5));
        }
        if (tiger.getAnimation() == ANIMATION_LEAP) {
            tiger.getNavigation().stop();
            Vec3 vec = target.position().subtract(tiger.position());
            tiger.setYRot(-((float) Mth.atan2(vec.x, vec.z)) * Mth.RAD_TO_DEG);
            tiger.yBodyRot = tiger.getYRot();
            if (tiger.getAnimationTick() >= 5 && tiger.getAnimationTick() < 11 && tiger.onGround()) {
                Vec3 vector3d1 = new Vec3(target.getX() - this.tiger.getX(), 0.0D, target.getZ() - this.tiger.getZ());
                if (vector3d1.lengthSqr() > 1.0E-7D) {
                    vector3d1 = vector3d1.normalize().scale(Math.min(dist, 15) * 0.2F);
                }
                this.tiger.setDeltaMovement(vector3d1.x, vector3d1.y + 0.3F + 0.1F * Mth.clamp(target.getEyeY() - this.tiger.getY(), 0, 2), vector3d1.z);
            }
            if (dist < target.getBbWidth() + 3 && tiger.getAnimationTick() >= 15) {
                target.hurt(tiger.damageSources().mobAttack(tiger), 2);
                tiger.setRunning(false);
                tiger.setStealth(false);
                tiger.setHolding(true);
            }
        } else {
            if(target != null){
                tiger.getNavigation().moveTo(target, tiger.isStealth() ? 0.75F : 1.0F);
            }
        }
    }
}

public ActionResult useOnBlock(ItemUsageContext context) {
	World world = context.getWorld();
	BlockPos pos = context.getBlockPos();
	BlockState state = world.getBlockState(pos);
	PlayerEntity player = context.getPlayer();
	boolean client = world.isClient;
	AthameStrippingRecipe entry = world.getRecipeManager().listAllOfType(BWRecipeTypes.ATHAME_STRIPPING_RECIPE_TYPE).stream().filter(recipe -> recipe.log == state.getBlock()).findFirst().orElse(null);
	if (entry != null) {
		world.playSound(player, pos, BWSoundEvents.ITEM_ATHAME_STRIP, SoundCategory.BLOCKS, 1, 1);
		if (!client) {
			world.setBlockState(pos, entry.strippedLog.getDefaultState().with(PillarBlock.AXIS, state.get(PillarBlock.AXIS)), 11);
			if (player != null) {
				context.getStack().damage(1, player, stackUser -> stackUser.sendToolBreakStatus(context.getHand()));
				if (world.random.nextFloat() < 2 / 3f) {
					ItemStack bark = entry.getOutput(world.getRegistryManager()).copy();
					if (!player.getInventory().insertStack(bark)) {
						player.dropStack(bark);
					}
				}
			}
		}
		return ActionResult.success(client);
	}
	BlockEntity blockEntity = world.getBlockEntity(state.getBlock() instanceof DoorBlock && state.get(DoorBlock.HALF) == DoubleBlockHalf.UPPER ? pos.down() : pos);
	if (blockEntity instanceof SigilHolder sigilHolder) {
		if (player != null && player.getUuid().equals(sigilHolder.getOwner())) {
			if (!client && !sigilHolder.getEntities().isEmpty()) {
				boolean whitelist = sigilHolder.getModeOnWhitelist();
				world.playSound(null, pos, BWSoundEvents.BLOCK_SIGIL_PLING, SoundCategory.BLOCKS, 1, whitelist ? 0.5f : 1);
				player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.toggle_" + (!whitelist ? "whitelist" : "blacklist")), true);
				sigilHolder.setModeOnWhitelist(!whitelist);
				blockEntity.markDirty();
			}
			return ActionResult.success(client);
		}
	} else if (blockEntity instanceof TaglockHolder taglockHolder) {
		if (player != null && player.getUuid().equals(taglockHolder.getOwner()) && taglockHolder.getFirstEmptySlot() != 0) {
			if (!client) {
				ItemScatterer.spawn(world, pos, taglockHolder.getTaglockInventory());
				taglockHolder.syncTaglockHolder(blockEntity);
				blockEntity.markDirty();
			}
			return ActionResult.success(client);
		}
	} else if (blockEntity instanceof Lockable lockable) {
		if (player != null && player.getUuid().equals(lockable.getOwner()) && !lockable.getEntities().isEmpty()) {
			if (!client) {
				boolean whitelist = lockable.getModeOnWhitelist();
				world.playSound(null, pos, BWSoundEvents.BLOCK_SIGIL_PLING, SoundCategory.BLOCKS, 1, whitelist ? 0.5f : 1);
				player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.toggle_" + (!whitelist ? "whitelist" : "blacklist")), true);
				lockable.setModeOnWhitelist(!whitelist);
				blockEntity.markDirty();
			}
			return ActionResult.success(client);
		}
	}
	return super.useOnBlock(context);
}

protected void updateCachedState() {
    ItemStack mainItem = this.menu.getMainItem();
    if (!ItemStack.isSameItemSameComponents(mainItem, this.lastMainItem)) {
        List<AffixInstance> newAffixes = AugmentingMenu.computeItemAffixes(mainItem);

        if (ItemStack.isSameItem(mainItem, this.lastMainItem) && this.currentItemAffixes.size() == newAffixes.size()) {
            this.list.setEntries(newAffixes);
            this.list.setSelected(this.lastSelection);
        }
        else {
            this.list.setEntries(newAffixes);
        }

        this.currentItemAffixes = newAffixes;
        this.lastMainItem = mainItem.copy();
        this.computeAlternatives(this.list.getSelected());
    }

    if (this.lastSelection != this.list.getSelected()) {
        this.lastSelection = this.list.getSelected();
        this.computeAlternatives(this.lastSelection);
    }

    int selected = this.getSelectedAffix();
    if (selected == DropDownList.NO_SELECTION) {
        Component comp = Component.translatable("button.apotheosis.augmenting.no_selection").withStyle(ChatFormatting.RED);
        this.upgradeBtn.active = false;
        this.upgradeBtn.setInactiveMessage(comp);
        this.rerollBtn.active = false;
        this.rerollBtn.setInactiveMessage(comp);
    }
    else {
        this.upgradeBtn.active = true;
        this.rerollBtn.active = true;

        AffixInstance current = this.currentItemAffixes.get(selected);

        if (!AugmentingMenu.canAugment(current)) {
            this.upgradeBtn.active = false;
            this.upgradeBtn.setInactiveMessage(Component.translatable("button.apotheosis.augmenting.max_level").withStyle(ChatFormatting.RED));
        }

        if (this.alternativePages.isEmpty()) {
            this.rerollBtn.active = false;
            this.rerollBtn.setInactiveMessage(Component.translatable("button.apotheosis.augmenting.no_alternatives").withStyle(ChatFormatting.RED));
        }

        if (this.upgradeBtn.isActive() && !this.menu.hasUpgradeCost() && !this.menu.player.isCreative()) {
            this.upgradeBtn.active = false;
            this.upgradeBtn.setInactiveMessage(CommonComponents.EMPTY);
        }

        if (this.rerollBtn.isActive() && !this.menu.hasRerollCost() && !this.menu.player.isCreative()) {
            this.rerollBtn.active = false;
            this.rerollBtn.setInactiveMessage(CommonComponents.EMPTY);
        }
    }
}

public void aiStep() {
	super.aiStep();
	ItemStack stack = this.getMainHandItem();
	ItemStack newStack = new ItemStack(Items.AIR);
	if (stack.getItem() != Items.AIR) {
		timer++;
		if (timer == 600) {
			this.spawnItem(stack);
			this.setItemInHand(InteractionHand.MAIN_HAND, newStack);
			timer = 0;
		}
		if (this.getLastHurtByMob() != null && timer < 600) {
			this.spawnItem(stack);
			this.setItemInHand(InteractionHand.MAIN_HAND, newStack);
			timer = 0;
		}
	}
	if (this.tickCount > 1000 && this.random.nextInt(1000) == 213) {
		this.setStealing(true);
	}
	if (this.isStealing()) {
		tryStealing++;
		if (this.tryStealing == 600) {
			this.setStealing(false);
			tryStealing = 0;
		}
		for (Player entity : this.level().getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(8, 8, 8))) {
			if (entity.getMainHandItem() != new ItemStack(Items.AIR) && !entity.isCreative() && this.getMainHandItem().isEmpty()) {
				this.getNavigation().moveTo(entity, 1);
				for (Player closePlayer : this.level().getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(1, 2, 1))) {
					if (this.getMainHandItem().isEmpty() && !closePlayer.getMainHandItem().isEmpty()) {
						ItemStack stack1 = closePlayer.getItemInHand(InteractionHand.MAIN_HAND);
						if (closePlayer.getItemInHand(InteractionHand.MAIN_HAND).getCount() > 1) {
							stack1.shrink(1);
							closePlayer.setItemInHand(InteractionHand.MAIN_HAND, stack1);
						} else {
							ItemStack airStack = new ItemStack(Items.AIR);
							closePlayer.setItemInHand(InteractionHand.MAIN_HAND, airStack);
						}
						this.setItemInHand(InteractionHand.MAIN_HAND, stack1);
						tryStealing = 0;
					}
				}
			}
		}
	}
	Vec3 vec3 = this.getDeltaMovement();
	if (!this.onGround() && this.level().getBlockState(this.blockPosition().below()).isAir() && !this.isClimbing()) {
		this.setFallingTicks(this.getFallingTicks() + 1);
		if (this.getFallingTicks() < 10) {
			this.setDeltaMovement(vec3.multiply(1.0D, 0.75D, 1.0D));
		} else {
			this.setDeltaMovement(vec3.multiply(vec3.x * 2.5D, 0.5D, vec3.z * 2.5D));
		}
	} else {
		this.setFallingTicks(0);
	}
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
	ItemStack itemstack = player.getItemInHand(hand);
	Item item = itemstack.getItem();

	if (item instanceof PaleopediaItem) {
		CompoundTag tag = itemstack.getTag();
		final List<Integer> already = new ArrayList<>(Ints.asList(tag.getIntArray("Pages")));
		if (!already.contains(EnumPaleoPages.CAMPTOSAURUS.ordinal())) {
			EnumPaleoPages.addPage(EnumPaleoPages.fromInt(EnumPaleoPages.CAMPTOSAURUS.ordinal()), itemstack);
			player.displayClientMessage(Component.translatable("paleopedia.camptosaurus_added"), true);
		} else {
			player.displayClientMessage(Component.translatable("paleopedia.camptosaurus_already_added"), true);
		}
		return InteractionResult.SUCCESS;
	}

	if (!this.isTame()) {
		if (item == PFBlocks.CLADOPHLEBIS.get().asItem()) {
			if (!player.getAbilities().instabuild) itemstack.shrink(1);
			if (this.random.nextInt(3) == 0 && !net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, player)) {
				this.tame(player);
				this.navigation.stop();
				this.setTarget((LivingEntity) null);
				this.setOrderedToSit(true);
				this.level().broadcastEntityEvent(this, (byte) 7);
			} else {
				this.level().broadcastEntityEvent(this, (byte) 6);
			}
			return InteractionResult.SUCCESS;
		}
		return InteractionResult.PASS;
	} else {
		if (!this.isBaby()) {
			if (player.isShiftKeyDown()) {
				this.openCustomInventoryScreen(player);
				return InteractionResult.SUCCESS;
			} else {
				if (!this.isSaddled() && item == Items.SADDLE) {
					if (!player.getAbilities().instabuild) itemstack.shrink(1);
					this.setSaddled(true);
					this.inventory.setItem(0, new ItemStack(Items.SADDLE));
					this.level().playSound(player, this.getX(), this.getY(), this.getZ(), SoundEvents.PIG_SADDLE, SoundSource.NEUTRAL, 0.5F, 1.0F);
					return InteractionResult.SUCCESS;
				}
				if (!this.hasChest() && item == Items.CHEST) {
					this.equipChest(player, itemstack);
					return InteractionResult.SUCCESS;
				}
				if (!this.isVehicle() && this.isSaddled()) {
					player.startRiding(this);
					return InteractionResult.SUCCESS;
				}
			}
		}
	}

	return super.mobInteract(player, hand);
}

