					return InteractionResult.SUCCESS;
				}
				if (this.isSaddled() && this.getPassengers().size() < this.getMaxRiders()) {
					player.startRiding(this);
					return InteractionResult.SUCCESS;
				}
			}
		}
	}
	return super.mobInteract(player, hand);
}

public void tick() {
    super.tick();
    this.setYHeadRot(this.getYRot());
    prevMergeProgress = mergeProgress;
    prevAttackProgress = attackProgress;
    if (prevHeadCount != this.getHeadCount()) {
        refreshDimensions();
        if (this.mergeProgress < 5.0F) {
            this.mergeProgress++;
        } else {
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(Mth.clamp(getHeadCount() * 10, 10, 100));
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(Mth.clamp(getHeadCount() * 2, 2, 10));
            double d = this.getAttribute(Attributes.MAX_HEALTH).getValue();
            if(this.getHealth() < d && getHeadCount() > 0){
                this.heal((float) Math.ceil(d - this.getHealth()));
            }
            prevHeadCount = this.getHeadCount();
        }
    }
    if (this.entityData.get(ATTACK_TICK) > 0) {
        this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
        if (attackProgress < 5F) {
            attackProgress++;
        }
    } else {
        LivingEntity target = this.getTarget();
        if (attackProgress >= 3F && target != null && this.distanceTo(target) < getSlimeSize(1.0F)) {
            target.hurt(damageSources().mobAttack(this), 4F + getHeadCount() * 2);
        }
        if (attackProgress > 0F) {
            attackProgress--;
        }
    }
    if (level().isClientSide && isAlive()) {
        float slimeSize = getSlimeSize(1);
        for (int i = 0; i < Math.ceil(slimeSize); i++) {
            double particleX = this.getX() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
            double particleY = this.getY() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
            double particleZ = this.getZ() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
            level().addParticle(ACParticleRegistry.FERROUSLIME.get(), particleX, particleY, particleZ, this.getId(), 0, 0);
        }
        AlexsCaves.PROXY.playWorldSound(this, (byte) 13);
    } else {
        LivingEntity living = this.getTarget();
        if (living != null && living.isAlive()) {
            if (this.getDeltaMovement().length() < 0.1) {
                noMoveTime++;
            } else {
                noMoveTime = 0;
            }
            if (noMoveTime > 40 && mergeCooldown <= 0) {
                split(1200);
            }
        }
    }
    if (mergeCooldown > 0) {
        mergeCooldown--;
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    final ItemStack itemstack = player.getItemInHand(hand);
    if (isTameableFood(itemstack)) {
        if (!isTame()) {
            this.usePlayerItem(player, hand, itemstack);
            if (getRandom().nextInt(5) == 0) {
                this.tame(player);
                this.level().broadcastEntityEvent(this, (byte) 7);
            } else {
                this.level().broadcastEntityEvent(this, (byte) 6);
            }
            return InteractionResult.SUCCESS;
        }
        if (isTame() && (getAllFoods().test(itemstack) && !isFood(itemstack)) && this.getHealth() < this.getMaxHealth()) {
            this.usePlayerItem(player, hand, itemstack);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.CAT_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.heal(5);
            return InteractionResult.SUCCESS;
        }
    }

    final InteractionResult interactionresult = itemstack.interactLivingEntity(player, this, hand);
    final InteractionResult type = super.mobInteract(player, hand);
    if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS && isTame() && isOwnedBy(player) && !isFood(itemstack) && !isTameableFood(itemstack) && !getAllFoods().test(itemstack)) {
        if (!this.hasDart() && itemstack.getItem() == AMItemRegistry.ANCIENT_DART.get()) {
            this.setDart(true);
            this.usePlayerItem(player, hand, itemstack);
            return InteractionResult.CONSUME;
        }
        if (this.hasDart() && itemstack.is(Tags.Items.SHEARS)) {
            this.setDart(false);
            itemstack.hurtAndBreak(1, this, (p_233654_0_) -> {
            });
            return InteractionResult.SUCCESS;
        }
        if (player.isShiftKeyDown() && player.getPassengers().isEmpty()) {
            this.startRiding(player);
            rideCooldown = 20;
            return InteractionResult.SUCCESS;
        } else {
            this.setCommand(this.getCommand() + 1);
            if (this.getCommand() == 3) {
                this.setCommand(0);
            }
            player.displayClientMessage(Component.translatable("entity.alexsmobs.all.command_" + this.getCommand(), this.getName()), true);
            final boolean sit = this.getCommand() == 2;
            if (sit) {
                this.forcedSit = true;
                this.setOrderedToSit(true);
            } else {
                this.forcedSit = false;
                this.setOrderedToSit(false);
            }
            return InteractionResult.SUCCESS;
        }
    }
    return type;
}

public void tick() {
    super.tick();
    if(this.isInWater()){
        this.setMaxUpStep(1.2F);
    }else{
        this.setMaxUpStep(0.6F);
    }
    prevFlyProgress = flyProgress;

    final boolean flying = isFlying();

    if (flying) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (revengeCooldown > 0) {
        revengeCooldown--;
    }
    if (revengeCooldown == 0 && this.getLastHurtByMob() != null) {
        this.setLastHurtByMob(null);
    }
    if (!this.level().isClientSide) {
        if(fishingCooldown > 0){
            fishingCooldown--;
        }
        if(this.getAnimation() == NO_ANIMATION && this.getRandom().nextInt(700) == 0){
            this.setAnimation(ANIMATION_BEAKSHAKE);
        }

        if (flying) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        if (this.revengeCooldown > 0 && !this.isFlying()) {
            if (this.onGround() || this.isInWater()) {
                this.setFlying(false);
            }
        }

        if (isFlying()) {
            this.setNoGravity(true);
        } else {
            this.setNoGravity(false);
        }
    }
    if (!this.level().isClientSide && this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 9 && this.hasLineOfSight(this.getTarget())) {
        getTarget().knockback(0.3F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
        this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    if(targetKomodoDragon != null){
        this.komodo.lookAt(targetKomodoDragon, 360, 180);
        this.komodo.setJostling(true);
        float x = (float)(komodo.getX() - targetKomodoDragon.getX());
        float y = Math.abs((float)(komodo.getY() - targetKomodoDragon.getY()));
        float z = (float)(komodo.getZ() - targetKomodoDragon.getZ());
        double distXZ = Math.sqrt((x * x + z * z));
        if (distXZ < 1.8F) {
            this.komodo.getNavigation().stop();
            this.komodo.getMoveControl().strafe(-0.5F, 0);
        } else if(distXZ > 2.4F) {
            this.komodo.setJostling(false);
            this.komodo.getNavigation().moveTo(targetKomodoDragon, 1);
        }else{
            this.komodo.lookAt(targetKomodoDragon, 360, 180);
            float f = komodo.getRandom().nextFloat() - 0.5F;
            //perfect jostle condition
            if(komodo.jostleDirection){
                if(angle < 10){
                    angle += 1;
                }else{
                    komodo.jostleDirection = false;
                }
                this.komodo.getMoveControl().strafe(f * 1, -0.4F);
            }
            if(!komodo.jostleDirection){
                if(angle > -10){
                    angle -= 1;
                }else{
                    komodo.jostleDirection = true;
                }
                this.komodo.getMoveControl().strafe(f * 1, 0.4F);
            }
            if(this.komodo.getRandom().nextInt(15) == 0 && this.komodo.onGround()){
                komodo.pushBackJostling(targetKomodoDragon, 0.1F);
            }
            komodo.nextJostleAngleFromServer = angle;
            this.komodo.jostleTimer++;
            this.targetKomodoDragon.jostleTimer++;
            if(this.komodo.jostleTimer > 500 || y > 2.0F){
                komodo.hasImpulse = true;
                if(komodo.onGround()){
                    komodo.pushBackJostling(targetKomodoDragon, 0.4F);
                }
                if(targetKomodoDragon.onGround()){
                    targetKomodoDragon.pushBackJostling(komodo, 0.4F);
                }
                this.komodo.jostleTimer = 0;
                this.targetKomodoDragon.jostleTimer = 0;
                this.komodo.jostleCooldown = 700 + this.komodo.getRandom().nextInt(2000);
                this.targetKomodoDragon.jostleTimer = 0;
                this.targetKomodoDragon.jostleCooldown = 700 + this.targetKomodoDragon.getRandom().nextInt(2000);
                this.stop();
            }
        }
    }

}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float damage = SpellConfig.ShockingDamage.get().floatValue() * WandUtil.damageMultiply();
    if (caster instanceof SpriteMob spriteMob) {
        if (spriteMob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
            damage = (float) spriteMob.getAttributeValue(Attributes.ATTACK_DAMAGE);
        }
    }
    int range = spellStat.getRange();
    int burning = spellStat.getBurning();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        damage += WandUtil.getPotencyLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
    }
    ColorUtil colorUtil = new ColorUtil(0xb1abf1);
    if (staff.is(ModItems.NAMELESS_STAFF.get())) {
        colorUtil = new ColorUtil(0xa7fc3e);
    }
    damage += spellStat.getPotency();
    Vec3 vec3 = caster.getEyePosition();
    BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
    Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
    Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
    if (lightningRod.isPresent() && !this.rightStaff(staff)){
        BlockPos blockPos = lightningRod.get();
        ModNetwork.sendToALL(new SLightningPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 5));
        worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.ZAP.get(), this.getSoundSource(), 1.0F, 1.0F);
    } else {
        LivingEntity livingEntity = MobUtil.getLivingTarget(target);
        if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
            Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
            ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, colorUtil, 5));
            if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                float chance = rightStaff(staff) ? 0.25F : 0.05F;
                float chainDamage = damage / 2.0F;
                if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                    chance += 0.25F;
                    chainDamage = damage;
                }
                if (worldIn.random.nextFloat() <= chance){
                    livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                }
                if (burning > 0){
                    if (worldIn.random.nextFloat() < 0.05F){
                        livingEntity.setSecondsOnFire(5 * burning);
                    }
                }
                if (this.rightStaff(staff)){
                    WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage, true);
                }
            }
            this.playSound(worldIn, caster, ModSounds.ZAP.get());
        } else {
            BlockPos blockPos = rayTraceResult.getBlockPos();
            ModNetwork.sendToALL(new SLightningPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 5));
            this.playSound(worldIn, caster, ModSounds.ZAP.get());
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (rightStaff(staff)){
            i = 2 + caster.level.random.nextInt(2);
        } else if (specialStaffs(staff)){
            i = 2;
        }
        for (int i1 = 0; i1 < i; ++i1) {
            SlimeServant slimeServant = new SlimeServant(ModEntityType.SLIME_SERVANT.get(), worldIn);
            BlockPos blockPos = BlockFinder.SummonRadius(caster.blockPosition(), slimeServant, worldIn);
            if (caster.isUnderWater()){
                blockPos = BlockFinder.SummonWaterRadius(caster, worldIn);
            }
            if (specialStaffs(staff)) {
                if (typeStaff(staff, SpellType.ABYSS)) {
                    slimeServant = new TropicalSlimeServant(ModEntityType.TROPICAL_SLIME_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.NECROMANCY)) {
                    slimeServant = new CryptSlimeServant(ModEntityType.CRYPT_SLIME_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.NETHER)) {
                    slimeServant = new MagmaCubeServant(ModEntityType.MAGMA_CUBE_SERVANT.get(), worldIn);
                }
            } else {
                if (worldIn.isWaterAt(blockPos)) {
                    slimeServant = new TropicalSlimeServant(ModEntityType.TROPICAL_SLIME_SERVANT.get(), worldIn);
                } else if (worldIn.dimension() == Level.NETHER) {
                    slimeServant = new MagmaCubeServant(ModEntityType.MAGMA_CUBE_SERVANT.get(), worldIn);
                } else if (BlockFinder.findStructure(worldIn, blockPos, ModTags.Structures.CRYPT)) {
                    slimeServant = new CryptSlimeServant(ModEntityType.CRYPT_SLIME_SERVANT.get(), worldIn);
                }
            }
            slimeServant.setTrueOwner(caster);
            slimeServant.moveTo(blockPos, 0.0F, 0.0F);
            if (slimeServant.getType() != ModEntityType.TROPICAL_SLIME_SERVANT.get()){
                MobUtil.moveDownToGround(slimeServant);
            }
            slimeServant.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            slimeServant.setPersistenceRequired();
            slimeServant.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED,null,null);
            slimeServant.setSize(2, true);
            this.buffSummon(caster, slimeServant, potency);
            this.SummonSap(caster, slimeServant);
            this.setTarget(caster, slimeServant);
            if (worldIn.addFreshEntity(slimeServant)) {
                this.uponSummon(worldIn, caster, staff, slimeServant);
            }
            this.summonAdvancement(caster, slimeServant);
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.SUMMON_SPELL.get());
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);

    if(this.isTame()) {
        if(!itemstack.isEmpty()) {
            if(itemstack.getItem().isEdible()) {
                FoodProperties food = itemstack.getItem().getFoodProperties();

                if(this.entityData.get(EntityLammergeier.DATA_HEALTH_ID) < 20.0F) {
                    if(!player.isCreative()) {
                        itemstack.shrink(1);
                    }
                    for(int i = 0; i < 10; i++) {
                        this.level.addParticle(ParticleTypes.HAPPY_VILLAGER, getX() + (this.getRandom().nextFloat() - 0.5F), getY() + this.getRandom().nextFloat(), getZ() + (this.getRandom().nextFloat() - 0.5F), 0, 0, 0);
                    }
                    this.heal((float) food.getNutrition());
                    return InteractionResult.SUCCESS;
                }
            }
        }
        if(this.isOwnedBy(player) && !this.isVehicle() && !this.level.isClientSide && this.tickCount - this.lastTick > 13 && !itemstack.isEdible()) {
            if(!this.isInSittingPose() && !this.isOrderedToSit()) {
                this.setTarget(null);
                this.navigation.stop();
                this.readyToSit = true;
            } else {
                this.readyToSit = false;
                this.setInSittingPose(false);
                this.setOrderedToSit(false);
                this.navigation.stop();
            }
            this.lastTick = this.tickCount;
        }
    } else if(this.isTamingItem(itemstack.getItem()) && !this.isTame()) {
        if(!player.isCreative()) {
            itemstack.shrink(1);
        }

        if(!this.level.isClientSide) {
            if(!ModPlatformEvents.tame(this, player)) {
                this.tame(player);
                // this.setOwnerId(player.getUniqueID());
                this.navigation.stop();
                // ((LammerMoveHelper) this.getMoveHelper()).action = Action.WAIT;
                this.setTarget(null);
                this.setInSittingPose(true);
                this.setOrderedToSit(true);
                this.setHealth(20.0F);
                this.level.broadcastEntityEvent(this, (byte) 7);
            } else {
                this.level.broadcastEntityEvent(this, (byte) 6);
            }
        }

        return InteractionResult.SUCCESS;
    }

    return super.mobInteract(player, hand);
}

public void tick() {
    if (this.moveTarget != null) {
        if (this.moveTarget.isValid()) {
            float accessDistance = 2.2f;

            //when approaching a chest, open it visually
            double distance = this.entity.position().distanceTo(Math3DUtil.center(this.moveTarget.getBlockPos()));

            //briefly before reaching the target, open chest, if it is one.
            if (distance < 2.5 && distance >= accessDistance && this.canSeeTarget() &&
                    this.moveTarget.isChest()) {
                this.toggleChest(this.moveTarget, true);
            }

            if (distance < accessDistance) {
                //stop moving while taking out
                this.entity.getNavigation().stop();
            } else {
                //continue moving
                BlockPos moveTarget = this.getMoveTarget();
                this.entity.getNavigation().moveTo(this.entity.getNavigation().createPath(moveTarget, 0), 1.0f);
            }

            //when close enough insert item
            if (distance < accessDistance && this.canSeeTarget()) {

                var handler = this.moveTarget.getItemHandler(this.entity.getDepositFacing());
                if (handler == null) { //worst case scenario if block entity or entity changes since last target reset.
                    this.resetTarget();
                    return;
                }
                ItemStack duplicate = this.entity.getItemInHand(InteractionHand.MAIN_HAND).copy();

                //simulate insertion
                ItemStack leftOverSimulated = ItemTransferUtil.insertItem(handler, duplicate, true);
                //if anything was inserted go for real
                if (leftOverSimulated.getCount() != duplicate.getCount()) {
                    ItemStack leftover = ItemTransferUtil.insertItem(handler, duplicate, false);
                    //if we inserted everything
                    this.entity.setItemInHand(InteractionHand.MAIN_HAND, leftover);
                    if (leftover.isEmpty()) {
                        this.moveTarget = null;
                        this.stop();
                    } else {
                        //pause ai to retry again in a little while.
                        this.pause(2000);
                    }
                }

                //after inserting, close chest
                if (this.moveTarget != null && this.moveTarget.isChest()) {
                    this.toggleChest(this.moveTarget, false);
                }
            }
        } else {
            this.resetTarget(); //if there is no block entity, recheck
        }
    }
}

private void doTick(Level level, BlockPos pos, BlockState blockState) {
	if (!(blockState.getBlock() instanceof HenostonePitfallBlock)) return;

	AABB detectionAABB = new AABB(pos.getX(), pos.getY() + 0.9, pos.getZ(), pos.getX() + 1, pos.getY() + 2.0, pos.getZ() + 1);

	switch (state) {

	case IDLE -> {
		if (!blockState.getValue(HenostonePitfallBlock.OPEN)) {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			if (!entities.isEmpty()) {
				transitionTo(TrapState.WARNING_1);
				playWarningSound(level, pos);
			}
		}
	}

	case WARNING_1 -> {
		timer++;
		if (timer >= WARNING_1_DURATION) {
			transitionTo(TrapState.WARNING_2);
			playWarningSound(level, pos);
		}
	}

	case WARNING_2 -> {
		timer++;
		if (timer >= WARNING_2_DURATION) {
			transitionTo(TrapState.WARNING_3);
			playWarningSound(level, pos);
		}
	}

	case WARNING_3 -> {
		timer++;
		if (timer == WARNING_3_BEEP_B) playWarningSound(level, pos);
		if (timer == WARNING_3_BEEP_C) playWarningSound(level, pos);
		if (timer >= WARNING_3_DURATION) {
			setOpen(level, pos, blockState, true);
			transitionTo(TrapState.OPEN);
		}
	}

	case OPEN -> {
		timer++;
		if (timer >= OPEN_HOLD_TICKS) {
			setOpen(level, pos, level.getBlockState(pos), false);
			transitionTo(TrapState.COOLDOWN);
		}
	}

	case COOLDOWN -> {
		timer++;
		if (timer >= COOLDOWN_DURATION) {
			transitionTo(TrapState.IDLE);
		}
	}
	}
}

public void bounceFromDirection(Direction hitDirection) {
    boolean flag = false;
    if(this.getBounces() > this.getMaximumBounces() - 1 && this.isExplosive()) {
        this.setDeltaMovement(Vec3.ZERO);
        this.setBounces(this.getMaximumBounces());
        return;
    }else if(targetsOnBounce()){
        Entity shooter = this.getOwner();
        Vec3 position = this.getEyePosition();
        Entity nearestBounceTarget = null;
        for (LivingEntity entity : level().getEntitiesOfClass(LivingEntity.class, new AABB(position.add(-10, -10, -10), position.add(10, 10, 10)))) {
            if((shooter == null || !entity.is(shooter) && !entity.isAlliedTo(shooter)) && !hitEntityIds.contains(entity.getId())){
                if(nearestBounceTarget == null || entity.distanceTo(this) < nearestBounceTarget.distanceTo(this)){
                    nearestBounceTarget = entity;
                }
            }
        }
        if(nearestBounceTarget != null){
            flag = true;
            if(!level().isClientSide){
                this.setBounces(this.getBounces() + 1);
            }
            if(this.getBounces() > this.getMaximumBounces()){
                this.discard();
            }else{
                Vec3 vec3 = nearestBounceTarget.getEyePosition().subtract(this.position()).normalize().scale(0.8F);
                this.setDeltaMovement(vec3.x, vec3.y, vec3.z);
            }
        }
    }
    if(bounceSoundCooldown == 0){
        bounceSoundCooldown = 5;
        this.playSound(ACSoundRegistry.GUMBALL_BOUNCE.get());
    }
    if(!flag){
        Vec3 deltaMovement = this.getDeltaMovement();
        double x = deltaMovement.x();
        double y = deltaMovement.y();
        double z = deltaMovement.z();
        switch (hitDirection.getAxis()) {
            case X:
                x = -x * 0.8F;
                break;
            case Y:
                y = -y * 0.5F;
                break;
            case Z:
                z = -z * 0.8F;
                break;
        }
        if(!level().isClientSide){
            this.setBounces(this.getBounces() + 1);
        }
        if(this.getBounces() > this.getMaximumBounces()){
            this.discard();
        }else{
            this.setDeltaMovement(x, y, z);
        }
    }
}

private void updateEyes() {
    float leftPitchDist = Math.abs(this.getEyePitch(true) - targetLeftPitch);
    float rightPitchDist = Math.abs(this.getEyePitch(false) - targetRightPitch);
    float leftYawDist = Math.abs(this.getEyeYaw(true) - targetLeftYaw);
    float rightYawDist = Math.abs(this.getEyeYaw(false) - targetRightYaw);
    if (rightLookCooldown == 0 && this.random.nextInt(20) == 0 && rightPitchDist < 0.5F && rightYawDist < 0.5F) {
        targetRightPitch = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
        targetRightYaw = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
        rightLookCooldown = 3 + random.nextInt(15);
    }
    if (leftLookCooldown == 0 && this.random.nextInt(20) == 0 && leftPitchDist < 0.5F && leftYawDist < 0.5F) {
        targetLeftPitch = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
        targetLeftYaw = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
        leftLookCooldown = 3 + random.nextInt(15);
    }

    if (leftPitchDist > 0.5F) {
        if (this.getEyePitch(true) < this.targetLeftPitch) {
            this.setEyePitch(true, this.getEyePitch(true) + Math.min(leftPitchDist, 4F));
        }
        if (this.getEyePitch(true) > this.targetLeftPitch) {
            this.setEyePitch(true, this.getEyePitch(true) - Math.min(leftPitchDist, 4F));
        }
    }

    if (rightPitchDist > 0.5F) {
        if (this.getEyePitch(false) < this.targetRightPitch) {
            this.setEyePitch(false, this.getEyePitch(false) + Math.min(rightPitchDist, 4F));
        }
        if (this.getEyePitch(false) > this.targetRightPitch) {
            this.setEyePitch(false, this.getEyePitch(false) - Math.min(rightPitchDist, 4F));
        }
    }

    if (leftYawDist > 0.5F) {
        if (this.getEyeYaw(true) < this.targetLeftYaw) {
            this.setEyeYaw(true, this.getEyeYaw(true) + Math.min(leftYawDist, 4F));
        }
        if (this.getEyeYaw(true) > this.targetLeftYaw) {
            this.setEyeYaw(true, this.getEyeYaw(true) - Math.min(leftYawDist, 4F));
        }
    }

    if (rightYawDist > 0.5F) {
        if (this.getEyeYaw(false) < this.targetRightYaw) {
            this.setEyeYaw(false, this.getEyeYaw(false) + Math.min(rightYawDist, 4F));
        }
        if (this.getEyeYaw(false) > this.targetRightYaw) {
            this.setEyeYaw(false, this.getEyeYaw(false) - Math.min(rightYawDist, 4F));
        }
    }

    if (rightLookCooldown > 0) {
        rightLookCooldown--;
    }

    if (leftLookCooldown > 0) {
        leftLookCooldown--;
    }
}

public void tick() {
    if (dashCooldown > 0) {
        dashCooldown--;
    }
    if (EntityWarpedMosco.this.getTarget() != null) {
        LivingEntity target = EntityWarpedMosco.this.getTarget();
        ranged = EntityWarpedMosco.this.shouldRangeAttack(target);
        if (EntityWarpedMosco.this.isFlying() || ranged || EntityWarpedMosco.this.distanceTo(target) > 12 && !EntityWarpedMosco.this.isTargetBlocked(target.position().add(0, target.getBbHeight() * 0.6F, 0))) {
            float speedRush = 5F;
            upTicks++;
            EntityWarpedMosco.this.setFlying(true);
            if (ranged) {
                if (farTarget == null || EntityWarpedMosco.this.distanceToSqr(Vec3.atCenterOf(farTarget)) < 9) {
                    farTarget = this.getAvoidTarget(target);
                }
                if (farTarget != null) {
                    EntityWarpedMosco.this.getMoveControl().setWantedPosition(farTarget.getX(), farTarget.getY() + target.getEyeHeight() * 0.6F, farTarget.getZ(), 3D);
                }
                EntityWarpedMosco.this.setAnimation(ANIMATION_SPIT);
                if(upTicks % 30 == 0){
                    EntityWarpedMosco.this.heal(1);
                }
                final int tick = EntityWarpedMosco.this.getAnimationTick();
                switch (tick) {
                    case 10, 20, 30, 40 -> EntityWarpedMosco.this.spit(target);
                }
            } else {
                if (upTicks > 20 || EntityWarpedMosco.this.distanceTo(target) < 6) {
                    EntityWarpedMosco.this.getMoveControl().setWantedPosition(target.getX(), target.getY() + target.getEyeHeight() * 0.6F, target.getZ(), speedRush);
                } else {
                    EntityWarpedMosco.this.getMoveControl().setWantedPosition(EntityWarpedMosco.this.getX(), EntityWarpedMosco.this.getY() + 3, EntityWarpedMosco.this.getZ(), 0.5F);
                }
            }
        } else {
            EntityWarpedMosco.this.getNavigation().moveTo(EntityWarpedMosco.this.getTarget(), 1.25F);
        }
        if (EntityWarpedMosco.this.isFlying()) {
            if (EntityWarpedMosco.this.distanceTo(target) < 4.3F) {
                if (dashCooldown == 0 || target.onGround() || target.isInLava() || target.isInWater()) {
                    target.hurt(EntityWarpedMosco.this.damageSources().mobAttack(EntityWarpedMosco.this), 5F);
                    EntityWarpedMosco.this.knockbackRidiculous(target, 1.0F);
                    dashCooldown = 30;
                }
                final float groundHeight = EntityWarpedMosco.this.getMoscoGround(EntityWarpedMosco.this.blockPosition()).getY();
                if (Math.abs(EntityWarpedMosco.this.getY() - groundHeight) < 3.0F && !EntityWarpedMosco.this.isOverLiquid()) {
                    EntityWarpedMosco.this.timeFlying += 300;
                    EntityWarpedMosco.this.setFlying(false);
                }
            }
        } else {
            if (EntityWarpedMosco.this.distanceTo(target) < 4F && EntityWarpedMosco.this.getAnimation() == NO_ANIMATION) {
                Animation animation = getRandomAttack(random);
                if (animation == ANIMATION_SUCK && target.isPassenger()) {
                    animation = ANIMATION_SLAM;
                }
                EntityWarpedMosco.this.setAnimation(animation);
            }
        }
    }
}

public void tick() {
    if(targetMoose != null){
        this.moose.lookAt(targetMoose, 360, 180);
        this.moose.setJostling(true);
        float f = (float)(moose.getX() - targetMoose.getX());
        float f1 = Math.abs((float)(moose.getY() - targetMoose.getY()));
        float f2 = (float)(moose.getZ() - targetMoose.getZ());
        double distXZ = Math.sqrt((f * f + f2 * f2));
        if (distXZ < 4F) {
            this.moose.getNavigation().stop();
            this.moose.getMoveControl().strafe(-0.5F, 0);
        } else if(distXZ > 4.5F) {
            this.moose.setJostling(false);
            this.moose.getNavigation().moveTo(targetMoose, 1);
        }else{
            this.moose.lookAt(targetMoose, 360, 180);
            //perfect jostle condition
            if(moose.jostleDirection){
                if(angle < 30){
                    angle++;
                }
                this.moose.getMoveControl().strafe(0, -0.2F);
            }
            if(!moose.jostleDirection){
                if(angle > -30){
                    angle--;
                }
                this.moose.getMoveControl().strafe(0, 0.2F);
            }
            if(this.moose.getRandom().nextInt(55) == 0 && this.moose.onGround()){
                moose.pushBackJostling(targetMoose, 0.2F);
            }
            if(this.moose.getRandom().nextInt(25) == 0 && this.moose.onGround()) {
                moose.playJostleSound();
            }
            moose.setJostleAngle(angle);
            if(this.moose.jostleTimer % 60 == 0 || this.moose.getRandom().nextInt(80) == 0){
                this.setJostleDirection(!moose.jostleDirection);
            }
            this.moose.jostleTimer++;
            this.targetMoose.jostleTimer++;
            if(this.moose.jostleTimer > 1000 || f1 > 2.0F){
                moose.hasImpulse = true;
                if(moose.onGround()){
                    moose.pushBackJostling(targetMoose, 0.9F);
                }
                if(targetMoose.onGround()){
                    targetMoose.pushBackJostling(moose, 0.9F);
                }
                this.moose.jostleTimer = 0;
                this.targetMoose.jostleTimer = 0;
                this.moose.jostleCooldown = 500 + this.moose.getRandom().nextInt(2000);
                this.targetMoose.jostleTimer = 0;
                this.targetMoose.jostleCooldown = 500 + this.targetMoose.getRandom().nextInt(2000);
                this.stop();
            }
        }
    }

}

protected void fireProjectiles(ItemStack itemStack, Level world, LivingEntity entity) {
    if (entity instanceof Player player && !world.isClientSide) {
        ItemStack advancementCopy = itemStack.copy();

        List<ItemStack> list = takeProjectiles(itemStack, 1);
        if (!list.isEmpty()) {
            int multishotEnchantLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.MULTISHOT, itemStack) * 3;
            int count = Math.max(getEffectLevel(itemStack, ItemEffect.multishot) + multishotEnchantLevel, 1);
            double strength = getAttributeValue(itemStack, TetraAttributes.drawStrength.get());
            float velocityBonus = getEffectLevel(itemStack, ItemEffect.velocity) / 100f;
            float projectileVelocity = getProjectileVelocity(strength, velocityBonus);
            double spread = getEffectEfficiency(itemStack, ItemEffect.multishot);

            if (spread == 0 && multishotEnchantLevel > 0) {
                spread = multishotDefaultSpread;
            }

            ModularLooseProjectilesEvent looseProjectilesEvent = new ModularLooseProjectilesEvent(itemStack, list.get(0), player, world, 1,
                    strength,
                    false,
                    projectileVelocity,
                    spread,
                    1,
                    player.getAbilities().instabuild,
                    count,
                    player.getXRot(),
                    player.getYRot());
            MinecraftForge.EVENT_BUS.post(looseProjectilesEvent);

            count = looseProjectilesEvent.getCount();
            spread = looseProjectilesEvent.getMultishotSpread();
            for (int i = 0; i < count; i++) {
                double yaw = looseProjectilesEvent.getBaseYaw() - spread * (count - 1) / 2f + spread * i;
                boolean isDupe = looseProjectilesEvent.isInfiniteAmmo() || count > 1 && i != count / 2;
                fireProjectile(world, looseProjectilesEvent.getFiringStack(),
                        looseProjectilesEvent.getAmmoStack(),
                        looseProjectilesEvent.getProjectileRemappers(),
                        player,
                        looseProjectilesEvent.getStrength(),
                        looseProjectilesEvent.getProjectileVelocity(),
                        (float) looseProjectilesEvent.getBasePitch(),
                        (float) yaw,
                        isDupe);
            }

            // todo: needs to apply 3 points of damage if it's firework
            itemStack.hurtAndBreak(1, player, p -> p.broadcastBreakEvent(p.getUsedItemHand()));
            applyUsageEffects(entity, itemStack, 1);

            world.playSound(null, player.getX(), player.getY(), player.getZ(),
                    SoundEvents.CROSSBOW_SHOOT, SoundSource.PLAYERS, 1, 1);

            if (player instanceof ServerPlayer) {
                CriteriaTriggers.SHOT_CROSSBOW.trigger((ServerPlayer) player, advancementCopy);

                player.awardStat(Stats.ITEM_USED.get(this));
            }
        }
    }
}

public void aiStep() {
	super.aiStep();

	int tpInvisibility = this.getTeleportInvisibility();
	if (tpInvisibility > 0) {
		if (this.getTarget() != null) {
			this.getLookControl().setLookAt(this.getTarget());
			this.getLookControl().tick();
		}
		this.setTeleportInvisibility(tpInvisibility - 1);
		if (tpInvisibility - 1 <= 0) {
			this.lichTeleportParticles(true);
			this.playSound(TFSounds.LICH_TELEPORT.get(), 1.125F, 1.125F);
		}
		return;
	}

	if (this.isDeadOrDying()) return;

	if (this.getPhase() == 3) {
		this.level().addParticle(TFParticleType.ANGRY_LICH.get(),
			this.getRandomX(0.65f),
			this.getEyeY() + 0.25D + this.getRandom().nextFloat() * 0.5D,
			this.getRandomZ(0.65f),
			this.getRandom().nextGaussian() * 0.02D, this.getRandom().nextGaussian() * 0.02D, this.getRandom().nextGaussian() * 0.02D);
		return;
	}

	// determine the hand position
	float angle = ((this.yBodyRot * Mth.PI) / 180F);

	double dx = this.getX() + (Mth.cos(angle) * 0.65);
	double dy = this.getY() + (this.getBbHeight() * 0.94);
	double dz = this.getZ() + (Mth.sin(angle) * 0.65);

	// add particles!

	// how many particles do we want to add?!
	int factor = (80 - this.getAttackCooldown()) / 10;
	int particles = factor > 0 ? this.getRandom().nextInt(factor) : 1;


	for (int j1 = 0; j1 < particles; j1++) {
		float sparkle = 1.0F - (this.getAttackCooldown() + 1.0F) / 60.0F;
		sparkle *= sparkle;

		float red = 0.37F * sparkle;
		float grn = 0.99F * sparkle;
		float blu = 0.89F * sparkle;

		// change color for fireball
		if (this.getNextAttackType() != 0) {
			red = 0.99F * sparkle;
			grn = 0.47F * sparkle;
			blu = 0.00F * sparkle;
		}

		this.level().addParticle(ColorParticleOption.create(TFParticleType.MAGIC_EFFECT.get(), red, grn, blu), dx + (this.getRandom().nextGaussian() * 0.025), dy + (this.getRandom().nextGaussian() * 0.025), dz + (this.getRandom().nextGaussian() * 0.025), 0.0F, 0.0F, 0.0F);
	}
}

public InteractionResult useOn(UseOnContext context) {
	Player player = context.getPlayer();
	Level world = context.getLevel();
	ItemStack stack = context.getItemInHand();

	if (world.isClientSide)
		return InteractionResult.SUCCESS;

	if (world.getBlockState(context.getClickedPos()).hasBlockEntity()) {
		if (world.getBlockEntity(context.getClickedPos()) instanceof ChestBlockEntity && player.isCrouching()) {
			ChestBlockEntity chest = (ChestBlockEntity) world.getBlockEntity(context.getClickedPos());
			Direction dir = context.getClickedFace();

			if (dir == Direction.UP) {
				chest.setLootTable(this.lootList.get(stack.getDamageValue()), this.lootRandomizer.nextLong());
				chest.unpackLootTable(player);
			} else if (dir == Direction.DOWN && !SuperpositionHandler.hasSpellstoneCooldown(player)) {

				SuperpositionHandler.setSpellstoneCooldown(player, 40);
				HashMap<Item, Integer> lootMap = new HashMap<Item, Integer>();

				for (int counter = 0; counter < 32768; counter++) {
					chest.setLootTable(this.lootList.get(stack.getDamageValue()), this.lootRandomizer.nextLong());
					chest.unpackLootTable(player);

					for (int slot = 0; slot < chest.getContainerSize(); slot++) {
						ItemStack generatedStack = chest.getItem(slot);
						Item generatedItem = generatedStack.getItem();
						int amount = generatedStack.getCount();

						if (!generatedStack.isEmpty()) {

							if (lootMap.containsKey(generatedItem)) {
								lootMap.put(generatedItem, lootMap.get(generatedItem) + amount);
							} else {
								lootMap.put(generatedItem, amount);
							}

						}
					}

					chest.clearContent();
				}

				EnigmaticLegacy.LOGGER.info("Estimated generation complete in 32768 instances, results:");
				for (Item theItem : lootMap.keySet()) {
					EnigmaticLegacy.LOGGER.info("Item: " + theItem.getName(new ItemStack(theItem)).getString() + ", Amount: " + lootMap.get(theItem));
				}

				player.sendSystemMessage(Component.translatable("message.enigmaticlegacy.gen_sim_complete").withStyle(ChatFormatting.DARK_PURPLE));

			} else {
				chest.clearContent();
			}

			return InteractionResult.SUCCESS;
		}
	}

	return InteractionResult.PASS;
}

public void tick() {
    if(partner != null){
        if(center == null || mudskipper.getRandom().nextInt(100) == 0){
            center = new Vec3((mudskipper.getX() + partner.getX()) / 2F, (mudskipper.getY() + partner.getY()) / 2F, (mudskipper.getZ() + partner.getZ()) / 2F);
        }
        this.mudskipper.setDisplaying(true);
        float x = (float)(mudskipper.getX() - partner.getX());
        float y = Math.abs((float)(mudskipper.getY() - partner.getY()));
        float z = (float)(mudskipper.getZ() - partner.getZ());
        double distXZ = Math.sqrt((x * x + z * z));

        if (distXZ > 3F) {
            mudskipper.getNavigation().moveTo(partner, 1F);
        }else{
            float speed = mudskipper.getRandom().nextFloat() * 0.5F + 0.8F;
            if(mudskipper.displayDirection){
                if(angle < 180){
                    angle += 10;
                }else{
                    mudskipper.displayDirection = false;
                }
            }
            if(!mudskipper.displayDirection){
                if(angle > -180){
                    angle -= 10;
                }else{
                    mudskipper.displayDirection = true;
                }
            }
            if(distXZ < 0.8F){
                if(this.mudskipper.onGround() && this.partner.onGround()){
                    this.mudskipper.lookAt(this.partner, 360, 360);
                    this.setDisplayDirection(!mudskipper.displayDirection);
                    this.mudskipper.openMouth(10 + this.mudskipper.getRandom().nextInt(20));
                    this.partner.setDeltaMovement(partner.getDeltaMovement().add(0.2F * mudskipper.getRandom().nextFloat(), 0.35F, 0.2F * mudskipper.getRandom().nextFloat()));
                }
            }
            Vec3 circle = getCirclingPosOf(center, 1.5F + mudskipper.getRandom().nextFloat());
            Vec3 dirVec = circle.subtract(mudskipper.position());
            float headAngle = -(float) (Mth.atan2(dirVec.x, dirVec.z) * (double) Mth.RAD_TO_DEG);
            this.mudskipper.getNavigation().moveTo(circle.x, circle.y, circle.z, speed);
            mudskipper.setYRot(headAngle);
            mudskipper.yHeadRot = headAngle;
            mudskipper.yBodyRot = headAngle;
            mudskipper.nextDisplayAngleFromServer = angle;
            this.mudskipper.displayTimer++;
            this.partner.displayTimer++;
            if(this.mudskipper.displayTimer > 400 || y > 2.0F){
                this.mudskipper.getNavigation().stop();
                this.partner.getNavigation().stop();
                mudskipper.hasImpulse = true;
                this.mudskipper.displayTimer = 0;
                this.partner.displayTimer = 0;
                this.mudskipper.displayCooldown = 200 + this.mudskipper.getRandom().nextInt(200);
                this.partner.displayTimer = 0;
                this.partner.displayCooldown = 200 + this.partner.getRandom().nextInt(200);
                this.stop();
            }
        }
    }
}

public void tick() {
    LivingEntity livingentity = this.entity.getTarget();
    if(animationCooldown > 0){
        animationCooldown--;
    }
    if (livingentity != null) {
        double d0 = this.entity.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
        boolean flag = this.entity.hasLineOfSight(livingentity);
        boolean flag1 = this.seeTime > 0;
        if (flag != flag1) {
            this.seeTime = 0;
        }

        if (flag) {
            ++this.seeTime;
        } else {
            --this.seeTime;
        }

        if (!(d0 > (double)this.maxAttackDistance) && this.seeTime >= 20) {
            this.entity.getNavigation().stop();
            ++this.strafingTime;
        } else {
            this.entity.getNavigation().moveTo(livingentity, this.moveSpeedAmp);
            this.strafingTime = -1;
        }

        if (this.strafingTime >= 20) {
            if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                this.strafingClockwise = !this.strafingClockwise;
            }

            if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                this.strafingBackwards = !this.strafingBackwards;
            }

            this.strafingTime = 0;
        }

        if (this.strafingTime > -1) {
            if (d0 > (double)(this.maxAttackDistance * 0.75F)) {
                this.strafingBackwards = false;
            } else if (d0 < (double)(this.maxAttackDistance * 0.25F)) {
                this.strafingBackwards = true;
            }

            this.entity.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
            this.entity.lookAt(livingentity, 30.0F, 30.0F);
        } else {
            this.entity.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
        }
        if (!flag && this.seeTime < -60) {
            this.entity.stopUsingItem();
        } else if (flag) {
            if(entity.getAnimation() != EntityStraddler.ANIMATION_LAUNCH){
                entity.setAnimation(EntityStraddler.ANIMATION_LAUNCH);
                this.attackTime = this.attackCooldown;
            }
        }
    }
}

public boolean continueExecuting()
{
	EntityLivingBase entitylivingbase = this.taskOwner.getAttackTarget();

	if (entitylivingbase == null)
	{
		entitylivingbase = this.target;
	}

	if (entitylivingbase == null)
	{
		return false;
	}
	else if (!entitylivingbase.isEntityAlive())
	{
		return false;
	}
	else
	{
		Team team = this.taskOwner.getTeam();
		Team team1 = entitylivingbase.getTeam();

		if (team != null && team1 == team)
		{
			return false;
		}
		else
		{
			double d0 = this.getTargetDistance();

			if (this.taskOwner.getDistanceSq(entitylivingbase) > d0 * d0)
			{
				return false;
			}
			else
			{
				if (this.shouldCheckSight)
				{
					if (this.taskOwner.getEntitySenses().canSee(entitylivingbase))
					{
						this.targetUnseenTicks = 0;
					}
					else if (++this.targetUnseenTicks > this.unseenMemoryTicks)
					{
						return false;
					}
				}

				if (entitylivingbase instanceof EntityPlayer && ((EntityPlayer)entitylivingbase).capabilities.disableDamage)
				{
					return false;
				}
				else
				{
					this.taskOwner.setAttackTarget(entitylivingbase);
					return true;
				}
			}
		}
	}
}

public void update() {
    super.update();
    if (!this.world.isRemote) {

    	boolean sync = false;
        if (this.waterLevel < 2 && this.slots.get(2).getItem() == Items.WATER_BUCKET) {
            if (this.slots.get(3).getCount() < 16) {
                this.slots.get(2).shrink(1);

                this.waterLevel++;

                ItemStack stack = this.slots.get(3);
                if (stack.getItem() == Items.BUCKET) {
                    stack.grow(1);
                } else {
                    this.slots.set(3, new ItemStack(Items.BUCKET));
                }

                sync = true;
            }
        }

        ItemStack stack = this.slots.get(1);
        if (!stack.isEmpty()) {
            if ((this.proximates < MAX_NUTRIENTS) || (this.minerals < MAX_NUTRIENTS) || (this.vitamins < MAX_NUTRIENTS) || (this.lipids < MAX_NUTRIENTS)) {
                this.consumeNutrients();
                sync = true;

            }
        }

        boolean active = this.isProcessing(0);
        boolean syncActive = false;
        if(active != prevActiveState) {
        	prevActiveState = active;
        	syncActive = true;


        }
        if (sync) {
            this.markDirty();
        }
        if(syncActive || sync)
        	RebornMod.NETWORK_WRAPPER.sendToAllTracking(new TileEntityFieldsMessage(getSyncFields(NonNullList.create()), this), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 5));

        if(syncActive) {

        	for (EntityPlayer entityplayer : this.world.getEntitiesWithinAABB(EntityPlayer.class, new AxisAlignedBB((double)((float)this.pos.getX() - 5.0F), (double)((float)this.pos.getY() - 5.0F), (double)((float)this.pos.getZ() - 5.0F), (double)((float)(this.pos.getX() + 1) + 5.0F), (double)((float)(this.pos.getY() + 1) + 5.0F), (double)((float)(this.pos.getZ() + 1) + 5.0F))))
            {
                if (entityplayer.openContainer instanceof CultivateContainer)
                {
                    if(this.isProcessing(0)) {
