public void onPlayerStoppedUsing(ItemStack stack, World worldIn, LivingEntity entityLiving, int timeLeft) {
  if (!(entityLiving instanceof PlayerEntity)) return;
  PlayerEntity playerentity = (PlayerEntity)entityLiving;
  boolean dontNeedAmmo = playerentity.abilities.isCreativeMode || EnchantmentHelper.getEnchantmentLevel(Enchantments.INFINITY, stack) > 0;
  ItemStack ammo = playerentity.findAmmo(stack);

  int pullDurationTicks = this.getUseDuration(stack) - timeLeft;
  pullDurationTicks = net.minecraftforge.event.ForgeEventFactory.onArrowLoose(stack, worldIn, playerentity,
          pullDurationTicks, !ammo.isEmpty() || dontNeedAmmo);
  if (pullDurationTicks < 0) return;
  if (ammo.isEmpty() && !dontNeedAmmo) return;
  if (ammo.isEmpty()) {
    ammo = new ItemStack(Items.ARROW);
  }

  float arrowVelocity = getArrowVelocity(pullDurationTicks);
  if (arrowVelocity < 0.1) return;
  boolean infiniteAmmo = playerentity.abilities.isCreativeMode || (ammo.getItem() instanceof ArrowItem && ((ArrowItem)ammo.getItem()).isInfinite(ammo, stack, playerentity));

  if (!worldIn.isRemote) {
    ArrowItem arrowitem = (ArrowItem)(ammo.getItem() instanceof ArrowItem ? ammo.getItem() : Items.ARROW);
    AbstractArrowEntity abstractArrowEntity = arrowitem.createArrow(worldIn, ammo, playerentity);
    abstractArrowEntity = customArrow(abstractArrowEntity);
    abstractArrowEntity.func_234612_a_(playerentity, playerentity.rotationPitch, playerentity.rotationYaw, 0.0F, arrowVelocity * 3.0F, 1.0F); // shoot
    if (arrowVelocity == 1.0F) {
      abstractArrowEntity.setIsCritical(true);
    }

    abstractArrowEntity.setDamage(0.0);
    abstractArrowEntity.setKnockbackStrength(0);

    if (infiniteAmmo || playerentity.abilities.isCreativeMode && (ammo.getItem() == Items.SPECTRAL_ARROW || ammo.getItem() == Items.TIPPED_ARROW)) {
      abstractArrowEntity.pickupStatus = AbstractArrowEntity.PickupStatus.CREATIVE_ONLY;
    }

    // --------- our capability code is this part -----------

    // set the level of fire based on how long the bow has been charging up (how long the player has been pulling it)
    final float MAX_CHARGEUP_TIME = 4;
    final float MAX_CHARGE = 100;
    float pullDurationSeconds = getPullDurationSeconds(stack, worldIn, entityLiving);
    if (pullDurationSeconds > MAX_CHARGEUP_TIME) pullDurationSeconds = MAX_CHARGEUP_TIME;
    int fireCharge = (int)(MAX_CHARGE*pullDurationSeconds);
    setElementalFireLevel(abstractArrowEntity, fireCharge);

    worldIn.addEntity(abstractArrowEntity);
  }

  worldIn.playSound((PlayerEntity)null,
          playerentity.getPosX(), playerentity.getPosY(), playerentity.getPosZ(),
          SoundEvents.ENTITY_ARROW_SHOOT, SoundCategory.PLAYERS,
          1.0F, 1.0F / (random.nextFloat() * 0.4F + 1.2F) + arrowVelocity * 0.5F);
  if (!infiniteAmmo && !playerentity.abilities.isCreativeMode) {
    ammo.shrink(1);
    if (ammo.isEmpty()) {
      playerentity.inventory.deleteStack(ammo);
    }
  }

  playerentity.addStat(Stats.ITEM_USED.get(this));
}

public static void onPlayerTick(PlayerTickEvent.Pre event) {
    if (event.getEntity() == Minecraft.getInstance().player) {
        var level = Minecraft.getInstance().level;

        ClientMagicData.getRecasts().tickRecasts();
        ClientMagicData.getCooldowns().tick(1);
        if (ClientMagicData.getCastDuration() > 0) {
            ClientMagicData.handleCastDuration();
        }

        if (level != null) {
            List<Entity> spellcasters = level.getEntities((Entity) null, event.getEntity().getBoundingBox().inflate(64), (mob) -> mob instanceof Player || mob instanceof IMagicEntity);
            spellcasters.forEach((entity) -> {
                LivingEntity livingEntity = (LivingEntity) entity;
                var spellData = ClientMagicData.getSyncedSpellData(livingEntity);
                /*
                Status Effect Visuals
                 */
                if (livingEntity.isAutoSpinAttack() && spellData.getSpinAttackType().equals(SpinAttackType.FIRE)) {
                    BurningDashSpell.ambientParticles(level, livingEntity);
                }
                /*
                Current Casting Spell Visuals
                 */
                //TODO: what is this, shouldnt there be an onClientCastTick?
                if (spellData.isCasting()) {
                    if (spellData.getCastingSpellId().equals(SpellRegistry.RAY_OF_SIPHONING_SPELL.get().getSpellId())) {
                        HitResult hit;
                        if (entity instanceof Mob mob && MagicData.getPlayerMagicData(mob).getAdditionalCastData() instanceof CastingMobAimingData aimingData) {
                            hit = RaycastBuilder.begin(entity.level, entity)
                                    .start(entity.getEyePosition())
                                    .end(entity.getEyePosition().add(aimingData.getForward(entity).scale(RayOfSiphoningSpell.getRange(0))))
                                    .checkForBlocks(true)
                                    .build();
                        } else {
                            hit = RaycastBuilder.begin(entity.level, entity)
                                    .range(RayOfSiphoningSpell.getRange(0))
                                    .checkForBlocks(true)
                                    .build();

                        }
                        Vec3 impact = hit.getLocation().subtract(0, .25, 0);
                        for (int i = 0; i < 8; i++) {
                            Vec3 motion = new Vec3(
                                    Utils.getRandomScaled(.2f),
                                    Utils.getRandomScaled(.2f),
                                    Utils.getRandomScaled(.2f)
                            );
                            entity.level.addParticle(ParticleHelper.SIPHON, impact.x + motion.x, impact.y + motion.y, impact.z + motion.z, motion.x, motion.y, motion.z);
                        }
                    } else if (spellData.getCastingSpellId().equals(SpellRegistry.RECALL_SPELL.get().getSpellId())) {
                        RecallSpell.ambientParticles(livingEntity, spellData);
                    } else if (spellData.getCastingSpellId().equals(SpellRegistry.RAISE_HELL_SPELL.get().getSpellId())) {
                        RaiseHellSpell.ambientParticles(livingEntity, spellData);
                    }
                }
            });
        }

    }
}

public void tick() {
    super.tick();
    //prevgetYRot() = getYRot();
    repelEntities(1.8F, 4.0f, 1.8F, 1.8F);
    this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());

    LivingEntity target = this.getTarget();
    Animation animation = getRandomAttack(random);
    Animation animation2 = this.getIsHelmetless() ? GUARDIAN_RAGE_UPPERCUT : GUARDIAN_UPPERCUT_AND_BULLET;
    if (this.isAlive()) {
        if (!this.getIsHelmetless() && this.isHelmetless()) {
            this.setIsHelmetless(true);
            BrokenHelmet();
        }
        if (!isNoAi() && this.getAnimation() == NO_ANIMATION && !this.getUsedMassDestruction() && this.isHelmetless()) {
            this.setAnimation(GUARDIAN_MASS_DESTRUCTION);
        }
        else if (target != null && target.isAlive()) {
            if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) >= 256 && this.distanceToSqr(target) <= 1024.0D && target.onGround() && this.getIsHelmetless() && this.getRandom().nextFloat() * 100.0F < 20f  && teleport_smash_cooldown <= 0) {
                teleport_smash_cooldown = TELEPORT_SMASH_COOLDOWN;
                this.setAnimation(GUARDIAN_AIR_STRIKE1);
            }else if (vortexcooldown <= 0 && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) <= 1024.0D && (this.distanceToSqr(target) >= 35.0D &&this.getRandom().nextFloat() * 100.0F < 2f || this.getRandom().nextFloat() * 100.0F < 60f && this.getY() + 3 <= target.getY())) {
                vortexcooldown = VORTEX_COOLDOWN;
                this.setAnimation(GUARDIAN_BLACKHOLE);
            } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) >= 4.3 && this.distanceTo(target) <= 16D && target.onGround() && this.getRandom().nextFloat() * 100.0F < 4f && teleport_cooldown <= 0) {
                teleport_cooldown = TELEPORT_COOLDOWN;
                this.setAnimation(GUARDIAN_HUG_ME);
            } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 4.3 && target.onGround() && this.getRandom().nextFloat() * 100.0F < 0.7f && teleport_cooldown <= 0) {
                teleport_cooldown = TELEPORT_COOLDOWN;
                this.setAnimation(GUARDIAN_HUG_ME);
            } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 2.75F) {
                if (this.random.nextInt(6) == 0) {
                    this.setAnimation(GUARDIAN_BURST_ATTACK);
                } else {
                    this.setAnimation(animation);
                }
            } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) > 2.75F && this.distanceTo(target) < 4.3F && (target.hasEffect(MobEffects.LEVITATION) || target.hasEffect(ModEffect.EFFECTSTUN.get()))) {
                uppercut_cooldown = UPPERCUT_COOLDOWN;
                this.setAnimation(animation2);
            } else if (stomp_cooldown <= 0 && !isNoAi() && this.getAnimation() == NO_ANIMATION && target.onGround() && (this.distanceTo(target) > 6F && this.distanceTo(target) < 13F && this.getRandom().nextFloat() * 100.0F < 10f || this.distanceTo(target) > 2.75F && this.distanceTo(target) < 4.3F && this.getRandom().nextFloat() * 100.0F < 2f)) {
                stomp_cooldown = STOMP_COOLDOWN;
                Animation animation3 = this.getIsHelmetless() ? GUARDIAN_RAGE_STOMP : GUARDIAN_STOMP;
                this.setAnimation(animation3);
            } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) > 2.75F && this.distanceTo(target) < 4.3F) {
                if (this.random.nextInt(4) == 0) {
                    uppercut_cooldown = UPPERCUT_COOLDOWN;
                    this.setAnimation(animation2);
                } else {
                    this.setAnimation(animation);
                }
            }
        }
    }


    if (stomp_cooldown > 0) stomp_cooldown--;
    if (teleport_cooldown > 0) teleport_cooldown--;
    if (teleport_smash_cooldown > 0) teleport_smash_cooldown--;
    if (uppercut_cooldown > 0) uppercut_cooldown--;
    if (vortexcooldown > 0) vortexcooldown--;
}

public void tick() {
    super.tick();
    this.prevSitProgress = this.sitProgress;
    if (this.isSitting()) {
        if (sitProgress < 10F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
        this.setOrderedToSit(false);
        sittingTime = 0;
        maxSitTime = 75 + random.nextInt(50);
    }
    if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isSitting() && this.getCommand() != 1 && random.nextInt(1500) == 0) {
        maxSitTime = 300 + random.nextInt(250);
        this.setOrderedToSit(true);
    }
    this.setMaxUpStep(2);
    if (!forcedSit && this.isSitting() && (this.getDartTarget() != null || this.getCommand() == 1)) {
        this.setOrderedToSit(false);
    }

    if (!this.level().isClientSide) {
        if (this.getTarget() != null && this.getAnimation() == ANIMATION_SCRATCH && this.getAnimationTick() == 10) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.3F, 0.0D, Mth.cos(f1) * 0.3F));
            getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            this.setAttackDecision(this.getTarget());
        }
        if (this.getDartTarget() != null && this.getDartTarget().isAlive() && this.getAnimation() == ANIMATION_THROW && this.getAnimationTick() == 5) {
            final Vec3 vector3d = this.getDartTarget().getDeltaMovement();
            final double d0 = this.getDartTarget().getX() + vector3d.x - this.getX();
            final double d1 = this.getDartTarget().getEyeY() - (double) 1.1F - this.getY();
            final double d2 = this.getDartTarget().getZ() + vector3d.z - this.getZ();
            final float f = Mth.sqrt((float)(d0 * d0 + d2 * d2));
            EntityTossedItem tossedItem = new EntityTossedItem(this.level(), this);
            tossedItem.setDart(this.hasDart());
            tossedItem.setXRot(tossedItem.getXRot() - 20F);
            tossedItem.shoot(d0, d1 + (double) (f * 0.2F), d2, hasDart() ? 1.15F : 0.75F, 8.0F);
            if (!this.isSilent()) {
                this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_THROW, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                this.gameEvent(GameEvent.PROJECTILE_SHOOT);
            }
            this.level().addFreshEntity(tossedItem);
            this.setAttackDecision(this.getDartTarget());
        }
    }
    if (rideCooldown > 0) {
        rideCooldown--;
    }
    if (!this.level().isClientSide && getAnimation() == NO_ANIMATION && this.getRandom().nextInt(300) == 0) {
        setAnimation(ANIMATION_HEADTILT);
    }
    if (!this.level().isClientSide && this.isSitting()) {
        this.getNavigation().stop();
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    super.tick();
    LivingEntity target = EntityFarseer.this.getTarget();
    if (laserCooldown > 0) {
        laserCooldown--;
    }
    timeSinceLastSuccessfulAttack++;
    if (timeSinceLastSuccessfulAttack > 100) {
        timeSinceLastSuccessfulAttack = 0;
        attackDecision = !attackDecision;
    }
    if (target != null) {
        double dist = EntityFarseer.this.distanceTo(target);
        boolean canLaserHit = willLaserHit(target);
        if (this.laserCooldown == 0 && attackDecision && canLaserHit && dist > 2F) {
            EntityFarseer.this.setAngry(true);
            EntityFarseer.this.entityData.set(LASER_ENTITY_ID, target.getId());
            if(laserUseTime == 0){
                EntityFarseer.this.playSound(AMSoundRegistry.FARSEER_BEAM.get(), EntityFarseer.this.getSoundVolume(), EntityFarseer.this.getVoicePitch());
            }
            laserUseTime++;
            if (laserUseTime > LASER_ATTACK_DURATION) {
                laserUseTime = 0;
                if (canLaserHit) {
                    float healthTenth = target.getMaxHealth() * 0.1F;
                    if(target.hurt(AMDamageTypes.causeFarseerDamage(EntityFarseer.this), random.nextInt(2) + Math.max(6, healthTenth)) && !target.isAlive()){
                        AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                    }
                    timeSinceLastSuccessfulAttack = 0;
                }
                if (lasersShot++ > 5) {
                    lasersShot = 0;
                    laserCooldown = 80 + random.nextInt(40);
                    EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                    attackDecision = EntityFarseer.this.getRandom().nextBoolean();
                }
            }
            EntityFarseer.this.entityData.set(LASER_ATTACK_LVL, laserUseTime);
            EntityFarseer.this.lookAt(target, 180F, 180F);
            if (dist < 17F && canLaserHit) {
                EntityFarseer.this.getNavigation().stop();
            } else {
                EntityFarseer.this.getNavigation().moveTo(target, 1F);
            }
            EntityFarseer.this.entityData.set(MELEEING, false);
        } else {
            if (!canLaserHit && dist > 10) {
                EntityFarseer.this.setAngry(false);
            }
            if (EntityFarseer.this.hasLaser()) {
                EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
            }
            EntityFarseer.this.entityData.set(MELEEING, dist < 4F);
            if (dist < 4F) {
                timeSinceLastSuccessfulAttack = 0;
            } else {
                EntityFarseer.this.getNavigation().moveTo(target, 1F);
                EntityFarseer.this.moveControl.setWantedPosition(target.getX(), target.getEyeY(), target.getZ(), 1F);
            }
        }
    }
}

public void onUpdate() {
	if (!world.isRemote) {
		if (fleeingTick == 0 && getAttackTarget() != null && getDistance(getAttackTarget()) < 2) {
			onCollideWithEntity(getAttackTarget());
		}
		if (getRidingEntity() != null) {
			setRotation(getRidingEntity().rotationYaw, getRidingEntity().rotationPitch);
			if (getRidingEntity().isBurning() && getRidingEntity() instanceof EntityLivingBase) {
				PotionEffect stomachContents = new PotionEffect(MobEffects.POISON, 120 + getBloodConsumed() * 200 / MAX_BLOOD_LEVEL, 0);
				((EntityLivingBase) getRidingEntity()).addPotionEffect(stomachContents);
				setBloodConsumed(0);
				Entity mount = this.getRidingEntity();
				dismountEntity(mount);
				flee();
				dismountRidingEntity();
				this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(mount));
			}
		}
		if (getBloodConsumed() == MAX_BLOOD_LEVEL && getRidingEntity() != null) {
			Entity mount = this.getRidingEntity();
			dismountEntity(getRidingEntity());
			dismountRidingEntity();
			this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(mount));
		}
		if (fleeingTick > 0) {
			fleeingTick--;
			if (fleeingTick == 0) {
				stopFleeing();
			}
		}
	}

	if (!firstTickCheck) {
		dismountRidingEntity();
		firstTickCheck = true;
	}
	if (--hungerCoolDown == 0) {
		if (getBloodConsumed() > 0) {
			setBloodConsumed(getBloodConsumed() - 1);
		}
	}
	if (getRidingEntity() != null) {
		moveProgress = 1 + mathSucking.swing(1, 0.15F, false);
		if (rand.nextInt(10) == 0) {
			for (int i = 0; i < 8; i++) {
				world.spawnParticle(EnumParticleTypes.REDSTONE, posX + (rand.nextFloat() - rand.nextFloat()), posY + rand.nextFloat(), posZ + (rand.nextFloat() - rand.nextFloat()), 0, 0, 0);
			}
		}
	} else if (!world.isRemote) {
		moveProgress = 0F + mathSucking.swing(1, 0.15F, false);
	}

	if (getRidingEntity() != null && getRidingEntity() instanceof EntityLivingBase && getBloodConsumed() < MAX_BLOOD_LEVEL) {
		drainage++;
		if (drainage >= attackCountDown && this.deathTime == 0) {
			getRidingEntity().attackEntityFrom(DamageSource.causeMobDamage(this), (int)getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
			drainage = 0;
			setBloodConsumed(getBloodConsumed() + 1);
		}
	}
	super.onUpdate();
}

public void tick() {
   LivingEntity livingentity = this.mob.getTarget();
   if (livingentity != null) {
      boolean flag = this.mob.getSensing().hasLineOfSight(livingentity);
      boolean flag1 = this.seeTime > 0;
      if (flag != flag1) {
         this.seeTime = 0;
      }

      if (flag) {
         ++this.seeTime;
      } else {
         --this.seeTime;
      }

      double d0 = this.mob.distanceToSqr(livingentity);
      boolean flag2 = (d0 > (double)this.attackRadiusSqr || this.seeTime < 5) && this.attackDelay == 0;
      if (flag2) {
         --this.updatePathDelay;
         if (this.updatePathDelay <= 0) {
            this.mob.getNavigation().moveTo(livingentity, this.canRun() ? this.speedModifier : this.speedModifier * 0.5D);
            this.updatePathDelay = PATHFINDING_DELAY_RANGE.sample(this.mob.getRandom());
         }
      } else {
         this.updatePathDelay = 0;
         this.mob.getNavigation().stop();
      }

      this.mob.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
      if (this.crossbowState == CrossbowState.UNCHARGED) {
         if (!flag2) {
            this.mob.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.mob, item -> item instanceof CrossbowItem));
            this.crossbowState = CrossbowState.CHARGING;
            this.mob.setChargingCrossbow(true);
         }
      } else if (this.crossbowState == CrossbowState.CHARGING) {
         if (!this.mob.isUsingItem()) {
            this.crossbowState = CrossbowState.UNCHARGED;
         }

         int i = this.mob.getTicksUsingItem();
         ItemStack itemstack = this.mob.getUseItem();
         if (i >= CrossbowItem.getChargeDuration(itemstack)) {
            this.mob.releaseUsingItem();
            this.crossbowState = CrossbowState.CHARGED;
            this.attackDelay = 20 + this.mob.getRandom().nextInt(20);
            this.mob.setChargingCrossbow(false);
         }
      } else if (this.crossbowState == CrossbowState.CHARGED) {
         --this.attackDelay;
         if (this.attackDelay == 0) {
            this.crossbowState = CrossbowState.READY_TO_ATTACK;
         }
      } else if (this.crossbowState == CrossbowState.READY_TO_ATTACK && flag) {
         this.mob.performRangedAttack(livingentity, 1.0F);
         ItemStack itemstack1 = this.mob.getItemInHand(ProjectileUtil.getWeaponHoldingHand(this.mob, item -> item instanceof CrossbowItem));
         CrossbowItem.setCharged(itemstack1, false);
         this.crossbowState = CrossbowState.UNCHARGED;
      }

   }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        if (staff.is(ModItems.NAMELESS_STAFF.get())){
            Vec3 vec3 = caster.position();
            Direction direction = caster.getDirection();
            double stepX = direction.getStepX();
            double stepZ = direction.getStepZ();
            for (int i1 = -3; i1 <= 3; ++i1) {
                VanguardServant summonedentity = new VanguardServant(ModEntityType.VANGUARD_SERVANT.get(), worldIn);
                summonedentity.setTrueOwner(caster);
                Vec3 vec32 = new Vec3(((2 * stepX) + (i1 * stepZ)) + vec3.x(), vec3.y(), ((2 * stepZ) + (i1 * stepX)) + vec3.z());
                if (!worldIn.noCollision(summonedentity, summonedentity.getBoundingBox().move(vec32))){
                    vec32 = Vec3.atCenterOf(BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, caster.level));
                }
                summonedentity.setPos(vec32);
                MobUtil.moveDownToGround(summonedentity);
                summonedentity.setPersistenceRequired();
                summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
                this.buffSummon(caster, summonedentity, potency);
                summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                summonedentity.setYHeadRot(caster.getYHeadRot());
                summonedentity.setYRot(caster.getYRot());
                this.SummonSap(caster, summonedentity);
                this.setTarget(caster, summonedentity);
                if (worldIn.addFreshEntity(summonedentity)) {
                    this.namelessSummon(worldIn, caster, staff, summonedentity);
                }
                this.summonAdvancement(caster, summonedentity);
            }
        } else {
            int i = 1;
            if (rightStaff(staff)){
                i = 2 + caster.level.random.nextInt(6);
            }
            for (int i1 = 0; i1 < i; ++i1) {
                VanguardServant summonedentity = new VanguardServant(ModEntityType.VANGUARD_SERVANT.get(), worldIn);
                summonedentity.setTrueOwner(caster);
                summonedentity.moveTo(BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn), 0.0F, 0.0F);
                MobUtil.moveDownToGround(summonedentity);
                summonedentity.setPersistenceRequired();
                summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
                this.buffSummon(caster, summonedentity, potency);
                summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                this.SummonSap(caster, summonedentity);
                this.setTarget(caster, summonedentity);
                if (worldIn.addFreshEntity(summonedentity)) {
                    this.uponSummon(worldIn, caster, staff, summonedentity);
                }
                this.summonAdvancement(caster, summonedentity);
            }
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.VANGUARD_SUMMON.get());
    }
}

	public InteractionResult mobInteract(Player player, @NotNull InteractionHand hand) {
		ItemStack itemstack = player.getItemInHand(hand);

		//debugging code
		if(itemstack.is(Items.DEBUG_STICK) && !player.level().isClientSide()){
            if(isResting()){
                // #5327 - isSleeping is always returning false.
                //vanilla foxes have their own isSleeping method instead of using the LivingEntity method,
                //but that uses entity data which is synced, ai goals (which we are using for sleep) are not.
                player.sendSystemMessage(Component.literal("setResting(false)"));
                setResting(false);
            }
            else{
                player.sendSystemMessage(Component.literal("setSleeping(true)"));
                setResting(true);
                return InteractionResult.CONSUME;
            }
		}

		if(itemstack.getItem() == Items.BONE && !isTame())
			return InteractionResult.PASS; //prevent bone being passed to superclass

		Level level = level();
		if(this.isTame()) {
			if(timeUntilPotatoEmerges <= 0 && itemstack.is(TinyPotatoModule.tiny_potato.asItem())) {
				timeUntilPotatoEmerges = 600;

				playSound(QuarkSounds.ENTITY_FOXHOUND_EAT, 1f, 1f);
				if(!player.getAbilities().instabuild)
					itemstack.shrink(1);
				return InteractionResult.sidedSuccess(level.isClientSide);
			}
		} else {
			if(!itemstack.isEmpty()) {
				if(itemstack.getItem() == Items.COAL && (level.getDifficulty() == Difficulty.PEACEFUL || player.getAbilities().invulnerable || player.getEffect(MobEffects.FIRE_RESISTANCE) != null) && !level.isClientSide) {
					if(random.nextDouble() < FoxhoundModule.tameChance) {
						this.tame(player); //this call ends up running ApplyTamingSideEffects
						this.navigation.stop();
						this.setTarget(null);
						this.setInSittingPose(true);
						level.broadcastEntityEvent(this, (byte) 7);
					} else {
						level.broadcastEntityEvent(this, (byte) 6);
					}

					if(!player.getAbilities().instabuild)
						itemstack.shrink(1);
					return InteractionResult.sidedSuccess(level.isClientSide);
				}
			}
		}

		InteractionResult res = super.mobInteract(player, hand);
		if(res.consumesAction()) {
            setResting(false);
            if (isOrderedToSit()) {
                setInSittingPose(true);
            }
        }

		return res;
	}

