        ParticleUtil.spawnPoof((ServerLevel) level, blockPosition());
        ItemStack stack = new ItemStack(ItemsRegistry.ALAKARKINOS_SHARD);
        level.addFreshEntity(new ItemEntity(level, getX(), getY(), getZ(), stack));
        this.remove(RemovalReason.DISCARDED);
    }
    if (!level.isClientSide) {
        stateMachine.tick();
        SummonUtil.healOverTime(this);
        if (findBlockCooldown > 0) {
            findBlockCooldown--;
        }
    } else {

        if (blowingBubbles()) {
            ticksBlowingAnim++;
            if (ticksBlowingAnim < 10) {
                return;
            }
            var optPos = this.entityData.get(BLOWING_AT);
            if (optPos.isEmpty()) {
                return;
            }
            BlockPos to = optPos.get();
            Vec3 towards = new Vec3(to.getX() + 0.5, to.getY() + 0.5, to.getZ() + 0.5);
            // Spawn particles from this mob to the target
            float randScale = 0.2f;
            Vec3 from = new Vec3(this.getX() + ParticleUtil.inRange(-randScale, randScale), this.getY() + 0.75 + ParticleUtil.inRange(-randScale, randScale), this.getZ() + ParticleUtil.inRange(-randScale, randScale));
            Vec3 dir = towards.subtract(from).normalize();
            Vec3 pos = from.add(dir.scale(0.5));
            Vec3 motion = dir.scale(0.2);
            level.addAlwaysVisibleParticle(
                    ModParticles.ALAKARK_BUBBLE_TYPE.get(),
                    pos.x, pos.y, pos.z, motion.x, motion.y * 0.05, motion.z
            );
            if (getRandom().nextInt(20) == 0) {
                level.playLocalSound(
                        getX(),
                        getY(),
                        getZ(),
                        SoundEvents.BUBBLE_COLUMN_WHIRLPOOL_AMBIENT,
                        SoundSource.NEUTRAL,
                        0.8F + getRandom().nextFloat() * 0.2F,
                        0.9F + getRandom().nextFloat() * 0.15F,
                        false
                );
            }
        } else {
            ticksBlowingAnim = 0;
        }
    }
}

public void tick() {
    if (tossItemCooldown > 0) {
        tossItemCooldown--;
    }
    if (checkReachCooldown > 0) {
        checkReachCooldown--;
    }
    if (checkReachCooldown == 0) {
        checkReachCooldown = 100 + mob.getRandom().nextInt(40);
        if (mob.canTeleport() && !mob.canReach(cruciblePos)) {
            mob.setTeleportingToPos(Vec3.atCenterOf(cruciblePos.relative(Util.getRandom(ACMath.HORIZONTAL_DIRECTIONS, mob.getRandom()))));
            return;
        }
    }
    Vec3 center = Vec3.atCenterOf(cruciblePos);
    double distance = Vec3.atBottomCenterOf(cruciblePos).subtract(mob.position()).horizontalDistance();
    if (distance < 8.0D) {
        mob.getLookControl().setLookAt(center.x, center.y + 1.0F - Math.sin(cookTime * 0.2F) * 0.2F, center.z, 10.0F, (float) this.mob.getMaxHeadXRot());
    }
    if (distance > 2.5D) {
        mob.getNavigation().moveTo(cruciblePos.getX() + 0.5F, cruciblePos.getY(), cruciblePos.getZ() + 0.5F, 1);
    } else {
        if (distance < 1.25D) {
            mob.getMoveControl().strafe(0.1F, 0F);
        } else {
            mob.getMoveControl().strafe(0F, 0F);
        }
        mob.setLastCruciblePos(cruciblePos);
        mob.getNavigation().stop();
        if (mob.level().getBlockEntity(cruciblePos) instanceof ConversionCrucibleBlockEntity crucibleBlock && hasLineOfSightCrucible()) {
            mob.updateHeldItems = false;
            boolean flag = crucibleBlock.isWitchMode();
            crucibleBlock.setWitchModeDuration(10);
            if (!flag && crucibleBlock.isWitchMode()) {
                crucibleBlock.rerollWantedItem();
                crucibleBlock.markUpdated();
            }
            if (mob.areArmsVisuallyCrossed(1.0F) && mob.getAnimation() == IAnimatedEntity.NO_ANIMATION && !crucibleBlock.getWantItem().isEmpty() && crucibleBlock.getItemDisplayProgress(1.0F) >= 1.0F) {
                mob.setItemInHand(InteractionHand.MAIN_HAND, crucibleBlock.getWantItem().copy());
            }
            if (!crucibleBlock.getWantItem().isEmpty() && crucibleBlock.getItemDisplayProgress(1.0F) >= 1.0F && tossItemCooldown == 0) {
                if (tossedItem != null) {
                    tossedItem.discard();
                }
                if (mob.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    mob.setAnimation(mob.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                } else if ((mob.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || mob.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && mob.getAnimationTick() == 4) {
                    mob.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    Vec3 from = mob.getSwingArmPosition();
                    ItemStack stack = crucibleBlock.getWantItem().copy();
                    tossedItem = new ItemEntity(mob.level(), from.x, from.y, from.z, stack);
                    Vec3 delta = center.subtract(from).normalize().scale(0.13F).add(0, 0.4F, 0);
                    tossedItem.setNeverPickUp();
                    tossedItem.setDeltaMovement(delta);
                    tossedItem.checkDespawn();
                    mob.level().addFreshEntity(tossedItem);
                    tossItemCooldown = 50;
                }
            }
            cookTime++;
        }
    }
}

public void serverTick(Level level, BlockPos pos, BlockState state) {
    if (FossilConfig.isEnabled(FossilConfig.MACHINES_REQUIRE_ENERGY) && energyStorage.getEnergy() <= 0) {
        if (cookingProgress > 0) {
            cookingProgress = Mth.clamp(cookingProgress - 2, 0, CultureVatMenu.CULTIVATION_DURATION);
        }
        return;
    }
    int prevCookingProgress = cookingProgress;
    boolean wasFueled = litTime > 0;
    boolean wasProcessing = cookingProgress > 0;
    boolean dirty = false;
    if (litTime > 0) {
        --litTime;
    }

    if (canProcess() && (litTime == 0 || (litTime > 0 && !canProcess(fuel)))) {
        ItemStack fuelStack = items.get(CultureVatMenu.FUEL_SLOT_ID);
        litDuration = litTime = getRecipeFuelTime(items.get(CultureVatMenu.INPUT_SLOT_ID), fuelStack);
        fuel = fuelStack.copy();
        if (litTime > 0) {
            dirty = true;
            fuelStack.shrink(1);
            if (fuelStack.isEmpty() && fuelStack.getItem().hasCraftingRemainingItem()) {
                items.set(CultureVatMenu.FUEL_SLOT_ID, new ItemStack(fuelStack.getItem().getCraftingRemainingItem()));
            }
        }
    }

    if (litTime > 0 && canProcess(fuel)) {
        cookingProgress++;
        if (cookingProgress >= CultureVatMenu.CULTIVATION_DURATION) {
            cookingProgress = 0;
            createItem();
            dirty = true;
        }
    }
    if (prevCookingProgress != cookingProgress && FossilConfig.isEnabled(FossilConfig.MACHINES_REQUIRE_ENERGY)) {
        energyStorage.extractEnergy(FossilConfig.getInt(FossilConfig.MACHINE_ENERGY_USAGE));
    }
    if (litTime == 0 && cookingProgress > 0 || litTime > 0 && cookingProgress > 0 && !canProcess(fuel)) {
        cookingProgress = Mth.clamp(cookingProgress - 2, 0, CultureVatMenu.CULTIVATION_DURATION);
    }

    if (wasFueled != litTime > 0) {
        dirty = true;
        state = state.setValue(CultureVatBlock.ACTIVE, litTime > 0);
        level.setBlock(pos, state, 3);
    }

    if (wasProcessing != cookingProgress > 0) {
        dirty = true;
        state = state.setValue(CultureVatBlock.EMBRYO, getDNAType());
        level.setBlock(pos, state, 3);
    }

    if (dirty) {
        setChanged(level, pos, state);
    }

    if (cookingProgress == 3001 && level.getRandom().nextInt(100) < FossilConfig.getInt(FossilConfig.CULTURE_VAT_FAIL_CHANCE)) {
        ModBlocks.CULTURE_VAT.get().onFailedCultivation(level, pos);
    }
}

public void tick() {
    if (hackComplete) return;

    isStarted = true;

    if (stopWormTimer > 0) {
        stopWormTimer--;
    }
    if (nukeVirusCooldown > 0) {
        nukeVirusCooldown--;
    }

    allConnections.clear();
    int nonNullNodes = 0;
    int completeNodes = 0;
    for (int i = 0; i < nodes.length; i++) {
        Node node = getNodeAt(i);
        if (node == null) continue;
        nonNullNodes++;

        int f = node.fortification;
        node.tick();
        if (controller != null && f < NODE_FORTIFICATION_TIME && node.fortification == NODE_FORTIFICATION_TIME) {
            controller.onNodeFortified(this, i);
        }

        if (side == HackingSide.AI && isAwake() && (isDummy() || node.isHacked()) && node.outGoingHacks.isEmpty()) {
            // start the trace to all neighbouring nodes
            for (int neighbourPos : getNeighbours(i)) {
                Node neighbourNode = getNodeAt(neighbourPos);
                if (neighbourNode != null && (isDummy() || !neighbourNode.isHacked())) {
                    // found an unhacked neighbour
                    node.startHacking(i, neighbourPos);
                }
            }
        }

        if (pendingNukePos == i) {
            activateNukeVirus(i);
        }

        // update all in-progress connections
        int finishedConns = 0;
        for (Pair<Integer, Float> conn : node.outGoingHacks) {
            if (conn.getValue() < 1F) {
                if (stopWormTimer == 0) {
                    Node targetNode = getNodeAt(conn.getKey());
                    if (targetNode != null) {
                        conn.setValue(Math.min(1F, conn.getValue() + targetNode.getProgressPerTick()));
                        targetNode.setHackProgress(conn.getKey(), conn.getValue(), true);
                    }
                }
            } else {
                finishedConns++;
            }
            allConnections.add(new ConnectionEntry(i, conn.getKey(), conn.getValue()));
        }
        if (finishedConns == node.outGoingHacks.size() && !node.outGoingHacks.isEmpty()) completeNodes++;
    }
    if (completeNodes >= nonNullNodes) {
        hackComplete = true;
    }
}

public void tick() {
	super.tick();

	if (getTarget() == null || !isAlive())
		return;

	LivingEntity target = getTarget();

	if (jumpCooldown > 0)
		jumpCooldown--;

	if (jumpCooldown <= 0) {
		if (jumpCount < 4) {
			jumpIntervalTimer--;

			if (jumpIntervalTimer <= 0) {
				setDeltaMovement((target.getX() - getX()) * 0.045, 0.699, (target.getZ() - getZ()) * 0.045);

				hurtMarked = true;

				if (!level.isClientSide) {
					level.playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_MECHBOT_JUMP.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
					level.addFreshEntity(new MechFallEntity(this, getX(), getY() - 0.25, getZ(), BaseMobProjectile.Type.MAGIC));

					if (getHealth() < 1250) {
						level.addFreshEntity(new MechFallEntity(this, getX() - 2.25, getY() - 0.25, getZ() - 2.25, BaseMobProjectile.Type.MAGIC));
						level.addFreshEntity(new MechFallEntity(this, getX() - 2.25, getY() - 0.25, getZ() + 2.25, BaseMobProjectile.Type.MAGIC));
						level.addFreshEntity(new MechFallEntity(this, getX() + 2.25, getY() - 0.25, getZ() - 2.25, BaseMobProjectile.Type.MAGIC));
						level.addFreshEntity(new MechFallEntity(this, getX() + 2.25, getY() - 0.25, getZ() + 2.25, BaseMobProjectile.Type.MAGIC));
					}
				}

				jumpCount++;
				jumpIntervalTimer = 15;
			}
		}
		else {
			jumpCooldown = 200;
			jumpCount = 0;
			jumpIntervalTimer = 15;
		}
	}

	if (getHealth() < 1000 ? random.nextInt(10) == 0 : random.nextInt(40) == 0) {
		MechShotEntity projectile = new MechShotEntity(this, BaseMobProjectile.Type.MAGIC);

		double distanceFactorX = target.getX() - this.getX();
		double distanceFactorY = target.getBoundingBox().minY + (double)(target.getBbHeight() / 3.0f) - projectile.getY();
		double distanceFactorZ = target.getZ() - this.getZ();
		double hyp = MathHelper.sqrt(distanceFactorX * distanceFactorX + distanceFactorZ * distanceFactorZ) + 0.2D;

		level.playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_MECHBOT_SHOOT.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
		projectile.shoot(distanceFactorX, distanceFactorY + hyp * 0.20000000298023224D, distanceFactorZ, 1.6f, (float)(4 - this.level.getDifficulty().getId()));
		level.addFreshEntity(projectile);
	}

	if (!level.isClientSide()) {
		float healthPercent = getHealth() / getMaxHealth();

		if (healthPercent != bossInfo.getPercent())
			bossInfo.setPercent(healthPercent);
	}
}

public Map<Activity, BrainActivityGroup<? extends AoABoss>> getAdditionalTasks() {
	return Map.of(AoABrainActivities.FIGHT_2.get(),
			new BrainActivityGroup(AoABrainActivities.FIGHT_2.get())
					.priority(11)
					.behaviours(
							new InvalidateMemory<>(AoABrainMemories.SECOND_ATTACK_TARGET.get())
									.invalidateIf((entity, target) -> {
