	public InteractionResult mobInteract(Player player, @NotNull InteractionHand hand) {
		ItemStack itemstack = player.getItemInHand(hand);

		//debugging code
		if(itemstack.is(Items.DEBUG_STICK) && !player.level().isClientSide()){
            if(isResting()){
                // #5327 - isSleeping is always returning false.
                //vanilla foxes have their own isSleeping method instead of using the LivingEntity method,
                //but that uses entity data which is synced, ai goals (which we are using for sleep) are not.
                player.sendSystemMessage(Component.literal("setResting(false)"));
                setResting(false);
            }
            else{
                player.sendSystemMessage(Component.literal("setSleeping(true)"));
                setResting(true);
                return InteractionResult.CONSUME;
            }
		}

		if(itemstack.getItem() == Items.BONE && !isTame())
			return InteractionResult.PASS; //prevent bone being passed to superclass

		Level level = level();
		if(this.isTame()) {
			if(timeUntilPotatoEmerges <= 0 && itemstack.is(TinyPotatoModule.tiny_potato.asItem())) {
				timeUntilPotatoEmerges = 600;

				playSound(QuarkSounds.ENTITY_FOXHOUND_EAT, 1f, 1f);
				if(!player.getAbilities().instabuild)
					itemstack.shrink(1);
				return InteractionResult.sidedSuccess(level.isClientSide);
			}
		} else {
			if(!itemstack.isEmpty()) {
				if(itemstack.getItem() == Items.COAL && (level.getDifficulty() == Difficulty.PEACEFUL || player.getAbilities().invulnerable || player.getEffect(MobEffects.FIRE_RESISTANCE) != null) && !level.isClientSide) {
					if(random.nextDouble() < FoxhoundModule.tameChance) {
						this.tame(player); //this call ends up running ApplyTamingSideEffects
						this.navigation.stop();
						this.setTarget(null);
						this.setInSittingPose(true);
						WantLoveGoal.setPetTime(this); //only sets time if dogsWantLove > 0
						level.broadcastEntityEvent(this, (byte) 7);
					} else {
						level.broadcastEntityEvent(this, (byte) 6);
					}

					if(!player.getAbilities().instabuild)
						itemstack.shrink(1);
					return InteractionResult.sidedSuccess(level.isClientSide);
				}
			}
		}

		InteractionResult res = super.mobInteract(player, hand);
		if(res.consumesAction()) {
            setResting(false);
            if (isOrderedToSit()) {
                setInSittingPose(true);
            }
        }

		return res;
	}

public void setMaxMobLife(ServerLevel serverLevel) {
    if (this.storedLivingEntity == null)
        return;

    ItemStack soul = getStack(this.inputSoulHandler, 0);
    ItemStack weapon = getStack(this.inputWeaponHandler, 0);
    if (soul.isEmpty() || weapon.isEmpty())
        return;

    //Setup soulValue and mob health
    float health = this.storedLivingEntity.getMaxHealth();
    this.soulValue = (int) (soul.has(OccultismDataComponents.SOUL_VALUE) ? (health * 0.5) : health);
    health *= BUTCHER_LIFE_MULT;
    if (weapon.isEnchanted()) { //Custom health modifier
        int fsLVL = weapon.getEnchantmentLevel(this.FRACTURE_SOUL);
        if (fsLVL > 0)
            health *= Math.clamp(1-(fsLVL * BUTCHER_FRAC_BONUS), 0, 1);
    }
    Holder<EntityType<?>> entityTypeHolder = this.storedLivingEntity.typeHolder(); //Boss penality
    if (entityTypeHolder.is(EntityTypes.BOSSES) && !soul.is(OccultismItems.TRINITY_GEM_ITEM)) {
        health *= 3;
    }

    //Setup attackSpeed
    double attackSpeed = 4.0;
    if (weapon.has(DataComponents.ATTRIBUTE_MODIFIERS)) {
        var mods = weapon.get(DataComponents.ATTRIBUTE_MODIFIERS);
        if (mods != null)
            for (var entry : mods.modifiers()) {
                var modifier = entry.modifier();
                if (entry.attribute().is(Objects.requireNonNull(Attributes.ATTACK_SPEED.getKey())))
                    attackSpeed += modifier.amount();
            }
    }

    //Setup attackDamage
    double attackDamage = 1.0;
    if (weapon.has(DataComponents.ATTRIBUTE_MODIFIERS)) {
        var mods = weapon.get(DataComponents.ATTRIBUTE_MODIFIERS);
        if (mods != null)
            for (var entry : mods.modifiers()) {
                var modifier = entry.modifier();
                if (entry.attribute().is(Objects.requireNonNull(Attributes.ATTACK_DAMAGE.getKey())))
                    attackDamage += modifier.amount();
            }
    }
    attackDamage = EnchantmentHelper.modifyDamage(serverLevel, weapon, this.storedLivingEntity,
            this.storedLivingEntity.damageSources().generic(), (float) attackDamage);
    if (weapon.is(OccultismTags.Items.TOOLS_KNIFE_IESNIUM) && //Custom vulnerability
            (entityTypeHolder.is(Entities.HEALED_BY_OTHERWORLD_FRUIT) || entityTypeHolder.is(EntityTypes.BOSSES))) {
        attackDamage *= 3;
    }

    //Final setups
    if (attackSpeed == 0 || attackDamage == 0)
        return;
    int life = Math.max((int) (health / attackDamage), 1);
    int hitSpeed = Math.max((int) (40 / attackSpeed), 1);
    this.maxMobLife = life;
    this.mobHealth = life;
    this.maxHitTimer = hitSpeed;
    this.hitTimer = hitSpeed;
}

protected void customServerAiStep() {
    if (this.getIsAct()) {
        if (this.deactivateProgress > 0) {
            float k1 = deactivateProgress - 1;
            if (k1 <= 0) {
                if (!this.isSilent()) {
                    this.level().globalLevelEvent(1023, this.blockPosition(), 0);
                }
            }
        }else{
            super.customServerAiStep();
            for (int i = 1; i < 3; ++i) {
                if (this.tickCount >= this.nextHeadUpdate[i - 1]) {
                    this.nextHeadUpdate[i - 1] = this.tickCount + 10 + this.random.nextInt(10);
                    int l1 = this.getAlternativeTarget(i);
                    if (l1 > 0) {
                        LivingEntity livingentity = (LivingEntity) this.level().getEntity(l1);
                        if (livingentity != null && this.canAttack(livingentity) && !(this.distanceToSqr(livingentity) > 1600.0D) && this.hasLineOfSight(livingentity) && (Laser_Mode_Progress == 30 || Laser_Mode_Progress == 0) && this.getAnimation() == NO_ANIMATION) {
                            this.performRangedAttack(i + 1, livingentity);
                            int f = this.getIsLaserMode() ? 15 + this.random.nextInt(5) : 30 + this.random.nextInt(20);
                            this.nextHeadUpdate[i - 1] = this.tickCount + f;
                            this.idleHeadUpdates[i - 1] = 0;
                        } else {
                            this.setAlternativeTarget(i, 0);
                        }
                    } else {
                        List<LivingEntity> list = this.level().getNearbyEntities(LivingEntity.class, TARGETING_CONDITIONS, this, this.getBoundingBox().inflate(20.0D, 8.0D, 20.0D));
                        if (!list.isEmpty()) {
                            LivingEntity livingentity1 = list.get(this.random.nextInt(list.size()));
                            this.setAlternativeTarget(i, livingentity1.getId());
                        }
                    }
                }
            }
            blockbreak();
            destroyBlock();
            if (this.getTarget() != null) {
                destoryblock2();
            }

            if (mode_change_cooldown < MODE_CHANGE_COOLDOWN) {
                mode_change_cooldown++;
            } else if (this.getAnimation() == NO_ANIMATION) {
                this.setIsLaserMode(!this.getIsLaserMode());
                this.playSound(ModSounds.HARBINGER_MODE_CHANGE.get(), 3.0f, 1.0f);
                mode_change_cooldown = this.random.nextInt(50);
            }

            if (this.getTarget() != null) {
                this.setAlternativeTarget(0, this.getTarget().getId());
            } else {
                this.setAlternativeTarget(0, 0);
            }
            if (this.tickCount % 20 == 0) {
                this.heal((float)CMCommonConfig.Harbinger.AutoHeal);
            }
        }
    }else{
        if (this.tickCount % 20 == 0) {
            this.heal(50 *  (float)CMCommonConfig.Harbinger.healthMultiplier);
        }
    }
}

public void tick(){
    super.tick();
    prevSwimProgress = swimProgress;
    prevSitProgress = sitProgress;
    prevDisplayProgress = displayProgress;
    prevMudProgress = mudProgress;
    if(displayProgress < 5F && this.isDisplaying()){
        displayProgress++;
    }
    if(displayProgress > 0F && !this.isDisplaying()){
        displayProgress--;
    }
    if(sitProgress < 5F && this.isOrderedToSit()){
        sitProgress++;
    }
    if(sitProgress > 0F && !this.isOrderedToSit()){
        sitProgress--;
    }
    //so the model does not sink in mud
    boolean mud = onMud();
    if (mud) {
        if (mudProgress < 1F)
            mudProgress += 0.5f;
    } else {
        if (mudProgress > 0)
            mudProgress -= 0.5f;
    }

    boolean swim = !this.onGround() && this.isInWaterOrBubble();
    if(swimProgress < 5F && swim){
        swimProgress++;
    }
    if(swimProgress > 0 && !swim){
        swimProgress--;
    }
    if (!this.level().isClientSide) {
        if (isInWaterOrBubble()) {
            swimTimer++;
        } else {
            swimTimer--;
        }
    }
    if (displayCooldown > 0) {
        displayCooldown--;
    }
    if(!this.level().isClientSide){
        if(this.getDisplayAngle() < nextDisplayAngleFromServer){
            this.setDisplayAngle(this.getDisplayAngle() + 1);

        }
        if(this.getDisplayAngle() > nextDisplayAngleFromServer) {
            this.setDisplayAngle(this.getDisplayAngle() - 1);
        }
    }
    if(this.isMouthOpen()){
        this.openMouth(this.getMouthTicks() - 1);
    }
    if (this.isInWater() && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (!this.isInWater() && !this.isLandNavigator) {
        switchNavigator(true);
    }
}

public void onUpdateMoveHelper() {
	IAttributeInstance entityMoveSpeedAttribute = this.entity.getAttributeMap().getAttributeInstance(SharedMonsterAttributes.MOVEMENT_SPEED);
	double entityMoveSpeed = entityMoveSpeedAttribute != null ? entityMoveSpeedAttribute.getAttributeValue() : 1.0D;
	double speed = this.getFlightSpeed() * entityMoveSpeed;

	if(this.action == EntityMoveHelper.Action.MOVE_TO) {
		double dx = this.posX - this.entity.posX;
		double dy = this.posY - this.entity.posY;
		double dz = this.posZ - this.entity.posZ;
		double dist = dx * dx + dy * dy + dz * dz;

		if(this.courseChangeCooldown-- <= 0) {
			this.courseChangeCooldown += this.getCourseChangeCooldown();

			dist = (double)MathHelper.sqrt(dist);

			if(this.isNotColliding(this.posX, this.posY, this.posZ, dist)) {
				if(dist < this.entity.width + speed) {
					speed *= dist / (this.entity.width + speed);
				}

				if(dist < 0.01D) {
					this.entity.setMoveForward(0);
					this.action = EntityMoveHelper.Action.WAIT;
				} else {
					this.entity.motionX += dx / dist * speed;
					this.entity.motionY += dy / dist * speed;
					this.entity.motionZ += dz / dist * speed;

					float yaw = (float)(MathHelper.atan2(dz, dx) * (180D / Math.PI)) - 90.0F;
					this.entity.rotationYaw = this.limitAngle(this.entity.rotationYaw, yaw, 90.0F);

					this.entity.setAIMoveSpeed((float)speed);
				}

				this.blocked = false;
			} else {
				this.blocked = true;
			}

			if(this.blocked) {
				this.action = EntityMoveHelper.Action.WAIT;
			}
		}
	} else if(this.action == EntityMoveHelper.Action.STRAFE) {
		float forward = this.moveForward;
		float strafe = this.moveStrafe;
		float dist = MathHelper.sqrt(forward * forward + strafe * strafe);

		float rotX = MathHelper.sin(this.entity.rotationYaw * 0.017453292F);
		float rotZ = MathHelper.cos(this.entity.rotationYaw * 0.017453292F);
		float strafeX = strafe * rotZ - forward * rotX;
		float strafeZ = forward * rotZ + strafe * rotX;

		this.entity.motionX += strafeX / dist * speed * 0.15D;
		this.entity.motionZ += strafeZ / dist * speed * 0.15D;

		this.entity.setAIMoveSpeed((float)speed);
		this.entity.setMoveForward(this.moveForward);
		this.entity.setMoveStrafing(this.moveStrafe);

		this.action = EntityMoveHelper.Action.WAIT;
	}
}

public void tick() {
    if (this.entity.isDiggingInProgress() || this.entity.isBuried()) {
        this.entity.setPraying(false);
        return;
    }
    if (center != null) {
        int worshippingTicks = this.entity.getWorshipTime();
        if (entity.isPackFollower()) {
            UnderzealotEntity leader = (UnderzealotEntity) entity.getPackLeader();
            float f = getPackPosition() / ((float) entity.getPackSize() - 1);
            Vec3 offset = new Vec3(2, 0, 0).yRot(f * ((float) Math.PI * 2F));
            Vec3 at = groundOf(Vec3.atCenterOf(center).add(offset));
            entity.getNavigation().moveTo(at.x, at.y, at.z, 1);
            if (entity.isPraying()) {
                attemptToFollowTicks = 0;
            } else if ((entity.getNavigation().isStuck() || attemptToFollowTicks > 60) && this.entity.distanceToSqr(at) > 8) {
                entity.setBuried(true);
                entity.reemergeAt(BlockPos.containing(at).above(), 20 + entity.getRandom().nextInt(20));
            }
            if (leader != null && leader.sacrificeCooldown > 0) {
                this.entity.sacrificeCooldown = leader.sacrificeCooldown;
            }
            if (leader != null && this.entity.distanceToSqr(at) < 4) {
                entity.setPraying(true);
                Vec3 slightOffset = at.subtract(entity.position());
                if (slightOffset.length() > 1F) {
                    slightOffset = slightOffset.normalize();
                }
                this.entity.setDeltaMovement(this.entity.getDeltaMovement().add(slightOffset.scale(0.04F)));
                entity.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(center));
                BlockPos pos = leader.getLastSacrificePos() == null ? leader.blockPosition().above(5) : leader.getLastSacrificePos().above(5);
                this.entity.setParticlePos(pos);
                entity.level().broadcastEntityEvent(entity, (byte) 77);
                if (worshippingTicks % 10 == 0) {
                    this.entity.level().broadcastEntityEvent(entity, (byte) 61);
                }
                this.entity.setWorshipTime(worshippingTicks + 1);
            } else {
                this.entity.setWorshipTime(0);
                attemptToFollowTicks++;
            }
        } else {
            this.entity.setParticlePos(center.above(5));
            Vec3 at = Vec3.atCenterOf(center);
            if (this.entity.distanceToSqr(at) < 4) {
                Vec3 slightOffset = at.subtract(entity.position());
                if (slightOffset.length() > 1F) {
                    slightOffset = slightOffset.normalize();
                }
                this.entity.setWorshipTime(worshippingTicks + 1);
                this.entity.setDeltaMovement(this.entity.getDeltaMovement().add(slightOffset.scale(0.04F)));
                if (worshippingTicks > UnderzealotEntity.MAX_WORSHIP_TIME - 300 && this.entity.cloudCooldown <= 0 && entity.isSurroundedByPrayers()) {
                    if (entity.getFirstPassenger() instanceof UnderzealotSacrifice underzealotSacrifice) {
                        underzealotSacrifice.triggerSacrificeIn(300);
                        entity.cloudCooldown = 400;
                        entity.level().broadcastEntityEvent(entity, (byte) 62);
                    }
                }
            } else {
                this.entity.setWorshipTime(0);
            }
            entity.getNavigation().moveTo(center.getX(), center.getY(), center.getZ(), 1);
        }
    }
}

public void tick() {
    LivingEntity target = watcher.getTarget();
    if (navigationCheckCooldown-- < 0) {
        calculateReach();
    }
    if (target != null && target.isAlive()) {
        double dist = watcher.distanceTo(target);
        watcher.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());

        if (retreatFor-- > 0) {
            if (retreatTo == null) {
                retreatFor = 0;
            } else {
                Vec3 retreatVec = retreatTo.subtract(watcher.position());
                if (retreatVec.length() > 1) {
                    retreatVec = retreatVec.normalize();
                    watcher.setDeltaMovement(watcher.getDeltaMovement().add(retreatVec.scale(0.2F)));
                    watcher.setShadeMode(true);
                } else {
                    retreatTo = null;
                }
            }
        } else {
            if (!canReachViaGround && !watcher.isShadeMode() && watcher.onGround()) {
                watcher.setShadeMode(true);
            }
            watcher.setShadeMode(!canReachViaGround);
            if (dist < 6 && watcher.hasLineOfSight(target) && watcher.onGround()) {
                watcher.setShadeMode(false);
            }
            if (dist > target.getBbWidth() + watcher.getBbWidth() + 0.5F) {
                watcher.getNavigation().moveTo(target, (watcher.isRunning() ? 1.3F : 1F) + Math.min(Math.log(possessions + 1), 1F) * 0.6F);
            } else {
                if (watcher.hasLineOfSight(target)) {
                    if (watcher.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        watcher.setAnimation(watcher.getRandom().nextBoolean() ? WatcherEntity.ANIMATION_ATTACK_0 : WatcherEntity.ANIMATION_ATTACK_1);
                        watcher.playSound(ACSoundRegistry.WATCHER_ATTACK.get());
                    } else if (watcher.getAnimationTick() == 8) {
                        target.hurt(target.damageSources().mobAttack(watcher), (float) watcher.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                        target.knockback(0.5D, watcher.getX() - target.getX(), watcher.getZ() - target.getZ());
                        retreatFor = 30 + watcher.getRandom().nextInt(30);
                        for (int i = 0; i < 15; i++) {
                            Vec3 vec3 = DefaultRandomPos.getPosAway(watcher, 30, 15, target.position());
                            if (vec3 != null) {
                                retreatTo = vec3;
                                break;
                            }
                        }
                    }
                }
                watcher.getNavigation().stop();
            }
        }
        if (possessions > 2 || dist < 20) {
            watcher.setRunning(true);
        }

        if (watcher.attemptPossession(target)) {
            if (watcher.getPossessedEntity() == null) {
                possessions++;
            }
            watcher.setPossessedEntityUUID(target.getUUID());
        }
    }
}

