            if (worldIn.addFreshEntity(viciousTooth)) {
                viciousTooth.playSound(ModSounds.TOOTH_SPAWN.get());
            }
        }
    }
    this.playSound(worldIn, caster, SoundEvents.EVOKER_CAST_SPELL);
}

	private static void hopperMoved(Level world, BlockPos pos, Direction direction, BlockState state, BlockEntity tile) {
		if(!world.isClientSide && tile instanceof HopperBlockEntity hopper) {
			hopper.setCooldown(0);

			Direction dir = state.getValue(HopperBlock.FACING);
			BlockPos offPos = pos.relative(dir);
			BlockPos targetPos = pos.relative(direction);
			if(offPos.equals(targetPos))
				return;

			if(world.isEmptyBlock(offPos))
				for(int i = 0; i < hopper.getContainerSize(); i++) {
					ItemStack stack = hopper.getItem(i);
					if(!stack.isEmpty()) {
						ItemStack drop = stack.copy();
						drop.setCount(1);
						hopper.removeItem(i, 1);

						boolean shouldDrop = true;
						if(drop.getItem() instanceof BlockItem blockItem) {
							BlockPos groundPos = offPos.below();
							if(world.isEmptyBlock(groundPos))
								groundPos = groundPos.below();
							Block seedType = blockItem.getBlock();
							if(blockItem instanceof SpecialPlantable || seedType instanceof BushBlock) {
                                BlockPos seedPos = groundPos.above();
                                if(state.canSurvive(world, seedPos)) {
                                    BlockState seedState = seedType.defaultBlockState();
                                    world.playSound(null, seedPos, ((AccessorBlockBehavior)seedType).invokeGetSoundType(seedState).getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);

                                    boolean canPlace = true;
                                    if(seedState.getBlock() instanceof DoublePlantBlock) {
                                        canPlace = false;

                                        BlockPos abovePos = seedPos.above();
                                        if(world.isEmptyBlock(abovePos)) {
                                            world.setBlockAndUpdate(abovePos, seedState.setValue(DoublePlantBlock.HALF, DoubleBlockHalf.UPPER));
                                            canPlace = true;
                                        }
                                    }

                                    if(canPlace) {
                                        world.setBlockAndUpdate(seedPos, seedState);
                                        shouldDrop = false;
                                    }

                                }

							}
						}

						if(shouldDrop) {
							double x = pos.getX() + 0.5 + (dir.getStepX() * 0.7);
							double y = pos.getY() + 0.15 + (dir.getStepY() * 0.4);
							double z = pos.getZ() + 0.5 + (dir.getStepZ() * 0.7);
							ItemEntity entity = new ItemEntity(world, x, y, z, drop);
							entity.setDeltaMovement(Vec3.ZERO);
							world.addFreshEntity(entity);
						}

						return;
					}
				}
		}
	}

public void tick() {
	super.tick();

	AbstractArrow fetching = getFetching();
	if(fetching != null && (isSleeping() || fetching.level() != level() || !fetching.isAlive() || fetching.pickup == Pickup.DISALLOWED))
		setFetching(null);

	if(!level().isClientSide) {
		if(hyperfocusCooldown > 0)
			hyperfocusCooldown--;

		if(fetching != null || isSleeping() || isInSittingPose() || !isTame() || isLeashed())
			currentHyperfocus = null;
		else {
			LivingEntity owner = getOwner();

			if(currentHyperfocus != null) {
				boolean hyperfocusClear = level().getBrightness(LightLayer.BLOCK, currentHyperfocus) > 0;
				boolean ownerAbsent = owner == null
						|| (owner instanceof Player
								&& (!owner.getMainHandItem().is(SHIBA_LIGHTS) && !owner.getOffhandItem().is(SHIBA_LIGHTS)));

				if(hyperfocusClear || ownerAbsent) {
					currentHyperfocus = null;
					hyperfocusCooldown = 40;

					if(hyperfocusClear && !ownerAbsent && owner instanceof ServerPlayer sp)
						ShibaModule.shibaHelpTrigger.trigger(sp);
				}
			}

			if(currentHyperfocus == null && owner instanceof Player player && hyperfocusCooldown == 0) {
				if(player.getMainHandItem().is(SHIBA_LIGHTS) || player.getOffhandItem().is(SHIBA_LIGHTS)) {
					BlockPos ourPos = blockPosition();
					final int searchRange = 10;
					for(int i = 0; i < 20; i++) {
						BlockPos test = ourPos.offset(random.nextInt(searchRange * 2 + 1) - searchRange, random.nextInt(searchRange * 2 + 1) - searchRange, random.nextInt(searchRange * 2 + 1) - searchRange);
						if(hasLineOfSight(test.above(), searchRange)
								&& level().getBlockState(test).isAir()
								&& level().getBlockState(test.below()).isSolidRender(level(), test.below())
								&& level().getBrightness(LightLayer.BLOCK, test) == 0
								&& !(ShibaModule.ignoreAreasWithSkylight && level().canSeeSky(test))) {

							currentHyperfocus = test;
						}
					}
				}
			}
		}
	}

	if(!isSleeping() && !level().isClientSide && fetching == null && getMouthItem().isEmpty()) {
		LivingEntity owner = getOwner();
		if(owner != null) {
			AABB check = owner.getBoundingBox().inflate(2);
			List<AbstractArrow> arrows = level().getEntitiesOfClass(AbstractArrow.class, check,
					a -> a.getOwner() == owner && a.pickup != Pickup.DISALLOWED);

			if(arrows.size() > 0) {
				AbstractArrow arrow = arrows.get(level().random.nextInt(arrows.size()));
				setFetching(arrow);
			}
		}
	}
}

public boolean hurt(DamageSource source, float amount) {
    if (this.isInvulnerableTo(source)) {
        return false;
    }

    if (source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
        return super.hurt(source, amount);
    } else {
        amount = Math.min(DamageCap(), amount);
    }

    double distSqr = calculateRange(source);

    if (distSqr != -1) {
        double limit = this.RangeLimit();
        double maxLimit = limit * 1.5;

        double limitSqr = limit * limit;
        double maxLimitSqr = maxLimit * maxLimit;

        if (distSqr >= maxLimitSqr) {
            return false;
        }

        if (distSqr > limitSqr) {
            double distance = Math.sqrt(distSqr);
            float multiplier = (float) ((maxLimit - distance) / (maxLimit - limit));
            amount *= multiplier;

            if (amount <= 0) return false;
        }
    }

    float BUCKET = this.damageBucket;

    if (!source.is(ModTag.BYPASSES_HURT_TIME)) {
        float projectedBucket = damageBucket + amount;
        float limit = this.DamageCap();

        if (projectedBucket > limit) {
            float roomLeft = limit - damageBucket;

            if (roomLeft > 0) {
                amount = roomLeft;
                damageBucket = limit;
            } else {
                amount = 0.1F;
            }
        } else {
            damageBucket += amount;
        }
    }

    boolean flag = super.hurt(source, amount);

    if (flag) {
        if (source.is(ModTag.BLOCK_SELF_REGEN)) {
            self_regen = HealCooldown();
        }
    } else {
        this.damageBucket = BUCKET;
    }

    return flag;
}

public void onUpdate() {
    super.onUpdate();
    if (!world.isRemote) {
        if (getAttackTarget() != null) {
            if (this.attackDelayCounter > 0 && !this.isCasting() && getAttackTarget().getDistance(this) < 10.0D) {
                this.attackDelayCounter--;
            }
            if (this.attackDelayCounter <= 0 || this.attackCounter > 0) {
                if (getEntitySenses().canSee(getAttackTarget())) {
                    if (attackCounter == 0) {
                        if (getAttackTarget().onGround && !getAttackTarget().isRiding()) {
                            attackCounter++;
                            if (!world.isRemote) {
                                tasks.removeTask(meleeAI);
                            }
                        }
                    } else if (attackCounter < MAX_ATTACK_TIME) {
                        attackCounter++;
                        startCasting();
                        if (!world.isRemote) {
                            chargeSpell(getAttackTarget());
                        }
                    } else if (attackCounter >= MAX_ATTACK_TIME) {
                        this.attackDelayCounter = MIN_ATTACK_DELAY + this.rand.nextInt(MAX_ATTACK_DELAY - MIN_ATTACK_DELAY + 1) + 1;
                        attackCounter = 0;
                        stopCasting();
                        if (!world.isRemote) {
                            if (!getAttackTarget().isRiding()) {
                                castSpell(getAttackTarget());
                            }
                            tasks.addTask(2, meleeAI);
                        }
                    }
                }
            }
        } else if (isCasting() || attackCounter != 0) {
            if (this.attackDelayCounter <= 0) {
                this.attackDelayCounter = MIN_ATTACK_DELAY + this.rand.nextInt(MAX_ATTACK_DELAY - MIN_ATTACK_DELAY + 1) + 1;
            }
            attackCounter = 0;
            stopCasting();
        }
    }
    if (world.isRemote) {
        prevRenderYawOffset = prevRotationYaw;
        renderYawOffset = rotationYaw;
        prevAttackAnimationTime = attackAnimationTime;
        if (isCasting()) {
            if (attackAnimationTime < MAX_ATTACK_ANIMATION_TIME) {
                attackAnimationTime++;
            }
            spawnParticles();
        } else {
            if (attackAnimationTime > 0) {
                attackAnimationTime--;
            }
        }
    } else {
        if (getAttackTarget() != null) {
            faceEntity(getAttackTarget(), 100, 100);
        }
        if (teleportCooldown > 0) {
            teleportCooldown--;
        }
    }
}

public void tick() {
    if (this.targetBlock != null) {
        if (this.entity.level().getBlockEntity(this.targetBlock) != null) {
            BlockEntity blockEntity = this.entity.level().getBlockEntity(this.targetBlock);

            float accessDistance = 1.86f;

            //when approaching a chest, open it visually
            double distance = this.entity.position().distanceTo(Math3DUtil.center(this.targetBlock));

            //briefly before reaching the target, open chest, if it is one.
            if (distance < 2.5 && distance >= accessDistance && this.canSeeTarget() &&
                    blockEntity instanceof Container container) {
                this.toggleChest(container, true);
            }

            if (distance < accessDistance) {
                //stop moving while taking out
                this.entity.getNavigation().stop();
            } else {
                //continue moving
                BlockPos moveTarget = this.getMoveTarget();
                this.entity.getNavigation().moveTo(this.entity.getNavigation().createPath(moveTarget, 0), 1.0f);
            }

            //when close enough extract item
            if (distance < accessDistance && this.canSeeTarget()) {

                var blockEntityHandler = this.entity.level().getCapability(Item.BLOCK, blockEntity.getBlockPos(), blockEntity.getBlockState(), blockEntity, this.entity.getDepositFacing());
                if (blockEntityHandler == null) { //worst case scenario if block entity or entity changes since last target reset.
                    this.resetTarget();
                    return;
                }

                var entityHandler = this.entity.getCapability(Item.ENTITY);

                if (this.tryPerformStorageActuatorExtraction(blockEntityHandler, entityHandler,
                        this.entity.getFilterItem())) {
                    //if the block entity is a storage actuator we use special optimized logic that can access the internal hashmap of item storage
                } else {
                    //if not a storage actuator, just use item handler defaults
                    int slot = EntityItemFilter.getFirstMatchingSlot(this.entity.level(), blockEntityHandler, this.entity);
                    if (slot >= 0) {
                        //simulate extraction
                        ItemStack toExtract = ItemTransferUtil.extractItem(blockEntityHandler, slot, Integer.MAX_VALUE, true);
                        if (!toExtract.isEmpty()) {
                            ItemStack remaining = ItemTransferUtil.insertItem(entityHandler, toExtract, true);
                            if (remaining.getCount() < toExtract.getCount()) {
                                //if simulation went well, do for real
                                ItemStack extracted = ItemTransferUtil.extractItem(blockEntityHandler, slot, toExtract.getCount() - remaining.getCount(), false);
                                ItemTransferUtil.insertItem(entityHandler, extracted, false);
                            }
                        }
                    }
                }

                //after extracting, close chest
                if (blockEntity instanceof Container container) {
                    this.toggleChest(container, false);
                }
            }
        } else {
            this.resetTarget(); //if there is no block entity, recheck
        }
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack stack = player.getItemInHand(hand);
    boolean owner = this.isTame() && isOwnedBy(player);
    InteractionResult type = super.mobInteract(player, hand);
    if (owner) {
        Optional<InteractionResult> result = emptybucketMobPickup(player, hand, this);
        if (result.isPresent()) {
            return result.get();
        }else{
            if (!player.isShiftKeyDown()) {
                this.openCustomInventoryScreen(player);
                this.setCommand(2);
                this.setOrderedToSit(true);
                return InteractionResult.sidedSuccess(this.level().isClientSide);
            }
        }

    }


    if (!isTame() && stack.is(ModItems.LAVA_POWER_CELL.get())) {
        this.usePlayerItem(player, hand, stack);
        this.gameEvent(GameEvent.EAT);
        if (!net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, player)) {
            this.tame(player);
            this.setIsAwaken(true);
            this.setAttackState(2);
            this.level().broadcastEntityEvent(this, (byte) 7);
        } else {
            this.level().broadcastEntityEvent(this, (byte) 6);
        }
        return InteractionResult.SUCCESS;
    }


    if (isTame() && stack.is(Items.COAL) && this.getHealth() < this.getMaxHealth()) {
        this.heal(5);
        if (!player.getAbilities().instabuild) {
            stack.shrink(1);
        }

        this.gameEvent(GameEvent.EAT, this);
        return InteractionResult.SUCCESS;

    }

    InteractionResult interactionresult = stack.interactLivingEntity(player, this, hand);
    if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS && isTame() && isOwnedBy(player)) {
        if (player.isShiftKeyDown()) {
            this.setCommand(this.getCommand() + 1);
            if (this.getCommand() == 3) {
                this.setCommand(0);
            }
            player.displayClientMessage(Component.translatable("entity.cataclysm.all.command_" + this.getCommand(), this.getName()), true);
            boolean sit = this.getCommand() == 2;
            if (sit) {
                this.setOrderedToSit(true);
                return InteractionResult.SUCCESS;
            } else {
                this.setOrderedToSit(false);
                return InteractionResult.SUCCESS;
            }
        }
    }
    return type;
}

