public static void ChargeEffect(LivingEvent.LivingTickEvent event){
    LivingEntity livingEntity = event.getEntity();
    if (livingEntity != null){
        AttributeInstance speed = livingEntity.getAttribute(Attributes.MOVEMENT_SPEED);
        AttributeInstance attack = livingEntity.getAttribute(Attributes.ATTACK_DAMAGE);

        MobEffectInstance chargeInstance = livingEntity.getEffect(GoetyEffects.CHARGED.get());
        boolean notNull = chargeInstance != null;
        boolean flag = notNull && chargeInstance.getAmplifier() < 1;
        boolean flag2 = notNull && chargeInstance.getAmplifier() >= 1;
        if (attack != null && speed != null) {
            if (notNull) {
                if (flag) {
                    if (speed.hasModifier(CHARGE_MOAR_SPEED_MOD)){
                        speed.removeModifier(CHARGE_MOAR_SPEED_MOD);
                    }
                    if (attack.hasModifier(CHARGE_BAD_ATTACK_MOD)){
                        attack.removeModifier(CHARGE_BAD_ATTACK_MOD);
                    }
                    if (!speed.hasModifier(CHARGE_SPEED_MOD)) {
                        speed.addPermanentModifier(CHARGE_SPEED_MOD);
                    }
                    if (!attack.hasModifier(CHARGE_ATTACK_MOD)) {
                        attack.addPermanentModifier(CHARGE_ATTACK_MOD);
                    }
                } else if (flag2) {
                    if (speed.hasModifier(CHARGE_SPEED_MOD)){
                        speed.removeModifier(CHARGE_SPEED_MOD);
                    }
                    if (attack.hasModifier(CHARGE_ATTACK_MOD)){
                        attack.removeModifier(CHARGE_ATTACK_MOD);
                    }
                    if (!speed.hasModifier(CHARGE_MOAR_SPEED_MOD)) {
                        speed.addPermanentModifier(CHARGE_MOAR_SPEED_MOD);
                    }
                    if (!attack.hasModifier(CHARGE_BAD_ATTACK_MOD)) {
                        attack.addPermanentModifier(CHARGE_BAD_ATTACK_MOD);
                    }
                }
            } else {
                if (speed.hasModifier(CHARGE_SPEED_MOD)){
                    speed.removeModifier(CHARGE_SPEED_MOD);
                }
                if (attack.hasModifier(CHARGE_ATTACK_MOD)){
                    attack.removeModifier(CHARGE_ATTACK_MOD);
                }
                if (speed.hasModifier(CHARGE_MOAR_SPEED_MOD)) {
                    speed.removeModifier(CHARGE_MOAR_SPEED_MOD);
                }
                if (attack.hasModifier(CHARGE_BAD_ATTACK_MOD)) {
                    attack.removeModifier(CHARGE_BAD_ATTACK_MOD);
                }
            }
        }
        if (notNull){
            if (chargeInstance.getAmplifier() >= 2 && livingEntity.hurtTime > 0){
                livingEntity.removeEffect(chargeInstance.getEffect());
            } else {
                if (livingEntity.tickCount % 20 == 0){
                    if (livingEntity.level instanceof ServerLevel serverLevel){
                        ServerParticleUtil.addParticlesAroundSelf(serverLevel, ModParticleTypes.ELECTRIC.get(), livingEntity);
                    }
                }
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        if (staff.is(ModItems.NAMELESS_STAFF.get())){
            Vec3 vec3 = caster.position();
            Direction direction = caster.getDirection();
            double stepX = direction.getStepX();
            double stepZ = direction.getStepZ();
            for (int i1 = -3; i1 <= 3; ++i1) {
                BlackguardServant summonedentity = new BlackguardServant(ModEntityType.BLACKGUARD_SERVANT.get(), worldIn);
                summonedentity.setTrueOwner(caster);
                Vec3 vec32 = new Vec3(((2 * stepX) + (i1 * stepZ)) + vec3.x(), vec3.y(), ((2 * stepZ) + (i1 * stepX)) + vec3.z());
                if (!worldIn.noCollision(summonedentity, summonedentity.getBoundingBox().move(vec32))){
                    vec32 = Vec3.atCenterOf(BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, caster.level));
                }
                summonedentity.setPos(vec32);
                MobUtil.moveDownToGround(summonedentity);
                summonedentity.setPersistenceRequired();
                summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
                this.buffSummon(caster, summonedentity, potency);
                summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                summonedentity.setYHeadRot(caster.getYHeadRot());
                summonedentity.setYRot(caster.getYRot());
                this.SummonSap(caster, summonedentity);
                this.setTarget(caster, summonedentity);
                if (worldIn.addFreshEntity(summonedentity)) {
                    this.namelessSummon(worldIn, caster, staff, summonedentity);
                }
                this.summonAdvancement(caster, summonedentity);
            }
        } else {
            int i = 1;
            if (rightStaff(staff)){
                i = 2 + caster.level.random.nextInt(6);
            } else if (staff.is(ModItems.OMINOUS_STAFF.get())) {
                i = 2;
            }
            for (int i1 = 0; i1 < i; ++i1) {
                BlackguardServant summonedentity = new BlackguardServant(ModEntityType.BLACKGUARD_SERVANT.get(), worldIn);
                if (staff.is(ModItems.OMINOUS_STAFF.get())) {
                    summonedentity = new ZombieRoyalGuardServant(ModEntityType.BLACKGUARD_VARIANT_SERVANT.get(), worldIn);
                }
                summonedentity.setTrueOwner(caster);
                summonedentity.moveTo(BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn), 0.0F, 0.0F);
                MobUtil.moveDownToGround(summonedentity);
                summonedentity.setPersistenceRequired();
                summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
                this.buffSummon(caster, summonedentity, potency);
                summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                this.SummonSap(caster, summonedentity);
                this.setTarget(caster, summonedentity);
                if (worldIn.addFreshEntity(summonedentity)) {
                    this.uponSummon(worldIn, caster, staff, summonedentity);
                }
                this.summonAdvancement(caster, summonedentity);
            }
        }
        this.SummonDown(caster);
        this.playSound(worldIn, caster, ModSounds.VANGUARD_SUMMON.get());
    }
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
