		final List<Integer> already = new ArrayList<>(Ints.asList(tag.getIntArray("Pages")));
		if (!already.contains(EnumPaleoPages.SARAHSAURUS.ordinal())) {
			EnumPaleoPages.addPage(EnumPaleoPages.fromInt(EnumPaleoPages.SARAHSAURUS.ordinal()), itemstack);
			player.displayClientMessage(Component.translatable("paleopedia.sarahsaurus_added"), true);
			return InteractionResult.SUCCESS;
		} else {
			player.displayClientMessage(Component.translatable("paleopedia.sarahsaurus_already_added"), true);
			return InteractionResult.SUCCESS;
		}
	}
	if (this.level().isClientSide()) {
		boolean flag = this.isOwnedBy(player) || this.isTame() || this.isFood(itemstack) && !this.isTame();
		return flag ? InteractionResult.CONSUME : InteractionResult.PASS;
	} else {
		if (this.getOwner() == player) {
			if (this.isTame()) {
				if (this.isFood(itemstack)) {
					if (this.getHealth() < this.getMaxHealth()) {
						if (!player.getAbilities().instabuild) {
							itemstack.shrink(1);
						}
						this.heal((float)item.getFoodProperties().getNutrition());
						return InteractionResult.SUCCESS;
					} else {
						if (this.canFallInLove()) {
							this.setInLove(player);
							if (!player.isCreative()) {
								itemstack.shrink(1);
							}
						}
					}
				} 
				if (item.equals(Items.AIR)) this.openCustomInventoryScreen(player);
				if (!this.hasChest() && itemstack.is(Items.CHEST)) {
					this.equipChest(player, itemstack);
					return InteractionResult.sidedSuccess(this.level().isClientSide());
				}
				if (this.isCarpet(itemstack) && !this.isWearingCarpet()) {
					this.equipCarpet(player, itemstack);
					return InteractionResult.sidedSuccess(this.level().isClientSide());
				}
			}
		} else {
			if (this.isFood(itemstack)) {
				if (!player.getAbilities().instabuild) {
					itemstack.shrink(1);
				}
				if (this.random.nextInt(3) == 0 && !net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, player)) {
					this.tame(player);
					this.navigation.stop();
					this.setTarget((LivingEntity)null);
					this.level().broadcastEntityEvent(this, (byte)7);
				} else {
					this.level().broadcastEntityEvent(this, (byte)6);
				}

				return InteractionResult.SUCCESS;
			}
		}
	}
	return super.mobInteract(player, hand);
}

	public static void serverTick(Level level, BlockPos pos, BlockState state, ChillboxBlockEntity chillbox) {
		boolean isLit = chillbox.isLit();
		boolean changed = false;
		if (chillbox.isLit()) {
			chillbox.chillTime--;
		}

		ItemStack fuelStack = chillbox.items.get(0);
		ItemStack inputStack = chillbox.items.get(1);
		boolean hasInputs = !inputStack.isEmpty();
		boolean hasFuel = !fuelStack.isEmpty();
		if (chillbox.isLit() || hasFuel && hasInputs) {

			int i = chillbox.getMaxStackSize();
			if (!chillbox.isLit() && canChill(level.registryAccess(), chillbox.items, i, chillbox)) {
				chillbox.chillTime = chillbox.getChillDuration(fuelStack);
				chillbox.chillDuration = chillbox.chillTime;
				if (chillbox.isLit()) {
					changed = true;
					if (fuelStack.hasCraftingRemainingItem())
						chillbox.items.set(1, fuelStack.getCraftingRemainingItem());
					else if (hasFuel) {
						fuelStack.shrink(1);
						if (fuelStack.isEmpty()) {
							chillbox.items.set(1, fuelStack.getCraftingRemainingItem());
						}
					}
				}
			}

			if (chillbox.isLit() && canChill(level.registryAccess(), chillbox.items, i, chillbox)) {
				chillbox.cookingProgress++;
				if (chillbox.cookingProgress == chillbox.cookingTotalTime) {
					chillbox.cookingProgress = 0;
					chillbox.cookingTotalTime = getTotalCookTime(level, chillbox);
					if (chill(level.registryAccess(), chillbox.items, i, chillbox)) {
						for (int index = 1; index <= 6; index++) {
							ItemStack stack = chillbox.items.get(index);
							if (stack.hasCraftingRemainingItem()) {
								ejectIngredientRemainder(level, pos.above(), state, stack.getCraftingRemainingItem());
							}
							if (!stack.isEmpty()) {
								stack.shrink(1);
							}
						}
					}

					changed = true;
				}
			} else {
				chillbox.cookingProgress = 0;
			}
		} else if (!chillbox.isLit() && chillbox.cookingProgress > 0) {
			chillbox.cookingProgress = Mth.clamp(chillbox.cookingProgress - 2, 0, chillbox.cookingTotalTime);
		}

		if (isLit != chillbox.isLit()) {
			changed = true;
//			state = state.setValue(AbstractFurnaceBlock.LIT, chillbox.isLit());
//			level.setBlock(pos, state, 3);
		}

		if (changed) {
			setChanged(level, pos, state);
			chillbox.setChanged();
		}
	}

public void directFromPlayer(float rotationYaw, float rotationPitch, boolean loadChunk, Entity over) {
    final Entity owner = this.getOwner();
    if (owner != null && this.distanceTo(owner) > 150) {
        returnControlTime = 100;
    }
    if (Math.abs(xo - this.getX()) > 0.1F || Math.abs(yo - this.getY()) > 0.1F || Math.abs(zo - this.getZ()) > 0.1F) {
        stillTicksCounter = 0;
    } else {
        stillTicksCounter++;
    }
    int stillTPthreshold = AMConfig.falconryTeleportsBack ? 200 : 6000;
    this.setOrderedToSit(false);
    this.setLaunched(true);
    if (owner != null && (returnControlTime > 0 && AMConfig.falconryTeleportsBack || stillTicksCounter > stillTPthreshold && this.distanceTo(owner) > 30)) {
        this.copyPosition(owner);
        returnControlTime = 0;
        stillTicksCounter = 0;
        launchTime = Math.max(launchTime, 12000);
    }
    if (!this.level().isClientSide) {
        if (returnControlTime > 0 && owner != null) {
            this.getLookControl().setLookAt(owner, 30, 30);
        } else {
            this.yBodyRot = rotationYaw;
            this.setYRot(rotationYaw);
            this.yHeadRot = rotationYaw;
            this.setXRot(rotationPitch);
        }
        if (rotationPitch < 10 && this.onGround()) {
            this.setFlying(true);
        }
        final float yawOffset = rotationYaw + 90;
        final float rad = 3F;
        final float speed = 1.2F;
        if (returnControlTime > 0) {
            this.getMoveControl().setWantedPosition(owner.getX(), owner.getY() + 10, owner.getZ(), speed);
        } else {
            this.getMoveControl().setWantedPosition(this.getX() + rad * 1.5F * Math.cos(yawOffset * Mth.DEG_TO_RAD), this.getY() - rad * Math.sin(rotationPitch * Mth.DEG_TO_RAD), this.getZ() + rad * Math.sin(yawOffset * Mth.DEG_TO_RAD), speed);
        }
        if (loadChunk) {
            loadChunkOnServer(this.blockPosition());
        }
        this.setLastHurtByMob(null);
        this.setTarget(null);
        if (over == null) {
            final List<Entity> list = this.level().getEntities(this, this.getBoundingBox().inflate(3.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR);
            Entity closest = null;
            for (final Entity e : list) {
                if (closest == null || this.distanceTo(e) < this.distanceTo(closest)) {
                    closest = e;
                }
            }
            over = closest;
        }
    }
    if (over != null && over != owner && !this.isAlliedTo(over) && canFalconryAttack(over)) {
        if (tackleCapCooldown == 0 && this.distanceTo(over) <= over.getBbWidth() + 4D) {
            this.setTackling(true);
            if (this.distanceTo(over) <= over.getBbWidth() + 2D) {
                final float speedDamage = (float) Math.ceil(Mth.clamp(this.getDeltaMovement().length() + 0.2, 0, 1.2D) * 3.333);
                over.hurt(this.damageSources().mobAttack(this), 5 + speedDamage + random.nextInt(2));
                tackleCapCooldown = 22;
            }
        }
    }
    this.lastPlayerControlTime = 10;
    this.controlledFlag = true;
}

public void tick() {
    super.tick();
    prevBurrowProgress = burrowProgress;
    prevDanceProgress = danceProgress;
    prevAttackProgress = attackProgress;
    prevStanceProgress = stanceProgress;

    if (this.isBurrowed()) {
        if (burrowProgress < 5F)
            burrowProgress += 0.5F;
    } else {
        if (burrowProgress > 0F)
            burrowProgress -= 0.5F;
    }

    if (this.burrowCooldown > 0) {
        this.burrowCooldown--;
    }

    if (this.getStanceTime() > 0) {
        this.setStanceTime(this.getStanceTime() - 1);
        if (this.stanceProgress < 5F) {
            this.stanceProgress++;
        }
    } else {
        if (this.stanceProgress > 0F) {
            this.stanceProgress--;
        }
    }

    if (this.getAttackTime() > 0) {
        this.setAttackTime(this.getAttackTime() - 1);
        if (this.attackProgress < 5F) {
            this.attackProgress += 2.5F;
        }
    } else {
        if (this.attackProgress > 0F) {
            this.attackProgress -= 0.5F;
        }
    }

    boolean dancing = this.getDanceTime() > 0 || this.isJukeboxing;
    if (dancing) {
        if (this.danceProgress < 5F) {
            this.danceProgress++;
        }
    } else {
        if (this.danceProgress > 0F) {
            this.danceProgress--;
        }
    }

    if (this.getDanceTime() > 0) {
        this.setBurrowed(false);
        this.setDanceTime(this.getDanceTime() - 1);
        if(this.getDanceTime() == 1 && weatherCooldown <= 0 && level().getGameRules().getBoolean(GameRules.RULE_WEATHER_CYCLE)){
            changeWeather();
        }
    }
    if(weatherCooldown > 0){
        weatherCooldown--;
    }
    if (this.jukeboxPosition == null || !this.jukeboxPosition.closerToCenterThan(this.position(), 15) || !this.level().getBlockState(this.jukeboxPosition).is(Blocks.JUKEBOX)) {
        this.isJukeboxing = false;
        this.setDanceTime(0);
        this.jukeboxPosition = null;
    }
}

public void tick() {
    LivingEntity target = hawk.getTarget();
    boolean paralized = target != null && target.getMobType() == MobType.ARTHROPOD && !target.noPhysics && target.hasEffect(AMEffectRegistry.DEBILITATING_STING.get());
    boolean paralizedWithChild = paralized && target.getEffect(AMEffectRegistry.DEBILITATING_STING.get()).getAmplifier() > 0;
    if (sandPos == null || !level().getBlockState(sandPos).is(BlockTags.SAND)) {
        sandPos = hawk.genSandPos(target.blockPosition());
    }
    if (orbitCooldown > 0) {
        orbitCooldown--;
        hawk.setFlying(true);
        if (target != null) {
            if (orbitVec == null || hawk.distanceToSqr(orbitVec) < 4F || !hawk.getMoveControl().hasWanted()) {
                orbitVec = hawk.getOrbitVec(target.position().add(0, target.getBbHeight(), 0), 10 + random.nextInt(2), false);
                if (orbitVec != null) {
                    hawk.getMoveControl().setWantedPosition(orbitVec.x, orbitVec.y, orbitVec.z, 1F);
                }
            }
        }
    } else if (((paralized && !hawk.isTame()) || (paralizedWithChild && hawk.bredBuryFlag)) && sandPos != null) {
        if (hawk.onGround()) {
            hawk.setFlying(false);
            hawk.getNavigation().moveTo(target, 1);
        } else {
            Vec3 vector3d = hawk.getBlockGrounding(hawk.position());
            if (vector3d != null && hawk.isFlying()) {
                hawk.getMoveControl().setWantedPosition(vector3d.x, vector3d.y, vector3d.z, 1F);
            }
        }
        if (hawk.distanceTo(target) < target.getBbWidth() + 1.5F && !target.isPassenger()) {
            hawk.setDragging(true);
            hawk.setFlying(false);
            target.startRiding(hawk, true);
        }
    } else {
        if (target != null && !paralizedWithChild) {
            double dist = hawk.distanceTo(target);
            if (dist < 10 && !hawk.isFlying()) {
                if (hawk.onGround()) {
                    hawk.setFlying(false);
                }
                hawk.getNavigation().moveTo(target, 1);
            } else {
                hawk.setFlying(true);
                hawk.getMoveControl().setWantedPosition(target.getX(), target.getEyeY(), target.getZ(), 1F);
            }
            if (dist < target.getBbWidth() + 2.5F) {
                if (hawk.entityData.get(ATTACK_TICK) == 0 && hawk.attackProgress == 0) {
                    hawk.entityData.set(ATTACK_TICK, 7);
                }
                if (hawk.attackProgress == 5F) {
                    hawk.doHurtTarget(target);
                    if(hawk.bredBuryFlag){
                        if(target.getHealth() <= 1.0F){
                            target.heal(5);
                        }
                    }
                    target.addEffect(new MobEffectInstance(AMEffectRegistry.DEBILITATING_STING.get(), target.getMobType() == MobType.ARTHROPOD ? EntityTarantulaHawk.STING_DURATION : 600, hawk.bredBuryFlag ? 1 : 0));
                    if (!hawk.level().isClientSide && target.getMobType() == MobType.ARTHROPOD) {
                        AlexsMobs.sendMSGToAll(new MessageTarantulaHawkSting(hawk.getId(), target.getId()));
                    }
                    orbitCooldown = target.getMobType() == MobType.ARTHROPOD ? 200 + random.nextInt(200) : 10 + random.nextInt(20);
                }
            }
        }
    }


}

public void onUpdate() {
	if (!this.world.isRemote && this.world.getDifficulty() == EnumDifficulty.PEACEFUL) {
		this.isDead = true;
	}

	if(this.attackCooldown > 0) {
		this.attackCooldown--;
	}

	this.prevSquishFactor = this.squishFactor;
	this.squishFactor += (this.squishAmount - this.squishFactor) * 0.5F;

	if (!this.world.isRemote) {
		if (getIsPlayerNearby(7, 3, 7, 7) || getAttackTarget() != null || this.world.rand.nextInt(2200) == 0) {
			if (!this.isActive()) {
				this.setActive(true);
				this.motionY += 0.6;
			}
		}

		if(this.isActive()) {
			if(this.getEntityAttribute(SLUDGE_TRAIL).getAttributeValue() == 1 && this.world.getClosestPlayer(this.posX, this.posY, this.posZ, 16, false) != null) {
				BlockPos position = new BlockPos(this.posX, this.posY, this.posZ);;
				if (this.world.isAirBlock(position)) {
					this.createTrail(position);
				}
			}

			if (this.getAttackTarget() == null && this.onGround && this.world.rand.nextInt(350) == 0 && !this.isInWater() && this.canHideIn(this.world.getBlockState(this.getPosition().down()))) {
				this.setActive(false);
			}
		} else if(this.isInWater() || !this.onGround) {
			this.setActive(true);
		} else {
			this.motionX = 0;
			this.motionY -= 0.1;
			this.motionZ = 0;
		}
	}

	super.onUpdate();

	if(this.isActive()) {
		this.setNormalSize();
	} else {
		this.setSmallSize();
	}

	if (this.onGround && !this.wasOnGround) {
		//Particles
		this.squishAmount = -0.5F;
	} else if (!this.onGround && this.wasOnGround) {
		this.squishAmount = 1.0F;
	}

	this.wasOnGround = this.onGround;
	this.alterSquishAmount();

	//Update animation
	if (this.world.isRemote) {
		this.scale.updateTimer();
		if (this.isActive()) {
			this.scale.increaseTimer();
		} else {
			this.scale.decreaseTimer();
		}
	}
}

    public void mountAbility(Entity rider) {
        if(this.getEntityWorld().isRemote)
            return;

        if(this.abilityToggled)
            return;

        if(this.hasPickupEntity()) {
            this.dropPickupEntity();
            return;
        }

        if(this.getStamina() < this.getStaminaCost())
            return;

        if(rider instanceof EntityPlayer) {
            EntityPlayer player = (EntityPlayer)rider;
            // Type:
            List<EntityProjectileRapidFire> projectiles = new ArrayList<EntityProjectileRapidFire>();

            EntityProjectileRapidFire projectileEntry = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), player, 15, 3);
            projectiles.add(projectileEntry);

			EntityProjectileRapidFire projectileEntry2 = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), this, 15, 3);
			projectileEntry2.offsetX += 1.0D;
			projectileEntry2.setProjectileScale(0.25f);
			projectiles.add(projectileEntry2);

			EntityProjectileRapidFire projectileEntry3 = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), this, 15, 3);
			projectileEntry3.offsetX -= 1.0D;
			projectileEntry3.setProjectileScale(0.25f);
			projectiles.add(projectileEntry3);

			EntityProjectileRapidFire projectileEntry4 = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), this, 15, 3);
			projectileEntry4.offsetZ += 1.0D;
			projectileEntry4.setProjectileScale(0.25f);
			projectiles.add(projectileEntry4);

			EntityProjectileRapidFire projectileEntry5 = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), this, 15, 3);
			projectileEntry5.offsetZ -= 1.0D;
			projectileEntry5.setProjectileScale(0.25f);
			projectiles.add(projectileEntry5);

			EntityProjectileRapidFire projectileEntry6 = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), this, 15, 3);
			projectileEntry6.offsetY += 1.0D;
			projectileEntry6.setProjectileScale(0.25f);
			projectiles.add(projectileEntry6);

			EntityProjectileRapidFire projectileEntry7 = new EntityProjectileRapidFire(EntityScorchfireball.class, this.getEntityWorld(), this, 15, 3);
			projectileEntry7.offsetY -= 10D;
			projectileEntry7.setProjectileScale(0.25f);
			projectiles.add(projectileEntry7);

            for(EntityProjectileRapidFire projectile : projectiles) {
                projectile.setProjectileScale(1f);

                // Y Offset:
                projectile.posY -= this.height / 4;

                // Launch:
                this.playSound(projectile.getLaunchSound(), 1.0F, 1.0F / (this.getRNG().nextFloat() * 0.4F + 0.8F));
                this.getEntityWorld().spawnEntity(projectile);
            }
            this.triggerAttackCooldown();
        }

        this.applyStaminaCost();
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
    int range = spellStat.getRange();
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    float chance = 0.05F;
    int cooldown = this.defaultSpellCooldown();
    if (WandUtil.enchantedFocus(caster)) {
        range += WandUtil.getRangeLevel(caster);
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
    }
    if (this.rightStaff(staff)){
        chance += 0.2F;
    }
    HitResult rayTraceResult = this.rayTrace(worldIn, caster, range, 3);
    LivingEntity target = this.getTarget(caster, range);
    EntityType<? extends AbstractMonolith> entityType = ModEntityType.TOTEMIC_WALL.get();
    if (this.typeStaff(staff, SpellType.FROST)){
        entityType = ModEntityType.GLACIAL_WALL.get();
    }
    if (target != null){
        if (this.isShifting(caster)){
            if (worldIn.getRandom().nextFloat() <= chance){
                WandUtil.summonQuadOffensiveTrap(caster, target, ModEntityType.TOTEMIC_BOMB.get(), potency);
                cooldown += MathHelper.secondsToTicks(3);
            } else {
                int xShift = worldIn.getRandom().nextInt(-1, 1);
                int zShift = worldIn.getRandom().nextInt(-1, 1);
                WandUtil.summonMonolith(caster, target, ModEntityType.TOTEMIC_BOMB.get(), xShift, zShift, potency);
                cooldown += MathHelper.secondsToTicks(2);
            }
        } else {
            int random = worldIn.random.nextInt(3);
            if (random == 0) {
                int[] rowToRemove = Util.getRandom(WandUtil.CONFIG_1_ROWS, caster.getRandom());
                Direction direction = Direction.fromYRot(target.getYHeadRot());
                switch (direction){
                    case NORTH -> rowToRemove = WandUtil.CONFIG_1_NORTH_ROW;
                    case SOUTH -> rowToRemove = WandUtil.CONFIG_1_SOUTH_ROW;
                    case WEST -> rowToRemove = WandUtil.CONFIG_1_WEST_ROW;
                    case EAST -> rowToRemove = WandUtil.CONFIG_1_EAST_ROW;
                }
                WandUtil.summonSquareTrap(caster, target, entityType, rowToRemove, duration);
            } else if (random == 1){
                WandUtil.summonWallTrap(caster, target, entityType, duration);
            } else {
                WandUtil.summonRandomPillarsTrap(caster, target, entityType, duration);
            }
        }
    } else if (rayTraceResult instanceof BlockHitResult){
        BlockPos blockPos = ((BlockHitResult) rayTraceResult).getBlockPos();
        if (this.isShifting(caster)){
            if (worldIn.random.nextFloat() <= chance){
                WandUtil.summonQuadOffensiveTrap(caster, blockPos, ModEntityType.TOTEMIC_BOMB.get(), potency);
                cooldown += MathHelper.secondsToTicks(3);
            } else {
                WandUtil.summonMonolith(caster, blockPos, ModEntityType.TOTEMIC_BOMB.get(), 0, 0, potency);
                cooldown += MathHelper.secondsToTicks(2);
            }
        } else {
            WandUtil.summonWallTrap(caster, blockPos, entityType, duration);
        }
    }
    if (caster instanceof Player player) {
        cooldown *= (int) ModAttributes.getCooldownDiscount(caster);
        SEHelper.addSpellCooldown(player, this, cooldown);
    }
}

public void tick() {
	super.tick();

	if (!this.level().isClientSide) {
		AttributeInstance knockbackResistance = this.getAttribute(Attributes.KNOCKBACK_RESISTANCE);
		if (knockbackResistance != null) {
			boolean noPassengers = this.getPassengers().isEmpty();
			boolean hasModifier = knockbackResistance.hasModifier(CAUGHT_KNOCKBACK_RESISTANCE);
			if (noPassengers && hasModifier || this.isBaby()) {
				knockbackResistance.removeModifier(CAUGHT_KNOCKBACK_RESISTANCE);
			} else if (!noPassengers && !hasModifier) {
				knockbackResistance.addTransientModifier(CAUGHT_KNOCKBACK_RESISTANCE);
			}
		}

		if (!this.isBaby()) {
			if (this.flyCooldown > 0) this.flyCooldown--;

			if (this.isFlying()) {
				this.ticksFlown++;

				if (this.isGrounded()) {
					this.setFlying(false);
				}
			} else {
				this.ticksFlown = 0;
			}

			if (this.random.nextFloat() < 0.005F && this.idleDelay <= 0 && !this.isFlying() && this.getTarget() == null && this.isNoEndimationPlaying()) {
				NetworkUtil.setPlayingAnimation(this, this.random.nextFloat() < 0.6F ? EEPlayableEndimations.GLIDER_EETLE_FLAP : EEPlayableEndimations.GLIDER_EETLE_MUNCH);
				this.resetIdleFlapDelay();
			}
		}

		if (this.isGrounded()) {
			this.groundedTimer--;
			if (this.groundedTimer <= 0) {
				this.groundedAttacker = null;
			}
		}
		if (this.isDiving()) {
			this.setDiving(false);
		}
	} else {
		if (!this.isBaby()) {
			TimedEndimation takeoff = this.takeoffEndimation;
			takeoff.tick();
			if (takeoff.isMaxed()) {
				this.takeoffMoving = true;
				takeoff.setDecrementing(true);
			} else {
				if (this.takeoffMoving) {
					this.takeoffMoving = takeoff.getTick() > 15;
				} else {
					takeoff.setDecrementing(!this.isFlying());
				}
			}
			TimedEndimation flying = this.flyingEndimation;
			flying.tick();
			boolean moving = this.isMoving();
			flying.setDecrementing(!moving);
			this.wingFlapSpeed += moving ? (0.5F - this.wingFlapSpeed) * 0.1F : (0.125F - this.wingFlapSpeed) * 0.2F;
			this.prevWingFlap = this.wingFlap;
			this.wingFlap += this.wingFlapSpeed;
		}
		this.flyingRotations.tick(this.getTargetFlyingRotations());
	}
}

public void tick() {
    LivingEntity target = luxtructosaurus.getTarget();
    if (target != null && target.isAlive()) {
        double distance = luxtructosaurus.distanceTo(target);
        double attackDistance = luxtructosaurus.getBbWidth() + target.getBbWidth();
        boolean farFlag = false;
        if (this.luxtructosaurus.getAnimation() == SauropodBaseEntity.ANIMATION_SPEW_FLAMES || this.luxtructosaurus.getAnimation() == SauropodBaseEntity.ANIMATION_LEFT_KICK || this.luxtructosaurus.getAnimation() == SauropodBaseEntity.ANIMATION_RIGHT_KICK || this.luxtructosaurus.getAnimation() == SauropodBaseEntity.ANIMATION_LEFT_WHIP || this.luxtructosaurus.getAnimation() == SauropodBaseEntity.ANIMATION_RIGHT_WHIP) {
            luxtructosaurus.turningFast = true;
            Vec3 vec3 = target.position().subtract(luxtructosaurus.position());
            this.luxtructosaurus.yBodyRot = Mth.approachDegrees(luxtructosaurus.yBodyRot, -((float) Mth.atan2(vec3.x, vec3.z)) * (180F / (float) Math.PI), 15);
            this.luxtructosaurus.yBodyRotO = this.luxtructosaurus.yBodyRot;
            this.luxtructosaurus.getLookControl().setLookAt(target.getX(), target.getEyeY(), target.getZ());
        } else {
            luxtructosaurus.turningFast = false;
        }
        if (distance > attackDistance) {
            this.luxtructosaurus.getNavigation().moveTo(target, 1.0D);
        }
        if (this.luxtructosaurus.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
            if (distance < attackDistance + 4.0D) {
                float random = this.luxtructosaurus.getRandom().nextFloat();
                if (random < 0.33 && this.luxtructosaurus.onGround()) {
                    this.luxtructosaurus.setAnimation(LuxtructosaurusEntity.ANIMATION_STOMP);
                    this.luxtructosaurus.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_ATTACK_STOMP.get(), 3.0F, this.luxtructosaurus.getVoicePitch());
                } else if (random < 0.66 && distance < attackDistance + 1.0D) {
                    this.luxtructosaurus.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_KICK.get(), 3.0F, this.luxtructosaurus.getVoicePitch());
                    this.luxtructosaurus.setAnimation(this.luxtructosaurus.getRandom().nextBoolean() ? LuxtructosaurusEntity.ANIMATION_LEFT_KICK : LuxtructosaurusEntity.ANIMATION_RIGHT_KICK);
                } else {
                    this.luxtructosaurus.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_TAIL.get(), 3.0F, this.luxtructosaurus.getVoicePitch());
                    this.luxtructosaurus.setAnimation(this.luxtructosaurus.getRandom().nextBoolean() ? LuxtructosaurusEntity.ANIMATION_RIGHT_WHIP : LuxtructosaurusEntity.ANIMATION_LEFT_WHIP);
                }
            } else {
                farFlag = true;
                if (luxtructosaurus.isEnraged() && flamesCooldown == 0) {
                    flamesCooldown = 200 + luxtructosaurus.getRandom().nextInt(300);
                    this.luxtructosaurus.setAnimation(SauropodBaseEntity.ANIMATION_SPEW_FLAMES);
                }
            }
            int roarRandomChance = farFlag ? 90 : 150;
            if (luxtructosaurus.isEnraged()) {
                roarRandomChance += 200;
            }
            if ((roarCooldown == 0 &&  this.luxtructosaurus.getRandom().nextInt(roarRandomChance) == 0 || !luxtructosaurus.isEnraged() && luxtructosaurus.getHealth() < luxtructosaurus.getMaxHealth() * 0.25F)) {
                roarCooldown = 100 + luxtructosaurus.getRandom().nextInt(200);
                this.luxtructosaurus.setAnimation(SauropodBaseEntity.ANIMATION_ROAR);
                this.luxtructosaurus.enragedFor = 500 + luxtructosaurus.getRandom().nextInt(200);
                this.luxtructosaurus.setEnraged(true);
            }
        }
        if (successfulJumpCooldown <= 0 && navigationCheckCooldown-- < 0 && (luxtructosaurus.onGround() || luxtructosaurus.isInLava())) {
            navigationCheckCooldown = 20 + luxtructosaurus.getRandom().nextInt(40);
            if (!canReach(target) && this.luxtructosaurus.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                this.luxtructosaurus.setAnimation(LuxtructosaurusEntity.ANIMATION_JUMP);
                this.luxtructosaurus.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_JUMP.get(), 5.0F, this.luxtructosaurus.getVoicePitch());
                this.luxtructosaurus.jumpTarget = target.position();
                successfulJumpCooldown = 100 + luxtructosaurus.getRandom().nextInt(200);
            }
        }
    }
    if (flamesCooldown > 0) {
        flamesCooldown--;
    }
    if (roarCooldown > 0) {
        roarCooldown--;
    }
    if (successfulJumpCooldown > 0) {
        successfulJumpCooldown--;
    }
}

public void tick() {
    super.tick();
    prevJostleProgress = jostleProgress;
    prevJostleAngle = this.getJostleAngle();

    if (this.isJostling()) {
        if (jostleProgress < 5F)
            jostleProgress++;
    } else {
        if (jostleProgress > 0F)
            jostleProgress--;
    }

    if (jostleCooldown > 0) {
        jostleCooldown--;
    }
    if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && getRandom().nextInt(120) == 0 && (this.getTarget() == null || !this.getTarget().isAlive()) && !this.isJostling() && this.getJostlingPartnerUUID() == null) {
        if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
            this.setAnimation(ANIMATION_EAT_GRASS);
        }
    }
    if (timeUntilAntlerDrop > 0) {
        timeUntilAntlerDrop--;
    }
    if (timeUntilAntlerDrop == 0) {
        if (this.isAntlered()) {
            this.setAntlered(false);
            this.spawnAtLocation(new ItemStack(AMItemRegistry.MOOSE_ANTLER.get()));
            timeUntilAntlerDrop = 2 * DAY + this.random.nextInt(3) * DAY;
        } else {
            this.setAntlered(true);
            timeUntilAntlerDrop = 7 * DAY + this.random.nextInt(3) * DAY;
        }
    }
    if (this.getTarget() != null && this.getTarget().isAlive()) {
        if (this.isJostling()) {
            this.setJostling(false);
        }
        if (!this.level().isClientSide && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 8) {
            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
            if (!isAntlered()) {
                dmg = 3;
            }
            if (this.getTarget() instanceof Wolf || this.getTarget() instanceof EntityOrca) {
                dmg = 2;
            }
            getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), dmg);
        }
    }
    if(snowTimer > 0){
        snowTimer--;
    }
    if (snowTimer == 0 && !this.level().isClientSide) {
        snowTimer = 200 + random.nextInt(400);
        if(this.isSnowy()){
            if(!permSnow){
                if (!this.level().isClientSide || this.getRemainingFireTicks() > 0 || this.isInWaterOrBubble() || !EntityGrizzlyBear.isSnowingAt(level(), this.blockPosition().above())) {
                    this.setSnowy(false);
                }
            }
        }else{
            if (!this.level().isClientSide && EntityGrizzlyBear.isSnowingAt(level(), this.blockPosition())) {
                this.setSnowy(true);
            }
        }
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void onTeleport(ZEntityTeleport event) {
	if(!enableMyaliteViaducts)
		return;

	Entity entity = event.getEntity();
	Level world = entity.level();
	BlockPos pos = BlockPos.containing(event.getTargetX(), event.getTargetY(), event.getTargetZ());

	if(!world.isLoaded(pos)) //ex. using /tp to teleport very far away; this function will block until the chunks are generated
		return;

	List<BlockPos> myalite = getAdjacentMyalite(null, world, pos, null);

	if(myalite == null || myalite.isEmpty()) {
		pos = pos.below();
		myalite = getAdjacentMyalite(null, world, pos, null);
	}

	if(myalite == null || myalite.isEmpty()) {
		pos = pos.relative(event.getEntity().getDirection());
		myalite = getAdjacentMyalite(null, world, pos, null);
	}

	if(myalite != null && !myalite.isEmpty()) {
		BlockPos prev;
		BlockPos cond = pos;

		List<BlockPos> found = new ArrayList<>();
		int moves = 0;
		do {
			prev = cond;
			cond = myalite.get(world.random.nextInt(myalite.size()));
			found.add(cond);
			myalite = getAdjacentMyalite(found, world, cond, null);

			moves++;
			if(myalite == null || moves > myaliteConduitDistance)
				return;
		} while(!myalite.isEmpty());

		BlockPos test = cond.offset(cond.getX() - prev.getX(), cond.getY() - prev.getY(), cond.getZ() - prev.getZ());

		find: if(!world.getBlockState(test).isAir()) {
			for(Direction d : Direction.values()) {
				test = cond.relative(d);
				if(world.getBlockState(test).isAir()) {
					if(d.getAxis() == Axis.Y)
						test = test.relative(d);

					break find;
				}
			}

			return;
		}

		event.setTargetX(test.getX() + 0.5);
		event.setTargetY(test.getY() + 0.5);
		event.setTargetZ(test.getZ() + 0.5);

		if(event.getEntity() instanceof ServerPlayer sp)
			useViaductTrigger.trigger(sp);

		if(world instanceof ServerLevel sworld) {
			for(BlockPos f : found)
				sworld.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, myalite_crystal.defaultBlockState()), f.getX() + 0.5, f.getY() + 0.5, f.getZ() + 0.5, 30, 0.25, 0.25, 0.25, 0);
		}
	}
}

default void kick(boolean backKick, boolean softBackKick) {
	AbstractHorse horse = (AbstractHorse) this;

	this.setKickTime(1);
	horse.setEating(false);

	AttributeInstance attributeinstance = horse.getAttribute(Attributes.MOVEMENT_SPEED);
	if (!attributeinstance.hasModifier(SPEED_MODIFIER_KICKING.id()))
		attributeinstance.addTransientModifier(SPEED_MODIFIER_KICKING);

	if (!backKick) {
		this.playFrontKickAnim();
		horse.level().broadcastEntityEvent(horse, (byte) 8);
	} else {
		this.playBackKickAnim();
		horse.level().broadcastEntityEvent(horse, (byte) 9);
	}

	List<LivingEntity> nearby = horse.level().getEntitiesOfClass(LivingEntity.class, horse.getBoundingBox().inflate(1.0F), KICKABLE_PREDICATE);
	for (LivingEntity living : nearby) {
		Vec3 attackAngleVector = living.position().subtract(horse.position()).normalize();
		attackAngleVector = new Vec3(attackAngleVector.x, 0.0D, attackAngleVector.z);

		float rot = horse.getVisualRotationYInDegrees();
		float x = Mth.sin(rot * Mth.DEG_TO_RAD);
		float z = -Mth.cos(rot * Mth.DEG_TO_RAD);
		double angle = attackAngleVector.dot(Vec3.directionFromRotation(0.0F, rot).normalize());
		boolean jumpkick = this.canJumpKick();

		if (!backKick && angle > 0.7D || backKick && angle < -0.7D) {
			DamageSource source;
			LivingEntity rider = horse.getControllingPassenger();
			if (rider != null) {
				source = EnvironmentalDamageTypes.ridingZebra(horse.level(), horse, rider);
			} else {
				source = horse.damageSources().mobAttack(horse);
			}
			float damage = (float) horse.getAttributeValue(Attributes.ATTACK_DAMAGE);
			float knockback = (float) horse.getAttributeValue(Attributes.ATTACK_KNOCKBACK);

			if (jumpkick) {
				float f = this.getJumpStrength();
				if (rider != null && rider.zza <= 0.0F)
					f *= 0.5F;
				damage += f * 6.0F;
				knockback = knockback * 0.8F + f * 1.1F;
			} else if (backKick) {
				if (!softBackKick)
					damage += 2.0F;
				else if (damage > 1.0F)
					damage = 1.0F;
				knockback *= 1.2F;
			} else {
				knockback *= 0.8F;
			}

			if (living.hurt(source, (int) damage)) {
				if (horse.level() instanceof ServerLevel serverLevel) {
					EnchantmentHelper.doPostAttackEffects(serverLevel, living, source);
				}

				if (!backKick)
					living.knockback(knockback, x, z);
				else
					living.knockback(knockback, -x, -z);
			}
		}
	}
}

public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext context)
{
	Level world = context.getLevel();
	BlockPos pos = context.getClickedPos();
	Player player = context.getPlayer();
	Direction side = context.getClickedFace();

	/*
		Multiblock Handling
	 */
	var restriction = stack.getOrDefault(IEDataComponents.MULTIBLOCK_RESTRICTION, MultiblockRestriction.DEFAULT);
	final Direction multiblockSide;
	if(side.getAxis()==Axis.Y&&player!=null)
		multiblockSide = Direction.fromYRot(player.getYRot()).getOpposite();
	else
		multiblockSide = side;
	for(MultiblockHandler.IMultiblock mb : MultiblockHandler.getMultiblocks())
		if(mb.isBlockTrigger(world.getBlockState(pos), multiblockSide, world))
		{
			boolean isAllowed;
			if(restriction.allowed.isPresent())
				isAllowed = restriction.allowed.get().contains(mb.getUniqueName());
			else if(restriction.forbidden.isPresent())
				isAllowed = !restriction.forbidden.get().contains(mb.getUniqueName());
			else
				isAllowed = true;
			if(!isAllowed)
				continue;
			if(MultiblockHandler.postMultiblockFormationEvent(player, mb, pos, stack).isCanceled())
				continue;
			if(mb.createStructure(world, pos, multiblockSide, player))
			{
				if(player instanceof ServerPlayer sPlayer)
					MultiblockAdvancementTrigger.INSTANCE.get().trigger(sPlayer, mb, stack);
				return InteractionResult.SUCCESS;
			}
		}

	/*
		Side Configs & Rotation Handling
	 */
	BlockEntity tile = world.getBlockEntity(pos);
	if(tile instanceof IConfigurableSides sideConfig)
	{
		Direction activeSide = ((player!=null)&&player.isShiftKeyDown())?side.getOpposite(): side;
		if(sideConfig.toggleSide(activeSide, player))
			return InteractionResult.SUCCESS;
		else
			return InteractionResult.FAIL;
	}

	if(world.getBlockState(pos).getBlock() instanceof IHammerBlockInteraction block)
	{
		InteractionResult result = block.useHammer(world.getBlockState(pos), world, pos, player, context);
		if(result.consumesAction())
			return result;
	}

	boolean rotate = !(tile instanceof IDirectionalBE)&&!(tile instanceof IHammerInteraction);
	if(!rotate&&tile instanceof IDirectionalBE dirBE)
		rotate = dirBE.canHammerRotate(side, context.getClickLocation().subtract(Vec3.atLowerCornerOf(pos)), player);
	if(rotate&&RotationUtil.rotateBlock(world, pos, player!=null&&(player.isShiftKeyDown()!=side.equals(Direction.DOWN))))
		return InteractionResult.SUCCESS;
	else if(!rotate&&tile instanceof IHammerInteraction hammerInteraction)
	{
		if(hammerInteraction.hammerUseSide(side, player, context.getHand(), context.getClickLocation()))
			return InteractionResult.SUCCESS;
	}
	return InteractionResult.PASS;
}

        public void tick() {
            speedFactor = 1;

            if (movement == EnumNagaMovement.GLIDING) {
                if (this.operation == Operation.MOVE_TO) {
                    if (EntityNaga.this.horizontalCollision) {
                        EntityNaga naga = EntityNaga.this;
                        naga.setYRot(naga.getYRot() + 180.0F);
                        this.speedFactor = 0.1F;
                        getNavigation().stop();
                    }

                    float orbitOffsetDiffX = (float) (getNavigation().getTargetPos().getX() - EntityNaga.this.getX());
                    float orbitOffsetDiffY = (float) (getNavigation().getTargetPos().getY() - EntityNaga.this.getY());
                    float orbitOffsetDiffZ = (float) (getNavigation().getTargetPos().getZ() - EntityNaga.this.getZ());
                    double horizontalDistToOrbitOffset = (double) Mth.sqrt(orbitOffsetDiffX * orbitOffsetDiffX + orbitOffsetDiffZ * orbitOffsetDiffZ);
                    double yFractionReduction = 1.0D - (double) Mth.abs(orbitOffsetDiffY * 0.7F) / horizontalDistToOrbitOffset;
                    orbitOffsetDiffX = (float) ((double) orbitOffsetDiffX * yFractionReduction);
                    orbitOffsetDiffZ = (float) ((double) orbitOffsetDiffZ * yFractionReduction);
                    horizontalDistToOrbitOffset = (double) Mth.sqrt(orbitOffsetDiffX * orbitOffsetDiffX + orbitOffsetDiffZ * orbitOffsetDiffZ);
                    double distToOrbitOffset = (double) Mth.sqrt(orbitOffsetDiffX * orbitOffsetDiffX + orbitOffsetDiffZ * orbitOffsetDiffZ + orbitOffsetDiffY * orbitOffsetDiffY);
                    float rotationYaw = EntityNaga.this.getYRot();
                    float desiredRotationYaw = (float) Mth.atan2((double) orbitOffsetDiffZ, (double) orbitOffsetDiffX);
                    float rotationYawWrapped = Mth.wrapDegrees(EntityNaga.this.getYRot() + 90.0F);
                    float desiredRotationYawWrapped = Mth.wrapDegrees(desiredRotationYaw * 57.295776F);
                    EntityNaga.this.setYRot(Mth.approachDegrees(rotationYawWrapped, desiredRotationYawWrapped, 4.0F) - 90.0F);
                    float newBanking = MowzieMathUtil.approachDegreesSmooth(getBanking(), getPrevBanking(), EntityNaga.this.getYRot() - rotationYaw, 0.5f, 0.1f);
                    setPrevBanking(getBanking());
                    setBanking(newBanking);
                    EntityNaga.this.yBodyRot = EntityNaga.this.getYRot();
//                if (MathHelper.degreesDifferenceAbs(rotationYaw, EntityNaga.this.rotationYaw) < 3.0F) {
//                    this.speedFactor = MathHelper.approach(this.speedFactor, 1.8F, 0.005F * (1.8F / this.speedFactor));
//                } else {
//                    this.speedFactor = MathHelper.approach(this.speedFactor, 0.2F, 0.025F);
//                }

                    float desiredPitch = (float) (-(Mth.atan2((double) (-orbitOffsetDiffY), horizontalDistToOrbitOffset) * 57.2957763671875D));
                    EntityNaga.this.setXRot(Mth.approachDegrees(EntityNaga.this.getXRot(), desiredPitch, 8));
                    float rotationYaw1 = EntityNaga.this.getYRot() + 90.0F;
                    double xMotion = (double) (this.speedFactor * Mth.cos(rotationYaw1 * 0.017453292F)) * Math.abs((double) orbitOffsetDiffX / distToOrbitOffset);
                    double yMotion = (double) (this.speedFactor * Mth.sin(rotationYaw1 * 0.017453292F)) * Math.abs((double) orbitOffsetDiffZ / distToOrbitOffset);
                    double zMotion = (double) (this.speedFactor * Mth.sin(desiredPitch * 0.017453292F)) * Math.abs((double) orbitOffsetDiffY / distToOrbitOffset);
                    Vec3 motion = EntityNaga.this.getDeltaMovement();
                    EntityNaga.this.setDeltaMovement(motion.add((new Vec3(xMotion, zMotion, yMotion)).subtract(motion).scale(0.1D)));
                }
            }
            else if (movement == EnumNagaMovement.HOVERING) {
                if (getAnimation() == NO_ANIMATION || getAnimation() == SPIT_ANIMATION) {
                    LivingEntity target = getTarget();
                    if (target != null && EntityNaga.this.distanceToSqr(this.parentEntity) < 1600.0D) {
                        lookAt(target, 100, 100);
                    }

                    if (this.operation == MoveControl.Operation.MOVE_TO) {
                        if (this.courseChangeCooldown-- <= 0) {
                            this.courseChangeCooldown += this.parentEntity.getRandom().nextInt(5) + 2;
                            Vec3 Vector3d = new Vec3(this.wantedX - this.parentEntity.getX(), this.wantedY - this.parentEntity.getY(), this.wantedZ - this.parentEntity.getZ());
                            double d0 = Vector3d.length();
                            Vector3d = Vector3d.normalize();
                            if (this.checkCollisions(Vector3d, Mth.ceil(d0))) {
                                this.parentEntity.setDeltaMovement(this.parentEntity.getDeltaMovement().add(Vector3d.scale(0.1D)));
                            } else {
                                this.operation = MoveControl.Operation.WAIT;
                            }
                        }
                    }

                }
            }
        }

public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext ctx) {
    Level level = ctx.getLevel();
    BlockPos pos = ctx.getClickedPos();
    Player player = ctx.getPlayer();

    if (player != null && !level.isClientSide) {
        if (player.isShiftKeyDown()) {
            // sneak-right-click: clear camo
            setCamoState(stack, null);
            level.playSound(null, ctx.getClickedPos(), ModSounds.CHIRP.get(), SoundSource.PLAYERS, 1f, 1f);
        } else {
            BlockEntity te = level.getBlockEntity(pos);
            BlockState state = level.getBlockState(pos);
            if (!(te instanceof CamouflageableBlockEntity camoTE)) {
                // right-click non-camo block: copy its state
                setCamoState(stack, state);
                level.playSound(null, ctx.getClickedPos(), ModSounds.CHIRP.get(), SoundSource.PLAYERS, 1f, 2f);
            } else {
                // right-click camo block: try to apply (or remove) camo

                IAirHandlerItem airHandler = PNCCapabilities.getAirHandler(stack).orElseThrow(RuntimeException::new);
                if (!player.isCreative() && airHandler.getPressure() < 0.1F) {
                    // not enough pressure
                    return InteractionResult.FAIL;
                }

                BlockState newCamo = getCamoState(stack);
                BlockState existingCamo = camoTE.getCamouflage();

                if (existingCamo == newCamo) {
                    level.playSound(null, ctx.getClickedPos(), SoundEvents.COMPARATOR_CLICK, SoundSource.PLAYERS, 1f, 2f);
                    return InteractionResult.SUCCESS;
                }

                // make sure player has enough of the camo item
                if (newCamo != null && !player.isCreative()) {
                    ItemStack camoStack = CamouflageableBlockEntity.getStackForState(newCamo);
                    if (!PneumaticCraftUtils.consumeInventoryItem(player.getInventory(), camoStack)) {
                        player.displayClientMessage(xlate("pneumaticcraft.message.camo.notEnoughBlocks", camoStack.getHoverName())
                                .withStyle(ChatFormatting.RED), true);
                        NetworkHandler.sendToAllTracking(new PacketPlaySound(ModSounds.MINIGUN_STOP.get(), SoundSource.PLAYERS,
                                pos, 1.0F, 2.0F, true), level, pos);
                        return InteractionResult.FAIL;
                    }
                }

                // return existing camo block, if any
                if (existingCamo != null && !player.isCreative()) {
                    ItemStack camoStack = CamouflageableBlockEntity.getStackForState(existingCamo);
                    ItemEntity entity = new ItemEntity(level, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, camoStack);
                    level.addFreshEntity(entity);
                    entity.playerTouch(player);
                }

                // and apply the new camouflage
                if (!player.isCreative()) {
                    airHandler.addAir(-PneumaticValues.USAGE_CAMO_APPLICATOR);
                }
                camoTE.setCamouflage(newCamo);
                BlockState particleState = newCamo == null ? existingCamo : newCamo;
                if (particleState != null) {
                    player.getCommandSenderWorld().levelEvent(LevelEvent.PARTICLES_DESTROY_BLOCK, pos, Block.getId(particleState));
                }
                NetworkHandler.sendToAllTracking(new PacketPlaySound(ModSounds.SHORT_HISS.get(), SoundSource.PLAYERS, pos, 1.0F, 1.0F, true), level, pos);
            }
        }
    }

    return InteractionResult.sidedSuccess(level.isClientSide);
}

public void load(CompoundTag nbt, HolderLookup.Provider holderLookup, boolean isPartial) {
	if (nbt.contains("ItemStorage", Tag.TAG_COMPOUND)) {
		CompoundTag data = nbt.getCompound("ItemStorage");

		if (!data.isEmpty()) {
			this.itemStorage.clear();

			for (String key : data.getAllKeys()) {
				try {
					this.itemStorage.put(Integer.parseInt(key), ItemStack.parseOptional(holderLookup, data.getCompound(key)));
				}
				catch (Exception ex) {
					Logging.logMessage(org.apache.logging.log4j.Level.WARN, "Invalid key in ItemStorage NBT data for player. Stop messing with player NBT!", ex);
				}
			}
		}
	}

	if (nbt.contains("PortalMap", Tag.TAG_COMPOUND)) {
		CompoundTag data = nbt.getCompound("PortalMap");

		if (!data.isEmpty()) {
			this.portalCoordinatesMap.clear();

			for (String entry : data.getAllKeys()) {
				try {
					CompoundTag portalReturnTag = data.getCompound(entry);
					ResourceLocation fromDim = ResourceLocation.read(portalReturnTag.getString("FromDim")).getOrThrow();
					BlockPos portalPos = NbtUtils.readBlockPos(portalReturnTag, "PortalPos").orElseGet(() -> getPlayer().level().getSharedSpawnPos());
					ResourceKey<Level> toDimKey = ResourceKey.create(Registries.DIMENSION, ResourceLocation.read(entry).getOrThrow());
					ResourceKey<Level> fromDimKey = ResourceKey.create(Registries.DIMENSION, fromDim);

					this.portalCoordinatesMap.put(toDimKey, new GlobalPos(fromDimKey, portalPos));
				}
				catch (Exception e) {
					Logging.logMessage(org.apache.logging.log4j.Level.WARN, "Found invalid portal map data, has someone been tampering with files? Data: " + entry);
				}
			}
		}
	}

	if (nbt.contains("Checkpoint", Tag.TAG_COMPOUND)) {
		try {
			CompoundTag checkpointTag = nbt.getCompound("Checkpoint");
			double x = checkpointTag.getDouble("x");
			double y = checkpointTag.getDouble("y");
			double z = checkpointTag.getDouble("z");
			float pitch = checkpointTag.getFloat("pitch");
			float yaw = checkpointTag.getFloat("yaw");

			this.activeCheckpoint = new PositionAndRotation(x, y, z, pitch, yaw);
		}
		catch (NumberFormatException e) {
			Logging.logMessage(org.apache.logging.log4j.Level.WARN, "Found invalid checkpoint data, has someone been tampering with files?");
		}
	}

	if (nbt.contains("PatchouliBooks")) {
		ListTag data = nbt.getList("PatchouliBooks", Tag.TAG_STRING);

		this.needsPatchouliSync = true;

		if (!this.patchouliBooks.isEmpty())
			this.patchouliBooks.clear();

		for (Tag book : data) {
			ResourceLocation.read(book.getAsString()).resultOrPartial(err -> Logging.logMessage(org.apache.logging.log4j.Level.WARN, err)).ifPresent(this.patchouliBooks::add);
		}
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity().level().isClientSide || !(context.entity() instanceof Player))
		return;

	Player player = (Player) context.entity();

	if (player.isCreative() || player.isSpectator())
		return;

	List<LivingEntity> genericMobs = player.level().getEntitiesOfClass(LivingEntity.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, neutralAngerRange.getValue()));
	List<EnderMan> endermen = player.level().getEntitiesOfClass(EnderMan.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, endermenRandomportRange.getValue()));

	for (EnderMan enderman : endermen) {
		if (random.nextDouble() <= (0.002 * endermenRandomportFrequency.getValue())) {
			if (enderman.teleportTowards(player) && player.hasLineOfSight(enderman)) {
				enderman.setTarget(player);
			}
		}
	}

	for (LivingEntity checkedEntity : genericMobs) {
		double visibility = player.getVisibilityPercent(checkedEntity);
		double angerDistance = Math.max(neutralAngerRange.getValue() * visibility, neutralXRayRange.getValue());

		if (checkedEntity.distanceToSqr(player.getX(), player.getY(), player.getZ()) > angerDistance * angerDistance) {
			continue;
		}

		if (checkedEntity instanceof Piglin && !SuperpositionHandler.hasCurio(player, EnigmaticItems.AVARICE_SCROLL)) {
			Piglin piglin = (Piglin) checkedEntity;

			if (piglin.getTarget() == null || !piglin.getTarget().isAlive()) {
				if (player.hasLineOfSight(checkedEntity) || player.distanceTo(checkedEntity) <= neutralXRayRange.getValue()) {
					PiglinAi.wasHurtBy(piglin, player);
				} else {
					continue;
				}
			}

		} else if (checkedEntity instanceof NeutralMob) {
			NeutralMob neutral = (NeutralMob) checkedEntity;

			if (neutralAngerBlacklist.contains(ForgeRegistries.ENTITY_TYPES.getKey(checkedEntity.getType()))) {
				continue;
			}

			if (neutral instanceof TamableAnimal tamable && tamable.isTame()) {
				continue;
			} else if (SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK)) {
				if (EnigmaticItems.ANIMAL_GUIDEBOOK.isTamableAnimal(checkedEntity)) {
					continue;
				}
			} else if (neutral instanceof IronGolem golem && golem.isPlayerCreated()) {
				continue;
			} else if (neutral instanceof Bee) {
				if (saveTheBees.getValue() || SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK)) {
					continue;
				}
			}

			if (neutral.getTarget() == null || !neutral.getTarget().isAlive()) {
				if (player.hasLineOfSight(checkedEntity) || player.distanceTo(checkedEntity) <= neutralXRayRange.getValue()) {
					neutral.setTarget(player);
				} else {
					continue;
				}
			}
		}
	}

}

public void tick() {
    super.tick();
    prevBuriedProgress = buriedProgress;
    prevCarryingProgress = carryingProgress;
    prevPrayingProgress = prayingProgress;
    if(!this.isNoAi() && (buriedProgress == 0.0F && this.isBuried() || buriedProgress == 20.0F && !this.isBuried())){
        this.playSound(ACSoundRegistry.UNDERZEALOT_DIG.get());
    }
    if (isBuried() && buriedProgress < 20.0F) {
        buriedProgress = Math.min(20.0F, buriedProgress + 1.5F);
    }
    if (!isBuried() && buriedProgress > 0.0F) {
        buriedProgress = Math.max(0.0F, buriedProgress - 1.5F);
    }
    if (isCarrying() && carryingProgress < 5.0F) {
        carryingProgress++;
    }
    if (!isCarrying() && carryingProgress > 0.0F) {
        carryingProgress--;
    }
    if (isPraying() && prayingProgress < 5.0F) {
        prayingProgress++;
    }
    if (!isPraying() && prayingProgress > 0.0F) {
        prayingProgress--;
    }
    if (!level().isClientSide) {
        if (this.isCarrying() && this.isPackFollower()) {
            for (Entity passenger : this.getPassengers()) {
                passenger.stopRiding();
            }
        }
        this.setCarrying(!this.getPassengers().isEmpty());
        if (this.isBuried() && buriedProgress >= 20.0F) {
            if (reemergeTime-- < 0) {
                this.moveTo(remergePos.getX() + 0.5F, remergePos.getY(), remergePos.getZ() + 0.5F);
                idleBuryIn = 400 + random.nextInt(800);
                reemergeTime = 0;
                this.setBuried(false);
            }
            Vec3 centerOf = Vec3.atBottomCenterOf(this.blockPosition()).subtract(this.position());
            this.getDeltaMovement().add(centerOf.x * 0.1F, 0, centerOf.z * 0.1F);
        } else if (digsIdle() && idleBuryIn-- < 0) {
            if (this.onGround()) {
                this.setBuried(true);
                idleBuryIn = 0;
                reemergeAt(findReemergePos(this.blockPosition(), 10), 40 + random.nextInt(60));
            }
        }
        if (isDiggingInProgress()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.0D, 1.0D, 0.0D));
        }
    } else if (isDiggingInProgress()) {
        BlockState stateOn = this.getBlockStateOn();
        if (stateOn.isSolid()) {
            for (int i = 0; i < 3; i++) {
                level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, stateOn), true, this.getRandomX(0.8F), this.getY(), this.getRandomZ(0.8F), random.nextFloat() - 0.5F, random.nextFloat() + 0.5F, random.nextFloat() - 0.5F);
            }
        }
        if (isBuried()) {
            this.setOldPosAndRot();
        }
    }
    if (cloudCooldown > 0) {
        cloudCooldown--;
    }
    if (sacrificeCooldown > 0) {
        sacrificeCooldown--;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    prevJostleAngle = this.getJostleAngle();
    super.tick();
    prevJostleProgress = jostleProgress;
    prevSitProgress = sitProgress;

    if(slaughterCooldown > 0){
        slaughterCooldown--;
    }
    if (!this.level().isClientSide && this.isAlive() && !this.isBaby() && --this.timeUntilSpit <= 0) {
        this.spawnAtLocation(AMItemRegistry.KOMODO_SPIT.get());
        this.timeUntilSpit = this.random.nextInt(12000) + 24000;
    }
    if(riderAttackCooldown > 0){
        riderAttackCooldown--;
    }
    if(this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player){
        Player rider = (Player)this.getControllingPassenger();
        if(rider.getLastHurtMob() != null && this.distanceTo(rider.getLastHurtMob()) < this.getBbWidth() + 3F && !this.isAlliedTo(rider.getLastHurtMob())){
            UUID preyUUID = rider.getLastHurtMob().getUUID();
            if (!this.getUUID().equals(preyUUID) && riderAttackCooldown == 0) {
                doHurtTarget(rider.getLastHurtMob());
                riderAttackCooldown = 20;
            }
        }
    }
    if (!hasJostlingSize && isJostling()){
        refreshDimensions();
        hasJostlingSize = true;
    }
    if (hasJostlingSize && !isJostling()){
        refreshDimensions();
        hasJostlingSize = false;
    }

    if (this.isJostling()) {
        if (jostleProgress < 5F)
            jostleProgress++;
    } else {
        if (jostleProgress > 0F)
            jostleProgress--;
    }

    if (this.isOrderedToSit()) {
        if (sitProgress < 5F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if(this.getCommand() == 2 && !this.isVehicle()){
        this.setOrderedToSit(true);
    }else{
        this.setOrderedToSit(false);
    }

    if (jostleCooldown > 0) {
        jostleCooldown--;
    }

    if(!this.level().isClientSide){
        if(this.getJostleAngle() < nextJostleAngleFromServer){
            this.setJostleAngle(this.getJostleAngle() + 1);

        }
        if(this.getJostleAngle() > nextJostleAngleFromServer) {
            this.setJostleAngle(this.getJostleAngle() - 1);
        }
    }
}

public void onDeath(DamageSource cause) {
	super.onDeath(cause);

	if(!this.world.isRemote) {
		List<SpiritTreeKillToken> killTokens = BetweenlandsWorldStorage.forWorld(this.world).getSpiritTreeKillTokens();
		if(killTokens.size() > 32) {
			killTokens.remove(0);
		}
		killTokens.add(new SpiritTreeKillToken(this.getPosition(), this.getWispStrengthModifier()));

		List<LocationSpiritTree> locations = BetweenlandsWorldStorage.forWorld(this.world).getLocalStorageHandler().getLocalStorages(LocationSpiritTree.class, this.getEntityBoundingBox(), loc -> loc.isInside(this));
		if(!locations.isEmpty()) {
			LocationSpiritTree location = locations.get(0);

			List<EntitySpiritTreeFaceSmall> smallFaces = this.world.getEntitiesWithinAABB(EntitySpiritTreeFaceSmall.class, location.getEnclosingBounds());
			for(EntitySpiritTreeFaceSmall face : smallFaces) {
				face.setDropItemsWhenDead(false);
				face.setDead();
			}

			List<BlockPos> wispPositions = new ArrayList<>();
			wispPositions.addAll(location.getGeneratedWispPositions());
			wispPositions.addAll(location.getNotGeneratedWispPositions());
			for(BlockPos wisp : wispPositions) {
				if(this.world.getBlockState(wisp).getBlock() == BlockRegistry.WISP) {
					this.world.setBlockToAir(wisp);
				}
			}

			List<BlockPos> positions = location.getLargeFacePositions();
			BlockPos lowest = null;
			for(BlockPos pos : positions) {
				if(lowest == null || lowest.getY() > pos.getY()) {
					lowest = pos;
				}
			}
			if(lowest != null) {
				int radius = 5;
				for(int xo = -radius; xo <= radius; xo++) {
					for(int yo = -radius; yo <= radius; yo++) {
						for(int zo = -radius; zo <= radius; zo++) {
							if(xo*xo + yo*yo + zo*zo <= radius*radius) {
								BlockPos pos = lowest.add(xo, yo, zo);
								IBlockState state = this.world.getBlockState(pos);

								if(SurfaceType.GRASS_AND_DIRT.matches(state) && !this.world.getBlockState(pos.up()).isNormalCube() && this.world.rand.nextInt(3) == 0) {
									this.world.setBlockState(pos, BlockRegistry.SPREADING_SLUDGY_DIRT.getDefaultState());
								}

								if(state.getBlock() == BlockRegistry.LOG_SPIRIT_TREE && this.world.rand.nextInt(5) == 0) {
									this.world.setBlockState(pos, BlockRegistry.LOG_SPREADING_ROTTEN_BARK.getDefaultState());
								}
							}
						}
					}
				}
			}

			for(BlockPos pos : location.getSmallFacePositions()) {
				IBlockState state = this.world.getBlockState(pos);
				if(state.getBlock() == BlockRegistry.LOG_SPIRIT_TREE && this.world.rand.nextInt(10) == 0) {
					this.world.setBlockState(pos, BlockRegistry.LOG_SPREADING_ROTTEN_BARK.getDefaultState());
				}
			}

			location.getGuard().clear(this.world);
			location.setVisible(false);
			location.setDirty(true);
		}
	}
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    if (!isShifting(caster)) {
        int i = 1;
        if (staff.is(ModItems.NAMELESS_STAFF.get())){
            i = 7;
        } else if (rightStaff(staff)){
            i = 2 + caster.level.random.nextInt(4);
        } else if (specialStaffs(staff)){
            i = 2;
        }
        for (int i1 = 0; i1 < i; ++i1) {
            EntityType<?> entityType;
            Summoned summonedentity = new ZombieServant(ModEntityType.ZOMBIE_SERVANT.get(), worldIn);
            BlockPos blockPos = BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn);
            if (caster.isUnderWater()){
                blockPos = BlockFinder.SummonWaterRadius(caster, worldIn);
            }
            if (specialStaffs(staff)) {
                if (typeStaff(staff, SpellType.FROST)) {
                    summonedentity = new FrozenZombieServant(ModEntityType.FROZEN_ZOMBIE_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.STORM)) {
                    summonedentity = new FrayedServant(ModEntityType.FRAYED_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.WILD)) {
                    summonedentity = new JungleZombieServant(ModEntityType.JUNGLE_ZOMBIE_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.NETHER)) {
                    summonedentity = new ZPiglinServant(ModEntityType.ZPIGLIN_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.ABYSS)) {
                    summonedentity = new DrownedServant(ModEntityType.DROWNED_SERVANT.get(), worldIn);
                } else if (staff.is(ModItems.OMINOUS_STAFF.get())) {
                    summonedentity = new ZombieVindicatorServant(ModEntityType.ZOMBIE_VINDICATOR_SERVANT.get(), worldIn);
                }
            } else {
                Player player = null;
                if (caster instanceof Player player1){
                    player = player1;
                }
                entityType = summonedentity.getVariant(player, worldIn, blockPos);
                if (entityType != null){
                    Entity entity = entityType.create(worldIn);
                    if (entity instanceof Summoned summoned){
                        summonedentity = summoned;
                    }
                }
            }
            summonedentity.setTrueOwner(caster);
            summonedentity.moveTo(blockPos, 0.0F, 0.0F);
            if (summonedentity.getType() != ModEntityType.DROWNED_SERVANT.get()){
                MobUtil.moveDownToGround(summonedentity);
            }
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.setPersistenceRequired();
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED,null,null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        SoundUtil.playNecromancerSummon(caster);
    }
}

private boolean trySpawnInvader(FinalizeSpawnEvent e, Mob mob, GenContext ctx, Player player) {
    // Invaders can only trigger off of natural spawns (chunk generation is considered "natural")
    if (e.getSpawnType() != EntitySpawnReason.NATURAL && e.getSpawnType() != EntitySpawnReason.CHUNK_GENERATION || !(mob instanceof Monster)) {
        debugLog("[Invaders]: Failed invader preconditions.");
        return false;
    }

    ServerLevelAccessor sLevel = e.getLevel();
    long gameTime = sLevel.getGameTime();

    if (player.getData(Attachments.INVADER_COOLDOWN) > gameTime) {
        debugLog("[Invaders]: Spawn cooldown is active for the context player {}.", player.getName().getString());
        return false;
    }

    ResourceKey<DimensionType> dimId = sLevel.getLevel().dimensionTypeRegistration().getKey();

    InvaderSpawnRules rules = sLevel.registryAccess().lookupOrThrow(Registries.DIMENSION_TYPE).getData(DataMaps.INVADER_SPAWN_RULES, dimId);
    if (rules == null) {
        debugLog("[Invaders]: No invader spawn rules present for dimension {}", dimId);
        return false;
    }

    float chance = rules.spawnChances().get(ctx.tier());
    SurfaceType surface = rules.surfaceType();

    if (ctx.rand().nextFloat() > chance) {
        debugLog("[Invaders]: Failed random chance roll.");
        return false;
    }

    if (surface.test(sLevel, BlockPos.containing(e.getX(), e.getY(), e.getZ()))) {
        debugLog("[Invaders]: Succeeded at random chance roll and surface test.");
        Invader item = InvaderRegistry.INSTANCE.getRandomItem(ctx);
        if (item == null) {
            Apotheosis.LOGGER.error("Attempted to spawn an Invader in dimension {} using configured spawn rules {} but no bosses were made available.", dimId, rules);
            return false;
        }

        if (!item.basicData().canSpawn(mob, sLevel, e.getSpawnType())) {
            debugLog("[Invaders]: Failed invader spawn conditions.");
            return false;
        }

        Mob boss = item.createBoss(sLevel, BlockPos.containing(e.getX() - 0.5, e.getY(), e.getZ() - 0.5), ctx);
        if (rules.autoAggro().orElse(AdventureConfig.bossAutoAggro) && !player.isCreative()) {
            boss.setTarget(player);
        }

        if (canSpawn(sLevel, boss, player.distanceToSqr(boss))) {
            sLevel.addFreshEntityWithPassengers(boss);
            e.setCanceled(true);
            e.setSpawnCancelled(true);

            sendInvaderSpawnNotification(sLevel.getLevel(), boss);

            long end = gameTime + rules.cooldown().orElse(AdventureConfig.bossSpawnCooldown);
            applyClusteredCooldown(sLevel.getLevel(), player, ctx.tier(), boss, end);
            debugLog("[Invaders]: Successfully spawned an invader {} at {}", boss.getName().getString(), boss.blockPosition());
            return true;
        }
        else {
            debugLog("Failed entity spawn checks.");
        }
    }
    else {
        debugLog("[Invaders]: Failed surface test " + surface);
    }

    return false;
}

public void tick() {
    LivingEntity livingentity = this.mob.getTarget();
    if (livingentity != null) {
        boolean flag = this.mob.getSensing().hasLineOfSight(livingentity);
        boolean flag1 = this.seeTime > 0;
        if (flag != flag1) {
            this.seeTime = 0;
        }

        if (flag) {
            this.seeTime++;
        } else {
            this.seeTime--;
        }

        double d0 = this.mob.distanceToSqr(livingentity);
        boolean flag2 = (d0 > (double) this.attackRadiusSqr || this.seeTime < 5) && this.attackDelay == 0;
        if (flag2) {
            this.updatePathDelay--;
            if (this.updatePathDelay <= 0) {
                this.mob.getNavigation().moveTo(livingentity, this.canRun() ? this.speedModifier : this.speedModifier * 0.5);
                this.updatePathDelay = PATHFINDING_DELAY_RANGE.sample(this.mob.getRandom());
            }
        } else {
            this.updatePathDelay = 0;
            this.mob.getNavigation().stop();
        }

        this.mob.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
        if (this.crossbowState == RangedCrossbowAttackGoal.CrossbowState.UNCHARGED) {
            if (!flag2) {
                this.mob.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.mob, IHunterCrossbow.class::isInstance)); // IVampirismCrossbow
                this.crossbowState = RangedCrossbowAttackGoal.CrossbowState.CHARGING;
                this.mob.setChargingCrossbow(true);
            }
        } else if (this.crossbowState == RangedCrossbowAttackGoal.CrossbowState.CHARGING) {
            if (!this.mob.isUsingItem()) {
                this.crossbowState = RangedCrossbowAttackGoal.CrossbowState.UNCHARGED;
            }

            int i = this.mob.getTicksUsingItem();
            ItemStack itemstack = this.mob.getUseItem();
            int chargeDuration = itemstack.getItem() instanceof IHunterCrossbow crossbow ? crossbow.getChargeDurationMod(itemstack, this.mob.level()) : CrossbowItem.getChargeDuration(itemstack, this.mob);
            if (i >= chargeDuration) {
                this.mob.releaseUsingItem();
                this.crossbowState = RangedCrossbowAttackGoal.CrossbowState.CHARGED;
                this.attackDelay = 20 + this.mob.getRandom().nextInt(20);
                this.mob.setChargingCrossbow(false);
            }
        } else if (this.crossbowState == RangedCrossbowAttackGoal.CrossbowState.CHARGED) {
            this.attackDelay--;
            if (this.attackDelay == 0) {
                this.crossbowState = RangedCrossbowAttackGoal.CrossbowState.READY_TO_ATTACK;
            }
        } else if (this.crossbowState == RangedCrossbowAttackGoal.CrossbowState.READY_TO_ATTACK && flag) {
            this.mob.performRangedAttack(livingentity, 1.0F);
            ItemStack itemInHand = this.mob.getItemInHand(ProjectileUtil.getWeaponHoldingHand(this.mob, IHunterCrossbow.class::isInstance)); // set state depending on still loaded projectiles
            ChargedProjectiles projectiles = itemInHand.getOrDefault(DataComponents.CHARGED_PROJECTILES, ChargedProjectiles.EMPTY);
            if (!projectiles.isEmpty()) {
                var delay = getAttackDelay(itemInHand);
                this.attackDelay = delay + this.mob.getRandom().nextInt(delay);
                this.crossbowState = CrossbowState.CHARGED;

            } else {
                itemInHand.remove(DataComponents.CHARGED_PROJECTILES);
                this.crossbowState = CrossbowState.UNCHARGED;
            }
        }
    }

}

public void tick() {
    super.tick();
    this.prevHoldProgress = holdProgress;
    this.prevSwimProgress = swimProgress;
    this.prevSitProgress = sitProgress;
    this.prevVibrateProgress = vibrateProgress;

    final boolean ground = !this.isInWaterOrBubble();
    final boolean bellowing = this.isBellowing();
    final boolean grabbing = this.getHeldMobId() != -1;
    final boolean sitting = this.isSitting() && ground;

    if (!ground && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (ground && !this.isLandNavigator) {
        switchNavigator(true);
    }
    if (ground && swimProgress > 0) {
        swimProgress--;
    }
    if (!ground && swimProgress < 5F) {
        swimProgress++;
    }
    if (bellowing && vibrateProgress < 5) {
        vibrateProgress++;
    }
    if (!bellowing && vibrateProgress > 0F) {
        vibrateProgress--;
    }
    if (sitting && sitProgress < 5) {
        sitProgress++;
    }
    if (!sitting && sitProgress > 0F) {
        sitProgress--;
    }
    if (grabbing && holdProgress < 5) {
        holdProgress += 2.5F;
    }
    if (!grabbing && holdProgress > 0F) {
        holdProgress -= 2.5F;
    }
    if (!this.level().isClientSide) {
        if (isInWater()) {
            swimTimer++;
        } else {
            if(this.isBellowing()){
                this.setBellowing(false);
            }
            swimTimer--;
        }
        if (this.getTarget() instanceof WaterAnimal && !this.isTame()) {
            WaterAnimal fish = (WaterAnimal) this.getTarget();
            CompoundTag fishNbt = new CompoundTag();
            fish.addAdditionalSaveData(fishNbt);
            fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
            fish.readAdditionalSaveData(fishNbt);
        }
    } else {
        if (this.isInWaterOrBubble() && this.isBellowing()) {
            int particles = 4 + getRandom().nextInt(3);
            for (int i = 0; i <= particles; i++) {
                Vec3 particleVec = new Vec3(0, 0, 1.0F).yRot((i / (float) particles) * (Mth.PI) * 2F).add(this.position());
                double particleY = this.getBoundingBox().minY + getFluidTypeHeight(ForgeMod.WATER_TYPE.get());
                this.level().addParticle(ParticleTypes.SPLASH, particleVec.x, particleY, particleVec.z, 0, 0.3F, 0);
            }
        }
    }
    if (bellowCooldown > 0) {
        bellowCooldown--;
    }
}

public void tick() {
    LivingEntity target = EntityVoidWorm.this.getTarget();
    boolean flag = false;
    float speed = 1;
    for (Entity entity : EntityVoidWorm.this.level().getEntitiesOfClass(LivingEntity.class, EntityVoidWorm.this.getBoundingBox().inflate(2.0D))) {
        if (!entity.is(EntityVoidWorm.this) && !(entity instanceof EntityVoidWormPart) && !entity.isAlliedTo(EntityVoidWorm.this) && entity != EntityVoidWorm.this) {
            if (EntityVoidWorm.this.isMouthOpen()) {
                launch(entity, true);
                flag = true;
                wormAttack(entity, EntityVoidWorm.this.damageSources().mobAttack(EntityVoidWorm.this), 8.0F + random.nextFloat() * 8.0F);
            } else {
                EntityVoidWorm.this.openMouth(15);
            }
        }
    }
    if (target != null) {
        if (mode == AttackMode.CIRCLE) {
            if (moveTo == null || EntityVoidWorm.this.distanceToSqr(moveTo) < 16 || EntityVoidWorm.this.horizontalCollision) {
                moveTo = EntityVoidWorm.this.getBlockInViewAway(target.position(), 0.4F + random.nextFloat() * 0.2F);
            }
            int interval = EntityVoidWorm.this.getHealth() < EntityVoidWorm.this.getMaxHealth() && !EntityVoidWorm.this.isSplitter() ? 15 : 40;
            if (modeTicks % interval == 0) {
                EntityVoidWorm.this.spit(new Vec3(3, 3, 0), false);
                EntityVoidWorm.this.spit(new Vec3(-3, 3, 0), false);
                EntityVoidWorm.this.spit(new Vec3(3, -3, 0), false);
                EntityVoidWorm.this.spit(new Vec3(-3, -3, 0), false);
            }
            modeTicks++;
            if (modeTicks > maxCircleTime) {
                maxCircleTime = 60 + random.nextInt(200);
                mode = AttackMode.SLAM_RISE;
                modeTicks = 0;
                moveTo = null;
            }
        } else if (mode == AttackMode.SLAM_RISE) {
            if (moveTo == null) {
                moveTo = EntityVoidWorm.this.getBlockInViewAwaySlam(target.position(), 20 + random.nextInt(20));
            }
            if (moveTo != null) {
                if (EntityVoidWorm.this.getY() > target.getY() + 15) {
                    moveTo = null;
                    modeTicks = 0;
                    mode = AttackMode.SLAM_FALL;
                }
            }
        } else if (mode == AttackMode.SLAM_FALL) {
            speed = 2;
            EntityVoidWorm.this.lookAt(target, 360, 360);
            moveTo = target.position();
            if (EntityVoidWorm.this.horizontalCollision) {
                moveTo = new Vec3(target.getX(), EntityVoidWorm.this.getY() + 3, target.getZ());
            }
            EntityVoidWorm.this.openMouth(20);
            if (EntityVoidWorm.this.distanceToSqr(moveTo) < 4 || flag) {
                mode = AttackMode.CIRCLE;
                moveTo = null;
                modeTicks = 0;
            }
        }
    }
    if (!EntityVoidWorm.this.hasLineOfSight(target) && random.nextInt(100) == 0) {
        if (EntityVoidWorm.this.makePortalCooldown == 0) {
            Vec3 to = new Vec3(target.getX(), target.getBoundingBox().maxY + 0.1, target.getZ());
            EntityVoidWorm.this.createPortal(EntityVoidWorm.this.position().add(EntityVoidWorm.this.getLookAngle().scale(20)), to, Direction.UP);
            EntityVoidWorm.this.makePortalCooldown = 50;
            mode = AttackMode.SLAM_FALL;
        }
    }
    if (moveTo != null && EntityVoidWorm.this.portalTarget == null) {
        EntityVoidWorm.this.getMoveControl().setWantedPosition(moveTo.x, moveTo.y, moveTo.z, speed);
    }
}

public void onUpdate() {
    //CAR STUFF START
    rotationDelta *= 0.8f;
    allWheels.forEach(FordExplorerEntity.this::processWheel);

    for(int i = 0; i < 4; i++) {
        List<WheelParticleData> markedRemoved = Lists.newArrayList();
        wheelDataList[i].forEach(wheel -> wheel.onUpdate(markedRemoved));
        markedRemoved.forEach(wheelDataList[i]::remove);
    }
    //CAR STUFF END

    if (posY < -64.0D) {
        outOfWorld();
    }
    MinecraftServer minecraftserver = world.getMinecraftServer();
    if (!world.isRemote && world instanceof WorldServer && minecraftserver != null) {
        world.profiler.startSection("portal");
        int i = getMaxInPortalTime();
        if (inPortal) {
            if (minecraftserver.getAllowNether()) {
                if (!isRiding() && portalCounter++ >= i) {
                    portalCounter = i;
                    timeUntilPortal = getPortalCooldown();
                    int j;
                    if (world.provider.getDimensionType().getId() == -1) {
                        j = 0;
                    } else {
                        j = -1;
                    }

                    changeDimension(j);
                }

                inPortal = false;
            }
        } else {
            if (portalCounter > 0) {
                portalCounter -= 4;
            }

            if (portalCounter < 0) {
                portalCounter = 0;
            }
        }

        if (timeUntilPortal > 0) {
            --timeUntilPortal;
        }

        world.profiler.endSection();
    }

    if (!hasNoGravity()) {
        motionY -= 0.03999999910593033D;
    }
    if(railTracks.equals(INACTIVE)) { //Shouldn't occur
        return;
    }
    if(getPassengers().isEmpty()) {
        return;
    }
    moveAlongTrack();

    if(!world.isRemote) {
        doBlockCollisions();
        rotationPitch = 0.0F;

        handleWaterMovement();
    }

}

