    public void updateTask() {
    	boolean fixated = this.host.hasFixateTarget() && this.host.getFixateTarget() == this.attackTarget;
        double distance = this.host.getDistance(this.attackTarget);
        boolean hasSight = fixated || this.host.getEntitySenses().canSee(this.attackTarget);
        float flyingHeightOffset = this.flyingHeight;

        if(hasSight && this.chaseTimeMax >= 0 && !fixated)
            ++this.chaseTime;
        else
            this.chaseTime = 0;

        if(!hasSight)
        	flyingHeightOffset = 0;

        // If within min range or chase timed out:
        if(distance <= this.minChaseDistance || (this.chaseTimeMax >= 0 && distance <= (double)this.attackDistance && this.chaseTime >= this.chaseTimeMax)) {
            if(!this.host.useDirectNavigator())
                this.host.getNavigator().clearPath();
            else
                this.host.directNavigator.clearTargetPosition(1.0D);
        }
        else if(--this.repathTime <= 0) {
        	this.repathTime = this.repathTimeMax;
            BlockPos targetPosition = this.attackTarget.getPosition();
            if(this.host.isFlying())
                targetPosition = targetPosition.add(0, flyingHeightOffset, 0);
            if(!this.host.useDirectNavigator())
                this.host.getNavigator().tryMoveToXYZ(targetPosition.getX(), targetPosition.getY(), targetPosition.getZ(), this.speed);
            else
                this.host.directNavigator.setTargetPosition(targetPosition, this.speed);
        }

        this.host.getLookHelper().setLookPositionWithEntity(this.attackTarget, 30.0F, 30.0F);
        float rangeFactor;

        // Attack Stamina/Cooldown:
        if(this.attackStaminaMax > 0) {
        	if(!this.attackOnCooldown) {
        		this.attackStamina -= this.staminaDrainRate;
        		if(this.attackStamina <= 0)
        			this.attackOnCooldown = true;
        	}
        	else {
        		this.attackStamina += this.staminaRecoverRate;
        		if(this.attackStamina >= this.attackStaminaMax)
        			this.attackOnCooldown = false;
        	}
        }
        else if(this.attackOnCooldown)
        	this.attackOnCooldown = false;

        // Fire Projectile:
        if(!this.attackOnCooldown) {
	        if(--this.attackTime == 0) {
	            if(distance > (double)this.attackDistance || (this.checkSight && !hasSight))
	                return;

	            rangeFactor = (float)distance / this.range;
	            float outerRangeFactor = rangeFactor; // Passed to the attack, clamps targets within 10% closeness.
	            if(rangeFactor < 0.1F)
	            	outerRangeFactor = 0.1F;
	            if(outerRangeFactor > 1.0F)
	            	outerRangeFactor = 1.0F;

	            this.host.attackRanged(this.attackTarget, outerRangeFactor);
	            this.attackTime = this.host.getRangedCooldown();
	        }
	        else if(this.attackTime < 0) {
				this.attackTime = this.host.getRangedCooldown();
	        }
        }
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    this.commonResult(worldIn, caster);
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1;
    }
    int i = 1;
    if (staff.is(ModItems.NAMELESS_STAFF.get())){
        i = 7;
    } else if (rightStaff(staff)){
        i = 2 + caster.level.random.nextInt(4);
    } else if (specialStaffs(staff)){
        i = 2;
    }
    if (!isShifting(caster)) {
        for (int i1 = 0; i1 < i; ++i1) {
            EntityType<?> entityType;
            AbstractSkeletonServant summonedentity = new SkeletonServant(ModEntityType.SKELETON_SERVANT.get(), worldIn);
            BlockPos blockPos = BlockFinder.SummonRadius(caster.blockPosition(), summonedentity, worldIn);
            if (caster.isUnderWater()){
                blockPos = BlockFinder.SummonWaterRadius(caster, worldIn);
            }
            if (specialStaffs(staff)) {
                if (typeStaff(staff, SpellType.FROST)) {
                    summonedentity = new StrayServant(ModEntityType.STRAY_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.STORM)) {
                    summonedentity = new RattledServant(ModEntityType.RATTLED_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.WILD)) {
                    summonedentity = new MossySkeletonServant(ModEntityType.MOSSY_SKELETON_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.NETHER)) {
                    summonedentity = new WitherSkeletonServant(ModEntityType.WITHER_SKELETON_SERVANT.get(), worldIn);
                } else if (typeStaff(staff, SpellType.ABYSS)) {
                    summonedentity = new SunkenSkeletonServant(ModEntityType.SUNKEN_SKELETON_SERVANT.get(), worldIn);
                } else if (staff.is(ModItems.OMINOUS_STAFF.get())) {
                    summonedentity = new SkeletonPillagerServant(ModEntityType.SKELETON_PILLAGER_SERVANT.get(), worldIn);
                }
            } else {
                Player player = null;
                if (caster instanceof Player player1){
                    player = player1;
                }
                entityType = summonedentity.getVariant(player, worldIn, blockPos);
                if (entityType != null){
                    Entity entity = entityType.create(worldIn);
                    if (entity instanceof AbstractSkeletonServant summoned){
                        summonedentity = summoned;
                    }
                }
            }
            summonedentity.setTrueOwner(caster);
            summonedentity.moveTo(blockPos, 0.0F, 0.0F);
            if (summonedentity.getType() != ModEntityType.SUNKEN_SKELETON_SERVANT.get()){
                MobUtil.moveDownToGround(summonedentity);
            }
            summonedentity.setPersistenceRequired();
            summonedentity.setLimitedLife(MobUtil.getSummonLifespan(worldIn) * duration);
            summonedentity.setArrowPower(potency);
            summonedentity.finalizeSpawn(worldIn, caster.level.getCurrentDifficultyAt(caster.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
            this.buffSummon(caster, summonedentity, potency);
            this.SummonSap(caster, summonedentity);
            this.setTarget(caster, summonedentity);
            if (worldIn.addFreshEntity(summonedentity)) {
                this.uponSummon(worldIn, caster, staff, summonedentity);
            }
            this.summonAdvancement(caster, summonedentity);
        }
        this.SummonDown(caster);
        SoundUtil.playNecromancerSummon(caster);
    }
}

public void tick() {
    super.tick();
    prevSitProgress = sitProgress;
    prevLayProgress = layProgress;
    prevAbsorbAmount = getAbsorbAmount();
    if (this.isInSittingPose() && sitProgress < 5F) {
        sitProgress++;
    }
    if (!this.isInSittingPose() && sitProgress > 0) {
        sitProgress--;
    }
    if (this.getLayTime() > 0 && layProgress < 5F) {
        layProgress++;
    }
    if (this.getLayTime() <= 0 && layProgress > 0) {
        layProgress--;
    }
    Entity absorbTarget = getAbsorbTarget();
    if (this.hasEffect(ACEffectRegistry.IRRADIATED.get()) && this.tickCount % 10 == 0) {
        this.heal(1);
    }
    if (absorbCooldown > 0) {
        absorbCooldown--;
    } else {
        LivingEntity owner = getOwner();
        if (absorbTarget == null) {
            if (!level().isClientSide) {
                Entity closestIrradiated = null;
                if (owner != null && owner.distanceTo(this) < 20 && owner.hasEffect(ACEffectRegistry.IRRADIATED.get())) {
                    closestIrradiated = owner;
                } else {
                    for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(9D))) {
                        if (!(entity instanceof RaycatEntity) && entity.hasEffect(ACEffectRegistry.IRRADIATED.get()) && (closestIrradiated == null || closestIrradiated.distanceTo(this) > entity.distanceTo(this))) {
                            if (this.isTame() || !(entity instanceof Player)) {
                                closestIrradiated = entity;
                            }
                        }
                    }
                }
                setAbsorbTargetId(closestIrradiated == null ? -1 : closestIrradiated.getId());
                resetAbsorbCooldown();
            }
        } else {
            if (getAbsorbAmount() <= 0) {
                setAbsorbAmount(1.0F);
                this.playSound(ACSoundRegistry.RAYCAT_ABSORB.get());
            } else {
                this.setAbsorbAmount(Math.max(0, getAbsorbAmount() - 0.05F));
                if (getAbsorbAmount() <= 0) {
                    int currentRad = this.hasEffect(ACEffectRegistry.IRRADIATED.get()) ? this.getEffect(ACEffectRegistry.IRRADIATED.get()).getAmplifier() + 1 : 0;
                    this.heal(10);
                    this.addEffect(new MobEffectInstance(ACEffectRegistry.IRRADIATED.get(), 200, currentRad));
                    this.lookAt(absorbTarget, 30, 30);
                    if (absorbTarget instanceof LivingEntity living) {
                        MobEffectInstance effectInstance = living.getEffect(ACEffectRegistry.IRRADIATED.get());
                        if (effectInstance != null) {
                            int timeLeft = effectInstance.getDuration();
                            int level = effectInstance.getAmplifier();
                            living.removeEffect(ACEffectRegistry.IRRADIATED.get());
                            if (level > 0) {
                                living.addEffect(new MobEffectInstance(ACEffectRegistry.IRRADIATED.get(), timeLeft, level - 1));
                            }
                        }
                    }
                    setAbsorbTargetId(-1);
                    if (!level().isClientSide) {
                        resetAbsorbCooldown();
                    }
                }
            }
        }
    }
}

public void tick() {
    super.tick();
    isInsidePortal = false;
    final boolean ground = !this.isInLava() && !this.isInWater() && this.onGround();
    if (jumpCooldown > 0) {
        jumpCooldown--;
        final float f2 = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
        this.setXRot(f2);

    }
    if (ground) {
        if (!this.isLandNavigator)
            switchNavigator(true);
    } else {
        if (this.isLandNavigator)
            switchNavigator(false);
    }

    if (!this.level().isClientSide) {
        final Entity child = getChild();
        if (child == null) {
            LivingEntity partParent = this;
            final int segments = 7 + getRandom().nextInt(8);
            for (int i = 0; i < segments; i++) {
                EntityBoneSerpentPart part = new EntityBoneSerpentPart(AMEntityRegistry.BONE_SERPENT_PART.get(), partParent, 0.9F, 180, 0);
                part.setParent(partParent);
                part.setBodyIndex(i);
                if (partParent == this) {
                    this.setChildId(part.getUUID());
                }
                part.setInitialPartPos(this);
                partParent = part;
                if (i == segments - 1) {
                    part.setTail(true);
                }
                level().addFreshEntity(part);
            }
        }

        if (boardCheckCooldown <= 0) {
            boardCheckCooldown = 100 + random.nextInt(150);
            final List<EntityStraddleboard> list = this.level().getEntitiesOfClass(EntityStraddleboard.class, this.getBoundingBox().inflate(100, 15, 100), STRADDLEBOARD_FRIENDLY);
            EntityStraddleboard closestBoard = null;
            for (final EntityStraddleboard board : list) {
                if (closestBoard == null || this.distanceTo(closestBoard) > this.distanceTo(board)) {
                    closestBoard = board;
                }
            }
            boardToBoast = closestBoard;
        } else {
            boardCheckCooldown--;
        }

        if (boardToBoast != null) {
            if (this.distanceTo(boardToBoast) > 200) {
                boardToBoast = null;
            } else {
                if (jumpCooldown == 0 && (this.isInLava() || this.isInWater()) && this.distanceTo(boardToBoast) < 15) {
                    final float up = 0.7F + this.getRandom().nextFloat() * 0.8F;
                    final Vec3 vector3d1 = this.getLookAngle();
                    this.setDeltaMovement(this.getDeltaMovement().add(vector3d1.x() * 0.6D, up, vector3d1.y() * 0.6D));
                    this.getNavigation().stop();
                    this.jumpCooldown = this.getRandom().nextInt(300) + 100;
                }
                if (this.distanceTo(boardToBoast) > 5) {
                    this.getNavigation().moveTo(boardToBoast, 1.5F);
                } else {
                    this.getNavigation().stop();
                }
            }
        }
    }
}

public void onLivingUpdate() {
	if (getEntityWorld().isRemote && !isSlamming()) {
		prevStandingAngle = standingAngle;

		if (standingAngle <= 0.1F)
			standingAngle += isAmbushSpawn() ? 0.01F : 0.2F;
		if (standingAngle > 0.1F && standingAngle <= 1F)
			standingAngle += isAmbushSpawn() ? 0.1F : 0.2F;

		if (standingAngle > 1F) {
			standingAngle = 1F;

			if (isAmbushSpawn())
				setIsAmbushSpawn(false);
		}
	}

	if (getEntityWorld().isRemote && isSlamming()) {
		prevStandingAngle = standingAngle;

		if (standingAngle >= 0F && standingAngle <= 1F)
			standingAngle -= 0.2F;

		if (standingAngle < 0F) {
			setIsSlamming(false);
			standingAngle = 0F;
		}
	}

	prevScreamTimer = getScreamTimer();
	if (!getEntityWorld().isRemote) {
		if (getScreamTimer() == 0) {
			setIsScreaming(true);
			setScreamTimer(1);
		}

		if (getScreamTimer() == 1) {
			getEntityWorld().playSound(null, getPosition(), getScreamSound(), SoundCategory.HOSTILE, 0.75F, 0.5F);
		}

		if (getScreamTimer() > 0 && getScreamTimer() <= screamingTimerMax) {
			setScreamTimer(getScreamTimer() + 1);
		}

		setIsScreaming(getScreamTimer() < screamingTimerMax);

		if(getAttackTarget() != null) {
			getLookHelper().setLookPositionWithEntity(getAttackTarget(), 100F, 100F);

			if(isScreaming()) {
				getNavigator().setPath(getNavigator().getPathToEntityLiving(getAttackTarget()), 0);
			}
		}
	}

	if(this.world.isRemote && this.isScreamingBeam()) {
		this.spawnScreamParticles();
	}

	if(!this.world.isRemote && this.isScreaming() && !this.isScreamingBeam() && this.getScreamTimer() >= 25) {
		breakBlocksForAOEScream(getAOEScreamBounds());
	}

	if(!this.world.isRemote) {
		if(this.isDoingSpecialAttack()) {
			this.actionCooldown = 60;
		} else if(this.actionCooldown > 0) {
			this.actionCooldown--;
		}
	}

	super.onLivingUpdate();
}

public boolean processInteract(EntityPlayer player, EnumHand hand) {
    ItemStack stack = player.getHeldItem(hand);
    if (player.isSneaking() && hand == EnumHand.MAIN_HAND) {
        if (this.isOwner(player)) {
            if (this.getAgePercentage() > 75) {
                player.displayGUIChest(this.inventory);
            } else {
                if (this.world.isRemote) {
                    TextComponentString denied = new TextComponentString(LangUtils.translate("message.too_young.name"));
                    denied.getStyle().setColor(TextFormatting.RED);
                    ClientProxy.MC.ingameGUI.addChatMessage(ChatType.GAME_INFO, denied);
                }
            }
        } else {
            if (this.world.isRemote) {
                TextComponentString denied = new TextComponentString(LangUtils.translate("message.not_owned.name"));
                denied.getStyle().setColor(TextFormatting.RED);
                ClientProxy.MC.ingameGUI.addChatMessage(ChatType.GAME_INFO, denied);
            }
        }
    } else {
        if (stack.isEmpty() && hand == EnumHand.MAIN_HAND && this.world.isRemote) {
            if (this.isOwner(player)) {
                RebornMod.NETWORK_WRAPPER.sendToServer(new BiPacketOrder(this));
            } else {
                TextComponentString denied = new TextComponentString(LangUtils.translate("message.not_owned.name"));
                denied.getStyle().setColor(TextFormatting.RED);
                ClientProxy.MC.ingameGUI.addChatMessage(ChatType.GAME_INFO, denied);
            }
        } else if (!stack.isEmpty()&& (this.metabolism.isThirsty() || this.metabolism.isHungry())) {
            if (!this.world.isRemote) {
                Item item = stack.getItem();
                boolean fed = false;
                if (item == Items.POTIONITEM) {
                    fed = true;
                    this.metabolism.increaseWater(1000);
                    this.setAnimation(EntityAnimation.DRINKING.get());
                } else if (FoodHelper.isEdible(this, this.dinosaur.getDiet(), item)) {
                    fed = true;
                    this.metabolism.eat(FoodHelper.getHealAmount(item));
                    this.setAnimation(EntityAnimation.EATING.get());
                    FoodHelper.applyEatEffects(this, item);
                }
                if (fed) {
                    this.dataManager.set(WATCHER_WAS_FED, true);
                    if (!player.capabilities.isCreativeMode) {
                        stack.shrink(1);
                        if (item == Items.POTIONITEM) {
                            player.inventory.addItemStackToInventory(new ItemStack(Items.GLASS_BOTTLE));
                        }
                    }
                    if (!this.isOwner(player)) {
                        if (this.rand.nextFloat() < 0.30) {
                            if (this.dinosaur.getDinosaurType() == Dinosaur.DinosaurType.AGGRESSIVE) {
                                if (this.rand.nextFloat() * 4.0F < (float) this.herd.members.size() / this.dinosaur.getMaxHerdSize()) {
                                    this.herd.enemies.add(player);
                                } else {
                                    this.attackEntityAsMob(player);
                                }
                            } else if (this.dinosaur.getDinosaurType() == Dinosaur.DinosaurType.SCARED) {
                                this.herd.fleeing = true;
                                this.herd.enemies.add(player);
                            }
                        }
                    }
                    player.swingArm(hand);
                }
            }
        }
    }

    return false;
}

public InteractionResult useOn(UseOnContext context) {
    Player player = context.getPlayer();
    InteractionHand hand = context.getHand();
    Level world = context.getLevel();
    BlockPos pos = context.getClickedPos();
    Direction facing = context.getClickedFace();
    ItemStack itemStack = player.getItemInHand(hand);

    BlockState blockState = world.getBlockState(pos);

    if (isBroken(itemStack)) {
        return InteractionResult.PASS;
    }

    boolean canChannel = getUseDuration(itemStack) > 0;
    if (!canChannel || player.isCrouching()) {
        ToolData toolData = getToolData(itemStack);
        Collection<ToolAction> tools = toolData.getValues().stream()
                .filter(tool -> toolData.getLevel(tool) > 0)
                .sorted(player.isCrouching() ? Comparator.comparing(ToolAction::name).reversed() : Comparator.comparing(ToolAction::name))
                .collect(Collectors.toList());

        for (ToolAction tool : tools) {
            BlockState block = blockState.getToolModifiedState(context, tool, false);
            if (block != null) {
                if (ToolActions.AXE_STRIP.equals(tool)) {
                    world.playSound(player, pos, SoundEvents.AXE_STRIP, SoundSource.BLOCKS, 1.0F, 1.0F);
                } else if (ToolActions.AXE_SCRAPE.equals(tool)) {
                    world.playSound(player, pos, SoundEvents.AXE_SCRAPE, SoundSource.BLOCKS, 1.0F, 1.0F);
                    world.levelEvent(player, 3005, pos, 0);
                } else if (ToolActions.AXE_WAX_OFF.equals(tool)) {
                    world.playSound(player, pos, SoundEvents.AXE_SCRAPE, SoundSource.BLOCKS, 1.0F, 1.0F);
                    world.levelEvent(player, 3005, pos, 0);
                } else if (ToolActions.HOE_DIG.equals(tool)) {
                    world.playSound(player, pos, SoundEvents.HOE_TILL, SoundSource.BLOCKS, 1.0F, 1.0F);
                } else if (ToolActions.SHOVEL_DIG.equals(tool)) {
                    world.playSound(player, pos, SoundEvents.SHOVEL_FLATTEN, SoundSource.BLOCKS, 1.0F, 1.0F);
                } else {
                    SoundEvent sound = blockState.getSoundType(world, pos, player).getHitSound();
                    world.playSound(player, pos, sound, SoundSource.BLOCKS, 1.0F, 1.0F);
                }

                if (!world.isClientSide) {
                    world.setBlock(pos, block, 11);
                    applyDamage(blockDestroyDamage, context.getItemInHand(), player);
                    applyUsageEffects(player, itemStack, 2);
                }

                return InteractionResult.sidedSuccess(world.isClientSide);
            }
        }

        if (tools.contains(TetraToolActions.dowse)) {
            if (dowseBlock(player, world, blockState, pos)) {
                applyDamage(blockDestroyDamage, itemStack, player);
                applyUsageEffects(player, itemStack, 2);
                return InteractionResult.sidedSuccess(world.isClientSide);
            }
        }

        int denailingLevel = getEffectLevel(itemStack, ItemEffect.denailing);
        if (denailingLevel > 0 && player.getAttackStrengthScale(0) > 0.9) {
            if (denailBlock(player, world, pos, hand, facing)) {
                applyDamage(blockDestroyDamage, itemStack, player);
                applyUsageEffects(player, itemStack, 2);
                player.resetAttackStrengthTicker();
                return InteractionResult.sidedSuccess(world.isClientSide);
            }
        }
    }

    return super.useOn(context);
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float damage = SpellConfig.FireballDamage.get().floatValue() * WandUtil.damageMultiply();
    int potency = spellStat.getPotency();
    int burning = spellStat.getBurning();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
    }
    Vec3 vector3d = caster.getViewVector( 1.0F);
    AbstractHurtingProjectile smallFireballEntity = new ModFireball(worldIn,
            caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.5F,
            caster.getZ() + vector3d.z / 2,
            vector3d.x,
            vector3d.y,
            vector3d.z);
    if (CuriosFinder.hasUnholySet(caster)){
        smallFireballEntity = new HellBolt(caster.getX() + vector3d.x / 2,
                caster.getEyeY() - 0.5F,
                caster.getZ() + vector3d.z / 2,
                vector3d.x,
                vector3d.y,
                vector3d.z, worldIn);
    }
    smallFireballEntity.setOwner(caster);
    if (smallFireballEntity instanceof ModFireball fireball) {
        if (isShifting(caster)) {
            fireball.setDangerous(false);
        }
        fireball.setExtraDamage(potency);
        fireball.setFiery(burning);
    } else if (smallFireballEntity instanceof HellBolt hellBolt){
        hellBolt.setDamage(damage + potency);
        hellBolt.setFiery(burning);
    }
    worldIn.addFreshEntity(smallFireballEntity);
    if (rightStaff(staff)) {
        for (int i = 0; i < 2; ++i) {
            AbstractHurtingProjectile smallFireballEntity2 = new ModFireball(worldIn,
                    caster.getX() + vector3d.x / 2 + worldIn.random.nextGaussian(),
                    caster.getEyeY() - 0.5F,
                    caster.getZ() + vector3d.z / 2 + worldIn.random.nextGaussian(),
                    vector3d.x,
                    vector3d.y,
                    vector3d.z);
            if (CuriosFinder.hasUnholySet(caster)){
                smallFireballEntity2 = new HellBolt(caster.getX() + vector3d.x / 2 + worldIn.random.nextGaussian(),
                        caster.getEyeY() - 0.5F,
                        caster.getZ() + vector3d.z / 2 + worldIn.random.nextGaussian(),
                        vector3d.x,
                        vector3d.y,
                        vector3d.z, worldIn);
            }
            smallFireballEntity2.setOwner(caster);
            if (smallFireballEntity2 instanceof ModFireball fireball) {
                if (isShifting(caster)) {
                    fireball.setDangerous(false);
                }
                fireball.setExtraDamage(potency);
                fireball.setFiery(burning);
            } else if (smallFireballEntity2 instanceof HellBolt hellBolt){
                hellBolt.setDamage(damage + potency);
                hellBolt.setFiery(burning);
            }
            worldIn.addFreshEntity(smallFireballEntity2);
