    SoundEvent soundEvent = SoundEvents.BLAZE_SHOOT;
    if (CuriosFinder.hasUnholySet(caster)) {
        soundEvent = ModSounds.HELL_BOLT_SHOOT.get();
    }
    this.playSound(worldIn, caster, soundEvent, 2.0F, this.projPitch(worldIn.getRandom()));
}

public void onUpdate() {
	super.onUpdate();

	if (world.isRemote && getSinkingTicks() <= 0) {
		this.rowTicks++;

		if (!isSilent() && posX != lastTickPosX && posZ != lastTickPosZ) {
			float rowAngle1 = MathHelper.cos(this.rowTicks * rowSpeed);
			float rowAngle2 = MathHelper.cos((this.rowTicks + 1) * rowSpeed);
			if(rowAngle1 <= 0.8f && rowAngle2 > 0.8f) {
				world.playSound(posX, posY, posZ, SoundEvents.ENTITY_GENERIC_SWIM, getSoundCategory(), 0.2F, 0.8F + 0.4F * this.rand.nextFloat(), false);
			}
		}
	}

	if(shutUpFFSTime > 0) {
		shutUpFFSTime--;
		livingSoundTime = -getTalkInterval();
	}

	if (getEntityWorld().containsAnyLiquid(getEntityBoundingBox()) && getSinkingTicks() <= 200)
		motionY += 0.06D;

	if (getSinkingTicks() > 0) {
		motionX *= 0.975D;
		motionZ *= 0.975D;
	}

	if (isGreeblingAboveWater() && getSinkingTicks() <= 200) {
		if (motionY < 0.0D)
			motionY = 0.0D;
		fallDistance = 0.0F;
	}
	else {
		motionY = -0.0075D;
	}

	limbSwing += 0.5D;
	if (posX != lastTickPosX && posZ != lastTickPosZ)
		limbSwingAmount += 0.5D;

	if(!getEntityWorld().isRemote) {
		if (getSinkingTicks() == 200 && isGreeblingAboveWater())
			world.playSound(null, getPosition(), SoundRegistry.CORACLE_SINK, SoundCategory.NEUTRAL, 1F, 1F);

		if (getSinkingTicks() > 0 && getSinkingTicks() < 400)
			setSinkingTicks(getSinkingTicks() + 1);

		if (getSinkingTicks() == 5)
			getEntityWorld().setEntityState(this, EVENT_DISAPPEAR);

		if (getSinkingTicks() >= 200 && getSinkingTicks() <= 400 && isGreeblingAboveWater())
			getEntityWorld().setEntityState(this, EVENT_SPOUT);

		if (getSinkingTicks() > 0 && !hasSetAIForEmptyBoat) {
			tasks.removeTask(avoidPlayer);
			tasks.removeTask(waterWander);
			tasks.removeTask(lookIdle);
			if(getNavigator().getPath() != null) {
				getNavigator().clearPath();
			}
			hasSetAIForEmptyBoat = true;
		}

		if (getSinkingTicks() >= 400)
			setDead();

		List<EntityPlayer> nearPlayers = getEntityWorld().getEntitiesWithinAABB(EntityPlayer.class, getEntityBoundingBox().grow(2.5, 2.5, 2.5), e -> !e.capabilities.isCreativeMode && !e.isInvisible());
		if (getSinkingTicks() == 0 && !nearPlayers.isEmpty()) {
			setSinkingTicks(getSinkingTicks() + 1);
			getEntityWorld().playSound(null, posX, posY, posZ, SoundRegistry.GREEBLING_VANISH, SoundCategory.NEUTRAL, 1F, 1F);
		}
	}
}

public void aiStep() {
	if (!this.level().isClientSide && this.isAlive() && this.getAge() < 0 && !this.isAttachedToCactus())
		this.setAge(this.age - 1);

	super.aiStep();

	if (this.getInLoveTime() == 0)
		this.setSuperInLove(false);

	this.jumpAmount0 = this.jumpAmount;
	if (this.jumpAnim) {
		if (this.jumpAmount < 1.0F)
			this.jumpAmount = Math.min(this.jumpAmount + 0.5F, 1.0F);
		else
			this.jumpAnim = false;
	} else if (this.jumpAmount > 0.0F) {
		this.jumpAmount = Math.max(this.jumpAmount - 0.1F, 0.0F);
	}

	if (this.isAlive()) {
		if (!this.level().isClientSide) {
			if (this.suckleCooldown > 0)
				this.suckleCooldown--;

			if (this.getHealth() < this.getMaxHealth() && this.isAttachedToCactus() && this.suckleHealTicks-- <= 0) {
				this.heal(1.0F);
				this.suckleHealTicks = 120;
				double d0 = this.random.nextGaussian() * 0.02D;
				double d1 = this.random.nextGaussian() * 0.02D;
				double d2 = this.random.nextGaussian() * 0.02D;
				NetworkUtil.spawnParticle((ServerLevel) this.level(), ParticleTypes.HEART, List.of(new ParticleInstance(this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), d0, d1, d2)));
			}
		} else {
			if (this.isLeaping() || this.hurtTime > 0) {
				boolean cold = this.level().getBiome(this.blockPosition()).value().coldEnoughToSnow(this.blockPosition());
				for (int i = 0; i < 3; i++) {
					double x = -this.getLookAngle().x * 0.7D + (this.random.nextDouble() - 0.5D) * 0.6D;
					double y = 0.6D + (this.random.nextDouble() - 0.5D) * 0.6D;
					double z = -this.getLookAngle().z * 0.7D + (this.random.nextDouble() - 0.5D) * 0.6D;
					if (this.isBaby()) {
						x *= 0.4D;
						y *= 0.4D;
						z *= 0.4D;
					}
					this.level().addParticle(cold ? AtmosphericParticleTypes.COLD_COCHINEAL_TRAIL.get() : AtmosphericParticleTypes.COCHINEAL_TRAIL.get(), this.getX() + x, this.getY() + y, this.getZ() + z, 0.0D, 0.0D, 0.0D);
				}
			}

			if (this.isAttachedToCactus() && this.isBaby() && this.random.nextInt(160) == 0) {
				this.level().addParticle(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0.0D, 0.0D, 0.0D);
			}
		}

		if (this.isAttachedToCactus() && this.random.nextInt(200) == 0) {
			this.playSound(AtmosphericSoundEvents.COCHINEAL_SUCKLE.get(), 0.85F, 0.4F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
		}

		if (!this.getEatingStack().isEmpty() && this.tickCount % 12 == 0) {
			this.playSound(AtmosphericSoundEvents.COCHINEAL_SUCKLE.get(), 1.4F, 0.4F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
			if (this.level().isClientSide) {
				for (int i = 0; i < 6; ++i) {
					Vec3 vec3 = new Vec3((this.random.nextFloat() - 0.5D) * 0.1D, Math.random() * 0.1D + 0.1D, (this.random.nextFloat() - 0.5D) * 0.1D);
					vec3 = vec3.xRot(-this.getXRot() * Mth.DEG_TO_RAD);
					vec3 = vec3.yRot(-this.getYRot() * Mth.DEG_TO_RAD);
					double d0 = (double) (-this.random.nextFloat()) * 0.6D - 0.3D;
					Vec3 vec31 = new Vec3((this.random.nextFloat() - 0.5D) * 0.8D, d0, 0.8D + (this.random.nextFloat() - 0.5D) * 0.4D);
					vec31 = vec31.yRot(-this.yBodyRot * Mth.DEG_TO_RAD);
					vec31 = vec31.add(this.getX(), this.getY() + 1.0F, this.getZ());
					this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getEatingStack()), vec31.x, vec31.y, vec31.z, vec3.x, vec3.y + 0.05D, vec3.z);
				}
			}
		}
	}
}

default void handleTick() {
	AbstractHorse horse = (AbstractHorse) this;

	if (horse.onGround() || horse.isInFluidType())
		this.setJumpStrength(-1.0F);

	if (horse.isEffectiveAi() && horse.isAlive()) {
		boolean resetkickcounter = true;
		if (!horse.isBaby() && !this.isKicking()) {
			LivingEntity rider = horse.getControllingPassenger();
			boolean jumpkick = this.canJumpKick();
			boolean isfleeing = this.isFleeing() && !horse.isImmobile() && !horse.getNavigation().isDone();

			if (!horse.isStanding() || jumpkick) {
				List<LivingEntity> nearby = horse.level().getEntitiesOfClass(LivingEntity.class, horse.getBoundingBox().inflate(0.9F), KICKABLE_PREDICATE);
				boolean shouldkick = false;
				boolean backkick = true;

				for (LivingEntity living : nearby) {
					Vec3 attackAngleVector = living.position().subtract(horse.position()).normalize();
					attackAngleVector = new Vec3(attackAngleVector.x, 0.0D, attackAngleVector.z);
					double angle = attackAngleVector.dot(Vec3.directionFromRotation(0.0F, horse.getVisualRotationYInDegrees()).normalize());

					if (angle > 0.7D) {
						if (isfleeing || jumpkick || (rider != null && rider.zza > 0.0F)) {
							shouldkick = true;
							backkick = false;
							break;
						}
					} else if (angle < -0.7D && !jumpkick) {
						if (isfleeing) {
							shouldkick = true;
						} else if (rider == null) {
							if (!living.isDiscrete()) {
								this.setKickCounter(this.getKickCounter() - 1);
								if (this.getKickCounter() <= 0)
									shouldkick = true;
							}
							if (!shouldkick)
								resetkickcounter = false;
						} else if (rider.zza <= 0.0F) {
							shouldkick = true;
						}
					}
				}

				if (shouldkick) {
					this.kick(backkick, rider == null && !isfleeing);
					this.playKickingSound();
				}
			}
		} else {
			this.setKickTime(this.getKickTime() + 1);
			if (this.getKickTime() > 10) {
				this.setKickTime(0);
				horse.getAttribute(Attributes.MOVEMENT_SPEED).removeModifier(SPEED_MODIFIER_KICKING);
			}
		}

		if (resetkickcounter) {
			this.setKickCounter(20);
		}
	}

	float f = this.getBackKickAnim();
	this.setBackKickAnimO(f);
	if (f > 0)
		this.setBackKickAnim(f - 1);

	float f1 = this.getFrontKickAnim();
	this.setFrontKickAnimO(f1);
	if (f1 > 0)
		this.setFrontKickAnim(f1 - 1);
}

public void tick() {
	super.tick();

	Vector3d motion = getDeltaMovement();
	double motionX = motion.x();
	double motionY = motion.y();
	double motionZ = motion.z();

	if (jumpCooldown == 0) {
		motionY = 1.6;
		fallDistance = -100;
		jumpCooldown = 320;
		shootStageTimer = 60;

		level.playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_CORALLUS_TAUNT.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
	}
	else {
		jumpCooldown--;
	}

	if (shootStageTimer > 0) {
		if (shotCooldown == 0 && !level.isClientSide) {
			List<PlayerEntity> targets = level.getEntitiesOfClass(PlayerEntity.class, getBoundingBox().inflate(40), PlayerUtil::shouldPlayerBeAffected);

			for (PlayerEntity target : targets) {
				CorallusShotEntity shot = new CorallusShotEntity(this, target, 12);

				shot.moveTo(getX(), getY() + getEyeHeight(), getZ(), random.nextFloat() * 360, 0);
				level.addFreshEntity(shot);
			}

			shotCooldown = 10 + random.nextInt(15);
		}
		else {
			shotCooldown--;
		}

		shootStageTimer--;
	}

	rageStateCooldown--;

	if (rageStateCooldown <= 0) {
		if (isEnraged()) {
			if (!level.isClientSide)
				setEnraged(false);

			rageStateCooldown = 200;
		}
		else {
			if (!level.isClientSide)
				setEnraged(true);

			rageStateCooldown = 80;
			EntityUtil.applyPotions(this, new EffectBuilder(Effects.DAMAGE_BOOST, 80).level(4));
		}
	}

	if (isInWater()) {
		if (motionX > -1.2000000476837158 && motionX < 1.2000000476837158)
			motionX *= 1.2000000476837158;

		if (motionZ > -1.2000000476837158 && motionZ < 1.2000000476837158)
			motionZ *= 1.2000000476837158;
	}

	setDeltaMovement(motionX, motionY, motionZ);

	if (!level.isClientSide()) {
		float healthPercent = getHealth() / getMaxHealth();

		if (healthPercent != bossInfo.getPercent())
			bossInfo.setPercent(healthPercent);
	}
}

public void tick(boolean serverSide) {
    ticks++;
    if (ticks < 5)
        return;
    if (!serverSide || level.getGameTime() % 3 != 0)
        return;

    boolean destroyPortal = false;
    boolean placingFrame = !framePos.isEmpty();
    if (placingFrame) {
        BlockPos pos = framePos.get(0);
        framePos.remove(pos);
        BlockState bs = level.getBlockState(pos);
        if (bs.is(BlockTagProvider.DECORATIVE_AN) || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
            tick(true);
            if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                tile.tickDuration = 20 * 60;
                tile.gameTime = level.getGameTime();
                tile.updateBlock();
            }
            return;
        }
        if (bs.canBeReplaced() || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
            level.setBlock(pos, BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState(), 3);
            if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                tile.tickDuration = 20 * 60;
                tile.gameTime = level.getGameTime();
                tile.updateBlock();
            }
            level.playSound(null, pos, BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
            ParticleUtil.spawnTouchPacket(level, pos, ParticleColor.makeRandomColor(255, 255, 255, level.random));
            placedBlocks.add(pos);
            return;
        } else {
            destroyPortal = true;
            ServerLevel serverLevel = (ServerLevel) level;
            serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
        }
    }
    boolean placingPortal = !portalPos.isEmpty() && framePos.isEmpty() && !destroyPortal;
    if (placingPortal) {
        for (BlockPos pos : portalPos) {
            if (level.getBlockState(pos).canBeReplaced()) {
                level.setBlock(pos, BlockRegistry.PORTAL_BLOCK.defaultBlockState().setValue(PortalBlock.AXIS, direction.getAxis()), 2);
                level.playSound(null, pos, BlockRegistry.PORTAL_BLOCK.get().defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                placedBlocks.add(pos);
            } else {
                destroyPortal = true;
                ServerLevel serverLevel = (ServerLevel) level;
                serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
                break;
            }
        }
        portalPos.clear();
    }
    if (destroyPortal) {
        for (BlockPos pos : placedBlocks) {
            level.destroyBlock(pos, false);
        }
        level.playSound(null, targetPos, SoundRegistry.GAIA_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
        portalPos.clear();
        framePos.clear();
        return;
    }
    if (portalPos.isEmpty()) {
        level.playSound(null, targetPos.above(2), SoundRegistry.TEMPESTRY_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
        for (BlockPos pos : placedBlocks) {
            if (level.getBlockEntity(pos) instanceof PortalTile portalTile) {
                portalTile.setFromScroll(warpScrollData);
            }
        }
    }
}

public void tick() {
    if (peppermintCooldown > 0) {
        peppermintCooldown--;
    }
    if (hexCooldown > 0) {
        hexCooldown--;
    }
    if (potionCooldown > 0) {
        potionCooldown--;
    }
    if (checkReachCooldown > 0) {
        checkReachCooldown--;
    }
    LivingEntity target = licowitch.getTarget();
    if(duration > 200 && checkReachCooldown == 0 && target != null){
        checkReachCooldown = 100 + licowitch.getRandom().nextInt(40);
        if(licowitch.canTeleport() && !licowitch.canReach(target.blockPosition())){
            licowitch.setTeleportingToPos(Vec3.atBottomCenterOf(target.blockPosition()));
            return;
        }
    }
    if (target != null && target.isAlive() && licowitch.getTeleportingToPos() == null) {
        double distance = licowitch.distanceTo(target);
        double distanceXZ = Mth.sqrt((float) licowitch.distanceToSqr(target.getX(), licowitch.getY(), target.getZ()));
        double attackDistance = licowitch.getBbWidth() + target.getBbWidth() + 5;
        licowitch.lookAt(target, 30.0F, 30.0F);
        if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT || enqueuedAttackType == 0 && distance < attackDistance - 1 || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && distanceXZ < 6.0F) {
            licowitch.getMoveControl().strafe(-4, 0.0F);
            licowitch.getNavigation().stop();
        } else if (distance > attackDistance || !this.licowitch.hasLineOfSight(target)) {
            this.licowitch.getNavigation().moveTo(target, 1.0D);
        }
        if (this.licowitch.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
            if (enqueuedAttackType == 0) {
                if (this.licowitch.hasLineOfSight(target)) {
                    if (peppermintCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                        enqueuedAttackType = 1;
                        peppermintCooldown = 80;
                    } else if (hexCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                        enqueuedAttackType = 2;
                        hexCooldown = 200;
                    } else if (potionCooldown <= 0 && distance < 10.0D && !target.hasEffect(MobEffects.HUNGER)) {
                        enqueuedAttackType = 3;
                        licowitch.updateHeldItems = false;
                        licowitch.setItemInHand(InteractionHand.MAIN_HAND, LicowitchEntity.hungerPotion.copy());
                        potionCooldown = 100;
                    }
                }
            } else {
                if (enqueuedAttackType == 1 && distance < 10.0D) {
                    this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_0);
                }
                if ((enqueuedAttackType == 2 || enqueuedAttackType == 4) && distance < 7.0D) {
                    this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_1);
                }
                if (enqueuedAttackType == 3 && distance < 10.0D) {
                    this.licowitch.setAnimation(licowitch.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                }
            }
        }
        if (enqueuedAttackType == 1 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0 && licowitch.getAnimationTick() == 18) {
            peppermintAttack(target);
            enqueuedAttackType = 0;
        }
        if (enqueuedAttackType == 2 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && licowitch.getAnimationTick() == 36) {
            hexAttack(target);
            enqueuedAttackType = 0;
        }
        if (enqueuedAttackType == 3 && (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && licowitch.getAnimationTick() == 6) {
            potionAttack(target);
            licowitch.updateHeldItems = true;
            enqueuedAttackType = 0;
        }
    }
    duration++;
}

public void tick() {
    super.tick();
    if (jumpCooldown > 0) {
        jumpCooldown--;
        float f2 = (float) -((float) this.getDeltaMovement().y * (double) Mth.RAD_TO_DEG);
        this.setXRot(f2);
    }
    if (this.isNoAi()) {
        this.setAirSupply(this.getMaxAirSupply());
    } else {

        if (this.isInWaterRainOrBubble()) {
            this.setMoistness(2400);
        } else {
            this.setMoistness(this.getMoistness() - 1);
            if (this.getMoistness() <= 0) {
                this.hurt(damageSources().dryOut(), 1.0F);
            }

            if (this.onGround()) {
                this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
                this.setYRot( this.random.nextFloat() * 360.0F);
                this.setOnGround(false);
                this.hasImpulse = true;
            }
        }

        if (this.level().isClientSide && this.isInWater() && this.getDeltaMovement().lengthSqr() > 0.03D) {
            Vec3 vector3d = this.getViewVector(0.0F);
            final float yRotRad = this.getYRot() * Mth.DEG_TO_RAD;
            final float f = Mth.cos(yRotRad) * 0.9F;
            final float f1 = Mth.sin(yRotRad) * 0.9F;
            final float f2 = 1.2F - this.random.nextFloat() * 0.7F;

            for (int i = 0; i < 2; ++i) {
                this.level().addParticle(ParticleTypes.DOLPHIN, this.getX() - vector3d.x * (double) f2 + (double) f, this.getY() - vector3d.y, this.getZ() - vector3d.z * (double) f2 + (double) f1, 0.0D, 0.0D, 0.0D);
                this.level().addParticle(ParticleTypes.DOLPHIN, this.getX() - vector3d.x * (double) f2 - (double) f, this.getY() - vector3d.y, this.getZ() - vector3d.z * (double) f2 - (double) f1, 0.0D, 0.0D, 0.0D);
            }
        }

    }
    LivingEntity attackTarget = this.getTarget();
    if (attackTarget != null && distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 2) {
        if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 4) {
            float damage =(float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            if(attackTarget instanceof Drowned || attackTarget instanceof Guardian){
                damage *= 2F;
            }
            boolean flag = attackTarget.hurt(this.damageSources().mobAttack(this), damage);
            if (flag) {
                this.doEnchantDamageEffects(this, attackTarget);
                this.playSound(SoundEvents.DOLPHIN_ATTACK, 1.0F, 1.0F);
            }
        }
        if (this.getAnimation() == ANIMATION_TAILSWING && this.getAnimationTick() == 6) {
            float damage =(float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            if(attackTarget instanceof Drowned || attackTarget instanceof Guardian){
                damage *= 2F;
            }
            boolean flag = attackTarget.hurt(this.damageSources().mobAttack(this), damage);
            if (flag) {
                this.doEnchantDamageEffects(this, attackTarget);
                this.playSound(SoundEvents.DOLPHIN_ATTACK, 1.0F, 1.0F);
            }
            final float yRotRad = this.getYRot() * Mth.DEG_TO_RAD;
            attackTarget.knockback(1F, Mth.sin(yRotRad), -Mth.cos(yRotRad));
            float knockbackResist = (float) Mth.clamp((1.0D - this.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)), 0, 1);
            this.getTarget().setDeltaMovement(this.getTarget().getDeltaMovement().add(0, knockbackResist * 0.4F, 0));

        }
    }
    if (attackTarget != null && attackTarget instanceof Player && attackTarget.hasEffect(AMEffectRegistry.ORCAS_MIGHT.get())) {
        attackTarget.removeEffect(AMEffectRegistry.ORCAS_MIGHT.get());
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public static void serverTick(Level level, BlockPos pos, BlockState state, CinderFurnaceBlockEntity entity) {
	boolean changed = false;
	boolean isLit;
	boolean wasLit;
	if (entity.litTimeRemaining > 0) {
		wasLit = true;
		entity.litTimeRemaining--;
		isLit = entity.litTimeRemaining > 0;
	} else {
		wasLit = false;
		isLit = false;
	}

	ItemStack fuel = entity.items.get(1);
	ItemStack ingredient = entity.items.get(0);
	boolean hasIngredient = !ingredient.isEmpty();
	boolean hasFuel = !fuel.isEmpty();
	if (isLit || hasFuel && hasIngredient) {
		if (hasIngredient) {
			SingleRecipeInput input = new SingleRecipeInput(ingredient);
			RecipeHolder<? extends AbstractCookingRecipe> recipe = entity.quickCheck.getRecipeFor(input, (ServerLevel) level).orElse(null);
			if (recipe != null) {
				int maxStackSize = entity.getMaxStackSize();
				ItemStack burnResult = recipe.value().assemble(input);
				if (!burnResult.isEmpty() && entity.canBurn(level, maxStackSize, burnResult)) {
					if (!isLit) {
						int newLitTime = entity.getBurnDuration(level.fuelValues(), fuel);
						entity.litTimeRemaining = newLitTime;
						entity.litTotalTime = newLitTime;
						if (newLitTime > 0) {
							consumeFuel(entity.items, fuel);
							isLit = true;
							changed = true;
						}
					}

					if (isLit) {
						// TF - cook faster
						entity.cookingTimer += entity.getCurrentSpeedMultiplier(level);
						if (entity.cookingTimer >= entity.cookingTotalTime) { // TF - change to geq since we can increment by >1
							entity.cookingTimer = 0;
							entity.cookingTotalTime = recipe.value().cookingTime();
							entity.burn(ingredient, burnResult);
							entity.setRecipeUsed(recipe);
							changed = true;
						}
					} else {
						entity.cookingTimer = 0;
					}
				} else {
					entity.cookingTimer = 0;
				}
			}
		} else {
			entity.cookingTimer = 0;
		}
	} else if (entity.cookingTimer > 0) {
		entity.cookingTimer = Mth.clamp(entity.cookingTimer - 2, 0, entity.cookingTotalTime);
	}

	if (wasLit != isLit) {
		changed = true;
		state = state.setValue(AbstractFurnaceBlock.LIT, isLit);
		level.setBlock(pos, state, 3);
	}

	// TF - occasionally cinderize nearby logs
	if (isLit && entity.litTimeRemaining % 5 == 0) {
		entity.cinderizeNearbyLog(level, pos);
	}

	if (changed) {
		setChanged(level, pos, state);
	}

}

public void aiStep() {
	super.aiStep();
	this.eatTicks++;

	if (this.dropEatingLootCooldown > 0) this.dropEatingLootCooldown--;

	if (!this.isInWater() && this.onGround() && this.verticalCollision) {
		this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.05F, 0.4F, (this.random.nextFloat() * 2.0F - 1.0F) * 0.05F));
		this.setOnGround(false);
		this.hasImpulse = true;
		this.playSound(this.getFlopSound(), this.getSoundVolume(), this.getVoicePitch());
	}

	if (this.level().getGameTime() % 20 == 0) {
		LivingEntity caughtEntity = this.getCaughtEntity();
		if (caughtEntity != null && (!this.isPickerelweedNearby() || this.isHidingInPickerelweed())) {
			this.level().playSound(null, this.blockPosition(), UASoundEvents.PIKE_BITE.get(), SoundSource.HOSTILE, 0.8F, 0.90F);
			if (this.level().isClientSide && caughtEntity.getHealth() <= 1 && this.getVariant().is(UAPikeVariants.SPECTRAL)) {
				for (int i = 0; i < 3; ++i) {
					this.level().addParticle(UAParticleTypes.SPECTRAL_CONSUME.get(), caughtEntity.getX() + (caughtEntity.getRandom().nextDouble() - 0.5D) * (double) caughtEntity.getBbWidth(), caughtEntity.getY() + caughtEntity.getRandom().nextDouble() * (double) caughtEntity.getBbHeight() - 0.25D, caughtEntity.getZ() + (caughtEntity.getRandom().nextDouble() - 0.5D) * (double) caughtEntity.getBbWidth(), (this.getCaughtEntity().getRandom().nextDouble() - 0.5D) * 2.0D, -caughtEntity.getRandom().nextDouble(), (caughtEntity.getRandom().nextDouble() - 0.5D) * 2.0D);
				}
			}
			caughtEntity.hurt(this.damageSources().mobAttack(this), 1.0F);
		}
	}

	if (this.getAttackCooldown() > 0) {
		this.setAttackCooldown(this.getAttackCooldown() - 1);
	}

	ItemStack itemstack = this.getItemBySlot(EquipmentSlot.MAINHAND);
	if (!this.level().isClientSide && this.isAlive() && this.isEffectiveAi() && !itemstack.isEmpty() && this.canEatItem(itemstack) && this.isInWater()) {
		if (this.eatTicks > 600) {
			ItemStack itemstackFood = itemstack.finishUsingItem(this.level(), this);
			if (!itemstack.isEmpty()) {
				this.setItemSlot(EquipmentSlot.MAINHAND, itemstackFood);
			}

			if (this.dropEatingLootCooldown <= 0) {
				if (this.random.nextFloat() < 0.2F) {
					for (ItemStack stacks : this.generateFishingLoot()) {
						if (stacks.getCount() > 0) {
							stacks.shrink(stacks.getCount() - 1);
						}
						this.spitOutItem(stacks);
					}
				} else {
					this.spitOutItem(new ItemStack(Items.BONE_MEAL));
				}
				this.dropEatingLootCooldown = 3600 + this.getRandom().nextInt(400);
			}

			this.heal(6);
			this.eatTicks = 0;
		} else if (this.eatTicks > 560 && this.random.nextFloat() < 0.1F) {
			this.playSound(this.getEatingSound(itemstack), 1.0F, 1.0F);
			this.level().broadcastEntityEvent(this, (byte) 45);
		}
	}

	if (this.isMoving() && this.isInWater() && this.getVariant().is(UAPikeVariants.SUPERCHARGED)) {
		Vec3 vec3d1 = this.getViewVector(0.0F);

		for (int i = 0; i < 2; ++i) {
			this.level().addParticle(ParticleTypes.BUBBLE, this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() - vec3d1.x * 1.5D, this.getY() + this.random.nextDouble() * (double) this.getBbHeight() - vec3d1.y * 1.5D, this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() - vec3d1.z * 1.5D, 0.0D, 0.0D, 0.0D);
		}
	}

	if (this.getVariant().is(UAPikeVariants.OBSIDIAN) && this.isLit()) {
		if (this.level().isClientSide) {
			for (int i = 0; i < 2; i++) {
				this.level().addParticle(ParticleTypes.PORTAL, this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth(), this.getY() + this.random.nextDouble() * (double) this.getBbHeight() - 0.25D, this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth(), (this.random.nextDouble() - 0.5D) * 2.0D, -this.random.nextDouble(), (this.random.nextDouble() - 0.5D) * 2.0D);
			}
		}
	}
}

public void onLivingUpdate() {
    super.onLivingUpdate();

    // Player Targets and No Player Healing:
    if(!this.getEntityWorld().isRemote) {
        if (this.updateTick % 200 == 0 || !this.firstPlayerTargetCheck) {
            this.firstPlayerTargetCheck = true;
            this.playerTargets = this.getNearbyEntities(EntityPlayer.class, null, 64);
        }
        if (this.updateTick % 20 == 0) {
            if (this.playerTargets.isEmpty()) {
                this.heal(50);
            }
        }
    }

    // Update Phases:
    if(!this.getEntityWorld().isRemote) {
        this.updatePhases();
        this.updateCurrentArenaNode();
        this.updateArenaMovement();
    }

    // Passive Attacks:
    if(!this.getEntityWorld().isRemote && this.updateTick % 20 == 0) {
        // Flying Player Wraith Attack:
        for(EntityPlayer target : this.playerTargets) {
            if(target.capabilities.isCreativeMode || target.isSpectator())
                continue;
            if(CreatureManager.getInstance().config.bossAntiFlight > 0 && target.posY > this.posY + CreatureManager.getInstance().config.bossAntiFlight + 1) {
                for(int i = 0; i < 3; i++) {
                    EntityWraith minion = new EntityWraith(this.getEntityWorld());
                    this.summonMinion(minion, this.getRNG().nextDouble() * 360, 5);
                    minion.setAttackTarget(target);
                }
            }
        }
    }

    // Clean Minion Lists:
    if(this.getEntityWorld().isRemote && this.updateTick % 200 == 0) {
        if(!this.triteMinions.isEmpty()) {
            for (EntityTrite minion : this.triteMinions.toArray(new EntityTrite[this.triteMinions.size()])) {
                if(minion == null || !minion.isEntityAlive() || minion.getMasterTarget() != this)
                    this.triteMinions.remove(minion);
            }
        }
        if(!this.astarothMinions.isEmpty()) {
            for (EntityAstaroth minion : this.astarothMinions.toArray(new EntityAstaroth[this.astarothMinions.size()])) {
                if(minion == null || !minion.isEntityAlive() || minion.getMasterTarget() != this)
                    this.astarothMinions.remove(minion);
            }
        }
        if(!this.cacodemonMinions.isEmpty()) {
            for (EntityCacodemon minion : this.cacodemonMinions.toArray(new EntityCacodemon[this.cacodemonMinions.size()])) {
                if(minion == null || !minion.isEntityAlive() || minion.getMasterTarget() != this)
                    this.cacodemonMinions.remove(minion);
            }
        }
    }

    // Update Animation States:
    if(!this.getEntityWorld().isRemote) {
        byte animationState = 0;
        if(this.aiRangedAttack != null && this.aiRangedAttack.attackOnCooldown)
            animationState += ANIMATION_STATES_ID.COOLDOWN.id;
        this.dataManager.set(ANIMATION_STATES, animationState);
    }

    // Client Attack Cooldown Particles:
    if(this.getEntityWorld().isRemote && (this.dataManager.get(ANIMATION_STATES) & ANIMATION_STATES_ID.COOLDOWN.id) > 0) {
        BlockPos particlePos = this.getFacingPosition(this, 13, this.getRotationYawHead() - this.rotationYaw);
        for(int i = 0; i < 4; ++i) {
            this.getEntityWorld().spawnParticle(EnumParticleTypes.SMOKE_LARGE, particlePos.getX() + (this.rand.nextDouble() - 0.5D) * 2, particlePos.getY() + (this.height * 0.2D) + this.rand.nextDouble() * 2, particlePos.getZ() + (this.rand.nextDouble() - 0.5D) * 2, 0.0D, 0.0D, 0.0D);
        }
    }
}

    public void onLivingUpdate() {
        super.onLivingUpdate();

        // Look At Target:
        if(this.hasAttackTarget() && !this.getEntityWorld().isRemote) {
            this.getLookHelper().setLookPositionWithEntity(this.getAttackTarget(), 30.0F, 30.0F);
        }

        // Arena Snapping:
        if(this.hasArenaCenter()) {
            BlockPos arenaPos = this.getArenaCenter();
            double arenaY = this.posY;
            if (this.getEntityWorld().isAirBlock(arenaPos))
                arenaY = arenaPos.getY();
            else if (this.getEntityWorld().isAirBlock(arenaPos.add(0, 1, 0)))
                arenaY = arenaPos.add(0, 1, 0).getY();

            if (this.posX != arenaPos.getX() || this.posY != arenaY || this.posZ != arenaPos.getZ())
                this.setPosition(arenaPos.getX(), arenaY, arenaPos.getZ());
        }

        // Sync Hellfire Energy:
        if(!this.getEntityWorld().isRemote)
            this.dataManager.set(HELLFIRE_ENERGY, this.hellfireEnergy);
        else
            this.hellfireEnergy = this.dataManager.get(HELLFIRE_ENERGY);

        // Hellfire Update:
        updateHellfireOrbs(this, this.updateTick, 5, this.hellfireEnergy, 10, this.hellfireOrbs);

        // Update Phases:
        if(!this.getEntityWorld().isRemote) {
			this.updatePhases();
		}

        // Player Targets and No Player Healing:
        if(!this.getEntityWorld().isRemote && this.updateTick % 200 == 0) {
            this.playerTargets = this.getNearbyEntities(EntityPlayer.class, null, 64);
        }
        if(!this.getEntityWorld().isRemote && this.updateTick % 20 == 0) {
            if (this.playerTargets.size() == 0)
                this.heal(50);
        }

        // Passive Attacks:
        if(!this.getEntityWorld().isRemote && this.updateTick % 20 == 0) {

            // Random Projectiles:
            for(int i = 0; i < 3; i++) {
                EntityProjectileBase projectile = new EntityHellfireball(this.getEntityWorld(), this);
                projectile.setProjectileScale(8f);
                projectile.shoot((this.getRNG().nextFloat()) - 0.5F, this.getRNG().nextFloat(), (this.getRNG().nextFloat()) - 0.5F, 1.2F, 3.0F);
                this.playSound(projectile.getLaunchSound(), 1.0F, 1.0F / (this.getRNG().nextFloat() * 0.4F + 0.8F));
                this.getEntityWorld().spawnEntity(projectile);
            }

            // Flying Player Wraith Attack:
            for(EntityPlayer target : this.playerTargets) {
                if(target.capabilities.isCreativeMode || target.isSpectator())
                    continue;
                this.attackRanged(target, 1F);
                if(CreatureManager.getInstance().config.bossAntiFlight > 0 && target.posY > this.posY + CreatureManager.getInstance().config.bossAntiFlight + 1) {
                    for(int i = 0; i < 3; i++) {
                        EntityWraith minion = new EntityWraith(this.getEntityWorld());
                        this.summonMinion(minion, this.getRNG().nextDouble() * 360, 5);
                        minion.setAttackTarget(target);
                        minion.setMasterTarget(null); // Clear master target so that these minions don't break phase 3 barriers.
                    }
                }
            }

            // Primary Target
            if(this.hasAttackTarget()) {
                this.attackRanged(this.getAttackTarget(), 1F);
            }
        }
    }

public InteractionResult mobInteract(Player player, InteractionHand hand) {
	ItemStack itemstack = player.getItemInHand(hand);
	Item item = itemstack.getItem();
	if (item instanceof PaleopediaItem) {
		CompoundTag tag = itemstack.getTag();
		final List<Integer> already = new ArrayList<>(Ints.asList(tag.getIntArray("Pages")));
		if (!already.contains(EnumPaleoPages.GARGOYLEOSAURUS.ordinal())) {
			EnumPaleoPages.addPage(EnumPaleoPages.fromInt(EnumPaleoPages.GARGOYLEOSAURUS.ordinal()), itemstack);
			player.displayClientMessage(Component.translatable("paleopedia.gargoyleosaurus_added"), true);
			return InteractionResult.SUCCESS;
		} else {
			player.displayClientMessage(Component.translatable("paleopedia.gargoyleosaurus_already_added"), true);
			return InteractionResult.SUCCESS;
		}
	}
	if (this.level().isClientSide()) {
		boolean flag = this.isOwnedBy(player) || this.isTame() || this.isFood(itemstack) && !this.isTame();
		return flag ? InteractionResult.CONSUME : InteractionResult.PASS;
	} else {
		if (this.isTame()) {
			if (this.getOwner() == player) {
				if (this.isFood(itemstack)) {
					if (this.getHealth() < this.getMaxHealth()) {
						if (!player.getAbilities().instabuild) {
							itemstack.shrink(1);
						}
						this.heal((float) item.getFoodProperties().getNutrition());
						return InteractionResult.SUCCESS;
					} else {
						if (this.canFallInLove()) {
							this.setInLove(player);
							if (!player.isCreative()) {
								itemstack.shrink(1);
							}
						}
					}
				} else {
					if (this.isTameSitting()) {
						this.setTameSitting(false);
						this.setTameWandering(true);
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.velociraptor.wandering"), true);
					} else if (this.isTameWandering()) {
						this.setTameWandering(false);
						this.setTamePatrolling(true);
						this.saveCurrentChunkAsPatrol();
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.gargoyleosaurus.patrolling"), true);
					} else if (this.isTamePatrolling()) {
						this.setTamePatrolling(false);
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.velociraptor.following"), true);
					} else {
						this.setTameSitting(true);
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.velociraptor.sitting"), true);
					}
				}
			}
		} else {
			if (this.isFood(itemstack)) {
				if (!player.getAbilities().instabuild) {
					itemstack.shrink(1);
				}

				if (this.getRandom().nextInt(3) == 0 && !net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, player)) {
					this.tame(player);
					this.navigation.stop();
					this.setTarget((LivingEntity) null);
					this.setTameSitting(true);
					this.level().broadcastEntityEvent(this, (byte) 7);
				} else {
					this.level().broadcastEntityEvent(this, (byte) 6);
				}

				return InteractionResult.SUCCESS;
			}
		}
	}
	return super.mobInteract(player, hand);
}

    public void onLivingUpdate() {
        super.onLivingUpdate();

		if(!this.getEntityWorld().isRemote) {

			// Light Aura:
			if(!this.isPetType("familiar")) {
				if (this.updateTick % 10 == 0) {
					List aoeTargets = this.getNearbyEntities(EntityLivingBase.class, null, 4);
					for (Object entityObj : aoeTargets) {
						EntityLivingBase target = (EntityLivingBase) entityObj;
						if(target == this) {
							continue;
						}
						if(target instanceof EntityWisp) {
							if (this.playPartner == null) {
								this.playPartner = (EntityWisp) target;
								if (((EntityWisp) target).playPartner == null) {
									((EntityWisp) target).playPartner = this;
								}
							}
							continue;
						}
						this.applyBuffs(target, 1, 1);
						this.applyDebuffs(target, 1, 1);
						if(target instanceof EntityZombie || target instanceof EntitySkeleton) {
							//target.setFire(10);
						}
						if(target instanceof EntityCreatureBase) {
							EntityCreatureBase targetCreature = (EntityCreatureBase)target;
							if(targetCreature.daylightBurns()) {
								//targetCreature.setFire(10);
							}
						}
					}
				}
			}

			// Playing:
			if(this.playPartner == null) {
				this.setAttackCooldownMax(this.getRangedCooldown());
				if (this.updateTick % 40 == 0) {
					List aoeTargets = this.getNearbyEntities(EntityWisp.class, null, 30);
					for (Object entityObj : aoeTargets) {
						EntityWisp target = (EntityWisp)entityObj;
						if(target != this && this.getAttackTarget() != target) {
							this.playPartner = target;
							if(target.playPartner == null) {
								target.playPartner = this;
							}
							break;
						}
					}
				}
			}
			else {
				if(this.playPartner.isDead || this.getAttackTarget() == this.playPartner || this.getDistance(this.playPartner) >= 100) {
					this.playPartner = null;
				}
				else if(this.hasAttackTarget()) {
					this.setAttackCooldownMax(this.getRangedCooldown());
					if(this.getPlayerOwner() == this.playPartner.getPlayerOwner()) {
						this.playPartner.setAttackTarget(this.getAttackTarget());
					}
				}
				else {
					if(!this.isAttackOnCooldown() && !this.hasAttackTarget()) {
						if(this.updateTick % this.getRangedCooldown() == 0) {
							this.setAttackCooldownMax(160);
							this.playPartner.setAttackCooldownMax(160);
							this.playPartner.triggerAttackCooldown();
							this.attackRanged(this.playPartner, this.getDistance(this.playPartner));
						}
					}
				}
			}
		}
    }

public void tick() {
    if (!mob.isFlying()) {
        mob.setNoGravity(false);
        super.tick();
    } else if (operation == Operation.MOVE_TO) {
        mob.setNoGravity(true);
        Vec3 offset = flyingWanted.subtract(mob.position());
        double dist = offset.length();
        if (dist > Math.min(1.5, mob.getBbWidth())) {
            float initialYRot = mob.getYRot();
            float initialXRot = mob.getXRot();
            float initialYaw = Util.yRotToYaw(initialYRot);

            float targetYaw = (float) Mth.atan2(offset.z, offset.x) * Mth.RAD_TO_DEG;//atan2 always returns between -180 and 180 so no wrapdegrees needed
            float targetPitch = (float) Mth.atan2(-offset.y, offset.horizontalDistance()) * Mth.RAD_TO_DEG;

            float newYaw = Mth.approachDegrees(initialYaw, targetYaw, 4);
            float newPitch = Mth.approachDegrees(initialXRot, targetPitch, 4);

            mob.setYRot(Util.yawToYRot(newYaw));
            mob.yBodyRot = mob.getYRot();
            mob.setXRot(newPitch);
            if (Mth.degreesDifferenceAbs(initialYRot, mob.getYRot()) < 3) {
                //Slows down before reaching the target to prevent overshooting
                float limit = 1.2f;
                if (dist > 15) {
                    limit = 2.2f;
                } else if (dist > 5) {
                    limit = 1.8f;
                }
                limit = shouldLandAtTarget ? limit * 0.8f : limit;
                speedModifier = Mth.approach((float) speedModifier, limit, (float) (0.05 * (1.8 / speedModifier)));
            } else {
                speedModifier = Mth.approach((float) speedModifier, 0.2f, 0.025f);
            }

            double targetXMove = speedModifier * Mth.cos(newYaw * Mth.DEG_TO_RAD) * Math.abs(offset.x / dist);
            double targetYMove = speedModifier * Mth.sin(-targetPitch * Mth.DEG_TO_RAD) * Math.abs(offset.y / dist);
            double targetZMove = speedModifier * Mth.sin(newYaw * Mth.DEG_TO_RAD) * Math.abs(offset.z / dist);
            Vec3 move = mob.getDeltaMovement();
            double newX = Mth.approach((float) move.x, (float) targetXMove, 0.01f);
            double newY = Mth.approach((float) move.y, (float) targetYMove, 0.01f);
            double newZ = Mth.approach((float) move.z, (float) targetZMove, 0.01f);
            mob.setDeltaMovement(newX, newY, newZ);
        } else {
            if (mob.isUsingStuckNavigation()) {
                mob.switchNavigator(false);
            }
            if (shouldLandAtTarget) {
                if (!mob.level.isEmptyBlock(mob.blockPosition().below())) {
                    mob.onReachAirTarget(new BlockPos(flyingWanted));//TODO: Maybe onReachGroundTarget?
                    mob.setFlying(false);
                    operation = Operation.WAIT;
                }
            } else {
                mob.onReachAirTarget(new BlockPos(flyingWanted));
                operation = Operation.WAIT;
            }
        }
        if (mob.verticalCollisionBelow && offset.y < 0) {
            if (!mob.isUsingStuckNavigation()) {
                if (offset.horizontalDistance() < 6 && offset.y > -3) {
                    //Just walk if close enough
                    mob.setFlying(false);
                    operation = Operation.WAIT;
                    mob.moveTo(flyingWanted, true, false);
                    //TODO: Maybe onReachGroundTarget?
                } else {
                    mob.doStuckNavigation(flyingWanted);
                }
            }
        } else if (mob.horizontalCollision || mob.verticalCollision) {
            doStuckDetection(mob.position());
        }
    } else {
        mob.setNoGravity(false);
    }
}

    public void render(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
        if (Minecraft.getInstance().options.hideGui || Minecraft.getInstance().player.isSpectator()) {
            return;
        }
        var screenWidth = guiGraphics.guiWidth();
        var screenHeight = guiGraphics.guiHeight();
        if (!ClientMagicData.getRecasts().hasRecastsActive())
            return;
        int totalHeightPerBar = 18;
        int screenTopBuffer = 6;
        var activeRecasts = ClientMagicData.getRecasts().getActiveRecasts();

        RenderSystem.setShader(GameRenderer::getPositionTexShader);
        RenderSystem.setShaderColor(1f, 1f, 1f, 1f);
        Anchor anchor = ClientConfigs.RECAST_ANCHOR.get();
        for (int castIndex = 0; castIndex < activeRecasts.size(); castIndex++) {
            var recastInstance = activeRecasts.get(castIndex);
            var spell = SpellRegistry.getSpell(recastInstance.getSpellId());
            int total = recastInstance.getTotalRecasts();
            int remaining = recastInstance.getRemainingRecasts();
            int totalWidth = total * ORB_WIDTH + (total - 1) * CONNECTOR_WIDTH;
            int barX, barY;
            barX = (int) (screenWidth * anchor.m1);
            barY = (int) (screenHeight * anchor.m2);
            if (anchor == Anchor.Center || anchor == Anchor.TopCenter) {
                barX -= totalWidth / 2;
            }
            if (anchor == Anchor.TopCenter) {
                barY += screenTopBuffer + bossbarOffset;
            }
            barX += ClientConfigs.RECAST_X_OFFSET.get();
            barY += ClientConfigs.RECAST_Y_OFFSET.get();
            barY += totalHeightPerBar * castIndex;

            var poseStack = guiGraphics.pose();
            poseStack.pushPose();
            poseStack.translate(barX - 18, barY - 2, 0);
            poseStack.scale(0.85f, 0.85f, 0.85f);
            RenderSystem.setShaderTexture(0, spell.getSpellIconResource());
            guiGraphics.blit(spell.getSpellIconResource(), 0, 0, 0, 0, 16, 16, 16, 16);
            RenderSystem.setShaderTexture(0, TEXTURE);
            guiGraphics.blit(TEXTURE, -2, -2, 116, 0, 20, 20, 256, 256);
            poseStack.popPose();

            for (int i = 0; i < total; i++) {
                int orbX = barX + (ORB_WIDTH + CONNECTOR_WIDTH) * i;
                int connectorX = orbX + ORB_WIDTH;
                if (i + 1 < total) {
                    // connector
                    guiGraphics.blit(TEXTURE, connectorX, barY + 3, CONNECTOR_TEXTURE_OFFSET_X, CONNECTOR_TEXTURE_OFFSET_Y, 6, 4, 256, 256);
                }
                //orb filling
                boolean charged = i < remaining;
                guiGraphics.blit(TEXTURE, orbX, barY, ORB_TEXTURE_OFFSET_X + (charged ? 0 : 10), ORB_TEXTURE_OFFSET_Y + 21, ORB_WIDTH, ORB_WIDTH, 256, 256);
                if (charged) {
//                    RenderSystem.setShader(GameRenderer::getRendertypeEyesShader);
//                    Vector3f color = SpellRegistry.getSpell(recastInstance.getKey()).getSchoolType().getTargetingColor();
//                    RenderSystem.setShaderColor(color.x(), color.y(), color.z(), 1f);
//                    blit(poseStack, orbX, barY, ORB_TEXTURE_OFFSET_X + 10, ORB_TEXTURE_OFFSET_Y + 21, ORB_WIDTH, ORB_WIDTH, 256, 256);
//                    RenderSystem.setShader(GameRenderer::getPositionTexShader);
//                    RenderSystem.setShaderColor(1f, 1f, 1f, 1f);
                    Vector3f color = spell.getSchoolType().getTargetingColor();
                    RenderSystem.setShaderColor(color.x(), color.y(), color.z(), 1f);
                    guiGraphics.blit(TEXTURE, orbX, barY, ORB_TEXTURE_OFFSET_X + (charged ? 0 : 10), ORB_TEXTURE_OFFSET_Y + 21, ORB_WIDTH, ORB_WIDTH, 256, 256);
                    RenderSystem.setShaderColor(1f, 1f, 1f, 1f);
                    //int color = SpellRegistry.getSpell(recastInstance.getSpellId()).getSchoolType().getDisplayName().getStyle().getColor().getValue();
                    //fillGradient(poseStack, orbX + 3, barY + 3, orbX + 7, barY + 7, color, color, 0);
                }
                //orb
                guiGraphics.blit(TEXTURE, orbX, barY, ORB_TEXTURE_OFFSET_X, ORB_TEXTURE_OFFSET_Y, ORB_WIDTH, ORB_WIDTH, 256, 256);
            }

            int textX = (barX + (ORB_WIDTH + CONNECTOR_WIDTH) * total);
            guiGraphics.drawString(Minecraft.getInstance().font, formatTime(recastInstance.getTicksRemaining(), recastInstance.getTicksToLive()), textX, barY + (ORB_WIDTH - Minecraft.getInstance().font.lineHeight) / 2, ChatFormatting.WHITE.getColor());
        }

        bossbarOffset = 0; // reset for next render frame
    }

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    Item item = itemstack.getItem();
    InteractionResult type = super.mobInteract(player, hand);
    if (itemstack.is(AMTagRegistry.BALD_EAGLE_FOODSTUFFS) && this.getHealth() < this.getMaxHealth()) {
        this.heal(10);
        if (!player.isCreative()) {
            itemstack.shrink(1);
        }
        this.level().broadcastEntityEvent(this, (byte) 7);
        return InteractionResult.CONSUME;
    } else if (itemstack.is(AMTagRegistry.BALD_EAGLE_TAMEABLES)) {
        if (itemstack.hasCraftingRemainingItem() && !player.getAbilities().instabuild) {
            this.spawnAtLocation(itemstack.getCraftingRemainingItem());
        }
        if (!player.isCreative()) {
            itemstack.shrink(1);
        }
        if (random.nextBoolean()) {
            this.level().broadcastEntityEvent(this, (byte) 7);
            this.tame(player);
            this.setCommand(1);
        } else {
            this.level().broadcastEntityEvent(this, (byte) 6);
        }
        return InteractionResult.CONSUME;
    } else if (isTame() && !isFood(itemstack)) {
        if (!this.isBaby() && item == AMItemRegistry.FALCONRY_HOOD.get()) {
            if (!this.hasCap()) {
                this.setCap(true);
                if (!player.isCreative()) {
                    itemstack.shrink(1);
                }
                this.gameEvent(GameEvent.ENTITY_INTERACT);
                this.playSound(SoundEvents.ARMOR_EQUIP_LEATHER, this.getSoundVolume(), this.getVoicePitch());
                return InteractionResult.SUCCESS;
            }
        } else if (itemstack.is(Tags.Items.SHEARS) && this.hasCap()) {
            this.gameEvent(GameEvent.ENTITY_INTERACT);
            this.playSound(SoundEvents.SHEEP_SHEAR, 1.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            if (!this.level().isClientSide) {
                if (player instanceof ServerPlayer) {
                    itemstack.hurt(1, random, (ServerPlayer) player);
                }
            }
            this.spawnAtLocation(AMItemRegistry.FALCONRY_HOOD.get());
            this.setCap(false);
            return InteractionResult.SUCCESS;
        } else if (!this.isBaby() && getRidingFalcons(player) <= 0 && (player.getItemInHand(InteractionHand.MAIN_HAND).getItem() == AMItemRegistry.FALCONRY_GLOVE.get() || player.getItemInHand(InteractionHand.OFF_HAND).getItem() == AMItemRegistry.FALCONRY_GLOVE.get())) {
            boardingCooldown = 30;
            this.setLaunched(false);
            this.ejectPassengers();
            this.startRiding(player, true);
            if (!this.level().isClientSide) {
                AlexsMobs.sendMSGToAll(new MessageMosquitoMountPlayer(this.getId(), player.getId()));
            }
            return InteractionResult.SUCCESS;
        } else {
            InteractionResult interactionresult = itemstack.interactLivingEntity(player, this, hand);
            if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS) {
                this.setCommand((this.getCommand() + 1) % 3);

                if (this.getCommand() == 3) {
                    this.setCommand(0);
                }
                player.displayClientMessage(Component.translatable("entity.alexsmobs.all.command_" + this.getCommand(), this.getName()), true);
                boolean sit = this.getCommand() == 2;
                if (sit) {
                    this.setOrderedToSit(true);
                    return InteractionResult.SUCCESS;
                } else {
                    this.setOrderedToSit(false);
                    return InteractionResult.SUCCESS;
                }
            }
        }
    }
    return type;
}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    InteractionResult type = super.mobInteract(player, hand);
    boolean owner = this.isTame() && isOwnedBy(player);
    if (itemstack.is(AMTagRegistry.RACCOON_TEAMING_FOODS) && bondWithBlueJays(player.getUUID())) {
        this.usePlayerItem(player, hand, itemstack);
        this.level().broadcastEntityEvent(this, (byte) 93);
        return InteractionResult.SUCCESS;
    } else if (this.isTame() && !this.getMainHandItem().isEmpty()) {
        if (!this.level().isClientSide) {
            this.spawnAtLocation(this.getMainHandItem().copy());
        }
        this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
        pickupItemCooldown = 60;
        return InteractionResult.SUCCESS;
    } else if (owner && itemstack.is(ItemTags.WOOL_CARPETS)) {
        DyeColor color = EntityElephant.getCarpetColor(itemstack);
        if (color != this.getColor()) {
            if (this.getColor() != null) {
                this.spawnAtLocation(this.getCarpetItemBeingWorn());
            }
            this.gameEvent(GameEvent.ENTITY_INTERACT);
            this.playSound(SoundEvents.LLAMA_SWAG, 1.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            itemstack.shrink(1);
            this.setColor(color);
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.PASS;
    } else if (owner && this.getColor() != null && itemstack.is(Tags.Items.SHEARS)) {
        this.gameEvent(GameEvent.ENTITY_INTERACT);
        this.playSound(SoundEvents.SHEEP_SHEAR, 1.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
        if (this.getColor() != null) {
            this.spawnAtLocation(this.getCarpetItemBeingWorn());
        }
        this.setColor(null);
        return InteractionResult.SUCCESS;
    } else if (isTame() && isRaccoonFood(itemstack) && !isFood(itemstack) && this.getHealth() < this.getMaxHealth()) {
        if (this.getMainHandItem().isEmpty()) {
            ItemStack copy = itemstack.copy();
            copy.setCount(1);
            this.setItemInHand(InteractionHand.MAIN_HAND, copy);
            this.onEatItem();
            if (itemstack.hasCraftingRemainingItem()) {
                this.spawnAtLocation(itemstack.getCraftingRemainingItem());
            }
            if (!player.isCreative()) {
                itemstack.shrink(1);
            }
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
        } else {
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.heal(5);
        }
        this.usePlayerItem(player, hand, itemstack);
        return InteractionResult.SUCCESS;
    }
    InteractionResult interactionresult = itemstack.interactLivingEntity(player, this, hand);
    if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS && isTame() && isOwnedBy(player) && !isRaccoonFood(itemstack)) {
        if (!player.isShiftKeyDown()) {
            this.setCommand(this.getCommand() + 1);
            if (this.getCommand() == 3) {
                this.setCommand(0);
            }
            player.displayClientMessage(Component.translatable("entity.alexsmobs.all.command_" + this.getCommand(), this.getName()), true);
            boolean sit = this.getCommand() == 2;
            if (sit) {
                this.forcedSit = true;
                this.setOrderedToSit(true);
                return InteractionResult.SUCCESS;
            } else {
                this.forcedSit = false;
                this.setOrderedToSit(false);
                return InteractionResult.SUCCESS;
            }
        }
    }
    return type;
}

public void tick() {
    super.tick();
    this.prevTackleProgress = tackleProgress;
    this.prevFlyProgress = flyProgress;
    if (!this.level().isClientSide) {
        if(perchSearchCooldown > 0){
            perchSearchCooldown--;
        }
        if(this.getTarget() != null && this.getTarget().isAlive()){
            this.setPerchPos(this.getTarget().blockPosition().above(7));
        }else{
            if (this.getPerchPos() != null && !isPerchBlock(this.getPerchPos(), level().getBlockState(this.getPerchPos()))) {
                this.setPerchPos(null);
            }
        }
        if (this.getPerchPos() == null && perchSearchCooldown == 0) {
            perchSearchCooldown = 20 + random.nextInt(20);
            this.setPerchPos(this.findNewPerchPos());
        }
        if (!isFlying() && landingCooldown == 0 && (this.getPerchPos() == null || this.shouldLeavePerch(this.getPerchPos()))) {
            this.setFlying(true);
        }
        if (!isFlying() && this.getTarget() != null){
            this.setFlying(true);
        }

        if(landingCooldown > 0 && isFlying() && this.onGround() && this.getTarget() == null){
            this.setFlying(false);
        }
    }
    final boolean flying = isFlying();
    if (flying) {
        if (this.isLandNavigator)
            switchNavigator(false);

        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (!this.isLandNavigator)
            switchNavigator(true);

        if (flyProgress > 0F)
            flyProgress--;
    }

    if (this.isTackling()) {
        if (tackleProgress < 5F)
            tackleProgress++;
    } else {
        if (tackleProgress > 0F)
            tackleProgress--;
    }

    if(landingCooldown > 0){
        landingCooldown--;
    }
    if(tackleCooldown > 0){
        tackleCooldown--;
    }
    if (isFlying()) {
        this.setNoGravity(true);
    } else {
        this.setNoGravity(false);
    }
    if (this.level().isClientSide  && hasSoulHeart()) {
        final float radius = 0.25F + random.nextFloat() * 1F;
        final float fly = this.flyProgress * 0.2F;
        final float wingSpread = 15F + 65 * fly + random.nextInt(5);
        final float angle = (Maths.STARTING_ANGLE * ((random.nextBoolean() ? -1 : 1) * (wingSpread + 180) + this.yBodyRot));
        final float angleMotion = (Maths.STARTING_ANGLE * this.yBodyRot);
        final double extraX = radius * Mth.sin(Mth.PI + angle);
        final double extraZ = radius * Mth.cos(angle);
        final double mov = this.getDeltaMovement().length();
        final double extraXMotion = -mov * Mth.sin((float) (Math.PI + angleMotion));
        final double extraZMotion = -mov * Mth.cos(angleMotion);
        final double yRandom = 0.2F + random.nextFloat() * 0.3F;
        this.level().addParticle(ParticleTypes.SOUL_FIRE_FLAME, this.getX() + extraX, this.getY() + yRandom, this.getZ() + extraZ, extraXMotion, random.nextFloat() * 0.1F, extraZMotion);
    }
}

public void tick() {
    super.tick();
    prevFlyProgress = flyProgress;
    prevPeckProgress = peckProgress;
    if (this.getGoldenTime() > 0 && !this.level().isClientSide) {
        this.setGoldenTime(this.getGoldenTime() - 1);
    }

    final boolean flying = isFlying();
    if (flying) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }
    if (!this.level().isClientSide) {
        if (flying) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }
        if (flying) {
            this.setNoGravity(true);
            if (this.isFlying() && !this.onGround()) {
                if (!this.isInWaterOrBubble()) {
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1F, 0.6F, 1F));
                }
            }
            this.timeFlying++;
        } else {
            this.setNoGravity(false);
            this.timeFlying = 0;
        }
    }
    if (this.entityData.get(PECK_TICK) > 0) {
        this.entityData.set(PECK_TICK, this.entityData.get(PECK_TICK) - 1);
        if (peckProgress < 5F) {
            peckProgress++;
        }
    } else {
        if (peckProgress > 0F) {
            peckProgress--;
        }
    }
    if (peckProgress >= 5 && this.getMainHandItem().isEmpty() && this.getSaplingState() != null) {
        peckBlockEffect();
    }
    if (!this.getMainHandItem().isEmpty()) {
        heldItemTime++;
        if (heldItemTime > 10 && canTargetItem(this.getMainHandItem())) {
            heldItemTime = 0;
            this.heal(4);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            if (this.getMainHandItem().hasCraftingRemainingItem()) {
                this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
            }
            final var mainHandItem = this.getMainHandItem();
            if (mainHandItem.is(AMTagRegistry.TOUCAN_GOLDEN_FOODS)) {
                this.setGoldenTime(12000);
            } else if (mainHandItem.is(AMTagRegistry.TOUCAN_ENCHANTED_GOLDEN_FOODS)) {
                this.setGoldenTime(-1);
                this.setEnchanted(true);
            }
            this.setSaplingState(getSaplingFor(this.getMainHandItem()));
            eatItemEffect(this.getMainHandItem());
            this.getMainHandItem().shrink(1);
        }
    } else {
        heldItemTime = 0;
    }
    if (this.isFlying() && this.getFeetBlockState().is(Blocks.VINE)) {
        float f = this.getYRot() * Mth.DEG_TO_RAD;
        this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f) * 0.2F, 0.4F, Mth.cos(f) * 0.2F));
    }
}

public void startSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int warmUp = this.castDuration(caster, staff) - 10;
    int duration = spellStat.getDuration() * (WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1);
    int range = spellStat.getRange() + WandUtil.getRangeLevel(caster);
    LivingEntity target = this.getTarget(caster, range);
    if (target != null && !this.isShifting(caster)){
        double radius = spellStat.getRadius();
        List<Vec3> vec3s = BlockFinder.buildOuterBlockCircle(target.position(), radius);
        for (Vec3 vec3 : vec3s) {
            FirePillar flames = new FirePillar(worldIn, vec3.x, vec3.y, vec3.z);
            flames.setOwner(caster);
            flames.setDuration(duration);
            flames.setWarmUp(warmUp);
            flames.setExtraDamage(WandUtil.getPotencyLevel(caster));
            MobUtil.moveDownToGround(flames);
            worldIn.addFreshEntity(flames);
        }
        if (rightStaff(staff)) {
            List<Vec3> vec32s = BlockFinder.buildOuterBlockCircle(target.position(), radius * 2.0D);
            for (Vec3 vec3 : vec32s) {
                FirePillar flames = new FirePillar(worldIn, vec3.x, vec3.y, vec3.z);
                flames.setOwner(caster);
                flames.setDuration(duration);
                flames.setWarmUp(warmUp);
                flames.setExtraDamage(WandUtil.getPotencyLevel(caster));
                MobUtil.moveDownToGround(flames);
                worldIn.addFreshEntity(flames);
            }
        }
    } else {
        Vec3 vector3d = caster.getViewVector(1.0F);
        float f = (float) Mth.atan2(vector3d.z - caster.getZ(), vector3d.x - caster.getX());
        for (int k = 0; k < 8; ++k) {
            float f2 = f + (float) k * (float) Math.PI * 0.25F + 1.0F;
            FirePillar flames = new FirePillar(worldIn, caster.getX() + (double) Mth.cos(f2), caster.getY(), caster.getZ() + (double) Mth.sin(f2));
            flames.setOwner(caster);
            flames.setDuration(duration);
            flames.setWarmUp(warmUp);
            flames.setExtraDamage(WandUtil.getPotencyLevel(caster));
            MobUtil.moveDownToGround(flames);
            worldIn.addFreshEntity(flames);
        }

        for (int k = 0; k < 8; ++k) {
            float f2 = f + (float) k * (float) Math.PI * 0.25F + 3.0F;
            FirePillar flames = new FirePillar(worldIn, caster.getX() + (double) Mth.cos(f2) * 3.0D, caster.getY(), caster.getZ() + (double) Mth.sin(f2) * 3.0D);
            flames.setOwner(caster);
            flames.setDuration(duration);
            flames.setWarmUp(warmUp);
            flames.setExtraDamage(WandUtil.getPotencyLevel(caster));
            MobUtil.moveDownToGround(flames);
            worldIn.addFreshEntity(flames);
        }

        if (rightStaff(staff)) {
            for (int k = 0; k < 8; ++k) {
                float f2 = f + (float) k * (float) Math.PI * 0.25F + 6.0F;
                FirePillar flames = new FirePillar(worldIn, caster.getX() + (double) Mth.cos(f2) * 6.0D, caster.getY(), caster.getZ() + (double) Mth.sin(f2) * 6.0D);
                flames.setOwner(caster);
                flames.setDuration(duration);
                flames.setWarmUp(warmUp);
                flames.setExtraDamage(WandUtil.getPotencyLevel(caster));
                MobUtil.moveDownToGround(flames);
                worldIn.addFreshEntity(flames);
            }

            for (int k = 0; k < 16; ++k) {
                float f2 = f + (float) k * (float) Math.PI * 0.25F + 9.0F;
                FirePillar flames = new FirePillar(worldIn, caster.getX() + (double) Mth.cos(f2) * 9.0F, caster.getY(), caster.getZ() + (double) Mth.sin(f2) * 9.0F);
                flames.setOwner(caster);
                flames.setDuration(duration);
                flames.setWarmUp(warmUp);
                flames.setExtraDamage(WandUtil.getPotencyLevel(caster));
                MobUtil.moveDownToGround(flames);
                worldIn.addFreshEntity(flames);
            }
        }
    }
}

