public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int burning = spellStat.getBurning();
    float radius = (float) spellStat.getRadius();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 2.0F;
    }
    Vec3 vector3d = caster.getViewVector( 1.0F);
    AbstractHurtingProjectile fireballEntity = new Lavaball(worldIn,
            caster.getX() + vector3d.x / 2,
            caster.getEyeY() - 0.2,
            caster.getZ() + vector3d.z / 2,
            vector3d.x,
            vector3d.y,
            vector3d.z);
    if (CuriosFinder.hasUnholySet(caster)){
        fireballEntity = new HellBlast(caster.getX() + vector3d.x / 2,
                caster.getEyeY() - 0.2,
                caster.getZ() + vector3d.z / 2,
                vector3d.x,
                vector3d.y,
                vector3d.z,
                worldIn);
    }
    fireballEntity.setOwner(caster);
    if (fireballEntity instanceof Lavaball lavaball) {
        if (rightStaff(staff)) {
            lavaball.setUpgraded(true);
        }
        if (isShifting(caster)) {
            lavaball.setDangerous(false);
        }
        lavaball.setExtraDamage(potency);
        lavaball.setFiery(burning);
        lavaball.setExplosionPower(lavaball.getExplosionPower() + radius);
    } else if (fireballEntity instanceof HellBlast hellBlast){
        hellBlast.setExtraDamage(potency);
        hellBlast.setRadius(hellBlast.getRadius() + radius);
        hellBlast.setFiery(burning);
    }
    worldIn.addFreshEntity(fireballEntity);
    if (rightStaff(staff)) {
        for (int i = 0; i < 2; ++i) {
            AbstractHurtingProjectile fireballEntity1 = new Lavaball(worldIn,
                    caster.getX() + vector3d.x / 2 + worldIn.random.nextGaussian(),
                    caster.getEyeY() - 0.2,
                    caster.getZ() + vector3d.z / 2 + worldIn.random.nextGaussian(),
                    vector3d.x,
                    vector3d.y,
                    vector3d.z);
            if (CuriosFinder.hasUnholySet(caster)){
                fireballEntity1 = new HellBlast(caster.getX() + vector3d.x / 2 + worldIn.random.nextGaussian(),
                        caster.getEyeY() - 0.2,
                        caster.getZ() + vector3d.z / 2 + worldIn.random.nextGaussian(),
                        vector3d.x,
                        vector3d.y,
                        vector3d.z,
                        worldIn);
            }
            fireballEntity1.setOwner(caster);
            if (fireballEntity1 instanceof Lavaball lavaball) {
                lavaball.setUpgraded(true);
                if (isShifting(caster)) {
                    lavaball.setDangerous(false);
                }
                lavaball.setExtraDamage(potency);
                lavaball.setFiery(burning);
                lavaball.setExplosionPower(lavaball.getExplosionPower() + radius);
            } else if (fireballEntity1 instanceof HellBlast hellBlast){
                hellBlast.setExtraDamage(potency);
                hellBlast.setRadius(hellBlast.getRadius() + radius);
                hellBlast.setFiery(burning);
            }
            worldIn.addFreshEntity(fireballEntity1);
        }
    }
    this.playSound(worldIn, caster, SoundEvents.GHAST_SHOOT, 2.0F, this.projPitch(worldIn.getRandom()));
}

public void tick() {
	super.tick();
	if (this.isEffectiveAi()) {
		boolean flag = this.isInWater();
		if (flag || this.getTarget() != null || this.level().isThundering()) {
			this.func_213454_em();
		}

		if (flag || this.isSleeping()) {
			this.setSitting(false);
		}

		if (this.isStuck() && this.getRandom().nextFloat() < 0.2F) {
			BlockPos blockpos = new BlockPos(this.blockPosition());
			BlockState blockstate = this.level().getBlockState(blockpos);
			this.level().levelEvent(2001, blockpos, Block.getId(blockstate));
		}
	}

	if (this.warningSoundTicks > 0) {
		--this.warningSoundTicks;
	}

	this.interestedAngleO = this.interestedAngle;
	if (this.func_213467_eg()) {
		this.interestedAngle += (1.0F - this.interestedAngle) * 0.4F;
	} else {
		this.interestedAngle += (0.0F - this.interestedAngle) * 0.4F;
	}

	this.crouchAmountO = this.crouchAmount;
	if (this.isCrouching()) {
		this.crouchAmount += 0.2F;
		if (this.crouchAmount > 3.0F) {
			this.crouchAmount = 3.0F;
		}
	} else {
		this.crouchAmount = 0.0F;
	}

	if (!this.level().isClientSide()) {
		if (this.horizontalCollision) {
			Boolean logBlock;
			BlockPos blockpos1 = new BlockPos(this.blockPosition().getX() + 1, this.blockPosition().getY() + 1, this.blockPosition().getZ());
			BlockPos blockpos2 = new BlockPos(this.blockPosition().getX() - 1, this.blockPosition().getY() + 1, this.blockPosition().getZ());
			BlockPos blockpos3 = new BlockPos(this.blockPosition().getX(), this.blockPosition().getY() + 1, this.blockPosition().getZ() + 1);
			BlockPos blockpos4 = new BlockPos(this.blockPosition().getX(), this.blockPosition().getY() + 1, this.blockPosition().getZ() - 1);
			BlockState blockstate1 = this.level().getBlockState(blockpos1);
			BlockState blockstate2 = this.level().getBlockState(blockpos2);
			BlockState blockstate3 = this.level().getBlockState(blockpos3);
			BlockState blockstate4 = this.level().getBlockState(blockpos4);
			if (blockstate1.is(BlockTags.LOGS) || blockstate1.is(BlockTags.PLANKS) || blockstate1.is(BlockTags.WOODEN_DOORS) || blockstate1.is(BlockTags.WOODEN_FENCES) || blockstate1.is(BlockTags.WOODEN_SLABS) || blockstate1.is(BlockTags.WOODEN_STAIRS) || blockstate2.is(BlockTags.LOGS) || blockstate2.is(BlockTags.PLANKS) || blockstate2.is(BlockTags.WOODEN_DOORS) || blockstate2.is(BlockTags.WOODEN_FENCES) || blockstate2.is(BlockTags.WOODEN_SLABS) || blockstate2.is(BlockTags.WOODEN_STAIRS)  || blockstate3.is(BlockTags.LOGS) || blockstate3.is(BlockTags.PLANKS) || blockstate3.is(BlockTags.WOODEN_DOORS) || blockstate3.is(BlockTags.WOODEN_FENCES) || blockstate3.is(BlockTags.WOODEN_SLABS) || blockstate3.is(BlockTags.WOODEN_STAIRS) || blockstate4.is(BlockTags.LOGS) || blockstate4.is(BlockTags.PLANKS) || blockstate4.is(BlockTags.WOODEN_DOORS) || blockstate4.is(BlockTags.WOODEN_FENCES) || blockstate4.is(BlockTags.WOODEN_SLABS) || blockstate4.is(BlockTags.WOODEN_STAIRS)) {
				logBlock = true;
				if (climbingTickCooldown == 0 && climbingTicks < 600) {
					this.setBesideClimbableBlock(logBlock);
					climbingTicks++;
				}
				if (climbingTicks >= 599 && climbingTickCooldown <= 300) {
					climbingTickCooldown++;
				}
				if (climbingTickCooldown == 300) {
					climbingTicks = 0;
					climbingTickCooldown = 0;
				}
			}
		}
	}

	prevSitProgress = sitProgress;
	if (this.entityData.get(SIT_TICK) > 0) {
		this.entityData.set(SIT_TICK, this.entityData.get(SIT_TICK) - 1);
		if (sitProgress < 1.0F) {
			sitProgress = Math.min(sitProgress + 0.1F, 1.0F);
		}
	} else {
		if (sitProgress > 0F) {
			sitProgress = Math.max(sitProgress - 0.2F, 0.0F);
		}
	}
}

public void tick() {
    super.tick();
    prevBirdPitch = this.birdPitch;
    prevScorchProgress = this.scorchProgress;
    float f2 = (float) -((float) this.getDeltaMovement().y * (double) Mth.RAD_TO_DEG);
    this.birdPitch = f2;
    if (this.level().isClientSide) {
        final float radius = 0.35F + random.nextFloat() * 3.5F;
        final float angle = (Maths.STARTING_ANGLE * ((random.nextBoolean() ? -85F : 85F) + this.yBodyRot));
        final float angleMotion = (Maths.STARTING_ANGLE * this.yBodyRot);
        final double extraX = radius * Mth.sin(Mth.PI + angle);
        final double extraZ = radius * Mth.cos(angle);
        final double extraXMotion = -0.2F * Mth.sin((float) (Math.PI + angleMotion));
        final double extraZMotion = -0.2F * Mth.cos(angleMotion);
        final double yRandom = 0.2F + random.nextFloat() * 0.3F;
        this.level().addParticle(AMParticleRegistry.SUNBIRD_FEATHER.get(), this.getX() + extraX, this.getY() + yRandom, this.getZ() + extraZ, extraXMotion, 0D, extraZMotion);
    } else {
        if (this.tickCount % 100 == 0) {
            if(!this.isScorching() && !getScorchingMobs().isEmpty()){
                this.setScorching(true);
            }
            List<Player> playerList = this.level().getEntitiesOfClass(Player.class, this.getScorchArea(), Predicates.alwaysTrue());
            for (Player e : playerList) {
                if (!e.hasEffect(AMEffectRegistry.SUNBIRD_BLESSING.get()) && !e.hasEffect(AMEffectRegistry.SUNBIRD_CURSE.get())) {
                    e.addEffect(new MobEffectInstance(AMEffectRegistry.SUNBIRD_BLESSING.get(), 600, 0));
                }
            }
        }
        if (beaconSearchCooldown > 0) {
            beaconSearchCooldown--;
        }
        if (beaconSearchCooldown <= 0) {
            beaconSearchCooldown = 100 + random.nextInt(200);
            if (level() instanceof ServerLevel) {
                List<BlockPos> beacons = this.getNearbyBeacons(this.blockPosition(), (ServerLevel) level(), 64);
                BlockPos closest = null;
                for (BlockPos pos : beacons) {
                    if (closest == null || this.distanceToSqr(closest.getX(), closest.getY(), closest.getZ()) > this.distanceToSqr(pos.getX(), pos.getY(), pos.getZ())) {
                        if (isValidBeacon(pos)) {
                            closest = pos;
                        }
                    }
                }
                if (closest != null && isValidBeacon(closest)) {
                    beaconPos = closest;
                }
            }
            if (beaconPos != null) {

                if (!isValidBeacon(beaconPos) && tickCount > 40) {
                    this.beaconPos = null;
                }
            }
        }
    }

    final boolean scorching = this.isScorching();
    if (scorching) {
        if (scorchProgress < 20F)
            scorchProgress++;
    } else {
        if (scorchProgress > 0F)
            scorchProgress--;
    }

    if (scorching && scorchProgress == 20F && !this.level().isClientSide) {
        if(fullScorchTime > 30){
            this.setScorching(false);
        }else if(fullScorchTime % 5 == 0){
            for (Entity e : getScorchingMobs()) {
                e.setSecondsOnFire(4);
                if (e instanceof Phantom) {
                    ((Phantom) e).addEffect(new MobEffectInstance(AMEffectRegistry.SUNBIRD_CURSE.get(), 200, 0));
                }
            }
        }
        fullScorchTime++;
    }else{
        fullScorchTime = 0;
    }
}

public void tick() {
	super.tick();

	Entity riding = getVehicle();
	if(riding != null)
		rideTime++;
	else
		rideTime = 0;

	if(eatCooldown > 0)
		eatCooldown--;

	if(angeryTicks > 0 && isAlive()) {
		angeryTicks--;

		if(onGround()) {
			int dangerRange = 3;
			double x = getX() + getBbWidth() / 2;
			double y = getY();
			double z = getZ() + getBbWidth() / 2;

			if(level() instanceof ServerLevel serverLevel) {
				if(angeryTicks == 3)
					playSound(QuarkSounds.ENTITY_TORETOISE_ANGRY, 1F, 0.2F);
				else if(angeryTicks == 0) {
					serverLevel.sendParticles(ParticleTypes.CLOUD, x, y, z, 200, dangerRange, 0.5, dangerRange, 0);
					gameEvent(GameEvent.ENTITY_ACTION);
				}
			}

			if(angeryTicks == 0) {
				AABB hurtAabb = new AABB(x - dangerRange, y - 1, z - dangerRange, x + dangerRange, y + 1, z + dangerRange);
				List<LivingEntity> hurtMeDaddy = level().getEntitiesOfClass(LivingEntity.class, hurtAabb, e -> !(e instanceof Toretoise));

				LivingEntity aggressor = lastAggressor == null ? this : lastAggressor;
				DamageSource damageSource = damageSources().mobAttack(aggressor);
				for(LivingEntity e : hurtMeDaddy) {
					DamageSource useSource = damageSource;
					if(e == aggressor)
						useSource = damageSources().mobAttack(this);
					if(e instanceof Player player && level().getDifficulty() == Difficulty.PEACEFUL){
						player.push(0, 0.25, 0);
						//give the player slight upwards knocback so there's some sort of feedback without hurting them in peaceful
					}

					e.hurt(useSource, 4 + level().getDifficulty().ordinal());
				}
			}
		}
	}

	if(level() instanceof ServerLevel serverLevel) {
		int ore = getOreType();
		if(ore != 0)
			breakOre: {
				AABB ourBoundingBox = getBoundingBox();
				BlockPos min = BlockPos.containing(Math.round(ourBoundingBox.minX), Math.round(ourBoundingBox.minY), Math.round(ourBoundingBox.minZ));
				BlockPos max = BlockPos.containing(Math.round(ourBoundingBox.maxX), Math.round(ourBoundingBox.maxY), Math.round(ourBoundingBox.maxZ));

				for(int ix = min.getX(); ix <= max.getX(); ix++)
					for(int iy = min.getY(); iy <= max.getY(); iy++)
						for(int iz = min.getZ(); iz <= max.getZ(); iz++) {
							BlockPos test = new BlockPos(ix, iy, iz);
							BlockState state = level().getBlockState(test);
							if(state.getBlock() == Blocks.MOVING_PISTON) {
								BlockEntity tile = level().getBlockEntity(test);
								if(tile instanceof PistonMovingBlockEntity piston && piston.isExtending()) {
									BlockState pistonState = piston.getMovedState();
									if(pistonState.is(BREAKS_TORETOISE_ORE)) {
										if(!pistonState.hasProperty(RodBlock.FACING) || pistonState.getValue(RodBlock.FACING) == piston.getMovementDirection()) {
											dropOre(ore, new LootParams.Builder(serverLevel)
													.withParameter(LootContextParams.TOOL, new ItemStack(Items.IRON_PICKAXE)));
											break breakOre;
										}
									}
								}
							}
						}
			}
	}
}

protected void onHitEntity(EntityHitResult result) {
	super.onHitEntity(result);

	Entity owner = getOwner();
	Entity hit = result.getEntity();
	if(hit == owner) return;

	addHit(hit);
	if (hit instanceof AbstractPickarang<?> apg) {
		apg.setReturning();
		clank(result);
		return;
	}
	ItemStack pickarang = getStack();

	ItemAttributeModifiers modifiers = pickarang.getAttributeModifiers();
	Multimap<Holder<Attribute>, AttributeModifier> attributeModifiers = ArrayListMultimap.create();

	for (ItemAttributeModifiers.Entry entry : modifiers.modifiers()) {
		attributeModifiers.put(entry.attribute(), entry.modifier());
	}

	if (owner instanceof LivingEntity leOwner) {
		ItemStack prev = leOwner.getMainHandItem();
		leOwner.setItemInHand(InteractionHand.MAIN_HAND, pickarang);
		leOwner.getAttributes().addTransientAttributeModifiers(attributeModifiers);
		PickarangModule.setActivePickarangDamage(PickarangModule.getDamageSource(this, leOwner));

		int ticksSinceLastSwing = leOwner.attackStrengthTicker;
		leOwner.attackStrengthTicker = (int) (1.0 / leOwner.getAttributeValue(Attributes.ATTACK_SPEED) * 20.0) + 1;

		float prevHealth = hit instanceof LivingEntity ? ((LivingEntity) hit).getHealth() : 0;

		hitEntity:
		{
			if (hit instanceof Toretoise toretoise) {
				int ore = toretoise.getOreType();

				if (ore != 0) {
					addHit(toretoise);
					if (level() instanceof ServerLevel serverLevel) {
						LootParams.Builder lootBuilder = new LootParams.Builder(serverLevel)
								.withParameter(LootContextParams.TOOL, pickarang);
						if (owner instanceof Player player)
							lootBuilder.withLuck(player.getLuck());
						toretoise.dropOre(ore, lootBuilder);
					}
					break hitEntity;
				}
			}

			// we need to call attack for enchantments and whatnot. we need the damage source hack so we can set it as a projectile so its not the player damage source
			if (owner instanceof Player p)
				p.attack(hit);
			else
				leOwner.doHurtTarget(hit);

			if (hit instanceof LivingEntity && ((LivingEntity) hit).getHealth() == prevHealth)
				clank(result);
		}

		leOwner.attackStrengthTicker = ticksSinceLastSwing;

		setStack(leOwner.getMainHandItem());
		leOwner.setItemInHand(InteractionHand.MAIN_HAND, prev);
		leOwner.getAttributes().addTransientAttributeModifiers(attributeModifiers);
		PickarangModule.setActivePickarangDamage(null);
	} else {
		Builder mapBuilder = new Builder();
		mapBuilder.add(Attributes.ATTACK_DAMAGE, 1);
		AttributeSupplier map = mapBuilder.build();
		AttributeMap manager = new AttributeMap(map);
		manager.addTransientAttributeModifiers(attributeModifiers);

		ItemStack stack = getStack();
		stack.hurtAndBreak(1, (LivingEntity) owner, null);
		setStack(stack);

		hit.hurt(PickarangModule.getDamageSource(this, owner), (float) manager.getValue(Attributes.ATTACK_DAMAGE));
	}
}

public void onUpdate() {
	if (getEntityWorld().isRemote) {
            if (isInWater() && !getEntityWorld().getBlockState(getPosition().down()).getMaterial().isSolid())
				motionY -= 0.2D;

		if (isBeingRidden() && getJawAngle() == 16)
			if (getEntityWorld().getTotalWorldTime() % 20 == 0)
				spawnEatingParticles();
		if (getPearlTimer() == 1)
			spawnSpittingParticles();
		if (getPearlTimer() >= 30)
			if (getEntityWorld().getTotalWorldTime() % 10 == 0)
				spawnMakingParticles();
	}

	if (!getEntityWorld().isRemote) {
		if (getPearlTimer() < 0) {
			if (getEntityWorld().getTotalWorldTime() % 5 == 0)
				checkAreaHere();

			if (getAttackTarget() != null) {
				if (!isBeingRidden() && getJawAngle() < 80) {
					setJawAngle(getJawAngle() + 8);
					if (getEatingHeight() > 0)
						setEatingHeight(0);
				}
				if (isBeingRidden() && getJawAngle() > 16)
					setJawAngle(getJawAngle() - 8);
			}

			if (getAttackTarget() == null) {
				if (!isBeingRidden()) {
					if (getJawAngle() > 0 && getTendrilCount() <= 0)
						setJawAngle(getJawAngle() - 8);
				}
			}

			if (isBeingRidden() && getJawAngle() == 16 && getPlacedByPlayer()) {
				if (getEntityWorld().getTotalWorldTime() % 20 == 0) {

					setEatingHeight(getEatingHeight() + 1);
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
					getPassengers().get(0).attackEntityFrom(DamageSource.GENERIC, 0F);
					if (getEatingHeight() == 10 && getPassengers().get(0) != null) {
						setContainedXP(getContainedXP() + Math.round(getXPEaten((EntityLivingBase) getPassengers().get(0)) * 0.5F));
						getPassengers().get(0).setDead();
						if(getContainedXP() >= 10)
							setPearlTimer(PEARL_CREATION_TIME);
						setEatingHeight(0);
						setJawAngle(0);
					}
				}
			}

			if (isBeingRidden() && getJawAngle() == 16 && !getPlacedByPlayer())
				if (getEntityWorld().getTotalWorldTime() % 20 == 0) {
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
					getPassengers().get(0).attackEntityFrom(DamageSource.causeMobDamage(this), (float) getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
				}

		} else {
			if (getPearlTimer() >= 0) {
				setPearlTimer(getPearlTimer() - 1);
				if (getEntityWorld().getTotalWorldTime() % 20 == 0 && getPearlTimer() >= 30)
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_DIGEST, SoundCategory.HOSTILE, 1F, 0.8F + rand.nextFloat() * 0.5F);
			}

			if (getPearlTimer() == 0) {
				int quotient = getContainedXP() / 10;
			    int result = getContainedXP() - quotient * 10;
				setContainedXP(result);
				ItemStack pearl = new ItemStack(ItemRegistry.ROCK_SNOT_PEARL, quotient);
				EntityItem item = new EntityItem(world, posX, posY + 0.5D, posZ, pearl);
				item.motionX = item.motionZ = 0D;
				item.motionY = 0.4D;
				world.spawnEntity(item);
				getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_SPIT, SoundCategory.HOSTILE, 1F, 1F);
			}
		}
	}
	super.onUpdate();
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    Vec3 srcVec = new Vec3(caster.getX(), caster.getEyeY(), caster.getZ());
    Vec3 lookVec = caster.getViewVector(1.0F);
    double knock = spellStat.getPotency();
    int range = spellStat.getRange();
    if (rightStaff(staff)){
        range *= 2;
        knock *= 2;
    }
    if (WandUtil.enchantedFocus(caster)){
        knock += WandUtil.getPotencyLevel(caster) / 4.0D;
        range += WandUtil.getRangeLevel(caster);
    }
    double dist = 0.9;
    double px = caster.getX() + lookVec.x * dist;
    double py = caster.getEyeY() + lookVec.y * dist;
    double pz = caster.getZ() + lookVec.z * dist;
    for (int i = 0; i < 16; i++) {
        double pVelocity = 0.3F + ((double) range / 10);
        double velocity = pVelocity + worldIn.getRandom().nextDouble() * pVelocity;
        Vec3 vec3 = lookVec.multiply(velocity, velocity, velocity);
        Vec3 pos = new Vec3(px, py, pz);
        pos = pos.add(caster.getRandom().nextGaussian() / 2, caster.getRandom().nextGaussian() / 2, caster.getRandom().nextGaussian() / 2);
        int width = worldIn.getRandom().nextIntBetweenInclusive(1, 4);
        float height = worldIn.getRandom().nextFloat() * 0.5F;
        worldIn.sendParticles(new WindBlowParticleOption(ColorUtil.WHITE, width, height), pos.x, pos.y, pos.z, 0, vec3.x, vec3.y, vec3.z, 1.0F);
    }
    for(int i = 1; i < range; ++i) {
        Vec3 vector3d2 = srcVec.add(lookVec.scale(i));
        if (typeStaff(staff, SpellType.FROST)){
            worldIn.sendParticles(ModParticleTypes.FROST.get(), vector3d2.x, vector3d2.y, vector3d2.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
        }
        if (typeStaff(staff, SpellType.WILD)){
            worldIn.sendParticles(ModParticleTypes.FLY.get(), vector3d2.x, vector3d2.y, vector3d2.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
        }
        if (typeStaff(staff, SpellType.NETHER)){
            worldIn.sendParticles(ParticleTypes.FLAME, vector3d2.x, vector3d2.y, vector3d2.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
        }
    }
    Vec3 rangeVec = new Vec3(lookVec.x * range, lookVec.y * range, lookVec.z * range);
    BlockHitResult result = this.blockResult(worldIn, caster, range);
    if (result != null){
        BlockPos blockPos = result.getBlockPos();
        BlockEntity blockEntity = worldIn.getBlockEntity(blockPos);
        if (blockEntity instanceof IWindPowered windPowered){
            windPowered.activate(MathHelper.secondsToTicks(15));
        }
    }
    List<Entity> entities = caster.level.getEntities(caster, caster.getBoundingBox().inflate(1.0D).expandTowards(rangeVec));
    for (Entity entity : entities){
        if (caster.hasLineOfSight(entity)){
            if (!MobUtil.areAllies(entity, caster) && !entity.getType().is(ModTags.EntityTypes.UNBLOWABLE_ENTITIES)) {
                MobUtil.knockBack(entity, caster, 2.0D * knock, 0.2D * knock, 2.0D * knock);
                if (entity instanceof LivingEntity living) {
                    if (typeStaff(staff, SpellType.FROST)) {
                        living.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (typeStaff(staff, SpellType.WILD)) {
                        MobEffect mobEffect = MobEffects.POISON;
                        if (CuriosFinder.hasWildRobe(caster)) {
                            mobEffect = GoetyEffects.ACID_VENOM.get();
                        }
                        living.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(5)));
                    }
                    if (typeStaff(staff, SpellType.STORM)) {
                        living.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (typeStaff(staff, SpellType.VOID)) {
                        living.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (typeStaff(staff, SpellType.NETHER)) {
                        living.setSecondsOnFire(5);
                    }
                }
                if (entity instanceof AbstractCyclone cyclone && (cyclone.getTrueOwner() == null || !MobUtil.areAllies(caster, cyclone.getTrueOwner()))) {
                    cyclone.trueRemove();
                }
            }
        }
    }
    this.playSound(worldIn, caster, ModSounds.WIND_BLAST.get(), 0.3F, 1.3F);
}

public static void fireCrossbow(IToolStackView tool, LivingEntity living, boolean creative, InteractionHand hand, CompoundTag heldAmmo) {
  // ammo already loaded? time to fire
  Level level = living.level();
  if (!level.isClientSide) {
    // shoot the projectile
    int damage = 0;

    // don't need to calculate these multiple times
    float velocity = ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.VELOCITY);
    float inaccuracy = ModifierUtil.getInaccuracy(tool, living);

    // the ammo has a stack size that may be greater than 1 (meaning multishot)
    // when creating the ammo stacks, we use split, so its getting smaller each time
    ItemStack ammo = ItemStack.of(heldAmmo);
    float startAngle = getAngleStart(ammo.getCount());
    int primaryIndex = ammo.getCount() / 2;
    for (int arrowIndex = 0; arrowIndex < ammo.getCount(); arrowIndex++) {
      // setup projectile
      AbstractArrow arrow = null;
      Projectile projectile;
      float speed;
      if (ammo.is(Items.FIREWORK_ROCKET)) {
        // TODO: don't hardcode fireworks, perhaps use a map or a JSON behavior list
        projectile = new FireworkRocketEntity(level, ammo, living, living.getX(), living.getEyeY() - 0.15f, living.getZ(), true);
        speed = 1.5f;
        damage += 3;
      } else {
        ArrowItem arrowItem = ammo.getItem() instanceof ArrowItem a ? a : (ArrowItem)Items.ARROW;
        arrow = arrowItem.createArrow(level, ammo, living);
        projectile = arrow;
        arrow.setCritArrow(true);
        arrow.setSoundEvent(SoundEvents.CROSSBOW_HIT);
        arrow.setShotFromCrossbow(true);
        speed = 3f;
        damage += 1;

        // vanilla arrows have a base damage of 2, cancel that out then add in our base damage to account for custom arrows with higher base damage
        float baseArrowDamage = (float)(arrow.getBaseDamage() - 2 + tool.getStats().get(ToolStats.PROJECTILE_DAMAGE));
        arrow.setBaseDamage(ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.PROJECTILE_DAMAGE, baseArrowDamage));

        // fortunately, don't need to deal with vanilla infinity here, our infinity was dealt with during loading
        if (creative) {
          arrow.pickup = Pickup.CREATIVE_ONLY;
        }
      }

      // TODO: can we get piglins/illagers to use our crossbow?

      // setup projectile
      Vec3 upVector = living.getUpVector(1.0f);
      float angle = startAngle + (10 * arrowIndex);
      Vector3f targetVector = living.getViewVector(1.0f).toVector3f().rotate((new Quaternionf()).setAngleAxis(angle * Math.PI / 180F, upVector.x, upVector.y, upVector.z));
      projectile.shoot(targetVector.x(), targetVector.y(), targetVector.z(), velocity * speed, inaccuracy);

      // add modifiers to the projectile, will let us use them on impact
      ModifierNBT modifiers = tool.getModifiers();
      EntityModifierCapability.getCapability(projectile).addModifiers(modifiers);

      // fetch the persistent data for the arrow as modifiers may want to store data
      ModDataNBT projectileData = PersistentDataCapability.getOrWarn(projectile);

      // let modifiers set properties
      for (ModifierEntry entry : modifiers.getModifiers()) {
        entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, living, ammo, projectile, arrow, projectileData, arrowIndex == primaryIndex);
      }

      // finally, fire the projectile
      level.addFreshEntity(projectile);
      level.playSound(null, living.getX(), living.getY(), living.getZ(), SoundEvents.CROSSBOW_SHOOT, SoundSource.PLAYERS, 1.0F, getRandomShotPitch(angle, living.getRandom()));
    }

    // clear the ammo, damage the bow
    tool.getPersistentData().remove(KEY_CROSSBOW_AMMO);
    ToolDamageUtil.damageAnimated(tool, damage, living, hand);

    // stats
    if (living instanceof ServerPlayer serverPlayer) {
      CriteriaTriggers.SHOT_CROSSBOW.trigger(serverPlayer, living.getItemInHand(hand));
      serverPlayer.awardStat(Stats.ITEM_USED.get(tool.getItem()));
    }
  }
}

public static Optional<ArrayList<Entity>> cast(Level world, Player player, PlayerData data, ItemStack bullet, ItemStack cad, int cd, int particles, float sound, Consumer<SpellContext> predicate, int reservoir) {
	if(!data.overflowed && data.getAvailablePsi() > 0 && !cad.isEmpty() && !bullet.isEmpty() && ISpellAcceptor.hasSpell(bullet) && isTruePlayer(player)) {
		ISpellAcceptor spellContainer = ISpellAcceptor.acceptor(bullet);
		Spell spell = spellContainer.getSpell();
		SpellContext context = new SpellContext().setPlayer(player).setSpell(spell);
		if(predicate != null) {
			predicate.accept(context);
		}

		if(context.isValid()) {
			if(context.cspell.metadata.evaluateAgainst(cad)) {
				int cost = Math.max(getRealCost(cad, bullet, context.cspell.metadata.getStat(EnumSpellStat.COST)) - reservoir, 0);
				PreSpellCastEvent event = new PreSpellCastEvent(cost, sound, particles, cd, spell, context, player, data, cad, bullet);
				if(PsiEvents.post(event).isCanceled()) {
					String cancelMessage = event.getCancellationMessage();
					if(cancelMessage != null && !cancelMessage.isEmpty()) {
						player.sendSystemMessage(Component.translatable(cancelMessage).setStyle(Style.EMPTY.withColor(ChatFormatting.RED)));
					}
					return Optional.empty();
				}

				cd = event.getCooldown();
				particles = event.getParticles();
				sound = event.getSound();
				cost = event.getCost();

				spell = event.getSpell();
				context = event.getContext();

				if(cost > 0) {
					data.deductPsi(cost, cd, true);
				}

				if(cost != 0 && sound > 0) {
					if(!world.isClientSide) {
						world.playSound(null, player.getX(), player.getY(), player.getZ(), PsiSoundHandler.cadShoot.get(), SoundSource.PLAYERS, sound, (float) (0.5 + Math.random() * 0.5));
					} else {
						int color = ((ICAD) cad.getItem()).getSpellColor(cad);
						float r = PsiRenderHelper.r(color) / 255F;
						float g = PsiRenderHelper.g(color) / 255F;
						float b = PsiRenderHelper.b(color) / 255F;
						for(int i = 0; i < particles; i++) {
							double x = player.getX() + (Math.random() - 0.5) * 2.1 * player.getBbWidth();
							double y = player.getY() + 0.35D;
							double z = player.getZ() + (Math.random() - 0.5) * 2.1 * player.getBbWidth();
							float grav = -0.15F - (float) Math.random() * 0.03F;
							PsiClientRuntime.sparkle(world, x, y, z, r, g, b, 0, -grav, 0, 0.25F, 15);
						}

						double x = player.getX();
						double y = player.getY() + player.getEyeHeight() - 0.1;
						double z = player.getZ();
						Vector3 lookOrig = new Vector3(player.getLookAngle());
						for(int i = 0; i < 25; i++) {
							Vector3 look = lookOrig.copy();
							double spread = 0.25;
							look.x += (Math.random() - 0.5) * spread;
							look.y += (Math.random() - 0.5) * spread;
							look.z += (Math.random() - 0.5) * spread;
							look.normalize().multiply(0.15);

							PsiClientRuntime.sparkle(world, x, y, z, r, g, b,
									(float) look.x, (float) look.y, (float) look.z, 0.3F, 5);
						}
					}
				}
				ArrayList<Entity> SpellEntities = new ArrayList<>();
				if(world.isClientSide) {
					spellContainer.predictSpell(context);
				} else {
					SpellEntities = spellContainer.castSpell(context);
				}
				PsiEvents.post(new SpellCastEvent(spell, context, player, data, cad, bullet));
				return Optional.of(SpellEntities);
			} else if(!world.isClientSide) {
				player.sendSystemMessage(Component.translatable("psimisc.weak_cad").setStyle(Style.EMPTY.withColor(ChatFormatting.RED)));
			}
		}
	}

	return Optional.empty();
}

public void tick() {
    LivingEntity target = EntityMimicOctopus.this.getTarget();
    if (target != null) {
        if (scareMobTime > 0) {
            if (fleePosition == null || target.distanceToSqr(fleePosition) < target.getBbWidth() * target.getBbWidth() * 2) {
                fleePosition = generateFleePosition(target);
            }
            if (target instanceof Mob) {
                if (fleePosition != null) {
                    ((Mob) target).getNavigation().moveTo(fleePosition.x, fleePosition.y, fleePosition.z, 1.5F);
                    ((Mob) target).getMoveControl().setWantedPosition(fleePosition.x, fleePosition.y, fleePosition.z, 1.5F);
                    ((Mob) target).setTarget(null);
                }
            }
            camoCooldown = Math.max(camoCooldown, 20);
            stopMimicCooldown = Math.max(stopMimicCooldown, 20);
            scareMobTime--;
            if (scareMobTime == 0) {
                stop();
                return;
            }
        }
        double dist = EntityMimicOctopus.this.distanceTo(target);
        boolean move = true;
        if (dist < 7F && EntityMimicOctopus.this.hasLineOfSight(target) && EntityMimicOctopus.this.getMimicState() == MimicState.GUARDIAN && EntityMimicOctopus.this.isUpgraded()) {
            EntityMimicOctopus.this.entityData.set(UPGRADED_LASER_ENTITY_ID, target.getId());
            move = false;
        }
        if (dist < 3) {
            EntityMimicOctopus.this.entityData.set(LAST_SCARED_MOB_ID, target.getId());
            if (move) {
                move = EntityMimicOctopus.this.isUpgraded() && dist > 2;
            }
            EntityMimicOctopus.this.getNavigation().stop();
            if (!EntityMimicOctopus.this.isStopChange()) {
                EntityMimicOctopus.this.setMimickedBlock(null);
                MimicState prev = EntityMimicOctopus.this.getMimicState();
                if (EntityMimicOctopus.this.isInWaterOrBubble()) {
                    if (prev != MimicState.GUARDIAN && prev != MimicState.PUFFERFISH) {
                        if (random.nextBoolean()) {
                            EntityMimicOctopus.this.setMimicState(MimicState.GUARDIAN);
                        } else {
                            EntityMimicOctopus.this.setMimicState(MimicState.PUFFERFISH);
                        }
                    }
                } else {
                    EntityMimicOctopus.this.setMimicState(MimicState.CREEPER);
                }
            }
            if (EntityMimicOctopus.this.getMimicState() != MimicState.OVERLAY) {
                EntityMimicOctopus.this.mimicCooldown = 40;
                EntityMimicOctopus.this.stopMimicCooldown = Math.max(EntityMimicOctopus.this.stopMimicCooldown, 60);
            }
            if (EntityMimicOctopus.this.isUpgraded() && EntityMimicOctopus.this.transProgress >= 5.0F) {
                if (EntityMimicOctopus.this.getMimicState() == MimicState.PUFFERFISH) {
                    if (EntityMimicOctopus.this.getBoundingBox().expandTowards(2, 1.3, 2).intersects(target.getBoundingBox())) {
                        target.hurt(EntityMimicOctopus.this.damageSources().mobAttack(EntityMimicOctopus.this), 4);
                        target.addEffect(new MobEffectInstance(MobEffects.POISON, 400, 2));
                    }
                }
                if (EntityMimicOctopus.this.getMimicState() == MimicState.GUARDIAN) {
                    if (EntityMimicOctopus.this.getBoundingBox().expandTowards(1, 1, 1).intersects(target.getBoundingBox())) {
                        target.hurt(EntityMimicOctopus.this.damageSources().mobAttack(EntityMimicOctopus.this), 1);
                    }
                    EntityMimicOctopus.this.entityData.set(UPGRADED_LASER_ENTITY_ID, target.getId());
                }
                if (EntityMimicOctopus.this.getMimicState() == MimicState.CREEPER) {
                    EntityMimicOctopus.this.creeperExplode();
                    EntityMimicOctopus.this.level().broadcastEntityEvent(EntityMimicOctopus.this, (byte) 69);
                    executionCooldown = 300;
                }
            }
            if (scareMobTime == 0) {
                EntityMimicOctopus.this.level().broadcastEntityEvent(EntityMimicOctopus.this, (byte) 68);
                scareMobTime = 60 + random.nextInt(60);
            }
        }
        if (move) {
            EntityMimicOctopus.this.lookAt(target, 30, 30);
            EntityMimicOctopus.this.getNavigation().moveTo(target, 1.2F);
        }
    }
}

public void tick() {
    if(moveToCooldown > 0){
        moveToCooldown--;
    }
    if (randomLeafCheckCooldown > 0) {
        randomLeafCheckCooldown--;
    } else {
        randomLeafCheckCooldown = 30 + ant.getRandom().nextInt(50);
        for (Direction dir : Direction.values()) {
            BlockPos offset = this.ant.blockPosition().relative(dir);
            if (isValidTarget(this.ant.level(), offset) && ant.getRandom().nextInt(1) == 0) {
                blockPos = offset;
                logStartPos = null;
            }
        }
    }

    if (ant.getAttachmentFacing() == Direction.UP) {
        this.ant.getMoveControl().setWantedPosition(blockPos.getX() + 0.5F, blockPos.getY() - 1D, blockPos.getZ() + 0.5F, 1);
        this.ant.setDeltaMovement(ant.getDeltaMovement().add(0, 0.5, 0));
        if (ant.getRandom().nextInt(2) == 0 && isValidTarget(this.ant.level(), ant.blockPosition().above())) {
            blockPos = ant.blockPosition().above();
        }
    } else if (blockPos.getY() > ant.getY() + 2F || logStartPos != null) {
        ant.getNavigation().stop();
        if (ant.getRandom().nextInt(5) == 0 && isValidTarget(this.ant.level(), ant.blockPosition().below())) {
            blockPos = ant.blockPosition().below();
        }
        if (logStartPos != null) {
            double xDif = logStartPos.getX() + 0.5 - ant.getX();
            double zDif = logStartPos.getZ() + 0.5 - ant.getZ();
            float f = (float) (Mth.atan2(zDif, xDif) * (double) Mth.RAD_TO_DEG) - 90.0F;
            ant.setYRot(f);
            ant.yBodyRot = ant.getYRot();
            Vec3 vec = new Vec3(logStartPos.getX() + 0.5, ant.getY(), logStartPos.getZ() + 0.5);
            vec = vec.subtract(ant.position());
            if (ant.onGround() || ant.onClimbable())
                this.ant.setDeltaMovement(vec.normalize().multiply(0.1, 0, 0.1).add(0, ant.getDeltaMovement().y, 0));
            if(moveToCooldown <= 0){
                moveToCooldown = 20 + ant.getRandom().nextInt(30);
                this.ant.getNavigation().moveTo(logStartPos.getX(), ant.getY(), logStartPos.getZ(), 1);
            }
            if (Math.abs(xDif) < 0.6 && Math.abs(zDif) < 0.6) {
                ant.setDeltaMovement(ant.getDeltaMovement().multiply(0D, 1D, 0D));
                this.ant.getMoveControl().setWantedPosition(logStartPos.getX() + 0.5D, ant.getY() + 2, logStartPos.getZ() + 0.5D, 1);
                BlockPos test = new BlockPos(logStartPos.getX(), (int) ant.getY(), logStartPos.getZ());
                if (!ant.level().getBlockState(test).is(BlockTags.LOGS) && ant.getAttachmentFacing() == Direction.DOWN) {
                    this.stop();
                    return;
                }
            }
        } else {
            for (int i = 0; i < 15; i++) {
                BlockPos test = blockPos.offset(6 - ant.getRandom().nextInt(12), -ant.getRandom().nextInt(7), 6 - ant.getRandom().nextInt(12));
                if (ant.level().getBlockState(test).is(BlockTags.LOGS)) {
                    logStartPos = test;
                    break;
                }
            }
        }
        tryTicks++;
    } else {
        super.tick();
        logStartPos = null;
    }
    if (this.isReachedTarget() || ant.blockPosition().above().equals(blockPos)) {
        ant.lookAt(EntityAnchorArgument.Anchor.EYES, new Vec3(blockPos.getX() + 0.5D, blockPos.getY(), blockPos.getZ() + 0.5));
        ant.setAnimation(EntityLeafcutterAnt.ANIMATION_BITE);
        if (this.idleAtLeavesTime >= 6) {
            ant.setLeafHarvestedPos(blockPos);
            ant.setLeafHarvestedState(ant.level().getBlockState(blockPos));
            if (!ant.hasLeaf()) {
                this.breakLeaves();
            }
            ant.setLeaf(true);
            stop();
            this.idleAtLeavesTime = 0;
        } else {
            ++this.idleAtLeavesTime;
        }
    }

}

private void doTick(Level level, BlockPos pos, BlockState blockState) {
	if (!(blockState.getBlock() instanceof HenostoneFireSpitterBlock fireSpitter)) return;

	Direction dir = fireSpitter.getDirection(blockState);

	rangeLen = raycastRange(level, pos, dir, 8.0);

	AABB detectionAABB = buildAABB(pos, dir, rangeLen);

	switch (state) {

	case IDLE -> {
		List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
		if (!entities.isEmpty()) {
			boolean hasValidTarget = entities.stream().anyMatch(e ->
			!(e instanceof Player player && player.isCreative()));
			if (hasValidTarget) {
				transitionTo(FireState.WARNING_1, level, pos);
			}
		}
		setPowered(level, pos, blockState, false);
	}

	case WARNING_1 -> {
		timer++;
		if (timer == WARNING_1_TICKS + 1) {
			playWarningSound(level, pos);
		}
		if (timer >= WARNING_2_TICKS) {
			transitionTo(FireState.WARNING_2, level, pos);
		}
	}

	case WARNING_2 -> {
		timer++;
		if (timer == WARNING_1_TICKS + 1) {
			playWarningSound(level, pos);
		}
		if (timer >= WARNING_2_TICKS) {
			transitionTo(FireState.WARNING_3, level, pos);
		}
	}

	case WARNING_3 -> {
		timer++;
		if (timer == WARNING_3A_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
		if (timer == WARNING_3B_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
		if (timer == WARNING_3C_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
		if (timer >= FIRE_START_TICKS - WARNING_3A_TICKS) {
			transitionTo(FireState.FIRING, level, pos);
		}
	}

	case FIRING -> {
		timer++;
		setPowered(level, pos, blockState, true);

		List<LivingEntity> targets = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
		double ox = pos.getX() + 0.5;
		double oy = pos.getY() + 0.5;
		double oz = pos.getZ() + 0.5;
		level.addParticle(ParticleTypes.FLAME, ox, oy, oz, dir.getStepX() * 0.5, 0, dir.getStepZ() * 0.5);
		for (LivingEntity entity : targets) {
			if (!entity.fireImmune()) {
				entity.setSecondsOnFire(8);
				entity.hurt(level.damageSources().inFire(), 1);
			}
		}

		if (timer >= FIRE_END_TICKS - FIRE_START_TICKS) {
			transitionTo(FireState.COOLDOWN, level, pos);
		}
	}

	case COOLDOWN -> {
		timer++;
		setPowered(level, pos, blockState, false);
		if (timer >= COOLDOWN_TICKS) {
			transitionTo(FireState.IDLE, level, pos);
		}
	}
	}
}

public void tick() {
	super.tick();
	if (this.isEffectiveAi()) {
		boolean flag = this.isInWater();
		if (flag || this.getTarget() != null || this.level().isThundering()) {
			this.func_213454_em();
		}

		if (flag || this.isSleeping()) {
			this.setSitting(false);
		}

		if (this.isStuck() && this.getRandom().nextFloat() < 0.2F) {
			BlockPos blockpos = new BlockPos(this.blockPosition());
			BlockState blockstate = this.level().getBlockState(blockpos);
			this.level().levelEvent(2001, blockpos, Block.getId(blockstate));
		}
	}

	if (this.isSitting() || this.isTameSitting()) {
		this.getNavigation().stop();
	}

	if (this.warningSoundTicks > 0) {
		--this.warningSoundTicks;
	}

	this.interestedAngleO = this.interestedAngle;
	if (this.func_213467_eg()) {
		this.interestedAngle += (1.0F - this.interestedAngle) * 0.4F;
	} else {
		this.interestedAngle += (0.0F - this.interestedAngle) * 0.4F;
	}

	this.crouchAmountO = this.crouchAmount;
	if (this.isCrouching()) {
		this.crouchAmount += 0.2F;
		if (this.crouchAmount > 3.0F) {
			this.crouchAmount = 3.0F;
		}
	} else {
		this.crouchAmount = 0.0F;
	}

	if (!this.level().isClientSide()) {
		if (this.horizontalCollision) {
			Boolean logBlock;
			BlockPos blockpos1 = new BlockPos((int) this.position().x() + 1, (int) this.position().y() + 1, (int) this.position().z());
			BlockPos blockpos2 = new BlockPos((int) this.position().x() - 1, (int) this.position().y() + 1, (int) this.position().z());
			BlockPos blockpos3 = new BlockPos((int) this.position().x(), (int) this.position().y() + 1, (int) this.position().z() + 1);
			BlockPos blockpos4 = new BlockPos((int) this.position().x(), (int) this.position().y() + 1, (int) this.position().z() - 1);
			BlockState blockstate1 = this.level().getBlockState(blockpos1);
			BlockState blockstate2 = this.level().getBlockState(blockpos2);
			BlockState blockstate3 = this.level().getBlockState(blockpos3);
			BlockState blockstate4 = this.level().getBlockState(blockpos4);
			if (blockstate1.is(BlockTags.LOGS) || blockstate1.is(BlockTags.PLANKS) || blockstate1.is(BlockTags.WOODEN_DOORS) || blockstate1.is(BlockTags.WOODEN_FENCES) || blockstate1.is(BlockTags.WOODEN_SLABS) || blockstate1.is(BlockTags.WOODEN_STAIRS) || blockstate2.is(BlockTags.LOGS) || blockstate2.is(BlockTags.PLANKS) || blockstate2.is(BlockTags.WOODEN_DOORS) || blockstate2.is(BlockTags.WOODEN_FENCES) || blockstate2.is(BlockTags.WOODEN_SLABS) || blockstate2.is(BlockTags.WOODEN_STAIRS)  || blockstate3.is(BlockTags.LOGS) || blockstate3.is(BlockTags.PLANKS) || blockstate3.is(BlockTags.WOODEN_DOORS) || blockstate3.is(BlockTags.WOODEN_FENCES) || blockstate3.is(BlockTags.WOODEN_SLABS) || blockstate3.is(BlockTags.WOODEN_STAIRS) || blockstate4.is(BlockTags.LOGS) || blockstate4.is(BlockTags.PLANKS) || blockstate4.is(BlockTags.WOODEN_DOORS) || blockstate4.is(BlockTags.WOODEN_FENCES) || blockstate4.is(BlockTags.WOODEN_SLABS) || blockstate4.is(BlockTags.WOODEN_STAIRS)) {
				logBlock = true;
				if (climbingTickCooldown == 0 && climbingTicks < 600) {
					this.setBesideClimbableBlock(logBlock);
					climbingTicks++;
				}
				if (climbingTicks >= 599 && climbingTickCooldown <= 300) {
					climbingTickCooldown++;
				}
				if (climbingTickCooldown == 300) {
					climbingTicks = 0;
					climbingTickCooldown = 0;
				}
			}
		}
	}
	prevSitProgress = sitProgress;
	if (this.entityData.get(SIT_TICK) > 0) {
		this.entityData.set(SIT_TICK, this.entityData.get(SIT_TICK) - 1);
		if (sitProgress < 1.0F) {
			sitProgress = Math.min(sitProgress + 0.1F, 1.0F);
		}
	} else {
		if (sitProgress > 0F) {
			sitProgress = Math.max(sitProgress - 0.2F, 0.0F);
		}
	}
}

public boolean update(DinosaurEntity entity) {
    if (this.home == null || entity.getDistanceSqToCenter(this.home) > 4096) {
        this.home = entity.getPosition();
    }
    World world = entity.world;
    double centerX = 0.0;
    double centerZ = 0.0;
    Set<UUID> remove = new HashSet<>();
    Set<DinosaurEntity> members = new HashSet<>();
    for (UUID parent : this.parents) {
        DinosaurEntity parentEntity = this.get(world, parent);
        if (parentEntity == null || parentEntity.isDead || parentEntity.isCarcass()) {
            remove.add(parent);
        } else {
            centerX += parentEntity.posX;
            centerZ += parentEntity.posZ;
            members.add(parentEntity);
            parentEntity.family = this;
        }
    }
    for (UUID child : this.children) {
        DinosaurEntity childEntity = this.get(world, child);
        if (childEntity == null || childEntity.isDead || childEntity.isCarcass() || childEntity.getAgePercentage() > 50) {
            remove.add(child);
        } else {
            members.add(childEntity);
            childEntity.family = this;
        }
    }
    this.parents.removeAll(remove);
    this.children.removeAll(remove);
    if (this.parents.isEmpty()) {
        return true;
    }
    if ((remove.size() > 0 && !this.parents.contains(this.head)) || this.head == null) {
        this.head = this.parents.iterator().next();
    }
    centerX /= this.parents.size();
    centerZ /= this.parents.size();
    if (this.stayHome > 0) {
        this.stayHome--;
        centerX = this.home.getX();
        centerZ = this.home.getZ();
    } else {
        centerX = (this.home.getX() / 2) + (centerX / 2);
        centerZ = (this.home.getZ() / 2) + (centerZ / 2);
    }
    double centerDistance = entity.getDistanceSq(centerX, entity.posY, centerZ);
    Random random = entity.getRNG();
    if (random.nextDouble() * centerDistance > 128) {
        for (DinosaurEntity member : members) {
            if (member.getAttackTarget() == null && member.getNavigator().noPath()) {
                int travelX = (int) (centerX + random.nextInt(4) - 2);
                int travelZ = (int) (centerZ + random.nextInt(4) - 2);
                int travelY = world.getTopSolidOrLiquidBlock(new BlockPos(travelX, 0, travelZ)).getY();
                member.getNavigator().tryMoveToXYZ(travelX, travelY, travelZ, 0.8);
            }
        }
    }
    if (entity.getRNG().nextInt(50) == 0 && (entity.getDinosaur().shouldBreedAroundOffspring() || this.children.isEmpty())) {
        DinosaurEntity father = null;
        DinosaurEntity mother = null;
        for (DinosaurEntity member : members) {
            if (this.parents.contains(member.getUniqueID())) {
                if (!member.shouldSleep() && member.getBreedCooldown() <= 0 && !member.isBreeding() && member.getHealth() >= member.getMaxHealth() && member.getGrowthStage() == GrowthStage.ADULT) {
                    if (member.isMale()) {
                        father = member;
                    } else {
                        mother = member;
                    }
                }
            }
        }
        if (father != null && mother != null) {
            if (father.getDistanceSq(mother) < 128) {
                father.getNavigator().tryMoveToEntityLiving(mother, 1.0);
                mother.getNavigator().tryMoveToEntityLiving(father, 1.0);
                father.breed(mother);
                mother.breed(father);
            }
        }
    }
    return false;
}

    public void onLivingUpdate() {
        super.onLivingUpdate();

        // Land/Fly:
        if(!this.getEntityWorld().isRemote) {
            if(this.isLanded) {
                this.wantsToLand = false;
                if(this.hasPickupEntity() || this.getControllingPassenger() != null || this.getLeashed() || this.isInWater() || (!this.isTamed() && this.updateTick % (5 * 20) == 0 && this.getRNG().nextBoolean())) {
                    this.leap(1.0D, 1.0D);
                    this.wanderAI.setPauseRate(0);
                    this.isLanded = false;
                }
            }
            else {
                if(this.wantsToLand) {
                    if(!this.isLanded && this.isSafeToLand()) {
                        this.wanderAI.setPauseRate(120);
                        this.isLanded = true;
                    }
                }
                else {
                    if (!this.hasPickupEntity() && !this.hasAttackTarget() && this.updateTick % (5 * 20) == 0 && this.getRNG().nextBoolean()) {
                        this.wantsToLand = true;
                    }
                }
            }
            if(this.hasPickupEntity() || this.getControllingPassenger() != null || this.hasAttackTarget() || this.isInWater()) {
                this.wantsToLand = false;
            }
            else if(this.isTamed() && !this.getLeashed()) {
                this.wantsToLand = true;
            }
        }

        // Entity Pickup Update:
        if(!this.getEntityWorld().isRemote && this.getControllingPassenger() == null) {
	    	this.attackAI.setEnabled(!this.hasPickupEntity());
            if(!this.isInWater()) {
                this.waterTime = 0;

                // Random Dropping:
                if(this.hasPickupEntity()) {
                    if(this.updateTick % this.getMeleeCooldown() == 0) {
                        this.attackMelee(this.getPickupEntity(), 1);
                    }
                    ExtendedEntity extendedEntity = ExtendedEntity.getForEntity(this.getPickupEntity());
                    if(extendedEntity != null)
                        extendedEntity.setPickedUpByEntity(this);
                    if(this.ticksExisted % 100 == 0 && this.getRNG().nextBoolean()) {
                        this.dropPickupEntity();
                    }
                }

    	    	/*/ Random Swooping:
    	    	else if(this.hasAttackTarget() && this.getDistance(this.getAttackTarget()) > 2 && this.getRNG().nextInt(20) == 0) {
    	    		if(this.posY - 1 > this.getAttackTarget().posY)
    	    			this.leap(1.0F, -1.0D, this.getAttackTarget());
    	    		else if(this.posY + 1 < this.getAttackTarget().posY)
    	    			this.leap(1.0F, 1.0D, this.getAttackTarget());
    	    	}*/
            }

            // Burst Out of Water:
            else {
                this.waterTime++;
                if(this.hasPickupEntity() || this.getAir() <= 40) {
	                if(this.waterTime >= (2 * 20)) {
	                    this.waterTime = 0;
	                    this.leap(0.5F, 2.0D);
	                }
                }
                else if(this.hasAttackTarget()) {
                	if(this.waterTime >= (16 * 20)) {
	                    this.waterTime = 4 * 20;
	                    this.leap(0.5F, 2.0D);
                	}
                }
                else if(this.waterTime >= (8 * 20)) {
                    this.waterTime = 4 * 20;
                    this.leap(0.5F, 2.0D);
            	}
            }
        }
    }

public void MagicResults(ItemStack stack, Level worldIn, LivingEntity caster, ISpell spell) {
    if (spell != null && caster instanceof Player playerEntity) {
        if (!worldIn.isClientSide) {
            ServerLevel serverWorld = (ServerLevel) worldIn;
            if (playerEntity.isCreative()) {
                if (stack.getTag() != null) {
                    spell.SpellResult(serverWorld, caster, stack, WandUtil.getStats(caster, spell));
                    boolean flag = false;
                    if (spell instanceof IChargingSpell chargingSpell) {
                        if (chargingSpell.shotsNumber(playerEntity, stack) > 0 && this.ShotsFired(stack) >= chargingSpell.shotsNumber(playerEntity, stack)) {
                            flag = true;
                        }
                    } else {
                        flag = true;
                    }
                    if (flag) {
                        this.setShots(stack, 0);
                        if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                            SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                        }
                    }
                }
            } else if (SEHelper.getSoulsAmount(playerEntity, SoulUse(caster, stack))) {
                boolean spent = true;
                if (spell instanceof IChargingSpell spell1 && spell1.everCharge()) {
                    if (stack.getTag() != null) {
                        stack.getTag().putInt(SECONDS, stack.getTag().getInt(SECONDS) + 1);
                        if (stack.getTag().getInt(SECONDS) != 20) {
                            spent = false;
                        } else {
                            stack.getTag().putInt(SECONDS, 0);
                        }
                    }
                }
                if (spent) {
                    SEHelper.decreaseSouls(playerEntity, SoulUse(caster, stack));
                    SEHelper.sendSEUpdatePacket(playerEntity);
                    if (MobsConfig.VillagerHateSpells.get() > 0) {
                        for (Villager villager : caster.level.getEntitiesOfClass(Villager.class, caster.getBoundingBox().inflate(16.0D))) {
                            if (villager.hasLineOfSight(caster)) {
                                villager.getGossips().add(caster.getUUID(), GossipType.MINOR_NEGATIVE, MobsConfig.VillagerHateSpells.get());
                            }
                        }
                    }
                }
                if (stack.getTag() != null) {
                    spell.SpellResult(serverWorld, caster, stack, WandUtil.getStats(caster, spell));
                    boolean flag = false;
                    if (spell instanceof IChargingSpell chargingSpell) {
                        if (chargingSpell.shotsNumber(playerEntity, stack) > 0 && this.ShotsFired(stack) >= chargingSpell.shotsNumber(playerEntity, stack)) {
                            flag = true;
                        }
                    } else {
                        flag = true;
                    }
                    if (flag) {
                        this.setShots(stack, 0);
                        if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                            SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                        }
                    }
                }
            } else {
                worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0F, 1.0F);
            }
        }
        if (worldIn.isClientSide) {
            if (playerEntity.isCreative()) {
                if (spell instanceof IBreathingSpell breathingSpells) {
                    breathingSpells.showWandBreath(caster, stack, WandUtil.getStats(caster, spell));
                }
            } else if (SEHelper.getSoulsAmount(playerEntity, SoulUse(caster, stack))) {
                if (spell instanceof IBreathingSpell breathingSpells) {
                    breathingSpells.showWandBreath(caster, stack, WandUtil.getStats(caster, spell));
                }
            } else {
                this.failParticles(worldIn, caster);
            }
        }
    } else {
        this.failParticles(worldIn, caster);
        worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0F, 1.0F);
    }
}

public boolean hurt(DamageSource source, float damage) {
    Entity entity = source.getDirectEntity();
    LivingEntity target = this.getTarget();
    double range = calculateRange(source);

    if (entity != null && !isNoAi() && (blockingProgress == 10 || swordProgress == 10)) {
        if (target != null && target.isAlive()) {
            if (this.getAnimation() == NO_ANIMATION) {
                if (this.getRandom().nextFloat() * 100.0F < 12f && counter_strike_cooldown <= 0 && range < 225) {
                    counter_strike_cooldown = CONTER_STRIKE_COOLDOWN;
                    Animation counter = this.getIsShieldBreak() ? SHIELD_BREAK_COUNTER : COUNTER;
                    this.setAnimation(counter);
                }
            }
        }
        if (this.getAnimation() == COUNTER) {
            if (this.getAnimationTick() > 16 && this.getAnimationTick() <= 46) {
                AnimationHandler.INSTANCE.sendAnimationMessage(this, STRIKE);
                this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
                if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                    return false;
                }
            }
        }
        if (this.getAnimation() == SHIELD_BREAK_COUNTER) {
            if (this.getAnimationTick() > 8 && this.getAnimationTick() <= 38) {
                AnimationHandler.INSTANCE.sendAnimationMessage(this, SHIELD_BREAK_STRIKE);
                this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
                if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                    return false;
                }
            }
        }
    }

    if (source.getDirectEntity() instanceof Ignis_Abyss_Fireball_Entity) {
        if (!(source.getEntity() instanceof Ignis_Entity)) {
            if (source.is(DamageTypeTags.IS_PROJECTILE)) {
                if (this.getShieldDurability() < 3) {
                    this.playSound(ModSounds.IGNIS_ARMOR_BREAK.get(), 1.0F, 0.8F);
                    if (!level().isClientSide) {
                        this.setShieldDurability(this.getShieldDurability() + 1);
                    }
                }
            }
        } else {
            return false;
        }
    }


    if ((this.getAnimation() == ULTIMATE_ATTACK || this.getBossPhase() == 1 && this.getHealth() <= this.getMaxHealth() * 1 / 3 || this.getBossPhase() == 0 && this.getHealth() <= this.getMaxHealth() * 2 / 3) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
        damage *= 0.5;
    }

    if ((this.getAnimation() == PHASE_3 || this.getAnimation() == PHASE_2 || this.getAnimation() == STRIKE) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
        return false;
    }
    if (source.getDirectEntity() instanceof Ignis_Fireball_Entity) {
        return false;
    }
    if (damage > 0.0F && this.canBlockDamageSource(source)) {
        this.hurtCurrentlyUsedShield(damage);
        if (!source.is(DamageTypeTags.IS_PROJECTILE)) {
            if (entity instanceof LivingEntity) {
                this.blockUsingShield((LivingEntity) entity);
            }
        }
        this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
        return false;
    }

    if (this.destroyBlocksTick <= 0) {
        this.destroyBlocksTick = 20;
    }

    Crackiness irongolem$crackiness = this.getCrackiness();
    boolean attack = super.hurt(source, damage);
    if (attack && this.getCrackiness() != irongolem$crackiness) {
        this.playSound(ModSounds.IGNIS_ARMOR_BREAK.get(), 1.0f, 0.8f);
    }

    return attack;
}

public void tick() {
    super.tick();
    this.prevStandProgress = this.standProgress;
    this.prevBegProgress = this.begProgress;
    this.prevWashProgress = this.washProgress;
    this.prevSitProgress = this.sitProgress;

    if (this.isStanding()) {
        if (standProgress < 5F)
            standProgress++;
    } else {
        if (standProgress > 0F)
            standProgress--;
    }

    if (this.isBegging()) {
        if (begProgress < 5F)
            begProgress++;
    } else {
        if (begProgress > 0F)
            begProgress--;
    }

    if (this.isWashing()) {
        if (washProgress < 5F)
            washProgress++;
    } else {
        if (washProgress > 0F)
            washProgress--;
    }

    if (this.isSitting()) {
        if (sitProgress < 5F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (isStanding() && ++standingTime > maxStandTime) {
        this.setStanding(false);
        standingTime = 0;
        maxStandTime = 75 + random.nextInt(50);
    }
    if (!this.level().isClientSide) {
        if (lookForWaterBeforeEatingTimer > 0) {
            lookForWaterBeforeEatingTimer--;
        } else if (!isWashing() && canTargetItem(this.getMainHandItem())) {
            onEatItem();
            if (this.getMainHandItem().hasCraftingRemainingItem()) {
                this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
            }
            this.getMainHandItem().shrink(1);
        }
    }
    if (isWashing()) {
        if (getWashPos() != null) {
            BlockPos washingPos = getWashPos();
            if (this.distanceToSqr(washingPos.getX() + 0.5D, washingPos.getY() + 0.5D, washingPos.getZ() + 0.5D) < 3) {
                for (int j = 0; (float) j < 4; ++j) {
                    double d2 = (this.random.nextDouble());
                    double d3 = (this.random.nextDouble());
                    Vec3 vector3d = this.getDeltaMovement();

                    this.level().addParticle(ParticleTypes.SPLASH, washingPos.getX() + d2, (double) (washingPos.getY() + 0.8F), washingPos.getZ() + d3, vector3d.x, vector3d.y, vector3d.z);
                }
            } else {
                setWashing(false);
            }
        }
    }
    if (!this.level().isClientSide && this.getTarget() != null && this.hasLineOfSight(this.getTarget()) && this.distanceTo(this.getTarget()) < 4 && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 5) {
        float f1 = this.getYRot() * Mth.DEG_TO_RAD;
        this.setDeltaMovement(this.getDeltaMovement().add((double) (-Mth.sin(f1) * -0.06F), 0.0D, (double) (Mth.cos(f1) * -0.06F)));
        this.getTarget().knockback(0.35F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
        this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
    }
    if (stealCooldown > 0) {
        stealCooldown--;
    }
    if (pickupItemCooldown > 0) {
        pickupItemCooldown--;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public ActionResult useOnBlock(ItemUsageContext context) {
	World world = context.getWorld();
	BlockPos pos = context.getBlockPos();
	BlockState state = world.getBlockState(pos);
	PlayerEntity player = context.getPlayer();
	boolean client = world.isClient;
	if (state.getBlock() instanceof BedBlock) {
		if (!client && player != null && player.isSneaking()) {
			MinecraftServer server = world.getServer();
			if (server != null) {
				if (state.get(BedBlock.PART) != BedPart.HEAD) {
					pos = pos.offset(state.get(BedBlock.FACING));
				}
				PlayerEntity earliestSleeper = null;
				for (ServerPlayerEntity playerEntity : server.getPlayerManager().getPlayerList()) {
					BlockPos bedPos = playerEntity.getSpawnPointPosition();
					if (bedPos != null && bedPos.equals(pos) && (earliestSleeper == null || playerEntity.getSleepTimer() < earliestSleeper.getSleepTimer())) {
						earliestSleeper = playerEntity;
					}
				}
				if (earliestSleeper != null) {
					return useTaglock(player, earliestSleeper, context.getHand(), false, true);
				}
			}
		}
		return ActionResult.success(client);
	} else {
		ItemStack stack = context.getStack();
		BlockEntity blockEntity = world.getBlockEntity(state.getBlock() instanceof DoorBlock && state.get(DoorBlock.HALF) == DoubleBlockHalf.UPPER ? pos.down() : pos);
		if (blockEntity instanceof TaglockHolder taglockHolder) {
			if (player.getUuid().equals(taglockHolder.getOwner())) {
				int firstEmpty = taglockHolder.getFirstEmptySlot();
				if (firstEmpty != -1) {
					if (!client) {
						taglockHolder.getTaglockInventory().set(firstEmpty, stack.split(1));
						taglockHolder.syncTaglockHolder(blockEntity);
						blockEntity.markDirty();
					}
					return ActionResult.success(client);
				}
			}
		} else if (blockEntity instanceof Lockable lockable) {
			if (hasTaglock(stack)) {
				if (player.getUuid().equals(lockable.getOwner()) && lockable.getLocked()) {
					UUID uuid = getTaglockUUID(stack);
					if (!lockable.getEntities().contains(uuid)) {
						if (!client) {
							if (lockable.getEntities().isEmpty()) {
								lockable.setModeOnWhitelist(true);
							}
							lockable.getEntities().add(uuid);
							if (!player.isCreative()) {
								stack.decrement(1);
							}
							lockable.syncLockable(blockEntity);
							blockEntity.markDirty();
						}
						return ActionResult.success(client);
					}
				}
			}
		} else if (blockEntity instanceof SigilHolder sigilHolder) {
			if (hasTaglock(stack)) {
				if (!client) {
					if (sigilHolder.getSigil() != null) {
						UUID uuid = getTaglockUUID(stack);
						if (!sigilHolder.getEntities().contains(uuid)) {
							if (sigilHolder.getEntities().isEmpty()) {
								sigilHolder.setModeOnWhitelist(true);
							}
							sigilHolder.getEntities().add(uuid);
							if (!player.isCreative()) {
								stack.decrement(1);
							}
							sigilHolder.syncSigilHolder(blockEntity);
							blockEntity.markDirty();
						}
					}
				}
				return ActionResult.success(client);
			}
		}
	}
	return super.useOnBlock(context);
}

public void tick() {
    super.tick();
    if (level.isClientSide && !initMusic) {
        initMusic = true;
        ((Runnable) () -> ChimeraMusic.play(WildenChimera.this)).run();
    }

    // written like this allows for hotswap
    // this.goalSelector.getAvailableGoals().stream().filter(WrappedGoal::isRunning).map(WrappedGoal::getGoal).forEach(System.out::println);


    if (!level.isClientSide && isDefensive()) {
        this.getNavigation().stop();
    }
    if (level.isClientSide && isFlying() && random.nextInt(18) == 0) {

        this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.BAT_LOOP, this.getSoundSource(),
                0.95F + this.random.nextFloat() * 0.05F,
                0.3f + this.random.nextFloat() * 0.05F,
                false);

    }

    if (!level.isClientSide && this.isInLava() && this.level.getGameTime() % 10 == 0) {
        this.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 20, 4));
        this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, 3));
        this.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 20));
        this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20, 3));

    }

    if (this.isFlying()) {
        this.navigation.stop();
        flyingNavigator.tick();
    }

    if (!level.isClientSide) {
        // Reduce skill cooldown
        if (diveCooldown > 0) {
            diveCooldown--;
            if (this.isInLava() || this.isInWater())
                diveCooldown -= 2;
        }
        if (summonCooldown > 0) summonCooldown--;
        if (spikeCooldown > 0) spikeCooldown--;
        if (ramCooldown > 0) ramCooldown--;

        if (getTarget() != null && this.invulnerableTime == 0 && !this.isDefensive() && !this.isFlying() && (this.onGround() || isInWater())) {
            var path = getNavigation().createPath(getTarget(), 1);
            if (path == null || !path.canReach() || getTarget().getY() - (this.getY() + 2) >= 3) {
                rageTimer--;
            }
        }

    }

    if (!level.isClientSide && getPhaseSwapping() && !this.dead) {
        if (swapTicks < 60) {
            swapTicks++;
            this.navigation.stop();
        } else {
            this.removeAllEffects();
            this.setPhaseSwapping(false);
            for (LivingEntity e : level.getEntitiesOfClass(Player.class, new AABB(this.blockPosition()).inflate(5))) {
                EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(level, new Spell().add(MethodTouch.INSTANCE)
                        .add(EffectLaunch.INSTANCE)
                        .add(AugmentAmplify.INSTANCE, 2)
                        .add(EffectDelay.INSTANCE)
                        .add(EffectKnockback.INSTANCE)
                        .add(AugmentAmplify.INSTANCE, 2)
                        , this, new LivingCaster(this)));
                resolver.onCastOnEntity(ItemStack.EMPTY, e, InteractionHand.MAIN_HAND);
            }
            getRandomUpgrade();
            ParticleUtil.spawnPoof((ServerLevel) level, blockPosition().above());
            if (getPhase() == 1)
                rageTimer = 200;
            swapTicks = 0;
        }
    }

    if (getPhaseSwapping() && level.isClientSide) {
        spawnPhaseParticles(blockPosition(), level, getPhase());
    }
}

public void onEntityUpdate() {

    if (!world.isRemote) {
        if (this.getHealth() < 0 && !this.isDead) {
            this.setDead();
            if (this.world.getGameRules().getBoolean("doEntityDrops")) {
                this.dropItems();
                ItemStack recordItem = this.dataManager.get(RECORD_ITEM);
                if (!recordItem.isEmpty()) {
                    this.entityDropItem(recordItem, 0);
                }
            }
        }

    }

    for (int i = 0; i < this.seats.length; i++) {
        Entity e = this.getEntityInSeat(i);
        if(e != null && e instanceof EntityPlayerMP) {
            resetFlyTicks((EntityPlayerMP) e);
        }
    }

    if (this.getSpeed() == Speed.FAST) {
        this.allWheels.forEach(wheel -> this.createWheelParticles(wheel, true));
    }
    this.allWheels.forEach(this::createWheelParticles);

    if (shouldStopUpdates()) {
        super.onEntityUpdate();
        return;
    }
    if (!world.isRemote) {
        if (prevWorldTime != -1) {
            world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(0.1f),
                    this::canRunoverEntity).forEach(this::runOverEntity);
        }
    }
    if (this.isInWater()) {
        for (int i = 0; i < this.seats.length; i++) {
            Entity e = this.getEntityInSeat(i);
            if (e != null) {
                e.attackEntityFrom(DamageSource.DROWN, 0.5f);
            }
        }
        this.setHealth(this.getHealth() - 0.25F);
    }
    if (previousPosition == null) {
        previousPosition = this.getPositionVector();
    }
    estimatedSpeed = this.getPositionVector().distanceTo(previousPosition)
            / (world.getTotalWorldTime() - prevWorldTime);
    previousPosition = this.getPositionVector();
    prevWorldTime = world.getTotalWorldTime();

    for (int i = 0; i < 4; i++) {
        List<WheelParticleData> markedRemoved = Lists.newArrayList();
        wheelDataList[i].forEach(wheel -> wheel.onUpdate(markedRemoved));
        markedRemoved.forEach(wheelDataList[i]::remove);
    }

    super.onEntityUpdate();

    this.allWheels.forEach(this::processWheel);

    Vector4d vec = wheeldata.carVector;
    this.backValue.setTarget(this.calculateWheelHeight(vec.y, false));
    this.frontValue.setTarget(this.calculateWheelHeight(vec.w, false));
    this.leftValue.setTarget(this.calculateWheelHeight(vec.z, true));
    this.rightValue.setTarget(this.calculateWheelHeight(vec.x, true));

    if (!this.world.isRemote) {
        this.updateHeal();
    }

    this.tickInterp();
    this.updateMotion();
    if (this.getPassengers().isEmpty() || !(this.getPassengers().get(0) instanceof EntityPlayer)) {
        this.setControlState((byte) 0);
    }
    if (this.world.isRemote) {
        this.handleControl();
    }
    this.applyMovement();
    this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
}

public BlockPos groundBlock(boolean ignoreAir) {
    Block block = this.blockState.getBlock();
    BlockPos blockpos = this.blockPosition();
    BlockState blockstate = this.level.getBlockState(blockpos);
    boolean isConcrete = this.blockState.getBlock() instanceof ConcretePowderBlock;
    boolean isConcreteInWater = isConcrete && this.level.getFluidState(blockpos).is(FluidTags.WATER);
    this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.5D, 0.7D));
    if (blockstate.is(Blocks.MOVING_PISTON))
        return null;
    if (this.cancelDrop) {
        this.discard();
        this.callOnBrokenAfterFall(block, blockpos);
        return null;
    }
    boolean canBeReplaced = blockstate.canBeReplaced(new DirectionalPlaceContext(this.level, blockpos, Direction.DOWN, ItemStack.EMPTY, Direction.UP));
    boolean isFreeBelow = FallingBlock.isFree(this.level.getBlockState(blockpos.below())) && (!isConcrete || !isConcreteInWater);
    boolean canSurvive = this.blockState.canSurvive(this.level, blockpos) && (!isFreeBelow || ignoreAir);
    if (canBeReplaced && canSurvive) {
        if (this.blockState.hasProperty(BlockStateProperties.WATERLOGGED) && this.level.getFluidState(blockpos).getType() == Fluids.WATER) {
            this.blockState = this.blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.TRUE);
        }

        if (this.level.setBlock(blockpos, this.blockState, 3)) {
            ((ServerLevel) this.level).getChunkSource().chunkMap.broadcast(this, new ClientboundBlockUpdatePacket(blockpos, this.level.getBlockState(blockpos)));
            this.discard();
            if (block instanceof Fallable fallable) {
                fallable.onLand(this.level, blockpos, this.blockState, blockstate, new FallingBlockEntity(level, this.getX(), this.getY(), this.getZ(), this.blockState));
            } else if (context != null && resolver != null) {
                RewindAttachment.get(context).addRewindEvent(level.getGameTime(), new EntityToBlockRewind(this, blockpos, this.blockState));
                ShapersFocus.tryPropagateBlockSpell(new BlockHitResult(
                        new Vec3(blockpos.getX(), blockpos.getY(), blockpos.getZ()), Direction.DOWN, blockpos, false
                ), level, getOwner(), context, resolver);
            }

            if (this.blockData != null && this.blockState.hasBlockEntity()) {
                BlockEntity blockentity = this.level.getBlockEntity(blockpos);
                if (blockentity != null) {

                    try {
                        blockentity.loadWithComponents(this.blockData, level.registryAccess());
                        if (blockentity instanceof SkullBlockEntity sk && this.blockData != null && this.blockData.contains("SkullOwner")) {
                            sk.setOwner(ANCodecs.decode(level.registryAccess(), ResolvableProfile.CODEC, this.blockData.getCompound("SkullOwner")));
                        }
                    } catch (Exception exception) {
                        exception.printStackTrace();
                    }

                    blockentity.setChanged();
                }
            }
            if (this.level.getBlockEntity(blockpos) instanceof MageBlockTile mbt) {
                if (context != null) {
                    mbt.color = context.getSpell().particleTimeline().get(ParticleTimelineRegistry.MAGEBLOCK_TIMELINE.get()).getColor();
                }
                mbt.setChanged();
            }

            return blockpos;
        } else if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
            this.discard();
            this.callOnBrokenAfterFall(block, blockpos);
            ItemStack itemstack = new ItemStack(block);
            if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                ResolvableProfile.CODEC
                        .parse(NbtOps.INSTANCE, blockData.get("profile"))
                        .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));
            }
            this.spawnAtLocation(itemstack);
            return null;
        }
    } else {
        this.discard();
        if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
            this.callOnBrokenAfterFall(block, blockpos);
            ItemStack itemstack = new ItemStack(block);
            if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                ResolvableProfile.CODEC
                        .parse(NbtOps.INSTANCE, blockData.get("profile"))
                        .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));

            }
            this.spawnAtLocation(itemstack);
        }
    }
    return null;
}

public void tick() {
    if (this.level.hasNeighborSignal(this.getBlockPos())) {
        this.miningTime = 0;
        return;
    }
    if (!this.level.isClientSide()) {
        ItemStack input = this.inputHandler.getStackInSlot(0);

        if (!this.cachedEnchantment) {
            this.setCachedEnchantment();
            this.cachedEnchantment = true;
        }

        // handle unusing enchantment from evilcraft, see
        // https://github.com/klikli-dev/occultism/issues/909
        if (input.isEnchanted() && input.getMaxDamage() - input.getDamageValue() < 6 &&
                this.UNUSING != null && input.getEnchantmentLevel(this.UNUSING) > 0) {
            this.miningTime = 0;
            return;
        }

        if (this.miningTime > 0) {

            int efficiency = this.bonusEfficiency && input.isEnchanted() ? input.getEnchantmentLevel(this.EFFICIENCY) : 0;
            if (efficiency > 0) {
                int extra1 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                int extra2 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                efficiency = Math.min(extra1, extra2);
            }

            this.miningTime -= 1 + efficiency;

            if (this.miningTime <= 0 && !this.level.isClientSide()) {
                this.mine();
            }

            if (input.getItem() != this.currentInputType) {
                this.miningTime = 0;
                this.possibleResults = null;
            }

            // handled by delta check
        } else if (!input.isEmpty()) {

            this.currentInputType = input.getItem();

            forceInitStackNBT(input, (ServerLevel) this.level);
            this.maxMiningTime = getMaxMiningTime(input);
            this.rollsPerOperation = getRollsPerOperation(input);
            this.outputMultiplier = getOutputMultiplier(input);
            this.miningTime = this.maxMiningTime;
        }

        // Sync Logic
        boolean needsSync = this.maxMiningTime != this.lastSyncedMaxMiningTime;

        // Sync if max mining time changed (e.g. new item with different stats)

        // Sync if mining active state changes (0 <-> >0)
        boolean wasActive = this.lastSyncedMiningTime > 0;
        boolean isActive = this.miningTime > 0;
        if (wasActive != isActive) {
            needsSync = true;
        }

        // Syncs if progress drifts by 10
        if (Math.abs(this.miningTime - this.lastSyncedMiningTime) >= 10) {
            needsSync = true;
        }
        // Also sync if we just finished (already covered by 0 check above? sorta).

        if (needsSync) {
            this.markNetworkDirty();
        }

        if (this.outputDirty) {
            this.setChanged();
            this.outputDirty = false;
        }
    } else {
        if (this.miningTime > 0 && this.level.getGameTime() % 10 == 0) {
            this.level.addParticle(ParticleTypes.PORTAL, this.worldPosition.getX() + 0.5f,
                    this.worldPosition.getY() + 0.5, this.worldPosition.getZ() + 0.5f, 0.0D, 0.0D, 0.0D);
        }
    }
}

public void rideTick() {
    Entity entity = this.getVehicle();
    if (this.isPassenger() && !entity.isAlive()) {
        this.stopRiding();
    } else {
        this.setDeltaMovement(0, 0, 0);
        this.tick();
        if (this.isPassenger()) {
            attachTime++;
            Entity mount = this.getVehicle();
            if (mount instanceof LivingEntity) {
                passengerIndex = mount.getPassengers().indexOf(this);
                this.yBodyRot = ((LivingEntity) mount).yBodyRot;
                this.setYRot( ((LivingEntity) mount).getYRot());
                this.yHeadRot = ((LivingEntity) mount).yHeadRot;
                this.yRotO = ((LivingEntity) mount).yHeadRot;
                float radius = mount.getBbWidth();
                float angle = (Maths.STARTING_ANGLE * (((LivingEntity) mount).yBodyRot + passengerIndex * 90F));
                double extraX = radius * Mth.sin(Mth.PI + angle);
                double extraZ = radius * Mth.cos(angle);
                this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                    this.removeVehicle();
                }
                this.setPhagePitch(0F);
                if (!this.level().isClientSide && attachTime > 15) {
                    LivingEntity target = (LivingEntity) mount;
                    float dmg = 1F;
                    if (target.getHealth() > target.getMaxHealth() * 0.2F) {
                        dmg = 6F;
                    }
                    if ((target.getHealth() < 1.5D || mount.hurt(this.damageSources().mobAttack(this), dmg)) && mount instanceof LivingEntity) {
                        dismountCooldown = 100;
                        if (mount instanceof EnderMan) {
                            this.setMissingEye(false);
                            this.gameEvent(GameEvent.EAT);
                            this.playSound(SoundEvents.ENDER_EYE_DEATH, this.getSoundVolume(), this.getVoicePitch());
                            this.heal(5);
                            ((EnderMan) mount).addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 400));
                            this.fleeAfterStealTime = 400;
                            this.setFlying(true);
                            this.angryEnderman = (PathfinderMob) mount;
                        } else {
                            if (random.nextInt(3) == 0) {
                                if (!this.isMissingEye()) {
                                    if (target.getEffect(AMEffectRegistry.ENDER_FLU.get()) == null) {
                                        target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), 12000));
                                    } else {
                                        MobEffectInstance inst = target.getEffect(AMEffectRegistry.ENDER_FLU.get());
                                        int duration = 12000;
                                        int level = 0;
                                        if (inst != null) {
                                            duration = inst.getDuration();
                                            level = inst.getAmplifier();
                                        }
                                        target.removeEffect(AMEffectRegistry.ENDER_FLU.get());
                                        target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), duration, Math.min(level + 1, 4)));
                                    }
                                    this.heal(5);
                                    this.gameEvent(GameEvent.ENTITY_ROAR);
                                    this.playSound(SoundEvents.ITEM_BREAK, this.getSoundVolume(), this.getVoicePitch());
                                    this.setMissingEye(true);
                                }
                                if (!this.level().isClientSide) {
                                    this.setTarget(null);
                                    this.setLastHurtMob(null);
                                    this.setLastHurtByMob(null);
                                    this.goalSelector.getRunningGoals().forEach(Goal::stop);
                                    this.targetSelector.getRunningGoals().forEach(Goal::stop);
                                }
                            }
                        }
                    }
                    if (((LivingEntity) mount).getHealth() <= 0 || this.fleeAfterStealTime > 0 || this.isMissingEye() && !(mount instanceof EnderMan) || !this.isMissingEye() && mount instanceof EnderMan) {
                        this.removeVehicle();
                        this.setTarget(null);
                        dismountCooldown = 100;
                        AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                        this.setFlying(true);
                    }
                }
            }

        }
    }

}

public void readFromNBT(NBTTagCompound nbt) {
    this.deserializing = true;

    super.readFromNBT(nbt);
    this.wasMoved = nbt.getBoolean("WasMoved");
    this.setAge(nbt.getInteger("DinosaurAge"));
    this.setCarcass(nbt.getBoolean("IsCarcass"));
    this.geneticsQuality = nbt.getInteger("DNAQuality");
    this.genetics = nbt.getString("Genetics");
    this.isMale = nbt.getBoolean("IsMale");
    this.growthSpeedOffset = nbt.getInteger("GrowthSpeedOffset");
    this.stayAwakeTime = nbt.getInteger("StayAwakeTime");
    this.setSleeping(nbt.getBoolean("IsSleeping"));
    this.carcassHealth = nbt.getInteger("CarcassHealth");
    this.order = Order.values()[nbt.getByte("Order")];
    this.breedCooldown = nbt.getInteger("BreedCooldown");
    this.pregnantTime = nbt.getInteger("PregnantTime");
    this.metabolism.readFromNBT(nbt);

    String ownerUUID = nbt.getString("OwnerUUID");
    if (ownerUUID.length() > 0) {
        this.owner = UUID.fromString(ownerUUID);
    }

    UUID uuid = nbt.getUniqueId("UUID");
    if (this.world != null) {
        boolean entityExists = this.world.loadedEntityList.stream()
                .anyMatch(entity -> entity.getUniqueID().equals(uuid));
        if (entityExists) {
            return; // Skip loading this entity instead of killing it
        }
    }
    this.setUniqueId(uuid);


    if (nbt.hasKey("Family")) {
        NBTTagCompound familyTag = nbt.getCompoundTag("Family");
        this.family = Family.readFromNBT(familyTag);
    }

    this.inventory.readFromNBT(nbt);

    NBTTagList trackersNBT = nbt.getTagList("TrackersUUID", Constants.NBT.TAG_STRING);
    this.trackersUUID.clear();
    for (int i = 0; i < trackersNBT.tagCount(); i++) {
        this.trackersUUID.add(trackersNBT.getStringTagAt(i));
    }
    this.dataManager.set(WATCHER_TRACKERS, new ArrayList<>(this.trackersUUID));

    NBTTagList relationships = nbt.getTagList("Relationships", Constants.NBT.TAG_COMPOUND);
    this.relationships.clear();
    for (int i = 0; i < relationships.tagCount(); i++) {
        NBTTagCompound compound = relationships.getCompoundTagAt(i);
        this.relationships.add(Relationship.readFromNBT(compound));
    }

    if (nbt.hasKey("GeneticAttributes")) {
        NBTTagCompound attributes = nbt.getCompoundTag("GeneticAttributes");
        this.attributes = DinosaurAttributes.from(attributes);
    }

    if (nbt.hasKey("Children")) {
        NBTTagList children = nbt.getTagList("Children", Constants.NBT.TAG_COMPOUND);
        this.children.clear();
        for (int i = 0; i < children.tagCount(); i++) {
            NBTTagCompound childTag = children.getCompoundTagAt(i);
            Entity entity = EntityList.createEntityFromNBT(childTag, this.world);
            if (entity instanceof DinosaurEntity) {
                DinosaurEntity child = (DinosaurEntity) entity;
                child.enablePersistence();
                this.children.add(child);
            }
        }
    }
    if (!this.world.isRemote) {
        DinosaurPersistenceHandler.trackEntity(this);
    }


    tranquilizerTicks = nbt.getInteger("TranquilizerTicks");
    ticksUntilDeath = nbt.getInteger("TicksUntilDeath");

    this.updateAttributes();
    this.updateBounds();

    this.deserializing = false;
}

public void render(GuiGraphics guiHelper, DeltaTracker deltaTracker) {
    if (Minecraft.getInstance().options.hideGui || Minecraft.getInstance().player.isSpectator()) {
        return;
    }
    var screenWidth = guiHelper.guiWidth();
    var screenHeight = guiHelper.guiHeight();
    Player player = Minecraft.getInstance().player;
    ManaBarOverlay.Display displayMode = ClientConfigs.SPELL_BAR_DISPLAY.get();
    if (displayMode == ManaBarOverlay.Display.Never || player == null) {
        return;
    } else if (displayMode == ManaBarOverlay.Display.Contextual) {
        handleFading(player);
        if (fadeoutDelay <= 0) {
            return;
        }
    } else {
        alpha = 1f;
    }

    var ssm = ClientMagicData.getSpellSelectionManager();
    if (ssm.getSpellCount() != lastSpellCount) {
        lastSpellCount = ssm.getSpellCount();
        ClientRenderCache.generateRelativeLocations(ssm, 20, 22);
        if (displayMode == ManaBarOverlay.Display.Contextual) {
            fadeoutDelay = CONTEXTUAL_FADE_WAIT;
        }
    }
    if (ssm.getSpellCount() <= 0) {
        return;
    }
    //System.out.println("SpellBarDisplay: Holding Spellbook");

    int centerX, centerY;
    int configOffsetY = ClientConfigs.SPELL_BAR_Y_OFFSET.get();
    int configOffsetX = ClientConfigs.SPELL_BAR_X_OFFSET.get();
    Anchor anchor = ClientConfigs.SPELL_BAR_ANCHOR.get();
    if (anchor == Anchor.Hotbar) {
        centerX = screenWidth / 2 - Math.max(110, screenWidth / 4);
        centerY = screenHeight - Math.max(55, screenHeight / 8);
    } else {
        centerX = screenWidth * anchor.m1;
        centerY = screenHeight * anchor.m2;
    }
    centerX += configOffsetX;
    centerY += configOffsetY;

    //
    //  Render Spells
    //
    List<SpellData> spells = ssm.getAllSpells().stream().map((slot) -> slot.spellData).toList();
    int spellbookCount = ssm.getSpellsForSlot(Curios.SPELLBOOK_SLOT).size();
    var locations = ClientRenderCache.relativeSpellBarSlotLocations;
    int approximateWidth = locations.size() / 3;
    //Move spellbar away from hotbar as it gets bigger
    centerX -= approximateWidth * 5;
    //var spellSelection = ClientMagicData.getSyncedSpellData(player).getSpellSelection();
    int selectedSpellIndex = ssm.getGlobalSelectionIndex();

    //Slot Border
    prepTranslucency();
    for (Vec2 location : locations) {
        guiHelper.blit(TEXTURE, centerX + (int) location.x, centerY + (int) location.y, 66, 84, 22, 22);
    }
    //Spell Icons
    for (int i = 0; i < locations.size(); i++) {
        guiHelper.blit(spells.get(i).getSpell().getSpellIconResource(), centerX + (int) locations.get(i).x + 3, centerY + (int) locations.get(i).y + 3, 0, 0, 16, 16, 16, 16);
    }
    //Border + Cooldowns
    for (int i = 0; i < locations.size(); i++) {
        if (i != selectedSpellIndex) {
            guiHelper.blit(TEXTURE, centerX + (int) locations.get(i).x, centerY + (int) locations.get(i).y, 22 + (!ssm.getAllSpells().get(i).slot.equals(Curios.SPELLBOOK_SLOT) ? 110 : 0), 84, 22, 22);
        }
        float f = ClientMagicData.getCooldownPercent(spells.get(i).getSpell());
        if (f > 0) {
            int pixels = (int) (16 * f + 1f);
            guiHelper.blit(TEXTURE, centerX + (int) locations.get(i).x + 3, centerY + (int) locations.get(i).y + 19 - pixels, 47, 87, 16, pixels);
        }
    }
    //Selected Outline
    for (int i = 0; i < locations.size(); i++) {
        //setTranslucentTexture(TEXTURE);
        if (i == selectedSpellIndex) {
            guiHelper.blit(TEXTURE, centerX + (int) locations.get(i).x, centerY + (int) locations.get(i).y, 0, 84, 22, 22);
        }
    }
    flushTranslucency();
}

public void tick() {
    if (!(this.level instanceof ServerLevel serverLevel)) {
        if (this.hitTimer == 1 && this.level != null) {
            this.level.addParticle(
                    ParticleTypes.ANGRY_VILLAGER,
                    this.getBlockPos().getX() + 0.5f,
                    this.getBlockPos().getY(),
                    this.getBlockPos().getZ() + 0.5f,
                    0.0D, 0.0D, 0.0D
            );
        }
        return;
    }

    if (serverLevel.hasNeighborSignal(this.getBlockPos()))
        return;

    ItemStack soul = getStack(this.inputSoulHandler, 0);
    ItemStack weapon = getStack(this.inputWeaponHandler, 0);
    ItemStack fuel = getStack(this.inputFuelHandler, 0);

    if (soul.isEmpty() || weapon.isEmpty()) {
        this.resetTime();
        return;
    }

    if (!this.cachedEnchantment)
        this.setCachedEnchantment();

    if (weapon.getDamageValue() >= weapon.getMaxDamage() - 6 &&
            this.UNUSING != null && weapon.getEnchantmentLevel(this.UNUSING) > 0) {
        this.resetTime();
        return;
    }

    if (this.storedLivingEntity == null
            || this.cachedSoul == null
            || this.cachedWeapon == null
            || !ItemStack.isSameItemSameComponents(this.cachedSoul, soul)
            || !this.cachedWeapon.is(weapon.getItem())) { //weapon damage in process, changing the components
        this.setStoredLivingEntity(soul, serverLevel);
        this.setMaxMobLife(serverLevel);
        this.cachedSoul = soul.copy();
        this.cachedWeapon = weapon.copy();
    }

    int fuelValue = fuel.getOrDefault(OccultismDataComponents.SOUL_VALUE, 0);

    if (fuel.isEmpty() || fuelValue * fuel.getCount() < this.soulValue) {
        this.resetTime();
        return;
    }

    if (this.wait) { //Reset the process, start from zero in next tick
        this.wait = false;
        this.mobHealth = this.maxMobLife;
        return;
    }

    if (--this.hitTimer > 0)
        return;

    this.hitTimer = this.maxHitTimer;
    this.mobHealth--;

    if (serverLevel.getRandom().nextFloat() < this.BUTCHER_HURT_CHANCE) {
        weapon.hurtAndBreak(1, serverLevel, null, item -> {
        });
        this.inputWeaponHandler.set(0, ItemResource.of(weapon), weapon.getCount());
    }

    if (this.mobHealth <= 0) {
        int luck = fuel.getOrDefault(OccultismDataComponents.LUCK_VALUE, 1);
        fuel.shrink(1 + (this.soulValue / Math.max(fuelValue, 1)));
        this.inputFuelHandler.set(0, ItemResource.of(fuel), fuel.getCount());

        this.defeat(soul, luck);
        this.mobHealth = this.maxMobLife;
    }

    this.markNetworkDirty();

    if (this.outputDirty) {
        this.setChanged();
        this.outputDirty = false;
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int burning = spellStat.getBurning();
    int range = spellStat.getRange();
    float radius = (float) spellStat.getRadius();
    if (WandUtil.enchantedFocus(caster)) {
        potency += WandUtil.getPotencyLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
        range += WandUtil.getRangeLevel(caster);
        radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 2.0F;
    }
    HitResult rayTrace = this.rayTrace(worldIn, caster, range, 3.0D);
    Vec3 location = rayTrace.getLocation();
    LivingEntity target = this.getTarget(caster, range);
    if (target != null){
        location = target.position();
    }
    BlockPos mutableBlockPos = new BlockPos.MutableBlockPos(location.x, location.y + 1.5D, location.z);
    int maxHeight = 15;
    int i = 0;
    while (mutableBlockPos.getY() < worldIn.getMaxBuildHeight() && worldIn.isEmptyBlock(mutableBlockPos) && i < maxHeight){
        mutableBlockPos = mutableBlockPos.above();
        i++;
    }
    if (rightStaff(staff)){
        potency += 2;
    }
    for (int j = 0; j < potency + 1; ++j){
        float xZ = 24.0F;
        float y = 4.0F;
        Vec3 vec3 = mutableBlockPos.getCenter()
                .add(worldIn.random.nextFloat() * xZ - (xZ / 2.0F),
                        worldIn.random.nextFloat() * y - (y / 2.0F),
                        worldIn.random.nextFloat() * xZ - (xZ / 2.0F));
        int clearTries = 0;
        while (clearTries < 6 && !worldIn.isEmptyBlock(BlockPos.containing(vec3)) && worldIn.getFluidState(BlockPos.containing(vec3)).isEmpty()){
            clearTries++;
            vec3 = mutableBlockPos.getCenter()
                    .add(worldIn.random.nextFloat() * xZ - (xZ / 2.0F),
                            worldIn.random.nextFloat() * y - (y / 2.0F),
                            worldIn.random.nextFloat() * xZ - (xZ / 2.0F));
        }
        if (!worldIn.isEmptyBlock(BlockPos.containing(vec3)) && worldIn.getFluidState(BlockPos.containing(vec3)).isEmpty()){
            vec3 = mutableBlockPos.getCenter();
        }
        Vec3 vec30 = vec3.offsetRandom(worldIn.getRandom(), 1.5F);
        worldIn.sendParticles(new FoggyCloudParticleOption(new ColorUtil(0x1a090d), 3.0F, 1), vec30.x(), vec30.y(), vec30.z(), 1, 0, 0, 0, 0);
        worldIn.sendParticles(new FoggyCloudParticleOption(new ColorUtil(0x240d12), 3.0F, 1), vec3.x(), vec3.y(), vec3.z(), 1, 0, 0, 0, 0);
        Vec3 vec31 = location.subtract(vec3);
        AbstractHurtingProjectile fireball = new Lavaball(worldIn,
                vec3.x,
                vec3.y,
                vec3.z,
                vec31.x,
                vec31.y,
                vec31.z);
        if (CuriosFinder.hasUnholySet(caster)){
            fireball = new HellBlast(vec3.x,
                    vec3.y,
                    vec3.z,
                    vec31.x,
                    vec31.y,
                    vec31.z, worldIn);
        }
        fireball.setOwner(caster);
        fireball.setPos(vec3);
        if (fireball instanceof Lavaball lavaball) {
            lavaball.setUpgraded(true);
            if (isShifting(caster)) {
                lavaball.setDangerous(false);
            }
            lavaball.setExtraDamage(potency);
            lavaball.setFiery(burning);
            lavaball.setExplosionPower(lavaball.getExplosionPower() + radius);
        } else if (fireball instanceof HellBlast hellBlast){
            hellBlast.setExtraDamage(potency);
            hellBlast.setRadius(hellBlast.getRadius() + radius);
            hellBlast.setFiery(burning);
        }
        if (worldIn.addFreshEntity(fireball)){
            SoundEvent soundEvent = SoundEvents.GHAST_SHOOT;
            if (fireball instanceof HellBlast){
                soundEvent = ModSounds.HELL_BLAST_SHOOT.get();
            }
            this.playSound(worldIn, fireball, soundEvent, 2.0F, this.projPitch(worldIn.getRandom()));
        }
    }
}

