    }
}

public void tick() {
    LivingEntity target = this.mob.getTarget();
    if (target != null) {
        if (timeSinceAttack < mob.getAttackCooldown()) {
            timeSinceAttack++;
        }

        double distToTarget = this.mob.distanceTo(target);

        float frontBackDistBuffer = 2f;
        float leftRightDistBuffer = 1.5f;
        if (chasing && distToTarget <= attackRadius) {
            chasing = false;
        }
        if (!chasing && distToTarget >= attackRadius + frontBackDistBuffer) {
            chasing = true;
        }

        // Chasing
        if (chasing) {
            this.mob.getNavigation().moveTo(target, 0.6);
            this.mob.getLookControl().setLookAt(target, 30.0F, 30.0F);
            mob.setStrafing(false);
            this.mob.setXxa(0);
            this.mob.getMoveControl().strafe(0, 0);
        }
        else {
            // In range
            if (!attacking && mob.getActiveAbility() == null) {
                this.mob.getNavigation().stop();
                float strafeSpeed = 0.5f;
                Vec3 circlePos = mob.updateCirclingPosition(this.attackRadius, strafeSpeed - 0.2f);
                double distToCirclePos = this.mob.position().distanceTo(circlePos);

                if (distToCirclePos <= leftRightDistBuffer) {
                    mob.setStrafing(true);

                    if (distToTarget > this.attackRadius + 0.5) {
                        this.strafingFrontBackMul = 1;
                    } else if (distToTarget < this.attackRadius - 0.5) {
                        this.strafingFrontBackMul = -1;
                    } else {
                        this.strafingFrontBackMul = 0;
                    }

                    Vec3 toTarget = target.position().subtract(this.mob.position()).multiply(1, 0, 1).normalize();
                    Vec3 toCirclePos = circlePos.subtract(this.mob.position()).multiply(1, 0, 1).normalize();
                    Vec3 cross = toTarget.cross(toCirclePos);
                    if (cross.y > 0) strafingLeftRightMul = 1;
                    else if (cross.y < 0) strafingLeftRightMul = -1;
                    else strafingLeftRightMul = 0;

                    float distScale = (float) Math.min(Math.pow(distToCirclePos * 1f / leftRightDistBuffer, 0.7), 1.0);

                    this.mob.getMoveControl().strafe(this.strafingFrontBackMul * strafeSpeed, this.strafingLeftRightMul * strafeSpeed * distScale);
                    this.mob.lookAt(target, 30.0F, 30.0F);

                    if (mob.random.nextFloat() < 0.002) {
                        mob.sendAbilityMessage(ROAR_ABILITY);
                    }
                } else {
                    this.mob.setXxa(0);
                    mob.setStrafing(false);
                    this.mob.getMoveControl().strafe(0, 0);
                    this.mob.getNavigation().moveTo(circlePos.x, circlePos.y, circlePos.z, 0.53);
                    this.mob.getLookControl().setLookAt(target, 30.0F, 30.0F);
                }
            }
            else {
                this.mob.setXxa(0);
                this.mob.getMoveControl().strafe(0, 0);
                mob.setStrafing(false);
            }

            // Attacking logic
            if (mob.random.nextInt(mob.getAttackChance()) == 0 && timeSinceAttack >= mob.getAttackCooldown() && mob.getSensing().hasLineOfSight(target)) {
                attacking = true;
            }
            if (attacking && mob.getActiveAbility() == null) {
                this.mob.setXxa(0);
                mob.setStrafing(false);
                mob.getNavigation().moveTo(target, 0.5);
                if (distToTarget <= 3.75 && mob.getSensing().hasLineOfSight(target)) {
                    attacking = false;
                    timeSinceAttack = 0;
                    AbilityHandler.INSTANCE.sendAbilityMessage(mob, ATTACK_ABILITY);
                }
            }
        }
    }
}

private boolean stealItem() {
    if (this.targetInventory != null) {
        Direction enumfacing = Direction.DOWN;

        if (isInventoryEmpty(this.targetInventory, enumfacing)) {
            return false;
        }
        if (this.targetInventory instanceof WorldlyContainer) {
            WorldlyContainer isidedinventory = (WorldlyContainer) this.targetInventory;
            int[] aint = isidedinventory.getSlotsForFace(enumfacing);

            for (int i : aint) {
                ItemStack itemstack = this.targetInventory.getItem(i);

                if (!itemstack.isEmpty() && canExtractItemFromSlot(this.targetInventory, itemstack, i, enumfacing))
                {
                    ItemStack itemstack1 = itemstack.copy();
                    this.targetInventory.setItem(i, ItemStack.EMPTY);
                    if (itemstack1.getItem().isEdible()) {
                        this.taskOwner.playSound(SoundEvents.PLAYER_BURP, 1, 1);
                        this.taskOwner.addHunger((itemstack1.getItem().getFoodProperties().getNutrition() * 10 * itemstack1.getCount()));
                        for(Pair<MobEffectInstance, Float> pair : itemstack1.getItem().getFoodProperties().getEffects()) {
                            if (pair.getFirst() != null && this.taskOwner.level.random.nextFloat() < pair.getSecond()) {
                                this.taskOwner.addEffect(new MobEffectInstance(pair.getFirst()));
                            }
                        }
                        return false;
                    }
                    if (!PotionUtils.getMobEffects(itemstack1).isEmpty()) {
                        this.taskOwner.playSound(SoundEvents.PLAYER_BURP, 1, 1);
                        this.taskOwner.addHunger(10);
                        for(MobEffectInstance effectinstance : PotionUtils.getMobEffects(itemstack1)) {
                            if (effectinstance.getEffect().isInstantenous()) {
                                effectinstance.getEffect().applyInstantenousEffect(this.taskOwner, this.taskOwner, this.taskOwner, effectinstance.getAmplifier(), 1.0D);
                            } else {
                                this.taskOwner.addEffect(new MobEffectInstance(effectinstance));
                            }
                        }
                        return false;
                    }
                    this.taskOwner.spawnAtLocation(itemstack, 0.2f);
                    return true;
                }
            }
        } else {
            int j = this.targetInventory.getContainerSize();

            for (int k = 0; k < j; ++k) {
                ItemStack itemstack = this.targetInventory.getItem(k);

                if (!itemstack.isEmpty() && canExtractItemFromSlot(this.targetInventory, itemstack, k, enumfacing))
                {
                    ItemStack itemstack1 = itemstack.copy();
                    this.targetInventory.setItem(k, ItemStack.EMPTY);
                    this.taskOwner.setAnimation(EntityBear.ATTACK_SWIPE);
                    if (itemstack1.getItem().isEdible()) {
                        this.taskOwner.playSound(SoundEvents.PLAYER_BURP, 1, 1);
                        this.taskOwner.addHunger((itemstack1.getItem().getFoodProperties().getNutrition() * 10 * itemstack1.getCount()));
                        for(Pair<MobEffectInstance, Float> pair : itemstack1.getItem().getFoodProperties().getEffects()) {
                            if (pair.getFirst() != null && this.taskOwner.level.random.nextFloat() < pair.getSecond()) {
                                this.taskOwner.addEffect(new MobEffectInstance(pair.getFirst()));
                            }
                        }
                        return false;
                    }
                    if (!PotionUtils.getMobEffects(itemstack1).isEmpty()) {
                        this.taskOwner.playSound(SoundEvents.GENERIC_DRINK, 1, 1);
                        this.taskOwner.addHunger(10);
                        for(MobEffectInstance effectinstance : PotionUtils.getMobEffects(itemstack1)) {
                            if (effectinstance.getEffect().isInstantenous()) {
                                effectinstance.getEffect().applyInstantenousEffect(this.taskOwner, this.taskOwner, this.taskOwner, effectinstance.getAmplifier(), 1.0D);
                            } else {
                                this.taskOwner.addEffect(new MobEffectInstance(effectinstance));
                            }
                        }
                        return false;
                    }
                    if (!(itemstack1.getItem().isEdible()) || !PotionUtils.getMobEffects(itemstack).isEmpty()) {
                        this.taskOwner.spawnAtLocation(itemstack, 0.2f);
                    }
                    else {
                        this.taskOwner.playSound(SoundEvents.PLAYER_BURP, 1, 1);
                        return false;
                    }
                    return true;
                }
            }
        }
    }
    return false;
}

public void update() {
    ItemStack handHeld = this.entity.getItemInHand(InteractionHand.MAIN_HAND);
    var recipeInput = new TieredSingleRecipeInput(handHeld, this.tier.get());
    Level level = this.entity.level();

    if (!this.currentRecipe.isPresent() && !handHeld.isEmpty()) {
        this.currentRecipe = ((ServerLevel) level).recipeAccess().getRecipeFor(OccultismRecipes.CRYSTALLIZE_TYPE.get(),
                recipeInput, level);
        this.crystallizeTimer = 0;

        if (this.currentRecipe.isPresent()) {
            //play crystallize sound
            level.playSound(null, this.entity.blockPosition(), SoundEvents.AMETHYST_CLUSTER_STEP,
                    SoundSource.NEUTRAL, 1f, 1 + 0.5f * this.entity.getRandom().nextFloat());
        } else {
            //if no recipe is found, drop hand held item as we can't process it
            this.entity.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, handHeld);
            if (droppedItem != null) {
                droppedItem.addTag(DROPPED_BY_CRYSTALLIZER);
            }
        }
    }
    if (this.currentRecipe.isPresent()) {
        if (handHeld.isEmpty() || !this.currentRecipe.get().value().matches(recipeInput, level)) {
            //Reset cached recipe if it no longer matches
            this.currentRecipe = Optional.empty();
        } else {
            //advance conversion
            this.crystallizeTimer++;

            //show particle effect while crystallize
            if (level.getGameTime() % 10 == 0) {
                Vec3 pos = this.entity.position();
                ((ServerLevel) level)
                        .sendParticles(ParticleTypes.WITCH, pos.x + level.getRandom().nextGaussian() / 3,
                                pos.y + 0.5, pos.z + level.getRandom().nextGaussian() / 3, 1, 0.0, 0.0, 0.0,
                                0.0);
            }

            //every two seconds, play another crystallize sound
            if (level.getGameTime() % 40 == 0) {
                level.playSound(null, this.entity.blockPosition(), SoundEvents.AMETHYST_CLUSTER_STEP,
                        SoundSource.NEUTRAL, 1f,
                        1 + 0.5f * this.entity.getRandom().nextFloat());
            }

            if (this.crystallizeTimer >= this.currentRecipe.get().value().getCrystallizeTime() * this.crystallizeTimeMultiplier.get()) {
                this.crystallizeTimer = 0;

                ItemStack result = this.currentRecipe.get().value().assemble(recipeInput);
                //make sure to ignore output multiplier on recipes that set that flag.
                //prevents e.g. 1x ingot -> 3x dust -> 3x ingot -> 9x dust ...
                float outputMultiplier = this.outputMultiplier.get();
                if (this.currentRecipe.get().value().getIgnoreCrystallizeMultiplier())
                    outputMultiplier = 1;
                int a = Math.min(this.operationCount.get(), handHeld.getCount());
                result.setCount((int) (result.getCount() * a * outputMultiplier));
                ItemStack inputCopy = handHeld.copy();
                inputCopy.setCount(a);
                handHeld.shrink(a);

                this.entity.setItemInHand(InteractionHand.MAIN_HAND, handHeld);

                this.onCrystallize(inputCopy, result);
                var event = new CrystallizerJobEvent(this.entity, inputCopy, result);
                NeoForge.EVENT_BUS.post(event);
                if (!event.getResult().isEmpty()) {
                    boolean flag = true;
                    if (level.getBlockState(this.entity.blockPosition().below()).is(OccultismBlocks.DIMENSIONAL_EXTRACTOR)) {
                        if (this.cachedStateBelow != level.getBlockState(this.entity.blockPosition().below(2)))
                            this.updateBelowBlock();
                        if (this.handlerBelow != null) {
                            ItemTransferUtil.insertItemStacked(this.handlerBelow, event.getResult(), false);
                            flag = false;
                        }

                    }
                    if (flag) {
                        ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, event.getResult());
                        if (droppedItem != null) {
                            droppedItem.addTag(DROPPED_BY_CRYSTALLIZER);
                        }
                    }
                }
                //Don't reset recipe here, keep it cached
            }
        }
    }
    super.update();
}

public void tick() {
    super.tick();
    repelEntities(1.7F, 3.7f, 1.7F, 1.7F);
    LivingEntity target = this.getTarget();
    prevdeactivateProgress = deactivateProgress;
    if (!this.getIsAwaken() && deactivateProgress < 30F) {
        deactivateProgress++;
    }
    if (this.getIsAwaken() && deactivateProgress > 0F) {
        deactivateProgress--;

    }

    if(!this.getIsAwaken()) {
        if (this.tickCount % 20 == 0) {
            this.heal(2.0F);
        }
    }

    if (deactivateProgress == 0 && this.isAlive()) {
        if (target != null && target.isAlive()) {
            if (void_rune_attack_cooldown <= 0 && !isNoAi() && this.getAnimation() == NO_ANIMATION && target.onGround() && (this.random.nextInt(45) == 0 && this.distanceTo(target) < 4 || this.random.nextInt(24) == 0 && this.distanceTo(target) < 10)) {
                void_rune_attack_cooldown = VOID_RUNE_ATTACK_COOLDOWN;
                this.setAnimation(VOID_RUNE_ATTACK);

            } else if (this.distanceTo(target) < 4 && !isNoAi() && this.getAnimation() == NO_ANIMATION) {
                Animation animation = getRandomAttack(random);
                this.setAnimation(animation);
            }
        }

        if (this.getAnimation() == ANIMATION_EARTHQUAKE) {
            if (this.getAnimationTick() == 19) {
                EarthQuake(5,6);
                EarthQuakeParticle();
                if (!this.level().isClientSide) {
                    if (CMCommonConfig.EnderGolem.ignoreMobGriefing) {
                        BlockBreaking(4, 4, 4);
                    } else {
                        if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                            BlockBreaking(4, 4, 4);
                        }
                    }
                }
            }
        }
        if ((this.getAnimation() == ANIMATION_ATTACK1 || this.getAnimation() == ANIMATION_ATTACK2) && this.getAnimationTick() == 13) {
            this.playSound(ModSounds.GOLEMATTACK.get(), 1, 1);
            if (target != null && target.isAlive()) {
                if (this.distanceTo(target) < 4.75F) {
                    target.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) + this.random.nextInt(4));
                    target.knockback(1.25F, this.getX() - target.getX(), this.getZ() - target.getZ());
                }
            }
        }
        if (this.getAnimation() == VOID_RUNE_ATTACK) {
            if (this.getAnimationTick() == 22) {
                EarthQuake(4.25f,4);
                EarthQuakeParticle();
                if (!this.level().isClientSide) {
                    if (CMCommonConfig.EnderGolem.ignoreMobGriefing) {
                        BlockBreaking(4, 4, 4);
                    } else {
                        if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                            BlockBreaking(4, 4, 4);
                        }
                    }
                }
            }
            if (this.getAnimationTick() == 28) {
                VoidRuneAttack();
            }
        }
    }
    if (void_rune_attack_cooldown > 0) void_rune_attack_cooldown--;
    if (!level().isClientSide) {
        timeWithoutTarget++;
        if (target != null) {
            timeWithoutTarget = 0;
            if(!this.getIsAwaken()) {
                this.setIsAwaken(true);
            }
        }

        if (timeWithoutTarget > 400 && this.getIsAwaken() && target == null) {
            timeWithoutTarget = 0;
            this.setIsAwaken(false);
        }
    }

}

