public static AttackShieldResult attackShield(World world, ProtectionShield shield, Vec3d centerPos, float shieldRotationYaw, float shieldRotationPitch, float shieldRotationRoll, float shieldExplosion, Object2IntMap<Entity> deflectionDamageCooldowns, DamageSource source, boolean checkOnly) {
	if(source instanceof EntityDamageSource) {
		EntityDamageSource entityDamage = (EntityDamageSource) source;

		Entity sourceEntity = entityDamage.getTrueSource();
		Entity immediateEntity = entityDamage.getImmediateSource();

		Entity attackingEntity = immediateEntity != null ? immediateEntity : sourceEntity;

		int shieldHit = -1;
		boolean isDeflected = false;

		Vec3d ray = null;
		Vec3d pos = null;

		if(attackingEntity == null) {
			isDeflected = true;
		} else {
			if(attackingEntity instanceof EntityLivingBase) {
				ray = attackingEntity.getLookVec();
			} else {
				ray = new Vec3d(attackingEntity.motionX, attackingEntity.motionY, attackingEntity.motionZ).normalize();
			}
			ray = ray.scale(64.0D);

			pos = new Vec3d(attackingEntity.posX, attackingEntity.posY + attackingEntity.getEyeHeight(), attackingEntity.posZ);

			if(shield.hasShield() && (attackingEntity instanceof EntityPlayer == false || !((EntityPlayer)attackingEntity).capabilities.isCreativeMode) || attackingEntity.isSneaking()) {
				shieldHit = rayTraceShield(shield, centerPos, shieldRotationYaw, shieldRotationPitch, shieldRotationRoll, shieldExplosion, pos, ray, false);

				if(shieldHit >= 0) {
					if(!checkOnly) {
						if(!world.isRemote && attackingEntity.isSneaking() && ((EntityPlayer)attackingEntity).capabilities.isCreativeMode) {
							shield.setActive(shieldHit, false);
						}

						if(world.isRemote) {
							shield.setAnimationTicks(shieldHit, 20);
						}
					}

					isDeflected = true;
				}
			}
		}

		if(isDeflected) {
			if(!checkOnly && !world.isRemote) {
				boolean damaged = false;

				if(sourceEntity != null && !deflectionDamageCooldowns.containsKey(sourceEntity)) {
					double dx = sourceEntity.posX - centerPos.x;
					double dy = sourceEntity.posY - centerPos.y;
					double dz = sourceEntity.posZ - centerPos.z;
					double len = Math.sqrt(dx*dx+dy*dy+dz*dz);
					sourceEntity.motionX = dx / len * 0.8F;
					sourceEntity.motionY = dy / len * 0.8F;
					sourceEntity.motionZ = dz / len * 0.8F;
					sourceEntity.velocityChanged = sourceEntity.isAirBorne = true;
					sourceEntity.attackEntityFrom(DamageSource.MAGIC, 2);

					deflectionDamageCooldowns.put(sourceEntity, 10);
					damaged = true;
				}

				if(immediateEntity != null && !deflectionDamageCooldowns.containsKey(immediateEntity)) {
					double dx = immediateEntity.posX - centerPos.x;
					double dy = immediateEntity.posY - centerPos.y;
					double dz = immediateEntity.posZ - centerPos.z;
					double len = Math.sqrt(dx*dx+dy*dy+dz*dz);
					immediateEntity.motionX = dx / len * 0.8F;
					immediateEntity.motionY = dy / len * 0.8F;
					immediateEntity.motionZ = dz / len * 0.8F;
					immediateEntity.velocityChanged = immediateEntity.isAirBorne = true;
					immediateEntity.attackEntityFrom(DamageSource.MAGIC, 2);

					deflectionDamageCooldowns.put(immediateEntity, 10);
					damaged = true;
				}

				if(damaged) {
					world.playSound(null, centerPos.x, centerPos.y, centerPos.z, SoundRegistry.FORTRESS_BOSS_NOPE, SoundCategory.HOSTILE, 1, 1);
				}
			}

			return new AttackShieldResult(true, shieldHit, pos, ray);
		} else {
			return new AttackShieldResult(false, shieldHit, pos, ray);
		}
	}

	return new AttackShieldResult(true, -1, null, null);
}

public void onUpdate() {
	this.prevHeadLook = this.headLook;

	super.onUpdate();

	if(this.clientHeadLookChanged) {
		this.headLook = new Vec3d(this.dataManager.get(LOOK_X), this.dataManager.get(LOOK_Y), this.dataManager.get(LOOK_Z));
		this.clientHeadLookChanged = false;
	}

	if(!this.world.isRemote) {
		EntityLivingBase attackTarget = this.getAttackTarget();

		this.dataManager.set(HIDDEN, attackTarget == null);

		if(attackTarget != null) {
			this.setHeadLook(attackTarget.getPositionEyes(1).subtract(this.getPositionEyes(1)));
		} else {
			this.setHeadLook(new Vec3d(this.getFacing().getDirectionVec()));
		}
	} else {
		this.prevHiddenPercent = this.hiddenPercent;

		if(this.dataManager.get(HIDDEN)) {
			if(this.hiddenPercent < 1.0F) {
				this.hiddenPercent += 0.01F;
				if(this.hiddenPercent > 1.0F) {
					this.hiddenPercent = 1.0F;
				}
			}
		} else {
			if(this.hiddenPercent > 0.0F) {
				this.hiddenPercent -= 0.04F;
				if(this.hiddenPercent < 0.0F) {
					this.hiddenPercent = 0.0F;
				}
			}
		}

		this.updateWallSprite();
	}

	if(this.isSucking()) {
		this.suckTimer--;

		if(!this.world.isRemote) {
			List<Entity> affectedEntities = (List<Entity>)this.world.getEntitiesWithinAABB(Entity.class, this.getEntityBoundingBox().grow(6.0F, 6.0F, 6.0F));

			for(Entity e : affectedEntities) {
				float dst = e.getDistance(this);

				if(e == this || dst > 6.0F || !this.canEntityBeSeen(e) || e instanceof IEntityBL) {
					continue;
				}

				Vec3d vec = new Vec3d(this.posX - e.posX, this.posY - e.posY, this.posZ - e.posZ);
				vec = vec.normalize();

				float mod = (float) Math.pow(1.0F - dst / 6.0F, 1.3D);

				if(e instanceof EntityPlayer) {
					if(((EntityPlayer)e).isActiveItemStackBlocking()) mod *= 0.18F;
				}

				e.motionX += vec.x * 0.1F * mod;
				e.motionY += vec.y * 0.215F * mod;
				e.motionZ += vec.z * 0.1F * mod;

				e.velocityChanged = true;
			}
		} else {
			Vec3d fwd = this.getHeadLook(1);
			Vec3d up = new Vec3d(this.getFacingUp().getDirectionVec());
			Vec3d right = fwd.crossProduct(up);

			Vec3d front = this.getFrontCenter().add(fwd.scale(0.3D)).add(up.scale(-0.3D));

			for(int i = 0; i < 3; i++) {
				Random rnd = this.world.rand;

				Vec3d vec = fwd.scale(rnd.nextFloat() * 5).add(up.scale((rnd.nextFloat() - 0.5F) * 1.2F)).add(right.scale((rnd.nextFloat() - 0.5F) * 1.2F));

				float rx = (float)vec.x;
				float ry = (float)vec.y;
				float rz = (float)vec.z;

				vec = vec.normalize();

				this.world.spawnParticle(EnumParticleTypes.SMOKE_NORMAL, front.x + rx, front.y + ry, front.z + rz, -vec.x * 0.5F, -vec.y * 0.5F, -vec.z * 0.5F);
			}
		}
	}
}

public void aiStep() {
	super.aiStep();

	if (this.getVehicle() == null) this.setFallSpeed(this.getFallSpeed() + 0.1F);

	if (this.getRandom().nextInt(50000) < 10 && !this.isHungry() && !this.hasFruit()) {
		this.setHungry(true);
	}

	if (this.level().isClientSide) {
		this.prevTailAnimation = this.tailAnimation;
		this.prevSwimmingAnimation = this.swimmingAnimation;
		if (!this.isInWater()) {
			this.tailSpeed = 1.0F;
			this.swimmingAnimationSpeed = 1.0F;
		} else if (this.isMoving()) {
			if (this.tailSpeed < 0.5F) {
				this.tailSpeed = 1.0F;
			} else {
				this.tailSpeed += (0.25F - this.tailSpeed) * 0.1F;
			}
		} else {
			this.tailSpeed += (0.1875F - this.tailSpeed) * 0.1F;
		}
		if (this.getFallSpeed() > 0.0F) {
			if (this.swimmingAnimationSpeed < 0.5F) {
				this.swimmingAnimationSpeed = 1.0F;
			} else {
				this.swimmingAnimationSpeed += ((this.swimmingAnimationSpeed * 2.5F) - this.getFallSpeed()) * 0.1F;
			}
		} else {
			this.swimmingAnimationSpeed = 1.0F;
		}
		this.tailAnimation += this.tailSpeed;
		this.swimmingAnimation += this.swimmingAnimationSpeed;
	}

	if (this.getBoofBoostCooldown() > 0) {
		this.setBoofBoostCooldown(this.getBoofBoostCooldown() - 1);
	}

	if ((this.onGround() || this.isPassenger()) && this.doesWantToGrow() && this.level().noCollision(this.getBoundingBox().inflate(2.0F, 0.0F, 2.0F))) {
		this.growUp();
	}

	if (!this.level().isClientSide && ((!this.isDescenting() && !this.isEating()) && this.getBoofBoostCooldown() <= 0 && (this.onGround() || this.isEyeInFluid(FluidTags.WATER)))) {
		this.push(-Mth.sin((float) (this.getYRot() * Math.PI / 180.0F)) * (5 * (random.nextFloat() + 0.1F)) * 0.1F, (random.nextFloat() * 0.45F) + 0.65F, Mth.cos((float) (this.getYRot() * Math.PI / 180.0F)) * (5 * (random.nextFloat() + 0.1F)) * 0.1F);
		NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.ADOLESCENT_BOOFLO_BOOF);
		this.setFallSpeed(0.0F);
		//Fixes super boosting underwater
		if (this.wasEyeInWater) {
			this.setBoofBoostCooldown(20);
		}
	}

	//Helps them not fall off the edge
	if ((this.getBoofBoostCooldown() <= 0 && !this.onGround()) && this.level().dimension() == Level.END && !this.isSafePos(this.blockPosition(), 3)) {
		this.setBoofBoostCooldown(20);
		this.setFallSpeed(0.0F);

		if (this.getY() <= 50) {
			this.push(-Mth.sin((float) (this.getYRot() * Math.PI / 180.0F)) * (5 * (random.nextFloat() + 0.1F)) * 0.1F, (random.nextFloat() * 0.45F) + 0.65F, Mth.cos((float) (this.getYRot() * Math.PI / 180.0F)) * (5 * (random.nextFloat() + 0.1F)) * 0.1F);
			this.setPlayingEndimation(EEPlayableEndimations.ADOLESCENT_BOOFLO_BOOF);
		}
	}

	if (!this.onGround() && this.level().dimension() == Level.END && !this.isSafePos(this.blockPosition(), 3) && !this.level().isClientSide) {
		this.push(-Mth.sin((float) (this.getYRot() * Math.PI / 180.0F)) * 0.01F, 0, Mth.cos((float) (this.getYRot() * Math.PI / 180.0F)) * 0.01F);
	}

	if (this.getBoofloAttackTarget() != null && this.hasLineOfSight(this.getBoofloAttackTarget())) {
		this.setYRot(this.yHeadRot);
	}

	if (this.level().isClientSide) {
		if (this.forcedAgeTimer > 0) {
			if (this.forcedAgeTimer % 4 == 0) {
				this.level().addParticle(ParticleTypes.HAPPY_VILLAGER, this.getX() + (this.random.nextFloat() * this.getBbWidth() * 2.0F) - this.getBbWidth(), this.getY() + 0.5D + (this.random.nextFloat() * this.getBbHeight()), this.getZ() + (this.random.nextFloat() * this.getBbWidth() * 2.0F) - this.getBbWidth(), 0.0D, 0.0D, 0.0D);
			}

			this.forcedAgeTimer--;
		}
	} else if (this.isAlive() && this.hasEaten()) {
		int growingAge = this.getGrowingAge();
		if (growingAge < 0) {
			growingAge++;
			this.setGrowingAge(growingAge);
		} else if (growingAge > 0) {
			growingAge--;
			this.setGrowingAge(growingAge);
		}
	}
}

public void tick() {
    super.tick();
    prevUncrossedArmsProgress = uncrossedArmsProgress;
    prevTeleportingProgress = teleportingProgress;
    if (!this.areArmsCrossed() && uncrossedArmsProgress < 5F) {
        uncrossedArmsProgress++;
    }
    if (this.areArmsCrossed() && uncrossedArmsProgress > 0F) {
        uncrossedArmsProgress--;
    }
    if (this.getTeleportingToPos() != null && teleportingProgress < 40F) {
        teleportingProgress++;
    }
    if (this.getTeleportingToPos() == null && teleportingProgress > 0F) {
        teleportingProgress = Math.max(0, teleportingProgress - 10);
    }
    if (this.getAnimation() == ANIMATION_SPELL_1) {
        float f = this.getAnimationTick() < 10 ? 0.2F : this.getAnimationTick() > 40 ? -0.2F : 0;
        float backAmount = this.getAnimationTick() > 40 ? 0.0F : 0.1F;
        this.setDeltaMovement(new Vec3(0, f, 0).add(new Vec3(0, 0, -backAmount).yRot((float) -Math.toRadians(this.getYRot()))));
        this.fallDistance = 0.0F;
    }
    if (updateHeldItems && !level().isClientSide) {
        ItemStack main = ItemStack.EMPTY;
        ItemStack offhand = ItemStack.EMPTY;
        if (this.getAnimation() == ANIMATION_SPELL_0 || this.getAnimation() == ANIMATION_SPELL_1) {
            main = new ItemStack(ACItemRegistry.SUGAR_STAFF.get());
        }
        if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() < 90) {
            main = new ItemStack(ACBlockRegistry.CANDY_CANE.get());
        }
        if (!main.isEmpty() || this.areArmsVisuallyCrossed(1.0F)) {
            this.setItemInHand(InteractionHand.MAIN_HAND, main);
        }
        if (!offhand.isEmpty() || this.areArmsVisuallyCrossed(1.0F)) {
            this.setItemInHand(InteractionHand.OFF_HAND, offhand);
        }
    }
    if (updateFoldedArms) {
        boolean unfold = this.teleportingProgress > 0 || this.getAnimation() == ANIMATION_SPELL_0 || this.getAnimation() == ANIMATION_SPELL_1 || this.getAnimation() == ANIMATION_SWING_LEFT || this.getAnimation() == ANIMATION_SWING_RIGHT;
        this.setArmsCrossed(!unfold);
    }
    if (!level().isClientSide) {
        List<UUID> possessedIds = getPossessedUUIDs();
        if (level() instanceof ServerLevel) {
            for (UUID possessedId : possessedIds) {
                Entity possessedEntity = ((ServerLevel) level()).getEntity(possessedId);
                if (possessedEntity != null) {
                    this.tickPossessedEntity(possessedEntity);
                }
            }
        }
        if (this.getHealth() < this.getMaxHealth() && this.getAnimation() == NO_ANIMATION && tickCount % 20 == 8 && eatCooldown == 0) {
            this.setAnimation(ANIMATION_EAT);
            eatCooldown = 200;
        }
        if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() == 90) {
            this.heal(5);
        }
        if (eatCooldown > 0) {
            eatCooldown--;
        }
    } else {
        if (this.getTeleportingToPos() != null && this.getTeleportingProgress(1.0F) < 1.0F) {
            Vec3 angle = new Vec3(random.nextBoolean() ? 0.5F : -0.5F, 2.0F, 0.0F).yRot((float) -Math.toRadians(this.yBodyRot));
            Vec3 delta = new Vec3(random.nextGaussian() * 2.0F, 4.0F, random.nextGaussian()).yRot((float) -Math.toRadians(this.yBodyRot)).add(this.position());
            this.level().addParticle(ACParticleRegistry.PURPLE_WITCH_MAGIC.get(), this.getX() + angle.x, this.getY() + angle.y, this.getZ() + angle.z, delta.x, delta.y, delta.z);
        } else if (this.random.nextFloat() < 0.003F) {
            for (int i = 0; i < this.random.nextInt(2) + 2; ++i) {
                this.level().addParticle(ACParticleRegistry.WITCH_COOKIE.get(), this.getX() + this.random.nextGaussian() * (double) 0.13F, this.getBoundingBox().maxY + 0.5D + this.random.nextGaussian() * (double) 0.13F, this.getZ() + this.random.nextGaussian() * (double) 0.13F, 0.0D, 0.0D, 0.0D);
            }
        }
    }
    if (this.teleportingProgress >= 40 && this.getTeleportingToPos() != null) {
        Vec3 vec3 = this.getTeleportingToPos();
        this.setPos(vec3.x, vec3.y, vec3.z);
        if (!level().isClientSide) {
            this.setTeleportingToPos(null);
        } else {
            for (int i = 0; i < this.random.nextInt(8) + 8; ++i) {
                this.level().addParticle(ACParticleRegistry.PURPLE_WITCH_EXPLOSION.get(), this.getX() + this.random.nextGaussian() * (double) 0.3F, this.getY() + this.random.nextGaussian() * (double) 1.5F, this.getZ() + this.random.nextGaussian() * (double) 0.3F, 0.0D, 0.0D, 0.0D);
            }
        }
        this.setOldPosAndRot();
        this.postTeleport();
    }
    if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() < 90 && this.getAnimationTick() % 4 == 0) {
        this.triggerItemUseEffects(this.getItemInHand(InteractionHand.MAIN_HAND), 2);
    }
    if (teleportCooldown > 0) {
        teleportCooldown--;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public static void onEntityJoinWorld(EntityJoinLevelEvent event) {
    Entity entity = event.getEntity();
    Level world = event.getLevel();
    if (entity instanceof LivingEntity && !world.isClientSide()) {
        if (entity instanceof Player player) {
            SEHelper.sendSEUpdatePacket(player);
            LichdomHelper.sendLichUpdatePacket(player);
        }
        if (entity instanceof Mob mob) {
            if (entity instanceof Witch witch) {
                witch.goalSelector.addGoal(1, new WitchBarterGoal(witch));
            }
            if (mob.getType().is(ModTags.EntityTypes.VILLAGE_GUARDS)) {
                mob.goalSelector.addGoal(1, new FreePrisonerGoal(mob));
                mob.targetSelector.addGoal(3, new TargetHostileOwnedGoal<>(mob, Owned.class));
                mob.targetSelector.addGoal(3, new DefendVillagerGoal(mob));
            }
            if (entity instanceof PathfinderMob creeper && creeper.getType().is(ModTags.EntityTypes.CREEPERS)) {
                creeper.goalSelector.addGoal(3, new AvoidEntityGoal<>(creeper, Player.class, (target) -> target != null && CuriosFinder.hasCurio(target, ModItems.FELINE_AMULET.get()), 6.0F, 1.0D, 1.2D, EntitySelector.NO_SPECTATORS::test));
            }
            if (entity instanceof Zombie zombie) {
                boolean villagerHater = zombie.targetSelector
                        .getAvailableGoals()
                        .stream()
                        .anyMatch(goal -> goal.getGoal() instanceof NearestAttackableTargetGoal<?> targetGoal && targetGoal.targetType == AbstractVillager.class);
                if (villagerHater) {
                    zombie.targetSelector.addGoal(3, new NearestAttackableTargetGoal<>(zombie, Prisoner.class, false));
                }
            }
        }
    }
    if (MainConfig.BetterDragonFireball.get()) {
        if (entity instanceof DragonFireball original) {
            ModDragonFireball dragonFireball;
            if (original.getOwner() instanceof LivingEntity livingEntity) {
                dragonFireball = new ModDragonFireball(entity.level, livingEntity, original.xPower, original.yPower, original.zPower);
            } else {
                dragonFireball = new ModDragonFireball(ModEntityType.MOD_DRAGON_FIREBALL.get(), entity.level);
            }
            dragonFireball.moveTo(original.position());
            if (entity.level.addFreshEntity(dragonFireball)) {
                original.discard();
                event.setCanceled(true);
            }
        }
        if (entity instanceof AreaEffectCloud cloud){
            if (cloud.getOwner() instanceof EnderDragon){
                DragonBreathCloud breathCloud = new DragonBreathCloud(entity.level, cloud.getX(), cloud.getY(), cloud.getZ());
                breathCloud.setOwner(cloud.getOwner());
                breathCloud.setRadius(cloud.getRadius());
                breathCloud.setRadiusOnUse(cloud.getRadiusOnUse());
                breathCloud.setRadiusPerTick(cloud.getRadiusPerTick());
                breathCloud.setDuration(cloud.getDuration());
                breathCloud.setDurationOnUse(cloud.getDurationOnUse());
                breathCloud.setWaitTime(cloud.getWaitTime());
                if (entity.level.addFreshEntity(breathCloud)) {
                    cloud.discard();
                    event.setCanceled(true);
                }
            }
        }
    }
    if (entity instanceof StormEntity){
        if (!entity.level.isClientSide){
            ServerLevel serverWorld = (ServerLevel) entity.level;
            serverWorld.setWeatherParameters(0, 6000, true, true);
        }
    }
    if (entity instanceof Raider raider){
        if (world instanceof ServerLevel) {
            if (raider.hasActiveRaid()) {
                Raid raid = raider.getCurrentRaid();
                if (raid != null && raid.isActive() && !raid.isBetweenWaves() && !raid.isOver() && !raid.isStopped()) {
                    Player player = EntityFinder.getNearbyPlayer(world, raid.getCenter());
                    if (player != null) {
                        if (MobsConfig.IllagerRaid.get()) {
                            if (SEHelper.getSoulAmountInt(player) < (MobsConfig.IllagerAssaultSEThreshold.get() * 2)) {
                                if (raider instanceof HuntingIllagerEntity){
                                    raid.removeFromRaid(raider, true);
                                    event.setCanceled(true);
                                }
                            }
                        } else {
                            if (raider instanceof HuntingIllagerEntity){
                                raid.removeFromRaid(raider, true);
                                event.setCanceled(true);
                            }
                        }
                    }
                }
            }
        }
    }
}

public void update() {
    ItemStack handHeld = this.entity.getItemInHand(InteractionHand.MAIN_HAND);
    var recipeInput = new SingleRecipeInput(handHeld);
    Level level = this.entity.level();

    if (!handHeld.isEmpty() && this.currentRecipe.isEmpty()
            && this.currentRecipeBlast.isEmpty()
            && this.currentRecipeSmoke.isEmpty()
            && this.currentRecipeCamp.isEmpty()) {

        this.currentRecipe = ((ServerLevel) level).recipeAccess().getRecipeFor(RecipeType.SMELTING,
                recipeInput, level);
        if (this.currentRecipe.isEmpty()) {
            this.currentRecipeBlast = ((ServerLevel) level).recipeAccess().getRecipeFor(RecipeType.BLASTING,
                    recipeInput, level);
            if (this.currentRecipeBlast.isEmpty()) {
                this.currentRecipeSmoke = ((ServerLevel) level).recipeAccess().getRecipeFor(RecipeType.SMOKING,
                        recipeInput, level);
                if (this.currentRecipeSmoke.isEmpty()) {
                    this.currentRecipeCamp = ((ServerLevel) level).recipeAccess().getRecipeFor(RecipeType.CAMPFIRE_COOKING,
                            recipeInput, level);
                }
            }
        }
        this.smeltingTimer = 0;

        if (this.currentRecipe.isPresent() || this.currentRecipeBlast.isPresent() || this.currentRecipeSmoke.isPresent() || this.currentRecipeCamp.isPresent()) {
            //play smelting sound
            level.playSound(null, this.entity.blockPosition(), SoundEvents.FIRE_AMBIENT,
                    SoundSource.NEUTRAL, 1f, 1 + 0.5f * this.entity.getRandom().nextFloat());
        } else {
            //if no recipe is found, drop hand held item as we can't process it
            this.entity.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, handHeld);
            if (droppedItem != null) {
                droppedItem.addTag(DROPPED_BY_SMELTER);
            }
        }
    }
    if (this.currentRecipe.isPresent()) {
        if (handHeld.isEmpty() || !this.currentRecipe.get().value().matches(recipeInput, level)) {
            //Reset cached recipe if it no longer matches
            this.currentRecipe = Optional.empty();
        } else {
            this.commonTick();
            if (this.smeltingTimer >= this.currentRecipe.get().value().cookingTime() * this.smeltingTimeMultiplier.get()) {
                this.smeltingTimer = 0;
                ItemStack result = this.currentRecipe.get().value().assemble(recipeInput);
                this.commonFinish(handHeld, result, level);
                //Don't reset recipe here, keep it cached
            }
        }
    } else if (this.currentRecipeBlast.isPresent()) {
        if (handHeld.isEmpty() || !this.currentRecipeBlast.get().value().matches(recipeInput, level)) {
            //Reset cached recipe if it no longer matches
            this.currentRecipeBlast = Optional.empty();
        } else {
            this.commonTick();
            if (this.smeltingTimer >= this.currentRecipeBlast.get().value().cookingTime() * this.smeltingTimeMultiplier.get()) {
                this.smeltingTimer = 0;
                ItemStack result = this.currentRecipeBlast.get().value().assemble(recipeInput);
                this.commonFinish(handHeld, result, level);
                //Don't reset recipe here, keep it cached
            }
        }
    } else if (this.currentRecipeSmoke.isPresent()) {
        if (handHeld.isEmpty() || !this.currentRecipeSmoke.get().value().matches(recipeInput, level)) {
            //Reset cached recipe if it no longer matches
            this.currentRecipeSmoke = Optional.empty();
        } else {
            this.commonTick();
            if (this.smeltingTimer >= this.currentRecipeSmoke.get().value().cookingTime() * this.smeltingTimeMultiplier.get()) {
                this.smeltingTimer = 0;
                ItemStack result = this.currentRecipeSmoke.get().value().assemble(recipeInput);
                this.commonFinish(handHeld, result, level);
                //Don't reset recipe here, keep it cached
            }
        }
    } else if (this.currentRecipeCamp.isPresent()) {
        if (handHeld.isEmpty() || !this.currentRecipeCamp.get().value().matches(recipeInput, level)) {
            //Reset cached recipe if it no longer matches
            this.currentRecipeCamp = Optional.empty();
        } else {
            this.commonTick();
            if (this.smeltingTimer >= this.currentRecipeCamp.get().value().cookingTime() * this.smeltingTimeMultiplier.get()) {
                this.smeltingTimer = 0;
                ItemStack result = this.currentRecipeCamp.get().value().assemble(recipeInput);
                this.commonFinish(handHeld, result, level);
                //Don't reset recipe here, keep it cached
            }
        }
    }
    super.update();
}

public void update() {
    ItemStack handHeld = this.entity.getItemInHand(InteractionHand.MAIN_HAND);
    var recipeInput = new TraderRecipeInput(handHeld, this.getFactoryID().toString());
    Level level = this.entity.level();
    if (this.currentRecipe.isEmpty() && !handHeld.isEmpty()) {
        this.currentRecipe = ((ServerLevel) level).recipeAccess().getRecipes().stream()
                .filter(r -> r.value() instanceof SpiritTradeRecipe && ((SpiritTradeRecipe) r.value()).matches(recipeInput, level))
                .map(r -> (RecipeHolder<SpiritTradeRecipe>) r)
                .filter(r -> r.value().getTrader() == null || r.value().getTrader().equals(this.getFactoryID().toString()))
                .collect(Collectors.toList());
        this.conversionTimer = 0;

        if (!this.currentRecipe.isEmpty()) {
            //play coin sound
            level.playSound(null, this.entity.blockPosition(), OccultismSounds.COIN.get(),
                    SoundSource.NEUTRAL, 10f, 1 + 0.05f * this.entity.getRandom().nextFloat());
            this.possibleResults = this.currentRecipe.stream().map(r -> r.value().getWeightedResult()).collect(Collectors.toList());
        } else {
            //if no recipe is found, drop hand held item as we can't process it
            this.entity.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, handHeld);
            if (droppedItem != null) {
                droppedItem.addTag(DROPPED_BY_TRADER);
            }
        }
    }
    if (!this.currentRecipe.isEmpty()) {
        if (handHeld.isEmpty() || !this.currentRecipe.get(0).value().matches(recipeInput, level)) {
            //Reset cached recipe if it no longer matches
            this.currentRecipe = List.of();
        } else {
            //advance conversion
            this.conversionTimer++;

            //show particle effect while trading
            if (level.getGameTime() % 10 == 0) {
                Vec3 pos = this.entity.position();
                ((ServerLevel) level)
                        .sendParticles(ParticleTypes.PORTAL, pos.x + level.getRandom().nextGaussian() / 3,
                                pos.y + 0.5, pos.z + level.getRandom().nextGaussian() / 3, 1, 0.0, 0.0, 0.0,
                                0.0);
            }

            //every two seconds, play another coin sound
            if (level.getGameTime() % 40 == 0) {
                level.playSound(null, this.entity.blockPosition(), OccultismSounds.COIN.get(),
                        SoundSource.NEUTRAL, 10f,
                        1 + 0.05f * this.entity.getRandom().nextFloat());
            }

            if (this.conversionTimer >= this.timeToConvert) {
                this.conversionTimer = 0;

                int a = Math.min(this.maxTradesPerRound, handHeld.getCount());
                for (int i = 0; i < a; i++) {
                    var result = WeightedRandom.getRandomItem(this.entity.getRandom(), this.possibleResults, WeightedRecipeResult::weight);
                    //Important: copy the result, don't use it raw!
                    result.ifPresent(r -> {
                        ItemStack finalResult = r.getStack().copy();
                        finalResult.setCount(finalResult.getCount());
                        ItemStack inputCopy = handHeld.copy();
                        handHeld.shrink(1);

                        this.entity.setItemInHand(InteractionHand.MAIN_HAND, handHeld);

                        this.onConvert(inputCopy, finalResult);
                        var event = new TraderJobEvent(this.entity, inputCopy, finalResult);
                        NeoForge.EVENT_BUS.post(event);
                        if (!event.getResult().isEmpty()) {
                            boolean flag = true;
                            if (level.getBlockState(this.entity.blockPosition().below()).is(OccultismBlocks.DIMENSIONAL_EXTRACTOR)) {
                                if (this.cachedStateBelow != level.getBlockState(this.entity.blockPosition().below(2)))
                                    this.updateBelowBlock();
                                if (this.handlerBelow != null) {
                                    ItemTransferUtil.insertItemStacked(this.handlerBelow, event.getResult(), false);
                                    flag = false;
                                }
                            }
                            if (flag) {
                                ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, event.getResult());
                                if (droppedItem != null) {
                                    droppedItem.addTag(DROPPED_BY_TRADER);
                                }
                            }
                        }
                    });
                }

                //Don't reset recipe here, keep it cached
            }
        }
    }
    super.update();
}

public void tick() {
    super.tick();
    this.prevDanceProgress = danceProgress;
    this.prevSitProgress = sitProgress;
    this.prevCarryItemProgress = carryItemProgress;
    if (this.jukeboxPosition == null || !this.jukeboxPosition.closerToCenterThan(this.position(), 15) || !this.level().getBlockState(this.jukeboxPosition).is(Blocks.JUKEBOX)) {
        this.setDancing(false);
        this.jukeboxPosition = null;
    }
    if (isDancing() && danceProgress < 5F) {
        danceProgress++;
    }
    if (!isDancing() && danceProgress > 0F) {
        danceProgress--;
    }
    if (isSitting() && sitProgress < 10F) {
        sitProgress++;
    }
    if (!isSitting() && sitProgress > 0F) {
        sitProgress--;
    }
    if (isCarryingItem() && carryItemProgress < 10F) {
        carryItemProgress++;
    }
    if (!isCarryingItem() && carryItemProgress > 0F) {
        carryItemProgress--;
    }
    if (!level().isClientSide) {
        if (isStillEnough() && !isCarryingItem() && random.nextInt(150) == 0 && this.getAnimation() == NO_ANIMATION && !this.isDancing()) {
            if (random.nextInt(3) == 0 && sitFor == 0) {
                sitFor = 100 + random.nextInt(80);
            } else {
                Animation idle;
                float rand = random.nextFloat();
                if (!this.isSitting()) {
                    if (rand < 0.25F) {
                        idle = ANIMATION_IDLE_JUMP;
                    } else if (rand < 0.5F) {
                        idle = ANIMATION_IDLE_FALL_OVER;
                    } else {
                        idle = rand < 0.75F ? ANIMATION_IDLE_WAVE_LEFT : ANIMATION_IDLE_WAVE_RIGHT;
                    }
                } else {
                    idle = rand < 0.5F ? ANIMATION_IDLE_WAVE_LEFT : ANIMATION_IDLE_WAVE_RIGHT;
                }
                this.setAnimation(idle);
            }
        }
        if(this.isCarryingItem() && this.getItemInHand(InteractionHand.OFF_HAND).isEmpty()){
            this.setCarryingItem(false);
        }
    }else{
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
        } else {
            this.reapplyPosition();
        }
    }
    if (this.getAnimation() == ANIMATION_IDLE_JUMP && this.onGround() && this.getAnimationTick() == 5) {
        this.jumpFromGround();
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
    if (sitFor > 0) {
        this.setSitting(true);
        sitFor--;
    } else {
        this.setSitting(false);
        if (sitFor < 0) {
            sitFor++;
        }
    }
    if(fleeFor > 0){
        fleeFor--;
        if(fleeFor == 0){
            this.setFleeingFromUUID(null);
        }
    }
    if(this.isOvenSpawned()){
        if(despawnFromOvenCooldown-- < 0){
            this.kill();
            this.spawnAtLocation(this.getItemInHand(InteractionHand.MAIN_HAND));
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            this.spawnAtLocation(this.getItemInHand(InteractionHand.OFF_HAND));
            this.setItemInHand(InteractionHand.OFF_HAND, ItemStack.EMPTY);
        }
    }
    lastStepX = this.xo;
    lastStepZ = this.zo;
}

public void tick() {
    super.tick();
    this.prevChargeProgress = this.chargeProgress;
    if (this.isCharging() && chargeProgress < 5F) {
        chargeProgress++;
    }
    if (!this.isCharging() && chargeProgress > 0F) {
        chargeProgress--;
    }
    if (!this.level().isClientSide) {
        if (snowTimer == 0) {
            snowTimer = 200 + random.nextInt(400);
            if (this.isSnowy()) {
                if (!permSnow) {
                    if (this.getRemainingFireTicks() > 0 || this.isInWaterOrBubble() || !EntityGrizzlyBear.isSnowingAt(level(), this.blockPosition().above())) {
                        this.setSnowy(false);
                    }
                }
            } else {
                if (EntityGrizzlyBear.isSnowingAt(level(), this.blockPosition())) {
                    this.setSnowy(true);
                }
            }
        }

        LivingEntity attackTarget = this.getTarget();
        if (this.getDeltaMovement().lengthSqr() < 0.05D && this.getAnimation() == NO_ANIMATION && (attackTarget == null || !attackTarget.isAlive())) {
            if ((getRandom().nextInt(600) == 0 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK))) {
                this.setAnimation(ANIMATION_EAT);
            }
        }
        if(this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() == 30 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK)){
            this.feedingsSinceLastShear++;
            BlockPos down = this.blockPosition().below();
            this.level().levelEvent(2001, down, Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
            this.level().setBlock(down, Blocks.DIRT.defaultBlockState(), 2);
        }

        if (isCharging()) {
            if (!hasChargedSpeed) {
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.65F);
                hasChargedSpeed = true;
            }
        } else {
            if (hasChargedSpeed) {
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
                hasChargedSpeed = false;
            }
        }

        if (attackTarget != null && attackTarget.isAlive() && this.isAlive()) {
            final double dist = this.distanceTo(attackTarget);
            if (hasLineOfSight(attackTarget)) {
                this.lookAt(attackTarget, 30, 30);
                this.yBodyRot = this.getYRot();
            }
            if (dist < this.getBbWidth() + 3.0F) {
                if (this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() > 8 && dist < this.getBbWidth() + 1.0F && this.hasLineOfSight(attackTarget)) {
                    float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                    if (attackTarget instanceof Wolf) {
                        dmg = 2;
                    }
                    launch(attackTarget, isCharging());
                    if (isCharging()) {
                        dmg += 3;
                        this.setCharging(false);
                    }
                    attackTarget.hurt(this.damageSources().mobAttack(this), dmg);
                }
            } else if (!this.isCharging()) {
                final Animation animation = this.getAnimation();
                if(animation == NO_ANIMATION){
                    this.setAnimation(ANIMATION_PREPARE_CHARGE);
                }
                else if (animation == ANIMATION_PREPARE_CHARGE) {
                    this.getNavigation().stop();
                    if (this.getAnimationTick() > 30) {
                        this.setCharging(true);
                    }
                }
            }
        }
    }
    if (chargeCooldown > 0) {
        chargeCooldown--;
    }
    if(feedingsSinceLastShear >= 5 && this.isSheared()){
        feedingsSinceLastShear = 0;
        this.setSheared(false);
    }
    if (!this.level().isClientSide && this.isCharging() && (this.getTarget() == null && this.chargePartner == null || this.isInWaterOrBubble())) {
        this.setCharging(false);
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public static void AttackEvent(LivingAttackEvent event){
    LivingEntity victim = event.getEntity();
    Entity source = event.getSource().getEntity();
    Entity direct = event.getSource().getDirectEntity();
    if (!event.getEntity().level.isClientSide) {
        if (MiscCapHelper.getShields(victim) > 0
                && !event.getSource().is(DamageTypeTags.BYPASSES_EFFECTS)
                && !event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY)){
            if (MiscCapHelper.getShieldCool(victim) <= 0) {
                MiscCapHelper.decreaseShields(victim);
                if (SpellConfig.BulwarkShieldBreakExtra.get() > 0.0D) {
                    int extra = Mth.floor(event.getAmount() / SpellConfig.BulwarkShieldBreakExtra.get());
                    if (extra >= 1) {
                        for (int i = 0; i < extra; ++i) {
                            MiscCapHelper.decreaseShields(victim);
                        }
                    }
                }
                MiscCapHelper.setShieldCool(victim, 10);
                if (event.getSource().getEntity() instanceof LivingEntity livingEntity){
                    MobUtil.knockBack(livingEntity, victim, 1.0D, 0.2D, 1.0D);
                }
            }
            event.setCanceled(true);
        }
        if (MainConfig.GoodwillNoDamage.get()) {
            Player player = null;
            if (source instanceof Player player1) {
                player = player1;
            } else if (MobUtil.getOwner(source) instanceof Player player1) {
                player = player1;
            }
            if (player != null) {
                if (SEHelper.isAlly(player, victim)) {
                    event.setCanceled(true);
                }
            } else if (source instanceof IOwned owned) {
                if (owned.isAllyWith(victim)) {
                    event.setCanceled(true);
                }
            }
        }
        if (victim instanceof Witch witch) {
            double d0 = witch.getAttributeValue(Attributes.FOLLOW_RANGE);
            AABB axisalignedbb = AABB.unitCubeFromLowerCorner(witch.position()).inflate(d0, 10.0D, d0);
            List<Mob> list = witch.level.getEntitiesOfClass(Mob.class, axisalignedbb);

            for (Mob mob : list){
                if (mob.getTarget() == null && witch.getLastHurtByMob() != null && !(witch.getLastHurtByMob() instanceof Raider) && !MobUtil.areAllies(witch.getLastHurtByMob(), witch)) {
                    if (mob instanceof Cultist && !mob.getType().is(Tags.EntityTypes.BOSSES) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(witch.getLastHurtByMob())) {
                        mob.setTarget(witch.getLastHurtByMob());
                    }
                }
            }
        }
    }

    if (event.getSource() instanceof NoKnockBackDamageSource){
        if (!victim.level.isClientSide) {
            CompoundTag tag = victim.getPersistentData();
            tag.putInt(NO_KNOCKBACK_TAG, victim.tickCount);
        }
    }

    if (source instanceof IOwned owned){
        if (owned.getMasterOwner() instanceof Player player) {
            victim.lastHurtByPlayer = player;
            victim.lastHurtByPlayerTime = 100;
        }
    }

    if (direct instanceof AbstractArrow arrowEntity){
        if (arrowEntity.getTags().contains(ConstantPaths.rainArrow()) || arrowEntity.getOwner() instanceof Apostle){
            if (arrowEntity.getOwner() != null) {
                if (victim instanceof IOwned ownedEntity) {
                    if (ownedEntity.getTrueOwner() != null) {
                        if (ownedEntity.getTrueOwner() == arrowEntity.getOwner()) {
                            event.setCanceled(true);
                        }
                    }
                }
                if (victim == arrowEntity.getOwner()){
                    event.setCanceled(true);
                }
            }
        }
        if (!(arrowEntity.getOwner() instanceof Apostle && victim.level.getDifficulty() == Difficulty.HARD)) {
            if (victim instanceof Player player) {
                if (MobUtil.starAmuletActive(player)) {
                    event.setCanceled(true);
                }
            }
        }
    }
}

public boolean attemptSpawnTome(int slot, ServerLevel level, BlockPos pos, boolean fire, @Nullable LivingEntity assailant, int maxTries) {
	RandomSource random = level.getRandom();
	SpawnData data = this.getOrCreateNextSpawnData(level, random, pos);
	CompoundTag tag = data.entityToSpawn();
	BlockState shelf = level.getBlockState(pos);
	Direction facing = shelf.getValue(HorizontalDirectionalBlock.FACING);
	try (ProblemReporter.ScopedCollector reporter = new ProblemReporter.ScopedCollector(this::toString, TwilightForestMod.LOGGER)) {
		ValueInput input = TagValueInput.create(reporter, level.registryAccess(), data.getEntityToSpawn());
		Optional<EntityType<?>> entityType = EntityType.by(input);
		//if the assigned entity doesn't exist or the bookshelf is blocked off, fail early
		if (entityType.isEmpty() || !level.getBlockState(pos.relative(facing)).canBeReplaced()) {
			this.delay(level, pos);
			return false;
		}

		//pick random spot in front of the shelf
		double x = pos.relative(facing).getX() + (random.nextDouble() - random.nextDouble()) * 2.0D;
		double y = (double) pos.getY() + (random.nextDouble() - random.nextDouble());
		double z = pos.relative(facing).getZ() + (random.nextDouble() - random.nextDouble()) * 2.0D;

		//apply spawning logic like vanilla spawners do
		if (level.noCollision(entityType.get().getSpawnAABB(x, y, z))) {
			boolean difficultyPreventsSpawn = !entityType.get().getCategory().isFriendly() && level.getDifficulty() == Difficulty.PEACEFUL;

			BlockPos blockpos = BlockPos.containing(x, y, z);
			if (data.getCustomSpawnRules().isPresent()) {
				if (difficultyPreventsSpawn) {
					return false;
				}

				SpawnData.CustomSpawnRules rules = data.getCustomSpawnRules().get();
				if (!rules.isValidPosition(blockpos, level) && !fire) {
					return false;
				}
			} else if (difficultyPreventsSpawn) {
				this.delay(level, pos);
				return false;
			}

			Entity entity = EntityType.loadEntityRecursive(tag, level, EntitySpawnReason.SPAWNER, processed -> {
				processed.snapTo(x, y, z, processed.getYRot(), processed.getXRot());
				//set entity on fire if told to do so
				if (fire) {
					processed.setRemainingFireTicks(200);
				}

				//target whoever was responsible for spawning the mob
				if (assailant != null && processed instanceof Mob mob) {
					mob.setTarget(assailant);
				}

				return processed;
			});
			if (entity == null) {
				this.delay(level, pos);
				return false;
			}

			int k = level.getEntities(EntityTypeTest.forExactClass(entity.getClass()), new AABB(pos).inflate(this.spawnCheckRange), EntitySelector.NO_SPECTATORS).size();
			if (k >= this.maxNearbyEntities && !fire) {
				this.delay(level, pos);
				return false;
			}

			entity.snapTo(entity.getX(), entity.getY(), entity.getZ(), random.nextFloat() * 360.0F, 0.0F);
			if (entity instanceof Mob mob) {
				boolean hasNoConfiguration = data.getEntityToSpawn().size() == 1 && data.getEntityToSpawn().getString("id").isPresent();
				EventHooks.finalizeMobSpawnSpawner(mob, level, level.getCurrentDifficultyAt(entity.blockPosition()), EntitySpawnReason.SPAWNER, null, this, hasNoConfiguration);

				data.getEquipment().ifPresent(mob::equip);
			}

			if (!level.tryAddFreshEntityWithPassengers(entity)) {
				this.delay(level, pos);
				return false;
			}

			level.gameEvent(entity, GameEvent.ENTITY_PLACE, blockpos);
			if (entity instanceof Mob mob) {
				mob.spawnAnim();
			}

			//after mob is spawned, clear that book's spot from the shelf
			if (level.getBlockEntity(pos) instanceof ChiseledCanopyShelfBlockEntity be) {
				be.removeTomeFromSlot(slot);
			}
			return true;
		} else {
			if (maxTries != 0) {
				return this.attemptSpawnTome(slot, level, pos, fire, assailant, maxTries - 1);
			}
		}
	}
	return false;
}

public void tick() {
    super.tick();
    this.prevPerchProgress = perchProgress;
    this.prevMouthProgress = mouthProgress;
    this.prevFlyProgress = flyProgress;

    if (this.isFlying()) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (this.isPerching()) {
        if (perchProgress < 5F)
            perchProgress++;
    } else {
        if (perchProgress > 0F)
            perchProgress--;
    }

    if (this.ringBufferIndex < 0) {
        //initial population of buffer
        Arrays.fill(this.ringBuffer, 15);
    }
    this.ringBufferIndex++;
    if (this.ringBufferIndex == this.ringBuffer.length) {
        this.ringBufferIndex = 0;
    }
    this.ringBuffer[this.ringBufferIndex] = this.entityData.get(TEMP_BRIGHTNESS);
    if (perchCooldown > 0) {
        perchCooldown--;
    }
    if (!this.level().isClientSide) {
        this.entityData.set(TEMP_BRIGHTNESS, level().getMaxLocalRawBrightness(this.blockPosition()));
        if (isFlying()) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        if (this.isFlying()) {
            if (!this.onGround()) {
                if (!this.isInWaterOrBubble()) {
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1F, 0.6F, 1F));
                }
            } else if (timeFlying > 20) {
                this.setFlying(false);
            }
            this.timeFlying++;
        } else {
            this.timeFlying = 0;
        }
        if (this.isPerching() && !this.isVehicle()) {
            this.setSleeping(this.level().isDay() && (this.getTarget() == null || !this.getTarget().isAlive()));
        } else if (isSleeping()) {
            this.setSleeping(false);
        }
        if(isPerching() && this.getPerchPos() != null) {
            if ((!level().getBlockState(this.getPerchPos()).is(AMTagRegistry.POTOO_PERCHES) || this.distanceToSqr(Vec3.atCenterOf(this.getPerchPos())) > 2.25F)) {
                this.setPerching(false);
            } else {
                slideTowardsPerch();
            }
        }
    }
    if (this.entityData.get(MOUTH_TICK) > 0) {
        this.entityData.set(MOUTH_TICK, this.entityData.get(MOUTH_TICK) - 1);
        if (mouthProgress < 5F) {
            mouthProgress++;
        }
    } else {
        if (mouthProgress > 0F) {
            mouthProgress--;
        }
    }
    if (!isSleeping() && (this.getTarget() == null || !this.getTarget().isAlive())) {
        int j = tickCount - lastScreamTimestamp;
        if (getEyeScale(10, 1.0F) == 0F) {
            if (j > 40) {
                this.openMouth(30);
                this.playSound(AMSoundRegistry.POTOO_CALL.get());
                this.gameEvent(GameEvent.ENTITY_ROAR);
            }
        } else if (getEyeScale(10, 1.0F) < 7) {
            if (j > 300 && j % 300 == 0 && random.nextInt(4) == 0) {
                this.openMouth(30);
                this.playSound(AMSoundRegistry.POTOO_CALL.get());
                this.gameEvent(GameEvent.ENTITY_ROAR);
            }
        }
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    float damage = SpellConfig.FireballDamage.get().floatValue() * WandUtil.damageMultiply();
    int potency = spellStat.getPotency();
    int burning = spellStat.getBurning();
    if (WandUtil.enchantedFocus(caster)){
        potency += WandUtil.getPotencyLevel(caster);
        burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
    }
    Vec3 vector3d = caster.getViewVector(1.0F);
    double x = caster.getX() + vector3d.x / 2;
    double y = caster.getEyeY() - 0.2D;
    double z = caster.getZ() + vector3d.z / 2;
    Vec3 origin = new Vec3(x, y, z);
    if (ItemHelper.hasMaleficHelm(caster) && this.rightStaff(staff)) {
        origin = MobUtil.vecFromCenterToFrontOfFace(caster, 0.5D, 0.0F);
        vector3d = MobUtil.vecCenterFaceVector(caster, 2.0D, 0.0F);
    }
    AbstractHurtingProjectile smallFireballEntity = new ModFireball(worldIn,
            origin.x,
            origin.y,
            origin.z,
            vector3d.x,
            vector3d.y,
            vector3d.z);
    if (CuriosFinder.hasUnholySet(caster)){
        smallFireballEntity = new HellBolt(
                origin.x,
                origin.y,
                origin.z,
                vector3d.x,
                vector3d.y,
                vector3d.z, worldIn);
    }
    smallFireballEntity.setOwner(caster);
    if (smallFireballEntity instanceof ModFireball fireball) {
        if (isShifting(caster)) {
            fireball.setDangerous(false);
        }
        fireball.setExtraDamage(potency);
        fireball.setFiery(burning);
    } else if (smallFireballEntity instanceof HellBolt hellBolt){
        hellBolt.setDamage(damage + potency);
        hellBolt.setFiery(burning);
    }
    worldIn.addFreshEntity(smallFireballEntity);
    if (rightStaff(staff)) {
        for (int i = 0; i < 2; ++i) {
            double x1 = caster.getX() + vector3d.x / 2 + worldIn.getRandom().nextGaussian();
            double y1 = caster.getEyeY() - 0.2D;
            double z1 = caster.getZ() + vector3d.z / 2 + worldIn.getRandom().nextGaussian();
            Vec3 origin2 = new Vec3(x1, y1, z1);
            if (ItemHelper.hasMaleficHelm(caster)) {
                if (i == 0) {
                    origin2 = MobUtil.vecFromCenterToFrontOfFace(caster, 0.5D, -10.0F);
                    vector3d = MobUtil.vecCenterFaceVector(caster, 2.0D, -10.0F);
                } else {
                    origin2 = MobUtil.vecFromCenterToFrontOfFace(caster, 0.5D, 10.0F);
                    vector3d = MobUtil.vecCenterFaceVector(caster, 2.0D, 10.0F);
                }
            }
            AbstractHurtingProjectile smallFireballEntity2 = new ModFireball(worldIn,
                    origin2.x,
                    origin2.y,
                    origin2.z,
                    vector3d.x,
                    vector3d.y,
                    vector3d.z);
            if (CuriosFinder.hasUnholySet(caster)){
                smallFireballEntity2 = new HellBolt(
                        origin2.x,
                        origin2.y,
                        origin2.z,
                        vector3d.x,
                        vector3d.y,
                        vector3d.z, worldIn);
            }
            smallFireballEntity2.setOwner(caster);
            if (smallFireballEntity2 instanceof ModFireball fireball) {
                if (isShifting(caster)) {
                    fireball.setDangerous(false);
                }
                fireball.setExtraDamage(potency);
                fireball.setFiery(burning);
            } else if (smallFireballEntity2 instanceof HellBolt hellBolt){
                hellBolt.setDamage(damage + potency);
                hellBolt.setFiery(burning);
            }
            worldIn.addFreshEntity(smallFireballEntity2);
        }
    }
    SoundEvent soundEvent = SoundEvents.BLAZE_SHOOT;
    if (CuriosFinder.hasUnholySet(caster)){
        soundEvent = ModSounds.HELL_BOLT_SHOOT.get();
    }
    this.playSound(worldIn, caster, soundEvent, 2.0F, this.projPitch(worldIn.getRandom()));
}

private void respawn(ServerPlayer player, boolean keep, CallbackInfoReturnable<ServerPlayer> info) {
	BlockPos pos = player.getRespawnPosition();
	float angle = player.getRespawnAngle();
	boolean forced = player.isRespawnForced();
	boolean override = false;
	boolean endRespawn = false;
	ServerLevel level = this.server.getLevel(player.getRespawnDimension());
	Optional<Vec3> optional = Optional.empty();

	if (level != null && pos != null) {
		AnchorSearchResult result = EndAnchor.findEndAnchor(level, pos, angle, forced, keep);

		if (result.found()) {
			optional = result.location();
			override = true;

			if (keep && level.dimension() == Level.END && optional.isPresent()) {
				endRespawn = true;
				optional = Optional.empty();
			}
		}
	}

	if (!override)
		return;

	this.players.remove(player);
	player.serverLevel().removePlayerImmediately(player, Entity.RemovalReason.DISCARDED);
	PlayerList list = (PlayerList) (Object) this;

	ServerLevel newLevel = level != null && optional.isPresent() ? level : this.server.overworld();
	ServerPlayer newPlayer = new ServerPlayer(this.server, newLevel, player.getGameProfile());
	newPlayer.connection = player.connection;
	newPlayer.restoreFrom(player, keep);
	newPlayer.setId(player.getId());
	newPlayer.setMainArm(player.getMainArm());

	for (String tag : player.getTags()) {
		newPlayer.addTag(tag);
	}

	boolean usedAnchorCharge = false;
	if (optional.isPresent()) {
		BlockState respawnState = newLevel.getBlockState(pos);
		boolean isAnchor = respawnState.is(Blocks.RESPAWN_ANCHOR) || respawnState.is(EnigmaticBlocks.END_ANCHOR);
		Vec3 vec3 = optional.get();
		float f1;
		if (!respawnState.is(BlockTags.BEDS) && !isAnchor) {
			f1 = angle;
		} else {
			Vec3 vec31 = Vec3.atBottomCenterOf(pos).subtract(vec3).normalize();
			f1 = (float) Mth.wrapDegrees(Mth.atan2(vec31.z, vec31.x) * (180F / (float) Math.PI) - 90.0D);
		}

		newPlayer.moveTo(vec3.x, vec3.y, vec3.z, f1, 0.0F);
		newPlayer.setRespawnPosition(newLevel.dimension(), pos, angle, forced, false);
		usedAnchorCharge = !keep && isAnchor && EndAnchor.useEndAnchor(newLevel, pos, respawnState);
	} else if (pos != null && !endRespawn) {
		newPlayer.connection.send(new ClientboundGameEventPacket(
				ClientboundGameEventPacket.NO_RESPAWN_BLOCK_AVAILABLE, 0.0F));
	} else if (pos != null && endRespawn) {
		newPlayer.setRespawnPosition(Level.END, pos, angle, forced, false);
	}

	while (!newLevel.noCollision(newPlayer) && newPlayer.getY() < newLevel.getMaxBuildHeight()) {
		newPlayer.setPos(newPlayer.getX(), newPlayer.getY() + 1.0D, newPlayer.getZ());
	}

	byte keepByte = (byte) (keep ? 1 : 0);
	LevelData leveldata = newPlayer.level().getLevelData();
	newPlayer.connection.send(new ClientboundRespawnPacket(newPlayer.level().dimensionTypeId(),
			newPlayer.level().dimension(), BiomeManager.obfuscateSeed(newPlayer.serverLevel().getSeed()),
			newPlayer.gameMode.getGameModeForPlayer(), newPlayer.gameMode.getPreviousGameModeForPlayer(),
			newPlayer.level().isDebug(), newPlayer.serverLevel().isFlat(), keepByte, newPlayer.getLastDeathLocation(),
			newPlayer.getPortalCooldown()));
	newPlayer.connection.teleport(newPlayer.getX(), newPlayer.getY(), newPlayer.getZ(), newPlayer.getYRot(),
			newPlayer.getXRot());
	newPlayer.connection.send(new ClientboundSetDefaultSpawnPositionPacket(newLevel.getSharedSpawnPos(),
			newLevel.getSharedSpawnAngle()));
	newPlayer.connection.send(new ClientboundChangeDifficultyPacket(leveldata.getDifficulty(),
			leveldata.isDifficultyLocked()));
	newPlayer.connection.send(new ClientboundSetExperiencePacket(newPlayer.experienceProgress,
			newPlayer.totalExperience, newPlayer.experienceLevel));
	list.sendLevelInfo(newPlayer, newLevel);
	list.sendPlayerPermissionLevel(newPlayer);
	newLevel.addRespawnedPlayer(newPlayer);
	this.players.add(newPlayer);
	this.playersByUUID.put(newPlayer.getUUID(), newPlayer);
	newPlayer.initInventoryMenu();
	newPlayer.setHealth(newPlayer.getHealth());
	net.minecraftforge.event.ForgeEventFactory.firePlayerRespawnEvent(newPlayer, keep);

	if (usedAnchorCharge && pos != null) {
		newPlayer.connection.send(new ClientboundSoundPacket(SoundEvents.RESPAWN_ANCHOR_DEPLETE, SoundSource.BLOCKS, pos.getX(), pos.getY(), pos.getZ(), 1.0F, 1.0F, newLevel.getRandom().nextLong()));
	}

	info.setReturnValue(newPlayer);
}

public void tick() {
    super.tick();
    if (this.tickCount == 1) {
        if(this.getLifespan() == 0){
            this.setLifespan(2000);
        }
    }
    if(!madeOpenNoise){
        this.gameEvent(GameEvent.ENTITY_PLACE);
        this.playSound(AMSoundRegistry.VOID_PORTAL_OPEN.get(), 1.0F, 1 + random.nextFloat() * 0.2F);
        madeOpenNoise = true;
    }
    Direction direction2 = this.getAttachmentFacing().getOpposite();
    float minX = -0.15F;
    float minY = -0.15F;
    float minZ = -0.15F;
    float maxX = 0.15F;
    float maxY = 0.15F;
    float maxZ = 0.15F;
    switch (direction2) {
        case NORTH, SOUTH -> {
            minX = -1.5F;
            maxX = 1.5F;
            minY = -1.5F;
            maxY = 1.5F;
        }
        case EAST, WEST -> {
            minZ = -1.5F;
            maxZ = 1.5F;
            minY = -1.5F;
            maxY = 1.5F;
        }
        case UP, DOWN -> {
            minX = -1.5F;
            maxX = 1.5F;
            minZ = -1.5F;
            maxZ = 1.5F;
        }
    }
    AABB bb = new AABB(this.getX() + minX, this.getY() + minY, this.getZ() + minZ, this.getX() + maxX, this.getY() + maxY, this.getZ() + maxZ);
    this.setBoundingBox(bb);
    if(this.level().isClientSide && random.nextFloat() < 0.5F && Math.min(tickCount, this.getLifespan()) >= 20){
        final double particleX = this.getBoundingBox().minX + random.nextFloat() * (this.getBoundingBox().maxX - this.getBoundingBox().minX);
        final double particleY = this.getBoundingBox().minY + random.nextFloat() * (this.getBoundingBox().maxY - this.getBoundingBox().minY);
        final double particleZ = this.getBoundingBox().minZ + random.nextFloat() * (this.getBoundingBox().maxZ - this.getBoundingBox().minZ);
        level().addParticle(AMParticleRegistry.WORM_PORTAL.get(), particleX, particleY, particleZ, 0.1 * random.nextGaussian(), 0.1 * random.nextGaussian(), 0.1 * random.nextGaussian());
    }
    List<Entity> entities = new ArrayList<>();
    entities.addAll(this.level().getEntities(this, bb.deflate(0.2F)));
    entities.addAll(this.level().getEntitiesOfClass(EntityVoidWorm.class, bb.inflate(1.5F)));
    if (!this.level().isClientSide) {
        MinecraftServer server = level().getServer();
        if (this.getDestination() != null && this.getLifespan() > 20 && tickCount > 20) {
            BlockPos offsetPos = this.getDestination().relative(this.getAttachmentFacing().getOpposite(), 2);
            for (Entity e : entities) {
                if(e.isOnPortalCooldown() || e.isShiftKeyDown() || e instanceof EntityVoidPortal || e.getParts() != null || e instanceof PartEntity<?> || e.getType().is(AMTagRegistry.VOID_PORTAL_IGNORES)){
                    continue;
                }
                if (e instanceof EntityVoidWormPart) {
                    if (this.getLifespan() < 22) {
                        this.setLifespan(this.getLifespan() + 1);
                    }
                } else if (e instanceof EntityVoidWorm) {
                    ((EntityVoidWorm) e).teleportTo(Vec3.atCenterOf(this.getDestination()));
                    e.setPortalCooldown();
                    ((EntityVoidWorm) e).resetPortalLogic();
                } else {
                    boolean flag = true;
                    if(exitDimension != null){
                        ServerLevel dimWorld = server.getLevel(exitDimension);
                        if (dimWorld != null && this.level().dimension() != exitDimension) {
                            teleportEntityFromDimension(e, dimWorld, offsetPos, true);
                            flag = false;
                        }
                    }
                    if(flag){
                        e.teleportToWithTicket(offsetPos.getX() + 0.5f, offsetPos.getY() + 0.5f, offsetPos.getZ() + 0.5f);
                        e.setPortalCooldown();
                    }
                }
            }
        }
    }
    this.setLifespan(this.getLifespan() - 1);
    if(this.getLifespan() <= 20){
        if(!madeCloseNoise){
            this.gameEvent(GameEvent.ENTITY_PLACE);
            this.playSound(AMSoundRegistry.VOID_PORTAL_CLOSE.get(), 1.0F, 1 + random.nextFloat() * 0.2F);
            madeCloseNoise = true;
        }
    }
    if (this.getLifespan() <= 0) {
        this.remove(RemovalReason.DISCARDED);
    }
    if(tickCount > 1){
        clearObstructions();
    }
}

public void tick() {
    super.tick();
    if (this.ringBufferIndex < 0) {
        for (int i = 0; i < this.ringBuffer.length; ++i) {
            this.ringBuffer[i] = this.getYRot();
        }
    }
    this.ringBufferIndex++;
    if (this.ringBufferIndex == this.ringBuffer.length) {
        this.ringBufferIndex = 0;
    }
    this.ringBuffer[this.ringBufferIndex] = this.getYRot();
    if(!this.level().isClientSide){
        final int segments = 15;
        final Entity child = getChild();
        if (child == null) {
            LivingEntity partParent = this;
            parts = new PalaeophisPartEntity[segments];
            PalaeophisPartIndex partIndex = PalaeophisPartIndex.HEAD;
            Vec3 prevPos = this.position();
            for (int i = 0; i < segments; i++) {
                final float prevReqRot = calcPartRotation(i) + getYawForPart(i);
                final float reqRot = calcPartRotation(i + 1) + getYawForPart(i);
                PalaeophisPartEntity part = new PalaeophisPartEntity(UPEntities.PALAEOPHIS_PART.get(), this);
                part.setParent(partParent);
                part.copyDataFrom(this);
                part.setBodyIndex(i);
                part.setPartType(PalaeophisPartIndex.sizeAt(1 + i));
                if (partParent == this) {
                    this.setChildId(part.getUUID());
                    this.entityData.set(CHILD_ID, part.getId());
                }
                if (partParent instanceof PalaeophisPartEntity) {
                    ((PalaeophisPartEntity) partParent).setChildId(part.getUUID());
                }
                part.setPos(part.tickMultipartPosition(this.getId(), partIndex, prevPos, this.getXRot(), prevReqRot, reqRot, true));
                partParent = part;
                level().addFreshEntity(part);
                parts[i] = part;
                partIndex = part.getPartType();
                prevPos = part.position();
            }
        }
        if (shouldReplaceParts() && this.getChild() instanceof PalaeophisPartEntity) {
            parts = new PalaeophisPartEntity[segments];
            parts[0] = (PalaeophisPartEntity) this.getChild();
            this.entityData.set(CHILD_ID, parts[0].getId());
            int i = 1;
            while (i < parts.length && parts[i - 1].getChild() instanceof PalaeophisPartEntity) {
                parts[i] = (PalaeophisPartEntity) parts[i - 1].getChild();
                i++;
            }
        }
        PalaeophisPartIndex partIndex = PalaeophisPartIndex.HEAD;
        Vec3 prev = this.position();
        float xRot = this.getXRot();
        for (int i = 0; i < segments; i++) {
            if (this.parts[i] != null) {
                final float prevReqRot = calcPartRotation(i) + getYawForPart(i);
                final float reqRot = calcPartRotation(i + 1) + getYawForPart(i);
                parts[i].setStrangleProgress(this.strangleProgress);
                parts[i].copyDataFrom(this);
                prev = parts[i].tickMultipartPosition(this.getId(), partIndex, prev, xRot, prevReqRot, reqRot, true);
                partIndex = parts[i].getPartType();
                xRot = parts[i].getXRot();
            }
        }

        if (isInWater()) swimTimer = Math.max(swimTimer + 1, 0);
        else swimTimer = Math.min(swimTimer - 1, 0);
    }
    if (sheddingCooldown >= 0) {
        sheddingCooldown--;
    }

    if (this.getSheddingTime() >= 0) {
        int shedTime = getSheddingTime();
        setSheddingTime(shedTime - 1);

        if (shedTime == 0) {
            // The snake was in "shed mode," and the shedding time has expired.
            // Reset sheddingCooldown for the next shedding event.
            sheddingCooldown = this.getRandom().nextInt(6000) + 1500;
        }
        return;
    }

    if (!this.level().isClientSide && this.isAlive() && this.getSheddingTime() < 0 && sheddingCooldown < 0) {
        // The snake is not in "shed mode," so let's start shedding.
        this.spawnAtLocation(UPItems.PALAEO_SKIN.get(), 1);

        // Set the shedding time for the snake (how long it will be in "shed mode").
        this.setSheddingTime(this.getRandom().nextInt(1000) + 1500);

    }


}

public void aiStep() {
    super.aiStep();
    if (!level.isClientSide) {
        if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
            this.setTarget(null);
        }
    }
    boolean breathing = isBreathing() && this.getAnimation() != ANIMATION_BITE && this.getAnimation() != ANIMATION_ROAR;
    boolean jumping = !this.isInWater() && !this.isOnGround() && this.getDeltaMovement().y >= 0;
    boolean wantJumping = false; //(ticksSinceJump > TIME_BETWEEN_JUMPS) && this.isInWater();
    boolean ground = !isInWater() && this.onGround;
    boolean prevJumping = this.isJumpingOutOfWater();
    this.ticksSinceRoar++;
    this.jumpCooldown++;
    this.prevJumpRot = jumpRot;
    if (this.ticksSinceRoar > TIME_BETWEEN_ROARS && isAtSurface() && this.getAnimation() != ANIMATION_BITE && jumpProgress == 0 && !isJumpingOutOfWater()) {
        this.setAnimation(ANIMATION_ROAR);
        this.ticksSinceRoar = 0;
    }
    if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 1) {
        this.playSound(IafSoundRegistry.SEA_SERPENT_ROAR, this.getSoundVolume() + 1, 1);
    }
    if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 5) {
        this.playSound(IafSoundRegistry.SEA_SERPENT_BITE, this.getSoundVolume(), 1);
    }
    if (isJumpingOutOfWater() && isWaterBlock(level, this.blockPosition().above(2))) {
        setJumpingOutOfWater(false);
    }
    if (this.swimCycle < 38) {
        this.swimCycle += 2;
    } else {
        this.swimCycle = 0;
    }
    if (breathing && breathProgress < 20.0F) {
        breathProgress += 0.5F;
    } else if (!breathing && breathProgress > 0.0F) {
        breathProgress -= 0.5F;
    }
    if (jumping && jumpProgress < 10.0F) {
        jumpProgress += 0.5F;
    } else if (!jumping && jumpProgress > 0.0F) {
        jumpProgress -= 0.5F;
    }
    if (wantJumping && wantJumpProgress < 10.0F) {
        wantJumpProgress += 2F;
    } else if (!wantJumping && wantJumpProgress > 0.0F) {
        wantJumpProgress -= 2F;
    }
    if (this.isJumpingOutOfWater() && jumpRot < 1.0F) {
        jumpRot += 0.1F;
    } else if (!this.isJumpingOutOfWater() && jumpRot > 0.0F) {
        jumpRot -= 0.1F;
    }
    if (prevJumping && !this.isJumpingOutOfWater()) {
        this.playSound(IafSoundRegistry.SEA_SERPENT_SPLASH, 5F, 0.75F);
        spawnSlamParticles(ParticleTypes.BUBBLE);
        this.doSplashDamage();
    }
    if (!ground && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (ground && !this.isLandNavigator) {
        switchNavigator(true);
    }
    setXRot(Mth.clamp((float) this.getDeltaMovement().y * 20F, -90, 90));
    if (changedSwimBehavior) {
        changedSwimBehavior = false;
    }
    if (!level.isClientSide) {
        if (attackDecision) {
            this.setBreathing(false);
        }
        if (this.getTarget() != null && this.getAnimation() != ANIMATION_ROAR) {
            if (!attackDecision) {
                if (!this.getTarget().isInWater() || !this.hasLineOfSight(this.getTarget()) || this.distanceTo(this.getTarget()) < 30 * this.getSeaSerpentScale()) {
                    attackDecision = true;
                }
                if (!attackDecision) {
                    shoot(this.getTarget());
                }
            } else {
                if (this.distanceToSqr(this.getTarget()) > 200 * this.getSeaSerpentScale()) {
                    attackDecision = false;
                }
            }
        } else {
            this.setBreathing(false);
        }
    }
    if (this.getAnimation() == ANIMATION_BITE && this.getTarget() != null && (this.isTouchingMob(this.getTarget()) || this.distanceToSqr(this.getTarget()) < 50)) {
        this.hurtMob(this.getTarget());
    }
    breakBlock();
    if (!level.isClientSide && this.isPassenger() && this.getRootVehicle() instanceof Boat) {
        Boat boat = (Boat) this.getRootVehicle();
        boat.remove(RemovalReason.KILLED);
        this.stopRiding();
    }
}

protected void onImpact(RayTraceResult rayTrace){

	Entity entityHit = rayTrace.entityHit;

	if(entityHit != null){
		// This is if the ice charge gets a direct hit
		float damage = Spells.ice_charge.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

		entityHit.attackEntityFrom(
				MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FROST).setProjectile(),
				damage);

		if(!this.world.isRemote && entityHit instanceof EntityLivingBase && !MagicDamage.isEntityImmune(DamageType.FROST, entityHit))
			((EntityLivingBase)entityHit).addPotionEffect(new PotionEffect(WizardryPotions.frost,
					Spells.ice_charge.getProperty(Spell.DIRECT_EFFECT_DURATION).intValue(),
					Spells.ice_charge.getProperty(Spell.DIRECT_EFFECT_STRENGTH).intValue()));
	}

	// Particle effect
	if(world.isRemote){
		this.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, this.posX, this.posY, this.posZ, 0, 0, 0);
		for(int i = 0; i < 30 * blastMultiplier; i++){

			ParticleBuilder.create(Type.ICE, rand, this.posX, this.posY, this.posZ, 2 * blastMultiplier, false)
			.time(35).gravity(true).spawn(world);

			float brightness = 0.4f + rand.nextFloat() * 0.5f;
			ParticleBuilder.create(Type.DARK_MAGIC, rand, this.posX, this.posY, this.posZ, 2 * blastMultiplier, false)
			.clr(brightness, brightness + 0.1f, 1.0f).spawn(world);
		}
	}

	if(!this.world.isRemote){

		this.playSound(WizardrySounds.ENTITY_ICE_CHARGE_SMASH, 1.5f, rand.nextFloat() * 0.4f + 0.6f);
		this.playSound(WizardrySounds.ENTITY_ICE_CHARGE_ICE, 1.2f, rand.nextFloat() * 0.4f + 1.2f);

		double radius = Spells.ice_charge.getProperty(Spell.EFFECT_RADIUS).floatValue() * blastMultiplier;

		List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(radius, this.posX, this.posY,
				this.posZ, this.world);

		// Slows targets
		for(EntityLivingBase target : targets){
			if(target != entityHit && target != this.getThrower()){
				if(!MagicDamage.isEntityImmune(DamageType.FROST, target))
					target.addPotionEffect(new PotionEffect(WizardryPotions.frost,
							Spells.ice_charge.getProperty(Spell.SPLASH_EFFECT_DURATION).intValue(),
							Spells.ice_charge.getProperty(Spell.SPLASH_EFFECT_STRENGTH).intValue()));
			}
		}

		// Places snow and ice on ground.
		for(int i = -1; i < 2; i++){
			for(int j = -1; j < 2; j++){

				BlockPos pos = new BlockPos(this.posX + i, this.posY, this.posZ + j);

				Integer y = BlockUtils.getNearestSurface(world, pos, EnumFacing.UP, 7, true,
						BlockUtils.SurfaceCriteria.SOLID_LIQUID_TO_AIR);

				if(y != null){

					pos = new BlockPos(pos.getX(), y, pos.getZ());

					double dist = this.getDistance(pos.getX(), pos.getY(), pos.getZ());

					// Randomised with weighting so that the nearer the block the more likely it is to be snowed.
					if(rand.nextInt((int)dist * 2 + 1) < 1 && dist < 2){
						if(world.getBlockState(pos.down()).getBlock() == Blocks.WATER){
							world.setBlockState(pos.down(), Blocks.ICE.getDefaultState());
						}else{
							// Don't need to check whether the block at pos can be replaced since getNearestFloorLevelB
							// only ever returns floors with air above them.
							world.setBlockState(pos, Blocks.SNOW_LAYER.getDefaultState());
						}
					}
				}
			}
		}

		// Releases shards
		for(int i = 0; i < Spells.ice_charge.getProperty(ICE_SHARDS).intValue(); i++){
			double dx = rand.nextDouble() - 0.5;
			double dy = rand.nextDouble() - 0.5;
			double dz = rand.nextDouble() - 0.5;
			EntityIceShard iceshard = new EntityIceShard(world);
			iceshard.setPosition(this.posX + dx, this.posY + dy, this.posZ + dz);
			iceshard.motionX = dx * 1.5;
			iceshard.motionY = dy * 1.5;
			iceshard.motionZ = dz * 1.5;
			iceshard.setCaster(this.getThrower());
			iceshard.damageMultiplier = this.damageMultiplier;
			world.spawnEntity(iceshard);
		}

		this.setDead();
	}
}

public ItemStack applyUpgrade(@Nullable EntityPlayer player, ItemStack wand, ItemStack upgrade){

	// Upgrades wand if necessary. Damage is copied, preserving remaining durability,
	// and also the entire NBT tag compound.
	if(upgrade.getItem() == WizardryItems.arcane_tome){

		Tier tier = Tier.values()[upgrade.getItemDamage()];

		// Checks the wand upgrade is for the tier above the wand's tier, and that either the wand has enough
		// progression or the player is in creative mode.
		if((player == null || player.isCreative() || Wizardry.settings.legacyWandLevelling
				|| WandHelper.getProgression(wand) >= tier.getProgression())
				&& tier == this.tier.next() && this.tier != Tier.MASTER){

			if(Wizardry.settings.legacyWandLevelling){
				// Progression has little meaning with legacy upgrade mechanics so just reset it
				// In theory, you can get 'free' progression when upgrading since progression can't be negative,
				// so the flipside of that is you lose any excess
				WandHelper.setProgression(wand, 0);
			}else{
				// Carry excess progression over to the new stack
				WandHelper.setProgression(wand, WandHelper.getProgression(wand) - tier.getProgression());
			}

			if(player != null) WizardData.get(player).setTierReached(tier);

			ItemStack newWand = new ItemStack(getWand(tier, this.element));
			newWand.setTagCompound(wand.getTagCompound());
			// This needs to be done after copying the tag compound so the mana capacity for the new wand
			// takes storage upgrades into account
			// Note the usage of the new wand item and not 'this' to ensure the correct capacity is used
			((IManaStoringItem)newWand.getItem()).setMana(newWand, this.getMana(wand));

			upgrade.shrink(1);

			return newWand;
		}

	}else if(WandHelper.isWandUpgrade(upgrade.getItem())){

		// Special upgrades
		Item specialUpgrade = upgrade.getItem();

		int maxUpgrades = this.tier.upgradeLimit;
		if(this.element == null) maxUpgrades += Constants.NON_ELEMENTAL_UPGRADE_BONUS;

		if(WandHelper.getTotalUpgrades(wand) < maxUpgrades
				&& WandHelper.getUpgradeLevel(wand, specialUpgrade) < Constants.UPGRADE_STACK_LIMIT){

			// Used to preserve existing mana when upgrading storage rather than creating free mana.
			int prevMana = this.getMana(wand);

			WandHelper.applyUpgrade(wand, specialUpgrade);

			// Special behaviours for specific upgrades
			if(specialUpgrade == WizardryItems.storage_upgrade){

				this.setMana(wand, prevMana);

			}else if(specialUpgrade == WizardryItems.attunement_upgrade){

				int newSlotCount = BASE_SPELL_SLOTS + WandHelper.getUpgradeLevel(wand,
						WizardryItems.attunement_upgrade);

				Spell[] spells = WandHelper.getSpells(wand);
				Spell[] newSpells = new Spell[newSlotCount];

				for(int i = 0; i < newSpells.length; i++){
					newSpells[i] = i < spells.length && spells[i] != null ? spells[i] : Spells.none;
				}

				WandHelper.setSpells(wand, newSpells);

				int[] cooldowns = WandHelper.getCooldowns(wand);
				int[] newCooldowns = new int[newSlotCount];

				if(cooldowns.length > 0){
					System.arraycopy(cooldowns, 0, newCooldowns, 0, cooldowns.length);
				}

				WandHelper.setCooldowns(wand, newCooldowns);
			}

			upgrade.shrink(1);

			if(player != null){

				WizardryAdvancementTriggers.special_upgrade.triggerFor(player);

				if(WandHelper.getTotalUpgrades(wand) == Tier.MASTER.upgradeLimit){
					WizardryAdvancementTriggers.max_out_wand.triggerFor(player);
				}
			}

		}
	}

	return wand;
}

public void explode() {
    this.level.gameEvent(this.source, GameEvent.EXPLODE, new Vec3(this.x, this.y, this.z));
    Set<BlockPos> set = Sets.newHashSet();
    int i = 16;

    for (int j = 0; j < 16; ++j) {
        for (int k = 0; k < 16; ++k) {
            for (int l = 0; l < 16; ++l) {
                if (j == 0 || j == 15 || k == 0 || k == 15 || l == 0 || l == 15) {
                    double d0 = (double) ((float) j / 15.0F * 2.0F - 1.0F);
                    double d1 = (double) ((float) k / 15.0F * 2.0F - 1.0F);
                    double d2 = (double) ((float) l / 15.0F * 2.0F - 1.0F);
                    double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                    d0 /= d3;
                    d1 /= d3;
                    d2 /= d3;
                    float f = this.radius * (0.7F + this.level.random.nextFloat() * 0.6F);
                    double d4 = this.x;
                    double d6 = this.y;
                    double d8 = this.z;

                    for (float f1 = 0.3F; f > 0.0F; f -= 0.22500001F) {
                        BlockPos blockpos = BlockPos.containing(d4, d6, d8);
                        BlockState blockstate = this.level.getBlockState(blockpos);
                        if (!this.level.isInWorldBounds(blockpos) || blockstate.is(ACTagRegistry.UNMOVEABLE)) {
                            break;
                        }

                        f -= blockstate.getFluidState().isEmpty() ? (blockstate.getBlock().getExplosionResistance() + 0.3F) * 0.3F : 0.0F;

                        set.add(blockpos);


                        d4 += d0 * (double) 0.3F;
                        d6 += d1 * (double) 0.3F;
                        d8 += d2 * (double) 0.3F;
                    }
                }
            }
        }
    }

    this.toBlow.addAll(set);
    float f2 = this.radius * 2.0F;
    int k1 = Mth.floor(this.x - (double) f2 - 1.0D);
    int l1 = Mth.floor(this.x + (double) f2 + 1.0D);
    int i2 = Mth.floor(this.y - (double) f2 - 1.0D);
    int i1 = Mth.floor(this.y + (double) f2 + 1.0D);
    int j2 = Mth.floor(this.z - (double) f2 - 1.0D);
    int j1 = Mth.floor(this.z + (double) f2 + 1.0D);
    List<Entity> list = this.level.getEntities(this.source, new AABB((double) k1, (double) i2, (double) j2, (double) l1, (double) i1, (double) j1));
    Vec3 vec3 = new Vec3(this.x, this.y, this.z);

    for (int k2 = 0; k2 < list.size(); ++k2) {
        Entity entity = list.get(k2);
        if (!entity.ignoreExplosion() && !(entity instanceof EnderMan)) {
            double d12 = Math.sqrt(entity.distanceToSqr(vec3)) / (double) f2;
            if (d12 <= 1.0D) {
                double d5 = entity.getX() + (random.nextFloat() - 0.5F) - this.x;
                double d7 = (entity instanceof FallingFrostmintEntity ? entity.getY() : entity.getEyeY()) - this.y;
                double d9 = entity.getZ() + (random.nextFloat() - 0.5F) - this.z;
                double d13 = Math.sqrt(d5 * d5 + d7 * d7 + d9 * d9);
                if (d13 != 0.0D) {
                    d5 /= d13;
                    d7 /= d13;
                    d9 /= d13;
                    double d14 = (double) getSeenPercent(vec3, entity);
                    double d10 = (1.0D - d12) * d14;
                    if(!(entity instanceof ItemEntity) || !fromSpear){
                        entity.hurt(this.getDamageSource(), (float) ((int) ((d10 * d10 + d10) / 2.0D * 7.0D * (double) f2 + 1.0D)));
                    }
                    double d11;
                    if (entity instanceof LivingEntity) {
                        LivingEntity livingentity = (LivingEntity) entity;
                        d11 = ProtectionEnchantment.getExplosionKnockbackAfterDampener(livingentity, d10);
                    } else {
                        d11 = d10;
                    }

                    d5 *= d11;
                    d7 *= d11;
                    d9 *= d11;
                    Vec3 vec31 = new Vec3(d5, d7, d9);
                    entity.setDeltaMovement(entity.getDeltaMovement().add(vec31));
                    if (entity instanceof Player) {
                        Player player = (Player) entity;
                        if (!player.isSpectator() && (!player.isCreative() || !player.getAbilities().flying)) {
                            this.hitPlayers.put(player, vec31);
                        }
                    }
                    if(entity instanceof LivingEntity living){
                        living.setTicksFrozen(living.getTicksRequiredToFreeze() + 200);
                        ((FrostmintFreezableAccessor)living).setFrostmintFreezing(true);
                    }
                }
            }
        }
    }

}

public void tick() {
    super.tick();
    prevSwimProgress = swimProgress;
    prevRetreatProgress = retreatProgress;
    prevSpinProgress = spinProgress;

    final boolean inWaterOrBubble = this.isInWaterOrBubble();
    final boolean spinning = this.isSpinning();
    final boolean retreated = this.hasRetreated();

    if (inWaterOrBubble) {
        if (swimProgress < 5F)
            swimProgress++;
    } else {
        if (swimProgress > 0F)
            swimProgress--;
    }

    if (spinning) {
        if (spinProgress < 5F)
            spinProgress++;
    } else {
        if (spinProgress > 0F)
            spinProgress--;
    }

    if (retreated) {
        if (retreatProgress < 5F)
            retreatProgress++;
    } else {
        if (retreatProgress > 0F)
            retreatProgress--;
    }

    if (spinning) {
        this.handleSpin();
        if (this.isAlive() && spinCounter > 5 && !this.isBaby()) {
            for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.3F))) {
                if (!isAlliedTo(entity) && !(entity instanceof EntityTerrapin)) {
                    entity.hurt(this.damageSources().mobAttack(lastLauncher == null ? this : lastLauncher), 4.0F + random.nextFloat() * 4.0F);
                }
            }
        }
        if (!this.isAlive()) {
            this.setSpinning(false);
        }
        if (this.horizontalCollision) {
            if(changeSpinAngleCooldown == 0){
                changeSpinAngleCooldown = 10;
                float f = collideDirectionAndSound().getAxis() == Direction.Axis.X ? this.spinYRot - 180 : 180 - this.spinYRot;
                f += random.nextInt(40) - 20;
                this.setYRot(f);
                this.copySpinDelta(f, Vec3.ZERO);
            }else{
                maxRollTime -= 30;
            }

        }
        if (changeSpinAngleCooldown > 0) {
            changeSpinAngleCooldown--;
        }
    }
    if (!this.level().isClientSide) {
        if (this.isInWaterOrBubble() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!this.isInWaterOrBubble() && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (isInWater()) {
            swimTimer = Math.max(0, swimTimer + 1);
        } else {
            swimTimer = Math.min(0, swimTimer - 1);
            List<Player> list = this.level().getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(0, 0.15F, 0));
            for (Player player : list) {
                if ((player.jumping || !player.onGround()) && player.getY() > this.getEyeY()) {
                    if (!hasRetreated()) {
                        this.hideInShellTimer += 40 + random.nextInt(40);
                    } else if (!isSpinning()) {
                        lastLauncher = player;
                        final int spin = 100 + random.nextInt(100);
                        this.hideInShellTimer = spin;
                        this.setYRot(player.getYHeadRot());
                        spinFor(spin);
                    }
                }
            }
        }

        if (swimProgress > 0) {
            this.setMaxUpStep(1);
        } else {
            this.setMaxUpStep(0.6F);
        }
        if (hideInShellTimer > 0) {
            hideInShellTimer--;
        }
        this.setRetreated(hideInShellTimer > 0 && !this.isSpinning());
    }
}

    public void travel(@NotNull Vec3 pTravelVector) {
        if (this.isInLava()) {
            // In lava special
            if (this.isEffectiveAi() && this.getControllingPassenger() == null) {
                // Ice dragons swim faster
                this.moveRelative(this.getSpeed(), pTravelVector);
                this.move(MoverType.SELF, this.getDeltaMovement());
                this.setDeltaMovement(this.getDeltaMovement().scale(0.7D));
                if (this.getTarget() == null) {
//                    this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.005D, 0.0D));
                }
            } else if (allowLocalMotionControl && this.getControllingPassenger() != null && canBeControlledByRider() && !isHovering() && !isFlying()) {
                LivingEntity rider = (LivingEntity) this.getControllingPassenger();

                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);
                // Bigger difference in speed for young and elder dragons
                float lavaSpeedMod = (float) (0.28f + 0.1 * Mth.map(speed, this.minimumSpeed, this.maximumSpeed, 0f, 1.5f));
                speed *= lavaSpeedMod;
                speed *= rider.isSprinting() ? 1.4f : 1.0f;

                float vertical = 0f;
                if (isGoingUp() && !isGoingDown()) {
                    vertical = 0.8f;
                } else if (isGoingDown() && !isGoingUp()) {
                    vertical = -0.8f;
                } else if (isGoingUp() && isGoingDown() && isControlledByLocalInstance()) {
                    // Try floating
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.3f, 1.0f));
                }

                Vec3 travelVector = new Vec3(
                        rider.xxa,
                        vertical,
                        rider.zza
                );
                if (this.isControlledByLocalInstance()) {
                    this.setSpeed(speed);

                    this.moveRelative(this.getSpeed(), travelVector);
                    this.move(MoverType.SELF, this.getDeltaMovement());

                    Vec3 currentMotion = this.getDeltaMovement();
                    if (this.horizontalCollision) {
                        currentMotion = new Vec3(currentMotion.x, 0.2D, currentMotion.z);
                    }
                    this.setDeltaMovement(currentMotion.scale(0.7D));

                    this.calculateEntityAnimation(this, false);
                } else {
                    this.setDeltaMovement(Vec3.ZERO);
                }
                this.tryCheckInsideBlocks();
            } else {
                super.travel(pTravelVector);
            }
        }
        // Over lava special
        else if (allowLocalMotionControl && this.getControllingPassenger() != null && canBeControlledByRider() && !isHovering() && !isFlying()
                && this.level.getBlockState(this.getBlockPosBelowThatAffectsMyMovement()).getFluidState().is(FluidTags.LAVA)) {
            LivingEntity rider = (LivingEntity) this.getControllingPassenger();

            double forward = rider.zza;
            double strafing = rider.xxa;
            // Inherit y motion for dropping
            double vertical = pTravelVector.y;
            float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);

            float groundSpeedModifier = (float) (1.8F * this.getFlightSpeedModifier());
            speed *= groundSpeedModifier;
            // Try to match the original riding speed
//            forward *= speed;
            // Faster sprint
            forward *= rider.isSprinting() ? 1.2f : 1.0f;
            // Slower going back
            forward *= rider.zza > 0 ? 1.0f : 0.2f;
            // Slower going sideway
            strafing *= 0.05f;

            if (this.isControlledByLocalInstance()) {
                this.flyingSpeed = speed * 0.1F;
                this.setSpeed(speed);

                // Vanilla walking behavior includes going up steps
                super.travel(new Vec3(strafing, vertical, forward));

                Vec3 currentMotion = this.getDeltaMovement();
                if (this.horizontalCollision) {
                    currentMotion = new Vec3(currentMotion.x, 0.2D, currentMotion.z);
                }
                this.setDeltaMovement(currentMotion.scale(0.7D));
            } else {
                this.setDeltaMovement(Vec3.ZERO);
            }
            this.tryCheckInsideBlocks();
//            this.updatePitch(this.yOld - this.getY());
            return;
        } else {
            super.travel(pTravelVector);
        }
    }

public boolean processInteract(EntityPlayer player, EnumHand hand) {
	ItemStack stack = player.getHeldItem(hand);
	boolean holdsEquipment = hand == EnumHand.MAIN_HAND && !stack.isEmpty() && (stack.getItem() instanceof IEquippable || stack.getItem() == ItemRegistry.AMULET_SLOT);
	if (holdsEquipment)
		return true;
	if (!stack.isEmpty()) {
		if (stack.getItem() == ItemRegistry.SNAIL_FLESH_RAW) {
			if (getHealth() < getMaxHealth()) {
				if (!getEntityWorld().isRemote) {
					heal(5.0F);
					if (!player.capabilities.isCreativeMode) {
						stack.shrink(1);
						if (stack.getCount() <= 0)
							player.setHeldItem(hand, ItemStack.EMPTY);
					}
				} else {
					playTameEffect(true);
				}

				return true;
			}
		}
		if (stack.getItem() == ItemRegistry.NET)
			return stack.getItem().itemInteractionForEntity(stack, player, this, EnumHand.MAIN_HAND);
	}

	if (isOwner(player) && hand == EnumHand.MAIN_HAND && !(this instanceof IPullerEntity)) {
		rotationYaw = player.rotationYaw;

		if (!getEntityWorld().isRemote) {
			setAttackTarget((EntityLivingBase) null);

			Entity riding = getRidingEntity();

			if (riding == null) {
				if (!player.isBeingRidden()) { // stops multiple mounting you
					if(isSitting()) {
						this.setSitting(false);
					}
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_MATRIARCH_LAND, SoundCategory.NEUTRAL, 0.25F, 1.5F);
					startRiding(player, true);
				}
			} else {
				boolean canUnmount = this.world.getCollisionBoxes(this, this.getEntityBoundingBox()).isEmpty();

				if(canUnmount) {
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_MATRIARCH_RELEASE, SoundCategory.NEUTRAL, 0.5F, 1F);
					dismountRidingEntity();
				} else if(player instanceof EntityPlayerMP) {
					((EntityPlayerMP) player).sendStatusMessage(new TextComponentTranslation("chat.chiromaw_tame.obstructed"), true);
				}

				if(!this.isSitting()) {
					if(canUnmount) {
						List<BlockPos> sitPositions = new ArrayList<>();

						for(int yo = 2; yo <= 4; yo++) {
							for(int xo = -1; xo <= 1; xo++) {
								for(int zo = -1; zo <= 1; zo++) {
									BlockPos pos = new BlockPos(riding.getPosition().add(xo, yo, zo));

									if(this.world.isAirBlock(pos)) {
										IBlockState state = this.world.getBlockState(pos.up());
										BlockFaceShape shape = state.getBlockFaceShape(this.world, pos.up(), EnumFacing.DOWN);

										if(shape == BlockFaceShape.SOLID || shape == BlockFaceShape.MIDDLE_POLE_THICK) {
											sitPositions.add(pos);
										}
									}
								}
							}
						}

						if(!sitPositions.isEmpty()) {
							this.setSitting(true);
							this.isJumping = false;

							Collections.sort(sitPositions, Comparator.comparingDouble(pos -> this.getDistanceSq(pos.getX() + 0.5f, pos.getY() + 0.5f, pos.getZ() + 0.5f)));

							BlockPos sitPosition = sitPositions.get(0);

							this.setPosition(sitPosition.getX() + 0.5f, sitPosition.getY() + 1 - this.height, sitPosition.getZ() + 0.5f);
							this.navigator.clearPath();
							this.motionX = this.motionY = this.motionZ = 0;
							this.velocityChanged = true;
							this.setMoveForward(0);
							this.setMoveStrafing(0);
							this.setMoveVertical(0);
						}
					}
				} else {
					this.setSitting(false);
				}
			}
		}
		return true;
	}

	return super.processInteract(player, hand);
}

    public void tick() {
        if (getClingDirection() != Direction.DOWN) {
            setDeltaMovement(0, 0, 0);
            setPos(xo, yo, zo);
        }

        super.tick();
        screamTimer = Math.max(0, screamTimer - 1);

        if (getClingDirection() != Direction.DOWN) {
            if (getClingDirection() != Direction.UP) {
                setYRot(getClingDirection().getOpposite().toYRot());
                yRotO = getYRot();
                yBodyRot = getYRot();
                yBodyRotO = yBodyRot;
            }
        }

        if (!level().isClientSide()) {
            if (getClingDirection() != Direction.DOWN) {
                if (!canContinueClinging()) {
//                    System.out.println("STOPPED CLINGING DUE TO MISSING BLOCK CONNECTION");
                    stopClinging();
                }
            }

            if (!getNightForm() && fleeGoal != null && !fleeGoal.isActive() && getClingDirection() == Direction.DOWN) {
                sitCooldown.tick();
            }

            // Curse status effect
            boolean isDay = isDayTime(level());
            boolean isNewMoon = level().getMoonPhase() == 4;
            if (!isDay && !isNewMoon) {
                addEffect(new MobEffectInstance(EffectHandler.MOONS_CURSE, 10, 0, false, false));
            }
            else {
                removeEffect(EffectHandler.MOONS_CURSE);
            }
        }
        else {
            if (getClingDirection().getAxis().isHorizontal()) {
                Vec3i clingDirVec = getClingDirection().getNormal();
                BlockState state = level().getBlockState(BlockPos.containing(position().add(0, getBbHeight(), 0)).offset(clingDirVec));
                missingWallClingUpperBlock = !state.isSolid();
            }
            else {
                missingWallClingUpperBlock = false;
            }
        }

        damageThreat -= damageThreatDecayRate;
        damageThreat = Mth.clamp(damageThreat, 0, 1);

        if (getTarget() != null && isStalking) {
            stalkingTimer -= 1;
            // Reduce timer faster if target is looking at the elokosa
            if (isLookingAtMe(getTarget())) {
                lookingAtMeTimer -= 1;
                lookingAtMeTimer = Math.max(lookingAtMeTimer, 0);
            }
            else {
                lookingAtMeTimer += 1;
                lookingAtMeTimer = Math.min(lookingAtMeTimer, LOOKING_AT_ME_TIMER_MAX);
            }
            if (getTarget() instanceof Mob mob && mob.getTarget() == this) {
                stalkingTimer = 0;
            }
            if (lookingAtMeTimer == 0) {
                stalkingTimer = 0;
            }
        }
        else {
            lookingAtMeTimer = LOOKING_AT_ME_TIMER_MAX;
        }

        if (getActiveAbilityType() != null && getActiveAbilityType() != HURT_ABILITY && getActiveAbilityType() != SCREAM_ABILITY) {
            getNavigation().stop();
            yHeadRot = yBodyRot = getYRot();
        }

        // Drool particles
        if (getNightForm() && level().isClientSide()) {
            if (random.nextInt(15) == 0) {
                AdvancedParticleBase.spawnParticle(level(), ParticleHandler.PIXEL, getX(), getY(), getZ(), 0, 0, 0, true, 0, 0, 0, 0, 0F, 1, 1, 1, 0.4, 1, 80, false, true, new ParticleComponent[]{
                        new ParticleComponent.Gravity(0.5f),
                        new ParticleComponent.PinLocation(droolPositions.get(random.nextInt(droolPositions.size())), 20).setVelocityOnRelease(0, -0.08f, 0),
                        new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.SCALE, new ParticleComponent.KeyTrack(
                                new float[]{0f, 2},
                                new float[]{0.0f, 0.125f}
                        ), false)
                });
            }
        }

//        if (getActiveAbility() == null) {
//            sendAbilityMessage(BACKFLIP_ABILITY);
//        }

    }

    public void onSyncUpdate() {
    	// Sync Target Status:
    	if(!this.getEntityWorld().isRemote) {
    		byte targets = 0;
    		if(this.getAttackTarget() != null)
    			targets += TARGET_BITS.ATTACK.id;
    		if(this.getMasterTarget() != null)
    			targets += TARGET_BITS.MASTER.id;
    		if(this.getParentTarget() != null)
    			targets += TARGET_BITS.PARENT.id;
    		if(this.getAvoidTarget() != null)
    			targets += TARGET_BITS.AVOID.id;
    		if(this.getControllingPassenger() != null)
    			targets += TARGET_BITS.RIDER.id;
			if(this.getPickupEntity() != null)
				targets += TARGET_BITS.PICKUP.id;
    		this.dataManager.set(TARGET, targets);
    	}

		// Attack Phase:
    	if(!this.getEntityWorld().isRemote)
    		this.dataManager.set(ATTACK_PHASE, this.attackPhase);

    	// Animations Server:
        if(!this.getEntityWorld().isRemote) {
        	byte animations = 0;

        	// Attack Cooldown:
        	if(this.isAttackOnCooldown()) {
        		animations += ANIMATION_STATE_BITS.ATTACKED.id;
        	}

        	// Airborne Animation:
        	if(this.onGround)
        		animations += ANIMATION_STATE_BITS.GROUNDED.id;

            // Swimming Animation:
            if(this.inWater)
                animations += ANIMATION_STATE_BITS.IN_WATER.id;

        	// Blocking Animation:
        	if(this.isBlocking())
        		animations += ANIMATION_STATE_BITS.BLOCKING.id;

        	// Blocking Animation:
        	if(this.isMinion())
        		animations += ANIMATION_STATE_BITS.MINION.id;

        	// Extra Animation 01:
        	if(this.extraAnimation01())
        		animations += ANIMATION_STATE_BITS.EXTRA01.id;

        	this.dataManager.set(ANIMATION_STATE, animations);
        }

        // Animations Client:
        else if(this.getEntityWorld().isRemote) {
        	byte animationState = this.getByteFromDataManager(ANIMATION_STATE);
        	if((animationState & ANIMATION_STATE_BITS.ATTACKED.id) > 0) {
        		if(!this.isAttackOnCooldown()) {
					this.triggerAttackCooldown();
				}
			}
			else {
        		this.resetAttackCooldown();
			}
        	this.onGround = (animationState & ANIMATION_STATE_BITS.GROUNDED.id) > 0;
            this.inWater = (animationState & ANIMATION_STATE_BITS.IN_WATER.id) > 0;
        	this.extraAnimation01 = (animationState & ANIMATION_STATE_BITS.EXTRA01.id) > 0;
        }

        // Is Minion:
        if(this.getEntityWorld().isRemote) {
    		this.isMinion = (this.getByteFromDataManager(ANIMATION_STATE) & ANIMATION_STATE_BITS.MINION.id) > 0;
        }

        // Subspecies:
        if(!this.getEntityWorld().isRemote) {
    		this.dataManager.set(SUBSPECIES, (byte)this.getSubspeciesIndex());
        }
        else {
        	if(this.getSubspeciesIndex() != this.getByteFromDataManager(SUBSPECIES))
        		this.applySubspecies(this.getByteFromDataManager(SUBSPECIES), false);
        }

        // Size:
        if(!this.getEntityWorld().isRemote) {
    		this.dataManager.set(SIZE, (float)this.sizeScale);
        }
        else {
        	if(this.sizeScale != this.getFloatFromDataManager(SIZE)) {
        		this.setSizeScale(this.getFloatFromDataManager(SIZE));
        	}
        }

        // Arena:
        if(!this.getEntityWorld().isRemote) {
            this.dataManager.set(ARENA, this.getArenaCenter() != null ? Optional.of(this.getArenaCenter()) : Optional.absent());
        }
    }

public void tick() {
    super.tick();
    this.prevLatchProgress = latchProgress;
    if (this.isLatched() && latchProgress < 5F) {
        latchProgress++;
    }
    if (!this.isLatched() && latchProgress > 0F) {
        latchProgress--;
    }
    if (noLatchCooldown > 0) {
        noLatchCooldown--;
    }
    double d1 = (this.getX() - xo);
    double d2 = (this.getZ() - zo);
    double d3 = Math.sqrt(d1 * d1 + d2 * d2);
    if (isLatched() && verticalCollision && d3 > 0.1F) {
        if (tickCount - lastStepTimestamp > 6) {
            lastStepTimestamp = tickCount;
            BlockState state = level().getBlockState(BlockPos.containing(this.getX(), this.getBoundingBox().maxY + 0.5, this.getZ()));
            this.playSound(state.getSoundType().getStepSound(), 1F, 0.5F);
        }
    }
    if (!level().isClientSide) {
        if (this.isLatched() && !this.isUpsideDownNavigator) {
            switchNavigator(true);
        }
        if (!this.isLatched() && this.isUpsideDownNavigator) {
            switchNavigator(false);
        }
    }
    Entity head = getHead();
    if (head instanceof BoundroidEntity boundroid) {
        if (!level().isClientSide) {
            this.entityData.set(HEAD_ID, head.getId());
            double distance = this.distanceTo(boundroid);
            double distanceGoal = isLatched() ? 1.25F + Math.sin(tickCount * 0.1F) * 0.25F : 3.5F;
            boolean headNoClip = false;
            float pullSpeed = boundroid.getTarget() != null ? 0.3F : 0.1F;
            if (!boundroid.hasLineOfSight(this) && !boundroid.stopPullingUp() && distance > 7) {
                headNoClip = true;
            }
            if (distance > distanceGoal && !boundroid.stopPullingUp()) {
                double disRem = Math.min(distance - distanceGoal, 1F);
                Vec3 moveTo = getChainFrom(1.0F).subtract(boundroid.position());
                if (moveTo.length() > 1.0D) {
                    moveTo = moveTo.normalize();
                }
                boundroid.draggedClimable = true;
                boundroid.setDeltaMovement(boundroid.getDeltaMovement().multiply(0.95F, 0.7F, 0.95F).add(moveTo.scale(disRem * pullSpeed)));
            } else {
                boundroid.draggedClimable = false;
            }
            distanceToCeiling = calculateDistanceToCeiling();
            if (this.isLatched()) {
                this.setNoGravity(true);
                if (distanceToCeiling > MAX_DIST_TO_CEILING || !isAlive() || noLatchCooldown > 0) {
                    changeLatchStateTime++;
                } else {
                    changeLatchStateTime = 0;
                }
                if (changeLatchStateTime > 5) {
                    this.setLatched(false);
                    if(noLatchCooldown > 0){
                        this.playSound(ACSoundRegistry.BOUNDROID_DAZED.get(), 2.0F, 1.0F);
                    }
                    changeLatchStateTime = 0;
                }
                this.setDeltaMovement(this.getDeltaMovement().add(0, 0.14, 0).scale(0.85F));
                goingUp = false;
                boundroid.stopGravity = true;
            } else {
                this.setNoGravity(false);
                boundroid.stopGravity = false;
                if ((distanceToCeiling < MAX_DIST_TO_CEILING || verticalCollision && !verticalCollisionBelow) && noLatchCooldown <= 0) {
                    changeLatchStateTime++;
                } else {
                    changeLatchStateTime = 0;
                }
                if (changeLatchStateTime > 5) {
                    this.setLatched(true);
                    changeLatchStateTime = 0;
                }
                if(goingUp && !hasBlockAbove()){
                    goingUp = false;
                }
                if (goingUp) {
                    this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, 1.5F, this.getDeltaMovement().z));
                } else if (this.onGround() && noLatchCooldown == 0 && this.isAlive() && random.nextInt(30) == 0 && distanceToCeiling > MAX_DIST_TO_CEILING && hasBlockAbove()) {
                    goingUp = true;
                }
            }
            boundroid.noPhysics = headNoClip;
        }
        if (boundroid.hurtTime > 0 || boundroid.deathTime > 0) {
            this.hurtTime = boundroid.hurtTime;
            this.deathTime = boundroid.deathTime;
        }
    } else if (!level().isClientSide) {
        this.remove(RemovalReason.KILLED);
    }
}

public void tick() {
    super.tick();
    if(isInNether()) {
        conversionTime++;
        if (conversionTime > 300 && !this.level().isClientSide) {
            Hoglin hoglin = this.convertTo(EntityType.HOGLIN, false);
            if(hoglin != null){
                hoglin.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 200, 0));
                this.dropEquipment();
                level().addFreshEntity(hoglin);
                this.remove(RemovalReason.DISCARDED);
            }
        }
    }
    if (entityToLaunchId != -1 && this.isAlive()) {
        Entity launch = this.level().getEntity(entityToLaunchId);
        this.ejectPassengers();
        entityToLaunchId = -1;
        if (launch != null && !launch.isPassenger()) {
            if (launch instanceof LivingEntity) {
                launch.setPos(this.getEyePosition().add(0, 1, 0));
                float rot = 180F + this.getYRot();
                float strength = (float) (getLaunchStrength() * (1.0D - ((LivingEntity) launch).getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)));
                float x = Mth.sin(rot * Mth.DEG_TO_RAD);
                float z = -Mth.cos(rot * Mth.DEG_TO_RAD);
                if (!(strength <= 0.0D)) {
                    launch.hasImpulse = true;
                    Vec3 vec3 = this.getDeltaMovement();
                    Vec3 vec31 = vec3.add((new Vec3(x, 0.0D, z)).normalize().scale(strength));
                    launch.setDeltaMovement(vec31.x, strength, vec31.z);
                }
            }
        }
    }
    if (this.getAnimation() == ANIMATION_BUCK && this.getAnimationTick() >= 5) {
        Entity passenger = this.getControllingPassenger();
        if (passenger instanceof LivingEntity) {
            entityToLaunchId = passenger.getId();
        }
    }
    if (!this.level().isClientSide) {
        if (this.isVehicle()) {
            ridingTime++;
            if (ridingTime >= this.getMaxRidingTime() && this.getAnimation() != ANIMATION_BUCK) {
                this.setAnimation(ANIMATION_BUCK);
            }
        } else {
            ridingTime = 0;
        }
        if (this.isAlive() && ridingTime > 0 && this.getDeltaMovement().horizontalDistanceSqr() > 0.1D) {
            for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                if (!(entity instanceof EntityTusklin) && !entity.isPassengerOfSameVehicle(this)) {
                    entity.hurt(this.damageSources().mobAttack(this), 4F + random.nextFloat() * 3.0F);
                    if (entity.onGround()) {
                        double d0 = entity.getX() - this.getX();
                        double d1 = entity.getZ() - this.getZ();
                        double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                        float f = 0.5F;
                        entity.push(d0 / d2 * f, f, d1 / d2 * f);
                    }
                }
            }
            this.setMaxUpStep(2F);
        }else{
            this.setMaxUpStep(1.1F);
        }
        if (this.getTarget() != null && this.hasLineOfSight(this.getTarget()) && distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + this.getBbWidth() + 1.8F) {
            if (this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() == 6) {
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                knockbackTarget(this.getTarget(), 0.9F, 0F);
            }
            if ((this.getAnimation() == ANIMATION_GORE_L) && this.getAnimationTick() == 6) {
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                knockbackTarget(this.getTarget(), 0.5F, -90F);
            }
            if ((this.getAnimation() == ANIMATION_GORE_R) && this.getAnimationTick() == 6) {
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                knockbackTarget(this.getTarget(), 0.5F, 90F);
            }
        }
    }
    if (this.getAnimation() == ANIMATION_RUT && this.getAnimationTick() == 23) {
        if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
            if (this.isBaby()) {
                if (level().getBlockState(this.blockPosition()).canBeReplaced() && random.nextInt(3) == 0) {
                    level().setBlockAndUpdate(this.blockPosition(), Blocks.BROWN_MUSHROOM.defaultBlockState());
                    this.gameEvent(GameEvent.BLOCK_DESTROY);
                    this.playSound(SoundEvents.CROP_PLANTED, this.getSoundVolume(), this.getVoicePitch());
                }
            }
            this.level().levelEvent(2001, blockPosition().below(), Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
            this.level().setBlock(blockPosition().below(), Blocks.DIRT.defaultBlockState(), 2);
            this.heal(5);
        }
    }
    if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && getRandom().nextInt(isBaby() ? 140 : 70) == 0 && (this.getLastHurtByMob() == null || this.distanceTo(this.getLastHurtByMob()) > 30)) {
        if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
            this.setAnimation(ANIMATION_RUT);
        }
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

    public void travel(Vec3 pTravelVector) {
        if (this.isInWater()) {
            // In water special
            if (this.isEffectiveAi() && this.getControllingPassenger() == null) {
                // Ice dragons swim faster
                this.moveRelative(this.getSpeed(), pTravelVector);
                this.move(MoverType.SELF, this.getDeltaMovement());
                this.setDeltaMovement(this.getDeltaMovement().scale(0.9D));
                if (this.getTarget() == null) {
//                    this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.005D, 0.0D));
                }
            } else if (allowLocalMotionControl && this.getControllingPassenger() != null && canBeControlledByRider() && !isHovering() && !isFlying()) {
                LivingEntity rider = (LivingEntity) this.getControllingPassenger();

                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);
                // Bigger difference in speed for young and elder dragons
                float waterSpeedMod =  (float) (0.42f + 0.1 * Mth.map(speed, this.minimumSpeed, this.maximumSpeed, 0f, 1.5f));
                speed *= waterSpeedMod;
                speed *= rider.isSprinting() ? 1.5f : 1.0f;

                float vertical = 0f;
                if (isGoingUp() && !isGoingDown()) {
                    vertical = 1f;
                } else if (isGoingDown() && !isGoingUp()) {
                    vertical = -1f;
                } else if (isGoingUp() && isGoingDown() && isControlledByLocalInstance()) {
                    // Try floating
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.5f, 1.0f));
                }

                Vec3 travelVector = new Vec3(
                        rider.xxa,
                        vertical,
                        rider.zza
                );
                if (this.isControlledByLocalInstance()) {
                    this.setSpeed(speed);

                    this.moveRelative(this.getSpeed(), travelVector);
                    this.move(MoverType.SELF, this.getDeltaMovement());

                    Vec3 currentMotion = this.getDeltaMovement();
                    if (this.horizontalCollision) {
                        currentMotion = new Vec3(currentMotion.x, 0.2D, currentMotion.z);
                    }
                    this.setDeltaMovement(currentMotion.scale(0.9D));

                    this.calculateEntityAnimation(this, false);
                } else {
                    this.setDeltaMovement(Vec3.ZERO);
                }
                this.tryCheckInsideBlocks();
            } else {
                super.travel(pTravelVector);
            }

        }
        // Over water special
        else if (allowLocalMotionControl && this.getControllingPassenger() != null && canBeControlledByRider() && !isHovering() && !isFlying()
                && this.level.getBlockState(this.getBlockPosBelowThatAffectsMyMovement()).getFluidState().is(FluidTags.WATER)) {
            // Movement when walking on the water, mainly used for not slowing down when jumping out of water
            LivingEntity rider = (LivingEntity) this.getControllingPassenger();

            double forward = rider.zza;
            double strafing = rider.xxa;
            // Inherit y motion for dropping
            double vertical = pTravelVector.y;
            float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);

            float groundSpeedModifier = (float) (1.8F * this.getFlightSpeedModifier());
            speed *= groundSpeedModifier;
            // Try to match the original riding speed
//            forward *= speed;
            // Faster sprint
            forward *= rider.isSprinting() ? 1.2f : 1.0f;
            // Slower going back
            forward *= rider.zza > 0 ? 1.0f : 0.2f;
            // Slower going sideway
            strafing *= 0.05f;

            if (this.isControlledByLocalInstance()) {
                this.flyingSpeed = speed * 0.1F;
                this.setSpeed(speed);

                // Vanilla walking behavior includes going up steps
                super.travel(new Vec3(strafing, vertical, forward));

                Vec3 currentMotion = this.getDeltaMovement();
                if (this.horizontalCollision) {
                    currentMotion = new Vec3(currentMotion.x, 0.2D, currentMotion.z);
                }
                this.setDeltaMovement(currentMotion.scale(1.0D));
            } else {
                this.setDeltaMovement(Vec3.ZERO);
            }
            this.tryCheckInsideBlocks();
//            this.updatePitch(this.yOld - this.getY());
            return;
        } else {
            super.travel(pTravelVector);
        }
    }

protected void fireArrow(ItemStack itemStack, Level world, LivingEntity entity, int timeLeft) {
    if (entity instanceof Player) {
        Player player = (Player) entity;
        ItemStack ammoStack = player.getProjectile(vanillaBow);

        boolean playerInfinite = isInfinite(player, itemStack, ammoStack);

        // multiply by 20 to align progress with vanilla bow (fully drawn at 1sec/20ticks)
        int drawProgress = Math.round(getProgress(itemStack, entity) * 20);
        drawProgress = net.minecraftforge.event.ForgeEventFactory.onArrowLoose(itemStack, world, player, drawProgress,
                !ammoStack.isEmpty() || playerInfinite);

        if (drawProgress < 0) {
            return;
        }

        if (!ammoStack.isEmpty() || playerInfinite) {
            if (ammoStack.isEmpty()) {
                ammoStack = new ItemStack(Items.ARROW);
            }

            double strength = getDrawStrength(entity, itemStack);
            float velocityBonus = getEffectLevel(itemStack, ItemEffect.velocity) / 100f;
            int suspendLevel = getEffectLevel(itemStack, ItemEffect.suspend);
            ArrowItem ammoItem = CastOptional.cast(ammoStack.getItem(), ArrowItem.class)
                    .orElse((ArrowItem) Items.ARROW);
            boolean infiniteAmmo = player.getAbilities().instabuild || ammoItem.isInfinite(ammoStack, itemStack, player);

            ModularLooseProjectilesEvent looseProjectilesEvent = new ModularLooseProjectilesEvent(itemStack, ammoStack, player, world,
                    drawProgress, strength, suspendLevel > 0,
                    getArrowVelocity(drawProgress, strength, getEffectLevel(itemStack, ItemEffect.velocity) / 100f, suspendLevel > 0),
                    getEffectEfficiency(itemStack, ItemEffect.multishot),
                    Math.max(0, 100 - getEffectEfficiency(itemStack, ItemEffect.spread) - FocusEffect.getSpreadReduction(player, itemStack)),
                    player.getAbilities().instabuild || ammoItem.isInfinite(ammoStack, itemStack, player),
                    Mth.clamp(getEffectLevel(itemStack, ItemEffect.multishot), 1, infiniteAmmo ? 64 : ammoStack.getCount()),
                    player.getXRot(),
                    player.getYRot());
            MinecraftForge.EVENT_BUS.post(looseProjectilesEvent);

            ammoStack = looseProjectilesEvent.getAmmoStack();
            ImmutableList<Function<AbstractArrow, AbstractArrow>> projectileRemappers = looseProjectilesEvent.getProjectileRemappers();

            strength = looseProjectilesEvent.getStrength();
            boolean hasSuspend = looseProjectilesEvent.isHasSuspend();
            float projectileVelocity = looseProjectilesEvent.getProjectileVelocity();
            double multishotSpread = looseProjectilesEvent.getMultishotSpread();
            float accuracy = looseProjectilesEvent.getAccuracy();
            infiniteAmmo = looseProjectilesEvent.isInfiniteAmmo();
            int count = looseProjectilesEvent.getCount();
            double basePitch = looseProjectilesEvent.getBasePitch();
            double baseYaw = looseProjectilesEvent.getBaseYaw();

            if (projectileVelocity > 0.1f) {
                if (!world.isClientSide) {
                    int powerLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.POWER_ARROWS, itemStack);
                    int punchLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.PUNCH_ARROWS, itemStack);
                    int flameLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.FLAMING_ARROWS, itemStack);
                    int piercingLevel = getEffectLevel(itemStack, ItemEffect.piercing)
                            + EnchantmentHelper.getTagEnchantmentLevel(Enchantments.PIERCING, itemStack);

                    for (int i = 0; i < count; i++) {
                        double yaw = baseYaw - multishotSpread * (count - 1) / 2f + multishotSpread * i;
                        fireProjectile(itemStack, world, (ArrowItem) ammoStack.getItem(), ammoStack, projectileRemappers, player,
                                (float) basePitch, (float) yaw, projectileVelocity, accuracy, drawProgress, strength, powerLevel, punchLevel,
                                flameLevel, piercingLevel, hasSuspend, infiniteAmmo);
                    }


                    applyDamage(1, itemStack, player);
                    applyNegativeUsageEffects(entity, itemStack, 1);

                    // max draw at 20, has to be drawn at least 3/4th for positive effects
                    if (drawProgress > 15) {
                        applyPositiveUsageEffects(entity, itemStack, 1);
                    }
                }

                float pitchBase = projectileVelocity;
                if (velocityBonus > 0) {
                    pitchBase -= pitchBase * velocityBonus;
                } else if (hasSuspend) {
                    pitchBase = pitchBase / 2;
                }
                world.playSound(null, player.getX(), player.getY(), player.getZ(),
                        SoundEvents.ARROW_SHOOT, SoundSource.PLAYERS,
                        0.8F + projectileVelocity * 0.2f,
                        1.9f + world.random.nextFloat() * 0.2F - pitchBase * 0.8F);

                if (!infiniteAmmo && !player.getAbilities().instabuild) {
                    ammoStack.shrink(count);
                    if (ammoStack.isEmpty()) {
                        player.getInventory().removeItem(ammoStack);
                    }
                }

                FocusEffect.onFireArrow(player, itemStack);

                player.awardStat(Stats.ITEM_USED.get(this));
            }
        }
    }
}

public void onUpdate() {
	if(!this.world.isRemote) {
		this.setFlag(6, this.isGlowing());
	}

	this.onEntityUpdate();

	this.delay = Math.max(this.delay - 1, 0);

	if(this.delay == 6) {
		this.world.playSound((EntityPlayer)null, this.posX, this.posY, this.posZ, SoundRegistry.THUNDER, SoundCategory.WEATHER, 10000.0F, 0.8F + this.rand.nextFloat() * 0.2F);
		this.world.playSound((EntityPlayer)null, this.posX, this.posY, this.posZ, SoundRegistry.LIGHTNING, SoundCategory.WEATHER, 2.0F, 0.5F + this.rand.nextFloat() * 0.2F);

		this.world.setEntityState(this, EVENT_STRIKE);
	} else if(this.delay > 0 && this.delay <= 4) {
		if(this.world.isRemote) {
			this.world.setLastLightningBolt(2);
		} else if(!this.effectOnly) {
			if(this.delay == 4) {
				BlockPos blockpos = new BlockPos(this);

				if(!this.world.isRemote && this.world.getGameRules().getBoolean("doFireTick") && (this.world.getDifficulty() == EnumDifficulty.NORMAL || this.world.getDifficulty() == EnumDifficulty.HARD) && this.world.isAreaLoaded(blockpos, 10)) {
					if(this.world.getBlockState(blockpos).getMaterial() == Material.AIR && Blocks.FIRE.canPlaceBlockAt(this.world, blockpos)) {
						this.world.setBlockState(blockpos, Blocks.FIRE.getDefaultState());
					}

					for(int i = 0; i < 4; ++i) {
						BlockPos blockpos1 = blockpos.add(this.rand.nextInt(3) - 1, this.rand.nextInt(3) - 1, this.rand.nextInt(3) - 1);

						if(this.world.getBlockState(blockpos1).getMaterial() == Material.AIR && Blocks.FIRE.canPlaceBlockAt(this.world, blockpos1)) {
							this.world.setBlockState(blockpos1, Blocks.FIRE.getDefaultState());
						}
					}
				}
			}


			Vec3d start = new Vec3d(this.startPos.getX() + 0.5f, this.startPos.getY(), this.startPos.getZ());
			Vec3d end = this.getPositionVector();

			Vec3d diff = end.subtract(start);
			Vec3d dir = diff.normalize();

			double length = diff.length();

			double range = 5.0D;

			int steps = MathHelper.ceil(length / range / 2);
			for(int i = 0; i < steps;i++) {
				Vec3d checkPos = start.add(diff.scale(1 / (float)steps * (i + 1)));

				List<Entity> nearbyEntities = this.world.getEntitiesWithinAABBExcludingEntity(this, new AxisAlignedBB(checkPos.x - range, checkPos.y - range, checkPos.z - range, checkPos.x + range, checkPos.y + range, checkPos.z + range));

				for(Entity entity : nearbyEntities) {
					if(entity instanceof EntityLightningBolt == false) {
						Vec3d entityPos = entity.getPositionVector();

						Vec3d projection = start.add(dir.scale(dir.dotProduct(entityPos.subtract(start))));

						if(projection.subtract(entityPos).length() < range) {

							if(entity instanceof EntityItem) {
								EntityItem entityItem = (EntityItem) entity;
								ItemStack stack = entityItem.getItem();
								Item item = stack.getItem();

								if(item == ItemRegistry.ANGLER_TOOTH_ARROW || item == ItemRegistry.BASILISK_ARROW || item == ItemRegistry.OCTINE_ARROW || item == ItemRegistry.POISONED_ANGLER_TOOTH_ARROW || item == ItemRegistry.SLUDGE_WORM_ARROW) {
									if(this.world.rand.nextInt(5) == 0) {
										int converted = this.world.rand.nextInt(Math.min(stack.getCount(), 5)) + 1;

										stack.shrink(converted);
										if(stack.isEmpty()) {
											entityItem.setDead();
										} else {
											entityItem.setItem(stack);
										}

										EntityItem arrows = new EntityItem(this.world, entityItem.posX, entityItem.posY, entityItem.posZ, new ItemStack(ItemRegistry.SHOCK_ARROW, converted));
										this.world.spawnEntity(arrows);
									}
								} else if(item == ItemRegistry.CHIROBARB_ERUPTER) {
									entityItem.setItem(new ItemStack(ItemRegistry.CHIROBARB_SHOCK_ERUPTER, stack.getCount()));
								}

							} else if(!net.minecraftforge.event.ForgeEventFactory.onEntityStruckByLightning(entity, this)) {
								entity.onStruckByLightning(this);

								if(this.isFloatingTarget && entity instanceof EntityPlayerMP) {
									AdvancementCriterionRegistry.STRUCK_BY_LIGHTNING_WHILE_FLYING.trigger((EntityPlayerMP) entity);
								}
							}

						}
					}
				}
			}
		}
	} else if(this.delay == 0 && !this.world.isRemote) {
		this.setDead();
	}

	if(this.world.isRemote) {
		this.spawnArcs();
	}
}

protected Vec3d updateSpitMobsTipPos(Vec3d armStartWorld, float maxArmLength, Vec3d dirFwd, Vec3d dirUp) {
	if(this.actionTimer < 200 && this.bulgeSpawnCooldown-- <= 0) {
		if(this.spawnSeriesType == null) {
			Set<BulgeType> availableTypes = new HashSet<>();

			AxisAlignedBB checkAabb = this.getEntityBoundingBox().grow(12, 1, 12).expand(0, 11, 0);

			TObjectIntMap<BulgeType> bulgeCounts = new TObjectIntHashMap<>();
			for(Bulge bulge : this.bulges) {
				bulgeCounts.increment(bulge.type);
			}

			for(BulgeType bulgeType : BulgeType.values()) {
				if(this.world.getEntitiesWithinAABB(bulgeType.entityType, checkAabb).size() + bulgeCounts.get(bulgeType) < bulgeType.maxEntityCount && (bulgeType.spawnSeries <= 1 || this.bulges.isEmpty())) {
					availableTypes.add(bulgeType);
				}
			}

			if(!availableTypes.isEmpty()) {
				WeightedList<BulgeType> list = new WeightedList<>();

				list.addAll(availableTypes);
				list.recalculateWeight();

				BulgeType bulgeType = list.getRandomItem(this.rand);

				this.addBulge(bulgeType);

				if(bulgeType.spawnSeries > 1) {
					this.spawnSeriesCount = bulgeType.spawnSeries;
					this.spawnSeriesType = bulgeType;
				}
			}
		} else {
			this.addBulge(this.spawnSeriesType);

			this.spawnSeriesCount--;

			if(this.spawnSeriesCount <= 0) {
				this.spawnSeriesCount = 0;
				this.spawnSeriesType = null;
			}
		}

		if(this.spawnSeriesType == null) {
			this.bulgeSpawnCooldown = 15 + this.world.rand.nextInt(15);
		} else {
			this.bulgeSpawnCooldown = 4;
		}
	}

	if(this.actionTimer >= 200 && this.bulges.isEmpty()) {
		this.startAction(ActionState.IDLE);
	}

	float furthestPos = 0.0f;
	Bulge nextBulge = null;

	for(Bulge bulge : this.bulges) {
		if(bulge.position > furthestPos) {
			furthestPos = bulge.position;
			nextBulge = bulge;
		}
	}

	this.armMovementTicks++;

	Vec3d targetTipPos = armStartWorld.add(dirFwd.scale(maxArmLength + 1.0f));

	Entity target = this.getAttackTarget();

	if(nextBulge != null && nextBulge.type == BulgeType.LARGE_SLUDGE_WORM) {
		float rx = (float) Math.cos(this.ticksExisted * 0.05f);
		float rz = (float) Math.sin(this.ticksExisted * 0.05f);

		targetTipPos = armStartWorld.add(dirFwd.scale(maxArmLength / 2)).add(rx * 2, 0, rz * 2);
	} else if(nextBulge != null && nextBulge.type == BulgeType.LEECH && target != null) {
		Vec3d bendPos = armStartWorld.add(dirFwd.scale(maxArmLength));

		Vec3d targetDir = target.getPositionVector().subtract(bendPos).normalize().scale(5);

		targetTipPos = bendPos.add(targetDir);
	} else {
		float idleX = MathHelper.cos(this.armMovementTicks / 9.0f) * 0.75F;
		float idleY = MathHelper.sin(this.armMovementTicks / 7.0f) * 0.75F;
		float idleZ = (MathHelper.cos(this.armMovementTicks / 15.0f) + 1) * 0.25f;

		float forwardPos = (float) dirFwd.dotProduct(targetTipPos.subtract(armStartWorld));
		float offsetZ = 0.0f;
		if(forwardPos < 1.0F) {
			offsetZ = 1.0F - forwardPos;
		}

		//Idle movement
		targetTipPos = targetTipPos.add(dirUp.scale(idleY)).add(dirFwd.crossProduct(dirUp).scale(idleX)).add(dirFwd.scale(offsetZ - idleZ));
	}

	Vec3d tipPos = this.rootTip.getPositionVector();

	Vec3d diff = targetTipPos.subtract(tipPos);

	targetTipPos = tipPos.add(diff.normalize().scale(Math.min(diff.length(), 0.5D)));

	return targetTipPos;
}

public boolean interact(EntityPlayer entityplayer)
{
    ItemStack itemstack = entityplayer.inventory.getCurrentItem();

  //before ownership check 
  		if ((itemstack != null) && getIsTamed() && ((itemstack.itemID == MoCreatures.scrollOfOwner.itemID)) 
  				&& MoCreatures.proxy.enableResetOwnership && MoCTools.isThisPlayerAnOP(entityplayer))
  		{
  			if (--itemstack.stackSize == 0)
  			{
  				entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
  			}
  			if (MoCreatures.isServer())
  			{
  				if (MoCreatures.proxy.enableOwnership) 
  				{
  					EntityPlayer epOwner = this.worldObj.getPlayerEntityByName(this.getOwnerName());
  					if (epOwner != null)
  					{
  						MoCTools.reduceTamedByPlayer(epOwner);
  					}
  					else
  					{
  						MoCTools.reduceTamedByOfflinePlayer(this.getOwnerName());
  					}
  				}
  				this.setOwner("");
  			}
  			return true;
  		}

    //if the player interacting is not the owner, do nothing!
    if (MoCreatures.proxy.enableOwnership && getOwnerName() != null && !getOwnerName().equals("") && !entityplayer.username.equals(getOwnerName())) { return true; }

    //changes name
    if ((itemstack != null) && getIsTamed() //&& MoCreatures.isServer()
            && ((itemstack.itemID == MoCreatures.medallion.itemID) || (itemstack.itemID == Item.book.itemID)))
    {
        if (MoCreatures.isServer())
        {
            MoCTools.tameWithName((EntityPlayerMP) entityplayer, this);
        }
        //TODO NAMER
        /*if (!MoCreatures.isServer())
        {
            MoCreatures.proxy.setName(entityplayer, this);
        }*/
        return true;
    }

    //sets it free, untamed
    if ((itemstack != null) && getIsTamed() 
            && ((itemstack.itemID == MoCreatures.scrollFreedom.itemID)))
    {
        if (--itemstack.stackSize == 0)
        {
            entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
        }
        if (MoCreatures.isServer())
        {

            if (MoCreatures.proxy.enableOwnership) MoCTools.reduceTamedByPlayer(entityplayer);
            this.setOwner("");
            this.setName("");
            this.dropMyStuff();
            this.setTamed(false);
        }

        return true;
    }

    //removes owner, any other player can claim it by renaming it
    if ((itemstack != null) && getIsTamed() 
                    && ((itemstack.itemID == MoCreatures.scrollOfSale.itemID)))
    {
        if (--itemstack.stackSize == 0)
        {
            entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
        }
        if (MoCreatures.isServer())
        {

            if (MoCreatures.proxy.enableOwnership) MoCTools.reduceTamedByPlayer(entityplayer);
            this.setOwner("");
        }

        return true;
    }

    if ((itemstack != null) && getIsTamed() && isMyHealFood(itemstack))
    {
        if (--itemstack.stackSize == 0)
        {
            entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
        }
        worldObj.playSoundAtEntity(this, "eating", 1.0F, 1.0F + ((rand.nextFloat() - rand.nextFloat()) * 0.2F));
        if (MoCreatures.isServer())
        {
            health = getMaxHealth();
        }
        return true;
    }

    return false;
}

    public void onUpdate() {
        if(this.shootingEntity != null || this.summoningPedestal != null) {
			this.projectileLife = 5;
		}
        super.onUpdate();

        // ==========Summoning Pedestal ==========
        if(!this.getEntityWorld().isRemote) {
            if(this.summoningPedestal != null) {
                this.shootingEntity = this.summoningPedestal.getPlayer();
                this.summonClass = this.summoningPedestal.getSummonClass();
            }
        }

        // ==========Sync Shooter Name ==========
        if(!this.getEntityWorld().isRemote) {
            // Summoning Staff or Summoning Pedestal (with active player):
            if(this.shootingEntity != null)
                this.dataManager.set(OWNER_NAME, this.shootingEntity.getName());
            // Summoning Pedestal:
            else if(this.summoningPedestal != null)
                this.dataManager.set(OWNER_NAME, this.summoningPedestal.getOwnerName());
            // Wild:
            else
                this.dataManager.set(OWNER_NAME, "");
        }
        else {
            this.ownerName = this.dataManager.get(OWNER_NAME);
        }

    	// ========== Check for Despawn ==========
    	if(!this.getEntityWorld().isRemote && !this.isDead) {
            // Summoning Pedestal:
            if(this.summoningPedestal != null) {
                if(this.summonClass == null) {
                    this.setDead();
                    return;
                }
            }

            // Summoning Staff:
            else {
                if(this.shootingEntity == null || !this.shootingEntity.isEntityAlive() || this.portalItem == null) {
                    this.setDead();
                    return;
                }
                ExtendedPlayer playerExt = ExtendedPlayer.getForPlayer(this.shootingEntity);
				if(playerExt != null && playerExt.staffPortal != this) {
					this.setDead();
					return;
				}
            }
    	}

    	// ========== Move ==========
    	this.moveToTarget();

        // ========== Stat Sync ==========
        // Summoning Staff:
        if(this.shootingEntity != null && this.summoningPedestal == null) {
            ExtendedPlayer playerExt = ExtendedPlayer.getForPlayer(this.shootingEntity);
            if(playerExt != null && this.portalItem != null) {
                if(++this.summonTick >= this.portalItem.getRapidTime(null)) {
                    this.summonDuration = this.portalItem.getSummonDuration();
                    if(this.shootingEntity.capabilities.isCreativeMode)
                        this.summonAmount += this.portalItem.getSummonAmount();
                    else {
                        float summonMultiplier = (float) (CreatureManager.getInstance().getCreature(this.summonClass).summonCost + this.portalItem.getSummonCostBoost()) * this.portalItem.getSummonCostMod();
                        int summonCost = Math.round((float) playerExt.summonFocusCharge * summonMultiplier);
                        if(playerExt.summonFocus >= summonCost) {
                            if(this.portalItem.getAdditionalCosts(this.shootingEntity)) {
                                playerExt.summonFocus -= summonCost;
                                this.summonAmount += this.portalItem.getSummonAmount();
                            }
                        }
                    }
                    this.summonTick = 0;
                }
            }
        }

        // Summoning Pedestal:
        else if(this.summonClass != null) {
            if (++this.summonTick >= this.summonTime) {
                this.summonAmount = this.summoningPedestal.summonAmount;
                this.summonTick = 0;
            }
        }

        // ========== Client ==========
        if(this.getEntityWorld().isRemote) {
            for(int i = 0; i < 32; ++i) {
                double angle = Math.toRadians(this.rand.nextFloat() * 360);
                float distance = this.rand.nextFloat() * 2;
                double x = distance * Math.cos(angle) + Math.sin(angle);
                double z = distance * Math.sin(angle) - Math.cos(angle);
                this.getEntityWorld().spawnParticle(EnumParticleTypes.PORTAL,
                        this.posX + x,
                        this.posY + (4.0F * this.rand.nextFloat()) - 2.0F,
                        this.posZ + z,
                        0.0D, 0.0D, 0.0D);
            }
            return;
        }
    }

protected void onHitEntity(EntityHitResult raytrace) {
    Entity target = raytrace.getEntity();
    Entity shooter = getOwner();
    Player playerShooter = CastOptional.cast(shooter, Player.class).orElse(null);

    DamageSource damagesource = level().damageSources().trident(this, (shooter == null ? this : shooter));
    SoundEvent soundevent = SoundEvents.TRIDENT_HIT;

    int pierceLevel = getEffectLevel(ItemEffect.piercing);
    int ricochetLevel = getEffectLevel(ItemEffect.ricochet);

    if (pierceLevel > 0 || ricochetLevel > 0) {
        if (hitEntities == null) {
            hitEntities = new IntOpenHashSet(5);
        }

        if (hitEntities.contains(target.getId())) {
            return;
        }

        if (hitEntities.size() < pierceLevel || hitEntities.size() < ricochetLevel) {
            hitEntities.add(target.getId());
        } else {
            dealtDamage = true;
        }
    } else {
        dealtDamage = true;
    }

    ItemStack heldTemp = null;
    if (playerShooter != null) {
        heldTemp = playerShooter.getMainHandItem();
        playerShooter.setItemInHand(InteractionHand.MAIN_HAND, thrownStack);
    }

    if (target instanceof LivingEntity && thrownStack.getItem() instanceof ItemModularHandheld) {
        LivingEntity targetLivingEntity = (LivingEntity) target;
        ItemModularHandheld item = (ItemModularHandheld) thrownStack.getItem();

        double abilityDamage = item.getAbilityBaseDamage(shooter instanceof LivingEntity living ? living : null, thrownStack);

        double critModifier = CritEffect.rollMultiplier(targetLivingEntity.getRandom(), item, thrownStack);
        double damage = abilityDamage * item.getEffectEfficiency(thrownStack, ItemEffect.throwable);

        damage += EnchantmentHelper.getDamageBonus(thrownStack, targetLivingEntity.getMobType());
        damage *= critModifier;

        if (target.hurt(damagesource, (float) damage)) {
            if (shooter instanceof LivingEntity livingShooter) {
                EnchantmentHelper.doPostHurtEffects(targetLivingEntity, shooter);
                EffectHelper.applyEnchantmentHitEffects(getPickupItem(), targetLivingEntity, livingShooter);
                ItemEffectHandler.applyHitEffects(thrownStack, targetLivingEntity, livingShooter);

                item.tickProgression(livingShooter, thrownStack, 1);
            }

            doPostHurtEffects(targetLivingEntity);

            if (critModifier != 1d && !level().isClientSide) {
                Vec3 hitVec = raytrace.getLocation();
                ((ServerLevel) level()).sendParticles(ParticleTypes.ENCHANTED_HIT,
                        hitVec.x(), hitVec.y(), hitVec.z(), 15, 0.2D, 0.2D, 0.2D, 0.0D);
            }
        }
    }

    float f1 = 1.0F;
    if (!level().isClientSide && level().isThundering() && EnchantmentHelper.hasChanneling(thrownStack)) {
        BlockPos blockpos = target.blockPosition();
        if (level().canSeeSky(blockpos)) {
            LightningBolt lightning = EntityType.LIGHTNING_BOLT.create(this.level());
            lightning.moveTo(Vec3.atBottomCenterOf(blockpos));
            lightning.setCause(shooter instanceof ServerPlayer ? (ServerPlayer) shooter : null);
            this.level().addFreshEntity(lightning);
            soundevent = SoundEvents.TRIDENT_THUNDER;
            f1 = 5.0F;
        }
    }

    if (playerShooter != null) {
        playerShooter.setItemInHand(InteractionHand.MAIN_HAND, heldTemp);
    }

    playSound(soundevent, f1, 1.0F);

    if (dealtDamage) {
        setDeltaMovement(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D));
    } else if (ricochetLevel > 0 && !level().isClientSide) {
        Vec3 hitPos = raytrace.getLocation();
        setPosRaw(hitPos.x(), hitPos.y(), hitPos.z());
        setDeltaMovement(level().getEntities(shooter, new AABB(target.blockPosition()).inflate(8d), entity ->
                        !hitEntities.contains(entity.getId())
                                && entity instanceof LivingEntity
                                && !entity.isInvulnerableTo(damagesource)
                                && (shooter == null || !entity.isAlliedTo(shooter)))
                .stream()
                .map(entity -> entity.position().add(0, entity.getBbHeight() * 0.8, 0))
                .map(pos -> pos.subtract(position()))
                .min(Comparator.comparing(Vec3::lengthSqr))
                .map(Vec3::normalize)
                .map(direction -> direction.multiply(1, 0.5, 1))
                .map(direction -> direction.scale(Math.max(getDeltaMovement().length() * 0.5, 0.3)))
                .orElse(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D)));
    }
}

    public static void SpecialDeath(LivingDeathEvent event){
        LivingEntity killed = event.getEntity();
        Entity killer = event.getSource().getEntity();
        Level world = killed.getCommandSenderWorld();
        if (killed instanceof PathfinderMob){
            if (killed.hasEffect(GoetyEffects.GOLD_TOUCHED.get())){
                if (world.getGameRules().getBoolean(GameRules.RULE_DOMOBLOOT)) {
                    int amp = Objects.requireNonNull(killed.getEffect(GoetyEffects.GOLD_TOUCHED.get())).getAmplifier() + 1;
                    for (int i = 0; i < (killed.level.random.nextInt(3) + 1) * amp; ++i) {
                        killed.spawnAtLocation(new ItemStack(Items.GOLD_NUGGET));
                    }
                }
            }
        }
        if (world instanceof ServerLevel serverLevel) {
            if (killed instanceof AbstractIllager illager){
                if (!illager.getType().getDescriptionId().contains("magispeller")
                        && !illager.getType().getDescriptionId().contains("faker")
                        && !illager.getType().getDescriptionId().contains("freakager")
                        && !illager.getType().getDescriptionId().contains("spiritcaller")) {
                    for (Apostle apostle : world.getEntitiesOfClass(Apostle.class, illager.getBoundingBox().inflate(32))) {
                        if (apostle.hasLineOfSight(illager)) {
                            Damned damned = new Damned(ModEntityType.DAMNED.get(), world);
                            damned.moveTo(illager.blockPosition().below(2), apostle.getYHeadRot(), apostle.getXRot());
                            damned.setTrueOwner(apostle);
                            damned.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(illager.blockPosition().below()), MobSpawnType.MOB_SUMMONED, null, null);
                            if (illager.hasCustomName()){
                                damned.setCustomName(illager.getCustomName());
                            }
                            damned.setHuman(false);
                            if (apostle.getTarget() != null) {
                                damned.setTarget(apostle.getTarget());
                            }
                            damned.setLimitedLife(100);
                            ServerParticleUtil.addParticlesAroundSelf(serverLevel, ModParticleTypes.BIG_FIRE.get(), damned);
                            world.addFreshEntity(damned);
                        }
                    }
                }
            }
        }
        if (killer instanceof Player player){
            if (world.getGameRules().getBoolean(GameRules.RULE_DOMOBLOOT)){
                Entity entity = event.getSource().getDirectEntity();
                if (entity instanceof Fangs){
                    if (CuriosFinder.findRing(player).getItem() == ModItems.RING_OF_WANT.get()) {
                        int enchantment = EnchantmentHelper.getTagEnchantmentLevel(ModEnchantments.WANTING.get(), CuriosFinder.findRing(player));
                        if (enchantment >= 3) {
                            if (world.random.nextFloat() <= (enchantment / 9.0F)) {
                                if (killed.getType() == EntityType.SKELETON) {
                                    killed.spawnAtLocation(new ItemStack(Items.SKELETON_SKULL));
                                }
                                if (killed.getType() == EntityType.ZOMBIE) {
                                    killed.spawnAtLocation(new ItemStack(Items.ZOMBIE_HEAD));
                                }
                                if (killed.getType() == EntityType.CREEPER) {
                                    killed.spawnAtLocation(new ItemStack(Items.CREEPER_HEAD));
                                }
                                if (killed.getType() == EntityType.WITHER_SKELETON) {
                                    killed.spawnAtLocation(new ItemStack(Items.WITHER_SKELETON_SKULL));
                                }
                                if (killed.getType() == EntityType.PIGLIN) {
                                    killed.spawnAtLocation(new ItemStack(Items.PIGLIN_HEAD));
                                }
                                if (MobsConfig.TallSkullDrops.get()) {
                                    if (killed.getType().is(ModTags.EntityTypes.TALL_HEAD) || killed instanceof Villager || killed instanceof AbstractIllager || killed instanceof Witch || (killed instanceof Cultist && killed.getType() != ModEntityType.APOSTLE.get())) {
                                        killed.spawnAtLocation(new ItemStack(ModBlocks.TALL_SKULL_ITEM.get()));
                                    }
                                }
                            }
                            if (killed instanceof Player player1) {
                                CompoundTag tag = new CompoundTag();
                                tag.putString("SkullOwner", player1.getDisplayName().getString());
                                ItemStack head = new ItemStack(Items.PLAYER_HEAD);
                                head.setTag(tag);
                                killed.spawnAtLocation(head);
                            }
                        }
                    }
                }
                if (killed.getType() == EntityType.SPIDER){
                    if (CuriosFinder.hasCurio(player, itemStack -> itemStack.getItem() instanceof WarlockGarmentItem)){
                        if (world.random.nextFloat() <= 0.075F){
                            for (int i = 0; i < (world.random.nextInt(2) + 1); ++i) {
                                killed.spawnAtLocation(new ItemStack(ModItems.SPIDER_EGG.get()));
                            }
                        }
                    }
                }
            }
        }
        if (killer instanceof WitherNecromancer necromancer){
            MobUtil.createWitherRose(killed, necromancer);
        }
/*        if (killer instanceof LivingEntity livingEntity){
            net.minecraft.network.chat.Component deathMessage = killed.getCombatTracker().getDeathMessage();
            livingEntity.sendSystemMessage(deathMessage);
        }*/
        if (!event.isCanceled()){
            MiscCapHelper.setFreezing(killed, 0);
            MiscCapHelper.setShields(killed, 0);
            MiscCapHelper.setShieldTime(killed, 0);
            MiscCapHelper.setShakeTime(killed, 0);
        }
    }

public void tick() {
    super.tick();
    prevBaskProgress = baskProgress;
    prevDigProgress = digProgress;
    prevBobbingProgress = bobbingProgress;
    prevSwimAngle = this.getSwimAngle();
    boolean dig = isDigging() && isInWaterOrBubble();
    float f2 = (float) -((float) this.getDeltaMovement().y * (double) Mth.RAD_TO_DEG);
    if (isInWater()) {
        this.setXRot(f2 * 2.5F);

        if (this.isLandNavigator)
            switchNavigator(false);
    } else {
        if (!this.isLandNavigator)
            switchNavigator(true);
    }

    if (isBasking()) {
        if (baskProgress < 5F)
            baskProgress++;
    } else {
        if (baskProgress > 0F)
            baskProgress--;
    }

    if (dig) {
        if (digProgress < 5F)
            digProgress++;
    } else {
        if (digProgress > 0F)
            digProgress--;
    }

    if (dig && level().getBlockState(this.getBlockPosBelowThatAffectsMyMovement()).canOcclude()) {
        BlockPos posit = this.getBlockPosBelowThatAffectsMyMovement();
        BlockState understate = level().getBlockState(posit);
        for (int i = 0; i < 4 + random.nextInt(2); i++) {
            double particleX = posit.getX() + random.nextFloat();
            double particleY = posit.getY() + 1F;
            double particleZ = posit.getZ() + random.nextFloat();
            double motX = this.random.nextGaussian() * 0.02D;
            double motY = 0.1F + random.nextFloat() * 0.2F;
            double motZ = this.random.nextGaussian() * 0.02D;
            level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, understate), particleX, particleY, particleZ, motX, motY, motZ);
        }
    }
    if (!this.level().isClientSide) {
        if (isBasking()) {
            if (this.getLastHurtByMob() != null || isInLove() || revengeCooldown > 0 || this.isInWaterOrBubble() || this.getTarget() != null || baskingTimer > 1000 && this.getRandom().nextInt(100) == 0) {
                this.setBasking(false);
            }
        } else {
            if (this.getTarget() == null && !isInLove() && this.getLastHurtByMob() == null && revengeCooldown == 0 && !isBasking() && baskingTimer == 0 && this.getRandom().nextInt(15) == 0) {
                if (!isInWaterOrBubble()) {
                    this.setBasking(true);
                }
            }
        }
        if (revengeCooldown > 0) {
            revengeCooldown--;
        }
        if (revengeCooldown == 0 && this.getLastHurtByMob() != null) {
            this.setLastHurtByMob(null);
        }
        float threshold = 0.05F;
        if (isInWater() && this.yRotO - this.getYRot() > threshold) {
            this.setSwimAngle(this.getSwimAngle() + 2);
        } else if (isInWater() && this.yRotO - this.getYRot() < -threshold) {
            this.setSwimAngle(this.getSwimAngle() - 2);
        } else if (this.getSwimAngle() > 0) {
            this.setSwimAngle(Math.max(this.getSwimAngle() - 10, 0));
        } else if (this.getSwimAngle() < 0) {
            this.setSwimAngle(Math.min(this.getSwimAngle() + 10, 0));
        }
        this.setSwimAngle(Mth.clamp(this.getSwimAngle(), -70, 70));
        if (isBasking()) {
            baskingTimer++;
        } else {
            baskingTimer = 0;
        }
        if (isInWater()) {
            swimTimer++;
            ticksSinceInWater = 0;
        } else {
            ticksSinceInWater++;
            swimTimer--;
        }
    }
    int bob = this.entityData.get(BOB_TICKS);
    if(bob > 0){
        bob--;
        if(this.bobbingProgress < 5F){
            this.bobbingProgress++;
        }
        this.entityData.set(BOB_TICKS, bob);
    }else{
        if(this.bobbingProgress > 0F){
            this.bobbingProgress--;
        }
        if(!this.level().isClientSide && random.nextInt(300) == 0 && !this.isInWater() && this.revengeCooldown == 0){
            bob = 20 + random.nextInt(20);
            this.entityData.set(BOB_TICKS, bob);
        }
    }
}

public @NotNull InteractionResult mobInteract(Player player, InteractionHand hand) {
    ItemStack stack = player.getItemInHand(hand);
    if (stack.isEmpty()) {
        return InteractionResult.PASS;
    }
    if (isWeak() && (aiTameType() == Taming.GEM && stack.is(ModItems.SCARAB_GEM.get()) || aiTameType() == Taming.AQUATIC_GEM && stack.is(ModItems.AQUATIC_SCARAB_GEM.get()))) {
        //Tame with gem
        if (!level.isClientSide) {
            ModTriggers.SCARAB_TAME_TRIGGER.trigger((ServerPlayer) player);
            heal(200);
            moodSystem.setMood(100);
            feed(500);
            getNavigation().stop();
            setTarget(null);
            setLastHurtByMob(null);
            tame(player);
            level.broadcastEntityEvent(this, TOTEM_PARTICLES);
            stack.shrink(1);
        }
        return InteractionResult.sidedSuccess(level.isClientSide);
    } else if (stack.is(ModItems.CHICKEN_ESSENCE.get()) && aiTameType() != Taming.GEM && aiTameType() != Taming.AQUATIC_GEM) {
        //Grow up with chicken essence
        if (!level.isClientSide) {
            if (isAdult()) {
                player.displayClientMessage(new TranslatableComponent("prehistoric.essence_fail_adult"), true);
                return InteractionResult.PASS;
            }
            if (isDeadlyHungry()) {
                player.displayClientMessage(new TranslatableComponent("prehistoric.essence_fail_hungry"), true);
                return InteractionResult.PASS;
            }
            if (!player.getAbilities().instabuild) {
                stack.shrink(1);
                player.addItem(new ItemStack(Items.GLASS_BOTTLE, 1));
            }
            grow(1);
            setHunger(1 + random.nextInt(getHunger()));
        }
        return InteractionResult.sidedSuccess(level.isClientSide);
    } else if (stack.is(ModItems.STUNTED_ESSENCE.get()) && !isAgingDisabled()) {
        //Stunt growth with stunted essence
        if (!level.isClientSide) {
            setHunger(getHunger() + 20);
            heal(getMaxHealth());
            setAgingDisabled(true);
            stack.shrink(1);
            playSound(SoundEvents.ZOMBIE_VILLAGER_CURE, getSoundVolume(), getVoicePitch());
        } else {
            AABB aabb = eatPos == null ? getBoundingBoxForCulling() : new AABB(eatPos, eatPos);
            Util.spawnItemParticles(level, stack.getItem(), 15, aabb);
            Util.spawnItemParticles(level, stack.getItem(), 15, aabb);
            Util.spawnItemParticles(level, Items.POISONOUS_POTATO, 15, aabb);
            Util.spawnItemParticles(level, Items.POISONOUS_POTATO, 15, aabb);
            Util.spawnItemParticles(level, Items.EGG, 15, aabb);
        }
        return InteractionResult.sidedSuccess(level.isClientSide);
    } else if (FoodMappings.getFoodAmount(stack.getItem(), data().diet()) > 0) {
        //Feed dino
        if (getHunger() < getMaxHunger() || getHealth() < getMaxHealth() && FossilConfig.isEnabled(FossilConfig.HEALING_DINOS) || !isTame() && aiTameType() == Taming.FEEDING) {
            if (!level.isClientSide && eatItem(stack)) {
                if (FossilConfig.isEnabled(FossilConfig.HEALING_DINOS)) {
                    heal(3);
                }
                if (getHunger() >= getMaxHunger() && isTame()) {
                    player.displayClientMessage(new TranslatableComponent("entity.fossil.situation.full", getName()), true);
                }
                if (aiTameType() == Taming.FEEDING && !isTame() && random.nextInt(10) == 1) {
                    tame(player);
                    level.broadcastEntityEvent(this, TOTEM_PARTICLES);
                }
            }
            return InteractionResult.sidedSuccess(level.isClientSide);
        }
    } else if (stack.is(ModItems.WHIP.get()) && aiTameType() != Taming.NONE && isAdult()) {
        if (isOwnedBy(player) && data().canBeRidden()) {
            if (!level.isClientSide && getRidingPlayer() == null) {
                player.yBodyRot = this.yBodyRot;
                player.setXRot(getXRot());
                player.startRiding(this);
                sitSystem.setSitting(false);
                sleepSystem.setSleeping(false);
                setCurrentOrder(OrderType.WANDER);
            } else if (getRidingPlayer() == player) {
                setSprinting(true);//TODO: Not needed
                moodSystem.increaseMood(-5);
            }
        } else if (FossilConfig.isEnabled(FossilConfig.WHIP_TO_TAME_DINO) && !isTame() && aiTameType() != Taming.AQUATIC_GEM && aiTameType() != Taming.GEM) {
            if (!level.isClientSide) {
                moodSystem.increaseMood(-5);
                if (random.nextInt(5) == 0) {
                    player.displayClientMessage(new TranslatableComponent("entity.fossil.prehistoric.tamed", info().displayName.get()), true);
                    moodSystem.increaseMood(-25);
                    tame(player);
                }
            }
        }
        return InteractionResult.sidedSuccess(level.isClientSide);
    } else if (stack.is(getOrderItem()) && isOwnedBy(player) && !player.isPassenger()) {
        if (!level.isClientSide) {
            jumping = false;
            getNavigation().stop();
            setCurrentOrder(OrderType.values()[(getCurrentOrder().ordinal() + 1) % 3]);
            sendOrderMessage(getCurrentOrder());
        }
        return InteractionResult.sidedSuccess(level.isClientSide);
    }
    return InteractionResult.PASS;
}

public void tick() {
    super.tick();
    float boardRot = this.getBoardRot();
    if(jumpFor > 0){
        jumpFor--;
    }
    if (this.getTimeSinceHit() > 0) {
        this.setTimeSinceHit(this.getTimeSinceHit() - 1);
    }
    if (extinguishTimer > 0) {
        extinguishTimer--;
    }
    if (this.entityData.get(REMOVE_SOON)) {
        this.removeIn--;
        this.setBoardRot((float) Math.sin(this.removeIn * 0.3F * Math.PI) * 50F);
        if (this.removeIn <= 0 && !this.level().isClientSide) {
            this.removeIn = 0;
            boolean drop;
            if(this.getEnchant(AMEnchantmentRegistry.STRADDLE_BOARDRETURN.get()) > 0){
                drop = returnToPlayer != null && !returnToPlayer.addItem(this.getItemBoard());
            }else{
                drop = true;
            }
            if(drop){
                spawnAtLocation(this.getItemStack().copy());
            }
            this.discard();
        }
    }
    Entity controller = getControllingPlayer();
    if (this.level().isClientSide) {
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY())  / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
            this.setRot(this.getYRot(), this.getXRot());
        } else {
            this.reapplyPosition();
            this.setRot(this.getYRot(), this.getXRot());
        }
    } else {
        this.checkInsideBlocks();
        float slowdown = this.isInWaterOrBubble() || onGround() ? 0.05F : 0.98F;
        tickMovement();
        this.move(MoverType.SELF, this.getDeltaMovement());
        this.setDeltaMovement(this.getDeltaMovement().multiply(slowdown, slowdown, slowdown));
        float f2 = (float) -((float) this.getDeltaMovement().y * 0.5F * (double) Mth.RAD_TO_DEG);
        this.setXRot(Mth.approachDegrees(this.getXRot(), f2, 5));

        if (controller instanceof Player player) {
            returnToPlayer = player;
            rideForTicks++;
            if (this.tickCount % 50 == 0) {
                if (getEnchant(AMEnchantmentRegistry.STRADDLE_LAVAWAX.get()) > 0) {
                    player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 100, 0, true, false));
                }
            }
            if (player.getRemainingFireTicks() > 0 && extinguishTimer == 0) {
                player.clearFire();
            }
            this.setYRot(Mth.approachDegrees(this.getYRot(), player.getYRot(), 6));
            Vec3 deltaMovement = this.getDeltaMovement();
            if (deltaMovement.y > -0.5D) {
                this.fallDistance = 1.0F;
            }

            float slow = player.zza < 0 ? 0 : player.zza * 0.115F;

            float threshold = 3F;
            boolean flag = false;
            float boardRot1 = boardRot;
            if (this.yRotO - this.getYRot() > threshold) {
                boardRot1 += 10;
                flag = true;
            }
            if (this.yRotO - this.getYRot() < -threshold) {
                boardRot1 -= 10;
                flag = true;
            }
            if (!flag) {
                if (boardRot1 > 0) {
                    boardRot1 = Math.max(boardRot1 - 5, 0);
                }
                if (boardRot1 < 0) {
                    boardRot1 = Math.min(boardRot1 + 5, 0);
                }
            }

            this.setBoardRot(Mth.approachDegrees(boardRot, Mth.clamp(boardRot1, -25, 25), 5));

            boardForwards = slow;

            if(player.isShiftKeyDown() || !this.isAlive() || this.entityData.get(REMOVE_SOON)){
                this.ejectPassengers();
            }
            if (player.isInWall()) {
                this.ejectPassengers();
                this.hurt(damageSources().generic(), 100);
            }
        }else{
            rideForTicks = 0;
        }
    }
    prevBoardRot = boardRot;
}

public void tick() {
    super.tick();
    this.prevFlyProgress = flyProgress;
    this.prevFlapAmount = flapAmount;
    this.prevAttackProgress = attackProgress;
    this.prevSitProgress = sitProgress;
    final float yMot = (float) -((float) this.getDeltaMovement().y * (double) Mth.RAD_TO_DEG);
    final float absYaw = Math.abs(this.getYRot() - this.yRotO);

    final boolean flying = isFlying();
    final boolean sitting = isSitting();

    if (flying) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (sitting) {
        if (sitProgress < 5F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (absYaw > 8) {
        flapAmount = Math.min(1F, flapAmount + 0.1F);
    } else if (yMot < 0.0F) {
        flapAmount = Math.min(-yMot * 0.2F, 1F);
    } else {
        if (flapAmount > 0.0F) {
            flapAmount -= Math.min(flapAmount, 0.05F);
        } else {
            flapAmount = 0;
        }
    }
    if (this.entityData.get(ATTACK_TICK) > 0) {
        this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
        if (attackProgress < 5F) {
            attackProgress++;
        }
    } else {
        if (attackProgress > 0F) {
            attackProgress--;
        }
    }
    if (!this.level().isClientSide) {
        if (isFlying()) {
            float lookYawDist = Math.abs(this.getFlightLookYaw() - targetFlightLookYaw);
            if (flightLookCooldown > 0) {
                flightLookCooldown--;
            }
            if (flightLookCooldown == 0 && this.random.nextInt(4) == 0 && lookYawDist < 0.5F) {
                targetFlightLookYaw = Mth.clamp(random.nextFloat() * 120F - 60, -60, 60);
                flightLookCooldown = 3 + random.nextInt(15);
            }
            if (this.getFlightLookYaw() < this.targetFlightLookYaw && lookYawDist > 0.5F) {
                this.setFlightLookYaw(this.getFlightLookYaw() + Math.min(lookYawDist, 4F));
            }
            if (this.getFlightLookYaw() > this.targetFlightLookYaw && lookYawDist > 0.5F) {
                this.setFlightLookYaw(this.getFlightLookYaw() - Math.min(lookYawDist, 4F));
            }
            if (this.onGround() && !this.isInWaterOrBubble() && this.timeFlying > 30) {
                this.setFlying(false);
            }
            timeFlying++;
            this.setNoGravity(true);
            if (this.isPassenger() || this.isInLove()) {
                this.setFlying(false);
            }
        } else {
            fallFlag = false;
            timeFlying = 0;
            this.setNoGravity(false);
        }
        if (isFlying() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!isFlying() && !this.isLandNavigator) {
            switchNavigator(true);
        }
    }
    if (!this.getMainHandItem().isEmpty()) {
        heldItemTime++;
        if (heldItemTime > 200 && canTargetItem(this.getMainHandItem())) {
            heldItemTime = 0;
            this.heal(4);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            if (this.getMainHandItem().hasCraftingRemainingItem()) {
                this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
            }
            eatItemEffect(this.getMainHandItem());
            this.getMainHandItem().shrink(1);
        }
    } else {
        heldItemTime = 0;
    }
    if (stealCooldown > 0) {
        stealCooldown--;
    }
    if(treasureSitTime > 0){
        treasureSitTime--;
    }
    if(this.isSitting() && this.isInWaterOrBubble()){
        this.setDeltaMovement(this.getDeltaMovement().add(0, 0.02F, 0));
    }
}

public InteractionResult mobInteract(@Nonnull Player player, @Nonnull InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    Item item = itemstack.getItem();
    MimicState readState = getStateForItem(itemstack);
    InteractionResult type = super.mobInteract(player, hand);
    if (readState != null && this.isTame()) {
        if (mimicCooldown == 0) {
            this.setMimicState(readState);
            mimicCooldown = 20;
            stopMimicCooldown = isUpgraded() ? 120 : 1200;
            camoCooldown = stopMimicCooldown;
            this.setMimickedBlock(null);
        }
        return InteractionResult.SUCCESS;
    }
    final boolean tame = isTame();
    if (tame && itemstack.is(AMTagRegistry.MIMIC_OCTOPUS_TOGGLES_MIMIC)) {
        this.setStopChange(!this.isStopChange());
        if (this.isStopChange()) {
            this.makeEatingParticles(itemstack);
        } else {
            this.level().broadcastEntityEvent(this, (byte) 6);
            this.mimicEnvironment();
        }
        return InteractionResult.SUCCESS;
    }
    if (!tame && itemstack.is(AMTagRegistry.MIMIC_OCTOPUS_TAMEABLES)) {
        this.usePlayerItem(player, hand, itemstack);
        this.gameEvent(GameEvent.EAT);
        this.playSound(SoundEvents.DOLPHIN_EAT, this.getSoundVolume(), this.getVoicePitch());
        fishFeedings++;
        if (this.getMimicState() == MimicState.OVERLAY && this.getMimickedBlock() == null) {
            if (fishFeedings > 5 && getRandom().nextInt(2) == 0 || fishFeedings > 8) {
                this.tame(player);
                this.level().broadcastEntityEvent(this, (byte) 7);
            } else {
                this.level().broadcastEntityEvent(this, (byte) 6);
            }
        }
        return InteractionResult.SUCCESS;
    }
    if (tame && itemstack.is(AMTagRegistry.MIMIC_OCTOPUS_TAMEABLES)) {
        if (this.getHealth() < this.getMaxHealth()) {
            this.usePlayerItem(player, hand, itemstack);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.DOLPHIN_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.heal(5);
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.PASS;
    }
    if (tame) {
        Optional<InteractionResult> result = Bucketable.bucketMobPickup(player, hand, this);
        if (result.isPresent()) {
            return result.get();
        }

        if (itemstack.is(AMTagRegistry.MIMIC_OCTOPUS_MOISTURIZES) && this.getMoistness() < 24000) {
            this.setMoistness(48000);
            this.makeEatingParticles(itemstack);
            this.usePlayerItem(player, hand, itemstack);
            return InteractionResult.SUCCESS;
        }

        if (!this.isUpgraded() && itemstack.is(AMTagRegistry.MIMIC_OCTOPUS_ATTACK_FOODS)) {
            mimicreamFeedings++;
            if (mimicreamFeedings > 5 || mimicreamFeedings > 2 && random.nextInt(2) == 0) {
                this.level().broadcastEntityEvent(this, (byte) 46);
                this.setUpgraded(true);
                this.setMimicState(MimicState.MIMICUBE);
                this.setStopChange(false);
                this.setMimickedBlock(null);
                this.stopMimicCooldown = 40;
            }
            this.makeEatingParticles(itemstack);
            this.usePlayerItem(player, hand, itemstack);
            return InteractionResult.SUCCESS;
        }
    }

    InteractionResult interactionresult = itemstack.interactLivingEntity(player, this, hand);
    if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS && isTame() && isOwnedBy(player)) {
        if (player.isShiftKeyDown()) {
            if (this.getMainHandItem().isEmpty()) {
                ItemStack cop = itemstack.copy();
                cop.setCount(1);
                this.setItemInHand(InteractionHand.MAIN_HAND, cop);
                itemstack.shrink(1);
                return InteractionResult.SUCCESS;
            } else {
                this.spawnAtLocation(this.getMainHandItem().copy());
                this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                return InteractionResult.SUCCESS;
            }
        } else if (!isFood(itemstack)) {
            this.setCommand(this.getCommand() + 1);
            if (this.getCommand() == 3) {
                this.setCommand(0);
            }
            player.displayClientMessage(Component.translatable("entity.alexsmobs.all.command_" + this.getCommand(), this.getName()), true);
            boolean sit = this.getCommand() == 2;
            if (sit) {
                this.setOrderedToSit(true);
                return InteractionResult.SUCCESS;
            } else {
                this.setOrderedToSit(false);
                return InteractionResult.SUCCESS;
            }
        }
    }
    return type;
}

public void aiStep() {
    super.aiStep();
    yBodyRot = getYRot();

    LivingEntity attackTarget = this.getTarget();
    if (singCooldown > 0) {
        singCooldown--;
        this.setSinging(false);
    }
    if (!level.isClientSide && attackTarget == null && !this.isAgressive()) {
        this.setSinging(true);
    }
    if (this.getAnimation() == ANIMATION_BITE && attackTarget != null && this.distanceToSqr(attackTarget) < 7D && this.getAnimationTick() == 5) {
        attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
    }
    if (this.getAnimation() == ANIMATION_PULL && attackTarget != null && this.distanceToSqr(attackTarget) < 16D && this.getAnimationTick() == 5) {
        attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
        double attackmotionX = (Math.signum(this.getX() - attackTarget.getX()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;
        double attackmotionY = (Math.signum(this.getY() - attackTarget.getY() + 1) * 0.5D - attackTarget.getDeltaMovement().y) * 0.100000000372529 * 5;
        double attackmotionZ = (Math.signum(this.getZ() - attackTarget.getZ()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;

        attackTarget.setDeltaMovement(attackTarget.getDeltaMovement().add(attackmotionX, attackmotionY, attackmotionZ));
        // float angle = (float) (Math.atan2(attackTarget.getDeltaMovement().z, attackTarget.getDeltaMovement().x) * 180.0D / Math.PI) - 90.0F;
        // entity.moveForward = 0.5F;
        double d0 = this.getX() - attackTarget.getX();
        double d2 = this.getZ() - attackTarget.getZ();
        double d1 = this.getY() - 1 - attackTarget.getY();
        double d3 = Math.sqrt((float) (d0 * d0 + d2 * d2));
        float f = (float) (Mth.atan2(d2, d0) * (180D / Math.PI)) - 90.0F;
        float f1 = (float) (-(Mth.atan2(d1, d3) * (180D / Math.PI)));
        attackTarget.setXRot(updateRotation(attackTarget.getXRot(), f1, 30F));
        attackTarget.setYRot(updateRotation(attackTarget.getYRot(), f, 30F));
    }
    if (level.isClientSide) {
        tail_buffer.calculateChainSwingBuffer(40, 10, 2.5F, this);
    }
    if (this.isAgressive()) {
        ticksAgressive++;
    } else {
        ticksAgressive = 0;
    }
    if (ticksAgressive > 300 && this.isAgressive() && attackTarget == null && !level.isClientSide) {
        this.setAggressive(false);
        this.ticksAgressive = 0;
        this.setSinging(false);
    }

    if (this.isInWater() && !this.isSwimming()) {
        this.setSwimming(true);
    }
    if (!this.isInWater() && this.isSwimming()) {
        this.setSwimming(false);
    }
    LivingEntity target = getTarget();
    boolean pathOnHighGround = this.isPathOnHighGround() || !level.isClientSide && target != null && !target.isInWater();
    if (target == null || !target.isInWater() && !target.isInWater()) {
        if (pathOnHighGround && this.isInWater()) {
            jumpFromGround();
            doWaterSplashEffect();
        }
    }
    if ((this.isInWater() && !pathOnHighGround) && this.isLandNavigator) {
        switchNavigator(false);
    }
    if ((!this.isInWater() || pathOnHighGround) && !this.isLandNavigator) {
        switchNavigator(true);
    }
    if (target instanceof Player && ((Player) target).isCreative()) {
        this.setTarget(null);
        this.setAggressive(false);
    }
    if (target != null && !this.isAgressive()) {
        this.setAggressive(true);
    }
    boolean singing = isActuallySinging() && !this.isAgressive() && !this.isInWater() && onGround;
    if (singing && singProgress < 20.0F) {
        singProgress += 1F;
    } else if (!singing && singProgress > 0.0F) {
        singProgress -= 1F;
    }
    boolean swimming = isSwimming();
    if (swimming && swimProgress < 20.0F) {
        swimProgress += 1F;
    } else if (!swimming && swimProgress > 0.0F) {
        swimProgress -= 0.5F;
    }
    if (!level.isClientSide && !EntityGorgon.isStoneMob(this) && this.isActuallySinging()) {
        updateLure();
        checkForPrey();

    }
    if (!level.isClientSide && EntityGorgon.isStoneMob(this) && this.isSinging()) {
        this.setSinging(false);
    }
    if (isActuallySinging() && !this.isInWater()) {
        if (this.getRandom().nextInt(3) == 0) {
            yBodyRot = getYRot();
            if (this.level.isClientSide) {
                float radius = -0.9F;
                float angle = (0.01745329251F * this.yBodyRot) - 3F;
                double extraX = radius * Mth.sin((float) (Math.PI + angle));
                double extraY = 1.2F;
                double extraZ = radius * Mth.cos(angle);
                IceAndFire.PROXY.spawnParticle(EnumParticles.Siren_Music, this.getX() + extraX + this.random.nextFloat() - 0.5, this.getY() + extraY + this.random.nextFloat() - 0.5, this.getZ() + extraZ + this.random.nextFloat() - 0.5, 0, 0, 0);
            }
        }
    }
    if (this.isActuallySinging() && !this.isInWater() && this.tickCount % 200 == 0) {
        this.playSound(IafSoundRegistry.SIREN_SONG, 2, 1);
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public static void LightningStruckEvent(EntityStruckByLightningEvent event){
    Entity entity = event.getEntity();
    Level level = entity.level;
    if (level instanceof ServerLevel serverLevel) {
        if (entity instanceof Mob mob) {
            if (mob.getType().is(ModTags.EntityTypes.FRAYED_CONVERT)) {
                if (MobsConfig.ZombieConvertFrayed.get()) {
                    EntityType<?> entityType = ModEntityType.FRAYED.get();
                    boolean servant = mob instanceof OwnableEntity;
                    if (event.getLightning().getCause() != null) {
                        if (CuriosFinder.hasNamelessSet(event.getLightning().getCause())) {
                            servant = true;
                        }
                    }
                    if (servant) {
                        entityType = ModEntityType.FRAYED_SERVANT.get();
                    }
                    Entity newMob = MobUtil.convertTo(mob, entityType, true, null);
                    if (newMob != null) {
                        if (newMob instanceof IServant servant2) {
                            if (event.getLightning().getCause() != null && CuriosFinder.hasNamelessSet(event.getLightning().getCause())) {
                                servant2.setTrueOwner(event.getLightning().getCause());
                            } else if (MobUtil.getOwner(mob) != null) {
                                servant2.setTrueOwner(MobUtil.getOwner(mob));
                            }
                            if (mob instanceof IServant servant1) {
                                servant2.copyStance(servant1);
                                servant2.setHostile(servant1.isHostile());
                                servant2.setNatural(servant1.isNatural());
                            }
                        }
                    }
                }
            }
            if (mob.getType().is(ModTags.EntityTypes.RATTLED_CONVERT)) {
                if (MobsConfig.SkeletonConvertRattled.get()) {
                    EntityType<?> entityType = ModEntityType.RATTLED.get();
                    boolean servant = mob instanceof OwnableEntity;
                    if (event.getLightning().getCause() != null) {
                        if (CuriosFinder.hasNamelessSet(event.getLightning().getCause())) {
                            servant = true;
                        }
                    }
                    if (servant) {
                        entityType = ModEntityType.RATTLED_SERVANT.get();
                    }
                    Entity newMob = MobUtil.convertTo(mob, entityType, true, null);
                    if (newMob != null) {
                        if (newMob instanceof IServant servant2) {
                            if (event.getLightning().getCause() != null && CuriosFinder.hasNamelessSet(event.getLightning().getCause())) {
                                servant2.setTrueOwner(event.getLightning().getCause());
                            } else if (MobUtil.getOwner(mob) != null) {
                                servant2.setTrueOwner(MobUtil.getOwner(mob));
                            }
                            if (mob instanceof IServant servant1) {
                                servant2.copyStance(servant1);
                                servant2.setHostile(servant1.isHostile());
                                servant2.setNatural(servant1.isNatural());
                            }
                        }
                    }
                }
            }
        }
        if (entity instanceof WanderingTrader trader) {
            boolean hasConverted = false;
            if (event.getLightning().getCause() != null) {
                if (CuriosFinder.hasUnholySet(event.getLightning().getCause()) && MobsConfig.TraderConvertReprobateUnholy.get()) {
                    ReprobateServant reprobate = ModEntityType.REPROBATE_SERVANT.get().create(serverLevel);
                    if (reprobate != null) {
                        reprobate.moveTo(trader.getX(), trader.getY(), trader.getZ(), trader.getYRot(), trader.getXRot());
                        reprobate.setTrueOwner(event.getLightning().getCause());
                        reprobate.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(reprobate.blockPosition()), MobSpawnType.CONVERSION, (SpawnGroupData) null, (CompoundTag) null);
                        reprobate.setNoAi(trader.isNoAi());
                        if (trader.hasCustomName()) {
                            reprobate.setCustomName(trader.getCustomName());
                            reprobate.setCustomNameVisible(trader.isCustomNameVisible());
                        }

                        reprobate.setPersistenceRequired();
                        net.minecraftforge.event.ForgeEventFactory.onLivingConvert(trader, reprobate);
                        serverLevel.addFreshEntityWithPassengers(reprobate);
                        hasConverted = true;
                        trader.discard();
                    }
                }
            }
            if (!hasConverted) {
                if (MobsConfig.TraderConvertReprobate.get()) {
                    if (serverLevel.getDifficulty() != Difficulty.PEACEFUL && net.minecraftforge.event.ForgeEventFactory.canLivingConvert(trader, ModEntityType.MAVERICK.get(), (timer) -> {
                    })) {
                        Reprobate reprobate = ModEntityType.REPROBATE.get().create(serverLevel);
                        if (reprobate != null) {
                            reprobate.moveTo(trader.getX(), trader.getY(), trader.getZ(), trader.getYRot(), trader.getXRot());
                            reprobate.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(reprobate.blockPosition()), MobSpawnType.CONVERSION, (SpawnGroupData) null, (CompoundTag) null);
                            reprobate.setNoAi(trader.isNoAi());
                            if (trader.hasCustomName()) {
                                reprobate.setCustomName(trader.getCustomName());
                                reprobate.setCustomNameVisible(trader.isCustomNameVisible());
                            }

                            reprobate.setPersistenceRequired();
                            net.minecraftforge.event.ForgeEventFactory.onLivingConvert(trader, reprobate);
                            serverLevel.addFreshEntityWithPassengers(reprobate);
                            trader.discard();
                        }
                    }
                }
            }
        }
    }
}

public void onUpdate() {
	super.onUpdate();

	if(!this.world.isRemote) {
		if(this.source == null) {
			this.setDead();
		} else {
			Entity shootingEntity;
			DamageSource damageSource;

			if(this.source instanceof EntityBLArrow) {
				shootingEntity = ((EntityBLArrow) this.source).getThrower();

				if(shootingEntity != null) {
					damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, shootingEntity);
				} else {
					damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, (EntityBLArrow) this.source);
				}
			} else if(this.source instanceof EntityLivingBase) {
				shootingEntity = null;
				damageSource = DamageSource.causeMobDamage((EntityLivingBase) this.source);
			} else {
				shootingEntity = null;
				damageSource = DamageSource.GENERIC;
			}

			List<Pair<Entity, Entity>> chain = new ArrayList<>();

			if(this.jumps < this.maxJumps) {
				if(this.ticksExisted != 0 && this.ticksExisted % 3 == 0) {
					Set<EntityLivingBase> newTargets = new HashSet<>();

					entityLoop: for(Entity entity : this.targets) {
						boolean isWet = entity.isWet() || entity.isInWater() || this.world.isRainingAt(entity.getPosition().up());

						List<EntityLivingBase> entities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, entity.getEntityBoundingBox().grow(isWet ? 6 : 4), e -> {
							Entity riding = e.getLowestRidingEntity();

							//Passengers are handled further down
							if(riding != e && riding instanceof EntityLivingBase) {
								return false;
							}

							return true;	
						});

						if(entities.size() > 1) {
							Collections.sort(entities, (e1, e2) -> Double.compare(e1.getDistanceSq(entity), e2.getDistanceSq(entity)));

							for(int j = 1; j < entities.size(); j++) {
								EntityLivingBase newTarget = entities.get(j);

								if(!this.targets.contains(newTarget) && !newTargets.contains(newTarget)) {
									newTargets.add(newTarget);

									chain.add(Pair.of(entity, newTarget));

									float f = MathHelper.sqrt(this.source.motionX * this.source.motionX + this.source.motionY * this.source.motionY + this.source.motionZ * this.source.motionZ);

									float damage = this.damage;
									if(this.source instanceof EntityBLArrow) {
										damage = MathHelper.ceil((double)f * ((EntityBLArrow) this.source).getDamage());

										if (((EntityBLArrow) this.source).getIsCritical()) {
											damage += this.rand.nextInt((int)damage / 2 + 2);
										}
									}

									boolean blocked = false;

									for(ItemStack stack : newTarget.getEquipmentAndArmor()) {
										if(!stack.isEmpty() && stack.getItem() instanceof ItemRubberBoots) {
											stack.damageItem(2, newTarget);
											blocked = true;
										}
									}

									boolean wasShocked = false;

									if(!blocked) {
										wasShocked = newTarget.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);

										//Also zap all passengers >:)
										for(Entity passenger : newTarget.getRecursivePassengers()) {
											if(passenger instanceof EntityLivingBase && !this.targets.contains(passenger) && !newTargets.contains(passenger)) {
												passenger.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);
												newTargets.add((EntityLivingBase) passenger);
											}
										}
									}

									if(!wasShocked) {
										newTarget.addPotionEffect(ElixirEffectRegistry.EFFECT_SHOCKED.createEffect(newTarget instanceof EntityPlayer ? 30 : 80, 0, true, true));
									}

									continue entityLoop;
								}
							}
						}
					}

					this.targets.addAll(newTargets);

					TheBetweenlands.networkWrapper.sendToAllTracking(new MessageShockArrowHit(chain), this);

					this.jumps++;
				}
			} else {
				this.setDead();
			}
		}
	}
}

public void onUpdate() {
    Level world = player.level();
    if (wasDBNO) {
        wasDBNO = false;
        if (world instanceof ServerLevel level) {
            DamageHandler.kill(level, player, 100000);
        }
        return;
    } else if (this.dbnoTimer >= 0) {
        if (dbnoTimer > 0) {
            this.setDBNOTimer(dbnoTimer - 1);
            if (dbnoTimer == 0) {
                sync();
            }
        }
        player.setAirSupply(300);
        player.setDeltaMovement(0, Math.min(0, player.getDeltaMovement().y()), 0);
        player.removeAllEffects();
        return;
    }
    super.onUpdate();
    int level = getLevel();
    if (level > 0) {
        if (player.tickCount % REFERENCE.REFRESH_SUNDAMAGE_TICKS == 0) {
            isGettingSundamage(world, true);
        }
        if (player.tickCount % REFERENCE.REFRESH_GARLIC_TICKS == 0) {
            isGettingGarlicDamage(world, true);
        }
    } else {
        sunDamageCache = false;
        garlicCache = EnumStrength.NONE;
    }
    this.vision.tick();

    if (!isRemote()) {
        if (level > 0) {

            if (isGettingSundamage(world)) {
                handleSunDamage(false);
            } else if (ticksInSun > 0) {
                ticksInSun--;
            }
            if (isGettingGarlicDamage(world) != EnumStrength.NONE) {
                DamageHandler.affectVampireGarlicAmbient(this, isGettingGarlicDamage(world), player.tickCount);
            }
            if (player.isAlive()) {
                player.setAirSupply(300);
                if (player.tickCount % 16 == 4 && !getSkillProperties().waterResistance && !player.getAbilities().instabuild) {
                    if (player.isInWater()) {
                        FluidState state1 = world.getFluidState(player.blockPosition());
                        FluidState state2 = world.getFluidState(player.blockPosition().above());
                        if ((state1.is(FluidTags.WATER) && (state1.getFlow(world, player.blockPosition()).lengthSqr() > 0)) || (state2.is(FluidTags.WATER) && (state2.getFlow(world, player.blockPosition().above()).lengthSqr() > 0))) {
                            player.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 80, (int) (getLevel() / (float) getMaxLevel() * 3)));
                        }
                    }
                }
            }

            if (player.tickCount % 9 == 3 && ModConfig.balance().vpFireResistanceReplace.get() && player.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                MobEffectInstance fireResistance = player.getEffect(MobEffects.FIRE_RESISTANCE);
                player.addEffect(new MobEffectInstance(ModEffects.FIRE_PROTECTION, fireResistance.getDuration(), fireResistance.getAmplifier()));
                player.removeEffect(MobEffects.FIRE_RESISTANCE);
            }
            if (feed_victim != -1 && feedBiteTickCounter++ >= FEED_TIMER) {
                updateFeeding();
                feedBiteTickCounter = 0;
            }

            if (forceNaturalArmorUpdate || player.tickCount % 128 == 0) {
                updateNaturalArmor(getLevel());
                forceNaturalArmorUpdate = false;
            }
        } else {
            ticksInSun = 0;
        }
    } else {
        if (level > 0) {
            if (isGettingSundamage(world)) {
                handleSunDamage(true);
            } else if (ticksInSun > 0) {
                ticksInSun--;
            }
        } else {
            ticksInSun = 0;
        }

        if (feed_victim != -1 && feedBiteTickCounter++ % 5 == 0) {
            Entity e = VampirismMod.proxy.getMouseOverEntity();
            if (e == null || e.getId() != feed_victim) {
                VampirismMod.proxy.sendToServer(new ServerboundSimpleInputEvent(ServerboundSimpleInputEvent.Event.FINISH_SUCK_BLOOD));
                feedBiteTickCounter = 0;
                feed_victim = -1;
                return;
            }
            if (feedBiteTickCounter >= FEED_TIMER) {
                feedBiteTickCounter = 0;
            }
        }
    }
    if (feed_victim == -1) {
        feedBiteTickCounter = 0;
    }
    if (remainingBarkTicks > 0) {
        --remainingBarkTicks;
    }
    if (crucifixTicks > 0) {
        --crucifixTicks;
        if (this.player.tickCount % 10 == 8 && crucifixTicks > 30) {
            this.player.addEffect(new MobEffectInstance(ModEffects.CRUCIFIX_SUPPRESSION, 20));
        }
    }
}

public void tick() {
    super.tick();
    this.prevAttackProgress = attackProgress;
    prevFlyProgress = flyProgress;
    this.prevSitProgress = this.sitProgress;

    final boolean isSittingOrPassenger = (this.isSitting() || this.isPassenger());
    if (isSittingOrPassenger) {
        if (sitProgress < 5F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (isFlying()) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (fleePumpkinFlag > 0) {
        fleePumpkinFlag--;
    }

    if (!this.level().isClientSide) {
        final boolean isFlying = isFlying();
        if (isFlying && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!isFlying && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (isFlying) {
            timeFlying++;
            this.setNoGravity(true);
            if (this.isSitting() || this.isPassenger() || this.isInLove()) {
                this.setFlying(false);
            }
        } else {
            timeFlying = 0;
            this.setNoGravity(false);
        }
    }
    if (!this.getMainHandItem().isEmpty()) {
        heldItemTime++;
        if (heldItemTime > 60 && isCrowEdible(this.getMainHandItem()) && (!this.isTame() || this.getHealth() < this.getMaxHealth())) {
            heldItemTime = 0;
            this.heal(4);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.PARROT_EAT, this.getSoundVolume(), this.getVoicePitch());
            if (seedThrowerID != null && this.getMainHandItem().is(AMTagRegistry.CROW_TAMEABLES) && !this.isTame()) {
                if (getRandom().nextFloat() < 0.3F) {
                    this.setTame(true);
                    this.setCommand(1);
                    this.setOwnerUUID(this.seedThrowerID);
                    final Player player = level().getPlayerByUUID(seedThrowerID);
                    if (player instanceof final ServerPlayer serverPlayer) {
                        CriteriaTriggers.TAME_ANIMAL.trigger(serverPlayer, this);
                    }
                    this.level().broadcastEntityEvent(this, (byte) 7);
                } else {
                    this.level().broadcastEntityEvent(this, (byte) 6);
                }
            }
            if (this.getMainHandItem().hasCraftingRemainingItem()) {
                this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
            }
            this.getMainHandItem().shrink(1);
        }
    } else {
        heldItemTime = 0;
    }
    if (boardingCooldown > 0) {
        boardingCooldown--;
    }
    if (this.entityData.get(ATTACK_TICK) > 0) {
        this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
        if (attackProgress < 5F) {
            attackProgress++;
        }
    } else {
        if (attackProgress > 0F) {
            attackProgress--;
        }
    }
    if(checkPerchCooldown > 0){
        checkPerchCooldown--;
    }


    if (this.isTame()) {
        if (checkPerchCooldown == 0) {
            checkPerchCooldown = 50;
            final BlockState below = this.getBlockStateOn();
            if (below.is(AMTagRegistry.CROW_HOME_BLOCKS)) {
                this.heal(1);
                this.level().broadcastEntityEvent(this, (byte) 67);
                this.setPerchPos(this.getBlockPosBelowThatAffectsMyMovement());
            }
        }
        if (this.getCommand() == 3 && getPerchPos() != null && checkPerchCooldown == 0) {
            checkPerchCooldown = 120;
            final BlockState below = this.level().getBlockState(getPerchPos());
            if (below.is(AMTagRegistry.CROW_HOME_BLOCKS)) {
                this.level().broadcastEntityEvent(this, (byte) 68);
                this.setPerchPos(null);
                this.setCommand(2);
                this.setOrderedToSit(true);
            }
        }
    }
}

public void tick() {
    super.tick();
    prevScreenShakeAmount = screenShakeAmount;
    this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
    this.legSolver.update(this, this.yBodyRot, this.getScale());
    AnimationHandler.INSTANCE.updateAnimations(this);
    if (screenShakeAmount > 0) {
        screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
    }
    if (this.onGround() && !this.isInFluidType() && this.walkAnimation.speed() > 0.1F && !this.isBaby()) {
        float f = (float) Math.cos(this.walkAnimation.position() * 0.8F - 1.5F);
        if (Math.abs(f) < 0.2) {
            if (screenShakeAmount <= 0.3) {
                this.playSound(ACSoundRegistry.TREMORSAURUS_STOMP.get(), 2, 1.0F);
                this.shakeWater();
            }
            screenShakeAmount = 1F;
        }
    }
    if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
        this.heal(2);
    }
    if (isRunning() && !hasRunningAttributes) {
        hasRunningAttributes = true;
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
    }
    if (!isRunning() && hasRunningAttributes) {
        hasRunningAttributes = false;
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
    }
    if(this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 5){
        this.playRoarSound();
    }
    if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 40 && !this.isBaby()) {
        screenShakeAmount = 1F;
        roarScatterTime = 30;
        if (this.getAnimationTick() % 5 == 0 && level().isClientSide) {
            this.shakeWater();
        }
    }
    if (roarScatterTime > 0) {
        roarScatterTime--;
        scareMobs();
    }
    if (this.getAnimation() == ANIMATION_SPEAK && this.getAnimationTick() == 5) {
        actuallyPlayAmbientSound();
    }
    if (!level().isClientSide) {
        if (this.getDeltaMovement().horizontalDistance() < 0.05 && this.getAnimation() == NO_ANIMATION && !this.isDancing() && !this.isInSittingPose()) {
            if (random.nextInt(180) == 0) {
                this.setAnimation(ANIMATION_SNIFF);
            }
            if (random.nextInt(600) == 0 && !this.isVehicle()) {
                this.tryRoar();
            }
        }
        boolean held = false;
        if (riderHitEntity != null && this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() > 10 && this.getAnimationTick() <= 12) {
            if (this.hasLineOfSight(riderHitEntity) && this.distanceTo(riderHitEntity) < this.getBbWidth() + riderHitEntity.getBbWidth() + 2.0D) {
                riderHitEntity.hurt(riderHitEntity.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                if (riderHitEntity instanceof LivingEntity living) {
                    living.knockback(0.5D, this.getX() - riderHitEntity.getX(), this.getZ() - riderHitEntity.getZ());
                }
                riderHitEntity = null;
            }
        }
        LivingEntity target = riderHitEntity instanceof LivingEntity ? (LivingEntity) riderHitEntity : this.getTarget();
        if (target != null && target.isAlive() && target.distanceTo(this) < (isVehicle() ? 10.0F : 5.5F)) {
            if (this.getAnimation() == ANIMATION_SHAKE_PREY && this.getAnimationTick() <= 35) {
                held = true;
                this.setHeldMobId(target.getId());
            }
        }
        if (!held && getHeldMobId() != -1) {
            this.setHeldMobId(-1);
            this.playSound(ACSoundRegistry.TREMORSAURUS_THROW.get());
            riderHitEntity = null;
        }
    } else {
        Player player = AlexsCaves.PROXY.getClientSidePlayer();
        if (player != null && player.isPassengerOfSameVehicle(this)) {
            if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
            }
            if (AlexsCaves.PROXY.isKeyDown(3) && (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null)) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 3));
            }
        }
    }
    if (this.isVehicle()) {
        if (this.getMeterAmount() < 1.0F) {
            this.setMeterAmount(Math.min(this.getMeterAmount() + 0.0035F, 1.0F));
        }
    } else {
        this.setMeterAmount(0.0F);
    }
    if(this.getAnimation() == ANIMATION_SHAKE_PREY && getHeldMobId() != -1){
        Entity entity = level().getEntity(getHeldMobId());
        if(entity != null){
            if (this.getAnimationTick() <= 35) {
                Vec3 shakePreyPos = getShakePreyPos();
                Vec3 minus = new Vec3(shakePreyPos.x - entity.getX(), shakePreyPos.y - entity.getY(), shakePreyPos.z - entity.getZ());
                entity.setDeltaMovement(minus);
                if (this.getAnimationTick() % 10 == 0) {
                    entity.hurt(damageSources().mobAttack(this), 5 + this.getRandom().nextInt(2));
                }
            }else{
                entity.setDeltaMovement(entity.getDeltaMovement().scale(0.6F));
            }
        }
    }
    if (roarCooldown > 0) {
        roarCooldown--;
    }
    lastStompX = this.getX();
    lastStompZ = this.getZ();
}

public void aiStep() {
    super.aiStep();
    LivingEntity attackTarget = this.getTarget();
    if (attackTarget != null && this.hasLineOfSight(attackTarget)) {
        int index = random.nextInt(getHeadCount());
        if (!isBreathing[index] && !isStriking[index]) {
            if (this.distanceTo(attackTarget) < 6) {
                if (strikeCooldown == 0 && strikingProgress[index] == 0) {
                    isBreathing[index] = false;
                    isStriking[index] = true;
                    this.level.broadcastEntityEvent(this, (byte) (40 + index));
                    strikeCooldown = 3;
                }
            } else if (random.nextBoolean() && breathCooldown == 0) {
                isBreathing[index] = true;
                isStriking[index] = false;
                this.level.broadcastEntityEvent(this, (byte) (50 + index));
                breathCooldown = 15;
            }

        }

    }
    for (int i = 0; i < HEADS; i++) {
        boolean striking = isStriking[i];
        boolean breathing = isBreathing[i];
        prevStrikeProgress[i] = strikingProgress[i];
        if (striking && strikingProgress[i] > 9) {
            isStriking[i] = false;
            if (attackTarget != null && this.distanceTo(attackTarget) < 6) {
                attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                attackTarget.addEffect(new MobEffectInstance(MobEffects.POISON, 100, 3, false, false));
                attackTarget.knockback(0.25F, this.getX() - attackTarget.getX(), this.getZ() - attackTarget.getZ());
            }
        }
        if (breathing) {
            if (tickCount % 7 == 0 && attackTarget != null && i < this.getHeadCount()) {
                Vec3 Vector3d = this.getViewVector(1.0F);
                if (random.nextFloat() < 0.2F) {
                    this.playSound(IafSoundRegistry.HYDRA_SPIT, this.getSoundVolume(), this.getVoicePitch());
                }
                double headPosX = this.headBoxes[i].getX() + Vector3d.x;
                double headPosY = this.headBoxes[i].getY() + 1.3F;
                double headPosZ = this.headBoxes[i].getZ() + Vector3d.z;
                double d2 = attackTarget.getX() - headPosX + this.random.nextGaussian() * 0.4D;
                double d3 = attackTarget.getY() + attackTarget.getEyeHeight() - headPosY + this.random.nextGaussian() * 0.4D;
                double d4 = attackTarget.getZ() - headPosZ + this.random.nextGaussian() * 0.4D;
                EntityHydraBreath entitylargefireball = new EntityHydraBreath(IafEntityRegistry.HYDRA_BREATH.get(),
                    level, this, d2, d3, d4);
                entitylargefireball.setPos(headPosX, headPosY, headPosZ);
                if (!level.isClientSide) {
                    level.addFreshEntity(entitylargefireball);
                }
            }
            if (isBreathing[i] && (attackTarget == null || !attackTarget.isAlive() || breathTicks[i] > 60) && !level.isClientSide) {
                isBreathing[i] = false;
                breathTicks[i] = 0;
                breathCooldown = 15;
                this.level.broadcastEntityEvent(this, (byte) (60 + i));
            }
            breathTicks[i]++;
        } else {
            breathTicks[i] = 0;
        }
        if (striking && strikingProgress[i] < 10.0F) {
            strikingProgress[i] += 2.5F;
        } else if (!striking && strikingProgress[i] > 0.0F) {
            strikingProgress[i] -= 2.5F;
        }
        prevSpeakingProgress[i] = speakingProgress[i];
        if (speakingProgress[i] > 0.0F) {
            speakingProgress[i] -= 0.1F;
        }
        prevBreathProgress[i] = breathProgress[i];
        if (breathing && breathProgress[i] < 10.0F) {
            breathProgress[i] += 1.0F;
        } else if (!breathing && breathProgress[i] > 0.0F) {
            breathProgress[i] -= 1.0F;
        }

    }
    if (strikeCooldown > 0) {
        strikeCooldown--;
    }
    if (breathCooldown > 0) {
        breathCooldown--;
    }
    if (this.getHeadCount() == 1 && this.getSeveredHead() != -1) {
        this.setSeveredHead(-1);
    }
    if (this.getHeadCount() == 1 && !this.isOnFire()) {
        this.setHeadCount(2);
        this.setSeveredHead(1);
        onlyRegrowOneHeadNotTwo = true;
    }

    if (this.getSeveredHead() != -1 && this.getSeveredHead() < this.getHeadCount()) {
        this.setSeveredHead(Mth.clamp(this.getSeveredHead(), 0, this.getHeadCount() - 1));
        regrowHeadCooldown++;
        if (regrowHeadCooldown >= 100) {
            headDamageTracker[this.getSeveredHead()] = 0;
            this.setSeveredHead(-1);
            if (this.isOnFire()) {
                this.setHeadCount(this.getHeadCount() - 1);
            } else {
                this.playSound(IafSoundRegistry.HYDRA_REGEN_HEAD, this.getSoundVolume(), this.getVoicePitch());
                if (!onlyRegrowOneHeadNotTwo) {
                    this.setHeadCount(this.getHeadCount() + 1);
                }
            }
            onlyRegrowOneHeadNotTwo = false;
            regrowHeadCooldown = 0;
        }
    } else {
        regrowHeadCooldown = 0;
    }
}

public void tick() {
    super.tick();
    prevStandProgress = standProgress;
    prevTongueProgress = tongueProgress;
    prevLeaningProgress = leaningProgress;

    if (isStanding()) {
        if (standProgress < 5F)
            standProgress++;
    } else {
        if (standProgress > 0F)
            standProgress--;
    }

    final boolean isTongueOut = this.getAnimation() == ANIMATION_TOUNGE_IDLE;
    if (isTongueOut) {
        if (tongueProgress < 5F)
            tongueProgress++;
    } else {
        if (tongueProgress > 0F)
            tongueProgress--;
    }

    if (isLeaning()) {
        if (leaningProgress < 5F)
            leaningProgress++;
    } else {
        if (leaningProgress > 0F)
            leaningProgress--;
    }

    if (isStanding() && ++standingTime > maxStandTime) {
        this.setStanding(false);
        standingTime = 0;
        maxStandTime = 75 + random.nextInt(50);
    }

    if (this.isPassenger() && this.getVehicle() instanceof final EntityAnteater mount) {
        if (this.isBaby()) {
            this.setYRot(mount.yBodyRot);
            this.yHeadRot = mount.yBodyRot;
            this.yBodyRot = mount.yBodyRot;
        } else {
            this.removeVehicle();
        }
    }

    if (eatAntCooldown > 0) {
        eatAntCooldown--;
    }
    if (antsEatenRecently >= 3 && eatAntCooldown <= 0) {
        this.resetAntCooldown();
    }
    if (ticksAntOnTongue > 10 && this.hasAntOnTongue()) {
        this.heal(6);
        this.gameEvent(GameEvent.EAT);
        this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
        this.setAntOnTongue(false);
    }
    if (this.hasAntOnTongue()) {
        ticksAntOnTongue++;
    } else {
        ticksAntOnTongue = 0;
    }
    if (!this.level().isClientSide && getTongueStickOut() > 0.6F && !this.hasAntOnTongue() && antsEatenRecently < 3) {
        EntityLeafcutterAnt closestAnt = null;
        for (EntityLeafcutterAnt entity : this.level().getEntitiesOfClass(EntityLeafcutterAnt.class, this.getBoundingBox().inflate(2.6F))) {
            if (closestAnt == null || entity.distanceTo(this) < closestAnt.distanceTo(this) && this.hasLineOfSight(entity)) {
                closestAnt = entity;
            }
        }
        if (closestAnt != null) {
            closestAnt.remove(RemovalReason.KILLED);
            ticksAntOnTongue = 0;
            this.setAntOnTongue(true);
            antsEatenRecently++;
        }
    }
    if (!this.getMainHandItem().isEmpty()) {
        heldItemTime++;
        if (heldItemTime > 10 && getTongueStickOut() < 0.3F && canTargetItem(this.getMainHandItem())) {
            heldItemTime = 0;
            this.heal(4);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.gameEvent(GameEvent.EAT);
            if (this.getMainHandItem().hasCraftingRemainingItem()) {
                this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
            }
            this.stopBeingAngry();
            this.getMainHandItem().shrink(1);
        }
    } else {
        heldItemTime = 0;
    }

    if (!this.level().isClientSide) {
        if (getRandom().nextInt(300) == 0)
            this.setAnimation(ANIMATION_TOUNGE_IDLE);

        final LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null) {
            if (distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 2) {
                if (this.getAnimationTick() == 7) {
                    if (this.getAnimation() == ANIMATION_SLASH_L) {
                        doHurtTarget(attackTarget);
                        final float rot = getYRot() + 90;
                        attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                    } else if (this.getAnimation() == ANIMATION_SLASH_R) {
                        doHurtTarget(attackTarget);
                        final float rot = getYRot() - 90;
                        attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                    }
                }
            }
        }
    }

    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    super.tick();
    prevWormAngle = this.getWormAngle();
    prevJawProgress = this.jawProgress;
    float threshold = 0.05F;
    if (this.isSplitter()) {
        this.xpReward = 10;
    } else {
        this.xpReward = 70;
    }
    if (this.yRotO - this.getYRot() > threshold) {
        this.setWormAngle(this.getWormAngle() + 15);
    } else if (this.yRotO - this.getYRot() < -threshold) {
        this.setWormAngle(this.getWormAngle() - 15);
    } else if (this.getWormAngle() > 0) {
        this.setWormAngle(Math.max(this.getWormAngle() - 20, 0));
    } else if (this.getWormAngle() < 0) {
        this.setWormAngle(Math.min(this.getWormAngle() + 20, 0));
    }
    if (!this.level().isClientSide) {
        if (!fullyThrough) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.9F, 0.9F, 0.9F).add(0, -0.01, 0));
        } else {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.01, 0));
        }
    }
    if (Math.abs(xo - this.getX()) < 0.01F && Math.abs(yo - this.getY()) < 0.01F && Math.abs(zo - this.getZ()) < 0.01F) {            stillTicks++;
    } else {
        stillTicks = 0;
    }
    if (stillTicks > 40 && makePortalCooldown == 0) {
        createStuckPortal();
    }
    if (makePortalCooldown > 0) {
        makePortalCooldown--;
    }
    if (makeIdlePortalCooldown > 0) {
        makeIdlePortalCooldown--;
    }
    if (makeIdlePortalCooldown == 0 && random.nextInt(100) == 0) {
        this.createPortalRandomDestination();
        makeIdlePortalCooldown = 200 + random.nextInt(1000);
    }
    if (this.entityData.get(JAW_TICKS) > 0) {
        if (this.jawProgress < 5) {
            jawProgress++;
        }
        this.entityData.set(JAW_TICKS, this.entityData.get(JAW_TICKS) - 1);
    } else {
        if (this.jawProgress > 0) {
            jawProgress--;
        }
    }
    if (this.isAlive()) {
        for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(2.0D))) {
            if (!entity.is(this) && !(entity instanceof EntityVoidWormPart) && !entity.isAlliedTo(this) && entity != this) {
                launch(entity, false);
            }
        }
        this.setMaxUpStep(2F);
    }else{
        this.setDeltaMovement(new Vec3(0, 0.03F, 0));
    }
    yBodyRot = getYRot();
    final float f2 = (float) -((float) this.getDeltaMovement().y * (double) Mth.RAD_TO_DEG);
    this.setXRot(f2);
    this.setMaxUpStep(2F);
    if (!this.level().isClientSide) {
        Entity child = getChild();
        if (child == null) {
            LivingEntity partParent = this;
            int tailstart = Math.min(3 + random.nextInt(2), getSegmentCount());
            int segments = getSegmentCount();
            for (int i = 0; i < segments; i++) {
                float scale = 1F + (i / (float) segments) * 0.5F;
                boolean tail = false;
                if (i >= segments - tailstart) {
                    tail = true;
                    scale = scale * 0.85F;
                }
                EntityVoidWormPart part = new EntityVoidWormPart(AMEntityRegistry.VOID_WORM_PART.get(), partParent,  1.0F + (scale * (tail ? 0.65F : 0.3F)) + (i == 0 ? 0.8F : 0), 180, i == 0 ? -0.0F : i == segments - tailstart ? -0.3F : 0);
                part.setInvulnerable(partParent.isInvulnerable());
                part.setParent(partParent);
                if (updatePostSummon) {
                    part.setPortalTicks(i * 2);
                }
                part.setBodyIndex(i);
                part.setTail(tail);
                part.setWormScale(scale);
                if (partParent == this) {
                    this.setChildId(part.getUUID());
                } else if (partParent instanceof EntityVoidWormPart) {
                    ((EntityVoidWormPart) partParent).setChildId(part.getUUID());
                }
                part.setInitialPartPos(this);
                partParent = part;
                level().addFreshEntity(part);
            }
        }
    }
    if (this.getPortalTicks() > 0) {
        this.setPortalTicks(this.getPortalTicks() - 1);
        if (this.getPortalTicks() == 2 && teleportPos != null) {
            this.setPos(teleportPos.x, teleportPos.y, teleportPos.z);
            teleportPos = null;
        }
    }
    if (this.portalTarget != null && this.portalTarget.getLifespan() < 5) {
        this.portalTarget = null;
    }
    this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());
    breakBlock();
    if (updatePostSummon) {
        updatePostSummon = false;
    }
    if (!this.isSilent() && !this.level().isClientSide) {
        this.level().broadcastEntityEvent(this, (byte) 67);
    }
}

protected void onHitEntity(EntityRayTraceResult rayTrace) {
	Entity target = rayTrace.getEntity();
	float drawPower = (float)this.getDeltaMovement().length();
	double damage = getBaseDamage();
	boolean critical = isCritArrow();

	if (bow != null) {
		damage = bow.getArrowDamage(this, target, damage, drawPower, critical);
	}
	else if (crossbow != null) {
		damage = crossbow.getArrowDamage(this, target, damage, drawPower, critical);
	}

	damage = Math.max(damage, 0.0D);

	if (getPierceLevel() > 0) {
		if (piercingIgnoreEntityIds == null)
			piercingIgnoreEntityIds = new IntOpenHashSet(5);

		if (piercedAndKilledEntities == null)
			piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);

		if (piercingIgnoreEntityIds.size() >= getPierceLevel() + 1) {
			remove();

			return;
		}

		piercingIgnoreEntityIds.add(target.getId());
	}

	Entity shooter = this.getOwner();
	DamageSource source;

	if (shooter == null) {
		source = DamageSource.arrow(this, this);
	}
	else {
		source = DamageSource.arrow(this, shooter);

		if (shooter instanceof LivingEntity)
			((LivingEntity)shooter).setLastHurtMob(target);
	}

	boolean isEnderman = target.getType() == EntityType.ENDERMAN;
	int fireTimer = target.getRemainingFireTicks();

	if (isOnFire() && !isEnderman)
		target.setSecondsOnFire(5);

	if (target.hurt(source, (float)damage)) {
		if (isEnderman)
			return;

		if (bow != null) {
			bow.onEntityHit(this, target, shooter, damage, drawPower);
		}
		else if (crossbow != null) {
			crossbow.onEntityHit(this, target, shooter, damage, drawPower);
		}

		if (target instanceof LivingEntity) {
			LivingEntity livingTarget = (LivingEntity)target;

			if (!level.isClientSide && getPierceLevel() <= 0)
				livingTarget.setArrowCount(livingTarget.getArrowCount() + 1);

			if (knockback > 0) {
				Vector3d Vector3d = getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale(knockback * 0.6D);

				if (Vector3d.lengthSqr() > 0.0D)
					livingTarget.push(Vector3d.x, 0.1D, Vector3d.z);
			}

			if (!level.isClientSide && shooter instanceof LivingEntity) {
				EnchantmentHelper.doPostHurtEffects(livingTarget, shooter);
				EnchantmentHelper.doPostDamageEffects((LivingEntity)shooter, livingTarget);
			}

			doPostHurtEffects(livingTarget);

			if (livingTarget != shooter && livingTarget instanceof PlayerEntity && shooter instanceof ServerPlayerEntity)
				((ServerPlayerEntity)shooter).connection.send(new SChangeGameStatePacket(SChangeGameStatePacket.ARROW_HIT_PLAYER, 0.0F));

			if (!target.isAlive() && piercedAndKilledEntities != null)
				piercedAndKilledEntities.add(livingTarget);

			if (!level.isClientSide && shooter instanceof ServerPlayerEntity) {
				ServerPlayerEntity serverplayerentity = (ServerPlayerEntity)shooter;

				if (piercedAndKilledEntities != null && shotFromCrossbow()) {
					CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayerentity, this.piercedAndKilledEntities);
				}
				else if (!target.isAlive() && shotFromCrossbow()) {
					CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayerentity, Arrays.asList(target));
				}
			}
		}

		playSound(getHitGroundSoundEvent(), 1.0F, 1.2F / (random.nextFloat() * 0.2F + 0.9F));

		if (getPierceLevel() <= 0)
			remove();
	}
	else {
		target.setRemainingFireTicks(fireTimer);
		setDeltaMovement(getDeltaMovement().scale(-0.1D));

		yRot += 180.0F;
		yRotO += 180.0F;

		if (!level.isClientSide && getDeltaMovement().lengthSqr() < 0.0000001) {
			if (pickup == PickupStatus.ALLOWED)
				spawnAtLocation(getPickupItem(), 0.1F);

			remove();
		}
	}
}

public void tick() {
	super.tick();
	prevRightPunchProgress = rightPunchProgress;
	prevLeftPunchProgress = leftPunchProgress;
	prevLaserX = this.getLaserX();
	prevLaserY = this.getLaserY();
	prevLaserZ = this.getLaserZ();
	prevLaserProgress = laserProgress;
	if (laserProgress < 1.0F && this.isUsingBeamAttack() && !this.isUsingRegularAttack()) {
		laserProgress += 0.1F;
	}
	if (laserProgress > 0.0F && (!this.isUsingBeamAttack() || this.isUsingRegularAttack())) {
		laserProgress -= 0.1F;
	}
	if (getTarget() != null) {
		targetDistance = distanceTo(getTarget()) - getTarget().getBbWidth() / 2f;
		targetAngle = (float) getAngleBetweenEntities(this, getTarget());
	}
	if (getTarget() != null && (!getTarget().isAlive() || getTarget().getHealth() <= 0))
		setTarget(null);
	if (!level().isClientSide()) {
		if (!isNoAi()) {
			if (isActive()) {
				if (getTarget() == null) {
					setActive(false);
				}
			} else if (getTarget() != null && targetDistance <= 30 || getTarget() != null && targetDistance <= 30) {
				setActive(true);
			}
			if(this.getHealthRatio() < 0.5F && shieldCooldown == 0 && !this.hasHealingShield()){
				shieldCooldown = 300 + random.nextInt(300);
				this.setHealingShield(3);
			}
		}
	}
	if (!isActive()) {
		setDeltaMovement(0, getDeltaMovement().y, 0);
		yRot = yRotO;
		if (this.getHealth() < this.getMaxHealth()) {
			this.setHealingShield(1);
		}
		if (this.getHealth() == this.getMaxHealth()) {
			this.setHealingShield(0);
		}
	}
	yBodyRot = yHeadRot;
	if (!level().isClientSide() && hasHealingShield()){
		if(this.getTarget() == null){
			this.heal(0.3F);
		}else{
			double dist = this.distanceTo(this.getTarget());
			if(dist > 16.0F){
				this.heal(3F);
			}else{
				this.heal((float)Mth.clamp(dist * 0.085F, 0.2F, 3F));
			}
		}
	}
	if (this.entityData.get(MELEE_TICK) > 0 && isUsingRegularAttack()) {
		if (Math.max(rightPunchProgress, leftPunchProgress) == 5 && this.getTarget() != null && this.distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + this.getBbWidth() + 2.0F) {
			this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
			if (this.getTarget().isBlocking()) {
				((Player)this.getTarget()).getCooldowns().addCooldown(Items.SHIELD, 100);
				((Player)this.getTarget()).stopUsingItem();
				this.level().broadcastEntityEvent(((Player)this.getTarget()), (byte)30);
			}
		}
		this.entityData.set(MELEE_TICK, this.entityData.get(MELEE_TICK) - 1);
		if (this.entityData.get(MELEE_TICK) == 0) {
			usingLeftHand = !usingLeftHand;
		}
		if (!usingLeftHand && rightPunchProgress < 5F) {
			rightPunchProgress += 2.5F;
		}
		if (usingLeftHand && leftPunchProgress < 5F) {
			leftPunchProgress += 2.5F;
		}
	} else {
		if (leftPunchProgress > 0F) {
			leftPunchProgress -= Math.min(0.5F, leftPunchProgress);
		}
		if (rightPunchProgress > 0F) {
			rightPunchProgress -= Math.min(0.5F, rightPunchProgress);
		}
	}
	if (usingLeftHand) {
		if (rightPunchProgress > 0F) {
			rightPunchProgress--;
		}
	} else {
		if (leftPunchProgress > 0F) {
			leftPunchProgress--;
		}
	}
	if (this.isUsingBeamAttack()) {
		double d0 = this.getLaserX() - this.getX();
		double d1 = this.getLaserY() - this.getY(1);
		double d2 = this.getLaserZ() - this.getZ();
		double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
		d0 = d0 / d3;
		d1 = d1 / d3;
		d2 = d2 / d3;
		double d4 = this.random.nextDouble();
		while (d4 < d3) {
			d4 += 3.0D - this.random.nextDouble() * 2.5D;
			this.level().addParticle(PFParticles.BOSS_LASER.get(), this.getX() + d0 * d4, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4, (random.nextFloat() - 0.5F) * 0.1F, random.nextFloat() * 0.2F, (random.nextFloat() - 0.5F) * 0.1F);
		}
	}
	if(this.hasHealingShield() && level().isClientSide()){
		for(int i = 0; i < 2 + random.nextInt(2); i++){
			this.level().addParticle(PFParticles.BOSS_HEAL.get(), this.getRandomX(2.0D), this.getY(), this.getRandomZ(2.0D), this.getX(), this.getY(0.75F), this.getZ());
		}
	}
	if (this.getLaserTick() < 0) {
		this.setLaserTick(this.getLaserTick() + 1);
	}
	if(shieldCooldown > 0 && !this.hasHealingShield()){
		shieldCooldown--;
	}
}

public void tick() {
    super.tick();
    prevOpenProgress = openProgress;
    prevClutchProgress = clutchProgress;
    prevBiteProgress = biteProgress;
    prevCosmawPitch = this.getCosmawPitch();
    if (!this.level().isClientSide) {
        final float f2 = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
        this.setCosmawPitch(this.getCosmawPitch() + 0.6F * (this.getCosmawPitch() + f2) - this.getCosmawPitch());
    }

    if (isMouthOpen()) {
        if (openProgress < 5F)
            openProgress++;
    } else {
        if (openProgress > 0F)
            openProgress--;
    }

    if (isVehicle()) {
        if (clutchProgress < 5F)
            clutchProgress++;
    } else {
        if (clutchProgress > 0F)
            clutchProgress--;
    }

    if (this.entityData.get(ATTACK_TICK) > 0) {
        if (biteProgress < 5F) {
            biteProgress = Math.min(5F, biteProgress + 2F);
        } else {
            if (this.getTarget() != null && this.distanceTo(this.getTarget()) < 3.3D) {
                if (this.getTarget() instanceof EntityCosmicCod && !this.isTame()) {
                    EntityCosmicCod fish = (EntityCosmicCod) this.getTarget();
                    CompoundTag fishNbt = new CompoundTag();
                    fish.addAdditionalSaveData(fishNbt);
                    fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
                    fish.readAdditionalSaveData(fishNbt);
                }
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            }
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
        }
    } else {
        if (biteProgress > 0F) {
            biteProgress -= 1F;
        }
    }
    if (!this.getMainHandItem().isEmpty()) {
        heldItemTime++;
        if (heldItemTime > 30 && canTargetItem(this.getMainHandItem())) {
            heldItemTime = 0;
            this.heal(4);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.DOLPHIN_EAT, this.getSoundVolume(), this.getVoicePitch());
            if (this.getMainHandItem().is(AMTagRegistry.COSMAW_TAMEABLES) && fishThrowerID != null && !this.isTame()) {
                if (getRandom().nextFloat() < 0.3F) {
                    this.setTame(true);
                    this.setCommand(1);
                    this.setOwnerUUID(this.fishThrowerID);
                    Player player = level().getPlayerByUUID(fishThrowerID);
                    if (player instanceof ServerPlayer) {
                        CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer) player, this);
                    }
                    this.level().broadcastEntityEvent(this, (byte) 7);
                } else {
                    this.level().broadcastEntityEvent(this, (byte) 6);
                }
            }
            if (this.getMainHandItem().hasCraftingRemainingItem()) {
                this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
            }
            this.getMainHandItem().shrink(1);
        }
    } else {
        heldItemTime = 0;
    }
    if (!this.level().isClientSide) {
        if (tickCount % 100 == 0 || lastSafeTpPosition == null) {
            BlockPos pos = getCosmawGround(this.blockPosition());
            if (pos.getY() > 1) {
                lastSafeTpPosition = pos;
            }
        }

        if (this.isVehicle()) {
            if (lastSafeTpPosition != null) {
                final double dist = this.distanceToSqr(Vec3.atCenterOf(lastSafeTpPosition));
                float speed = 0.8F;
                if(this.getY() < -40){
                    speed = 3F;
                }
                if (verticalCollision && dist > 14) {
                    this.setYRot(this.stuckRot);
                    if (random.nextInt(50) == 0) {
                        this.stuckRot = Mth.wrapDegrees(this.stuckRot + 90);

                    }
                    final float angle = (Maths.STARTING_ANGLE * stuckRot);
                    final double extraX = -2 * Mth.sin(Mth.PI + angle);
                    final double extraZ = -2 * Mth.cos(angle);
                    this.getMoveControl().setWantedPosition(this.getX() + extraX, this.getY() + 2, this.getZ() + extraZ, speed);
                } else if (lastSafeTpPosition.getY() > this.getY() + 2.3F) {
                    this.getMoveControl().setWantedPosition(this.getX(), this.getY() + 2, this.getZ(), speed);
                } else {
                    this.getMoveControl().setWantedPosition(lastSafeTpPosition.getX(), lastSafeTpPosition.getY() + 2, lastSafeTpPosition.getZ(), speed);
                }
                if (dist < 7 && getCosmawGround(this.blockPosition()).getY() > 1) {
                    this.ejectPassengers();
                }
            } else {
                if (this.getY() < 0F) {
                    this.getDeltaMovement().add(0, 0.75F, 0);
                } else if (this.getY() < 80F) {
                    this.getDeltaMovement().add(0, 0.1F, 0);
                }
            }

        }
    }

}

