public void tick() {
    super.tick();
    prevSurfacePosition = surfacePosition;
    prevScreenShakeAmount = screenShakeAmount;
    prevMouthOpenProgress = mouthOpenProgress;

    if (isMoving() || surfacePosition == null) {
        surfacePosition = calculateLightAbovePosition();
    }
    if (this.isMouthOpen() && mouthOpenProgress < 10F) {
        mouthOpenProgress++;
    }
    if (!this.isMouthOpen() && mouthOpenProgress > 0F) {
        mouthOpenProgress--;
    }
    surfaceY = calculateSurfaceY();
    prevZRot = zRot;
    prevDigPitch = digPitch;
    this.yBodyRot = this.getYRot();
    this.yHeadRot = this.getYRot();
    Entity target = this.getTarget();
    if(!level().isClientSide && (!this.isLeaping() || (target == null || !target.isAlive())) && !this.isRidingMode()){
        this.setTargetDigPitch((float) (-(Mth.atan2(this.getDeltaMovement().y, this.getDeltaMovement().horizontalDistance()) * (180F / (float) Math.PI))));
    }
    if (screenShakeAmount > 0) {
        screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
    }
    this.digPitch = Mth.approachDegrees(digPitch, getTargetDigPitch(), 5);
    if (this.isMoving()) {
        this.zRot += (this.entityData.get(Z_ROT_DIRECTION) ? -10 : 10);
        if (random.nextInt(300) == 0 && !level().isClientSide) {
            this.entityData.set(Z_ROT_DIRECTION, random.nextBoolean());
        }
        screenShakeAmount = 1.5F;
    } else {
        this.zRot = Mth.approachDegrees(this.zRot, 0, 2);
    }
    if (level().isClientSide) {
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
        } else {
            this.reapplyPosition();
        }
        if(this.isDigging() && isAlive()){
            AlexsCaves.PROXY.playWorldSound(this, (byte) 17);
        }
        spawnDustParticles(false);
    }else{
        Entity ridingSegment = this.getRidingSegment();
        this.entityData.set(RIDING_SEGMENT_ID, ridingSegment == null ? -1 : ridingSegment.getId());
        this.entityData.set(DIGGING, isDigLogic() && !isLeaping());
    }
    boolean flag = false;
    BlockState centralState = level().getBlockState(this.blockPosition());
    BlockState centralStateBelow = level().getBlockState(this.blockPosition().below());
    if ((!isSafeDig(level(), this.blockPosition())) && !this.isLeaping()) {
        if (!canDigBlock(centralStateBelow)) {
            this.setDeltaMovement(random.nextFloat() - 0.5F, 0.8F, random.nextFloat() - 0.5F);
            flag = true;
        }
    }else if((surfaceY < this.getEyeY() || centralStateBelow.isAir() || this.isInFluidType()) && isSafeDig(level(), this.blockPosition().below()) && !isRidingMode() && !this.isLeaping()){
        if(outOfGroundTime++ > 10){
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.5, 0));
        }
    }else{
        outOfGroundTime = 0;
    }
    if(isRidingMode()){
        boolean flag1 = false;
        int worldHeight = level().getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, (int) this.getX(), (int) this.getZ());
        if(isTouchingBedrock()){
            noPhysics = false;
            this.setDeltaMovement(this.getDeltaMovement().scale(0.9).add(0, this.getY() < worldHeight - 6.0F ? 0.2F : -0.2F, 0));
        }else if((centralState.isSolid() || this.horizontalCollision || ridingPlayer != null && ridingPlayer.getY() > this.getY() + this.getBbHeight() + 4.0F) && !this.isLeaping()){
            float upOrDown = 0.4F;
            if(surfaceY < worldHeight + 1.0F){
                upOrDown = 0.8F;
            }else if(this.getY() > level().getMinBuildHeight() + 3.0F){
                upOrDown = -0.1F;
            }
            this.setDeltaMovement(this.getDeltaMovement().scale(0.9).add(0, upOrDown, 0));
            flag = true;
            flag1 = !this.horizontalCollision;
        }
        if(!this.isLeaping() && !level().getBlockState(this.blockPosition().below()).isSolid() && !this.horizontalCollision){
            flag = true;
            this.setDeltaMovement(this.getDeltaMovement().scale(0.9).add(0, -0.8F, 0));
        }
        noPhysics = flag1;
    }
    if(wasDiggingLastTick != isDigging()){
        wasDiggingLastTick = isDigging();
        if(!isDigging()){
            attemptPlayStopDiggingNoise();
        }
    }
    this.setNoGravity(!this.getNavigation().isDone() && !this.isLeaping() && !flag && !this.isInWall());
    if (timeBetweenAttacks > 0) {
        timeBetweenAttacks--;
    }
    if (leapAttackCooldown > 0) {
        leapAttackCooldown--;
    }
    if(ridingModeTicks > 0){
        ridingModeTicks--;
    }
    if(recentlyLeaptTicks > 0 && !this.isLeaping()){
        recentlyLeaptTicks--;
    }
    if(forceMouthOpenTicks > 0){
        forceMouthOpenTicks--;
    }
    if(attackNoiseCooldown > 0){
        attackNoiseCooldown--;
    }
    if(stopDiggingNoiseCooldown > 0){
        stopDiggingNoiseCooldown--;
    }
}

public void tick() {
    super.tick();
    prevWheelRot = wheelRot;
    prevWheelYaw = wheelYaw;
    prevRollLeanProgress = rollLeanProgress;
    prevFormProgress = formProgress;
    prevAttackPoseProgress = attackPoseProgress;
    boolean wheelSpinning = false;
    double speed = this.getDeltaMovement().horizontalDistance();

    if (speed > 0.01) {
        if (this.isFormed()) {
            float f = (float) Math.cos(this.walkAnimation.position() * 0.4F - 1.5F);
            if (this.walkAnimation.speed() > 0.2F && Math.abs(f) < 0.2F) {
                if (movingSoundTimer == 0) {
                    movingSoundTimer = 5;
                    this.playSound(ACSoundRegistry.MAGNETRON_STEP.get());
                }
            }
            if (movingSoundTimer > 0) {
                movingSoundTimer--;
            }
        } else {
            wheelSpinning = true;
            wheelRot += Math.max(speed * 10, 1) * 15;
            if (movingSoundTimer++ > 20) {
                this.playSound(ACSoundRegistry.MAGNETRON_ROLL.get());
                movingSoundTimer = 0;
            }
        }
    }
    if (!wheelSpinning && Mth.wrapDegrees(wheelRot) != 0) {
        wheelRot = Mth.approachDegrees(wheelRot, 0, 15);
    }
    if (!this.level().isClientSide && !isFormed()) {
        LivingEntity target = this.getTarget();
        if (target instanceof Player && target.isAlive() && this.distanceTo(target) < 8) {
            this.startForming();
        }
    }
    if (wheelSpinning || this.isFormed()) {
        wheelYaw = Mth.approachDegrees(wheelYaw, yBodyRot, 15);
    }
    AttackPose attackPose = this.getAttackPose();
    if (this.prevAttackPose != attackPose) {
        if (attackPoseProgress < 10.0F) {
            attackPoseProgress += 1F;
        } else if (attackPoseProgress >= 10.0F) {
            if (attackPose == AttackPose.SLAM) {
                spawnGroundEffects();
            }
            this.prevAttackPose = attackPose;
        }
    } else {
        this.attackPoseProgress = 10.0F;
    }
    if (isFormed() && formProgress < FORM_TIME) {
        if (formProgress == 0) {
            this.playSound(ACSoundRegistry.MAGNETRON_ASSEMBLE.get());
        }
        formProgress++;
    }
    if (!isFormed() && formProgress > 0F) {
        formProgress = 0;
    }
    if (wheelSpinning && rollLeanProgress < 5F) {
        rollLeanProgress++;
    }
    if (!wheelSpinning && rollLeanProgress > 0F) {
        rollLeanProgress--;
    }
    if (!level().isClientSide) {
        if (isFormed() && this.isLandNavigator) {
            switchMoveController(false);
        }
        if (!isFormed() && !this.isLandNavigator) {
            switchMoveController(true);
        }
    }
    tickMultipart();
    if (level().isClientSide) {
        for (int i = 0; i < lightningAnimOffsets.length; i++) {
            lightningAnimOffsets[i] = new Vec3(random.nextFloat() - 0.5F, random.nextFloat() - 0.5F, random.nextFloat() - 0.5F).scale(0.3F);
        }
    }
    if (syncCooldown > 0) {
        syncCooldown--;
    } else {
        syncCooldown = 200;
        //syncBlockStatesWithMultipart();
    }
    if (!this.isAlive() && shouldDropBlocks()) {
        if (this.isFormed()) {
            for (MagnetronPartEntity part : allParts) {
                if (part.getBlockState() != null && level().getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
                    BlockPos placeAt = part.blockPosition();
                    while (!level().getBlockState(placeAt).isAir() && placeAt.getY() < level().getMaxBuildHeight()) {
                        placeAt = placeAt.above();
                    }
                    FallingBlockEntity.fall(level(), placeAt, part.getBlockState());
                    part.setBlockState(null);
                }
            }
        }
        if (!droppedHeart) {
            droppedHeart = true;
            FallingBlockEntity.fall(level(), this.blockPosition(), ACBlockRegistry.HEART_OF_IRON.get().defaultBlockState().setValue(HeartOfIronBlock.AXIS, this.getDirection().getAxis()));
        }
        removeParts();
    }
    if (isFormed() && !hasFormedAttributes) {
        hasFormedAttributes = true;
        refreshDimensions();
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(80F);
        this.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1F);
        this.heal(80F);
    }
    if (!isFormed() && !isBaby() && hasFormedAttributes) {
        hasFormedAttributes = false;
        refreshDimensions();
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30F);
        this.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(0F);
        this.heal(30F);
    }
}

public void tick() {
    super.tick();
    this.setMaxUpStep(1F);
    prevGlideProgress = glideProgress;
    prevAttachChangeProgress = attachChangeProgress;
    prevForageProgress = forageProgress;
    prevSitProgress = sitProgress;
    if (attachChangeProgress > 0F) {
        attachChangeProgress -= 0.25F;
    }
    //boolean glideVisual = this.isGliding() || this.getVehicle() != null && this.getVehicle().fallDistance != 0;
    if (glideProgress < 5F && isGliding()) {
        glideProgress += 2.5F;
    }
    if (glideProgress > 0F && !isGliding()) {
        glideProgress -= 2.5F;
    }
    if (forageProgress < 5F && getForagingTime() > 0) {
        forageProgress++;
    }
    if (forageProgress > 0F && getForagingTime() <= 0) {
        forageProgress--;
    }
    boolean sitVisual = this.isOrderedToSit() && !this.isInWater() && this.onGround();
    if (sitProgress < 5F && sitVisual) {
        sitProgress++;
    }
    if (sitProgress > 0F && !sitVisual) {
        sitProgress--;
    }
    if (isGliding()) {
        if (shouldStopGliding()) {
            this.setGliding(false);
        } else {
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.99D, 0.5D, 0.99D));
        }
    }
    Vec3 vector3d = this.getDeltaMovement();
    if (!this.level().isClientSide) {
        this.setBesideClimbableBlock(this.horizontalCollision);
        if (this.onGround() || this.isOrderedToSit() || this.isInWaterOrBubble() || this.isInLava() || this.isGliding() || this.isPassenger()) {
            this.entityData.set(ATTACHED_FACE, Direction.DOWN);
        } else {
            Direction closestDirection = Direction.DOWN;
            double closestDistance = 100;
            for (Direction dir : POSSIBLE_DIRECTIONS) {
                BlockPos antPos = new BlockPos(Mth.floor(this.getX()), Mth.floor(this.getY()), Mth.floor(this.getZ()));
                BlockPos offsetPos = antPos.relative(dir);
                Vec3 offset = Vec3.atCenterOf(offsetPos);
                if (closestDistance > this.position().distanceTo(offset) && level().loadedAndEntityCanStandOnFace(offsetPos, this, dir.getOpposite())) {
                    closestDistance = this.position().distanceTo(offset);
                    closestDirection = dir;
                }
            }
            this.entityData.set(ATTACHED_FACE, closestDistance > this.getBbWidth() * 0.5F + 0.7F ? Direction.DOWN : closestDirection);
        }
    }
    boolean flag = false;
    if (this.getAttachmentFacing() != Direction.DOWN) {
        if (!this.horizontalCollision && this.getAttachmentFacing() != Direction.UP) {
            Vec3 vec = Vec3.atLowerCornerOf(this.getAttachmentFacing().getNormal());
            this.setDeltaMovement(vector3d.add(vec.normalize().multiply(0.1F, 0.1F, 0.1F)));
        }
        if (!this.onGround() && vector3d.y < 0.0D) {
            this.setDeltaMovement(vector3d.multiply(1.0D, 0.5D, 1.0D));
            flag = true;
        }
    }
    if (this.getAttachmentFacing() != Direction.DOWN && !this.isGliding()) {
        this.setNoGravity(true);
        this.setDeltaMovement(vector3d.multiply(0.6D, 0.4D, 0.6D));
    } else {
        this.setNoGravity(false);
    }
    if (prevAttachDir != this.getAttachmentFacing()) {
        attachChangeProgress = 1F;
    }
    this.prevAttachDir = this.getAttachmentFacing();
    if (!this.level().isClientSide) {
        if ((this.getAttachmentFacing() == Direction.UP || this.isGliding()) && !this.isGlidingNavigator) {
            switchNavigator(false);
        }
        if (this.getAttachmentFacing() != Direction.UP && this.isGlidingNavigator) {
            switchNavigator(true);
        }
    }
    BlockPos on = this.blockPosition().relative(this.getAttachmentFacing());
    if (shouldForage() && level().getBlockState(on).is(BlockTags.LEAVES)) {
        BlockState state = level().getBlockState(on);
        if (this.getForagingTime() < 100) {
            if (random.nextInt(2) == 0) {
                for (int i = 0; i < 4 + random.nextInt(2); i++) {
                    double motX = this.random.nextGaussian() * 0.02D;
                    double motY = this.random.nextGaussian() * 0.02D;
                    double motZ = this.random.nextGaussian() * 0.02D;
                    level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, state), on.getX() + random.nextFloat(), on.getY() + random.nextFloat(), on.getZ() + random.nextFloat(), motX, motY, motZ);
                }
            }
            this.setForagingTime(this.getForagingTime() + 1);
        } else {
            if (!this.level().isClientSide) {
                List<ItemStack> lootList = getForageLoot(state);
                if (lootList.size() > 0) {
                    for (ItemStack stack : lootList) {
                        ItemEntity e = this.spawnAtLocation(stack.copy());
                        if(e != null){
                            e.hasImpulse = true;
                            e.setDeltaMovement(e.getDeltaMovement().multiply(0.2, 0.2, 0.2));
                        }
                    }
                }
            }
            this.forageCooldown = 8000 + 8000 * random.nextInt(2);
            this.setForagingTime(0);
        }
    } else {
        this.setForagingTime(0);
    }
    if (detachCooldown > 0) {
        detachCooldown--;
    }
    if (rideCooldown > 0) {
        rideCooldown--;
    }
}

public void tick() {
    super.tick();
    prevClapProgress = clapProgress;
    prevClingProgress = clingProgress;
    prevDistanceToCeiling = this.getDistanceToCeiling();
    boolean clingVisually = this.isClinging() || this.isJumpingUp() || this.jumping;
    if (clingVisually && clingProgress < 5F) {
        clingProgress++;
    }
    if (!clingVisually && clingProgress > 0F && this.getDistanceToCeiling() == 0) {
        clingProgress--;
    }

    final boolean clapping = this.isClapping();
    if (clapping) {
        if (clapProgress < 5F)
            clapProgress++;
    } else {
        if (clapProgress > 0F)
            clapProgress--;
    }

    if (!this.level().isClientSide) {
        float technicalDistToCeiling = calculateDistanceToCeiling();
        float gap = Math.max(technicalDistToCeiling - this.getDistanceToCeiling(), 0F);
        if(this.isClinging()){
            this.setNoGravity(true);
            if (technicalDistToCeiling > MAX_DIST_TO_CEILING || !isAlive() || clingCooldown > 0 || this.isInFluidType()) {
                this.setClinging(false);
            }
            float goal = Math.min(technicalDistToCeiling, MAX_DIST_TO_CEILING);
            if(this.getDistanceToCeiling() < goal){
                this.setDistanceToCeiling(Math.min(goal, prevDistanceToCeiling + 0.15F));
            }
            if(this.getDistanceToCeiling() > goal){
                this.setDistanceToCeiling(Math.max(goal, prevDistanceToCeiling - 0.15F));
            }
            if(this.getDistanceToCeiling() < 1F){
                gap = -0.03F;
            }
            this.setDeltaMovement(this.getDeltaMovement().add(0, gap * 0.5F, 0));
        }else{
            this.setNoGravity(false);
            if (technicalDistToCeiling < MAX_DIST_TO_CEILING && clingCooldown <= 0) {
                this.setClinging(true);
            }
            this.setDistanceToCeiling(Math.max(0, prevDistanceToCeiling - 0.5F));
            if(this.onGround() && clingCooldown <= 0 && !this.isJumpingUp() && this.isAlive() && random.nextFloat() < 0.0085F && technicalDistToCeiling > MAX_DIST_TO_CEILING && !this.level().canSeeSky(this.blockPosition())){
                this.setJumpingUp(true);
            }
        }
    }
    if(this.isJumpingUp()){
        if(this.isAlive() && !this.level().canSeeSky(this.blockPosition()) && (!this.verticalCollision || this.onGround())){
            this.setDistanceToCeiling(1.5F);
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.2F, 0));
            for(int i = 0; i < 3; i++){
                this.level().addParticle(ParticleTypes.SCULK_CHARGE_POP, this.getRandomX(0.5F), this.getY() - 0.2F, this.getRandomZ(0.5F), 0, -0.2F, 0);
            }
        }else{
            this.setJumpingUp(false);
        }
    }
    if(clingCooldown > 0){
        clingCooldown--;
    }
    if(!this.isAlive() || clingCooldown > 0 && this.isClinging()){
        this.setDeltaMovement(this.getDeltaMovement().add(0, -0.25F, 0));
    }
    if (this.isClinging() && !this.isUpsideDownNavigator) {
        switchNavigator(true);
    }
    if (!this.isClinging() && this.isUpsideDownNavigator) {
        switchNavigator(false);
    }
    if(this.isClapping() && this.isAlive() && clingCooldown <= 0){
        float dir = this.isClinging() ? -0.5F : 0.1F;
        if(clapTick % 8 == 0){
            this.playSound(AMSoundRegistry.SKREECHER_CLAP.get(), this.getSoundVolume() * 3F, this.getVoicePitch());
            this.gameEvent(GameEvent.ENTITY_ROAR);
            angerAllNearbyWardens();
            this.level().addParticle(AMParticleRegistry.SKULK_BOOM.get(), this.getX(), this.getEyeY(), this.getZ(), 0, dir, 0);
        }else if(clapTick % 15 == 0){
            this.playSound(AMSoundRegistry.SKREECHER_CALL.get(), this.getSoundVolume() * 4F, this.getVoicePitch());
        }
        if(clapTick >= 100){
            if(!hasAttemptedWardenSpawning && AMConfig.skreechersSummonWarden){
                hasAttemptedWardenSpawning = true;
                BlockPos spawnAt = this.blockPosition().below();
                while(spawnAt.getY() > -64 && !level().getBlockState(spawnAt).isFaceSturdy(level(), spawnAt, Direction.UP)){
                    spawnAt = spawnAt.below();
                }
                Holder<Biome> holder = level().getBiome(spawnAt);
                if(!this.level().isClientSide && getNearbyWardens().isEmpty() && holder.is(AMTagRegistry.SKREECHERS_CAN_SPAWN_WARDENS)){
                    Warden warden = EntityType.WARDEN.create(this.level());

                    warden.moveTo(this.getX(), spawnAt.getY() + 1, this.getZ(), this.getYRot(), 0.0F);
                    warden.finalizeSpawn((ServerLevel)level(), level().getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.TRIGGERED, (SpawnGroupData)null, (CompoundTag)null);
                    warden.setAttackTarget(this);
                    warden.increaseAngerAt(this, 79, false);
                    this.level().addFreshEntity(warden);

                }
            }
        }
        clapTick++;
        if(!this.level().isClientSide){
            if(this.getTarget() != null && this.getTarget().isAlive() && this.hasLineOfSight(this.getTarget()) && !this.getTarget().hasEffect(MobEffects.INVISIBILITY) && !this.hasEffect(MobEffects.BLINDNESS)) {
                double horizDist = this.getTarget().position().subtract(this.position()).horizontalDistance();
                if (horizDist > 20) {
                    this.setClapping(false);
                }
            }else{
                this.setClapping(false);
            }
        }
    }
    if(!this.isClinging() && !hasGroundSize){
        refreshDimensions();
        hasGroundSize = true;
    }
    if(this.isClinging() && hasGroundSize){
        refreshDimensions();
        hasGroundSize = false;
    }
}

public static void onPlayerTick(TickEvent.PlayerTickEvent event){
    Player player = event.player;
    Level world = player.level;
    ISoulEnergy soulEnergy = SEHelper.getCapability(player);
    if (event.phase == TickEvent.Phase.END) {
        SEHelper.getFocusCoolDown(player).tick(player, world);
        if (player.onGround()){
            if (SEHelper.getTicksInAir(player) > 0) {
                SEHelper.setTicksInAir(player, 0);
            }
            if (SEHelper.getAirJumps(player) > 0) {
                SEHelper.setAirJumps(player, 0);
            }
            if (SEHelper.getAirJumpCooldown(player) > 0) {
                SEHelper.setAirJumpCooldown(player, 0);
            }
        } else {
            SEHelper.setTicksInAir(player, SEHelper.getTicksInAir(player) + 1);
        }
        if (SEHelper.getAirJumpCooldown(player) > 0) {
            SEHelper.setAirJumpCooldown(player, SEHelper.getAirJumpCooldown(player) - 1);
        }
        if (SEHelper.getRestPeriod(player) > 0) {
            SEHelper.decreaseRestPeriod(player, 1);
        }
        if (SEHelper.hasResearch(player, ResearchList.FORBIDDEN)){
            if (!SEHelper.hasResearch(player, ResearchList.BURIED)){
                SEHelper.addResearch(player, ResearchList.BURIED);
            }
        }
        if (!soulEnergy.getSEActive() && soulEnergy.getSoulEnergy() > 0) {
            if (!world.isClientSide){
                player.addEffect(new MobEffectInstance(GoetyEffects.SOUL_HUNGER.get(), 60));
                if (player.tickCount % 5 == 0) {
                    SEHelper.decreaseSESouls(player, 1);
                    SEHelper.sendSEUpdatePacket(player);
                }
            }
        }
        if (!player.isUsingItem() || !(WandUtil.getSpell(player) instanceof BurrowingSpell)) {
            BurrowingSpell.resetMiningProgress(world, player);
        }
    }
    if (soulEnergy.getArcaBlock() != null){
        if (soulEnergy.getArcaBlockDimension() == world.dimension()) {
            if (!world.isClientSide){
                ServerLevel serverWorld = (ServerLevel) world;
                BlockPos blockPos = soulEnergy.getArcaBlock();
                BlockEntity tileEntity = world.getBlockEntity(blockPos);
                if (tileEntity instanceof ArcaBlockEntity arcaTile) {
                    if (arcaTile.getPlayer() == player) {
                        RandomSource pRand = world.random;
                        if (pRand.nextInt(12) == 0) {
                            for (int i = 0; i < 3; ++i) {
                                int j = pRand.nextInt(2) * 2 - 1;
                                int k = pRand.nextInt(2) * 2 - 1;
                                double d0 = (double) blockPos.getX() + 0.5D + 0.25D * (double) j;
                                double d1 = (float) blockPos.getY() + pRand.nextFloat();
                                double d2 = (double) blockPos.getZ() + 0.5D + 0.25D * (double) k;
                                double d3 = pRand.nextFloat() * (float) j;
                                double d4 = ((double) pRand.nextFloat() - 0.5D) * 0.125D;
                                double d5 = pRand.nextFloat() * (float) k;
                                serverWorld.sendParticles(ParticleTypes.ENCHANT, d0, d1, d2, 0, d3, d4, d5, 1.0F);
                            }
                        }
                        if (!soulEnergy.getSEActive()) {
                            soulEnergy.setSEActive(true);
                            SEHelper.sendSEUpdatePacket(player);
                        }
                    } else {
                        if (soulEnergy.getSEActive()) {
                            soulEnergy.setSEActive(false);
                            SEHelper.sendSEUpdatePacket(player);
                        }
                    }
                } else {
                    if (soulEnergy.getSEActive()) {
                        soulEnergy.setSEActive(false);
                        SEHelper.sendSEUpdatePacket(player);
                    }
                }
            }
        } else if (soulEnergy.getArcaBlockDimension() == null){
            soulEnergy.setArcaBlockDimension(world.dimension());
            SEHelper.sendSEUpdatePacket(player);
        }
    }
    if (world instanceof ServerLevel) {
        if (soulEnergy.getCameraUUID() != null){
            Entity entity = EntityFinder.getEntityByUuiD(soulEnergy.getCameraUUID());
            if (entity == null || !entity.isAlive()
                    || entity.level.dimension() != player.level.dimension()
                    || player.isShiftKeyDown() || player.hurtTime > 0
                    || !player.isAlive()){
                SEHelper.setCamera(player, null);
            }
        }
        soulEnergy.grudgeList().removeIf(uuid -> {
            Entity entity = EntityFinder.getLivingEntityByUuiD(uuid);
            return (entity instanceof Mob mob && (!mob.isAlive() || mob.isRemoved()));
        });
        soulEnergy.allyList().removeIf(uuid -> {
            Entity entity = EntityFinder.getLivingEntityByUuiD(uuid);
            return (entity instanceof Mob mob && (!mob.isAlive() || mob.isRemoved()));
        });
    }
    if (soulEnergy.getSoulEnergy() < 0){
        soulEnergy.setSoulEnergy(0);
    }
    if (soulEnergy.getGrappling() instanceof VineHook vineHook && vineHook.isAttached()) {
        if (vineHook.isStaff()) {
            player.resetFallDistance();
        }
        Vec3 vec3 = vineHook.position().subtract(player.getEyePosition());
        float f = vineHook.getLength();
        double d = vec3.length();
        if (d > (double)f) {
            double e = d / (double)f * 0.1D;
            player.setDeltaMovement(player.getDeltaMovement().add(vec3.scale(1.0 / d).multiply(e, e * 1.1, e)));
        }
    }
    if (!MobUtil.isSpellCasting(player) && soulEnergy.maxWarding() > 0){
        soulEnergy.setMaxWarding(0);
        soulEnergy.setWarding(0);
    }
}

