public void tick() {
    super.tick();

    this.prevSwimProgress = swimProgress;

    final boolean ground = !this.isInWaterOrBubble();

    if (!ground && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (ground && !this.isLandNavigator) {
        switchNavigator(true);
    }
    if (ground && swimProgress > 0) {
        swimProgress--;
    }
    if (!ground && swimProgress < 5F) {
        swimProgress++;
    }
    if (!this.level().isClientSide) {
        if (isInWater()) {
            swimTimer++;
        } else {
            swimTimer--;
        }
    }

    prevHeadHeight = this.getHeadHeight();
    float neckBase = 5.5F;
    if (!this.isNoAi() && !this.isBaby()) {
        Vec3[] avector3d = new Vec3[this.allParts.length];
        for (int j = 0; j < this.allParts.length; ++j) {
            this.allParts[j].collideWithNearbyEntities();
            avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
        }
        float yaw = this.getYRot() * ((float) Math.PI / 180F);
        float neckContraction = 0.3F * Math.abs(getHeadHeight() / 3) + 0.5F * Math.abs(getHeadYaw(0) / 50F);

        for (int l = 0; l < this.theEntireNeck.length; ++l) {
            float f = l / ((float) this.theEntireNeck.length);
            float f1 = -(2.2F + l - f * neckContraction);
            float f2 = Mth.sin(yaw + (float) Math.toRadians(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
            float f3 = Mth.cos(yaw + (float) Math.toRadians(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
            this.setPartPosition(this.theEntireNeck[l], f2 * f1, neckBase + Math.sin(f * Math.PI * 0.5F) * (getHeadHeight() * -11.1F), -f3 * f1);
        }

        for (int l = 0; l < this.allParts.length; ++l) {
            this.allParts[l].xo = avector3d[l].x;
            this.allParts[l].yo = avector3d[l].y;
            this.allParts[l].zo = avector3d[l].z;
            this.allParts[l].xOld = avector3d[l].x;
            this.allParts[l].yOld = avector3d[l].y;
            this.allParts[l].zOld = avector3d[l].z;
        }
    }
    if (entityToLaunchId != -1 && this.isAlive()) {
        Entity launch = this.level().getEntity(entityToLaunchId);
        this.ejectPassengers();
        entityToLaunchId = -1;
        if (launch != null && !launch.isPassenger()) {
            if (launch instanceof LivingEntity) {
                this.playSound(UPSounds.BRACHI_TOSS.get(), 0.5F, 0.5F);
                launch.setPos(this.getEyePosition().add(0, 1, 0));
                float rot = 180F + this.getYRot();
                float strength = (float) (getLaunchStrength() * (1.0D - ((LivingEntity) launch).getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)));
                float x = Mth.sin(rot * ((float) Math.PI / 180F));
                float z = -Mth.cos(rot * ((float) Math.PI / 180F));
                if (!(strength <= 0.0D)) {
                    launch.hasImpulse = true;
                    Vec3 vec3 = this.getDeltaMovement();
                    Vec3 vec31 = vec3.add((new Vec3(x, 0.0D, z)).normalize().scale(strength));
                    launch.setDeltaMovement(vec31.x, strength, vec31.z);
                }
            }
        }
    }
    if (this.isLaunching()) {
        Entity passenger = this.getControllingPassenger();
        if (passenger instanceof LivingEntity) {
            entityToLaunchId = passenger.getId();
            this.setLaunching(false);
            for (Entity rider : this.getPassengers()) {
                if (rider instanceof Player player) {
                    player.addEffect(new MobEffectInstance(UPEffects.BRACHI_PROTECTION.get(), 200));
                }
            }
        }
    }
    if (!level().isClientSide) {
        if (this.isVehicle()) {
            ridingTime++;
            if (ridingTime >= this.getMaxRidingTime()) {
                this.setLaunching(true);
                this.isLaunching();
            }
        } else {
            ridingTime = 0;
            this.setLaunching(false);
        }
        if (this.isAlive() && ridingTime > 0 && this.getDeltaMovement().horizontalDistanceSqr() > 0.1D && this.isLaunching()) {
            for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                if (!(entity instanceof BrachiosaurusEntity) && !entity.isPassengerOfSameVehicle(this)) {
                    entity.hurt(this.damageSources().mobAttack(this), 4F + random.nextFloat() * 3.0F);
                    if (entity.onGround()) {
                        double d0 = entity.getX() - this.getX();
                        double d1 = entity.getZ() - this.getZ();
                        double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                        float f = 0.5F;
                        entity.push(d0 / d2 * f, f, d1 / d2 * f);
                    }
                }
            }
        }
    }
    if ( headPeakCooldown == 0) {
        float low = getLowHeadHeight();
        this.setHeadHeight(this.getHeadHeight() + (0.5F + ((getLowHeadHeight() + getHighHeadHeight(low)) / 2F) - this.getHeadHeight()) * 0.2F);
    } else {
        if (getMaxFluidHeight() <= this.getBbHeight() * 0.5F && getMaxFluidHeight() >= this.getBbHeight() * 0.25F) {
            float mot = (float) this.getDeltaMovement().lengthSqr();
            this.setHeadHeight(Mth.clamp(this.getHeadHeight() + 0.1F - 0.2F * mot, 0, 2));
            headPeakCooldown = 5;
        }
    }

    this.TailKinematics.calculateTailAngles(this);
}

public static void DeathEvent(LivingDeathEvent event){
    LivingEntity killed = event.getEntity();
    Entity killer = event.getSource().getEntity();
    if (!killed.isRemoved()){
        IOwned owned = null;
        if (killer instanceof IOwned owned1){
            owned = owned1;
        } else if (killed.getLastHurtByMob() instanceof IOwned owned1) {
            owned = owned1;
        }
        if (owned != null) {
            if (owned.getMasterOwner() instanceof ServerPlayer serverPlayer) {
                ModCriteriaTriggers.SERVANT_KILLED_ENTITY.trigger(serverPlayer, killed, event.getSource());
            }
            owned.uncreditedKill(killed);
        }
    }
    RaiderServant raider = null;
    if (killer == null) {
        if (killed.getLastHurtByMob() instanceof RaiderServant servant) {
            raider = servant;
        } else if (MobUtil.getOwner(killed.getLastHurtByMob()) instanceof RaiderServant servant) {
            raider = servant;
        }
    } else if (killer instanceof RaiderServant servant) {
        raider = servant;
    } else if (MobUtil.getOwner(killer) instanceof RaiderServant servant) {
        raider = servant;
    }
    if (raider != null) {
        if (!raider.level.isClientSide) {
            if (raider.isCapturing()) {
                RaiderServant leader = null;
                if (raider.getLeader() != null) {
                    leader = raider.getLeader();
                } else if (raider.isLeader()) {
                    leader = raider;
                }
                LivingEntity owner;
                if (raider.getTrueOwner() != null) {
                    owner = raider.getTrueOwner();
                } else {
                    owner = raider;
                }
                if (killed instanceof AbstractVillager villager && !villager.isBaby()) {
                    Prisoner prisoner = ServantUtil.takePrisoner(villager);
                    if (prisoner != null) {
                        if (leader != null) {
                            prisoner.setTrueOwner(raider.getTrueOwner());
                            prisoner.setLeader(leader);
                        } else {
                            prisoner.setTrueOwner(raider);
                        }
                    }
                } else if (killed instanceof Prisoner prisoner) {
                    if (owner != null) {
                        if (prisoner.getTrueOwner() != owner) {
                            prisoner.setTrueOwner(owner);
                            if (leader != null) {
                                prisoner.setLeader(leader);
                            }
                            if (!prisoner.isSilent()) {
                                prisoner.playSound(SoundEvents.IRON_TRAPDOOR_CLOSE);
                            }
                            prisoner.heal(prisoner.getMaxHealth());
                            event.setCanceled(true);
                        }
                    }
                }
            } else if (raider instanceof AbstractIllagerServant illager) {
                if (illager.level.getGameRules().getBoolean(GameRules.RULE_DOMOBLOOT)) {
                    if (killed instanceof AbstractVillager villager) {
                        int emeralds = illager.level.getRandom().nextIntBetweenInclusive(1, 3);
                        if (villager instanceof Villager villager1 && MobsConfig.IllagerServantLootVillagers.get()) {
                            emeralds += villager1.getVillagerData().getLevel() - 1;
                        } else if (villager instanceof WanderingTrader && MobsConfig.IllagerServantLootTraders.get()) {
                            emeralds *= 2;
                        } else {
                            emeralds = 0;
                        }
                        if (emeralds > 0) {
                            List<ItemStack> list = new ArrayList<>();
                            for (MerchantOffer offer : villager.getOffers()) {
                                if (!offer.isOutOfStock()) {
                                    ItemStack itemStack = offer.assemble();
                                    if (!itemStack.isEmpty()) {
                                        if (itemStack.isStackable()) {
                                            itemStack.setCount(offer.getMaxUses() - offer.getUses());
                                        }
                                        list.add(itemStack);
                                    }
                                }
                            }
                            if (!list.isEmpty()) {
                                for (ItemStack itemStack : list) {
                                    if (illager.getInventory().canAddItem(itemStack)) {
                                        illager.getInventory().addItem(itemStack);
                                    } else {
                                        villager.spawnAtLocation(itemStack);
                                    }
                                }
                            }
                            ItemStack itemStack = new ItemStack(Items.EMERALD, emeralds);
                            if (illager.getInventory().canAddItem(itemStack)) {
                                illager.getInventory().addItem(itemStack);
                            } else {
                                villager.spawnAtLocation(itemStack);
                            }
                        }
                    }
                }
            }
        }
    }

    if (killed instanceof IOwned owned) {
        if (!killed.level.isClientSide) {
            if (owned.canRevive(event.getSource())) {
                Entity revivalTarget = ServantUtil.peekReviveTarget(owned);
                if (revivalTarget != null) {
                    killed.stopRiding();
                    owned.startRevival();
                    event.setCanceled(true);
                }
            }
        }
    }
}

public void tick() {
    tickMultipart();
    super.tick();
    prevInactiveProgress = inactiveProgress;
    prevHeadGroundProgress = headGroundProgress;
    if (this.isInactive() && inactiveProgress < 10.0F) {
        inactiveProgress++;
    }
    if (!this.isInactive() && inactiveProgress > 0.0F) {
        inactiveProgress--;
    }
    if (this.isSlamming() && headGroundProgress < 5.0F) {
        headGroundProgress++;
    }
    if (!this.isSlamming() && headGroundProgress > 0.0F) {
        headGroundProgress--;
    }
    if (damageSustained > 0 && tickCount % 500 == 0) {
        damageSustained--;
    }
    if (this.level().isClientSide) {
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
        } else {
            this.reapplyPosition();
        }
        if(isAlive()){
            AlexsCaves.PROXY.playWorldSound(this, (byte) 14);
        }
    } else if (triggerAdvancement && tickCount % 20 == 0) {
        boolean flag = false;
        double advancementRange = 20.0D;
        for (Player player : level().getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(advancementRange))) {
            if (player.distanceTo(this) < advancementRange) {
                flag = true;
                ACAdvancementTriggerRegistry.FINISHED_QUARRY.triggerForEntity(player);
            }
        }
        triggerAdvancement = !flag;
    }
    if (this.isInactive()) {
        if (!this.isNoGravity()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.2D, 0.0D));
        }
    } else {
        BlockPos quarryPos = getQuarryPos();
        if (quarryActivityTime-- < 0) {
            quarryActivityTime = 20;
            if (quarryPos == null || !level().getBlockState(quarryPos).is(ACBlockRegistry.QUARRY.get())) {
                setQuarryPos(null);
                setInactive(true);
            } else if (level().getBlockEntity(quarryPos) instanceof QuarryBlockEntity quarryBlockEntity) {
                lastMiningArea = quarryBlockEntity.getMiningBox();
            }
        }
        BlockPos targetPos = getTargetPos();
        if (!level().isClientSide) {
            if (targetPos == null) {
                this.setTargetPos(findTarget());
            } else {
                Vec3 dist = Vec3.upFromBottomCenterOf(quarryPos == null ? targetPos : targetPos.atY(quarryPos.getY()), 4).subtract(this.position());
                if (dist.horizontalDistance() < 0.5F) {
                    if (blockBreakCooldown <= 0) {
                        this.setSlamming(true);
                        if (this.headPart.position().distanceTo(Vec3.atBottomCenterOf(targetPos)) < 1.1) {
                            this.setSlamming(false);
                            level().playSound(null, targetPos, ACSoundRegistry.BOUNDROID_SLAM.get(), SoundSource.BLOCKS, 1.5F, 1.0F);
                            level().destroyBlock(targetPos, true);
                            this.setTargetPos(null);
                            blockBreakCooldown = 35;
                            this.setPullingItemsFor(20);
                        }
                    }
                } else {
                    this.setDeltaMovement(this.getDeltaMovement().add(dist.normalize().scale(0.1F)));
                }
            }
        }
    }
    if (this.pullingItemsFor() > 0) {
        int i = this.pullingItemsFor() - 1;
        this.setPullingItemsFor(i);
        BlockPos quarry = getQuarryPos();
        boolean flag = false;
        for (ItemEntity itemEntity : level().getEntitiesOfClass(ItemEntity.class, this.headPart.getBoundingBox().inflate(2, 4, 2))) {
            itemEntity.hasImpulse = true;
            if (!pulledItems.contains(itemEntity)) {
                pulledItems.add(itemEntity);
            }
            flag = true;
        }
        for (ItemEntity itemEntity : pulledItems) {
            if (i == 0) {
                if (quarry != null && level().getBlockState(quarry).is(ACBlockRegistry.QUARRY.get())) {
                    itemEntity.setPos(quarry.getX() + 0.5F, quarry.getY() + 1F, quarry.getZ() + 0.5F);
                    Direction facing = level().getBlockState(quarry).getValue(QuarryBlock.FACING);
                    itemEntity.setDefaultPickUpDelay();
                    itemEntity.setDeltaMovement(new Vec3(facing.getStepX() * 0.1F, 0.4F, facing.getStepZ() * 0.1F));
                }
            } else {
                itemEntity.setPos(this.headPart.position().subtract(0, 0.5, 0));
                itemEntity.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (flag && quarry != null) {
            if (level().getBlockEntity(quarry) instanceof QuarryBlockEntity quarryBlockEntity) {
                quarryBlockEntity.spinFor = 13;
                level().playSound((Player) null, quarry, ACSoundRegistry.QUARRY_CRUSH.get(), SoundSource.BLOCKS, 1.0F, 0.9F + level().random.nextFloat() * 0.2F);
            }
        }
        if (i == 0) {
            pulledItems.clear();
        }
    }
    if (blockBreakCooldown > 0) {
        blockBreakCooldown--;
    }
    if (shakeTime > 0) {
        shakeTime--;
    }
    this.move(MoverType.SELF, this.getDeltaMovement());
    this.setDeltaMovement(this.getDeltaMovement().scale(0.7F));

}

public void tick() {
    super.tick();
    if (!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
        this.setEating(true);
        this.setOrderedToSit(true);
        this.setStanding(false);
    }
    if (isEating() && !this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
        this.setEating(false);
        eatingTime = 0;
        if (!forcedSit) {
            this.setOrderedToSit(true);
        }
    }
    if (isEating()) {
        eatingTime++;
        if (!this.getMainHandItem().is(ItemTags.LEAVES)) {
            for (int i = 0; i < 3; i++) {
                double d2 = this.random.nextGaussian() * 0.02D;
                double d0 = this.random.nextGaussian() * 0.02D;
                double d1 = this.random.nextGaussian() * 0.02D;
                this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
            }
        }
        if (eatingTime % 5 == 0) {
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.PANDA_EAT, this.getSoundVolume(), this.getVoicePitch());
        }
        if (eatingTime > 100) {
            ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
            if (!stack.isEmpty()) {
                this.heal(4);
                if (isTameableFood(stack) && bananaThrowerID != null) {
                    if (getRandom().nextFloat() < 0.3F) {
                        this.setTame(true);
                        this.setOwnerUUID(this.bananaThrowerID);
                        Player player = level().getPlayerByUUID(bananaThrowerID);
                        if (player instanceof ServerPlayer) {
                            CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer)player, this);
                        }
                        this.level().broadcastEntityEvent(this, (byte) 7);
                    } else {
                        this.level().broadcastEntityEvent(this, (byte) 6);
                    }
                }
                if (stack.hasCraftingRemainingItem()) {
                    this.spawnAtLocation(stack.getCraftingRemainingItem());
                }
                stack.shrink(1);
            }
            eatingTime = 0;
        }
    }
    prevSitProgress = sitProgress;
    prevStandProgress = standProgress;

    if (this.isSitting()) {
        if (sitProgress < 10F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (this.isStanding()) {
        if (standProgress < 10F)
            standProgress++;
    } else {
        if (standProgress > 0F)
            standProgress--;
    }

    if (this.isPassenger() && this.getVehicle() instanceof EntityGorilla) {
        if(!this.isBaby()){
            this.removeVehicle();
        }else{
            EntityGorilla mount = (EntityGorilla) this.getVehicle();
            this.setYRot( mount.yBodyRot);
            this.yHeadRot = mount.yBodyRot;
            this.yBodyRot = mount.yBodyRot;
        }
    }
    if (isStanding() && ++standingTime > maxStandTime) {
        this.setStanding(false);
        standingTime = 0;
        maxStandTime = 75 + random.nextInt(50);
    }
    if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
        this.setOrderedToSit(false);
        sittingTime = 0;
        maxSitTime = 75 + random.nextInt(50);
    }
    if (!forcedSit && this.isSitting() && (this.getTarget() != null || this.isStanding()) && !this.isEating()) {
        this.setOrderedToSit(false);
    }
    if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
        maxSitTime = 300 + random.nextInt(250);
        this.setOrderedToSit(true);
    }
    if (this.forcedSit && !this.isVehicle() && this.isTame()) {
        this.setOrderedToSit(true);
    }
    if (sitProgress == 0 && poundChestCooldown <= 0 && this.isSilverback() && random.nextInt(800) == 0 && this.getAnimation() == NO_ANIMATION && !this.isSitting() && !this.isNoAi() && this.getMainHandItem().isEmpty()) {
        this.setAnimation(ANIMATION_POUNDCHEST);
    }
    if (!this.level().isClientSide && this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 10) {
        float f1 = this.getYRot() * Mth.DEG_TO_RAD;
        this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
        getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
        this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
    }
    if (!hasSilverbackAttributes && isSilverback() && !isBaby()) {
        hasSilverbackAttributes = true;
        refreshDimensions();
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(50F);
        this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10F);
        this.heal(50F);
    }
    if (hasSilverbackAttributes && !isSilverback() && !isBaby()) {
        hasSilverbackAttributes = false;
        refreshDimensions();
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30F);
        this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(8F);
        this.heal(30F);
    }
    if(poundChestCooldown > 0){
        poundChestCooldown--;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void onUpdate() {
	if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || (this.getOwner() != null && !this.getOwner().isEntityAlive()))) {
		this.setDead();
		return;
	}

	this.setTriangleSize(this.getTriangleSize());

	this.motionX = 0;
	this.motionY = 0;
	this.motionZ = 0;

	super.onUpdate();

	if(!this.world.isRemote) {
		this.despawnTicks++;
		if(this.despawnTicks >= this.getMaxDespawnTicks()) {
			this.setDead();
		}

		this.rotation += 1.0F;
		this.getDataManager().set(ROTATION, this.rotation);

		List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(this.getTriangleSize()*2, 0, this.getTriangleSize()*2));
		for(EntityLivingBase target : targets) {
			if(target != this.getOwner()) {
				Vec3d[] vertices = this.getTriangleVertices(1);

				if(EntityFortressBoss.rayTraceTriangle(new Vec3d(target.posX - this.posX, 1, target.posZ - this.posZ), new Vec3d(0, -2, 0), vertices[0], vertices[1], vertices[2])) {

					if(this.isPlayerControlled()) {
						IPuppetCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);

						Entity owner = this.getOwner();

						if(cap != null && cap.getPuppeteer() == owner && owner instanceof EntityPlayer) {
							EntityPlayer player = (EntityPlayer) owner;

							IPuppeteerCapability playerCap = player.getCapability(CapabilityRegistry.CAPABILITY_PUPPETEER, null);
							if(playerCap != null) {
								ProtectionShield shield = playerCap.getShield();

								if(shield != null) {
									float healthPercent = 0.3f;

									if(target.getHealth() * (1 - healthPercent) > 5.0f) {
										float healthCost = target.getHealth() * healthPercent;
										float prevHealth = target.getHealth();

										if(target.attackEntityFrom(DamageSource.MAGIC, healthCost) && (prevHealth - target.getHealth()) >= healthCost * 0.5f) {
											List<Integer> indices = new ArrayList<>();
											for(int i = 0; i < 20; i++) {
												indices.add(i);
											}
											Collections.shuffle(indices, this.rand);

											for(int index : indices) {
												if(!shield.isActive(index)) {
													shield.setActive(index, true);
													break;
												}
											}

											this.maxDespawnTicks = this.despawnTicks + 8;
										}
									}
								}
							}
						}
					} else if(target instanceof EntityPlayer)  {
						float damage = (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue();
						if(target.attackEntityFrom(DamageSource.MAGIC, damage) && this.getOwner() != null && this.getOwner() instanceof EntityLivingBase) {
							EntityLivingBase owner = (EntityLivingBase) this.getOwner();
							if(owner.getHealth() < owner.getMaxHealth() - damage) {
								owner.heal(damage * 3.0F);
							}
						}
					}

				}
			}
		}
	} else {
		this.prevRotation = this.rotation;
		this.rotation = this.getDataManager().get(ROTATION);

		for(int c = 0; c < 4; c++) {
			float r1 = this.world.rand.nextFloat();
			float r2 = this.world.rand.nextFloat();
			this.rotation += 15;
			Vec3d[] vertices = this.getTriangleVertices(1);
			this.rotation -= 15;
			double xc = 0, zc = 0;
			for(int i = 0; i < 3; i++) {
				Vec3d vertex = vertices[i];
				switch(i) {
				default:
				case 0:
					xc += vertex.x * (1 - Math.sqrt(r1));
					zc += vertex.z * (1 - Math.sqrt(r1));
					break;
				case 1:
					xc += (Math.sqrt(r1) * (1 - r2)) * vertex.x;
					zc += (Math.sqrt(r1) * (1 - r2)) * vertex.z;
					break;
				case 2:
					xc += (Math.sqrt(r1) * r2) * vertex.x;
					zc += (Math.sqrt(r1) * r2) * vertex.z;
					break;
				}
			}
			Vec3d rp = new Vec3d(xc, vertices[0].y, zc);

			double sx = this.posX + rp.x;
			double sy = this.posY + rp.y + 4;
			double sz = this.posZ + rp.z;
			double ex = this.posX + rp.x;
			double ey = this.posY + rp.y;
			double ez = this.posZ + rp.z;

			if(this.getOwner() != null) {
				sx = this.getOwner().posX;
				sy = this.getOwner().getEntityBoundingBox().minY + (this.getOwner().getEntityBoundingBox().maxY - this.getOwner().getEntityBoundingBox().minY) / 2.0D;
				sz = this.getOwner().posZ;
			}

			if(!this.isPlayerControlled()) {
				this.world.spawnParticle(EnumParticleTypes.PORTAL, sx, sy, sz, ex - sx, ey - sy, ez - sz);
			}
		}
	}
}

public void tick() {
    super.tick();
    prevRunProgress = runProgress;
    prevLeapProgress = leapProgress;
    prevRelaxedProgress = relaxedProgress;
    prevHideProgress = hideProgress;
    prevTailYaw = tailYaw;
    float headPuzzleRot = getPuzzledHeadRot();
    if (isRunning() && runProgress < 5F) {
        runProgress++;
    }
    if (!isRunning() && runProgress > 0F) {
        runProgress--;
    }
    if (isLeaping() && leapProgress < 5F) {
        leapProgress++;
    }
    if (!isLeaping() && leapProgress > 0F) {
        leapProgress--;
    }
    if (getRelaxedFor() > 0 && relaxedProgress < 20F) {
        relaxedProgress++;
    }
    if (getRelaxedFor() <= 0 && relaxedProgress > 0F) {
        relaxedProgress--;
    }
    if (getHideFor() > 0 && hideProgress < 20F) {
        hideProgress++;
    }
    if (getHideFor() <= 0 && hideProgress > 0F) {
        hideProgress--;
    }
    if (isRunning() && !hasRunningAttributes) {
        hasRunningAttributes = true;
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
    }
    if (!isRunning() && hasRunningAttributes) {
        hasRunningAttributes = false;
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
    }
    if (isElder() && !hasElderAttributes) {
        hasElderAttributes = true;
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(32.0D);
        this.getAttribute(Attributes.ARMOR).setBaseValue(5.0D);
        this.heal(36.0F);
    }
    if (!isElder() && hasElderAttributes) {
        hasElderAttributes = false;
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(24.0D);
        this.getAttribute(Attributes.ARMOR).setBaseValue(0.0D);
        this.heal(28.0F);
    }
    if (this.tickCount % (this.getHideFor() > 0 ? 15 : 100) == 0 && this.getHealth() < this.getMaxHealth()) {
        this.heal(2);
    }
    if (!level().isClientSide) {
        puzzledTick(headPuzzleRot);
        if (isStillEnough() && random.nextInt(100) == 0 && this.getAnimation() == NO_ANIMATION && this.getRelaxedFor() <= 0 && !this.isDancing()) {
            Animation idle;
            float rand = random.nextFloat();
            if (rand < 0.45F) {
                idle = ANIMATION_SCRATCH_1;
            } else if (rand < 0.9F) {
                idle = ANIMATION_SCRATCH_2;
            } else {
                idle = ANIMATION_SHAKE;
            }
            this.setAnimation(idle);
        }
        if (fleeTicks > 0) {
            fleeTicks--;
        }
        if (this.isLeaping()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(1.1F, 1, 1.1F));
        }
    }
    if (this.getAnimation() == ANIMATION_CALL_1 && this.getAnimationTick() == 5 || this.getAnimation() == ANIMATION_CALL_2 && this.getAnimationTick() == 4) {
        actuallyPlayAmbientSound();
    }
    if (!level().isClientSide) {
        if (eatHeldItemIn > 0) {
            eatHeldItemIn--;
        } else if (canTargetItem(this.getMainHandItem())) {
            ItemStack stack = this.getMainHandItem();
            this.level().broadcastEntityEvent(this, (byte) 45);
            this.heal(5);
            if (stack.is(ACItemRegistry.DINOSAUR_NUGGET.get()) && justLootedChest) {
                this.setRelaxedForTime(200 + random.nextInt(200));
            }
            if (!this.level().isClientSide) {
                stack.shrink(1);
            }
            justLootedChest = false;
        }
        if (getRelaxedFor() > 0) {
            this.setRelaxedForTime(this.getRelaxedFor() - 1);
        }
        if (getHideFor() > 0) {
            this.setHideFor(this.getHideFor() - 1);
        }
    }
    LivingEntity target = this.getTarget();
    if (target != null && target.isAlive() && !(target instanceof Player player && player.isCreative())) {
        if (this.isElder()) {
            PackAnimal leader = this;
            while (leader.getAfterPackMember() != null) {
                leader = leader.getAfterPackMember();
                if(!((VallumraptorEntity) leader).isAlliedTo(target)){
                    ((VallumraptorEntity) leader).setTarget(target);
                }
            }
        }
        if (this.getHealth() < this.getMaxHealth() * 0.45F && this.isTame() && this.getHideFor() <= 0) {
            int i = 80 + random.nextInt(40);
            this.setHideFor(i);
            this.fleeFromPosition = target.position();
            this.fleeTicks = i;
            if (target instanceof Mob mob) {
                mob.setTarget(null);
                mob.setLastHurtByMob(null);
                mob.setLastHurtMob(null);
            }
        }
        if (target instanceof GrottoceratopsEntity && (tickCount + this.getId()) % 20 == 0 && getPackSize() < 4 && !this.isTame()) {
            this.fleeFromPosition = target.position();
            this.fleeTicks = 100 + random.nextInt(100);
            this.setTarget(null);
            this.setLastHurtByMob(null);
        }
    }
    tailYaw = Mth.approachDegrees(this.tailYaw, yBodyRot, 8);
    prevPuzzleHeadRot = headPuzzleRot;
    AnimationHandler.INSTANCE.updateAnimations(this);
}

	public InteractionResult mobInteract(Player player, @NotNull InteractionHand hand) {
		ItemStack heldItemStack = player.getItemInHand(hand);
		Item item = heldItemStack.getItem();
		Level level = this.level();
		if(player.isDiscrete() && player.getMainHandItem().isEmpty()) {
			if(hand == InteractionHand.MAIN_HAND && WantLoveGoal.canPet(this)) {
				if(level instanceof ServerLevel serverLevel) {
					Vec3 pos = position();
					serverLevel.sendParticles(ParticleTypes.HEART, pos.x, pos.y + 0.5, pos.z, 1, 0, 0, 0, 0.1);
					playSound(QuarkSounds.ENTITY_SHIBA_WHINE, 0.6F, 0.5F + (float) Math.random() * 0.5F);
				}

				WantLoveGoal.setPetTime(this);
				return InteractionResult.sidedSuccess(level.isClientSide);
			}
		}
		else if(level.isClientSide) {
			boolean flag = this.isOwnedBy(player) || this.isTame() || item == Items.BONE && !this.isTame();
			return flag ? InteractionResult.SUCCESS : InteractionResult.PASS;
		} else {
            boolean isPlayerOwner = this.isOwnedBy(player);
			if(this.isTame()) {
				ItemStack mouthItem = getMouthItem();

				if(!mouthItem.isEmpty()) {
					ItemStack copy = mouthItem.copy();
					if(!player.addItem(copy))
						spawnAtLocation(copy);

					if(player.level() instanceof ServerLevel serverLevel) {
						Vec3 pos = position();
						serverLevel.sendParticles(ParticleTypes.HEART, pos.x, pos.y + 0.5, pos.z, 1, 0, 0, 0, 0.1);
						playSound(QuarkSounds.ENTITY_SHIBA_WHINE, 0.6F, 0.5F + (float) Math.random() * 0.5F);
					}
					setMouthItem(ItemStack.EMPTY);
					return InteractionResult.CONSUME;
				}

				if(this.isFood(heldItemStack) && this.getHealth() < this.getMaxHealth()) {
					if(!player.getAbilities().instabuild) {
						heldItemStack.shrink(1);
					}

					this.heal((float) item.getFoodProperties(heldItemStack, this).nutrition());
					return InteractionResult.CONSUME;
				}


                if (item instanceof DyeItem dyeItem) {
                    DyeColor dyecolor = dyeItem.getDyeColor();
                    if (dyecolor != this.getCollarColor()) {
                        this.setCollarColor(dyecolor);
                        if (!player.getAbilities().instabuild) {
                            heldItemStack.shrink(1);
                        }

                        return InteractionResult.CONSUME;
                    }
                }

                if (!heldItemStack.isEmpty() && mouthItem.isEmpty() && (heldItemStack.is(SHIBA_HOLDABLES))) {
                    ItemStack copy = heldItemStack.copy();
                    copy.setCount(1);
                    heldItemStack.setCount(heldItemStack.getCount() - 1);

                    setMouthItem(copy);
                    return InteractionResult.CONSUME;
                }

                if (heldItemStack.is(Items.WOLF_ARMOR) && this.isOwnedBy(player) && this.getBodyArmorItem().isEmpty() && !this.isBaby()) {
                    this.setBodyArmorItem(heldItemStack.copyWithCount(1));
                    heldItemStack.consume(1, player);

                    return InteractionResult.SUCCESS;
                }

                if (heldItemStack.canPerformAction(net.neoforged.neoforge.common.ItemAbilities.SHEARS_REMOVE_ARMOR)
                        && this.isOwnedBy(player) && this.hasArmor()
                        && (!EnchantmentHelper.has(this.getBodyArmorItem(), EnchantmentEffectComponents.PREVENT_ARMOR_CHANGE) || player.isCreative())) {
                    heldItemStack.hurtAndBreak(1, player, getSlotForHand(hand));
                    this.playSound(SoundEvents.ARMOR_UNEQUIP_WOLF);
                    ItemStack itemstack1 = this.getBodyArmorItem();
                    this.setBodyArmorItem(ItemStack.EMPTY);
                    this.spawnAtLocation(itemstack1);

                    return InteractionResult.SUCCESS;
                }

                if (ArmorMaterials.ARMADILLO.value().repairIngredient().get().test(heldItemStack) && this.isInSittingPose()
                        && this.hasArmor() && isPlayerOwner && this.getBodyArmorItem().isDamaged()) {
                    heldItemStack.shrink(1);
                    this.playSound(SoundEvents.WOLF_ARMOR_REPAIR);
                    ItemStack bodyArmor = this.getBodyArmorItem();
                    int repairValue = bodyArmor.getMaxDamage() / 8;
                    bodyArmor.setDamageValue(Math.max(0, bodyArmor.getDamageValue() - repairValue));

                    return InteractionResult.SUCCESS;
                }

                InteractionResult interactionResult = super.mobInteract(player, hand);

                if ((!interactionResult.consumesAction() || this.isBaby()) && isPlayerOwner) {
                    this.setOrderedToSit(!this.isOrderedToSit());
                    this.jumping = false;
                    this.navigation.stop();
                    this.setTarget(null);
                    return InteractionResult.CONSUME;
                }

                return interactionResult;


            } else if(item == Items.BONE) {
				if(!player.getAbilities().instabuild) {
					heldItemStack.shrink(1);
				}

				if(this.random.nextInt(3) == 0 && !EventHooks.onAnimalTame(this, player)) {
					WantLoveGoal.setPetTime(this);

					this.tame(player);
					this.navigation.stop();
					this.setTarget(null);
					this.setOrderedToSit(true);
					level.broadcastEntityEvent(this, (byte) 7);
				} else {
					level.broadcastEntityEvent(this, (byte) 6);
				}

				return InteractionResult.CONSUME;
			}
		}
		return super.mobInteract(player, hand);
	}

    public void travel(@NotNull Vec3 pTravelVector) {
        float baseSpeed;
        if (this.isOrderedToSit()) {
            super.travel(Vec3.ZERO);
            return;
        }
        if (this.isAlive()) {
            // Handle riding movement
            if (this.isVehicle() && this.canBeControlledByRider() && this.isSaddled()
                    && this.getControllingPassenger() instanceof LivingEntity rider) {
                // Mouse controlled yaw
                this.setYRot(rider.getYRot());
                this.yRotO = this.getYRot();
                this.setXRot(rider.getXRot() * 0.5F);
                this.setRot(this.getYRot(), this.getXRot());
                this.yBodyRot = this.getYRot();
                this.yHeadRot = this.yBodyRot;

                float sideway = rider.xxa;
                float forward = rider.zza;
                float vertical = this.isGoingUp() ? 1.0F : this.isGoingDown() ? -1.0F : 0F;

                float speedFactor = 0.6f;
                float waterSpeedFactor = 1.0f;
                float landSpeedFactor = 1.0f;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED) * speedFactor;
                if (this.isInWater()) {
                    if (allowMousePitchControl) {
                        // TODO: travel vector does not match the actual movement direction, might be friction issue again
                        forward = forward * Mth.abs(Mth.cos(this.getXRot() * ((float) Math.PI / 180F)));
                        vertical = forward * Mth.abs(Mth.sin(this.getXRot() * ((float) Math.PI / 180F)));

                        if (isGoingUp() && !isGoingDown()) {
                            vertical = (float) Math.max(vertical, 0.5);
                        } else if (isGoingDown() && !isGoingUp()) {
                            vertical = (float) Math.min(vertical, -0.5);
                        } else if (isGoingUp() && isGoingDown()) {
                            vertical = 0;
                        }
                        // X rotation takes minus on looking upward
                        else if (this.getXRot() < 0) {
                            vertical *= 1;
                        } else if (this.getXRot() > 0) {
                            vertical *= -1;
                        } else if (isControlledByLocalInstance()) {
//                        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.8f, 1.0f));
                        }
                    }
                } else {
                    vertical = (float) pTravelVector.y;
                    speed *= .3f;
                }

                Vec3 travelVector = new Vec3(
                        sideway,
                        vertical,
                        forward
                );
                if (this.isControlledByLocalInstance()) {
                    if (this.isInWater()) {
                        this.flyingSpeed = this.getSpeed() * 0.1f;
                        this.setSpeed(speed);

                        this.moveRelative(this.getSpeed(), travelVector);
                        this.move(MoverType.SELF, this.getDeltaMovement());

                        Vec3 currentMotion = this.getDeltaMovement();
                        if (this.horizontalCollision) {
                            currentMotion = new Vec3(currentMotion.x, 0.2D, currentMotion.z);
                        }
                        this.setDeltaMovement(currentMotion.scale(0.7D));

                        this.calculateEntityAnimation(this, false);


                        // Vanilla travel has a smaller friction factor for Y axis
                        // Add more friction in case moving too fast on Y axis
//                    if (this.isFlying() || this.isHovering()) {
//                        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.92f, 1.0f));
//                    }
                    } else {
                        this.flyingSpeed = this.getSpeed();
                        this.setSpeed(speed);
                        super.travel(new Vec3(sideway, vertical, forward));
                    }

                } else if (rider instanceof Player) {
                    this.setDeltaMovement(Vec3.ZERO);
                    // Disable server side vehicle movement check, in case of console log spam
                    // Happens when stepping up blocks
                    // Might because client & server's onGround flag is out of sync
                    // I can't get it fixed, so it's disabled
                    this.noPhysics = IGNORE_PHYSICS_ON_SERVER;
                }
            } else {

                if (this.isEffectiveAi()) {
                    // Handle AI movement
                    if (this.isInWater()) {
                        this.moveRelative(0.1F, pTravelVector);
                        baseSpeed = 0.6F;
                        float speedBonus = EnchantmentHelper.getDepthStrider(this);
                        if (speedBonus > 3.0F) {
                            speedBonus = 3.0F;
                        }
                        if (!this.onGround) {
                            speedBonus *= 0.5F;
                        }
                        if (speedBonus > 0.0F) {
                            baseSpeed += (0.54600006F - baseSpeed) * speedBonus / 3.0F;
                        }
                        this.move(MoverType.SELF, this.getDeltaMovement());
                        // Friction
                        this.setDeltaMovement(this.getDeltaMovement().multiply(baseSpeed * 0.9D,
                                                                               baseSpeed * 0.9D,
                                                                               baseSpeed * 0.9D
                        ));
                    } else {
                        super.travel(pTravelVector);
                    }
                }
            }
        }
        this.animationSpeedOld = this.animationSpeed;
        double deltaX = this.getX() - this.xo;
        double deltaZ = this.getZ() - this.zo;
        double deltaY = this.getY() - this.yo;
        float delta = Mth.sqrt((float) (deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ)) * 4.0F;
        if (delta > 1.0F) {
            delta = 1.0F;
        }
        this.animationSpeed += (delta - this.animationSpeed) * 0.4F;
        this.animationPosition += this.animationSpeed;

    }

public void render(GuiGraphics guiHelper, DeltaTracker deltaTracker) {
    if (Minecraft.getInstance().options.hideGui || Minecraft.getInstance().player.isSpectator() || !active) {
        return;
    }
    var screenWidth = guiHelper.guiWidth();
    var screenHeight = guiHelper.guiHeight();

    var minecraft = Minecraft.getInstance();
    Player player = minecraft.player;

    if (player == null || minecraft.screen != null || minecraft.mouseHandler.isMouseGrabbed()) {
        close();
        return;
    }

    var swsm = ClientMagicData.getSpellSelectionManager();
    int totalSpellsAvailable = swsm.getSpellCount();

    if (totalSpellsAvailable <= 0) {
        close();
        return;
    }
    PoseStack poseStack = guiHelper.pose();
    poseStack.pushPose();
    float guiScale = 1f;
    if (ClientConfigs.SPELL_WHEEL_CONSISTENT_SIZE.get()) {
        float invertedGuiScaleFactor = (float) (1 / minecraft.getWindow().getGuiScale());
        float physicalScaleFactor = Math.min(minecraft.getWindow().getScreenWidth() / 1920f, minecraft.getWindow().getScreenHeight() / 1080f);
        guiScale = invertedGuiScaleFactor * physicalScaleFactor * 3 * ClientConfigs.SPELL_WHEEL_SCALE.get().floatValue();
    }
    int centerX = screenWidth / 2;
    int centerY = screenHeight / 2;
    poseStack.translate(centerX, centerY, 0);
    poseStack.scale(guiScale, guiScale, 1);
    centerX = 0;
    centerY = 0;


    Vec2 screenCenter = new Vec2(minecraft.getWindow().getScreenWidth() * .5f, minecraft.getWindow().getScreenHeight() * .5f);
    Vec2 mousePos = new Vec2((float) minecraft.mouseHandler.xpos(), (float) minecraft.mouseHandler.ypos());
    double radiansPerSpell = Math.toRadians(360 / (float) totalSpellsAvailable);

    float mouseRotation = (Utils.getAngle(mousePos, screenCenter) + 1.570f + (float) radiansPerSpell * .5f) % 6.283f;

    wheelSelection = (int) Mth.clamp(mouseRotation / radiansPerSpell, 0, totalSpellsAvailable - 1);
    if (mousePos.distanceToSqr(screenCenter) < ringOuterEdgeMin * ringOuterEdgeMin) {
        wheelSelection = Math.max(0, swsm.getSelectionIndex());
    }

    guiHelper.fill(0, 0, screenWidth, screenHeight, 0);
    //RenderSystem.enableBlend();
    //RenderSystem.defaultBlendFunc();
    //final Tesselator tesselator = Tesselator.getInstance();
    //final BufferBuilder buffer = tesselator.getBuilder();
    //buffer.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_COLOR);

    drawRadialBackgrounds(guiHelper, centerX, centerY, wheelSelection);
    drawDividingLines(guiHelper, centerX, centerY);

    //tesselator.end();
    //RenderSystem.disableBlend();

    //Text background
    var selectedSpell = swsm.getSpellData(wheelSelection);
    var spellLevel = selectedSpell.getSpell().getLevelFor(selectedSpell.getLevel(), player);
    var font = Minecraft.getInstance().font;
    var info = selectedSpell.getSpell().getUniqueInfo(spellLevel, minecraft.player);
    int textHeight = Math.max(3, info.size()) * font.lineHeight + 5;
    int textCenterMargin = 5;
    int textTitleMargin = 5;
    var spell = selectedSpell.getSpell();
    var title = spell.getDisplayName(minecraft.player).withStyle(Style.EMPTY.withUnderlined(true));
    var level = Component.translatable("ui.irons_spellbooks.level", TooltipsUtils.getLevelComponenet(selectedSpell, player).withStyle(spell.getRarity(spellLevel).getDisplayName().getStyle()));
    var mana = Component.translatable("ui.irons_spellbooks.mana_cost", selectedSpell.getSpell().getManaCost(spellLevel)).withStyle(ChatFormatting.AQUA);
    var cooldownTicks = MagicManager.getEffectiveSpellCooldown(spell, player, swsm.getSpellSlot(wheelSelection).getCastSource());
    var cooldownTime = Component.translatable("tooltip.irons_spellbooks.cooldown_length_seconds", Utils.timeFromTicks(cooldownTicks, 2)).withStyle(ChatFormatting.YELLOW);

    drawTextBackground(guiHelper, centerX, centerY, ringOuterEdge + textHeight - textTitleMargin - font.lineHeight, textCenterMargin, Math.max(2, info.size()) * font.lineHeight);
    guiHelper.drawString(font, title, (int) (centerX - font.width(title) / 2), (int) (centerY - (ringOuterEdge + textHeight)), 0xFFFFFF, true);
    int infoHeight = (int) (centerY - (ringOuterEdge + textHeight) + font.lineHeight + textTitleMargin);
    guiHelper.drawString(font, level, (int) (centerX - font.width(level) - textCenterMargin), infoHeight, 0xFFFFFF, true);
    if (spell.getManaCost(spellLevel) > 0) {
        infoHeight += font.lineHeight;
        guiHelper.drawString(font, mana, (int) (centerX - font.width(mana) - textCenterMargin), infoHeight, 0xFFFFFF, true);
    }
    if (cooldownTicks > 0) {
        infoHeight += font.lineHeight;
        guiHelper.drawString(font, cooldownTime, (int) (centerX - font.width(cooldownTime) - textCenterMargin), infoHeight, 0xFFFFFF, true);
    }

    for (int i = 0; i < info.size(); i++) {
        var line = info.get(i);
        guiHelper.drawString(font, line, (int) (centerX + textCenterMargin), (int) (centerY - (ringOuterEdgeMax + textHeight) + font.lineHeight * (i + 1) + textTitleMargin), 0x3be33b, true);
    }

    //Spell Icons
    float scale = Mth.lerp(totalSpellsAvailable / 15f, 2, 1.25f) * .65f;
    double radius = 3 / scale * (ringInnerEdge + ringInnerEdge) * .5 * (.85f + .25f * (totalSpellsAvailable / 15f));
    Vec2[] locations = new Vec2[totalSpellsAvailable];
    for (int i = 0; i < locations.length; i++) {
        locations[i] = new Vec2((float) (Math.sin(radiansPerSpell * i) * radius), (float) (-Math.cos(radiansPerSpell * i) * radius));
    }
    for (int i = 0; i < locations.length; i++) {
        var currentSpell = swsm.getSpellData(i);
        if (currentSpell != null) {
            var texture = currentSpell.getSpell().getSpellIconResource();
            poseStack.pushPose();
            poseStack.translate(centerX, centerY, 0);
            poseStack.scale(scale, scale, scale);

            //Icon
            int iconWidth = 16 / 2;
            int borderWidth = 32 / 2;
            int cdWidth = 16 / 2;
            guiHelper.blit(texture, (int) locations[i].x - iconWidth, (int) locations[i].y - iconWidth, 0, 0, 16, 16, 16, 16);
            /*
            Border
             */
            guiHelper.blit(TEXTURE, (int) locations[i].x - borderWidth, (int) locations[i].y - borderWidth, swsm.getSelectionIndex() == i ? 32 : 0, 106, 32, 32);
            /*
            Cooldown
             */
            float f = ClientMagicData.getCooldownPercent(currentSpell.getSpell());
            if (f > 0) {
                RenderSystem.enableBlend();
                int pixels = (int) (16 * f + 1f);
                guiHelper.blit(TEXTURE, (int) locations[i].x - cdWidth, (int) locations[i].y + cdWidth - pixels, 47, 87, 16, pixels);
            }
            poseStack.popPose();
        }
    }


    poseStack.popPose();
}

public void onUpdate() {
	double prevMotionX = this.motionX;
	double prevMotionZ = this.motionZ;

	if(this.isEntityInsideOpaqueBlock()) {
		this.setSize(this.width, 0.95F);
	} else {
		this.setSize(this.width, 1.2F);
	}

	if(this.isRolling()) {
		this.stepHeight = 1.1F;
	} else {
		this.stepHeight = 0.6F;
	}

	super.onUpdate();

	if(!this.world.isRemote) {
		if(this.getHideout() != null && !this.isValidHideoutBlock(this.getHideout())) {
			this.setHideout(null);
		}

		if(this.getAIMoveSpeed() > 0.3F && this.moveForward != 0) {
			this.dataManager.set(ROLL_SPEED, 0.05F + (this.getAIMoveSpeed() - 0.3F) / 3.0F);
			if(!this.rollSoundPlayed) {
				this.playRollSound();
			}
			this.rollSoundPlayed = true;
		} else {
			this.dataManager.set(ROLL_SPEED, 0.0F);
			this.rollSoundPlayed = false;
		}

		IAttributeInstance attackAttribute = this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE);

		if(this.isRolling()) {
			if(this.collidedHorizontally) {
				boolean pg = this.onGround;
				double pmx = this.motionX;
				double pmy = this.motionY;
				double pmz = this.motionZ;
				double px = this.posX;
				double py = this.posY;
				double pz = this.posZ;

				this.move(MoverType.SELF, MathHelper.clamp(prevMotionX, -4, 4), 0, 0);

				boolean cx = Math.abs(this.posX - px) < Math.abs(MathHelper.clamp(prevMotionX, -4, 4)) / 2.0D;

				this.onGround = pg;
				this.motionX = pmx;
				this.motionY = pmy;
				this.motionZ = pmz;
				this.setPosition(px, py, pz);

				this.move(MoverType.SELF, 0, 0, MathHelper.clamp(prevMotionZ, -4, 4));

				boolean cz = Math.abs(this.posZ - pz) < Math.abs(MathHelper.clamp(prevMotionZ, -4, 4)) / 2.0D;

				this.onGround = pg;
				this.motionX = pmx;
				this.motionY = pmy;
				this.motionZ = pmz;
				this.setPosition(px, py, pz);

				this.onRollIntoWall(cx, cz, MathHelper.clamp(prevMotionX, -4, 4), MathHelper.clamp(prevMotionZ, -4, 4));
			}

			attackAttribute.removeModifier(ROLLING_ATTACK_MODIFIER_ATTRIBUTE_UUID);
			attackAttribute.applyModifier(new AttributeModifier(ROLLING_ATTACK_MODIFIER_ATTRIBUTE_UUID, "Rolling attack modifier", Math.min(Math.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ) * 20.0F, 10.0F), 0));

			Vec3d motionDir = new Vec3d(this.motionX, 0, this.motionZ).normalize();
			List<Entity> collidingEntities = this.world.getEntitiesInAABBexcluding(this, this.getEntityBoundingBox().grow(0.35D, 0, 0.35D), EntitySelectors.getTeamCollisionPredicate(this));
			for(Entity collidingEntity : collidingEntities) {
				if(collidingEntity.hurtResistantTime <= 0) {
					double dot = motionDir.dotProduct(collidingEntity.getPositionVector().subtract(this.getPositionVector()));
					if(dot >= -0.5D && dot <= Math.sqrt(this.width * this.width) * 0.5D) {
						if(this.attackEntityAsMob(collidingEntity) && collidingEntity instanceof EntityLivingBase) {
							((EntityLivingBase) collidingEntity).knockBack(this, (float) Math.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ) * 3.0F, -this.motionX, -this.motionZ);

							if(collidingEntity instanceof EntityPlayerMP) {
								AdvancementCriterionRegistry.ROLLED_OVER_BY_BOULDER_SPRITE.trigger((EntityPlayerMP) collidingEntity);
							}
						}
					}
				}
			}
		} else {
			attackAttribute.removeModifier(ROLLING_ATTACK_MODIFIER_ATTRIBUTE_UUID);
		}

		if(this.rollingTicks > 0 && this.rollingDir != null) {
			double speed;
			if(this.rollingDuration - this.rollingTicks < this.rollingAccelerationTime) {
				speed = 0.5D + (this.rollingSpeed - 0.5D) / this.rollingAccelerationTime * (this.rollingDuration - this.rollingTicks);
			} else if(this.rollingTicks < this.rollingDecelerationTime) {
				speed = 0.5D + (this.rollingSpeed - 0.5D) / this.rollingDecelerationTime * this.rollingTicks;
			} else {
				speed = this.rollingSpeed;
			}

			this.getMoveHelper().setMoveTo(this.posX + this.rollingDir.x, this.posY, this.posZ + this.rollingDir.z, speed);

			this.rollingTicks--;
		}
	} else {
		if(this.isEntityAlive() && this.isRolling()) {
			this.setRollSpeed(this.dataManager.get(ROLL_SPEED));
		}

		this.updateRollAnimationState();

		if(this.onGround) {
			double particleTiming = 0.75D;
			if(this.prevRollAnimation % 1 < particleTiming && this.rollAnimation % 1 >= particleTiming) {
				BlockPos posBelow = this.getPosition().down();
				IBlockState stateBelow = this.world.getBlockState(posBelow);
				if(!stateBelow.getBlock().isAir(stateBelow, this.world, posBelow)) {
					int stateId = Block.getStateId(stateBelow);
					int betweenstoneId = Block.getStateId(BlockRegistry.BETWEENSTONE.getDefaultState());
					for(int i = 0; i < 28; i++) {
						double dx = this.rand.nextDouble() - 0.5D;
						double dz = this.rand.nextDouble() - 0.5D;
						this.world.spawnParticle(EnumParticleTypes.BLOCK_DUST, this.posX + this.motionX + dx, this.posY - 0.2D, this.posZ + this.motionZ + dz, dx * 0.3D, 0.3D, dz * 0.3D, stateId);
					}
					for(int i = 0; i < 12; i++) {
						double dx = this.rand.nextDouble() - 0.5D;
						double dz = this.rand.nextDouble() - 0.5D;
						this.world.spawnParticle(EnumParticleTypes.BLOCK_DUST, this.posX + this.motionX + dx, this.posY - 0.2D, this.posZ + this.motionZ + dz, dx * 0.3D, 0.3D, dz * 0.3D, betweenstoneId);
					}
				}
			}
		}
	}
}

public void tick() {
    super.tick();
    prevShootProgress = shootProgress;
    prevFlyProgress = flyProgress;
    prevFlutterPitch = this.getFlutterPitch();
    prevSitProgress = sitProgress;
    float extraMotionSlow = 1.0F;
    float extraMotionSlowY = 1.0F;
    this.yBodyRot = this.getYRot();
    this.yHeadRot = this.getYRot();
    prevFlutterPitch = this.getFlutterPitch();
    prevTentacleProgress = this.tentacleProgress;

    if (isFlying()) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (isSitting()) {
        if (sitProgress < 5F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (tentacleProgress < 5F && entityData.get(TENTACLING)) {
        tentacleProgress++;
    }

    if(tentacleProgress == 5F && !entityData.get(TENTACLING)){
        if (squishCooldown == 0 && this.isFlying()) {
            squishCooldown = 10;
            this.playSound(AMSoundRegistry.FLUTTER_FLAP.get(), this.getSoundVolume(), 1.5F * this.getVoicePitch());
        }
    }
    if (tentacleProgress > 0F && !entityData.get(TENTACLING)) {
        tentacleProgress--;
    }
    this.FlutterRotation += this.rotationVelocity;
    if ((double) this.FlutterRotation > (Mth.TWO_PI)) {
        if (this.level().isClientSide) {
            this.FlutterRotation = Mth.TWO_PI;
        } else {
            this.FlutterRotation = (float) ((double) this.FlutterRotation - (Mth.TWO_PI));
            if (this.random.nextInt(10) == 0) {
                this.rotationVelocity = 1.0F / (this.random.nextFloat() + 1.0F) * 0.5F;
            }
            this.level().broadcastEntityEvent(this, (byte) 19);
        }
    }
    if (this.FlutterRotation < Mth.PI) {
        float f = this.FlutterRotation / Mth.PI;
        if ((double) f >= 0.95F) {
            this.entityData.set(TENTACLING, true);
            if (squishCooldown == 0 && this.isFlying()) {
                squishCooldown = 10;
                this.gameEvent(GameEvent.ENTITY_ROAR);
                this.playSound(AMSoundRegistry.FLUTTER_FLAP.get(), 3F, 1.5F * this.getVoicePitch());
            }
            this.randomMotionSpeed = 0.8F;
        } else {
            this.entityData.set(TENTACLING, false);
            randomMotionSpeed = 0.01F;
        }
    }
    if (!this.level().isClientSide) {
        if (isFlying() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!isFlying() && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (this.isFlying()) {
            this.setDeltaMovement(this.getDeltaMovement().x * this.randomMotionSpeed * extraMotionSlow, this.getDeltaMovement().y * this.randomMotionSpeed * extraMotionSlowY, this.getDeltaMovement().z * this.randomMotionSpeed * extraMotionSlow);
            timeFlying++;
            if (this.onGround() && timeFlying > 20 || this.isSitting()) {
                this.setFlying(false);
            }
        } else {
            timeFlying = 0;
        }
    }
    if (!this.onGround() && this.getDeltaMovement().y < 0.0D) {
        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0D, 0.8D, 1.0D));
    }
    if (this.isFlying()) {
        float dist = (float) ((Math.abs(this.getDeltaMovement().x()) + Math.abs(this.getDeltaMovement().z())) * 30);
        this.incrementFlutterPitch(-dist);
        if (this.horizontalCollision) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.2F, 0));
        }
    }
    if (this.getFlutterPitch() > 0F) {
        float decrease = Math.min(2.5F, this.getFlutterPitch());
        this.decrementFlutterPitch(decrease);
    }
    if (this.getFlutterPitch() < 0F) {
        float decrease = Math.min(2.5F, -this.getFlutterPitch());
        this.incrementFlutterPitch(decrease);
    }
    boolean shooting = entityData.get(SHOOTING);
    if (shooting && shootProgress < 5) {
        shootProgress += 1;
    }
    if (!shooting && shootProgress > 0) {
        shootProgress -= 1;
    }
    if (shooting) {
        this.incrementFlutterPitch(-30);
    }
    if (!this.level().isClientSide && shooting && shootProgress == 5F) {
        if (this.getTarget() != null) {
            this.spit(this.getTarget());
        }
        this.entityData.set(SHOOTING, false);
    }
    if (this.hasPotStats && !this.isPotted()) {
        this.hasPotStats = false;
        this.getAttribute(Attributes.ARMOR).setBaseValue(0.21D);
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.21D);
    }
    if (!this.hasPotStats && this.isPotted()) {
        this.hasPotStats = true;
        this.getAttribute(Attributes.ARMOR).setBaseValue(16.0D);
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.18D);
    }
    if (this.entityData.get(SHAKING_HEAD_TICKS) > 0) {
        this.entityData.set(SHAKING_HEAD_TICKS, this.entityData.get(SHAKING_HEAD_TICKS) - 1);
    }
    if(squishCooldown > 0){
        squishCooldown--;
    }
}

public void tick() {
    super.tick();
    prevFaceCameraProgress = faceCameraProgress;
    prevLaserLvl = this.getLaserAttackLvl();
    if (this.getAnimation() == ANIMATION_EMERGE) {
        this.setHasEmerged(true);
        faceCameraProgress = 1F;
    } else if (faceCameraProgress > 0.0F) {
        faceCameraProgress = Math.max(0, faceCameraProgress - 0.2F);
    }
    prevAngryProgress = angryProgress;
    for (int i = 0; i < HANDS; i++) {
        prevClaspProgress[i] = claspProgress[i];
        prevStrikeProgress[i] = strikeProgress[i];
    }
    if (this.posPointer < 0) {
        for (int i = 0; i < this.positions.length; ++i) {
            this.positions[i][0] = this.getX();
            this.positions[i][1] = this.getY();
            this.positions[i][2] = this.getZ();
            this.positions[i][3] = this.yBodyRot;
        }
    }
    if (++this.posPointer == this.positions.length) {
        this.posPointer = 0;
    }
    this.positions[this.posPointer][0] = this.getX();
    this.positions[this.posPointer][1] = this.getY();
    this.positions[this.posPointer][2] = this.getZ();
    this.positions[this.posPointer][3] = this.yBodyRot;
    if (this.isAngry() && angryProgress < 5F) {
        angryProgress++;
    }
    if (!this.isAngry() && angryProgress > 0F) {
        angryProgress--;
    }
    if (this.isAlive()) {
        if (random.nextInt(isAngry() ? 12 : 40) == 0 && claspingHand == -1) {
            int i = Mth.clamp(random.nextInt(HANDS), 0, 3);
            if (claspProgress[i] == 0) {
                claspingHand = i;
            }
        }
        if (claspingHand >= 0) {
            if (claspProgress[claspingHand] < 5F) {
                claspProgress[claspingHand]++;
            } else {
                claspingHand = -1;
            }
        } else {
            for (int i = 0; i < HANDS; i++) {
                if (claspProgress[i] > 0) {
                    claspProgress[i]--;
                }
            }
        }
        if (!this.hasEmerged()) {
            this.setInvisible(true);
            if(this.level().hasNearbyAlivePlayer(this.getX(), this.getY(), this.getZ(), 9)){
                this.setAnimation(ANIMATION_EMERGE);
            }
        }else{
            this.setInvisible(this.hasEffect(MobEffects.INVISIBILITY));
        }
        if (this.getAnimation() == ANIMATION_EMERGE) {
            if(this.level().isClientSide){
                this.level().addParticle(AMParticleRegistry.STATIC_SPARK.get(), this.getRandomX(0.75F), this.getRandomY(), this.getRandomZ(0.75F), (this.getRandom().nextFloat() - 0.5F) * 0.2F, this.getRandom().nextFloat() * 0.2F, (this.getRandom().nextFloat() - 0.5F) * 0.2F);
            }
            if(this.getAnimationTick() == 1){
                this.playSound(AMSoundRegistry.FARSEER_EMERGE.get(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        LivingEntity target = this.getTarget();
        if (target != null) {
            if (this.entityData.get(MELEEING)) {
                if (meleeCooldown == 0) {
                    meleeCooldown = 5;
                    int i = random.nextInt(HANDS);
                    this.isStriking[i] = true;
                    this.level().broadcastEntityEvent(this, (byte) (40 + i));
                }
            }
        }
        if (meleeCooldown > 0) {
            meleeCooldown--;
        }
        for (int i = 0; i < HANDS; i++) {
            if (!this.isStriking[i] || !this.entityData.get(MELEEING)) {
                if (strikeProgress[i] > 0F) {
                    strikeProgress[i]--;
                }
            } else if (this.isStriking[i]) {
                if (strikeProgress[i] < 5F) {
                    strikeProgress[i]++;
                }
                if (strikeProgress[i] == 5F) {
                    isStriking[i] = false;
                    this.level().broadcastEntityEvent(this, (byte) (44 + i));
                    if (target != null && distanceTo(target) <= 4F) {
                        target.hurt(this.damageSources().mobAttack(this), 5 + random.nextInt(5));
                    }
                }
            }
        }

        if (this.hasLaser()) {
            LivingEntity livingentity = this.getLaserTarget();
            if (livingentity != null) {
                Vec3 hit = this.calculateLaserHit(livingentity.getEyePosition());
                this.entityData.set(LASER_DISTANCE, (float) hit.distanceTo(this.getEyePosition()));
                this.getLookControl().setLookAt(livingentity, 90.0F, 90.0F);
                this.getLookControl().tick();
                double d0 = hit.x - this.getX();
                double d1 = hit.y - this.getEyeY();
                double d2 = hit.z - this.getZ();
                double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                d0 = d0 / d3;
                d1 = d1 / d3;
                d2 = d2 / d3;
                float progress = this.getLaserAttackLvl() / (float) LASER_ATTACK_DURATION;
                double d4 = this.random.nextDouble();
                while (d4 < d3 * progress) {
                    d4 += 0.5F + 2F * this.random.nextDouble();
                    double width = d4 / (d3 * progress);
                    double d5 = (random.nextDouble() - 0.5F) * width;
                    double d6 = (random.nextDouble() - 0.5F) * width;
                    this.level().addParticle(AMParticleRegistry.STATIC_SPARK.get(), this.getX() + d0 * d4 + d5, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4 + d6, (this.getRandom().nextFloat() - 0.5F) * 0.2F, this.getRandom().nextFloat() * 0.2F, (this.getRandom().nextFloat() - 0.5F) * 0.2F);
                }
            }
        }
    }
    if (this.isAngry()) {
        angryShakeVec = new Vec3(random.nextFloat() - 0.5F, random.nextFloat() - 0.5F, random.nextFloat() - 0.5F);
    } else {
        angryShakeVec = Vec3.ZERO;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    super.tick();
    if (localMimic != this.getPrevMimickedBlock()) {
        localMimic = this.getPrevMimickedBlock();
        colorShiftProgress = 0.0F;
    }
    if (localMimicState != this.getPrevMimicState()) {
        localMimicState = this.getPrevMimicState();
        transProgress = 0.0F;
    }

    if (this.isInWater()) {
        if (this.isLandNavigator)
            switchNavigator(false);
    } else {
        if (!this.isLandNavigator)
            switchNavigator(true);
    }

    BlockPos pos = AMBlockPos.fromCoords(this.getX(), this.getEyeY() - 1F, this.getZ());
    boolean ground = level().getBlockState(pos).isFaceSturdy(level(), pos, Direction.UP) && this.getMimicState() != MimicState.GUARDIAN || !this.isInWaterOrBubble() || this.isSitting();
    this.prevTransProgress = transProgress;
    this.prevColorShiftProgress = colorShiftProgress;
    this.prevGroundProgress = groundProgress;
    this.prevSitProgress = sitProgress;
    if (this.getPrevMimicState() != this.getMimicState() && transProgress < 5.0F) {
        transProgress += 0.25F;
    }
    if (this.getPrevMimicState() == this.getMimicState() && transProgress > 0F) {
        transProgress -= 0.25F;
    }
    if (getPrevMimickedBlock() != this.getMimickedBlock() && colorShiftProgress < 5.0F) {
        colorShiftProgress += 0.25F;
    }
    if (getPrevMimickedBlock() == this.getMimickedBlock() && colorShiftProgress > 0F) {
        colorShiftProgress -= 0.25F;
    }
    if (ground && groundProgress < 5F) {
        groundProgress += 0.5F;
    }
    if (!ground && groundProgress > 0F) {
        groundProgress -= 0.5F;
    }
    if (isSitting() && sitProgress < 5F) {
        sitProgress += 0.5F;
    }
    if (!isSitting() && sitProgress > 0F) {
        sitProgress -= 0.5F;
    }
    if (this.isInWaterOrBubble()) {
        float f2 = (float) -((float) this.getDeltaMovement().y * 3 * (double) Mth.RAD_TO_DEG);
        this.setXRot(f2);
    }
    if (camoCooldown > 0) {
        camoCooldown--;
    }
    if (mimicCooldown > 0) {
        mimicCooldown--;
    }
    if (stopMimicCooldown > 0) {
        stopMimicCooldown--;
    }
    if (this.isNoAi()) {
        this.setAirSupply(this.getMaxAirSupply());
    } else {
        if (this.isInWaterRainOrBubble() || this.getMainHandItem().getItem() == Items.WATER_BUCKET) {
            this.setMoistness(60000);
        } else {
            this.setMoistness(this.getMoistness() - 1);
            if (this.getMoistness() <= 0 && moistureAttackTime-- <= 0) {
                this.setOrderedToSit(false);
                this.hurt(damageSources().dryOut(), random.nextInt(2) == 0 ? 1.0F : 0F);
                moistureAttackTime = 20;
            }
        }
    }
    if (camoCooldown <= 0 && random.nextInt(300) == 0) {
        mimicEnvironment();
        camoCooldown = this.getRandom().nextInt(2200) + 200;
    }
    if ((this.getMimicState() != MimicState.OVERLAY || this.getMimickedBlock() != null) && stopMimicCooldown == 0 && !this.isStopChange()) {
        this.setMimicState(MimicState.OVERLAY);
        this.setMimickedBlock(null);
        stopMimicCooldown = -1;
    }
    if (this.level().isClientSide && exclaimTime > 0) {
        exclaimTime--;
        if (exclaimTime == 0) {
            Entity e = level().getEntity(this.entityData.get(LAST_SCARED_MOB_ID));
            if (e != null && transProgress >= 5.0F) {
                double d2 = this.random.nextGaussian() * 0.1D;
                double d0 = this.random.nextGaussian() * 0.1D;
                double d1 = this.random.nextGaussian() * 0.1D;
                this.level().addParticle(AMParticleRegistry.SHOCKED.get(), e.getX(), e.getEyeY() + e.getBbHeight() * 0.15F + (double) (this.random.nextFloat() * e.getBbHeight() * 0.15F), e.getZ(), d0, d1, d2);
            }
        }
    }

    if (this.hasGuardianLaser()) {
        if (this.guardianLaserTime < 30) {
            ++this.guardianLaserTime;
        }
        LivingEntity livingentity = this.getGuardianLaser();
        if (livingentity != null && this.isInWaterOrBubble()) {
            this.getLookControl().setLookAt(livingentity, 90.0F, 90.0F);
            this.getLookControl().tick();
            double d5 = this.getLaserAttackAnimationScale(0.0F);
            double d0 = livingentity.getX() - this.getX();
            double d1 = livingentity.getY(0.5D) - this.getEyeY();
            double d2 = livingentity.getZ() - this.getZ();
            double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
            d0 = d0 / d3;
            d1 = d1 / d3;
            d2 = d2 / d3;
            double d4 = this.random.nextDouble();
            while (d4 < d3) {
                d4 += 1.8D - d5 + this.random.nextDouble() * (1.7D - d5);
                this.level().addParticle(ParticleTypes.BUBBLE, this.getX() + d0 * d4, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4, 0.0D, 0.0D, 0.0D);
            }
            if (guardianLaserTime == 30) {
                livingentity.hurt(this.damageSources().mobAttack(this), 5);
                guardianLaserTime = 0;
                this.entityData.set(UPGRADED_LASER_ENTITY_ID, -1);
            }
        }
    }
    if (!this.level().isClientSide && tickCount % 40 == 0) {
        this.heal(2);
    }
/*if(!world.isRemote){
        if(ticksExisted % 80 == 0){
            mimicEnvironment();
        }else if(ticksExisted % 40 == 0){
            this.setMimicState(MimicState.OVERLAY);
            this.setMimickedBlock(null);
        }
    }*/
}

    public void tick() {
        super.tick();
        if(this.passiveFor > 0){
            passiveFor--;
        }
        if (this.isInWater()) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        this.prevStrangleProgress = strangleProgress;
        if (this.isStrangling()) {
            if (strangleProgress < 5F)
                strangleProgress++;
        } else {
            if (strangleProgress > 0F)
                strangleProgress--;
        }

        this.yBodyRot = this.getYRot();
        this.yHeadRot = Mth.clamp(this.yHeadRot, this.yBodyRot - 70, this.yBodyRot + 70);

        if (this.isStrangling()) {
            if (!level().isClientSide && this.getTarget() != null && this.getTarget().isAlive()) {
                this.setXRot(0);
                final LivingEntity target = this.getTarget();
                final float radius = this.getTarget().getBbWidth() * -0.5F;
                final float angle = (Maths.STARTING_ANGLE * (target.yBodyRot - 45F));
                final double extraX = radius * Mth.sin(Mth.PI + angle);
                final double extraZ = radius * Mth.cos(angle);
                Vec3 targetVec = new Vec3(extraX + target.getX(), target.getY(1.0F), extraZ + target.getZ());
                Vec3 moveVec = targetVec.subtract(this.position()).scale(1F);
                this.setDeltaMovement(moveVec);
                if (!target.onGround()) {
                    target.setDeltaMovement(new Vec3(0, -0.08F, 0));
                } else {
                    target.setDeltaMovement(Vec3.ZERO);
                }
                if (strangleTimer >= 40 && strangleTimer % 20 == 0) {
                    final double health = Mth.clamp(this.getTarget().getMaxHealth(), 4, 50);
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) Math.max(4F, 0.25F * health));
                }
                if (this.getTarget() == null || !this.getTarget().isAlive()) {
                    strangleTimer = 0;
                    this.setStrangling(false);
                }
            }
            fallDistance = 0;
            strangleTimer++;
            this.setNoGravity(true);
        } else {
            this.setNoGravity(false);
        }
        if (this.ringBufferIndex < 0) {
            for (int i = 0; i < this.ringBuffer.length; ++i) {
                this.ringBuffer[i] = this.getYRot();
            }
        }
        this.ringBufferIndex++;
        if (this.ringBufferIndex == this.ringBuffer.length) {
            this.ringBufferIndex = 0;
        }
        this.ringBuffer[this.ringBufferIndex] = this.getYRot();

        if (!this.level().isClientSide) {
            final int segments = 7;
            final Entity child = getChild();
            if (child == null) {
                LivingEntity partParent = this;
                parts = new EntityAnacondaPart[segments];
                AnacondaPartIndex partIndex = AnacondaPartIndex.HEAD;
                Vec3 prevPos = this.position();
                for (int i = 0; i < segments; i++) {
                    final float prevReqRot = calcPartRotation(i) + getYawForPart(i);
                    final float reqRot = calcPartRotation(i + 1) + getYawForPart(i);
                    EntityAnacondaPart part = new EntityAnacondaPart(AMEntityRegistry.ANACONDA_PART.get(), this);
                    part.setParent(partParent);
                    part.copyDataFrom(this);
                    part.setBodyIndex(i);
                    part.setPartType(AnacondaPartIndex.sizeAt(1 + i));
                    if (partParent == this) {
                        this.setChildId(part.getUUID());
                        this.entityData.set(CHILD_ID, part.getId());
                    }
                    if (partParent instanceof EntityAnacondaPart) {
                        ((EntityAnacondaPart) partParent).setChildId(part.getUUID());
                    }
                    part.setPos(part.tickMultipartPosition(this.getId(), partIndex, prevPos, this.getXRot(), prevReqRot, reqRot, false));
                    partParent = part;
                    level().addFreshEntity(part);
                    parts[i] = part;
                    partIndex = part.getPartType();
                    prevPos = part.position();
                }
            }
            if (shouldReplaceParts() && this.getChild() instanceof EntityAnacondaPart) {
                parts = new EntityAnacondaPart[segments];
                parts[0] = (EntityAnacondaPart) this.getChild();
                this.entityData.set(CHILD_ID, parts[0].getId());
                int i = 1;
                while (i < parts.length && parts[i - 1].getChild() instanceof EntityAnacondaPart) {
                    parts[i] = (EntityAnacondaPart) parts[i - 1].getChild();
                    i++;
                }
            }
            AnacondaPartIndex partIndex = AnacondaPartIndex.HEAD;
            Vec3 prev = this.position();
            float xRot = this.getXRot();
//                float yRot = this.getYRot();
//                float headRot = Mth.wrapDegrees(this.getYRot());
            for (int i = 0; i < segments; i++) {
                if (this.parts[i] != null) {
                    final float prevReqRot = calcPartRotation(i) + getYawForPart(i);
                    final float reqRot = calcPartRotation(i + 1) + getYawForPart(i);
                    parts[i].setStrangleProgress(this.strangleProgress);
                    parts[i].copyDataFrom(this);
                    prev = parts[i].tickMultipartPosition(this.getId(), partIndex, prev, xRot, prevReqRot, reqRot, true);
                    partIndex = parts[i].getPartType();
                    xRot = parts[i].getXRot();
                }
            }

            if (isInWater()) swimTimer = Math.max(swimTimer + 1, 0);
            else swimTimer = Math.min(swimTimer - 1, 0);
        }
        if (shedCooldown > 0) {
            shedCooldown--;
        }
        if (this.getSheddingTime() > 0) {
            this.setSheddingTime(this.getSheddingTime() - 1);
            if (this.getSheddingTime() == 0) {
                this.spawnItemAtOffset(new ItemStack(AMItemRegistry.SHED_SNAKE_SKIN.get()), 1 + random.nextFloat(), 0.2F);
                shedCooldown = 1000 + random.nextInt(2000);
            }
        }
    }

public void tick() {
    super.tick();
    float leftPropellerRot = getLeftPropellerRot();
    float rightPropellerRot = getRightPropellerRot();
    float backPropellerRot = getBackPropellerRot();
    if (controlDownTicks > 0 || this.getDamageLevel() >= 4 && !this.onGround()) {
        this.setDeltaMovement(this.getDeltaMovement().add(0, -0.08, 0));
        controlDownTicks--;
    } else if (controlUpTicks > 0 && getWaterHeight() > 1.5F) {
        this.setDeltaMovement(this.getDeltaMovement().add(0, 0.08, 0));
        controlUpTicks--;
    }
    if (this.tickCount % 200 == 0 && damageSustained > 0) {
        damageSustained--;
    }
    this.xRotO = this.getXRot();
    this.yRotO = Mth.wrapDegrees(this.getYRot());
    this.prevSonarFlashAmount = sonarFlashAmount;
    if(this.getDangerAlertTicks() > 0 && sonarFlashAmount < 1.0F){
        sonarFlashAmount += 0.25F;
    }
    if(this.getDangerAlertTicks() <= 0 && sonarFlashAmount > 0.0F){
        sonarFlashAmount -= 0.25F;
    }
    if(this.getDangerAlertTicks() > 0 && this.getDamageLevel() <= 3 && this.isVehicle() && tickCount % 20 == 0){
        this.playSound(ACSoundRegistry.SUBMARINE_SONAR.get());
    }
    if(this.getDamageLevel() > 0 && this.isVehicle()){
        if(creakTime-- <= 0){
            creakTime = 500 - (this.getDamageLevel() * 120) + random.nextInt(60);
            this.playSound(ACSoundRegistry.SUBMARINE_CREAK.get());
        }
    }
    float acceleration = this.getAcceleration();
    if (this.level().isClientSide) {
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
        } else {
            this.reapplyPosition();
        }
        Player player = AlexsCaves.PROXY.getClientSidePlayer();
        if (player != null && player.isPassengerOfSameVehicle(this)) {
            if (AlexsCaves.PROXY.isKeyDown(0) && controlUpTicks < 2) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 0));
                controlUpTicks = 10;
            }
            if (AlexsCaves.PROXY.isKeyDown(1) && controlDownTicks < 2) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 1));
                controlDownTicks = 10;
            }
            if (AlexsCaves.PROXY.isKeyDown(2) && floodlightToggleCooldown <= 0) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
                floodlightToggleCooldown = 5;
            }
        }
        if (this.isVehicle() && this.isInWaterOrBubble() && this.isAlive()) {
            AlexsCaves.PROXY.playWorldSound(this, (byte) 15);
        }
    } else {
        if (acceleration < 0.0F) {
            this.setAcceleration(Math.min(0F, acceleration + 0.01F));
        }
        if (acceleration > 0.0F) {
            this.setAcceleration(Math.max(0F, acceleration - 0.01F));
        }
        if (Math.abs(acceleration) > 0) {
            Vec3 vec3 = new Vec3(0, 0, Mth.clamp(acceleration, -0.25F, TOP_SPEED) * 0.2F).xRot(-this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYRot() * ((float) Math.PI / 180F));
            this.setDeltaMovement(this.getDeltaMovement().add(vec3));
        }
        if (this.isInWaterOrBubble()) {
            this.move(MoverType.SELF, this.getDeltaMovement());
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.8F, 0.8F, 0.8F));
        } else {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.5F, 0));
            this.move(MoverType.SELF, this.getDeltaMovement().scale(0.9F));
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.1F, 0.3F, 0.1F));
        }
        if (!isWaxed() && this.getOxidizationLevel() < 3) {
            if (oxidizeTime > 0) {
                oxidizeTime--;
            } else {
                resetOxidizeTime();
                this.setOxidizationLevel(this.getOxidizationLevel() + 1);
            }
        }
        if(this.getDangerAlertTicks() > 0){
            this.setDangerAlertTicks(this.getDangerAlertTicks() - 1);
        }
    }
    float xRotSet = Mth.clamp(-(float) this.getDeltaMovement().y * 2F, -1.0F, 1.0F) * -(float) (180F / (float) Math.PI) * (float) Math.signum(getAcceleration() + 0.01);
    float rot = acceleration * 30 + Math.signum(acceleration) * 15;

    this.setBackPropellerRot(backPropellerRot + rot);
    this.setLeftPropellerRot(leftPropellerRot + rot + (turnLeftTicks > 0 ? 5 * turnLeftTicks : 0));
    this.setRightPropellerRot(rightPropellerRot + rot + (turnRightTicks > 0 ? 5 * turnRightTicks : 0));

    if (this.getWaterHeight() >= 1.5F) {
        if (Math.abs(getAcceleration()) > 0.05F) {
            Vec3 bubblesAt = new Vec3(0F, 0.3F, -2F).xRot((float) Math.toRadians(this.getXRot())).yRot((float) Math.toRadians(-this.getYRot()));
            for (int i = 0; i < 1 + random.nextInt(4); i++) {
                float offsetX = 0.5F - random.nextFloat();
                float offsetY = 0.5F - random.nextFloat();
                float offsetZ = 0.5F - random.nextFloat();
                level().addParticle(ParticleTypes.BUBBLE_COLUMN_UP, this.getX() + offsetX + bubblesAt.x, this.getY(0.5F) + offsetY + bubblesAt.y, this.getZ() + offsetZ + bubblesAt.z, 0, 0, 0);
            }
        }
        if (submergedTicks < 10) {
            submergedTicks++;
        }
    } else if (submergedTicks > 0) {
        submergedTicks = 0;
    }
    if (floodlightToggleCooldown > 0) {
        floodlightToggleCooldown--;
    }
    if (turnLeftTicks > 0) {
        turnLeftTicks--;
    }
    if (turnRightTicks > 0) {
        turnRightTicks--;
    }
    if (shakeTime > 0) {
        shakeTime--;
    }
    if(wereLightsOn != this.areLightsOn()){
        this.playSound(wereLightsOn ? ACSoundRegistry.SUBMARINE_LIGHT_OFF.get() :  ACSoundRegistry.SUBMARINE_LIGHT_ON.get());
        wereLightsOn = this.areLightsOn();
    }
    this.setXRot(ACMath.approachRotation(this.getXRot(), Mth.clamp(getDamageLevel() >= 4 ? 0 : xRotSet, -50, 50), 2));
    prevLeftPropellerRot = leftPropellerRot;
    prevRightPropellerRot = rightPropellerRot;
    prevBackPropellerRot = backPropellerRot;

}

public boolean interact(EntityPlayer entityplayer)
{
	ItemStack itemstack = entityplayer.inventory.getCurrentItem();

	//before ownership check 
	if ((itemstack != null) && getIsTamed() && ((itemstack.itemID == MoCreatures.scrollOfOwner.itemID)) 
			&& MoCreatures.proxy.enableResetOwnership && MoCTools.isThisPlayerAnOP(entityplayer))
	{
		if (--itemstack.stackSize == 0)
		{
			entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
		}
		if (MoCreatures.isServer())
		{
			if (MoCreatures.proxy.enableOwnership) 
			{
				EntityPlayer epOwner = this.worldObj.getPlayerEntityByName(this.getOwnerName());
				if (epOwner != null)
				{
					MoCTools.reduceTamedByPlayer(epOwner);
				}
				else
				{
					MoCTools.reduceTamedByOfflinePlayer(this.getOwnerName());
				}
			}
			this.setOwner("");

		}
		return true;
	}
	//if the player interacting is not the owner, do nothing!
	if (MoCreatures.proxy.enableOwnership && getOwnerName() != null && !getOwnerName().equals("") && !entityplayer.username.equals(getOwnerName())) 
	{
		//System.out.println("Player " + entityplayer + " attempted interaction. Denies as " + getOwnerName() + " is the owner");
		return true; 
	}

	//changes name
	if ((itemstack != null) && getIsTamed() //&& MoCreatures.isServer()
			&& ((itemstack.itemID == MoCreatures.medallion.itemID) || (itemstack.itemID == Item.book.itemID)))
	{
		if (MoCreatures.isServer())
		{
			MoCTools.tameWithName((EntityPlayerMP) entityplayer, this);
		}
		//TODO NAMER
		/*if (!MoCreatures.isServer())
		{
			MoCreatures.proxy.setName(entityplayer, this);
		}*/
		return true;
	}

	//sets it free, untamed
	if ((itemstack != null) && getIsTamed() 
			&& ((itemstack.itemID == MoCreatures.scrollFreedom.itemID)))
	{
		if (--itemstack.stackSize == 0)
		{
			entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
		}
		if (MoCreatures.isServer())
		{

			if (MoCreatures.proxy.enableOwnership) MoCTools.reduceTamedByPlayer(entityplayer);
			this.setOwner("");
			this.setName("");
			this.dropMyStuff();
			this.setTamed(false);
		}

		return true;
	}

	//removes owner, any other player can claim it by renaming it
	if ((itemstack != null) && getIsTamed() 
				&& ((itemstack.itemID == MoCreatures.scrollOfSale.itemID)))
	{
		if (--itemstack.stackSize == 0)
		{
			entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
		}
		if (MoCreatures.isServer())
		{

			if (MoCreatures.proxy.enableOwnership) MoCTools.reduceTamedByPlayer(entityplayer);
			this.setOwner("");
		}

		return true;
	}
	//heals
	if ((itemstack != null) && getIsTamed() && isMyHealFood(itemstack))
	{
		if (--itemstack.stackSize == 0)
		{
			entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
		}
		worldObj.playSoundAtEntity(this, "eating", 1.0F, 1.0F + ((rand.nextFloat() - rand.nextFloat()) * 0.2F));
		if (MoCreatures.isServer())
		{
			health = getMaxHealth();
		}
		return true;
	}

	//attaches rope
	if ((itemstack != null) && (riddenByEntity == null) && (roper == null) && getIsTamed() && (itemstack.itemID == MoCreatures.rope.itemID))
	{
		if (--itemstack.stackSize == 0)
		{
			entityplayer.inventory.setInventorySlotContents(entityplayer.inventory.currentItem, null);
		}
		worldObj.playSoundAtEntity(this, "roping", 1.0F, 1.0F + ((rand.nextFloat() - rand.nextFloat()) * 0.2F));
		roper = entityplayer;
		setEating(false);
		return true;
	}

	//removes rope
	if ((roper != null) && getIsTamed())
	{
		entityplayer.inventory.addItemStackToInventory(new ItemStack(MoCreatures.rope));
		worldObj.playSoundAtEntity(this, "roping", 1.0F, 1.0F + ((rand.nextFloat() - rand.nextFloat()) * 0.2F));
		roper = null;
		return true;
	}

	if ((itemstack != null) && getIsTamed() && (itemstack.itemID == Item.shears.itemID))
	{
		if (MoCreatures.isServer())
		{
			dropMyStuff();
		}

		return true;
	}
	return false;
}

