public void tick() {
    super.tick();

    this.prevAttackProgress = attackProgress;
    this.prevBirdPitch = birdPitch;
    this.prevTackleProgress = tackleProgress;
    this.prevFlyProgress = flyProgress;
    this.prevFlapAmount = flapAmount;
    this.prevSwoopProgress = swoopProgress;
    this.prevSitProgress = sitProgress;
    float yMot = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
    this.birdPitch = yMot;

    if (isFlying()) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (isTackling()) {
        if (tackleProgress < 5F)
            tackleProgress++;
    } else {
        if (tackleProgress > 0F)
            tackleProgress--;
    }

    final boolean sit = isSitting() || this.isPassenger();
    if (sit) {
        if (sitProgress < 5F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (this.isLaunched()) {
        launchTime++;
    } else {
        launchTime = 0;
    }

    if (lastPlayerControlTime > 0) {
        lastPlayerControlTime--;
    }
    if (lastPlayerControlTime <= 0) {
        controlledFlag = false;
    }

    if (yMot < 0.1F) {
        flapAmount = Math.min(-yMot * 0.2F, 1F);
        if (swoopProgress > 0) {
            swoopProgress--;
        }
    } else {
        if (flapAmount > 0.0F) {
            flapAmount -= Math.min(flapAmount, 0.1F);
        } else {
            flapAmount = 0;
        }
        if (swoopProgress < yMot * 0.2F) {
            swoopProgress = Math.min(yMot * 0.2F, swoopProgress + 1);
        }
    }

    if (this.isTackling()) {
        flapAmount = Math.min(2, flapAmount + 0.2F);
    }

    if (!this.level().isClientSide) {
        if (isFlying()) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        if (tackleCapCooldown == 0 && this.isTackling() && !this.isVehicle() && (this.getTarget() == null || !this.getTarget().isAlive())) {
            this.setTackling(false);
        }

        if (isFlying()) {
            timeFlying++;
            this.setNoGravity(true);
            if (this.isSitting() || this.isPassenger() || this.isInLove()) {
                if (!isLaunched()) {
                    this.setFlying(false);
                }
            }
            if (this.getTarget() != null && this.getTarget().getY() < this.getX() && !this.isVehicle()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(1.0, 0.9, 1.0));
            }
        } else {
            timeFlying = 0;
            this.setNoGravity(false);
        }

        if (this.isInWaterOrBubble() && this.isVehicle()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.1F, 0));
        }

        if (this.isSitting() && !this.isLaunched()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.1F, 0));
        }

        if (this.getTarget() != null && this.isInWaterOrBubble()) {
            timeFlying = 0;
            this.setFlying(true);
        }

        if (this.onGround() && this.timeFlying > 30 && isFlying() && !this.isInWaterOrBubble()) {
            this.setFlying(false);
        }
    }

    final int attackTick = this.entityData.get(ATTACK_TICK);
    if (attackTick > 0) {
        if (attackTick == 2 && this.getTarget() != null && this.distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + 2D) {
            this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
        }
        this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
        if (attackProgress < 5F) {
            attackProgress++;
        }
    } else {
        if (attackProgress > 0F) {
            attackProgress--;
        }
    }

    if (this.isPassenger()) {
        this.setFlying(false);
        this.setTackling(false);
    }

    if (boardingCooldown > 0) {
        boardingCooldown--;
    }
    if (returnControlTime > 0) {
        returnControlTime--;
    }
    if (tackleCapCooldown > 0) {
        tackleCapCooldown--;
    }
}

public void tick() {
    super.tick();
    prevJumpProgress = jumpProgress;
    prevReboundProgress = reboundProgress;
    prevSleepProgress = sleepProgress;
    prevInterestedProgress = interestedProgress;
    prevTransformTime = this.transformsIn();

    if (!this.level().isClientSide) {
        this.entityData.set(JUMP_ACTIVE, !this.onGround());
    }

    if (this.entityData.get(JUMP_ACTIVE) && !isInWaterOrBubble()) {
        if (jumpProgress < 5F) {
            jumpProgress += 0.5F;
            if (reboundProgress > 0) {
                reboundProgress--;
            }
        }
        if (jumpProgress >= 5F) {
            if (reboundProgress < 5F) {
                reboundProgress += 0.5F;
            }
        }
    } else {
        if (reboundProgress > 0) {
            reboundProgress = Math.max(reboundProgress - 1F, 0);
        }
        if (jumpProgress > 0) {
            jumpProgress = Math.max(jumpProgress - 1F, 0);
        }
    }

    if (this.isSleepingPose()) {
        if (sleepProgress < 5F)
            sleepProgress++;
    } else {
        if (sleepProgress > 0F)
            sleepProgress--;
    }

    if (this.isBegging()) {
        if (interestedProgress < 5F)
            interestedProgress++;
    } else {
        if (interestedProgress > 0F)
            interestedProgress--;
    }

    if (!this.level().isClientSide) {
        final LivingEntity target = this.getTarget();
        if (target != null && target.isAlive()) {
            if (this.isSleeping()) {
                this.setSleeping(false);
            }
            final double dist = this.distanceTo(target);
            boolean flag = false;
            if (this.getAnimationTick() == 5) {
                if (dist < 3.5D && this.getAnimation() == ANIMATION_BELLY) {
                    for (final LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(2.0D))) {
                        if ((entity == target || entity instanceof Monster) && !entity.getType().is(AMTagRegistry.BUNFUNGUS_IGNORE_AOE_ATTACKS)) {
                            flag = true;
                            launch(entity);
                            entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                        }
                    }
                } else if (dist < 2.5D && this.getAnimation() == ANIMATION_SLAM) {
                    for (final LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(2.0D))) {
                        if ((entity == target || entity instanceof Monster) && !entity.getType().is(AMTagRegistry.BUNFUNGUS_IGNORE_AOE_ATTACKS)) {
                            flag = true;
                            entity.knockback(0.2F, entity.getX() - this.getX(), entity.getZ() - this.getZ());
                            entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                        }
                    }
                }
            }
            if (flag) {
                this.playSound(AMSoundRegistry.BUNFUNGUS_ATTACK.get(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        if (this.tickCount % 40 == 0) {
            this.heal(1);
        }
    }
    if (this.getAnimation() == NO_ANIMATION && this.isCarrot(this.getItemInHand(InteractionHand.MAIN_HAND))) {
        this.setAnimation(ANIMATION_EAT);
    }
    if (this.getAnimation() == ANIMATION_EAT) {
        if (this.getAnimationTick() % 4 == 0) {
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
        }
        if (this.getAnimationTick() >= 18) {
            ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
            if (!stack.isEmpty()) {
                stack.shrink(1);
                this.setCarroted(true);
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1000));
                this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1000, 1));
                this.heal(8);
            }
        } else {
            for (int i = 0; i < 3; i++) {
                final double d2 = this.random.nextGaussian() * 0.02D;
                final double d0 = this.random.nextGaussian() * 0.02D;
                final double d1 = this.random.nextGaussian() * 0.02D;
                this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
            }
        }
    }
    if (!this.level().isClientSide) {
        if (this.transformsIn() > 0) {
            this.setTransformsIn(this.transformsIn() - 1);
        }
    }

    if (this.level().isClientSide) {
        if (isRabbitForm()){
            for (int i = 0; i < 3; i++) {
                final double d2 = this.random.nextGaussian() * 0.02D;
                final double d0 = this.random.nextGaussian() * 0.02D;
                final double d1 = this.random.nextGaussian() * 0.02D;
                final float f1 = (EntityBunfungus.MAX_TRANSFORM_TIME - this.transformsIn()) / (float)EntityBunfungus.MAX_TRANSFORM_TIME;
                final float scale = f1 * 0.5F + 0.15F;
                this.level().addParticle(AMParticleRegistry.BUNFUNGUS_TRANSFORMATION.get(), this.getRandomX(scale), this.getY(this.random.nextDouble() * scale), this.getRandomZ(scale), d0, d1, d2);
            }
        }

        if (isSleeping() && random.nextFloat() < 0.3F) {
            final double d0 = this.random.nextGaussian() * 0.02D;
            final float radius = this.getBbWidth() * (0.7F + random.nextFloat() * 0.1F);
            final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
            final double extraX = radius * Mth.sin(Mth.PI + angle) + random.nextFloat() * 0.5F - 0.25F;
            final double extraZ = radius * Mth.cos(angle) + random.nextFloat() * 0.5F - 0.25F;
            ParticleOptions data = random.nextFloat() < 0.3F ? AMParticleRegistry.BUNFUNGUS_TRANSFORMATION.get() : AMParticleRegistry.FUNGUS_BUBBLE.get();
            this.level().addParticle(data, this.getX() + extraX, this.getY() + random.nextFloat() * 0.1F, this.getZ() + extraZ, 0, d0, 0);
        }
    } else {
        if (this.level().isDay() && this.getTarget() == null && !this.isBegging() && !this.isInWaterOrBubble()) {
            if (tickCount % 10 == 0 && this.getRandom().nextInt(300) == 0) {
                this.setSleeping(true);
            }
        } else if (this.isSleeping()) {
            this.setSleeping(false);
        }
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

