public InteractionResult mobInteract(Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);
	Item item = stack.getItem();

	Holder<SlabfishVariant> slabfishVariant = this.getVariant();

	if (item == Items.WATER_BUCKET && this.isAlive() && !(this.isTame() && !player.isSecondaryUseActive())) {
		this.dropLeash(true, true);
		if (this.hasBackpack())
			this.dropBackpack();
		return Bucketable.bucketMobPickup(player, hand, this).get();
	}

	if (stack.is(ItemTags.CREEPER_DROP_MUSIC_DISCS)) {
		this.usePlayerItem(player, hand, stack);
		this.playBurpSound();
		this.particleCloud(ParticleTypes.NOTE);
		this.dropItem(EnvironmentalItems.MUSIC_DISC_SLABRAVE.get());
		return InteractionResult.SUCCESS;
	}

	if (this.isTame()) {
		Registry<SlabfishBackpack> backpacks = SlabfishHelper.slabfishBackpacks(this.registryAccess());
		if (this.hasBackpack() && SlabfishHelper.getBackpackType(backpacks, stack).isPresent() && !SlabfishHelper.getBackpackType(backpacks, stack).get().is(this.getBackpack().get())) {
			if (!this.level().isClientSide()) {
				ItemStack previousBackpack = this.slabfishBackpack.getItem(2);

				if (!previousBackpack.isEmpty()) {
					Containers.dropItemStack(this.level(), this.getX(), this.getY(), this.getZ(), previousBackpack.copy());
					this.slabfishBackpack.removeItemNoUpdate(2);
				}

				this.slabfishBackpack.setItem(2, new ItemStack(item));
				this.usePlayerItem(player, hand, stack);
				this.playBackpackDyeSound();
			}
			return InteractionResult.SUCCESS;
		}

		Registry<SlabfishSweater> sweaters = SlabfishHelper.slabfishSweaters(this.registryAccess());
		if (SlabfishHelper.getSweaterType(sweaters, stack).isPresent() && !player.isSecondaryUseActive() && (!this.hasSweater() || !SlabfishHelper.getSweaterType(sweaters, stack).get().is(this.getSweater().get()))) {
			if (!this.level().isClientSide()) {
				ItemStack previousSweater = this.slabfishBackpack.getItem(0);
				if (!previousSweater.isEmpty()) {
					Containers.dropItemStack(this.level(), this.getX(), this.getY(), this.getZ(), previousSweater.copy());
					this.slabfishBackpack.removeItemNoUpdate(0);
				}
				this.slabfishBackpack.setItem(0, new ItemStack(item));
				this.usePlayerItem(player, hand, stack);
			}
			return InteractionResult.SUCCESS;
		}

		if (stack.is(Tags.Items.CHESTS_WOODEN) && !this.hasBackpack()) {
			if (!this.level().isClientSide()) {
				this.slabfishBackpack.setItem(1, new ItemStack(item));
				this.usePlayerItem(player, hand, stack);
				if (player instanceof ServerPlayer serverPlayer)
					EnvironmentalCriteriaTriggers.BACKPACK_SLABFISH.get().trigger(serverPlayer);
			}
			return InteractionResult.SUCCESS;
		}

		if (item == Items.SHEARS && this.hasSweater() && !player.isSecondaryUseActive()) {
			ItemStack previousSweater = this.slabfishBackpack.getItem(0);
			if (!previousSweater.isEmpty()) {
				Containers.dropItemStack(this.level(), this.getX(), this.getY(), this.getZ(), previousSweater.copy());
				this.slabfishBackpack.removeItemNoUpdate(0);
			}
			return InteractionResult.SUCCESS;
		}

		if (player.isSecondaryUseActive() && stack.is(Tags.Items.TOOLS_SHEAR) && this.hasBackpack()) {
			this.dropBackpack();
			return InteractionResult.SUCCESS;
		}

		if (this.isFood(stack) && this.getHealth() < this.getMaxHealth()) {
			this.usePlayerItem(player, hand, stack);
			this.level().playLocalSound(this.getX(), this.getY(), this.getZ(), EnvironmentalSoundEvents.SLABFISH_EAT.get(), SoundSource.NEUTRAL, 1F, 1F, true);
			this.heal(item.getFoodProperties(stack, player).nutrition());
			this.particleCloud(ParticleTypes.COMPOSTER);
			return InteractionResult.SUCCESS;
		}

		if (Ingredient.of(EnvironmentalItemTags.SLABFISH_SNACKS).test(stack)) {
			stack.finishUsingItem(this.level(), this);
			this.level().playLocalSound(this.getX(), this.getY(), this.getZ(), EnvironmentalSoundEvents.SLABFISH_EAT.get(), SoundSource.NEUTRAL, 1F, 1F, true);
			return InteractionResult.SUCCESS;
		}

		if (this.isFood(stack)) {
			int i = this.getAge();
			if (!this.level().isClientSide && i == 0 && this.canFallInLove()) {
				this.usePlayerItem(player, hand, stack);
				this.setInLove(player);
				return InteractionResult.SUCCESS;
			}

			if (this.isBaby()) {
				this.usePlayerItem(player, hand, stack);
				this.ageUp((int) ((float) (-i / 20) * 0.1F), true);
				return InteractionResult.sidedSuccess(this.level().isClientSide);
			}

			if (this.level().isClientSide) {
				return InteractionResult.CONSUME;
			}
		}

		if (!this.isOrderedToSit() && this.isOwnedBy(player) && player.isSecondaryUseActive() && !this.isInWater()) {
			this.setOwnerUUID(player.getUUID());
			if (!this.level().isClientSide())
				this.setOrderedToSit(true);
			return InteractionResult.SUCCESS;
		}

		if (this.isOrderedToSit() && this.isOwnedBy(player) && player.isSecondaryUseActive()) {
			if (!this.level().isClientSide())
				this.setOrderedToSit(false);
			return InteractionResult.SUCCESS;
		}

		if (!player.isSecondaryUseActive()) {
			if (!this.level().isClientSide()) {
				openGui((ServerPlayer) player);
			}
			return InteractionResult.SUCCESS;
		}

	} else if (stack.is(EnvironmentalItemTags.SLABFISH_TAME_ITEMS)) {
		if (!player.getAbilities().instabuild) {
			stack.shrink(1);
		}

		if (this.random.nextInt(3) == 0 && !EventHooks.onAnimalTame(this, player)) {
			this.tame(player);
			this.setOrderedToSit(true);
			this.level().broadcastEntityEvent(this, (byte) 7);
		} else {
			this.level().broadcastEntityEvent(this, (byte) 6);
		}

		return InteractionResult.SUCCESS;
	}

	return super.mobInteract(player, hand);
}

public InteractionResult mobInteract(Player player, InteractionHand p_230254_2_) {
	ItemStack itemstack = player.getItemInHand(p_230254_2_);
	Item item = itemstack.getItem();
	if (item instanceof PaleopediaItem) {
		CompoundTag tag = itemstack.getTag();
		final List<Integer> already = new ArrayList<>(Ints.asList(tag.getIntArray("Pages")));
		if (!already.contains(EnumPaleoPages.VELOCIRAPTOR.ordinal())) {
			EnumPaleoPages.addPage(EnumPaleoPages.fromInt(EnumPaleoPages.VELOCIRAPTOR.ordinal()), itemstack);
			player.displayClientMessage(Component.translatable("paleopedia.velociraptor_added"), true);
			return InteractionResult.SUCCESS;
		} else {
			player.displayClientMessage(Component.translatable("paleopedia.velociraptor_already_added"), true);
			return InteractionResult.SUCCESS;
		}
	}
	if (this.level().isClientSide()) {
		boolean flag = this.isOwnedBy(player) || this.isTame() || this.isFood(itemstack) && !this.isTame();
		return flag ? InteractionResult.CONSUME : InteractionResult.PASS;

	} else {
		if (this.isTame()) {
			if (this.getOwner() == player) {
				if (this.isFood(itemstack)) {
					if (this.getHealth() < this.getMaxHealth()) {
						if (!player.getAbilities().instabuild) {
							itemstack.shrink(1);
						}
						this.heal((float)item.getFoodProperties().getNutrition());
						return InteractionResult.SUCCESS;
					} else {
						if (this.canFallInLove()) {
							this.setInLove(player);
							if (!player.isCreative()) {
								itemstack.shrink(1);
							}
						}
					}
				} else if (!this.isArmored() && item == PFItems.SMALL_DINOSAUR_ARMOR.get()) {
					this.setArmored(true);
					this.setArmorDamage(itemstack.getMaxDamage() - itemstack.getDamageValue());
					if (!player.isCreative()) {
						itemstack.shrink(1);
					}
				} else if (this.isArmored() && item == Items.SHEARS) {
					this.setArmored(false);
					ItemStack armorStack = new ItemStack(PFItems.SMALL_DINOSAUR_ARMOR.get());
					armorStack.setDamageValue(armorStack.getMaxDamage() - this.getArmorDamage());
					this.spawnAtLocation(armorStack);
					if (!player.isCreative()) {
						itemstack.hurtAndBreak(1, player, (p_41007_) -> {
							p_41007_.broadcastBreakEvent(EquipmentSlot.MAINHAND);
						});
					}
				} else {
					if (this.isTameSitting()) {
						this.setTameSitting(false);
						this.setTameWandering(true);
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.velociraptor.wandering"), true);
					} else if(this.isTameWandering()) {
						this.setTameWandering(false);
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.velociraptor.following"), true);
					} else {
						this.setTameSitting(true);
						player.displayClientMessage(Component.translatable("entity.prehistoricfauna.velociraptor.sitting"), true);
					}
				}
			} else if ((itemstack.is(PFTags.MEATS_2_HUNGER) || itemstack.is(PFTags.MEATS_4_HUNGER) || itemstack.is(PFTags.MEATS_6_HUNGER) || itemstack.is(PFTags.MEATS_8_HUNGER) || itemstack.is(PFTags.MEATS_10_HUNGER) || itemstack.is(PFTags.MEATS_12_HUNGER))) {
				if (this.getCurrentHunger() < this.maxHunger) {
					if (itemstack.is(PFTags.MEATS_2_HUNGER)) {
						if (this.getCurrentHunger() + 2 >= this.maxHunger) {
							this.setHunger(this.maxHunger);
						} else {
							this.setHunger(this.getCurrentHunger() + 2);
						}
						if (!player.isCreative()) {
							itemstack.shrink(1);
						}
					} else if (itemstack.is(PFTags.MEATS_4_HUNGER)) {
						if (this.getCurrentHunger() + 4 >= this.maxHunger) {
							this.setHunger(this.maxHunger);
						} else {
							this.setHunger(this.getCurrentHunger() + 4);
						}
						if (!player.isCreative()) {
							itemstack.shrink(1);
						}
					} else if (itemstack.is(PFTags.MEATS_6_HUNGER)) {
						if (this.getCurrentHunger() + 6 >= this.maxHunger) {
							this.setHunger(this.maxHunger);
						} else {
							this.setHunger(this.getCurrentHunger() + 6);
						}
						if (!player.isCreative()) {
							itemstack.shrink(1);
						}
					} else if (itemstack.is(PFTags.MEATS_8_HUNGER)) {
						if (this.getCurrentHunger() + 8 >= this.maxHunger) {
							this.setHunger(this.maxHunger);
						} else {
							this.setHunger(this.getCurrentHunger() + 8);
						}
						if (!player.isCreative()) {
							itemstack.shrink(1);
						}
					} else if (itemstack.is(PFTags.MEATS_10_HUNGER)) {
						if (this.getCurrentHunger() + 10 >= this.maxHunger) {
							this.setHunger(this.maxHunger);
						} else {
							this.setHunger(this.getCurrentHunger() + 10);
						}
						if (!player.isCreative()) {
							itemstack.shrink(1);
						}
					} else if (itemstack.is(PFTags.MEATS_12_HUNGER)) {
						if (this.getCurrentHunger() + 12 >= this.maxHunger) {
							this.setHunger(this.maxHunger);
						} else {
							this.setHunger(this.getCurrentHunger() + 12);
						}
						if (!player.isCreative()) {
							itemstack.shrink(1);
						}
					}
				} else {
					player.displayClientMessage(Component.translatable("entity.prehistoricfauna.fullHunger"), true);
				} 
			}
		} else {
			if (this.isFood(itemstack)) {
				if (!player.getAbilities().instabuild) {
					itemstack.shrink(1);
				}

				if (this.random.nextInt(3) == 0 && !net.minecraftforge.event.ForgeEventFactory.onAnimalTame(this, player)) {
					this.tame(player);
					this.navigation.stop();
					this.setTarget((LivingEntity)null);
					this.setTameSitting(true);
					this.level().broadcastEntityEvent(this, (byte)7);
				} else {
					this.level().broadcastEntityEvent(this, (byte)6);
				}

				return InteractionResult.SUCCESS;
			}
		}
		return super.mobInteract(player, p_230254_2_);
	}
}

public void tick() {
    LivingEntity target = entity.getTarget();
    if (target != null && target.isAlive()) {
        double distance = entity.distanceTo(target);
        double attackDistance = entity.getBbWidth() + target.getBbWidth();
        boolean inPursuit = !this.isMovementFrozen();
        if (attemptSonicDamageIn > 0) {
            attemptSonicDamageIn--;
            if (attemptSonicDamageIn == 0 && this.entity.hasLineOfSight(target)) {
                target.hurt(ACDamageTypes.causeForsakenSonicBoomDamage(entity.level().registryAccess(), entity), entity.getSonicDamageAgainst(target));
                knockBackAngle(target, 1.0F, 0F);
            }
        }
        if (sonicEnqueued && this.entity.hasLineOfSight(target) && distance < 200F) {
            this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            entity.setSonarId(target.getId());
            this.entity.getNavigation().stop();
            if(distance > 10 || entity.getRandom().nextFloat() < 0.4){
                tryAnimation(ForsakenEntity.ANIMATION_SONIC_ATTACK);
                this.entity.playSound(ACSoundRegistry.FORSAKEN_SCREECH.get(), this.entity.getSoundVolume(), this.entity.getVoicePitch());
            }else{
                tryAnimation(ForsakenEntity.ANIMATION_SONIC_BLAST);
                this.entity.playSound(ACSoundRegistry.FORSAKEN_AOE.get(), this.entity.getSoundVolume(), this.entity.getVoicePitch());
            }
            if (this.entity.getAnimation() == ForsakenEntity.ANIMATION_SONIC_ATTACK) {
                inPursuit = false;
                if (this.entity.getAnimationTick() >= 10 && this.entity.getAnimationTick() <= 30 && attemptSonicDamageIn <= 0) {
                    attemptSonicDamageIn = (int) Math.ceil(distance * 0.2F);
                }
                if (this.entity.getAnimationTick() > 30) {
                    sonicEnqueued = false;
                }
            }
            if (this.entity.getAnimation() == ForsakenEntity.ANIMATION_SONIC_BLAST) {
                inPursuit = false;
                if (this.entity.getAnimationTick() >= 10 && this.entity.getAnimationTick() <= 30) {
                    if (this.entity.getAnimationTick() % 5 == 0) {
                        List<LivingEntity> list = this.entity.level().getEntitiesOfClass(LivingEntity.class, this.entity.getBoundingBox().inflate(16, 8, 16));
                        for (LivingEntity living : list) {
                            if (living != this.entity && !this.entity.isAlliedTo(living) && !living.isAlliedTo(entity) && living.distanceTo(entity) <= 14F && !living.getType().is(ACTagRegistry.FORSAKEN_IGNORES)) {
                                living.hurt(ACDamageTypes.causeForsakenSonicBoomDamage(entity.level().registryAccess(), entity), (float) Math.ceil(entity.getSonicDamageAgainst(target) * 0.65F));
                            }
                        }
                    }
                }
                if (this.entity.getAnimationTick() > 40) {
                    sonicEnqueued = false;
                }
            }
        } else if (jumpEnqueued) {
            if (jumpTarget == null) {
                jumpTarget = findJumpTarget(target, distance > 20.0F);
            } else {
                inPursuit = false;
                if (entity.isLeaping()) {
                    Vec3 vec3 = this.entity.getDeltaMovement();
                    Vec3 vec31 = new Vec3(this.jumpTarget.getX() + 0.5F - this.entity.getX(), 0.0D, this.jumpTarget.getZ() + 0.5F - this.entity.getZ());
                    if (vec31.lengthSqr() > 1.0E-7D) {
                        vec31 = vec31.scale(0.155F).add(vec3.scale(0.2D));
                    }
                    this.entity.setDeltaMovement(vec31.x, 0.2F + (double) vec31.length() * 0.3F, vec31.z);
                    jumpEnqueued = false;
                    jumpTarget = null;
                } else if (entity.onGround()) {
                    entity.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(jumpTarget));
                    tryAnimation(ForsakenEntity.ANIMATION_PREPARE_JUMP);
                }
            }
        }
        if (inPursuit) {
            this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            this.entity.getNavigation().moveTo(target, 1.0D);
            if (distance < attackDistance + 1.0F && this.entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                float attackType = entity.getRandom().nextFloat();
                if (attackType < 0.25F && target.getBbWidth() < 2.0F) {
                    tryAnimation(this.entity.getRandom().nextBoolean() ? ForsakenEntity.ANIMATION_LEFT_PICKUP : ForsakenEntity.ANIMATION_RIGHT_PICKUP);
                } else if (attackType < 0.5F) {
                    tryAnimation(this.entity.getRandom().nextBoolean() ? ForsakenEntity.ANIMATION_LEFT_SLASH : ForsakenEntity.ANIMATION_RIGHT_SLASH);
                } else if (attackType < 0.75F) {
                    tryAnimation(ForsakenEntity.ANIMATION_GROUND_SMASH);
                } else {
                    tryAnimation(ForsakenEntity.ANIMATION_BITE);
                    this.entity.playSound(ACSoundRegistry.FORSAKEN_BITE.get());
                }
            }
        } else {
            entity.getNavigation().stop();
        }
        if ((distance > 20.0F && this.entity.getRandom().nextFloat() < 0.01 || entity.hasSonicCharge()) && !this.sonicEnqueued) {
            this.sonicEnqueued = true;
            this.entity.setSonicCharge(false);
        }
        if (distance > 30.0F && this.entity.getRandom().nextFloat() < 0.05 && !this.jumpEnqueued) {
            this.startCleanJump();
        }
        if (distance < 64.0F && distance > attackDistance && inPursuit) {
            this.entity.setRunning(true);
        } else {
            this.entity.setRunning(false);
        }
        if ((entity.getAnimation() == ForsakenEntity.ANIMATION_RIGHT_PICKUP || entity.getAnimation() == ForsakenEntity.ANIMATION_LEFT_PICKUP) && entity.getHeldMobId() == target.getId() && entity.getAnimationTick() >= 30) {
            checkAndDealDamage(target, 1.2F, 5);
        }
        if (entity.getAnimation() == ForsakenEntity.ANIMATION_RIGHT_SLASH && entity.getAnimationTick() >= 15 && entity.getAnimationTick() <= 18) {
            float knockbackStrength = 0.5F;
            if (checkAndDealDamage(target, 0.8F, 2)) {
                knockbackStrength = 3F;
                entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
            }
            knockBackAngle(target, knockbackStrength, -90F);
        }
        if (entity.getAnimation() == ForsakenEntity.ANIMATION_LEFT_SLASH && entity.getAnimationTick() >= 15 && entity.getAnimationTick() <= 18) {
            float knockbackStrength = 0.5F;
            if (checkAndDealDamage(target, 0.8F, 2)) {
                knockbackStrength = 3F;
                entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
            }
            knockBackAngle(target, knockbackStrength, 90F);
        }
        if (entity.getAnimation() == ForsakenEntity.ANIMATION_GROUND_SMASH && entity.getAnimationTick() >= 10 && entity.getAnimationTick() <= 15) {
            Vec3 smashPos = entity.position().add(new Vec3(0, 0, 3.5F).yRot((float) -Math.toRadians(entity.yBodyRot)));
            List<LivingEntity> list = this.entity.level().getEntitiesOfClass(LivingEntity.class, new AABB(smashPos.x - 4, smashPos.y - 2, smashPos.z - 4, smashPos.x + 4, smashPos.y + 3, smashPos.z + 4));
            boolean flag = false;
            for (LivingEntity living : list) {
                if (living != this.entity && !this.entity.isAlliedTo(living) && !living.isAlliedTo(entity) && living.distanceToSqr(smashPos) <= 16F && !living.getType().is(ACTagRegistry.FORSAKEN_IGNORES)) {
                    if (checkAndDealDamage(living, 0.8F, 3) && living.onGround()) {
                        living.setDeltaMovement(living.getDeltaMovement().add(0, 0.5, 0));
                        flag = true;
                    }
                }
            }
            if(flag){
                entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
            }
        }
        if (entity.getAnimation() == ForsakenEntity.ANIMATION_BITE && entity.getAnimationTick() >= 5 && entity.getAnimationTick() <= 8) {
            float knockbackStrength = 0.0F;
            if (checkAndDealDamage(target, 1F, 1)) {
                knockbackStrength = 0.5F;
            }
            knockBackAngle(target, knockbackStrength, 0F);
        }
        if (navigationCheckCooldown-- < 0 && this.entity.onGround()) {
            navigationCheckCooldown = 20 + entity.getRandom().nextInt(40);
            if (!canReach(target)) {
                this.startCleanJump();
            }
        }
    }
}

