			}
			if (target.getType().is(PFTags.ANIMALS_200_HUNGER)) {
				if (target.isDeadOrDying()) {
					if (dinosaur.getCurrentHunger() + 200 >= dinosaur.maxHunger) {
						dinosaur.setHunger(dinosaur.maxHunger);
					} else {
						dinosaur.setHunger(dinosaur.currentHunger + 200);
					}
				}
			}
		} else stop();
	} else stop();
	super.tick();
}

	public void onUpdate() {
		if (this.world.isRemote) {
			prevGrowCount = growCount;
			growCount = getGrowTimer();
			if (getGrowTimer() > 0 && getGrowTimer() < 40)
				if (this.ticksExisted % 4 == 0)
					this.spawnVolatileParticles(true);
		}

        if (!this.world.isRemote) {
			if (isInTar()) {
				if (getGrowTimer() > 0)
					setGrowTimer(Math.max(0, getGrowTimer() - 1));
				if (getGrowTimer() <= 0) {
					EntityTarBeast tar_beast = new EntityTarBeast(getEntityWorld());
					tar_beast.setPositionAndRotation(posX, posY, posZ, rotationYaw, rotationPitch);
					tar_beast.setGrowTimer(0);
					getEntityWorld().spawnEntity(tar_beast);
					setDead();
				}
			}

			if (!isInTar() && getGrowTimer() < 40)
				setGrowTimer(Math.min(40, getGrowTimer() + 1));

            if (this.getAttackTarget() == null) {
                this.setHiding(true);

                this.canTurnVolatileOnTarget = false;
            } else {
                this.setHiding(false);

                if (this.canTurnVolatile && !this.isVolatile() && !this.isRiding() && this.canPossess(this.getAttackTarget()) && this.canTurnVolatileOnTarget) {
                    if (this.volatileCooldownTicks > 0) {
                        this.volatileCooldownTicks--;
                    }

                    if (this.getHealth() <= this.getMaxHealth() * this.getEntityAttribute(VOLATILE_HEALTH_START_ATTRIB).getAttributeValue() && this.volatileCooldownTicks <= 0) {
                        this.setVolatile(true);
                        this.didTurnVolatileOnPlayer = true;
                        this.volatileReceivedDamage = 0.0F;
                        this.volatileCooldownTicks = this.getMaxVolatileCooldown() + this.world.rand.nextInt(this.getMaxVolatileCooldown()) + 20;
                        this.volatileTicks = 0;

                        TheBetweenlands.networkWrapper.sendToAllAround(new MessageWightVolatileParticles(this), new TargetPoint(this.dimension, this.posX, this.posY, this.posZ, 32));
                        this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.WIGHT_ATTACK, SoundCategory.HOSTILE, 1.6F, 1.0F);
                    }
                } else if (this.didTurnVolatileOnPlayer && this.isVolatile() && !this.canPossess(this.getAttackTarget())) {
                    this.setVolatile(false);
                    this.didTurnVolatileOnPlayer = false;
                }
            }
        }

        if (this.isVolatile()) {
        	if(!this.world.isRemote) {
	        	if (this.volatileTicks < this.getEntityAttribute(VOLATILE_LENGTH_ATTRIB).getAttributeValue()) {
	            	this.volatileTicks++;

	                if (this.volatileTicks >= 20) {
	                    this.noClip = true;
	                }
	            } else {
	                if (!this.world.isRemote) {
	                    this.motionY -= 0.075D;

	                    this.fallDistance = 0;

	                    if (this.didTurnVolatileOnPlayer && this.onGround) {
	                        this.setVolatile(false);
	                        this.didTurnVolatileOnPlayer = false;
	                    }
	                }

	                this.noClip = false;
	            }

	            if (this.volatileTicks < 20) {
	                this.moveHelper.setMoveTo(this.posX, this.posY + 1.0D, this.posZ, 0.15D);
	            }

	            if (this.getAttackTarget() != null) {
	                EntityLivingBase attackTarget = this.getAttackTarget();

	                if (this.getRidingEntity() == null && this.getDistance(attackTarget) < 1.75D && this.canPossess(attackTarget)) {
	                    this.startRiding(attackTarget, true);
	                    this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(attackTarget));
	                }

	                if (this.getRidingEntity() == null) {
	                    double dx = attackTarget.posX - this.posX;
	                    double dz = attackTarget.posZ - this.posZ;
	                    double dy;
	                    if (attackTarget instanceof EntityLivingBase) {
	                        EntityLivingBase entitylivingbase = attackTarget;
	                        dy = entitylivingbase.posY + (double) entitylivingbase.getEyeHeight() - (this.posY + (double) this.getEyeHeight());
	                    } else {
	                        dy = (attackTarget.getEntityBoundingBox().minY + attackTarget.getEntityBoundingBox().maxY) / 2.0D - (this.posY + (double) this.getEyeHeight());
	                    }
	                    double dist = (double) MathHelper.sqrt(dx * dx + dz * dz);
	                    float yaw = (float) (Math.atan2(dz, dx) * 180.0D / Math.PI) - 90.0F;
	                    float pitch = (float) (-(Math.atan2(dy, dist) * 180.0D / Math.PI));
	                    this.setRotation(yaw, pitch);
	                    this.setRotationYawHead(yaw);
	                } else {
	                    this.setRotation(0, 0);
	                    this.setRotationYawHead(0);

	                    if (this.ticksExisted % 5 == 0 && this.canEntityBeSeen(this.getAttackTarget()) && !this.isWearingSkullMask(this.getAttackTarget())) {
	                        List<EntityVolatileSoul> existingSouls = this.world.getEntitiesWithinAABB(EntityVolatileSoul.class, this.getEntityBoundingBox().grow(16.0D, 16.0D, 16.0D));
	                        if (existingSouls.size() < 16) {
	                            EntityVolatileSoul soul = new EntityVolatileSoul(this.world);
	                            float mx = this.world.rand.nextFloat() - 0.5F;
	                            float my = this.world.rand.nextFloat() / 2.0F;
	                            float mz = this.world.rand.nextFloat() - 0.5F;
	                            Vec3d dir = new Vec3d(mx, my, mz).normalize();
	                            soul.setOwner(this.getUniqueID());
	                            soul.setLocationAndAngles(this.posX + dir.x * 0.5D, this.posY + dir.y * 1.5D, this.posZ + dir.z * 0.5D, 0, 0);
	                            soul.shoot(mx * 2.0D, my * 2.0D, mz * 2.0D, 1.0F, 1.0F);
	                            this.world.spawnEntity(soul);
	                        }
	                    }
	                }
	            }

	            this.moveHelper = this.flightMoveHelper;
        	}

            if (this.world.isRemote && (this.getRidingEntity() == null || this.ticksExisted % 4 == 0)) {
                this.spawnVolatileParticles(false);
            }

            this.setSize(0.7F, 0.7F);
        } else {
        	if(!this.world.isRemote) {
	            this.noClip = false;
	            this.moveHelper = this.groundMoveHelper;
        	}

            this.setSize(0.7F, 2.2F);
        }

        this.lastHidingAnimationTicks = this.hidingAnimationTicks;
        if (this.isHiding()) {
            if (this.hidingAnimationTicks < 12)
                this.hidingAnimationTicks++;
        } else {
            if (this.hidingAnimationTicks > 0)
                this.hidingAnimationTicks--;
        }

        super.onUpdate();
    }

	public InteractionResult useOn(UseOnContext context)
	{
		Level world = context.getLevel();
		BlockPos pos = context.getClickedPos();

		Player player = context.getPlayer();
		ItemStack stack = context.getItemInHand();
		InteractionHand hand = context.getHand();
		Direction direction = context.getClickedFace();

//		ItemStack stack = player.getHeldItem(hand);
		if (!world.isClientSide)
		{
			EnumRitualReaderState state = this.getState(stack);
			BlockEntity tile = world.getBlockEntity(pos);
			if (tile instanceof IMasterRitualStone master)
			{
                if (master.getCurrentRitual() == null)
					super.useOn(context);
				this.setMasterBlockPos(stack, pos);
				this.setBlockPos(stack, BlockPos.ZERO);

				switch (state)
				{
				case INFORMATION:
					master.provideInformationOfRitualToPlayer(player);

					break;
				case SET_AREA:
					if (player.isShiftKeyDown() && player.getItemInHand(InteractionHand.OFF_HAND).getItem() instanceof ItemBloodOrb)
					{
						Ritual ritual = master.getCurrentRitual();
						for (String range : ritual.getListOfRanges())
						{
							AreaDescriptor aabb = ritual.getBlockRange(range);
							master.setBlockRange(range, aabb);
						}
						break;
					}

					String range = this.getCurrentBlockRange(stack);

					if (range == null || range.isEmpty() || player.isShiftKeyDown())
					{
						String newRange = master.getNextBlockRange(range);
						range = newRange;
						this.setCurrentBlockRange(stack, newRange);
					}

					master.provideInformationOfRangeToPlayer(player, range);

					break;
				case SET_WILL_TYPES:
					List<EnumDemonWillType> typeList = new ArrayList<>();
					NonNullList<ItemStack> inv = player.getInventory().items;
					for (int i = 0; i < 9; i++)
					{
						ItemStack testStack = inv.get(i);
						if (testStack.isEmpty())
						{
							continue;
						}

						if (testStack.getItem() instanceof IDiscreteDemonWill)
						{
							EnumDemonWillType type = ((IDiscreteDemonWill) testStack.getItem()).getType(testStack);
							if (!typeList.contains(type))
							{
								typeList.add(type);
							}
						}
					}

					master.setActiveWillConfig(player, typeList);
					master.provideInformationOfWillConfigToPlayer(player, typeList);
					break;
				}

				return InteractionResult.FAIL;
			} else
			{
				if (state == EnumRitualReaderState.SET_AREA)
				{
					BlockPos masterPos = this.getMasterBlockPos(stack);
					if (!masterPos.equals(BlockPos.ZERO))
					{
						BlockPos containedPos = getBlockPos(stack);
						if (containedPos.equals(BlockPos.ZERO))
						{
							BlockPos pos1 = pos.subtract(masterPos);
							this.setBlockPos(stack, pos1);
							player.displayClientMessage(Component.translatable("ritual.bloodmagic.blockRange.firstBlock"), true);
						} else
						{
							tile = world.getBlockEntity(masterPos);
							if (tile instanceof IMasterRitualStone master)
							{
                                BlockPos pos2 = pos.subtract(masterPos);
								String range = this.getCurrentBlockRange(stack);
								if (range == null || range.isEmpty())
								{
									String newRange = master.getNextBlockRange(range);
									range = newRange;
									this.setCurrentBlockRange(stack, newRange);
								}
								Ritual ritual = master.getCurrentRitual();
								List<EnumDemonWillType> willConfig = master.getActiveWillConfig();
								DemonWillHolder holder = WorldDemonWillHandler.getWillHolder(master.getWorldObj(), master.getMasterBlockPos());

								int maxHorizontalRange = ritual.getMaxHorizontalRadiusForRange(range, willConfig, holder);
								int maxVerticalRange = ritual.getMaxVerticalRadiusForRange(range, willConfig, holder);
								int maxVolume = ritual.getMaxVolumeForRange(range, willConfig, holder);

								switch (master.setBlockRangeByBounds(player, range, containedPos, pos2))
								{
								case SUCCESS:
									player.displayClientMessage(Component.translatable("ritual.bloodmagic.blockRange.success"), true);
									break;
								case NOT_WITHIN_BOUNDARIES:
									player.displayClientMessage(Component.translatable("ritual.bloodmagic.blockRange.tooFar", maxVerticalRange, maxHorizontalRange), false);
									break;
								case VOLUME_TOO_LARGE:
									player.displayClientMessage(Component.translatable("ritual.bloodmagic.blockRange.tooBig", maxVolume), false);
									break;
								default:
									player.displayClientMessage(Component.translatable("ritual.bloodmagic.blockRange.noRange"), false);
									break;
								}
							}
							this.setBlockPos(stack, BlockPos.ZERO);
						}
					}
				}
			}
		} else
		{
			EnumRitualReaderState state = this.getState(stack);

			if (state == EnumRitualReaderState.SET_AREA)
			{
				BlockEntity tile = world.getBlockEntity(pos);
				if (tile instanceof TileMasterRitualStone)
				{

//					System.out.println("Setting range holo... I think");
					ClientHandler.setRitualRangeHolo((TileMasterRitualStone) tile, true);

				}
			}

		}

		return super.useOn(context);
	}

public void onUpdate() {
	super.onUpdate();

	if (world.isRemote) {
		prevGrowCount = growCount;
		growCount = getGrowTimer();
		if(ticksExisted % 10 == 0) {
			renderParticles(world, posX, posY, posZ, rand);
		}
		if(this.sheddingProgress > this.getSheddingSpeed()) {
			this.sheddingProgress = 0;

			for(int i = 0; i < 200; i++) {
				Random rnd = world.rand;
				float rx = rnd.nextFloat() * 4.0F - 2.0F;
				float ry = rnd.nextFloat() * 4.0F - 2.0F;
				float rz = rnd.nextFloat() * 4.0F - 2.0F;
				Vec3d vec = new Vec3d(rx, ry, rz);
				vec = vec.normalize();
				BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.25F, this.posY + ry, this.posZ + rz + 0.25F, ParticleArgs.get().withMotion(vec.x * 0.5F, vec.y * 0.5F, vec.z * 0.5F));
			}
		} else if(this.isShedding() || this.sheddingProgress > 0) {
			this.sheddingProgress++;
		} else {
			this.sheddingProgress = 0;
		}

		if(this.isSucking()) {
			for(int i = 0; i < 5; i++) {
				Random rnd = world.rand;
				float rx = rnd.nextFloat() * 8.0F - 4.0F;
				float ry = rnd.nextFloat() * 8.0F - 4.0F;
				float rz = rnd.nextFloat() * 8.0F - 4.0F;
				Vec3d vec = new Vec3d(rx, ry, rz);
				vec = vec.normalize();
				this.world.spawnParticle(EnumParticleTypes.SMOKE_LARGE, this.posX + rx + 0.25F, this.posY + ry, this.posZ + rz + 0.25F, -vec.x * 0.5F, -vec.y * 0.5F, -vec.z * 0.5F);
			}
		}
	}

	if(!world.isRemote) {
		if(this.isInsideOfMaterial(BLMaterialRegistry.TAR)) {
			this.stepHeight = 2.0F;
		} else {
			this.stepHeight = 0.75F;
		}

		if(this.shedCooldown > 0 && this.getAttackTarget() != null) {
			this.shedCooldown--;
		}

		if(!this.isSucking() && !this.isPreparing()) {
			if(this.shedCooldown == 0 && this.getAttackTarget() != null && this.getAttackTarget().getDistance(this) < 6.0D && this.canEntityBeSeen(this.getAttackTarget())) {
				this.setShedding(true);
				this.shedCooldown = this.getSheddingCooldown() + this.world.rand.nextInt(this.getSheddingCooldown() / 2);
			}

			if(this.sheddingProgress > this.getSheddingSpeed()) {
				this.playSound(SoundRegistry.TAR_BEAST_LIVING, 1F, (this.rand.nextFloat() * 0.2F + 1.0F) * 0.6F);
				for(int i = 0; i < 8; i++) {
					this.playSound(SoundRegistry.TAR_BEAST_STEP, 1F, (this.rand.nextFloat() * 0.4F + 0.8F) * 0.8F);
				}
				this.sheddingProgress = 0;
				this.setShedding(false);
				if(this.getAttackTarget() != null) {
					List<EntityLivingBase> affectedEntities = (List<EntityLivingBase>)this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(6.0F, 6.0F, 6.0F));
					for(EntityLivingBase e : affectedEntities) {
						if(e == this || e.getDistance(this) > 6.0F || !e.canEntityBeSeen(this) || e instanceof EntityTarBeast) continue;
						if(e instanceof EntityPlayer) {
							if(((EntityPlayer)e).isActiveItemStackBlocking()) continue;
						}
						double dst = e.getDistance(this);
						float dmg = (float) (this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue() / dst * 7.0F);
						e.attackEntityFrom(DamageSource.causeMobDamage(this), dmg);
						e.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, (int)(20 + (1.0F - dst / 6.0F) * 150), 1));
					}
				}
			}

			if(this.isShedding()) {
				this.sheddingProgress++;
			} else {
				this.sheddingProgress = 0;
			}
		}

		if(this.suckingCooldown > 0 && this.getAttackTarget() != null) {
			this.suckingCooldown--;
		}

		if(!this.isShedding()) {
			if(this.suckingCooldown == 0 && this.getAttackTarget() != null && this.getAttackTarget().getDistance(this) <= 10.0D && this.canEntityBeSeen(this.getAttackTarget())) {
				this.setPreparing();
			}

			if(this.isPreparing()) {
				this.suckingPreparation++;

				if(this.suckingPreparation > this.getEntityAttribute(SUCK_PREPARATION_SPEED_ATTRIB).getAttributeValue()) {
					this.suckingPreparation = 0;

					this.setSucking(true);
					this.suckingCooldown = this.getSuckingCooldown() + this.world.rand.nextInt(this.getSuckingCooldown() / 2);
					this.playSound(SoundRegistry.TAR_BEAST_SUCK, 1F, 1F);
				}
			}

			if(this.suckingProgress > (int)this.getEntityAttribute(SUCK_LENGTH_ATTRIB).getAttributeValue()) {
				this.setSucking(false);
				this.suckingProgress = 0;
			}

			if(this.isSucking()) {
				this.suckingProgress++;

				List<Entity> affectedEntities = (List<Entity>)this.world.getEntitiesWithinAABB(Entity.class, this.getEntityBoundingBox().grow(10.0F, 10.0F, 10.0F));
				for(Entity e : affectedEntities) {
					if(e == this || e.getDistance(this) > 10.0F || !this.canEntityBeSeen(e) || e instanceof EntityTarBeast) continue;
					Vec3d vec = new Vec3d(this.posX - e.posX, this.posY - e.posY, this.posZ - e.posZ);
					vec = vec.normalize();
					float dst = e.getDistance(this);
					float mod = (float) Math.pow(1.0F - dst / 13.0F, 1.2D);
					if(e instanceof EntityPlayer) {
						if(((EntityPlayer)e).isActiveItemStackBlocking()) mod *= 0.18F;
					}
					if(dst < 1.0F && e instanceof EntityLivingBase) {
						((EntityLivingBase) e).addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, 20, 3));
						((EntityLivingBase) e).addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, 20, 3));
						e.motionX *= 0.008F;
						e.motionY *= 0.008F;
						e.motionZ *= 0.008F;
						if(e instanceof EntityPlayer) {
							((EntityPlayer)e).jumpMovementFactor = 0.0F;
						}
						if(this.ticksExisted % 12 == 0) {
							e.attackEntityFrom(DamageSource.DROWN, 1);
						}
					}
					e.motionX += vec.x * 0.18F * mod;
					e.motionY += vec.y * 0.18F * mod;
					e.motionZ += vec.z * 0.18F * mod;
					e.velocityChanged = true;
				}
				getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(0.75D);
			} else {
				this.suckingProgress = 0;
				getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(1.0D);
			}
		}

		if (getGrowTimer() < 40) {
			setGrowTimer(Math.min(40, getGrowTimer() + 1));
		}
	}
}

public void releaseUsing(ItemStack bow, Level level, LivingEntity living, int timeLeft) {
  // call the stop using hook
  ToolStack tool = ToolStack.from(bow);
  int duration = getUseDuration(bow);
  for (ModifierEntry entry : tool.getModifiers()) {
    entry.getHook(ModifierHooks.TOOL_USING).beforeReleaseUsing(tool, entry, living, duration, timeLeft, ModifierEntry.EMPTY);
  }

  // no broken
  if (tool.isBroken()) {
    return;
  }

  // just not handling vanilla infinity at all, we have our own hooks which someone could use to mimic infinity if they wish with a bit of effort
  Player player = living instanceof Player p ? p : null;
  boolean creative = player != null && player.getAbilities().instabuild;
  // its a little redundant to search for ammo twice, but otherwise we risk shrinking the stack before we know if we can fire
  // also helps blocking, as you can block without ammo
  Predicate<ItemStack> ammoPredicate = switch (tool.getPersistentData().getInt(KEY_BALLISTA)) {
    case FLAG_BALLISTA_HELD -> null; // main hand comes via an event, we just call the hook for merging
    case FLAG_BALLISTA_QUIVER -> BALLISTA_ONLY;
    case FLAG_NO_BALLISTA -> getSupportedHeldProjectiles();
    default -> isBallista(tool) ? getSupportedBallistaAmmo() : getSupportedHeldProjectiles();
  };
  ItemStack foundAmmo = BowAmmoModifierHook.getAmmo(tool, bow, living, ammoPredicate);
  boolean hasAmmo = !foundAmmo.isEmpty() || creative && !tool.getVolatileData().getBoolean(BowAmmoModifierHook.SKIP_INVENTORY_AMMO);

  // ask forge its thoughts on shooting
  int chargeTime = duration - timeLeft;
  if (player != null) {
    chargeTime = ForgeEventFactory.onArrowLoose(bow, level, player, chargeTime, hasAmmo);
  }

  // no ammo? no charge? nothing to do
  if (!hasAmmo || chargeTime < 0) {
    return;
  }

  // calculate arrow power
  float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
  float velocity = ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.VELOCITY);
  float power = charge * velocity;
  if (power < 0.1f) {
    return;
  }

  // launch the arrow
  if (!level.isClientSide) {
    int originalSlot = -1;
    int desiredProjectiles = 1;
    // if it's a ballista shot, locate the original slot so we can store it on the entity
    if (foundAmmo.is(TinkerTags.Items.BALLISTA_AMMO)) {
      if (player != null) {
        if (foundAmmo == living.getOffhandItem()) {
          originalSlot = Inventory.SLOT_OFFHAND;
        } else {
          Inventory inventory = player.getInventory();
          // does not use the inventory method as we want instance match, not deep compare
          for (int i = 0; i < Inventory.INVENTORY_SIZE; i++) {
            if (inventory.getItem(i) == foundAmmo) {
              originalSlot = i;
              break;
            }
          }
        }
      }
    } else {
      // TODO: remove multishot logic? or keep it around for addons?
      desiredProjectiles = BowAmmoModifierHook.getDesiredProjectiles(tool);
    }
    // filter ammo based on request from current ballista settings
    ItemStack ammo = BowAmmoModifierHook.consumeAmmo(tool, bow, living, player, ammoPredicate, desiredProjectiles);
    // could only be empty at this point if we are creative, as hasAmmo returned true above
    if (ammo.isEmpty()) {
      ammo = new ItemStack(Items.ARROW);
    }

    // prepare the arrows
    ArrowItem arrowItem = ammo.getItem() instanceof ArrowItem arrow ? arrow : (ArrowItem)Items.ARROW;
    // shenanigans: if the ammo is a melee tool, fire that using the thrown tool projectile
    boolean thrownTool = ammo.is(TinkerTags.Items.BALLISTA_AMMO);
    float waterInertia = 0.6f;
    SoundEvent sound = SoundEvents.ARROW_SHOOT;
    if (thrownTool) {
      sound = SoundEvents.TRIDENT_THROW;
      IToolStackView thrown = ToolStack.from(ammo);
      float thrownVelocity = ConditionalStatModifierHook.getModifiedStat(thrown, living, ToolStats.VELOCITY);
      power *= thrownVelocity * ConditionalStatModifierHook.getModifiedStat(thrown, living, ToolStats.DRAW_SPEED) / 1.5f;
      if (ammo.is(TinkerTags.Items.MELEE_WEAPON)) {
        power *= thrown.getStats().get(ToolStats.ATTACK_SPEED);
      }
      velocity *= thrownVelocity;
      waterInertia = ConditionalStatModifierHook.getModifiedStat(thrown, living, ToolStats.WATER_INERTIA);
    }
    float inaccuracy = ModifierUtil.getInaccuracy(tool, living);
    float startAngle = getAngleStart(ammo.getCount());
    int primaryIndex = ammo.getCount() / 2;
    for (int arrowIndex = 0; arrowIndex < ammo.getCount(); arrowIndex++) {
      AbstractArrow arrow;
      if (thrownTool) {
        ThrownTool thrown = new ThrownTool(level, living, ammo, charge, velocity, waterInertia);
        thrown.setOriginalSlot(originalSlot);
        arrow = thrown;
      } else {
        arrow = arrowItem.createArrow(level, ammo, living);
      }
      float angle = startAngle + (10 * arrowIndex);
      arrow.shootFromRotation(living, living.getXRot() + angle, living.getYRot(), 0, power * 3.0F, inaccuracy);
      if (charge == 1.0F) {
        arrow.setCritArrow(true);
      }

      // vanilla arrows have a base damage of 2, cancel that out then add in our base damage to account for custom arrows with higher base damage
      // calculate it just once as all four arrows are the same item, they should have the same damage
      float baseArrowDamage = (float)(arrow.getBaseDamage() - 2 + tool.getStats().get(ToolStats.PROJECTILE_DAMAGE));
      arrow.setBaseDamage(ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.PROJECTILE_DAMAGE, baseArrowDamage));

      // just store all modifiers on the tool for simplicity
      ModifierNBT modifiers = tool.getModifiers();
      EntityModifierCapability.getCapability(arrow).addModifiers(modifiers);

      // fetch the persistent data for the arrow as modifiers may want to store data
      ModDataNBT arrowData = PersistentDataCapability.getOrWarn(arrow);

      // if infinite, skip pickup
      if (creative) {
        arrow.pickup = AbstractArrow.Pickup.CREATIVE_ONLY;
      }

      // let modifiers such as fiery and punch set properties
      for (ModifierEntry entry : modifiers.getModifiers()) {
        entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, living, ammo, arrow, arrow, arrowData, arrowIndex == primaryIndex);
      }

      // allow ballista to run a few remaining hooks if present
      if (thrownTool) {
        // know the cast is valid as we created the instance above
        ((ThrownTool) arrow).onRelease(living, arrowData);
      }

      level.addFreshEntity(arrow);
      level.playSound(null, living.getX(), living.getY(), living.getZ(), sound, SoundSource.PLAYERS, 1.0F, 1.0F / (level.getRandom().nextFloat() * 0.4F + 1.2F) + charge * 0.5F + (angle / 10f));
    }
    int damage = ammo.getCount();
    if (thrownTool) {
      damage *= 3;
    }
    ToolDamageUtil.damageAnimated(tool, damage, living, living.getUsedItemHand());
  }

  // stats and sounds
  if (player != null) {
    player.awardStat(Stats.ITEM_USED.get(this));
  }
}

public @NotNull InteractionResult mobInteract(Player pPlayer, @NotNull InteractionHand pHand) {
    ItemStack itemstack = pPlayer.getItemInHand(pHand);

    if (this.level().isClientSide()) {
        boolean willInteract = this.isOwnedBy(pPlayer) || this.isTame() || itemstack.is(Items.DIAMOND) && !this.isTame();
        return willInteract ? InteractionResult.CONSUME : InteractionResult.PASS;
    }

    if (!this.isTame()) {
        if (!EventHooks.onAnimalTame(this, pPlayer)) {
            this.tame(pPlayer);
            this.navigation.stop();
            this.setTarget(null);
            this.setOrderedToSit(true);
            this.level().broadcastEntityEvent(this, (byte) 7);
        } else {
            this.level().broadcastEntityEvent(this, (byte) 6);
        }
    }

    if (this.isTame() && this.isOwnedBy(pPlayer)) {

        if (itemstack.is(OccultismItems.CURSED_HONEY.asItem())) {
            long time = this.getHeartTime() + HEART_INTERVAL - this.level().getGameTime();
            if (time < 0) {
                this.setHeartTime(this.level().getGameTime());
                this.lastHeartTime = this.level().getGameTime();
                itemstack.shrink(1);
                ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(OccultismItems.SWEET_HONEY_HEART.asItem()));
            } else if (pPlayer.level().isClientSide()) {
                pPlayer.sendOverlayMessage(Component.translatable("dialog.occultism.partner.heart_on_cooldown", time));
            }
            return InteractionResult.SUCCESS;
        }

        var effects = itemstack.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY);
        if (effects.hasEffects()) {
            for (var instance : effects.getAllEffects()) {
                if (instance.getEffect().value().isInstantenous()) {
                    instance.getEffect().value().applyInstantenousEffect((ServerLevel) this.level(), this, this, pPlayer, instance.getAmplifier() + 2, 1.0D);
                } else {
                    pPlayer.addEffect(new MobEffectInstance(instance.getEffect(), instance.getDuration() * 5, instance.getAmplifier(), instance.isAmbient(), instance.isVisible()));
                }
            }

            if (!pPlayer.isCreative()) {
                itemstack.shrink(1);
                var remainder = itemstack.getItem().getCraftingRemainder();
                if (remainder == null) {
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.GLASS_BOTTLE));
                } else {
                    ItemTransferUtil.giveItemToPlayer(pPlayer, remainder.create());
                }
            }

            return InteractionResult.SUCCESS;
        }

        var effectsStew = itemstack.getOrDefault(DataComponents.SUSPICIOUS_STEW_EFFECTS, SuspiciousStewEffects.EMPTY);
        if (!effectsStew.effects().isEmpty()) {
            //Spoiler: int buff = hasCrown() ? 1 : 0;
            for (var instance : effectsStew.effects()) {
                if (instance.effect().value().isInstantenous()) {
                    instance.effect().value().applyInstantenousEffect((ServerLevel) this.level(), this, this, pPlayer, 1 /*+ buff*/, 1.0D);
                } else {
                    pPlayer.addEffect(new MobEffectInstance(instance.effect(), instance.duration() * (50 /*+ 25*buff*/), 0 /*buff*/, false, false));
                }
            }
            //Double nutrition
            pPlayer.getFoodData().eat(Foods.SUSPICIOUS_STEW);
            pPlayer.getFoodData().eat(Foods.SUSPICIOUS_STEW);

            if (!pPlayer.isCreative()) {
                itemstack.shrink(1);
                ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.BOWL));
            }

            return InteractionResult.SUCCESS;
        }

        //cook raw food
        var recipe = this.lastRecipe.isPresent() ? this.lastRecipe.get().value().input().test(itemstack) ? this.lastRecipe : this.getRecipe(itemstack) : this.getRecipe(itemstack);
        if (recipe.isPresent()) {
            this.lastRecipe = recipe;
            var result = recipe.get().value().assemble(new SingleRecipeInput(itemstack));

            if (pPlayer.isShiftKeyDown()) {
                var multiResult = result.copy();
                multiResult.setCount(result.getCount() * itemstack.getCount());

                if (!pPlayer.isCreative()) {
                    itemstack.shrink(itemstack.getCount());
                }
                ItemTransferUtil.giveItemToPlayer(pPlayer, multiResult);
            } else {
                if (!pPlayer.isCreative()) {
                    itemstack.shrink(1);
                }
                ItemTransferUtil.giveItemToPlayer(pPlayer, result);
            }

            for (int i = 0; i < 2; i++) {
                Vec3 pos = this.position().add((this.getRandom().nextFloat() - 0.5f) * 0.7,
                        1.5 + (this.getRandom().nextFloat() - 0.5f) * 0.7, (this.getRandom().nextFloat() - 0.5f) * 0.7);
                ((ServerLevel) this.level()).sendParticles(ParticleTypes.FLAME, pos.x, pos.y, pos.z, 1, 0, 0, 0, 0);
            }


            return InteractionResult.SUCCESS;
        }

        //heal with food
        if (this.isFood(itemstack) && this.getHealth() < this.getMaxHealth()) {
            FoodProperties foodProperties = itemstack.get(DataComponents.FOOD);
            this.heal(foodProperties != null ? (float) foodProperties.nutrition() : 1.0F);
            if (!pPlayer.isCreative()) {
                itemstack.shrink(1);
            }

            this.gameEvent(GameEvent.EAT, this);
            return InteractionResult.SUCCESS;
        }

        //sit/stand
        InteractionResult interactionresult = super.mobInteract(pPlayer, pHand);
        if ((!interactionresult.consumesAction() || this.isBaby()) && itemstack.isEmpty()) {
            this.setOrderedToSit(!this.isOrderedToSit());
            this.jumping = false;
            this.navigation.stop();
            this.setTarget(null);
            return InteractionResult.SUCCESS;
        } else {
            return interactionresult;
        }
    } else if (itemstack.is(Items.DIAMOND)) {
        //tame with a diamond
        if (!pPlayer.isCreative()) {
            itemstack.shrink(1);
        }

        if (!EventHooks.onAnimalTame(this, pPlayer)) {
            this.tame(pPlayer);
            this.navigation.stop();
            this.setTarget(null);
            this.setOrderedToSit(true);
            this.level().broadcastEntityEvent(this, (byte) 7);
        } else {
            this.level().broadcastEntityEvent(this, (byte) 6);
        }

        return InteractionResult.SUCCESS;
    } else {
        return super.mobInteract(pPlayer, pHand);
    }
}

public void tick() {
    super.tick();
    this.setYRot(this.yHeadRot);
    if (isInWater() && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (!isInWater() && !this.isLandNavigator) {
        switchNavigator(true);
    }
    Entity weapon = getTongue();
    if (weapon instanceof The_Leviathan_Tongue_Entity magneticWeapon) {
        this.entityData.set(TONGUE_ID, magneticWeapon.getId());
        magneticWeapon.setControllerUUID(this.getUUID());
    }

    if (!this.getPassengers().isEmpty() && this.getPassengers().get(0).isShiftKeyDown() && this.getAnimation() == LEVIATHAN_TENTACLE_HOLD_BLAST) {
        this.getPassengers().get(0).setShiftKeyDown(false);
    }


    LivingEntity target = this.getTarget();
    if (!level().isClientSide) {
        float halfHealth = this.getMaxHealth() / 2;
        if (!this.getMeltDown()) {
            this.bossInfo.setProgress((this.getHealth() - halfHealth) / (this.getMaxHealth() - halfHealth));
        }else{
            this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());
            this.bossInfo.setRenderType(6);
        }

    }

    final boolean groundAnimate = !this.isInWater();
    this.prevNoSwimProgress = NoSwimProgress;
    if (groundAnimate) {
        if (this.NoSwimProgress < 10F)
            this.NoSwimProgress++;
    } else {
        if (this.NoSwimProgress > 0F)
            this.NoSwimProgress--;
    }
    this.prevLeftTentacleProgress = LeftTentacleProgress;
    this.prevRightTentacleProgress = RightTentacleProgress;
    if (blocksByrighttentacle) {
        if (this.RightTentacleProgress < 10F)
            this.RightTentacleProgress++;
    } else {
        if (this.RightTentacleProgress > 0F)
            this.RightTentacleProgress--;
    }
    if (blocksBylefttentacle) {
        if (this.LeftTentacleProgress < 10F)
            this.LeftTentacleProgress++;
    } else {
        if (this.LeftTentacleProgress > 0F)
            this.LeftTentacleProgress--;
    }

    if (tickCount % 10 == 0) {
        blocksByrighttentacle = checkBlocksByTentacle(1,-3)
                || checkBlocksByTentacle(2,-3)
                || checkBlocksByTentacle(3,-3)
                || checkBlocksByTentacle(4,-3)
                || checkBlocksByTentacle(5,-3);
        blocksBylefttentacle = checkBlocksByTentacle(1,3)
                || checkBlocksByTentacle(2,3)
                || checkBlocksByTentacle(3,3)
                || checkBlocksByTentacle(4,3)
                || checkBlocksByTentacle(5,3);

    }

    if (this.portalTarget != null && this.portalTarget.getLifespan() < 5) {
        this.portalTarget = null;
    }
    if (teleportPos != null) {
        this.setPos(teleportPos.x, teleportPos.y, teleportPos.z);
        teleportPos = null;
    }
    if (makePortalCooldown > 0) {
        makePortalCooldown--;
    }

    if (hunting_cooldown > 0) {
        hunting_cooldown--;
    }

    if (bite_cooldown > 0) {
        bite_cooldown--;
    }

    if (melee_cooldown > 0) {
        melee_cooldown--;
    }


    if (!this.isNoAi()) {
        if (this.getAnimation() == NO_ANIMATION && !this.getMeltDown() && this.isMeltDown() && this.isAlive()) {
            this.setAnimation(LEVIATHAN_PHASE2);
        }
        if(this.getAnimation() == NO_ANIMATION &&  this.getTarget() !=null) {
            if (Math.abs(xo - this.getX()) < 0.01F && Math.abs(yo - this.getY()) < 0.01F && Math.abs(zo - this.getZ()) < 0.01F) {
                waterstillTicks++;
            } else {
                waterstillTicks = 0;
            }
            if (waterstillTicks > 40 && makePortalCooldown == 0) {
                createStuckPortal();
            }
        }
        if (!this.level().isClientSide) {
            if (this.destroyBlocksTick > 0) {
                --this.destroyBlocksTick;
                if (this.destroyBlocksTick == 0){
                    if(CMCommonConfig.Leviathan.ignoreMobGriefing){
                        blockbreak(0.5D,0.5D,0.5D);
                    }else{
                        if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                            blockbreak(0.5D,0.5D,0.5D);
                        }
                    }
                }
            }
            if(mode ==AttackMode.MELEE) {
                if (CMCommonConfig.Leviathan.ignoreMobGriefing) {
                    blockbreak2();
                } else {
                    if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                        blockbreak2();
                    }
                }
            }
        }
        final float f17 = this.getYRot() * (float) Math.PI / 180.0F;
        final float pitch = this.getXRot() * (float) Math.PI / 180.0F;
        final float f3 = Mth.sin(f17) * (1 - Math.abs(this.getXRot() / 90F));
        final float f18 = Mth.cos(f17) * (1 - Math.abs(this.getXRot() / 90F));
        this.setPartPosition(this.headPart, f3 * -3.8F, -pitch * 3F, -f18 * -3.8F);
        this.setPartPosition(this.tailPart1, f3 * 3.3F, -pitch * -5F, -f18 * 3.3F);
        this.setPartPosition(this.tailPart2, f3 * 4.7F, -pitch * -8F, -f18 * 4.7F);
        Vec3[] avector3d = new Vec3[this.leviathanParts.length];
        for (int j = 0; j < this.leviathanParts.length; ++j) {
            avector3d[j] = new Vec3(this.leviathanParts[j].getX(), this.leviathanParts[j].getY(), this.leviathanParts[j].getZ());
        }
        for (int l = 0; l < this.leviathanParts.length; ++l) {
            this.leviathanParts[l].xo = avector3d[l].x;
            this.leviathanParts[l].yo = avector3d[l].y;
            this.leviathanParts[l].zo = avector3d[l].z;
            this.leviathanParts[l].xOld = avector3d[l].x;
            this.leviathanParts[l].yOld = avector3d[l].y;
            this.leviathanParts[l].zOld = avector3d[l].z;
        }

    }
}

public void tick() {
    super.tick();
    prevLeapProgress = leapProgress;
    prevRunProgress = runProgress;
    prevChargeProgress = chargeProgress;
    prevSitProgress = sitProgress;
    prevTailYaw = tailYaw;
    prevVehicleProgress = vehicleProgress;
    prevManeAngle = maneAngle;
    prevLeapPitch = leapPitch;
    leapPitch = Mth.clamp((float) this.getDeltaMovement().y, -0.5F, 1.5F) * -(float) (180F / (float) Math.PI);
    if (this.isLeaping() && leapProgress < 5F) {
        leapProgress++;
    }
    if (!this.isLeaping() && leapProgress > 0F) {
        leapProgress--;
    }
    if (this.isRunning() && runProgress < 5F) {
        runProgress++;
    }
    if (!this.isRunning() && runProgress > 0F) {
        runProgress--;
    }
    if (this.isCharging() && chargeProgress < 5F) {
        chargeProgress++;
    }
    if (!this.isCharging() && chargeProgress > 0F) {
        chargeProgress = Math.max(0, chargeProgress - 0.25F);
    }
    if (this.isInSittingPose() && sitProgress < 5F) {
        sitProgress++;
    }
    if (!this.isInSittingPose() && sitProgress > 0F) {
        sitProgress--;
    }
    if (this.getControllingPassenger() != null && vehicleProgress < 5F) {
        vehicleProgress++;
    }
    if (this.getControllingPassenger() == null && vehicleProgress > 0F) {
        vehicleProgress--;
    }
    if(this.onGround() && this.isLeaping() && !leapImpulse){
        this.setLeaping(false);
    }
    if(leapImpulse){
        leapImpulse = false;
    }
    if(this.isCharging()){
        Vec3 chargeFocalPoint = this.position().add(new Vec3(0F, 0F, 1F).yRot((float) Math.toRadians(-this.getChargeYaw())));
        for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(3.5D))) {
            float dist = (float) entity.distanceToSqr(chargeFocalPoint);
            if (!(this.isTame() && isAlliedTo(entity)) && !entity.isPassengerOfSameVehicle(this) && !(entity instanceof CandicornEntity) && entity != this && dist < 7.0F) {
                float dmgExtra = 7.0F - dist;
                entity.hurt(this.damageSources().mobAttack(this), 7.0F + dmgExtra);
                entity.knockback(2.0F, chargeFocalPoint.x - entity.getX(), chargeFocalPoint.z - entity.getZ());
            }
        }
        if(!this.isVehicle()){
            this.setYRot(Mth.approachDegrees(this.yRotO, this.getChargeYaw(), 25));
            this.yBodyRot = Mth.approachDegrees(this.yBodyRot, this.getChargeYaw(), 25);
            this.yBodyRotO = this.yBodyRot;
            this.yHeadRot = this.getYRot();
            this.yHeadRotO = this.yHeadRot;
        }
    }
    if(chargeParticleCooldown <= 0 && this.chargeProgress > 2.5F){
        chargeParticleCooldown = 3;
        level().addAlwaysVisibleParticle(ACParticleRegistry.CANDICORN_CHARGE.get(), true, this.getX(), this.getY() + 0.5F, this.getZ(), this.getId(), 0.0F, this.getChargeYaw());
    }
    if(chargeParticleCooldown > 0){
        chargeParticleCooldown--;
    }
    if (!level().isClientSide) {
        if (this.getDeltaMovement().horizontalDistance() < 0.02 && random.nextInt(200) == 0 && controllerForwardsTicks <= 0 && this.getAnimation() == NO_ANIMATION && !this.isNoAi() && !this.isInSittingPose()) {
            Animation idle;
            float rand = random.nextFloat();
            if (rand < 0.15F) {
                idle = ANIMATION_BUCK;
            } else if (rand < 0.6F) {
                idle = random.nextBoolean() ? ANIMATION_TAIL_FLICK_1 : ANIMATION_TAIL_FLICK_2;
            } else {
                idle = ANIMATION_NIBBLE_IDLE;
            }
            this.setAnimation(idle);
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.5D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25D);
        }
    }else{
        Player player = AlexsCaves.PROXY.getClientSidePlayer();
        if (player != null && player.isPassengerOfSameVehicle(this)) {
            if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F && this.isRunning()) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
            }
        }
        spawnPossessedParticles(getRandomX(0.5D), getRandomY(), getRandomZ(0.5D), this.level());
    }
    Entity controllingPassenger = this.getControllingPassenger();
    if(controllingPassenger != null){
        float f = Mth.degreesDifference(controllingPassenger.getYHeadRot(), this.yBodyRot);
        if(Math.abs(f) > 2){
            if(f < 0){
                maneAngle = Mth.approach(maneAngle, -1F, 0.3F);
            }else{
                maneAngle = Mth.approach(maneAngle, 1F, 0.3F);
            }
        }
        if(!level().isClientSide) {
            if(this.touchingWall()){
                this.setRunning(false);
                this.setCharging(false);
                playerDrivenChargeTicks = 0;
                controllerForwardsTicks = 0;
            }
            if (playerDrivenChargeTicks > 0) {
                this.setCharging(true);
                this.setRunning(true);
                this.setChargeYaw(controllingPassenger.getYHeadRot());
                playerDrivenChargeTicks--;
            } else if (this.isCharging()) {
                this.setCharging(false);
            }
            if (controllerForwardsTicks > 20) {
                this.setRunning(true);
            } else {
                this.setRunning(false);
                this.setCharging(false);
                playerDrivenChargeTicks = 0;
            }
            if (this.getMeterAmount() < 1.0F && !this.isCharging() && this.isRunning()) {
                this.setMeterAmount(Math.min(this.getMeterAmount() + 0.005F, 1.0F));
            }
        }
    }else{
        if(controllerForwardsTicks > 0){
            controllerForwardsTicks = 0;
            this.setRunning(false);
        }
        if(playerDrivenChargeTicks > 0){
            playerDrivenChargeTicks = 0;
            this.setCharging(false);
        }
        this.setMeterAmount(0.0F);
    }
    if(this.isCharging() && isAlive()){
        AlexsCaves.PROXY.playWorldSound(this, (byte) 19);
    }
    tailYaw = Mth.approachDegrees(this.tailYaw, yBodyRot, 10);

    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
	super.tick();

	Level world = this.level();
	RandomSource random = this.random;
	if (this.isDeadOrDying()) {
		if (!this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT) && !this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT) && !world.isClientSide) {
			NetworkUtil.setPlayingAnimation(this, random.nextBoolean() ? EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT : EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT);
		}
		if (++this.deathTime >= 100) {
			if (!world.isClientSide) {
				ItemEntity elytra = this.spawnAtLocation(Items.ELYTRA);
				if (elytra != null) {
					elytra.setExtendedLifetime();
				}
				this.playSound(EESoundEvents.BROOD_EETLE_DEATH.get(), 2.0F, 0.9F + random.nextFloat() * 0.1F);
				this.discard();
				if (world instanceof ServerLevel serverLevel) {
					Vec3 eggSackPos = BroodEggSack.getEggPos(this.position(), this.yBodyRot, this.getEggCannonProgressServer(), this.getEggCannonFlyingProgressServer(), this.getFlyingRotations().getFlyPitch(), this.isOnLastHealthStage());
					serverLevel.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, EEBlocks.EETLE_EGG.get().defaultBlockState()), eggSackPos.x(), eggSackPos.y() + 0.83F, eggSackPos.z(), 30, 0.3125F, 0.3125F, 0.3125F, 0.2D);
					serverLevel.sendParticles(new CorrockCrownParticleData(EEParticleTypes.END_CROWN, 180, 61, 0.0F, 0.1F, Optional.of(0.15F)), eggSackPos.x(), eggSackPos.y() + 0.83F, eggSackPos.z(), 2000, 0.3125F, 0.3125F, 0.3125F, 1.0D);
				}
			} else {
				for (int i = 0; i < 20; ++i) {
					world.addParticle(ParticleTypes.POOF, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), random.nextGaussian() * 0.02D, random.nextGaussian() * 0.02D, random.nextGaussian() * 0.02D);
				}
			}
		} else if (world.isClientSide) {
			int deathTime = this.deathTime;
			if (deathTime == 30 || deathTime == 50 || deathTime == 70) {
				Vec3[] directionals = this.dyingParticleDirectionals = new Vec3[8];
				for (int i = 0; i < 8; i++) {
					double xOffset = MathUtil.makeNegativeRandomly(random.nextDouble() * 0.5D, random);
					double yOffset = random.nextDouble() * 1.5D;
					double zOffset = MathUtil.makeNegativeRandomly(random.nextDouble() * 0.5D, random);
					directionals[i] = new Vec3(xOffset, yOffset, zOffset);
				}
			}
			if (deathTime >= 35 && deathTime <= 85 && deathTime % 2 == 0 && ((deathTime - 35) % 20 + 20) % 20 <= 10) {
				Vec3[] dyingParticleDirectionals = this.dyingParticleDirectionals;
				if (dyingParticleDirectionals != null) {
					CorrockCrownParticleData dyingParticle = new CorrockCrownParticleData(EEParticleTypes.END_CROWN, 30, 10, 1.0F, 0.05F, Optional.of(0.2F));
					Vec3 eggSackPos = BroodEggSack.getEggPos(this.position(), this.yBodyRot, this.getEggCannonProgress(), this.getEggCannonFlyingProgress(), this.getFlyingRotations().getFlyPitch(), this.isOnLastHealthStage());
					double minY = eggSackPos.y() - 0.4D;
					for (int i = 0; i < 8; i++) {
						Vec3 directional = dyingParticleDirectionals[i];
						double x = eggSackPos.x() + directional.x();
						double y = minY + directional.y();
						double z = eggSackPos.z() + directional.z();
						world.addParticle(dyingParticle, x, y, z, directional.x(), 0.5D + random.nextDouble() * 0.05D, directional.z());
					}
				}
			}
		}
	}

	if (!world.isClientSide) {
		if (this.idleDelay > 0) this.idleDelay--;
		if (this.slamCooldown > 0) this.slamCooldown--;
		if (this.eggCannonCooldown > 0) this.eggCannonCooldown--;
		if (this.flyCooldown > 0) this.flyCooldown--;
		if (this.eggDropOffCooldown > 0) this.eggDropOffCooldown--;

		if (random.nextFloat() < 0.005F && this.idleDelay <= 0 && this.onGround() && !this.isFiringCannon() && this.isNoEndimationPlaying()) {
			NetworkUtil.setPlayingAnimation(this, random.nextFloat() < 0.6F && !this.isFlying() ? EEPlayableEndimations.BROOD_EETLE_FLAP : EEPlayableEndimations.BROOD_EETLE_MUNCH);
			this.resetIdleFlapDelay();
		}

		BroodEggSack eggSackEntity = this.getEggSack(world);
		if (eggSackEntity != null && eggSackEntity.isAlive()) {
			eggSackEntity.xo = eggSackEntity.xOld = eggSackEntity.getX();
			eggSackEntity.yo = eggSackEntity.yOld = eggSackEntity.getY();
			eggSackEntity.zo = eggSackEntity.zOld = eggSackEntity.getZ();
			eggSackEntity.updatePosition(this);
		} else {
			eggSackEntity = new BroodEggSack(world);
			eggSackEntity.setBroodID(this.getId());
			eggSackEntity.updatePosition(this);
			world.addFreshEntity(eggSackEntity);
			this.setEggSackID(eggSackEntity.getId());
		}

		if (this.isFlying()) {
			this.ticksFlying++;

			if (this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_AIR_SLAM) && this.getAnimationTick() == 5 && (this.onGround() || !this.level().noCollision(DetectionHelper.checkOnGround(this.getBoundingBox(), 0.25F)))) {
				BroodEetleSlamGoal.slam(this, random, 1.0F);
			}
		} else {
			this.ticksFlying = 0;
		}

		if (this.level().getGameTime() % 5 == 0) {
			BlockPos takeoffPos = this.takeoffPos;
			if (takeoffPos != null && this.position().distanceToSqr(Vec3.atLowerCornerOf(takeoffPos)) > 256.0F) {
				this.takeoffPos = null;
			}
		}

		float percentage = this.getHealth() / this.getMaxHealth();
		this.bossInfo.setProgress(percentage);
		if (percentage != this.prevHealthPercentage) {
			HealthStage newStage = HealthStage.getStage(percentage);
			if (newStage.eggGrowthChance > 0.0F && newStage.ordinal() > this.getHealthStage().ordinal()) {
				newStage.awakeNearbyEggs(this);
			}
			this.setHealthStage(newStage);
		}
		this.prevHealthPercentage = percentage;
	} else {
		TimedEndimation takeoff = this.takeoffEndimation;
		takeoff.tick();
		if (takeoff.isMaxed()) {
			this.takeoffMoving = true;
			takeoff.setDecrementing(true);
		} else {
			if (this.takeoffMoving) {
				this.takeoffMoving = takeoff.getTick() > 15;
			} else {
				takeoff.setDecrementing(!this.isFlying());
			}
		}

		this.wingFlapSpeed += this.isMoving() ? (0.5F - this.wingFlapSpeed) * 0.1F : (0.125F - this.wingFlapSpeed) * 0.2F;
		this.prevWingFlap = this.wingFlap;
		this.wingFlap += this.wingFlapSpeed;
	}

	TimedEndimation eggCannonEndimation = this.eggCannonEndimation;
	eggCannonEndimation.setDecrementing(!this.isFiringCannon() && !((this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT) || this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT)) && this.getAnimationTick() >= 15));
	eggCannonEndimation.tick();

	TimedEndimation eggMouthEndimation = this.eggMouthEndimation;
	eggMouthEndimation.setDecrementing(!eggCannonEndimation.isMaxed() && this.isNotDroppingEggs());
	eggMouthEndimation.tick();

	TimedEndimation eggCannonFlyingEndimation = this.eggCannonFlyingEndimation;
	eggCannonFlyingEndimation.setDecrementing(!this.isFlying());
	eggCannonFlyingEndimation.tick();

	TimedEndimation flying = this.flyingEndimation;
	flying.setDecrementing(!this.isMoving());
	flying.tick();

	TimedEndimation sleepingEndimation = this.sleepingEndimation;
	sleepingEndimation.setDecrementing(!this.isSleeping());
	sleepingEndimation.tick();

	TimedEndimation healPulseEndimation = this.healPulseEndimation;
	if (healPulseEndimation.isMaxed()) {
		healPulseEndimation.setDecrementing(true);
	}
	healPulseEndimation.tick();

	this.flyingRotations.tick(this.getTargetFlyingRotations());
}

public void tick() {
    super.tick();
    prevEnderiophageScale = this.getPhageScale();
    float extraMotionSlow = 1.0F;
    float extraMotionSlowY = 1.0F;
    if (slowDownTicks > 0) {
        slowDownTicks--;
        extraMotionSlow = 0.33F;
        extraMotionSlowY = 0.1F;
    }
    if (dismountCooldown > 0) {
        dismountCooldown--;
    }
    if (squishCooldown > 0) {
        squishCooldown--;
    }
    if (!this.level().isClientSide) {
        if (!this.isPassenger() && attachTime != 0) {
            attachTime = 0;
        }
        if (fleeAfterStealTime > 0) {
            if (angryEnderman != null) {
                Vec3 vec = this.getBlockInViewAway(angryEnderman.position(), 10);
                if (fleeAfterStealTime < 5) {
                    if (angryEnderman instanceof NeutralMob) {
                        ((NeutralMob) angryEnderman).stopBeingAngry();
                    }
                    try {
                        angryEnderman.goalSelector.getRunningGoals().forEach(Goal::stop);
                        angryEnderman.targetSelector.getRunningGoals().forEach(Goal::stop);
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                    angryEnderman = null;
                }
                if (vec != null) {
                    this.setFlying(true);
                    this.getMoveControl().setWantedPosition(vec.x, vec.y, vec.z, 1.3F);
                }
            }
            fleeAfterStealTime--;
        }
    }
    this.yBodyRot = this.getYRot();
    this.yHeadRot = this.getYRot();
    this.setPhagePitch(-90F);
    if (this.isAlive() && this.isFlying() && randomMotionSpeed > 0.75F && this.getDeltaMovement().lengthSqr() > 0.02D) {
        if (this.level().isClientSide) {
            float pitch = -this.getPhagePitch() / 90F;
            float radius = this.getBbWidth() * 0.2F * -pitch;
            float angle = (Maths.STARTING_ANGLE * this.getYRot());
            double extraX = radius * Mth.sin(Mth.PI + angle);
            double extraY = 0.2F - (1 - pitch) * 0.15F;
            double extraZ = radius * Mth.cos(angle);
            double motX = extraX * 8 + random.nextGaussian() * 0.05F;
            double motY = -0.1F;
            double motZ = extraZ + random.nextGaussian() * 0.05F;
            this.level().addParticle(AMParticleRegistry.DNA.get(), this.getX() + extraX, this.getY() + extraY, this.getZ() + extraZ, motX, motY, motZ);
        }
    }
    prevPhagePitch = this.getPhagePitch();
    prevFlyProgress = flyProgress;

    if (isFlying()) {
        if (flyProgress < 5F) {
            flyProgress++;
        }
    } else {
        if (flyProgress > 0F) {
            flyProgress--;
        }
    }

    this.lastTentacleAngle = this.tentacleAngle;
    this.phageRotation += this.rotationVelocity;
    if ((double) this.phageRotation > (Math.PI * 2D)) {
        if (this.level().isClientSide) {
            this.phageRotation = Mth.TWO_PI;
        } else {
            this.phageRotation = (float) ((double) this.phageRotation - (Math.PI * 2D));
            if (this.random.nextInt(10) == 0) {
                this.rotationVelocity = 1.0F / (this.random.nextFloat() + 1.0F) * 0.2F;
            }
            this.level().broadcastEntityEvent(this, (byte) 19);
        }
    }
    if (this.phageRotation < Mth.PI) {
        float f = this.phageRotation / Mth.PI;
        this.tentacleAngle = Mth.sin(f * f * Mth.PI) * 4.275F;
        if ((double) f > 0.75D) {
            if (squishCooldown == 0 && this.isFlying()) {
                squishCooldown = 20;
                this.playSound(AMSoundRegistry.ENDERIOPHAGE_SQUISH.get(), 3F, this.getVoicePitch());
            }
            this.randomMotionSpeed = 1.0F;
        } else {
            randomMotionSpeed = 0.01F;
        }
    }
    if (!this.level().isClientSide) {
        if (isFlying() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!isFlying() && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (this.isFlying()) {
            this.setDeltaMovement(this.getDeltaMovement().x * this.randomMotionSpeed * extraMotionSlow, this.getDeltaMovement().y * this.randomMotionSpeed * extraMotionSlowY, this.getDeltaMovement().z * this.randomMotionSpeed * extraMotionSlow);
            timeFlying++;
            if (this.onGround() && timeFlying > 100) {
                this.setFlying(false);
            }
        } else {
            timeFlying = 0;
        }
        if (this.isMissingEye() && this.getTarget() != null) {
            if (!(this.getTarget() instanceof EnderMan)) {
                this.setTarget(null);
            }
        }
    }
    if (!this.onGround() && this.getDeltaMovement().y < 0.0D) {
        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0D, 0.6D, 1.0D));
    }
    if (this.isFlying()) {
        float phageDist = -(float) ((Math.abs(this.getDeltaMovement().x()) + Math.abs(this.getDeltaMovement().z())) * 6F);
        this.incrementPhagePitch(phageDist * 1);
        this.setPhagePitch(Mth.clamp(this.getPhagePitch(), -90, 10));
        float plateau = 2;
        if (this.getPhagePitch() > plateau) {
            this.decrementPhagePitch(phageDist * Math.abs(this.getPhagePitch()) / 90);
        }
        if (this.getPhagePitch() < -plateau) {
            this.incrementPhagePitch(phageDist * Math.abs(this.getPhagePitch()) / 90);
        }
        if (this.getPhagePitch() > 2F) {
            this.decrementPhagePitch(1);
        } else if (this.getPhagePitch() < -2) {
            this.incrementPhagePitch(1);
        }
        if (this.horizontalCollision) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.2F, 0));
        }
    } else {
        if (this.getPhagePitch() > 0F) {
            float decrease = Math.min(2, this.getPhagePitch());
            this.decrementPhagePitch(decrease);
        }
        if (this.getPhagePitch() < 0F) {
            float decrease = Math.min(2, -this.getPhagePitch());
            this.incrementPhagePitch(decrease);
        }
    }
    if (this.getPhageScale() < 1F) {
        this.setPhageScale(this.getPhageScale() + 0.05F);
    }
}

public void travel(Vector3d travelVector) {
	if (isEffectiveAi() || isControlledByLocalInstance()) {
		ModifiableAttributeInstance gravity = getAttribute(ForgeMod.ENTITY_GRAVITY.get());
		boolean isFalling = getDeltaMovement().y <= 0.0D;

		if (isFalling && hasEffect(Effects.SLOW_FALLING)) {
			if (!gravity.hasModifier(SLOW_FALLING)) gravity.addTransientModifier(SLOW_FALLING);
				fallDistance = 0.0F;
		}
		else if (gravity.hasModifier(SLOW_FALLING)) {
			gravity.removeModifier(SLOW_FALLING);
		}

		double gravityValue = gravity.getValue();

		FluidState fluidState = level.getFluidState(blockPosition());

		if (isInWater() && isAffectedByFluids() && !canStandOnFluid(fluidState.getType())) {
			double initialYPos = getY();
			float drag = isSprinting() ? 0.9F : getWaterSlowDown();
			float swimMotionFactor = 0.02F;
			float depthStrider = (float)EnchantmentHelper.getDepthStrider(this);

			if (depthStrider > 3.0F)
				depthStrider = 3.0F;

			if (!onGround)
				depthStrider *= 0.5F;

			if (depthStrider > 0.0F) {
				drag += (0.54600006F - drag) * depthStrider / 3.0F;
				swimMotionFactor += (getSpeed() - swimMotionFactor) * depthStrider / 3.0F;
			}

			if (hasEffect(Effects.DOLPHINS_GRACE))
				drag = 0.96F;

			swimMotionFactor *= (float)getAttribute(ForgeMod.SWIM_SPEED.get()).getValue();

			moveRelative(swimMotionFactor, travelVector);
			move(MoverType.SELF, getDeltaMovement());

			Vector3d vector3d6 = getDeltaMovement();

			if (horizontalCollision && onClimbable())
				vector3d6 = new Vector3d(vector3d6.x, 0.2D, vector3d6.z);

			setDeltaMovement(vector3d6.multiply(drag, 0.8F, drag));

			Vector3d constrainedMotion = getFluidFallingAdjustedMovement(gravityValue, isFalling, getDeltaMovement());

			setDeltaMovement(constrainedMotion);

			if (horizontalCollision && isFree(constrainedMotion.x, constrainedMotion.y + (double)0.6F - getY() + initialYPos, constrainedMotion.z))
				setDeltaMovement(constrainedMotion.x, 0.3F, constrainedMotion.z);
		}
		else if (isInLava() && isAffectedByFluids() && !canStandOnFluid(fluidState.getType())) {
			double originalYPos = getY();
			moveRelative(0.02F, travelVector);
			move(MoverType.SELF, getDeltaMovement());

			if (getFluidHeight(FluidTags.LAVA) <= getFluidJumpThreshold()) {
				setDeltaMovement(getDeltaMovement().multiply(0.5D, 0.8F, 0.5D));

				Vector3d constrainedMotion = getFluidFallingAdjustedMovement(gravityValue, isFalling, getDeltaMovement());

				setDeltaMovement(constrainedMotion);
			}
			else {
				setDeltaMovement(getDeltaMovement().scale(0.5D));
			}

			if (!isNoGravity())
				setDeltaMovement(getDeltaMovement().add(0.0D, -gravityValue / 4.0D, 0.0D));

			Vector3d newMotion = getDeltaMovement();

			if (horizontalCollision && isFree(newMotion.x, newMotion.y + (double)0.6F - getY() + originalYPos, newMotion.z))
				setDeltaMovement(newMotion.x, 0.3F, newMotion.z);
		}
		else if (isFallFlying()) {
			Vector3d curMotion = getDeltaMovement();

			if (curMotion.y > -0.5D)
				fallDistance = 1.0F;

			Vector3d lookVec = getLookAngle();
			float normalizedPitch = xRot * ((float)Math.PI / 180F);
			double lookHypot = Math.sqrt(lookVec.x * lookVec.x + lookVec.z * lookVec.z);
			double lateralMotion = Math.sqrt(getHorizontalDistanceSqr(curMotion));
			double lookVecLength = lookVec.length();
			float pitchRotation = MathHelper.cos(normalizedPitch);
			pitchRotation = (float)((double)pitchRotation * (double)pitchRotation * Math.min(1.0D, lookVecLength / 0.4D));
			curMotion = getDeltaMovement().add(0.0D, gravityValue * (-1.0D + (double)pitchRotation * 0.75D), 0.0D);

			if (curMotion.y < 0.0D && lookHypot > 0.0D) {
				double verticalVelocityAdjust = curMotion.y * -0.1D * (double)pitchRotation;
				curMotion = curMotion.add(lookVec.x * verticalVelocityAdjust / lookHypot, verticalVelocityAdjust, lookVec.z * verticalVelocityAdjust / lookHypot);
			}

			if (normalizedPitch < 0.0F && lookHypot > 0.0D) {
				double lateralVelocityAdjust = lateralMotion * (double)(-MathHelper.sin(normalizedPitch)) * 0.04D;
				curMotion = curMotion.add(-lookVec.x * lateralVelocityAdjust / lookHypot, lateralVelocityAdjust * 3.2D, -lookVec.z * lateralVelocityAdjust / lookHypot);
			}

			if (lookHypot > 0.0D)
				curMotion = curMotion.add((lookVec.x / lookHypot * lateralMotion - curMotion.x) * 0.1D, 0.0D, (lookVec.z / lookHypot * lateralMotion - curMotion.z) * 0.1D);

			setDeltaMovement(curMotion.multiply(0.99F, 0.98F, 0.99F));
			move(MoverType.SELF, getDeltaMovement());

			if (horizontalCollision && !level.isClientSide) {
				double newLateralMotion = Math.sqrt(getHorizontalDistanceSqr(getDeltaMovement()));
				double lateralMotionDiff = lateralMotion - newLateralMotion;
				float lateralCollisionSpeed = (float)(lateralMotionDiff * 10.0D - 3.0D);

				if (lateralCollisionSpeed > 0.0F) {
					playSound(getFallDamageSound((int)lateralCollisionSpeed), 1.0F, 1.0F);
					hurt(DamageSource.FLY_INTO_WALL, lateralCollisionSpeed);
				}
			}

			if (onGround && !level.isClientSide)
				setSharedFlag(7, false);
		}
		else {
			BlockPos standingPosition = getBlockPosBelowThatAffectsMyMovement();
			float blockSlipperiness = level.getBlockState(getBlockPosBelowThatAffectsMyMovement()).getSlipperiness(level, getBlockPosBelowThatAffectsMyMovement(), this);
			float friction = onGround ? blockSlipperiness * 0.91F : 0.91F;
			Vector3d newMotion = handleRelativeFrictionAndCalculateMovement(travelVector, blockSlipperiness);
			double verticalMotion = newMotion.y;

			if (isSlipperyMovement)
				friction *= 0.9f;

			if (hasEffect(Effects.LEVITATION)) {
				verticalMotion += (0.05D * (double)(getEffect(Effects.LEVITATION).getAmplifier() + 1) - newMotion.y) * 0.2D;
				fallDistance = 0.0F;
			}
			else if (level.isClientSide && !level.hasChunkAt(standingPosition)) {
				if (getY() > 0.0D) {
					verticalMotion = -0.1D;
				}
				else {
					verticalMotion = 0.0D;
				}
			}
			else if (!isNoGravity()) {
				verticalMotion -= gravityValue;
			}

			setDeltaMovement(newMotion.x * (double)friction, verticalMotion * (double)0.98F, newMotion.z * (double)friction);
		}
	}

	calculateEntityAnimation(this, this instanceof IFlyingAnimal);
}

public void onUpdate() {
    super.onUpdate();
    if(this.world.isRemote && this.dataManager.get(WATCHER_WAS_FED)) {
        this.world.spawnParticle(EnumParticleTypes.VILLAGER_HAPPY, this.posX + (double)(this.rand.nextFloat() * this.width * 2.0F) - (double)this.width, this.posY + 0.5D + (double)(this.rand.nextFloat() * this.height), this.posZ + (double)(this.rand.nextFloat() * this.width * 2.0F) - (double)this.width, 0.0D, 0.0D, 0.0D);
    }
    if (!this.world.isRemote) {
        DinosaurPersistenceHandler.trackEntity(this);
    }
    if(this.ticksUntilDeath > 0) {
        if(--this.ticksUntilDeath == 0) {
            this.playSound(this.getSoundForAnimation(EntityAnimation.DYING.get()), this.getSoundVolume(), this.getSoundPitch());
            this.setHealth(this.getMaxHealth());
            this.setCarcass(true);
        }
    }

    if (this.attackCooldown > 0) {
        this.attackCooldown--;
    }

    if (!this.world.isRemote) {
        if (this.animation == EntityAnimation.LEAP.get()) {
            if (this.motionY < 0) {
                this.setAnimation(EntityAnimation.LEAP_LAND.get());
            }
        } else if (this.animation == EntityAnimation.LEAP_LAND.get() && (this.onGround || this.isSwimming())) {
            this.setAnimation(EntityAnimation.IDLE.get());
        }
    }

    if (this.animation != null && this.animation != EntityAnimation.IDLE.get()) {
        boolean shouldHold = EntityAnimation.getAnimation(this.animation).shouldHold();

        if (this.animationTick < this.animationLength) {
            this.animationTick++;
        } else if (!shouldHold) {
            this.animationTick = 0;
            if (this.animation == EntityAnimation.PREPARE_LEAP.get()) {
                this.setAnimation(EntityAnimation.LEAP.get());
            } else {
                this.setAnimation(EntityAnimation.IDLE.get());
            }
        } else {
            this.animationTick = this.animationLength - 1;
        }
    }

    if (!this.world.isRemote) {
        this.dataManager.set(WATCHER_WAS_MOVED, this.wasMoved);
        this.dataManager.set(WATCHER_AGE, this.dinosaurAge);
        this.dataManager.set(WATCHER_IS_SLEEPING, this.isSleeping);
        this.dataManager.set(WATCHER_IS_CARCASS, this.isCarcass);
        this.dataManager.set(WATCHER_TRACKERS, new ArrayList<>(this.trackersUUID)); // Ensure a new list is set
        this.dataManager.set(WATCHER_CURRENT_ORDER, (byte) this.order.ordinal());
        this.dataManager.set(WATCHER_OWNER_IDENTIFIER, this.owner != null ? this.owner.toString() : "");
        this.dataManager.set(WATCHER_IS_RUNNING, this.getAIMoveSpeed() > this.getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getAttributeValue());
    } else {
        this.updateTailBuffer();
        this.wasMoved = this.dataManager.get(WATCHER_WAS_MOVED);
        this.dinosaurAge = this.dataManager.get(WATCHER_AGE);
        this.isSleeping = this.dataManager.get(WATCHER_IS_SLEEPING);
        this.isCarcass = this.dataManager.get(WATCHER_IS_CARCASS);
        try {
            this.trackersUUID = new ArrayList<>(this.dataManager.get(WATCHER_TRACKERS));
        } catch (ClassCastException e) {
            this.trackersUUID = new ArrayList<>();
        }
        String owner = this.dataManager.get(WATCHER_OWNER_IDENTIFIER);
        this.order = Order.values()[this.dataManager.get(WATCHER_CURRENT_ORDER)];

        if (!owner.isEmpty() && (this.owner == null || !owner.equals(this.owner.toString()))) {
            this.owner = UUID.fromString(owner);
        } else if (owner.isEmpty()) {
            this.owner = null;
        }
    }

    if (this.ticksExisted % 20 == 0) {
        this.updateAttributes();
        this.updateBounds();
    }

    if (this.isCarcass) {
        this.renderYawOffset = this.rotationYaw;
        this.rotationYawHead = this.rotationYaw;
    }

    if (this.isSleeping) {
        if (this.getAnimation() != EntityAnimation.SLEEPING.get()) {
            this.setAnimation(EntityAnimation.SLEEPING.get());
        }
    } else if (this.getAnimation() == EntityAnimation.SLEEPING.get()) {
        this.setAnimation(EntityAnimation.IDLE.get());
    }

    if (!this.world.isRemote) {
        if (this.isCarcass) {
            if (this.getAnimation() != EntityAnimation.DYING.get()) {
                this.setAnimation(EntityAnimation.DYING.get());
            }

            if (this.ticksExisted % 1000 == 0) {
                this.attackEntityFrom(DamageSource.GENERIC, 1.0F);
            }
        } else {
            if (this.isSleeping) {
                if (this.ticksExisted % 20 == 0) {
                    if (this.stayAwakeTime <= 0 && this.hasPredators()) {
                        this.disturbSleep();
                    }
                }

                if (!this.shouldSleep() && !this.world.isRemote && tranquilizerTicks-- <= 0) {
                    this.isSleeping = false;
                    this.tranquilizerTicks = 0;
                    this.tranqed = false;
                }
            } else if (this.getAnimation() == EntityAnimation.SLEEPING.get()) {
                this.setAnimation(EntityAnimation.IDLE.get());
            }

            if (!this.isSleeping) {
                if (this.order == Order.SIT) {
                    if (this.getAnimation() != EntityAnimation.RESTING.get()) {
                        this.setAnimation(EntityAnimation.RESTING.get());
                    }
                } else if (!this.isSittingNaturally && this.getAnimation() == EntityAnimation.RESTING.get() && !this.world.isRemote) {
                    this.setAnimation(EntityAnimation.IDLE.get());
                }
            }
        }
    }

    if (!this.shouldSleep() && !this.isSleeping) {
        this.stayAwakeTime = 0;
    }

    if (this.isServerWorld()) {
        this.animationTasks.onUpdateTasks();
    }

    if (this.stayAwakeTime > 0) {
        this.stayAwakeTime--;
    }
    if (this.wireTicks > 0) {
        this.wireTicks--;
    }
    if (this.disableHerdingTicks > 0) {
        this.disableHerdingTicks--;
    }

    if (this.legSolver != null) {
        double msc = dinosaur.getScaleInfant() / dinosaur.getScaleAdult();
        this.legSolver.update(this, (float) this.interpolate(msc, 1.0) * this.getAttributes().getScaleModifier());
    }

    this.prevAge = this.dinosaurAge;
}

public void tick() {
    super.tick();

    LivingEntity target = elokosa.getTarget();
    if (target != null) {
        double distToTarget = this.elokosa.distanceTo(target);

        elokosa.getLookControl().setLookAt(target);

        // Stalking
        if (elokosa.isStalking) {
            if (elokosa.stalkingTimer <= 0 && elokosa.getActiveAbility() == null) {
                elokosa.isStalking = false;
                AbilityHandler.INSTANCE.sendAbilityMessage(elokosa, SCREAM_ABILITY);
            }
            if (target.tickCount - target.getLastHurtByMobTimestamp() < 20 && target.getLastHurtByMob() instanceof EntityElokosa) {
                elokosa.isStalking = false;
            }
        }
        // Not stalking
        else {
            Path path = this.elokosa.getNavigation().createPath(target, 0);
            if (path == null) {
                // Leap to target
                if (elokosa.isOnGroundOrClinging() && (elokosa.getActiveAbility() == null || elokosa.getActiveAbility().getAbilityType() == SCREAM_ABILITY && elokosa.getActiveAbility().getTicksInUse() >= SCREAM_CANCEL_TICK)) {
                    Vec3 vecBetween = target.position().multiply(1, 0, 1).subtract(elokosa.position().multiply(1, 0, 1)).normalize();
                    elokosa.jumpGoalPos = target.position().add(vecBetween.scale(-2));
                    elokosa.jumpVel = elokosa.calculateOptimalJumpVector(elokosa, elokosa.jumpGoalPos);
                    if (elokosa.jumpVel != null) {
                        elokosa.sendAbilityMessage(LEAP_TO_TARGET_ABILITY);
                    }
                }
            }
            else {
                float frontBackDistBuffer = 2f;
                float leftRightDistBuffer = 1.5f;
                if (chasing && distToTarget <= attackRadius) {
                    chasing = false;
                }
                if (!chasing && distToTarget >= attackRadius + frontBackDistBuffer + 2) {
                    chasing = true;
                    attackRadius = elokosa.random.nextFloat() * (ATTACK_RADIUS_MAX - ATTACK_RADIUS_MIN) + ATTACK_RADIUS_MIN;
                }

                if (fleeing && distToTarget >= attackRadius || fleeingTimer >= 100) {
                    fleeing = false;
                    fleeingTimer = 0;
                }
                if (!fleeing && distToTarget <= attackRadius - frontBackDistBuffer && !hasReturnedToCircleAfterAttacking && !attacking) {
                    fleeing = true;
                    attackRadius = elokosa.random.nextFloat() * (ATTACK_RADIUS_MAX - ATTACK_RADIUS_MIN) + ATTACK_RADIUS_MIN;
                }


                if (!attacking && elokosa.getActiveAbility() == null && distToTarget <= 4.5 && elokosa.getDotProductBodyFacingEntity(target) > 0.3 && (elokosa.damageThreat > 0.5 || elokosa.random.nextFloat() > 0.7) && elokosa.dodgeCooldown.isFinished()) {
                    elokosa.dodgeCooldown.startCooldown();
                    AbilityHandler.INSTANCE.sendAbilityMessage(elokosa, BACKFLIP_ABILITY);
                    return;
                }

                // Chasing
                if (chasing) {
                    this.elokosa.setXxa(0);
                    this.elokosa.getNavigation().moveTo(target, 2);

                    this.elokosa.getLookControl().setLookAt(target, 30.0F, 30.0F);
                    elokosa.setStrafing(false);
                }
                else if (fleeing && !attacking) {
                    this.elokosa.setXxa(0);
                    Vec3 vecBetween = target.position().subtract(elokosa.position());
                    vecBetween = vecBetween.normalize();
                    Vec3 fleePos = elokosa.position().add(vecBetween.scale(-5));
                    this.elokosa.getNavigation().moveTo(fleePos.x, fleePos.y, fleePos.z, 2);
                    this.elokosa.getLookControl().setLookAt(target, 30.0F, 30.0F);
                    elokosa.setStrafing(false);
                    fleeingTimer++;
                }
                else {
                    // In range
                    if (!attacking && elokosa.getActiveAbility() == null) {
                        this.elokosa.getNavigation().stop();
                        float strafeSpeed = 1f;
                        Vec3 circlePos = elokosa.updateCirclingPosition(1f);
                        double distToCirclePos = this.elokosa.position().distanceTo(circlePos);

                        if (distToCirclePos <= leftRightDistBuffer) {
                            hasReturnedToCircleAfterAttacking = true;
                            elokosa.setStrafing(true);

                            if (distToTarget > this.attackRadius + 0.5) {
                                this.strafingFrontBackMul = 1;
                            } else if (distToTarget < this.attackRadius - 0.5) {
                                this.strafingFrontBackMul = -1;
                            } else {
                                this.strafingFrontBackMul = 0;
                            }

                            Vec3 toTarget = target.position().subtract(this.elokosa.position()).multiply(1, 0, 1).normalize();
                            Vec3 toCirclePos = circlePos.subtract(this.elokosa.position()).multiply(1, 0, 1).normalize();
                            Vec3 cross = toTarget.cross(toCirclePos);
                            if (cross.y > 0) strafingLeftRightMul = 1;
                            else if (cross.y < 0) strafingLeftRightMul = -1;
                            else strafingLeftRightMul = 0;

                            float distScale = (float) Math.min(Math.pow(distToCirclePos * 1f / leftRightDistBuffer, 0.7), 1.0);

                            this.elokosa.getMoveControl().strafe(this.strafingFrontBackMul * strafeSpeed, this.strafingLeftRightMul * strafeSpeed * distScale);
                            this.elokosa.lookAt(target, 30.0F, 30.0F);

                            if (elokosa.random.nextFloat() < 0.002) {
                                elokosa.sendAbilityMessage(SCREAM_ABILITY);
                            }
                        } else {
                            this.elokosa.setXxa(0);
                            elokosa.setStrafing(false);
                            this.elokosa.getNavigation().moveTo(circlePos.x, circlePos.y, circlePos.z, 1.7);
                            this.elokosa.getLookControl().setLookAt(target, 30.0F, 30.0F);
                        }
                    } else {
                        this.elokosa.setXxa(0);
                        elokosa.setStrafing(false);
                    }

                    // Attacking logic
                    if (elokosa.random.nextInt(50) == 0 && elokosa.attackCooldown.isFinished() && elokosa.getSensing().hasLineOfSight(target)) {
                        attacking = true;
                        numberOfAttacksLeft = elokosa.random.nextInt(1, 3);
                        hasReturnedToCircleAfterAttacking = false;
                    }
                    if ((attacking || hasReturnedToCircleAfterAttacking && elokosa.random.nextInt(30) == 0 && distToTarget <= 4) && elokosa.getActiveAbility() == null) {
                        this.elokosa.setXxa(0);
                        elokosa.setStrafing(false);
                        elokosa.getNavigation().moveTo(target, 2);
                        float distanceThreshold = doCombo ? 3.75f : 4.75f;
                        if (distToTarget <= distanceThreshold && elokosa.getSensing().hasLineOfSight(target)) {
                            doCombo = elokosa.random.nextFloat() > 0.5;
                            // 1/3 chance to attack again with no cooldown
                            if (numberOfAttacksLeft <= 0) {
                                attacking = false;
                                elokosa.attackCooldown.startCooldown();
                            }
                            if (doCombo) {
                                if (elokosa.random.nextFloat() < 0.25) {
                                    AbilityHandler.INSTANCE.sendAbilityMessage(elokosa, ATTACK_COMBO_ROAR_ABILITY);
                                } else {
                                    AbilityHandler.INSTANCE.sendAbilityMessage(elokosa, ATTACK_COMBO_ABILITY);
                                }
                            }
                            else {
                                AbilityHandler.INSTANCE.sendAbilityMessage(elokosa, ATTACK_ABILITY);
                            }
                            numberOfAttacksLeft--;
                        }
                    }
                }
            }
        }
    }
}

public void aiStep() {
    Vec3 vec3 = this.getDeltaMovement().multiply(1.0D, 0.6D, 1.0D);
    this.bossEvent.setProgress(this.getHealth() / this.getMaxHealth());
    prev_Laser_Mode_Progress = Laser_Mode_Progress;
    if (this.getIsLaserMode() && Laser_Mode_Progress < 30f) {
        Laser_Mode_Progress++;
    }
    if (!this.getIsLaserMode() && Laser_Mode_Progress > 0F) {
        Laser_Mode_Progress--;
    }
    prevdeactivateProgress = deactivateProgress;
    if (!this.getIsAct() && deactivateProgress < 40F) {
        deactivateProgress = 40;
    }
    if (this.getIsAct() && deactivateProgress > 0F) {
        deactivateProgress--;
    }
    if (this.getIsAct()) {
        if (skill_cooldown > 0) skill_cooldown--;
    }


    Entity entity = this.level().getEntity(this.getAlternativeTarget(0));
    if (!this.level().isClientSide && this.getAlternativeTarget(0) > 0 && this.isAlive() && !this.getIsCharge() && this.getAnimation() != STUN_ANIAMATION) {
        if (entity != null) {
            double d0 = vec3.y;
            double l0 = (this.getAnimation() == MISSILE_FIRE_FAST_ANIAMATION || this.getAnimation() == MISSILE_FIRE_ANIAMATION || this.getAnimation() == LAUNCH_ANIAMATION) ? 1.0D : 2.25d;
            if (this.getY() < entity.getY() + l0) {
                d0 = Math.max(0.0D, d0);
                d0 += 0.3D - d0 * (double) 0.6F;
            }
            vec3 = new Vec3(vec3.x, d0, vec3.z);
            Vec3 vec31 = new Vec3(entity.getX() - this.getX(), 0.0D, entity.getZ() - this.getZ());
            if (vec31.horizontalDistanceSqr() > 25.0D && !(this.getAnimation() == DEATHLASER_ANIMATION && this.getAnimationTick() > 13 || this.getAnimation() == MISSILE_FIRE_ANIAMATION || this.getAnimation() == MISSILE_FIRE_FAST_ANIAMATION)) {
                Vec3 vec32 = vec31.normalize();
                vec3 = vec3.add(vec32.x * 0.3D - vec3.x * 0.6D, 0.0D, vec32.z * 0.3D - vec3.z * 0.6D);
            }

        }
    }

    LivingEntity target = this.getTarget();
    if (this.getIsAct()) {
        if (this.isAlive() && this.deactivateProgress == 0) {
            if (target != null && target.isAlive() && skill_cooldown <= 0 && (Laser_Mode_Progress == 30 || Laser_Mode_Progress == 0)) {
                if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getOverload() >= 3 && this.getRandom().nextFloat() * 100.0F < 3f) {
                    skill_cooldown = SKILL_COOLDOWN;
                    this.setAnimation(DEATHLASER_ANIMATION);
                } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getOverload() < 3 && this.distanceToSqr(target) < 64 && (this.getRandom().nextFloat() * 100.0F < 4f && this.hasLineOfSight(target) || this.getRandom().nextFloat() * 100.0F < 20f && !this.hasLineOfSight(target))) {
                    skill_cooldown = SKILL_COOLDOWN;
                    this.setAnimation(CHARGE_ANIMATION);
                } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getOverload() < 3 && this.getRandom().nextFloat() * 100.0F < 3f && Laser_Mode_Progress == 0) {
                    skill_cooldown = SKILL_COOLDOWN;
                    this.setAnimation(LAUNCH_ANIAMATION);
                } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getOverload() < 3 && this.getRandom().nextFloat() * 100.0F < 1.5f) {
                    skill_cooldown = SKILL_COOLDOWN;
                    Animation missile = this.isPowered() ? MISSILE_FIRE_FAST_ANIAMATION : MISSILE_FIRE_ANIAMATION;
                    this.setAnimation(missile);
                }
            }
        }
    }
    this.setDeltaMovement(vec3);
    if (vec3.horizontalDistanceSqr() > 0.05D) {
        this.setYRot((float) Mth.atan2(vec3.z, vec3.x) * (180F / (float) Math.PI) - 90.0F);
    }

    super.aiStep();
    for (int i = 0; i < 2; ++i) {
        this.yRotOHeads[i] = this.yRotHeads[i];
        this.xRotOHeads[i] = this.xRotHeads[i];
    }


    if ((this.getAnimation() != CHARGE_ANIMATION) && getIsCharge()) {
        setIsCharge(false);
    }
    //setInvulnerable(!getIsAct());
    if (this.getAnimation() == STUN_ANIAMATION) {
        if (this.getAnimationTick() == 15) {
            this.level().playSound((Player) null, this, ModSounds.HARBINGER_STUN.get(), SoundSource.HOSTILE, 4F, level().random.nextFloat() * 0.2F + 1.0F);
        }
    }
    if (this.getAnimation() == DEATHLASER_ANIMATION) {
        if (this.getAnimationTick() == 33) {
            this.level().playSound((Player) null, this, ModSounds.DEATH_LASER.get(), SoundSource.HOSTILE, 4.0f, 0.75f);
        }
    }

    if (this.getAnimation() == CHARGE_ANIMATION) {
        if (this.getAnimationTick() == 24) {
            this.level().playSound((Player) null, this, ModSounds.HARBINGER_CHARGE.get(), SoundSource.HOSTILE, 4.0f, 0.65f);
        }
    }
    if (this.getAnimation() == MISSILE_FIRE_ANIAMATION || this.getAnimation() == MISSILE_FIRE_FAST_ANIAMATION) {
        if (this.getAnimationTick() == 24) {
            this.level().playSound((Player) null, this, ModSounds.HARBINGER_PREPARE.get(), SoundSource.HOSTILE, 4.0f, 1.0f);
        }
    }


    for (int j = 0; j < 2; ++j) {
        int k = this.getAlternativeTarget(j + 1);
        Entity entity1 = null;
        if (k > 0) {
            entity1 = this.level().getEntity(k);
        }

        if (entity1 != null) {
            double d9 = this.getHeadX(j + 1);
            double d1 = this.getHeadY(j + 1);
            double d3 = this.getHeadZ(j + 1);
            double d4 = entity1.getX() - d9;
            double d5 = entity1.getEyeY() - d1;
            double d6 = entity1.getZ() - d3;
            double d7 = Math.sqrt(d4 * d4 + d6 * d6);
            float f = (float) (Mth.atan2(d6, d4) * (double) (180F / (float) Math.PI)) - 90.0F;
            float f1 = (float) (-(Mth.atan2(d5, d7) * (double) (180F / (float) Math.PI)));
            this.xRotHeads[j] = this.m_31442_(this.xRotHeads[j], f1, 40.0F);
            this.yRotHeads[j] = this.m_31442_(this.yRotHeads[j], f, 10.0F);
        } else {
            this.yRotHeads[j] = this.m_31442_(this.yRotHeads[j], this.yBodyRot, 10.0F);
        }
    }
    if (this.level().isClientSide) {
        if (this.getIsAct()) {
            double d0 = (random.nextFloat() - 0.5F) + this.getDeltaMovement().x;
            double d1 = (random.nextFloat() - 0.5F) + this.getDeltaMovement().y;
            double d2 = (random.nextFloat() - 0.5F) + this.getDeltaMovement().z;
            double dist = 1F + random.nextFloat() * 0.2F;
            double d3 = d0 * dist;
            double d4 = d1 * dist;
            double d5 = d2 * dist;
            this.level().addParticle(new LightningParticleOptions(255, 51,  0), this.getX() + d0, this.getY() + 2, this.getZ() + d2, d3, d4, d5);

            if (entity != null && this.getAnimation() != MISSILE_FIRE_ANIAMATION) {
                float f = Mth.cos((yBodyRot) * ((float) Math.PI / 180F));
                float f1 = Mth.sin((yBodyRot) * ((float) Math.PI / 180F));
                double theta = (yBodyRot) * (Math.PI / 180);
                theta += Math.PI / 2;
                double vecX = Math.cos(theta);
                double vecZ = Math.sin(theta);
                double vec = -1.75D;
                double math = 1.35;
                for (int i1 = 0; i1 < 5; i1++) {
                    float angle = (0.01745329251F * this.yBodyRot) + i1;
                    double extraX = 0.2F * Mth.sin((float) (Math.PI + angle));
                    double extraY = 2.75F;
                    double extraZ = 0.2F * Mth.cos(angle);
                    this.level().addParticle(ParticleTypes.SMOKE, getX() + vec * vecX + extraX + f * math, this.getY() + extraY, getZ() + vec * vecZ + extraZ + f1 * math, 0, -0.07, 0);
                    this.level().addParticle(ParticleTypes.SMOKE, getX() + vec * vecX + extraX + f * -math, this.getY() + extraY, getZ() + vec * vecZ + extraZ + f1 * -math, 0, -0.07, 0);
                }
            }
            if (this.getAnimation() == STUN_ANIAMATION)
                for (int i = 0; i < 2; ++i) {
                    this.level().addParticle(ParticleTypes.LARGE_SMOKE, this.getRandomX(1.5D), this.getRandomY(), this.getRandomZ(1.5D), 0.0D, 0.0D, 0.0D);
                }
        }
    }

}

public void onUpdate() {
	super.onUpdate();
	/*
	//TODO Insta hatch
	if (!getEntityWorld().isRemote) {
		this.setHasHatched(true);
		this.setIsTransforming(true);
		this.setTransformCount(60);
		this.setEatingCooldown(0);
		this.setAmountEaten(MAX_FOOD_NEEDED);
	}
	 */	

	//Wild Eggs
	if (!getEntityWorld().isRemote && getIsWild()) {
		this.setHasHatched(true);
		this.setEatingCooldown(0);
		this.setAmountEaten(MAX_FOOD_NEEDED);
	}

	// STAGE 1
	if (!getHasHatched()) {
		if (!getEntityWorld().isRemote) {
			if (ticksExisted %200 == 0) { // 200 = 10 seconds (no need to count this every second)
				if (getEntityWorld().getBlockState(getPosition().down()).getBlock() instanceof BlockOctine)
					setHatchTick(getHatchTick() + 1); // increment whilst on an octine block.
			}
			if (getHatchTick() >= 60) { // how many increments before hatching 60 = 10 minutes
				getEntityWorld().setEntityState(this, EVENT_HATCH_PARTICLES);
				setIsHungry(true);
				setHasHatched(true);
				getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_HATCH, SoundCategory.BLOCKS, 1F, 1F);
			}
		}

		if (getEntityWorld().isRemote) {
			if (getHatchTick() >= 1) { // animation
				prevHatchAnimation = hatchAnimation;
				hatchAnimation++;
			}
			if(getElectricBoogaloo())
				spawnLightningArcs();
		}
	}

	// STAGE 2
	if (getHasHatched()) {
		prevFeederRotation = feederRotation;
		prevHeadPitch = headPitch;
		prevTransformTick = getTransformCount();

		if (getEntityWorld().isRemote) {
			if(!getIsTransforming())
				checkFeeder();
			else {
				if(getOwner() != null)
					lookAtFeeder(getOwner(), 30F);
				}

			if (getRising() && getRiseCount() >= MAX_RISE) {
				if (!getIsHungry())
					if (headPitch < 40)
						headPitch += 8;
				if (getIsHungry())
					if (headPitch > 0)
						headPitch -= 8;
			}

			if (!getRising() && getRiseCount() < MAX_RISE)
				headPitch = getRiseCount();

			if (getAmountEaten() >= MAX_FOOD_NEEDED && !getIsChewing())
				; // TODO maybe else something to show this is ready to transform/transforming

			if (getElectricBoogaloo())
				spawnLightningArcs();

			if (getIsChewing())
				if (getTransformCount() < 60)
					spawnEatingParticles();

			if (!getIsHungry() && getRiseCount() >= MAX_RISE && !getIsChewing()) {
				if(!flapArms && flapArmsCount <= 0) {
					if(rand.nextInt(200) == 0) {
						flapArms = true;
						flapArmsCount = 30;
					}
				}
				if(blinkCount <= 0)
					if(rand.nextInt(200) == 0)
						blinkCount =  rand.nextBoolean() ? 10 : 5;
			}

			if (flapArmsCount >= 0)
				flapArmsCount--;

			if(flapArms && flapArmsCount <= 0)
				flapArms = false;

			if (blinkCount >= 0)
				blinkCount--;

		}

		prevRise = getRiseCount();
		if (!getRising() && getRiseCount() > MIN_RISE) {
			setRiseCount(getRiseCount() - 4);
		} else if (getRising() && getRiseCount() < MAX_RISE) {
			setRiseCount(getRiseCount() + 4);
		}

		if (!getEntityWorld().isRemote) {
			checkArea();

			if (!getIsHungry()) {
				setEatingCooldown(getEatingCooldown() - 1);
				if (getEatingCooldown() <= MAX_EATING_COOLDOWN && getEatingCooldown() > MAX_EATING_COOLDOWN - 60 && !getIsChewing())
					setIsChewing(true);
				if (getEatingCooldown() < MAX_EATING_COOLDOWN - 60 && getIsChewing())
					setIsChewing(false);
				if (getEatingCooldown() <= MIN_EATING_COOLDOWN && getAmountEaten() < MAX_FOOD_NEEDED) {
					setIsHungry(true);
					setFoodCraved(chooseNewFoodFromLootTable());
				}
			}

			if (getIsTransforming()) {
				if (getTransformCount() == 1)
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_HATCHLING_TRANSFORM, SoundCategory.NEUTRAL, 1F, 1F);
				if (getTransformCount() <= 60) {
					setTransformCount(getTransformCount() + 1);
					getEntityWorld().setEntityState(this, EVENT_FLOAT_UP_PARTICLES);
					}
				if(getOwner() != null)
					lookAtFeeder(getOwner(), 30F);
			}

			if (!isDead && getRiseCount() >= MAX_RISE) {
				if(getIsHungry() && ticksExisted %20 == 0) {
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_HATCHLING_HUNGRY_LONG, SoundCategory.NEUTRAL, 1F, 1F + rand.nextFloat() * 0.125F - rand.nextFloat() * 0.125F);
				}
				if (getAmountEaten() >= MAX_FOOD_NEEDED && getEatingCooldown() <= 0) {
					if (!getIsTransforming())
						setIsTransforming(true);
					if (!isDead && getTransformCount() >= 60) {
						Entity spawn = getEntitySpawned();
						if (spawn != null) {
							if (!spawn.isDead) { // just in case
								getEntityWorld().setEntityState(this, EVENT_NEW_SPAWN);
								getEntityWorld().playSound(null, getPosition(), SoundRegistry.CHIROMAW_MATRIARCH_BARB_FIRE, SoundCategory.NEUTRAL, 1F, 1F + (getEntityWorld().rand.nextFloat() - getEntityWorld().rand.nextFloat()) * 0.8F);
								getEntityWorld().spawnEntity(spawn);
							}
							setDead();
						}
					}
				}
			}
		}
	}

	this.rotationYaw = this.facing.getHorizontalAngle();
}

public void tick() {
    super.tick();
    this.prevBipedProgress = bipedProgress;
    this.prevTackleProgress = tackleProgress;
    this.prevSpikeShakeProgress = spikeShakeProgress;
    this.prevTurnAngle = getTurnAngle();

    if (this.isBipedal()) {
        if (bipedProgress < 5.0F)
            bipedProgress++;
    } else {
        if (bipedProgress > 0F)
            bipedProgress--;
    }

    if (this.isTackling()) {
        if (tackleProgress < 5.0F)
            tackleProgress++;
    } else {
        if (tackleProgress > 0F)
            tackleProgress--;
    }

    if (this.isSpikeShaking()) {
        if (spikeShakeProgress < 5.0F)
            spikeShakeProgress++;

        if (currentSpeedMode != 2) {
            currentSpeedMode = 2;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.1F);
        }
    } else {
        if (spikeShakeProgress > 0F)
            spikeShakeProgress--;

        if (isBipedal()) {
            if (currentSpeedMode != 0) {
                currentSpeedMode = 0;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35F);
            }
        } else {
            if (currentSpeedMode != 1) {
                currentSpeedMode = 1;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
        }
    }

    if (this.hasSpikes()) {
        if (!hasSpikedArmor) {
            hasSpikedArmor = true;
            this.getAttribute(Attributes.ARMOR).setBaseValue(12F);
        }
    } else {
        if (hasSpikedArmor) {
            hasSpikedArmor = false;
            this.getAttribute(Attributes.ARMOR).setBaseValue(0F);
        }
    }

    if (!this.level().isClientSide) {
        if (this.tickCount % 200 == 0) {
            if (isInWaterRainOrBubble() && !this.hasSpikes()) {
                this.setSpiked(true);
            }
            if (this.isHotBiome() && !isInWaterRainOrBubble()) {
                this.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 400));
                if (random.nextInt(2) == 0 && !this.isInWaterRainOrBubble()) {
                    this.setSpiked(false);
                }
            }
        }
        float threshold = 1F;
        boolean flag = false;
        if (isBipedal() && this.yRotO - this.getYRot() > threshold) {
            this.setTurnAngle(this.getTurnAngle() + 5);
            flag = true;
        }
        if (isBipedal() && this.yRotO - this.getYRot() < -threshold) {
            this.setTurnAngle(this.getTurnAngle() - 5);
            flag = true;
        }
        if (!flag) {
            if (this.getTurnAngle() > 0) {
                this.setTurnAngle(Math.max(this.getTurnAngle() - 10, 0));
            }
            if (this.getTurnAngle() < 0) {
                this.setTurnAngle(Math.min(this.getTurnAngle() + 10, 0));
            }
        }
        this.setTurnAngle(Mth.clamp(this.getTurnAngle(), -60, 60));
        if (standingTime > 0) {
            standingTime--;
        }
        if (standingTime < 0) {
            standingTime++;
        }

        if (standingTime <= 0 && this.isBipedal()) {
            standingTime = -200 - random.nextInt(400);
            this.setBipedal(false);
        }
        if (standingTime == 0 && !this.isBipedal() && this.getDeltaMovement().lengthSqr() >= 0.03D) {
            standingTime = 200 + random.nextInt(600);
            this.setBipedal(true);
        }
        if (shakeTime > 0) {
            if (this.shakeTime % 5 == 0) {
                int spikeCount = 2 + random.nextInt(4);
                for (int i = 0; i < spikeCount; i++) {
                    float f = ((i + 1) / (float) spikeCount) * 360F;
                    EntityIceShard shard = new EntityIceShard(level(), this);
                    shard.shootFromRotation(this, this.getXRot() - random.nextInt(40), f, 0.0F, 0.15F + random.nextFloat() * 0.2F, 1.0F);
                    level().addFreshEntity(shard);
                }
            }
            shakeTime--;
        }
        if (shakeTime == 0 && this.isSpikeShaking()) {
            this.setSpikeShaking(false);
            if (random.nextInt(2) == 0) {
                this.setSpiked(false);
            }
        }
        if (this.getTarget() != null && isValidLeader(this.getTarget())) {
            this.setTarget(null);
        }
        //Makes entire pack attack target
        if (this.getTarget() != null && !isValidLeader(this.getTarget()) && this.getTarget().isAlive() && (this.getLastHurtByMob() == null || !this.getLastHurtByMob().isAlive())) {
            this.setLastHurtByMob(this.getTarget());
        }
        LivingEntity playerTarget = null;
        if (leader instanceof Player) {
            playerTarget = leader.getLastHurtMob();
            if (playerTarget == null || !playerTarget.isAlive() || playerTarget instanceof EntityFroststalker) {
                playerTarget = leader.getLastHurtByMob();
            }
        }
        if (playerTarget != null && playerTarget.isAlive() && !(playerTarget instanceof EntityFroststalker)) {
            this.setTarget(playerTarget);
        }
        boolean attackAnim = this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 5 ||
                this.getAnimation() == ANIMATION_SHOVE && this.getAnimationTick() == 8 ||
                this.getAnimation() == ANIMATION_SLASH_L && this.getAnimationTick() == 7 ||
                this.getAnimation() == ANIMATION_SLASH_R && this.getAnimationTick() == 7;
        if (this.getTarget() != null && attackAnim) {
            getTarget().knockback(0.2F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
        }
    }
    if (fleeFireFlag > 0) {
        fleeFireFlag--;
    }
    if(!this.level().isClientSide){
        if(resetLeaderCooldown > 0){
            resetLeaderCooldown--;
        }else{
            resetLeaderCooldown = 200 + this.getRandom().nextInt(200);
            this.lookForPlayerLeader();
        }
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

public void tick() {
    super.tick();
    boolean moving = this.getDeltaMovement().lengthSqr() > 0.03D;
    int pouchTick = this.entityData.get(POUCH_TICK);
    this.prevTotalMovingProgress = totalMovingProgress;
    this.prevPouchProgress = pouchProgress;
    this.prevSitProgress = sitProgress;
    this.prevStandProgress = standProgress;

    if (this.isSitting()) {
        if (sitProgress < 5F) {
            sitProgress++;
        }
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (eatCooldown > 0) {
        eatCooldown--;
    }

    if (this.isStanding()) {
        if (standProgress < 5F)
            standProgress++;
    } else {
        if (standProgress > 0F)
            standProgress--;
    }

    if (moving) {
        if (totalMovingProgress < 5F) {
            totalMovingProgress++;
        }
    } else {
        if (totalMovingProgress > 0F)
            totalMovingProgress--;
    }

    if (pouchTick != 0 && pouchProgress < 5) {
        pouchProgress += 1;
    }
    if (pouchTick == 0 && pouchProgress > 0) {
        pouchProgress -= 1;
    }
    if (pouchTick > 0) {
        this.entityData.set(POUCH_TICK, pouchTick - 1);
    }
    if (isStanding() && ++standingTime > maxStandTime) {
        this.setStanding(false);
        standingTime = 0;
        maxStandTime = 75 + random.nextInt(50);
    }
    if (isSitting() && !forcedSit() && ++sittingTime > maxSitTime) {
        this.setOrderedToSit(false);
        sittingTime = 0;
        maxSitTime = 75 + random.nextInt(50);
    }
    if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && this.getCommand() != 1 && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
        maxSitTime = 500 + random.nextInt(350);
        this.setOrderedToSit(true);
    }
    if (!forcedSit() && this.isSitting() && (this.getTarget() != null || this.isStanding())) {
        this.setOrderedToSit(false);
    }
    if (this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
        maxStandTime = 75 + random.nextInt(50);
        this.setStanding(true);
    }
    if (this.forcedSit() && !this.isVehicle() && this.isTame()) {
        this.setOrderedToSit(true);
    }
    if (!this.level().isClientSide) {
        if (tickCount == 1) {
            updateClientInventory();
        }

        if (!moving && this.getAnimation() == NO_ANIMATION && !this.isSitting() && !this.isStanding()) {
            if ((getRandom().nextInt(180) == 0 || this.getHealth() < this.getMaxHealth() && getRandom().nextInt(40) == 0) && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK)) {
                this.setAnimation(ANIMATION_EAT_GRASS);
            }
        }
        if (this.getAnimation() == ANIMATION_EAT_GRASS && this.getAnimationTick() == 20 && this.getHealth() < this.getMaxHealth() && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK)) {
            this.heal(6);
            this.level().levelEvent(2001, blockPosition().below(), Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
            this.level().setBlock(blockPosition().below(), Blocks.DIRT.defaultBlockState(), 2);
        }
        if (this.getHealth() < this.getMaxHealth() && this.isTame() && eatCooldown == 0) {
            eatCooldown = 20 + random.nextInt(40);
            if (!this.kangarooInventory.isEmpty()) {
                ItemStack foodStack = ItemStack.EMPTY;
                for (int i = 0; i < this.kangarooInventory.getContainerSize(); i++) {
                    ItemStack stack = this.kangarooInventory.getItem(i);
                    if (stack.getItem().isEdible() && stack.getItem().getFoodProperties() != null && !stack.getItem().getFoodProperties().isMeat()) {
                        foodStack = stack;
                    }
                }
                if (!foodStack.isEmpty() && foodStack.getItem().getFoodProperties() != null) {
                    AlexsMobs.sendMSGToAll(new MessageKangarooEat(this.getId(), foodStack));
                    this.heal(foodStack.getItem().getFoodProperties().getNutrition() * 2);
                    foodStack.shrink(1);
                    this.gameEvent(GameEvent.EAT);
                    this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
                }
            }
        }
    }
    if (this.jumpTicks < this.jumpDuration) {
        ++this.jumpTicks;
    } else if (this.jumpDuration != 0) {
        this.jumpTicks = 0;
        this.jumpDuration = 0;
        this.setJumping(false);
    }
    LivingEntity attackTarget = this.getTarget();
    if (attackTarget != null && this.hasLineOfSight(attackTarget)) {
        if (distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 1) {
            if (this.getAnimation() == ANIMATION_KICK && this.getAnimationTick() == 8) {
                attackTarget.knockback(1.3F, Mth.sin(this.getYRot() * Mth.DEG_TO_RAD), -Mth.cos(this.getYRot() * Mth.DEG_TO_RAD));
                this.doHurtTarget(this.getTarget());
            }
            if ((this.getAnimation() == ANIMATION_PUNCH_L) && this.getAnimationTick() == 6) {
                float rot = getYRot() + 90;
                attackTarget.knockback(0.85F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                this.doHurtTarget(this.getTarget());
            }
            if ((this.getAnimation() == ANIMATION_PUNCH_R) && this.getAnimationTick() == 6) {
                float rot = getYRot() - 90;
                attackTarget.knockback(0.85F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                this.doHurtTarget(this.getTarget());
            }
        }
        this.lookAt(attackTarget, 360, 360);
    }
    if (this.isBaby() && attackTarget != null) {
        this.setTarget(null);
    }
    if (this.isVehicle()) {
        this.entityData.set(POUCH_TICK, 10);
        this.setStanding(true);
        maxStandTime = 25;
    }

    if (this.isPassenger()) {
        if (this.isBaby() && this.getVehicle() instanceof EntityKangaroo) {
            EntityKangaroo mount = (EntityKangaroo) this.getVehicle();
            this.setYRot(mount.yBodyRot);
            this.yHeadRot = mount.yBodyRot;
            this.yBodyRot = mount.yBodyRot;
        }
        if (this.getVehicle() instanceof EntityKangaroo && !this.isBaby()) {
            this.removeVehicle();
        }
    }
    if (clientArmorCooldown > 0) {
        clientArmorCooldown--;
    }
    if (tickCount > 5 && !this.level().isClientSide && clientArmorCooldown == 0 && this.isTame()) {
        this.updateClientInventory();
        clientArmorCooldown = 20;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

	public void onUpdate() {
		super.onUpdate();

		if(!world.isRemote) {
			if(getItemStackDamage() >= 64) {  // needs to match or exceed Item maxDamage
				getEntityWorld().setEntityState(this, EVENT_DEAD);
				setDead();
			}
		}

		 if (this.timeInGround > 4 && getType() == 2 && getAnimated()) {
	         this.returnHome = true;
	      }

	      Entity entityOwner = getThrower();
	      if ((this.returnHome || this.noClip) && entityOwner != null && getType() == 2) {
	        	this.noClip = true;
	        	inGround = false;
	     		double targetX = entityOwner.posX - posX;
	    		double targetY = entityOwner.posY + entityOwner.getEyeHeight() - posY + height * 0.5D;
	    		double targetZ = entityOwner.posZ - posZ;
	    		moveToTarget(targetX, targetY, targetZ, 0.5F);

                double wiggleSpeed = Math.sin((double) (ticksExisted + getEntityId()) * 0.5D) * 0.05D;
                double wiggleOffsetX = Math.cos((double) (rotationYaw * 0.01F));
                double wiggleOffsetZ = Math.sin((double) (rotationYaw * 0.01F));
                motionX += wiggleSpeed * wiggleOffsetX;
                motionZ += wiggleSpeed * wiggleOffsetZ;

	            if (this.world.isRemote) {
	               this.lastTickPosY = this.posY;
	            }

	            if (this.returningTicks == 0) {
	            	playSound(SoundRegistry.SPEAR_RETURN_1, 1F, 1F);
	            }
	            ++this.returningTicks;
	      }

		if (prevRotationPitch == 0.0F && prevRotationYaw == 0.0F) {
			float f = MathHelper.sqrt(motionX * motionX + motionZ * motionZ);
			rotationYaw = (float) (MathHelper.atan2(motionX, motionZ) * (180D / Math.PI));
			rotationPitch = (float) (MathHelper.atan2(motionY, (double) f) * (180D / Math.PI));
			prevRotationYaw = rotationYaw;
			prevRotationPitch = rotationPitch;
		}

		BlockPos blockpos = new BlockPos(xTile, yTile, zTile);
		IBlockState iblockstate = world.getBlockState(blockpos);
		Block block = iblockstate.getBlock();

		if (iblockstate.getMaterial() != Material.AIR && noClip == false) {
			AxisAlignedBB axisalignedbb = iblockstate.getCollisionBoundingBox(world, blockpos);
			if (axisalignedbb != Block.NULL_AABB&& axisalignedbb.offset(blockpos).contains(new Vec3d(posX, posY, posZ)))
				inGround = true;
		}

		if (arrowShake > 0)
			--arrowShake;

		if (inGround) {
			int j = block.getMetaFromState(iblockstate);

			if ((block != inTile || j != inData) && !world.collidesWithAnyBlock(getEntityBoundingBox().grow(0.05D))) {
				inGround = false;
				motionX *= (double) (rand.nextFloat() * 0.2F);
				motionY *= (double) (rand.nextFloat() * 0.2F);
				motionZ *= (double) (rand.nextFloat() * 0.2F);
				ticksInGround = 0;
				ticksInAir = 0;
			} else {
				++ticksInGround;
				if (ticksInGround >= 6000)
					setDead();
			}
			++timeInGround;
		} else {
			timeInGround = 0;
			++ticksInAir;
			Vec3d vec3d1 = new Vec3d(posX, posY, posZ);
			Vec3d vec3d = new Vec3d(posX + motionX, posY + motionY, posZ + motionZ);
			RayTraceResult raytraceresult = world.rayTraceBlocks(vec3d1, vec3d, false, true, false);
			vec3d1 = new Vec3d(posX, posY, posZ);
			vec3d = new Vec3d(posX + motionX, posY + motionY, posZ + motionZ);

			if (raytraceresult != null)
				vec3d = new Vec3d(raytraceresult.hitVec.x, raytraceresult.hitVec.y, raytraceresult.hitVec.z);

			Entity entity = findEntityOnPath(vec3d1, vec3d);
			if (noClip)
				raytraceresult = null;

			if (entity != null)
				raytraceresult = new RayTraceResult(entity);

			if (raytraceresult != null && raytraceresult.entityHit instanceof EntityPlayer) {
				EntityPlayer entityplayer = (EntityPlayer) raytraceresult.entityHit;

				if (shootingEntity instanceof EntityPlayer && !((EntityPlayer) shootingEntity).canAttackPlayer(entityplayer))
					raytraceresult = null;
			}

			if (raytraceresult != null)
				onHit(raytraceresult);

			if (raytraceresult != null && !net.minecraftforge.event.ForgeEventFactory.onProjectileImpact(this, raytraceresult))
				onHit(raytraceresult);

			if (getIsCritical()) {
				for (int k = 0; k < 4; ++k)
					world.spawnParticle(EnumParticleTypes.CRIT, posX + motionX * (double) k / 4.0D, posY + motionY * (double) k / 4.0D, posZ + motionZ * (double) k / 4.0D, -motionX, -motionY + 0.2D, -motionZ);
			}

			posX += motionX;
			posY += motionY;
			posZ += motionZ;

			float f4 = MathHelper.sqrt(motionX * motionX + motionZ * motionZ);
			rotationYaw = (float) (MathHelper.atan2(motionX, motionZ) * (180D / Math.PI));
			if (shootingEntity != null && getDistance(shootingEntity) > 4)
				for (rotationPitch = (float) (MathHelper.atan2(motionY, (double) f4) * (180D / Math.PI)); rotationPitch - prevRotationPitch < -180.0F; prevRotationPitch -= 360.0F) {
					;
				}
			else
				for (rotationPitch = (float) (MathHelper.atan2(motionY, (double) -f4) * (180D / Math.PI)); rotationPitch - prevRotationPitch < -180.0F; prevRotationPitch -= 360.0F) {
					;
				}

			while (rotationPitch - prevRotationPitch >= 180.0F)
				prevRotationPitch += 360.0F;

			while (rotationYaw - prevRotationYaw < -180.0F)
				prevRotationYaw -= 360.0F;

			while (rotationYaw - prevRotationYaw >= 180.0F)
				prevRotationYaw += 360.0F;

			rotationPitch = prevRotationPitch + (rotationPitch - prevRotationPitch) * 0.2F;
			rotationYaw = prevRotationYaw + (rotationYaw - prevRotationYaw) * 0.2F;
			float drag = 0.99F;

			if (isInWater()) {
				for (int i = 0; i < 4; ++i)
					world.spawnParticle(EnumParticleTypes.WATER_BUBBLE, posX - motionX * 0.25D, posY - motionY * 0.25D, posZ - motionZ * 0.25D, motionX, motionY, motionZ, new int[0]);
				drag = getWaterDrag();
			}

			if (isWet())
				extinguish();

			if (!hasNoGravity())
				motionY -= 0.05000000074505806D;

			motionX *= (double) drag;
			motionY *= (double) drag;
			motionZ *= (double) drag;

			setPosition(posX, posY, posZ);

			 if(!noClip)
				 doBlockCollisions();
		}
	}

    public void aiStep() {
        super.aiStep();
        if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
            this.setTarget(null);
        }
        if (this.isInWater() && this.jumping && this.getControllingPassenger() == null) {
            this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y + 0.1D, this.getDeltaMovement().z);
        }
        if (this.isBaby() && this.getTarget() != null) {
            this.setTarget(null);
        }
        if (this.isInLove()) {
            this.setFlying(false);
        }
        if (this.isOrderedToSit() && this.getTarget() != null) {
            this.setTarget(null);
        }
        boolean flapping = this.isFlapping();
        boolean flying = this.isFlying() && this.isOverAir() || (this.isOverAir() && !onLeaves());
        boolean diving = flying && this.getDeltaMovement().y <= -0.1F || this.isFallen;
        boolean sitting = isOrderedToSit() && !isFlying();
        boolean notGrounded = flying || this.getAnimation() == ANIMATION_WING_BLAST;
        if (!level.isClientSide) {
            if (this.isOrderedToSit() && (this.getCommand() != 1 || this.getControllingPassenger() != null)) {
                this.setOrderedToSit(false);
            }
            if (!this.isOrderedToSit() && this.getCommand() == 1 && this.getControllingPassenger() == null) {
                this.setOrderedToSit(true);
            }
            if (this.isOrderedToSit()) {
                this.getNavigation().stop();
                //TODO
                //this.getMoveHelper().action = MovementController.Action.WAIT;
            }
            if (flying) {
                ticksFlying++;
            } else {
                ticksFlying = 0;
            }
        }
        if (isFlying() && this.onGround) {
            this.setFlying(false);
        }
        if (sitting && sitProgress < 20.0F) {
            sitProgress += 0.5F;
        } else if (!sitting && sitProgress > 0.0F) {
            sitProgress -= 0.5F;
        }
        if (flightCooldown > 0) {
            flightCooldown--;
        }
        if (!level.isClientSide) {
            if (this.flightBehavior == FlightBehavior.CIRCLE) {
                ticksCircling++;
            } else {
                ticksCircling = 0;
            }
        }
        if (this.getUntamedRider() != null && !this.isTame()) {
            ridingTime++;
        }
        if (this.getUntamedRider() == null) {
            ridingTime = 0;
        }
        if (!this.isTame() && ridingTime > IafConfig.amphithereTameTime && this.getUntamedRider() != null && this.getUntamedRider() instanceof Player) {
            this.level.broadcastEntityEvent(this, (byte) 45);
            this.tame((Player) this.getUntamedRider());
            if (this.getTarget() == this.getUntamedRider())
                this.setTarget(null);
        }
        if (isStill()) {
            this.ticksStill++;
        } else {
            this.ticksStill = 0;
        }
        if (!this.isFlying() && !this.isBaby() && ((this.isOnGround() && this.random.nextInt(200) == 0 && flightCooldown == 0 && this.getPassengers().isEmpty() && !this.isNoAi() && canMove()) || this.getY() < -1)) {
            this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y + 0.5D, this.getDeltaMovement().z);
            this.setFlying(true);
        }
//        if (this.getControllingPassenger() != null && this.isFlying() && !this.onGround) {
//
//            if (this.getControllingPassenger().getXRot() > 25 && this.getDeltaMovement().y > -1.0F) {
//                this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y - 0.1D, this.getDeltaMovement().z);
//
//            }
//            if (this.getControllingPassenger().getXRot() < -25 && this.getDeltaMovement().y < 1.0F) {
//                this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y + 0.1D, this.getDeltaMovement().z);
//
//            }
//        }
        if (notGrounded && groundProgress > 0.0F) {
            groundProgress -= 2F;
        } else if (!notGrounded && groundProgress < 20.0F) {
            groundProgress += 2F;
        }
        if (diving && diveProgress < 20.0F) {
            diveProgress += 1F;
        } else if (!diving && diveProgress > 0.0F) {
            diveProgress -= 1F;
        }
        // TODO: ??
        if (this.isFlying() && this.getControllingPassenger() == null) {
            this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y + 0.08D, this.getDeltaMovement().z);
        }
        if (this.isFallen && this.flightBehavior != FlightBehavior.NONE) {
            this.flightBehavior = FlightBehavior.NONE;
        }
        if (this.flightBehavior == FlightBehavior.NONE && this.getControllingPassenger() == null && this.isFlying()) {
            this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y - 0.3D, this.getDeltaMovement().z);
        }
        if (this.isFlying() && !this.isOnGround() && this.isFallen && this.getControllingPassenger() == null) {
            this.setDeltaMovement(this.getDeltaMovement().x, this.getDeltaMovement().y - 0.2D, this.getDeltaMovement().z);
            this.setXRot(Math.max(this.getXRot() + 5, 75));
        }
        if (this.isFallen && this.onGround) {
            this.setFlying(false);
            if (this.isTame()) {
                flightCooldown = 50;
            } else {
                flightCooldown = 12000;
            }
            this.isFallen = false;
        }
        if (flying && this.isOverAir()) {
            if (this.getRidingPlayer() == null && this.navigatorType != 1) {
                switchNavigator(1);
            }
            if (this.getRidingPlayer() != null && this.navigatorType != 2) {
                switchNavigator(2);
            }
        }
        if (!flying && this.navigatorType != 0) {
            switchNavigator(0);
        }
        if ((this.hasHomePosition || this.getCommand() == 2) && this.flightBehavior == FlightBehavior.WANDER) {
            this.flightBehavior = FlightBehavior.CIRCLE;
        }
        if (flapping && flapProgress < 10.0F) {
            flapProgress += 1F;
        } else if (!flapping && flapProgress > 0.0F) {
            flapProgress -= 1F;
        }
        if (flapTicks > 0) {
            flapTicks--;
        }
        if (level.isClientSide) {
            if (!onGround) {
                if (this.isVehicle())
                    roll_buffer.calculateChainFlapBufferHead(40, 1, 2F, 0.5F, this);
                else {
                    yBodyRot = getYRot();
                    roll_buffer.calculateChainFlapBuffer(70, 1, 2F, 0.5F, this);

                }
                pitch_buffer.calculateChainPitchBuffer(90, 10, 10F, 0.5F, this);
            }
            tail_buffer.calculateChainSwingBuffer(70, 20, 5F, this);
        }
        if (changedFlightBehavior) {
            changedFlightBehavior = false;
        }
        if (!flapping && (this.getDeltaMovement().y > 0.15F || this.getDeltaMovement().y > 0 && this.tickCount % 200 == 0) && this.isOverAir()) {
            flapWings();
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public static void LivingEffects(LivingEvent.LivingTickEvent event){
    LivingEntity livingEntity = event.getEntity();
    if (livingEntity != null){
        if (livingEntity.level instanceof ServerLevel serverLevel) {
            if (livingEntity.hasEffect(GoetyEffects.ILLAGUE.get())) {
                EffectsUtil.Illague(serverLevel, livingEntity);
            }
            if (livingEntity.hasEffect(GoetyEffects.SOUL_BURN.get())) {
                if (livingEntity.tickCount % 2 == 0) {
                    serverLevel.sendParticles(ModParticleTypes.BIG_SOUL_FIRE.get(), livingEntity.getRandomX(1.0D), livingEntity.getY(livingEntity.getRandom().nextDouble() * 0.5F), livingEntity.getRandomZ(1.0D), 1, 0, 0, 0, 0);
                }
            }
            if (livingEntity.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
                if (livingEntity.tickCount % 10 == 0) {
                    ColorUtil colorUtil = VOID_TOUCHED;
                    serverLevel.sendParticles(new FollowFireParticleOption(livingEntity.getId()), livingEntity.getX(), livingEntity.getY() + (livingEntity.getBbHeight() / 2.0F), livingEntity.getZ(), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);
                }
            }
            if (VampirismLoaded.VAMPIRISM.isLoaded()) {
                if (VampirismIntegration.hasSunscreen(livingEntity)) {
                    MiscCapHelper.setSunscreen(livingEntity, 20);
                }
            }
        }
        AttributeInstance armor = livingEntity.getAttribute(Attributes.ARMOR);
        if (armor != null){
            if (livingEntity.hasEffect(GoetyEffects.SOUL_ARMOR.get())){
                if (ItemHelper.noArmor(livingEntity)){
                    if (!armor.hasModifier(SOUL_ARMOR_MOD)){
                        armor.addPermanentModifier(SOUL_ARMOR_MOD);
                    }
                } else {
                    if (armor.hasModifier(SOUL_ARMOR_MOD)){
                        armor.removeModifier(SOUL_ARMOR_MOD);
                    }
                }
            } else {
                if (armor.hasModifier(SOUL_ARMOR_MOD)){
                    armor.removeModifier(SOUL_ARMOR_MOD);
                }
            }
        }
        if (livingEntity.getTags().contains(ConstantPaths.gassed())){
            if (livingEntity.tickCount % 20 == 0){
                livingEntity.getTags().remove(ConstantPaths.gassed());
            }
        }
        if (livingEntity.hasEffect(GoetyEffects.BURN_HEX.get())){
            if (livingEntity.hasEffect(MobEffects.FIRE_RESISTANCE)){
                livingEntity.removeEffectNoUpdate(MobEffects.FIRE_RESISTANCE);
            }
        }
        if (livingEntity.hasEffect(GoetyEffects.CLIMBING.get())){
            MobUtil.ClimbAnyWall(livingEntity);
        }
        if (livingEntity instanceof Bee bee){
            if (!bee.level.isClientSide) {
                if (bee.getTags().contains(ConstantPaths.conjuredBee())){
                    if ((bee.getTarget() == null && bee.getPersistentAngerTarget() == null) || bee.hasStung()){
                        if (bee.tickCount % MathHelper.secondsToTicks(10) == 0){
                            bee.spawnAnim();
                            bee.discard();
                        }
                    }
                }
            }
        }
        if (livingEntity instanceof Bat bat){
            if (!bat.level.isClientSide){
                if (bat.getTags().contains(ConstantPaths.conjuredBat())){
                    if (bat.tickCount % MathHelper.secondsToTicks(20) == 0){
                        bat.spawnAnim();
                        bat.discard();
                    }
                }
            }
        }
        if (livingEntity.hasEffect(GoetyEffects.FREEZING.get())){
            if (!livingEntity.level.isClientSide){
                MobEffectInstance instance = livingEntity.getEffect(GoetyEffects.FREEZING.get());
                if (instance != null) {
                    livingEntity.setIsInPowderSnow(true);
                    if (livingEntity.canFreeze()) {
                        int h = instance.getAmplifier() + 1;
                        MiscCapHelper.setFreezing(livingEntity, h);
                        if (livingEntity.level instanceof ServerLevel serverLevel) {
                            float chance = 0.005F * (h * h);
                            if (serverLevel.getRandom().nextFloat() <= chance) {
                                ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.SNOWFLAKE, livingEntity);
                            }
                        }
                        int i = livingEntity.getTicksFrozen();
                        int j = h * 4;
                        livingEntity.setTicksFrozen(Math.min(livingEntity.getTicksRequiredToFreeze() + 5, i + j));
                    }
                }
            }
        } else {
            if (!livingEntity.level.isClientSide){
                if (MiscCapHelper.isFreezing(livingEntity)){
                    MiscCapHelper.setFreezing(livingEntity, 0);
                }
            }
        }
        if (livingEntity instanceof Player && livingEntity.hasEffect(GoetyEffects.SENSE_LOSS.get())){
            MobEffectInstance mobEffectInstance = livingEntity.getEffect(GoetyEffects.SENSE_LOSS.get());
            if (mobEffectInstance != null) {
                if (livingEntity.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, mobEffectInstance.getDuration(), mobEffectInstance.getAmplifier(), mobEffectInstance.isAmbient(), mobEffectInstance.isVisible()))){
                    livingEntity.removeEffect(GoetyEffects.SENSE_LOSS.get());
                }
            }
        }
        if (livingEntity.hasEffect(GoetyEffects.EXPLOSIVE.get())) {
            MobEffectInstance mobEffectInstance = livingEntity.getEffect(GoetyEffects.EXPLOSIVE.get());
            if (mobEffectInstance != null){
                int a = mobEffectInstance.getAmplifier() + 1;
                if (MobUtil.isPushed(livingEntity)) {
                    int max = Math.max(1, 100 - (a * 10));
                    if (livingEntity.getRandom().nextInt(max) == 0) {
                        if (!livingEntity.level.isClientSide) {
                            livingEntity.level.explode(livingEntity, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 3.0F + (a / 2.0F), Level.ExplosionInteraction.BLOCK);
                            livingEntity.removeEffect(GoetyEffects.EXPLOSIVE.get());
                        }
                    }
                }
            }
        }
        if (livingEntity.hasEffect(GoetyEffects.SNOW_SKIN.get())){
            MobEffectInstance mobEffectInstance = livingEntity.getEffect(GoetyEffects.SNOW_SKIN.get());
            if(mobEffectInstance != null){
                if (!livingEntity.level.isClientSide){
                    int i = Mth.floor(livingEntity.getX());
                    int j = Mth.floor(livingEntity.getY());
                    int k = Mth.floor(livingEntity.getZ());
                    BlockPos blockpos = new BlockPos(i, j, k);
                    Holder<Biome> biome = livingEntity.level.getBiome(blockpos);
                    if (biome.is(BiomeTags.SNOW_GOLEM_MELTS)) {
                        livingEntity.hurt(livingEntity.damageSources().onFire(), 1.0F);
                    }

                    livingEntity.setIsInPowderSnow(false);
                    livingEntity.setTicksFrozen(0);

                    BlockState blockstate = Blocks.SNOW.defaultBlockState();

                    for(int l = 0; l < 4; ++l) {
                        i = Mth.floor(livingEntity.getX() + (double)((float)(l % 2 * 2 - 1) * 0.25F));
                        j = Mth.floor(livingEntity.getY());
                        k = Mth.floor(livingEntity.getZ() + (double)((float)(l / 2 % 2 * 2 - 1) * 0.25F));
                        BlockPos blockpos1 = new BlockPos(i, j, k);
                        if (livingEntity.level.isEmptyBlock(blockpos1) && blockstate.canSurvive(livingEntity.level, blockpos1)) {
                            livingEntity.level.setBlockAndUpdate(blockpos1, blockstate);
                            livingEntity.level.gameEvent(GameEvent.BLOCK_PLACE, blockpos1, GameEvent.Context.of(livingEntity, blockstate));
                        }
                    }
                }
            }
        }
        /*if (livingEntity instanceof Mob mob) {
            if (mob.getTarget() != null) {
                if (mob.getTarget().hasEffect(GoetyEffects.ENCHANTED.get())) {
                    if (MiscCapHelper.getEnchanter(mob.getTarget()) instanceof LivingEntity enchanter && TargetingConditions.forCombat().test(mob, enchanter)) {
                        mob.setTarget(enchanter);
                    }
                }
            }
        }*/
    }
}

