protected void moveAlongTrack() {
    fallDistance = 0.0F;
    Vec3d vec3d = getPos();

    posY = (double)railTracks.getY();

    double slopeAdjustment = 0.0078125D;
    TourRailBlock.EnumRailDirection dir = TourRailBlock.getRailDirection(world, railTracks);

    EnumFacing facing = getFacingDir();
    //TODO: Working?
    switch (dir) {
        case ASCENDING_EAST:
            motionX -= slopeAdjustment;
            ++posY;
            break;
        case ASCENDING_WEST:
            motionX += slopeAdjustment;
            ++posY;
            break;
        case ASCENDING_NORTH:
            motionZ += slopeAdjustment;
            ++posY;
            break;
        case ASCENDING_SOUTH:
            motionZ -= slopeAdjustment;
            ++posY;
        default:
    }
    double d1 = (double)(dir.getBackwardsX(facing) - dir.getForwardX(facing));
    double d2 = (double)(dir.getBackwardsZ(facing) - dir.getForwardZ(facing));
    double d3 = Math.sqrt(d1 * d1 + d2 * d2);
    double d4 = motionX * d1 + motionZ * d2;
    if (d4 < 0.0D) {
        d1 = -d1;
        d2 = -d2;
    }

    double d5 = Math.sqrt(motionX * motionX + motionZ * motionZ);

    if (d5 > 2.0D) {
        d5 = 2.0D;
    }
    double d = 1;
    if(forward()) {
        if(!prevKeyDown && isInReverse) {
            d = -1;
        }
        isInReverse = false;
        prevKeyDown = true;
    } else if(backward()) {
        if(!prevKeyDown && !isInReverse) {
            d = -1;
        }
        isInReverse = true;
        prevKeyDown = true;
    } else {
        prevKeyDown = false;
    }
    if(!world.isRemote) {
        d5 *= d;
    }


    motionX = d5 * d1 / d3;
    motionZ = d5 * d2 / d3;




    Vec3d vec = getPositionVector();
    Vec3d dirVec = new Vec3d(-d1, 0, d2).add(vec);
    double target = MathUtils.cosineFromPoints(vec.addVector(0, 0, 1), dirVec, vec);

    if(dirVec.x < vec.x) {
        target = -target;
    }

    this.adjustedRotationYaw = target;

    if(isInReverse) {
        target += 180F;
    }

    double d22;
    do {
        d22 = Math.abs(rotationYawInterp.getCurrent() - target);
        double d23 = Math.abs(rotationYawInterp.getCurrent() - (target + 360f));
        double d24 = Math.abs(rotationYawInterp.getCurrent() - (target - 360f));

        if(d23 < d22) {
            target += 360f;
        } else if(d24 < d22) {
            target -= 360f;
        }
    } while(d22 > 180);

    target = Math.round(target * 100D) / 100D;




    rotationYawInterp.setSpeed(this.getSpeedType().modifier * 4f);

    if(!prevOnRails) {
        rotationYawInterp.reset(target);
    } else if(d != -1) {
        rotationYawInterp.setTarget(target);
    }

    setRotation((float) rotationYawInterp.getCurrent(), rotationPitch);

    double d18 = (double)railTracks.getX() + 0.5D + (double)dir.getForwardX(facing) * 0.5D;
    double d19 = (double)railTracks.getZ() + 0.5D + (double)dir.getForwardZ(facing) * 0.5D;
    double d20 = (double)railTracks.getX() + 0.5D + (double)dir.getBackwardsX(facing) * 0.5D;
    double d21 = (double)railTracks.getZ() + 0.5D + (double)dir.getBackwardsZ(facing) * 0.5D;
    d1 = d20 - d18;
    d2 = d21 - d19;
    double d10;

    if (d1 == 0.0D) {
        posX = (double)railTracks.getX() + 0.5D;
        d10 = posZ - (double)railTracks.getZ();
    } else if (d2 == 0.0D) {
        posZ = (double)railTracks.getZ() + 0.5D;
        d10 = posX - (double)railTracks.getX();
    } else {
        double d11 = posX - d18;
        double d12 = posZ - d19;
        d10 = (d11 * d1 + d12 * d2) * 2.0D;
    }

    posX = d18 + d1 * d10;
    posZ = d19 + d2 * d10;
    setPosition(posX, posY, posZ);
    moveMinecartOnRail();

    double drag = isBeingRidden() ? 0.9D : 0.75D;

    motionX *= drag;
    motionZ *= drag;

    Vec3d vec3d1 = getPos();

    if (vec3d1 != null && vec3d != null) {
        double d14 = (vec3d.y - vec3d1.y) * 0.05D;
        d5 = Math.sqrt(motionX * motionX + motionZ * motionZ);

        if (d5 > 0.0D) {
            motionX = motionX / d5 * (d5 + d14);
            motionZ = motionZ / d5 * (d5 + d14);
        }
    }

    int j = MathHelper.floor(posX);
    int i = MathHelper.floor(posZ);

    if (j != railTracks.getX() || i != railTracks.getZ()) {
        d5 = Math.sqrt(motionX * motionX + motionZ * motionZ);
        motionX = d5 * (double)(j - railTracks.getX());
        motionZ = d5 * (double)(i - railTracks.getZ());
    }
    double d15 = Math.sqrt(motionX * motionX + motionZ * motionZ);
    if(d15 == 0) {
        d15 = 1;
    }
    double d16 = 0.06D;
    motionX += motionX / d15 * d16;
    motionZ += motionZ / d15 * d16;
}

public void onEntityUpdate() {
	if(!this.world.isRemote) {
		//Spawn puller entities that were loaded from nbt
		Iterator<Entity> entityIt = this.loadedPullerEntities.iterator();
		while(entityIt.hasNext()) {
			Entity entity = entityIt.next();

			//Spawning can fail if a chunk isn't loaded yet so keep trying until it works
			if(this.world.spawnEntity(entity)) {
				entityIt.remove();
			}
		}

		//Remove dead pullers
		Iterator<DraetonPhysicsPart> partIt = this.physicsParts.iterator();
		while(partIt.hasNext()) {
			DraetonPhysicsPart part = partIt.next();

			if(part.type == DraetonPhysicsPart.Type.PULLER) {
				Entity entity = part.getEntity();
				if(entity == null || !entity.isEntityAlive()) {
					part.isActive = false;
					partIt.remove();

					TheBetweenlands.networkWrapper.sendToAllTracking(new MessageUpdateDraetonPhysicsPart(this, part, Action.REMOVE), this);
				}
			}
		}

		//Updates leakages
		List<DraetonLeakage> expiredLeakages = null;
		for(DraetonLeakage leakage : this.leakages) {
			if(leakage.age++ > 6000) {
				if(expiredLeakages == null) {
					expiredLeakages = new ArrayList<>();
				}
				expiredLeakages.add(leakage);
			}
		}
		if(expiredLeakages != null) {
			for(DraetonLeakage expired : expiredLeakages) {
				this.removeLeakage(expired);
			}
		}
	}

	for(DraetonPhysicsPart part : this.physicsParts) {
		part.prevX = part.x;
		part.prevY = part.y;
		part.prevZ = part.z;
	}

	this.prevPosX = this.posX;
	this.prevPosY = this.posY;
	this.prevPosZ = this.posZ;

	float drag = 0.98f;
	for(DraetonPhysicsPart part : this.physicsParts) {
		if(part.getEntity() != null) {
			drag = part.getEntity().getCarriageDrag(drag);
		}
	}

	if(this.onGround || this.inWater) {
		drag *= 0.8f;
	}

	this.motionY *= drag;
	this.motionX *= drag;
	this.motionZ *= drag;

	float speed = MathHelper.sqrt(this.motionX*this.motionX + this.motionY*this.motionY + this.motionZ*this.motionZ);

	this.handleWaterMovement();

	if(this.waterLevel - this.posY > 0.2D) {
		if(this.motionY < 0) {
			this.motionY *= 0.75F;
		}

		this.motionY += 0.01D;
	}

	if(!this.world.isRemote || this.canPassengerSteer()) {
		this.move(MoverType.SELF, this.motionX, this.motionY - 0.0000001f, this.motionZ);
		this.pushOutOfBlocks(this.posX, this.posY, this.posZ);
	}

	float newSpeed = MathHelper.sqrt(this.motionX*this.motionX + this.motionY*this.motionY + this.motionZ*this.motionZ);

	if(!this.world.isRemote) {
		if(this.crashCooldown > 0) {
			if(!this.collided || this.onGround) {
				this.crashCooldown--;
			}
		} else if(this.getControllingPassenger() != null && !this.dataManager.get(ANCHOR_FIXATED) && (this.collided || this.onGround) && speed > this.crashSpeedThreshold && speed - newSpeed > this.crashSpeedThreshold * 0.5f) {
			float leakageChance = Math.min((speed - this.crashSpeedThreshold) * 3.0f, 0.5f) + 0.25f;
			if(this.world.rand.nextFloat() < leakageChance) {
				this.motionX = this.motionY = this.motionZ = 0;
				this.crashCooldown = 20;
				if(this.leakages.size() < 16) {
					this.addLeakage(this.generateRandomLeakage());
				}
			}
		}
	}

	if(!this.world.isRemote || this.canPassengerSteer()) {
		Entity controller = this.getControllingPassenger();

		if(this.world.isRemote && this.canPassengerSteer() && controller instanceof EntityLivingBase) {
			controller.fallDistance = 0;

			this.handleControllerMovement((EntityLivingBase) controller);
		}

		this.updateCarriage();

		if(!this.world.isRemote) {
			this.lerpX = this.posX;
			this.lerpY = this.posY;
			this.lerpZ = this.posZ;
			this.lerpYaw = this.rotationYaw;
			this.lerpPitch = this.rotationPitch;

			for(DraetonPhysicsPart part : this.physicsParts) {
				part.lerpX = part.x;
				part.lerpY = part.y;
				part.lerpZ = part.z;
			}
		}

		if(!this.inWater) {
			if(this.getPassengers().isEmpty() || this.physicsParts.isEmpty()) {
				this.motionY -= 0.005f;
			}
			if(!this.isBurnerRunning()) {
				this.motionY -= 0.06f;
			}
		}
	} else if(this.world.isRemote) {
		this.motionX = this.motionY = this.motionZ = 0;

		for(DraetonPhysicsPart part : this.physicsParts) {
			part.tickLerp();
		}
	}

	this.updateBurner();

	this.updatePullerSlots();

	if(this.world instanceof WorldServer) {
		//Send server state of parts to non-controller players
		if(this.ticksExisted % this.movementSyncTicks == 0) {
			for(DraetonPhysicsPart part : this.physicsParts) {
				MessageUpdateDraetonPhysicsPart msg = new MessageUpdateDraetonPhysicsPart(this, part, MessageUpdateDraetonPhysicsPart.Action.UPDATE);

				Set<? extends EntityPlayer> tracking = ((WorldServer) this.world).getEntityTracker().getTrackingPlayers(this);
				for(EntityPlayer player : tracking) {
					//Don't send to controller
					if(player instanceof EntityPlayerMP && player != this.getControllingPassenger()) {
						TheBetweenlands.networkWrapper.sendTo(msg, (EntityPlayerMP) player);
					}
				}
			}
		}
	}

	this.firstUpdate = false;
}

    public void onLivingUpdate() {
		// Enforce Damage Limit:
		if(this.damageLimit > 0) {
			if (this.healthLastTick < 0)
				this.healthLastTick = this.getHealth();
			if (this.healthLastTick - this.getHealth() > this.damageLimit)
				this.setHealth(this.healthLastTick);
			this.healthLastTick = this.getHealth();
			if (!this.getEntityWorld().isRemote && this.updateTick % 20 == 0) {
				this.damageTakenThisSec = 0;
			}
		}

        super.onLivingUpdate();

		// Attack Updates:
		if(this.attackCooldown > 0) {
			this.attackCooldown--;
			if(this.attackCooldown > this.getAttackCooldownMax()) {
				this.triggerAttackCooldown();
			}
		}
        this.updateBattlePhase();
        this.updateArmSwingProgress();

		// Blocking Updates:
		if(this.currentBlockingTime > 0) {
			this.currentBlockingTime--;
		}
		if(this.currentBlockingTime < 0) {
			this.currentBlockingTime = 0;
		}

        // First Spawn:
        if(!this.getEntityWorld().isRemote && this.firstSpawn) {
            this.onFirstSpawn();
            this.firstSpawn = false;
        }

        // Fixate Target:
		if(!this.getEntityWorld().isRemote && !this.hasFixateTarget() && this.fixateUUID != null) {
			double range = 64D;
			List connections = this.getEntityWorld().getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(range, range, range));
			Iterator possibleFixateTargets = connections.iterator();
			while(possibleFixateTargets.hasNext()) {
				EntityLivingBase possibleFixateTarget = (EntityLivingBase)possibleFixateTargets.next();
				if(possibleFixateTarget != this && possibleFixateTarget.getUniqueID().equals(this.fixateUUID)) {
					this.setFixateTarget(possibleFixateTarget);
					break;
				}
			}
			this.fixateUUID = null;
		}
		if(this.hasFixateTarget()) {
        	this.setAttackTarget(this.getFixateTarget());
		}

        // Prevent Creative Attack Target:
        if(this.hasAttackTarget()) {
            if(this.getAttackTarget() instanceof EntityPlayer) {
                EntityPlayer targetPlayer = (EntityPlayer)this.getAttackTarget();
                if(targetPlayer.capabilities.isCreativeMode)
                    this.setAttackTarget(null);
            }
        }

        // Fleeing:
        if(this.hasAvoidTarget()) {
        	if(this.currentFleeTime-- <= 0)
        		this.setAvoidTarget(null);
        }

        // Gliding:
        if(!this.onGround && this.motionY < 0.0D) {
            this.motionY *= this.getFallingMod();
        }

        // Sunlight Damage:
        if(!this.getEntityWorld().isRemote && this.daylightBurns() && this.getEntityWorld().isDaytime()) {
        	float brightness = this.getBrightness();
            if(brightness > 0.5F && this.rand.nextFloat() * 30.0F < (brightness - 0.4F) * 2.0F && this.getEntityWorld().canBlockSeeSky(this.getPosition())) {
                boolean shouldBurn = true;
                ItemStack helmet = this.inventory.getEquipmentStack("head");
                if(helmet != null) {
                    if(helmet.isItemStackDamageable()) {
                    	helmet.setItemDamage(helmet.getItemDamage() + this.rand.nextInt(2));
                        if(helmet.getItemDamage() >= helmet.getMaxDamage()) {
                            this.renderBrokenItemStack(helmet);
                            this.setCurrentItemOrArmor(4, ItemStack.EMPTY);
                        }
                    }
                    shouldBurn = false;
                }
                if(shouldBurn) {
					this.setFire(8);
				}
            }
        }

        // Water Damage:
        if(!this.getEntityWorld().isRemote && this.waterDamage() && this.isWet() && !this.isInLava()) {
            this.attackEntityFrom(DamageSource.DROWN, 1.0F);
        }

        // Out of Water Suffocation:
        if(!this.getEntityWorld().isRemote && !this.canBreatheAboveWater()) {
	        int currentAir = this.getAir();
	        if(this.isEntityAlive()) {
	        	if((!this.isLavaCreature && !this.waterContact())
	        		|| (this.isLavaCreature && !this.lavaContact())) {
		        	currentAir--;
		            this.setAir(currentAir);
		            if(this.getAir() <= -200) {
		                this.setAir(-180);
		                this.attackEntityFrom(DamageSource.DROWN, 2.0F);
		            }
		        }
		        else {
		            this.setAir(299);
		        }
	        }
        }

        // Natural Despawn Light Scaling:
        float light = this.getBrightness();
        if(!this.creatureInfo.creatureSpawn.spawnsInLight && light > 0.5F) {
			this.idleTime += 2;
		}
		else if(!this.creatureInfo.creatureSpawn.spawnsInDark && light <= 0.5F) {
			this.idleTime += 2;
		}

	    // Stealth Invisibility:
    	if(!this.getEntityWorld().isRemote) {
	        if(this.isStealthed() && !this.isInvisible())
	        	this.setInvisible(true);
	        else if(!this.isStealthed() && this.isInvisible() && !this.isPotionActive(MobEffects.INVISIBILITY))
                this.setInvisible(false);
    	}
        if(this.isStealthed()) {
        	if(this.stealthPrev != this.isStealthed())
                this.startStealth();
            this.onStealth();
        }
        else if(this.isInvisible() && !this.isPotionActive(MobEffects.INVISIBILITY) && !this.getEntityWorld().isRemote) {
            this.setInvisible(false);
        }
        this.stealthPrev = this.isStealthed();

        // Pickup Items:
        if(this.ticksExisted % 20 == 0 && !this.getEntityWorld().isRemote && this.isEntityAlive() && this.canPickupItems())
        	this.pickupItems();

        // Entity Pickups:
        if(!this.getEntityWorld().isRemote && this.pickupEntity != null) {
			if(!this.pickupEntity.isEntityAlive())
				this.dropPickupEntity();
			else if(Math.sqrt(this.getDistance(this.pickupEntity)) > 32D) {
				this.dropPickupEntity();
			}
        }

        // Boss Health Bar:
        this.getBossInfo();

        // Minion To Master Update:
        if(this.getMasterTarget() != null && this.getMasterTarget() instanceof EntityCreatureBase)
            ((EntityCreatureBase)this.getMasterTarget()).onMinionUpdate(this, this.updateTick);

        this.updateTick++;
    }

public void tick() {
    super.tick();
    prevStrikeProgress = strikeProgress;
    prevReturnProgress = returnProgress;
    Entity controller = getController();
    Entity target = getTarget();
    if (!level().isClientSide) {
        if (this.comingBack || controller instanceof TeletorEntity && (target == null || !target.isAlive())) {
            this.noPhysics = true;
        } else {
            this.noPhysics = false;
        }
        if (controller == null && this.tickCount > 20 || this.getItemStack().isEmpty()) {
            if(hadPlayerController){
                this.plopItem();
                hadPlayerController = false;
            }
            this.remove(RemovalReason.DISCARDED);
        }
    }
    if ((this.getTarget() == null || comingBack || playerUseCooldown > 0) && strikeProgress > 0) {
        strikeProgress = Math.max(0, strikeProgress - 0.1F);
    }
    if (controller instanceof TeletorEntity teletor) {
        this.entityData.set(CONTROLLER_ID, teletor.getId());
        teletor.setWeaponUUID(this.getUUID());
        if (!level().isClientSide) {
            Entity e = teletor.getTarget();
            this.entityData.set(TARGET_ID, e != null && e.isAlive() ? e.getId() : -1);
        }
        boolean attacking = !comingBack && target != null && target.isAlive();
        Vec3 vec3 = attacking ? target.getEyePosition() : teletor.getWeaponPosition();
        Vec3 want = vec3.subtract(this.position());
        if (target != null && !comingBack) {
            this.entityData.set(IDLING, false);
            if (want.length() < target.getBbWidth() + 1F) {
                if (strikeProgress < 1F) {
                    strikeProgress = Math.max(0, strikeProgress + 0.35F);
                } else {
                    hurtEntity(teletor, target);
                    this.comingBack = true;
                }
            } else if (want.length() > 32) {
                this.comingBack = true;
            }
        }
        directMovementTowards(vec3, 0.1F);
        if (this.distanceTo(controller) < 2.5F && this.getY() > controller.getY()) {
            this.entityData.set(IDLING, true);
            if (this.comingBack) {
                this.comingBack = false;
            }
        }
    } else if (controller instanceof Player player) {
        Vec3 moveTo = null;
        this.entityData.set(CONTROLLER_ID, controller.getId());
        this.entityData.set(IDLING, false);
        this.comingBack = !isOwnerWearingGauntlet();
        float speed = 0.1F;
        boolean haste = false;
        if (isOwnerWearingGauntlet()) {
            hadPlayerController = true;
            float maxDist = 30F;
            if(getController() instanceof LivingEntity living && living.getUseItem().is(ACItemRegistry.GALENA_GAUNTLET.get())){
                ItemStack useItem = living.getUseItem();
                haste = useItem.getEnchantmentLevel(ACEnchantmentRegistry.FERROUS_HASTE.get()) > 0;
                int fieldExtension = useItem.getEnchantmentLevel(ACEnchantmentRegistry.FIELD_EXTENSION.get());
                maxDist += fieldExtension * 5F;
            }
            BlockPos miningBlock = null;
            HitResult hitresult = ProjectileUtil.getHitResultOnViewVector(player, Entity::canBeHitByProjectile, maxDist);
            if (hitresult instanceof EntityHitResult entityHitResult && playerUseCooldown == 0) {
                Entity entity = entityHitResult.getEntity();
                moveTo = entity.position().add(0, entity.getBbHeight() * 0.5F, 0);
                speed = 0.2F;
                if (this.distanceTo(entity) < entity.getBbWidth() + 1.5F) {
                    if (strikeProgress < 1F) {
                        strikeProgress = Math.max(0, strikeProgress + 0.35F);
                    } else {
                        hurtEntity(player, entity);

                        playerUseCooldown = haste ? 3 : 5 + random.nextInt(5);
                    }
                }
            } else {
                moveTo = player.getEyePosition().add(player.getViewVector(1.0F).scale(maxDist - 20F));
                if (hitresult.getType() == HitResult.Type.BLOCK || hitresult.getLocation().subtract(player.getEyePosition()).length() < maxDist) {
                    if (hitresult instanceof BlockHitResult blockHitResult) {
                        if (this.distanceToSqr(Vec3.atCenterOf(blockHitResult.getBlockPos())) < 2.25F) {
                            miningBlock = blockHitResult.getBlockPos();
                        }
                        if (!level().getBlockState(blockHitResult.getBlockPos()).isAir()) {
                            moveTo = hitresult.getLocation();
                        }
                    }
                }
            }
            if (miningBlock != null) {
                if (lastSelectedBlock == null || !lastSelectedBlock.equals(miningBlock)) {
                    if (lastSelectedBlock != null) {
                        this.level().destroyBlockProgress(player.getId(), lastSelectedBlock, -1);
                    }
                    lastSelectedBlock = miningBlock;
                    destroyBlockProgress = 0.0F;
                }
                BlockState miningState = level().getBlockState(miningBlock);
                SoundType soundType = miningState.getSoundType();
                float f = miningState.getDestroySpeed(level(), miningBlock);
                float itemDestroySpeed = getDigSpeed(player, miningState, miningBlock);
                if (itemDestroySpeed > 1.0F) {
                    if (totalMiningTime % 4 == 0) {
                        this.playSound(soundType.getHitSound(), (soundType.getVolume() + 1.0F) / 8.0F, soundType.getPitch() * 0.5F);
                    }
                    totalMiningTime++;
                    strikeProgress = (float) Math.abs(Math.sin(tickCount * 0.6F) * 1.2F - 0.2F);
                    float j = itemDestroySpeed / f / (float) (haste ? 8 : 10);
                    destroyBlockProgress += j;
                    this.level().destroyBlockProgress(player.getId(), lastSelectedBlock, (int) (destroyBlockProgress * 10F));
                    if (destroyBlockProgress >= 1.0F && !level().isClientSide) {
                        damageItem(1);
                        ItemStack itemStack = getItemStack();
                        itemStack.mineBlock(this.level(), miningState, miningBlock, player);
                        int fortuneLevel = itemStack.getEnchantmentLevel(Enchantments.BLOCK_FORTUNE);
                        int silkTouchLevel = itemStack.getEnchantmentLevel(Enchantments.SILK_TOUCH);
                        int exp = miningState.getExpDrop(level(), level().random, miningBlock, fortuneLevel, silkTouchLevel);
                        net.minecraftforge.event.ForgeEventFactory.onPlayerDestroyItem(player, itemStack, InteractionHand.MAIN_HAND);
                        boolean flag;
                        if (miningState.getBlock() instanceof ShulkerBoxBlock) {
                            flag = level().destroyBlock(miningBlock, true);
                            player.awardStat(Stats.BLOCK_MINED.get(miningState.getBlock()));
                            player.causeFoodExhaustion(0.005F);
                        }
                        else {
                            flag = level().destroyBlock(miningBlock, false);
                            miningState.getBlock().playerDestroy(level(), player, miningBlock, miningState, level().getBlockEntity(miningBlock), itemStack);
                        }
                        if (flag && exp > 0 && level() instanceof ServerLevel serverLevel) {
                            miningState.getBlock().popExperience(serverLevel, miningBlock, exp);
                        }
                        destroyBlockProgress = 0.0F;
                    }
                }
            }
        } else {
            if (returnProgress < 1F) {
                returnProgress = Math.min(1, returnProgress + 0.2F);
            }
            if (lastSelectedBlock != null) {
                this.level().destroyBlockProgress(player.getId(), lastSelectedBlock, -1);
                lastSelectedBlock = null;
            }
            moveTo = player.position().add(0, 1, 0);
            if (distanceTo(controller) < 1.4) {
                if (!this.isRemoved()) {
                    if(!spawnedItem && player.addItem(this.getItemStack())){
                        spawnedItem = true;
                        this.remove(RemovalReason.DISCARDED);
                    }else{
                        plopItem();
                    }
                }
            }
        }
        if (moveTo != null) {
            directMovementTowards(moveTo, speed);
        }
    }
    if (playerUseCooldown > 0) {
        playerUseCooldown--;
    }
    this.move(MoverType.SELF, this.getDeltaMovement());
    this.setDeltaMovement(this.getDeltaMovement().scale(0.9F));
}

public static void DamageEvents(LivingDamageEvent event){
    LivingEntity target = event.getEntity();
    Entity attacker = event.getSource().getEntity();
    float finalDamage = event.getAmount();

    if (!target.level.isClientSide) {
        if (target.hasEffect(GoetyEffects.SAPPED.get())) {
            MobEffectInstance effectInstance = target.getEffect(GoetyEffects.SAPPED.get());
            if (effectInstance != null) {
                int i = effectInstance.getAmplifier() + 1;
                finalDamage += finalDamage * (0.2F * i);
            }
        }

        if (target.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
            if (!event.getSource().is(ModDamageSource.VOIDED)) {
                MobEffectInstance effectInstance = target.getEffect(GoetyEffects.VOID_TOUCHED.get());
                if (effectInstance != null) {
                    int i = effectInstance.getAmplifier() + 2;
                    finalDamage *= i;
                    target.removeEffect(GoetyEffects.VOID_TOUCHED.get());
                }
            }
        }

        if (target.hasEffect(GoetyEffects.SHIELDING.get()) || target.hasEffect(GoetyEffects.SHIELDED.get())) {
            if (!event.getSource().is(DamageTypeTags.BYPASSES_EFFECTS) && !event.getSource().is(DamageTypeTags.BYPASSES_RESISTANCE)) {
                MobEffectInstance effectInstance = target.getEffect(GoetyEffects.SHIELDING.get());
                if (effectInstance == null && target.hasEffect(GoetyEffects.SHIELDED.get())) {
                    effectInstance = target.getEffect(GoetyEffects.SHIELDED.get());
                }
                if (effectInstance != null) {
                    int i = effectInstance.getAmplifier() + 1;
                    finalDamage -= finalDamage * (0.05F * i);
                }
            }
        }

        if (attacker instanceof LivingEntity attackerL) {
            if (attackerL.hasEffect(GoetyEffects.SHADOW_WALK.get())) {
                float multiply = 1.25F + (EffectsUtil.getAmplifier(attackerL, GoetyEffects.SHADOW_WALK.get()) / 4.0F);
                finalDamage *= multiply;
                attackerL.removeEffect(GoetyEffects.SHADOW_WALK.get());
            }
            if (target.hasEffect(GoetyEffects.CHILL_HIDE.get()) && ModDamageSource.physicalAttacks(event.getSource())) {
                MobEffectInstance effectInstance = target.getEffect(GoetyEffects.CHILL_HIDE.get());
                if (effectInstance != null) {
                    int i = effectInstance.getAmplifier() * 2;
                    attackerL.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + i), 1));
                }
            }
            if (attackerL.hasEffect(GoetyEffects.RADIANCE.get())) {
                MobEffectInstance effectInstance = attackerL.getEffect(GoetyEffects.RADIANCE.get());
                if (effectInstance != null) {
                    int amp = effectInstance.getAmplifier() + 1;
                    float heal = 6.0F * ((amp / 2.0F) + 1);
                    if (attackerL.level instanceof ServerLevel serverLevel) {
                        float chance = event.getSource().is(DamageTypeTags.IS_PROJECTILE) ? 0.5F : 0.2F;
                        if (attackerL.level.getRandom().nextFloat() <= chance) {
                            attackerL.level.playSound(null, target, ModSounds.RADIANCE_WAVE.get(), attacker.getSoundSource(), 0.9F, 1.0F);
                            serverLevel.sendParticles(new ShockwaveParticleOption(4, 1), target.getX(), target.getY() + 0.25F, target.getZ(), 0, 0, 0, 0, 0.5F);
                            for (LivingEntity living2 : attackerL.level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(4.0D), ally -> MobUtil.areAllies(attackerL, ally) || ally == attackerL)) {
                                living2.heal(heal);
                                for (int i = 0; i < serverLevel.getRandom().nextInt(10) + 10; ++i) {
                                    serverLevel.sendParticles(ModParticleTypes.HEAL_EFFECT_2.get(), living2.getRandomX(1.5D), living2.getRandomY(), living2.getRandomZ(1.5D), 0, 0.0F, 1.0F, 0.0F, 1.0F);
                                }
                                ColorUtil colorUtil = new ColorUtil(0xfffcc5);
                                serverLevel.sendParticles(new RisingCircleParticleOption(0), living2.getX(), living2.getY(), living2.getZ(), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);
                                living2.level.playSound(null, living2, ModSounds.HEAL_SPELL.get(), living2.getSoundSource(), 1.0F, 1.0F);
                            }
                        }
                    }
                }
            }
            if (attackerL.hasEffect(GoetyEffects.LEECHING.get())) {
                MobEffectInstance effectInstance = attackerL.getEffect(GoetyEffects.LEECHING.get());
                if (effectInstance != null) {
                    if (ModDamageSource.physicalAttacks(event.getSource())) {
                        int amp = effectInstance.getAmplifier();
                        float increase = 0.02F * amp;
                        float heal = target.getMaxHealth() * (0.05F + increase);
                        if (heal > 0.0F) {
                            attackerL.level.playSound(null, attackerL, ModSounds.LEECHING.get(), attackerL.getSoundSource(), 1.0F, 1.0F);
                            attackerL.heal(heal);
                        }
                    }
                }
            }
            if (attackerL.hasEffect(GoetyEffects.SWIRLING.get())) {
                MobEffectInstance effectInstance = attackerL.getEffect(GoetyEffects.SWIRLING.get());
                if (effectInstance != null) {
                    if (ModDamageSource.physicalAttacks(event.getSource()) && !event.getSource().is(ModDamageSource.SWORD)) {
                        int amp = effectInstance.getAmplifier();
                        float damage = 5.0F * ((amp / 2.0F) + 1);
                        if (attackerL.level instanceof ServerLevel serverLevel) {
                            ServerParticleUtil.windShockwaveParticle(serverLevel, ColorUtil.WHITE, 4.0F, 0, -1, attackerL.position().add(0.0D, 1.0D, 0.0D));
                            for (LivingEntity livingEntity : attackerL.level.getEntitiesOfClass(LivingEntity.class, attackerL.getBoundingBox().inflate(4.0D, 1.0D, 4.0D))) {
                                if (attackerL != livingEntity && livingEntity != target && !MobUtil.areAllies(attackerL, livingEntity)) {
                                    livingEntity.hurt(ModDamageSource.sword(attackerL, attackerL), damage);
                                }
                            }
                        }
                    }
                }
            }
        }

        if (event.getAmount() > 0.0F) {
            if (target.hasEffect(GoetyEffects.ALTRUISTIC.get())) {
                MobEffectInstance effectInstance = target.getEffect(GoetyEffects.ALTRUISTIC.get());
                if (effectInstance != null) {
                    int amp = effectInstance.getAmplifier() + 1;
                    float heal = Math.min(0.25F * amp, 1.0F);
                    for (LivingEntity living : target.level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(60.0D), livingEntity -> MobUtil.areAllies(target, livingEntity) && livingEntity != target)) {
                        living.heal(event.getAmount() * heal);
                    }
                }
            }
            if (target.hasEffect(GoetyEffects.MANDATE.get())) {
                MobEffectInstance effectInstance = target.getEffect(GoetyEffects.MANDATE.get());
                if (effectInstance != null) {
                    int amp = effectInstance.getAmplifier() + 1;
                    double radius = 8.0D * amp;
                    int size = 4 * amp;
                    List<LivingEntity> allies = target.level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(radius), livingEntity -> MobUtil.areAllies(target, livingEntity) && livingEntity != target && !livingEntity.hasEffect(GoetyEffects.MANDATE.get()));
                    if (target instanceof Mob mob) {
                        allies.removeIf(livingEntity -> MobUtil.getOwner(livingEntity) != mob);
                    }
                    if (!allies.isEmpty()) {
                        allies.sort(Comparator.comparingDouble(target::distanceToSqr));
                        if (allies.size() > size) {
                            allies.subList(size, allies.size()).clear();
                        }
                        finalDamage /= (allies.size() + 1);
                        float distribute = finalDamage;
                        for (LivingEntity living : allies) {
                            if (living != target) {
                                living.hurt(event.getSource(), distribute);
                            }
                        }
                    }
                }
            }
            Entity aggressor = null;
            LivingEntity enchanted = null;
            if (target.hasEffect(GoetyEffects.ENCHANTED.get())) {
                finalDamage *= 0.5F;
                aggressor = attacker;
                enchanted = target;
            } else if (attacker instanceof LivingEntity livingEntity && livingEntity.hasEffect(GoetyEffects.ENCHANTED.get())) {
                aggressor = target;
                enchanted = livingEntity;
            }
            if (aggressor instanceof Mob mob && mob.getTarget() == enchanted) {
                if (MiscCapHelper.getEnchanter(enchanted) instanceof LivingEntity livingEntity) {
                    float chance = 0.05F;
                    if (mob.getHealth() < mob.getMaxHealth() * 0.5F) {
                        chance += 0.2F;
                    }
                    if (mob.getHealth() < mob.getMaxHealth() * 0.25F) {
                        chance += 0.2F;
                    }
                    if (mob.getRandom().nextFloat() <= chance) {
                        mob.setTarget(livingEntity);
                    }
                }
            }
        }
        if (finalDamage != event.getAmount()) {
            event.setAmount(finalDamage);
        }
    }
}

public void tick() {
    super.tick();
    final boolean shooting = entityData.get(SHOOTING);
    if (prevFlying != this.isFlying()) {
        this.refreshDimensions();
    }

    if (shooting) {
        if (shootProgress < 5F)
            shootProgress++;
    } else {
        if (shootProgress > 0F)
            shootProgress--;
    }

    if (this.isFlying()) {
        if (flyProgress < 5F)
            flyProgress++;
    } else {
        if (flyProgress > 0F)
            flyProgress--;
    }

    if (!this.level().isClientSide) {
        if (this.isPassenger())
            this.setFlying(false);

        if (isFlying()) {
            this.setNoGravity(true);
        } else {
            this.setNoGravity(false);
        }
        LivingEntity target = this.getTarget();
        if (this.getFleeingEntityId() == -1) {
            if (target == null && tickCount - repellentCheckTime > 50) {
                repellentCheckTime = tickCount;
                LivingEntity closestRepel = null;
                for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(30), REPELLENT)) {
                    if(closestRepel == null || entity.distanceTo(this) < closestRepel.distanceTo(this)){
                        closestRepel = entity;
                    }
                }
                if(closestRepel != null){
                    this.setFleeingEntityId(closestRepel.getId());
                }
            }
            if (target != null && REPELLENT.test(target) && this.distanceTo(target) < 20) {
                this.setFleeingEntityId(target.getId());
            }
        } else {
            Entity fleeing = level().getEntity(this.getFleeingEntityId());
            if (fleeing instanceof LivingEntity living && REPELLENT.test(living) && this.distanceTo(living) < 20) {
                this.setTarget(null);
                this.setLastHurtByMob(null);
                if(this.isPassenger()){
                    this.stopRiding();
                }
                if(fleePos == null || fleePos.distanceTo(this.position()) < 3 || random.nextInt(40) == 0){
                    Vec3 vec = LandRandomPos.getPosAway(this, 8, 4, fleeing.position());
                    if(vec != null){
                        fleePos = vec;
                    }
                }else{
                    this.setFlying(true);
                    this.moveControl.setWantedPosition(fleePos.x, fleePos.y + 1, fleePos.z, 1.2F);
                }
            } else {
                this.setFleeingEntityId(-1);
            }
        }
        if (hasLuringLaviathan()) {
            this.setTarget(null);
            this.setLastHurtByMob(null);
            final Entity entity = this.level().getEntity(this.getLuringLaviathan());
            if (entity instanceof EntityLaviathan && ((EntityLaviathan) entity).isChilling()) {
                Vec3 vec = ((EntityLaviathan) entity).getLureMosquitoPos();
                this.setFlying(true);
                this.lookAt(entity, 10, 10);
                this.getMoveControl().setWantedPosition(vec.x, vec.y, vec.z, 0.7F);
            } else {
                this.setLuringLaviathan(-1);
            }
        }
    }
    if (this.flyProgress == 0 && random.nextInt(200) == 0) {
        randomWingFlapTick = 5 + random.nextInt(15);
    }
    if (randomWingFlapTick > 0) {
        randomWingFlapTick--;
    }
    if (!this.level().isClientSide && onGround() && !this.isFlying() && (flightTicks >= 0 && random.nextInt(5) == 0 || this.getTarget() != null)) {
        this.setFlying(true);
        this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
        this.setOnGround(false);
        this.hasImpulse = true;
    }
    if (flightTicks < 0) {
        flightTicks++;
    }
    if (!this.level().isClientSide && isFlying()) {
        flightTicks++;
        if (flightTicks > 200 && (this.getTarget() == null || !this.getTarget().isAlive())) {
            BlockPos above = this.getGroundPosition(this.blockPosition().above());
            if (level().getFluidState(above).isEmpty() && !level().getBlockState(above).isAir()) {
                this.getDeltaMovement().add(0, -0.2D, 0);
                if (this.onGround()) {
                    this.setFlying(false);
                    flightTicks = -150 - random.nextInt(200);
                }
            }
        }
    }
    prevMosquitoScale = this.getMosquitoScale();
    if (isShrinking()) {
        if (this.getMosquitoScale() > 0.4F) {
            this.setMosquitoScale(this.getMosquitoScale() - 0.1F);
        }
    } else {
        if (this.getMosquitoScale() < 1F && !this.isSick()) {
            this.setMosquitoScale(this.getMosquitoScale() + 0.05F);
        }
    }
    if (!this.level().isClientSide && shootingTicks > 0) {
        shootingTicks--;
        if (shootingTicks == 0) {
            if (this.getTarget() != null && this.getBloodLevel() > 0) {
                this.spit(this.getTarget());
            }
            this.entityData.set(SHOOTING, false);
        }
    }
    if (isFlying()) {
        if (loopSoundTick == 0) {
            this.gameEvent(GameEvent.ENTITY_ROAR);
            this.playSound(AMSoundRegistry.MOSQUITO_LOOP.get(), this.getSoundVolume(), this.getVoicePitch());
        }
        loopSoundTick++;
        if (loopSoundTick > 100) {
            loopSoundTick = 0;
        }
    }

    if (isPassenger()) {
        if (drinkTime < 0)
            drinkTime = 0;

        drinkTime++;
    } else {
        drinkTime = 0;
    }
    prevFlyProgress = flyProgress;
    prevShootProgress = shootProgress;
    prevFlying = this.isFlying();
    if (this.isSick()) {
        sickTicks++;
        if (this.getTarget() != null && !this.isPassenger()) {
            this.setTarget(null);
        }
        if (sickTicks > 100) {
            this.setShrink(false);
            this.setMosquitoScale(this.getMosquitoScale() + 0.015F);
            if (sickTicks > 160) {
                EntityWarpedMosco mosco = AMEntityRegistry.WARPED_MOSCO.get().create(level());
                mosco.copyPosition(this);
                if (!this.level().isClientSide) {
                    mosco.finalizeSpawn((ServerLevelAccessor) level(), level().getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.CONVERSION, null, null);
                }

                if (!this.level().isClientSide) {
                    this.level().broadcastEntityEvent(this, (byte) 79);
                    level().addFreshEntity(mosco);
                }
                this.remove(RemovalReason.DISCARDED);

            }
        }
    }
}

public void tick() {
    super.tick();
    prevSitProgress = sitProgress;
    prevStandProgress = standProgress;

    if (isSitting()) {
        if (this.sitProgress < 5F)
            this.sitProgress++;
    } else {
        if (this.sitProgress > 0F)
            this.sitProgress--;
    }

    if (isStanding()) {
        if (this.standProgress < 5F)
            this.standProgress += 0.5F;
    } else {
        if (this.standProgress > 0F)
            this.standProgress -= 0.5F;
    }

    if (isStanding() && ++standingTime > maxStandTime) {
        this.setStanding(false);
        standingTime = 0;
        maxStandTime = 75 + random.nextInt(50);
    }
    if (isSitting() && isStanding()) {
        this.setStanding(false);
    }
    if (hasChestVarChanged && elephantInventory != null && !this.isChested()) {
        for (int i = 3; i < 18; i++) {
            if (!elephantInventory.getItem(i).isEmpty()) {
                if (!this.level().isClientSide) {
                    this.spawnAtLocation(elephantInventory.getItem(i), 1);
                }
                elephantInventory.removeItemNoUpdate(i);
            }
        }
        hasChestVarChanged = false;
    }
    if (!hasTuskedAttributes && isTusked() && !isBaby()) {
        refreshDimensions();
    }
    if (hasTuskedAttributes && !isTusked() && !isBaby()) {
        refreshDimensions();
    }
    if (charging) {
        chargingTicks++;
    }
    if (!this.getMainHandItem().isEmpty() && this.canTargetItem(this.getMainHandItem())) {
        if (this.getAnimation() == NO_ANIMATION) {
            this.setAnimation(ANIMATION_EAT);
        }
        if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() == 17) {
            this.eatItemEffect(this.getMainHandItem());
            if (this.getMainHandItem().is(AMTagRegistry.ELEPHANT_TAMEABLES) && !this.isTame() && (!isTusked() || isBaby()) && blossomThrowerUUID != null) {
                if (random.nextInt(3) == 0) {
                    this.setTame(true);
                    this.setOwnerUUID(blossomThrowerUUID);
                    Player player = this.level().getPlayerByUUID(blossomThrowerUUID);
                    if (player != null) {
                        this.tame(player);
                    }
                    for (Entity passenger : this.getPassengers()) {
                        passenger.removeVehicle();
                    }
                    this.level().broadcastEntityEvent(this, (byte) 7);
                } else {
                    this.level().broadcastEntityEvent(this, (byte) 6);
                }
            }
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            this.heal(10);
        }
    }
    if (chargeCooldown > 0) {
        chargeCooldown--;
    }
    if (charging) {
        chargingTicks++;
    } else {
        chargingTicks = 0;
    }
    if (this.getAnimation() == ANIMATION_CHARGE_PREPARE) {
        this.yBodyRot = getYRot();
        if (this.getAnimationTick() == 20) {
            this.charging = true;
        }
    }
    if (this.getControllingPassenger() != null && charging && chargingTicks > 100) {
        this.charging = false;
        this.chargeCooldown = 200;
    }
    LivingEntity target = this.getTarget();
    double maxAttackMod = 0.0F;
    if (this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player) {
        Player rider = (Player) this.getControllingPassenger();
        if (rider.getLastHurtMob() != null && !this.isAlliedTo(rider.getLastHurtMob())) {
            UUID preyUUID = rider.getLastHurtMob().getUUID();
            if (!this.getUUID().equals(preyUUID)) {
                target = rider.getLastHurtMob();
                maxAttackMod = 4F;
            }
        }
    }
    if (!this.level().isClientSide && target != null) {
        if (this.distanceTo(target) > this.getBbWidth() * 0.5F + 0.5F && this.getControllingPassenger() == null && this.isTusked() && this.hasLineOfSight(target) && this.getAnimation() == NO_ANIMATION && !charging && chargeCooldown == 0) {
            this.setAnimation(ANIMATION_CHARGE_PREPARE);
        }
        if (this.getAnimation() == ANIMATION_CHARGE_PREPARE && this.getControllingPassenger() == null) {
            this.lookAt(target, 360, 30);
            this.yBodyRot = getYRot();
            if (this.getAnimationTick() == 20) {
                this.charging = true;
            }
        }
        if (this.distanceTo(target) < 10D && charging) {
            this.setAnimation(ANIMATION_FLING);
        }
        if (this.distanceTo(target) < 2.1D && charging) {
            target.knockback(1F, target.getX() - this.getX(), target.getZ() - this.getZ());
            target.hasImpulse = true;
            target.setDeltaMovement(target.getDeltaMovement().add(0, 0.7F, 0));
            target.hurt(this.damageSources().mobAttack(this), 2.4F * (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            launch(target, true);
            this.charging = false;
            this.chargeCooldown = 400;
        }
        double dist = this.distanceTo(target);
        if (dist < 4.5D + maxAttackMod && this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() == 15) {
            target.knockback(1F, target.getX() - this.getX(), target.getZ() - this.getZ());
            target.setDeltaMovement(target.getDeltaMovement().add(0, 0.3F, 0));
            launch(target, false);
            target.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        if (dist < 4.5D + maxAttackMod && this.getAnimation() == ANIMATION_STOMP && this.getAnimationTick() == 17) {
            target.knockback(0.3F, target.getX() - this.getX(), target.getZ() - this.getZ());
            target.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
    }
    if (!this.level().isClientSide && this.getTarget() == null && this.getControllingPassenger() == null) {
        charging = false;
    }
    if (charging && !hasChargedSpeed) {
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.65F);
        hasChargedSpeed = true;
    }
    if (!charging && hasChargedSpeed) {
        this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35F);
        hasChargedSpeed = false;
    }
    if (!this.level().isClientSide && this.getRandom().nextInt(400) == 0 && this.getAnimation() == NO_ANIMATION) {
        this.setAnimation(this.getRandom().nextBoolean() ? ANIMATION_TRUMPET_0 : ANIMATION_TRUMPET_1);
    }
    if (this.getAnimation() == ANIMATION_TRUMPET_0 && this.getAnimationTick() == 8 || this.getAnimation() == ANIMATION_TRUMPET_1 && this.getAnimationTick() == 4) {
        this.gameEvent(GameEvent.ENTITY_ROAR);
        this.playSound(AMSoundRegistry.ELEPHANT_TRUMPET.get(), this.getSoundVolume(), this.getVoicePitch());
    }
    if (this.isAlive() && charging) {
        for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
            if (!(this.isTame() && isAlliedTo(entity)) && !(!this.isTame() && entity instanceof EntityElephant) && entity != this) {
                entity.hurt(this.damageSources().mobAttack(this), 8.0F + random.nextFloat() * 8.0F);
                launch(entity, true);
            }
        }
        this.setMaxUpStep(2F);
    }else{
        this.setMaxUpStep(1.1F);
    }
    if (!isTame() && isTrader()) {
        if (!this.level().isClientSide) {
            this.tryDespawn();
        }
    }
    if (this.getTarget() != null && !this.getTarget().isAlive()) {
        this.setTarget(null);
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

    public void travel(@NotNull Vec3 pTravelVector) {
        if (this.getAnimation() == ANIMATION_SHAKEPREY || !this.canMove() && !this.isVehicle() || this.isOrderedToSit()) {
            if (this.getNavigation().getPath() != null) {
                this.getNavigation().stop();
            }
            pTravelVector = new Vec3(0, 0, 0);
        }
        // Player riding controls
        // Note: when motion is handled by the client no server side setDeltaMovement() should be called
        // otherwise the movement will halt
        // Todo: move wrongly fix
        if (allowLocalMotionControl && this.getControllingPassenger() != null && canBeControlledByRider()) {
            LivingEntity rider = (LivingEntity) this.getControllingPassenger();
            if (rider == null) {
                super.travel(pTravelVector);
                return;
            }

            // Flying control, include flying through waterfalls
            if (isHovering() || isFlying()) {
                double forward = rider.zza;
                double strafing = rider.xxa;
                double vertical = 0;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);
                // Bigger difference in speed for young and elder dragons
//                float airSpeedModifier = (float) (5.2f + 1.0f * Mth.map(Math.min(this.getAgeInDays(), 125), 0, 125, 0f, 1.5f));
                float airSpeedModifier = (float) (5.2f + 1.0f * Mth.map(speed, this.minimumSpeed, this.maximumSpeed, 0f, 1.5f));
                // Apply speed mod
                speed *= airSpeedModifier;
                // Set flag for logic and animation
                if (forward > 0) {
                    this.setFlying(true);
                    this.setHovering(false);
                }
                // Rider controlled tackling
                if (this.isAttacking() && this.getXRot() > -5 && this.getDeltaMovement().length() > 1.0d) {
                    this.setTackling(true);
//                } else if (this.getXRot() > 10 && this.getDeltaMovement().length() > 1.0d) {
//                    this.setDiving(true);
                    // Todo: diving animation here
                } else {
                    this.setTackling(false);
                }

                gliding = allowMousePitchControl && rider.isSprinting();
                if (!gliding) {
                    // Mouse controlled yaw
                    speed += glidingSpeedBonus;
                    // Slower on going astern
                    forward *= rider.zza > 0 ? 1.0f : 0.5f;
                    // Slower on going sideways
                    strafing *= 0.4f;
                    if (isGoingUp() && !isGoingDown()) {
                        vertical = 1f;
                    } else if (isGoingDown() && !isGoingUp()) {
                        vertical = -1f;
                    }
                    // Damp the vertical motion so the dragon's head is more responsive to the control
                    else if (isControlledByLocalInstance()) {
//                        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.8f, 1.0f));
                    }
                } else {
                    // Mouse controlled yaw and pitch
                    speed *= 1.5f;
                    strafing *= 0.1f;
                    // Diving is faster
                    // Todo: a new and better algorithm much like elytra flying
                    glidingSpeedBonus = (float) Mth.clamp(glidingSpeedBonus + this.getDeltaMovement().y * -0.05d, -0.8d, 1.5d);
                    speed += glidingSpeedBonus;
                    // Try to match the moving vector to the rider's look vector
                    forward = Mth.abs(Mth.cos(this.getXRot() * ((float) Math.PI / 180F)));
                    vertical = Mth.abs(Mth.sin(this.getXRot() * ((float) Math.PI / 180F)));
                    // Pitch is still responsive to spacebar and x key
                    if (isGoingUp() && !isGoingDown()) {
                        vertical = Math.max(vertical, 0.5);
                    } else if (isGoingDown() && !isGoingUp()) {
                        vertical = Math.min(vertical, -0.5);
                    } else if (isGoingUp() && isGoingDown()) {
                        vertical = 0;
                    }
                    // X rotation takes minus on looking upward
                    else if (this.getXRot() < 0) {
                        vertical *= 1;
                    } else if (this.getXRot() > 0) {
                        vertical *= -1;
                    } else if (isControlledByLocalInstance()) {
//                        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.8f, 1.0f));
                    }
                }
                // Speed bonus damping
                glidingSpeedBonus -= glidingSpeedBonus * 0.01d;

                if (this.isControlledByLocalInstance()) {
                    // Vanilla friction on Y axis is smaller, which will influence terminal speed for climbing and diving
                    // use same friction coefficient on all axis simplifies how travel vector is computed
                    this.flyingSpeed = speed * 0.1F;
                    this.setSpeed(speed);

                    this.moveRelative(flyingSpeed, new Vec3(strafing, vertical, forward));
                    this.move(MoverType.SELF, this.getDeltaMovement());
                    this.setDeltaMovement(this.getDeltaMovement().multiply(new Vec3(0.9, 0.9, 0.9)));

                    Vec3 currentMotion = this.getDeltaMovement();
                    if (this.horizontalCollision) {
                        currentMotion = new Vec3(currentMotion.x, 0.1D, currentMotion.z);
                    }
                    this.setDeltaMovement(currentMotion);

                    this.calculateEntityAnimation(this, false);
                } else {
                    this.setDeltaMovement(Vec3.ZERO);
                }
                this.tryCheckInsideBlocks();
                this.updatePitch(this.yOld - this.getY());
                return;
            }
            // In water move control, for those that can't swim
            else if (isInWater() || isInLava()) {
                double forward = rider.zza;
                double strafing = rider.xxa;
                double vertical = 0;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);

                if (isGoingUp() && !isGoingDown()) {
                    vertical = 0.5f;
                } else if (isGoingDown() && !isGoingUp()) {
                    vertical = -0.5f;
                }

                this.flyingSpeed = speed;
                // Float in water for those can't swim is done in LivingEntity#aiStep on server side
                // Leave this handled by both side before we have a better solution
                this.setSpeed(speed);
                // Overwrite the zza in setSpeed
                this.setZza((float) forward);
                // Vanilla in water behavior includes float on water and moving very slow
                // in lava behavior includes moving slow and sink
                super.travel(pTravelVector.add(strafing, vertical, forward));

                return;
            }
            // Walking control
            else {
                double forward = rider.zza;
                double strafing = rider.xxa;
                // Inherit y motion for dropping
                double vertical = pTravelVector.y;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);

                float groundSpeedModifier = (float) (1.8F * this.getFlightSpeedModifier());
                speed *= groundSpeedModifier;
                // Try to match the original riding speed
                forward *= speed;
                // Faster sprint
                forward *= rider.isSprinting() ? 1.2f : 1.0f;
                // Slower going back
                forward *= rider.zza > 0 ? 1.0f : 0.2f;
                // Slower going sideway
                strafing *= 0.05f;

                if (this.isControlledByLocalInstance()) {
                    this.flyingSpeed = speed * 0.1F;
                    this.setSpeed(speed);

                    // Vanilla walking behavior includes going up steps
                    super.travel(new Vec3(strafing, vertical, forward));
                } else {
                    this.setDeltaMovement(Vec3.ZERO);
                }
                this.tryCheckInsideBlocks();
                this.updatePitch(this.yOld - this.getY());
                return;
            }
        }
        // No rider move control
        else {
            super.travel(pTravelVector);
        }
    }

public static void TargetEvents(LivingChangeTargetEvent event) {
    LivingEntity attacker = event.getEntity();
    LivingEntity target = event.getOriginalTarget();
    if (attacker instanceof Mob mobAttacker) {
        if (target != null) {
            if (target instanceof Player) {
                if (MobUtil.isWitchType(mobAttacker)) {
                    if (CuriosFinder.isWitchFriendly(target)) {
                        if (mobAttacker.getLastHurtByMob() != target) {
                            if (event.getTargetType() == MOB_TARGET) {
                                event.setNewTarget(null);
                            } else {
                                event.setCanceled(true);
                            }
                        } else {
                            mobAttacker.setLastHurtByMob(target);
                        }
