public void tick() {
    super.tick();
    this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
    prevSwimProgress = swimProgress;
    prevBiteProgress = biteProgress;
    prevHeadHeight = this.getHeadHeight();
    if (shouldSwim()) {
        if (swimProgress < 5F)
            swimProgress++;
    } else {
        if (swimProgress > 0F)
            swimProgress--;
    }

    if (this.isObsidian()) {
        if (!hasObsidianArmor) {
            hasObsidianArmor = true;
            this.getAttribute(Attributes.ARMOR).setBaseValue(30F);
        }
    } else {
        if (hasObsidianArmor) {
            hasObsidianArmor = false;
            this.getAttribute(Attributes.ARMOR).setBaseValue(10F);
        }
    }

    if (!this.level().isClientSide) {
        if (!this.isObsidian() && this.isInWaterOrBubble()) {
            if (conversionTime < 300) {
                conversionTime++;
            } else {
                this.setObsidian(true);
            }

        }
        if (shouldSwim()) {
            fallDistance = 0.0F;
        }
    }
    float neckBase = 0.8F;
    if (!this.isNoAi()) {
        Vec3[] avector3d = new Vec3[this.allParts.length];
        for (int j = 0; j < this.allParts.length; ++j) {
            this.allParts[j].collideWithNearbyEntities();
            avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
        }
        float yaw = this.yBodyRot * Mth.DEG_TO_RAD;
        float neckContraction = 2.0F * Math.abs(getHeadHeight() / 3) + 0.5F * Math.abs(getHeadYaw(0) / 50F);

        for (int l = 0; l < this.theEntireNeck.length; ++l) {
            float f = l / ((float) this.theEntireNeck.length);
            float f1 = -(2.2F + l - f * neckContraction);
            float f2 = Mth.sin(yaw + Maths.rad(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
            float f3 = Mth.cos(yaw + Maths.rad(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
            this.setPartPosition(this.theEntireNeck[l], f2 * f1, neckBase + Math.sin(f * Math.PI * 0.5F) * (getHeadHeight() * 1.1F), -f3 * f1);
        }
        this.setPartPosition(this.seat1, getXForPart(yaw, 145) * 0.75F, 2F, getZForPart(yaw, 145) * 0.75F);
        this.setPartPosition(this.seat2, getXForPart(yaw, -145) * 0.75F, 2F, getZForPart(yaw, -145) * 0.75F);
        this.setPartPosition(this.seat3, getXForPart(yaw, 35) * 0.95F, 2F, getZForPart(yaw, 35) * 0.95F);
        this.setPartPosition(this.seat4, getXForPart(yaw, -35) * 0.95F, 2F, getZForPart(yaw, -35) * 0.95F);

        if (this.level().isClientSide && this.isChilling()) {
            if (!this.isBaby()) {
                this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, 158) * 1.75F, this.getY(1), this.getZ() + getZForPart(yaw, 158) * 1.75F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, -166) * 1.48F, this.getY(1), this.getZ() + getZForPart(yaw, -166) * 1.48F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, 14) * 1.78F, this.getY(0.9), this.getZ() + getZForPart(yaw, 14) * 1.78F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, -14) * 1.6F, this.getY(1.1), this.getZ() + getZForPart(yaw, -14) * 1.6F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
            }
            this.level().addParticle(ParticleTypes.SMOKE, this.headPart.getRandomX(0.6D), this.headPart.getY(0.9), this.headPart.getRandomZ(0.6D), 0.0D, this.random.nextDouble() / 5.0D, 0.0D);

        }

        for (int l = 0; l < this.allParts.length; ++l) {
            this.allParts[l].xo = avector3d[l].x;
            this.allParts[l].yo = avector3d[l].y;
            this.allParts[l].zo = avector3d[l].z;
            this.allParts[l].xOld = avector3d[l].x;
            this.allParts[l].yOld = avector3d[l].y;
            this.allParts[l].zOld = avector3d[l].z;
        }
    }
    if ((this.isInLava() || this.isInWaterOrBubble()) && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (!(this.isInLava() || this.isInWaterOrBubble()) && !this.isLandNavigator) {
        switchNavigator(true);
    }
    if (!this.level().isClientSide) {
        if (this.getChillTime() > 0) {
            this.setChillTime(this.getChillTime() - 1);
        } else if (this.shouldSwim()) {
            if (random.nextInt(this.isVehicle() ? 200 : 2000) == 0 && revengeCooldown == 0) {
                this.setChillTime(100 + random.nextInt(500));
            }
        }
        if (revengeCooldown > 0) {
            revengeCooldown--;
        }
        if (headPeakCooldown > 0) {
            headPeakCooldown--;
        }
        if (revengeCooldown == 0 && this.getLastHurtByMob() != null) {
            this.setLastHurtByMob(null);
        }
    }
    if (!this.level().isClientSide) {
        if (this.getControllingPassenger() == null && (this.getChillTime() > 0 || this.hasHeadGear() || dismountCooldown > 0)) {
            floatLaviathan();
        }

        if (!this.isChilling() && headPeakCooldown == 0) {
            float low = getLowHeadHeight();
            this.setHeadHeight(this.getHeadHeight() + (0.5F + ((getLowHeadHeight() + getHighHeadHeight(low)) / 2F) - this.getHeadHeight()) * 0.2F);
        } else {
            if (getMaxFluidHeight() <= this.getBbHeight() * 0.5F && getMaxFluidHeight() >= this.getBbHeight() * 0.25F) {
                float mot = (float) this.getDeltaMovement().lengthSqr();
                this.setHeadHeight(Mth.clamp(this.getHeadHeight() + 0.1F - 0.2F * mot, 0, 2));
                headPeakCooldown = 5;
            }
        }
    }
    if (this.isChilling()) {
        boolean keepChillin = false;
        boolean startBiting = false;
        for (EntityCrimsonMosquito entity : this.level().getEntitiesOfClass(EntityCrimsonMosquito.class, this.getBoundingBox().inflate(30.0D), HEALTHY_MOSQUITOES)) {
            entity.setLuringLaviathan(this.getId());
            keepChillin = true;
        }
        if (keepChillin) {
            this.setChillTime(Math.max(20, this.getChillTime()));
        }
        for (EntityCrimsonMosquito entity : this.level().getEntitiesOfClass(EntityCrimsonMosquito.class, this.headPart.getBoundingBox().inflate(1.0D), HEALTHY_MOSQUITOES)) {
            startBiting = true;
            if (this.biteProgress == 5.0F) {
                entity.hurt(this.damageSources().mobAttack(this), 1000);
                entity.setShrink(true);
                this.setChillTime(0);
            }
        }
        if (startBiting) {
            if (this.entityData.get(ATTACK_TICK) <= 0 && this.biteProgress == 0) {
                this.entityData.set(ATTACK_TICK, 7);
            }
        }
    }
    if (this.entityData.get(ATTACK_TICK) > 0) {
        this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
    }
    if (this.entityData.get(ATTACK_TICK) > 0 && this.biteProgress < 5.0F) {
        this.biteProgress++;
    }
    if (this.entityData.get(ATTACK_TICK) <= 0 && this.biteProgress > 0.0F) {
        this.biteProgress--;
    }
    if (dismountCooldown > 0) {
        dismountCooldown--;
    }
    if (this.hasBodyGear()) {
        List<Entity> list = this.level().getEntities(this, this.getBoundingBox().inflate(0.2F, -0.01F, 0.2F), EntitySelector.pushableBy(this));
        if (!list.isEmpty()) {
            boolean flag2 = !this.level().isClientSide;
            for (int j = 0; j < list.size(); ++j) {
                Entity entity = list.get(j);
                if (!entity.hasPassenger(this)) {
                    if (flag2 && !(entity instanceof Player) && !entity.isPassenger() && entity.getBbWidth() < this.getBbWidth() && !(entity instanceof EntityLaviathan) && !(entity instanceof Enemy) && entity instanceof Mob && this.canAddPassenger(entity) && !(entity instanceof WaterAnimal)) {
                        entity.startRiding(this);
                    } else {
                        this.push(entity);
                    }
                }
            }
        }
    }
    if (this.isVehicle() && !this.level().isClientSide && tickCount % 40 == 0 && this.getPassengers().size() > 3) {
        for (Entity entity : this.getPassengers()) {
            if (entity instanceof ServerPlayer) {
                AMAdvancementTriggerRegistry.LAVIATHAN_FOUR_PASSENGERS.trigger((ServerPlayer) entity);
            }
        }
    }
    lastX = this.getX();
    lastZ = this.getZ();
}

public void update() {
    if (this.leader == null || this.leader.isCarcass() || this.leader.isDead) {
        this.updateLeader();
    }

    if (this.stateTicks > 0 && this.failedPathTicks < this.members.size() * 2) {
        this.stateTicks--;
    } else {
        if (this.herdType.shouldRandomlyFlock()) {
            this.state = this.state == State.MOVING ? State.IDLE : State.MOVING;
        } else {
            this.state = State.IDLE;
        }

        this.resetStateTicks();
        this.enemies.clear();
        this.fleeing = false;
    }

    if (this.leader != null) {
        if (this.leader.shouldSleep()) {
            this.state = State.IDLE;
            this.resetStateTicks();
        }

        this.center = this.getCenterPosition();

        if (this.enemies.size() > 0) {
            if (this.fleeing) {
                this.state = State.MOVING;

                float angle = 0.0F;

                for (EntityLivingBase attacker : this.enemies) {
                    angle += MathHelper.atan2(this.center.z - attacker.posZ, this.center.x - attacker.posX);
                }

                angle /= this.enemies.size();

                this.moveX = -MathHelper.cos(angle);
                this.moveZ = MathHelper.sin(angle);

                this.normalizeMovement();
            } else {
                this.state = State.IDLE;
            }
        } else {
            this.fleeing = false;
        }

        List<DinosaurEntity> remove = new LinkedList<>();

        for (DinosaurEntity entity : this) {
            if (entity.getDistanceSq(this.center.x, this.center.y, this.center.z) > 2048) {
                remove.add(entity);
            }
        }

        for (DinosaurEntity entity : remove) {
            this.splitHerd(entity);

            if (entity == this.leader) {
                this.updateLeader();
            }
        }

        if (this.leader == null) {
            return;
        }

        boolean attemptedPath = false;
        int failedPaths = 0;

        for (DinosaurEntity entity : this) {
            if (this.enemies.isEmpty() || this.fleeing) {
                if (!(entity.getMetabolism().isHungry() || entity.getMetabolism().isThirsty()) && !entity.isMovementBlocked() && !entity.isInWater() && (this.fleeing || entity.getNavigator().noPath()) && (this.state == State.MOVING || this.random.nextInt(50) == 0)) {
                    float entityMoveX = this.moveX * 8.0F;
                    float entityMoveZ = this.moveZ * 8.0F;

                    float centerDistance = (float) Math.abs(entity.getDistance(this.center.x, entity.posY, this.center.z));

                    if (this.fleeing) {
                        centerDistance *= 4.0F;
                    }

                    if (centerDistance > 0) {
                        entityMoveX += (this.center.x - entity.posX) / centerDistance;
                        entityMoveZ += (this.center.z - entity.posZ) / centerDistance;
                    }

                    for (DinosaurEntity other : this) {
                        if (other != entity) {
                           /*TODO:make sure works */ float distance = (float) entity.getDistanceSq(other);

                            float separation = (entity.width * 1.5F) + 1.5F;

                            if (distance < separation) {
                                float scale = distance / separation;
                                entityMoveX += (entity.posX - other.posX) / scale;
                                entityMoveZ += (entity.posZ - other.posZ) / scale;
                            }
                        }
                    }

                    double navigateX = entity.posX + entityMoveX;
                    double navigateZ = entity.posZ + entityMoveZ;

                    Dinosaur dinosaur = entity.getDinosaur();
                    double speed = this.state == State.IDLE ? 0.8 : dinosaur.getFlockSpeed();

                    if (this.fleeing) {
                        if (dinosaur.getAttackSpeed() > speed) {
                            speed = dinosaur.getAttackSpeed();
                        }
                    }

                    if (entity.disableHerdingTicks <= 0 && entity.getAttackTarget() == null && (this.members.size() > 1 || this.fleeing)) {
                        BlockPos navigatePos = entity.world.getHeight(new BlockPos(navigateX, 0, navigateZ)).up();
                        if (entity.getNavigator().getPath() != null && !entity.getNavigator().getPath().isFinished()) {
                            PathPoint finalPoint = entity.getNavigator().getPath().getFinalPathPoint();
                            if (navigatePos.getDistance(finalPoint.x, finalPoint.y, finalPoint.z) < 25) {
                                continue;
                            }
                        }
                        attemptedPath = true;
                        if (entity.getDistanceSqToCenter(navigatePos) > 16 && !entity.isMovementBlocked()) {
                            boolean canMove = entity.getNavigator().tryMoveToXYZ(navigatePos.getX(), navigatePos.getY(), navigatePos.getZ(), speed);
                            if (!canMove) {
                                failedPaths++;
                            }
                        }
                    }
                }
            } else if (!this.fleeing && (entity.getAttackTarget() == null || this.random.nextInt(20) == 0) && this.enemies.size() > 0) {
                if (entity.getAgePercentage() > 50) {
                    int index = this.random.nextInt(this.enemies.size());
                    Iterator<EntityLivingBase> enemyIterator = this.enemies.iterator();
                    for (int i = 0; i < index; i++) {
                        enemyIterator.next();
                    }
                    entity.setAttackTarget(enemyIterator.next());
                }
            }
        }

        if (attemptedPath) {
            if (failedPaths > this.members.size() / 4) {
                this.moveX = -this.moveX + (this.random.nextFloat() - 0.5F) * 0.1F;
                this.moveZ = -this.moveZ + (this.random.nextFloat() - 0.5F) * 0.1F;
                this.failedPathTicks++;
                this.normalizeMovement();
            } else if (this.failedPathTicks > 0) {
                this.failedPathTicks--;
            }
        }

        List<EntityLivingBase> invalidEnemies = new LinkedList<>();

        for (EntityLivingBase enemy : this.enemies) {
            if (enemy.isDead || (enemy instanceof DinosaurEntity && ((DinosaurEntity) enemy).isCarcass()) || (enemy instanceof EntityPlayer && ((EntityPlayer) enemy).capabilities.isCreativeMode) || enemy.getDistanceSq(this.center.x, this.center.y, this.center.z) > 1024 || this.members.contains(enemy)) {
                invalidEnemies.add(enemy);
            }
        }

        this.enemies.removeAll(invalidEnemies);

        if (this.fleeing && this.enemies.size() == 0) {
            this.fleeing = false;
            this.state = State.IDLE;
        }

        if (this.state == State.IDLE) {
            this.moveX = 0.0F;
            this.moveZ = 0.0F;
        } else {
            this.moveX += (this.random.nextFloat() - 0.5F) * 0.1F;
            this.moveZ += (this.random.nextFloat() - 0.5F) * 0.1F;

            this.normalizeMovement();
        }

        this.refreshMembers();
    }
}

public void tick() {
	this.noPhysics = this.getSize() == PurpoidSize.NORMAL && this.restOntoProgress >= 0.6F;
	super.tick();
	this.noPhysics = false;
	Level level = this.level();
	if (level.isClientSide) {
		this.restOntoProgressO = this.restOntoProgress;
		this.prevPull = this.pull;
		Vec3 pos = this.position();
		this.pull = pos.add(this.pull.subtract(pos).normalize().scale(0.25F));

		if ((this.isBoosting() || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_SQUIRT_ATTACK) || this.getStunTimer() > 0) && level.getGameTime() % 4 == 0) {
			double dy = this.pull.y() - pos.y();
			CorrockCrownParticleData particleData = this.createParticleData();
			RandomSource random = this.getRandom();
			for (int i = 0; i < 2; i++) {
				level.addParticle(particleData, this.getRandomX(0.5D), this.getY() + this.getEyeHeight(), this.getRandomZ(0.5D), MathUtil.makeNegativeRandomly(random.nextDouble() * 0.05F, random), dy * random.nextDouble(), MathUtil.makeNegativeRandomly(random.nextDouble() * 0.05F, random));
			}
		}

		if (!this.isDeadOrDying() && (this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_FAST_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM) || this.isPassenger() || this.getStunTimer() > 0) && this.shouldApplyRotationSnaps()) {
			pos = pos.subtract(0.0F, 1.0F, 0.0F);
			this.pull = pos.add(this.pull.subtract(pos).normalize().scale(0.1F));
		} else {
			float restOntoProgressO = this.restOntoProgressO;
			if (restOntoProgressO > 0.0F) {
				Direction restingSide = this.getRestingSide();
				if (restingSide != Direction.DOWN) {
					restOntoProgressO *= restOntoProgressO;
					pos = pos.subtract(restOntoProgressO * restingSide.getStepX(), restOntoProgressO * restingSide.getStepY(), restOntoProgressO * restingSide.getStepZ());
					this.pull = pos.add(this.pull.subtract(pos).normalize().scale(0.1F));
				}
			}
		}

		int animationTick = this.getAnimationTick();
		if ((this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_FAST_TELEPORT_TO)) && animationTick == 7 || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM) && animationTick == 4 || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEFRAG) && animationTick == 2) {
			this.burstParticles();
		}
	} else {
		if (this.isAlive()) {
			if (this.getSize() != PurpoidSize.PURPAZOID) {
				int age = this.growingAge;
				if (age < 0) {
					this.updateAge(++age);
				} else if (age > 0) {
					this.updateAge(--age);
				}

				if (this.despawnTimer > 0 && --this.despawnTimer == 0) {
					level.broadcastEntityEvent(this, (byte) 1);
					this.discard();
					return;
				}
			} else {
				int tickCount = this.tickCount;

				if (tickCount >= 40) {
					var shieldersIterator = this.shielders.iterator();
					int id = this.getId();
					double x = this.getX();
					double z = this.getZ();
					while (shieldersIterator.hasNext()) {
						if (((ServerLevel) level).getEntity(shieldersIterator.next()) instanceof Purpoid purpoid) {
							int shieldedMommyID = purpoid.getIDOfShieldedMommy();
							boolean purpDoesNotShield = shieldedMommyID < 0;
							if ((purpDoesNotShield || shieldedMommyID == id) && purpoid.isAlive() && purpoid.isBaby() && Mth.square(purpoid.getX() - x) + Mth.square(purpoid.getZ() - z) <= 4096.0D) {
								if (purpDoesNotShield) purpoid.setShieldedMommyId(id);
								continue;
							} else {
								purpoid.setShieldedMommyId(-1);
							}
						}
						shieldersIterator.remove();
					}

					int shieldedMommyID = this.getIDOfShieldedMommy();
					if (shieldedMommyID >= 0) {
						Entity shieldedMommy = level.getEntity(shieldedMommyID);
						if (!(shieldedMommy instanceof Purpoid mommy) || !mommy.shielders.contains(this.uuid)) {
							this.setShieldedMommyId(-1);
						}
					}
				}

				if (tickCount % 20 == 0) {
					AABB searchBox = this.getBoundingBox().inflate(32.0F);
					var nearbyRevengeTargets = level.getEntitiesOfClass(LivingEntity.class, searchBox, entity -> TargetingConditions.DEFAULT.test(this, entity) && this.revengeTargets.contains(entity.getUUID()));
					if (!nearbyRevengeTargets.isEmpty()) {
						var nearbyPassivePurps = level.getEntitiesOfClass(Purpoid.class, searchBox, purpoid -> {
							if (!purpoid.isBaby()) return false;
							LivingEntity purpoidTarget = purpoid.getTarget();
							return (purpoidTarget == null || !purpoidTarget.isAlive()) && !purpoid.isResting();
						});
						RandomSource random = this.getRandom();
						for (Purpoid purpoid : nearbyPassivePurps) {
							purpoid.setTarget(nearbyRevengeTargets.get(random.nextInt(nearbyRevengeTargets.size())));
						}
					}
				}
			}
		}

		if (this.wantsToFlee && this.isNoEndimationPlaying() && !this.getTeleportController().isTeleporting()) {
			BlockPos pos = this.blockPosition();
			int purpoidBlockX = pos.getX();
			int purpoidBlockZ = pos.getZ();
			int levelHeight = level.getHeight();
			RandomSource random = this.getRandom();
			EntityDimensions size = this.getDimensions(this.getPose());
			List<BlockPos> possiblePositions = new ArrayList<>();
			BlockPos.MutableBlockPos mutableBlockPos = new BlockPos.MutableBlockPos();
			for (int relX = -16; relX <= 16; relX++) {
				int x = purpoidBlockX + relX;
				double xMiddle = x + 0.5D;
				for (int relZ = -16; relZ <= 16; relZ++) {
					int z = purpoidBlockZ + relZ;
					int heightAtXZ = level.getHeight(Heightmap.Types.MOTION_BLOCKING, x, z);
					if (!Block.canSupportRigidBlock(level, mutableBlockPos.set(x, heightAtXZ - 1, z))) continue;
					double zMiddle = z + 0.5D;
					int minColumnHeight = Math.min(heightAtXZ + 4, levelHeight);
					int y = Math.min(minColumnHeight + 4 + random.nextInt(9), levelHeight);
					while (y >= minColumnHeight) {
						if (level.noCollision(size.makeBoundingBox(xMiddle, y, zMiddle))) {
							possiblePositions.add(new BlockPos(x, y, z));
							break;
						}
						y--;
					}
				}
			}
			if (!possiblePositions.isEmpty()) {
				this.teleportController.beginTeleportation(this, possiblePositions.get(random.nextInt(possiblePositions.size())), false);
				this.wantsToFlee = false;
			} else if (this.tryToTeleportRandomly(0, 24, 32)) {
				this.wantsToFlee = false;
			}
		}

		if (this.hasTeleportCooldown()) this.teleportCooldown--;
		if (this.hasRestCooldown()) this.restCooldown--;

		if (this.isBoosting()) {
			this.setBoostingTicks(this.getBoostingTicks() - 1);
		} else if (!this.isPassenger() && this.hasTeleportCooldown() && !this.isResting() && this.random.nextFloat() <= 0.001F) {
			this.setBoostingTicks(this.random.nextInt(81) + 80);
		}

		int stunTimer = this.getStunTimer();
		if (stunTimer > 0) this.setStunTimer(stunTimer - 1);

		this.teleportController.tick(this);
	}

	BlockPos restingPos = this.getRestingPos();
	if (restingPos != null && !(this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM))) {
		Direction side = this.getRestingSide();
		Direction.Axis axis = side.getAxis();
		double chosenTestingPos = axis.choose(restingPos.getX(), restingPos.getY(), restingPos.getZ());
		if (side.getAxis().getPlane() == Direction.Plane.HORIZONTAL && side.getAxisDirection() == Direction.AxisDirection.POSITIVE) {
			chosenTestingPos += 1.0D;
		}
		this.restOntoProgress = (float) (1.0F - Mth.clamp(Math.abs(chosenTestingPos - axis.choose(this.getX(), this.getY(), this.getZ())) / 3.0D, 0.0D, 1.0D));
	} else if (this.getStunTimer() > 0) {
		this.restOntoProgress = Math.min(this.restOntoProgress + 0.025F, 1.0F);
	} else {
		this.restOntoProgress = Math.max(this.restOntoProgress - 0.025F, 0.0F);
	}

	if (this.isDeadOrDying()) {
		if (!this.isEndimationPlaying(EEPlayableEndimations.PURPOID_DEATH) && !level.isClientSide) {
			NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PURPOID_DEATH);
		}
		if (++this.deathTime >= 20) {
			if (!level.isClientSide) {
				this.discard();
			} else {
				CorrockCrownParticleData particleData = this.createParticleData();
				RandomSource random = this.getRandom();
				for (int i = 0; i < 12; ++i) {
					level.addParticle(particleData, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), MathUtil.makeNegativeRandomly(random.nextFloat() * 0.25F, random), (random.nextFloat() - random.nextFloat()) * 0.3F + 0.1F, MathUtil.makeNegativeRandomly(random.nextFloat() * 0.25F, random));
				}
				for (int i = 0; i < 20; ++i) {
					level.addParticle(ParticleTypes.POOF, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
				}
			}
		}
	}
}

public void tick() {
	super.tick();

	if (this.breedDelay > 0) this.breedDelay--;
	if (this.deflateDelay > 0) this.deflateDelay--;
	if (this.croakDelay > 0) this.croakDelay--;

	if (this.isBoofed()) {
		if (this.hasAggressiveAttackTarget()) {
			this.navigation = this.attackingNavigator;
		} else {
			if (this.navigation instanceof EndergeticFlyingPathNavigator) {
				this.navigation = new FlyingPathNavigation(this, this.level()) {

					@Override
					public boolean isStableDestination(BlockPos pos) {
						return this.level.isEmptyBlock(pos);
					}

				};
			}

			if (this.getBoofloAttackTarget() == null && this.isPathFinding() && this.getDeltaMovement().length() < 0.25F && RayTraceHelper.rayTrace(this, 2.0D, 1.0F).getType() == Type.BLOCK) {
				this.getNavigation().stop();
			}
		}
	}

	if (this.isControlledByLocalInstance() && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_CHARGE) && this.getAnimationTick() >= 15) {
		this.setDeltaMovement(this.getDeltaMovement().multiply(0.9D, 1.0D, 0.9D));
		this.push(0.0F, -0.225F, 0.0F);
	}

	if (!this.level().isClientSide) {
		this.setOnGround(!this.level().noCollision(DetectionHelper.checkOnGround(this.getBoundingBox(), 0.07F)));

		int power = this.getBoostPower();
		if (power > 0 && !this.isBoostExpanding()) {
			this.setBoostPower(Math.max(0, power - (this.onGround() ? 3 : 2)));
			if (this.getBoostPower() <= 0) {
				this.setBoostLocked(false);
			}
		} else if (this.isBoostExpanding()) {
			if (power < MAX_BOOST_POWER) {
				if (this.isBoostLocked()) {
					int incremented = power + BOOST_POWER_INCREMENT;
					this.setBoostPower(Math.min(HALF_BOOST_POWER, incremented));
					if (incremented >= HALF_BOOST_POWER) {
						this.setBoostExpanding(false);
					}
				} else {
					this.setBoostPower(Math.min(MAX_BOOST_POWER, power + BOOST_POWER_INCREMENT));
				}
			} else {
				if (!this.isBoostLocked() && this.getControllingPassenger() instanceof Player) {
					NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_INFLATE);
					this.playSound(this.getInflateSound(), 0.75F, 1.0F);
				}
				this.setBoostExpanding(false);
			}
		}

		if (this.onGround() && !this.isBoofed() && this.isBoostExpanding()) {
			this.setBoostExpanding(false);
			this.setBoostLocked(false);
		}

		/*
		 * Resends data to clients
		 */
		if (this.isBoofed() && !this.onGround()) {
			this.setBoofed(true);
		}

		if (this.isBoofed() && this.isNoEndimationPlaying() && this.isMovingInAir()) {
			if (RayTraceHelper.rayTrace(this, 2.0D, 1.0F).getType() != Type.BLOCK) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SWIM);
			}
		}

		if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SWIM) && this.getAnimationTick() <= 15) {
			this.setMovingInAir(true);
		}

		if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_EAT)) {
			if ((this.getAnimationTick() > 20 && this.getAnimationTick() <= 140)) {
				if (this.getAnimationTick() % 20 == 0) {
					if (this.level() instanceof ServerLevel && this.hasCaughtFruit()) {
						((ServerLevel) this.level()).sendParticles(new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(EEItems.BOLLOOM_FRUIT.get())), this.getX(), this.getY() + (double) this.getBbHeight() / 1.5D, this.getZ(), 10, (double) (this.getBbWidth() / 4.0F), (double) (this.getBbHeight() / 4.0F), (double) (this.getBbWidth() / 4.0F), 0.05D);
					}

					if (this.hasCaughtPuffBug()) {
						this.getPassengers().get(0).hurt(this.level().damageSources().mobAttack(this), 0.0F);
					}

					this.playSound(SoundEvents.GENERIC_EAT, 1.0F, 1.0F);
				}
				if (this.getAnimationTick() == 140) {
					this.setCaughtFruit(false);
					this.heal(5.0F);

					if (this.hasCaughtPuffBug()) {
						this.playSound(SoundEvents.PLAYER_BURP, 1.0F, 0.75F);
						this.getPassengers().get(0).discard();
					}
				}
			}
		}

		if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_HOP)) {
			if (this.getAnimationTick() == 10) {
				this.playSound(this.getHopSound(false), 0.95F, this.getVoicePitch());
				this.shouldPlayLandSound = true;
			}
		}

		if (this.shouldPlayLandSound && this.onGround() && !this.wasOnGround) {
			this.playSound(this.getHopSound(true), 0.95F, this.getVoicePitch());
			this.shouldPlayLandSound = false;
		}
	}

	if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_INFLATE) && this.getAnimationTick() == 2) {
		this.boof(1.0F, 1.0F, false);
	}

	if (!this.level().isClientSide && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_GROWL)) {
		if (this.getAnimationTick() == 10) {
			this.playSound(this.getGrowlSound(), 0.75F, this.getVoicePitch());
		}

		if (this.getAnimationTick() >= 20) {
			for (Player players : this.getNearbyPlayers(0.4F)) {
				if (!this.hasAggressiveAttackTarget()) {
					this.setBoofloAttackTargetId(players.getId());
				}
			}
		}
	}

	if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SLAM) && this.getAnimationTick() == 3) {
		this.boof(1.2F, 2.2F, true);
		this.playSound(this.getSlamSound(), 0.75F, 1.0F);
	}

	if (this.isInWater()) {
		if (!this.isBoofed()) {
			this.setBoofed(true);
		} else if (this.random.nextFloat() < 0.7F && this.isControlledByLocalInstance()) {
			this.push(0.0F, 0.05F, 0.0F);
		}
	}

	if (this.onGround() && this.isBoofed()) {
		if (this.hasAggressiveAttackTarget() && !this.hasCaughtPuffBug()) {
			if (!this.level().isClientSide) {
				if (this.isNoEndimationPlaying()) {
					NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_INFLATE);
				} else if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_CHARGE)) {
					NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SLAM);
				}
			}
		} else {
			if (this.isVehicle() && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_CHARGE)) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SLAM);
			} else {
				if (this.deflateDelay <= 0 && (!this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SLAM) && !this.isInWater())) {
					this.setBoofed(false);
				}
			}
		}
	}

	if (this.getRandom().nextInt(40000) < 10 && !this.hasCaughtFruit() && !this.hasCaughtPuffBug()) {
		this.setHungry(true);
	}

	if (this.level().isClientSide) {
		if (this.isBoofed()) {
			this.OPEN_JAW.setDecrementing(this.getBoofloAttackTarget() == null || this.hasCaughtPuffBug() || (this.hasAggressiveAttackTarget() && !(this.getBoofloAttackTarget() instanceof PuffBug)));

			this.OPEN_JAW.tick();
		}
	}

	this.wasOnGround = this.onGround();

	if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_EAT) && !this.hasCaughtFruit()) {
		this.setYRot(this.yHeadRot = this.yBodyRot = this.getLockedYaw());
	}
}

public void tick() {
    super.tick();
    if (this.isBaby() || this.getEyeHeight() > this.getBbHeight()) {
        this.refreshDimensions();
    }
    if(!isStanding() && this.getBbHeight() >= 2.75F){
        this.refreshDimensions();
    }
    this.prevStandProgress = this.standProgress;
    this.prevSitProgress = this.sitProgress;

    if (this.isSitting()) {
        if (sitProgress < 10F)
            sitProgress++;
    } else {
        if (sitProgress > 0F)
            sitProgress--;
    }

    if (this.isStanding()) {
        if (standProgress < 10F)
            standProgress++;
    } else {
        if (standProgress > 0F)
            standProgress--;
    }

    if(!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))){
        this.setEating(true);
        this.setOrderedToSit(true);
        this.setStanding(false);
    }
    if(recalcSize){
        recalcSize = false;
        this.refreshDimensions();
    }

    if(isEating() && !this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))){
        this.setEating(false);
        eatingTime = 0;
        if(!forcedSit){
            this.setOrderedToSit(true);
        }
    }
    if(isEating()){
        eatingTime++;
        for(int i = 0; i < 3; i++){
            double d2 = this.random.nextGaussian() * 0.02D;
            double d0 = this.random.nextGaussian() * 0.02D;
            double d1 = this.random.nextGaussian() * 0.02D;
            this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
        }
        if(eatingTime % 5 == 0){
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
        }
        if(eatingTime > 100){
            ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
            if(!stack.isEmpty()){
                if(stack.is(AMTagRegistry.GRIZZLY_HONEY)){
                    this.setHoneyed(true);
                    this.heal(10);
                    this.honeyedTime = 700;
                }else{
                    this.heal(4);
                }
                if(stack.is(AMTagRegistry.GRIZZLY_TAMEABLES) && !this.isTame() && this.salmonThrowerID != null){
                   if(getRandom().nextFloat() < 0.3F){
                       this.setTame(true);
                       this.setOwnerUUID(this.salmonThrowerID);
                       Player player = level().getPlayerByUUID(salmonThrowerID);
                       if (player instanceof ServerPlayer) {
                           CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer)player, this);
                       }
                       this.level().broadcastEntityEvent(this, (byte)7);
                   }else{
                       this.level().broadcastEntityEvent(this, (byte)6);
                   }
                }
                if(stack.hasCraftingRemainingItem()){
                    this.spawnAtLocation(stack.getCraftingRemainingItem());
                }
                stack.shrink(1);
            }
            eatingTime = 0;
        }
    }
    if (isStanding() && ++standingTime > maxStandTime) {
        this.setStanding(false);
        standingTime = 0;
        maxStandTime = 75 + random.nextInt(50);
    }
    if (isSitting() && !forcedSit && ++sittingTime > maxSitTime) {
        this.setOrderedToSit(false);
        sittingTime = 0;
        maxSitTime = 75 + random.nextInt(50);
    }
    if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
        maxSitTime = 300 + random.nextInt(250);
        this.setOrderedToSit(true);
    }
    /*
    if(this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && rand.nextInt(1500) == 0){
        maxStandTime = 75 + rand.nextInt(50);
        this.setStanding(true);
    }
     */
    if (!forcedSit && this.isSitting() && (this.getTarget() != null || this.isStanding()) && !this.isEating()) {
        this.setOrderedToSit(false);
    }
    if (this.getAnimation() == NO_ANIMATION && this.getAprilFoolsFlag() < 1 && random.nextInt(isStanding() ? 350 : 2500) == 0) {
        this.setAnimation(ANIMATION_SNIFF);
    }
    if (this.isSitting()) {
        this.getNavigation().stop();
    }
    LivingEntity attackTarget = this.getTarget();
    if(this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player){
        Player rider = (Player)this.getControllingPassenger();
        if(rider.getLastHurtMob() != null && this.distanceTo(rider.getLastHurtMob()) < this.getBbWidth() + 3F && !this.isAlliedTo(rider.getLastHurtMob())){
            UUID preyUUID = rider.getLastHurtMob().getUUID();
            if (!this.getUUID().equals(preyUUID)) {
                attackTarget = rider.getLastHurtMob();
                if (getAnimation() == NO_ANIMATION || getAnimation() == ANIMATION_SNIFF) {
                    EntityGrizzlyBear.this.setAnimation(random.nextBoolean() ? ANIMATION_MAUL : random.nextBoolean() ? ANIMATION_SWIPE_L : ANIMATION_SWIPE_R);
                }
            }
        }
    }
    if (attackTarget != null) {
        if(!this.level().isClientSide){
            this.setSprinting(true);
        }
        if (distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 2.5F) {
            if (this.getAnimation() == ANIMATION_MAUL && this.getAnimationTick() % 5 == 0 && this.getAnimationTick() > 3) {
                doHurtTarget(attackTarget);
            }
            if ((this.getAnimation() == ANIMATION_SWIPE_L) && this.getAnimationTick() == 7) {
                doHurtTarget(attackTarget);
                float rot = getYRot() + 90;
                attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
            }
            if ((this.getAnimation() == ANIMATION_SWIPE_R) && this.getAnimationTick() == 7) {
                doHurtTarget(attackTarget);
                float rot = getYRot() - 90;
                attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
            }

        }
    }else{
        if(!this.level().isClientSide && this.getControllingPassenger() == null){
            this.setSprinting(false);
        }
    }
    if(!this.level().isClientSide && isHoneyed() && --honeyedTime <= 0){
        this.setHoneyed(false);
        honeyedTime = 0;
    }
    if(this.forcedSit && !this.isVehicle() && this.isTame()){
        this.setOrderedToSit(true);
    }
    if(this.isVehicle() && this.isSitting()){
        this.setOrderedToSit(false);
    }
    if (!this.level().isClientSide && this.isAlive() && isTame() && !this.isBaby() && --this.timeUntilNextFur <= 0) {
        this.spawnAtLocation(AMItemRegistry.BEAR_FUR.get());
        this.timeUntilNextFur = this.random.nextInt(24000) + 24000;
    }
    if(snowTimer > 0){
        snowTimer--;
    }
    if (snowTimer == 0 && !this.level().isClientSide) {
        snowTimer = 200 + random.nextInt(400);
        if(this.isSnowy()){
           if(!permSnow){
               if (!this.level().isClientSide || this.getRemainingFireTicks() > 0 || this.isInWaterOrBubble() || !isSnowingAt(level(), this.blockPosition().above())) {
                   this.setSnowy(false);
               }
           }
        }else{
            if (!this.level().isClientSide &&  isSnowingAt(level(), this.blockPosition())) {
                this.setSnowy(true);
            }
        }
    }
    if(this.isFreddy()){
        this.setStanding(true);
        this.standingTime = 0;
        this.maxStandTime = 40;
    }
    AnimationHandler.INSTANCE.updateAnimations(this);
}

    public void travel(@NotNull Vec3 pTravelVector) {
        if (!this.canMove() && !this.isVehicle()) {
            super.travel(pTravelVector.multiply(0, 1, 0));
            return;
        }

        // TODO: add pitch animation
        // TODO: how to use fliesLikeElytra flag
        // TODO: match original speed

        // Player riding controls
        // Note: when motion is handled by the client no server side setDeltaMovement() should be called
        // otherwise the movement will halt
        // Todo: move wrongly fix
        if (allowLocalMotionControl && this.getControllingPassenger() != null && canBeControlledByRider()) {
            LivingEntity rider = (LivingEntity) this.getControllingPassenger();
            if (rider == null) {
                super.travel(pTravelVector);
                return;
            }


//            final int i = rider.getPassengers().indexOf(this);
//            final float radius = (i == 2 ? -0.2F : 0.5F) + (((Player) rider).isFallFlying() ? 2 : 0);
//            final float angle = (0.01745329251F * ((Player) rider).yBodyRot) + (i == 1 ? 90 : i == 0 ? -90 : 0);
//            final double extraX = radius * Mth.sin((float) (Math.PI + angle));
//            final double extraZ = radius * Mth.cos(angle);
//            final double extraY = (rider.isShiftKeyDown() ? 1.2D : 1.4D) + (i == 2 ? 0.4D : 0D);
//            this.yHeadRot = ((Player) rider).yHeadRot;
//            this.setYRot(((Player) rider).yHeadRot);
            this.setYRot(rider.getYRot());
            this.yRotO = this.getYRot();
//            this.yHeadRotO = this.getYRot();
//            this.yBodyRotO = this.getYRot();
            this.setXRot(rider.getXRot() * 0.5F);
            this.setRot(this.getYRot(), this.getXRot());
            this.yBodyRot = this.getYRot();

            this.yHeadRotO = this.yHeadRot;
            this.yHeadRot = this.yBodyRot;

            // Flying control, include flying through waterfalls
            if (isHovering() || isFlying()) {
//                double forward = rider.zza;
                double forward = 1f;
                double strafing = rider.xxa;
                double vertical = 0;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED) * .5f;
                // Bigger difference in speed for young and elder dragons
//                float airSpeedModifier = (float) (5.2f + 1.0f * Mth.map(Math.min(this.getAgeInDays(), 125), 0, 125, 0f, 1.5f));
                float airSpeedModifier = (float) (5.2f + 1.0f * Mth.map(speed, this.minimumSpeed, this.maximumSpeed, 0f, 1.5f));
                // Apply speed mod
                speed *= airSpeedModifier;
                // Set flag for logic and animation
//                if (forward > 0) {
//                    this.setFlying(true);
//                }

                gliding = allowMousePitchControl && rider.isSprinting();
                gliding = true;
                if (!gliding) {
                    // Mouse controlled yaw
                    speed += glidingSpeedBonus * (rider.isSprinting() ? 1.5f : 1.0f);
                    // Slower on going astern
                    forward *= rider.zza > 0 ? 1.0f : 0.5f;
                    // Slower on going sideways
                    strafing *= 0.4f;
                    if (isGoingUp() && !isGoingDown()) {
                        vertical = 1f;
                    } else if (isGoingDown() && !isGoingUp()) {
                        vertical = -1f;
                    }
                    // Damp the vertical motion so the dragon's head is more responsive to the control
                    else if (isControlledByLocalInstance()) {
//                        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.8f, 1.0f));
                    }
                } else {
                    // Mouse controlled yaw and pitch
                    speed *= 1.5f;
                    strafing *= 0.1f;
                    // Diving is faster
                    // Todo: a new and better algorithm much like elytra flying
                    glidingSpeedBonus = (float) Mth.clamp(glidingSpeedBonus + this.getDeltaMovement().y * -0.05d, -0.8d, 1.5d);
                    speed += glidingSpeedBonus;
                    // Try to match the moving vector to the rider's look vector
                    forward = Mth.abs(Mth.cos(this.getXRot() * ((float) Math.PI / 180F)));
                    vertical = Mth.abs(Mth.sin(this.getXRot() * ((float) Math.PI / 180F)));
                    // Pitch is still responsive to spacebar and x key
                    if (isGoingUp() && !isGoingDown()) {
                        vertical = Math.max(vertical, 0.5);
                    } else if (isGoingDown() && !isGoingUp()) {
                        vertical = Math.min(vertical, -0.5);
                    } else if (isGoingUp() && isGoingDown()) {
                        vertical = 0;
                    }
                    // X rotation takes minus on looking upward
                    else if (this.getXRot() < 0) {
                        vertical *= 1;
                    } else if (this.getXRot() > 0) {
                        vertical *= -1;
                    } else if (isControlledByLocalInstance()) {
//                        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0f, 0.8f, 1.0f));
                    }
                }
                // Speed bonus damping
                glidingSpeedBonus -= glidingSpeedBonus * 0.01d;

                if (this.isControlledByLocalInstance()) {
                    // Vanilla friction on Y axis is smaller, which will influence terminal speed for climbing and diving
                    // use same friction coefficient on all axis simplifies how travel vector is computed
                    this.flyingSpeed = speed * 0.1F;
                    this.setSpeed(speed);

                    this.moveRelative(flyingSpeed, new Vec3(strafing, vertical, forward));
                    this.move(MoverType.SELF, this.getDeltaMovement());
                    this.setDeltaMovement(this.getDeltaMovement().multiply(new Vec3(0.9, 0.9, 0.9)));

                    Vec3 currentMotion = this.getDeltaMovement();
                    if (this.horizontalCollision) {
                        currentMotion = new Vec3(currentMotion.x, 0.1D, currentMotion.z);
                    }
                    this.setDeltaMovement(currentMotion);

                    this.calculateEntityAnimation(this, false);
                } else {
                    this.setDeltaMovement(Vec3.ZERO);
                }
                this.tryCheckInsideBlocks();
                return;
            }
            // In water move control, for those that can't swim
            else if (isInWater() || isInLava()) {
                double forward = rider.zza;
                double strafing = rider.xxa;
                double vertical = 0;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);

                if (isGoingUp() && !isGoingDown()) {
                    vertical = 0.5f;
                } else if (isGoingDown() && !isGoingUp()) {
                    vertical = -0.5f;
                }

                this.flyingSpeed = speed;
                // Float in water for those can't swim is done in LivingEntity#aiStep on server side
                // Leave this handled by both side before we have a better solution
                this.setSpeed(speed);
                // Overwrite the zza in setSpeed
                this.setZza((float) forward);
                // Vanilla in water behavior includes float on water and moving very slow
                // in lava behavior includes moving slow and sink
                super.travel(pTravelVector.add(strafing, vertical, forward));

                return;
            }
            // Walking control
            else {
                double forward = rider.zza;
                double strafing = rider.xxa;
                // Inherit y motion for dropping
                double vertical = pTravelVector.y;
                float speed = (float) this.getAttributeValue(Attributes.MOVEMENT_SPEED);

                float groundSpeedModifier = (float) (1.8F * this.getFlightSpeedModifier());
                speed *= groundSpeedModifier;
                // Try to match the original riding speed
                forward *= speed;
                // Faster sprint
                forward *= rider.isSprinting() ? 1.2f : 1.0f;
                // Slower going back
                forward *= rider.zza > 0 ? 1.0f : 0.2f;
                // Slower going sideway
                strafing *= 0.05f;

                if (this.isControlledByLocalInstance()) {
                    this.flyingSpeed = speed * 0.1F;
                    this.setSpeed(speed);

                    // Vanilla walking behavior includes going up steps
                    super.travel(new Vec3(strafing, vertical, forward));
                } else {
                    this.setDeltaMovement(Vec3.ZERO);
                }
                this.tryCheckInsideBlocks();
                return;
            }
        }
        // No rider move control
        else {
            super.travel(pTravelVector);
        }
    }

    public void tick() {
        prevMotionX = getDeltaMovement().x;
        prevMotionY = getDeltaMovement().y;
        prevMotionZ = getDeltaMovement().z;
        prevHoverAnimFrac = hoverAnimFrac;
        prevFlapAnimFrac = flapAnimFrac;

        super.tick();
//        setDead();
        yBodyRot = getYRot();
        if (level().isClientSide()) {
            banking = getBanking();
            prevBanking = getPrevBanking();
        }

        if (spitCooldown > 0) spitCooldown--;
        if (swoopCooldown > 0) swoopCooldown--;
        if (onGroundTimer > 0) onGroundTimer--;
        if (roarAnimation < ROAR_DURATION) roarAnimation++;

        if (getAnimation() == null) AnimationHandler.INSTANCE.sendAnimationMessage(this, NO_ANIMATION);

        if (hasEffect(MobEffects.POISON)) removeEffectNoUpdate(MobEffects.POISON);

//        if (tickCount == 1) {
//            System.out.println("Naga at " + position());
//        }

        if (!level().isClientSide) {
            if (getTarget() != null && targetDistance < 29.5 && movement != EnumNagaMovement.FALLEN && movement != EnumNagaMovement.FALLING) {
                setAttacking(true);
                if (getAnimation() == NO_ANIMATION && swoopCooldown == 0 && random.nextInt(80) == 0 && getY() - getTarget().getY() > 0) {
                    interrupted = false;
//                    System.out.println("Swoop");
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SWOOP_ANIMATION);
                    swoopCooldown = SWOOP_COOLDOWN_MAX;
                }
                else if (getAnimation() == NO_ANIMATION && spitCooldown == 0 && random.nextInt(80) == 0) {
                    interrupted = false;
//                    System.out.println("Spit");
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SPIT_ANIMATION);
                    spitCooldown = SPIT_COOLDOWN_MAX;
                }
            } else {
                setAttacking(false);
            }
        }

        if (movement != EnumNagaMovement.FALLING && movement != EnumNagaMovement.FALLEN) {
            if (getAttacking()) {
                movement = EnumNagaMovement.HOVERING;
                hoverAnim.increaseTimer();

                if (getAnimation() == NO_ANIMATION && !level().isClientSide) {
                    List<Projectile> projectilesNearby = getEntitiesNearby(Projectile.class, 30);
                    for (Projectile a : projectilesNearby) {
                        Vec3 aActualMotion = new Vec3(a.getX() - a.xo, a.getY() - a.yo, a.getZ() - a.zo);
                        if (aActualMotion.length() < 0.1 || a.tickCount <= 1) {
                            continue;
                        }

                        float dot = (float) a.getDeltaMovement().normalize().dot(this.position().subtract(a.position()).normalize());
                        if (dot > 0.96) {
                            Vec3 dodgeVec = a.getDeltaMovement().cross(new Vec3(0, 1, 0)).normalize().scale(1.2);
                            Vec3 newPosLeft = position().add(dodgeVec.scale(2));
                            Vec3 newPosRight = position().add(dodgeVec.scale(-2));
                            Vec3 diffLeft = newPosLeft.subtract(a.position());
                            Vec3 diffRight = newPosRight.subtract(a.position());
                            if (diffRight.dot(a.getDeltaMovement()) > diffLeft.dot(a.getDeltaMovement())) {
                                dodgeVec = dodgeVec.scale(-1);
                            }
                            setDeltaMovement(getDeltaMovement().add(dodgeVec));
                            AnimationHandler.INSTANCE.sendAnimationMessage(this, DODGE_ANIMATION);
                        }
                    }
                }
            }
            else {
                movement = EnumNagaMovement.GLIDING;
                hoverAnim.decreaseTimer();
                flapAnim.decreaseTimer();
            }
        }
        else if (movement == EnumNagaMovement.FALLING) {
            if (onGround() || isInLava() || isInWater()) {
                AnimationHandler.INSTANCE.sendAnimationMessage(this, EntityNaga.LAND_ANIMATION);
                movement = EnumNagaMovement.FALLEN;
                onGroundTimer = GROUND_TIMER_MAX;
                setDeltaMovement(0, getDeltaMovement().y, 0);
                getNavigation().stop();
            }
        }

        if (movement == EnumNagaMovement.FALLEN) {
            if (onGroundTimer <= 0 && getAnimation() == NO_ANIMATION) {
                setAnimationTick(0);
                AnimationHandler.INSTANCE.sendAnimationMessage(this, EntityNaga.GET_UP_ANIMATION);
            }
        }

        if (getAnimation() == SWOOP_ANIMATION && getAnimationTick() < 43) {
            hoverAnim.increaseTimer();
            flapAnim.decreaseTimer();
        }
        else if (getAnimation() == HURT_TO_FALL_ANIMATION) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else if (getAnimation() == LAND_ANIMATION) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else if (getAnimation() == GET_UP_ANIMATION && getAnimationTick() < 26) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else if (movement == EnumNagaMovement.FALLEN) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
            setYRot(yRotO);
            yHeadRot = yHeadRotO;
            setXRot(xRotO);
        }
        else if (movement == EnumNagaMovement.FALLING) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else {
            flapAnim.increaseTimer();
        }

        if (getAnimation() == SPIT_ANIMATION && level().isClientSide && mouthPos != null && !interrupted) {
            if (getAnimationTick() == 33) {
//            System.out.println(mouthPos);
                float explodeSpeed = 2.4f;
                for (int i = 0; i < 25; i++) {
                    Vec3 particlePos = new Vec3(0.25, 0, 0);
                    particlePos = particlePos.yRot((float) (random.nextFloat() * 2 * Math.PI));
                    particlePos = particlePos.xRot((float) (random.nextFloat() * 2 * Math.PI));
                    double value = random.nextFloat() * 0.1f;
                    double life = random.nextFloat() * 10f + 20f;
                    ParticleVanillaCloudExtended.spawnVanillaCloud(level(), particlePos.x + mouthPos[0].x, particlePos.y + mouthPos[0].y, particlePos.z + mouthPos[0].z, particlePos.x * explodeSpeed, particlePos.y * explodeSpeed, particlePos.z * explodeSpeed, 1, 0.25d + value, 0.75d + value, 0.25d + value, 0.6, life);
                }
            }

            if (getAnimationTick() <= 15 && mouthPos != null && !interrupted) {
//            System.out.println(mouthPos);

                int howMany = 4;
                for (int i = 0; i < howMany; i++) {
                    Vec3 particlePos = new Vec3(3, 0, 0);
                    particlePos = particlePos.yRot((float) (random.nextFloat() * 2 * Math.PI));
                    particlePos = particlePos.xRot((float) (random.nextFloat() * 2 * Math.PI));
                    double value = random.nextFloat() * 0.15f;
                    ParticleVanillaCloudExtended.spawnVanillaCloudDestination(level(), particlePos.x + mouthPos[0].x, particlePos.y + mouthPos[0].y, particlePos.z + mouthPos[0].z, 0, 0, 0, 1, 0.25d + value, 0.75d + value, 0.25d + value, 0.9, 15, mouthPos);
                }
            }
        }

        if (getAnimation() == HURT_TO_FALL_ANIMATION && getAnimationTick() == 17) {
            movement = EnumNagaMovement.FALLING;
        }

        if (getAnimation() == GET_UP_ANIMATION && getAnimationTick() == 26) {
            movement = EnumNagaMovement.HOVERING;
        }

        if (level().isClientSide && movement == EnumNagaMovement.HOVERING && flapAnim.getAnimationFraction() >= 0.5) {

            if (shoulderRot > 0.9) hasFlapSoundPlayed = false;

            if (shoulderRot <= 0.7 && !hasFlapSoundPlayed) {
                level().playLocalSound(getX(), getY(), getZ(), MMSounds.ENTITY_NAGA_FLAP_1.get(), SoundSource.HOSTILE, 2, (float) (0.85 + random.nextFloat() * 0.2), false);
                hasFlapSoundPlayed = true;
            }
        }

        hoverAnimFrac = hoverAnim.getAnimationProgressSinSqrt();
        flapAnimFrac = flapAnim.getAnimationProgressSinSqrt();

        if (!this.level().isClientSide && this.level().getDifficulty() == Difficulty.PEACEFUL)
        {
            this.discard() ;
        }

//        setAttacking(true);
//        getNavigator().clearPath();
//        setMotion(new Vector3d(0, 0, 0));
//        setPosition(getPosX(), 10, getPosZ());
//
//        if (getAnimation() == NO_ANIMATION) {
//            AnimationHandler.INSTANCE.sendAnimationMessage(this, TAIL_DEMO_ANIMATION);
//        }
    }

public void onUpdate() {
	super.onUpdate();

	if(this.isAnchored()) {
		this.setSize(1.8F, 1.8F);
	} else {
		this.setSize(1.8F, 0.2F);
	}

	if(this.dataManager.get(BLOW_STATE) != 0 || this.dataManager.get(ROTATING_WAVE_STATE) != 0 || this.dataManager.get(CRAWLING_WAVE_STATE) != 0 || this.dataManager.get(SPIT_STATE) != 0) {
		this.setGlowTicks(20);
	}

	if(!this.world.isRemote) {
		if(this.isActive() && this.isEntityAlive() && this.getAttackTarget() != null) {
			if(this.ticksExisted % 20 == 0) {
				this.updateWispStrengthModifier();
			}

			if(this.ticksExisted % 10 == 0) {
				List<LocationSpiritTree> locations = BetweenlandsWorldStorage.forWorld(this.world).getLocalStorageHandler().getLocalStorages(LocationSpiritTree.class, this.getEntityBoundingBox(), loc -> loc.isInside(this));
				if(!locations.isEmpty()) {
					LocationSpiritTree location = locations.get(0);

					List<BlockPos> wispPositions = new ArrayList<>();

					wispPositions.addAll(location.getNotGeneratedWispPositions());

					if(this.getHealth() < this.getMaxHealth() / 2) {
						wispPositions.addAll(location.getGeneratedWispPositions());
					}

					for(BlockPos wispPosition : wispPositions) {
						if(!location.getGuard().isGuarded(this.world, null, wispPosition) && this.world.getBlockState(wispPosition).getBlock() == BlockRegistry.WISP) {
							location.getGuard().setGuarded(this.world, wispPosition, true);
							this.dataManager.set(LAST_LOCKED_WISP, wispPosition);
							break;
						}
					}
				}
			}
		}

		float strengthModifier = this.getWispStrengthModifier();
		if(strengthModifier <= 1.0F) {
			this.experienceValue = (int) (DEFAULT_XP_DROPPED * strengthModifier);
		} else {
			this.experienceValue = (int) (DEFAULT_XP_DROPPED * (1 + (strengthModifier - 1) * 6));
		}

		IAttributeInstance attackAttribute = this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE);
		attackAttribute.removeModifier(STRENGTH_MULTIPLIER_ATTRIBUTE_UUID);
		attackAttribute.applyModifier(new AttributeModifier(STRENGTH_MULTIPLIER_ATTRIBUTE_UUID, "Wisp strength modifier", strengthModifier - 1.0F, 2));

		if(this.blowTicks > 0) {
			if(this.blowTicks > 20 + this.blowDelay) {
				this.dataManager.set(BLOW_STATE, 3);

				if((this.blowTicks - (21 + this.blowDelay)) % 15 == 0) {
					this.doBlowAttack();
					this.world.setEntityState(this, EVENT_BLOW_ATTACK);
					this.playSound(SoundRegistry.SPIRIT_TREE_FACE_SPIT_ROOT_SPIKES, 1, 0.9F + this.rand.nextFloat() * 0.2F);
				}
			} else {
				if(this.blowTicks > this.blowDelay) {
					this.dataManager.set(BLOW_STATE, 2);
					if(this.blowTicks == this.blowDelay + 1) {
						this.playSound(SoundRegistry.SPIRIT_TREE_FACE_SUCK, 1, 1);
					}
				} else {
					this.dataManager.set(BLOW_STATE, 1);
				}
			}

			if(this.blowTicks > 160 + this.blowDelay) {
				this.dataManager.set(BLOW_STATE, 0);
				this.blowTicks = 0;
			} else {
				this.blowTicks++;
			}
		}

		if(this.rotatingWaveTicks > 0) {
			if(this.rotatingWaveTicks > this.rotatingWaveDelay) {
				this.dataManager.set(ROTATING_WAVE_STATE, 2);

				if((this.rotatingWaveTicks - 1 - this.rotatingWaveDelay) % 3 == 0) {
					for(int i = 0; i < 2; i++) {
						double increment = Math.PI * 2 / 20;

						double a1 = (this.rotatingWaveStart + (this.rotatingWaveTicks - this.rotatingWaveDelay) / 3 * increment) * (i == 0 ? 1 : -1);
						double a2 = (this.rotatingWaveStart + ((this.rotatingWaveTicks - this.rotatingWaveDelay) / 3 + 1) * increment) * (i == 0 ? 1 : -1);

						double start = Math.min(a1, a2);
						double end = Math.max(a1, a2);

						List<BlockPos> blocks = BlockShapeUtils.getRingSegment(this.getAnchor(), start, end, WorldGenSpiritTreeStructure.RADIUS_INNER_CIRLCE + 0.5D, WorldGenSpiritTreeStructure.RADIUS_OUTER_CIRCLE + 0.5D, false, new ArrayList<>());

						List<BlockPos> spawnBlocks = new ArrayList<>();

						for(BlockPos pos : blocks) {
							BlockPos spawnPos = this.getWaveGroundPos(pos, 0);

							if(spawnPos != null) {
								spawnBlocks.add(spawnPos);
							}
						}

						if(!spawnBlocks.isEmpty()) {
							EntitySpikeWave spikeWave = new EntitySpikeWave(this.world);
							spikeWave.delay = 2;
							spikeWave.setAttackDamage(10.0F * this.getWispStrengthModifier());
							for(BlockPos pos : spawnBlocks) {
								spikeWave.addPosition(pos);
							}
							this.world.spawnEntity(spikeWave);
						}
					}
				}
			} else {
				this.dataManager.set(ROTATING_WAVE_STATE, 1);
			}

			if(this.rotatingWaveTicks >= 3 * 20 * 3 + this.rotatingWaveDelay) {
				this.rotatingWaveTicks = 0;
				this.dataManager.set(ROTATING_WAVE_STATE, 0);
			} else {
				this.rotatingWaveTicks++;
			}
		}

		if(this.crawlingWaveTicks > 0) {
			final int ticksPerWave = CRAWLING_WAVE_RANGE / 3 * 4;

			if(this.crawlingWaveTicks > this.crawlingWaveDelay) {
				this.dataManager.set(CRAWLING_WAVE_STATE, 2);

				if(this.getAttackTarget() != null) {
					if((this.crawlingWaveTicks - 1 - this.crawlingWaveDelay) % ticksPerWave == 0) {
						this.crawlingWaveAngle = (float) Math.atan2(this.getAttackTarget().posZ - this.posZ, this.getAttackTarget().posX - this.posX);
					}

					if((this.crawlingWaveTicks - 1 - this.crawlingWaveDelay) % 4 == 0) {
						int dist = WorldGenSpiritTreeStructure.RADIUS_OUTER_CIRCLE + ((this.crawlingWaveTicks - 1 - this.crawlingWaveDelay) / 4 * 3) % CRAWLING_WAVE_RANGE;

						double a1 = this.crawlingWaveAngle - Math.PI / 16;
						double a2 = this.crawlingWaveAngle + Math.PI / 16;

						List<BlockPos> blocks = BlockShapeUtils.getRingSegment(this.getAnchor(), a1, a2, dist, dist + 3, false, new ArrayList<>());

						List<BlockPos> spawnBlocks = new ArrayList<>();

						for(BlockPos pos : blocks) {
							BlockPos spawnPos = this.getWaveGroundPos(pos, 4);

							if(spawnPos != null) {
								spawnBlocks.add(spawnPos);
							}
						}

						if(!spawnBlocks.isEmpty()) {
							EntitySpikeWave spikeWave = new EntitySpikeWave(this.world);
							spikeWave.delay = 2;
							spikeWave.setAttackDamage(10.0F * this.getWispStrengthModifier());
							for(BlockPos pos : spawnBlocks) {
								spikeWave.addPosition(pos);
							}
							this.world.spawnEntity(spikeWave);
						}
					}
				}
			} else {
				this.dataManager.set(CRAWLING_WAVE_STATE, 1);
			}

			if(this.crawlingWaveTicks >= ticksPerWave * 3 + this.crawlingWaveDelay) {
				this.crawlingWaveTicks = 0;
				this.dataManager.set(CRAWLING_WAVE_STATE, 0);
			} else {
				this.crawlingWaveTicks++;
			}
		}
	} else {
		int blowState = this.dataManager.get(BLOW_STATE);
		if(blowState == 2) {
			Vec3d frontCenter = this.getFrontCenter();
			for(int i = 0; i < 4; i++) {
				Random rnd = world.rand;
				float rx = rnd.nextFloat() * 4.0F - 2.0F + this.getFacing().getXOffset() * 4;
				float ry = rnd.nextFloat() * 4.0F - 2.0F + this.getFacing().getYOffset() * 4;
				float rz = rnd.nextFloat() * 4.0F - 2.0F + this.getFacing().getZOffset() * 4;
				Vec3d vec = new Vec3d(rx, ry, rz);
				vec = vec.normalize();
				this.world.spawnParticle(EnumParticleTypes.SMOKE_NORMAL, frontCenter.x + rx, frontCenter.y - 0.75D + ry, frontCenter.z + rz, -vec.x * 0.5F, -vec.y * 0.5F, -vec.z * 0.5F);
			}
		}
	}
}

public void tick() {
    this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());
    prevblockingProgress = blockingProgress;
    prevswordProgress = swordProgress;
    prevTargetPosition = clientTargetPosition;
    Vec3 EndPos = getTargetPosition();
    clientTargetPosition = EndPos;
    floatStrider();
    if (this.getIsBlocking() && blockingProgress < 10F) {
        blockingProgress++;
    }
    if (!this.getIsBlocking() && blockingProgress > 0F) {
        blockingProgress--;
    }
    if (this.getIsSword() && swordProgress < 10F) {
        swordProgress++;
    }
    if (!this.getIsSword() && swordProgress > 0F) {
        swordProgress--;
    }

    if (!this.getPassengers().isEmpty() && this.getPassengers().get(0).isShiftKeyDown() && this.getAnimation() == POKED_ATTACK) {
        this.getPassengers().get(0).setShiftKeyDown(false);
    }


    LivingEntity target = this.getTarget();
    SwingParticles();
    if (this.level().isClientSide) {
        if (this.random.nextInt(24) == 0 && !this.isSilent()) {
            this.level().playLocalSound(this.getX() + 0.5D, this.getY() + 0.5D, this.getZ() + 0.5D, SoundEvents.BLAZE_BURN, this.getSoundSource(), 1.0F + this.random.nextFloat(), this.random.nextFloat() * 0.7F + 0.3F, false);
        }
        if (this.getBossPhase() > 1) {
            int i = this.getCrackiness() == Crackiness.NONE ? 5 : this.getCrackiness() == Crackiness.LOW ? 4 : this.getCrackiness() == Crackiness.MEDIUM ? 3 : 2;
            if (random.nextInt(i) == 0) {
                this.level().addParticle(ModParticle.SOUL_LAVA.get(), this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
            }
        } else {
            for (int i = 0; i < 2; ++i) {
                this.level().addParticle(ParticleTypes.LARGE_SMOKE, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
            }
        }

    } else {
        if (timeWithoutTarget > 0) timeWithoutTarget--;
        if (target != null) {
            timeWithoutTarget = UNARMED_COOLDOWN;
            if (this.getIsShieldBreak()) {
                this.setIsSword(true);
            } else {
                this.setIsBlocking(true);
            }
        }

        if (this.getAnimation() == NO_ANIMATION && timeWithoutTarget <= 0) {
            if (this.getIsBlocking() || this.getIsSword() && target == null) {
                this.setIsSword(false);
                this.setIsBlocking(false);
            }
        }
        if (this.getBossPhase() > 0) {
            this.bossInfo.setColor(BossEvent.BossBarColor.BLUE);
            this.bossInfo.setRenderType(3);
        }
        if (this.getBossPhase() > 1) {
            bossInfo.setDarkenScreen(true);
            if (this.getAnimation() != PHASE_3) {
                this.setIsShieldBreak(true);
            }
        }

        if (this.getIsBlocking() && blockingProgress == 10) {
            if (this.getAnimation() == NO_ANIMATION) {
                setIsShield(true);
            } else if (this.getAnimation() == COUNTER) {
                setIsShield(true);
            } else if (this.getAnimation() == STRIKE) {
                setIsShield(false);
            } else if (this.getAnimation() == POKED_ATTACK) {
                setIsShield(false);
            } else if (this.getAnimation() == BREAK_THE_SHIELD) {
                setIsShield(false);
            } else if (this.getAnimation() == HORIZONTAL_SWING_ATTACK) {
                setIsShield(this.getAnimationTick() > 31);
            } else if (this.getAnimation() == HORIZONTAL_SWING_ATTACK_SOUL) {
                setIsShield(this.getAnimationTick() > 27);
            } else if (this.getAnimation() == BODY_CHECK_ATTACK1 || this.getAnimation() == BODY_CHECK_ATTACK2 ||
                    this.getAnimation() == BODY_CHECK_ATTACK3 || this.getAnimation() == BODY_CHECK_ATTACK4) {
                setIsShield(this.getAnimationTick() < 25);
            } else if (this.getAnimation() == BODY_CHECK_ATTACK_SOUL1 || this.getAnimation() == BODY_CHECK_ATTACK_SOUL2 ||
                    this.getAnimation() == BODY_CHECK_ATTACK_SOUL3 || this.getAnimation() == BODY_CHECK_ATTACK_SOUL4) {
                setIsShield(this.getAnimationTick() < 21);
            } else if (this.getAnimation() == POKE_ATTACK) {
                setIsShield(this.getAnimationTick() < 39);
            } else if (this.getAnimation() == POKE_ATTACK2) {
                setIsShield(this.getAnimationTick() < 34);
            } else if (this.getAnimation() == POKE_ATTACK3) {
                setIsShield(this.getAnimationTick() < 29);
            } else if (this.getAnimation() == SWING_ATTACK) {
                setIsShield(this.getAnimationTick() < 24);
            } else if (this.getAnimation() == SWING_ATTACK_SOUL) {
                setIsShield(this.getAnimationTick() < 18);
            } else if (this.getAnimation() == SWING_ATTACK_BERSERK) {
                setIsShield(this.getAnimationTick() < 15);
            } else if (this.getAnimation() == SWING_UPPERSLASH) {
                setIsShield(this.getAnimationTick() > 27);
            } else if (this.getAnimation() == MAGIC_ATTACK) {
                setIsShield(this.getAnimationTick() > 34 && this.getAnimationTick() < 46);
            } else if (this.getAnimation() == HORIZONTAL_SMALL_SWING_ATTACK) {
                setIsShield(false);
            } else if (this.getAnimation() == HORIZONTAL_SMALL_SWING_ALT_ATTACK2) {
                setIsShield(false);
            } else if (this.getAnimation() == EARTH_SHUDDERS_ATTACK) {
                setIsShield(false);
            } else if (this.getAnimation() == REINFORCED_SMASH_SOUL || this.getAnimation() == REINFORCED_SMASH) {
                setIsShield(this.getAnimationTick() > 6 && this.getAnimationTick() < 19);
            } else if (this.getAnimation() == REINFORCED_SMASH_IN_AIR_SOUL || this.getAnimation() == REINFORCED_SMASH_IN_AIR) {
                setIsShield(false);
            }
        } else {
            setIsShield(false);
        }

    }

    if (body_check_cooldown > 0) body_check_cooldown--;
    if (air_smash_cooldown > 0) air_smash_cooldown--;
    if (counter_strike_cooldown > 0) counter_strike_cooldown--;
    if (poke_cooldown > 0) poke_cooldown--;
    if (earth_shudders_cooldown > 0) earth_shudders_cooldown--;
    if (horizontal_small_swing_cooldown > 0) horizontal_small_swing_cooldown--;
    if (horizontal_swing_cooldown > 0) horizontal_swing_cooldown--;
    if (magic_cooldown > 0) magic_cooldown--;
    if (reinforced_smash_cooldown > 0) reinforced_smash_cooldown--;
    if (sword_dance_cooldown > 0) sword_dance_cooldown--;
    if (ultimate_cooldown > 0) ultimate_cooldown--;
    repelEntities(1.4F, 4, 1.4F, 1.4F);

    Animation animation = getRandomPoke(random);
    if (this.isAlive()) {
        if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getShieldDurability() > 2 && !this.getIsShieldBreak()) {
            this.setAnimation(BREAK_THE_SHIELD);
        } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getHealth() <= this.getMaxHealth() * 2 / 3 && this.getBossPhase() < 1) {
            this.setAnimation(PHASE_2);
        } else if (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.getHealth() <= this.getMaxHealth() * 1 / 3 && this.getBossPhase() < 2) {
            this.setAnimation(PHASE_3);
        } else if (target != null && target.isAlive()) {
            if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) <= 225.0D && ultimate_cooldown <= 0 && this.getBossPhase() > 1) {
                ultimate_cooldown = ULTIMATE_COOLDOWN;
                this.setAnimation(ULTIMATE_ATTACK);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) <= 400.0D && reinforced_smash_cooldown <= 0) {
                reinforced_smash_cooldown = REINFORCED_SMASH_COOLDOWN;
                Animation ranimation = getRandomReinforced(random);
                this.setAnimation(ranimation);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) >= 225 && this.distanceToSqr(target) <= 1024.0D && target.onGround() && air_smash_cooldown <= 0) {
                air_smash_cooldown = AIR_SMASH_COOLDOWN;
                this.setAnimation(SMASH_IN_AIR);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && (this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) >= 81 && this.distanceToSqr(target) <= 625 && magic_cooldown <= 0 && this.getRandom().nextFloat() * 100.0F < 1f)
                    // || (!isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceToSqr(target) >= 25 && this.distanceToSqr(target) <= 81 && magic_cooldown <= 0 && this.getRandom().nextFloat() * 100.0F < 0.6f
                    || (!isNoAi() && (this.getAnimation() == NO_ANIMATION && this.getRandom().nextFloat() * 100.0F < 10f && this.getY() + 5 <= target.getY()) && magic_cooldown <= 0)) {
                magic_cooldown = MAGIC_COOLDOWN;
                this.setAnimation(MAGIC_ATTACK);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 12F && this.distanceTo(target) > 5 && poke_cooldown <= 0 && this.getRandom().nextFloat() * 100.0F < 4f) {
                poke_cooldown = POKE_COOLDOWN;
                this.setAnimation(animation);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 12F && this.getRandom().nextFloat() * 100.0F < 15F && poke_cooldown <= 0 && target.hasEffect(ModEffect.EFFECTSTUN.get())) {
                poke_cooldown = POKE_COOLDOWN;
                this.setAnimation(animation);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 6.5F && this.getRandom().nextFloat() * 100.0F < 4f) {
                Animation animation2 = this.getBossPhase() > 0 ? HORIZONTAL_SWING_ATTACK_SOUL : HORIZONTAL_SWING_ATTACK;
                horizontal_swing_cooldown = HORIZONTAL_SWING_COOLDOWN;
                this.setAnimation(animation2);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 4.25F && this.getRandom().nextFloat() * 100.0F < 8f) {
                Animation animation3 = this.getBossPhase() > 1 ? SWING_ATTACK_BERSERK : this.getBossPhase() > 0 ? SWING_ATTACK_SOUL : SWING_ATTACK;
                this.setAnimation(animation3);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 5.25F && this.getRandom().nextFloat() * 100.0F < 5f && this.getIsShieldBreak() && sword_dance_cooldown <= 0) {
                sword_dance_cooldown = this.getBossPhase() > 1 ? SWORD_DANCE_COOLDOWN : this.getBossPhase() > 0 ? SWORD_DANCE_COOLDOWN + 120 : SWORD_DANCE_COOLDOWN + 240;
                this.setAnimation(COMBO1);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 3F && this.getRandom().nextFloat() * 100.0F < 20f && !this.getIsShieldBreak()) {
                this.setAnimation(SHIELD_SMASH_ATTACK);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 5F && this.getRandom().nextFloat() * 100.0F < 0.7f && counter_strike_cooldown <= 0 && !target.hasEffect(ModEffect.EFFECTSTUN.get())) {
                counter_strike_cooldown = CONTER_STRIKE_COOLDOWN;
                Animation counter = this.getIsShieldBreak() ? SHIELD_BREAK_COUNTER : COUNTER;
                this.setAnimation(counter);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) > 4.5F && this.distanceTo(target) < 11F && earth_shudders_cooldown <= 0 && this.getRandom().nextFloat() * 100.0F < 1F && (this.getY() >= target.getY() - 2.5D && this.getY() <= target.getY() + 2.5D)) {
                earth_shudders_cooldown = EARTH_SHUDDERS_COOLDOWN;
                this.setAnimation(EARTH_SHUDDERS_ATTACK);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 5.5F && this.getRandom().nextFloat() * 100.0F < 15f && horizontal_small_swing_cooldown <= 0) {
                horizontal_small_swing_cooldown = HORIZONTAL_SMALL_SWING_COOLDOWN;
                this.setAnimation(HORIZONTAL_SMALL_SWING_ATTACK);
            } else if ((blockingProgress == 10 || swordProgress == 10) && !isNoAi() && this.getAnimation() == NO_ANIMATION && this.distanceTo(target) < 3F && this.getRandom().nextFloat() * 100.0F < 10f && body_check_cooldown <= 0) {
                body_check_cooldown = BODY_CHECK_COOLDOWN;
                Animation animation5 = this.getBossPhase() > 0 ? BODY_CHECK_ATTACK_SOUL1 : BODY_CHECK_ATTACK1;
                this.setAnimation(animation5);
            }
        }
    }
    blockbreak();

    super.tick();
}

public void onEntityUpdate() {
	this.prevPosX = this.posX;
	this.prevPosY = this.posY;
	this.prevPosZ = this.posZ;

	boolean attached = this.isAttached();

	if(!attached) {
		this.handleWaterMovement();
		this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
	}

	boolean prevAttached = attached;
	attached = this.isAttached();

	if(attached && !prevAttached) {
		this.world.playSound((EntityPlayer)null, this.posX, this.posY, this.posZ, SoundEvents.BLOCK_METAL_STEP, SoundCategory.PLAYERS, 1, 1.5F);
	}

	Entity nextNode;
	Entity prevNode;

	if(!this.world.isRemote) {
		nextNode = this.getNextNodeByUUID();
		prevNode = this.getPreviousNodeByUUID();

		if(nextNode != null && nextNode.getEntityId() != this.cachedNextNodeDW) {
			this.getDataManager().set(DW_NEXT_NODE, nextNode.getEntityId());
			this.cachedNextNodeDW = nextNode.getEntityId();
		} else if(nextNode == null && this.cachedNextNodeDW != -1) {
			this.getDataManager().set(DW_NEXT_NODE, -1);
			this.cachedNextNodeDW = -1;
		}

		if(prevNode != null && prevNode.getEntityId() != this.cachedPrevNodeDW) {
			this.getDataManager().set(DW_PREV_NODE, prevNode.getEntityId());
			this.cachedPrevNodeDW = prevNode.getEntityId();
		} else if(prevNode == null && this.cachedPrevNodeDW != -1) {
			this.getDataManager().set(DW_PREV_NODE, -1);
			this.cachedPrevNodeDW = -1;
		}

		if(this.isEntityAlive()) {
			if(attached) {
				BlockPos pos = this.getPosition();

				if(this.lightBlock != null && (this.lightBlock.getX() != pos.getX() || this.lightBlock.getY() != pos.getY() || this.lightBlock.getZ() != pos.getZ())) {
					if(this.world.isBlockLoaded(this.lightBlock) && this.world.getBlockState(this.lightBlock).getBlock() == BlockRegistry.CAVING_ROPE_LIGHT) {
						this.world.setBlockToAir(this.lightBlock);
					}

					this.lightBlock = null;
				}

				if(this.lightBlock == null) {
					if(this.world.isAirBlock(pos)) {
						this.world.setBlockState(pos, BlockRegistry.CAVING_ROPE_LIGHT.getDefaultState());
						this.lightBlock = pos;
					}
				}
			} else if(this.lightBlock != null) {
				if(this.world.isBlockLoaded(this.lightBlock) && this.world.getBlockState(this.lightBlock).getBlock() == BlockRegistry.CAVING_ROPE_LIGHT) {
					this.world.setBlockToAir(this.lightBlock);
				}

				this.lightBlock = null;
			}
		}
	} else {
		nextNode = this.getNextNode();
		prevNode = this.getPreviousNode();
	}

	if(!this.world.isRemote) {
		if(nextNode instanceof EntityPlayer) {
			if(nextNode.getDistance(this) > 1.5D) {
				this.pickUp = true;
			}
			if(this.pickUp && nextNode.getEntityBoundingBox().grow(0.4D, 0.4D, 0.4D).intersects(this.getEntityBoundingBox())) {
				this.removeNode(nextNode);
				EntityPlayer player = (EntityPlayer) nextNode;
				if(player.inventory.addItemStackToInventory(new ItemStack(ItemRegistry.CAVING_ROPE, 1))) {
					this.world.playSound((EntityPlayer)null, player.posX, player.posY, player.posZ, SoundEvents.ENTITY_ITEM_PICKUP, SoundCategory.PLAYERS, 0.2F, ((this.rand.nextFloat() - this.rand.nextFloat()) * 0.7F + 1.0F) * 2.0F);
				} else {
					EntityItem itemEntity = new EntityItem(this.world, this.posX, this.posY, this.posZ, new ItemStack(ItemRegistry.CAVING_ROPE, 1));
					itemEntity.setPickupDelay(0);
					this.world.spawnEntity(itemEntity);
				}
			}
			if(nextNode.getDistance(this) < ROPE_LENGTH - 1) {
				this.canExtend = true;
			}
			if(this.canExtend && nextNode.getDistance(this) > ROPE_LENGTH + 1) {
				IInventory inventory = ((EntityPlayer)nextNode).inventory;
				int invSize = inventory.getSizeInventory();
				for(int i = 0; i < invSize; ++i) {
					ItemStack stack = inventory.getStackInSlot(i);
					if(!stack.isEmpty() && stack.getItem() == ItemRegistry.CAVING_ROPE) {
						stack.shrink(1);
						inventory.setInventorySlotContents(i, stack.getCount() > 0 ? stack : ItemStack.EMPTY);
						Vec3d connection = this.getConnectionToNext();
						if(connection != null) {
							Vec3d newPos = nextNode.getPositionVector().add(connection.scale(-0.5D)).add(0, 0.1D, 0);
							RayTraceResult result = this.world.rayTraceBlocks(nextNode.getPositionVector(), newPos, false);
							if(result != null && result.typeOfHit == Type.BLOCK && result.hitVec.squareDistanceTo(nextNode.getPositionVector()) < newPos.squareDistanceTo(nextNode.getPositionVector())) {
								newPos = result.hitVec.add(result.hitVec.subtract(this.getPositionVector()).normalize().scale(0.1D));
							}
							EntityRopeNode rope = this.extendRope(nextNode, newPos.x, newPos.y, newPos.z);
							if(rope.isAttached()) {
								this.world.playSound((EntityPlayer)null, this.posX, this.posY, this.posZ, SoundEvents.BLOCK_METAL_STEP, SoundCategory.PLAYERS, 1, 1.5F);
							}
							break;
						}
					}
				}
			}
			if(nextNode.getDistance(this) > ROPE_LENGTH_MAX) {
				if(nextNode instanceof EntityPlayer) {
					((EntityPlayer) nextNode).sendStatusMessage(new TextComponentTranslation("chat.rope.disconnected"), true);
				}
				this.setNextNode(null);
			}
		}
	}

	this.motionY *= 0.88D;
	this.motionX *= 0.88D;
	this.motionZ *= 0.88D;

	if(!attached && !this.onGround && !this.inWater) {
		boolean isFloating = false;

		if(nextNode != null && this.getDistance(nextNode) >= ROPE_LENGTH) {
			Vec3d connection = this.getConnectionToNext();
			if(connection != null) {
				double mx = connection.x * 0.02D;
				double my = connection.y * 0.02D;
				double mz = connection.z * 0.02D;
				double len = Math.sqrt(mx*mx + my*my + mz*mz);
				if(len > 0.5D) {
					mx /= len * 0.5D;
					my /= len * 0.5D;
					mz /= len * 0.5D;
				}
				if(prevNode != null && prevNode.getDistance(this.posX + mx, this.posY + my, this.posZ + mz) < ROPE_LENGTH + 1) {
					this.motionX += mx;
					this.motionZ += mz;
					this.motionY += my;
					isFloating = true;
				}
			}
		}

		if(!isFloating) {
			this.motionY -= 0.28D;
		}

		if(nextNode != null) {
			double mx = this.motionX;
			double my = this.motionY;
			double mz = this.motionZ;
			Vec3d nextPoint = new Vec3d(this.posX + mx, this.posY + my, this.posZ + mz);
			Vec3d tetherPoint = new Vec3d(nextNode.posX, nextNode.posY, nextNode.posZ);
			if(tetherPoint.distanceTo(nextPoint) >= ROPE_LENGTH) {
				Vec3d constrainedPoint = nextPoint.subtract(tetherPoint).normalize();
				constrainedPoint = new Vec3d(
						constrainedPoint.x * ROPE_LENGTH, 
						constrainedPoint.y * ROPE_LENGTH, 
						constrainedPoint.z * ROPE_LENGTH).add(tetherPoint.x, tetherPoint.y, tetherPoint.z);
				Vec3d diff = new Vec3d(this.posX, this.posY, this.posZ).subtract(constrainedPoint);
				this.motionX = -diff.x;
				this.motionY = -diff.y;
				this.motionZ = -diff.z;
			}
		}

		if(prevNode != null) {
			double mx = this.motionX;
			double my = this.motionY;
			double mz = this.motionZ;
			Vec3d nextPoint = new Vec3d(this.posX + mx, this.posY + my, this.posZ + mz);
			Vec3d tetherPoint = new Vec3d(prevNode.posX, prevNode.posY, prevNode.posZ);
			if(tetherPoint.distanceTo(nextPoint) >= ROPE_LENGTH) {
				Vec3d constrainedPoint = nextPoint.subtract(tetherPoint).normalize();
				constrainedPoint = new Vec3d(
						constrainedPoint.x * ROPE_LENGTH, 
						constrainedPoint.y * ROPE_LENGTH, 
						constrainedPoint.z * ROPE_LENGTH).add(tetherPoint.x, tetherPoint.y, tetherPoint.z);
				Vec3d diff = new Vec3d(this.posX, this.posY, this.posZ).subtract(constrainedPoint).scale(0.8D);
				this.motionX = -diff.x;
				this.motionY = -diff.y;
				this.motionZ = -diff.z;
			}
		}

		double speed = Math.sqrt(this.motionX * this.motionX + this.motionY * this.motionY + this.motionZ * this.motionZ);
		this.motionX *= Math.min(speed, 0.05D) / 0.05D;
		this.motionY *= Math.min(speed, 0.05D) / 0.05D;
		this.motionZ *= Math.min(speed, 0.05D) / 0.05D;
	} else {
		this.motionX = 0.0D;
		this.motionY = 0.0D;
		this.motionZ = 0.0D;
	}

	if(!this.world.isRemote) {
		if(nextNode == null) {
			if(prevNode == null) {
				this.onKillCommand();
			} else {
				this.despawnTimer++;
				if(this.despawnTimer >= BetweenlandsConfig.GENERAL.cavingRopeDespawnTime * 20) {
					if(prevNode != null && prevNode instanceof EntityRopeNode) {
						EntityRopeNode prevRopeNode = (EntityRopeNode) prevNode;
						prevRopeNode.setNextNode(null);
						prevRopeNode.despawn(); 
					}
					this.onKillCommand();
				}
			}
		} else {
			this.despawnTimer = 0;
		}
	}
}

public void updateDragonServer() {
    // Update dragon rider
    dragon.updateRider();

    // Update dragon pitch
    dragon.updatePitch(dragon.yo - dragon.getY());

    if (dragon.lookingForRoostAIFlag && dragon.getLastHurtByMob() != null || dragon.isSleeping()) {
        dragon.lookingForRoostAIFlag = false;
    }
    if (IafConfig.doDragonsSleep && !dragon.isSleeping() && !dragon.isTimeToWake() && dragon.getPassengers().isEmpty() && this.dragon.getCommand() != 2) {
        if (dragon.hasHomePosition
            && dragon.getRestrictCenter() != null
            && DragonUtils.isInHomeDimension(dragon)
            && dragon.getDistanceSquared(Vec3.atCenterOf(dragon.getRestrictCenter())) > dragon.getBbWidth() * 10
            && this.dragon.getCommand() != 2 && this.dragon.getCommand() != 1) {
            dragon.lookingForRoostAIFlag = true;
        } else {
            dragon.lookingForRoostAIFlag = false;
            if ((/* Avoid immediately sleeping after killing the target */ dragon.level.getGameTime() - ticksAfterClearingTarget >= 20) && !dragon.isInWater() && dragon.isOnGround() && !dragon.isFlying() && !dragon.isHovering() && dragon.getTarget() == null) {
                dragon.setInSittingPose(true);
            }
        }
    } else {
        dragon.lookingForRoostAIFlag = false;
    }
    if (dragon.isSleeping() && (dragon.isFlying() || dragon.isHovering() || dragon.isInWater() || (dragon.level.canSeeSkyFromBelowWater(dragon.blockPosition()) && dragon.isTimeToWake() && !dragon.isTame() || dragon.isTimeToWake() && dragon.isTame()) || dragon.getTarget() != null || !dragon.getPassengers().isEmpty())) {
        dragon.setInSittingPose(false);
    }
    if (dragon.isOrderedToSit() && dragon.getControllingPassenger() != null) {
        dragon.setOrderedToSit(false);
    }
    if (dragon.blockBreakCounter <= 0) {
        dragon.blockBreakCounter = IafConfig.dragonBreakBlockCooldown;
    }
    dragon.updateBurnTarget();
    if (dragon.isOrderedToSit()) {
        if (dragon.getCommand() != 1 || dragon.getControllingPassenger() != null)
            dragon.setOrderedToSit(false);
    } else {
        if (dragon.getCommand() == 1 && dragon.getControllingPassenger() == null)
            dragon.setOrderedToSit(true);
    }
    if (dragon.isOrderedToSit()) {
        dragon.getNavigation().stop();
    }
    if (dragon.isInLove()) {
        dragon.level.broadcastEntityEvent(dragon, (byte) 18);
    }
    if ((int) dragon.xo == (int) dragon.getX() && (int) dragon.zo == (int) dragon.getZ()) {
        dragon.ticksStill++;
    } else {
        dragon.ticksStill = 0;
    }
    if (dragon.getControllingPassenger() == null && dragon.isTackling() && !dragon.isFlying() && dragon.isOnGround()) {
        dragon.tacklingTicks++;
        if (dragon.tacklingTicks == 40) {
            dragon.tacklingTicks = 0;
            dragon.setTackling(false);
            dragon.setFlying(false);
        }
    }
    if (dragon.getRandom().nextInt(500) == 0 && !dragon.isModelDead() && !dragon.isSleeping()) {
        dragon.roar();
    }
    // In air tackle attack
    if (dragon.isFlying() && dragon.getTarget() != null) {
        if (dragon.airAttack == IafDragonAttacks.Air.TACKLE)
            dragon.setTackling(true);

        if (dragon.isTackling()) {
            if (dragon.getBoundingBox().expandTowards(2.0D, 2.0D, 2.0D).intersects(dragon.getTarget().getBoundingBox())) {
                dragon.usingGroundAttack = true;
                dragon.randomizeAttacks();
                attackTarget(dragon.getTarget(), null, dragon.getDragonStage() * 3);
                dragon.setFlying(false);
                dragon.setHovering(false);
            }
        }
    }

    if (dragon.getControllingPassenger() == null && dragon.isTackling() && (dragon.getTarget() == null || dragon.airAttack != IafDragonAttacks.Air.TACKLE)) {
        dragon.setTackling(false);
        dragon.randomizeAttacks();
    }
    if (dragon.isPassenger()) {
        dragon.setFlying(false);
        dragon.setHovering(false);
        dragon.setInSittingPose(false);
    }
    if (dragon.isFlying() && dragon.tickCount % 40 == 0 || dragon.isFlying() && dragon.isSleeping()) {
        dragon.setInSittingPose(false);
    }
    if (!dragon.canMove()) {
        if (dragon.getTarget() != null) {
            dragon.setTarget(null);
            ticksAfterClearingTarget = dragon.level.getGameTime();
        }
        dragon.getNavigation().stop();
    }
    if (!dragon.isTame()) {
        dragon.updateCheckPlayer();
    }
    if (dragon.isModelDead() && (dragon.isFlying() || dragon.isHovering())) {
        dragon.setFlying(false);
        dragon.setHovering(false);
    }
    if (dragon.getControllingPassenger() == null) {
        if ((dragon.useFlyingPathFinder() || dragon.isHovering()) && dragon.navigatorType != 1) {
            dragon.switchNavigator(1);
        }
    } else {
        if ((dragon.useFlyingPathFinder() || dragon.isHovering()) && dragon.navigatorType != 2) {
            dragon.switchNavigator(2);
        }
    }
    if (dragon.getControllingPassenger() == null && !dragon.useFlyingPathFinder() && !dragon.isHovering() && dragon.navigatorType != 0) {
        dragon.switchNavigator(0);
    }
    // Dragon landing
    if (dragon.getControllingPassenger() == null && !dragon.isOverAir() && dragon.doesWantToLand() && (dragon.isFlying() || dragon.isHovering()) && !dragon.isInWater()) {
        dragon.setFlying(false);
        dragon.setHovering(false);
    }
    if (dragon.isHovering()) {
        if (dragon.isFlying() && dragon.flyTicks > 40) {
            dragon.setHovering(false);
            dragon.setFlying(true);
        }
        dragon.hoverTicks++;
    } else {
        dragon.hoverTicks = 0;
    }
    if (dragon.isHovering() && !dragon.isFlying()) {
        if (dragon.isSleeping()) {
            dragon.setHovering(false);
        }
        // Slowly land the hovering dragon
        if (dragon.getControllingPassenger() == null && dragon.doesWantToLand() && !dragon.isOnGround() && !dragon.isInWater()) {
            dragon.setDeltaMovement(dragon.getDeltaMovement().add(0, -0.25, 0));
        } else {
            if ((dragon.getControllingPassenger() == null || dragon.getControllingPassenger() instanceof EntityDreadQueen) && !dragon.isBeyondHeight()) {
                double up = dragon.isInWater() ? 0.12D : 0.08D;
                dragon.setDeltaMovement(dragon.getDeltaMovement().add(0, up, 0));
            }
            if (dragon.hoverTicks > 40) {
                dragon.setHovering(false);
                dragon.setFlying(true);
                dragon.flyHovering = 0;
                dragon.hoverTicks = 0;
                dragon.flyTicks = 0;
            }
        }
    }
    if (dragon.isSleeping()) {
        dragon.getNavigation().stop();
    }
    if ((dragon.isOnGround() || dragon.isInWater()) && dragon.flyTicks != 0) {
        dragon.flyTicks = 0;
    }
    if (dragon.isAllowedToTriggerFlight() && dragon.isFlying() && dragon.doesWantToLand()) {
        dragon.setFlying(false);
        dragon.setHovering(dragon.isOverAir());
        if (!dragon.isOverAir()) {
            dragon.flyTicks = 0;
            dragon.setFlying(false);
        }
    }
    if (dragon.isFlying()) {
        dragon.flyTicks++;
    }
    if ((dragon.isHovering() || dragon.isFlying()) && dragon.isSleeping()) {
        dragon.setFlying(false);
        dragon.setHovering(false);
    }
    if (!dragon.isFlying() && !dragon.isHovering()) {
        if (dragon.isAllowedToTriggerFlight() || dragon.getY() < dragon.level.getMinBuildHeight()) {
            if (dragon.getRandom().nextInt(dragon.getFlightChancePerTick()) == 0 || dragon.getY() < dragon.level.getMinBuildHeight() || dragon.getTarget() != null && Math.abs(dragon.getTarget().getY() - dragon.getY()) > 5 || dragon.isInWater() && !dragon.isIceInWater()) {
                dragon.setHovering(true);
                dragon.setInSittingPose(false);
                dragon.setOrderedToSit(false);
                dragon.flyHovering = 0;
                dragon.hoverTicks = 0;
                dragon.flyTicks = 0;
            }
        }
    }
    if (dragon.getTarget() != null) {
        if (!DragonUtils.isAlive(dragon.getTarget())) {
            dragon.setTarget(null);
            ticksAfterClearingTarget = dragon.level.getGameTime();
        }
    }
    if (!dragon.isAgingDisabled()) {
        dragon.setAgeInTicks(dragon.getAgeInTicks() + 1);
        if (dragon.getAgeInTicks() % 24000 == 0) {
            dragon.updateAttributes();
            dragon.growDragon(0);
        }
    }
    if (dragon.tickCount % IafConfig.dragonHungerTickRate == 0 && IafConfig.dragonHungerTickRate > 0) {
        if (dragon.getHunger() > 0) {
            dragon.setHunger(dragon.getHunger() - 1);
        }
    }
    if ((dragon.groundAttack == IafDragonAttacks.Ground.FIRE) && dragon.getDragonStage() < 2) {
        dragon.usingGroundAttack = true;
        dragon.randomizeAttacks();
        dragon.playSound(dragon.getBabyFireSound(), 1, 1);
    }
    if (dragon.isBreathingFire()) {
        if(dragon.isSleeping() || dragon.isModelDead()){
            dragon.setBreathingFire(false);
            dragon.randomizeAttacks();
            dragon.fireTicks = 0;
        }
        if (dragon.burningTarget == null) {
            if (dragon.fireTicks > dragon.getDragonStage() * 25 || dragon.getOwner() != null && dragon.getPassengers().contains(dragon.getOwner()) && dragon.fireStopTicks <= 0) {
                dragon.setBreathingFire(false);
                dragon.randomizeAttacks();
                dragon.fireTicks = 0;
            }
        }

        if (dragon.fireStopTicks > 0 && dragon.getOwner() != null && dragon.getPassengers().contains(dragon.getOwner())) {
            dragon.fireStopTicks--;
        }
    }
    if (dragon.isFlying()) {
        if (dragon.getTarget() != null && dragon.getBoundingBox().expandTowards(3.0F, 3.0F, 3.0F).intersects(dragon.getTarget().getBoundingBox())) {
            dragon.doHurtTarget(dragon.getTarget());
        }
        if (dragon.airAttack == IafDragonAttacks.Air.TACKLE && (dragon.horizontalCollision || dragon.isOnGround())) {
            dragon.usingGroundAttack = true;
            if (dragon.getControllingPassenger() == null) {
                dragon.setFlying(false);
                dragon.setHovering(false);
            }
        }
        if (dragon.usingGroundAttack) {
            dragon.airAttack = IafDragonAttacks.Air.TACKLE;
        }
        if (dragon.airAttack == IafDragonAttacks.Air.TACKLE && dragon.getTarget() != null && dragon.isTargetBlocked(dragon.getTarget().position())) {
            dragon.randomizeAttacks();
        }
    }

}

public void onUpdate() {
	super.onUpdate();

	Iterator<Object2IntMap.Entry<Entity>> cooldownIt = this.deflectionDamageCooldowns.object2IntEntrySet().iterator();
	while(cooldownIt.hasNext()) {
		Object2IntMap.Entry<Entity> entry = cooldownIt.next();

		if(entry.getIntValue() > 0) {
			this.deflectionDamageCooldowns.put(entry.getKey(), entry.getIntValue() - 1);
		} else {
			cooldownIt.remove();
		}
	}

	EntityPlayer closestPlayer = this.world.getNearestAttackablePlayer(this, 32.0D, 16.0D);
	if(closestPlayer != null) {
		this.faceEntity(closestPlayer, 360.0F, 360.0F);
		this.setAttackTarget(closestPlayer);
	}

	this.lastShieldRotationYaw = this.shieldRotationYaw;
	this.lastShieldRotationPitch = this.shieldRotationPitch;
	this.lastShieldRotationRoll = this.shieldRotationRoll;

	this.lastShieldExplosion = this.shieldExplosion;
	if(this.isEntityAlive()) {
		this.shieldExplosion = 0.2F;
	} else {
		this.shieldExplosion = 0.2F + (this.deathTicks % 16) / 16.0F * (this.deathTicks / 60.0F);
	}

	float shieldRotation = 0.0F;
	if(this.world.isRemote) {
		shieldRotation = this.getDataManager().get(SHIELD_ROTATION);
		this.anchor = this.getDataManager().get(ANCHOR);
		this.anchorRadius = this.getDataManager().get(ANCHOR_RADIUS);
		this.shield.unpackActiveData(this.getDataManager().get(SHIELD_STATE));
	} else {
		if(this.isEntityAlive()) {
			shieldRotation = this.ticksExisted;
			this.getDataManager().set(SHIELD_ROTATION, shieldRotation + 1);
		}
		this.getDataManager().set(ANCHOR, this.anchor);
		this.getDataManager().set(ANCHOR_RADIUS, (float) this.anchorRadius);
	}
	int activeShields = 0;
	for(int i = 0; i <= 19; i++) {
		if(this.shield.isActive(i))
			activeShields++;
	}
	if(this.isEntityAlive()) {
		this.shieldRotationYaw = shieldRotation * (1.0F + 6.0F / 20.0F * (20-activeShields));
		this.shieldRotationPitch = shieldRotation * (1.4F + 8.0F / 20.0F * (20-activeShields));
		this.shieldRotationRoll = shieldRotation * (1.6F + 10.0F / 20.0F * (20-activeShields));
	} else {
		this.shieldRotationYaw = shieldRotation * 2.0F;
		this.shieldRotationPitch = 0;
		this.shieldRotationRoll = 0;
	}

	if(this.isEntityAlive()) {
		final Vec3d anchorCenter = this.getAnchorCenter();

		if(!this.world.isRemote) {
			if(this.isFloating() && this.posY < anchorCenter.y) {
				this.motionY = 0.1F;
			} else if(!this.isFloating()) {
				this.motionY += -0.1F;
				this.groundTicks++;
				if(this.groundTicks > 180 && this.groundAttackTicks > 20) {
					this.groundTicks = 0;
					this.setFloating(true);
				}
			}

			if(this.isFloating() && (this.getDistance(anchorCenter.x, this.posY, anchorCenter.z) > this.anchorRadius || Math.abs(this.posY - anchorCenter.y) > this.anchorRadius)) {
				this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_TELEPORT, SoundCategory.HOSTILE, 1.0F, 1.0F);
				this.setPosition(anchorCenter.x, anchorCenter.y, anchorCenter.z);
			}

			//Heal when no player is nearby
			if(this.ticksExisted % 12 == 0 && this.getHealth() < this.getMaxHealth()) {
				List<EntityLivingBase> currentlyTrackedEntities = this.world.getEntitiesWithinAABB(EntityPlayer.class, this.getEntityBoundingBox().grow(this.anchorRadius*2, this.anchorRadius*2, this.anchorRadius*2));
				Iterator<EntityLivingBase> it = currentlyTrackedEntities.iterator();
				while(it.hasNext()) {
					EntityLivingBase living = it.next();
					if(living.getDistance(anchorCenter.x, living.posY, anchorCenter.z) > this.anchorRadius + 4 || Math.abs(living.posY - anchorCenter.y) > this.anchorRadius)
						it.remove();
				}
				if(currentlyTrackedEntities.isEmpty()) {
					this.heal(1);
				}
			}
		}

		AxisAlignedBB checkArea = this.getEntityBoundingBox().grow(32, 16, 32);
		List<EntityPlayer> players = this.world.getEntitiesWithinAABB(EntityPlayer.class, checkArea);
		if(!players.isEmpty()) {
			if(!this.world.isRemote) {
				this.getDataManager().set(SHIELD_STATE, this.shield.packActiveData());

				if(this.isFloating() && this.posY >= anchorCenter.y) {
					AxisAlignedBB checkAABB = this.getEntityBoundingBox().grow(16, 16, 16);
					List<EntityWight> wights = this.world.getEntitiesWithinAABB(EntityWight.class, checkAABB);
					List<EntityFortressBossSpawner> spawners = this.world.getEntitiesWithinAABB(EntityFortressBossSpawner.class, checkAABB);
					if(wights.isEmpty() && spawners.isEmpty()) {
						this.wightSpawnTicks--;
						if(this.wightSpawnTicks <= 0) {
							if(this.wightSpawnTicks == 0) {
								int spawnY = this.world.getHeight(this.getPosition()).getY();
								if(Math.abs(spawnY - this.posY) < this.anchorRadius) {
									EntityFortressBossSpawner spawner = new EntityFortressBossSpawner(this.world, this);
									spawner.setLocationAndAngles(MathHelper.floor(this.posX), spawnY, MathHelper.floor(this.posZ), 0, 0);
									spawner.setOwner(this);
									this.world.spawnEntity(spawner);
								}
							}
							this.wightSpawnTicks = 160 + this.world.rand.nextInt(200);
						}
					}


					List<EntityFortressBossBlockade> blockades = this.world.getEntitiesWithinAABB(EntityFortressBossBlockade.class, checkAABB);
					if(blockades.isEmpty()) {
						this.blockadeSpawnTicks--;
						if(this.blockadeSpawnTicks <= 0) {
							if(this.blockadeSpawnTicks == 0) {
								int spawnY = this.world.getHeight(this.getPosition()).getY();
								if(Math.abs(spawnY - this.posY) < this.anchorRadius) {
									EntityFortressBossBlockade blockade = new EntityFortressBossBlockade(this.world, this);
									blockade.setLocationAndAngles(this.posX, spawnY, this.posZ, 0, 0);
									blockade.setTriangleSize(1.2F + this.world.rand.nextFloat() * 1.6F);
									blockade.setOwner(this);
									blockade.setMaxDespawnTicks(400);
									this.world.spawnEntity(blockade);
								}
							}
							this.blockadeSpawnTicks = 190 + this.world.rand.nextInt(160);
						}
					}

					this.teleportTicks--;
					if(this.teleportTicks <= 0) {
						if(this.teleportTicks == 0) {
							this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_TELEPORT, SoundCategory.HOSTILE, 1.0F, 1.0F);
							this.setLocationAndAngles(anchorCenter.x + (this.world.rand.nextFloat()-0.5F)*2.0F*(this.anchorRadius-1), anchorCenter.y, anchorCenter.z + (this.world.rand.nextFloat()-0.5F)*2.0F*(this.anchorRadius-1), 0, 0);
						}
						this.teleportTicks = 140 + this.world.rand.nextInt(200);
					}

					if(this.turretStreak <= 0 && this.getHealth() < this.getMaxHealth() / 2.0F){
						if(this.turretStreak == 0) {
							this.turretStreakTicks++;
							int turretFrequency = MathHelper.floor(15.0D - 14.0D / 300.0D * this.turretStreakTicks);
							if(this.turretStreakTicks % turretFrequency == 0) {
								double angle = Math.PI * 2.0D / 150.0D * this.turretStreakTicks;
								for(int d = 0; d < 2; d++) {
									Vec3d dir = new Vec3d(Math.sin(angle) * (d == 0 ? 1 : -1), 0, Math.cos(angle) * (d == 0 ? 1 : -1));
									dir = dir.normalize().scale(this.anchorRadius);
									EntityFortressBossTurret turret = new EntityFortressBossTurret(this.world, this);
									turret.setLocationAndAngles(anchorCenter.x + dir.x, anchorCenter.y + dir.y, anchorCenter.z + dir.z, 0, 0);
									turret.setAttackDelay(turretFrequency);
									this.world.spawnEntity(turret);
									this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_SUMMON_PROJECTILES, SoundCategory.HOSTILE, 0.25F, 0.3F + 0.7F / 300.0F * this.turretStreakTicks);
								}
							}
							if(this.turretStreakTicks >= 300) {
								double angle = Math.PI * 2.0D / 32.0D;
								for(int i = 0; i < 32; i++) {
									Vec3d dir = new Vec3d(Math.sin(angle * i), 0, Math.cos(angle * i));
									dir = dir.normalize().scale(this.anchorRadius);
									EntityFortressBossTurret turret = new EntityFortressBossTurret(this.world, this);
									turret.setLocationAndAngles(anchorCenter.x + dir.x, anchorCenter.y + dir.y, anchorCenter.z + dir.z, 0, 0);
									turret.setAttackDelay(5 + i / 3);
									this.world.spawnEntity(turret);
								}
								this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_SUMMON_PROJECTILES, SoundCategory.HOSTILE, 1.0F, 1.0F);
								this.turretStreakTicks = 0;
								this.turretStreak = -1;
							}
						}
						if(this.turretStreak < 0) {
							this.turretStreak = 250 + this.world.rand.nextInt(200);
							this.turretStreakTicks = 0;
						}
					} else {
						if(this.turretTicks <= 0) {
							if(this.turretTicks == 0) {
								double angle = Math.PI * 2.0D / 9;
								for(int i = 0; i < 9; i++) {
									if(this.world.rand.nextInt(3) == 0) {
										Vec3d dir = new Vec3d(Math.sin(angle * i), 0, Math.cos(angle * i));
										dir = dir.normalize().scale(8.0D);
										EntityFortressBossTurret turret = new EntityFortressBossTurret(this.world, this);
										turret.setLocationAndAngles(anchorCenter.x + dir.x, anchorCenter.y + dir.y, anchorCenter.z + dir.z, 0, 0);
										turret.setDeflectable(this.world.rand.nextInt(2) != 0);
										this.world.spawnEntity(turret);
									}
								}
								this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_SUMMON_PROJECTILES, SoundCategory.HOSTILE, 1.0F, 1.0F);
							}
							this.turretTicks = 100 + this.world.rand.nextInt(200);
						} else {
							this.turretTicks--;
							if(this.turretStreak > 0)
								this.turretStreak--;
						}
					}
				}

				if(!this.isFloating() && this.onGround) {
					if(this.groundAttackTicks <= 0) {
						if(this.groundAttackTicks == 0) {
							double angle = Math.PI * 2.0D / 32;
							for(int i = 0; i < 32; i++) {
								Vec3d dir = new Vec3d(Math.sin(angle * i), 0, Math.cos(angle * i));
								dir = dir.normalize();
								float speed = 0.8F;
								EntityFortressBossProjectile bullet = new EntityFortressBossProjectile(this.world, this);
								bullet.setLocationAndAngles(this.posX, this.posY + 0.5D, this.posZ, 0, 0);
								bullet.shoot(dir.x, dir.y, dir.z, speed, 0.0F);
								this.world.spawnEntity(bullet);
							}
						}
						this.groundAttackTicks = 40 + this.world.rand.nextInt(80);
						this.getDataManager().set(GROUND_ATTACK_STATE, false);
						this.turretStreak = -1;
						this.turretTicks = -1;
					} else {
						this.groundAttackTicks--;
						if(this.groundAttackTicks <= 20) {
							this.getDataManager().set(GROUND_ATTACK_STATE, true);
						}
					}
				} else {
					this.getDataManager().set(GROUND_ATTACK_STATE, false);
				}
			} else {
				for(int i = 0; i <= 19; i++) {
					if(this.shield.getAnimationTicks(i) == 0 && this.world.rand.nextInt(50) == 0)
						this.shield.setAnimationTicks(i, 40);
					if(this.shield.getAnimationTicks(i) > 0) {
						this.shield.setAnimationTicks(i, this.shield.getAnimationTicks(i) - 1);
						if(this.shield.getAnimationTicks(i) == 20)
							this.shield.setAnimationTicks(i, 0);
					}
				}
				if(this.getDataManager().get(GROUND_ATTACK_STATE)) {
					if(this.groundAttackTicks < 20)
						this.groundAttackTicks++;
				} else {
					this.groundAttackTicks = 0;
				}
			}
		}
	} else {
		this.setFloating(true);
	}
}

public void tick() {
	if (this.stuckInBlock) {
		this.setDeltaMovement(Vec3.ZERO);
	}

	if (this.getVehicle() instanceof Booflo) {
		this.disableProjectile();
		this.removeLaunchDirection();
		this.setInflated(true);
	}

	super.tick();
	this.getRotationController().tick();
	this.keepEffectsAbsorbed();

	this.fallDistance = 0;

	Vec3 motion = this.getDeltaMovement();

	if (!this.level().isClientSide) {
		if (this.teleportCooldown > 0) {
			this.teleportCooldown--;
		}

		if (this.puffCooldown > 0) {
			this.puffCooldown--;
		}

		if (!this.isPassenger() && this.isInflated() && !this.getRotationController().rotating && this.isNoEndimationPlaying()) {
			if (this.isBoosting() && RayTraceHelper.rayTrace(this, 2.0D, 1.0F).getType() != Type.BLOCK || ((this.onGround() || this.isInWater()) && this.puffCooldown <= 0 && this.getPollinationPos() == null && this.getLaunchDirection() == null && this.getFireDirection() == null)) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PUFF_BUG_PUFF);
				this.playSound(this.getPuffSound(), 0.15F, this.getVoicePitch());
			}
		}

		if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_TO) && this.getAnimationTick() == 10 && !this.getTeleportController().hasNoDestination()) {
			this.getTeleportController().bringToDestination();
		} else if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_FROM)) {
			this.setDeltaMovement(Vec3.ZERO);
		}

		if (this.getHivePos() == null) {
			if (this.level().getGameTime() % 5 == 0 && this.getRandom().nextFloat() <= 0.1F) {
				PuffBugHiveTileEntity hive = this.findNewNearbyHive();
				if (hive != null) {
					this.addToHive(hive);
					if (this.isNoEndimationPlaying()) {
						NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PUFF_BUG_CLAIM_HIVE);
					}
				}
			}
			this.ticksAwayFromHive = 0;
		} else {
			if (this.getHive() == null) {
				this.setHivePos(null);
			} else {
				if (this.getAttachedHiveSide() == Direction.UP) {
					this.ticksAwayFromHive++;

					if (this.ticksAwayFromHive < 1500) {
						if (this.getTarget() == null && this.getRandom().nextInt(7500) == 0 && !this.isInLove() && !this.getHive().isHiveFull()) {
							for (PuffBug nearbyHiveMembers : this.level().getEntitiesOfClass(PuffBug.class, this.getBoundingBox().inflate(9.0F), puffbug -> (puffbug.getHive() != null && puffbug.getHive() == this.getHive()) && this.distanceTo(puffbug) < 12.0F)) {

								this.setInLoveTime(1000);
								this.level().broadcastEntityEvent(this, (byte) 18);

								nearbyHiveMembers.setInLoveTime(1000);
								this.level().broadcastEntityEvent(nearbyHiveMembers, (byte) 18);

								if (this.isInLove() || nearbyHiveMembers.isInLove()) break;
							}
						}
					}
				} else {
					this.ticksAwayFromHive = 0;
				}
			}
		}

		if (this.getAttachedHiveSide() != Direction.UP) {
			this.setInflated(false);
		} else if (!this.isInflated() && this.getFireDirection() == null) {
			this.setInflated(true);
		}

		if (this.getTarget() != null && !CAN_ANGER.test(this.getTarget())) {
			this.setTarget(null);
		}

		if (this.isProjectile() && (this.updateFluidHeightAndDoFluidPushing(FluidTags.WATER, 1.0F) || this.updateFluidHeightAndDoFluidPushing(FluidTags.LAVA, 1.0F))) {
			this.disableProjectile();
		}
	} else {
		this.prevSpin = this.spin;
		RandomSource rand = this.getRandom();

		if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_PUFF) && this.getAnimationTick() == 5) {
			for (int i = 0; i < 3; i++) {
				double offsetX = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);
				double offsetZ = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);

				double x = this.getX() + offsetX;
				double y = this.getY() + (rand.nextFloat() * 0.05F) + 0.7F;
				double z = this.getZ() + offsetZ;

				this.level().addParticle(EEParticleTypes.SHORT_POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.1F), rand) + 0.05F, (rand.nextFloat() * 0.05F) + 0.025F, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.1F), rand) + 0.05F);
			}
		} else if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_TO) && this.getAnimationTick() == 8) {
			for (int i = 0; i < 6; i++) {
				double offsetX = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);
				double offsetZ = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);

				double x = this.getX() + offsetX;
				double y = this.getY() + (rand.nextFloat() * 0.05F) + 0.7F;
				double z = this.getZ() + offsetZ;

				this.level().addParticle(EEParticleTypes.SHORT_POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F, (rand.nextFloat() * 0.025F) + 0.025F, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F);
			}
		} else if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_FROM) && this.getAnimationTick() == 5) {
			for (int i = 0; i < 6; i++) {
				double offsetX = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);
				double offsetZ = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);

				double x = this.getX() + offsetX;
				double y = this.getY() + (rand.nextFloat() * 0.05F) + 0.7F;
				double z = this.getZ() + offsetZ;

				this.level().addParticle(EEParticleTypes.SHORT_POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F, (rand.nextFloat() * 0.025F) + 0.025F, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F);
			}
		}

		this.HIVE_LANDING.tick();
		this.HIVE_SLEEP.tick();

		this.HIVE_LANDING.setDecrementing(this.getAttachedHiveSide() == Direction.UP);

		if (this.HIVE_LANDING.isMaxed()) {
			if (this.HIVE_SLEEP.isDecrementing() && this.HIVE_SLEEP.getTick() == 0) {
				this.HIVE_SLEEP.setDecrementing(false);
			} else if (this.HIVE_SLEEP.isMaxed()) {
				this.HIVE_SLEEP.setDecrementing(true);
			}
		} else {
			this.HIVE_SLEEP.setDecrementing(true);
		}

		if (this.isProjectile() && this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_FLY)) {
			this.spin = this.spin + 55.0F;
		} else {
			this.spin = 0.0F;
		}
	}

	if (this.getDesiredHiveSide() != null) {
		if (this.getHive() != null && this.getDesiredHiveSide() != Direction.DOWN) {
			float degrees = (this.getDesiredHiveSide() == Direction.SOUTH ? 0 : this.getDesiredHiveSide().getAxisDirection().getStep()) * (this.getDesiredHiveSide().getAxis() == Axis.Z ? 180.0F : -90.0F);
			this.setYRot(this.yRotO = degrees);
			this.yHeadRot = this.yHeadRotO = degrees;
			this.yBodyRot = this.yBodyRotO = degrees;
		}
	}

	if (this.getAttachedHiveSide() != Direction.UP) {
		if (this.getHive() != null) {
			this.setDeltaMovement(this.getDeltaMovement().multiply(1.0F, 0.0F, 1.0F));
			this.getNavigation().stop();
			this.setSpeed(0.0F);

			this.push(0.0F, 0.0025F, 0.0F);

			this.setYRot(this.yRotO);
			this.yHeadRot = this.yHeadRotO;
			this.yBodyRot = this.yBodyRotO;

			if (!this.level().isClientSide && !this.isAtCorrectRestLocation(this.getAttachedHiveSide())) {
				this.setAttachedHiveSide(Direction.UP);
			}
		} else {
			if (!this.level().isClientSide) {
				this.setAttachedHiveSide(Direction.UP);
			}
		}
	} else {
		if ((this.getLaunchDirection() != null || this.getFireDirection() != null)) {
			this.setYRot(0.0F);
			this.yHeadRot = 0.0F;
			this.yBodyRot = 0.0F;

			Vec3 fireDirection = this.getFireDirection();

			if (fireDirection != null) {
				if ((this.level().isClientSide && !this.stuckInBlock) || !this.level().isClientSide) {
					this.getRotationController().rotate((float) Mth.wrapDegrees(fireDirection.y() - this.getYRot()), (float) fireDirection.x() + 90.0F, 0.0F, 5);
				}

				LivingEntity target = this.getTarget();

				if (!this.stuckInBlock) {
					if (!this.level().isClientSide && target != null && this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_FLY)) {
						float seekOffset = target.getY() > this.getY() ? 0.0F : 0.5F;
						Vec3 targetVecNoScale = new Vec3(target.getX() - this.getX(), target.getY() - seekOffset - this.getY(), target.getZ() - this.getZ());
						Vec3 targetVec = targetVecNoScale.scale(SEEKING_FACTOR);

						double motionLength = motion.length();
						double targetVecLength = targetVec.length();

						float totalVecLength = Mth.sqrt((float) (motionLength * motionLength + targetVecLength * targetVecLength));

						Vec3 newMotion = motion.scale(motionLength / totalVecLength).add(targetVec.scale(targetVecLength / totalVecLength));

						float gravityCompensator = totalVecLength <= 4.0F ? 0.05F : 0.1F;

						this.setDeltaMovement(newMotion.scale(0.4F).add(0.0F, gravityCompensator, 0.0F));
					}

					Vec3 newestMotion = this.getDeltaMovement();

					float pitch = -((float) (Mth.atan2(newestMotion.y(), Mth.sqrt((float) (newestMotion.x() * newestMotion.x() + newestMotion.z() * newestMotion.z()))) * (double) (180F / (float) Math.PI)));
					float yaw = (float) (Mth.atan2(newestMotion.z(), newestMotion.x()) * (double) (180F / (float) Math.PI)) - 90F;

					this.setFireDirection(pitch, yaw);
				}
			}
		}
	}

	if (this.isProjectile() && !this.isInflated()) {
		BlockPos blockpos = this.blockPosition();
		BlockState blockstate = this.level().getBlockState(blockpos);
		if (!blockstate.isAir() && !this.noPhysics) {
			VoxelShape voxelshape = blockstate.getCollisionShape(this.level(), blockpos);
			if (!voxelshape.isEmpty()) {
				for (AABB axisalignedbb : voxelshape.toAabbs()) {
					if (axisalignedbb.move(blockpos).contains(this.position())) {
						this.stuckInBlock = true;
						break;
					}
				}
			}
		}

		if (this.stuckInBlock && !this.noPhysics) {
			if (!this.level().isClientSide && this.stuckInBlockState != blockstate && this.level().noCollision(this.getBoundingBox().inflate(0.06D))) {
				this.disableProjectile();
			}
			this.setDeltaMovement(this.getDeltaMovement().multiply(0.0F, 1.0F, 0.0F));
		} else {
			Vec3 positionVec = new Vec3(this.getX(), this.getY(), this.getZ());
			Vec3 endVec = positionVec.add(motion);

			HitResult traceResult = this.level().clip(new ClipContext(positionVec, endVec, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
			EntityHitResult entityTraceResult = this.traceEntity(positionVec, endVec);

			if (entityTraceResult != null) {
				traceResult = entityTraceResult;
			}

			if (traceResult.getType() != Type.MISS) {
				this.onSting(traceResult);
				this.hasImpulse = true;
			}
		}
	}
}

    public static void LivingEffects(LivingEvent.LivingTickEvent event){
        LivingEntity livingEntity = event.getEntity();
        if (livingEntity != null && livingEntity.isAlive()){
            if (!MobUtil.isSpellCasting(livingEntity)){
                if (MiscCapHelper.getClientTargetID(livingEntity) > 0){
                    MiscCapHelper.setClientTargetID(livingEntity, 0);
                }
            }
            if (MiscCapHelper.getEnchanterTime(livingEntity) > 0) {
                MiscCapHelper.setEnchanterTime(livingEntity, MiscCapHelper.getEnchanterTime(livingEntity) - 1);
            }
            if (MiscCapHelper.getShields(livingEntity) > 0) {
                if (MiscCapHelper.getShieldTime(livingEntity) > 0) {
                    MiscCapHelper.decreaseShieldTime(livingEntity);
                } else {
                    MiscCapHelper.setShields(livingEntity, 0);
                    if (!livingEntity.level.isClientSide) {
                        if (livingEntity instanceof Player player) {
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(ModSounds.WALL_DISAPPEAR.get(), 1.0F, 2.0F));
                        } else {
                            livingEntity.playSound(ModSounds.WALL_DISAPPEAR.get(), 1.0F, 2.0F);
                        }
                    }
                }
            } else {
                if (MiscCapHelper.getShieldTime(livingEntity) > 0) {
                    MiscCapHelper.setShieldTime(livingEntity, 0);
                }
            }
            if (MiscCapHelper.getShieldCool(livingEntity) > 0){
                MiscCapHelper.decreaseShieldCool(livingEntity);
            }
            if (MiscCapHelper.getShakeTime(livingEntity) > 0) {
                MiscCapHelper.setShakeTime(livingEntity, MiscCapHelper.getShakeTime(livingEntity) - 1);
            }
            if (MiscCapHelper.getSunscreen(livingEntity) > 0) {
                MiscCapHelper.setSunscreen(livingEntity, MiscCapHelper.getSunscreen(livingEntity) - 1);
            }
            if (livingEntity instanceof Mob mob){
                double followRange = 32.0D;
                if (mob.getAttribute(Attributes.FOLLOW_RANGE) != null){
                    followRange = mob.getAttributeValue(Attributes.FOLLOW_RANGE) * 2;
                }
//                MiscCapHelper.updateMobTarget(mob); Commented in case it causes lag
                if (mob.getTarget() instanceof Apostle apostle){
                    if (apostle.obsidianInvul > 5){
                        for (AbstractObsidianMonolith obsidianMonolith : mob.level.getEntitiesOfClass(AbstractObsidianMonolith.class, mob.getBoundingBox().inflate(followRange, 8.0D, followRange))){
                            if (obsidianMonolith.getOwner() == apostle){
                                mob.setTarget(obsidianMonolith);
                                try {
                                    mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, obsidianMonolith.getUUID(), 600L);
                                    mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, obsidianMonolith, 600L);
                                    if (mob instanceof Warden warden) {
                                        warden.increaseAngerAt(obsidianMonolith, AngerLevel.ANGRY.getMinimumAnger() + 20, false);
                                        warden.setAttackTarget(obsidianMonolith);
                                    }
                                } catch (NullPointerException ignored) {
                                }
                            }
                        }
                    }
                }
                if (mob.getTarget() instanceof AbstractObsidianMonolith monolith){
                    if (monolith.empowered > 5){
                        for (Heretic heretic : mob.level.getEntitiesOfClass(Heretic.class, mob.getBoundingBox().inflate(followRange, 8.0D, followRange))){
                            if (heretic.getMonolith() == monolith){
                                mob.setTarget(heretic);
                            }
                        }
                    }
                }
                if (mob.getTarget() instanceof IHiding hiding) {
                    if (hiding.isHiding()) {
                        mob.setTarget(null);
                    }
                }
            }
            if (livingEntity instanceof Raider raider) {
                if (raider.getTarget() instanceof Player player) {
                    if (SEHelper.getSoulAmountInt(player) > MobsConfig.IllagerAssaultSEThreshold.get() * 2){
                        if (!raider.isAggressive()) {
                            raider.setAggressive(true);
                        }
                    }
                }
            }
            if (livingEntity instanceof Villager villager){
                if (!villager.level.isClientSide) {
                    Brain<?> brain = villager.getBrain();
                    Optional<LivingEntity> avoidIllager = Optional.empty();
                    NearestVisibleLivingEntities nearestvisiblelivingentities = brain.getMemory(MemoryModuleType.NEAREST_VISIBLE_LIVING_ENTITIES).orElse(NearestVisibleLivingEntities.empty());
                    for (LivingEntity livingentity : nearestvisiblelivingentities.findAll((p_186157_) -> true)) {
                        if (livingentity instanceof HuntingIllagerEntity || livingentity instanceof Tormentor || livingentity instanceof HostileGolem || livingentity instanceof Trampler || livingentity instanceof Vizier){
                            avoidIllager = Optional.of(livingentity);
                        } else if (livingentity instanceof RaiderServant servant) {
                            if (servant.isRaiding() || servant.isHostile()) {
                                avoidIllager = Optional.of(livingentity);
                                if (servant.isRaiding()) {
                                    brain.setMemory(MemoryModuleType.HEARD_BELL_TIME, villager.level.getGameTime());
                                }
                            }
                        }
                    }
                    if (avoidIllager.isPresent()) {
                        brain.setMemory(MemoryModuleType.NEAREST_HOSTILE, avoidIllager);
