    public void tick() {
//        if (ticksExisted == 1)
//            System.out.println("Spawned " + getName().getFormattedText() + " at " + getPosition());
        setYRot(yBodyRot);
        super.tick();
        this.repelEntities(3.8f, 3.8f, 3.8f, 3.8f);

        if (getTarget() != null && (!getTarget().isAlive() || getTarget().getHealth() <= 0)) setTarget(null);

        if (isAlwaysActive()) {
            setActive(true);
        }

        if (getActive() && getAnimation() != ACTIVATE_ANIMATION && getAnimation() != ACTIVATE_NO_CRYSTAL_ANIMATION) {
            legSolver.update(this);

            if (getAnimation() == SWIPE_ANIMATION || getAnimation() == SWIPE_TWICE_ANIMATION) {
                if (getAnimationTick() == 3) {
                    int i = Mth.nextInt(random, 0, MMSounds.ENTITY_FROSTMAW_ATTACK.size());
                    if (i < MMSounds.ENTITY_FROSTMAW_ATTACK.size()) {
                        playSound(MMSounds.ENTITY_FROSTMAW_ATTACK.get(i).get(), 2, 0.9f + random.nextFloat() * 0.2f);
                    }
                }
            }

            if (getAnimation() == SWIPE_ANIMATION) {
                if (getAnimationTick() == 6) {
                    playSound(MMSounds.ENTITY_FROSTMAW_WHOOSH.get(), 2, 0.8f);
                }
                if (getTarget() != null) lookControl.setLookAt(getTarget(), 30, 30);
            }

            if (getAnimation() == ROAR_ANIMATION) {
                if (getAnimationTick() == 10) {
                    playSound(MMSounds.ENTITY_FROSTMAW_ROAR.get(), 4, 1);
                    EntityCameraShake.cameraShake(level(), position(), 45, 0.03f, 60, 20);
                }
                if (getAnimationTick() >= 8 && getAnimationTick() < 65) {
                    doRoarEffects();
                }
            }

            if (getAnimation() == LAND_ANIMATION) {
                if (getAnimationTick() == 3) {
                    playSound(MMSounds.ENTITY_FROSTMAW_LAND.get(), 3, 0.9f);
                }
            }

            if (getAnimation() == SLAM_ANIMATION) {
                if (getAnimationTick() == 82) {
                    playSound(MMSounds.ENTITY_FROSTMAW_LIVING_1.get(), 2, 1);
                }
                if (getTarget() != null) lookControl.setLookAt(getTarget(), 30, 30);
                if (getAnimationTick() == 82) {
                    int i = Mth.nextInt(random, 0, MMSounds.ENTITY_FROSTMAW_ATTACK.size() - 1);
                    if (i < MMSounds.ENTITY_FROSTMAW_ATTACK.size()) {
                        playSound(MMSounds.ENTITY_FROSTMAW_ATTACK.get(i).get(), 2, 0.9f + random.nextFloat() * 0.2f);
                    }
                    playSound(MMSounds.ENTITY_FROSTMAW_WHOOSH.get(), 2, 0.7f);
                }
                if (getAnimationTick() == 87) {
                    playSound(MMSounds.ENTITY_FROSTMAW_LAND.get(), 3, 1f);
                    float radius = 4;
                    float slamPosX = (float) (getX() + radius * Math.cos(Math.toRadians(getYRot() + 90)));
                    float slamPosZ = (float) (getZ() + radius * Math.sin(Math.toRadians(getYRot() + 90)));
                    if (level().isClientSide) level().addParticle(new ParticleRing.Data(0f, (float)Math.PI/2f, 17, 1f, 1f, 1f, 1f, 60, false, ParticleRing.EnumRingBehavior.GROW), slamPosX, getY() + 0.2f, slamPosZ, 0, 0, 0);
                    AABB hitBox = new AABB(slamPosX - 0.5f, getY() - 0.5f,  slamPosZ - 0.5f,slamPosX + 0.5f, getY() + 0.5f, slamPosZ + 0.5f).inflate(3, 3, 3);
                    List<LivingEntity> entitiesHit = level().getEntitiesOfClass(LivingEntity.class, hitBox);
                    for (LivingEntity entity: entitiesHit) {
                        if (entity != this && entity.position().distanceToSqr(slamPosX, getY(), slamPosZ) <= 9) {
                            doHurtTarget(entity, 4f, 1);
                            if (entity.isBlocking()) entity.getUseItem().hurtAndBreak(400, entity, LivingEntity.getSlotForHand(entity.getUsedItemHand()));
                        }
                    }
                    EntityCameraShake.cameraShake(level(), new Vec3(slamPosX, getY(), slamPosZ), 30, 0.1f, 0, 20);
                }
            }
            if (getAnimation() == DODGE_ANIMATION && !level().isClientSide) {
                getNavigation().stop();
                if (getAnimationTick() == 2) {
                    dodgeYaw = (float) Math.toRadians(targetAngle + 90 + random.nextFloat() * 150 - 75);
                }
                if (getAnimationTick() == 6 && (onGround() || isInLava() || isInWater())) {
                    float speed = 1.7f;
                    Vec3 m = getDeltaMovement().add(speed * Math.cos(dodgeYaw), 0, speed * Math.sin(dodgeYaw));
                    setDeltaMovement(m.x, 0.6, m.z);
                }
                if (getTarget() != null) lookControl.setLookAt(getTarget(), 30, 30);
            }

            if (getAnimation() == ICE_BREATH_ANIMATION) {
                if (getTarget() != null) {
                    lookControl.setLookAt(getTarget(), 30, 30);
                    lookAt(getTarget(), 30, 30);
                    yHeadRot = yBodyRot = getYRot();
                }
                Vec3 mouthPos = new Vec3(2.3, 2.65, 0);
                mouthPos = mouthPos.yRot((float)Math.toRadians(-getYRot() - 90));
                mouthPos = mouthPos.add(position());
                mouthPos = mouthPos.add(new Vec3(0, 0, 1).xRot((float)Math.toRadians(-getXRot())).yRot((float)Math.toRadians(-yHeadRot)));
                if (getAnimationTick() == 13) {
                    iceBreath = new EntityIceBreath(EntityHandler.ICE_BREATH.get(), level(), this);
                    iceBreath.absMoveTo(mouthPos.x, mouthPos.y, mouthPos.z, yHeadRot, getXRot() + 10);
                    if (!level().isClientSide) level().addFreshEntity(iceBreath);
                }
                if (iceBreath != null)
                    iceBreath.absMoveTo(mouthPos.x, mouthPos.y, mouthPos.z, yHeadRot, getXRot() + 10);
            }

            if (getAnimation() == ICE_BALL_ANIMATION) {
                if (getTarget() != null) lookControl.setLookAt(getTarget(), 15, 15);
                Vec3 projectilePos = new Vec3(2.0, 1.9, 0);
                projectilePos = projectilePos.yRot((float)Math.toRadians(-getYRot()- 90));
                projectilePos = projectilePos.add(position());
                projectilePos = projectilePos.add(new Vec3(0, 0, 1).xRot((float)Math.toRadians(-getXRot())).yRot((float)Math.toRadians(-yHeadRot)));
                if (level().isClientSide) {
                    Vec3 mouthPos = socketPosArray[2];
                    if (getAnimationTick() < 12) {
                        for (int i = 0; i < 6; i++) {
                            Vec3 particlePos = new Vec3(3.5, 0, 0);
                            particlePos = particlePos.yRot((float) (random.nextFloat() * 2 * Math.PI));
                            particlePos = particlePos.xRot((float) (random.nextFloat() * 2 * Math.PI));
                            float value = random.nextFloat() * 0.15f;
                            level().addParticle(new ParticleCloud.Data(0.75f + value, 0.75f + value, 1f, 5f + random.nextFloat() * 15f, 30, ParticleCloud.EnumCloudBehavior.CONSTANT, 1f), mouthPos.x + particlePos.x, mouthPos.y + particlePos.y, mouthPos.z + particlePos.z, -0.1 * particlePos.x, -0.1 * particlePos.y, -0.1 * particlePos.z);
                        }
                        for (int i = 0; i < 8; i++) {
                            Vec3 particlePos = new Vec3(3.5, 0, 0);
                            particlePos = particlePos.yRot((float) (random.nextFloat() * 2 * Math.PI));
                            particlePos = particlePos.xRot((float) (random.nextFloat() * 2 * Math.PI));
                            level().addParticle(new ParticleSnowFlake.Data(40, false), mouthPos.x + particlePos.x, mouthPos.y + particlePos.y, mouthPos.z + particlePos.z, -0.07 * particlePos.x, -0.07 * particlePos.y, -0.07 * particlePos.z);
                        }
                    }
                }

                if (getAnimationTick() == 32) {
                    if (getTarget() != null) prevTargetPos = getTarget().position().add(new Vec3(0f, getTarget().getBbHeight() / 2.0, 0f));
                }
                if (getAnimationTick() == 33) {
                    playSound(MMSounds.ENTITY_FROSTMAW_ICEBALL_SHOOT.get(), 2, 0.7f);

                    EntityIceBall iceBall = new EntityIceBall(EntityHandler.ICE_BALL.get(), level(), this);
                    iceBall.absMoveTo(projectilePos.x, projectilePos.y, projectilePos.z, yHeadRot, getXRot() + 10);
                    float projSpeed = 1.6f;
                    if (getTarget() != null) {
                        float ticksUntilHit = targetDistance / projSpeed;
                        Vec3 targetPos = getTarget().position().add(new Vec3(0f, getTarget().getBbHeight() / 2.0, 0f));
                        Vec3 targetMovement = targetPos.subtract(prevTargetPos).scale(ticksUntilHit * 0.95);
                        targetMovement = targetMovement.subtract(0, targetMovement.y, 0);
                        Vec3 futureTargetPos = targetPos.add(targetMovement);
                        Vec3 projectileMid = projectilePos.add(new Vec3(0, iceBall.getBbHeight() / 2.0, 0));
                        Vec3 shootVec = futureTargetPos.subtract(projectileMid).normalize();
                        iceBall.shoot(shootVec.x, shootVec.y, shootVec.z, projSpeed, 0);
                    }
                    else {
                        iceBall.shoot(getLookAngle().x, getLookAngle().y, getLookAngle().z, projSpeed, 0);
                    }
                    if (!level().isClientSide) level().addFreshEntity(iceBall);
                }
            }

            spawnSwipeParticles();

            if (fallDistance > 0.2 && !onGround() && getLastDamageSource() != null && !getLastDamageSource().is(DamageTypes.LAVA)) shouldPlayLandAnimation = true;
            if (onGround() && shouldPlayLandAnimation && getAnimation() != DODGE_ANIMATION) {
                if (!level().isClientSide && getAnimation() == NO_ANIMATION) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, LAND_ANIMATION);
                }
                shouldPlayLandAnimation = false;
            }

            if (getTarget() != null) {
                timeWithoutTarget = 0;

                float entityHitAngle = (float) ((Math.atan2(getTarget().getZ() - getZ(), getTarget().getX() - getX()) * (180 / Math.PI) - 90) % 360);
                float entityAttackingAngle = yBodyRot % 360;
                if (entityHitAngle < 0) {
                    entityHitAngle += 360;
                }
                if (entityAttackingAngle < 0) {
                    entityAttackingAngle += 360;
                }
                float entityRelativeAngle = entityHitAngle - entityAttackingAngle;
                if (getNavigation().isDone() && !((entityRelativeAngle <= 30 / 2f && entityRelativeAngle >= -30 / 2f) || (entityRelativeAngle >= 360 - 30 / 2f || entityRelativeAngle <= -360 + 30 / 2f))) {
                    getNavigation().moveTo(getTarget(), 0.85);
                }

                if (shouldDodgeMeasure >= 16) shouldDodge = true;
                if (getTarget().hasEffect(EffectHandler.FROZEN)) shouldDodge = false;
                if (targetDistance < 4 && shouldDodge && getAnimation() == NO_ANIMATION) {
                    shouldDodge = false;
                    dodgeCooldown = DODGE_COOLDOWN;
                    shouldDodgeMeasure = 0;
                    if (getHasCrystal()) {
                        wantsToIceBreathAfterDodging = true;
                    }
                    iceBreathCooldown = 0;
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, DODGE_ANIMATION);
                }

                if (targetDistance > 5.5 && !(getAnimation() == ICE_BREATH_ANIMATION && targetDistance < 7.5)) {
                    if (getAnimation() != SLAM_ANIMATION) getNavigation().moveTo(getTarget(), 1);
                    else getNavigation().moveTo(getTarget(), 0.95);
                }
                else getNavigation().stop();
                if (targetDistance <= 8.5 && getAnimation() == NO_ANIMATION && slamCooldown <= 0 && random.nextInt(4) == 0 && getHealthRatio() < 0.6) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SLAM_ANIMATION);
                    slamCooldown = SLAM_COOLDOWN;
                }
                if (targetDistance <= 6.5 && getAnimation() == NO_ANIMATION && !wantsToIceBreathAfterDodging) {
                    if (random.nextInt(4) == 0)
                        AnimationHandler.INSTANCE.sendAnimationMessage(this, SWIPE_TWICE_ANIMATION);
                    else AnimationHandler.INSTANCE.sendAnimationMessage(this, SWIPE_ANIMATION);
                }
                if (targetDistance <= 13.5 && getAnimation() == NO_ANIMATION && iceBreathCooldown <= 0 && getHasCrystal() && (onGround() || wasTouchingWater)) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, ICE_BREATH_ANIMATION);
                    iceBreathCooldown = ICE_BREATH_COOLDOWN;
                    wantsToIceBreathAfterDodging = false;
                }
                if (targetDistance >= 14.5 && getAnimation() == NO_ANIMATION && iceBallCooldown <= 0 && getHasCrystal() && (onGround() || wasTouchingWater)) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, ICE_BALL_ANIMATION);
                    iceBallCooldown = ICE_BALL_COOLDOWN;
                }
            }
            else if (!level().isClientSide) {
                if (!isAlwaysActive()) {
                    timeWithoutTarget++;
                    if (timeWithoutTarget > 1200 || level().getDifficulty() == Difficulty.PEACEFUL) {
                        timeWithoutTarget = 0;
                        if (getAnimation() == NO_ANIMATION) {
                            AnimationHandler.INSTANCE.sendAnimationMessage(this, DEACTIVATE_ANIMATION);
                            setActive(false);
                        }
                    }
                }
            }
        }
        else {
            getNavigation().stop();
            setDeltaMovement(0, getDeltaMovement().y, 0);
            yBodyRot = yBodyRotO;
            if (!level().isClientSide && getAnimation() != ACTIVATE_ANIMATION) {
                if (ConfigHandler.COMMON.MOBS.FROSTMAW.healsOutOfBattle.get()) heal(0.3f);
            }
            if (getTarget() != null && getTarget().hasEffect(MobEffects.INVISIBILITY)) {
                setTarget(null);
            }
            if (!getAttackableEntityLivingBaseNearby(8, 8, 8, 8).isEmpty() && getTarget() != null && getAnimation() == NO_ANIMATION) {
                if (level().getDifficulty() != Difficulty.PEACEFUL) {
                    if (getHasCrystal()) AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_ANIMATION);
                    else AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_NO_CRYSTAL_ANIMATION);
                    setActive(true);
                }
            }

            if (ConfigHandler.COMMON.MOBS.FROSTMAW.stealableIceCrystal.get() && getHasCrystal() && tickCount > 20 && getAnimation() == NO_ANIMATION) {
                Vec3 crystalPos = new Vec3(1.6, 0.4, 1.8);
                crystalPos = crystalPos.yRot((float) Math.toRadians(-getYRot() - 90));
                crystalPos = crystalPos.add(position());
                for (Player player : getPlayersNearby(8, 8, 8, 8)) {
                    if (player.position().distanceTo(crystalPos) <= 1.8 && (player.isCreative() || player.isInvisible()) && !isInventoryFull(player.getInventory())) {
                        ItemHandlerHelper.giveItemToPlayer(player, new ItemStack(ItemHandler.ICE_CRYSTAL.get()));
                        setHasCrystal(false);
                        if (level().getDifficulty() != Difficulty.PEACEFUL) {
                            AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_NO_CRYSTAL_ANIMATION);
                            setActive(true);
                        }

                        if (player instanceof ServerPlayer serverPlayer) {
                            AdvancementHandler.STEAL_ICE_CRYSTAL_TRIGGER.value().trigger(serverPlayer);
                        }

                        break;
                    }
                }
            }
        }

        if (getAnimation() == ACTIVATE_ANIMATION || getAnimation() == ACTIVATE_NO_CRYSTAL_ANIMATION) {
            //if (getAnimationTick() == 1) playSound(MMSounds.ENTITY_FROSTMAW_WAKEUP, 1, 1);
            if (getAnimation() == ACTIVATE_ANIMATION && getAnimationTick() == 18) playSound(MMSounds.ENTITY_FROSTMAW_ATTACK.get(0).get(), 1.5f, 1);
            if ((getAnimation() == ACTIVATE_ANIMATION && getAnimationTick() == 52) || (getAnimation() == ACTIVATE_NO_CRYSTAL_ANIMATION && getAnimationTick() == 34)) {
                playSound(MMSounds.ENTITY_FROSTMAW_ROAR.get(), 4, 1);
                EntityCameraShake.cameraShake(level(), position(), 45, 0.03f, 60, 20);
            }
            if ((getAnimation() == ACTIVATE_ANIMATION && getAnimationTick() >= 51 && getAnimationTick() < 108) || (getAnimation() == ACTIVATE_NO_CRYSTAL_ANIMATION && getAnimationTick() >= 33 && getAnimationTick() < 90)) {
                doRoarEffects();
            }
        }

        if (level().isClientSide) {
            if ((getAnimation() == SWIPE_ANIMATION || getAnimation() == SWIPE_TWICE_ANIMATION) && getAnimationTick() == 1) {
                swingWhichArm = random.nextBoolean();
            }
        }

        //Footstep Sounds
        float moveX = (float) (getX() - xo);
        float moveZ = (float) (getZ() - zo);
        float speed = Mth.sqrt(moveX * moveX + moveZ * moveZ);
        if (frame % 16 == 5 && speed > 0.05 && active) {
            playSound(MMSounds.ENTITY_FROSTMAW_STEP.get(), 3F, 0.8F + random.nextFloat() * 0.2f);
            EntityCameraShake.cameraShake(level(), position(), 20, 0.03f, 0, 10);
        }

        //Breathing sounds
        if (frame % 118 == 1 && !active) {
            int i = Mth.nextInt(random, 0, 1);
            playSound(MMSounds.ENTITY_FROSTMAW_BREATH.get(i).get(), 1.5F, 1.1F + random.nextFloat() * 0.1f);
        }

//        if (getAnimation() == NO_ANIMATION && onGround()) {
//            AnimationHandler.INSTANCE.sendAnimationMessage(this, SLAM_ANIMATION);
//            setActive(true);
//        }

        if (iceBreathCooldown > 0) iceBreathCooldown--;
        if (iceBallCooldown > 0) iceBallCooldown--;
        if (slamCooldown > 0) slamCooldown--;
        if (shouldDodgeMeasure > 0 && tickCount % 7 == 0) shouldDodgeMeasure--;
        if (dodgeCooldown > 0) dodgeCooldown--;
        yRotO = getYRot();
    }

public void tick() {
    super.tick();
    AnimationHandler.INSTANCE.updateAnimations(this);
    this.legSolver.update(this, this.yBodyRot, this.getScale());
    prevScreenShakeAmount = screenShakeAmount;
    prevBeamProgress = beamProgress;
    prevClientBeamEndPosition = clientBeamEndPosition;
    prevClientSpikesDownAmount = clientSpikesDownAmount;
    boolean water = this.isInFluidType();
    if (water && this.isLandNavigator) {
        switchNavigator(false);
    }
    if (!water && !this.isLandNavigator) {
        switchNavigator(true);
    }
    if (isTremorzillaSwimming()) {
        timeSwimming++;
        this.setAirSupply(getMaxAirSupply());
    } else {
        timeSwimming = 0;
    }

    if (screenShakeAmount > 0) {
        screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
    }
    if (this.isFiring() && beamProgress < 5F) {
        beamProgress++;
    }
    if (!this.isFiring() && beamProgress > 0F) {
        beamProgress--;
    }

    clientSpikesDownAmount = Mth.approach(clientSpikesDownAmount, this.getSpikesDownAmount(), 0.1F);
    Vec3 beamEnd = getBeamEndPosition();
    clientBeamEndPosition = beamEnd;
    if (this.isFiring()) {
        boolean flag = false;
        if (this.isFiring() && beamEnd != null) {
            Vec3 vec3 = beamEnd.subtract(getBeamShootFrom(1.0F));
            float beamYaw = -((float) Mth.atan2(vec3.x, vec3.z)) * (180F / (float) Math.PI);
            if (Mth.degreesDifferenceAbs(beamYaw, Mth.wrapDegrees(this.yBodyRot)) > 80F) {
                flag = true;
                this.setYRot(Mth.approachDegrees(this.getYRot(), beamYaw, 10));
                this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, beamYaw, 10);
                lastYawBeforeWhip = beamYaw;
            }
        }
        if (!flag) {
            this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, lastYawBeforeWhip, 15);
        }
    } else if (this.getAnimation() != ANIMATION_RIGHT_TAIL && this.getAnimation() != ANIMATION_LEFT_TAIL) {
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, this.getYRot(), 4);
        this.yHeadRot = Mth.approachDegrees(this.yHeadRotO, this.yHeadRot, 2);
        lastYawBeforeWhip = this.yBodyRot;
    } else {
        float negative = this.getAnimation() == ANIMATION_RIGHT_TAIL ? -1 : 1;
        float target = 0;
        if (this.getAnimationTick() < 5) {
            float f = this.getAnimationTick() / 5F;
            target = f * -10;
        } else {
            float f = (this.getAnimationTick() - 10) / 15F;
            target = Mth.clamp(f, 0F, 1F) * 170;
        }
        if (this.getAnimationTick() > 25F) {
            this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, lastYawBeforeWhip, 15);
        } else {
            this.walkAnimation.setSpeed(1 + AlexsCaves.PROXY.getPartialTicks());
            this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, lastYawBeforeWhip + negative * target, 70);
        }
    }
    if (screenShakeAmount > 0) {
        screenShakeAmount = Math.max(0, screenShakeAmount - 0.15F);
    }
    if (this.onGround() && !this.isInFluidType() && this.walkAnimation.speed() > 0.1F && !this.isBaby() && !this.isNoAi() && this.isAlive()) {
        float f = (float) Math.cos(this.walkAnimation.position() * 0.25F - 1.5F);
        float f1 = (float) Math.cos(this.walkAnimation.position() * 0.25F - 1.0F);
        float f2 = (float) Math.sin(this.walkAnimation.position() * 0.25F - 1.0F);
        if (Math.abs(f) < 0.2F) {
            if (screenShakeAmount <= 0.3) {
                this.playSound(ACSoundRegistry.TREMORZILLA_STOMP.get(), 6.0F, 0.7F);
            }
            screenShakeAmount = 2.0F;
        }
        if (this.walkAnimation.speed() > 0.5F && Math.abs(f1) < 0.1F) {
            stompEffect(f2 > 0, 1F, 1.3F, 0.4F + this.walkAnimation.speed(), 2F);
        }
    }
    tickMultipart();
    if (level().isClientSide) {
        if (this.lSteps > 0) {
            double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
            double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
            double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
            this.setYRot(Mth.wrapDegrees((float) this.lyr));
            this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
            --this.lSteps;
            this.setPos(d5, d6, d7);
        } else {
            this.reapplyPosition();
        }
        Player player = AlexsCaves.PROXY.getClientSidePlayer();
        if (player != null && player.isPassengerOfSameVehicle(this)) {
            if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
            }
            if (AlexsCaves.PROXY.isKeyDown(3) && (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null)) {
                AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 3));
            }
        }
        if (this.isFiring() && beamProgress > 0) {
            if (!makingBeamSoundOnClient) {
                AlexsCaves.PROXY.playWorldSound((Object) this, (byte) 16);
                makingBeamSoundOnClient = true;
            }
        }
        if (!isFiring() && makingBeamSoundOnClient) {
            AlexsCaves.PROXY.clearSoundCacheFor(this);
            makingBeamSoundOnClient = false;
        }
    } else {
        double waterHeight = getMaxFluidHeight();
        if (waterHeight > 0 && waterHeight < this.getBbHeight() - 1.0F && !this.verticalCollision) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.02, 0));
        }
        this.setTremorzillaSwimming(waterHeight > 2.0F);
    }
    if (this.isAlive()) {
        if (this.isFiring()) {
            tickBreath();
        } else if (steamFromMouthFor > 0 && level().isClientSide) {
            level().addAlwaysVisibleParticle(ACParticleRegistry.TREMORZILLA_STEAM.get(), true, this.getX(), this.getEyeY(), this.getZ(), this.getId(), 0, 0);
        }
        if(!this.isFiring() && killCountFromBeam > 0){
            if(killCountFromBeam > 20 && !this.level().isClientSide){
                if(this.isVehicle()){
                    for(Entity passenger : this.getPassengers()){
                        ACAdvancementTriggerRegistry.TREMORZILLA_KILL_BEAM.triggerForEntity(passenger);
                    }
                }
            }
            killCountFromBeam = 0;
        }
        if ((this.getAnimation() == ANIMATION_RIGHT_SCRATCH || this.getAnimation() == ANIMATION_LEFT_SCRATCH) && this.getAnimationTick() == 18) {
            Vec3 center = new Vec3(0, 5 * this.getScale(), 6 * this.getScale()).yRot(-this.yBodyRot * ((float) Math.PI / 180F)).add(position());
            this.hurtEntitiesAround(center, 6.0F, 10.0F, 2.0F, false, true, true);
            if (!level().isClientSide) {
                this.breakBlocksAround(center, 3.0F, false, false, 0.6F);
            }
        }
        if ((this.getAnimation() == ANIMATION_RIGHT_TAIL || this.getAnimation() == ANIMATION_LEFT_TAIL) && this.getAnimationTick() >= 10 && this.getAnimationTick() < 25) {
            this.hurtEntitiesAround(tailPart1.centeredPosition(), 4.0F, 10.0F, 2.0F, false, true, true);
            this.hurtEntitiesAround(tailPart2.centeredPosition(), 4.0F, 10.0F, 2.0F, false, true, true);
            this.hurtEntitiesAround(tailPart3.centeredPosition(), 4.0F, 10.0F, 2.0F, false, true, true);
            this.hurtEntitiesAround(tailPart4.centeredPosition(), 3.0F, 10.0F, 2.0F, false, true, true);
            this.hurtEntitiesAround(tailPart5.centeredPosition(), 3.0F, 10.0F, 2.0F, false, true, true);
            if (!level().isClientSide) {
                this.breakBlocksAround(tailPart1.centeredPosition(), 2.0F, false, false, 0.6F);
                this.breakBlocksAround(tailPart2.centeredPosition(), 2.0F, false, false, 0.6F);
                this.breakBlocksAround(tailPart3.centeredPosition(), 2.0F, false, false, 0.6F);
                this.breakBlocksAround(tailPart4.centeredPosition(), 1.0F, false, false, 0.6F);
                this.breakBlocksAround(tailPart5.centeredPosition(), 1.0F, false, false, 0.6F);
            }
        }
        if ((this.getAnimation() == ANIMATION_LEFT_STOMP || this.getAnimation() == ANIMATION_RIGHT_STOMP) && this.getAnimationTick() == 18) {
            this.stompEffect(this.getAnimation() == ANIMATION_LEFT_STOMP, 2.0F, 5F, 1.2F, 10F);
            screenShakeAmount = 4.0F;
        }
        if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 10) {
            Vec3 center = new Vec3(0, 7 * this.getScale(), 5 * this.getScale()).yRot(-this.yBodyRot * ((float) Math.PI / 180F)).add(position());
            this.hurtEntitiesAround(center, 7.5F, 10.0F, 2.0F, false, true, true);
            if (!level().isClientSide) {
                this.breakBlocksAround(center, 4.0F, false, false, 0.6F);
            }
        }
        if (this.getAnimation() == ANIMATION_ROAR_1 && this.getAnimationTick() > 10 && this.getAnimationTick() < 50 || this.getAnimation() == ANIMATION_ROAR_2 && this.getAnimationTick() > 15 && this.getAnimationTick() < 50) {
            screenShakeAmount = 8.0F;
            if (!level().isClientSide) {
                scareMobs();
            }
        }
        if (this.getAnimation() == ANIMATION_SPEAK && this.getAnimationTick() == 5 && !this.isFiring()) {
            actuallyPlayAmbientSound();
        }
    }
    if (!level().isClientSide) {
        LivingEntity target = this.getTarget();
        if (target == null || !target.isAlive()) {
            timeWithoutTarget++;
        } else {
            timeWithoutTarget = 0;
        }
        if (wantsToUseBeamFromServer && (timeWithoutTarget > 100 && !this.isVehicle() || this.isInSittingPose())) {
            wantsToUseBeamFromServer = false;
        }
        if (isFiring()) {
            wantsToUseBeamFromServer = false;
            int iterateBy = 1;
            if (!isVehicle()) {
                if (target == null || !target.isAlive()) {
                    iterateBy = 3;
                } else if (target.distanceTo(this) > 100) {
                    iterateBy = 8;
                }
            }
            beamTime += iterateBy;
            if (beamTime > maxBeamTime) {
                beamTime = 0;
                this.setFiring(false);
                this.playSound(ACSoundRegistry.TREMORZILLA_BEAM_END.get(), 8.0F, 1.0F);
                this.beamServerTarget = null;
                this.setBeamEndPosition(null);
                this.setCharge(0);
            } else {
                if (!isStunned()) {
                    tickBeamTargeting();
                }
                this.setCharge(MAX_CHARGE);
            }
        } else if (wantsToUseBeamFromServer && this.isPowered()) {
            float spikesThreshold = 0.95F;
            if (this.getAnimation() == ANIMATION_PREPARE_BREATH && this.getSpikesDownAmount() >= spikesThreshold && this.getAnimationTick() > 15 && !this.isFiring()) {
                this.maxBeamTime = 100 + random.nextInt(150);
                this.beamServerTarget = createInitialBeamVec();
                this.lookAt(EntityAnchorArgument.Anchor.EYES, beamServerTarget);
                this.setFiring(true);
                this.setMaxBeamBreakLength(100F);
            }
            if (this.getSpikesDownAmount() >= spikesThreshold && this.getAnimation() == NO_ANIMATION && !isStunned()) {
                this.setAnimation(ANIMATION_PREPARE_BREATH);
                this.playSound(ACSoundRegistry.TREMORZILLA_BEAM_START.get(), 8.0F, 1.0F);
            }
            this.setSpikesDownAmount(Math.min(this.getSpikesDownAmount() + 0.005F, 1F));
            if ((tickCount + this.getId()) % 10 == 0 && level() instanceof ServerLevel serverLevel) {
                getNearbySirens(serverLevel, 256).forEach(this::activateSiren);
            }
            float f = calculateSpikesDownAmount(this.getSpikesDownAmount(), 6F);
            if (Math.floor(f - 0.005F) != Math.floor(f) && chargeSoundCooldown <= 0 && f <= 5) {
                float pitch = 0.7F + this.getSpikesDownAmount() * 0.7F;
                this.playSound(f > 4 ? ACSoundRegistry.TREMORZILLA_CHARGE_COMPLETE.get() : ACSoundRegistry.TREMORZILLA_CHARGE_NORMAL.get(), 8.0F, pitch);
                chargeSoundCooldown = 19;
            }
            if (chargeSoundCooldown > 0) {
                chargeSoundCooldown--;
            }
        } else {
            this.setSpikesDownAmount(Math.max(this.getSpikesDownAmount() - 0.05F, 0F));
            if (this.getDeltaMovement().horizontalDistance() < 0.05 && this.getAnimation() == NO_ANIMATION && !this.isDancing() && !this.isInSittingPose() && !this.isNoAi()) {
                if (random.nextInt(800) == 0 && !this.isVehicle()) {
                    this.tryRoar();
                }
            }
        }
        if (!this.isPowered()) {
            this.setCharge(this.getCharge() + 1);
        }
        float healthAmount = this.getHealth() / this.getMaxHealth();
        if (healthAmount <= 0.2F) {
            healEveryTick(10, 5.0F);
        } else if (healthAmount <= 0.5F) {
            healEveryTick(20, 3.0F);
        } else {
            healEveryTick(100, 2.0F);
        }
    }
    if (!this.isPowered()) {
        this.setSpikesDownAmount(0.0F);
    }
    if (steamFromMouthFor > 0) {
        steamFromMouthFor--;
    }
    if (roarCooldown > 0) {
        roarCooldown--;
    }
    if (wasPreviouslyChild != this.isBaby()) {
        wasPreviouslyChild = this.isBaby();
        this.refreshDimensions();
        for (TremorzillaPartEntity tremorzillaPartEntity : this.allParts) {
            tremorzillaPartEntity.refreshDimensions();
        }
    }
    if (this.hasEffect(ACEffectRegistry.IRRADIATED.get())) {
        MobEffectInstance instance = this.getEffect(ACEffectRegistry.IRRADIATED.get());
        int level = instance == null ? 1 : 1 + instance.getAmplifier();
        this.heal(level * 12);
        this.removeEffect(ACEffectRegistry.IRRADIATED.get());
    }
    if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 2) {
        this.playSound(ACSoundRegistry.TREMORZILLA_BITE.get(), 4.0F, this.getVoicePitch());
    }
    if ((this.getAnimation() == ANIMATION_RIGHT_SCRATCH || this.getAnimation() == ANIMATION_LEFT_SCRATCH) && this.getAnimationTick() == 2) {
        this.playSound(ACSoundRegistry.TREMORZILLA_SCRATCH_ATTACK.get(), 4.0F, this.getVoicePitch());
    }
    if ((this.getAnimation() == ANIMATION_RIGHT_STOMP || this.getAnimation() == ANIMATION_LEFT_STOMP) && this.getAnimationTick() == 2) {
        this.playSound(ACSoundRegistry.TREMORZILLA_STOMP_ATTACK.get(), 4.0F, this.getVoicePitch());
    }
    if ((this.getAnimation() == ANIMATION_RIGHT_TAIL || this.getAnimation() == ANIMATION_LEFT_TAIL) && this.getAnimationTick() == 2) {
        this.playSound(ACSoundRegistry.TREMORZILLA_TAIL_ATTACK.get(), 4.0F, this.getVoicePitch());
    }
    if(this.getAnimation() == ANIMATION_CHEW && this.getAnimationTick() % 6 == 0 && this.getAnimationTick() <= 30){
        this.playSound(ACSoundRegistry.TREMORZILLA_EAT.get(), 4.0F, this.getVoicePitch());
        if(level().isClientSide){
            BlockParticleOption particleOption1 = new BlockParticleOption(ParticleTypes.BLOCK, ACBlockRegistry.BLOCK_OF_URANIUM.get().defaultBlockState());
            BlockParticleOption particleOption2 = new BlockParticleOption(ParticleTypes.BLOCK, ACBlockRegistry.WASTE_DRUM.get().defaultBlockState());
            for(int i = 0; i < 8; i++){
                Vec3 particlesPos = this.getBeamShootFrom(1.0F).add(new Vec3(random.nextBoolean() ? -0.8F : 0.8F, 2, 2.5F + random.nextFloat()).scale(getScale()).xRot((float) Math.toRadians(-this.getXRot())).yRot((float) Math.toRadians(-this.getYHeadRot())));
                level().addAlwaysVisibleParticle(random.nextInt(3) == 0 ? particleOption2 : particleOption1, true, particlesPos.x, particlesPos.y, particlesPos.z, 0, 0, 0);
            }
        }
    }
    if(!level().isClientSide && this.getAnimation() == ANIMATION_CHEW && this.getAnimationTick() == 34 && lastFedPlayer != null){
        if(!this.isTame()){
            this.setTameAttempts(this.getTameAttempts() + 1);
            if (this.getTameAttempts() >= 4 && getRandom().nextInt(3) == 0) {
                this.tame(lastFedPlayer);
                this.clearRestriction();
                this.level().broadcastEntityEvent(this, (byte) 7);
            } else {
                this.level().broadcastEntityEvent(this, (byte) 6);
            }
        }
        lastFedPlayer = null;
    }
    lastStompX = xo;
    lastStompZ = zo;
}

public void aiStep() {
    super.aiStep();
    scaleParts();

    if (echoSoundCooldown > 0) {
        echoSoundCooldown--;
    }
    if (this.isSleeping()) {
        this.getNavigation().stop();
        this.setXRot(-90);
        this.whaleSpeedMod = 0;
        if (this.isEyeInFluid(FluidTags.WATER) && this.getAirSupply() < 200) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.06, 0));
        } else {
            BlockPos waterPos = this.blockPosition();
            while (level().getFluidState(waterPos).is(FluidTags.WATER) && waterPos.getY() < 255) {
                waterPos = waterPos.above();
            }
            if (waterPos.getY() - this.getY() < (isBaby() ? 7 : 12)) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.06, 0));
            }
            if (random.nextInt(100) == 0) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, random.nextGaussian() * 0.06, 0));
            }
        }
    } else {
        if (this.whaleSpeedMod == 0) {
            this.whaleSpeedMod = 1;
        }
    }
    float rPitch = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
    if (this.isGrabbing()) {
        this.setXRot(0);
    } else {
        this.setXRot(Mth.clamp(rPitch, -90, 90));
    }
    if (this.onGround() && !this.isInWaterOrBubble()) {
        this.setBeached(true);
        this.setXRot(0);
        this.setSleeping(false);
    }
    if (this.isBeached()) {
        this.whaleSpeedMod = 0;
        this.setDeltaMovement(this.getDeltaMovement().multiply(0.5, 1F, 0.5));
        if (this.isEyeInFluid(FluidTags.WATER)) {
            Player entity = this.level().getNearestPlayer(REWARD_PLAYER_PREDICATE, this);
            if (this.getLastHurtByMob() != entity) {
                rewardPlayer = entity;
            }
            this.despawnDelay = 47999;
            this.setBeached(false);
        }
    }
    if (rewardPlayer != null && !hasRewardedPlayer && this.isInWaterOrBubble()) {
        final double d0 = rewardPlayer.getX() - this.getX();
        final double d1 = rewardPlayer.getEyeY() - this.getEyeY();
        final double d2 = rewardPlayer.getZ() - this.getZ();
        final double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
        final float targetYaw = (float) (Mth.atan2(d2, d0) * Mth.RAD_TO_DEG) - 90.0F;
        final float targetPitch = (float) (-(Mth.atan2(d1, d3) * Mth.RAD_TO_DEG));
        this.setYRot((this.getYRot() + Mth.clamp(targetYaw - this.getYRot(), -2, 2)));
        this.setXRot((this.getXRot() + Mth.clamp(targetPitch - this.getXRot(), -2, 2)));
        this.yBodyRot = getYRot();
        this.whaleSpeedMod = 0.1F;
        this.getMoveControl().setWantedPosition(rewardPlayer.getX(), rewardPlayer.getY(), rewardPlayer.getZ(), 0.5D);
        if (this.distanceTo(rewardPlayer) < 10F) {
            if (!this.level().isClientSide) {
                final Vec3 vec = this.getMouthVec();
                final ItemEntity itementity = new ItemEntity(this.level(), vec.x, vec.y, vec.z, new ItemStack(AMItemRegistry.AMBERGRIS.get(), 2 + random.nextInt(2)));
                itementity.setDefaultPickUpDelay();
                level().addFreshEntity(itementity);
            }
            hasRewardedPlayer = true;
            rewardPlayer = null;
        }
    }

    prevChargingProgress = chargeProgress;
    prevSleepProgress = sleepProgress;
    prevBeachedProgress = beachedProgress;
    prevGrabProgress = grabProgress;
    if (this.tickCount % 200 == 0) {
        this.heal(2);
    }

    if (isCharging()) {
        if (this.chargeProgress < 10F)
            this.chargeProgress++;
    } else {
        if (this.chargeProgress > 0F)
            this.chargeProgress--;
    }

    if (isSleeping()) {
        if (this.sleepProgress < 10F)
            this.sleepProgress++;
    } else {
        if (this.sleepProgress > 0F)
            this.sleepProgress--;
    }

    if (isBeached()) {
        if (this.beachedProgress < 10F)
            this.beachedProgress++;
    } else {
        if (this.beachedProgress > 0F)
            this.beachedProgress--;
    }

    if (isGrabbing()) {
        if (this.grabProgress < 10F)
            this.grabProgress++;

        grabTime++;
    } else {
        if (this.grabProgress > 0F)
            this.grabProgress--;

        grabTime = 0;
    }

    this.yHeadRot = this.getYRot();
    this.yBodyRot = this.getYRot();

    if (!this.isNoAi()) {
        if (this.ringBufferIndex < 0) {
            for (int i = 0; i < this.ringBuffer.length; ++i) {
                this.ringBuffer[i][0] = this.getYRot();
                this.ringBuffer[i][1] = this.getY();
            }
        }
        this.ringBufferIndex++;
        if (this.ringBufferIndex == this.ringBuffer.length) {
            this.ringBufferIndex = 0;
        }
        this.ringBuffer[this.ringBufferIndex][0] = this.getYRot();
        this.ringBuffer[ringBufferIndex][1] = this.getY();
        Vec3[] avector3d = new Vec3[this.whaleParts.length];

        for (int j = 0; j < this.whaleParts.length; ++j) {
            this.whaleParts[j].collideWithNearbyEntities();
            avector3d[j] = new Vec3(this.whaleParts[j].getX(), this.whaleParts[j].getY(), this.whaleParts[j].getZ());
        }
        final float f15 = (float) (this.getMovementOffsets(5, 1.0F)[1] - this.getMovementOffsets(10, 1.0F)[1]) * 10.0F * Mth.DEG_TO_RAD;
        final float f16 = Mth.cos(f15);
        final float f17 = this.getYRot() * Mth.DEG_TO_RAD;
        final float pitch = this.getXRot() * Mth.DEG_TO_RAD;
        final float xRotDiv90 = Math.abs(this.getXRot() / 90F);
        final float f3 = Mth.sin(f17) * (1 - xRotDiv90);
        final float f18 = Mth.cos(f17) * (1 - xRotDiv90);

        this.setPartPosition(this.bodyPart, f3 * 0.5F, -pitch * 0.5F, -f18 * 0.5F);
        this.setPartPosition(this.bodyFrontPart, (f3) * -3.5F, -pitch * 3F, (f18) * 3.5F);
        this.setPartPosition(this.headPart, f3 * -7F, -pitch * 5F, -f18 * -7F);
        double[] adouble = this.getMovementOffsets(5, 1.0F);

        for (int k = 0; k < 3; ++k) {
            final EntityCachalotPart enderdragonpartentity;
            if (k == 0) {
                enderdragonpartentity = this.tail1Part;
            } else if (k == 1) {
                enderdragonpartentity = this.tail2Part;
            } else {
                enderdragonpartentity = this.tail3Part;
            }

            final double[] adouble1 = this.getMovementOffsets(15 + k * 5, 1.0F);
            final float f7 = this.getYRot() * Mth.DEG_TO_RAD + (float) Mth.wrapDegrees(adouble1[0] - adouble[0]) * Mth.DEG_TO_RAD;
            final float f19 = 1 - Math.abs(this.getXRot() / 90F);
            final float f20 = Mth.sin(f7) * f19;
            final float f21 = Mth.cos(f7) * f19;
            final float f22 = -3.6F;
            final float f23 = (float) (k + 1) * f22 - 2F;
            this.setPartPosition(enderdragonpartentity, -(f3 * 0.5F + f20 * f23) * f16, pitch * 1.5F * (k + 1), (f18 * 0.5F + f21 * f23) * f16);
        }

        for (int l = 0; l < this.whaleParts.length; ++l) {
            this.whaleParts[l].xo = avector3d[l].x;
            this.whaleParts[l].yo = avector3d[l].y;
            this.whaleParts[l].zo = avector3d[l].z;
            this.whaleParts[l].xOld = avector3d[l].x;
            this.whaleParts[l].yOld = avector3d[l].y;
            this.whaleParts[l].zOld = avector3d[l].z;
        }
    }
    if (!this.level().isClientSide) {
        LivingEntity target = this.getTarget();
        if (target == null || !target.isAlive()) {
            this.setGrabbing(false);
            whaleSpeedMod = this.isSleeping() ? 0 : 1;
            this.setCharging(false);
            this.setCaughtSquidId(-1);
        } else if (!isBeached() && !isSleeping() && rewardPlayer == null) {
            if (isGrabbing() && this.getTarget().isAlive()) {
                this.setCaughtSquidId(this.getTarget().getId());
                whaleSpeedMod = 0.1F;
                final float scale = this.isBaby() ? 0.5F : 1F;
                final float offsetAngle = -(float) Math.cos(grabTime * 0.3F) * 0.1F * grabProgress;
                final float renderYaw = (float) this.getMovementOffsets(0, 1.0F)[0];
                final Vec3 extraVec = new Vec3(0, 0, -3F).xRot(-this.getXRot() * Mth.DEG_TO_RAD).yRot(-renderYaw * Mth.DEG_TO_RAD);
                final Vec3 backOfHead = this.headPart.position().add(extraVec);
                final Vec3 swingVec = new Vec3(isHoldingSquidLeft() ? 1.4F : -1.4F, -0.1, 3F).xRot(-this.getXRot() * Mth.DEG_TO_RAD).yRot(-renderYaw * Mth.DEG_TO_RAD).yRot(offsetAngle);
                final Vec3 mouth = backOfHead.add(swingVec).scale(scale);
                this.getTarget().setPos(mouth.x, mouth.y, mouth.z);
                if (isHoldingSquidLeft()) {
                    this.getTarget().setYRot(this.yBodyRot + 90 - (float) Math.toDegrees(offsetAngle));
                } else {
                    this.getTarget().setYRot(this.yBodyRot - 90 - (float) Math.toDegrees(offsetAngle));
                }
                if (this.getTarget() instanceof EntityGiantSquid) {
                    if (((EntityGiantSquid) this.getTarget()).tickCaptured(this)) {
                        this.setGrabbing(false);
                        this.getTarget().setPos(this.getDismountLocationForPassenger(this.getTarget()));
                    }
                }
                if (grabTime % 20 == 0 && grabTime > 30) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), 4 + random.nextInt(4));
                }
                if (grabTime > 300) {
                    this.setGrabbing(false);
                    this.getTarget().setPos(this.getDismountLocationForPassenger(this.getTarget()));
                }
            } else {
                this.setCaughtSquidId(-1);
                this.lookAt(target, 360, 360);
                waitForEchoFlag = this.getLastHurtByMob() == null || !this.getLastHurtByMob().is(target);
                if (target instanceof Player || !target.isInWaterOrBubble()) {
                    waitForEchoFlag = false;
                }
                if (waitForEchoFlag && !receivedEcho) {
                    this.setCharging(false);
                    whaleSpeedMod = 0.25F;
                    if (echoTimer % 10 == 0) {
                        if (echoTimer % 40 == 0) {
                            this.playSound(AMSoundRegistry.CACHALOT_WHALE_CLICK.get(), this.getSoundVolume(), this.getVoicePitch());
                            this.gameEvent(GameEvent.ENTITY_ROAR);
                        }
                        final EntityCachalotEcho echo = new EntityCachalotEcho(this.level(), this);
                        final float radius = this.headPart.getBbWidth() * 0.5F;
                        final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                        final double extraX = (radius * (1F + random.nextFloat() * 0.13F)) * Mth.sin(Mth.PI + angle) + (random.nextFloat() - 0.5F) + this.getDeltaMovement().x * 2F;
                        final double extraZ = (radius * (1F + random.nextFloat() * 0.13F)) * Mth.cos(angle) + (random.nextFloat() - 0.5F) + this.getDeltaMovement().z * 2F;
                        final double x = this.headPart.getX() + extraX;
                        final double y = this.headPart.getY() + this.headPart.getBbHeight() * 0.5D;
                        final double z = this.headPart.getZ() + extraZ;
                        echo.setPos(x, y, z);
                        final double d0 = target.getX() - x;
                        final double d1 = target.getY(0.1D) - y;
                        final double d2 = target.getZ() - z;
                        echo.shoot(d0, d1, d2, 1F, 0.0F);
                        this.level().addFreshEntity(echo);
                    }
                    echoTimer++;
                }
                if (!waitForEchoFlag || receivedEcho) {
                    final double d0 = target.getX() - this.getX();
                    final double d1 = target.getEyeY() - this.getEyeY();
                    final double d2 = target.getZ() - this.getZ();
                    final double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                    final float targetYaw = (float) (Mth.atan2(d2, d0) * Mth.RAD_TO_DEG) - 90.0F;
                    final float targetPitch = (float) (-(Mth.atan2(d1, d3) * Mth.RAD_TO_DEG));
                    this.setXRot((this.getXRot() + Mth.clamp(targetPitch - this.getXRot(), -2, 2)));
                    if (d0 * d0 + d2 * d2 >= 4) {
                        this.setYRot((this.getYRot() + Mth.clamp(targetYaw - this.getYRot(), -2, 2)));
                        this.yBodyRot = getYRot();
                    }
                    if (chargeCooldown <= 0 && Math.abs(Mth.wrapDegrees(targetYaw) - Mth.wrapDegrees(this.getYRot())) < 4) {
                        this.setCharging(true);
                        whaleSpeedMod = 1.2F;
                        final double distSq = d0 * d0 + d2 * d2;
                        if (distSq < 4) {
                            this.setYRot(yRotO);
                            this.yBodyRot = yRotO;
                            this.setDeltaMovement(this.getDeltaMovement().multiply(0.8, 1, 0.8));
                        } else {
                            if (this.isInWater() && target.isInWater()) {
                                final Vec3 vector3d = this.getDeltaMovement();
                                Vec3 vector3d1 = new Vec3(target.getX() - this.getX(), target.getY() - this.getY(), target.getZ() - this.getZ());
                                if (vector3d1.lengthSqr() > 1.0E-7D) {
                                    vector3d1 = vector3d1.normalize().scale(0.5D).add(vector3d.scale(0.8D));
                                }
                                this.setDeltaMovement(vector3d1.x, vector3d1.y, vector3d1.z);
                            }
                            this.getMoveControl().setWantedPosition(target.getX(), target.getY(), target.getZ(), 1.0D);
                        }
                        if (this.isCharging()) {
                            if (this.distanceTo(target) < this.getBbWidth() && chargeProgress > 4) {
                                if (target instanceof EntityGiantSquid && !this.isBaby()) {
                                    this.setGrabbing(true);
                                    this.setHoldingSquidLeft(random.nextBoolean());
                                } else {
                                    target.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                                }
                                this.setCharging(false);
                                if (target.getVehicle() instanceof final Boat boat) {
                                    for (int i = 0; i < 3; ++i) {
                                        this.spawnAtLocation(boat.getVariant().getPlanks());
                                    }
                                    for (int j = 0; j < 2; ++j) {
                                        this.spawnAtLocation(Items.STICK);
                                    }
                                    target.removeVehicle();
                                    boat.hurt(this.damageSources().mobAttack(this), 1000);
                                    boat.remove(RemovalReason.DISCARDED);
                                }
                                chargeCooldown = target instanceof Player ? 30 : 100;
                                if (random.nextInt(10) == 0) {
                                    Vec3 vec = this.getMouthVec();
                                    ItemEntity itementity = new ItemEntity(this.level(), vec.x, vec.y, vec.z, new ItemStack(AMItemRegistry.CACHALOT_WHALE_TOOTH.get()));
                                    itementity.setDefaultPickUpDelay();
                                    level().addFreshEntity(itementity);
                                }
                            }
                        }
                    }
                }
            }
        }
        if (chargeCooldown > 0) {
            chargeCooldown--;
        }
        if (spoutTimer > 0) {
            level().broadcastEntityEvent(this, (byte) 67);
            spoutTimer--;
            this.setXRot(0);
            this.setDeltaMovement(this.getDeltaMovement().multiply(0, 0, 0));
        }
        if (isSleepTime() && !this.isSleeping() && this.isInWaterOrBubble() && this.getTarget() == null) {
            this.setSleeping(true);
        }
        if (this.isSleeping() && (!isSleepTime() || this.getTarget() != null)) {
            this.setSleeping(false);
        }
        if (target instanceof Player && ((Player) target).isCreative()) {
            this.setTarget(null);
        }
    }

    if (this.isAlive() && isCharging()) {
        for (final Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.headPart.getBoundingBox().inflate(1.0D))) {
            if (!isAlliedTo(entity) && !(entity instanceof EntityCachalotPart) && entity != this) {
                launch(entity, true);
            }
        }
    }
    if (this.isInWater() && !this.isEyeInFluid(FluidTags.WATER) && this.getAirSupply() > 140) {
        this.setDeltaMovement(this.getDeltaMovement().add(0, -0.06, 0));
    }
    if (!this.level().isClientSide) {
        this.tryDespawn();
    }
    prevEyesInWater = this.isEyeInFluid(FluidTags.WATER);
}

public void onLivingUpdate() {
    super.onLivingUpdate();


    if (!RebornConfig.ENTITIES.allowCarcass && this.isCarcass) {
        this.attackEntityFrom(DamageSource.ANVIL, 1000);
    }


    EntityLivingBase target = this.getAttackTarget();
    if (target instanceof DinosaurEntity) {
        DinosaurEntity entity = (DinosaurEntity) target;
        if (entity != null && entity.isCarcass) {
            if (this.getAttackTarget() == null) {
            } else {
                super.onLivingUpdate();
            }
        }
    }


    if(!GameRuleHandler.DINO_METABOLISM.getBoolean(this.world)) {
        if(this.getMetabolism().getEnergy() < this.getMetabolism().getMaxEnergy()) {
            this.getMetabolism().setEnergy(this.getMetabolism().getMaxEnergy());
        }

        if(this.getMetabolism().getWater() < this.getMetabolism().getMaxWater()) {
            this.getMetabolism().setWater(this.getMetabolism().getMaxWater());
        }
    }

    if(this.animation != null && EntityAnimation.getAnimation(this.animation).doesBlockMovement()) {
        this.blocked = true;
    } else {
        this.blocked = false;
    }
    if (!this.world.isRemote && this instanceof TyrannosaurusEntity) {
        if (this.moveTicks > 0) {
            this.moveTicks--;
            this.motionX = 0;
            this.motionZ = 0;
            this.motionX += MathHelper.sin(-(float) Math.toRadians(this.rotationYaw - 90)) * 0.03;
            this.motionZ += MathHelper.cos((float) Math.toRadians(this.rotationYaw - 90)) * 0.03;
            this.motionX *= 6.3;
            this.motionZ *= 6.3;
        }
        if (this.moveTicks > -5) {
            this.moveTicks--;

            if (this.moveTicks == -4) {
                this.wasMoved = true;
            }
        }
    }
    if(this.isCarcass() && (this instanceof TyrannosaurusEntity ? this.wasMoved : true) && !(this instanceof MicroraptorEntity)){
        this.motionX = 0;
        this.motionZ = 0;
    }

    if (this.breedCooldown > 0) {
        this.breedCooldown--;
    }

    if(!this.world.isRemote && dinosaur.getDiet().canEat(this, FoodType.MEAT) && this.getMetabolism().isHungry())
    {
        world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(10, 10, 10), this::canEatEntity).stream().findAny().ifPresent(this::setAttackTarget);
    }

    if (!this.isMale() && !this.world.isRemote && !this.dinosaur.isHybrid) {
        if (this.isPregnant()) {
            if (--this.pregnantTime <= 0) {
                this.navigator.clearPath();
                this.setAnimation(dinosaur.givesDirectBirth() ? EntityAnimation.GIVING_BIRTH.get() : EntityAnimation.LAYING_EGG.get());
                if(this.family != null) {
                    this.family.setHome(this.getPosition(), 6000);
                }
            }
        }
        if ((this.getAnimation() == EntityAnimation.LAYING_EGG.get() || this.getAnimation() == EntityAnimation.GIVING_BIRTH.get()) && this.animationTick == this.getAnimationLength() / 2) {
            for (DinosaurEntity child : this.children) {
                Entity entity;
                if (dinosaur.givesDirectBirth()) {
                    entity = child;
                    child.setAge(0);
                    if(this.family != null) {
                        this.family.addChild(entity.getUniqueID());
                    }
                    if(child instanceof MammothEntity){
                        ((MammothEntity) child).setVariant(((MammothEntity)this).getVariant());
                    }
                    if(child instanceof DeinotheriumEntity){
                        ((DeinotheriumEntity) child).setVariant(((DeinotheriumEntity)this).getVariant());
                    }
                    if(child instanceof SmilodonEntity){
                        ((SmilodonEntity) child).setVariant(((SmilodonEntity)this).getVariant());
                    }
                    if(child instanceof TitanisEntity){
                        ((TitanisEntity) child).setVariant(((TitanisEntity)this).getVariant());
                    }
                    if(child instanceof ParaceratheriumEntity){
                        ((ParaceratheriumEntity) child).setVariant(((ParaceratheriumEntity)this).getVariant());
                    }
                } else {
                    entity = new DinosaurEggEntity(this.world, child, this);
                    if(child instanceof CompsognathusEntity){
                        ((CompsognathusEntity) child).setVariant(((CompsognathusEntity)this).getVariant());
                    }
                    if(child instanceof AllosaurusEntity){
                        ((AllosaurusEntity) child).setVariant(((AllosaurusEntity)this).getVariant());
                    }
                    if(child instanceof ParasaurolophusEntity){
                        ((ParasaurolophusEntity) child).setVariant(((ParasaurolophusEntity)this).getVariant());
                    }
                    if(child instanceof CeratosaurusEntity){
                        ((CeratosaurusEntity) child).setVariant(((CeratosaurusEntity)this).getVariant());
                    }
                    if(child instanceof SpinoraptorEntity){
                        ((SpinoraptorEntity) child).setVariant(((SpinoraptorEntity)this).getVariant());
                    }
                    if(child instanceof IndoraptorEntity){
                        ((IndoraptorEntity) child).setVariant(((IndoraptorEntity)this).getVariant());
                    }
                    if(child instanceof BaryonyxEntity){
                        ((BaryonyxEntity) child).setVariant(((BaryonyxEntity)this).getVariant());
                    }
                    if(child instanceof DiplodocusEntity){
                        ((DiplodocusEntity) child).setVariant(((DiplodocusEntity)this).getVariant());
                    }
                    if(child instanceof AnkylodocusEntity){
                        ((AnkylodocusEntity) child).setVariant(((AnkylodocusEntity)this).getVariant());
                    }
                    if(child instanceof CamarasaurusEntity){
                        ((CamarasaurusEntity) child).setVariant(((CamarasaurusEntity)this).getVariant());
                    }
                    if(child instanceof BrachiosaurusEntity){
                        ((BrachiosaurusEntity) child).setVariant(((BrachiosaurusEntity)this).getVariant());
                    }
                    if(child instanceof AnkylosaurusEntity){
                        ((AnkylosaurusEntity) child).setVariant(((AnkylosaurusEntity)this).getVariant());
                    }
                    if(child instanceof ApatosaurusEntity){
                        ((ApatosaurusEntity) child).setVariant(((ApatosaurusEntity)this).getVariant());
                    }
                    if(child instanceof OviraptorEntity){
                        ((OviraptorEntity) child).setVariant(((OviraptorEntity)this).getVariant());
                    }
                    if(child instanceof ChasmosaurusEntity){
                        ((ChasmosaurusEntity) child).setVariant(((ChasmosaurusEntity)this).getVariant());
                    }
                    if(child instanceof StyracosaurusEntity){
                        ((StyracosaurusEntity) child).setVariant(((StyracosaurusEntity)this).getVariant());
                    }
                    if(child instanceof SinoceratopsEntity){
                        ((SinoceratopsEntity) child).setVariant(((SinoceratopsEntity)this).getVariant());
                    }
                    if(child instanceof TriceratopsEntity){
                        ((TriceratopsEntity) child).setVariant(((TriceratopsEntity)this).getVariant());
                    }
                    if(child instanceof MicroceratusEntity){
                        ((MicroceratusEntity) child).setVariant(((MicroceratusEntity)this).getVariant());
                    }
                    if(child instanceof ProtoceratopsEntity){
                        ((ProtoceratopsEntity) child).setVariant(((ProtoceratopsEntity)this).getVariant());
                    }
                    if(child instanceof VectipeltaEntity){
                        ((VectipeltaEntity) child).setVariant(((VectipeltaEntity)this).getVariant());
                    }
                }
                entity.setPosition(this.posX + (this.rand.nextFloat() - 0.5F), this.posY + 0.5F, this.posZ + (this.rand.nextFloat() - 0.5F));
                this.world.spawnEntity(entity);
            }
        }
    }
    if (!GameRuleHandler.DINO_BREEDING.getBoolean(this.world) && this.isPregnant()) {
        this.pregnantTime = 0;
        this.children.clear();
    }

    if (this.breeding != null && GameRuleHandler.DINO_BREEDING.getBoolean(this.world)) {
        if (this.ticksExisted % 10 == 0) {
            this.getNavigator().tryMoveToEntityLiving(this.breeding, 1.0);
        }
        boolean dead = this.breeding.isDead || this.breeding.isCarcass();
        if (dead || this.getEntityBoundingBox().intersects(this.breeding.getEntityBoundingBox().expand(3, 3, 3))) {                if (!dead) {
                this.breedCooldown = dinosaur.getBreedCooldown();
                if (!this.isMale()) {
                    int minClutch = dinosaur.getMinClutch();
                    int maxClutch = dinosaur.getMaxClutch();
                    for (int i = 0; i < this.rand.nextInt(maxClutch - minClutch) + minClutch; i++) {
                        try {
                            DinosaurEntity child = this.getClass().getConstructor(World.class).newInstance(this.world);
                            child.setAge(0);
                            child.setMale(this.rand.nextDouble() > 0.5);
                            child.setDNAQuality(100);
                            DinosaurAttributes attributes = DinosaurAttributes.combine(this, this.getAttributes(), this.breeding.getAttributes());
                            StringBuilder genetics = new StringBuilder();
                            for (int c = 0; c < this.genetics.length(); c++) {
                                if (this.rand.nextBoolean()) {
                                    genetics.append(this.genetics.charAt(i));
                                } else {
                                    genetics.append(this.breeding.genetics.charAt(i));
                                }
                            }
                            child.setGenetics(genetics.toString());
                            child.setAttributes(attributes);
                            child.enablePersistence();
                            this.children.add(child);
                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                    }
                    this.pregnantTime = 9600;
                }
            }
            this.breeding = null;
        }
    }

    if (this.ticksExisted % 10 == 0) {
        this.inLava = this.isInLava();
    }

    if (this.isClimbing()) {
        this.prevLimbSwingAmount = this.limbSwingAmount;
        double deltaY = (this.posY - this.prevPosY) * 4.0F;
        if (deltaY > 1.0F) {
            deltaY = 1.0F;
        }
        this.limbSwingAmount += (deltaY - this.limbSwingAmount) * 0.4F;
        this.limbSwing += this.limbSwingAmount;
    }

    if (!this.isCarcass) {
        if (this.firstUpdate) {
            this.updateAttributes();
        }

        this.updateGrowth();


        if (!this.world.isRemote) {
            if (this.metabolism.isHungry()) {
                List<EntityItem> entitiesWithinAABB = this.world.getEntitiesWithinAABB(EntityItem.class, this.getEntityBoundingBox().expand(1.0, 1.0, 1.0));
                for (EntityItem itemEntity : entitiesWithinAABB) {
                    Item item = itemEntity.getItem().getItem();
                    if (FoodHelper.isEdible(this, dinosaur.getDiet(), item)) {
                        this.setAnimation(EntityAnimation.EATING.get());

                        if (itemEntity.getItem().getCount() > 1) {
                            itemEntity.getItem().shrink(1);
                        } else {
                            itemEntity.setDead();
                        }

                        this.getMetabolism().eat(FoodHelper.getHealAmount(item));
                        FoodHelper.applyEatEffects(this, item);
                        this.heal(10.0F);

                        break;
                    }
                }
            }

            this.metabolism.update();
        }

        if (this.ticksExisted % 62 == 0) {
            this.playSound(this.getBreathingSound(), this.getSoundVolume(), this.getSoundPitch());
        }

        if (!dinosaur.isMarineCreature()) {
            if (this.isInsideOfMaterial(Material.WATER) || (this.getNavigator().noPath() && this.inWater() || this.inLava())) {
                this.getJumpHelper().setJumping();
            } else {
                if (this.isSwimming()) {
                    Path path = this.getNavigator().getPath();
                    if (path != null) {
                        AxisAlignedBB detectionBox = this.getEntityBoundingBox().expand(0.5, 0.5, 0.5);
                        if (this.world.collidesWithAnyBlock(detectionBox)) {
                            List<AxisAlignedBB> colliding = this.world.getCollisionBoxes(this.getAttackingEntity(), detectionBox);
                            boolean swimUp = false;
                            for (AxisAlignedBB bound : colliding) {
                                if (bound.maxY > this.getEntityBoundingBox().minY) {
                                    swimUp = true;
                                    break;
                                }
                            }
                            if (swimUp) {
                                this.getJumpHelper().setJumping();
                            }
                        }
                    }
                }
            }
        }

        if (this.herd == null) {
            this.herd = new Herd(this);
        }

        if (!this.world.isRemote) {
            if (this.order == Order.WANDER) {
                if (this.herd.state == Herd.State.IDLE && this.getAttackTarget() == null && !this.metabolism.isThirsty() && !this.metabolism.isHungry() && this.getNavigator().noPath()) {
                    if (!this.isSleeping && this.onGround && !this.isInWater() && this.getAnimation() == EntityAnimation.IDLE.get() && this.rand.nextInt(800) == 0) {
                        this.setAnimation(EntityAnimation.RESTING.get());
                        this.isSittingNaturally = true;
                    }
                } else if (this.getAnimation() == EntityAnimation.RESTING.get()) {
                    this.setAnimation(EntityAnimation.IDLE.get());
                    this.isSittingNaturally = false;
                }
            }

            if (this == this.herd.leader && !this.dinosaur.isMarineCreature()) {
                this.herd.update();
                //\\\this.tasks.addTask(3, new DinosaurHerdWanderEntityAI(this.herd, 0.8D, 2, 25));
                //} else {
                //this.tasks.removeTask(new DinosaurWanderEntityAI(this, 0.8D, 2, 10));
                //this.tasks.removeTask(new DinosaurHerdWanderEntityAI(this.herd, 0.8D, 2, 25));
            }

            if (this.ticksExisted % 10 == 0) {
                if (this.family != null && (this.family.getHead() == null || this.family.getHead().equals(this.getUniqueID()))) {
                    if (this.family.update(this)) {
                        this.family = null;
                    }
                } else if (this.family == null && this.getAttackTarget() == null) {
                    if (this.relationships.size() > 0 && this.rand.nextDouble() > 0.9) {
                        DinosaurEntity chosen = null;
                        Relationship chosenRelationship = null;
                        for (Relationship relationship : this.relationships) {
                            if (relationship.getScore() > Relationship.MAX_SCORE * 0.9) {
                                DinosaurEntity entity = relationship.get(this);
                                if (entity != null && this.isMale != entity.isMale) {
                                    chosen = entity;
                                    chosenRelationship = relationship;
                                    break;
                                }
                            }
                        }
                        if (chosen != null) {
                            this.family = new Family(this.getUniqueID(), chosen.getUniqueID());
                            chosenRelationship.setFamily();
                            this.breedCooldown = this.rand.nextInt(1000) + 1000;
                            chosen.breedCooldown = this.breedCooldown;
                        }
                    }
                }
                if (this.herd != null) {
                    for (DinosaurEntity herdMember : this.herd.members) {
                        if (herdMember != this) {
                            Relationship relationship = this.getRelationship(herdMember, true);
                            relationship.updateHerd(this);
                        }
                    }
                    for (EntityLivingBase enemy : this.herd.enemies) {
                        if (enemy instanceof DinosaurEntity) {
                            Relationship relationship = new Relationship(enemy.getUniqueID(), (short) -30);
                            if (!this.relationships.contains(relationship)) {
                                this.relationships.add(relationship);
                            }
                        }
                    }
                }
                if (this.relationships.size() > 0) {
                    Set<Relationship> removal = new HashSet<>();
                    for (Relationship relationship : this.relationships) {
                        if (relationship.update(this)) {
                            removal.add(relationship);
                        }
                    }
                    this.relationships.removeAll(removal);
                }
            }

            if (!this.getNavigator().noPath()) {
                if (this.isSittingNaturally && this.getAnimation() == EntityAnimation.RESTING.get()) {
                    this.setAnimation(EntityAnimation.IDLE.get());
                    this.isSittingNaturally = false;
                }
            }
        }
    }

    if (this.isServerWorld()) {
        this.lookHelper.onUpdateLook();
    }

    if(this.getDoesEatEggs()){
        eatEggs();
    }

    if(!this.world.isRemote && this.ticksExisted % 20 == 0)
        this.dataManager.set(WATCHER_WAS_FED, false);
}

