public boolean cycleMode(Player player) {
    var template = getTemplate();

    if (template == null || template.getModes().isEmpty())
        return false;

    var stack = this.getAbilitiesData().getRelicData().getStack();
    var event = new AbilityModeSwitchEvent(player, stack, this.getId(), getMode(), getNextMode());

    NeoForge.EVENT_BUS.post(event);

    if (event.isCanceled())
        return false;

    setMode(event.getToMode());

    return true;
}

protected void onHit(HitResult result) {
    super.onHit(result);

    if (this.getOwner() instanceof Player player && result instanceof EntityHitResult entityResult && entityResult.getEntity() instanceof LivingEntity entity && !entity.getStringUUID().equals(player.getStringUUID())) {
        entity.invulnerableTime = 0;

        var stack = getRelicStack();

        if (entity.hurt(getCommandSenderWorld().damageSources().thrown(this, player), getDamage())) {
            if (this.isOnFire())
                entity.igniteForTicks(this.getRemainingFireTicks());

            entity.addEffect(new MobEffectInstance(RelicsMobEffects.ANTI_HEAL, 0, 20 * 5, false, false), player);
        }
    }

    this.discard();
}

