private static void finishParry(Player player, ItemStack stack, boolean evaluateMiss) {
    var wasActive = getActiveTicks(stack) > 0 || !getCapturedProjectiles(stack).isEmpty();

    releaseCapturedProjectiles(player, stack);

    if (evaluateMiss && !hasSucceeded(stack) && stack.getItem() instanceof ShieldOfRetaliationItem relic
            && relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation").canPlayerUse(player)) {
        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");

        setMissed(stack, true);
        setMissedTicks(stack, Math.max(1, (int) Math.round(ability.getStatData("miss_duration").getValue() * 20D)));
    }

    if (wasActive && stack.getItem() instanceof ShieldOfRetaliationItem relic) {
        var cooldown = relic.getCooldownTicks(player, stack);

        if (cooldown > 0)
            player.getCooldowns().addCooldown(relic, cooldown);
    }

    setActiveTicks(stack, 0);
    setActiveDuration(stack, 0);
    setSucceeded(stack, false);
    setReleaseLocked(stack, true);
}

public static void onLivingDamage(LivingDamageEvent.Pre event) {
    var entity = event.getEntity();
    var original = event.getOriginalDamage();
    double resistedTotal = 0D;

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.ROLLER_SKATE.get())) {
        var relic = (RollerSkateItem) stack.getItem();

        var duration = relic.getDuration(stack);

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").canPlayerUse(entity) || !relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getRankModifierData("resistance").isEnabled() || duration <= 0)
            continue;

        var modifier = (float) (original * (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatData("resistance").getValue() * ((float) duration / relic.getMaxDuration())));

        relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("damage_resisted").addValue(modifier);

        relic.getRelicData(entity, stack).getLevelingData().addExperience("skating", "resisting_damage", modifier);

        resistedTotal += modifier;
    }

    if (resistedTotal > 0D)
        event.setNewDamage((float) Math.max(0D, original - resistedTotal));
}

public static void addModifierNames(ItemStack stack, IToolStackView tool, @Nullable Player player, List<Component> tooltips, TooltipFlag flag) {
  RegistryAccess access = player == null ? null : player.level().registryAccess();
  for (ModifierEntry entry : tool.getModifierList()) {
    if (entry.getModifier().shouldDisplay(ModifierTooltip.TOOL)) {
      Component name = entry.getModifier().getDisplayName(tool, entry, access);
      if (flag.isAdvanced() && Config.CLIENT.modifiersIDsInAdvancedTooltips.get()) {
        tooltips.add(Component.translatable(KEY_ID_FORMAT, name, Component.literal(entry.getModifier().getId().toString())).withStyle(ChatFormatting.DARK_GRAY));
      } else {
        tooltips.add(name);
      }
    }
  }
  if (!stack.isEmpty()) {
    CompoundTag tag = stack.getTag();
    if (tag != null && tag.contains("Enchantments", Tag.TAG_LIST)) {
      ListTag enchantments = tag.getList("Enchantments", Tag.TAG_COMPOUND);
      for (int i = 0; i < enchantments.size(); ++i) {
        CompoundTag enchantmentTag = enchantments.getCompound(i);
        // TODO: is this the best place for this, or should we let vanilla run?
        BuiltInRegistries.ENCHANTMENT.getOptional(ResourceLocation.tryParse(enchantmentTag.getString("id")))
                                     .ifPresent(enchantment -> tooltips.add(enchantment.getFullname(enchantmentTag.getInt("lvl"))));
      }
    }
  }
}

public void wornTick(CureEffects ability, EquipmentSlotAccess slot, LivingEntity entity, boolean isOnCooldown, boolean isDisabled) {
    if (isDisabled || isOnCooldown || !ability.isNonCosmetic()) {
        return;
    }
    Map<Holder<MobEffect>, MobEffectInstance> effects = new HashMap<>();

    int maxEffectDuration = ability.maxEffectDuration().get() * 20;
    entity.getActiveEffectsMap().forEach((effect, instance) -> {
        if (effect.is(ModTags.ANTIDOTE_VESSEL_CANCELLABLE) && !instance.endsWithin(maxEffectDuration) && !instance.isInfiniteDuration()) {
            effects.put(effect, instance);
        }
    });

    effects.forEach((effect, instance) -> {
        entity.removeEffectNoUpdate(effect);
        if (maxEffectDuration > 0) {
            entity.addEffect(new MobEffectInstance(effect, maxEffectDuration, instance.getAmplifier(), instance.isAmbient(), instance.isVisible(), instance.showIcon()));
        }
    });

    if (!effects.isEmpty()) {
        slot.hurtAndBreak(ability.itemDamage.get());
        slot.addCooldown(2 * 20);
    }
}

public static void onLivingTick(EntityTickEvent.Post event) {
    if (!(event.getEntity() instanceof LivingEntity entity) || entity.level().isClientSide())
        return;

    var total = 0F;

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.LEAFY_MANTLE.get())) {
        var relic = (LeafyMantleItem) stack.getItem();

        if (!relic.isHiding(stack) || relic.getCurrentProgress(stack) < relic.getMaxProgress())
            continue;

        if (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").canPlayerUse(entity) && relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getRankModifierData("absorption").isEnabled())
            total += (float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getStatData("absorption").getValue();
    }

    var current = entity.getAbsorptionAmount();
    var cap = Math.max(current, total);

    if (cap > 0F) {
        EntityUtils.resetAttribute(entity, Attributes.MAX_ABSORPTION, cap, AttributeModifier.Operation.ADD_VALUE, ATTRIBUTE);

        if (current < total)
            entity.setAbsorptionAmount(total);
    }
}

private void checkTotemDeathProtection(DamageSource killingDamage, CallbackInfoReturnable<Boolean> cir) {
    LivingEntity self = (LivingEntity) (Object) this;

    // finds the first equipped totem with the equipable_totem component
    ItemStack totem = EquipableTotem.findTotem(self);

    // identical to the remainder of the logic in checkTotemDeathProtection
    // injecting on the variable assignments instead of HEAD might simplify this somewhat
    if (!killingDamage.is(DamageTypeTags.BYPASSES_INVULNERABILITY) && totem != null) {
        DeathProtection deathProtection = Objects.requireNonNull(totem.get(DataComponents.DEATH_PROTECTION));
        ItemStack copy = totem.copy();
        totem.shrink(1);

        if (self instanceof ServerPlayer serverPlayer) {
            serverPlayer.awardStat(Stats.ITEM_USED.get(copy.getItem()));
            CriteriaTriggers.USED_TOTEM.trigger(serverPlayer, copy);
            copy.causeUseVibration(self, GameEvent.ITEM_INTERACT_FINISH);
        }

        self.setHealth(1F);
        deathProtection.applyEffects(copy, self);
        self.level().broadcastEntityEvent(self, EntityEvent.PROTECTED_FROM_DEATH);

        cir.setReturnValue(true); // early return intended!
    }
}

private static int stunNearbyTargets(Player player, ItemStack stack) {
    if (!(stack.getItem() instanceof ShieldOfRetaliationItem relic))
        return 0;

    var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");

    if (!ability.getRankModifierData("stun").isEnabled())
        return 0;

    var stunned = 0;
    var radius = ability.getStatData("stun_radius").getValue();
    var stunTicks = (int) Math.round(ability.getStatData("stun").getValue() * 20D);
    var view = player.getViewVector(1F);

    for (var target : player.level().getEntitiesOfClass(LivingEntity.class, player.getBoundingBox().inflate(radius), target -> TargetingUtils.canHarm(player, target, stack, "retaliation"))) {
        var direction = target.position().subtract(player.position());
        direction = new Vec3(direction.x, 0D, direction.z);

        if (direction.lengthSqr() > 0.0001D && direction.normalize().dot(view) <= 0D)
            continue;

        if (TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.STUN, stunTicks, 0, false, false), player, stack, "retaliation"))
            stunned++;
    }

    return stunned;
}

public static void onLivingDamage(LivingDamageEvent.Pre event) {
    if (!(event.getSource().getEntity() instanceof Player player))
        return;

    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
        var relic = (GhostlyMantleItem) stack.getItem();
        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("gaze");

        if (!ability.canPlayerUse(player) || !ability.getRankModifierData("dread").isEnabled())
            continue;

        if (!TargetingUtils.canHarm(player, event.getEntity(), stack, "gaze"))
            continue;

        var charges = relic.getTotalCharges(stack);

        if (charges <= 0)
            continue;

        var extra = event.getNewDamage() * charges * ability.getStatData("damage").getValue();

        event.setNewDamage((float) (event.getNewDamage() + extra));
        ability.getStatisticData().getMetricData("damage_bonus").addValue(extra);

        return;
    }
}

public static void onLivingHurt2(LivingIncomingDamageEvent event) {
    if (!(event.getSource().getEntity() instanceof LivingEntity entity))
        return;

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.MIDNIGHT_MANTLE.get())) {
        var relic = (MidnightMantleItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").canPlayerUse(entity) || !relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").getRankModifierData("strike").isEnabled()
                || relic.getInvisibilityCooldown(stack) > 0 || !relic.canHideInTheDarkness(entity, stack))
            continue;

        if (!TargetingUtils.canHarm(entity, event.getEntity(), stack, "invisibility"))
            continue;

        var damage = event.getAmount() * relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").getStatData("damage").getValue();

        event.setAmount((float) (event.getAmount() + damage));

        if (!entity.level().isClientSide()) {
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").getStatisticData().getMetricData("additional_damage").addValue(damage);

            relic.getRelicData(entity, stack).getLevelingData().addExperience("invisibility", "damage_dealing", 1);
        }

        relic.setInvisibilityCooldown(stack, (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").getStatData("cooldown").getValue());
    }
}

public static void onLivingDamage1(LivingDamageEvent.Post event) {
    var target = event.getEntity();

    if (!(event.getSource().getEntity() instanceof LivingEntity source) || target instanceof AbstractPiglin)
        return;

    var level = source.level();

    for (var stack : EntityUtils.findEquippedCurios(source, RelicsItems.PIGLIN_MASK.get())) {
        var relic = (PiglinMaskItem) stack.getItem();

        if (!relic.getRelicData(source, stack).getAbilitiesData().getAbilityData("neutrality").getRankModifierData("legion").isEnabled())
            continue;

        for (var piglin : level.getEntitiesOfClass(Mob.class, source.getBoundingBox().inflate(32), mob -> mob instanceof Piglin || mob instanceof ZombifiedPiglin)) {
            if (piglin.getTarget() != null || !piglin.hasLineOfSight(target) || piglin.isBaby())
                continue;

            relic.getRelicData(source, stack).getLevelingData().addExperience("neutrality", "target", 1);
            relic.getRelicData(target, stack).getAbilitiesData().getAbilityData("neutrality").getStatisticData().getMetricData("target").addValue(1);

            piglin.getBrain().setMemory(MemoryModuleType.ANGRY_AT, target.getUUID());

            piglin.setTarget(target);
        }
    }
}

private void shouldConsumeEnderPearl(ItemStack stack, int amount, LivingEntity owner, Operation<Void> operation) {
    if (ModDataComponents.ENDER_PEARL_HUNGER_COST.on(owner).findAny() && owner instanceof Player player) {
        int cost = ModDataComponents.ENDER_PEARL_HUNGER_COST.on(player)
                .minInt(20, ability -> ability.foodCost().get());
        if (player.getFoodData().getFoodLevel() >= cost || player.isCreative()) {
            if (cost > 0 && !player.isCreative()) {
                player.getFoodData().setFoodLevel(player.getFoodData().getFoodLevel() - cost);
                owner.level().playSound(
                        null,
                        player.getX(),
                        player.getY(),
                        player.getZ(),
                        SoundEvents.GENERIC_EAT,
                        SoundSource.PLAYERS,
                        0.5F,
                        0.8F + owner.getRandom().nextFloat() * 0.4F
                );
            }
            ModDataComponents.ENDER_PEARL_HUNGER_COST.on(player).iterate((ability, slot) -> {
                slot.addCooldown(ability.cooldown().get() * 20);
                slot.hurtAndBreak(ability.itemDamage().get());
            });
            return;
        }
    }
    operation.call(stack, amount, owner);
}

public static void addTransientAttributeModifiers(LivingEntity livingEntity, AccessoryAttributeBuilder attributes) {
    if(attributes.isEmpty()) return;

    var attributeMap = livingEntity.getAttributes();
    var capability = livingEntity.accessoriesCapability();

    var containers = capability.getContainers();

    attributes.getSlotModifiers().asMap().forEach((s, modifiers) -> {
        var container = containers.get(s);

        if(container == null) return;

        modifiers.stream()
                .filter(modifier -> !container.hasModifier(modifier.id()))
                .forEach(container::addTransientModifier);
    });

    attributes.getAttributeModifiers(true).asMap().forEach((holder, modifiers) -> {
        var instance = attributeMap.getInstance(holder);

        if(instance == null) return;

        modifiers.stream()
                .filter(modifier -> !instance.hasModifier(modifier.id()))
                .forEach(instance::addTransientModifier);
    });
}

public static void removeTransientAttributeModifiers(LivingEntity livingEntity, AccessoryAttributeBuilder attributes) {
    if(attributes.isEmpty()) return;

    var attributeMap = livingEntity.getAttributes();
    var capability = livingEntity.accessoriesCapability();

    var containers = capability.getContainers();

    attributes.getSlotModifiers().asMap().forEach((s, modifiers) -> {
        var container = containers.get(s);

        if(container == null) return;

        modifiers.stream()
                .map(AttributeModifier::id)
                .forEach(container::removeModifier);
    });

    attributes.getAttributeModifiers(true).asMap().forEach((holder, modifiers) -> {
        var instance = attributeMap.getInstance(holder);

        if(instance == null) return;

        modifiers.stream()
                .map(AttributeModifier::id)
                .forEach(instance::removeModifier);
    });
}

protected void onHitEntity(EntityHitResult result) {
    if (!(result.getEntity() instanceof LivingEntity entity) || this.impactedEntities.contains(entity.getStringUUID())
            || (!(this.getOwner() instanceof LivingEntity owner) || entity.getStringUUID().equals(owner.getStringUUID()))
            || !TargetingUtils.canHarm(owner, entity, this.getStack(), "revival"))
        return;

    var level = this.level();

    entity.invulnerableTime = 0;

    if (TargetingUtils.hurtEnemy(entity, level.damageSources().thrown(owner, this), this.getDamage(), this.getStack(), "revival")) {
        var paralysis = this.getParalysis();

        if (paralysis > 0)
            TargetingUtils.addHarmfulEffect(entity, new MobEffectInstance(RelicsMobEffects.PARALYSIS, (int) (paralysis * 20), 0, false, false), owner, this.getStack(), "revival");

        if (stack.getItem() instanceof LeafyMantleItem relic) {
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("damage_dealt").addValue(this.getDamage());

            if (!level.isClientSide())
                relic.getRelicData(entity, stack).getLevelingData().addExperience("revival", "leaves_impact", 1);

            if (paralysis > 0)
                relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("paralysis_duration").addValue(paralysis);
        }
    }

    this.impactedEntities.add(entity.getStringUUID());
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    super.curioTick(slotContext, stack);

    var entity = slotContext.entity();
    var level = entity.level();

    if (level.isClientSide())
        return;

    var cooldown = this.getBounceCooldown(stack);
    var leaped = this.isLeaped(stack);
    var leaps = this.getLeaps(stack);

    if (entity.tickCount % 20 == 0 && (leaped || leaps > 0))
        this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("bounce_duration").addValue(1);

    if (cooldown > 0)
        this.addBounceCooldown(stack, -1);

    if (leaped) {
        if (entity.isInLiquid() || entity.isFallFlying() || (entity instanceof Player player && player.getAbilities().flying)) {
            this.setLeaped(stack, false);
            this.setLeaps(stack, 0);
        }

        if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("bounce").getRankModifierData("disappearance").isEnabled() && leaps <= 0)
            entity.addEffect(new MobEffectInstance(RelicsMobEffects.VANISHING, 5, 0, false, false));
    }
}

