        for (var piglin : level.getEntitiesOfClass(Mob.class, target.getBoundingBox().inflate(32), mob -> mob instanceof Piglin || mob instanceof ZombifiedPiglin)) {
            if (piglin.getTarget() != null || !piglin.hasLineOfSight(source) || piglin.isBaby())
                continue;

            relic.getRelicData(target, stack).getLevelingData().addExperience("neutrality", "target", 1);
            relic.getRelicData(target, stack).getAbilitiesData().getAbilityData("neutrality").getStatisticData().getMetricData("target").addValue(1);

            piglin.getBrain().setMemory(MemoryModuleType.ANGRY_AT, source.getUUID());

            if (source instanceof LivingEntity)
                piglin.setTarget((LivingEntity) source);
        }
    }
}

public void onUsingTick(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int useDuration, int timeLeft, ModifierEntry activeModifier) {
  // mark the tool with whether we can drink; don't play particles if simulate does nothing
  int useTime = useDuration - timeLeft;
  boolean notActive = modifier != activeModifier;
  if (notActive && useTime == 0) {
    FluidStack fluid = TANK_HELPER.getFluid(tool);
    if (!fluid.isEmpty() && slurp(fluid, modifier, entity, asPlayer(entity), FluidAction.SIMULATE) > 0) {
      tool.getPersistentData().putBoolean(modifier.getId(), true);
    }
  }

  // if we reached the end, finish drinking; don't have to release the current use
  int duration = getUseDuration(tool, modifier);
  if (notActive && useTime == duration) {
    finishDrinking(tool, modifier, entity, true);
    tool.getPersistentData().remove(modifier.getId());
  }
  // if we have not finished drinking, and we can drink, play effects
  else if (useTime < duration && useTime % 4 == 0 && (!notActive || tool.getPersistentData().getBoolean(modifier.getId()))) {
    FluidStack fluid = TANK_HELPER.getFluid(tool);
    if (!fluid.isEmpty()) {
      addFluidParticles(entity, fluid, 5);
      // add drinking sounds if blocking or using another modifier
      if (notActive) {
        entity.playSound(SoundEvents.GENERIC_DRINK, 0.5F, entity.getRandom().nextFloat() * 0.1f + 0.9f);
      }
    }
  }
}

private static int addModifier(CommandContext<CommandSourceStack> ctx, Holder<Attribute> holder, ResourceLocation resourceLocation, double d, AttributeModifier.Operation operation, String slotName, boolean isStackable, boolean usedInSlotValidation) throws CommandSyntaxException {
    var commandSourceStack = ctx.getSource();

    if (operation == null) {
        commandSourceStack.sendFailure(Component.literal("Unable to locate AttributeModifier Operation type passed to the command!"));

        return -1;
    }

    var livingEntity = ctx.getSource().getPlayerOrException();
    var stack = livingEntity.getMainHandItem();

    var component = stack.getOrDefault(AccessoriesDataComponents.ATTRIBUTES, AccessoryItemAttributeModifiers.EMPTY);

    if (component.hasModifier(holder, resourceLocation)) {
        throw ERROR_MODIFIER_ALREADY_PRESENT.create(resourceLocation, getAttributeDescription(holder), stack.getDisplayName());
    }

    stack.set(AccessoriesDataComponents.ATTRIBUTES, component.withModifierAdded(holder, new AttributeModifier(resourceLocation, d, operation), slotName, isStackable, usedInSlotValidation));

    commandSourceStack.sendSuccess(
            () -> Component.translatable(
                    "accessories.commands.attribute.modifier.add.success_itemstack", Component.translationArg(resourceLocation), getAttributeDescription(holder), stack.getDisplayName()
            ),
            false
    );

    return 1;
}

protected void onHitEntity(EntityHitResult result) {
    if (!(result.getEntity() instanceof LivingEntity entity) || (!(this.getOwner() instanceof LivingEntity owner) || entity.getStringUUID().equals(owner.getStringUUID()))
            || !TargetingUtils.canHarm(owner, entity, this.getStack(), "skating"))
        return;

    entity.invulnerableTime = 0;

    var damage = this.getDamage();

    if (TargetingUtils.hurtEnemy(entity, this.level().damageSources().thrown(owner, this), this.getDamage(), this.getStack(), "skating")) {
        var ignite = this.getIgnite();
        var toApply = (int) (ignite * 20);
        var current = entity.getRemainingFireTicks();
        var diff = toApply - current;

        if (ignite > 0)
            entity.setRemainingFireTicks(Math.max(toApply, current));

        this.discard();

        if (stack.getItem() instanceof RollerSkateItem relic) {
            relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("damage_dealt").addValue(damage);

            relic.getRelicData(owner, stack).getLevelingData().addExperience("skating", "spark_hit", 1);

            if (diff > 0)
                relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("ignite_duration").addValue(diff / 20F);
        }
    }
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    super.curioTick(slotContext, stack);

    var entity = slotContext.entity();

    var duration = this.getDuration(stack);
    var stacks = this.getStacks(stack);

    if (entity.tickCount % 20 == 0) {
        if (duration > 0 || stacks > 0) {
            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("looting").getStatisticData().getMetricData("effect_duration").addValue(1);

            if (stacks >= PiglinMaskItem.getMaxStacks())
                this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("looting").getStatisticData().getMetricData("tripled_effect_duration").addValue(1);
        }

        if (duration > 0) {
            this.addDuration(entity, stack, -1);
        } else if (stacks > 0) {
            if (stacks >= PiglinMaskItem.getMaxStacks())
                this.setStacks(stack, 0);
            else
                this.addStacks(stack, -1);
        }

        var modifier = stacks >= PiglinMaskItem.getMaxStacks() ? 3 : 1;

        EntityUtils.resetAttribute(entity, stack, Attributes.ATTACK_SPEED, (float) (stacks * this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("looting").getStatData("attack_speed").getValue() * modifier), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
    }
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
