private static List<LivingEntity> updateEntities(CommandContext<CommandSourceStack> context, BiPredicate<IToolStackView,StatOverrideModifier> updateAction) throws CommandSyntaxException {
  return HeldModifiableItemIterator.apply(context, (living, stack) -> {
    ToolStack tool = ToolStack.copyFrom(stack);

    // apply the proper operation
    StatOverrideModifier stats = TinkerModifiers.statOverride.get();
    boolean needsModifier = updateAction.test(tool, stats);

    // ensure the modifier is present if needed/not present if not needed
    int level = tool.getUpgrades().getLevel(stats.getId());
    boolean hasModifier = level > 0;
    if (needsModifier && !hasModifier) {
      tool.addModifier(stats.getId(), 1);
    } else if (hasModifier && !needsModifier) {
      tool.removeModifier(stats.getId(), level);
    } else {
      tool.rebuildStats();
    }

    // ensure the tool is still valid
    Component validated = tool.tryValidate();
    if (validated != null) {
      throw MODIFIER_ERROR.create(validated);
    }

    // if successful, update held item
    living.setItemInHand(InteractionHand.MAIN_HAND, tool.copyStack(stack));
    return true;
  });
}

public void tick() {
    float xj = (this.random.nextFloat() * .001f * wander * (this.random.nextBoolean() ? 1 : -1));
    float yj = (this.random.nextFloat() * .001f * wander * (this.random.nextBoolean() ? 1 : -1)) + .00025f;
    float zj = (this.random.nextFloat() * .001f * wander * (this.random.nextBoolean() ? 1 : -1));
    wander *= .98f;
    if (onGround) {
        yd = Math.abs(yd);
    }
    this.xd += xj;
    this.yd += yj;
    this.zd += zj;
    if (--litTimer <= 0) {
        lit = !lit;
        litTimer = random.nextIntBetweenInclusive(5, 20);
        //this.setSprite(sprites.get(lit ? 0 : 1, 1));
    }
    if (lit) {
        litTween = Mth.lerp(flickerIntensity, litTween, 1);
    } else {
        litTween = Mth.lerp(flickerIntensity, litTween, 0);
    }
    this.rCol = Mth.lerp(litTween, unlitColor.x(), litColor.x());
    this.gCol = Mth.lerp(litTween, unlitColor.y(), litColor.y());
    this.bCol = Mth.lerp(litTween, unlitColor.z(), litColor.z());
    if (age >= lifetime - 1 && litTween > .1f) {
        //they are only allowed to die if they have faded out
        lifetime++;
    }
    super.tick();
}

public void processTargets() {
    var level = this.level();
    var center = this.getCenter().getCenter();

    var owner = this.getOwner();

    for (var entity : level.getEntitiesOfClass(Entity.class, this.getBoundingBox(), entity -> !(entity instanceof ShockwaveBlockEntity) && (owner == null || !owner.getStringUUID().equals(entity.getStringUUID())))) {
        var motion = entity.position().add(0F, 1F, 0F).subtract(center).normalize().scale(this.getKnockback());

        if (entity instanceof LivingEntity livingEntity) {
            if (!(owner instanceof LivingEntity livingOwner) || !TargetingUtils.canHarm(livingOwner, livingEntity, this.getStack(), "bounce"))
                continue;

            if (entity instanceof ServerPlayer player)
                NetworkHandler.sendToClient(new S2CSetEntityMotion(entity.getId(), motion.toVector3f()), player);
            else
                entity.setDeltaMovement(motion);

            var damage = this.getDamage();

            if (TargetingUtils.hurtEnemy(livingEntity, level.damageSources().explosion(livingOwner, this), damage, this.getStack(), "bounce")) {
                var stun = this.getStun();

                if (stun > 0)
                    TargetingUtils.addHarmfulEffect(livingEntity, new MobEffectInstance(RelicsMobEffects.STUN, stun, 0, false, false), livingOwner, this.getStack(), "bounce");
            }
        } else {
            entity.setDeltaMovement(motion);
        }
    }
}

public static boolean stopArmorInteract(Player player, EquipmentSlot slotType) {
  if (!player.isSpectator()) {
    ItemStack helmet = player.getItemBySlot(slotType);
    if (helmet.is(TinkerTags.Items.ARMOR)) {
      ToolStack tool = ToolStack.from(helmet);
      // fetch interaction data if present
      int chargeTime = 0;
      ModifierEntry activeModifier = ModifierEntry.EMPTY;
      TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
      if (data != null) {
        Map<EquipmentSlot,ArmorInteractData> interactMap = data.get(INTERACT_KEY);
        if (interactMap != null) {
          ArmorInteractData interactData = interactMap.remove(slotType);
          if (interactData != null) {
            activeModifier = tool.getModifier(interactData.modifier);
            chargeTime = player.tickCount - interactData.startTime;
          }
        }
      }
      // run modifier hook for stop interact
      // TODO 1.21: consider only running hook on the active modifier
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.ARMOR_INTERACT).stopInteract(tool, entry, player, slotType, chargeTime, activeModifier);
      }
      // cleanup drawtime on the tool
      GeneralInteractionModifierHook.finishUsing(tool);
      return true;
    }
  }
  return false;
}

private static int removeModifier(CommandContext<CommandSourceStack> ctx, Holder<Attribute> holder, ResourceLocation location) throws CommandSyntaxException {
    var commandSourceStack = ctx.getSource();
    var livingEntity = ctx.getSource().getPlayerOrException();

    MutableBoolean removedModifier = new MutableBoolean(false);

    var stack = livingEntity.getMainHandItem();

    stack.update(AccessoriesDataComponents.ATTRIBUTES, AccessoryItemAttributeModifiers.EMPTY, component -> {
        var size = component.modifiers().size();

        component = component.withoutModifier(holder, location);

        if(size != component.modifiers().size()) removedModifier.setTrue();

        return component;
    });

    if(!removedModifier.getValue()) {
        throw ERROR_NO_SUCH_MODIFIER.create(location, stack.getDisplayName(), getAttributeDescription(holder));
    }

    commandSourceStack.sendSuccess(
            () -> Component.translatable(
                    "accessories.commands.attribute.modifier.remove.success_itemstack", Component.translationArg(location), getAttributeDescription(holder), stack.getDisplayName()
            ),
            false
    );

    return 1;
}

public void tick() {
    if (tickCount % 20 == 0) {
        if (!isDormant || level().isClientSide()
                || !onGround() || isDeadOrDying()
                || isPassenger() || !getPassengers().isEmpty()
                || level().getNearestPlayer(this, 32) != null) {
            tickRate = 1;
        } else {
            tickRate = DORMANT_TICK_RATE;
        }
    }

    if (tickCount % tickRate != 0) {
        return;
    }
    super.tick();

    if (isInWater()) {
        ticksInAir = 0;
    } else if (!onGround()) {
        ticksInAir++;
    } else {
        if (ticksInAir > 0) {
            playSound(getLandingSound(), getSoundVolume(), getVoicePitch());
            ticksInAir = 0;
        }
    }

    if (attackCooldown > 0) {
        attackCooldown--;
    }
}

public static void onEntityTick(EntityTickEvent.Post event) {
    if (!(event.getEntity() instanceof Player player))
        return;

    var abilities = player.getAbilities();
    var hasEffect = player.hasEffect(RelicsMobEffects.FLIGHT);
    var hadEffect = player.getPersistentData().getBoolean(FLIGHT_TAG);

    if (hasEffect) {
        player.getPersistentData().putBoolean(FLIGHT_TAG, true);
        player.fallDistance = 0F;

        if (!abilities.mayfly || !abilities.flying) {
            abilities.mayfly = true;
            abilities.flying = true;
            player.onUpdateAbilities();
        }

        return;
    }

    if (!hadEffect)
        return;

    player.getPersistentData().remove(FLIGHT_TAG);

    if (player.isCreative() || player.isSpectator())
        return;

    abilities.mayfly = false;
    abilities.flying = false;
    player.onUpdateAbilities();
}

public void processTargets() {
    var level = this.level();
