protected void onHitEntity(EntityHitResult result) {
    if (this.tickCount < ARC_DURATION || !(result.getEntity() instanceof LivingEntity entity) || this.impactedEntities.contains(entity.getStringUUID())
            || (!(this.getOwner() instanceof LivingEntity owner) || entity.getStringUUID().equals(owner.getStringUUID()))
            || !TargetingUtils.canHarm(owner, entity, this.getStack(), "reflection"))
        return;

    entity.invulnerableTime = 0;

    if (TargetingUtils.hurtEnemy(entity, this.level().damageSources().thrown(owner, this), this.getDamage(), this.getStack(), "reflection")) {
        var stun = this.getStun();

        if (stun > 0)
            TargetingUtils.addHarmfulEffect(entity, new MobEffectInstance(RelicsMobEffects.STUN, (int) (stun * 20), 0, false, false), owner, this.getStack(), "reflection");

        if (stack.getItem() instanceof ReflectiveNecklaceItem relic) {
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_damage").addValue(this.getDamage());

            if (stun > 0)
                relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_stun").addValue(stun);

            relic.getRelicData(entity, stack).getLevelingData().addExperience("reflection", "impact", 1);
        }
    }

    this.impactedEntities.add(entity.getStringUUID());

    var remainingPierces = this.getPiercings();

    if (remainingPierces <= 0)
        this.discard();
    else
        this.setPiercings(remainingPierces - 1);
}

private InteractionResult eatSlice(LevelAccessor world, BlockPos pos, BlockState state, Player player) {
  if (!player.canEat(false) && !food.canAlwaysEat()) {
    return InteractionResult.PASS;
  }
  // repurpose fast eating, will mean no eating if we have the effect
  if (combination == EffectCombination.BLOCK && hasAllEffects(player)) {
    return InteractionResult.PASS;
  }
  player.awardStat(Stats.EAT_CAKE_SLICE);
  // apply food stats
  player.getFoodData().eat(food.getNutrition(), food.getSaturationModifier());
  for (Pair<MobEffectInstance,Float> pair : food.getEffects()) {
    if (!world.isClientSide() && pair.getFirst() != null && world.getRandom().nextFloat() < pair.getSecond()) {
      MobEffectInstance effect = new MobEffectInstance(pair.getFirst());
      // if adding, increase duration by current duration, provided its an exact level match
      if (combination == EffectCombination.ADD) {
        MobEffectInstance current = player.getEffect(effect.getEffect());
        if (current != null && current.getAmplifier() == effect.getAmplifier()) {
          effect.duration += current.getDuration();
        }
      }
      player.addEffect(effect);
    }
  }
  // remove one bite from the cake
  int i = state.getValue(BITES);
  if (i < 6) {
    world.setBlock(pos, state.setValue(BITES, i + 1), 3);
  } else {
    world.removeBlock(pos, false);
  }
  return InteractionResult.SUCCESS;
}

static void beforeEntityInteract(EntityInteract event) {
  ItemStack stack = event.getItemStack();
  Player player = event.getEntity();
  InteractionHand hand = event.getHand();
  InteractionSource source = InteractionSource.RIGHT_CLICK;
  if (!stack.is(TinkerTags.Items.INTERACTABLE_RIGHT)) {
    // if the hand is empty, allow performing chestplate interaction (assuming a modifiable chestplate)
    if (stack.isEmpty()) {
      stack = player.getItemBySlot(EquipmentSlot.CHEST);
      if (stack.is(TinkerTags.Items.INTERACTABLE_ARMOR)) {
        source = InteractionSource.ARMOR;
      } else {
        return;
      }
    } else {
      return;
    }
  }
  if (!player.getCooldowns().isOnCooldown(stack.getItem())) {
    // actual interaction hook
    ToolStack tool = ToolStack.from(stack);
    Entity target = event.getTarget();
    for (ModifierEntry entry : tool.getModifierList()) {
      // exit on first successful result
      InteractionResult result = entry.getHook(ModifierHooks.ENTITY_INTERACT).beforeEntityUse(tool, entry, player, target, hand, source);
      if (result.consumesAction()) {
        event.setCanceled(true);
        event.setCancellationResult(result);
        return;
      }
    }
  }
}

public void clearCachedSlotModifiers() {
    var slotModifiers = HashMultimap.<String, AttributeModifier>create();

    var containers = this.getContainers();

    containers.forEach((name, container) -> {
        var modifiers = container.getCachedModifiers();

        if (modifiers.isEmpty()) return;

        var accessories = container.getAccessories();

        for (int i = 0; i < accessories.getContainerSize(); i++) {
            var stack = accessories.getItem(i);

            if (stack.isEmpty()) continue;

            var slotReference = container.createReference(i);

            slotModifiers.putAll(AccessoryAttributeLogic.getAttributeModifiers(stack, slotReference).getSlotModifiers());
        }
    });

    slotModifiers.asMap().forEach((name, modifiers) -> {
        if (!containers.containsKey(name)) return;

        var container = containers.get(name);

        modifiers.forEach(container.getCachedModifiers()::remove);

        container.clearCachedModifiers();
    });
}

static void onBlock(ShieldBlockEvent event) {
  LivingEntity entity = event.getEntity();
  ItemStack activeStack = entity.getUseItem();
  if (!activeStack.isEmpty() && activeStack.is(TinkerTags.Items.MODIFIABLE)) {
    ToolStack tool = ToolStack.from(activeStack);
    // first check block angle
    if (!tool.isBroken() && canBlock(event.getEntity(), event.getDamageSource().getSourcePosition(), tool)) {
      // TODO: hook for conditioning block amount based on on damage type
      // handle block amount
      event.setBlockedDamage(Math.min(event.getBlockedDamage(), tool.getStats().get(ToolStats.BLOCK_AMOUNT)));

      // handle damaging the shield ourselves to fix a couple of shield related bugs
      if (entity instanceof Player player) {
        event.setShieldTakesDamage(false);
        // this code is based on code from Player#hurtCurrentlyUsedShield
        if (!entity.level().isClientSide) {
          player.awardStat(Stats.ITEM_USED.get(tool.getItem()));
        }

        float damage = event.getBlockedDamage();
        if (damage >= 3) {
          InteractionHand usingHand = entity.getUsedItemHand();
          if (ToolDamageUtil.damageAnimated(tool, 1 + Mth.floor(damage), entity, usingHand)) {
            ForgeEventFactory.onPlayerDestroyItem(player, activeStack, usingHand);
            entity.stopUsingItem();
            entity.playSound(SoundEvents.SHIELD_BREAK, 0.8F, 0.8F + entity.level().random.nextFloat() * 0.4F);
          }
        }
      }
    } else {
      event.setCanceled(true);
    }
  }
}

public void onStoppedUsing(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int timeLeft) {
  if (entity instanceof Player player) {
    int chargeTime = getUseDuration(tool, modifier) - timeLeft;
    if (chargeTime > 10) {
      Level level = player.level();
      ItemStack stack = player.getUseItem();

      // unlike the trident, we actually consider how long you charged for, and change the power of the projectile
      float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
      float velocity = ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.VELOCITY);
      ThrownTool thrown = new ThrownTool(level, player, stack, charge, velocity, ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.WATER_INERTIA));
      if (player.getUsedItemHand() == InteractionHand.OFF_HAND) {
        thrown.setOriginalSlot(Inventory.SLOT_OFFHAND);
      } else {
        thrown.setOriginalSlot(player.getInventory().selected);
      }
      thrown.shootFromRotation(player, player.getXRot(), player.getYRot(), 0, charge * velocity * 2, ModifierUtil.getInaccuracy(tool, entity));
      if (player.getAbilities().instabuild) {
        thrown.pickup = AbstractArrow.Pickup.CREATIVE_ONLY;
      }

      // alert modifiers we are leaving, though most of these won't have much impact
      thrown.onRelease(entity, PersistentDataCapability.getOrWarn(thrown));

      // don't run projectile hooks, as the projectile has the tool already for that. Throwing runs melee hooks
      level.addFreshEntity(thrown);
      level.playSound(null, thrown, SoundEvents.TRIDENT_THROW, SoundSource.PLAYERS, 1, 1);
      if (!player.getAbilities().instabuild) {
        player.getInventory().removeItem(stack);
      }
      player.awardStat(Stats.ITEM_USED.get(tool.getItem()));
    }
  }
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        var player = ctx.player();

        if (player.containerMenu.containerId != this.getContainer()) {
            this.causeError(player);

            return;
        }

        var stack = DescriptionUtils.gatherRelicStack(player, this.getSlot());

        if (!(stack.getItem() instanceof IRelicItem relic)) {
            this.causeError(player);

            return;
        }

        var abilityData = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(this.getAbility());

        var event = new AbilityModeSwitchEvent(player, stack, this.getAbility(), abilityData.getMode(), this.getMode());

        NeoForge.EVENT_BUS.post(event);

        if (!event.isCanceled())
            abilityData.setMode(event.getToMode());

        try {
            player.containerMenu.getSlot(this.getSlot()).set(stack);
        } catch (Exception e) {
            e.printStackTrace();

            this.causeError(player);
        }
    });
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        var player = ctx.player();

        if (player.containerMenu.containerId != this.getContainer()) {
            this.causeError(player);

            return;
        }

        var stack = DescriptionUtils.gatherRelicStack(player, this.getSlot());

        if (!(stack.getItem() instanceof IRelicItem relic)) {
            this.causeError(player);

            return;
        }

        var synergyData = relic.getRelicData(player, stack).getAbilitiesData().getSynergyData(this.getSynergy());

        var event = new SynergyModeSwitchEvent(player, stack, this.getSynergy(), synergyData.getMode(), this.getMode());

        NeoForge.EVENT_BUS.post(event);

        if (!event.isCanceled())
            synergyData.setMode(event.getToMode());

        try {
            player.containerMenu.getSlot(this.getSlot()).set(stack);
        } catch (Exception e) {
            e.printStackTrace();

            this.causeError(player);
        }
    });
}

public static float getToolAttribute(IToolStackView tool, LivingEntity holder, Attribute attribute, float toolValue) {
  // fetch attribute instance
  AttributeInstance instance = holder.getAttribute(attribute);
  if (instance == null) {
    return (float) holder.getAttributeBaseValue(attribute);
  }

  // Mantle optimizes this method by skipping if the mainhand and offhand have no attributes
  // for our case though, we wish to merge in the tool value so always have something
  // plus, its more efficient in the attribute builder if we can directly modify the final map

  // start building our attributes list
  Map<Operation, Set<AttributeModifier>> modifiers = CombatHelper.copyModifiers(instance);

  // remove mainhand attributes
  ItemStack mainStack = CombatHelper.getMainhandAttributeStack(holder);
  if (!mainStack.isEmpty()) {
    for (AttributeModifier modifier : mainStack.getAttributeModifiers(EquipmentSlot.MAINHAND).get(attribute)) {
      modifiers.get(modifier.getOperation()).remove(modifier);
    }
  }

  // start adding in "mainhand" attributes for the given slot and attribute
  BiConsumer<Attribute, AttributeModifier> attributeConsumer = (check, modifier) -> {
    if (check == attribute) {
      // this will remove duplicates due to AttributeModifier equals only checking UUID
      modifiers.get(modifier.getOperation()).add(modifier);
    }
  };
  for (ModifierEntry entry : tool.getModifierList()) {
    entry.getHook(ModifierHooks.ATTRIBUTES).addAttributes(tool, entry, EquipmentSlot.MAINHAND, attributeConsumer);
  }

  // add in the tool value and build the stat
  return (float) CombatHelper.computeAttribute(attribute, instance.getBaseValue() + toolValue, modifiers);
}

private static int resetAll(CommandContext<CommandSourceStack> context) throws CommandSyntaxException {
  List<LivingEntity> successes = HeldModifiableItemIterator.apply(context, (living, stack) -> {
    // remove modifier
    ToolStack tool = ToolStack.from(stack);
    StatOverrideModifier stats = TinkerModifiers.statOverride.get();
    int level = tool.getModifierLevel(stats);
    if (level > 0) {
      tool = tool.copy();
      tool.removeModifier(stats.getId(), level);

      // ensure the tool is still valid
      Component error = tool.tryValidate();
      if (error != null) {
        throw MODIFIER_ERROR.create(error);
      }
      error = stats.getHook(ModifierHooks.REMOVE).onRemoved(tool, stats);
      if (error != null) {
        throw MODIFIER_ERROR.create(error);
      }

      // if successful, update held item
      living.setItemInHand(InteractionHand.MAIN_HAND, tool.copyStack(stack));
    }
    return true;
  });

  // success message
  CommandSourceStack source = context.getSource();
  int size = successes.size();
  if (size == 1) {
    source.sendSuccess(() -> Component.translatable(RESET_ALL_SINGLE, successes.get(0).getDisplayName()), true);
  } else {
    source.sendSuccess(() -> Component.translatable(RESET_ALL_MULTIPLE, size), true);
  }
  return size;
}

public ToolAttackContext build() {
  Entity target = Objects.requireNonNull(this.target, "Must set target to build a tool attack context");
  boolean fullyCharged = cooldown > 0.9f;
  float criticalModifier = 1.0f;
  if (!extraAttack && projectile == null) {
    criticalModifier = ToolAttackUtil.getCriticalModifier(attacker, playerAttacker, target, targetLiving, fullyCharged);
  }

  // knockback
  float baseKnockback = this.baseKnockback;
  // vanilla applies 0.4 knockback to living via the attack hook
  if (targetLiving != null) {
    baseKnockback += 0.4f;
  }
  // if sprinting, deal bonus knockback
  if (fullyCharged && attacker.isSprinting()) {
    baseKnockback += 0.5f;
  }

  // sound
  SoundEvent sound = this.sound;
  if (sound == null) {
    if (criticalModifier > 1) {
      sound = SoundEvents.PLAYER_ATTACK_CRIT;
    } else if (fullyCharged) {
      if (attacker.isSprinting()) {
        sound = SoundEvents.PLAYER_ATTACK_KNOCKBACK;
      } else {
        sound = SoundEvents.PLAYER_ATTACK_STRONG;
      }
    } else {
      sound = SoundEvents.PLAYER_ATTACK_WEAK;
    }
  }
  // build final context
  return new ToolAttackContext(attacker, playerAttacker, hand, slot, projectile, target, targetLiving, baseDamage, baseKnockback, cooldown, criticalModifier, extraAttack, sound);
}

public static void onLivingJump(LivingEvent.LivingJumpEvent event) {
    var entity = event.getEntity();
    var level = entity.level();

    if (level.isClientSide())
        return;

    var power = 0D;

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.SPRINGY_BOOT.get())) {
        var relic = (SpringyBootItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("bounce").canPlayerUse(entity) || relic.isLeaped(stack) || relic.getBounceCooldown(stack) > 0 || !entity.isShiftKeyDown())
            continue;

        power += relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("power").getValue();

        relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("primary_bounces").addValue(1);

        relic.setLeaped(stack, true);
        relic.addBounceCooldown(stack, 5);
    }

    if (power > 0D) {
        var lookAngle = entity.getLookAngle();

        if (lookAngle.y() < 0F)
            lookAngle = new Vec3(lookAngle.x(), 0F, lookAngle.z());

        var motion = lookAngle.multiply(-1F, 1F, -1F).add(0F, 0.5F, 0F).normalize().scale(power);

        NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CBounceFromSurface(entity.getId(), motion.toVector3f()), entity);

        SpringyBootItem.spawnBounceFog(level, entity, Math.max(1.1D, power * 0.85D), 12 + Mth.ceil(power * 5D));

        level.playSound(null, entity.blockPosition(), RelicsSounds.SPRING_BOING.get(), SoundSource.MASTER, 5F, 0.5F);
    }
}

public static void addAttribute(Attribute attribute, Operation operation, double amount, @Nullable UUID uuid, @Nullable Player player, List<Component> tooltip) {
  // find value
  boolean showEquals = false;
  if (player != null) {
    if (uuid == Item.BASE_ATTACK_DAMAGE_UUID) {
      amount += player.getAttributeBaseValue(Attributes.ATTACK_DAMAGE);
      showEquals = true;
    } else if (uuid == Item.BASE_ATTACK_SPEED_UUID) {
      amount += player.getAttributeBaseValue(Attributes.ATTACK_SPEED);
      showEquals = true;
    }
  }
  // some numbers display a bit different
  double displayValue = amount;
  if (operation == Operation.ADDITION) {
    // vanilla multiplies knockback resist by 10 for some odd reason
    if (attribute.equals(Attributes.KNOCKBACK_RESISTANCE)) {
      displayValue *= 10;
    }
  } else {
    // display multiply as percentage
    displayValue *= 100;
  }
  // final tooltip addition
  Component name = Component.translatable(attribute.getDescriptionId());
  if (showEquals) {
    tooltip.add(Component.literal(" ")
                         .append(Component.translatable("attribute.modifier.equals." + operation.toValue(), ItemStack.ATTRIBUTE_MODIFIER_FORMAT.format(displayValue), name))
                         .withStyle(ChatFormatting.DARK_GREEN));
  } else if (amount > 0.0D) {
    tooltip.add((Component.translatable("attribute.modifier.plus." + operation.toValue(), ItemStack.ATTRIBUTE_MODIFIER_FORMAT.format(displayValue), name))
                  .withStyle(ChatFormatting.BLUE));
  } else if (amount < 0.0D) {
    displayValue *= -1;
    tooltip.add((Component.translatable("attribute.modifier.take." + operation.toValue(), ItemStack.ATTRIBUTE_MODIFIER_FORMAT.format(displayValue), name))
                  .withStyle(ChatFormatting.RED));
  }
}

static void afterEntityInteract(EntityInteract event) {
  Player player = event.getEntity();
  if (event.getItemStack().isEmpty() && !player.isSpectator()) {
    ItemStack chestplate = player.getItemBySlot(EquipmentSlot.CHEST);
    if (chestplate.is(TinkerTags.Items.INTERACTABLE_ARMOR) && !player.getCooldowns().isOnCooldown(chestplate.getItem())) {
      // from this point on, we are taking over interaction logic, to ensure chestplate hooks run in the right order
      event.setCanceled(true);

      ToolStack tool = ToolStack.from(chestplate);
      Entity target = event.getTarget();
      InteractionHand hand = event.getHand();

      // initial entity interaction
      InteractionResult result = target.interact(player, hand);
      if (result.consumesAction()) {
        event.setCancellationResult(result);
        return;
      }

      // after entity use for chestplates
      if (target instanceof LivingEntity livingTarget) {
        for (ModifierEntry entry : tool.getModifierList()) {
          // exit on first successful result
          result = entry.getHook(ModifierHooks.ENTITY_INTERACT).afterEntityUse(tool, entry, player, livingTarget, hand, InteractionSource.ARMOR);
          if (result.consumesAction()) {
            event.setCanceled(true);
            event.setCancellationResult(result);
            return;
          }
        }
      }

      // did not interact with an entity? try direct interaction
      // needs to be run here as the interact empty hook does not fire when targeting entities
      result = onChestplateUse(player, chestplate, hand);
      event.setCancellationResult(result);
    }
  }
}

public void inventoryTick(ItemStack stack, Level level, Entity entity, int slotId, boolean isSelected) {
    super.inventoryTick(stack, level, entity, slotId, isSelected);

    if (level.isClientSide() || !(entity instanceof Player player))
        return;

    var ticks = getActiveTicks(stack);

    var missedTicks = getMissedTicks(stack);

    if (stack.getOrDefault(RelicsDataComponents.SHIELD_OF_RETALIATION_MISSED, false) && missedTicks > 0) {
        if (missedTicks <= 1)
            setMissed(stack, false);
        else
            setMissedTicks(stack, missedTicks - 1);
    } else if (stack.getOrDefault(RelicsDataComponents.SHIELD_OF_RETALIATION_MISSED, false) || missedTicks > 0) {
        setMissed(stack, false);
    }

    if (ticks <= 0)
        return;

    if (!isParryStack(player, stack)) {
        finishParry(player, stack, true);

        return;
    }

    holdCapturedProjectiles(player, stack);
    ticks = getActiveTicks(stack);

    if (ticks == 1) {
        finishParry(player, stack, true);
        player.stopUsingItem();

        return;
    }

    setActiveTicks(stack, ticks - 1);
}

public List<IDisplayableCastingRecipe> getRecipes(RegistryAccess access) {
  if (displayRecipes == null) {
    // first, get a list of potion IDs
    List<String> potions = getPotionIds();
    List<CompoundTag> potionNBT = potions.stream().map(id -> {
      CompoundTag fluidNBT = new CompoundTag();
      fluidNBT.putString(PotionUtils.TAG_POTION, id);
      return fluidNBT;
    }).toList();

    // next, make 1 copy of the potion fluid with NBT list per potion fluid
    List<FluidStack> basePotions = this.fluid.getFluids();
    List<FluidStack> fluids = basePotions.stream()
      .flatMap(fluid -> potionNBT.stream().map(nbt -> new FluidStack(fluid.getFluid(), fluid.getAmount(), nbt)))
      .toList();

    // finally, create 1 recipe per input tool
    int basePotionCount = basePotions.size();
    displayRecipes = Arrays.stream(bottle.getItems()).map(stack -> {
      // start with just the tool with the modifier
      ItemStack withModifier = addModifier(stack);
      // next, add the potion to the tools
      List<ItemStack> withPotion = addPotion(withModifier, potions);
      // duplicate the list if we have multiple potion fluids
      if (basePotionCount > 1) {
        List<ItemStack> list = new ArrayList<>(withPotion.size() * basePotionCount);
        for (int i = 0; i < basePotionCount; i++) {
          list.addAll(withPotion);
        }
        withPotion = List.copyOf(list);
      }
      // and finally create the recipe
      return DisplayCastingRecipe.from(this)
        .cast(withModifier).consumed()
        .results(withPotion).fluids(fluids).linkFluidsToOutput()
        .coolingTime(coolingTime).build();
    }).toList();
  }
  return displayRecipes;
}

public static void addAttributeTooltips(Consumer<Component> tooltip, ItemStack stack, Item.TooltipContext context, TooltipDisplay display) {
    boolean hasSlotTooltip = false;

    // FIXME: Fix attribute tooltips
    //  - This needs a more precise injection target to show correctly,
    //    this breaks when there are multiple vanilla slots (@ModifyReceiver on forEachModifier might work)
    //  - Don't show artifact attributes/mob effects under hand slots
    if (display.shows(DataComponents.ATTRIBUTE_MODIFIERS)) {
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            MutableBoolean b = new MutableBoolean(false);
            stack.forEachModifier(slot, (_, _) -> b.setTrue());
            if (b.booleanValue()) {
                hasSlotTooltip = true;

                addAttributeTooltips(tooltip, stack, display);
                addMobEffectTooltips(tooltip, stack, context, display);
            }
        }
    }

    // add attribute and mob effect tooltips if they haven't already been added under the vanilla tooltip
    if (!hasSlotTooltip) {
        if (getAbilityIfVisible(ModDataComponents.ATTRIBUTE_MODIFIERS, stack, display).findAny().isPresent()
                || getAbilityIfVisible(ModDataComponents.MOB_EFFECTS, stack, display).findAny().isPresent()
        ) {
            tooltip.accept(CommonComponents.EMPTY);
            tooltip.accept(Component.translatable("item.modifiers.%s".formatted(EquipmentSlotGroup.BODY.getSerializedName()))
                    .withStyle(ChatFormatting.GRAY)
            );
        }

        addAttributeTooltips(tooltip, stack, display);
        addMobEffectTooltips(tooltip, stack, context, display);
    }

    // these don't fall under the normal "When Equipped:" tooltip
    addWhenHurtTooltips(tooltip, stack, context, display);
    addPerFoodPointEatenTooltips(tooltip, stack, context, display);
    addAttacksInflictTooltips(tooltip, stack, context, display);
}

public void tick() {
    super.tick();

    var level = getCommandSenderWorld();
    var particleCenter = this.position().add(this.getDeltaMovement().scale(-1F));

    if (tickCount > 3)
        for (int i = 0; i < 3; i++)
            level.addParticle(ParticleUtils.constructSimpleSpark(new Color(50 + random.nextInt(100), 150 + random.nextInt(100), 0), 0.01F + random.nextFloat() * Math.min(tickCount * 0.01F, 0.1F), 5 + random.nextInt(3), 0.9F),
                    particleCenter.x() + MathUtils.randomFloat(random) * 0.05F, particleCenter.y() + MathUtils.randomFloat(random) * 0.05F, particleCenter.z() + MathUtils.randomFloat(random) * 0.05F, 0F, 0F, 0F);

    if (this.tickCount >= 250) {
        if (!level.isClientSide())
            this.discard();

        return;
    }

    if (target == null || target.isDeadOrDying()) {
        if (level.isClientSide())
            return;

        var targets = locateNearestTargets();

        if (targets.isEmpty())
            return;

        setTarget(targets.get(random.nextInt(targets.size())));

        NetworkHandler.sendToClientsTrackingEntity(new S2CSyncEntityTargetPacket(this.getId(), target.getId()), this);

        return;
    }

    var direction = target.position().subtract(this.position()).normalize();
    var motion = this.getDeltaMovement();

    var factor = Math.clamp(tickCount * 0.05F, 0F, 1F);

    this.setDeltaMovement(motion.x + (direction.x * factor - motion.x) * factor, motion.y, motion.z + (direction.z * factor - motion.z) * factor);
}

public void processTargets() {
    var level = this.level();
    var center = this.getCenter().getCenter();
    var owner = this.getOwner();

    for (var entity : level.getEntitiesOfClass(Entity.class, this.getBoundingBox(), entity -> !(entity instanceof ShockwaveBlockEntity) && (owner == null || !owner.getStringUUID().equals(entity.getStringUUID())))) {
        var motion = entity.position().add(0F, 1F, 0F).subtract(center).normalize().scale(this.getKnockback());

        if (entity instanceof LivingEntity livingEntity) {
            if (!(owner instanceof LivingEntity livingOwner) || !TargetingUtils.canHarm(livingOwner, livingEntity, this.getStack(), "bounce"))
                continue;

            if (entity instanceof ServerPlayer player)
                NetworkHandler.sendToClient(new S2CSetEntityMotion(entity.getId(), motion.toVector3f()), player);
            else
                entity.setDeltaMovement(motion);

            var damage = this.getDamage();

            if (TargetingUtils.hurtEnemy(livingEntity, level.damageSources().explosion(livingOwner, this), damage, this.getStack(), "bounce")) {
                var stun = this.getStun();

                if (stun > 0)
                    TargetingUtils.addHarmfulEffect(livingEntity, new MobEffectInstance(RelicsMobEffects.STUN, stun, 0, false, false), livingOwner, this.getStack(), "bounce");

                var stack = this.getStack();

                if (stack.getItem() instanceof SpringyBootItem relic) {
                    relic.getRelicData(livingOwner, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("shockwave_targets").addValue(1);

                    relic.getRelicData(livingOwner, stack).getLevelingData().addExperience("bounce", "shockwave_hit", 1);

                    relic.getRelicData(livingOwner, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("shockwave_damage").addValue(damage);

                    if (stun > 0)
                        relic.getRelicData(livingOwner, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("shockwave_stun").addValue(stun / 20D);
                }
            }
        } else {
            entity.setDeltaMovement(motion);
        }
    }
}

public static void onLivingHurt4(LivingDamageEvent.Post event) {
    if (event.getOriginalDamage() < 1D || !(event.getSource().getEntity() instanceof LivingEntity source))
        return;

    var entity = event.getEntity();

    if (source.getStringUUID().equals(entity.getStringUUID()))
        return;

    var level = entity.level();
    var random = level.getRandom();

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.MIDNIGHT_MANTLE.get())) {
        var relic = (MidnightMantleItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").canPlayerUse(entity) || random.nextDouble() > relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("star_chance").getValue())
            continue;

        var star = new ConstellationStarEntity(RelicsEntities.CONSTELLATION_STAR.get(), level);

        star.setDeltaMovement(MathUtils.randomFloat(random) * 0.5F, 0.1F + random.nextFloat() * 0.1F, MathUtils.randomFloat(random) * 0.5F);
        star.setConstellationRadius((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("constellation_radius").getValue());
        star.setExplosionRadius((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("explosion_radius").getValue());
        star.setDamage((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("explosion_damage").getValue());
        star.setTremor((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("tremor_duration").getValue());
        star.setLifetime((int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("star_lifetime").getValue());
        star.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
        star.setPos(entity.getEyePosition());
        star.setOwner(entity);
        star.setStack(stack);

        if (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getRankModifierData("stun").isEnabled())
            star.setStun((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatData("stun_duration").getValue());

        level.addFreshEntity(star);

        if (!level.isClientSide()) {
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("constellation").getStatisticData().getMetricData("total_stars").addValue(1);

            relic.getRelicData(entity, stack).getLevelingData().addExperience("constellation", "star_creation", 1);
        }
    }
}

public static void onLivingHurt(LivingDamageEvent.Pre event) {
    if (!(event.getSource().getDirectEntity() instanceof LivingEntity entity))
        return;

    var level = entity.level();
    var stacks = EntityUtils.findEquippedCurios(entity, RelicsItems.JELLYFISH_NECKLACE.get()).stream()
            .filter(stack -> stack.getItem() instanceof JellyfishNecklaceItem relic
                    && relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").canPlayerUse(entity)
                    && !relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getMode().equals("disabled"))
            .toList();

    if (stacks.isEmpty())
        return;

    var stack = stacks.getFirst();
    var relic = (JellyfishNecklaceItem) stack.getItem();
    var chargeUnlocked = stacks.stream().anyMatch(
            equippedStack -> relic.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("shock").getRankModifierData("charge").isEnabled());

    if (!chargeUnlocked)
        return;

    if (relic.getDuration(stack) <= 0)
        return;

    var targets = relic.getDamagedEntities(stack);
    var target = event.getEntity();
    var uuid = target.getStringUUID();

    if (!targets.contains(uuid)) {
        var paralysis = RelicStackingUtils.bestValue(entity, stack, "shock", "paralysis",
                abilityData -> !abilityData.getMode().equals("disabled"));

        target.addEffect(new MobEffectInstance(RelicsMobEffects.PARALYSIS, (int) (paralysis * 20), 0, false, false));

        if (!level.isClientSide()) {
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getStatisticData().getMetricData("hit_paralysis").addValue(paralysis);
            relic.getRelicData(entity, stack).getLevelingData().addExperience("shock", "hit_paralysis", paralysis);
        }

        relic.addDamagedEntities(stack, uuid);
    }
}

private void tickElectricSynergy() {
    var owner = this.getOwner();

    if (owner == null)
        return;

    ElectricSynergy synergy;

    if (this.level().isClientSide()) {
        if (!this.isElectricChainActive())
            return;

        synergy = new ElectricSynergy(0F, this.isElectricChainFlawless());
    } else {
        synergy = resolveElectricSynergy(owner);

        this.setElectricChainState(synergy != null, synergy != null && synergy.flawless());
    }

    if (synergy == null)
        return;

    var illusions = this.level().getEntitiesOfClass(GlitchyIllusionEntity.class, owner.getBoundingBox().inflate(96D),
                    illusion -> illusion.isAlive() && illusion.getOwner() == owner)
            .stream()
            .sorted(Comparator.comparingInt(GlitchyIllusionEntity::getId))
            .toList();

    if (illusions.size() < 2 || illusions.getFirst() != this)
        return;

    var damagedTargets = new HashSet<UUID>();

    for (var i = 1; i < illusions.size(); i++) {
        var previous = illusions.get(i - 1);
        var current = illusions.get(i);
        var start = previous.position().add(0D, previous.getBbHeight() * 0.55D, 0D);
        var end = current.position().add(0D, current.getBbHeight() * 0.55D, 0D);

        if (this.level().isClientSide())
            this.spawnElectricChainParticles(start, end, synergy.flawless());
        else
            this.hurtElectricChainTargets(owner, start, end, synergy.damage(), damagedTargets);
    }
}

public static void onLivingDeath(LivingDeathEvent event) {
    var target = event.getEntity();

    if (target.level().isClientSide())
        return;

    if (!(target instanceof Player player))
        return;

    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
        var relic = (GhostlyMantleItem) stack.getItem();
        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("spectral_escape");

        if (!ability.canPlayerUse(player) || relic.getEscapeCooldown(stack) > 0)
            continue;

        event.setCanceled(true);

        player.setHealth(Math.max(1F, player.getHealth()));
        player.deathTime = 0;

        var duration = (int) Math.max(1D, ability.getStatData("duration").getValue() * 20D);

        player.addEffect(new MobEffectInstance(RelicsMobEffects.FLIGHT, duration, 0, false, false, true));
        player.addEffect(new MobEffectInstance(RelicsMobEffects.IMMORTALITY, duration, 0, false, false, true));
        relic.setEscapeCooldown(stack, (int) Math.max(1D, ability.getStatData("cooldown").getValue() * 20D));

        ability.getStatisticData().getMetricData("prevented_deaths").addValue(1);

        var leveling = relic.getRelicData(player, stack).getLevelingData();
        var experience = leveling.getTotalExperienceBetweenLevels(leveling.getLevel(), leveling.getLevel() + 1) * 0.05D;

        relic.getRelicData(player, stack).getLevelingData().addExperience("spectral_escape", "death_prevention", experience);

        if (ability.getRankModifierData("reprisal").isEnabled() && event.getSource().getEntity() instanceof LivingEntity attacker && attacker != player
                && TargetingUtils.canHarm(player, attacker, stack, "spectral_escape")) {
            var marks = relic.getReprisalMarks(stack);

            marks.put(attacker.getStringUUID(), ability.getStatData("damage").getValue());
            relic.setReprisalMarks(stack, marks);
        }

        return;
    }
}

public static List<Component> getDefaultStats(IToolStackView tool, @Nullable Player player, List<Component> tooltip, TooltipKey key, TooltipFlag flag) {
  TooltipBuilder builder = new TooltipBuilder(tool, tooltip);
  if (tool.hasTag(TinkerTags.Items.DURABILITY)) {
    builder.addDurability();
  }
  boolean allowMelee = !EntityInteractionModifierHook.meleeDisabled(tool);
  boolean meleePrimary = allowMelee && tool.hasTag(TinkerTags.Items.MELEE_PRIMARY);
  if (meleePrimary) {
    builder.addWithAttribute(ToolStats.ATTACK_DAMAGE, Attributes.ATTACK_DAMAGE);
    builder.add(ToolStats.ATTACK_SPEED);
  }
  if (tool.hasTag(TinkerTags.Items.RANGED)) {
    builder.add(ToolStats.DRAW_SPEED);
    builder.add(ToolStats.VELOCITY);
    if (tool.hasTag(TinkerTags.Items.LAUNCHERS)) {
      builder.add(ToolStats.PROJECTILE_DAMAGE);
    }
    builder.add(ToolStats.ACCURACY);
  }
  if (allowMelee && !meleePrimary && tool.hasTag(TinkerTags.Items.MELEE_WEAPON)) {
    builder.addWithAttribute(ToolStats.ATTACK_DAMAGE, Attributes.ATTACK_DAMAGE);
    builder.add(ToolStats.ATTACK_SPEED);
  }
  if (tool.hasTag(TinkerTags.Items.HARVEST)) {
    if (tool.hasTag(TinkerTags.Items.HARVEST_PRIMARY)) {
      builder.addTier();
    }
    builder.add(ToolStats.MINING_SPEED);
  }
  // slimestaffs and shields are holdable armor, so show armor stats
  if (tool.hasTag(TinkerTags.Items.ARMOR)) {
    builder.addOptional(ToolStats.ARMOR);
    builder.addOptional(ToolStats.ARMOR_TOUGHNESS);
    builder.addOptional(ToolStats.KNOCKBACK_RESISTANCE, 10f);
  }
  if (ModifierUtil.canPerformAction(tool, ToolActions.SHIELD_BLOCK)) {
    builder.add(ToolStats.BLOCK_AMOUNT);
    builder.add(ToolStats.BLOCK_ANGLE);
  }

  builder.addAllFreeSlots();
  for (ModifierEntry entry : tool.getModifierList()) {
    entry.getHook(ModifierHooks.TOOLTIP).addTooltip(tool, entry, player, tooltip, key, flag);
  }
  return builder.getTooltips();
}

private void serverTick(Level level, BlockPos pos) {
  // no recipe
  // TODO: should consider the case where the tank has fluid, but there is no current recipe
  // would like to avoid doing a recipe lookup every tick, so need some way to handle the case of no recipe found, ideally without fluid voiding
  if (currentRecipe == null) {
    return;
  }
  // fully filled
  FluidStack currentFluid = tank.getFluid();
  if (coolingTime >= 0) {
    timer++;
    if (timer >= coolingTime) {
      if (!currentRecipe.matches(castingInventory, level)) {
        // if lost our recipe or the recipe needs more fluid then we have, we are done
        // will come around later for the proper fluid amount
        currentRecipe = findCastingRecipe();
        recipeName = null;
        if (currentRecipe == null || currentRecipe.getFluidAmount(castingInventory) > currentFluid.getAmount()) {
          timer = 0;
          updateAnalogSignal();
          // TODO: client does not get updated if this happens
          return;
        }
      }

      // actual recipe result
      boolean consumed = currentRecipe.isConsumed(castingInventory);
      ItemStack output = currentRecipe.assemble(castingInventory, level.registryAccess());
      if (currentRecipe.switchSlots() != lastRedstone) {
        if (!consumed) {
          setItem(OUTPUT, getItem(INPUT));
        }
        setItem(INPUT, output);
      } else {
        if (consumed) {
          setItem(INPUT, ItemStack.EMPTY);
        }
        setItem(OUTPUT, output);
      }
      // if redstone swapped behavior, add a click sound
      if (lastRedstone) {
        level.playSound(null, getBlockPos(), Sounds.CASTING_CLICKS.getSound(), SoundSource.BLOCKS, 1.0f, 1.0f);
      }
      level.playSound(null, pos, Sounds.CASTING_COOLS.getSound(), SoundSource.BLOCKS, 0.5f, 4f);
      reset();
    } else {
      updateAnalogSignal();
    }
  }
}

public static void onLivingHurt5(LivingIncomingDamageEvent event) {
    if (event.getAmount() < 1D || !(event.getSource().getEntity() instanceof LivingEntity entity))
        return;

    var target = event.getEntity();

    if (target.getStringUUID().equals(entity.getStringUUID()))
        return;

    var level = entity.level();
    var random = level.getRandom();

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.MIDNIGHT_MANTLE.get())) {
        var relic = (MidnightMantleItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").canPlayerUse(entity)
                || relic.getStarfallCooldown(stack) > 0
                || random.nextFloat() > relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getStatData("chance").getValue())
            continue;

        var pos = new Vec3(target.getX() + MathUtils.randomFloat(random) * 10, target.getY() + 25 + random.nextInt(25), target.getZ() + MathUtils.randomFloat(random) * 10);

        if (level.clip(new ClipContext(pos, target.position(), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, target)).getType() != HitResult.Type.MISS)
            continue;

        var motion = target.position().subtract(pos).normalize().scale(2F);

        var star = new FallingStarEntity(RelicsEntities.FALLING_STAR.get(), level);

        star.setDamage((float) (event.getAmount() * relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getStatData("damage").getValue()));
        star.setRadius((int) Math.round(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getStatData("radius").getValue()));
        star.setStun((int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getStatData("stun").getValue() * 20));
        star.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
        star.setDeltaMovement(motion);
        star.setOwner(entity);
        star.setStack(stack);
        star.setPos(pos);

        if (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getRankModifierData("bounce").isEnabled())
            star.setBounceChance((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getStatData("bounce_chance").getValue());

        level.addFreshEntity(star);
        relic.setStarfallCooldown(stack, 20);

        if (!level.isClientSide()) {
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("starfall").getStatisticData().getMetricData("total_stars").addValue(1);

            relic.getRelicData(entity, stack).getLevelingData().addExperience("starfall", "star_creation", 1);
        }
    }
}

public static void handle(C2SChainedElectricityPacket packet, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        if (!(ctx.player() instanceof ServerPlayer player) || player.level().isClientSide())
            return;

        var level = player.level();
        var position = new Vec3(packet.x, packet.y, packet.z);
        var slot = CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(packet.slotId, packet.slotIndex));

        if (slot.isEmpty())
            return;

        var stack = slot.get().stack();

        if (!(stack.getItem() instanceof KineticBeltItem))
            return;

        ChainedElectricityEntity previous = null;
        var previousId = stack.getOrDefault(RelicsDataComponents.KINETIC_BELT_LAST_ELECTRICITY_ID, -1);
        var bestDistance = Double.MAX_VALUE;

        if (previousId >= 0) {
            var raw = level.getEntity(previousId);

            if (raw instanceof ChainedElectricityEntity candidate && candidate.isAlive() && candidate.getOwner() == player) {
                bestDistance = candidate.position().distanceToSqr(position);

                if (bestDistance < 1D)
                    return;

                if (bestDistance <= 100D)
                    previous = candidate;
            }
        }

        var electricity = new ChainedElectricityEntity(RelicsEntities.KINETIC_ELECTRICITY.get(), player.level());

        electricity.setLifetime(Math.max(1, packet.lifetime));
        electricity.setDamage(Math.max(0F, packet.damage));
        electricity.setFlawless(packet.flawless);
        electricity.setPos(position);
        electricity.setOwner(player);
        electricity.setStack(stack);

        if (previous != null && bestDistance <= 100D)
            electricity.setPreviousEntity(previous);

        level.addFreshEntity(electricity);

        stack.set(RelicsDataComponents.KINETIC_BELT_LAST_ELECTRICITY_ID, electricity.getId());
    });
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    var entity = slotContext.entity();
    var level = entity.level();

    if (level.isClientSide())
        return;

    if (this.getStarfallCooldown(stack) > 0)
        this.addStarfallCooldown(stack, -1);

    if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").canPlayerUse(entity)) {
        var mode = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getMode();

        if (!mode.isEmpty()) {
            if (entity.tickCount % 20 == 0)
                this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getStatisticData().getMetricData("duration_" + mode).addValue(1);

            var totalEffectiveness = this.getModeEffectiveness(entity, stack);

            var attackEffectiveness = mode.equals("full_moon") ? totalEffectiveness : 0D;
            var healEffectiveness = mode.equals("new_moon") ? totalEffectiveness : 0D;

            EntityUtils.resetAttribute(entity, Attributes.ATTACK_SPEED,
                    (float) (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getStatData("attack_speed").getValue() * attackEffectiveness),
                    AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL,
                    getPhaseAttributeId(stack, Attributes.ATTACK_SPEED, slotContext));
            EntityUtils.resetAttribute(entity, Attributes.MAX_HEALTH,
                    (float) (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getStatData("max_health").getValue() * healEffectiveness),
                    AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL,
                    getPhaseAttributeId(stack, Attributes.MAX_HEALTH, slotContext));
        }

        if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getRankModifierData("switch").isEnabled() && this.getPhaseDuration(stack) > 0)
            this.addPhaseDuration(stack, -1);
    }

    if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").canPlayerUse(entity)) {
        var cooldown = this.getInvisibilityCooldown(stack);

        if (cooldown > 0) {
            if (level.getEntitiesOfClass(Mob.class, entity.getBoundingBox().inflate(16)).stream().noneMatch(mob -> mob.getTarget() == entity && mob.hasLineOfSight(entity)))
                this.addInvisibilityCooldown(stack, -1);
        } else if (this.canHideInTheDarkness(entity, stack)) {
            entity.addEffect(new MobEffectInstance(RelicsMobEffects.VANISHING, 5, 0, false, false));

            if (entity.tickCount % 20 == 0) {
                this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").getStatisticData().getMetricData("duration").addValue(1);

                this.getRelicData(entity, stack).getLevelingData().addExperience("invisibility", "being_invisible", 1);
            }
        }
    }
}

static void leftClickBlock(LeftClickBlock event) {
  if (event.getAction() != Action.START) {
    return;
  }
  // ensure we have not fired this tick
  Player player = event.getEntity();
  if (player.getCapability(TinkerDataCapability.CAPABILITY).filter(data -> data.computeIfAbsent(LAST_TICK).update(player)).isEmpty()) {
    return;
  }
  // must support interaction
  ItemStack stack = event.getItemStack();
  if (!stack.is(TinkerTags.Items.INTERACTABLE_LEFT) || player.getCooldowns().isOnCooldown(stack.getItem())) {
    return;
  }

  // build usage context
  InteractionHand hand = event.getHand();
  BlockPos pos = event.getPos();
  Direction direction = event.getFace();
  if (direction == null) {
    direction = player.getDirection().getOpposite();
  }
  UseOnContext context = new UseOnContext(player, hand, new BlockHitResult(Util.toHitVec(pos, direction), direction, pos, false));

  // run modifier hooks
  ToolStack tool = ToolStack.from(stack);
  List<ModifierEntry> modifiers = tool.getModifierList();
  for (ModifierEntry entry : modifiers) {
    InteractionResult result = entry.getHook(ModifierHooks.BLOCK_INTERACT).beforeBlockUse(tool, entry, context, InteractionSource.LEFT_CLICK);
    if (result.consumesAction()) {
      setLeftClickEventResult(event, result);
      // always cancel block interaction, prevents breaking glows/fires
      event.setCanceled(true);
      return;
    }
  }
  // TODO: don't think there is an equivalence to block interactions
  for (ModifierEntry entry : modifiers) {
    InteractionResult result = entry.getHook(ModifierHooks.BLOCK_INTERACT).afterBlockUse(tool, entry, context, InteractionSource.LEFT_CLICK);
    if (result.consumesAction()) {
      setLeftClickEventResult(event, result);
      // always cancel block interaction, prevents breaking glows/fires
      event.setCanceled(true);
      return;
    }
  }

  // fallback to default interaction
  InteractionResult result = onLeftClickInteraction(tool, player, hand);
  if (result.consumesAction()) {
    setLeftClickEventResult(event, result);
  }
}

protected void onHitEntity(EntityHitResult pResult) {
  this.dealtDamage = true;

  // need a living entity to run our attack hooks, just do nothing if we lack an owner
  if (!tridentItem.isEmpty() && this.getOwner() instanceof LivingEntity owner) {
    Entity target = pResult.getEntity();

    IToolStackView tool = getTool();
    if (ToolAttackUtil.canPerformAttack(tool) && ToolAttackUtil.isAttackable(owner, target)) {
      // if the tool is blunted, don't deal damage and instead go squeak
      if (EntityInteractionModifierHook.meleeDisabled(tool)) {
        owner.playSound(Sounds.TOY_SQUEAK.getSound());
      } else {
        // hack: swap the offhand for the tool so any relevant modifier hooks (notably looting) see the right thing
        // does not actually matter which slot we use, just need the tool there to ensure hooks are properly run
        // skip the hack if attacking ourself, as that might cause it to drop/duplicate. Its not like we need looting on ourself, why are you killing yourself?
        ItemStack offhand = owner.getOffhandItem();
        boolean notSelf = owner != target;
        if (notSelf) {
          owner.setItemInHand(InteractionHand.OFF_HAND, tridentItem);
        }
        // TODO: consider whether redundant sound is fine
        ToolAttackContext context = ToolAttackContext.attacker(owner).target(target).hand(InteractionHand.OFF_HAND).baseDamage(tool.getStats().get(ToolStats.ATTACK_DAMAGE) * multiplier).cooldown(charge).projectile(this).build();
        if (ToolAttackUtil.performAttack(tool, context)) {
          if (target instanceof LivingEntity living) {
            this.doPostHurtEffects(living);
          }
        }

        // restore held item
        if (notSelf) {
          owner.setItemInHand(InteractionHand.OFF_HAND, offhand);
        }

        // cancel post hit logic if it hit an enderman with no enderference
        if (!TinkerEffects.canHitWithProjectile(context.getLivingTarget())) {
          return;
        }
      }
    }

    // back off from the target
    this.setDeltaMovement(this.getDeltaMovement().multiply(-0.01, -0.1, -0.01));
    if (!level().isClientSide) {
      // play sound
      if (tool.getModifiers().getLevel(ModifierIds.channeling) == 0) {
        this.playSound(tool.isBroken() ? SoundEvents.ITEM_BREAK : SoundEvents.TRIDENT_HIT, 1.0f, 1.0f);
      }
      // update the stack so visual changes to the tool render (e.g. broken or fluid)
      // need to force since its the same instance, just NBT changes
      this.entityData.set(STACK, tridentItem, true);
    }
  }
}

static void livingDamage(LivingDamageEvent event) {
  LivingEntity entity = event.getEntity();
  DamageSource source = event.getSource();

  // give modifiers a chance to respond to damage happening
  float amount = event.getAmount();
  EquipmentContext context = new EquipmentContext(entity);
  if (context.hasModifiableArmor()) {
    amount = ModifyDamageModifierHook.modifyDamageTaken(ModifierHooks.MODIFY_DAMAGE, context, source, amount, OnAttackedModifierHook.isDirectDamage(source));
    event.setAmount(amount);
    if (amount <= 0) {
      event.setCanceled(true);
    }
  }

  // for remaining code, ensure amount is not more than they will take
  amount = Math.min(amount, entity.getHealth());

  // apply post hit modifier effects. Done regardless of damage dealt - don't care if absorption took it all
  if (Config.COMMON.allowMonsterMeleeModifiers.get() && source.is(TinkerTags.DamageTypes.MODIFIER_WHITELIST)) {
    Entity attacker = event.getSource().getEntity();
    if (attacker != null && !attacker.getType().is(TinkerTags.EntityTypes.DAMAGE_MODIFIER_BLACKLIST) && attacker instanceof LivingEntity living) {
      ItemStack weapon = living.getMainHandItem();
      if (!weapon.isEmpty()) {
        if (weapon.is(TinkerTags.Items.MELEE_WEAPON)) {
          // already know we are not a player
          IToolStackView tool = ToolStack.from(weapon);
          ToolAttackContext meleeContext = ToolAttackContext.attacker(living, null).target(event.getEntity()).applyAttributes().build();
          for (ModifierEntry entry : tool.getModifiers()) {
            entry.getHook(ModifierHooks.MONSTER_MELEE_HIT).onMonsterMeleeHit(tool, entry, meleeContext, amount);
          }
        }
      } else {// unarmed
        // not consider adding non-chest armor to the unarmed tag
        ItemStack unarmed = living.getItemBySlot(EquipmentSlot.CHEST);
        if (!unarmed.isEmpty() && unarmed.is(TinkerTags.Items.UNARMED)) {
          // already know we are not a player
          IToolStackView tool = ToolStack.from(unarmed);
          ToolAttackContext meleeContext = ToolAttackContext.attacker(living, null).target(event.getEntity()).applyAttributes().addBaseDamage(tool.getStats().get(ToolStats.ATTACK_DAMAGE)).slot(EquipmentSlot.CHEST, InteractionHand.MAIN_HAND).build();
          for (ModifierEntry entry : tool.getModifiers()) {
            entry.getHook(ModifierHooks.MONSTER_MELEE_HIT).onMonsterMeleeHit(tool, entry, meleeContext, amount);
          }
        }
      }
    }
  }

  // when damaging ender dragons, may drop scales - must be player caused explosion, end crystals and TNT are examples
  if (amount >= 2 && Config.COMMON.dropDragonScales.get() && entity.getType() == EntityType.ENDER_DRAGON
      && source.is(DamageTypeTags.IS_EXPLOSION) && source.getEntity() != null && source.getEntity().getType() == EntityType.PLAYER) {
    // drops up to 1 scale per heart lost, capping at 5 scales
    ModifierUtil.dropItem(entity, new ItemStack(TinkerModifiers.dragonScale, 1 + entity.level().random.nextInt(Math.min(5, (int)(amount / 2)))));
  }
}

public int onDamageTool(IToolStackView tool, ModifierEntry modifier, int amount, @Nullable LivingEntity holder, @Nullable ItemStack stack) {
  if (holder != null) {
    // want to randomly select a slot, but skip any that lack tools
    List<ItemStack> options = new ArrayList<>(10);
    // if the stack is armor, consider all armor slots
    if (tool.hasTag(TinkerTags.Items.WORN_ARMOR)) {
      for (EquipmentSlot slot : ModifiableArmorMaterial.ARMOR_SLOTS) {
        ItemStack check = holder.getItemBySlot(slot);
        // with armor, we can check the items as a heuristic to work around the potential of null stack
        if (canTarget(check) && check.getItem() != tool.getItem()) {
          options.add(check);
        }
      }
    } else {
      // if its a player, consider all hotbar slots
      if (holder instanceof Player player) {
        Inventory inventory = player.getInventory();
        for (int i = 0; i < 9; i++) {
          consider(options, inventory.getItem(i), stack);
        }
      } else {
        // non player adds just the mainhand to consider
        consider(options, holder.getMainHandItem(), stack);
      }
      // always consider offhand
      consider(options, holder.getOffhandItem(), stack);
    }

    // now that we have our options, randomly choose one
    if (!options.isEmpty()) {
      // figure out how much durability from the local tool to eat
      int consumed = Math.min(this.consume.compute(modifier.getEffectiveLevel()) * amount, tool.getCurrentDurability());
      int granted = this.grant.compute(modifier.getEffectiveLevel());
      if (consumed > 0 && granted > 0) {
        // deal extra damage to the local tool, specifically direct damage
        ToolDamageUtil.directDamage(tool, consumed, holder, stack);

        // grant some shield to the choice tool
        ItemStack choiceStack = options.get(TConstruct.RANDOM.nextInt(options.size()));
        ToolStack choice = ToolStack.from(choiceStack);
        Modifier shield = this.shield.get();
        ModifierEntry entry = choice.getModifier(shield);
        // if the modifier is missing, add it
        if (entry.getLevel() == 0) {
          entry = new ModifierEntry(shield, 1);
          choice.addModifier(shield.getId(), 1);
        }
        // update the durability bar
        shield.getHook(ModifierHooks.CAPACITY_BAR).addAmount(choice, entry, granted * amount);
      }
    }
  }
  return amount;
}

public void onUnequip(SlotContext slotContext, ItemStack newStack, ItemStack stack) {
    super.onUnequip(slotContext, newStack, stack);

    if (stack.getItem() == newStack.getItem())
        return;

    var entity = slotContext.entity();
    var activeRegenerationStacks = EntityUtils.findEquippedCurios(entity, RelicsItems.JELLYFISH_NECKLACE.get()).stream()
            .filter(equippedStack -> equippedStack != stack)
            .filter(equippedStack -> equippedStack.getItem() == this
                    && this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("regeneration").canPlayerUse(entity))
            .toList();
    var inWaterOrRain = entity.isInLiquid() || entity.isInRain();

    if (activeRegenerationStacks.isEmpty()) {
        EntityUtils.removeAttribute(entity, Attributes.MAX_ABSORPTION, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);
        EntityUtils.removeAttribute(entity, Attributes.MAX_HEALTH, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, REGEN_MAX_HEALTH_ATTRIBUTE);
        entity.setAbsorptionAmount(Math.min(entity.getAbsorptionAmount(), entity.getMaxAbsorption()));

        return;
    }

    var remainingMultiplier = (float) activeRegenerationStacks.stream()
            .mapToDouble(equippedStack -> this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("regeneration").getStatData("max_health").getValue())
            .sum();
    var retentionUnlocked = activeRegenerationStacks.stream()
            .anyMatch(equippedStack -> this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("regeneration").getRankModifierData("retention").isEnabled());

    if (inWaterOrRain) {
        EntityUtils.resetAttribute(entity, Attributes.MAX_HEALTH, remainingMultiplier, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, REGEN_MAX_HEALTH_ATTRIBUTE);
        EntityUtils.removeAttribute(entity, Attributes.MAX_ABSORPTION, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);
        entity.setAbsorptionAmount(Math.min(entity.getAbsorptionAmount(), entity.getMaxAbsorption()));

        return;
    }

    EntityUtils.removeAttribute(entity, Attributes.MAX_HEALTH, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, REGEN_MAX_HEALTH_ATTRIBUTE);

    if (!retentionUnlocked) {
        EntityUtils.removeAttribute(entity, Attributes.MAX_ABSORPTION, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);
        entity.setAbsorptionAmount(Math.min(entity.getAbsorptionAmount(), entity.getMaxAbsorption()));

        return;
    }

    var retentionCap = Math.max(0F, entity.getMaxHealth() * remainingMultiplier);
    var keptAbsorption = Math.min(entity.getAbsorptionAmount(), retentionCap);

    if (keptAbsorption <= 0F) {
        EntityUtils.removeAttribute(entity, Attributes.MAX_ABSORPTION, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);
        entity.setAbsorptionAmount(Math.min(entity.getAbsorptionAmount(), entity.getMaxAbsorption()));

        return;
    }

    EntityUtils.resetAttribute(entity, Attributes.MAX_ABSORPTION, keptAbsorption, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);
    entity.setAbsorptionAmount(keptAbsorption);
}

public static void onLivingDamage(LivingDamageEvent.Pre event) {
    var source = event.getSource().getEntity();
    var damage = event.getOriginalDamage();
    var entity = event.getEntity();

    var level = entity.level();
    var random = level.getRandom();

    if (damage >= 1) {
        for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.REFLECTIVE_NECKLACE.get())) {
            var relic = (ReflectiveNecklaceItem) stack.getItem();

            if (level.getRandom().nextDouble() > relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("chance").getValue())
                continue;

            var orbDamage = Math.clamp((float) (damage * relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("damage").getValue()), Float.MIN_VALUE, Float.MAX_VALUE);

            var orb = new ReflectiveOrbEntity(RelicsEntities.REFLECTIVE_ORB.get(), level);

            orb.setPiercings(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("piercing").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("piercings").getValue() : 0);
            orb.setBounces(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("bounce").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("bounces").getValue() : 0);
            orb.setStun(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("stun").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("stun").getValue() : 0);
            orb.setLifetime((int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("lifetime").getValue() * 20));
            orb.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
            orb.setPos(entity.getEyePosition());
            orb.setDamage(orbDamage);
            orb.setOwner(entity);
            orb.setStack(stack);

            if (source != null)
                orb.setDeltaMovement(entity.position().subtract(source.position()).normalize().add(MathUtils.randomFloat(random) * 0.5D, 0, MathUtils.randomFloat(random) * 0.5D));
            else
                orb.setDeltaMovement(MathUtils.randomFloat(random) * 0.5D, 0.5D + random.nextFloat() * 0.25D, MathUtils.randomFloat(random) * 0.5D);

            level.addFreshEntity(orb);

            relic.getRelicData(entity, stack).getLevelingData().addExperience("reflection", "construct", orbDamage * 0.1D);

            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_orbs").addValue(1);
        }
    }

    if (!(event.getSource().getEntity() instanceof LivingEntity livingSource))
        return;

    var stack = EntityUtils.findEquippedCurio(livingSource, RelicsItems.REFLECTIVE_NECKLACE.get());

    if (!stack.isEmpty()) {
        var step = 0;

        for (var orb : level.getEntitiesOfClass(ReflectiveOrbEntity.class, livingSource.getBoundingBox().inflate(ORB_SEARCH_RADIUS)).stream()
                .filter(orb -> !orb.isTargeted() && orb.getOwner() instanceof LivingEntity owner && owner.getStringUUID().equals(livingSource.getStringUUID()))
                .sorted(Comparator.comparingInt(orb -> (int) orb.position().distanceTo(entity.position())))
                .toList()) {

            ServerScheduler.schedule(step++ * 2, () -> orb.setTarget(entity.position().add(0D, entity.getBbHeight(), 0D).add(entity.getKnownMovement())));
        }
    }
}

public InteractionResult beforeEntityUse(IToolStackView tool, ModifierEntry modifier, Player player, Entity target, InteractionHand hand, InteractionSource source) {
  // melee items get spilling via attack, non melee interact to use it
  if (!tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
    FluidStack fluid = TANK_HELPER.getFluid(tool);
    if (!fluid.isEmpty()) {
      FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
      if (recipe.hasEntityEffects()) {
        Level world = player.level();

        // cooldown based on attack speed/draw speed. both are on the same scale and default to 1, we don't care which one the tool uses
        // applied before we do the effect to block recursive calls, notably ender might cause that
        player.getCooldowns().addCooldown(tool.getItem(), (int)(20 / ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.DRAW_SPEED)));

        if (!world.isClientSide) {
          // for the main target, consume fluids
          float level = this.strength.compute(modifier);
          int numTargets = 0;
          int consumed = recipe.applyToEntity(fluid, level, FluidEffectContext.builder(world).user(player).target(target), FluidAction.EXECUTE);
          if (consumed > 0) {
            numTargets++;
            UseFluidOnHitModifier.spawnParticles(target, fluid);
            fluid.shrink(consumed);
          }

          // expanded logic, consumes extra fluid per target
          if (!fluid.isEmpty()) {
            float range = 1 + tool.getVolatileData().getInt(IModifiable.EXPANDED);
            float rangeSq = range * range;
            for (Entity aoeTarget : world.getEntitiesOfClass(Entity.class, target.getBoundingBox().inflate(range, 0.25, range))) {
              if (aoeTarget != player && aoeTarget != target && !(aoeTarget instanceof ArmorStand stand && stand.isMarker()) && target.distanceToSqr(aoeTarget) < rangeSq) {
                consumed = recipe.applyToEntity(fluid, level, FluidEffectContext.builder(world).user(player).target(aoeTarget), FluidAction.EXECUTE);
                if (consumed > 0) {
                  numTargets++;
                  UseFluidOnHitModifier.spawnParticles(aoeTarget, fluid);
                  // consume fluid for each target entity
                  fluid.shrink(consumed);
                  if (fluid.isEmpty()) {
                    break;
                  }
                }
              }
            }
          }

          // consume the fluid last, if any target used fluid
          if (ModifierUtil.consumesResources(player)) {
            if (numTargets > 0) {
              TANK_HELPER.setFluid(tool, fluid);
            }

            // damage the tool, we charge for the multiplier and for the number of targets hit
            ToolDamageUtil.damageAnimated(tool, Mth.ceil(numTargets * level), player, hand, modifier.getId());
          }
        }

        return InteractionResult.SUCCESS;
      }
    }
  }
  return InteractionResult.PASS;
}

public void sling(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int chargeTime, ModifierEntry activeModifier) {
  Level level = entity.level();
  // must be sufficiently charged, not have too much knockback resistance, and not have any modifier zeroing its force
  float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
  if (charge > 0 && target.matches(entity)) {
    float forceMultiplier = this.forceMultiplier.compute(modifier);
    float multiplier = charge * Math.abs(forceMultiplier);
    float force = SlingForceModifierHook.modifySlingForce(tool, entity, entity, modifier, SlingModule.getPower(tool, entity) * multiplier, multiplier);
    if (force > 0) {
      Vec3 look = entity.getLookAngle();
      if (biasUpwards) {
        look = look.add(0, Math.max(0, 0.5 - force * 0.1 * Mth.sign(forceMultiplier)), 0);
      }
      look = look.normalize();

      RandomSource random = entity.getRandom();
      float inaccuracy = ModifierUtil.getInaccuracy(tool, entity) * 0.0075f;
      Vec3 angle = new Vec3(
        (look.x + random.nextGaussian() * inaccuracy),
        (look.y + random.nextGaussian() * inaccuracy) / heightReduction,
        (look.z + random.nextGaussian() * inaccuracy)
      );
      // fling in look direction, unless force is negative in which case reverse it
      if (forceMultiplier < 0) {
        angle = angle.multiply(-1, -1, -1);
      }
      angle = SlingAngleModifierHook.modifySlingAngle(tool, entity, entity, modifier, force, multiplier, angle);
      entity.push(force * angle.x, force * angle.y, force * angle.z);

      // if on the ground, get off the ground so jumping is not required before springing
      if (leaveGround && entity.onGround()) {
        entity.move(MoverType.SELF, new Vec3(0, 1.3f, 0));
      }

      // after sling callback
      SlimeBounceHandler.addBounceHandler(entity);
      SlingLaunchModifierHook.afterSlingLaunch(tool, entity, entity, modifier, force, multiplier, angle);

      if (!level.isClientSide) {
        level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), Sounds.SLIME_SLING.getSound(), entity.getSoundSource(), 1, 1);
        ToolDamageUtil.damageAnimated(tool, 1, entity, entity.getUsedItemHand(), modifier.getId());
      }
      // only need player for exhaustion, cooldowns, and drill attack
      if (entity instanceof Player player) {
        if (!level.isClientSide) {
          player.causeFoodExhaustion(0.2F);
          player.getCooldowns().addCooldown(tool.getItem(), 3);
        }
        // if supported, perform drill attack if the modifier is available
        if (ModifierManager.isInTag(modifier.getId(), TinkerTags.Modifiers.DRILL_ATTACKS) && ModifierUtil.canPerformAction(tool, TinkerToolActions.DRILL_ATTACK)) {
          player.startAutoSpinAttack(20);
        }
      }
      return;
    }
  }
  // play failure sound
  if (!level.isClientSide && ModifierUtil.isActiveModifier(tool, modifier, activeModifier)) {
    level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), Sounds.SLIME_SLING.getSound(), entity.getSoundSource(), 1, 0.5f);
  }
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    if (!(slotContext.entity() instanceof LivingEntity entity))
        return;

    var level = entity.getCommandSenderWorld();

    var progress = this.getCurrentProgress(stack);
    var hiding = this.isHiding(stack);

    boolean inLeaves = BlockPos
            .betweenClosedStream(entity.getBoundingBox())
            .anyMatch(pos -> level.getBlockState(pos).is(BlockTags.LEAVES));

    var cooldown = this.getInvisibilityCooldown(stack);

    if (cooldown > 0)
        this.addInvisibilityCooldown(stack, -1);

    if (level.isClientSide() && inLeaves) {
        if (entity instanceof LocalPlayer player && player.input.jumping) {
            var motion = player.getDeltaMovement();

            player.setDeltaMovement(motion.x(), 0.25F, motion.z());
        }
    }

    if (inLeaves && cooldown <= 0) {
        if (!hiding)
            this.setHiding(stack, true);
        if (progress < this.getMaxProgress())
            this.addCurrentProgress(stack, 1);

        if (!level.isClientSide() && this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getRankModifierData("disappearance").isEnabled())
            entity.addEffect(new MobEffectInstance(RelicsMobEffects.VANISHING, 5, 0, false, false));

        if (entity.tickCount % 20 == 0) {
            if (entity.getHealth() < entity.getMaxHealth()) {
                var heal = (float) Math.min(this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getStatData("heal").getValue(), entity.getMaxHealth() - entity.getHealth());

                entity.heal(heal);

                if (!level.isClientSide()) {
                    this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getStatisticData().getMetricData("heal_amount").addValue(heal);

                    this.getRelicData(entity, stack).getLevelingData().addExperience("camouflage", "healing", heal);
                }
            }

            if (!level.isClientSide()) {
                this.getRelicData(entity, stack).getLevelingData().addExperience("camouflage", "hiding", 1);

                this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getStatisticData().getMetricData("hide_duration").addValue(1);
            }
        }
    } else {
        if (hiding)
            this.setHiding(stack, false);

        if (progress > 0)
            this.addCurrentProgress(stack, -1);
    }
}

private boolean shoot(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, @Nullable Player player, EquipmentSlot slot) {
  Level level = entity.level();

  // first, try to find the requested ammo
  // TODO: multishot?
  ItemStack fireball = BowAmmoModifierHook.consumeAmmo(tool, ItemStack.EMPTY, entity, player, this, 1);
  if (!fireball.isEmpty()) {
    // if we found a fireball, fire it
    if (!level.isClientSide) {
      // fetch stats
      float power = ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.PROJECTILE_DAMAGE);
      float velocity = ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.VELOCITY);
      float inaccuracy = ModifierUtil.getInaccuracy(tool, entity) / 16f;


      // prepare projectile
      Vec3 lookVec = entity.getLookAngle().scale(2);
      RandomSource random = entity.getRandom();
      CustomFireball projectile = new CustomFireball(level, entity, lookVec.x + random.nextGaussian() * inaccuracy, lookVec.y, lookVec.z + random.nextGaussian() * inaccuracy);
      projectile.xPower *= velocity;
      projectile.yPower *= velocity;
      projectile.zPower *= velocity;
      projectile.setPower(power);
      projectile.setPos(projectile.getX(), entity.getY(0.5D) + 0.5D, projectile.getZ());

      // add in type specific behavior
      projectile.setItem(fireball);
      FireballType type = getFireballType(fireball);
      projectile.setDamageMultiplier(damageMultiplier * type.damageMultiplier);
      DamageTypePair damageTypes = type.damageType(this.damageType);
      projectile.setDamageType(damageTypes.ranged(), damageTypes.melee());

      // set projectile modifiers
      ModifierNBT modifiers = tool.getModifiers();
      if (!ammoModifiers.isEmpty()) {
        ModifierNBT.Builder builder = ModifierNBT.builder();
        builder.add(modifiers);
        builder.add(ammoModifiers);
        builder.add(type.ammoModifiers);
        modifiers = builder.build();
      }
      EntityModifierCapability.getCapability(projectile).setModifiers(modifiers);

      // fetch the persistent data for the fireball as modifiers may want to store data
      ModDataNBT projectileData = PersistentDataCapability.getOrWarn(projectile);
      // let modifiers set properties
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, entity, ItemStack.EMPTY, projectile, null, projectileData, true);
      }

      // finally, release the projectile
      level.addFreshEntity(projectile);

      // damage tool if not creative
      if (ModifierUtil.consumesResources(player)) {
        ToolDamageUtil.damageAnimated(tool, durability.compute(modifier), entity, slot, modifier.getId());
      }
    }
    entity.playSound(sound, 2.0F, (level.random.nextFloat() - level.random.nextFloat()) * 0.2F + 1.0F);
    return true;
  }
  return false;
}

public InteractionResult onToolUse(IToolStackView tool, ModifierEntry modifier, Player player, InteractionHand hand, InteractionSource source) {
  // disallow casting if the main hand can cast. Only comes up if the main hand is doing left click fishing; vanilla limitations means we can't support that
  if (source != InteractionSource.ARMOR && !tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source) && (hand == InteractionHand.MAIN_HAND || !player.getMainHandItem().canPerformAction(ToolActions.FISHING_ROD_CAST))) {
    Level level = player.level();
    if (player.fishing != null) {
      ItemStack stack = player.getItemInHand(hand);
      // due to fishing rod buggy behavior, chance we end up retrieving someone else's cast, so keep this logic 1 to 1 with vanilla
      if (!level.isClientSide) {
        int damage = player.fishing.retrieve(stack);
        if (damage > 0) {
          ToolDamageUtil.damageAnimated(tool, damage, player, Util.getSlotType(hand));
          // we apply cooldown as this is a weapon, don't want to let you spam it. But only need the cooldown if something happened
          GeneralInteractionModifierHook.addCooldown(tool, player, 1);
        }
      }

      level.playSound( null, player.getX(), player.getY(), player.getZ(), SoundEvents.FISHING_BOBBER_RETRIEVE, SoundSource.NEUTRAL, 1, 0.4f / (level.getRandom().nextFloat() * 0.4f + 0.8f));
      player.gameEvent(GameEvent.ITEM_INTERACT_FINISH);
    } else {
      level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.FISHING_BOBBER_THROW, SoundSource.NEUTRAL, 0.5f, 0.4f / (level.getRandom().nextFloat() * 0.4f + 0.8f));
      if (!level.isClientSide) {
        float luck = ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.SEA_LUCK);
        float lure = ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.LURE);
        float velocity = ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.VELOCITY);
        float inaccuracy = ModifierUtil.getInaccuracy(tool, player);
        CombatFishingHook hook = new CombatFishingHook(player, level, (int) luck, (int) lure, velocity, inaccuracy);
        hook.setPower(ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.PROJECTILE_DAMAGE));
        // apply material for the renderer
        hook.setMaterial(tool.getMaterial(tool.getVolatileData().getInt(HOOK_MATERIAL)).getVariant());

        // copy tool data to the bobber for modifier hooks
        ModifierNBT modifiers = tool.getModifiers();
        EntityModifierCapability.getCapability(hook).setModifiers(modifiers);
        // apply grapple or drill
        if (ModifierUtil.canPerformAction(tool, TinkerToolActions.GRAPPLE_HOOK)) {
          hook.setGrapple(ModifierUtil.canPerformAction(tool, TinkerToolActions.DRILL_ATTACK) ? GrappleType.DRILL : GrappleType.DASH);
        }
        // apply collecting
        if (ModifierUtil.canPerformAction(tool, TinkerToolActions.ITEM_HOOK)) {
          hook.setCollecting();
        }

        // fetch the persistent data for the hook as modifiers may want to store data
        ModDataNBT arrowData = PersistentDataCapability.getOrWarn(hook);

        // let modifiers such as fiery and punch set properties
        for (ModifierEntry entry : modifiers.getModifiers()) {
          entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, player, ItemStack.EMPTY, hook, null, arrowData, true);
        }
        level.addFreshEntity(hook);
      }

      player.awardStat(Stats.ITEM_USED.get(tool.getItem()));
      player.gameEvent(GameEvent.ITEM_INTERACT_START);
    }

    if (level.isClientSide) {
      OffhandCooldownTracker.swingHand(player, hand, false);
    }
    return InteractionResult.CONSUME;
  }
  return InteractionResult.PASS;
}

private void spit(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int chargeTime) {
  // find the fluid to spit
  FluidStack fluid = TANK_HELPER.getFluid(tool);
  if (!fluid.isEmpty()) {
    FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
    if (recipe.hasEffects()) {
      // projectile stats
      float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
      // power - size of each individual projectile
      float power = charge * ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.PROJECTILE_DAMAGE);
      // level acts like multishot level, meaning higher produces more projectiles
      int shots = this.shots.compute(modifier.getEffectiveLevel());
      // amount is the amount per projectile, total cost is amount times level
      // if its 0, that means we have only a couple mb left
      int amount = Math.min(fluid.getAmount(), (int)(recipe.getAmount(fluid.getFluid()) * power) * shots) / shots;
      if (amount > 0) {
        // other stats now that we know we are shooting
        // velocity determines how far it goes, does not impact damage unlike bows
        float velocity = ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.VELOCITY) * charge * 3.0f;
        float inaccuracy = ModifierUtil.getInaccuracy(tool, entity);

        // multishot stuff
        float startAngle = ModifiableLauncherItem.getAngleStart(shots);
        int primaryIndex = shots / 2;
        Level world = entity.level();
        for (int shotIndex = 0; shotIndex < shots; shotIndex++) {
          FluidEffectProjectile spit = new FluidEffectProjectile(world, entity, new FluidStack(fluid, amount), power);
          // apply fins
          spit.setWaterInertia(ConditionalStatModifierHook.getModifiedStat(tool, entity, ToolStats.WATER_INERTIA));

          // setup projectile target
          Vec3 upVector = entity.getUpVector(1.0f);
          float angle = startAngle + (10 * shotIndex);
          Vector3f targetVector = entity.getViewVector(1.0f).toVector3f().rotate((new Quaternionf()).setAngleAxis(angle * Math.PI / 180F, upVector.x, upVector.y, upVector.z));
          spit.shoot(targetVector.x(), targetVector.y(), targetVector.z(), velocity, inaccuracy);

          // store all modifiers on the spit
          EntityModifierCapability.getCapability(spit).setModifiers(tool.getModifiers());

          // fetch the persistent data for the arrow as modifiers may want to store data
          ModDataNBT arrowData = PersistentDataCapability.getOrWarn(spit);
          // let modifiers set properties
          for (ModifierEntry entry : tool.getModifierList()) {
            entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, entity, ItemStack.EMPTY, spit, null, arrowData, shotIndex == primaryIndex);
          }

          // finally, fire the projectile
          world.addFreshEntity(spit);
          world.playSound(null, entity.getX(), entity.getY(), entity.getZ(), Sounds.SPIT.getSound(), SoundSource.PLAYERS, 1.0F, 1.0F / (world.getRandom().nextFloat() * 0.4F + 1.2F) + charge * 0.5F + (angle / 10f));

        }

        // consume the fluid and durability
        if (ModifierUtil.consumesResources(entity)) {
          fluid.shrink(amount * shots);
          TANK_HELPER.setFluid(tool, fluid);
        }
        // stop using doesn't know the slot, so just figure it out
        ToolDamageUtil.damageAnimated(tool, shots, entity, modifier.getId());
      }
    }
  }
}

public InteractionResult afterBlockUse(IToolStackView tool, ModifierEntry modifier, UseOnContext context, InteractionSource source) {
  if (!tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
    FluidStack fluid = TANK_HELPER.getFluid(tool);
    if (!fluid.isEmpty()) {
      FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
      if (recipe.hasBlockEffects()) {
        Player player = context.getPlayer();
        Level world = context.getLevel();

        // cooldown based on draw speed, works similarly enough to attack speed
        // applied before we do the effect to block recursive calls, notably ender might cause that
        if (player != null) {
          player.getCooldowns().addCooldown(tool.getItem(), (int)(20 / ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.DRAW_SPEED)));
        }

        if (!world.isClientSide) {
          float level = strength.compute(modifier);
          int numTargets = 0;
          BlockHitResult hit = context.getHitResult();
          BlockState state = world.getBlockState(hit.getBlockPos());
          int consumed = recipe.applyToBlock(fluid, level, FluidEffectContext.builder(world).user(player).block(hit), FluidAction.EXECUTE);
          if (consumed > 0) {
            numTargets++;
            spawnParticles(world, hit, fluid);
            fluid.shrink(consumed);
          }

          // AOE selection logic, get boosted from expanded
          if (!fluid.isEmpty()) {
            for (BlockPos offset : tool.getHook(ToolHooks.AOE_ITERATOR).getBlocks(tool, context, state, AOEMatchType.TRANSFORM)) {
              BlockHitResult offsetHit = Util.offset(hit, offset);
              consumed = recipe.applyToBlock(fluid, level, FluidEffectContext.builder(world).user(player).block(offsetHit), FluidAction.EXECUTE);
              if (consumed > 0) {
                numTargets++;
                spawnParticles(world, offsetHit, fluid);
                fluid.shrink(consumed);
                // stop if we run out of fluid
                if (fluid.isEmpty()) {
                  break;
                }
              }
            }
          }

          // update fluid in tool and damage tool
          if (ModifierUtil.consumesResources(player)) {
            if (numTargets > 0) {
              TANK_HELPER.setFluid(tool, fluid);
            }

            // damage the tool, we charge for the multiplier and for the number of targets hit
            ItemStack stack = context.getItemInHand();
            if (ToolDamageUtil.damage(tool, Mth.ceil(numTargets * level), player, stack, modifier.getId()) && player != null) {
              player.broadcastBreakEvent(source.getSlot(context.getHand()));
            }
          }
        }
        return InteractionResult.SUCCESS;
      }
    }
  }
  return InteractionResult.PASS;
}

private DiscreteVoxelShape updateLeaves(LevelAccessor world, BoundingBox boundingBox, Set<BlockPos> logs, Set<BlockPos> leaves) {
  List<Set<BlockPos>> distanceList = Lists.newArrayList();
  DiscreteVoxelShape shapePart = new BitSetDiscreteVoxelShape(boundingBox.getXSpan(), boundingBox.getYSpan(), boundingBox.getZSpan());
  for (int j = 0; j < 6; ++j) {
    distanceList.add(Sets.newHashSet());
  }

  BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos();

  //for (BlockPos leavePos : Lists.newArrayList(leaves)) {
    //if (boundingBox.isInside(leavePos)) {
      //TODO shapePart.setFull(leavePos.getX() - boundingBox.minX(), leavePos.getY() - boundingBox.minY(), leavePos.getZ() - boundingBox.minZ(), true, true);
    //}
  //}

  for (BlockPos logPos : Lists.newArrayList(logs)) {
    //if (boundingBox.isInside(logPos)) {
      //TODO shapePart.setFull(logPos.getX() - boundingBox.minX(), logPos.getY() - boundingBox.minY(), logPos.getZ() - boundingBox.minZ(), true, true);
    //}
    for (Direction direction : Direction.values()) {
      mutable.setWithOffset(logPos, direction);
      if (!logs.contains(mutable)) {
        BlockState blockstate = world.getBlockState(mutable);
        if (blockstate.hasProperty(BlockStateProperties.DISTANCE)) {
          distanceList.get(0).add(mutable.immutable());
          setBlockStateAt(world, mutable, blockstate.setValue(BlockStateProperties.DISTANCE, 1));
          //if (boundingBox.isInside(mutable)) {
            //TODO shapePart.setFull(mutable.getX() - boundingBox.minX(), mutable.getY() - boundingBox.minY(), mutable.getZ() - boundingBox.minZ(), true, true);
          //}
        }
      }
    }
  }

  for (int distance = 1; distance < 6; ++distance) {
    Set<BlockPos> current = distanceList.get(distance - 1);
    Set<BlockPos> next = distanceList.get(distance);

    for (BlockPos pos : current) {
      //if (boundingBox.isInside(pos)) {
        //TODO shapePart.setFull(pos.getX() - boundingBox.minX(), pos.getY() - boundingBox.minY(), pos.getZ() - boundingBox.minZ(), true, true);
      //}

      for (Direction direction : Direction.values()) {
        mutable.setWithOffset(pos, direction);
        if (!current.contains(mutable) && !next.contains(mutable)) {
          BlockState state = world.getBlockState(mutable);
          if (state.hasProperty(BlockStateProperties.DISTANCE)) {
            int stateDistance = state.getValue(BlockStateProperties.DISTANCE);
            if (stateDistance > distance + 1) {
              BlockState furtherState = state.setValue(BlockStateProperties.DISTANCE, distance + 1);
              setBlockStateAt(world, mutable, furtherState);
              //if (boundingBox.isInside(mutable)) {
                //TODO shapePart.setFull(mutable.getX() - boundingBox.minX(), mutable.getY() - boundingBox.minY(), mutable.getZ() - boundingBox.minZ(), true, true);
              //}
              next.add(mutable.immutable());
            }
          }
        }
      }
    }
  }

  return shapePart;
}

public void rebuildStats() {
  // quick safety checks: to rebuild stats we need
  // * tool definition (contains stats and traits)
  // * material registry (to fetch material stats and traits)
  // * modifier registry (run relevant modifier hooks)
  // * item tags (control tool behaviors in various places)
  // if any of these are missing, attempting to rebuild stats may corrupt the tool's state (persistent data, damage, broken)
  if (!definition.isDataLoaded() || !MaterialRegistry.isFullyLoaded() || !ModifierManager.INSTANCE.isDynamicModifiersLoaded() || !TinkerTags.isTagsLoaded()) {
    return;
  }

  // add tool slots to volatile data, ensures it is there even from an empty tool, and properly updates on datapack update
  ToolDefinitionData toolData = getDefinitionData();

  // first, determine the list of modifiers, this is done in a couple stages
  // we start by cloning upgrades and adding tool traits and material traits
  MaterialNBT materials = getMaterials();
  ModifierNBT.Builder modBuilder = ModifierNBT.builder();
  modBuilder.add(getUpgrades());
  toolData.getHook(ToolHooks.TOOL_TRAITS).addTraits(definition, materials, modBuilder);
  ModifierNBT beforeTraits = modBuilder.build();

  // temporary context while we add modifier traits, will recreate if we have modifiers
  // clear out volatile data, mostly affects the volatile data hook
  ToolRebuildContext context = new ToolRebuildContext(item, definition, materials, getUpgrades(), beforeTraits, getPersistentData());

  // if we have modifiers, apply modifier traits, saves creating some builders if empty
  List<ModifierEntry> modifierList = Collections.emptyList();
  if (beforeTraits.isEmpty()) {
    // if no modifiers, just clear modifiers
    setModifiers(ModifierNBT.EMPTY);
  } else {
    modBuilder = ModifierNBT.builder();
    TraitBuilder traitBuilder = new TraitBuilder(context, modBuilder);
    traitBuilder.add(beforeTraits);

    // set the final modifier list on the tool
    ModifierNBT allMods = modBuilder.build();
    setModifiers(allMods);
    modifierList = allMods.getModifiers();
    // context for further modifier hooks
    context = context.withModifiers(allMods);
  }

  // build volatile data first, it's a parameter to the other hooks
  ToolDataNBT volatileData = new ToolDataNBT();
  toolData.getHook(ToolHooks.VOLATILE_DATA).addVolatileData(context, volatileData);
  for (ModifierEntry entry : modifierList) {
    entry.getHook(ModifierHooks.VOLATILE_DATA).addVolatileData(context, entry, volatileData);
  }
  setVolatileModData(volatileData);

  // regular stats last so we can include volatile data
  ModifierStatsBuilder statBuilder = ModifierStatsBuilder.builder();
  toolData.getHook(ToolHooks.TOOL_STATS).addToolStats(context, statBuilder);
  for (ModifierEntry entry : modifierList) {
    entry.getHook(ModifierHooks.TOOL_STATS).addToolStats(context, entry, statBuilder);
  }
  setStats(statBuilder.build());
  setMultipliers(statBuilder.buildMultipliers());

  // finally, update raw data, called last to make the parameters more convenient mostly, plus no other hooks should be responding to this data
  for (ModifierEntry entry : modifierList) {
    entry.getHook(ModifierHooks.RAW_DATA).addRawData(this, entry, getRestrictedNBT());
  }
}

public void onInventoryTick(IToolStackView tool, ModifierEntry modifier, Level world, LivingEntity holder, int itemSlot, boolean isSelected, boolean isCorrectSlot, ItemStack stack) {
  // overslime increases every 2^(4-level) seconds
  // that is 1 per second at 4 levels, 1 per 8 seconds at 1 level
  // we support max level 6, as that leaves us working with integers
  int level = Math.min(modifier.getLevel(), 6);
  int updateInterval = 5 << (6 - level);

  // don't run if drawing back a bow, prevents losing animation
  // does mean you may end up wasting some fuel, could be as much as 19 lost. So, don't hold your bows for 20 updates?
  if (!world.isClientSide && holder.tickCount % updateInterval == 0 && holder.getUseItem() != stack) {
    // must have overslime and space to fill
    if (OverslimeModule.INSTANCE.getAmount(tool) < OverslimeModule.getCapacity(tool)) {
      // find current fuel info
      ResourceLocation key = modifier.getId();
      FuelInfo info = FuelInfo.read(tool, key);

      // if we have no fuel, try and find some
      boolean neededFuel = info == null;
      // since we will write this to NBT, use game time as that is global
      long time = holder.level().getGameTime();
      if (neededFuel || info.expiration < time) {
        info = null;
        FluidStack fluid = ToolTankHelper.TANK_HELPER.getFluid(tool);
        if (!fluid.isEmpty()) {
          MeltingFuel fuel = MeltingFuelLookup.findFuel(fluid.getFluid());
          if (fuel != null) {
            // scale amount consumed by level
            int amount = fuel.getAmount(fluid.getFluid());
            // scale up fuel duration so we always get the same amount of overslime per fuel bucket
            // if we didn't do this, lower levels would consume way more than higher ones
            // this works out to equivalent to the alloyer/melter at level 4
            // note this does mean changing trait levels multiplies fuel efficiency, but the part swap costs more than just adding a slimeball so its fine
            int duration = fuel.getDuration() * updateInterval / 5;
            // if we don't have a full recipe, use what is left but scale down the duration
            if (amount > fluid.getAmount()) {
              ToolTankHelper.TANK_HELPER.setFluid(tool, FluidStack.EMPTY);
              duration = duration * fluid.getAmount() / amount;
            } else {
              // if we have a complete recipe, just decrease fluid in the tank
              fluid.shrink(amount);
              ToolTankHelper.TANK_HELPER.setFluid(tool, fluid);
            }
            info = new FuelInfo(time + duration, fuel.getRate());
          }
        }
        // store current fuel in NBT for next round if it will last
        // no need to store if it will expire before our next update tick though
        if (info != null && info.expiration >= time + updateInterval) {
          info.write(tool, key);
        } else if (!neededFuel) {
          // no need to remove if we had nothing, saves some hash map modifications
          tool.getPersistentData().remove(key);
        }
      }
      // if we have fuel, increase overslime
      if (info != null) {
        // restore 1 per 10 rate. For the remainder, treat it as a chance
        int restore = info.rate / 10;
        int remainder = info.rate % 10;
        if (remainder > 0 && Modifier.RANDOM.nextInt(10) < remainder) {
          restore++;
        }
        OverslimeModule.INSTANCE.addAmount(tool, restore);
      }
    }
  }
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    var entity = slotContext.entity();

    if (entity instanceof Player player && !player.level().isClientSide()) {
        if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("gluttony").canPlayerUse(player)) {
            var foodLevel = player.getFoodData().getFoodLevel();
            var center = 10;

            var above = Math.max(0, foodLevel - center);
            var below = Math.max(0, center - foodLevel);

            var positive = above * this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gluttony").getStatData("early_multiplier").getValue();
            var negative = below * this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gluttony").getStatData("late_multiplier").getValue();

            var modifier = Math.clamp(positive - negative, -0.9D, 1.0D);

            if (modifier > 0.0001D)
                this.getRelicData(player, stack).getAbilitiesData().getAbilityData("gluttony").getStatisticData().getMetricData("positive_duration").addValue(1D / 20D);
            else if (modifier < -0.0001D)
                this.getRelicData(player, stack).getAbilitiesData().getAbilityData("gluttony").getStatisticData().getMetricData("negative_duration").addValue(1D / 20D);

            var blacklist = RelicsConfigs.RELICS_CONFIG.getRingOfSDSGluttonyAttributesBlacklist();

            for (var instance : entity.getAttributes().attributes.values()) {
                var attribute = instance.getAttribute();

                if (blacklist.contains(attribute.getRegisteredName()))
                    continue;

                EntityUtils.resetAttribute(entity, attribute, (float) modifier, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, getGluttonyAttributeId(stack, attribute, slotContext));
            }
        }
    }

    if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("sloth").canPlayerUse(entity)) {
        var slothData = stack.getOrDefault(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_SLOTH.get(), SlothData.create(entity.position(), entity.getYRot(), entity.getXRot(), 0));

        var positionDelta = entity.position().distanceToSqr(new Vec3(slothData.x(), slothData.y(), slothData.z()));
        var rotationDelta = Math.abs(entity.getYRot() - slothData.yaw()) + Math.abs(entity.getXRot() - slothData.pitch());

        var stillTicks = slothData.stillTicks();
        var gainedImmortality = false;

        if (positionDelta > 0.0001D || rotationDelta > 0.001F) {
            stillTicks = 0;
        } else {
            stillTicks++;

            var requiredTicks = Math.max(1, (int) Math.round(this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("sloth").getStatData("time").getValue() * 20D));
            var hasImmortality = entity.hasEffect(RelicsMobEffects.IMMORTALITY);

            if (stillTicks >= requiredTicks && !entity.level().isClientSide()) {
                entity.addEffect(new MobEffectInstance(RelicsMobEffects.IMMORTALITY, 5, 0, false, false, true));

                if (!hasImmortality)
                    gainedImmortality = true;
            }
        }

        stack.set(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_SLOTH.get(), slothData.with(entity.position(), entity.getYRot(), entity.getXRot(), stillTicks));

        if (gainedImmortality)
            this.getRelicData(entity, stack).getLevelingData().addExperience("sloth", "immortality", 1);

        if (entity.hasEffect(RelicsMobEffects.IMMORTALITY))
            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("sloth").getStatisticData().getMetricData("immortality_duration").addValue(1D / 20D);
    }
}

static void chestplateInteractWithBlock(PlayerInteractEvent.RightClickBlock event) {
  // only handle chestplate interacts if the current hand is empty
  Player player = event.getEntity();
  if (event.getItemStack().isEmpty() && !player.isSpectator()) {
    // item must be a chestplate
    // TODO 1.21: add a modifier tag so we only perform the cancellation if a modifier needs it
    ItemStack chestplate = player.getItemBySlot(EquipmentSlot.CHEST);
    if (chestplate.is(TinkerTags.Items.INTERACTABLE_ARMOR) && !player.getCooldowns().isOnCooldown(chestplate.getItem())) {
      // no turning back, from this point we are fully in charge of interaction logic (since we need to ensure order of the hooks)

      // begin interaction
      ToolStack tool = ToolStack.from(chestplate);
      InteractionHand hand = event.getHand();
      BlockHitResult trace = event.getHitVec();
      UseOnContext context = new UseOnContext(player, hand, trace);

      // first, before block use (in forge, onItemUseFirst)
      if (event.getUseItem() != Result.DENY) {
        InteractionResult result = onBlockUse(context, tool, chestplate, entry -> entry.getHook(ModifierHooks.BLOCK_INTERACT).beforeBlockUse(tool, entry, context, InteractionSource.ARMOR));
        if (result.consumesAction()) {
          event.setCanceled(true);
          event.setCancellationResult(result);
          return;
        }
      }

      // next, block interaction
      // empty stack automatically bypasses sneak, so no need to check the hand we interacted with, just need to check the other hand
      BlockPos pos = event.getPos();
      Result useBlock = event.getUseBlock();
      Level level = player.level();
      if (useBlock == Result.ALLOW || (useBlock != Result.DENY
                                       && (!player.isSecondaryUseActive() || player.getItemInHand(Util.getOpposite(hand)).doesSneakBypassUse(level, pos, player)))) {
        InteractionResult result = level.getBlockState(pos).use(level, player, hand, trace);
        if (result.consumesAction()) {
          if (player instanceof ServerPlayer serverPlayer) {
            CriteriaTriggers.ITEM_USED_ON_BLOCK.trigger(serverPlayer, pos, ItemStack.EMPTY);
          }
          event.setCanceled(true);
          event.setCancellationResult(result);
          return;
        }
      }

      // regular item interaction: must not be deny, and either be allow or not have a cooldown
      Result useItem = event.getUseItem();
      event.setCancellationResult(InteractionResult.PASS);
      if (useItem != Result.DENY && (useItem == Result.ALLOW || !player.getCooldowns().isOnCooldown(chestplate.getItem()))) {
        // finally, after block use (in forge, onItemUse)
        InteractionResult result = onBlockUse(context, tool, chestplate, entry -> entry.getHook(ModifierHooks.BLOCK_INTERACT).afterBlockUse(tool, entry, context, InteractionSource.ARMOR));
        if (result.consumesAction()) {
          event.setCanceled(true);
          event.setCancellationResult(result);
          if (player instanceof ServerPlayer serverPlayer) {
            CriteriaTriggers.ITEM_USED_ON_BLOCK.trigger(serverPlayer, pos, ItemStack.EMPTY);
          }
          return;
        }
      }

      // did not interact with an entity? try direct interaction
      // needs to be run here as the interact empty hook does not fire when targeting blocks
      InteractionResult result = onChestplateUse(player, chestplate, hand);
      event.setCanceled(true);
      event.setCancellationResult(result);
    }
  }
}

public void tick() {
    super.tick();

    if (!this.isNoGravity())
        this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.03D, 0.0D));

    if (!this.level().noCollision(this.getBoundingBox()))
        this.moveTowardsClosestSpace(this.getX(), (this.getBoundingBox().minY + this.getBoundingBox().maxY) / 2.0D, this.getZ());

    if (this.tickCount >= 15) {
        for (var tooth : this.level().getEntitiesOfClass(GoldenToothEntity.class, this.getBoundingBox())) {
            if (tooth.getUUID().equals(this.getUUID()) || tooth.isRemoved())
                continue;

            this.setStacks(this.getStacks() + tooth.getStacks());

            tooth.discard();
        }

        double maxDistance = 16;

        var player = this.level().getNearestPlayer(this.getX(), this.getY(), this.getZ(), maxDistance, entity -> {
            var entry = (Player) entity;

            return !entry.isSpectator() && !this.getSuitableRelics(entry).isEmpty();
        });

        if (player != null) {
            this.setDeltaMovement(this.getDeltaMovement().add(player.position().add(0F, player.getBbHeight() / 2F, 0F).subtract(this.position()).normalize().scale((maxDistance - this.position().distanceTo(player.position())) / (maxDistance * 10))));

            if (this.position().distanceTo(player.position()) <= player.getBbWidth() * 1.25F) {
                var suitable = this.getSuitableRelics(player);

                for (var stack : suitable) {
                    var relic = ((PiglinMaskItem) stack.getItem());

                    if (relic.getStacks(stack) < PiglinMaskItem.getMaxStacks()) {
                        relic.addStacks(stack, this.getStacks());
                        relic.setDuration(player, stack, relic.getMaxDuration(player, stack));

                        relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("looting").getStatisticData().getMetricData("teeth_picked_up").addValue(this.getStacks());
                        relic.getRelicData(player, stack).getLevelingData().addExperience("looting", "stack", this.getStacks());
                    }

                    player.addItem(new ItemStack(RelicsItems.GOLDEN_TOOTH.get(), this.getStacks()));

                    this.discard();

                    this.level().playSound(null, this.blockPosition(), SoundEvents.ARMOR_EQUIP_GOLD.value(), SoundSource.MASTER, 0.5F, 1.25F + this.level().getRandom().nextFloat() * 0.75F);
                }
            }
        }
    }

    this.move(MoverType.SELF, this.getDeltaMovement());

    var friction = 0.98F;

    if (this.onGround()) {
        var pos = getBlockPosBelowThatAffectsMyMovement();

        friction = this.level().getBlockState(pos).getFriction(this.level(), pos, this) * 0.98F;
    }

    this.setDeltaMovement(this.getDeltaMovement().multiply(friction, 0.98D, friction));

    if (this.onGround())
        this.setDeltaMovement(this.getDeltaMovement().multiply(1D, -0.9D, 1D));

    if (this.tickCount >= 1000)
        this.discard();
}

public void sling(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int chargeTime, ModifierEntry activeModifier) {
  Level level = entity.level();
  if (!level.isClientSide && entity instanceof ServerPlayer player) {
    // must have enough charge and force must not be zeroed by a modifier
    // don't care about multiplier here as no knockback to change it
    float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
    if (charge > 0 && target.matches(entity)) {
      float multiplier = charge * this.forceMultiplier.compute(modifier);
      float force = SlingForceModifierHook.modifySlingForce(tool, entity, entity, modifier, SlingModule.getPower(tool, entity) * multiplier, multiplier);
      if (force > 0) {
        Vec3 look = player.getLookAngle();
        float inaccuracy = ModifierUtil.getInaccuracy(tool, player) * 0.0075f;
        RandomSource random = player.getRandom();
        Vec3 angle = SlingAngleModifierHook.modifySlingAngle(tool, entity, entity, modifier, force, multiplier, new Vec3(
          look.x + random.nextGaussian() * inaccuracy,
          look.y + random.nextGaussian() * inaccuracy,
          look.z + random.nextGaussian() * inaccuracy
        ));
        double offX = angle.x * force;
        double offY = angle.y * force + 1; // add extra to help with bad collisions
        double offZ = angle.z * force;

        // find teleport target
        BlockPos furthestPos = null;
        while (Math.abs(offX) > .5 || Math.abs(offY) > .5 || Math.abs(offZ) > .5) { // while not too close to player
          BlockPos posAttempt = BlockPos.containing(player.getX() + offX, player.getY() + offY, player.getZ() + offZ);
          // if we do not have a position yet, see if this one is valid
          if (furthestPos == null) {
            if (level.getWorldBorder().isWithinBounds(posAttempt) && !level.getBlockState(posAttempt).isSuffocating(level, posAttempt)) {
              furthestPos = posAttempt;
            }
          } else {
            // if we already have a position, clear if the new one is unbreakable
            if (level.getBlockState(posAttempt).getDestroySpeed(level, posAttempt) == -1) {
              furthestPos = null;
            }
          }

          // update for next iteration
          offX -= (Math.abs(offX) > .25 ? (offX >= 0 ? 1 : -1) * .25 : 0);
          offY -= (Math.abs(offY) > .25 ? (offY >= 0 ? 1 : -1) * .25 : 0);
          offZ -= (Math.abs(offZ) > .25 ? (offZ >= 0 ? 1 : -1) * .25 : 0);
        }

        // get furthest teleportable block
        if (furthestPos != null) {
          SlingModifierTeleportEvent event = new SlingModifierTeleportEvent(player, furthestPos.getX() + 0.5f, furthestPos.getY(), furthestPos.getZ() + 0.5f, tool, modifier);
          MinecraftForge.EVENT_BUS.post(event);
          if (!event.isCanceled()) {
            player.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());

            // only called if we successfully teleport
            SlingLaunchModifierHook.afterSlingLaunch(tool, entity, entity, modifier, force, multiplier, angle);

            // particle effect from EnderPearlEntity
            for (int i = 0; i < 32; ++i) {
              level.addParticle(ParticleTypes.PORTAL, player.getX(), player.getY() + level.random.nextDouble() * 2.0D, player.getZ(), level.random.nextGaussian(), 0.0D, level.random.nextGaussian());
            }
            level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.SLIME_SLING_TELEPORT.getSound(), player.getSoundSource(), 1f, 1f);
            player.causeFoodExhaustion(0.2F);
            player.getCooldowns().addCooldown(tool.getItem(), 3);
            ToolDamageUtil.damageAnimated(tool, 1, entity, entity.getUsedItemHand(), modifier.getId());
            return;
          }
        }
      }
    }
    if (ModifierUtil.isActiveModifier(tool, modifier, activeModifier)) {
      level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), Sounds.SLIME_SLING_TELEPORT.getSound(), entity.getSoundSource(), 1, 0.5f);
    }
  }
}

public static void onLivingIncomingDamage(LivingIncomingDamageEvent event) {
    if (event.getEntity() instanceof Player player && !player.level().isClientSide()) {
        var attacker = event.getSource().getEntity() instanceof LivingEntity livingAttacker ? livingAttacker : null;

        if (attacker == null && event.getSource().getDirectEntity() instanceof Projectile projectile
                && projectile.getOwner() instanceof LivingEntity projectileOwner) {
            attacker = projectileOwner;
        }

        if (attacker != null && attacker != player) {
            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GLITCHY_MANTLE.get())) {
                var relic = (GlitchyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("distortion");

                if (!ability.canPlayerUse(player) || !TargetingUtils.canHarm(player, attacker, stack, "distortion"))
                    continue;

                if (player.getRandom().nextDouble() >= ability.getStatData("miss_chance").getValue())
                    continue;

                event.setCanceled(true);

                player.addEffect(new MobEffectInstance(RelicsMobEffects.GLITCH, 10, 0, false, false));

                ability.getStatisticData().getMetricData("misses").addValue(1);
                relic.getRelicData(player, stack).getLevelingData().addExperience("distortion", "miss", 1);

                if (ability.getRankModifierData("disorientation").isEnabled()) {
                    var rotation = attacker.getRandom().nextFloat() * 360F;

                    if (attacker instanceof ServerPlayer serverAttacker)
                        serverAttacker.teleportTo(serverAttacker.serverLevel(), serverAttacker.getX(), serverAttacker.getY(), serverAttacker.getZ(), rotation, serverAttacker.getXRot());

                    attacker.setYRot(rotation);
                    attacker.setYHeadRot(rotation);
                    attacker.setYBodyRot(rotation);
                    attacker.yRotO = rotation;
                    attacker.yHeadRotO = rotation;
                    attacker.yBodyRotO = rotation;

                    if (attacker instanceof Mob mob) {
                        mob.setTarget(null);

                        var radians = Math.toRadians(rotation);
                        var direction = new Vec3(-Math.sin(radians), 0D, Math.cos(radians));
                        var destination = mob.position().add(direction.scale(3D));

                        mob.getNavigation().stop();
                        mob.getNavigation().moveTo(destination.x(), destination.y(), destination.z(), 1D);
                    }
                }

                return;
            }
        }
    }

    if (!event.getContainer().getSource().is(DamageTypes.IN_WALL))
        return;

    var entity = event.getEntity();

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.GLITCHY_MANTLE.get())) {
        var relic = (GlitchyMantleItem) stack.getItem();
        var ability = relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch");

        if (relic.isGlitchEnabled(entity, stack) && ability.getRankModifierData("phase").isEnabled()) {
            event.setCanceled(true);

            return;
        }
    }
}

private void tickGaze(LivingEntity owner, ItemStack stack) {
    var ability = this.getRelicData(owner, stack).getAbilitiesData().getAbilityData("gaze");
    var charges = this.getGazeCharges(stack);
    var changed = false;

    if (!ability.canPlayerUse(owner)) {
        if (!charges.isEmpty()) {
            charges.clear();
            this.setGazeCharges(stack, charges);
        }

        return;
    }

    var seenThisTick = new java.util.HashSet<String>();
    var range = ability.getStatData("range").getValue();
    var maxCharges = Math.max(1, (int) MathUtils.round(ability.getStatData("charges").getValue(), 0));

    for (var target : owner.level().getEntitiesOfClass(LivingEntity.class, owner.getBoundingBox().inflate(range),
            entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarm(owner, entity, stack, "gaze"))) {
        var key = target.getStringUUID();
        var looking = isLookingAt(target, owner) && target.hasLineOfSight(owner);
        var data = charges.getOrDefault(key, GazeChargeData.EMPTY);

        if (!looking)
            continue;

        seenThisTick.add(key);

        var lookTicks = data.lookTicks() + 1;
        var currentCharges = data.charges();

        if (lookTicks >= 20) {
            lookTicks = 0;

            if (currentCharges < maxCharges) {
                currentCharges++;
                ability.getStatisticData().getMetricData("charges_applied").addValue(1);
                this.getRelicData(owner, stack).getLevelingData().addExperience("gaze", "eye_contact", 1);
            }
        }

        charges.put(key, new GazeChargeData(currentCharges, lookTicks, 0));
        changed = true;
    }

    var iterator = charges.entrySet().iterator();

    while (iterator.hasNext()) {
        var entry = iterator.next();

        if (seenThisTick.contains(entry.getKey()))
            continue;

        var data = entry.getValue();
        var decayTicks = data.decayTicks() + 1;
        var currentCharges = data.charges();

        if (decayTicks >= 20) {
            decayTicks = 0;
            currentCharges--;
        }

        if (currentCharges <= 0)
            iterator.remove();
        else
            entry.setValue(new GazeChargeData(currentCharges, 0, decayTicks));

        changed = true;
    }

    if (changed)
        this.setGazeCharges(stack, charges);
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    super.curioTick(slotContext, stack);

    var entity = slotContext.entity();
    var level = entity.level();
    var movementSpeedAttributeId = getMovementSpeedAttributeId(stack, slotContext);

    if (!this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glass").canPlayerUse(entity)) {
        this.setSpeedBlend(stack, 0F);

        EntityUtils.removeAttribute(entity, Attributes.MOVEMENT_SPEED, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, movementSpeedAttributeId);

        return;
    }

    if (level.isClientSide())
        return;

    var position = entity.position();
    var state = level.getFluidState(level.clip(new ClipContext(position, position.add(0, -2, 0), ClipContext.Block.OUTLINE, ClipContext.Fluid.ANY, entity)).getBlockPos());

    var attribute = Attributes.MOVEMENT_SPEED;
    var operation = AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL;

    var targetProgress = 0F;
    var fluidAmount = 0;
    var progressBeforeUpdate = this.getSpeedBlend(stack);

    if (state.getType() != Fluids.EMPTY) {
        var entry = this.getFluidEntries(entity, stack).get(state.getFluidType().toString());

        if (entry != null) {
            targetProgress = 20F;
            fluidAmount = entry.getAmount();
        }
    }

    if (targetProgress > 0F && entity.tickCount % 20 == 0) {
        if (entity.getKnownMovement().multiply(1, 0, 1).length() > 0)
            this.getRelicData(entity, stack).getLevelingData().addExperience("glass", "standing", 1);

        this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glass").getStatisticData().getMetricData("duration").addValue(1);
    }

    var progress = progressBeforeUpdate;

    if (progress < targetProgress)
        progress = Math.min(targetProgress, progress + 1F);
    else if (progress > targetProgress)
        progress = Math.max(targetProgress, progress - 1F);

    this.setSpeedBlend(stack, progress);

    var maxModifier = (float) (-0.5F + fluidAmount / 1000F * this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glass").getStatData("speed").getValue());

    if (targetProgress <= 0F && progressBeforeUpdate > 1.0E-4F) {
        var attributeInstance = entity.getAttribute(attribute);

        if (attributeInstance != null) {
            var existing = attributeInstance.getModifier(movementSpeedAttributeId);

            if (existing != null) {
                var ratioBeforeUpdate = progressBeforeUpdate / 20F;

                if (ratioBeforeUpdate > 1.0E-4F)
                    maxModifier = (float) (existing.amount() / ratioBeforeUpdate);
            }
        }
    }

    var modifier = maxModifier * (progress / 20F);

    EntityUtils.resetAttribute(entity, attribute, modifier, operation, movementSpeedAttributeId);
}

public static void addAbilityDescriptions(
        Consumer<Component> tooltip,
        ItemStack stack,
        Item.TooltipContext context,
        TooltipDisplay display,
        TooltipFlag tooltipFlag,
        @Nullable Player player
) {
    if (!Artifacts.CONFIG.client.showTooltips.get()) {
        return;
    }

    if (showsMissingDependencyTooltip(stack, display)) {
        tooltip.accept(Component.translatable("%s.tooltip.missing_dependency".formatted(Artifacts.MOD_ID))
                .withStyle(ChatFormatting.RED, ChatFormatting.BOLD)
        );
    } else if (showsCosmeticTooltip(stack, display)) {
        tooltip.accept(Component.translatable("%s.tooltip.cosmetic".formatted(Artifacts.MOD_ID))
                .withStyle(ChatFormatting.ITALIC).withStyle(ChatFormatting.GRAY)
        );
    } else if (ItemDamageUtil.needsRepair(stack)) {
        tooltip.accept(Component.translatable("%s.tooltip.broken".formatted(Artifacts.MOD_ID))
                .withStyle(ChatFormatting.RED)
        );
    }

    // Description that shows even when the item is cosmetic (used by Novelty Drinking Hat)
    TooltipHelper.getComponentIfVisible(ModDataComponents.ABILITY_LORE, stack, display)
            .forEach(lore -> lore.addToTooltip(context, tooltip, tooltipFlag, stack));

    // Tooltip order (a bit janky but vanilla does it in a similar way)
    Consumer<ComponentType<?, ? extends EquipmentAbility>> descriptions
            = type -> TooltipHelper.addAbilityDescription(tooltip, stack, context, display, type);

    // Non-equipable abilities
    descriptions.accept(ModDataComponents.HANDHELD_GLIDER);
    descriptions.accept(ModDataComponents.BLOCKS_ATTACKS);
    descriptions.accept(ModDataComponents.INFINITE_CONSUMABLE);
    descriptions.accept(ModDataComponents.EQUIPABLE_TOTEM);

    // Composite abilities
    descriptions.accept(ModDataComponents.MOB_EFFECTS);
    descriptions.accept(ModDataComponents.ENCHANTMENT_LEVEL_MODIFIERS);
    descriptions.accept(ModDataComponents.ATTRIBUTE_MODIFIERS);
    descriptions.accept(ModDataComponents.POST_DAMAGE_EFFECTS);
    descriptions.accept(ModDataComponents.POST_EATING_EFFECTS);
    descriptions.accept(ModDataComponents.ATTACK_EFFECTS);
    descriptions.accept(ModDataComponents.RETALIATION_EFFECTS);

    // Other
    descriptions.accept(ModDataComponents.TOOL_TIER_UPGRADE);
    descriptions.accept(ModDataComponents.DOUBLE_JUMP);
    descriptions.accept(ModDataComponents.CURE_EFFECTS);
    descriptions.accept(ModDataComponents.DAMAGE_ABSORPTION);
    descriptions.accept(ModDataComponents.ENDER_PEARL_HUNGER_COST);
    descriptions.accept(ModDataComponents.ENDER_PEARL_DAMAGE_IMMUNITY);
    descriptions.accept(ModDataComponents.REPLENISH_HUNGER_ON_GRASS);
    descriptions.accept(ModDataComponents.CREEPER_REPELLENT);
    descriptions.accept(ModDataComponents.PHANTOM_REPELLENT);
    descriptions.accept(ModDataComponents.SINKING);
    descriptions.accept(ModDataComponents.AUTO_SMELT);
    descriptions.accept(ModDataComponents.FLUID_COLLISION);
    descriptions.accept(ModDataComponents.SWIM_IN_AIR);
    descriptions.accept(ModDataComponents.WALK_ON_POWDER_SNOW);
    descriptions.accept(ModDataComponents.DAMAGE_IMMUNITY);
    descriptions.accept(ModDataComponents.POST_EATING_PLANT_GROWTH);

    // Toggle key(s)
    TooltipHelper.getComponentIfVisible(ModDataComponents.TOGGLE_KEY, stack, display).forEach(toggleKey -> {
        if (!TooltipHelper.isCosmetic(stack) && player != null && player.level().isClientSide()) {
            ToggleKeyHandlers.addTooltip(toggleKey, stack.has(ModDataComponents.DISABLED_BY_TOGGLE.get()), tooltip);
        }
    });
}

public void tick() {
    super.tick();

    this.setDeltaMovement(0D, 0D, 0D);

    if (this.level().isClientSide()) {
        if (this.getLifetime() - this.tickCount > 1) {
            var random = this.random;
            var radius = this.getRadius();

            var x = this.getX() + MathUtils.randomFloat(random) * radius;
            var z = this.getZ() + MathUtils.randomFloat(random) * radius;

            this.level().addParticle(new GhostlyFogParticle.Options(this.getLifetime() - this.tickCount - 1),
                    x,
                    this.getY() + random.nextDouble() * 2,
                    z,
                    MathUtils.randomFloat(random) * 0.01F,
                    -0.025F,
                    MathUtils.randomFloat(random) * 0.01F);
        }

        return;
    }

    if (this.tickCount > this.getLifetime()) {
        this.discard();

        return;
    }

    var owner = this.getOwner();
    var radius = this.getRadius();
    var gameTime = this.level().getGameTime();

    if (lastExposureCleanupTick != gameTime && gameTime % 200L == 0L) {
        lastExposureCleanupTick = gameTime;

        LAST_EXPOSURE_TICK.values().removeIf(tick -> tick < gameTime - 200L);
    }

    for (var target : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(radius),
            entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarm(owner, entity, this.getStack(), "fog"))) {
        target.getPersistentData().putFloat(GhostlyMantleItem.FOG_SUFFOCATION_DAMAGE_TAG, this.getSuffocationDamage());
        target.getPersistentData().putLong(GhostlyMantleItem.FOG_SUFFOCATION_UNTIL_TAG, this.level().getGameTime() + 5L);

        if (this.getAirDrain() > 0)
            target.setAirSupply(Math.max(-20, target.getAirSupply() - this.getAirDrain()));

        if (this.getTremorTicks() > 0)
            TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.TREMOR, this.getTremorTicks(), 0, false, false), owner, this.getStack(), "fog");

        if (target.getAirSupply() <= -20 && this.tickCount % 20 == 0)
            target.hurt(this.level().damageSources().inWall(), 1F);

        if (owner == null)
            continue;

        var key = owner.getStringUUID() + ":" + target.getStringUUID();

        if (LAST_EXPOSURE_TICK.getOrDefault(key, Long.MIN_VALUE) == gameTime)
            continue;

        LAST_EXPOSURE_TICK.put(key, gameTime);

        for (var stack : EntityUtils.findEquippedCurios(owner, RelicsItems.GHOSTLY_MANTLE.get())) {
            var relic = (GhostlyMantleItem) stack.getItem();
            var ability = relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("fog");

            if (!ability.canPlayerUse(owner))
                continue;

            ability.getStatisticData().getMetricData("fog_exposure").addValue(1D / 20D);
            relic.getRelicData(owner, stack).getLevelingData().addExperience("fog", "fog_exposure", 1D / 20D);

            break;
        }
    }
}

public void read(MapCarrierDecodable carrier, SerializationContext ctx, boolean sync){
    EndecUtils.dfuKeysCarrier(
            carrier,
            Map.of(
                    "SlotName", "slot_name",
                    "BaseSize", "base_size",
                    "CurrentSize", "current_size",
                    "RenderOptions", "render_options",
                    "Modifiers", "modifiers",
                    "PersistentModifiers", "persistent_modifiers",
                    "CachedModifiers", "cached_modifiers",
                    "Items", "items",
                    "Cosmetics", "cosmetics"
            ));

    this.slotName = carrier.get(SLOT_NAME_KEY);

    this.baseSize = carrier.get(BASE_SIZE_KEY);

    if(sync) {
        this.modifiers.clear();
        this.persistentModifiers.clear();
        this.modifiersByOperation.clear();

        if (carrier.has(MODIFIERS_KEY)) {
            var persistentTag = carrier.get(MODIFIERS_KEY);

            for (var compoundTag : persistentTag) {
                var modifier = AttributeModifier.CODEC.parse(NbtOps.INSTANCE, compoundTag).getOrThrow();

                if (modifier != null) this.addTransientModifier(modifier);
            }
        }
    } else {
        if (carrier.has(PERSISTENT_MODIFIERS_KEY)) {
            var persistentTag = carrier.get(PERSISTENT_MODIFIERS_KEY);

            for (var compoundTag : persistentTag) {
                var modifier = AttributeModifier.CODEC.parse(NbtOps.INSTANCE, compoundTag).getOrThrow();

                if (modifier != null) this.addPersistentModifier(modifier);
            }
        }

        if (carrier.has(CACHED_MODIFIERS_KEY)) {
            var cachedTag = carrier.get(CACHED_MODIFIERS_KEY);

            for (CompoundTag compoundTag : cachedTag) {
                var modifier = AttributeModifier.CODEC.parse(NbtOps.INSTANCE, compoundTag).getOrThrow();

                if (modifier != null) {
                    this.cachedModifiers.add(modifier);
                    this.addTransientModifier(modifier);
                }
            }

            this.update();
        }
    }

    if(carrier.has(CURRENT_SIZE_KEY)) {
        ctx = ctx.withAttributes(ContainerAttribute.CONTAINER.instance(new ContainerAttribute(this)));
        var currentSize = carrier.get(CURRENT_SIZE_KEY);

        var sentOptions = carrier.get(RENDER_OPTIONS_KEY);

        this.renderOptions = getWithSize(currentSize, sentOptions);

        if(this.accessories.getContainerSize() != currentSize) {
            this.accessories = new ExpandedContainer(this, currentSize, "accessories");
            this.cosmeticAccessories = new ExpandedContainer(this, currentSize, "cosmetic_accessories");
        }

        this.accessories.loadItemsFromList(carrier.get(ctx, ITEMS_KEY));
        this.cosmeticAccessories.loadItemsFromList(carrier.get(ctx, COSMETICS_KEY));
    } else {
        this.renderOptions = carrier.get(RENDER_OPTIONS_KEY);
    }
}

public void onRemovedFromLevel() {
    super.onRemovedFromLevel();

    var reason = this.getRemovalReason();

    if (reason == null || !reason.shouldDestroy())
        return;

    var level = this.level();
    var random = level.getRandom();
    var position = this.position();

    for (var target : level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(this.getExplosionRadius()),
            entity -> (this.getOwner() == null || !this.getOwner().getStringUUID().equals(entity.getStringUUID()))
                    && TargetingUtils.canHarm(this.getOwner(), entity, this.getStack(), "constellation"))) {
        target.invulnerableTime = 0;

        var damage = this.getDamage();

        if (TargetingUtils.hurtEnemy(target, this.level().damageSources().thrown(this.getOwner() instanceof LivingEntity owner ? owner : this, this), damage, this.getStack(), "constellation")) {
            var stun = this.getStun();

            TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.STUN, (int) (stun * 20), 0), this.getOwner(), this.getStack(), "constellation");

            if (stack.getItem() instanceof MidnightMantleItem relic && this.getOwner() instanceof LivingEntity owner) {
                relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("constellation").getStatisticData().getMetricData("star_damage").addValue(damage);

                relic.getRelicData(owner, stack).getLevelingData().addExperience("constellation", "star_damage", damage);

                if (stun > 0)
                    relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("constellation").getStatisticData().getMetricData("star_stun").addValue(stun);
            }
        }
    }

    var ringParticleCount = 100 + random.nextInt(50);

    for (var i = 0; i < ringParticleCount; i++) {
        var angle = 2 * Math.PI * i / ringParticleCount;
        var velocity = new Vec3(Math.cos(angle), 0.15D + random.nextDouble() * 0.1D, Math.sin(angle)).normalize().scale(0.05D + random.nextDouble() * 0.05D);

        var color = this.isFlawless() ? new Color(255, 215, 0) : new Color(50 + random.nextInt(150), 50 + random.nextInt(150), 255);

        level.addParticle(ParticleUtils.constructSimpleSpark(color, 0.75F + random.nextFloat() * 0.25F, 50 + random.nextInt(25), 0.95F), true, position.x, position.y, position.z, velocity.x, velocity.y, velocity.z);
    }

    var burstParticleCount = 250 + random.nextInt(100);

    for (var i = 0; i < burstParticleCount; i++) {
        var velocity = new Vec3(random.nextGaussian(), random.nextGaussian(), random.nextGaussian()).normalize().scale(0.1 + random.nextDouble() * 0.1);
        var color = this.isFlawless() ? new Color(255, 235, 100) : new Color(100 + random.nextInt(155), 100 + random.nextInt(155), 255);

        var spark = ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat(), 20 + random.nextInt(10), 0.9F);

        level.addParticle(spark, true, position.x, position.y, position.z, velocity.x, velocity.y, velocity.z);
    }

    var trailCount = 10;
    var pointCount = 25;
    var maxDistance = 2.5;

    for (var i = 0; i < trailCount; i++) {
        var direction = new Vec3(random.nextGaussian(), random.nextDouble(), random.nextGaussian()).normalize();

        for (var j = 1; j <= pointCount; j++) {
            var t = j / (double) pointCount;

            var spacedT = Math.pow(t, 1.5);

            var px = position.x + direction.x * spacedT * maxDistance;
            var py = position.y + direction.y * spacedT * maxDistance;
            var pz = position.z + direction.z * spacedT * maxDistance;

            var color = this.isFlawless() ? new Color(255, 200, 50) : new Color(80 + random.nextInt(100), 80 + random.nextInt(100), 255);
            var spark = ParticleUtils.constructSimpleSpark(color, (float) (1F * (1 - t) + 0.1F), 15 + random.nextInt(15), 0.5F);

            level.addParticle(spark, true, px, py, pz, direction.x * 0.02, direction.y * 0.02, direction.z * 0.02);
        }
    }
}

public void sling(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int chargeTime, ModifierEntry activeModifier) {
  Level level = entity.level();
  if (!level.isClientSide && entity instanceof Player player) {
    float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
    if (charge > 0) {
      Vec3 start = player.getEyePosition(1F);
      Vec3 look = player.getLookAngle();
      Vec3 direction = start.add(look.x * RANGE, look.y * RANGE, look.z * RANGE);
      AABB bb = player.getBoundingBox().expandTowards(look.x * RANGE, look.y * RANGE, look.z * RANGE).expandTowards(1, 1, 1);

      EntityHitResult hit = ProjectileUtil.getEntityHitResult(level, player, start, direction, bb, e -> e instanceof LivingEntity);
      if (hit != null) {
        LivingEntity target = (LivingEntity)hit.getEntity();
        if (this.target.matches(target)) {
          double targetDist = start.distanceToSqr(target.getEyePosition(1F));

          // cancel if there's a block in the way
          BlockHitResult mop = ModifiableItem.blockRayTrace(level, player, ClipContext.Fluid.NONE);
          if (mop.getType() != HitResult.Type.BLOCK || targetDist < mop.getBlockPos().distToCenterSqr(start)) {
            // melee tools also do damage as a treat
            boolean didBonk = false;
            if (damageMultiplier > 0 && ToolAttackUtil.isAttackable(entity, target) && EntityInteractionModifierHook.isMelee(tool)) {
              didBonk = true;
              ModDataNBT data = tool.getPersistentData();
              data.putBoolean(IS_BONKING, true);
              InteractionHand hand = player.getUsedItemHand();
              ToolAttackContext.Builder builder = ToolAttackContext.attacker(entity).target(target).hand(hand).cooldown(Math.min(1, charge));
              if (hand == InteractionHand.MAIN_HAND) {
                builder.applyAttributes();
              } else {
                builder.toolAttributes(tool);
              }
              ToolAttackUtil.performAttack(tool, builder.build());
              data.remove(IS_BONKING);
            }

            // send it flying
            float inaccuracy = ModifierUtil.getInaccuracy(tool, player) * 0.0075f;
            RandomSource random = player.getRandom();
            float multiplier = charge * this.forceMultiplier.compute(modifier);
            float force = SlingForceModifierHook.modifySlingForce(tool, entity, target, modifier, SlingModule.getPower(tool, player) * multiplier, multiplier);
            Vec3 angle = Vec3.ZERO;
            if (force > 0) {
              // skip the bonk if we lack force, but the attack is fine
              angle = SlingAngleModifierHook.modifySlingAngle(tool, entity, target, modifier, force, multiplier, new Vec3(
                (-look.x + random.nextGaussian() * inaccuracy),
                0,
                (-look.z + random.nextGaussian() * inaccuracy)
              ));
              target.knockback(force, angle.x, angle.z);
              if (target instanceof ServerPlayer playerMP) {
                TinkerNetwork.getInstance().sendVanillaPacket(new ClientboundSetEntityMotionPacket(target), playerMP);
              }
              didBonk = true;
            }

            // if we dealt damage or knockback, apply bonk effects
            if (didBonk) {
              // spawn the bonk particle
              ToolAttackUtil.spawnAttackParticle(TinkerTools.bonkAttackParticle.get(), player, 0.6d);

              // modifier callbacks
              SlingLaunchModifierHook.afterSlingLaunch(tool, entity, target, modifier, force, multiplier, angle);

              // cooldowns and stuff
              level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.BONK.getSound(), player.getSoundSource(), 1, 0.5f);
              player.causeFoodExhaustion(0.2F);
              player.getCooldowns().addCooldown(tool.getItem(), 3);
              ToolDamageUtil.damageAnimated(tool, 1, entity, entity.getUsedItemHand(), modifier.getId());
              return;
            }
          }
        }
      }
    }
    // play failure sound
    if (ModifierUtil.isActiveModifier(tool, modifier, activeModifier)) {
      level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.BONK.getSound(), player.getSoundSource(), 1, 1f);
    }
  }
}

public static void onLivingDamageOwner(LivingDamageEvent.Pre event) {
    var entity = event.getEntity();

    if (!(entity instanceof Player player))
        return;

    var original = event.getNewDamage();

    if (original <= 0F)
        return;

    var allActiveBelts = EntityUtils.findEquippedCurios(player, RelicsItems.HUNTING_BELT.get(), stack -> {
        var relic = (HuntingBeltItem) stack.getItem();

        return relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("pack").canPlayerUse(player);
    });
    var leaderBelts = allActiveBelts.stream()
            .filter(stack -> {
                var relic = (HuntingBeltItem) stack.getItem();

                return relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("pack").getRankModifierData("leader").isEnabled();
            })
            .toList();

    if (leaderBelts.isEmpty())
        return;

    var maxRadius = 0D;

    for (var stack : leaderBelts) {
        var relic = (HuntingBeltItem) stack.getItem();
        var radius = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("pack").getStatData("pet_radius").getValue();

        maxRadius = Math.max(maxRadius, radius);
    }

    var nearbyPets = player.level().getEntitiesOfClass(LivingEntity.class, player.getBoundingBox().inflate(maxRadius),
            target -> target instanceof OwnableEntity ownable && ownable.getOwner() != null
                    && ownable.getOwner().getUUID().equals(player.getUUID()));

    if (nearbyPets.isEmpty())
        return;

    var beltResisted = new ArrayList<Double>(leaderBelts.size());
    var totalResisted = 0D;

    for (var stack : leaderBelts) {
        var relic = (HuntingBeltItem) stack.getItem();
        var radius = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("pack").getStatData("pet_radius").getValue();
        var resistancePerPet = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("pack").getStatData("resistance_per_pet").getValue();
        var petsInRange = nearbyPets.stream().filter(pet -> pet.distanceToSqr(player) <= radius * radius).count();

        var reduction = Math.min(petsInRange, 5L) * resistancePerPet;
        var clamped = Math.clamp(reduction, 0D, 0.9D);
        var resisted = original * clamped;

        beltResisted.add(resisted);
        totalResisted += resisted;
    }

    if (totalResisted <= 0D)
        return;

    var maxResisted = original * 0.9D;
    var scale = totalResisted > maxResisted ? maxResisted / totalResisted : 1D;
    var appliedResisted = totalResisted * scale;

    event.setNewDamage((float) (original - appliedResisted));

    for (var i = 0; i < leaderBelts.size(); i++) {
        var resisted = beltResisted.get(i) * scale;

        if (resisted <= 0D)
            continue;

        var stack = leaderBelts.get(i);
        var relic = (HuntingBeltItem) stack.getItem();

        relic.getRelicData(player, stack).getLevelingData().addExperience("pack", "pet_resistance", resisted);
        relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("pack").getStatisticData().getMetricData("damage_resisted").addValue(resisted);
    }
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    if (!(slotContext.entity() instanceof LivingEntity entity))
        return;

    var level = entity.level();
    var random = level.getRandom();
    var movementSpeedAttributeId = getAttributeId(stack, Attributes.MOVEMENT_SPEED, slotContext);
    var stepHeightAttributeId = getAttributeId(stack, Attributes.STEP_HEIGHT, slotContext);

    var duration = this.getDuration(stack);

    if (entity.isSprinting() && entity.onGround() && !entity.isInLiquid() && !entity.isFallFlying()) {
        if (duration < this.getMaxDuration())
            this.addDuration(stack, 1);

        var movement = entity.getKnownMovement().multiply(1, 0, 1).length();

        if (movement > 0F) {
            this.getRelicData(entity, stack).getLevelingData().addExperience("skating", "skating", 1D / 20D);

            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("distance_traveled").addValue(movement);
        }
    } else if (duration > 0)
        this.addDuration(stack, -1);

    if (duration > 0) {
        EntityUtils.resetAttribute(entity, Attributes.MOVEMENT_SPEED, (float) (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatData("speed").getValue() / this.getMaxDuration() * this.getDuration(stack)), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, movementSpeedAttributeId);

        if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getRankModifierData("step_height").isEnabled())
            EntityUtils.resetAttribute(entity, Attributes.STEP_HEIGHT, (float) this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatData("step_height").getValue(), AttributeModifier.Operation.ADD_VALUE, stepHeightAttributeId);
        else
            EntityUtils.removeAttribute(entity, Attributes.STEP_HEIGHT, AttributeModifier.Operation.ADD_VALUE, stepHeightAttributeId);
    } else {
        EntityUtils.removeAttribute(entity, Attributes.MOVEMENT_SPEED, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, movementSpeedAttributeId);
        EntityUtils.removeAttribute(entity, Attributes.STEP_HEIGHT, AttributeModifier.Operation.ADD_VALUE, stepHeightAttributeId);
    }

    if (level.isClientSide() && entity instanceof LocalPlayer && this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getRankModifierData("sparkling").isEnabled()) {
        var motion = entity.getDeltaMovement();

        var xMotion = motion.x;
        var zMotion = motion.z;

        var speed = Mth.sqrt((float) (xMotion * xMotion + zMotion * zMotion));

        if (speed > 0.25F && entity.onGround()) {
            var yawRad = entity.getYRot() * (float) Math.PI / 180F;

            var inputX = entity.xxa;
            var inputZ = entity.zza;

            var inLen = Mth.sqrt(inputX * inputX + inputZ * inputZ);

            if (inLen > 0.01F) {
                inputX /= inLen;
                inputZ /= inLen;

                var directionX = inputZ * -Mth.sin(yawRad) + inputX * Mth.cos(yawRad);
                var directionZ = inputZ * Mth.cos(yawRad) + inputX * Mth.sin(yawRad);

                var dot = directionX * (xMotion / speed) + directionZ * (zMotion / speed);

                if (dot < 0.75F) {
                    var count = Mth.clamp((int) (speed * 10), 1, 20);

                    for (int i = 0; i < count; i++) {
                        var force = ((0.25F + random.nextFloat() * 0.25F) * speed) * 2F;

                        var offset = MathUtils.randomFloat(random) * 0.35F;

                        var deltaX = -directionX * force + (-directionZ) * offset;
                        var deltaY = 0.2F + random.nextFloat() * 0.2F * speed;
                        var deltaZ = -directionZ * force + directionX * offset;

                        NetworkHandler.sendToServer(new C2SCreateSpark(slotContext.identifier(), slotContext.index(), entity.position().toVector3f(), new Vector3f(deltaX, deltaY, deltaZ), entity.getStringUUID(),
                                (float) (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatData("damage").getValue() * speed), (float) (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("skating").getStatData("ignite").getValue() * speed), this.getRelicData(entity, stack).isVisuallyFlawless()));
                    }
                }
            }
        }
    }
}

public static void onEntityTick(EntityTickEvent.Post event) {
    if (!(event.getEntity() instanceof ServerPlayer player) || player.level().isClientSide())
        return;

    var usingSlot = -1;
    var currentDimension = player.level().dimension().location().toString();

    if (player.isUsingItem() && player.getUseItem().getItem() instanceof ClotOfTimeItem)
        usingSlot = player.getUsedItemHand() == InteractionHand.MAIN_HAND ? player.getInventory().selected : Inventory.SLOT_OFFHAND;

    PathPointData pointToAppend = null;

    for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
        var stack = player.getInventory().getItem(i);

        if (!(stack.getItem() instanceof ClotOfTimeItem relic))
            continue;

        var rememberedTicks = relic.getRememberedTicks(player, stack);

        if (rememberedTicks <= 0) {
            setPath(stack, List.of());
            setRewindCursor(stack, -1D);
            relic.setCooldown(stack, 0);

            continue;
        }

        var cursor = stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);
        var storedPath = stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of());
        var usingThisStack = i == usingSlot;
        var justStoppedRewind = false;

        if (usingThisStack) {
            var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

            if (ability.canPlayerUse(player) && ability.getRankModifierData("oblivion").isEnabled()) {
                for (var mob : player.level().getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(16D))) {
                    if (mob.getTarget() == player)
                        mob.setTarget(null);
                }
            }
        }

        if (usingThisStack && cursor >= 0D)
            relic.setCooldown(stack, Math.max(relic.getCooldown(stack), Math.max(1, player.getTicksUsingItem())));

        if (!usingThisStack && cursor >= 0D) {
            setRewindCursor(stack, -1D);

            if (!storedPath.isEmpty()) {
                var lastPoint = storedPath.getLast();
                var lastDimension = lastPoint.dimension().isBlank() ? currentDimension : lastPoint.dimension();

                if (!lastDimension.equals(currentDimension))
                    relic.setCooldown(stack, 0);
                else if (relic.getCooldown(stack) <= 0)
                    relic.setCooldown(stack, 1);
            } else if (relic.getCooldown(stack) <= 0)
                relic.setCooldown(stack, 1);

            justStoppedRewind = true;
        }

        if (usingThisStack)
            continue;

        if (!justStoppedRewind) {
            var cooldown = relic.getCooldown(stack);

            if (cooldown > 0)
                relic.setCooldown(stack, cooldown - 1);
        }

        if (!storedPath.isEmpty() && !shouldAppendPoint(player, storedPath.getLast(), currentDimension))
            continue;

        if (pointToAppend == null)
            pointToAppend = PathPointData.fromPlayer(player, currentDimension);

        setPath(stack, buildUpdatedPath(storedPath, rememberedTicks, pointToAppend));
    }
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    var stack = player.getItemInHand(hand);

    if (!this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").canPlayerUse(player))
        return InteractionResultHolder.pass(stack);

    if (player.isShiftKeyDown() && this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getRankModifierData("salvo").isEnabled()) {
        if (!level.isClientSide()) {
            var hit = EntityUtils.rayTraceEntity(player, entity -> entity instanceof LivingEntity living && !living.isDeadOrDying() && !EntityUtils.isAlliedTo(player, living) && !living.is(player), 64D);

            if (!(hit instanceof EntityHitResult entityHit) || !(entityHit.getEntity() instanceof LivingEntity target))
                return InteractionResultHolder.pass(stack);

            var stacks = this.getHealingStacks(stack);

            if (stacks.isEmpty())
                return InteractionResultHolder.pass(stack);

            var look = player.getLookAngle();
            var eye = player.getEyePosition();
            var right = look.cross(new Vec3(0, 1, 0));

            if (right.lengthSqr() < 1e-4)
                right = new Vec3(1, 0, 0);

            var up = look.cross(right).normalize();
            right = right.normalize();

            var count = stacks.size();
            var radius = 0.6D;
            var basePos = eye.subtract(look.scale(0.75D));

            for (int i = 0; i < count; i++) {
                var healingStack = stacks.get(i);
                var projectileDamage = Math.max(0F, healingStack.remainingHeal());

                var angle = (Math.PI * 2D / count) * i + player.getRandom().nextDouble() * (Math.PI / count);
                var offset = right.scale(Math.cos(angle) * radius).add(up.scale(Math.sin(angle) * radius));
                var spawnPos = basePos.add(offset);

                ServerScheduler.schedule(i * 2, () -> {
                    var projectile = new SelfSacrificeProjectileEntity(RelicsEntities.SELF_SACRIFICE_PROJECTILE.get(), level);

                    projectile.setOwner(player);
                    projectile.setPos(spawnPos);
                    projectile.setStack(stack);
                    projectile.setDeltaMovement(look.scale(0.25F).add(offset.normalize().scale(0.25F)).add(0, 0.05F, 0));
                    projectile.setDamage(projectileDamage);
                    projectile.setTarget(target);
                    projectile.setFlawless(this.getRelicData(player, stack).isVisuallyFlawless());

                    level.addFreshEntity(projectile);

                    this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getStatisticData().getMetricData("projectiles_created").addValue(1);
                });
            }

            this.setHealingStacks(stack, List.of());
        }

        return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
    }

    if (!level.isClientSide()) {
        if (player.getHealth() / player.getMaxHealth() < 0.33F || this.getHealingStacks(stack).size() >= this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getStatData("stacks").getValue())
            return InteractionResultHolder.pass(stack);

        var damage = this.getHealthCost(player);

        var remaining = Math.max(0F, player.getHealth() - 1F);

        damage = Math.min(damage, remaining);

        player.invulnerableTime = 0;
        player.hurt(level.damageSources().magic(), damage);

        this.getRelicData(player, stack).getLevelingData().addExperience("sacrifice", "self_inflicted", 1);

        this.addHealingStack(player, stack, this.buildHealingStack(player));
    }

    return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
}

public void tick() {
    super.tick();

    var level = getCommandSenderWorld();

    var particleCenter = this.position().add(this.getDeltaMovement().scale(-1F));

    for (int i = 0; i < 5; i++)
        level.addParticle(ParticleUtils.constructSimpleSpark(new Color(50 + random.nextInt(100), 0, 150 + random.nextInt(100)), 0.1F + random.nextFloat() * 0.15F, 5 + random.nextInt(10), 0.85F),
                particleCenter.x() + MathUtils.randomFloat(random) * 0.25F, particleCenter.y(), particleCenter.z() + MathUtils.randomFloat(random) * 0.25F, 0F, 0F, 0F);

    var currentTarget = getTarget();

    if (currentTarget != null && (this.position().distanceTo(currentTarget.position()) >= 16F || currentTarget.isDeadOrDying()))
        currentTarget = null;

    if (!level.isClientSide()) {
        LivingEntity potentialTarget = null;

        var candidateEntities = locateNearestTargets();

        candidateEntities.removeIf(entity -> blacklistedTargets.contains(entity.getStringUUID()));

        var targetEntities = candidateEntities.stream()
                .filter(entity -> {
                    var uuid = entity.getStringUUID();

                    return !bouncedTargets.contains(uuid) && !blacklistedTargets.contains(uuid);
                })
                .toList();

        if (!targetEntities.isEmpty())
            potentialTarget = targetEntities.getFirst();
        else if (!candidateEntities.isEmpty()) {
            bouncedTargets.clear();

            potentialTarget = candidateEntities.getFirst();
        }

        if (potentialTarget != null && (currentTarget == null || !currentTarget.getStringUUID().equals(potentialTarget.getStringUUID()))) {
            NetworkHandler.sendToClientsTrackingEntity(new S2CSyncEntityTargetPacket(this.getId(), potentialTarget.getId()), this);

            setTarget(potentialTarget);

            currentTarget = potentialTarget;
        }
    }

    if (currentTarget == null || currentTarget.isDeadOrDying() || this.tickCount >= 250 || getBounces() >= getMaxBounces()) {
        if (!level.isClientSide())
            this.discard();

        return;
    }

    if (this.getEyePosition().distanceTo(currentTarget.getEyePosition()) <= 1.5F) {
        currentTarget.invulnerableTime = 0;

        if (currentTarget.hurt(level.damageSources().thrown(this, getOwner()), getDamage())) {
            bouncedTargets.add(currentTarget.getStringUUID());
            lastTarget = currentTarget;

            setTarget(null);
            addBounces(1);

            if (random.nextDouble() <= getChance()) {
                var entity = new ShadowGlaiveEntity(RelicsEntities.SHADOW_GLAIVE.get(), level);

                entity.setMaxBounces(getMaxBounces());
                entity.setBounces(getBounces());
                entity.setPos(getEyePosition());
                entity.setDamage(getDamage());
                entity.setOwner(getOwner());

                level.addFreshEntity(entity);
            }
        } else {
            blacklistedTargets.add(currentTarget.getStringUUID());

            setTarget(null);
        }
    } else {
        this.setDeltaMovement(currentTarget.getEyePosition().subtract(this.getEyePosition()).normalize());
    }
}

private static void releaseCapturedProjectiles(Player player, ItemStack stack) {
    if (!(player.level() instanceof ServerLevel serverLevel) || !(stack.getItem() instanceof ShieldOfRetaliationItem relic))
        return;

    var captured = getCapturedProjectiles(stack);

    if (captured.isEmpty())
        return;

    var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");
    var look = player.getLookAngle().normalize();
    var right = getViewRight(player);
    var up = right.cross(look).normalize();
    var eyePosition = player.getEyePosition();
    var maxAimDistance = 64D;
    var aimEnd = eyePosition.add(look.scale(maxAimDistance));
    var blockHit = player.level().clip(new ClipContext(eyePosition, aimEnd, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player));
    var entityHit = EntityUtils.rayTraceEntity(player, entity -> entity instanceof LivingEntity living && living.isAlive() && !living.is(player), maxAimDistance);
    var aimPoint = aimEnd;

    if (blockHit.getType() != HitResult.Type.MISS)
        aimPoint = blockHit.getLocation();

    if (entityHit != null && eyePosition.distanceToSqr(entityHit.getLocation()) < eyePosition.distanceToSqr(aimPoint))
        aimPoint = entityHit.getLocation();

    var bonus = ability.getStatData("projectile_damage").getValue();
    var released = 0;

    for (var data : captured) {
        var entity = serverLevel.getEntity(UUID.fromString(data.uuid()));

        if (!(entity instanceof Projectile projectile) || projectile.isRemoved())
            continue;

        projectile.setOwner(player);
        projectile.setNoGravity(false);
        var position = player.getEyePosition()
                .add(look.scale(data.forwardOffset()))
                .add(right.scale(data.rightOffset()))
                .add(up.scale(data.upOffset()));
        var direction = aimPoint.subtract(position);

        if (direction.lengthSqr() < 0.0001D)
            direction = look;
        else
            direction = direction.normalize();

        var horizontal = Math.sqrt(direction.x * direction.x + direction.z * direction.z);
        var yRot = (float) Math.toDegrees(Math.atan2(direction.x, direction.z));
        var xRot = (float) Math.toDegrees(Math.atan2(direction.y, horizontal));

        projectile.setPos(position.x, position.y, position.z);
        projectile.setDeltaMovement(direction.scale(3.5F));
        projectile.setYRot(yRot);
        projectile.setXRot(xRot);
        projectile.yRotO = yRot;
        projectile.xRotO = xRot;
        projectile.getPersistentData().putDouble(REFLECTED_PROJECTILE_DAMAGE_TAG, bonus);

        released++;
    }

    if (released > 0)
        ability.getStatisticData().getMetricData("projectiles_reflected").addValue(released);

    if (released > 0) {
        player.level().playSound(null, player.blockPosition(), RelicsSounds.SHIELD_OF_RETALIATION_RELEASE.get(), SoundSource.PLAYERS, 1F, 0.95F + player.getRandom().nextFloat() * 0.1F);

        ShakeManager.addForPlayer(player, Shake.builder(player)
                .amplitude(0.15F + Math.min(released * 0.05F, 0.25F))
                .radius(Integer.MAX_VALUE)
                .duration(10)
                .speed(2.5F)
                .build());

        ChromaticAberrationManager.addForPlayer(player, ChromaticAberration.builder(player)
                .strength(0.025F + Math.min(released * 0.025F, 0.1F))
                .radius(Integer.MAX_VALUE)
                .fadeOutTime(2)
                .fadeInTime(2)
                .duration(10)
                .build());
    }

    setCapturedProjectiles(stack, List.of());
}

private void tickFogTrail(LivingEntity entity, ItemStack stack) {
    var ability = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("fog");

    if (!ability.canPlayerUse(entity) || ability.getMode().equals("disabled")) {
        this.setLastFogPos(stack, entity.position());

        return;
    }

    var current = entity.position();
    var last = this.getLastFogPos(stack);

    if (last == Vec3.ZERO || last.distanceToSqr(current) > 256D) {
        this.setLastFogPos(stack, current);

        return;
    }

    var distance = last.distanceTo(current);
    var fogRadius = Math.max(0.1D, ability.getStatData("radius").getValue());

    if (distance < fogRadius)
        return;

    var direction = current.subtract(last).normalize();
    var steps = Math.min(8, (int) Math.floor(distance / fogRadius));
    var gravity = entity.getAttributeValue(Attributes.GRAVITY);
    var maxGroundSearch = FOG_GROUND_SEARCH_STEP;

    if (gravity > 0.001D) {
        var upwardSpeed = entity.getAttributeValue(Attributes.JUMP_STRENGTH);

        while (upwardSpeed > 0D && maxGroundSearch < MAX_FOG_GROUND_SEARCH) {
            maxGroundSearch += upwardSpeed;
            upwardSpeed = (upwardSpeed - gravity) * 0.98D;
        }

        maxGroundSearch = Math.min(maxGroundSearch, MAX_FOG_GROUND_SEARCH);
    }

    var spawned = false;

    for (var i = 1; i <= steps; i++) {
        var pos = last.add(direction.scale(i * fogRadius));
        var y = pos.y;
        var groundFound = false;

        for (var j = 0D; j <= maxGroundSearch; j += FOG_GROUND_SEARCH_STEP) {
            var blockPos = BlockPos.containing(pos.x, pos.y + 0.2D - j, pos.z);
            var state = entity.level().getBlockState(blockPos);

            if (state.isAir())
                continue;

            var shape = state.getCollisionShape(entity.level(), blockPos);

            if (shape.isEmpty())
                continue;

            y = blockPos.getY() + shape.max(Direction.Axis.Y) + 0.03D;
            groundFound = true;

            break;
        }

        if (!groundFound)
            continue;

        var fog = new GhostlyFogEntity(RelicsEntities.GHOSTLY_FOG.get(), entity.level());

        fog.setOwner(entity);
        fog.setLifetime((int) Math.max(1D, ability.getStatData("duration").getValue() * 20D));
        fog.setRadius((float) fogRadius);
        fog.setAirDrain((int) Math.max(0D, MathUtils.round(ability.getStatData("air_loss").getValue(), 0)));
        fog.setSuffocationDamage((float) ability.getStatData("suffocation_damage").getValue());
        fog.setTremorTicks(ability.getRankModifierData("frostbite").isEnabled() ? (int) Math.max(1D, ability.getStatData("tremor").getValue() * 20D) : 0);
        fog.setStack(stack);
        fog.setPos(pos.x, y, pos.z);

        entity.level().addFreshEntity(fog);
        spawned = true;

        ability.getStatisticData().getMetricData("fog_clouds").addValue(1);
        this.getRelicData(entity, stack).getLevelingData().addExperience("fog", "fog_creation", 0.1D / steps);
    }

    this.setLastFogPos(stack, spawned ? last.add(direction.scale(steps * fogRadius)) : current);
}

public void tick() {
    super.tick();

    var level = this.getCommandSenderWorld();
    var currentTarget = this.getTarget();
    var distance = this.getDistance();

    if (currentTarget != null) {
        if (this.position().distanceTo(currentTarget.position()) >= distance || currentTarget.isDeadOrDying())
            currentTarget = null;
    } else if (!level.isClientSide()) {
        var selectedTarget = (LivingEntity) null;
        var nearbyTargets = this.locateNearestTargets();

        if (nearbyTargets.isEmpty()) {
            this.bouncedTargets.clear();

            nearbyTargets = this.locateNearestTargets();
        }

        if (!nearbyTargets.isEmpty()) {
            var totalWeight = 0.0;
            var weightList = new ArrayList<Double>();

            for (var targetCandidate : nearbyTargets) {
                var distanceToCandidate = this.position().distanceTo(targetCandidate.position());
                var candidateWeight = distance - distanceToCandidate;

                weightList.add(candidateWeight);

                totalWeight += candidateWeight;
            }

            var randomPoint = this.random.nextDouble() * totalWeight;
            var cumulativeWeight = 0.0;

            for (var i = 0; i < nearbyTargets.size(); i++) {
                cumulativeWeight += weightList.get(i);

                if (randomPoint <= cumulativeWeight) {
                    selectedTarget = nearbyTargets.get(i);

                    break;
                }
            }
        }

        if (selectedTarget != null) {
            this.setTarget(selectedTarget);

            currentTarget = selectedTarget;
        }
    }

    if (currentTarget == null || currentTarget.isDeadOrDying() || this.tickCount >= 250 || this.getBounces() <= 0) {
        if (!level.isClientSide())
            this.discard();

        return;
    }

    if (level.isClientSide())
        this.spawnArcParticles(level, currentTarget);

    if (this.getEyePosition().distanceTo(currentTarget.getEyePosition()) <= 1.5F) {
        currentTarget.invulnerableTime = 0;

        var damage = this.getDamage();
        var owner = this.getOwner();

        if (TargetingUtils.hurtEnemy(currentTarget, level.damageSources().thrown(this, owner), damage + (currentTarget.isInLiquid() || currentTarget.isInRain() ? damage * this.getDamageModifier() : 0F), this.getStack(), "shock")) {
            this.bouncedTargets.add(currentTarget.getStringUUID());
            this.lastTarget = currentTarget;

            this.setTarget(null);
            this.setBounces(this.getBounces() - 1);

            if (!level.isClientSide()) {
                if (stack.getItem() instanceof JellyfishNecklaceItem relic && owner instanceof LivingEntity entity) {
                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getStatisticData().getMetricData("arcs_bounces").addValue(1);

                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getStatisticData().getMetricData("arcs_damage").addValue(damage);

                    relic.getRelicData(entity, stack).getLevelingData().addExperience("shock", "arcs_bouncing", 1);
                }
            }
        } else {
            this.blacklistedTargets.add(currentTarget.getStringUUID());

            this.setTarget(null);
        }
    } else {
        var targetEye = currentTarget.getEyePosition();

        this.setPos(targetEye.x, targetEye.y - this.getBbHeight() * 0.5F, targetEye.z);
        this.setDeltaMovement(0D, 0D, 0D);
    }
}

public void tick() {
    var cachedMotion = this.getDeltaMovement();

    super.tick();

    this.noPhysics = this.tickCount <= ARC_DURATION;

    var level = this.level();
    var isTargeted = this.isTargeted();
    var target = this.getTarget();
    var position = this.position();
    var semiTarget = this.getOwner() == null ? target : this.getOwner().position();

    var maxDistance = ReflectiveNecklaceItem.ORB_SEARCH_RADIUS;
    var normal = position.subtract(semiTarget).normalize();
    var origin = semiTarget.add(normal.scale(maxDistance));

    if (this.tickCount >= (this.getLifetime() + (isTargeted ? 100 : 0))) {
        this.discard();

        return;
    }

    if (target.equals(Vec3.ZERO)) {
        if (this.tickCount < ARC_DURATION) {
            var damp = 1D - this.tickCount / (double) ARC_DURATION;

            this.setDeltaMovement(new Vec3(cachedMotion.x() * damp, 0.25D + this.random.nextFloat() * 0.25D, cachedMotion.z() * damp));
        } else
            this.setDeltaMovement(this.getDeltaMovement().scale(0.9F));
    } else if (!isTargeted) {
        this.setTargeted(true);

        this.setDeltaMovement(target.subtract(position).normalize().scale(1.5F));
    } else {
        if (!bounced)
            this.setDeltaMovement(cachedMotion);

        if (position.distanceTo(semiTarget) >= maxDistance)
            if (this.bounce(normal, origin))
                this.spawnBounceParticles = true;
    }

    if (level.isClientSide()) {
        var random = level.getRandom();

        level.addParticle(ParticleUtils.constructSimpleSpark(this.isFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(50 + random.nextInt(100), random.nextInt(100), 255), 0.1F + (random.nextFloat() * 0.15F), 15, 0.9F), this.getX(), this.getY() + this.getBbHeight() / 2F, this.getZ(), MathUtils.randomFloat(random) * 0.05F, MathUtils.randomFloat(random) * 0.05F, MathUtils.randomFloat(random) * 0.05F);
    }

    if (this.takeBounces && position.distanceTo(semiTarget) < maxDistance) {
        this.setBounces(this.getBounces() - 1);

        this.takeBounces = false;

        if (stack.getItem() instanceof ReflectiveNecklaceItem relic && this.getOwner() instanceof LivingEntity owner)
            relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_bounces").addValue(1);

        if (this.spawnBounceParticles) {
            var up = Math.abs(normal.y) < 0.99 ? new Vec3(0, 1, 0) : new Vec3(1, 0, 0);

            var axis1 = normal.cross(up).normalize();
            var axis2 = normal.cross(axis1).normalize();

            var segments = 6;
            var radius = 1D;

            var directions = new Vec3[segments];

            for (var i = 0; i < segments; i++) {
                var angle = 2 * Math.PI * i / segments;

                directions[i] = axis1.scale(Math.cos(angle) * radius).add(axis2.scale(Math.sin(angle) * radius));
            }

            var fillStep = 0.25;
            var shatterSpeed = 0.075F;

            for (var i = 0; i < segments; i++) {
                var edge1 = directions[i];
                var edge2 = directions[(i + 1) % segments];

                for (var t = 0.0; t <= 1.0; t += fillStep) {
                    for (var u = 0.0; u <= 1.0 - t; u += fillStep) {
                        var point = origin.add(edge1.scale(t)).add(edge2.scale(u));
                        var shardDir = point.subtract(origin).normalize();

                        var vx = (float) (shardDir.x * shatterSpeed);
                        var vy = (float) (shardDir.y * shatterSpeed);
                        var vz = (float) (shardDir.z * shatterSpeed);

                        this.level().addParticle(ParticleUtils.constructSimpleSpark(this.isFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(50 + random.nextInt(100), random.nextInt(100), 255), 0.35F, 40, 0.9F), true, point.x, point.y, point.z, vx, vy, vz);
                    }
                }
            }

            this.spawnBounceParticles = false;
        }
    }

    this.bounced = false;
}

public static void onLivingDamage(LivingDamageEvent.Pre event) {
    var entity = event.getEntity();
    var level = entity.level();
    var random = level.getRandom();

    var damage = event.getNewDamage();
    var health = entity.getHealth();
    var absorption = entity.getAbsorptionAmount();

    if (damage < health)
        return;

    var damageToThreshold = health - 0.1F;
    var remaining = damage - damageToThreshold;
    var diff = absorption - remaining;

    if (diff > 0)
        return;

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.LEAFY_MANTLE.get())) {
        var relic = (LeafyMantleItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").canPlayerUse(entity))
            continue;

        if (diff > 0)
            break;

        if (!level.isClientSide())
            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("damage_negated").addValue(Math.abs(diff));

        var radius = (int) Math.ceil(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("radius").getValue());
        var heal = (float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("heal").getValue();

        var center = entity.blockPosition();

        var positions = IntStream.rangeClosed(-radius, radius).boxed()
                .flatMap(dx -> IntStream.rangeClosed(-radius, radius)
                        .boxed()
                        .flatMap(dy -> IntStream.rangeClosed(-radius, radius)
                                .mapToObj(dz -> new BlockPos(center.getX() + dx, center.getY() + dy, center.getZ() + dz))))
                .filter(pos -> level.getBlockState(pos).is(BlockTags.LEAVES))
                .sorted(Comparator.comparingDouble(pos -> pos.distSqr(center)))
                .toList();

        var potential = positions.size() * heal;

        if (potential + diff < 0)
            continue;

        var blocks = 0;

        for (var pos : positions) {
            ServerScheduler.schedule(blocks + random.nextInt(10), () -> {
                var leaves = new LeavesBlockEntity(RelicsEntities.LEAVES_BLOCK.get(), level);

                var posVec = new Vec3(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D);

                var toPlayer = entity.position().subtract(posVec).normalize();
                var randomVec = new Vec3(MathUtils.randomFloat(random), MathUtils.randomFloat(random), MathUtils.randomFloat(random));
                var perpendicular = randomVec.subtract(toPlayer.scale(randomVec.dot(toPlayer))).normalize().scale(0.5D + random.nextDouble() * 0.5D);

                leaves.setParalysis((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("paralysis").getValue());
                leaves.setDeltaMovement(perpendicular.scale(0.5F + random.nextFloat()));
                leaves.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
                leaves.setPos(posVec.x(), posVec.y(), posVec.z());
                leaves.setBlockState(level.getBlockState(pos));
                leaves.setTarget(entity);
                leaves.setOwner(entity);
                leaves.setDamage(heal);
                leaves.setStack(stack);

                level.addFreshEntity(leaves);

                level.destroyBlock(pos, false);

                if (!level.isClientSide()) {
                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("leaves_consumed").addValue(1);

                    relic.getRelicData(entity, stack).getLevelingData().addExperience("revival", "consuming_leaves", 1);
                }
            });

            blocks++;

            diff += heal;

            if (diff >= 0)
                break;
        }

        if (blocks > 0) {
            event.setNewDamage(damageToThreshold);

            if (diff > 0) {
                var healAmount = diff;

                ServerScheduler.schedule(1, () -> {
                    entity.heal(healAmount);
                });
            }
        }
    }
}

public static void onLivingIncomingDamage(LivingIncomingDamageEvent event) {
    if (event.getEntity().level().isClientSide())
        return;

    if (event.getSource().getDirectEntity() instanceof Projectile projectile) {
        var bonus = projectile.getPersistentData().getDouble(REFLECTED_PROJECTILE_DAMAGE_TAG);

        if (bonus > 0D) {
            event.setAmount((float) (event.getAmount() * (1D + bonus)));
            projectile.getPersistentData().remove(REFLECTED_PROJECTILE_DAMAGE_TAG);
        }
    }

    if (!(event.getEntity() instanceof Player player))
        return;

    var inventory = player.getInventory();

    for (int i = 0; i < inventory.getContainerSize(); i++) {
        var stack = inventory.getItem(i);

        if (!(stack.getItem() instanceof ShieldOfRetaliationItem relic))
            continue;

        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");

        if (!ability.canPlayerUse(player) || getActiveTicks(stack) <= 0)
            continue;

        if (!isParryStack(player, stack))
            continue;

        if (!canBlockDamageFrom(player, event))
            continue;

        var incomingProjectile = event.getSource().getDirectEntity() instanceof Projectile projectile ? projectile : null;
        var sourcePosition = getDamageSourcePosition(event);

        var blockedDamage = event.getAmount();
        applyBlockRecoil(player, sourcePosition, incomingProjectile == null ? null : incomingProjectile.getDeltaMovement(), blockedDamage);

        if (incomingProjectile != null && ability.getRankModifierData("projectile").isEnabled()) {
            event.setCanceled(true);
            setSucceeded(stack, true);

            if (captureProjectile(player, stack, incomingProjectile))
                player.level().playSound(null, incomingProjectile.blockPosition(), RelicsSounds.SHIELD_OF_RETALIATION_PROJECTILE.get(), SoundSource.PLAYERS, 0.8F, 0.9F + player.getRandom().nextFloat() * 0.2F);

            extendShieldWindow(stack, relic, player);

            addBlockRewards(player, stack, blockedDamage, 0);

            return;
        }

        event.setCanceled(true);

        setSucceeded(stack, true);
        player.level().playSound(null, player.blockPosition(), RelicsSounds.SHIELD_OF_RETALIATION_DEFLECT.get(), SoundSource.PLAYERS, 0.9F, 0.9F + player.getRandom().nextFloat() * 0.2F);

        if (incomingProjectile != null)
            incomingProjectile.deflect(ProjectileDeflection.REVERSE, player, incomingProjectile.getOwner(), true);

        ShakeManager.addForPlayer(player, (sourcePosition != null ? Shake.builder(sourcePosition) : Shake.builder(player))
                .radius(Integer.MAX_VALUE)
                .amplitude(0.15F)
                .duration(10)
                .speed(2.5F)
                .build());

        if (!ability.getRankModifierData("guard").isEnabled()) {
            var cooldown = relic.getCooldownTicks(player, stack);

            if (cooldown > 0)
                player.getCooldowns().addCooldown(relic, cooldown);

            setActiveTicks(stack, 0);
            setActiveDuration(stack, 0);
            setReleaseLocked(stack, true);
            player.stopUsingItem();
        }

        addBlockRewards(player, stack, blockedDamage, stunNearbyTargets(player, stack));

        return;
    }

    for (int i = 0; i < inventory.getContainerSize(); i++) {
        var stack = inventory.getItem(i);

        if (!(stack.getItem() instanceof ShieldOfRetaliationItem relic) || !hasMissed(stack))
            continue;

        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");

        if (!ability.canPlayerUse(player))
            continue;

        setMissed(stack, false);

        var amount = event.getAmount();
        var multiplier = 1D + ability.getStatData("miss_damage").getValue();
        var modified = amount * multiplier;

        if (Float.isFinite(amount) && Double.isFinite(modified) && modified <= Float.MAX_VALUE)
            event.setAmount((float) modified);

        return;
    }
}

public void update(){
    var holder = AccessoriesHolderImpl.getHolder(this.capability());

    var hasChangeOccurred = !this.resizingUpdate;

    if(!update) return;

    this.update = false;

    if(this.capability.entity().level().isClientSide()) return;

    var slotType = this.slotType();

    if(this.baseSize == null) this.baseSize = 0;

    if (slotType != null && this.baseSize != slotType.amount()) {
        this.baseSize = slotType.amount();

        hasChangeOccurred = true;
    }

    double baseSize = this.baseSize;

    double size;

    if(ExtraSlotTypeProperties.getProperty(this.slotName, false).allowResizing()) {
        for (AttributeModifier modifier : this.getModifiersForOperation(AttributeModifier.Operation.ADD_VALUE)) {
            baseSize += modifier.amount();
        }

        size = baseSize;

        for (AttributeModifier modifier : this.getModifiersForOperation(AttributeModifier.Operation.ADD_MULTIPLIED_BASE)) {
            size += (this.baseSize * modifier.amount());
        }

        for (AttributeModifier modifier : this.getModifiersForOperation(AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL)) {
            size *= modifier.amount();
        }
    } else {
        size = baseSize;
    }

    //--

    var currentSize = (int) Math.round(size);

    if(currentSize != this.accessories.getContainerSize()) {
        hasChangeOccurred = true;

        var invalidAccessories = new ArrayList<Pair<Integer, ItemStack>>();

        var invalidStacks = new ArrayList<ItemStack>();

        this.containerListenerLock = true;

        var newAccessories = new ExpandedContainer(this, currentSize, "accessories");
        var newCosmetics = new ExpandedContainer(this, currentSize, "cosmetic_accessories");

        newAccessories.toggleFlagablity();
        newCosmetics.toggleFlagablity();

        for (int i = 0; i < this.accessories.getContainerSize(); i++) {
            if (i < newAccessories.getContainerSize()) {
                newAccessories.setItem(i, this.accessories.getItem(i));
                newCosmetics.setItem(i, this.cosmeticAccessories.getItem(i));
            } else {
                invalidAccessories.add(Pair.of(i, this.accessories.getItem(i)));
                invalidStacks.add(this.cosmeticAccessories.getItem(i));
            }
        }

        newAccessories.toggleFlagablity();
        newCosmetics.toggleFlagablity();

        this.containerListenerLock = false;

        newAccessories.copyPrev(this.accessories);
        newCosmetics.copyPrev(this.cosmeticAccessories);

        this.accessories = newAccessories;
        this.cosmeticAccessories = newCosmetics;

        this.renderOptions = getWithSize(currentSize, this.renderOptions);

        var livingEntity = this.capability.entity();

        //TODO: Confirm if this is needed
        for (var invalidAccessory : invalidAccessories) {
            var index = invalidAccessory.getFirst();

            var invalidStack = invalidAccessory.getSecond();

            if (invalidStack.isEmpty()) continue;

            var slotReference = SlotReference.of(livingEntity, this.slotName, index);

            AttributeUtils.removeTransientAttributeModifiers(livingEntity, AccessoryAttributeLogic.getAttributeModifiers(invalidStack, slotReference));

            var accessory = AccessoryRegistry.getAccessoryOrDefault(invalidStack);

            if (accessory != null) accessory.onUnequip(invalidStack, slotReference);

            invalidStacks.add(invalidStack);
        }

        holder.invalidStacks.addAll(invalidStacks);

        if (this.update) this.capability.updateContainers();
    }

    if(!hasChangeOccurred) {
        if (!trackedForUpdate) {
            var inv = holder.containersRequiringUpdates();

            inv.remove(this);
        } else {
            trackedForUpdate = false;
        }
    } else {
        var cache = holder.getLookupCache();

        if (cache != null) cache.clearContainerCache(this.slotName);
    }
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    super.curioTick(slotContext, stack);

    var entity = slotContext.entity();
    var level = entity.level();
    var gravityAttributeId = getGravityAttributeId(stack, slotContext);

    if (!this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gliding").canPlayerUse(entity) || this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gliding").getMode().equals("disabled")) {
        EntityUtils.removeAttribute(entity, Attributes.GRAVITY, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, gravityAttributeId);

        if (!level.isClientSide())
            this.setLastElectricityEntityId(stack, -1);

        return;
    }
    var random = level.getRandom();
    var isActive = this.isActive(stack);
    var isLanded = this.isLanded(stack);

    if (!level.isClientSide() && !isActive)
        this.setLastElectricityEntityId(stack, -1);

    var onGround = entity.onGround();

    var hasAttribute = EntityUtils.hasAttribute(entity, Attributes.GRAVITY, gravityAttributeId);

    if (level.isClientSide()) {
        if (entity instanceof LocalPlayer player) {
            if (player.input.jumping && !player.isFallFlying() && !player.getAbilities().flying && !player.isSwimming())
                NetworkHandler.sendToServer(new C2SSetActive(slotContext.identifier(), slotContext.index(), true));
            else if (isActive)
                NetworkHandler.sendToServer(new C2SSetActive(slotContext.identifier(), slotContext.index(), false));
        }
    }

    if (isLanded) {
        if (this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gliding").getRankModifierData("momentum").isEnabled() && !onGround && isActive)
            this.setLanded(stack, false);
    } else {
        if (onGround && !isActive)
            this.setLanded(stack, true);
    }

    var motion = entity.getDeltaMovement();
    var verticalMotion = (float) -motion.y;

    var minVy = 0.25F;
    var maxVy = 7.5F;
    var baseSlowFactor = Math.clamp((maxVy - verticalMotion) / (maxVy - minVy), 0F, 1F);

    var slowFactor = (float) Math.sqrt(baseSlowFactor);

    var maxReductionPerTick = 1F;

    var reduction = maxReductionPerTick * slowFactor;

    entity.fallDistance = Math.max(entity.fallDistance - reduction, 0.1F);

    if (isActive) {
        if (entity.tickCount % 20 == 0) {
            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gliding").getStatisticData().getMetricData("duration").addValue(1);

            this.getRelicData(entity, stack).getLevelingData().addExperience("gliding", "gliding", 1);
        }

        if (!hasAttribute)
            EntityUtils.applyAttribute(entity, Attributes.GRAVITY, (float) -Math.min(this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("gliding").getStatData("efficiency").getValue(), 0.9F), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, gravityAttributeId);

        var prevPosition = new Vec3(entity.xOld, entity.yOld, entity.zOld);
        var position = entity.position();
        var movementDelta = position.subtract(prevPosition);
        var horizontalDelta = new Vec3(movementDelta.x, 0, movementDelta.z);
        var horizontalDistance = horizontalDelta.length();
        var trailLagFactor = Math.clamp(0.3D + horizontalDistance * 0.18D, 0.3D, 0.85D);
        var laggedMovementDelta = movementDelta.scale(1D - trailLagFactor);
        var distance = laggedMovementDelta.length();
        var spawnStep = 0.075D;
        int spawnCount = (int) (distance / spawnStep) + 1;

        var yawRadians = Math.toRadians(entity.yBodyRot);
        var facingForward = new Vec3(-Math.sin(yawRadians), 0, Math.cos(yawRadians)).normalize();
        var forward = horizontalDelta.lengthSqr() > 1.0E-6D ? horizontalDelta.normalize() : facingForward;
        var right = forward.cross(new Vec3(0, 1, 0)).normalize();
        var left = right.scale(-1);
        var sideOffset = 0.4D;
        var backOffset = 0.2D;
        var speedBackOffset = backOffset + Math.min(horizontalDistance * 0.5D, 1.4D);
        var electricitySpawnPosition = prevPosition.add(laggedMovementDelta).subtract(forward.scale(speedBackOffset));

        if (level.isClientSide() && this.getRelicData(entity, stack).getAbilitiesData().getSynergyData("electricity").isUnlocked()
                && this.getRelicData(entity, stack).getAbilitiesData().getSynergyData("electricity").getMode().equals("enabled")) {
            var synergy = this.getRelicData(entity, stack).getAbilitiesData().getSynergyData("electricity");

            NetworkHandler.sendToServer(new C2SChainedElectricityPacket(
                    electricitySpawnPosition.x,
                    electricitySpawnPosition.y + entity.getBbHeight() / 2F - 0.15F,
                    electricitySpawnPosition.z,
                    (float) synergy.getStatData("damage").getValue(),
                    (int) synergy.getStatData("lifetime").getValue(),
                    this.getRelicData(entity, stack).isVisuallyFlawless(),
                    slotContext.identifier(),
                    slotContext.index()
            ));
        }

        for (var i = 0; i <= spawnCount; i++) {
            var t = spawnCount == 0 ? 0 : (double) i / spawnCount;
            var basePosition = prevPosition.add(laggedMovementDelta.scale(t)).subtract(forward.scale(speedBackOffset));
            var centerX = basePosition.x;
            var centerY = basePosition.y + entity.getBbHeight() / 2F - 0.15F;
            var centerZ = basePosition.z;

            for (var side : new Vec3[]{right, left}) {
                var x = centerX + side.x * sideOffset + (random.nextDouble() * 2 - 1) * 0.02;
                var y = centerY + (random.nextDouble() * 2 - 1) * 0.02;
                var z = centerZ + side.z * sideOffset + (random.nextDouble() * 2 - 1) * 0.02;

                var vx = (random.nextFloat() * 2 - 1) * 0.01F;
                var vy = (random.nextFloat() * 2 - 1) * 0.01F;
                var vz = (random.nextFloat() * 2 - 1) * 0.01F;

                level.addParticle(ParticleUtils.constructSimpleSpark(this.getRelicData(entity, stack).isVisuallyFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(random.nextInt(50), 75 + random.nextInt(100), 255), 0.1F + random.nextFloat() * 0.15F, 100 + random.nextInt(20), 0.995F), x, y, z, vx, vy, vz);
            }
        }
    } else if (hasAttribute)
        EntityUtils.removeAttribute(entity, Attributes.GRAVITY, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, gravityAttributeId);
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    super.curioTick(slotContext, stack);

    if (!(slotContext.entity() instanceof LivingEntity entity))
        return;

    var level = entity.level();
    var belowState = level.getBlockState(entity.getBlockPosBelowThatAffectsMyMovement());

    var ability = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch");
    var forcedFall = this.isForcedFall(stack);
    var onGround = entity.onGround();
    var glitchEnabled = this.isGlitchEnabled(entity, stack);

    if (!glitchEnabled) {
        this.setStandTicks(stack, 0);
        this.setForcedFall(stack, false);
        this.setPhaseTicks(stack, 0);
    } else {
        var stable = onGround && belowState.isAir() && !isMovingHorizontally(entity) && !entity.isShiftKeyDown();

        if (!forcedFall) {
            if (stable) {
                this.addStandTicks(stack, 1);

                if (this.getStandTicks(stack) >= (int) Math.max(1D, ability.getStatData("stability_time").getValue() * 20D)) {
                    this.setForcedFall(stack, true);
                    this.setForcedFallStartY(stack, entity.getY());
                    this.setStandTicks(stack, 0);

                    if (!level.isClientSide())
                        this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch").getStatisticData().getMetricData("forced_falls").addValue(1);
                }
            } else {
                this.setStandTicks(stack, 0);
            }
        }

        if (this.isForcedFall(stack) && onGround && !belowState.isAir() && entity.fallDistance <= 0F)
            this.setForcedFall(stack, false);
    }

    if (level.isClientSide())
        return;

    var gameTime = level.getGameTime();

    if (glitchEnabled && belowState.isAir() && this.canCollideWithAirLike(entity, stack) && this.getLastAirTick(stack) != gameTime) {
        this.setLastAirTick(stack, gameTime);

        ability.getStatisticData().getMetricData("solid_air_duration").addValue(1D / 20D);

        if (isMovingHorizontally(entity))
            this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "air_walking", 1D / 20D);
    }

    var illusion = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("illusion");

    if (illusion.canPlayerUse(entity) && illusion.getMode().equals("enabled")) {
        if (this.getIllusionCooldown(stack) > 0) {
            this.addIllusionCooldown(stack, -1);
        } else {
            var look = entity.getLookAngle().multiply(1D, 0D, 1D);
            var backward = look.lengthSqr() > 1.0E-6D ? look.normalize().scale(-0.95D) : Vec3.ZERO;
            var spawnPos = entity.position().add(backward);
            var copy = new GlitchyIllusionEntity(RelicsEntities.GLITCHY_ILLUSION.get(), level);

            copy.setOwner(entity);
            copy.setLifetime((int) Math.max(1D, illusion.getStatData("duration").getValue() * 20D));
            copy.setStunDuration((int) Math.max(1D, illusion.getStatData("stun").getValue() * 20D));
            copy.setStunRadius((float) Math.max(0D, illusion.getStatData("stun_radius").getValue()));
            copy.setFlawless(this.getRelicData(entity, stack).isVisuallyFlawless());
            copy.setStack(stack);
            copy.setPos(spawnPos.x(), spawnPos.y(), spawnPos.z());
            copy.setYRot(entity.getYRot());
            copy.setXRot(entity.getXRot());
            copy.setYHeadRot(entity.getYHeadRot());
            copy.setSnapshotXRot(entity.getXRot());
            copy.setPose(entity.getPose());

            if (level.getEntitiesOfClass(GlitchyIllusionEntity.class, copy.getBoundingBox().inflate(0.05D)).isEmpty()) {
                level.addFreshEntity(copy);

                this.setIllusionCooldown(stack, (int) Math.max(1D, illusion.getStatData("interval").getValue() * 20D));
                illusion.getStatisticData().getMetricData("illusions").addValue(1);
                this.getRelicData(entity, stack).getLevelingData().addExperience("illusion", "creation", 1);
            }
        }
    } else {
        this.setIllusionCooldown(stack, 0);
    }

    if (glitchEnabled && ability.getRankModifierData("phase").isEnabled()) {
        var eyesInsideBlock = areEyesInsideCollidingBlock(entity);

        if (!eyesInsideBlock) {
            this.setLastSafePosition(stack, entity.position());
            this.setPhaseTicks(stack, 0);
        } else {
            if (this.getLastPhaseTick(stack) != gameTime) {
                this.setLastPhaseTick(stack, gameTime);

                ability.getStatisticData().getMetricData("phase_duration").addValue(1D / 20D);
                this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "phasing", 1D / 20D);
            }

            if (!level.isClientSide())
                entity.addEffect(new MobEffectInstance(RelicsMobEffects.GLITCH, 5, 0, false, false));

            this.addPhaseTicks(stack, 1);

            var limit = Math.max(1, (int) Math.round(ability.getStatData("phase_time").getValue() * 20D));

            if (this.getPhaseTicks(stack) > limit) {
                var pos = this.getLastSafePosition(stack);

                if (entity instanceof ServerPlayer serverPlayer) {
                    serverPlayer.teleportTo(serverPlayer.serverLevel(), pos.x(), pos.y(), pos.z(), entity.getYRot(), entity.getXRot());
                    serverPlayer.setDeltaMovement(Vec3.ZERO);
                } else {
                    entity.teleportTo(pos.x(), pos.y(), pos.z());
                    entity.setDeltaMovement(Vec3.ZERO);
                }

                level.playSound(null, BlockPos.containing(pos), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1F, 1F);

                this.setPhaseTicks(stack, 0);
                ability.getStatisticData().getMetricData("phase_rollbacks").addValue(1);
            }
        }
    }
}

public void onEntityFall(BlockGetter getter, Entity entity, CallbackInfo ci) {
    if (!(entity instanceof LivingEntity livingEntity))
        return;

    var level = livingEntity.level();

    var waveIndex = 0;

    for (var stack : EntityUtils.findEquippedCurios(livingEntity, RelicsItems.SPRINGY_BOOT.get())) {
        if (!(stack.getItem() instanceof SpringyBootItem relic))
            continue;

        if (relic.isLeaped(stack)) {
            if (relic.getBounceCooldown(stack) <= 0) {
                if (!livingEntity.level().isClientSide()) {
                    var motion = livingEntity.getKnownMovement();
                    var speed = motion.y();

                    if (speed <= -0.75D) {
                        relic.addBounceCooldown(stack, 5);
                        relic.addLeaps(stack, 1);

                        speed = Math.abs(speed);

                        if (!livingEntity.isShiftKeyDown()) {
                            if (!level.isClientSide()) {
                                relic.getRelicData(livingEntity, stack).getLevelingData().addExperience("bounce", "bounce", 1);

                                relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("secondary_bounces").addValue(1);
                            }

                            level.playSound(null, livingEntity.blockPosition(), RelicsSounds.SPRING_BOING.get(), SoundSource.PLAYERS, (float) Math.clamp(0.5F + speed * 0.5F, 0.5F, 2F), (float) Math.max(0.1F, 2F - speed * 0.75F));

                            NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CBounceFromSurface(livingEntity.getId(), motion.multiply(1F, -1F, 1F).toVector3f()), livingEntity);

                            SpringyBootItem.spawnBounceFog(level, livingEntity, Math.max(1.1D, speed * 0.85D), 12 + Mth.ceil(speed * 2.5D));
                        } else {
                            if (relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getRankModifierData("shockwave").isEnabled()) {
                                var delayTicks = waveIndex * 20;

                                var center = livingEntity.blockPosition();
                                var verticalSpeed = Math.abs(livingEntity.getKnownMovement().y());
                                var radius = (int) Math.min(25, Math.round((1 + relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("radius").getValue()) * verticalSpeed));
                                var damage = (float) relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("damage").getValue();
                                var stun = (int) relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("stun").getValue() * 20;
                                var serverLevel = (ServerLevel) level;

                                relic.getRelicData(livingEntity, stack).getLevelingData().addExperience("bounce", "create_shockwave", radius);

                                ServerScheduler.schedule(delayTicks, () -> {
                                    relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("shockwaves_amount").addValue(1);

                                    var poses = new ArrayList<BlockPos>();

                                    for (var i = -radius; i <= radius; i++) {
                                        var r1 = (int) Mth.sqrt(radius * radius - i * i);

                                        for (var j = -r1; j <= r1; j++)
                                            poses.add(center.offset(i, 0, j));
                                    }

                                    for (var step = 0; step <= radius; step++) {
                                        var finalStep = step;

                                        ServerScheduler.schedule(finalStep, () -> {
                                            var height = 0.25F;

                                            poses.stream().filter(pos -> {
                                                var dx = pos.getX() - center.getX();
                                                var dz = pos.getZ() - center.getZ();

                                                var dist = Math.hypot(dx, dz);

                                                return dist >= finalStep && dist < finalStep + 1;
                                            }).forEach(entryPos -> {
                                                var centerY = center.getY();
                                                var maxOffset = 8;

                                                var groundY = WorldUtils.findSurfaceY(level, entryPos.getX(), entryPos.getZ(), centerY, maxOffset);

                                                var minAllowedY = Math.max(level.getMinBuildHeight(), centerY - maxOffset);
                                                var maxAllowedY = Math.min(level.getMaxBuildHeight(), centerY + maxOffset);

                                                if (groundY < minAllowedY || groundY > maxAllowedY)
                                                    return;

                                                var surfacePos = new BlockPos(entryPos.getX(), groundY, entryPos.getZ());
                                                var shockwave = new SpringyBootShockwaveBlockEntity(RelicsEntities.SHOCKWAVE_BLOCK.get(), level);

                                                shockwave.setDamage(damage);
                                                shockwave.setStun(stun);
                                                shockwave.setPos(surfacePos.getX() + 0.5F, surfacePos.getY(), surfacePos.getZ() + 0.5F);
                                                shockwave.setBlockState(level.getBlockState(surfacePos));
                                                shockwave.setDeltaMovement(0, height, 0);
                                                shockwave.setOwner(livingEntity);
                                                shockwave.setCenter(surfacePos);
                                                shockwave.setKnockback(1F);
                                                shockwave.setStack(stack);

                                                level.addFreshEntity(shockwave);

                                                var px = surfacePos.getX() + 0.15D + level.random.nextDouble() * 0.7D;
                                                var pz = surfacePos.getZ() + 0.15D + level.random.nextDouble() * 0.7D;

                                                var direction = new Vec3(px - (center.getX() + 0.5D), 0D, pz - (center.getZ() + 0.5D));

                                                if (direction.lengthSqr() < 0.001D)
                                                    direction = new Vec3(level.random.nextDouble() - 0.5D, 0D, level.random.nextDouble() - 0.5D);

                                                direction = direction.normalize();

                                                var particleSpeed = 0.008D + level.random.nextDouble() * 0.012D;
                                                var lifetime = 10 + level.random.nextInt(25);
                                                var fogPosition = new Vector3f((float) px, surfacePos.getY() + 0.04F, (float) pz);
                                                var fogMotion = new Vector3f((float) (direction.x * particleSpeed), height / 2F, (float) (direction.z * particleSpeed));

                                                NetworkHandler.sendToClientsTrackingChunk(new S2CSpawnParticle(new GhostlyFogParticle.Options(lifetime), fogPosition, fogMotion), serverLevel, new ChunkPos(surfacePos));
                                            });
                                        });
                                    }
                                });

                                waveIndex++;
                            }
                        }
                    }
                }
            }

            ci.cancel();
        }
    }
}

static void livingHurt(LivingHurtEvent event) {
  LivingEntity entity = event.getEntity();

  // determine if there is any modifiable armor, if not nothing to do
  DamageSource source = event.getSource();
  EquipmentContext context = new EquipmentContext(entity);
  int vanillaModifier = 0;
  float modifierValue = 0;
  float originalDamage = event.getAmount();

  Entity attacker = source.getEntity();
  if (attacker instanceof LivingEntity living) {
    // boost damage based on monster's melee weapon
    if (Config.COMMON.allowMonsterMeleeModifiers.get() && source.is(TinkerTags.DamageTypes.MODIFIER_WHITELIST) && !living.getType().is(TinkerTags.EntityTypes.DAMAGE_MODIFIER_BLACKLIST)) {
      ItemStack weapon = living.getMainHandItem();
      if (!weapon.isEmpty()) {
          if (weapon.is(TinkerTags.Items.MELEE_WEAPON)) {
            IToolStackView tool = ToolStack.from(weapon);
            // already know the player is null
            ToolAttackContext meleeContext = ToolAttackContext.attacker(living, null).target(entity).applyAttributes().build();
            float baseDamage = originalDamage;
            for (ModifierEntry entry : tool.getModifiers()) {
                originalDamage = entry.getHook(ModifierHooks.MONSTER_MELEE_DAMAGE).getMeleeDamage(tool, entry, meleeContext, baseDamage, originalDamage);
            }
          }
      } else {// unarmed
        // not consider adding non-chest armor to the unarmed tag
        ItemStack unarmed = living.getItemBySlot(EquipmentSlot.CHEST);
        if (!unarmed.isEmpty() && unarmed.is(TinkerTags.Items.UNARMED)) {
          // get the melee damage attribute
          float damageAttr = (float) entity.getAttributeValue(Attributes.ATTACK_DAMAGE);
          IToolStackView tool = ToolStack.from(unarmed);
          // already know the player is null
          ToolAttackContext meleeContext = ToolAttackContext.attacker(living, null).target(entity).toolAttributes(tool).addBaseDamage(originalDamage - damageAttr).slot(EquipmentSlot.CHEST, InteractionHand.MAIN_HAND).build();
          originalDamage = meleeContext.getBaseDamage();
          float baseDamage = originalDamage;
          for (ModifierEntry entry : tool.getModifiers()) {
            originalDamage = entry.getHook(ModifierHooks.MONSTER_MELEE_DAMAGE).getMeleeDamage(tool, entry, meleeContext, baseDamage, originalDamage);
          }
        }
      }
    }

    // run shulking global damage "boost", its a bit hardcoded Java wise to make it softcoded in JSON
    if (attacker.isCrouching()) {
      double crouchMultiplier = living.getAttributeValue(TinkerAttributes.CROUCH_DAMAGE_MULTIPLIER.get());
      crouchMultiplier += ArmorStatModule.getStat(attacker, TinkerDataKeys.CROUCH_DAMAGE);
      if (crouchMultiplier != 0) {
        originalDamage *= crouchMultiplier;
      }
    }
  }

  // conducting - boosts damage from fire
  if (source.is(TinkerTags.DamageTypes.FIRE_PROTECTION)) {
    int level = TinkerEffect.getLevel(entity, TinkerEffects.conductive);
    if (level > 0) {
      originalDamage *= Math.pow(2, level);
    }
  }
  // venom - boosts damage from magic
  if (source.is(TinkerTags.DamageTypes.MAGIC_PROTECTION)) {
    int level = TinkerEffect.getLevel(entity, TinkerEffects.venom);
    if (level > 0) {
      originalDamage *= Math.pow(2, level);
    }
  }

  // ensure any changes made so far apply, though we may change it again
  event.setAmount(originalDamage);

  // for our own armor, we have boosts from modifiers to consider
  if (context.hasModifiableArmor()) {
    // first, allow modifiers to change the damage being dealt and respond to it happening
    originalDamage = ModifyDamageModifierHook.modifyDamageTaken(ModifierHooks.MODIFY_HURT, context, source, originalDamage, OnAttackedModifierHook.isDirectDamage(source));
    event.setAmount(originalDamage);
    if (originalDamage <= 0) {
      event.setCanceled(true);
      return;
    }

    // remaining logic is reducing damage like vanilla protection
    // fetch vanilla enchant level, assuming its not bypassed in vanilla
    if (DamageSourcePredicate.CAN_PROTECT.matches(source)) {
      modifierValue = vanillaModifier = EnchantmentHelper.getDamageProtection(entity.getArmorSlots(), source);
    }

    // next, determine how much tinkers armor wants to change it
    // note that armor modifiers can choose to block "absolute damage" if they wish, currently just starving damage I think
    for (EquipmentEntry entry : context.iterateTools()) {
      ModifierEntry modifier = entry.modifier();
      modifierValue = modifier.getHook(ModifierHooks.PROTECTION).getProtectionModifier(entry.tool(), modifier, context, entry.slot(), source, modifierValue);
    }

    // give slimes a 4x armor boost
    if (entity.getType().is(TinkerTags.EntityTypes.SMALL_ARMOR)) {
      modifierValue *= 4;
    }
  } else if (DamageSourcePredicate.CAN_PROTECT.matches(source) && entity.getType().is(TinkerTags.EntityTypes.SMALL_ARMOR)) {
    vanillaModifier = EnchantmentHelper.getDamageProtection(entity.getArmorSlots(), source);
    modifierValue = vanillaModifier * 4;
  }

  // if we changed anything, run our logic. Changing the cap has 2 problematic cases where same value will work:
  // * increased cap and vanilla is over the vanilla cap
  // * decreased cap and vanilla is now under the cap
  // that said, don't actually care about cap unless we have some protection, can use vanilla to simplify logic
  float cap = 20f;
  if (modifierValue > 0) {
    cap = (float) ProtectionModifierHook.getProtectionCap(entity, context.getTinkerData());
  }
  if (vanillaModifier != modifierValue || (cap > 20 && vanillaModifier > 20) || (cap < 20 && vanillaModifier > cap)) {
    // fetch armor and toughness if blockable, passing in 0 to the logic will skip the armor calculations
    float armor = 0, toughness = 0;
    if (!source.is(DamageTypeTags.BYPASSES_ARMOR)) {
      armor = entity.getArmorValue();
      toughness = (float)entity.getAttributeValue(Attributes.ARMOR_TOUGHNESS);
    }

    // set the final dealt damage
    float finalDamage = ArmorUtil.getDamageForEvent(originalDamage, armor, toughness, vanillaModifier, modifierValue, cap);
    event.setAmount(finalDamage);

    // armor is damaged less as a result of our math, so damage the armor based on the difference if there is one
    if (!source.is(DamageTypeTags.BYPASSES_ARMOR)) {
      int damageMissed = getArmorDamage(originalDamage) - getArmorDamage(finalDamage);
      // TODO: is this check sufficient for whether the armor should be damaged? I partly wonder if I need to use reflection to call damageArmor
      if (damageMissed > 0 && entity instanceof Player) {
        for (EquipmentSlot slotType : ModifiableArmorMaterial.ARMOR_SLOTS) {
          // for our own armor, saves effort to damage directly with our utility
          IToolStackView tool = context.getToolInSlot(slotType);
          if (tool != null && (!source.is(DamageTypeTags.IS_FIRE) || !tool.getItem().isFireResistant())) {
            // mark this as protection (any valid modifier really would do) so tanned can reduce it to not count it as separate damage
            ToolDamageUtil.damageAnimated(tool, damageMissed, entity, slotType, ARMOR_DAMAGE);
          } else {
            // if not our armor, damage using vanilla like logic
            ItemStack armorStack = entity.getItemBySlot(slotType);
            if (!armorStack.isEmpty() && (!source.is(DamageTypeTags.IS_FIRE) || !armorStack.getItem().isFireResistant()) && armorStack.getItem() instanceof ArmorItem) {
              armorStack.hurtAndBreak(damageMissed, entity, e -> e.broadcastBreakEvent(slotType));
            }
          }
        }
      }
    }
  }
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    var entity = slotContext.entity();
    var level = entity.level();

    var activeRegenerationStacks = RelicStackingUtils.findActiveStacks(entity, RelicsItems.JELLYFISH_NECKLACE.get(),
            equippedStack -> equippedStack.getItem() == this
                    && this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("regeneration").canPlayerUse(entity));

    if (RelicStackingUtils.isControllerStack(stack, activeRegenerationStacks)) {
        var multiplier = (float) RelicStackingUtils.sumValue(entity, stack, "regeneration", "max_health");
        var retentionUnlocked = activeRegenerationStacks.stream().anyMatch(
                equippedStack -> this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("regeneration").getRankModifierData("retention").isEnabled());

        if (entity.isInLiquid() || entity.isInRain()) {
            var boostedMaxHealth = entity.getMaxHealth() * multiplier;

            EntityUtils.resetAttribute(entity, Attributes.MAX_HEALTH, multiplier, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, REGEN_MAX_HEALTH_ATTRIBUTE);
            EntityUtils.removeAttribute(entity, Attributes.MAX_ABSORPTION, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);

            entity.setHealth(entity.getHealth() + Math.min(entity.getAbsorptionAmount(), boostedMaxHealth));
        } else {
            EntityUtils.removeAttribute(entity, Attributes.MAX_HEALTH, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, REGEN_MAX_HEALTH_ATTRIBUTE);

            if (retentionUnlocked && !EntityUtils.hasAttribute(entity, Attributes.MAX_HEALTH, REGEN_MAX_HEALTH_ATTRIBUTE)
                    && !EntityUtils.hasAttribute(entity, Attributes.MAX_ABSORPTION, REGEN_RETENTION_ATTRIBUTE)) {
                var baseMaxHealth = entity.getMaxHealth();
                var currentHealth = entity.getHealth();
                var extraHealth = Math.max(0F, currentHealth - baseMaxHealth);

                entity.setHealth(Math.min(currentHealth, baseMaxHealth));

                EntityUtils.resetAttribute(entity, Attributes.MAX_ABSORPTION, extraHealth, AttributeModifier.Operation.ADD_VALUE, REGEN_RETENTION_ATTRIBUTE);
                entity.setAbsorptionAmount(extraHealth);
            }
        }
    }

    var activeShockStacks = RelicStackingUtils.findActiveStacks(entity, RelicsItems.JELLYFISH_NECKLACE.get(),
            equippedStack -> equippedStack.getItem() == this && this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("shock").canPlayerUse(entity)
                    && !this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("shock").getMode().equals("disabled"));

    if (RelicStackingUtils.isControllerStack(stack, activeShockStacks)) {
        var cooldown = this.getCooldown(stack);
        var maxRings = (int) Math.ceil(RelicStackingUtils.sumValue(entity, stack, "shock", "rings",
                abilityData -> !abilityData.getMode().equals("disabled")));
        var rings = Math.min(this.getRings(stack), maxRings);
        if (rings != this.getRings(stack))
            this.setRings(stack, rings);

        var cooldownTicks = (int) Math.round(RelicStackingUtils.bestValue(entity, stack, "shock", "cooldown", abilityData -> !abilityData.getMode().equals("disabled")) * 20D);
        var radius = RelicStackingUtils.bestValue(entity, stack, "shock", "radius", abilityData -> !abilityData.getMode().equals("disabled"));
        var knockback = RelicStackingUtils.bestValue(entity, stack, "shock", "knockback", abilityData -> !abilityData.getMode().equals("disabled"));
        var paralysis = RelicStackingUtils.bestValue(entity, stack, "shock", "paralysis", abilityData -> !abilityData.getMode().equals("disabled"));
        var distance = RelicStackingUtils.bestValue(entity, stack, "shock", "distance", abilityData -> !abilityData.getMode().equals("disabled"));
        var bounces = (int) Math.round(RelicStackingUtils.bestValue(entity, stack, "shock", "bounces", abilityData -> !abilityData.getMode().equals("disabled")));
        var damage = RelicStackingUtils.bestValue(entity, stack, "shock", "damage", abilityData -> !abilityData.getMode().equals("disabled"));
        var conductorUnlocked = activeShockStacks.stream().anyMatch(equippedStack -> this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("shock").getRankModifierData("conductor").isEnabled());
        var chargeUnlocked = activeShockStacks.stream().anyMatch(equippedStack -> this.getRelicData(entity, equippedStack).getAbilitiesData().getAbilityData("shock").getRankModifierData("charge").isEnabled());
        var damageModifier = conductorUnlocked ? RelicStackingUtils.maxValue(entity, stack, "shock", "damage_modifier", abilityData -> !abilityData.getMode().equals("disabled")) : 0D;
        var chargeDurationTicks = (int) Math.round(RelicStackingUtils.bestValue(entity, stack, "shock", "duration", abilityData -> !abilityData.getMode().equals("disabled")) * 20D);
        var flawless = activeShockStacks.stream().anyMatch(equippedStack -> this.getRelicData(entity, equippedStack).isVisuallyFlawless());

        if (rings < maxRings) {
            if (cooldown > 0)
                this.addCooldown(stack, -1);
            else {
                this.addRings(stack, 1);
                this.setCooldown(stack, cooldownTicks);

                if (!level.isClientSide()) {
                    this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getStatisticData().getMetricData("rings_accumulated").addValue(1);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("shock", "rings_accumulating", 1);
                }
            }
        }

        var affectedEntities = this.getAffectedEntities(stack);

        Predicate<LivingEntity> predicate = entry -> {
            var uuid = entry.getStringUUID();

            return !uuid.equals(entity.getStringUUID()) && !affectedEntities.contains(uuid) && TargetingUtils.canHarm(entity, entry, stack, "shock");
        };

        var collidedEntities = level.getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(0.5F), predicate);

        if (rings > 0 && !collidedEntities.isEmpty()) {
            for (var target : level.getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(0.5F).inflate(radius), predicate)) {
                var diff = target.position().add(0, target.getBbHeight() / 2D, 0).subtract(entity.position());
                var totalKnockback = 0.5D * knockback;

                if (!level.isClientSide()) {
                    TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.PARALYSIS, (int) (paralysis * 20), 0, false, true), entity, stack, "shock");

                    this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getStatisticData().getMetricData("rings_paralysis").addValue(paralysis);
                }

                target.setDeltaMovement(diff.normalize().multiply(totalKnockback, totalKnockback / 2F, totalKnockback));

                var spark = new ElectricSparkEntity(RelicsEntities.ELECTRIC_SPARK.get(), level);

                spark.setDamageModifier(conductorUnlocked ? (float) damageModifier : 0F);
                spark.setDistance((float) distance);
                spark.setBounces(bounces);
                spark.setDamage((float) damage);
                spark.setPos(entity.position().add(0F, entity.getBbHeight() / 2F, 0D));
                spark.setFlawless(flawless);
                spark.setTarget(target);
                spark.setOwner(entity);
                spark.setStack(stack);

                level.addFreshEntity(spark);

                this.addAffectedEntities(stack, target.getStringUUID());

                if (!level.isClientSide())
                    this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("shock").getStatisticData().getMetricData("arcs_spawned").addValue(1);
            }

            this.addRings(stack, -1);

            if (chargeUnlocked)
                this.setDuration(stack, chargeDurationTicks);
        }

        if (!affectedEntities.isEmpty())
            this.removeAffectedEntities(stack, affectedEntities.stream()
                    .filter(Predicate.not(collidedEntities.stream()
                            .map(Entity::getStringUUID)
                            .collect(Collectors.toSet())::contains))
                    .toArray(String[]::new));

        if (chargeUnlocked) {
            var duration = this.getDuration(stack);

            if (duration > 0)
                this.addDuration(stack, -1);
            else
                this.setDamagedEntities(stack, new ArrayList<>());
        }

        var controllerCooldown = this.getCooldown(stack);
        var controllerRings = this.getRings(stack);
        var controllerDuration = this.getDuration(stack);
        var controllerDamagedEntities = this.getDamagedEntities(stack);
        var controllerAffectedEntities = this.getAffectedEntities(stack);

        for (var equippedStack : activeShockStacks) {
            if (equippedStack == stack)
                continue;

            this.setCooldown(equippedStack, controllerCooldown);
            this.setRings(equippedStack, controllerRings);
            this.setDuration(equippedStack, controllerDuration);
            this.setDamagedEntities(equippedStack, new ArrayList<>(controllerDamagedEntities));
            this.setAffectedEntities(equippedStack, new ArrayList<>(controllerAffectedEntities));
        }
    }
}

protected void onHitBlock(BlockHitResult result) {
    var center = result.getBlockPos();
    var level = this.level();

    ShakeManager.add(level, Shake.builder(this)
            .amplitude(0.075F)
            .duration(5)
            .radius(16)
            .build());

    if (level.isClientSide())
        return;

    var serverLevel = (ServerLevel) level;
    var position = this.position();
    var radius = Math.max(this.getRadius() - this.bounces, 1);

    var ringParticleCount = 250 + random.nextInt(250);

    for (var i = 0; i < ringParticleCount; i++) {
        var angle = 2 * Math.PI * i / ringParticleCount;
        var velocity = new Vec3(Math.cos(angle), 0.15D + random.nextDouble() * 0.1D, Math.sin(angle)).normalize().scale(0.5 + random.nextDouble() * 0.25D);

        var color = this.isFlawless() ? new Color(255, 215, 0) : new Color(50 + random.nextInt(150), 50 + random.nextInt(150), 255);

        NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.75F + random.nextFloat() * 0.25F, 5 + random.nextInt(5), 0.8F), position.toVector3f(), velocity.toVector3f()), this);
    }

    var burstParticleCount = 250 + random.nextInt(100);

    for (var i = 0; i < burstParticleCount; i++) {
        var velocity = new Vec3(random.nextGaussian(), random.nextGaussian(), random.nextGaussian()).normalize().scale(0.1 + random.nextDouble() * 0.25);
        var color = this.isFlawless() ? new Color(255, 235, 100) : new Color(100 + random.nextInt(155), 100 + random.nextInt(155), 255);

        NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat(), 10 + random.nextInt(10), 0.9F), position.toVector3f(), velocity.toVector3f()), this);
    }

    var trailCount = 10;
    var pointCount = 75;
    var maxDistance = 5;

    for (var i = 0; i < trailCount; i++) {
        var direction = new Vec3(random.nextGaussian(), random.nextDouble(), random.nextGaussian()).normalize();

        for (var j = 1; j <= pointCount; j++) {
            var t = j / (double) pointCount;

            var spacedT = Math.pow(t, 1.5);

            var px = position.x + direction.x * spacedT * maxDistance;
            var py = position.y + direction.y * spacedT * maxDistance;
            var pz = position.z + direction.z * spacedT * maxDistance;

            var color = this.isFlawless() ? new Color(255, 200, 50) : new Color(80 + random.nextInt(100), 80 + random.nextInt(100), 255);
            var spark = ParticleUtils.constructSimpleSpark(color, (float) (1F * (1 - t) + 0.1F), 15 + random.nextInt(15), 0.5F);

            NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(spark, new Vector3f((float) px, (float) py, (float) pz), new Vector3f((float) (direction.x * 0.02F), (float) (direction.y * 0.02F), (float) (direction.z * 0.02F))), this);
        }
    }

    if (this.noPhysics || !level.getBlockState(center).blocksMotion())
        return;

    var poses = new ArrayList<BlockPos>();

    for (var i = -radius; i <= radius; i++) {
        var r1 = (int) Mth.sqrt(radius * radius - i * i);

        for (var j = -r1; j <= r1; j++)
            poses.add(center.offset(i, 0, j));
    }

    for (var step = 0; step <= radius; step++) {
        int finalStep = step;

        ServerScheduler.schedule(finalStep, () -> {
            var height = 0.25F;

            poses.stream().filter(pos -> {
                var dx = pos.getX() - center.getX();
                var dz = pos.getZ() - center.getZ();
                var dist = Math.hypot(dx, dz);

                return dist >= finalStep && dist < finalStep + 1;
            }).forEach(entryPos -> {
                var centerY = center.getY();

                int maxOffset = 8;

                var groundY = WorldUtils.findSurfaceY(level, entryPos.getX(), entryPos.getZ(), centerY, maxOffset);

                var minAllowedY = Math.max(level.getMinBuildHeight(), centerY - maxOffset);
                var maxAllowedY = Math.min(level.getMaxBuildHeight(), centerY + maxOffset);

                if (groundY < minAllowedY || groundY > maxAllowedY)
                    return;

                var surfacePos = new BlockPos(entryPos.getX(), groundY, entryPos.getZ());

                var shockwave = new FallingStarShockwaveBlockEntity(RelicsEntities.SHOCKWAVE_BLOCK.get(), level);

                shockwave.setPos(surfacePos.getX() + 0.5F, surfacePos.getY(), surfacePos.getZ() + 0.5F);
                shockwave.setBlockState(level.getBlockState(surfacePos));
                shockwave.setDeltaMovement(0, height, 0);
                shockwave.setDamage(this.getDamage());
                shockwave.setOwner(this.getOwner());
                shockwave.setStack(this.getStack());
                shockwave.setStun(this.getStun());
                shockwave.setCenter(surfacePos);
                shockwave.setKnockback(0.75F);

                level.addFreshEntity(shockwave);

                var px = surfacePos.getX() + 0.15D + random.nextDouble() * 0.7D;
                var pz = surfacePos.getZ() + 0.15D + random.nextDouble() * 0.7D;

                var direction = new Vec3(px - (center.getX() + 0.5D), 0D, pz - (center.getZ() + 0.5D));

                if (direction.lengthSqr() < 0.001D)
                    direction = new Vec3(random.nextDouble() - 0.5D, 0D, random.nextDouble() - 0.5D);

                direction = direction.normalize();

                var speed = 0.008D + random.nextDouble() * 0.012D;
                var lifetime = 10 + random.nextInt(25);
                var fogPosition = new Vector3f((float) px, surfacePos.getY() + 0.04F, (float) pz);
                var fogMotion = new Vector3f((float) (direction.x * speed), height / 2F, (float) (direction.z * speed));

                NetworkHandler.sendToClientsTrackingChunk(new S2CSpawnParticle(new GhostlyFogParticle.Options(lifetime), fogPosition, fogMotion), serverLevel, new ChunkPos(surfacePos));
            });
        });
    }

    level.playSound(null, this.blockPosition(), RelicsSounds.FALLING_STAR_FALL.get(), SoundSource.MASTER, 0.5F, 1F + random.nextFloat() + this.bounces * 0.2F);

    var bounceChance = this.getBounceChance();

    if (bounceChance > 0F) {
        if (this.bounced)
            return;

        if (random.nextFloat() <= bounceChance) {
            var normal = Vec3.atLowerCornerOf(result.getDirection().getNormal()).normalize();

            var motion = this.getDeltaMovement();
            var reflected = motion.subtract(normal.scale(2 * motion.dot(normal))).normalize().scale(0.5F + this.getRadius() * 0.075F);

            this.setDeltaMovement(reflected);

            this.bounced = true;
            this.bounces++;

            var stack = this.getStack();

            if (stack.getItem() instanceof MidnightMantleItem relic && this.getOwner() instanceof LivingEntity owner) {
                relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("starfall").getStatisticData().getMetricData("star_bounces").addValue(1);

                relic.getRelicData(owner, stack).getLevelingData().addExperience("starfall", "star_bounce", 1);
            }
        } else
            this.discard();
    } else
        this.discard();
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    var stack = player.getItemInHand(hand);

    if (!this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").canPlayerUse(player))
        return InteractionResultHolder.pass(stack);

    var radius = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatData("distance").getValue();

    var eyePos = player.getEyePosition();
    var lookAngle = player.getLookAngle().normalize();

    var destination = eyePos.add(lookAngle.scale(radius));

    var hit = level.clip(new ClipContext(eyePos, destination, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player));

    var impulse = Vec3.ZERO;

    var charge = this.getCharge(player, stack);

    if (charge <= 0)
        return InteractionResultHolder.pass(stack);

    if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("ascent").isEnabled()
            && hit.getType() == HitResult.Type.BLOCK && hit.getLocation().distanceTo(eyePos) <= radius) {
        var current = hit.getBlockPos();

        var maxUp = (int) Math.floor(radius - eyePos.distanceTo(hit.getLocation()));

        BlockPos feetPos = null;

        for (int i = 1; i <= maxUp && current.getY() + i < level.getMaxBuildHeight(); i++) {
            var feet = current.above(i);
            var head = feet.above();

            if (level.isEmptyBlock(feet) && level.isEmptyBlock(head)) {
                feetPos = feet;

                break;
            }
        }

        if (feetPos != null)
            destination = feetPos.getBottomCenter();
        else
            destination = hit.getLocation().subtract(lookAngle.scale(0.5));
    } else {
        destination = hit.getLocation();

        if (!level.getBlockState(hit.getBlockPos().below()).blocksMotion())
            destination = destination.add(0, -1, 0);

        var extra = Math.min(player.getKnownMovement().length(), 5);

        impulse = lookAngle.scale(1.25 + extra);
    }

    var random = level.getRandom();

    var shift = player.getBbHeight() / 2F;
    var from = player.position().add(0F, shift, 0F);
    var to = destination.add(0F, shift, 0F);

    level.playSound(player, new BlockPos((int) from.x(), (int) from.y(), (int) from.z()), SoundEvents.ENDERMAN_TELEPORT, SoundSource.MASTER, 1F, 1F);
    level.playSound(player, new BlockPos((int) to.x(), (int) to.y(), (int) to.z()), SoundEvents.ENDERMAN_TELEPORT, SoundSource.MASTER, 1F, 1F);

    if (!level.isClientSide) {
        ServerScheduler.schedule(1, () -> {
            var direction = to.subtract(from);
            var dist = Math.max(0.001, direction.length());

            var forward = direction.scale(1.0 / dist);
            var up = Math.abs(forward.y) < 0.99 ? new Vec3(0, 1, 0) : new Vec3(1, 0, 0);
            var right = forward.cross(up).normalize();
            var binormal = forward.cross(right).normalize();

            var pointCount = (int) Math.round(dist);
            var points = new Vec3[pointCount];

            for (int i = 0; i < pointCount; i++) {
                var t = i / (float) (pointCount - 1);

                var base = new Vec3(Mth.lerp(t, from.x, to.x), Mth.lerp(t, from.y, to.y), Mth.lerp(t, from.z, to.z));
                var wobble = 1F + 0.5F * (float) Math.sin(t * Math.PI);

                var ox = (random.nextFloat() - 0.5F) * wobble;
                var oy = (random.nextFloat() - 0.5F) * wobble;

                points[i] = base.add(right.scale(ox)).add(binormal.scale(oy));
            }

            var segments = 12;

            for (int i = 0; i < pointCount - 1; i++) {
                var p0 = points[i];
                var p1 = points[i + 1];

                for (int s = 0; s <= segments; s++) {
                    var t = s / (float) segments;

                    var px = Mth.lerp(t, p0.x, p1.x);
                    var py = Mth.lerp(t, p0.y, p1.y);
                    var pz = Mth.lerp(t, p0.z, p1.z);

                    if (level instanceof ServerLevel serverLevel)
                        serverLevel.sendParticles(ParticleUtils.constructSimpleSpark(FlawlessUtils.getColor(player, stack, new Color(155 + random.nextInt(100), 80, 255)), 1F, 3, 0.5F), px, py, pz, 1, 0, 0, 0, 0);
                }
            }
        });

        if (player instanceof ServerPlayer serverPlayer) {
            serverPlayer.teleportTo((ServerLevel) level, destination.x, destination.y, destination.z, player.getYRot(), player.getXRot());

            serverPlayer.fallDistance = 0;

            NetworkHandler.sendToClient(new S2CSetEntityMotion(player.getId(), impulse.toVector3f()), serverPlayer);

            var finalImpulse = impulse;

            ServerScheduler.schedule(1, () -> NetworkHandler.sendToClient(new S2CSetEntityMotion(player.getId(), finalImpulse.toVector3f()), serverPlayer));

            this.addCharge(player, stack, -1);

            this.getRelicData(player, stack).getLevelingData().addExperience("blink", "blink", 1);

            this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("blinks_amount").addValue(1);
            this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("distance_traveled").addValue(from.distanceTo(to));

            if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("safe_fall").isEnabled())
                this.setSafeFall(stack, true);

            if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("flicker").isEnabled()) {
                for (var mob : level.getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(32))) {
                    if (mob.getTarget() == player) {
                        mob.setTarget(null);

                        this.getRelicData(player, stack).getLevelingData().addExperience("blink", "flicker", 1);

                        this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("targets").addValue(1);
                    }
                }
            }
        }
    } else {
        if (impulse == Vec3.ZERO)
            ShakeManager.add(level, Shake.builder(player)
                    .radius(Integer.MAX_VALUE)
                    .amplitude(0.2F)
                    .duration(5)
                    .build());
        else
            ShakeManager.add(level, Shake.builder(player)
                    .radius(Integer.MAX_VALUE)
                    .amplitude(0)
                    .fovAmplitude(0.35F)
                    .duration(10)
                    .speed(2)
                    .build());

        ChromaticAberrationManager.add(level, ChromaticAberration.builder(player)
                .radius(Integer.MAX_VALUE)
                .strength(0.075F)
                .duration(10)
                .build());
    }
    return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
}

public void onUseTick(Level level, LivingEntity livingEntity, ItemStack stack, int remainingUseDuration) {
    if (!(livingEntity instanceof Player player))
        return;

    if (player.isPassenger())
        player.stopRiding();

    if (level.isClientSide())
        return;

    var path = new ArrayList<>(stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()));

    if (path.size() < 2) {
        stack.set(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

        if (this.getCooldown(stack) <= 0)
            this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

        player.stopUsingItem();

        return;
    }

    var lastIndex = path.size() - 1;
    var cursor = (double) stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

    if (cursor < 0D || cursor > lastIndex)
        cursor = lastIndex;

    var speed = 1.05D + Math.min(3D, Math.max(0, player.getTicksUsingItem() - 1) * 0.01D);

    cursor = Math.max(0D, cursor - speed);

    var segment = Mth.floor(cursor);

    var t = (float) (cursor - segment);

    var p1 = path.get(segment);
    var p2 = path.get(Math.min(lastIndex, segment + 1));

    if (player instanceof ServerPlayer serverPlayer) {
        var p0 = path.get(Math.max(0, segment - 1));
        var p3 = path.get(Math.min(lastIndex, segment + 2));
        var currentDimension = serverPlayer.level().dimension().location().toString();
        var p1Dimension = p1.dimension().isBlank() ? currentDimension : p1.dimension();
        var p2Dimension = p2.dimension().isBlank() ? currentDimension : p2.dimension();

        if (!p1Dimension.equals(currentDimension)) {
            var dimensionId = ResourceLocation.tryParse(p1Dimension);

            if (dimensionId != null) {
                var key = ResourceKey.create(Registries.DIMENSION, dimensionId);
                var targetLevel = serverPlayer.server.getLevel(key);

                if (targetLevel != null) {
                    serverPlayer.teleportTo(targetLevel, p1.x(), p1.y(), p1.z(), p1.yRot(), p1.xRot());
                    serverPlayer.setPortalCooldown();
                    serverPlayer.setDeltaMovement(Vec3.ZERO);
                    serverPlayer.fallDistance = 0F;

                    setRewindCursor(stack, -1D);
                    setPath(stack, path);

                    player.stopUsingItem();

                    return;
                }
            }
        }

        double targetX;
        double targetY;
        double targetZ;

        float targetYRot;
        float targetXRot;

        if (!p1Dimension.equals(p2Dimension)) {
            var point = p1Dimension.equals(currentDimension) ? p1 : p2;

            targetX = point.x();
            targetY = point.y();
            targetZ = point.z();

            targetYRot = point.yRot();
            targetXRot = point.xRot();
        } else {
            targetX = Mth.catmullrom(t, (float) p0.x(), (float) p1.x(), (float) p2.x(), (float) p3.x());
            targetY = Mth.catmullrom(t, (float) p0.y(), (float) p1.y(), (float) p2.y(), (float) p3.y());
            targetZ = Mth.catmullrom(t, (float) p0.z(), (float) p1.z(), (float) p2.z(), (float) p3.z());

            var targetRotation = this.interpolateLookRotationCatmullrom(t, p0, p1, p2, p3);

            targetYRot = targetRotation.yRot();
            targetXRot = targetRotation.xRot();
        }

        var clampedXRot = Mth.clamp(targetXRot, -90F, 90F);

        if (serverPlayer.distanceToSqr(targetX, targetY, targetZ) > 16D * 16D)
            serverPlayer.teleportTo((ServerLevel) serverPlayer.level(), targetX, targetY, targetZ, targetYRot, clampedXRot);
        else
            serverPlayer.moveTo(targetX, targetY, targetZ, targetYRot, clampedXRot);

        serverPlayer.setYHeadRot(targetYRot);
        serverPlayer.yHeadRotO = targetYRot;
        serverPlayer.yBodyRot = targetYRot;
        serverPlayer.yBodyRotO = targetYRot;
        serverPlayer.setDeltaMovement(Vec3.ZERO);
        serverPlayer.fallDistance = 0F;
    }

    if (level instanceof ServerLevel) {
        var random = level.random;
        var previousCenter = new Vec3(player.xOld, player.yOld + player.getBbHeight() * 0.55D, player.zOld);
        var currentCenter = new Vec3(player.getX(), player.getY() + player.getBbHeight() * 0.55D, player.getZ());
        var movement = currentCenter.subtract(previousCenter);
        var distance = movement.length();
        var spawnCount = Mth.clamp((int) Math.ceil(distance / 0.125D), 2, 5);
        var phase = player.tickCount * 0.45D;

        for (int step = 0; step <= spawnCount; step++) {
            var progress = spawnCount == 0 ? 0D : (double) step / spawnCount;
            var center = previousCenter.add(movement.scale(progress));
            var subPhase = phase + progress * 0.35D;

            for (int i = 0; i < 6; i++) {
                var angle = subPhase + i * (Math.PI * 2D / 6D);
                var radius = 0.45D + 0.12D * Math.sin(subPhase * 1.6D + i);

                var px = center.x + Math.cos(angle) * radius;
                var pz = center.z + Math.sin(angle) * radius;
                var py = center.y + Math.sin(angle * 1.7D) * 0.2D;

                var hue = (float) ((0.58D + subPhase * 0.025D + i * 0.06D) % 1D);
                var color = Color.getHSBColor(hue, 0.6F + random.nextFloat() * 0.25F, 1F);

                var inward = new Vec3(center.x - px, center.y - py, center.z - pz).scale(0.1D);
                var swirl = new Vec3(-Math.sin(angle), 0D, Math.cos(angle)).scale(0.03D);

                var velocity = inward.add(swirl).add(0D, 0.01D + random.nextDouble() * 0.01D, 0D);

                NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat() * 0.15F, 20 + random.nextInt(10), 0.975F), new Vector3f((float) px, (float) py, (float) pz),
                        new Vector3f((float) velocity.x, (float) velocity.y, (float) velocity.z)), player);
            }
        }
    }

    var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

    if (ability.canPlayerUse(player)) {
        this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "rewind", 1D / 20D);

        ability.getStatisticData().getMetricData("rewind_duration").addValue(1D / 20D);
    }

    if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
        var rewindHealth = Mth.lerp(t, p1.health(), p2.health());
        var currentHealth = player.getHealth();
        var targetHealth = Math.min(player.getMaxHealth(), Math.max(currentHealth, rewindHealth));

        if (targetHealth > currentHealth) {
            player.setHealth(targetHealth);

            if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
                this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "health_rewind", targetHealth - currentHealth);
                ability.getStatisticData().getMetricData("health_restored").addValue(targetHealth - currentHealth);
            }
        }
    }

    while (path.size() > 2 && cursor <= path.size() - 2)
        path.removeLast();

    if (cursor <= 0D) {
        setRewindCursor(stack, -1D);
        setPath(stack, path);

        if (this.getCooldown(stack) <= 0)
            this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

        player.stopUsingItem();

        return;
    }

    setRewindCursor(stack, cursor);
    setPath(stack, path);
}

public static void onLivingEntityTick(LivingEntity entity) {
    if (entity.isRemoved()) return;

    var capability = AccessoriesCapability.get(entity);

    if (capability != null) {
        var dirtyStacks = new HashMap<SlotPath, ItemStack>();
        var dirtyCosmeticStacks = new HashMap<SlotPath, ItemStack>();

        var removedAttributesBuilder = new AccessoryAttributeBuilder();
        var addedAttributesBuilder = new AccessoryAttributeBuilder();

        for (var containerEntry : AccessoriesHolderImpl.getHolder(capability).getAllSlotContainers().entrySet()) {
            var container = containerEntry.getValue();

            var accessories = container.getAccessories();
            var cosmetics = container.getCosmeticAccessories();

            for (int i = 0; i < accessories.getContainerSize(); i++) {
                var slotReference = container.createReference(i);

                var currentStack = accessories.getItem(i);

                // TODO: Move ticking below checks?
                if (!currentStack.isEmpty()) {
                    // TODO: Document this behavior to prevent double ticking maybe!!!
                    currentStack.inventoryTick(entity.level(), entity, null);

                    var accessory = AccessoryRegistry.getAccessoryOrDefault(currentStack);

                    if (accessory != null) {
                        accessory.tick(currentStack, slotReference);

                        AccessoryNestUtils.recursivelyConsume(currentStack, stack -> {
                            var effects = stack.get(AccessoriesDataComponents.MOB_EFFECTS);

                            if (effects != null) {
                                effects.handleReapplyingEffects(entity, entity.level().getGameTime());
                            }
                        });
                    }
                }

                var lastStack = accessories.getPreviousItem(i);
                var flagged = accessories.isSlotFlagged(i);

                // Prevent attribute related logic on the client and if the entity
                // is dead as such data should not be updated. Though we allow for
                // ticking to occur at least for vanilla parity I guess.
                if (entity.level().isClientSide() || entity.isDeadOrDying()) continue;

                if (!ItemStack.matches(currentStack, lastStack) || flagged) {
                    if (!lastStack.isEmpty()) {
                        var removedEnchantmentBuilder = new AccessoryAttributeBuilder(slotReference);

                        // TODO: MAYBE MOVE THIS TO AccessoryAttributeLogic or something
                        EnchantmentHelper.forEachModifier(lastStack, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot(), (attributeHolder, modifier) -> {
                            var namespace = modifier.id().getNamespace();
                            var splitPath = new ArrayList<>(List.of(modifier.id().getPath().split("/")));

                            splitPath.removeLast();

                            removedEnchantmentBuilder.addStackable(attributeHolder, new AttributeModifier(ResourceLocation.fromNamespaceAndPath(namespace, String.join("/", splitPath)), modifier.amount(), modifier.operation()));
                        });

                        removedAttributesBuilder.addFrom(removedEnchantmentBuilder);
                        removedAttributesBuilder.addFrom(AccessoryAttributeLogic.getAttributeModifiers(lastStack, slotReference));

                        ((AccessoriesLivingEntityExtension) entity).pushEnchantmentContext(lastStack, slotReference);
                        EnchantmentHelper.stopLocationBasedEffects(lastStack, entity, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot());
                    }

                    if (!currentStack.isEmpty()) {
                        var addedEnchantmentBuilder = new AccessoryAttributeBuilder(slotReference);

                        EnchantmentHelper.forEachModifier(currentStack, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot(), (attributeHolder, modifier) -> {
                            var namespace = modifier.id().getNamespace();
                            var splitPath = new ArrayList<>(List.of(modifier.id().getPath().split("/")));

                            splitPath.removeLast();

                            addedEnchantmentBuilder.addStackable(attributeHolder, new AttributeModifier(ResourceLocation.fromNamespaceAndPath(namespace, String.join("/", splitPath)), modifier.amount(), modifier.operation()));
                        });

                        addedAttributesBuilder.addFrom(addedEnchantmentBuilder);
                        addedAttributesBuilder.addFrom(AccessoryAttributeLogic.getAttributeModifiers(currentStack, slotReference));

                        ((AccessoriesLivingEntityExtension) entity).pushEnchantmentContext(currentStack, slotReference);
                        EnchantmentHelper.runLocationChangedEffects((ServerLevel) entity.level(), currentStack, entity, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot());
                    }

                    AccessoryNestUtils.recursivelyConsume(lastStack, stack -> {
                        if (stack.has(AccessoriesDataComponents.MOB_EFFECTS)) {
                            stack.get(AccessoriesDataComponents.MOB_EFFECTS)
                                .handleRemovingEffects(entity);
                        }
                    });

                    AccessoryNestUtils.recursivelyConsume(currentStack, stack -> {
                        if (stack.has(AccessoriesDataComponents.MOB_EFFECTS)) {
                            stack.get(AccessoriesDataComponents.MOB_EFFECTS)
                                .handleApplyingConstantEffects(entity);
                        }
                    });

                    boolean equipmentChange = false;

                    /*
                     * TODO: Does item check need to exist anymore?
                     */
                    if (!ItemStack.isSameItem(currentStack, lastStack) || flagged) {
                        AccessoryRegistry.getAccessoryOrDefault(lastStack).onUnequip(lastStack, slotReference);
                        AccessoryRegistry.getAccessoryOrDefault(currentStack).onEquip(currentStack, slotReference);

                        if (entity instanceof ServerPlayer serverPlayer) {
                            if (!currentStack.isEmpty()) {
                                ACCESSORY_EQUIPPED.trigger(serverPlayer, currentStack, slotReference, false);
                            }

                            if (!lastStack.isEmpty()) {
                                ACCESSORY_UNEQUIPPED.trigger(serverPlayer, lastStack, slotReference, false);
                            }
                        }

                        equipmentChange = true;
                    }

                    AccessoryChangeCallback.EVENT.invoker().onChange(lastStack, currentStack, slotReference, equipmentChange ? SlotStateChange.REPLACEMENT : SlotStateChange.MUTATION);

                    container.getAccessories().setPreviousItem(i, currentStack);
                    dirtyStacks.put(slotReference.slotPath(), currentStack.copy());

                    recursiveStackChange(slotReference, AccessoryNestUtils.getData(lastStack), AccessoryNestUtils.getData(currentStack));
                }

                var currentCosmeticStack = cosmetics.getItem(i);
                var lastCosmeticStack = container.getCosmeticAccessories().getPreviousItem(i);

                if (!ItemStack.matches(currentCosmeticStack, lastCosmeticStack)) {
                    cosmetics.setPreviousItem(i, currentCosmeticStack);
                    dirtyCosmeticStacks.put(slotReference.slotPath(), currentCosmeticStack.copy());

                    if (entity instanceof ServerPlayer serverPlayer) {
                        if (!currentStack.isEmpty()) {
                            ACCESSORY_EQUIPPED.trigger(serverPlayer, currentStack, slotReference, true);
                        }
                        if (!lastStack.isEmpty()) {
                            ACCESSORY_UNEQUIPPED.trigger(serverPlayer, lastStack, slotReference, true);
                        }
                    }
                }
            }
        }

        if (entity.level().isClientSide()) return;

        AttributeUtils.removeTransientAttributeModifiers(entity, removedAttributesBuilder);
        AttributeUtils.addTransientAttributeModifiers(entity, addedAttributesBuilder);

        //--
        var updatedContainers = AccessoriesHolderImpl.getHolder(capability).containersRequiringUpdates();

        capability.updateContainers();

        ContainersChangeCallback.EVENT.invoker().onChange(entity, capability, ImmutableMap.copyOf(updatedContainers));

        if (!dirtyStacks.isEmpty() || !dirtyCosmeticStacks.isEmpty() || !updatedContainers.isEmpty()) {
            var packet = SyncContainerData.of(entity, updatedContainers.keySet(), dirtyStacks, dirtyCosmeticStacks);

            AccessoriesNetworking.sendToTrackingAndSelf(entity, packet);
        }

        updatedContainers.clear();
    }

    //--

    var holder = ((AccessoriesHolderImpl) AccessoriesInternals.INSTANCE.getHolder(entity));

    // Fix for holder data not being loaded so invalid stacks can be collected
    if (holder.loadedFromTag() && capability == null) {
        var tempCapability = new AccessoriesCapabilityImpl(entity);
    }

    var invalidStacks = (holder).invalidStacks;

    if (!invalidStacks.isEmpty() && entity.level() instanceof ServerLevel serverLevel) {
        for (ItemStack invalidStack : invalidStacks) {
            if (entity instanceof ServerPlayer serverPlayer) {
                AccessoriesInternals.INSTANCE.giveItemToPlayer(serverPlayer, invalidStack);
            } else {
                entity.spawnAtLocation(serverLevel, invalidStack);
            }
        }

        invalidStacks.clear();
    }
}

public static boolean performAttack(IToolStackView tool, ToolAttackContext context) {
  // moved damage calculation, knockback, and cooldown to ToolAttackUtil.Builder
  // missing: enchantment modifiers, we handle modifiers instead

  // calculate conditional damage from modifiers
  float baseDamage = context.getBaseDamage();
  float damage = baseDamage;
  List<ModifierEntry> modifiers = tool.getModifierList();
  for (ModifierEntry entry : modifiers) {
    damage = entry.getHook(ModifierHooks.MELEE_DAMAGE).getMeleeDamage(tool, entry, context, baseDamage, damage);
  }
  // no damage? do nothing
  if (damage <= 0) {
    return false;
  }
  // checked immediately in case anything else changes damage
  boolean isMagic = damage > baseDamage;

  // knockback moved lower

  // apply critical damage boost
  float criticalModifier = context.getCriticalModifier();
  if (criticalModifier != 1) {
    damage += baseDamage * (criticalModifier - 1);
  }

  // removed: sword check hook, replaced by weapon callback
  // removed: fire aspect check, replaced by before damage lower

  // apply cutoff and cooldown, store if damage was above base for magic particles
  float cooldown = context.getCooldown();
  if (cooldown < 1) {
    damage *= (0.2f + cooldown * cooldown * 0.8f);
  }

  // track original health and motion before attack
  // Vec3 originalTargetMotion = targetEntity.getDeltaMovement();
  float oldHealth = 0.0F;
  LivingEntity targetLiving = context.getLivingTarget();
  if (targetLiving != null) {
    oldHealth = targetLiving.getHealth();
  }

  // removed: vanilla knockback enchant support
  // changed: knockback halved for simplicity

  // apply modifier knockback and special effects
  float baseKnockback = context.getBaseKnockback();
  float knockback = baseKnockback;
  for (ModifierEntry entry : modifiers) {
    knockback = entry.getHook(ModifierHooks.MELEE_HIT).beforeMeleeHit(tool, entry, context, damage, baseKnockback, knockback);
  }

  // set hand for proper looting context
  LivingEntity attackerLiving = context.getAttacker();
  EquipmentSlot sourceSlot = context.getSlotType();
  ModifierLootingHandler.setLootingSlot(attackerLiving, sourceSlot);

  // if knockback is below the vanilla amount, we need to prevent knockback, the remainder will be applied later
  AttributeInstance knockbackModifier = null;
  if (knockback < 0.4f) {
    knockbackModifier = disableKnockback(targetLiving);
  } else if (targetLiving != null) {
    // we will apply 0.4 of the knockback in the attack hook, need to apply the remainder ourself
    knockback -= 0.4f;
  }

  ///////////////////
  // actual attack //
  ///////////////////

  // removed: sword special attack check and logic, replaced by this
  Entity targetEntity = context.getTarget();
  boolean didHit = targetEntity.hurt(context.makeDamageSource(), damage);

  // reset hand to make sure we don't mess with vanilla tools
  ModifierLootingHandler.setLootingSlot(attackerLiving, EquipmentSlot.MAINHAND);
  // reset knockback if needed
  enableKnockback(knockbackModifier);

  // if we failed to hit, fire failure hooks
  // alternatively, if we cannot hit this target, we are supposed to return true for the sake of special casing endermen,
  Level level = context.getLevel();
  boolean isExtraAttack = context.isExtraAttack();
  Projectile projectile = context.getProjectile();
  if (!didHit || projectile != null && !TinkerEffects.canHitWithProjectile(targetLiving)) {
    if (!isExtraAttack) {
      level.playSound(null, attackerLiving.getX(), attackerLiving.getY(), attackerLiving.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, attackerLiving.getSoundSource(), 1.0F, 1.0F);
    }
    // alert modifiers nothing was hit, mainly used for fiery
    for (ModifierEntry entry : modifiers) {
      entry.getHook(ModifierHooks.MELEE_HIT).failedMeleeHit(tool, entry, context, damage);
    }
    return false;
  }

  // post melee hook - TODO: should this be lower?
  tool.getHook(ToolHooks.MELEE_HIT).afterMeleeHit(tool, context, damage);

  // determine damage actually dealt
  float damageDealt = damage;
  if (targetLiving != null) {
    damageDealt = oldHealth - targetLiving.getHealth();
  }

  // apply knockback
  if (knockback > 0) {
    if (targetLiving != null) {
      targetLiving.knockback(knockback, Mth.sin(attackerLiving.getYRot() * DEGREE_TO_RADIANS), -Mth.cos(attackerLiving.getYRot() * DEGREE_TO_RADIANS));
    } else {
      targetEntity.push(-Mth.sin(attackerLiving.getYRot() * DEGREE_TO_RADIANS) * knockback, 0.1d, Mth.cos(attackerLiving.getYRot() * DEGREE_TO_RADIANS) * knockback);
    }
    attackerLiving.setDeltaMovement(attackerLiving.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
    attackerLiving.setSprinting(false);
  }

  // removed: sword sweep attack, handled above

  // apply velocity change to players if needed
  if (targetEntity.hurtMarked && targetEntity instanceof ServerPlayer serverPlayer) {
    serverPlayer.connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
    targetEntity.hurtMarked = false;
    // TODO: why was this needed before? targetEntity.setDeltaMovement(originalTargetMotion);
  }

  // play sound effects and particles

  Player attackerPlayer = context.getPlayerAttacker();
  if (attackerPlayer != null) {
    // particles
    if (criticalModifier > 1) {
      attackerPlayer.crit(targetEntity);
    }
    if (isMagic) {
      attackerPlayer.magicCrit(targetEntity);
    }
    // sounds
    level.playSound(null, attackerLiving.getX(), attackerLiving.getY(), attackerLiving.getZ(), context.getSound(), attackerLiving.getSoundSource(), 1.0F, 1.0F);
  }
  if (damageDealt > 2.0F && level instanceof ServerLevel server) {
    int particleCount = (int)(damageDealt * 0.5f);
    server.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0, 0.1, 0.2);
  }

  // deal attacker thorns damage
  attackerLiving.setLastHurtMob(targetEntity);
  if (targetLiving != null) {
    EnchantmentHelper.doPostHurtEffects(targetLiving, attackerLiving);
  }

  // apply modifier effects
  // removed: bane of arthropods hook, replaced by this
  for (ModifierEntry entry : modifiers) {
    entry.getHook(ModifierHooks.MELEE_HIT).afterMeleeHit(tool, entry, context, damageDealt);
  }

  // hurt resistance adjustment for high speed weapons
  float speed = tool.getStats().get(ToolStats.ATTACK_SPEED);
  int time = Math.round(20f / speed);
  if (time < targetEntity.invulnerableTime) {
    targetEntity.invulnerableTime = (targetEntity.invulnerableTime + time) / 2;
  }

  // final attack hooks
  if (attackerPlayer != null) {
    if (targetLiving != null) {
      if (!level.isClientSide && !isExtraAttack) {
        ItemStack held = attackerLiving.getItemBySlot(sourceSlot);
        if (!held.isEmpty()) {
          held.hurtEnemy(targetLiving, attackerPlayer);
        }
      }
      attackerPlayer.awardStat(Stats.DAMAGE_DEALT, Math.round(damageDealt * 10.0F));
    }
    // removed: fire damage, handled in modifier hook above
    if (projectile == null) {
      attackerPlayer.causeFoodExhaustion(0.1F);
    }

    // add usage stat
    if (!isExtraAttack && projectile == null) {
      attackerPlayer.awardStat(Stats.ITEM_USED.get(tool.getItem()));
    }
  }

  // damage the tool
  if (!tool.hasTag(TinkerTags.Items.UNARMED)) {
    int durabilityLost = targetLiving != null ? 1 : 0;
    if (!tool.hasTag(TinkerTags.Items.MELEE_PRIMARY)) {
      durabilityLost *= 2;
    }
    // don't do the full damage animation for broken projectiles as it's not next to you, so that's weird
    if (projectile != null) {
      ToolDamageUtil.damage(tool, durabilityLost, attackerLiving, attackerLiving.getItemBySlot(sourceSlot));
    } else {
      ToolDamageUtil.damageAnimated(tool, durabilityLost, attackerLiving, sourceSlot);
    }
  }

  return true;
}

public void tick() {
    super.tick();

    if (this.isStuck())
        this.setDeltaMovement(Vec3.ZERO);

    var level = this.level();

    if (this.isStuck()) {
        if (!level.isClientSide()) {
            var owner = this.getOwner();

            if (owner instanceof LivingEntity livingOwner && !level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox(),
                    entity -> entity != livingOwner && TargetingUtils.canHarm(livingOwner, entity, this.getStack(), "constellation")).isEmpty())
                this.discard();

            if (this.tickCount % 5 == 0 && this.tickCount >= this.getLifetime() * 20 && random.nextInt(20) == 0)
                this.discard();
        }

        if (level.isClientSide()) {
            var color = isFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(50 + random.nextInt(50), 50 + random.nextInt(150), 255);
            var data = ParticleUtils.constructSimpleSpark(color, 0.2F + random.nextFloat() * 0.1F, 30 + random.nextInt(20), 0.95F);

            level.addParticle(data, this.getX() + MathUtils.randomFloat(random) * this.getBbWidth() / 2F, this.getY(), this.getZ() + MathUtils.randomFloat(random) * this.getBbWidth() / 2F, 0, 0.1F + random.nextFloat() * 0.1F, 0);
        }

        var origin = this;
        var queue = new ArrayDeque<ConstellationStarEntity>();
        var visited = new HashSet<ConstellationStarEntity>();

        queue.add(origin);
        visited.add(origin);

        while (!queue.isEmpty()) {
            var current = queue.removeFirst();

            var neighbors = level.getEntitiesOfClass(ConstellationStarEntity.class, current.getBoundingBox().inflate(this.getConstellationRadius()));

            for (var star : neighbors) {
                if (visited.add(star))
                    queue.add(star);
            }
        }

        if (visited.size() < 2)
            return;

        var sortedIds = new ArrayList<>(visited);

        var originIndex = sortedIds.indexOf(origin);

        var totalStars = sortedIds.size();
        var starEntities = new ConstellationStarEntity[totalStars];
        var starCenters = new Vec3[totalStars];
        var midYs = new double[totalStars];

        for (var i = 0; i < totalStars; i++) {
            var e = sortedIds.get(i);

            starEntities[i] = e;

            if (e != null) {
                var c = e.getBoundingBox().getCenter();

                starCenters[i] = c;
                midYs[i] = c.y;
            }
        }

        var edges = new ArrayList<int[]>();
        var exists = new boolean[totalStars][totalStars];

        for (var i = 0; i < totalStars; i++) {
            var a = starCenters[i];

            if (a == null || !starEntities[i].isStuck())
                continue;

            var neighbors = new ArrayList<EdgeCandidate>();

            for (var j = 0; j < totalStars; j++) {
                if (i == j)
                    continue;

                var b = starCenters[j];

                if (b == null || !starEntities[j].isStuck())
                    continue;

                var dx = a.x - b.x;
                var dy = a.y - b.y;
                var dz = a.z - b.z;

                neighbors.add(new EdgeCandidate(i, j, dx * dx + dy * dy + dz * dz));
            }

            neighbors.sort(Comparator.comparingDouble(e -> e.weightSquared));

            var connections = 0;

            for (var candidate : neighbors) {
                if (connections >= 2)
                    break;

                var u = candidate.indexU;
                var v = candidate.indexV;

                if (exists[u][v])
                    continue;

                edges.add(new int[]{u, v});
                exists[u][v] = exists[v][u] = true;

                connections++;
            }
        }

        for (var edge : edges) {
            if (edge[0] != originIndex)
                continue;

            var a = starCenters[edge[0]];
            var b = starCenters[edge[1]];

            if (a == null || b == null)
                continue;

            var dir = b.subtract(a);
            var length = dir.length();
            var dirNorm = dir.scale(1 / length);

            var proximityThreshold = 0.5;

            var segmentBox = new AABB(
                    Math.min(a.x(), b.x()) - proximityThreshold,
                    Math.min(a.y(), b.y()) - proximityThreshold,
                    Math.min(a.z(), b.z()) - proximityThreshold,
                    Math.max(a.x(), b.x()) + proximityThreshold,
                    Math.max(a.y(), b.y()) + proximityThreshold,
                    Math.max(a.z(), b.z()) + proximityThreshold
            );

            var crossed = false;
            var owner = this.getOwner();

            for (var entity : level.getEntitiesOfClass(LivingEntity.class, segmentBox,
                    entity -> owner instanceof LivingEntity livingOwner && entity != livingOwner && TargetingUtils.canHarm(livingOwner, entity, this.getStack(), "constellation"))) {
                if (entity.getBoundingBox().clip(a, b).isPresent()) {
                    crossed = true;

                    if (!level.isClientSide() && owner instanceof LivingEntity livingOwner)
                        TargetingUtils.addHarmfulEffect(entity, new MobEffectInstance(RelicsMobEffects.TREMOR, (int) (this.getTremor() * 20), 0), livingOwner, this.getStack(), "constellation");

                    if (!level.isClientSide() && entity.tickCount % 20 == 0 && stack.getItem() instanceof MidnightMantleItem relic && owner instanceof LivingEntity livingOwner)
                        relic.getRelicData(livingOwner, stack).getLevelingData().addExperience("constellation", "star_tremor", 1);
                }
            }

            if (level.isClientSide()) {
                var particleSpacing = 0.15;

                var up = new Vec3(0, 1, 0);
                var u = dirNorm.cross(up);

                if (u.length() < 1e-4)
                    u = dirNorm.cross(new Vec3(1, 0, 0));

                u = u.normalize();

                var v = dirNorm.cross(u).normalize();

                var stepCount = Math.max(1, (int) Math.ceil(length / particleSpacing));

                var amplitude = 0.05D;
                var wavelength = 2D;
                var speed = 0.05D;

                var time = (level.getGameTime() + this.getId()) * speed;

                for (var step = 0; step <= stepCount; step++) {
                    var f = step / (double) stepCount;
                    var basePos = a.add(dir.scale(f));
                    var phase = (f * length) / wavelength * 2 * Math.PI + time;
                    var offset = u.scale(Math.cos(phase) * amplitude).add(v.scale(Math.sin(phase) * amplitude));
                    var pos = basePos.add(offset);

                    if (crossed) {
                        var color = new Color(255, random.nextInt(50), 0);
                        var data = ParticleUtils.constructSimpleSpark(color, 0.25F, 5, 0.9F);

                        var motion = 0.05F;

                        level.addParticle(data, true, pos.x, pos.y, pos.z, MathUtils.randomFloat(random) * motion, MathUtils.randomFloat(random) * motion, MathUtils.randomFloat(random) * motion);
                    } else {
                        var color = isFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(50 + random.nextInt(50), 50 + random.nextInt(150), 255);
                        var data = ParticleUtils.constructSimpleSpark(color, 0.25F, 0, 1F);

                        level.addParticle(data, true, pos.x, pos.y, pos.z, 0, 0, 0);
                    }
                }
            }
        }
    }
}

private static void addEntityBasedTooltipData(LivingEntity entity, Accessory accessory, ItemStack stack, List<Component> tooltip, TooltipDisplay display, Item.TooltipContext tooltipContext, TooltipFlag tooltipType) {
    // TODO: MAYBE DEPENDING ON ENTITY OR SOMETHING SHOW ALL VALID SLOTS BUT COLOR CODE THEM IF NOT VALID FOR ENTITY?
    // TODO: ADD BETTER HANDLING FOR POSSIBLE SLOTS THAT ARE EQUIPABLE IN BUT IS AT ZERO SIZE
    var validSlotTypes = new HashSet<>(SlotValidatorRegistry.getValidSlotTypes(entity, stack));

    if (validSlotTypes.isEmpty()) return;

    {
        final var validUniqueSlots = new HashSet<SlotType>();

        validSlotTypes.removeIf(slotType -> {
            var isUnique = UniqueSlotHandling.isUniqueSlot(slotType.name());

            if(isUnique) validUniqueSlots.add(slotType);

            return isUnique;
        });

        var sharedSlotTypes = SlotTypeLoader.INSTANCE.getEntries(entity.level()).values()
                .stream()
                .filter(slotType -> !UniqueSlotHandling.isUniqueSlot(slotType.name()))
                .collect(Collectors.toSet());

        var slotInfoComponent = Component.literal("");

        var slotsComponent = Component.literal("");
        boolean allSlots = false;

        if (validSlotTypes.containsAll(sharedSlotTypes)) {
            slotsComponent.append(Component.translatable(Accessories.translationKey("slot.any")));
            allSlots = true;
        } else {
            var entitySlotTypes = Set.copyOf(EntitySlotLoader.getEntitySlots(entity).values());

            var invalidSlotsTypes = Sets.difference(entitySlotTypes, validSlotTypes);

            if (invalidSlotsTypes.size() < validSlotTypes.size()) {
                slotsComponent.append(Component.translatable(Accessories.translationKey("slot.any")));
                slotsComponent.append(Component.translatable(Accessories.translationKey("slot.except")).withStyle(ChatFormatting.GRAY));

                var invalidSlotsItr = invalidSlotsTypes.iterator();

                while(invalidSlotsItr.hasNext()) {
                    var type = invalidSlotsItr.next();

                    if (ExtraSlotTypeProperties.getProperty(type.name(), entity.level().isClientSide()).allowTooltipInfo()) {
                        slotsComponent.append(Component.translatable(type.translation()).withStyle(ChatFormatting.RED));

                        if (invalidSlotsItr.hasNext()) {
                            slotsComponent.append(Component.literal(", ").withStyle(ChatFormatting.GRAY));
                        }
                    }
                }
            } else {
                var validSlotsItr = validSlotTypes.iterator();

                while(validSlotsItr.hasNext()) {
                    var type = validSlotsItr.next();

                    if (ExtraSlotTypeProperties.getProperty(type.name(), entity.level().isClientSide()).allowTooltipInfo()) {
                        slotsComponent.append(Component.translatable(type.translation()));

                        if (validSlotsItr.hasNext()) {
                            slotsComponent.append(Component.literal(", ").withStyle(ChatFormatting.GRAY));
                        }
                    }
                }
            }
        }

        validSlotTypes.addAll(validUniqueSlots);

        final var filteredValidUniqueSlots = validUniqueSlots.stream()
                .filter(slotType -> ExtraSlotTypeProperties.getProperty(slotType.name(), true).allowTooltipInfo())
                .toList();

        if (!filteredValidUniqueSlots.isEmpty()) {
            var uniqueItr = filteredValidUniqueSlots.iterator();

            while(uniqueItr.hasNext()) {
                var type = uniqueItr.next();

                slotsComponent.append(Component.translatable(type.translation()));

                if(uniqueItr.hasNext()) {
                    slotsComponent.append(Component.literal(", ").withStyle(ChatFormatting.GRAY));
                }
            }
        }

        if(!slotsComponent.getSiblings().isEmpty()) {
            var slotTranslationKey = "slot.tooltip." + ((validSlotTypes.size() > 1 && !allSlots) ? "plural" : "singular");

            slotInfoComponent.append(
                Component.translatable(Accessories.translationKey(slotTranslationKey))
                    .withStyle(ChatFormatting.GRAY)
                    .append(slotsComponent.withStyle(ChatFormatting.BLUE))
            );

            tooltip.add(slotInfoComponent);
        }
    }

    var slotSpecificModifiers = new HashMap<SlotType, AccessoryAttributeBuilder>();
    AccessoryAttributeBuilder defaultModifiers = null;

    boolean allDuplicates = true;

    for (var slotType : validSlotTypes) {
        var reference = SlotReference.of(entity, slotType.name(), 0);

        var builder = AccessoryAttributeLogic.getAttributeModifiers(stack, reference, true);

        if (builder.isEmpty()) continue;

        slotSpecificModifiers.put(slotType, builder);

        if (defaultModifiers == null) {
            defaultModifiers = builder;
        } else if (allDuplicates) {
            // TODO: ! WARNING ! THIS MAY NOT WORK?
            allDuplicates = defaultModifiers.equalWithoutPaths(builder);
        }
    }

    var slotTypeToTooltipInfo = new HashMap<SlotType, List<Component>>();

    if (allDuplicates) {
        if (defaultModifiers != null && !defaultModifiers.isEmpty()) {
            var attributeTooltip = new ArrayList<Component>();

            addAttributeTooltip(entity, stack, defaultModifiers.getAttributeModifiers(false), attributeTooltip, display, tooltipContext, tooltipType);

            slotTypeToTooltipInfo.put(null, attributeTooltip);
        }
    } else {
        for (var slotModifiers : slotSpecificModifiers.entrySet()) {
            var slotType = slotModifiers.getKey();
            var modifiers = slotModifiers.getValue();

            var attributeTooltip = new ArrayList<Component>();

            addAttributeTooltip(entity, stack, modifiers.getAttributeModifiers(false), attributeTooltip, display, tooltipContext, tooltipType);

            slotTypeToTooltipInfo.put(slotType, attributeTooltip);
        }
    }

    var extraAttributeTooltips = new HashMap<SlotType, List<Component>>();
    List<Component> defaultExtraAttributeTooltip = null;

    boolean allDuplicatesExtras = true;

    for (var slotType : validSlotTypes) {
        var extraAttributeTooltip = new ArrayList<Component>();
        accessory.getAttributesTooltip(stack, slotType, extraAttributeTooltip, tooltipContext, tooltipType);

        extraAttributeTooltips.put(slotType, extraAttributeTooltip);

        if (defaultExtraAttributeTooltip == null) {
            defaultExtraAttributeTooltip = extraAttributeTooltip;
        } else if (allDuplicatesExtras) {
            allDuplicatesExtras = extraAttributeTooltip.equals(defaultExtraAttributeTooltip);
        }
    }

    if (allDuplicatesExtras) {
        if (defaultExtraAttributeTooltip != null) {
            slotTypeToTooltipInfo.computeIfAbsent(null, s -> new ArrayList<>())
                .addAll(defaultExtraAttributeTooltip);
        }
    } else {
        extraAttributeTooltips.forEach((slotType, components) -> {
            slotTypeToTooltipInfo.computeIfAbsent(slotType, s -> new ArrayList<>())
                    .addAll(components);
        });
    }

    if (slotTypeToTooltipInfo.containsKey(null)) {
        var anyTooltipInfo = slotTypeToTooltipInfo.get(null);

        if (!anyTooltipInfo.isEmpty()) {
            tooltip.add(CommonComponents.EMPTY);

            tooltip.add(
                    Component.translatable(Accessories.translationKey("tooltip.attributes.any"))
                            .withStyle(ChatFormatting.GRAY)
            );

            tooltip.addAll(anyTooltipInfo);
        }

        slotTypeToTooltipInfo.remove(null);
    }

    if (!slotTypeToTooltipInfo.isEmpty()) {
        for (var entry : slotTypeToTooltipInfo.entrySet()) {
            var tooltipData = entry.getValue();

            if (tooltipData.isEmpty()) continue;

            tooltip.add(CommonComponents.EMPTY);

            tooltip.add(
                    Component.translatable(
                            Accessories.translationKey("tooltip.attributes.slot"),
                            Component.translatable(entry.getKey().translation()).withStyle(ChatFormatting.BLUE)
                    ).withStyle(ChatFormatting.GRAY)
            );

            tooltip.addAll(entry.getValue());
        }
    }
}

public void generateTrees(BranchedCommandGenerator root, CommandBuildContext context, Commands.CommandSelection environment) {
    root.modifyRootNode(builder -> builder.requires(stack -> stack.hasPermission(Commands.LEVEL_GAMEMASTERS)));

    if (((CommandSelectionAccessor) (Object) environment).accessories$includeIntegrated()) {
        root.branch("rendering", renderingBranch -> {
            renderingBranch.leaves(
                "create-renderer-stack",
                required("renderer_id", ResourceLocationArgument.id()),
                required("item_model_id", ResourceLocationArgument.id()),
                required("custom_name", ComponentArgument.textComponent(context)),
                defaulted("is_bundle", BoolArgumentType.bool(), false),
                (ctx, rendererId, itemModelId, component, isBundle) -> {
                    AccessoriesCommands.createRenderStack(ctx, rendererId, itemModelId, component, isBundle);
                    return 0;
                }
            ).leaves(
                "listen-to-renderer",
                defaulted("item_model_id", ResourceLocationArgument.id(), null),
                (ctx, id) -> {
                    CustomRendererLoader.constantFileResolving(ctx.getSource().getServer(), id);

                    return 1;
                }
            );
        });
    }

    var toggleableFeatures = List.of("banner", "glider", "totem");

    var featureToggleFailure = new DynamicCommandExceptionType(branch -> Component.translatable("accessories.commands.feature.toggle.failure", branch, toggleableFeatures.toString()));

    root.leaves(
        "feature",
        branches("enable", "disable"),
        branches(toggleableFeatures),
        //required("value", BoolArgumentType.bool()),
        (ctx, state, branch) -> {
            var bl = Objects.equals(state, "enable");

            switch (branch) {
                case "banner" -> Accessories.config().contentOptions.allowBannerEquip(bl);
                case "glider" -> Accessories.config().contentOptions.allowGliderEquip(bl);
                case "totem" -> Accessories.config().contentOptions.allowTotemEquip(bl);
                case null, default -> throw featureToggleFailure.create(branch);
            }

            ctx.getSource().sendSystemMessage(Component.translatable("accessories.commands.feature.toggle." + (bl ? "on" : "off"), branch));

            return 1;
        }
    );

    root.leaves(
        "edit",
        defaulted("entity", EntityArgument.entity(), AccessoriesCommands::getOrThrowLivingEntity, null),
        (ctx, livingEntity) -> {
            Accessories.askPlayerForVariant(ctx.getSource().getPlayerOrException(), livingEntity);

            return 1;
        });

    var validLoggingBranches = List.of("slots", "groups", "entity_bindings");

    var logFailureType = new DynamicCommandExceptionType(branch -> Component.translatable("accessories.commands.dump.failure", branch, validLoggingBranches.toString()));

    root.leaves(
        "dump",
        branches(validLoggingBranches),
        (ctx, branch) -> {
            switch (branch) {
                case "slots" -> {
                    LOGGER.info("All given Slots registered:");

                    for (var slotType : SlotTypeLoader.INSTANCE.getEntries(ctx.getSource().getLevel()).values()) {
                        LOGGER.info(slotType.dumpData());
                    }
                }
                case "groups" -> {
                    LOGGER.info("All given Slot Groups registered:");

                    for (var group : SlotGroupLoader.getGroups(ctx.getSource().getLevel())) {
                        LOGGER.info(group.dumpData());
                    }
                }
                case "entity_bindings" ->{
                    LOGGER.info("All given Entity Bindings registered:");

                    EntitySlotLoader.INSTANCE.getEntitySlotData(false).forEach((type, slots) -> {
                        LOGGER.info("[EntityType: {}] <-> [Slots: {}]", type, slots.keySet());
                    });
                }
                default -> throw logFailureType.create(branch);
            }

            ctx.getSource().sendSystemMessage(Component.translatable("accessories.commands.dump.success", branch));

            return 1;
        }
    );

    AccessoriesItemCommands.INSTANCE.generateTrees(root, context, environment);

    root.branch("slot", slotBranch -> {
        slotBranch
            .leaves(
                "get",
                required("entity", EntityArgument.entity(), EntityArgument::getEntity),
                required("slot", SlotArgumentType.INSTANCE),
                defaulted("scale", DoubleArgumentType.doubleArg(), 1.0),
                (ctx, entity, slot, scale) -> {
                    var container = getContainer(entity, slot);

                    var size = container.getSize();

                    ctx.getSource().sendSuccess(
                            () -> Component.translatable("accessories.commands.slot.value.get.success", Component.translatable(Accessories.translationKey("slot." + slot.replace(":", "."))), entity.getName(), size),
                            false
                    );

                    return (int)(size * scale);
                }
            )
            .branch("modifier", modiferBranch -> {
                modiferBranch
                    .leaves(
                        "clear",
                        required("entity", EntityArgument.entity(), EntityArgument::getEntity),
                        defaulted("slot", SlotArgumentType.INSTANCE, ""),
                        (ctx, entity, s) -> {
                            if (s.isBlank()) {
                                var capability = getCapability(entity);

                                capability.clearSlotModifiers();

                                ctx.getSource().sendSuccess(
                                    () -> Component.translatable(
                                        "accessories.commands.slot.modifier.clear.all.success", entity.getName()
                                    ),
                                    false
                                );
                            } else {
                                var container = getContainer(entity, s);

                                container.clearModifiers();

                                ctx.getSource().sendSuccess(
                                    () -> Component.translatable(
                                        "accessories.commands.slot.modifier.clear.container.success", s, entity.getName()
                                    ),
                                    false
                                );
                            }

                            return 1;
                        }
                    )
                    .branch(
                        required("entity", EntityArgument.entity(), EntityArgument::getEntity),
                        required("slot", SlotArgumentType.INSTANCE),
                        required("id", ResourceLocationArgument.id()),
                        branchBuilder -> {
                            branchBuilder.leaves(
                                "add",
                                required("amount", DoubleArgumentType.doubleArg()),
                                branches(List.of("add_value", "add_multiplied_base", "add_multiplied_total"), operationTypeStr -> {
                                    return Arrays.stream(AttributeModifier.Operation.values())
                                        .filter(value -> value.getSerializedName().equals(operationTypeStr))
                                        .findFirst()
                                        .orElse(null);
                                }),
                                defaulted("is_persistent", BoolArgumentType.bool(), true),
                                (ctx, entity, slot, id, amount, operation, isPersistent) -> {
                                    var container = getContainer(entity, slot);

                                    var modifier = new AttributeModifier(id, amount, operation);

                                    if (isPersistent) {
                                        container.addPersistentModifier(modifier);
                                    } else {
                                        container.addTransientModifier(modifier);
                                    }

                                    ctx.getSource().sendSystemMessage(Component.translatable("accessories.commands.slot.modifier.addition", id, slot, entity.getDisplayName()));

                                    return 1;
                                }
                            ).leaves(
                                "remove",
                                (ctx, entity, slot, id) -> {
                                    var container = getContainer(entity, slot);

                                    var doseExist = container.hasModifier(id);

                                    if(doseExist) container.removeModifier(id);

                                    var messageType = (doseExist
                                        ? "accessories.commands.slot.modifier.removed.success"
                                        : "accessories.commands.slot.modifier.removed.failure");

                                    ctx.getSource().sendSystemMessage(Component.translatable(messageType, id, slot, entity.getDisplayName()));

                                    return 1;
                                }
                            ).leaves(
                                "get",
                                defaulted("scale", DoubleArgumentType.doubleArg(), 1.0),
                                (ctx, entity, slot, id, scale) -> {
                                    var container = getContainer(entity, slot);
                                    var modifiers = container.getModifiers();
                                    var attribute = SlotAttribute.getAttributeHolder(container.slotType());

                                    if (!modifiers.containsKey(id)) {
                                        throw ERROR_NO_SUCH_MODIFIER.create(entity.getName(), getAttributeDescription(attribute), id);
                                    }

                                    double d = modifiers.get(id).amount();
                                    ctx.getSource().sendSuccess(
                                        () -> Component.translatable(
                                            "commands.attribute.modifier.value.get.success", Component.translationArg(id), getAttributeDescription(attribute), entity.getName(), d
                                        ),
                                        false
                                    );
                                    return (int)(d * scale);
                                }
                            );
                    });
            });
    });

    root.branch("enchant", enchantBranch -> {
        enchantBranch.leaves(
            required("targets", EntityArgument.entities(), EntityArgument::getEntities),
            required("enchantment", ResourceArgument.resource(context, Registries.ENCHANTMENT), ResourceArgument::getEnchantment),
            defaulted("applyDelay", IntegerArgumentType.integer(0), 1),
            (ctx, targets, enchantmentRef, level) -> {
                var source = ctx.getSource();
                var enchantment = enchantmentRef.value();

                if (level > enchantment.getMaxLevel()) throw EnchantCommandAccessor.accessories$ERROR_LEVEL_TOO_HIGH().create(level, enchantment.getMaxLevel());

                int i = 0;

                var isSingleTarget = targets.size() == 1;

                for (var entity : targets) {
                    if (entity instanceof LivingEntity livingEntity) {
                        var itemStack = livingEntity.getMainHandItem();
                        if (!itemStack.isEmpty()) {
                            if (EnchantmentHelper.isEnchantmentCompatible(EnchantmentHelper.getEnchantmentsForCrafting(itemStack).keySet(), enchantmentRef)) {
                                itemStack.enchant(enchantmentRef, level);
                                i++;
                            } else if (isSingleTarget) {
                                throw EnchantCommandAccessor.accessories$ERROR_INCOMPATIBLE().create(itemStack.getHoverName().getString());
                            }
                        } else if (isSingleTarget) {
                            throw EnchantCommandAccessor.accessories$ERROR_NO_ITEM().create(livingEntity.getName().getString());
                        }
                    } else if (isSingleTarget) {
                        throw EnchantCommandAccessor.accessories$ERROR_NOT_LIVING_ENTITY().create(entity.getName().getString());
                    }
                }

                if (i == 0) throw EnchantCommandAccessor.accessories$ERROR_NOTHING_HAPPENED().create();

                var fullname = Enchantment.getFullname(enchantmentRef, level);

                source.sendSuccess(() -> isSingleTarget
                    ? Component.translatable("commands.enchant.success.single", fullname, targets.iterator().next().getDisplayName())
                    : Component.translatable("commands.enchant.success.multiple", fullname, targets.size()), true);

                return i;
            }
        );
    });

    root.branch("components", itemComponentBranch -> {
        itemComponentBranch.leaves(
            "effect/add",
            required("effect", ResourceArgument.resource(context, Registries.MOB_EFFECT)),
            defaulted("applyDelay", IntegerArgumentType.integer(1, 1000000), null),
            defaulted("seconds", IntegerArgumentType.integer(1, 1000000), -1),
            defaulted("amplifier", IntegerArgumentType.integer(0, 255), 1),
            defaulted("hideParticles", BoolArgumentType.bool(), null),
            defaulted("hideIcon", BoolArgumentType.bool(), null),
            (ctx, effect, applyDelay, seconds, amplifier, hideParticles, hideIcon) -> {
                if (seconds == -1) {
                    if (hideParticles == null) hideParticles = true;
                }

                if (hideIcon == null) hideIcon = false;

                var effectInstance = new MobEffectInstance(effect, seconds, amplifier, false, !hideParticles, !hideIcon);

                var player = ctx.getSource().getPlayerOrException();

                player.getMainHandItem().update(
                        AccessoriesDataComponents.MOB_EFFECTS,
                        AccessoryMobEffectsComponent.EMPTY,
                        data -> applyDelay != null
                                ? data.addEffect(effectInstance, applyDelay)
                                : data.addEffect(effectInstance));

                return 1;
            }
        );

        //--

        itemComponentBranch.leaves(
            "nest",
            required("item", ItemArgument.item(context), (ctx, name) -> ItemArgument.getItem(ctx, name).createItemStack(1, false)),
            (ctx, innerStack) -> {
                var player = ctx.getSource().getPlayerOrException();

                player.getMainHandItem().update(
                        AccessoriesDataComponents.NESTED_ACCESSORIES,
                        AccessoryNestContainerContents.EMPTY,
                        data -> data.addStack(innerStack));

                ctx.getSource().sendSystemMessage(Component.translatable("accessories.commands.nest.addition"));

                return 1;
            });

        //--

        itemComponentBranch.leaves(
            "slot",
            branches("add", "remove"),
            branches("valid", "invalid"),
            required("slot", SlotArgumentType.INSTANCE),
            (ctx, operation, condition, slot) -> adjustSlotValidationOnStack(condition, Objects.equals(operation, "add"), slot, ctx)
        );

        //--

        itemComponentBranch.branch("stack-sizing", branchBuilder -> {
            branchBuilder.leaves(
                "useStackSize",
                required("value", BoolArgumentType.bool()),
                (ctx, bl) -> {
                    var player = ctx.getSource().getPlayerOrException();

                    player.getMainHandItem().update(AccessoriesDataComponents.STACK_SETTINGS,
                            AccessoryStackSettings.DEFAULT,
                            component -> component.useStackSize(bl));

                    return 1;
                    }
            ).leaves(
                required("size", IntegerArgumentType.integer()),
                (ctx, size) -> {
                    var player = ctx.getSource().getPlayerOrException();

                    player.getMainHandItem().update(AccessoriesDataComponents.STACK_SETTINGS,
                            AccessoryStackSettings.DEFAULT,
                            component -> component.sizeOverride(size));

                    return 1;
                }
            );
        });

        //--

        itemComponentBranch.branch(
            "attribute",
            required("attribute", ResourceExtendedArgument.attributes(context)),
            required("id", ResourceLocationArgument.id()),
            branchBuilder -> {
                branchBuilder.leaves(
                        "add",
                        required("amount", DoubleArgumentType.doubleArg()),
                        branches(List.of("add_value", "add_multiplied_base", "add_multiplied_total"), operationTypeStr -> {
                            return Arrays.stream(AttributeModifier.Operation.values())
                                    .filter(value -> value.getSerializedName().equals(operationTypeStr))
                                    .findFirst()
                                    .orElse(null);
                        }),
                        required("slot", SlotArgumentType.INSTANCE),
                        required("isStackable", BoolArgumentType.bool()),
                        defaulted("usedInSlotValidation", BoolArgumentType.bool(), false),
                        AccessoriesCommands::addModifier
                ).leaves(
                        "remove",
                        AccessoriesCommands::removeModifier
                ).leaves(
                        "get",
                        defaulted("scale", DoubleArgumentType.doubleArg(), 1.0),
                        AccessoriesCommands::getAttributeModifier
                );
            });
    });
}

public void addCooldown(Player player, Level level, Item item, int coolDown) {
    this.cooldowns.put(item, new CooldownInstance(coolDown));
    if (!level.isClientSide) {
        this.onCooldownStarted(player, item, coolDown);
    }
}

public void addSpecificCooldown(Player player, Level level, ItemStack itemStack, int coolDown) {
    this.cooldownsSpecific.put(keyOf(itemStack), new CooldownInstance(coolDown));
    if (!level.isClientSide) {
        this.onSpecificCooldownStarted(player, itemStack, coolDown);
    }
}

public void removeCooldown(Player player, Level level, Item item) {
    this.cooldowns.remove(item);
    if (!level.isClientSide) {
        this.onCooldownEnded(player, item);
    }
}

public void removeSpecificCooldown(Player player, Level level, ItemStack itemStack) {
    this.cooldownsSpecific.remove(keyOf(itemStack));
    if (!level.isClientSide) {
        this.onSpecificCooldownEnded(player, itemStack);
    }
}

public void removeSpecificCooldown(Player player, Level level, String string) {
    this.cooldownsSpecific.remove(string);
    if (!level.isClientSide) {
        this.onSpecificCooldownEnded(player, string);
    }
}

public boolean hasCooldown(LivingEntity entity) {
	if (this.containsKey(entity))
		if (this.get(entity) > 0)
			return true;

	return false;
}

public float getSpecificCooldownPercent(ItemStack itemStack) {
    CooldownInstance cooldownInstance = this.cooldownsSpecific.get(keyOf(itemStack));
    if (cooldownInstance != null) {
        return Mth.clamp((float) cooldownInstance.time / cooldownInstance.totalTime, 0.0F, 1.0F);
    }
    return 0.0F;
}

public int getCooldown(LivingEntity entity) {
	if (this.containsKey(entity))
		return this.get(entity);
	else {
		this.put(entity, 0);
		return 0;
	}
}

public float getCooldownPercent(Item item) {
    CooldownInstance cooldownInstance = this.cooldowns.get(item);
    if (cooldownInstance != null) {
        return Mth.clamp((float) cooldownInstance.time / cooldownInstance.totalTime, 0.0F, 1.0F);
    } else {
        return 0.0F;
    }
}

public void save(ListTag listTag) {
    cooldowns.forEach((item, cooldown) -> {
        if (isOnCooldown(item)) {
            CompoundTag compoundTag = new CompoundTag();
            compoundTag.putInt("Item", Item.getId(item));
            compoundTag.putInt("Time", cooldown.time);
            compoundTag.putInt("TotalTime", cooldown.totalTime);
            listTag.add(compoundTag);
        }
    });
}

public void load(ListTag listTag){
    if (listTag != null) {
        listTag.forEach(tag -> {
            CompoundTag compoundTag = (CompoundTag) tag;
            Item item = Item.byId(compoundTag.getInt("Item"));
            int startTime = compoundTag.getInt("Time");
            int endTime = compoundTag.getInt("TotalTime");
            cooldowns.put(item, new CooldownInstance(startTime, endTime));
        });
    }
}

public void loadSpecifics(ListTag listTag){
    if (listTag != null) {
        listTag.forEach(tag -> {
            CompoundTag compoundTag = (CompoundTag) tag;
            String key = compoundTag.getString("Key");
            int startTime = compoundTag.getInt("Time");
            int endTime = compoundTag.getInt("TotalTime");
            cooldownsSpecific.put(key, new CooldownInstance(startTime, endTime));
        });
    }
}

public static void consume(SFocusCooldownPacket packet, Supplier<NetworkEvent.Context> ctx) {
    ctx.get().enqueueWork(() -> {
        Player player = Goety.PROXY.getPlayer();
        if (player != null) {
            if (packet.duration == 0) {
                SEHelper.getFocusCoolDown(player).removeCooldown(player, player.level, packet.item);
            } else {
                SEHelper.addCooldown(player, packet.item, packet.duration);
            }
        }
    });
    ctx.get().setPacketHandled(true);
}

public static void consume(SFocusSpecificCooldownPacket packet, Supplier<NetworkEvent.Context> ctx) {
    ctx.get().enqueueWork(() -> {
        Player player = Goety.PROXY.getPlayer();
        if (player != null) {
            if (packet.duration == 0) {
                SEHelper.getFocusCoolDown(player).removeSpecificCooldown(player, player.level, packet.key);
            } else {
                SEHelper.addSpecificCooldown(player, packet.itemStack, packet.duration);
            }
        }
    });
    ctx.get().setPacketHandled(true);
}

protected boolean conjureItem(EntityPlayer caster, SpellModifiers modifiers){

	ItemStack armour;
	boolean flag = false;

	// Used this rather than getArmorInventoryList because I need to access the slot itself
	for(EntityEquipmentSlot slot : InventoryUtils.ARMOUR_SLOTS){

		if(caster.getItemStackFromSlot(slot).isEmpty() &&
				!InventoryUtils.doesPlayerHaveItem(caster, SPECTRAL_ARMOUR_MAP.get(slot))){

			armour = new ItemStack(SPECTRAL_ARMOUR_MAP.get(slot));
			IConjuredItem.setDurationMultiplier(armour, modifiers.get(WizardryItems.duration_upgrade));
			// Sets a blank "ench" tag to trick the renderer into showing the enchantment effect on the armour model
			NBTExtras.storeTagSafely(armour.getTagCompound(), "ench", new NBTTagList());
			caster.setItemStackToSlot(slot, armour);
			flag = true;
		}
	}

	return flag;
}

public static void dragonBlast(LivingEntity livingEntity, Vec3 target) {
    if (livingEntity instanceof Player player) {
        if (CuriosFinder.hasCurio(player, ModItems.RING_OF_THE_DRAGON.get())) {
            ItemStack ring = CuriosFinder.findCurio(player, ModItems.RING_OF_THE_DRAGON.get());
            if (player.level instanceof ServerLevel serverLevel) {
                if (!player.getCooldowns().isOnCooldown(ring.getItem())) {
                    float radius = 3.0F;
                    if (ring.getEnchantmentLevel(ModEnchantments.RADIUS.get()) > 0) {
                        radius += ring.getEnchantmentLevel(ModEnchantments.RADIUS.get()) * 0.5F;
                    }
                    ColorUtil colorUtil = ColorUtil.LIGHT_PURPLE;
                    serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), radius, 1), target.x, target.y + 0.25F, target.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), radius, 1), target.x, target.y + 0.25F, target.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    for (int i = 0; i < Mth.floor(radius); ++i) {
                        serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), target.x + (serverLevel.getRandom().nextGaussian() / 16.0F), target.y + 1.0F + (serverLevel.getRandom().nextGaussian() / 16.0F), target.z + (serverLevel.getRandom().nextGaussian() / 16.0F), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);
                    }
                    new SpellExplosion(serverLevel, player, serverLevel.damageSources().explosion(player, player), target.x, target.y, target.z, radius, 0.0F);
                    serverLevel.playSound(null, target.x, target.y, target.z, ModSounds.VOID_BLAST.get(), livingEntity.getSoundSource(), 1.3F, 1.0F);
                    player.getCooldowns().addCooldown(ring.getItem(), 40);
                }
            }
        }
    }
}

public InteractionResult interactAt(Player playerIn, Vec3 p_31595_, InteractionHand p_31596_) {
    ItemStack itemStack = playerIn.getItemInHand(p_31596_);
    if (itemStack.getItem() instanceof AnimationCore){
        if (SEHelper.hasResearch(playerIn, ResearchList.HAUNTING)) {
            if (ItemHelper.isFullEquipped(this)) {
                HauntedArmorServant hauntedArmorServant = new HauntedArmorServant(ModEntityType.HAUNTED_ARMOR_SERVANT.get(), playerIn.level);
                for (EquipmentSlot equipmentSlot : EquipmentSlot.values()) {
                    hauntedArmorServant.setItemSlot(equipmentSlot, this.getItemBySlot(equipmentSlot));
                    hauntedArmorServant.setGuaranteedDrop(equipmentSlot);
                }
                hauntedArmorServant.setPersistenceRequired();
                hauntedArmorServant.setTrueOwner(playerIn);
                hauntedArmorServant.moveTo(this.blockPosition(), this.getYRot(), this.getXRot());
                hauntedArmorServant.setLeftHanded(playerIn.getMainArm() == HumanoidArm.LEFT);
                if (playerIn.level.addFreshEntity(hauntedArmorServant)) {
                    this.playSound(ModSounds.SUMMON_SPELL.get());
                    this.showBreakingParticles();
                    itemStack.shrink(1);
                    this.discard();
                    return InteractionResult.SUCCESS;
                }
            }
        }
    }
    return super.interactAt(playerIn, p_31595_, p_31596_);
}

public void tick(Player player, Level level) {
    if (!this.cooldowns.isEmpty()) {
        Iterator<Map.Entry<Item, CooldownInstance>> iterator = this.cooldowns.entrySet().iterator();

        while(iterator.hasNext()) {
            Map.Entry<Item, CooldownInstance> entry = iterator.next();
            entry.getValue().decreaseTime();
            if (entry.getValue().time <= 0) {
                iterator.remove();
                if (!level.isClientSide) {
                    this.onCooldownEnded(player, entry.getKey());
                }
            }
        }
    }
    if (!this.cooldownsSpecific.isEmpty()) {
        Iterator<Map.Entry<String, CooldownInstance>> iterator = this.cooldownsSpecific.entrySet().iterator();

        while(iterator.hasNext()) {
            Map.Entry<String, CooldownInstance> entry = iterator.next();
            entry.getValue().decreaseTime();
            if (entry.getValue().time <= 0) {
                iterator.remove();
                if (!level.isClientSide) {
                    this.onSpecificCooldownEnded(player, entry.getKey());
                }
            }
        }
    }
}

public void tick() {
    super.tick();
    if (!this.level.isClientSide){
        AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (attributeinstance != null) {
            if ((this.getTarget() != null || this.isAggressive())
                    && !attributeinstance.hasModifier(SPEED_MODIFIER_HOSTILE)) {
                attributeinstance.addTransientModifier(SPEED_MODIFIER_HOSTILE);
            } else if (attributeinstance.hasModifier(SPEED_MODIFIER_HOSTILE)){
                attributeinstance.removeModifier(SPEED_MODIFIER_HOSTILE);
            }
        }
    }
    if (this.isGuarding()){
        ++this.blockTime;
        int total = MathHelper.secondsToTicks(3 + this.level.random.nextInt(3));
        if (this.blockTime > total){
            this.coolTime = total * 2;
            this.setGuarding(false);
        }
    } else {
        this.blockTime = 0;
        if (this.coolTime > 0){
            --this.coolTime;
        }
    }

    if (!this.isInLava() && !this.isInFluidType(ForgeMod.LAVA_TYPE.get())){
        this.clearFire();
    }

    if (this.breakShield > 0){
        --this.breakShield;
    }

    if (this.isEffectiveAi()) {
        if (!this.hasItemInSlot(EquipmentSlot.HEAD) && !this.hasItemInSlot(EquipmentSlot.CHEST) && !this.hasItemInSlot(EquipmentSlot.LEGS) && !this.hasItemInSlot(EquipmentSlot.FEET)) {
            this.kill();
        }
    }

    if (this.level.isClientSide) {
        for(int i = 0; i < 2; ++i) {
            this.level.addParticle(ParticleTypes.SMOKE, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
        }
    }
}

