public static void onLivingHurtEvent(LivingHurtEvent event){

	PotionEffect effect = event.getEntityLiving().getActivePotionEffect(WizardryPotions.mark_of_sacrifice);

	if(effect != null && event.getSource().isMagicDamage()){
		event.setAmount(event.getAmount() * (1 + (1 + effect.getAmplifier()) * DAMAGE_INCREASE_PER_LEVEL));
		event.getEntityLiving().removePotionEffect(WizardryPotions.mark_of_sacrifice);
	}
}

public static void onLivingSetAttackTargetEvent(LivingSetAttackTargetEvent event){
	// Mind trick
	// If the target is null already, no need to set it to null, or infinite loops will occur.
	if((event.getEntityLiving().isPotionActive(WizardryPotions.mind_trick)
			|| event.getEntityLiving().isPotionActive(WizardryPotions.fear))
			&& event.getEntityLiving() instanceof EntityLiving && event.getTarget() != null){
		((EntityLiving)event.getEntityLiving()).setAttackTarget(null);
	}
}

public static void onLivingSetAttackTargetEvent(LivingSetAttackTargetEvent event){ // Not fired for revenge-targeting
	if(event.getTarget() instanceof EntityPlayer && event.getEntityLiving() instanceof EntityLiving){
		EntityLiving possessee = getPossessee((EntityPlayer)event.getTarget());
		EntityLiving attacker = (EntityLiving)event.getEntityLiving();
		if(possessee != null && !attacker.canAttackClass(possessee.getClass())){
			((EntityLiving)event.getEntityLiving()).setAttackTarget(null); // Mobs can't target a player possessing an entity they don't normally attack
		}
	}
}

