public static void onLivingAttackEvent(LivingAttackEvent event){
	if(event.getSource() != null && event.getSource().getTrueSource() instanceof EntityLivingBase){
		// Cancels the mind trick effect if the creature takes damage
		// This has been moved to within an (event.getSource().getEntity() instanceof EntityLivingBase) check so it
		// doesn't crash the game with a ConcurrentModificationException. If you think about it, mind trick only
		// ought to be cancelled if something attacks the entity since potions, drowning, cacti etc. don't affect the
		// targeting.
		if(event.getEntityLiving().isPotionActive(WizardryPotions.mind_trick)){
			event.getEntityLiving().removePotionEffect(WizardryPotions.mind_trick);
		}
	}
}

private boolean tryToPlaceIce(World world, BlockPos pos, EntityLivingBase caster, int duration){

	if(world.getBlockState(pos.down()).isSideSolid(world, pos.down(), EnumFacing.UP) && BlockUtils.canBlockBeReplaced(world, pos)){
		if(BlockUtils.canPlaceBlock(caster, world, pos)){
			world.setBlockState(pos, WizardryBlocks.permafrost.getDefaultState());
			world.scheduleUpdate(pos.toImmutable(), WizardryBlocks.permafrost, duration);
			return true;
		}
	}

	return false;
}

public static void onBlockPlaceEvent(BlockEvent.PlaceEvent event){

	EntityLiving possessee = getPossessee(event.getPlayer());

	if(possessee instanceof EntityEnderman){
		if(((EntityEnderman)possessee).getHeldBlockState() == event.getState()){
			((EntityEnderman)possessee).setHeldBlockState(null);
		}else{
			event.setCanceled(true);
		}
	}
}

public static int getCurrentCooldown(ItemStack wand){

	if(wand.getTagCompound() == null) wand.setTagCompound(new NBTTagCompound());

	int[] cooldowns = getCooldowns(wand);

	int selectedSpell = wand.getTagCompound().getInteger(SELECTED_SPELL_KEY);

	if(selectedSpell < 0 || cooldowns.length <= selectedSpell) return 0;
	// Don't need to check if the tag compound is null since the above check is equivalent.
	return cooldowns[selectedSpell];
}

public static int getCurrentMaxCooldown(ItemStack wand){

	int[] cooldowns = getMaxCooldowns(wand);

	if(wand.getTagCompound() == null) return 0;

	int selectedSpell = wand.getTagCompound().getInteger(SELECTED_SPELL_KEY);

	if(selectedSpell < 0 || cooldowns.length <= selectedSpell) return 0;

	return cooldowns[selectedSpell];
}

