		return false;
	}
}

public ItemStack assemble(CraftingInput inv, HolderLookup.Provider registries) {
	int numberOfIngredients = 0;
	ItemStack tome = ItemStack.EMPTY;
	for (int slot = 0; slot < inv.size(); slot++) {
		ItemStack stack = inv.getItem(slot);
		if (chargingIngredient.test(stack)) {
			numberOfIngredients++;
		} else if (stack.getItem() == ModItems.ALKAHESTRY_TOME.get()) {
			tome = stack.copy();
		}
	}

	AlkahestryTomeItem.addCharge(tome, chargeToAdd * numberOfIngredients);

	return tome;
}

private static InteractionHand getActiveHandgunHand(Player player, boolean handgunInMain, boolean handgunInOff) {
	if (handgunInMain != handgunInOff) {
		return handgunInMain ? InteractionHand.MAIN_HAND : InteractionHand.OFF_HAND;
	}

	boolean mainValid = isValidTimeFrame(player, player.getMainHandItem());
	boolean offValid = isValidTimeFrame(player, player.getOffhandItem());

	if (mainValid != offValid) {
		return mainValid ? InteractionHand.MAIN_HAND : InteractionHand.OFF_HAND;
	}

	return ModItems.HANDGUN.get().getCooldown(player.getMainHandItem()) < ModItems.HANDGUN.get().getCooldown(player.getOffhandItem())
			? InteractionHand.MAIN_HAND
			: InteractionHand.OFF_HAND;
}

public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand, BlockHitResult pHit) {
    if (LichdomHelper.isLich(pPlayer)) {
        ItemStack itemStack = pPlayer.getItemInHand(pHand);
        if (itemStack.getItem() instanceof DyeItem dyeItem) {
            LichdomHelper.setLichModeColor(pPlayer, dyeItem.getDyeColor().getTextColor());
            pLevel.playSound(pPlayer, pPos.getX(), pPos.getY(), pPos.getZ(), ModSounds.CAST_SPELL.get(), pPlayer.getSoundSource(), 1.0F, 0.5F);
            return InteractionResult.SUCCESS;
        } else if (itemStack.is(Items.WATER_BUCKET) && LichdomHelper.lichModeColor(pPlayer) > -1) {
            LichdomHelper.setLichModeColor(pPlayer, -1);
            pLevel.playSound(pPlayer, pPos.getX(), pPos.getY(), pPos.getZ(), SoundEvents.BUCKET_EMPTY, pPlayer.getSoundSource(), 1.0F, 1.0F);
            pLevel.playSound(pPlayer, pPos.getX(), pPos.getY(), pPos.getZ(), ModSounds.CAST_SPELL.get(), pPlayer.getSoundSource(), 1.0F, 0.5F);
            return InteractionResult.SUCCESS;
        }
    }
    return super.use(pState, pLevel, pPos, pPlayer, pHand, pHit);
}

public void copyTags(ItemStack itemStack, BlockEntity blockEntity) {
    if (itemStack.getItem() instanceof OminousDecreeItem item) {
        if (blockEntity instanceof OminousDecreeBlockEntity decreeBlock) {
            GlobalPos globalPos = decreeBlock.getDecreePos();
            if (globalPos != null) {
                item.addBlockEntityTags(itemStack, decreeBlock.getTrueOwner(), globalPos.dimension(), globalPos.pos(), null);
            }
            OminousDecreeItem.setRange(itemStack, decreeBlock.getRange());
            OminousDecreeItem.setMode(itemStack, decreeBlock.getMode().getName());

            if (decreeBlock.getEntityType() != null) {
                OminousDecreeItem.addEntityTypeTags(itemStack, decreeBlock.getEntityType());
            }
        }
    }
}

protected void handleAttributes(float p_34340_) {
    AttributeInstance speed = this.getAttribute(Attributes.MOVEMENT_SPEED);
    AttributeInstance knockResist = this.getAttribute(Attributes.KNOCKBACK_RESISTANCE);
    if (speed != null){
        speed.addPermanentModifier(new AttributeModifier("Random spawn speed bonus", this.random.nextDouble() * 0.05D, AttributeModifier.Operation.ADDITION));
