public void addStoredCharge(ItemStack containerStack, int slot, int chargeToAdd, @Nullable ItemStack chargeStack) {
	if (slot > FIRST_SLOT) {
		return;
	}
	runOnHandler(containerStack, handler -> {
		ItemStack currentStack = handler.getStackInSlot(FIRST_SLOT);
		if (currentStack.isEmpty()) {
			if (chargeStack != null) {
				handler.setStackInSlot(slot, chargeStack);
			}
			return;
		}

		currentStack.setCount(Math.min(Config.COMMON.items.voidTear.itemLimit.get(), currentStack.getCount() + chargeToAdd));
		handler.setStackInSlot(FIRST_SLOT, currentStack);
	});
}

private static void addItemEffectsToPotionMap(String name, String[] effects) {
	getItemStackFromName(name).ifPresent(stack -> {
		PotionIngredient ingredient = new PotionIngredient(stack);
		for (String effect : effects) {
			String[] effectValues = effect.split("\\|");
			String potionName = effectValues[0];
			if (!potionName.isEmpty()) {
				short durationWeight = Short.parseShort(effectValues[1]);
				short ampWeight = Short.parseShort(effectValues[2]);
				ingredient.addEffect(potionName, durationWeight, ampWeight);
			}
		}
		if (!ingredient.getEffects().isEmpty()) {
			ingredients.add(ingredient);
		}
	});
}

default void SummonSap(LivingEntity owner, LivingEntity summonedEntity){
    if (owner != null && summonedEntity != null) {
        if (this.hasSummonDown(owner)) {
            MobEffectInstance effectinstance = owner.getEffect(GoetyEffects.SUMMON_DOWN.get());
            if (effectinstance != null) {
                summonedEntity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, EffectsUtil.infiniteEffect(), effectinstance.getAmplifier()));
                summonedEntity.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), EffectsUtil.infiniteEffect(), effectinstance.getAmplifier() + 4));
            }
            for (ItemStack itemStack : summonedEntity.getAllSlots()){
                if (itemStack.isDamageableItem()){
                    itemStack.setDamageValue(itemStack.getMaxDamage() - summonedEntity.getRandom().nextInt(1 + summonedEntity.getRandom().nextInt(Math.max(itemStack.getMaxDamage() - 3, 1))));
                }
            }
            summonedEntity.setHealth(summonedEntity.getMaxHealth() / 2.0F);
        }
    }
}

