public static boolean unlockSpecialSlot(String slot, Player player) {
	if (!slot.equals("scroll") && !slot.equals("spellstone") && !slot.equals("ring") && !slot.equals("charm"))
		throw new IllegalArgumentException("Slot type '" + slot + "' is not supported!");

	MutableBoolean success = new MutableBoolean(false);
	UUID id = slot.equals("scroll") ? SCROLL_SLOT_UUID : (slot.equals("spellstone") ? SPELLSTONE_SLOT_UUID
			: (slot.equals("ring") ? RING_SLOT_UUID : CHARM_SLOT_UUID));

	ICuriosHelper apiHelper = CuriosApi.getCuriosHelper();

	apiHelper.getCuriosHandler(player).ifPresent(handler -> handler.getStacksHandler(slot).ifPresent(stacks -> {
		Map<UUID, AttributeModifier> map = stacks.getModifiers();
		if (!stacks.getModifiers().containsKey(id)) {
			stacks.addPermanentModifier(new AttributeModifier(id, "Masterslot", 1, Operation.ADDITION));
			success.setTrue();
		}
	}));

	return success.getValue();
}

protected boolean affectEntity(World world, Vec3d origin, @Nullable EntityLivingBase caster, EntityLivingBase target, int targetCount, int ticksInUse, SpellModifiers modifiers){

	if(!MagicDamage.isEntityImmune(DamageType.POISON, target) && EntityUtils.isLiving(target)){

		DamageSource source = caster != null ? MagicDamage.causeDirectMagicDamage(caster, DamageType.POISON) : DamageSource.MAGIC;
		target.attackEntityFrom(source, getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

		int bonusAmplifier = SpellBuff.getStandardBonusAmplifier(modifiers.get(SpellModifiers.POTENCY));
		int duration = (int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
		int amplifier = (int)(getProperty(EFFECT_STRENGTH).floatValue() + bonusAmplifier);

		if(!world.isRemote){
			target.addPotionEffect(new PotionEffect(MobEffects.POISON, duration, amplifier));
			target.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, duration, amplifier));
			target.addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, duration, amplifier));
		}
	}

	return true;
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	if(!world.isRemote){
		caster.addPotionEffect(new PotionEffect(MobEffects.RESISTANCE, 10,
				getProperty(EFFECT_STRENGTH).intValue(), false, false));
	}

	if(WizardData.get(caster).getVariable(SHIELD_KEY) == null){

		EntityShield shield = new EntityShield(world, caster);

		WizardData.get(caster).setVariable(SHIELD_KEY, shield);
		if(!world.isRemote){
			world.spawnEntity(shield);
		}
	}

	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

public void update(){

	this.doNotSync = false;

	ItemStack stack = this.getStackInSlot(ContainerArcaneWorkbench.CENTRE_SLOT);

	// Decrements wand damage (increases mana) every 1.5 seconds if it has a condenser upgrade
	if(stack.getItem() instanceof IManaStoringItem && !this.world.isRemote && !((IManaStoringItem)stack.getItem()).isManaFull(stack)
			&& this.world.getTotalWorldTime() % electroblob.wizardry.constants.Constants.CONDENSER_TICK_INTERVAL == 0){
		// If the upgrade level is 0, this does nothing anyway.
		int baseAmount = WandHelper.getUpgradeLevel(stack, WizardryItems.condenser_upgrade);
		int amount = (int)(baseAmount * Wizardry.settings.condenserAmountMultiplier);
		((IManaStoringItem)stack.getItem()).rechargeMana(stack, amount);
	}

	// The server doesn't care what these are, and there's no need for them to be synced or saved.
	if(this.world.isRemote){
		timer++;
	}
}

default void pacify() {
    if (this instanceof Mob mob) {
        if (mob.getTarget() != null) {
            mob.setTarget(null);
            if (mob.getLastHurtByMob() != null){
                mob.setLastHurtByMob(null);
            }
            if (mob.getBrain() != null) {
                mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                mob.getBrain().eraseMemory(MemoryModuleType.HURT_BY);
            }
            if (mob instanceof NeutralMob neutralMob) {
                neutralMob.setPersistentAngerTarget(null);
                neutralMob.stopBeingAngry();
            }
            mob.setAggressive(false);
        }
    }
}

default void SummonDown(LivingEntity entityLiving){
    MobEffectInstance effectinstance1 = entityLiving.getEffect(GoetyEffects.SUMMON_DOWN.get());
    int i = 1;
    int s = SummonDownDuration();
    if (effectinstance1 != null) {
        i += effectinstance1.getAmplifier();
        entityLiving.removeEffectNoUpdate(GoetyEffects.SUMMON_DOWN.get());
    } else {
        --i;
    }

    i = Mth.clamp(i, 0, 4);
    if (entityLiving instanceof Player player){
        if (WandUtil.enchantedFocus(player)){
            s = Mth.floor(s * 1.5F);
        }
    }
    MobEffectInstance effectinstance = new MobEffectInstance(GoetyEffects.SUMMON_DOWN.get(), s, i, false, false, true);
    entityLiving.addEffect(effectinstance);
}

