protected void onHitEntity(EntityHitResult pResult) {
    super.onHitEntity(pResult);
    if (!this.level.isClientSide) {
        Entity entity = pResult.getEntity();
        Entity entity1 = this.getOwner();
        int flaming = this.getFiery();
        int i = 0;
        if (flaming > 0){
            i = entity.getRemainingFireTicks() + (flaming - 1);
            entity.setSecondsOnFire(5 * flaming);
        }
        boolean flag = entity.hurt(ModDamageSource.hellfire(this, entity1), this.getDamage());
        if (!flag) {
            entity.setRemainingFireTicks(i);
        }
        if (entity1 instanceof LivingEntity) {
            this.doEnchantDamageEffects((LivingEntity)entity1, entity);
        }
    }
}

public void hitEntity(Entity entity){
    Entity entity1 = this.getOwner();
    float damage = SpellConfig.PyroclastDamage.get().floatValue() * WandUtil.damageMultiply();
    damage += this.getPotency();
    if (entity.hurt(ModDamageSource.modFireball(this.getOwner(), this.level), damage)) {
        if (this.isUpgraded()) {
            if (!(entity1 != null && entity1.getType().getDescriptionId().contains("netherite_monstrosity"))) {
                if (entity instanceof LivingEntity livingEntity) {
                    livingEntity.addEffect(new MobEffectInstance(GoetyEffects.STUNNED.get(), MathHelper.secondsToTicks(2), 0, false, false));
                }
            }
        }
        if (this.getFlaming() != 0){
            entity.setSecondsOnFire(5 * this.getFlaming());
        }
    }
    if (entity1 instanceof LivingEntity) {
        this.doEnchantDamageEffects((LivingEntity)entity1, entity);
    }
}

public boolean processInteract(EntityPlayer player, EnumHand hand){

	ItemStack itemstack = player.getHeldItem(hand);

	// Allows the owner (but not other players) to dispel the spirit horse using a wand (shift-clicking, because
	// clicking mounts the horse in this case).
	if(itemstack.getItem() instanceof ISpellCastingItem && this.getOwner() == player && player.isSneaking()){
		// Prevents accidental double clicking.
		if(this.ticksExisted > 20 && dispelTimer == 0){

			this.dispelTimer++;

			this.playSound(WizardrySounds.ENTITY_SPIRIT_HORSE_VANISH, 0.7F, rand.nextFloat() * 0.4F + 1.0F);
			// This is necessary to prevent the wand's spell being cast when performing this action.
			return true;
		}
		return false;
	}

	return super.processInteract(player, hand);
}

protected boolean applyEffects(EntityLivingBase caster, SpellModifiers modifiers){

	if(!caster.getActivePotionEffects().isEmpty()){

		ItemStack milk = new ItemStack(Items.MILK_BUCKET);

		boolean flag = false;

		for(PotionEffect effect : new ArrayList<>(caster.getActivePotionEffects())){ // Get outta here, CMEs
			// The PotionEffect version (as opposed to Potion) does not call cleanup callbacks
			if(effect.isCurativeItem(milk)){
				caster.removePotionEffect(effect.getPotion());
				flag = true;
			}
		}

		return flag;
	}

	return false;
}

