	}

	return livingdata;
}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(world.canBlockSeeSky(pos.up())){

		if(!world.isRemote){
			// Temporarily disable the fire tick gamerule if player block damage is disabled
			// Bit of a hack but it works fine!
			boolean doFireTick = world.getGameRules().getBoolean("doFireTick");
			if(doFireTick && !Wizardry.settings.playerBlockDamage) world.getGameRules().setOrCreateGameRule("doFireTick", "false");

			EntityLightningBolt lightning = new EntityLightningBolt(world, pos.getX(), pos.getY(), pos.getZ(), false);
			if(caster != null) lightning.getEntityData().setUniqueId(SUMMONER_NBT_KEY, caster.getUniqueID());
			lightning.getEntityData().setFloat(DAMAGE_MODIFIER_NBT_KEY, modifiers.get(SpellModifiers.POTENCY));
			world.addWeatherEffect(lightning);

			// Reset doFireTick to true if it was true before
			if(doFireTick && !Wizardry.settings.playerBlockDamage) world.getGameRules().setOrCreateGameRule("doFireTick", "true");
		}

		return true;
	}

	return false;
}

protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse,
							  SpellModifiers modifiers){

	if(target instanceof EntityLiving && !blacklist.contains(target.getClass()) && caster instanceof EntityPlayer
			&& !isPossessing((EntityPlayer)caster)){

		EntityPlayer player = (EntityPlayer)caster;

		if(!player.isCreative() && player.getHealth() <= getProperty(CRITICAL_HEALTH).floatValue()){
			player.sendStatusMessage(new TextComponentTranslation(
					"spell." + this.getRegistryName() + ".insufficienthealth"), true);
			return false;
		}

		if(!world.isRemote){
			int duration = (int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
			if(possess(player, (EntityLiving)target, duration)){
				return true;
			}
		}
	}

	return false;
}

public VoidVaultState update(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData) {
    return switch (this) {
        case INACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.activationRange());
        case ACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
        case UNLOCKING -> {
            serverData.setStateUpdatingResumeTime(world.getGameTime() + 20L);
            yield EJECTING;
        }
        case EJECTING -> {
            if (serverData.getItemsToEject().isEmpty()) {
                serverData.finishEjecting();
                yield updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
            } else {
                float f = serverData.getEjectSoundPitchModifier();
                this.ejectItem(world, pos, serverData.getItemToEject(), f);
                sharedData.setDisplayItem(serverData.getItemToDisplay());
                boolean bl = serverData.getItemsToEject().isEmpty();
                int i = bl ? 20 : 20;
                serverData.setStateUpdatingResumeTime(world.getGameTime() + i);
                yield EJECTING;
            }
        }
    };
}

