public void necroRevive() {
    if (this.getNecroConvert() != null) {
        if (!this.level.isClientSide) {
            if (this.getIdol() == null) {
                if (this.getTrueOwner() != null) {
                    if (CuriosFinder.hasNamelessSet(this.getTrueOwner())) {
                        Mob mob = this.convertTo(this.getNecroConvert(), true);
                        if (mob instanceof ZombieRavager servant) {
                            servant.setTrueOwner(this.getTrueOwner());
                            if (this.hasSaddle()) {
                                servant.equipSaddle(false);
                            }
                            servant.updateArmor();
                            net.minecraftforge.event.ForgeEventFactory.onLivingConvert(this, servant);
                            if (!this.isSilent()) {
                                this.level.levelEvent((Player) null, 1026, this.blockPosition(), 0);
                            }
                        }
                    }
                }
            }
        }
    }
}

public boolean doHurtTarget(Entity target) {
    if (super.doHurtTarget(target)) {
        if (target instanceof LivingEntity livingEntity) {
            int i = this.getMasterOwner() instanceof Player ? 7 : 0;
            if (this.level.getDifficulty() == Difficulty.NORMAL) {
                i = 7;
