        modRavager.finalizeSpawn(p_34399_, p_34399_.getCurrentDifficultyAt(modRavager.blockPosition()), MobSpawnType.CONVERSION, (SpawnGroupData) null, (CompoundTag) null);

        if (this.hasSaddle()) {
