public boolean hurt(DamageSource source, float amount) {
    if (source.is(DamageTypeTags.IS_FALL) || source.is(DamageTypeTags.IS_DROWNING)) {
        return false;
    }

    if (source.is(DamageTypes.WITHER) || source.is(DamageTypes.WITHER_SKULL)) {
        return false;
    }

    if (source.getEntity() instanceof Mob || source.getDirectEntity() instanceof AbstractArrow){
        amount = (amount + 1.0F) / 2.0F;
    }

    if (this.hasEffect(MobEffects.INVISIBILITY) && amount >= 1.0F){
        this.removeEffect(MobEffects.INVISIBILITY);
        if (this.level instanceof ServerLevel serverLevel){
            for(int i = 0; i < 8; ++i) {
                ColorUtil colorUtil = new ColorUtil(0x3e293c);
                serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, colorUtil.red, colorUtil.green, colorUtil.blue, 0.5F);
            }
        }
    }

    return super.hurt(source, amount);
}

public boolean canUse() {
    List<SorcererSpell> spells = new ArrayList<>();
    for (SorcererSpell spell1 : SorcererSpell.values()){
        if (Sorcerer.this.getSorcererLevel() >= spell1.minLevel && Sorcerer.this.getSorcererLevel() <= spell1.maxLevel) {
            if (spell1.getSpell().conditionsMet(Sorcerer.this.level, Sorcerer.this)) {
                if (Sorcerer.this.spellCoolDown[spell1.trueId] <= 0) {
                    if (spell1.getSpell() instanceof SummonSpell && !Sorcerer.this.hasEffect(GoetyEffects.SUMMON_DOWN.get())) {
                        spells.add(spell1);
                    } else if (!(spell1.getSpell() instanceof SummonSpell)) {
                        spells.add(spell1);
                    }
                }
            }
        }
    }
    if (!spells.isEmpty()) {
        this.spell = spells.get(Sorcerer.this.random.nextInt(spells.size()));
    } else {
        this.spell = null;
    }
    if (this.spell != null && this.spell.getSpell() instanceof IChargingSpell){
        this.chargeTicks = 20;
    }
    return this.spell != null && super.canUse();
}

protected void checkAndPerformAttack(LivingEntity livingEntity, double distToEnemySqr) {
    double d0 = this.getAttackReachSqr(livingEntity);
    this.mob.getLookControl().setLookAt(livingEntity, 100.0F, 100.0F);
    if (distToEnemySqr <= d0 && this.isTimeToAttack()) {
        int i = 0;
        float angle = 2.0F;
        double radius = 2.0D;
        double extraX = this.mob.getX() + 0.8D * Math.sin((double)(-this.mob.getYRot()) * Math.PI / 180.0D) + (double)angle * Math.sin((double)(-this.mob.yHeadRot) * Math.PI / 180.0D) * Math.cos((double)(-this.mob.getXRot()) * Math.PI / 180.0D);
        double extraZ = this.mob.getZ() + 0.8D * Math.cos((double)(-this.mob.getYRot()) * Math.PI / 180.0D) + (double)angle * Math.cos((double)(-this.mob.yHeadRot) * Math.PI / 180.0D) * Math.cos((double)(-this.mob.getXRot()) * Math.PI / 180.0D);
        List<LivingEntity> list = this.mob.level.getEntitiesOfClass(LivingEntity.class, new AABB(extraX - radius, this.mob.getY(), extraZ - radius, extraX + radius, this.mob.getY() + radius, extraZ + radius));
        for (LivingEntity target : list) {
            if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target) && !MobUtil.areAllies(this.mob, target)) {
                if (this.mob.doHurtTarget(target) || target.isBlocking()) {
                    ++i;
                }
            }
        }
        if (i > 0) {
            this.mob.swing(InteractionHand.MAIN_HAND);
            this.mob.playSound(ModSounds.SWING.get(), 2.0F, 0.5F);
        }
        this.resetAttackCooldown();
    }

}

public void onEntityCollision(World world, BlockPos pos, IBlockState state, Entity entity){

	if(entity instanceof EntityLivingBase){

		if(world.getTileEntity(pos) instanceof TileEntityPlayerSave){

			TileEntityPlayerSave tileentity = (TileEntityPlayerSave)world.getTileEntity(pos);

			if(AllyDesignationSystem.isValidTarget(tileentity.getCaster(), entity)){

				DamageSource source = tileentity.getCaster() == null ? DamageSource.CACTUS
						: MagicDamage.causeDirectMagicDamage(tileentity.getCaster(), DamageType.MAGIC);

				entity.attackEntityFrom(source, Spells.snare.getProperty(Spell.DAMAGE).floatValue());

				if(!world.isRemote){
					((EntityLivingBase)entity).addPotionEffect(new PotionEffect(MobEffects.SLOWNESS,
							Spells.snare.getProperty(Spell.EFFECT_DURATION).intValue(),
							Spells.snare.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}

				if(!world.isRemote) world.destroyBlock(pos, false);
			}
		}
	}
}

private static int update(EntityPlayer player, Integer possessionTimer){

	if(possessionTimer == null) possessionTimer = 0;

	if(possessionTimer > 0){

		if(isPossessing(player) && !player.isSneaking()){

			possessionTimer--;

			if(player.world.isRemote){
				ParticleBuilder.create(Type.DARK_MAGIC, player).clr(0.1f, 0, 0.3f).spawn(player.world);
				Wizardry.proxy.loadShader(player, SHADER);
			}

		}else{
			((Possession)Spells.possession).endPossession(player);
			return 0;
		}

	}else if(isPossessing(player)){
		((Possession)Spells.possession).endPossession(player);
	}

	return possessionTimer;
}

public boolean cast(World world, double x, double y, double z, EnumFacing direction, int ticksInUse, int duration, SpellModifiers modifiers){
	// Gets a 1x1x1 bounding box corresponding to the block in front of the dispenser
	AxisAlignedBB boundingBox = new AxisAlignedBB(new BlockPos(x, y, z));
	List<EntityLivingBase> entities = world.getEntitiesWithinAABB(EntityLivingBase.class, boundingBox);

	float distance = -1;
	EntityLivingBase nearestEntity = null;
	// Finds the nearest entity within the bounding box
	for(EntityLivingBase entity : entities){
		float newDistance = (float)entity.getDistance(x, y, z);
		if(distance == -1 || newDistance < distance){
			distance = newDistance;
			nearestEntity = entity;
		}
	}

	if(nearestEntity == null) return false;

	// Only return on the server side or the client probably won't spawn particles
	if(!this.applyEffects(nearestEntity, modifiers) && !world.isRemote) return false;
	if(world.isRemote) this.spawnParticles(world, nearestEntity, modifiers);
	// This MUST be the coordinates of the actual dispenser, so we need to offset it
	this.playSound(world, x - direction.getXOffset(), y - direction.getYOffset(), z - direction.getZOffset(), ticksInUse, duration, modifiers);

	return true;
}

private void doEntityShearableCheck(ItemStack stack, Player player, Vec3 lookVector) {
	if (player.level().isClientSide) {
		return;
	}
	double lowerX = Math.min(player.getX(), player.getX() + lookVector.x * 10D);
	double lowerY = Math.min(player.getY() + player.getEyeHeight(), player.getY() + player.getEyeHeight() + lookVector.y * 10D);
	double lowerZ = Math.min(player.getZ(), player.getZ() + lookVector.z * 10D);
	double upperX = Math.max(player.getX(), player.getX() + lookVector.x * 10D);
	double upperY = Math.max(player.getY() + player.getEyeHeight(), player.getY() + player.getEyeHeight() + lookVector.y * 10D);
	double upperZ = Math.max(player.getZ(), player.getZ() + lookVector.z * 10D);
	List<Mob> eList = player.level().getEntitiesOfClass(Mob.class, new AABB(lowerX, lowerY, lowerZ, upperX, upperY, upperZ));
	RandomSource rand = player.level().random;
	for (Mob e : eList) {
		int distance = (int) player.distanceTo(e);
		int probabilityFactor = (distance - 3) / 2;
		if (probabilityFactor > 0 && player.level().random.nextInt(probabilityFactor) != 0) {
			continue;
		}
		if (!e.is(player)) {
			e.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 120, 1));
		}
		if (e instanceof IShearable) {
			shearEntity(stack, player, rand, e);
		}
	}
}

public void performRangedAttack(LivingEntity target, float distanceFactor) {
    if (!this.isUndeadClone()) {
        ItemStack itemstack = this.getProjectile(this.getItemInHand(ProjectileUtil.getWeaponHoldingHand(this, item -> item instanceof BowItem)));
        AbstractArrow abstractarrowentity = this.getMobArrow(itemstack, distanceFactor);
        abstractarrowentity = ((BowItem) this.getMainHandItem().getItem()).customArrow(abstractarrowentity);
        double d0 = target.getX() - this.getX();
        double d1 = target.getY(0.3333333333333333D) - abstractarrowentity.getY();
        double d2 = target.getZ() - this.getZ();
        double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
        abstractarrowentity.shoot(d0, d1 + d3 * (double) 0.2F, d2, 1.6F, (float) (14 - this.level.getDifficulty().getId() * 4));
        this.playSound(SoundEvents.ARROW_SHOOT, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
        this.level.addFreshEntity(abstractarrowentity);
    } else {
        double d3 = target.getX() - this.getX();
        double d4 = (target.getY() + 0.5F) - (this.getY() + 0.5F);
        double d5 = target.getZ() - this.getZ();
        NecroBolt soulBolt = new NecroBolt(this, d3, d4, d5, this.level);
        soulBolt.setPos(this.getX(), this.getEyeY() - 0.2F, this.getZ());
        soulBolt.setOwner(this);
        if (this.level.addFreshEntity(soulBolt)) {
            SoundUtil.playNecroBoltIllusion(this);
            this.setShot(true);
        }
        this.swing(InteractionHand.MAIN_HAND);
    }
}

public void tick() {
    if (this.target == null){
        return;
    }

    this.ticksUntilNextAttack = Math.max(this.ticksUntilNextAttack - 1, 0);

    if (this.ticksUntilNextAttack == 0) {
        MobUtil.instaLook(this.whisperer, this.target);

        this.whisperer.getNavigation().stop();

        if (this.whisperer.getCurrentAnimation() != this.whisperer.getAnimationState(ATTACK)) {
            this.whisperer.setAnimationState(ATTACK);
            this.whisperer.playSound(this.whisperer.getAttackSound(), this.whisperer.getSoundVolume(), this.whisperer.getVoicePitch());
        }

        if (this.whisperer.attackTick == 14) {
            if (this.target.distanceTo(this.whisperer) < 2.5F) {
                this.resetAttackCooldown();
                this.whisperer.swing(InteractionHand.MAIN_HAND);
                this.whisperer.doHurtTarget(this.target);
            }
        }
    }
}

public void tick() {
    if (this.windCaller.getTarget() == null) {
        this.stop();
        return;
    }

    if (this.windCaller.distanceTo(this.windCaller.getTarget()) <= 13.0D || this.attack) {
        if (!this.attack) {
            this.windCaller.setAnimationState(UPDRAFT);
            this.windCaller.playSound(ModSounds.WIND_CALLER_UPDRAFT.get(), 1.2F, 1.0F);
            this.attack = true;
        }

        if (this.spellTick >= MathHelper.secondsToTicks(0.85F)){
            if (!this.attack2){
                new UpdraftSpell().mobSpellResult(this.windCaller, this.windCaller.staff);
                this.attack2 = true;
            }
        }
        MobUtil.instaLook(this.windCaller, this.windCaller.getTarget());
        this.windCaller.getNavigation().stop();
        ++this.spellTick;
    } else {
        this.windCaller.getNavigation().moveTo(this.windCaller.getTarget(), 1.1D);
    }
}

public void tick() {
    super.tick();
    if (!this.level.isClientSide) {
        AttributeInstance modifiableattributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (this.getCurrentAnimation() == this.getAnimationState(ATTACK)){
            this.getNavigation().stop();
            if (modifiableattributeinstance != null) {
                if (this.getAttribute(Attributes.MOVEMENT_SPEED) != null) {
                    modifiableattributeinstance.removeModifier(STOP_MODIFIER);
                    modifiableattributeinstance.addTransientModifier(STOP_MODIFIER);
                }
            }
        } else {
            if (modifiableattributeinstance != null) {
                if (modifiableattributeinstance.hasModifier(STOP_MODIFIER)) {
                    modifiableattributeinstance.removeModifier(STOP_MODIFIER);
                }
            }
        }
        if (this.attackAnim > 0) {
            --this.attackAnim;
        } else {
            this.setAnimationState("");
        }
    }
}

