private void spawnDecoy(World world, EntityLivingBase caster, SpellModifiers modifiers, double splitSpeed){

	if(!world.isRemote){
		EntityDecoy decoy = new EntityDecoy(world);
		decoy.setCaster(caster);
		decoy.setLifetime(getProperty(DECOY_LIFETIME).intValue());
		decoy.setLocationAndAngles(caster.posX, caster.posY, caster.posZ, caster.rotationYaw, caster.rotationPitch);
		decoy.addVelocity(-caster.getLookVec().z * splitSpeed, 0, caster.getLookVec().x * splitSpeed);
		// Ignores the show names setting, since this would allow a player to easily detect a decoy
		// Instead, a decoy player has its caster's name tag shown permanently and non-player decoys have nothing
		if(caster instanceof EntityPlayer) decoy.setCustomNameTag(caster.getName());
		world.spawnEntity(decoy);

		// Tricks any mobs that are targeting the caster into targeting the decoy instead.
		for(EntityLiving creature : EntityUtils.getEntitiesWithinRadius(16, caster.posX, caster.posY,
				caster.posZ, world, EntityLiving.class)){
			// More likely to trick mobs the higher the damage multiplier
			// The default base value is 0.5, so modifiers of 2 or more will guarantee mobs are tricked
			if(creature.getAttackTarget() == caster && world.rand.nextFloat()
					< getProperty(MOB_TRICK_CHANCE).floatValue() * modifiers.get(SpellModifiers.POTENCY)){
				creature.setAttackTarget(decoy);
			}
		}
	}

	caster.addVelocity(caster.getLookVec().z * splitSpeed, 0, -caster.getLookVec().x * splitSpeed);
}

protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(EntityUtils.isLiving(target)){

		if(target instanceof EntityBlaze || target instanceof EntityMagmaCube){
			target.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.FROST),
					getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));
		}

		if(MagicDamage.isEntityImmune(DamageType.FROST, target)){
			if(!world.isRemote && caster instanceof EntityPlayer) ((EntityPlayer)caster).sendStatusMessage(
					new TextComponentTranslation("spell.resist", target.getName(), this.getNameForTranslationFormatted()), true);
		}else{
			if(!world.isRemote){
				((EntityLivingBase)target).addPotionEffect(new PotionEffect(WizardryPotions.frost,
						(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade)),
						getProperty(EFFECT_STRENGTH).intValue()));
			}
		}

		if(target.isBurning()) target.extinguish();

		return true;
	}

	return false; // If the spell hit a non-living entity
}

default void pacifySurroundingMobs(double range) {
    if (this instanceof LivingEntity owned) {
        for (Mob mob : owned.level.getEntitiesOfClass(Mob.class, owned.getBoundingBox().inflate(range), mob -> !MobUtil.areAllies(mob, owned))) {
            mob.setTarget(null);
            mob.setLastHurtByMob(null);
            Brain<?> brain = mob.getBrain();
            if (brain.hasMemoryValue(MemoryModuleType.ATTACK_TARGET)) {
                Optional<?> memory = brain.getMemory(MemoryModuleType.ATTACK_TARGET);
                if (memory.isPresent() && memory.get() == owned) {
                    brain.eraseMemory(MemoryModuleType.ATTACK_TARGET);
                }
            }
            if (brain.hasMemoryValue(MemoryModuleType.ANGRY_AT)) {
                Optional<?> memory = brain.getMemory(MemoryModuleType.ANGRY_AT);
                if (memory.isPresent() && memory.get() == owned.getUUID()) {
                    brain.eraseMemory(MemoryModuleType.ANGRY_AT);
                }
            }
            if (brain.hasMemoryValue(MemoryModuleType.HURT_BY_ENTITY)) {
                Optional<?> memory = brain.getMemory(MemoryModuleType.HURT_BY_ENTITY);
                if (memory.isPresent() && memory.get() == owned) {
                    brain.eraseMemory(MemoryModuleType.HURT_BY_ENTITY);
                }
            }
        }
    }
}

default void stayingMode(){
    if (this instanceof Mob owned) {
        AttributeInstance modifiableattributeinstance = owned.getAttribute(Attributes.MOVEMENT_SPEED);
        if (modifiableattributeinstance != null) {
            boolean isRidden = owned.getControllingPassenger() instanceof IServant servant && servant.isStaying();
            if (this.isStaying() || isRidden || this.altStaying()) {
                if (owned.getNavigation().getPath() != null) {
                    owned.getNavigation().stop();
                }
                if (owned.getAttribute(Attributes.MOVEMENT_SPEED) != null) {
                    modifiableattributeinstance.removeModifier(SPEED_MODIFIER);
                    modifiableattributeinstance.addTransientModifier(SPEED_MODIFIER);
                }
                this.stayingPosition();
                if (!isRidden) {
                    if (this.isWandering()) {
                        this.setWandering(false);
                    }
                }
            } else {
                if (modifiableattributeinstance.hasModifier(SPEED_MODIFIER)) {
                    modifiableattributeinstance.removeModifier(SPEED_MODIFIER);
                }
            }
        }
    }
}

protected void tickDeath() {
    ++this.deathTime;
    if (this.deathTime == 40) {
        if (this.getTrueOwner() != null && MobsConfig.BlackBeastHowlingSoul.get()){
            ItemStack itemStack = new ItemStack(ModItems.HOWLING_SOUL.get());
            HowlingSoul.setOwnerName(this.getTrueOwner(), itemStack);
            HowlingSoul.setSummon(this, itemStack);
            FlyingItem flyingItem = new FlyingItem(ModEntityType.FLYING_ITEM.get(), this.level, this.getX(), this.getY(), this.getZ());
            flyingItem.setOwner(this.getTrueOwner());
            flyingItem.setItem(itemStack);
            flyingItem.setParticle(ModParticleTypes.TOTEM_EFFECT.get());
            flyingItem.setSecondsCool(ItemConfig.ReviveSecondsCool.get());
            this.level.addFreshEntity(flyingItem);
        }
        this.remove(RemovalReason.KILLED);
        this.dropExperience();
    }
    if (this.level instanceof ServerLevel serverLevel){
        double d0 = this.random.nextGaussian() * 0.02D;
        double d1 = this.random.nextGaussian() * 0.02D;
        double d2 = this.random.nextGaussian() * 0.02D;
        serverLevel.sendParticles(ModParticleTypes.WRAITH.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
        serverLevel.sendParticles(ModParticleTypes.WRAITH_BURST.get(), this.getRandomX(1.0D), this.getY(), this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
    }
    this.setYRot(this.deathRotation);
    this.setYBodyRot(this.deathRotation);
}

public void mobSense() {
    if (MobsConfig.MobSense.get()) {
        if (this.isAlive()) {
            if (this.getTarget() != null) {
                if (!this.isInvisible()) {
                    if (this.invisibleCool > 0) {
                        super.mobSense();
                    } else {
                        this.addEffect(new MobEffectInstance(MobEffects.INVISIBILITY, MathHelper.secondsToTicks(30), 0, false, false));
                        this.invisibleCool = MathHelper.secondsToTicks(30);
                        if (this.level instanceof ServerLevel serverLevel) {
                            for (int i = 0; i < 8; ++i) {
                                ColorUtil colorUtil = new ColorUtil(0x3e293c);
                                serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, colorUtil.red, colorUtil.green, colorUtil.blue, 0.5F);
