                serverLevel.sendParticles(new SculkChargeParticleOptions(0.0F), (double) blockPos.getX() + 0.5D, (double) blockPos.getY(), (double) blockPos.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
