public static void spawnPathPaticles(World world, Path path, float durationMultiplier){

	// A bit annoying that we have to use the reference here but there's no easy way around it
	float duration = Spells.clairvoyance.getProperty(DURATION).floatValue();

	PathPoint point, nextPoint;

	while(!path.isFinished()){

		point = path.getPathPointFromIndex(path.getCurrentPathIndex());
		if(point == path.getFinalPathPoint()) break;
		nextPoint = path.getCurrentPathLength() - path.getCurrentPathIndex() <= 2 ? path.getFinalPathPoint()
				: path.getPathPointFromIndex(path.getCurrentPathIndex() + 2);

		ParticleBuilder.create(Type.PATH).pos(point.x + 0.5, point.y + 0.5, point.z + 0.5).vel(
				(nextPoint.x - point.x) / (float)PARTICLE_MOVEMENT_INTERVAL,
				(nextPoint.y - point.y) / (float)PARTICLE_MOVEMENT_INTERVAL,
				(nextPoint.z - point.z) / (float)PARTICLE_MOVEMENT_INTERVAL)
		.time((int)(duration * durationMultiplier)).clr(0, 1, 0.3f).spawn(world);

		path.incrementPathIndex();
		path.incrementPathIndex();
	}

	point = path.getFinalPathPoint();

	ParticleBuilder.create(Type.PATH).pos(point.x + 0.5, point.y + 0.5, point.z + 0.5)
	.time((int)(duration * durationMultiplier)).clr(1f, 1f, 1f).spawn(world);
}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	boolean flag = false;

	pos = pos.offset(side);

	int blastUpgradeCount = (int)((modifiers.get(WizardryItems.blast_upgrade) - 1) / Constants.RANGE_INCREASE_PER_LEVEL + 0.5f);

	float radius = getProperty(EFFECT_RADIUS).floatValue() + 0.73f * blastUpgradeCount;

	List<BlockPos> sphere = BlockUtils.getBlockSphere(pos, radius * modifiers.get(WizardryItems.blast_upgrade));

	for(BlockPos pos1 : sphere){

		if(world.isAirBlock(pos1)){
			if(!world.isRemote){
				world.setBlockState(pos1, WizardryBlocks.vanishing_cobweb.getDefaultState());
				if(world.getTileEntity(pos1) instanceof TileEntityTimer){
					((TileEntityTimer)world.getTileEntity(pos1))
							.setLifetime((int)(getProperty(DURATION).doubleValue()
									* modifiers.get(WizardryItems.duration_upgrade)));
				}
			}
			flag = true;
		}
	}

	return flag;
}

private void burnNearbyBlocks(World world, Vec3d origin, @Nullable EntityLivingBase caster, SpellModifiers modifiers){

	if(!world.isRemote && EntityUtils.canDamageBlocks(caster, world)){

		double radius = getProperty(EFFECT_RADIUS).floatValue() * modifiers.get(WizardryItems.blast_upgrade);

		for(int i = -(int)radius; i <= (int)radius; i++){
			for(int j = -(int)radius; j <= (int)radius; j++){

				BlockPos pos = new BlockPos(origin).add(i, 0, j);

				Integer y = BlockUtils.getNearestSurface(world, new BlockPos(pos), EnumFacing.UP, (int)radius, true, SurfaceCriteria.NOT_AIR_TO_AIR);

				if(y != null){

					pos = new BlockPos(pos.getX(), y, pos.getZ());

					double dist = origin.distanceTo(new Vec3d(origin.x + i, y, origin.z + j));

					// Randomised with weighting so that the nearer the block the more likely it is to be set alight.
					if(y != -1 && world.rand.nextInt((int)(dist * 2) + 1) < radius && dist < radius && dist > 1.5
							&& BlockUtils.canPlaceBlock(caster, world, pos)){
						world.setBlockState(pos, Blocks.FIRE.getDefaultState());
					}
				}
			}
		}
	}
}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	boolean flag = false;

	if(!world.isRemote){

		int blastUpgradeCount = (int)((modifiers.get(WizardryItems.blast_upgrade) - 1) / Constants.BLAST_RADIUS_INCREASE_PER_LEVEL + 0.5f);
		// Results in the following patterns:
		// 0 blast upgrades: single block
		// 1 blast upgrade: 3x3 without corners or edges
		// 2 blast upgrades: 3x3 with corners
		// 3 blast upgrades: 5x5 without corners or edges
		float radius = 0.5f + 0.73f * blastUpgradeCount;

		int duration = (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));

		List<BlockPos> sphere = BlockUtils.getBlockSphere(pos.up(), radius);

		for(BlockPos pos1 : sphere){
			flag |= tryToPlaceIce(world, pos1, caster, duration);
		}

		return flag;

	}

	return true;

}

public static void setCurrentCooldown(ItemStack wand, int cooldown){

	if(wand.getTagCompound() == null) wand.setTagCompound((new NBTTagCompound()));

	int[] cooldowns = getCooldowns(wand);

	int selectedSpell = wand.getTagCompound().getInteger(SELECTED_SPELL_KEY);
	int spellCount = getSpells(wand).length;

	if(spellCount <= selectedSpell) return; // Probably shouldn't happen

	// The length of the spells array must be greater than 0 since this method can only be called if a spell is
	// cast, which is impossible if there are no spells.
	if(cooldowns.length <= selectedSpell) cooldowns = new int[spellCount];

	if(cooldown <= 0) cooldown = 1;

	cooldowns[selectedSpell] = cooldown;

	setCooldowns(wand, cooldowns);

	int[] maxCooldowns = getMaxCooldowns(wand);

	if(maxCooldowns.length <= selectedSpell) maxCooldowns = new int[spellCount];

	maxCooldowns[selectedSpell] = cooldown;

	setMaxCooldowns(wand, maxCooldowns);
}

private static int resetFocusCooldown(CommandSourceStack pSource, Collection<? extends ServerPlayer> pTargets) {
    int i = 0;
    for(ServerPlayer serverPlayer : pTargets) {
        if (!WandUtil.findFocus(serverPlayer).isEmpty()){
            ItemStack itemStack = WandUtil.findFocus(serverPlayer);
            Item item = itemStack.getItem();
            if (SEHelper.getCooldowns(serverPlayer).containsKey(item)){
                SEHelper.getFocusCoolDown(serverPlayer).removeCooldown(serverPlayer, pSource.getLevel(), item);
                ++i;
            }
            if (SEHelper.getSpecificCooldowns(serverPlayer).containsKey(FocusCooldown.keyOf(itemStack))) {
                SEHelper.getFocusCoolDown(serverPlayer).removeSpecificCooldown(serverPlayer, pSource.getLevel(), itemStack);
                ++i;
            }
        }
    }

    if (i == 0){
        pSource.sendFailure(Component.translatable("commands.goety.spell.cooldown.held.failure"));
    } else {
        if (pTargets.size() == 1) {
            pSource.sendSuccess(() -> Component.translatable("commands.goety.spell.cooldown.held.success.single", WandUtil.findFocus(pTargets.iterator().next()).getDisplayName()), true);
        } else {
            pSource.sendSuccess(() -> Component.translatable("commands.goety.spell.cooldown.held.success.multiple", pTargets.size()), true);
        }
    }

    return i;
}

public boolean doHurtTarget(Entity target) {
    if (super.doHurtTarget(target)) {
        if (target instanceof LivingEntity livingEntity) {
            int amp = 0;
            int i = this.getMasterOwner() instanceof Player ? 7 : 0;
            if (this.level.getDifficulty() == Difficulty.NORMAL) {
                i = 7;
            } else if (this.level.getDifficulty() == Difficulty.HARD) {
                i = 15;
            }

            if (i > 0) {
                MobEffect effect = MobEffects.MOVEMENT_SLOWDOWN;
                if (CuriosFinder.hasFrostRobes(this.getMasterOwner())){
                    if (!target.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES)) {
                        effect = GoetyEffects.FREEZING.get();
                    } else {
                        amp += 1;
                    }
                }
                livingEntity.addEffect(new MobEffectInstance(effect, i * 20, amp), this);
            }
        }

        return true;
    } else {
        return false;
    }
}

public void tick() {
    super.tick();
    LivingEntity livingEntity = this.inquillager.getTarget();
    if (livingEntity != null) {
        ++this.bombTimer;
        if (this.bombTimer >= 60) {
            Vec3 vector3d = livingEntity.getDeltaMovement();
            double d0 = livingEntity.getX() + vector3d.x - this.inquillager.getX();
            double d1 = livingEntity.getEyeY() - (double) 1.1F - this.inquillager.getY();
            double d2 = livingEntity.getZ() + vector3d.z - this.inquillager.getZ();
            float f = Mth.sqrt((float) (d0 * d0 + d2 * d2));
            Potion potion;
            if (livingEntity.isInvertedHealAndHarm()) {
                potion = Potions.HEALING;
            } else {
                potion = Potions.HARMING;
            }
            ThrownPotion potionentity = new ThrownPotion(this.inquillager.level, this.inquillager);
            potionentity.setItem(PotionUtils.setPotion(new ItemStack(Items.SPLASH_POTION), potion));
            potionentity.setXRot(potionentity.getXRot() - -20.0F);
            potionentity.shoot(d0, d1 + (double) (f * 0.2F), d2, 0.75F, 8.0F);
            if (!this.inquillager.isSilent()) {
                this.inquillager.level.playSound((Player) null, this.inquillager.getX(), this.inquillager.getY(), this.inquillager.getZ(), SoundEvents.WITCH_THROW, this.inquillager.getSoundSource(), 1.0F, 0.8F + this.inquillager.random.nextFloat() * 0.4F);
            }
            this.inquillager.level.addFreshEntity(potionentity);
            this.bombTimer = 0;
        }
    }
}

