public void soulJar() {
    if (this.getTrueOwner() instanceof Player player && MobsConfig.NecromancerSoulJar.get()){
        Optional<ItemStack> optional = player.getInventory().items.stream().filter(itemStack1 -> itemStack1.is(ModItems.EMPTY_SOUL_JAR.get())).findFirst();
        if (optional.isPresent()){
            ItemStack original = optional.get();
            if (original.is(ModItems.EMPTY_SOUL_JAR.get())){
                if (!player.isCreative()){
                    original.shrink(1);
                }
                ItemStack itemStack = new ItemStack(ModItems.SOUL_JAR.get());
                SoulJar.setOwnerName(this.getTrueOwner(), itemStack);
                SoulJar.setSummon(this, itemStack);
                if (this instanceof AbstractCairnNecromancer){
                    SoulJar.setCairn(itemStack);
                } else if (this instanceof AbstractMossyNecromancer){
                    SoulJar.setMossy(itemStack);
                } else if (this instanceof DrownedNecromancer){
                    SoulJar.setDrowned(itemStack);
                } else if (this instanceof AbstractWitherNecromancer){
                    SoulJar.setWither(itemStack);
                }
                SEHelper.addSpecificCooldown(player, itemStack, MathHelper.secondsToTicks(ItemConfig.ReviveSecondsCool.get()));
                if (!player.getInventory().add(itemStack)) {
                    player.drop(itemStack, false, true);
                }
            }
        }
    }
}

public void uncreditedKill(LivingEntity target) {
    if (!MobUtil.areAllies(this, target)) {
        int total = this.level.getEntitiesOfClass(CarrionMaggot.class, this.getBoundingBox().inflate(16.0F), maggot -> MobUtil.areAllies(this, maggot)).size();
        if (total < SpellConfig.CarrionLimit.get()) {
            int random = this.getRandom().nextIntBetweenInclusive(1, 3);
            if (target.getMaxHealth() < 20.0F) {
                random = 1;
            }
            for (int i = 0; i < random; ++i) {
                CarrionMaggot carrionMaggot = new CarrionMaggot(ModEntityType.CARRION_MAGGOT.get(), this.level);
                carrionMaggot.setTrueOwner(this.getTrueOwner() != null ? this.getTrueOwner() : this);
                BlockPos blockPos = BlockFinder.SummonRadius(target.blockPosition(), carrionMaggot, this.level, 3);
                carrionMaggot.moveTo(blockPos.getCenter());
                if (this.level instanceof ServerLevel serverLevel) {
                    carrionMaggot.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(carrionMaggot.blockPosition()), MobSpawnType.BREEDING, null, null);
                }
                carrionMaggot.setNatural(this.isNatural());
                carrionMaggot.setHostile(this.isHostile());
                carrionMaggot.setUpgraded(this.isUpgraded());
                carrionMaggot.copyStance(this);
                EffectsUtil.copyEffects(this, carrionMaggot);
                if (this.isLimitedLife()) {
                    carrionMaggot.setLimitedLife(this.getLifespan());
                }
                this.level.addFreshEntity(carrionMaggot);
            }
        }
    }
}

private void updateImbuedItem(ItemStack stack, Set<Imbuement> activeImbuements){

	if(stack.isItemEnchanted()){

		NBTTagList enchantmentList = stack.getItem() == Items.ENCHANTED_BOOK ?
				ItemEnchantedBook.getEnchantments(stack) : stack.getEnchantmentTagList();

		Iterator<NBTBase> iterator = enchantmentList.iterator();
		// For each of the item's enchantments
		while(iterator.hasNext()){
			NBTTagCompound enchantmentTag = (NBTTagCompound) iterator.next();
			Enchantment enchantment = Enchantment.getEnchantmentByID(enchantmentTag.getShort("id"));
			// Ignores the enchantment unless it is an imbuement
			if(enchantment instanceof Imbuement){
				int duration = this.getImbuementDuration(enchantment);
				// If the imbuement is still active:
				if(duration > 0){
					// Decrements the timer
					this.imbuementDurations.put((Imbuement)enchantment, duration - IMBUEMENT_UPDATE_INTERVAL);
					// Adds this imbuement to the set of imbuements that need to be kept
					activeImbuements.add((Imbuement)enchantment);
				}else{
					// Otherwise, removes the enchantment from the item
					((Imbuement) enchantment).onImbuementRemoval(stack);
					iterator.remove(); // FIXME: Apparently this can cause a CME
				}
			}
		}
	}
}

public static boolean runAway(EntityCreature target, EntityLivingBase caster, double distance){

	if(target.getDistance(caster) < distance){

		Vec3d Vec3d = RandomPositionGenerator.findRandomTargetBlockAwayFrom(target, (int)distance, (int)(distance/2),
				new Vec3d(caster.posX, caster.posY, caster.posZ));

		if(Vec3d == null){
			return false;

		}else{
			// In both cases it is necessary to check if the entity already has a path so it doesn't change
			// direction every tick, unless that path is towards the caster.
			// Path path = target.getNavigator().getPathToXYZ(Vec3d.xCoord, Vec3d.yCoord, Vec3d.zCoord);

			boolean flag = true;

			if(!target.getNavigator().noPath()){
				PathPoint point = target.getNavigator().getPath().getFinalPathPoint();
				if(point != null) flag = caster.getDistance(point.x, point.y, point.z) < distance;
			}
			// Has a built in mind trick effect because for whatever reason this makes it work with skeletons.
			target.setAttackTarget(null);

			if(flag) return target.getNavigator().tryMoveToXYZ(Vec3d.x, Vec3d.y, Vec3d.z, 1.25);// target.getEntityAttribute(SharedMonsterAttributes.movementSpeed).getAttributeValue());
		}
	}

	return false;
}

public static boolean findMindControlTarget(EntityLiving target, EntityLivingBase caster, World world){

	// As of 1.1, this now uses the creature's follow range, like normal targeting. It also
	// no longer lasts until the creature dies; instead it is a potion effect which continues to
	// set the target until it wears off.
	List<EntityLivingBase> possibleTargets = EntityUtils.getLivingWithinRadius(
			target.getEntityAttribute(SharedMonsterAttributes.FOLLOW_RANGE).getAttributeValue(),
			target.posX, target.posY, target.posZ, world);

	possibleTargets.remove(target);
	possibleTargets.remove(target.getRidingEntity());
	possibleTargets.removeIf(e -> e instanceof EntityArmorStand);

	EntityLivingBase newAITarget = null;

	for(EntityLivingBase possibleTarget : possibleTargets){
		if(AllyDesignationSystem.isValidTarget(caster, possibleTarget) && (newAITarget == null
				|| target.getDistance(possibleTarget) < target.getDistance(newAITarget))){
			newAITarget = possibleTarget;
		}
	}

	if(newAITarget != null){
		target.setAttackTarget(newAITarget);
		return true;
	}

	return false;

}

public void tick() {
    super.tick();
    LivingEntity target = this.enchanter.getTarget();

    boolean flag = this.meleeTick > 0;
    if (target != null && target.isAlive()) {
        flag |= this.enchanter.isWithinMeleeAttackRange(target);
        if (!this.enchanter.isWithinMeleeAttackRange(target)) {
            this.enchanter.getNavigation().moveTo(target, 1.0D);
        }
    }
    if (flag) {
        if (target != null && !target.isDeadOrDying()) {
            MobUtil.instaLook(this.enchanter, target);
        }
        if (!this.enchanter.isCurrentAnimation(IEnchanter.ATTACK)) {
            this.enchanter.setAnimationState(IEnchanter.ATTACK);
        }
        ++this.meleeTick;
        if (this.meleeTick == 11) {
            this.enchanter.playSound(ModSounds.ENCHANTER_ATTACK.get());
            this.enchanter.playSound(ModSounds.BOOK_CLOSE.get());
            if (target != null && !target.isDeadOrDying() && (this.enchanter.isWithinMeleeAttackRange(target) || this.enchanter.getBoundingBox().inflate(1.0D).intersects(target.getBoundingBox()))) {
                this.enchanter.doHurtTarget(target);
            }
        }
        this.enchanter.getNavigation().stop();
        this.enchanter.getMoveControl().strafe(0, 0);
    }
}

