protected void performSpellCasting() {
    if (Minister.this.getTarget() != null) {
        BlockPos blockPos = Minister.this.getTarget().blockPosition();
        if (Minister.this.getTarget().distanceTo(Minister.this) <= 4.0F){
            this.surroundTeeth();
        } else {
            for (int length = 0; length < 16; length++) {
                blockPos = blockPos.offset(Minister.this.getRandom().nextInt(-4, 4), 0, Minister.this.getRandom().nextInt(-4, 4));
                BlockPos.MutableBlockPos blockpos$mutable = new BlockPos.MutableBlockPos(blockPos.getX(), blockPos.getY(), blockPos.getZ());

                while(blockpos$mutable.getY() < blockPos.getY() + 8.0D && !Minister.this.level.getBlockState(blockpos$mutable).blocksMotion()) {
                    blockpos$mutable.move(Direction.UP);
                }

                if (Minister.this.level.noCollision(new AABB(blockpos$mutable))){
                    ++this.teethAmount;
                    ViciousTooth viciousTooth = new ViciousTooth(ModEntityType.VICIOUS_TOOTH.get(), Minister.this.level);
                    viciousTooth.setPos(Vec3.atCenterOf(blockpos$mutable));
                    viciousTooth.setOwner(Minister.this);
                    if (Minister.this.level.addFreshEntity(viciousTooth)) {
                        viciousTooth.playSound(ModSounds.TOOTH_SPAWN.get());
                    }
                }
            }
        }
        if (this.teethAmount <= 0){
            this.surroundTeeth();
        }
    }
}

protected void onHitEntity(EntityHitResult pResult) {
    super.onHitEntity(pResult);
    Entity target = pResult.getEntity();
    Entity owner = this.getOwner();
    LivingEntity livingentity = owner instanceof LivingEntity ? (LivingEntity)owner : null;
    float damage = SpellConfig.MagicBoltDamage.get().floatValue() * WandUtil.damageMultiply();
    boolean flag;
    if (livingentity != null) {
        if (livingentity instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null){
            damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
        }
        damage += this.getExtraDamage();
        flag = target.hurt(ModDamageSource.magicBolt(this, livingentity), damage);
        if (flag) {
            this.doEnchantDamageEffects(livingentity, target);
        }
    } else {
        flag = target.hurt(ModDamageSource.magicBolt(this, this), 4.0F);
    }

    int duration = 100;
    if (flag){
        if (target instanceof LivingEntity livingTarget){
            if (livingentity != null) {
                duration *= this.getExtraDuration() + 1;
            }
            livingTarget.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), duration));
        }
    }
}

public static void voidedEffect(Level pLevel, LivingEntity pEntity) {
    if (!CuriosFinder.hasVoidRobe(pEntity)
            && !pEntity.getType().is(ModTags.EntityTypes.VOID_TOUCHED_IMMUNE)) {
        if (pEntity.canBeAffected(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get()))) {
            if (!pLevel.isClientSide) {
                MobEffectInstance instance = pEntity.getEffect(GoetyEffects.VOID_TOUCHED.get());
                float damage = pEntity.getMaxHealth() * 0.05F;
                boolean flag = pEntity.getType().is(Tags.EntityTypes.BOSSES) || pEntity.getType().is(ModTags.EntityTypes.MINI_BOSSES) || pEntity.getMaxHealth() >= 200.0D;
                if (flag) {
                    damage = 1.0F;
                }
                if (instance == null) {
                    if (pEntity.hurt(ModDamageSource.getDamageSource(pLevel, ModDamageSource.VOIDED), damage)) {
                        pEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(3), flag ? 0 : 2, false, true));
                    }
                } else {
                    if (pEntity.tickCount % 20 == 0) {
                        if (pEntity.hurt(ModDamageSource.getDamageSource(pLevel, ModDamageSource.VOIDED), damage)) {
                            if (!flag) {
                                EffectsUtil.increaseEffect(pEntity, GoetyEffects.VOID_TOUCHED.get(), 9, false, true);
                            } else {
                                pEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(3), 0, false, true));
                            }
                        }
                    }
                }
            }
        }
    }
}

