public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	WizardData data = WizardData.get(caster);

	if(!world.isRemote){

		Entity oldWolf = EntityUtils.getEntityByUUID(world, data.getVariable(UUID_KEY));

		if(oldWolf != null) oldWolf.setDead();

		BlockPos pos = BlockUtils.findNearbyFloorSpace(caster, 2, 4);
		if(pos == null) return false;

		EntitySpiritWolf wolf = new EntitySpiritWolf(world);
		wolf.setPosition(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5);
		wolf.setTamed(true);
		wolf.setOwnerId(caster.getUniqueID());
		// Potency gives the wolf more strength AND more health
		wolf.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).applyModifier(
				new AttributeModifier(POTENCY_ATTRIBUTE_MODIFIER, modifiers.get(SpellModifiers.POTENCY) - 1, EntityUtils.Operations.MULTIPLY_CUMULATIVE));
		wolf.getEntityAttribute(SharedMonsterAttributes.MAX_HEALTH).applyModifier(
				new AttributeModifier(POTENCY_ATTRIBUTE_MODIFIER, modifiers.amplified(SpellModifiers.POTENCY, 1.5f) - 1, EntityUtils.Operations.MULTIPLY_CUMULATIVE));
		wolf.setHealth(wolf.getMaxHealth());

		world.spawnEntity(wolf);

		data.setVariable(UUID_KEY, wolf.getUniqueID());
	}

	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;

}

protected ItemInteractionResult useItemOn(ItemStack heldItem, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand,
		BlockHitResult hitResult) {
	return level.getBlockEntity(pos, ModBlocks.APOTHECARY_MORTAR_TILE_TYPE.get()).map(mortar -> {
		// if we're in cooldown prevent player from insta inserting essence that they just got from mortar
		if (mortar.isInCooldown(level) && heldItem.getItem() == ModItems.POTION_ESSENCE.get()) {
			return ItemInteractionResult.FAIL;
		}

		ItemStack stackToAdd = heldItem.copy();
		stackToAdd.setCount(1);

		boolean putItemInSlot = InventoryHelper.executeOnItemHandlerAt(level, pos, state, mortar, itemHandler -> {
			if (InventoryHelper.insertIntoInventory(stackToAdd, itemHandler) == 1) {
				heldItem.shrink(1);
				return true;
			}
			return false;
		}, false);

		if (!putItemInSlot) {
			if (mortar.usePestle(level)) {
				level.playSound(null, pos, soundType.getStepSound(), SoundSource.BLOCKS, (soundType.getVolume() + 1.0F) / 2.0F,
						soundType.getPitch() * 0.8F);
				return ItemInteractionResult.CONSUME;
			} else {
				return ItemInteractionResult.FAIL;
			}
		} else {
			mortar.setChanged();
		}
		return ItemInteractionResult.SUCCESS;
	}).orElse(ItemInteractionResult.FAIL);
}

public void start() {
    int warmUp = MathHelper.secondsToTicks(2);
    this.spellTime = warmUp + 20;
    AbstractWitherNecromancer.this.setSpellCooldown(AbstractWitherNecromancer.this.getSpellCooldown() + 60);
    AbstractWitherNecromancer.this.playSound(ModSounds.RUMBLE.get(), 1.0F, 1.0F);
    AbstractWitherNecromancer.this.setSpellCasting(true);
    AbstractWitherNecromancer.this.setNecromancerSpellType(NecromancerSpellType.CLOUD);
    AbstractWitherNecromancer.this.setAnimationState(SPELL_ANIM);
    LivingEntity target = AbstractWitherNecromancer.this.getTarget();
    if (AbstractWitherNecromancer.this.level instanceof ServerLevel serverLevel
            && target != null && target.isAlive()) {
        int duration = 180;
        double radius = 3.0D;
        List<Vec3> vec3s = BlockFinder.buildOuterBlockCircle(target.position(), radius);
        for (Vec3 vec3 : vec3s) {
            FirePillar flames = new FirePillar(serverLevel, vec3.x, vec3.y, vec3.z);
            flames.setOwner(AbstractWitherNecromancer.this);
            flames.setDuration(duration);
            flames.setWarmUp(warmUp);
            MobUtil.moveDownToGround(flames);
            serverLevel.addFreshEntity(flames);
        }
        List<Vec3> vec32s = BlockFinder.buildOuterBlockCircle(target.position(), radius * 2.0D);
        for (Vec3 vec3 : vec32s) {
            FirePillar flames = new FirePillar(serverLevel, vec3.x, vec3.y, vec3.z);
            flames.setOwner(AbstractWitherNecromancer.this);
            flames.setDuration(duration);
            flames.setWarmUp(warmUp);
            MobUtil.moveDownToGround(flames);
            serverLevel.addFreshEntity(flames);
        }
    }
}

protected void onHitEntity(EntityHitResult pResult) {
    if (!this.level.isClientSide) {
        Entity entity = pResult.getEntity();
        Entity entity1 = this.getOwner();
        float enchantment = this.getExtraDamage();
        float damage = 5.0F;
        int flaming = 1 + this.getFiery();
        if (entity1 instanceof Player){
            damage = SpellConfig.FireballDamage.get().floatValue() * WandUtil.damageMultiply();
        } else if (entity1 instanceof LivingEntity) {
            damage = this.getDamage();
        }
        int i = entity.getRemainingFireTicks() + (flaming - 1);
        entity.setSecondsOnFire(5 * flaming);
        DamageSource damageSource = entity.damageSources().fireball(this, entity1);
        if (entity1 instanceof LivingEntity livingEntity){
            if (CuriosFinder.hasNetherRobe(livingEntity)){
                damageSource = ModDamageSource.magicFireball(this, entity1, this.level);
            }
            if (MobUtil.getOwner(livingEntity) != null){
                if (CuriosFinder.hasNetherRobe(MobUtil.getOwner(livingEntity))){
                    damageSource = ModDamageSource.magicFireball(this, entity1, this.level);
                }
            }
        }
        boolean flag = entity.hurt(damageSource, damage + enchantment);
        if (!flag) {
            entity.setRemainingFireTicks(i);
        } else if (entity1 instanceof LivingEntity) {
            this.doEnchantDamageEffects((LivingEntity)entity1, entity);
        }
    }
}

public void onUpdate(){

	super.onUpdate();

	if(this.rand.nextInt(700) == 0 && this.ticksExisted + 100 < lifetime)
		this.playSound(WizardrySounds.ENTITY_DECAY_AMBIENT, 0.2F + rand.nextFloat() * 0.2F,
				0.6F + rand.nextFloat() * 0.15F);

	if(!this.world.isRemote){
		List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2f, this.posX, this.posY,
				this.posZ, this.height, this.world);
		for(EntityLivingBase target : targets){
			if(target != this.getCaster()){
				// If this check wasn't here the potion would be reapplied every tick and hence the entity would be
				// damaged each tick.
				// In this case, we do want particles to be shown.
				if(!target.isPotionActive(WizardryPotions.decay))
					target.addPotionEffect(new PotionEffect(WizardryPotions.decay,
							Spells.decay.getProperty(Spell.EFFECT_DURATION).intValue(), 0));
			}
		}

	}else if(this.rand.nextInt(15) == 0){

		double radius = rand.nextDouble() * 0.8;
		float angle = rand.nextFloat() * (float)Math.PI * 2;
		float brightness = rand.nextFloat() * 0.4f;

		ParticleBuilder.create(Type.DARK_MAGIC)
		.pos(this.posX + radius * MathHelper.cos(angle), this.posY, this.posZ + radius * MathHelper.sin(angle))
		.clr(brightness, 0, brightness + 0.1f)
		.spawn(world);
	}
}

public void tick() {
    this.maverick.setTarget(null);
