public void deserializeNBT(NBTTagCompound nbt){

	if(nbt != null){

		this.imbuementDurations = NBTExtras.NBTToMap(nbt.getTagList("imbuements", NBT.TAG_COMPOUND),
				(NBTTagInt tag) -> (Imbuement)Enchantment.getEnchantmentByID(tag.getInt()), NBTTagInt::getInt);

		this.allies = new HashSet<>(NBTExtras.NBTToList(nbt.getTagList("allies", NBT.TAG_COMPOUND), NBTUtil::getUUIDFromTag));
		this.allyNames = new HashSet<>(NBTExtras.NBTToList(nbt.getTagList("allyNames", NBT.TAG_STRING), NBTTagString::getString));

		this.spellsDiscovered = new HashSet<>();
		for(int id : nbt.getIntArray("discoveredSpells")){
			spellsDiscovered.add(Spell.byMetadata(id));
		}

		this.maxTierReached = Tier.values()[nbt.getInteger("maxTierReached")];

		// Probably won't be null but we may as well just reinitialise it instead of clearing it
		this.recentSpells = EvictingQueue.create(MAX_RECENT_SPELLS);
		// Deserialize recent spells with timestamps
		NBTTagList recentSpellsList = nbt.getTagList("recentSpells", NBT.TAG_COMPOUND);
		for(int i = 0; i < recentSpellsList.tagCount(); i++) {
			NBTTagCompound spellTag = recentSpellsList.getCompoundTagAt(i);
			Spell spell = Spell.byMetadata(spellTag.getInteger("spellId"));
			long timestamp = spellTag.getLong("timestamp");
			this.recentSpells.add(new SimpleEntry<>(spell, timestamp));
		}

		try{
			storedVariables.forEach(k -> this.spellData.put(k, k.read(nbt)));
		}catch(ClassCastException e){
			// Should only happen if someone manually edits the save file
			Wizardry.logger.error("Wizard data NBT tag was not of expected type!", e);
		}
	}
}

private boolean attemptCastSpell(Spell spell, SpellModifiers modifiers){

	// If anything stops the spell working at this point, nothing else happens.
	if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.NPC, spell, attacker, modifiers))){
		return false;
	}

	// This is only called when spell casting starts so ticksInUse is always zero
	if(spell.cast(attacker.world, attacker, EnumHand.MAIN_HAND, 0, target, modifiers)){

		if(spell.isContinuous){
			// -1 because the spell has been cast once already!
			this.continuousSpellTimer = this.continuousSpellDuration - 1;
			setContinuousSpellAndNotify(spell, modifiers);

		}else{

			MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.NPC, spell, attacker, modifiers));

			// For now, the cooldown is just added to the constant base cooldown. I think this
			// is a reasonable way of doing things; it's certainly better than before.
			this.cooldown = this.baseCooldown + spell.getCooldown();

			if(spell.requiresPacket()){
				// Sends a packet to all players in dimension to tell them to spawn particles.
				IMessage msg = new PacketNPCCastSpell.Message(attacker.getEntityId(), target.getEntityId(),
						EnumHand.MAIN_HAND, spell, modifiers);
				WizardryPacketHandler.net.sendToDimension(msg, attacker.world.provider.getDimension());
			}
		}

		return true;
	}

	return false;
}

public void tick() {
    if (this.target != null){
        double d0 = this.servant.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
        boolean flag = this.servant.getSensing().hasLineOfSight(this.target);

        if (d0 <= this.attackRadiusSqr) {
            this.servant.getNavigation().stop();
            if (flag) {
                --this.attackTime;
            }
        } else {
            this.servant.attackAnim = 0;
            this.servant.setAnimationState("");
            this.servant.getNavigation().moveTo(this.target, this.speedModifier);
        }
        this.servant.getLookControl().setLookAt(this.target, 30.0F, 30.0F);

        if (this.attackTime == 20){
            this.servant.setAnimationState(ATTACK);
