public void explode(){
    if (!this.level.isClientSide) {
        Entity owner = this.getOwner();
        if (owner != null) {
            boolean flag = this.isDangerous();
            LootingExplosion.Mode lootMode = CuriosFinder.hasWanting(owner) ? LootingExplosion.Mode.LOOT : LootingExplosion.Mode.REGULAR;
            ExplosionUtil.lootExplode(this.level, owner, this.getX(), this.getY(), this.getZ(), this.getExplosionPower(), flag, flag ? Explosion.BlockInteraction.DESTROY : Explosion.BlockInteraction.KEEP, lootMode);
        } else  {
            if (this.level instanceof ServerLevel serverLevel){
                ColorUtil colorUtil = new ColorUtil(0xff8905);
                serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, this.getExplosionPower(), 1), this.getX(), this.getY(), this.getZ(), 0, 0.0D, 0.0D, 0.0D, 0);
                serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, this.getExplosionPower(), 1), this.getX(), this.getY(), this.getZ(), 0, 0.0D, 0.0D, 0.0D, 0);
                for (int i = 0; i < 8; ++i) {
                    ColorUtil colorUtil1 = new ColorUtil(0xac9b8f);
                    serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), this.getRandomX(1.0F), this.getRandomY(), this.getRandomZ(1.0F), 0, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 1.0F);
                    serverLevel.sendParticles(ModParticleTypes.BIG_FIRE_GROUND.get(), this.getRandomX(0.5F), this.getY(), this.getRandomZ(0.5F), 1, 0.0F, 0.0F, 0.0F, 0.0F);
                }
            }
            this.playSound(SoundEvents.GENERIC_EXPLODE, 4.0F, (1.0F + (this.level.getRandom().nextFloat() - this.level.getRandom().nextFloat()) * 0.2F) * 0.7F);
            float damage = SpellConfig.PyroclastDamage.get().floatValue() * WandUtil.damageMultiply();
            damage += this.getPotency();
            new SpellExplosion(this.level, this, this.damageSources().explosion(this, owner != null ? owner : this), this.getX(), this.getY(), this.getZ(), this.getExplosionPower(), damage) {
                @Override
                public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                    super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                    if (Pyroclast.this.isUpgraded()) {
                        if (target instanceof LivingEntity target1 && !MobUtil.areAllies(owner, target1) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target1)) {
                            target1.addEffect(new MobEffectInstance(GoetyEffects.STUNNED.get(), MathHelper.secondsToTicks(2), 0, false, false));
                        }
                    }
                }
            };
        }
        this.discard();
    }
}

private static List<WitchBrewJeiRecipe> getBrewRecipes(RecipeManager recipeManager, IVanillaRecipeFactory vanillaRecipeFactory, IIngredientManager ingredientManager) {
    List<WitchBrewJeiRecipe> recipes = new ArrayList<>();
    for (ItemStack itemStack : ingredientManager.getAllItemStacks()){
        List<MobEffectInstance> effects = new ArrayList<>();
        List<BrewEffectInstance> blockEffects = new ArrayList<>();
        BrewingRecipe brewingRecipe = recipeManager.getAllRecipesFor(ModRecipeSerializer.BREWING_TYPE.get()).stream().filter(recipe -> recipe.input.test(itemStack)).findFirst().orElse(null);
        ItemStack brew = new ItemStack(ModItems.BREW.get());
        int capacity = 0;
        int soulCost = 0;
        if (brewingRecipe != null){
            effects.add(new MobEffectInstance(brewingRecipe.output, brewingRecipe.duration));
            capacity = brewingRecipe.getCapacityExtra();
            soulCost = brewingRecipe.getSoulCost();
        } else if (BrewEffects.INSTANCE.getEffectFromCatalyst(itemStack.getItem()) != null){
            BrewEffect brewEffect = BrewEffects.INSTANCE.getEffectFromCatalyst(itemStack.getItem());
            if (brewEffect != null){
                if (brewEffect instanceof PotionBrewEffect potionBrewEffect){
                    effects.add(new MobEffectInstance(potionBrewEffect.mobEffect, potionBrewEffect.duration));
                } else {
                    blockEffects.add(new BrewEffectInstance(brewEffect, 1));
                }
                capacity = brewEffect.getCapacityExtra();
                soulCost = brewEffect.getSoulCost();
            }
        }
        if (!effects.isEmpty() || !blockEffects.isEmpty()) {
            BrewUtils.setCustomEffects(brew, effects, blockEffects);
            brew.getOrCreateTag().putInt("CustomPotionColor", BrewUtils.getColor(effects, blockEffects));
            WitchBrewJeiRecipe recipe = new WitchBrewJeiRecipe(itemStack, brew, capacity, soulCost);
            if (!recipes.contains(recipe)) {
                recipes.add(recipe);
            }
        }
    }
    return recipes;
}

public void onUpdate(){

	double extensionSpeed = 0;

	if(!world.isRemote){
		if(lifetime - this.ticksExisted < 15){
			extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 15));
		}else if(lifetime - this.ticksExisted < 25){
			extensionSpeed = 0;
		}else if(lifetime - this.ticksExisted < 28){
			extensionSpeed = 0.25;
		}

		if(facing != null){ // Will probably be null on the client side, but should never be on the server side
			this.move(MoverType.SELF, this.facing.getXOffset() * extensionSpeed, this.facing.getYOffset() * extensionSpeed,
					this.facing.getZOffset() * extensionSpeed);
		}
	}

	if(lifetime - this.ticksExisted == 30) this.playSound(WizardrySounds.ENTITY_ICE_SPIKE_EXTEND, 1, 2.5f);

	if(!this.world.isRemote){
		for(Object entity : this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox())){
			if(entity instanceof EntityLivingBase && this.isValidTarget((EntityLivingBase)entity)){
				DamageSource source = this.getCaster() == null ? DamageSource.MAGIC : MagicDamage.causeDirectMagicDamage(this.getCaster(), DamageType.FROST);
				// Potion effect only gets added if the damage succeeded
				// We DO want knockback here or the entity gets stuck on the spike, which is a bit of a cheat
				if(((EntityLivingBase)entity).attackEntityFrom(source, Spells.ice_spikes.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier))
					((EntityLivingBase)entity).addPotionEffect(new PotionEffect(WizardryPotions.frost,
							Spells.ice_spikes.getProperty(Spell.EFFECT_DURATION).intValue(),
							Spells.ice_spikes.getProperty(Spell.EFFECT_STRENGTH).intValue()));
			}
		}
	}

	super.onUpdate();
}

public static void onSpellCastPreEvent(SpellCastEvent.Pre event){
	// Arcane jammer has a chance to prevent spell casting
	// We can't just use a straight-up random number because otherwise people can spam it to get it to cast
	// Instead, we're using the world time to make blocks of time when spells will and won't work
	random.setSeed(event.getWorld().getTotalWorldTime() / UPDATE_INTERVAL);
	// For some unfathomable reason, the first call to this after setting the seed remains the same for long
	// sequences of consecutive seeds, so let's clear it out first to get to a more changeable value
	random.nextInt(2);

	if(event.getCaster() != null && event.getCaster().isPotionActive(WizardryPotions.arcane_jammer)
			// Arcane jammer I has a 1/2 chance, level II has a 2/3 chance, and so on
			&& random.nextInt(event.getCaster().getActivePotionEffect(WizardryPotions.arcane_jammer).getAmplifier() + 2) > 0){

		event.setCanceled(true);

		// TODO: This currently doesn't play nicely with continuous or charge-up spells
		if(event.getSource() == Source.WAND || event.getSource() == Source.SCROLL){
			event.getCaster().setActiveHand(EnumHand.MAIN_HAND);
		}

		// Because we're using a seed that should be consistent, we can do client-side stuff!
		event.getWorld().playSound(event.getCaster().posX, event.getCaster().posY, event.getCaster().posZ,
				WizardrySounds.MISC_SPELL_FAIL, WizardrySounds.SPELLS, 1, 1, false);

		if(event.getWorld().isRemote){

			Vec3d centre = event.getCaster().getPositionEyes(1).add(event.getCaster().getLookVec());

			for(int i = 0; i < 5; i++){
				double x = centre.x + 0.5f * (event.getWorld().rand.nextFloat() - 0.5f);
				double y = centre.y + 0.5f * (event.getWorld().rand.nextFloat() - 0.5f);
				double z = centre.z + 0.5f * (event.getWorld().rand.nextFloat() - 0.5f);
				event.getWorld().spawnParticle(EnumParticleTypes.SMOKE_LARGE, x, y, z, 0, 0, 0);
			}
		}
	}
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	// Won't work if the weapon already has the enchantment
	if(WizardData.get(caster) != null
			&& WizardData.get(caster).getImbuementDuration(WizardryEnchantments.flaming_weapon) <= 0){

		for(ItemStack stack : InventoryUtils.getPrioritisedHotbarAndOffhand(caster)){

			if((ImbueWeapon.isSword(stack) || ImbueWeapon.isBow(stack))
					&& !EnchantmentHelper.getEnchantments(stack).containsKey(WizardryEnchantments.flaming_weapon)){
				// The enchantment level as determined by the damage multiplier. The + 0.5f is so that
				// weird float processing doesn't incorrectly round it down.
				stack.addEnchantment(WizardryEnchantments.flaming_weapon,
						modifiers.get(SpellModifiers.POTENCY) == 1.0f ? 1
								: (int)((modifiers.get(SpellModifiers.POTENCY) - 1.0f)
										/ Constants.POTENCY_INCREASE_PER_TIER + 0.5f));

				WizardData.get(caster).setImbuementDuration(WizardryEnchantments.flaming_weapon,
						(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade)));

				if(world.isRemote){
					for(int i=0; i<10; i++){
						double x = caster.posX + world.rand.nextDouble() * 2 - 1;
						double y = caster.posY + caster.getEyeHeight() - 0.5 + world.rand.nextDouble();
						double z = caster.posZ + world.rand.nextDouble() * 2 - 1;
						ParticleBuilder.create(Type.SPARKLE).pos(x, y, z).vel(0, 0.1, 0).clr(0.9f, 0.7f, 1).spawn(world);
					}
				}

				this.playSound(world, caster, ticksInUse, -1, modifiers);
				return true;

			}
		}
	}
	return false;
}

