								: (int)((modifiers.get(SpellModifiers.POTENCY) - 1.0f)
										/ Constants.POTENCY_INCREASE_PER_TIER + 0.5f));

				WizardData.get(caster).setImbuementDuration(WizardryEnchantments.freezing_weapon,
						(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade)));

				if(world.isRemote){
					for(int i=0; i<10; i++){
						double x = caster.posX + world.rand.nextDouble() * 2 - 1;
						double y = caster.posY + caster.getEyeHeight() - 0.5 + world.rand.nextDouble();
						double z = caster.posZ + world.rand.nextDouble() * 2 - 1;
						ParticleBuilder.create(Type.SPARKLE).pos(x, y, z).vel(0, 0.1, 0).clr(0.9f, 0.7f, 1).spawn(world);
					}
				}

				this.playSound(world, caster, ticksInUse, -1, modifiers);
				return true;

			}
		}
	}
	return false;
}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(!world.isRemote && EntityUtils.canDamageBlocks(caster, world)){

		// Stops the ice being placed floating above snow and grass. Directions other than up included for
		// completeness.
		if(BlockUtils.canBlockBeReplaced(world, pos)){
			// Moves the blockpos back into the block
			pos = pos.offset(side.getOpposite());
		}

		if(origin.squareDistanceTo(pos.getX(), pos.getY(), pos.getZ()) > MINIMUM_PLACEMENT_RANGE * MINIMUM_PLACEMENT_RANGE
				&& world.getBlockState(pos).getBlock() != WizardryBlocks.ice_statue && world.getBlockState(pos).getBlock() != WizardryBlocks.dry_frosted_ice){

			pos = pos.offset(side);

			int duration = (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));

			if(BlockUtils.canBlockBeReplaced(world, pos) && BlockUtils.canPlaceBlock(caster, world, pos)){
				world.setBlockState(pos, WizardryBlocks.dry_frosted_ice.getDefaultState());
				world.scheduleUpdate(pos.toImmutable(), WizardryBlocks.dry_frosted_ice, duration);
			}

			// Builds a 2 block high wall if it hits the ground
			if(side == EnumFacing.UP){
				pos = pos.offset(side);

				if(BlockUtils.canBlockBeReplaced(world, pos) && BlockUtils.canPlaceBlock(caster, world, pos)){
					world.setBlockState(pos, WizardryBlocks.dry_frosted_ice.getDefaultState());
					world.scheduleUpdate(pos.toImmutable(), WizardryBlocks.dry_frosted_ice, duration);
				}
			}
		}
	}

	return true;
}

public static boolean rechargeManaOnApplyButtonPressed(Slot centre, Slot crystals) {
	boolean changed = false;
	if (!(centre.getStack().getItem() instanceof IWorkbenchItem) || !(centre.getStack().getItem() instanceof IManaStoringItem)) {
		return false;
	}
	IManaStoringItem iManaStoringItem = (IManaStoringItem) centre.getStack().getItem();

	// Charges the item by appropriate amount
	if (crystals.getStack() != ItemStack.EMPTY && !iManaStoringItem.isManaFull(centre.getStack())) {

		int chargeDepleted = iManaStoringItem.getManaCapacity(centre.getStack()) - iManaStoringItem.getMana(centre.getStack());

		// Not too pretty but allows addons implementing the IManaStoringItem interface to provide their mana amount for custom crystals,
		// previously this was defaulted to the regular crystal's amount, allowing players to exploit it if a crystal was worth less mana than that.
		int manaPerItem = crystals.getStack().getItem() instanceof IManaStoringItem ?
				((IManaStoringItem) crystals.getStack().getItem()).getMana(crystals.getStack()) :
				crystals.getStack().getItem() instanceof ItemCrystal ? Constants.MANA_PER_CRYSTAL : Constants.MANA_PER_SHARD;

		if (crystals.getStack().getItem() == WizardryItems.crystal_shard) {manaPerItem = Constants.MANA_PER_SHARD;}
		if (crystals.getStack().getItem() == WizardryItems.grand_crystal) {manaPerItem = Constants.GRAND_CRYSTAL_MANA;}

		if (crystals.getStack().getCount() * manaPerItem < chargeDepleted) {
			// If there aren't enough crystals to fully charge the item
			iManaStoringItem.rechargeMana(centre.getStack(), crystals.getStack().getCount() * manaPerItem);
			crystals.decrStackSize(crystals.getStack().getCount());

		} else {
			// If there are excess crystals (or just enough)
			iManaStoringItem.setMana(centre.getStack(), iManaStoringItem.getManaCapacity(centre.getStack()));
			crystals.decrStackSize((int) Math.ceil(((double) chargeDepleted) / manaPerItem));
		}

		changed = true;
	}

	return changed;
}

private void updateSpecialItems() {
	resetSpecialItems();

	ItemStack item = getItem();
	if (item.isEmpty()) {
		return;
	}

	IItemHandler ih = item.getCapability(Capabilities.ItemHandler.ITEM);
	if (ih != null) {
		itemHandler = ih;
	}

	if (item.getItem() instanceof IPedestalActionItem pedestalActionItem) {
		tickable = true;
		actionItem = pedestalActionItem;
	} else if (item.getItem() instanceof IPedestalRedstoneItem pedestalRedstoneItem) {
		redstoneItem = pedestalRedstoneItem;
	} else {
		PedestalRegistry.getItemWrapper(item).ifPresent(wrapper -> {
			if (wrapper instanceof IPedestalActionItem pedestalActionItem) {
				tickable = true;
				actionItem = pedestalActionItem;
			}
			if (wrapper instanceof IPedestalRedstoneItemWrapper) {
				redstoneItem = (IPedestalRedstoneItem) wrapper;
			}
		});
	}

	IFluidHandlerItem itemFluidHandler = item.getCapability(Capabilities.FluidHandler.ITEM);
	if (itemFluidHandler != null) {
		fluidContainer = item;
	}

	actionCooldown = 0;
}

public void finalizeExplosion() {
    if (this.level instanceof ServerLevel serverLevel) {
        ColorUtil colorUtil = new ColorUtil(0xfef597);
        if (this.isStaff()) {
            DamageSource damageSource = ModDamageSource.getDamageSource(this.level, ModDamageSource.SHOCK);
            int radius = 2;
            float damage = SpellConfig.ElectroOrbDamage.get().floatValue() * WandUtil.damageMultiply();
            if (this.getOwner() != null) {
                damageSource = ModDamageSource.indirectShock(this, this.getOwner());
                if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                    damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
                }
            }
            serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), 5, 0, true), this.getX(), this.getY() + 0.5F, this.getZ(), 0, 0, 0, 0, 0);
            serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), radius, 1), this.getX(), this.getY() + 0.5F, this.getZ(), 1, 0, 0, 0, 0);
            new SpellExplosion(serverLevel, this, damageSource, this.blockPosition(), radius, damage){
                @Override
                public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                    if (target instanceof LivingEntity target1){
                        super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                        float chance = 0.05F;
                        float chainDamage = actualDamage / 2.0F;
                        if (serverLevel.isThundering() && serverLevel.isRainingAt(target1.blockPosition())){
                            chance += 0.25F;
                            chainDamage = actualDamage;
                        }
                        if (serverLevel.random.nextFloat() <= chance){
                            target1.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                        }
                        WandUtil.chainLightning(target1, ElectroOrb.this.getOwner(), radius, chainDamage);
                    }
                }
            };
            serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.REDSTONE_EXPLODE.get(), this.getSoundSource(), 1.0F, 1.0F);
        }
    }
}

protected void onHitEntity(EntityHitResult p_37626_) {
   if (!this.level.isClientSide) {
      Entity entity = p_37626_.getEntity();
      Entity entity1 = this.getOwner();
      boolean flag;
      float enchantment = this.getExtraDamage();
      int duration = 1;
      float damage;
      if (entity1 instanceof LivingEntity livingentity) {
         if (entity1 instanceof Player){
            damage = SpellConfig.WitherSkullDamage.get().floatValue() * WandUtil.damageMultiply();
         } else {
            damage = this.getDamage();
         }
         flag = entity.hurt(this.damageSources().witherSkull(this, livingentity), damage + enchantment);
         if (flag) {
            if (entity.isAlive()) {
               this.doEnchantDamageEffects(livingentity, entity);
            } else {
               livingentity.heal(5.0F);
            }
         }
      } else {
         flag = entity.hurt(this.damageSources().magic(), 5.0F);
      }

      if (flag && entity instanceof LivingEntity livingEntity) {
         if (livingEntity instanceof Player player){
            if (WandUtil.enchantedFocus(player)){
               duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), player);
            }
         }
         livingEntity.addEffect(new MobEffectInstance(MobEffects.WITHER, 200 * duration, 1), this.getEffectSource());
      }

   }
}

public void onUpdate(){

	super.onUpdate();

	if(!this.world.isRemote){

		List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(width/2, this.posX, this.posY,
				this.posZ, this.height, this.world);

		for(EntityLivingBase target : targets){

			if(this.isValidTarget(target)){

				EntityUtils.attackEntityWithoutKnockback(target, this.getCaster() != null
						? MagicDamage.causeIndirectMagicDamage(this, this.getCaster(), DamageType.FROST)
						: DamageSource.MAGIC, Spells.frost_sigil.getProperty(Spell.DAMAGE).floatValue()
						* damageMultiplier);

				if(!MagicDamage.isEntityImmune(DamageType.FROST, target))
					target.addPotionEffect(new PotionEffect(WizardryPotions.frost,
							Spells.frost_sigil.getProperty(Spell.EFFECT_DURATION).intValue(),
							Spells.frost_sigil.getProperty(Spell.EFFECT_STRENGTH).intValue()));

				this.playSound(WizardrySounds.ENTITY_FROST_SIGIL_TRIGGER, 1.0f, 1.0f);

				// The trap is destroyed once triggered.
				this.setDead();
			}
		}
	}else if(this.rand.nextInt(15) == 0){
		double radius = (0.5 + rand.nextDouble() * 0.3) * width/2;
		float angle = rand.nextFloat() * (float)Math.PI * 2;
		ParticleBuilder.create(Type.SNOW)
		.pos(this.posX + radius * MathHelper.cos(angle), this.posY + 0.1, this.posZ + radius * MathHelper.sin(angle))
		.vel(0, 0, 0) // Required since default for snow is not stationary
		.spawn(world);
	}
}

