public boolean hurt(DamageSource source, float amount) {
    if (this.getShields() > 0
            && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)
            && !this.isInvulnerableTo(source)) {
        if (source.getEntity() != null && source.getEntity() instanceof LivingEntity livingEntity) {
            this.setLastHurtByMob(livingEntity);
            if (!source.is(DamageTypeTags.IS_EXPLOSION)) {
                double d0 = livingEntity.getX() - this.getX();

                double d1;
                for(d1 = livingEntity.getZ() - this.getZ(); d0 * d0 + d1 * d1 < 1.0E-4D; d1 = (Math.random() - Math.random()) * 0.01D) {
                    d0 = (Math.random() - Math.random()) * 0.01D;
                }

                this.knockback((double)0.4F, d0, d1);
            }
        }

        amount = this.getDamageAfterArmorAbsorb(source, amount);
        amount = this.getDamageAfterMagicAbsorb(source, amount);
        this.setShieldHealth(this.getShieldHealth() - amount);

        if (this.getShieldHealth() <= 0) {
            this.breakShield();
        } else {
            this.playHurtSound(source);
        }
        return false;
    } else {
        if (source.is(DamageTypeTags.IS_FIRE) && this.getFireHealCool() <= 0){
            this.heal(amount);
            this.healShield(amount);
            this.setFireHealCool(10);
            return false;
        }
        return super.hurt(source, amount);
    }
}

public void trigger(){
    if (!this.level.isClientSide) {
        double bbSize = 3.0D + this.getExtraRadius();
        float damage = SpellConfig.BiomineAcidDamage.get().floatValue() * WandUtil.damageMultiply();
        damage += this.getExtraDamage();
        for (LivingEntity livingentity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(bbSize, bbSize / 2.0D, bbSize))) {
            if (livingentity.isAlive() && !livingentity.isInvulnerable()) {
                if (this.getOwner() != null) {
                    if (!MobUtil.areAllies(this.getOwner(), livingentity) && livingentity != this.getOwner()) {
                        this.explodeDamage(livingentity);
                    }
                } else {
                    this.explodeDamage(livingentity);
                }
            }
        }
        AcidPool acidPool = new AcidPool(ModEntityType.ACID_POOL.get(), this.level);
        acidPool.setPos(this.position());
        acidPool.setRadius(2.0F + this.getExtraRadius());
        acidPool.setDamage(damage);
        acidPool.setColor(0x20b33e);
        ColorUtil colorUtil0 = new ColorUtil(0x20b33e);
        acidPool.setParticle(ModParticleTypes.BIG_CULT_SPELL.get());
        acidPool.setParticleSpeed(colorUtil0.red(), colorUtil0.green(), colorUtil0.blue());
        acidPool.setDuration(MathHelper.secondsToTicks(3) + this.getExtraDuration());
        if (this.getOwner() != null) {
            acidPool.setOwner(this.getOwner());
        }
        this.level.addFreshEntity(acidPool);
        if (this.level instanceof ServerLevel serverLevel) {
            ColorUtil colorUtil = ColorUtil.WHITE;
            serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, (float) bbSize, 1), this.getX(), this.getY(), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
            serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, (float) bbSize, 1), this.getX(), this.getY(), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
        }
        this.playSound(ModSounds.BIOMINE_TRIGGER.get(), 1.4F, 1.0F);
        this.discard();
    }
}

public IEntityLivingData onInitialSpawn(DifficultyInstance difficulty, IEntityLivingData livingdata){

	livingdata = super.onInitialSpawn(difficulty, livingdata);

	textureIndex = this.rand.nextInt(6);

	if(rand.nextBoolean()){
		this.setElement(Element.values()[rand.nextInt(Element.values().length - 1) + 1]);
	}else{
		this.setElement(Element.MAGIC);
	}

	Element element = this.getElement();

	// Adds armour.
	for(EntityEquipmentSlot slot : InventoryUtils.ARMOUR_SLOTS){
		this.setItemStackToSlot(slot, new ItemStack(WizardryItems.getArmour(element, slot)));
	}

	// Default chance is 0.085f, for reference.
	for(EntityEquipmentSlot slot : EntityEquipmentSlot.values())
		this.setDropChance(slot, 0.0f);

	// All wizards know magic missile, even if it is disabled.
	spells.add(Spells.magic_missile);

	Tier maxTier = populateSpells(this, spells, element, false, 3, rand);

	// Now done after the spells so it can take the tier into account.
	ItemStack wand = new ItemStack(WizardryItems.getWand(maxTier, element));
	ArrayList<Spell> list = new ArrayList<>(spells);
	list.add(Spells.heal);
	WandHelper.setSpells(wand, list.toArray(new Spell[5]));
	this.setItemStackToSlot(EntityEquipmentSlot.MAINHAND, wand);

	this.setHealCooldown(50);

	return livingdata;
}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(caster != null && caster.isSneaking() && world.getBlockState(pos).getBlock() == WizardryBlocks.spectral_block){

		if(!world.isRemote){
			// Dispelling of blocks
			world.setBlockToAir(pos);
		}else{
			ParticleBuilder.create(Type.FLASH).pos(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5).scale(3)
			.clr(0.75f, 1, 0.85f).spawn(world);
		}

		return true;
	}

	pos = pos.offset(side);

	if(world.isRemote){
		ParticleBuilder.create(Type.FLASH).pos(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5).scale(3)
		.clr(0.75f, 1, 0.85f).spawn(world);
	}

	if(BlockUtils.canBlockBeReplaced(world, pos)){

		if(!world.isRemote){

			world.setBlockState(pos, WizardryBlocks.spectral_block.getDefaultState());

			if(world.getTileEntity(pos) instanceof TileEntityTimer){
				((TileEntityTimer)world.getTileEntity(pos)).setLifetime((int)(getProperty(BLOCK_LIFETIME).floatValue()
						* modifiers.get(WizardryItems.duration_upgrade)));
			}
		}

		return true;
	}

	return false;
}

public static void onPlayerInteractEvent(PlayerInteractEvent event){

	if(event instanceof PlayerInteractEvent.RightClickItem) return; // Can always do this

	EntityLiving possessee = getPossessee(event.getEntityPlayer());

	if(possessee != null){

		// Let endermen interact with blocks
		if(possessee instanceof EntityEnderman && (
				(event instanceof PlayerInteractEvent.RightClickBlock && ((EntityEnderman)possessee).getHeldBlockState() != null)
						|| (event instanceof PlayerInteractEvent.LeftClickBlock && ((EntityEnderman)possessee).getHeldBlockState() == null)))
			return;

		if(WizardData.get(event.getEntityPlayer()) != null && event.getWorld().isRemote
				&& (event instanceof PlayerInteractEvent.RightClickEmpty
				|| event instanceof PlayerInteractEvent.EntityInteract
				|| event instanceof PlayerInteractEvent.RightClickBlock)){

			Integer cooldown = WizardData.get(event.getEntityPlayer()).getVariable(SHOOT_COOLDOWN_KEY);

			if(cooldown == null || cooldown == 0){

				WizardryPacketHandler.net.sendToServer(new PacketControlInput.Message(PacketControlInput.ControlType.POSSESSION_PROJECTILE));
				WizardData.get(event.getEntityPlayer()).setVariable(SHOOT_COOLDOWN_KEY, PROJECTILE_COOLDOWN);

				if(possessee instanceof EntityLightningWraith){
					Spells.arc.cast(event.getWorld(), event.getEntityPlayer(), EnumHand.MAIN_HAND, 0, new SpellModifiers());
				}

				if(possessee instanceof EntityCreeper){
					((EntityCreeper)possessee).ignite();
				}
			}
		}

		if(event.isCancelable()) event.setCanceled(true);
	}
}

public void tick() {
    super.tick();
    if (this.cropPos.isPresent()) {
        BlockPos blockpos = this.cropPos.get();
        if (blockpos.closerToCenterThan(this.servant.position(), 2.0D)){
            if (this.servant.level.getGameTime() >= this.nextWorkCycleTime) {
                ItemStack itemstack = ItemStack.EMPTY;
                SimpleContainer simplecontainer = this.servant.getInventory();
                int i = simplecontainer.getContainerSize();

                for (int j = 0; j < i; ++j) {
                    ItemStack itemstack1 = simplecontainer.getItem(j);
                    if (itemstack1.is(Items.BONE_MEAL)) {
                        itemstack = itemstack1;
                        break;
                    }
                }

                if (!itemstack.isEmpty() && BoneMealItem.growCrop(itemstack, this.servant.level, blockpos)) {
                    this.servant.level.levelEvent(1505, blockpos, 0);
                    itemstack.shrink(1);
                    if (this.servant.getMainHandItem().is(Items.BONE_MEAL)) {
                        this.servant.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                    } else if (this.servant.getOffhandItem().is(Items.BONE_MEAL)){
                        this.servant.setItemSlot(EquipmentSlot.OFFHAND, ItemStack.EMPTY);
                    }
                    this.cropPos = this.pickNextTarget(this.servant.level, this.servant);
                    this.setCurrentCropAsTarget(this.servant);
                    this.nextWorkCycleTime = this.servant.level.getGameTime() + 40L;
                }

                ++this.timeWorkedSoFar;
            }
        } else {
            this.servant.getLookControl().setLookAt(blockpos.getCenter());
            this.servant.getNavigation().moveTo(blockpos.getCenter().x(), blockpos.getCenter().y(), blockpos.getCenter().z(), 1.0F);
        }
    }
}

public void tick() {
    if (this.target != null) {
        double d0 = this.mob.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
        boolean flag = this.mob.getSensing().hasLineOfSight(this.target);

        if (this.mob.distanceTo(this.target) <= this.attackRadius) {
            this.mob.getNavigation().stop();
            if (!this.mob.stopMoving) {
                this.mob.playSound(ModSounds.SPIDER_CALL.get(), this.mob.getSoundVolume(), this.mob.getVoicePitch());
            }
            this.mob.stopMoving = true;
        } else {
            this.mob.getNavigation().moveTo(this.target, this.speedModifier);
            this.mob.stopMoving = false;
        }

        if (this.mob.stopMoving) {
            MobUtil.instaLook(this.mob, this.target);
        } else {
            this.mob.getLookControl().setLookAt(this.target, 30.0F, 30.0F);
        }
        --this.attackTime;
        if (this.attackTime == this.attackInterval - MathHelper.secondsToTicks(0.75F)) {
            if (!flag) {
                return;
            }

            this.mob.setAnimationState(SHOOT);
            this.mob.shootAnim = MathHelper.secondsToTicks(0.56F) + 5;
        } else if (this.attackTime == this.attackInterval - MathHelper.secondsToTicks(0.75F + 0.36F)) {
            float f = (float) Math.sqrt(d0) / this.attackRadius;
            float f1 = Mth.clamp(f, 0.1F, 1.0F);
            this.mob.performRangedAttack(this.target, f1);
        } else if (this.attackTime <= 0) {
            this.attackTime = this.attackInterval;
        }
    }

}

protected void onHitEntity(EntityHitResult p_37626_) {
    super.onHitEntity(p_37626_);
    if (!this.level.isClientSide) {
        float baseDamage = SpellConfig.WitherBoltDamage.get().floatValue() * WandUtil.damageMultiply();
        Entity entity = p_37626_.getEntity();
        Entity entity1 = this.getOwner();
        boolean flag;
        if (entity1 instanceof LivingEntity livingentity) {
            if (livingentity instanceof Mob mob){
                if (mob.getAttribute(Attributes.ATTACK_DAMAGE) != null && mob.getAttributeValue(Attributes.ATTACK_DAMAGE) > 0){
                    baseDamage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
                }
            }
            baseDamage += this.getExtraDamage();
            flag = entity.hurt(entity.damageSources().indirectMagic(this, livingentity), baseDamage);
            if (flag) {
                if (entity.isAlive()) {
                    this.doEnchantDamageEffects(livingentity, entity);
                } else {
                    livingentity.heal(2.0F);
                }
            }
        } else {
            flag = entity.hurt(entity.damageSources().magic(), baseDamage);
        }

        if (flag && entity instanceof LivingEntity livingEntity) {
            livingEntity.addEffect(new MobEffectInstance(MobEffects.WITHER, 200), this.getEffectSource());
            double x = this.getX();
            double z = this.getZ();
            if (entity1 != null){
                x = entity1.getX();
                z = entity1.getZ();
            }
            livingEntity.knockback(1.0F, x - entity.getX(), z - entity.getZ());
        }

    }
}

public void onLivingUpdate(){

	super.onLivingUpdate();

	// Still better to store this to a local variable as it's almost certainly more efficient.
	int healCooldown = this.getHealCooldown();

	// This is now done slightly differently because isPotionActive doesn't work on client here, meaning that when
	// affected with arcane jammer and healCooldown == 0, whilst the wizard didn't actually heal or play the sound,
	// the particles still spawned, and since healCooldown wasn't reset they spawned every tick until the arcane
	// jammer wore off.
	if(healCooldown == 0 && this.getHealth() < this.getMaxHealth() && this.getHealth() > 0
			&& !this.isPotionActive(WizardryPotions.arcane_jammer)){

		// Healer wizards use greater heal.
		this.heal(this.getElement() == Element.HEALING ? 8 : 4);
		this.setHealCooldown(-1);

		// deathTime == 0 checks the wizard isn't currently dying
	}else if(healCooldown == -1 && this.deathTime == 0){

		// Heal particles TODO: Change this so it uses the heal spell directly
		if(world.isRemote){
			ParticleBuilder.spawnHealParticles(world, this);
		}else{
			if(this.getHealth() < 10){
				// Wizards heal themseselves more often if they have low health
				this.setHealCooldown(150);
			}else{
				this.setHealCooldown(400);
			}

			this.playSound(Spells.heal.getSounds()[0], 0.7F, rand.nextFloat() * 0.4F + 1.0F);
		}
	}

	if(healCooldown > 0){
		this.setHealCooldown(healCooldown - 1);
	}
}

private static int update(EntityPlayer player, Integer countdown){

	if(countdown == null) return 0;

	if(!player.world.isRemote){

		WizardData data = WizardData.get(player);

		List<Location> locations = data.getVariable(Transportation.LOCATIONS_KEY);
		if(locations == null || locations.isEmpty()) return 0;

		// If the location was selected, either it was already at the end of the list or it was moved there
		Location destination = locations.get(locations.size() - 1);

		if(countdown == 1 && destination.dimension == player.dimension){

			Entity mount = player.getRidingEntity();
			if(mount != null) player.dismountRidingEntity();

			player.setPositionAndUpdate(destination.pos.getX() + 0.5, destination.pos.getY(), destination.pos.getZ() + 0.5);

			boolean teleportMount = mount != null && ItemArtefact.isArtefactActive(player, WizardryItems.charm_mount_teleporting);

			if(teleportMount){
				mount.setPositionAndUpdate(destination.pos.getX() + 0.5, destination.pos.getY(), destination.pos.getZ() + 0.5);
				player.startRiding(mount);
			}

			player.addPotionEffect(new PotionEffect(MobEffects.BLINDNESS, 50, 0));
			IMessage msg = new PacketTransportation.Message(destination.pos, teleportMount ? null : player);
			WizardryPacketHandler.net.sendToDimension(msg, player.world.provider.getDimension());
		}

		if(countdown > 0){
			countdown--;
		}
	}

	return countdown;
}

public void hurtEntities(LivingEntity livingEntity){
    ColorUtil colorUtil = new ColorUtil(this.getLightningColor());
    if (this.level instanceof ServerLevel serverLevel) {
        if (livingEntity != null && !livingEntity.isDeadOrDying() && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
            if (livingEntity.isSensitiveToWater()) {
                livingEntity.hurt(livingEntity.damageSources().indirectMagic(this, this.getOwner()), 1.0F);
            }
            if (this.random.nextFloat() <= 0.05F) {
                Vec3 vec3 = this.position();
                float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
                damage += this.getExtraDamage();
                BlockHitResult rayTraceResult = this.blockResult(serverLevel, this, 16);
                Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(serverLevel, BlockPos.containing(rayTraceResult.getLocation()), 16);
                if (lightningRod.isPresent() && !this.isStaff()) {
                    BlockPos blockPos = lightningRod.get();
                    ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                    serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.THUNDERBOLT.get(), this.getSoundSource(), 1.0F, 1.0F);
                } else {
                    Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                    ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                    if (livingEntity.hurt(ModDamageSource.indirectShock(this, this.getOwner()), damage)) {
                        float chance = this.isStaff() ? 0.25F : 0.05F;
                        float chainDamage = damage / 2.0F;
                        if (serverLevel.isThundering() && serverLevel.isRainingAt(livingEntity.blockPosition())){
                            chance += 0.25F;
                            chainDamage = damage;
                        }
                        if (serverLevel.getRandom().nextFloat() <= chance){
                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                        }
                        if (this.isStaff()){
                            WandUtil.chainLightning(livingEntity, this.getOwner() != null ? this.getOwner() : null, 6.0D, chainDamage);
                        }
                    }
                    serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.THUNDERBOLT.get(), this.getSoundSource(), 1.0F, 1.0F);
                }
            }
        }
    }
}

public void update(LevelAccessor p_222312_, BlockPos p_222313_, RandomSource p_222314_, NetherSpreaderUtil p_222315_, boolean p_222316_) {
    if (this.shouldUpdate(p_222312_, p_222313_, p_222315_.isWorldGeneration)) {
        if (this.updateDelay > 0) {
            --this.updateDelay;
        } else {
            BlockState blockstate = p_222312_.getBlockState(this.pos);
            NetherBehaviour netherbehaviour = getBlockBehaviour(blockstate);
            if (p_222316_ && netherbehaviour.attemptSpreadVein(p_222312_, this.pos, blockstate, this.facings, p_222315_.isWorldGeneration())) {
                if (netherbehaviour.canChangeBlockStateOnSpread()) {
                    blockstate = p_222312_.getBlockState(this.pos);
                    netherbehaviour = getBlockBehaviour(blockstate);
                }

                p_222312_.playSound(null, this.pos, ModSounds.NETHER_SPREAD.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
            }

            this.charge = netherbehaviour.attemptUseCharge(this, p_222312_, p_222313_, p_222314_, p_222315_, p_222316_);
            if (this.charge <= 0) {
                netherbehaviour.onDischarged(p_222312_, blockstate, this.pos, p_222314_);
            } else {
                BlockPos blockpos = getValidMovementPos(p_222312_, this.pos, p_222314_);
                if (blockpos != null) {
                    netherbehaviour.onDischarged(p_222312_, blockstate, this.pos, p_222314_);
                    this.pos = blockpos.immutable();
                    if (p_222315_.isWorldGeneration() && !this.pos.closerThan(new Vec3i(p_222313_.getX(), this.pos.getY(), p_222313_.getZ()), 15.0D)) {
                        this.charge = 0;
                        return;
                    }

                    blockstate = p_222312_.getBlockState(blockpos);
                } else {
                    this.charge -= 1;
                }

                this.decayDelay = netherbehaviour.updateDecayDelay(this.decayDelay);
                this.updateDelay = netherbehaviour.getNetherSpreadDelay();
            }
        }
    }
}

public static void setCamera(Player player, @Nullable Entity target, @Nullable BlockPos blockPos){
    if (target != null || blockPos != null) {
        if (target == player || blockPos != null){
            double Y;
            SurveyEye surveyEye = new SurveyEye(ModEntityType.SURVEY_EYE.get(), player.level);
            BlockPos.MutableBlockPos blockpos$mutable;
            if (target == player){
                Y = player.getY();
                blockpos$mutable = new BlockPos.MutableBlockPos(player.getX(), player.getY() + 8, player.getZ());
            } else {
                Y = blockPos.getY();
                blockpos$mutable = new BlockPos.MutableBlockPos(blockPos.getX(), blockPos.getY() + 1, blockPos.getZ());
            }

            while(blockpos$mutable.getY() < Y + 16.0D && !player.level.getBlockState(blockpos$mutable).blocksMotion()) {
                blockpos$mutable.move(Direction.UP);
            }
            surveyEye.setPos(Vec3.atCenterOf(blockpos$mutable));
            if (target == player) {
                surveyEye.lookAt(player, 90.0F, 90.0F);
            } else {
                surveyEye.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atBottomCenterOf(blockpos$mutable));
            }
            surveyEye.setOwner(player);
            if (player.level.addFreshEntity(surveyEye)){
                getCapability(player).setCameraUUID(surveyEye.getUUID());
                target = surveyEye;
            }
        } else {
            getCapability(player).setCameraUUID(target.getUUID());
        }
    } else {
        getCapability(player).setCameraUUID(null);
        target = player;
    }
    if (player instanceof ServerPlayer serverPlayer && target != null) {
        serverPlayer.connection.send(new ClientboundSetCameraPacket(target));
    }
    sendSEUpdatePacket(player);
}

default void enchanterTick() {
    if (this instanceof Mob mob) {
        if (mob.level instanceof ServerLevel serverLevel) {
            if (this.getEnchantCool() > 0) {
                this.setEnchantCool(this.getEnchantCool() - 1);
            }
            if (mob.tickCount > 20) {
                if (!this.getEnchantList().isEmpty()) {
                    this.getEnchantList().removeIf(uuid -> {
                        Entity entity = serverLevel.getEntity(uuid);
                        if (!(entity instanceof LivingEntity livingEntity)) {
                            return true;
                        }
                        if (mob.isDeadOrDying()) {
                            return true;
                        }
                        if (this.enchantTimeLimit() > -1) {
                            if (this.getEnchantTime() >= this.enchantTimeLimit()) {
                                this.setEnchantCool(200);
                                return true;
                            }
                        }
                        if (livingEntity.isDeadOrDying()) {
                            return true;
                        }
                        return livingEntity.distanceTo(mob) > 20.0F;
                    });
                    this.getEnchantList().forEach(uuid -> {
                        Entity entity = serverLevel.getEntity(uuid);
                        if (entity instanceof LivingEntity livingEntity) {
                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.ENCHANTED.get(), 30), mob);
                        }
                    });
                    this.setEnchantTime(this.getEnchantTime() + 1);
                } else if (this.getEnchantTime() > 0) {
                    this.setEnchantTime(0);
                }
            }
        }
    }
}

