public void tick() {
    if (this.target != null && !this.mob.isSpellCasting()) {
        double d0 = this.mob.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
        boolean flag = this.mob.getSensing().hasLineOfSight(this.target);
        if (flag) {
            ++this.seeTime;
        } else {
            this.seeTime = 0;
        }

        if (!(d0 > (double) this.attackRadiusSqr) && this.seeTime >= 5) {
            this.mob.getNavigation().stop();
        } else {
            this.mob.getNavigation().moveTo(this.target, this.speedModifier);
        }

        int speed = Mth.floor(Math.max(this.mob.getAttackSpeed(), 1.0F));
        this.mob.getLookControl().setLookAt(this.target, 30.0F, 30.0F);
        int attackIntervalMin = this.attackInterval / speed;
        --this.attackTime;
        if (this.attackTime <= ANIMATION_START) {
            this.mob.setShooting(true);
            if (this.mob.getCurrentAnimation() != this.mob.getAnimationState(ATTACK)) {
                this.mob.setAnimationState(ATTACK);
            }
        }
        if (this.attackTime == 0) {
            if (!flag) {
                return;
            }

            float f = (float) Math.sqrt(d0) / this.attackRadius;
            float f1 = Mth.clamp(f, 0.1F, 1.0F);
            this.mob.performRangedAttack(this.target, f1);
            this.attackTime = attackIntervalMin;
        } else if (this.attackTime < 0) {
            this.mob.setShooting(false);
            this.attackTime = attackIntervalMin;
        }
    }
}

protected void onHit(HitResult p_36913_) {
    super.onHit(p_36913_);
    Entity entity = this.getOwner();
    float radius = 0;
    int duration = 1;
    float damage = 0.0F;
    if (p_36913_.getType() != HitResult.Type.ENTITY || !this.ownedBy(((EntityHitResult)p_36913_).getEntity())) {
        if (!this.level.isClientSide) {
            List<LivingEntity> list = this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(4.0D, 2.0D, 4.0D));
            DragonBreathCloud breathCloud = new DragonBreathCloud(this.level, this.getX(), this.getY(), this.getZ());
            if (entity instanceof LivingEntity livingEntity) {
                if (entity instanceof Player player){
                    if (WandUtil.enchantedFocus(player)){
                        radius = WandUtil.getLevels(ModEnchantments.RADIUS.get(), player);
                        duration = WandUtil.getLevels(ModEnchantments.DURATION.get(), player) + 1;
                        damage = WandUtil.getLevels(ModEnchantments.POTENCY.get(), player) / 2.0F;
                    }
                }
                breathCloud.setOwner(livingEntity);
            }
            breathCloud.setDamage(breathCloud.getDamage() + damage);
            breathCloud.setRadius(3.0F + radius);
            breathCloud.setDuration(600 * duration);
            breathCloud.setRadiusPerTick((7.0F - breathCloud.getRadius()) / (float)breathCloud.getDuration());
            if (!list.isEmpty()) {
                for(LivingEntity livingentity : list) {
                    double d0 = this.distanceToSqr(livingentity);
                    if (d0 < 16.0D) {
                        breathCloud.setPos(livingentity.getX(), livingentity.getY(), livingentity.getZ());
                        break;
                    }
                }
            }

            this.level.levelEvent(2006, this.blockPosition(), this.isSilent() ? -1 : 1);
            this.level.addFreshEntity(breathCloud);
            this.discard();
        }

    }
}

public void tick() {
    super.tick();
    this.tickLerp();

    if (this.getHurtTime() > 0) {
        this.setHurtTime(this.getHurtTime() - 1);
    }

    if (this.getDamage() > 0.0F) {
        this.setDamage(this.getDamage() - 1.0F);
    }

    if (this.getOwner() != null) {
        this.ownerCheck();
    }

    if (this.isVehicle() && this.getControllingPassenger() != null) {
        this.setYRot(this.getControllingPassenger().getYRot());
        if (!this.level.isClientSide) {
            if (this.getControllingPassenger() instanceof Player player) {
                if (ItemConfig.HauntedBroomSoulDistance.get() > 0) {
                    if (this.prevLoc.distanceTo(this.position()) >= Mth.square(ItemConfig.HauntedBroomSoulDistance.get())) {
                        this.prevLoc = this.position();
                        if (SEHelper.getSoulsAmount(player, ItemConfig.HauntedBroomSouls.get())) {
                            SEHelper.decreaseSouls(player, ItemConfig.HauntedBroomSouls.get());
                        } else {
                            SEHelper.addCooldown(player, this.getItem().getItem(), MathHelper.minutesToTicks(1));
                            this.hurt(this.damageSources().dryOut(), 100.0F);
                        }
                    }
                }
            }
        }
    }

    if (this.isControlledByLocalInstance()) {
        this.handleInputs();
    } else {
        this.setDeltaMovement(Vec3.ZERO);
    }
}

public static void shootProjectile(EntityPlayer possessor){

	if(WizardData.get(possessor) != null){

		Integer cooldown = WizardData.get(possessor).getVariable(SHOOT_COOLDOWN_KEY);

		if(cooldown == null || cooldown == 0){

			EntityLiving possessee = getPossessee(possessor);

			if(possessee != null){

				if(possessee instanceof EntityLightningWraith){
					Spells.arc.cast(possessor.world, possessor, EnumHand.MAIN_HAND, 0, new SpellModifiers());
				}

				if(possessee instanceof EntityCreeper){
					((Possession)Spells.possession).endPossession(possessor);
					((EntityCreeper)possessee).ignite(); // Aaaaaaand.... RUN!
				}

				Function<World, ? extends IProjectile> factory = projectiles.get(possessee.getClass());

				if(factory != null){

					IProjectile projectile = factory.apply(possessor.world);
					Vec3d look = possessor.getLookVec();
					((Entity)projectile).setPosition(possessor.posX + look.x, possessor.posY + possessor.getEyeHeight() + look.y, possessor.posZ + look.z);
					projectile.shoot(look.x, look.y, look.z, 1.6f, EntityUtils.getDefaultAimingError(possessor.world.getDifficulty()));

					if(projectile instanceof EntityMagicProjectile) ((EntityMagicProjectile)projectile).setCaster(possessor);
					else if(projectile instanceof EntityMagicArrow) ((EntityMagicArrow)projectile).setCaster(possessor);

					possessor.world.spawnEntity((Entity)projectile);

				}

				WizardData.get(possessor).setVariable(SHOOT_COOLDOWN_KEY, PROJECTILE_COOLDOWN);
			}
		}
	}
}

public void tick() {
    LivingEntity target = this.geomancer.getTarget();
    if (target != null) {
        MobUtil.instaLook(this.geomancer, target);
        this.geomancer.getNavigation().stop();
        ++this.spellTick;
        if (this.spellTick == 13){
            this.geomancer.playSound(ModSounds.GEOMANCER_ATTACK.get(), 0.55F, 0.8F);
            int trueCooldown = MathHelper.secondsToTicks(3);
            float chance = 0.25F;
            if (this.geomancer.random.nextBoolean()){
                if (this.geomancer.random.nextFloat() <= chance){
                    WandUtil.summonQuadOffensiveTrap(this.geomancer, target, ModEntityType.TOTEMIC_BOMB.get(), 0);
                    trueCooldown += MathHelper.secondsToTicks(3);
                } else {
                    int xShift = this.geomancer.getRandom().nextInt(-1, 1);
                    int zShift = this.geomancer.getRandom().nextInt(-1, 1);
                    WandUtil.summonMonolith(this.geomancer, target, ModEntityType.TOTEMIC_BOMB.get(), xShift, zShift, 0);
                    trueCooldown += MathHelper.secondsToTicks(2);
                }
            } else {
                int random = this.geomancer.random.nextInt(3);
