public void aiStep() {
    super.aiStep();
    if (this.postTeleportTick <= 0) {
        if (this.getCurrentAnimation() == this.getAnimationState(TELEPORT_IN)) {
            this.setAnimationState(IDLE);
        }
    } else if (this.postTeleportTick == 13) {
        this.setAnimationState(TELEPORT_IN);
    }
    if (!this.level.isClientSide) {
        if (!this.isDeadOrDying()) {
            this.setAggressive(this.getTarget() != null);
            if (this.isMeleeAttacking()) {
                ++this.attackTick;
            } else if (this.isAttacking()) {
                this.setAnimationState(IDLE);
            }
            AttributeInstance instance = this.getAttribute(Attributes.ATTACK_DAMAGE);
            if (instance != null) {
                if (this.getCurrentAnimation() == this.getAnimationState(SMASH)) {
                    if (this.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                        instance.removeModifier(SMASH_ATTACK_MODIFIER);
                        instance.addTransientModifier(SMASH_ATTACK_MODIFIER);
                    }
                } else {
                    if (instance.hasModifier(SMASH_ATTACK_MODIFIER)) {
                        instance.removeModifier(SMASH_ATTACK_MODIFIER);
                    }
                }
            }
            if (this.teleportCool <= 0) {
                if (!this.isStaying()) {
                    if (!this.isHiding()) {
                        if (this.getTarget() != null) {
                            this.startHide();
                        }
                    }
                }
            }
        }
    }
}

protected void onHit(HitResult hitResult) {
    if (!this.level.isClientSide) {
        DamageSource damageSource = ModDamageSource.getDamageSource(this.level, ModDamageSource.SHOCK);
        float damage = SpellConfig.SurgingDamage.get().floatValue() * WandUtil.damageMultiply();
        if (this.getOwner() != null) {
            damageSource = ModDamageSource.indirectShock(this, this.getOwner());
        }
        damage += this.getExtraDamage();
        if (hitResult instanceof EntityHitResult result) {
            Entity entity = result.getEntity();
            if (entity.hurt(damageSource, damage)) {
                float chance = this.isStaff() ? 0.25F : 0.05F;
                if (this.level.isThundering() && this.level.isRainingAt(entity.blockPosition())) {
                    chance += 0.25F;
                }
                if (entity instanceof LivingEntity livingEntity) {
                    if (this.level.getRandom().nextFloat() <= chance) {
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (this.isStaff()) {
                        float chainDamage = damage / 2.0F;
                        WandUtil.chainLightning(livingEntity, this.getOwner() instanceof LivingEntity living ? living : null, 2.0D, chainDamage);
                    }
                }
            }
        }
        if (this.level instanceof ServerLevel serverLevel) {
            ColorUtil colorUtil = this.isOrange() ? new ColorUtil(ChatFormatting.GOLD) : new ColorUtil(0xa4ffff);
            serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), 0.5F, 1), this.getX(), this.getY(), this.getZ(), 1, 0, 0, 0, 0);
            for (int i = 0; i < 8; ++i) {
                Vec3 vec3 = this.position();
                int random1 = this.level.getRandom().nextIntBetweenInclusive(-1, 1);
                int random2 = this.level.getRandom().nextIntBetweenInclusive(-1, 1);
                int random3 = this.level.getRandom().nextIntBetweenInclusive(-1, 1);
                Vec3 vec31 = vec3.add(this.level.getRandom().nextDouble() * random1, this.level.getRandom().nextDouble() * random2, this.level.getRandom().nextDouble() * random3);
                ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, colorUtil, 8));
            }
        }
        this.playSound(ModSounds.THUNDERBOLT.get(), 1.0F, 1.0F + (this.random.nextFloat() - this.random.nextFloat()) * 0.2F);
        this.discard();
    }
}

protected void onHit(HitResult pResult) {
    if (pResult instanceof EntityHitResult entityHitResult && !this.isExplode()){
        this.onHitEntity(entityHitResult);
    }
    if (this.level instanceof ServerLevel serverLevel){
        if (this.isExplode()) {
            Vec3 vec3 = Vec3.atCenterOf(this.blockPosition());
            if (pResult instanceof BlockHitResult blockHitResult) {
                BlockPos blockpos = blockHitResult.getBlockPos().relative(blockHitResult.getDirection());
                if (BlockFinder.canBeReplaced(serverLevel, blockpos)) {
                    vec3 = Vec3.atCenterOf(blockpos);
                }
            } else if (pResult instanceof EntityHitResult entityHitResult) {
                Entity entity1 = entityHitResult.getEntity();
                vec3 = Vec3.atCenterOf(entity1.blockPosition());
            }
            float damage = this.baseDamage + this.getExtraDamage();
            new SpellExplosion(serverLevel, this.getOwner() != null ? this.getOwner() : this, this.damageSources().indirectMagic(this, this.getOwner()), vec3.x, vec3.y, vec3.z, 1.5F + this.getExtraRadius(), damage) {
                @Override
                public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                    super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                    if (target.level.getRandom().nextFloat() <= 0.25F) {
                        if (target instanceof LivingEntity livingEntity && !livingEntity.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(3), 2, false, true));
                        }
                    }
                }
            };
            ColorUtil colorUtil = new ColorUtil(0xb103d8);
            serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 1.5F, 1), vec3.x, BlockFinder.moveDownToGround(this), vec3.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 3.0F, 1), vec3.x, BlockFinder.moveDownToGround(this), vec3.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 1.5F, 1), vec3.x, BlockFinder.moveDownToGround(this), vec3.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 3.0F, 1), vec3.x, BlockFinder.moveDownToGround(this), vec3.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            DustCloudParticleOption cloudParticleOptions = new DustCloudParticleOption(new Vector3f(Vec3.fromRGB24(16733695).toVector3f()), 1.0F);
            for (int i = 0; i < 2; ++i) {
                ServerParticleUtil.circularParticles(serverLevel, cloudParticleOptions, vec3.x, this.getY() + 0.25D, vec3.z, 0, 0.14D, 0, 1.0F);
            }
            this.playSound(ModSounds.FUNGUS_EXPLOSION.get(), 1.0F, 0.6F + (serverLevel.getRandom().nextFloat() * 0.4F));
        }
        this.discard();
    }
}

