public void onUpdate(){

	super.onUpdate();

	if(lifetime - ticksExisted > 10 && spawnTimer-- == 0){

		this.playSound(WizardrySounds.ENTITY_ZOMBIE_SPAWNER_SPAWN, 1, 1);

		if(!world.isRemote){

			EntityZombieMinion zombie = spawnHusks ? new EntityHuskMinion(world) : new EntityZombieMinion(world);

			zombie.setPosition(this.posX + (rand.nextDouble() * 2 - 1) * MAX_NUDGE_DISTANCE, this.posY,
					this.posZ + (rand.nextDouble() * 2 - 1) * MAX_NUDGE_DISTANCE);
			zombie.setCaster(this.getCaster());
			// Modifier implementation
			// Attribute modifiers are pretty opaque, see https://minecraft.gamepedia.com/Attribute#Modifiers
			zombie.setLifetime(Spells.zombie_apocalypse.getProperty(SpellMinion.MINION_LIFETIME).intValue());
			IAttributeInstance attribute = zombie.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE);
			attribute.applyModifier(new AttributeModifier(SpellMinion.POTENCY_ATTRIBUTE_MODIFIER,
					damageMultiplier - 1, EntityUtils.Operations.MULTIPLY_CUMULATIVE));
			zombie.setHealth(zombie.getMaxHealth()); // Need to set this because we may have just modified the value
			zombie.hurtResistantTime = 30; // Prevent fall damage
			zombie.hideParticles(); // Hide spawn particles or they pop out the top of the hidden box

			world.spawnEntity(zombie);
		}

		spawnTimer += Spells.zombie_apocalypse.getProperty(ZombieApocalypse.MINION_SPAWN_INTERVAL).intValue() + rand.nextInt(20);
	}

	if(world.isRemote){

		float b = 0.15f;

		for(double r = 1.5; r < 4; r += 0.2){
			ParticleBuilder.create(Type.CLOUD).clr(b-=0.02, 0, 0).pos(posX, posY - 0.3, posZ).scale(0.5f / (float)r)
					.spin(r, 0.02/r * (1 + world.rand.nextDouble())).spawn(world);
		}

	}

}

default void mobSense(){
    if (this instanceof Mob owned) {
        if (MobsConfig.MobSense.get()) {
            if (owned.isAlive()) {
                if (owned.getTarget() != null) {
                    if (owned.getTarget() instanceof Mob mob) {
                        if (mob instanceof Animal animal) {
                            animal.setLastHurtByMob(owned);
                        } else if (mob.getTarget() == null) {
                            LivingEntity target = owned;
                            if (mob.getType().is(ModTags.EntityTypes.IGNORE_SERVANTS)) {
                                if (this.getTrueOwner() != null) {
                                    if (mob.canAttack(this.getTrueOwner()) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(mob)) {
                                        target = this.getTrueOwner();
                                    }
                                }
                            }
                            if (mob instanceof Guardian guardian) {
                                if (guardian.hasLineOfSight(owned) && guardian.distanceToSqr(owned) > 9.0D) {
                                    mob.setTarget(target);
                                }
                            } else {
                                mob.setTarget(target);
                            }
                        }
                        if (!mob.getBrain().isActive(Activity.FIGHT) && !(mob instanceof Warden)) {
                            LivingEntity target = owned;
                            if (mob.getType().is(ModTags.EntityTypes.IGNORE_SERVANTS)) {
                                if (this.getTrueOwner() != null) {
                                    if (mob.canAttack(this.getTrueOwner()) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(mob)) {
                                        target = this.getTrueOwner();
                                    }
                                }
                            }
                            mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, target.getUUID(), 600L);
                            mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, target, 600L);
                        }
                    }
                }
            }
        }
    }
}

public boolean hurt(DamageSource pSource, float pAmount) {
    LivingEntity livingEntity = this.getTarget();
    if (this.getInvulnerableTicks() > 0 && !pSource.is(DamageTypes.FELL_OUT_OF_WORLD)){
        return false;
    }
    if (this.moddedInvul > 0){
        return false;
    }
    if (livingEntity != null){
        if (pSource.getEntity() instanceof Irk irk && irk.getTarget() != this){
            return false;
        } else if (pAmount > 0.0F) {
            if (!MobsConfig.VizierMinion.get()) {
                int irks = this.level.getEntitiesOfClass(Irk.class, this.getBoundingBox().inflate(32)).size();
                if ((this.level.random.nextBoolean() || this.getHealth() < this.getMaxHealth()/2) && irks < 16) {
                    Irk irk = new Irk(ModEntityType.IRK.get(), this.level);
                    irk.setPos(this.getX(), this.getY(), this.getZ());
                    irk.setLimitedLife(MobUtil.getSummonLifespan(this.level));
                    irk.setTrueOwner(this);
                    this.level.addFreshEntity(irk);
                }
            } else {
                int vexes = this.level.getEntitiesOfClass(Vex.class, this.getBoundingBox().inflate(32)).size();
                if ((this.level.random.nextBoolean() || this.getHealth() < this.getMaxHealth()/2) && vexes < 16) {
                    if (!this.level.isClientSide) {
                        Vex irk = new Vex(EntityType.VEX, this.level);
                        irk.setPos(this.getX(), this.getY(), this.getZ());
                        irk.setLimitedLife(MobUtil.getSummonLifespan(this.level));
                        irk.setOwner(this);
                        irk.finalizeSpawn((ServerLevelAccessor) this.level, this.level.getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                        this.level.addFreshEntity(irk);
                    }
                }
            }
        }
    }

    if (this.isSpellcasting() && !pSource.is(DamageTypes.FELL_OUT_OF_WORLD)){
        return super.hurt(pSource, pAmount / 2);
    } else {
        return super.hurt(pSource, pAmount);
    }
}

public void tick() {
    super.tick();
    if (!this.level.isClientSide) {
        if (this.tickCount % 2 == 0) {
            if (this.level instanceof ServerLevel serverLevel) {
                ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ModParticleTypes.FLY.get(), this);
            }
        }
        if (this.getTarget() != null) {
            this.navigation.moveTo(this.getTarget(), 7.0D);
        } else {
            Vec3 vec3 = LandRandomPos.getPos(this, 10, 7);
            if (vec3 == null){
                vec3 = DefaultRandomPos.getPos(this, 10, 7);
            }
            if (vec3 != null){
                this.navigation.moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
            }
        }
        if (this.level.collidesWithSuffocatingBlock(this, this.getBoundingBox().move(0.0D, -1.0D, 0.0D))) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.02D, 0.0D));
        } else {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.008D, 0.0D));
        }
        if (!this.moveControl.hasWanted()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.95F, 1.0F, 0.95F));
        }
        float inflate = 2.0F - this.getBbWidth() * 0.5F;
        for (LivingEntity living : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(inflate))) {
            if (living != this && !MobUtil.areAllies(this, living) && SummonTargetGoal.predicate(this).test(living)) {
                if (living.hurt(ModDamageSource.swarm(this, this.getTrueOwner()), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE))) {
                    this.playSound(ModSounds.INSECT_SWARM_BITE.get(), 1.0F, this.getVoicePitch());
                    int speed = (int) ((this.getHealth() / this.getMaxHealth()) * 5);
                    living.invulnerableTime = Math.min(20, (20 - speed));
                    this.hurt(this.damageSources().starve(), 2.0F);
                    if (this.getTrueOwner() != null && CuriosFinder.hasWildRobe(this.getTrueOwner())){
                        living.addEffect(new MobEffectInstance(GoetyEffects.ACID_VENOM.get(), MathHelper.secondsToTicks(5)));
                    }
                }
            }
        }
    }
}

public boolean canUse() {
    if (!EvokerServant.this.isLeader()) {
        return false;
    } else if (EvokerServant.this.getTarget() != null) {
        return false;
    } else if (EvokerServant.this.isCastingSpell()) {
        return false;
    } else if (EvokerServant.this.tickCount < this.nextAttackTickCount) {
        return false;
    } else if (EvokerServant.this.ravageCool > 0) {
        return false;
    } else if (EvokerServant.this.getNearbyCompanions().isEmpty()) {
        return false;
    } else if (this.otherEvokers().size() < 2) {
        return false;
    } else {
        if (EvokerServant.this.getTrueOwner() instanceof Player player) {
            if (!SEHelper.hasResearch(player, ResearchList.RAVAGING)){
                return false;
            } else if (EvokerServant.this.getCommandPosEntity() instanceof Mob mob && this.ravagePredicate.test(mob) && !(mob instanceof RaiderServant raiderServant && EvokerServant.this.getLeader() == raiderServant) && mob.distanceTo(EvokerServant.this) <= 16.0D) {
                EvokerServant.this.setRavageTarget(mob);
                return true;
            } else if (EvokerServant.this.isGrudgedTowardsTag(ModTags.EntityTypes.VILLAGERS) || EvokerServant.this.isGrudgedTowardsTag(ModTags.EntityTypes.PILLAGERS)) {
                TargetingConditions conditions = this.ravageTargeting;
                if (!EvokerServant.this.isGrudgedTowardsTag(ModTags.EntityTypes.VILLAGERS)) {
                    conditions = this.pillagerTargeting;
                } else if (!EvokerServant.this.isGrudgedTowardsTag(ModTags.EntityTypes.PILLAGERS)) {
                    conditions = this.villagerTargeting;
                }
                List<Mob> list = EvokerServant.this.level.getNearbyEntities(Mob.class, conditions, EvokerServant.this, EvokerServant.this.getBoundingBox().inflate(16.0D, 4.0D, 16.0D));
                if (list.isEmpty()) {
                    return false;
                } else {
                    EvokerServant.this.setRavageTarget(list.get(EvokerServant.this.random.nextInt(list.size())));
                    return true;
                }
            } else {
                return false;
            }
        } else {
            return false;
        }
    }
}

public void updateCursors(LevelAccessor p_222256_, BlockPos p_222257_, RandomSource p_222258_, boolean p_222259_) {
    if (!this.cursors.isEmpty()) {
        List<NetherSpreaderUtil.ChargeCursor> list = new ArrayList<>();
        Map<BlockPos, ChargeCursor> map = new HashMap<>();
        Object2IntMap<BlockPos> object2intmap = new Object2IntOpenHashMap<>();

        for (NetherSpreaderUtil.ChargeCursor chargeCursor : this.cursors) {
            chargeCursor.update(p_222256_, p_222257_, p_222258_, this, p_222259_);
            if (chargeCursor.charge > 0) {
                BlockPos blockpos = chargeCursor.getPos();
                object2intmap.computeInt(blockpos, (p_222264_, p_222265_) -> {
                    return (p_222265_ == null ? 0 : p_222265_) + chargeCursor.charge;
                });
                NetherSpreaderUtil.ChargeCursor chargeCursor1 = map.get(blockpos);
                if (chargeCursor1 == null) {
                    map.put(blockpos, chargeCursor);
                    list.add(chargeCursor);
                } else if (!this.isWorldGeneration() && chargeCursor.charge + chargeCursor1.charge <= 1000) {
                    chargeCursor1.mergeWith(chargeCursor);
                } else {
                    list.add(chargeCursor);
                    if (chargeCursor.charge < chargeCursor1.charge) {
                        map.put(blockpos, chargeCursor);
                    }
                }
            }

        }

        for (Object2IntMap.Entry<BlockPos> entry : object2intmap.object2IntEntrySet()) {
            BlockPos blockpos1 = entry.getKey();
            int k = entry.getIntValue();
            NetherSpreaderUtil.ChargeCursor chargeCursor = map.get(blockpos1);
            Collection<Direction> collection = chargeCursor == null ? null : chargeCursor.getFacingData();
            if (k > 0 && collection != null) {
                int i = (int) (Math.log1p((double) k) / (double) 2.3F) + 1;
                int j = (i << 6) + MultifaceBlock.pack(collection);
                p_222256_.levelEvent(2001, blockpos1, Block.getId(Blocks.NETHERRACK.defaultBlockState()));
            }
        }

        this.cursors = list;
    }
}

public void onLivingUpdate(){

	super.onLivingUpdate();

	int healCooldown = this.getHealCooldown();

	// This is now done slightly differently because isPotionActive doesn't work on client here, meaning that when
	// affected with arcane jammer and healCooldown == 0, whilst the wizard didn't actually heal or play the sound,
	// the particles still spawned, and since healCooldown wasn't reset they spawned every tick until the arcane
	// jammer wore off.
	if(healCooldown == 0 && this.getHealth() < this.getMaxHealth() && this.getHealth() > 0
			&& !this.isPotionActive(WizardryPotions.arcane_jammer)){

		// Healer wizards use greater heal.
		this.heal(this.getElement() == Element.HEALING ? 8 : 4);
		this.setHealCooldown(-1);

		// deathTime == 0 checks the wizard isn't currently dying
	}else if(healCooldown == -1 && this.deathTime == 0){

		// Heal particles TODO: Change this so it uses the heal spell directly
		if(world.isRemote){
			for(int i=0; i<10; i++){
				double x = (double)((float)this.posX + rand.nextFloat() * 2 - 1.0F);
				// Apparently the client side spawns the particles 1 block higher than it should... hence the -
				// 0.5F.
				double y = (double)((float)this.posY - 0.5F + rand.nextFloat());
				double z = (double)((float)this.posZ + rand.nextFloat() * 2 - 1.0F);
				ParticleBuilder.create(Type.SPARKLE).pos(x, y, z).vel(0, 0.1F, 0).clr(1, 1, 0.3f).spawn(world);
			}
		}else{
			if(this.getHealth() < 10){
				// Wizards heal themselves more often if they have low health
				this.setHealCooldown(150);
			}else{
				this.setHealCooldown(400);
			}

			this.playSound(Spells.heal.getSounds()[0], 0.7F, rand.nextFloat() * 0.4F + 1.0F);
		}
	}
	if(healCooldown > 0){
		this.setHealCooldown(healCooldown - 1);
	}
}

public void performRangedAttack(LivingEntity target, float velocity) {
    if (target.distanceTo(this) < 6.0F && this.coolDown <= 0 && this.level.getBlockState(this.blockPosition().above(2)).isAir() && !(this.getTarget() instanceof Raider)) {
        this.totalCool = Mth.nextInt(this.random, 6, 10);
        for (int i = 0; i < this.totalCool; ++i) {
            MobUtil.throwSnapFungus(this, level);
        }
        this.coolDown = MathHelper.secondsToTicks(this.totalCool);
        if (!this.isSilent()) {
            this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), this.getSoundSource(), 2.0F, 0.8F + this.random.nextFloat() * 0.4F);
        }
    } else {
        if (this.level instanceof ServerLevel) {
            if (this.isAlliedTarget(target) && this.getTarget() != target) {
                if (!this.isSilent()) {
                    this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), this.getSoundSource(), 2.0F, 0.8F + this.random.nextFloat() * 0.4F);
                }
                Vec3 vec3 = target.getDeltaMovement();
                double d0 = target.getX() + vec3.x - this.getX();
                double d1 = target.getEyeY() - (double)1.1F - this.getY();
                double d2 = target.getZ() + vec3.z - this.getZ();
                double d3 = Math.sqrt(d0 * d0 + d2 * d2);
                BerserkFungus berserkFungus = new BerserkFungus(this, this.level);
                berserkFungus.setXRot(berserkFungus.getXRot() - 20.0F);
                berserkFungus.shoot(d0, d1 + d3 * 0.2D, d2, 0.75F, 8.0F);
                this.level.addFreshEntity(berserkFungus);
            } else {
                Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), this.level);
                wartling.setTarget(target);
                if (this.isInFluidType()){
                    wartling.setPos(this.getX(), this.getY(0.5F), this.getZ());
                    wartling.setXRot(this.getXRot());
                    wartling.setYRot(this.getYRot());
                    double d0 = target.getX() - wartling.getX();
                    double d1 = target.getY(0.3333333333333333D) - wartling.getY();
                    double d2 = target.getZ() - wartling.getZ();
                    double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                    MobUtil.shoot(wartling, d0, d1 + d3 * (double)0.2F, d2, 1.6F, 1.0F);
                } else {
                    wartling.moveTo(this.blockPosition(), this.getYRot(), this.getXRot());
                }
                this.summonWartlings(wartling);
            }
        }
    }
}

private void finishConversion(ServerLevel p_34399_) {
    Villager villager = this.convertTo(EntityType.VILLAGER, false);

    if (villager == null){
        return;
    }
    for(EquipmentSlot equipmentslot : EquipmentSlot.values()) {
        ItemStack itemstack = this.getItemBySlot(equipmentslot);
        if (!itemstack.isEmpty()) {
            if (EnchantmentHelper.hasBindingCurse(itemstack)) {
                villager.getSlot(equipmentslot.getIndex() + 300).set(itemstack);
            } else {
                double d0 = (double)this.getEquipmentDropChance(equipmentslot);
                if (d0 > 1.0D) {
                    this.spawnAtLocation(itemstack);
                }
            }
        }
    }

    villager.setVillagerData(this.getVillagerData());
    if (this.gossips != null) {
        villager.setGossips(this.gossips);
    }

    if (this.tradeOffers != null) {
        villager.setOffers(new MerchantOffers(this.tradeOffers));
    }

    villager.setVillagerXp(this.villagerXp);
    villager.finalizeSpawn(p_34399_, p_34399_.getCurrentDifficultyAt(villager.blockPosition()), MobSpawnType.CONVERSION, (SpawnGroupData)null, (CompoundTag)null);
    villager.refreshBrain(p_34399_);
    if (this.conversionStarter != null) {
        Player player = p_34399_.getPlayerByUUID(this.conversionStarter);
        if (player instanceof ServerPlayer) {
            p_34399_.onReputationEvent(ReputationEventType.ZOMBIE_VILLAGER_CURED, player, villager);
        }
    }

    villager.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 200, 0));
    if (!this.isSilent()) {
        p_34399_.levelEvent((Player)null, 1027, this.blockPosition(), 0);
    }
    net.minecraftforge.event.ForgeEventFactory.onLivingConvert(this, villager);
}

