public void attackGoal(){
    this.goalSelector.addGoal(4, new ModMeleeAttackGoal(this, 1.0D, true){

        @Override
        public boolean canUse() {
            return super.canUse() && this.mob instanceof AbstractBroodMother broodMother && !broodMother.isCircling;
        }

        @Override
        public boolean canContinueToUse() {
            return super.canContinueToUse() && this.mob instanceof AbstractBroodMother broodMother && !broodMother.isCircling;
        }

        protected void checkAndPerformAttack(LivingEntity livingEntity, double distToEnemySqr) {
            double d0 = this.getAttackReachSqr(livingEntity);
            this.mob.getLookControl().setLookAt(livingEntity, 100.0F, 100.0F);
            if (distToEnemySqr <= d0 && this.isTimeToAttack()) {
                int i = 0;
                float angle = 2.0F;
                double radius = 2.0D;
                double extraX = this.mob.getX() + 0.8D * Math.sin((double)(-this.mob.getYRot()) * Math.PI / 180.0D) + (double)angle * Math.sin((double)(-this.mob.yHeadRot) * Math.PI / 180.0D) * Math.cos((double)(-this.mob.getXRot()) * Math.PI / 180.0D);
                double extraZ = this.mob.getZ() + 0.8D * Math.cos((double)(-this.mob.getYRot()) * Math.PI / 180.0D) + (double)angle * Math.cos((double)(-this.mob.yHeadRot) * Math.PI / 180.0D) * Math.cos((double)(-this.mob.getXRot()) * Math.PI / 180.0D);
                List<LivingEntity> list = this.mob.level.getEntitiesOfClass(LivingEntity.class, new AABB(extraX - radius, this.mob.getY(), extraZ - radius, extraX + radius, this.mob.getY() + radius, extraZ + radius));
                for (LivingEntity target : list) {
                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target) && !MobUtil.areAllies(this.mob, target)) {
                        if (this.mob.doHurtTarget(target) || target.isBlocking()) {
                            ++i;
                        }
                    }
                }
                if (i > 0) {
                    this.mob.swing(InteractionHand.MAIN_HAND);
                    this.mob.playSound(ModSounds.SWING.get(), 2.0F, 0.5F);
                }
                this.resetAttackCooldown();
            }

        }

        @Override
        protected double getAttackReachSqr(LivingEntity target) {
            return this.mob.getBbWidth() * 1.25D * this.mob.getBbWidth() * 1.25D + target.getBbWidth();
        }
    });
}

public void silentDie(DamageSource cause){
    super.die(cause);
    if (this.level instanceof ServerLevel serverLevel){
        serverLevel.sendParticles(new PortalShockwaveParticleOption(), this.getX(), this.getY(), this.getZ(), 0, 0, 0, 0, 0);
        ServerParticleUtil.blockBreakParticles(this.getParticles(), BlockPos.containing(this.position()), this.getState(), serverLevel);
        ServerParticleUtil.blockBreakParticles(this.getParticles(), BlockPos.containing(this.position()).above(), this.getState(), serverLevel);
        ServerParticleUtil.blockBreakParticles(this.getParticles(), BlockPos.containing(this.position()).above().above(), Blocks.CRYING_OBSIDIAN.defaultBlockState(), serverLevel);
        new SpellExplosion(this.level, null, this.damageSources().magic(), this.blockPosition(), 16, 5.0F){
            @Override
            public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                if (target instanceof IOwned owned && target instanceof LivingEntity living){
                    if (owned.getTrueOwner() == AbstractObsidianMonolith.this.getTrueOwner() || owned.getTrueOwner() == AbstractObsidianMonolith.this){
                        if (!(owned instanceof AbstractObsidianMonolith)) {
                            if (living.hurt(living.damageSources().magic(), AbstractObsidianMonolith.this.level.random.nextInt(10) + 5.0F)){
                                AbstractObsidianMonolith.this.launch(living, AbstractObsidianMonolith.this);
                            }
                        }
                    }
                }
                if (target instanceof ZombifiedPiglin piglin){
                    if (piglin.isAlive()){
                        piglin.spawnAnim();
                        piglin.discard();
                    }
                }
            }
        };
        if (cause.getEntity() instanceof Mob mob && mob.getTarget() == this && this.getTrueOwner() != null){
            mob.setTarget(this.getTrueOwner());
            try {
                mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, this.getTrueOwner().getUUID(), 600L);
                mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, this.getTrueOwner(), 600L);
                if (mob instanceof Warden warden) {
                    warden.increaseAngerAt(this.getTrueOwner(), AngerLevel.ANGRY.getMinimumAnger() + 20, false);
                    warden.setAttackTarget(this.getTrueOwner());
                }
            } catch (NullPointerException ignored) {
            }
        }
        if (this.getTrueOwner() instanceof Apostle apostle && apostle.isAlive()){
            apostle.setMonolithCoolDown(MathHelper.minutesToTicks(1));
        }
    }
    this.remove(RemovalReason.KILLED);
}

private void applySplash(List<MobEffectInstance> mobEffectInstances, List<BrewEffectInstance> brewEffectInstances, @Nullable Entity hitEntity) {
    ItemStack itemstack = this.getItem();
    int area = BrewUtils.getAreaOfEffect(itemstack) + 4;
    int areaSqr = Mth.square(area);
    AABB aabb = this.getBoundingBox().inflate(area, area / 2.0D, area);
    List<LivingEntity> list = this.level.getEntitiesOfClass(LivingEntity.class, aabb);
    if (!list.isEmpty()) {
        Entity entity = this.getEffectSource();

        for(LivingEntity livingentity : list) {
            if (livingentity.isAffectedByPotions()) {
                double d0 = this.distanceToSqr(livingentity);
                if (d0 < areaSqr) {
                    double d1 = 1.0D - Math.sqrt(d0) / areaSqr;
                    if (livingentity == hitEntity) {
                        d1 = 1.0D;
                    }

                    if (!mobEffectInstances.isEmpty()) {
                        for (MobEffectInstance mobeffectinstance : mobEffectInstances) {
                            MobEffect mobeffect = mobeffectinstance.getEffect();
                            if (mobeffect.isInstantenous()) {
                                mobeffect.applyInstantenousEffect(this, this.getOwner(), livingentity, mobeffectinstance.getAmplifier(), d1);
                            } else {
                                int i = (int) (d1 * (double) mobeffectinstance.getDuration() + 0.5D);
                                if (i > 20) {
                                    livingentity.addEffect(new MobEffectInstance(mobeffect, i, mobeffectinstance.getAmplifier(), mobeffectinstance.isAmbient(), mobeffectinstance.isVisible()), entity);
                                }
                            }
                        }
                    }
                    if (!brewEffectInstances.isEmpty()) {
                        for (BrewEffectInstance brewEffectInstance : brewEffectInstances) {
                            BrewEffect brewEffect = brewEffectInstance.getEffect();
                            if (brewEffect.isInstantenous()) {
                                brewEffect.applyInstantenousEffect(this, this.getOwner(), livingentity, brewEffectInstance.getAmplifier(), d1);
                            }
                        }
                    }
                }
            }
        }
    }

}

