public void aiStep() {
    super.aiStep();
    if (this.isAlive()) {
        AttributeInstance speed = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (speed != null) {
            if (this.getTarget() != null) {
                if (!speed.hasModifier(SPEED_BOOST)) {
                    speed.addPermanentModifier(SPEED_BOOST);
                }
            } else {
                if (speed.hasModifier(SPEED_BOOST)) {
                    speed.removeModifier(SPEED_BOOST);
                }
            }
        }
        if (this.bitingTick > 0) {
            --this.bitingTick;
        }

        if (!this.level.isClientSide && this.isAlive() && !this.isNoAi()){
            if (this.isConverting()) {
                --this.conversionTime;
                if (this.conversionTime < 0) {
                    this.doRavagerConversion();
                }
            } else if (this.getAttributeValue(Attributes.MAX_HEALTH) >= 75.0D) {
                this.startConversion(300);
            }
        }

        if (this.level.isClientSide){
            if (this.getRavagedSize() >= 4) {
                if (this.getDeltaMovement().horizontalDistanceSqr() > (double) 2.5000003E-7F && this.random.nextInt(5) == 0) {
                    int i = Mth.floor(this.getX());
                    int j = Mth.floor(this.getY() - (double) 0.2F);
                    int k = Mth.floor(this.getZ());
                    BlockPos pos = new BlockPos(i, j, k);
                    BlockState blockstate = this.level.getBlockState(pos);
                    if (!blockstate.isAir()) {
                        this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, blockstate).setPos(pos), this.getX() + ((double) this.random.nextFloat() - 0.5D) * (double) this.getBbWidth(), this.getY() + 0.1D, this.getZ() + ((double) this.random.nextFloat() - 0.5D) * (double) this.getBbWidth(), 4.0D * ((double) this.random.nextFloat() - 0.5D), 0.5D, ((double) this.random.nextFloat() - 0.5D) * 4.0D);
                    }
                }
            }
        }
    }
}

protected void onHitEntity(EntityHitResult pResult) {
    Entity target = pResult.getEntity();
    float f = 6.0F;
    float f1 = 0.0F;
    int i = 0;
    Entity owner = this.getOwner();
    if (this.getItem().getItem() instanceof SwordItem swordItem){
        f = swordItem.getDamage();
    }
    if (!this.getItem().isEmpty()) {
        f1 += this.getItem().getEnchantmentLevel(Enchantments.KNOCKBACK);
        i = this.getItem().getEnchantmentLevel(Enchantments.FIRE_ASPECT);
    }
    if (target instanceof LivingEntity livingentity) {
        f += EnchantmentHelper.getDamageBonus(this.getItem(), livingentity.getMobType());
    }
    DamageSource damagesource = ModDamageSource.sword(this, owner == null ? this : owner);
    if (owner instanceof Player player){
        damagesource = this.damageSources().playerAttack(player);
    } else if (owner instanceof Mob mob){
        damagesource = this.damageSources().mobAttack(mob);
    }
    SoundEvent soundevent = SoundEvents.TRIDENT_HIT;
    if (target.hurt(damagesource, f)) {
        if (target instanceof LivingEntity livingTarget) {
            if (owner instanceof LivingEntity) {
                EnchantmentHelper.doPostHurtEffects(livingTarget, owner);
                EnchantmentHelper.doPostDamageEffects((LivingEntity)owner, livingTarget);
                ItemHelper.setItemEffect(this.getItem(), livingTarget);
            }
            if (f1 > 0) {
                double d0 = this.getX() - livingTarget.getX();
                double d1 = this.getZ() - livingTarget.getZ();
                livingTarget.knockback(f1 * 0.5F, d0, d1);
            }
            if (i > 0) {
                livingTarget.setSecondsOnFire(i * 4);
            }

            this.doPostHurtEffects(livingTarget);
        }
    }

    float f2 = 1.0F;
    this.playSound(soundevent, f2, 1.0F);
}

public static void applySplash(LivingEntity livingEntity, ItemStack itemStack, @Nullable Entity target, BlockPos blockPos, List<MobEffectInstance> mobEffectInstances, List<BrewEffectInstance> brewEffectInstances) {
    int area = BrewUtils.getAreaOfEffect(itemStack) + 4;
    int areaSqr = Mth.square(area);
    Vec3 vec3 = blockPos.getCenter();
    if (target != null){
        vec3 = target.position();
    }
    AABB aabb = makeBoundingBox(vec3.x, vec3.y, vec3.z).inflate(area, area / 2.0D, area);
    List<LivingEntity> list = livingEntity.level.getEntitiesOfClass(LivingEntity.class, aabb);
    if (!list.isEmpty()) {
        for(LivingEntity livingTarget : list) {
            if (livingTarget.isAffectedByPotions()) {
                double d0 = vec3.distanceToSqr(livingTarget.position());
                if (d0 < areaSqr) {
                    double d1 = 1.0D - Math.sqrt(d0) / areaSqr;
                    if (livingTarget == target) {
                        d1 = 1.0D;
                    }

                    if (!mobEffectInstances.isEmpty()) {
                        for (MobEffectInstance mobeffectinstance : mobEffectInstances) {
                            MobEffect mobeffect = mobeffectinstance.getEffect();
                            if (mobeffect.isInstantenous()) {
                                mobeffect.applyInstantenousEffect(livingEntity, livingEntity, livingTarget, mobeffectinstance.getAmplifier(), d1);
                            } else {
                                int i = (int) (d1 * (double) mobeffectinstance.getDuration() + 0.5D);
                                if (i > 20) {
                                    livingTarget.addEffect(new MobEffectInstance(mobeffect, i, mobeffectinstance.getAmplifier(), mobeffectinstance.isAmbient(), mobeffectinstance.isVisible()), livingEntity);
                                }
                            }
                        }
                    }
                    if (!brewEffectInstances.isEmpty()) {
                        for (BrewEffectInstance brewEffectInstance : brewEffectInstances) {
                            BrewEffect brewEffect = brewEffectInstance.getEffect();
                            if (brewEffect.isInstantenous()) {
                                brewEffect.applyInstantenousEffect(livingEntity, livingEntity, livingTarget, brewEffectInstance.getAmplifier(), d1);
                            }
                        }
                    }
                }
            }
        }
    }

}

public static void onLivingAttackEvent(LivingAttackEvent event){

	// Retaliatory effects
	// These are better off here because the revenge effects are pretty similar, and I'd rather keep the (lengthy)
	// if statement in one place.
	if(event.getSource() != null && event.getSource().getTrueSource() instanceof EntityLivingBase
			&& !event.getSource().isProjectile() && !(event.getSource() instanceof IElementalDamage
					&& ((IElementalDamage)event.getSource()).isRetaliatory())){

		EntityLivingBase attacker = (EntityLivingBase)event.getSource().getTrueSource();
		World world = event.getEntityLiving().world;

		if(attacker.getDistance(event.getEntityLiving()) < 10){

			// Fireskin
			if(event.getEntityLiving().isPotionActive(WizardryPotions.fireskin)
					&& !MagicDamage.isEntityImmune(DamageType.FIRE, event.getEntityLiving()))
				attacker.setFire(Spells.fire_breath.getProperty(Spell.BURN_DURATION).intValue() * 20);

			// Ice Shroud
			if(event.getEntityLiving().isPotionActive(WizardryPotions.ice_shroud)
					&& !MagicDamage.isEntityImmune(DamageType.FROST, event.getEntityLiving())
					&& !(attacker instanceof FakePlayer)) // Fake players cause problems
				if(!world.isRemote) attacker.addPotionEffect(new PotionEffect(WizardryPotions.frost,
						Spells.ice_shroud.getProperty(Spell.EFFECT_DURATION).intValue(),
						Spells.ice_shroud.getProperty(Spell.EFFECT_STRENGTH).intValue()));

			// Static Aura
			if(event.getEntityLiving().isPotionActive(WizardryPotions.static_aura)){

				if(world.isRemote){

					ParticleBuilder.create(Type.LIGHTNING).entity(event.getEntity()).pos(0, event.getEntity().height / 2, 0)
							.target(attacker).spawn(world);

					ParticleBuilder.spawnShockParticles(world, attacker.posX,
							attacker.posY + attacker.height / 2, attacker.posZ);
				}

				DamageSafetyChecker.attackEntitySafely(attacker, MagicDamage.causeDirectMagicDamage(event.getEntityLiving(),
						DamageType.SHOCK, true), Spells.static_aura.getProperty(Spell.DAMAGE).floatValue(), event.getSource().getDamageType());
				attacker.playSound(WizardrySounds.SPELL_STATIC_AURA_RETALIATE, 1.0F, world.rand.nextFloat() * 0.4F + 1.5F);
			}
		}
	}

}

public void tick() {
    super.tick();
    if (!this.level.isClientSide){
        if (this.getTarget() != null){
            if (!this.isWebShooting()){
                this.stopMoving = false;
                if (!this.getTarget().hasEffect(GoetyEffects.TANGLED.get())) {
                    if (this.distanceTo(this.getTarget()) <= 5.0F) {
                        this.isFleeing = true;
                        Vec3 vec3 = DefaultRandomPos.getPosAway(this, 7, 5, this.getTarget().position());
                        if (vec3 != null) {
                            this.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 1.25F);
                        }
                    } else {
                        this.isFleeing = false;
                    }
                } else {
                    this.isFleeing = false;
                    this.setClimbing(false);
                }
            } else {
                this.isFleeing = false;
            }
        } else {
            this.isFleeing = false;
            this.stopMoving = false;
        }
        AttributeInstance modifiableattributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (this.stopMoving) {
            if (modifiableattributeinstance != null) {
                modifiableattributeinstance.removeModifier(SHOOT_SPEED_MODIFIER);
                modifiableattributeinstance.addTransientModifier(SHOOT_SPEED_MODIFIER);
            }
        } else {
            if (modifiableattributeinstance != null) {
                if (modifiableattributeinstance.hasModifier(SHOOT_SPEED_MODIFIER)) {
                    modifiableattributeinstance.removeModifier(SHOOT_SPEED_MODIFIER);
                }
            }
        }
        if (this.shootAnim > 0) {
            --this.shootAnim;
        } else {
            this.setAnimationState(IDLE);
        }
    }
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	double range = getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade);

	RayTraceResult rayTrace = RayTracer.standardBlockRayTrace(world, caster, range, false);

	if(rayTrace != null && rayTrace.typeOfHit == RayTraceResult.Type.BLOCK){

		BlockPos pos = rayTrace.getBlockPos().offset(rayTrace.sideHit);

		if(world.isAirBlock(pos)){

			if(!world.isRemote){
				world.setBlockState(pos, WizardryBlocks.magic_light.getDefaultState());
				if(world.getTileEntity(pos) instanceof TileEntityTimer){
					int lifetime = ItemArtefact.isArtefactActive(caster, WizardryItems.charm_light) ? -1
							: (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
					((TileEntityTimer)world.getTileEntity(pos)).setLifetime(lifetime);
				}
			}

			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}
	}else{

		int x = (int)(Math.floor(caster.posX) + caster.getLookVec().x * range);
		int y = (int)(Math.floor(caster.posY) + caster.eyeHeight + caster.getLookVec().y * range);
		int z = (int)(Math.floor(caster.posZ) + caster.getLookVec().z * range);

		BlockPos pos = new BlockPos(x, y, z);

		if(world.isAirBlock(pos)){
			if(!world.isRemote){
				world.setBlockState(pos, WizardryBlocks.magic_light.getDefaultState());
				if(world.getTileEntity(pos) instanceof TileEntityTimer){
					int lifetime = ItemArtefact.isArtefactActive(caster, WizardryItems.charm_light) ? -1
							: (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
					((TileEntityTimer)world.getTileEntity(pos)).setLifetime(lifetime);
				}
			}

			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}
	}
	return false;
}

protected boolean spawnMinions(World world, EntityLivingBase caster, SpellModifiers modifiers){

	if(!world.isRemote){
		for(int i=0; i<getProperty(MINION_COUNT).intValue(); i++){

			int range = getProperty(SUMMON_RADIUS).intValue();

			// Try and find a nearby floor space
			BlockPos pos = BlockUtils.findNearbyFloorSpace(caster, range, range*2);

			if(flying){
				if(pos != null){
					// Make sure the flying entity spawns above the ground
					pos = pos.up(2); // Adding 2 will suffice, it's not exactly a game-changer...
				}else{
					// If there was no floor around to spawn them on, just pick any spot in mid-air
					pos = caster.getPosition().north(world.rand.nextInt(range*2) - range)
							.east(world.rand.nextInt(range*2) - range);
				}
			}else{
				// If there was no floor around and the entity isn't a flying one, the spell fails.
				// As per the javadoc for findNearbyFloorSpace, there's no point trying the rest of the minions.
				if(pos == null) return false;
			}

			T minion = createMinion(world, caster, modifiers);

			minion.setPosition(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5);
			minion.setCaster(caster);
			// Modifier implementation
			// Attribute modifiers are pretty opaque, see https://minecraft.gamepedia.com/Attribute#Modifiers
			minion.setLifetime((int)(getProperty(MINION_LIFETIME).floatValue() * modifiers.get(WizardryItems.duration_upgrade)));
			IAttributeInstance attribute = minion.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE);
			if(attribute != null) attribute.applyModifier( // Apparently some things don't have an attack damage
					new AttributeModifier(POTENCY_ATTRIBUTE_MODIFIER, modifiers.get(SpellModifiers.POTENCY) - 1, EntityUtils.Operations.MULTIPLY_CUMULATIVE));
			// This is only used for artefacts, but it's a nice example of custom spell modifiers
			minion.getEntityAttribute(SharedMonsterAttributes.MAX_HEALTH).applyModifier(
					new AttributeModifier(HEALTH_MODIFIER, modifiers.get(HEALTH_MODIFIER) - 1, EntityUtils.Operations.MULTIPLY_CUMULATIVE));
			minion.setHealth(minion.getMaxHealth()); // Need to set this because we may have just modified the value

			this.addMinionExtras(minion, pos, caster, modifiers, i);

			world.spawnEntity(minion);
		}
	}

	return true;
}

public void summonGolem(){
    if (this.level != null) {
        if (this.getPosition() != null) {
            if (this.level.dimension() == this.getPosition().dimension()) {
                if (this.level.isLoaded(this.getPosition().pos())) {
                    if (this.checkCage() && this.cursedCageTile.getSouls() >= this.getSoulCost()) {
                        ItemStack itemStack = ModItems.ANIMATION_CORE.get().getDefaultInstance();
                        BlockState blockState = this.level.getBlockState(this.getPosition().pos());
                        AABB aabb = new AABB(this.getPosition().pos());
                        List<HauntedArmorStand> list = this.level.getEntitiesOfClass(HauntedArmorStand.class, aabb, ItemHelper::isFullEquipped);
                        Optional<HauntedArmorStand> optional = !list.isEmpty() ? list.stream().findFirst() : Optional.empty();
                        if (optional.isPresent() && SEHelper.hasResearch(this.getOwner(), ResearchList.HAUNTING)){
                            HauntedArmorStand hauntedArmorStand = optional.get();
                            HauntedArmorServant hauntedArmorServant = new HauntedArmorServant(ModEntityType.HAUNTED_ARMOR_SERVANT.get(), this.level);
                            for (EquipmentSlot equipmentSlot : EquipmentSlot.values()) {
                                hauntedArmorServant.setItemSlot(equipmentSlot, hauntedArmorStand.getItemBySlot(equipmentSlot));
                                hauntedArmorServant.setGuaranteedDrop(equipmentSlot);
                            }
                            hauntedArmorServant.setPersistenceRequired();
                            hauntedArmorServant.setTrueOwner(this.getOwner());
                            hauntedArmorServant.moveTo(hauntedArmorStand.blockPosition(), hauntedArmorStand.getYRot(), hauntedArmorStand.getXRot());
                            hauntedArmorServant.setLeftHanded(this.getOwner().getMainArm() == HumanoidArm.LEFT);
                            if (this.level.addFreshEntity(hauntedArmorServant)) {
                                hauntedArmorStand.playSound(ModSounds.SUMMON_SPELL.get());
                                hauntedArmorStand.showBreakingParticles();
                                hauntedArmorStand.discard();
                            }
                        } else if (GolemType.getGolemList().containsKey(blockState)) {
                            if (GolemType.getGolemList().get(blockState).spawnServant(this.getOwner(), itemStack, this.level, this.getPosition().pos())) {
                                this.level.playSound(null, this.getBlockPos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                this.level.playSound(null, this.getPosition().pos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                this.cursedCageTile.decreaseSouls(this.getSoulCost());
                                this.generateManyParticles();
                            }
                        } else {
                            if (SpawnFromBlock.spawnServant(this.getOwner(), itemStack, this.level, this.getPosition().pos())) {
                                this.level.playSound(null, this.getBlockPos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                this.level.playSound(null, this.getPosition().pos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                this.cursedCageTile.decreaseSouls(this.getSoulCost());
                                this.generateManyParticles();
                            }
                        }
                    }
                }
            }
        }
    }
}

protected void onHit(HitResult result) {
	if (!this.level().isClientSide) {

		this.clearInvincibility();

		if (result.getType() == HitResult.Type.ENTITY) {
			Entity entity = ((EntityHitResult) result).getEntity();

			if (entity == this.getOwner())
				return;

			if (this.getOwner() != null) {
				if (entity.hurt(entity.damageSources().indirectMagic(this, this.getOwner()), this.isSkullInvulnerable() ? 24.0F : 8.0F)) {
					if (entity.isAlive()) {
						this.doEnchantDamageEffects((LivingEntity) this.getOwner(), entity);
					}
				}
			} else {
				entity.hurt(entity.damageSources().magic(), this.isSkullInvulnerable() ? 16.0F : 5.0F);
			}

			if (entity instanceof LivingEntity) {

				((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.WITHER, 20 * 30, 1));

			}
		}

		float explosionRadius = this.isSkullInvulnerable() ? 1.5F : 1.0F;
		WitherExplosion explosion = new WitherExplosion(this.level(), this, this.getX(), this.getY(), this.getZ(), explosionRadius, false, Explosion.BlockInteraction.DESTROY);


		if (!net.minecraftforge.event.ForgeEventFactory.onExplosionStart(this.level(), explosion)) {
			explosion.explode();
			explosion.finalizeExplosion(true);

			for(ServerPlayer serverPlayer : this.level().getServer().getLevel(this.level().dimension()).players()) {
				if (serverPlayer.distanceToSqr(explosion.getPosition().x, explosion.getPosition().y, explosion.getPosition().z) < 4096.0D) {
					serverPlayer.connection.send(new ClientboundExplodePacket(explosion.getPosition().x, explosion.getPosition().y, explosion.getPosition().z, explosionRadius, explosion.getToBlow(), explosion.getHitPlayers().get(serverPlayer)));
				}
			}
		}

		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketWitherParticles(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), this.isSkullInvulnerable() ? 20 : 16, false));

		this.discard();
	}

}

protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(EntityUtils.isLiving(target)){

		if(!canControl(target)){
			if(!world.isRemote){
				if(caster instanceof EntityPlayer){
					// Adds a message saying that the player/boss entity/wizard resisted mind control
					((EntityPlayer)caster).sendStatusMessage(new TextComponentTranslation("spell.resist", target.getName(),
							this.getNameForTranslationFormatted()), true);
				}
			}

		}else if(target instanceof EntityLiving){

			if(!world.isRemote){
				if(!MindControl.findMindControlTarget((EntityLiving)target, caster, world)){
					// If no valid target was found, this just acts like mind trick.
					((EntityLiving)target).setAttackTarget(null);
				}
			}

			if(target instanceof EntitySheep && ((EntitySheep)target).getFleeceColor() == EnumDyeColor.BLUE
					&& EntityUtils.canDamageBlocks(caster, world)){
				if(!world.isRemote) ((EntitySheep)target).setFleeceColor(EnumDyeColor.RED); // Wololo!
				world.playSound(caster.posX, caster.posY, caster.posZ, SoundEvents.EVOCATION_ILLAGER_PREPARE_WOLOLO, WizardrySounds.SPELLS, 1, 1, false);
			}

			if(!world.isRemote) startControlling((EntityLiving)target, caster,
					(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade)));
		}

		if(world.isRemote){

			for(int i=0; i<10; i++){
				ParticleBuilder.create(Type.DARK_MAGIC, world.rand, target.posX,
						target.posY + target.getEyeHeight(), target.posZ, 0.25, false)
				.clr(0.8f, 0.2f, 1.0f).spawn(world);
				ParticleBuilder.create(Type.DARK_MAGIC, world.rand, target.posX,
						target.posY + target.getEyeHeight(), target.posZ, 0.25, false)
				.clr(0.2f, 0.04f, 0.25f).spawn(world);
			}
		}

		return true;
	}

	return false;
}

public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand, BlockHitResult pHit) {
    if (pState.hasBlockEntity()) {
        BlockEntity tileEntity = pLevel.getBlockEntity(pPos);
        if (tileEntity instanceof ArcaBlockEntity arcaTileEntity) {
            if (arcaTileEntity.getPlayer() == pPlayer) {
                ISoulEnergy soulEnergy = SEHelper.getCapability(arcaTileEntity.getPlayer());
                ItemStack itemStack = pPlayer.getMainHandItem();
                if (itemStack.isEmpty()) {
                    if (!pPlayer.isShiftKeyDown() && !pPlayer.isCrouching()){
                        if (soulEnergy.getArcaBlock() == null){
                            soulEnergy.setArcaBlock(arcaTileEntity.getBlockPos());
                            soulEnergy.setArcaBlockDimension(pLevel.dimension());
                            if (!soulEnergy.getSEActive()){
                                soulEnergy.setSEActive(true);
                            }
                            SEHelper.sendSEUpdatePacket(arcaTileEntity.getPlayer());
                            return InteractionResult.SUCCESS;
                        }
                    } else {
                        pLevel.destroyBlock(pPos, true);
                        return InteractionResult.sidedSuccess(pLevel.isClientSide);
                    }
                } else if (itemStack.is(ModItems.WAYSTONE.get())) {
                    if (WaystoneItem.isSameDimension(tileEntity, itemStack)){
                        BlockPos blockPos = WaystoneItem.getBlockPos(itemStack);
                        if (blockPos != null && soulEnergy.getArcaRevivePos() != blockPos) {
                            if (blockPos.distToCenterSqr(pPos.getCenter()) <= Mth.square(8)) {
                                soulEnergy.setArcaRevivePos(blockPos);
                                SEHelper.sendSEUpdatePacket(pPlayer);
                                if (pLevel instanceof ServerLevel) {
                                    ModNetwork.sendTo(pPlayer, new SPlayPlayerSoundPacket(SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, 1.0F, 1.0F));
                                }
                                pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.revivePos"), true);
                                return InteractionResult.sidedSuccess(pLevel.isClientSide);
                            } else {
                                pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.difDimension"), true);
                                return InteractionResult.FAIL;
                            }
                        }
                    } else {
                        pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.difDimension"), true);
                        return InteractionResult.FAIL;
                    }
                }
            }
        }
    }
    return InteractionResult.PASS;
}

public void tick() {
    this.witch.setTarget(null);
    LivingEntity trader = WitchBarterHelper.getTrader(witch);
    if (--this.progress > 0) {
        this.witch.getNavigation().stop();
        if (trader != null && this.witch.distanceTo(trader) <= 16.0F) {
            this.witch.getLookControl().setLookAt(trader);
        }
    }
    if (this.progress <= 0) {
        Vec3 vec3 = trader != null ? trader.position() : this.witch.position();
        if (!this.witch.level.isClientSide) {
            if (this.witch.level.getServer() != null) {
                float luck = 0.0F;
                if (this.witch.getMainHandItem().is(ModTags.Items.WITCH_BETTER_CURRENCY)){
                    luck = 1.0F;
                }
                LootTable loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.WITCH_BARTER);
                if (this.witch instanceof Warlock){
                    loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.WARLOCK_BARTER);
                }
                if (this.witch instanceof Heretic){
                    loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.HERETIC_BARTER);
                }
                if (this.witch instanceof Reprobate){
                    loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.REPROBATE_BARTER);
                }
                if (this.witch instanceof Crone){
                    loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.CRONE_BARTER);
                }
                if (this.witch instanceof Heresiarch){
                    loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.HERESIARCH_BARTER);
                }
                List<ItemStack> list = loottable.getRandomItems((new LootParams.Builder((ServerLevel) this.witch.level)).withParameter(LootContextParams.THIS_ENTITY, this.witch).withParameter(LootContextParams.ORIGIN, this.witch.position()).withLuck(luck).create(LootContextParamSets.GIFT));
                for(ItemStack itemstack : list) {
                    BehaviorUtils.throwItem(this.witch, itemstack, vec3.add(0.0D, 1.0D, 0.0D));
                }
            }
        }
        this.clearTrade();
    }

    if (this.witch.hurtTime != 0){
        if (this.witch.getItemInHand(InteractionHand.MAIN_HAND).is(ModTags.Items.WITCH_CURRENCY)) {
            this.witch.spawnAtLocation(this.witch.getItemInHand(InteractionHand.MAIN_HAND));
            this.clearTrade();
        }
    }
}

public void tick() {
    super.tick();
    if (!this.level.isClientSide){
        if (!this.isMeleeAttacking() && !this.isSmashing()){
            if (!this.isMoving()){
                this.setAnimationState("idle");
            } else {
                this.setAnimationState("walk");
            }
        }
        if (this.attackCool > 0){
            --this.attackCool;
            this.navigation.stop();
        } else {
            if (this.isMeleeAttacking()){
                ++this.attackTick;
                if (this.attackTick >= 20){
                    this.attackCool = 10;
                    this.setMeleeAttacking(false);
                }
            } else {
                this.attackTick = 0;
            }
            if (this.isSmashing()){
                ++this.smashTick;
                if (this.smashTick == 19){
                    new FrostNovaSpell().mobSpellResult(this, ItemStack.EMPTY);
                }
                if (this.smashTick >= MathHelper.secondsToTicks(2.5F)){
                    this.attackCool = 10;
                    this.setSmashing(false);
                }
            } else {
                this.smashTick = 0;
            }
        }
        if (this.isUpgraded()){
            if (this.level instanceof ServerLevel serverLevel){
                ServerParticleUtil.addAuraParticles(serverLevel, ParticleTypes.SNOWFLAKE, this, 1.0F);
                for (LivingEntity living : serverLevel.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0F))) {
                    if (!living.isFreezing() && living.canFreeze() && MobUtil.validEntity(living) && !MobUtil.areAllies(this, living)) {
                        ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.SNOWFLAKE, living);
                        living.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), 100, 0));
                    }
                }
            }
        }
    }
}

public AbstractArrow getArrow(ItemStack pArrowStack, float pDistanceFactor) {
    DeathArrow deathArrow = new DeathArrow(this.level, this);
    deathArrow.setEffectsFromItem(pArrowStack);
    deathArrow.setEnchantmentEffectsFromEntity(this, pDistanceFactor);
    if (this.getArrowEffect() != null){
        MobEffect mobEffect = this.getArrowEffect();
        int amp;
        if (this.isSecondPhase() && this.getArrowEffect() != MobEffects.HARM){
            amp = 1;
        } else {
            amp = 0;
        }
        if (this.getTarget() != null && this.getArrowEffect() == MobEffects.HARM && this.getTarget().isInvertedHealAndHarm()){
            mobEffect = MobEffects.HEAL;
        }
        if (this.isSecondPhase()){
            if (this.getArrowEffect() == MobEffects.POISON){
                mobEffect = GoetyEffects.ACID_VENOM.get();
            }
            if (this.getArrowEffect() == MobEffects.DARKNESS){
                mobEffect = MobEffects.BLINDNESS;
            }
        }
        deathArrow.addEffect(new MobEffectInstance(mobEffect, mobEffect.isInstantenous() ? 1 : 200, amp));
    }
    if (this.getFireArrow()){
        deathArrow.setRemainingFireTicks(100);
    }
    if (MobsConfig.ApostleCritArrows.get()) {
        if (this.isInNether()) {
            deathArrow.setCritArrow(true);
        } else {
            float critChance = 0.05F;
            if (this.level.getDifficulty() == Difficulty.HARD) {
                critChance += 0.25F;
            }
            if (this.isSecondPhase()) {
                critChance += 0.1F;
            }
            if (this.isSecondPhase() && this.getHealth() <= this.getMaxHealth() / 4) {
                critChance += 0.25F;
            }
            if (this.level.random.nextFloat() <= critChance) {
                deathArrow.setCritArrow(true);
            }
        }
    }
    return deathArrow;
}

public void tick() {
    super.tick();
    if (!this.isNoGravity()) {
        MobUtil.moveDownToGround(this);
    }
    if (this.level instanceof ServerLevel serverWorld) {
        float f = 1.5F;
        float f5 = (float) Math.PI * f * f;
        if (this.tickCount == this.getLifeSpan()){
            if (!this.noParticles) {
                for (int j1 = 0; j1 < 16; ++j1) {
                    for (int k1 = 0; (float) k1 < f5; ++k1) {
                        float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        float f7 = Mth.sqrt(this.random.nextFloat()) * f;
                        float f8 = Mth.cos(f6) * f7;
                        float f9 = Mth.sin(f6) * f7;
                        serverWorld.sendParticles(ParticleTypes.REVERSE_PORTAL, this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 0, 0, 0.5D, 0, 0.5F);
                    }
                }
            }
            if (this.entity != null){
                if (this.noPos) {
                    this.entity.setPos(this.getX(), this.getY(), this.getZ());
                }
                if (this.preMade) {
                    if (this.entity instanceof TamableAnimal tamableAnimal && this.getOwnerId() != null) {
                        tamableAnimal.setOwnerUUID(this.getOwnerId());
                    }
                    if (this.entity instanceof IOwned owned && this.getTrueOwner() != null) {
                        owned.setTrueOwner(this.getTrueOwner());
                    }
                    if (this.entity instanceof Mob mob) {
                        ForgeEventFactory.onFinalizeSpawn(mob, serverWorld, this.level.getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                        if (this.getTrueOwner() != null && this.getTrueOwner() instanceof Mob mob1) {
                            if (mob1.getTarget() != null) {
                                mob.setTarget(mob1.getTarget());
                            }
                        }
                    }
                }
                serverWorld.addFreshEntity(this.entity);
            }
        }
    }
    if (this.tickCount >= this.getLifeSpan()){
        this.playSound(ModSounds.SUMMON_SPELL.get(), 1.0F, 1.0F);
        this.discard();
    }
}

public void tick() {
	if (this.getItem().isEmpty()) {
		this.discard();
	} else {
		if (!this.level().isClientSide && this.position != null) {
			if (!this.position().equals(this.position)) {
				this.teleportTo(this.position.x, this.position.y, this.position.z);
			}
		}

		super.tick();

		if (this.pickupDelay > 0 && this.pickupDelay != 32767) {
			--this.pickupDelay;
		}

		this.xo = this.getX();
		this.yo = this.getY();
		this.zo = this.getZ();
		Vec3 vec3d = this.getDeltaMovement();

		if (!this.isNoGravity()) {
			this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.04D, 0.0D));
		}

		if (this.level().isClientSide) {
			this.noPhysics = false;

			this.level().addParticle(ParticleTypes.PORTAL, this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), ((Math.random() - 0.5) * 2.0), ((Math.random() - 0.5) * 2.0), ((Math.random() - 0.5) * 2.0));
		}

		++this.age;

		if (!this.level().isClientSide) {
			double d0 = this.getDeltaMovement().subtract(vec3d).lengthSqr();
			if (d0 > 0.01D) {
				this.hasImpulse = true;
			}
		}

		ItemStack item = this.getItem();

		if (item.isEmpty()) {
			this.discard();
		}

		// Portal Cooldown
		this.setPortalCooldown();
	}
}

protected void onImpact(RayTraceResult rayTrace){

	if(!this.world.isRemote){

		Entity entityHit = rayTrace.entityHit;

		if(entityHit != null){
			// This is if the poison bomb gets a direct hit
			float damage = Spells.poison_bomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

			entityHit.attackEntityFrom(
					MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.POISON).setProjectile(),
					damage);

			if(!this.world.isRemote && entityHit instanceof EntityLivingBase && !MagicDamage.isEntityImmune(DamageType.POISON, entityHit))
				((EntityLivingBase)entityHit).addPotionEffect(new PotionEffect(MobEffects.POISON,
						Spells.poison_bomb.getProperty(Spell.DIRECT_EFFECT_DURATION).intValue(),
						Spells.poison_bomb.getProperty(Spell.DIRECT_EFFECT_STRENGTH).intValue()));
		}

		// Notify clients to play the explosion effect
		WizardryPacketHandler.net.sendToAllAround(
				new PacketBombExplosion.Message(PacketBombExplosion.POISON_BOMB, posX, posY, posZ, blastMultiplier),
				new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

		this.playSound(WizardrySounds.ENTITY_POISON_BOMB_SMASH, 1.5F, rand.nextFloat() * 0.4F + 0.6F);
		this.playSound(WizardrySounds.ENTITY_POISON_BOMB_POISON, 1.2F, 1.0f);

		double range = Spells.poison_bomb.getProperty(Spell.EFFECT_RADIUS).floatValue() * blastMultiplier;

		List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(range, this.posX, this.posY,
				this.posZ, this.world);

		for(EntityLivingBase target : targets){
			if(target != entityHit && target != this.getThrower()
					&& !MagicDamage.isEntityImmune(DamageType.POISON, target)){
				target.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.POISON),
						Spells.poison_bomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);
				if(!this.world.isRemote){
					target.addPotionEffect(new PotionEffect(MobEffects.POISON,
							Spells.poison_bomb.getProperty(Spell.SPLASH_EFFECT_DURATION).intValue(),
							Spells.poison_bomb.getProperty(Spell.SPLASH_EFFECT_STRENGTH).intValue()));
				}
			}
		}
	}

	this.setDead();
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	// Won't work if the weapon already has the enchantment
	if(WizardData.get(caster) != null){

		for(ItemStack stack : InventoryUtils.getPrioritisedHotbarAndOffhand(caster)){

			if(isSword(stack)
					&& !EnchantmentHelper.getEnchantments(stack).containsKey(WizardryEnchantments.magic_sword)
					&& WizardData.get(caster).getImbuementDuration(WizardryEnchantments.magic_sword) <= 0){
				// The enchantment level as determined by the damage multiplier. The + 0.5f is so that
				// weird float processing doesn't incorrectly round it down.
				stack.addEnchantment(WizardryEnchantments.magic_sword, modifiers.get(SpellModifiers.POTENCY) == 1.0f
						? 1
						: (int)((modifiers.get(SpellModifiers.POTENCY) - 1.0f) / Constants.POTENCY_INCREASE_PER_TIER
								+ 0.5f));
				WizardData.get(caster).setImbuementDuration(WizardryEnchantments.magic_sword,
						(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade)));

			}else if(isBow(stack)
					&& !EnchantmentHelper.getEnchantments(stack).containsKey(WizardryEnchantments.magic_bow)
					&& WizardData.get(caster).getImbuementDuration(WizardryEnchantments.magic_bow) <= 0){
				// The enchantment level as determined by the damage multiplier. The + 0.5f is so that
				// weird float processing doesn't incorrectly round it down.
				stack.addEnchantment(WizardryEnchantments.magic_bow, modifiers.get(SpellModifiers.POTENCY) == 1.0f
						? 1
						: (int)((modifiers.get(SpellModifiers.POTENCY) - 1.0f) / Constants.POTENCY_INCREASE_PER_TIER
								+ 0.5f));
				WizardData.get(caster).setImbuementDuration(WizardryEnchantments.magic_bow,
						(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade)));

			}else{
				continue;
			}

			if(world.isRemote){
				for(int i=0; i<10; i++){
					double x = caster.posX + world.rand.nextDouble() * 2 - 1;
					double y = caster.posY + caster.getEyeHeight() - 0.5 + world.rand.nextDouble();
					double z = caster.posZ + world.rand.nextDouble() * 2 - 1;
					ParticleBuilder.create(Type.SPARKLE).pos(x, y, z).vel(0, 0.1, 0).clr(0.9f, 0.7f, 1).spawn(world);
				}
			}

			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}
	}
	return false;
}

public void update(){

	if(lastUserUUID != null && lastUser == null) lastUser = world.getPlayerEntityByUUID(lastUserUUID);

	if(imbuementTimer > 0){

		if(imbuementTimer == 1){ // Has to be done here because of syncing
			world.playSound(pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5,
					WizardrySounds.BLOCK_IMBUEMENT_ALTAR_IMBUE, SoundCategory.BLOCKS, 1, 1, false);
		}

		ItemStack result = getResult();

		if(result.isEmpty()){
			imbuementTimer = 0;

		}else{

			if(imbuementTimer++ >= IMBUEMENT_DURATION){
				this.stack = result;
				consumeReceptacleContents();
				imbuementTimer = 0;
				displayElement = null;
				if(lastUser instanceof EntityPlayerMP){
					WizardryAdvancementTriggers.imbuement_altar.trigger((EntityPlayerMP)lastUser, this.stack);
				}
			}

			if(world.isRemote && world.rand.nextInt(2) == 0){

				Element[] elements = getReceptacleElements();

				Vec3d centre = GeometryUtils.getCentre(this.pos.up());

				for(int i = 0; i < elements.length; i++){

					if(elements[i] == null) continue;

					Vec3d offset = new Vec3d(EnumFacing.byHorizontalIndex(i).getDirectionVec());
					Vec3d vec = GeometryUtils.getCentre(this.pos).add(0, 0.3, 0).add(offset.scale(0.7));

					int[] colours = BlockReceptacle.PARTICLE_COLOURS.get(elements[i]);

					ParticleBuilder.create(Type.DUST, world.rand, vec.x, vec.y, vec.z, 0.1, false)
							.vel(centre.subtract(vec).scale(0.02)).clr(colours[1]).fade(colours[2]).time(50).spawn(world);
				}
			}
		}
	}
}

public void healServant() {
    super.healServant();
    if (!this.level.isClientSide) {
        if (this.eatenFoodLevel <= 0 && this.getHealth() < this.getMaxHealth()) {
            if (this.countFoodPointsInInventory() != 0) {
                for (int i = 0; i < this.getInventory().getContainerSize(); ++i) {
                    ItemStack itemstack = this.getInventory().getItem(i);
                    if (!itemstack.isEmpty()) {
                        Integer integer = this.getFoodPoints().get(itemstack.getItem());
                        if (integer != null) {
                            FoodProperties foodProperties = itemstack.getFoodProperties(this);
                            if (foodProperties != null) {
                                if (!foodProperties.getEffects().isEmpty()) {
                                    for(Pair<MobEffectInstance, Float> pair : foodProperties.getEffects()) {
                                        if (pair.getFirst() != null && this.getRandom().nextFloat() < pair.getSecond()) {
                                            this.addEffect(new MobEffectInstance(pair.getFirst()));
                                        }
                                    }
                                }
                            }
                            if (!BrewUtils.isEmpty(itemstack)){
                                if (!PotionUtils.getMobEffects(itemstack).isEmpty()) {
                                    for (MobEffectInstance instance : PotionUtils.getMobEffects(itemstack)) {
                                        if (instance.getEffect().isInstantenous()) {
                                            instance.getEffect().applyInstantenousEffect(this, this, this, instance.getAmplifier(), 1.0D);
                                        } else {
                                            this.addEffect(new MobEffectInstance(instance));
                                        }
                                    }
                                }
                                if (!BrewUtils.getBrewEffects(itemstack).isEmpty()) {
                                    for (BrewEffectInstance instance : BrewUtils.getBrewEffects(itemstack)) {
                                        instance.getEffect().drinkBlockEffect(this, this, this, instance.getAmplifier(), BrewUtils.getAreaOfEffect(itemstack));
                                    }
                                }
                            }
                            this.eatenFoodLevel = integer;
                            this.playSound(SoundEvents.GENERIC_EAT);
                            if (this.level instanceof ServerLevel serverLevel) {
                                ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, new ItemParticleOption(ParticleTypes.ITEM, itemstack), this);
                            }
                            this.getInventory().removeItem(i, 1);
                            break;
                        }
                    }
                }
            }
        }
    }
}

public void tick() {
    if (this.targetPos != null) {
        if (this.heretic.level instanceof ServerLevel serverLevel) {
            ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_PURPLE);
            ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.RISING_ENCHANT.get(), this.targetPos.x, this.targetPos.y, this.targetPos.z, colorUtil.red, colorUtil.green, colorUtil.blue, 1.0F);
        }
        if (this.heretic.distanceToSqr(this.targetPos) > Mth.square(4.0D)){
            ++this.movingTime;
            this.heretic.getNavigation().moveTo(this.targetPos.x, this.targetPos.y, this.targetPos.z, 1.0F);
        } else {
            MobUtil.instaLook(this.heretic, this.targetPos);
            ++this.castingTime;
            if (!this.heretic.isCasting()){
                this.heretic.setCasting(true);
                this.heretic.level.broadcastEntityEvent(this.heretic, (byte) 6);
            }
            if (this.castingTime == TOTAL_CAST_TIME){
                Summoned summon = new ZPiglinServant(ModEntityType.ZPIGLIN_SERVANT.get(), this.heretic.level);
                if (this.heretic.getRandom().nextFloat() <= 0.5F){
                    summon = new Hellhound(ModEntityType.HELLHOUND.get(), this.heretic.level);
                } else if (this.heretic.getRandom().nextFloat() <= 0.25F){
                    summon = new MagmaCubeServant(ModEntityType.MAGMA_CUBE_SERVANT.get(), this.heretic.level);
                } else if (this.heretic.getRandom().nextFloat() <= 0.05F){
                    summon = new BlazeServant(ModEntityType.BLAZE_SERVANT.get(), this.heretic.level);
                }
                summon.moveTo(this.targetPos);
                summon.setTrueOwner(this.heretic);
                if (this.heretic.level instanceof ServerLevel serverLevel) {
                    summon.finalizeSpawn(serverLevel, this.heretic.level.getCurrentDifficultyAt(BlockPos.containing(this.targetPos)), MobSpawnType.MOB_SUMMONED, null, null);
                    ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.FLAME, summon);
                }
                if (summon instanceof MagmaCubeServant cube){
                    cube.setSize(2, true);
                }
                if (this.heretic.getTarget() != null) {
                    summon.setTarget(this.heretic.getTarget());
                }
                summon.setLimitedLife(MathHelper.minecraftDayToTicks(5));
                if (this.heretic.level.addFreshEntity(summon)){
                    summon.playSound(ModSounds.SUMMON_SPELL_FIERY.get(), 1.0F, 1.0F);
                    this.heretic.getConvokePos().remove(this.targetPos);
                    this.heretic.setCastCoolDown(100);
                }
            }
        }
    } else {
        this.findTargetPos();
    }
    super.tick();
}

