protected void onHitEntity(EntityHitResult p_37626_) {
    if (!this.level.isClientSide) {
        float baseDamage = SpellConfig.IceSpikeDamage.get().floatValue() * WandUtil.damageMultiply();
        Entity entity = p_37626_.getEntity();
        if (this.getPierceLevel() > 0) {
            if (this.piercingIgnoreEntityIds == null) {
                this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
            }

            if (this.piercedAndKilledEntities == null) {
                this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
            }

            if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
                this.discard();
                return;
            }

            this.piercingIgnoreEntityIds.add(entity.getId());
        }
        Entity entity1 = this.getOwner();
        boolean flag;
        baseDamage += this.getExtraDamage();
        if (entity1 instanceof LivingEntity livingentity) {
            if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                this.piercedAndKilledEntities.add(livingentity);
            }
            flag = entity.hurt(ModDamageSource.iceSpike(this, livingentity), baseDamage);
            if (flag) {
                if (entity.isAlive()) {
                    this.doEnchantDamageEffects(livingentity, entity);
                }
            }
        } else {
            flag = entity.hurt(ModDamageSource.iceSpike(this, this), baseDamage);
        }

        if (flag && entity instanceof LivingEntity livingEntity) {
            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + livingEntity.getRandom().nextInt(2))));
            this.playSound(ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            if (livingEntity.level instanceof ServerLevel serverLevel){
                ServerParticleUtil.addParticlesAroundSelf(serverLevel, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.PACKED_ICE.defaultBlockState()), livingEntity);
            }
            if (this.getPierceLevel() <= 0) {
                this.discard();
            }
        }

    }
}

protected void onHit(HitResult result) {
    super.onHit(result);
    if (!this.level.isClientSide) {
        if (this.growTick <= 0) {
            Entity entity = this.getOwner();
            Vec3 vec30 = Vec3.atCenterOf(this.blockPosition());
            if (entity instanceof LivingEntity livingEntity) {
                if (result instanceof BlockHitResult blockHitResult){
                    BlockPos blockpos = blockHitResult.getBlockPos().relative(blockHitResult.getDirection());
                    if (BlockFinder.canBeReplaced(this.level, blockpos)) {
                        vec30 = Vec3.atCenterOf(blockpos);
                    }
                } else if (result instanceof EntityHitResult entityHitResult){
                    Entity entity1 = entityHitResult.getEntity();
                    vec30 = Vec3.atCenterOf(entity1.blockPosition());
                }
                MagicFire magicFire = new MagicFire(this.level, vec30, livingEntity);
                if (this.level.addFreshEntity(magicFire)) {
                    for (Direction direction : Direction.values()) {
                        if (direction.getAxis().isHorizontal()) {
                            MagicFire magicFire1 = new MagicFire(this.level, Vec3.atCenterOf(magicFire.blockPosition().relative(direction)), livingEntity);
                            this.level.addFreshEntity(magicFire1);
                        }
                    }
                }
            }
            this.playSound(SoundEvents.DRAGON_FIREBALL_EXPLODE, 1.5F, 0.75F);
            for (int i = 0; i < 8; ++i) {
                VoidShock voidShock = new VoidShock(ModEntityType.VOID_SHOCK.get(), this.level);
                voidShock.setPos(this.getX(), this.getY(), this.getZ());
                Vec3 vec3 = this.position().add(this.level.getRandom().nextInt(-3, 3), this.level.getRandom().nextInt(3, 6), this.level.getRandom().nextInt(-3, 3));
                voidShock.signalTo(vec3, MathHelper.secondsToTicks(2) + (i * 5));
                voidShock.setBaseDamage(this.baseDamage);
                voidShock.setExtraDamage(this.getExtraDamage());
                if (this.getOwner() != null) {
                    voidShock.setOwner(this.getOwner());
                    if (this.getOwner() instanceof Mob mob) {
                        voidShock.setTarget(mob.getTarget());
                    }
                }
                this.level.addFreshEntity(voidShock);
            }
            this.level.broadcastEntityEvent(this, (byte) 6);
            this.growTick = 1;
            float damage = this.baseDamage + this.getExtraDamage();
            new SpellExplosion(this.level, this, this.damageSources().indirectMagic(this, this.getOwner()), this.getX(), this.getY(), this.getZ(), 2.0F, damage);
        }
    }

}

public void onUpdate(){

	if(this.ticksExisted % 120 == 1){
		this.playSound(WizardrySounds.ENTITY_BLIZZARD_AMBIENT, 1.0f, 1.0f);
	}

	super.onUpdate();

	// This is a good example of why you might define a spell base property without necessarily using it in the
	// spell - in fact, blizzard doesn't even have a spell class (yet)
	double radius = Spells.blizzard.getProperty(Spell.EFFECT_RADIUS).doubleValue() * sizeMultiplier;

	if(!this.world.isRemote){

		List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(radius, this.posX, this.posY,
				this.posZ, this.world);

		for(EntityLivingBase target : targets){

			if(this.isValidTarget(target)){

				if(this.getCaster() != null){
					EntityUtils.attackEntityWithoutKnockback(target,
							MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.FROST),
							1 * damageMultiplier);
				}else{
					EntityUtils.attackEntityWithoutKnockback(target, DamageSource.MAGIC,
							1 * damageMultiplier);
				}
			}

			// All entities are slowed, even the caster (except those immune to frost effects)
			if(!world.isRemote && !MagicDamage.isEntityImmune(DamageType.FROST, target))
				target.addPotionEffect(new PotionEffect(WizardryPotions.frost, 20, 0));
		}

	}else{

		for(int i=0; i<6; i++){
			double speed = (rand.nextBoolean() ? 1 : -1) * (0.1 + 0.05 * rand.nextDouble());
			ParticleBuilder.create(Type.SNOW).pos(this.posX, this.posY + rand.nextDouble() * height, this.posZ).vel(0, 0, 0)
			.time(100).scale(2).spin(rand.nextDouble() * (radius - 0.5) + 0.5, speed).shaded(true).spawn(world);
		}

		for(int i=0; i<3; i++){
			double speed = (rand.nextBoolean() ? 1 : -1) * (0.05 + 0.02 * rand.nextDouble());
			ParticleBuilder.create(Type.CLOUD).pos(this.posX, this.posY + rand.nextDouble() * (height - 0.5), this.posZ)
					.clr(0xffffff).shaded(true).spin(rand.nextDouble() * (radius - 1) + 0.5, speed).spawn(world);
		}
	}
}

public void tick() {
    LivingEntity livingentity = Vizier.this.getTarget();
    if (livingentity != null) {
        ++this.duration;
        ++this.duration2;
        if (Vizier.this.airBound > AIR_BOUND_TIME){
            if (!Vizier.this.level.isClientSide) {
                ServerLevel serverWorld = (ServerLevel) Vizier.this.level;
                for (int i = 0; i < 5; ++i) {
                    double d0 = serverWorld.random.nextGaussian() * 0.02D;
                    double d1 = serverWorld.random.nextGaussian() * 0.02D;
                    double d2 = serverWorld.random.nextGaussian() * 0.02D;
                    serverWorld.sendParticles(ParticleTypes.ENCHANT, Vizier.this.getRandomX(1.0D), Vizier.this.getRandomY() + 1.0D, Vizier.this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                }
            }
        } else {
            if (Vizier.this.level instanceof ServerLevel serverLevel) {
                BlockPos blockPos = livingentity.blockPosition().below();
                double groundY = BlockFinder.findGroundY(serverLevel, blockPos.getCenter());
                BlockParticleOption option = new BlockParticleOption(ParticleTypes.BLOCK, serverLevel.getBlockState(blockPos));
                for (int i = 0; i < 4; ++i) {
                    float radius = 1.0F;
                    if (MobUtil.healthIsHalved(Vizier.this) || serverLevel.getDifficulty() != Difficulty.EASY){
                        radius = 3.0F;
                    }
                    ServerParticleUtil.circularParticles(serverLevel, option, livingentity.getX(), groundY + 0.25D, livingentity.getZ(), radius);
                }
            }
        }
        int time = Vizier.this.getHealth() <= Vizier.this.getMaxHealth() / 2 ? 5 : 10;
        time = Vizier.this.airBound > AIR_BOUND_TIME ? time * 2 : time;
        if (this.duration >= time) {
            this.duration = 0;
            if (Vizier.this.airBound > AIR_BOUND_TIME && !Vizier.this.flyWarn){
                Vizier.this.playSound(ModSounds.VIZIER_CELEBRATE.get(), 1.0F, 1.5F);
                Vizier.this.flyWarn = true;
            } else {
                this.attack(livingentity);
            }
        }
        if (this.duration2 >= 160) {
            Vizier.this.setSpellcasting(false);
            Vizier.this.setCasting(0);
            Vizier.this.setCastTimes(1);
            this.duration2 = 0;
            this.duration = 0;
        }
    } else {
        stop();
    }
}

public void performRangedAttack(LivingEntity p_33317_, float p_33318_) {
    if (p_33317_.distanceTo(this) < 6.0F && this.coolDown <= 0 && this.level.getBlockState(this.blockPosition().above(2)).isAir() && !(this.getTarget() instanceof Raider)) {
        this.totalCool = Mth.nextInt(this.random, 6, 10);
        for (int i = 0; i < this.totalCool; ++i) {
            MobUtil.throwBlastFungus(this, level);
        }
        if (this.getHealth() <= this.getMaxHealth() / 2){
            this.coolDown = MathHelper.secondsToTicks(this.totalCool / 2);
        } else {
            this.coolDown = MathHelper.secondsToTicks(this.totalCool);
        }
        if (!this.isSilent()) {
            this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), this.getSoundSource(), 2.0F, 0.8F + this.random.nextFloat() * 0.4F);
        }
    } else {
        if (this.getTarget() instanceof Raider){
            if (!this.isSilent()) {
                this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), this.getSoundSource(), 2.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        }
        if (this.level instanceof ServerLevel) {
            if (this.getTarget() instanceof Raider raider){
                Vec3 vec3 = raider.getDeltaMovement();
                double d0 = raider.getX() + vec3.x - this.getX();
                double d1 = raider.getEyeY() - (double)1.1F - this.getY();
                double d2 = raider.getZ() + vec3.z - this.getZ();
                double d3 = Math.sqrt(d0 * d0 + d2 * d2);
                BerserkFungus berserkFungus = new BerserkFungus(this, this.level);
                berserkFungus.setXRot(berserkFungus.getXRot() - 20.0F);
                berserkFungus.shoot(d0, d1 + d3 * 0.2D, d2, 0.75F, 8.0F);
                this.level.addFreshEntity(berserkFungus);
            } else {
                Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), this.level);
                wartling.setTarget(p_33317_);
                if (this.isInFluidType()){
                    wartling.setPos(this.getX(), this.getY(0.5F), this.getZ());
                    wartling.setXRot(this.getXRot());
                    wartling.setYRot(this.getYRot());
                    double d0 = p_33317_.getX() - wartling.getX();
                    double d1 = p_33317_.getY(0.3333333333333333D) - wartling.getY();
                    double d2 = p_33317_.getZ() - wartling.getZ();
                    double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                    MobUtil.shoot(wartling, d0, d1 + d3 * (double)0.2F, d2, 1.6F, 1.0F);
                } else {
                    wartling.moveTo(this.blockPosition(), this.getYRot(), this.getXRot());
                }
                this.summonWartlings(wartling);
            }
        }
    }
}

public void aiStep() {
    super.aiStep();

    if (this.coolDown > 0){
        --this.coolDown;
    }

    if (!this.level.isClientSide){
        if (this.isAlive()){
            this.healRaidersGoal.decrementCooldown();
            this.attackPlayersGoal.setCanAttack(this.healRaidersGoal.getCooldown() <= 0);
        }
        if (this.random.nextFloat() < 7.5E-4F) {
            this.level.broadcastEntityEvent(this, (byte)15);
        }
        if (this.getTarget() != null) {
            if (!(this.getTarget() instanceof Raider)) {
                if (this.getTarget().distanceTo(this) < 6.0F && this.coolDown <= this.totalCool / 2) {
                    this.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(ModItems.SNAP_FUNGUS.get()));
                } else {
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                }
            } else {
                this.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(ModItems.BERSERK_FUNGUS.get()));
            }
        } else {
            if (this.getMainHandItem().is(ModItems.SNAP_FUNGUS.get()) || this.getMainHandItem().is(ModItems.BERSERK_FUNGUS.get())){
                this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
            }
            boolean flag = false;
            if (!this.isInLava()) {
                if (this.getHealth() < this.getMaxHealth()) {
                    flag = true;
                }
                if (!this.getActiveEffects().isEmpty()) {
                    if (this.getActiveEffects().stream().anyMatch((mobEffectInstance -> mobEffectInstance.getEffect().getCategory() == MobEffectCategory.HARMFUL && !mobEffectInstance.getEffect().getCurativeItems().isEmpty()))){
                        flag = true;
                    }
                }
                if (flag){
                    if (this.tickCount % 60 == 0){
                        Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), this.level);
                        wartling.moveTo(this.blockPosition(), this.getYRot(), this.getXRot());
                        this.summonWartlings(wartling);
                    }
                }
            }
        }

    }
}

