                                break;
                            }
                        }
                    }
                }
            }
        }

        return true;
    }
}

public static void onLivingHurtEvent(LivingHurtEvent event){

	// Ward
	PotionEffect effect = event.getEntityLiving().getActivePotionEffect(WizardryPotions.ward);

	if(effect != null && event.getSource().isMagicDamage()){
		event.setAmount(event.getAmount() * Math.max(0, 1 - 0.2f * (1 + effect.getAmplifier()))); // Resistance is 20%
	}

	// Flaming and freezing swords
	if(event.getSource().getTrueSource() instanceof EntityLivingBase){

		EntityLivingBase attacker = (EntityLivingBase)event.getSource().getTrueSource();

		// Players can only ever attack with their main hand, so this is the right method to use here.
		if(!attacker.getHeldItemMainhand().isEmpty() && ImbueWeapon.isSword(attacker.getHeldItemMainhand())){

			int level = EnchantmentHelper.getEnchantmentLevel(WizardryEnchantments.flaming_weapon,
					attacker.getHeldItemMainhand());

			if(level > 0 && !MagicDamage.isEntityImmune(DamageType.FIRE, event.getEntityLiving()))
				event.getEntityLiving().setFire(level * 4);

			level = EnchantmentHelper.getEnchantmentLevel(WizardryEnchantments.freezing_weapon,
					attacker.getHeldItemMainhand());
			// Frost lasts for longer because it doesn't do any actual damage
			if(!event.getEntityLiving().world.isRemote && level > 0 && !MagicDamage.isEntityImmune(DamageType.FROST, event.getEntityLiving()))
				event.getEntityLiving().addPotionEffect(new PotionEffect(WizardryPotions.frost, level * 200, 0));
		}
	}

	// Freezing bow
	if(event.getSource().getImmediateSource() instanceof EntityArrow
			&& event.getSource().getImmediateSource().getEntityData() != null){

		int level = event.getSource().getImmediateSource().getEntityData()
				.getInteger(FreezingWeapon.FREEZING_ARROW_NBT_KEY);

		if(!event.getEntityLiving().world.isRemote && level > 0 && !MagicDamage.isEntityImmune(DamageType.FROST, event.getEntityLiving()))
			event.getEntityLiving().addPotionEffect(new PotionEffect(WizardryPotions.frost, level * 150, 0));
	}

	// Damage scaling
	if(event.getSource() != null && event.getSource() instanceof IElementalDamage){

		if(event.getSource().getTrueSource() instanceof EntityPlayer){
			event.setAmount((float)(event.getAmount() * Wizardry.settings.playerDamageScale));
		}else{
			event.setAmount((float)(event.getAmount() * Wizardry.settings.npcDamageScale));
		}
	}
}

public void onUpdate(){

	super.onUpdate();

	this.move(MoverType.SELF, motionX, 0, motionZ);

	if(this.world.isRemote){

		float areaFactor = (width * width) / 36; // Ensures cloud/raindrop density stays the same for different sizes

		for(int i = 0; i < 2 * areaFactor; i++) ParticleBuilder.create(Type.CLOUD, this)
				.clr(0.3f, 0.3f, 0.3f).shaded(true).spawn(world);
	}

	boolean stormcloudRingActive = getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(), WizardryItems.ring_stormcloud);

	List<EntityLivingBase> targets = world.getEntitiesWithinAABB(EntityLivingBase.class,
			this.getEntityBoundingBox().expand(0, -10, 0));

	targets.removeIf(t -> !this.isValidTarget(t));

	float damage = Spells.stormcloud.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier;

	for(EntityLivingBase target : targets){

		if(target.ticksExisted % 150 == 0){ // Use target's lifetime so they don't all get hit at once, looks better

			if(!this.world.isRemote){
				EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(
						this, this.getCaster(), MagicDamage.DamageType.SHOCK), damage);
			}else{
				ParticleBuilder.create(Type.LIGHTNING).pos(target.posX, posY + height/2, target.posZ)
						.target(target).scale(2).spawn(world);
				ParticleBuilder.spawnShockParticles(world, target.posX, target.posY + target.height, target.posZ);
			}

			target.playSound(WizardrySounds.ENTITY_STORMCLOUD_THUNDER, 1, 1.6f);
			target.playSound(WizardrySounds.ENTITY_STORMCLOUD_ATTACK, 1, 1);

			if(stormcloudRingActive) this.lifetime -= 40; // Each strike prolongs the lifetime by 2 seconds with the ring
		}
	}

	if(stormcloudRingActive){
		EntityUtils.getLivingWithinRadius(width * 3, posX, posY, posZ, world).stream()
				.filter(this::isValidTarget).min(Comparator.comparingDouble(this::getDistanceSq)).ifPresent(e -> {
			Vec3d vel = e.getPositionVector().subtract(this.getPositionVector()).normalize().scale(0.2);
			this.motionX = vel.x;
			this.motionZ = vel.z;
		});
	}

}

public void tick() {
    if (this.level != null) {
        ++this.tickCount;
        if (this.level instanceof ServerLevel serverLevel) {
            int radius = 8 + this.getEnchantments().getOrDefault(ModEnchantments.RADIUS.get(), 0);
            if (this.target == null) {
                for (LivingEntity livingEntity : serverLevel.getEntitiesOfClass(LivingEntity.class, new AABB(this.worldPosition).inflate(radius * 2))) {
                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.distanceToSqr(this.getBlockPos().getCenter()) <= Mth.square(radius)) {
                        boolean flag = livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.25F;
                        if (this.getTrueOwner() != null) {
                            flag &= !MobUtil.areAllies(this.getTrueOwner(), livingEntity);
                        } else {
                            flag &= !this.isAllyWith(livingEntity);
                        }
                        if (flag) {
                            this.target = livingEntity;
                        }
                    }
                }
            } else {
                if (!this.target.isAlive() || this.target.getHealth() < this.target.getMaxHealth() * 0.25F || this.target.distanceToSqr(this.getBlockPos().getCenter()) > Mth.square(radius)) {
                    this.attackTick = 0;
                    this.target = null;
                } else {
                    ++this.attackTick;
                    if (this.attackTick % 20 == 0) {
                        Vec3 vector3d1 = this.getBlockPos().getCenter();
                        DamageSource damageSource = this.getTrueOwner() != null ? ModDamageSource.soulLeech(this.getTrueOwner(), this.getTrueOwner()) : this.level.damageSources().magic();
                        this.target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), 10, 0, false, false));
                        if (this.target.hurt(damageSource, this.target.getMaxHealth() * 0.1F)) {
                            ColorUtil colorUtil1 = new ColorUtil(0x5038dd);
                            serverLevel.sendParticles(new SpirallingParticleOption(1.0F, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 5), vector3d1.x, vector3d1.y, vector3d1.z, 1, 0.0D, 0.0D, 0.0D, 1.0D);
                            Vec3 vec3 = new Vec3(this.target.getX(), this.target.getY() + (this.target.getBbHeight() / 2.0F), this.target.getZ());
                            serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil1, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                            for (int i = 0; i < 8; ++i) {
                                Vec3 vec31 = new Vec3(this.target.getRandomX(1.0F), this.target.getRandomY(), this.target.getRandomZ(1.0F));
                                serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 0x5038dd, 10), vec31.x, vec31.y, vec31.z, 1, 0.0, 0.0, 0.0, 0.0);
                            }
                            this.level.playSound(null, this.worldPosition, ModSounds.SOUL_EAT.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                            if (this.getTrueOwner() instanceof Player player) {
                                if (SEHelper.getSoulGiven(this.target) > 0) {
                                    int enchantment = this.getEnchantments().getOrDefault(ModEnchantments.SOUL_EATER.get(), 0);
                                    int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                    SEHelper.increaseSouls(player, MainConfig.BlackCrystalSouls.get() * soulEater);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

public void start() {
    int warmUp = MathHelper.secondsToTicks(2);
    this.spellTime = warmUp + 20;
