public void aiStep() {
    super.aiStep();

    if (this.coolDown > 0){
        --this.coolDown;
    }

    if (!this.level.isClientSide){
        if (this.isAlive()){
            this.healRaidersGoal.decrementCooldown();
            this.attackPlayersGoal.setCanAttack(this.healRaidersGoal.getCooldown() <= 0);
        }
        if (this.random.nextFloat() < 7.5E-4F) {
            this.level.broadcastEntityEvent(this, (byte)15);
        }
        if (this.getTarget() != null) {
            if (!(this.getTarget() instanceof Raider)) {
                if (this.getTarget().distanceTo(this) < 6.0F && this.coolDown <= this.totalCool / 2) {
                    this.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(ModItems.BLAST_FUNGUS.get()));
                } else {
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                }
                if (this.getHealth() <= this.getMaxHealth() / 4 && this.tickCount % 10 == 0 && this.random.nextBoolean()){
                    MobUtil.throwBlastFungus(this, level);
                }
            } else {
                this.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(ModItems.BERSERK_FUNGUS.get()));
            }
        } else {
            if (this.getMainHandItem().is(ModItems.BLAST_FUNGUS.get()) || this.getMainHandItem().is(ModItems.BERSERK_FUNGUS.get())){
                this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
            }
            boolean flag = false;
            if (!this.isInLava()) {
                if (this.getHealth() < this.getMaxHealth()) {
                    flag = true;
                }
                if (!this.getActiveEffects().isEmpty()) {
                    if (this.getActiveEffects().stream().anyMatch((mobEffectInstance -> mobEffectInstance.getEffect().getCategory() == MobEffectCategory.HARMFUL))){
                        flag = true;
                    }
                }
                if (flag){
                    if (this.tickCount % 60 == 0){
                        Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), this.level);
                        wartling.moveTo(this.blockPosition(), this.getYRot(), this.getXRot());
                        this.summonWartlings(wartling);
                    }
                }
            }
        }

    }
}

public void aiStep() {
    if (!this.level.isClientSide && this.isAlive()) {
        this.setAggressive(this.getTarget() != null);
        AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (this.isDrinkingPotion()) {
            int i = this.usingTime;
            if (i % 4 == 0) {
                if (!this.isSilent()) {
                    this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.GENERIC_DRINK, this.getSoundSource(), 0.5F, this.level.random.nextFloat() * 0.1F + 0.9F);
                }
            }
            if (this.usingTime-- <= 0) {
                this.setUsingItem(false);
                ItemStack itemstack = this.getOffhandItem();
                this.setItemSlot(EquipmentSlot.OFFHAND, ItemStack.EMPTY);
                if (itemstack.is(Items.POTION)) {
                    List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                    if (!list.isEmpty()) {
                        for(MobEffectInstance mobeffectinstance : list) {
                            this.addEffect(new MobEffectInstance(mobeffectinstance));
                        }
                    }
                }

                if (attributeinstance != null) {
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                }
            }
        } else {
            Potion potion = null;
            if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                potion = Potions.WATER_BREATHING;
            } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                potion = Potions.FIRE_RESISTANCE;
            } else if (this.random.nextFloat() < 0.05F && this.getHealth() < this.getMaxHealth() && ((this.getTarget() == null) || (this.getTarget() != null && this.getTarget().distanceTo(this) >= 11.0D))) {
                potion = Potions.HEALING;
            } else if (this.random.nextFloat() < 0.5F && this.getTarget() != null && !this.hasEffect(MobEffects.MOVEMENT_SPEED) && this.getTarget().distanceTo(this) >= 11.0D) {
                potion = Potions.SWIFTNESS;
            }

            if (potion != null) {
                this.setItemSlot(EquipmentSlot.OFFHAND, PotionUtils.setPotion(new ItemStack(Items.POTION), potion));
                this.usingTime = this.getOffhandItem().getUseDuration();
                this.setUsingItem(true);

                if (attributeinstance != null) {
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                }
            }
        }
    }

    super.aiStep();
}

