protected void onHitEntity(EntityHitResult pResult) {
    if (!this.level.isClientSide) {
        Entity entity = pResult.getEntity();
        if (this.getSpearLevel() > 0) {
            if (this.piercingIgnoreEntityIds == null) {
                this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
            }

            if (this.piercedAndKilledEntities == null) {
                this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
            }

            if (this.piercingIgnoreEntityIds.size() >= this.getSpearLevel() + 1) {
                this.discard();
                return;
            }

            this.piercingIgnoreEntityIds.add(entity.getId());
        }
        Entity entity1 = this.getOwner();
        boolean flag;
        float damage = entity1 instanceof Mob mob ? (float) MobUtil.getAttributeValue(mob, Attributes.ATTACK_DAMAGE, 2.0D) : SpellConfig.PoisonDartDamage.get().floatValue();
        damage += this.getExtraDamage();
        if (entity1 instanceof LivingEntity livingentity) {
            if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                this.piercedAndKilledEntities.add(livingentity);
            }
            flag = entity.hurt(this.damageSources().arrow(this, entity1), damage);
            if (flag) {
                if (entity.isAlive()) {
                    this.doEnchantDamageEffects(livingentity, entity);
                }
            }
        } else {
            flag = entity.hurt(this.damageSources().arrow(this, this), damage);
        }
        if (flag && entity.getType() != EntityType.ENDERMAN && entity instanceof LivingEntity livingEntity) {
            if (entity1 instanceof LivingEntity) {
                EnchantmentHelper.doPostHurtEffects(livingEntity, entity1);
                EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingEntity);
            }

            this.doPostHurtEffects(livingEntity);

            MobEffect mobEffect = MobEffects.POISON;
            if ((entity1 instanceof IOwned owned && CuriosFinder.hasWildRobe(owned.getMasterOwner()))
                    || (entity1 instanceof LivingEntity livingEntity1 && CuriosFinder.hasWildRobe(livingEntity1))) {
                mobEffect = GoetyEffects.ACID_VENOM.get();
            }
            livingEntity.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(2 + this.getDuration())));

            this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            if (this.getSpearLevel() <= 0) {
                this.discard();
            }
        }
    }
}

public static void infect(Mob target, LivingEntity owner, boolean permanent, boolean keepLoot){
    Summoned summoned = null;
    if (target instanceof PiglinBrute){
        summoned = target.convertTo(ModEntityType.ZPIGLIN_BRUTE_SERVANT.get(), keepLoot);
    } else if (target instanceof AbstractPiglin){
        summoned = target.convertTo(ModEntityType.ZPIGLIN_SERVANT.get(), keepLoot);
    } else if (target instanceof Villager || target instanceof Prisoner || target.getType().getDescriptionId().contains("entity.guardvillagers.guard")){
        if (target instanceof Villager villager) {
            MobUtil.releaseAllPois(villager);
        }
        summoned = target.convertTo(ModEntityType.ZOMBIE_VILLAGER_SERVANT.get(), keepLoot);
    } else if (target instanceof Vindicator || target instanceof VindicatorServant){
        summoned = target.convertTo(ModEntityType.ZOMBIE_VINDICATOR_SERVANT.get(), keepLoot);
    } else if (target instanceof Pillager || target instanceof PillagerServant){
        summoned = target.convertTo(ModEntityType.SKELETON_PILLAGER_SERVANT.get(), keepLoot);
    } else if (target instanceof Ravager || target instanceof ModRavager){
        summoned = target.convertTo(ModEntityType.ZOMBIE_RAVAGER.get(), keepLoot);
    }

    if (summoned != null) {
        EntityType<? extends LivingEntity> entityType = (EntityType<? extends LivingEntity>) summoned.getType();
        if (net.minecraftforge.event.ForgeEventFactory.canLivingConvert(target, entityType, (timer) -> {})) {
            if (owner != null) {
                summoned.setTrueOwner(owner);
            }
            if (target.level instanceof ServerLevel serverLevel) {
                summoned.finalizeSpawn(serverLevel, target.level.getCurrentDifficultyAt(summoned.blockPosition()), MobSpawnType.CONVERSION, null, null);
            }
            if (!permanent) {
                summoned.setLimitedLife(10 * (15 + target.level.random.nextInt(45)));
            }
            if (summoned instanceof ZombieVillagerServant servant) {
                if (target instanceof Villager villager) {
                    servant.setVillagerData(villager.getVillagerData());
                    servant.setGossips(villager.getGossips().store(NbtOps.INSTANCE));
                    servant.setTradeOffers(villager.getOffers().createTag());
                    servant.setVillagerXp(villager.getVillagerXp());
                } else if (target instanceof Prisoner prisoner) {
                    servant.setVillagerData(prisoner.getVillagerData());
                    if (prisoner.getGossips() != null) {
                        servant.setGossips(prisoner.getGossips());
                    }
                    if (prisoner.getOffers() != null) {
                        servant.setTradeOffers(prisoner.getOffers());
                    }
                    servant.setVillagerXp(prisoner.getVillagerXp());
                }
            } else if (summoned instanceof ZombieRavager servant) {
                servant.convertNewEquipment(target);
            }
            summoned.setBaby(target.isBaby());
            net.minecraftforge.event.ForgeEventFactory.onLivingConvert(target, summoned);
            if (!summoned.isSilent()) {
                summoned.level.levelEvent(null, 1026, summoned.blockPosition(), 0);
            }
        }
    }
}

protected void checkAndPerformAttack(LivingEntity enemy, double distToEnemySqr) {
    double d0 = this.getAttackReachSqr(enemy);
    boolean smash = Endersent.this.random.nextBoolean();

    if (!Endersent.this.isMeleeAttacking() && distToEnemySqr <= d0){
        Endersent.this.setMeleeAttacking(true);
        if (smash) {
            Endersent.this.setAnimationState(SWIPE);
            Endersent.this.playSound(ModSounds.ENDERSENT_SWING.get(), Endersent.this.getSoundVolume(), Endersent.this.getVoicePitch());
        } else {
            Endersent.this.setAnimationState(ATTACK);
            Endersent.this.playSound(ModSounds.ENDERSENT_ATTACK.get(), Endersent.this.getSoundVolume(), Endersent.this.getVoicePitch());
        }
    }
    if (Endersent.this.isMeleeAttacking()) {
        float seconds = Endersent.this.isCurrentAnimation(ATTACK) ? 2.44F : 2.84F;
        if (Endersent.this.attackTick < MathHelper.secondsToTicks(seconds)) {
            MobUtil.instaLook(Endersent.this, enemy);
            if (Endersent.this.isCurrentAnimation(SWIPE)) {
                if (Endersent.this.attackTick == MathHelper.secondsToTicks(1)) {
                    this.massiveSweep(Endersent.this, 4.5D, 200.0D);
                }
            } else if (Endersent.this.isCurrentAnimation(ATTACK)) {
                if (Endersent.this.attackTick == MathHelper.secondsToTicks(1)) {
                    double x = Endersent.this.getXFront();
                    double z = Endersent.this.getZFront();
                    float size = 2.5F;
                    BlockPos blockPos = BlockPos.containing(x, Endersent.this.getY() - 1.0F, z);
                    AABB aabb = new AABB(blockPos).inflate(size);
                    for (LivingEntity target : Endersent.this.level.getEntitiesOfClass(LivingEntity.class, aabb)) {
                        if (target != Endersent.this && !MobUtil.areAllies(target, Endersent.this)) {
                            Endersent.this.doHurtTarget(target);
                        }
                    }
                    CameraShake.cameraShake(Endersent.this.level, blockPos.getCenter(), 15.0F, 0.1F, 0, 10);
                    if (Endersent.this.level instanceof ServerLevel serverLevel) {
                        BlockState blockState = serverLevel.getBlockState(blockPos);
                        BlockParticleOption option = new BlockParticleOption(ParticleTypes.BLOCK, blockState);
                        ServerParticleUtil.circularParticles(serverLevel, option, blockPos.getX(), blockPos.getY() + 1.0F, blockPos.getZ(), 0.0F, 0.0F, 0.0F, size);
                        ColorUtil colorUtil = new ColorUtil(serverLevel.getBlockState(blockPos).getMapColor(serverLevel, blockPos).col);
                        serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), size, 1), x, BlockFinder.moveDownToGround(Endersent.this), z, 1, 0.0D, 0.0D, 0.0D, 0);
                        ColorUtil colorUtil1 = new ColorUtil(0x3c3c3e);
                        ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.BIG_CULT_SPELL.get(), blockPos.getX(), blockPos.getY() + 1.0F, blockPos.getZ(), colorUtil1.red(), colorUtil1.green(), colorUtil1.blue(), size);
                    }
                }
            }
        } else {
            if (!Endersent.this.isHiding() && !Endersent.this.isDeadlyEscape()) {
                if (Endersent.this.level.getRandom().nextFloat() <= 0.3F) {
                    Endersent.this.startHide();
                    if (Endersent.this.level.getRandom().nextBoolean() && Endersent.this.watchlingNumber() <= 3) {
                        Endersent.this.summonWatchlings();
                    }
                }
            }
            Endersent.this.setMeleeAttacking(false);
        }
    }
}

public void tick() {
    super.tick();
    if (this.tickCount % 5 == 0) {
        this.bossInfo.update();
    }
    this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());
    if (this.isCelebrating()){
        if (this.tickCount % 100 == 0 && this.hurtTime <= 0){
            this.laughAnimationState.start(this.tickCount);
            this.level.broadcastEntityEvent(this, (byte) 6);
        }
    }
    if (this.isDeadOrDying()){
        for (AnimationState animationState : this.getAnimations()){
            if (animationState != deathAnimationState){
                animationState.stop();
            }
        }
        this.setYRot(this.deathRotation);
        this.setYBodyRot(this.deathRotation);
    }
    if (this.level instanceof ServerLevel serverLevel){
        if (this.hasStaff()) {
            if (!this.getMainHandItem().isEmpty()) {
                if (this.getOffhandItem().isEmpty()) {
                    this.setItemSlot(EquipmentSlot.OFFHAND, this.getOffhandItem());
                } else {
                    this.spawnAtLocation(this.getMainHandItem());
                }
                this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
            }
        }
        ServerParticleUtil.addAuraParticles(serverLevel, ParticleTypes.ENCHANT, this, 8.0F);
        for (LivingEntity living : serverLevel.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(8.0F, 4.0F, 8.0F))) {
            if (living.getMobType() == MobType.ILLAGER && living != this && MobUtil.areAllies(this, living)) {
                boolean flag = false;
                if (living instanceof Mob mob){
                    if (mob.getTarget() != this){
                        flag = true;
                    }
                } else {
                    flag = true;
                }
                if (flag) {
                    living.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, 0, false, false));
                }
            }
        }
        if (this.coolDown > 0){
            --this.coolDown;
        }
        if (this.getTarget() != null){
            serverLevel.broadcastEntityEvent(this, (byte) 14);
        } else {
            serverLevel.broadcastEntityEvent(this, (byte) 15);
        }
        this.setAggressive(this.getTarget() != null);
    }
}

public static ISoulEnergy load(CompoundTag tag, ISoulEnergy soulEnergy) {
    soulEnergy.setSEActive(tag.getBoolean("seActive"));
    if (tag.contains("arcax") && tag.contains("arcay") && tag.contains("arcaz")) {
        soulEnergy.setArcaBlock(new BlockPos(tag.getInt("arcax"), tag.getInt("arcay"), tag.getInt("arcaz")));
    }
    if (tag.contains("arcaReviveX") && tag.contains("arcaReviveY") && tag.contains("arcaReviveZ")) {
        soulEnergy.setArcaRevivePos(new BlockPos(tag.getInt("arcaReviveX"), tag.getInt("arcaReviveY"), tag.getInt("arcaReviveZ")));
    }
    if (tag.contains("dimension")) {
        soulEnergy.setArcaBlockDimension(Level.RESOURCE_KEY_CODEC.parse(NbtOps.INSTANCE, tag.get("dimension")).resultOrPartial(Goety.LOGGER::error).orElse(Level.OVERWORLD));
    } else {
        soulEnergy.setArcaBlockDimension(Level.OVERWORLD);
    }
    if (tag.contains("EndWalkX") && tag.contains("EndWalkY") && tag.contains("EndWalkZ") && tag.contains("EndWalkDim")) {
        soulEnergy.setEndWalkPos(new BlockPos(tag.getInt("EndWalkX"), tag.getInt("EndWalkY"), tag.getInt("EndWalkZ")));
        soulEnergy.setEndWalkDimension(Level.RESOURCE_KEY_CODEC.parse(NbtOps.INSTANCE, tag.get("EndWalkDim")).resultOrPartial(Goety.LOGGER::error).orElse(Level.OVERWORLD));
    }
    if (tag.contains("miningPosX") && tag.contains("miningPosY") && tag.contains("miningPosZ")) {
        soulEnergy.setMiningPos(new BlockPos(tag.getInt("miningPosX"), tag.getInt("miningPosY"), tag.getInt("miningPosZ")));
    }
    soulEnergy.setSoulEnergy(tag.getInt("soulEnergy"));
    soulEnergy.setRecoil(tag.getInt("recoil"));
    soulEnergy.setRestPeriod(tag.getInt("restPeriod"));
    soulEnergy.setApostleWarned(tag.getBoolean("apostleWarned"));
    soulEnergy.setBottling(tag.getInt("bottling"));
    soulEnergy.setWarding(tag.getInt("warding"));
    soulEnergy.setMaxWarding(tag.getInt("maxWarding"));
    if (tag.contains("BannerBaseColor")) {
        soulEnergy.setBannerBaseColor(DyeColor.byId(tag.getInt("BannerBaseColor")));
    }
    if (tag.contains("BannerPattern")){
        soulEnergy.setBannerPattern(tag.getList("BannerPattern", 10));
    }
    soulEnergy.setTicksInAir(tag.getInt("airTick"));
    soulEnergy.setAirJumps(tag.getInt("airJumps"));
    soulEnergy.setAirJumpCooldown(tag.getInt("airJumpCoolDown"));
    soulEnergy.setMiningProgress(tag.getInt("miningProgress"));
    if (tag.contains("cameraUUID")) {
        soulEnergy.setCameraUUID(tag.getUUID("cameraUUID"));
    } else {
        soulEnergy.setCameraUUID(null);
    }
    replaceAll(soulEnergy.grudgeList(), loadUUIDs(tag, "grudgeList"), soulEnergy::addGrudge, soulEnergy::removeGrudge);
    replaceAll(soulEnergy.grudgeTypeList(), loadTypes(tag, "grudgeTypeList"), soulEnergy::addGrudgeType, soulEnergy::removeGrudgeType);
    replaceAll(soulEnergy.allyList(), loadUUIDs(tag, "allyList"), soulEnergy::addAlly, soulEnergy::removeAlly);
    replaceAll(soulEnergy.allyTypeList(), loadTypes(tag, "allyTypeList"), soulEnergy::addAllyType, soulEnergy::removeAllyType);
    replaceAll(soulEnergy.groundedList(), loadUUIDs(tag, "groundedList"), soulEnergy::addGrounded, soulEnergy::removeGrounded);
    replaceAll(soulEnergy.groundedTypeList(), loadTypes(tag, "groundedTypeList"), soulEnergy::addGroundedType, soulEnergy::removeGroundedType);
    replaceAll(soulEnergy.getResearch(), loadResearch(tag), soulEnergy::addResearch, soulEnergy::removeResearch);
    if (tag.contains("coolDowns", Tag.TAG_LIST)){
        ListTag listTag = (ListTag) tag.get("coolDowns");
        soulEnergy.cooldowns().load(listTag);
    }
    if (tag.contains("coolDownsSpecifics", Tag.TAG_LIST)){
        ListTag listTag2 = (ListTag) tag.get("coolDownsSpecifics");
        soulEnergy.cooldowns().loadSpecifics(listTag2);
    }
    return soulEnergy;
}

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
    ItemStack itemstack = pPlayer.getItemInHand(pHand);
    if (this.getTrueOwner() != null && pPlayer == this.getTrueOwner()) {
        if (this.isFood(itemstack) && this.getHealth() < this.getMaxHealth()) {
            FoodProperties foodProperties = itemstack.getFoodProperties(this);
            if (foodProperties != null){
                this.heal((float)foodProperties.getNutrition());
                if (!pPlayer.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }

                this.gameEvent(GameEvent.EAT, this);
                this.eat(this.level, itemstack);
                if (this.level instanceof ServerLevel serverLevel) {
                    for (int i = 0; i < 7; ++i) {
                        double d0 = this.random.nextGaussian() * 0.02D;
                        double d1 = this.random.nextGaussian() * 0.02D;
                        double d2 = this.random.nextGaussian() * 0.02D;
                        serverLevel.sendParticles(ModParticleTypes.HEAL_EFFECT.get(), this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                    }
                }
                pPlayer.swing(pHand);
                return InteractionResult.SUCCESS;
            }
        } else if (pPlayer.getMainHandItem().getItem() instanceof TaglockKit
                && TaglockKit.hasEntity(pPlayer.getMainHandItem())
                && !MobUtil.areAllies(pPlayer, TaglockKit.getEntity(pPlayer.getMainHandItem()))){
            this.setPrey(TaglockKit.getEntity(pPlayer.getMainHandItem()));
            this.setTarget(this.getPrey());
            if (!pPlayer.getAbilities().instabuild) {
                TaglockKit.removeEntity(pPlayer.getMainHandItem());
            }
            if (!this.level.isClientSide) {
                if (this.getPrey() instanceof ServerPlayer player) {
                    if (CuriosFinder.hasCurio(player, ModItems.ALARMING_CHARM.get())) {
                        player.displayClientMessage(Component.translatable("info.goety.summon.hunt").withStyle(ChatFormatting.RED), true);
                        ModNetwork.sendToClient(player, new SPlayPlayerSoundPacket(SoundEvents.WOLF_HOWL, 3.0F, 0.5F));
                    }
                }
            }
            if (MobUtil.sameDimension(this, this.getPrey())) {
                this.teleportTowards(this.getPrey());
            }
            if (this.isStaying()){
                this.setStaying(false);
            }
            if (this.isGuardingArea()){
                this.setBoundPos(null);
            }
            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().isEmpty() && this.happyCool <= 0){
            this.happyCool = 40;
            this.level.broadcastEntityEvent(this, (byte) 102);
            this.playSound(SoundEvents.WOLF_AMBIENT, 1.0F, 0.5F);
            this.heal(1.0F);
            return InteractionResult.SUCCESS;
        }
    }
    return super.mobInteract(pPlayer, pHand);
}

public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand, BlockHitResult pHit) {
    if (!pLevel.isClientSide) {
        if (pLevel instanceof ServerLevel serverLevel) {
            if (pState.getValue(POWERED)) {
                boolean flag = pLevel.getDifficulty() == Difficulty.PEACEFUL;
                if (pLevel.getDifficulty() != Difficulty.PEACEFUL) {
                    Crone crone = new Crone(ModEntityType.CRONE.get(), pLevel);
                    BlockPos blockPos = BlockFinder.SummonFurtherRadius(pPos, crone, pLevel);
                    if (!serverLevel.getBlockState(blockPos.below()).isSolidRender(pLevel, blockPos.below())) {
                        blockPos = BlockFinder.SummonRadius(pPos, crone, pLevel);
                    }
                    crone.setPos(blockPos.getX(), blockPos.getY(), blockPos.getZ());
                    if (!CuriosFinder.isWitchFriendly(pPlayer) && MobUtil.validEntity(pPlayer)){
                        crone.setTarget(pPlayer);
                    }
                    crone.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(pPos), MobSpawnType.TRIGGERED, null, null);
                    crone.setPersistenceRequired();
                    SummonCircleBoss summonCircle = new SummonCircleBoss(serverLevel, blockPos, crone);
                    flag = pLevel.addFreshEntity(summonCircle);
                    if (flag) {
                        pLevel.playSound(null, summonCircle.blockPosition(), ModSounds.CRONE_LAUGH.get(), SoundSource.HOSTILE, 2.0F, 1.0F);
                    }
                }
                if (flag) {
                    pLevel.playSound(null, pPos, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 1.0F, 0.75F);
                    ServerParticleUtil.smokeParticles(ParticleTypes.SMOKE, pPos.getX() + 0.5F, pPos.getY() + 0.5F, pPos.getZ() + 0.5F, serverLevel);
                    pLevel.setBlockAndUpdate(pPos, ModBlocks.CRYSTAL_BALL.get().defaultBlockState().setValue(POWERED, false));
                }
            } else if (pPlayer.getItemInHand(pHand).getItem() instanceof TaglockKit && TaglockKit.hasEntity(pPlayer.getItemInHand(pHand))){
                ItemStack itemStack = pPlayer.getItemInHand(pHand);
                Entity entity = TaglockKit.getEntity(pPlayer.getItemInHand(pHand));
                if (entity != null && TaglockKit.isSameDimension(pPlayer, itemStack) && (pLevel.getNearestPlayer(entity, 80.0D) != null || entity instanceof Player)) {
                    SEHelper.setCamera(pPlayer, TaglockKit.getEntity(pPlayer.getItemInHand(pHand)));
                    ModNetwork.sendTo(pPlayer, new SPlayPlayerSoundPacket(ModSounds.END_WALK.get(), 1.0F, 0.5F));
                    pLevel.playSound(pPlayer, pPlayer.blockPosition(), ModSounds.END_WALK.get(), SoundSource.PLAYERS, 1.0F, 0.5F);
                } else {
                    pPlayer.displayClientMessage(Component.translatable("info.goety.taglock.difDimension"), true);
                }
            } else if (pPlayer.getItemInHand(pHand).getItem() instanceof WaystoneItem && WaystoneItem.hasBlock(pPlayer.getItemInHand(pHand))){
                ItemStack itemStack = pPlayer.getItemInHand(pHand);
                GlobalPos globalPos = WaystoneItem.getPosition(pPlayer.getItemInHand(pHand));
                if (globalPos != null && WaystoneItem.isSameDimension(pPlayer, itemStack) && pLevel.isLoaded(globalPos.pos())) {
                    SEHelper.setCamera(pPlayer, null, globalPos.pos());
                    ModNetwork.sendTo(pPlayer, new SPlayPlayerSoundPacket(ModSounds.END_WALK.get(), 1.0F, 0.5F));
                    pLevel.playSound(pPlayer, pPlayer.blockPosition(), ModSounds.END_WALK.get(), SoundSource.PLAYERS, 1.0F, 0.5F);
                } else {
                    pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.difDimension"), true);
                }
            } else if (pPlayer.getItemInHand(pHand).is(ModTags.Items.RESPAWN_BOSS) && MainConfig.CrystalBallRespawn.get() && BlockFinder.findStructure(serverLevel, pPlayer, ModTags.Structures.CRONE_SPAWNS)) {
                ItemStack itemStack = pPlayer.getItemInHand(pHand);
                if (pPlayer instanceof ServerPlayer serverPlayer) {
                    CriteriaTriggers.ITEM_USED_ON_BLOCK.trigger(serverPlayer, pPos, itemStack);
                }
                pLevel.setBlockAndUpdate(pPos, ModBlocks.CRYSTAL_BALL.get().defaultBlockState().setValue(POWERED, Boolean.TRUE));
                itemStack.shrink(1);
                pLevel.playSound(null, pPos, SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, SoundSource.BLOCKS, 1.0F, 1.0F);
            }
        }
    }
    return InteractionResult.sidedSuccess(pLevel.isClientSide);
}

public void tick() {
    if (!Vizier.this.level.isClientSide) {
        LivingEntity livingentity = Vizier.this.getTarget();
        if (livingentity != null) {
            Vizier.this.getLookControl().setLookAt(livingentity, Vizier.this.getMaxHeadXRot(), Vizier.this.getMaxHeadYRot());
            double d0 = Math.min(livingentity.getY(), Vizier.this.getY());
            double d1 = Math.max(livingentity.getY(), Vizier.this.getY()) + 1.0D;
            float f = (float) Mth.atan2(livingentity.getZ() - Vizier.this.getZ(), livingentity.getX() - Vizier.this.getX());
            ++this.duration;
            if (Vizier.this.airBound > AIR_BOUND_TIME){
                if (!Vizier.this.level.isClientSide) {
                    ServerLevel serverWorld = (ServerLevel) Vizier.this.level;
                    for (int i = 0; i < 5; ++i) {
                        double d3 = serverWorld.random.nextGaussian() * 0.02D;
                        double d4 = serverWorld.random.nextGaussian() * 0.02D;
                        double d2 = serverWorld.random.nextGaussian() * 0.02D;
                        serverWorld.sendParticles(ParticleTypes.ENCHANT, Vizier.this.getRandomX(1.0D), Vizier.this.getRandomY() + 1.0D, Vizier.this.getRandomZ(1.0D), 0, d3, d4, d2, 0.5F);
                    }
                }
            }
            if (this.duration >= 40) {
                if (Vizier.this.airBound < AIR_BOUND_TIME) {
                    for (int l = 0; l < 16; ++l) {
                        double d2 = 1.25D * (double) (l + 1);
                        this.createSpellEntity(Vizier.this.getX() + (double) Mth.cos(f) * d2, Vizier.this.getZ() + (double) Mth.sin(f) * d2, d0, d1, f, l * 2);
                        if (MobUtil.healthIsHalved(Vizier.this)) {
                            float fleft = f + 0.2F;
                            float fright = f - 0.2F;
                            this.createSpellEntity(Vizier.this.getX() + (double) Mth.cos(fleft) * d2, Vizier.this.getZ() + (double) Mth.sin(fleft) * d2, d0, d1, fleft, l);
                            this.createSpellEntity(Vizier.this.getX() + (double) Mth.cos(fright) * d2, Vizier.this.getZ() + (double) Mth.sin(fright) * d2, d0, d1, fright, l);
                        }
                    }
                } else {
                    for (int j = 0; j < 3; ++j) {
                        SwordProjectile swordProjectile = new SwordProjectile(Vizier.this, Vizier.this.level, Vizier.this.getMainHandItem());
                        double d4 = livingentity.getX() - Vizier.this.getX();
                        double d5 = livingentity.getY(0.3333333333333333D) - swordProjectile.getY();
                        double d2 = livingentity.getZ() - Vizier.this.getZ();
                        double d3 = Mth.sqrt((float) (d4 * d4 + d2 * d2));
                        swordProjectile.pickup = AbstractArrow.Pickup.CREATIVE_ONLY;
                        swordProjectile.shoot(d4 + Vizier.this.random.nextGaussian(), d5 + d3 * (double) 0.2F, d2 + Vizier.this.random.nextGaussian(), 1.6F, 0.6F);
                        if (!Vizier.this.getSensing().hasLineOfSight(livingentity)) {
                            swordProjectile.setNoPhysics(true);
                        }
                        Vizier.this.level.addFreshEntity(swordProjectile);
                    }
                    if (!Vizier.this.isSilent()) {
                        Vizier.this.playSound(SoundEvents.DROWNED_SHOOT, 1.0F, 1.0F);
                    }
                }
                this.duration = 0;
                Vizier.this.setSpellcasting(false);
                Vizier.this.setCastTimes(0);
                Vizier.this.setCasting(0);
                Vizier.this.playSound(SoundEvents.EVOKER_CAST_SPELL, 1.0F, 0.5F);
            }
        } else {
            stop();
        }
    }
}

public RitualRecipe fromNetwork(ResourceLocation recipeId, FriendlyByteBuf buffer) {
    ModShapelessRecipe recipe = serializer.fromNetwork(recipeId, buffer);
    if (recipe == null){
        return null;
    }
    String craftType = buffer.readUtf(32767);

    ResourceLocation ritualType = buffer.readResourceLocation();

    EntityType<?> entityToSummon = null;
    if (buffer.readBoolean()) {
        entityToSummon = buffer.readRegistryId();
    }

    int duration = buffer.readVarInt();
    int summonLife = buffer.readVarInt();
    int soulCost = buffer.readVarInt();

    Ingredient activationItem = Ingredient.fromNetwork(buffer);

    TagKey<EntityType<?>> entityToSacrifice = null;
    String entityToSacrificeDisplayName = "";
    if (buffer.readBoolean()) {
        var tagRL = buffer.readResourceLocation();
        entityToSacrifice = TagKey.create(Registries.ENTITY_TYPE, tagRL);
        entityToSacrificeDisplayName = buffer.readUtf();
    }

    EntityType<?> entityToConvertInto = null;
    TagKey<EntityType<?>> entityToConvert = null;
    String entityToConvertDisplayName = "";
    if (buffer.readBoolean()) {
        var tagRL = buffer.readResourceLocation();
        entityToConvert = TagKey.create(Registries.ENTITY_TYPE, tagRL);
        entityToConvertDisplayName = buffer.readUtf();
    }

    if (buffer.readBoolean()){
        entityToConvertInto = buffer.readRegistryId();
    }

    TagKey<Structure> structureTag = null;
    String structureName = "";
    if (buffer.readBoolean()) {
        var tagRL = buffer.readResourceLocation();
        structureTag = TagKey.create(Registries.STRUCTURE, tagRL);
        structureName = buffer.readUtf();
    }

    Enchantment enchantment = null;
    int xpLevelCost = 0;
    if (buffer.readBoolean()){
        enchantment = buffer.readRegistryId();
        xpLevelCost = buffer.readVarInt();
    }
    String research = "";
    if (buffer.readBoolean()){
        research = buffer.readUtf(32767);
    }

    return new RitualRecipe(recipe.getId(), recipe.getGroup(), craftType, ritualType, recipe.getResultItem(null), entityToSummon, entityToConvertInto,
            activationItem, recipe.getIngredients(), duration, summonLife, soulCost, entityToSacrifice, entityToSacrificeDisplayName, entityToConvert, entityToConvertDisplayName, structureTag, structureName, enchantment, xpLevelCost, research);
}

public void explode(HitResult pResult){
    if (!this.level.isClientSide) {
        Vec3 vec3 = Vec3.atCenterOf(this.blockPosition());
        if (pResult instanceof BlockHitResult blockHitResult){
            BlockPos blockpos = blockHitResult.getBlockPos().relative(blockHitResult.getDirection());
            if (BlockFinder.canBeReplaced(this.level, blockpos)) {
                vec3 = Vec3.atCenterOf(blockpos);
            }
        } else if (pResult instanceof EntityHitResult entityHitResult){
            Entity entity1 = entityHitResult.getEntity();
            vec3 = Vec3.atCenterOf(entity1.blockPosition());
        }
        MobUtil.explosionDamage(this.level, this.getOwner() != null ? this.getOwner() : this, this.damageSources().explosion(this, this.getOwner()), vec3.x, vec3.y, vec3.z, this.explosionPower, 0);
        if (this.level instanceof ServerLevel serverLevel){
            ServerParticleUtil.addParticlesAroundSelf(serverLevel, ModParticleTypes.BIG_FIRE.get(), this);
            ColorUtil colorUtil = new ColorUtil(0xdd9c16);
            serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, this.explosionPower + 1.0F, 1), vec3.x, BlockFinder.moveDownToGround(this), vec3.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.BIG_FIRE_GROUND.get(), vec3.x, this.getY() + 0.25D, vec3.z, 0, 0, 0, this.explosionPower);
            DustCloudParticleOption cloudParticleOptions = new DustCloudParticleOption(new Vector3f(Vec3.fromRGB24(0x7a6664).toVector3f()), 1.0F);
            DustCloudParticleOption cloudParticleOptions2 = new DustCloudParticleOption(new Vector3f(Vec3.fromRGB24(0xeca294).toVector3f()), 1.0F);
            for (int i = 0; i < 2; ++i) {
                ServerParticleUtil.circularParticles(serverLevel, cloudParticleOptions, vec3.x, this.getY() + 0.25D, vec3.z, 0, 0.14D, 0, this.explosionPower / 2.0F);
            }
            ServerParticleUtil.circularParticles(serverLevel, cloudParticleOptions2, vec3.x, this.getY() + 0.25D, vec3.z, 0, 0.14D, 0, this.explosionPower / 2.0F);
        }
        this.playSound(SoundEvents.GENERIC_EXPLODE, 4.0F, 1.0F);
        int i = this.isStaff() ? 3 : 2;
        for (int i1 = 0; i1 < i; i1++) {
            MagmaCubeServant magmaCube = ModEntityType.MAGMA_CUBE_SERVANT.get().create(this.level);
            if (magmaCube != null) {
                if (this.getOwner() != null) {
                    magmaCube.setTrueOwner(this.getOwner());
                } else {
                    magmaCube.setHostile(true);
                }
                magmaCube.finalizeSpawn((ServerLevelAccessor) this.level, this.level.getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                magmaCube.setSize(2, true);
                if (i1 == 2){
                    magmaCube.setSize(4, true);
                }
                magmaCube.moveTo(this.position());
                int i2 = this.getDefaultDuration() == 0 ? MobUtil.getSummonLifespan(this.level) : this.getDefaultDuration();
                magmaCube.setLimitedLife(i2 * (this.getDuration() + 1));
                this.level.addFreshEntity(magmaCube);
            }
        }
        if (this.isStaff()){
            for (int i1 = 0; i1 < 4; i1++) {
                Pyroclast pyroclast = new Pyroclast(this.getX(), this.getY() + 1.5F, this.getZ(), this.level);
                if (this.getOwner() != null){
                    pyroclast.setOwner(this.getOwner());
                } else {
                    pyroclast.setOwner(this);
                }
                pyroclast.setExplosionPower(this.getExplosionPower() / 2.0F);
                pyroclast.setPotency((int)this.getExtraDamage());
                pyroclast.setFlaming(0);
                MobUtil.shootUp(pyroclast, this, MobUtil.ceilingVelocity(this, 0.75F));
            }
        }
        this.discard();
    }
}

public void spreadNether(){
    if (this.level instanceof ServerLevel serverLevel) {
        int activeHeretics = this.level.getEntitiesOfClass(Mob.class, this.getBoundingBox().inflate(10.0D), living -> living.isAlive() && living instanceof IHeretic heretic && heretic.isCasting() && heretic.getMonolith() == this).size();
        Vec3 skyVec = new Vec3(this.getX(), this.getY() + this.cloudHeight, this.getZ());
        if (!this.level.canSeeSky(this.blockPosition().above())) {
            skyVec = this.level.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING, this.blockPosition()).getCenter().add(0, this.cloudHeight, 0);
        }
        if (this.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING) && MobsConfig.ObsidianMonolithSpread.get() && this.level.dimension() != Level.NETHER) {
            if (this.startSpreading()) {
                if (this.level.isEmptyBlock(BlockPos.containing(skyVec))) {
                    ServerParticleUtil.addAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, 2.0F);
                    ServerParticleUtil.addReverseAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, 6.0F);
                    ServerParticleUtil.addAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, 10.0F);
                }
                this.netherSpreaderUtil.updateCursors(this.level, this.blockPosition().below(), this.random, true);

                if (this.getSpreaderLeveling() >= 100) {
                    this.setSpreaderLeveling(0);
                    if (this.getSpreaderLevel() < 9) {
                        this.setSpreaderLevel(this.getSpreaderLevel() + 1);
                    }
                }

                if (this.getSpreaderProgress() >= 1.0F) {
                    this.setSpreaderProgress(0.0F);
                    this.setSpreaderLeveling(this.getSpreaderLeveling() + 1);
                    this.netherSpreaderUtil.clear();
                    for (int i = 0; i < 5; i++) {
                        int range = this.getSpreaderLevel();
                        BlockPos blockPos = this.blockPosition().below();
                        if (range > 0) {
                            int x = serverLevel.getRandom().nextInt(-range, range);
                            int y = serverLevel.getRandom().nextInt(-range, range / 2);
                            int z = serverLevel.getRandom().nextInt(-range, range);
                            blockPos = this.blockPosition().below().offset(x, y, z);
                        }
                        this.netherSpreaderUtil.addCursors(blockPos, 10);
                    }
                } else {
                    this.setSpreaderProgress(this.getSpreaderProgress() + (0.005F * (activeHeretics + 1)));
                }
            } else {
                ++this.startUp;
                if (this.startUp > 0) {
                    if (this.level.isEmptyBlock(BlockPos.containing(skyVec))) {
                        float radius = 4.0F;
                        float totalTime = MathHelper.minecraftDayToTicks(MobsConfig.ObsidianMonolithStartUpTime.get());
                        if (this.startUp > totalTime / 4.0F) {
                            radius = 6.0F;
                        }
                        if (this.startUp > totalTime / 2.0F) {
                            radius = 8.0F;
                        }
                        if (this.startUp > totalTime / 1.5F) {
                            radius = 12.0F;
                        }
                        ServerParticleUtil.addReverseVisualAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, radius / 2.0F);
                        ServerParticleUtil.addVisibleAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, radius);
                    }
                }
            }
        }
    }
}

public void endPossession(EntityPlayer player){

	// Reverts the possessed entity back to normal

	EntityLiving victim = getPossessee(player);

	if(victim != null){

		victim.isDead = false;
		victim.setNoAI(false);
		victim.getEntityData().removeTag(NBT_KEY);
		victim.setPosition(player.posX, player.posY, player.posZ);
		if(!player.world.isRemote) player.world.spawnEntity(victim);

		if(!player.world.isRemote){
			for(PotionEffect effect : player.getActivePotionEffects()){
				if(effect.getPotion() instanceof PotionSlowTime) continue; // Don't transfer slow time
				victim.addPotionEffect(effect);
			}
		}
	}

	// Reverts the player back to normal

	player.clearActivePotions();

	player.eyeHeight = player.getDefaultEyeHeight(); // How convenient!

	if(WizardData.get(player) != null){
		WizardData.get(player).setVariable(TIMER_KEY, 0);
		WizardData.get(player).setVariable(POSSESSEE_KEY, null);
	}

	if(!player.capabilities.isCreativeMode){
		player.capabilities.allowFlying = false;
		player.capabilities.isFlying = false;
	}

	if(player.world.isRemote && player == net.minecraft.client.Minecraft.getMinecraft().player){
		net.minecraft.client.Minecraft.getMinecraft().entityRenderer.stopUseShader();
		Wizardry.proxy.playBlinkEffect(player);
	}

	for(IAttribute attribute : INHERITED_ATTRIBUTES.keySet()){
		player.getAttributeMap().getAttributeInstance(attribute).removeModifier(INHERITED_ATTRIBUTES.get(attribute));
	}

	if(player instanceof EntityPlayerMP){

		player.inventory.clear();

		if(player.getEntityData() != null){
			player.inventory.readFromNBT(player.getEntityData().getTagList(INVENTORY_NBT_KEY, NBT.TAG_COMPOUND));
		}

		player.inventoryContainer.detectAndSendChanges();
	}

	this.playSound(player.world, player, 0, -1, null, "end");

	if(!player.world.isRemote && player instanceof EntityPlayerMP){
		WizardryPacketHandler.net.sendToAllTracking(new PacketPossession.Message(player, null, 0), player);
		WizardryPacketHandler.net.sendTo(new PacketPossession.Message(player, null, 0), (EntityPlayerMP)player);
	}
}

public void tick() {
    LivingEntity livingentity = this.mob.getTarget();
    if (livingentity != null) {
        boolean canSeeEnemy = this.mob.getSensing().hasLineOfSight(livingentity);
        boolean noRaiders = livingentity.level.getEntitiesOfClass(Raider.class, livingentity.getBoundingBox().inflate(5.0D), (entity) -> entity != this.mob && this.mob.hasLineOfSight(entity) && !(entity instanceof Tormentor)).isEmpty();

        if (canSeeEnemy) {
            ++this.seeTime;
        } else {
            this.seeTime = 0;
        }

        double distanceSq = this.mob.distanceToSqr(livingentity);
        double distance = Mth.sqrt((float) distanceSq);
        if (distance <= 5.0F) {
            if (this.isWalkable()) {
                this.mob.getMoveControl().strafe(mob.isUsingItem() ? -0.5F : -3.0F, 0);
            }
        }

        ItemStack activeStack = this.mob.getUseItem();
        boolean shouldMoveTowardsEnemy = ((distanceSq > (double) this.attackRadiusSqr) || this.seeTime < 5) && this.attackDelay == 0;
        if (shouldMoveTowardsEnemy) {
            double speedChange = this.isCrossbowUncharged() ? this.speedModifier : this.speedModifier * 0.5D;
            this.mob.getNavigation().moveTo(livingentity, speedChange);
        } else {
            this.mob.getNavigation().stop();
        }

        this.mob.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);

        if (this.crossbowState == CrossbowState.UNCHARGED && !CrossbowItem.isCharged(activeStack)) {
            if (canSeeEnemy) {
                this.mob.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.mob, item -> item instanceof CrossbowItem));
                this.crossbowState = CrossbowState.CHARGING;
                this.mob.setChargingCrossbow(true);
            }
        } else if (this.crossbowState == CrossbowState.CHARGING) {
            if (!this.mob.isUsingItem()) {
                this.crossbowState = CrossbowState.UNCHARGED;
            }

            int i = this.mob.getTicksUsingItem();
            if (i >= CrossbowItem.getChargeDuration(activeStack) || CrossbowItem.isCharged(activeStack)) {
                this.mob.releaseUsingItem();
                this.crossbowState = CrossbowState.CHARGED;
                this.attackDelay = 20 + this.mob.getRandom().nextInt(20);
                if (this.mob.getOffhandItem().getItem() instanceof FireworkRocketItem) {
                    this.mob.startUsingItem(InteractionHand.OFF_HAND);
                }
                this.mob.setChargingCrossbow(false);
            }
        } else if (this.crossbowState == CrossbowState.CHARGED) {
            --this.attackDelay;
            if (this.attackDelay == 0) {
                this.crossbowState = CrossbowState.READY_TO_ATTACK;
            }
        } else if (this.crossbowState == CrossbowState.READY_TO_ATTACK && canSeeEnemy && noRaiders) {
            this.mob.performRangedAttack(livingentity, 1.0F);
            CrossbowItem.setCharged(this.mob.getItemInHand(ProjectileUtil.getWeaponHoldingHand(this.mob, item -> item instanceof CrossbowItem)), false);
            this.crossbowState = CrossbowState.UNCHARGED;
        }

    }
}

public void tick() {
    if (this.level instanceof ServerLevel serverLevel) {
        if (this.getBlockState().getValue(VoidShrineBlock.CHARGE) >= 4) {
            if (!this.getBlockState().getValue(VoidShrineBlock.TRIGGERED)) {
                serverLevel.setBlockAndUpdate(this.worldPosition, this.getBlockState().setValue(VoidShrineBlock.TRIGGERED, true));
            } else {
                if (this.tick > 120) {
                    ++this.coolTick;
                } else {
                    ++this.tick;
                }
                if (this.tick < 100) {
                    Vec3 vec3 = Vec3.atCenterOf(this.getBlockPos());
                    if (this.level.getRandom().nextInt(20) == 0) {
                        Vec3 endVec = vec3.add(0.0D, 2.5D, 0.0D);
                        ModNetwork.sendToALL(new SLightningPacket(vec3, endVec, new ColorUtil(ChatFormatting.LIGHT_PURPLE), 2));
                    }
                    if (this.tick % 5 == 0){
                        serverLevel.sendParticles(new TeleportInShockwaveParticleOption(4, 1), vec3.x, vec3.y + 0.25F, vec3.z, 0, 0, 0, 0, 0.5F);
                    }
                    int width = this.level.getRandom().nextIntBetweenInclusive(1, 4);
                    float height = this.level.getRandom().nextFloat() * 0.5F;
                    vec3 = vec3.offsetRandom(this.level.getRandom(), 3.0F);
                    serverLevel.sendParticles(new WindBlowParticleOption(new ColorUtil(ChatFormatting.LIGHT_PURPLE), width, height), vec3.x, vec3.y, vec3.z, 0, 0.0F, 1.0F, 0.0F, 1.0F);
                }
                if (this.tick == 100) {
                    this.breakBlocksAround();
                    Vec3 vec3 = this.worldPosition.above().getCenter();
                    EnderKeeper keeper = new EnderKeeper(ModEntityType.ENDER_KEEPER.get(), serverLevel);
                    keeper.setPos(vec3);
                    keeper.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(this.worldPosition), MobSpawnType.TRIGGERED, null, null);
                    keeper.setBoundPos(this.worldPosition);
                    keeper.setPersistenceRequired();
                    serverLevel.addFreshEntity(keeper);
                    this.setChanged();
                }
                if (this.coolTick < 20) {
                    for (Player player : serverLevel.getEntitiesOfClass(Player.class, new AABB(this.getBlockPos()).inflate(64.0F), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
                        player.addEffect(new MobEffectInstance(GoetyEffects.IMPAIRED.get(), 5, 0, false, false));
                    }
                }
                ItemStack itemStack = ItemStack.EMPTY;
                LazyOptional<IItemHandler> lazyOptional = this.getCapability(ForgeCapabilities.ITEM_HANDLER, null);
                if (lazyOptional.isPresent()) {
                    if (lazyOptional.resolve().isPresent()) {
                        Optional<IItemHandler> optional = lazyOptional.resolve();
                        if (optional.isPresent()) {
                            itemStack = optional.get().getStackInSlot(0);
                        }
                    }
                }
                if (this.coolTick >= 20 && itemStack.isEmpty()) {
                    serverLevel.playSound(null, this.worldPosition, SoundEvents.RESPAWN_ANCHOR_DEPLETE.get(), SoundSource.BLOCKS, 1.0F, 0.8F);
                    serverLevel.setBlockAndUpdate(this.worldPosition, this.getBlockState().setValue(VoidShrineBlock.CHARGE, 0).setValue(VoidShrineBlock.TRIGGERED, false));
                }
            }
        } else {
            if (this.coolTick > 0) {
                this.coolTick = 0;
            }
            if (this.tick > 0) {
                this.tick = 0;
            }
        }
    }
}

public void aiStep() {
    AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
    if (!this.level.isClientSide && this.isAlive()) {
        --this.cooldown;
        if (this.cooldown <= 0 && this.getRandom().nextBoolean()) {
            this.findTarget();
            this.cooldown = 200;
        }
        if (this.getShootTarget() == null) {
            if (this.getTarget() != null && this.getTarget().isAlive()) {
                this.setShootTarget(this.getTarget());
            }
        }

        if (this.isDrinkingPotion()) {
            if (this.usingTime-- <= 0) {
                this.setUsingItem(false);
                ItemStack itemstack = this.getMainHandItem();
                this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                if (itemstack.is(Items.POTION)) {
                    List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                    if (list != null) {
                        for(MobEffectInstance mobeffectinstance : list) {
                            this.addEffect(new MobEffectInstance(mobeffectinstance));
                        }
                    }
                }

                if (attributeinstance != null) {
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                }
            }
        } else {
            Potion potion = null;
            if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                potion = Potions.WATER_BREATHING;
            } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                potion = Potions.FIRE_RESISTANCE;
            } else if (this.random.nextFloat() < 0.05F && this.getHealth() < this.getMaxHealth()) {
                potion = Potions.HEALING;
            } else if (this.random.nextFloat() < 0.5F && this.getTarget() != null && !this.hasEffect(MobEffects.MOVEMENT_SPEED) && this.getTarget().distanceToSqr(this) > 121.0D) {
                potion = Potions.SWIFTNESS;
            }

            if (potion != null) {
                this.setItemSlot(EquipmentSlot.MAINHAND, PotionUtils.setPotion(new ItemStack(Items.POTION), potion));
                this.usingTime = this.getMainHandItem().getUseDuration();
                this.setUsingItem(true);
                if (!this.isSilent()) {
                    this.level().playSound((Player)null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_DRINK, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                }

                if (attributeinstance != null) {
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                }
            }
        }

        if (this.random.nextFloat() < 7.5E-4F) {
            this.level().broadcastEntityEvent(this, (byte)15);
        }
    }

    super.aiStep();
}

protected void checkAndPerformAttack(LivingEntity enemy, double distToEnemySqr) {
    if (!Wight.this.isHiding()) {
        boolean smash = Wight.this.random.nextBoolean();
        float chance = MobUtil.healthIsHalved(Wight.this) ? 0.25F : 0.0F;
        if (!Wight.this.isMeleeAttacking() && Wight.this.targetClose(enemy, distToEnemySqr)){
            Wight.this.setMeleeAttacking(true);
            float pitch = 0.0F;
            if (Wight.this.level.getRandom().nextFloat() <= chance && !Wight.this.isHallucination()){
                Wight.this.setAnimationState(SUPER_SMASH);
                pitch = 0.5F;
            } else if (smash) {
                Wight.this.setAnimationState(SMASH);
            } else {
                Wight.this.setAnimationState(ATTACK);
            }
            Wight.this.playSound(ModSounds.WIGHT_PRE_SWING.get(), Wight.this.getSoundVolume(), Wight.this.getVoicePitch() - pitch);
        }
        if (Wight.this.isMeleeAttacking()) {
            float seconds = Wight.this.getCurrentAnimation() == Wight.this.getAnimationState(SUPER_SMASH) ? 2.05F : 1.7F;
            if (Wight.this.attackTick < MathHelper.secondsToTicks(seconds)) {
                Wight.this.setYBodyRot(Wight.this.getYHeadRot());
                if (Wight.this.getCurrentAnimation() == Wight.this.getAnimationState(SUPER_SMASH)) {
                    if (Wight.this.attackTick == 24) {
                        Wight.this.playSound(ModSounds.WIGHT_SWING.get(), Wight.this.getSoundVolume(), Wight.this.getVoicePitch() - 0.5F);
                        Difficulty difficulty = Wight.this.level.getDifficulty();
                        int h = difficulty == Difficulty.HARD ? 8 : difficulty == Difficulty.NORMAL ? 6 : 4;
                        for (int i = 0; i <= h; ++i) {
                            surroundTremor(Wight.this, i, 3, 0.0F, false, 0.1F);
                        }
                        Wight.this.level.playSound(null, Wight.this.blockPosition(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + Wight.this.level.random.nextFloat() * 0.4F);
                        Wight.this.level.playSound(null, Wight.this.blockPosition(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + Wight.this.level.random.nextFloat() * 0.4F);
                        Wight.this.level.playSound(null, Wight.this.blockPosition(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + Wight.this.level.random.nextFloat() * 0.4F);
                        if (Wight.this.targetClose(enemy, distToEnemySqr)) {
                            Wight.this.doHurtTarget(enemy);
                            if (enemy instanceof Player player){
                                Wight.this.maybeDisableShield(player, new ItemStack(Items.IRON_AXE), player.isUsingItem() ? player.getUseItem() : ItemStack.EMPTY);
                            }
                        }
                    }
                } else if (Wight.this.getCurrentAnimation() == Wight.this.getAnimationState(SMASH)) {
                    int i = Wight.this.attackFast ? 10 : 20;
                    if (Wight.this.attackTick == i) {
                        Wight.this.playSound(ModSounds.WIGHT_SWING.get(), Wight.this.getSoundVolume(), Wight.this.getVoicePitch() - 0.5F);
                        if (Wight.this.targetClose(enemy, distToEnemySqr)) {
                            Wight.this.doHurtTarget(enemy);
                            if (enemy instanceof Player player){
                                Wight.this.maybeDisableShield(player, new ItemStack(Items.STONE_AXE), player.isUsingItem() ? player.getUseItem() : ItemStack.EMPTY);
                            }
                        }
                    }
                } else {
                    int i = Wight.this.attackFast ? 7 : 14;
                    if (Wight.this.attackTick == i) {
                        Wight.this.playSound(ModSounds.WIGHT_SWING.get(), Wight.this.getSoundVolume(), Wight.this.getVoicePitch());
                        this.massiveSweep(Wight.this, 3.0D, 100.0D);
                    }
                }
            } else {
                Wight.this.setMeleeAttacking(false);
                Wight.this.teleport();
            }
        }
    } else {
        Wight.this.setMeleeAttacking(false);
    }
}

public void tick() {
    super.tick();
    if (this.level.isClientSide) {
        if (!this.isHiding()) {
            ColorUtil colorUtil = new ColorUtil(0xf169e9);
            Vec3 vec3 = this.getHorizontalLookAngle();
            if (this.tickCount % 2 == 0) {
                this.level.addParticle(new MagicSmokeParticleOption(0xf4cdf6, 0xae00bc, 10 + this.level.getRandom().nextInt(10), 0.35F), this.getX() + (vec3.x / 2.0D), this.getEyeY() + 0.35F, this.getZ() + (vec3.z / 2.0D), 0.0D, 0.01D, 0.0D);
                this.level.addParticle(ModParticleTypes.SMALL_STATION_CULT_SPELL.get(), this.getX() + (vec3.x / 2.0D), this.getEyeY() + 0.35F, this.getZ() + (vec3.z / 2.0D), colorUtil.red(), colorUtil.green(), colorUtil.blue());
            }
        }
        this.idleAnimationState.animateWhen(!this.walkAnimation.isMoving() && this.getCurrentAnimation() == 0, this.tickCount);
    } else {
        if (this.fleeCool > 0) {
            --this.fleeCool;
        }

        if (this.fleeCool <= 0) {
            if (this.getTarget() != null) {
                if (this.getTarget().distanceTo(this) <= 3.0D) {
                    this.isFleeing = true;
                    Vec3 vec3 = DefaultRandomPos.getPosAway(this, 16, 7, this.getTarget().position());
                    if (vec3 != null) {
                        this.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 1.2F);
                    }
                }

                if (this.isFleeing) {
                    ++this.fleeTime;
                    if (this.fleeTime >= MathHelper.secondsToTicks(5) || (this.getTarget().distanceTo(this) > 3.0D && this.getNavigation().isDone())) {
                        this.isFleeing = false;
                        this.fleeTime = 0;
                        this.fleeCool = MathHelper.secondsToTicks(5);
                    }
                }
            }
        }

        if (this.getCurrentAnimation() == this.getAnimationState(POST_ATTACK)) {
            ++this.postAttackTick;
            if (this.postAttackTick >= MathHelper.secondsToTicks(0.5F)) {
                this.setAnimationState(IDLE);
                this.postAttackTick = 0;
            }
        } else {
            if (this.attackCoolTick > 0) {
                --this.attackCoolTick;
            }
            if (this.postAttackTick > 0) {
                this.postAttackTick = 0;
            }
        }

        if (this.teleportCool <= 0) {
            if (!this.isStaying()) {
                if (!this.isHiding()) {
                    if (this.getTarget() != null && this.postAttackTick <= 0) {
                        if (this.getTarget().distanceTo(this) <= 10.0F) {
                            this.startHide();
                        }
                    }
                }
            }
        }
    }
}

public void onEntityTick(TickEvent.ClientTickEvent event) {
	if (event.phase == Phase.END) {
		try {
			Player player = Minecraft.getInstance().player;

			if (player != null) {
				if (this.clientWorldTicks != player.level().getGameTime()) {
					this.clientWorldTicks = player.level().getGameTime();
					EnigmaticLegacy.PROXY.updateInfinitumCounters();
				}
			}

			/*
			 * This event seems to be the only way to detect player logging out of server
			 * on client side, since PlayerEvent.PlayerLoggedOutEvent seems to only be fired
			 * on the server side.
			 */

			if (player == null) {
				if (OmniconfigWrapper.onRemoteServer) {

					/*
					 * After we log out of remote server, dismiss config values it
					 * sent us and load our own ones from local file.
					 */

					for (OmniconfigWrapper wrapper : OmniconfigWrapper.wrapperRegistry.values()) {

						EnigmaticLegacy.LOGGER.info("Dismissing values of " + wrapper.config.getConfigFile().getName() + " in favor of local config...");

						for (Omniconfig.GenericParameter param : wrapper.retrieveInvocationList()) {
							if (param.isSynchronized()) {
								String oldValue = param.valueToString();
								param.invoke(wrapper.config);

								EnigmaticLegacy.LOGGER.info("Value of '" + param.getId() + "' was restored to '" + param.valueToString() + "'; former server-forced value: " + oldValue);
							}
						}
					}

					OmniconfigWrapper.onRemoteServer = false;

				}
			}


			/*
			 * Handler for displaying queued Toasts on client.
			 */

			EnigmaticEventHandler.DEFERRED_TOASTS.tick(player);

			if (EnigmaticEventHandler.DEFERRED_TOASTS.getCooldown(player) == 1) {
				Minecraft.getInstance().getToasts().addToast(EnigmaticEventHandler.SCHEDULED_TOASTS.get(0));
				EnigmaticEventHandler.SCHEDULED_TOASTS.remove(0);

				if (EnigmaticEventHandler.SCHEDULED_TOASTS.size() > 0) {
					EnigmaticEventHandler.DEFERRED_TOASTS.put(player, 5);
				}
			}

		} catch (Exception ex) {
			// DO NOTHING
		}

	}
}

public void tick() {
    super.tick();
    if (!this.level.isClientSide) {
        if (this.level instanceof ServerLevel serverLevel){
            serverLevel.sendParticles(ModParticleTypes.CULT_SPELL.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, MathHelper.rgbParticle(this.getColor())[0], MathHelper.rgbParticle(this.getColor())[1], MathHelper.rgbParticle(this.getColor())[2], 0.5F);
        }
        if (this.isInSolid()){
            this.discard();
        }
        int i = this.duration - this.tickCount;
        if (this.area > 0) {
            if (this.random.nextInt(40) == 0 || this.tickCount == 5) {
                boolean expanded = false;
                for (Direction direction : Direction.values()) {
                    double probability = 0.4D;
                    if (direction.getAxis().isHorizontal()) {
                        probability = 0.8D;
                    }
                    if (this.level.random.nextDouble() < probability) {
                        BlockPos blockPos = this.blockPosition().relative(direction);
                        BlockState blockState = this.level.getBlockState(blockPos);
                        if (blockState.isAir() || blockState.canBeReplaced(Fluids.FLOWING_WATER)) {
                            if (this.level.getEntitiesOfClass(BrewGas.class, new AABB(blockPos)).isEmpty()) {
                                BrewGas brewGas = new BrewGas(ModEntityType.BREW_EFFECT_GAS.get(), this.level);
                                brewGas.setPos(blockPos.getX(), blockPos.getY(), blockPos.getZ());
                                brewGas.setGas(this.effects, this.brewEffects, this.duration, this.area - 1, this.owner != null ? this.owner : null);
                                if (this.level.addFreshEntity(brewGas)) {
                                    expanded = true;
                                }
                            } else {
                                expanded = true;
                            }
                        }
                    }
                }
                if (expanded) {
                    --this.area;
                }
            }
        } else if (this.tickCount >= this.duration || this.level.random.nextInt(i) == 0) {
            this.discard();
        }
        if (!this.effects.isEmpty() || !this.brewEffects.isEmpty()) {
            List<LivingEntity> list1 = this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox());
            if (!list1.isEmpty()) {
                for(LivingEntity livingentity : list1) {
                    if (livingentity.isAffectedByPotions() && !livingentity.getTags().contains(ConstantPaths.gassed())) {
                        for(MobEffectInstance mobEffectInstance : this.effects) {
                            if (mobEffectInstance.getEffect().isInstantenous()) {
                                mobEffectInstance.getEffect().applyInstantenousEffect(this, this.getOwner(), livingentity, mobEffectInstance.getAmplifier(), 0.5D);
                            } else {
                                livingentity.addEffect(new MobEffectInstance(mobEffectInstance), this);
                            }
                        }

                        for(BrewEffectInstance brewEffectInstance : this.brewEffects) {
                            if (brewEffectInstance.getEffect().canLinger()) {
                                brewEffectInstance.getEffect().applyInstantenousEffect(this, this.getOwner(), livingentity, brewEffectInstance.getAmplifier(), 0.5D);
                            }
                        }
                        livingentity.addTag(ConstantPaths.gassed());
                    }
                }
            }
        }
    }
}

public void onUpdate(){

	super.onUpdate();

	double speed = Spells.earthquake.getProperty(Earthquake.SPREAD_SPEED).doubleValue();

	if(!world.isRemote && EntityUtils.canDamageBlocks(getCaster(), world)){

		// The further the earthquake is going to spread, the finer the angle increments.
		for(float angle = 0; angle < 2 * Math.PI; angle += Math.PI / (lifetime * 1.5)){

			// Calculates coordinates for the block to be moved. The radius increases with time. The +1.5 is to
			// leave blocks in the centre untouched.
			int x = this.posX < 0 ? (int)(this.posX + ((this.ticksExisted * speed) + 1.5) * MathHelper.sin(angle) - 1)
					: (int)(this.posX + ((this.ticksExisted * speed) + 1.5) * MathHelper.sin(angle));
			int y = (int)(this.posY - 0.5);
			int z = this.posZ < 0 ? (int)(this.posZ + ((this.ticksExisted * speed) + 1.5) * MathHelper.cos(angle) - 1)
					: (int)(this.posZ + ((this.ticksExisted * speed) + 1.5) * MathHelper.cos(angle));

			BlockPos pos = new BlockPos(x, y, z);

			if(!BlockUtils.isBlockUnbreakable(world, pos) && !world.isAirBlock(pos) && world.isBlockNormalCube(pos, false)
					// Checks that the block above is not solid, since this causes the falling sand to vanish.
					&& !world.isBlockNormalCube(pos.up(), false) && BlockUtils.canBreakBlock(getCaster(), world, pos)){

				// Falling blocks do the setting block to air themselves.
				EntityFallingBlock fallingblock = new EntityFallingBlock(world, x + 0.5, y + 0.5, z + 0.5,
						world.getBlockState(new BlockPos(x, y, z)));
				fallingblock.motionY = 0.3;
				world.spawnEntity(fallingblock);
			}
		}

	}

	List<EntityLivingBase> targets = EntityUtils
			.getLivingWithinRadius((this.ticksExisted * speed) + 1.5, this.posX, this.posY, this.posZ, world);

	// In this particular instance, the caster is completely unaffected because they will always be in the
	// centre.
	targets.remove(this.getCaster());

	for(EntityLivingBase target : targets){

		// Searches in a 1 wide ring.
		if(this.getDistance(target) > (this.ticksExisted * speed) + 0.5 && target.posY < this.posY + 1
				&& target.posY > this.posY - 1){

			// Knockback must be removed in this instance, or the target will fall into the floor.
			double motionX = target.motionX;
			double motionZ = target.motionZ;

			if(this.isValidTarget(target)){
				target.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getCaster(), DamageType.BLAST),
						10 * this.damageMultiplier);
				if(!world.isRemote) target.addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, 400, 1));
			}

			// All targets are thrown, even those immune to the damage, so they don't fall into the ground.
			target.motionX = motionX;
			target.motionY = 0.8; // Throws target into the air.
			target.motionZ = motionZ;

			// Player motion is handled on that player's client so needs packets
			if(target instanceof EntityPlayerMP){
				((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
			}
		}
	}
}

public RitualRecipe fromJson(ResourceLocation recipeId, JsonObject json) {

    String group = GsonHelper.getAsString(json, "group", "");
    String craftType = GsonHelper.getAsString(json, "craftType", "");
    NonNullList<Ingredient> ingredients = itemsFromJson(GsonHelper.getAsJsonArray(json, "ingredients"));
    if (ingredients.isEmpty()) {
        throw new JsonParseException("No ingredients for shapeless recipe");
    }
    ItemStack result = ShapedRecipe.itemStackFromJson(GsonHelper.getAsJsonObject(json, "result"));

    ResourceLocation ritualType = new ResourceLocation(json.get("ritual_type").getAsString());

    EntityType<?> entityToSummon = null;
    if (json.has("entity_to_summon")) {
        entityToSummon = ForgeRegistries.ENTITY_TYPES.getValue(new ResourceLocation(GsonHelper.getAsString(json, "entity_to_summon")));
    }

    JsonElement activationItemElement =
            GsonHelper.isArrayNode(json, "activation_item") ? GsonHelper.getAsJsonArray(json,
                    "activation_item") : GsonHelper.getAsJsonObject(json, "activation_item");
    Ingredient activationItem = Ingredient.fromJson(activationItemElement);

    int duration = GsonHelper.getAsInt(json, "duration", 30);
    int summonLife = GsonHelper.getAsInt(json, "summonLife", -1);
    int soulCost = GsonHelper.getAsInt(json, "soulCost", 0);

    TagKey<EntityType<?>> entityToSacrifice = null;
    String entityToSacrificeDisplayName = "";
    if (json.has("entity_to_sacrifice")) {
        var tagRL = new ResourceLocation(GsonHelper.getAsString(json.getAsJsonObject("entity_to_sacrifice"), "tag"));
        entityToSacrifice = TagKey.create(Registries.ENTITY_TYPE, tagRL);

        entityToSacrificeDisplayName = json.getAsJsonObject("entity_to_sacrifice").get("display_name").getAsString();
    }

    EntityType<?> entityToConvertInto = null;
    TagKey<EntityType<?>> entityToConvert = null;
    String entityToConvertDisplayName = "";
    String research = "";
    Enchantment enchantment = null;
    int xpLevelCost = 0;
    if (json.has("entity_to_convert")){
        var tagRL = new ResourceLocation(GsonHelper.getAsString(json.getAsJsonObject("entity_to_convert"), "tag"));
        entityToConvert = TagKey.create(Registries.ENTITY_TYPE, tagRL);

        entityToConvertDisplayName = json.getAsJsonObject("entity_to_convert").get("display_name").getAsString();
    }
    if (json.has("entity_to_convert_into")) {
        entityToConvertInto = ForgeRegistries.ENTITY_TYPES.getValue(new ResourceLocation(GsonHelper.getAsString(json, "entity_to_convert_into")));
    }
    TagKey<Structure> structureTag = null;
    String structureName = "";
    if (json.has("structure_to_locate")){
        var tagRL = new ResourceLocation(GsonHelper.getAsString(json.getAsJsonObject("structure_to_locate"), "tag"));
        structureTag = TagKey.create(Registries.STRUCTURE, tagRL);

        structureName = json.getAsJsonObject("structure_to_locate").get("display_name").getAsString();
    }
    if (json.has("enchantment")){
        enchantment = ForgeRegistries.ENCHANTMENTS.getValue(new ResourceLocation(GsonHelper.getAsString(json, "enchantment")));
        xpLevelCost = GsonHelper.getAsInt(json, "xpLevelCost", 0);
    }
    if (json.has("research")){
        research = GsonHelper.getAsString(json, "research", "");
    }
    return new RitualRecipe(recipeId, group, craftType, ritualType,
            result, entityToSummon, entityToConvertInto, activationItem, ingredients, duration,
            summonLife, soulCost, entityToSacrifice, entityToSacrificeDisplayName,
            entityToConvert, entityToConvertDisplayName, structureTag, structureName,
            enchantment, xpLevelCost, research);
}

public void attackAI(){
    if (!this.level.isClientSide) {
        if (this.isPostTeleporting()){
            this.getNavigation().stop();
        }
        if (this.fireCooldown > 0){
            --this.fireCooldown;
        }
        if (this.fireTick > 10) {
            ++this.fireTick;
        }
        if (this.fireTick > 54){
            this.fireCooldown = 80;
            this.fireTick = 0;
            if (this.isFiring()){
                this.stopFiring();
            }
        }
        if (this.getTarget() != null && !this.isPostTeleporting()) {
            if (!this.isFiring()){
                this.getLookControl().setLookAt(this.getTarget(), 100.0F, this.getMaxHeadXRot());
            }
            if (this.getSensing().hasLineOfSight(this.getTarget())) {
                if ((this.fireCooldown <= 0 && !this.isTeleporting()
                        && this.getTarget().distanceToSqr(this) < Mth.square(this.attackRange())) || this.isFiring()) {
                    if (this.fireTick <= 10){
                        ++this.fireTick;
                    }
                    if (this.isFiring()){
                        this.getNavigation().stop();
                        double d2 = this.getTarget().getX() - this.getX();
                        double d1 = this.getTarget().getZ() - this.getZ();
                        this.setYRot(-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
                        this.yBodyRot = this.getYRot();
                    }
                    if (this.fireTick > 10) {
                        this.startFiring();
                        this.getNavigation().stop();
                    } else {
                        this.movement();
                        this.stopFiring();
                    }
                    if (this.fireTick == 20) {
                        this.magicFire(this.getTarget());
                    }
                } else {
                    if (this.fireTick <= 10) {
                        this.fireTick = 0;
                    }
                    this.stopFiring();
                    if (this.canTeleport() && this.getTarget().distanceToSqr(this) <= Mth.square(4.0F)) {
                        this.getNavigation().stop();
                        this.setIsTeleporting(true);
                    } else if (!this.isTeleporting()) {
                        this.movement();
                    }
                }
            } else {
                if (MobsConfig.WraithAggressiveTeleport.get()) {
                    if (this.canTeleport()) {
                        this.getNavigation().stop();
                        this.setIsTeleporting(true);
                    }
                }
            }
        } else {
            if (this.fireTick <= 10) {
                this.fireTick = 0;
            }
            this.setIsTeleporting(false);
        }
    }
}

public void aiStep() {
    super.aiStep();
    if (this.isHostile() && this.getMobType() != MobType.UNDEAD) {
        if (MobsConfig.RavagerHostileConvert.get()) {
            if (this.tickCount % 20 == 0) {
                if (this.hasSaddle()) {
                    if (!this.getArmor().isEmpty()) {
                        ArmoredRavager armoredRavager = this.convertTo(ModEntityType.ARMORED_RAVAGER.get(), false);
                        if (armoredRavager != null) {
                            armoredRavager.setArmorEquipment(this.getArmor());
                        }
                    } else {
                        this.convertTo(EntityType.RAVAGER, false);
                    }
                }
            }
        }
    }
    if (this.isAlive()) {
        AttributeInstance attribute = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (attribute != null) {
            if (this.isImmobile()) {
                attribute.setBaseValue(0.0D);
            } else {
                double d0 = this.getTarget() != null ? this.aggressiveSpeed() : this.regularSpeed();
                double d1 = attribute.getBaseValue();
                attribute.setBaseValue(Mth.lerp(0.1D, d1, d0));
            }
        }
        if (!this.level.isClientSide) {
            if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level, this)) {
                boolean flag = false;
                AABB aabb = this.getBoundingBox().inflate(0.2D);

                for (BlockPos blockpos : BlockPos.betweenClosed(Mth.floor(aabb.minX), Mth.floor(aabb.minY), Mth.floor(aabb.minZ), Mth.floor(aabb.maxX), Mth.floor(aabb.maxY), Mth.floor(aabb.maxZ))) {
                    BlockState blockstate = this.level.getBlockState(blockpos);
                    Block block = blockstate.getBlock();
                    if (block instanceof LeavesBlock) {
                        flag = this.level.destroyBlock(blockpos, true, this) || flag;
                    }
                }
            }
        }

        if (this.roarCool > 0){
            --this.roarCool;
        }

        if (this.roarTick > 0) {
            --this.roarTick;
            if (this.roarTick == 10) {
                this.roar();
            }
        }

        if (this.attackTick > 0) {
            --this.attackTick;
        }

        if (this.stunnedTick > 0) {
            --this.stunnedTick;
            this.stunEffect();
            if (this.stunnedTick == 0) {
                this.playSound(this.getRoarSound(), 1.0F, 1.0F);
                this.roarTick = 20;
            }
        }

        if (this.getControllingPassenger() instanceof IServant summoned
            && summoned instanceof Mob mob) {
            this.setTarget(mob.getTarget());
        }
    }
}

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
    ItemStack itemInHand = pPlayer.getItemInHand(pHand);
    Item item = itemInHand.getItem();
    ItemStack mainHandItem = this.getMainHandItem();
    if (pPlayer.isCrouching() && !(item.interactLivingEntity(itemInHand, pPlayer, this, pHand).consumesAction() || itemInHand.is(ModTags.Items.GRIMOIRES))) {
        this.unshackle(pPlayer);
        return InteractionResult.SUCCESS;
    } else if (this.getMasterOwner() != null && this.getMasterOwner() == pPlayer) {
        if (MobsConfig.PrisonerMining.get() && (item instanceof PickaxeItem || itemInHand.is(ItemTags.PICKAXES))) {
            this.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 1.0F, 1.0F);
            this.setItemSlot(EquipmentSlot.MAINHAND, itemInHand.copyWithCount(1));
            this.dropEquipment(EquipmentSlot.MAINHAND, mainHandItem);
            this.setGuaranteedDrop(EquipmentSlot.MAINHAND);
            if (!pPlayer.getAbilities().instabuild) {
                itemInHand.shrink(1);
            }
            this.updateList = 5;
            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().is(Items.STICK)) {
            this.dropEquipment(EquipmentSlot.MAINHAND, this.getMainHandItem());
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            return InteractionResult.SUCCESS;
        } else if (this.validFood(itemInHand) && this.canHaveMoreFood() && this.getInventory().canAddItem(itemInHand)) {
            this.getInventory().addItem(itemInHand.copyWithCount(1));
            if (!pPlayer.getAbilities().instabuild) {
                itemInHand.shrink(1);
            }
            this.playSound(SoundEvents.ITEM_PICKUP, 1.0F, 1.0F);
            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().is(ModItems.WAYSTONE.get())) {
            if (WaystoneItem.isSameDimension(this, pPlayer.getMainHandItem())) {
                if (WaystoneItem.getBlockEntity(pPlayer.getMainHandItem(), this.level) instanceof ChestBlockEntity chestBlock && chestBlock.canOpen(pPlayer)) {
                    if (!this.level.isClientSide) {
                        BlockPos blockPos = WaystoneItem.getBlockPos(pPlayer.getMainHandItem());
                        if (blockPos != null) {
                            this.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                            if (this.level instanceof ServerLevel serverLevel) {
                                for (int i = 0; i < 7; ++i) {
                                    double d0 = this.random.nextGaussian() * 0.02D;
                                    double d1 = this.random.nextGaussian() * 0.02D;
                                    double d2 = this.random.nextGaussian() * 0.02D;
                                    serverLevel.sendParticles(ParticleTypes.ANGRY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                                }
                            }
                            if (chestBlock.getBlockState().is(ModTags.Blocks.RAIDING_CHESTS)) {
                                this.setDumpChestPos(blockPos);
                                this.setDumpChestDim(this.level.dimension());
                            } else {
                                this.setChestPos(blockPos);
                                this.setChestDim(this.level.dimension());
                            }
                            return InteractionResult.SUCCESS;
                        }
                    }
                }
            }
            return InteractionResult.FAIL;
        } else if (pPlayer.getMainHandItem().isEmpty() && this.isMining()) {
            float f = (float)Mth.floor((Mth.wrapDegrees(pPlayer.getYRot() - 180.0F) + 22.5F) / 45.0F) * 45.0F;
            this.setYRot(f);
            this.setYBodyRot(f);
            this.setYHeadRot(f);
            this.setCustomLook(f);
            this.playSound(SoundEvents.VILLAGER_NO, 1.0F, 0.75F);
            return InteractionResult.SUCCESS;
        } else if (this.getLeader() != null) {
            this.setLeader(null);
            this.setFollowing();
            return InteractionResult.SUCCESS;
        } else if (this.getTrueOwner() instanceof OwnableEntity ownable && ownable.getOwner() == pPlayer) {
            this.setTrueOwner(pPlayer);
            this.setFollowing();
            return InteractionResult.SUCCESS;
        }
    }
    return InteractionResult.PASS;
}

public void tick() {
    super.tick();
    if (this.level instanceof ServerLevel serverLevel) {
        if (this.getWarmupDelayTicks() <= 0) {
            if (!this.sentSpikeEvent) {
                this.sentSpikeEvent = true;
                if (this.explodeEffect) {
                    SoundEvent soundEvent = SoundEvent.createVariableRangeEvent(new ResourceLocation(this.getSoundEvent()));
                    this.playSound(soundEvent, 1.0F, 1.0F);
                    ColorUtil colorUtil = new ColorUtil(this.getColor());
                    ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.BIG_CULT_SPELL.get(), this.getX(), this.getY() + 1.0F, this.getZ(), colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius());
                    ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.ROLLING_SPIRAL.get(), this.getX(), this.getY() + 1.0F, this.getZ(), colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius());
                    serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius(), 1), this.getX(), this.getY(), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius(), 1), this.getX(), this.getY(), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                }
            }
        } else {
            --this.warmupDelayTicks;
            if (this.level.getRandom().nextBoolean()) {
                ColorUtil colorUtil = new ColorUtil(this.getWarmupColor());
                ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.BIG_CULT_SPELL.get(), this.getX(), this.getY() - 0.5F, this.getZ(), colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius() / 2.0F);
            }
        }

        if (this.sentSpikeEvent){
            ++this.lifeTick;
            if (this.getParticle() == null || this.getParticle() == ModParticleTypes.NONE.get()) {
                if (this.tickCount % 5 == 0) {
                    serverLevel.sendParticles(new FoggyCloudParticleOption(new ColorUtil(this.getColor()), this.radius() / 2.0F, 1), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0, 0, 0, 0);
                }
            }
            List<LivingEntity> targets = new ArrayList<>();
            for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())){
                if (this.owner != null) {
                    if (livingEntity != this.owner && !MobUtil.areAllies(this.owner, livingEntity)) {
                        targets.add(livingEntity);
                    }
                } else {
                    targets.add(livingEntity);
                }
            }
            if (!targets.isEmpty()){
                for (LivingEntity livingEntity : targets) {
                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                        float damage = this.getDamage();
                        if (this.getPercentDamage() > 0.0F) {
                            damage = livingEntity.getMaxHealth() * this.getPercentDamage();
                        }
                        boolean flag;
                        if (this.owner != null) {
                            flag = livingEntity.hurt(ModDamageSource.acid(this, this.owner), damage);
                        } else {
                            flag = livingEntity.hurt(this.damageSources().magic(), damage);
                        }
                        if (flag) {
                            if (this.getInvTime() > -1) {
                                livingEntity.invulnerableTime = this.getInvTime();
                            }
                            if (!this.getEffects().isEmpty()) {
                                for (MobEffectInstance mobeffectinstance1 : this.getEffects()) {
                                    if (mobeffectinstance1.getEffect().isInstantenous()) {
                                        mobeffectinstance1.getEffect().applyInstantenousEffect(this, this.getOwner(), livingEntity, mobeffectinstance1.getAmplifier(), 0.5D);
                                    } else {
                                        livingEntity.addEffect(new MobEffectInstance(mobeffectinstance1), this);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (this.lifeTick >= this.getDuration()) {
                this.discard();
            }
        }
    }
}

public void aiStep() {
    super.aiStep();

    if (!this.onGround() && this.getDeltaMovement().y < 0.0D) {
        this.setDeltaMovement(this.getDeltaMovement().multiply(1.0D, 0.6D, 1.0D));
    }

    if (this.level.isClientSide) {
        this.spinAnimationState.startIfStopped(this.tickCount);
        for(int i = 0; i < 2; ++i) {
            this.level.addParticle(ParticleTypes.LARGE_SMOKE, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
            if (this.level.random.nextFloat() <= 0.25F){
                this.level.addParticle(ModParticleTypes.BIG_FIRE.get(), this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
            }
        }
    } else {
        LivingEntity follow = null;
        if (this.getTarget() != null){
            follow = this.getTarget();
        } else if (this.getTrueOwner() != null && this.isFollowing()){
            follow = this.getTrueOwner();
        }
        //Based this movement codes on Dungeon Mobs' Wildfire codes: https://github.com/Infamous-Misadventures/Dungeons-Mobs/blob/1.19/src/main/java/com/infamous/dungeons_mobs/entities/blaze/WildfireEntity.java
        if (follow != null
                && ((!this.onGround() && steepDropBelow())
                || follow.getY() > (this.getY() + 3)
                || this.getY() < follow.getY()
                || this.distanceTo(follow) >= 16.0D)) {
            if (this.getY() < follow.getY() + 5) {
                this.setDeltaMovement(0.0D, 0.04D, 0.0D);
            } else {
                this.setDeltaMovement(0.0D, -0.01D, 0.0D);
            }

            if (!this.isStaying()) {
                double x = follow.getX() - this.getX();
                double y = follow.getY() - this.getY();
                double z = follow.getZ() - this.getZ();
                double d = Math.sqrt(x * x + y * y + z * z);
                this.setDeltaMovement(this.getDeltaMovement()
                        .add(x / d * 0.2D,
                                y / d * 0.2D,
                                z / d * 0.2D)
                        .scale(0.4D));
            }
            this.move(MoverType.SELF, this.getDeltaMovement());

            this.lookAt(EntityAnchorArgument.Anchor.EYES, new Vec3(follow.getX(), follow.getEyeY(), follow.getZ()));
        }
    }

    if (this.getShields() < 4 && this.getRegenShieldTick() > 0) {
        --this.regenShieldTick;
        if (this.getRegenShieldTick() <= 0) {
            this.addShield();
        }
    }

    if (this.getShields() > 0 && this.getShieldHealth() <= 0) {
        this.breakShield();
    }

    if (this.getSummonCooldown() > 0){
        --this.summonCooldown;
    }

    if (this.getShockwaveCooldown() > 0){
        --this.shockwaveCooldown;
    }

    if (this.getFireHealCool() > 0){
        --this.fireHealCool;
    }

    if (this.getFleeingCool() > 0){
        --this.fleeingCool;
    }
}

public boolean doHurtTarget(Entity target) {
    boolean flag = false;
    Potion potion = Potions.HARMING;
    if (target instanceof LivingEntity livingEntity) {
        if (!livingEntity.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) && !livingEntity.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) && livingEntity.canBeAffected(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN))) {
            potion = Potions.SLOWNESS;
        } else if (livingEntity.getHealth() >= 8.0F && !livingEntity.hasEffect(MobEffects.POISON) && livingEntity.canBeAffected(new MobEffectInstance(MobEffects.POISON))) {
            potion = Potions.POISON;
        } else if (!livingEntity.hasEffect(MobEffects.WEAKNESS) && !livingEntity.hasEffect(MobEffects.WEAKNESS) && this.random.nextFloat() < 0.25F && livingEntity.canBeAffected(new MobEffectInstance(MobEffects.WEAKNESS))) {
            potion = Potions.WEAKNESS;
        } else if (livingEntity.isInvertedHealAndHarm()) {
            potion = Potions.HEALING;
        }

        List<MobEffectInstance> instants = new ArrayList<>();
        List<MobEffectInstance> effects = new ArrayList<>();

        for (MobEffectInstance instance : potion.getEffects()){
            if (instance.getEffect().isInstantenous()) {
                instants.add(instance);
            } else {
                double d1;
                if (this.level.getDifficulty() == Difficulty.HARD) {
                    d1 = 1.0D;
                } else {
                    d1 = 0.25D;
                }
                int i = instance.mapDuration((p_267930_) -> {
                    return (int)(d1 * (double)p_267930_ + 0.5D);
                });
                MobEffectInstance mobeffectinstance1 = new MobEffectInstance(instance.getEffect(), i, instance.getAmplifier(), instance.isAmbient(), instance.isVisible());
                if (!mobeffectinstance1.endsWithin(20)) {
                    effects.add(mobeffectinstance1);
                }
            }
        }
        if (!effects.isEmpty() || !instants.isEmpty()) {
            boolean hurt;
            if (!instants.isEmpty()) {
                hurt = !livingEntity.isDamageSourceBlocked(this.damageSources().mobAttack(this)) && !this.isInvisible();
            } else if (this.isInvisible()) {
                hurt = MobUtil.doHurtTarget(this, livingEntity, this.damageSources().indirectMagic(this, this));
            } else {
                hurt = super.doHurtTarget(livingEntity);
            }
            if (hurt) {
                if (!effects.isEmpty()) {
                    for (MobEffectInstance instance : effects) {
                        livingEntity.addEffect(new MobEffectInstance(instance));
                    }
                }
                if (!instants.isEmpty()) {
                    for (MobEffectInstance instance : instants) {
                        instance.getEffect().applyInstantenousEffect(this, this, livingEntity, instance.getAmplifier(), 1.0D);
                    }
                }
            } else if (livingEntity.isBlocking()){
                super.doHurtTarget(livingEntity);
            }
            flag = true;
        }
        if (flag) {
            if (this.hasEffect(MobEffects.INVISIBILITY)) {
                this.removeEffect(MobEffects.INVISIBILITY);
                if (this.level instanceof ServerLevel serverLevel){
                    for(int i = 0; i < 8; ++i) {
                        ColorUtil colorUtil = new ColorUtil(0x3e293c);
                        serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, colorUtil.red, colorUtil.green, colorUtil.blue, 0.5F);
                    }
                }
            }
            if (!livingEntity.isSprinting()) {
                if (this.fleeTime <= 0) {
                    this.fleeTime = MathHelper.secondsToTicks(1);
                }
            }
        }
    }
    return flag;
}

public void aiStep() {
    if (!this.level.isClientSide && this.isAlive()) {
        this.setAggressive(this.getTarget() != null);
        if (this.fleeTime > 0){
            --this.fleeTime;
        }
        AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (this.isDrinkingPotion()) {
            int i = this.usingTime;
            if (i % 4 == 0) {
                if (!this.isSilent()) {
                    this.level.playSound(null, this.getX(), this.getY(), this.getZ(), this.getDrinkingSound(this.getOffhandItem()), this.getSoundSource(), 0.5F, this.level.random.nextFloat() * 0.1F + 0.9F);
                }
            }
            if (this.usingTime-- <= 0) {
                this.setUsingItem(false);
                ItemStack itemstack = this.getOffhandItem();
                this.setItemSlot(EquipmentSlot.OFFHAND, ItemStack.EMPTY);
                if (itemstack.is(Items.POTION)) {
                    List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                    if (!list.isEmpty()) {
                        for(MobEffectInstance mobeffectinstance : list) {
                            this.addEffect(new MobEffectInstance(mobeffectinstance));
                        }
                    }
                } else if (itemstack.is(Items.MILK_BUCKET)) {
                    this.curePotionEffects(itemstack);
                }

                if (attributeinstance != null) {
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                }
            }
        } else {
            Potion potion = null;
            ItemStack milk = ItemStack.EMPTY;
            if (this.random.nextFloat() < 0.15F && this.hasHarmfulEffect()) {
                milk = new ItemStack(Items.MILK_BUCKET);
            } else if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                potion = Potions.WATER_BREATHING;
            } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                potion = Potions.FIRE_RESISTANCE;
            } else if (this.random.nextFloat() < 0.05F && this.getHealth() < this.getMaxHealth() && (this.getTarget() == null || this.getTarget().distanceTo(this) >= 8.0D)) {
                if (!this.hasEffect(MobEffects.INVISIBILITY) && !this.isInvisible()
                        && this.level.getEntitiesOfClass(Maverick.class, this.getBoundingBox().inflate(8.0D), maverick -> MobUtil.areAllies(this, maverick) && maverick.isInvisible()).size() <= 2) {
                    potion = Potions.INVISIBILITY;
                } else if (this.random.nextFloat() <= 0.25F && !this.hasEffect(MobEffects.REGENERATION)){
                    potion = Potions.REGENERATION;
                } else {
                    potion = Potions.HEALING;
                }
            } else if (this.random.nextFloat() < 0.5F && this.getTarget() != null && !this.hasEffect(MobEffects.MOVEMENT_SPEED) && this.getTarget().distanceToSqr(this) > 121.0D) {
                potion = Potions.SWIFTNESS;
            }

            ItemStack itemStack = ItemStack.EMPTY;
            if (potion != null || !milk.isEmpty()) {
                if (!milk.isEmpty()) {
                    itemStack = milk;
                } else if (potion != null) {
                    itemStack = PotionUtils.setPotion(new ItemStack(Items.POTION), potion);
                }
            }
            if (!itemStack.isEmpty()) {
                this.setItemSlot(EquipmentSlot.OFFHAND, itemStack);
                this.usingTime = this.getOffhandItem().getUseDuration();
                this.setUsingItem(true);

                if (attributeinstance != null) {
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                }
            }
        }
    }

    if (this.random.nextFloat() < 7.5E-4F) {
        this.level.broadcastEntityEvent(this, (byte)15);
    }

    super.aiStep();
}

public boolean hurt(DamageSource pSource, float pAmount) {
    LivingEntity livingEntity = this.getTarget();
    if (!this.level.isClientSide) {
        if (livingEntity != null && pSource.getEntity() instanceof LivingEntity) {
            this.increaseHitTime();
        }
    }

    int smiteLevel = 0;
    if (pSource.getDirectEntity() instanceof LivingEntity living){
        int smite = EnchantmentHelper.getEnchantmentLevel(Enchantments.SMITE, living);
        if (smite > 0){
            int smite2 = Mth.clamp(smite, 1, 5);
            int duration = MathHelper.secondsToTicks(smite2);
            this.antiRegenTotal = duration;
            this.antiRegen = duration;
            smiteLevel = smite;
            if (this.level instanceof ServerLevel){
                ModNetwork.sendToALL(new SApostleSmitePacket(this.getId(), duration));
                if (this.getCoolDown() < this.coolDownLimit()){
                    this.coolDown += 10;
                }
            }
        }
    }

    if (pSource.is(DamageTypes.FELL_OUT_OF_WORLD) && pSource.getEntity() == null){
        this.discard();
    }

    if (pSource.is(DamageTypes.LIGHTNING_BOLT) || pSource.is(DamageTypes.FALL) || pSource.is(DamageTypes.IN_WALL)){
        return false;
    }

    if (pSource.getDirectEntity() instanceof AbstractArrow && ((AbstractArrow) pSource.getDirectEntity()).getOwner() == this){
        return false;
    }

    if (this.isSettingUpSecond()){
        return false;
    }

    if (pSource.getDirectEntity() instanceof NetherMeteor || pSource.getEntity() instanceof NetherMeteor){
        return false;
    }

    if (this.moddedInvul > 0 || this.obsidianInvul > 0){
        return false;
    }

    float trueAmount = this.isInNether() ? pAmount * (1.0F - (MobsConfig.ApostleNetherDamageReduction.get() / 100.0F)) : pAmount;

    if (!this.isNoAi()) {
        if (this.getHealth() > trueAmount) {
            if (this.getHitTimes() >= this.hitTimeTeleport()) {
                this.teleport();
            } else if (pSource.getEntity() == null) {
                if (this.level.getRandom().nextBoolean()) {
                    this.teleport();
                }
            }
        }
    }

    if (!this.level.getNearbyPlayers(TargetingConditions.forCombat().selector(MobUtil.NO_CREATIVE_OR_SPECTATOR), this, this.getBoundingBox().inflate(32)).isEmpty()){
        if (!(pSource.getEntity() instanceof Player)){
            trueAmount = trueAmount / 2;
        }
    }

    if (smiteLevel > 0) {
        if (MobsConfig.ApostleSmiteDamageReduction.get() > 0) {
            float reduce = 1.0F - (MobsConfig.ApostleSmiteDamageReduction.get() / 100.0F);
            trueAmount *= reduce;
        }
    }

    if (this.isDeadOrDying()) {
        this.deathBlow = pSource;
    }

    return super.hurt(pSource, trueAmount);
}

public void aiStep() {
    if (this.activeTick > 0){
        super.aiStep();
    }
    if (!this.level.isClientSide) {
        if (this.warmupDelayTicks > 0){
            --this.warmupDelayTicks;
            if (!this.canSpawn(this.level)){
                this.discard();
            }
        } else {
            if (this.burrowCooldown > 0) {
                --this.burrowCooldown;
            } else {
                this.startBursting();
            }
        }
    }
    if (!this.isEmerging()){
        if (!this.isActivate()){
            this.setActivate(true);
            if (!this.level.isClientSide) {
                this.level.broadcastEntityEvent(this, (byte) 100);
            }
        }
        if (!this.isPerpetual()) {
            if (!this.level.isClientSide) {
                if (this.activeTick == MathHelper.secondsToTicks(this.getLifeSpan())){
                    this.burrow();
                }
                if (this.activeTick >= MathHelper.secondsToTicks(this.getLifeSpan())){
                    this.setAge(this.getAge() - this.getAgeSpeed());
                    this.level.broadcastEntityEvent(this, (byte) 5);
                }
                if (this.getAge() <= 0){
                    this.discard();
                }
            }
        } else {
            if (!this.level.isClientSide) {
                if (this.proximity) {
                    if (this.proximityTick > 0) {
                        if (!this.hasTarget() && this.getAge() >= this.localEmergingTime()) {
                            --this.proximityTick;
                        }
                    } else {
                        this.burrowThenHold();
                    }
                }
            }
        }
        if (!this.level.isClientSide) {
            if (!this.isOnFire() && !this.isDeadOrDying() && (!this.limitedLifespan || this.limitedLifeTicks > 20)) {
                if (this.getHealth() < this.getMaxHealth()){
                    if (this.getTrueOwner() instanceof Player owner) {
                        boolean curio = false;
                        int soulCost = 0;
                        int healRate = 0;
                        float healAmount = 0;
                        if (MobsConfig.NaturalMinionHeal.get()){
                            curio = CuriosFinder.hasWildRobe(owner);
                            soulCost = MobsConfig.NaturalMinionHealCost.get();
                            healRate = MobsConfig.NaturalMinionHealTime.get();
                            healAmount = MobsConfig.NaturalMinionHealAmount.get().floatValue();
                        }
                        if (curio) {
                            if (SEHelper.getSoulsAmount(owner, soulCost)) {
                                if (this.tickCount % (MathHelper.secondsToTicks(healRate) + 1) == 0) {
                                    this.heal(healAmount);
                                    Vec3 vector3d = this.getDeltaMovement();
                                    if (this.level instanceof ServerLevel serverWorld) {
                                        SEHelper.decreaseSouls(owner, soulCost);
                                        serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0, vector3d.x * -0.2D, 0.1D, vector3d.z * -0.2D, 0.5F);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

public void onProjectileImpact(ProjectileImpactEvent event) {
	if (event.getRayTraceResult() instanceof EntityHitResult) {
		EntityHitResult result = (EntityHitResult) event.getRayTraceResult();

		if (result.getEntity() instanceof Player) {
			Player player = (Player) result.getEntity();
			Entity arrow = event.getEntity();

			if (!player.level().isClientSide) {
				if (arrow instanceof Projectile) {
					Projectile projectile = (Projectile) arrow;

					if (projectile.getOwner() == player) {
						for (String tag : arrow.getTags()) {
							if (tag.startsWith("AB_DEFLECTED")) {
								try {
									int time = Integer.parseInt(tag.split(":")[1]);
									if (arrow.tickCount - time < 10)
										// If we cancel the event here it gets stuck in the infinite loop
										return;
								} catch (Exception ex) {
									ex.printStackTrace();
								}
							}
						}
					}
				}

				boolean trigger = false;
				double chance = 0.0D;

				if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ANGEL_BLESSING)) {
					trigger = true;
					chance += AngelBlessing.deflectChance.getValue().asModifier(false);
				}

				if (SuperpositionHandler.hasCurio(player, EnigmaticItems.THE_CUBE)) {
					trigger = true;
					chance += 0.35;
				}

				if (EnigmaticItems.ENIGMATIC_AMULET.hasColor(player, AmuletColor.VIOLET)) {
					trigger = true;
					chance += 0.15;
				}

				if (trigger && Math.random() <= chance) {
					event.setCanceled(true);

					arrow.setDeltaMovement(arrow.getDeltaMovement().scale(-1.0D));
					arrow.yRotO = arrow.getYRot() + 180.0F;
					arrow.setYRot(arrow.getYRot() + 180.0F);;

					if (arrow instanceof AbstractArrow absar) {
						if (!(absar instanceof ThrownTrident)) {
							absar.setOwner(player);
						}

						((AccessorAbstractArrowEntity)absar).clearHitEntities();
						absar.pickup = Pickup.CREATIVE_ONLY;
						absar.setPierceLevel((byte) 0);
					} else if (arrow instanceof AbstractHurtingProjectile) {
						((AbstractHurtingProjectile) arrow).setOwner(player);

						((AbstractHurtingProjectile) arrow).xPower = -((AbstractHurtingProjectile) arrow).xPower;
						((AbstractHurtingProjectile) arrow).yPower = -((AbstractHurtingProjectile) arrow).yPower;
						((AbstractHurtingProjectile) arrow).zPower = -((AbstractHurtingProjectile) arrow).zPower;
					}

					arrow.getTags().removeIf(tag -> tag.startsWith("AB_DEFLECTED"));
					arrow.addTag("AB_DEFLECTED:" + arrow.tickCount);

					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 64.0D, player.level().dimension())), new PacketForceArrowRotations(arrow.getId(), arrow.getYRot(), arrow.getXRot(), arrow.getDeltaMovement().x, arrow.getDeltaMovement().y, arrow.getDeltaMovement().z, arrow.getX(), arrow.getY(), arrow.getZ()));
					player.level().playSound(null, player.blockPosition(), EnigmaticSounds.DEFLECT, SoundSource.PLAYERS, 1.0F, 0.95F + (float) (Math.random() * 0.1D));
				}
			} /*else {
				if (event.getEntity().getTags().contains("enigmaticlegacy.redirected")) {
					event.setCanceled(true);
					event.getEntity().removeTag("enigmaticlegacy.redirected");
				}
			}*/
		}
	}
}

public void tick() {
    super.tick();
    if (this.level.isClientSide()) {
        if (this.isAlive()) {
            this.idleAnimationState.animateWhen(!this.walkAnimation.isMoving() && this.isCurrentAnimation(IDLE), this.tickCount);
            if (this.walkAnimation.isMoving()) {
                if (this.onGround() && this.tickCount % 5 == 0) {
                    ColorUtil colorUtil = new ColorUtil(16711680);
                    this.level.addParticle(ModParticleTypes.REDSTONE_DEBRIS.get(), this.getX(), this.getY() + 0.1F, this.getZ(), colorUtil.red, colorUtil.green, colorUtil.blue);
                }
            }
        }
    }
    if (this.isAlive()) {
        if (!this.level.isClientSide) {
            if (this.isMeleeAttacking()) {
                this.getNavigation().stop();
                ++this.attackTick;
                if (this.attackTick >= MathHelper.secondsToTicks(1)){
                    this.setMeleeAttacking(false);
                    this.setAnimationState(IDLE);
                } else if (this.getCurrentAnimation() != this.getAnimationState(ATTACK)){
                    this.setAnimationState(ATTACK);
                }
            } else {
                this.setAnimationState(IDLE);
            }
            if (this.getTarget() != null){
                if (this.getTarget().isAlive() && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(this.getTarget())){
                    if (this.hasLineOfSight(this.getTarget())) {
                        if (this.targetClose(this.getTarget(), this.distanceToSqr(this.getTarget()))) {
                            if (!this.isMeleeAttacking()) {
                                this.setMeleeAttacking(true);
                            }
                            if (this.attackTick == 8) {
                                this.doHurtTarget(this.getTarget());
                                this.playSound(ModSounds.REDSTONE_CUBE_ATTACK.get(), 0.6F, 1.0F);
                            }
                        } else {
                            this.getNavigation().moveTo(this.getTarget(), 1.25F);
                        }
                    }
                }
                if (!EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(this.getTarget())) {
                    this.setTarget(null);
                }
            }
            ItemStack itemStack = this.getMainHandItem();
            if (!itemStack.isEmpty() && MobsConfig.RedstoneCubeBlockFind.get()){
                Block block = Block.byItem(itemStack.getItem());
                if (this.tickCount % 20 == 0) {
                    List<BlockPos> blockPosList = new ArrayList<>();
                    this.detectPos = null;
                    for (int i = -16; i <= 16; ++i){
                        for (int j = -16; j <= 16; ++j){
                            for (int k = -16; k <= 16; ++k){
                                BlockPos blockPos = this.blockPosition().offset(i, j, k);
                                if (this.level.getBlockState(blockPos).getBlock() == block){
                                    blockPosList.add(blockPos);
                                }
                            }
                        }
                    }
                    if (!blockPosList.isEmpty()){
                        blockPosList.sort(Comparator.comparingDouble(blockPos -> this.distanceToSqr(Vec3.atCenterOf(blockPos))));
                        if (blockPosList.stream().findFirst().isPresent()){
                            BlockPos blockPos = blockPosList.stream().findFirst().get();
                            float distance = 1.0F - ((float) this.distanceToSqr(Vec3.atCenterOf(blockPos)) / Mth.square(16.0F));
                            this.bigGlow = distance;
                            this.playSound(ModSounds.TOCK.get(), distance, 1.5F);
                            this.detectPos = Vec3.atCenterOf(blockPos);
                        }
                    }
                }
            } else {
                this.detectPos = null;
            }
            this.bigGlow = Math.max(this.bigGlow - 0.01F, 0.0F);
            ModNetwork.sentToTrackingEntityAndPlayer(this, new SRCGlowPacket(this.getId(), this.bigGlow));
        } else {
            this.glow();
        }
    }
}

public void tick() {
    super.tick();
    if (this.isAlive()){
        if (!this.level.isClientSide) {
            AttributeInstance modifiableattributeinstance = this.getAttribute(Attributes.ATTACK_DAMAGE);
            AttributeInstance modifiableattributeinstance2 = this.getAttribute(Attributes.ATTACK_KNOCKBACK);
            if (modifiableattributeinstance != null) {
                if (this.isLeaping()) {
                    if (this.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                        modifiableattributeinstance.removeModifier(LEAP_ATTACK_MODIFIER);
                        modifiableattributeinstance.addTransientModifier(LEAP_ATTACK_MODIFIER);
                    }
                } else {
                    if (modifiableattributeinstance.hasModifier(LEAP_ATTACK_MODIFIER)) {
                        modifiableattributeinstance.removeModifier(LEAP_ATTACK_MODIFIER);
                    }
                }
            }
            if (modifiableattributeinstance2 != null) {
                if (this.isLeaping()) {
                    if (this.getAttribute(Attributes.ATTACK_KNOCKBACK) != null) {
                        modifiableattributeinstance2.removeModifier(LEAP_KNOCKBACK_MODIFIER);
                        modifiableattributeinstance2.addTransientModifier(LEAP_KNOCKBACK_MODIFIER);
                    }
                } else {
                    if (modifiableattributeinstance2.hasModifier(LEAP_KNOCKBACK_MODIFIER)) {
                        modifiableattributeinstance2.removeModifier(LEAP_KNOCKBACK_MODIFIER);
                    }
                }
            }

            if (this.restTick > 0) {
                this.setAnimationState(REST);
                --this.restTick;
                if (this.restTick == (REST_TIME - 1)){
                    this.playSound(ModSounds.LEAPLEAF_REST.get(), this.getSoundVolume(), this.getVoicePitch());
                }
            } else {
                if (!this.isMeleeAttacking() && !this.isChestPound() && !this.isLeaping()) {
                    ++this.idleTime;
                    if (this.level.random.nextFloat() <= 0.05F && !this.isMoving() && this.hurtTime <= 0 && (this.getTarget() == null || this.getTarget().isDeadOrDying()) && !this.isNovelty && this.idleTime >= MathHelper.secondsToTicks(10)) {
                        this.idleTime = 0;
                        this.isNovelty = true;
                        this.level.broadcastEntityEvent(this, (byte) 22);
                    }
                    if (this.isNovelty){
                        this.setAnimationState(ALERT);
                    } else {
                        this.setAnimationState(IDLE);
                    }
                } else {
                    this.isNovelty = false;
                    this.noveltyTick = 0;
                    this.level.broadcastEntityEvent(this, (byte) 23);
                }
                if (this.isMeleeAttacking()) {
                    ++this.attackTick;
                    if (this.attackTick >= MathHelper.secondsToTicks(1.29F)){
                        this.setMeleeAttacking(false);
                    }
                }
                if (this.isCharging()) {
                    if (this.chargeTick < MathHelper.secondsToTicks(2)) {
                        ++this.chargeTick;
                    }
                }
                if (this.isLeaping()) {
                    ++this.leapTick;
                }
                if (this.coolTick > 0) {
                    --this.coolTick;
                }
                if (this.isNovelty){
                    ++noveltyTick;
                    this.level.broadcastEntityEvent(this, (byte) 24);
                    if (this.noveltyTick >= MathHelper.secondsToTicks(5.75F) || this.isMoving() || this.getTarget() != null || this.hurtTime > 0){
                        this.isNovelty = false;
                        this.noveltyTick = 0;
                        this.level.broadcastEntityEvent(this, (byte) 23);
                    }
                }
            }
        }
    }
}

private boolean doCasting(World world, EntityLivingBase caster, SpellModifiers modifiers){

	if(world.canBlockSeeSky(new BlockPos(caster))){

		double maxRadius = getProperty(EFFECT_RADIUS).doubleValue();

		for(int i = 0; i < getProperty(LIGHTNING_BOLTS).intValue(); i++){

			double radius = maxRadius * CENTRE_RADIUS_FRACTION + world.rand.nextDouble() * maxRadius
					* (1 - CENTRE_RADIUS_FRACTION) * modifiers.get(WizardryItems.blast_upgrade);
			float angle = world.rand.nextFloat() * (float)Math.PI * 2;

			double x = caster.posX + radius * MathHelper.cos(angle);
			double z = caster.posZ + radius * MathHelper.sin(angle);
			Integer y = BlockUtils.getNearestFloor(world, new BlockPos(x, caster.posY, z), (int)maxRadius);

			if(y != null){

				if(!world.isRemote){
					EntityLightningBolt lightning = new EntityLightningBolt(world, x, y, z, false);
					lightning.getEntityData().setUniqueId(LightningBolt.SUMMONER_NBT_KEY, caster.getUniqueID());
					lightning.getEntityData().setFloat(LightningBolt.DAMAGE_MODIFIER_NBT_KEY, modifiers.get(SpellModifiers.POTENCY));
					world.addWeatherEffect(lightning);
				}

				// Secondary chaining effect
				List<EntityLivingBase> secondaryTargets = EntityUtils.getLivingWithinRadius(
						getProperty(SECONDARY_RANGE).doubleValue(), x, y + 1, z, world);

				for(int j = 0; j < Math.min(secondaryTargets.size(), getProperty(SECONDARY_MAX_TARGETS).intValue()); j++){

					EntityLivingBase secondaryTarget = secondaryTargets.get(j);

					if(AllyDesignationSystem.isValidTarget(caster, secondaryTarget)){

						if(world.isRemote){

							ParticleBuilder.create(Type.LIGHTNING).pos(x, y, z).target(secondaryTarget).spawn(world);

							ParticleBuilder.spawnShockParticles(world, secondaryTarget.posX,
									secondaryTarget.posY + secondaryTarget.height / 2,
									secondaryTarget.posZ);
						}

						playSound(world, secondaryTarget, 0, -1, modifiers);

						secondaryTarget.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
								getProperty(SECONDARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

						// Tertiary chaining effect

						List<EntityLivingBase> tertiaryTargets = EntityUtils.getLivingWithinRadius(
								getProperty(TERTIARY_RANGE).doubleValue(), secondaryTarget.posX,
								secondaryTarget.posY + secondaryTarget.height / 2, secondaryTarget.posZ, world);

						for(int k = 0; k < Math.min(tertiaryTargets.size(), getProperty(TERTIARY_MAX_TARGETS).intValue()); k++){

							EntityLivingBase tertiaryTarget = tertiaryTargets.get(k);

							if(!secondaryTargets.contains(tertiaryTarget)
									&& AllyDesignationSystem.isValidTarget(caster, tertiaryTarget)){

								if(world.isRemote){
									ParticleBuilder.create(Type.LIGHTNING).entity(secondaryTarget)
											.pos(0, secondaryTarget.height / 2, 0).target(tertiaryTarget).spawn(world);
									ParticleBuilder.spawnShockParticles(world, tertiaryTarget.posX,
											tertiaryTarget.posY + tertiaryTarget.height / 2,
											tertiaryTarget.posZ);
								}

								playSound(world, tertiaryTarget, 0, -1, modifiers);

								tertiaryTarget.attackEntityFrom(
										MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
										getProperty(TERTIARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));
							}
						}
					}
				}
			}
		}

		return true;
	}

	return false;
}

private boolean teleport(double pX, double pY, double pZ) {
    BlockPos.MutableBlockPos blockpos$mutableblockpos = new BlockPos.MutableBlockPos(pX, pY, pZ);

    while(blockpos$mutableblockpos.getY() > this.level.getMinBuildHeight() && !this.level.getBlockState(blockpos$mutableblockpos).blocksMotion()) {
        blockpos$mutableblockpos.move(Direction.DOWN);
    }

    BlockState blockstate = this.level.getBlockState(blockpos$mutableblockpos);
    boolean flag = blockstate.blocksMotion();
    boolean flag1 = blockstate.getFluidState().is(FluidTags.WATER) && !this.isSwimming();
    if (flag && !flag1) {
        net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(this, pX, pY, pZ);
        if (event.isCanceled()) return false;
        Vec3 vec3 = this.position();
        boolean flag2 = this.randomTeleport(event.getTargetX(), event.getTargetY(), event.getTargetZ(), false);
        if (this.isSwimming() || (this.getTarget() != null && this.getTarget().isInWater())){
            flag2 = MobUtil.randomWaterTeleport(this, event.getTargetX(), event.getTargetY(), event.getTargetZ(), false);
        }
        if (flag2) {
            if (this.getTarget() != null && !this.isScreaming() && this.getTarget().distanceTo(this) >= 4.0D && this.spawnCool <= 0 && this.level.random.nextFloat() <= 0.25F){
                this.setSummoning(true);
                this.level.broadcastEntityEvent(this, (byte) 8);
                this.playSound(ModSounds.WIGHT_SUMMON.get(), 3.0F, 1.0F);
                int amount = 3 + this.level.random.nextInt(1 + this.level.getDifficulty().getId());
                for (int j = 0; j < amount; ++j){
                    CarrionMaggot carrionMaggot = new CarrionMaggot(ModEntityType.CARRION_MAGGOT.get(), this.level);
                    BlockPos blockPos = BlockFinder.SummonRadius(this.blockPosition(), carrionMaggot, this.level);
                    carrionMaggot.setTrueOwner(this);
                    carrionMaggot.setLimitedLife(MobUtil.getSummonLifespan(this.level));
                    carrionMaggot.moveTo(blockPos, this.getYRot(), this.getXRot());
                    carrionMaggot.finalizeSpawn((ServerLevelAccessor) this.level, this.level.getCurrentDifficultyAt(blockPos), MobSpawnType.MOB_SUMMONED, null, null);
                    DelayedSummon delayedSummon = new DelayedSummon(this.level, blockPos, carrionMaggot, true, true, this);
                    delayedSummon.setLifeSpan(MathHelper.secondsToTicks(this.random.nextInt(1 + j)));
                    this.level.addFreshEntity(delayedSummon);
                }
                this.spawnCool = MathHelper.secondsToTicks(10);
            } else if ((this.level.random.nextFloat() <= 0.25F && this.hidingCooldown <= 0) || this.isScreaming()){
                this.setHide(true);
                this.level.broadcastEntityEvent(this, (byte) 4);
                this.applyDarkness();
            } else if (this.level.random.nextFloat() <= 0.25F){
                this.applyDarkness();
                if (this.level.random.nextFloat() <= 0.15F && this.getTarget() != null){
                    int amount = 4 + this.level.random.nextInt(1 + this.level.getDifficulty().getId());
                    for (int j = 0; j < amount; ++j){
                        Wight falseWight = new Wight(ModEntityType.WIGHT.get(), this.level);
                        Vec3 vec31 = BlockFinder.SummonRadius(this.blockPosition(), falseWight, this.level).getCenter();
                        falseWight.setTrueOwner(this);
                        falseWight.setLimitedLife(MathHelper.secondsToTicks(5 + this.level.random.nextInt(10)));
                        falseWight.setPos(vec31);
                        double d2 = this.getTarget().getX() - falseWight.getX();
                        double d1 = this.getTarget().getZ() - falseWight.getZ();
                        falseWight.setYRot(-((float)Mth.atan2(d2, d1)) * (180F / (float)Math.PI));
                        float f = (float) Mth.atan2(d1, d2);
                        float f2 = f + (float) j * (float) Math.PI * 0.25F + 4.0F;
                        vec31 = new Vec3(this.getTarget().getX() + (double) Mth.cos(f2) * 4.0D, this.getTarget().getY(), this.getTarget().getZ() + (double) Mth.sin(f2) * 4.0D);
                        falseWight.setPos(vec31);
                        falseWight.finalizeSpawn((ServerLevelAccessor) this.level, this.level.getCurrentDifficultyAt(BlockPos.containing(vec31)), MobSpawnType.MOB_SUMMONED, null, null);
                        falseWight.spawnHallucination();
                        falseWight.setHealth(this.getHealth());
                        this.level.addFreshEntity(falseWight);
                    }
                }
            }
            if (this.level instanceof ServerLevel serverLevel){
                for (int i = 0; i < 16; ++i) {
                    serverLevel.sendParticles(ParticleTypes.LARGE_SMOKE,
                            this.prevX + (double)this.getBbWidth() * (2.0D * this.random.nextDouble() - 1.0D) * 0.5D,
                            this.prevY + (double)this.getBbHeight() * this.random.nextDouble(),
                            this.prevZ + (double)this.getBbWidth() * (2.0D * this.random.nextDouble() - 1.0D) * 0.5D,
                            0, 0.0D, 0.0D, 0.0D, 0.5F);
                }
                serverLevel.sendParticles(new TeleportInShockwaveParticleOption(), this.prevX, this.prevY + 0.5F, this.prevZ, 0, 0, 0, 0, 0.5F);
                if (!this.isHiding()){
                    this.teleportHit(serverLevel);
                }
            }
            this.level.gameEvent(GameEvent.TELEPORT, vec3, GameEvent.Context.of(this));
            if (!this.isSilent()) {
                this.level.playSound((Player)null, this.prevX, this.prevY, this.prevZ, ModSounds.WIGHT_TELEPORT.get(), this.getSoundSource(), 1.0F, 0.5F);
            }
        }

        return flag2;
    } else {
        return false;
    }
}

public void attackAI(){
    if (!this.level.isClientSide) {
        if (this.fireCooldown > 0){
            --this.fireCooldown;
        }
        if (this.fireTick > 10) {
            ++this.fireTick;
        }
        if (this.fireTick > 54){
            this.fireCooldown = 80;
            this.fireTick = 0;
            if (this.isFiring()){
                this.stopFiring();
            }
        }
        if (this.getTarget() != null) {
            if (!this.isFiring()){
                this.getLookControl().setLookAt(this.getTarget(), 100.0F, this.getMaxHeadXRot());
            }
            if (this.getSensing().hasLineOfSight(this.getTarget())) {
                if (!this.isBreathing()) {
                    if ((this.fireCooldown <= 0 && !this.isTeleporting()
                            && this.getTarget().distanceToSqr(this) < Mth.square(this.attackRange())) || this.isFiring()) {
                        if (this.fireTick <= 10){
                            ++this.fireTick;
                        }
                        if (this.isFiring()){
                            this.getNavigation().stop();
                            double d2 = this.getTarget().getX() - this.getX();
                            double d1 = this.getTarget().getZ() - this.getZ();
                            this.setYRot(-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
                            this.yBodyRot = this.getYRot();
                        }
                        if (this.fireTick > 10) {
                            this.startFiring();
                            this.getNavigation().stop();
                        } else {
                            this.movement();
                            this.stopFiring();
                        }
                        if (this.fireTick == 20) {
                            this.magicFire(this.getTarget());
                        }
                    } else {
                        if (this.fireTick <= 10) {
                            this.fireTick = 0;
                        }
                        this.stopFiring();
                        this.movement();
                    }
                } else {
                    this.getNavigation().stop();
                    this.fireCooldown = 100;
                    this.fireTick = 0;
                    ++this.breathTick;
                    if (this.initial != null) {
                        this.lookAt(EntityAnchorArgument.Anchor.EYES, this.initial);
                    }
                    this.setYRot(this.yHeadRot);
                    if (this.breathTick >= 20) {
                        Vec3 vector3d = new Vec3(this.getTarget().getX() - this.initial.x, (this.getTarget().getY() + this.getTarget().getEyeHeight()) - this.initial.y, this.getTarget().getZ() - this.initial.z);
                        vector3d = vector3d.normalize();
                        double speed = 0.25D;

                        this.initial = this.initial.add(vector3d.x * speed, vector3d.y * speed, vector3d.z * speed);

                        this.level.broadcastEntityEvent(this, (byte) 10);
                        Entity entity = MobUtil.getSingleTarget(this.level, this, 8, 3.0F);
                        if (entity != null) {
                            this.doBreathing(entity);
                            this.gameEvent(GameEvent.PROJECTILE_SHOOT);
                        }
                    } else {
                        this.initial = new Vec3(this.getTarget().getX(), this.getTarget().getEyeY(), this.getTarget().getZ());
                    }
                    if (this.breathTick >= MathHelper.secondsToTicks(3.5F) || this.hurtStop()){
                        this.stopBreathing();
                    }
                }
            }
        } else {
            if (this.fireTick <= 10) {
                this.fireTick = 0;
            }
            this.stopBreathing();
        }
    }
}

public ItemStack getBrew() {
    ItemStack brew = new ItemStack(ModItems.BREW.get());
    if (this.level != null && !this.level.isClientSide) {
        List<MobEffectInstance> effects = new ArrayList<>();
        List<BrewEffectInstance> blockEffects = new ArrayList<>();
        int hidden = 0;
        for (int i = 0; i < this.getCapacity(); i++) {
            ItemStack itemStack = this.getItem(i);
            Item item = itemStack.getItem();
            BrewModifier brewModifier = new BrewEffects().getModifier(item);
            BrewEffect brewEffect = new BrewEffects().getEffectFromCatalyst(item);
            BrewingRecipe brewingRecipe = this.level.getRecipeManager().getAllRecipesFor(ModRecipeSerializer.BREWING_TYPE.get()).stream().filter(recipe -> recipe.input.test(itemStack)).findFirst().orElse(null);
            EntityType<?> entityType = this.getSacrificed(i);
            if (entityType != null){
                brewingRecipe = this.level.getRecipeManager().getAllRecipesFor(ModRecipeSerializer.BREWING_TYPE.get()).stream()
                        .filter(recipe -> {
                            if (recipe.getEntityTypeTag() != null){
                                return entityType.is(recipe.getEntityTypeTag());
                            } else if (recipe.getEntityType() != null) {
                                return entityType == recipe.getEntityType();
                            }
                            return false;
                        }).findFirst().orElse(null);
                brewEffect = new BrewEffects().getEffectFromSacrifice(entityType);
            }
            BrewingRecipe finalBrewingRecipe = brewingRecipe;
            if (brewingRecipe != null && effects.stream().noneMatch(effect -> effect.getEffect() == finalBrewingRecipe.output)) {
                effects.add(new MobEffectInstance(brewingRecipe.output, brewingRecipe.duration));
            } else if (brewEffect != null){
                if (brewEffect instanceof PotionBrewEffect potionBrewEffect){
                    effects.add(new MobEffectInstance(potionBrewEffect.mobEffect, potionBrewEffect.duration));
                } else {
                    blockEffects.add(new BrewEffectInstance(brewEffect, brewEffect.duration));
                }
            } else if (brewModifier != null) {
                if (brewModifier.getId().equals(BrewModifier.HIDDEN)) {
                    hidden++;
                } else if (brewModifier.getId().equals(BrewModifier.SPLASH) && brew.is(ModItems.BREW.get())) {
                    brew = new ItemStack(ModItems.SPLASH_BREW.get());
                } else if (brewModifier.getId().equals(BrewModifier.LINGERING) && brew.is(ModItems.SPLASH_BREW.get())) {
                    brew = new ItemStack(ModItems.LINGERING_BREW.get());
                } else if (brewModifier.getId().equals(BrewModifier.GAS) && brew.is(ModItems.LINGERING_BREW.get())) {
                    brew = new ItemStack(ModItems.GAS_BREW.get());
                }
            }
        }
        for (int i = 0; i < effects.size(); i++) {
            for (int j = 0; j < this.getDuration(); j++) {
                MobEffect type = effects.get(i).getEffect();
                int duration = effects.get(i).getDuration();
                effects.set(i, new MobEffectInstance(type, type.isInstantenous() ? duration : duration * 2));
            }
            for (int j = 0; j < this.getAmplifier(); j++) {
                MobEffect type = effects.get(i).getEffect();
                int duration = effects.get(i).getDuration();
                effects.set(i, new MobEffectInstance(type, type.isInstantenous() ? duration : duration / 2, effects.get(i).getAmplifier() + 1));
            }
            for (int j = 0; j < hidden; j++) {
                MobEffect type = effects.get(i).getEffect();
                int duration = effects.get(i).getDuration();
                int amplifier = effects.get(i).getAmplifier();
                effects.set(i, new MobEffectInstance(type, duration, amplifier, false, false, false));
            }
        }
        for (int i = 0; i < blockEffects.size(); i++) {
            for (int j = 0; j < this.getDuration(); j++) {
                BrewEffect type = blockEffects.get(i).getEffect();
                int duration = blockEffects.get(i).getDuration();
                blockEffects.set(i, new BrewEffectInstance(type, type.isInstantenous() ? duration : duration * 2));
            }
            for (int j = 0; j < this.getAmplifier(); j++) {
                BrewEffect type = blockEffects.get(i).getEffect();
                int duration = blockEffects.get(i).getDuration();
                blockEffects.set(i, new BrewEffectInstance(type, duration, blockEffects.get(i).getAmplifier() + 1));
            }
        }
        BrewUtils.setCustomEffects(brew, effects, blockEffects);
        BrewUtils.setAreaOfEffect(brew, this.getAoE());
        BrewUtils.setLingering(brew, this.getLingering());
        BrewUtils.setQuaff(brew, this.getQuaff());
        BrewUtils.setVelocity(brew, this.getVelocity());
        BrewUtils.setAquatic(brew, this.isAquatic());
        BrewUtils.setFireProof(brew, this.isFireProof());
        brew.getOrCreateTag().putInt("CustomPotionColor", BrewUtils.getColor(effects, blockEffects));
        brew.getOrCreateTag().putBoolean("CustomBrew", true);
        this.markUpdated();
    }
    return brew;
}

public void tick() {
    super.tick();
    this.noPhysics = true;
    if (this.getItem().isEmpty()){
        this.discard();
    }
    Vec3 vec3 = this.getDeltaMovement();
    double d0 = this.getX() + vec3.x;
    double d1 = this.getY() + vec3.y;
    double d2 = this.getZ() + vec3.z;
    double d3 = vec3.horizontalDistance();
    this.setXRot(lerpRotation(this.xRotO, (float)(Mth.atan2(vec3.y, d3) * (double)(180F / (float)Math.PI))));
    this.setYRot(lerpRotation(this.yRotO, (float)(Mth.atan2(vec3.x, vec3.z) * (double)(180F / (float)Math.PI))));
    if (this.getOwner() != null){
        double d4 = this.getOwner().getX() - this.getX();
        double d5 = this.getOwner().getZ() - this.getZ();
        this.setYRot(-((float) Mth.atan2(d4, d5)) * (180F / (float) Math.PI));
    }
    if (!this.level.isClientSide) {
        ++this.life;
        if (this.life < 80){
            this.setDeltaMovement(0.0D, 0.05D, 0.0D);
        } else if (this.life > 100) {
            if (this.getOwner() != null && this.getOwner().level.dimension() == this.level.dimension()) {
                if (this.getOwner().distanceTo(this) >= 64){
                    this.teleportTowards(this.getOwner());
                } else {
                    Vec3 vector3d = this.getOwner().getEyePosition();
                    Vec3 vector3d1 = this.position();
                    Vec3 vector3d2 = vector3d.subtract(vector3d1);
                    if (vector3d2.lengthSqr() > 1) {
                        vector3d2.normalize();
                    }
                    double speed = 0.1D;
                    Vec3 motion = new Vec3(vector3d2.x * speed, vector3d2.y * speed, vector3d2.z * speed);
                    this.setDeltaMovement(motion);
                    if (this.getOwner().getBoundingBox().inflate(1.0F).intersects(this.getBoundingBox())){
                        if (this.getOwner() instanceof Player player){
                            if (this.getSecondsCool() > 0){
                                SEHelper.addSpecificCooldown(player, this.getItem(), MathHelper.secondsToTicks(this.getSecondsCool()));
                            }
                            if (!player.getInventory().add(this.getItem())) {
                                player.drop(this.getItem(), false, true);
                            } else {
                                if (!this.level.isClientSide){
                                    ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ITEM_PICKUP, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 1.4F + 2.0F));
                                }
                            }
                        } else {
                            this.level.addFreshEntity(new ItemEntity(this.level, this.getX(), this.getY(), this.getZ(), this.getItem()));
                        }
                        this.discard();
                    }
                }
            } else {
                if (this.getOwner() instanceof Player player){
                    if (this.getSecondsCool() > 0){
                        SEHelper.addSpecificCooldown(player, this.getItem(), MathHelper.secondsToTicks(this.getSecondsCool()));
                    }
                    if (!player.getInventory().add(this.getItem())) {
                        player.drop(this.getItem(), false, true);
                    } else {
                        if (!this.level.isClientSide){
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ITEM_PICKUP, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 1.4F + 2.0F));
                        }
                    }
                } else {
                    this.level.addFreshEntity(new ItemEntity(this.level, this.getX(), this.getY(), this.getZ(), this.getItem()));
                }
                this.discard();
            }
        }
    }

    if (this.isInWater()) {
        for(int i = 0; i < 4; ++i) {
            this.level.addParticle(ParticleTypes.BUBBLE, d0 - vec3.x * 0.25D, d1 - vec3.y * 0.25D, d2 - vec3.z * 0.25D, vec3.x, vec3.y, vec3.z);
        }
    } else {
        this.level.addParticle(this.getParticle(), d0 - vec3.x * 0.25D + this.random.nextDouble() * 0.6D - 0.3D, d1 - vec3.y * 0.25D, d2 - vec3.z * 0.25D + this.random.nextDouble() * 0.6D - 0.3D, vec3.x, vec3.y, vec3.z);
    }

    if (!this.level.isClientSide) {
        this.setPos(d0, d1, d2);
    } else {
        this.setPosRaw(d0, d1, d2);
    }

}

public void tick() {
    super.tick();
    if (this.level instanceof ServerLevel serverLevel) {
        float area = this.getAreaOfEffect() / 2;
        float f = 1.5F + area;
        float f5 = (float) Math.PI * f * f;
        for (int k1 = 0; (float) k1 < f5; ++k1) {
            float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
            float f7 = Mth.sqrt(this.random.nextFloat()) * f;
            float f8 = Mth.cos(f6) * f7;
            float f9 = Mth.sin(f6) * f7;
            serverLevel.sendParticles(ModParticleTypes.BURNING.get(), this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 1, 0, 0, 0, 0);
        }
        ColorUtil color = ColorUtil.GOLD;
        ServerParticleUtil.windParticle(serverLevel, color, (f - 1.0F) + serverLevel.random.nextFloat() * 0.5F, 0.0F, this.getId(), this.position());
        ServerParticleUtil.windParticle(serverLevel, color, f + serverLevel.random.nextFloat() * 0.5F, 0.0F, this.getId(), this.position());

        if (this.tickCount == 20 || this.getImmediate()){
            for (int j1 = 0; j1 < 16; ++j1) {
                for (int k1 = 0; (float) k1 < f5; ++k1) {
                    float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                    float f7 = Mth.sqrt(this.random.nextFloat()) * f;
                    float f8 = Mth.cos(f6) * f7;
                    float f9 = Mth.sin(f6) * f7;
                    serverLevel.sendParticles(ParticleTypes.FLAME, this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 0, 0, 0.5D, 0, 0.5F);
                }
            }
            List<Entity> targets = new ArrayList<>();
            float area0 = 1.0F + area;
            AABB aabb = this.getBoundingBox();
            AABB aabb1 = new AABB(aabb.minX - area0, aabb.minY - 1.0F, aabb.minZ - area0, aabb.maxX + area0, aabb.maxY + 1.0F, aabb.maxZ + area0);
            for (Entity entity : this.level.getEntitiesOfClass(Entity.class, aabb1)){
                if (this.owner != null) {
                    if (entity != this.owner && !MobUtil.areAllies(entity, this.owner)) {
                        if (this.owner instanceof Mob mob && this.owner instanceof Enemy && entity instanceof Enemy) {
                            if (mob.getTarget() == entity) {
                                targets.add(entity);
                            }
                        } else {
                            targets.add(entity);
                        }
                    }
                } else {
                    targets.add(entity);
                }
            }
            if (!targets.isEmpty()){
                for (Entity entity : targets) {
                    if ((this.owner != null && CuriosFinder.hasUnholySet(this.owner))) {
                        if (entity instanceof LivingEntity livingEntity) {
                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.BURN_HEX.get(), 1200));
                        }
                        entity.hurt(ModDamageSource.hellfire(this, this.owner), AttributesConfig.ApostleMagicDamage.get().floatValue() + this.getExtraDamage());
                    } else {
                        float damage = 5.0F;
                        if (this.owner != null){
                            if (this.owner instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                                damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
                            }
                            entity.hurt(ModDamageSource.magicFireBreath(this, this.owner), damage + this.getExtraDamage());
                        } else {
                            entity.hurt(damageSources().magic(), damage + this.getExtraDamage());
                        }
                    }
                    if (entity instanceof LivingEntity livingEntity) {
                        MobUtil.push(livingEntity, 0.0D, 1.0D, 0.0D, 0.5D);
                        if (this.burning > 0){
                            livingEntity.setSecondsOnFire(this.burning * 4);
                        }
                    }
                }
            }
        }
    }
    if (this.tickCount > 20 || (this.getImmediate() && this.tickCount > 5)){
        this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.25D, 0.0D));
        this.move(MoverType.SELF, this.getDeltaMovement());
    }
    if (this.tickCount == 20 || (this.getImmediate() && this.tickCount == 5)){
        this.playSound(SoundEvents.GENERIC_EXPLODE, 1.0F, 0.5F);
    }
    if (this.owner != null){
        if (this.owner.isDeadOrDying() || this.owner.isRemoved()){
            this.discard();
        }
    }
    if (this.tickCount % 30 == 0){
        this.discard();
    }
}

public void updateTask(){

	// Only executed server side.

	double distanceSq = this.attacker.getDistanceSq(this.target.posX, this.target.posY,
			this.target.posZ);
	boolean targetIsVisible = this.attacker.getEntitySenses().canSee(this.target);

	if(targetIsVisible){
		++this.seeTime;
	}else{
		this.seeTime = 0;
	}

	if(distanceSq <= (double)this.maxAttackDistance && this.seeTime >= 20){
		this.attacker.getNavigator().clearPath();
	}else{
		this.attacker.getNavigator().tryMoveToEntityLiving(this.target, this.speed);
	}

	this.attacker.getLookHelper().setLookPositionWithEntity(this.target, 30.0F, 30.0F);

	if(this.continuousSpellTimer > 0){

		this.continuousSpellTimer--;

		// If the target goes out of range or out of sight...
		if(distanceSq > (double)this.maxAttackDistance || !targetIsVisible
		// ...or the spell is cancelled via events...
				|| MinecraftForge.EVENT_BUS
						.post(new SpellCastEvent.Tick(Source.NPC, attacker.getContinuousSpell(), attacker,
								attacker.getModifiers(), this.continuousSpellDuration - this.continuousSpellTimer))
				// ...or the spell no longer succeeds...
				|| !attacker.getContinuousSpell().cast(attacker.world, attacker, EnumHand.MAIN_HAND,
						this.continuousSpellDuration - this.continuousSpellTimer, target, attacker.getModifiers())
				// ...or the time has elapsed...
				|| this.continuousSpellTimer == 0){

			// ...reset the continuous spell timer and start the cooldown.
			this.continuousSpellTimer = 0;
			this.cooldown = attacker.getContinuousSpell().getCooldown() + this.baseCooldown;
			setContinuousSpellAndNotify(Spells.none, new SpellModifiers());
			return;

		}else if(this.continuousSpellDuration - this.continuousSpellTimer == 1){
			// On the first tick, if the spell did succeed, fire SpellCastEvent.Post.
			MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.NPC, attacker.getContinuousSpell(),
					attacker, attacker.getModifiers()));
		}

	}else if(--this.cooldown == 0){

		if(distanceSq > (double)this.maxAttackDistance || !targetIsVisible){
			return;
		}

		double dx = target.posX - attacker.posX;
		double dz = target.posZ - attacker.posZ;

		List<Spell> spells = new ArrayList<Spell>(attacker.getSpells());

		if(spells.size() > 0){

			if(!attacker.world.isRemote){

				// New way of choosing a spell; keeps trying until one works or all have been tried

				Spell spell;

				while(!spells.isEmpty()){

					spell = spells.get(attacker.world.rand.nextInt(spells.size()));

					SpellModifiers modifiers = attacker.getModifiers();

					if(spell != null && attemptCastSpell(spell, modifiers)){
						// The spell worked, so we're done!
						attacker.rotationYaw = (float)(Math.atan2(dz, dx) * 180.0D / Math.PI) - 90.0F;
						return;
					}else{
						spells.remove(spell);
					}
				}
			}
		}

	}else if(this.cooldown < 0){
		// This should only be reached when the entity first starts attacking. Stops it attacking instantly.
		this.cooldown = this.baseCooldown;
	}
}

public void tick() {
    this.target = this.leapleaf.getTarget();

    this.leapleaf.navigation.stop();
    if (this.target != null) {
        this.leapleaf.lookAt(EntityAnchorArgument.Anchor.EYES, target.position());
        if (this.leapleaf.chargeTick == 1){
            this.leapleaf.setAnimationState(CHARGE);
            this.leapleaf.playSound(ModSounds.LEAPLEAF_CHARGE.get(), this.leapleaf.getSoundVolume(), this.leapleaf.getVoicePitch());
        }
        if (this.leapleaf.chargeTick < MathHelper.secondsToTicks(1.21F)){
            this.leapleaf.navigation.stop();
        } else {
            if (this.leapleaf.distanceTo(this.target) <= 6.5F){
                this.leapleaf.setCharging(false);
                this.leapleaf.chargeTick = 0;
                this.leapleaf.setAnimationState(LEAP);
                this.leapleaf.playSound(ModSounds.LEAPLEAF_LEAP.get(), this.leapleaf.getSoundVolume(), this.leapleaf.getVoicePitch());
                this.leapleaf.setLeaping(true);
                double dx = this.target.getX() - this.leapleaf.getX();
                double dy = this.target.getY() - this.leapleaf.getY();
                double dz = this.target.getZ() - this.leapleaf.getZ();
                double horizontalDist = Math.sqrt(dx * dx + dz * dz);
                if (horizontalDist > 1.0E-4) {
                    this.leapDirection = new Vec3(dx / horizontalDist, dy, dz / horizontalDist);
                } else {
                    this.leapDirection = this.leapleaf.getLookAngle();
                }
            } else {
                this.leapleaf.navigation.moveTo(this.target, 1.25F);
            }
        }

        if (this.leapleaf.leapTick == 1) {
            double leapSpeed = 0.6D;
            this.leapleaf.setDeltaMovement(this.leapDirection.x * leapSpeed, 0.75 + Mth.clamp(this.leapDirection.y * 0.05D, 0, 0.5), this.leapDirection.z * leapSpeed);
        }
    }

    double xLeft = this.leapleaf.getX() + this.leapleaf.getHorizontalLeftLookAngle().x;
    double zLeft = this.leapleaf.getZ() + this.leapleaf.getHorizontalLeftLookAngle().z;
    double xRight = this.leapleaf.getX() + this.leapleaf.getHorizontalRightLookAngle().x;
    double zRight = this.leapleaf.getZ() + this.leapleaf.getHorizontalRightLookAngle().z;
    if (this.leapleaf.isLeaping() && this.leapleaf.onGround() && this.leapleaf.leapTick > 1) {
        Vec3 vec3 = MobUtil.getFrontPos(this.leapleaf, 1);
        AABB aabb = new AABB(vec3, vec3).inflate(3.0D);
        boolean random = this.leapleaf.random.nextFloat() <= 0.25F;
        for (LivingEntity target : this.leapleaf.level.getEntitiesOfClass(LivingEntity.class, aabb)) {
            if (target != this.leapleaf && !target.isAlliedTo(this.leapleaf) && !this.leapleaf.isAlliedTo(target)) {
                if (target.isDamageSourceBlocked(ModDamageSource.summonAttack(this.leapleaf, this.leapleaf.getTrueOwner()))) {
                    MobUtil.disableShield(target, 100);
                }
                if (this.leapleaf.doHurtTarget(target) && (random || !target.isAlive())){
                    this.leapleaf.restTick = REST_TIME;
                }
            }
        }
        this.leapleaf.setLeaping(false);
        this.leapleaf.coolTick = MathHelper.secondsToTicks(2);
        if (this.leapleaf.level instanceof ServerLevel serverLevel){
            BlockPos leftPos = BlockPos.containing(xLeft, this.leapleaf.getY() - 1.0F, zLeft);
            BlockPos rightPos = BlockPos.containing(xRight, this.leapleaf.getY() - 1.0F, zRight);
            BlockState leftState = serverLevel.getBlockState(leftPos);
            BlockState rightState = serverLevel.getBlockState(rightPos);
            BlockParticleOption leftOption = new BlockParticleOption(ParticleTypes.BLOCK, leftState);
            BlockParticleOption rightOption = new BlockParticleOption(ParticleTypes.BLOCK, rightState);
            for (int i = 0; i < 8; ++i) {
                ServerParticleUtil.circularParticles(serverLevel, leftOption, xLeft, this.leapleaf.getY() + 0.25D, zLeft, 1.5F);
            }
            for (int i = 0; i < 8; ++i) {
                ServerParticleUtil.circularParticles(serverLevel, rightOption, xRight, this.leapleaf.getY() + 0.25D, zRight, 1.5F);
            }
            int left = leftState.getMapColor(serverLevel, leftPos).col;
            int right = rightState.getMapColor(serverLevel, rightPos).col;
            ColorUtil colorUtil = left == 0 ? ColorUtil.WHITE : new ColorUtil(left);
            ColorUtil colorUtil1 = right == 0 ? ColorUtil.WHITE : new ColorUtil(right);
            serverLevel.sendParticles(new SmashParticleOption(colorUtil, 5, 10), xLeft, BlockFinder.moveDownToGround(this.leapleaf), zLeft, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            serverLevel.sendParticles(new SmashParticleOption(colorUtil1, 5, 10), xRight, BlockFinder.moveDownToGround(this.leapleaf), zRight, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            BlockPos blockPos2 = BlockPos.containing(xLeft, this.leapleaf.getY() + 0.25D, zLeft);
            BlockPos blockPos3 = BlockPos.containing(xRight, this.leapleaf.getY() + 0.25D, zRight);

            for (Direction direction : Direction.values()){
                if (direction.getAxis().isHorizontal()){
                    BlockPos blockPos4 = blockPos2.relative(direction, 2);
                    BlockPos blockPos5 = blockPos3.relative(direction, 2);
                    serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), blockPos4.getX(), blockPos4.getY(), blockPos4.getZ(), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 0.5F);
                    serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), blockPos5.getX(), blockPos5.getY(), blockPos5.getZ(), 0, colorUtil1.red(), colorUtil1.green(), colorUtil1.blue(), 0.5F);
                }
            }
        }
    }
}

