public void tick() {
    super.tick();
    if (!this.level.isClientSide) {
        this.setClimbing(this.horizontalCollision);
        AttributeInstance modifiableattributeinstance = this.getAttribute(Attributes.FOLLOW_RANGE);
        if (MobUtil.isInBrightLight(this)){
            if (modifiableattributeinstance != null) {
                if (this.getAttribute(Attributes.FOLLOW_RANGE) != null) {
                    modifiableattributeinstance.removeModifier(DETECTION_MODIFIER);
                    modifiableattributeinstance.addTransientModifier(DETECTION_MODIFIER);
                }
            }
        } else {
            if (modifiableattributeinstance != null) {
                if (modifiableattributeinstance.hasModifier(DETECTION_MODIFIER)) {
                    modifiableattributeinstance.removeModifier(DETECTION_MODIFIER);
                }
            }
        }
    }
    if (this.summonCooldown > 0) {
        --this.summonCooldown;
    }
    if (this.webCooldown > 0) {
        --this.webCooldown;
    }
    if (this.chargeCooldown > 0) {
        --this.chargeCooldown;
    }
    if (this.backOffCooldown > 0) {
        --this.backOffCooldown;
    }
    if (this.meleeTicks > 0) {
        --this.meleeTicks;
    } else {
        if (this.getCurrentAnimation() == this.getAnimationState(ATTACK)){
            this.setAnimationState(0);
        }
    }
    if (this.jumpTicks > 0){
        --this.jumpTicks;
    } else {
        if (this.getCurrentAnimation() == this.getAnimationState(JUMP)){
            this.setAnimationState(0);
        }
    }
    if (this.getAttackType() > 0) {
        ++this.attackTicks;
        if (!this.level.isClientSide) {
            this.level.broadcastEntityEvent(this, (byte) 4);
        }
    } else {
        if (!this.level.isClientSide) {
            this.level.broadcastEntityEvent(this, (byte) 5);
        }
    }
    AttributeInstance modifiableattributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
    if (modifiableattributeinstance != null){
        if (this.getAttackType() > 0 || this.isMeleeAttacking()) {
            modifiableattributeinstance.removeModifier(SPEED_STOP);
            modifiableattributeinstance.addTransientModifier(SPEED_STOP);
        } else {
            if (modifiableattributeinstance.hasModifier(SPEED_STOP)) {
                modifiableattributeinstance.removeModifier(SPEED_STOP);
            }
        }
    }
    if (this.getAttackType() != 0){
        this.getNavigation().stop();
        this.getMoveControl().strafe(0.0F, 0.0F);
    }

    if (this.random.nextInt(200) == 0) {
        this.circleDirection = !this.circleDirection;
    }

    this.circleTick += this.circleDirection ? 1 : -1;

    if (this.getTarget() != null) {
        Predicate<Entity> predicate = entity -> entity.isAlive()
                && ((entity instanceof SpiderServant spiderServant && spiderServant.getTrueOwner() == this) || entity instanceof Spider spider && spider.getTarget() != null && spider.getTarget() == this.getTarget() && this.isHostile());
        int i = this.level.getEntitiesOfClass(LivingEntity.class, this.getTarget().getBoundingBox().inflate(8.0D)
                , predicate).size();

        if (this.getAttackType() == 0
                && i > 0
                && this.getTarget().distanceTo(this) >= 4.0D) {
            this.isCircling = true;
            this.circleTarget(this.getTarget(), this.circleTick);
            MobUtil.instaLook(this, this.getTarget());
        } else {
            this.isCircling = false;
        }
    } else {
        this.isCircling = false;
    }
    this.attackAI();
}

public void tick() {
    super.tick();
    this.setNoGravity(true);

    LivingEntity owner = this.getOwner();

    this.move(MoverType.SELF, this.getDeltaMovement());

    for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(this.growProgress), entity -> entity != this && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(entity))) {
        if (owner instanceof Mob mob && mob instanceof IHeretic heretic) {
            if (!MobUtil.areAllies(mob, entity)) {
                if (entity == mob.getTarget() || MobUtil.getOwner(entity) == mob.getTarget() || entity instanceof Mob mob1 && mob1.getTarget() == mob) {
                    heretic.setChantTimes(heretic.getChantTimes() + 1);
                    if (heretic.getChantTimes() == 3) {
                        Vec3 vec3 = new Vec3(entity.getX(), entity.getY(), entity.getZ());
                        FireBlastTrap fireBlastTrap = new FireBlastTrap(owner.level, vec3.x, vec3.y + 0.25D, vec3.z);
                        MobUtil.moveDownToGround(fireBlastTrap);
                        fireBlastTrap.setOwner(owner);
                        fireBlastTrap.setAreaOfEffect(2.0F);
                        fireBlastTrap.setExtraDamage(this.getExtraDamage());
                        fireBlastTrap.setBurning(this.getBurning());
                        this.level.addFreshEntity(fireBlastTrap);
                    }
                }
            }
        } else if (owner != null && owner.getUseItem().getItem() instanceof InfernalTome){
            if (!MobUtil.areAllies(owner, entity) && entity.isAttackable()) {
                ItemStack itemStack = owner.getUseItem();
                CompoundTag compoundTag = itemStack.getTag();
                if (compoundTag != null){
                    if (compoundTag.contains(InfernalTome.CHANT_TIMES)){
                        InfernalTome.increaseChantTimes(itemStack);
                        if (InfernalTome.getChantTimes(itemStack) == 3){
                            Vec3 vec3 = new Vec3(entity.getX(), entity.getY(), entity.getZ());
                            FireBlastTrap fireBlastTrap = new FireBlastTrap(owner.level, vec3.x, vec3.y + 0.25D, vec3.z);
                            MobUtil.moveDownToGround(fireBlastTrap);
                            fireBlastTrap.setOwner(owner);
                            fireBlastTrap.setAreaOfEffect(2.0F);
                            fireBlastTrap.setExtraDamage(this.getExtraDamage());
                            fireBlastTrap.setBurning(this.getBurning());
                            this.level.addFreshEntity(fireBlastTrap);
                        }
                    }
                }
            }
        }
    }

    Vec3 motion = this.getDeltaMovement();
    float horizontalMotionMagnitude = Mth.sqrt((float) motion.horizontalDistanceSqr());
    double motionX = motion.x();
    double motionY = motion.y();
    double motionZ = motion.z();

    if (this.xRotO == 0.0F && this.yRotO == 0.0F) {
        this.setYRot((float) (Mth.atan2(motionX, motionZ) * (double) (180F / (float) Math.PI)));
        this.setXRot((float) (Mth.atan2(motionY, horizontalMotionMagnitude) * (double) (180F / (float) Math.PI)));
        this.yRotO = this.getYRot();
        this.xRotO = this.getXRot();
    }

    this.setYRot((float) (Mth.atan2(motionX, motionZ) * (double) (180F / (float) Math.PI)));

    for (this.setXRot((float) (Mth.atan2(motionY, horizontalMotionMagnitude) * (double) (180F / (float) Math.PI))); this.getXRot() - this.xRotO < -180.0F; this.xRotO -= 360.0F) {
    }

    while (this.getXRot() - this.xRotO >= 180.0F) {
        this.xRotO += 360.0F;
    }

    while (this.getYRot() - this.yRotO < -180.0F) {
        this.yRotO -= 360.0F;
    }

    while (this.getYRot() - this.yRotO >= 180.0F) {
        this.yRotO += 360.0F;
    }

    float yRot = Mth.lerp(0.2F, this.yRotO, this.getYRot());
    float xRot = Mth.lerp(0.2F, this.xRotO, this.getXRot());
    this.setYRot(yRot);
    this.setXRot(xRot);
    if (!this.level.isClientSide) {
        this.setYRotVisual(this.getYRot());
        this.setXRotVisual(this.getXRot());
    }
    this.prevGrowProgress = this.growProgress;

    if (this.growProgress < 0.1F) {
        this.growProgress += 0.025F;
    } else {
        this.growProgress += 0.1F;
    }

    if (this.tickCount > 40) {
        this.discard();
    }
}

public void onConfirmedDeath(LivingDeathEvent event) {
	if (event.getEntity() instanceof ServerPlayer) {
		ServerPlayer player = (ServerPlayer) event.getEntity();

		/*
		 * Updates Enigmatic Amulet/Scroll of Postmortal Recall possession status for LivingDropsEvent.
		 */

		if (event.isCanceled()) {
			POSTMORTAL_POSESSIONS.removeAll(player);
			return;
		}

		SuperpositionHandler.setPersistentBoolean(player, "DeathFromEntity", event.getSource().getEntity() instanceof LivingEntity);

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ENIGMATIC_AMULET) || SuperpositionHandler.hasItem(player, EnigmaticItems.ENIGMATIC_AMULET)) {
			POSTMORTAL_POSESSIONS.put(player, EnigmaticItems.ENIGMATIC_AMULET);
		} else if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ASCENSION_AMULET) || SuperpositionHandler.hasItem(player, EnigmaticItems.ASCENSION_AMULET)) {
			POSTMORTAL_POSESSIONS.put(player, EnigmaticItems.ASCENSION_AMULET);
		}

		if (SuperpositionHandler.hasItem(player, EnigmaticItems.CURSED_STONE)) {
			POSTMORTAL_POSESSIONS.put(player, EnigmaticItems.CURSED_STONE);

			for (List<ItemStack> list : player.getInventory().compartments) {
				for (ItemStack itemstack : list) {
					if (!itemstack.isEmpty() && itemstack.getItem() == EnigmaticItems.CURSED_STONE) {
						itemstack.setCount(0);
					}
				}
			}
		}

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ESCAPE_SCROLL)) {
			POSTMORTAL_POSESSIONS.put(player, EnigmaticItems.ESCAPE_SCROLL);

			if (!player.level().isClientSide) {
				ItemStack tomeStack = SuperpositionHandler.getCurioStack(player, EnigmaticItems.ESCAPE_SCROLL);
				PermanentItemEntity droppedTomeStack = new PermanentItemEntity(player.level(), player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), tomeStack.copy());
				droppedTomeStack.setPickupDelay(10);
				player.level().addFreshEntity(droppedTomeStack);

				tomeStack.shrink(1);
			}
		}

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ELDRITCH_AMULET) && SuperpositionHandler.isTheWorthyOne(player)) {
			EnigmaticItems.ELDRITCH_AMULET.storeInventory(player);
			POSTMORTAL_POSESSIONS.put(player, EnigmaticItems.ELDRITCH_AMULET);
		} else {
			for (int i = 0; i < player.getInventory().armor.size(); i++) {
				ItemStack armor = player.getInventory().armor.get(i);

				if (armor.getEnchantmentLevel(EnigmaticEnchantments.ETERNAL_BINDING) > 0) {
					player.getInventory().armor.set(i, ItemStack.EMPTY);
					SuperpositionHandler.setPersistentTag(player, "EternallyBoundArmor" + i, armor.serializeNBT());
				}
			}
		}
	}

	if (event.getSource().getEntity() instanceof ServerPlayer player) {
		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.THE_CUBE)) {
			EnigmaticItems.THE_CUBE.applyRandomEffect(player, true);
		}

		if (event.getEntity() instanceof WitherBoss) {
			int killedWither = SuperpositionHandler.getPersistentInteger(player, "TimesKilledWither", 0);

			if (killedWither <= 0) {
				Quote.BREATHES_RELIEVED.play(player, 140);
				killedWither++;
			} else if (killedWither == 1) {
				Quote.APPALING_PRESENCE.play(player, 140);
				killedWither++;
			} else if (killedWither == 2) {
				Quote.TERRIFYING_FORM.play(player, 140);
				killedWither++;
			} else if (killedWither > 2 && killedWither < 5) {
				killedWither++;
			} else if (killedWither == 4) {
				Quote.WHETHER_IT_IS.play(player, 140);
				killedWither++;
			}

			SuperpositionHandler.setPersistentInteger(player, "TimesKilledWither", killedWither);
		}
	}

	if (event.getSource().getDirectEntity() instanceof ServerPlayer attacker) {
		ItemStack weapon = attacker.getMainHandItem();

		if (weapon.is(EnigmaticItems.ELDRITCH_PAN)) {
			ResourceLocation killedType = ForgeRegistries.ENTITY_TYPES.getKey(event.getEntity().getType());

			if (EldritchPan.addKillIfNotPresent(weapon, killedType)) {
				attacker.sendSystemMessage(Component.translatable("message.enigmaticlegacy.eldritch_pan_buff")
						.withStyle(ChatFormatting.GOLD));
			}
		}
	}
}

public void tick() {
    super.tick();

    if (this.target != null){
        if (this.target.distanceTo(this.whisperer) > 13.0F){
            this.whisperer.navigation.moveTo(this.target, 1.0F);
        } else {
            MobUtil.instaLook(this.whisperer, this.target);
            this.whisperer.navigation.stop();
            boolean first = this.whisperer.getRandom().nextBoolean();
            float chance = this.whisperer.getRandom().nextFloat();
            int spellTime = 0;
            int cooldown = MathHelper.secondsToTicks(1);
            if (!this.whisperer.isSummoning()) {
                if (first) {
                    if (chance >= 0.5F) {
                        this.type = 1;
                    } else if (chance >= 0.35F) {
                        this.type = 3;
                    } else if (chance >= 0.15F) {
                        this.type = 2;
                    }
                } else {
                    if (chance >= 0.75F) {
                        this.type = 3;
                    } else if (chance >= 0.15F) {
                        this.type = 1;
                    } else if (chance >= 0.1F) {
                        this.type = 2;
                    }
                }
                this.whisperer.setSummoning(true);
            } else {
                if (this.type == 1){
                    spellTime = 34;
                    if (this.whisperer.getCurrentAnimation() != this.whisperer.getAnimationState(SUMMON)){
                        this.whisperer.setAnimationState(SUMMON);
                        this.whisperer.playSound(this.whisperer.getSummonSound(), this.whisperer.getSoundVolume(), this.whisperer.getVoicePitch());
                    }
                    if (this.whisperer.summonTick == 20){
                        int random = this.whisperer.random.nextInt(5);
                        Direction direction = Direction.fromYRot(this.target.getYHeadRot());
                        if (random == 0) {
                            WandUtil.summonMinorSquareTrap(this.whisperer, this.target, this.whisperer.getVines(), direction, 0);
                        } else if (random == 1) {
                            WandUtil.summonHallTrap(this.whisperer, this.target, this.whisperer.getVines(), 0);
                        } else if (random == 2) {
                            WandUtil.summonCubeTrap(this.whisperer, this.target, this.whisperer.getVines(), 0);
                        } else if (random == 3) {
                            WandUtil.summonCircleTrap(this.whisperer, this.target, this.whisperer.getVines(), direction, 0);
                        } else {
                            WandUtil.summonSurroundTrap(this.whisperer, this.target, this.whisperer.getVines(), 0);
                        }
                    }
                    cooldown = spellTime + MathHelper.secondsToTicks(1);
                } else if (this.type == 2){
                    spellTime = 63;
                    if (this.whisperer.getCurrentAnimation() != this.whisperer.getAnimationState(SUMMON_POISON)){
                        this.whisperer.setAnimationState(SUMMON_POISON);
                        this.whisperer.playSound(this.whisperer.getSummonPoisonSound(), this.whisperer.getSoundVolume(), this.whisperer.getVoicePitch());
                    }
                    if (this.whisperer.summonTick == 20){
                        int x = (int) (this.whisperer.getHorizontalLeftLookAngle().x * 4);
                        int z = (int) (this.whisperer.getHorizontalLeftLookAngle().z * 4);
                        BlockPos left = new BlockPos(this.whisperer.blockPosition().offset(x, 0, z));
                        WandUtil.summonTurret(this.whisperer, BlockFinder.SummonPosition(this.whisperer, left), this.whisperer.getPoison(), target, 0, 0);
                    }
                    if (this.whisperer.summonTick == 50){
                        int x = (int) (this.whisperer.getHorizontalRightLookAngle().x * 4);
                        int z = (int) (this.whisperer.getHorizontalRightLookAngle().z * 4);
                        BlockPos right = new BlockPos(this.whisperer.blockPosition().offset(x, 0, z));
                        WandUtil.summonTurret(this.whisperer, BlockFinder.SummonPosition(this.whisperer, right), this.whisperer.getPoison(), target, 0, 0);
                    }
                    cooldown = (int) (spellTime + MathHelper.secondsToTicks(1.4F));
                } else if (this.type == 3){
                    spellTime = 74;
                    if (this.whisperer.getCurrentAnimation() != this.whisperer.getAnimationState(SUMMON_THORNS)){
                        this.whisperer.setAnimationState(SUMMON_THORNS);
                        this.whisperer.playSound(ModSounds.WHISPERER_CAST_THORNS.get(), this.whisperer.getSoundVolume(), this.whisperer.getVoicePitch());
                    }
                    if (this.whisperer.summonTick == 44){
                        this.whisperer.playSound(this.whisperer.getSummonThornsSound(), this.whisperer.getSoundVolume(), this.whisperer.getVoicePitch());
                    }
                    if (this.whisperer.summonTick == 46){
                        EntangleVines entangleVines = new EntangleVines(this.whisperer.level, this.whisperer, this.target);
                        entangleVines.setDamaging(CuriosFinder.hasWildRobe(this.whisperer.getTrueOwner()));
                        this.whisperer.level.addFreshEntity(entangleVines);
                    }
                    cooldown = (int) (spellTime + MathHelper.secondsToTicks(0.1F));
                }
                if (this.type < 1 || (spellTime > 0 && this.whisperer.summonTick >= spellTime)){
                    this.whisperer.setSummoning(false);
                    this.whisperer.summonTick = 0;
                    this.whisperer.summonCool = cooldown;
                }
            }
        }
    } else {
        this.whisperer.setSummoning(false);
        this.whisperer.summonTick = 0;
    }
}

protected void onHitEntity(EntityHitResult p_36757_) {
    Entity entity = p_36757_.getEntity();
    double baseDamage = this.getBaseDamage();
    this.hitEnemy = true;
    if (!this.level.isClientSide) {
        this.level.broadcastEntityEvent(this, (byte) 4);
    }
    if (this.getPierceLevel() > 0) {
        if (this.piercingIgnoreEntityIds == null) {
            this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
        }

        if (this.piercedAndKilledEntities == null) {
            this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
        }

        if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
            this.discard();
            return;
        }

        this.piercingIgnoreEntityIds.add(entity.getId());
    }

    if (this.isCritArrow()) {
        long j = this.random.nextInt(Mth.floor(baseDamage) / 2 + 2);
        baseDamage = (int)Math.min(j + (long)baseDamage, 2147483647L);
    }

    Entity entity1 = this.getOwner();
    DamageSource damagesource;
    if (entity1 == null) {
        damagesource = this.damageSources().arrow(this, this);
    } else {
        damagesource = this.damageSources().arrow(this, entity1);
        if (entity1 instanceof LivingEntity) {
            ((LivingEntity)entity1).setLastHurtMob(entity);
        }
    }

    boolean flag = entity.getType() == EntityType.ENDERMAN;
    int k = entity.getRemainingFireTicks();
    if (this.isOnFire() && !flag) {
        entity.setSecondsOnFire(5);
    }

    if (entity.hurt(damagesource, (float)baseDamage)) {
        if (flag) {
            return;
        }

        if (entity instanceof LivingEntity livingentity) {
            if (!this.level.isClientSide && this.getPierceLevel() <= 0) {
                livingentity.setArrowCount(livingentity.getArrowCount() + 1);
            }

            if (this.getKnockback() > 0) {
                double d0 = Math.max(0.0D, 1.0D - livingentity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
                Vec3 vec3 = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double)this.getKnockback() * 0.6D * d0);
                if (vec3.lengthSqr() > 0.0D) {
                    livingentity.push(vec3.x, 0.1D, vec3.z);
                }
            }

            if (!this.level.isClientSide && entity1 instanceof LivingEntity) {
                EnchantmentHelper.doPostHurtEffects(livingentity, entity1);
                EnchantmentHelper.doPostDamageEffects((LivingEntity)entity1, livingentity);
            }

            this.doPostHurtEffects(livingentity);
            if (livingentity != entity1 && livingentity instanceof Player && entity1 instanceof ServerPlayer && !this.isSilent()) {
                ((ServerPlayer)entity1).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
            }

            if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                this.piercedAndKilledEntities.add(livingentity);
            }

            if (!this.level.isClientSide && entity1 instanceof ServerPlayer serverplayer) {
                if (this.piercedAndKilledEntities != null && this.shotFromCrossbow()) {
                    CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayer, this.piercedAndKilledEntities);
                } else if (!entity.isAlive() && this.shotFromCrossbow()) {
                    CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayer, Arrays.asList(entity));
                }
            }
        }

        this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
        if (this.getPierceLevel() <= 0) {
            this.discard();
        }
    } else {
        entity.setRemainingFireTicks(k);
        this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
        this.setYRot(this.getYRot() + 180.0F);
        this.yRotO += 180.0F;
        if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
            if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                this.spawnAtLocation(this.getPickupItem(), 0.1F);
            }

            this.discard();
        }
    }

}

public static boolean onDamageSourceBlocking(LivingEntity blocker, ItemStack useItem, DamageSource source,
											 CallbackInfoReturnable<Boolean> info) {
	if (blocker instanceof Player player && useItem != null) {
		boolean blocking = ((IProperShieldUser)blocker).isActuallyReallyBlocking();

		if (!blocking)
			return false;

		if (useItem.getItem() instanceof InfernalShield) {
			boolean piercingArrow = false;
			Entity entity = source.getDirectEntity();

			if (entity instanceof AbstractArrow arrow) {
				if (arrow.getPierceLevel() > 0) {
					piercingArrow = true;
				}
			}

			piercingArrow = false; // defend against Piercing... for now

			if (!source.is(DamageTypeTags.BYPASSES_SHIELD) && !piercingArrow) {
				Vec3 sourcePos = source.getSourcePosition();

				if (sourcePos != null) {
					Vec3 lookVec = blocker.getViewVector(1.0F);
					Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
					sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

					if (sourceToSelf.dot(lookVec) < 0.0D) {
						int strength = -1;

						if (player.hasEffect(EnigmaticEffects.BLAZING_STRENGTH)) {
							MobEffectInstance effectInstance = player.getEffect(EnigmaticEffects.BLAZING_STRENGTH);
							strength = effectInstance.getAmplifier();
							player.removeEffect(EnigmaticEffects.BLAZING_STRENGTH);
							strength = strength > 2 ? 2 : strength;
						}

						player.addEffect(new MobEffectInstance(EnigmaticEffects.BLAZING_STRENGTH, 1200, strength + 1, true, true));

						if (source.getDirectEntity() instanceof LivingEntity living && living.isAlive()) {
							if (!living.fireImmune() && !(living instanceof Guardian)) {
								StackTraceElement[] stacktrace = Thread.currentThread().getStackTrace();

								// Ensure that we will not be caught in any sort of StackOverflow because of thorns-like effects
								if (Arrays.stream(stacktrace).filter(element -> {
									return SuperpositionHandler.class.getName().equals(element.getClassName());
								}).count() < 2) {
									living.invulnerableTime = 0;
									living.hurt(living.damageSources().source(DamageTypes.ON_FIRE, player), 4F);
									living.setSecondsOnFire(4);
									EnigmaticEventHandler.KNOCKBACK_THAT_BASTARD.remove(living);
								}
							}
						}

						return true;
					}
				}
			}
		} else if (useItem.getItem() instanceof EldritchPan) {
			Entity projectile = source.getDirectEntity();

			if (!(projectile instanceof Projectile))
				return false;

			if (!source.is(DamageTypeTags.BYPASSES_SHIELD)) {
				Vec3 sourcePos = source.getSourcePosition();

				if (sourcePos != null) {
					Vec3 lookVec = blocker.getViewVector(1.0F);
					Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
					sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

					if (sourceToSelf.dot(lookVec) < 0.0D) {
						projectile.kill();

						FoodData data = player.getFoodData();
						data.eat(4, 0.5F);

						player.level().playSound(null, player.getX(), player.getY(), player.getZ(),
								SoundEvents.PLAYER_BURP, SoundSource.PLAYERS, 0.5F,
								player.level().random.nextFloat() * 0.1F + 0.9F);

						player.gameEvent(GameEvent.EAT);

						if (projectile instanceof LargeFireball fireball) {
							fireball.explosionPower = 0;
						}

						if (player.level() instanceof ServerLevel level) {
							Vec3 angle = player.getLookAngle();
							angle.multiply(1, 0, 1).normalize().multiply(0.5, 0.5, 0.5);

							level.sendParticles(new ItemParticleOption(ParticleTypes.ITEM,
									new ItemStack(Items.FIRE_CHARGE)), player.getX() + angle.x,
									player.getY() + player.getEyeHeight() - 0.1, player.getZ() + angle.z,
									10, 0.3D, 0.3D, 0.3D, 0.03D);
						}

						return true;
					}
				}
			}
		}
	}

	return false;
}

public boolean possess(EntityPlayer possessor, EntityLiving target, int duration){

	if(possessor.isSneaking()) return false;

	if(WizardData.get(possessor) != null){

		WizardData.get(possessor).setVariable(POSSESSEE_KEY, target);
		WizardData.get(possessor).setVariable(TIMER_KEY, duration);

		possessor.setPositionAndRotation(target.posX, target.posY, target.posZ, target.rotationYaw, target.rotationPitch);
		possessor.eyeHeight = target.getEyeHeight();
		setSize(possessor, target.width, target.height);

		target.dismountRidingEntity();
		target.setDead();
		target.setNoAI(true);
		target.setAttackTarget(null);
		target.getEntityData().setBoolean(NBT_KEY, true);

		// Attributes

		if(target instanceof EntityFlying || target instanceof net.minecraft.entity.passive.EntityFlying){
			possessor.capabilities.allowFlying = true;
			possessor.capabilities.isFlying = true;
		}

		// Apply attribute modifiers which change the player's attribute value to the target's value
		// Uses predefined UUIDs so we can easily remove them later
		attributes:
		for(IAttribute attribute : INHERITED_ATTRIBUTES.keySet()){

			IAttributeInstance instance = target.getAttributeMap().getAttributeInstance(attribute);

			if(instance != null){

				double targetValue = instance.getAttributeValue();
				double currentValue = possessor.getAttributeMap().getAttributeInstance(attribute).getAttributeValue();
				// Don't ask me why, but the player's base movement speed seems to be 0.1
				if(attribute == SharedMonsterAttributes.MOVEMENT_SPEED) currentValue /= possessor.capabilities.getWalkSpeed();

				for(EntityEquipmentSlot slot : EntityEquipmentSlot.values()){
					if(target.getItemStackFromSlot(slot).getAttributeModifiers(slot).containsKey(attribute.getName())){
						// If the mob has equipment, use the modifiers for that equipment instead of the mob's normal ones
						// Not doing this results in the player being able to one-hit most mobs when possessing a zombie pigman!
						continue attributes;
					}
				}

				possessor.getAttributeMap().getAttributeInstance(attribute).applyModifier(new AttributeModifier(
						INHERITED_ATTRIBUTES.get(attribute), "possessionModifier", targetValue / currentValue,
						EntityUtils.Operations.MULTIPLY_FLAT));
			}
		}

		if(possessor.world.isRemote){
			// Shaders and effects
			Wizardry.proxy.loadShader(possessor, SHADER);
			Wizardry.proxy.playBlinkEffect(possessor);

		}else{

			// Targeting

			for(EntityLiving creature : EntityUtils.getEntitiesWithinRadius(16, possessor.posX,
					possessor.posY, possessor.posZ, possessor.world, EntityLiving.class)){
				// Mobs are dumb, if a player possesses something they're like "Huh?! Where'd you go?"
				// Of course, this won't last long if the player attacks them, since they'll revenge-target them
				if(creature.getAttackTarget() == possessor && !creature.canAttackClass(target.getClass()))
					creature.setAttackTarget(null);
			}

			// Inventory and items

			if(possessor.getEntityData() != null){
				NBTExtras.storeTagSafely(possessor.getEntityData(), INVENTORY_NBT_KEY, possessor.inventory.writeToNBT(new NBTTagList()));
			}

			possessor.inventory.clear();
			possessor.inventoryContainer.detectAndSendChanges();

			ItemStack stack = target.getHeldItemMainhand().copy();

			if(target instanceof EntityEnderman && ((EntityEnderman)target).getHeldBlockState() != null){
				stack = new ItemStack(((EntityEnderman)target).getHeldBlockState().getBlock());

			}else if(stack.getItem() instanceof ItemBow){
				Map<Enchantment, Integer> enchantments = EnchantmentHelper.getEnchantments(stack);
				enchantments.put(Enchantments.INFINITY, 1);
				EnchantmentHelper.setEnchantments(enchantments, stack);
				ItemStack arrow = new ItemStack(Items.ARROW);
				if(target instanceof EntityStray || target instanceof EntityStrayMinion){
					arrow = new ItemStack(Items.TIPPED_ARROW);
					PotionUtils.addPotionToItemStack(arrow, PotionTypes.SLOWNESS);
				}
				possessor.setHeldItem(EnumHand.OFF_HAND, arrow);
			}

			possessor.setItemStackToSlot(EntityEquipmentSlot.MAINHAND, stack);

			// Packets

			WizardryPacketHandler.net.sendToAllTracking(new PacketPossession.Message(possessor, target, duration), possessor);
			if(possessor instanceof EntityPlayerMP){
				WizardryPacketHandler.net.sendTo(new PacketPossession.Message(possessor, target, duration), (EntityPlayerMP)possessor);
			}
		}

		return true;
	}

	return false;
}

public void performRangedAttack(LivingEntity target, float p_34144_) {
    if (!this.isDrinkingPotion()) {
        boolean grief = ForgeEventFactory.getMobGriefingEvent(this.level, this);
        Vec3 vec3 = target.getDeltaMovement();
        double d0 = target.getX() + vec3.x - this.getX();
        double d1 = target.getEyeY() - (double)1.1F - this.getY();
        double d2 = target.getZ() + vec3.z - this.getZ();
        double d3 = Math.sqrt(d0 * d0 + d2 * d2);
        int amp = 0;
        if (this.level.getRandom().nextFloat() <= 0.05F && this.level.getDifficulty() != Difficulty.EASY){
            amp = 2;
        } else if (this.level.getRandom().nextFloat() <= 0.25F){
            amp = 1;
        }
        List<MobEffectInstance> mobEffectInstance = new ArrayList<>();
        List<BrewEffectInstance> brewEffectInstance = new ArrayList<>();
        if (target instanceof Raider raider && this.hasActiveRaid() && raider.getTarget() != this) {
            if (target.getHealth() <= 4.0F) {
                mobEffectInstance.add(new MobEffectInstance(MobEffects.HEAL, 1));
            } else {
                mobEffectInstance.add(new MobEffectInstance(MobEffects.REGENERATION, 900));
                if (this.random.nextFloat() <= 0.05F) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.ABSORPTION, 1800));
                }
            }
            this.setTarget(null);
        } else if (d3 >= 8.0D && !target.hasEffect(MobEffects.MOVEMENT_SLOWDOWN)) {
            mobEffectInstance.add(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 1800 / (amp + 1), amp));
            if (this.random.nextFloat() <= 0.25F && target.onGround() && grief){
                brewEffectInstance.add(new BrewEffectInstance(new SweetBerriedEffect(), 1, amp));
            }
            if (this.random.nextFloat() <= 0.25F && this.noBrewMinions(target) && grief){
                brewEffectInstance.add(new BrewEffectInstance(new WebbedBrewEffect(0, 0), 1, amp));
            } else if (this.random.nextFloat() <= 0.5F){
                if (this.random.nextBoolean()) {
                    brewEffectInstance.add(new BrewEffectInstance(new TransposeBrewEffect()));
                }
            }
        } else if (target.getHealth() >= 8.0F && !target.hasEffect(MobEffects.POISON) && target.canBeAffected(new MobEffectInstance(MobEffects.POISON))) {
            if (!target.hasEffect(MobEffects.POISON) && target.canBeAffected(new MobEffectInstance(MobEffects.POISON))){
                mobEffectInstance.add(new MobEffectInstance(MobEffects.POISON, 900 / (amp + 1), amp));
            }
            if (this.random.nextFloat() <= 0.25F && !this.hasEffect(GoetyEffects.FIERY_AURA.get()) && !target.hasEffect(GoetyEffects.FREEZING.get()) && !target.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES)){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FREEZING.get(), 900 / (amp + 1), amp));
            } else if (this.random.nextFloat() <= 0.25F && !this.hasEffect(GoetyEffects.FROSTY_AURA.get()) && !target.hasEffect(GoetyEffects.FLAMMABLE.get()) && !target.fireImmune() && !target.isInFluidType(ForgeMod.WATER_TYPE.get())){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FLAMMABLE.get(), 900 / (amp + 1), amp));
            } else if (this.random.nextFloat() <= 0.05F && !target.hasEffect(GoetyEffects.TRIPPING.get())){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.TRIPPING.get(), 1800 / (amp + 1), amp));
            }
        } else if (target.hasEffect(MobEffects.REGENERATION) && !target.hasEffect(GoetyEffects.CURSED.get())){
            mobEffectInstance.add(new MobEffectInstance(GoetyEffects.CURSED.get(), 600, 0));
        } else if (this.getLastDamageSource() != null
                && ModDamageSource.physicalAttacks(this.getLastDamageSource())
                && !target.hasEffect(MobEffects.WEAKNESS) && this.random.nextFloat() < 0.25F) {
            mobEffectInstance.add(new MobEffectInstance(MobEffects.WEAKNESS, 1800 / (amp + 1), amp));
            if (this.random.nextFloat() <= 0.25F){
                brewEffectInstance.add(new BrewEffectInstance(new TransposeBrewEffect(), 1, amp));
            } else if (this.random.nextFloat() <= 0.5F
                    && !target.fireImmune()
                    && MobUtil.isInSunlight(target)
                    && !target.hasEffect(MobEffects.FIRE_RESISTANCE)
                    && !target.hasEffect(GoetyEffects.SUN_ALLERGY.get())){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.SUN_ALLERGY.get(), 3600 / (amp + 1), amp));
            } else if (this.random.nextFloat() <= 0.75F
                    && target.level.getMaxLocalRawBrightness(target.blockPosition()) < 2
                    && !target.hasEffect(GoetyEffects.NYCTOPHOBIA.get())){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.NYCTOPHOBIA.get(), 1800 / (amp + 1), amp));
            } else if (!target.hasEffect(GoetyEffects.SAPPED.get())) {
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.SAPPED.get(), 1800 / (amp + 1), amp));
            }
        } else {
            if (this.random.nextFloat() <= 0.05F){
                brewEffectInstance.add(new BrewEffectInstance(new StripBrewEffect(0, 0)));
            } else if (this.random.nextFloat() <= 0.25F && (target.onGround() || (!target.hasEffect(MobEffects.LEVITATION) && !target.hasEffect(GoetyEffects.PLUNGE.get())))){
                if (target.onGround() && grief) {
                    brewEffectInstance.add(new BrewEffectInstance(new ThornTrapBrewEffect(0), 1, amp));
                } else if (!target.hasEffect(MobEffects.LEVITATION) && !target.hasEffect(GoetyEffects.PLUNGE.get())){
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.PLUNGE.get(), 900 / (amp + 1), amp));
                }
            } else if (this.random.nextFloat() <= 0.35F && !target.hasEffect(MobEffects.BLINDNESS) && !MobUtil.isInWeb(target) && target.getMaxHealth() > 10.0F && this.noBrewMinions(target)){
                mobEffectInstance.add(new MobEffectInstance(MobEffects.BLINDNESS, MathHelper.secondsToTicks(5)));
                brewEffectInstance.add(new BrewEffectInstance(new BatsBrewEffect(0, 0)));
            } else if (this.random.nextFloat() <= 0.55F && !MobUtil.isInWeb(target) && !target.hasEffect(MobEffects.LEVITATION)){
                brewEffectInstance.add(new BrewEffectInstance(new LaunchBrewEffect(), 1));
            } else if (this.random.nextFloat() <= 0.75F && !MobUtil.isInWeb(target) && target.getMaxHealth() > 10.0F && this.noBrewMinions(target)){
                brewEffectInstance.add(new BrewEffectInstance(new BeesBrewEffect(0, 0)));
            } else {
                mobEffectInstance.add(new MobEffectInstance(MobEffects.HARM, 1, amp));
            }
        }

        if (!mobEffectInstance.isEmpty() || !brewEffectInstance.isEmpty()) {
            ThrownBrew thrownBrew = new ThrownBrew(this.level, this);
            ItemStack brew0 = this.level.getRandom().nextFloat() <= 0.15F && this.level.getDifficulty() == Difficulty.HARD ? new ItemStack(ModItems.GAS_BREW.get()) : new ItemStack(ModItems.SPLASH_BREW.get());
            ItemStack brew = BrewUtils.setCustomEffects(brew0, mobEffectInstance, brewEffectInstance);
            BrewUtils.setAreaOfEffect(brew, this.level.getRandom().nextInt(amp + 1));
            brew.getOrCreateTag().putInt("CustomPotionColor", BrewUtils.getColor(mobEffectInstance, brewEffectInstance));
            thrownBrew.setItem(brew);
            float velocity = 0.75F;
            if (target.distanceTo(this) >= 4.0F) {
                thrownBrew.setXRot(thrownBrew.getXRot() + 20.0F);
            } else {
                thrownBrew.setXRot(thrownBrew.getXRot());
                velocity = 1.0F;
            }
            thrownBrew.shoot(d0, d1 + d3 * 0.2D, d2, velocity, 8.0F);
            if (!this.isSilent()) {
                this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_THROW, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }

            this.level.addFreshEntity(thrownBrew);
        }
    }
}

public void aiStep() {
    super.aiStep();
    if (!this.isHiding() && !this.isDeadOrDying()) {
        if (this.level.isClientSide) {
            for(int i = 0; i < 2; ++i) {
                this.level.addParticle(ParticleTypes.PORTAL, this.getRandomX(0.5D), this.getRandomY() - 0.25D, this.getRandomZ(0.5D), (this.random.nextDouble() - 0.5D) * 2.0D, -this.random.nextDouble(), (this.random.nextDouble() - 0.5D) * 2.0D);
            }
        }
    }
    if (this.deadlyEscapeCool > 0) {
        if (this.isDeadlyEscape()) {
            this.setDeadlyEscape(false);
        }
        --this.deadlyEscapeCool;
    }
    if (this.recentHitTime > 0) {
        --this.recentHitTime;
    }
    this.idleTick();
    if (!this.level.isClientSide) {
        if (!this.isDeadOrDying()) {
            this.setAggressive(this.getTarget() != null);
            if (this.getEyeType() > 0 && !this.isHiding()) {
                this.eyeTypeEffects();
            }
            if (this.getVoidFrame() instanceof VoidFrameBlockEntity voidFrameBlock) {
                voidFrameBlock.setCoolTick(0);
                if (this.getTarget() == null && this.distanceToSqr(voidFrameBlock.getBlockPos().getCenter()) > Mth.square(48)) {
                    if (this.tickCount % 10 == 0) {
                        Vec3 vec3 = voidFrameBlock.getBlockPos().getCenter();
                        this.getNavigation().stop();
                        this.teleportTo(vec3.x, vec3.y + 1, vec3.z);
                    }
                }
            }
            if (this.isMeleeAttacking()) {
                ++this.attackTick;
            } else if (this.isAttacking()) {
                if (this.isDeadlyEscape()) {
                    this.setAnimationState(DEADLY_ESCAPE);
                } else {
                    this.setAnimationState(IDLE);
                }
            }
            if (this.isCurrentAnimation(TELEPORT_IN)) {
                if (this.postTeleportTick <= 0) {
                    this.setAnimationState(IDLE);
                } else if (this.postTeleportTick == (MathHelper.secondsToTicks(1.92F - 0.44F))) {
                    this.frontSmash();
                }
            }
            AttributeInstance instance = this.getAttribute(Attributes.ATTACK_DAMAGE);
            if (instance != null) {
                if (this.isCurrentAnimation(TELEPORT_IN)) {
                    if (this.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                        instance.removeModifier(TELEPORT_ATTACK_MODIFIER);
                        instance.addTransientModifier(TELEPORT_ATTACK_MODIFIER);
                    }
                } else {
                    if (instance.hasModifier(TELEPORT_ATTACK_MODIFIER)) {
                        instance.removeModifier(TELEPORT_ATTACK_MODIFIER);
                    }
                }
                if (this.isCurrentAnimation(DEADLY_ESCAPE)) {
                    if (this.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                        instance.removeModifier(DE_ATTACK_MODIFIER);
                        instance.addTransientModifier(DE_ATTACK_MODIFIER);
                    }
                } else {
                    if (instance.hasModifier(DE_ATTACK_MODIFIER)) {
                        instance.removeModifier(DE_ATTACK_MODIFIER);
                    }
                }
            }
            if (!this.isHiding()) {
                if (this.getTarget() != null) {
                    if (!this.isTeleporting()
                            && !this.isDeadlyEscape()
                            && this.postTeleportTick <= 0) {
                        if (this.getTarget().distanceTo(this) <= 8.0F
                                && this.level.getRandom().nextBoolean()
                                && this.recentHitTime > 0
                                && this.deadlyEscapeCool <= 0
                                && this.watchlingNumber() < 3) {
                            if (!this.isMeleeAttacking()
                                    && !this.isAttacking()) {
                                this.setAnimationState(DEADLY_ESCAPE);
                            }
                            this.setDeadlyEscape(true);
                        } else if (!this.isWithinMeleeAttackRange(this.getTarget())
                                && !this.isMeleeAttacking()
                                && !this.isAttacking()
                                && this.recentHitTime > 0
                                && this.level.getRandom().nextBoolean()
                                && this.teleportCool <= 0) {
                            this.savedTeleportTarget = this.getTarget();
                            this.teleportHideTime = MathHelper.secondsToTicks(this.level.getRandom().nextIntBetweenInclusive(3, 5));
                            this.setTeleporting(true);
                            this.setAnimationState(TELEPORT_OUT);
                        }
                    }
                }
                if (this.isDeadlyEscape() && this.isCurrentAnimation(DEADLY_ESCAPE)) {
                    this.setTeleporting(false);
                    this.deadlyEscape();
                    this.savedTeleportTarget = null;
                } else if (this.isTeleporting()) {
                    this.setDeadlyEscape(false);
                    this.specialTeleport();
                }
            }
        }
    }
}

public void aiStep() {
    if (!this.level.isClientSide && this.isAlive()) {
        if (this.lastHitTime > 0){
            --this.lastHitTime;
        } else if (this.hitTimes > 0) {
            this.hitTimes = 0;
        }
        if (this.toHealTime > 0) {
            --this.toHealTime;
        }
        if (this.overwhelmed > 0) {
            --this.overwhelmed;
        }
        this.healRaidersGoal.decrementCooldown();
        this.attackPlayersGoal.setCanAttack(this.healRaidersGoal.getCooldown() <= 0);

        if (this.isDrinkingPotion()) {
            if (this.usingTime-- <= 0) {
                this.setUsingItem(false);
                ItemStack itemstack = this.getMainHandItem();
                this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                if (itemstack.is(ModItems.BREW.get())) {
                    List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                    for (MobEffectInstance mobeffectinstance : list) {
                        this.addEffect(new MobEffectInstance(mobeffectinstance));
                    }
                    List<BrewEffectInstance> list1 = BrewUtils.getBrewEffects(itemstack);
                    for (BrewEffectInstance brewEffectInstance : list1) {
                        brewEffectInstance.getEffect().drinkBlockEffect(this, this, this, brewEffectInstance.getAmplifier(), BrewUtils.getAreaOfEffect(itemstack));
                    }
                }

                this.getAttribute(Attributes.MOVEMENT_SPEED).removeModifier(SPEED_MODIFIER_DRINKING);
            }
        } else {
            int amp = 0;
            if (this.level.getRandom().nextFloat() <= 0.05F && this.level.getDifficulty() == Difficulty.NORMAL){
                amp = 2;
            } else if (this.level.getRandom().nextFloat() <= 0.25F){
                amp = 1;
            }
            List<MobEffectInstance> mobEffectInstance = new ArrayList<>();
            List<BrewEffectInstance> brewEffectInstance = new ArrayList<>();
            if (this.random.nextFloat() < 0.15F && (this.isInWall() || (this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypes.IN_WALL)))){
                brewEffectInstance.add(new BrewEffectInstance(new BlindJumpBrewEffect(0), 1, amp));
            } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && (this.getLastDamageSource().is(DamageTypes.CACTUS) || this.getLastDamageSource().is(DamageTypes.SWEET_BERRY_BUSH))){
                brewEffectInstance.add(new BrewEffectInstance(new HarvestBlockEffect()));
            } else if (this.random.nextFloat() < 0.15F && this.getHealth() < this.getMaxHealth() && (this.getTarget() == null || this.toHealTime == 0)) {
                mobEffectInstance.add(new MobEffectInstance(MobEffects.HEAL, 1, amp));
            } else if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                mobEffectInstance.add(new MobEffectInstance(MobEffects.WATER_BREATHING, 3600));
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.SWIFT_SWIM.get(), 3600));
            } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                mobEffectInstance.add(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 3600));
            } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FALL) && !this.hasEffect(MobEffects.SLOW_FALLING)){
                mobEffectInstance.add(new MobEffectInstance(MobEffects.SLOW_FALLING, 3600));
            } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && ModDamageSource.physicalAttacks(this.getLastDamageSource()) && !this.hasEffect(GoetyEffects.REPULSIVE.get())){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.REPULSIVE.get(), 1800 / (amp + 1), amp));
            } else if (this.random.nextFloat() < 0.15F && this.getTarget() != null) {
                if ((this.random.nextFloat() <= 0.15F && this.getTarget().distanceTo(this) <= 4.0F)){
                    brewEffectInstance.add(new BrewEffectInstance(new BlindJumpBrewEffect(0), 1, amp));
                } else if (this.random.nextFloat() <= 0.15F && !this.hasEffect(MobEffects.REGENERATION)){
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.REGENERATION, 900 / (amp + 1), amp));
                    if (this.random.nextFloat() < 0.25F && MobUtil.isInSunlight(this) && !this.hasEffect(GoetyEffects.PHOTOSYNTHESIS.get())){
                        mobEffectInstance.add(new MobEffectInstance(GoetyEffects.PHOTOSYNTHESIS.get(), 1800));
                    }
                } else if (this.random.nextFloat() < 0.05F && !this.hasEffect(MobEffects.DAMAGE_RESISTANCE)){
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1800));
                } else if (this.random.nextFloat() < 0.05F && !this.hasEffect(GoetyEffects.FROSTY_AURA.get()) && !this.hasEffect(GoetyEffects.FIERY_AURA.get())) {
                    if (this.random.nextBoolean()) {
                        if (!this.getTarget().hasEffect(GoetyEffects.FREEZING.get()) && !this.getTarget().hasEffect(MobEffects.FIRE_RESISTANCE) && !this.getTarget().fireImmune()) {
                            mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FIERY_AURA.get(), 1800 / (amp + 1), amp));
                        }
                    } else {
                        if (!this.getTarget().isOnFire() && this.getTarget().canFreeze()){
                            mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FROSTY_AURA.get(), 1800 / (amp + 1), amp));
                        }
                    }
                }
            } else if (this.random.nextFloat() <= 0.15F && MobUtil.isInWeb(this) && !this.hasEffect(GoetyEffects.CLIMBING.get())){
                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.CLIMBING.get(), 3600));
            } else if (this.random.nextFloat() < 0.05F && MobUtil.hasLongNegativeEffects(this)) {
                brewEffectInstance.add(new BrewEffectInstance(new PurifyBrewEffect("purify_debuff", 0, 0, MobEffectCategory.BENEFICIAL, 0x385858, true)));
            }

            if (!mobEffectInstance.isEmpty() || !brewEffectInstance.isEmpty()) {
                ItemStack brew = BrewUtils.setCustomEffects(new ItemStack(ModItems.BREW.get()), mobEffectInstance, brewEffectInstance);
                BrewUtils.setAreaOfEffect(brew, this.level.getRandom().nextInt(amp + 1));
                brew.getOrCreateTag().putInt("CustomPotionColor", BrewUtils.getColor(mobEffectInstance, brewEffectInstance));
                this.setItemSlot(EquipmentSlot.MAINHAND, brew);
                this.usingTime = this.overwhelmed > 0 ? this.getMainHandItem().getUseDuration() / 2 : this.getMainHandItem().getUseDuration();
                this.setUsingItem(true);
                if (!this.isSilent()) {
                    this.level.playSound((Player)null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_DRINK, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                }

                AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
                attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
            } else if (this.getMainHandItem().getItem() instanceof BrewItem){
                this.usingTime = this.overwhelmed > 0 ? this.getMainHandItem().getUseDuration() / 2 : this.getMainHandItem().getUseDuration();
                this.setUsingItem(true);
                AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
                attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
            }
        }

        if (this.random.nextFloat() < 7.5E-4F) {
            this.level.broadcastEntityEvent(this, (byte)15);
        }
    }

    super.aiStep();
}

public void aiStep() {
    this.jumping = false;
    MiscCapHelper.updateMobTarget(this);
    if (!this.level.isClientSide) {
        if (!this.isDeadOrDying()) {
            this.setAggressive(this.getTarget() != null);
            if (!this.isMeleeAttacking() && !this.isScreaming()) {
                this.setAnimationState(IDLE);
            }
            if (this.isMeleeAttacking()) {
                ++this.attackTick;
            }
            if (this.getTarget() != null){
                this.breakBlocksAround();
            }
            if (MobUtil.healthIsHalved(this) && this.level.getDifficulty() == Difficulty.HARD) {
                if (!this.attackFast) {
                    this.attackFast = true;
                    this.level.broadcastEntityEvent(this, (byte) 10);
                }
            } else {
                if (this.attackFast) {
                    this.attackFast = false;
                    this.level.broadcastEntityEvent(this, (byte) 11);
                }
            }
            if (this.level instanceof ServerLevel serverLevel) {
                Vec3 vec3 = this.getDeltaMovement();
                if (this.isInWater()) {
                    if (this.getTarget() != null) {
                        if (this.getTarget().getY() > this.getY() + 2) {
                            this.setDeltaMovement(vec3.x(), Math.min(0.3D, vec3.y() + 0.05D), vec3.z());
                        } else if (this.getTarget().getY() < this.getY() - 2) {
                            this.setDeltaMovement(vec3.x(), Math.max(-0.3D, vec3.y() - 0.05D), vec3.z());
                        }
                    } else if (this.isUnderWater()) {
                        this.setDeltaMovement(vec3.x(), 0.15D, vec3.z());
                    }
                    if (this.getNavigation().isDone()) {
                        this.setDeltaMovement(vec3.x() * 0.8D, vec3.y(), vec3.z() * 0.8D);
                    }
                }

                this.climb(serverLevel);
                this.updatePersistentAnger(serverLevel, true);
                if (!this.isHiding()) {
                    this.hidingTime = 0;
                    if (this.regenHeal > 0){
                        if (this.tickCount % 10 == 0){
                            --this.regenHeal;
                            if (!this.isOnFire()) {
                                this.heal(1.0F);
                                Vec3 vector3d = this.getDeltaMovement();
                                serverLevel.sendParticles(ParticleTypes.SCULK_SOUL, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0, vector3d.x * -0.2D, 0.1D, vector3d.z * -0.2D, 0.5F);
                            }
                        }
                    }
                    for (int i = 0; i < 2; ++i) {
                        serverLevel.sendParticles(ParticleTypes.SMOKE, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0, 0.0D, 0.0D, 0.0D, 0.5F);
                    }
                } else {
                    ++this.hidingTime;
                    if (this.hidingTime >= MathHelper.secondsToTicks(5)) {
                        this.setHide(false);
                        this.level.broadcastEntityEvent(this, (byte) 5);
                        this.hidingCooldown = MathHelper.secondsToTicks(this.level.random.nextInt(5) + 5);
                        if (this.getTarget() != null) {
                            this.teleportNearTo(this.getTarget());
                            this.teleportHit(serverLevel);
                        } else {
                            this.teleport();
                            this.teleportHit(serverLevel);
                        }
                    }
                }
            }
            if (this.isScreaming()){
                if (this.getTarget() != null) {
                    MobUtil.instaLook(this, this.getTarget());
                }
                this.getNavigation().stop();
                ++this.screamTick;
                int total = this.isSummoning() ? 30 : 4;
                if (this.screamTick >= total){
                    for (int i = 0; i < 64; ++i){
                        if (this.teleport()){
                            this.setScreaming(false);
                            this.setSummoning(false);
                            this.level.broadcastEntityEvent(this, (byte) 9);
                            break;
                        }
                    }
                }
            }
            if (this.hidingCooldown > 0) {
                --this.hidingCooldown;
            }
            if (this.spawnCool > 0 && !this.isHiding()){
                --this.spawnCool;
            }
            if (this.teleportCool > 0){
                --this.teleportCool;
            }
            if (this.isHallucination()){
                if (this.getTrueOwner() != null){
                    if (this.getTrueOwner().isDeadOrDying()){
                        this.hallucinateVanish();
                    }
                }
            }
        }
    }

    if (this.isHiding() || this.isScreaming()){
        this.jumping = false;
        this.xxa = 0.0F;
        this.zza = 0.0F;
        this.move(MoverType.SELF, new Vec3(0.0D, 0.0D, 0.0D));
    }

    super.aiStep();
}

public void tick() {
    super.tick();
    if (!this.isActivated()){
        int count = SpellConfig.RuptureDuration.get() / 3;
        if (this.tickCount % count == 0) {
            if (this.level.isClientSide) {
                if (this.getAnimation() < 2) {
                    this.setAnimation(this.getAnimation() + 1);
                }
            }
            this.playSound(ModSounds.RUMBLE.get(), 2.0F, this.random.nextFloat() + 0.75F);
        }
    } else {
        if (this.level.isClientSide) {
            if (this.tickCount % 20 == 0) {
                if (this.isClosing) {
                    if (this.getAnimation() > 0) {
                        this.setAnimation(this.getAnimation() - 1);
                    }
                } else {
                    if (this.getAnimation() < 7) {
                        this.setAnimation(this.getAnimation() + 1);
                    } else {
                        this.setAnimation(3);
                    }
                }
            }
        }
    }
    if (!this.level.isClientSide) {
        if (this.warmUp <= 0) {
            if (!this.isActivated()) {
                this.setActivated(true);
                this.level.broadcastEntityEvent(this, (byte) 100);
            }
            if (!this.playEvent) {
                this.playSound(ModSounds.VOID_RIFT_OPEN.get(), 5.0F, 1.0F);
                ModNetwork.sendToALL(new SPlayLoopSoundPacket(this, ModSounds.VOID_RIFT.get(), 5.0F, 1.0F));
                this.playEvent = true;
            }
            if (this.tickCount % 200 == 0){
                this.playSound(SoundEvents.PORTAL_AMBIENT, 5.0F, 0.75F);
            }
            List<Entity> targets = new ArrayList<>();
            float range = 16.0F * (this.getSize() + 1.0F);
            /*if (!this.isClosing) {
                int rangeInt = Mth.floor(range);
                this.suckBlocks(rangeInt, rangeInt, rangeInt);
            }*/
            if (this.level instanceof ServerLevel serverWorld) {
                ServerParticleUtil.gatheringParticles(ParticleTypes.PORTAL, this, serverWorld, (int)range);
            }
            for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(range))) {
                if (!(entity instanceof Endermite)) {
                    if (entity instanceof ModFallingBlock modFallingBlock && modFallingBlock.getMode() == ModFallingBlock.FallingBlockMode.DEBRIS){
                        targets.add(entity);
                        if (entity.distanceTo(this) <= 1.0F){
                            entity.discard();
                        }
                    }
                    if (this.getOwner() != null) {
                        if (!MobUtil.areAllies(this.getOwner(), entity) && MobUtil.getOwner(entity) != this.getOwner()) {
                            targets.add(entity);
                        }
                    } else {
                        targets.add(entity);
                    }
                }
            }
            if (!targets.isEmpty()) {
                for (Entity entity : targets) {
                    double distance = 1.0D - (entity.distanceTo(this) / range);
                    double scale = distance * 0.25D;
                    Vec3 vec3 = entity.position().subtract(this.position());
                    vec3 = vec3.normalize().scale(scale);
                    MobUtil.pull(entity, vec3.x, vec3.y, vec3.z, 0.5D);
                    if (entity.distanceTo(this) <= this.getBoundingBox().getSize()){
                        if (entity instanceof LivingEntity livingEntity) {
                            float damage = SpellConfig.RuptureDamage.get().floatValue() * WandUtil.damageMultiply();
                            if (this.getOwner() != null) {
                                if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                                    damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F;
                                }
                            }
                            damage += this.getExtraDamage();
                            livingEntity.hurt(this.damageSources().indirectMagic(this, this.getOwner()), damage);
                        }
                    }
                }
            }
        } else {
            if (this.level instanceof ServerLevel serverWorld) {
                double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                double d2 = this.getY() + 0.5F;
                double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                serverWorld.sendParticles(ParticleTypes.PORTAL, d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
            }
            if (this.getOwner() != null && this.getOwner().isDeadOrDying()) {
                this.discard();
            }
            --this.warmUp;
        }
        if (this.tickCount >= this.getDuration()) {
            if (!this.isClosing){
                this.isClosing = true;
                this.level.broadcastEntityEvent(this, (byte) 101);
            }
            if (this.tickCount >= this.getDuration() + 20) {
                if (this.level instanceof ServerLevel serverLevel) {
                    ColorUtil colorUtil = new ColorUtil(0x7317d2);
                    float range = 8.0F * (this.getSize() + 1.0F);
                    serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, range, 0, true), this.getX(), this.getY() + 0.5D, this.getZ(), 0, 0, 0, 0, 0);
                    ServerParticleUtil.createParticleBall(ParticleTypes.DRAGON_BREATH, this.getX(), this.getY() + 0.5D, this.getZ(), serverLevel,  8 + (int) this.getSize());
                    this.playSound(SoundEvents.RESPAWN_ANCHOR_DEPLETE.get(), 5.0F, 0.5F);
                    this.playSound(SoundEvents.GENERIC_EXPLODE, 5.0F, 0.5F);
                    new SpellExplosion(this.level, this.getOwner() != null ? this.getOwner() : this, this.damageSources().indirectMagic(this, this.getOwner()), this.blockPosition(), range / 4, 0.0F) {
                        @Override
                        public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                            super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                            if (VoidRift.this.isStaff()) {
                                if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target)) {
                                    if (target instanceof LivingEntity livingEntity) {
                                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(5), 2, false, true));
                                    }
                                }
                            }
                        }
                    };
                }
                this.discard();
            }
        }
    }
}

