public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand, BlockHitResult pHit) {
    if (pLevel.getBlockEntity(pPos) instanceof BrewCauldronBlockEntity cauldron) {
        ItemStack stack = pPlayer.getItemInHand(pHand);
        boolean bucket = ItemHelper.isValidFluidContainerToFill(stack, Fluids.WATER), waterBucket = ItemHelper.isValidFluidContainerToDrain(stack, Fluids.WATER), glassBottle = stack.getItem() == Items.GLASS_BOTTLE, waterBottle = (stack.getItem() == Items.POTION || stack.getItem() == ModItems.BREW.get()) && PotionUtils.getPotion(stack) == Potions.WATER, apple = BrewUtils.brewableFood(stack), waystone = stack.getItem() instanceof WaystoneItem, ladle = stack.getItem() == ModItems.CAULDRON_LADLE.get();
        boolean taglock = stack.getItem() instanceof TaglockKit && TaglockKit.hasEntity(stack);
        boolean playSound = false;
        if (!pLevel.isClientSide) {
            int targetLevel = cauldron.getTargetLevel(stack, pPlayer);
            if (cauldron.mode == BrewCauldronBlockEntity.Mode.CRAFTED) {
                if (targetLevel > -1) {
                    Ingredient takeWith = cauldron.getRecipe().getTakeWith();
                    ItemStack bottle = null;
                    boolean flag = stack.isEmpty();
                    if (!takeWith.isEmpty()) {
                        flag = takeWith.test(stack);
                    }
                    if (flag) {
                        if (stack.is(Items.GLASS_BOTTLE)) {
                            SEHelper.increaseBottling(pPlayer);
                        }
                        bottle = cauldron.getCraftedItem();
                    }
                    if (bottle != null) {
                        ItemHelper.addAndConsumeItem(pPlayer, pHand, bottle);
                        playSound = true;
                    }
                    if (targetLevel == 0) {
                        cauldron.mode = cauldron.reset();
                    }
                }
            } else if (bucket || waterBucket || apple || taglock || glassBottle || waterBottle || waystone || ladle) {
                if (targetLevel > -1) {
                    if (bucket) {
                        ItemHelper.addAndConsumeItem(pPlayer, pHand, ItemHelper.fill(Fluids.WATER, stack.copyWithCount(1)), false);
                        playSound = true;
                    } else if (waterBucket) {
                        ItemHelper.addAndConsumeItem(pPlayer, pHand, ItemHelper.drain(Fluids.WATER, stack.copyWithCount(1)), false);
                        playSound = true;
                    } else if (apple){
                        if (cauldron.mode == BrewCauldronBlockEntity.Mode.COMPLETED) {
                            ItemStack itemStack = BrewUtils.setCustomEffects(stack.copyWithCount(1), PotionUtils.getCustomEffects(cauldron.getBrew()), BrewUtils.getBrewEffects(cauldron.getBrew()));
                            ItemHelper.addAndConsumeItem(pPlayer, pHand, itemStack);
                            SEHelper.increaseBottling(pPlayer);
                            playSound = true;
                        }
                    } else if (taglock && pState.getValue(LEVEL) >= 3){
                        if (cauldron.mode == BrewCauldronBlockEntity.Mode.COMPLETED) {
                            LivingEntity target = TaglockKit.getEntity(stack);
                            if (target != null){
                                if (TaglockKit.isSameDimension(pPlayer, stack) && (TaglockKit.isInRange(Vec3.atCenterOf(pPos), stack, BrewCauldronBlockEntity.getWitchPoles(cauldron))) || BrewCauldronBlockEntity.getWitchPoles(cauldron) >= 3) {
                                    List<MobEffectInstance> list = PotionUtils.getMobEffects(cauldron.getBrew());
                                    List<BrewEffectInstance> list1 = BrewUtils.getBrewEffects(cauldron.getBrew());
                                    if (!list.isEmpty()) {
                                        for (MobEffectInstance mobeffectinstance : list) {
                                            MobEffect mobeffect = mobeffectinstance.getEffect();
                                            if (mobeffect.isInstantenous()) {
                                                mobeffect.applyInstantenousEffect(pPlayer, pPlayer, target, mobeffectinstance.getAmplifier(), 1.0F);
                                            } else {
                                                int i = (int) (1.0F * (double) mobeffectinstance.getDuration() + 0.5D);
                                                if (i > 20) {
                                                    target.addEffect(new MobEffectInstance(mobeffect, i, mobeffectinstance.getAmplifier(), mobeffectinstance.isAmbient(), mobeffectinstance.isVisible()), pPlayer);
                                                }
                                            }
                                        }
                                    }
                                    if (!list1.isEmpty()) {
                                        for (BrewEffectInstance brewEffectInstance : list1) {
                                            BrewEffect brewEffect = brewEffectInstance.getEffect();
                                            if (brewEffect.isInstantenous()) {
                                                brewEffect.applyInstantenousEffect(pPlayer, pPlayer, target, brewEffectInstance.getAmplifier(), 1.0F);
                                            }
                                        }
                                    }
                                    pLevel.playSound(null, pPos, ModSounds.CAST_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    ItemHelper.addAndConsumeItem(pPlayer, pHand, new ItemStack(Items.GLASS_BOTTLE));
                                    SEHelper.increaseBottling(pPlayer, 5);
                                    playSound = true;
                                } else {
                                    pLevel.playSound(null, pPos, ModSounds.SPELL_FAIL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    pPlayer.displayClientMessage(Component.translatable("info.goety.taglock.difDimension"), true);
                                }
                            }
                        }
                    } else if (waystone && pState.getValue(LEVEL) >= 3 && cauldron.getBrew().getItem() instanceof ThrowableBrewItem){
                        if (cauldron.mode == BrewCauldronBlockEntity.Mode.COMPLETED) {
                            GlobalPos globalPos = WaystoneItem.getPosition(stack);
                            if (globalPos != null){
                                if (globalPos.dimension() == pLevel.dimension()
                                        && (WaystoneItem.isInRange(Vec3.atCenterOf(pPos), stack, BrewCauldronBlockEntity.getWitchPoles(cauldron))) || BrewCauldronBlockEntity.getWitchPoles(cauldron) >= 3) {
                                    BrewUtils.onHit(pPlayer, cauldron.getBrew(), null, globalPos.pos(), WaystoneItem.getDirection(cauldron.getBrew()));
                                    pLevel.playSound(null, pPos, ModSounds.CAST_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    SEHelper.increaseBottling(pPlayer, 5);
                                    playSound = true;
                                } else {
                                    pLevel.playSound(null, pPos, ModSounds.SPELL_FAIL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.difDimension"), true);
                                }
                            }
                        }
                    } else if (glassBottle) {
                        ItemStack bottle = null;
                        if (cauldron.mode == BrewCauldronBlockEntity.Mode.IDLE) {
                            bottle = PotionUtils.setPotion(new ItemStack(Items.POTION), Potions.WATER);
                        } else if (cauldron.mode == BrewCauldronBlockEntity.Mode.COMPLETED) {
                            SEHelper.increaseBottling(pPlayer);
                            bottle = cauldron.getBrew();
                        } else if (cauldron.mode == BrewCauldronBlockEntity.Mode.CRAFTED) {
                            SEHelper.increaseBottling(pPlayer);
                            bottle = cauldron.getCraftedItem();
                        } else if (cauldron.mode == BrewCauldronBlockEntity.Mode.FAILED){
                            bottle = new ItemStack(ModItems.REFUSE_BOTTLE.get());
                        }
                        if (bottle != null) {
                            ItemHelper.addAndConsumeItem(pPlayer, pHand, bottle);
                            playSound = true;
                        }
                    } else if (waterBottle) {
                        ItemHelper.addAndConsumeItem(pPlayer, pHand, new ItemStack(Items.GLASS_BOTTLE));
                        playSound = true;
                    } else if (ladle) {
                        cauldron.brew(pPlayer);
                    }
                    if (targetLevel == 0) {
                        cauldron.mode = cauldron.reset();
                    }
                }
            }
            if (targetLevel > -1 && pState.getValue(ModStateProperties.LEVEL_BREW) != targetLevel) {
                pLevel.setBlockAndUpdate(pPos, pState.setValue(ModStateProperties.LEVEL_BREW, targetLevel));
            }
            if (playSound) {
                pLevel.playSound(null, pPos, bucket ? SoundEvents.BUCKET_FILL : waterBucket ? SoundEvents.BUCKET_EMPTY : glassBottle ? SoundEvents.BOTTLE_FILL : SoundEvents.BOTTLE_EMPTY, SoundSource.BLOCKS, 1.0F, 1.0F);
            }
            cauldron.markUpdated();
        }
        return InteractionResult.sidedSuccess(pLevel.isClientSide);
    }
    return super.use(pState, pLevel, pPos, pPlayer, pHand, pHit);
}

public void tick() {
    super.tick();
    if (this.isDeadOrDying()){
        this.setYRot(this.deathRotation);
        this.setYBodyRot(this.deathRotation);
    } else {
        this.interestedAngleO = this.interestedAngle;
        if (this.isInterested()) {
            this.interestedAngle += (1.0F - this.interestedAngle) * 0.4F;
        } else {
            this.interestedAngle += (0.0F - this.interestedAngle) * 0.4F;
        }
        if (this.happyCool > 0) {
            --this.happyCool;
        }
    }
    if (!this.level.isClientSide()) {
        if (!this.isDeadOrDying()) {
            if (!this.isMeleeAttacking() && !this.isSummoning()) {
                if (this.isStaying()) {
                    this.isStandingUp = MathHelper.secondsToTicks(1);
                    if (this.isSittingDown > 0
                            && this.getCurrentAnimation() != this.getAnimationState(SIT)) {
                        --this.isSittingDown;
                        this.getNavigation().stop();
                        this.setAnimationState(TO_SIT);
                    } else {
                        if (this.isSittingDown > 0) {
                            this.isSittingDown = 0;
                        }
                        this.setAnimationState(SIT);
                    }
                } else {
                    this.isSittingDown = MathHelper.secondsToTicks(1);
                    if (this.isStandingUp > 0 && this.level.getBlockState(this.blockPosition().above()).isAir()) {
                        --this.isStandingUp;
                        this.getNavigation().stop();
                        this.setAnimationState(TO_STAND);
                    } else {
                        if (this.isStandingUp > 0) {
                            this.isStandingUp = 0;
                        }
                        if (!this.level.getBlockState(this.blockPosition().above()).isAir()
                                && this.isCrouching()
                                && !this.isMoving()){
                            this.setAnimationState(SIT);
                        } else {
                            this.setAnimationState(IDLE);
                        }
                    }
                }
            }
            if (MobsConfig.BlackBeastDayStrength.get()) {
                int boostAmp = 1;
                int resistAmp = 0;

                if (this.level.dayTime() >= MathHelper.minecraftDayToTicks(100)) {
                    boostAmp = 2;
                    resistAmp = 2;
                }

                if (this.level.dayTime() >= MathHelper.minecraftDayToTicks(50) && !MobUtil.isInSunlightNoRain(this)) {
                    this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 20, boostAmp, false, false));
                    this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, resistAmp, false, false));
                }
            }
            if (this.attackTick > 0) {
                --this.attackTick;
            }
            if (this.summonCool > 0) {
                --this.summonCool;
            }
            if (this.pathFindTick > 0) {
                --this.pathFindTick;
            }
            if (this.getTarget() != null){
                if (this.pathFindTick <= 0){
                    this.path = this.findPath(this.getTarget().position());
                    this.pathFindTick = 10;
                }
                if (this.getTarget().getY() > this.getY() && !this.isWithinMeleeAttackRange(this.getTarget()) && (this.path == null || !this.path.canReach())) {
                    this.beastHeadTick();
                }
            }
            if (this.summonTick > 0) {
                this.getNavigation().stop();
                --this.summonTick;
            }
            if (this.summonTick == MathHelper.secondsToTicks(1.17F)) {
                CameraShake.cameraShake(this.level, this.position(), 10.0F, 0.1F, 0, 20);
                this.roar();
            }

            if (this.summonTick == MathHelper.secondsToTicks(1)){
                if (this.level instanceof ServerLevel serverLevel) {
                    for (int i1 = 0; i1 < 3; ++i1) {
                        Summoned summonedentity = new BlackWolf(ModEntityType.BLACK_WOLF.get(), serverLevel);
                        BlockPos blockPos = BlockFinder.SummonRadius(this.blockPosition(), summonedentity, serverLevel);
                        summonedentity.setTrueOwner(this);
                        summonedentity.moveTo(blockPos, this.getYRot(), this.getXRot());
                        MobUtil.moveDownToGround(summonedentity);
                        summonedentity.setPersistenceRequired();
                        summonedentity.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                        if (this.getTrueOwner() != null) {
                            summonedentity.setUpgraded(CuriosFinder.hasWildRobe(this.getTrueOwner()));
                        }
                        summonedentity.setLimitedLife(MobUtil.getSummonLifespan(serverLevel));
                        summonedentity.setHealth(summonedentity.getMaxHealth());
                        this.setTarget(this.getTarget());
                        serverLevel.addFreshEntity(summonedentity);
                    }
                }
            }
            if (this.getPrey() != null){
                if (this.getTarget() == null){
                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(this.getPrey())
                            && MobUtil.sameDimension(this, this.getPrey())
                            && this.level.isLoaded(this.getPrey().blockPosition())) {
                        this.setTarget(this.getPrey());
                    }
                } else if (this.getTarget() == this.getPrey()){
                    if (this.getTarget().distanceTo(this) > 64.0D
                            && MobUtil.sameDimension(this, this.getPrey())){
                        this.teleportTowards(this.getPrey());
                    }
                }
                this.chunkLoadTarget(this.getPrey().blockPosition());
                if (this.getTrueOwner() != null) {
                    if (MobUtil.areAllies(this.getPrey(), this.getTrueOwner()) || this.getPrey().isDeadOrDying()) {
                        if (this.getTrueOwner().distanceTo(this) > 32.0D
                                && MobUtil.sameDimension(this, this.getTrueOwner())) {
                            this.teleportTowards(this.getTrueOwner());
                        }
                        if (this.getPrey() != null){
                            this.setPrey(null);
                        }
                    }
                }
            }
        }
    }

    boolean shouldCrouch = !this.level.getBlockState(this.blockPosition().above().relative(this.getDirection())).isAir() && this.level.getBlockState(this.blockPosition().relative(this.getDirection())).isAir();

    if (!shouldCrouch && !this.isInWall()) {
        this.setPose(Pose.STANDING);
    } else {
        this.setPose(Pose.CROUCHING);
    }
}

	public void onLivingDropsLowest(LivingDropsEvent event) {
		Level level = event.getEntity().level();

		/*
		 * Eldritch Pan cooking logic.
		 */

        if (event.getSource().getDirectEntity() instanceof ServerPlayer player)
            if (SuperpositionHandler.isTheWorthyOne(player))
                if (player.getMainHandItem().is(EnigmaticItems.ELDRITCH_PAN)
                        || player.getOffhandItem().is(EnigmaticItems.ELDRITCH_PAN))
                    for (ItemEntity drop : new ArrayList<>(event.getDrops())) {
                        ItemStack stack = drop.getItem();
                        Optional<SmeltingRecipe> optional = level.getRecipeManager().getRecipeFor(
                                RecipeType.SMELTING, new SimpleContainer(stack), level);

                        optional.ifPresent(recipe -> {
                            ItemStack result = recipe.getResultItem(level.registryAccess());

                            if (!result.isEmpty()) {
                                ItemStack cooked = result.copyWithCount(stack.getCount() * result.getCount());

                                event.getDrops().remove(drop);
                                this.addDrop(event, cooked);
                            }
                        });
                    }

		/*
		 * Escape Scroll logic.
		 */

		if (event.getEntity() instanceof ServerPlayer player) {
			CompoundTag deathLocation = new CompoundTag();
			deathLocation.putDouble("x", player.getX());
			deathLocation.putDouble("y", player.getY());
			deathLocation.putDouble("z", player.getZ());
			deathLocation.putString("dimension", player.level().dimension().location().toString());

			SuperpositionHandler.setPersistentTag(player, "LastDeathLocation", deathLocation);

			boolean droppedCrystal = false;
			boolean hadEscapeScroll = this.hadEscapeScroll(player);

			DimensionalPosition dimPoint = hadEscapeScroll ? SuperpositionHandler.getRespawnPoint(player) : new DimensionalPosition(player.getX(), player.getY(), player.getZ(), player.level());

			if (hadEscapeScroll) {
				BlockPos respawnPos = player.getRespawnPosition();
				ServerLevel respawnLevel = ServerLifecycleHooks.getCurrentServer().getLevel(player.getRespawnDimension());
				boolean isEndAnchor = false;

				if (respawnLevel.getBlockState(respawnPos).is(EnigmaticBlocks.END_ANCHOR)) {
					dimPoint = new DimensionalPosition(respawnPos.getX() + 0.5, respawnPos.getY() + 1.5,
							respawnPos.getZ() + 0.5, respawnLevel);
					isEndAnchor = true;
				}

				player.level().playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 100, 1.25F, false));

				for (ItemEntity dropIt : event.getDrops()) {
					ItemEntity alternativeDrop = new ItemEntity(dimPoint.world, dimPoint.posX, dimPoint.posY, dimPoint.posZ, dropIt.getItem());
					alternativeDrop.teleportTo(dimPoint.posX, dimPoint.posY, dimPoint.posZ);

					if (!isEndAnchor) {
						alternativeDrop.setDeltaMovement(THEY_SEE_ME_ROLLIN.nextDouble()-0.5, THEY_SEE_ME_ROLLIN.nextDouble()-0.5, THEY_SEE_ME_ROLLIN.nextDouble()-0.5);
					} else {
						alternativeDrop.setDeltaMovement(0, 0, 0);
					}

					dimPoint.world.addFreshEntity(alternativeDrop);
					dropIt.setItem(ItemStack.EMPTY);
				}

				event.getDrops().clear();

				final DimensionalPosition dimPointFinal = dimPoint;

				dimPoint.world.playSound(null, BlockPos.containing(dimPoint.posX, dimPoint.posY, dimPoint.posZ), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(dimPointFinal.posX, dimPointFinal.posY, dimPointFinal.posZ, 128, dimPointFinal.world.dimension())), new PacketRecallParticles(dimPoint.posX, dimPoint.posY, dimPoint.posZ, 48, false));
			}

			if (this.hadEnigmaticAmulet(player) && !event.getDrops().isEmpty() && EnigmaticItems.ENIGMATIC_AMULET.isVesselEnabled()) {
				ItemStack soulCrystal = SuperpositionHandler.canDropSoulCrystal(player, this.hadCursedRing(player)) ? EnigmaticItems.SOUL_CRYSTAL.createCrystalFrom(player) : null;
				ItemStack storageCrystal = EnigmaticItems.STORAGE_CRYSTAL.storeDropsOnCrystal(event.getDrops(), player, soulCrystal);
				PermanentItemEntity droppedStorageCrystal = new PermanentItemEntity(dimPoint.world, dimPoint.getPosX(), dimPoint.getPosY() + 1.5, dimPoint.getPosZ(), storageCrystal);
				droppedStorageCrystal.setOwnerId(player.getUUID());
				dimPoint.world.addFreshEntity(droppedStorageCrystal);
				EnigmaticLegacy.LOGGER.info("Summoned Extradimensional Storage Crystal for " + player.getGameProfile().getName() + " at X: " + dimPoint.getPosX() + ", Y: " + dimPoint.getPosY() + ", Z: " + dimPoint.getPosZ());
				event.getDrops().clear();

				if (soulCrystal != null) {
					droppedCrystal = true;
				}

				SoulArchive.getInstance().addItem(droppedStorageCrystal);
			} else if (SuperpositionHandler.canDropSoulCrystal(player, this.hadCursedRing(player))) {
				ItemStack soulCrystal = EnigmaticItems.SOUL_CRYSTAL.createCrystalFrom(player);
				PermanentItemEntity droppedSoulCrystal = new PermanentItemEntity(dimPoint.world, dimPoint.getPosX(), dimPoint.getPosY() + 1.5, dimPoint.getPosZ(), soulCrystal);
				droppedSoulCrystal.setOwnerId(player.getUUID());
				dimPoint.world.addFreshEntity(droppedSoulCrystal);
				EnigmaticLegacy.LOGGER.info("Teared Soul Crystal from " + player.getGameProfile().getName() + " at X: " + dimPoint.getPosX() + ", Y: " + dimPoint.getPosY() + ", Z: " + dimPoint.getPosZ());

				droppedCrystal = true;
				SoulArchive.getInstance().addItem(droppedSoulCrystal);
			}

			if (SuperpositionHandler.isPermanentlyDead(player)) {
				EnigmaticLegacy.packetInstance.send(PacketDistributor.PLAYER.with(() -> player),
						new PacketPermadeath());
				SuperpositionHandler.setCurrentWorldFractured(true);
			}

			ResourceLocation soulLossAdvancement = new ResourceLocation(EnigmaticLegacy.MODID, "book/soul_loss");

			if (SuperpositionHandler.isAffectedBySoulLoss(player, this.hadCursedRing(player))) {
				SuperpositionHandler.grantAdvancement(player, soulLossAdvancement);
			} else if (SuperpositionHandler.hasAdvancement(player, soulLossAdvancement)) {
				SuperpositionHandler.revokeAdvancement(player, soulLossAdvancement);
			}

			POSTMORTAL_POSESSIONS.removeAll(player);
			return;
		} else if (event.getEntity() instanceof Player) {
			POSTMORTAL_POSESSIONS.removeAll(event.getEntity());
		}

		/*
		 * Ender Slayer XP conversion.
		 */

		if (event.isRecentlyHit() && event.getSource() != null && event.getSource().getEntity() instanceof Player && SuperpositionHandler.isTheCursedOne((Player) event.getSource().getEntity())) {
			Player player = (Player) event.getSource().getEntity();
			LivingEntity killed = event.getEntity();

			if (killed instanceof EnderMan && killed.level().dimension().equals(PROXY.getEndKey())
					&& killed.getPersistentData().getBoolean("EnderSlayerVictim")) {
				int extraXP = 0;

				for (ItemEntity entity : event.getDrops()) {
					if (entity.getItem() != null) {
						if (entity.getItem().is(Items.ENDER_PEARL)) {
							this.dropXPOrb(killed.level(), killed.getX(), killed.getY(), killed.getZ(), 10);
							//extraXP += 10;
						} else if (entity.getItem().is(Items.ENDER_EYE)) {
							this.dropXPOrb(killed.level(), killed.getX(), killed.getY(), killed.getZ(), 20);
							//extraXP += 20;
						}
					}
				}

				//killed.getPersistentData().remove("EnderSlayerVictim");
				//killed.getPersistentData().putInt("EnderSlayerExtraXP", extraXP);
				event.getDrops().clear();
				event.setCanceled(true);
			}
		}
	}

public void onUpdate(){

	if(suspendTimer > 0){
		suspendTimer--;
	}

	if(this.getCaster() == null && this.casterUUID != null){
		Entity entity = EntityUtils.getEntityByUUID(world, casterUUID);
		if(entity instanceof EntityLivingBase){
			this.caster = new WeakReference<>((EntityLivingBase)entity);
		}
	}

	if(getBlock() != null){

		// === Copied from super ===

		Block block = getBlock().getBlock();

		if(getBlock().getMaterial() == Material.AIR){
			this.setDead();

		}else{

			this.prevPosX = this.posX;
			this.prevPosY = this.posY;
			this.prevPosZ = this.posZ;

			if(this.fallTime++ == 0){

				BlockPos blockpos = new BlockPos(this);

				if(this.world.getBlockState(blockpos).getBlock() == block){
					this.world.setBlockToAir(blockpos);
				}else if(!this.world.isRemote){
					this.setDead();
					return;
				}
			}

			if(!this.hasNoGravity()){
				this.motionY -= 0.03999999910593033D;
			}

			this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);

			if(!this.world.isRemote){

				BlockPos blockpos1 = new BlockPos(this);
				boolean isConcrete = getBlock().getBlock() == Blocks.CONCRETE_POWDER;
				boolean isConcreteInWater = isConcrete && this.world.getBlockState(blockpos1).getMaterial() == Material.WATER;
				double d0 = this.motionX * this.motionX + this.motionY * this.motionY + this.motionZ * this.motionZ;

				if(isConcrete && d0 > 1.0D){

					RayTraceResult raytraceresult = this.world.rayTraceBlocks(new Vec3d(this.prevPosX, this.prevPosY, this.prevPosZ), new Vec3d(this.posX, this.posY, this.posZ), true);

					if(raytraceresult != null && this.world.getBlockState(raytraceresult.getBlockPos()).getMaterial() == Material.WATER){
						blockpos1 = raytraceresult.getBlockPos();
						isConcreteInWater = true;
					}
				}

				if(!this.onGround && !isConcreteInWater){

					if(this.fallTime > 100 && !this.world.isRemote && (blockpos1.getY() < 1 || blockpos1.getY() > 256) || this.fallTime > 600){
						this.setDead();
					}

				}else{

					IBlockState iblockstate = this.world.getBlockState(blockpos1);

					if(this.world.isAirBlock(new BlockPos(this.posX, this.posY - 0.009999999776482582D, this.posZ))){
						if(!isConcreteInWater && BlockFalling.canFallThrough(this.world.getBlockState(new BlockPos(this.posX, this.posY - 0.009999999776482582D, this.posZ)))){
							this.onGround = false;
							return;
						}
					}

					this.motionX *= 0.699999988079071D;
					this.motionZ *= 0.699999988079071D;
					this.motionY *= -0.5D;

					if(iblockstate.getBlock() != Blocks.PISTON_EXTENSION){

						if(suspendTimer == 0){

							this.setDead(); // Moved inside the above if statement

							if(this.world.mayPlace(block, blockpos1, true, EnumFacing.UP, null)
									&& (isConcreteInWater || !BlockFalling.canFallThrough(this.world.getBlockState(blockpos1.down())))
									&& this.world.setBlockState(blockpos1, getBlock(), 3)){

								if(block instanceof BlockFalling){
									((BlockFalling)block).onEndFalling(this.world, blockpos1, getBlock(), iblockstate);
								}

								if(this.tileEntityData != null && block.hasTileEntity(getBlock())){

									TileEntity tileentity = this.world.getTileEntity(blockpos1);

									if(tileentity != null){

										NBTTagCompound nbttagcompound = tileentity.writeToNBT(new NBTTagCompound());

										for(String s : this.tileEntityData.getKeySet()){
											NBTBase nbtbase = this.tileEntityData.getTag(s);

											if(!"x".equals(s) && !"y".equals(s) && !"z".equals(s)){
												NBTExtras.storeTagSafely(nbttagcompound, s, nbtbase.copy());
											}
										}

										tileentity.readFromNBT(nbttagcompound);
										tileentity.markDirty();
									}
								}

							}else{
								// Never drops the block, instead if it can't reattach to the world it breaks
								world.playEvent(2001, this.getPosition(), Block.getStateId(getBlock()));
							}
						}
					}
				}
			}

			this.motionX *= 0.9800000190734863D;
			this.motionY *= 0.9800000190734863D;
			this.motionZ *= 0.9800000190734863D;
		}

		// === End super copy ===
	}

	double velocitySquared = motionX * motionX + motionY * motionY + motionZ * motionZ;

	if(velocitySquared >= 0.2){

		List<Entity> list = this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox());

		for(Entity entity : list){

			if(entity instanceof EntityLivingBase && isValidTarget(entity)){

				float damage = Spells.greater_telekinesis.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;
				damage *= Math.min(1, velocitySquared/0.4); // Reduce damage at low speeds

				entity.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
						MagicDamage.DamageType.FORCE), damage);

				double dx = -this.motionX;
				double dz;
				for(dz = -this.motionZ; dx * dx + dz * dz < 1.0E-4D; dz = (Math.random() - Math.random()) * 0.01D){
					dx = (Math.random() - Math.random()) * 0.01D;
				}
				((EntityLivingBase)entity).knockBack(this, 0.6f, dx, dz);
			}
		}
	}

}

public void tick() {
    if (this.getInvulnerableTicks() > 0) {
        this.setAnimationState("intro");
        this.setDeltaMovement(Vec3.ZERO);
        int j1 = this.getInvulnerableTicks() - 1;
        if (j1 == 30){
            for(int i = 0; i < 5; ++i) {
                double d0 = this.random.nextGaussian() * 0.02D;
                double d1 = this.random.nextGaussian() * 0.02D;
                double d2 = this.random.nextGaussian() * 0.02D;
                this.level.addParticle(ModParticleTypes.CONFUSED.get(), this.getRandomX(1.0D), this.getRandomY() + 1.0D, this.getRandomZ(1.0D), d0, d1, d2);
            }
            this.playSound(ModSounds.VIZIER_CONFUSE.get(), 1.0F, 1.0F);
        }
        if (j1 == 10) {
            for(int i = 0; i < 5; ++i) {
                double d0 = this.random.nextGaussian() * 0.02D;
                double d1 = this.random.nextGaussian() * 0.02D;
                double d2 = this.random.nextGaussian() * 0.02D;
                this.level.addParticle(ParticleTypes.ANGRY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 1.0D, this.getRandomZ(1.0D), d0, d1, d2);
            }
            this.playSound(ModSounds.VIZIER_RAGE.get(), 1.0F, 1.0F);
        }
        this.setInvulnerableTicks(j1);
        if (!this.level.isClientSide){
            this.level.broadcastEntityEvent(this, (byte) 5);
        }
    } else if (!this.isDeadOrDying()) {
        this.setAnimationState(0);
    }
    this.noPhysics = true;
    super.tick();
    this.noPhysics = false;
    this.setNoGravity(true);
    this.oBob = this.bob;

    if (this.moddedInvul > 0){
        --this.moddedInvul;
    }

    float f = Math.min(0.1F, Mth.sqrt((float) getHorizontalDistanceSqr(this.getDeltaMovement())));

    this.bob += (f - this.bob) * 0.4F;
    if (this.level.getDifficulty() == Difficulty.PEACEFUL) {
        this.remove(RemovalReason.DISCARDED);
    }
    if (!this.isSpellcasting()){
        this.setCasting(this.getCasting() + 1);
    } else {
        if (this.getCastTimes() == 3){
            this.setDeltaMovement(Vec3.ZERO);
        } else {
            Vec3 vector3d = this.getDeltaMovement().multiply(1.0D, 0.6D, 1.0D);
            if (!this.level.isClientSide){
                if (this.getTarget() != null){
                    double d0 = vector3d.y;
                    if (this.getY() < this.getTarget().getY() + 3.0D) {
                        d0 = Math.max(0.0D, d0);
                        d0 = d0 + (0.3D - d0 * (double)0.6F);
                    }

                    vector3d = new Vec3(vector3d.x, d0, vector3d.z);
                    Vec3 vector3d1 = new Vec3(this.getTarget().getX() - this.getX(), 0.0D, this.getTarget().getZ() - this.getZ());
                    if (getHorizontalDistanceSqr(vector3d1) > 9.0D) {
                        Vec3 vector3d2 = vector3d1.normalize();
                        vector3d = vector3d.add(vector3d2.x * 0.3D - vector3d.x * 0.6D, 0.0D, vector3d2.z * 0.3D - vector3d.z * 0.6D);
                    }
                }
            }
            this.setDeltaMovement(vector3d);
            if (getHorizontalDistanceSqr(vector3d) > 0.05D) {
                this.setYRot((float)Mth.atan2(vector3d.z, vector3d.x) * (180F / (float)Math.PI) - 90.0F);
            }
        }
    }
    if (this.getCasting() >= 300){
        this.setCasting(0);
    }
    int i = this.level.getEntitiesOfClass(Irk.class, this.getBoundingBox().inflate(64)).size();
    if (MobsConfig.VizierMinion.get()){
        i = this.level.getEntitiesOfClass(Vex.class, this.getBoundingBox().inflate(64)).size();
    }
    if (this.getCastTimes() == 1){
        if (i >= 2){
            if (this.level.random.nextBoolean()) {
                this.setCastTimes(2);
            } else {
                this.setCastTimes(3);
            }
        } else {
            this.setCastTimes(3);
        }
    }
    this.moveCloak();
    MiscCapHelper.updateMobTarget(this);
    if (this.getTarget() == null){
        for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(32.0F), EntitySelector.NO_CREATIVE_OR_SPECTATOR)){
            if ((livingEntity instanceof Player || livingEntity instanceof AbstractVillager || livingEntity instanceof IronGolem) && canAttack(livingEntity)){
                this.setTarget(livingEntity);
            }
        }
    } else {
        if (!EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(this.getTarget())) {
            this.setTarget(null);
        } else {
            if (!this.getTarget().onGround() && this.getTarget().noJumpDelay <= 0){
                ++this.airBound;
            } else {
                this.airBound = 0;
            }
        }
    }
    double nearestGround = BlockFinder.findNearestGroundY(this.level, this.blockPosition(), 20);
    double currentY = this.getY();

    double minAbove = 2.0D;
    double maxAbove = 8.0D;
    double idealHeight = 4.0D;

    double aboveGround = currentY - nearestGround;

    boolean adjust = false;
    double targetY = currentY;

    if (aboveGround < minAbove) {
        targetY = nearestGround + idealHeight;
        adjust = true;
    } else if (aboveGround > maxAbove) {
        if (this.getTarget() != null && !this.getTarget().onGround() && this.airBound > AIR_BOUND_TIME / 2) {
            if (aboveGround > maxAbove * 2) {
                targetY = nearestGround + maxAbove;
                adjust = true;
            }
        } else {
            targetY = nearestGround + idealHeight;
            adjust = true;
        }
    }

    if (adjust && !this.isSpellcasting()) {
        this.getMoveControl().setWantedPosition(this.getX(), targetY, this.getZ(), 0.8F);
    }

    if (this.tickCount % 5 == 0) {
        this.bossInfo.update();
    }
    this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());

    if (this.level instanceof ServerLevel serverLevel){
        if (this.tickCount % 5 == 0 && this.tickCount < 100) {
            if (this.getTarget() != null && this.getTarget().isAlive()) {
                if (serverLevel.structureManager().getStructureWithPieceAt(this.blockPosition(), StructureTags.ON_WOODLAND_EXPLORER_MAPS).isValid()) {
                    StructureStart structureStart = serverLevel.structureManager().getStructureWithPieceAt(this.blockPosition(), StructureTags.ON_WOODLAND_EXPLORER_MAPS);
                    BoundingBox boundingBox = structureStart.getBoundingBox();
                    AABB aabb = new AABB(boundingBox.minX(), boundingBox.minY(), boundingBox.minZ(), boundingBox.maxX(), boundingBox.maxY(), boundingBox.maxZ());
                    for (Raider raider : this.level.getEntitiesOfClass(Raider.class, aabb)) {
                        if (raider.getTarget() == null) {
                            raider.setTarget(this.getTarget());
                        }
                    }
                }
            }
        }
    }
}

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
    ItemStack itemstack = pPlayer.getItemInHand(pHand);
    if (this.getTrueOwner() != null && pPlayer == this.getTrueOwner()) {
        ItemStack leaderBanner = this.getLeaderBannerInstance();
        if (pHand == InteractionHand.MAIN_HAND
                && this.canBeLeader()
                && !leaderBanner.isEmpty()
                && ItemHelper.sameBanner(itemstack, leaderBanner)
                && !ItemHelper.sameBanner(this.getItemBySlot(EquipmentSlot.HEAD), leaderBanner)) {
            ItemStack helmet = this.getItemBySlot(EquipmentSlot.HEAD);
            this.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 1.0F, 1.0F);
            this.playSound(this.getCelebrateSound(), 1.0F, this.getVoicePitch());
            this.dropEquipment(EquipmentSlot.HEAD, helmet);
            this.setItemSlot(EquipmentSlot.HEAD, this.getLeaderBannerWithNameInstance());
            this.setGuaranteedDrop(EquipmentSlot.HEAD);
            if (!pPlayer.getAbilities().instabuild) {
                itemstack.shrink(1);
            }
            for (int i = 0; i < 7; ++i) {
                double d0 = this.random.nextGaussian() * 0.02D;
                double d1 = this.random.nextGaussian() * 0.02D;
                double d2 = this.random.nextGaussian() * 0.02D;
                this.level.addParticle(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), d0, d1, d2);
            }
            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().getItem() instanceof TaglockKit
                && TaglockKit.hasEntity(pPlayer.getMainHandItem())
                && !MobUtil.areAllies(pPlayer, TaglockKit.getEntity(pPlayer.getMainHandItem()))
                && this.isLeader()){
            this.setMarked(TaglockKit.getEntity(pPlayer.getMainHandItem()));
            this.setTarget(this.getMarked());
            if (!pPlayer.getAbilities().instabuild) {
                TaglockKit.removeEntity(pPlayer.getMainHandItem());
            }
            if (!this.level.isClientSide) {
                if (this.getMarked() instanceof ServerPlayer player) {
                    if (CuriosFinder.hasCurio(player, ModItems.ALARMING_CHARM.get())) {
                        player.displayClientMessage(Component.translatable("info.goety.summon.hunt").withStyle(ChatFormatting.RED), true);
                        ModNetwork.sendToClient(player, new SPlayPlayerSoundPacket(SoundEvents.RAID_HORN.get(), 64.0F, 1.0F));
                    }
                }
            }

            if (this.isStaying()){
                this.setStaying(false);
            }
            if (this.isGuardingArea()){
                this.setBoundPos(null);
            }
            for (RaiderServant servant : this.getNearbyCompanions()) {
                servant.setMarked(this.getMarked());
                servant.setTarget(this.getMarked());
                if (servant.getLeader() == null){
                    servant.setLeader(this);
                    servant.setFollowing();
                }
                if (MobUtil.sameDimension(servant, this.getMarked())) {
                    servant.teleportTowards(this.getMarked());
                }
            }
            if (MobUtil.sameDimension(this, this.getMarked())) {
                this.teleportTowards(this.getMarked());
            }
            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().is(ModItems.WAYSTONE.get())
                && WaystoneItem.hasBlock(pPlayer.getMainHandItem())
                && WaystoneItem.isSameDimension(this, pPlayer.getMainHandItem())
                && (pPlayer.getOffhandItem().is(Items.GOAT_HORN) || pPlayer.getOffhandItem().is(ModItems.RAIDING_HORN.get()))
                && !SEHelper.getFocusCoolDown(pPlayer).isOnCooldown(ModItems.WAYSTONE.get())
                && this.isLeader()){
            if (this.level instanceof ServerLevel serverLevel) {
                GlobalPos globalPos = WaystoneItem.getPosition(pPlayer.getMainHandItem());
                if (globalPos != null){
                    BlockPos blockPos = globalPos.pos();
                    if (!serverLevel.isLoaded(blockPos)){
                        pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.unloaded"), true);
                        return InteractionResult.FAIL;
                    }
                    if (serverLevel.isVillage(blockPos)){
                        if (this.isAllyWithType(EntityType.VILLAGER)) {
                            return InteractionResult.FAIL;
                        }
                        this.setRaidPos(blockPos);
                        this.setRaidDim(serverLevel.dimension());
                        if (this.isStaying()){
                            this.setStaying(false);
                        }
                        if (this.isGuardingArea()){
                            this.setBoundPos(null);
                        }
                        boolean flag = this.position().distanceToSqr(blockPos.getCenter()) <= Mth.square(32);
                        if (!flag) {
                            int k = 0;
                            BlockPos blockPos1 = this.findRandomSpawnPos(k, 20);
                            if (blockPos1 != null) {
                                for (RaiderServant servant : this.getNearbyCompanions()) {
                                    servant.setRaidPos(blockPos);
                                    servant.setRaidDim(serverLevel.dimension());
                                    if (servant.getLeader() == null) {
                                        servant.setLeader(this);
                                        servant.setFollowing();
                                    }
                                    servant.moveTo(blockPos1, 0.0F, 0.0F);
                                }
                                this.moveTo(blockPos1, 0.0F, 0.0F);
                                flag = true;
                            } else {
                                ++k;
                            }
                        }
                        if (flag) {
                            long j = serverLevel.getRandom().nextLong();
                            for(ServerPlayer serverplayer : serverLevel.players()) {
                                Vec3 vec3 = serverplayer.position();
                                Vec3 vec31 = this.position();
                                double d0 = Math.sqrt((vec31.x - vec3.x) * (vec31.x - vec3.x) + (vec31.z - vec3.z) * (vec31.z - vec3.z));
                                double d1 = vec3.x + 13.0D / d0 * (vec31.x - vec3.x);
                                double d2 = vec3.z + 13.0D / d0 * (vec31.z - vec3.z);
                                if (d0 <= 64.0D) {
                                    serverplayer.connection.send(new ClientboundSoundPacket(SoundEvents.RAID_HORN, SoundSource.NEUTRAL, d1, serverplayer.getY(), d2, 64.0F, 1.0F, j));
                                }
                            }
                            if (this.getTrueOwner() instanceof Player player) {
                                SEHelper.addCooldown(player, ModItems.WAYSTONE.get(), 300);
                            }
                            return InteractionResult.SUCCESS;
                        }
                    }
                }
            }
            return InteractionResult.CONSUME;
        } else if (pPlayer.getMainHandItem().is(ModItems.OMINOUS_SHACKLES.get())
                && !this.isCapturing()
                && !this.isFollower()){
            if (!this.level.isClientSide) {
                this.setCaptureMode(true);
                this.playSound(SoundEvents.CHAIN_PLACE, 1.0F, 1.0F);
            }

            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().is(Tags.Items.SHEARS)
                && this.isCapturing()
                && !this.isFollower()){
            if (!this.level.isClientSide) {
                this.setCaptureMode(false);
                this.playSound(SoundEvents.CHAIN_BREAK, 1.0F, 0.5F);
            }

            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().isEmpty() && this.isLeader() && !this.getBindPrisoners().isEmpty()){
            for (Prisoner prisoner : this.getBindPrisoners()) {
                prisoner.setLeader(this);
            }
            this.playSound(SoundEvents.CHAIN_PLACE, 1.0F, 1.0F);
            return InteractionResult.SUCCESS;
        } else if (pPlayer.getMainHandItem().isEmpty() && this.getItemBySlot(EquipmentSlot.HEAD).getItem() instanceof BannerItem){
            ItemStack helmet = this.getItemBySlot(EquipmentSlot.HEAD);
            this.setItemSlot(EquipmentSlot.HEAD, ItemStack.EMPTY);
            this.dropEquipment(EquipmentSlot.HEAD, helmet);
            return InteractionResult.SUCCESS;
        } else if (this.canLinkToIdol()) {
            return this.linkToIdol(pPlayer, pHand);
        }
    }
    return super.mobInteract(pPlayer, pHand);
}

public void tick() {
    super.tick();
    if (this.level.isClientSide) {
        if (this.miningAnimationState.isStarted()) {
            ++this.toMineTick;
            if (this.toMineTick == 26) {
                this.playSound(ModSounds.VILLAGER_CHOP.get());
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), ModSounds.VILLAGER_CHOP.get(), this.getSoundSource(), 1.0F, 1.0F, false);
                ModNetwork.sendToServer(new CPrisonerMinePacket(this.getId()));
            }
            if (this.toMineTick >= 55) {
                this.toMineTick = 0;
            }
        } else {
            this.toMineTick = 0;
        }
    }
    if (!this.level.isClientSide) {
        if (this.isFollowing()) {
            this.level.broadcastEntityEvent(this, (byte) 4);
        } else {
            this.level.broadcastEntityEvent(this, (byte) 5);
        }
        /*if (this.getTrueOwner() instanceof Raider raider && raider.getCurrentRaid() != null) {
            if (raider.getCurrentRaid().isLoss() && raider.isRemoved()) {
                this.discard();
            }
        }*/
        if (this.getTrueOwner() instanceof RaiderServant raider) {
            if (raider.getLeader() != null && this.getLeader() != raider.getLeader()) {
                this.setLeader(raider.getLeader());
                if (raider.getLeader().getTrueOwner() != null) {
                    this.setTrueOwner(raider.getLeader().getTrueOwner());
                }
            }
        }
        if (this.getLeader() == null && this.getTrueOwner() instanceof Player player && this.isFollowing()) {
            float f = this.distanceTo(player);
            if (f > 6.0F) {
                double d0 = (player.getX() - this.getX()) / (double)f;
                double d1 = (player.getY() - this.getY()) / (double)f;
                double d2 = (player.getZ() - this.getZ()) / (double)f;
                this.setDeltaMovement(this.getDeltaMovement().add(Math.copySign(d0 * d0 * 0.4D, d0), Math.copySign(d1 * d1 * 0.4D, d1), Math.copySign(d2 * d2 * 0.4D, d2)));
                this.checkSlowFallDistance();
            }
        }
        if (this.level instanceof ServerLevel serverLevel) {
            if (this.noBlockTick > 0) {
                --this.noBlockTick;
            }
            if (this.updateList > 0) {
                --this.updateList;
            }
            if (MobsConfig.PrisonerHunger.get()) {
                if (this.hasEffect(MobEffects.SATURATION)) {
                    MobEffectInstance instance = this.getEffect(MobEffects.SATURATION);
                    if (instance != null) {
                        this.removeHunger(1);
                    }
                } else if (this.hasEffect(MobEffects.HUNGER)) {
                    MobEffectInstance instance = this.getEffect(MobEffects.HUNGER);
                    if (instance != null) {
                        float chance = 0.005F * (float)(instance.getAmplifier() + 1);
                        if (this.level.getRandom().nextFloat() <= chance) {
                            this.getHungry();
                        }
                    }
                }
                if (this.isHungry()) {
                    this.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN, 5));
                }
            }
            if (this.getMainHandItem().is(ItemTags.PICKAXES) && this.getMainHandItem().getItem() instanceof PickaxeItem pickaxe) {
                int range = MobsConfig.PrisonerMiningRange.get();
                if (this.blockPosList.isEmpty() || this.updateList > 0) {
                    if (!this.blockPosList.isEmpty()) {
                        this.blockPosList.clear();
                    }
                    if (!this.rareList.isEmpty()) {
                        this.rareList.clear();
                    }
                    for (int i = -range; i < range; ++i) {
                        for (int j = -range; j < range; ++j) {
                            for (int k = -range; k < range; ++k) {
                                BlockPos blockPos = this.blockPosition().offset(i, j, k);
                                BlockState blockState = serverLevel.getBlockState(blockPos);
                                boolean hasSight = true;
                                if (MobsConfig.PrisonerMiningSeeBlocks.get()) {
                                    hasSight = false;
                                    for (Direction direction : Direction.values()) {
                                        hasSight = BlockFinder.canSeeBlock(this, blockPos.relative(direction));
                                        if (hasSight) {
                                            break;
                                        }
                                    }
                                }
                                if (hasSight) {
                                    if (blockState.is(ModTags.Blocks.PRISONER_MINEABLE) && !blockState.is(ModTags.Blocks.PRISONER_UNMINEABLE)) {
                                        this.blockPosList.add(blockPos);
                                        if (blockState.is(ModTags.Blocks.PRISONER_RARE_ORES)) {
                                            this.rareList.add(blockPos);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                if (!this.blockPosList.isEmpty()) {
                    int swings = MobsConfig.PrisonerMiningSwings.get();
                    int addChance = 0;
                    if (swings > 1) {
                        if (this.hasEffect(MobEffects.DIG_SPEED)) {
                            if (MobsConfig.PrisonerMiningHaste.get()) {
                                MobEffectInstance instance = this.getEffect(MobEffects.DIG_SPEED);
                                if (instance != null) {
                                    int amp = instance.getAmplifier() + 1;
                                    int tempSwing = swings;
                                    for (int i = 0; i < amp; ++i) {
                                        if ((tempSwing - amp) > 1) {
                                            ++addChance;
                                        } else {
                                            break;
                                        }
                                    }
                                    swings = Math.max(1, swings - amp);
                                }
                            }
                        } else if (this.hasEffect(MobEffects.DIG_SLOWDOWN)) {
                            if (MobsConfig.PrisonerMiningMiningFatigue.get()) {
                                MobEffectInstance instance = this.getEffect(MobEffects.DIG_SLOWDOWN);
                                if (instance != null) {
                                    int amp = instance.getAmplifier() + 1;
                                    swings += amp;
                                }
                            }
                        }
                    }
                    if (this.mineTimes >= swings) {
                        BlockPos blockPos = this.blockPosList.get(RandomUtil.nextInt(serverLevel.getRandom(), blockPosList.size()));
                        boolean isRare = false;
                        if (!this.rareList.isEmpty()) {
                            if (this.rareList.contains(blockPos)) {
                                isRare = true;
                                if (MobsConfig.PrisonerMiningRareChance.get() != 0 && RandomUtil.nextInt(serverLevel.getRandom(), MobsConfig.PrisonerMiningRareChance.get()) != 0) {
                                    List<BlockPos> newBlockList = new ArrayList<>(blockPosList);
                                    newBlockList.removeIf(this.rareList::contains);
                                    if (newBlockList.size() > 1) {
                                        blockPos = this.blockPosList.get(RandomUtil.nextInt(serverLevel.getRandom(), newBlockList.size()));
                                    } else {
                                        blockPos = null;
                                    }
                                }
                            }
                        }
                        if (!isRare) {
                            if (MobsConfig.PrisonerMiningChance.get() != 0 && RandomUtil.nextInt(serverLevel.getRandom(), MobsConfig.PrisonerMiningChance.get()) != 0) {
                                blockPos = null;
                            }
                        }
                        if (blockPos != null) {
                            BlockState blockState = serverLevel.getBlockState(blockPos);
                            if (TierSortingRegistry.isCorrectTierForDrops(pickaxe.getTier(), blockState)) {
                                for (ItemStack itemStack : Block.getDrops(blockState, serverLevel, blockPos, this.level.getBlockEntity(blockPos), this, this.getMainHandItem())) {
                                    this.getInventory().addItem(itemStack);
                                }
                            }
                            if (MobsConfig.PrisonerMiningBreakBlocks.get()) {
                                serverLevel.destroyBlock(blockPos, false, this);
                            }
                        }
                        if (MobsConfig.PrisonerHunger.get()) {
                            float hungerChance = MobsConfig.PrisonerMiningHungerChance.get() / 100.0F;
                            if (addChance > 0) {
                                hungerChance = Math.max(1.0F, hungerChance + (addChance / 10.0F));
                            }
                            if (this.level.getRandom().nextFloat() <= hungerChance) {
                                this.getHungry();
                            }
                        }
                        this.mineTimes = 0;
                        this.updateList = 5;
                    }
                } else {
                    this.noBlockTick = 100;
                    this.mineTimes = 0;
                }

            } else {
                if (!this.blockPosList.isEmpty()) {
                    this.blockPosList.clear();
                }
                if (!this.rareList.isEmpty()) {
                    this.rareList.clear();
                }
            }
        }
    }
}

