	property.setLanguageKey("config." + Wizardry.MODID + ".currency_items");
	propOrder.add(property.getName());
	currencyItems = new HashMap<>();
	currencyItemNbt = new HashMap<>();
	for(String string : property.getStringList()){
		string = string.trim();
		// Split on the last space to separate the item spec from the integer value; this correctly
		// handles NBT strings that contain spaces inside quoted values.
		int lastSpace = string.lastIndexOf(' ');
		if(lastSpace < 0){
			Wizardry.logger.warn("Invalid entry in currency items: {}", string);
			continue;
		}
		String itemSpec = string.substring(0, lastSpace).toLowerCase(Locale.ROOT);
		String valueStr = string.substring(lastSpace + 1);
		// Check for an optional NBT tag (do NOT lowercase the raw NBT string - it is case-sensitive)
		int nbtStart = itemSpec.indexOf('{');
		NBTTagCompound nbt = null;
		if(nbtStart >= 0){
			// Re-extract the NBT portion from the original (non-lowercased) string to preserve case
			String rawNbt = string.substring(nbtStart, lastSpace);
			itemSpec = itemSpec.substring(0, nbtStart);
			try{
				nbt = JsonToNBT.getTagFromJson(rawNbt);
			}catch(NBTException e){
				Wizardry.logger.warn("Invalid NBT in currency items '{}': {}", string, e.getMessage());
				continue;
			}
		}
		try{
			Pair<ResourceLocation, Short> key = parseItemMetaString(itemSpec);
			currencyItems.put(key, Integer.parseInt(valueStr));
			if(nbt != null) currencyItemNbt.put(key, nbt);
		}catch(NumberFormatException e){
			Wizardry.logger.warn("Invalid integer in currency items: {}", valueStr);
		}
	}

	property = config.get(TWEAKS_CATEGORY, "cooldown_reduction_per_level", 0.15,
			"The fraction by which cooldowns are reduced for each level of cooldown upgrade.",
			0.05, Integer.MAX_VALUE); // Sure, I mean you COULD set it to 2^31-1... what could possibly go wrong?
	property.setLanguageKey("config." + Wizardry.MODID + ".cooldown_reduction_per_level");
	cooldownReductionPerLevel = property.getDouble();
	propOrder.add(property.getName());

	property = config.get(TWEAKS_CATEGORY, "storage_increase_per_level", 0.15,
			"The fraction by which maximum charge is increased for each level of storage upgrade.",
			0.05, Integer.MAX_VALUE);
	property.setLanguageKey("config." + Wizardry.MODID + ".storage_increase_per_level");
	storageIncreasePerLevel = (float) property.getDouble();
	propOrder.add(property.getName());

	property = config.get(TWEAKS_CATEGORY, "potency_increase_per_tier", 0.15,
			"The fraction by which potency is increased for each tier of matching wand. May cause extreme lag with high values!",
			0.05, Integer.MAX_VALUE);
	property.setLanguageKey("config." + Wizardry.MODID + ".potency_increase_per_tier");
	potencyIncreasePerTier = property.getDouble();
	propOrder.add(property.getName());

	property = config.get(TWEAKS_CATEGORY, "duration_increase_per_level", 0.25,
			"The fraction by which spell duration is increased for each level of duration upgrade.",
			0.05, Integer.MAX_VALUE);
	property.setLanguageKey("config." + Wizardry.MODID + ".duration_increase_per_level");
	durationIncreasePerLevel = property.getDouble();
	propOrder.add(property.getName());

	property = config.get(TWEAKS_CATEGORY, "range_increase_per_level", 0.25,
			"The fraction by which spell range is increased for each level of range upgrade. May cause extreme lag with high values!",
			0.05, Integer.MAX_VALUE);
	property.setLanguageKey("config." + Wizardry.MODID + ".range_increase_per_level");
	rangeIncreasePerLevel = property.getDouble();
	propOrder.add(property.getName());

	property = config.get(TWEAKS_CATEGORY, "blast_increase_per_level", 0.25,
			"The fraction by which spell blast is increased for each level of blast upgrade. May cause extreme lag with high values!",
			0.05, Integer.MAX_VALUE);
	property.setLanguageKey("config." + Wizardry.MODID + ".blast_increase_per_level");
	blastIncreasePerLevel = property.getDouble();
	propOrder.add(property.getName());


	property = config.get(TWEAKS_CATEGORY, "frost_slowness_increase_per_level", 0.5,
			"The fraction by which movement speed is reduced per level of frost effect.",
			0.05, Integer.MAX_VALUE);
	property.setLanguageKey("config." + Wizardry.MODID + ".frost_slowness_increase_per_level");
	frostSlownessIncreasePerLevel = property.getDouble();
	propOrder.add(property.getName());


	checkForRedundantOptions(TWEAKS_CATEGORY, propOrder); // Must be before the order is set!
	config.setCategoryPropertyOrder(TWEAKS_CATEGORY, propOrder);

}

public Mode insertItem(ItemStack itemStack){
    if (this.level != null && !this.level.isClientSide){
        boolean craft = itemStack.is(ModItems.NIGHTSHADE_BLOSSOM.get());
        if (this.mode == Mode.IDLE && craft) {
            this.clearContent();
            return Mode.CRAFTING;
        } else if (this.mode == Mode.CRAFTING && this.addCraftItem(itemStack)) {
            if (!this.canCraft(this.level)) {
                return this.fail();
            }
            return Mode.CRAFTING;
        }
        Item ingredient = itemStack.getItem();
        BrewModifier brewModifier = new BrewEffects().getModifier(ingredient);
        int modLevel = brewModifier != null ? brewModifier.getLevel() : -1;
        boolean activate = brewModifier instanceof CapacityModifier && brewModifier.getLevel() == 0;
        int firstEmpty = getFirstEmptySlot();
        if (firstEmpty != -1 && this.mode != Mode.CRAFTING) {
            if (this.mode == Mode.BREWING && !this.freeModifier(brewModifier) && !activate) {
                if (this.getOccupiedSlots() >= this.getCapacity()) {
                    return fail();
                }
            }

            this.setItem(firstEmpty, itemStack);
            if (this.mode == Mode.IDLE && this.getCapacity() < BrewConfig.InitialCapacity.get() && activate) {
                this.clearContent();
                this.capacity = BrewConfig.InitialCapacity.get();
                if (this.level instanceof ServerLevel serverLevel){
                    for(int k = 0; k < 20; ++k) {
                        float f2 = serverLevel.random.nextFloat() * 4.0F;
                        float f1 = serverLevel.random.nextFloat() * ((float)Math.PI * 2F);
                        double d1 = Mth.cos(f1) * f2;
                        double d2 = 0.01D + serverLevel.random.nextDouble() * 0.5D;
                        double d3 = Mth.sin(f1) * f2;
                        serverLevel.sendParticles(ParticleTypes.WITCH, (this.getBlockPos().getX() + 0.5D) + d1 * 0.1D, (this.getBlockPos().getY() + 0.5D) + 0.3D, (this.getBlockPos().getZ() + 0.5D) + d3 * 0.1D, 0, d1, d2, d3, 0.25F);
                    }
                }
                return Mode.BREWING;
            }
            if (this.mode == Mode.BREWING) {
                BrewingRecipe brewingRecipe = this.level.getRecipeManager().getAllRecipesFor(ModRecipeSerializer.BREWING_TYPE.get()).stream().filter(recipe -> recipe.input.test(itemStack)).findFirst().orElse(null);
                BrewEffect brewEffect = new BrewEffects().getEffectFromCatalyst(ingredient);
                if (this.hasNoAugmentation()) {
                    if (brewingRecipe != null || brewEffect != null) {
                        if (brewingRecipe != null){
                            if ((brewingRecipe.getCapacityExtra() + this.getCapacityUsed()) <= this.getCapacity()) {
                                this.capacityUsed += brewingRecipe.getCapacityExtra();
                                this.addCost(brewingRecipe.soulCost);
                                this.setColor(BrewUtils.getColor(this.getBrew()));
                                return Mode.BREWING;
                            }
                        }
                        if (brewEffect != null){
                            if ((brewEffect.getCapacityExtra() + this.getCapacityUsed()) <= this.getCapacity()) {
                                this.capacityUsed += brewEffect.getCapacityExtra();
                                this.addCost(brewEffect.getSoulCost());
                                this.setColor(BrewUtils.getColor(this.getBrew()));
                                return Mode.BREWING;
                            }
                        }
                    }
                }

                if (brewModifier != null) {
                    if (BrewUtils.hasEffect(this.getBrew())) {
                        if (brewModifier.getId().equals(BrewModifier.HIDDEN) || brewModifier.getId().equals(BrewModifier.SPLASH) || brewModifier.getId().equals(BrewModifier.LINGERING) || brewModifier.getId().equals(BrewModifier.GAS)) {
                            if (brewModifier.getId().equals(BrewModifier.HIDDEN)) {
                                this.addCost(10);
                            }
                            return Mode.BREWING;
                        }
                        if (brewModifier.getId().equals(BrewModifier.DURATION)) {
                            if (this.getDuration() == 0 && modLevel == 0) {
                                this.duration++;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getDuration() == 1 && modLevel == 1) {
                                this.duration++;
                                this.multiplyCost(1.5F);
                                return Mode.BREWING;
                            }
                            if (this.getDuration() == 2 && modLevel == 2) {
                                this.duration++;
                                this.multiplyCost(2.0F);
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.AMPLIFIER)) {
                            if (this.getAmplifier() == 0 && modLevel == 0) {
                                this.amplifier++;
                                this.multiplyCost(2.0F);
                                return Mode.BREWING;
                            }
                            if (this.getAmplifier() == 1 && modLevel == 1) {
                                this.amplifier++;
                                this.multiplyCost(2.5F);
                                return Mode.BREWING;
                            }
                            if (this.getAmplifier() == 2 && modLevel == 2) {
                                this.amplifier++;
                                this.multiplyCost(3.0F);
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.AOE)) {
                            if (this.getAoE() == 0 && modLevel == 0) {
                                this.aoe++;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getAoE() == 1 && modLevel == 1) {
                                this.aoe++;
                                this.multiplyCost(1.5F);
                                return Mode.BREWING;
                            }
                            if (this.getAoE() == 2 && modLevel == 2) {
                                this.aoe++;
                                this.multiplyCost(2.0F);
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.LINGER)) {
                            if (this.getLingering() == 0 && modLevel == 0) {
                                this.lingering++;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getLingering() == 1 && modLevel == 1) {
                                this.lingering++;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getLingering() == 2 && modLevel == 2) {
                                this.lingering++;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.QUAFF)) {
                            if (this.getQuaff() == 0 && modLevel == 0) {
                                this.quaff += 8;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getQuaff() == 8 && modLevel == 1) {
                                this.quaff += 8;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getQuaff() == 16 && modLevel == 2) {
                                this.quaff += 8;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.VELOCITY)) {
                            if (this.getVelocity() == 0 && modLevel == 0) {
                                this.velocity += 0.1F;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getVelocity() == 0.1F && modLevel == 1) {
                                this.velocity += 0.2F;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                            if (this.getVelocity() == 0.3F && modLevel == 2) {
                                this.velocity += 0.2F;
                                this.multiplyCost(1.25F);
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.AQUATIC)) {
                            if (!this.isAquatic() && modLevel == 0) {
                                this.isAquatic = true;
                                return Mode.BREWING;
                            }
                        }
                        if (brewModifier.getId().equals(BrewModifier.FIRE_PROOF)) {
                            if (!this.isFireProof() && modLevel == 0) {
                                this.isFireProof = true;
                                return Mode.BREWING;
                            }
                        }
                    } else if (brewModifier instanceof CapacityModifier capacityModifier) {
                        int initial = BrewConfig.InitialCapacity.get();
                        int level1 = BrewConfig.Level1Capacity.get();
                        int level2 = BrewConfig.Level2Capacity.get();
                        int level3 = BrewConfig.Level3Capacity.get();
                        int level4 = BrewConfig.Level4Capacity.get();
                        int level5 = BrewConfig.Level5Capacity.get();
                        int level6 = BrewConfig.Level6Capacity.get();
                        if (this.getCapacity() == initial && capacityModifier.getLevel() == 1) {
                            this.capacity += level1;
                            this.clearContent();
                            return Mode.BREWING;
                        }
                        if (this.getCapacity() == (initial + level1) && capacityModifier.getLevel() == 2) {
                            this.capacity += level2;
                            this.clearContent();
                            return Mode.BREWING;
                        }
                        if (this.getCapacity() == (initial + level1 + level2) && capacityModifier.getLevel() == 3) {
                            this.capacity += level3;
                            this.clearContent();
                            return Mode.BREWING;
                        }
                        if (this.getCapacity() == (initial + level1 + level2 + level3) && capacityModifier.getLevel() == 4) {
                            this.capacity += level4;
                            this.clearContent();
                            return Mode.BREWING;
                        }
                        if (this.getCapacity() == (initial + level1 + level2 + level3 + level4) && capacityModifier.getLevel() == 5) {
                            this.capacity += level5;
                            this.clearContent();
                            return Mode.BREWING;
                        }
                        if (this.getCapacity() == (initial + level1 + level2 + level3 + level4 + level5) && capacityModifier.getLevel() == 6) {
                            this.capacity += level6;
                            this.clearContent();
                            return Mode.BREWING;
                        }
                    }
                }
            }
        } else if (this.mode == Mode.IDLE && this.getCapacity() < BrewConfig.InitialCapacity.get() && activate) {
            this.clearContent();
            this.capacity = BrewConfig.InitialCapacity.get();
            if (this.level instanceof ServerLevel serverLevel){
                for(int k = 0; k < 20; ++k) {
                    float f2 = serverLevel.random.nextFloat() * 4.0F;
                    float f1 = serverLevel.random.nextFloat() * ((float)Math.PI * 2F);
                    double d1 = Mth.cos(f1) * f2;
                    double d2 = 0.01D + serverLevel.random.nextDouble() * 0.5D;
                    double d3 = Mth.sin(f1) * f2;
                    serverLevel.sendParticles(ParticleTypes.WITCH, (this.getBlockPos().getX() + 0.5D) + d1 * 0.1D, (this.getBlockPos().getY() + 0.5D) + 0.3D, (this.getBlockPos().getZ() + 0.5D) + d3 * 0.1D, 0, d1, d2, d3, 0.25F);
                }
            }
            return Mode.BREWING;
        }
        this.markUpdated();
    }
    return this.fail();
}

public void onPlayerTick(LivingTickEvent event) {
	if (!event.getEntity().isAlive())
		return;

	if (!event.getEntity().level().isClientSide) {
		if (event.getEntity() instanceof EnderMan || event.getEntity() instanceof Shulker) {
			int cooldown = event.getEntity().getPersistentData().getInt("ELTeleportBlock");

			if (cooldown > 0) {
				if (--cooldown > 0) {
					event.getEntity().getPersistentData().putInt("ELTeleportBlock", cooldown);
				} else {
					event.getEntity().getPersistentData().remove("ELTeleportBlock");
				}
			}
		}
	}

	if (event.getEntity() instanceof Player player) {
		if (!player.level().isClientSide) {
			SCHEDULED_DATA_SYNC.removeIf(p -> {
				TransientPlayerData.get(p).syncToPlayer();
				return true;
			});

			var counter = IPlaytimeCounter.get(player);

			if (SuperpositionHandler.isTheCursedOne(player)) {
				counter.incrementTimeWithCurses();
			} else {
				counter.incrementTimeWithoutCurses();
			}

			if (SuperpositionHandler.hasCurio(player, EnigmaticItems.DESOLATION_RING) && SuperpositionHandler.isTheWorthyOne(player)) {
				DESOLATION_BOXES.put(player, SuperpositionHandler.getBoundingBoxAroundEntity(player, 128));
			} else {
				DESOLATION_BOXES.remove(player);
			}

			if (SuperpositionHandler.hasItem(player, EnigmaticItems.SOUL_COMPASS)) {
				Integer lastUpdate = LAST_SOUL_COMPASS_UPDATE.get(player);

				if (lastUpdate == null || player.tickCount - lastUpdate > 10) {
					var optional = SuperpositionHandler.updateSoulCompass((ServerPlayer) player);


					optional.ifPresent(tuple -> {
						BlockPos pos = tuple.getB();

						if (player.distanceToSqr(pos.getX(), pos.getY(), pos.getZ()) < 256) {
							player.level().getChunkAt(pos);
							UUID id = tuple.getA();
							int radius = 3;

							AABB box = new AABB(pos.getX() - radius, pos.getY() - radius, pos.getZ() - radius,
									pos.getX() + radius, pos.getY() + radius, pos.getZ() + radius);

							List<PermanentItemEntity> list = player.level().getEntitiesOfClass(PermanentItemEntity.class, box, entity -> entity.getUUID().equals(id));

							if (list.size() <= 0) {
								SoulArchive.getInstance().removeItem(id);
							}
						}
					});
				}
			}

			if (player.tickCount % 100 == 0) {
				this.syncPlayTime(player);
			}
		} else {
			if (scheduledCubeRevive > 0 && !(Minecraft.getInstance().screen instanceof ReceivingLevelScreen)) {
				scheduledCubeRevive--;

				if (scheduledCubeRevive == 0) {
					PROXY.displayReviveAnimation(player.getId(), 1);
					scheduledCubeRevive = -1;
				}
			}
		}

		/*
		 * Temporary handler for fixing player state corruption.
		 * I still do not know why it happens.
		 */

		if (Float.isNaN(player.getHealth())) {
			player.setHealth(0F);
		}

		if (Float.isNaN(player.getAbsorptionAmount())) {
			player.setAbsorptionAmount(0F);
		}

		BlueSkiesHelper.maybeFixCapability(player);

		if (EnigmaticItems.FORBIDDEN_FRUIT.haveConsumedFruit(player)) {
			FoodData foodStats = player.getFoodData();
			foodStats.setFoodLevel(20);
			foodStats.saturationLevel = 0F;

			if (player.hasEffect(MobEffects.HUNGER)) {
				player.removeEffect(MobEffects.HUNGER);
			}
		}

		if (!CursedRing.disableInsomnia.getValue())
			if (player.isSleeping() && SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
				if (player.getSleepTimer() == 5) {
					if (player instanceof ServerPlayer) {
						player.sendSystemMessage(Component.translatable("message.enigmaticlegacy.cursed_sleep")
								.withStyle(ChatFormatting.RED));
					}
				} else if (player.getSleepTimer() > 90) {
					player.sleepCounter = 90;
				}
			}

		if (player.isOnFire() && SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
			player.setRemainingFireTicks(player.getRemainingFireTicks()+2);
		}

		/*
		 * Handler for faster effect ticking, if player is bearing Blazing Core.
		 */

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.BLAZING_CORE))
			if (!player.getActiveEffects().isEmpty()) {
				Collection<MobEffectInstance> effects = new ArrayList<>();
				effects.addAll(player.getActiveEffects());

				for (MobEffectInstance effect : effects) {
					if (effect.getEffect().equals(EnigmaticEffects.MOLTEN_HEART)) {
						if (player.tickCount % 2 == 0 && effect.duration > 0) {
							effect.duration += 1;
						}
					} else {
						effect.tick(player, () -> {});
					}
				}

			}

		/*
		 * Handler for removing debuffs from players protected by Etherium Armor Shield.
		 * Removed as of Release 2.5.0.
		 */

		/*
		if (EnigmaticLegacy.etheriumChestplate.hasShield(player))
			if (!player.getActivePotionEffects().isEmpty()) {
				List<MobEffectInstance> effects = new ArrayList<MobEffectInstance>(player.getActivePotionEffects());

				for (MobEffectInstance effect : effects) {
					if (!effect.getPotion().isBeneficial()) {
						player.removePotionEffect(effect.getPotion());
					}
				}
			}
		 */

		if (player instanceof ServerPlayer  serverPlayer) {

			/*
			 * Handler for players' spellstone cooldowns.
			 */

			if (SuperpositionHandler.hasSpellstoneCooldown(player)) {
				SuperpositionHandler.tickSpellstoneCooldown(player, 1);
			}

			TransientPlayerData data = TransientPlayerData.get(player);
			data.setFireImmunityTimer(data.getFireImmunityTimer() - (player.isOnFire() ? 100 : 200));

			if (data.needsSync) {
				data.syncToPlayer();
				data.needsSync = false;
			}

			EnigmaticItems.ENIGMATIC_ITEM.handleEnigmaticFlight(player);

			/*
			 * Detect Unwitnessed Amulet and turn in into random color;
			 */

			for (NonNullList<ItemStack> list : player.getInventory().compartments) {
				for (int i = 0; i < list.size(); ++i) {
					ItemStack stack = list.get(i);

					// Null check 'cause I don't trust you
					if (stack != null) {
						if (stack.is(EnigmaticItems.UNWITNESSED_AMULET)) {
							stack = new ItemStack(EnigmaticItems.ENIGMATIC_AMULET);
							EnigmaticItems.ENIGMATIC_AMULET.setInscription(stack, player.getGameProfile().getName());

							if (EnigmaticAmulet.seededColorGen.getValue()) {
								EnigmaticItems.ENIGMATIC_AMULET.setSeededColor(stack);
							} else {
								EnigmaticItems.ENIGMATIC_AMULET.setRandomColor(stack);
							}

							list.set(i, stack);
						} else if (CursedRing.autoEquip.getValue() && !player.isCreative() && !player.isSpectator()
								&& stack.is(EnigmaticItems.CURSED_RING)) {
							if (!SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
								if (SuperpositionHandler.tryForceEquip(player, stack)) {
									list.set(i, ItemStack.EMPTY);
								}
							}
						}
					}
				}
			}

			/*
			 * Handle Growing Hunger application.
			 */

			List<ItemStack> handItems = ImmutableList.of(player.getMainHandItem()/*, player.getOffhandItem()*/);

			if (handItems.stream().anyMatch(s -> s.is(EnigmaticItems.ELDRITCH_PAN))) {
				int currentTicks = EldritchPan.HOLDING_DURATIONS.getOrDefault(player, 0);

				if (SuperpositionHandler.cannotHunger(player)) {
					int bloodlustAmplifier = currentTicks / GrowingBloodlustEffect.ticksPerLevel.getValue();

					bloodlustAmplifier = Math.min(bloodlustAmplifier, 9);

					player.addEffect(new MobEffectInstance(EnigmaticEffects.GROWING_BLOODLUST,
							MobEffectInstance.INFINITE_DURATION, bloodlustAmplifier, true, true));
				} else {
					int hungerAmplifier = currentTicks / GrowingHungerEffect.ticksPerLevel.getValue();

					hungerAmplifier = Math.min(hungerAmplifier, 9);

					player.addEffect(new MobEffectInstance(EnigmaticEffects.GROWING_HUNGER,
							MobEffectInstance.INFINITE_DURATION, hungerAmplifier, true, true));
				}

				EldritchPan.HOLDING_DURATIONS.put(player, currentTicks + 1);
			} else {
				EldritchPan.HOLDING_DURATIONS.put(player, 0);
				player.removeEffect(EnigmaticEffects.GROWING_HUNGER);
				player.removeEffect(EnigmaticEffects.GROWING_BLOODLUST);
			}
		}

	}

}

public void attackGoals() {
