public void onEntityHurt(LivingHurtEvent event) {
	if (event.getAmount() >= Float.MAX_VALUE)
		return;

	// TODO The priorities are messed up as fuck. We gotta do something about it.

	/*
	 * Ideally fixed numerical increases should come first, then percentage alterations,
	 * and the last in order - handlers that use the event for notification purpose, doing
	 * something other with it than altering damage dealt.
	 */

	if (event.getSource().getEntity() instanceof LivingEntity) {
		LivingEntity attacker = (LivingEntity) event.getSource().getEntity();
		Entity immediateSource = event.getSource().getDirectEntity();

		if (immediateSource instanceof ThrownTrident || immediateSource instanceof LivingEntity) {
			ItemStack mainhandStack = ItemStack.EMPTY;
			if (immediateSource instanceof ThrownTrident) {
				if (((ThrownTrident)immediateSource).tridentItem != null) {
					mainhandStack = ((ThrownTrident)immediateSource).tridentItem;
				}
			} else {
				if (((LivingEntity)immediateSource).getMainHandItem() != null) {
					mainhandStack = ((LivingEntity)immediateSource).getMainHandItem();
				}
			}

			int torrentLevel = 0;
			int wrathLevel = 0;

			if ((torrentLevel = mainhandStack.getEnchantmentLevel(EnigmaticEnchantments.TORRENT)) > 0) {
				event.setAmount(event.getAmount() + EnigmaticEnchantments.TORRENT.bonusDamageByCreature(attacker, event.getEntity(), torrentLevel));
			}

			if ((wrathLevel = mainhandStack.getEnchantmentLevel(EnigmaticEnchantments.WRATH)) > 0) {
				event.setAmount(event.getAmount() + EnigmaticEnchantments.WRATH.bonusDamageByCreature(attacker, event.getEntity(), wrathLevel));
			}
		}
	}

	if (event.getSource().getDirectEntity() instanceof Player && event.getSource().is(DamageTypes.PLAYER_ATTACK)) {
		Player player = (Player) event.getSource().getDirectEntity();

		/*
		 * Handler for applying Withering to victims of bearer of the Void Pearl.
		 */

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.VOID_PEARL)) {
			event.getEntity().addEffect(new MobEffectInstance(MobEffects.WITHER, VoidPearl.witheringTime.getValue(), VoidPearl.witheringLevel.getValue(), false, true));
		}

		if (player instanceof ServerPlayer && SuperpositionHandler.isTheCursedOne(player)) {
			if (player.getMainHandItem().is(EnigmaticItems.ENDER_SLAYER)) {
				if (event.getEntity() instanceof ServerPlayer targetPlayer) {
					targetPlayer.getCooldowns().addCooldown(Items.ENDER_PEARL, 400);
					targetPlayer.getCooldowns().addCooldown(EnigmaticItems.RECALL_POTION, 400);
					targetPlayer.getCooldowns().addCooldown(EnigmaticItems.TWISTED_MIRROR, 400);

					if (SuperpositionHandler.hasCurio(targetPlayer, EnigmaticItems.EYE_OF_NEBULA)
							|| SuperpositionHandler.hasCurio(targetPlayer, EnigmaticItems.THE_CUBE)) {
						SuperpositionHandler.setSpellstoneCooldown(targetPlayer, 400);
					}
				}

				if (event.getEntity() instanceof EnderMan || event.getEntity() instanceof Shulker) {
					event.getEntity().getPersistentData().putInt("ELTeleportBlock", 400);
				}
			}
		}

		float bonusDamage = 0F;

		if (player.getMainHandItem() != null) {
			ItemStack mainhandStack = player.getMainHandItem();

			if (mainhandStack.is(EnigmaticItems.THE_TWIST)) {
				if (SuperpositionHandler.isTheCursedOne(player)) {
					if (OmniconfigHandler.isBossOrPlayer(event.getEntity())) {
						bonusDamage += event.getAmount() * TheTwist.bossDamageBonus.getValue().asModifier(false);
					}
				} else {
					event.setCanceled(true);
				}
			} else if (mainhandStack.is(EnigmaticItems.THE_INFINITUM)) {
				if (SuperpositionHandler.isTheWorthyOne(player)) {
					if (OmniconfigHandler.isBossOrPlayer(event.getEntity())) {
						//event.setAmount(10000000);
						bonusDamage += event.getAmount() * TheInfinitum.bossDamageBonus.getValue().asModifier(false);
					}
				} else {
					event.setCanceled(true);

					player.addEffect(new MobEffectInstance(MobEffects.WITHER,            160, 3, false, true));
					player.addEffect(new MobEffectInstance(MobEffects.CONFUSION,         500, 3, false, true));
					player.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,          300, 3, false, true));
					player.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 300, 3, false, true));
					player.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN,      300, 3, false, true));
					player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS,         100, 3, false, true));
				}
			} else if (mainhandStack.is(EnigmaticItems.ELDRITCH_PAN)) {
				if (!SuperpositionHandler.isTheWorthyOne(player)) {
					event.setCanceled(true);
				}
			} else if (mainhandStack.is(EnigmaticItems.ENDER_SLAYER)) {
				if (SuperpositionHandler.isTheCursedOne(player)) {
					if (EnigmaticItems.ENDER_SLAYER.isEndDweller(event.getEntity())) {
						if (player.level().dimension().equals(PROXY.getEndKey())) {
							if (event.getEntity() instanceof EnderMan
									&& RegisteredMeleeAttack.getRegisteredAttackStregth(player) >= 1F) {
								event.setAmount((event.getAmount() + 100F) * 10F);
							}
							event.getEntity().getPersistentData().putBoolean("EnderSlayerVictim", true);
						}

						bonusDamage += event.getAmount() * EnderSlayer.endDamageBonus.getValue().asModifier(false);
					}
				} else {
					event.setCanceled(true);
				}
			}

			event.setAmount(event.getAmount() + bonusDamage);

			int slayerLevel = 0;
			if ((slayerLevel = mainhandStack.getEnchantmentLevel(EnigmaticEnchantments.SLAYER)) > 0) {
				event.setAmount(event.getAmount() + EnigmaticEnchantments.SLAYER.bonusDamageByCreature(player, event.getEntity(), slayerLevel));

				if (event.getEntity() instanceof Monster) {
					int i = 20 + player.getRandom().nextInt(10 * slayerLevel);
					event.getEntity().addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, i, 3));
				}
			}

			if (EnigmaticEnchantmentHelper.hasNemesisCurseEnchantment(mainhandStack)) {
				float supposedDamage = event.getAmount()*0.35F;

				player.hurt(player.damageSources().source(EnigmaticDamageTypes.NEMESIS_CURSE, event.getEntity()), supposedDamage);
			}
		} else {
			event.setAmount(event.getAmount() + bonusDamage);
		}
	}

	if (event.getEntity() instanceof Player) {
		Player player = (Player) event.getEntity();

		/*
		 * Handler for resistance lists.
		 */

		List<ItemStack> advancedCurios = SuperpositionHandler.getAdvancedCurios(player);
		if (advancedCurios.size() > 0) {
			for (ItemStack advancedCurioStack : advancedCurios) {
				ItemSpellstoneCurio advancedCurio = (ItemSpellstoneCurio) advancedCurioStack.getItem();
				Mob trueSource = event.getSource().getEntity() instanceof Mob ? (Mob)event.getSource().getEntity() : null;

				if ((event.getSource().is(DamageTypes.EXPLOSION) || event.getSource().is(DamageTypes.PLAYER_EXPLOSION)) && advancedCurio == EnigmaticItems.GOLEM_HEART && SuperpositionHandler.hasAnyArmor(player)) {
					continue;
				} else if (advancedCurio == EnigmaticItems.BLAZING_CORE && trueSource != null && (trueSource.getMobType() == MobType.WATER || trueSource instanceof Drowned)) {
					event.setAmount(event.getAmount() * 2F);
				} else if (advancedCurio == EnigmaticItems.EYE_OF_NEBULA && player.isInWater()) {
					event.setAmount(event.getAmount() * 2F);
				} else if (advancedCurio == EnigmaticItems.OCEAN_STONE && trueSource != null && (trueSource.getMobType() == MobType.WATER || trueSource instanceof Drowned)) {
					event.setAmount(event.getAmount() * OceanStone.underwaterCreaturesResistance.getValue().asModifierInverted());
				}

				for (var type : advancedCurio.resistanceList.keySet()) {
					if (event.getSource().is(type)) {
						event.setAmount(event.getAmount() * advancedCurio.resistanceList.get(event.getSource().typeHolder().unwrapKey().get()).get());
						break;
					}
				}
			}
		}

		if (event.getSource().is(DamageTypes.FALL)) {
			if (EnigmaticItems.ENIGMATIC_AMULET.hasColor(player, AmuletColor.MAGENTA)) {
				event.setAmount(event.getAmount() - 2.0f);
			}
		}

		/*
		 * Handler for damaging feedback of Blazing Core.
		 */

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.BLAZING_CORE)) {
			if (event.getSource().getEntity() instanceof LivingEntity && EnigmaticItems.BLAZING_CORE.nemesisList.stream().anyMatch(event.getSource()::is)) {
				LivingEntity attacker = (LivingEntity) event.getSource().getEntity();
				if (!attacker.fireImmune()) {
					attacker.hurt(attacker.damageSources().source(DamageTypes.ON_FIRE, player), (float) BlazingCore.damageFeedback.getValue());
					attacker.setSecondsOnFire(BlazingCore.ignitionFeedback.getValue());
				}
			}

		}

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.BERSERK_CHARM)) {
			event.setAmount(event.getAmount() * (1.0F - (SuperpositionHandler.getMissingHealthPool(player)*(float)BerserkEmblem.damageResistance.getValue())));
		}

		/*
		 * Handler for doubling damage on bearers of Ring of the Seven Curses.
		 */

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
			event.setAmount(event.getAmount()*CursedRing.painMultiplier.getValue().asModifier());
		}

		/*
		 * Handler for increasing damage on users of Bulwark of Blazing Pride.
		 */
		if (event.getSource().getEntity() != null) {
			if (player.getUseItem().getItem() instanceof InfernalShield && ((IProperShieldUser) player).isActuallyReallyBlocking()) {
				Vec3 sourcePos = event.getSource().getSourcePosition();
				if (sourcePos != null) {
					Vec3 lookVec = player.getViewVector(1.0F);
					Vec3 sourceToSelf = sourcePos.vectorTo(player.position()).normalize();
					sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);
					if (!(sourceToSelf.dot(lookVec) < 0.0D)) {
						event.setAmount(event.getAmount() * 1.5F);
					}
				}
			}
		}
	} else if (event.getEntity() instanceof Monster || event.getEntity() instanceof EnderDragon) {
		Mob mob = (Mob) event.getEntity();

		if (event.getSource().getEntity() instanceof Player) {
			Player player = (Player) event.getSource().getEntity();

			if (mob instanceof EnderDragon && player instanceof ServerPlayer splayer) {
				Quote.POOR_CREATURE.playOnceIfUnlocked(splayer, 60);
			}

			/*
			 * Handler for damage bonuses of Charm of Monster Slayer.
			 */

			if (SuperpositionHandler.hasCurio(player, EnigmaticItems.MONSTER_CHARM)) {
				if (mob.isInvertedHealAndHarm()) {
					event.setAmount(event.getAmount() * MonsterCharm.undeadDamageBonus.getValue().asModifier(true));
				} else if (mob.isAggressive() || mob instanceof Creeper) {

					if (mob instanceof EnderMan || mob instanceof ZombifiedPiglin || mob instanceof Blaze || mob instanceof Guardian || mob instanceof ElderGuardian || !mob.canChangeDimensions()) {
						// NO-OP
					} else {
						event.setAmount(event.getAmount() * MonsterCharm.hostileDamageBonus.getValue().asModifier(true));
					}

				}
			}

			/*
			 * Handler for damage debuff of Ring of the Seven Curses.
			 */

			if (SuperpositionHandler.isTheCursedOne(player)) {
				boolean bypass = false;

				if (event.getSource().getDirectEntity() == player)
					if (player.getMainHandItem().getItem() == EnigmaticItems.THE_TWIST
							|| player.getMainHandItem().getItem() == EnigmaticItems.THE_INFINITUM
							|| player.getMainHandItem().getItem() == EnigmaticItems.ELDRITCH_PAN) {
						// Don't do worthiness check since event is gonna be canceled for non-worthy already
						bypass = true;
					}

				if (!bypass) {
					event.setAmount(event.getAmount() * CursedRing.monsterDamageDebuff.getValue().asModifierInverted());
				}
			}
		}
	}

	if (event.getSource().getEntity() instanceof Player player) {
		Entity immediateSource = event.getSource().getDirectEntity();

		float damageBoost = 0F;

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.BERSERK_CHARM)) {
			damageBoost += event.getAmount()*(SuperpositionHandler.getMissingHealthPool(player)*(float)BerserkEmblem.attackDamage.getValue());
		}

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_SCROLL)) {
			damageBoost += event.getAmount()*(CursedScroll.damageBoost.getValue().asModifier()*SuperpositionHandler.getCurseAmount(player));
		}

		event.setAmount(event.getAmount()+damageBoost);

		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.EYE_OF_NEBULA)) {
			if (SuperpositionHandler.isMagic(event.getSource())) {
				event.setAmount(event.getAmount() * EyeOfNebula.magicBoost.getValue().asModifier(true));
			}
		}

		if (TransientPlayerData.get(player).hasEyeOfNebulaPower()) {
			event.setAmount(event.getAmount() * EyeOfNebula.attackEmpower.getValue().asModifier(true));
			TransientPlayerData.get(player).setEyeOfNebulaPower(false);
		}
	}

	if (event.getEntity() instanceof TamableAnimal) {
		TamableAnimal pet = (TamableAnimal) event.getEntity();

		if (pet.isTame()) {
			LivingEntity owner = pet.getOwner();

			if (owner instanceof Player && SuperpositionHandler.hasItem((Player)owner, EnigmaticItems.HUNTER_GUIDEBOOK)) {
				if (owner.level() == pet.level() && owner.distanceTo(pet) <= HunterGuidebook.effectiveDistance.getValue()) {
					event.setCanceled(true);
					owner.hurt(event.getSource(), SuperpositionHandler.hasItem((Player)owner, EnigmaticItems.ANIMAL_GUIDEBOOK) ? (event.getAmount()*HunterGuidebook.synergyDamageReduction.getValue().asModifierInverted()) : event.getAmount());
				}
			}
		}
	}

	if (event.getEntity() instanceof ServerPlayer player && event.getSource().getDirectEntity() instanceof LivingEntity living) {
		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.THE_CUBE)) {
			if (event.getAmount() <= EnigmaticItems.THE_CUBE.getDamageLimit(player) && THEY_SEE_ME_ROLLIN.nextDouble() <= 0.35) {
				event.setCanceled(true);
				living.hurt(event.getSource(), event.getAmount());
				player.level().playSound(null, player.blockPosition(), EnigmaticSounds.SWORD_HIT_REJECT, SoundSource.PLAYERS, 1F, 1F);
			} else {
				EnigmaticItems.THE_CUBE.applyRandomEffect(living, false);
			}
		}
	}
}

public void aiStep() {
    super.aiStep();
    if (this.level.getDifficulty() == Difficulty.PEACEFUL){
        this.remove(RemovalReason.DISCARDED);
    }
    if (this.moddedInvul > 0){
        --this.moddedInvul;
    }
    if (this.obsidianInvul > 0){
        --this.obsidianInvul;
    }
    if (this.level.isClientSide){
        if (this.isSettingUpSecond()){
            for(int i = 0; i < 40; ++i) {
                double d0 = this.random.nextGaussian() * 0.2D;
                double d1 = this.random.nextGaussian() * 0.2D;
                double d2 = this.random.nextGaussian() * 0.2D;
                this.level.addAlwaysVisibleParticle(ParticleTypes.LARGE_SMOKE, this.getX(), this.getY() + 0.5, this.getZ(), d0, d1, d2);
            }
        }
        this.oClientShootIndicatorProgress = this.clientShootIndicatorProgress;
        this.oClientShootIndicatorEnd = this.clientShootIndicatorEnd;
        this.clientShootIndicatorProgress = this.getShootIndicatorProgress();
        this.clientShootIndicatorEnd = new Vec3(this.getShootIndicatorEnd());
    }
    if (!this.level.isClientSide){
        this.addTitleEffect();
        AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (attributeinstance != null) {
            if (attributeinstance.hasModifier(SPEED_MODIFIER_CASTING)){
                attributeinstance.removeModifier(SPEED_MODIFIER_CASTING);
            }
            if (this.isCasting() && !this.isInNether()) {
                attributeinstance.addTransientModifier(SPEED_MODIFIER_CASTING);
            }
            if (attributeinstance.hasModifier(SPEED_MODIFIER_MONOLITH)){
                attributeinstance.removeModifier(SPEED_MODIFIER_MONOLITH);
            }
            if (this.monolithWeakened()){
                attributeinstance.addTransientModifier(SPEED_MODIFIER_MONOLITH);
            }
        }
        AttributeInstance armor = this.getAttribute(Attributes.ARMOR);
        AttributeInstance toughness = this.getAttribute(Attributes.ARMOR_TOUGHNESS);
        if (armor != null && toughness != null) {
            if (armor.hasModifier(WEAK_ARMOR_MODIFIER)){
                armor.removeModifier(WEAK_ARMOR_MODIFIER);
            }
            if (toughness.hasModifier(WEAK_ARMOR_MODIFIER)){
                toughness.removeModifier(WEAK_ARMOR_MODIFIER);
            }
            if (!this.isInNether() && MobsConfig.ApostleHalvedArmor.get()) {
                armor.addTransientModifier(WEAK_ARMOR_MODIFIER);
                toughness.addTransientModifier(WEAK_ARMOR_MODIFIER);
            }
        }
        if (this.obsidianInvul > 0){
            this.level.broadcastEntityEvent(this, (byte) 101);
        } else {
            this.level.broadcastEntityEvent(this, (byte) 102);
        }
        if (this.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING) && MobsConfig.ApocalypseMode.get() && !this.isInNether()) {
            this.netherSpreaderUtil.updateCursors(this.level, this.blockPosition().below(), this.random, true);
            if (this.tickCount >= 100 && this.tickCount % 100 == 0 && !this.isSettingUpSecond()) {
                this.netherSpreaderUtil.clear();
                for (int i = 0; i < 5; i++) {
                    int range = 2;
                    int x = this.getRandom().nextInt(-range, range);
                    int y = this.getRandom().nextInt(-range, range / 2);
                    int z = this.getRandom().nextInt(-range, range);
                    BlockPos blockPos = this.blockPosition().below().offset(x, y, z);
                    this.netherSpreaderUtil.addCursors(blockPos, 10);
                }
            }
        } else {
            this.netherSpreaderUtil.clear();
        }
        // shoot indicator
        Vec3 targetPos = getViewVector(1.0F);
        if (getTarget() != null) {
            LivingEntity target = getTarget();
            targetPos = new Vec3(target.getX(), target.getY(0.5F), target.getZ());
        }
        this.setShootIndicatorEnd(targetPos.toVector3f());
        if (MobsConfig.ApostleShootIndicator.get() && this.isUsingItem() && this.getTicksUsingItem() >= 10 && this.getTicksUsingItem() <= 20) {
            this.setShootIndicatorProgress((this.getTicksUsingItem() - 10F) / 10F);
            if (this.getTicksUsingItem() == 10 && this.level instanceof ServerLevel serverLevel) {
                ColorUtil colorUtil = ColorUtil.DARK_RED;
                serverLevel.sendParticles(new ShootIndicatorParticleOption(this.getId()), this.getX(), this.getY(), this.getZ(), 0, colorUtil.red, colorUtil.green, colorUtil.blue, 1.0F);
            }
        } else {
            this.setShootIndicatorProgress(-1.0F);
        }
    }
    if (this.isSettingUpSecond()){
        this.antiRegen = 0;
        this.antiRegenTotal = 0;
        this.toTeleportTime = 0;
        this.toTeleportPos = null;
        this.setFiring(false);
        this.stopUsingItem();
        if (this.tickCount % 5 == 0) {
            this.heal(0.015625F * this.getMaxHealth());
        }
        for (Entity entity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(3.0D), ALIVE)) {
            if (!MobUtil.areAllies(this, entity)) {
                this.barrier(entity, this);
            }
        }

        if (!this.level.isClientSide){
            this.resetHitTime();
            this.resetCoolDown();
            this.setSpellCycle(0);
            if (this.level instanceof ServerLevel serverLevel){
                ServerParticleUtil.windParticle(serverLevel, ColorUtil.BLACK, 2.0F, 1.5F, this.getId(), this.position());
                ServerParticleUtil.windParticle(serverLevel, ColorUtil.BLACK, 4.0F, 0.5F, this.getId(), this.position());
            }
        }
        if (this.getHealth() >= this.getMaxHealth()){
            if (!this.level.isClientSide){
                ServerLevel serverLevel = (ServerLevel) this.level;
                if (!serverLevel.isThundering()) {
                    serverLevel.setWeatherParameters(0, 6000, true, true);
                }
                for(int k = 0; k < 60; ++k) {
                    float f2 = random.nextFloat() * 4.0F;
                    float f1 = random.nextFloat() * ((float)Math.PI * 2F);
                    double d1 = Mth.cos(f1) * f2;
                    double d2 = 0.01D + random.nextDouble() * 0.5D;
                    double d3 = Mth.sin(f1) * f2;
                    serverLevel.sendParticles(ParticleTypes.FLAME, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.25F);
                }
            }
            this.setSettingUpSecond(false);
            this.setSecondPhase(true);
            this.level.broadcastEntityEvent(this, (byte) 103);
        }
    } else {
        if (this.tickCount % 10 == 0){
            this.prevVecPos = this.position();
        }
        if (this.toTeleportPos != null) {
            if (!MobsConfig.ApostleDelayedTeleport.get()) {
                this.toTeleportPos = null;
            } else {
                ++this.toTeleportTime;
                int time = this.isSecondPhase() ? 20 : 40;
                if (this.toTeleportTime >= time) {
                    this.teleportTo(this.toTeleportPos.x, this.toTeleportPos.y, this.toTeleportPos.z);
                    this.teleportHits();
                    this.toTeleportPos = null;
                } else {
                    if (this.level instanceof ServerLevel serverLevel){
                        ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.SMOKE, this);
                        serverLevel.sendParticles(ParticleTypes.LARGE_SMOKE, this.toTeleportPos.x, this.toTeleportPos.y + 0.25F, this.toTeleportPos.z, 1, 0, 0, 0, 0);
                        ServerParticleUtil.windParticle(serverLevel, ColorUtil.BLACK, 2.0F, 0.25F, -1, this.toTeleportPos);
                        for(int i = 0; i < 16; ++i) {
                            Vec3 vec3 = this.toTeleportPos.add((double)this.getBbWidth() * (2.0D * this.random.nextDouble() - 1.0D) * 0.5F, (double)this.getBbHeight() * this.random.nextDouble(), (double)this.getBbWidth() * (2.0D * this.random.nextDouble() - 1.0D) * 0.5F);
                            serverLevel.sendParticles(new AbsorbTrailParticleOption(vec3, 0xff7700, 10),  this.getRandomX(0.5F), this.getRandomY(), this.getRandomZ(0.5F), 1, 0, 0, 0, 1.0F);
                        }
                    }
                }
            }
        } else {
            if (this.toTeleportTime > 0) {
                this.toTeleportTime = 0;
            }
        }
        if (this.getTarget() != null && !this.isCasting()) {
            if (this.tickCount % 40 == 0){
                if (this.getTarget().isVisuallyCrawling() && !this.getSensing().hasLineOfSight(this.getTarget())){
                    FireBlastTrap fireBlastTrap = new FireBlastTrap(this.level, this.getTarget().getX(), this.getTarget().getY() + 0.25D, this.getTarget().getZ());
                    fireBlastTrap.setOwner(this);
                    fireBlastTrap.setAreaOfEffect(2.0F);
                    this.level.addFreshEntity(fireBlastTrap);
                }
            }
            if (this.isInWall() || (this.prevVecPos != null && this.prevVecPos.distanceTo(this.position()) <= 0.1D)) {
                ++this.stuckTime;
            } else {
                if (this.level.getBlockStates(this.getBoundingBox().inflate(1.0F)).anyMatch(blockState1 -> blockState1.getBlock() instanceof MovingPistonBlock)){
                    this.stuckTime += 20;
                    this.teleport();
                } else {
                    if (this.stuckTime > 0){
                        --this.stuckTime;
                    }
                }
            }
            if (this.toTeleportPos == null) {
                if (this.stuckTime > 50) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.LARGE_SMOKE, this);
                    }
                }
                if (this.stuckTime >= 100) {
                    this.escapeTeleport();
                    this.stuckTime = 0;
                }
            }
        } else {
            this.stuckTime = 0;
        }
    }
    LivingEntity target = this.getTarget();
    if (this.getMainHandItem().isEmpty() && this.isAlive()){
        this.setItemInHand(InteractionHand.MAIN_HAND, new ItemStack(Items.BOW));
    }
    if (this.isSmited()){
        --this.antiRegen;
    }
    if (this.getTornadoCoolDown() > 0){
        --this.tornadoCoolDown;
    }
    if (this.getInfernoCoolDown() > 0){
        --this.infernoCoolDown;
    }
    if (this.getMonolithCoolDown() > 0){
        --this.monolithCoolDown;
    }
    if (this.getDamnedCoolDown() > 0){
        --this.damnedCoolDown;
    }
    if (!this.isSmited()) {
        int count = this.isSecondPhase() ? 200 : 400;
        if (MobsConfig.ApostleQuickerRegen.get()) {
            count = this.isSecondPhase() ? 20 : 40;
        }
        if (this.isInNether()) {
            if (this.Regen()) {
                if (this.tickCount % (count / 2) == 0) {
                    if (this.getHealth() < this.getMaxHealth()) {
                        this.heal(1.0F);
                    }
                }
            } else {
                if (this.tickCount % count == 0) {
                    if (this.getHealth() < this.getMaxHealth()) {
                        this.heal(1.0F);
                    }
                }
            }
        } else {
            if (this.Regen()) {
                if (this.tickCount % count == 0) {
                    if (this.getHealth() < this.getMaxHealth()) {
                        this.heal(1.0F);
                    }
                }
            }
        }
        if (this.obsidianInvul > 0){
            int obsidianRegenTime = this.isSecondPhase() ? 40 : 80;
            if (this.tickCount % obsidianRegenTime == 0) {
                if (this.getHealth() < this.getMaxHealth()) {
                    this.heal(1.0F);
                }
            }
        }
    }
    if (this.isSecondPhase()) {
        if (this.tickCount % 100 == 0 && !this.isDeadOrDying()) {
            if (!this.level.isClientSide){
                ServerLevel ServerLevel = (ServerLevel) this.level;
                ServerLevel.setWeatherParameters(0, 6000, true, true);
            }
        }
        if (this.tickCount % 20 == 0) {
            BlockPos.MutableBlockPos blockPos = new BlockPos.MutableBlockPos(this.getRandomX(0.2), this.getY(), this.getRandomZ(0.2));

            while (blockPos.getY() < this.getY() + 64.0D && !this.level.getBlockState(blockPos).isSolidRender(this.level, blockPos)) {
                blockPos.move(Direction.UP);
            }
            if (blockPos.getY() > this.getY() + 32.0D) {
                NetherMeteor fireball = this.getNetherMeteor();
                fireball.setDangerous(ForgeEventFactory.getMobGriefingEvent(this.level, this) && MobsConfig.ApocalypseMode.get());
                fireball.setPos(blockPos.getX(), blockPos.getY(), blockPos.getZ());
                this.level.addFreshEntity(fireball);
            }
        }
    }
    if (!this.level.isClientSide) {
        if (this.getCoolDown() < this.coolDownLimit()) {
            ++this.coolDown;
        } else {
            if (!this.isSecondPhase() || this.getDamnedCoolDown() <= 0) {
                this.setSpellCycle(0);
            } else {
                this.setSpellCycle(1);
            }
        }
        if (this.getSpellCycle() == 1) {
            if (this.level.getRandom().nextBoolean()) {
                this.setSpellCycle(2);
            } else {
                this.setSpellCycle(3);
            }
        }
    }
    for (LivingEntity living : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(32))){
        if (MobsConfig.ApostleBoilsWater.get()) {
            if (!(living instanceof Cultist) && !(living instanceof Witch) && !(living instanceof IOwned && ((IOwned) living).getTrueOwner() == this)) {
                if (living.isInWater()) {
                    living.hurt(living.damageSources().hotFloor(), 1.0F);
                }
            }
        }
        if (MobsConfig.ApostleConvertsVillagers.get()){
            if (this.level instanceof ServerLevel serverLevel) {
                if (living instanceof AbstractVillager villager) {
                    float chance = 0.25F;
                    if (MobUtil.isDirectlyLooking(this, villager)){
                        chance = 0.75F;
                    }
                    if (this.tickCount % 100 == 0 && this.random.nextFloat() <= chance) {
                        boolean flag = true;
                        if (villager instanceof Villager villager1){
                            if (villager1.getVillagerData().getLevel() >= 5){
                                flag = false;
                            }
                        }
                        if (flag){
                            float chance2 = this.random.nextFloat();
                            Mob mob = EntityType.WITCH.create(serverLevel);
                            if (this.random.nextBoolean()){
                                mob = ModEntityType.WARLOCK.get().create(serverLevel);
                            }
                            if (chance2 <= 0.25F) {
                                mob = ModEntityType.HERETIC.get().create(serverLevel);
                            }
                            if (villager instanceof WanderingTrader){
                                mob = ModEntityType.MAVERICK.get().create(serverLevel);
                                if (this.random.nextBoolean()){
                                    mob = ModEntityType.REPROBATE.get().create(serverLevel);
                                }
                            }
                            if (mob != null) {
                                mob.moveTo(villager.getX(), villager.getY(), villager.getZ(), villager.getYRot(), villager.getXRot());
                                ForgeEventFactory.onFinalizeSpawn(mob, serverLevel, serverLevel.getCurrentDifficultyAt(mob.blockPosition()), MobSpawnType.CONVERSION, null, null);
                                mob.setNoAi(villager.isNoAi());
                                if (villager.hasCustomName()) {
                                    mob.setCustomName(villager.getCustomName());
                                    mob.setCustomNameVisible(villager.isCustomNameVisible());
                                }

                                mob.setPersistenceRequired();
                                net.minecraftforge.event.ForgeEventFactory.onLivingConvert(villager, mob);
                                serverLevel.addFreshEntityWithPassengers(mob);
                                if (villager instanceof Villager villager1) {
                                    MobUtil.releaseAllPois(villager1);
                                }
                                villager.discard();
                            }
                        }
                    }
                }
            }
        }
        if (living instanceof Player player){
            player.getAbilities().flying &= player.isCreative();
        }
    }
    if (target == null){
        if (this.getHitTimes() > 0) {
            this.resetHitTime();
        }
        boolean flag = false;
        if (this.killedPlayer){
            --this.lastKilledPlayer;
            if (this.lastKilledPlayer == 0) {
                this.remove(RemovalReason.DISCARDED);
            }
        } else {
            flag = true;
        }
        if (flag) {
            for (Player player : this.level.getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(256), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
                if (!MobUtil.areAllies(this, player)) {
                    this.setTarget(player);
                }
            }
        }
        for (Mob mob : this.level.getEntitiesOfClass(Mob.class, this.getBoundingBox().inflate(this.getAttributeValue(Attributes.FOLLOW_RANGE)), EntitySelector.LIVING_ENTITY_STILL_ALIVE)){
            if (mob.getTarget() == this && this.getTarget() == null){
                this.setTarget(mob);
            }
        }
    } else {
        if (this.killedPlayer){
            this.killedPlayer = false;
            this.lastKilledPlayer = 200;
        }
        if (this.tickCount % 100 == 0 && !this.isSettingUpSecond()){
            if (!this.level.isClientSide){
                if (this.isInNether()) {
                    for (ZombifiedPiglin zombifiedPiglin : this.level.getEntitiesOfClass(ZombifiedPiglin.class, this.getBoundingBox().inflate(16))){
                        if (zombifiedPiglin.getTarget() != this.getTarget()){
                            zombifiedPiglin.setTarget(this.getTarget());
                        }
                    }
                }
            }
        }
        if (this.isSecondPhase()) {
            if (this.getHealth() <= this.getMaxHealth() / 8){
                if (this.tickCount % 100 == 0){
                    this.teleport();
                }
            }
            if (MobUtil.isInRain(target)) {
                int count = 100 * (this.random.nextInt(5) + 1);
                if (this.tickCount % count == 0) {
                    BlockPos.MutableBlockPos blockpos$mutable = new BlockPos.MutableBlockPos(target.getX(), target.getY(), target.getZ());

                    while (blockpos$mutable.getY() > this.level.getMinBuildHeight() && !this.level.getBlockState(blockpos$mutable).blocksMotion()) {
                        blockpos$mutable.move(Direction.DOWN);
                    }

                    LightningTrap lightningTrap = new LightningTrap(this.level, blockpos$mutable.getX(), blockpos$mutable.getY() + 1, blockpos$mutable.getZ());
                    lightningTrap.setOwner(this);
                    lightningTrap.setDuration(50);
                    this.level.addFreshEntity(lightningTrap);
                }
            }
        }
        if ((target.distanceToSqr(this) > 1024 || !this.getSensing().hasLineOfSight(target)) && target.onGround() && !this.isSettingUpSecond()){
            this.teleportTowards(target);
        }
    }
    if (this.isInWater() || this.isInLava() || this.isInFluidType() || this.isInWall()){
        this.teleport();
    }
    if (this.isInNether()){
        if (target != null){
            target.addEffect(new MobEffectInstance(GoetyEffects.BURN_HEX.get(), 100));
        }
    }
}

public void aiStep() {
    super.aiStep();

    Vec3 vector3d = this.getDeltaMovement();
    if (!this.onGround()&& vector3d.y < 0.0D && !this.isNoGravity()) {
        this.setDeltaMovement(vector3d.multiply(1.0D, 0.6D, 1.0D));
    }
    if (this.getVoidShrine() != null) {
        try {
            this.getVoidShrine().setCoolTick(0);
        } catch (NullPointerException ignored) {
        }
    }
    if (this.swingCool > 0) {
        --this.swingCool;
    }
    if (this.swingComboCool > 0) {
        --this.swingComboCool;
    }
    if (this.rapidSwingCool > 0) {
        --this.rapidSwingCool;
    }
    if (this.chargeCool > 0) {
        --this.chargeCool;
    }
    if (this.spell1Cool > 0) {
        --this.spell1Cool;
    }
    if (this.spell2Cool > 0) {
        --this.spell2Cool;
    }
    if (this.spell3Cool > 0) {
        --this.spell3Cool;
    }
    if (this.lifeStealCool > 0) {
        --this.lifeStealCool;
    }
    if (this.groundPoundCool > 0) {
        --this.groundPoundCool;
    }
    if (this.backAwayCool > 0) {
        --this.backAwayCool;
    }
    if (this.slicingCool > 0) {
        --this.slicingCool;
    }
    if (this.moddedInvul > 0){
        --this.moddedInvul;
    }

    if (!this.level.isClientSide) {
        if (this.getBoundPos() == null) {
            if (this.tickCount % 100 == 0 || this.lastSafePosition == null) {
                BlockPos blockPos = this.getSafeGround();
                if (blockPos.getY() > 1) {
                    this.lastSafePosition = blockPos;
                }
            }
        }
        float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
        if (this.isAttacking()) {
            ++this.attackTick;
        } else {
            this.attackTick = 0;
        }
        if (this.isCurrentAnimation(SWING)) {
            if (this.attackTick == 13) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SWING.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 18) {
                CameraShake.cameraShake(this.level, this.position(), 15.0F, 0.1F, 0, 10);
                this.pushOn(1.35F, 1.35F);
                this.areaAttack(6.5F, 6, 90, damage, 60, false);
            }
        }
        if (this.isCurrentAnimation(SWING_COMBO)) {
            if (this.attackTick == 13 || this.attackTick == 31) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SWING.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 18 || this.attackTick == 34) {
                CameraShake.cameraShake(this.level, this.position(), 15.0F, 0.1F, 0, 10);
                this.pushOn(1.35F, 1.35F);
                this.areaAttack(6.5F, 6, 90, damage, 60, false);
            }
        }
        if (this.isCurrentAnimation(SWING_COMBO_TRIPLE)) {
            if (this.attackTick == 13 || this.attackTick == 31 || this.attackTick == 52) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SWING.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 18 || this.attackTick == 34) {
                CameraShake.cameraShake(this.level, this.position(), 15.0F, 0.1F, 0, 10);
                this.pushOn(1.35F, 1.35F);
                this.areaAttack(6.5F, 6, 90, damage, 60, false);
            }
            if (this.attackTick == 56) {
                CameraShake.cameraShake(this.level, this.position(), 15.0F, 0.1F, 0, 10);
                this.areaAttack(6.5F, 8, 100, damage, 100, false);
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SMASH.get(), 3.0F, this.getVoicePitch() * 0.5F);
                this.playSound(SoundEvents.GENERIC_EXPLODE, 3.0F, this.getVoicePitch() * 0.5F);
                this.playSound(SoundEvents.TOTEM_USE, 3.0F, this.getVoicePitch() * 0.5F);
            }
            for (int i = 56; i < 66; ++i) {
                if (this.attackTick == i) {
                    int l = i - 56;
                    this.outwardTremor(l, 0.0F, damage);
                    this.outwardTremor(l, 0.5F, damage);
                    this.outwardTremor(l, -0.5F, damage);
                    if (l >= 1) {
                        this.outwardTremor(l, 1.5F, damage);
                        this.outwardTremor(l, -1.5F, damage);
                    }
                    if (l >= 2) {
                        this.outwardTremor(l, 2.5F, damage);
                        this.outwardTremor(l, -2.5F, damage);
                    }
                    if (l >= 3) {
                        this.outwardTremor(l, 3.5F, damage);
                        this.outwardTremor(l, -3.5F, damage);
                    }
                    if (l >= 4) {
                        this.outwardTremor(l, 4.5F, damage);
                        this.outwardTremor(l, -4.5F, damage);
                    }
                    if (l >= 5) {
                        this.outwardTremor(l, 5.5F, damage);
                        this.outwardTremor(l, -5.5F, damage);
                    }
                    if (l >= 6) {
                        this.outwardTremor(l, 6.5F, damage);
                        this.outwardTremor(l, -6.5F, damage);
                    }
                    if (l >= 7) {
                        this.outwardTremor(l, 7.5F, damage);
                        this.outwardTremor(l, -7.5F, damage);
                    }

                }
            }
        }
        if (this.isCurrentAnimation(RAPID_SWING)) {
            if (this.attackTick == 10 || this.attackTick == 20 || this.attackTick == 28 || this.attackTick == 36 || this.attackTick == 44) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SWING.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick >= 13 && this.attackTick < 54) {
                if (this.getTarget() != null) {
                    this.lookAt(this.getTarget(), 100.0F, 100.0F);
                    this.getLookControl().setLookAt(this.getTarget(), 100.0F, 100.0F);
                }
                if (this.attackTick == 16 || this.attackTick == 24 || this.attackTick == 32 || this.attackTick == 40 || this.attackTick == 48) {
                    this.areaAttack(6.5F, 6, 120, damage, 60, false);
                    VoidSlash voidSlash = new VoidSlash(this.level, this);
                    voidSlash.setPos(this.getEyePosition());
                    voidSlash.setVoidLevel(3);
                    voidSlash.slash(this.getLookAngle(), 1.0F);
                    voidSlash.setDamage(damage);
                    this.level.addFreshEntity(voidSlash);
                }
            }
        }
        if (this.isCurrentAnimation(CHARGE)) {
            if (this.attackTick == 18) {
                ModNetwork.sentToTrackingEntityAndPlayer(this, new SPlayFollowSoundPacket(this, ModSounds.VHOE_CHARGE.get(), 3.0F, this.getVoicePitch(), false));
                float f1 = (float) Math.cos(Math.toRadians(this.getYRot() + 90));
                float f2 = (float) Math.sin(Math.toRadians(this.getYRot() + 90));
                if (this.getTarget() != null) {
                    float r = this.distanceTo(this.getTarget());
                    r = Mth.clamp(r, 0.0F, 10.0F);
                    this.push(f1 * 0.9F * r, 0, f2 * 0.9F * r);
                } else {
                    this.push(f1 * 3.0F, 0, f2 * 3.0F);
                }
            }
            if (this.attackTick >= 18 && this.attackTick < 27) {
                if (this.level instanceof ServerLevel serverLevel) {
                    int width = serverLevel.getRandom().nextIntBetweenInclusive(1, 4);
                    float height = serverLevel.getRandom().nextFloat() * 0.5F;
                    Vec3 vec3 = this.getEyePosition().offsetRandom(serverLevel.getRandom(), 2.0F);
                    Vec3 angle = this.getLookAngle().multiply(-1.0D, 1.0D, -1.0D);
                    serverLevel.sendParticles(new WindBlowParticleOption(new ColorUtil(ChatFormatting.LIGHT_PURPLE), width, height), vec3.x, vec3.y, vec3.z, 0, angle.x, angle.y, angle.z, 1.0F);
                }
                for (LivingEntity entityHit : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.2D))) {
                    if (!MobUtil.areAllies(this, entityHit)) {
                        boolean flag = entityHit.hurt(this.damageSources().mobAttack(this), damage + (entityHit.getMaxHealth() * AttributesConfig.EnderKeeperHPPercentDamage.get().floatValue()));
                        if (entityHit.isDamageSourceBlocked(this.damageSources().mobAttack(this))) {
                            MobUtil.disableShield(entityHit, 100);
                        }
                        if (flag) {
                            this.applyVoidTouched(entityHit);
                            double d0 = entityHit.getX() - this.getX();
                            double d1 = entityHit.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            entityHit.push(d0 / d2 * 2.5D, 0.18D, d1 / d2 * 2.2D);
                        }
                    }
                }
            }
        }
        if (this.isCurrentAnimation(SPELL_1)) {
            if (this.attackTick >= 10 && this.attackTick < 35) {
                int tickRate = MobUtil.healthIsHalved(this) ? 2 : 5;
                if (this.attackTick % tickRate == 0) {
                    VoidShock voidShock = new VoidShock(this, this.getTarget(), this.level);
                    voidShock.setPos(this.position().add(this.level.getRandom().nextInt(-3, 3), 4.0D, this.level.getRandom().nextInt(-3, 3)));
                    voidShock.setPower(Vec3.ZERO, 10);
                    voidShock.setBaseDamage(damage);
                    this.level.addFreshEntity(voidShock);
                    this.playSound(ModSounds.TELEPORT_ORB_THROW.get(), 2.0F, this.getVoicePitch());
                }
            }
            if (this.attackTick % 10 == 0 && this.attackTick < 35) {
                this.playSound(ModSounds.SWIRLINGS.get(), 1.5F, this.getVoicePitch() - 0.25F);
            }
        }
        if (this.isCurrentAnimation(SPELL_2)) {
            if (this.attackTick > 10 && this.attackTick <= 28) {
                if (this.level instanceof ServerLevel serverLevel) {
                    ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_PURPLE);
                    ServerParticleUtil.gatheringParticles(new GatherTrailParticleOption(colorUtil, this.position().add(0, 8, 0)), this, serverLevel, 2);
                }
            }
            if (this.attackTick == 43) {
                VoidShockBomb voidShock = new VoidShockBomb(this, this.level);
                voidShock.setPos(this.position().add(0, 6.0D, 0));
                voidShock.setBaseDamage(damage);
                voidShock.shootFromRotation(this, this.getXRot(), this.getYRot(), 0.0F, 1.0F, 1.0F);
                this.level.addFreshEntity(voidShock);
                this.playSound(ModSounds.HEAVY_WOOSH.get(), 3.0F, this.getVoicePitch());
                this.playSound(ModSounds.TELEPORT_ORB_THROW.get(), 3.0F, this.getVoicePitch() - 0.5F);
                if (MobUtil.healthIsHalved(this)) {
                    for (int i = 0; i < 2; ++i){
                        VoidShockBomb voidShock2 = new VoidShockBomb(this, this.level);
                        voidShock2.setPos(this.position().add(0, 6.0D, 0));
                        voidShock2.setBaseDamage(damage);
                        voidShock2.shootFromRotation(this, this.getXRot(), this.getYRot(), 0.0F, 0.5F + this.level.getRandom().nextFloat(), 8.0F);
                        this.level.addFreshEntity(voidShock2);
                    }
                }
            }
        }
        if (this.isCurrentAnimation(SPELL_3)) {
            if (this.attackTick >= 20 && this.attackTick < 60) {
                int amount = MobUtil.healthIsHalved(this) ? 2 : 1;
                for (int i = 0; i < amount; ++i) {
                    BlockPos blockPos = this.blockPosition();
                    if (this.attackTick < 40 && this.getTarget() != null) {
                        blockPos = this.getTarget().blockPosition();
                    }
                    BlockPos blockPos1 = blockPos.offset(this.level.getRandom().nextInt(-16, 16), 0, this.level.getRandom().nextInt(-16, 16));
                    BlockPos blockPos2 = blockPos.offset(this.level.getRandom().nextInt(-16, 16), 0, this.level.getRandom().nextInt(-16, 16));
                    Vec3 vec3 = Vec3.atBottomCenterOf(blockPos1);
                    Vec3 vec32 = Vec3.atBottomCenterOf(blockPos2);
                    VoidLightningTrap trap = new VoidLightningTrap(this.level, vec3.x, vec3.y, vec3.z);
                    trap.setOwner(this);
                    trap.setDuration(40);
                    trap.setDamage(damage);
                    if (!this.level.getEntitiesOfClass(VoidLightningTrap.class, new AABB(blockPos1)).isEmpty()) {
                        trap.setPos(vec32.x(), vec32.y(), vec32.z());
                    }
                    MobUtil.moveDownToGround(trap);
                    this.level.addFreshEntity(trap);
                }
            }
        }
        if (this.isCurrentAnimation(LIFE_STEAL)) {
            double radius = this.getBoundingBox().getSize() * 2.0F;
            if (this.attackTick < 40) {
                if (this.level instanceof ServerLevel serverWorld) {
                    ServerParticleUtil.gatheringParticles(ParticleTypes.PORTAL, this, serverWorld, 20);
                }
            }
            if (this.attackTick == 40) {
                this.playSound(ModSounds.VHOE_PINWHEEL.get(), 2.0F, 0.75F);
            }
            if (this.attackTick == 60) {
                if (this.level instanceof ServerLevel serverWorld) {
                    ColorUtil colorUtil = new ColorUtil(ChatFormatting.LIGHT_PURPLE);
                    serverWorld.sendParticles(new AoEParticleOption(0, 4.0F / 60.0F, 4.0F, 60), this.getX(), this.getY() + 0.1F, this.getZ(), 0, colorUtil.red, colorUtil.green, colorUtil.blue, 1.0F);
                }
            }
            if (this.attackTick >= 40 && this.attackTick < 120) {
                this.level.broadcastEntityEvent(this, (byte) 6);
                if (this.level instanceof ServerLevel serverWorld) {
                    ColorUtil colorUtil = new ColorUtil(ChatFormatting.LIGHT_PURPLE);
                    ServerParticleUtil.gatheringParticles(new GatherTrailParticleOption(colorUtil, this.position().add(0, 1, 0)), this, serverWorld, 4);
                    ServerParticleUtil.windParticle(serverWorld, colorUtil, (float) radius, 1.0F, this.getId(), this.position());
                    ServerParticleUtil.gatheringParticles(ParticleTypes.PORTAL, this, serverWorld, 20);
                    if (this.attackTick % 5 == 0) {
                        serverWorld.sendParticles(new ReverseShockwaveParticleOption(colorUtil, 20.0F, 1.0F, 0, true), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0, 0, 0, 0.5F);
                    }
                }
                if (MobUtil.healthIsHalved(this)) {
                    if (this.attackTick % 10 == 0) {
                        VoidShock voidShock = new VoidShock(this, this.getTarget(), this.level);
                        voidShock.setPos(this.position().add(0.0D, 4.0D, 0.0D));
                        voidShock.setPower(Vec3.ZERO, 10);
                        voidShock.setBaseDamage(damage);
                        this.level.addFreshEntity(voidShock);
                        this.playSound(ModSounds.TELEPORT_ORB_THROW.get(), 2.0F, this.getVoicePitch());
                    }
                }
                for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(20.0F))) {
                    if (!MobUtil.areAllies(this, livingEntity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.isAlive()) {
                        Vec3 vec30 = this.position().subtract(livingEntity.position());
                        vec30 = vec30.normalize();
                        double scale = (this.attackTick - 40) / 80.0D;
                        vec30 = vec30.scale(scale);
                        vec30 = vec30.scale(0.2D);
                        Vec3 add = livingEntity.getDeltaMovement().add(vec30);
                        MobUtil.drag(livingEntity, add.x, add.y, add.z, MobUtil.healthIsHalved(this) ? 0.0D : 0.5D);
                        if (this.distanceTo(livingEntity) < radius) {
                            float lifeSteal = ((livingEntity.getMaxHealth() - livingEntity.getHealth()) * 0.25F) + 1.0F;
                            if (livingEntity.hurt(this.damageSources().indirectMagic(this, this), lifeSteal)) {
                                if (this.level instanceof ServerLevel serverLevel) {
                                    ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_PURPLE);
                                    Vec3 vec3 = new Vec3(livingEntity.getX(), livingEntity.getY() + (livingEntity.getBbHeight() / 2.0F), livingEntity.getZ());
                                    Vec3 vector3d1 = new Vec3(this.getRandomX(1.0F), this.getEyeY(), this.getRandomZ(1.0F));
                                    serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                                    for (int i = 0; i < 8; ++i){
                                        vec3 = new Vec3(livingEntity.getRandomX(1.0F), livingEntity.getRandomY(), livingEntity.getRandomZ(1.0F));
                                        serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 11141290, 10), vec3.x, vec3.y, vec3.z, 1, 0.0, 0.0, 0.0, 0.0);
                                    }
                                }
                                this.heal(lifeSteal);
                                this.playSound(ModSounds.SOUL_EAT.get(), 2.0F, 1.0F);
                            }
                            Vec3 vec3 = vec30.reverse();
                            vec3 = vec3.normalize();
                            vec3 = vec3.scale(2.0D);
                            MobUtil.drag(livingEntity, vec3.x, vec3.y, vec3.z, MobUtil.healthIsHalved(this) ? 0.0D : 0.5D);
                        }
                    }
                }
            }
            if (this.attackTick == 114) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SWING.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 119) {
                CameraShake.cameraShake(this.level, this.position(), 15.0F, 0.1F, 0, 10);
                this.areaAttack(6.5F, 6, 90, damage, 60, false);
            }
            if (this.attackTick == 120) {
                if (this.level instanceof ServerLevel serverLevel) {
                    new SpellExplosion(serverLevel, this, this.damageSources().indirectMagic(this, this), this.getX(), this.getY(), this.getZ(), 4.0F, damage) {
                        @Override
                        public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                            super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                            if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target)) {
                                if (target instanceof LivingEntity livingEntity && !livingEntity.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
                                    livingEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(3), 2, false, true));
                                }
                            }
                        }
                    };
                    ColorUtil colorUtil = new ColorUtil(0xb103d8);
                    serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 4.0F, 1), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 8.0F, 1), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 4.0F, 1), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 8.0F, 1), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    DustCloudParticleOption cloudParticleOptions = new DustCloudParticleOption(new Vector3f(Vec3.fromRGB24(16733695).toVector3f()), 1.0F);
                    for (int i = 0; i < 2; ++i) {
                        ServerParticleUtil.circularParticles(serverLevel, cloudParticleOptions, this.getX(), this.getY() + 0.25D, this.getZ(), 0, 0.14D, 0, 3.5F);
                    }
                    this.playSound(ModSounds.FUNGUS_EXPLOSION.get(), 3.0F, 0.6F + (serverLevel.getRandom().nextFloat() * 0.4F));
                }
            }
        }
        if (this.isCurrentAnimation(GROUND_POUND) || this.isCurrentAnimation(GROUND_POUND_SPIN)) {
            if (this.hidingTime >= 10) {
                this.stopHide();
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SMASH.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 5) {
                if (this.level instanceof ServerLevel serverLevel) {
                    ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_PURPLE);
                    serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, this.groundPoundSize, 1), this.getX(), BlockFinder.moveDownToGround(this), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                }
                CameraShake.cameraShake(this.level, this.position(), 25.0F, 0.2F, 0, 20);
            }

            for (int i = 5; i < 5 + this.groundPoundSize; ++i) {
                if (this.attackTick == i) {
                    this.surroundTremor(i - 5, 3, 0.0F, damage);
                }
            }

            if (this.isCurrentAnimation(GROUND_POUND_SPIN)) {
                if (this.attackTick == 33) {
                    this.pushOn(3.0F, 3.0F);
                }
                if (this.attackTick == 38) {
                    this.playSound(ModSounds.SWIRLINGS.get(), 2.0F, this.getVoicePitch() - 0.25F);
                }
                if (this.attackTick >= 38 && this.attackTick < 58) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        serverLevel.sendParticles(new WindParticleOption(new ColorUtil(ChatFormatting.DARK_PURPLE), 4.5F, 1.5F, this.getId()), this.getX(), this.getY(), this.getZ(), 1, 0, 0, 0, 1.0F);
                        serverLevel.sendParticles(new WindParticleOption(new ColorUtil(ChatFormatting.DARK_PURPLE), 6.0F, 1.0F, this.getId()), this.getX(), this.getY(), this.getZ(), 1, 0, 0, 0, 1.0F);
                        serverLevel.sendParticles(new WindParticleOption(new ColorUtil(ChatFormatting.DARK_PURPLE), 4.5F, 0.5F, this.getId()), this.getX(), this.getY(), this.getZ(), 1, 0, 0, 0, 1.0F);
                    }
                    for (LivingEntity entityHit : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(6.0D, 0.0D, 6.0D))) {
                        if (!MobUtil.areAllies(this, entityHit)) {
                            boolean flag = entityHit.hurt(this.damageSources().mobAttack(this), damage + (entityHit.getMaxHealth() * AttributesConfig.EnderKeeperHPPercentDamage.get().floatValue()));
                            if (entityHit.isDamageSourceBlocked(this.damageSources().mobAttack(this))) {
                                MobUtil.disableShield(entityHit, 100);
                            }
                            if (flag) {
                                this.applyVoidTouched(entityHit);
                                double d0 = entityHit.getX() - this.getX();
                                double d1 = entityHit.getZ() - this.getZ();
                                double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                                entityHit.push(d0 / d2 * 2.5D, 0.18D, d1 / d2 * 2.2D);
                            }
                        }
                    }
                }
            }
        }
        if (this.isCurrentAnimation(BACK_AWAY)) {
            if (this.attackTick == 2) {
                float speed = -2.5F;
                float dodgeYaw = (float) Math.toRadians(this.getYRot() + 90);
                Vec3 vec3 = this.getDeltaMovement().add(speed * Math.cos(dodgeYaw), 0, speed * Math.sin(dodgeYaw));
                this.playSound(SoundEvents.PLAYER_ATTACK_CRIT, 2.0F, 1.0F);
                this.setDeltaMovement(vec3.x, 0.4F, vec3.z);
            }
        }
        if (this.isCurrentAnimation(SLICE_START)) {
            int hideTime = MobUtil.healthIsHalved(this) ? 20 : 40;
            if (this.getTarget() == null || this.getTarget().isDeadOrDying()) {
                this.stopHide();
                this.setAnimationState(IDLE);
            } else if (this.hidingTime >= hideTime) {
                this.stopHide();
                this.setAnimationState(SLICE_1);
            }
        }
        if (this.isCurrentAnimation(SLICE_1) || this.isCurrentAnimation(SLICE_2)) {
            if (this.attackTick == 1) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_WINDUP.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 5) {
                this.playSound(ModSounds.OBSIDIAN_CLAYMORE_SWING.get(), 2.0F, this.getVoicePitch());
            }
            if (this.attackTick == 10) {
                float pushPower = MobUtil.healthIsHalved(this) ? 3.0F : 1.35F;
                this.pushOn(pushPower, pushPower);
                this.areaAttack(6.5F, 5, 90, damage, 60, false);
            }
            if (this.attackTick >= 24) {
                this.startHide();
                if (this.getTarget() != null) {
                    this.teleportTowards(this.getTarget(), 2.0F);
                }
            }
            if (this.getTarget() == null || this.getTarget().isDeadOrDying()) {
                this.stopHide();
                this.setAnimationState(IDLE);
            }
        }
    }
    if (this.getTarget() != null) {
        this.getTarget().addEffect(new MobEffectInstance(GoetyEffects.PLUNGE.get(), 5, 0, false, false));
        if (this.getTarget() instanceof Player player) {
            player.getAbilities().flying &= player.isCreative();
        }
    }
}

public boolean applyEffectTick(ServerLevel level, LivingEntity entity, int amplifier) {
    if (entity instanceof Player player && entity.isAlive()) {
        VampirePlayer.get(player).requestNaturalArmorUpdate();
    }
    return true;
}

public static void applyModifier(@NotNull Player player, @NotNull Holder<Attribute> attribute, String name, int level, int lcap, double max, double type, AttributeModifier.@NotNull Operation operation, boolean evenIntOnly) {
    double m = calculateModifierValue(level, lcap, max, type);
    AttributeInstance instance = player.getAttribute(attribute);
    if (instance != null) {
        instance.removeModifier(ID);
        if (evenIntOnly) {
            m = Math.round(m / 2) * 2;
        }
        instance.addPermanentModifier(new AttributeModifier(ID, m, operation));
    } else if (SharedConstants.IS_RUNNING_IN_IDE) {
        throw new IllegalStateException("Attribute " + attribute + " not found for player " + player);
    }
}

public void addBalanceModifier(String key, Consumer<? extends Conf> modifier) {
    if (balanceModifications.put(key, modifier) != null) {
        if (VampirismMod.inDev) LOGGER.warn("Overriding existing config modifier for '{}'", key);
    }
}

public float getCooldownPercentage(Holder<? extends IAction<T>> action) {
    if (cooldownTimers.containsKey(action)) {
        return -cooldownTimers.getInt(action) / (float) expectedCooldownTimes.getInt(action);
    }
    return 0;
}

public <T extends BalanceBuilder.Conf> void addBalanceModification(String key, Consumer<T> modifier) {
    if (this.balanceBuilder == null) {
        throw new IllegalStateException("Must add balance modifications during mod construction");
    }
    this.balanceBuilder.addBalanceModifier(key, modifier);
}

public void onReActivatedServer(IVampirePlayer vampire) {
    setModifier(vampire.asEntity(), true);
    if (!((VampirePlayer) vampire).getSkillProperties().bat) {
        updatePlayer((VampirePlayer) vampire, true);
    }
}

public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
    super.setPlacedBy(level, pos, state, placer, stack);
    BlockEntity tile = level.getBlockEntity(pos);
    if (placer instanceof Player && tile instanceof AlchemicalCauldronBlockEntity cauldronBlockEntity) {
        cauldronBlockEntity.setOwnerID((Player) placer);
    }
}

public int getCooldown(IVampirePlayer player) {
    int cooldown = ModConfig.balance().vaDarkBloodProjectileCooldown.get() * 20;
    if (player.getRefinementHandler().isRefinementEquipped(ModRefinements.DARK_BLOOD_PROJECTILE_AOE)) {
        cooldown *= ModConfig.balance().vrDarkBloodProjectileAOECooldownMod.get();
    }
    return cooldown;
}

public int getDuration(@NotNull IVampirePlayer player) {
    int duration = 20 * (ModConfig.balance().vaSunscreenDuration.get());
    if (player.getRefinementHandler().isRefinementEquipped(ModRefinements.SUN_SCREEN)) {
        duration *= ModConfig.balance().vrSunscreenDurationMod.get();
    }
    return duration;
}

public int getCooldown(@NotNull IVampirePlayer player) {
    int cooldown = ModConfig.balance().vaTeleportCooldown.get() * 20;
    if (player.getRefinementHandler().isRefinementEquipped(ModRefinements.TELEPORT_DISTANCE)) {
        cooldown = (int)(cooldown * ModConfig.balance().vrTeleportCooldownMod.get());
    }
    return cooldown;
}

private void removeAttributes(Holder<IRefinement> refinement) {
    Holder<Attribute> attribute = refinement.value().getAttribute();
    if (attribute == null) return;

    AttributeInstance instance = this.player.getAttribute(attribute);
    if (instance == null) return;
    instance.removeModifier(refinement.unwrapKey().orElseThrow().identifier());
}

public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
    super.setPlacedBy(level, pos, state, placer, stack);

    BlockEntity tile = level.getBlockEntity(pos);
    if (tile instanceof VaporStillBlockEntity potionTableBlockEntity && placer instanceof Player player) {
        potionTableBlockEntity.setOwnerID(player);
    }
}

public void removeAttributeModifiers(AttributeMap attributeMap) {
    for (Map.Entry<Holder<Attribute>, AttributeTemplate> entry : this.attributeModifiers.entrySet()) {
        AttributeInstance attributeinstance = attributeMap.getInstance(entry.getKey());
        if (attributeinstance != null) {
            attributeinstance.removeModifier(entry.getValue().id());
        }
    }
}

public boolean test(@NotNull LootContext context) {
    Entity player = context.getOptionalParameter(target.contextParam());
    if (player instanceof Player) {
        ItemStack active = ((Player) player).getMainHandItem();
        return !active.isEmpty() && active.getItem() instanceof StakeItem;
    }
    return false;
}

public void resetTimer(Holder<? extends IAction<T>> action) {
    if (action.value() instanceof ILastingAction<T>) {
        //noinspection unchecked
        deactivateAction((Holder<ILastingAction<T>>) action, true);
    }
    this.cooldownTimers.removeInt(action);
    this.expectedCooldownTimes.removeInt(action);
    sync();
}

public final void onDisable(T player) {
    removeAttributesModifiersFromEntity(player.asEntity());
    player.getActionHandler().relockActionHolder(getActions());
    if (IFaction.is(player.getFaction(), this.factions())) {
        onDisabled(player);
    } else {
        throw new IllegalArgumentException("Faction player instance is of wrong class " + player.getClass() + " for action " + FactionRegistries.SKILL.get().getKey(this));
    }
}

private void removeAttributesModifiersFromEntity(Player player) {
    for (Map.Entry<Holder<Attribute>, SkillAttributeHolder> entry : this.attributeModifierMap.entrySet()) {
        AttributeInstance attribute = player.getAttribute(entry.getKey());

        if (attribute != null) {
            attribute.removeModifier(entry.getValue().skillId());
        }
    }
}

public void addAttributeModifiers(AttributeMap attributeMap, int amplifier) {
    for (Map.Entry<Holder<Attribute>, AttributeTemplate> entry : this.attributeModifiers.entrySet()) {
        AttributeInstance attributeinstance = attributeMap.getInstance(entry.getKey());
        if (attributeinstance != null) {
            attributeinstance.removeModifier(entry.getValue().id());
            attributeinstance.addPermanentModifier(entry.getValue().create(amplifier));
        }
    }
}

public void resetTimers() {
    for (Holder<? extends ILastingAction<T>> action : activeTimers.keySet()) {
        deactivateAction(action, true);
    }
    activeTimers.clear();
    cooldownTimers.clear();
    expectedCooldownTimes.clear();
    expectedDurations.clear();
    sync();
}

public final void onEnable(T player) {
    applyAttributesModifiersToEntity(player.asEntity());

    if (IFaction.is(player.getFaction(), this.factions())) {
        player.getActionHandler().unlockActionHolder(getActions());
        onEnabled(player);
    } else {
        throw new IllegalArgumentException("skill is not allowed for player for skill " + FactionRegistries.SKILL.get().getKey(this));
    }
}

private void applyAttributesModifiersToEntity(Player player) {
    for (Map.Entry<Holder<Attribute>, SkillAttributeHolder> entry : this.attributeModifierMap.entrySet()) {
        AttributeInstance instance = player.getAttribute(entry.getKey());

        if (instance != null) {
            AttributeModifier attributeModifier = entry.getValue().create();
            instance.addOrReplacePermanentModifier(attributeModifier);
        }
    }
}

public void onDeactivated(IVampirePlayer vampire) {
    Player player = vampire.asEntity();
    setModifier(player, false);
    if (!player.onGround()) {
        player.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, 20, 100, false, false));
    }
    //player.addPotionEffect(new PotionEffect(MobEffects.REGENERATION, 20, 0, false, false));
    updatePlayer((VampirePlayer) vampire, false);
    player.removeData(ModAttachments.VAMPIRE_BAT);
}

public void updateItems() {
    for (IRefinementItem.AccessorySlotType value : IRefinementItem.AccessorySlotType.values()) {
        var refinements = this.refinementSets.remove(value);
        if (refinements != null) {
            refinements.forEach(this::removeAttributes);
        }
    }

    applyAttributes();
    sync();
}

public void setItem(int slot, ItemStack stack) {
    ItemStack itemstack = this.items.get(slot);
    boolean flag = !stack.isEmpty() && ItemStack.isSameItemSameComponents(itemstack, stack);
    this.items.set(slot, stack);
    stack.limitSize(this.getMaxStackSize(stack));
    if (slot == 0 && !flag && this.level instanceof ServerLevel serverlevel) {
        this.totalCookingTime = getTotalCookTime(serverlevel, this);
        this.cookingTimer = 0;
        this.setChanged();
    }
}

public ActionsBuilder<E> useActions(@Nullable Supplier<Integer> cooldownSupplier) {
    this.memories.add(ModMemoryTypes.ACTION_ACTIVE.get());
    this.memories.add(ModMemoryTypes.ACTION_COOLDOWN.get());
    this.sensors.add(ModSensors.ACTION_SENSOR.get());

    if (cooldownSupplier != null) {
        this.actionBuilders.cooldown(cooldownSupplier);
    }

    return this.actionBuilders;
}

public void onActivatedClient(IVampirePlayer vampire) {
    if (!((VampirePlayer) vampire).getSkillProperties().bat) {
        updatePlayer((VampirePlayer) vampire, true);
