public static boolean reduceAppliedOilDuration(@NotNull ItemStack stack) {
    return AppliedOilContent.getAppliedOil(stack).map(appliedOil -> {
        int newDuration = appliedOil.duration() - appliedOil.oil().value().getDurationReduction();
        if (newDuration > 0) {
            AppliedOilContent.apply(stack, appliedOil.oil(), newDuration);
            return false;
        } else {
            AppliedOilContent.remove(stack);
            return true;
        }
    }).orElse(true);
}

public static boolean reduceAppliedOilDuration(@NotNull ItemStack stack, IApplicableOil oil, int durationReduction) {
    return AppliedOilContent.getAppliedOil(stack).filter(s -> s.oil().value() == oil).map(appliedOil -> {
        int newDuration = appliedOil.duration() - durationReduction;
        if (newDuration > 0) {
            AppliedOilContent.apply(stack, appliedOil.oil(), newDuration);
            return false;
        } else {
            AppliedOilContent.remove(stack);
            return true;
        }
    }).orElse(true);
}

public void preRemoveSideEffects(BlockPos pos, BlockState state) {
    super.preRemoveSideEffects(pos, state);
    // Removes the slowdown if the altar is broken. Falls back to PlayerList lookup in case this.player hasn't been resolved yet (the live reference is set in tick) or the player is in another dimension;
    // Non-owner block breaking is canceled inside ServerEventHandler.onBlockBreak.
    Player target = this.player != null ? this.player : resolveOnlinePlayer();
    if (target != null) {
        AttributeInstance attribute = target.getAttribute(Attributes.MOVEMENT_SPEED);
        if (attribute != null && attribute.hasModifier(ID_MOVEMENT_SLOWDOWN)) {
            attribute.removeModifier(ID_MOVEMENT_SLOWDOWN);
        }
    }
}

private static int setSwordCharged(@NotNull CommandSourceStack commandSource, @NotNull Collection<ServerPlayer> players, float charge) {
    for (ServerPlayer player : players) {
        ItemStack held = player.getMainHandItem().copy();

        if (held.getItem() instanceof VampireSwordItem sword) {
            sword.setCharged(held, charge);
            player.setItemInHand(InteractionHand.MAIN_HAND, held);
        } else {
            commandSource.sendSuccess(() -> Component.translatable("command.vampirism.test.swordcharged.nosword"), false);
        }
    }
    return 0;
}

public static boolean handleHeldNonVampireItem(ItemStack stack, Entity entity, @Nullable EquipmentSlot slot) {
    if (entity instanceof LivingEntity living && (slot != null && slot.getType() == EquipmentSlot.Type.HAND) && entity.tickCount % 16 == 8 ) {
        if (Helper.isVampire(living)) {
            living.addEffect(new MobEffectInstance(ModEffects.TOXICANT, 20, 1));
            if (living instanceof Player player) {
                player.getInventory().removeItem(stack);
                player.drop(stack, true);
            }
            return true;
        }
    }
    return false;
}

protected void onInsideBlock(BlockState pState) {
    if (pState.isAir()) {
        AttributeInstance attribute = getAttribute(Attributes.FLYING_SPEED);
        if (attribute != null && attribute.getModifier(SPEED_MODIFIER) == null) {
            attribute.addTransientModifier(new AttributeModifier(SPEED_MODIFIER, 0.2, AttributeModifier.Operation.ADD_VALUE));
        }
    } else {
        AttributeInstance attribute = getAttribute(Attributes.FLYING_SPEED);
        if (attribute != null) {
            attribute.removeModifier(SPEED_MODIFIER);
        }
    }
}

public static void configure(ActionBuilder<Dracula> builder) {
    builder.activeMemory(ModMemoryTypes.REGENERATION_ACTIVE)
            .cooldown(ModMemoryTypes.REGENERATION_COOLDOWN, () -> 60 * 20)
            .add(RegenerationBehavior.create(), RegenerationBehavior.sensors(), RegenerationBehavior.memories())
            .canActivate((level, dracula) -> {
                float v = (dracula.getHealth() / dracula.getMaxHealth());
                float gate = 1 - RegenerationBehavior.HEALTH_PERCENTAGE;
                if (v >= gate) {
                    return false;
                }
                return dracula.getRandom().nextFloat() < ((1 - v) / gate);
            });
}

private void addAttributes(Holder<IRefinement> refinement) {
    Holder<Attribute> attribute = refinement.value().getAttribute();
    if (attribute == null) return;

    var instance = this.player.getAttribute(attribute);
    if (instance == null) return;
    var factory = refinement.value().attributeFactory();
    if (factory == null) return;
    AttributeModifier attributeModifier = factory.apply(refinement.unwrapKey().orElseThrow().identifier(), refinement.value().getModifierValue());
    if (instance.hasModifier(attributeModifier.id())) {
        instance.removeModifier(attributeModifier.id());
    }
    instance.addTransientModifier(attributeModifier);
}

public static ItemStack getMap(Entity entity, TagKey<Structure> destination, String displayName, Holder<MapDecorationType> decorationType, int radius) {
    if (entity.level() instanceof ServerLevel serverlevel) {
        BlockPos targetPos = serverlevel.findNearestMapStructure(destination, entity.blockPosition(), radius, true);
        if (targetPos != null) {
            ItemStack itemStack = MapItem.create(serverlevel, targetPos.getX(), targetPos.getZ(), (byte)2, true, true);
            MapItem.renderBiomePreviewMap(serverlevel, itemStack);
            MapItemSavedData.addTargetDecoration(itemStack, targetPos, "+", decorationType);
            itemStack.set(DataComponents.ITEM_NAME, Component.translatable(displayName));
            return itemStack;
        }
    }

    return null;
}

public void setEntityLevel(int level) {
    if (level >= 0) {
        getEntityData().set(LEVEL, level);
        this.updateEntityAttributes();
        if (level == 2) {
            this.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, 1000000, 1, false, false));
        }
        if (level == 1) {
            this.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(Items.IRON_SWORD));
        } else {
            this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
        }

    }
}

private void applyAttributes() {
    for (ItemStack refinementItem : this.refinementItems) {
        if (refinementItem.getItem() instanceof IRefinementItem refinement) {
            IRefinementItem.AccessorySlotType slotType = refinement.getSlotType();
            IRefinementSet refinementSet = refinement.getRefinementSet(refinementItem);
            Set<Holder<IRefinement>> refinements;
            if (refinementSet == null) {
                refinements = Set.of();
            } else {
                refinements = refinementSet.getRefinements();
            }
            refinementSets.put(slotType, refinements);
            refinements.forEach(this::addAttributes);
        }
    }
}

private void checkMistFormTrigger() {
    long gameTime = this.level().getGameTime();
    if (gameTime < this.mistCooldownUntil) return;
    this.recentDamage.removeIf(p -> gameTime - p.getFirst() > 100);
    float total = 0;
    for (Pair<Long, Float> p : this.recentDamage) {
        total += p.getSecond();
    }
    if (total > this.getMaxHealth() * 0.2f) {
        this.setState(DraculaState.MIST);
        this.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
        this.mistStartTime = gameTime;
        this.mistCooldownUntil = gameTime + MIST_COOLDOWN;
        this.recentDamage.clear();
    }
}

public static void handlePotentialBannerKill(@Nullable Entity offender, IFactionEntity victim) {
    if (offender instanceof Player player) {
        Holder<? extends IFaction<?>> faction = victim.getFaction();
        if (victim.asEntity().getItemBySlot(EquipmentSlot.HEAD).has(FactionDataComponents.IS_FACTION_BANNER)) {
            Holder<? extends IPlayableFaction<?>> playerFaction = IFactionHelper.get().getFaction(player);
            if (playerFaction != faction) {
                Holder<MobEffect> badOmen = faction.components().get(FactionDataComponents.VILLAGE_BAD_OMEN);
                if (badOmen != null) {
                    MobEffectInstance inst = player.getEffect(badOmen);
                    int i = inst != null ? Math.min(inst.getAmplifier() + 1, 4) : 0;
                    if (inst != null) player.removeEffectNoUpdate(badOmen);
                    player.addEffect(new MobEffectInstance(badOmen, 120000, i, false, false, true));
                }
            }
        }
    }
}

private void endRitual() {
    // Falls back to PlayerList lookup in case this.player hasn't been resolved yet (the live reference is set in tick) or the player is in another dimension.
    Player target = this.player != null ? this.player : resolveOnlinePlayer();
    if (target != null) {
        AttributeInstance movementSpeedAttribute = target.getAttribute(Attributes.MOVEMENT_SPEED);
        if (movementSpeedAttribute != null) {
            movementSpeedAttribute.removeModifier(ID_MOVEMENT_SLOWDOWN);
        }
    }

    this.player = null;
    this.playerUUID = null;
    this.tips = List.of();
    this.runTime = 0;

    updateClient();
    setChanged();
}

public IActionResult activateServer(@NotNull IVampirePlayer player, ActivationContext context) {
    Player entityPlayer = player.asEntity();
    boolean refined = player.getRefinementHandler().isRefinementEquipped(ModRefinements.SUMMON_BATS);
    int amount = ModConfig.balance().vaSummonBatsCount.get();
    if (amount > 1 && refined) {
        amount = amount / 2;
    }
    for (int i = 0; i < amount; i++) {
        BlindingBatEntity e = ModEntities.BLINDING_BAT.get().create(entityPlayer.level(), EntitySpawnReason.TRIGGERED);
        e.restrictLiveSpan();
        if (refined) e.setTargeting();
        e.setResting(false);
        e.copyPosition(player.asEntity());
        player.asEntity().level().addFreshEntity(e);
    }
    entityPlayer.level().playSound(null, entityPlayer.getX(), entityPlayer.getY(), entityPlayer.getZ(), ModSounds.BAT_SWARM.get(), SoundSource.PLAYERS, 1.3F, entityPlayer.level().getRandom().nextFloat() * 0.2F + 1.3F);
    return IActionResult.SUCCESS;
}

protected void freezeEntities(IVampirePlayer vampire) {
    Player player = vampire.asEntity();
    IFactionPredicate build = IFactionPredicate.builder(ModFactions.VAMPIRE).ignoreDisguise().and(EntitySelector.NO_SPECTATORS).build();
    List<LivingEntity> l = player.level().getEntitiesOfClass(LivingEntity.class, player.getBoundingBox().inflate(7, 4, 7), build);
    for (LivingEntity entity : l) {
        if (player.equals(entity)) continue;
        entity.level().playSound(null, entity.getX(), entity.getY(), entity.getZ(), ModSounds.FREEZE.get(), SoundSource.PLAYERS, 1f, 1f);
        ModParticles.spawnParticlesServer(player.level(), ParticleTypes.SNOWFLAKE, entity.getX(), entity.getY(), entity.getZ(), 20, 1, 1, 1, 0);

        if (!entity.canFreeze()) continue;

        int dur = ModConfig.balance().vaFreezeDuration.get() * 20;
        if (vampire.getRefinementHandler().isRefinementEquipped(ModRefinements.FREEZE_DURATION)) {
            dur *= ModConfig.balance().vrFreezeDurationMod.get();
        }
        entity.addEffect(new MobEffectInstance(ModEffects.FREEZE, dur));
        entity.setSharedFlagOnFire(false);
    }
}

public boolean initiateCaptureOrIncreaseBadOmenLevel(@NotNull Holder<? extends IFaction<?>> faction, @Nullable Consumer<Component> feedback, int badOmenLevel, float strengthModifier) {
    if (!IFaction.is(faction, de.teamlapen.faction.api.tags.FactionTags.CAN_RAID)) {
        return false;
    }
    if (this.capturingFaction == null) {
        this.initiateCapture(faction, feedback, badOmenLevel, strengthModifier);
        return true;
    }
    if (IFaction.is(this.capturingFaction, faction)) {
        if (this.phase == CAPTURE_PHASE.PHASE_1_OPPOSITE) {
            int tmpBadOmen = this.badOmenLevel;
            float tmpStrength = this.strengthRatio;
            this.calculateAttackStrength(this.badOmenLevel + badOmenLevel, strengthModifier);
            this.captureTimer = this.captureTimer / 2;
            LOGGER.debug("Increase capture from strength {} and badomen level {} to strength {} and badomen level {}", tmpStrength, tmpBadOmen, this.strengthRatio, this.badOmenLevel);
        }
        return true;
    }
    return false;
}

public void deactivateAction(Holder<? extends ILastingAction<T>> action, boolean ignoreCooldown, boolean fullCooldown) {
    if (activeTimers.containsKey(action)) {
        int leftTime = activeTimers.getInt(action);
        int duration = expectedDurations.getInt(action);
        var event = FactionEventFactory.fireActionDeactivatedEvent(player, action, leftTime, expectedCooldownTimes.getInt(action), ignoreCooldown, fullCooldown);
        int cooldown = event.getCooldown();
        if (!event.ignoreCooldown() && !cooldownTimers.containsKey(action)) {
            if (!event.fullCooldown()) {
                cooldown -= (int) (cooldown * (leftTime / (float) duration / 2f));
            } else {
                expectedCooldownTimes.put(action, cooldown);
            }
            //Entries should be at least 1
            cooldownTimers.put(action, Math.max(cooldown, 1));
            activeTimers.put(action, 1);
        }
        activeTimers.removeInt(action);
        expectedDurations.removeInt(action);
        action.value().onDeactivated(player);
        sync();
    }
}

public void startRitual(Player player) {
    if (this.level == null) return;

    this.player = player;
    this.playerUUID = player.getUUID();
    this.runTime = DURATION_TICK;
    player.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, DURATION_TICK, MobEffectInstance.MAX_AMPLIFIER, false, false));

    AttributeInstance movementSpeedAttribute = player.getAttribute(Attributes.MOVEMENT_SPEED);
    if (movementSpeedAttribute != null && !movementSpeedAttribute.hasModifier(ID_MOVEMENT_SLOWDOWN)) {
        movementSpeedAttribute.addTransientModifier(new AttributeModifier(ID_MOVEMENT_SLOWDOWN, -1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
    }

    if (!this.tips.isEmpty()) {
        for (BlockPos tip : this.tips) {
            ModParticles.spawnParticlesServer(this.level, new BloodShredParticleOptions(tip.getCenter(), 60, false, BloodShredParticleOptions.PURE_BLOOD_COLOR), this.worldPosition.getX() + 0.5, this.worldPosition.getY() + 0.5, this.worldPosition.getZ() + 0.5, 5, 0.1, 0.1, 0.1, 0);
        }
    }

    updateClient();
    setChanged();
}

public static void tryPullingBlood(Level level, BlockPos pos, BloodSieveBlockEntity blockEntity) {
    if (blockEntity.pullCooldownTime > 0) {
        blockEntity.pullCooldownTime--;
        return;
    }

    boolean needsChange;

    try (var transaction = Transaction.openRoot()) {
        var moved = ResourceHandlerUtil.move(level.getCapability(Capabilities.Fluid.BLOCK, pos.above(), Direction.DOWN), blockEntity.inputFluidInventory, BloodHelper::isConvertibleToBlood, 100, transaction);
        needsChange = moved != 0;
        transaction.commit();
    }

    try (var transaction = Transaction.openRoot()) {
        var moved = ResourceHandlerUtil.move(blockEntity.outputFluidInventory, level.getCapability(Capabilities.Fluid.BLOCK, pos.below(), Direction.UP), BloodHelper::isConvertibleToBlood, 100, transaction);
        needsChange = moved != 0 || needsChange;
        transaction.commit();
    }

    blockEntity.pullCooldownTime = PULL_DELAY;
    if (needsChange) blockEntity.setChanged();
}

public boolean doHurtTarget(ServerLevel level, Entity entity) {
    if (canSuckBloodFromPlayer && !level().isClientSide() && wantsBlood() && entity instanceof Player player && !Helper.isHunter(player) && !UtilLib.canReallySee(player, this, true)) {
        int amt = VampirePlayer.get(player).onBite(this);
        drinkBlood(amt, IBloodStats.MEDIUM_SATURATION, new DrinkBloodContext(player));
        VampirePlayer.get(player).tryInfect(this);
        return true;
    }
    if (entity instanceof LivingEntity living) {
        for (ItemStack e : Arrays.stream(EquipmentSlot.values()).filter(x -> x.getType() == EquipmentSlot.Type.HUMANOID_ARMOR).map(living::getItemBySlot).toList()) {
            if (e.getItem() instanceof HunterCoatItem) {
                int j = 1;
                if (((HunterCoatItem) e.getItem()).getVampirismTier().equals(IItemWithTier.Tier.ENHANCED)) {
                    j = 2;
                } else if (((HunterCoatItem) e.getItem()).getVampirismTier().equals(IItemWithTier.Tier.ULTIMATE)) {
                    j = 3;
                }
                if (getRandom().nextInt((4 - j) * 2) == 0) {
                    addEffect(new MobEffectInstance(ModEffects.TOXICANT, (int) (20 * Math.sqrt(j)), j));
                }
            }
        }
    }
    return super.doHurtTarget(level, entity);
}

public void initiateCapture(@NotNull Holder<? extends IFaction<?>> faction, @Nullable Consumer<Component> feedback, int badOmenLevel, float strengthModifier) {
    this.updateTileStatus();
    if (!this.capturePreconditions(faction, feedback == null ? (_) -> {
    } : feedback)) {
        return;
    }
    this.forceVillageUpdate = true;
    this.captureAbortTimer = 0;
    this.captureDuration = 24000;
    this.captureTimer = 0;
    this.captureForceTargetTimer = 0;
    this.setCapturingFaction(faction);
    this.calculateAttackStrength(badOmenLevel, strengthModifier);
    this.timeSinceLastRaid = 0;

    this.phase = IFaction.isNeutral(this.controllingFaction) ? CAPTURE_PHASE.PHASE_1_NEUTRAL : CAPTURE_PHASE.PHASE_1_OPPOSITE;

    Identifier currentFactionId = this.controllingFaction.unwrapKey().orElseThrow().identifier();
    this.notifyNearbyPlayers(Component.translatable("message." + currentFactionId.getNamespace() + ".village_raid.attacked." + currentFactionId.getPath(), faction.value().getNamePlural()));

    this.setChanged();

    this.makeAgressive();
    LOGGER.debug("Initiated capture with strength {} by {} at {} with badomen level {}", this.strengthRatio, faction.getRegisteredName(), this.getBlockPos(), badOmenLevel);
}

protected void tick(ServerLevel level, Dracula entity, long gameTime) {
    this.ticks++;
    entity.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);
    entity.getNavigation().stop();

    if (ticks <= 100 && ticks % 10 == 0) {
        double angle = (ticks / 10.0) * (Math.PI * 2);
        double x = entity.getX() + Math.cos(angle) * 2;
        double z = entity.getZ() + Math.sin(angle) * 2;
        double y = entity.getY() + 1.5;

        BloodProjectileEntity projectile = new BloodProjectileEntity(level, entity, Vec3.ZERO);
        projectile.setPos(x, y, z);
        projectile.setNoGravity(true);
        projectile.setMaxTicks(200);
        level.addFreshEntity(projectile);
        spawnedProjectiles.add(projectile);
    }

    if (ticks == 100) {
        for (BloodProjectileEntity projectile : spawnedProjectiles) {
            if (projectile.isAlive()) {
                Vec3 direction = projectile.position().subtract(entity.position().add(0, 1.5, 0)).normalize();
                projectile.setDeltaMovement(direction.scale(0.5));
                projectile.setMotionFactor(1.0f);
            }
        }
    }
}

private void setModifier(Player player, boolean enabled) {
    Identifier key = ModRegistries.ACTIONS.getKey(this);
    if (key == null) {
        return;
    }
    if (enabled) {
        AttributeInstance armor = player.getAttribute(Attributes.ARMOR);
        if (armor != null && !armor.hasModifier(key)) {
            armor.addPermanentModifier(new AttributeModifier(key, -1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
        }
        AttributeInstance armorToughness = player.getAttribute(Attributes.ARMOR_TOUGHNESS);
        if (armorToughness != null && !armorToughness.hasModifier(key)) {
            armorToughness.addPermanentModifier(new AttributeModifier(key, -1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
        }
        AttributeInstance fly = player.getAttribute(NeoForgeMod.CREATIVE_FLIGHT);
        if (fly != null && !fly.hasModifier(key)) {
            fly.addPermanentModifier(new AttributeModifier(key, 1, AttributeModifier.Operation.ADD_VALUE));
        }

        setFlightSpeed(player, ModConfig.balance().vaBatFlightSpeed.get().floatValue());
    } else {
        Objects.requireNonNull(player.getAttribute(Attributes.ARMOR)).removeModifier(key);
        Objects.requireNonNull(player.getAttribute(Attributes.ARMOR_TOUGHNESS)).removeModifier(key);
        Objects.requireNonNull(player.getAttribute(NeoForgeMod.CREATIVE_FLIGHT)).removeModifier(key);

        setFlightSpeed(player, 0.05F);
    }
    player.onUpdateAbilities();

}

public void onLivingDamage(LivingIncomingDamageEvent event) {
    if (event.getSource().is(DamageTypes.PLAYER_ATTACK) && event.getSource().getEntity() instanceof Player player) {
        ItemStack stack = player.getMainHandItem();
        OilUtils.getAppliedOil(stack).ifPresent(oil -> {
            if (oil instanceof IWeaponOil) {
                event.setAmount(event.getAmount() + ((IWeaponOil) oil).onDamage(stack, event.getAmount(), ((IWeaponOil) oil), event.getEntity(), player));
            }
        });
        if (Helper.isHunter(player) && Helper.isVampire(event.getEntity())) {
            Item item = stack.getItem();
            if (item instanceof HunterAxeItem && HunterPlayer.get(player).getSkillHandler().isSkillEnabled(HunterSkills.AXE2)) {
                event.getEntity().addEffect(new MobEffectInstance(ModEffects.BLEEDING, 20, 0, false, false, true));
            } else if (item == ModItems.STAKE.get() && HunterPlayer.get(player).getSkillHandler().isSkillEnabled(HunterSkills.STAKE2)) {
                event.getEntity().addEffect(new MobEffectInstance(ModEffects.BLEEDING, 40, 0, false, false, true));
            }
        }
    }
    if (event.getSource().is(ModDamageTypeTags.ENTITY_PHYSICAL) && !event.getSource().is(DamageTypeTags.BYPASSES_ARMOR)) {
        for (ItemStack armorStack : Arrays.stream(EquipmentSlot.values()).filter(x -> x.getType() == EquipmentSlot.Type.HUMANOID_ARMOR).map(x -> event.getEntity().getItemBySlot(x)).toList()) {
            if (OilUtils.getAppliedOil(armorStack).map(oil -> {
                if (oil instanceof EvasionOil evasionOil && evasionOil.evasionChance() > Optional.ofNullable(event.getSource().getEntity()).map(entity -> entity.level().getRandom().nextFloat()).orElse(1f)) {
                    event.setAmount(0);
                    oil.reduceDuration(armorStack, oil, oil.getDurationReduction());
                    return true;
                }
                return false;
            }).orElse(false)) {
                break;
            }
        }
    }
}

public void tick() {
    if (attackTime > 0) {
        attackTime--;
    } else {
        LivingEntity target = entity.getTarget();
        if (target != null) {
            double d0 = this.entity.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());
            boolean canSee = this.entity.getSensing().hasLineOfSight(target);
            boolean couldSee = this.seeTime > 0;

            if (canSee != couldSee) {
                this.seeTime = 0;
            }

            if (canSee) {
                ++this.seeTime;
                this.entity.lookAt(target, 19.0F, 10.0F);


                this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition(1.0F));
            } else {
                --this.seeTime;
            }

            if (d0 <= (double) this.maxAttackDistance && this.seeTime >= 20) {
                attack(target);
                this.attackTime = attackCooldown;
                entity.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 20));


            } else {
                this.entity.getNavigation().moveTo(target, 1.0);

            }
        }
    }
}

public static BehaviorControl<Dracula> create(double radius, int thresholdTicks, int minAttackers) {
    double radiusSqt = radius * radius;

    return BehaviorBuilder.create(inst -> inst.group(
            inst.present(ModMemoryTypes.SURROUNDED_SINCE.get()),
            inst.present(ModMemoryTypes.NEAREST_ATTACKABLE.get()),
            inst.registered(ModMemoryTypes.FLYING_SWORD_ACTIVE.get()),
            inst.registered(ModMemoryTypes.FLYING_SWORD_COOLDOWN.get()),
            inst.registered(ModMemoryTypes.ACTION_ACTIVE.get()),
            inst.registered(ModMemoryTypes.ACTION_COOLDOWN.get()),
            inst.absent(ModMemoryTypes.SURROUNDED_COOLDOWN.get())
    ).apply(inst, (timer,nearest, swordActive, swordCooldown, actionActive, actionCooldown, cooldown) -> (level, dracula, gameTime) -> {
        if (level.getGameTime() - inst.get(timer) < thresholdTicks) return false;

        List<LivingEntity> entities = inst.get(nearest).stream().filter(x -> x.distanceToSqr(dracula) < radiusSqt).toList();
        if (entities.size() < minAttackers) return false;

        for (LivingEntity livingEntity : entities) {
            livingEntity.knockback(1.5, livingEntity.getX() - dracula.getX(), livingEntity.getZ() - dracula.getZ());
            livingEntity.addEffect(new MobEffectInstance(ModEffects.FREEZE, 40, 1));
        }

        Vec3 avgAttackerPos = getAvgPos(entities);
        Vec3 safePos = DefaultRandomPos.getPosAway(dracula, 20, 7, avgAttackerPos);
        if (safePos != null) {
            dracula.teleportTo(safePos.x, safePos.y, safePos.z);
        }

        timer.erase();
        swordActive.set(Unit.INSTANCE);
        swordCooldown.erase();
        actionActive.set(Unit.INSTANCE);
        actionCooldown.erase();
        cooldown.setWithExpiry(Unit.INSTANCE, 20 * 10);
        return true;
    }));
}

protected IActionResult activateServer(IVampirePlayer player, ActivationContext context) {
    Player shooter = player.asEntity();
    IRefinementAccess skillHandler = player.getRefinementHandler();

    float directDamage = ModConfig.balance().vaDarkBloodProjectileDamage.get().floatValue();
    float indirectDamage = directDamage * 0.5f;
    float speed = 0.95f;
    if (skillHandler.isRefinementEquipped(ModRefinements.DARK_BLOOD_PROJECTILE_DAMAGE)) {
        float modifier = ModConfig.balance().vrDarkBloodProjectileDamageMod.get().floatValue();
        directDamage *= modifier;
        indirectDamage *= modifier;
    }
    if (skillHandler.isRefinementEquipped(ModRefinements.DARK_BLOOD_PROJECTILE_SPEED)) {
        speed = 1.4f;
    }

    if (skillHandler.isRefinementEquipped(ModRefinements.DARK_BLOOD_PROJECTILE_AOE)) {
        for (int i = 0; i < 32; i++) {
            Vec3 vec3d = getRotationVector(shooter.getViewXRot(1.0f), shooter.getViewYRot(1.0f) + i * 11.25f);
            DarkBloodProjectileEntity entity = createProjectile(shooter, shooter.position(), 0, vec3d, false, 0, 0, 0.95f);
            entity.setMaxTicks(7);
            entity.excludeShooter();
            if (i == 0) {
                entity.setDamage(0, directDamage);
                entity.explode(ModConfig.balance().vrDarkBloodProjectileAOERange.get(), null);
            }
        }
    } else {
        boolean goThrough = skillHandler.isRefinementEquipped(ModRefinements.DARK_BLOOD_PROJECTILE_PENETRATION);
        createProjectile(shooter, shooter.position(), shooter.getEyeHeight() * 0.9f, shooter.getViewVector(1.0F), goThrough, directDamage, indirectDamage, speed);
        if (skillHandler.isRefinementEquipped(ModRefinements.DARK_BLOOD_PROJECTILE_MULTI_SHOT)) {
            createProjectile(shooter, shooter.position(), shooter.getEyeHeight() * 0.9f, getVectorForRotation(shooter.getViewXRot(1.0f), shooter.getViewYRot(1.0f) + 30f), goThrough, directDamage, indirectDamage, speed);
            createProjectile(shooter, shooter.position(), shooter.getEyeHeight() * 0.9f, getVectorForRotation(shooter.getViewXRot(1.0f), shooter.getViewYRot(1.0f) - 30f), goThrough, directDamage, indirectDamage, speed);
        }
    }
    return IActionResult.SUCCESS;
}

public void updateActions() {
    //First update cooldown timers so active actions that become deactivated are not ticked.
    for (Iterator<Object2IntMap.Entry<Holder<? extends IAction<T>>>> it = cooldownTimers.object2IntEntrySet().iterator(); it.hasNext(); ) {
        Object2IntMap.Entry<Holder<? extends IAction<T>>> entry = it.next();
        int value = entry.getIntValue();
        player.asEntity().awardStat(FactionStats.ACTION_COOLDOWN_TIME.get().get(entry.getKey().value()));
        if (value <= 1) { //<= Just in case we have missed something
            expectedCooldownTimes.removeInt(entry);
            it.remove();
        } else {
            entry.setValue(value - 1);
        }
    }

    List<Holder<? extends ILastingAction<T>>> toRemove = new ArrayList<>();
    for (Object2IntMap.Entry<Holder<? extends ILastingAction<T>>> entry : activeTimers.object2IntEntrySet()) {
        int newtimer = entry.getIntValue() - 1;

        if (newtimer == 0) {
            toRemove.add(entry.getKey());
        } else {
            Holder<? extends ILastingAction<T>> action = entry.getKey();
            ActionEvent.ActionUpdateEvent<T> event = FactionEventFactory.fireActionUpdateEvent(player, action, newtimer);
            int expectedDuration = expectedDurations.getInt(action);
            if ((!event.shouldSkipActionUpdate() && action.value().onUpdate(player, expectedDuration - newtimer, expectedDuration)) || event.shouldDeactivation()) {
                entry.setValue(1); //Value of means they are deactivated next tick and onUpdate is not called again
            } else {
                player.asEntity().awardStat(FactionStats.ACTION_TIME.get().get(action.value()));
                entry.setValue(newtimer);
            }
        }
    }
    toRemove.forEach(holder -> {
        deactivateAction(holder, true);
        cooldownTimers.put(holder, expectedCooldownTimes.getInt(holder));
    });
    sync();
}

public void tick() {
    if (entity.level() instanceof ServerLevel level) {
        /*
         * Make sure all entities with no blood die
         * check for sanguinare as the entity might be converting instead of dying
         */
        if (blood == 0 && entity.tickCount % 20 == 10 && entity.getEffect(ModEffects.SANGUINARE) == null) {
            DamageHandler.hurtModded(level, entity, ModDamageSources::noBlood, 1000);
        }
        if (blood > 0 && blood < getMaxBlood() && entity.tickCount % 40 == 8) {
            if (blood < getMaxBlood() * 0.5) {
                entity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 41));
                entity.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 41, 2));
            }
            if (entity.getRandom().nextInt(BalanceMobProps.mobProps.BLOOD_REGEN_CHANCE) == 0 && LevelAttributeModifier.calculateModifierValue(blood, getMaxBlood(), 1, 0.8) < entity.getRandom().nextDouble()) {
                setBlood(getBlood() + 1);
                sync();
            }
        }
        if (poisonousBlood > 0) {
            poisonousBlood--;
            if (poisonousBlood == 0) {
                sync();
            }
        }
        if (Helper.isVampire(entity)) {
            poisonousBlood = 0;
        }
    }
    if (markForBloodCalculation) {
        IEntityBlood entry = VampirismApi.services().entityRegistry().getOrCreateEntry(entity);
        setMaxBlood(entry.blood());
        markForBloodCalculation = false;
    }
    if (this.remainingBarkTicks > 0) {
        --this.remainingBarkTicks;
    }
}

public IActionResult activateServer(@NotNull IVampirePlayer vampire, ActivationContext context) {
    Player player = vampire.asEntity();
    int dist = ModConfig.balance().vaTeleportMaxDistance.get();
    if (vampire.getRefinementHandler().isRefinementEquipped(ModRefinements.TELEPORT_DISTANCE)) {
        dist *= ModConfig.balance().vrTeleportDistanceMod.get();
    }
    HitResult target = UtilLib.getPlayerLookingSpot(player, dist);
    if (target.getType() == HitResult.Type.MISS) {
        player.playSound(SoundEvents.NOTE_BLOCK_BASS.value(), 1, 1);
        return IActionResult.fail(Component.translatable("message.vampirism.action.teleport.no_target"));
    }
    if (!(player instanceof ServerPlayer serverPlayer)) {
        return IActionResult.SUCCESS;
    }

    // Teleport to slightly in front of the visual hit spot, towards the player. Executed similar to an ender pearl to reduce the risk of getting stuck.
    Vec3 origin = serverPlayer.position();
    Vec3 hitLocation = target.getLocation();
    Vec3 destination = hitLocation.add(hitLocation.vectorTo(origin).normalize().scale(0.5));

    if (serverPlayer.isPassenger()) {
        serverPlayer.stopRiding();
    }
    serverPlayer.teleport(new TeleportTransition((ServerLevel) serverPlayer.level(), destination, Vec3.ZERO, serverPlayer.getYRot(), serverPlayer.getXRot(), Set.of(), TeleportTransition.DO_NOTHING));
    serverPlayer.resetFallDistance();

    AreaParticleCloud particleCloud = new AreaParticleCloud(ModEntities.PARTICLE_CLOUD.get(), serverPlayer.level());
    particleCloud.setPos(origin.x(), origin.y(), origin.z());
    particleCloud.setRadius(0.7F);
    particleCloud.setHeight(serverPlayer.getBbHeight());
    particleCloud.setDuration(5);
    particleCloud.setSpawnRate(15);
    particleCloud.setParticle(ColorParticleOption.create(ParticleTypes.ENTITY_EFFECT, 0xFF500000));
    serverPlayer.level().addFreshEntity(particleCloud);
    serverPlayer.level().playSound(null, origin.x(), origin.y(), origin.z(), ModSounds.TELEPORT_AWAY.get(), SoundSource.PLAYERS, 1f, 1f);
    serverPlayer.level().playSound(null, serverPlayer.getX(), serverPlayer.getY(), serverPlayer.getZ(), ModSounds.TELEPORT_HERE.get(), SoundSource.PLAYERS, 1f, 1f);
    return IActionResult.SUCCESS;
}

private static void trySuckingItems(Level level, BlockPos pos, BloodGrinderBlockEntity blockEntity) {
    if (blockEntity.pullCooldownTime > 0) {
        blockEntity.pullCooldownTime--;
        return;
    }

    if (level.getBlockState(pos.above()).isFaceSturdy(level, pos, Direction.DOWN, SupportType.CENTER)) {
        blockEntity.pullCooldownTime = PULL_DELAY;
        blockEntity.setChanged();
        return;
    }

    List<ItemEntity> items = getItemsAbove(level, pos);
    for (ItemEntity itemEntity : items) {
        ItemStack inputStack = blockEntity.inputStack;
        ItemStack entityStack = itemEntity.getItem();
        if (entityStack.isEmpty() || !isGrindable(entityStack)) continue;

        if (inputStack.isEmpty()) {
            int transferAmount = Math.min(entityStack.getCount(), entityStack.getMaxStackSize());
            blockEntity.inputStack = entityStack.split(transferAmount);
        } else if (ItemStack.isSameItemSameComponents(inputStack, entityStack) && inputStack.getCount() < inputStack.getMaxStackSize()) {
            int transferAmount = Math.min(entityStack.getCount(), inputStack.getMaxStackSize() - inputStack.getCount());
            blockEntity.inputStack.grow(transferAmount);
            entityStack.shrink(transferAmount);
        } else {
            continue;
        }

        if (entityStack.isEmpty()) {
            itemEntity.discard();
        } else {
            itemEntity.setItem(entityStack);
        }

        blockEntity.pullCooldownTime = PULL_DELAY;
        blockEntity.setChanged();
        break;
    }
}

private void updateAttributes(Player player, boolean enabled) {
    Identifier key = ModRegistries.ACTIONS.getKey(this);
    if (key == null) {
        return;
    }

    AttributeInstance speed = player.getAttribute(Attributes.MOVEMENT_SPEED);
    if (speed != null) {
        if (enabled) {
            speed.addOrReplacePermanentModifier(new AttributeModifier(key, 0.2, AttributeModifier.Operation.ADD_MULTIPLIED_BASE));
        } else {
            speed.removeModifier(key);
        }
    }
    AttributeInstance stepHeight = player.getAttribute(Attributes.STEP_HEIGHT);
    if (stepHeight != null) {
        if (enabled) {
            stepHeight.addOrReplacePermanentModifier(new AttributeModifier(key, 0.4, AttributeModifier.Operation.ADD_VALUE));
        } else {
            stepHeight.removeModifier(key);
        }
    }
    AttributeInstance gravity = player.getAttribute(Attributes.GRAVITY);
    if (gravity != null) {
        if (enabled) {
            gravity.addOrReplacePermanentModifier(new AttributeModifier(key, -0.7, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
        } else {
            gravity.removeModifier(key);
        }
    }
    AttributeInstance jump = player.getAttribute(Attributes.JUMP_STRENGTH);
    if (jump != null) {
        if (enabled) {
            jump.addOrReplacePermanentModifier(new AttributeModifier(key, -0.7, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
        } else {
            jump.removeModifier(key);
        }
    }

}

public static void filterBlood(BloodSieveBlockEntity blockEntity) {
    if (blockEntity.filterCooldownTime > 0) {
        blockEntity.filterCooldownTime--;
        return;
    }

    if (!blockEntity.inputFluidInventory.isEmpty()) {
        try (var transaction = Transaction.openRoot()) {

            int extracted;
            float conversionRate;
            try (var access = blockEntity.inputFluidInventory.beginAccess()) {
                FluidResource resource = blockEntity.inputFluidInventory.getResource(0);
                if (resource.isEmpty()) return;

                IFluidBloodConversion bloodConversion = BloodHelper.getBloodConversion(resource.getFluid());
                conversionRate = bloodConversion.conversionRate();

                int amountAsInt = blockEntity.inputFluidInventory.getAmountAsInt(0);

                extracted = blockEntity.inputFluidInventory.extract(resource, Math.min(amountAsInt, 50), transaction);
            }

            int blood = (int) Math.ceil(extracted * conversionRate);

            if (blood > 0) {
                try (var access = blockEntity.outputFluidInventory.beginAccess()) {
                    int inserted = blockEntity.outputFluidInventory.insert(FluidResource.of(ModFluids.BLOOD), blood, transaction);

                    if (inserted > 0) {
                        blockEntity.filterStack.setDamageValue(blockEntity.filterStack.getDamageValue() + inserted);
                        if (blockEntity.filterStack.isBroken()) {
                            blockEntity.filterStack = ItemStack.EMPTY;
                        }
                        blockEntity.updateFilterState(blockEntity.level, blockEntity.worldPosition);
                        transaction.commit();
                    }
                }
            }
        }
    }

    blockEntity.filterCooldownTime = FILTER_DELAY;
}

public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, DiffuserBlockEntity blockEntity) {
    boolean hasChanged = false;
    if (blockEntity.litTime > 0) {
        blockEntity.litTime--;
        if (blockEntity.bootTimer > 0) {
            blockEntity.bootTimer--;
            if (blockEntity.bootTimer == 0) {
                blockEntity.activateEffect(level, blockPos, blockState);
            }
        }
        if (blockEntity.loaded && blockEntity.bootTimer == 0) {
            blockEntity.loaded = false;
            blockEntity.activateEffect(level, blockPos, blockState);
        }
    } else if (blockEntity.litTime == 0 && blockEntity.getBurnDuration(blockEntity.items.get(SLOT_FUEL)) > 0) {
        ItemStack fuelStack = blockEntity.items.get(SLOT_FUEL);
        int burnDuration = blockEntity.getBurnDuration(fuelStack);
        blockEntity.litTime += burnDuration;
        blockEntity.litDuration = burnDuration;
        fuelStack.shrink(1);
        blockEntity.items.set(SLOT_FUEL, fuelStack);
        hasChanged = true;
    } else {
        int maxBootTimer = ModConfig.balance().diffuserBootTime.get() * 20;
        if (blockEntity.bootTimer == 0) {
            blockEntity.deactivateEffect(level, blockPos, blockState);
            blockEntity.bootTimer = maxBootTimer;

        } else if (blockEntity.bootTimer != maxBootTimer) {
            blockEntity.bootTimer = maxBootTimer;
        }
    }

    boolean shouldBeLit = blockEntity.bootTimer == 0 && blockEntity.litTime > 0;
    if (blockState.getValue(DiffuserBlock.LIT) != shouldBeLit) {
        blockState = blockState.setValue(DiffuserBlock.LIT, shouldBeLit);
        level.setBlock(blockPos, blockState, Block.UPDATE_ALL);
        hasChanged = true;
    }

    if (hasChanged && !level.isClientSide()) {
        setChanged(level, blockPos, blockState);
    }
}

public void updateActions(ServerLevel level, T entity, Brain<T> brain, Map<Activity, Collection<Action<T>>> actionsByActivity) {
    if (brain.hasMemoryValue(ModMemoryTypes.ACTION_ACTIVE.get())) {
        Optional<Long> actionActiveSince = brain.getMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get());

        if (actionActiveSince.isEmpty()) {
            brain.setMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get(), level.getGameTime());
            return;
        }

        if (level.getGameTime() - actionActiveSince.get() < 40) {
            return;
        }

        if (actionsByActivity.values().stream().flatMap(Collection::stream).map(Action::activity).noneMatch(brain::isActive)) {
            brain.eraseMemory(ModMemoryTypes.ACTION_ACTIVE.get());
            brain.eraseMemory(ModMemoryTypes.ACTION_COOLDOWN.get());
            brain.eraseMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get());
        }
    } else if (!brain.hasMemoryValue(ModMemoryTypes.ACTION_COOLDOWN.get())) {
        var activity = brain.getActiveNonCoreActivity().orElse(null);
        if (activity == null || activity == Activity.IDLE) return;
        var actionsSource = actionsByActivity.get(activity);
        if (actionsSource == null) return;
        ArrayList<Action<T>> actions = new ArrayList<>(actionsSource);
        Collections.shuffle(actions);

        for (Action<T> action : actions) {
            if (brain.hasMemoryValue(action.cooldownMemory().memory())) {
                continue;
            }

            if (!action.precondition().test(level, entity)) {
                continue;
            }

            if (!action.requirements().stream().allMatch(pair -> brain.checkMemory(pair.getFirst(), pair.getSecond()))) {
                continue;
            }

            brain.setMemory(ModMemoryTypes.ACTION_ACTIVE.get(), Unit.INSTANCE);
            brain.setMemory(action.activeMemory(), Unit.INSTANCE);
            brain.setMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get(), level.getGameTime());
            return;
        }
    }
}

public static void processGrinding(Level level, BlockPos pos, BloodGrinderBlockEntity blockEntity) {
    ItemStack inputStack = blockEntity.inputStack;
    ItemStack filterStack = blockEntity.filterStack;
    ControllableFluidTank fluidInventory = blockEntity.fluidInventory;

    boolean canGrind = !inputStack.isEmpty() && isGrindable(inputStack);
    int blood = canGrind ? getBlood(inputStack) : 0;
    int space = fluidInventory.getCapacity(FluidResource.of(ModFluids.BLOOD)) - fluidInventory.getAmount();

    if (!canGrind || (space < blood && !fluidInventory.isEmpty()) || filterStack.isEmpty() || !filterStack.isDamageableItem() || filterStack.getDamageValue() >= filterStack.getMaxDamage()) {
        updateGrindState(level, pos, false);
        blockEntity.grindCooldownTime = -1;
        return;
    }

    if (blockEntity.grindCooldownTime < 0) {
        blockEntity.grindCooldownTime = GRIND_DELAY;
        blockEntity.setChanged();
        updateGrindState(level, pos, true);
        return;
    }

    if (blockEntity.grindCooldownTime > 0) {
        blockEntity.grindCooldownTime--;
        updateGrindState(level, pos, true);
        return;
    }

    // The durability of filters is multiplied by 100 for parity with the blood sieve, so it must be considered
    int numberAllowedByFilter = Mth.clamp((int) Math.ceil((double) (filterStack.getMaxDamage() - filterStack.getDamageValue()) / 100), 0, 4);
    int numberAllowedToGrind = Mth.clamp((space - space % blood) / blood, 1, numberAllowedByFilter);
    try (var access = fluidInventory.beginAccess()) {
        int added = ResourceHandlerUtil.insertStacking(fluidInventory, FluidResource.of(ModFluids.BLOOD), blood * numberAllowedToGrind, null);
        inputStack.shrink(numberAllowedToGrind);
    }

    filterStack.setDamageValue(filterStack.getDamageValue() + numberAllowedToGrind * 100);
    if (filterStack.isBroken()) {
        blockEntity.filterStack = ItemStack.EMPTY;
    }
    blockEntity.updateFilterState(level, pos);

    level.playSound(null, pos, ModSounds.BLOOD_SQUEEZE.get(), SoundSource.BLOCKS, 0.5f + level.getRandom().nextFloat() / 4, 1.0f - level.getRandom().nextFloat() / 4);

    blockEntity.grindCooldownTime = -1;
    updateGrindState(level, pos, false);
    blockEntity.setChanged();
}

public IActionResult toggleAction(Holder<? extends IAction<T>> action, IAction.ActivationContext context) {
    if (ActionHelper.checkActionDisableEffect(this.player)) return IActionResult.DISABLED_EFFECT;
    if (activeTimers.containsKey(action)) {
        // it must be a lasting action because it is in the activeTimers field
        deactivateAction(SafeCast.<Holder<ILastingAction<T>>>cast(action));
        return IActionResult.SUCCESS;
    } else if (cooldownTimers.containsKey(action)) {
        return IActionResult.ON_COOLDOWN;
    } else {
        if (this.player.asEntity().isSpectator()) return IActionResult.RESTRICTED;
        if (!isActionUnlocked(action)) return IActionResult.NOT_UNLOCKED;
        if (!isActionAllowedPermission(action)) return IActionResult.DISALLOWED_PERMISSION;

        IActionResult r = checkDefaultToggleConditions(action);
        if (r.successful()) {

            var mutualExclusiveActions = action.value().mutualExclusiveActionTag();
            if (mutualExclusiveActions != null) {
                deactivateActions(mutualExclusiveActions);
            }

            /* Only lasting actions have a duration, so regular actions will return a duration of -1. */
            int duration = action.value() instanceof ILastingAction<T> lasting ? lasting.getDuration(player) : -1;
            ActionEvent.ActionActivatedEvent<T> activationEvent = FactionEventFactory.fireActionActivatedEvent(player, action, action.value().getCooldown(player), duration);
            if (activationEvent.isCanceled()) return IActionResult.fail(activationEvent.getCancelMessage());
            r = action.value().onActivated(player, context);
            if (r.successful()) {
                player.asEntity().awardStat(FactionStats.ACTION_USED.get().get(action.value()));
                //Even though lasting actions do not activate their cooldown until they deactivate
                //we probably want to keep this here so that they are edited by one event.
                int cooldown = activationEvent.getCooldown();
                expectedCooldownTimes.put(action, cooldown);
                if (action.value() instanceof ILastingAction) {
                    expectedDurations.put(action, activationEvent.getDuration());
                    duration = activationEvent.getDuration();
                    //noinspection unchecked
                    activeTimers.put((Holder<ILastingAction<T>>) action, duration);
                } else {
                    cooldownTimers.put(action, cooldown);
                }

                if (player instanceof ServerPlayer serverPlayer) {
                    FactionAdvancements.ACTION_TRIGGER.get().trigger(serverPlayer, action);
                }
            }
        }
        return r;
    }
}

public void onUpdate() {
    FoodData foodStats = player.getFoodData();
    foodStats.setFoodLevel(10);
    Difficulty enumDifficulty = player.level().getDifficulty();
    float exhaustion = ((FoodDataAccessor)foodStats).getExhaustionLevel();
    ((FoodDataAccessor)foodStats).setExhaustionLevel(0);
    addExhaustion(exhaustion);
    this.prevBloodLevel = bloodLevel;
    float bloodExhaustionGate = player.level().getBiome(player.blockPosition()).is(ModBiomeTags.HasFaction.IS_VAMPIRE_BIOME) ? 6f : 4f;
    if (this.bloodExhaustionLevel > bloodExhaustionGate) {
        this.bloodExhaustionLevel -= bloodExhaustionGate;
        if (bloodSaturationLevel > 0) {
            bloodSaturationLevel = Math.max(bloodSaturationLevel - 1F, 0F);
        } else if (enumDifficulty != Difficulty.PEACEFUL || ModConfig.balance().vpBloodUsagePeaceful.get()) {
            this.bloodLevel = Math.max(bloodLevel - 1, 0);
        }
    }
    if (player.level() instanceof ServerLevel level) {
        boolean regen = level.getGameRules().get(GameRules.NATURAL_HEALTH_REGENERATION);
        if (regen && this.bloodSaturationLevel > 0 && player.isHurt() && this.bloodLevel >= maxBlood) {
            ++this.bloodTimer;
            if (this.bloodTimer >= 10) {
                float f = Math.min(this.bloodSaturationLevel, 6F);
                player.heal((f / 6F) * getHealModifier());
                this.addExhaustion(f);
                this.bloodTimer = 0;
            }
        } else if (regen && this.bloodLevel > 0 && player.isHurt()) {
            ++this.bloodTimer;

            boolean betterHeal = this.bloodLevel >= (18) && this.bloodTimer >= 80;
            boolean heal = this.bloodTimer >= 300;
            if (betterHeal || heal) {
                player.heal(betterHeal ? getHealModifier() : 0.5F * getHealModifier());
                this.addExhaustion(betterHeal ? 6F : 3F);
                this.bloodTimer = 0;
            }
        } else if (this.bloodLevel <= 0 && !player.isCreative() && !player.isSpectator()) {
            ++this.bloodTimer;

            if (this.bloodTimer >= 80) {
                if (player.getHealth() > 10.0F || enumDifficulty == Difficulty.HARD || player.getHealth() > 1.0F && enumDifficulty == Difficulty.NORMAL) {
                    this.player.addEffect(new MobEffectInstance(ModEffects.NO_BLOOD, 150, 0));
                }

                this.bloodTimer = 0;
            }
        } else {
            this.bloodTimer = 0;
        }
    }
    if (this.prevBloodLevel != this.bloodLevel) {
        this.changed = true;
    }
}

public static void serverTick(Level pLevel, BlockPos pPos, BlockState pState, AlchemicalCauldronBlockEntity pBlockEntity) {
    boolean flagWasLit;
    boolean flagChanged = false;
    if (pBlockEntity.isLit()) {
        pBlockEntity.litTime--;
    }
    if (pBlockEntity.litTime > 0) {
        flagWasLit = true;
        --pBlockEntity.litTime;
    } else {
        flagWasLit = false;
    }

    ItemStack fuel = pBlockEntity.items.get(3);
    ItemStack ingredient = pBlockEntity.items.get(1);
    ItemStack fluid = pBlockEntity.items.get(0);
    boolean hasIngredient = !ingredient.isEmpty();
    boolean hasFuel = !fuel.isEmpty();
    boolean hasFluid = !fluid.isEmpty();
    if (pBlockEntity.isLit() || hasFuel && hasIngredient && hasFluid) {
        RecipeHolder<AlchemicalCauldronRecipe> recipeholder;
        if (hasIngredient && hasFluid) {
            recipeholder = pBlockEntity.quickCheck.getRecipeFor(new AlchemicalCauldronRecipeInput(ingredient, fluid, pBlockEntity.getPlayerSkillHandler()), (ServerLevel) pLevel).orElse(null);
        } else {
            recipeholder = null;
        }

        int i = pBlockEntity.getMaxStackSize();
        if (!pBlockEntity.isLit() && canBurn(pLevel.registryAccess(), recipeholder, pBlockEntity.items, i, pBlockEntity) && pBlockEntity.canPlayerCook(recipeholder)) {
            pBlockEntity.litTime = pBlockEntity.getBurnDuration(fuel);
            pBlockEntity.litDuration = pBlockEntity.litTime;
            if (pBlockEntity.isLit()) {
                flagChanged = true;
                pBlockEntity.items.set(3, Helper.shrinkItemStack(fuel, pLevel, pPos)); //Reduce fuel
            }
        }

        if (pBlockEntity.isLit() && canBurn(pLevel.registryAccess(), recipeholder, pBlockEntity.items, i, pBlockEntity) && pBlockEntity.canPlayerCook(recipeholder)) {
            pBlockEntity.cookingProgress++;
            if (pBlockEntity.cookingProgress == pBlockEntity.cookingTotalTime) {
                pBlockEntity.cookingProgress = 0;
                pBlockEntity.cookingTotalTime = getTotalCookTime(pLevel, pBlockEntity);
                if (burn(pLevel.registryAccess(), recipeholder, pBlockEntity.items, i, pBlockEntity)) {
                    pBlockEntity.setRecipeUsed(recipeholder);
                }

                flagChanged = true;
            }
        } else {
            pBlockEntity.cookingProgress = 0;
        }
    } else if (pBlockEntity.cookingProgress > 0) {
        pBlockEntity.cookingProgress = Mth.clamp(pBlockEntity.cookingProgress - 2, 0, pBlockEntity.cookingTotalTime);
    }

    if (flagWasLit != pBlockEntity.isLit()) {
        flagChanged = true;
    }

    if (flagChanged) {
        pBlockEntity.setChanged();
    }
}

public int recalculateCuriosSlots(Player player)
{
	Optional<ICuriosItemHandler> curioInv = CuriosApi.getCuriosInventory(player).resolve();
	if (curioInv.isEmpty()) {
		return 0;
	}
	ICurioStacksHandler livingArmourSockets = curioInv.get().getCurios().get("living_armour_socket");
	if (livingArmourSockets == null) {
		return 0;
	}
	if (LivingUtil.hasFullSet(player))
	{
		LivingStats stats = LivingStats.fromPlayer(player);
		int curiosLevel = (stats != null) ? stats.getLevel(LivingArmorRegistrar.UPGRADE_CURIOS_SOCKET.get().getKey()) : 0;
		livingArmourSockets.removeModifier(player.getUUID());
		if (curiosLevel != 0)
		{
			livingArmourSockets.addTransientModifier(new AttributeModifier(player.getUUID(), "legacy", Double.valueOf(LivingArmorRegistrar.UPGRADE_CURIOS_SOCKET.get().getBonusValue("slots", curiosLevel).intValue()), AttributeModifier.Operation.ADDITION));
		}
		return curiosLevel;
	} else
	{
		livingArmourSockets.removeModifier(player.getUUID());
		return 0;
	}
}

public void onPlayerTick(Player player) {
	player.level().getProfiler().push("botania:tick_wearables");

	ItemStack[] oldStacks = map.computeIfAbsent(player, p -> {
		ItemStack[] array = new ItemStack[9];
		Arrays.fill(array, ItemStack.EMPTY);
		return array;
	});

	Inventory inv = player.getInventory();
	for (int i = 0; i < 9; i++) {
		ItemStack old = oldStacks[i];
		ItemStack current = inv.getItem(i);

		if (!ItemStack.matches(old, current)) {
			if (old.getItem() instanceof BaubleItem bauble) {
				player.getAttributes().removeAttributeModifiers(bauble.getEquippedAttributeModifiers(old));
				bauble.onUnequipped(old, player);
			}
			if (canEquip(current, player)) {
				BaubleItem bauble = (BaubleItem) current.getItem();
				player.getAttributes().addTransientAttributeModifiers(bauble.getEquippedAttributeModifiers(current));
				bauble.onEquipped(current, player);
			}
			oldStacks[i] = current.copy(); // shift-clicking mutates the stack we stored,
			// making it empty and failing the equality check - let's avoid that
		}

		if (canEquip(current, player)) {
			((BaubleItem) current.getItem()).onWornTick(current, player);
		}
	}
	player.level().getProfiler().pop();
}

