public static int rollNewCooldownStrength(RandomSource random) {
	var total = random.nextInt(COOLDOWN_ROLL_TOTAL);
	var index = 0;
	while (total >= COOLDOWN_ROLL_PDF[index]) {
		total -= COOLDOWN_ROLL_PDF[index];
		index++;
	}
	return index + 1;
}

