public static BlockState getStateForPlacement(BlockState state, LevelAccessor world, BlockPos pos, @Nullable Player player, Direction face) {
    for (Attribute attr : Attribute.getAll(state.typeHolder())) {
        if (attr instanceof AttributeState atr) {
            state = atr.getStateForPlacement(state, world, pos, player, face);
        }
    }
    if (state.getBlock() instanceof IStateFluidLoggable fluidLoggable) {
        FluidState fluidState = world.getFluidState(pos);
        state = fluidLoggable.setState(state, fluidState.getType());
    }
    return state;
}

default ItemStack pickupBlock(@Nullable LivingEntity owner, LevelAccessor world, BlockPos pos, BlockState state) {
    IFluidLogType fluidLogged = state.getValue(getFluidLoggedProperty());
    if (!fluidLogged.isEmpty()) {
        Fluid fluid = fluidLogged.getFluid();
        ItemStack bucket = fluid.getFluidType().getBucket(new FluidStack(fluid, FluidType.BUCKET_VOLUME));
        if (!bucket.isEmpty()) {
            world.setBlock(pos, setState(state, Fluids.EMPTY), Block.UPDATE_ALL);
            return bucket;
        }
    }
    return ItemStack.EMPTY;
}

