        {
            prevFlySpeedMap.put(player.getUUID(), player.getAbilities().getFlyingSpeed());
        }

        if (player.level().isClientSide) {
            player.getAbilities().setFlyingSpeed(getFlySpeedForFlightLevel(amplifier));
        }
        player.onUpdateAbilities();
    }
}

