public void addSecurityTooltip(ItemAccess itemAccess, Item.TooltipContext context, @Nullable Player player, Consumer<Component> builder) {
    addOwnerTooltip(itemAccess, context, player, builder);
    ISecurityObject security = securityCapability(itemAccess);
    if (security != null) {
        Level level = context.level();
        if (level == null && player != null) {
            level = player.level();
        }
        //If we can't determine if the tooltip is being gotten on the client side, just assume it is
        SecurityData data = SecurityUtils.get().getFinalData(security, level == null || level.isClientSide());
        builder.accept(MekanismLang.SECURITY.translateColored(EnumColor.GRAY, data.mode()));
        if (data.override()) {
            builder.accept(MekanismLang.SECURITY_OVERRIDDEN.translateColored(EnumColor.RED));
        }
    }
}

private static void onChangedPotionEffect(LivingEntity entity, MobEffectInstance effectInstance, boolean reapply) {
    entity.effectsDirty = true;
    if (reapply && !entity.level().isClientSide()) {
        MobEffect effect = effectInstance.getEffect().value();
        effect.removeAttributeModifiers(entity.getAttributes());
        effect.addAttributeModifiers(entity.getAttributes(), effectInstance.getAmplifier());
        entity.refreshDirtyAttributes();
    }
    if (!entity.level().isClientSide()) {
        entity.sendEffectToPassengers(effectInstance);
    }
    if (entity instanceof ServerPlayer player) {
        player.connection.send(new ClientboundUpdateMobEffectPacket(entity.getId(), effectInstance, false));
        CriteriaTriggers.EFFECTS_CHANGED.trigger(player, null);
    }
}

