public void setPlacedBy(Level world, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
    super.setPlacedBy(world, pos, state, placer, stack);
    AttributeHasBounding hasBounding = Attribute.get(state, AttributeHasBounding.class);
    if (hasBounding != null) {
        hasBounding.placeBoundingBlocks(world, pos, state);
    }
    TileEntityUpdateable tile = WorldUtils.getTileEntity(TileEntityUpdateable.class, world, pos);
    if (tile != null) {
        //Note: We call onAdded here rather than in onPlace so that we make sure we can run any client side code and that the
        // tile is present
        tile.onAdded(world);
        if (tile instanceof ISecurityTile securityTile && securityTile.getOwnerUUID() == null && placer != null) {
            //There was no stored owner that got set, use the placer's id
            securityTile.setOwnerUUID(placer.getUUID(), null);
            if (!world.isClientSide()) {
                //If the machine doesn't already have an owner, make sure we portray this
                PacketDistributor.sendToAllPlayers(new PacketSyncSecurity(placer.getUUID()));
            }
        }
    }
}

private static void giveItem(ServerPlayer player, ItemStack prototypeItemStack) {
    ItemStack copyToDrop = prototypeItemStack.copy();
    boolean added = player.getInventory().add(copyToDrop);
    if (added && copyToDrop.isEmpty()) {
        ItemEntity drop = player.createItemStackToDrop(prototypeItemStack.copy(), false, false);
        if (drop != null) {
            drop.makeFakeItem();
            drop.level().addFreshEntity(drop);
        }
        player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.ITEM_PICKUP, SoundSource.PLAYERS, 0.2F,
              ((player.getRandom().nextFloat() - player.getRandom().nextFloat()) * 0.7F + 1.0F) * 2.0F);
        player.containerMenu.broadcastChanges();
    } else {
        ItemEntity drop = player.createItemStackToDrop(copyToDrop, false, false);
        if (drop != null) {
            drop.setNoPickUpDelay();
            drop.setTarget(player.getUUID());
            drop.level().addFreshEntity(drop);
        }
    }
}

private static void applyAttributesAndEffects(LooniumMobSpawnData mobSpawnData,
		LooniumStructureConfiguration pickedConfig, Mob mob) {
	List<LooniumMobAttributeModifier> attributeModifiers = mobSpawnData.attributeModifiers != null
			? mobSpawnData.attributeModifiers
			: pickedConfig.attributeModifiers;
	for (LooniumMobAttributeModifier attributeModifier : attributeModifiers) {
		AttributeInstance attribute = mob.getAttribute(attributeModifier.attribute);
		if (attribute != null) {
			attribute.addPermanentModifier(attributeModifier.createAttributeModifier());
			if (attribute.getAttribute() == Attributes.MAX_HEALTH) {
				mob.setHealth(mob.getMaxHealth());
			}
		}
	}

	List<LooniumMobEffectToApply> effectsToApply = mobSpawnData.effectsToApply != null
			? mobSpawnData.effectsToApply
			: pickedConfig.effectsToApply;
	for (LooniumMobEffectToApply effectToApply : effectsToApply) {
		mob.addEffect(effectToApply.createMobEffectInstance());
	}
}

public void tickFlower() {
	super.tickFlower();

	if (getLevel().isClientSide) {
		return;
	}

	for (Creeper entity : getLevel().getEntitiesOfClass(Creeper.class, new AABB(getEffectivePos().offset(-RANGE, -RANGE_Y, -RANGE), getEffectivePos().offset(RANGE + 1, RANGE_Y + 1, RANGE + 1)))) {
		((CreeperAccessor) entity).setCurrentFuseTime(2);
		entity.setTarget(null);

		if (getMana() >= COST) {
			if (pacifyCreeper(entity)) {
				XplatAbstractions.INSTANCE.tigersEyeComponent(entity).setPacified();
				entity.playSound(BotaniaSounds.tigerseyePacify, 1.0F, (level.random.nextFloat() - level.random.nextFloat()) * 0.2F + 1.0F);
				level.blockEvent(getBlockPos(), getBlockState().getBlock(), SUCCESS_EVENT, entity.getId());
				addMana(-COST);
				sync();
			}
		}
	}
}

public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand, BlockHitResult blockRayTraceResult)
{
	TileAltar altar = (TileAltar) world.getBlockEntity(pos);

	if (altar == null || player.isShiftKeyDown())
		return InteractionResult.FAIL;

	ItemStack playerItem = player.getItemInHand(hand);

	if (playerItem.getItem() instanceof IAltarReader)// || playerItem.getItem() instanceof IAltarManipulator)
	{
		playerItem.getItem().use(world, player, hand);
		return InteractionResult.SUCCESS;
	}

	if (Utils.insertItemToTile(altar, player))
		altar.startCycle();
	else
		altar.setActive();

	world.sendBlockUpdated(pos, state, state, 3);
	return InteractionResult.SUCCESS;
}

public int getCurrentActiveSlot()
{
	if (currentActiveSlot == -1)
	{
		currentActiveSlot = 0;
		for (Direction dir : Direction.values())
		{
			BlockPos offsetPos = this.getCurrentBlockPos().relative(dir);
			BlockEntity tile = level.getBlockEntity(offsetPos);
			if (tile != null)
			{
				LazyOptional<IItemHandler> opt = tile.getCapability(ForgeCapabilities.ITEM_HANDLER, dir.getOpposite());
				if (opt != null && opt.isPresent())
				{
					currentActiveSlot = dir.ordinal();
					break;
				}
			}
		}
	}

	return currentActiveSlot;
}

public List<ItemStack> getAllOutputs(RandomSource rand, ItemStack inputStack, ItemStack toolStack, double secondaryBonus)
{
	if (toolStack.isEmpty())
	{
		return super.getAllOutputs(rand, inputStack, toolStack, secondaryBonus);
	}

	List<ItemStack> list = new ArrayList<ItemStack>();
	Collection<MobEffectInstance> collection = PotionUtils.getCustomEffects(toolStack);
	ItemStack outputCopyStack = output.copy();
	PotionUtils.setCustomEffects(outputCopyStack, collection);

	list.add(outputCopyStack);

	for (Pair<ItemStack, Pair<Double, Double>> pair : addedItems)
	{
		Pair<Double, Double> bonus = pair.getRight();
		if (rand.nextDouble() < (bonus.getLeft() + secondaryBonus * bonus.getRight()))
			list.add(pair.getLeft().copy());
	}

	return list;
}

public boolean triggerEvent(int id, int param) {
	switch (id) {
		case SET_KEEP_TICKS_EVENT:
			recipeKeepTicks = param;
			return true;
		case SET_COOLDOWN_EVENT:
			cooldown = param;
			return true;
		case CRAFT_EFFECT_EVENT: {
			if (level.isClientSide) {
				for (int i = 0; i < 25; i++) {
					float red = (float) Math.random();
					float green = (float) Math.random();
					float blue = (float) Math.random();
					SparkleParticleData data = SparkleParticleData.sparkle((float) Math.random(), red, green, blue, 10);
