public void onBurstCollision(ManaBurst burst) {
	ItemStack lens = getItemHandler().getItem(0);
	boolean active = !getBlockState().getValue(BlockStateProperties.POWERED);
	boolean valid = !lens.isEmpty() && lens.getItem() instanceof BasicLensItem && (!(lens.getItem() instanceof TinyPlanetExcempt excempt) || excempt.shouldPull(lens));

	if (active) {
		burst.setSourceLens(valid ? lens.copy() : ItemStack.EMPTY);
		burst.setColor(0xFFFFFF);
		burst.setGravity(0F);

		if (valid) {
			Entity burstEntity = burst.entity();
			BurstProperties properties = new BurstProperties(burst.getStartingMana(), burst.getMinManaLoss(), burst.getManaLossPerTick(), burst.getBurstGravity(), 1F, burst.getColor());

			((BasicLensItem) lens.getItem()).apply(lens, properties, level);

			burst.setColor(properties.color);
			burst.setStartingMana(properties.maxMana);
			burst.setMinManaLoss(properties.ticksBeforeManaLoss);
			burst.setManaLossPerTick(properties.manaLossPerTick);
			burst.setGravity(properties.gravity);
			burstEntity.setDeltaMovement(burstEntity.getDeltaMovement().scale(properties.motionModifier));
		}
	}
}

private static void fillBowlSuspiciously(MushroomCow mushroomCow) {
	MushroomCowAccessor mushroomCowAccessor = (MushroomCowAccessor) mushroomCow;
	MobEffect effect = mushroomCowAccessor.getEffect();
	int effectDuration = mushroomCowAccessor.getEffectDuration();

	Level world = mushroomCow.level();
	List<ItemEntity> bowlItemEntities = world.getEntitiesOfClass(ItemEntity.class, mushroomCow.getBoundingBox(),
			itemEntity -> itemEntity.getItem().is(Items.BOWL) && !itemEntity.getItem().isEmpty());
	for (ItemEntity bowlItemEntity : bowlItemEntities) {
		ItemStack bowlItem = bowlItemEntity.getItem();
		ItemStack stewItem = new ItemStack(Items.SUSPICIOUS_STEW);
		SuspiciousStewItem.saveMobEffect(stewItem, effect, effectDuration);
		spawnItem(mushroomCow, stewItem);

		EntityHelper.shrinkItem(bowlItemEntity);
		if (bowlItem.getCount() == 0) {
			bowlItemEntity.discard();
		}

		// only one suspicious stew per flower fed
		mushroomCowAccessor.setEffect(null);
		mushroomCowAccessor.setEffectDuration(0);
		break;
	}
}

public boolean applyAnointment(AnointmentHolder holder, ItemStack stack, int level)
{
	if (level < 0)
	{
		return false;
	}

	IAttributeProvider prov = this.getAttributeProvider();
	if (prov == null)
	{
		return true;
	}

	Multimap<Attribute, AttributeModifier> modifiers = HashMultimap.create();
	modifiers.putAll(stack.getItem().getAttributeModifiers(EquipmentSlot.MAINHAND, stack));

	this.getAttributeProvider().handleAttributes(holder, modifiers, UUID.nameUUIDFromBytes(this.getKey().toString().getBytes()), this, level);

	for (Entry<Attribute, AttributeModifier> entry : modifiers.entries())
	{
		stack.addAttributeModifier(entry.getKey(), entry.getValue(), EquipmentSlot.MAINHAND);
	}

	return true;
}

public void onEntityUseTick(LivingEntityUseItemEvent.Tick event)
{
	ItemStack stack = event.getItem();
	if (stack.getItem() instanceof BowItem || stack.getItem() instanceof CrossbowItem)
	{
		AnointmentHolder holder = AnointmentHolder.fromItemStack(stack);
		if (holder == null)
		{
			return;
		}
		int quickDrawLevel = holder.getAnointmentLevel(AnointmentRegistrar.ANOINTMENT_QUICK_DRAW.get());
		if (quickDrawLevel > 0)
		{
			double amount = rollMap.getOrDefault(stack, 0D) + AnointmentRegistrar.ANOINTMENT_QUICK_DRAW.get().getBonusValue("speed", quickDrawLevel).doubleValue();
			if (amount >= 1)
			{
				int drawReduction = (int) amount;
				event.setDuration(event.getDuration() - drawReduction);
			} else
			{
				rollMap.put(stack, amount);
			}
		}
	}
}

public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
	ItemStack currentStack = player.getItemInHand(hand);

	if (variant.indestructible && !player.isCreative()) {
		return InteractionResult.PASS;
	}
	if (!currentStack.isEmpty()
			&& Block.byItem(currentStack.getItem()) != Blocks.AIR
			&& world.getBlockEntity(pos) instanceof PlatformBlockEntity camo) {
		BlockPlaceContext ctx = new BlockPlaceContext(player, hand, currentStack, hit);
		BlockState changeState = Block.byItem(currentStack.getItem()).getStateForPlacement(ctx);

		if (changeState != null && !changeState.is(BotaniaTags.Blocks.UNSUPPORTED_PLATFORM_DISGUISE)
				&& (changeState.isSolidRender(world, pos) || changeState.getRenderShape() == RenderShape.MODEL)
				&& !(changeState.getBlock() instanceof PlatformBlock)
				&& !changeState.isAir()) {
			if (!world.isClientSide) {
				camo.setCamoState(changeState);
			}

			return InteractionResult.sidedSuccess(world.isClientSide());
		}
	}

	return InteractionResult.PASS;
}

