public static void serverTick(Level level, BlockPos worldPosition, BlockState state, RunicAltarBlockEntity self) {
	if (self.manaToGet == 0) {
		List<ItemEntity> items = level.getEntitiesOfClass(ItemEntity.class, new AABB(worldPosition, worldPosition.offset(1, 1, 1)));
		for (ItemEntity item : items) {
			if (item.isAlive() && !item.getItem().isEmpty() && !item.getItem().is(BotaniaBlocks.livingrock.asItem())
					&& !XplatAbstractions.INSTANCE.itemFlagsComponent(item).runicAltarSpawned) {
				ItemStack stack = item.getItem();
				if (self.addItem(null, stack, null)) {
					EntityHelper.syncItem(item);
				}
			}
		}
	}

	int newSignal = 0;
	if (self.manaToGet > 0) {
		newSignal++;
		if (self.mana >= self.manaToGet) {
			newSignal++;
		}
	}

	if (newSignal != self.signal) {
		self.signal = newSignal;
		level.updateNeighbourForOutputSignal(worldPosition, state.getBlock());
	}

	self.updateRecipe();
	self.tickCooldown();
}

public void onUpdate()
{
	if (getLevel().isClientSide)
		return;

	if (isPowered() && isActive())
	{
		active = false;
		redstoned = true;
		stopRitual(Ritual.BreakType.REDSTONE);
		return;
	}

	if (!isActive() && !isPowered() && isRedstoned() && getCurrentRitual() != null)
	{
		active = true;
		ItemStack crystalStack = NBTHelper.checkNBT(ItemActivationCrystal.CrystalType.getStack(getCurrentRitual().getCrystalLevel()));
		BindableHelper.applyBinding(crystalStack, new Binding(owner, PlayerHelper.getUsernameFromUUID(owner)));
		activateRitual(crystalStack, null, getCurrentRitual());
		redstoned = false;
	}

	if (getCurrentRitual() != null && isActive())
	{
		if (activeTime % getCurrentRitual().getRefreshTime() == 0)
			performRitual(getLevel(), getBlockPos());

		activeTime++;
	}
}

