public static boolean brainwashEntity(Mob entity, List<Mob> mobs) {
	LivingEntity target = entity.getTarget();
	boolean did = false;

	if (!(target instanceof Enemy)) {
		Mob newTarget;
		do {
			newTarget = mobs.get(entity.level().random.nextInt(mobs.size()));
		} while (newTarget == entity);

		entity.setTarget(null);

		// Move any HurtByTargetGoal to highest priority
		GoalSelector targetSelector = ((MobAccessor) entity).getTargetSelector();
		for (WrappedGoal entry : targetSelector.getAvailableGoals()) {
			if (entry.getGoal() instanceof HurtByTargetGoal goal) {
				// Remove all ignorals. We can't actually resize or overwrite
				// the array, but we can fill it with classes that will never pass
				// the game logic's checks.
				var ignoreClasses = ((HurtByTargetGoalAccessor) goal).getIgnoreDamageClasses();
				Arrays.fill(ignoreClasses, Void.TYPE);

				// Concurrent modification OK since we break out of the loop
				targetSelector.removeGoal(goal);
				targetSelector.addGoal(-1, goal);
				break;
			}
		}

		// Now set last hurt by, which HurtByTargetGoal will pick up
		entity.setLastHurtByMob(newTarget);
		did = true;
	}

	return did;
}

private MethodSpec getFieldGetter(String annotatedName, VariableElement fieldElement) {
    //create and add the MethodHandle field
    FieldSpec fieldGetterHandle = FieldSpec.builder(MethodHandle.class, "fieldGetter$" + annotatedName, Modifier.STATIC, Modifier.PRIVATE)
          .initializer(CodeBlock.of("getGetterHandle($T.class, $S)", containingClassName, annotatedName))
          .build();
    handlerTypeSpec.addField(fieldGetterHandle);

    //build a proxy getter which uses the MethodHandle
    TypeName fieldType = TypeName.get(fieldElement.asType());
    MethodSpec.Builder getterMethodBuilder = MethodSpec.methodBuilder("getter$" + annotatedName)
          .addModifiers(Modifier.STATIC, Modifier.PRIVATE)
          .returns(fieldType)
          //.addException(computerException)
          .beginControlFlow("try");
    //call the MethodHandle
    if (fieldElement.getModifiers().contains(Modifier.STATIC)) {
        getterMethodBuilder
              .addStatement("return ($T)$N.invokeExact()", fieldType, fieldGetterHandle);
    } else {
        getterMethodBuilder
              .addParameter(subjectParam)
              .addStatement("return ($T)$N.invokeExact($N)", fieldType, fieldGetterHandle, subjectParam);
    }
    //catch a failing method handle (throw as RuntimeException)
    getterMethodBuilder.nextControlFlow("catch ($T wmte)", WrongMethodTypeException.class)
          .addStatement("throw new $T($S, wmte)", RuntimeException.class, "Getter not bound correctly")
          //catch other unknown exception and rethrow as RuntimeException
          .nextControlFlow("catch ($T t)", Throwable.class)
          .addStatement("throw new $T(t.getMessage(), t)", RuntimeException.class)
          .endControlFlow();

    //build the proxy and add to the class
    MethodSpec getterMethod = getterMethodBuilder.build();
    handlerTypeSpec.addMethod(getterMethod);
    return getterMethod;
}

private void updateSound(Level level) {
    // If machine sounds are disabled, noop
    if (!hasSound() || !MekanismConfig.client.enableMachineSounds.get() || soundEvent == null) {
        return;
    }
    if (canPlaySound() && !isRemoved()) {
        // If sounds are being muted, we can attempt to start them on every tick, only to have them
        // denied by the event bus, so use a cooldown period that ensures we're only trying once every
        // second or so to start a sound.
        if (--playSoundCooldown > 0) {
            return;
        }
        SoundEvent sound = soundEvent.get();
        if (sound != lastSoundEvent) {
            if (activeSound != null) {
                //The sound changed, stop it so that we can start it back up again
                SoundHandler.stopTileSound(getSoundPos());
                activeSound = null;
            }
            lastSoundEvent = sound;
        }

        // If this machine isn't fully muffled, and we don't seem to be playing a sound for it, go ahead and
        // play it
        if (!isFullyMuffled() && (activeSound == null || !Minecraft.getInstance().getSoundManager().isActive(activeSound))) {
            activeSound = SoundHandler.startTileSound(lastSoundEvent, getSoundCategory(), getInitialVolume(), level.getRandom(), getSoundPos());
        }
        // Always reset the cooldown; either we just attempted to play a sound or we're fully muffled; either way
        // we don't want to try again
        playSoundCooldown = SharedConstants.TICKS_PER_SECOND;
    } else if (activeSound != null) {
        SoundHandler.stopTileSound(getSoundPos());
        activeSound = null;
        playSoundCooldown = 0;
    }
}

public void renderHUD(GuiGraphics gui, Minecraft mc) {
	ItemStack stack = hourglass.getItemHandler().getItem(0);
	if (!stack.isEmpty()) {
		int x = mc.getWindow().getGuiScaledWidth() / 2 + 8;
		int y = mc.getWindow().getGuiScaledHeight() / 2 - 10;

		String first, second;
		if (hourglass.isDust()) {
			first = Integer.toString(hourglass.time);
			second = Integer.toString(hourglass.getTotalTime());
		} else {
			first = StringUtil.formatTickDuration(hourglass.time);
			second = StringUtil.formatTickDuration(hourglass.getTotalTime());
		}
		String timer = String.format("%s / %s", first, second);

		String status = hourglass.lock ? "locked" : "";
		if (!hourglass.move) {
			status = status.isEmpty() ? "stopped" : "lockedStopped";
		}
		if (!status.isEmpty()) {
			status = I18n.get("botaniamisc." + status);
		}

		int textWidth = Math.max(mc.font.width(timer), mc.font.width(status));

		RenderHelper.renderHUDBox(gui, x, y, x + textWidth + 24, y + 22);

		gui.renderFakeItem(stack, x + 2, y + 3);
		gui.renderItemDecorations(mc.font, stack, x + 2, y + 3);

		gui.drawString(mc.font, timer, x + 22, y + 2, hourglass.getColor());
		if (!status.isEmpty()) {
			gui.drawString(mc.font, status, x + 22, y + 12, hourglass.getColor());
		}
	}
}

public void die(@NotNull DamageSource source) {
	super.die(source);
	LivingEntity lastAttacker = getKillCredit();

	if (!level().isClientSide) {
		for (UUID u : playersWhoAttacked) {
			Player player = level().getPlayerByUUID(u);
			if (!isTruePlayer(player)) {
				continue;
			}
			DamageSource currSource = player == lastAttacker ? source : player.damageSources().playerAttack(player);
			if (player != lastAttacker) {
				// Vanilla handles this in attack code, but only for the killer
				CriteriaTriggers.PLAYER_KILLED_ENTITY.trigger((ServerPlayer) player, this, currSource);
			}
			if (!anyWithArmor) {
				GaiaGuardianNoArmorTrigger.INSTANCE.trigger((ServerPlayer) player, this, currSource);
			}
		}

		// Clear wither from nearby players
		for (Player player : getPlayersAround()) {
			if (player.getEffect(MobEffects.WITHER) != null) {
				player.removeEffect(MobEffects.WITHER);
			}
		}

		// Stop all the pixies leftover from the fight
		for (PixieEntity pixie : level().getEntitiesOfClass(PixieEntity.class, getArenaBB(getSource()), p -> p.isAlive() && p.getPixieType() == 1)) {
			pixie.spawnAnim();
			pixie.discard();
		}
		for (MagicLandmineEntity landmine : level().getEntitiesOfClass(MagicLandmineEntity.class, getArenaBB(getSource()))) {
			landmine.discard();
		}
		if ((XplatAbstractions.instance().isRunningCategory(BotaniaSpeedrunCategories.GAIA_I) && !hardMode) ||
				(XplatAbstractions.instance().isRunningCategory(BotaniaSpeedrunCategories.GAIA_II) && hardMode)) {
			XplatAbstractions.instance().completeSpeedrunTimer();
		}
	}

	playSound(BotaniaSounds.gaiaDeath, 1F, (1F + (level().random.nextFloat() - level().random.nextFloat()) * 0.2F) * 0.7F);
	level().addParticle(ParticleTypes.EXPLOSION_EMITTER, getX(), getY(), getZ(), 1D, 0D, 0D);
}

public static void renderRangeHologram(PoseStack stack, MultiBufferSource renderer, TileMasterRitualStone masterRitualStone, float partialTicks)
{
	Camera activerenderinfo = Minecraft.getInstance().gameRenderer.getMainCamera();
	Vec3 eyePos = activerenderinfo.getPosition();
	VertexConsumer buffer = renderer.getBuffer(Sheets.translucentCullBlockSheet());
	LocalPlayer player = minecraft.player;
