	{
		ItemStack itemStack = player.getMainHandItem();
		EnumRitualReaderState state = ((ItemRitualReader) itemStack.getItem()).getState(itemStack);
		if (state == EnumRitualReaderState.SET_AREA)
		{
			String range = ((ItemRitualReader) itemStack.getItem()).getCurrentBlockRange(itemStack);
			AreaDescriptor descriptor = masterRitualStone.getBlockRange(range);
			if (descriptor == null)
			{
				return;
			}

			stack.pushPose();
			BlockPos vec3;
			vec3 = masterRitualStone.getBlockPos();
			AABB aabb = descriptor.getAABB(vec3);
			double sizeOffset = -1d / 16d;
			if (aabb.contains(eyePos))
			{
				sizeOffset *= -1;
			}

			double minX = aabb.minX - eyePos.x + sizeOffset;
			double minY = aabb.minY - eyePos.y + sizeOffset;
			double minZ = aabb.minZ - eyePos.z + sizeOffset;

			stack.translate(minX, minY, minZ);

			ResourceLocation rl = boarder;
			Model3D model = getBlockModelWithSize(rl, aabb.getXsize() - 2 * sizeOffset, aabb.getYsize() - 2 * sizeOffset, aabb.getZsize() - 2 * sizeOffset);
			RenderResizableCuboid.INSTANCE.renderCube(model, stack, buffer, 0x99FF4444, 0x00F000F0, OverlayTexture.NO_OVERLAY);
			stack.popPose();
		}
	}
}

	public void startCycle()
	{
		if (tileAltar.getLevel() != null)
			tileAltar.getLevel().sendBlockUpdated(tileAltar.getBlockPos(), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), 3);

		checkTier();

		// Temporary thing to test the recipes.
//		fluid.setAmount(10000);
//		this.setMainFluid(new FluidStack(BloodMagicBlocks.LIFE_ESSENCE_FLUID.get(), 10000));

		if ((fluid == null || fluid.getAmount() <= 0) && totalCharge <= 0)
			return;

		if (!isActive)
			progress = 0;

		ItemStack input = tileAltar.getItem(0);

		if (!input.isEmpty())
		{
			// Do recipes
			RecipeBloodAltar recipe = BloodMagicAPI.INSTANCE.getRecipeRegistrar().getBloodAltar(tileAltar.getLevel(), input);
			if (recipe != null)
			{
				if (recipe.getMinimumTier() <= altarTier.ordinal())
				{
					this.isActive = true;
					this.recipe = recipe;
					this.liquidRequired = recipe.getSyphon();
					this.consumptionRate = recipe.getConsumeRate();
					this.drainRate = recipe.getDrainRate();
					this.canBeFilled = false;
					return;
				}
			} else if (input.getItem() instanceof IBloodOrb)
			{
				this.isActive = true;
				this.canBeFilled = true;
				return;
			}
		}

		isActive = false;
	}

public boolean process(Set<? extends TypeElement> annotatedTypes, RoundEnvironment roundEnvironment) {
    TypeMirror methodFactoryType = processingEnv.getElementUtils().getTypeElement(MekAnnotationProcessors.COMPUTER_METHOD_FACTORY_ANNOTATION_CLASSNAME).asType();
    TypeSpec.Builder registryType = TypeSpec.classBuilder("ComputerMethodRegistry_" + mekModule())
          .addModifiers(Modifier.PUBLIC)
          .addSuperinterface(methodRegistryInterface);
    boolean hasOriginatingElements = false;

    //this should only ever be 1 annotation
    for (Element element : roundEnvironment.getElementsAnnotatedWithAny(annotatedTypes.toArray(new TypeElement[0]))) {
        if (element instanceof TypeElement factoryTypeEl) {
            //get the annotation mirror for @MethodFactory
            AnnotationMirror annotationMirror = null;
            for (AnnotationMirror am : factoryTypeEl.getAnnotationMirrors()) {
                if (typeUtils().isSameType(am.getAnnotationType(), methodFactoryType)) {
                    annotationMirror = am;
                    break;
                }
            }
            if (annotationMirror == null) {
                processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Couldn't find annotation mirror", factoryTypeEl);
                continue;
            }
            registryType.addOriginatingElement(factoryTypeEl);
            hasOriginatingElements = true;
            AnnotationHelper helper = new AnnotationHelper(processingEnv.getElementUtils(), annotationMirror);
            addHandlerToRegistry((TypeElement) typeUtils().asElement(helper.getClassValue("target")), ClassName.get(factoryTypeEl));
        }
    }

    if (hasOriginatingElements) {
        registryType.addMethod(registryInit.build());
        TypeSpec registrySpec = registryType.build();
        String packageName = "mekanism.generated." + mekModule();
        try {
            JavaFile.builder(packageName, registrySpec).build().writeTo(processingEnv.getFiler());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        try (Writer serviceWriter = processingEnv.getFiler().createResource(StandardLocation.CLASS_OUTPUT, "", "META-INF/services/" + methodRegistryInterface.canonicalName()).openWriter()) {
            serviceWriter.write(packageName + "." + registrySpec.name());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
    return false;
}

protected boolean onUpdateServer(ServerLevel level) {
    boolean sendUpdatePacket = super.onUpdateServer(level);
    delayTicks = Math.max(0, delayTicks - 1);
    if (delayTicks == 6) {
        setActive(false);
    }

    if (canFunction() && delayTicks == 0) {
        ResourceHandler<ItemResource> back = getHomeInventory();
        //If there is no tile to pull from or the push to, skip doing any checks
        if (back != null) {
            Direction direction = getDirection();
            if (targetInventory == null) {
                targetInventory = Capabilities.ITEM.createCache(level, worldPosition.relative(direction), direction.getOpposite());
            }
            ResourceHandler<ItemResource> frontCap = targetInventory.getCapability();
            if (frontCap != null) {
                try (Transaction transaction = Transaction.openRoot()) {
                    TransitResponse response = TransitResponse.EMPTY;
                    for (SorterFilter<?> filter : filterManager.getEnabledFilters()) {
                        TransitRequest request = filter.mapInventory(back, singleItem, transaction);
                        if (request.isEmpty()) {
                            continue;
                        }
                        response = request.eject(this, level, frontCap, !singleItem && filter.sizeMode ? filter.min : 1, filter.color, transaction);
                        if (!response.isEmpty()) {
                            break;
                        }
                    }

                    if (autoEject && response.isEmpty()) {
                        //TODO - 1.21: Evaluate if this (and SorterFilter#mapInventory) should use a stack's max stack size or the absolute stack size
                        TransitRequest request = TransitRequest.definedItem(back, singleItem ? 1 : Item.ABSOLUTE_MAX_STACK_SIZE, strictFinder, transaction);
                        response = request.eject(this, level, frontCap, 1, color, transaction);
                    }
                    if (response.useAll(transaction)) {
                        transaction.commit();
                        setActive(true);
                    }
                }
            }
        }
        delayTicks = MekanismUtils.TICKS_PER_HALF_SECOND;
    }
    return sendUpdatePacket;
}

public void onInteract(PlayerInteractEvent.RightClickItem event)
{
	if (event.getLevel().isClientSide)
		return;

	Player player = event.getEntity();

	if (PlayerHelper.isFakePlayer(player))
		return;

	ItemStack held = event.getItemStack();
	if (!held.isEmpty() && held.getItem() instanceof IBindable)
	{ // Make sure it's bindable
		IBindable bindable = (IBindable) held.getItem();
		Binding binding = bindable.getBinding(held);
		if (binding == null)
		{ // If the binding is null, let's create one
			if (bindable.onBind(player, held))
			{
				ItemBindEvent toPost = new ItemBindEvent(player, held);
				if (MinecraftForge.EVENT_BUS.post(toPost)) // Allow cancellation of binding
					return;

				BindableHelper.applyBinding(held, player); // Bind item to the player
			}
			// If the binding exists, we'll check if the player's name has changed since
			// they last used it and update that if so.
		} else if (binding.getOwnerId().equals(player.getGameProfile().getId()) && !binding.getOwnerName().equals(player.getGameProfile().getName()))
		{
			binding.setOwnerName(player.getGameProfile().getName());
			BindableHelper.applyBinding(held, binding);
		}
	}

	if (!held.isEmpty() && held.getItem() instanceof IBloodOrb)
	{
		IBloodOrb bloodOrb = (IBloodOrb) held.getItem();
		SoulNetwork network = NetworkHelper.getSoulNetwork(player);

		BloodOrb orb = bloodOrb.getOrb(held);
		if (orb == null)
			return;

		if (orb.getTier() > network.getOrbTier())
			network.setOrbTier(orb.getTier());
	}
}

private MethodSpec getMethodProxy(String annotatedName, ExecutableElement executableElement) {
    /* the types of the params for use as $L for the Method(Handle) lookup */
    CodeBlock.Builder paramTypes = CodeBlock.builder();
    //the params of the target method, used as proxy method params
    List<ParameterSpec> proxyParams = new ArrayList<>();

    //non-static methods need a subject as the first param (signature and calling method handle)
    if (!executableElement.getModifiers().contains(Modifier.STATIC)) {
        proxyParams.add(subjectParam);
    }
    //gather the classes and the parameters
    for (VariableElement parameter : executableElement.getParameters()) {
        TypeMirror paramType = parameter.asType();
        paramTypes.add(", $T.class", typeUtils.erasure(paramType));
        proxyParams.add(ParameterSpec.get(parameter));
    }
    CodeBlock builtParamTypes = paramTypes.build();

    //build and add a field to hold the MethodHandle
    FieldSpec methodHandleField = FieldSpec.builder(MethodHandle.class, "method$" + annotatedName, Modifier.STATIC, Modifier.PRIVATE)
          .initializer(CodeBlock.of("getMethodHandle($T.class, $S$L)", containingClassName, annotatedName, builtParamTypes))
          .build();
    handlerTypeSpec.addField(methodHandleField);

    //Build and add the proxy method
    TypeName returnType = TypeName.get(executableElement.getReturnType());
    MethodSpec proxyMethod = MethodSpec.methodBuilder("proxy$" + annotatedName)
          .addParameters(proxyParams)
          .addModifiers(Modifier.STATIC, Modifier.PRIVATE)
          .addException(computerException)
          .returns(returnType)
          .beginControlFlow("try")
          //invoke the method handle
          .addStatement("return ($T)$N.invokeExact($L)", returnType, methodHandleField, proxyParams.stream().map(ParameterSpec::name).collect(Collectors.joining(", ")))
          //catch a failing method handle (throw as RuntimeException)
          .nextControlFlow("catch ($T wmte)", WrongMethodTypeException.class)
          .addStatement("throw new $T($S, wmte)", RuntimeException.class, "Method not bound correctly")
          //catch and rethrow a ComputerException
          .nextControlFlow("catch ($T cex)", computerException)
          .addStatement("throw cex")
          //catch other exceptions and rethrow as a RuntimeException
          .nextControlFlow("catch ($T t)", Throwable.class)
          .addStatement("throw new $T(t.getMessage(), t)", RuntimeException.class)
          .endControlFlow()
          .build();
    handlerTypeSpec.addMethod(proxyMethod);
    return proxyMethod;
}

private void spawnMobs(List<Player> players) {
	for (int pl = 0; pl < playerCount; pl++) {
		for (int i = 0; i < 3 + level().random.nextInt(2); i++) {
			Mob entity = switch (level().random.nextInt(3)) {
				case 0 -> {
					if (level().random.nextInt(hardMode ? 3 : 12) == 0) {
						yield EntityType.WITCH.create(level());
					}
					yield EntityType.ZOMBIE.create(level());
				}
				case 1 -> {
					if (level().random.nextInt(8) == 0) {
						yield EntityType.WITHER_SKELETON.create(level());
					}
					yield EntityType.SKELETON.create(level());
				}
				case 2 -> {
					if (!players.isEmpty()) {
						for (int j = 0; j < 1 + level().random.nextInt(hardMode ? 8 : 5); j++) {
							PixieEntity pixie = new PixieEntity(level());
							pixie.setProps(players.get(random.nextInt(players.size())), this, 1, 8);
							pixie.setPos(getX() + getBbWidth() / 2, getY() + 2, getZ() + getBbWidth() / 2);
							pixie.finalizeSpawn((ServerLevelAccessor) level(), level().getCurrentDifficultyAt(pixie.blockPosition()),
									MobSpawnType.MOB_SUMMONED, null, null);
							level().addFreshEntity(pixie);
						}
					}
					yield null;
				}
				default -> null;
			};

			if (entity != null) {
				if (!entity.fireImmune()) {
					entity.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 600, 0));
				}
				float range = 6F;
				entity.setPos(getX() + 0.5 + Math.random() * range - range / 2, getY() - 1,
						getZ() + 0.5 + Math.random() * range - range / 2);
				entity.finalizeSpawn((ServerLevelAccessor) level(), level().getCurrentDifficultyAt(entity.blockPosition()),
						MobSpawnType.MOB_SUMMONED, null, null);
				if (entity instanceof WitherSkeleton && hardMode) {
					entity.setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(BotaniaItems.elementiumSword));
				}
				level().addFreshEntity(entity);
			}
		}
	}
}

