public void tickFlower() {
	super.tickFlower();

	if (getLevel().isClientSide) {
		return;
	}

	if (cooldown > -1) {
		cooldown--;
	}
	if (digestingMana != 0) {
		int munchInterval = 2 + (2 * lastFoodCount);

		if (cooldown == 0) {
			addMana(digestingMana);
			digestingMana = 0;

			float burpPitch = (float) Math.pow(2.0, (streakLength == 0 ? -lastFoodCount : streakLength) / 12.0);
			//Usage of vanilla sound event: Subtitle is just "Burp", at least in English, and not specific to players.
			getLevel().playSound(null, getEffectivePos(), SoundEvents.PLAYER_BURP, SoundSource.BLOCKS, 1F, burpPitch);
			getLevel().gameEvent(null, GameEvent.BLOCK_DEACTIVATE, getEffectivePos());
			sync();
		} else if (cooldown % munchInterval == 0) {
			//Usage of vanilla sound event: Subtitle is "Eating", generic sounds are meant to be reused.
			getLevel().playSound(null, getEffectivePos(), SoundEvents.GENERIC_EAT, SoundSource.BLOCKS, 0.5F, 1F);

			Vec3 offset = getLevel().getBlockState(getEffectivePos()).getOffset(getLevel(), getEffectivePos()).add(0.4, 0.6, 0.4);

			((ServerLevel) getLevel()).sendParticles(new ItemParticleOption(ParticleTypes.ITEM, lastFoods.get(0)), getEffectivePos().getX() + offset.x, getEffectivePos().getY() + offset.y, getEffectivePos().getZ() + offset.z, 10, 0.1D, 0.1D, 0.1D, 0.03D);
		}
	}

	List<ItemEntity> items = getLevel().getEntitiesOfClass(ItemEntity.class, new AABB(getEffectivePos().offset(-RANGE, -RANGE, -RANGE), getEffectivePos().offset(RANGE + 1, RANGE + 1, RANGE + 1)));

	for (ItemEntity item : items) {
		ItemStack stack = item.getItem();

		if (DelayHelper.canInteractWithImmediate(this, item) && stack.getItem().isEdible()) {
			if (cooldown <= 0) {
				streakLength = Math.min(streakLength + 1, processFood(stack));

				int val = getFoodValue(stack);
				digestingMana = getDigestingMana(val, getMultiplierForStreak(streakLength));
				cooldown = getCooldown(val);
				//Usage of vanilla sound event: Subtitle is "Eating", generic sounds are meant to be reused.
				item.playSound(SoundEvents.GENERIC_EAT, 0.2F, 0.6F);
				getLevel().gameEvent(null, GameEvent.EAT, item.position());
				getLevel().gameEvent(null, GameEvent.BLOCK_ACTIVATE, getEffectivePos());
				sync();
				((ServerLevel) getLevel()).sendParticles(new ItemParticleOption(ParticleTypes.ITEM, stack), item.getX(), item.getY(), item.getZ(), 20, 0.1D, 0.1D, 0.1D, 0.05D);
			}

			item.discard();
		}
	}
}

public static void render(PetalApothecaryBlockEntity altar, GuiGraphics gui, Minecraft mc) {
	int xc = mc.getWindow().getGuiScaledWidth() / 2;
	int yc = mc.getWindow().getGuiScaledHeight() / 2;

	float angle = -90;
	int radius = 24;
	int amt = 0;
	for (int i = 0; i < altar.inventorySize(); i++) {
		if (altar.getItemHandler().getItem(i).isEmpty()) {
			break;
		}
		amt++;
	}

	if (amt > 0) {
		float anglePer = 360F / amt;

		Optional<PetalApothecaryRecipe> maybeRecipe = altar.level.getRecipeManager()
				.getRecipeFor(BotaniaRecipeTypes.PETAL_TYPE, altar.getItemHandler(), altar.level);
		maybeRecipe.ifPresent(recipe -> {
			RenderSystem.setShaderColor(1F, 1F, 1F, 1F);
			RenderHelper.drawTexturedModalRect(gui, HUDHandler.manaBar, xc + radius + 9, yc - 8, 0, 8, 22, 15);

			ItemStack stack = recipe.assemble(altar.getItemHandler(), altar.getLevel().registryAccess());
			gui.renderFakeItem(stack, xc + radius + 32, yc - 8);

			var reagents = recipe.getReagent().getItems();
			ItemStack reagent;
			if (reagents.length == 0) {
				reagent = new ItemStack(Items.BARRIER);
			} else {
				int idx = (int) ((altar.level.getGameTime() / 20) % reagents.length);
				reagent = reagents[idx];
			}
			gui.renderFakeItem(reagent, xc + radius + 16, yc + 6);
			gui.drawString(mc.font, "+", xc + radius + 14, yc + 10, 0xFFFFFF, false);
		});

		for (int i = 0; i < amt; i++) {
			double xPos = xc + Math.cos(angle * Math.PI / 180D) * radius - 8;
			double yPos = yc + Math.sin(angle * Math.PI / 180D) * radius - 8;
			PoseStack pose = RenderSystem.getModelViewStack();
			pose.pushPose();
			pose.translate(xPos, yPos, 0);
			RenderSystem.applyModelViewMatrix();
			gui.renderFakeItem(altar.getItemHandler().getItem(i), 0, 0);
			pose.popPose();
			RenderSystem.applyModelViewMatrix();

			angle += anglePer;
		}
	}
	if (altar.recipeKeepTicks > 0 && altar.canAddLastRecipe()) {
		String s = I18n.get("botaniamisc.altarRefill0");
		gui.drawString(mc.font, s, xc - mc.font.width(s) / 2, yc + 10, 0xFFFFFF, false);
		s = I18n.get("botaniamisc.altarRefill1");
		gui.drawString(mc.font, s, xc - mc.font.width(s) / 2, yc + 20, 0xFFFFFF, false);
	}
}

private void feedAnimal(List<Animal> animals, List<ItemEntity> items) {
	// randomize animals with same age
	Collections.shuffle(animals);
	// feed adults first, then babies, youngest to oldest
	animals.sort(Comparator.comparing(Animal::isBaby).thenComparingInt(animal -> Math.min(animal.getAge(), 0)));

	boolean did = false;
	for (Animal animal : animals) {
		// Note: Empty item stacks are implicitly excluded in Animal::isFood and ItemStack::is(TagKey)
		if (animal.getAge() == 0 && !animal.isInLove() || animal.getAge() < -600 && -animal.getAge() % 100 == 0) {
			for (ItemEntity item : items) {
				if (!animal.isFood(item.getItem())) {
					continue;
				}
				consumeFoodItemAndMana(item);
				did = true;

				if (animal.isBaby()) {
					animal.ageUp(AgeableMob.getSpeedUpSecondsWhenFeeding(-animal.getAge()), true);
				} else {
					animal.setInLoveTime(1200);
					((AnimalAccessor) animal).botania_setLoveCause(null);
				}
				getLevel().broadcastEntityEvent(animal, EntityEvent.IN_LOVE_HEARTS);
				break;
			}

			if (getMana() < MANA_COST) {
				break;
			}
		}

		if (!animal.isBaby() && isBrownMooshroomWithoutEffect(animal)) {
			for (ItemEntity item : items) {
				ItemStack stack = item.getItem();
				if (!stack.is(ItemTags.SMALL_FLOWERS)) {
					continue;
				}
				var effect = SuspiciousEffectHolder.tryGet(stack.getItem());
				if (effect == null) {
					continue;
				}
				consumeFoodItemAndMana(item);
				did = true;

				MushroomCowAccessor cowAccessor = (MushroomCowAccessor) animal;
				cowAccessor.setEffect(effect.getSuspiciousEffect());
				cowAccessor.setEffectDuration(effect.getEffectDuration());
				animal.playSound(SoundEvents.MOOSHROOM_EAT, 2.0F, 1.0F);
				break;
			}

			if (getMana() < MANA_COST) {
				break;
			}
		}
	}
	if (did) {
		sync();
	}
}

public static void commonTick(Level level, BlockPos worldPosition, BlockState state, IncensePlateBlockEntity self) {
	ItemStack stack = self.getItemHandler().getItem(0);
	if (!stack.isEmpty() && self.burning) {
		if (state.getValue(BlockStateProperties.WATERLOGGED) && self.timeLeft > 1) {
			self.timeLeft = 1;
			self.spawnSmokeParticles();
		}

		Brew brew = ((IncenseStickItem) BotaniaItems.incenseStick).getBrew(stack);
		MobEffectInstance effect = brew.getPotionEffects(stack).get(0);
		if (self.timeLeft > 0) {
			self.timeLeft--;
			if (!level.isClientSide) {
				List<Player> players = level.getEntitiesOfClass(Player.class, new AABB(worldPosition.getX() + 0.5 - RANGE, worldPosition.getY() + 0.5 - RANGE, worldPosition.getZ() + 0.5 - RANGE, worldPosition.getX() + 0.5 + RANGE, worldPosition.getY() + 0.5 + RANGE, worldPosition.getZ() + 0.5 + RANGE));
				for (Player player : players) {
					MobEffectInstance currentEffect = player.getEffect(effect.getEffect());
					boolean nightVision = effect.getEffect() == MobEffects.NIGHT_VISION;
					if (currentEffect == null || currentEffect.getDuration() < (nightVision ? 205 : 3)) {
						MobEffectInstance applyEffect = new MobEffectInstance(effect.getEffect(), nightVision ? 285 : 80, effect.getAmplifier(), true, true);
						player.addEffect(applyEffect);
					}
				}

				if (level.random.nextInt(20) == 0) {
					level.playSound(null, worldPosition, SoundEvents.FIRE_AMBIENT, SoundSource.BLOCKS, 0.1F, 1);
				}
			} else {
				double x = worldPosition.getX() + 0.5;
				double y = worldPosition.getY() + 0.5;
				double z = worldPosition.getZ() + 0.5;

				int color = brew.getColor(stack);
				float r = (color >> 16 & 0xFF) / 255F;
				float g = (color >> 8 & 0xFF) / 255F;
				float b = (color & 0xFF) / 255F;

				WispParticleData data1 = WispParticleData.wisp(0.05F + (float) Math.random() * 0.02F, r, g, b);
				level.addParticle(data1, x - (Math.random() - 0.5) * 0.2, y - (Math.random() - 0.5) * 0.2, z - (Math.random() - 0.5) * 0.2, 0.005F - (float) Math.random() * 0.01F, 0.01F + (float) Math.random() * 0.005F, 0.005F - (float) Math.random() * 0.01F);
				WispParticleData data = WispParticleData.wisp(0.05F + (float) Math.random() * 0.02F, 0.2F, 0.2F, 0.2F);
				level.addParticle(data, x - (Math.random() - 0.5) * 0.2, y - (Math.random() - 0.5) * 0.2, z - (Math.random() - 0.5) * 0.2, 0.005F - (float) Math.random() * 0.01F, 0.01F + (float) Math.random() * 0.001F, 0.005F - (float) Math.random() * 0.01F);
			}
		} else {
			self.getItemHandler().setItem(0, ItemStack.EMPTY);
			self.burning = false;
			level.gameEvent(null, GameEvent.BLOCK_DEACTIVATE, worldPosition);
			VanillaPacketDispatcher.dispatchTEToNearbyPlayers(self);
		}
	} else {
		self.timeLeft = 0;
	}

	int newComparator = 0;
	if (!stack.isEmpty()) {
		newComparator = 1;
	}
	if (self.burning) {
		newComparator = 2;
	}
	if (self.comparatorOutput != newComparator) {
		self.comparatorOutput = newComparator;
		level.updateNeighbourForOutputSignal(worldPosition, state.getBlock());
		self.setChanged();
	}
}

public void readAdditionalSaveData(CompoundTag cmp) {
	super.readAdditionalSaveData(cmp);
	setTicksExisted(cmp.getInt(TAG_TICKS_EXISTED));
	setColor(cmp.getInt(TAG_COLOR));
	setMana(cmp.getInt(TAG_MANA));
	setStartingMana(cmp.getInt(TAG_STARTING_MANA));
	setMinManaLoss(cmp.getInt(TAG_MIN_MANA_LOSS));
	setManaLossPerTick(cmp.getFloat(TAG_TICK_MANA_LOSS));
	setGravity(cmp.getFloat(TAG_GRAVITY));

	CompoundTag lensCmp = cmp.getCompound(TAG_LENS_STACK);
	ItemStack stack = ItemStack.of(lensCmp);
	if (!stack.isEmpty()) {
		setSourceLens(stack);
	} else {
		setSourceLens(ItemStack.EMPTY);
	}

	int x = cmp.getInt(TAG_SPREADER_X);
	int y = cmp.getInt(TAG_SPREADER_Y);
	int z = cmp.getInt(TAG_SPREADER_Z);
	BlockPos sourceCoords = new BlockPos(x, y, z);
	if (NO_SOURCE.equals(sourceCoords)) {
		setBurstSource(null);
	} else {
		ResourceLocation dim = cmp.contains(TAG_SPREADER_DIM) ? ResourceLocation.tryParse(cmp.getString(TAG_SPREADER_DIM)) : null;
		setBurstSource(GlobalPos.of(dim != null ? ResourceKey.create(Registries.DIMENSION, dim) : level().dimension(), sourceCoords));
	}

	if (cmp.contains(TAG_LAST_COLLISION_X)) {
		x = cmp.getInt(TAG_LAST_COLLISION_X);
		y = cmp.getInt(TAG_LAST_COLLISION_Y);
		z = cmp.getInt(TAG_LAST_COLLISION_Z);
		lastCollision = new BlockPos(x, y, z);
	}

	// Reread Motion because Entity.load clamps it to +/-10
	ListTag motion = cmp.getList("Motion", Tag.TAG_DOUBLE);
	setDeltaMovement(motion.getDouble(0), motion.getDouble(1), motion.getDouble(2));

	boolean hasShooter = cmp.getBoolean(TAG_HAS_SHOOTER);
	if (hasShooter) {
		UUID serializedUuid = cmp.getUUID(TAG_SHOOTER);
		UUID identity = getShooterUUID();
		if (!serializedUuid.equals(identity)) {
			setShooterUUID(serializedUuid);
		}
	}
	warped = cmp.getBoolean(TAG_WARPED);
	orbitTime = cmp.getInt(TAG_ORBIT_TIME);
	tripped = cmp.getBoolean(TAG_TRIPPED);
	if (cmp.contains(TAG_MAGNETIZE_POS)) {
		magnetizePos = BlockPos.CODEC.parse(NbtOps.INSTANCE, cmp.get(TAG_MAGNETIZE_POS)).get().orThrow();
	} else {
		magnetizePos = null;
	}
	entityData.set(LEFT_SOURCE_POS, cmp.getBoolean(TAG_LEFT_SOURCE));

	this.alreadyCollidedAt.clear();
	for (var tag : cmp.getList(TAG_ALREADY_COLLIDED_AT, Tag.TAG_INT_ARRAY)) {
		var pos = BlockPos.CODEC.parse(NbtOps.INSTANCE, tag).result();
		pos.ifPresent(this.alreadyCollidedAt::add);
	}
}

public boolean activateRitual(ItemStack activationCrystal, @Nullable Player activator, Ritual ritual)
{
	if (PlayerHelper.isFakePlayer(activator))
		return false;

	Binding binding = ((IBindable) activationCrystal.getItem()).getBinding(activationCrystal);
	if (binding != null && ritual != null)
	{
		if (activationCrystal.getItem() instanceof ItemActivationCrystal)
		{
			int crystalLevel = ((ItemActivationCrystal) activationCrystal.getItem()).getCrystalLevel(activationCrystal);
			if (RitualHelper.canCrystalActivate(ritual, crystalLevel))
			{
				if (!getLevel().isClientSide)
				{
					SoulNetwork network = NetworkHelper.getSoulNetwork(binding);

					if (!isRedstoned() && network.getCurrentEssence() < ritual.getActivationCost() && (activator != null && !activator.isCreative()))
					{
						activator.displayClientMessage(Component.translatable("chat.bloodmagic.ritual.weak"), true);
						return false;
					}

					if (currentRitual != null)
						currentRitual.stopRitual(this, Ritual.BreakType.ACTIVATE);

					RitualEvent.RitualActivatedEvent event = new RitualEvent.RitualActivatedEvent(this, binding.getOwnerId(), ritual, activator, activationCrystal, crystalLevel);

					if (MinecraftForge.EVENT_BUS.post(event))
					{
						if (activator != null)
							activator.displayClientMessage(Component.translatable("chat.bloodmagic.ritual.prevent"), true);
						return false;
					}

					if (ritual.activateRitual(this, activator, binding.getOwnerId()))
					{
						if (!isRedstoned() && (activator != null && !activator.isCreative()))
							network.syphon(ticket(ritual.getActivationCost()));

						if (activator != null)
							activator.displayClientMessage(Component.translatable("chat.bloodmagic.ritual.activate"), true);

						this.active = true;
						this.owner = binding.getOwnerId();
						this.cachedNetwork = network;
						this.currentRitual = ritual;

						if (!checkBlockRanges(ritual.getModableRangeMap()))
							addBlockRanges(ritual.getModableRangeMap());

						notifyUpdate();
						this.setChanged();
						return true;
					}
				}

				notifyUpdate();
				return true;
			}
		}
	} else
	{
		if (activator != null)
			activator.displayClientMessage(Component.translatable("chat.bloodmagic.ritual.notValid"), true);
	}

	return false;
}

	public void update()
	{
//		World world = tileAltar.getWorld();
//
//		RecipeBloodAltar recipe = BloodMagicAPI.INSTANCE.getRecipeRegistrar().getBloodAltar(world, new ItemStack(Items.DIAMOND));
//
//		if (recipe != null)
//		{
//			System.out.println("Found a recipe!");
//		}
//
//		List<RecipeBloodAltar> altarRecipes = world.getRecipeManager().getRecipesForType(BloodMagicRecipeType.ALTAR);
//
//		System.out.println("There are currently " + altarRecipes.size() + " Altar Recipes loaded.");
//
//		this.fluidInput = new FluidStack(BloodMagicBlocks.LIFE_ESSENCE_FLUID.get(), 1000);

//		System.out.println(this.fluidOutput.getAmount());

		Level world = tileAltar.getLevel();
		BlockPos pos = tileAltar.getBlockPos();

		if (world.isClientSide)
			return;

		// Used instead of the world time for checks that do not happen every tick
		internalCounter++;

		if (lockdownDuration > 0)
			lockdownDuration--;

		if (internalCounter % 20 == 0)
		{
			for (Direction facing : Direction.values())
			{
				BlockPos newPos = pos.relative(facing);
				BlockState block = world.getBlockState(newPos);
				block.getBlock().onNeighborChange(block, world, newPos, pos);
			}
		}
		if (internalCounter % (Math.max(20 - this.accelerationUpgrades, 1)) == 0)
		{
			int syphonMax = (int) (20 * this.dislocationMultiplier);
			int fluidInputted;
			int fluidOutputted;
			fluidInputted = Math.min(syphonMax, -this.fluid.getAmount() + capacity);
			fluidInputted = Math.min(this.fluidInput.getAmount(), fluidInputted);
			this.fluid.setAmount(this.fluid.getAmount() + fluidInputted);
			this.fluidInput.setAmount(this.fluidInput.getAmount() - fluidInputted);
			fluidOutputted = Math.min(syphonMax, this.bufferCapacity - this.fluidOutput.getAmount());
			fluidOutputted = Math.min(this.fluid.getAmount(), fluidOutputted);
			this.fluidOutput.setAmount(this.fluidOutput.getAmount() + fluidOutputted);
			this.fluid.setAmount(this.fluid.getAmount() - fluidOutputted);
			tileAltar.getLevel().sendBlockUpdated(tileAltar.getBlockPos(), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), 3);
		}

		if (internalCounter % this.getChargingFrequency() == 0 && !this.isActive)
		{
			int chargeInputted = Math.min(chargingRate, this.fluid.getAmount());
			chargeInputted = Math.min(chargeInputted, maxCharge - totalCharge);
			totalCharge += chargeInputted;
			this.fluid.setAmount(this.fluid.getAmount() - chargeInputted);
			tileAltar.getLevel().sendBlockUpdated(tileAltar.getBlockPos(), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), 3);
		}

		if (internalCounter % 100 == 0 && (this.isActive || this.cooldownAfterCrafting <= 0))
			startCycle();

		updateAltar();
	}

	public ItemStack getOutput(ItemStack flaskStack, List<EffectHolder> flaskEffectList)
	{
		ItemStack copyStack = flaskStack.copy();

		boolean savePotencies = outputEffectList.size() == 1 && inputEffectList.size() == 1;
		int amplifier = 0;
		double ampDurMod = 1;
		double lengthDurMod = 1;

		// Remove inputs
		List<EffectHolder> flaskEffectCopyList = new ArrayList<>(flaskEffectList);
		for (int i = 0; i < inputEffectList.size(); i++)
		{
			MobEffect inputEffect = inputEffectList.get(i);
//			int outputBaseDuration = outputEffectList.get(i).getValue();

			for (int j = 0; j < flaskEffectCopyList.size(); j++)
			{
				EffectHolder flaskEffect = flaskEffectCopyList.get(j);
				if (flaskEffect.getPotion().equals(inputEffect))
				{
					if (savePotencies)
					{
						amplifier = flaskEffect.getAmplifier();
						ampDurMod = flaskEffect.getAmpDurationMod();
						lengthDurMod = flaskEffect.getLengthDurationMod();
					}

					flaskEffectCopyList.remove(j);
					break;
				}
			}
		}

		// Check if the outputs already exist in here. If it does, check/change the
		// duration
		boolean[] alreadyAddedArray = new boolean[outputEffectList.size()];

		outputLoop: for (int i = 0; i < outputEffectList.size(); i++)
		{
			MobEffect outputEffect = outputEffectList.get(i).getKey();
			int outputBaseDuration = outputEffectList.get(i).getValue();

			for (int j = 0; j < flaskEffectCopyList.size(); j++)
			{
				EffectHolder flaskEffect = flaskEffectCopyList.get(j);
				if (flaskEffect.getPotion().equals(outputEffect))
				{
					alreadyAddedArray[i] = true;
					if (flaskEffect.getBaseDuration() < outputBaseDuration)
					{
						flaskEffect.setBaseDuration(outputBaseDuration);
					}

					continue outputLoop;
				}
			}

			alreadyAddedArray[i] = false;
		}

		for (int i = 0; i < outputEffectList.size(); i++)
		{
			flaskEffectCopyList.add(new EffectHolder(outputEffectList.get(i).getKey(), outputEffectList.get(i).getValue(), amplifier, ampDurMod, lengthDurMod));
		}

		((ItemAlchemyFlask) copyStack.getItem()).setEffectHoldersOfFlask(copyStack, flaskEffectCopyList);

		return copyStack;
	}

public static void commonTick(Level level, BlockPos worldPosition, BlockState state, BellowsBlockEntity self) {
	boolean disable = true;
	BlockEntity tile = self.getLinkedTile();
	if (!self.active && tile instanceof ManaPoolBlockEntity pool) {
		boolean transfer = pool.isDoingTransfer;
		if (transfer) {
			if (pool.ticksDoingTransfer > 0) {
				self.setActive(true);
			}
			disable = false;
		}
	}

	float max = 0.9F;
	float min = 0F;

	float incr = max / 20F;

	if (self.movePos < max && self.active && self.moving >= 0F) {
		if (self.moving == 0F) {
			if (!level.isClientSide()) {
				level.gameEvent(null, GameEvent.BLOCK_ACTIVATE, worldPosition);
			}
			level.playSound(null, worldPosition, BotaniaSounds.bellows, SoundSource.BLOCKS, 1F, 1F);
		}

		if (tile instanceof AbstractFurnaceBlockEntity furnace) {
			if (ExoflameFurnaceHandler.canSmelt(furnace)) {
				AbstractFurnaceBlockEntityAccessor mFurnace = (AbstractFurnaceBlockEntityAccessor) furnace;
				mFurnace.setCookingProgress(Math.min(mFurnace.getCookingTotalTime() - 1, mFurnace.getCookingProgress() + 20));
				mFurnace.setLitTime(Math.max(0, mFurnace.getLitTime() - 10));
			}

			if (furnace instanceof FurnaceBlockEntity
					&& furnace.hasLevel() && furnace.getBlockState().getValue(FurnaceBlock.LIT)) {
				// [VanillaCopy] FurnaceBlock
				double d0 = (double) worldPosition.getX() + 0.5D;
				double d1 = (double) worldPosition.getY();
				double d2 = (double) worldPosition.getZ() + 0.5D;
				// Botania: no playSound

				Direction enumfacing = furnace.getBlockState().getValue(FurnaceBlock.FACING);
				Direction.Axis enumfacing$axis = enumfacing.getAxis();
				double d3 = 0.52D;
				double d4 = level.random.nextDouble() * 0.6D - 0.3D;
				double d5 = enumfacing$axis == Direction.Axis.X ? (double) enumfacing.getStepX() * 0.52D : d4;
				double d6 = level.random.nextDouble() * 6.0D / 16.0D;
				double d7 = enumfacing$axis == Direction.Axis.Z ? (double) enumfacing.getStepZ() * 0.52D : d4;
				level.addParticle(ParticleTypes.SMOKE, d0 + d5, d1 + d6, d2 + d7, 0.0D, 0.0D, 0.0D);
				level.addParticle(ParticleTypes.FLAME, d0 + d5, d1 + d6, d2 + d7, 0.0D, 0.0D, 0.0D);
			}
		}

		self.movePos += incr * 3;
		self.moving = incr * 3;
		if (self.movePos >= max) {
			self.movePos = Math.min(max, self.movePos);
			self.moving = 0F;
			if (disable) {
				self.setActive(false);
			}
		}
	} else if (self.movePos > min) {
		self.movePos -= incr;
		self.moving = -incr;
		if (self.movePos <= min) {
			self.movePos = Math.max(min, self.movePos);
			self.moving = 0F;
		}
	}

}

public void tickFlower() {
	super.tickFlower();

	if (burnTime == 0 && cooldown > 0) {
		cooldown--;
		for (int i = 0; i < 3; i++) {
			WispParticleData data = WispParticleData.wisp((float) Math.random() / 6, 0.1F, 0.1F, 0.1F, 1);
			emitParticle(data, 0.5 + Math.random() * 0.2 - 0.1, 0.5 + Math.random() * 0.2 - 0.1, 0.5 + Math.random() * 0.2 - 0.1, 0, (float) Math.random() / 30, 0);
		}
	}

	if (!getLevel().isClientSide) {
		if (burnTime > 0 && ticksExisted % getGenerationDelay() == 0) {
			addMana(manaPerTick);
			sync();
		}
	}

	if (burnTime == 0) {
		if (getMana() < getMaxMana() && !getLevel().isClientSide) {
			List<BlockPos> offsets = Arrays.asList(OFFSETS);
			Collections.shuffle(offsets);

			for (BlockPos offset : offsets) {
				BlockPos pos = getEffectivePos().offset(offset);

				BlockState bstate = getLevel().getBlockState(pos);
				FluidState fstate = getLevel().getFluidState(pos);
				if (fstate.is(consumedFluid) && fstate.isSource()) {
					if (consumedFluid != FluidTags.WATER) {
						getLevel().setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());
					} else {
						int waterAround = 0;
						for (Direction dir : Direction.values()) {
							if (getLevel().getFluidState(pos.relative(dir)).is(consumedFluid)) {
								waterAround++;
							}
						}

						if (waterAround < 2) {
							if (bstate.getBlock() instanceof BucketPickup bucketPickup) {
								bucketPickup.pickupBlock(getLevel(), pos, bstate);
							} else {
								getLevel().setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());
							}
							getLevel().gameEvent(null, GameEvent.FLUID_PICKUP, pos);
						}
					}

					if (cooldown == 0) {
						burnTime += startBurnTime;
						cooldown = getCooldownTime(true);
						getLevel().gameEvent(null, GameEvent.BLOCK_ACTIVATE, getBlockPos());
					} else {
						cooldown = getCooldownTime(false);
					}

					setChanged();
					sync();
					playSound();
					break;
				}
			}
		}
	} else {
		if (getLevel().random.nextInt(8) == 0) {
			doBurnParticles();
		}
		burnTime--;
		if (burnTime == 0) {
			getLevel().gameEvent(null, GameEvent.BLOCK_DEACTIVATE, getBlockPos());
			setChanged();
			sync();
		}
	}
}

	public void onBreakBlock(BlockEvent.BreakEvent event)
	{
		Player player = event.getPlayer();
		if (player != null)
		{
			if (LivingUtil.hasFullSet(player))
			{
				LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_DIGGING.get(), 1);
				LivingStats stats = LivingStats.fromPlayer(player);
				int mineTime = LivingArmorRegistrar.UPGRADE_DIGGING.get().getBonusValue("speed_time", stats.getLevel(LivingArmorRegistrar.UPGRADE_DIGGING.get().getKey())).intValue();
				if (mineTime > 0)
				{
					player.addEffect(new MobEffectInstance(MobEffects.DIG_SPEED, mineTime, LivingArmorRegistrar.UPGRADE_DIGGING.get().getBonusValue("speed_level", stats.getLevel(LivingArmorRegistrar.UPGRADE_DIGGING.get().getKey())).intValue(), true, false));
				}
			}

			ItemStack heldStack = player.getMainHandItem();
			AnointmentHolder holder = AnointmentHolder.fromItemStack(heldStack);

			if (holder != null)
			{
				boolean hasAnointmentChanged = false;

				if (holder.getAnointmentLevel(AnointmentRegistrar.ANOINTMENT_SILK_TOUCH.get()) >= 1)
				{
					int bonusLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.BLOCK_FORTUNE, player.getMainHandItem());
					int exp = event.getState().getExpDrop(event.getLevel(), event.getLevel().getRandom(), event.getPos(), bonusLevel, holder.getAnointmentLevel(AnointmentRegistrar.ANOINTMENT_SILK_TOUCH.get()));
					event.setExpToDrop(exp);
				}

				int hiddenLevel = holder.getAnointmentLevel(AnointmentRegistrar.ANOINTMENT_HIDDEN_KNOWLEDGE.get());
				if (hiddenLevel > 0)
				{
					double expBonus = AnointmentRegistrar.ANOINTMENT_HIDDEN_KNOWLEDGE.get().getBonusValue("exp", hiddenLevel).doubleValue();

					if (event.getExpToDrop() > 0 && expBonus > 0)
					{
						int expAdded = (int) expBonus + (expBonus % 1 > event.getLevel().getRandom().nextDouble() ? 1
								: 0);
						event.setExpToDrop(event.getExpToDrop() + expAdded);

						if (holder.consumeAnointmentDurability(heldStack, EquipmentSlot.MAINHAND, AnointmentRegistrar.ANOINTMENT_HIDDEN_KNOWLEDGE.get(), player))
						{
							hasAnointmentChanged = true;
						}
					}
				}

				int repairLevel = holder.getAnointmentLevel(AnointmentRegistrar.ANOINTMENT_WEAPON_REPAIR.get());
				if (repairLevel > 0)
				{
					if (heldStack.isDamageableItem() && heldStack.isDamaged())
					{
						double expBonus = AnointmentRegistrar.ANOINTMENT_WEAPON_REPAIR.get().getBonusValue("exp", repairLevel).doubleValue();

						double repairRatio = heldStack.getXpRepairRatio();
						double durabilityBonus = Math.min(expBonus / repairRatio, heldStack.getDamageValue());
						int durabilityAdded = (int) durabilityBonus + (durabilityBonus % 1 > event.getLevel().getRandom().nextDouble()
								? 1
								: 0);
						if (durabilityAdded > 0)
							heldStack.setDamageValue(Math.max(0, heldStack.getDamageValue() - durabilityAdded));

						if (holder.consumeAnointmentDurability(heldStack, EquipmentSlot.MAINHAND, AnointmentRegistrar.ANOINTMENT_WEAPON_REPAIR.get(), player))
						{
							hasAnointmentChanged = true;
						}
					}
				}

                if (heldStack.is(BloodMagicTags.CHARGES)) {
                    return;
                }
				if (holder.consumeAnointmentDurabilityOnHarvest(heldStack, EquipmentSlot.MAINHAND, player) || hasAnointmentChanged) {
                    holder.toItemStack(heldStack);
                }
			}
		}
	}

protected boolean onUpdateServer(ServerLevel level) {
    boolean sendUpdatePacket = super.onUpdateServer(level);
    closeInvalidScreens();
    if (!initCalc) {
        //If it had finished searching, and we didn't initialize things yet,
        // reset it and start running again if needed. This happens after saving the miner to disk
        if (searcher.state == State.FINISHED) {
            boolean prevRunning = running;
            reset();
            start(level);
            running = prevRunning;
        }
        initCalc = true;
    }

    energySlot.fillContainerOrConvert(null);

    if (recheckOverflow) {
        //Try adding any overflow stacks we have before we actually try to process as if we have some overflow we can't add
        // then we will skip functioning and avoid draining energy.
        // Note: We may not have any overflow stacks, in which case this will effectively NO-OP
        // We also mark needing to recheck if the overflow can fit as false as we will know if we can or can't currently add it all
        try (Transaction transaction = Transaction.openRoot()) {
            tryAddOverflow(transaction);
            transaction.commit();
        }
    }

    boolean isActive = false;

    //Note: If we have any overflow don't function or use any energy until the overflow has been dealt with
    if (!hasOverflow && canFunction() && running && searcher.state == State.FINISHED && !oresToMine.isEmpty()) {
        int energyPerTick = energyContainer.getEnergyPerTick();
        try (Transaction transaction = Transaction.openRoot()) {
            if (energyContainer.extract(energyPerTick, transaction, AutomationType.INTERNAL) == energyPerTick) {
                isActive = true;
                if (delay > 0) {
                    delay--;
                }
                //TODO: Eventually we may want to avoid draining energy if we can't function due to a missing replace stack or the normal drops
                // being too much to fit
                if (delay == 0) {
                    tryMineBlock(level, transaction);
                    delay = getDelay();
                }
                transaction.commit();
            }
        }
    }
    setActive(isActive);

    if (doEject && delayTicks == 0) {
        Direction direction = getDirection();
        Direction oppositeDirection = direction.getOpposite();
        BlockPos ejectPos = getBlockPos().above().relative(oppositeDirection);
        if (selfEjectInventory == null) {
            selfEjectInventory = Capabilities.ITEM.createCache(level, ejectPos, oppositeDirection);
        }
        ResourceHandler<ItemResource> ejectHandler = selfEjectInventory.getCapability();
        if (ejectInventory == null) {
            ejectInventory = Capabilities.ITEM.createCache(level, ejectPos.relative(oppositeDirection), direction);
        }
        ResourceHandler<ItemResource> targetHandler = ejectInventory.getCapability();
        if (ejectHandler != null && targetHandler != null) {
            try (Transaction transaction = Transaction.openRoot()) {
                TransitRequest ejectMap = InventoryUtils.getEjectItemMap(ejectHandler, mainSlots, transaction);
                if (!ejectMap.isEmpty()) {
                    TransitResponse response = ejectMap.eject(this, level, ejectPos, targetHandler, 1, null, transaction);
                    if (response.useAll(transaction)) {
                        transaction.commit();
                    }
                }
            }
        }
        delayTicks = MekanismUtils.TICKS_PER_HALF_SECOND;
    } else if (delayTicks > 0) {
        delayTicks--;
    }
    return sendUpdatePacket;
}

public void tick() {
	Entity thrower = getOwner();
	if (!(thrower instanceof Player player) || !thrower.isAlive()) {
		if (!level().isClientSide) {
			discard();
		}
		return;
	}
	if (!level().isClientSide) {
		ItemStack stack = PlayerHelper.getFirstHeldItem(player, BotaniaItems.kingKey);
		boolean newCharging = !stack.isEmpty() && KeyOfTheKingsLawItem.isCharging(stack);
		if (isCharging() != newCharging) {
			setCharging(newCharging);
		}
	}

	Vec3 mot = getDeltaMovement();

	int liveTime = getLiveTicks();
	int delay = getDelay();
	boolean charging = isCharging() && liveTime == 0;

	if (charging) {
		setDeltaMovement(Vec3.ZERO);

		int chargeTime = getChargeTicks();
		setChargeTicks(chargeTime + 1);

		if (level().random.nextInt(20) == 0) {
			level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonSpawn, SoundSource.PLAYERS, 0.1F, 1F + level().random.nextFloat() * 3F);
		}
	} else {
		if (liveTime < delay) {
			setDeltaMovement(Vec3.ZERO);
		} else if (liveTime == delay) {
			Vec3 playerLook;
			BlockHitResult rtr = ToolCommons.raytraceFromEntity(player, 64, true);
			if (rtr.getType() != HitResult.Type.BLOCK) {
				playerLook = player.getLookAngle().scale(64).add(player.position());
			} else {
				playerLook = Vec3.atCenterOf(rtr.getBlockPos());
			}

			Vec3 thisVec = VecHelper.fromEntityCenter(this);

			mot = playerLook.subtract(thisVec.x, thisVec.y, thisVec.z).normalize().scale(2);
			level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonAttack, SoundSource.PLAYERS, 2F, 0.1F + level().random.nextFloat() * 3F);
		}

		if (!level().isClientSide) {
			setLiveTicks(liveTime + 1);
			AABB axis = new AABB(getX(), getY(), getZ(), xOld, yOld, zOld).inflate(2);
			List<LivingEntity> entities = level().getEntitiesOfClass(LivingEntity.class, axis);
			for (LivingEntity living : entities) {
				if (living == thrower) {
					continue;
				}

				if (living.hurtTime == 0) {
					living.hurt(level().damageSources().playerAttack(player), 20);
					onHit(new EntityHitResult(living));
					return;
				}
			}
		}
	}

	super.tick();

	// Apply after super tick so drag is not applied by super
	setDeltaMovement(mot);

	if (level().isClientSide && liveTime > delay) {
		WispParticleData data = WispParticleData.wisp(0.3F, 1F, 1F, 0F, 1);
		level().addParticle(data, getX(), getY(), getZ(), 0, -0F, 0);
	}

	if (!level().isClientSide && liveTime > 200 + delay) {
		discard();
	}
}

public void tickFlower() {
	super.tickFlower();

	if (getLevel().isClientSide) {
		if (!ateOnce && cooldown > 0) {
			if (Math.random() < 0.5) {
				Vec3 offset = getLevel().getBlockState(getBlockPos()).getOffset(getLevel(), getBlockPos());
				double x = getBlockPos().getX() + offset.x + 0.2 + Math.random() * 0.6;
				double y = getBlockPos().getY() + offset.y + 0.6 + Math.random() * 0.3;
				double z = getBlockPos().getZ() + offset.z + 0.2 + Math.random() * 0.6;
				WispParticleData data = WispParticleData.wisp(0.05F, 0.5F, 0.5F, 0.5F);
				getLevel().addParticle(data, x, y, z, 0, 0.025F, 0);
			}
			cooldown--;
		}
		return;
	}

	if (!ateOnce && cooldown > 0) {
		cooldown--;
		if (cooldown == 0) {
			setChanged();
		} else {
			level.blockEntityChanged(getBlockPos());
		}
		return;
	}

	eatLeaves: {
		if (getMaxMana() - getMana() >= MANA_PER_LEAF && ticksExisted % 4 == 0) {
			Map<BlockPos, Float> coordsMap = new HashMap<>();
			Random rng = new Random();
			BlockPos pos = getEffectivePos();

			for (BlockPos pos_ : BlockPos.betweenClosed(pos.offset(-RANGE, 0, -RANGE),
					pos.offset(RANGE, RANGE_Y, RANGE))) {
				BlockState state = getLevel().getBlockState(pos_);
				if (state.is(BlockTags.LEAVES)) {
					for (Direction dir : Direction.values()) {
						if (getLevel().isEmptyBlock(pos_.relative(dir))) {
							coordsMap.put(pos_.immutable(), (state.hasProperty(LeavesBlock.DISTANCE)
									? state.getValue(LeavesBlock.DISTANCE) : 1) + 2.0f * rng.nextFloat());
							break;
						}
					}
				}
			}

			if (coordsMap.isEmpty()) {
				break eatLeaves;
			}

			float maxDistance = 0F;
			for (float distance : coordsMap.values()) {
				maxDistance = Math.max(maxDistance, distance);
			}

			float finalMaxDistance = maxDistance;
			coordsMap.values().removeIf(dist -> dist < finalMaxDistance - 1f);
			List<BlockPos> coords = new ArrayList<>(coordsMap.keySet());

			BlockPos breakCoords = coords.get(level.getRandom().nextInt(coords.size()));
			BlockState state = getLevel().getBlockState(breakCoords);
			getLevel().removeBlock(breakCoords, false);
			ticksWithoutEating = 0;
			ateOnce = true;
			cooldown = COOLDOWN_TICKS;
			if (BotaniaConfig.common().blockBreakParticles()) {
				getLevel().levelEvent(LevelEvent.PARTICLES_DESTROY_BLOCK, breakCoords, Block.getId(state));
			}
			getLevel().gameEvent(null, GameEvent.BLOCK_DESTROY, breakCoords);
			addMana(MANA_PER_LEAF);
			level.blockEntityChanged(getBlockPos());
		}
	}

	if (ateOnce) {
		ticksWithoutEating++;
		if (ticksWithoutEating >= 5) {
			ateOnce = false;
			ticksWithoutEating = 0;
			setChanged();
			sync();
		}
	}
}

protected Optional<IDecomposedRecipe> decompose(Object... importantData) {
    TypeData<IIngredientWithAmount, CTFluidIngredient, ChemicalStackIngredient> inputs = new TypeData<>();
    TypeData<IItemStack, IFluidStack, ChemicalStackTemplate> outputs = new TypeData<>();
    int duration = -1;
    int energy = -1;
    Boolean perTickUsage = null;
    for (Object data : importantData) {
        if (data instanceof List<?> dataList) {
            if (dataList.size() != 1) {
                //Failed, output lists must be of length one or handled manually instead of using this helper
                return Optional.empty();
            }
            //Update data to be the element
            data = dataList.getFirst();
        } else if (data instanceof long[] longs) {
            if (longs.length != 1) {
                //Failed, output arrays must be of length one or handled manually instead of using this helper
                return Optional.empty();
            }
            //Update data to be the element
            data = longs[0];
        }
        if (data instanceof ItemStackIngredient ingredient) {
            inputs.addItem(CrTUtils.toCrT(ingredient));
        } else if (data instanceof FluidStackIngredient ingredient) {
            inputs.addFluid(CrTUtils.toCrT(ingredient));
        } else if (data instanceof ChemicalStackIngredient ingredient) {
            inputs.addChemical(ingredient);
        } else if (data instanceof ItemStack stack) {
            outputs.addItem(IItemStack.of(stack));
        } else if (data instanceof FluidStack stack) {
            outputs.addFluid(IFluidStack.of(stack));
        } else if (data instanceof ChemicalStackTemplate stack) {
            outputs.addChemical(stack);
        } else if (data instanceof PressurizedReactionRecipeOutput(ItemStackTemplate item, ChemicalStackTemplate chemical)) {
            if (item != null) {
                outputs.addItem(IItemStack.of(item));
            }
            if (chemical != null) {
                outputs.addChemical(chemical);
            }
        } else if (data instanceof ElectrolysisRecipeOutput(ChemicalStackTemplate left, ChemicalStackTemplate right)) {
            outputs.addChemical(left);
            outputs.addChemical(right);
        } else if (data instanceof Boolean b) {
            if (perTickUsage != null) {
                //Fail if we have multiple per tick usages specified
                return Optional.empty();
            }
            perTickUsage = b;
        } else if (data instanceof Integer i) {
            if (duration != -1) {
                //Fail if we have multiple durations specified
                return Optional.empty();
            }
            duration = i;
        } else if (data instanceof Long l) {
            if (energy != -1) {
                //Fail if we have multiple energy values specified
                return Optional.empty();
            }
            energy = l;
        } else {
            //Fail if we have important data we don't know how to handle
            return Optional.empty();
        }
    }
    DecomposedRecipeBuilder builder = IDecomposedRecipe.builder();
    inputs.addItemToBuilder(builder, CrTRecipeComponents.ITEM.input())
          .addFluidToBuilder(builder, CrTRecipeComponents.FLUID.input())
          .addChemicalToBuilder(builder, CrTRecipeComponents.CHEMICAL.input());
    outputs.addItemToBuilder(builder, CrTRecipeComponents.ITEM.output())
          .addFluidToBuilder(builder, CrTRecipeComponents.FLUID.output());
    if (!outputs.chemicalData.isEmpty()) {
        builder.with(CrTRecipeComponents.CHEMICAL.output(), CrTUtils.convertChemical(outputs.chemicalData));
    }
    if (duration != -1) {
        builder.with(BuiltinRecipeComponents.Processing.TIME, duration);
    }
    if (energy != -1) {
        builder.with(CrTRecipeComponents.ENERGY, energy);
    }
    if (perTickUsage != null) {
        builder.with(CrTRecipeComponents.PER_TICK_USAGE, perTickUsage);
    }
    return Optional.of(builder.build());
}

