private void spawnMob(ServerLevel world, LooniumMobSpawnData pickedMobType,
		LooniumStructureConfiguration pickedConfig, LootTable pickedLootTable) {

	ItemStack lootStack = pickRandomLootItem(world, pickedLootTable);
	if (lootStack.isEmpty()) {
		return;
	}

	RandomSource random = world.random;
	double x = getEffectivePos().getX() + 0.5 - RANGE + 2 * RANGE * random.nextDouble();
	double y = getEffectivePos().getY();
	double z = getEffectivePos().getZ() + 0.5 - RANGE + 2 * RANGE * random.nextDouble();

	while (!world.noCollision(pickedMobType.type.getAABB(x, y, z))) {
		y += 1.0;
		if (y >= world.getMaxBuildHeight()) {
			return;
		}
	}

	Entity entity = pickedMobType.type.create(world);
	if (!(entity instanceof Mob mob)) {
		return;
	}

	if (pickedMobType.nbt != null) {
		mob.readAdditionalSaveData(pickedMobType.nbt);
	}
	if (pickedMobType.spawnAsBaby != null) {
		mob.setBaby(pickedMobType.spawnAsBaby);
	}

	mob.absMoveTo(x, y, z, random.nextFloat() * 360F, 0);
	mob.setDeltaMovement(Vec3.ZERO);

	applyAttributesAndEffects(pickedMobType, pickedConfig, mob);

	LooniumComponent looniumComponent = XplatAbstractions.INSTANCE.looniumComponent(mob);
	if (looniumComponent != null) {
		looniumComponent.setSlowDespawn(true);
		looniumComponent.setOverrideDrop(true);
		looniumComponent.setDrop(lootStack);
	}

	mob.finalizeSpawn(world, world.getCurrentDifficultyAt(mob.blockPosition()), MobSpawnType.SPAWNER, null, null);
	if (Boolean.FALSE.equals(pickedMobType.spawnAsBaby) && mob.isBaby()) {
		// Note: might have already affected initial equipment/attribute selection, or even caused a special
		// mob configuration (such as chicken jockey) to spawn, which may look weird when reverting to adult.
		mob.setBaby(false);
	}

	if (pickedMobType.equipmentTable != null) {
		LootTable equipmentTable = world.getServer().getLootData().getLootTable(pickedMobType.equipmentTable);
		if (equipmentTable != LootTable.EMPTY) {
			LootParams lootParams = new LootParams.Builder(world)
					.withParameter(LootContextParams.THIS_ENTITY, mob)
					.withParameter(LootContextParams.ORIGIN, mob.position())
					// TODO 1.21: replace with LootContextParamSets.EQUIPMENT
					.create(LootContextParamSets.SELECTOR);
			var equippedSlots = new HashSet<EquipmentSlot>();
			equipmentTable.getRandomItems(lootParams, equipmentStack -> {
				EquipmentSlot slot = equipmentStack.is(BotaniaTags.Items.LOONIUM_OFFHAND_EQUIPMENT)
						? EquipmentSlot.OFFHAND
						: LivingEntity.getEquipmentSlotForItem(equipmentStack);
				if (equippedSlots.contains(slot)) {
					slot = equippedSlots.contains(EquipmentSlot.MAINHAND)
							&& !(equipmentStack.getItem() instanceof TieredItem)
									? EquipmentSlot.OFFHAND
									: EquipmentSlot.MAINHAND;
				}
				if (!equippedSlots.add(slot)) {
					return;
				}
				mob.setItemSlot(slot, slot.isArmor() ? equipmentStack.copyWithCount(1) : equipmentStack);
			});
		}
	}

	// in case the mob spawned with a vehicle or passenger(s), ensure those don't drop unexpected loot
	mob.getRootVehicle().getPassengersAndSelf().forEach(e -> {
		if (e instanceof Mob otherMob) {
			// prevent armor/weapon drops on player kill, also no nautilus shells from drowned:
			Arrays.stream(EquipmentSlot.values()).forEach(slot -> otherMob.setDropChance(slot, 0));

			if (otherMob instanceof PatrollingMonster patroller && patroller.isPatrolLeader()) {
				//  Loonium may be presenting challenges, but not that type of challenge
				patroller.setPatrolLeader(false);
				patroller.setItemSlot(EquipmentSlot.HEAD, ItemStack.EMPTY);
			}

			if (e == mob) {
				return;
			}

			Optional<LooniumMobSpawnData> mobType = pickedConfig.spawnedMobs.unwrap().stream()
					.filter(mobSpawnData -> mobSpawnData.type.tryCast(otherMob) != null).findFirst();

			ItemStack bonusLoot;
			if (mobType.isPresent()) {
				applyAttributesAndEffects(mobType.get(), pickedConfig, otherMob);
				bonusLoot = pickRandomLootItem(world, pickedLootTable);
			} else {
				bonusLoot = ItemStack.EMPTY;
			}

			LooniumComponent otherLooniumComponent = XplatAbstractions.INSTANCE.looniumComponent(otherMob);
			if (otherLooniumComponent != null) {
				otherLooniumComponent.setSlowDespawn(true);
				otherLooniumComponent.setOverrideDrop(true);
				otherLooniumComponent.setDrop(bonusLoot);
			}
		}
	});

	if (!world.tryAddFreshEntityWithPassengers(mob)) {
		return;
	}

	mob.spawnAnim();
	world.levelEvent(LevelEvent.PARTICLES_MOBBLOCK_SPAWN, getBlockPos(), 0);
	world.gameEvent(mob, GameEvent.ENTITY_PLACE, mob.position());

	addMana(-pickedConfig.manaCost);
	sync();
}

	protected void onHitEntity(EntityHitResult p_213868_1_)
	{
		super.onHitEntity(p_213868_1_);
		Entity entity = p_213868_1_.getEntity();
		float f = (float) this.getDeltaMovement().length();
		int i = Mth.ceil(Mth.clamp(this.damage, 0.0D, 2.147483647E9D));
		if (this.getPierceLevel() > 0)
		{
			if (this.piercedEntities == null)
			{
				this.piercedEntities = new IntOpenHashSet(5);
			}

			if (this.hitEntities == null)
			{
				this.hitEntities = Lists.newArrayListWithCapacity(5);
			}

			if (this.piercedEntities.size() >= this.getPierceLevel() + 1)
			{
				this.discard();
				return;
			}

			this.piercedEntities.add(entity.getId());
		}

		if (this.getIsCritical())
		{
			long j = (long) this.random.nextInt(i / 2 + 2);
			i = (int) Math.min(j + (long) i, 2147483647L);
		}

		Entity entity1 = this.getOwner();
		DamageSource damagesource;
		if (entity1 == null)
		{
			damagesource = entity.damageSources().thrown(this,this);
		} else
		{
			damagesource = entity.damageSources().thrown(this, entity1);
			if (entity1 instanceof LivingEntity)
			{
				((LivingEntity) entity1).setLastHurtMob(entity);
			}
		}

		boolean flag = entity.getType() == EntityType.ENDERMAN;
		int k = entity.getRemainingFireTicks();
		if (this.isOnFire() && !flag)
		{
			entity.setSecondsOnFire(5);
		}

		if (entity.hurt(damagesource, (float) i))
		{
			if (flag)
			{
				return;
			}

			if (!entity.isAlive() && entity1 instanceof Player && entity instanceof LivingEntity)
			{
				double willAmount = this.getWillDropForMobHealth(((LivingEntity) entity).getMaxHealth());
				if (willAmount > 0)
					PlayerDemonWillHandler.addDemonWill(willType, (Player) entity1, willAmount);
			}

			if (entity instanceof LivingEntity)
			{
				LivingEntity livingentity = (LivingEntity) entity;
//				if (!this.world.isRemote && this.getPierceLevel() <= 0)
//				{
//					livingentity.setArrowCountInEntity(livingentity.getArrowCountInEntity() + 1);
//				}

				if (this.knockbackStrength > 0)
				{
					Vec3 vector3d = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double) this.knockbackStrength * 0.6D);
					if (vector3d.lengthSqr() > 0.0D)
					{
						livingentity.push(vector3d.x, 0.1D, vector3d.z);
					}
				}

				if (!this.level().isClientSide && entity1 instanceof LivingEntity)
				{
					EnchantmentHelper.doPostHurtEffects(livingentity, entity1);
					EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingentity);
				}

				this.daggerHit(livingentity);
				if (entity1 != null && livingentity != entity1 && livingentity instanceof Player && entity1 instanceof ServerPlayer && !this.isSilent())
				{
					((ServerPlayer) entity1).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
				}

				if (!entity.isAlive() && this.hitEntities != null)
				{
					this.hitEntities.add(livingentity);
				}
			}

			this.playSound(this.hitSound, 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
			if (this.getPierceLevel() <= 0)
			{
				this.discard();
			}
		} else
		{
			entity.setRemainingFireTicks(k);
			this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
			this.setYRot(this.getYRot() + 180.0F);
			this.yRotO += 180.0F;
			if (!this.level().isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D)
			{
				if (this.pickupStatus == AbstractArrow.Pickup.ALLOWED)
				{
					this.spawnAtLocation(this.getArrowStack(), 0.1F);
				}

				this.discard();
			}
		}

	}

	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		Level world = masterRitualStone.getWorldObj();
//		if (world.isRemote)
//		{
//			return;
//		}
		int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();

		if (currentEssence < getRefreshCost())
		{
			masterRitualStone.getOwnerNetwork().causeNausea();
			return;
		}

		BlockPos pos = masterRitualStone.getMasterBlockPos();

		List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();

		double corrosiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.CORROSIVE, willConfig);
		double destructiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DESTRUCTIVE, willConfig);
		double rawWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DEFAULT, willConfig);
		double steadfastWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.STEADFAST, willConfig);
		double vengefulWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.VENGEFUL, willConfig);

		refreshTime = getRefreshTimeForRawWill(rawWill);

		boolean consumeRawWill = rawWill >= rawWillDrain && refreshTime != defaultRefreshTime;

		int maxEffects = currentEssence / getRefreshCost();
		int totalEffects = 0;

		BlockPos altarPos = pos.offset(altarOffsetPos);

		BlockEntity tile = world.getBlockEntity(altarPos);

		AreaDescriptor altarRange = masterRitualStone.getBlockRange(ALTAR_RANGE);

		if (!altarRange.isWithinArea(altarOffsetPos) || !(tile instanceof IBloodAltar))
		{
			for (BlockPos newPos : altarRange.getContainedPositions(pos))
			{
				BlockEntity nextTile = world.getBlockEntity(newPos);
				if (nextTile instanceof IBloodAltar)
				{
					tile = nextTile;
					altarOffsetPos = newPos.subtract(pos);

					altarRange.resetCache();
					break;
				}
			}
		}

		boolean useIncense = corrosiveWill >= corrosiveWillThreshold;

		if (tile instanceof IBloodAltar)
		{
			IBloodAltar tileAltar = (IBloodAltar) tile;

			AreaDescriptor damageRange = masterRitualStone.getBlockRange(DAMAGE_RANGE);
			AABB range = damageRange.getAABB(pos);

			double destructiveDrain = 0;

			List<Player> entities = world.getEntitiesOfClass(Player.class, range);

			for (Player player : entities)
			{
				float healthThreshold = steadfastWill >= steadfastWillThreshold ? 0.7f : 0.3f;

				if (vengefulWill >= vengefulWillThreshold && !player.getGameProfile().getId().equals(masterRitualStone.getOwner()))
				{
					healthThreshold = 0.1f;
				}

				float health = player.getHealth();
				float maxHealth = player.getMaxHealth();

				float sacrificedHealth = 1;
				double lpModifier = 1;

				if ((health / player.getMaxHealth() > healthThreshold) && (!useIncense || !player.hasEffect(BloodMagicPotions.SOUL_FRAY.get())))
				{
					if (useIncense)
					{
						double incenseAmount = PlayerSacrificeHelper.getPlayerIncense(player);

						sacrificedHealth = health - maxHealth * healthThreshold;
						lpModifier *= PlayerSacrificeHelper.getModifier(incenseAmount);

						PlayerSacrificeHelper.setPlayerIncense(player, 0);
						player.addEffect(new MobEffectInstance(BloodMagicPotions.SOUL_FRAY.get(), PlayerSacrificeHelper.soulFrayDuration));
					}

					if (destructiveWill >= destructiveWillDrain * sacrificedHealth)
					{
						lpModifier *= getLPModifierForWill(destructiveWill);
						destructiveWill -= destructiveWillDrain * sacrificedHealth;
						destructiveDrain += destructiveWillDrain * sacrificedHealth;
					}

					if (LivingUtil.hasFullSet(player))
					{
						LivingStats stats = LivingStats.fromPlayer(player, true);
						double bonus = LivingArmorRegistrar.UPGRADE_SELF_SACRIFICE.get().getBonusValue("self_mod", stats.getLevel(LivingArmorRegistrar.UPGRADE_SELF_SACRIFICE.get().getKey())).doubleValue();
						lpModifier *= (1 + bonus);
						LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_SELF_SACRIFICE.get(), sacrificedHealth);
					}

					player.setHealth(health - sacrificedHealth);
					BloodMagic.packetHandler.sendTo(new SetClientHealthPacket(health - sacrificedHealth), (ServerPlayer) player);

					tileAltar.sacrificialDaggerCall((int) (ConfigManager.COMMON.sacrificialDaggerConversion.get() * lpModifier * sacrificedHealth), false);

					totalEffects++;

					if (totalEffects >= maxEffects)
					{
						break;
					}

				}
			}

			if (destructiveDrain > 0)
			{
				WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.STEADFAST, destructiveDrain, true);
			}
		}

		masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(getRefreshCost() * totalEffects));
		if (totalEffects > 0 && consumeRawWill)
		{
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DEFAULT, rawWillDrain, true);
		}
	}

	private void updateAltar()
	{
//		System.out.println("Updating altar.");
		if (tileAltar.getOutputState())
			tileAltar.setOutputState(false);

		if (!isActive)
		{
			if (cooldownAfterCrafting > 0)
			{
				cooldownAfterCrafting--;
				if (cooldownAfterCrafting <= 0)
				{
					startCycle();
				}
			}

			return;
		}

		if (!canBeFilled && recipe == null)
		{
			startCycle();
			return;
		}

		ItemStack input = tileAltar.getItem(0);

		if (input.isEmpty())
			return;

		Level world = tileAltar.getLevel();
		BlockPos pos = tileAltar.getBlockPos();

		if (world.isClientSide)
			return;

		if (!canBeFilled)
		{
			boolean hasOperated = false;
			int stackSize = input.getCount();

			if (totalCharge > 0)
			{
				int chargeDrained = Math.min(liquidRequired * stackSize - progress, totalCharge);

				totalCharge -= chargeDrained;
				progress += chargeDrained;
				hasOperated = true;
			}
			if (fluid != null && fluid.getAmount() >= 1)
			{
//				int liquidDrained = Math.min((int) (altarTier.ordinal() >= 1
//						? consumptionRate * (1 + consumptionMultiplier)
//						: consumptionRate), fluid.getAmount());
				int liquidDrained = Math.min((int) (consumptionRate * (1 + consumptionMultiplier)), fluid.getAmount());

				if (liquidDrained > (liquidRequired * stackSize - progress))
					liquidDrained = liquidRequired * stackSize - progress;

				fluid.setAmount(fluid.getAmount() - liquidDrained);
				progress += liquidDrained;

				hasOperated = true;

				if (internalCounter % 4 == 0 && world instanceof ServerLevel)
				{
					ServerLevel server = (ServerLevel) world;
//					server.spawnParticle(ParticleTypes.SPLASH, (double) pos.getX()
//							+ worldIn.rand.nextDouble(), (double) (pos.getY() + 1), (double) pos.getZ()
//									+ worldIn.rand.nextDouble(), 1, 0.0D, 0.0D, 0.0D, 1.0D);
					server.sendParticles(DustParticleOptions.REDSTONE, pos.getX() + 0.5, pos.getY() + 1.0, pos.getZ() + 0.5, 1, 0.2, 0.0, 0.2, 0.0);
				}

			} else if (!hasOperated && progress > 0)
			{
				progress -= (int) (efficiencyMultiplier * drainRate);

				if (progress < 0)
					progress = 0;

				if (internalCounter % 2 == 0 && world instanceof ServerLevel)
				{
					ServerLevel server = (ServerLevel) world;
					server.sendParticles(ParticleTypes.LARGE_SMOKE, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0.1, 0, 0.1, 0);
				}
			}

			if (hasOperated)
			{
				if (progress >= liquidRequired * stackSize)
				{
					ItemStack result = ItemHandlerHelper.copyStackWithSize(recipe.getOutput(), stackSize);

					BloodMagicCraftedEvent.Altar event = new BloodMagicCraftedEvent.Altar(result, input.copy());
					MinecraftForge.EVENT_BUS.post(event);
					tileAltar.setItem(0, event.getOutput());
					if (tileAltar.getLevel().getBlockState(tileAltar.getBlockPos().below()).getBlock() instanceof RedstoneLampBlock)
						tileAltar.setOutputState(true);

					progress = 0;

					if (world instanceof ServerLevel)
					{
						ServerLevel server = (ServerLevel) world;
						server.sendParticles(DustParticleOptions.REDSTONE, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 40, 0.3, 0, 0.3, 0);
					}

					this.cooldownAfterCrafting = 30;
					this.isActive = false;
				}
			}

		} else
		{
			ItemStack contained = tileAltar.getItem(0);

			if (contained.isEmpty() || !(contained.getItem() instanceof IBloodOrb) || !(contained.getItem() instanceof IBindable))
				return;

			BloodOrb orb = ((IBloodOrb) contained.getItem()).getOrb(contained);
			Binding binding = ((IBindable) contained.getItem()).getBinding(contained);

			if (binding == null || orb == null)
				return;

			if (fluid != null && fluid.getAmount() >= 1)
			{
//				int liquidDrained = Math.min((int) (altarTier.ordinal() >= 2
//						? orb.getFillRate() * (1 + consumptionMultiplier)
//						: orb.getFillRate()), fluid.getAmount());
				int liquidDrained = Math.min((int) (orb.getFillRate() * (1 + consumptionMultiplier)), fluid.getAmount());
				int drain = NetworkHelper.getSoulNetwork(binding).add(liquidDrained, (int) (orb.getCapacity() * this.orbCapacityMultiplier));
				fluid.setAmount(fluid.getAmount() - drain);

				if (drain > 0 && internalCounter % 4 == 0 && world instanceof ServerLevel)
				{
					ServerLevel server = (ServerLevel) world;
					server.sendParticles(ParticleTypes.WITCH, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0.001);
				}
			}
		}

		tileAltar.getLevel().sendBlockUpdated(tileAltar.getBlockPos(), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), tileAltar.getLevel().getBlockState(tileAltar.getBlockPos()), 3);
	}

public void performRitual(IMasterRitualStone masterRitualStone)
{
	Level world = masterRitualStone.getWorldObj();
	int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();

	if (currentEssence < getRefreshCost())
	{
		masterRitualStone.getOwnerNetwork().causeNausea();
		return;
	}

	int maxGrowths = currentEssence / getRefreshCost();
	int totalGrowths = 0;
	BlockPos pos = masterRitualStone.getMasterBlockPos();

	AreaDescriptor chestRange = masterRitualStone.getBlockRange(CHEST_RANGE);
	BlockEntity chest = world.getBlockEntity(chestRange.getContainedPositions(pos).get(0));
	IItemHandler itemHandler = null;
	if (chest != null)
	{
		itemHandler = Utils.getInventory(chest, null);
	}

	List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();

	double rawWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DEFAULT, willConfig);
	double steadfastWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.STEADFAST, willConfig);
	double corrosiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.CORROSIVE, willConfig);
	double destructiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DESTRUCTIVE, willConfig);
	double vengefulWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.VENGEFUL, willConfig);

	refreshTime = getRefreshTimeForRawWill(rawWill);

	boolean consumeRawWill = rawWill >= rawWillDrain && refreshTime != defaultRefreshTime;

	double vengefulDrain = 0;
	double steadfastDrain = 0;
	double destructiveDrain = 0;

	boolean decreaseBreedTimer = vengefulWill >= vengefulWillDrain;
	boolean breedAnimals = steadfastWill >= steadfastWillDrain && itemHandler != null;
	boolean kamikaze = destructiveWill >= destructiveWillDrain;

	AreaDescriptor growingRange = masterRitualStone.getBlockRange(GROWTH_RANGE);
	AABB axis = growingRange.getAABB(masterRitualStone.getMasterBlockPos());
	List<Animal> animalList = world.getEntitiesOfClass(Animal.class, axis);

	boolean performedEffect = false;

	for (Animal animal : animalList)
	{
		if (animal.getAge() < 0)
		{
			animal.ageUp(5);
			totalGrowths++;
			performedEffect = true;
		} else if (animal.getAge() > 0)
		{
			if (decreaseBreedTimer)
			{
				if (vengefulWill >= vengefulWillDrain)
				{
					animal.setAge(Math.max(0, animal.getAge() - getBreedingDecreaseForWill(vengefulWill)));
					vengefulDrain += vengefulWillDrain;
					vengefulWill -= vengefulWillDrain;
					performedEffect = true;
				} else
				{
					decreaseBreedTimer = false;
				}
			}
		} else
		{
			if (kamikaze)
			{
				if (destructiveWill >= destructiveWillDrain)
				{
					if (!animal.hasEffect(BloodMagicPotions.SACRIFICIAL_LAMB.get()))
					{
						animal.addEffect(new MobEffectInstance(BloodMagicPotions.SACRIFICIAL_LAMB.get(), 1200));
						destructiveDrain += destructiveWillDrain;
						destructiveWill -= destructiveWillDrain;
						performedEffect = true;
					}
				} else
				{
					kamikaze = false;
				}
			}

			if (breedAnimals)
			{
				if (steadfastWill >= steadfastWillDrain)
				{
					if (!animal.isInLove())
					{
						for (int slot = 0; slot < itemHandler.getSlots(); slot++)
						{
							ItemStack foodStack = itemHandler.getStackInSlot(slot);
							if (foodStack != null && animal.isFood(foodStack) && itemHandler.extractItem(slot, 1, true) != null)
							{
								animal.setInLove(null);
								itemHandler.extractItem(slot, 1, false);
								steadfastDrain += steadfastWillDrain;
								steadfastWill -= steadfastWillDrain;
								performedEffect = true;
								break;
							}
						}
					}
				} else
				{
					breedAnimals = false;
				}
			}
		}

		if (totalGrowths >= maxGrowths)
		{
			break;
		}
	}

	if (performedEffect && consumeRawWill)
	{
		WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DEFAULT, rawWillDrain, true);
	}

	if (vengefulDrain > 0)
	{
		WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.VENGEFUL, vengefulDrain, true);
	}

	if (steadfastDrain > 0)
	{
		WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.STEADFAST, steadfastDrain, true);
	}

	if (destructiveDrain > 0)
	{
		WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DESTRUCTIVE, destructiveDrain, true);
	}

	masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(totalGrowths * getRefreshCost()));
}

