public void performRitual(IMasterRitualStone masterRitualStone)
{
	timer++;
	Level world = masterRitualStone.getWorldObj();
	int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();
	int lpDrain = 0;

	if (currentEssence < getRefreshCost())
	{
		masterRitualStone.getOwnerNetwork().causeNausea();
		return;
	}

	BlockPos pos = masterRitualStone.getMasterBlockPos();
	List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();

	double rawWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DEFAULT, willConfig);
	double rawDrained = 0;

	DemonWillHolder holder = WorldDemonWillHandler.getWillHolder(world, pos);
	AreaDescriptor lavaRange = masterRitualStone.getBlockRange(LAVA_RANGE);

	int maxLavaVolume = getMaxVolumeForRange(LAVA_RANGE, willConfig, holder);
	if (!lavaRange.isWithinRange(getMaxVerticalRadiusForRange(LAVA_RANGE, willConfig, holder), getMaxHorizontalRadiusForRange(LAVA_RANGE, willConfig, holder)) || (maxLavaVolume != 0 && lavaRange.getVolume() > maxLavaVolume))
	{
		return;
	}

	for (BlockPos newPos : lavaRange.getContainedPositions(pos))
	{
		BlockState state = world.getBlockState(newPos);
		if (world.isEmptyBlock(newPos) || Utils.isFlowingLiquid(world, newPos, state))
		{
			int lpCost = getLPCostForRawWill(rawWill);
			if (currentEssence < lpCost)
			{
				break;
			}
			if (BlockProtectionHelper.tryPlaceBlock(world, newPos, Blocks.LAVA.defaultBlockState(), masterRitualStone.getOwner()))
			{
				currentEssence -= lpCost;
				lpDrain += lpCost;
				if (rawWill > 0)
				{
					double drain = getWillCostForRawWill(rawWill);
					rawWill -= drain;
					rawDrained += drain;
				}
			}
		}
	}

	if (rawWill > 0)
	{
		AreaDescriptor chestRange = masterRitualStone.getBlockRange(LAVA_TANK_RANGE);
		BlockEntity tile = world.getBlockEntity(chestRange.getContainedPositions(pos).get(0));
		double drain = getWillCostForRawWill(rawWill);
		int lpCost = getLPCostForRawWill(rawWill);

		if (rawWill >= drain && currentEssence >= lpCost)
		{
			if (tile != null)
			{
				LazyOptional<IFluidHandler> capability = tile.getCapability(ForgeCapabilities.FLUID_HANDLER, null);
				if (capability.isPresent())
				{
					IFluidHandler handler = capability.resolve().get();
					double filled = handler.fill(new FluidStack(Fluids.LAVA, 1000), FluidAction.EXECUTE);

					double ratio = filled / 1000;

					rawWill -= drain * ratio;
					rawDrained += drain * ratio;

					currentEssence -= Math.ceil(lpCost * ratio);
					lpDrain += Math.ceil(lpCost * ratio);
				}
			}
		}
	}

	double vengefulWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.VENGEFUL, willConfig);
	double steadfastWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.STEADFAST, willConfig);
	double corrosiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.CORROSIVE, willConfig);

	if (vengefulWill >= vengefulWillDrain)
	{
		double vengefulDrained = 0;
		AreaDescriptor fuseRange = masterRitualStone.getBlockRange(FIRE_FUSE_RANGE);

		AABB fuseArea = fuseRange.getAABB(pos);
		List<LivingEntity> entities = world.getEntitiesOfClass(LivingEntity.class, fuseArea);

		for (LivingEntity entity : entities)
		{
			if (vengefulWill < vengefulWillDrain)
			{
				break;
			}

			if (entity instanceof Player)
			{
				continue;
			}

			if (!entity.hasEffect(BloodMagicPotions.FIRE_FUSE.get()))
			{
				entity.addEffect(new MobEffectInstance(BloodMagicPotions.FIRE_FUSE.get(), 100, 0));

				vengefulDrained += vengefulWillDrain;
				vengefulWill -= vengefulWillDrain;
			}
		}

		if (vengefulDrained > 0)
		{
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.VENGEFUL, vengefulDrained, true);
		}
	}

	if (steadfastWill >= steadfastWillDrain)
	{
		double steadfastDrained = 0;
		AreaDescriptor resistRange = masterRitualStone.getBlockRange(FIRE_RESIST_RANGE);

		int duration = getFireResistForWill(steadfastWill);

		AABB resistArea = resistRange.getAABB(pos);
		List<Player> entities = world.getEntitiesOfClass(Player.class, resistArea);

		for (Player entity : entities)
		{
			if (steadfastWill < steadfastWillDrain)
			{
				break;
			}
			if (!entity.hasEffect(MobEffects.FIRE_RESISTANCE) || (entity.getEffect(MobEffects.FIRE_RESISTANCE).getDuration() < 2))
			{
				entity.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 100, 0));

				steadfastDrained += steadfastWillDrain;
				steadfastWill -= steadfastWillDrain;
			}
		}

		if (steadfastDrained > 0)
		{
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.STEADFAST, steadfastDrained, true);
		}
	}

	if (timer % corrosiveRefreshTime == 0 && corrosiveWill >= corrosiveWillDrain)
	{
		double corrosiveDrained = 0;
		AreaDescriptor resistRange = masterRitualStone.getBlockRange(FIRE_DAMAGE_RANGE);

		float damage = getCorrosiveDamageForWill(corrosiveWill);

		AABB damageArea = resistRange.getAABB(pos);
		List<LivingEntity> entities = world.getEntitiesOfClass(LivingEntity.class, damageArea);

		for (LivingEntity entity : entities)
		{
			if (corrosiveWill < corrosiveWillDrain)
			{
				break;
			}

			if (!entity.isAlive() && entity.hurtTime <= 0 && Utils.isImmuneToFireDamage(entity))
			{
				if (entity.hurt(entity.damageSources().source(BloodMagicDamageTypes.SACRIFICE), damage))
				{
					corrosiveDrained += corrosiveWillDrain;
					corrosiveWill -= corrosiveWillDrain;
				}
			}
		}

		if (corrosiveDrained > 0)
		{
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.CORROSIVE, corrosiveDrained, true);
		}
	}

	if (rawDrained > 0)
	{
		WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DEFAULT, rawDrained, true);
	}

	masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(lpDrain));
}

	public void onEntityUpdate(LivingEvent.LivingTickEvent event)
	{
		if (event.getEntity().level().isClientSide)
		{
			if (event.getEntity() instanceof Player)
			{
				Player player = (Player) event.getEntity();
				if (LivingUtil.hasFullSet(player))
				{
					LivingStats stats = LivingStats.fromPlayer(player, true);
					if (!player.onGround() && player.getDeltaMovement().y() < 0)
					{
						int jumpLevel = stats.getLevel(LivingArmorRegistrar.UPGRADE_JUMP.get().getKey());
						double fallDistanceMultiplier = LivingArmorRegistrar.UPGRADE_JUMP.get().getBonusValue("fall", jumpLevel).doubleValue();
						player.fallDistance = (float) Math.max(0, player.fallDistance + fallDistanceMultiplier * player.getDeltaMovement().y());
//				System.out.println("Player's motion: " + player.getMotion().getY() + ", Player's fall reduction multiplier: " + fallDistanceMultiplier + ", Player's final fall distance: " + player.fallDistance);
					}
				}
			}
		}

		if (event.getEntity() instanceof Player player)
		{
			float percentIncrease = 0;

//			System.out.println("Player's motion: " + player.getMotion().getY() + ", Player's final fall distance: " + player.fallDistance);

			if (LivingUtil.hasFullSet(player))
			{
				LivingStats stats = LivingStats.fromPlayer(player, true);
				ItemStack chestStack = player.getItemBySlot(EquipmentSlot.CHEST);

				if (!event.getEntity().level().isClientSide)
				{
					int currentFood = player.getFoodData().getFoodLevel();

					if (foodMap.getOrDefault(player.getUUID(), 19) < currentFood)
					{
						LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_KNOCKBACK_RESIST.get(), currentFood - foodMap.getOrDefault(player.getUUID(), 19));
					}

					foodMap.put(player.getUUID(), currentFood);
				}

//				percentIncrease += LivingArmorRegistrar.UPGRADE_SPEED.get().getBonusValue("speed_modifier", stats.getLevel(LivingArmorRegistrar.UPGRADE_SPEED.get().getKey())).doubleValue();
				if (player.isSprinting())
				{
					int speedTime = LivingArmorRegistrar.UPGRADE_SPEED.get().getBonusValue("speed_time", stats.getLevel(LivingArmorRegistrar.UPGRADE_SPEED.get().getKey())).intValue();
					if (speedTime > 0)
					{
						int speedLevel = LivingArmorRegistrar.UPGRADE_SPEED.get().getBonusValue("speed_level", stats.getLevel(LivingArmorRegistrar.UPGRADE_SPEED.get().getKey())).intValue();
						player.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, speedTime, speedLevel, true, false));
					}
				}

				double distance = 0;

				if (posXMap.containsKey(player.getUUID()))
				{
					distance = Math.sqrt((player.getX() - posXMap.get(player.getUUID())) * (player.getX() - posXMap.get(player.getUUID())) + (player.getZ() - posZMap.get(player.getUUID())) * (player.getZ() - posZMap.get(player.getUUID())));
				}

//				System.out.println("Distance travelled: " + distance);
				if (player.onGround() && distance > 0 && distance < 50)
				{
					distance *= (1 + percentIncrease);
					LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_SPEED.get(), distance);
//					System.out.println("Current exp for speed: " + LivingStats.fromPlayer(player).getUpgrades().getOrDefault(LivingArmorRegistrar.UPGRADE_SPEED.get(), 0d));
				}

				if (!player.onGround() && player.getDeltaMovement().y() < 0)
				{

					int jumpLevel = stats.getLevel(LivingArmorRegistrar.UPGRADE_JUMP.get().getKey());
					double fallDistanceMultiplier = LivingArmorRegistrar.UPGRADE_JUMP.get().getBonusValue("fall", jumpLevel).doubleValue();
					player.fallDistance = (float) Math.max(0, player.fallDistance + fallDistanceMultiplier * player.getDeltaMovement().y());
//					System.out.println("Player's motion: " + player.getMotion().getY() + ", Player's fall reduction multiplier: " + fallDistanceMultiplier + ", Player's final fall distance: " + player.fallDistance);
				}

				int fireLevel = stats.getLevel(LivingArmorRegistrar.UPGRADE_FIRE_RESIST.get().getKey());
				if (fireLevel > 0)
				{
					boolean hasChanged = false;
					int fireCooldown = chestStack.getTag().getInt("fire_cooldown");
					if (fireCooldown > 0)
					{
						fireCooldown--;
						hasChanged = true;
					}

					if (hasChanged)
					{
						chestStack.getTag().putInt("fire_cooldown", fireCooldown);
					}
				}

				if (player.getRemainingFireTicks() > 0)
				{
					LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_FIRE_RESIST.get(), 1);
					if (fireLevel > 0)
					{
						boolean hasChanged = false;
						int fireCooldown = chestStack.getTag().getInt("fire_cooldown");

						if (player.getRemainingFireTicks() > 0 && fireCooldown <= 0)
						{
							fireCooldown = LivingArmorRegistrar.UPGRADE_FIRE_RESIST.get().getBonusValue("cooldown_time", fireLevel).intValue();
							player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, LivingArmorRegistrar.UPGRADE_FIRE_RESIST.get().getBonusValue("resist_duration", fireLevel).intValue(), 0, true, false));
							hasChanged = true;
						}

						if (hasChanged)
						{
							chestStack.getTag().putInt("fire_cooldown", fireCooldown);
						}
					}
				}

				int poisonLevel = stats.getLevel(LivingArmorRegistrar.UPGRADE_POISON_RESIST.get().getKey());
				if (player.hasEffect(MobEffects.POISON))
				{
					LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_POISON_RESIST.get(), 1);
				}
				if (poisonLevel > 0)
				{
					boolean hasChanged = false;
					int poisonCooldown = chestStack.getTag().getInt("poison_cooldown");
					if (poisonCooldown > 0)
					{
						poisonCooldown--;
						hasChanged = true;
					}

					if (player.hasEffect(MobEffects.POISON) && poisonCooldown <= 0 && LivingArmorRegistrar.UPGRADE_POISON_RESIST.get().getBonusValue("max_cure", poisonLevel).intValue() >= player.getEffect(MobEffects.POISON).getAmplifier())
					{
						poisonCooldown = LivingArmorRegistrar.UPGRADE_POISON_RESIST.get().getBonusValue("cooldown", poisonLevel).intValue();
						player.removeEffect(MobEffects.POISON);
						hasChanged = true;
					}

					if (hasChanged)
					{
						chestStack.getTag().putInt("poison_cooldown", poisonCooldown);
					}
				}

				int battleHungryLevel = stats.getLevel(LivingArmorRegistrar.DOWNGRADE_BATTLE_HUNGRY.get().getKey());
				if (battleHungryLevel > 0)
				{
					boolean hasChanged = false;
					int battleCooldown = chestStack.getTag().getInt("battle_cooldown");
					if (battleCooldown > 0)
					{
						battleCooldown--;
						hasChanged = true;
					}

					if (battleCooldown <= 0)
					{
						battleCooldown = 20;
						float exhaustionAdded = LivingArmorRegistrar.DOWNGRADE_BATTLE_HUNGRY.get().getBonusValue("exhaustion", battleHungryLevel).floatValue();
						player.causeFoodExhaustion(exhaustionAdded);
						hasChanged = true;
					}

					if (hasChanged)
					{
						chestStack.getTag().putInt("battle_cooldown", battleCooldown);
					}
				}

				int pastArmourDamage = chestStack.getTag().getInt("past_damage");
				int currentArmourDamage = chestStack.getDamageValue();
				if (pastArmourDamage > currentArmourDamage)
				{
//					System.out.println("Past damage: " + pastArmourDamage + ", current damage: " + currentArmourDamage);
					LivingUtil.applyNewExperience(player, LivingArmorRegistrar.UPGRADE_REPAIR.get(), pastArmourDamage - currentArmourDamage);
				}

				if (currentArmourDamage != pastArmourDamage)
				{
					chestStack.getTag().putInt("past_damage", currentArmourDamage);
				}

				if (!player.level().isClientSide)
				{
					int repairingLevel = stats.getLevel(LivingArmorRegistrar.UPGRADE_REPAIR.get().getKey());
					if (repairingLevel > 0)
					{
						boolean hasChanged = false;
						int repairCooldown = chestStack.getTag().getInt("repair_cooldown");
						if (repairCooldown > 0)
						{
							repairCooldown--;
							hasChanged = true;
						}

						if (repairCooldown <= 0)
						{

							repairCooldown = LivingArmorRegistrar.UPGRADE_REPAIR.get().getBonusValue("interval", repairingLevel).intValue();
							hasChanged = true;
							EquipmentSlot randomSlot = EquipmentSlot.values()[2 + player.level().random.nextInt(4)];
							ItemStack repairStack = player.getItemBySlot(randomSlot);
							if (!repairStack.isEmpty())
							{
								if (repairStack.isDamageableItem() && repairStack.isDamaged())
								{
									int maxDurabilityRepaired = LivingArmorRegistrar.UPGRADE_REPAIR.get().getBonusValue("max", repairingLevel).intValue();
									int toRepair = Math.min(maxDurabilityRepaired, repairStack.getDamageValue());
									if (toRepair > 0)
									{
										repairStack.setDamageValue(repairStack.getDamageValue() - toRepair);
									}
								}
							}
						}

						if (hasChanged)
						{
							chestStack.getTag().putInt("repair_cooldown", repairCooldown);
						}
					}
				}
			}

//			if (percentIncrease > 0 && (player.isOnGround()) && (Math.abs(player.moveForward) > 0 || Math.abs(player.moveStrafing) > 0))
//			{
//				player.travel(new Vector3d(player.moveStrafing * percentIncrease, 0, player.moveForward * percentIncrease));
//			}

			posXMap.put(player.getUUID(), player.getX());
			posZMap.put(player.getUUID(), player.getZ());
		}
	}

	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		Level world = masterRitualStone.getWorldObj();
		BlockPos masterPos = masterRitualStone.getMasterBlockPos();
		Direction direction = masterRitualStone.getDirection();

		Player selectedPlayer = null;
		AreaDescriptor downgradeRange = masterRitualStone.getBlockRange(DOWNGRADE_RANGE);

		for (Player player : world.getEntitiesOfClass(Player.class, downgradeRange.getAABB(masterRitualStone.getMasterBlockPos())))
		{
			if (!player.isCrouching() && LivingUtil.hasFullSet(player))
			{
				selectedPlayer = player;
				break;
			}
		}

		if (selectedPlayer == null)
		{
			return;
		}

		LivingStats playerStats = LivingStats.fromPlayer(selectedPlayer, true);

//		System.out.println("Found a downgrade!");

		BlockPos chestOffsetPos = new BlockPos(0, 1, 0);
		chestOffsetPos = chestOffsetPos.relative(direction, 2);

		BlockPos chestPos = masterPos.offset(chestOffsetPos);

		BlockEntity tile = world.getBlockEntity(chestPos);

		if (tile == null)
		{
			selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.missingInventory", chestPos.getX(), chestPos.getY(), chestPos.getZ()), true);
			return;
		}

		// Contains the desired levels for each upgrade.
		Map<LivingUpgrade, Integer> downgradeMap = new HashMap<>();

		int availablePoints = 0;
//		int wantedLevel = 0;
		Direction accessDir = Direction.DOWN;

		Map<Integer, List<Integer>> priorityMap = new HashMap<>();
		// Contains the ItemStack used for each downgrade.  Used for the insufficient level message.
		Map<LivingUpgrade, ItemStack> downgradeItemStacksMap= new HashMap<>();

		LazyOptional<IItemHandler> capability = tile.getCapability(ForgeCapabilities.ITEM_HANDLER, accessDir);
		if (capability.isPresent())
		{
			IItemHandler handler = capability.resolve().get();

			for (int i = 0; i < handler.getSlots(); i++)
			{
				ItemStack invStack = handler.getStackInSlot(i);
				availablePoints += getAvailablePointsFromStack(invStack);
				LivingUpgrade downgrade = getDowngradeFromStack(world, invStack);
				if (downgrade != null && downgrade != LivingUpgrade.DUMMY)
				{
					int wantedLevel = getLevelFromStack(invStack);
					downgradeMap.put(downgrade, downgradeMap.getOrDefault(downgrade, 0) + wantedLevel);
					downgradeItemStacksMap.put(downgrade, invStack);
				}

				int priority = getPriorityFromStack(invStack);
				if (priority >= 0)
				{
					if (priorityMap.containsKey(priority))
					{
						priorityMap.get(priority).add(i);
					} else
					{
						ArrayList<Integer> priorityList = new ArrayList<Integer>();
						priorityList.add(i);
						priorityMap.put(priority, priorityList);
					}
				}
			}
		} else if (tile instanceof Container)
		{
			for (int i = 0; i < ((Container) tile).getContainerSize(); i++)
			{
				ItemStack invStack = ((Container) tile).getItem(i);
				availablePoints += getAvailablePointsFromStack(invStack);
				LivingUpgrade downgrade = getDowngradeFromStack(world, invStack);
				if (downgrade != null && downgrade != LivingUpgrade.DUMMY)
				{
					int wantedLevel = getLevelFromStack(invStack);
					downgradeMap.put(downgrade, downgradeMap.getOrDefault(downgrade, 0) + wantedLevel);
					downgradeItemStacksMap.put(downgrade, invStack);
				}

				int priority = getPriorityFromStack(invStack);
				if (priority >= 0)
				{
					if (priorityMap.containsKey(priority))
					{
						priorityMap.get(priority).add(i);
					} else
					{
						ArrayList<Integer> priorityList = new ArrayList<Integer>();
						priorityList.add(i);
						priorityMap.put(priority, priorityList);
					}
				}
			}
		}

		if (downgradeMap.isEmpty())
		{
			return;
		}

		// TODO: Change when chest logic is implemented.

		// Stores the difference in points between the player's armour and the requested
		// downgrade. 0 means nothing is added.
		Map<LivingUpgrade, Integer> pointDifferentialMap = new HashMap<LivingUpgrade, Integer>();
		int totalDifferentialPoints = 0;
		LivingUpgrade lastSkippedDowngrade = null;
		for (Entry<LivingUpgrade, Integer> entry : downgradeMap.entrySet())
		{
			LivingUpgrade downgrade = entry.getKey();
			int playerDowngradeLevel = playerStats.getLevel(downgrade.getKey());
			int wantedLevel = Math.min(entry.getValue(), downgrade.getLevel(Integer.MAX_VALUE));
			if (playerDowngradeLevel >= wantedLevel)
			{
				lastSkippedDowngrade = downgrade;
				continue;
			}

			if (!LivingUtil.canTrain(selectedPlayer, downgrade, playerDowngradeLevel, wantedLevel))
			{
				selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.trainingBraceletBlock"), true);
				return;
			}

			int playerInitialPoints = 0;
			if (playerDowngradeLevel > 0)
			{
				playerInitialPoints = playerStats.getUpgrades().getOrDefault(downgrade, 0d).intValue();
			}

			int totalRequiredPoints = Math.abs(downgrade.getLevelCost(wantedLevel));
			int upgradeRequiredPoints = totalRequiredPoints - playerInitialPoints;
			if (upgradeRequiredPoints > 0)
			{
				pointDifferentialMap.put(downgrade, upgradeRequiredPoints);
				totalDifferentialPoints += upgradeRequiredPoints;
			}
		}

		if (availablePoints < totalDifferentialPoints)
		{
			selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.notEnoughPoints"), true);
			return;
		}
		if (priorityMap.isEmpty() || pointDifferentialMap.isEmpty())
		{
			if (lastSkippedDowngrade != null)
			{
				String itemName = downgradeItemStacksMap.get(lastSkippedDowngrade).getItem().getDefaultInstance().getDisplayName().getString();
				int lastCharIndex = itemName.length() - 1;
				if (itemName.charAt(0) == '[' && itemName.charAt(lastCharIndex) == ']')
				{
					itemName = itemName.substring(1, lastCharIndex); // remove the brackets around the item name.
				}
				selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.notEnoughKeyItems", itemName), true);
			}
			return;
		}

		List<Integer> slotOrderList = new ArrayList<>();

		List<Integer> priorityList = new ArrayList<>(priorityMap.keySet());

		Collections.sort(priorityList);
		for (int priority : priorityList)
		{
			slotOrderList.addAll(priorityMap.get(priority));
		}

		// Consumption logic
		int requiredPoints = totalDifferentialPoints;
		int initialRequiredPoints = requiredPoints;
//		System.out.println("Initial required points: " + requiredPoints);

		List<ItemStack> excessStackList = new ArrayList<>();

		if (capability.isPresent())
		{
			IItemHandler handler = capability.resolve().get();

			for (int i : slotOrderList)
			{
				ItemStack invStack = handler.getStackInSlot(i);
				if (!invStack.isEmpty() && invStack.getItem() instanceof ILivingUpgradePointsProvider)
				{
					ItemStack simStack = handler.extractItem(i, invStack.getCount(), true);

					int containedPoints = ((ILivingUpgradePointsProvider) simStack.getItem()).getAvailableUpgradePoints(simStack, requiredPoints);
					int drainPoints = Math.min(containedPoints, requiredPoints);
					int remainingPointsInItem = ((ILivingUpgradePointsProvider) simStack.getItem()).getExcessUpgradePoints(simStack, drainPoints);
					ItemStack newItemStack = ((ILivingUpgradePointsProvider) simStack.getItem()).getResultingStack(simStack, drainPoints);

					if (newItemStack.isEmpty() || handler.isItemValid(i, newItemStack))
					{
						// Actual number of points syphoned from the item.
						int totalPoints = ((ILivingUpgradePointsProvider) simStack.getItem()).getTotalUpgradePoints(simStack);
						int totalDrainedPoints = (totalPoints - remainingPointsInItem);
//						System.out.println("Contained points: " + containedPoints + ", remaining points: " + remainingPointsInItem);
						requiredPoints -= totalDrainedPoints;
						handler.extractItem(i, simStack.getCount(), false);
						ItemStack remainingStack = handler.insertItem(i, newItemStack, false);

						if (!remainingStack.isEmpty())
						{
							excessStackList.add(remainingStack);
						}

						if (requiredPoints <= 0)
						{
							break;
						}
					}
				}
			}
		} else if (tile instanceof Container)
		{
			for (int i : slotOrderList)
			{
				ItemStack invStack = ((Container) tile).getItem(i);
				if (!invStack.isEmpty() && invStack.getItem() instanceof ILivingUpgradePointsProvider)
				{
					int drainPoints = Math.min(((ILivingUpgradePointsProvider) invStack.getItem()).getAvailableUpgradePoints(invStack, requiredPoints), requiredPoints);
					int remainingPointsInItem = ((ILivingUpgradePointsProvider) invStack.getItem()).getExcessUpgradePoints(invStack, drainPoints);
					ItemStack newItemStack = ((ILivingUpgradePointsProvider) invStack.getItem()).getResultingStack(invStack, drainPoints);

					requiredPoints -= (drainPoints - remainingPointsInItem);
					((Container) tile).setItem(i, newItemStack);

					if (requiredPoints <= 0)
					{
						break;
					}
				}
			}
		}

		if (requiredPoints < 0)
		{
			ItemStack scrapStack = new ItemStack(BloodMagicItems.UPGRADE_SCRAPS.get());
			((ItemLivingTomeScrap) BloodMagicItems.UPGRADE_SCRAPS.get()).setTotalUpgradePoints(scrapStack, Math.abs(requiredPoints));
			excessStackList.add(scrapStack);
		}

		// TODO: Apply ALL upgrades.
		if (requiredPoints <= 0)
		{
			for (Entry<LivingUpgrade, Integer> entry : pointDifferentialMap.entrySet())
			{
				LivingUtil.applyExperienceToUpgradeCap(selectedPlayer, entry.getKey(), entry.getValue());
			}

			masterRitualStone.setActive(false);

			LightningBolt lightningboltentity = EntityType.LIGHTNING_BOLT.create(world);
			lightningboltentity.setPos(masterPos.getX() + 0.5, masterPos.getY(), masterPos.getZ() + 0.5);
			world.addFreshEntity(lightningboltentity);
		} else if (requiredPoints < initialRequiredPoints)
		{
			ItemStack scrapStack = new ItemStack(BloodMagicItems.UPGRADE_SCRAPS.get());
			((ItemLivingTomeScrap) BloodMagicItems.UPGRADE_SCRAPS.get()).setTotalUpgradePoints(scrapStack, Math.abs(initialRequiredPoints - requiredPoints));
			excessStackList.add(scrapStack);
		}

		for (ItemStack item : excessStackList)
		{
			ItemStack copyStack = item.copy();

			if (tile != null)
			{
				copyStack = Utils.insertStackIntoTile(copyStack, tile, Direction.DOWN);
			} else
			{
				Utils.spawnStackAtBlock(world, chestPos, Direction.UP, copyStack);
				continue;
			}
			if (!copyStack.isEmpty())
			{
				Utils.spawnStackAtBlock(world, chestPos, Direction.UP, copyStack);
			}
		}
	}

public void addModifier(List<Temperature.Trait> traits, TempModifier modifier, Placement placement)
{
    for (Temperature.Trait trait : traits)
    {   this.addModifier(trait, modifier, placement);
