public static Optional<TempModifier> tagToModifier(CompoundTag modifierTag)
{
    // Create a new modifier from the CompoundTag
    Optional<TempModifier> optional = TempModifierRegistry.getValue(new ResourceLocation(modifierTag.getString("Id")));
    optional.ifPresent(modifier ->
    {
        modifier.setNBT(modifierTag.getCompound("ModifierData"));

        // Set the modifier's expiration time
        if (modifierTag.contains("ExpireTicks"))
        {   modifier.expires(modifierTag.getInt("ExpireTicks"));
        }

        // Set the modifier's tick rate
        if (modifierTag.contains("TickRate"))
        {   modifier.tickRate(modifierTag.getInt("TickRate"));
        }

        // Set the modifier's ticks existed
        modifier.setTicksExisted(modifierTag.getInt("TicksExisted"));
    });

    return optional;
}

    private boolean updateConnection(EnergyLinkData data, IOPStorage storage, TileEnergyCore core) {
        if (core.energy.getOPStored() < data.operationEnergy() * 20) {
//            coreEnergyLow = true;
            disconnect();
            return false;
        }
//        coreEnergyLow = false;

        if (linkCharge < data.activationEnergy()) {
            long chargeRate = Math.max(1, data.activationEnergy() / (20 * 30));
            long remaining = data.activationEnergy() - linkCharge;
            linkCharge += storage.modifyEnergyStored(-Math.min(remaining, chargeRate));
            markDirty();
            return false;
        }

        long maintenanceCost = (long) ((data.operationEnergy() * 0.1) + (data.operationEnergy() * 0.9 * (flow.orElse(0D) / data.transferLimit())));
        long extracted = core.energy.extractOP(maintenanceCost, false);
        if (extracted < maintenanceCost) {
            disconnect();
            return false;
        }

        return true;
    }

public static void handleBlockToolModificationEvent(BlockEvent.BlockToolModificationEvent event) {

    if (event.isCanceled()) {
        return;
    }
    // Flux Shovel
    ItemStack stack = event.getHeldItemStack();
    Item item = stack.getItem();
    ToolAction action = event.getToolAction();
    if (action.equals(ToolActions.SHOVEL_FLATTEN)) {
        if (item instanceof FluxShovelItem shovel) {
            BlockState state = event.getState();
            if (state.is(Blocks.DIRT_PATH) || state.is(FLUX_PATH.get()) || state.is(Blocks.FARMLAND)) {
                event.setFinalState(Blocks.DIRT.defaultBlockState());
            } else if (shovel.isEmpowered(stack)) {
                BlockState modified = state.getBlock().getToolModifiedState(state, event.getContext(), action, true);
                if (modified != null && modified.is(Blocks.DIRT_PATH)) {
                    if (!event.isSimulated()) {
                        state.getBlock().getToolModifiedState(state, event.getContext(), action, false);
                    }
                    event.setFinalState(FLUX_PATH.get().defaultBlockState());
                }
            }
        }
    }
}

