    int handOffset = !leftHand ? 1 : -1;

    poseStack.translate((float) handOffset * -0.2785682F, 0.18344387F, 0.15731531F);
    poseStack.mulPose(Axis.XP.rotationDegrees(-13.935F));
    poseStack.mulPose(Axis.YP.rotationDegrees((float) handOffset * 35.3F));
    poseStack.mulPose(Axis.ZP.rotationDegrees((float) handOffset * -9.785F));
    float drawTime = (float) 72000 - ((float) player.getUseItemRemainingTicks() - event.getPartialTick() + 1.0F);
    float charge = drawTime / 20.0F;
    charge = (charge * charge + charge * 2.0F) / 3.0F;
    if (charge > 1.0F) {
        charge = 1.0F;
    }

    if (charge > 0.1F) {
        float f15 = Mth.sin((drawTime - 0.1F) * 1.3F);
        float f18 = charge - 0.1F;
        float animOffset = f15 * f18;
        poseStack.translate(animOffset * 0.0F, animOffset * 0.004F, animOffset * 0.0F);
    }

    poseStack.translate(charge * 0.0F, charge * 0.0F, charge * 0.04F);
    poseStack.scale(1.0F, 1.0F, 1.0F + charge * 0.2F);
    poseStack.mulPose(Axis.YN.rotationDegrees((float) handOffset * 45.0F));
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand)
{
    ItemStack itemStack = player.getItemInHand(hand);
    double reachDistance = player.getAttribute(ForgeMod.BLOCK_REACH.get()).getValue();

    Vec3 eye = player.getEyePosition();
    Vec3 look = eye.add(player.getLookAngle().scale(reachDistance));
    EntityHitResult entityHitResult = ProjectileUtil.getEntityHitResult(level, player, eye, look, (new AABB(eye, look)).inflate(1.0D), (entity) -> {
        return entity instanceof Minecart;
    }, 0.0F);
    if (entityHitResult != null && entityHitResult.getType() == EntityHitResult.Type.ENTITY)
    {
        if (entityHitResult.getEntity() instanceof Minecart minecart && minecart.getDisplayBlockState().getBlock() != ModBlocks.MINECART_INSULATION)
        {
            if (!player.isCreative())
            {   player.getMainHandItem().shrink(1);
            }
            player.swing(InteractionHand.MAIN_HAND, true);
            WorldHelper.playEntitySound(SoundEvents.LLAMA_SWAG, minecart, SoundSource.PLAYERS, 1f, (float) ((Math.random() / 5) + 0.9));
            minecart.setDisplayBlockState(ModBlocks.MINECART_INSULATION.defaultBlockState());
            minecart.setDisplayOffset(5);
            return InteractionResultHolder.sidedSuccess(itemStack, level.isClientSide());
        }
    }

    return InteractionResultHolder.pass(itemStack);
}

public static boolean addModifier(LivingEntity entity, TempModifier modifier, Trait trait, Placement placement)
{
    TempModifierEvent.Add event = new TempModifierEvent.Add(entity, trait, modifier);
    MinecraftForge.EVENT_BUS.post(event);
    if (!event.isCanceled())
    {
        LazyOptional<ITemperatureCap> optCap = EntityTempManager.getTemperatureCap(entity);
        if (optCap.resolve().isPresent())
        {
            ITemperatureCap cap = optCap.resolve().get();
            List<TempModifier> modifiers = cap.getModifiers(trait);
            Consumer<TempModifier> onAdded = mod ->
            {   modifier.onAdded(entity, trait);
                updateSiblingsAdd(modifiers, entity, trait, modifier);
            };
            Consumer<TempModifier> onRemoved = mod ->
            {   modifier.onRemoved(entity, trait);
                updateSiblingsRemove(modifiers, entity, trait, modifier);
            };
            if (addModifier(modifiers, event.getModifier(), placement, onAdded, onRemoved))
            {   updateModifiers(entity, cap);
                return true;
            }
            return false;
        }
    }
    return false;
}

public void load(CompoundTag nbt)
{
    super.load(nbt);

    CompoundTag players = new CompoundTag();
    players.put("Players", Objects.requireNonNullElseGet(nbt.get("TrustedPlayers"), ListTag::new));
    this.entityData.set(TRUSTED_PLAYERS, players);

    this.setLastShed(nbt.getInt("LastShed"));
    this.setShedTime(nbt.getInt("ShedTime"));
    this.setHurtTimestamp(nbt.getInt("HurtTimestamp"));
    this.setAgeSecs(nbt.getInt("AgeInSeconds"));
    this.setEatTimestamp(nbt.getInt("EatTimestamp"));

    if (nbt.contains("TrackingPos"))
        this.setTrackingPos(BlockPos.of(nbt.getLong("TrackingPos")));

    ListTag edibleCooldowns = nbt.getList("EdibleCooldowns", 10);
    for (int i = 0; i < edibleCooldowns.size(); i++)
    {
        CompoundTag cooldownTag = edibleCooldowns.getCompound(i);
        ChameleonEdibles.EDIBLES.stream().filter(ed -> ed.getName().equals(cooldownTag.getString("Item"))).findFirst().ifPresent(edible ->
        {   this.setCooldown(edible, cooldownTag.getInt("Cooldown"));
        });
    }
    this.setTemperature(nbt.getFloat("Temperature"));
    this.desiredTemp = this.getTemperature();
}

public static void handleFillWaterskin(Player player, ItemStack thisStack, InteractionHand usedHand, BlockPos filledAtPos, FluidStack filledFluid)
{
    Level level = player.level();
    ItemStack filledWaterskin = getFilledItem(thisStack, level, filledAtPos);
    WaterskinEvent.Fill event = new WaterskinEvent.Fill(thisStack, filledWaterskin, player, level, filledAtPos, filledFluid);
    MinecraftForge.EVENT_BUS.post(event);
    filledWaterskin = event.getResultWaterskin();

    //Replace 1 of the stack with a FilledWaterskinItem
    if (thisStack.getCount() > 1 || player.getAbilities().instabuild)
    {
        if (!player.addItem(filledWaterskin))
        {
            ItemEntity itementity = player.drop(filledWaterskin, false);
            if (itementity != null)
            {   itementity.setNoPickUpDelay();
                itementity.setThrower(player.getUUID());
            }
        }
        thisStack.shrink(1);
    }
    else
    {   player.setItemInHand(usedHand, filledWaterskin);
    }
    player.swing(usedHand);
    player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
    player.awardStat(Stats.ITEM_USED.get(thisStack.getItem()));
    WorldHelper.playEntitySound(ModSounds.WATERSKIN_FILL, player, SoundSource.PLAYERS, 2f, (float) Math.random() / 5 + 0.9f);
}

public static void onGoatTick(LivingEvent.LivingTickEvent event)
{
    LivingEntity entity = event.getEntity();
    getFurCap(entity).ifPresent(cap ->
    {
        EntityDropData furConfig = ConfigSettings.FUR_TIMINGS.get();
        // Tick fur growth cooldown
        if (cap.furGrowthCooldown() > 0)
        {   cap.setFurGrowthCooldown(Math.min(cap.furGrowthCooldown() - 1, furConfig.cooldown()));
        }
        cap.setAge(cap.age() + 1);

        // Entity is goat, current tick is a multiple of the regrow time, and random chance succeeds
        if (!entity.level().isClientSide
        && cap.isSheared()
        && cap.age() % Math.max(1, furConfig.interval()) == 0
        && cap.furGrowthCooldown() == 0
        && entity.getRandom().nextDouble() < furConfig.chance())
        {
            WorldHelper.playEntitySound(SoundEvents.WOOL_HIT, entity, entity.getSoundSource(), 0.5f, 0.6f);
            WorldHelper.playEntitySound(SoundEvents.LLAMA_SWAG, entity, entity.getSoundSource(), 0.5f, 0.8f);

            // Spawn particles
            WorldHelper.spawnParticleBatch(entity.level(), ParticleTypes.SPIT, entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), 0.5f, 0.5f, 0.5f, 10, 0.05f);
            // Set not sheared
            cap.setSheared(false);
            syncData(entity, null);
        }
    });
}

public CompoundTag saveWithoutId(CompoundTag tag)
{
    super.saveWithoutId(tag);

    tag.put("TrustedPlayers", Objects.requireNonNullElseGet(this.getTrustedPlayers().get("Players"), ListTag::new));
    tag.putInt("LastShed", this.getLastShed());
    tag.putInt("ShedTime", this.getShedTime());
    tag.putInt("HurtTimestamp", this.getHurtTimestamp());
    tag.putInt("AgeInSeconds", this.getAgeSecs());
    tag.putLong("EatTimestamp", this.getEatTimestamp());

    // Tracking pos
    if (this.isTracking())
        tag.putLong("TrackingPos", this.getTrackingPos().asLong());
    else tag.remove("TrackingPos");

    // Edible cooldowns
    ListTag edibleCooldowns = new ListTag();
    for (String key : this.getCooldowns().getAllKeys())
    {
        CompoundTag cooldownTag = new CompoundTag();
        cooldownTag.putString("Edible", key);
        cooldownTag.putInt("Cooldown", this.getCooldowns().getInt(key));
        edibleCooldowns.add(cooldownTag);
    }
    tag.put("EdibleCooldowns", edibleCooldowns);

    tag.putFloat("Temperature", this.getTemperature());
    return tag;
}

public boolean plungeAttack(Level world, LivingEntity attacker, ItemStack stack) {

    if (attacker.fallDistance <= attacker.getMaxFallDistance() || !isEmpowered(stack) || !useEnergy(stack, true, attacker)) {
        return false;
    }
    float range = getPlungeRange(attacker.fallDistance);
    if (world.isClientSide) {
        // TODO circle particle
        world.addParticle(new CylindricalParticleOptions(CoreParticles.BLAST_WAVE.get(), range * 2.0F, range * 3.0F, 0, VFXHelper.windColor(world.random).toRGBA(), 1.5F), attacker.getX(), attacker.getY(), attacker.getZ(), 0, 0, 0);
        return true;
    }
    if (Utils.getItemEnchantmentLevel(Enchantments.CHANNELING, stack) > 0) {
        if (world.canSeeSky(attacker.blockPosition()) && world instanceof ServerLevel && world.isThundering()) {
            attacker.addEffect(new MobEffectInstance(LIGHTNING_RESISTANCE.get(), 40, 0, false, false));
            Utils.spawnLightningBolt(world, attacker.blockPosition(), attacker);
        }
    }
    double r2 = range * range;
    boolean hit = false;
    for (Entity target : world.getEntities(attacker, attacker.getBoundingBox().inflate(range, 1, range), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
        if (attacker.distanceToSqr(target) <= r2) {
            hit |= target.hurt(IFluxItem.fluxDirectDamage(attacker), getPlungeAttackDamage(attacker, stack));
        }
    }
    if (hit) {
        world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_RETURN, SoundSource.PLAYERS, 10.0F, 1.0F);
    } else {
        world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_HIT_GROUND, SoundSource.PLAYERS, 3.0F, 1.0F);
    }
    return hit;
}

public void start()
{
    // Scan for ItemEntity in a 5-block range
    List<Entity> items = WorldHelper.getEntities(this.entity.level(), new AABB(this.entity.blockPosition()).inflate(5), e -> true);
    for (Entity ent : items)
    {
        if (ent instanceof ItemEntity itemEntity && itemEntity.getOwner() != null
        && (this.entity.isPlayerTrusted(itemEntity.getOwner().getUUID()) || this.entity.isTamingItem(itemEntity.getItem())))
        {
            ItemStack item = itemEntity.getItem();
            Optional<Edible> edible = ChameleonEdibles.getEdible(item);
            if (edible.isPresent()
            && (!itemEntity.getPersistentData().contains("Recipient") || itemEntity.getPersistentData().getUUID("Recipient").equals(this.entity.getUUID())))
            {
                if (this.entity.getCooldown(edible.get()) <= 0 && edible.get().shouldEat(item, this.entity, itemEntity.getOwner())
                || isBreedingItem(itemEntity.getItem()))
                {
                    this.target = ent;
                    this.lookPos = ent.position();
                    break;
                }
            }
        }
        else if (ent.getType().is(this.wantedEntities))
        {
            this.target = ent;
            this.lookPos = ent.position();
            break;
        }
    }
}

public InteractionResult useOn(UseOnContext context)
{
    Level level = context.getLevel();
    BlockPos pos = context.getClickedPos();
    BlockState state = level.getBlockState(pos);
    Player player = context.getPlayer();

    if (state.is(Blocks.CAULDRON) || state.is(Blocks.WATER_CAULDRON))
    {
        boolean hasWater = state.is(Blocks.WATER_CAULDRON);
        // Fill cauldron
        int waterLevel = hasWater ? state.getValue(LayeredCauldronBlock.LEVEL) : 0;
        if (waterLevel >= 3) return InteractionResult.PASS;
        state = hasWater
                ? state.setValue(LayeredCauldronBlock.LEVEL, waterLevel + 1)
                : Blocks.WATER_CAULDRON.defaultBlockState().setValue(LayeredCauldronBlock.LEVEL, 1);
        level.setBlock(pos, state, 3);
        // Pouring sound / visuals
        if (!level.isClientSide)
        {   level.playSound(null, pos, ModSounds.WATERSKIN_FILL, SoundSource.BLOCKS, 2f, (float) Math.random() / 5 + 0.9f);
            WorldHelper.spawnParticleBatch(level, ParticleTypes.SPLASH, pos.getX() + 0.5, pos.getY() + 0.65, pos.getZ() + 0.5, 0.5, 0.5, 0.5, 10, 0);
        }
        // Consume waterskin
        if (player != null)
        {   consumeWaterskin(context.getItemInHand(), player, context.getHand());
            player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);
        }
        return InteractionResult.SUCCESS;
    }
    return InteractionResult.PASS;
}

private int executeAddModifier(CommandContext<CommandSourceStack> context, Collection<? extends Entity> entities, Temperature.Trait trait, ResourceLocation modifierId,
                               int duration, int tickRate, CompoundTag nbt, Mode mode, Order order, ResourceLocation otherId, int maxCount)
{
    CommandSourceStack source = context.getSource();
    if (entities.stream().anyMatch(entity -> !(entity instanceof Player || EntityTempManager.isTemperatureEnabled(entity))))
    {   source.sendFailure(Component.translatable("commands.cold_sweat.temperature.invalid"));
        return 0;
    }
    Optional<TempModifier> modifierOpt = TempModifierRegistry.getValue(modifierId);
    if (modifierOpt.isEmpty())
    {   source.sendFailure(Component.translatable("commands.cold_sweat.temp_modifier.invalid"));
        return 0;
    }
    TempModifier modifier = modifierOpt.get();
    modifier.expires(duration).tickRate(tickRate);
    modifier.getNBT().merge(nbt);

    Placement placement = Placement.of(mode, order, mod -> otherId == null || mod.getID().equals(otherId))
                                   .limitDuplicates(Matcher.SAME_CLASS, maxCount);
    for (Entity entity : entities)
    {   Temperature.addModifier(((LivingEntity) entity), modifier, trait, placement);
    }
    if (entities.size() == 1)
    {   source.sendSuccess(() -> Component.translatable("commands.cold_sweat.temp_modifier.single.add.result",
                                                        modifierId, entities.iterator().next().getName().getString()), true);
    }
    else
    {   source.sendSuccess(() -> Component.translatable("commands.cold_sweat.temp_modifier.many.add.result",
                                                        modifierId, entities.size()), true);
    }
    return entities.size();
}

public void tick(ModuleContext moduleContext) {
    if (invulnerableTime > 0) {
        invulnerableTime--;
        markDirty();
        if (moduleContext instanceof StackModuleContext) {
            LivingEntity entity = ((StackModuleContext) moduleContext).getEntity();
            if (entity instanceof Player) {
                if (invulnerableTime == 0) {
                    ((Player) entity).displayClientMessage(Component.literal(""), true);
                } else {
                    ((Player) entity).displayClientMessage(Component.translatable("module.draconicevolution.undying.invuln.active", MathUtils.round(invulnerableTime / 20D, 10)).withStyle(ChatFormatting.GOLD), true);
                }
            }
        }
    }

    IOPStorage storage = moduleContext.getOpStorage();
    if (!(moduleContext instanceof StackModuleContext && EffectiveSide.get().isServer() && storage != null)) {
        return;
    }

    StackModuleContext context = (StackModuleContext) moduleContext;
    UndyingData data = module.getData();
    if (!context.isEquipped() || charge >= data.chargeTime()) {
        return;
    }

    if (storage.getOPStored() >= data.getChargeEnergyRate()) {
        storage.modifyEnergyStored(-data.getChargeEnergyRate());
        charge++;
        markDirty();
    }
}

private int executeClearModifier(CommandSourceStack source, Collection<? extends Entity> entities, Temperature.Trait attribute)
{
    for (Entity entity : entities)
    {
        if (EntityTempManager.isTemperatureEnabled(entity) && entity instanceof LivingEntity living)
        {
            EntityTempManager.getTemperatureCap(entity).ifPresent(cap ->
            {   AttributeInstance instance = EntityTempManager.getAttribute(attribute, living);
                if (instance == null) return;
                instance.removeModifiers();
                EntityTempManager.getAttribute(attribute, living).setBaseValue(Double.NaN);
                cap.clearPersistentAttribute(instance.getAttribute());
            });
        }
        else
        {   source.sendFailure(Component.translatable("commands.cold_sweat.temperature.invalid"));
            return 0;
        }
    }
    if (entities.size() == 1)
    {   source.sendSuccess(() ->
                           Component.translatable("commands.cold_sweat.temperature.clear.single.result",
                                                  attribute.getSerializedName(),
                                                  entities.iterator().next().getName().getString()), true);
    }
    else
    {   source.sendSuccess(() ->
                           Component.translatable("commands.cold_sweat.temperature.clear.many.result",
                                                  attribute.getSerializedName(),
                                                  entities.size()), true);
    }
    return entities.size();
}

private int executeClearAllModifiers(CommandSourceStack source, Collection<? extends Entity> entities)
{
    for (Entity entity : entities)
    {
        if (EntityTempManager.isTemperatureEnabled(entity) && entity instanceof LivingEntity living)
        {
            EntityTempManager.getTemperatureCap(entity).ifPresent(cap ->
            {
                for (Temperature.Trait attribute : EntityTempManager.VALID_ATTRIBUTE_TRAITS)
                {
                    AttributeInstance instance = EntityTempManager.getAttribute(attribute, living);
                    if (instance == null) continue;
                    instance.removeModifiers();
                    instance.setBaseValue(instance.getAttribute().getDefaultValue());
                    cap.clearPersistentAttribute(instance.getAttribute());
                }
            });
        }
        else
        {   source.sendFailure(Component.translatable("commands.cold_sweat.temperature.invalid"));
            return 0;
        }
    }
    if (entities.size() == 1)
    {   source.sendSuccess(() -> Component.translatable("commands.cold_sweat.temperature.clear.all.single.result",
                                                        entities.iterator().next().getName().getString()), true);
    }
    else
    {   source.sendSuccess(() -> Component.translatable("commands.cold_sweat.temperature.clear.all.many.result",
                                                        entities.size()), true);
    }
    return entities.size();
}

public void tick(ModuleContext context) {
    if ((tick++ % 20 != 0) || !(context instanceof StackModuleContext ctx)) return;
    if (!(ctx.getEntity() instanceof ServerPlayer player) || player.level().isClientSide() || !ctx.isEquipped()) return;

    if (!enabled.getValue()) {
        if (wasJustDisabled && appliedByModule) {
            player.removeEffect(MobEffects.NIGHT_VISION);
            wasJustDisabled = appliedByModule = false;
            markDirty();
        }
        return;
    }

    IOPStorage opStorage = ctx.getOpStorage();
    if (opStorage == null || opStorage.getOPStored() < EquipCfg.nightVisionEnergy * 20L) {
        if (appliedByModule && disableTimer++ >= 3) {
            player.removeEffect(MobEffects.NIGHT_VISION);
            appliedByModule = false;
            markDirty();
        }
        return;
    }

    boolean shouldApply = player.level().getRawBrightness(player.blockPosition(), 0) <= enableInLight.getValue();
    if (shouldApply) {
        player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, 302, 0, false, false));
        ctx.getOpStorage().modifyEnergyStored(-EquipCfg.nightVisionEnergy * 20L);
        appliedByModule = true;
        disableTimer = 0;
    } else if (appliedByModule && disableTimer++ >= 3){
        player.removeEffect(MobEffects.NIGHT_VISION);
        appliedByModule = true;
    }
    markDirty();
}

public void tick() {
    updateCrystalLogic();
    super.tick();
    if (level.isClientSide) return;

    if (portalHelper.isRunning()) {
        int maxSpeed = portalHelper.isBuilding() ? 125 : 384; //ignitionStage.get() == 1 ? 128 : 256;
        int cycles = Utils.scaleToTPS(level, maxSpeed / 8, maxSpeed);
        for (int i = 0; i < cycles && portalHelper.isRunning(); i++) {
            portalHelper.updateTick();
        }
    } else if (!teleportQ.isEmpty()) {
        for (Entity entity : teleportQ) {
            TargetPos target = getTargetPos();
            if (target == null) {
                deactivate();
                teleportQ.clear();
                return;
            }

            BCoreNetwork.sendSound(entity.level(), entity.blockPosition(), DESounds.PORTAL.get(), SoundSource.PLAYERS, 0.1F, rand.nextFloat() * 0.1F + 0.9F, false);
            entity.setPortalCooldown();
            target.teleport(entity);
            if (entity instanceof ServerPlayer) {
                //This is a hack. I need to find a better solution.
                DelayedTask.run(10, () -> DraconicNetwork.sendDislocatorTeleported((ServerPlayer) entity));
                DelayedTask.run(20, () -> DraconicNetwork.sendDislocatorTeleported((ServerPlayer) entity));
                DelayedTask.run(60, () -> DraconicNetwork.sendDislocatorTeleported((ServerPlayer) entity));
            }
            entity.setPortalCooldown();
            DelayedTask.run(1, () -> BCoreNetwork.sendSound(entity.level(), entity.blockPosition(), DESounds.PORTAL.get(), SoundSource.PLAYERS, 0.1F, rand.nextFloat() * 0.1F + 0.9F, false));
        }
        teleportQ.clear();
    }
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack stack = player.getItemInHand(hand);
    if (!(level instanceof ServerLevel serverLevel)) {
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    }

    TargetPos targetPos = getTargetPos(stack, level);

    if (player.isShiftKeyDown()) {
        if (targetPos == null) {
            setLocation(stack, targetPos = TargetPos.of(player));
            messageUser(player, Component.translatable("dislocate.draconicevolution.bound_to").append("{" + targetPos.getReadableName(false) + "}").withStyle(ChatFormatting.GREEN));
        } else {
            messageUser(player, Component.translatable("dislocate.draconicevolution.already_bound").withStyle(ChatFormatting.RED));
        }
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    } else {
        if (targetPos == null) {
            messageUser(player, Component.translatable("dislocate.draconicevolution.not_set").withStyle(ChatFormatting.RED));
            return new InteractionResultHolder<>(InteractionResult.PASS, stack);
        }
        if (player.getHealth() > 2 || player.getAbilities().instabuild) {
            player.getCooldowns().addCooldown(this, 20);
            dislocateEntity(stack, player, player, targetPos);
            stack.hurtAndBreak(1, serverLevel, player, e -> {});

            if (!player.getAbilities().instabuild) {
                player.setHealth(player.getHealth() - 2);
            }
        } else {
            messageUser(player, Component.translatable("dislocate.draconicevolution.low_health").withStyle(ChatFormatting.RED));
        }
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    }
}

public static void onEatFood(LivingEntityUseItemEvent.Finish event)
{
    ItemStack item = event.getItem();
    if (event.getEntity() instanceof Player player
    && (item.getUseAnimation() == UseAnim.DRINK || item.getUseAnimation() == UseAnim.EAT)
    && !event.getEntity().level().isClientSide)
    {
        // If food item defined in config
        for (FoodData foodData : ConfigSettings.FOOD_TEMPERATURES.get().get(item.getItem()))
        {
            if (foodData != null && foodData.test(item))
            {
                double temperature = foodData.temperature(item, player);
                int duration = foodData.duration(item, player);
                Trait modTrait = duration > 0 ? Trait.BASE : Trait.CORE;
                // Custom class for soul sprouts
                FoodTempModifier foodModifier = item.getItem() == ModItems.SOUL_SPROUT
                                                ? new SoulSproutTempModifier(temperature)
                                                : new FoodTempModifier(temperature);
                // Store the item ID & duration of the TempModifier
                foodModifier.getNBT().putString("item", ForgeRegistries.ITEMS.getKey(item.getItem()).toString());
                foodModifier.getNBT().putInt("duration", duration);
                // Set duration & tick rate
                foodModifier.expires(duration).tickRate(duration);
                // Add the TempModifier
                Placement placement = Placement.LAST.limitDuplicates(Matcher.EQUALS, foodData.stackLimit(item, player))
                                      .orElse(Placement.of(Mode.REPLACE, Order.FIRST, foodModifier::equals));
                Temperature.addModifier(player, foodModifier, modTrait, placement);
                foodData.modifiers().forEach((trait, modifiers) ->
                {   modifiers.forEach(modifier -> Temperature.addModifier(player, modifier.get(), trait, placement));
                });
            }
        }
    }
}

public static void onDryingItemUsed(PlayerInteractEvent.RightClickItem event)
{
    ItemStack stack = event.getItemStack();
    Player player = event.getEntity();
    Collection<DryingItemData> dryingResults = ConfigSettings.DRYING_ITEMS.get().get(stack.getItem());

    if (!player.level().isClientSide() && Temperature.hasModifier(player, Temperature.Trait.WORLD, WaterTempModifier.class))
    {
        for (DryingItemData dryingResult : dryingResults)
        {
            if (!dryingResult.test(player, stack)) continue;
            // Create result item
            ItemStack newStack = dryingResult.result();
            CompoundTag oldTag = NBTHelper.getTagOrEmpty(stack).copy();
            if (!oldTag.isEmpty())
            {   newStack.getOrCreateTag().merge(NBTHelper.getTagOrEmpty(stack).copy());
            }
            // Remove item from player's inventory
            if (!player.getAbilities().instabuild)
            {
                stack.shrink(1);
                // Add result item to player's inventory
                if (!player.getInventory().add(newStack))
                {   player.drop(newStack, false);
                }
            }
            // Effects
            player.swing(event.getHand(), true);
            WorldHelper.playEntitySound(dryingResult.sound(), player, SoundSource.PLAYERS, 1.0F, 1.0F);
            // Remove water temperature modifier
            Temperature.removeModifiers(player, Temperature.Trait.WORLD, mod -> mod instanceof WaterTempModifier);
            break;
        }
    }
}

public static void removeModifiers(LivingEntity entity, Trait trait, int maxCount, Order order, Predicate<TempModifier> condition)
{
    EntityTempManager.getTemperatureCap(entity).ifPresent(cap ->
    {
        List<TempModifier> modifiers = cap.getModifiers(trait);
        boolean forwardOrder = order == Order.FIRST;
        int removed = 0;

        for (int i = forwardOrder ? 0 : modifiers.size() - 1; i >= 0 && i < modifiers.size(); i += forwardOrder ? 1 : -1)
        {
            if (removed < maxCount)
            {
                TempModifier modifier = modifiers.get(i);
                if (condition.test(modifier))
                {
                    TempModifierEvent.Remove event = new TempModifierEvent.Remove(entity, trait, modifier);
                    MinecraftForge.EVENT_BUS.post(event);
                    if (!event.isCanceled())
                    {
                        cap.removeModifier(modifier, trait);
                        modifier.onRemoved(entity, trait);
                        updateSiblingsRemove(modifiers, entity, trait, modifier);
                        i += forwardOrder ? -1 : 1;
                        removed++;
                    }
                }
            }
            else break;
        }

        // Update modifiers if anything actually changed
        if (removed > 0)
        {   updateModifiers(entity, cap);
        }
    });
}

public boolean hurt(DamageSource source, float amount) {
    if (isInvulnerableTo(source)) {
        return false;
    } else {
        if (!isRemoved() && !level().isClientSide) {
            GuardianFightManager manager = getManager();
            float shield = getShieldPower() / (float) DEConfig.guardianCrystalShield;
            if (shield > 0) {
                BCoreNetwork.sendSound(level(), this, DESounds.SHIELD_STRIKE.get(), SoundSource.HOSTILE, 6, 0.5F + shield, false);
            }
            if (manager != null && shield > 0) {
                float modifier = manager.getCrystalDamageModifier(this, source);
                if (modifier == 0) {
                    playChargeAnimation();
                    return false;
                }
                amount *= modifier;
            }
            if (shield > 0) {
                float newPower = (int) (getShieldPower() - amount);
                if (newPower > 0) {
                    setShieldPower(newPower);
                    onCrystalAttacked(source, amount, false);
                    return true;
                }
            }

            discard();
            if (!source.is(DamageTypeTags.IS_EXPLOSION)) {
                level().explode(null, getX(), getY(), getZ(), 10.0F, Level.ExplosionInteraction.BLOCK);
            }
            onCrystalAttacked(source, amount, true);
        }

        return true;
    }
}

public static void handleWaterFreezingFire(TickEvent.PlayerTickEvent event)
{
    Player player = event.player;

    // Water / Rain
    if (!player.level().isClientSide && event.phase == TickEvent.Phase.START)
    {
        if (player.tickCount % 5 == 0)
        {
            if (!player.isSpectator() && (WorldHelper.isInWater(player) || player.tickCount % 40 == 0
            && WorldHelper.isRainingAt(player.level(), player.blockPosition())))
            {   Temperature.addModifier(player, new WaterTempModifier().tickRate(5), Trait.WORLD, Placement.LAST.noDuplicates(Matcher.SAME_CLASS));
            }

            if (player.isFreezing())
            {   Temperature.replaceOrAddModifier(player, new FreezingTempModifier(), Trait.BASE, Matcher.SAME_CLASS);
            }
        }

        if (player.isFreezing() && player.getTicksFrozen() > 0)
        {
            AtomicReference<Double> insulation = new AtomicReference<>((double) 0);
            boolean hasIcePotion = player.hasEffect(ModEffects.ICE_RESISTANCE) && ConfigSettings.ICE_RESISTANCE_ENABLED.get();

            if (!hasIcePotion)
            {
                Temperature.getModifier(player, Trait.RATE, ArmorInsulationTempModifier.class).ifPresent(insulModifier ->
                {   insulation.updateAndGet(v -> (v + insulModifier.getNBT().getDouble("Hot") + insulModifier.getNBT().getDouble("Cold")));
                });
            }

            if (!(hasIcePotion || insulation.get() > 0) && (player.tickCount % Math.max(1, 37 - insulation.get())) == 0)
            {   player.setTicksFrozen(player.getTicksFrozen() - 1);
            }
        }
    }
}

public void onTick(TickEvent.LevelTickEvent event)
{
    if (event.level.isClientSide == level.isClientSide && event.phase == TickEvent.Phase.START)
    {
        // Temperature of waterskin weakens over time
        double waterTemp = CSMath.blend(itemTemp, itemTemp / 5, tick, 20, 100);
        double effectAmount = waterTemp * (ConfigSettings.WATERSKIN_CONSUME_STRENGTH.get() / 50d);
        double wetnessTemp = 0.05 * CSMath.sign(waterTemp+0.01);

        // Move the box down at the speed of gravity
        aabb = aabb.move(0, -acceleration, 0);

        // If there's ground, stop
        BlockPos pos = BlockPos.containing(aabb.minX, aabb.minY, aabb.minZ);
        if (WorldHelper.isSpreadBlocked(level, chunk.getBlockState(pos), pos, Direction.DOWN, Direction.DOWN))
        {   MinecraftForge.EVENT_BUS.unregister(this);
            return;
        }

        // Apply the waterskin modifier to all entities in the box
        WorldHelper.getEntitiesOfClass(Player.class, level, aabb, e -> true).forEach(player ->
        {
            if (!affectedPlayers.contains(player))
            {   // Apply the effect and store the player
                Temperature.addModifier(player, new WaterskinTempModifier(effectAmount).expires(0), Temperature.Trait.CORE, Placement.LAST);
                Temperature.replaceOrAddModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                affectedPlayers.add(player);
            }
        });

        // Increase the speed of the box
        acceleration += 0.0052;
        tick++;

        // Expire after 5 seconds
        if (tick > 100)
        {   MinecraftForge.EVENT_BUS.unregister(this);
        }
    }
}

public InteractionResult mobInteract(@NotNull Player player, @NotNull InteractionHand hand)
{
    // Shed chameleon
    if (!ConfigSettings.CHAMELEON_SHED_AUTOMATICALLY.get() && makeShed(this))
    {   return InteractionResult.SUCCESS;
    }

    // Feed edible
    ItemStack stack = player.getItemInHand(hand);
    Edible edible = ChameleonEdibles.getEdible(stack).orElse(null);

    if (edible != null)
    {
        if (this.feedCooldown <= 0 && this.getCooldown(edible) <= 0 && edible.shouldEat(stack, this, player))
        {
            this.feedCooldown = 10;
            if (!player.level().isClientSide)
            {
                ItemStack dropStack = stack.copy();
                dropStack.setCount(1);
                ItemEntity dropped = player.drop(dropStack, true);
                if (dropped != null)
                {   dropped.getPersistentData().putUUID("Recipient", this.getUUID());
                }
                player.stopUsingItem();
                player.swing(hand, true);
                this.usePlayerItem(player, hand, stack);

                return InteractionResult.SUCCESS;
            }
        }
        return InteractionResult.CONSUME;
    }
    else if (this.isPlayerTrusted(player) && player.getPassengers().isEmpty() && !this.level().isClientSide)
    {
        if (this.startRiding(player) && player instanceof ServerPlayer serverPlayer)
        {   ColdSweatPacketHandler.INSTANCE.send(PacketDistributor.PLAYER.with(() -> serverPlayer), new EntityMountMessage(this.getId(), player.getId(), EntityMountMessage.Action.MOUNT));
        }
        return InteractionResult.SUCCESS;
    }

    return InteractionResult.PASS;
}

