public static boolean performPourAction(ItemStack stack, LivingEntity entity, InteractionHand hand)
{
    if (!(entity instanceof Player player && stack.is(ModItems.FILLED_WATERSKIN))) return false;

    // Play empty sound
    if (!player.level().isClientSide)
    {
        double temperature = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE);
        double wetnessTemp = 0.05 * CSMath.sign(temperature == 0 ? 1 : temperature);
        // Replace or add water temp modifier
        Placement modPlacement = Placement.of(Mode.REPLACE, Order.FIRST, mod -> mod instanceof WaterTempModifier).orElse(Placement.LAST);
        Temperature.addModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, modPlacement);

        WorldHelper.playEntitySound(ModSounds.WATERSKIN_POUR, player, player.getSoundSource(), 2f, (float) ((Math.random() / 5) + 0.9));
    }

    consumeWaterskin(stack, player, hand);
    MinecraftForge.EVENT_BUS.post(new LivingEntityUseItemEvent.Finish(player, stack, 1, stack.getCraftingRemainingItem()));
    player.swing(hand, true);

    // spawn falling water particles
    Random rand = new Random();
    for (int i = 0; i < 6; i++)
    {
        TaskScheduler.scheduleServer(() ->
        {
            ParticleBatchMessage particleBatch = new ParticleBatchMessage(2);
            for (int p = 0; p < 10; p++)
            {
                AABB playerBB = player.getDimensions(player.getPose()).makeBoundingBox(player.position()).inflate(0.2);
                particleBatch.addParticle(ParticleTypes.FALLING_WATER,
                                          Mth.lerp(rand.nextFloat(), playerBB.minX, playerBB.maxX),
                                          playerBB.maxY,
                                          Mth.lerp(rand.nextFloat(), playerBB.minZ, playerBB.maxZ),
                                          0.3, 0.3, 0.3);
            }
            particleBatch.sendEntity(player);
        }, i);
    }
    player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
    player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);

    return true;
}

public boolean tryBlockDeath(LivingDeathEvent event) {
    /*
     * If you die, you die. The invulnerability does not block death only damage. So if someone really wants to kill the player they can.
     * This is to allow this module to block full power guardian beam damage.
     * The undying module is intended to be the only way to have *some* change of *maybe* surviving a full power beam hit.
     * */
    if (event.getSource().is(DEDamage.GUARDIAN_LASER) && invulnerableTime > 0) {
        event.getEntity().setHealth(event.getEntity().getHealth() + 1);
        return true;
    }

    UndyingData data = module.getData();
    if (charge >= data.chargeTime()) {
        LivingEntity entity = event.getEntity();
        entity.setHealth(entity.getHealth() + data.healthBoost());
        ItemStack stack = entity.getItemBySlot(EquipmentSlot.CHEST);
        if (!stack.isEmpty()) {
            try (ModuleHost stackHost = DECapabilities.getHost(stack)) {
                if (stackHost != null) {
                    ShieldControlEntity shield = stackHost.getEntitiesByType(ModuleTypes.SHIELD_CONTROLLER).map(e -> (ShieldControlEntity) e).findAny().orElse(null);
                    if (shield != null) {
                        shield.boost(data.shieldBoost(), data.shieldBoostTime());
                    }
                }
            }
        }
        if (module.getModuleTechLevel().index >= 2) {
            entity.clearFire();
            Iterator<MobEffectInstance> iterator = entity.getActiveEffectsMap().values().iterator();
            while (iterator.hasNext()) {
                MobEffectInstance effect = iterator.next();
                if (!effect.getEffect().value().isBeneficial()) {
                    entity.onEffectRemoved(effect);
                    iterator.remove();
                }
            }
        }
        charge = 0;
        DraconicNetwork.sendUndyingActivation(entity, module.getItem());
        entity.level().playSound(null, entity.blockPosition(), SoundEvents.TOTEM_USE, SoundSource.PLAYERS, 5F, (0.95F + (entity.level().random.nextFloat() * 0.1F)));
        invulnerableTime = data.invulnerableTime();
        markDirty();
        return true;
    }
    return false;
}

