public boolean attackEntityPartFrom(DraconicGuardianPartEntity part, DamageSource source, float damage) {
    if (this.phaseManager.getCurrentPhase().getType() == PhaseType.DYING || source.getEntity() == this) {
        return false;
    } else {
        float shieldPower = getShieldPower();
        if (shieldPower > 0) {
            BCoreNetwork.sendSound(level(), blockPosition(), DESounds.SHIELD_STRIKE.get(), SoundSource.HOSTILE, 20, random.nextFloat() * 0.2F + 0.9F, false);
        }

        if (hitCoolDown > 0 && damage < lastDamage * 1.1F) {
            lastDamage = damage;
            return false;
        }
        lastDamage = damage;
        hitCoolDown = 5;

        if (fightManager != null && !fightManager.onGuardianAttacked(this, source, damage)) {
            this.phaseManager.getCurrentPhase().onAttacked(source, damage, shieldPower, false);
            return false;
        }

        damage = this.phaseManager.getCurrentPhase().onAttacked(source, damage, shieldPower, true);
        if (damage > 500) damage = 500;
        shieldPower -= Math.min(shieldPower, damage);
        if (shieldPower > 0) {
            setShieldPower(shieldPower);
            return true;
        } else {
            damage -= getShieldPower();
            setShieldPower(0);
        }

        if (damage > 100) damage = 100;

        if (part != this.dragonPartHead) {
            damage = (damage / 4.0F) + Math.min(damage, 1.0F);
        }

        if (damage < 0.01F) {
            return false;
        } else {
            if (source.getEntity() instanceof Player || source.is(DamageTypes.EXPLOSION)) {
                this.attackDragonFrom(source, damage);
                if (this.isDeadOrDying() && !this.phaseManager.getCurrentPhase().getIsStationary()) {
                    this.setHealth(1.0F);
                    this.phaseManager.setPhase(PhaseType.DYING);
                }
            }

            return true;
        }
    }
}

public static boolean addModifier(List<TempModifier> modifiers, TempModifier modifier, Placement placement,
                                  Consumer<TempModifier> onAdded, Consumer<TempModifier> onRemoved)
{
    boolean added = false;
    Predicate<TempModifier> predicate = placement.predicate();
    if (predicate == null) predicate = mod -> true;

    boolean isForward = placement.order() == Order.FIRST;
    Matcher duplicateMatcher = placement.duplicates();
    int maxDuplicates = placement.maxDuplicates();

    tryAdd:
    {
        if (duplicateMatcher != Matcher.IGNORE
        && modifiers.stream().filter(mod -> duplicateMatcher.check(modifier, mod)).count() >= maxDuplicates)
        {   break tryAdd;
        }

        if (modifiers.isEmpty())
        {
            if (placement.mode().isAdding())
            {
                modifiers.add(modifier);
                if (onAdded != null) onAdded.accept(modifier);
                return true;
            }
            else break tryAdd;
        }
        // Get the start of the iterator & which direction it's going
        int start = isForward ? 0 : (modifiers.size() - 1);
        // Iterate through the list (backwards if "forward" is false)
        for (int i = start; isForward ? i < modifiers.size() : i >= 0; i += isForward ? 1 : -1)
        {
            TempModifier modifierAt = modifiers.get(i);
            // If the predicate is true, inject the modifier at this position (or after it if "after" is true)
            if (predicate.test(modifierAt))
            {
                added = true;
                if (placement.mode() == Mode.REPLACE)
                {   modifiers.set(i, modifier);
                    if (onRemoved != null) onRemoved.accept(modifierAt);
                }
                else
                {   modifiers.add(i + (placement.mode() == Mode.ADD_AFTER ? 1 : 0), modifier);
                }
                if (onAdded != null) onAdded.accept(modifier);
                break tryAdd;
            }
        }
    }
    // Use fallback if modifier was not added
    if (!added && placement.fallback() != null)
    {   added = addModifier(modifiers, modifier, placement.fallback(), onAdded, onRemoved);
    }
    return added;
}

private int executeModifyEntityTemp(CommandSourceStack source, Collection<? extends Entity> entities, Temperature.Trait attribute,
                                    double amount, AttributeModifier.Operation operation, boolean permanent)
{
    for (Entity entity : entities)
    {
        if (EntityTempManager.isTemperatureEnabled(entity) && entity instanceof LivingEntity living)
        {
            AttributeInstance instance = EntityTempManager.getAttribute(attribute, living);
            if (instance == null) continue;
            if (operation != null)
            {
                AttributeModifier modifier = EntityTempManager.makeAttributeModifier(attribute, amount, operation);
                instance.addPermanentModifier(modifier);
            }
            else
            {   EntityTempManager.getAttribute(attribute, living).setBaseValue(amount);
            }
            EntityTempManager.getTemperatureCap(entity).ifPresent(cap ->
            {
                if (permanent)
                {   cap.markPersistentAttribute(instance.getAttribute());
                }
                else cap.clearPersistentAttribute(instance.getAttribute());
            });
        }
        else
        {   source.sendFailure(Component.translatable("commands.cold_sweat.temperature.invalid"));
            return 0;
        }
    }
    if (entities.size() == 1)
    {
        if (operation == null)
        source.sendSuccess(() ->
                           Component.translatable("commands.cold_sweat.temperature.modify.set.single.result",
                                                  attribute.getSerializedName(),
                                                  entities.iterator().next().getName().getString(), amount), true);
        else source.sendSuccess(() ->
                                Component.translatable("commands.cold_sweat.temperature.modify.add_modifier.single.result",
                                                       attribute.getSerializedName(),
                                                       entities.iterator().next().getName().getString()), true);
    }
    else
    {
        if (operation == null)
        source.sendSuccess(() ->
                           Component.translatable("commands.cold_sweat.temperature.modify.set.many.result",
                                                  attribute.getSerializedName(),
                                                  entities.size(), amount), true);
        else source.sendSuccess(() ->
                                Component.translatable("commands.cold_sweat.temperature.modify.add_modifier.many.result",
                                                       attribute.getSerializedName(),
                                                       entities.size()), true);
    }
    return entities.size();
}

private void handleBlink(ServerPlayer player, ItemStack stack, boolean showFuel) {
    if (!player.getAbilities().instabuild) {
        if (player.getCooldowns().isOnCooldown(stack.getItem())) {
            return;
        }
        int blinkFuel = getFuel(stack);
        if (blinkFuel <= 0) {
            if (!useFuel(stack, player)) {
                messageUser(player, Component.translatable("dislocate.draconicevolution.no_fuel").withStyle(ChatFormatting.RED));
                return;
            } else {
                blinkFuel = DEConfig.dislocatorBlinksPerPearl;
            }
        }

        blinkFuel--;
        setFuel(stack, blinkFuel);
        if (showFuel) {
            player.displayClientMessage(Component.translatable("dislocate.draconicevolution.teleport_fuel").append(" " + getFuel(stack)).withStyle(ChatFormatting.WHITE), true);
        }
        player.getCooldowns().addCooldown(stack.getItem(), 5);
    }

    Vec3 playerVec = player.getEyePosition(1);
    double range = DEConfig.dislocatorBlinkRange;
    Vec3 endVec = playerVec.add(player.getLookAngle().multiply(range, range, range));
    ClipContext context = new ClipContext(playerVec, endVec, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player);
    BlockHitResult result = player.level().clip(context);

    player.level().playSound(null, playerVec.x, playerVec.y, playerVec.z, DESounds.BLINK.get(), SoundSource.PLAYERS, 1F, 1F);

    DraconicNetwork.sendBlinkEffect(player, (float) (playerVec.distanceTo(endVec) / range));

    if (result.getType() == HitResult.Type.MISS) {
        if (player.isFallFlying()) { //Maintain momentum if elytra flying
            player.connection.teleport(endVec.x, endVec.y, endVec.z, player.getYRot(), player.getXRot(), Sets.newHashSet(RelativeMovement.X, RelativeMovement.Y, RelativeMovement.Z));
            player.setYHeadRot(player.getYRot());
        } else {
            TeleportUtils.teleportEntity(player, player.level().dimension(), endVec.x, endVec.y, endVec.z);
        }
    } else {
        BlockPos pos = result.getBlockPos().relative(result.getDirection());
        Vec3D vec = new Vec3D(pos).add(0.5, 0, 0.5);
        switch (result.getDirection()) {
            case DOWN:
            case UP:
                break;
            default:
                if (player.level().getBlockState(pos.below()).isPathfindable(PathComputationType.AIR)) {
                    vec.y -= 1;
                }
        }
        TeleportUtils.teleportEntity(player, player.level().dimension(), vec.x, vec.y, vec.z);
    }

    player.level().playSound(null, player.getX(), player.getY(), player.getZ(), DESounds.BLINK.get(), SoundSource.PLAYERS, 1F, 1F);

}

public static void onShearGoat(PlayerInteractEvent.EntityInteract event)
{
    Entity entity = event.getTarget();
    Player player = event.getEntity();
    ItemStack stack = event.getItemStack();

    if (entity instanceof LivingEntity living && (!(living instanceof AgeableMob ageable) || !ageable.isBaby())
    && !entity.level().isClientSide && stack.is(Tags.Items.SHEARS))
    {
        getFurCap(living).ifPresent(cap ->
        {
            if (cap.isSheared())
            {   event.setResult(PlayerInteractEvent.Result.DENY);
                return;
            }

            // Use shears
            player.swing(event.getHand(), true);
            shear(living, player);
            if (!player.getAbilities().instabuild)
            {   stack.hurtAndBreak(1, player, (p) -> p.broadcastBreakEvent(player.getUsedItemHand()));
            }

            // Random chance to ram the player when sheared
            if (living instanceof Goat goat && !player.getAbilities().instabuild && goat.level().getDifficulty() != Difficulty.PEACEFUL
            && !goat.level().isClientSide && goat.getRandom().nextDouble() < 0.4)
            {
                // Set ram cooldown ticks
                goat.getBrain().setMemory(MemoryModuleType.RAM_COOLDOWN_TICKS, 30);
                // Stop active goals
                for (WrappedGoal goal : goat.goalSelector.getAvailableGoals())
                {
                    if (goal.isInterruptable())
                    {   goal.stop();
                    }
                }

                // Start lowering head
                TaskScheduler.scheduleServer(() ->
                {
                    ClientboundEntityEventPacket packet = new ClientboundEntityEventPacket(goat, (byte) 58);
                    ((ServerChunkCache) goat.level().getChunkSource()).broadcastAndSend(goat, packet);
                }, 5);

                // Look at player
                BehaviorUtils.lookAtEntity(goat, player);
                // Stop walking
                goat.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);

                // Set ram target to player pos
                goat.getBrain().setMemory(MemoryModuleType.RAM_TARGET, player.position());
                TaskScheduler.scheduleServer(() ->
                {
                    if (player.distanceTo(goat) <= 10)
                    {
                        goat.playSound(goat.isScreamingGoat() ? SoundEvents.GOAT_SCREAMING_PREPARE_RAM : SoundEvents.GOAT_PREPARE_RAM, 1.0F, 1.0F);
                        goat.getBrain().setMemory(MemoryModuleType.RAM_TARGET, player.position());
                    }
                }, 30);

                // Trigger ram
                goat.getBrain().setActiveActivityIfPossible(Activity.RAM);
            }
            event.setResult(PlayerInteractEvent.Result.ALLOW);
        });
    }
}

public void inventoryTick(ItemStack stack, Level level, Entity entity, int itemSlot, boolean isSelected)
{
    if (!level.isClientSide && entity instanceof LivingEntity living && living.tickCount % 5 == 0)
    {
        boolean shouldBeOn = false;
        try
        {
            if (!(isSelected || living.getOffhandItem() == stack || CompatManager.Curios.hasCurio(living, stack)))
            {   return;
            }
            double max = Temperature.get(living, Temperature.Trait.BURNING_POINT);

            double temp = Temperature.getModifier(living, Temperature.Trait.WORLD, SoulLampTempModifier.class)
                          .map(mod -> mod.getLastInput(Temperature.Trait.WORLD)).orElseGet(() -> Temperature.get(living, Temperature.Trait.WORLD));

            // Is in valid dimension
            if ((ConfigSettings.LAMP_DIMENSIONS.get(level.registryAccess()).contains(level.dimensionType()))
            // Is world temp more than max
            && temp > max && getFuel(stack) > 0)
            {
                shouldBeOn = true;
                // Drain fuel
                if (!(living instanceof Player player && player.isCreative() || living.isSpectator()))
                {   addFuel(stack, -0.005 * CSMath.clamp(temp - max, 1, 3));
                }

                // Affect nearby players
                double radius = 5d;
                AABB bb = new AABB(living.getX() - radius, living.getY() + (living.getBbHeight() / 2) - radius, living.getZ() - radius,
                                   living.getX() + radius, living.getY() + (living.getBbHeight() / 2) + radius, living.getZ() + radius);

                if (Math.random() < 0.6)
                {
                    AABB bb2 = bb.inflate(-3);
                    double x = bb2.minX + (bb2.maxX - bb2.minX) * Math.random();
                    double y = bb2.minY + (bb2.maxY - bb2.minY) * Math.random();
                    double z = bb2.minZ + (bb2.maxZ - bb2.minZ) * Math.random();
                    double xSpeed = (Math.random() - 0.5) * 0.02;
                    double zSpeed = (Math.random() - 0.5) * 0.02;
                    new ParticleBatchMessage(0).addParticle(ParticleTypes.SOUL_FIRE_FLAME, x, y, z, xSpeed, 0, zSpeed)
                                               .sendEntity(living);
                }

                for (LivingEntity ent : WorldHelper.getEntitiesOfClass(LivingEntity.class, level, bb, e -> true))
                {
                    if (!EntityTempManager.isTemperatureEnabled(ent))
                    {   continue;
                    }
                    // Extend modifier time if it is present
                    Optional<SoulLampTempModifier> mod = Temperature.getModifier(ent, Temperature.Trait.WORLD, SoulLampTempModifier.class);
                    if (mod.isPresent())
                    {   mod.get().setTicksExisted(0);
                    }
                    else
                    {   Temperature.replaceOrAddModifier(ent, new SoulLampTempModifier().expires(5).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                    }
                }
            }
        }
        finally
        {
            // If the conditions are not met, turn off the lamp
            if (isLit(stack) != shouldBeOn)
            {
                setLit(stack, shouldBeOn);
                if (getFuel(stack) < 0.5)
                {   setFuel(stack, 0);
                }
                WorldHelper.playEntitySound(shouldBeOn ? ModSounds.SOUL_LAMP_ON : ModSounds.SOUL_LAMP_OFF, living, living.getSoundSource(), 1.5f, (float) Math.random() / 5f + 0.9f);
            }
        }
    }
}

public static void tickTemperature(LivingEvent.LivingTickEvent event)
{
    LivingEntity entity = event.getEntity();
    boolean isServer = !entity.level().isClientSide;
    if (!TEMPERATURE_ENABLED_ENTITIES.contains(entity.getType())) return;

    getTemperatureCap(entity).ifPresent(cap ->
    {
        // Tick modifiers serverside
        if (isServer)
        {   cap.tick(entity);
        }

        // Tick modifiers & removed expired
        AtomicBoolean sync = new AtomicBoolean(false);
        for (Trait trait : VALID_MODIFIER_TRAITS)
        {
            List<TempModifier> modifiers = cap.getModifiers(trait);
            for (int i = 0; i < modifiers.size(); i++)
            {
                TempModifier modifier = modifiers.get(i);
                // Tick modifier
                if (modifier.getTicksExisted() % modifier.getTickRate() == 0)
                {   modifier.tick(entity);
                }
                if (isServer)
                {
                    // Sync if the modifier is dirty
                    if (modifier.isDirty())
                    {   sync.set(true);
                        modifier.markClean();
                    }
                    // Remove expired modifiers
                    int expireTime = modifier.getExpireTime();
                    modifier.setTicksExisted(modifier.getTicksExisted() + 1);
                    if (modifier.getTicksExisted() > expireTime && expireTime != -1)
                    {
                        modifier.onRemoved(entity, trait);
                        Temperature.updateSiblingsRemove(modifiers, entity, trait, modifier);
                        modifiers.remove(i);
                        sync.set(true);
                        i--;
                    }
                }
            }
        }
        if (isServer && sync.get())
        {   Temperature.updateModifiers(entity, cap);
        }

        // Spawn particles for uninhabitable entities
        if (isServer && hasClimateData(entity))
        {
            if (entity.tickCount % 5 == 0 && entity.getRandom().nextDouble() < 0.1)
            {
                double worldTemp = cap.getTrait(Trait.WORLD);
                double entityX = entity.getX();
                double entityY = entity.getY() + entity.getBbHeight();
                double entityZ = entity.getZ();

                if (worldTemp < cap.getTrait(Trait.FREEZING_POINT))
                {
                    WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_COLD.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                   entity.getRandom().nextInt(2, 4), 0);
                }
                else if (worldTemp > cap.getTrait(Trait.BURNING_POINT))
                {
                    WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_HOT.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                   entity.getRandom().nextInt(2, 4), 0);
                }
            }
        }
    });
}

public void tick(ModuleContext moduleContext) {
    IOPStorage storage = moduleContext.getOpStorage();
    if (!(moduleContext instanceof StackModuleContext context && EffectiveSide.get().isServer() && storage != null)) {
        return;
    }

    if (tick++ % 10 == 0) clearCaches();
    markDirty();


    ShieldData shieldData = getShieldData(context.getEntity());
    data.shieldCapacity = shieldData.shieldCapacity();
    double chargeRate = shieldData.shieldRecharge();
    boolean enabled = shieldEnabled.getValue() && getShieldPoints() > 0;

    if (data.shieldPoints > data.shieldCapacity) {
        data.shieldPoints = data.shieldCapacity;
    }

    //# Rendering #
    //Hit Indicator (Controls the effect where the shield flashes brighter when hit)
    if (shieldHitIndicator > 0) {
        shieldHitIndicator -= 0.1F;
    }

    data.shieldVisible = enabled && (alwaysVisible.getValue() || System.currentTimeMillis() - lastHitTime < 5000);
    if (data.shieldVisible && shieldAnim < 1) {
        shieldAnim = Math.min(shieldAnim + 0.05F, 1F);
    } else if (!data.shieldVisible && shieldAnim > 0) {
        shieldAnim = Math.max(shieldAnim - 0.05F, 0F);
    }

    if (data.envDmgCoolDown > 0) data.envDmgCoolDown--;

    //# Logic #
    if (!context.isEquipped()) {
        return;
    }

    if (conflict) {
        data.shieldCapacity = 0;
        data.shieldPoints = 0;
        return;
    }

    //Passive Draw
    if (enabled && storage.getOPStored() > 0) {
        double passiveDraw = data.shieldPoints * data.shieldPoints * EquipCfg.shieldPassiveModifier;
        if (passiveDraw > 0) {
            passivePowerCache += passiveDraw;
            if (passivePowerCache >= 1) {
                storage.modifyEnergyStored(-(int) passivePowerCache);
                passivePowerCache = passivePowerCache % 1;
            }
        }
    } else if (enabled && data.shieldPoints > 0) {
        //Shield drains if you run out of power. It takes 60 seconds to drain from full to zero.
        data.shieldPoints = Math.max(0, data.shieldPoints - (data.shieldCapacity / (60D * 20D)));
    }
    if (data.shieldBoost > 0) {
        data.boostTime--;
        if (data.boostTime == 0) {
            data.shieldBoost = 0;
        }
    }

    //Recharge Logic
    if (!enabled) chargeRate *= 1.25;
    if (data.shieldCoolDown > 0) {
        data.shieldCoolDown = Math.max(0, data.shieldCoolDown - (enabled ? 100 : 125));
    } else if (data.shieldPoints < data.shieldCapacity && data.shieldCapacity > 0 && chargeRate > 0 && storage.getOPStored() > 0) {
        double energyPerPoint = Math.max(chargeRate * EquipCfg.energyShieldChg, EquipCfg.energyShieldChg);
        long extracted = storage.modifyEnergyStored(-(int) Math.max(1, Math.min(chargeRate, data.shieldCapacity - data.shieldPoints) * energyPerPoint));
        data.shieldPoints += extracted / energyPerPoint;
    }
}

public static void defineDefaultModifiers(DefaultTempModifiersEvent event)
{
    LivingEntity entity = event.getEntity();
    boolean isPlayer = entity instanceof Player;
    boolean isTempSensitive = entity.getType().is(ModEntityTags.TEMPERATURE_SENSITIVE);

    // Use a far more performant (less accurate) check for climate-enabled entities
    if (hasClimateData(entity))
    {
        boolean isAdvanced = ConfigSettings.ADVANCED_ENTITY_TEMPERATURE.get();
        boolean wasAdvanced = entity.getPersistentData().getBoolean("AdvancedTemperature");
        // Clear modifiers if the "Advanced" setting was changed
        if (isAdvanced != wasAdvanced)
        {   Temperature.getModifiers(entity).clear();
            entity.getPersistentData().putBoolean("AdvancedTemperature", isAdvanced);
        }
        // Use basic temp calculation if not advanced
        if (!isAdvanced)
        {
            event.addModifier(List.of(Trait.WORLD, Trait.FREEZING_POINT, Trait.BURNING_POINT),
                              new EntityClimateTempModifier().tickRate(200),
                              Placement.FIRST.noDuplicates(Matcher.SAME_CLASS));
            return;
        }
    }

    // TempModifier tick rate is generally slower for entities than for players
    double tickMultiplier = isPlayer ? 1
                          : isTempSensitive ? 4
                          : 40;
    int slowTickRate = (int) Math.min(60 * tickMultiplier, 400);
    int mediumTickRate = (int) (10 * tickMultiplier * 2);
    int mediumTickRate2 = (int) (10 * tickMultiplier);
    int fastTickRate = (int) (5 * tickMultiplier);

    event.addModifier(Trait.WORLD, new BiomeTempModifier(isPlayer ? 49 : isTempSensitive ? 16 : 9).tickRate(mediumTickRate),
                      Placement.FIRST.noDuplicates(Matcher.SAME_CLASS));

    event.addModifier(Trait.WORLD, new ElevationTempModifier(isPlayer ? 49 : isTempSensitive ? 16 : 1).tickRate(mediumTickRate),
                      Placement.of(Mode.ADD_AFTER, Order.FIRST, mod -> mod instanceof BiomeTempModifier).noDuplicates(Matcher.SAME_CLASS));

    event.addModifier(Trait.WORLD, new ShadeTempModifier().tickRate(10),
                      Placement.of(Mode.ADD_BEFORE, Order.FIRST, mod -> mod instanceof ElevationTempModifier).noDuplicates(Matcher.SAME_CLASS));

    event.addModifier(Trait.WORLD, new CaveBiomeTempModifier(isPlayer ? 6 : isTempSensitive ? 5 : 3).tickRate(mediumTickRate),
                      Placement.of(Mode.ADD_AFTER, Order.FIRST, mod -> mod instanceof ElevationTempModifier).noDuplicates(Matcher.SAME_CLASS));

    event.addModifier(Trait.WORLD, new BlockTempModifier(isPlayer ? -1 : 4).tickRate(fastTickRate),
                      Placement.LAST.noDuplicates(Matcher.SAME_CLASS));

    event.addModifier(Trait.WORLD, new EntitiesTempModifier().tickRate(mediumTickRate2),
                      Placement.LAST.noDuplicates(Matcher.SAME_CLASS));

    // Serene Seasons compat
    event.addModifierById(Trait.WORLD, new ResourceLocation("sereneseasons:season"),
                          mod -> mod.tickRate(slowTickRate),
                          Placement.of(Mode.ADD_AFTER, Order.FIRST, mod2 -> mod2 instanceof BiomeTempModifier).noDuplicates(Matcher.SAME_CLASS));
    // Weather2 Compat
    event.addModifierById(Trait.WORLD, new ResourceLocation("weather2:storm"),
                          mod -> mod.tickRate(slowTickRate),
                          Placement.of(Mode.ADD_AFTER, Order.FIRST, mod2 -> mod2 instanceof BiomeTempModifier).noDuplicates(Matcher.SAME_CLASS));
    // Sublevel block temperature (i.e. Valkyrien Skies ships)
    event.addModifierById(Trait.WORLD, new ResourceLocation(ColdSweat.MOD_ID, "sublevel_blocks"),
                          mod -> mod.tickRate(mediumTickRate2),
                          Placement.of(Mode.ADD_AFTER, Order.FIRST, mod2 -> mod2 instanceof BlockTempModifier).noDuplicates(Matcher.SAME_CLASS));
    // Ad Astra Compat
    event.addModifierById(Trait.WORLD, new ResourceLocation("ad_astra:oxygen"),
                          mod -> mod.tickRate(mediumTickRate2),
                          Placement.LAST.noDuplicates(Matcher.SAME_CLASS));

    if (isPlayer && !(entity instanceof DummyPlayer))
    {
        event.addModifier(List.of(Trait.FREEZING_POINT, Trait.BURNING_POINT), new AcclimationTempModifier().tickRate(20),
                          Placement.LAST.noDuplicates(Matcher.SAME_CLASS));
        event.addModifier(Arrays.asList(VALID_MODIFIER_TRAITS), new InventoryItemsTempModifier().tickRate(5),
                          Placement.LAST.noDuplicates(Matcher.SAME_CLASS));
    }
}

public void tick(LivingEntity entity)
{
    // Apply temp modifiers
    double worldTemp = this.modifyFromAttribute(entity, Trait.WORLD, 0);
    double baseTemp  = this.modifyFromAttribute(entity, Trait.BASE,  0);
    double coreTemp  = Temperature.apply(this.getTrait(Trait.CORE), entity, Trait.CORE, this.getModifiers(Trait.CORE));
    double maxTemp = this.modifyFromAttribute(entity, Trait.BURNING_POINT,  ConfigSettings.MAX_TEMP.get());
    double minTemp = this.modifyFromAttribute(entity, Trait.FREEZING_POINT, ConfigSettings.MIN_TEMP.get());
    double coldDampening  = this.modifyFromAttribute(entity, Trait.COLD_DAMPENING,  0);
    double heatDampening  = this.modifyFromAttribute(entity, Trait.HEAT_DAMPENING,  0);
    double coldResistance = this.modifyFromAttribute(entity, Trait.COLD_RESISTANCE, 0);
    double heatResistance = this.modifyFromAttribute(entity, Trait.HEAT_RESISTANCE, 0);

    double rate = 0;

    // 1 if newWorldTemp is above max, -1 if below min, 0 if between the values (safe)
    int worldTempSign = CSMath.getSignForRange(worldTemp, minTemp, maxTemp);

    // Don't change player temperature if they're in creative/spectator mode
    if (worldTempSign != 0 && (!(entity instanceof Player player) || !player.isCreative()) && !entity.isSpectator()
    && !isPeacefulMode(entity))
    {
        // How much hotter/colder the player's temp is compared to max/min
        double difference = Math.abs(worldTemp - CSMath.clamp(worldTemp, minTemp, maxTemp));

        // How much the player's temperature should change
        double changeBy = (Math.max(
                // Change proportionally to the w of the world temperature
                (difference / 7d) * ConfigSettings.TEMP_RATE.get(),
                // Ensure a minimum speed for temperature change
                Math.abs(ConfigSettings.TEMP_RATE.get() / 50d)
        // If it's hot or cold
        ) * worldTempSign);

        // Temp is decreasing; apply cold dampening
        if (changeBy < 0)
        {   changeBy = (coldDampening < 0
                        // Cold dampening is negative; increase the change by the dampening
                        ? changeBy * (1 + Math.abs(coldDampening))
                        // Cold dampening is positive; apply the change as a percentage of the dampening
                        : CSMath.blend(changeBy, 0, coldDampening, 0, 1));
        }
        // Temp is increasing; apply heat dampening
        else if (changeBy > 0)
        {   changeBy = (heatDampening < 0
                        // Heat dampening is negative; increase the change by the dampening
                        ? changeBy * (1 + Math.abs(heatDampening))
                        // Heat dampening is positive; apply the change as a percentage of the dampening
                        : CSMath.blend(changeBy, 0, heatDampening, 0, 1));
        }
        // Apply temp/attribute modifiers
        rate = this.modifyFromAttribute(entity, Trait.RATE, changeBy);
        // Apply rate multiplier if entity has climate data
        rate *= CSMath.getIfNotNull(ConfigHelper.getFirstOrNull(ConfigSettings.ENTITY_CLIMATES, entity.getType(), data -> data.test(entity)), EntityClimateData::rate, 1.0);
        // Apply the rate to entity's temperature
        coreTemp += rate;
    }

    // If needed, equalize the player's temperature back to 0
    double equilibrium = getEquilibriumDelta(coreTemp, entity);
    int coreDeltaSign = CSMath.sign(coreTemp - this.getTrait(Trait.CORE));
    int equilibriumSign = CSMath.sign(equilibrium);
    // Only apply equilibrium delta if it isn't working against any CORE modifiers
    if (coreDeltaSign == 0 || coreDeltaSign == equilibriumSign)
    {   coreTemp += equilibrium;
    }

    // Write the new temperature values
    this.setTrait(Trait.CORE, CSMath.clamp(coreTemp, -150, 150), entity);
    this.setTrait(Trait.BASE, CSMath.clamp(baseTemp, -150, 150), entity);
    this.setTrait(Trait.WORLD, worldTemp, entity);
    // Write the new ability values
    this.setTrait(Trait.BURNING_POINT, maxTemp);
    this.setTrait(Trait.FREEZING_POINT, minTemp);
    this.setTrait(Trait.COLD_RESISTANCE, coldResistance);
    this.setTrait(Trait.HEAT_RESISTANCE, heatResistance);
    this.setTrait(Trait.COLD_DAMPENING, coldDampening);
    this.setTrait(Trait.HEAT_DAMPENING, heatDampening);
    this.setTrait(Trait.RATE, rate);

    if (syncTimer > 0)
    {   syncTimer--;
    }

    // Sync the temperature values to the client
    if (changed && syncTimer <= 0)
    {   this.syncValues(entity);
    }

    // Deal damage to the player at a set interval if temperature is critical
    this.tickHurting(entity);
}

    public void handleClientAction(ServerPlayer player, ItemStack stack, MCDataInput input) {
        int action = input.readByte();
        int selectIndex = getSelectedIndex(stack);
        LinkedList<DislocatorTarget> list = new LinkedList<>(getTargetList(stack));
        //if (list.size() <= 1 && action != 6 && action != 0) return;
        DislocatorTarget selected = selectIndex >= 0 && selectIndex < list.size() ? list.get(selectIndex) : null;

        switch (action) {
            case 0: //Add Current Pos
                int mode = input.readByte();
                int index = input.readVarInt();
                DislocatorTarget newPoint = new DislocatorTarget(player).setName(input.readString());
                if (mode == 1 || index < 0) { //Add Top
                    list.addFirst(newPoint);
                } else if (mode == 2 || index >= list.size()) { //Add Bottom
                    list.addLast(newPoint);
                } else { //Add bellow selected
                    list.add(index, newPoint);
                }
                selected = newPoint;
                break;
            case 1: //Remove
                DataUtils.safeRemove(list, input.readVarInt());
                break;
            case 2: //Update Name
                DataUtils.ifPresent(list, input.readVarInt(), e -> e.setName(input.readString()));
                break;
            case 3: //Update Lock
                DataUtils.ifPresent(list, input.readVarInt(), e -> e.setLocked(input.readBoolean()));
                break;
            case 4: //Set Selected
                selected = DataUtils.safeGet(list, input.readVarInt());
                break;
            case 5: //Set Blink Mode
                setBlinkMode(stack, input.readBoolean());
                break;
            case 6: //Add Fuel
                addFuel(stack, player, input.readBoolean(), input.readBoolean());
                return;
            case 7: //Update Pos
                DataUtils.ifPresent(list, input.readVarInt(), e -> e.update(player));
                break;
            case 8: //Teleport
                DataUtils.ifPresent(list, input.readVarInt(), e -> handleTeleport(player, stack, e == null ? null : e.pos, true));
                break;
            case 9: //Scroll
                break;
            case 10: //Move
                if (list.size() == 0) return;
                if (selected == null) return;
//                boolean up = input.readBoolean();
                int newIndex = input.readVarInt();
                if (newIndex > selectIndex) newIndex--;
                if (newIndex < 0 || newIndex >= list.size()) return;
                list.remove(selected);
                list.add(newIndex, selected);

//                list.set(newIndex, selected);
//                list.set(selectIndex, swapWith);
                break;
            case 11: //Teleport to selected
                if (list.size() == 0) return;
                handleTeleport(player, stack, selected == null ? null : selected.pos, true);
                break;
            case 12: //Blink
                handleBlink(player, stack, true);
                break;
            case 13: //Select Next / Previous
                if (list.size() == 0) return;
                selected = DataUtils.safeGet(list, Math.floorMod(selectIndex += input.readBoolean() ? 1 : -1, list.size()));
                if (selected != null) {
                    DislocatorTarget up = DataUtils.safeGet(list, Math.floorMod(selectIndex - 1, list.size()));
                    DislocatorTarget down = DataUtils.safeGet(list, Math.floorMod(selectIndex + 1, list.size()));
                    if (up != null) ChatHelper.sendIndexed(player, Component.literal(up.getName()).withStyle(ChatFormatting.GRAY), MSG_ID1);
                    ChatHelper.sendIndexed(player, Component.literal(ChatFormatting.GREEN + ">" + ChatFormatting.GOLD + selected.getName() + ChatFormatting.GREEN + "<"), MSG_ID2);
                    if (down != null) ChatHelper.sendIndexed(player, Component.literal(down.getName()).withStyle(ChatFormatting.GRAY), MSG_ID3);
                }
                break;
            default:
                return;
        }

        setTargetList(stack, list);
        if (selected != null) {
            if (list.contains(selected)) {
                setSelectedIndex(stack, list.indexOf(selected));
            } else if (selectIndex > 0 && selectIndex - 1 < list.size()) {
                setSelectedIndex(stack, selectIndex - 1);
            }
        } else {
            setSelectedIndex(stack, 0);
        }
    }

private static void logAndAddRegistries(RegistryAccess registryAccess, Multimap<RegistryHolder<?>, Holder<? extends ConfigData>> registries)
{
    // Ensure default registry entries load last
    setDefaultRegistryPriority(registries);

    // Load registry removals
    loadRegistryModifiers(registryAccess);

    // Mark holders as "JSON"
    for (Holder<? extends ConfigData> holder : registries.values())
    {   holder.value().setConfigType(ConfigData.Type.JSON);
    }

    // Fire pre-registry-loading event
    LoadRegistriesEvent.Pre event = new LoadRegistriesEvent.Pre(registryAccess, registries, REGISTRY_MODIFIERS);
    MinecraftForge.EVENT_BUS.post(event);

    // Remove registries that don't have required loaded mods
    registries.values().removeIf(holder -> !holder.get().areRequiredModsLoaded());

    // Remove registry entries that match removal criteria
    modifyRegistries(event.getRegistries());

    /*
     Add JSON data to the config settings
     */
    // insulators
    Collection<Holder<InsulatorData>> insulators = event.getRegistry(ModRegistries.INSULATOR_DATA);
    addInsulatorConfigs(insulators);
    logRegistryLoaded(String.format("Loaded %s insulators", insulators.size()), insulators);
    // fuels
    Collection<Holder<FuelData>> fuels = event.getRegistry(ModRegistries.FUEL_DATA);
    addFuelConfigs(fuels);
    logRegistryLoaded(String.format("Loaded %s fuels", fuels.size()), fuels);
    // foods
    Collection<Holder<FoodData>> foods = event.getRegistry(ModRegistries.FOOD_DATA);
    addFoodConfigs(foods);
    logRegistryLoaded(String.format("Loaded %s foods", foods.size()), foods);
    // item temperatures
    Collection<Holder<ItemTempData>> itemTemps = event.getRegistry(ModRegistries.ITEM_TEMP_DATA);
    addItemTempConfigs(itemTemps);
    logRegistryLoaded(String.format("Loaded %s item temperatures", itemTemps.size()), itemTemps);
    // drying items
    Collection<Holder<DryingItemData>> dryingItems = event.getRegistry(ModRegistries.DRYING_ITEM_DATA);
    addDryingItemConfigs(dryingItems);
    logRegistryLoaded(String.format("Loaded %s drying items", dryingItems.size()), dryingItems);
    // insulation slots
    Collection<Holder<ItemInsulationSlotsData>> insulationSlots = event.getRegistry(ModRegistries.INSULATION_SLOTS_DATA);
    addInsulationSlotConfigs(insulationSlots);
    logRegistryLoaded(String.format("Loaded %s insulation slots configs", insulationSlots.size()), insulationSlots);

    // block temperatures
    Collection<Holder<BlockTempData>> blockTemps = event.getRegistry(ModRegistries.BLOCK_TEMP_DATA);
    addBlockTempConfigs(blockTemps);
    logRegistryLoaded(String.format("Loaded %s block temperatures", blockTemps.size()), blockTemps);
    // biome temperatures
    Collection<Holder<BiomeTempData>> biomeTemps = event.getRegistry(ModRegistries.BIOME_TEMP_DATA);
    addBiomeTempConfigs(biomeTemps, registryAccess);
    logRegistryLoaded(String.format("Loaded %s biome temperatures", biomeTemps.size()), biomeTemps);
    // dimension temperatures
    Collection<Holder<DimensionTempData>> dimensionTemps = event.getRegistry(ModRegistries.DIMENSION_TEMP_DATA);
    addDimensionTempConfigs(dimensionTemps, registryAccess);
    logRegistryLoaded(String.format("Loaded %s dimension temperatures", dimensionTemps.size()), dimensionTemps);
    // structure temperatures
    Collection<Holder<StructureTempData>> structureTemps = event.getRegistry(ModRegistries.STRUCTURE_TEMP_DATA);
    addStructureTempConfigs(structureTemps, registryAccess);
    logRegistryLoaded(String.format("Loaded %s structure temperatures", structureTemps.size()), structureTemps);
    // depth temperatures
    Collection<Holder<DepthTempData>> depthTemps = event.getRegistry(ModRegistries.DEPTH_TEMP_DATA);
    addDepthTempConfigs(depthTemps, registryAccess);
    logRegistryLoaded(String.format("Loaded %s depth temperatures", depthTemps.size()), depthTemps);

    // mounts
    Collection<Holder<MountData>> mounts = event.getRegistry(ModRegistries.MOUNT_DATA);
    addMountConfigs(mounts);
    logRegistryLoaded(String.format("Loaded %s insulated mounts", mounts.size()), mounts);
    // spawn biomes
    Collection<Holder<SpawnBiomeData>> spawnBiomes = event.getRegistry(ModRegistries.ENTITY_SPAWN_BIOME_DATA);
    addSpawnBiomeConfigs(spawnBiomes, registryAccess);
    logRegistryLoaded(String.format("Loaded %s entity spawn biomes", spawnBiomes.size()), spawnBiomes);
    // entity temperatures
    Collection<Holder<EntityTempData>> entityTemps = event.getRegistry(ModRegistries.ENTITY_TEMP_DATA);
    addEntityTempConfigs(entityTemps);
    logRegistryLoaded(String.format("Loaded %s entity temperatures", entityTemps.size()), entityTemps);
    // entity climates
    Collection<Holder<EntityClimateData>> entityClimates = event.getRegistry(ModRegistries.ENTITY_CLIMATE_DATA);
    addEntityClimateConfigs(entityClimates);
    logRegistryLoaded(String.format("Loaded %s entity climates", entityClimates.size()), entityClimates);
    // temp effects
    Collection<Holder<TempEffectsData>> tempEffects = event.getRegistry(ModRegistries.TEMP_EFFECTS_DATA);
    addTempEffectsConfigs(tempEffects);
    logRegistryLoaded(String.format("Loaded %s temp effects", tempEffects.size()), tempEffects);

    // Fire post-registry-loading event
    LoadRegistriesEvent.Post postEvent = new LoadRegistriesEvent.Post(registryAccess, event.getRegistries());
    MinecraftForge.EVENT_BUS.post(postEvent);
}

protected void onHitEntity(EntityHitResult p_213868_1_) {
    Entity entity = p_213868_1_.getEntity();
    float velLength = (float) this.getDeltaMovement().length();
    double baseDamage = this.getBaseDamage();
    Entity owner = this.getOwner();
    DamageSource damagesource = getDamageSource(entity);
    if (this.getWeaponItem() != null && this.level() instanceof ServerLevel serverlevel) {
        baseDamage = EnchantmentHelper.modifyDamage(serverlevel, this.getWeaponItem(), entity, damagesource, (float)baseDamage);
    }
    int damage = Mth.ceil(Mth.clamp((double)velLength * baseDamage, 0.0D, 2.147483647E9D));

    int penetration = entityData.get(PENETRATION);
    if (this.getPierceLevel() > 0 || penetration > 0) {
        if (this.piercingIgnoreEntityIds == null) {
            this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
        }

        if (this.piercedAndKilledEntities == null) {
            this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
        }

        if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1 && this.piercingIgnoreEntityIds.size() >= penetration + 1) {
            this.discard();
            return;
        }

        this.piercingIgnoreEntityIds.add(entity.getId());
    }

    if (this.isCritArrow()) {
        long j = (long) this.random.nextInt(damage / 2 + 2);
        damage = (int) Math.min(j + (long) damage, 2147483647L);
    }

    boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
    int k = entity.getRemainingFireTicks();
    if (this.isOnFire() && !isEnderman) {
        entity.setRemainingFireTicks(5);
    }

    //Break shields with penetration
    if (penetration > 1 && entity instanceof Player) {
        Player player = (Player) entity;
        if (player.isUsingItem() && player.getUseItem().getItem() instanceof ShieldItem) {
            player.getCooldowns().addCooldown(player.getUseItem().getItem(), 100);
            level().broadcastEntityEvent(player, (byte) 30);
            player.stopUsingItem();
        }
    }

    if (entity.hurt(damagesource, (float) damage)) {
        if (isEnderman) {
            return;
        }

        if (entity instanceof LivingEntity livingentity) {
            if (!level().isClientSide && this.getPierceLevel() <= 0 && penetration <= 0) {
                livingentity.setArrowCount(livingentity.getArrowCount() + 1);
            }

            this.doKnockback(livingentity, damagesource);
            if (this.level() instanceof ServerLevel serverlevel1) {
                EnchantmentHelper.doPostAttackEffectsWithItemSource(serverlevel1, livingentity, damagesource, this.getWeaponItem());
            }

            this.doPostHurtEffects(livingentity);
            if (livingentity != owner && livingentity instanceof Player && owner instanceof ServerPlayer && !this.isSilent()) {
                ((ServerPlayer) owner).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
            }

            if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                this.piercedAndKilledEntities.add(livingentity);
            }

            if (!level().isClientSide && owner instanceof ServerPlayer serverPlayer) {
                if (this.piercedAndKilledEntities != null && this.shotFromCrossbow()) {
                    CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverPlayer, this.piercedAndKilledEntities);
                } else if (!entity.isAlive() && this.shotFromCrossbow()) {
                    CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverPlayer, Arrays.asList(entity));
                }
            }
        }

        this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
        if (this.getPierceLevel() <= 0 && penetration <= 0) {
            this.discard();
        }
    } else {
        entity.setRemainingFireTicks(k);
        this.setDeltaMovement(this.getDeltaMovement().scale(0));
        this.setYRot(getYRot() + 180.0F);
        this.yRotO += 180.0F;
        if (!level().isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
            if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                this.spawnAtLocation(this.getPickupItem(), 0.1F);
            }

            this.discard();
        }
    }
}

public void tick(Level level, BlockPos pos)
{
    // Init the hearth upon first tick
    if (this.ticksExisted == 0)
    {   this.init();
    }

    // Easy access to clientside testList::stream
    boolean isClient = level.isClientSide;

    this.ticksExisted++;

    if (rebuildCooldown > 0) rebuildCooldown--;

    if (this.ticksExisted % 200 == 0)
    {   this.ensurePathSynchronization();
    }

    // Locate nearby entities
    if (this.level != null && this.ticksExisted % 20 == 0)
    {
        this.isEntityNearby = false;
        entities.clear();
        AABB searchArea = new AABB(WorldHelper.sublevelToWorld(level, pos)).inflate(this.getMaxRange());

        for (Entity entity : WorldHelper.getEntities(this.level, searchArea, EntityTempManager::isTemperatureEnabled))
        {
            if (entity instanceof LivingEntity living)
            {   this.entities.add(living);
                this.isEntityNearby = true;
            }
        }
    }

    // Tick down the time for each effect
    this.tickPotionEffects();

    if (this.rebuildCooldown <= 0 && !this.queuedUpdates.isEmpty())
    {
        this.rebuildCooldown = 100;
        for (BlockPos updatedPos : this.queuedUpdates)
        {
            seeSkyMap.remove(new BlockPos2D(updatedPos.getX(), updatedPos.getZ()));

            SpreadPath path = this.pathLookup.get(updatedPos);
            if (path != null)
            {   // removePath/removePaths wake up whatever's adjacent to every freed position
                this.removePaths(path.getChildrenRecursive());
                this.removePath(path);
            }
            else
            {   // Not currently live — clear any stale rejection marker so it can be reattempted,
                // and wake up whatever's adjacent so it reconsiders spreading here
                this.pathLookup.remove(updatedPos);
                this.wakeNeighbors(updatedPos);
            }
        }
        this.queuedUpdates.clear();
        if (isClient)
        {   HearthDebugRenderer.updatePaths(this);
        }
    }

    if (this.getColdFuel() > 0 || this.getHotFuel() > 0)
    {
        // Gradually increases insulation amount
        if (insulationLevel < this.getInsulationTime())
        {   insulationLevel++;
        }

        if ((this.usingColdFuel || this.usingHotFuel || (this.isSmartEnabled() && this.isEntityNearby)))
        {
            // Determine whether particles are enabled
            if (this.ticksExisted % 20 == 0)
            {
                showParticles = isClient
                        && Minecraft.getInstance().options.particles().get() == ParticleStatus.ALL
                        && !HearthSaveDataHandler.DISABLED_HEARTHS.contains(levelPos);
            }

            if (paths.isEmpty())
            {   this.traversePipes();
            }

            // Mark as not spreading if all paths are frozen
            this.spreading = this.frozenPaths < paths.size();

            int pathCount = paths.size();
            // Spread to new blocks
            // Only tick paths every 20 ticks for hearths with one or fewer paths (prevents hearths that can't spread causing undue lag)
            if (this.spreading && (this.hasSmokestack && this.paths.size() > 1 || this.ticksExisted % 20 == 0))
            {   this.tickPaths();
            }
            if (isClient && spreading && paths.size() != pathCount)
            {   HearthDebugRenderer.updatePaths(this);
                this.traversePipes();
            }

            // Give insulation to players
            if (!isClient && this.ticksExisted % 20 == 0)
            {
                boolean isProvidingInsulation = false;
                // Provide insulation to players & calculate fuel usage
                for (int i = 0; i < entities.size(); i++)
                {
                    LivingEntity entity = entities.get(i);
                    if (entity == null || entity instanceof DummyPlayer) continue;
                    BlockPos entityPos = WorldHelper.worldToSublevel(this.level, entity.blockPosition());
                    // Check if entity is in valid position & insulate
                    if (this.areaContainsEntity(entity) && !WorldHelper.canSeeSky(level, entityPos, 64))
                    {   isProvidingInsulation |= this.insulateEntity(entity);
                    }
                }
                if (this.isSmartEnabled() && !isProvidingInsulation)
                {   this.clearFuelUsage();
                }
            }

            // Drain fuel
            if (!isClient)
            {   this.tickDrainFuel();
            }

            // Spawn air particles
            if (level.isClientSide)
            {   this.spawnRandomAirParticles();
            }
        }
    }
    // Periodically check for fuel input
    if (this.ticksExisted % 40 == 0)
    {   this.checkForFuel();
    }
    // Ensure correct block state
    if (!isClient)
    {   this.checkForStateChange();
    }
    // Update fuel
    if (!isClient && this.isFuelChanged())
    {   this.updateFuelState();
    }
    // Particles
    if (isClient)
    {   this.tickParticles();
    }
}

