public ActionResult onItemRightClick(ItemStack itemStackIn, World worldIn, PlayerEntity playerIn, Hand hand) {
    int range = (int) applyPropertyModifiers(MPAConstants.BLINK_DRIVE_RANGE);
    int energyConsumption = getEnergyUsage();

    RayTraceResult hitRayTrace = rayTrace(worldIn, playerIn, RayTraceContext.FluidMode.SOURCE_ONLY, range);
    if (hitRayTrace != null && hitRayTrace.getType() == RayTraceResult.Type.BLOCK) {
        double distance = hitRayTrace.getHitVec().distanceTo(playerIn.getPositionVec());

        // adjust energy consumption for actual distance.
        energyConsumption = (int) (energyConsumption * (distance/range));

        if (ElectricItemUtils.getPlayerEnergy(playerIn) > energyConsumption) {
            PlayerUtils.resetFloatKickTicks(playerIn);
            int amountDrained = ElectricItemUtils.drainPlayerEnergy(playerIn, energyConsumption);
            worldIn.playSound(playerIn, playerIn.getPosition(), SoundEvents.ENTITY_ENDERMAN_TELEPORT, SoundCategory.PLAYERS, 0.5F, 0.4F / ((float) Math.random() * 0.4F + 0.8F));
            PlayerUtils.teleportEntity(playerIn, hitRayTrace);
            worldIn.playSound(playerIn, playerIn.getPosition(), SoundEvents.ENTITY_ENDERMAN_TELEPORT, SoundCategory.PLAYERS, 0.5F, 0.4F / ((float) Math.random() * 0.4F + 0.8F));
            return ActionResult.resultSuccess(itemStackIn);
        }
    }
    return ActionResult.resultPass(itemStackIn);
}

public void onPlayerTickActive(PlayerEntity player, @Nonnull ItemStack itemStackIn) {
    if (player.abilities.isFlying || player.isPassenger() || player.isElytraFlying() || !player.isOnGround())
        onPlayerTickInactive(player, itemStackIn);

    // really hate running this check on every tick but needed for player speed adjustments
    if (ElectricItemUtils.getPlayerEnergy(player) < ElectricItemUtils.getMaxPlayerEnergy(player)) {
        itemStackIn.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(h->{
            if(h instanceof IModularItem && !((IModularItem) h).isModuleOnline(MPARegistryNames.SPRINT_ASSIST_MODULE_REGNAME));
            // only fires if the sprint assist module isn't installed and active
            MovementManager.INSTANCE.setMovementModifier(itemStackIn, 0, player);
        });

        // server side
        if (!player.world.isRemote &&
                // every 20 ticks
                (player.world.getGameTime() % 20) == 0 &&
                // player not jumping, flying, or riding
                player.isOnGround()) {
            double distance = player.distanceWalkedModified - player.prevDistanceWalkedModified;
            ElectricItemUtils.givePlayerEnergy(player, (int) (distance * 10 * applyPropertyModifiers(MPAConstants.ENERGY_GENERATION)));
        }
    }
}

