public boolean hitEntity(ItemStack itemStack, LivingEntity target, LivingEntity attacker) {
    if (attacker instanceof PlayerEntity) {
        itemStack.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(iItemHandler -> {
            if (iItemHandler instanceof IModeChangingItem) {
                ((IModeChangingItem) iItemHandler).getOnlineModuleOrEmpty(MPARegistryNames.MELEE_ASSIST_MODULE_REGNAME)
                        .getCapability(PowerModuleCapability.POWER_MODULE).ifPresent(pm->{
                    PlayerEntity player = (PlayerEntity) attacker;
                    double drain = pm.applyPropertyModifiers(MPAConstants.PUNCH_ENERGY);
                    if (ElectricItemUtils.getPlayerEnergy(player) > drain) {
                        ElectricItemUtils.drainPlayerEnergy(player, (int) drain);
                        double damage = pm.applyPropertyModifiers(MPAConstants.PUNCH_DAMAGE);
                        double knockback = pm.applyPropertyModifiers(MPAConstants.PUNCH_KNOCKBACK);
                        DamageSource damageSource = DamageSource.causePlayerDamage(player);
                        if (target.attackEntityFrom(damageSource, (float) (int) damage)) {
                            Vector3d lookVec = player.getLookVec();
                            target.addVelocity(lookVec.x * knockback, Math.abs(lookVec.y + 0.2f) * knockback, lookVec.z * knockback);
                        }
                    }
                });
            }
        });
    }
    return true;
}

    public void handleFallEvent(LivingFallEvent event) {
        if (event.getEntityLiving() instanceof PlayerEntity && event.getDistance() > 3.0) {
            PlayerEntity player = (PlayerEntity) event.getEntityLiving();
            ItemStack boots = player.getItemStackFromSlot(EquipmentSlotType.FEET);
            boots.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(iModularItem -> {
                if (!(iModularItem instanceof IModularItem)) {
                    return;
                }

                ItemStack shockAbsorbers = ((IModularItem) iModularItem).getOnlineModuleOrEmpty(MPARegistryNames.SHOCK_ABSORBER_MODULE_REGNAME);
                shockAbsorbers.getCapability(PowerModuleCapability.POWER_MODULE).ifPresent(sa -> {
                    double distanceAbsorb = event.getDistance() * sa.applyPropertyModifiers(MPAConstants.MULTIPLIER);
                    if (player.world.isRemote && MPALibSettings.useSounds()) {
                        Musique.playerSound(player, SoundDictionary.SOUND_EVENT_GUI_INSTALL, SoundCategory.PLAYERS, (float) (distanceAbsorb), (float) 1, false);
                    }
                    double drain = distanceAbsorb * sa.applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);
                    int avail = ElectricItemUtils.getPlayerEnergy(player);
                    if (drain < avail) {
                        ElectricItemUtils.drainPlayerEnergy(player, (int) drain);
                        event.setDistance((float) (event.getDistance() - distanceAbsorb));
//                        event.getEntityLiving().sendMessage(new TextComponentString("modified fall settings: [ damage : " + event.getDamageMultiplier() + " ], [ distance : " + event.getDistance() + " ]"));
                    }
                });
            });
        }
    }

public void onPlayerTickActive(PlayerEntity player, ItemStack chestPlate) {
