                    }
                }
                // fill by being in the rain or bubble column
            } else if (player.isInWaterRainOrBubbleColumn()) {
                FluidStack water = new FluidStack(Fluids.WATER, 100);
                if (fluidHandler.fill(water, IFluidHandler.FluidAction.EXECUTE) > 0) {
                    player.playSound(SoundEvents.ITEM_BUCKET_FILL, 1.0F, 1.0F);
                }
            }
        }
    }

    // Apply cooling
    double currentHeat = HeatUtils.getPlayerHeat(player);
    double maxHeat = HeatUtils.getPlayerMaxHeat(player);
    if ((currentHeat / maxHeat) >= ticker.applyPropertyModifiers(MPAConstants.HEAT_ACTIVATION_PERCENT)) {

        // cool 200 per bucket
        double coolAmount = fluidHandler.drain(
                // adjust so cooling does not exceed cooling needed
                (int) Math.min(1000, currentHeat/coolingFactor),
                // only execute on server, simulate on client
                player.world.isRemote ? IFluidHandler.FluidAction.SIMULATE : IFluidHandler.FluidAction.EXECUTE)
                .getAmount() * coolingFactor;

        HeatUtils.coolPlayer(player, coolAmount);
        if (coolAmount > 0) {
            player.world.playSound(player, player.getPosition(), SoundEvents.ENTITY_GENERIC_EXTINGUISH_FIRE, SoundCategory.MASTER, 1.0F, 1.0F);
            for (int i = 0; i < 4; i++) {
                player.world.addOptionalParticle(ParticleTypes.SMOKE, player.getPosX(), player.getPosY() + 0.5, player.getPosZ(), 0.0D, 0.0D, 0.0D);
            }
        }
    }
}

public void onPlayerTickActive(PlayerEntity player, ItemStack stack) {
    int energyUSage = (int) applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);

    if (ElectricItemUtils.getPlayerEnergy(player) > energyUSage) {
        boolean isServerSide = !player.world.isRemote;

        if ((player.world.getGameTime() % 20) == 0 && isServerSide) {
            ElectricItemUtils.drainPlayerEnergy(player, energyUSage);
        }
        int range = (int) applyPropertyModifiers(MPAConstants.RADIUS);
        World world = player.world;
        AxisAlignedBB bounds = player.getBoundingBox().grow(range);

        if (isServerSide) {
            bounds.expand(0.2000000029802322D, 0.2000000029802322D, 0.2000000029802322D);
            if (stack.getDamage() >> 1 >= 7) {
                List<ArrowEntity> arrows = world.getEntitiesWithinAABB(ArrowEntity.class, bounds);
                for (ArrowEntity arrow : arrows) {
                    if ((arrow.pickupStatus == ArrowEntity.PickupStatus.ALLOWED) && (world.rand.nextInt(6) == 0)) {
                        ItemEntity replacement = new ItemEntity(world, arrow.getPosX(), arrow.getPosY(), arrow.getPosZ(), new ItemStack(Items.ARROW));
                        world.addEntity(replacement);
                    }
                    arrow.remove();
                }
            }
        }

        for (ItemEntity e : world.getEntitiesWithinAABB(ItemEntity.class, bounds)) {
            if (e.isAlive() && !e.getItem().isEmpty() && !e.cannotPickup()) {
                if (isServerSide) {
                    double x = player.getPosX() - e.getPosX();
                    double y = player.getPosY() - e.getPosY();
                    double z = player.getPosZ() - e.getPosZ();

                    double length = Math.sqrt(x * x + y * y + z * z) * 0.75D;

                    x = x / length + player.getMotion().x * 22.0D;
                    y = y / length + player.getMotion().y / 22.0D;
                    z = z / length + player.getMotion().z * 22.0D;

                    e.setMotion(x, y, z);

                    e.isAirBorne = true;
                    if (e.collidedHorizontally) {
                        e.setMotion(e.getMotion().add(0, 1, 0));
                    }
                } else if (world.rand.nextInt(20) == 0) {
                    float pitch = 0.85F - world.rand.nextFloat() * 3.0F / 10.0F;
                    world.playSound(e.getPosX(), e.getPosY(), e.getPosZ(), SoundEvents.ENTITY_ENDERMAN_TELEPORT, SoundCategory.PLAYERS, 0.6F, pitch, true);
                }
            }
        }
    }
}

public boolean onBlockStartBreak(ItemStack itemStack, BlockPos posIn, PlayerEntity player) {
    if (player.world.isRemote)
        return false; // fixme : check?
    AtomicBoolean harvested = new AtomicBoolean(false);
    RayTraceResult rayTraceResult = rayTrace(player.world, player, RayTraceContext.FluidMode.SOURCE_ONLY);
    if (rayTraceResult == null || rayTraceResult.getType() != RayTraceResult.Type.BLOCK) {
        return false;
    }
    int radius = (int) (applyPropertyModifiers(MPAConstants.AOE_MINING_RADIUS) - 1) / 2;
    if (radius == 0)
        return false;

    Direction side = ((BlockRayTraceResult) rayTraceResult).getFace();
    Stream<BlockPos> posList;
    switch (side) {
        case UP:
        case DOWN:
            posList = BlockPos.getAllInBox(posIn.north(radius).west(radius), posIn.south(radius).east(radius));
            break;

        case EAST:
        case WEST:
            posList = BlockPos.getAllInBox(posIn.up(radius).north(radius), posIn.down(radius).south(radius));
            break;

        case NORTH:
        case SOUTH:
            posList = BlockPos.getAllInBox(posIn.up(radius).west(radius), posIn.down(radius).east(radius));
            break;

        default:
            posList = new ArrayList<BlockPos>().stream();
    }
    int energyUsage = this.getEnergyUsage();
    AtomicInteger blocksBroken = new AtomicInteger(0);
    posList.forEach(blockPos-> {
        BlockState state = player.world.getBlockState(blockPos);
        int playerEnergy = ElectricItemUtils.getPlayerEnergy(player);
        itemStack.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(modeChanging -> {
            if (modeChanging instanceof IModeChangingItem) {
                for (ItemStack blockBreakingModule : ((IModeChangingItem) modeChanging).getInstalledModulesOfType(IBlockBreakingModule.class)) {

                    if (blockBreakingModule.getCapability(PowerModuleCapability.POWER_MODULE).map(b -> {
                        if(b instanceof IBlockBreakingModule) {
                            if (((IBlockBreakingModule) b).canHarvestBlock(itemStack, state, player, blockPos, playerEnergy - energyUsage)) {
                                return true;
                            }
                        }
                        return false;
                    }).orElse(false)) {
                        if (posIn == blockPos) { // center block
                            harvested.set(true);
                        }
                        blocksBroken.getAndAdd(1);
                        Block.replaceBlock(state, Blocks.AIR.getDefaultState(), player.world, blockPos, Constants.BlockFlags.DEFAULT);
                        ElectricItemUtils.drainPlayerEnergy(player,
                                blockBreakingModule.getCapability(PowerModuleCapability.POWER_MODULE).map(m -> {
                                    if (m instanceof IBlockBreakingModule) {
                                        return ((IBlockBreakingModule) m).getEnergyUsage();
                                    }
                                    return 0;
                                }).orElse(0) + energyUsage);
                        break;
                    }
                }
            }
        });
    });
    return harvested.get();
}

