public void handleLivingJumpEvent(LivingJumpEvent event) {
    if (event.getEntityLiving() instanceof EntityPlayer) {
        EntityPlayer player = (EntityPlayer) event.getEntityLiving();
        ItemStack stack = player.getItemStackFromSlot(EntityEquipmentSlot.LEGS);

        if (stack != null && stack.getItem() instanceof ItemPowerArmor
                && ModuleManager.itemHasActiveModule(stack, JumpAssistModule.MODULE_JUMP_ASSIST)) {
            double jumpAssist = ModuleManager.computeModularProperty(stack, JumpAssistModule.JUMP_MULTIPLIER) * 2;
            double drain = ModuleManager.computeModularProperty(stack, JumpAssistModule.JUMP_ENERGY_CONSUMPTION);
            double avail = ElectricItemUtils.getPlayerEnergy(player);
            if ((FMLCommonHandler.instance().getEffectiveSide() == Side.CLIENT) && NuminaConfig.useSounds()) {
                Musique.playerSound(player, SoundDictionary.SOUND_EVENT_JUMP_ASSIST, SoundCategory.PLAYERS, (float) (jumpAssist / 8.0), (float) 1, false);
            }
            if (drain < avail) {
                ElectricItemUtils.drainPlayerEnergy(player, drain);
                setPlayerJumpTicks(player, jumpAssist);
                double jumpCompensationRatio = ModuleManager.computeModularProperty(stack, JumpAssistModule.JUMP_FOOD_COMPENSATION);
                if (player.isSprinting()) {
                    player.getFoodStats().addExhaustion((float) (-0.8 * jumpCompensationRatio));
                } else {
                    player.getFoodStats().addExhaustion((float) (-0.2 * jumpCompensationRatio));
                }
            }
        }
    }
}

public void onPlayerTickActive(EntityPlayer player, ItemStack item) {
    Vec3d playerHorzFacing = player.getLookVec();
    playerHorzFacing = new Vec3d(playerHorzFacing.xCoord, 0, playerHorzFacing.zCoord);
    playerHorzFacing.normalize();
    PlayerInputMap movementInput = PlayerInputMap.getInputMapFor(player.getCommandSenderEntity().getName());
    boolean sneakkey = movementInput.sneakKey;
    float forwardkey = movementInput.forwardKey;
    ItemStack torso = player.getItemStackFromSlot(EntityEquipmentSlot.CHEST);
    boolean hasParachute = false;
    NuminaPlayerUtils.resetFloatKickTicks(player);
    if (torso != null && torso.getItem() instanceof IModularItem) {
        hasParachute = ModuleManager.itemHasActiveModule(torso, ParachuteModule.MODULE_PARACHUTE);
    }
    if (sneakkey && player.motionY < 0 && (!hasParachute || forwardkey > 0)) {
        if (player.motionY < -0.1) {
            float vol = (float)( player.motionX*player.motionX + player.motionZ * player.motionZ);
            double motionYchange = Math.min(0.08, -0.1 - player.motionY);
            player.motionY += motionYchange;
            player.motionX += playerHorzFacing.xCoord * motionYchange;
            player.motionZ += playerHorzFacing.zCoord * motionYchange;

            // sprinting speed
            player.jumpMovementFactor += 0.03f;
        }
    }
}

public void setMovementModifier(ItemStack item, double multiplier) {
    NBTTagList modifiers = item.getTagCompound().getTagList("AttributeModifiers", (byte) 10); // Type 10 for tag compound
    NBTTagCompound sprintModifiers = new NBTTagCompound();
    item.getTagCompound().setTag("AttributeModifiers", modifiers);
    for (int i = 0; i < modifiers.tagCount(); i++) {
        NBTTagCompound tag = modifiers.getCompoundTagAt(i);
        if (Objects.equals(new AttributeModifier(tag).name, "Sprint Assist")) {
            sprintModifiers = tag;
            sprintModifiers.setInteger("Operation", 1);
            sprintModifiers.setDouble("Amount", multiplier - 1);
            sprintModifiers.setString("Slot", EntityEquipmentSlot.LEGS.getName());
        }
    }

    //TODO: fix this so knockback does not have to be readded
    // this should be when first created
    if (sprintModifiers.hasNoTags()) {
        modifiers.appendTag(new AttributeModifier(1, TAGUUID, multiplier - 1, "generic.movementSpeed", "Sprint Assist", EntityEquipmentSlot.LEGS).toNBT());

        // add knockback resistance back because it doesn't show in tooltip after AttributeModifiers tag is added
        modifiers.appendTag(new AttributeModifier(0, TAGUUID, 0.25,
                SharedMonsterAttributes.KNOCKBACK_RESISTANCE.getAttributeUnlocalizedName(),
                SharedMonsterAttributes.KNOCKBACK_RESISTANCE.getAttributeUnlocalizedName(), EntityEquipmentSlot.LEGS).toNBT());

    }
}

