private void loadTweaks(ItemStack stack, IPowerModule module) {
    NBTTagCompound itemTag = MuseItemUtils.getMuseItemTag(stack);
    NBTTagCompound moduleTag = itemTag.getCompoundTag(module.getDataName());

    propertyStrings = new HashMap();
    Set<String> tweaks = new HashSet<String>();

    Map<String, List<IPropertyModifier>> propertyModifiers = module.getPropertyModifiers();
    for (Map.Entry<String, List<IPropertyModifier>> property : propertyModifiers.entrySet()) {
        double currValue = 0;
        for (IPropertyModifier modifier : property.getValue()) {
            currValue = modifier.applyModifier(moduleTag, currValue);
            if (modifier instanceof PropertyModifierLinearAdditive) {
                tweaks.add(((PropertyModifierLinearAdditive) modifier).getTradeoffName());
            }
        }
        propertyStrings.put(property.getKey(), currValue);
    }

    sliders = new LinkedList();
    int y = 0;
    for (String tweak : tweaks) {
        y += 20;
        MusePoint2D center = new MusePoint2D((border.left() + border.right()) / 2, border.top() + y);
        ClickableTinkerSlider slider = new ClickableTinkerSlider(
                center,
                border.right() - border.left() - 8,
                moduleTag, tweak);
        sliders.add(slider);
        if (selectedSlider != null && slider.hitBox(center.x(), center.y())) {
            selectedSlider = slider;
        }
    }
}

    public void onPlayerTickActive(EntityPlayer player, ItemStack item) {
        if (item == player.getItemStackFromSlot(EntityEquipmentSlot.LEGS)) { // now you actually have to wear these to get the speed boost
//            double motionX = player.posX - player.lastTickPosX;
//            double motionY = player.posY - player.lastTickPosY;
//            double motionZ = player.posZ - player.lastTickPosZ;
//            double horzMovement = Math.sqrt(motionX * motionX + motionZ * motionZ);

            double horzMovement = player.distanceWalkedModified - player.prevDistanceWalkedModified;
            double totalEnergy = ElectricItemUtils.getPlayerEnergy(player);
            if (horzMovement > 0) { // stop doing drain calculations when player hasn't moved
                if (player.isSprinting()) {
                    double exhaustion = Math.round(horzMovement * 100.0F) * 0.01;
                    double sprintCost = ModuleManager.computeModularProperty(item, SPRINT_ENERGY_CONSUMPTION);
                    if (sprintCost < totalEnergy) {
                        double sprintMultiplier = ModuleManager.computeModularProperty(item, SPRINT_SPEED_MULTIPLIER);
                        double exhaustionComp = ModuleManager.computeModularProperty(item, SPRINT_FOOD_COMPENSATION);
                        ElectricItemUtils.drainPlayerEnergy(player, sprintCost * horzMovement * 5);
                        setMovementModifier(item, sprintMultiplier * 1.2);
                        player.getFoodStats().addExhaustion((float) (-0.01 * exhaustion * exhaustionComp));
                        player.jumpMovementFactor = player.getAIMoveSpeed() * .2f;
                    }
                } else {
                    double cost = ModuleManager.computeModularProperty(item, WALKING_ENERGY_CONSUMPTION);
                    if (cost < totalEnergy) {
                        double walkMultiplier = ModuleManager.computeModularProperty(item, WALKING_SPEED_MULTIPLIER);
                        ElectricItemUtils.drainPlayerEnergy(player, cost * horzMovement * 5);
                        setMovementModifier(item, walkMultiplier);
                        player.jumpMovementFactor = player.getAIMoveSpeed() * .2f;
                    }
                }
            }
        } else
            onPlayerTickInactive(player, item);
    }

public ActionResult onItemRightClick(ItemStack itemStackIn, World worldIn, EntityPlayer playerIn, EnumHand hand) {
    if (hand == EnumHand.MAIN_HAND) {
        double range = 64;
        double timer = MuseItemUtils.getDoubleOrZero(itemStackIn, TIMER);
        double energyConsumption = ModuleManager.computeModularProperty(itemStackIn, ENERGY);
        if (ElectricItemUtils.getPlayerEnergy(playerIn) > energyConsumption && timer == 0) {
            ElectricItemUtils.drainPlayerEnergy(playerIn, energyConsumption);
            MuseItemUtils.setDoubleOrRemove(itemStackIn, TIMER, 10);
            MuseHeatUtils.heatPlayer(playerIn, ModuleManager.computeModularProperty(itemStackIn, HEAT));
            RayTraceResult hitMOP = MusePlayerUtils.doCustomRayTrace(playerIn.worldObj, playerIn, true, range);
            // TODO: actual railgun sound
            worldIn.playSound(playerIn, playerIn.getPosition(), SoundEvents.ENTITY_ARROW_SHOOT, SoundCategory.PLAYERS, 0.5F, 0.4F / ((float) Math.random() * 0.4F + 0.8F));
            double damage = ModuleManager.computeModularProperty(itemStackIn, IMPULSE) / 100.0;
            double knockback = damage / 20.0;
            Vec3d lookVec = playerIn.getLookVec();
            if (hitMOP != null) {
                switch (hitMOP.typeOfHit) {
                    case ENTITY:
                        drawParticleStreamTo(playerIn, worldIn, hitMOP.hitVec.xCoord, hitMOP.hitVec.yCoord, hitMOP.hitVec.zCoord);
                        DamageSource damageSource = DamageSource.causePlayerDamage(playerIn);
                        if (hitMOP.entityHit.attackEntityFrom(damageSource, (int) damage)) {
                            hitMOP.entityHit.addVelocity(lookVec.xCoord * knockback, Math.abs(lookVec.yCoord + 0.2f) * knockback, lookVec.zCoord
                                    * knockback);
                        }
                        break;
                    case BLOCK:
                        drawParticleStreamTo(playerIn, worldIn, hitMOP.hitVec.xCoord, hitMOP.hitVec.yCoord, hitMOP.hitVec.zCoord);
                        break;
                    default:
                        break;
                }
                playerIn.addVelocity(-lookVec.xCoord * knockback, Math.abs(-lookVec.yCoord + 0.2f) * knockback, -lookVec.zCoord * knockback);

                worldIn.playSound(playerIn, playerIn.getPosition(), SoundEvents.ENTITY_ARROW_SHOOT, SoundCategory.PLAYERS, 0.5F, 0.4F / ((float) Math.random() * 0.4F + 0.8F));
            }
            playerIn.setActiveHand(hand);
            return new ActionResult(EnumActionResult.SUCCESS, itemStackIn);
        }
    }
    return new ActionResult(EnumActionResult.PASS, itemStackIn);
}

public static EnumActionResult onItemUseFirst(ItemStack stack, EntityPlayer player, World world, BlockPos pos, EnumFacing side, float hitX, float hitY, float hitZ, EnumHand hand) {
    if(stack.getItemDamage() > 0) {
        stack.setItemDamage(0);
    }

    IBlockState state = world.getBlockState(pos);
    Block block = state.getBlock();
    TileEntity tile = world.getTileEntity(pos);
    if(world.isAirBlock(pos))
        return EnumActionResult.PASS;

    PlayerInteractEvent.RightClickBlock event = new PlayerInteractEvent.RightClickBlock(player, hand, stack, pos, side, new Vec3d((double)hitX, (double)hitY, (double)hitZ));
    if(MinecraftForge.EVENT_BUS.post(event) || event.getResult() == Event.Result.DENY || event.getUseItem() == Event.Result.DENY || event.getUseBlock() == Event.Result.DENY)
        return EnumActionResult.PASS;

    if (ModCompatibility.isRFAPILoaded() && ServerHelper.isServerWorld(world) && player.isSneaking() &&
            block instanceof IDismantleable && ((IDismantleable)block).canDismantle(world, pos, state, player)) {
        ((IDismantleable)block).dismantleBlock(world, pos, state, player, false);

        if (!player.capabilities.isCreativeMode) {
            useEnergy(stack, false);
        }
        return EnumActionResult.SUCCESS;
    } else if(ModCompatibility.isIndustrialCraftLoaded() && block instanceof IWrenchable && block.hasTileEntity(state)) {
        int hitSide = side.ordinal();
        IWrenchable wrenchable = (IWrenchable)block;
        if(player.isSneaking()) {
            hitSide = BlockHelper.SIDE_OPPOSITE[hitSide];
        }

        if(wrenchable.setFacing(world, pos, EnumFacing.VALUES[hitSide], player)) {
            return ServerHelper.isServerWorld(world)?EnumActionResult.SUCCESS:EnumActionResult.PASS;
        } else if(wrenchable.wrenchCanRemove(world, pos, player)) {
            int fortune = EnchantmentHelper.getEnchantmentLevel(Enchantments.FORTUNE, stack);
            List<ItemStack> drops = wrenchable.getWrenchDrops(world, pos, state, tile, player, fortune);
            if(!drops.isEmpty()) {
                world.setBlockToAir(pos);
                if(ServerHelper.isServerWorld(world)) {
                    Iterator iterator = drops.iterator();

                    while(iterator.hasNext()) {
                        ItemStack drop = (ItemStack)iterator.next();
                        float f = 0.7F;
                        double x2 = (double)(world.rand.nextFloat() * f) + (double)(1.0F - f) * 0.5D;
                        double y2 = (double)(world.rand.nextFloat() * f) + (double)(1.0F - f) * 0.5D;
                        double z2 = (double)(world.rand.nextFloat() * f) + (double)(1.0F - f) * 0.5D;
                        EntityItem entity = new EntityItem(world, (double)pos.getX() + x2, (double)pos.getY() + y2, (double)pos.getZ() + z2, drop);
                        entity.setPickupDelay(10);
                        world.spawnEntityInWorld(entity);
                    }
                }
                return ServerHelper.isServerWorld(world)?EnumActionResult.SUCCESS:EnumActionResult.PASS;
            }
            return EnumActionResult.PASS;
        }
    } else if(BlockHelper.canRotate(block)) {
        world.setBlockState(pos, BlockHelper.rotateVanillaBlock(world, state, pos), 3);
        if(!player.capabilities.isCreativeMode) {
            useEnergy(stack, false);
        }
        player.swingArm(hand);
        return ServerHelper.isServerWorld(world)?EnumActionResult.SUCCESS:EnumActionResult.PASS;
    } else if(!player.isSneaking() && block.rotateBlock(world, pos, side)) {
        if(!player.capabilities.isCreativeMode) {
            useEnergy(stack, false);
        }

        player.swingArm(hand);
        return ServerHelper.isServerWorld(world)?EnumActionResult.SUCCESS:EnumActionResult.PASS;
    } else {
        return EnumActionResult.PASS;
    }
    return EnumActionResult.PASS;
}

public void renderBatch(ParticleVisualBatchKey key, List<ParticleVisualSubmission> submissions, DeltaTracker partialTicks, Matrix4f viewMat, Matrix4f projMat) {
    RenderType renderType = key.renderType();
    VertexBuffer meshBuffer = key.vertexBuffer();
    InstanceFormat instanceFormat = key.instanceFormat();

    if (meshBuffer == null || instanceFormat == null) return;

    int totalInstances = 0;
    for (ParticleVisualSubmission submission : submissions) {
        MeshVisualDrawData data = (MeshVisualDrawData) submission.drawData();
        totalInstances += data.liveCount();
    }

    if (totalInstances == 0) return;

    Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
    float pt = partialTicks.getGameTimeDeltaPartialTick(false);
    int strideFloats = instanceFormat.totalFloats();

    FloatBuffer instanceData = MemoryUtil.memAllocFloat(totalInstances * strideFloats);

    try {
        int currentInstanceOffset = 0;

        for (ParticleVisualSubmission submission : submissions) {
            MeshVisualDrawData data = (MeshVisualDrawData) submission.drawData();
            int targetId = data.targetVisualId();
            int liveCount = data.liveCount();

            synchronized (data.particles()) {
                int elementOffset = 0;
                int particlesWritten = 0;

                for (InstanceElement element : instanceFormat.elements()) {
                    particlesWritten = element.writer().write(
                            data.particles(), liveCount, targetId, pt, camera,
                            instanceData, currentInstanceOffset, elementOffset, strideFloats
                    );
                    elementOffset += element.floatCount();
                }

                currentInstanceOffset += particlesWritten;
            }
        }

        instanceData.position(0);
        instanceData.limit(totalInstances * strideFloats);

        if (instanceVbo == -1) instanceVbo = glGenBuffers();

        glBindBuffer(GL_ARRAY_BUFFER, instanceVbo);
        glBufferData(GL_ARRAY_BUFFER, instanceData, GL_DYNAMIC_DRAW);

        renderType.setupRenderState();
        meshBuffer.bind();
        ShaderInstance shader = RenderSystem.getShader();

        int baseAttributes = meshBuffer.getFormat().getElements().size();
        int currentAttribute = baseAttributes;
        int offset = 0;

        for (InstanceElement element : instanceFormat.elements()) {
            glEnableVertexAttribArray(currentAttribute);
            glVertexAttribPointer(currentAttribute, element.floatCount(), GL_FLOAT, false, instanceFormat.strideBytes(), offset);
            glVertexAttribDivisor(currentAttribute, 1);

            offset += element.floatCount() * Float.BYTES;
            currentAttribute++;
        }

        IVertexBuffer.cast(meshBuffer).drawWithShaderInstanced(viewMat, projMat, shader, totalInstances);

        for (int i = baseAttributes; i < currentAttribute; i++) {
            glVertexAttribDivisor(i, 0);
            glDisableVertexAttribArray(i);
        }

        glBindBuffer(GL_ARRAY_BUFFER, 0);
        VertexBuffer.unbind();
        renderType.clearRenderState();

    } finally {
        MemoryUtil.memFree(instanceData);
    }
}

