public static double thrust(EntityPlayer player, double thrust, boolean flightControl) {
    PlayerInputMap movementInput = PlayerInputMap.getInputMapFor(player.getCommandSenderEntity().getName());
    boolean jumpkey = movementInput.jumpKey;
    float forwardkey = movementInput.forwardKey;
    float strafekey = movementInput.strafeKey;
    boolean downkey = movementInput.downKey;
    boolean sneakkey = movementInput.sneakKey;
    double thrustUsed = 0;
    if (flightControl) {
        Vec3d desiredDirection = player.getLookVec().normalize();
        double strafeX = desiredDirection.zCoord;
        double strafeZ = -desiredDirection.xCoord;
        double scaleStrafe = (strafeX * strafeX + strafeZ * strafeZ);
        double flightVerticality = 0;
        ItemStack helm = player.getItemStackFromSlot(EntityEquipmentSlot.HEAD);;
        if (helm != null && helm.getItem() instanceof IModularItem) {
            flightVerticality = ModuleManager.computeModularProperty(helm, FlightControlModule.FLIGHT_VERTICALITY);
        }

        desiredDirection = new Vec3d(
                (desiredDirection.xCoord * Math.signum(forwardkey) + strafeX * Math.signum(strafekey)),
                (flightVerticality * desiredDirection.yCoord * Math.signum(forwardkey) + (jumpkey ? 1 : 0) - (downkey ? 1 : 0)),
                (desiredDirection.zCoord * Math.signum(forwardkey) + strafeZ * Math.signum(strafekey)));

        desiredDirection = desiredDirection.normalize();
        // Gave up on this... I suck at math apparently
        // double ux = player.motionX / thrust;
        // double uy = player.motionY / thrust;
        // double uz = player.motionZ / thrust;
        // double vx = desiredDirection.xCoord;
        // double vy = desiredDirection.yCoord;
        // double vz = desiredDirection.zCoord;
        // double b = (2 * ux * vx + 2 * uy * vy + 2 * uz * vz);
        // double c = (ux * ux + uy * uy + uz * uz - 1);
        //
        // double actualThrust = (-b + Math.sqrt(b * b - 4 * c))
        // / (2);
        //
        // player.motionX = desiredDirection.xCoord *
        // actualThrust;
        // player.motionY = desiredDirection.yCoord *
        // actualThrust;
        // player.motionZ = desiredDirection.zCoord *
        // actualThrust;

        // Brakes
        if (player.motionY < 0 && desiredDirection.yCoord >= 0) {
            if (-player.motionY > thrust) {
                player.motionY += thrust;
                thrustUsed += thrust;
                thrust = 0;
            } else {
                thrust -= player.motionY;
                thrustUsed += player.motionY;
                player.motionY = 0;
            }
        }
        if (player.motionY < -1) {
            thrust += 1 + player.motionY;
            thrustUsed -= 1 + player.motionY;
            player.motionY = -1;
        }
        if (Math.abs(player.motionX) > 0 && desiredDirection.lengthVector() == 0) {
            if (Math.abs(player.motionX) > thrust) {
                player.motionX -= Math.signum(player.motionX) * thrust;
                thrustUsed += thrust;
                thrust = 0;
            } else {
                thrust -= Math.abs(player.motionX);
                thrustUsed += Math.abs(player.motionX);
                player.motionX = 0;
            }
        }
        if (Math.abs(player.motionZ) > 0 && desiredDirection.lengthVector() == 0) {
            if (Math.abs(player.motionZ) > thrust) {
                player.motionZ -= Math.signum(player.motionZ) * thrust;
                thrustUsed += thrust;
                thrust = 0;
            } else {
                thrustUsed += Math.abs(player.motionZ);
                thrust -= Math.abs(player.motionZ);
                player.motionZ = 0;
            }
        }

        // Thrusting, finally :V
        double vx = thrust * desiredDirection.xCoord;
        double vy = thrust * desiredDirection.yCoord;
        double vz = thrust * desiredDirection.zCoord;
        player.motionX += vx;
        player.motionY += vy;
        player.motionZ += vz;
        thrustUsed += thrust;

    } else {
        Vec3d playerHorzFacing = player.getLookVec();
        playerHorzFacing = new Vec3d(playerHorzFacing.xCoord, 0,  playerHorzFacing.zCoord);
        playerHorzFacing.normalize();
        if (forwardkey == 0) {
            player.motionY += thrust;
        } else {
            player.motionY += thrust / root2;
            player.motionX += playerHorzFacing.xCoord * thrust / root2 * Math.signum(forwardkey);
            player.motionZ += playerHorzFacing.zCoord * thrust / root2 * Math.signum(forwardkey);
        }
        thrustUsed += thrust;
    }

    // Slow the player if they are going too fast
    double horzm2 = player.motionX * player.motionX + player.motionZ * player.motionZ;
    double horzmlim = Config.getMaximumFlyingSpeedmps() * Config.getMaximumFlyingSpeedmps() / 400;
    if (sneakkey && horzmlim > 0.05) {
        horzmlim = 0.05;
    }

    if (horzm2 > horzmlim) {
        double ratio = Math.sqrt(horzmlim / horzm2);
        player.motionX *= ratio;
        player.motionZ *= ratio;
    }
    NuminaPlayerUtils.resetFloatKickTicks(player);
    return thrustUsed;
}

public void renderBatch(ParticleVisualBatchKey key, List<ParticleVisualSubmission> submissions, DeltaTracker partialTicks, Matrix4f viewMat, Matrix4f projMat) {
    RenderType renderType = key.renderType();
    renderType.setupRenderState();

    Tesselator tesselator = Tesselator.getInstance();
    BufferBuilder builder = tesselator.begin(VertexFormat.Mode.TRIANGLE_STRIP, DefaultVertexFormat.POSITION_TEX_COLOR);

    boolean hasData = false;
    boolean isFirstTrail = true;

    float lastX = 0;
    float lastY = 0;
    float lastZ = 0;

    int lastR = 255;
    int lastG = 255;
    int lastB = 255;
    int lastA = 0;

    float lastU = 0;
    float lastV = 0;

    Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
    double camX = camera.getPosition().x;
    double camY = camera.getPosition().y;
    double camZ = camera.getPosition().z;
    Vector3f look = camera.getLookVector();

    float pt = partialTicks.getGameTimeDeltaPartialTick(false);

    for (ParticleVisualSubmission submission : submissions) {
        TrailVisualDrawData data = (TrailVisualDrawData) submission.drawData();
        TrailVisualStorage storage = data.storage();
        int liveCount = data.liveCount();
        float halfWidth = data.width() * 0.5f;

        int[] visualIds = data.particles().visualIds();
        int targetId = data.targetVisualId();

        float[] rArr = data.particles().r();
        float[] gArr = data.particles().g();
        float[] bArr = data.particles().b();
        float[] aArr = data.particles().a();

        double[] vxArr = data.particles().vx();
        double[] vyArr = data.particles().vy();
        double[] vzArr = data.particles().vz();

        synchronized (data.particles()) {
            for (int i = 0; i < liveCount; i++) {
                if (visualIds[i] != targetId) continue;

                int points = storage.historyCount()[i];
                if (points < 2) continue;

                int spineCount = points + 1;

                if (spineCount > SPINE_X.length) {
                    int newSize = spineCount * 2;
                    SPINE_X = new float[newSize];
                    SPINE_Y = new float[newSize];
                    SPINE_Z = new float[newSize];
                    PERP_X = new float[newSize];
                    PERP_Y = new float[newSize];
                    PERP_Z = new float[newSize];
                }

                double[] xHist = storage.xHistory();
                double[] yHist = storage.yHistory();
                double[] zHist = storage.zHistory();
                int baseIdx = i * storage.maxPoints();

                for (int j = 0; j < spineCount; j++) {
                    if (j < points - 1) {
                        SPINE_X[j] = (float) (lerp(xHist[baseIdx + j], xHist[baseIdx + j + 1], pt) - camX);
                        SPINE_Y[j] = (float) (lerp(yHist[baseIdx + j], yHist[baseIdx + j + 1], pt) - camY);
                        SPINE_Z[j] = (float) (lerp(zHist[baseIdx + j], zHist[baseIdx + j + 1], pt) - camZ);
                    } else {
                        double lastHx = xHist[baseIdx + points - 1];
                        double lastHy = yHist[baseIdx + points - 1];
                        double lastHz = zHist[baseIdx + points - 1];
                        double curX = lastHx + vxArr[i];
                        double curY = lastHy + vyArr[i];
                        double curZ = lastHz + vzArr[i];

                        SPINE_X[j] = (float) (lerp(lastHx, curX, pt) - camX);
                        SPINE_Y[j] = (float) (lerp(lastHy, curY, pt) - camY);
                        SPINE_Z[j] = (float) (lerp(lastHz, curZ, pt) - camZ);
                    }
                }

                for (int j = 0; j < spineCount; j++) {
                    float dx, dy, dz;

                    if (j == 0) {
                        dx = SPINE_X[1] - SPINE_X[0];
                        dy = SPINE_Y[1] - SPINE_Y[0];
                        dz = SPINE_Z[1] - SPINE_Z[0];
                    } else if (j == spineCount - 1) {
                        dx = SPINE_X[j] - SPINE_X[j - 1];
                        dy = SPINE_Y[j] - SPINE_Y[j - 1];
                        dz = SPINE_Z[j] - SPINE_Z[j - 1];
                    } else {
                        dx = SPINE_X[j + 1] - SPINE_X[j - 1];
                        dy = SPINE_Y[j + 1] - SPINE_Y[j - 1];
                        dz = SPINE_Z[j + 1] - SPINE_Z[j - 1];
                    }

                    float px = look.y() * dz - look.z() * dy;
                    float py = look.z() * dx - look.x() * dz;
                    float pz = look.x() * dy - look.y() * dx;

                    float len = (float) Math.sqrt(px * px + py * py + pz * pz);
                    if (len > 0) {
                        PERP_X[j] = (px / len) * halfWidth;
                        PERP_Y[j] = (py / len) * halfWidth;
                        PERP_Z[j] = (pz / len) * halfWidth;
                    } else {
                        PERP_X[j] = PERP_Y[j] = PERP_Z[j] = 0;
                    }
                }

                int r = (int) (rArr[i] * 255.0F);
                int g = (int) (gArr[i] * 255.0F);
                int b = (int) (bArr[i] * 255.0F);
                float baseAlpha = aArr[i];

                if (!isFirstTrail) {
                    builder.addVertex(lastX, lastY, lastZ).setUv(lastU, lastV).setColor(lastR, lastG, lastB, 0);
                    builder.addVertex(SPINE_X[0] - PERP_X[0], SPINE_Y[0] - PERP_Y[0], SPINE_Z[0] - PERP_Z[0]).setUv(0, 0).setColor(r, g, b, 0);
                }
                isFirstTrail = false;
                hasData = true;

                for (int j = 0; j < spineCount; j++) {
                    float u = (float) j / (spineCount - 1);
                    int alpha = (int) (u * baseAlpha * 255.0F);

                    builder.addVertex(SPINE_X[j] - PERP_X[j], SPINE_Y[j] - PERP_Y[j], SPINE_Z[j] - PERP_Z[j])
                            .setUv(u, 0)
                            .setColor(r, g, b, alpha);

                    lastX = SPINE_X[j] + PERP_X[j];
                    lastY = SPINE_Y[j] + PERP_Y[j];
                    lastZ = SPINE_Z[j] + PERP_Z[j];
                    lastU = u;
                    lastV = 1;
                    lastR = r;
                    lastG = g;
                    lastB = b;
                    lastA = alpha;
                    builder.addVertex(lastX, lastY, lastZ).setUv(u, 1).setColor(r, g, b, alpha);
                }
            }
        }
    }

    if (hasData) {
        BufferUploader.drawWithShader(builder.buildOrThrow());
    }
    renderType.clearRenderState();
}

