public boolean canUse() {
    target = this.mob.getTarget();
    if (target == null || spellCastingMob.isCasting())
        return false;

    if (attackTime <= -interval * (projectileCount - 1)) {
        //IronsSpellbooks.LOGGER.debug("SpellBarrageGoal.canUse resetAttackTimer");
        resetAttackTimer();
    }
    attackTime--;
    //IronsSpellbooks.LOGGER.debug("SpellBarrageGoal.canUse: spell:{}, attackTime:{}, interval:{}, a%i:{}, result:{}", spell, attackTime, interval, attackTime % interval, attackTime <= 0 && attackTime % interval == 0);
    return attackTime <= 0 && attackTime % interval == 0;
}

public void tick() {
    var target = mob.getTarget();
    if (target != null) {
        mob.getLookControl().setLookAt(target);
    }
    if (abilityTimer == getActionTimestamp()) {
        doAction();
    }
    if (abilityTimer >= getActionDuration()) {
        stop();
    }
    abilityTimer++;
}

protected void doAction() {
    mob.setTaunting(true);
    mob.playSound(SoundRegistry.ECHOING_STRIKE.get(), 2, 1);
    MagicManager.spawnParticles(mob.level, new BlastwaveParticleOptions(SpellRegistry.ECHOING_STRIKES_SPELL.get().getSchoolType().getTargetingColor(), 3), mob.getX(), mob.getY(), mob.getZ(), 1, 0, 0, 0, 0, true);
    if (targets != null) {
        targets.forEach(entity -> {
            if (entity instanceof Mob tauntmob) {
                MagicManager.spawnParticles(mob.level, ParticleTypes.ANGRY_VILLAGER, tauntmob.getX(), tauntmob.getEyeY() + (tauntmob.getBoundingBox().maxY - tauntmob.getEyeY()) * 2, tauntmob.getZ(), 5, 0.3, 0.3, 0.3, 0, false);
                tauntmob.setTarget(this.mob);
            }
        });
    }
}

