public void onAttackEntity(AttackEntityEvent event) {
  if (!isEnabled()) { return; }
  if (!(event.getTarget() instanceof LivingEntity target)) { return; }
  Player attacker = event.getEntity();
  ItemStack main = attacker.getMainHandItem();
  ItemStack off = attacker.getOffhandItem();
  var h = EnchantUtil.holder(EnchantRegistry.VENOM, attacker);
  int mainLevel = EnchantUtil.getCurrentLevelTool(h, main);
  int offLevel = EnchantUtil.getCurrentLevelTool(h, off);
  int level = Math.max(mainLevel, offLevel);
  if (level > 0) {
    EntityUtil.addOrMergePotionEffect(target, new MobEffectInstance(MobEffects.POISON, TICKSPERLEVEL * level, level - 1));
  }
}

public ItemStack onActionConsumeTool(Level world, BlockPos pos, BlockState blockState, ItemStack targetStack, Player player,
        ToolAction requiredTool, int requiredLevel, boolean consumeResources) {
    BlockPos basePos = pos.above();
    BlockState baseState = world.getBlockState(basePos);
    ItemStack upgradedStack = CastOptional.cast(baseState.getBlock(), HammerBaseBlock.class)
            .map(base -> base.applyActionEffects(world, basePos, baseState, targetStack, player, requiredTool, requiredLevel, consumeResources))
            .orElse(targetStack);

    if (consumeResources) {
        TileEntityOptional.from(world, pos, HammerHeadBlockEntity.class).ifPresent(HammerHeadBlockEntity::activate);
        world.playSound(player, pos, SoundEvents.ANVIL_LAND, SoundSource.BLOCKS, 0.2f, (float) (0.5 + Math.random() * 0.2));
    }
    return upgradedStack;
}

