public void applyInstantenousEffect(@Nullable Entity pSource, @Nullable Entity pIndirectSource, LivingEntity livingEntity, int pAmplifier, double pHealth) {
    //IronsSpellbooks.LOGGER.debug("Instant mana applying effect");
    int i = pAmplifier + 1;
    int maxMana = (int) livingEntity.getAttributeValue(AttributeRegistry.MAX_MANA);
    int manaAdd = (int) (i * manaPerAmplifier + (maxMana * (i * manaPerAmplifierPercent)));
    MagicData pmg = MagicData.getPlayerMagicData(livingEntity);
    //IronsSpellbooks.LOGGER.debug("old mana: {}", pmg.getMana());
    pmg.setMana(pmg.getMana() + manaAdd);
    if (livingEntity instanceof ServerPlayer serverPlayer) {
        PacketDistributor.sendToPlayer(serverPlayer, new SyncManaPacket(pmg));
    }
    //IronsSpellbooks.LOGGER.debug("new mana: {}", pmg.getMana());

}

protected void doAction() {
    // perform leap
    Vec3 leapVector = new Vec3(0, .5, 1.5);
    var target = mob.getTarget();
    if (target == null) {
        return;
    }
    Vec3 power = Utils.lerp(Math.clamp(mob.distanceTo(target) / 18f, 0, 1), new Vec3(0.125, 0.25, 0.125), new Vec3(3, 1.2, 3));
    Vec3 lunge = leapVector.multiply(power.x, power.y, power.z).yRot(-Utils.getAngle(mob.getX(), mob.getZ(), target.getX(), target.getZ()) - Mth.HALF_PI);
    mob.push(lunge);
    mob.getAttribute(Attributes.MOVEMENT_SPEED).removeModifier(TELEGRAPH_SPEED_MODIFIER);
    mob.playSound(SoundRegistry.ICE_SPIDER_SWING.get(), 3, Utils.random.nextIntBetweenInclusive(13, 16) * .1f);
    mob.playSound(SoundRegistry.ICE_SPIDER_AMBIENT.get(), 3, Utils.random.nextIntBetweenInclusive(14, 20) * .1f);
}

