public ItemStack onCraftConsumeTool(Level world, BlockPos pos, BlockState blockState, ItemStack targetStack, String slot, boolean isReplacing, Player player,
        ToolAction requiredTool, int requiredLevel, boolean consumeResources) {
    BlockPos basePos = pos.above();
    BlockState baseState = world.getBlockState(basePos);
    ItemStack upgradedStack = CastOptional.cast(baseState.getBlock(), HammerBaseBlock.class)
            .map(base -> base.applyCraftEffects(world, basePos, baseState, targetStack, slot, isReplacing, player, requiredTool, requiredLevel, consumeResources))
            .orElse(targetStack);

    if (consumeResources) {
        TileEntityOptional.from(world, pos, HammerHeadBlockEntity.class).ifPresent(HammerHeadBlockEntity::activate);
        world.playSound(player, pos, SoundEvents.ANVIL_LAND, SoundSource.PLAYERS, 0.2f, (float) (0.5 + Math.random() * 0.2));
    }

    return upgradedStack;
}

public static void applyEnchantmentHitEffects(ItemStack itemStack, LivingEntity target, LivingEntity attacker) {
    EnchantmentHelper.getEnchantments(itemStack).forEach((enchantment, level) -> enchantment.doPostAttack(attacker, target, level));

    if (attacker != null) {
        for (ItemStack equipment : attacker.getAllSlots()) {
            EnchantmentHelper.getEnchantments(equipment).forEach((enchantment, level) -> enchantment.doPostAttack(attacker, target, level));
        }
    }

    // fire aspect has to be applied separately :o
    int fireAspectLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FIRE_ASPECT, itemStack);
    if (fireAspectLevel > 0) {
        target.setSecondsOnFire(fireAspectLevel * 4);
    }
}

