public void addCooldown(ServerPlayer serverPlayer, AbstractSpell spell, CastSource castSource) {
    int effectiveCooldown = getEffectiveSpellCooldown(spell, serverPlayer, castSource);
    var pre = NeoForge.EVENT_BUS.post(new SpellCooldownAddedEvent.Pre(effectiveCooldown, spell, serverPlayer, castSource));

    if (castSource == CastSource.SCROLL || pre.isCanceled()) {
        return;
    }

    effectiveCooldown = pre.getEffectiveCooldown();

    MagicData.getPlayerMagicData(serverPlayer).getPlayerCooldowns().addCooldown(spell, effectiveCooldown);
    PacketDistributor.sendToPlayer(serverPlayer, new SyncCooldownPacket(spell.getSpellId(), effectiveCooldown));

    NeoForge.EVENT_BUS.post(new SpellCooldownAddedEvent.Post(effectiveCooldown, spell, serverPlayer, castSource));
}

public boolean applyEffectTick(LivingEntity livingEntity, int pAmplifier) {
    if (!livingEntity.level.isClientSide) {
        if (livingEntity.horizontalCollision) {
            double d11 = livingEntity.getDeltaMovement().horizontalDistance();
            float f1 = (float) (d11 * 10.0D - 1.0D);
            //IronsSpellbooks.LOGGER.debug("AirborneEffect horizontalCollision: {}, {}", livingEntity.getDeltaMovement().horizontalDistance(),f1);
            if (f1 > 0.0F) {
                livingEntity.playSound(SoundEvents.HOSTILE_BIG_FALL, 2.0F, 1.5F);
                livingEntity.hurt(livingEntity.damageSources().flyIntoWall(), getDamageFromLevel(pAmplifier + 1));
                return false;
            }
        }
    }
    return true;
}

public void increaseAngerLevel(Player angryAt, int levels, boolean showParticles) {
    if (level.isClientSide) {
        return;
    }
    int anger = Math.min(angerLevels.getOrDefault(angryAt.getUUID(), 0) + levels, 10);
    angerLevels.put(angryAt.getUUID(), anger);
    lastAngerLevelUpdate = tickCount;
    if (anger < getAngerThreshold() && showParticles) {
        MagicManager.spawnParticles(level, ParticleTypes.ANGRY_VILLAGER, getX(), getY() + 1.25, getZ(), 15, .3, .2, .3, 0, false);
        getAngerSound().ifPresent((sound) -> playSound(sound, getSoundVolume(), getVoicePitch()));
    }
    if (anger >= getAngerThreshold()) {
        setPersistentAngerTarget(angryAt.getUUID());
    }
}

