    this.mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, this.mob.getLastHurtByMob(), 200L);

    this.targetMob = this.mob.getTarget();
    this.timestamp = this.mob.getLastHurtByMobTimestamp();
