        this.stopHalfHealthAttack();
        this.castComplete();
        this.attackGoal.stop();
        this.serverTriggerAnimation("fire_boss_death");
        this.serverTriggerEvent(STOP_MUSIC);
        this.playSound(SoundRegistry.FIRE_BOSS_DEATH.get(), 5, 1);
