            if (this.duration % Math.max(i, 1) == 0) {
                player.playSound(SoundEvents.WARDEN_HEARTBEAT, 1, 0.85f);
            }
        }
    }
    return true;

}

protected void handleAttackLogic(double distanceSquared) {
    if (--this.attackTime <= 0) {

        if (!mob.isCasting()) {
