public void onRightClickItem(PlayerInteractEvent.RightClickItem event) {
  if (!isEnabled()) { return; }
  Level world = event.getLevel();
  if (world.isClientSide || event.isCanceled()) { return; }
  ItemStack stack = event.getItemStack();
  int level = EnchantUtil.getCurrentLevelTool(EnchantUtil.holder(EnchantRegistry.PEARL, world), stack);
  if (level <= 0) { return; }
  int adjustedCooldown = COOLDOWN / level;
  Player player = event.getEntity();
  if (player.getCooldowns().isOnCooldown(stack.getItem())) { return; }
  ThrownEnderpearl pearl = new ThrownEnderpearl(world, player);
  Vec3 lookVector = player.getLookAngle();
  pearl.shoot(lookVector.x(), lookVector.y(), lookVector.z(), VELOCITY, INNACCURACY);
  EntityUtil.setCooldownItem(player, stack.getItem(), adjustedCooldown);
  SoundUtil.playSound(player, SoundEvents.ENDER_PEARL_THROW, 0.5F, 0.4F / (world.random.nextFloat() * 0.4F + 0.8F));
  world.addFreshEntity(pearl);
  event.setCancellationResult(InteractionResult.SUCCESS);
  event.setCanceled(true);
}

public static void preHitEffects(LivingIncomingDamageEvent event) {
    var damageSource = event.getSource();
    if (damageSource instanceof SpellDamageSource spellDamageSource) {
        if (spellDamageSource.getIFrames() >= 0) {
            event.getContainer().setPostAttackInvulnerabilityTicks(spellDamageSource.getIFrames());
        }
    }
    IMagicSummon fromSummon = damageSource.getDirectEntity() instanceof IMagicSummon summon ? summon : damageSource.getEntity() instanceof IMagicSummon summon ? summon : null;
    if (fromSummon != null) {
        var summoner = fromSummon.getSummoner();
        if (summoner != null && summoner.getUUID().equals(event.getEntity().getUUID())) {
            event.setCanceled(true);
            return;
        }
        if (summoner instanceof LivingEntity livingSummoner) {
            event.setAmount(event.getAmount() * (float) livingSummoner.getAttributeValue(AttributeRegistry.SUMMON_DAMAGE));
        }
    }
}

default void onRemovedHelper(Entity entity, DeferredHolder<MobEffect, SummonTimer> holder) {
    /*
    Decreases player's summon timer amplifier to keep track of how many of their summons remain.
    */
    var reason = entity.getRemovalReason();
    if (reason != null && getSummoner() instanceof ServerPlayer player && reason.shouldDestroy()) {
        var effect = player.getEffect(holder);
        if (effect != null) {
            var decrement = new MobEffectInstance(holder, effect.getDuration(), effect.getAmplifier() - 1, false, false, true);
            if (decrement.getAmplifier() >= 0) {
                player.getActiveEffectsMap().put(holder, decrement);
                player.connection.send(new ClientboundUpdateMobEffectPacket(player.getId(), decrement, false));
            } else {
                player.removeEffect(holder);
            }
        }
    }
    onRemovedHelper(entity);
}

protected void doSpellAction() {
    if (!spellCastingMob.getHasUsedSingleAttack() && singleUseSpell != SpellRegistry.none() && singleUseDelay <= 0) {
        spellCastingMob.setHasUsedSingleAttack(true);
        spellCastingMob.initiateCastSpell(singleUseSpell, singleUseLevel);
        fleeCooldown = 7 + singleUseSpell.getCastTime(singleUseLevel);
    } else {
        var spell = getNextSpellType();
        int spellLevel = (int) (spell.getMaxLevel() * Mth.lerp(mob.getRandom().nextFloat(), minSpellQuality, maxSpellQuality));
        spellLevel = Math.max(spellLevel, 1);

        //Make sure cast is valid. if not, try again shortly
        if (!spell.shouldAIStopCasting(spellLevel, mob, target)) {
            spellCastingMob.initiateCastSpell(spell, spellLevel);
            fleeCooldown = 7 + spell.getCastTime(spellLevel);
        } else {
            spellAttackDelay = 5;
        }
    }
}

