private static boolean createSpider(ServerLevel level, BlockPos.MutableBlockPos pos, LivingEntity targetEntity) {
    BlockState blockstate = level.getBlockState(pos);
    if (!NaturalSpawner.isValidEmptySpawnBlock(level, pos, blockstate, blockstate.getFluidState(), EntityRegistry.ICE_SPIDER.get())) {
        return false;
    } else if (!checkPatrollingMonsterSpawnRules(EntityRegistry.ICE_SPIDER.get(), level, MobSpawnType.PATROL, pos, level.random)) {
        return false;
    }
    IceSpiderEntity iceSpider = new IceSpiderEntity(level);
    iceSpider.moveTo(pos.immutable(), 0, 0);
    iceSpider.setTarget(targetEntity);
    level.playSound(null, iceSpider.blockPosition(), SoundRegistry.ICE_SPIDER_HOWL.get(), SoundSource.HOSTILE, 4, 1f);
    iceSpider.setEmergeFromGround();
    if (!EventHooks.checkSpawnPosition(iceSpider, level, MobSpawnType.PATROL)) {
        return false;
    }
    level.addFreshEntity(iceSpider);
    iceSpider.finalizeSpawn(level, level.getCurrentDifficultyAt(pos), MobSpawnType.PATROL, null);
    return true;
}

private static boolean breakBlock(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, BlockPos pos,
        float refHardness, ToolAction refTool) {
    BlockState offsetState = world.getBlockState(pos);

    float blockHardness = offsetState.getDestroySpeed(world, pos);
    if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
            && blockHardness != -1
            && blockHardness <= refHardness
            && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
        if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
            EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

            item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

            return true;
        }
    }

    return false;
}

public static void postHitEffects(LivingDamageEvent.Post event) {
    var damageSource = event.getSource();
    if (damageSource instanceof SpellDamageSource spellDamageSource && spellDamageSource.hasPostHitEffects()) {
        float actualDamage = event.getNewDamage();
        var target = event.getEntity();
        var attacker = event.getSource().getEntity();
        if (attacker instanceof LivingEntity livingAttacker) {
            if (spellDamageSource.getLifestealPercent() > 0) {
                livingAttacker.heal(spellDamageSource.getLifestealPercent() * actualDamage);
            }
        }
        if (spellDamageSource.getFreezeTicks() > 0 && target.canFreeze()) {
            //Freeze ticks count down by 2, so we * 2 so the spell damages source can be dumb
            target.setTicksFrozen(target.getTicksFrozen() + spellDamageSource.getFreezeTicks() * 2);
        }
        if (spellDamageSource.getFireTime() > 0 && target instanceof LivingEntity) {
            target.igniteForTicks(spellDamageSource.getFireTime());
        }
    }
}

protected void handleAttackLogic(double distanceSquared) {
