public ItemStack applyCraftEffects(Level world, BlockPos pos, BlockState blockState, ItemStack targetStack, String slot, boolean isReplacing,
        Player player, ToolAction requiredTool, int requiredLevel, boolean consumeResources) {
    if (consumeResources) {
        consumeFuel(world, pos);
    }

    if (isReplacing) {
        int preciseLevel = TileEntityOptional.from(world, pos, HammerBaseBlockEntity.class)
                .map(te -> te.getEffectLevel(HammerEffect.precise))
                .orElse(0);

        if (preciseLevel > 0) {
            ItemStack upgradedStack = targetStack.copy();

            ItemModuleMajor.addImprovement(upgradedStack, slot, qualityImprovementKey, preciseLevel);
            return upgradedStack;
        }
    }

    return targetStack;
}

private static void enqueueBlockBreak(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos, float refHardness, ToolAction refTool, int remaining) {
    ServerScheduler.schedule(1, () -> {
        BlockState offsetState = world.getBlockState(pos);

        float blockHardness = offsetState.getDestroySpeed(world, pos);
        if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
                && blockHardness != -1
                && blockHardness <= refHardness
                && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
            if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
                EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

                item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

                if (remaining > 0) {
                    enqueueBlockBreak(world, player, item, itemStack, direction, pos.relative(direction), refHardness, refTool, remaining - 1);
                }
            }
        }
    });
}

public static int perform(ItemStack itemStack, Player player, int xp) {
    int maxXpDrain = EffectHelper.getEffectLevel(itemStack, ItemEffect.satiating);
    if (maxXpDrain > 0 && xp > 0) {
        int xpDrain = Math.min(xp, maxXpDrain);

        MobEffectInstance currentSatiatedInstance = player.getEffect(SatiatedPotionEffect.instance);
        int currentAmplifier = Optional.ofNullable(currentSatiatedInstance)
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1);
        int updatedAmplifier = Math.min(Byte.MAX_VALUE, currentAmplifier + xpDrain);

        int duration = Optional.ofNullable(currentSatiatedInstance)
                .map(MobEffectInstance::getDuration)
                .map(currentDuration -> Math.max(currentDuration + satiatedStackDuration, satiatedInitialDuration))
                .orElse(satiatedInitialDuration);

        player.addEffect(new MobEffectInstance(SatiatedPotionEffect.instance, duration, currentAmplifier + updatedAmplifier, false, false, true));
        return xpDrain;
    }
    return 0;
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
    AbilityUseResult result = directSlam(attacker, hand, item, itemStack, target, hitVec, chargedTicks);

    double overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
    attacker.causeFoodExhaustion(overextendLevel > 0 ? 6 : 1);
    attacker.swing(hand, false);
    attacker.getCooldowns().addCooldown(item, Math.round(getCooldown(item, itemStack) * 1.5f));

    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
    if (revengeLevel > 0) {
        RevengeTracker.removeEnemy(attacker, target);
    }

    item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);
    item.applyDamage(2, itemStack, attacker);

    int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
    if (echoLevel > 0) {
        echoTarget(attacker, hand, item, itemStack, target, hitVec, chargedTicks);
    }
}

protected void doAction() {
    var target = mob.getTarget();
    if (target != null) {
        mob.playSound(SoundRegistry.FIRE_BOSS_FIREBALL.get(), 3f, Utils.random.nextIntBetweenInclusive(80, 110) * .01f);
        mob.playSound(SoundRegistry.SOULCALLER_TOLL_SUCCESS.get(), 3f, .75f);
        MagicManager.spawnParticles(mob.level, new BlastwaveParticleOptions(1, .6f, 0.3f, 8), mob.getX(), mob.getBoundingBox().getCenter().y, mob.getZ(), 0, 0, 0, 0, 0, true);

        Vec3 delta = this.mob.position().subtract(target.position()).normalize();
        Vec3 random = Utils.getRandomVec3(1).normalize().subtract(delta).normalize();
        float intensity = Mth.lerp(mob.getHealth() / mob.getMaxHealth(), 1, 0.75f);
        OminousFireOrbEntity fireOrb = new OminousFireOrbEntity(mob.level);
        fireOrb.setFuse(20 * 25);
        fireOrb.setDamage(160 * intensity);
        fireOrb.setHealth(150);
        fireOrb.setRadius(50 * intensity);
        fireOrb.setOwner(mob);
        fireOrb.setPos(mob.getEyePosition());
        fireOrb.setDeltaMovement(random.scale(0.3).add(0, 1, 0));
        mob.level.addFreshEntity(fireOrb);
    }
}

protected void checkHits() {
    if (level.isClientSide)
        return;
    List<LivingEntity> targets = this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(this.getInflation().x, this.getInflation().y, this.getInflation().z));
    boolean hit = false;
    var radiusSqr = getRadius();
    radiusSqr *= radiusSqr;
    for (LivingEntity target : targets) {
        if (canHitEntity(target) && (!isCircular() || target.distanceToSqr(this) < radiusSqr)) {
            if (canHitTargetForGroundContext(target)) {
                applyEffect(target);
                hit = true;
            }
        }
    }
    if (hit) {
        this.setRadius(getRadius() + radiusOnUse);
        this.duration += durationOnUse;
        onPostHit();
    }
}

