    }

    if (!level().isClientSide) {
        if (tickCount % 20 == 0 && this.random.nextFloat() < .5f && this.getFirstPassenger() instanceof Mob mob) {
            mob.setTarget(this);
        }
        if (tickCount > duration || (target != null && target.isDeadOrDying()) || !isVehicle()) {
            this.removeRoot();
        }
    } else {
        if (tickCount < 20) {
            clientDiggingParticles(this);
        }
    }
}

public void tick() {
  this.syncEnergy();
  if (this.requiresRedstone() && !this.isPowered()) {
    setLitProperty(false);
    return;
  }
  ItemStack stack = inputSlots.getStackInSlot(0);
  if (stack.isEmpty()) {
    timer = TIMERCONF.get();
    setLitProperty(false);
    return;
  }
  if (POWERCONF.get() > 0 && energy.getEnergyStored() < POWERCONF.get()) {
    return;
  }
  setLitProperty(true);
  if (--timer > 0) {
    return;
  }
  timer = TIMERCONF.get();
  tryDoPackage();
}

private AbilityUseResult defensiveExecute(Player attacker, ItemModularHandheld item, ItemStack itemStack, LivingEntity target) {
    boolean targetFullHealth = target.getMaxHealth() == target.getHealth();
    double damageMultiplier = item.getEffectLevel(itemStack, ItemEffect.abilityDefensive) / 100f;

    if (targetFullHealth) {
        damageMultiplier += item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) / 100f;
    }

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.2f, 0.2f);

    if (result != AbilityUseResult.fail) {
        int amp = Optional.ofNullable(target.getEffect(SeveredPotionEffect.instance))
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1);
        amp += targetFullHealth ? 2 : 1;
        amp = Math.min(amp, 2);

        target.addEffect(new MobEffectInstance(SeveredPotionEffect.instance, 1200, amp, false, false));
    }

    return result;
}

public void onCriticalHit(CriticalHitEvent event) {
    Optional.ofNullable(event.getEntity())
            .map(LivingEntity::getMainHandItem)
            .filter(itemStack -> !itemStack.isEmpty())
            .filter(itemStack -> itemStack.getItem() instanceof IModularItem)
            .ifPresent(itemStack -> {
                int backstabLevel = getEffectLevel(itemStack, ItemEffect.backstab);
                if (backstabLevel > 0 && event.getTarget() instanceof LivingEntity) {
                    LivingEntity attacker = event.getEntity();
                    LivingEntity target = (LivingEntity) event.getTarget();
                    if (180 - Math.abs(Math.abs(attacker.yHeadRot - target.yHeadRot) % 360 - 180) < 60) {
                        event.setDamageModifier(Math.max(1.25f + 0.25f * backstabLevel, event.getDamageModifier()));
                        event.setResult(Event.Result.ALLOW);
                    }
                }

                int critLevel = getEffectLevel(itemStack, ItemEffect.criticalStrike);
                if (critLevel > 0) {
                    CritEffect.critEntity(event, itemStack, critLevel);
                }
            });
}

public boolean canUse() {
    // immediately short circuit and create new portal
    if (twinPortal) {
        return true;
    }
    // only use in ominous mode combat
    if (!(mob.isAggressive() && mob.isOminous())) {
        return false;
    }
    // cooldown
    if (--cooldown > 0) {
        return false;
    }
    // limit summon count and delay next check if we cannot use
    int summons = mob.level.getEntities(mob, mob.getBoundingBox().inflate(32), entity -> SummonManager.getOwner(entity) == mob).size();
    if (summons < 12) {
        return true;
    } else {
        cooldown = 20 * 5;
        return false;
    }
}

public void tick() {
    if (customMovementTimer > 0) {
        customMovementTimer--;
        var target = mob.getTarget();
        if (target != null) {
            float f = Math.clamp(customMovementTimer / (float) customMovementDuration, 0, 1f);
            Vec3 movement = currentCustomMovementControl.apply(f).scale(mob.getAttributeValue(Attributes.MOVEMENT_SPEED));
            float angle = -Utils.getAngle(mob.getX(), mob.getZ(), target.getX(), target.getZ()) - Mth.HALF_PI;
            mob.setDeltaMovement(mob.getDeltaMovement().add(movement.yRot(angle).scale(f * f)));
            float slowdownRange = (float) mob.getAttributeValue(Attributes.ENTITY_INTERACTION_RANGE) * mob.getScale() * .9f;
            if (mob.distanceToSqr(target) < slowdownRange * slowdownRange) {
                //rapid deceleration
                customMovementTimer -= 2;
            }
        } else {
            // stop
            customMovementTimer = 0;
        }
    } else {
        super.tick();
    }
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    float range = getRange(spellLevel, entity);
    float strength = getStrength(spellLevel, entity);

    GustCollider gust = new GustCollider(level, entity);
    gust.setPos(entity.position().add(0, entity.getEyeHeight() * .7, 0).add(entity.getForward().normalize().scale(2f)));
    gust.range = range;
    gust.strength = strength;
    gust.amplifier = spellLevel - 1;
    level.addFreshEntity(gust);
    gust.setDealDamageActive();
    gust.tick();

    float kickback = (float) entity.getBoundingBox().getCenter().distanceToSqr(Utils.getTargetBlock(level, entity, ClipContext.Fluid.NONE, 3.5f).getLocation());
    kickback = Mth.clamp(1 / (kickback + 1) - .11f, 0f, .95f);
    if (kickback > 0) {
        entity.setDeltaMovement(entity.getDeltaMovement().subtract(entity.getLookAngle().scale(kickback * spellLevel * .25f)));
        entity.resetFallDistance();
        entity.hurtMarked = true;
    }
    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    PlayerRecasts recasts = playerMagicData.getPlayerRecasts();
    if (!recasts.hasRecastForSpell(this)) {
        SummonedEntitiesCastData summonedEntitiesCastData = new SummonedEntitiesCastData();
        int summonTime = 20 * 60 * 10;
        Vec3 spawn = entity.position();
        Vec3 forward = entity.getForward().normalize().scale(1.5f);
        spawn.add(forward.x, 0.15f, forward.z);

        SummonedHorse horse = new SummonedHorse(world, entity);
        horse.setPos(spawn);
        setAttributes(horse, getSpellPower(spellLevel, entity) / 100f);
        var creature = NeoForge.EVENT_BUS.post(new SpellSummonEvent<>(entity, horse, this.spellId, spellLevel)).getCreature();
        world.addFreshEntity(creature);
        SummonManager.initSummon(entity, creature, summonTime, summonedEntitiesCastData);

        RecastInstance recastInstance = new RecastInstance(this.getSpellId(), spellLevel, getRecastCount(spellLevel, entity), summonTime, castSource, summonedEntitiesCastData);
        recasts.addRecast(recastInstance, playerMagicData);
    }

    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

