private void delayExhaustion(Player attacker, ItemModularHandheld item, ItemStack itemStack, int duration, int amplifier) {
    int delay = getChargeTime(item, itemStack) + getCooldown(item, itemStack) + item.getEffectLevel(itemStack, ItemEffect.abilityEcho);

    try {
        DelayData data = delayCache.get(attacker.getId(), DelayData::new);
        data.timestamp = attacker.level().getGameTime() + delay;
        data.amplifier += amplifier;
    } catch (ExecutionException e) {
        e.printStackTrace();
    }

    ServerScheduler.schedule(delay + 1, () -> {
        DelayData data = delayCache.getIfPresent(attacker.getId());
        if (attacker.isAlive() && attacker.level() != null && data != null && attacker.level().getGameTime() > data.timestamp) {
            int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);
            attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, duration, currentAmp + data.amplifier, false, true));

            delayCache.invalidate(attacker.getId());
        }
    });
}

public static void perform(LivingEntity entity, ItemStack itemStack, double multiplier) {
    if (!entity.level().isClientSide && entity instanceof Player player) {
        double effectProbability = EffectHelper.getEffectLevel(itemStack, ItemEffect.ravenous);

        if (effectProbability > 0 && entity.getRandom().nextDouble() < effectProbability / 100 * multiplier) {
            float exhaustAmount = EffectHelper.getEffectEfficiency(itemStack, ItemEffect.ravenous);
            player.causeFoodExhaustion(exhaustAmount);
        }

        if (effectProbability > 0 && player.getFoodData().getFoodLevel() == 0) {
            MobEffectInstance currentExhaustedInstance = player.getEffect(ExhaustedPotionEffect.instance);
            int currentAmplifier = Optional.ofNullable(currentExhaustedInstance)
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);

            int duration = Optional.ofNullable(currentExhaustedInstance)
                    .map(MobEffectInstance::getDuration)
                    .map(currentDuration -> currentDuration + exhaustionStackDuration)
                    .orElse(exhaustionInitialDuration);
            player.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, duration, currentAmplifier + 1, false, false, true));
        }
    }
}

public static void perform(ItemStack itemStack, int effectLevel, LivingEntity attacker, LivingEntity target) {
    if (attacker.getRandom().nextFloat() < effectLevel / 100f) {
        int stackCap = (int) EffectHelper.getEffectEfficiency(itemStack, ItemEffect.severing) - 1;

        int currentAmplifier = Optional.ofNullable(target.getEffect(SeveredPotionEffect.instance))
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1);

        target.addEffect(new MobEffectInstance(SeveredPotionEffect.instance, 1200, Math.min(currentAmplifier + 1, stackCap), false, false));

