                    target.getX() + target.getBbWidth() * (0.3 + rand.nextGaussian() * 0.4),
                    target.getY() + target.getBbHeight() * (0.2 + rand.nextGaussian() * 0.4),
                    target.getZ() + target.getBbWidth() * (0.3 + rand.nextGaussian() * 0.4),
                    20,
                    0, 0, 0, 0f);
        }
    }
}

public CastResult canBeCastedBy(int spellLevel, CastSource castSource, MagicData playerMagicData, Player player) {
    if (ServerConfigs.DISABLE_ADVENTURE_MODE_CASTING.get()) {
        if (player instanceof ServerPlayer serverPlayer && serverPlayer.gameMode.getGameModeForPlayer() == GameType.ADVENTURE) {
            return new CastResult(CastResult.Type.FAILURE, Component.translatable("ui.irons_spellbooks.cast_error_adventure").withStyle(ChatFormatting.RED));
        }
    }
    var playerMana = playerMagicData.getMana();

    boolean hasEnoughMana = playerMana - getManaCost(spellLevel) >= 0;
    boolean isSpellOnCooldown = playerMagicData.getPlayerCooldowns().isOnCooldown(this);
    boolean hasRecastForSpell = playerMagicData.getPlayerRecasts().hasRecastForSpell(getSpellId());
    if (requiresLearning() && !isLearned(player)) {
        return new CastResult(CastResult.Type.FAILURE, Component.translatable("ui.irons_spellbooks.cast_error_unlearned").withStyle(ChatFormatting.RED));
    } else if (castSource == CastSource.SCROLL && this.getRecastCount(spellLevel, player) > 0) {
        return new CastResult(CastResult.Type.FAILURE, Component.translatable("ui.irons_spellbooks.cast_error_scroll", getDisplayName(player)).withStyle(ChatFormatting.RED));
    } else if ((castSource == CastSource.SPELLBOOK || castSource == CastSource.SWORD) && isSpellOnCooldown && !(player.isCreative() && !ServerConfigs.CREATIVE_COOLDOWN.get())) {
        return new CastResult(CastResult.Type.FAILURE, Component.translatable("ui.irons_spellbooks.cast_error_cooldown", getDisplayName(player)).withStyle(ChatFormatting.RED));
    } else if (!hasRecastForSpell && castSource.consumesMana() && !hasEnoughMana && !(player.isCreative() && !ServerConfigs.CREATIVE_MANA_COST.get())) {
        return new CastResult(CastResult.Type.FAILURE, Component.translatable("ui.irons_spellbooks.cast_error_mana", getDisplayName(player)).withStyle(ChatFormatting.RED));
    } else {
        return new CastResult(CastResult.Type.SUCCESS);
    }
}

public void tick() {
    this.firstTick = false;
    var owner = getOwner();
    if (owner != null) {
        setPos(owner.position());
        this.xOld = owner.xOld;
        this.yOld = owner.yOld;
        this.zOld = owner.zOld;
        this.xo = owner.xo;
        this.yo = owner.yo;
        this.zo = owner.zo;
    }
    if (shouldFade && this.tickCount >= duration - 10) {
        this.entityData.set(DATA_FADING, true);
    }
    if (!level.isClientSide
            && (duration > 0 && tickCount > duration
            || duration == 0 && tickCount > 20 * 20
            || (hasOwner && (owner == null || owner.isRemoved())))
    ) {
        discard();
    }
}

public static void handleClientBoundOnCastFinished(UUID castingEntityId, String spellId, boolean cancelled) {
    ClientMagicData.resetClientCastState(castingEntityId);
    var player = Minecraft.getInstance().player.level.getPlayerByUUID(castingEntityId);

    var spell = SpellRegistry.getSpell(spellId);


    var finishAnimation = spell.getCastFinishAnimation();

    if (finishAnimation.getForPlayer().isPresent() && !cancelled) {
        AnimationHelper.animatePlayerStart(player, finishAnimation.getForPlayer().get());
    } else if (finishAnimation != AnimationHolder.pass() || cancelled) {
        AnimationHelper.cancelPlayerAnimation((AbstractClientPlayer) player);
    }

    if (cancelled && spell.stopSoundOnCancel()) {
        spell.getCastStartSound().ifPresent((soundEvent) -> Minecraft.getInstance().getSoundManager().stop(soundEvent.getLocation(), null));
    }

    if (castingEntityId.equals(Minecraft.getInstance().player.getUUID()) && ClientInputEvents.isUseKeyDown()) {
        ClientInputEvents.hasReleasedSinceCasting = false;
    }
}

public static List<MutableComponent> formatActiveSpellTooltip(ItemStack stack, SpellData spellData, CastSource castSource, @Nonnull LocalPlayer player) {
    var spell = spellData.getSpell();
    var spellLevel = spell.getLevelFor(spellData.getLevel(), player);
    var title = getTitleComponent(spellData, player);
    var uniqueInfo = spell.getUniqueInfo(spellLevel, player);
    var manaCost = getManaCostComponent(spell.getCastType(), spell.getManaCost(spellLevel)).withStyle(ChatFormatting.BLUE);
    var cooldownTime = Component.translatable("tooltip.irons_spellbooks.cooldown_length_seconds", Utils.timeFromTicks(MagicManager.getEffectiveSpellCooldown(spell, player, castSource), 2)).withStyle(ChatFormatting.BLUE);

    List<MutableComponent> lines = new ArrayList<>();
    lines.add(Component.empty());
    lines.add(title);
    uniqueInfo.forEach((line) -> lines.add(Component.literal(" ").append(line.withStyle(getStyleFor(player, spell)))));
    if (spell.getCastType() != CastType.INSTANT) {
        lines.add(Component.literal(" ").append(getCastTimeComponent(spell.getCastType(), Utils.timeFromTicks(spell.getEffectiveCastTime(spellLevel, player), 2)).withStyle(ChatFormatting.BLUE)));
    }
    if ((castSource != CastSource.SWORD || ServerConfigs.SWORDS_CONSUME_MANA.get()) && spell.getManaCost(spellLevel) > 0) {
        lines.add(manaCost);
    }
    if ((castSource != CastSource.SWORD || ServerConfigs.SWORDS_CD_MULTIPLIER.get().floatValue() > 0) && spell.getSpellCooldown() > 0) {
        lines.add(cooldownTime);
    }
    return lines;
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
    if (!target.level().isClientSide) {
        AbilityUseResult result;
        if (isDefensive(item, itemStack, hand)) {
            result = defensiveExecute(attacker, item, itemStack, target);
        } else {
            result = regularExecute(attacker, item, itemStack, target, chargedTicks);
        }

        playEffects(result != AbilityUseResult.fail, target, hitVec);

        item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);
    }

    attacker.causeFoodExhaustion(1f);
    attacker.swing(hand, false);
    attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack));

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    item.applyDamage(2, itemStack, attacker);
}

public AbilityUseResult performDefensive(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack,
        LivingEntity target) {
    int armor = target.getArmorValue();

    float knockbackMultiplier = 0.3f;

    boolean isPunctured = target.getEffect(PuncturedPotionEffect.instance) != null;
    if (armor < 6 || isPunctured) {
        knockbackMultiplier += 0.6f;
    }

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, 0.3, 0.8f, knockbackMultiplier);

    if (result != AbilityUseResult.fail) {
        target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, (int) (item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) * 20),
                item.getEffectLevel(itemStack, ItemEffect.abilityDefensive), false, true));

        target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_KNOCKBACK, SoundSource.PLAYERS, 1, 0.8f);
    } else {
        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.8f);
    }

    return result;
}

public void handleClientEvent(byte eventId) {
    switch (eventId) {
        case CLIENT_STOP_TRACKING -> {
            FogManager.stopEvent(this.uuid);
            MusicManager.stopEvent(this.uuid);
            BossbarManager.stopTracking(this.uuid);
        }
        case CLIENT_START_TRACKING -> {
            FogManager.createEvent(this, new FogManager.FogEvent(Optional.empty(), true));
            if (!isSpawning()) {
                MusicManager.createEvent(this, new FireBossMusicHandler(true));
            }
            BossbarManager.startTracking(this.uuid, BOSSBAR_SPRITE);
        }
        case PROC_HALF_HEALTH_TIMER -> this.halfHealthTimer = HALF_HEALTH_ANIM_DURATION;
        case STOP_HALF_HEALTH_TIMER -> {
            this.halfHealthTimer = 0;
            this.playAnimation("idle");
        }
        case START_MUSIC -> MusicManager.createEvent(this, new FireBossMusicHandler(true));
        case STOP_MUSIC -> MusicManager.stopEvent(this.uuid);
        case DAGGER_PARTICLES -> this.clientDaggerParticles = true;
    }
}

public void onEntityUpdate(LivingDamageEvent.Pre event) {
  if (!isEnabled()) { return; }
  final int level = EnchantUtil.getCurrentArmorLevelSlot(
      EnchantUtil.holder(EnchantRegistry.STAND, event.getEntity()), event.getEntity(), EquipmentSlot.LEGS);
  if (level > 0 && event.getEntity().getHealth() - event.getOriginalDamage() <= 0 && event.getEntity() instanceof ServerPlayer player) {
    int cooldownTicks = COOLDOWN == null ? 20 : COOLDOWN.get();
    if (cooldownTicks > 0 && player.getCooldowns().isOnCooldown(player.getItemBySlot(EquipmentSlot.LEGS).getItem())) {
      return;
    }
    final int xpCost = Math.max(1, (COST == null ? 50 : COST.get()) / level);
    if (PlayerUtil.getExpTotal(player) < xpCost) { return; }
    float toSurvive = event.getEntity().getHealth() - 1;
    event.setNewDamage (toSurvive);
    player.giveExperiencePoints(-1 * xpCost);
    SoundUtil.playSoundFromServer(player, SoundRegistry.CHAOS_REAPER.get(), 1F, 0.4F);
    ChatUtil.sendStatusMessage(player, "enchantment." + ModCyclic.MODID + "." + ID + ".activated");
    int absTicks = ABS == null ? 600 : ABS.get();
    if (absTicks > 0) {
      player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, absTicks, level - 1));
    }
    if (cooldownTicks > 0) {
      player.getCooldowns().addCooldown(player.getItemBySlot(EquipmentSlot.LEGS).getItem(), cooldownTicks);
    }
  }
}

private ItemStack buildPreviewStack(UpgradeSchematic schematic, ItemStack targetStack, String slot, ItemStack[] materials) {
    if (schematic.isMaterialsValid(targetStack, slot, materials)) {
        ItemStack result = schematic.applyUpgrade(targetStack, materials, false, slot, null);

        float severity = schematic.getSeverity(targetStack, materials, slot);
        boolean willReplace = schematic.willReplace(targetStack, materials, slot);

        if (willReplace) {
            TetraEnchantmentHelper.removeEnchantments(result, slot);
        }

        Map<ToolAction, Integer> tools = schematic.getRequiredToolLevels(targetStack, materials);
        for (Map.Entry<ToolAction, Integer> entry : tools.entrySet()) {
            result = WorkbenchTile.consumeCraftingToolEffects(result, slot, willReplace, entry.getKey(), entry.getValue(), viewingPlayer,
                    tileEntity.getLevel(), tileEntity.getBlockPos(), tileEntity.getBlockState(), false);
        }

        result = WorkbenchTile.applyCraftingBonusEffects(result, slot, willReplace, viewingPlayer, materials, materials, tools, schematic,
                tileEntity.getLevel(), tileEntity.getBlockPos(), tileEntity.getBlockState(), false, severity);

        IModularItem.updateIdentifier(result);
        return result;
    }
    return ItemStack.EMPTY;
}

public void teleport(Entity entity) {
    if (entity.level instanceof ServerLevel serverLevel) {
        var uuid = this.getUUID();
        PortalManager.INSTANCE.processDelayCooldown(uuid, entity.getUUID(), 1);
        if (PortalManager.INSTANCE.canUsePortal(uuid, entity)) {
            var portalData = PortalManager.INSTANCE.getPortalData(uuid);
            PortalManager.INSTANCE.addPortalCooldown(entity, uuid);
            //PortalManager.INSTANCE.addPortalCooldown(entity, portalData.portalEntityId2);
            portalData.getConnectedPortalPos(uuid).ifPresent(portalPos -> {
                Vec3 destination = portalPos.pos();
                serverLevel.playSound(null, this.getBlockPos(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.BLOCKS, 1f, 1f);
                if (serverLevel.dimension().equals(portalPos.dimension())) {
                    entity.teleportTo(serverLevel, destination.x, destination.y, destination.z, RelativeMovement.ROTATION, portalPos.rotation(), entity.getXRot());
                } else {
                    var server = serverLevel.getServer();
                    var dim = server.getLevel(portalPos.dimension());
                    if (dim != null) {
                        entity.changeDimension(new DimensionTransition(dim, destination, Vec3.ZERO, portalPos.rotation(), entity.getXRot(), DimensionTransition.DO_NOTHING));
                        dim.playSound(null, destination.x, destination.y, destination.z, SoundEvents.ENDERMAN_TELEPORT, SoundSource.BLOCKS, 1f, 1f);
                    }
                }
            });
        }
    }
}

public synchronized void saveSummonerData(ServerLevel serverLevel, Entity summoner) {
    Set<UUID> summons = ownerToSummons.get(summoner.getUUID());
    if (summons == null) {
        return;
    }
    var savedSummons = new ArrayList<CompoundTag>();
    List<Entity> toRemove = new ArrayList<>();
    for (UUID uuid : summons) {
        Entity entity = serverLevel.getEntity(uuid);
        if (entity != null && !entity.isRemoved() && entity.isAddedToLevel()) {
            CompoundTag saveData = new CompoundTag();
            entity.save(saveData);
            int durationRemaining = INSTANCE.getExpirationTick(entity.getUUID()) - serverLevel.getServer().getTickCount();
            saveData.putInt("summon_duration_remaining", durationRemaining);
            savedSummons.add(saveData);
            toRemove.add(entity);
        }
    }
    for (Entity entity : toRemove) {
        entity.setRemoved(Entity.RemovalReason.UNLOADED_WITH_PLAYER);
    }
    IronsDataStorage.INSTANCE.setDirty();
    INSTANCE.offlineSummonersToSavedEntities.put(summoner.getUUID(), savedSummons);
    INSTANCE.stopTrackingSummonerAndSummons(summoner);
}

protected void doAction() {
    var target = mob.getTarget();
    if (target != null) {
        mob.playSound(SoundRegistry.FIRE_CAST.get(), 2f, Utils.random.nextIntBetweenInclusive(80, 110) * .01f);

        Vec3 pos = mob.position();
        int count = 7;
        int delay = Utils.random.nextIntBetweenInclusive(30, 70);
        float yAngle = -Utils.getAngle(target.getX(), target.getZ(), mob.getX(), mob.getZ()) + Mth.HALF_PI;
        for (int i = 0; i < count; i++) {
            Vec3 offset = new Vec3(1.5 * mob.getScale(), 0, 0)
                    .zRot(Mth.lerp(i / (count - 1f), 0, -Mth.PI))
                    .yRot(yAngle)
                    .add(0, mob.getEyeHeight(), 0);
            FieryDaggerEntity dagger = new FieryDaggerEntity(mob.level);
            dagger.setOwner(mob);
            dagger.ownerTrack = offset;
            dagger.setTarget(mob.getTarget());
            dagger.setPos(pos.add(offset.yRot(mob.getYRot())));
            dagger.delay = delay + i * 2;
            dagger.setDamage((float) (mob.getAttributeValue(Attributes.ATTACK_DAMAGE) * .75));
            mob.level.addFreshEntity(dagger);
        }
    }
}

