private void doSummon() {
    boolean isSkeleton = random.nextDouble() < .3;
    Monster undead = isSkeleton ?
            new SummonedSkeleton(level, false) :
            new SummonedZombie(level, false);
    equip(undead, generateEquipment());
    undead.moveTo(this.position().add(0, 0.1, 0));
    undead.setYRot(this.getYRot());
    undead.finalizeSpawn((ServerLevel) level, level.getCurrentDifficultyAt(undead.getOnPos()), MobSpawnType.MOB_SUMMONED, null);
    SummonManager.setDuration(undead, 5 * 60 * 20);
    var owner = getSummoner();
    if (owner != null) {
        SummonManager.setOwner(undead, owner);
        if (forcedTarget != null) {
            undead.setTarget(forcedTarget);
        } else if (owner instanceof Mob mob) {
            undead.setTarget(mob.getTarget());
        }
    }
    undead.setDeltaMovement(this.getForward().add(0, 0.5, 0).scale(0.25));
    level.addFreshEntity(undead);
    Vec3 pos = this.position();
    MagicManager.spawnParticles(level, ParticleTypes.SMOKE, pos.x, pos.y + 1, pos.z, 25, 0.1, 0.3, 0.1, 0.1, false);
    level.playSound(null, pos.x, pos.y, pos.z, SoundEvents.TRIAL_SPAWNER_SPAWN_MOB, SoundSource.HOSTILE, 2f, 1.0f);
    level.playSound(null, pos.x, pos.y, pos.z, SoundEvents.VEX_AMBIENT, SoundSource.HOSTILE, 2f, 0.75f);
}

public void tick() {
    if (!level.isClientSide) {
        if (tickCount % delay == 0) {
            //do volley
            int arrows = arrowsPerRow;
            float speed = .85f;
            Vec3 motion = Vec3.directionFromRotation(getXRot() - tickCount / 5f * 7, this.getYRot()).normalize().scale(speed);
            Vec3 orth = new Vec3(-Mth.cos(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI), 0, Mth.sin(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI));
            for (int i = 0; i < arrows; i++) {
                float distance = (i - arrows * .5f) * .7f;
                SmallMagicArrow arrow = new SmallMagicArrow(this.level, this.getOwner());
                arrow.setDamage(this.getDamage());
                var spawn = this.position().add(orth.scale(distance));
                arrow.setPos(spawn);
                arrow.shoot(motion.add(Utils.getRandomVec3(.04f)));
                arrow.setOwner(this.getOwner());
                level.addFreshEntity(arrow);
                MagicManager.spawnParticles(level, ParticleTypes.FIREWORK, spawn.x, spawn.y, spawn.z, 2, .1, .1, .1, .05, false);
            }
            level.playSound(null, position().x, position().y, position().z, SoundEvents.FIREWORK_ROCKET_LAUNCH, SoundSource.NEUTRAL, 3.0f, 1.1f + Utils.random.nextFloat() * .3f);
            level.playSound(null, position().x, position().y, position().z, SoundRegistry.BOW_SHOOT.get(), SoundSource.NEUTRAL, 2, Utils.random.nextIntBetweenInclusive(16, 20) * .1f);
        } else if (tickCount > rows * delay) {
            discard();
        }
    }
}

public static void createEcho(LivingDamageEvent.Post event) {
    var damageSource = event.getSource();
    if (damageSource.getEntity() instanceof LivingEntity attacker && (damageSource.getDirectEntity() == attacker || damageSource.getDirectEntity() instanceof AbstractArrow) && !(damageSource instanceof SpellDamageSource)) {
        var effect = attacker.getEffect(MobEffectRegistry.ECHOING_STRIKES);
        if (effect == null) {
            return;
        }
        var data = EchoingStrikesData.get(attacker);
        if (!data.hasHitsRemaining()) {
            attacker.removeEffect(MobEffectRegistry.ECHOING_STRIKES);
            return;
        }
        var level = attacker.level();
        var percent = getDamageModifier(effect.getAmplifier(), attacker);
        var target = event.getEntity();
        if (damageSource.isDirect()) {
            createEchoingSword(attacker, level, target, event.getNewDamage() * percent);
        } else {
            createEchoingArrow(attacker, level, target, event.getNewDamage() * percent);
        }

        data.decrementHit();
        if (!data.hasHitsRemaining()) {
            attacker.removeEffect(MobEffectRegistry.ECHOING_STRIKES);
        }
    }
}

public void tick() {
    super.tick();

    var target = mob.getTarget();
    if (target == null) {
        return;
    }
    mob.attackGoal.setTarget(mob.getTarget());
    mob.attackGoal.doMovement(mob.distanceToSqr(mob.getTarget()));
    if (abilityTimer == DAMAGER_START) {
        mob.playSound(SoundRegistry.ICE_SPIDER_BITE.get());
    }
    if (abilityTimer >= DAMAGER_START && abilityTimer <= DAMAGER_END) {
        double meleeRange = mob.getAttributeValue(Attributes.ENTITY_INTERACTION_RANGE) * mob.getScale();
        if (target.distanceToSqr(mob) <= meleeRange * meleeRange && Utils.hasLineOfSight(mob.level, mob, target, true)) {
            if (this.mob.doHurtTarget(target)) {
                if (target.isBlocking() && target instanceof Player player) {
                    player.disableShield();
                } else {
                    mob.startGrapple(target);
                    mob.playSound(SoundRegistry.ICE_SPIDER_GRAPPLE_LATCH.get());
                }
            }
            stop(); // only allow one chance for the attack to land
        }
    }
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    if (entity instanceof ServerPlayer serverPlayer) {
        PortalData portalData = new PortalData();
        portalData.setPortalDuration(20 * 60);
        portalData.firstPortal(serverPlayer.getUUID(), PortalPos.of(serverPlayer.level.dimension(), serverPlayer.position(), serverPlayer.getYRot()));

        PocketDimensionManager.INSTANCE.maybeGeneratePocketRoom(serverPlayer);
        BlockPos portalPos = PocketDimensionManager.INSTANCE.findPortalForStructure(serverPlayer.serverLevel(), PocketDimensionManager.INSTANCE.structurePosForPlayer(serverPlayer));
        ServerLevel pocketLevel = serverPlayer.getServer().getLevel(PocketDimensionManager.POCKET_DIMENSION);
        var portal = pocketLevel.getBlockEntity(portalPos);
        if (portal instanceof PortalFrameBlockEntity portalFrameBlockEntity) {
            Vec3 particlePos = serverPlayer.getBoundingBox().getCenter();
            MagicManager.spawnParticles(level, ParticleTypes.SMOKE, particlePos.x, particlePos.y, particlePos.z, 100, 0.1, 0.2, 0.1, 0.1, false);

            var uuid = portalFrameBlockEntity.getUUID();
