public StructureTemplate.StructureBlockInfo processBlock(@NotNull LevelReader levelReader,
                                                         @NotNull BlockPos jigsawPiecePos,
                                                         @NotNull BlockPos jigsawPieceBottomCenterPos,
                                                         StructureTemplate.@NotNull StructureBlockInfo blockInfoLocal,
                                                         StructureTemplate.StructureBlockInfo blockInfoGlobal,
                                                         StructurePlaceSettings structurePlacementData) {
    // check if the current block is at local y = 0 (meaning we are at the min height of the structure piece)
    // and it is not air (and thus we wouldnt need foundation here)
    // and some other check from yungnickyung
    if (blockInfoLocal.pos().getY() == 0 && !blockInfoGlobal.state().is(Blocks.AIR)
            && !(levelReader instanceof WorldGenRegion worldGenRegion && !worldGenRegion.getCenter().equals(new ChunkPos(blockInfoGlobal.pos())))
    ) {
        BlockPos.MutableBlockPos mutable = blockInfoGlobal.pos().mutable().move(Direction.DOWN);
        BlockState currentState = levelReader.getBlockState(mutable);

        // while we have not traversed outside the bounds of the world and we have not yet hit solid material, create foundation block
        while (mutable.getY() > levelReader.getMinBuildHeight()
                && mutable.getY() < levelReader.getMaxBuildHeight()
                && (currentState.isAir() || !levelReader.getFluidState(mutable).isEmpty())) {
            levelReader.getChunk(mutable).setBlockState(mutable, block, false);
            // iterate downward
            mutable.move(Direction.DOWN);
            currentState = levelReader.getBlockState(mutable);
        }
    }
    return blockInfoGlobal;
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
  if (playerIn.getCooldowns().isOnCooldown(this)) {
    return super.use(worldIn, playerIn, handIn);
  }
  AttributeInstance healthAttribute = playerIn.getAttribute(Attributes.MAX_HEALTH);
  //    if (healthAttribute != null && healthAttribute.getBaseValue() > 2) {
  //get attribute modif by id
  AttributeModifier oldHealthModifier = healthAttribute.getModifier(AttributesUtil.DEFAULT_ID);
  double addedHealth = 0;
  if (oldHealthModifier != null && oldHealthModifier.amount() <= -18) {
    addedHealth = -18;
  }
  else {
    addedHealth = (oldHealthModifier == null) ? -2.0D : oldHealthModifier.amount() - 2.0D;
    //actually DO the eating of the thing
    playerIn.getCooldowns().addCooldown(this, COOLDOWN);
    playerIn.getItemInHand(handIn).shrink(1);
    SoundUtil.playSound(playerIn, SoundRegistry.FILL.get());
    playerIn.getFoodData().eat(3, 1);
    playerIn.giveExperiencePoints(HEARTXPMINUS.get());
  }
  //replace the modifier on the main attribute
  healthAttribute.removeModifier(AttributesUtil.DEFAULT_ID);
  AttributeModifier healthModifier = new AttributeModifier(AttributesUtil.DEFAULT_ID, addedHealth, AttributeModifier.Operation.ADD_VALUE);
  healthAttribute.addPermanentModifier(healthModifier);
  //
  return super.use(worldIn, playerIn, handIn);
}

public static void perform(LivingEntity entity, ItemStack itemStack, double multiplier) {
    if (!entity.level().isClientSide) {
        Level level = entity.level();
        double effectProbability = EffectHelper.getEffectEfficiency(itemStack, ItemEffect.vexing);
        if (effectProbability > 0
            && !isInTimeout(entity)
            && entity.getRandom().nextDouble() < effectProbability / 100 * multiplier) {
            int effectLevel = EffectHelper.getEffectLevel(itemStack, ItemEffect.vexing);
            BlockPos origin = entity.blockPosition();

            Vex vex = EntityType.VEX.create(level);
            if (vex != null) {
                vex.setItemInHand(InteractionHand.MAIN_HAND, itemStack.copy());
                vex.setDropChance(EquipmentSlot.MAINHAND, 0);
                vex.setLimitedLife(160);
                vex.moveTo(entity.getX(), entity.getY() + 1, entity.getZ(), entity.getYRot(), 0.0F);
                vex.setIsCharging(true);
                vex.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(origin), MobSpawnType.MOB_SUMMONED, null, null);
                vex.setBoundOrigin(origin);
                vex.addEffect(new MobEffectInstance(UnstablePowerMobEffect.instance, 1199, effectLevel - 1, false, false));

                ((ServerLevelAccessor) level).addFreshEntityWithPassengers(vex);
                vex.playAmbientSound();
                setCurrentVex(entity, vex);
            }
        }
    }
}

public boolean canUse() {
    if (!(this.owner.get() instanceof LivingEntity owner)) {
        return false;
    } else {
        if (--intervalToCheck <= 0) {
            var entities = owner.level.getEntitiesOfClass(Mob.class, owner.getBoundingBox().inflate(16, 8, 16), potentionalAggressor -> potentionalAggressor.getTarget() != null &&
                    (potentionalAggressor.getTarget().getUUID().equals(owner.getUUID())
                            || (potentionalAggressor.getTarget() instanceof IMagicSummon summon
                            && summon.getSummoner() != null && summon.getSummoner().getUUID().equals(owner.getUUID())))
                    && Utils.hasLineOfSight(mob.level, mob.getEyePosition(), potentionalAggressor.getEyePosition(), false)
            );
            if (entities.isEmpty()) {
                currentIntensity = Math.max(0, currentIntensity - 10);
                return false;
            } else {
                mob.setTarget(entities.stream().min(Comparator.comparingDouble(o -> o.distanceToSqr(owner))).orElse(entities.getFirst()));
                return true;
            }
        } else {
            int i = owner.getLastHurtByMobTimestamp();
            int tick = owner.tickCount;
            int combatIntervalModifier = Math.clamp((tick - i) / 5, 0, 200);
            int intensityModifier = maxIntensity - currentIntensity;
            intervalToCheck = 20 + combatIntervalModifier + intensityModifier;
        }
    }
    return false;
}

