public void createDaggerZone(Vec3 center) {
    MagicManager.spawnParticles(level, new BlastwaveParticleOptions(new Vector3f(1, .6f, 0.3f), explosionRadius + 1), center.x, center.y + .15, center.z, 1, 0, 0, 0, 0, false);
    playSound(SoundRegistry.FIRE_CAST.get(), 2f, Utils.random.nextIntBetweenInclusive(80, 110) * .01f);

    float spawnRadius = this.explosionRadius;
    float density = 1f;
    int rings = (int) (spawnRadius * density);
    float ringSpacing = 1 / density;
    for (int i = 1; i < rings; i++) {
        float ringRadius = ringSpacing * i;
        int daggerCount = (int) (ringRadius * Mth.TWO_PI);
        float angle = 360f / daggerCount * Mth.DEG_TO_RAD;
        for (int j = 0; j < daggerCount; j++) {
            Vec3 jitter = Utils.getRandomVec3(ringSpacing * .4f);
            Vec3 pos = Utils.moveToRelativeGroundLevel(level, center.add(ringRadius * Mth.sin(angle * j), 0, ringRadius * Mth.cos(angle * j)).add(jitter), 8);
            FieryDaggerEntity dagger = new FieryDaggerEntity(level);
            dagger.setOwner(this.getOwner());
            dagger.setDamage(this.getDamage());
            dagger.delay = this.delay + Utils.random.nextInt(20);
            dagger.setDeltaMovement(0, getSpeed(), 0);
            dagger.deltaMovementOld = dagger.getDeltaMovement();
            dagger.moveTo(pos);
            dagger.isGrounded = true;
            level.addFreshEntity(dagger);
        }
    }
    createFireField();
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    var recasts = playerMagicData.getPlayerRecasts();
    if (!recasts.hasRecastForSpell(this)) {
        SummonedEntitiesCastData summonedEntitiesCastData = new SummonedEntitiesCastData();
        int summonTime = 20 * 60 * 10;
        AttributeModifier healthModifier = new AttributeModifier(IronsSpellbooks.id("spell_power_health_bonus"), getHealthBonus(spellLevel, entity), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
        AttributeModifier damageModifier = new AttributeModifier(IronsSpellbooks.id("spell_power_damage_bonus"), getDamageBonus(spellLevel, entity), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);

        SummonedWeaponEntity claymore = new SummonedClaymoreEntity(world, entity);
        SummonedWeaponEntity rapier = new SummonedRapierEntity(world, entity);
        SummonedWeaponEntity sword = new SummonedSwordEntity(world, entity);

        List<SummonedWeaponEntity> weapons = List.of(claymore, rapier, sword);
        weapons.forEach(weapon -> {
            weapon.moveTo(entity.position().add(0, 1.2, 0).add(Utils.getRandomVec3(1)));
            weapon.getAttribute(Attributes.ATTACK_DAMAGE).addPermanentModifier(damageModifier);
            weapon.getAttribute(Attributes.MAX_HEALTH).addPermanentModifier(healthModifier);
            weapon.setHealth(weapon.getMaxHealth());
            var creature = NeoForge.EVENT_BUS.post(new SpellSummonEvent<>(entity, weapon, this.spellId, spellLevel)).getCreature();
            world.addFreshEntity(creature);
            SummonManager.initSummon(entity, creature, summonTime, summonedEntitiesCastData);
        });
        RecastInstance recastInstance = new RecastInstance(this.getSpellId(), spellLevel, getRecastCount(spellLevel, entity), summonTime, castSource, summonedEntitiesCastData);
        recasts.addRecast(recastInstance, playerMagicData);
    }

    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, TileConveyor e) {
  e.tick();
  // Convert any regular ItemEntities on the belt
  final double edgeBuf = 0.02;
  boolean isRamp = blockState.getValue(BlockConveyor.TYPE).isVertical();
  double conversionCeiling = isRamp ? blockPos.getY() + 1.5 : blockPos.getY() + 0.5;
  List<ItemEntity> regularItems = level.getEntitiesOfClass(ItemEntity.class, new AABB(blockPos).inflate(-edgeBuf, 0, -edgeBuf).expandTowards(0.0F, 0.5F, 0.0F));
  for (ItemEntity item : regularItems) {
    boolean centerInBlock = item.getX() >= blockPos.getX() && item.getX() <= blockPos.getX() + 1
        && item.getZ() >= blockPos.getZ() && item.getZ() <= blockPos.getZ() + 1;
    if (!(item instanceof ConveyorItemEntity) && item.getY() <= conversionCeiling && centerInBlock) {
      ConveyorItemEntity wrapped = new ConveyorItemEntity(level, item.getX(), item.getY(), item.getZ(), item.getItem().copy());
      level.addFreshEntity(wrapped);
      item.discard();
    }
  }
  //try to insert at the exit edge into the adjacent block
  List<ConveyorItemEntity> beltItems = level.getEntitiesOfClass(ConveyorItemEntity.class, new AABB(blockPos).expandTowards(0.0F, 0.5F, 0.0F));
  for (ConveyorItemEntity item : beltItems) {
    tryInsertIntoOutput(item, blockState, blockPos, level);
  }
  // Periodically extract one item from the block at the belt's input end
  if (e.extractCooldown > 0) {
    e.extractCooldown--;
  } else {
    e.extractCooldown = extractRate();
    tryExtractFromInput(blockState, blockPos, level);
  }
}

public void tick() {
  this.syncEnergy();
  if (this.requiresRedstone() && !this.isPowered()) {
    setLitProperty(false);
    return;
  }
  timer--;
  final int cost = POWERCONF.get();
  if (energy.getEnergyStored() < cost) {
    if (cost > 0) {
      setLitProperty(false);
      return; //out of energy so keep it rendered as off
    }
  }
  setLitProperty(true);
  if (timer > 0) {
    return;
  }
  timer = delay;
  ItemStack dropMe = inventory.getStackInSlot(0).copy();
  BlockPos target = getTargetPos();
  int amtDrop = Math.min(this.dropCount, dropMe.getCount());
  if (amtDrop > 0) {
    energy.extractEnergy(cost, false);
    dropMe.setCount(amtDrop);
    ItemStackUtil.dropItemStackMotionless(level, target, dropMe);
    inventory.getStackInSlot(0).shrink(amtDrop);
  }
}

public void castSpell(Level world, int spellLevel, ServerPlayer serverPlayer, CastSource castSource, boolean triggerCooldown) {
    if (Log.SPELL_DEBUG) {
        IronsSpellbooks.LOGGER.debug("AbstractSpell.castSpell isClient:{}, spell{}({})", world.isClientSide, getSpellId(), spellLevel);
    }

    MagicData magicData = MagicData.getPlayerMagicData(serverPlayer);
    var playerRecasts = magicData.getPlayerRecasts();
    var playerAlreadyHasRecast = playerRecasts.hasRecastForSpell(getSpellId());

    var event = new SpellOnCastEvent(serverPlayer, this.getSpellId(), spellLevel, getManaCost(spellLevel), this.getSchoolType(), castSource);
    NeoForge.EVENT_BUS.post(event);
    if (castSource.consumesMana() && !playerAlreadyHasRecast && !(serverPlayer.isCreative() && !ServerConfigs.CREATIVE_MANA_COST.get())) {
        var newMana = Math.max(magicData.getMana() - event.getManaCost(), 0);
        magicData.setMana(newMana);
        PacketDistributor.sendToPlayer(serverPlayer, new SyncManaPacket(magicData));
    }
    onCast(world, event.getSpellLevel(), serverPlayer, castSource, magicData);

    //If onCast just added a recast then don't decrement it

    var playerHasRecastsLeft = playerRecasts.hasRecastForSpell(getSpellId());
    if (playerAlreadyHasRecast && playerHasRecastsLeft) {
        playerRecasts.decrementRecastCount(getSpellId());
    } else if (!playerHasRecastsLeft && triggerCooldown && !(serverPlayer.isCreative() && !ServerConfigs.CREATIVE_COOLDOWN.get())) {
        MagicHelper.MAGIC_MANAGER.addCooldown(serverPlayer, this, castSource);
    }

    PacketDistributor.sendToPlayer(serverPlayer, new OnClientCastPacket(this.getSpellId(), spellLevel, castSource, magicData.getAdditionalCastData()));
}

