        fireOrb.setDamage(160 * intensity);
        fireOrb.setHealth(150);
        fireOrb.setRadius(50 * intensity);
        fireOrb.setOwner(mob);
        fireOrb.setPos(pos);
        mob.level.addFreshEntity(fireOrb);
    }
}

