public static void causeEffect(Level world, Player breakingPlayer, ItemStack toolStack, BlockPos origin, ToolAction tool) {
    if (world.isClientSide) {
        return;
    }

    boolean alternate = isAlternate(breakingPlayer);
    var targets = breakBlocksAround(world, breakingPlayer, toolStack, origin, tool, alternate);

    int minDelay = targets.stream()
            .mapToInt(Pair::getLeft)
            .min()
            .orElse(0);
    int maxDelay = targets.stream()
            .mapToInt(Pair::getLeft)
            .max()
            .orElse(0);
    int duration = maxDelay - minDelay;
    duration = targets.size() > 10 ? duration : duration * 2;
    duration = Math.max(4, duration);

    double distance = breakingPlayer.getEyePosition().subtract(Vec3.atCenterOf(origin)).length();

    causeVfx(breakingPlayer, alternate, duration, (float) distance - 0.5f);

    if (toolStack.getItem() instanceof ItemModularHandheld item) {
        int amount = Math.max(1, targets.size() / 4);

        if (!targets.isEmpty()) {
            item.applyUsageEffects(breakingPlayer, toolStack, amount);
        }
        item.applyDamage(amount, toolStack, breakingPlayer);
    }
}

    private Map<String, String> getValuesFromSpell(AbstractSpell spell) {
        var info = spell.getUniqueInfo(spell.getMaxLevel(), null);
        var map = new HashMap<String, String>();
        map.put("Name", Component.translatable(spell.getComponentId()).getString());
        map.put("Mana Cost", String.valueOf(spell.getManaCost(spell.getMaxLevel())));
        map.put("Cooldown", Utils.timeFromTicks(spell.getSpellCooldown(), 0));
        map.put("Cast Type", spell.getCastType().toString());
        Set<String> tracked = new HashSet<>();
        for (Component component : info) {
            if (component.getContents() instanceof TranslatableContents translatableContents) {
//                String property = Component.translatable(translatableContents.getKey()).getString().replace("%s ",""); // get translation key, generate without args, then remove empty args from resulting string
                String fullLine = component.getString();
                String translate = Component.translatable(translatableContents.getKey()).getString();
                int valueBeginIndex = translate.indexOf("%s");
                if (valueBeginIndex < 0) {
                    IronsSpellbooks.LOGGER.info("skipping property {}", translate);
                    continue;
                }
                int valueEndIndex = fullLine.indexOf(" ", valueBeginIndex);
                if (valueEndIndex < 0) {
                    valueEndIndex = fullLine.length();
                }
                String value = fullLine.substring(valueBeginIndex, valueEndIndex);
                String property = translate.replace("%s", "");
                map.put(property, value);
                if (!tracked.contains(property)) {
                    trackOccurance(property);
                    tracked.add(property); // prevent same spell adding duplicates
                }
            }
        }
        return map;
    }

public boolean applyEffectTick(LivingEntity livingEntity, int amplifier) {
    var self = livingEntity.getEffect(MobEffectRegistry.IMMOLATE);
    if (DELAYED_INSTANCES.containsKey(self) && !(DELAYED_INSTANCES.get(self) - duration > 4)) {
        return true;
    }
    float explosionRadius = 6;
    var level = livingEntity.level;
    if (level.isClientSide) {
        return true;
    }
    @Nullable Entity attacker = EFFECT_CREDIT.remove(livingEntity);
    double baseDamage = damageFor(attacker);

    var source = new DamageSource(level.damageSources().damageTypes.getHolderOrThrow(ISSDamageTypes.FIRE_MAGIC), attacker);
    var explosionRadiusSqr = explosionRadius * explosionRadius;
    var entities = level.getEntities(null, livingEntity.getBoundingBox().inflate(explosionRadius));
    Vec3 losPoint = Utils.raycastForBlock(level, livingEntity.position(), livingEntity.position().add(0, 1, 0), ClipContext.Fluid.NONE).getLocation();
    for (Entity entity : entities) {
        double distanceSqr = entity.distanceToSqr(livingEntity.position());
        if (distanceSqr < explosionRadiusSqr && entity.canBeHitByProjectile() && !DamageSources.isFriendlyFireBetween(attacker, entity) && Utils.hasLineOfSight(level, losPoint, entity.getBoundingBox().getCenter(), true)) {
            double p = (1 - distanceSqr / explosionRadiusSqr);
            float damage = (float) (baseDamage * p);
            entity.invulnerableTime = 0; // ensure explosion can hit after the damage that procs it
            if (entity.hurt(source, damage) && entity instanceof LivingEntity livingVictim) {
                var inst = addImmolateStack(livingVictim, attacker);
                DELAYED_INSTANCES.put(inst, inst.getDuration());
            }
        }
    }
    PacketDistributor.sendToPlayersTrackingEntityAndSelf(livingEntity, new FieryExplosionParticlesPacket(livingEntity.getBoundingBox().getCenter(), 1.5f));
    level.playSound(null, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), SoundEvents.GENERIC_EXPLODE.value(), livingEntity.getSoundSource(), 4.0F, (1.0F + (level.random.nextFloat() - level.random.nextFloat()) * 0.2F) * 0.7F);
    return false;
}

public void tickGrapple() {
    UUID uuid = getGrappleTargetUUID();
    if (uuid == null) {
        return;
    }
    if (!(level instanceof ServerLevel serverLevel)) {
        return;
    }
    if (cachedGrappleTarget == null) {
        var entity = serverLevel.getEntity(uuid);
        if (entity == null) {
            setGrappleTargetUUID(null);
            return;
        } else {
            cachedGrappleTarget = entity;
        }
    }
    if (cachedGrappleTarget.isRemoved()) {
        stopGrappling();
        return;
    }
    if (grappleTime % 20 == 0) {
        this.heal(this.getMaxHealth() * .08f);
    }
    if (grappleTime++ > 40) {
        var entity = cachedGrappleTarget;
        stopGrappling();
        entomb(entity);
    } else {
        cachedGrappleTarget.setTicksFrozen(Math.min(cachedGrappleTarget.getTicksRequiredToFreeze() * 3, cachedGrappleTarget.getTicksFrozen() + 10));
        yHeadRot = yBodyRot;
    }
}

