public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    entity.hasImpulse = true;
    float multiplier = (15 + getSpellPower(spellLevel, entity)) / 20f;

    Vec3 forward = entity.getLookAngle();

    //Create Dashing Movement Impulse
    var upwardness = forward.dot(new Vec3(0, 1, 0));
    var remap = 1 - (Math.max(0, upwardness) * 0.6f);
    var impulse = forward.scale(3 * multiplier).multiply(1, remap, 1);
    //Start Spin Attack
    if (entity.onGround()) {
        if (entity instanceof ServerPlayer serverPlayer) {
            serverPlayer.connection.teleport(serverPlayer.getX(), serverPlayer.getY() + 1, serverPlayer.getZ(), serverPlayer.getYRot(), serverPlayer.getXRot());
        } else {
            entity.move(MoverType.SELF, new Vec3(0.0, 1.1999999F, 0.0));
        }
        impulse.add(0, 0.5, 0);
    } else {
        impulse.add(0, 0.25, 0);
    }
    entity.setDeltaMovement(new Vec3(
            Mth.lerp(.75f, entity.getDeltaMovement().x, impulse.x),
            Mth.lerp(.75f, entity.getDeltaMovement().y, impulse.y),
            Mth.lerp(.75f, entity.getDeltaMovement().z, impulse.z)
    ));
    entity.hurtMarked = true;

    entity.addEffect(new MobEffectInstance(MobEffectRegistry.VOLT_STRIKE, 10, getDamage(spellLevel, entity), false, false, false));
    entity.invulnerableTime = 20;
    playerMagicData.getSyncedData().setSpinAttackType(SpinAttackType.LIGHTNING);
    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

public void onCriticalAttack(CriticalHitEvent event) {
    Player player = event.getEntity();
    ItemStack weapon = player.getMainHandItem();

    if (!weapon.isEmpty() && event.getTarget() instanceof LivingEntity livingEntity) {
        if (weapon.getItem() == ModItems.THE_IMMOLATOR.get()) {
            if(livingEntity.hasEffect(ModEffect.EFFECTBLAZING_BRAND.get())){
                event.setResult(Event.Result.ALLOW);
            }
        }
        if (weapon.getItem() == ModItems.THE_ANNIHILATOR.get() || weapon.getItem() == ModItems.CERAUNUS.get() || weapon.getItem() == ModItems.THE_IMMOLATOR.get() ) {
            if(event.isVanillaCritical()){
                livingEntity.playSound(ModSounds.PARRY.get(), 0.5f, 1.1F);
            }
        }
    }

    AttributeInstance attackDamageAttr = player.getAttribute(ModAttribute.ADDITIONAL_CRITICAL_DAMAGE.get());
    if (attackDamageAttr != null) {

        double extraCritPercent = attackDamageAttr.getValue();

        float vanillaCrit = event.getDamageModifier();

        float finalMultiplier = (float)(vanillaCrit + (extraCritPercent / 100.0));

        if (finalMultiplier < 1.0f) {
            finalMultiplier = 1.0f;
        }
        event.setDamageModifier(finalMultiplier);

    }
}

public void onTileEntityChange(Player player, WorkbenchTile tileEntity, ItemStack itemStack, String selectedSlot, UpgradeSchematic currentSchematic) {
    ItemModule module = CastOptional.cast(itemStack.getItem(), IModularItem.class)
            .map(item -> item.getModuleFromSlot(itemStack, selectedSlot))
            .orElse(null);

    if (currentSchematic == null) {
        updateSchematicList(player, tileEntity, selectedSlot);
    } else {
        Level world = tileEntity.getLevel();
        BlockPos pos = tileEntity.getBlockPos();
        Map<ToolAction, Integer> availableTools = PropertyHelper.getCombinedToolLevels(player, world, pos, world.getBlockState(pos));
        ItemStack[] materials = tileEntity.getMaterials();

        ItemStack previewStack = currentSchematic.applyUpgrade(itemStack.copy(), materials, false, selectedSlot, player);

        schematicDetail.update(world, pos, tileEntity, currentSchematic, itemStack, selectedSlot, materials, availableTools, player);
        schematicDetail.updateMagicCapacity(currentSchematic, selectedSlot, itemStack, previewStack);
        schematicDetail.updateButton(currentSchematic, player, itemStack, previewStack, materials, selectedSlot, availableTools);

        tab = 1;
    }

    moduleDetails.update(module, itemStack);
    tabGroup.setHasContent(0, module != null);

    tweakControls.update(module, itemStack);
    tabGroup.setHasContent(2, module != null && module.isTweakable(itemStack));

    schematicDetail.setVisible(currentSchematic != null);
    schematicList.setVisible(currentSchematic == null);

    updateTabVisibility();
    tabGroup.setActive(tab);
}

public void update(ItemStack itemStack, ItemModule module) {
    String moduleKey = module.getUnlocalizedName();
    String moduleVariant = module.getVariantData(itemStack).key;

    boolean hasActive = alwaysShowStats;

    tooltip = new ArrayList<>();
    tooltip.add(Component.translatable("tetra.modular.synergy_indicator.header").withStyle(ChatFormatting.GRAY));

    if (itemStack.getItem() instanceof IModularItem item) {
        Set<SynergyData> activeSynergies = Arrays.stream(item.getSynergyData(itemStack))
                .collect(Collectors.toSet());

        hasActive = hasActive || Arrays.stream(item.getSynergyData(itemStack))
                .filter(data -> shouldShow(data, activeSynergies, moduleKey, moduleVariant))
                .anyMatch(this::providesStats);

        Arrays.stream(item.getAllSynergyData(itemStack))
                .filter(data -> shouldShow(data, activeSynergies, moduleKey, moduleVariant))
                .filter(this::providesStats)
                .flatMap(data -> getLines(activeSynergies.contains(data), data).stream())
                .map(Component::literal)
                .collect(Collectors.toCollection(() -> tooltip));
    }

    if (tooltip.size() <= 1) {
        tooltip = Collections.singletonList(Component.translatable("tetra.modular.synergy_indicator.empty").withStyle(ChatFormatting.GRAY));
        indicator.setTextureCoordinates(emptyCoord, 0);
    } else if (!hasActive) {
        indicator.setTextureCoordinates(inactiveCoord, 0);
    } else {
        indicator.setTextureCoordinates(activeCoord, 0);
    }
}

public StructureTemplate.StructureBlockInfo process(LevelReader world, BlockPos pos, BlockPos pos2, StructureTemplate.StructureBlockInfo $,
        StructureTemplate.StructureBlockInfo blockInfo, StructurePlaceSettings placementSettings, @Nullable StructureTemplate template) {
    if (blockInfo.state().getBlock() instanceof TransferUnitBlock) {
        RandomSource random = placementSettings.getRandom(blockInfo.pos());

        CompoundTag newCompound = blockInfo.nbt().copy();

        int cellState = 0;

        // randomize cell
        if (random.nextFloat() < 0.1) {
            int charge = random.nextInt(ThermalCellItem.maxCharge);
            ItemStack itemStack = new ItemStack(ThermalCellItem.instance.get());
            ThermalCellItem.recharge(itemStack, charge);

            cellState = charge > 0 ? 2 : 1;

            TransferUnitBlockEntity.writeCell(newCompound, itemStack);
        } else if (random.nextFloat() < 0.2) {
            TransferUnitBlockEntity.writeCell(newCompound, new ItemStack(ThermalCellItem.instance.get()));
            cellState = 1;
        }

        // randomize configuration & plate
        EnumTransferConfig[] configs = EnumTransferConfig.values();
        BlockState newState = blockInfo.state()
                .setValue(TransferUnitBlock.cellProp, cellState)
                .setValue(TransferUnitBlock.configProp, configs[random.nextInt(configs.length)])
                .setValue(TransferUnitBlock.plateProp, random.nextBoolean());

        return new StructureTemplate.StructureBlockInfo(blockInfo.pos(), newState, newCompound);
    }
    return blockInfo;
}

protected static InteractionResult eat(LevelAccessor level, BlockPos pos, BlockState state, Player player) {
    if (!player.canEat(false)) {
        return InteractionResult.PASS;
    }
    player.getFoodData().eat(4, 1F);
    if (!level.isClientSide()) {
        MobEffectInstance mobEffectInstance = player.getEffect(MobEffectRegistry.FROSTBITTEN_STRIKES);
        if (mobEffectInstance == null) {
            mobEffectInstance = new MobEffectInstance(MobEffectRegistry.FROSTBITTEN_STRIKES, FROSTBITE_DURATION, FROSTBITE_AMPLIFIER, false, false, true);
        }else{
            mobEffectInstance = new MobEffectInstance(MobEffectRegistry.FROSTBITTEN_STRIKES, mobEffectInstance.getDuration() + FROSTBITE_DURATION, FROSTBITE_AMPLIFIER, false, false, true);
        }
        player.addEffect(mobEffectInstance);
        level.playSound(null, pos, SoundEvents.GENERIC_EAT, SoundSource.BLOCKS);
        level.playSound(null, pos, SoundEvents.HONEY_DRINK, SoundSource.BLOCKS);
    }
    for (int i = 0; i < 5; i++) {
        level.addParticle(ColorParticleOption.create(ParticleTypes.ENTITY_EFFECT, 0xFFd0f9ff),
                pos.getX() + (2 + level.getRandom().nextFloat() * 10) / 16f,
                pos.getY() + 15 / 16f,
                pos.getZ() + (2 + level.getRandom().nextFloat() * 14) / 16f,
                0, 0.1, 0);
    }
    int bites = state.getValue(BITES);
    level.gameEvent(player, GameEvent.EAT, pos);
    if (bites < MAX_BITES) {
        level.setBlock(pos, state.setValue(BITES, bites + 1), 3);
    } else {
        level.destroyBlock(pos, false);
        level.gameEvent(player, GameEvent.BLOCK_DESTROY, pos);
        level.playSound(null, pos, SoundEvents.SNIFFER_EGG_HATCH, SoundSource.BLOCKS);
    }
    return InteractionResult.SUCCESS;
}

private void handleEntityPortal(@Nullable RecastInstance recastInstance, Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData, Player player, ServerLevel serverLevel, BlockHitResult blockHitResult) {
    Vec3 hitResultPos = blockHitResult.getLocation().subtract(entity.getForward().normalize().multiply(.25, 0, .25));
    Vec3 portalLocation = level.clip(new ClipContext(hitResultPos, hitResultPos.add(0, -entity.getBbHeight() - 1, 0), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, entity)).getLocation().add(0, 0.076, 0);
    float portalRotation = 90 + Utils.getAngle(portalLocation.x, portalLocation.z, entity.getX(), entity.getZ()) * Mth.RAD_TO_DEG;
    if (recastInstance != null) {
        var portalData = (PortalData) recastInstance.getCastData();

        if (portalData.globalPos1 != null & portalData.portalEntityId1 != null) {
            portalData.globalPos2 = PortalPos.of(player.level.dimension(), portalLocation, portalRotation);
            portalData.setPortalDuration(getPortalDuration(spellLevel, player));
            PortalEntity secondPortalEntity = setupPortalEntity(serverLevel, portalData, player, portalLocation, portalRotation);
            secondPortalEntity.setPortalConnected();
            portalData.portalEntityId2 = secondPortalEntity.getUUID();
            PortalManager.INSTANCE.addPortalData(portalData.portalEntityId1, portalData);
            PortalManager.INSTANCE.addPortalData(portalData.portalEntityId2, portalData);

            var firstPortalLevel = serverLevel.getServer().getLevel(portalData.globalPos1.dimension());
            if (firstPortalLevel != null) {
                var firstPortalEntity = (PortalEntity) firstPortalLevel.getEntity(portalData.portalEntityId1);
                if (firstPortalEntity != null) {
                    firstPortalEntity.setPortalConnected();
                    firstPortalEntity.setTicksToLive(portalData.ticksToLive);
                }
            }
        }
    } else {
        var portalData = new PortalData();
        portalData.setPortalDuration(getRecastDuration(spellLevel, player) + 10);
        PortalEntity portalEntity = setupPortalEntity(level, portalData, player, portalLocation, portalRotation);
        portalData.globalPos1 = PortalPos.of(player.level.dimension(), portalLocation, portalRotation);
        portalData.portalEntityId1 = portalEntity.getUUID();
        playerMagicData.getPlayerRecasts().addRecast(new RecastInstance(getSpellId(), spellLevel, 2, getRecastDuration(spellLevel, player), castSource, portalData), playerMagicData);
    }
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    Vec3 targetLocation = null;
    if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData castTargetingData) {
        targetLocation = castTargetingData.getTargetPosition((ServerLevel) level);
    }
    if (targetLocation == null) {
        targetLocation = RaycastBuilder.begin(level, entity)
                .range(100)
                .checkForBlocks(true)
                .build()
                .getLocation();
    }
    Vec3 backward = new Vec3(targetLocation.x - entity.getX(), 0, targetLocation.z - entity.getZ()).normalize().scale(-4);
    //Vec3 spawnLocation = Utils.moveToRelativeGroundLevel(level, Utils.moveToRelativeGroundLevel(level, targetLocation, 6).add(backward), 1, 2);
    //spawnLocation = Utils.raycastForBlock(level, spawnLocation.add(0, 0.25, 0), spawnLocation.add(0, 6, 0), ClipContext.Fluid.NONE).getLocation().add(0, -1, 0);
    Vec3 raycastTarget = Utils.moveToRelativeGroundLevel(level, targetLocation.add(0, 2, 0), 4).add(backward).add(0, 6, 0);
    Vec3 spawnLocation = Utils.raycastForBlock(level, targetLocation, raycastTarget, ClipContext.Fluid.NONE).getLocation();
    spawnLocation = spawnLocation.subtract(targetLocation).scale(.9f).add(targetLocation);
    float dx = Mth.sqrt((float) ((spawnLocation.x - targetLocation.x) * (spawnLocation.x - targetLocation.x) + (spawnLocation.z - targetLocation.z) * (spawnLocation.z - targetLocation.z)));
    float arrowAngleX = dx == 0 ? 70 : (float) (Mth.atan2(dx, (spawnLocation.y - targetLocation.y)) * Mth.RAD_TO_DEG);
    float arrowAngleY = entity.getX() == targetLocation.x && entity.getZ() == targetLocation.z ? (entity.getYRot() - 90) * Mth.DEG_TO_RAD : Utils.getAngle(entity.getX(), entity.getZ(), targetLocation.x, targetLocation.z);

    ArrowVolleyEntity arrowVolleyEntity = new ArrowVolleyEntity(EntityRegistry.ARROW_VOLLEY_ENTITY.get(), level);
    arrowVolleyEntity.moveTo(spawnLocation);
    arrowVolleyEntity.setYRot(arrowAngleY * Mth.RAD_TO_DEG + 90);
    arrowVolleyEntity.setXRot(arrowAngleX + 25);
    arrowVolleyEntity.setDamage(getDamage(spellLevel, entity));
    arrowVolleyEntity.setArrowsPerRow(getArrowsPerRow(spellLevel, entity));
    arrowVolleyEntity.setRows(getRows(spellLevel, entity));
    arrowVolleyEntity.setOwner(entity);
    level.addFreshEntity(arrowVolleyEntity);

    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    var teleportData = (TeleportSpell.TeleportData) playerMagicData.getAdditionalCastData();

    FrozenHumanoid shadow = new FrozenHumanoid(level, entity);
    shadow.setShatterDamage(getDamage(spellLevel, entity));
    shadow.setDeathTimer(100);
    level.addFreshEntity(shadow);
    var tauntTarget = entity.getLastHurtByMob();
    Predicate<Entity> predicate = tauntTarget == null ? (mob -> entity instanceof Enemy ^ mob instanceof Enemy)
            : (mob -> mob.getClass().isAssignableFrom(tauntTarget.getClass()) || mob.isAlliedTo(tauntTarget) || entity instanceof Enemy ^ mob instanceof Enemy);
    Utils.performTaunt(shadow, 10, predicate);
    Vec3 dest = null;
    if (teleportData != null) {
        var potentialTarget = teleportData.getTeleportTargetPosition();
        dest = potentialTarget;
    }

    if (dest == null) {
        dest = findTeleportLocation(spellLevel, level, entity);
    }

    PacketDistributor.sendToPlayersTrackingEntityAndSelf(entity, new FrostStepParticlesPacket(entity.position(), dest));

    if (entity.isPassenger()) {
        entity.stopRiding();
    }
    Utils.handleSpellTeleport(this, entity, dest);
    entity.resetFallDistance();
    level.playSound(null, dest.x, dest.y, dest.z, getCastFinishSound().get(), SoundSource.NEUTRAL, 1f, 1f);

    playerMagicData.resetAdditionalCastData();

    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

private void handleStanceBreakSequence() {
    int tick = STANCE_BREAK_ANIM_TIME - stanceBreakTimer;
    if (stanceBreakCounter == 2) {
        // we will enter soul mode
        if (tick == 80) {
            this.setSoulMode(true);
            Vec3 vec3 = this.getBoundingBox().getCenter();
            MagicManager.spawnParticles(level, ParticleHelper.FIRE, vec3.x, vec3.y, vec3.z, 120, 0.3, 0.3, 0.3, 0.3, true);
            var speed = this.getAttribute(Attributes.MOVEMENT_SPEED);
            speed.removeModifier(SOUL_SPEED_MODIFIER);
            speed.addPermanentModifier(SOUL_SPEED_MODIFIER);
            var scale = this.getAttribute(Attributes.SCALE);
            scale.removeModifier(SOUL_SCALE_MODIFIER);
            scale.addPermanentModifier(SOUL_SCALE_MODIFIER);
            this.playSound(SoundRegistry.FIRE_BOSS_TRANSITION_SOUL.get(), 3, 1);
            upgradeScythe();
        } else if (tick < 80) {
            var f = Mth.lerp(tick / 80f, 0.2, 0.4);
            Vec3 vec3 = this.getBoundingBox().getCenter();
            MagicManager.spawnParticles(level, ParticleHelper.FIRE, vec3.x, vec3.y, vec3.z, 12 + (int) (f * 10), f, f, f, 0.02, true);
        }
    }
    if (tick >= STANCE_BREAK_BEGIN_SLAMS_TIMESTAMP) {
        if (tick == STANCE_BREAK_BEGIN_SLAMS_TIMESTAMP) {
            createEruptionEntity(8, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            playSound(SoundRegistry.FIRE_ERUPTION_SLAM.get(), 2, 1.2f);
        } else if (tick == STANCE_BREAK_BEGIN_SLAMS_TIMESTAMP + 25) {
            createEruptionEntity(11, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 2);
            playSound(SoundRegistry.FIRE_ERUPTION_SLAM.get(), 3, 1f);
        } else if (tick == STANCE_BREAK_BEGIN_SLAMS_TIMESTAMP + 50) {
            createEruptionEntity(15, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 3);
            playSound(SoundRegistry.FIRE_ERUPTION_SLAM.get(), 4, 0.9f);
        }
    }
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    entity.hasImpulse = true;
    float multiplier = (15 + getSpellPower(spellLevel, entity)) / 12f;

    //Direction for Mobs to cast in
    Vec3 forward = entity.getLookAngle();
    if (playerMagicData.getAdditionalCastData() instanceof BurningDashDirectionOverrideCastData) {
        if (Utils.random.nextBoolean())
            forward = forward.yRot(90);
        else
            forward = forward.yRot(-90);
    }

    //Create Dashing Movement Impulse
    var vec = forward.multiply(3, 1, 3).normalize().add(0, .25, 0).scale(multiplier);
    //Start Spin Attack
    if (entity.onGround()) {
        entity.setPos(entity.position().add(0, 1.5, 0));
        vec.add(0, 0.25, 0);
    }
    playerMagicData.setAdditionalCastData(new ImpulseCastData((float) vec.x, (float) vec.y, (float) vec.z, true));
    //entity.setDeltaMovement(entity.getDeltaMovement().add(vec));
    entity.setDeltaMovement(new Vec3(
            Mth.lerp(.75f, entity.getDeltaMovement().x, vec.x),
            Mth.lerp(.75f, entity.getDeltaMovement().y, vec.y),
            Mth.lerp(.75f, entity.getDeltaMovement().z, vec.z)
    ));


    entity.addEffect(new MobEffectInstance(MobEffectRegistry.BURNING_DASH, 15, getDamage(spellLevel, entity), false, false, false));
    entity.invulnerableTime = 20;
    //startSpinAttack(entity, 10);
    playerMagicData.getSyncedData().setSpinAttackType(SpinAttackType.FIRE);
    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

public static void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, int effectLevel, LivingEntity target) {
    if (!attacker.level().isClientSide) {
        int comboPoints = ComboPoints.get(attacker);
        boolean isSatiated = !attacker.getFoodData().needsFood();

        if (hand == InteractionHand.OFF_HAND && item.getEffectLevel(itemStack, ItemEffect.abilityDefensive) > 0) {
            performDefensive(attacker, item, itemStack, target);
        } else {
            performRegular(attacker, item, itemStack, damageMultiplier, effectLevel, target, isSatiated, comboPoints);
        }

        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 0.8f, 0.8f);

        boolean overextended = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend) > 0;
        attacker.causeFoodExhaustion(overextended ? 6f : 0.5f);
        attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack));

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            performEcho(attacker, item, itemStack, damageMultiplier, effectLevel, target, isSatiated, comboPoints);
        }
    }

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
    if (revengeLevel > 0) {
        RevengeTracker.removeEnemy(attacker, target);
    }

    attacker.swing(hand, false);
    item.tickProgression(attacker, itemStack, 2);
    item.applyDamage(2, itemStack, attacker);
}

private void renderSpellList(GuiGraphics guiHelper, float partialTick, int mouseX, int mouseY) {
    ItemStack inkStack = menu.getInkSlot().getItem();

    SpellRarity inkRarity = getRarityFromInk(inkStack.getItem());

    availableSpells.sort((a, b) -> SpellConfigManager.getSpellConfigValue(a.spell, SpellConfigParameter.MIN_RARITY).compareRarity(SpellConfigManager.getSpellConfigValue(b.spell, SpellConfigParameter.MIN_RARITY)));

    List<FormattedCharSequence> additionalTooltip = null;
    for (int i = 0; i < availableSpells.size(); i++) {
        SpellCardInfo spellCard = availableSpells.get(i);

        if (i - scrollOffset >= 0 && i - scrollOffset < 3) {
            if (inkRarity == null || spellCard.spell.getMinRarity() > inkRarity.getValue()) {
                spellCard.activityState = SpellCardInfo.ActivityState.INK_ERROR;
            } else if (minecraft != null && !spellCard.spell.canBeCraftedBy(minecraft.player)) {
                spellCard.activityState = SpellCardInfo.ActivityState.UNLEARNED_ERROR;
            } else {
                spellCard.activityState = SpellCardInfo.ActivityState.ENABLED;
            }
            int x = leftPos + SPELL_LIST_X;
            int y = topPos + SPELL_LIST_Y + (i - scrollOffset) * 19;
            spellCard.button.setX(x);
            spellCard.button.setY(y);
            spellCard.draw(this, guiHelper, x, y, mouseX, mouseY);
            if (additionalTooltip == null)
                additionalTooltip = spellCard.getTooltip(x, y, mouseX, mouseY);
        } else {
            spellCard.activityState = SpellCardInfo.ActivityState.DISABLED;
        }
        spellCard.button.active = spellCard.activityState == SpellCardInfo.ActivityState.ENABLED;
    }

    if (additionalTooltip != null) {
        guiHelper.renderTooltip(font, additionalTooltip, mouseX, mouseY);
    }
}

public void handleEquipmentChanges(CallbackInfoReturnable<Map<EquipmentSlot, ItemStack>> cir) {
    // Last hand items are accurate at this point
    // Mainhand assigning/removing is handled by minecraft. All we are doing is fudging offhand handling
    // The return of this function is a map of equipmentslots to itemstacks, of itemstacks who have been changed
    var changedEquipment = cir.getReturnValue();
    if (changedEquipment == null) {
        return;
    }
    LivingEntity self = (LivingEntity) (Object) this;
    ItemStack toStack = changedEquipment.get(EquipmentSlot.MAINHAND);
    if (toStack == null) {
        // If this stack was not changed, continue
        return;
    }
    ItemStack fromStack = getLastHandItem(EquipmentSlot.MAINHAND);
    ItemStack offhandStack = self.getOffhandItem();
    //offhand swap
    if (fromStack == offhandStack) {
        return;
    }
    //Do we even care
    if (!offhandStack.isEmpty() && offhandStack.has(ComponentRegistry.MULTIHAND_WEAPON)) {
        //did we equip a multihand item? (hide offhand)
        if (toStack.has(ComponentRegistry.MULTIHAND_WEAPON)) {
            if (!toStack.isEmpty()) {
                self.getAttributes().removeAttributeModifiers(filterApplicableAttributes(offhandStack.getAttributeModifiers()));
            }
        }
        //did we unequip a multihand item? (reveal offhand)
        else if (fromStack.has(ComponentRegistry.MULTIHAND_WEAPON)) {
            if (!offhandStack.isEmpty()) {
                self.getAttributes().addTransientAttributeModifiers(filterApplicableAttributes(offhandStack.getAttributeModifiers()));
            }
        }
    }
}

private void handleTelekinesis(ServerLevel world, LivingEntity entity, MagicData playerMagicData, float strength) {
    if (playerMagicData.getAdditionalCastData() instanceof TelekinesisData targetData) {
        var targetEntity = targetData.getTarget(world);
        if (targetEntity != null) {
            if ((targetEntity.isRemoved() || targetEntity.isDeadOrDying()) && entity instanceof ServerPlayer serverPlayer) {
                Utils.serverSideCancelCast(serverPlayer);
                return;
            }
            float resistance = Utils.clampedKnockbackResistanceFactor(entity, .2f, 1f);
            float lockedDistance = targetData.getDistance();
            float actualDistance = entity.distanceTo(targetEntity);
            float distance = Mth.lerp(actualDistance > lockedDistance ? .05f : .02f, lockedDistance, actualDistance);
            targetData.setDistance(distance);
            Vec3 force = (entity.getForward().normalize().scale(targetData.getDistance()).add(entity.position()).subtract(targetEntity.position())).scale(resistance * strength);
            Vec3 travel = new Vec3(targetEntity.getX() - targetEntity.xOld, targetEntity.getY() - targetEntity.yOld, targetEntity.getZ() - targetEntity.zOld);
            if (force.y > 0) {
                targetEntity.resetFallDistance();
            }
            if ((playerMagicData.getCastDurationRemaining()) % 10 == 0) {
                int airborne = (int) (travel.x * travel.x + travel.z * travel.z) / 2;
                targetEntity.addEffect(new MobEffectInstance(MobEffectRegistry.AIRBORNE, 31, airborne, false, false, true));
                targetEntity.addEffect(new MobEffectInstance(MobEffectRegistry.ANTIGRAVITY, 11, 0, false, false, true));
            }
            var deltaMovement = targetEntity.getDeltaMovement();
            var newMotion = force.subtract(deltaMovement).scale(0.25).add(deltaMovement);
            var delta = newMotion.subtract(deltaMovement);
            var clampedMotion = new Vec3(
                    Utils.signedMin(delta.x, force.x * 4),
                    Utils.signedMin(delta.y, force.y * 4),
                    Utils.signedMin(delta.z, force.z * 4)
            );
            targetEntity.setDeltaMovement(deltaMovement.add(clampedMotion));
            targetEntity.hurtMarked = true;
        }
    }
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    Vec3 dest = null;
    if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData castTargetingData) {
        LivingEntity target = castTargetingData.getTarget((ServerLevel) level);
        if (target != null) {
            dest = target.position();
        }
    }
    if (dest == null) {
        HitResult raycast = RaycastBuilder.begin(level, entity)
                .range(getRange(spellLevel, entity))
                .checkForBlocks(true)
                .bbInflation(0.35f)
                .build();
        if (raycast.getType() == HitResult.Type.ENTITY) {
            dest = ((EntityHitResult) raycast).getEntity().position();
        } else {
            dest = raycast.getLocation().subtract(entity.getForward().normalize());
        }
    }
    dest = Utils.moveToRelativeGroundLevel(level, dest, 6);
    Vec3 start = entity.position();
    float horizontalDist = (float) dest.subtract(start).horizontalDistance();
    int delay = Math.max(8, Math.min(40, Mth.ceil(horizontalDist * 1.5f))) * 2/ 3;

    FangSwirlEntity swirl = new FangSwirlEntity(EntityRegistry.FANG_SWIRL.get(), level);
    swirl.moveTo(dest.x, dest.y, dest.z);
    swirl.setStartPos(start);
    swirl.setDelay(delay);
    swirl.setRadius(getSwirlRadius(spellLevel, entity));
    swirl.setDuration(getSwirlDurationTicks(spellLevel, entity));
    swirl.setOwner(entity);
    swirl.setDamage(getDamage(spellLevel, entity));
    level.addFreshEntity(swirl);
    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public static void onPlayerTick(TickEvent.PlayerTickEvent event) {
    if (event.player.level().getGameTime() % 2 == 0) {
        if (hasApplicableItem(event.player) && event.player.isCrouching()) {
            Player player = event.player;
            int id = getIdentifier(player);
            Integer duration = cache.getIfPresent(id);
            boolean isDrawing = isDrawing(event.player);
            int change = isDrawing ? 1 : 2;
            cache.put(id, duration != null ? duration + change : change);

            if (!player.level().isClientSide) {
                int respiration = EnchantmentHelper.getRespiration(player);
                int amount = isDrawing ? 6 : 2;
                int reduction = 0;
                if (respiration > 0) {
                    for (int i = 0; i < amount - 1; i++) {
                        // slightly offset from how the vanilla calculations work
                        if (player.getRandom().nextInt(respiration + 2) > 1) {
                            reduction++;
                        }
                    }
                }
                player.setAirSupply(player.getAirSupply() - (amount - reduction));

                if (player.getAirSupply() <= -20) {
                    player.setAirSupply(0);

                    // todo 1.20: custom damage type for this
                    player.hurt(player.level().damageSources().drown(), 2.0F);
                }
            }

        } else {
            cache.invalidate(getIdentifier(event.player));
        }
    }
}

public static void applyHitEffects(ItemStack itemStack, LivingEntity target, LivingEntity attacker) {
    int bleedingLevel = getEffectLevel(itemStack, ItemEffect.bleeding);
    if (bleedingLevel > 0) {
        if (!MobType.UNDEAD.equals(target.getMobType()) && attacker.getRandom().nextFloat() < 0.3f) {
            target.addEffect(new MobEffectInstance(BleedingPotionEffect.instance, 40, bleedingLevel, false, false));
            BleedingPotionEffect.spawnParticles(target, 8);
        }
    }

    int severLevel = getEffectLevel(itemStack, ItemEffect.severing);
    if (severLevel > 0) {
        SeveringEffect.perform(itemStack, severLevel, attacker, target);
    }

    // todo: only trigger if target is standing on stone/earth/sand/gravel
    int earthbindLevel = getEffectLevel(itemStack, ItemEffect.earthbind);
    if (earthbindLevel > 0 && attacker.getRandom().nextFloat() < Math.max(0.1, 0.5 * (1 - target.getY() / 128))) {
        target.addEffect(new MobEffectInstance(EarthboundPotionEffect.instance, earthbindLevel * 20, 0, false, true));

        if (target.level() instanceof ServerLevel serverLevel) {
            BlockState blockState = serverLevel.getBlockState(BlockPos.containing(target.getX(), target.getY() - 1, target.getZ()));
            serverLevel.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, blockState),
                    target.getX(), target.getY() + 0.1, target.getZ(),
                    16, 0, serverLevel.random.nextGaussian() * 0.2, 0, 0.1);
        }
    }

    int stunLevel = getEffectLevel(itemStack, ItemEffect.stun);
    if (stunLevel > 0) {
        StunEffect.perform(itemStack, stunLevel, attacker, target);
    }

    DataEffectsHandler.applyOnHitEffects(itemStack, target, attacker);

    ApplyHitTargetEffectsEvent event = new ApplyHitTargetEffectsEvent(attacker, target, itemStack);
    MinecraftForge.EVENT_BUS.post(event);
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec,
        int chargedTicks) {
    if (!attacker.level().isClientSide) {
        int armorBefore = target.getArmorValue();
        int comboPoints = ComboPoints.get(attacker);
        boolean isSatiated = !attacker.getFoodData().needsFood();

        AbilityUseResult result;
        if (isDefensive(item, itemStack, hand)) {
            result = performDefensive(attacker, hand, item, itemStack, target);
        } else {
            result = performRegular(attacker, item, itemStack, target, chargedTicks, isSatiated, comboPoints);
        }

        boolean overextended = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend) > 0;
        attacker.causeFoodExhaustion(overextended ? 6f : 1f);

        // trigger no cooldown with the exhilaration mod if puncture brought the target's armor below 6
        if (!(item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration) > 0 && armorBefore >= 6 && target.getArmorValue() < 6)) {
            attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack) + target.getArmorValue() * 10);
        }

        item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            performEcho(attacker, item, itemStack, target, chargedTicks, isSatiated, comboPoints);
        }
    }

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    attacker.swing(hand, false);
    item.applyDamage(2, itemStack, attacker);
}

protected void doAction() {
    var target = mob.getTarget();
    if (target != null) {
        mob.playSound(SoundRegistry.FIERY_DAGGER_THROW.get(), 2f, Utils.random.nextIntBetweenInclusive(80, 110) * .01f);

        Vec3 start = mob.getEyePosition();
        Vec3 targetPos = target.position();
        Vec3 deltaAim = targetPos.subtract(start);
        // throw 3 daggers at 45 degree angles, centered around our target's postion
        for (int i = 0; i < 3; i++) {
            Vec3 aim = start.add(deltaAim.yRot(Mth.PI / 4 * (i - 1)));
            int delay = Utils.random.nextIntBetweenInclusive(10, 40);

            FieryDaggerEntity dagger = new FieryDaggerEntity(mob.level);
            dagger.setOwner(mob);
            dagger.setPos(start);
            dagger.delay = delay;
            dagger.setDamage((float) (mob.getAttributeValue(Attributes.ATTACK_DAMAGE) * .75));
            dagger.setExplosionRadius(4 + Utils.random.nextFloat() * 2);
            dagger.setNoGravity(false);

            Vec3 horizontal = aim.subtract(start).multiply(1, 0, 1);
            double horizontalSpeed = 1 * Mth.cos(Mth.PI * .25f) + 0.5; // + 0.5 for extra oomph
            double distance = horizontal.length();
            double ticks = distance / horizontalSpeed;

            // y(t) = -1/2(g)(t^2) + v0*t
            // => v0 = [y1 + 1/2(g)(t1^2)]/t1
            double y1 = aim.y - start.y;
            double g = dagger.getGravity();
            double verticalSpeed = (y1 + 0.5 * g * ticks * ticks) / ticks;
            Vec3 trajectory = horizontal.normalize().scale(horizontalSpeed).add(0, verticalSpeed, 0);
            dagger.setDeltaMovement(trajectory);
            mob.level.addFreshEntity(dagger);
        }
    }
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    Vec3 spawn = null;
    if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData castTargetingData) {
        var target = castTargetingData.getTarget((ServerLevel) world);
        if (target != null)
            spawn = target.position();
    }
    if (spawn == null) {
        spawn = RaycastBuilder.begin(world, entity)
                .range(32)
                .checkForBlocks(true)
                .bbInflation(.15f)
                .build()
                .getLocation();
        spawn = Utils.moveToRelativeGroundLevel(world, spawn, 6);
    }

    int duration = getDuration(spellLevel, entity);
    float radius = getRadius(spellLevel, entity);


    HealingAoe aoeEntity = new HealingAoe(world);
    aoeEntity.setOwner(entity);
    aoeEntity.setCircular();
    aoeEntity.setRadius(radius);
    aoeEntity.setDuration(duration);
    aoeEntity.setDamage(getHealing(spellLevel, entity));
    aoeEntity.setPos(spawn);
    world.addFreshEntity(aoeEntity);

    TargetedAreaEntity visualEntity = TargetedAreaEntity.createTargetAreaEntity(world, spawn, radius, 0xc80000);
    visualEntity.setDuration(duration);
    visualEntity.setOwner(aoeEntity);
    visualEntity.setShouldFade(true);

    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

private void applyConsumeEffect() {
    Direction facing = getLevel().getBlockState(getBlockPos()).getValue(HammerBaseBlock.facingProp);
    Vec3 pos = Vec3.atCenterOf(getBlockPos());

    Vec3 oppositePos = pos.add(Vec3.atLowerCornerOf(facing.getOpposite().getNormal()).scale(0.55));
    pos = pos.add(Vec3.atLowerCornerOf(facing.getNormal()).scale(0.55));

    if (hasEffect(HammerEffect.power)) {
        spawnParticle(ParticleTypes.ENCHANTED_HIT, Vec3.atLowerCornerOf(getBlockPos()).add(0.5, -0.9, 0.5), 15, 0.1f);
    }

    if (hasEffect(HammerEffect.power)) {
        spawnParticle(ParticleTypes.WHITE_ASH, Vec3.atLowerCornerOf(getBlockPos()).add(0.5, -0.9, 0.5), 15, 0.1f);
        int count = level.random.nextInt(2 + getEffectLevel(HammerEffect.power) * 4);

        if (count > 2) {
            // particles cell 1
            spawnParticle(ParticleTypes.LAVA, pos, 2, 0.06f);
            spawnParticle(ParticleTypes.LARGE_SMOKE, pos, 2, 0f);

            // particles cell 2
            spawnParticle(ParticleTypes.LAVA, oppositePos, 2, 0.06f);
            spawnParticle(ParticleTypes.LARGE_SMOKE, oppositePos, 2, 0f);

            CombustingEffect.igniteBlocksAround(level, getBlockPos(), 3, count, true, false);
        }
    }

    if (level.random.nextFloat() < getJamChance()) {
        TileEntityOptional.from(level, getBlockPos().below(), HammerHeadBlockEntity.class).ifPresent(head -> {
            head.setJammed(true);

            level.getEntitiesOfClass(ServerPlayer.class, new AABB(getBlockPos()).inflate(10, 5, 10))
                    .forEach(player -> BlockUseCriterion.trigger(player, head.getBlockState(), ItemStack.EMPTY, ImmutableMap.<String, String>builder().put("jammed", "true").build()));
        });
        level.playSound(null, getBlockPos(), SoundEvents.GRINDSTONE_USE, SoundSource.BLOCKS, 0.8f, 0.5f);
    }
}

public static boolean causeEffect(Player breakingPlayer, ItemStack itemStack, ItemModularHandheld item, Level world, BlockPos pos, BlockState blockState) {
    int strikingLevel = 0;
    ToolAction tool = null;

    if (breakingPlayer.hasEffect(MobEffects.DIG_SLOWDOWN)) {
        return false;
    }

    // essentially checks if the item is effective for each tool type, and checks if it can strike for that type
    for (Pair<ItemEffect, ToolAction> entry : effectActionMap) {
        if (ToolActionHelper.isEffectiveOn(entry.getRight(), blockState)) {
            strikingLevel = EffectHelper.getEffectLevel(itemStack, entry.getLeft());
            if (strikingLevel > 0) {
                tool = entry.getRight();
                break;
            }
        }
    }

    if (strikingLevel > 0) {
        if (breakingPlayer.getAttackStrengthScale(0) > 0.9 && blockState.getDestroySpeed(world, pos) != -1) {
            if (EffectHelper.getEffectLevel(itemStack, ItemEffect.sweepingStrike) > 0) {
                SweepingStrikeEffect.causeEffect(world, breakingPlayer, itemStack, pos, tool);
            } else {
                if (ToolActionHelper.playerCanDestroyBlock(breakingPlayer, blockState, pos, itemStack)) {
                    EffectHelper.breakBlock(world, breakingPlayer, itemStack, pos, blockState, true, false);

                    item.applyUsageEffects(breakingPlayer, itemStack, 1);
                    item.applyDamage(item.getBlockDestroyDamage(), itemStack, breakingPlayer);
                }
            }
        }
        breakingPlayer.resetAttackStrengthTicker();
        return true;
    }

    return false;
}

public static void sweepAttack(ItemStack itemStack, LivingEntity target, LivingEntity attacker, int sweepingLevel) {
    boolean trueSweep = EffectHelper.getEffectLevel(itemStack, ItemEffect.truesweep) > 0;
    float damage = (float) Math.max(attacker.getAttributeValue(Attributes.ATTACK_DAMAGE) * (sweepingLevel * 0.125f), 1);
    float knockback = trueSweep ? (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack) + 1) * 0.5f : 0.5f;
    double range = 1 + EffectHelper.getEffectEfficiency(itemStack, ItemEffect.sweeping);
    double reach = attacker.getAttributeValue(ForgeMod.ENTITY_REACH.get());

    // range values set up to mimic vanilla behaviour
    attacker.level().getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(range, 0.25d, range)).stream()
            .filter(entity -> entity != attacker)
            .filter(entity -> entity != target)
            .filter(entity -> !attacker.isAlliedTo(entity))
            .filter(entity -> attacker.distanceToSqr(entity) < (range + reach) * (range + reach))
            .forEach(entity -> {
                entity.knockback(knockback,
                        Mth.sin(attacker.getYRot() * (float) Math.PI / 180F),
                        -Mth.cos(attacker.getYRot() * (float) Math.PI / 180F));

                DamageSource damageSource = attacker instanceof Player
                        ? attacker.damageSources().playerAttack((Player) attacker)
                        : attacker.damageSources().mobAttack(attacker);

                if (trueSweep) {
                    ItemEffectHandler.applyHitEffects(itemStack, entity, attacker);
                    EffectHelper.applyEnchantmentHitEffects(itemStack, entity, attacker);

                    causeTruesweepDamage(damageSource, damage, itemStack, attacker, entity);
                } else {
                    entity.hurt(damageSource, damage);
                }

            });

    attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
            SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

    CastOptional.cast(attacker, Player.class).ifPresent(Player::sweepAttack);
}

public static void truesweep(ItemStack itemStack, LivingEntity attacker, boolean triggerVfx) {
    int sweepingLevel = getSweepingLevel(itemStack);
    float damage = (float) Math.max(attacker.getAttributeValue(Attributes.ATTACK_DAMAGE) * (sweepingLevel * 0.125f), 1);
    float knockback = 0.5f + EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack) * 0.5f;
    double range = 2 + EffectHelper.getEffectEfficiency(itemStack, ItemEffect.sweeping);

    Vec3 target = Vec3.directionFromRotation(attacker.getXRot(), attacker.getYRot())
            .normalize()
            .scale(range)
            .add(attacker.getEyePosition(0));
    AABB aoe = new AABB(target, target);

    // range values set up to mimic vanilla behaviour
    attacker.level().getEntitiesOfClass(LivingEntity.class, aoe.inflate(range, 1d, range)).stream()
            .filter(entity -> entity != attacker)
            .filter(entity -> !attacker.isAlliedTo(entity))
            .forEach(entity -> {
                entity.knockback(knockback,
                        Mth.sin(attacker.getYRot() * (float) Math.PI / 180F),
                        -Mth.cos(attacker.getXRot() * (float) Math.PI / 180F));

                ItemEffectHandler.applyHitEffects(itemStack, entity, attacker);
                EffectHelper.applyEnchantmentHitEffects(itemStack, entity, attacker);


                DamageSource damageSource = attacker instanceof Player
                        ? attacker.damageSources().playerAttack((Player) attacker)
                        : attacker.damageSources().mobAttack(attacker);
                causeTruesweepDamage(damageSource, damage, itemStack, attacker, entity);
            });

    if (triggerVfx) {
        attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
                SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

        CastOptional.cast(attacker, Player.class).ifPresent(Player::sweepAttack);
    }
}

protected void handleAttackLogic(double distanceSquared) {
    var meleeRange = meleeRange();
    if (fireballcooldown > 0) {
        // poor man's way to clean up the fireball attribute
        if (fireballcooldown == 20 * 10 - 20) {
            mob.getAttribute(AttributeRegistry.CAST_TIME_REDUCTION).removeModifier(MODIFIER_FIRE_BALLER);
        }
        fireballcooldown--;
    } else {
        // if we are very ranged (and preferably high in the sky) launch down a fireball
        if (!mob.onGround() && distanceSquared > meleeRange * meleeRange * 2 * 2) {
            if (!isActing()) {
                // insta-cast that fireball
                mob.getAttribute(AttributeRegistry.CAST_TIME_REDUCTION).addOrUpdateTransientModifier(MODIFIER_FIRE_BALLER);
                mob.initiateCastSpell(SpellRegistry.FIREBALL_SPELL.get(), mob.isSoulMode() ? 6 : 5);
                fireballcooldown = 20 * 10;
                return;
            }
        }
    }
    if (meleeAnimTimer > 0 && currentAttack != null) {
        // in order to make more seamless animation -> action transitions, we cut our ai pause short if we have encountered our last frame
        // the animation still plays out, creating a smoother overall transition
        int shortcut = 5;
        if (meleeAnimTimer < shortcut) {
            if (currentAttack.attacks.keySet().intStream().noneMatch(i -> i > currentAttack.lengthInTicks - shortcut)) {
                meleeAnimTimer = 0;
            }
        }
    }
    // delay attacking while the dagger is active (primarily to let parries play out)
    // or sometimes if we are midair (reduce, but not remove, ariel attacks)
    boolean delayNextAttack = mob.spectralDaggerActive() || (!mob.onGround() && mob.getRandom().nextBoolean());
    if (delayNextAttack) {
        meleeAttackDelay++;
    }
    super.handleAttackLogic(distanceSquared);
}

protected void doAction() {
    var primaryTarget = mob.getTarget();
    if (primaryTarget != null) {
        var type = primaryTarget.getClass();
        var targets = mob.level.getEntitiesOfClass(type, mob.getBoundingBox().inflate(32));
        Vec3 start = mob.getEyePosition();
        int radius = Math.max(4, 7 - (targets.size() - 1));
        for (Entity target : targets) {
            mob.playSound(SoundRegistry.FIERY_DAGGER_THROW.get(), 2f, Utils.random.nextIntBetweenInclusive(80, 110) * .01f);

            Vec3 targetPos = target.position();
            Vec3 deltaAim = targetPos.subtract(start);
            Vec3 aim = start.add(deltaAim);

            FieryDaggerEntity dagger = new FieryDaggerEntity(mob.level);
            dagger.setOwner(mob);
            dagger.setPos(start);
            dagger.delay = 0;
            dagger.setDamage((float) (mob.getAttributeValue(Attributes.ATTACK_DAMAGE) * .75));
            dagger.setExplosionRadius(radius);
            dagger.setNoGravity(false);

            Vec3 horizontal = aim.subtract(start).multiply(1, 0, 1);
            double horizontalSpeed = 1 * Mth.cos(Mth.PI * .25f) + 1.25;
            double distance = horizontal.length();
            double ticks = distance / horizontalSpeed;

            // y(t) = -1/2(g)(t^2) + v0*t
            // => v0 = [y1 + 1/2(g)(t1^2)]/t1
            double y1 = aim.y - start.y;
            double g = dagger.getGravity();
            double verticalSpeed = (y1 + 0.5 * g * ticks * ticks) / ticks;
            Vec3 trajectory = horizontal.normalize().scale(horizontalSpeed).add(0, verticalSpeed, 0);
            dagger.setDeltaMovement(trajectory);
            mob.level.addFreshEntity(dagger);
        }
    }
}

public void onPotionApplicableCharms(MobEffectEvent.Applicable event) {
  if (inPotionAddedHandler) {
    return;
  }
  if (!(event.getEntity() instanceof Player ply)) {
    return;
  }
  MobEffectInstance inst = event.getEffectInstance();
  ItemStack antiPotion = CharmUtil.getIfEnabled(ply, ItemRegistry.CHARM_ANTIPOTION.get());
  if (!antiPotion.isEmpty()) {
    event.setResult(MobEffectEvent.Applicable.Result.DO_NOT_APPLY);
    ItemStackUtil.damageItem(ply, antiPotion);
    return;
  }
  boolean makeInvisible = false;
  int durationBoost = 0;
  ItemStack stealthStack = CharmUtil.getIfEnabled(ply, ItemRegistry.CHARM_STEALTHPOTION.get());
  if (!stealthStack.isEmpty()) {
    makeInvisible = true;
  }
  ItemStack boostStack = CharmUtil.getIfEnabled(ply, ItemRegistry.CHARM_BOOSTPOTION.get());
  if (!boostStack.isEmpty()) {
    durationBoost = inst.getDuration() / 2;
  }
  if (makeInvisible || durationBoost > 0) {
    event.setResult(MobEffectEvent.Applicable.Result.DO_NOT_APPLY);
    inPotionAddedHandler = true;
    try {
      boolean visible = !makeInvisible && inst.isVisible();
      int duration = inst.getDuration() + durationBoost;
      ply.addEffect(new MobEffectInstance(inst.getEffect(), duration, inst.getAmplifier(), inst.isAmbient(), visible, inst.showIcon()));
      if (durationBoost > 0) {
        ItemStackUtil.damageItem(ply, boostStack);
      }
    } finally {
      inPotionAddedHandler = false;
    }
  }
}

public void checkForEntitiesToTeleport() {
    if (this.level.isClientSide) return;
    level.getEntities((Entity) null, this.getBoundingBox(), (entity -> !entity.getType().is(ModTags.CANT_USE_PORTAL) && (entity.isPickable() || entity instanceof Projectile) && !entity.isVehicle() && !entity.isSpectator())).forEach(entity -> {
        //IronsSpellbooks.LOGGER.debug("PortalEntity: entity near portal:{}, portal:{}", entity, uuid);

        PortalManager.INSTANCE.processDelayCooldown(uuid, entity.getUUID(), 1);

        if (PortalManager.INSTANCE.canUsePortal(this, entity)) {
            //IronsSpellbooks.LOGGER.debug("PortalEntity: teleport entity:{} portal:{}", entity, uuid);

            PortalManager.INSTANCE.addPortalCooldown(entity, uuid);

            var portalData = PortalManager.INSTANCE.getPortalData(this);
            portalData.getConnectedPortalPos(uuid).ifPresent(portalPos -> {
                Vec3 destination = portalPos.pos().add(0, entity.getY() - this.getY(), 0);
                entity.setYRot(portalPos.rotation());
                this.level.playSound(null, this.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.NEUTRAL, 1f, 1f);
                if (level.dimension().equals(portalPos.dimension())) {
                    entity.teleportTo(destination.x, destination.y + .1, destination.z);
                    var delta = entity.getDeltaMovement();
                    float hspeed = (float) Math.sqrt(delta.x * delta.x + delta.z * delta.z);
                    float f = portalPos.rotation() * Mth.DEG_TO_RAD;
                    entity.setDeltaMovement(-Mth.sin(f) * hspeed, delta.y, Mth.cos(f) * hspeed);
                    handleLoopTracking(entity);
                } else {
                    //IronsSpellbooks.LOGGER.debug("PortalEntity: teleport entity:{} to dimension: {}", entity, portalPos.dimension());
                    var server = level.getServer();
                    if (server != null) {
                        var dim = server.getLevel(portalPos.dimension());
                        if (dim != null) {
                            entity.changeDimension(new DimensionTransition(dim, destination, Vec3.ZERO, entity.getYRot(), entity.getXRot(), DimensionTransition.DO_NOTHING));
                        }
                    }
                }
                this.level.playSound(null, destination.x, destination.y, destination.z, SoundEvents.ENDERMAN_TELEPORT, SoundSource.NEUTRAL, 1f, 1f);
            });
        }
    });
}

private static void groundSlamEntity(Player attacker, LivingEntity target, ItemModularHandheld item, ItemStack itemStack, Vec3 origin,
        double damageMultiplier, int slowDuration, double momentumEfficiency, int revengeLevel) {
    ServerScheduler.schedule(target.blockPosition().distManhattan(BlockPos.containing(origin)) - 3, () -> {
        float knockback = momentumEfficiency > 0 ? 0.1f : 0.5f;

        AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockback, knockback);

        if (momentumEfficiency > 0) {
            target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.GENERIC_BIG_FALL, SoundSource.PLAYERS, 1, 0.7f);
        } else {
            target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.9f);
        }

        if (result != AbilityUseResult.fail) {
            if (slowDuration > 0) {
                target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, slowDuration, 1, false, true));
            }

            if (momentumEfficiency > 0) {
                double velocity = momentumEfficiency;
                velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                target.push(0, velocity, 0);
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, 40, 0, false, false));
            }

            if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
                RevengeTracker.removeEnemySynced((ServerPlayer) attacker, target);
            }
        }

        if (result == AbilityUseResult.crit) {
            RandomSource rand = target.getRandom();
            CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                    world.sendParticles(ParticleTypes.CRIT,
                            target.getX(), target.getY(), target.getZ(), 10,
                            rand.nextGaussian() * 0.3, rand.nextGaussian() * 0.5, rand.nextGaussian() * 0.3, 0.1f));
        }
    });
}

public StructureTemplate.StructureBlockInfo process(LevelReader world, BlockPos pos, BlockPos pos2, StructureTemplate.StructureBlockInfo $,
        StructureTemplate.StructureBlockInfo blockInfo, StructurePlaceSettings placementSettings, @Nullable StructureTemplate template) {
    if (blockInfo.state().getBlock() instanceof HammerBaseBlock) {
        RandomSource random = placementSettings.getRandom(blockInfo.pos());
        CompoundTag newCompound = blockInfo.nbt().copy();

        // randomize cells
        ItemStack cell1 = random.nextBoolean() ? new ItemStack(ThermalCellItem.instance.get()) : null;
        ItemStack cell2 = random.nextBoolean() ? new ItemStack(ThermalCellItem.instance.get()) : null;

        int charge1 = random.nextInt(ThermalCellItem.maxCharge);
        if (cell1 != null) {
            ThermalCellItem.recharge(cell1, charge1);
        }

        int charge2 = ThermalCellItem.maxCharge - random.nextInt(Math.max(charge1, 1));
        if (cell2 != null) {
            ThermalCellItem.recharge(cell2, charge2);
        }

        HammerBaseBlockEntity.writeCells(newCompound, cell1, cell2);

        HammerEffect module = HammerEffect.efficient;
        if (random.nextFloat() < 0.1) {
            module = HammerEffect.reliable;
        } else if (random.nextFloat() < 0.1) {
            module = random.nextBoolean() ? HammerEffect.precise : HammerEffect.power;
        }

        if (random.nextBoolean()) {
            HammerBaseBlockEntity.writeModules(newCompound, module, null);
        } else {
            HammerBaseBlockEntity.writeModules(newCompound, null, module);
        }


        return new StructureTemplate.StructureBlockInfo(blockInfo.pos(), blockInfo.state(), newCompound);
    }
    return blockInfo;
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, BlockPos targetPos, Vec3 hitVec, int chargedTicks) {
    if (!attacker.level().isClientSide) {
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int slowDuration = isDefensive(item, itemStack, hand) ? (int) (item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) * 20) : 0;
        double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
        double overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);

        double range = getAoeRange(attacker, item, itemStack, overchargeBonus);

        Vec3 direction = hitVec.subtract(attacker.position()).multiply(1, 0, 1).normalize();
        double yaw = Mth.atan2(direction.x, direction.z);
        AABB boundingBox = new AABB(hitVec, hitVec).inflate(range + 1, 4, range + 1).move(direction.scale(range / 2));
        List<LivingEntity> targets = attacker.level().getEntitiesOfClass(LivingEntity.class, boundingBox).stream()
                .filter(Entity::isAlive)
                .filter(Entity::isAttackable)
                .filter(entity -> !attacker.equals(entity))
                .filter(entity -> inRange(hitVec, entity, yaw, range))
                .collect(Collectors.toList());

        double damageMultiplier = getAoeDamageMultiplier(attacker, item, itemStack, slowDuration > 0, overchargeBonus, targets);

        targets.forEach(entity -> groundSlamEntity(attacker, entity, item, itemStack, hitVec, damageMultiplier, slowDuration, momentumEfficiency, revengeLevel));

        spawnGroundParticles(attacker.level(), hitVec, direction, yaw, range);

        attacker.causeFoodExhaustion(overextendLevel > 0 ? 6 : 1);

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            echoGround(attacker, item, itemStack, hitVec, direction, yaw, range, damageMultiplier * echoLevel / 100d, slowDuration,
                    momentumEfficiency, revengeLevel);
        }
    }

    attacker.swing(hand, false);
    attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack));

    item.tickProgression(attacker, itemStack, 2);
    item.applyDamage(2, itemStack, attacker);
}

public void onShieldDamage(ShieldBlockEvent event) {
    DamageSource source = event.getDamageSource();

    LivingEntity entity = event.getEntity();
    Item item = entity.getUseItem().getItem();
    Entity directEntity = source.getDirectEntity();
    if (source.is(CMDamageTypes.MALEDICTIO_SAGITTA)) {
        event.setShieldTakesDamage(false);
    }


    ParryCapability.IParryCapability ParryCapability = ModCapabilities.getCapability(event.getEntity(), ModCapabilities.PARRY_CAPABILITY);

    if (item == ModItems.BULWARK_OF_THE_FLAME.get()) {
        if (ParryCapability != null) {
            if (ParryCapability.getParryFrame() < 13) {
                if (directEntity instanceof LivingEntity livingEntity) {
                    livingEntity.setSecondsOnFire(3);
                    livingEntity.playSound(SoundEvents.ANVIL_LAND, 0.8f, 1.3F);
                    MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTBLAZING_BRAND.get(), 100, 0);
                    livingEntity.knockback(0.5F, entity.getX() - livingEntity.getX(), entity.getZ() - livingEntity.getZ());
                    livingEntity.addEffect(effectinstance);
                }
            }
        }
    }
    if (item == ModItems.AZURE_SEA_SHIELD.get()) {
        if (ParryCapability != null) {
            if (ParryCapability.getParryFrame() < 10) {
                if (directEntity instanceof LivingEntity livingEntity) {
                    livingEntity.playSound(ModSounds.PARRY.get(), 0.4f, 1.0F);
                    entity.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 60, 1));
                    MobEffectInstance effectinstance = new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 60, 1);
                    livingEntity.knockback(0.5F, entity.getX() - livingEntity.getX(), entity.getZ() - livingEntity.getZ());
                    livingEntity.addEffect(effectinstance);
                }
            }
        }
    }

}

public boolean setTeleportLocationBehindTarget(int distance) {
    var target = getTarget();
    boolean valid = false;
    if (target != null) {
        var rotation = target.getLookAngle().normalize().scale(-distance);
        var pos = target.position();
        var teleportPos = rotation.add(pos);

        for (int i = 0; i < 24; i++) {
            Vec3 randomness = Utils.getRandomVec3(.15f * i).multiply(1, 0, 1);
            teleportPos = Utils.moveToRelativeGroundLevel(level, target.position().subtract(new Vec3(0, 0, distance / (float) (i / 7 + 1)).yRot(-(target.getYRot() + i * 45) * Mth.DEG_TO_RAD)).add(randomness), 5);
            teleportPos = new Vec3(teleportPos.x, teleportPos.y + .1f, teleportPos.z);
            var reposBB = this.getBoundingBox().move(teleportPos.subtract(this.position()));
            //IronsSpellbooks.LOGGER.debug("setTeleportLocationBehindTarget attempt to teleport to {}:", reposBB.getCenter());
            if (!level.collidesWithSuffocatingBlock(this, reposBB.inflate(-.05f))) {
                //IronsSpellbooks.LOGGER.debug("\n\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nsetTeleportLocationBehindTarget: {} {} {} empty. teleporting\n\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\n", reposBB.minX, reposBB.minY, reposBB.minZ);
                valid = true;
                break;
            }
            //IronsSpellbooks.LOGGER.debug("fail");

        }
        if (valid) {
            if (Log.SPELL_DEBUG) {
                //IronsSpellbooks.LOGGER.debug("ASCM.setTeleportLocationBehindTarget: valid, pos:{}, isClient:{}", teleportPos, level.isClientSide());
            }
            playerMagicData.setAdditionalCastData(new TeleportSpell.TeleportData(teleportPos));
        } else {
            if (Log.SPELL_DEBUG) {
                //IronsSpellbooks.LOGGER.debug("ASCM.setTeleportLocationBehindTarget: invalid, pos:{}, isClient:{}", teleportPos, level.isClientSide());
            }
            playerMagicData.setAdditionalCastData(new TeleportSpell.TeleportData(this.position()));

        }
    } else {
        if (Log.SPELL_DEBUG) {
            //IronsSpellbooks.LOGGER.debug("ASCM.setTeleportLocationBehindTarget: no target, isClient:{}", level.isClientSide());
        }
        playerMagicData.setAdditionalCastData(new TeleportSpell.TeleportData(this.position()));
    }
    return valid;
}

public void start() {
    Level level = mob.level;
    Entity target = mob.getTarget();
    if (target == null) {
        // should be impossible
        return;
    }
    List<? extends Entity> otherTargets = level.getEntitiesOfClass(target.getClass(), mob.getBoundingBox().inflate(20, 10, 20), entity -> !entity.isSpectator() && Utils.hasLineOfSight(level, mob, entity, false));
    if (!otherTargets.isEmpty()) {
        target = otherTargets.get(mob.getRandom().nextInt(otherTargets.size()));
    }

    int summonCount = 5 + (int) Mth.lerp(1 - mob.getHealth() / mob.getMaxHealth(), 0, 5 + 1);
    int delay = 20;
    this.cooldown = summonCount * delay * 2;

    UndeadRiftEntity rift = new UndeadRiftEntity(level);
    SummonManager.setOwner(rift, mob);
    rift.setDelay(delay);
    rift.setSummonsToSpawn(summonCount);
    Vec3 dir = new Vec3(0, 0, 1).yRot(
            (-target.getYRot() - 90 + mob.getRandom().nextInt(180)) * Mth.DEG_TO_RAD
    ).add(0, -.2, 0).normalize();
    Vec3 targetPos = level.clip(new ClipContext(
            target.getBoundingBox().getCenter(), target.getBoundingBox().getCenter().add(dir.scale(4.5 + target.getBbWidth())),
            ClipContext.Block.COLLIDER, ClipContext.Fluid.ANY, CollisionContext.empty())).getLocation();
    targetPos = Utils.moveToRelativeGroundLevel(level, targetPos.subtract(dir), 3, 10);
    rift.moveTo(targetPos);
    Utils.fudgeNoCollision(level, rift);
    rift.setYRot(Utils.getAngle(targetPos.x, targetPos.z, target.getX(), target.getZ()) * Mth.RAD_TO_DEG + 90);
    rift.setForcedTarget((LivingEntity) target); // safe cast because the entities of class must extend living entity by proxy of getTarget returning a living entity
    level.addFreshEntity(rift);
    MagicManager.spawnParticles(level, ParticleTypes.LARGE_SMOKE, targetPos.x, targetPos.y + 1, targetPos.z, 50, 0.1, 0.3, 0.1, 0.1, false);
    level.playSound(null, targetPos.x, targetPos.y, targetPos.z, SoundEvents.TRIAL_SPAWNER_SPAWN_MOB, SoundSource.HOSTILE, 2f, 1.0f);
    level.playSound(null, targetPos.x, targetPos.y, targetPos.z, SoundEvents.VEX_AMBIENT, SoundSource.HOSTILE, 2f, 0.75f);
    if (twinPortal) {
        twinPortal = false;
    } else if (mob.getRandom().nextFloat() < .2f) {
        twinPortal = true;
        cooldown = 10;
    }
}

public void render(OminousFireOrbEntity entity, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight) {
    super.render(entity, entityYaw, partialTick, poseStack, bufferSource, packedLight);
    float f = entity.tickCount + partialTick;

    int fuse = entity.getFuse();
    int chargeTime = entity.getChargeTime();

    float fuseProgress = entity.getFuseProgressTicks() + partialTick;
    float fusePercent = fuse > 0 ? Mth.clamp(fuseProgress / fuse, 0f, 1f) : 0f;
    float chargePercent = chargeTime > 0 ? Mth.clamp(f / chargeTime, 0, 1f) : 0f;

    poseStack.pushPose();
    float scale = fuse > 0 ? Mth.lerp(fusePercent, 1f, 1.85f) : 1f;
    poseStack.translate(0, 2 + Mth.sin(f * .2f) * .1f, 0);
    poseStack.scale(scale, scale, scale);
    poseStack.scale(1.2f, 1.2f, 1.2f);
    float swirlX = Mth.cos(.08f * f) * 180;
    float swirlY = Mth.sin(.08f * f) * 180;
    float swirlZ = Mth.cos(.08f * f + 5464) * 180;
    poseStack.mulPose(Axis.XP.rotationDegrees(swirlX));
    poseStack.mulPose(Axis.YP.rotationDegrees(swirlY));
    poseStack.mulPose(Axis.ZP.rotationDegrees(swirlZ));

    if (entity.getFuseProgressTicks() > 0) {
        VertexConsumer consumer = bufferSource.getBuffer(RenderType.entityCutoutNoCull(BASE_TEXTURE));
        fireball.render(poseStack, consumer, LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, -1);
    }
    if (fuse > 0 || chargeTime > 0) {
        float percent = entity.tickCount >= chargeTime ? fusePercent : 1f - chargePercent;
        float intensity = Mth.lerp(percent, .5f, 1.25f);
        float outlineScale = Mth.lerp(percent, 0.8f, 2.5f) + Mth.sin(f * intensity) * .4f * intensity;
        poseStack.scale(outlineScale, outlineScale, outlineScale);
        VertexConsumer consumer = bufferSource.getBuffer(RenderType.entityCutoutNoCull(getSwirlTextureLocation(entity)));
        poseStack.mulPose(Axis.XP.rotationDegrees(swirlX));
        poseStack.mulPose(Axis.YP.rotationDegrees(swirlY));
        poseStack.mulPose(Axis.ZP.rotationDegrees(swirlZ));

        outline.render(poseStack, consumer, LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, -1);
    }
    poseStack.popPose();

}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {

    entity.addEffect(new MobEffectInstance(MobEffectRegistry.ASCENSION, 80, 0, false, false, true));

    Vec3 vec = entity.position();
    for (int i = 0; i < 32; i++) {
        if (!level.getBlockState(BlockPos.containing(vec).below()).isAir())
            break;
        vec = vec.subtract(0, 1, 0);
    }
    Vec3 strikePos = vec;

    LightningBolt lightningBolt = EntityType.LIGHTNING_BOLT.create(level);
    lightningBolt.setVisualOnly(true);
    lightningBolt.setDamage(0);
    lightningBolt.setPos(strikePos);
    level.addFreshEntity(lightningBolt);

    //livingEntity.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 100));
    float radius = 5;
    level.getEntities(entity, entity.getBoundingBox().inflate(radius)).forEach(target -> {
        double distance = target.distanceToSqr(strikePos);
        if (distance < radius * radius) {
            float finalDamage = (float) (getDamage(spellLevel, entity) * (1 - distance / (radius * radius)));
            DamageSources.applyDamage(target, finalDamage, getDamageSource(lightningBolt, entity));
            if (target instanceof Creeper creeper) {
                creeper.thunderHit((ServerLevel) level, lightningBolt);
            }
            if (target instanceof LivingEntity livingEntity) {
                livingEntity.knockback(0.25f + finalDamage / 10f, entity.getX() - livingEntity.getX(), entity.getZ() - livingEntity.getZ());
            }
        }
    });

    Vec3 motion = entity.getLookAngle().multiply(1, 0, 1).normalize().add(0, 5, 0).scale(.125);
    playerMagicData.setAdditionalCastData(new ImpulseCastData((float) motion.x, (float) motion.y, (float) motion.z, true));
    entity.setDeltaMovement(entity.getDeltaMovement().add(motion));
    entity.hasImpulse = true;


    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public void tick(LivingEntity entity) {
    if(isRush()) {
        int standingOnY = Mth.floor(entity.getY()) - 3;
        double headY = entity.getY() + 2.0D;
        float yawRadians = (float) (Math.toRadians(90 + entity.getYRot()));
        int temp = getTimer();

            setTimer(temp - 1);
            //Deal with rocket punch is valid
            if (temp > 0) {
                double yaw = Math.toRadians(entity.getYRot() + 90);
                double xExpand = 3 * Math.cos(yaw);
                double zExpand = 3 * Math.sin(yaw);
                AABB attackRange = entity.getBoundingBox().expandTowards(xExpand, 0, zExpand);
                for (LivingEntity target : entity.level().getEntitiesOfClass(LivingEntity.class, attackRange)) {
                    if (!target.isAlliedTo(entity) && target != entity) {
                        target.hurt(entity.damageSources().mobAttack(entity), getdamage());

                    }
                }


                if(temp % 2 ==0){
                    this.spawnFangs(entity.getX(), headY, entity.getZ(), standingOnY, yawRadians, 1, entity.level(), entity);
                    double x = entity.getX();
                    double y = entity.getY() + entity.getBbHeight() / 2;
                    double z = entity.getZ();
                    float yaw2 = (float) Math.toRadians(-entity.getYRot());
                    float yaw3 = (float) Math.toRadians(-entity.getYRot() + 180);
                    entity.level().addParticle(new RingParticleOptions(yaw2, 0, 20, 86, 236, 204, 1.0f, 30f, false, 2), x, y, z, 0, 0, 0);

                    entity.level().addParticle(new RingParticleOptions(yaw3, 0, 20, 86, 236, 204, 1.0f, 30f, false, 2), x, y, z, 0, 0, 0);

                }
            }

            if (temp == 0) {
                setRush(false);

        }
    }
}

public void tick() {
  this.syncEnergy();
  ItemStack dropMe = inputSlots.getStackInSlot(0).copy();
  if (dropMe.isEmpty()) {
    this.status = UncraftStatusEnum.EMPTY;
    timer = TIMER.get();
    return;
  }
  if (this.requiresRedstone() && !this.isPowered()) {
    setLitProperty(false);
    return;
  }
  final int cost = POWERCONF.get();
  if (energy.getEnergyStored() < cost && cost > 0) {
    return;
  }
  setLitProperty(true);
  //only tick down if we have enough energy and have a valid item
  if (this.status != UncraftStatusEnum.EMPTY && this.status != UncraftStatusEnum.MATCH) {
    this.timer = TIMER.get();
    return;
  }
  if (--timer > 0) {
    return;
  }
  timer = TIMER.get();
  if (level.isClientSide || level.getServer() == null) {
    return;
  }
  RecipeHolder<?> match = this.findMatchingRecipe(level, dropMe);
  if (match != null) {
    var status = uncraftRecipe(match.value());
    this.status = status;
    if (status == UncraftStatusEnum.MATCH) {
      //pay cost
      inputSlots.extractItem(0, match.value().getResultItem(level.registryAccess()).getCount(), false);
      energy.extractEnergy(cost, false);
    }
  }
  else {
    this.status = UncraftStatusEnum.NORECIPE;
  }
}

public void onLivingHurt(LivingHurtEvent event) {
    Optional.ofNullable(event.getSource().getEntity())
            .filter(entity -> entity instanceof LivingEntity)
            .map(entity -> (LivingEntity) entity)
            .map(LivingEntity::getMainHandItem)
            .filter(itemStack -> itemStack.getItem() instanceof IModularItem)
            .ifPresent(itemStack -> {
                int quickStrikeLevel = getEffectLevel(itemStack, ItemEffect.quickStrike);
                if (quickStrikeLevel > 0) {
                    float maxDamage = (float) ((LivingEntity) event.getSource().getEntity())
                            .getAttribute(Attributes.ATTACK_DAMAGE).getValue();
                    float multiplier = quickStrikeLevel * 0.05f + 0.2f;

                    if (event.getAmount() < multiplier * maxDamage) {
                        event.setAmount(multiplier * maxDamage);
                    }
                }

                int armorPenetrationLevel = getEffectLevel(itemStack, ItemEffect.armorPenetration);
                if (armorPenetrationLevel > 0) {
                    ArmorPenetrationEffect.onLivingHurt(event, armorPenetrationLevel);
                }
            });

    if (!event.getSource().is(DamageTypeTags.BYPASSES_ARMOR)) {
        Optional.ofNullable(event.getEntity())
                .map(entity -> Stream.of(entity.getMainHandItem(), entity.getOffhandItem()))
                .orElseGet(Stream::empty)
                .filter(itemStack -> !itemStack.isEmpty())
                .filter(itemStack -> itemStack.getItem() instanceof ItemModularHandheld)
                .forEach(itemStack -> {
                    ItemModularHandheld item = (ItemModularHandheld) itemStack.getItem();
                    if (item.getAttributeValue(itemStack, Attributes.ARMOR) > 0 || item.getAttributeValue(itemStack,
                            Attributes.ARMOR_TOUGHNESS) > 0) {
                        int reducedAmount = (int) Math.ceil(event.getAmount() - CombatRules.getDamageAfterAbsorb(event.getAmount(),
                                (float) event.getEntity().getArmorValue(),
                                (float) event.getEntity().getAttribute(Attributes.ARMOR_TOUGHNESS).getValue()));
                        item.applyUsageEffects(event.getEntity(), itemStack, reducedAmount);
                        item.applyDamage(reducedAmount, itemStack, event.getEntity());
                    }
                });
    }
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    Vec3 dest = null;
    var teleportData = (TeleportSpell.TeleportData) playerMagicData.getAdditionalCastData();
    if (teleportData != null) {
        var potentialTarget = teleportData.getTeleportTargetPosition();
        if (potentialTarget != null) {
            dest = potentialTarget;
            Utils.handleSpellTeleport(this, entity, dest);
        }
    } else {
        HitResult hitResult = RaycastBuilder.begin(level, entity)
                .range(getDistance(spellLevel, entity))
                .checkForBlocks(true)
                .build();
        if (entity.isPassenger()) {
            entity.stopRiding();
        }
        if (hitResult.getType() == HitResult.Type.ENTITY && ((EntityHitResult) hitResult).getEntity() instanceof LivingEntity target) {
            //dest = target.position().subtract(new Vec3(0, 0, 1.5).yRot(target.getYRot()));
            for (int i = 0; i < 8; i++) {
                dest = target.position().subtract(new Vec3(0, 0, 1.5).yRot(-(target.getYRot() + i * 45) * Mth.DEG_TO_RAD));
                if (level.getBlockState(BlockPos.containing(dest).above()).isAir())
                    break;

            }
            Utils.handleSpellTeleport(this, entity, dest.add(0, 1, 0));
            entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition().subtract(0, .15, 0));
        } else {
            dest = TeleportSpell.findTeleportLocation(level, entity, getDistance(spellLevel, entity));
            Utils.handleSpellTeleport(this, entity, dest);

        }
    }
    entity.resetFallDistance();
    level.playSound(null, dest.x, dest.y, dest.z, getCastFinishSound().get(), SoundSource.NEUTRAL, 1f, 1f);

    //Invis take 1 tick to set in
    entity.setInvisible(true);
    entity.addEffect(new MobEffectInstance(MobEffectRegistry.TRUE_INVISIBILITY, 100, 0, false, false, true));


    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public void onLivingAttack(LivingAttackEvent event) {
    if (!event.getSource().is(DamageTypeTags.BYPASSES_ARMOR) && event.getEntity().isBlocking()) {
        Optional.ofNullable(event.getEntity())
                .map(LivingEntity::getUseItem)
                .filter(itemStack -> itemStack.getItem() instanceof ItemModularHandheld)
                .ifPresent(itemStack -> {
                    ItemModularHandheld item = (ItemModularHandheld) itemStack.getItem();
                    LivingEntity blocker = event.getEntity();
                    if (UseAnim.BLOCK.equals(itemStack.getUseAnimation())) {
                        item.applyUsageEffects(blocker, itemStack, Mth.ceil(event.getAmount() / 2f));
                    }

                    if (event.getSource().getDirectEntity() instanceof LivingEntity attacker) {
                        if (item.getEffectLevel(itemStack, ItemEffect.blockingReflect) > attacker.getRandom().nextFloat() * 100) {
                            attacker.hurt(event.getEntity().damageSources().thorns(event.getEntity()),
                                    (float) (item.getAbilityBaseDamage(event.getEntity(), itemStack) * item.getEffectEfficiency(itemStack,
                                            ItemEffect.blockingReflect)));
                            applyHitEffects(itemStack, attacker, blocker);
                            EffectHelper.applyEnchantmentHitEffects(itemStack, attacker, blocker);

                            float knockbackFactor = 0.5f + EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack);
                            attacker.knockback(knockbackFactor * 0.5f,
                                    blocker.getX() - attacker.getX(), blocker.getZ() - attacker.getZ());
                        }
                    }
                });
    }

    if ("arrow".equals(event.getSource().getMsgId())) {
        CastOptional.cast(event.getSource().getEntity(), LivingEntity.class)
                .map(shooter -> Stream.of(shooter.getMainHandItem(), shooter.getOffhandItem()))
                .orElseGet(Stream::empty)
                .filter(itemStack -> itemStack.getItem() instanceof ModularBowItem || itemStack.getItem() instanceof ModularCrossbowItemImpl)
                .findFirst()
                .ifPresent(itemStack -> {
                    IModularItem item = (IModularItem) itemStack.getItem();
                    item.tickHoningProgression((LivingEntity) event.getSource().getEntity(), itemStack, 2);
                    applyHitEffects(itemStack, event.getEntity(), (LivingEntity) event.getSource().getEntity());
                });

    }

    RevengeTracker.onAttackEntity(event);
}

private void hitEntities(ServerPlayer player, ItemModularHandheld item, ItemStack itemStack, AABB aoe,
        double damageMultiplier, int revengeLevel, boolean overextend, int overextendLevel, double momentumEfficiency,
        AtomicInteger kills, AtomicInteger revengeKills, AtomicInteger hits) {
    Collection<LivingEntity> momentumTargets = new LinkedList<>();
    player.level().getEntitiesOfClass(LivingEntity.class, aoe).stream()
            .filter(entity -> entity != player)
            .filter(entity -> !player.isAlliedTo(entity))
            .forEach(entity -> {
                double individualDamageMultiplier = damageMultiplier;

                boolean canRevenge = revengeLevel > 0 && RevengeTracker.canRevenge(player, entity);
                if (canRevenge) {
                    individualDamageMultiplier += revengeLevel / 100d;
                }

                if (overextend && entity.getHealth() / entity.getMaxHealth() >= overextendLevel / 100f) {
                    individualDamageMultiplier *= 2;
                }

                AbilityUseResult result = item.hitEntity(itemStack, player, entity, individualDamageMultiplier, 0.5f, 0.2f);
                if (result != AbilityUseResult.fail) {
                    if (!entity.isAlive()) {
                        kills.incrementAndGet();

                        if (canRevenge) {
                            revengeKills.incrementAndGet();
                            RevengeTracker.removeEnemySynced(player, entity);
                        }
                    } else if (momentumEfficiency > 0) {
                        momentumTargets.add(entity);
                    }

                    hits.incrementAndGet();
                }

                if (result == AbilityUseResult.crit) {
                    player.getCommandSenderWorld().playSound(player, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 1.3f);
                }
            });

    if (momentumEfficiency > 0 && kills.get() > 0) {
        int stunDuration = (int) (momentumEfficiency * kills.get() * 20);
        momentumTargets.forEach(entity -> entity.addEffect(new MobEffectInstance(StunPotionEffect.instance, stunDuration, 0, false, false)));
    }
}

public static boolean doEffect(LivingEntity livingEntity, DamageSource damageSource) {
    if (livingEntity.level.isClientSide
            || damageSource.is(DamageTypeTags.IS_FALL)
            || damageSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)
            || damageSource.is(DamageTypeTagGenerator.BYPASS_EVASION)) {
        return false;
    }

    var data = MagicData.getPlayerMagicData(livingEntity).getSyncedData();
    data.subtractEvasionHit();
    if (data.getEvasionHitsRemaining() < 0) {
        livingEntity.removeEffect(MobEffectRegistry.EVASION);
    }

    double d0 = livingEntity.getX();
    double d1 = livingEntity.getY();
    double d2 = livingEntity.getZ();
    float maxRadius = 12;
    var level = livingEntity.level;
    var random = livingEntity.getRandom();
    Vec3 horizontalDirection = livingEntity.getForward().multiply(1, 0, 1).add(0.1,0,0).normalize();
    Vec3 origin = livingEntity.getBoundingBox().getCenter();
    float radius = maxRadius / 2f;
    int range = 45;
    for (int attempts = 0; attempts < 24; attempts++) {
        Vec3 direction = horizontalDirection.scale(-1).yRot(random.nextIntBetweenInclusive(-range, range) * Mth.DEG_TO_RAD);
        HitResult raycast = Utils.raycastForBlock(level, origin, origin.add(direction.scale(radius).add(0, 4, 0)), ClipContext.Fluid.NONE);
        Vec3 destination = Utils.moveToRelativeGroundLevel(level, raycast.getLocation().subtract(direction.scale(livingEntity.getBbWidth())), 5);
        if (destination.distanceToSqr(livingEntity.position()) > 4 && level.noCollision(livingEntity.getBoundingBox().move(destination.subtract(livingEntity.position())).inflate(-0.05)) && !level.getBlockState(BlockPos.containing(destination).below()).isAir()) {
            particleCloud(livingEntity);
            level.playSound(null, d0, d1, d2, SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, 1.0F);
            Utils.handleSpellTeleport(SpellRegistry.EVASION_SPELL.get(), livingEntity, destination);
            if (damageSource.getEntity() != null) {
                livingEntity.lookAt(EntityAnchorArgument.Anchor.EYES, damageSource.getEntity().getEyePosition());
            }
            break;
        }
        range *= 2;
        radius += 1;
    }

    particleCloud(livingEntity);
    level.playSound(null, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, 1.0F);
    return true;
}

protected void handleAttackLogic(double distanceSquared) {
    var meleeRange = meleeRange();
    float rangeMultiplier = nextAttack == null ? 1f : nextAttack.rangeMultiplier;
    float procRangeSqr = meleeRange * meleeRange * rangeMultiplier * rangeMultiplier * 1.2f * 1.2f;
    if (meleeAnimTimer < 0 && (!wantsToMelee || distanceSquared > procRangeSqr || mob.isCasting())) {
        super.handleAttackLogic(distanceSquared);
        return;
    }
    //Handling Animation hit frames
    mob.getLookControl().setLookAt(target);
    if (meleeAnimTimer > 0 && currentAttack != null) {
        //We are currently attacking and are in a melee animation
        forceFaceTarget();
        meleeAnimTimer--;
        if (currentAttack.isHitFrame(meleeAnimTimer)) {
            AttackKeyframe attackData = currentAttack.getHitFrame(meleeAnimTimer);
            onHitFrame(attackData, meleeRange);
        }
        if (currentAttack.canCancel && (currentAttack.isSingleHit() || currentAttack.lengthInTicks - meleeAnimTimer > currentAttack.attacks.keySet().intStream().sorted().findFirst().orElse(0))) {
            Vec3 delta = mob.position().subtract(target.position());
            var modifiedDistanceSquared = delta.x * delta.x + delta.y * delta.y * .5 * .5 + delta.z * delta.z;
            if (modifiedDistanceSquared > meleeRange * meleeRange * 1.5 * 1.5) {
                stopMeleeAction();
            }
        }
    } else if (queueCombo != null && target != null && !target.isDeadOrDying()) {
        nextAttack = queueCombo;
        queueCombo = null;
        doMeleeAction();
    } else if (meleeAnimTimer == 0) {
        //Reset animations/attack
        nextAttack = getNextAttack((float) distanceSquared);
        resetMeleeAttackInterval(distanceSquared);
        meleeAnimTimer = -1;
    } else {
        //Handling attack delay
        if (distanceSquared < procRangeSqr) {
            if (hasLineOfSight && --this.meleeAttackDelay == 0) {
                doMeleeAction();
            } else if (this.meleeAttackDelay < 0) {
                resetMeleeAttackInterval(distanceSquared);
            }
        }
    }
}

public void onLivingDamage(LivingDamageEvent event) {
    LivingEntity entity = event.getEntity();
    DamageSource source = event.getSource();
    float damage = event.getAmount();

    if (source.is(DamageTypeTags.IS_LIGHTNING)) {
        if (entity.hasEffect(ModEffect.EFFECTWETNESS.get())) {
            MobEffectInstance effectinstance1 = entity.getEffect(ModEffect.EFFECTWETNESS.get());
            if (effectinstance1 != null) {
                float i = (effectinstance1.getAmplifier() + 1) * 0.2F;
                float f = damage + damage * i;
                damage = Math.min(Float.MAX_VALUE, f);
                event.setAmount(damage);
            }
        }
    }
    if (entity.getHealth() <= event.getAmount() && entity.hasEffect(ModEffect.EFFECTSTUN.get())) {
        entity.removeEffect(ModEffect.EFFECTSTUN.get());
    }
    if (!event.getEntity().getItemBySlot(EquipmentSlot.LEGS).isEmpty() && event.getSource() != null && event.getSource().getEntity() != null) {
        if (event.getEntity().getItemBySlot(EquipmentSlot.LEGS).getItem() == ModItems.IGNITIUM_LEGGINGS.get()) {
            Entity attacker = event.getSource().getEntity();
            if (attacker instanceof LivingEntity && attacker != event.getEntity()) {
                if (event.getEntity().getRandom().nextFloat() < 0.5F) {
                    MobEffectInstance effectinstance1 = ((LivingEntity) attacker).getEffect(ModEffect.EFFECTBLAZING_BRAND.get());
                    int i = 1;
                    if (effectinstance1 != null) {
                        i += effectinstance1.getAmplifier();
                        ((LivingEntity) attacker).removeEffectNoUpdate(ModEffect.EFFECTBLAZING_BRAND.get());
                    } else {
                        --i;
                    }

                    i = Mth.clamp(i, 0, 4);
                    MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTBLAZING_BRAND.get(), 100, i, false, false, true);
                    ((LivingEntity) attacker).addEffect(effectinstance);

                    if (!attacker.isOnFire()) {
                        attacker.setSecondsOnFire(5);
                    }
                }
            }
        }
    }
}

public void initiateCastSpell(AbstractSpell spell, int spellLevel) {
    if (Log.SPELL_DEBUG) {
        IronsSpellbooks.LOGGER.debug("ASCM.initiateCastSpell: spellType:{} spellLevel:{}, isClient:{}", spell.getSpellId(), spellLevel, level.isClientSide);
    }

    if (spell == SpellRegistry.none()) {
        castingSpell = null;
        return;
    }

    if (level.isClientSide) {
        cancelCastAnimation = false;
    }

    castingSpell = new SpellData(spell, spellLevel);

    if (getTarget() != null) {
        forceLookAtTarget(getTarget());
    }

    if (!level.isClientSide && !castingSpell.getSpell().checkPreCastConditions(level, spellLevel, this, playerMagicData)) {
        if (Log.SPELL_DEBUG) {
            IronsSpellbooks.LOGGER.debug("ASCM.precastfailed: spellType:{} spellLevel:{}, isClient:{}", spell.getSpellId(), spellLevel, level.isClientSide);
        }

        castingSpell = null;
        return;
    }

    // fixme: this is dumb and non-extensible
    if (spell == SpellRegistry.TELEPORT_SPELL.get() || spell == SpellRegistry.FROST_STEP_SPELL.get()) {
        setTeleportLocationBehindTarget(10);
    } else if (spell == SpellRegistry.BLOOD_STEP_SPELL.get()) {
        setTeleportLocationBehindTarget(3);
    } else if (spell == SpellRegistry.BURNING_DASH_SPELL.get()) {
        setBurningDashDirectionData();
    } else if (spell == SpellRegistry.RAY_OF_SIPHONING_SPELL.get()) {
        playerMagicData.setAdditionalCastData(new CastingMobAimingData());
    }

    playerMagicData.initiateCast(castingSpell.getSpell(), castingSpell.getLevel(), castingSpell.getSpell().getEffectiveCastTime(castingSpell.getLevel(), this), CastSource.MOB, SpellSelectionManager.MAINHAND);

    if (!level.isClientSide) {
        castingSpell.getSpell().onServerPreCast(level, castingSpell.getLevel(), this, playerMagicData);
    }
}

public void tick() {
    abilityTimer++;
    mob.setSpeed(0);
    mob.setZza(0);
    mob.setXxa(0);
    var target = mob.getTarget();
    if (target != null) {
        mob.getLookControl().setLookAt(target);
    }
    if (abilityTimer == ACTION_TIMESTAMP) {
        //targeted orbs
        if (target != null) {
            var range = mob.getAttributeValue(Attributes.FOLLOW_RANGE);
            var targets = mob.level.getEntitiesOfClass(target.getClass(), mob.getBoundingBox().inflate(range, 8, range));
            for (LivingEntity entity : targets) {
                if (Utils.hasLineOfSight(mob.level, mob, entity, false)) {
                    FireBomb fireBomb = fireBomb();
                    double horizontalSpeed = 0.5;
                    Vec3 horizontal = entity.position().subtract(mob.position()).multiply(1, 0, 1);
                    double distance = horizontal.length();
                    double ticks = distance / horizontalSpeed;
                    // y(t) = -1/2(g)(t^2) + v0*t
                    // => v0 = [y1 + 1/2(g)(t1^2)]/t1
                    double y1 = entity.getY() - mob.getY();
                    double g = fireBomb.getGravity();
                    double verticalSpeed = (y1 + 0.5 * g * ticks * ticks) / ticks;
                    Vec3 estMovement = entity.getDeltaMovement().multiply(1, 0, 1).scale(ticks);
                    Vec3 trajectory = horizontal.normalize().scale(horizontalSpeed).add(0, verticalSpeed, 0).add(estMovement);
                    fireBomb.setDeltaMovement(trajectory);
                    mob.level.addFreshEntity(fireBomb);
                }
            }
        }
        //random orbs
        for (int i = 0; i < 4; i++) {
            FireBomb fireBomb = fireBomb();
            Vec3 motion = Utils.getRandomVec3(0.85).add(0, 3, 0).scale(0.3);
            fireBomb.setDeltaMovement(motion);

            mob.level.addFreshEntity(fireBomb);
        }
    }
    if (abilityTimer >= ANIM_DURATION) {
        isUsing = false;
    }
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (level.isClientSide) {
        return false;
    }
    /*
    can parry:
    - serverside
    - in combat
    - we aren't in melee attack anim or spell cast
    - the damage source is caused by an entity (ie not fall damage)
    - the damage is caused within our rough field of vision (117 degrees)
    - the damage is not /kill
     */
    boolean isDodgeableAttack = this.isAggressive() &&
            parryCooldown <= 0 &&
            !isImmobile() &&
            pSource.getEntity() != null &&
            !pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY);
    boolean canParry = isDodgeableAttack &&
            !attackGoal.isActing() &&
            pSource.getSourcePosition() != null && pSource.getSourcePosition().subtract(this.position()).normalize().dot(this.getForward()) >= 0.35;
    if (canParry && this.random.nextFloat() < 0.5) {
        serverTriggerAnimation("offhand_parry");
        procSpectralDagger();
        this.parryCooldown = 100;
        this.playSound(SoundRegistry.FIRE_DAGGER_PARRY.get());
        return false;
    }
    if (isStanceBroken()) {
        pAmount *= 0.40f;
    }
    if (isSoulMode()) {
        pAmount *= 0.50f;
    }
    if (isHalfHealthAttacking()) {
        pAmount *= 0.80f;
    }
    // damage limiter
    var limit = getMaxHealth() * 0.025f;
    if (pAmount > limit) {
        pAmount = limit + (pAmount - limit) * .3f; // damage about limit has .3x multiplier applied
    }
    if (pSource.is(DamageTypes.IN_WALL) && this.destroyBlockDelay <= 0) {
        Utils.doMobBreakSuffocatingBlocks(this);
        destroyBlockDelay = 40;
    }
    return super.hurt(pSource, pAmount);
}

protected void customServerAiStep() {
    super.customServerAiStep();

    LivingEntity target = getTarget();
    if (target != null) {
        this.navigation.moveTo(target, 7);
        //this.moveControl.setWantedPosition(target.getX(), target.getY(), target.getZ(), 5);
    }
    if (this.tickCount % 8 == 0) {
        if (level.collidesWithSuffocatingBlock(this, this.getBoundingBox().move(0, -1, 0))) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.02, 0));
        } else {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.008, 0));
        }
    }
    if (!this.moveControl.hasWanted()) {
        this.setDeltaMovement(this.getDeltaMovement().multiply(.95f, 1, .95f));
    }
    if ((this.tickCount % 7) == 0) {
        float fade = 1 - Mth.clamp((tickCount - maxLife + 40) / (float) (maxLife), 0, 1f);
        this.playSound(SoundRegistry.FIREFLY_SWARM_IDLE.get(), .25f * fade, .95f + Utils.random.nextFloat() * .1f);
    }
    if (this.tickCount % 15 == 0) {
        //Damage tick
        float inflate = radius - this.getBbWidth() * .5f;
        this.level.getEntities(this, this.getBoundingBox().inflate(inflate), this::canHitEntity).forEach(
                (entity) -> {
                    if (canHitEntity(entity)) {
                        boolean hit = DamageSources.applyDamage(entity, damage, SpellRegistry.FIREFLY_SWARM_SPELL.get().getDamageSource(this, getOwner()));
                        if (hit) {
                            this.playSound(SoundRegistry.FIREFLY_SWARM_ATTACK.get(), .75f, .9f + Utils.random.nextFloat() * .2f);
                            if (target == null) {
                                setTarget(entity);
                            } else if (target != entity) {
                                nextTarget = entity;
                            }
                        }
                    }
                }
        );
        if (getTarget() == null || getTarget().isDeadOrDying()) {
            setTarget(nextTarget);
            if (nextTarget != null && nextTarget.isRemoved()) {
                nextTarget = null;
            }
        }
    }
}

public void tick(Level level) {
    boolean doManaRegen = level.getServer().getTickCount() % MANA_REGEN_TICKS == 0;

    level.players().stream().toList().forEach(player -> {
        if (player instanceof ServerPlayer serverPlayer) {
            MagicData playerMagicData = MagicData.getPlayerMagicData(serverPlayer);
            playerMagicData.getPlayerCooldowns().tick(1);
            playerMagicData.getPlayerRecasts().tick(2);

            if (playerMagicData.isCasting()) {
                var spell = SpellRegistry.getSpell(playerMagicData.getCastingSpellId());
                if ((spell.getCastType() == CastType.LONG && !serverPlayer.isUsingItem()) || spell.getCastType() == CastType.INSTANT) {
                    if (playerMagicData.getCastDurationRemaining() <= 0) {
                        spell.castSpell(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData.getCastSource(), true);
                        if (playerMagicData.getCastSource() == CastSource.SCROLL) {
                            Scroll.attemptRemoveScrollAfterCast(serverPlayer);
                        }
                        spell.onServerCastComplete(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData, false);
                    }
                } else if (spell.getCastType() == CastType.CONTINUOUS) {
                    if ((playerMagicData.getCastDurationRemaining()) % CONTINUOUS_CAST_TICK_INTERVAL == 0) {
                        if (playerMagicData.getCastDurationRemaining() <= 0 || (playerMagicData.getCastSource().consumesMana() && playerMagicData.getMana() - spell.getManaCost(playerMagicData.getCastingSpellLevel()) * 2 < 0)) {
                            spell.castSpell(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData.getCastSource(), true);

                            if (playerMagicData.getCastSource() == CastSource.SCROLL) {
                                Scroll.attemptRemoveScrollAfterCast(serverPlayer);
                            }

                            spell.onServerCastComplete(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData, false);

                        } else {
                            spell.castSpell(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData.getCastSource(), false);
                        }
                    }
                }
                playerMagicData.handleCastDuration();
                if (playerMagicData.isCasting()) {
                    spell.onServerCastTick(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData);
                }
            }

            if (doManaRegen) {
                if (regenPlayerMana(serverPlayer, playerMagicData)) {
                    PacketDistributor.sendToPlayer(serverPlayer, new SyncManaPacket(playerMagicData));
                }
            }
        }
    });
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    Vec3 start = entity.getEyePosition();
    Vec3 end = start.add(entity.getForward().normalize().scale(80));
    HitResult hitResult = RaycastBuilder.begin(entity.level, entity)
            .start(start)
            .end(end)
            .checkForBlocks(true)
            .bbInflation(0.35f)
            .filter(Utils::validAntiMagicTarget)
            .build();
    Vec3 forward = entity.getForward().normalize();
    if (hitResult instanceof EntityHitResult entityHitResult) {
        var hitEntity = entityHitResult.getEntity();
        if (!(NeoForge.EVENT_BUS.post(new CounterSpellEvent(entity, hitEntity)).isCanceled())) {
            if (hitEntity instanceof AntiMagicSusceptible antiMagicSusceptible) {
                if (antiMagicSusceptible instanceof IMagicSummon summon) {
                    if (summon.getSummoner() == entity) {
                        if (summon instanceof Mob mob && mob.getTarget() == null) {
                            antiMagicSusceptible.onAntiMagic(playerMagicData);
                        }
                    } else {
                        antiMagicSusceptible.onAntiMagic(playerMagicData);
                    }
                } else {
                    antiMagicSusceptible.onAntiMagic(playerMagicData);
                }
            } else if (hitEntity instanceof ServerPlayer serverPlayer) {
                Utils.serverSideCancelCast(serverPlayer, true);
                MagicData.getPlayerMagicData(serverPlayer).getPlayerRecasts().removeAll(RecastResult.COUNTERSPELL);
            } else if (hitEntity instanceof IMagicEntity abstractSpellCastingMob) {
                abstractSpellCastingMob.cancelCast();
            }
            if (hitEntity instanceof LivingEntity livingEntity) {
                //toList to avoid concurrent modification
                for (Holder<MobEffect> mobEffect : livingEntity.getActiveEffectsMap().keySet().stream().toList()) {
                    if (mobEffect.value() instanceof MagicMobEffect) {
                        livingEntity.removeEffect(mobEffect);
                    }
                }
            }
        }
    }
    double distance = entity.position().distanceTo(hitResult.getLocation());
    for (float i = 1; i < distance; i += .5f) {
        Vec3 pos = entity.getEyePosition().add(forward.scale(i));
        MagicManager.spawnParticles(world, ParticleTypes.ENCHANT, pos.x, pos.y, pos.z, 1, 0, 0, 0, 0, false);
    }
    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

public static List<Component> formatScrollTooltip(ItemStack stack, Player player) {
    if (stack.getItem() instanceof Scroll && ISpellContainer.isSpellContainer(stack)) {
        var spellList = ISpellContainer.get(stack);
        if (spellList.isEmpty()) {
            return List.of();
        }

        var spellData = spellList.getSpellAtIndex(0);
        var spell = spellData.getSpell();
        var spellLevel = spell.getLevelFor(spellData.getLevel(), player);


        var levelText = getLevelComponenet(spellData, player);
        var title = Component.translatable("tooltip.irons_spellbooks.level", levelText)
                .append(" ")
                .append(Component.translatable("tooltip.irons_spellbooks.rarity", spell.getRarity(spellData.getLevel()).getDisplayName()).withStyle(spell.getRarity(spellData.getLevel()).getDisplayName().getStyle()))
                .withStyle(ChatFormatting.GRAY);
        var uniqueInfo = spell.getUniqueInfo(spellLevel, player);
        var whenInSpellBook = Component.translatable("tooltip.irons_spellbooks.scroll_tooltip").withStyle(ChatFormatting.GRAY);
        var manaCost = getManaCostComponent(spell.getCastType(), spell.getManaCost(spellLevel)).withStyle(ChatFormatting.BLUE);
        var cooldownTime = Component.translatable("tooltip.irons_spellbooks.cooldown_length_seconds", Utils.timeFromTicks(MagicManager.getEffectiveSpellCooldown(spell, player, CastSource.SCROLL), 2)).withStyle(ChatFormatting.BLUE);
        MutableComponent castType = null;
        if (spell.getCastType() != CastType.INSTANT) {
            castType = (Component.literal(" ").append(getCastTimeComponent(spell.getCastType(), Utils.timeFromTicks(spell.getEffectiveCastTime(spellLevel, player), 2)).withStyle(ChatFormatting.BLUE)));
        }
        List<Component> lines = new ArrayList<>();
        String parentModId = spell.getSpellResource().getNamespace();
        if (!parentModId.equals(IronsSpellbooks.MODID)) {
            CustomizeScrollModNameEvent.resolveModLabel(parentModId).ifPresent(lines::add);
        }
        lines.add(Component.literal(" ").append(title));
        uniqueInfo.forEach((line) -> lines.add(Component.literal(" ").append(line.withStyle(line.getStyle().applyTo(getStyleFor(player, spell))))));
        if (castType != null) {
            lines.add(castType);
        }

        lines.add(Component.empty());
        lines.add(whenInSpellBook);
        if (spell.getManaCost(spellLevel) > 0) {
            lines.add(manaCost);
        }
        if (spell.getSpellCooldown() > 0) {
            lines.add(cooldownTime);
        }
        lines.add(spell.getSchoolType().getDisplayName().copy());

        return lines;
    }
    return List.of();
}

    public boolean applyEffectTick(LivingEntity livingEntity, int amplifier) {
        var level = livingEntity.level;
        if (level.isClientSide) {
            return true;
        }
        List<Entity> list = level.getEntities(livingEntity, livingEntity.getBoundingBox().inflate(.25, .5, .25));
        boolean hit = false;
        UUID ignore = null;
        if (!list.isEmpty()) {
            for (Entity entity : list) {
                if (DamageSources.applyDamage(entity, amplifier, SpellRegistry.VOLT_STRIKE_SPELL.get().getDamageSource(livingEntity))) {
                    //Guarantee that the entity receives i-frames, since we are damaging every tick
                    entity.invulnerableTime = 20;
                    hit = true;
                    ignore = entity.getUUID();
                }
            }
        }
        if (!hit &&
                (
//                        Utils.raycastForBlock(level, livingEntity.position(), livingEntity.position().add(livingEntity.getDeltaMovement()), ClipContext.Fluid.NONE).getType() == HitResult.Type.BLOCK
                        !level.noCollision(livingEntity.getBoundingBox().move(livingEntity.getDeltaMovement()).move(livingEntity.getDeltaMovement().normalize().scale(0.1)).deflate(0.1))
                )) {
            hit = true;
        }
        if (hit) {
            float explosionRadius = 4;
            var explosionRadiusSqr = explosionRadius * explosionRadius;
            var entities = level.getEntities(livingEntity, livingEntity.getBoundingBox().inflate(explosionRadius));
            Vec3 losPoint = Utils.raycastForBlock(level, livingEntity.position(), livingEntity.position().add(0, 1, 0), ClipContext.Fluid.NONE).getLocation();
            for (Entity entity : entities) {
                double distanceSqr = entity.distanceToSqr(livingEntity.position());
                if (ignore != entity.getUUID() && distanceSqr < explosionRadiusSqr && entity.canBeHitByProjectile() && Utils.hasLineOfSight(level, losPoint, entity.getBoundingBox().getCenter(), true)) {
                    double p = (1 - distanceSqr / explosionRadiusSqr);
                    float damage = (float) (amplifier * p * 0.5);
                    DamageSources.applyDamage(entity, damage, SpellRegistry.VOLT_STRIKE_SPELL.get().getDamageSource(livingEntity));
                }
            }
            livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().normalize().scale(-0.5).add(0, 0.5, 0));
            livingEntity.hurtMarked = true;

            var x = livingEntity.getX();
            var y = livingEntity.getY() + 1;
            var z = livingEntity.getZ();
            MagicManager.spawnParticles(level, ParticleHelper.ELECTRIC_SPARKS, x, y, z, 25, .08, .08, .08, 0.3, false);
            MagicManager.spawnParticles(level, ParticleHelper.ELECTRICITY, x, y, z, 75, .1, .1, .1, .5, false);
            MagicManager.spawnParticles(level, new BlastwaveParticleOptions(new Vector3f(.7f, 1f, 1f), explosionRadius * 2), x, y + .15f, z, 1, 0, 0, 0, 0, true);
            level.playSound(null, x, y, z, SoundEvents.TRIDENT_THUNDER.value(), livingEntity.getSoundSource(), 4, 0.8f);
            return false;
        }
        livingEntity.fallDistance = 0;
        return true;
    }

private static void onEntityImpact(Player player, LivingEntity target, LungeData data) {
    ItemStack itemStack = data.itemStack;
    ItemModularHandheld item = CastOptional.cast(itemStack.getItem(), ItemModularHandheld.class).orElse(null);

    if (item == null) {
        activeCache.invalidate(getIdentifier(player));
        return;
    }

    Vec3 bounceVector = player.position().subtract(target.position()).normalize().scale(0.1f);
    player.setDeltaMovement(bounceVector);
    player.hurtMarked = true;

    float cooldownMultiplier = data.hitCooldown;

    int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);

    if (RevengeTracker.canRevenge(player) && RevengeTracker.canRevenge(player, target)) {
        cooldownMultiplier = 0;
        RevengeTracker.removeEnemy(player, target);
    }

    if (!player.level().isClientSide) {
        double bonusDamage = 0;

        if (momentumLevel > 0) {
            bonusDamage = Math.min(momentumLevel, player.fallDistance);
        }

        int lungeLevel = item.getEffectLevel(itemStack, ItemEffect.lunge);
        AbilityUseResult result = item.hitEntity(itemStack, player, target, data.damageMultiplierOffset + lungeLevel / 100f, bonusDamage,
                0.5f, 0.5f);

        if (result != AbilityUseResult.fail) {
            if (momentumLevel > 0) {
                int duration = 10 + (int) (Math.min(momentumLevel, player.fallDistance) * item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum) * 20);
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, duration, 0, false, false));
                spawnMomentumParticles(target, bonusDamage);
            }
        }

        target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_KNOCKBACK, SoundSource.PLAYERS, 1, 0.8f);
        player.swing(InteractionHand.MAIN_HAND, true);
    }

    if (momentumLevel > 0) {
        player.fallDistance = Math.max(0, player.fallDistance - momentumLevel);
    }

    item.tickProgression(player, itemStack, 2);
    item.applyDamage(2, itemStack, player);

    player.getCooldowns().addCooldown(item, (int) (instance.getCooldown(item, itemStack) * cooldownMultiplier));

    activeCache.invalidate(getIdentifier(player));
}

public void tick() {
    super.tick();
    float maxHealth = this.getMaxHealth();
    float currentHealth = this.getHealth();
    this.bossEvent.setProgress(currentHealth / maxHealth);
    int daggerTime = getSpectralDaggerTime();
    if (getSpectralDaggerTime() != 0) {
        this.entityData.set(DATA_DAGGER_TIME, daggerTime - Mth.sign(daggerTime));
    }
    if (parryCooldown > 0) {
        parryCooldown--;
    }
    if (isSpawning()) {
        spawnTimer--;
        handleSpawnSequence();
        if (spawnTimer == 0 && !level.isClientSide) {
            spawnKnight(true);
            spawnKnight(false);
        }
    } else if (isDespawning()) {
        // reuse death time for fadeout animations
        deathTime++;
        if (!level.isClientSide) {
            deathParticles();
            if (getTarget() != null) {
                // stop despawning if we re-aggro
                setDespawning(false);
            }
            if (deathTime > 160) {
                doForcedDespawned();
            }
        }
    } else if (deathTime > 0 && !isDeadOrDying()) {
        // quickly fade back in from despawn animation
        deathTime = Math.max(0, deathTime - 3);
    } else if (isHalfHealthAttacking()) {
        halfHealthTimer--;
        if (!level.isClientSide) {
            handleHalfHealthSequence();
        }
    }
    if (!level.isClientSide) {
        // while this is server-only logic, this cannot be in aistep because ai is disabled during stance breaks
        if (isStanceBroken()) {
            stanceBreakTimer--;
            handleStanceBreakSequence();
        }
        if (isSoulMode() && !dead && !isSpawning()) {
            soulParticles();
        }
    }
    if (destroyBlockDelay > 0) {
        --destroyBlockDelay;
    }
    if (stuckDetectorDelay > 0) {
        --stuckDetectorDelay;
    }
}

public void tick() {
    super.tick();

    if (++age > FAILSAFE_EXPIRE_TIME) {
        //This exists in case there is any bug with removing the cone onCastComplete
        discard();
    }

    //TODO: try this instead of the ray trace
    /*
    So. This is what vectors are for.
    The player has a vector that is their "front" called "LookVec" (Search the EntityPlayer class).
    Take that vector, multiply by 0.5 (or 0.2 or whatever), add their current position, and voila. You have the spot a half-block in front of them.
    */

    var owner = this.getOwner();
    if (owner != null) {
        var rayTraceVector = rayTrace(owner);
        var ownerEyePos = owner.getEyePosition(1.0f).subtract(0, .8, 0);
        this.setPos(ownerEyePos);
        this.setXRot(owner.getXRot());
        this.setYRot(owner.getYRot());
        this.yRotO = getYRot();
        this.xRotO = getXRot();
        //setDeltaMovement(ownerEyePos);

        double scale = 1;

        for (int i = 0; i < subEntities.length; i++) {
            var subEntity = subEntities[i];

            double distance = 1 + (i * scale * subEntity.getDimensions(null).width() / 2);
            Vec3 newVector = ownerEyePos.add(rayTraceVector.multiply(distance, distance, distance));
            subEntity.setPos(newVector);
            subEntity.setDeltaMovement(newVector);
            var vec3 = new Vec3(subEntity.getX(), subEntity.getY(), subEntity.getZ());
            subEntity.xo = vec3.x;
            subEntity.yo = vec3.y;
            subEntity.zo = vec3.z;
            subEntity.xOld = vec3.x;
            subEntity.yOld = vec3.y;
            subEntity.zOld = vec3.z;
        }
    }

    /* Hit Detection */
    if (!level.isClientSide) {
        if (dealDamageActive) {
            for (Entity entity : getSubEntityCollisions()) {
                //irons_spellbooks.LOGGER.debug("ConeOfColdHit : {}", entity.getName().getString());
                onHitEntity(new EntityHitResult(entity));
            }
            dealDamageActive = false;
        }
    } else {
        spawnParticles();
    }

}

public void onEntityDamage(LivingDamageEvent.Pre event) {
  DamageSource src = event.getSource();
  if (event.getEntity() instanceof AbstractHorse horse) {
    if (horse.getPersistentData().getBoolean(ItemHorseNetheriteFire.NBT_KEY)
        && (src.is(DamageTypes.LAVA) || src.is(DamageTypes.IN_FIRE) || src.is(DamageTypes.ON_FIRE) || src.is(DamageTypes.HOT_FLOOR)
            || src.is(DamageTypes.FIREBALL) || src.is(DamageTypes.UNATTRIBUTED_FIREBALL)
            || src.is(DamageTypes.LIGHTNING_BOLT))) {
      event.setNewDamage(0);
      horse.clearFire();
      return;
    }
    if (horse.getPersistentData().getBoolean(ItemHorsePrismarineWater.NBT_KEY)
        && src.is(DamageTypes.DROWN)) {
      event.setNewDamage(0);
      return;
    }
  }
  if (event.getEntity() instanceof Player player) {
    if (src.is(DamageTypes.PLAYER_EXPLOSION)) {
      //explosion thingy
      this.damageFinder(event, player, ItemRegistry.CHARM_CREEPER.get(), 0);
    }
    if (src.is(DamageTypes.FALL) || src.is(DamageTypes.CACTUS) || src.is(DamageTypes.SWEET_BERRY_BUSH)) {
      this.damageFinder(event, player, ItemRegistry.CHARM_LONGFALL.get(), 0);
    }
    else if (src.is(DamageTypes.FLY_INTO_WALL) || src.is(DamageTypes.IN_WALL)) {
      //stone lung
      this.damageFinder(event, player, ItemRegistry.CHARM_STONE.get(), 0);
    }
    else if (src.is(DamageTypes.MAGIC) || src.is(DamageTypes.DRAGON_BREATH)) {
      this.damageFinder(event, player, ItemRegistry.CHARM_MAGICDEFENSE.get(), 0.5F);
    }
    else if (src.is(DamageTypes.STARVE)) {
      if (this.damageFinder(event, player, ItemRegistry.CHARM_STARVATION.get(), 0)) {
        player.getFoodData().eat(0, 0.2F);
      }
    }
    else if (src.is(DamageTypes.DROWN)) {
      if (this.damageFinder(event, player, ItemRegistry.CHARM_WATER.get(), 0)) {
        //and a holdover bonus
        MobEffectInstance eff = new MobEffectInstance(MobEffects.WATER_BREATHING, Const.TICKS_PER_SEC * 10, 1, false, false, false);

        player.addEffect(eff);
      }
    }
    else if (src.is(DamageTypes.LAVA) || src.is(DamageTypes.IN_FIRE) || src.is(DamageTypes.ON_FIRE)) {
      this.damageFinder(event, player, ItemRegistry.CHARM_FIRE.get(), 0);
      this.damageFinder(event, player, ItemRegistry.CHARM_ULTIMATE.get(), 0);
    }
  }
  else if (src.getEntity() instanceof Player) {
    //player DEALING damage
    Player ply = (Player) src.getEntity();
    ItemStack find = CharmUtil.getIfEnabled(ply, ItemRegistry.CHARM_VENOM.get());
    if (!find.isEmpty() && ply.level().random.nextDouble() < 0.25F) {
      int seconds = 2 + ply.level().random.nextInt(4);
      event.getEntity().addEffect(new MobEffectInstance(MobEffects.POISON, Const.TICKS_PER_SEC * seconds, 0, false, false, false));
      ItemStackUtil.damageItem(ply, find);
    }

  }
}

public void onHit(PlayerInteractEvent.LeftClickBlock event) {
  Player player = event.getEntity();
  ItemStack held = player.getItemInHand(event.getHand());
  Level world = player.getCommandSenderWorld();
  BlockState target = world.getBlockState(event.getPos());
  if (player.isCrouching()
      && target.getBlock() instanceof IBlockFacade) {
    //
    onHitFacadeHandler(event, player, held, target);
    //
  }
  if (held.getItem() instanceof ShapeCard && player.isCrouching()) {
    ShapeCard.setBlockState(held, target);
    ChatUtil.sendStatusMessage(player, target.getBlock().getDescriptionId());
  }
  if (player.isCrouching()
      && target.getBlock() instanceof IBlockFacade) {
    //
    onHitFacadeHandler(event, player, held, target);
    //
  }
  ///////////////// builders
  if (held.getItem() instanceof BuilderItem) {
    if (BuilderActionType.getTimeout(held) > 0) {
      //without a timeout, this fires every tick. so you 'hit once' and get this happening 6 times
      return;
    }
    BuilderActionType.setTimeout(held);
    event.setCanceled(true);
    if (player.isCrouching()) {
      //pick out target block
      BuilderActionType.setBlockState(held, target);
      ChatUtil.sendStatusMessage(player, target.getBlock().getDescriptionId());
      event.setCanceled(true);
      SoundUtil.playSound(player, SoundRegistry.DCOIN.get(), 0.3F, 1F);
    }
    else {
      //change size
      if (!world.isClientSide) {
        BuilderActionType.toggle(held);
      }
      SoundUtil.playSound(player, SoundRegistry.TOOL_MODE.get());
      ChatUtil.sendStatusMessage(player, ChatUtil.lang(BuilderActionType.getName(held)));
      event.setCanceled(true);
    }
  }
  if (held.getItem() instanceof AntimatterEvaporatorWandItem) {
    AntimatterEvaporatorWandItem.toggleMode(player, held);
  }
  if (held.getItem() instanceof RandomizerItem) {
    if (BuilderActionType.getTimeout(held) > 0) {
      return;
    }
    BuilderActionType.setTimeout(held);
    event.setCanceled(true);
    if (!world.isClientSide) {
      BuilderActionType.toggle(held);
    }
    SoundUtil.playSound(player, SoundRegistry.TOOL_MODE.get());
    ChatUtil.sendStatusMessage(player, ChatUtil.lang(BuilderActionType.getName(held)));
  }
}

public void tick() {
  this.syncEnergy();
  if (this.requiresRedstone() && !this.isPowered()) {
    return;
  }
  if (level.isClientSide) { //  || !(level instanceof ServerLevel)
    return;
  }
  if (timer > 0) {
    timer--;
    return;
  }
  //timer is zero so trigger
  timer = timerDelay;
  if (fakePlayer == null) {
    UUID useOwner = USE_OWNER_UUID.get() ? this.ownerId : null;
    fakePlayer = setupBeforeTrigger((ServerLevel) level, "user", useOwner);
  }
  final int repair = POWERCONF.get();
  if (repair > 0) {
    //we need to pay a cost
    if (energy.getEnergyStored() < repair) {
      //not enough cost
      return;
    }
    //i dont care if result is SUCCESS or FAIL. still drain power every time. 
    //user can turn off with redstone if they want to save power
    energy.extractEnergy(repair, false);
  }
  try {
    // Added to address the broken server side FakePlayer cooldowns we they
    // are not getting decremented causing any item with one to not function correctly.
    var cooldowns = fakePlayer.get().getCooldowns();
    TileBlockEntityCyclic.tryEquipItem(inventory, fakePlayer, 0, InteractionHand.MAIN_HAND);
    var item = fakePlayer.get().getItemInHand(InteractionHand.MAIN_HAND).getItem();
    var oldItem = item.asItem();
    if (cooldowns.isOnCooldown(item)) {
      cooldowns.removeCooldown(item);
    }
    BlockPos target = this.worldPosition.relative(this.getCurrentFacing());
    if (entities) {
      //do entities
      this.interactEntities(target);
    }
    else {
      //not entities so blocks
      if (doHitBreak) {
        TileBlockEntityCyclic.playerAttackBreakBlock(fakePlayer, level, target, InteractionHand.MAIN_HAND, this.getCurrentFacing());
      }
      else {
        TileBlockEntityCyclic.interactUseOnBlock(fakePlayer, level, target, InteractionHand.MAIN_HAND, null);
      }
    }
    boolean mainhandChanged = oldItem != userSlots.getStackInSlot(0).getItem();
    if (mainhandChanged) {
      this.depositOutputMainhand();
    }
    TileBlockEntityCyclic.syncEquippedItem(this.userSlots, fakePlayer, 0, InteractionHand.MAIN_HAND);
  }
  catch (Exception e) {
    ModCyclic.LOGGER.error("User action item error", e);
  }
  final boolean dropItemsOnGround = false;
  tryDumpFakePlayerInvo(fakePlayer, this.outputSlots, dropItemsOnGround);
}

public void serverTick() {
  //redstone phase
  if (this.requiresRedstone() && !this.isPowered()) {
    setLitProperty(false);
    return;
  }
  //i am running
  setLitProperty(true);
  if (this.level.isClientSide) {
    return;
  }

  this.syncEnergy();
  final int cost = POWERCONF.get();
  if (energy.getEnergyStored() < cost && cost > 0) {
    return;
  }
  if (timer < 0) {
    timer = 0;
  }
  RecipeHolder<CraftingRecipe> lastValidRecipe = findMatchingRecipe(null);
  if (lastValidRecipe == null) {
    //reset 
    this.timer = TIMER_FULL;
    setPreviewSlot(ItemStack.EMPTY);
  }
  else {
    //recipes not null and it matches  
    ItemStack recipeOutput = lastValidRecipe.value().getResultItem(level.registryAccess()).copy();
    setPreviewSlot(recipeOutput);
    //if we have space for the output, then go ahead
    if (hasFreeSpace(outHandler, recipeOutput)) {
      if (!checkInput(inputHandler)) { //Checks input before processing
        this.timer = TIMER_FULL;
        return;
      }
      if (--timer > 0) { //Get recipe before processing
        return;
      }
      if (doCraft(lastValidRecipe)) {
        //reset the timer
        this.timer = TIMER_FULL;
        //pay energy cost
        this.energy.extractEnergy(cost, false);
        //get the result item
        depositOutput(recipeOutput, outHandler);
        //stuff like empty buckets happen down here
        CraftingInput craftingInput = CraftingInput.of(3, 3, java.util.List.of(
      craftMatrix.getItem(0), craftMatrix.getItem(1), craftMatrix.getItem(2),
      craftMatrix.getItem(3), craftMatrix.getItem(4), craftMatrix.getItem(5),
      craftMatrix.getItem(6), craftMatrix.getItem(7), craftMatrix.getItem(8)
  ));
        NonNullList<ItemStack> rem = lastValidRecipe.value().getRemainingItems(craftingInput);
        for (int i = 0; i < rem.size(); ++i) {
          ItemStack s = rem.get(i);
          if (!s.isEmpty() && s.getItem() == craftMatrix.getItem(i).getItem()) {
            s = depositOutput(s, this.inputHandler);
          }
          //otherwise its something like bucket->empty bucket, so different item, so right side 
          depositOutput(s, this.outHandler);
        }
        this.updateComparatorOutputLevel();
      }
    }
  }
}

public static AbilityUseResult performRegular(Player attacker, ItemModularHandheld item, ItemStack itemStack, double damageMultiplier,
        int amplifier, LivingEntity target, boolean isSatiated, int comboPoints) {
    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

    int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
    if (comboLevel > 0) {
        damageMultiplier += comboLevel * comboPoints / 100d;
    }

    if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
        damageMultiplier += revengeLevel / 100d;
    }

    int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
    if (exhilarationLevel > 0) {
        int amp = Optional.ofNullable(target.getEffect(PriedPotionEffect.instance))
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1) + 1;
        if (amp > 0) {
            damageMultiplier += exhilarationLevel * amp / 100d;
        }
    }

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.2f, 0.2f);

    if (result != AbilityUseResult.fail) {
        int currentAmplifier = Optional.ofNullable(target.getEffect(PriedPotionEffect.instance))
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1);

        double comboEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityCombo);
        if (comboEfficiency > 0 && attacker.getCommandSenderWorld().getRandom().nextFloat() < (comboEfficiency * comboPoints / 100f)) {
            amplifier++;

            if (!target.getCommandSenderWorld().isClientSide) {
                RandomSource rand = target.getCommandSenderWorld().getRandom();
                ((ServerLevel) target.getCommandSenderWorld()).sendParticles(ParticleTypes.CRIT,
                        target.getX(), target.getY() + target.getBbHeight() / 2, target.getZ(), 10,
                        rand.nextGaussian() * 0.3, rand.nextGaussian() * target.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f);
            }
        }

        if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
            amplifier++;
        }

        double overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
        if (overextendLevel > 0 && isSatiated) {
            amplifier++;
        }

        target.addEffect(new MobEffectInstance(PriedPotionEffect.instance, (int) (item.getEffectEfficiency(itemStack, ItemEffect.pry) * 20),
                currentAmplifier + amplifier, false, false));

        if (!target.getCommandSenderWorld().isClientSide) {
            ParticleHelper.spawnArmorParticles(target);
        }

        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0 && currentAmplifier > -1) {
            int duration = momentumLevel * (currentAmplifier + 1);
            target.addEffect(new MobEffectInstance(StunPotionEffect.instance, duration, 0, false, false));
        }
    }

    return result;
}

public AbilityUseResult performRegular(Player attacker, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, int chargedTicks,
        boolean isSatiated, int comboPoints) {
    int armor = target.getArmorValue();

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, 1, 0.2f, 0.2f);

    if (result != AbilityUseResult.fail) {
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        boolean isPunctured = target.getEffect(PuncturedPotionEffect.instance) != null;
        boolean reversal = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge) > 0 && armor > attacker.getArmorValue();

        if (armor < 6 || isPunctured || reversal) {
            int duration = 80;

            if (overchargeBonus > 0) {
                duration += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge) * 10);
            }

            double comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
            if (comboLevel > 0) {
                duration += comboLevel * comboPoints;
            }

            double overextendEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityOverextend);
            if (overextendEfficiency > 0 && isSatiated) {
                duration += overextendEfficiency * 20;
            }

            int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationLevel > 0 && isPunctured) {
                duration += exhilarationLevel;
            }

            target.addEffect(new MobEffectInstance(BleedingPotionEffect.instance, duration, 1, false, false));
            BleedingPotionEffect.spawnParticles(target, 8);
        }

        if (!(armor < 6 || isPunctured) || reversal) {
            int amplifier = item.getEffectLevel(itemStack, ItemEffect.puncture) - 1;
            int duration = (int) (item.getEffectEfficiency(itemStack, ItemEffect.puncture) * 20);

            if (overchargeBonus > 0) {
                amplifier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge);
            }

            int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
            if (overextendLevel > 0 && isSatiated) {
                amplifier += overextendLevel;
            }

            target.addEffect(new MobEffectInstance(PuncturedPotionEffect.instance, duration, amplifier, false, false));
        }

        if (!isPunctured) {
            int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
            if (momentumLevel > 0) {
                double velocity = momentumLevel / 100d + item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum) * armor;
                velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                target.push(0, velocity, 0);
            }
        }

        target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 0.8f);
    } else {
        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.8f);
    }

    return result;
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack,
        @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
    super.perform(attacker, hand, item, itemStack, target, targetPos, hitVec, chargedTicks);

    boolean isDefensive = isDefensive(item, itemStack, hand);
    int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
    boolean overextended = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend) > 0;

    double exhaustDuration = item.getEffectEfficiency(itemStack, ItemEffect.overpower);

    if (!attacker.level().isClientSide && !isDefensive) {
        int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1);

        int newAmp = 1;

        if (overchargeBonus > 0) {
            newAmp += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));
        }

        double comboEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityCombo);
        if (comboEfficiency > 0 && attacker.getCommandSenderWorld().getRandom().nextFloat() < (comboEfficiency * ComboPoints.get(attacker) / 100f)) {
            newAmp--;

            RandomSource rand = attacker.getCommandSenderWorld().getRandom();
            ((ServerLevel) attacker.getCommandSenderWorld()).sendParticles(ParticleTypes.HAPPY_VILLAGER,
                    attacker.getX(), attacker.getY() + attacker.getBbHeight() / 2, attacker.getZ(), 10,
                    rand.nextGaussian() * 0.3, rand.nextGaussian() * attacker.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f);
        }

        if (target != null && revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
            newAmp--;
        }

        if (overextended && !attacker.getFoodData().needsFood()) {
            newAmp = -1;
        }

        if (newAmp > 0) {
            int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
            if (echoLevel > 0) {
                delayExhaustion(attacker, item, itemStack, (int) (exhaustDuration * 20), newAmp);
            } else {
                attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, (int) (exhaustDuration * 20),
                        newAmp + currentAmp, false, true));
            }
        }
    }

    attacker.causeFoodExhaustion(overextended ? 6 : 1);
    attacker.swing(hand, false);

    int cooldown = getCooldown(item, itemStack);

    if (isDefensive) {
        cooldown = (int) (cooldown * (1 + item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) / 100f));
    }

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    if (target != null && revengeLevel > 0) {
        RevengeTracker.removeEnemy(attacker, target);
    }

    attacker.getCooldowns().addCooldown(item, cooldown);
}

public void craft(Player player) {
    ItemStack targetStack = getTargetItemStack();
    ItemStack upgradedStack = targetStack;
    IModularItem item = CastOptional.cast(upgradedStack.getItem(), IModularItem.class).orElse(null);

    BlockState blockState = getBlockState();

    Map<ToolAction, Integer> availableTools = PropertyHelper.getCombinedToolLevels(player, getLevel(), getBlockPos(), blockState);

    ItemStack[] materials = getMaterials();
    ItemStack[] materialsAltered = Arrays.stream(getMaterials()).map(ItemStack::copy).toArray(ItemStack[]::new);

    if (item != null && currentSchematic != null && currentSchematic.canApplyUpgrade(player, targetStack, materialsAltered, currentSlot, availableTools)) {
        float severity = currentSchematic.getSeverity(targetStack, materialsAltered, currentSlot);
        boolean willReplace = currentSchematic.willReplace(targetStack, materialsAltered, currentSlot);

        if (willReplace) {
            TetraEnchantmentHelper.removeEnchantments(targetStack, currentSlot);
        }

        // store durability and honing factor so that it can be restored after the schematic is applied
        double durabilityFactor = upgradedStack.isDamageableItem() ? upgradedStack.getDamageValue() * 1d / upgradedStack.getMaxDamage() : 0;
        double honingFactor = Mth.clamp(item.getHoningProgress(upgradedStack) * 1d / item.getHoningLimit(upgradedStack), 0, 1);

        Map<ToolAction, Integer> tools = currentSchematic.getRequiredToolLevels(targetStack, materials);

        upgradedStack = currentSchematic.applyUpgrade(targetStack, materialsAltered, true, currentSlot, player);

        upgradedStack = applyCraftingBonusEffects(upgradedStack, currentSlot, willReplace, player, materials, materialsAltered, tools, currentSchematic, level, worldPosition, blockState, true, severity);

        for (Map.Entry<ToolAction, Integer> entry : tools.entrySet()) {
            upgradedStack = consumeCraftingToolEffects(upgradedStack, currentSlot, willReplace, entry.getKey(), entry.getValue(), player, level, worldPosition, blockState, true);
        }

        item.assemble(upgradedStack, level, severity);

        // remove or restore honing progression
        if (currentSchematic.isHoning()) {
            IModularItem.removeHoneable(upgradedStack);
        } else if (ConfigHandler.moduleProgression.get() && !IModularItem.isHoneable(upgradedStack)) {
            item.setHoningProgress(upgradedStack, (int) Math.ceil(honingFactor * item.getHoningLimit(upgradedStack)));
        }

        // restore durability damage
        // todo: hacky check if repair schematic
        if (upgradedStack.isDamageableItem() && !(currentSchematic instanceof RepairSchematic)) {
            if (durabilityFactor > 0 && willReplace && currentSlot.equals(item.getRepairSlot(upgradedStack))) {
                item.repair(upgradedStack);
            } else {
                upgradedStack.setDamageValue((int) Math.ceil(durabilityFactor * upgradedStack.getMaxDamage()));
            }
        }

        int xpCost = currentSchematic.getExperienceCost(targetStack, materials, currentSlot);
        if (!player.isCreative() && xpCost > 0) {
            player.giveExperienceLevels(-xpCost);
        }
    }

    ItemStack tempStack = upgradedStack;
    handler.ifPresent(handler -> {
        for (int i = 0; i < materialsAltered.length; i++) {
            handler.setStackInSlot(i + 1, materialsAltered[i]);
        }

        emptyMaterialSlots(player);
        handler.setStackInSlot(0, tempStack);
    });

    clearSchematic();
}

public AbilityUseResult directSlam(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
    int stunDuration = 0;
    double damageMultiplier = item.getEffectLevel(itemStack, ItemEffect.slam) * 1.5 / 100;
    float knockbackBase = (float) item.getEffectEfficiency(itemStack, ItemEffect.slam);
    float knockbackMultiplier = 1f;

    boolean isDefensive = isDefensive(item, itemStack, hand);
    int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

    if (isDefensive) {
        damageMultiplier -= 0.3;
        stunDuration = item.getEffectLevel(itemStack, ItemEffect.abilityDefensive);
    }

    if (overchargeBonus > 0) {
        double bonus = overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
        damageMultiplier += bonus;
        knockbackMultiplier += bonus;
    }

    int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
    if (momentumLevel > 0) {
        stunDuration = momentumLevel;
    }

    double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
    if (momentumEfficiency > 0) {
        knockbackMultiplier = 0.4f;
    }

    double overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
    if (overextendLevel > 0 && !attacker.getFoodData().needsFood()) {
        damageMultiplier += overextendLevel / 100d;
    }

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockbackMultiplier * knockbackBase, knockbackMultiplier / 2);

    if (result != AbilityUseResult.fail) {
        if (stunDuration > 0) {
            target.addEffect(new MobEffectInstance(StunPotionEffect.instance, stunDuration, 0, false, false));
        }

        if (momentumEfficiency > 0) {
            double velocity = momentumEfficiency;
            velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
            target.push(0, velocity, 0);
        }

        if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
            target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
        }

        double exhilarationEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
        if (exhilarationEfficiency > 0) {
            knockbackExhilaration(attacker, attacker.position(), target, target.level().getGameTime() + 200, exhilarationEfficiency);
        }

        RandomSource rand = target.getRandom();
        CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                world.sendParticles(ParticleTypes.CRIT,
                        hitVec.x, hitVec.y, hitVec.z, 10,
                        rand.nextGaussian() * 0.3, rand.nextGaussian() * target.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f));

        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.7f);
    } else {
        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.7f);
    }

    return result;
}

protected void handleAttackLogic(double distanceSquared) {
    var meleeRange = meleeRange();
    if (meleeAnimTimer < 0 && (!wantsToMelee || distanceSquared > meleeRange * meleeRange || spellCastingMob.isCasting())) {
        super.handleAttackLogic(distanceSquared);
        return;
    }
    //Handling Animation hit frames
    mob.getLookControl().setLookAt(target);
    deadKing.isMeleeing = meleeAnimTimer > 0;
    if (meleeAnimTimer > 0) {
        //We are currently attacking and are in a melee animation
        forceFaceTarget();
        meleeAnimTimer--;
        if (currentAttack.data.isHitFrame(meleeAnimTimer - 4)) {
            if (currentAttack == DeadKingBoss.AttackType.SLAM) {
                mob.playSound(SoundRegistry.DEAD_KING_SLAM.get());
            } else {
                playSwingSound();
            }
        } else if (currentAttack.data.isHitFrame(meleeAnimTimer)) {
            Vec3 lunge = target.position().subtract(mob.position()).normalize().scale(.35f);
            mob.push(lunge.x, lunge.y, lunge.z);
            if (currentAttack == DeadKingBoss.AttackType.SLAM) {
                Vec3 slamPos = mob.position().add(mob.getForward().multiply(1, 0, 1).normalize().scale(2.5f));
                Vec3 bbHalf = new Vec3(meleeRange, meleeRange, meleeRange).scale(.3);
                float damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) * 1.5f;
                mob.level.getEntitiesOfClass(LivingEntity.class, new AABB(slamPos.subtract(bbHalf), slamPos.add(bbHalf))).forEach((entity) -> {
                    if (entity.isPickable() && !DamageSources.isFriendlyFireBetween(mob, entity)) {
                        entity.hurt(mob.level().damageSources().mobAttack(mob), damage);
                        var impulse = (slamPos.subtract(entity.position()).add(0, 0.75, 0)).normalize().scale(Mth.lerp(entity.distanceToSqr(mob.position()) / (meleeRange * meleeRange), 2, .5));
                        entity.setDeltaMovement(entity.getDeltaMovement().add(impulse));
                        entity.hurtMarked = true;
                        if (entity instanceof Player player && player.isBlocking()) {
                            player.disableShield();
                        }
                    }
                });
            } else {
                if (distanceSquared <= meleeRange * meleeRange && Utils.hasLineOfSight(mob.level, mob, target, true)) {
                    boolean flag = this.mob.doHurtTarget(target);
                    target.invulnerableTime = 0;
                    if (flag) {
                        if (currentAttack.data.isSingleHit() && ((mob.getRandom().nextFloat() < .75f) || target.isBlocking())) {
                            //Attack again! combos!
                            queueCombo = randomizeNextAttack(0);
                        }
                    }
                }
            }

        }
    } else if (queueCombo != null && target != null && !target.isDeadOrDying()) {
        nextAttack = queueCombo;
        queueCombo = null;
        doMeleeAction();
    } else if (meleeAnimTimer == 0) {
        //Reset animations/attack
        nextAttack = randomizeNextAttack((float) distanceSquared);
        resetMeleeAttackInterval(distanceSquared);
        meleeAnimTimer = -1;
    } else {
        //Handling attack delay
        if (distanceSquared < meleeRange * meleeRange * 1.2 * 1.2) {
            if (hasLineOfSight && --this.meleeAttackDelay == 0) {
                doMeleeAction();
            } else if (this.meleeAttackDelay < 0) {
                resetMeleeAttackInterval(distanceSquared);
            }
        }
    }
}

private AbilityUseResult regularExecute(Player attacker, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, int chargedTicks) {
    long harmfulCount = target.getActiveEffects().stream()
            .filter(effect -> effect.getEffect().getCategory() == MobEffectCategory.HARMFUL)
            .mapToInt(MobEffectInstance::getAmplifier)
            .map(amp -> amp + 1)
            .sum();

    if (target.isOnFire()) {
        harmfulCount++;
    }

    if (target.isFreezing()) {
        harmfulCount++;
    }

    float missingHealth = Mth.clamp(1 - target.getHealth() / target.getMaxHealth(), 0, 1);
    double efficiency = item.getEffectEfficiency(itemStack, ItemEffect.execute);

    double damageMultiplier = missingHealth + harmfulCount * efficiency / 100;

    double comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
    if (comboLevel > 0) {
        damageMultiplier *= 1 + comboLevel * ComboPoints.get(attacker) / 100;
    }

    damageMultiplier += 1;

    if (canOvercharge(item, itemStack)) {
        damageMultiplier *= 1 + getOverchargeBonus(item, itemStack, chargedTicks) * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
    }

    double revengeMultiplier = getRevengeMultiplier(attacker, item, itemStack);
    if (revengeMultiplier > 0) {
        damageMultiplier *= revengeMultiplier;
    }

    int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
    if (overextendLevel > 0) {
        FoodData foodStats = attacker.getFoodData();
        float exhaustion = Math.min(40, foodStats.getFoodLevel() + foodStats.getSaturationLevel());
        damageMultiplier *= 1 + overextendLevel * exhaustion * 0.25 / 100;
        attacker.causeFoodExhaustion(exhaustion); // 4 exhaustion per food/saturation so this should drain 1/4th
    }

    int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
    if (echoLevel > 0) {
        echoExecute(attacker, item, itemStack, target);
    }

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.2f, 0.2f);

    if (result != AbilityUseResult.fail) {
        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0) {
            int duration = (int) (momentumLevel * damageMultiplier * 20);
            target.addEffect(new MobEffectInstance(StunPotionEffect.instance, duration, 0, false, false));
        }

        int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
        if (exhilarationLevel > 0 && !target.isAlive()) {
            float maxHealth = target.getMaxHealth();
            int amplifier = Math.round((1 - missingHealth) / exhilarationLevel * 100) - 1;
            int duration = (int) (Math.min(200, item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration) * maxHealth) * 20);

            if (amplifier >= 0 && duration > 0) {
                attacker.addEffect(new MobEffectInstance(SmallStrengthPotionEffect.instance, duration, amplifier, false, true));
            }
        }
    }

    return result;
}

protected void handleAttackLogic(double distanceSquared) {
    //Handling Animation hit frames
    var meleeRange = meleeRange();
    float distance = Mth.sqrt((float) distanceSquared);
    mob.getLookControl().setLookAt(target);
    if (meleeAnimTimer > 0) {
        //We are currently attacking and are in a melee animation
        forceFaceTarget();
        meleeAnimTimer--;
        if (currentAttack.data.isHitFrame(meleeAnimTimer - 4)) {
            if (currentAttack != KeeperEntity.AttackType.Lunge) {
                playSwingSound();
            }
        } else if (currentAttack.data.isHitFrame(meleeAnimTimer)) {
            if (currentAttack != KeeperEntity.AttackType.Lunge) {
                //mob.lookAt(target, 300, 300);
                Vec3 lunge = target.position().subtract(mob.position()).normalize().scale(.55f)/*.add(0, 0.2, 0)*/;
                mob.push(lunge.x, lunge.y, lunge.z);
                if (distance <= meleeRange && Utils.hasLineOfSight(mob.level, mob, target, true)) {
                    boolean flag = this.mob.doHurtTarget(target);
                    target.invulnerableTime = 0;
                    if (flag) {
                        playImpactSound();
                        if (currentAttack.data.isSingleHit() && ((mob.getRandom().nextFloat() < .75f) || target.isBlocking())) {
                            //Attack again! combos!
                            queueCombo = randomizeNextAttack(0);
                        }
                    }
                }
            } else {
                if (!hasLunged) {
                    Vec3 lunge = target.position().subtract(mob.position()).normalize().multiply(2.4, .5, 2.4).add(0, 0.15, 0);
                    mob.push(lunge.x, lunge.y, lunge.z);
                    oldLungePos = mob.position();
                    mob.getNavigation().stop();
                    hasLunged = true;
                    playSwingSound();
                }
                if (!hasHitLunge && distance <= meleeRange * .45f) {
                    if (this.mob.doHurtTarget(target)) {
                        playImpactSound();
                    }
                    Vec3 knockback = oldLungePos.subtract(target.position());
                    target.knockback(1, knockback.x, knockback.z);
                    hasHitLunge = true;
                }
            }
        }
    } else if (queueCombo != null && target != null && !target.isDeadOrDying()) {
        nextAttack = queueCombo;
        queueCombo = null;
        doMeleeAction();
    } else if (meleeAnimTimer == 0) {
        //Reset animations/attack
        nextAttack = randomizeNextAttack(distance);
        resetMeleeAttackInterval(distanceSquared);
        meleeAnimTimer = -1;
    } else {
        //Handling attack delay
        if (distance < meleeRange * (nextAttack == KeeperEntity.AttackType.Lunge ? 3 : 1)) {
            if (hasLineOfSight && --this.meleeAttackDelay == 0) {
                doMeleeAction();
            } else if (this.meleeAttackDelay < 0) {
                resetMeleeAttackInterval(distanceSquared);
            }
        } else if (--this.meleeAttackDelay < 0) {
            //Always keep the clock running, eventually he'll lunge to close distance. Otherwise he can be kited incredibly easily
            resetMeleeAttackInterval(distanceSquared);
            nextAttack = randomizeNextAttack(distance);
        }
    }
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
    boolean isDefensive = isDefensive(item, itemStack, hand);
    int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

    double damageMultiplier = item.getEffectLevel(itemStack, isDefensive ? ItemEffect.abilityDefensive : ItemEffect.overpower) / 100f;
    double efficiency = item.getEffectEfficiency(itemStack, ItemEffect.overpower);

    if (overchargeBonus > 0) {
        damageMultiplier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
    }

    int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
    if (comboLevel > 0) {
        damageMultiplier += comboLevel * ComboPoints.get(attacker) / 100d;
    }

    if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
        damageMultiplier += revengeLevel / 100d;
    }

    AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.1f, 0.1f);
    if (result != AbilityUseResult.fail) {
        int currentAmplifier = Optional.ofNullable(target.getEffect(ExhaustedPotionEffect.instance))
                .map(MobEffectInstance::getAmplifier)
                .orElse(-1);

        int amplifier = currentAmplifier + 2;

        if (isDefensive) {
            amplifier--;
        }

        if (overchargeBonus > 0) {
            amplifier += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));
        }

        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0 && currentAmplifier > -1) {
            double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
            double velocity = momentumLevel / 100d;
            velocity += momentumEfficiency * (currentAmplifier + 1);

            velocity += momentumEfficiency * Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .map(amp -> amp + 1)
                    .orElse(0);

            velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);

            if (velocity > 0) {
                target.push(0, velocity, 0);
            }
        }


        int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
        if (exhilarationLevel > 0 && !target.isAlive()) {
            ServerScheduler.schedule(0, () -> attacker.removeEffect(ExhaustedPotionEffect.instance));

        }

        target.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, (int) (efficiency * 20), amplifier, false, true));

        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 0.8f);
    } else {
        target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.8f);
    }


    item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);
    item.applyDamage(2, itemStack, attacker);
}

public void tick() {
    var radius = this.getRadius();
    var level = this.level;
    if (waveAnim++ < radius) {
        if (!level.isClientSide) {
            if (waveAnim % 2 == 0) {
                float volume = (waveAnim + 8) / 16f;
                this.playSound(SoundRegistry.EARTHQUAKE_IMPACT.get(), volume, Utils.random.nextIntBetweenInclusive(90, 110) * .01f);
            }
            var circumferenceMin = (waveAnim - 1) * 2 * 3.14f;
            var circumferenceMax = (waveAnim + 1) * 2 * 3.14f;
            int minBlocks = Mth.clamp((int) circumferenceMin, 0, 750);
            int maxBlocks = Mth.clamp((int) circumferenceMax, 0, 750);
            float anglePerBlockMin = 360f / minBlocks;
            float anglePerBlockMax = 360f / maxBlocks;
            //block trail
            for (int i = 0; i < minBlocks; i++) {
                Vec3 vec3 = new Vec3(
                        waveAnim * Mth.cos(anglePerBlockMin * i),
                        0,
                        waveAnim * Mth.sin(anglePerBlockMin * i)
                );
                BlockPos blockPos = BlockPos.containing(Utils.moveToRelativeGroundLevel(level, position().add(vec3), 4)).below();
                Utils.createTremorBlock(level, blockPos, .1f + random.nextFloat() * .2f);
            }
            //fire trail
            for (int i = 0; i < maxBlocks; i++) {
                if (random.nextFloat() < 0.25f) {
                    // reduce density of fire for better visual clarity
                    continue;
                }
                Vec3 vec3 = new Vec3(
                        (waveAnim + 1) * Mth.cos(anglePerBlockMax * i),
                        0,
                        (waveAnim + 1) * Mth.sin(anglePerBlockMax * i)
                );
                BlockPos blockPos = BlockPos.containing(Utils.moveToRelativeGroundLevel(level, position().add(vec3), 4)).above();
                if (level.getBlockState(blockPos.below()).isFaceSturdy(level, blockPos.below(), Direction.UP)) {
                    Utils.createTremorBlockWithState(level, Blocks.FIRE.defaultBlockState(), blockPos.below(), .1f + random.nextFloat() * .2f);
                }
            }
            List<LivingEntity> targets = this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(this.getInflation().x, this.getInflation().y, this.getInflation().z));
            var r1Sqr = waveAnim * waveAnim;
            var r2Sqr = (waveAnim + 1) * (waveAnim + 1);
            for (LivingEntity target : targets) {
                var distanceSqr = target.distanceToSqr(this);
                if (canHitEntity(target) && distanceSqr >= r1Sqr && distanceSqr <= r2Sqr) {
                    if (canHitTargetForGroundContext(target)) {
                        applyEffect(target);
                    }
                }
            }
        } else {
            // fire particles
            int particles = (int) ((waveAnim + 1) * 2 * 3.14f * 2.5f);
            float anglePerParticle = Mth.TWO_PI / particles;
            for (int i = 0; i < particles; i++) {
                Vec3 trig = new Vec3(
                        Mth.cos(anglePerParticle * i),
                        0,
                        Mth.sin(anglePerParticle * i)
                );
                float r = Mth.lerp(Utils.random.nextFloat(), waveAnim, waveAnim + 1);
                Vec3 pos = trig.scale(r).add(Utils.getRandomVec3(0.4)).add(this.position()).add(0, 0.5, 0);
                Vec3 motion = trig.add(Utils.getRandomVec3(0.5)).scale(0.1);
                level.addParticle(ParticleHelper.FIRE, pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
            }
        }
    } else {
        this.discard();
    }

}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
    if (!attacker.level().isClientSide) {
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
        int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
        boolean overextend = overextendLevel > 0 && !attacker.getFoodData().needsFood();
        ServerPlayer serverPlayer = (ServerPlayer) attacker;

        int cooldown = getCooldown(item, itemStack);
        double damageMultiplier = EffectHelper.getEffectLevel(itemStack, ItemEffect.reap) / 100d;
        double range = EffectHelper.getEffectEfficiency(itemStack, ItemEffect.reap);

        if (overchargeBonus > 0) {
            damageMultiplier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
            range += overchargeBonus * 0.5;
        }

        int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
        int comboPoints = ComboPoints.get(attacker);
        if (comboLevel > 0) {
            damageMultiplier += comboLevel * comboPoints / 100d;
        }

        AtomicInteger kills = new AtomicInteger();
        AtomicInteger revengeKills = new AtomicInteger();
        AtomicInteger hits = new AtomicInteger();
        Vec3 targetVec;
        if (target != null) {
            targetVec = hitVec;
        } else {
            targetVec = Vec3.directionFromRotation(attacker.getXRot(), attacker.getYRot())
                    .normalize()
                    .scale(range)
                    .add(attacker.getEyePosition(0));
        }

        AABB aoe = new AABB(targetVec, targetVec).inflate(range, 1d, range);

        hitEntities(serverPlayer, item, itemStack, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel, momentumEfficiency,
                kills, revengeKills, hits);

        applyBuff(attacker, kills.get(), hits.get(), hand, item, itemStack, chargedTicks, comboPoints, revengeKills.get());

        attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
                SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

        item.tickProgression(attacker, itemStack, 1 + kills.get());

        attacker.sweepAttack();

        attacker.causeFoodExhaustion(overextendLevel > 0 ? 6 : 1);

        double exhilarationEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
        if (exhilarationEfficiency > 0 && kills.get() > 0) {
            cooldown = (int) (cooldown * (1 - exhilarationEfficiency / 100d));
        }

        attacker.getCooldowns().addCooldown(item, cooldown);

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            echoReap(serverPlayer, hand, item, itemStack, chargedTicks, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel,
                    momentumEfficiency, comboPoints);
        }
    }
    attacker.swing(hand, false);

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    item.applyDamage(2, itemStack, attacker);
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack,
        @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
    if (attacker.onGround()) {
        float damageMultiplierOffset = 0;
        float strength = 1 + EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack) * 0.5f;
        Vec3 lookVector = attacker.getLookAngle();
        double verticalVelocityFactor = 0.8;
        float hitCooldown = 0.7f;
        float exhaustDuration = 0;
        double echoStrength = 0;

        if (canOvercharge(item, itemStack)) {
            int overcharge = getOverchargeBonus(item, itemStack, chargedTicks);
            strength += overcharge * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100f;
            damageMultiplierOffset += item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge) / 100f;
        }

        double comboEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityCombo);
        if (comboEfficiency > 0) {
            hitCooldown -= comboEfficiency * ComboPoints.get(attacker) / 100;
        }

        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0) {
            verticalVelocityFactor = 1.2;
        }

        int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
        if (overextendLevel > 0 && !attacker.getFoodData().needsFood()) {
            damageMultiplierOffset += overextendLevel / 100d;
            strength += item.getEffectEfficiency(itemStack, ItemEffect.abilityOverextend);
            verticalVelocityFactor += 0.1;
        }

        int exhilarateLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
        if (exhilarateLevel > 0) {
            damageMultiplierOffset += exhilarateLevel / 100f;
            strength += item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
            exhaustDuration += 15;
        }

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            echoStrength = item.getEffectEfficiency(itemStack, ItemEffect.abilityEcho);
        }

        if (isDefensive(item, itemStack, hand)) {
            lookVector = lookVector.multiply(-1.2, 0, -1.2).add(0, 0.4, 0);
        } else {
            activeCache.put(getIdentifier(attacker), new LungeData(itemStack, damageMultiplierOffset, hitCooldown, exhaustDuration, echoLevel, echoStrength));
        }

        // current velocity projected onto the look vector
        attacker.setDeltaMovement(lookVector.scale(attacker.getDeltaMovement().dot(lookVector) / lookVector.dot(lookVector)));

        attacker.push(
                lookVector.x * strength,
                Mth.clamp(lookVector.y * strength * verticalVelocityFactor + 0.3, 0.3, verticalVelocityFactor),
                lookVector.z * strength);
        attacker.hurtMarked = true;

        attacker.move(MoverType.SELF, new Vec3(0, 0.4, 0));

        attacker.causeFoodExhaustion(overextendLevel > 0 ? 6 : 1);
        attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack));

        attacker.level().playSound(attacker, BlockPos.containing(attacker.position().add(attacker.getDeltaMovement())), SoundEvents.UI_TOAST_IN,
                SoundSource.PLAYERS, 1, 1.3f);

    }

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }
}

public static InteractionResult attemptInteraction(Level world, BlockState blockState, BlockPos pos, Player player, InteractionHand hand,
        BlockHitResult rayTrace) {
    ItemStack heldStack = player.getItemInHand(hand);
    Collection<ToolAction> availableTools = PropertyHelper.getItemTools(heldStack);

    AABB boundingBox = blockState.getShape(world, pos, CollisionContext.of(player)).bounds();
    double hitU = 16 * getHitU(rayTrace.getDirection(), boundingBox,
            rayTrace.getLocation().x - pos.getX(),
            rayTrace.getLocation().y - pos.getY(),
            rayTrace.getLocation().z - pos.getZ());
    double hitV = 16 * getHitV(rayTrace.getDirection(), boundingBox,
            rayTrace.getLocation().x - pos.getX(),
            rayTrace.getLocation().y - pos.getY(),
            rayTrace.getLocation().z - pos.getZ());

    BlockInteraction possibleInteraction = CastOptional.cast(blockState.getBlock(), IInteractiveBlock.class)
            .map(block -> block.getPotentialInteractions(world, pos, blockState, rayTrace.getDirection(), availableTools))
            .map(Arrays::stream).orElseGet(Stream::empty)
            .filter(interaction -> interaction.isWithinBounds(hitU, hitV))
            .filter(interaction -> PropertyHelper.getItemToolLevel(heldStack, interaction.requiredTool) >= interaction.requiredLevel)
            .findFirst()
            .orElse(null);

    if (possibleInteraction != null) {
        if (InteractionHand.MAIN_HAND == hand) {
            if (player.getAttackStrengthScale(0) < 0.8) {
                if (player.getOffhandItem().isEmpty()) {
                    player.resetAttackStrengthTicker();
                    return InteractionResult.FAIL;
                }
                return InteractionResult.PASS;
            }
        } else {
            if (player.getCooldowns().isOnCooldown(heldStack.getItem())) {
                return InteractionResult.FAIL;
            }
        }

        possibleInteraction.applyOutcome(world, pos, blockState, player, hand, rayTrace.getDirection());

        if (availableTools.contains(possibleInteraction.requiredTool) && heldStack.isDamageableItem()) {
            if (heldStack.getItem() instanceof IModularItem) {
                IModularItem item = (IModularItem) heldStack.getItem();

                item.applyDamage(2, heldStack, player);
                if (possibleInteraction.applyUsageEffects) {
                    item.applyUsageEffects(player, heldStack, possibleInteraction.requiredLevel * 2);
                }
            } else {
                heldStack.hurtAndBreak(2, player, breaker -> breaker.broadcastBreakEvent(breaker.getUsedItemHand()));
            }
        }

        if (player instanceof ServerPlayer serverPlayer) {
            BlockState newState = world.getBlockState(pos);

            BlockInteractionCriterion.trigger(serverPlayer, blockState, newState, possibleInteraction.requiredTool,
                    possibleInteraction.requiredLevel);
        }

        if (InteractionHand.MAIN_HAND == hand) {
            player.resetAttackStrengthTicker();
        } else {
            int cooldown = CastOptional.cast(heldStack.getItem(), ItemModularHandheld.class)
                    .map(item -> (int) (20 * item.getCooldownBase(heldStack)))
                    .orElse(10);
            player.getCooldowns().addCooldown(heldStack.getItem(), cooldown);
        }

        if (player.level().isClientSide) {
            InteractiveBlockOverlay.markDirty();
        }

        return InteractionResult.sidedSuccess(player.level().isClientSide);
    }
    return InteractionResult.PASS;
}

    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        float distance = 12f; //todo: scale with power
        Vec3 forward = entity.getForward();
        Vec3 end = Utils.raycastForBlock(level, entity.getEyePosition(), entity.getEyePosition().add(forward.scale(distance)), ClipContext.Fluid.NONE).getLocation();
        AABB hitbox = entity.getHitbox().expandTowards(end.subtract(entity.getEyePosition())).inflate(2);
        var targetableEntities = level.getEntities(entity, hitbox, e ->
                !e.isSpectator() &&
                        (e instanceof LivingEntity || e instanceof Projectile) &&
                        e.getBoundingBox().getCenter().subtract(entity.getBoundingBox().getCenter()).normalize().dot(entity.getForward()) >= .85);
        targetableEntities.sort(Comparator.comparingDouble(e -> e.distanceToSqr(entity)));
        if (!targetableEntities.isEmpty() && targetableEntities.get(0).distanceToSqr(entity) < distance * distance) {
            var closestEntity = targetableEntities.get(0);

            float radius = 2.5f;
            AABB damageBox = AABB.ofSize(closestEntity.getBoundingBox().getCenter(), radius, radius + 1, radius).move(forward.scale(radius / 2));
            // dampen end position by taking average of it and the impact location
            end = damageBox.getCenter().add(end).scale(0.5);
            var damageEntities = level.getEntities(entity, damageBox);
            var damageSource = this.getDamageSource(entity);
            boolean projectileEffects = false;
            for (Entity targetEntity : damageEntities) {
                if (targetEntity instanceof Projectile projectile &&
                        !projectile.noPhysics &&
                        !(projectile instanceof AbstractArrow arrow && ((AbstractArrowAccessor) arrow).isInGround()) &&
                        !projectile.getType().is(ModTags.CANT_PARRY)) {
                    projectileEffects = true;
                    projectile.setOwner(entity);
                    projectile.shoot(forward.x, forward.y, forward.z, (float) projectile.getDeltaMovement().length(), 0f);
                } else if (targetEntity.isAlive() &&
                        entity.isPickable() &&
                        Utils.hasLineOfSight(level, entity.getEyePosition(), targetEntity.getBoundingBox().getCenter(), true)) {
                    if (DamageSources.applyDamage(targetEntity, getDamage(spellLevel, entity), damageSource)) {
                        MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, targetEntity.getX(), targetEntity.getY() + targetEntity.getBbHeight() * .5f, targetEntity.getZ(), 15, targetEntity.getBbWidth() * .5f, targetEntity.getBbHeight() * .5f, targetEntity.getBbWidth() * .5f, .25, false);
                        EnchantmentHelper.doPostAttackEffects((ServerLevel) level, targetEntity, damageSource);
//                        targetEntity.setDeltaMovement(targetEntity.getDeltaMovement().add(end.subtract(targetEntity.position()).scale(1 / 6f)));
                        Vec3 knockback = targetEntity.position().subtract(entity.position()).normalize().add(0, 0.5, 0).normalize();
                        knockback.scale(Utils.random.nextIntBetweenInclusive(70, 100) / 100f *
                                Utils.clampedKnockbackResistanceFactor(targetEntity, .2f, 1f) * .1f);
                        targetEntity.setDeltaMovement(targetEntity.getDeltaMovement().add(knockback));

                        targetEntity.hurtMarked = true;
                    }
                }
            }
            if (projectileEffects) {
                level.playSound(null, closestEntity.getX(), closestEntity.getY(), closestEntity.getZ(), SoundRegistry.FIRE_DAGGER_PARRY.get(), entity.getSoundSource());
                MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, closestEntity.getX(), closestEntity.getY() + closestEntity.getBbHeight() * .5f, closestEntity.getZ(), 25, 0, 0, 0, .4, false);
            }
        }
        Vec3 rayVector = end.subtract(entity.getEyePosition());
        Vec3 impulse = rayVector.scale(1 / 6f).add(0, 0.1, 0);
        entity.setDeltaMovement(entity.getDeltaMovement().scale(0.2).add(impulse));
        entity.hurtMarked = true;
        entity.addEffect(new MobEffectInstance(MobEffectRegistry.FALL_DAMAGE_IMMUNITY, 20, 0, false, false, true));

        forward = impulse.normalize(); // recalculate forward as the direction we are actually moving
        Vec3 up = new Vec3(0, 1, 0);
        if (forward.dot(up) > .999) {
            up = new Vec3(1, 0, 0);
        }
        Vec3 right = up.cross(forward);
        Vec3 particlePos = end.subtract(forward.scale(3)).add(right.scale(-0.3));
        MagicManager.spawnParticles(level,
                new EnderSlashParticleOptions(
                        (float) forward.x,
                        (float) forward.y,
                        (float) forward.z,
                        (float) right.x,
                        (float) right.y,
                        (float) right.z,
                        1f),
                particlePos.x, particlePos.y + .3, particlePos.z, 1, 0, 0, 0, 0, true);
        int trailParticles = 15;
        double speed = rayVector.length() / 12.0 * .75;
        for (int i = 0; i < trailParticles; i++) {
            Vec3 particleStart = entity.getBoundingBox().getCenter().add(Utils.getRandomVec3(1 + entity.getBbWidth()));
            Vec3 particleEnd = particleStart.add(rayVector);
            MagicManager.spawnParticles(level, new TraceParticleOptions(Utils.v3f(particleEnd), new Vector3f(1f, .333f, 1f)), particleStart.x, particleStart.y, particleStart.z, 1, 0, 0, 0, speed, false);
        }

        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

private void applyBuff(Player attacker, int kills, int hits, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, int chargedTicks,
        int comboPoints, int revengeKills) {
    int defensiveLevel = item.getEffectLevel(itemStack, ItemEffect.abilityDefensive);
    if (defensiveLevel > 0) {
        if (hand == InteractionHand.OFF_HAND) {
            if (hits > 0) {
                int duration = defensiveLevel * (1 + kills * 2);
                attacker.addEffect(new MobEffectInstance(SteeledPotionEffect.instance, duration, hits - 1, false, true));
            }
        } else if (kills > 0) {
            int duration = (int) (item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) * 20);
            attacker.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, duration, kills - 1, false, true));
        }
    }

    if (kills > 0) {
        int overchargeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge);
        if (overchargeLevel > 0) {
            double duration = 30 * 20;

            duration *= 1 + getOverchargeBonus(item, itemStack, chargedTicks) * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge);

            attacker.addEffect(new MobEffectInstance(SmallStrengthPotionEffect.instance, (int) duration, kills - 1, false, true));
        }

        int speedLevel = item.getEffectLevel(itemStack, ItemEffect.abilitySpeed);
        if (speedLevel > 0) {
            attacker.addEffect(new MobEffectInstance(MobEffects.DIG_SPEED, (int) (item.getEffectEfficiency(itemStack, ItemEffect.abilitySpeed) * 20),
                    kills - 1, false, true));
        }

        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0) {
            attacker.addEffect(new MobEffectInstance(UnwaveringPotionEffect.instance, momentumLevel * kills * 20,
                    0, false, true));
        }

        double comboEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityCombo);
        if (comboEfficiency > 0) {
            double duration = 15 * 20;

            duration += comboEfficiency * comboPoints * 20;

            attacker.addEffect(new MobEffectInstance(MobEffects.DIG_SPEED, (int) duration, kills - 1, false, true));
        }


        if (revengeKills > 0) {
            double duration = 20 * 20;
            duration += item.getEffectEfficiency(itemStack, ItemEffect.abilityRevenge) * revengeKills * 20;

            attacker.addEffect(new MobEffectInstance(SmallStrengthPotionEffect.instance, (int) duration, kills - 1, false, true));
        }

        int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
        if (exhilarationLevel > 0) {
            int currentAmplifier = Optional.ofNullable(attacker.getEffect(SmallAbsorbPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);
            int amp = Math.max(currentAmplifier, kills - 1);
            attacker.addEffect(new MobEffectInstance(SmallAbsorbPotionEffect.instance, 30 * 20, amp, false, true));
        }

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            int amp = Optional.ofNullable(attacker.getEffect(SmallStrengthPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);
            amp = Math.min(echoLevel, amp + kills);
            attacker.addEffect(new MobEffectInstance(SmallStrengthPotionEffect.instance, 30 * 20, amp, false, true));
        }
    }

    int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
    if (overextendLevel > 0) {
        if (kills > 0) {
            attacker.addEffect(new MobEffectInstance(SmallHealthPotionEffect.instance, 45 * 20, kills - 1, false, true));
        } else if (!attacker.getFoodData().needsFood()) {
            attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, 20 * 20, 4, false, true));
            attacker.causeFoodExhaustion(12);
        }
    }
}

public static void commonTick(Level level, BlockPos pos, BlockState blockState, Cursed_tombstone_Entity entity) {
    if(blockState.getBlock() instanceof Cursed_Tombstone_Block) {
        if (!blockState.getValue(Cursed_Tombstone_Block.POWERED)) {
            if(entity.summonCooldownProgress < CMCommonConfig.Blocks.CursedTombstoneCooldown * 1200){
                entity.summonCooldownProgress++;
            }else{

                level.setBlock(pos, blockState.setValue(Cursed_Tombstone_Block.POWERED, Boolean.valueOf(true)), 2);
                level.gameEvent(GameEvent.BLOCK_CHANGE, pos, GameEvent.Context.of(null, blockState));

            }
        }else{
            if (blockState.getValue(Cursed_Tombstone_Block.LIT)) {
                entity.tickCount++;
                if(entity.tickCount == 1) {
                    ScreenShake_Entity.ScreenShake(level, Vec3.atCenterOf(pos), 20, 0.05f, 0, 80);
                    //   this.level.addFreshEntity(new Flame_Strike_Entity(this.level, this.getBlockPos().getX() + 0.5F, this.getBlockPos().getY(), this.getBlockPos().getZ() + 0.5F, 0, 0, 100, 0, 2.5F, false, null));
                }
                if(entity.tickCount > 60 && entity.tickCount < 63) {
                    double d0 = pos.getX() + 0.5F;
                    double d1 = pos.getY() + 2;
                    double d2 = pos.getZ() + 0.5F;
                    float size = 3;

                    for (float i = -size; i <= size; ++i) {
                        for (float j = -size; j <= size; ++j) {
                            for (float k = -size; k <= size; ++k) {
                                double d3 = (double) j + (entity.rnd.nextDouble() - entity.rnd.nextDouble()) * 0.5D;
                                double d4 = (double) i + (entity.rnd.nextDouble() - entity.rnd.nextDouble()) * 0.5D;
                                double d5 = (double) k + (entity.rnd.nextDouble() - entity.rnd.nextDouble()) * 0.5D;
                                double d6 = (double) Mth.sqrt((float) (d3 * d3 + d4 * d4 + d5 * d5)) / 0.5 + entity.rnd.nextGaussian() * 0.05D;

                                level.addParticle(ModParticle.PHANTOM_WING_FLAME.get(), d0, d1, d2, d3 / d6, d4 / d6, d5 / d6);

                                if (i != -size && i != size && j != -size && j != size) {
                                    k += size * 2 - 1;

                                }
                            }
                        }
                    }
                }
                if(entity.tickCount > 63) {
                    Maledictus_Entity maledictus = ModEntities.MALEDICTUS.get().create(level);
                    if (level instanceof ServerLevel serverLevel) {
                        if (maledictus != null) {
                            ScreenShake_Entity.ScreenShake(level, Vec3.atCenterOf(pos), 20, 0.1f, 0, 40);
                            maledictus.setPos(pos.getX() + 0.5, pos.getY() + 2, pos.getZ() + 0.5);
                            maledictus.setTombstoneDirection(blockState.getValue(Cursed_Tombstone_Block.FACING));
                            maledictus.setHomePos(GlobalPos.of(serverLevel.dimension(), pos));
                            maledictus.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(pos), MobSpawnType.SPAWNER, null,null);
                            int MthX = Mth.floor(pos.getX());
                            int MthY = Mth.floor(pos.getY());
                            int MthZ = Mth.floor(pos.getZ());
                            for (int k2 = -1; k2 <= 1; ++k2) {
                                for (int l2 = -1; l2 <= 1; ++l2) {
                                    for (int j = 0; j <= 5; ++j) {
                                        int i3 = MthX + k2;
                                        int k = MthY + j;
                                        int l = MthZ + l2;
                                        BlockPos blockpos = new BlockPos(i3, k, l);
                                        BlockState block = level.getBlockState(blockpos);
                                        if (block != Blocks.AIR.defaultBlockState() && !block.is(ModTag.ALTAR_DESTROY_IMMUNE)) {
                                            level.destroyBlock(blockpos, false);
                                        }

                                    }
                                }
                            }
                            if (level.addFreshEntity(maledictus)) {
                                level.destroyBlock(pos, false);
                            }
                        }
                    }

                }

            }else{
                entity.tickCount = 0;
            }
        }
    }

}

private void renderLorePage(GuiGraphics guiHelper, float partialTick, int mouseX, int mouseY) {
    int x = leftPos + LORE_PAGE_X;
    int y = topPos;
    int margin = 2;
    var textColor = Style.EMPTY.withColor(0x322c2a);
    var poseStack = guiHelper.pose();
    //
    // Title
    //
    boolean spellSelected = selectedSpellIndex >= 0 && selectedSpellIndex < spellSlots.size() && spellSlots.get(selectedSpellIndex).hasSpell();
    var title = selectedSpellIndex < 0 ? Component.translatable("ui.irons_spellbooks.no_selection") : spellSelected ? spellSlots.get(selectedSpellIndex).spellSlot.getSpell().getDisplayName(Minecraft.getInstance().player) : Component.translatable("ui.irons_spellbooks.empty_slot");
    //font.drawWordWrap(title.withStyle(ChatFormatting.UNDERLINE).withStyle(textColor), titleX, titleY, LORE_PAGE_WIDTH, 0xFFFFFF);

    var titleLines = font.split(title.withStyle(ChatFormatting.UNDERLINE).withStyle(textColor), LORE_PAGE_WIDTH);
    int titleY = topPos + 10;

    for (FormattedCharSequence line : titleLines) {
        int titleWidth = font.width(line);
        int titleX = x + (LORE_PAGE_WIDTH - titleWidth) / 2;
        guiHelper.drawString(font, line, titleX, titleY, 0xFFFFFF, false);

        //show description if hovering
        if (spellSelected && isHovering(titleX, titleY, titleWidth, font.lineHeight, mouseX, mouseY)) {
            guiHelper.renderTooltip(font, TooltipsUtils.createSpellDescriptionTooltip(spellSlots.get(selectedSpellIndex).spellSlot.getSpell(), font), mouseX, mouseY);
        }

        //increment y for next line
        titleY += font.lineHeight;
    }
    var titleHeight = font.wordWrapHeight(title.withStyle(ChatFormatting.UNDERLINE).withStyle(textColor), LORE_PAGE_WIDTH);
    int descLine = /*y + titleHeight + font.lineHeight*/titleY + 4;

    if (selectedSpellIndex < 0 || selectedSpellIndex >= spellSlots.size() || !spellSlots.get(selectedSpellIndex).hasSpell()) {
        return;
    }
    //good orange color: 0xe2701b
    //okay green color: 0x30bf30
    //good mana color:0x448fff)
    //var colorLevel = Style.EMPTY.withColor(ChatFormatting.LIGHT_PURPLE);
    var colorMana = Style.EMPTY.withColor(0x0044a9);
    var colorCast = Style.EMPTY.withColor(0x115511);
    var colorCooldown = Style.EMPTY.withColor(0x115511);
    var spell = spellSlots.get(selectedSpellIndex).spellSlot.getSpell();
    var spellLevel = spellSlots.get(selectedSpellIndex).spellSlot.getLevel();
    float textScale = 1f;
    float reverseScale = 1 / textScale;

    Component school = spell.getSchoolType().getDisplayName();
    poseStack.scale(textScale, textScale, textScale);


    //
    //  School
    //
    drawTextWithShadow(font, guiHelper, school, x + (LORE_PAGE_WIDTH - font.width(school.getString())) / 2, descLine, 0xFFFFFF, 1);
    descLine += font.lineHeight * textScale;

    //
    // Level
    //
    var levelText = Component.translatable("ui.irons_spellbooks.level", spellLevel).withStyle(textColor);
    guiHelper.drawString(font, levelText, x + (LORE_PAGE_WIDTH - font.width(levelText.getString())) / 2, descLine, 0xFFFFFF, false);
    descLine += font.lineHeight * textScale * 2;

    //
    // Mana
    //
    descLine += drawStatText(font, guiHelper, x + margin, descLine, "ui.irons_spellbooks.mana_cost", textColor, Component.translatable(spell.getManaCost(spellLevel) + ""), colorMana, textScale);

    //
    // Cast Time
    //

    descLine += drawText(font, guiHelper, TooltipsUtils.getCastTimeComponent(spell.getCastType(), Utils.timeFromTicks(spell.getEffectiveCastTime(spellLevel, null), 1)), x + margin, descLine, textColor.getColor().getValue(), textScale);

    //
    // Cooldown
    //
    descLine += drawStatText(font, guiHelper, x + margin, descLine, "ui.irons_spellbooks.cooldown", textColor, Component.translatable(Utils.timeFromTicks(spell.getSpellCooldown(), 1)), colorCooldown, textScale);


    //
    //  Unique Info
    //
    for (MutableComponent component : spell.getUniqueInfo(spellLevel, null)) {
        descLine += drawText(font, guiHelper, component, x + margin, descLine, textColor.getColor().getValue(), 1);
    }


    poseStack.scale(reverseScale, reverseScale, reverseScale);
}

public void tick() {
  this.syncEnergy();
  if (level.isClientSide) {
    return;
  }
  if (this.requiresRedstone() && !this.isPowered()) {
    timer = 0;
    return;
  }
  ItemStack input = inputSlots.getStackInSlot(SLOT_INPUT);
  if (input.isEmpty() || input.is(DataTags.DISENCHANTER_IMMUNE)) {
    timer = 0;
    return;
  }
  Integer cost = POWERCONF.get();
  if (energy.getEnergyStored() < cost && (cost > 0)) {
    timer = 0;
    return;
  }
  if (FLUIDCOST.get() > 0 && tank.getFluidAmount() < FLUIDCOST.get()) {
    timer = 0;
    return;
  }
  ItemStack book = inputSlots.getStackInSlot(SLOT_BOOK);
  if (book.getItem() != Items.BOOK
      || outputSlots.getStackInSlot(0).isEmpty() == false
      || outputSlots.getStackInSlot(1).isEmpty() == false
      || input.getCount() != 1) {
    timer = 0;
    return;
  }
  //input is size 1, at least one book exists, and output IS empty
  ItemEnchantments inputEnchants = EnchantmentHelper.getEnchantmentsForCrafting(input);
  Holder<Enchantment> keyMoved = null;
  int levelMoved = 0;
  for (var entry : inputEnchants.entrySet()) {
    keyMoved = entry.getKey();
    levelMoved = entry.getIntValue();
    break;
  }
  if (keyMoved == null) {
    timer = 0;
    return;
  }
  //and input has at least one enchantment - count down the timer
  if (timer <= 0) {
    timer = TIMERCONF.get();
  }
  timer--;
  if (timer > 0) {
    return;
  }
  timer = 0;
  //success happening
  if (level.random.nextDouble() < 0.5) {
    SoundUtil.playSound(level, worldPosition, SoundEvents.ENCHANTMENT_TABLE_USE);
  } else {
    SoundUtil.playSound(level, worldPosition, SoundEvents.ANVIL_USE);
  }
  energy.extractEnergy(cost, false);
  if (FLUIDCOST.get() > 0) {
    tank.drain(FLUIDCOST.get(), IFluidHandler.FluidAction.EXECUTE);
  } else if (FLUIDCOST.get() < 0) {
    Fluid newFluid = FluidXpJuiceHolder.STILL.get();
    if (!this.getFluid().isEmpty()) {
      //if its holding a tag compatible but different fluid, just fill
      newFluid = this.getFluid().getFluid();
    }
    tank.fill(new FluidStack(newFluid, -1 * FLUIDCOST.get()), IFluidHandler.FluidAction.EXECUTE);
  }
  //build the enchanted book with just the single moved enchantment
  final Holder<Enchantment> movedKey = keyMoved;
  final int movedLvl = levelMoved;
  ItemStack eBook = new ItemStack(Items.ENCHANTED_BOOK);
  EnchantmentHelper.updateEnchantments(eBook, m -> m.set(movedKey, movedLvl));
  //replace book with enchanted
  inputSlots.extractItem(SLOT_BOOK, 1, false);
  outputSlots.insertItem(0, eBook, false);
  //strip the moved enchantment off a copy so we can see what (if anything) remains
  ItemStack stripped = input.copy();
  EnchantmentHelper.updateEnchantments(stripped, m -> m.removeIf(h -> h.equals(movedKey)));
  boolean remainingEmpty = EnchantmentHelper.getEnchantmentsForCrafting(stripped).isEmpty();
  //do i replace input with a book?
  if (input.getItem() == Items.ENCHANTED_BOOK && remainingEmpty) { // empty ench on enchbook override
    inputSlots.extractItem(SLOT_INPUT, 64, false); //delete input
    inputSlots.insertItem(SLOT_INPUT, new ItemStack(Items.BOOK), false);
  } else {
    //was a normal item, so ok to set its ench list to empty
    if (input.getItem() == Items.ENCHANTED_BOOK) { // normal enchanted book - swap in stripped copy
      inputSlots.extractItem(SLOT_INPUT, 64, false); //delete input
      inputSlots.insertItem(SLOT_INPUT, stripped, false);
    } else { // non-book set as removed from item
      EnchantmentHelper.updateEnchantments(input, m -> m.removeIf(h -> h.equals(movedKey)));
    }
  }
  //recalculate input item
  input = inputSlots.getStackInSlot(SLOT_INPUT);
  ItemEnchantments postInput = EnchantmentHelper.getEnchantmentsForCrafting(input);
  if (!input.isEmpty() && postInput.isEmpty()) {
    //hey we done, bump it over to the ALL NEW finished slot
    if (outputSlots.getStackInSlot(1).isEmpty()) {
      //only if there is space, then do it
      outputSlots.insertItem(1, input.copy(), false);
      inputSlots.extractItem(SLOT_INPUT, 64, false);
    }
    //delete input
  }
}
